INSERT INTO games VALUES (127379, 10, 'Counter-Strike', 'Play the world''s number 1 online action game. Engage in an incredibly realistic brand of terrorist warfare in this wildly popular team-based game. Ally with teammates to complete strategic missions. Take out enemy sites. Rescue hostages. Your role affects your team''s success. Your team''s success affects your role.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/10/header.jpg?t=1745368572', 1, 0, NULL);
INSERT INTO games VALUES (127382, 20, 'Team Fortress Classic', 'One of the most popular online action games of all time, Team Fortress Classic features over nine character classes -- from Medic to Spy to Demolition Man -- enlisted in a unique style of online team warfare. Each character class possesses unique weapons, items, and abilities, as teams compete online in a variety of game play modes.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/20/header.jpg?t=1745368565', 1, 0, NULL);
INSERT INTO games VALUES (127383, 30, 'Day of Defeat', 'Enlist in an intense brand of Axis vs. Allied teamplay set in the WWII European Theatre of Operations. Players assume the role of light/assault/heavy infantry, sniper or machine-gunner class, each with a unique arsenal of historical weaponry at their disposal. Missions are based on key historical operations.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/30/header.jpg?t=1745368580', 0, 0, NULL);
INSERT INTO games VALUES (127384, 40, 'Deathmatch Classic', 'Enjoy fast-paced multiplayer gaming with Deathmatch Classic (a.k.a. DMC). Valve''s tribute to the work of id software, DMC invites players to grab their rocket launchers and put their reflexes to the test in a collection of futuristic settings.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/40/header.jpg?t=1745368570', 1, 0, NULL);
INSERT INTO games VALUES (127385, 50, 'Half-Life: Opposing Force', 'Return to the Black Mesa Research Facility as one of the military specialists assigned to eliminate Gordon Freeman. Experience an entirely new episode of single player action. Meet fierce alien opponents, and experiment with new weaponry. Named ''Game of the Year'' by the Academy of Interactive Arts and Sciences.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/50/header.jpg?t=1745368539', 1, 0, NULL);
INSERT INTO games VALUES (127386, 60, 'Ricochet', 'A futuristic action game that challenges your agility as well as your aim, Ricochet features one-on-one and team matches played in a variety of futuristic battle arenas.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/60/header.jpg?t=1745368568', 1, 0, NULL);
INSERT INTO games VALUES (127387, 70, 'Half-Life', 'Named Game of the Year by over 50 publications, Valve''s debut title blends action and adventure with award-winning technology to create a frighteningly realistic world where players must think to survive. Also includes an exciting multiplayer mode that allows you to play against friends and enemies around the world.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/70/header.jpg?t=1745368462', 1, 0, NULL);
INSERT INTO games VALUES (127388, 80, 'Counter-Strike: Condition Zero', 'With its extensive Tour of Duty campaign, a near-limitless number of skirmish modes, updates and new content for Counter-Strike''s award-winning multiplayer game play, plus over 12 bonus single player missions, Counter-Strike: Condition Zero is a tremendous offering of single and multiplayer content.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/80/header.jpg?t=1745368574', 1, 0, NULL);
INSERT INTO games VALUES (127380, 100, 'Counter-Strike: Condition Zero', 'With its extensive Tour of Duty campaign, a near-limitless number of skirmish modes, updates and new content for Counter-Strike''s award-winning multiplayer game play, plus over 12 bonus single player missions, Counter-Strike: Condition Zero is a tremendous offering of single and multiplayer content.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/80/header.jpg?t=1745368574', 1, 0, NULL);
INSERT INTO games VALUES (127381, 130, 'Half-Life: Blue Shift', 'Made by Gearbox Software and originally released in 2001 as an add-on to Half-Life, Blue Shift is a return to the Black Mesa Research Facility in which you play as Barney Calhoun, the security guard sidekick who helped Gordon out of so many sticky situations.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/130/header.jpg?t=1745368541', 0, 0, NULL);
INSERT INTO games VALUES (135119, 400, 'Portal', 'Portal™ is a new single player game from Valve. Set in the mysterious Aperture Science Laboratories, Portal has been called one of the most innovative new games on the horizon and will offer gamers hours of unique gameplay.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/400/header.jpg?t=1745368554', 1, 0, NULL);
INSERT INTO games VALUES (135624, 440, 'Team Fortress 2', 'Nine distinct classes provide a broad range of tactical abilities and personalities. Constantly updated with new game modes, maps, equipment and, most importantly, hats!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/440/header.jpg?t=1745368581', 1, 1, NULL);
INSERT INTO games VALUES (139108, 570, 'Dota 2', 'Every day, millions of players worldwide enter battle as one of over a hundred Dota heroes. And no matter if it''s their 10th hour of play or 1,000th, there''s always something new to discover. With regular updates that ensure a constant evolution of gameplay, features, and heroes, Dota 2 has taken on a life of its own.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/570/header.jpg?t=1748018387', 1, 1, NULL);
INSERT INTO games VALUES (132256, 620, 'Portal 2', 'The &quot;Perpetual Testing Initiative&quot; has been expanded to allow you to design co-op puzzles for you and your friends!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/620/header.jpg?t=1745363004', 1, 0, NULL);
INSERT INTO games VALUES (127378, 630, 'Alien Swarm', 'Co-operative multiplayer game and complete code base available for free.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/630/header.jpg?t=1745368585', 0, 1, NULL);
INSERT INTO games VALUES (137670, 730, 'Counter-Strike 2', 'For over two decades, Counter-Strike has offered an elite competitive experience, one shaped by millions of players from across the globe. And now the next chapter in the CS story is about to begin. This is Counter-Strike 2.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/730/header.jpg?t=1749053861', 1, 1, NULL);
INSERT INTO games VALUES (137507, 1500, 'Darwinia', 'Darwinia blends real-time strategy, action, and puzzles with a unique gesture-based control system. Save the Darwinians, battle viruses, and restore order in a retro-inspired digital world. Winner of multiple prestigious  awards, including the Seumas McNally Grand Prize at IGF 2006.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1500/header.jpg?t=1747681440', 0, 0, NULL);
INSERT INTO games VALUES (132498, 1640, 'Disciples II: Gallean''s Return', 'Disciples II: Gallean''s Return is a compilation edition that includes the base game, Disciples II: Dark Prophecy, plus the two standalone expansions Disciples II: Guardians of the Light and Disciples II: Servants of the Dark.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1640/header.jpg?t=1740588512', 0, 0, NULL);
INSERT INTO games VALUES (131695, 2610, 'GUN™', 'When life robs Colton White of all that matters, the only thing left he can trust is his GUN. From award-winning developer, Neversoft, and accomplished screenwriter, Randall Jahnson (The Mask of Zorro, The Doors), GUN follows Colton on his quest for discovery as he seeks to exact vengeful justice on those who have wronged him.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2610/header.jpg?t=1499877030', 0, 0, NULL);
INSERT INTO games VALUES (138778, 3050, 'Xpand Rally Xtreme', 'Xpand Rally Xtreme shows the true climate and conditions of rally racing. Dangerous, technical tracks, based on the world''s hardest special stages full of moguls,jumps,grooves and tight hairpins. By winning races amass funds for faster cars and repairs.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/3050/header.jpg?t=1729249907', 0, 0, NULL);
INSERT INTO games VALUES (135351, 3330, 'Zuma Deluxe', 'Deep in the jungle lie hidden temples bursting with traps and trickery, and it''s up to you to uncover their treasures. Fire magical balls from your stone frog idol to make matches of three or more and clear the deadly chain before it reaches the golden skull.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/3330/header.jpg?t=1627918693', 0, 0, NULL);
INSERT INTO games VALUES (41, 3350, 'Bejeweled Deluxe', 'In the game, you must swap two adjacent gems to line up three or more of the same jewel type horizontally or vertically to eliminate them. Keep playing until there are no moves left or you''ve conquered the board. Bejeweled''s gameplay can be fun for both kids and adults.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/3350/header.jpg?t=1628006310', 0, 0, NULL);
INSERT INTO games VALUES (42, 3360, 'Big Money! Deluxe', 'Here''s your chance to strike it rich! Grab as much loot as you can before your pile of coins reaches the top of the window. If you move fast enough to fill the money meter, you''ll score a moneybag. Collect enough bags, and you''ll join the ranks of the rich and famous.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/3360/header.jpg?t=1584807663', 0, 0, NULL);
INSERT INTO games VALUES (43, 3380, 'Dynomite Deluxe', 'It''s prehistoric egg-blasting fun! Use your slingshot to match three or more dino eggs of the same color... and watch them explode! Can you blast all the eggs before Mama Brontosaurus tramples your game?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/3380/header.jpg?t=1737677397', 0, 0, NULL);
INSERT INTO games VALUES (44, 3390, 'Feeding Frenzy 2 Deluxe', 'The feeding frenzy begins again! Swim and swerve through underwater worlds, chow down on smaller fish, and chomp your way to ocean supremacy. But watch out: boatloads of pesky predators are looking to make lunch out of you.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/3390/header.jpg?t=1615206261', 0, 0, NULL);
INSERT INTO games VALUES (46, 3410, 'Heavy Weapon Deluxe', 'It''s shoot-''em-up arcade action at its best! Use an incredible assortment of heavy artillery to blast away enemy tanks and planes, and fight your way to victory. What are you waiting for? Pull yourself up by your bootstraps and get into the action!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/3410/header.jpg?t=1737677403', 0, 0, NULL);
INSERT INTO games VALUES (48, 3430, 'Pizza Frenzy Deluxe', 'Pizza Frenzy is a wacky action puzzler that puts you in charge of your own pizza delivery empire! Reflexes and quick thinking are required to juggle all the orders. This fast-paced game will keep your mouse clicking with rewarding action and pattern matching.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/3430/header.jpg?t=1584809547', 0, 0, NULL);
INSERT INTO games VALUES (50, 3480, 'Peggle Deluxe', 'Take your best shot with energizing arcade fun! Aim, shoot, clear the orange pegs, then sit back and cheer as 10 whimsical teachers guide you to Peggle greatness.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/3480/header.jpg?t=1682108520', 0, 0, NULL);
INSERT INTO games VALUES (26, 3600, 'Escape Rosecliff Island', 'An unexpected storm has left you shipwrecked on a mysterious and remote private island. Seek &amp; find cleverly hidden objects and solve puzzles to find a way off the island! Find over 2100 hidden objects in 25 intriguing and mysterious locations to find items that will help you escape!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/3600/header.jpg?t=1729270397', 0, 0, NULL);
INSERT INTO games VALUES (28, 3620, 'Zuma''s Revenge!', 'An irresistible force has taken our fearless frog to an island where the puzzle-action of Zuma has evolved in amazing ways… but evil spirits and tenacious tiki bosses rule the land! Survive by firing stone spheres to destroy the deadly stream of balls. Conquer over 60 levels!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/3620/header.jpg?t=1628007882', 0, 0, NULL);
INSERT INTO games VALUES (29, 3700, 'Sniper Elite', 'As World War II draws to a close, the first covert battles of the Cold War begin. Caught in the life and death struggle between Soviets and Germans in war-torn Berlin, you control the fate of a lone American OSS Sniper.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/3700/header.jpg?t=1579791723', 0, 0, NULL);
INSERT INTO games VALUES (30, 3710, 'Judge Dredd: Dredd vs. Death', 'Welcome to Mega-City One, a city of over 400 million people - every one of them a potential criminal. It is the third decade of the 22nd Century, unemployment is widespread, boredom is universal and only the Judges can prevent total anarchy. Empowered to dispense instant justice, they are Judge, Jury and Executioner all in one.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/3710/header.jpg?t=1579791442', 0, 0, NULL);
INSERT INTO games VALUES (31, 3720, 'Evil Genius', 'Everybody wants to rule the world! Achieve global power with EVIL GENIUS, the one and only complete world domination simulator. All the everyday tasks of the deliciously wicked mastermind are available to experience and master from building your ultra-secret base to developing spectacular super-weapons to carry out your nefarious master...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/3720/header.jpg?t=1721932669', 0, 0, NULL);
INSERT INTO games VALUES (32, 3730, 'Aliens versus Predator Classic 2000', 'Aliens Versus Predator Classic 2000 features the Colonial Marine, Alien and Predator Campaigns and the frenetic single-player Skirmish mode from the original title: Alien Versus Predator Gold Edition, which was released to massive acclaim in 2000.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/3730/header.jpg?t=1579791217', 0, 0, NULL);
INSERT INTO games VALUES (33, 3800, 'Advent Rising', 'A common legend pervades the galaxy-that of a powerful, highly intelligent ancient race that will one day deliver the universe. They are known as Humans. The Advent of Humanity Begins...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/3800/header.jpg?t=1614819828', 0, 0, NULL);
INSERT INTO games VALUES (34, 3810, 'BloodRayne (Legacy)', 'In the years between the World Wars, Agent BloodRayne works as a killing machine for The Brimstone Society--a top secret fraternity that hunts down and destroys supernatural threats. Starring heroine Rayne, this original action horror game unleashed the red headed dhampir on the world.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/3810/header.jpg?t=1605897948', 0, 0, NULL);
INSERT INTO games VALUES (35, 3830, 'Psychonauts', 'A Psychic Odyssey Through the Minds of Misfits, Monsters, and Madmen. This classic action/adventure platformer from acclaimed developers Double Fine Productions follows the story of a young psychic named Razputin.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/3830/header.jpg?t=1731601282', 0, 0, NULL);
INSERT INTO games VALUES (36, 3900, 'Sid Meier''s Civilization® IV', 'With over 6 million units sold and unprecedented critical acclaim from fans and press around the world, Sid Meier''s Civilization is recognized as one of the greatest PC game franchises of all-time. Now, Sid Meier and Firaxis Games will take this incredibly fun and addictive game to new heights by adding new ways to play and win, new...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/3900/header.jpg?t=1724341287', 0, 0, NULL);
INSERT INTO games VALUES (37, 3920, 'Sid Meier''s Pirates!', 'Sail the Caribbean, marauding all on the high seas or ally your ship and crew as a privateer in search of riches - the life you choose is up to you. Face dogged enemies, raid unsuspecting villages, woo fair maidens, avoid capture or dig for buried treasure. Discover what it takes to become one of the most famous pirates in history!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/3920/header.jpg?t=1568748025', 0, 0, NULL);
INSERT INTO games VALUES (38, 3980, 'CivCity: Rome', 'CivCity: Rome, an innovative city builder inspired by the world of Sid Meiers Civilization, and created by a collaboration between Firefly Studios and Firaxis Games, invites players to shift focus from building a multi-city empire and zoom-in on the great cities of the Roman Empire, culminating in Rome itself!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/3980/header.jpg?t=1569015577', 0, 0, NULL);
INSERT INTO games VALUES (39, 3990, 'Civilization IV®: Warlords', 'Sid Meier''s Civilization IV: Warlords is the first expansion pack for the award-winning game that has become an instant world-wide hit. Paying homage to some of history''s greatest military leaders, the expansion delivers six unique and interesting scenarios, giving players the chance to change the course of history with the help of their...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/3990/header.jpg?t=1573064463', 0, 0, NULL);
INSERT INTO games VALUES (131485, 4000, 'Garry''s Mod', 'Garry''s Mod is a physics sandbox. There aren''t any predefined aims or goals. We give you the tools and leave you to play.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/4000/header.jpg?t=1736937068', 1, 0, NULL);
INSERT INTO games VALUES (12, 4500, 'S.T.A.L.K.E.R.: Shadow of Chernobyl', 'S.T.A.L.K.E.R.: Shadow of Chernobyl tells a story about survival in the Zone – a very dangerous place, where you fear not only the radiation, anomalies and deadly creatures, but other S.T.A.L.K.E.R.s, who have their own goals and wishes.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/4500/header.jpg?t=1747756056', 0, 0, NULL);
INSERT INTO games VALUES (13, 4520, 'Full Spectrum Warrior', 'The U.S. Army is the most powerful ground force in the entire world. The backbone of a ground invasion is the U.S. Army Infantry, and in the midst of combat, their skills, courage, and teamwork are put to the test. While readiness continues to be the U.S. Army''s top priority, how it goes about its business is changing.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/4520/header.jpg?t=1727863949', 1, 0, NULL);
INSERT INTO games VALUES (14, 4530, 'Full Spectrum Warrior: Ten Hammers', 'Sequel to the critically acclaimed, squad-based/real-time tactical combat game, Full Spectrum Warrior: Ten Hammers delivers the most authentic and realistic infantry combat experience ever. As Squad Leader, coordinate the actions of multiple infantry squads, leading them through over 12 levels of intense action.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/4530/header.jpg?t=1727863760', 0, 0, NULL);
INSERT INTO games VALUES (15, 4560, 'Company of Heroes - Legacy Edition', 'Delivering a visceral WWII gaming experience, Company of Heroes redefines RTS by bringing the sacrifice of heroic soldiers, war-ravaged environments, and dynamic battlefields to life. This legacy version also grants access to the latest version of COH, just called &quot;Company of Heroes&quot;.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/4560/header.jpg?t=1573488196', 1, 0, NULL);
INSERT INTO games VALUES (16, 4570, 'Warhammer 40,000: Dawn of War - Anniversary Edition', 'All of Warhammer 40,000: Dawn of War in one glorious package. Play the genre-defining classic real time strategy game in all its blood-soaked glory, including four complete campaigns and nine full-fledged factions.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/4570/header.jpg?t=1726767274', 0, 0, NULL);
INSERT INTO games VALUES (17, 4580, 'Warhammer® 40,000: Dawn of War® - Dark Crusade', 'Deep under the central desert of Kronus, a vast honeycomb of skull-lined tunnels and funeral chambers house the awakening Necron menace. Eons ago, these were the boulevards and squares of a great necropolis built to house the bones of the races who had fallen to the Necrons, and ultimately were where the Necrons themselves retire to...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/4580/header.jpg?t=1726775222', 0, 0, NULL);
INSERT INTO games VALUES (18, 4700, 'Total War: MEDIEVAL II – Definitive Edition', 'Spanning the most turbulent era in Western history, your quest for territory and power takes you through Europe, Africa, the Middle East, and even onto the shores of the New World.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/4700/header.jpg?t=1724863909', 0, 0, NULL);
INSERT INTO games VALUES (19, 4720, 'Condemned: Criminal Origins', 'What twists the mind of an ordinary human into a serial killer?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/4720/header.jpg?t=1603127440', 0, 0, NULL);
INSERT INTO games VALUES (20, 4760, 'Rome: Total War™ - Collection', 'Control and conquer the greatest empire ever known to man.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/4760/header.jpg?t=1741017727', 0, 0, NULL);
INSERT INTO games VALUES (21, 4770, 'Rome: Total War™ - Alexander', 'Rome: Total War - Alexander is the second official expansion pack to Rome: Total War. An entirely new campaign map that stretches from Macedonia to Greece and into the heart of the ancient Persian Empire New campaign game that tasks players with matching the exploits of Alexander the Great as he swept across Central Asia and dominated...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/4770/header.jpg?t=1711461029', 0, 0, NULL);
INSERT INTO games VALUES (22, 4800, 'Heroes of Annihilated Empires', 'Heroes of Annihilated Empires - is a fantasy-based game from GSC Game World in the genre of RTS vs RPG for PC. 4 unique races awaits for the heroes, who want to fight in an Epic scale battles!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/4800/header.jpg?t=1685134248', 0, 0, NULL);
INSERT INTO games VALUES (23, 4850, 'Cossacks: Back to War', 'Cossacks: Back to War contains all of the gameplay features of Cossacks: European Wars and Cossacks: The Art of War, this is a complete care package for all current and future Cossacks fans. This add-on contains two new nations: Switzerland and Hungary.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/4850/header.jpg?t=1685134248', 0, 0, NULL);
INSERT INTO games VALUES (24, 4870, 'Cossacks: Art of War', 'Cossacks: The Art of War continues the history of the great battles of XVII–XVIII centuries', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/4870/header.jpg?t=1685134248', 0, 0, NULL);
INSERT INTO games VALUES (25, 4880, 'Cossacks: European Wars', 'This game is devoted to the key events of the XVII–XVIII centuries.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/4880/header.jpg?t=1685134248', 0, 0, NULL);
INSERT INTO games VALUES (1, 4890, 'Cossacks II: Battle for Europe', 'Cossacks II: Battle for Europe is a standalone add-on for &quot;Cossacks II: Napoleonic Wars&quot; presenting new nations with the possibility to wage multiplayer battles.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/4890/header.jpg?t=1685134248', 0, 0, NULL);
INSERT INTO games VALUES (3, 4920, 'Natural Selection 2', 'A fast paced multiplayer shooter that pits aliens against humans in a strategic and action-packed struggle for survival!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/4920/header.jpg?t=1747384807', 0, 0, NULL);
INSERT INTO games VALUES (127367, 6000, 'STAR WARS™ Republic Commando™', 'You are the leader of an elite squad of Republic Commandos, your mission is to infiltrate, dominate, and ultimately, annihilate the enemy. Your squad will follow your orders and your lead, working together as a team - instinctively, intelligently, instantly. You are their leader. They are your weapon.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/6000/header.jpg?t=1741729103', 0, 0, NULL);
INSERT INTO games VALUES (127368, 6010, 'Indiana Jones® and the Fate of Atlantis™', 'The Man With The Hat Is Back In His Greatest Adventure Yet! 1939 - The eve of World War II. Nazi agents are about to get their hands on a weapon more dangerous than the atom bomb. Only Indy can stop them before they unleash the deadly secret that sank Atlantis.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/6010/header.jpg?t=1571778027', 0, 0, NULL);
INSERT INTO games VALUES (127369, 6020, 'STAR WARS™ Jedi Knight - Jedi Academy™', 'Forge your weapon and follow the path of the Jedi Jedi Knight: Jedi Academy is the latest installment of the highly acclaimed Jedi Knight series. Take on the role of a new student eager to learn the ways of the Force from Jedi Master Luke Skywalker.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/6020/header.jpg?t=1741814908', 0, 0, NULL);
INSERT INTO games VALUES (127370, 6030, 'STAR WARS™ Jedi Knight II - Jedi Outcast™', 'The Legacy of Star Wars Dark Forces™ and Star Wars® Jedi Knight lives on in the intense first-person action of Jedi Outcast.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/6030/header.jpg?t=1741814017', 0, 0, NULL);
INSERT INTO games VALUES (127371, 6040, 'The Dig®', 'An asteroid the size of a small moon is on a crash course toward Earth. Once the wayward asteroid is nuked into a safe orbit, a trio conducts a routine examination of the rocky surface. What they uncover is anything but routine.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/6040/header.jpg?t=1542756570', 0, 0, NULL);
INSERT INTO games VALUES (127372, 6060, 'STAR WARS™ Battlefront II (Classic, 2005)', 'Join the rise of Darth Vader’s elite 501st Legion of Stormtroopers as you fight through an all new story-based saga where every action you take impacts the battlefront and, ultimately, the fate of the Star Wars galaxy.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/6060/header.jpg?t=1707697325', 0, 0, NULL);
INSERT INTO games VALUES (127373, 6080, 'Thrillville®: Off the Rails™', 'Thrillville™: Off the Rails lives up to its name with 20 death-defying rides! Players can build incredible coasters to leap from one track to another, launch through the air like cannonballs, blast through a burning rings of fire and more!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/6080/header.jpg?t=1542756729', 0, 0, NULL);
INSERT INTO games VALUES (127374, 6090, 'Armed and Dangerous®', 'Meet the Lionhearts. A smack-talking rag-tag band of rebels on an impossible quest. If they can make it through an army of psychotic robots and wall-smashing Goliaths, they just might save the world... if they don''t burn it down first.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/6090/header.jpg?t=1741730256', 0, 0, NULL);
INSERT INTO games VALUES (127375, 6120, 'Shank', 'Shank is the cult-classic revival of the sidescrolling beat-em-up. Play as Shank in an over-the-top grindhouse game, packed to the rim with enemies, bosses, combos, and more by the award-winning team at Klei Entertainment.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/6120/header.jpg?t=1720817954', 0, 0, NULL);
