INSERT INTO games VALUES (127303, 9460, 'Frontlines™: Fuel of War™', 'Frontlines™: Fuel of War™ is an open-world First Person Shooter set on the frontlines of tomorrow. In a world ravaged by a global energy crisis, environmental decay, and economic depression, players assume the role of an elite soldier in the Western Coalition Army on an epic crusade against the Red Star Alliance to control the last of...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/9460/header.jpg?t=1727864110', 0, 0, NULL);
INSERT INTO games VALUES (127304, 9480, 'Saints Row 2', 'Saints Row 2 brings true freedom to open-world gaming. Players can play as who they want, how they want, and with whomever they want in this sequel to the much acclaimed and tremendously successful Saints Row.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/9480/header.jpg?t=1725434161', 0, 0, NULL);
INSERT INTO games VALUES (127305, 9500, 'Gish', 'Gish isn''t your average hero. In fact, he''s not your average anything...you see, Gish is a ball of tar. A Sunday stroll with his lady friend, Brea, goes awry when a shadowy figure emerges from an open manhole and pulls Brea below ground.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/9500/header.jpg?t=1580493559', 0, 0, NULL);
INSERT INTO games VALUES (127307, 9730, 'Tycoon City: New York', 'Here''s your chance to make it big in the Big Apple... New York City, the city that never sleeps! Go for broke building your own Manhattan empire, creating and customizing over 100 types of major businesses: run a hot nightclub, oversee a media conglomerate, open a lucrative Broadway theater - the choices are endless.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/9730/header.jpg?t=1726254142', 0, 0, NULL);
INSERT INTO games VALUES (127308, 9760, 'Act of War: High Treason', 'The highly anticipated sequel to the critically acclaimed game Act of War: Direct Action picks up where the techno-thriller left off. On the eve of the U.S. Presidential elections, simultaneous terrorist attacks hit both candidates. Clues point to corrupt elements within the U.S.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/9760/header.jpg?t=1727869536', 0, 0, NULL);
INSERT INTO games VALUES (127309, 9800, 'Death to Spies', 'Smersh is Russian for &quot;Death to Spies&quot; and was the name of a set of counterintelligence agencies formed in the Soviet Army during World War II. Their mission was to secure the rear of the active Red Army by arresting traitors, deserters, spies and criminal cells.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/9800/header.jpg?t=1681208934', 0, 0, NULL);
INSERT INTO games VALUES (127285, 9880, 'Champions Online', 'Grab your cape and defend Millennium City in this comic book-style action MMORPG! Design your hero and costume from thousands of costume pieces, face super-villains like Dr. Destroyer, and create your own unique nemesis.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/9880/header.jpg?t=1749060254', 0, 1, NULL);
INSERT INTO games VALUES (127286, 9900, 'Star Trek Online', 'In Star Trek Online, the Star Trek universe appears for the first time on a truly massive scale. Players take the captain''s chair as they command their own starship and crew. Explore strange new worlds, seek out new life and new civilizations, and boldly go where no one has gone before.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/9900/header.jpg?t=1739293516', 0, 1, NULL);
INSERT INTO games VALUES (127287, 9940, 'Blade Kitten', 'In Blade Kitten, join Kit Ballard as she explores the mysterious world of Hollow Wish to hunt down rogue mechs and soft targets.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/9940/header.jpg?t=1718331964', 0, 0, NULL);
INSERT INTO games VALUES (136030, 10090, 'Call of Duty: World at War', 'Call of Duty is back, redefining war like you''ve never experienced before. Building on the Call of Duty 4®: Modern Warfare engine, Call of Duty: World at War immerses players into the most gritty and chaotic WWII combat ever experienced.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/10090/header.jpg?t=1654830025', 0, 0, NULL);
INSERT INTO games VALUES (127496, 10100, 'King''s Quest™ Collection', 'Seven classic games in one collection. Celebrate the golden age of adventure games all over again with the return of King''s Quest.The bravest knight in all of Daventry, Sir Graham, is appointed by the dying king to embark on a Quest for the Crown.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/10100/header.jpg?t=1481829482', 0, 0, NULL);
INSERT INTO games VALUES (127278, 10110, 'Space Quest™ Collection', 'Experience a blast from the past with the complete, completely twisted Space Quest Collection.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/10110/header.jpg?t=1472516706', 0, 0, NULL);
INSERT INTO games VALUES (127280, 10130, 'TimeShift™', 'Master time to become the ultimate weapon! Dr. Aiden Krone has made a Time Jump across the space-time continuum - a reckless act with frightening consequences. Now, a disturbing alternate reality has evolved within the bleak and rain-soaked Alpha District.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/10130/header.jpg?t=1531432708', 0, 0, NULL);
INSERT INTO games VALUES (127282, 10150, 'Prototype™', 'You are the Prototype, Alex Mercer, a man without memory armed with amazing shape-shifting abilities, hunting your way to the heart of the conspiracy which created you; making those responsible pay. Fast &amp; Deadly Shape-Shifting Combat: Reconfigure your body to the situation at hand.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/10150/header.jpg?t=1655760765', 0, 0, NULL);
INSERT INTO games VALUES (134923, 10180, 'Call of Duty®: Modern Warfare® 2 (2009)', 'The most-anticipated game of the year and the sequel to the best-selling first-person action game of all time, Modern Warfare 2 continues the gripping and heart-racing action as players face off against a new threat dedicated to bringing the world to the brink of collapse.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/10180/header.jpg?t=1748044299', 0, 0, NULL);
INSERT INTO games VALUES (127283, 10190, 'Call of Duty®: Modern Warfare® 2 (2009)', 'The most-anticipated game of the year and the sequel to the best-selling first-person action game of all time, Modern Warfare 2 continues the gripping and heart-racing action as players face off against a new threat dedicated to bringing the world to the brink of collapse.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/10180/header.jpg?t=1748044299', 0, 0, NULL);
INSERT INTO games VALUES (127269, 10220, 'Postal III', 'Good or Insane? The choice is yours. Following the Apocalyptic end to the Postal Dude’s week in Paradise, we follow him and his insane pitbull Champ as they emigrate to its appropriately named sister city, Catharsis.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/10220/header.jpg?t=1706900017', 0, 0, NULL);
INSERT INTO games VALUES (127273, 10270, 'Disciples III: Reincarnation', '&quot;Disciples III: Reincarnation&quot; offers a revamped and enhanced version of &quot;Disciples III: Renaissance&quot; plus the addon &quot;Resurrection&quot; with all new features, a revised battle engine and all new graphics.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/10270/header.jpg?t=1730283964', 0, 0, NULL);
INSERT INTO games VALUES (127275, 10500, 'Total War: EMPIRE – Definitive Edition', 'Command the seas, control the land, forge a new nation, and conquer the globe.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/10500/header.jpg?t=1724863702', 0, 0, NULL);
INSERT INTO games VALUES (127277, 10680, 'Aliens vs. Predator™', 'Survive, hunt and prey in the deadly jungles and swamps in distinctly new and thrilling first person gameplay.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/10680/header.jpg?t=1603127038', 0, 0, NULL);
INSERT INTO games VALUES (127251, 11040, 'Sherlock Holmes - Nemesis', 'This new Sherlock Holmes game sends us to 19th Century London where Arséne Lupin, a young French burglar with an impressive track record, has just challenged Scotland Yard and the most famous of detectives - Sherlock Holmes.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/11040/header.jpg?t=1667212865', 0, 0, NULL);
INSERT INTO games VALUES (127252, 11050, 'Dracula: Origin', 'Dracula: Origin reveals the dark origins of the Dracula curse. Step into the shoes of the famous Professor Van Helsing and experience a thrilling journey that will take you from London to Egypt, Austria and through Carpathian Europe right into the terrifying lair of the Dark Prince.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/11050/header.jpg?t=1660124866', 0, 0, NULL);
INSERT INTO games VALUES (127254, 11140, 'Sherlock Holmes: The Awakened (2008)', 'The Sherlock Holmes series returns with this updated version of The Awakened, which brings a whole new dimension to the original title developed by Frogwares. The game puts the player into an investigation of the Cthulhu Mythos - as imagined by Father of modern horror, H.P. Lovecraft.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/11140/header.jpg?t=1667208997', 0, 0, NULL);
INSERT INTO games VALUES (127255, 11150, 'Sherlock Holmes: The Silver Earring', 'Melvyn Bromsby, a rich tycoon, is about to make a statement, when suddenly a shot rings out. Sir Bromsby collapses - a mortal wound to the heart... A baffling murder, dozens of witnesses and no suspects! You, Sherlock Holmes, must use all your skills to shed light on this mysterious case.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/11150/header.jpg?t=1667211602', 0, 0, NULL);
INSERT INTO games VALUES (127256, 11180, 'Sherlock Holmes: The Mystery of the Persian Carpet', 'Scotland Yard has called Sherlock Holmes with an urgent request for help! A young painter has been found murdered and rolled up in a remarkable Persian carpet. Along with Watson, you must investigate the peculiar crime, exploring crime scene locations in search of missing clues.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/11180/header.jpg?t=1667206751', 0, 0, NULL);
INSERT INTO games VALUES (127257, 11190, 'Sherlock Holmes versus Jack the Ripper', 'Recognized as one of the best licenses in gaming and lauded by the press, Sherlock Holmes is back with an investigation that is sure to be the most horrifying of the series. The famous detective stands against the most dangerous serial killer England has ever known - Jack the Ripper.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/11190/header.jpg?t=1667209418', 0, 0, NULL);
INSERT INTO games VALUES (127258, 11200, 'Shadowgrounds Survivor', 'Surviving is only half the game. The award-winning atmosphere and gameplay mechanics of the original Shadowgrounds make a triumphant return in this spin off/sequel armed with a slick new feature set! Shadowgrounds Survivor tells the story of the last remaining humans on Jupiter''s moon Ganymede, where the alien onslaught is in full force.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/11200/header.jpg?t=1725011465', 0, 0, NULL);
INSERT INTO games VALUES (127259, 11230, 'Gumboy Tournament', 'Test your reflexes, judgment and tactics while facing up to eight other players in this follow-up to the critically acclaimed and popular arcade game Gumboy: Crazy Adventures, winner of numerous accolades including Gametunnel''s GAME OF THE YEAR 2006.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/11230/header.jpg?t=1731688812', 0, 0, NULL);
INSERT INTO games VALUES (127260, 11240, 'Space Trader: Merchant Marine', 'Space Trader is an open world trading colony sim wrapped in a shooter. Start as a Rookie and earn your way to Master using shrewd trades, back alley deals, bribes, and well-placed bullet. Buy low, sell high and don’t take no for an answer.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/11240/header.jpg?t=1725043291', 0, 0, NULL);
INSERT INTO games VALUES (127262, 11260, 'Pacific Storm Allies', 'Pacific Storm: Allies expands upon the success of the internationally acclaimed original to deliver an unforgettable mix of real-time strategy and blistering arcade combat, recreating World War II''s most heated battles.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/11260/header.jpg?t=1691593029', 0, 0, NULL);
INSERT INTO games VALUES (127263, 11280, 'Penguins Arena: Sedna''s World', 'Penguins Arena is a thrilling and innovative First Penguin Shooter with quick, hectic rounds and where the magic of reincarnation, combined with the supernatural ability to return to the game as a ghost, ensures that your character has every chance to change your tribe''s fate, even in the afterlife.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/11280/header.jpg?t=1667023239', 0, 0, NULL);
INSERT INTO games VALUES (127264, 11340, 'Larva Mortus', 'Larva Mortus is a fast-paced hack and slash top-down shooter. As an agent specializing in exorcism, you are tasked to hunt monsters of the supernatural in a dark, ominous, and randomly generated atmosphere full of undead, terrifying and demonic nightmares.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/11340/header.jpg?t=1725041872', 0, 0, NULL);
INSERT INTO games VALUES (127265, 11370, 'Nikopol: Secrets of the Immortals', 'Nikopol is a first-person dystopian point-and-click sci-fi adventure game. In 2023 France is ruled by an iron-fist religious dictatorship. A mysterious pyramid ship suddenly appears above Paris. Begin to unravel a conspiracy involving the government, your missing father, and Egyptian Gods.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/11370/header.jpg?t=1726172791', 0, 0, NULL);
INSERT INTO games VALUES (127266, 11390, 'Crash Time 2', 'Race and solve crimes as a detective in Crash Time 2. As part of the Autobahn police, you''ll escort politicians and transport valuables while burning rubber and destroying obstacles. Prove your driving and detective skills in this open-world combat racing game.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/11390/header.jpg?t=1726172821', 0, 0, NULL);
INSERT INTO games VALUES (127267, 11450, 'Overlord™', 'Prepare to be tempted, mesmerized and thrilled, become the Overlord, how corrupt you become depends on how you handle any given situation. Your actions impact the game world. With incredible power at your disposal and a team of evil minded minions to do your evil bidding, how will you resist the temptation to be incredibly despotic?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/11450/header.jpg?t=1729270455', 0, 0, NULL);
INSERT INTO games VALUES (129335, 11480, 'Soldiers: Heroes of World War II - Enhanced Edition', 'The first installment in the real-time tactics series that would become known as Men of War, now refreshed and enhanced! Take command of American, British, Soviet, or German forces and fight on the battlefields of World War II in 32 single-player missions or with others in PvP and co-op sessions.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/11480/31e7b127e3ef4c376e732df31440d0231fe2329a/header.jpg?t=1747996700', 0, 0, NULL);
INSERT INTO games VALUES (127268, 11550, 'Second Sight', 'Combining an atmospheric, psychological thriller narrative with paranormal psychic abilities, stealthy exploration and intense shooter action, Second Sight brings a new dimension to stealth action games, giving players control of a character endowed with incredible psychic abilities.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/11550/header.jpg?t=1617889764', 0, 0, NULL);
INSERT INTO games VALUES (127234, 12130, 'Manhunt', 'You awake to the sound of your own panicked breath. In Manhunt, you must run, hide and fight to survive. If you can stay alive long enough, you may find out who did this to you. This is a brutal blood sport.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/12130/header.jpg?t=1618852702', 0, 0, NULL);
INSERT INTO games VALUES (127235, 12150, 'Max Payne 2: The Fall of Max Payne', 'Max Payne 2: The Fall of Max Payne is a violent, film-noir love story. Dark, tragic and intense, the in-depth story is a thrill-ride of shocking twists and revelations. Love hurts.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/12150/header.jpg?t=1709651720', 0, 0, NULL);
INSERT INTO games VALUES (127236, 12180, 'Grand Theft Auto 2', 'Grand Theft Auto is back. The cars are faster. The streets are busier. The bad guys are nastier. The police are angrier. And now, the FBI and the Army are getting involved... Seven ruthless gangs are involved in a ruthless power struggle and it is up to you to make a name for yourself. Respect is earned, not given.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/12180/header.jpg?t=1709651730', 0, 0, NULL);
INSERT INTO games VALUES (127237, 12200, 'Bully: Scholarship Edition', 'Bully tells the story of mischievous 15-year-old Jimmy Hopkins as he goes through the hilarity and awkwardness of adolescence. Beat the jocks at dodge ball, play pranks on the preppies, save the nerds, kiss the girl and navigate the social hierarchy in the worst school around.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/12200/header.jpg?t=1741118085', 0, 0, NULL);
INSERT INTO games VALUES (127238, 12220, 'Grand Theft Auto: Episodes from Liberty City', 'Grand Theft Auto: Episodes from Liberty City includes both The Lost and Damned and The Ballad of Gay Tony together and does not require a copy of the original Grand Theft Auto IV to play.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/12220/header.jpg?t=1618853641', 0, 0, NULL);
INSERT INTO games VALUES (127240, 12320, 'Sacred Gold', 'A shadow of evil has fallen on the kingdom of Ancaria. It is a time for champions - a time to journey into the perilous world of SACRED. Battle blood-thirsty orcs &amp; lumbering ogres... Destroy undead wizards &amp; rotting mummies... Slay hellish demons &amp; legendary dragons.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/12320/header.jpg?t=1727860072', 0, 0, NULL);
INSERT INTO games VALUES (127241, 12330, 'Darkstar One', 'Darkstar One offers a fantastic amount of freedom of choice. The story-based missions gradually lead you deeper into the galaxy to new races, new technologies and ever stronger opponents. Explore a vast array of solar systems in search of hidden artifacts of ancient races, essential objects for upgrading your ship--the Darkstar One.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/12330/header.jpg?t=1740588963', 0, 0, NULL);
INSERT INTO games VALUES (127242, 12360, 'FlatOut: Ultimate Carnage Collector''s Edition', 'Ready for the aggressive, adrenaline-filled ride that leaves you breathless? FlatOut: Ultimate Carnage Collector''s Edition is all about destructive action. With carnage modes like the Deathmatch derby, Carnage Race and Head-on races are pure wreck-filled, adrenaline-pumping rides of maximum mayhem.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/12360/header.jpg?t=1721472240', 0, 0, NULL);
INSERT INTO games VALUES (127243, 12370, 'Jagged Alliance 2 Gold', 'The small country of Arulco has been taken over by a merciless dictator - and only you can loosen the iron grip! Jagged Alliance 2 Gold Pack immerses you into an elaborate role-playing universe where you will interact with more than 150 characters, recruit your own band of soldiers and create your own custom mercenary to win back Arulco...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1620/header.jpg?t=1572300558', 0, 0, NULL);
INSERT INTO games VALUES (127245, 12390, 'Exodus from the Earth', 'The Intelligence Agency has commissioned you, Francis Rixon, to find out what is happening inside the Corporation''s confines and to retrieve information about a secret mineral upon which the very existence of the human race may depend.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/12390/header.jpg?t=1748726879', 0, 0, NULL);
INSERT INTO games VALUES (127215, 12470, 'Port Royale 2', 'The Caribbean in the 17th Century - Trade with over 60 towns, create your own production facilities, expand your trading empire and influence the development of the New World. As pirates and military fleets threaten your trade convoys, you''ll need escort ships.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/12470/header.jpg?t=1740586280', 0, 0, NULL);
INSERT INTO games VALUES (127217, 12500, 'PuzzleQuest: Challenge of the Warlords', 'PuzzleQuest: Challenge of the Warlords delivers, for the first time ever, classic puzzle-game action backed with an epic story of good vs. evil. Challenge your match 3 skills as you battle against computer opponents to save the Kingdom of Etheria from the evil Lord Bane.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/12500/header.jpg?t=1478043255', 0, 0, NULL);
INSERT INTO games VALUES (127218, 12510, 'Prison Tycoon 3™: Lockdown', 'Crack that Whip! Take reigns of a privately run prison. You are responsible for the care, custody, and control of individuals who have been arrested. Begin with a low security prison and build it up to a SuperMax. From construction to daily operations, you must protect society while turning a profit. It''s time for lockdown.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/12510/header.jpg?t=1591334569', 0, 0, NULL);
INSERT INTO games VALUES (127219, 12520, '18 Wheels of Steel: American Long Haul', 'Your American Dream Starts Behind the Wheel of Your Own Big Rig! North America''s open roads await! You ain''t working for the Man any more! You''re the owner of your own trucking business and you call the shots. Build your empire one rig at a time to dominate the roadways and outbid the competition. Can you handle the pressure?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/12520/header.jpg?t=1591334616', 0, 0, NULL);
INSERT INTO games VALUES (127227, 12640, 'Drakensang', 'Drakensang is a third-person party-based RPG based on the pen &amp; paper role-play rules of The Dark Eye. Drakensang is the first PC game for over 10 years to be based on Germany''s most successful and popular role-play system. Drakensang builds on the pen &amp; paper rules as applied in version 4.0.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/12640/header.jpg?t=1447351678', 0, 0, NULL);
INSERT INTO games VALUES (127229, 12690, 'Hunting Unlimited 2010', 'Get the Shot. Get the Game. Experience fast-paced hunting action in pursuit of the biggest trophy bucks throughout North America, Canada and Now the Bavarian Forest! Wilderness Madness! Free Hunt Mode drops you right in the action with game a plenty, or for exacting hunting adventures try Challenge Mode. Calling All Predators.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/12690/header.jpg?t=1580944276', 0, 0, NULL);
INSERT INTO games VALUES (127230, 12710, 'Overlord™: Raising Hell', 'How evil can you get? Discover how corruptible you are in Overlord, the twisted fantasy action adventure where you can be evil (or really evil). In the game''s seriously warped fantasy world, players will become the Overlord and get first-hand experience of how absolute power corrupts absolutely.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/12710/header.jpg?t=1729270521', 0, 0, NULL);
INSERT INTO games VALUES (132785, 12810, 'Overlord II', 'Overlord II, sequel to the critically acclaimed cult hit, sees the return of the chaotic Minions and their new Dark Master. Bigger, badder and more beautifully destructive, Overlord 2 has a Glorious Empire to smash, a massive Netherworld to revive, Minion mounts to mobilize, a trio of mistresses to woo, War Machines to crush opposition...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/12810/header.jpg?t=1656372034', 0, 0, NULL);
INSERT INTO games VALUES (127231, 12900, 'AudioSurf', 'Ride your music. Audiosurf is a music-adapting puzzle racer where you use your own music to create your own experience. The shape, the speed, and the mood of each ride is determined by the song you choose.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/12900/header.jpg?t=1568404797', 0, 0, NULL);
INSERT INTO games VALUES (127189, 13500, 'Prince of Persia: Warrior Within™', 'Enter the dark underworld of Prince of Persia Warrior Within, the sword-slashing sequel to the critically acclaimed Prince of Persia: The Sands of Time™. Hunted by Dahaka, an immortal incarnation of Fate seeking divine retribution, the Prince embarks upon a path of both carnage and mystery to defy his preordained death.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/13500/header.jpg?t=1720535324', 0, 0, NULL);
INSERT INTO games VALUES (127190, 13520, 'Far Cry®', 'A tropical paradise seethes with hidden evil in Far Cry®, a cunningly detailed action shooter that pushes the boundaries of combat to shocking new levels. Freelance mariner Jack Carver is cursing the day he ever came to this island.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/13520/header.jpg?t=1602602361', 0, 0, NULL);
INSERT INTO games VALUES (131692, 13530, 'Prince of Persia: The Two Thrones™', 'The Prince of Persia, a seasoned warrior, returns from the Island of Time to Babylon with his love, Kaileena. Instead of the peace that he longs for, he finds his homeland ravaged by war and the kingdom turned against him.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/13530/header.jpg?t=1720535330', 0, 0, NULL);
INSERT INTO games VALUES (127191, 13540, 'Tom Clancy''s Rainbow Six® Vegas', 'Tom Clancy''s Rainbow Six makes its next-generation hardware debut in the most dramatic installment of the renowned first-person shooter franchise to date. Rainbow operatives take to the chaotic streets of Las Vegas as an escalating terrorist siege in ''Sin City'' threatens to take world terrorism to new, uncontrollable heights.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/13540/header.jpg?t=1692730276', 0, 0, NULL);
INSERT INTO games VALUES (127192, 13560, 'Tom Clancy''s Splinter Cell®', 'Infiltrate terrorists'' positions, acquire critical intelligence by any means necessary, execute with extreme prejudice, and exit without a trace! You are Sam Fisher, a highly trained secret operative of the NSA''s secret arm: Third Echelon.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/13560/header.jpg?t=1680011054', 0, 0, NULL);
INSERT INTO games VALUES (127193, 13570, 'Tom Clancy''s Splinter Cell Chaos Theory®', 'The year is 2008. Citywide blackouts ... stock exchange sabotage ... electronic hijacking of national defense systems ... this is information warfare. To prevent these attacks, operatives must infiltrate deep into hostile territory and aggressively collect critical intelligence, closer than ever to enemy soldiers.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/13570/header.jpg?t=1734363533', 0, 0, NULL);
INSERT INTO games VALUES (127194, 13580, 'Tom Clancy''s Splinter Cell Double Agent®', 'The best-selling Tom Clancy''s Splinter Cell® saga takes on an entirely new direction. In the highly anticipated sequel to the 2005 game of the year, Tom Clancy''s Splinter Cell Double Agent™, play as a double agent spy for the first time ever.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/13580/header.jpg?t=1680014047', 0, 0, NULL);
INSERT INTO games VALUES (127195, 13600, 'Prince of Persia®: The Sands of Time', 'Amidst the scorched sands of ancient Persia, there is a legend spun in an ancient tongue. It speaks of a time borne by blood and ruled by deceit. Drawn to the dark powers of a magic dagger, a young Prince is led to unleash a deadly evil upon a beautiful kingdom.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/13600/header.jpg?t=1720535333', 0, 0, NULL);
INSERT INTO games VALUES (127198, 15000, 'Tom Clancy''s Rainbow Six Lockdown™', 'Engineered specifically for the PC by Red Storm Entertainment, Rainbow Six returns to deliver the tensest close-quarters battles ever experienced online. In this episode, Rainbow faces independent terrorist threats, tied together by one common element - the Legion virus.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/15000/header.jpg?t=1692730248', 0, 0, NULL);
INSERT INTO games VALUES (136867, 15080, 'Rayman Raving Rabbids™', 'Hordes of crazed out-of control bunnies have invaded, enslaving Rayman and forcing him to participate in ''gladiator'' style trials. Help Rayman win his freedom back by entertaining and outwitting these fury foes. Use the most hilarious fighting moves imaginable.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/15080/header.jpg?t=1624892708', 0, 0, NULL);
INSERT INTO games VALUES (127199, 15100, 'Assassin''s Creed™: Director''s Cut Edition', 'Assassin''s Creed™ is the next-gen game developed by Ubisoft Montreal that redefines the action genre. While other games claim to be next-gen with impressive graphics and physics, Assassin''s Creed merges technology, game design, theme and emotions into a world where you instigate chaos and become a vulnerable, yet powerful, agent of...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/15100/header.jpg?t=1602600542', 0, 0, NULL);
INSERT INTO games VALUES (127200, 15120, 'Tom Clancy''s Rainbow Six® Vegas 2', 'Tom Clancy''s Rainbow Six® Vegas 2 - the sequel to the award-winning next-generation first-person shooter - returns to Sin City. Tom Clancy''s Rainbow Six Vegas 2 is your last chance to rescue America''s sexiest city from an escalating terrorist siege that will force you into heart-pounding action from beginning to end.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/15120/header.jpg?t=1692730299', 0, 0, NULL);
INSERT INTO games VALUES (127201, 15130, 'Beyond Good and Evil™', 'Play as Jade, a young investigative reporter, and expose a terrible government conspiracy. It is up to you and your loyal pig friend Pey''j to save your planet and its inhabitants.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/15130/header.jpg?t=1718743204', 0, 0, NULL);
INSERT INTO games VALUES (127203, 15170, 'Heroes of Might & Magic V', 'Witness the amazing evolution of the genre-defining strategy game as it becomes a next-generation phenomenon, melding classic deep fantasy with next-generation visuals and gameplay. In the renowned Might &amp; Magic universe, demon swarms spread chaos over the land in a relentless assault.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/15170/header.jpg?t=1692823544', 0, 0, NULL);
INSERT INTO games VALUES (136011, 15190, 'Brothers in Arms: Road to Hill 30™', 'Based on a true story. Set during the famous airdrop before the invasion at Normandy, where Sgt. Matt Baker and his squad of 101st Airborne Paratroopers were scattered over the French countryside.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/15190/header.jpg?t=1544534380', 0, 0, NULL);
INSERT INTO games VALUES (127204, 15200, 'Silent Hunter®: Wolves of the Pacific', 'Hunt, hide and kill as you take command of U.S. submarines and crews and navigate the treacherous waters of the Pacific during WWII. Silent Hunter, the industry-leading naval warfare simulation franchise for over a decade, returns to its roots with next-generation graphical realism, immersive gameplay, innovative crew evolution and more...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/15200/header.jpg?t=1680013334', 0, 0, NULL);
INSERT INTO games VALUES (127205, 15210, 'Silent Hunter® III', 'The king of submarine simulations returns with an all-new 3D engine, new crew command features, and more realistic WWII naval action than ever before. The movie-like graphics and simple, tension-filled gameplay make this the perfect game for the realism fanatic and the casual gamer.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/15210/header.jpg?t=1680013272', 0, 0, NULL);
INSERT INTO games VALUES (127206, 15240, 'Silent Hunter®: Wolves of the Pacific U-Boat Missions', 'Experience the thrill of the hunt! Prowl the waters as the captain of a German submarine in a never-before-seen theatre of operations  the Indian Ocean. Take part in the war against British supply lines off the coast of North Africa and support the Japanese war against the U.S. Navy.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/15240/header.jpg?t=1475239467', 0, 0, NULL);
INSERT INTO games VALUES (127207, 15270, 'Cold Fear™', 'In a ferocious Arctic storm, distress signals are sent from a mysterious Russian whaler. As leading Coast Guard veteran Tom Hansen, you board to investigate  and discover unthinkable horrors lurking beneath the ship''s bloodstained decks.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/15270/header.jpg?t=1565719542', 0, 0, NULL);
INSERT INTO games VALUES (127209, 15300, 'Tom Clancy''s Ghost Recon®', 'Eastern Europe, 2008. War has broken out on the borders of Russia and the fate of the world hangs in the balance. That''s when the call goes out for the Ghostsan elite handful of specially trained Green Berets, armed with the latest technology and trained to use the deadliest weapons.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/15300/header.jpg?t=1692818486', 0, 0, NULL);
INSERT INTO games VALUES (127210, 15320, 'IL-2 Sturmovik: 1946', 'Il-2 1946 includes all of the original IL-2 series content: IL-2 Sturmovik™: Forgotten Battles, Ace Expansion Pack, Pacific Fighters™ and alternate histry campaigns of year 1946. What was years ago began as a one-aircraft study sim is now an astonishing anthology, with a whopping 229 flyable aircraft and over 300 aircraft total!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/15320/header.jpg?t=1721725925', 0, 0, NULL);
INSERT INTO games VALUES (127211, 15370, 'Heroes of Might & Magic V: Tribes of the East', 'For the first time, play as the Orc faction and recruit heroes, build armies and manage cities as you explore and conquer legendary lands. Use tactics, skills and magic to outsmart fantasy armies while developing your heroes and unveiling the dark plot that threatens to tear the world of Ashan apart.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/15370/header.jpg?t=1692823670', 0, 0, NULL);
INSERT INTO games VALUES (127212, 15380, 'Heroes of Might & Magic V: Hammers of Fate', 'Take part in a thrilling new adventure in the world of Ashan with the Hammers of Fate expansion. Discover uncharted territories and experience new ways of playing Heroes of Might & Magic V. Introducing a brand-new Dwarves faction, made up of heroic warriors and rune magic adepts who stalk the deepest mountains and most hostile regions of...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/15380/header.jpg?t=1721932679', 0, 0, NULL);
INSERT INTO games VALUES (127213, 15390, 'Brothers in Arms: Hell''s Highway™', 'Brothers in Arms Hell''s Highway brings the critically acclaimed squad-based WWII shooter into the next generation of gaming with amazing graphics and sound, new cutting-edge gameplay features and a totally redesigned online component.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/15390/header.jpg?t=1544535852', 0, 0, NULL);
INSERT INTO games VALUES (127214, 15400, 'Harvest: Massive Encounter', 'Harvest: Massive Encounter is an award-winning real-time strategy game with battles of epic proportions and a unique style of resource management and exploration. Build power plants, mineral harvesters and defense towers and make sure they have sufficient energy to fend off endless hordes of evil aliens.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/15400/header.jpg?t=1447351635', 0, 0, NULL);
INSERT INTO games VALUES (127171, 15500, 'The Wonderful End of the World', 'You can''t save the whole world. It''s going to be eaten by a mythological demon with the head of a fish. But as a puppet that absorbs all it touches, you can try to rescue as much of Earth''s greatness as you can before the end arrives. In the beginning, you roam the Earth, capable of absorbing only the tiniest of objects.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/15500/header.jpg?t=1570193610', 0, 0, NULL);
INSERT INTO games VALUES (127172, 15520, 'AaAaAA!!! - A Reckless Disregard for Gravity', 'BASE jump through a floating city, creating your own stunts to delight your fans. Use quick reflexes to negotiate the intricate tangle of girders that make up the floating city. Flip protesters off for points!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/15520/header.jpg?t=1570193105', 0, 0, NULL);
INSERT INTO games VALUES (127173, 15560, 'AaaaaAAaaaAAAaaAAAAaAAAAA!!! for the Awesome', '82 remastered levels from the original and 43 brand new ones that are twice as fast!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/15560/header.jpg?t=1581730007', 0, 0, NULL);
INSERT INTO games VALUES (127174, 15620, 'Warhammer 40,000: Dawn of War II - Anniversary Edition', 'All of Warhammer 40,000: Dawn of War II in one package. Play the award-winning real-time strategy game in all its glory, including three full campaigns, six multiplayer factions, and a full co-op Last Stand mode with eight unique heroes.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/15620/header.jpg?t=1749205127', 0, 0, NULL);
INSERT INTO games VALUES (127175, 15700, 'Oddworld: Abe''s Oddysee®', 'Selected by the fickle finger of fate, Abe™, floor-waxer first class for RuptureFarms, was catapulted into a life of adventure when he overheard plans by his boss, Molluck the Glukkon™, to turn Abe and his fellow Mudokons into Tasty Treats as part of a last-ditch effort to rescue Molluck''s failing meat-packing empire.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/15700/header.jpg?t=1728644292', 0, 0, NULL);
INSERT INTO games VALUES (127176, 15710, 'Oddworld: Abe''s Exoddus®', 'Abe''s peaceful retirement was shattered when visited by a vision from the Mudokon Spirit Guides. Abe™ learned the Magog Cartel was mining Necrum, the sacred Mudokon city of the dead, to collect bones to make super-addictive SoulStorm Brew.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/15710/header.jpg?t=1728644414', 0, 0, NULL);
INSERT INTO games VALUES (127177, 15740, 'Oddworld: Munch''s Oddysee', 'New port for 2016! 60 FPS, higher res textures, higher poly models, improved audio, numerous fixes and improvements, and trading cards, badges, emotes and backgrounds!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/15740/header.jpg?t=1728644460', 0, 0, NULL);
INSERT INTO games VALUES (127178, 15750, 'Oddworld: Stranger''s Wrath HD', 'You''re the Stranger, a mysterious bounty hunter on a mission to bag the ultimate prize. And you need that money like no one else because there is something very wrong with your health and the only way to fix it is a very costly operation.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/15750/header.jpg?t=1728644503', 0, 0, NULL);
INSERT INTO games VALUES (127156, 16100, 'Virtual Villagers: A New Home', 'Care for and nurture a tribe of little people by teaching them the basics of survival. They need to become farmers, builders, scientists, parents and make decisions about unpredictable ''island events''! Guide their day-to-day lives and help them explore and restore their new home.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/16100/header.jpg?t=1447351300', 0, 0, NULL);
INSERT INTO games VALUES (127158, 16120, 'Plant Tycoon', 'Plant Tycoon is a gardening sim game where you nurture plants and experiment with increasingly rare and valuable species. The object is to breed and cross breed plants until you find the 6 Magic Plants of Isola and solve the genetic puzzle. You start with a couple of dollars, a handful of seeds, some soil and water.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/16120/header.jpg?t=1447351299', 0, 0, NULL);
INSERT INTO games VALUES (127160, 16180, 'Virtual Villagers - The Secret City', 'Embark on a journey with a group of villagers in search of a new part of the island to populate. Land on the hidden shores of the northern side of Isola and explore what was once a secret city. Find new sources of food to nourish your villagers and help them rebuild the remains of this mysterious city. Who lived here before?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/16180/header.jpg?t=1447351335', 0, 0, NULL);
INSERT INTO games VALUES (127162, 16300, 'Everyday Shooter', 'Everyday Shooter is an album of games exploring the expressive power of abstract shooters. Dissolute sounds of destruction are replaced with guitar riffs harmonizing over an all-guitar soundtrack, while modulating shapes celebrate the flowing beauty of geometry.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/16300/header.jpg?t=1447351312', 0, 0, NULL);
INSERT INTO games VALUES (127163, 16450, 'F.E.A.R. 2: Project Origin', 'Assume the role of Special Forces Sgt. Becket as your routine mission quickly turns into a fight for survival against the wrath of Alma Wade. As Alma''s terrifying power surges out of control, your squad is forced to battle through an apocalyptic landscape in search of clues for how to destroy her!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/16450/header.jpg?t=1745614462', 0, 0, NULL);
INSERT INTO games VALUES (127165, 16600, 'Trials 2: Second Edition', 'RedLynx Trials 2 Second Edition is a spectacular motorcycle game featuring stunning graphics and addictive gameplay! 4 game types (race, flip, wheelie, dynamic)Race: Race against other players to compete levels as fast as possibleFlip: Try to make as many backflips or frontflips with your bikeWheelie: Drive on your backwheel for longest...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/16600/header.jpg?t=1447351307', 0, 0, NULL);
INSERT INTO games VALUES (127167, 16710, 'Insecticide Part 1', 'Enter the fast shooting world of INSECTICIDE as hot shot rookie Detective Chrys Liszt and help solve a crime of epic proportions. Lead your team on a bug hunt, collecting clues and solving puzzles. Use old-fashioned street smarts, unique insect abilities and an arsenal of ingenious bug weapons to confront your suspects.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/16710/header.jpg?t=1447351378', 0, 0, NULL);
INSERT INTO games VALUES (127168, 16720, 'Velvet Assassin', 'Inspired by the fascinating story and unbreakable spirit of British secret agent Violette Szabo, players take control of Violette Summer, a beautiful World War II spy deep behind enemy lines with no support or official backing from the British Government.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/16720/header.jpg?t=1447351446', 0, 0, NULL);
INSERT INTO games VALUES (127169, 16730, 'Legendary', 'All creatures of ancient myth, legend and lore are real  they''ve just been sealed away for thousands of years inside Pandora''s Box, waiting... When a thief named Deckard is hired to steal an ancient artifact, he unwittingly triggers a war between man and myth.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/16730/header.jpg?t=1447351498', 0, 0, NULL);
INSERT INTO games VALUES (127170, 16810, 'Sid Meier''s Civilization IV: Colonization', 'Sid Meier''s Civilization IV: Colonization is the third offering in the award winning Civilization IV series. A re-imagining of the classic Colonization game Sid Meier created in 1994, Sid Meier''s Civilization IV: Colonization is a total conversion of the Civilization IV engine into a game experience in which players will lead a European...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/16810/header.jpg?t=1573064277', 0, 0, NULL);
INSERT INTO games VALUES (139950, 16900, 'GROUND BRANCH', 'From one of the developers behind the original Rainbow Six® and Ghost Recon® games, comes a thinking-man''s first-person shooter featuring in-depth character and weapon customization. Take your time. Think ahead. Get the job done.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/16900/header.jpg?t=1747049838', 0, 0, NULL);
INSERT INTO games VALUES (127140, 17020, 'Global Agenda: Free Agent', '2155. From the ashes of the devastating Third Great War rose the Commonwealth, an oppressive world government determined to control the entire planet. The few remaining independent factions retaliate the only way they can, with elite teams of special operatives trained in advanced warfare tactics and equipped with high-tech weaponry.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/17020/header.jpg?t=1645124145', 0, 1, NULL);
INSERT INTO games VALUES (127142, 17100, 'Children of the Nile: Enhanced Edition', 'Children of the Nile&trade; is a unique gem of a city-building game, unparalleled in both grandeur and attention to detail.As Pharaoh you will guide your people through thousands of years of history: from simple hunter-gatherers to the creation of an immortal civilization.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/17100/header.jpg?t=1447351375', 0, 0, NULL);
INSERT INTO games VALUES (127143, 17120, 'Children of the Nile: Alexandria', 'Children of the Nile: Alexandria is an addition to the base Children of the Nile game, adding a new mini-campaign focused on the rise of the city of Alexandria. Using the unique city-building dynamics of Children of the Nile, you will carve out a new dynasty to rule all of Egypt, and build the greatest city of the ancient world!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/17120/header.jpg?t=1447351440', 0, 0, NULL);
INSERT INTO games VALUES (127144, 17140, 'Hinterland', 'June 11, 2009 - Update Two new playable Orc classes: Lord (Warrior) or Shaman. Expanded gameplay: Orcs consume twice as much food, learn martial skills faster, manufacture items slower, and the Shaman uses totems to summon creatures. Several new items regardless of character class.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/17140/header.jpg?t=1447351490', 0, 0, NULL);
INSERT INTO games VALUES (127146, 17330, 'Crysis Warhead®', 'Pulse-racing new installment from 2007''s PC Game of the Year*: Play as Sergeant Sykes and experience a whole new side of the battle. A standard combat mission behind enemy lines becomes critical when you discover your enemies have captured something of vital importance to the ensuing war.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/17330/header.jpg?t=1734377275', 0, 0, NULL);
INSERT INTO games VALUES (127148, 17390, 'SPORE™', 'Be the architect of your own universe with Spore, an exciting single-player adventure. From Single Cell to Galactic God, evolve your creature in a universe of your own creations.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/17390/header.jpg?t=1642702281', 0, 0, NULL);
INSERT INTO games VALUES (127149, 17410, 'Mirror''s Edge™', 'In a city where information is heavily monitored, couriers called Runners transport sensitive data. In this seemingly utopian paradise, a crime has been committed, &amp; you are being hunted. You are a Runner called Faith and this innovative first-person action-adventure is your story.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/17410/header.jpg?t=1738878228', 0, 0, NULL);
INSERT INTO games VALUES (127150, 17440, 'SPORE™ Creepy & Cute Parts Pack', 'Add horror and humor to your universe. Make grotesque beasts or cuddly critters, then watch them do the robot, zombie walk, break dance and more! Includes over 100 new items. 60 New parts 48 New paint options 24 New animations', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/17440/header.jpg?t=1615390501', 0, 0, NULL);
INSERT INTO games VALUES (127151, 17460, 'Mass Effect (2007)', 'As Commander Shepard, you lead an elite squad on a heroic, action-packed adventure throughout the galaxy.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/17460/header.jpg?t=1684225163', 0, 0, NULL);
INSERT INTO games VALUES (127152, 17470, 'Dead Space (2008)', 'You are Isaac Clarke, an engineer on the spacecraft USG Ishimura. You''re not a warrior. You''re not a soldier. You are, however, the last line of defense for the remaining living crew.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/17470/header.jpg?t=1664889864', 0, 0, NULL);
INSERT INTO games VALUES (127153, 17480, 'Command & Conquer™ Red Alert™ 3', 'The desperate leadership of a doomed Soviet Union travels back in time to change history and restore the glory of Mother Russia.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/17480/header.jpg?t=1741704738', 1, 0, NULL);
INSERT INTO games VALUES (127127, 17710, 'Nuclear Dawn', 'Explore war-torn post-apocalyptic landscapes and take fight against enemies using various weapons in this FPS/RTS hybrid.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/17710/header.jpg?t=1705881554', 1, 0, NULL);
INSERT INTO games VALUES (127129, 18000, 'Precipice of Darkness, Episode One', 'On the Rain-Slick Precipice of Darkness, Episode One is the first installment in the RPG-Adventure game series based on the web comic Penny Arcade. Create your character in the classic comic style, and join Gabe and Tycho in the alternate 1920s universe of New Arcadia, where you''ll combat savage enemies, solve mysteries, meet bizarre new...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/18000/header.jpg?t=1447351344', 0, 0, NULL);
INSERT INTO games VALUES (127130, 18020, 'Precipice of Darkness, Episode Two', 'On the Rain-Slick Precipice of Darkness, Episode Two is the second installment in the RPG-adventure game series based on the web comic Penny Arcade. Whether you''re a fan of the first installment or new to the series, you''ll be able to pick up and play Episode Two as a standalone experience.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/18020/header.jpg?t=1447351546', 0, 0, NULL);
INSERT INTO games VALUES (127131, 18040, 'DeathSpank', 'For uncounted years, DeathSpank has been a Dispenser of Justice, a Vanquisher of Evil, and a Hero to the Downtrodden.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/18040/header.jpg?t=1615215099', 0, 0, NULL);
INSERT INTO games VALUES (127133, 18050, 'DeathSpank: Thongs of Virtue', 'Join DeathSpank in the hunt for the Thongs of Virtue! Fight through all new environments and quests and collect all new weapons, armor, and loot in one of the funniest action-RPGs to date!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/18050/header.jpg?t=1615197289', 0, 0, NULL);
INSERT INTO games VALUES (127134, 18070, 'The Baconing', 'Roesha is a downloadable co-op character who helps DeathSpank in both his battles and his adventure. Enjoy 50% off both the game and DLC!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/18070/header.jpg?t=1447354527', 0, 0, NULL);
INSERT INTO games VALUES (127136, 18110, 'Shattered Horizon', 'Experience zero gravity space combat in this innovative FPS. Now includes the Last Stand pack: play all game modes in single player with bots.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/18110/header.jpg?t=1569394150', 0, 0, NULL);
INSERT INTO games VALUES (127137, 18120, 'Unstoppable Gorg', 'Defend the solar system from fearsome aliens by sending satellites into orbit in revolutionary tower defense action!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/18120/header.jpg?t=1573632254', 0, 0, NULL);
INSERT INTO games VALUES (127138, 18300, 'Spectraball', 'Spectraball combines elements of platforming, puzzle solving, addictive gameplay, and stunning visuals to deliver an experience that sets a new standard for the genre. In addition, Spectraball utilizes Steamworks, offering full support for achievements and stat tracking.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/18300/header.jpg?t=1447351501', 0, 0, NULL);
INSERT INTO games VALUES (127120, 18500, 'Defense Grid: The Awakening', 'Defense Grid: The Awakening is a unique spin on tower defense gameplay that will appeal to players of all skill levels. A horde of enemies is invading, and it''s up to the player to stop them by strategically building fortification towers around their base.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/18500/header.jpg?t=1721059385', 0, 0, NULL);
INSERT INTO games VALUES (127122, 18700, 'And Yet It Moves', 'And Yet It Moves is a puzzle-platformer, set in a unique world, made of ripped paper. Within the paper-collage you can jump, run and last but certainly not least: rotate the world. Learn how to apply the physical consequences of rotation to master the many tricky situations you may encounter.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/18700/208611c758a9144526656c9ece7a0813152edc02/header.jpg?t=1748516696', 0, 0, NULL);
INSERT INTO games VALUES (127123, 18820, 'Zero Gear', 'Zero Gear is physically-fueled, online multiplayer kart combat madness. Deck out your kart and character before jumping into one of many different game modes. Outrageous kinematic gameplay and weapons make every round a blast. The potential for tiny vehicular mayhem has never been so humongous!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/18820/header.jpg?t=1668706888', 0, 0, NULL);
INSERT INTO games VALUES (127124, 19200, 'Tank Universal', 'Tank Universal is an action FPS tank wargame inspired by Tron and Battlezone. Explore a rich virtual sci-fi 3D world, and take part in large-scale tank combat between your AI allies and the forces of an evil dictator.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/19200/header.jpg?t=1635514825', 0, 0, NULL);
INSERT INTO games VALUES (136362, 19800, 'Brothers in Arms: Earned in Blood™', 'With its unprecedented combination of authenticity, compelling story and squad-based action, the Brothers in Arms franchise has established itself as a benchmark for military action games, receiving the highest average review scores of any console WWII game to date (www.gamerankings.com).', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/19800/header.jpg?t=1544534652', 0, 0, NULL);
INSERT INTO games VALUES (127100, 19830, 'Tom Clancy''s Rainbow Six® 3 Gold', 'Raven Shield:Command an elite multinational squad of special operatives against hidden terrorist forces. In Tom Clancy''s Rainbow Six 3: Raven Shield, the third installment to the wildly popular Rainbow Six series, Team Rainbow faces the hidden global forces of a new and secretive foe.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/19830/header.jpg?t=1692730213', 0, 0, NULL);
INSERT INTO games VALUES (127101, 19900, 'Far Cry® 2', 'You are a gun for hire, trapped in a war-torn African state, stricken with malaria and forced to make deals with corrupt warlords on both sides of the conflict in order to make this country your home. You must identify and exploit your enemies'' weaknesses, neutralizing their superior numbers and firepower with surprise, subversion,...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/19900/header.jpg?t=1709317476', 0, 0, NULL);
INSERT INTO games VALUES (127102, 19980, 'Prince of Persia®', 'The critically acclaimed Prince of Persia® franchise returns for the first time on next-generation platforms with an all-new epic journey. Built by the same award-winning Ubisoft Montreal studio that created Assassin''s Creed™, Prince of Persia has been in development for over three years to deliver a whole new action-adventure gaming...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/19980/header.jpg?t=1720535332', 0, 0, NULL);
INSERT INTO games VALUES (127104, 20500, 'Red Faction Guerrilla Steam Edition', 'Set 50 years after the climactic events of the original Red Faction, Red Faction: Guerrilla allows players to take the role of an insurgent fighter with the newly re-established Red Faction movement as they battle for liberation from the oppressive Earth Defense Force.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/20500/header.jpg?t=1591111308', 0, 0, NULL);
INSERT INTO games VALUES (127105, 20510, 'S.T.A.L.K.E.R.: Clear Sky', 'S.T.A.L.K.E.R.: Clear Sky – standalone prequel for the acclaimed S.T.A.L.K.E.R.: Shadow of Chernobyl, which tells you story about the Clear Sky group, that want to research the Zone and understand it better.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/20510/header.jpg?t=1747756044', 0, 0, NULL);
INSERT INTO games VALUES (127106, 20530, 'Red Faction', 'JOIN THE REVOLUTION! Lured to Mars by the Ultor Corporation''s promise of a better life, thousands have come to seek their fortune and work for the massive mining company. But all is not as it seems. A deadly plague is sweeping through the barracks, and miners suffer daily abuse at the hands of the Ultor guards.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/20530/header.jpg?t=1709553303', 0, 0, NULL);
INSERT INTO games VALUES (127107, 20540, 'Company of Heroes: Tales of Valor', 'Company of Heroes®: Tales of Valor™ is the expansion to the Game of the Year winner and highest rated real time strategy franchise Company of Heroes®. Featuring new campaigns to overcome, units to command, and battlefields to conquer, Company of Heroes®: Tales of Valor™ delivers evolved gameplay mechanics and 3 episodic adventures...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/20540/header.jpg?t=1711460562', 0, 0, NULL);
INSERT INTO games VALUES (127108, 20550, 'Red Faction II', 'Twenty-second century Earth. Five years after the rebellion on Mars. For the last 15 years, Sopot, the corrupt dictator, has oppressed the people of the Commonwealth. His relentless pursuit of unification with the neighboring United Republic has left the country soaked in unnecessary bloodshed and poverty.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/20550/header.jpg?t=1709553317', 0, 0, NULL);
INSERT INTO games VALUES (136770, 20570, 'Warhammer® 40,000: Dawn of War® II Chaos Rising', 'In Dawn of War II: Chaos Rising you will take command of the Blood Ravens and defend the sector against the Chaos Space Marines of the Black Legion. Purge the Chaos filth and hold the chapter together as traitorous forces work from within to try bring down the Blood Ravens.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/20570/header.jpg?t=1726774741', 0, 0, NULL);
INSERT INTO games VALUES (127111, 20820, 'Shatter', 'Shatter is a retro-inspired brick-breaking game that merges familiar action with unique twists and a modern crafted production approach.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/20820/header.jpg?t=1747697858', 0, 0, NULL);
INSERT INTO games VALUES (127112, 20900, 'The Witcher: Enhanced Edition Director''s Cut', 'Become The Witcher, Geralt of Rivia, a legendary monster slayer caught in a web of intrigue woven by forces vying for control of the world. Make difficult decisions and live with the consequences in a game that will immerse you in an extraordinary tale like no other.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/20900/header.jpg?t=1749200362', 0, 0, NULL);
INSERT INTO games VALUES (127113, 20920, 'The Witcher 2: Assassins of Kings Enhanced Edition', 'A time of untold chaos has come. Mighty forces clash behind the scenes in a struggle for power and influence. The Northern Kingdoms mobilize for war. But armies on the march are not enough to stop a bloody conspiracy...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/20920/header.jpg?t=1749200131', 1, 0, NULL);
INSERT INTO games VALUES (131582, 21010, 'Watchmen: The End is Nigh', 'The lines between good and bad have been blurred and crime and terror run rampant in the streets. The alleys, rooftops and sewers are crawling with criminals and brutal gangs. And now, Underboss — in a daring escape — has broken out of prison and is ruling with vicious darkness.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/21010/header.jpg?t=1723776967', 0, 0, NULL);
INSERT INTO games VALUES (127094, 21030, 'Watchmen: The End is Nigh Part 2', 'Watchmen: The End Is Nigh Part 2 delves further into the partnership of Rorschach and Nite Owl before the hero-banning Keene Act. It’s now June 1977, and any day now the passage of the Keene Act will outlaw all masked vigilantes not sanctioned by the government.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/21030/header.jpg?t=1723777053', 0, 0, NULL);
