INSERT INTO games VALUES (127097, 21110, 'F.E.A.R.', 'Experience the original F.E.A.R. along with F.E.A.R. Extraction Point and F.E.A.R. Perseus Mandate.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/21090/header.jpg?t=1681232225', 0, 0, NULL);
