INSERT INTO games VALUES (127099, 21130, 'LEGO® Harry Potter: Years 1-4', 'Build the adventure from Privet Drive to the Triwizard Tournament and experience the magic of the first four Harry Potter stories – LEGO style! Explore Hogwarts™ School of Witchcraft and Wizardry, learn spells, brew potions and relive the adventures like never before with tongue-in-cheek humor and creative customization that is unique to...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/21130/header.jpg?t=1728579610', 0, 0, NULL);
INSERT INTO games VALUES (127089, 21690, 'Resident Evil 5', 'This game is a port of the Games for Windows - Live version that was released in 2009. If you buy the Untold Stories Bundle here on Steam, it will be the same as upgrading to Resident Evil 5 Gold Edition.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/21690/header.jpg?t=1712193350', 0, 0, NULL);
INSERT INTO games VALUES (127090, 21780, 'Driver® Parallel Lines', 'You were the fastest wheelman on the street. You were a legend. You were money. Until they set you up and sent you down. Twenty-eight years inside for someone else''s crime. Now you''re getting out. Guess what? You got a new job, it''s called getting revenge.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/21780/header.jpg?t=1447351411', 0, 0, NULL);
INSERT INTO games VALUES (127091, 21800, 'Tom Clancy''s EndWar™', 'Live the thrilling career of an army commander and lead your army to victory in a massive online World War III! Take control of the U.S.-led Joint Strike Force, the European Enforcers Corps, or the Russian Spetsnaz Guards Brigade in a persistent ongoing World War.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/21800/header.jpg?t=1698436023', 0, 0, NULL);
INSERT INTO games VALUES (138946, 21980, 'Call of Juarez: Bound in Blood', 'THE OLD WEST, 1864. In order to save their family, the McCall brothers will kill anyone who stands between them and the legendary Gold of Juarez.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/21980/header.jpg?t=1685519805', 0, 0, NULL);
INSERT INTO games VALUES (127092, 22000, 'World of Goo', 'World of Goo is a multiple award winning physics based puzzle / construction game made entirely by two guys.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/22000/header.jpg?t=1745599609', 1, 0, NULL);
INSERT INTO games VALUES (127093, 22100, 'Mount & Blade', 'Calradia is a land at war, offering great riches and even greater dangers to adventurers and mercenaries that flock to shed their blood on its soil. With courage and a strong sword, an unknown stranger can make a name as a warrior. Free-form sand-box gameplay.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/22100/header.jpg?t=1728559530', 0, 0, NULL);
INSERT INTO games VALUES (127069, 22120, 'Penumbra: Black Plague Gold Edition', 'Surrounded by enemies and assaulted by terror from all sides, Philip must collect clues and solve vexing puzzles while combating the gnawing psychological terrors that assail his mind and threaten to strip him of his sanity.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/22120/header.jpg?t=1727954568', 0, 0, NULL);
INSERT INTO games VALUES (127070, 22130, 'Hearts of Iron 2 Complete', 'Includes Hearts of Iron II plus the two expansions, Doomsday and Armageddon When Germany is defeated in 1945, the Allies and the new Soviet alliance fight for supremacy. World War III is drawing closer. Play as the ruler of one of 175 countries through World Wars II and III.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/22130/header.jpg?t=1669909739', 0, 0, NULL);
INSERT INTO games VALUES (127071, 22140, 'Penumbra: Requiem', 'Puzzle expansion for Penumbra: Black Plague. Requiem is part of Penumbra: Black Plague Gold Edition, included in the Penumbra Collection.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/22140/header.jpg?t=1727954566', 0, 0, NULL);
INSERT INTO games VALUES (127072, 22180, 'Penumbra Overture', 'Penumbra: Overture is a first person survival horror game, emphasizing on survival and problem solving instead of mindless violence and gore.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/22180/header.jpg?t=1727954565', 0, 0, NULL);
INSERT INTO games VALUES (132905, 22200, 'Zeno Clash', 'Zeno Clash is an action/fighting game set in a punk fantasy world. The game is played from a first person perspective and the combat is generally up close and brutal. Experience a deep storyline set in a fantastic world.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/22200/header.jpg?t=1660841601', 0, 0, NULL);
INSERT INTO games VALUES (127073, 22230, 'Rock of Ages', 'A rock-solid combination of rock-rolling action, deep strategy, and captivating art and music from different ages of history, this is a game of crush or be crushed!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/22230/header.jpg?t=1667563022', 0, 0, NULL);
INSERT INTO games VALUES (127074, 22300, 'Fallout 3', 'Vault-Tec engineers have worked around the clock on an interactive reproduction of Wasteland life for you to enjoy from the comfort of your own vault. Included is an expansive world, unique combat, shockingly realistic visuals, tons of player choice, and an incredible cast of dynamic characters.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/22300/header.jpg?t=1732208474', 0, 0, NULL);
INSERT INTO games VALUES (127075, 22310, 'Rogue Warrior', 'Rogue Warrior is a character-driven, first-person-shooter, featuring Richard ''Demo Dick'' Marcinko''s explosive personality in an action-packed single player campaign, and intense multiplayer combat. Playing as Richard ''Demo Dick'' Marcinko, you go behind the iron curtain to disrupt a suspected North Korean ballistic missile program.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/22310/header.jpg?t=1574189934', 0, 0, NULL);
INSERT INTO games VALUES (127076, 22320, 'The Elder Scrolls III: Morrowind® Game of the Year Edition', 'The Elder Scrolls III: Morrowind® Game of the Year Edition includes Morrowind plus all of the content from the Bloodmoon and Tribunal expansions. The original Mod Construction Set is not included in this package. An epic, open-ended single-player RPG, Morrowind allows you to create and play any kind of character imaginable.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/22320/header.jpg?t=1569959880', 0, 0, NULL);
INSERT INTO games VALUES (127077, 22330, 'The Elder Scrolls IV: Oblivion® Game of the Year Edition (2009)', 'PUBLISHER UPDATE - This is the product page for The Elder Scrolls IV: Oblivion Game of the Year Edition, released in 2009. ---The Elder Scrolls IV: Oblivion® Game of the Year Edition presents one of the best RPGs of all time like never before. Step inside the most richly detailed and vibrant game-world ever created.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/22330/header.jpg?t=1745343031', 0, 0, NULL);
INSERT INTO games VALUES (127078, 22340, 'Call of Cthulhu®: Dark Corners of the Earth', 'Call of Cthulhu: Dark Corners of the Earth is a first-person horror game that combines intense action and adventure elements.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/22340/header.jpg?t=1573831510', 0, 0, NULL);
INSERT INTO games VALUES (127079, 22350, 'BRINK', 'You decide the combat role you want to assume in the world of Brink as you fight to save yourself and mankind’s last refuge!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/22350/header.jpg?t=1573221255', 0, 1, NULL);
INSERT INTO games VALUES (127082, 22370, 'Fallout 3: Game of the Year Edition', 'Prepare for the Future™ With Fallout 3: Game of the Year Edition, experience the most acclaimed game of 2008 like never before. Create a character of your choosing and descend into an awe-inspiring, post-apocalyptic world where every minute is a fight for survival.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/22370/header.jpg?t=1732208097', 0, 0, NULL);
INSERT INTO games VALUES (127083, 22380, 'Fallout: New Vegas', 'Welcome to Vegas. New Vegas. Enjoy your stay!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/22380/header.jpg?t=1665072891', 0, 0, NULL);
INSERT INTO games VALUES (127084, 22450, 'Hunted: The Demon’s Forge™', 'It will take the combined efforts of two great warriors to explore menacing dungeons, overgrown ruins, and downtrodden towns … and discover the secrets of the Demon’s Forge.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/22450/header.jpg?t=1572894032', 0, 0, NULL);
INSERT INTO games VALUES (127085, 22500, 'Spectromancer', 'A turn-based online fantasy card game. No character leveling, no grinding, no deck building - just 100% skill-based and fast-paced card battles!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/22500/header.jpg?t=1706852656', 0, 0, NULL);
INSERT INTO games VALUES (127065, 22600, 'Worms Reloaded', 'Ten years on from Worms™ Armageddon and the turn-based comic mayhem continues in Worms™ Reloaded, an all-new edition available for PC through Steam.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/22600/header.jpg?t=1596807362', 0, 0, NULL);
INSERT INTO games VALUES (127066, 22610, 'Alien Breed: Impact', 'Experience the explosive science fiction arcade-shooter that resurrects a much revered franchise in an epic single player and co-op multiplayer campaign.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/22610/header.jpg?t=1741626879', 0, 0, NULL);
INSERT INTO games VALUES (127067, 22650, 'Alien Breed 2: Assault', 'Can you survive the alien onslaught? Gamers across the world will now have a chance to play the next chapter in this high-budget, high-quality series.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/22650/header.jpg?t=1668766470', 0, 0, NULL);
