INSERT INTO games VALUES (127053, 23310, 'The Last Remnant™', 'Mitra, yama, qsiti, sovani... These four races exist in one world. A world filled with Remnants — mysterious artifacts from an ancient era. Who created the Remnant? How long ago? And for what purpose? With these questions left unanswered, the Remnants became beneficial tools used for the good of civilization. The world was at peace...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/23310/header.jpg?t=1536078342', 0, 0, NULL);
INSERT INTO games VALUES (127054, 23380, 'Gyromancer', 'Gyromancer is a Pop Cap / Square Enix collaboration. This is a Puzzle RPG. Join Rivel and his companion, Laska, on a grand chase spanning twelve stages. What awaits at the end of the hunt?Each stage contains its own objectives, from defeating the beasts that block your way to solving puzzles before time runs out.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/23380/header.jpg?t=1576026145', 0, 0, NULL);
INSERT INTO games VALUES (127055, 23400, 'Imperium Romanum Gold Edition', 'The city builder strategy game Imperium Romanum is set in the time-honoured Roman Empire. As governor of a Roman province, you will devise a strategy to build a well organised, prosperous and commanding settlement. Its fortune very much lies in your own hands.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/23400/header.jpg?t=1730292613', 0, 0, NULL);
INSERT INTO games VALUES (127056, 23420, 'Europa Universalis: Rome - Gold Edition', 'Europa Universalis Rome Gold combines the epic strategy title Europa Universalis Rome with the expansion pack Vae Victis. Experience one of the most defining periods in world history in an experience crafted by the masters of Grand Strategy.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/23420/header.jpg?t=1669649162', 0, 0, NULL);
INSERT INTO games VALUES (127057, 23450, 'Grand Ages: Rome', 'As Governor of a Roman Province in the time-honoured Roman Empire, its fortune very much lies in your hands. Choose one of five Roman noble families such as Caesar’s Julii with different abilities to accomplish the comprehensive missions.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/23450/header.jpg?t=1730286138', 0, 0, NULL);
INSERT INTO games VALUES (127059, 23460, 'Ceville', 'The mean cruel cold blooded tyrant Ceville ruthlessly rules the beautiful kingdom of Faeryanis. Or rather, he used to rule the beautiful kingdom of Faeryanis, until the brave people revolted against his regime and drove him out of the palace.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/23460/header.jpg?t=1668502176', 0, 0, NULL);
