INSERT INTO games VALUES (127061, 23500, 'Puzzle Quest: Galactrix', 'The puzzle game of the future has arrived! The original best-selling new Puzzle franchise is back in an all new dimension with its signature Match-3, turn based battles in an insanely addictive and masterful hybrid of RPG and Puzzle genres.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/23500/header.jpg?t=1478043305', 0, 0, NULL);
INSERT INTO games VALUES (127062, 23530, 'Earth Defense Force: Insect Armageddon', 'Thousands of giant insects and aliens once again ravage the earth, and only the Earth Defense Force can stop them.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/23530/header.jpg?t=1478042684', 0, 0, NULL);
