INSERT INTO games VALUES (127033, 24240, 'PAYDAY™ The Heist', 'Take on the role of a hardened career criminal executing intense, dynamic heists in constant pursuit of the next “big score”', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/24240/header.jpg?t=1747223432', 0, 0, NULL);
INSERT INTO games VALUES (127034, 24400, 'King Arthur - The Role-playing Wargame', 'Welcome to the lost age of chivalry, where magic and myth is alive, and you are destined to be one of the living legends: Arthur, the son of Uther Pendragon, the Once and Future King of the prophecies. Fulfill your destiny and claim your rightful place on the throne of Britannia.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/24400/header.jpg?t=1589881021', 0, 0, NULL);
INSERT INTO games VALUES (127036, 24420, 'Aquaria', 'Aquaria is an award-winning action-adventure game set in a massive underwater world teeming with life and filled with ancient secrets. Join Naija, a lone underwater adventurer, as she travels from hidden caves shrouded in darkness, to beautiful, sunlit oases in search of her past.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/24420/header.jpg?t=1447351632', 0, 0, NULL);
INSERT INTO games VALUES (127038, 24480, 'King Arthur II: The Role-Playing Wargame', 'Experience the sequel to the Role-playing Real Time Strategy Hit!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/24480/header.jpg?t=1669816972', 0, 0, NULL);
INSERT INTO games VALUES (127042, 24670, 'Trainz™ Simulator 12', 'Released 2011. See also Trainz A New Era and TRS19.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/24670/header.jpg?t=1571295015', 0, 0, NULL);
INSERT INTO games VALUES (127043, 24720, 'SPORE™ Galactic Adventures', 'Take Your Creature From Zero To Galactic HeroGet out of your starship and turn your Spore creatures into legendary Space Captains. For the first time, beam down with your allies to take on action-packed, planetside adventures. Complete quests, collect rewards, and even create your own missions.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/24720/header.jpg?t=1659617138', 0, 0, NULL);
