INSERT INTO games VALUES (127045, 24790, 'Command & Conquer 3 Tiberium Wars™', 'The year is 2047. A massive nuclear fireball explodes high in the night sky, marking the dramatic beginning of the Third Tiberium War and the long-awaited return of the most groundbreaking Real-Time Strategy franchise of all time', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/24790/header.jpg?t=1741704759', 1, 0, NULL);
INSERT INTO games VALUES (127025, 24800, 'Command & Conquer: Red Alert 3 - Uprising', 'Red Alert 3: Uprising features four new mini-campaigns, giving players a deeper dive into the storyline''s of the Soviets, the Allies, the Empire of the Rising Sun and a unique campaign centered on the origins of everyone’s favorite psionic Japanese schoolgirl commando, Yuriko Omega.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/24800/header.jpg?t=1741704725', 1, 0, NULL);
INSERT INTO games VALUES (127026, 24810, 'Command & Conquer™ 3: Kane’s Wrath', 'In the name of Kane! The Command &amp; Conquer™ series continues to thrive with Command &amp; Conquer™ 3: Kane’s Wrath.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/24810/header.jpg?t=1741704747', 1, 0, NULL);
INSERT INTO games VALUES (127027, 24870, 'Need for Speed: Shift', 'Need for Speed™ SHIFT is an award-winning authentic racing game that combines the true driver’s experience with real-world physics, pixel-perfect car models, and a wide range of authentic race tracks. Need for Speed SHIFT takes players in a different direction to create a simulation experience that replicates the true feeling of driving...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/24870/header.jpg?t=1622575105', 0, 0, NULL);
INSERT INTO games VALUES (127028, 24880, 'The Saboteur™', 'This open-world action thriller takes you through the seedy streets of Paris as you seek to undermine the German authority and lead a rebellion. Fight across rooftops and through dangerous alleys, and operate a wide variety of vehicles as you navigate your terrain.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/24880/header.jpg?t=1718287884', 0, 0, NULL);
INSERT INTO games VALUES (127029, 25000, 'Overgrowth', 'Feel like the star of a martial arts film in Overgrowth, as you jump, kick, throw, and slash your way to victory. Free the rabbits from their evil overlords in the main story, then play through the prequel story, and finally, try out nine years of mods developed by the community, or create your own!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/25000/header.jpg?t=1667232407', 0, 0, NULL);
INSERT INTO games VALUES (127030, 25010, 'Lugaru HD', 'Follow Turner, a rebel bunny rabbit with impressive combat skills in his quest to find those responsible for slaughtering his village. Uncover a far-reaching conspiracy involving the corrupt leaders of the rabbit republic and the wolves of the nearby lands. Streamlined Combat: Gone are the days of combo memorization and button mashing.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/25010/header.jpg?t=1667233211', 0, 0, NULL);
INSERT INTO games VALUES (127032, 25600, 'Eschalon: Book I', 'Eschalon: Book I is an old-school role-playing game that will take you across massive outdoor environments and deep into dozens of sprawling dungeons as you seek to uncover the mystery of who you are. It features a tile-built, turn-based game world where the result of absolutely every action is rolled, calculated or statistically...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/25600/header.jpg?t=1572431963', 0, 1, NULL);
INSERT INTO games VALUES (127016, 25700, 'Madballs in Babo:Invasion', 'Now with cross-platform multiplayer! PC vs. Mac at last.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/25700/header.jpg?t=1572532849', 1, 0, NULL);
INSERT INTO games VALUES (127017, 25800, 'Europa Universalis III Complete', 'Europa Universalis III Complete includes the original Europa Universalis III as well as the expansions In Nomine and Napoleons Ambition Europa Universalis III delves deeply into the areas of exploration, trade, warfare and diplomacy.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/25800/header.jpg?t=1669909664', 0, 0, NULL);
INSERT INTO games VALUES (127019, 25830, 'Knights of Honor', 'As King, it is your duty to lead your people in their struggle to raise your kingdom from its humble beginnings to a position of power and prestige. War, diplomacy and a burgeoning economy are the means by which you increase your power and expand your influence.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/25830/header.jpg?t=1713278015', 0, 0, NULL);
INSERT INTO games VALUES (127022, 25890, 'Hearts of Iron III', 'Hearts of Iron III lets you play the most engaging conflict in world history, World War 2, on all fronts as any country and through multiple different scenarios. Guide your nation to glory between 1936 and 1948 and wage war, conduct diplomacy and build your industry in the most detailed World War 2 game ever made.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/25890/header.jpg?t=1669816232', 0, 0, NULL);
INSERT INTO games VALUES (127023, 25900, 'King''s Bounty: The Legend', 'King''s Bounty: The Legend is an adventure game with tactical turn-based battles and role-playing elements.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/25900/header.jpg?t=1721724331', 0, 0, NULL);
INSERT INTO games VALUES (127024, 25910, 'Supreme Ruler 2020 Gold', 'Supreme Ruler 2020 Gold contains Supreme Ruler 2020 and the expansion, Global Crisis: SUPREME RULER 2020 Overnight, the US dollar crashes AND the sound echoes across the globe. The economic crisis amplifies global instabilities and regional disputes, tearing the world asunder. Nations dissolve, economies collapse, and tensions escalate.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/25910/header.jpg?t=1726496942', 0, 0, NULL);
INSERT INTO games VALUES (127002, 25930, 'East India Company', 'Trade exotic goods, command fleets, and dominate 17th-century seas. This blend of real-time strategy and naval warfare lets you build a trading empire across Europe and Asia. Strategize trade routes, engage in epic naval battles, and expand your influence to become the ultimate maritime force.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/25930/header.jpg?t=1737975903', 0, 0, NULL);
INSERT INTO games VALUES (127003, 25980, 'Majesty 2', 'In the world of Majesty, you are the ruler of the kingdom Ardania. At your service are your loyal and somewhat obnoxious subordinates, who have their own minds about how things should be done. In fact, Majesty is the only game where your heroes decide on their own what should be done and when, leaving you to try to control them through...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/25980/header.jpg?t=1669909907', 0, 0, NULL);
INSERT INTO games VALUES (127004, 25990, 'Majesty Gold HD', 'The High Definition edition of Majesty Gold contains main game, the Northern Expansion Pack as well as 2 new quests and several other graphics and gameplay updates.Majesty is a Real-time strategy game with indirect control – your heroes have a will of their own!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/25990/header.jpg?t=1713279683', 0, 0, NULL);
INSERT INTO games VALUES (127005, 26000, 'The Maw', 'The pinnacle of alien evolution, Maw is a cowardly fat blob concerned mostly with snacking and lounging. He can, however, absorb the traits of anything he eats, is virtually indestructible, and can grow to unlimited size. If he wasn''t a danger to all life in the universe, he''d make the perfect pet.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/26000/header.jpg?t=1667851486', 1, 0, NULL);
INSERT INTO games VALUES (127007, 26500, 'Cogs', 'Cogs is a puzzle game where players build machines from sliding tiles. Players can choose from 50 levels and 3 gameplay modes. New puzzles are unlocked by building contraptions quickly and efficiently. Inventor Mode: Starting with simple puzzles, players are introduced to the widgets that are used to build machines  gears, pipes,...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/26500/c3d262489f77c07c5eeb5f9823014fd11c93e21d/header.jpg?t=1747422815', 0, 0, NULL);
INSERT INTO games VALUES (127008, 26800, 'Braid', 'This is the original version of Braid from 2009, which may not work well on newer systems. For an updated version of the game with nicer graphics, more levels and a large amount of developer commentary, see Braid, Anniversary Edition.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/26800/header.jpg?t=1734027955', 1, 0, NULL);
INSERT INTO games VALUES (127009, 26900, 'Crayon Physics Deluxe', 'Crayon Physics Deluxe is a 2D physics puzzle / sandbox game, in which you get to experience what it would be like if your drawings would be magically transformed into real physical objects. Solve puzzles with your artistic vision and creative use of physics.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/26900/header.jpg?t=1667476228', 0, 0, NULL);
INSERT INTO games VALUES (127010, 27000, 'The Path', 'There is one rule in the game. And it needs to be broken. There is one goal. And when you attain it, you die.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/27000/header.jpg?t=1667032931', 0, 0, NULL);
INSERT INTO games VALUES (127011, 27020, 'The Graveyard', 'The Graveyard is a very short computer game. You play an old lady who visits a graveyard. You walk around, sit on a bench and listen to a song. It''s more like an explorable painting than an actual game. An experiment with poetry and storytelling but without words.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/27020/header.jpg?t=1667032207', 0, 0, NULL);
INSERT INTO games VALUES (126991, 27900, 'Twin Sector', 'The story of Twin Sector takes place in a post-apocalyptic future where the remains of mankind have been put to artificial sleep in cryogenic chambers deep under the contaminated surface of earth — until the planet becomes habitable again. You as the player must take the role of Ashley Simms, the protagonist of Twin Sector.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/27900/header.jpg?t=1533143416', 0, 0, NULL);
INSERT INTO games VALUES (126993, 27940, 'Dead Horde', 'As a survivor of the mutant virus, make your way through the city and wipe out the hordes of flesh eating mutants. Teamwork is the key to survive the DEAD HORDE...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/27940/header.jpg?t=1601304558', 0, 0, NULL);
INSERT INTO games VALUES (131836, 28000, 'Kane & Lynch 2: Dog Days', 'Pure adrenaline of non-stop action in Single Player, Online Co-op and Multiplayer. Double the pleasure and mayhem with new multiplayer DLCs! (click for details)', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/28000/header.jpg?t=1592492023', 0, 0, NULL);
INSERT INTO games VALUES (126997, 29180, 'Osmos', 'Enter the ambient world of Osmos: elegant, physics-based gameplay, dreamlike visuals, and a minimalist, electronic soundtrack. Your objective is to grow by absorbing other motes. Propel yourself by ejecting matter behind you. But be wise: ejecting matter also shrinks you. Relax - good things come to those who wait.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/29180/header.jpg?t=1602721579', 0, 0, NULL);
INSERT INTO games VALUES (126969, 29800, 'Caster', 'Dash across Scenic Locations destroying bug like creatures called the Flanx using 6 Unique Attacks that include Massive Terrain Deformation and High Speed Barrages of Energy Blasts!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/29800/header.jpg?t=1462569292', 0, 0, NULL);
INSERT INTO games VALUES (126970, 29900, 'Dark Sector', 'A third-person Action/Shooter that thrusts players into a sci-fi flavored nightmare scenario set in the post Cold War era.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/29900/header.jpg?t=1732992837', 0, 0, NULL);
INSERT INTO games VALUES (126971, 31100, 'Wallace & Gromit’s Grand Adventures', 'Enter the colorful world of West Wallaby Street in a series of four cracking adventures brought to you by Aardman Animations, the creators of the Wallace &amp; Gromit animated films, and award-winning Telltale Games.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/31100/header.jpg?t=1744374797', 0, 0, NULL);
INSERT INTO games VALUES (126974, 31170, 'Tales of Monkey Island: Complete Season', 'While explosively stripping the evil pirate LeChuck of his demonic mojo, Guybrush Threepwood inadvertently infects the entire Caribbean with the arch-fiend''s expelled voodoo, which threatens to transform buccaneers into unruly pirate monsters.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/31170/header.jpg?t=1714040835', 0, 0, NULL);
INSERT INTO games VALUES (126979, 31220, 'Sam & Max 301: The Penal Zone', 'Wield psychic powers against fearsome foes in this epic comedy saga. In The Devil’s Playhouse, an otherworldly power for controlling matter and space calls to the strongest and strangest who might wield it -- intergalactic warlords and eldritch gods, under-dwellers and scholars of the arcane.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/31220/header.jpg?t=1719435979', 0, 0, NULL);
INSERT INTO games VALUES (126984, 31270, 'Puzzle Agent', 'Created with indie comic artist Graham Annable''s unique narrative and visual sensibilities, delivered with the distinctive Telltale storytelling style, Puzzle Agent is sure to challenge, thrill and engage in more ways than you can shake a cryptogram at!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/31270/header.jpg?t=1686674900', 0, 0, NULL);
INSERT INTO games VALUES (126985, 31280, 'Poker Night at the Inventory', 'Prepare for a different kind of poker night in a very different kind of club and play against familiar faces!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/31280/header.jpg?t=1558627507', 0, 0, NULL);
INSERT INTO games VALUES (126986, 31290, 'Back to the Future: The Game', 'Featuring a special appearance by Michael J. Fox!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/31290/header.jpg?t=1542232304', 0, 0, NULL);
INSERT INTO games VALUES (126988, 31700, 'Iron Grip: Warlord', 'Iron Grip: Warlord invigorates tower defense with first-person shooter elements to give a new twist to the genre.It puts you in the heat of the battle, fighting off hordes of AI-controlled invaders. Play alone or with friends, in a diverse and challenging struggle to save all of Atelia.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/31700/header.jpg?t=1447353019', 0, 0, NULL);
INSERT INTO games VALUES (126943, 31800, 'Nancy Drew®: Danger by Design', 'Go Undercover in Paris and Unravel a Case in Style!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/31800/header.jpg?t=1734460557', 0, 0, NULL);
INSERT INTO games VALUES (126944, 31810, 'Nancy Drew®: Last Train to Blue Moon Canyon', 'Catch this train — it’s your ticket to solving a century-old mystery!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/31810/header.jpg?t=1734461898', 0, 0, NULL);
INSERT INTO games VALUES (126945, 31820, 'Nancy Drew®: The Haunted Carousel', 'Take a Spin with Danger to Unravel the Mystery of a Ghostly Merry-go-Round!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/31820/header.jpg?t=1734466086', 0, 0, NULL);
INSERT INTO games VALUES (126946, 31830, 'Nancy Drew®: Curse of Blackmoor Manor', 'Delve into Dark Legends Lurking in the Shadow of an Old English Mansion!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/31830/header.jpg?t=1734460177', 0, 0, NULL);
INSERT INTO games VALUES (126947, 31840, 'Nancy Drew®: Danger on Deception Island', 'Plunge into Danger to Bring a Mysterious Island’s Secrets to the Surface!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/31840/header.jpg?t=1734460917', 0, 0, NULL);
INSERT INTO games VALUES (126948, 31850, 'Nancy Drew®: Ghost Dogs of Moon Lake', 'Hunt for Clues on the Trail of a Pack of Phantom Hounds!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/31850/header.jpg?t=1734461024', 0, 0, NULL);
INSERT INTO games VALUES (126949, 31860, 'Nancy Drew®: Legend of the Crystal Skull', 'The Search is on for an Unearthly Artifact in New Orleans!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/31860/header.jpg?t=1734462308', 0, 0, NULL);
INSERT INTO games VALUES (126951, 31880, 'Nancy Drew®: Secret of the Old Clock', 'Venture into the Past and Outwit a Criminal Before Time Runs Out!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/31880/header.jpg?t=1734463685', 0, 0, NULL);
INSERT INTO games VALUES (130391, 31890, 'Nancy Drew®: Secret of the Scarlet Hand', 'Expose Buried Secrets and Catch a Thief Red-handed!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/31890/header.jpg?t=1734464053', 0, 0, NULL);
INSERT INTO games VALUES (126952, 31900, 'Nancy Drew®: The Creature of Kapu Cave', 'Team up with the Hardy Boys® and Track an Ancient Legend Through Hawaii!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/31900/header.jpg?t=1734465113', 0, 0, NULL);
INSERT INTO games VALUES (126953, 31910, 'Nancy Drew®: The Haunting of Castle Malloy', 'Unveil a Ghostly Legend and Find a Vanished Groom!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/31910/header.jpg?t=1734466622', 0, 0, NULL);
INSERT INTO games VALUES (126954, 31920, 'Nancy Drew®: The Phantom of Venice', 'Infiltrate a Carnevale of Criminals in Italy!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/31920/header.jpg?t=1734466860', 0, 0, NULL);
INSERT INTO games VALUES (126955, 31930, 'Nancy Drew®: The White Wolf of Icicle Creek', 'Follow a Trail to Hidden Secrets and Sabotage!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/31930/header.jpg?t=1734468527', 0, 0, NULL);
INSERT INTO games VALUES (126960, 32150, 'Everyday Genius: SquareLogic', 'The next generation of puzzle games is here! Combining simple arithmetic with colorful cages and logical problem solving, this new puzzle game makes sure you never have to guess—and you don’t have to be a math wiz!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/32150/header.jpg?t=1447352629', 0, 0, NULL);
INSERT INTO games VALUES (126961, 32160, 'Zombie Bowl-o-Rama', 'Bowl or Beware! From the depths of the graveyard…a gruesome gang in search of brains! When Zombies show up at the town’s lanes, it’s up to you to put ‘em back in the ground! The Zombies have taken over your favorite lanes, and it’s up to you to send ‘em back to the graveyard where they belong!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/32160/header.jpg?t=1688475037', 0, 0, NULL);
INSERT INTO games VALUES (126963, 32310, 'Indiana Jones® and the Last Crusade™', 'Europe, 1938: The lost Ark was just a warm-up! Now Adolf Hitler is after the most powerful talisman of all - the Holy Grail. A few brave men stand in his way. Fortunately, one of them is Indiana Jones, and this time he has his dad with him.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/32310/header.jpg?t=1741737791', 0, 0, NULL);
INSERT INTO games VALUES (126964, 32330, 'LEGO® Indiana Jones™: The Original Adventures', 'Build, Battle and Brawl your way out of trouble! Play through all three classic Indiana Jones™ movies and relive your favorite Indy adventures in the tongue-in-cheek worlds of LEGO®. Explore and Discover - Battle enemies, solve puzzles, and seek out the world''s greatest treasures.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/32330/header.jpg?t=1699055876', 0, 0, NULL);
INSERT INTO games VALUES (126965, 32340, 'LOOM™', 'Long after the passing of the Second Shadow, when dragons ruled the twilight sky and the stars were bright and numerous, came the Age of the Great Guilds. Blacksmiths. Shepherds. Clerics. Each dedicated to the absolute control of secret knowledge. Another such Guild was the Weavers.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/32340/header.jpg?t=1741809404', 0, 0, NULL);
INSERT INTO games VALUES (126966, 32350, 'STAR WARS™ Starfighter™', 'Join three heroic starfighter pilots in harrowing deep space and planetary missions to save the planet of Naboo. Rookie Naboo pilot Rhys Dallows, mercenary Vana Sage and alien pirate Nym form an unlikely alliance as they join together against an unexpected assault on the peaceful planet.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/32350/header.jpg?t=1741816220', 0, 0, NULL);
INSERT INTO games VALUES (126967, 32360, 'The Secret of Monkey Island: Special Edition', 'Back by popular demand, The Secret of Monkey Island™: Special Edition faithfully re-imagines the internationally-acclaimed classic game (originally released in 1990) for original and new audiences alike.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/32360/header.jpg?t=1741729431', 0, 0, NULL);
INSERT INTO games VALUES (128614, 32370, 'STAR WARS™ Knights of the Old Republic™', 'It is four thousand years before the Galactic Empire and hundreds of Jedi Knights have fallen in battle against the ruthless Sith. You are the last hope of the Jedi Order. Can you master the awesome power of the Force on your quest to save the Republic? Or will you fall to the lure of the dark side?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/32370/header.jpg?t=1681144833', 0, 0, NULL);
INSERT INTO games VALUES (126914, 32380, 'STAR WARS™ Jedi Knight: Dark Forces II', 'Jedi Knight: Dark Forces II picks up where the award-winning Dark Forces™ game left off...with even more features and firepower in dazzling 3D graphics. As Kyle Katarn, you must acquire a lightsaber and learn the ways of the Force to become a Jedi Knight.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/32380/header.jpg?t=1741814501', 0, 0, NULL);
INSERT INTO games VALUES (126915, 32390, 'STAR WARS™ Jedi Knight - Mysteries of the Sith™', 'It is five years after Kyle''s victory over the seven dark Jedi. Invading Imperial forces advance upon a quiet Rebel outpost, interrupting Kyle''s training of a brave new Jedi, Mara Jade. First introduced in Timothy Zahn''s award-winning Star Wars novel, Heir to the Empire, Mara Jade blends her past experiences as a one time smuggler and...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/32390/header.jpg?t=1741815272', 0, 0, NULL);
INSERT INTO games VALUES (126916, 32400, 'STAR WARS™ Dark Forces (Classic, 1995)', 'Behind a veil of secrecy the evil Empire is creating a doomsday army - one that, if finished, will become the final cog in the Empire''s arsenal of terror and domination. Your Mission? Join the Rebel Alliance''s covert operations division, infiltrate the Empire.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/32400/header.jpg?t=1741812834', 0, 0, NULL);
INSERT INTO games VALUES (126918, 32430, 'STAR WARS™ - The Force Unleashed™ Ultimate Sith Edition', 'A game that will show gamers the deepest, darkest side of the Force in a story that puts them on a collision course with Luke Skywalker himself.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/32430/header.jpg?t=1741729267', 0, 0, NULL);
INSERT INTO games VALUES (126919, 32440, 'LEGO® Star Wars™ - The Complete Saga', 'Kick Some Brick in I through VI! Play through all six Star Wars movies in one videogame! Adding new characters, new levels, new features and for the first time ever, the chance to build and battle your way through a fun Star Wars galaxy on your PC!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/32440/header.jpg?t=1604517910', 0, 0, NULL);
INSERT INTO games VALUES (131408, 32450, 'LEGO® Indiana Jones™ 2: The Adventure Continues', 'LEGO® Indy is back in his biggest adventure yet. Battle through all four movies, including all-new levels from the original adventures and your favorite new moments from The Kingdom of the Crystal Skull... or in true LEGO® fashion, get creative and build your own levels to play with friends!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/32450/header.jpg?t=1724886380', 0, 0, NULL);
INSERT INTO games VALUES (126920, 32460, 'Monkey Island™ 2 Special Edition: LeChuck’s Revenge™', 'Wannabe pirate Guybrush Threepwood, and the now zombie pirate LeChuck, return in what has long been considered one of the greatest LucasArts adventure games of all time.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/32460/header.jpg?t=1741809770', 0, 0, NULL);
INSERT INTO games VALUES (126921, 32470, 'STAR WARS™ Empire at War - Gold Pack', 'Command or corrupt an entire galaxy in the definitive Star Wars strategy collection. It is a time of galactic civil war. Will you take up the reins of the Rebellion, assume control of the Empire, or rule the Star Wars Underworld?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/32470/header.jpg?t=1741729002', 0, 0, NULL);
INSERT INTO games VALUES (126922, 32500, 'STAR WARS™: The Force Unleashed™ II', 'The Star Wars® Saga continues with Star Wars®: The Force Unleashed™ II, the highly anticipated sequel to the fastest-selling Star Wars game ever created.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/32500/header.jpg?t=1741729220', 0, 0, NULL);
INSERT INTO games VALUES (126923, 32510, 'LEGO® Star Wars™ III - The Clone Wars™', 'LEGO Star Wars III: The Clone Wars will allow fans to explore endlessly and laugh their way through the Star Wars galaxy in the most humorous, accessible and action-packed LEGO game to date.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/32510/header.jpg?t=1699053866', 0, 0, NULL);
INSERT INTO games VALUES (126924, 32610, 'Delta Force Xtreme 2', 'Enemies lurk in locations around the globe, waiting for the right opportunity to strike. As part of Delta Force, the U.S. Army''s most secretive and highly trained unit, you have the skills and the firepower to hunt them down and take them out.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/32610/header.jpg?t=1733246373', 0, 0, NULL);
INSERT INTO games VALUES (126925, 32620, 'Delta Force 1', 'As a member of Delta Force — The Army''s Elite, top secret special forces unit — the word ''impossible'' is not in your vocabulary. In Delta Force, you will conduct missions swiftly and silently, in every possible terrain, under every imaginable condition and through unconventional means.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/32620/header.jpg?t=1733246315', 0, 0, NULL);
INSERT INTO games VALUES (126926, 32630, 'Delta Force 2', 'You''re a member of the U.S. Army''s best kept secret: the elite SPECIAL OPERATIONS unit known as Delta Force, formed to BATTLE TERRORISM throughout the world. When the best of the rest can''t handle the op, YOU are called into action. Can you handle THE JOB? Features FREE NovaWorld™: online gaming supporting up to 50 players.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/32630/header.jpg?t=1733246331', 0, 0, NULL);
INSERT INTO games VALUES (126927, 32640, 'Delta Force Land Warrior', 'Engage the enemy across vast outdoor environments and expansive indoor environments as you take control of the US Army''s elite anti-terrorist unit. Delta Force Land Warrior™ introduces new weapons and characters for both single player and intense online multiplayer via NovaWorld.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/32640/header.jpg?t=1733246344', 0, 0, NULL);
INSERT INTO games VALUES (126930, 32680, 'Delta Force — Black Hawk Down: Team Sabre', 'Delta Force — Black Hawk Down: Team Sabre is the official expansion pack to the #1 best selling PC game in North America. Team Sabre was developed using the Delta Force — Black Hawk Down engine and it requires the mother product to run.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/32680/header.jpg?t=1733246380', 0, 0, NULL);
INSERT INTO games VALUES (126935, 32750, 'Comanche 4', 'The best-selling Comanche series returns with this fast-paced action game that places you at the controls of a Comanche RAH-66 helicopter. In 6 single player campaigns and multiplayer, the game combines serious firepower with effortless controls and stunning, interactive terrain.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/32750/header.jpg?t=1727864647', 0, 0, NULL);
INSERT INTO games VALUES (126936, 32760, 'Tachyon: The Fringe', 'Caught in the middle of a violent conflict on the fringe of the galaxy — your ability to survive will depend on your piloting skills and combat savvy as a mercenary space fighter. But, as you explore the vastly detailed world of Tachyon: The Fringe, you will often find that the most powerful weapon on your ship is in your head.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/32760/header.jpg?t=1727864842', 0, 0, NULL);
INSERT INTO games VALUES (126937, 32770, 'Joint Operations: Combined Arms Gold', 'The most ferocious online conflict of the 21st century is now available in its most definitive form: introducing Joint Operations: Combined Arms Gold, the largest multiplayer FPS collection ever. With the award-winning Joint Operations: Typhoon Rising and the bestselling Joint Operations: Escalation together in one convenient package,...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/32770/header.jpg?t=1727864992', 0, 0, NULL);
INSERT INTO games VALUES (126938, 32900, 'Restaurant Empire II', 'Restaurant Empire 2 is the most realistic and comprehensive restaurant business simulation available, featuring 4 cuisines, 600 recipes, 4 huge cities, 2 campaigns with a total of 34 missions, 1400 interior objects, and a mix of business strategy and role-playing gameplay such as cooking contests.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/32900/header.jpg?t=1681490080', 0, 0, NULL);
