INSERT INTO games VALUES (126940, 33110, 'Alien Shooter: Revisited', 'Crowds of blood-thirsty monsters, crawling from every corner of the secret research base. Gloomy basements and modern labs, darkness changing into blazing bulbs. The only usual thing is: you''re in a bad place alone, and there''s no one to help you!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/33110/header.jpg?t=1731075623', 0, 0, NULL);
