INSERT INTO games VALUES (130825, 38410, 'Fallout 2: A Post Nuclear Role Playing Game', 'Fallout® 2 is the sequel to the critically acclaimed game that took RPG''ing out of the dungeons and into a dynamic, apocalyptic retro-future. It''s been 80 long years since your ancestors trod across the wastelands.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/38410/header.jpg?t=1572025546', 0, 0, NULL);
INSERT INTO games VALUES (126808, 38420, 'Fallout Tactics: Brotherhood of Steel', 'Tactical Squad-Based Combat comes to the Fallout® Universe! You are the wretched refuse. You may be born from dirt, but we will forge you into steel. You will learn to bend; if not you, will you break. In these dark times, the Brotherhood - your Brotherhood - is all that stands between the rekindled flame of civilization and the howling,...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/38420/header.jpg?t=1572025647', 0, 0, NULL);
