INSERT INTO games VALUES (126812, 38460, 'MDK 2', '3 Unlikely Heroes, 1 Ultimate Goal Kurt Hectic is back to save the universe. This time he is teamed with the genius Dr. Hawkins and the 6-legged gun-toting robotic dog, Max. Together they must out-sneak, out-blast and out-think their enemies as they attempt to reclaim earth from a vile alien menace.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/38460/header.jpg?t=1668714838', 0, 0, NULL);
INSERT INTO games VALUES (126813, 38480, 'Earthworm Jim', 'Jim wasn''t always a studly super-worm. He was once just a spineless, dirt-eater with no real mission in his life...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/38480/header.jpg?t=1668117597', 0, 0, NULL);
INSERT INTO games VALUES (126815, 38600, 'Faerie Solitaire', 'Have magical fun in the addicting Card game, Faerie Solitaire! Find and raise a Faerie pet and repopulate the magical land of Avalon using the resources found by clearing each level.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/38600/header.jpg?t=1598211907', 0, 0, NULL);
INSERT INTO games VALUES (126816, 38700, 'Toki Tori', 'The gameplay in Toki Tori is a blend of two genres. While it looks like a platform game, it''s a puzzle game at heart. To progress through the game, the player must pick up each egg in a level using a set number of tools.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/38700/header.jpg?t=1596256691', 0, 0, NULL);
INSERT INTO games VALUES (126817, 38720, 'RUSH', 'From the twisted puzzle minds behind the award winning Toki Tori comes a new game, simply called RUSH. Fortunately for fans of high quality puzzle games, RUSH is anything but simple. In the game''s fully three dimensional levels, players need to guide cubes to color coded exit points using Conveyor belts, Warps, Stops Signs, Splits and...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/38720/header.jpg?t=1488470929', 0, 0, NULL);
INSERT INTO games VALUES (126818, 38740, 'EDGE', 'EDGE, the award winning retro-styled platform game has been extended! Now with over 40 brand new levels, additional music and all-new races against the notorious Dark Cube!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/38740/header.jpg?t=1596256602', 0, 0, NULL);
INSERT INTO games VALUES (126785, 39000, 'Moonbase Alpha', 'NASA has once again landed on the lunar surface with the goal of colonization, research, and further exploration. Shortly after the return to the Moon, NASA has established a small outpost on the south pole of the moon called Moonbase Alpha.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/39000/header.jpg?t=1447352605', 0, 1, NULL);
INSERT INTO games VALUES (126786, 39110, 'SEASON OF MYSTERY: The Cherry Blossom Murders', 'Your husband Richard lies dead beneath the cherry blossoms of Old Japan, and the police are of no help. Step into history and uncover the truth when no one else will. Find devilishly hidden clues, explore exotic locales, and bring the killer to justice!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/39110/header.jpg?t=1721932682', 0, 0, NULL);
INSERT INTO games VALUES (126787, 39120, 'RIFT', 'Dive into a world of epic adventure! Create your perfect hero thanks to a uniquely customizable class system. Collect, craft, and customize your gear. Go it alone or group up to challenge dungeons, raids, dynamic open-world content, and your fellow players.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/39120/header.jpg?t=1700242293', 0, 1, NULL);
INSERT INTO games VALUES (126788, 39140, 'FINAL FANTASY VII', 'The RPG classic FINAL FANTASY VII returns to PC, now with brand new online features!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/39140/header.jpg?t=1734374610', 0, 0, NULL);
INSERT INTO games VALUES (135360, 39190, 'Dungeon Siege', 'Dungeon Siege® combines the immersive elements of a role-playing game with over-the-top intensity and non-stop action. Dungeon Siege plunges you into a continuous 3D fantasy world where you face off against an army of evil that has been unleashed.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/39190/header.jpg?t=1709630517', 0, 0, NULL);
INSERT INTO games VALUES (126789, 39200, 'Dungeon Siege II', 'It’s been a generation since you vanquished the evil that plagued the Land of Ehb, and now…a new menace has awakened. In Dungeon Siege II, the sequel to the best-selling RPG from Gas Powered Games, you will be called on to again wield sword and spell to save the world from a growing abomination many years in the making.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/39200/header.jpg?t=1683564444', 0, 0, NULL);
INSERT INTO games VALUES (126769, 39510, 'Gothic II: Gold Edition', 'Gothic II: Gold Edition brings together the excitement of Gothic II and the add-on Night of the Raven to your fingertips!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/39510/header.jpg?t=1727858765', 0, 0, NULL);
INSERT INTO games VALUES (126770, 39520, 'The Guild Gold Edition', 'It’s the year 1400- the late Middle Ages. Europe sees the dawn of the golden age of the new departures and the free spirit. Under the rule of the bourgeoisie and businessmen, more and more towns are emerging from the clutches of the aristocracy and are achieving independence, power and wealth.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/39520/header.jpg?t=1562843668', 0, 0, NULL);
INSERT INTO games VALUES (126771, 39530, 'Painkiller: Black Edition', 'Painkiller Black Edition includes the expansion pack Battle Out of Hell, featuring 10 additional single-player levels and many new villains.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/39530/header.jpg?t=1709653382', 0, 0, NULL);
INSERT INTO games VALUES (126772, 39540, 'SpellForce - Platinum Edition', 'Included in the Platinum Edition are three titles:SpellForce: The Order of DawnIn a world beyond imagination...In their immeasurable greed and constant thirst for power, the thirteen most powerful Mages of all time doomed the land, hurling it into an endless spiral of chaos and despair.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/39540/header.jpg?t=1618008861', 0, 0, NULL);
INSERT INTO games VALUES (126773, 39550, 'SpellForce 2 - Anniversary Edition', 'SpellForce 2 - Anniversary Edition presents the award-winning SpellForce saga hits: &quot;SpellForce 2 – Shadow Wars&quot; and the add-on &quot;SpellForce 2 – Dragon Storm&quot; for a spectacular game experience!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/39550/header.jpg?t=1561968743', 0, 0, NULL);
INSERT INTO games VALUES (126774, 39560, 'Painkiller: Resurrection', 'William &quot;Bill&quot; Sherman has a problem - he''s dead. Blown to pieces by his own C4 payload, which he wanted to eliminate a South American druglord with on behalf of some shady secret service people.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/39560/header.jpg?t=1640265319', 0, 0, NULL);
INSERT INTO games VALUES (126775, 39630, 'AquaNox', 'The water is no longer calm. The undersea world has undergone a transformation from tranquil environment to a place of unspeakable violence, graphic murder and horrific danger.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/39630/header.jpg?t=1670158465', 0, 0, NULL);
INSERT INTO games VALUES (126777, 39650, 'The Guild II', 'The Guild 2 is the shining successor of the ultra successful medieval life sim, Europe 1400. The Guild 2 is a unique mixture of RPG and life simulation in an immersive middle ages scenario. The player and his party become part of history and can even change it in real-time. Go back to the dark middle ages and found a new dynasty!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/39650/header.jpg?t=1727858290', 0, 0, NULL);
INSERT INTO games VALUES (126779, 39670, 'Chaser', 'Mars, 2044. The UN establishes MARSCORP (Martian Security and Economics Committee) under the leadership of Samuel Longwood. In the years that follow, the UN gradually loses control of MARSCORP, mainly due to the non-transparent licence policy of its director.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/39670/header.jpg?t=1562768220', 0, 0, NULL);
INSERT INTO games VALUES (126780, 39680, 'The Guild II Renaissance', 'For centuries Europe has been dominated by the church and nobility. On the shoulders of ordinary people the servants of god and the noble families justified their power and wealth. This was the incontrovertible, divine world order. A truly dark era… In the 14th Century the world order is beginning to transform itself.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/39680/header.jpg?t=1727858194', 0, 0, NULL);
INSERT INTO games VALUES (126781, 39690, 'ArcaniA', 'War covers the southern islands until it finally reaches the idyllic isle of Feshyr. You take on the role as the new nameless hero after your village has been pillaged and destroyed by paladins of the king. Seeking revenge, you soon realize that this cowardly attack did not just happen on a reckless mercenary''s whim.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/39690/header.jpg?t=1662034747', 0, 0, NULL);
INSERT INTO games VALUES (126782, 39800, 'Nation Red', 'Nation Red is an ultra fast infinite play arena-based shooter providing an exceptional close-quarter battlefield experience. Fight thousands of zombie mutants and their bosses in frantic bloody gameplay while earning close to 100 perks. Fight in Barricade, Survival or Free Play mode.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/39800/header.jpg?t=1669304630', 0, 0, NULL);
INSERT INTO games VALUES (126784, 40100, 'Supreme Commander 2', 'Includes 47 Steam achievements, leaderboards, and stats!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/40100/header.jpg?t=1636731871', 0, 0, NULL);
INSERT INTO games VALUES (126750, 40300, 'Risen', 'Delve into a gritty, raw and atmospheric fantasy world in which every action has a consequence. In the epic world of Risen, filled with mysterious earthquakes, fearsome monsters and unimaginable treasures, forge your path with the sword, learn the art of staff fighting or become a powerful mage.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/40300/header.jpg?t=1674662941', 0, 0, NULL);
INSERT INTO games VALUES (126752, 40330, 'Secret Files: Tunguska', 'Unravel one of the greatest mysteries of our time! On the 30th June 1908 an explosion with the combined energy of 2000 Hiroshima bombs rocked the region of Tunguska in Central Siberia and felled over 6,000 square km of trees. The explosion could be heard from as far as 1,000km away.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/40330/header.jpg?t=1645612053', 0, 0, NULL);
INSERT INTO games VALUES (126754, 40350, 'Lost Horizon', '1936: Soldiers of the Third Reich roam the world seeking occult weapons for their insane plans of conquest. When Fenton Paddock, a former British soldier and hapless smuggler, is asked to look for his friend Richard, who went missing in Tibet, he has no idea that this search will lead him across three continents to a secret that could...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/40350/header.jpg?t=1645606288', 0, 0, NULL);
INSERT INTO games VALUES (126755, 40380, 'nail''d', 'Constant sense of ultimate speed is your only companion, and fast reflexes and tactical skills are what stands between victory and defeat. Buy before Dec. 7 10AM PST and get 10% off.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/40380/header.jpg?t=1570019041', 0, 0, NULL);
INSERT INTO games VALUES (126756, 40390, 'Risen 2: Dark Waters', 'Set several years after the end of Risen, raging titans have devastated the world and pushed humanity to the brink of existence. Subsequently, monstrous creatures have risen from the watery depths of the sea and their attacks have brought all seafaring to a grinding halt.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/40390/header.jpg?t=1601972779', 0, 0, NULL);
INSERT INTO games VALUES (126757, 40400, 'AI War: Fleet Command', '&quot;You are outgunned. You are massively outnumbered. You must win.&quot; These are your orders. Humanity has already fought its war against the machines -- and lost. AI death squads stand watch over every planet and every wormhole, the few remaining human settlements are held captive in orbiting bubbles, and the AIs have turned their...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/40400/header.jpg?t=1741478931', 0, 0, NULL);
INSERT INTO games VALUES (136173, 40700, 'Machinarium', 'Machinarium is the award-winning independent adventure game developed by the makers of Samorost series, Botanicula and CHUCHEL. Help Josef the robot save his girlfriend Berta kidnapped by the Black Cap Brotherhood gang!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/40700/header.jpg?t=1748258174', 1, 0, NULL);
INSERT INTO games VALUES (126759, 40720, 'Samorost 2', 'Samorost 2 tells a surreal story of a space gnome whose dog just got kidnapped by mischievous aliens. Set out on a short expedition to rescue the pup, deal with curious strangers and relax to the soothing music by Tomáš &quot;Floex&quot; Dvořák.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/40720/header.jpg?t=1743606005', 1, 0, NULL);
INSERT INTO games VALUES (126760, 40800, 'Super Meat Boy', 'The infamous, tough-as-nails platformer comes to Steam with a playable Head Crab character (Steam-exclusive)!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/40800/header.jpg?t=1700669950', 0, 0, NULL);
INSERT INTO games VALUES (126761, 40950, 'Stronghold HD (2012)', 'The original castle sim, Stronghold HD allows you to design, build and destroy historical castles. Engage in medieval warfare against the AI in one of two single player campaigns or online with up to 8 players.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/40950/header.jpg?t=1742480124', 0, 0, NULL);
INSERT INTO games VALUES (126762, 40960, 'Stronghold 2: Steam Edition', 'Tax, torture or treat your peasants! Rehabilitate criminals or sentence them to death? Decide as you enjoy jousting over a lavish banquet, all while under siege from the warmongering Lord Barclay.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/40960/header.jpg?t=1742482046', 0, 0, NULL);
INSERT INTO games VALUES (126763, 40970, 'Stronghold Crusader HD (2012)', 'The highly anticipated sequel to the best-selling Stronghold, Stronghold Crusader HD throws you into historic battles and castle sieges from the Crusades with fiendish AI opponents, new units, 4 historical campaigns and over 100 unique skirmish missions.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/40970/header.jpg?t=1742481898', 0, 0, NULL);
INSERT INTO games VALUES (126764, 40980, 'Stronghold Legends: Steam Edition', 'Catapult werewolves over castle walls, incinerate troops with dragon fire and command the Knights of the Round Table! This remaster of the mythical ‘castle sim’ features Steam multiplayer, Workshop support, new maps, achievements and DLC campaigns.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/40980/header.jpg?t=1742482203', 0, 0, NULL);
INSERT INTO games VALUES (126765, 41000, 'Serious Sam HD: The First Encounter', 'Serious Sam HD: The First Encounter is a visually upgraded and fully Steam supported remake version of the original high-adrenaline single-play and 16-player co-operative arcade-action FPS which was Gamespot''s Game of the Year 2001 and which scored overall of 87% on Metacritic!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/41000/header.jpg?t=1728687623', 0, 0, NULL);
INSERT INTO games VALUES (126766, 41014, 'Serious Sam HD: The Second Encounter', 'Serious Sam HD: The Second Encounter is a visually upgraded and fully Steam supported remake of the original high-adrenaline single-play and 16-player co-operative arcade-action FPS and Gamespot''s Game of the Month!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/41014/5004d7be31179bfe3e6968062b146477d58205a3/header.jpg?t=1748457295', 0, 0, NULL);
INSERT INTO games VALUES (137139, 41050, 'Serious Sam Classic: The First Encounter', 'Serious Sam is a high-adrenaline single-play and 16-player co-operative arcade-action FPS and Gamespot''s Game of the Year 2001!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/41050/header.jpg?t=1728688619', 0, 0, NULL);
