INSERT INTO games VALUES (126736, 41070, 'Serious Sam 3: BFE', 'Serious Sam 3: BFE is a prequel to the original indie fast action FPS and Game of the Year sensation - Serious Sam: The First Encounter!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/41070/header.jpg?t=1728688460', 0, 0, NULL);
INSERT INTO games VALUES (126737, 41100, 'Hammerfight', 'Hammerfight is about 2D battles of flying machines equipped with various slashing, piercing and blunt weaponry.A unique combat system is based on realistic physics simulation, and it ties the movements of the rider to the movements of your mouse. As you wave the mouse, your rider swings his warhammer, smashing the foe into the wall!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/41100/header.jpg?t=1574977946', 0, 1, NULL);
INSERT INTO games VALUES (126738, 41300, 'Altitude', 'Now Available on PC, Mac and Linux!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/41300/header.jpg?t=1721932661', 0, 1, NULL);
INSERT INTO games VALUES (126740, 41500, 'Torchlight', 'Adventure awaits in the award-winning Action RPG debut from Runic Games! Explore the randomized depths of this boom town, collect loot, and level up to save Torchlight - and possibly the world.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/41500/header.jpg?t=1712608874', 0, 0, NULL);
INSERT INTO games VALUES (126744, 41700, 'S.T.A.L.K.E.R.: Call of Pripyat', 'S.T.A.L.K.E.R.: Call of Pripyat is the direct sequel of the S.T.A.L.K.E.R.: Shadow of Chernobyl. As a Major Alexander Degtyarev you should investigate the crash of the governmental helicopters around the Zone and find out, what happened there.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/41700/header.jpg?t=1747756035', 0, 0, NULL);
INSERT INTO games VALUES (126746, 41740, 'Cargo! The Quest for Gravity', 'Create crazy, yet functional, custom vehicles to solve missions with your own unique style!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/41740/header.jpg?t=1671733324', 0, 0, NULL);
INSERT INTO games VALUES (126747, 41800, 'Gratuitous Space Battles', 'Who needs backstory? Who needs resource-gathering? Diplomacy is so last year. Gratuitous Space Battles cuts right to the chase of sci-fi strategy games, and deals with large, completely unjustified space battles between huge opposing space fleets.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/41800/header.jpg?t=1478026207', 0, 0, NULL);
INSERT INTO games VALUES (126721, 41900, 'The Bard''s Tale ARPG: Remastered and Resnarkled', 'You are the Bard, a selfish rogue weary of pointless sub-quests and rat-infested cellars. Now includes original classic games The Bard’s Tale 1, 2 &amp; 3!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/41900/header.jpg?t=1689781985', 0, 0, NULL);
INSERT INTO games VALUES (126723, 42120, 'Lead and Gold: Gangs of the Wild West', 'Lead and Gold: Gangs of the Wild West is a third-person shooter that delivers an intense team-based multiplayer experience. Relive the violent era of the Wild West with adrenaline-fueled action and fast-paced gunfights. Engage in gritty battles in beautifully rendered classic Western settings.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/42120/header.jpg?t=1729084001', 0, 0, NULL);
INSERT INTO games VALUES (126724, 42140, 'Hamilton''s Great Adventure', 'All new DLC, Retro Fever, Now Available!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/42140/header.jpg?t=1591085088', 0, 0, NULL);
INSERT INTO games VALUES (126726, 42170, 'Krater', 'The game brings you far into the future of a post-apocalyptic Sweden.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/42170/header.jpg?t=1591085012', 0, 0, NULL);
INSERT INTO games VALUES (126728, 42210, 'Nancy Drew®: Secrets Can Kill REMASTERED', 'Play the Game that Started the Award-Winning Series!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/42210/header.jpg?t=1734464188', 0, 0, NULL);
INSERT INTO games VALUES (126729, 42220, 'Nancy Drew®: The Captive Curse', 'A terrifying myth comes alive in Germany!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/42220/header.jpg?t=1734464657', 0, 0, NULL);
INSERT INTO games VALUES (126730, 42230, 'Nancy Drew®: Trail of the Twister', 'Apprehend a Saboteur Stirring up Turbulent Trouble!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/42230/header.jpg?t=1734469213', 0, 0, NULL);
INSERT INTO games VALUES (126731, 42500, 'DogFighter', 'Take to the skies in this fast paced, arcade aerial combat game featuring arena style gameplay. Fly solo in single player or compete against other players in online multiplayer modes.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/42500/header.jpg?t=1447352631', 0, 0, NULL);
INSERT INTO games VALUES (126732, 42670, 'Singularity™', 'FIGHT THE PAST TO SAVE THE FUTURE. STOP THE SINGULARITY. Learn the truth behind a massive cover-up of the catastrophic SINGULARITY, an event that fractured time and threatens the world as we know it. Armed with powerful, advanced weaponry and the experimental Time Manipulation Device, fight enemies from the past, the present, and...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/42670/header.jpg?t=1707182249', 0, 0, NULL);
INSERT INTO games VALUES (126733, 42680, 'Call of Duty®: Modern Warfare® 3 (2011)', 'The best-selling first-person action series of all-time returns with an epic sequel to the multiple GOTY award winner Call of Duty®: Modern Warfare® 2', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/115300/header.jpg?t=1692032509', 0, 0, NULL);
INSERT INTO games VALUES (132196, 42700, 'Call of Duty®: Black Ops', 'The biggest first-person action series of all time and the follow-up to critically acclaimed Call of Duty®: Modern Warfare 2 returns with Call of Duty®: Black Ops.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/42700/header.jpg?t=1748040520', 0, 0, NULL);
INSERT INTO games VALUES (126734, 42710, 'Call of Duty®: Black Ops', 'The biggest first-person action series of all time and the follow-up to critically acclaimed Call of Duty®: Modern Warfare 2 returns with Call of Duty®: Black Ops.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/42700/header.jpg?t=1748040520', 0, 0, NULL);
INSERT INTO games VALUES (126712, 42850, 'Arsenal of Democracy: A Hearts of Iron Game', 'Taking place from 1936-64, Arsenal of Democracy lets you play as any nation during the era of WW2, complete with detailed models for economics, diplomacy, research, and intelligence. Warfare is also fully represented with all three branches of operations: land, sea, and air.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/42850/header.jpg?t=1713276699', 0, 0, NULL);
INSERT INTO games VALUES (126713, 42890, 'Sword of the Stars: Complete Collection', 'Sword of the Stars: Complete Collection is the original Sword of the Stars games and the three expansions Born of Blood, A Murder of Crows and Argos Naval Yard. It is the year 2405, and human scientists have discovered a new technology that allows travel from star to star at speeds faster than light.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/42890/header.jpg?t=1710238345', 0, 0, NULL);
INSERT INTO games VALUES (126715, 42910, 'Magicka', 'Magicka is a satirical action-adventure game set in a rich fantasy world based on Norse mythology. The player assumes the role of a wizard from a sacred order tasked with stopping an evil sorcerer who has thrown the world into turmoil, his foul creations besieging the forces of good.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/42910/header.jpg?t=1726497076', 0, 0, NULL);
INSERT INTO games VALUES (126720, 42960, 'Victoria II', 'Carefully guide your nation from the era of absolute monarchies in the early 19th century, through expansion and colonization, to finally become a truly great power by the dawn of the 20th century. Victoria II is a grand strategy game played during the colonial era of the 19th century, where the player takes control of a country, guiding...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/42960/header.jpg?t=1622805098', 0, 0, NULL);
INSERT INTO games VALUES (126701, 42980, 'Victoria I Complete', 'Carefully guide your nation from the era of absolute monarchies in the early 19th century, through expansion, colonization and social upheaval, to emerge as one of the great world powers by the dawn of the 20th century in Victoria Complete.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/42980/header.jpg?t=1713346021', 0, 0, NULL);
INSERT INTO games VALUES (131895, 42990, 'Sword of the Stars II: Enhanced Edition', 'The Enhanced Edition contains Sword of the Stars II: The Lords of Winter and the first expansion, the End of Flesh. The new expansion introduces the new playable race, the Loa. All previous DLCs containing new avatars, new combat music, alternate voices, skins, and new badges for the warships are also included.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/42990/header.jpg?t=1710237755', 0, 0, NULL);
INSERT INTO games VALUES (126702, 43000, 'Front Mission Evolved', 'Experience piloting and customizing massive armored units called Wanzers while engaging in high-intensity battles driven by a compelling story. The battle begins now!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/43000/header.jpg?t=1478809109', 0, 0, NULL);
INSERT INTO games VALUES (126703, 43100, 'World of Zoo', 'What would you do if you had the keys to the zoo? World of Zoo is the only life sim game that pushes you past the fences and into a world of your own zoo. Create and customize your zoo experience and develop hands on relationships to earn the trust and love of your animals.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/43100/header.jpg?t=1732705865', 0, 0, NULL);
INSERT INTO games VALUES (126704, 43190, 'The Haunted: Hells Reach', 'Winner of 2010′s Make Something Unreal contest, The Haunted: Hells Reach is a fast-paced horror game where your goal is to liberate cursed places and survive the assault of Hell.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/43190/header.jpg?t=1678983225', 0, 0, NULL);
INSERT INTO games VALUES (126706, 43600, 'Nancy Drew®: Warnings at Waverly Academy', 'Enroll in a School Plagued by Suspicions and Lies!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/43600/header.jpg?t=1734469468', 0, 0, NULL);
INSERT INTO games VALUES (126708, 44340, 'Operation Flashpoint: Red River', 'Stand together with the US Marines in Operation Flashpoint: Red River, the ultimate tactical infantry shooter.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/44340/header.jpg?t=1573465898', 0, 0, NULL);
INSERT INTO games VALUES (126709, 44350, 'GRID 2', 'Be fast, be first and be famous as the race returns in GRID 2, the sequel to the BAFTA-award winning, multi-million selling Race Driver: GRID.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/44350/header.jpg?t=1571948291', 0, 0, NULL);
INSERT INTO games VALUES (126688, 44690, 'GT Legends', 'The golden age of motor sports has returned. Experience one of the world’s most exciting racing series in GT LEGENDS', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/44690/header.jpg?t=1478077613', 0, 0, NULL);
INSERT INTO games VALUES (126689, 45100, 'Secret of the Magic Crystals', 'In this game you manage a horse-breeding farm set in a fantasy surrounding. The game enables you to breed legendary horses such as Pegasus, Unicorn, Fire-steed, Ice-steed and Demon-steed. You can buy over 700 objects during the game. Make all kinds of horseshoes as well as lots of magical potions for your horses.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/45100/header.jpg?t=1450984857', 0, 0, NULL);
INSERT INTO games VALUES (126691, 45300, 'Wings of Prey', 'Wings of Prey is based around the large-scale aerial combat and ground military operations of World War II. Players can participate in some of the war’s most famous battles piloting fighters, battle planes and bombers across a range of thrilling missions.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/45300/header.jpg?t=1685004348', 0, 0, NULL);
INSERT INTO games VALUES (126692, 45400, 'Fortix', 'Can you reclaim your ancestors’ land? Evil forces have taken over the once fertile land of Fortiana. You are the only one who can storm the castles and claw it back from the hordes of dragons. Experience a new type of strategy and arcade game. Fence off parts of the battlefield to corner your enemies.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/45400/header.jpg?t=1447353028', 0, 0, NULL);
INSERT INTO games VALUES (126695, 45450, 'Fortix 2', 'Fortix 2 is best described as a reverse turret defense game. As Sir Fortix, the knight, you must conquer castles while dodging tower turrets and evil monsters. Fight your way across the shires of the island Artalom, storming from castle to castle.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/45450/header.jpg?t=1447354185', 0, 0, NULL);
INSERT INTO games VALUES (126696, 45720, 'Lost Planet: Extreme Condition Colonies Edition', 'Lost Planet: Extreme Condition Colonies Edition includes everything that made the original Lost Planet a hit on PC as well as adding tons of new features.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/45720/header.jpg?t=1709710947', 0, 0, NULL);
INSERT INTO games VALUES (126697, 45740, 'Dead Rising® 2', 'The sequel to the million-plus selling Dead Rising, Dead Rising 2 takes the zombie survival horror to Fortune City, America’s latest and greatest entertainment playground.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/45740/header.jpg?t=1693277199', 1, 0, NULL);
INSERT INTO games VALUES (126698, 45760, 'Ultra Street Fighter® IV', 'The world’s greatest fighting game evolves to a whole new level with Ultra Street Fighter IV.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/45760/header.jpg?t=1727684497', 1, 0, NULL);
INSERT INTO games VALUES (126699, 45770, 'Dead Rising 2: Off the Record', 'You are Frank West – photojournalist and original hero of the Dead Rising Willamette incident – taking center stage experiencing the re-imagined Fortune City outbreak.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/45770/header.jpg?t=1693277274', 1, 0, NULL);
INSERT INTO games VALUES (126656, 46250, 'NecroVisioN: Lost Company', 'NecroVisioN: Lost Company is the prequel to original horror FPS shooter, taking place before the NecroVisioN story begins. It contains a bunch of unique levels, characters, weapons and gameplay elements as well as new main hero that presents the original game story from opposite perspective.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/46250/header.jpg?t=1726487562', 0, 0, NULL);
INSERT INTO games VALUES (126657, 46260, 'Star Wolves 3: Civil War', 'Large-scale battles have become a vestige of the past, depleting resources of conflicting parties. Settled space, where welfare and order had reigned, has become a cemetery for dead ships which is flooded with pirates and adventurists.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/46260/header.jpg?t=1681218883', 0, 0, NULL);
INSERT INTO games VALUES (126658, 46270, 'Star Wolves', 'Star wolves is a 3D space RPG with deep strategy and tactical elements. The game thrusts players into a world of freelance space hunters in the XXI-XXII century A.D. during a time of political crisis for the all-powerful Empire and the three mega-corporations that control all the known worlds.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/46270/header.jpg?t=1681218789', 0, 0, NULL);
INSERT INTO games VALUES (126660, 46290, 'Theatre of War', 'Command a special task force composed of different kinds of units, including tanks, APCs, field guns, mortars, various infantry regiments and will also have an opportunity to call for artillery and air support.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/46290/header.jpg?t=1681218351', 0, 0, NULL);
INSERT INTO games VALUES (126664, 46370, 'Rig n Roll', 'Players will step into the shoes of a young man in the year 2014 as he arrives in California to pursue his dreams of road domination and capture the Californian cargo transportation market. There are miles of highways to conquer and cities and towns to reach as he becomes the greatest trucker on the highways.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/46370/header.jpg?t=1681219331', 0, 0, NULL);
INSERT INTO games VALUES (126666, 46400, 'Greed: Black Border', 'Hack ‘n slash your way through this science-fiction-themed action/RPG. In the futuristic universe of GREED, the discovery of new interstellar travel possibilities has led to a new age of colonialization. The five largest colonial powers are entangled in a full-scale war over a new element called Ikarium, the recently discovered rare...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/46400/header.jpg?t=1717596926', 0, 0, NULL);
INSERT INTO games VALUES (126667, 46410, 'Avencast: Rise of the Mage', 'Play Avencast, the epic roguelike action-RPG with tons of combat moves, spells, and equipment. Fight against evil forces to save your academy and vanquish the darkness. As you progress, learn powerful spells and combos to increase your chances of victory.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/46410/header.jpg?t=1730734617', 0, 0, NULL);
INSERT INTO games VALUES (126668, 46440, 'Future Wars', 'Battle it out on the proving grounds and get ready for Future Wars. Similar to classic titles such as Advance Wars and Battle Isle, the game takes strategy gaming away from the micro-management overkill that it has become and using simple, proven rock-paper-scissors principles, reopens the genre to everyone.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/46440/header.jpg?t=1717597161', 0, 0, NULL);
INSERT INTO games VALUES (126669, 46450, 'Grotesque Tactics: Evil Heroes', 'Grotesque Tactics is a highly addictive tactical RPG combining elements of popular Western and Asian console RPGs.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/46450/header.jpg?t=1717595888', 0, 0, NULL);
INSERT INTO games VALUES (126670, 46460, 'Scratches - Director''s Cut', 'Dark Legends surround the old abandoned Blackwood house, secluded far away in the northern wastelands. For writer Michael Arthate, this cold, solitary atmosphere is fodder for his restless imagination. But Michael soon becomes distracted by the mysteries offered up, as he follows a trail exploring and delving into the secrets of the past.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/46460/header.jpg?t=1531764133', 0, 0, NULL);
INSERT INTO games VALUES (126671, 46480, 'Still Life', 'Still Life 2 also now available!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/46480/header.jpg?t=1616086736', 0, 0, NULL);
INSERT INTO games VALUES (126672, 46490, 'Still Life 2', 'Who is hiding behind Mr. X? Still Life 2 reveals the long-awaited ending of Still Life and spells a new investigation for Agent Victoria McPherson. In Fall 2008, Victoria is sent to Maine where Ellen Dunnigan''s body has just been found.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/46490/header.jpg?t=1570009802', 0, 0, NULL);
