INSERT INTO games VALUES (126638, 46770, 'Making History II: The War of the World', 'What if Germany won the Battle of Britain? What if Moscow fell in 1942?You’re in charge. Anything can happen and history will never repeat itself in this classic WWII grand strategy game MAKING HISTORY II: The War of the World. Are you ready to battle for global dominance?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/46770/header.jpg?t=1667063397', 0, 0, NULL);
