INSERT INTO games VALUES (126635, 48110, 'Silent Hunter 5®: Battle of the Atlantic', 'Step behind the periscope of a German U-boat and take on the Allied Forces in famous battles across the vast Atlantic Ocean and Mediterranean Sea. The best-selling submarine series of all time continues with the highly anticipated Silent Hunter: Battle of the Atlantic.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/48110/header.jpg?t=1680013163', 0, 0, NULL);
INSERT INTO games VALUES (126621, 48190, 'Assassin’s Creed® Brotherhood', 'It’s time to join the Brotherhood.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/48190/header.jpg?t=1681861086', 1, 0, NULL);
INSERT INTO games VALUES (126622, 48220, 'Might & Magic: Heroes VI', 'Heroes VI is a fast-paced epic story where Angels plot to end -- once and for all -- an unfinished war with their ancient rivals, the Faceless.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/48220/header.jpg?t=1698436685', 1, 0, NULL);
