INSERT INTO games VALUES (126625, 48720, 'Mount & Blade: With Fire & Sword', 'The standalone expansion for Mount &amp; Blade! With Fire &amp; Sword builds and expands upon the highly regarded combat system from Mount &amp; Blade: Warband. Firearms have been introduced to the battlefield.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/48720/header.jpg?t=1728559305', 0, 0, NULL);
INSERT INTO games VALUES (126626, 48800, 'Ship Simulator Extremes', 'VSTEP and Paradox are proud to announce the next installment of the acclaimed Ship Simulator series. With over 550K copies sold, the series returns to take you into the most extreme conditions on earth… Ever wonder how it feels to sail a half-million-ton supertanker through the perfect storm?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/48800/header.jpg?t=1710237847', 0, 0, NULL);
