INSERT INTO games VALUES (126612, 49800, 'Flight of the Icarus', 'Flight of the Icarus is a game where you play as a privateer who owns an airship that helps ferry goods from town to town in a post-apocalyptic world where the skies are dominated by pirates and danger. Shoot down enemy aeroplanes with a variety of deadly weaponry. Keep the ship from falling out the sky.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/49800/header.jpg?t=1475862762', 0, 0, NULL);
INSERT INTO games VALUES (126614, 49900, 'Plain Sight', 'Plain Sight is a multiplayer arcade game about suicidal ninja robots. Fly through space, leap over planetoids and destroy opponents with your trusty katana. Killing fellow robots lets you steal their tasty, tasty energy. Packed with spinach-like goodness; energy makes you bigger, stronger, faster and generally more awesome.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/49900/header.jpg?t=1741795243', 0, 1, NULL);
INSERT INTO games VALUES (126615, 50000, 'Nimbus', 'Nimbus is a unique combination of racing & puzzling. The player controls a craft with no means of directly propelling itself and needs to use whatever is scattered around the levels to acquire thrust and reach the goal. Traverse a world map with several distinct islands in order to recover your lost love.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/50000/header.jpg?t=1447353658', 0, 0, NULL);
INSERT INTO games VALUES (126609, 50130, 'Mafia II (Classic)', 'Vito Scaletta has started to make a name for himself on the streets of Empire Bay as someone who can be trusted to get a job done. Together with his buddy Joe, he is working to prove himself to the Mafia, quickly escalating up the family ladder with crimes of larger reward, status and consequence… the life as a wise guy isn’t quite as...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/50130/header.jpg?t=1746717708', 0, 0, NULL);
INSERT INTO games VALUES (126601, 50620, 'Darksiders™', 'Deceived by the forces of evil into prematurely bringing about the end of the world, War – the first Horseman of the Apocalypse – stands accused of breaking the sacred law by inciting a war between Heaven and Hell. In the slaughter that ensued, the demonic forces defeated the heavenly hosts and laid claim to the Earth.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/50620/header.jpg?t=1732172873', 0, 0, NULL);
INSERT INTO games VALUES (126588, 50990, 'Mystery Case Files: Ravenhearst®', 'Rumors surrounding the history of stately Ravenhearst Manor have circulated for decades. The recently acquired diary of Emma Ravenhearst may hold the key to unraveling the tale behind this unsettling place, yet the pages are missing.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/50990/header.jpg?t=1629483295', 0, 0, NULL);
INSERT INTO games VALUES (130653, 51000, 'Mystery Case Files: Return to Ravenhearst™', 'Emma''s soul is free. But her ghost has delivered a dire warning: evil still lurks in Ravenhearst Manor. Big Fish Games Studios takes you deep inside the cursed estate in Mystery Case Files: Return to Ravenhearst™, the thrilling sequel.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/51000/header.jpg?t=1629483369', 0, 0, NULL);
INSERT INTO games VALUES (126589, 51010, 'My Tribe', 'Create a prosperous island paradise for your industrious, intelligent tribe with this real-time Brain Teaser! Your tribe will have a mind of its own, learning skills and starting families even when you''re not around, but check back often to keep your island idyllic.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/51010/header.jpg?t=1478298384', 0, 0, NULL);
INSERT INTO games VALUES (126592, 51060, 'Drawn®: The Painted Tower', 'Enter the world of Drawn, and unravel the secrets of the Painted Tower. Overcome challenging puzzles on your quest to save Iris. A curse has locked each floor of the tower, and only the most creative adventurer can find a way through.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/51060/header.jpg?t=1531436636', 0, 0, NULL);
