INSERT INTO games VALUES (126597, 55110, 'Red Faction®: Armageddon™', 'Red Faction: Armageddon Path to War includes 4 new missions, 2 unlockable items and 10 new achievements!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/55110/header.jpg?t=1591105530', 0, 0, NULL);
