INSERT INTO games VALUES (59036, 222640, 'Aarklash: Legacy', 'In Aarklash: Legacy take command of a mercenary squad in search of truth and guide it through countless battles.Welcome to Aarklash, a land of chaos where incessant battles between the forces of Light, Destiny and Darkness have lasted since the beginning of time.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/222640/header.jpg?t=1725289395', 0, 0, NULL);
INSERT INTO games VALUES (59037, 222660, 'Retro/Grade', 'Play a classic Shoot ''Em Up... in reverse!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/222660/header.jpg?t=1447356820', 0, 0, NULL);
INSERT INTO games VALUES (59026, 222730, 'Reus', 'In Reus, you control powerful giants to shape the planet to your will. You can create mountains, oceans, forests and more. Enrich your planet with plants, minerals and animal life. There is only one thing on the planet that you do not control: mankind, with all their virtues and and all their vices.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/222730/header.jpg?t=1730204355', 0, 0, NULL);
INSERT INTO games VALUES (59027, 222750, 'Wargame: Airland Battle', '2 SIDES, 12 NATIONS, 750 UNITS: THE STRATEGY GAME REFERENCE IS BACK! Richer, more beautiful and more accessible, Wargame AirLand Battle is the sequel to the explosive real-time strategy game Wargame European Escalation! 1985.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/222750/header.jpg?t=1639653297', 0, 0, NULL);
INSERT INTO games VALUES (59029, 222880, 'Insurgency', 'Take to the streets for intense close quarters combat, where a team''s survival depends upon securing crucial strongholds and destroying enemy supply in this multiplayer and cooperative Source Engine based experience.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/222880/header.jpg?t=1610560212', 0, 0, NULL);
INSERT INTO games VALUES (59030, 222980, 'Dead Pixels', 'A toxic waste spill finds its way into the water supply, causing the recently deceased to rise from their graves. Now it''s up to you to blast your way through the hordes of undead if you''re going to escape the city. On the way to your rescue, you''ll search stores and houses for supplies, and trade with other survivors.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/222980/header.jpg?t=1744651097', 0, 0, NULL);
INSERT INTO games VALUES (59032, 223100, 'Homefront®: The Revolution', 'Homefront®: The Revolution is an open-world first person shooter where you must lead the Resistance movement in guerrilla warfare against a superior military force.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/223100/header.jpg?t=1614763860', 0, 0, NULL);
INSERT INTO games VALUES (59033, 223220, 'Giana Sisters: Twisted Dreams', 'Giana Sisters: Twisted Dreams is a blistering hardcore platformer with contrasting worlds.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/223220/header.jpg?t=1744278700', 0, 0, NULL);
INSERT INTO games VALUES (59017, 223330, 'Sea Dogs: To Each His Own', '1654 AC. The Caribbean. A place of opportunities and mysteries.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/223330/header.jpg?t=1698397841', 0, 0, NULL);
INSERT INTO games VALUES (59018, 223410, 'Perpetuum', 'Perpetuum is a persistent, sandbox, single server, massively multiplayer sci-fi rpg (MMORPG). Control huge robots and mechs to gain access to an alien planet''s resources and knowledge, amass huge wealth, or even claim part of the world for yourself using terraforming and complex infrastructure.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/223410/header.jpg?t=1667059829', 0, 1, NULL);
INSERT INTO games VALUES (59019, 223430, 'Miner Wars 2081', 'Operate an advanced mining ship in a fully destructible and open-world environment!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/223430/header.jpg?t=1727771176', 0, 0, NULL);
INSERT INTO games VALUES (59020, 223450, 'Dyad', 'Experience a mind-bending, psychedelic sensory overload in Dyad! Blast through a reactive audio-visual tube creating a harmonious synthesis of color and sound as you Hook, Graze, and Lance enemies to master Dyad''s 27 unique levels.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/223450/header.jpg?t=1447356874', 0, 0, NULL);
INSERT INTO games VALUES (59021, 223470, 'POSTAL 2', 'Live a week in the life of &quot;The POSTAL Dude&quot;; a hapless everyman just trying to check off some chores. Buying milk, returning an overdue library book, getting Gary Coleman''s autograph, what could possibly go wrong?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/223470/header.jpg?t=1726251082', 0, 0, NULL);
INSERT INTO games VALUES (59022, 223490, 'Blockscape', 'The ultimate block building game.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/223490/header.jpg?t=1716822216', 0, 0, NULL);
INSERT INTO games VALUES (59023, 223510, 'Miasmata', 'Miasmata is a first-person survival/adventure game, developed from the ground-up by brothers Joe and Bob Johnson. You play as Robert Hughes, a plague-stricken scientist on a journey to discover a cure. Your adventure begins on the shores of a remote and mysterious island.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/223510/header.jpg?t=1447356877', 0, 0, NULL);
INSERT INTO games VALUES (59024, 223630, 'AirBuccaneers', 'Welcome to the ancient North, once the cradle of culture and peace, but is now corrupted by magic and inhabited by nasty bandits sowing destruction in airships.Choose to be a vicious Buccaneer or an infamous Viking and take a glider to the skies. Your goal is to drop enemy vessels and secure dominance of the ancient North.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/223630/header.jpg?t=1447356882', 0, 1, NULL);
INSERT INTO games VALUES (59025, 223710, 'Cry of Fear', 'Cry of Fear is a psychological single-player and co-op horror game set in a deserted town filled with horrific creatures and nightmarish delusions. You play as a young man desperately searching for answers in the cold Scandinavian night, finding his way through the city as he slowly descends into madness.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/223710/header.jpg?t=1643567513', 0, 1, NULL);
INSERT INTO games VALUES (59011, 223730, 'Fly''N', 'Somewhere between a platformer, a puzzle game and a great big dollop of pure fun, Fly’N will challenge your skills through more than forty levels set in a luxuriant world. Experiment with the four Buds to save the World-Trees from Dyer, the loony hair-dryer who intends to destroy their Helys!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/223730/header.jpg?t=1737558683', 0, 0, NULL);
INSERT INTO games VALUES (132735, 223750, 'DCS World Steam Edition', 'Feel the excitement of flying the Su-25T &quot;Frogfoot&quot; attack jet and the TF-51D &quot;Mustang&quot; in the free-to-play Digital Combat Simulator World!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/223750/header.jpg?t=1745509192', 0, 1, NULL);
INSERT INTO games VALUES (59012, 223810, 'Ys I & II Chronicles+', 'Long, long ago, there was an ancient kingdom called Ys which prospered under the auspices of two heavenly Goddesses. Over time, the kingdom came to be known as Esteria, and its divine history was largely forgotten by all but the descendants of those who once preached the Goddesses’ will.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/223810/header.jpg?t=1740512356', 0, 0, NULL);
INSERT INTO games VALUES (59013, 223830, 'Xenonauts', 'Xenonauts is a strategy game in which you control a multi-national military organisation defending a Cold War-era Earth from alien invasion, using small squads of persistent soldiers to eliminate the extraterrestrials and recover their technology in turn-based ground combat.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/223830/header.jpg?t=1673967760', 0, 0, NULL);
INSERT INTO games VALUES (128208, 223850, '3DMark', '3DMark is for gamers, overclockers and system builders who want to get more out of their hardware. With its wide range of benchmark tests, 3DMark has everything you need to test your PC''s performance.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/223850/header.jpg?t=1737967093', 1, 0, NULL);
INSERT INTO games VALUES (59014, 223870, 'Ys I & II Chronicles+', 'Long, long ago, there was an ancient kingdom called Ys which prospered under the auspices of two heavenly Goddesses. Over time, the kingdom came to be known as Esteria, and its divine history was largely forgotten by all but the descendants of those who once preached the Goddesses’ will.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/223810/header.jpg?t=1740512356', 0, 0, NULL);
INSERT INTO games VALUES (59016, 224040, 'LocoCycle', 'Newly self-aware, I.R.I.S. the martial-arts wielding assassin motorcycle, has begun a cross-continent escape to freedom. I.R.I.S.’s only ally is her engineer Pablo, who gets conscripted into the quest after his pant leg gets caught in her chassis. Hunted by the psychopathic motorcycle S.P.I.K.E. and a multinational weapons cartel, I.R.I.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/224040/header.jpg?t=1667851212', 0, 0, NULL);
INSERT INTO games VALUES (59001, 224260, 'No More Room in Hell', 'The chances of you surviving this all out war of society and the undead are slim to none. Already, there are millions of the walking dead shambling about, searching for food to eat. There''s no known cure. One bite can possibly end it all for you. However, you aren''t alone in this nightmare.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/224260/header.jpg?t=1696263772', 1, 1, NULL);
INSERT INTO games VALUES (59003, 224300, 'Legacy of Kain: Defiance', 'Take control of two powerful and highly evolved vampires: Kain, an all-powerful demigod, and Raziel, a demonic angel of death. Each equipped with a legendary sword, Kain &amp; Raziel must battle through a world loaded with conflict and intrigue as they attempt to unravel their destinies and defeat the dark forces that seek to condemn...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/224300/header.jpg?t=1727994013', 0, 0, NULL);
INSERT INTO games VALUES (59004, 224460, 'Contrast', 'CONTRAST is a puzzle/platform game where you can move between a fantastic 3D world and a mysterious shadowy universe in 2D in the blink of an eye. Delve into a dreamlike and surreal 1920s world, inspired by the performance art world of vaudeville and film noir, and cradled by a smooth and sultry jazz ambiance.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/224460/header.jpg?t=1697238477', 0, 0, NULL);
INSERT INTO games VALUES (59005, 224480, 'Octodad: Dadliest Catch', 'Octodad: Dadliest Catch is a game about destruction, deception, and fatherhood. The player controls Octodad, a dapper octopus masquerading as a human, as he goes about his life. Octodad''s existence is a constant struggle, as he must master mundane tasks with his unwieldy boneless tentacles while simultaneously keeping his cephalopodan...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/224480/header.jpg?t=1748894325', 1, 0, NULL);
INSERT INTO games VALUES (59006, 224500, 'Gnomoria', 'Gnomoria is a sandbox village management game where you help lead a small group of gnomes, who have set out on their own, to thrive into a bustling kingdom! Anything you see can be broken down and rebuilt elsewhere.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/224500/header.jpg?t=1456262462', 0, 0, NULL);
INSERT INTO games VALUES (59007, 224740, 'Clockwork Empires', 'Take on the role of a Colonial Bureaucrat sent forth by the Clockwork Empire to build a Frontier Colony. Design houses &amp; workshops to feed the Ravenous Maw of Industry, manage a uniquely unruly population, avoid cannibalism &amp; monsters, and make Important Decisions for the glory of the Empire!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/224740/header.jpg?t=1557750612', 0, 0, NULL);
INSERT INTO games VALUES (59008, 224760, 'FEZ', 'Gomez is a 2D creature living in a 2D world. Or is he? When the existence of a mysterious 3rd dimension is revealed to him, Gomez is sent out on a journey that will take him to the very end of time and space. Use your ability to navigate 3D structures from 4 distinct classic 2D perspectives.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/224760/header.jpg?t=1572375251', 1, 0, NULL);
INSERT INTO games VALUES (59009, 224820, 'Super House of Dead Ninjas', 'Super House of Dead Ninjas is an action arcade game with roguelite elements. Race against a 30 second timer as you descend floor after foe-filled floor and attempt to unlock the secrets of this deadly tower!Play as the fearsome Crimson Ninja, wielding an arsenal of deadly ninja weapons and attacks.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/224820/header.jpg?t=1733239240', 0, 0, NULL);
INSERT INTO games VALUES (59010, 224860, 'Arma Tactics', 'Arma Tactics is a turn-based close-combat strategy game, where you take control of a four-member Special Forces team. There are no given strategies, rails to move on, or paths to follow; it‘s up to you to decide how you will play through both the story-driven missions and generated missions with randomized objectives.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/224860/header.jpg?t=1748872803', 0, 0, NULL);
INSERT INTO games VALUES (58986, 224940, 'Legacy of Kain: Soul Reaver 2 (2001)', 'In this sequel to the critically acclaimed Legacy of Kain: Soul Reaver, reassume the role of Raziel, and travel back through the currents of time into various eras of Nosgoth''s past in your relentless pursuit of Kain.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/224940/header.jpg?t=1727994086', 0, 0, NULL);
INSERT INTO games VALUES (58987, 224960, 'Tomb Raider I (1996)', 'Adventurer Lara Croft has been hired to recover the pieces of an ancient artifact known as the Scion. With her fearless acrobatic style she runs, jumps, swims and climbs her way towards the truth of its origin and powers - leaving only a trail of empty tombs and gun-cartridges in her wake.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/224960/header.jpg?t=1729009969', 0, 0, NULL);
INSERT INTO games VALUES (58988, 224980, 'Tomb Raider IV: The Last Revelation (1999)', 'According to Egyptian legend, Horus, son of the light, outwitted the evil God Set and imprisoned him in a secret tomb. Five thousand years later, Lara Croft discovers the lost tomb and unwittingly unleashes the evil God Set, fulfilling the ancient prophecy of his return to plunge mankind into darkness!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/224980/header.jpg?t=1729010052', 0, 0, NULL);
INSERT INTO games VALUES (58989, 225000, 'Tomb Raider V: Chronicles (2000)', 'Lara Croft is missing in Egypt - presumed dead. Those closest to her gather together at the Croft Estate on a grey, rainy day for a memorial service in her honour. Afterwards, the friends sit quietly together in the study of the Croft Mansion and reminisce about Lara''s past exploits; exploits that have until now remained a secret..', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/225000/header.jpg?t=1729010120', 0, 0, NULL);
INSERT INTO games VALUES (58990, 225020, 'Tomb Raider VI: The Angel of Darkness (2003)', 'A series of grisly murders brings Lara into conflict with a sinister Alchemist from the past, and a secret alliance of powerful individuals shrouded in mystery. Accused of the murder of her one time mentor, Werner Von Croy, Lara becomes a fugitive on the run.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/225020/header.jpg?t=1729010145', 0, 0, NULL);
INSERT INTO games VALUES (58991, 225080, 'Brothers - A Tale of Two Sons', 'Guide two brothers on an epic fairy tale journey from visionary Swedish film director, Josef Fares and top-tier developer Starbreeze Studios. Control both brothers at once as you experience co-op play in single player mode, like never before.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/225080/header.jpg?t=1725036160', 0, 0, NULL);
INSERT INTO games VALUES (58992, 225160, 'Shadow Warrior Classic Redux', 'The definitive version of the cult classic shooter, Shadow Warrior Classic Redux features remastered visuals and two massive expansion packs. Corporations rule every facet of life in a near-future Japan and employ Shadow Warriors, one-man armies of unparalleled skill, to protect their power and forcefully remove all opposition.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/225160/header.jpg?t=1706008342', 0, 0, NULL);
INSERT INTO games VALUES (58993, 225260, 'Brutal Legend', 'Brütal Legend is an action-adventure that marries visceral action combat with open-world freedom. Set in a universe somewhere between Lord of the Rings and Spinal Tap, it’s a fresh take on the action/driving genre, which in this case is full of imitation cover bands, demons intent on enslaving humanity and Heavy metal tunes.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/225260/header.jpg?t=1731601676', 0, 0, NULL);
INSERT INTO games VALUES (58994, 225280, 'Full Mojo Rampage', 'Full Mojo Rampage is a rogue-like game that takes place within the confines of the Voodoo reality. In this realm only the most powerful rites and powers can provide a safeguard against evil. Dying is not the end, only the beginning to becoming a stronger voodoo soul!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/225280/header.jpg?t=1667058295', 0, 0, NULL);
INSERT INTO games VALUES (58995, 225300, 'Tomb Raider II (1997)', 'The second instalment in the Tomb Raider series invites you to join Lara as she travels around the globe to retrieve a precious artefact before it falls into the wrong hands. The legendary artefact, the Dagger of Xian, is said to give its possessor the power of a fire breathing dragon.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/225300/header.jpg?t=1729010173', 0, 0, NULL);
INSERT INTO games VALUES (58996, 225320, 'Tomb Raider III (1998)', 'Thousands of years ago a meteor crashed into Antarctica and the shockwaves of its impact are being felt in the modern age. Lara Croft will follow clues leading to a deadly secret, boldly leaping chasms and blasting monsters that no one has leaped or blasted before. This time she faces a mystery that''s from way out of this world.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/225320/header.jpg?t=1729010354', 0, 0, NULL);
INSERT INTO games VALUES (58997, 225360, 'DARK', 'DARK is a unique stealth-action game with RPG elements in which you take on the role of the ultimate hunter: a vampire. Ambush your enemies from the shadows, roam the darkness and use powerful vampire skills to dispatch your opponents.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/225360/header.jpg?t=1730283377', 0, 0, NULL);
INSERT INTO games VALUES (58998, 225420, 'Cities in Motion 2', 'Cities in Motion 2 is the sequel to the popular mass transit simulation game Cities in Motion. Build, manage and lead your transportation network to provide cities with their ever changing needs. CIM2 introduces new features including multiplayer game modes, day and night cycles, timetables and dynamic cities.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/225420/header.jpg?t=1726497191', 0, 0, NULL);
INSERT INTO games VALUES (58999, 225540, 'Just Cause™ 3', 'With over 1000 km² of complete freedom from sky to seabed, Rico Rodriguez returns to unleash chaos in the most creative and explosive ways imaginable.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/225540/header.jpg?t=1728396027', 0, 0, NULL);
INSERT INTO games VALUES (59000, 225600, 'Blade Symphony', 'Prove you are the world''s greatest swordsman! Engage in tactical 1 vs. 1 sword fighting, 2 vs. 2, or sandbox FFA, or capture Control Points in a tactical slash-em-up.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/225600/header.jpg?t=1678231957', 1, 1, NULL);
INSERT INTO games VALUES (58983, 225640, 'Sacred 2 Gold', 'Experience the world of Ancaria in its full glory with Sacred 2: Gold Edition. Containing Sacred 2 Fallen Angel and the awesome add-on Ice and Blood. Defeat countless dangerous enemies; capture powerful weapons and valuable treasures. Prepare yourself for the ultimate battle and become a legend.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/225640/header.jpg?t=1641301466', 0, 0, NULL);
INSERT INTO games VALUES (58984, 225840, 'Sven Co-op', 'Sven Co-op is a co-operative game originally based around Valve Software''s Half-Life. In this game players must work together against computer controlled enemies and solve puzzles as a team.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/225840/header.jpg?t=1735034103', 0, 1, NULL);
INSERT INTO games VALUES (58985, 226120, 'Weird Worlds: Return to Infinite Space', 'Weird Worlds: Return to Infinite Space is a hybrid roguelike game of space exploration, adventure and starship combat.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/226120/header.jpg?t=1748130105', 0, 0, NULL);
INSERT INTO games VALUES (58972, 226560, 'Escape Dead Island', 'Escape Dead Island is a Survival-Mystery adventure that lets players delve into the Dead Island universe and unravel the origins of the zombie outbreak.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/226560/header.jpg?t=1669391222', 0, 0, NULL);
INSERT INTO games VALUES (58973, 226620, 'Desktop Dungeons', 'Each step into the unknown heals you and reveals new obstacles as you guide fresh heros to glorious retirement or ignominious death. Master tactical spells, appease ancient gods and get rich through taxidermy in this award-winning quick-play puzzle-roguelike.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/226620/header.jpg?t=1681842667', 0, 0, NULL);
INSERT INTO games VALUES (58974, 226700, 'Infestation: The New Beginning', 'Infestation is a Survival Horror MMO that immerses players in a zombie-infested, post-apocalyptic world in which a viral outbreak has decimated the human population leaving in its wake, a nightmare of epic proportion.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/226700/header.jpg?t=1732532491', 0, 1, NULL);
INSERT INTO games VALUES (58975, 226720, 'LOST PLANET® 3', 'The extreme and unpredictable conditions that characterized the Lost Planet series return, harsher than ever before. Lost Planet 3 reveals new truths about the foreboding planet and the colonial history of E.D.N. III.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/226720/header.jpg?t=1644283090', 0, 0, NULL);
INSERT INTO games VALUES (58976, 226740, 'Monster Loves You!', 'Live the life of a Monster, from birth to elderhood and beyond, making decisions that affect the world of Monsters and Humans. Solve problems. Meet animals and interesting people. Get to know them. Eat them. Make your own story!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/226740/header.jpg?t=1701881262', 0, 0, NULL);
INSERT INTO games VALUES (58978, 226820, 'Nancy Drew®: Ghost of Thornton Hall', 'Some Families Keep Deadly Secrets!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/226820/header.jpg?t=1734461287', 0, 0, NULL);
INSERT INTO games VALUES (58979, 226840, 'Age of Wonders III', 'Age of Wonders III is the long anticipated sequel to the award-winning strategy series. Delivering a unique mix of Empire Building, Role Playing and Warfare, Age of Wonders III offers the ultimate in turn-based fantasy strategy for veterans of the series and new players alike!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/226840/header.jpg?t=1726491137', 0, 0, NULL);
INSERT INTO games VALUES (58980, 226860, 'Galactic Civilizations III', 'Build a civilization that will stand the test of time in the largest space-based strategy game ever! Choose from dozens of unique races and make a name for yourself across the galaxy through diplomacy, espionage, technological advances, and more.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/226860/header.jpg?t=1747329377', 0, 0, NULL);
INSERT INTO games VALUES (58981, 226960, 'Ironclad Tactics', 'Ironclad Tactics is a fast-paced, card-based tactics game set in an alternate history Civil War - with steam-powered military robots!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/226960/header.jpg?t=1667071144', 0, 0, NULL);
INSERT INTO games VALUES (58959, 227000, 'Primordia', 'Life has ceased. Man is but a myth. And now, even the machines have begun to fail. Lead Horatio Nullbuilt and his sarcastic sidekick Crispin on a journey through the crumbling world of Primordia, facing malfunctioning robots, ancient secrets, and an implacable, power-hungry foe.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/227000/header.jpg?t=1728038162', 0, 0, NULL);
INSERT INTO games VALUES (58960, 227020, 'Rise of Venice', 'Venice: As a young man striving for success, power and wealth and with the support of your family, you begin to build up a trading empire across Genua, Tripoli, Rome, Alexandria and Constantinople in addition to many other significant cities from the Renaissance. This is where your story begins...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/227020/header.jpg?t=1730301519', 1, 0, NULL);
INSERT INTO games VALUES (58961, 227060, 'Hegemony Rome: The Rise of Caesar', 'Hegemony Rome: The Rise of Caesar takes you to the plains and forests of ancient Gaul where Julius Caesar wages a decade long war to subjugate the barbarian hordes. Hegemony Rome will immerse you in the history like no other real time strategy game ever before, forcing you to pay close attention to the changing seasons and rapidly...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/227060/header.jpg?t=1570501634', 1, 0, NULL);
INSERT INTO games VALUES (58962, 227080, 'Papo & Yo', 'Quico’s best friend, Monster, is a huge beast with razor-sharp teeth, but that doesn’t scare Quico away from playing with him. That said, Monster does have a very dangerous problem: an addiction to poisonous frogs.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/227080/header.jpg?t=1616766842', 0, 0, NULL);
INSERT INTO games VALUES (58963, 227100, 'Sniper Elite: Nazi Zombie Army', '** Please note: a remastered and improved edition of this game is now available in Zombie Army Trilogy.**Featuring a co-op campaign for 1 to 4 players, Nazi Zombie Army is a horrifying new stand-alone expansion of the award-winning Sniper Elite series.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/227100/header.jpg?t=1589878229', 0, 0, NULL);
INSERT INTO games VALUES (58964, 227160, 'Kinetic Void', 'Kinetic Void is a 3D space adventure with a focus on customization and enjoyable space simulation. The shipyard allows players to construct their ship piece by piece. Ships can be as simplistic as a cockpit, a hull, a engine and a gun, or as complex as a player wants.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/227160/header.jpg?t=1447357131', 0, 0, NULL);
INSERT INTO games VALUES (58965, 227180, 'Kingdom Wars', 'Kingdom Wars is a free to play 3D MMORTS with real-time siege combat, without the pay to win element so common in the genre. Kingdom Wars offers beautiful 3D online world, where players construct strongholds, direct citizens, complete quests and eventually manage a global empire.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/227180/header.jpg?t=1506091554', 0, 1, NULL);
INSERT INTO games VALUES (58966, 227200, 'Waking Mars', 'In 2097, life is discovered on Mars. When your mission of first contact becomes trapped by a cave-in, you must master the alien ecosystem to survive. Soon you stumble upon more than anyone expected, and with time running out, you will make a decision that determines the fate of a lost planet.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/227200/header.jpg?t=1447357132', 0, 0, NULL);
INSERT INTO games VALUES (58967, 227220, 'Sang-Froid - Tales of Werewolves', 'Combining action and strategy in a unique way, Sang-Froid: Tales of Werewolves transports you into an epic folktale co-written with best-selling Canadian author Bryan Perro (Amos Daragon, Wariwulf), in which two feuding brothers will have to put aside their differences to save their sister, who is pursued by the Devil himself!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/227220/header.jpg?t=1726588248', 0, 1, NULL);
INSERT INTO games VALUES (58968, 227260, 'DisplayFusion', 'DisplayFusion will make your multi-monitor life much easier! With powerful features like Multi-Monitor Taskbars, TitleBar Buttons, Monitor Fading, and fully customizable HotKeys, DisplayFusion will make managing your multiple monitors easy.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/227260/header.jpg?t=1683646404', 1, 0, NULL);
INSERT INTO games VALUES (58969, 227300, 'Euro Truck Simulator 2', 'Travel across Europe as king of the road, a trucker who delivers important cargo across impressive distances! With dozens of cities to explore, your endurance, skill and speed will all be pushed to their limits.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/227300/header.jpg?t=1739871676', 1, 0, NULL);
INSERT INTO games VALUES (58970, 227380, 'Dragon''s Lair', 'Haven''t heard of Dragon''s Lair?! Well, you play the heroic Dirk the Daring, a valiant knight on a quest to rescue the fair princess from the clutches of an evil dragon! Originally released in the summer of 1983, Dragon''s Lair has solidified itself as a cultural icon in gaming.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/227380/header.jpg?t=1709672143', 0, 0, NULL);
INSERT INTO games VALUES (58971, 227560, 'Scourge: Outbreak', 'Blast your way through Nogari Island as Echo Squad. Utilize a devastating array of weapons and special abilities to crush everything that stands in your way. Features a fully Co-op enabled Campaign for up to 4 Players, as well as a variety of 8 Player Versus multiplayer modes!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/227560/header.jpg?t=1478162856', 0, 0, NULL);
INSERT INTO games VALUES (58950, 227580, '10,000,000', '10000000: The Dungeon Crawling Matching Game', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/227580/header.jpg?t=1572970613', 1, 0, NULL);
INSERT INTO games VALUES (58951, 227600, 'Castle of Illusion', 'Mickey Mouse returns to star in Castle of Illusion, a fantastical reimagining of the Sega Genesis classic.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/227600/header.jpg?t=1625781778', 0, 0, NULL);
INSERT INTO games VALUES (58952, 227760, 'March of the Eagles', '“he Who Fears Being Conquered Is Sure Of Defeat.”The war-game March of the Eagles focuses on the dramatic conflicts of Europe during 1805 to 1820. Explore one of the defining periods in European history with this experience crafted by the masters of Grand Strategy, Paradox Development Studio.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/227760/header.jpg?t=1709828629', 0, 0, NULL);
INSERT INTO games VALUES (58953, 227780, 'Serious Sam Classics: Revolution', 'Serious Sam is a high-adrenaline arcade-action shooter heavily focused on frantic action. In a world where cyberpunk meets fantasy-fiction and advanced technology is mixed with black magic and psycho-powers, Sam travels through four beautiful worlds, confronting countless foes on his way to Mental''s base.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/227780/header.jpg?t=1582213660', 0, 0, NULL);
INSERT INTO games VALUES (58954, 227860, 'Castle Story', 'Castle Story is a creative voxel-based strategy game in which you can build castles one brick at a time using an army of little creatures called Bricktrons. Design and build your own castles, expand your territory in a vast landscape and defend your Bricktrons against onslaughts of hostile creatures.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/227860/header.jpg?t=1667578994', 0, 0, NULL);
INSERT INTO games VALUES (58955, 228180, 'Action! - Gameplay Recording and Streaming', 'With Action! you can record and live stream your HD/4K/HDR10/8K gameplay, display game''s fps, add webcams, live audio commentary, add streaming overlays such as chatbox, alert box, monitor the status of your recording and streaming, benchmark your computer and more!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/228180/header.jpg?t=1671703021', 1, 0, NULL);
INSERT INTO games VALUES (58956, 228260, 'Fallen Enchantress: Legendary Heroes', 'Fallen Enchantress is 4X strategy game from the makers of Sins of a Solar Empire and Galactic Civilizations. Build a civilization in the magical world of Elemental. Recruit heroes, train armies, build cities, forge alliances and save the world in this rich world where it''s never the same game twice.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/228260/header.jpg?t=1741098726', 0, 0, NULL);
INSERT INTO games VALUES (58957, 228280, 'Baldur''s Gate: Enhanced Edition', 'The classic adventure returns! Baldur’s Gate: Enhanced Edition includes the original Baldur’s Gate adventure, the Tales of the Sword Coast expansion, and all-new content including three new party members.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/228280/header.jpg?t=1746198680', 1, 0, NULL);
INSERT INTO games VALUES (58945, 228380, 'Wreckfest', 'Wreckfest is a demolition derby themed racing game with soft-body damage modeling, sophisticated driving dynamics and in-depth vehicle upgrading, featuring both demolition derbies and more traditional track races. It’s all about fun, breakneck racing and over-the-top crashes.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/228380/header.jpg?t=1742490584', 1, 0, NULL);
INSERT INTO games VALUES (58946, 228400, 'Ace Combat Assault Horizon - Enhanced Edition', 'Never before has combat been so fast in-your-face.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/228400/header.jpg?t=1655312069', 0, 0, NULL);
INSERT INTO games VALUES (58948, 228760, 'TrackMania² Canyon', 'TrackMania² Canyon will let you experience the fun and adrenaline of racing stunning cars on sensational tracks in a major enhanced sequel to Nadeo Studio’s online racing phenomenon TrackMania, already enjoyed by millions of players.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/228760/header.jpg?t=1680016448', 1, 0, NULL);
INSERT INTO games VALUES (58949, 228960, 'Skulls of the Shogun', 'Enter the Samurai Afterlife and join forces with vibrant ghost-samurai warriors, magical animal monks, and mustachioed samurai generals. It''s fast-paced turn-based strategy inspired by Advance Wars, and supercharged with fighting-game flare!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/228960/header.jpg?t=1638440485', 1, 0, NULL);
INSERT INTO games VALUES (58940, 229480, 'Dungeons & Dragons: Chronicles of Mystara', 'Dungeons &amp; Dragons: Chronicles of Mystara brings reworkings of two of Capcom’s classic arcade hits - Dungeons &amp; Dragons: Tower of Doom and Dungeons &amp; Dragons: Shadow over Mystara – together in one definitive digital package.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/229480/header.jpg?t=1644219327', 0, 0, NULL);
INSERT INTO games VALUES (58941, 229520, 'Dungeon Hearts', 'Dungeon Hearts fuses the strategy and pattern matching of puzzle games with the kinetic pace of action games. Align magical runes as they flow along the Fatestream to attack, defend, and conjure magic in frenetic battles against a bestiary of fantastic creatures out to use those same runes against you.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/229520/header.jpg?t=1447357261', 0, 0, NULL);
INSERT INTO games VALUES (58943, 229580, 'Dream', 'Dream is an exploration game that takes place within the subconscious mind of Howard Phillips, a young man whose waking hours are tedious and dull, but whose dreams are lucid and powerful.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/229580/header.jpg?t=1568743684', 0, 0, NULL);
INSERT INTO games VALUES (58944, 229600, 'Bientôt l''été', 'Bientôt l’été is a videogame for two players. Two players who pretend to be lovers. They pretend to be lovers separated from each other by lightyears of deep space. They have lonely walks along the shore of a simulated ocean, thinking wistful thoughts of each other. Thoughts from ancient Earth literature by Marguerite Duras.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/229600/header.jpg?t=1667028919', 0, 0, NULL);
INSERT INTO games VALUES (58932, 229870, 'ShootMania Storm', 'ShootMania the FPS “Powered By Players”ShootMania Storm is revolutionizing the multiplayer FPS by adding a community dimension and unlimited replayability. Developed by the Nadeo studio, renowned for community racing game, TrackMania, ShootMania Storm boasts quick-fire matches and epic battles, where only your talent will distinguish you...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/229870/header.jpg?t=1680013045', 0, 0, NULL);
INSERT INTO games VALUES (58936, 230050, 'DLC Quest', 'What happens when DLC practices go too far? An indie developer makes a game that mocks the industry and its foibles, that''s what! Defeat the bad guy, save the world and get the girl! But first you''ll need to find coins to buy DLC to enable animation, sound and even pausing.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/230050/header.jpg?t=1668113649', 0, 0, NULL);
INSERT INTO games VALUES (58937, 230150, 'Incredipede', 'Grow arms and legs to transform into a snake, spider, butterfly, or fifty-legged horror - anything you can imagine. Control your creations in a fumblecore dash to solve each puzzle. Learn to swing through the trees, climb sheer cliffs, or even fly.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/230150/header.jpg?t=1693703082', 0, 0, NULL);
INSERT INTO games VALUES (132035, 230210, 'ASYLUM', 'An epic supernatural horror adventure and the spiritual successor to cult classic Scratches set in a massive, decaying mental institute. Inspired by H. P. Lovecraft, Hammer Films and twisted Euro Horror from the 80s.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/230210/header.jpg?t=1745611590', 0, 0, NULL);
INSERT INTO games VALUES (58938, 230230, 'Divinity: Original Sin (Classic)', 'Gather your party and get ready for a new, back-to-the-roots RPG adventure! Discuss your decisions with companions; fight foes in turn-based combat; explore an open world and interact with everything and everyone you see. Join up with a friend to play online in co-op and make your own adventures with the powerful RPG toolkit.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/230230/header.jpg?t=1732019432', 0, 0, NULL);
INSERT INTO games VALUES (58939, 230270, 'N++ (NPLUSPLUS)', 'N++ is a fast-paced, momentum-based platformer about darting around obstacles, narrowly evading enemies and collecting gold in a beautiful minimalist landscape.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/230270/header.jpg?t=1668008256', 1, 0, NULL);
INSERT INTO games VALUES (137995, 230290, 'Universe Sandbox', 'Create &amp; destroy on an unimaginable scale with a realistic physics-based space simulator. Explore the beauty of our universe and the fragility of our planet. Use science to bend the laws of gravity, collide planets, boil away oceans, fire epic space lasers, and customize your universe.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/230290/header.jpg?t=1745448523', 1, 0, NULL);
INSERT INTO games VALUES (58919, 230650, 'Lords of Football', 'Lords of Football is a whole new sports lifestyle simulator, played in God Mode.The everyday routine of football is brought to life, simulating footballers'' training to improve their skills and all the drama and real-life distractions that unfold during a normal season.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/230650/header.jpg?t=1573219483', 0, 0, NULL);
INSERT INTO games VALUES (58920, 230700, 'La-Mulana', 'LA-MULANA is an “Archaeological Ruin Exploration Action Game,” bringing the classic appeal of adventure with the punishing difficulty of retro-inspired gaming. Search inside ancient ruins, seeking out the “Secret Treasure of Life” – which sleeps in the sprawling ruins of “LA-MULANA” and is said to be the beginning of all civilization.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/230700/header.jpg?t=1749102745', 0, 0, NULL);
INSERT INTO games VALUES (58923, 230840, 'Daylight', 'You awake, trapped in an abandoned hospital. Your only source of light is your phone. You hit a dead-end and must turn around, but behind you lurks an eerie presence and strange noises... Experience Daylight, a procedurally generated psychological thriller for your PC.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/230840/header.jpg?t=1447357330', 0, 0, NULL);
INSERT INTO games VALUES (58924, 230860, 'Cannon Brawl', 'Cannon Brawl is action RTS and artillery hybrid. Pilot an airship, command powerful weapon emplacements and use the destructible terrain to out think and destroy your enemy! It''s a new take on artillery strategy!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/230860/header.jpg?t=1728954769', 0, 0, NULL);
INSERT INTO games VALUES (58925, 230980, 'Starseed Pilgrim', 'Starseed Pilgrim is a game about tending a symphonic garden, exploring space, and embracing fate.You are a gardener, tending to empty noise and empty space to fill them both with colour.You are a refugee, building your own world away from the spreading darkness.You are an explorer, discovering new places, new rules, and new fascinations.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/230980/header.jpg?t=1634922642', 0, 0, NULL);
INSERT INTO games VALUES (58926, 231040, 'Beatbuddy: Tale of the Guardians', 'Awakened from his slumber, Beatbuddy journeys through lush hand-painted environments on a quest to save his companions and his own immortality. Beatbuddy interacts with the living breathing environment that pulses to the beat of an original soundtrack, aiding him as he unlocks new paths and solves puzzles.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/231040/header.jpg?t=1700046592', 0, 0, NULL);
INSERT INTO games VALUES (58928, 231140, 'Cities XL Platinum', 'Build cities, shape a world.Cities XL Platinum lets you design, build and link up cities of all shapes and sizes around the Cities XL planet!Build more impressive cities than ever before! Cities XL Platinum offers a huge variety of over 1,000 buildings and constructions (including 50 brand new structures), that you can freely place on...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/231140/header.jpg?t=1651242019', 0, 0, NULL);
INSERT INTO games VALUES (58929, 231160, 'The Swapper', 'What if someone knew your mind better than you did? The Swapper is an award-winning, narrative driven puzzle game set in the furthest reaches of space.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/231160/18296f9c4adf96ec1aedc3daf8b817afbc41f740/header.jpg?t=1742578969', 0, 0, NULL);
INSERT INTO games VALUES (58915, 231200, 'Kentucky Route Zero: PC Edition', 'KENTUCKY ROUTE ZERO is a magical realist adventure game about a secret highway running through the caves beneath Kentucky, and the mysterious folks who travel it.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/231200/header.jpg?t=1692292539', 1, 0, NULL);
INSERT INTO games VALUES (58916, 231310, 'MirrorMoon EP', 'MirrorMoon EP is a game about mystery and exploration set in outer space. These space travels begin on a red planet and its unique moon and extend across galaxies. The single player part of MirrorMoon EP blends adventure and exploration with navigation-based puzzle solving.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/231310/header.jpg?t=1727787684', 0, 0, NULL);
INSERT INTO games VALUES (58917, 231330, 'Deadfall Adventures', 'Deadfall Adventures is an action-driven first-person shooter, spiced up with elements from action-adventure games. Become an adventurer, hunt for treasures, explore unknown regions of the world and rescue the damsel in distress from the clutches of enemies, both earthly and not-so-earthly.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/231330/header.jpg?t=1744351771', 0, 0, NULL);
INSERT INTO games VALUES (58918, 231430, 'Company of Heroes 2', 'Experience the ultimate WWII RTS platform with COH2 and its standalone expansions. This package includes the base game, which you can then upgrade by purchasing The Western Front Armies, Ardennes Assault and/or The British Forces. More info in the &quot;About This Game&quot; section below.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/231430/header.jpg?t=1749205518', 0, 0, NULL);
INSERT INTO games VALUES (58914, 231740, 'Knights of Pen and Paper +1 Edition', 'Set out on a grand adventure in this turn-based, retro style, pixel-art RPG, inspired by the great titles of the 90''s. Take on the roles of in-game players taking on the roles of their characters in a traditional pen and paper RPG session in the ultimate meta roleplaying experience.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/231740/header.jpg?t=1709829868', 0, 0, NULL);
INSERT INTO games VALUES (58908, 232010, 'Euro Truck Simulator', 'The original Euro Truck Simulator - the game which has become the classic of the genre and is still relevant today. The first truck simulation game in a European setting, with European long haul trucks!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/232010/header.jpg?t=1636488177', 0, 0, NULL);
INSERT INTO games VALUES (58909, 232050, 'Eador. Masters of the Broken World', 'Eador is a universe made of countless shards of land drifting in the Great Nothing. Each of the shards is a little world unto itself, with geography and denizens of its own. The power over the shards is bitterly contested by Masters, the immortal beings mortals believe to be gods.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/232050/header.jpg?t=1571149287', 0, 0, NULL);
INSERT INTO games VALUES (58910, 232090, 'Killing Floor 2', 'In KILLING FLOOR 2, players descend into continental Europe after it has been overrun by horrific, murderous clones called Zeds that were created by rogue elements of the Horzine Corporation. 6-player Co-Op &amp; 12-player VS Zed-slaughtering mayhem.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/232090/header.jpg?t=1729011001', 1, 0, NULL);
INSERT INTO games VALUES (58911, 232430, 'Gone Home', 'June 7th, 1995. 1:15 AM. You arrive home after a year abroad. You expect your family to greet you, but the house is empty. Something''s not right. Where is everyone? And what''s happened here? Unravel the mystery for yourself in Gone Home, a story exploration game from The Fullbright Company.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/232430/header.jpg?t=1726593929', 0, 0, NULL);
INSERT INTO games VALUES (58891, 232750, 'Mars: War Logs', 'An Intense Cyberpunk Rpg On the Red Planet! Mars War Logs takes you to Mars, nearly a century after the cataclysm that threw the planet and its colonists into chaos. Water has become the most precious resource on the arid red planet, with a few companies fighting a perpetual war for its control.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/232750/header.jpg?t=1712312619', 0, 0, NULL);
INSERT INTO games VALUES (58892, 232770, 'POSTAL', 'Take control of The POSTAL Dude in his infamous first outing as he battles to survive in a world gone mad! POSTAL is a classic isometric shooter filled to the brim with fast-paced explosive action.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/232770/header.jpg?t=1726332202', 0, 1, NULL);
INSERT INTO games VALUES (58893, 232790, 'Broken Age', 'A family friendly, hand-animated, puzzle-filled adventure game with an all-star cast, including Elijah Wood, Jack Black and Masasa Moyo. Funded by a record breaking crowdfunding campaign and designed by industry legend Tim Schafer, Broken Age is a timeless coming-of-age story.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/232790/header.jpg?t=1731601916', 0, 0, NULL);
INSERT INTO games VALUES (58894, 232890, 'Stronghold Crusader 2', 'Stronghold Crusader 2 is the long awaited sequel to the original castle sim. After 12 years Stronghold returns to the desert with a new 3D engine and powerful Havok Physics. Crusader 2 recaptures the original game’s addictive, fast-paced gameplay and authentic castle simulation.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/232890/header.jpg?t=1742482563', 0, 0, NULL);
INSERT INTO games VALUES (58895, 232910, 'TrackMania² Stadium', 'TrackMania² Stadium is the return of the popular Stadium environment enjoyed by millions of players with TrackMania Nations Forever. Now part of the ManiaPlanet environment, Stadium allows for improved services around the game, better graphics and a powerful track editor.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/232910/header.jpg?t=1680016487', 1, 0, NULL);
INSERT INTO games VALUES (58896, 232950, 'Bridge Project', 'Build A Bridge... and Get Over It!The Bridge Project is the successor to the original and award-winning Bridge Builder simulation, all amateur designers and structural engineers finally have a new challenge on their PC.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/232950/header.jpg?t=1562765398', 0, 0, NULL);
INSERT INTO games VALUES (58897, 232970, 'Thunder Wolves', 'When this “wolf pack” strikes, you hear the thunder roll. The Thunder Wolves attack from the air. They are mercenaries, and the best helicopter pilots in the world. Every one of them is ready for action at all times—and ready to fight evil, wherever it lurks.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/232970/header.jpg?t=1732704563', 0, 0, NULL);
INSERT INTO games VALUES (58898, 233130, 'Shadow Warrior', 'Shadow Warrior is a bold reimagining of the classic 3D Realms’ shooter from independent developer Flying Wild Hog (Hard Reset) starring the legendary and quick-witted warrior Lo Wang.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/233130/header.jpg?t=1710246206', 0, 0, NULL);
INSERT INTO games VALUES (58899, 233150, 'LUFTRAUSERS', 'The skies will be set aflame and the seas will overflow with wreckage in Vlambeer’s stylish arcade shooter LUFTRAUSERS! Select from over 125 combinations of weapons, bodies, and propulsion systems and take to the skies to battle enemy fighter planes, battleships, submarines, and rival aces for glory, honor, and high scores.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/233150/header.jpg?t=1659054136', 0, 0, NULL);
INSERT INTO games VALUES (58900, 233190, 'Final Exam', 'Jump into the frenzied action and the whacky humor of a pure 2.5D side-scroller! While they were going to their old high school for what was supposed to be the party of their life, four long-time friends end up in a ghost town full of monstrous creatures.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/233190/header.jpg?t=1650905619', 0, 0, NULL);
INSERT INTO games VALUES (58901, 233210, 'Air Conflicts: Vietnam', 'The Vietnam War, one of the most explosive and violent wars of all time. You are Joe Thompson, an intrepid and patriotic pilot fighting to uphold the values of his country. This war will be the ultimate test for Joe and will irrevocably change his relationship with his family.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/233210/header.jpg?t=1447357501', 0, 0, NULL);
INSERT INTO games VALUES (58902, 233230, 'Kairo', 'Enter the lost world of Kairo. Explore vast abandoned monuments. Bring strange and ancient machinery back to life. Slowly uncover the true purpose of Kairo and fulfil a great destiny.Kairo is an atmospheric 3D exploration and puzzle solving game.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/233230/header.jpg?t=1666983924', 0, 0, NULL);
INSERT INTO games VALUES (58903, 233270, 'Far Cry 3 - Blood Dragon', 'Far Cry® 3: Blood Dragon is THE Kick-Ass Cyber Shooter.Welcome to an 80’s vision of the future. The year is 2007 and you are Sargent Rex Colt, a Mark IV Cyber Commando. Your mission: get the girl, kill the baddies, and save the world.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/233270/header.jpg?t=1747655650', 0, 0, NULL);
INSERT INTO games VALUES (58904, 233290, 'Murdered: Soul Suspect', 'MURDERED: SOUL SUSPECT™ takes players into a whole new realm of mystery where the case is personal and the clues just out of reach, challenging gamers to solve the hardest case of all… their own murder.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/233290/header.jpg?t=1503075903', 0, 0, NULL);
INSERT INTO games VALUES (58905, 233310, 'Avadon 2: The Corruption', 'Avadon 2: The Corruption is a huge, indie fantasy role-playing adventure, the second chapter in the epic Avadon trilogy. You will serve the keep of Avadon, working as a spy and warrior to fight the enemies of your homeland. As a servant of the Black Fortress, your word is law.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/233310/header.jpg?t=1724976770', 0, 0, NULL);
INSERT INTO games VALUES (58906, 233350, 'Sudeki', 'Sudeki, a world torn apart into light, shadow and dark. Rent asunder by deceit and betrayal, the land cries out for a peace that only four united heroes can bring. Beyond the protective walls of Illumina Castle lie miles of pastoral, rolling countryside, though once a serene landscape, the Aklorian forces have transformed the countryside...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/233350/header.jpg?t=1573226855', 0, 0, NULL);
INSERT INTO games VALUES (58907, 233370, 'The Raven - Legacy of a Master Thief', '''The Raven - Legacy of a Master Thief'' is a thrilling crime adventure in three chapters from the creators of ''The Book of Unwritten Tales''. Full of twists and turns, it immerses you in both sides of the story, combining thrill-of-the-chase whodunit with the risk and reward of a heist story. Paris, 1960.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/233370/header.jpg?t=1562058409', 0, 0, NULL);
INSERT INTO games VALUES (58875, 233450, 'Prison Architect', 'Only the world’s most ruthless Warden can contain the world’s most ruthless inmates. Design and develop your personalized penitentiary in Prison Architect.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/233450/header.jpg?t=1737117114', 1, 0, NULL);
INSERT INTO games VALUES (58876, 233470, 'Evoland', 'Evoland is a journey through the history of action/adventure gaming, allowing you to unlock new technologies, gameplay systems and graphic upgrades as you progress through the game.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/233470/header.jpg?t=1716563896', 0, 0, NULL);
INSERT INTO games VALUES (58879, 233550, 'Another World – 20th Anniversary Edition', 'Also known as Out Of This World™, Another World is a pioneer action/platformer that released across more than a dozen platforms since its debut in 1991. Along the years, Another World™ has attained cult status among critics and sophisticated gamers alike.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/233550/header.jpg?t=1743411543', 1, 0, NULL);
INSERT INTO games VALUES (58880, 233610, 'Distance', 'Distance is an atmospheric racing platformer. Fusing futuristic arcade racing with parkour, survive a deadly, mysterious, neon-drenched city by jumping, rotating, and flying.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/233610/header.jpg?t=1688091852', 0, 0, NULL);
INSERT INTO games VALUES (58881, 233680, 'Black Ink', 'Explore Black Ink, a GPU-based painting app redefining creativity. Move beyond traditional tools, customize brushes, and let your imagination soar. Node-based system offers limitless control. Create in high-definition without performance loss.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/233680/header.jpg?t=1721027421', 0, 0, NULL);
INSERT INTO games VALUES (131304, 233700, 'Sword of the Stars: The Pit', 'A fun, fast, light-hearted, turn-based RPG, where the tradition of old school dungeon-diving games meets the sci-fi Sword of the Stars universe!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/233700/header.jpg?t=1713313740', 0, 0, NULL);
INSERT INTO games VALUES (58882, 233720, 'Surgeon Simulator', 'Surgeon Simulator is an over-the-top operation sim, stitching together pitch-black humour with life-saving surgery. Become Dr. Burke, a would-be surgeon with a less than conventional toolkit, as he performs procedures on patients including the Heavy from TF2! ...is that a hammer?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/233720/header.jpg?t=1726238747', 0, 0, NULL);
INSERT INTO games VALUES (58883, 233740, 'Organ Trail: Director''s Cut', 'Organ Trail is a retro zombie survival game. Travel westward in a station wagon with 4 of your friends, scavenging for supplies and fending off the undead. Members of your party might die of dysentery or you might have to put them down yourself when they get bit.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/233740/header.jpg?t=1737497858', 0, 0, NULL);
INSERT INTO games VALUES (58884, 233800, 'Arma 3 Tools', 'A complete tools suite for the Real Virtuality game engine powering Arma 3.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/233800/header.jpg?t=1726044269', 0, 0, NULL);
INSERT INTO games VALUES (58885, 233840, 'Worms Clan Wars', 'Worms™ Clan Wars is the biggest and best Worms™ game to date - more worms, larger landscapes, more dynamic water, more weapons and more customisation items than ever before.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/233840/header.jpg?t=1728996842', 0, 0, NULL);
INSERT INTO games VALUES (58886, 233860, 'Kenshi', 'A free-roaming squad based RPG. Focusing on open-ended sandbox gameplay features rather than a linear story. Be a trader, a thief, a rebel, a warlord, an adventurer, a farmer, a slave, or just food for the cannibals. Train your men up from puny victims to master warriors.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/233860/header.jpg?t=1721059338', 1, 0, NULL);
INSERT INTO games VALUES (58887, 233980, 'UnEpic', 'Daniel was just an average guy. He was a great videogame player, a big fan of sci-fi movies, and a novice RPG player. In the midst of an RPG, he was teleported to a castle. At first, Daniel believed that he was having a massive hallucination.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/233980/header.jpg?t=1706997556', 1, 0, NULL);
INSERT INTO games VALUES (58889, 234140, 'Mad Max', 'Play as Mad Max, a reluctant hero and survivor who wants nothing more than to leave the madness behind and find solace.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/234140/header.jpg?t=1732555043', 0, 0, NULL);
INSERT INTO games VALUES (58890, 234160, 'Strike Suit Infinity', 'Ok, cadet. This is it. All your training has brought you to this point - you are here for one reason only: to be the best.Strike Suit Infinity is a frantic high score chaser where your skill is the only thing that matters. Whatever combat experience you have had so far is considered irrelevant.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/234160/header.jpg?t=1717796701', 0, 0, NULL);
INSERT INTO games VALUES (58863, 234190, 'Receiver', 'Receiver was created for the 7-day FPS challenge to explore gun handling mechanics, randomized levels, and unordered storytelling. Armed only with a handgun and an audio cassette player, you must uncover the secrets of the Mindkill in a building complex infested with automated turrets and hovering shock drones.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/234190/header.jpg?t=1667232597', 0, 0, NULL);
INSERT INTO games VALUES (58864, 234270, 'Ken Follett''s The Pillars of the Earth', '12th century, England: In a time of poverty and war, a small town begins the construction of a cathedral to claim wealth and safety for its people. In their struggle to survive, lives and destinies intertwine. Based on Ken Follett''s world-bestseller ‘The Pillars of the Earth’.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/234270/header.jpg?t=1734629756', 0, 0, NULL);
INSERT INTO games VALUES (58868, 234390, 'Teleglitch: Die More Edition', 'In a cold, dark future dominated by mega-corporations, a small lonely planet on the edge of habitable space is the site of a shadowy research facility specializing in necrotic tissue reactivation. You are a scientist who has suddenly awoken to the realization that you are the lone survivor.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/234390/header.jpg?t=1726497232', 0, 0, NULL);
INSERT INTO games VALUES (58869, 234490, 'Rush Bros.', 'Rush Bros. “Discover gameplay with custom music” Rush Bros is a music reactive Platform Racing Game that features a single player and a competitive multiplayer either split-screen local or online between two simultaneous racers.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/234490/header.jpg?t=1729044490', 0, 0, NULL);
INSERT INTO games VALUES (58871, 234650, 'Shadowrun Returns', 'The unique cyberpunk-meets-fantasy world of Shadowrun has gained a huge cult following since its creation nearly 25 years ago. Now, creator Jordan Weisman returns to the world of Shadowrun, modernizing this classic game setting as a single player, turn-based tactical RPG.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/234650/header.jpg?t=1709809316', 0, 0, NULL);
INSERT INTO games VALUES (58872, 234670, 'NARUTO SHIPPUDEN: Ultimate Ninja STORM 3 Full Burst HD', 'Live the 4th Great Ninja War and its overpowering boss fights or defy your friends in ultra dynamic online and offline ninja confrontations!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/234670/header.jpg?t=1703662542', 0, 0, NULL);
INSERT INTO games VALUES (58873, 234710, 'Poker Night 2', 'The chips are down and the ante is up in this sentence already bursting with poker clichés! Take the fifth seat in Poker Night 2, at a table featuring Claptrap (Borderlands 2), Brock Samson (The Venture Bros.), Ash (Army of Darkness) and Sam (Sam and Max series).', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/234710/header.jpg?t=1567209058', 0, 0, NULL);
INSERT INTO games VALUES (58855, 234920, 'Dyscourse', 'Dyscourse is an interactive choice-based narrative adventure game where you journey through a stylized world of choice and consequence. Choose wisely.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/234920/header.jpg?t=1568759973', 0, 0, NULL);
INSERT INTO games VALUES (58856, 234940, 'The 39 Steps', 'Prepare to experience the original man-on-the-run thriller in a completely new way! There are secrets to be discovered, locations to be explored and - above all - an incredible tale to be told in this ground-breaking interactive novel.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/234940/header.jpg?t=1556008903', 0, 0, NULL);
INSERT INTO games VALUES (58858, 235210, 'STRIDER™ / ストライダー飛竜®', 'Strider returns in a brand new adventure, complete with incredible side-scrolling action, and lightning fast combat all in a massive interconnected world! Download the full game February 19th and become the original assassin!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/235210/header.jpg?t=1712193426', 0, 0, NULL);
INSERT INTO games VALUES (58859, 235250, 'Super Sanctum TD', 'Super Sanctum TD is a retro-styled Tower Defense game that focuses on strategy, customization and replayability. Build advanced mazes and construct powerful towers to prevent alien hordes from reaching the Core!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/235250/header.jpg?t=1510129510', 0, 0, NULL);
INSERT INTO games VALUES (58860, 235320, 'Original War', 'An American geological expedition, under a UN mandate, assesses the natural resources in a distant part of Siberia, deep in the trackless steppes of Eastern Russia. But instead of oil, they discover a deposit of a hitherto unknown mineral.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/235320/header.jpg?t=1748943843', 0, 0, NULL);
INSERT INTO games VALUES (58861, 235360, 'Prime World: Defenders', 'Fight off hordes of monstrous mutants created from a strange cataclysmic event in the new tower defense game, Prime World: Defenders. Join a group of exile treasure hunters who have ventured into the capital of an ancient empire, vast with mystery and danger.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/235360/header.jpg?t=1570455408', 0, 0, NULL);
INSERT INTO games VALUES (58862, 235380, 'Blitzkrieg 3', 'Blitzkrieg 3 is a WW2 RTS made for true admirers of strategic mastery! Challenge your tactical skills in historical campaigns and defeat powerful Neural Network AI in competitive matches.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/235380/header.jpg?t=1673539368', 1, 0, NULL);
INSERT INTO games VALUES (58842, 235520, 'The White Laboratory', 'The White Laboratory is a sandbox style physics-based tower defense and RTS game in which you modularly build and command robotic structures. Use them to defend against or conquer other disobedient mechanical blocks on a facility floating in the atmosphere of a remote gas planet.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/235520/header.jpg?t=1745570593', 0, 0, NULL);
INSERT INTO games VALUES (58843, 235540, 'Warhammer: End Times - Vermintide', 'Vermintide is an epic co-operative action combat adventure set in the End Times of the iconic Warhammer Fantasy world.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/235540/header.jpg?t=1729084164', 0, 0, NULL);
INSERT INTO games VALUES (58844, 235600, 'Tom Clancy’s Splinter Cell Blacklist', 'The United States has a military presence in two-thirds of countries around the world, and some of them have had enough. A group of terrorists calling themselves The Engineers initiate a terror ultimatum called the Blacklist - a deadly countdown of escalating attacks on U.S. interests.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/235600/header.jpg?t=1747656599', 0, 0, NULL);
INSERT INTO games VALUES (58845, 235620, 'Small World', 'CONTROL FANTASY RACES, SET OFF TO CONQUER NEW LANDS, OVERTHROW YOUR ENEMIES AND CLAIM THE VICTORY! In this digital adaptation of the legendary board game, dive into a world inhabited by whimsical fantasy races.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/235620/header.jpg?t=1741270770', 0, 0, NULL);
INSERT INTO games VALUES (58846, 235660, 'Eador: Genesis', 'Eador: Genesis is an indie turn-based strategy game created by Alexey Bokulev. It has inspired the development of Eador: Masters of the Broken World.Take the role of a mighty Master and shape the destiny of Eador, on land and within the astral plane itself.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/235660/header.jpg?t=1563274911', 0, 0, NULL);
INSERT INTO games VALUES (58848, 235800, 'Audiosurf 2', 'Ride your music in more ways than ever before. Audiosurf 2 is the music game for your entire music collection. Hundreds of mods/skins on Workshop. Free demo available.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/235800/header.jpg?t=1568407090', 0, 0, NULL);
INSERT INTO games VALUES (58849, 235820, 'Element4l', 'Element4l is an immersive and experimental indie platform game, with a strong focus on flow and smooth gameplay, wrapped in an exceptional soundtrack by Mind Tree.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/235820/header.jpg?t=1667031619', 0, 0, NULL);
INSERT INTO games VALUES (58850, 235900, 'RPG Maker XP', 'RPG MAKER lets you create an original role-playing game without any prior specialized knowledge or training. RPG MAKER XP is full of the functions you''ve been asking for, including game data encryption and a scripting feature that lets you change the very heart of the RPG MAKER engine.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/235900/header.jpg?t=1724913422', 0, 0, NULL);
INSERT INTO games VALUES (58851, 235980, 'Tetrobot and Co.', 'Tetrobot is the world''s most popular and reliable robot, but he''s not perfect. That''s why I, Maya, have built him a microscopic little brother, Psychobot.Help me guide Psy through Tetrobot''s cogs and circuits: by swallowing blocks of matter and spitting them out, we can repair anything.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/235980/header.jpg?t=1729349305', 0, 0, NULL);
INSERT INTO games VALUES (58853, 236090, 'Dust: An Elysian Tail', 'Immerse yourself in a gorgeous hand-painted world on a search for your true identity. As the mysterious warrior, Dust, your action-packed journey will take you from peaceful glades to snowy mountaintops and beyond.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/236090/header.jpg?t=1667838728', 0, 0, NULL);
INSERT INTO games VALUES (58854, 236110, 'Dungeon Defenders II', 'Dungeon Defenders II is a cooperative Action Tower Defense game packed with roleplaying elements like loot, leveling, and pets.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/236110/header.jpg?t=1749075763', 0, 1, NULL);
INSERT INTO games VALUES (58831, 236130, 'Horizon', 'Horizon is a turn-based space strategy game of galactic exploration and conquest in which you are in control of humanity’s destiny. You will explore deep space, find new frontiers and discover alien artifacts hidden on long-abandoned planets.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/236130/header.jpg?t=1715798080', 0, 0, NULL);
INSERT INTO games VALUES (58832, 236150, 'Starpoint Gemini 2', 'Captain your own space ship and roam the galaxy in 3D in this tactical space simulator with tons of RPG depth ! Space has never looked so inviting - but images can betray...It has been two years since the end of the second Gemini war, the situation in the wartorn system is further from resolution than ever.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/236150/header.jpg?t=1732638762', 0, 0, NULL);
INSERT INTO games VALUES (58834, 236370, 'Interstellar Marines', 'UPDATE 28 AVAILABLE - Interstellar Marines is an immersive tactical sci-fi First Person Simulator in the making, offering a unique blend of tactical gameplay, dynamic environments and non-scripted AI. Play Singleplayer or Co-op/PvP on servers around the world.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/236370/header.jpg?t=1579498657', 0, 0, NULL);
INSERT INTO games VALUES (128132, 236390, 'War Thunder', 'War Thunder is the most comprehensive free-to-play, cross-platform, MMO military game dedicated to aviation, armoured vehicles, and naval craft, from the early 20th century to the most advanced modern combat units. Join now and take part in major battles on land, in the air, and at sea.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/236390/143bb936a24b8dfb7a8eadcb7173e9ab5bc1fa62/header.jpg?t=1746626432', 1, 1, NULL);
INSERT INTO games VALUES (58835, 236430, 'DARK SOULS™ II', 'Developed by FROM SOFTWARE, DARK SOULS™ II is the highly anticipated sequel to the gruelling 2011 breakout hit Dark Souls. The unique old-school action RPG experience captivated imaginations of gamers worldwide with incredible challenge and intense emotional reward.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/236430/header.jpg?t=1726158600', 1, 0, NULL);
INSERT INTO games VALUES (58836, 236450, 'PAC-MAN™ Championship Edition DX+', 'It''s time to gear up!Get ready for more ghost chain gobbling and frantic action in PAC-MAN® CE-DX+! The award-winning chomping game makes a shattering debut on Steam with even more content and a refined user-interface to compare high scores with your friends!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/236450/header.jpg?t=1580311291', 0, 0, NULL);
INSERT INTO games VALUES (58838, 236510, 'Takedown: Red Sabre', 'TAKEDOWN is a thinking-person’s shooter; brutal, hardcore and deadly - like the real thing. Not for the faint hearted, Takedown requires you to bring your ''A'' game - FPS fans looking for an ultra hardcore experience only need apply!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/236510/header.jpg?t=1447357732', 0, 0, NULL);
INSERT INTO games VALUES (58839, 236690, 'Blood Bowl 2', 'Blood Bowl 2 smashes Warhammer and American football together, in an explosive cocktail of turn-based strategy, humour and brutality, adapted from Games Workshop’s famous boardgame.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/236690/header.jpg?t=1728038137', 0, 0, NULL);
INSERT INTO games VALUES (58840, 236730, 'Anomaly 2', 'Anomaly 2 is a sequel to the critically acclaimed Anomaly Warzone Earth. Maintaining the core elements of the original, Anomaly 2 adds plenty of new features: unit morphing, over million tactical combinations, post-apo world and tower defense vs tower offense multiplayer mode.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/236730/header.jpg?t=1716457749', 0, 0, NULL);
INSERT INTO games VALUES (58841, 236790, 'Agricultural Simulator 2013 - Steam Edition', 'Best In Farming!An idyllic farming environment surrounded by inviting &amp; untilled mountain panoramas set in the beautiful landscapes of Tuscany, The Alps and USA await all fans of the Agricultural Simulator series.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/236790/header.jpg?t=1727966331', 0, 0, NULL);
INSERT INTO games VALUES (58823, 236930, 'Blackwell Epiphany', 'The last game in the Blackwell series.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/236930/header.jpg?t=1728037695', 0, 0, NULL);
INSERT INTO games VALUES (58825, 237350, 'Frozen Cortex', 'A hard-hitting simultaneous-turn-based tactical game from the creators of Frozen Synapse. Defeat your opponent’s plans on a randomly-generated playfield in this brutal futuresport.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/237350/header.jpg?t=1465901348', 0, 0, NULL);
INSERT INTO games VALUES (58826, 237370, 'PlayClaw 5 - Game Recording and Streaming', 'The amazing PlayClaw video capture tool gives customers incredible power!PlayClaw has been designed to make full use of multi-core processors and hardware accelerated H.264 codecs, which ensures the outstanding quality of the output with a minimal impact on system performance.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/237370/header.jpg?t=1526399686', 1, 0, NULL);
INSERT INTO games VALUES (58827, 237430, 'Expeditions: Conquistador', 'Conquer the New world: In the 16th Century, Spanish explorers and soldiers reached the shores of America. The search for gold, fame, and adventure drove these travelers into a treacherous wilderness where they faced hunger, disease, and dangerous predators. In their wake, the Aztec Empires lay in ruins.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/237430/header.jpg?t=1660136640', 0, 0, NULL);
INSERT INTO games VALUES (58829, 237550, 'Realms of Arkania: Blade of Destiny', 'A legend reborn as Realms of Arkania: Blade of Destiny returns!Developed by Austrian developer Crafty Studios, Realms of Arkania – Blade of Destiny is a faithful remake of the 1992 original, adored by a generation of Role Players and one of the most successful RPG’s of the 1990’s.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/237550/header.jpg?t=1727966377', 0, 0, NULL);
INSERT INTO games VALUES (58830, 237570, 'Penny Arcade''s On the Rain-Slick Precipice of Darkness 4', 'Penny Arcade’s “On the Rain-Slick Precipice of Darkness 4” concludes the saga of Tycho Brahe, Scion of The Long Project, and his almost certainly human partner Jonathan Gabriel. The world has been destroyed, but existence extends beyond this mortal plane in the gruesome Underhell!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/237570/header.jpg?t=1682942925', 0, 1, NULL);
INSERT INTO games VALUES (58808, 237740, 'Angry Video Game Nerd Adventures', '&quot;The most rewarding game of 2013!&quot; Influenced by retro classics Mega Man and Castlevania, Angry Video Game Nerd Adventures features the AVGN and friends as they blast their way through 10 levels of fun, fast paced 2D action based on the AVGN''s adventures in his online series.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/237740/header.jpg?t=1726252819', 0, 0, NULL);
INSERT INTO games VALUES (58810, 237850, 'Dreamfall Chapters', 'The Final Cut is the ultimate collector''s edition of Dreamfall Chapters, a story-driven 3D adventure about choice and consequence, set in parallel worlds: a cyberpunk vision of the future and a magical fantasy realm.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/237850/header.jpg?t=1733410272', 0, 0, NULL);
INSERT INTO games VALUES (58811, 237870, 'Planet Explorers', 'Planet Explorers is an open world sandbox adventure RPG game set on a distant planet. The game uses a new OpenCL calculated voxel system to allow players to change the terrain in any way, create new objects such as weapons, vehicles, objects, and do it anywhere.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/237870/header.jpg?t=1596510667', 0, 1, NULL);
INSERT INTO games VALUES (58812, 237890, 'Agarest: Generations of War', 'At the dawn of time, a terrible war raged between the forces of good and evil, ending in the destruction of the world of Agarest. After their victory, the Gods of Light unified the decaying bodies of the Gods of Darkness and created a new world.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/237890/header.jpg?t=1572353455', 0, 0, NULL);
INSERT INTO games VALUES (58813, 237930, 'Transistor', 'Discover the world of Transistor, a sci-fi-themed action RPG from the creators of Bastion.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/237930/header.jpg?t=1729113992', 0, 0, NULL);
INSERT INTO games VALUES (58814, 237950, 'UFO: Afterlight', 'The story is situated on Mars. It starts where UFO: Aftermath left off and runs simultaneously with UFO: Aftershock. While the Laputans on Earth are fighting Wargots and Starghosts and finding out what caused the destruction of their home planet, a small colony on Mars is trying to survive and flourish.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/237950/header.jpg?t=1748947064', 0, 0, NULL);
INSERT INTO games VALUES (58816, 237990, 'The Banner Saga', 'Live through an epic role-playing Viking saga where your strategic choices directly affect your personal journey. Make allies as you travel with your caravan across this stunning yet harsh landscape. Carefully choose those who will help fight a new threat that jeopardizes an entire civilization.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/237990/header.jpg?t=1650912084', 1, 0, NULL);
INSERT INTO games VALUES (58817, 238010, 'Deus Ex: Human Revolution - Director''s Cut', 'You play Adam Jensen, an ex-SWAT specialist who''s been handpicked to oversee the defensive needs of one of America''s most experimental biotechnology firms. Your job is to safeguard company secrets, but when a black ops team breaks in and kills the very scientists you were hired to protect, everything you thought you knew about your job...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/238010/header.jpg?t=1726596595', 0, 0, NULL);
INSERT INTO games VALUES (58818, 238050, 'The Apogee Throwback Pack', 'The Apogee Throwback Pack is a collection of four classic Apogee Software titles all in one kick ass package. Blast your way across the galaxy as British Special Agent Blake Stone in &quot;Aliens of Gold&quot; and &quot;Planet Strike&quot;, then take on an ancient evil menace as the H.U.N.T in &quot;Rise of the Triad&quot;.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/238050/header.jpg?t=1618626935', 0, 0, NULL);
INSERT INTO games VALUES (58820, 238090, 'Sniper Elite 3', 'Sniper Elite 3 is a tactical third-person shooter that combines stealth, gameplay choice and genre-defining ballistics with huge, open levels and the exotic terrain of World War 2 North Africa.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/238090/header.jpg?t=1601483606', 1, 0, NULL);
INSERT INTO games VALUES (58821, 238210, 'System Shock® 2 (Classic)', '&quot;Remember, it is my will that guided you here. It is my will that gave you your cybernetic implants, the only beauty in that meat you call a body. If you value that meat... you will do as I tell you.&quot; The cult classic sci-fi horror FPS-RPG has returned.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/238210/0cd0fc862305030e7bb72b1b967962af339cb8ec/header_alt_assets_0.jpg?t=1742502733', 0, 0, NULL);
INSERT INTO games VALUES (58822, 238240, 'Edge of Space', 'Suit up as an operative of the Ark Corporation, sent to the farthest reaches of the universe in search of habitable planets to terraform. However, after the long space journey you awaken from cryosleep to find that your ship has gone way off course and is disabled near a strange new world.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/238240/header.jpg?t=1667241258', 0, 0, NULL);
INSERT INTO games VALUES (58797, 238280, 'Legend of Dungeon', 'Legend of Dungeon is a randomly generated action RPG Beat''em''up with heavy Rogue-like elements, striking visuals, and dynamic music.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/238280/header.jpg?t=1667065004', 0, 0, NULL);
INSERT INTO games VALUES (58798, 238320, 'Outlast', 'Hell is an experiment you can''t survive in Outlast, a first-person survival horror game developed by veterans of some of the biggest game franchises in history. As investigative journalist Miles Upshur, explore Mount Massive Asylum and try to survive long enough to discover its terrible secret... if you dare.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/238320/header.jpg?t=1666817106', 0, 0, NULL);
INSERT INTO games VALUES (58799, 238370, 'Magicka 2', 'The world’s most irreverent co-op action adventure returns! In the next chapter of Magicka, players ascend from the ruins of Aldrheim to experience a Midgård almost wiped free of Wizards after the Wizard Wars, with the few that do remain having either gone mad or extremely hostile toward all others', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/238370/header.jpg?t=1709831158', 0, 0, NULL);
INSERT INTO games VALUES (58800, 238460, 'BattleBlock Theater®', 'Welcome to BattleBlock Theater! You’ve got no where to go but up...on stage. Play single player or co-op to free your friends and save Hatty Hattington! Jump, solve and battle your way through a mysterious theater inhabited by highly technological felines.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/238460/header.jpg?t=1733782954', 1, 0, NULL);
INSERT INTO games VALUES (58801, 238530, 'Super Puzzle Platformer Deluxe', 'The title says it all. Take one part falling block puzzle game, combine one part old-school platformer, add a couple thousand pixels, blend and serve. Why match colored blocks when you can just shoot the hell out of them? Your goal is to survive as long as you can. From celebrated indie developer Andrew Morrish and Adult Swim Games.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/238530/header.jpg?t=1734680323', 0, 0, NULL);
INSERT INTO games VALUES (58802, 238630, 'Fist Puncher', 'The sinister Milkman holds the city of San Cruces in his nasty criminal grip, and it’s up to legendary black belt neurosurgeon Dr. Karate and the rest of the Fist Puncher team to deliver old-school justice to the lawless streets.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/238630/header.jpg?t=1720581774', 0, 0, NULL);
INSERT INTO games VALUES (58803, 238750, 'Might & Magic X - Legacy', 'After a decade, a Might &amp; Magic® RPG is back with both the unique core formula and a new set of improved and fine-tuned features. The best RPG of its class!In the wake of the spectacular events in Might &amp; Magic® Heroes® VI, you will play in a party of four adventurers entangled in intrigue and political machinations unfolding in...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/238750/header.jpg?t=1747657195', 1, 0, NULL);
INSERT INTO games VALUES (58804, 238870, 'Citadels', 'The Legend Of King Arthur Reborn!A vast army has gathered in front of the castle gates and is preparing to attack King Arthur! How has it come to this? Witness important events in the history of the legendary king and accompany him and his army on the path to an uncertain future.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/238870/header.jpg?t=1742825326', 0, 0, NULL);
INSERT INTO games VALUES (58805, 238890, 'Skyward Collapse', 'How do you balance -- and indeed encourage -- a war between factions without letting either side obliterate the other? How do you rule over gods, creatures, and men who refuse to obey you? How do you build a landscape of villages when bandits and mythology are conspiring to tear it down?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/238890/header.jpg?t=1729277210', 0, 0, NULL);
INSERT INTO games VALUES (58806, 238910, 'Bionic Dues', 'Bionic Dues is a tactical, turn-based roguelite with mech customization. Out-think wide-ranging tactical situations featuring robots with bad GPS, terrible aim, insecurity, a lack of focus, a tendency to backstab, and dozens of other maladies to exploit.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/238910/header.jpg?t=1741478960', 0, 0, NULL);
INSERT INTO games VALUES (58807, 238930, '7 Grand Steps: What Ancients Begat', 'What Ancients Begat is a complete (~15 hour) game of family generations surviving the rise of western civilization. Survival is the ultimate goal. The sub-goals, you choose, build their story.Experience an abstract telling of the lives of our earliest recorded ancestors.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/238930/header.jpg?t=1447357877', 0, 0, NULL);
INSERT INTO games VALUES (58787, 239030, 'Papers, Please', 'Congratulations. The October labor lottery is complete. Your name was pulled. For immediate placement, report to the Ministry of Admission at Grestin Border Checkpoint. An apartment will be provided for you and your family in East Grestin. Expect a Class-8 dwelling.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/239030/header.jpg?t=1678266428', 1, 0, NULL);
INSERT INTO games VALUES (58788, 239070, 'Hammerwatch', 'A hack and slash action adventure, set in a fantasy pixel art environment. Play solo or co-op in this adventure from bottom to top of Castle Hammerwatch. Kill hordes of enemies with varied looks and features through four unique environments with traps, hidden secrets and puzzles.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/239070/header.jpg?t=1727923111', 0, 0, NULL);
INSERT INTO games VALUES (58789, 239090, 'Samurai GUNN', 'Samurai GUNN is a lightning-fast Bushido brawler for two to four players. Each samurai is armed with a sword and gunn, with only 3 bullets to a life. Strategy and quick reflexes are the key to deflecting bullets and sending your opponents’ heads rolling.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/239090/header.jpg?t=1732907569', 0, 0, NULL);
INSERT INTO games VALUES (58790, 239120, 'Final Fantasy III (3D Remake)', 'FINAL FANTASY® III, one of the best-loved games from the epic RPG series, available on Steam.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/239120/header.jpg?t=1624982475', 1, 0, NULL);
INSERT INTO games VALUES (58791, 239140, 'Dying Light', 'First-person action survival game set in a post-apocalyptic open world overrun by flesh-hungry zombies. Roam a city devastated by a mysterious virus epidemic. Scavenge for supplies, craft weapons, and face hordes of the infected.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/239140/header.jpg?t=1738004178', 1, 0, NULL);
INSERT INTO games VALUES (58792, 239160, 'Thief', 'Garrett, the Master Thief, steps out of the shadows into the City. In this treacherous place, where the Baron’s Watch spreads a rising tide of fear and oppression, his skills are the only things he can trust. Even the most cautious citizens and their best-guarded possessions are not safe from his reach.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/239160/header.jpg?t=1726596864', 0, 0, NULL);
INSERT INTO games VALUES (58793, 239200, 'Amnesia: A Machine for Pigs', 'From the creators of Amnesia: The Dark Descent and Dear Esther comes a new first-person horrorgame that will drag you to the depths of greed, power and madness. It will bury its snout into your ribs and it will eat your heart.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/239200/header.jpg?t=1727954562', 0, 0, NULL);
INSERT INTO games VALUES (58794, 239350, 'Spelunky', 'Spelunky is a unique platformer with randomized levels that offer a challenging new experience each time you play. Journey deep underground and explore fantastic places filled with all manner of monsters, traps, and treasure.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/239350/header.jpg?t=1632912566', 0, 0, NULL);
INSERT INTO games VALUES (58795, 239430, 'Q.U.B.E: Director''s Cut', 'Q.U.B.E: Director''s Cut is the definitive version of the brain-twisting first-person puzzler. Using special high-tech gloves to manipulate cubes in the environment, the player solves an array of conundrums - from physics-based challenges; to 3D jigsaws; to platform-based trials.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/239430/header.jpg?t=1730459259', 0, 0, NULL);
INSERT INTO games VALUES (58780, 239700, 'Hate Plus', 'Let''s spend the next three real-time days together uncovering the mystery of what went horribly wrong on a derelict generation ship, with the help of a spunky/more-than-slightly-traumatized AI sidekick! A sequel to Analogue: A Hate Story that tells a whole new hate story of its own.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/239700/header.jpg?t=1726321087', 1, 0, NULL);
INSERT INTO games VALUES (58781, 239800, 'Bleed', 'Wryn is a girl with a big arsenal and big dreams -- she wants to be the ultimate videogame hero! Help her take down the Greatest Heroes of All Time in an action-packed bid to claim the title for herself and show the world what a true hero looks like!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/239800/header.jpg?t=1572981766', 0, 0, NULL);
INSERT INTO games VALUES (58782, 239840, 'Dead State: Reanimated', 'Dead State is a narrative-driven survival RPG set at the dawn of the undead apocalypse. Drawing inspiration from classic RPGs like Fallout, X-Com, and Suikoden, Dead State combines strategic, turn-based combat with base building mechanics, character creation, and social management.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/239840/header.jpg?t=1572648629', 0, 0, NULL);
INSERT INTO games VALUES (58786, 240440, 'Quadrilateral Cowboy', 'When you have a top-of-the-line hacking deck armed with a 56.6k modem and a staggering 256k RAM, it means just one thing: you answer only to the highest bidder.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/240440/header.jpg?t=1603302631', 0, 0, NULL);
INSERT INTO games VALUES (58773, 240600, 'MotoGP™13', '2013 Riders, teams and tracks; both simulation and accessible bike handling with scalable aids; photorealistic graphics with TV style interface; ingame voice over by official MotoGP™ commentators; first person elements such as the helmet view and 3D pits to put you in the rider’s shoes.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/240600/header.jpg?t=1728478425', 0, 0, NULL);
INSERT INTO games VALUES (58774, 240620, 'Wanderlust Adventures', 'Wanderlust Adventures is an online, free-roaming, open world, action adventure RPG. Join fellow heroes online, explore vast and deadly landscapes, and capture companions to aid you in your quest. Forge powerful items, salvage artifacts, and crush the souls of menacing foes!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/240620/header.jpg?t=1479240507', 0, 0, NULL);
INSERT INTO games VALUES (58776, 240720, 'Getting Over It with Bennett Foddy', 'A game I made for a certain kind of person. To hurt them.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/240720/header.jpg?t=1666987027', 1, 0, NULL);
INSERT INTO games VALUES (58777, 240760, 'Wasteland 2: Director''s Cut', 'From the producer of the original Fallout comes Wasteland 2. With over 80 hours of gameplay, deck out your Ranger squad with devastating weaponry, test the limits of your strategy skills, and bring justice to the Wasteland! The choices are yours…but so are the consequences.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/240760/header.jpg?t=1686191412', 0, 0, NULL);
INSERT INTO games VALUES (58778, 240970, 'Half Minute Hero: The Second Coming', 'The world''s speediest homage/roast to JRPGs! Can you save the world in 30 seconds? Get a quest, find those in need, fight through dungeons, earn cash, get cool loot and level up until YOU&gt;EVIL. Don''t have enough time? Pay the Goddess to reset the clock and try again! Over 100 mini-JRPGs for you to test your might with!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/240970/header.jpg?t=1594366098', 0, 0, NULL);
INSERT INTO games VALUES (58779, 241000, 'Jon Shafer''s At the Gates', 'At the Gates is an indie strategy game from Jon Shafer, designer of Civilization 5. You are a dark age lord building a kingdom to replace the crumbling Roman Empire. Manage your clans, explore the landscape around you, harvest its resources, and build a mighty economic and military machine.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/241000/header.jpg?t=1586523911', 0, 0, NULL);
INSERT INTO games VALUES (58758, 241240, 'Contraption Maker', 'The spiritual successor to The Incredible Machine from its original designer and programmer. Play 100s of puzzles. Build and share elaborate contraptions with an huge variety of parts and critters.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/241240/header.jpg?t=1724702807', 0, 0, NULL);
INSERT INTO games VALUES (58759, 241260, 'Sherlock Holmes: Crimes and Punishments', 'Become the most celebrated detective of all time: Sherlock Holmes! Use your impressive talents as a detective to solve six thrilling and varied cases: murders, missing persons, spectacular thefts and numerous investigations that sometimes lead you into the realms of the fantastic.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/241260/header.jpg?t=1693291960', 1, 0, NULL);
INSERT INTO games VALUES (58760, 241300, 'Card City Nights 2', 'Adventure and Cards now back together! And remember, it''s always night in space.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/241300/header.jpg?t=1632146375', 0, 0, NULL);
INSERT INTO games VALUES (58761, 241320, 'Ittle Dew', 'Adventuress Ittle Dew and her sidekick Tippsie crash onto a strange island, filled with loot and mysterious inhabitants. It quickly dawns on the duo that this might become their biggest adventure yet.Ittle Dew boils down the classic adventure formula until there is only fun left.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/241320/header.jpg?t=1573569073', 0, 0, NULL);
INSERT INTO games VALUES (58762, 241410, 'CastleStorm', 'Welcome to the world of CastleStorm, a super genre mashup of 2D physics destruction mashed with tower defense brawler! CastleStorm was born out of the fond childhood memory of building and destroying LEGO castles.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/241410/header.jpg?t=1727780515', 0, 0, NULL);
INSERT INTO games VALUES (58763, 241540, 'State of Decay', 'The end is here. Life as you knew it has gone to hell after the mother of all zombie outbreaks. Now you and the few scattered survivors must band together to survive and rebuild in a 3rd-person action game set in a dynamic open world.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/241540/header.jpg?t=1573205685', 0, 0, NULL);
INSERT INTO games VALUES (58764, 241600, 'Rogue Legacy', 'Rogue Legacy is a genealogical rogue-&quot;LITE&quot; where anyone can be a hero. Each time you die, your child will succeed you. Every child is unique. One child might be colorblind, another might be a dwarf with vertigo. But that''s OK, because no one is perfect, and you don''t have to be to succeed.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/241600/header.jpg?t=1743078622', 0, 0, NULL);
INSERT INTO games VALUES (58765, 241620, 'Inquisitor', 'Action-oriented combat with a deep and involving tale of betrayal, torture, madness, and infernal damnation. If a gritty old-school open-ended isometric RPG is what you looking for, look no further. Inquisitor will provide you with hours of gameplay and a dark, involving story.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/241620/d2cde7d87656c592f175fbb749ca5ba603f91b50/header.jpg?t=1743167906', 0, 0, NULL);
INSERT INTO games VALUES (58768, 241720, 'Guncraft', 'Block and Load! Combining the addictive nature of block building sandbox games with the speed and competition of modern first-person shooters, Guncraft takes voxel-based gaming to a whole new level. Players can create maps and arenas based on anything imaginable and, once complete, can utterly destroy them with bullets, bombs, grenades,...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/241720/header.jpg?t=1525801744', 0, 0, NULL);
INSERT INTO games VALUES (58769, 241760, 'Kill to Collect', 'Welcome to the last city on Earth. Earn your keep and die trying in Pieces Interactive’s cyberpunk action rogue-like, featuring 1-4 player co-op. Travel down the sleepless cesspool of murderous vagrants and cybernetic freaks, as you slice and dice your way to the lower levels of Geoshelter Alpha.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/241760/header.jpg?t=1729076458', 0, 0, NULL);
INSERT INTO games VALUES (58771, 241910, 'Goodbye Deponia', 'More chaos, more destruction, more Rufus. Not one, not two, but three Rufuses cause all kinds of crazy mayhem in the long-awaited adventure comedy Goodbye Deponia!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/241910/header.jpg?t=1734630505', 0, 0, NULL);
INSERT INTO games VALUES (58772, 241930, 'Middle-earth™: Shadow of Mordor™', 'Fight through Mordor and uncover the truth of the spirit that compels you, discover the origins of the Rings of Power, build your legend and ultimately confront the evil of Sauron in this new chronicle of Middle-earth.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/241930/header.jpg?t=1745613450', 0, 0, NULL);
INSERT INTO games VALUES (58749, 242050, 'Assassin’s Creed® IV Black Flag™', 'The year is 1715. Pirates rule the Caribbean and have established their own lawless Republic where corruption, greediness and cruelty are commonplace.Among these outlaws is a brash young captain named Edward Kenway.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/242050/header.jpg?t=1738250868', 0, 0, NULL);
INSERT INTO games VALUES (58751, 242130, 'Vector Thrust', 'Vector Thrust is a fast-paced single and mulltiplayer combat flight game, using a unique cel shaded art style. The game features 260 fully playable aircraft (through various iterations of over 45 aircraft models).', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/242130/header.jpg?t=1599049559', 0, 0, NULL);
INSERT INTO games VALUES (58752, 242530, 'The Chaos Engine', 'Prepare for the dark world of The Chaos Engine, a steampunk Victorian age in which one or two players must fight the hostile creations of the Chaos Engine across four dynamic landscapes and take part in the ultimate battle.Choose from six hard-nailed mercenaries each with their own unique weapons and skills.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/242530/header.jpg?t=1574864269', 0, 0, NULL);
INSERT INTO games VALUES (58753, 242550, 'Rayman® Legends', 'Michel Ancel, the celebrated creator of Rayman®, Beyond Good &amp; Evil®, and the Raving Rabbids®, returns to unleash his innovative creativity on this new entry into the Rayman® franchise.When Rayman, Globox, and the Teensies discover a mysterious tent filled with captivating paintings, they are suddenly transported to a series of...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/242550/header.jpg?t=1744316870', 0, 0, NULL);
INSERT INTO games VALUES (58754, 242570, 'Space Hulk', '&quot;WE ARE THE VANGUARD OF HONOUR. THE CUTTING EDGE OF THE BLOOD ANGELS. WE BRING DEATH.&quot;The legendary Space Hulk returns to Windows PC, Mac and Linux in this epic turn based strategy game. Set in the Warhammer 40,000 universe, an intriguing story of legendary battles and heroic actions unfolds.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/242570/header.jpg?t=1572552321', 0, 0, NULL);
INSERT INTO games VALUES (58756, 242680, 'Nuclear Throne', 'Nuclear Throne is a post-apocalyptic roguelike-like top-down shooter. Not ''the final hope of humanity'' post-apocalyptic, but ''humanity is extinct and mutants and monsters now roam the world'' post-apocalyptic. Fight your way through the wastelands with powerful weaponry, collecting radiation to mutate some new limbs and abilities.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/242680/header.jpg?t=1747943408', 0, 0, NULL);
INSERT INTO games VALUES (58757, 242700, 'Injustice: Gods Among Us Ultimate Edition', 'Injustice: Gods Among Us Ultimate Edition enhances the bold new franchise to the fighting game genre from NetherRealm Studios. Featuring six new playable characters, over 30 new skins, and 60 new S.T.A.R. Labs missions, this edition packs a punch.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/242700/header.jpg?t=1745967056', 0, 0, NULL);
INSERT INTO games VALUES (58730, 242760, 'The Forest', 'As the lone survivor of a passenger jet crash, you find yourself in a mysterious forest battling to stay alive against a society of cannibalistic mutants. Build, explore, survive in this terrifying first person survival horror simulator.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/242760/header.jpg?t=1699381053', 1, 0, NULL);
INSERT INTO games VALUES (58731, 242780, 'Cognition: An Erica Reed Thriller', 'FBI agent Erica Reed has an uncanny talent: she can see the past and piece together how a crime unfolded. But not even this sixth sense could save her younger brother, Scott, from a brutal serial killer. Three years later, the investigation into Scott’s murder has gone cold -- but Erica’s work has only just begun.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/242780/header.jpg?t=1478025368', 0, 0, NULL);
INSERT INTO games VALUES (58732, 242820, '140', '140 is a challenging minimalistic platformer with abstract colorful graphics. Rhythmic awareness is required to overcome obstacles controlled by an energetic, yet melancholic electronic soundtrack.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/242820/header.jpg?t=1632130187', 1, 0, NULL);
INSERT INTO games VALUES (58733, 242840, 'In Verbis Virtus', 'Use your real voice to cast spells in In Verbis Virtus, a fantasy adventure unlike any other. Step into the shoes of a wizard in search of an ancient power. Explore a lost temple, making your way through forgotten chambers brimming with unspeakable beauty and terror.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/242840/header.jpg?t=1667037061', 0, 0, NULL);
INSERT INTO games VALUES (58734, 242860, 'Verdun', 'Merciless trench warfare immerses you and your squad in intense battles of attack and defense. Verdun is the first multiplayer FPS set in an authentic World War One setting offering a rarely seen battlefield experience.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/242860/header.jpg?t=1739289304', 0, 0, NULL);
INSERT INTO games VALUES (58735, 242880, 'Sir, You Are Being Hunted', 'Sir, You Are Being Hunted is a freedom sandbox stealth experience, where each playthrough is unique, thanks to our British Countryside Generator. Escape from these robot-infested islands with violence, trickery and stealth. This brutally funny game is available for Windows, OSX, and Linux.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/242880/header.jpg?t=1718831931', 0, 0, NULL);
INSERT INTO games VALUES (58736, 242920, 'Banished', 'In this city-building strategy game, you control a group of exiled travelers who decide to restart their lives in a new land. They have only the clothes on their backs and a cart filled with supplies from their homeland. The townspeople of Banished are your primary resource.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/242920/header.jpg?t=1667584747', 0, 0, NULL);
INSERT INTO games VALUES (58737, 242940, 'Anachronox', 'Join Sylvester &quot;Sly&quot; Boots and Stiletto Anyway as they trek across six bizarre planets investigating a galaxy-crushing mystery, searching for artefacts from an extinct alien race and unlocking the secrets of a powerful, advanced technology. It''s your turn. PICK YOUR POISON.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/242940/header.jpg?t=1592490066', 0, 0, NULL);
INSERT INTO games VALUES (58738, 242960, 'Blood Omen 2: Legacy of Kain', 'Cast down from power by a mysterious warlord centuries ago, Kain reawakens in a world he barely recognises. His armies slain, his vampire brethren nearly extinct, Kain is one of the last of his kind. With an agenda of vengeance, Kain shall unleash a wicked wrath to uncover the plot that threatens the land he seeks to conquer.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/242960/header.jpg?t=1727993892', 0, 0, NULL);
INSERT INTO games VALUES (58739, 242980, 'Daikatana', 'In 2455 AD, Kage Mishima used the magical powers of Daikatana, the most powerful sword ever forged, to alter time and establish himself as supreme dictator. You are Hiro Miyamoto, one of the few people on earth who knows what happened.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/242980/header.jpg?t=1592490694', 0, 0, NULL);
INSERT INTO games VALUES (58740, 243000, 'Omikron: The Nomad Soul', '&quot;I have many things to tell you and very little time… I come from a universe parallel to yours. My world is desperately in need of your help. Only YOU can save us.&quot;Responding to the desperate pleas of a mysterious character from another dimension, your soul must enter the dark and futuristic city of Omikron.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/243000/header.jpg?t=1592492951', 0, 0, NULL);
INSERT INTO games VALUES (58741, 243020, 'Pandemonium', 'Join two kindred spirits, Fargus the Jester and Nikki the acrobat in a fantastic 3D world of magic and mystery as they bounce, tumble and jump through 18 massive and diverse levels in search of the Wishing Engine!Key Features:Fast-paced 3D platform action in a lush, texture-mapped environment.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/243020/header.jpg?t=1592493100', 0, 0, NULL);
INSERT INTO games VALUES (58742, 243040, 'Startopia', 'A once thriving network of space stations and planets have been left lifeless, redundant scars of the apocalypse. Into this age of darkness comes light. You will lead the way in rebuilding the network of space stations to a standard accepted by the individual alien races, attracting them to harness their expertise and research new...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/243040/header.jpg?t=1595800937', 0, 0, NULL);
INSERT INTO games VALUES (58743, 243060, 'Urban Chaos', 'Urban Chaos throws you into the heart of a modern urban jungle at the turn of the millenium. To succeed you''ll need a lethal combination of stealth, physical agility and martial art skills as you interact with the city around you.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/243060/header.jpg?t=1596846329', 0, 0, NULL);
INSERT INTO games VALUES (58744, 243160, 'Mushroom 11', 'An award-winning anti-platformer where destruction is the only way to move. Mold yourself into any form by destroying your cells, and traverse a devastated landscape filled with brain-twisting puzzles and bizarre mutations. Are you ready to break the mold?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/243160/header.jpg?t=1572465769', 0, 0, NULL);
INSERT INTO games VALUES (58745, 243200, 'The Dark Eye: Memoria', 'In Memoria, players travel through different time periods, following two distinct protagonists: Sadja, a southern princess who wants to be a war hero, and Geron, a bird catcher who wants to lift a curse from his girlfriend.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/243200/header.jpg?t=1610644521', 0, 0, NULL);
INSERT INTO games VALUES (58746, 243220, 'FRACT OSC', 'FRACT is a musical exploration game. You arrive in a forgotten place and explore the vast and unfamiliar landscape to discover the secrets of a world built on sound. You rebuild its machinery by solving puzzles and bring the world back to life by shaping sound and creating music in the game.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/243220/header.jpg?t=1715185193', 0, 0, NULL);
INSERT INTO games VALUES (58748, 243360, 'TrackMania² Valley', 'TrackMania² Valley is the third environment of TrackMania², the sequel to Nadeo Studio’s online racing phenomenon TrackMania, already enjoyed by millions of players. Valley is a new take on the classic arcade rally racing genre. Flirting between arcade and simulation, Valley marks a new checkpoint in the history of racing games.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/243360/header.jpg?t=1680016531', 1, 0, NULL);
INSERT INTO games VALUES (58717, 243450, 'Urban Trial Freestyle', 'The city is your playground! Nothing will stop you on your freestyle trials bike. Use the urban landscape to pull spectacular tricks - backflips, 360s, wallrides, ollies, and more. Customize your bike to boost your performance in Time Attack or Stunt mode. Choose between speed and style, developing your own unique riding style.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/243450/header.jpg?t=1712232235', 0, 0, NULL);
INSERT INTO games VALUES (58718, 243470, 'Watch_Dogs™', 'In today''s hyper-connected world, Chicago operates under ctOS, the most advanced computer network in America.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/243470/header.jpg?t=1739177057', 0, 0, NULL);
INSERT INTO games VALUES (58719, 243780, 'PixelJunk™ Monsters Ultimate', 'Tikiman the Forest Defender is in trouble. Hordes of monsters are sweeping through his realm, hoping to chow down on his offspring – and it’s up to you to defend them. By placing weapon towers at strategic points around the landscape, you can destroy the invaders and save the little ones.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/243780/header.jpg?t=1667297961', 0, 0, NULL);
INSERT INTO games VALUES (58720, 243800, 'Gas Guzzlers Extreme', 'Gas Guzzlers Extreme is a fast, furious, armed-to-the-teeth, trigger-happy shooter, shifted into top gear! Take a white knuckle ride in this crazily addictive combat racing game.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/243800/header.jpg?t=1726665808', 0, 0, NULL);
INSERT INTO games VALUES (58722, 243930, 'Bound By Flame', 'You are a mercenary possessed by a flame demon in a desperate world ravaged by seven Ice Lords. In this RPG where every choice counts, you will have to choose between unleashing the powers of the beast within and rejecting its demonic influence.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/243930/header.jpg?t=1650901586', 1, 0, NULL);
INSERT INTO games VALUES (58723, 243970, 'Invisible, Inc.', 'Take control of Invisible''s agents in the field and infiltrate the world''s most dangerous corporations. Stealth, precision, and teamwork are essential in high-stakes, high-profit missions, where every move may cost an agent their life.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/243970/header.jpg?t=1738778734', 0, 0, NULL);
INSERT INTO games VALUES (58724, 244030, 'Take On Mars', 'Take On Mars places you right in the middle of mankind’s most exciting undertaking. Start out in the seat of a rover operator, finish as the first human to have ever set foot on the Red Planet.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/244030/header.jpg?t=1748944279', 0, 0, NULL);
INSERT INTO games VALUES (58725, 244050, 'Rise of Flight United', 'Pilot legendary aircraft of the early years of aviation, French Spad 13, German Albatros D.Va and Russian built Nieuport 17, in the free-to-play Rise of Flight United! This WWI aviation sim that has something for every flight-sim fan, from single player skirmish and career to multiplayer dogfights, but one thing is for certain, the...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/244050/header.jpg?t=1742807805', 0, 1, NULL);
INSERT INTO games VALUES (58726, 244070, 'Sid Meier’s Ace Patrol', 'Battle to Rule the Skies!The skies over Europe are a dangerous place, where ace pilots lead their squadrons to glorious victory or crushing defeat! Take control of dozens of the most famous fighter planes of WWI and head into the dogfight. Roll, slip, and loop to get the drop on enemy aces.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/244070/header.jpg?t=1568756608', 0, 0, NULL);
INSERT INTO games VALUES (58727, 244090, 'Sid Meier’s Ace Patrol: Pacific Skies', 'Battle to Rule the Pacific Skies!Take flight over the treacherous Pacific waters where ace pilots redefine historic World War II battles! Skillfully pilot the most iconic American and Japanese fighter planes of the Pacific War while representing the army or navy.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/244090/header.jpg?t=1568756707', 0, 0, NULL);
INSERT INTO games VALUES (58728, 244160, 'Homeworld Remastered Collection', 'Experience the epic space strategy games that redefined the RTS genre. Control your fleet and build an armada across more than 30 single-player missions. Choose unit types, fleet formations and flight tactics for each strategic situation.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/244160/header.jpg?t=1698168325', 0, 0, NULL);
INSERT INTO games VALUES (58729, 244210, 'Assetto Corsa', 'Assetto Corsa v1.16 introduces the new &quot;Laguna Seca&quot; laser-scanned track, 7 new cars among which the eagerly awaited Alfa Romeo Giulia Quadrifoglio! Check the changelog for further info!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/244210/header.jpg?t=1730473196', 0, 0, NULL);
INSERT INTO games VALUES (58699, 244410, 'Supreme Ruler 1936', 'Real-Time Strategy Game. Guide your nation through the most violent era in modern history. Play massive campaigns as one of the principal nations, set-piece scenarios of famous battles, or set your own victory condition and play as any nation in the world in Sandbox mode.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/244410/header.jpg?t=1560371484', 0, 0, NULL);
INSERT INTO games VALUES (58700, 244430, 'realMyst: Masterpiece Edition', 'Released in 2014, experience one of the first 3D adaptations of the renowned puzzle-adventure game Myst! Each discovery you make, every puzzle you solve, will bring you closer to reversing a wrong that has gone unchecked for ages.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/244430/header.jpg?t=1671038643', 0, 0, NULL);
INSERT INTO games VALUES (58701, 244450, 'Men of War: Assault Squad 2', 'Men of War: Assault Squad 2 features new single player style skirmish modes that take players from extreme tank combat to deadly sniper stealth missions. Commanders can now faceoff against opponents on various new multiplayer 1v1 – 8v8 maps.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/244450/header.jpg?t=1726486647', 0, 0, NULL);
INSERT INTO games VALUES (58702, 244590, 'Epigenesis', 'Epigenesis is an online multiplayer sports/FPS game in which two sides are locked in a never-ending fight for world domination by playing ball.In this non-lethal ballgame of the future, players leap across platforms suspended high up in the air trying to get a ball located in the middle of the arena and score goals against their...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/244590/header.jpg?t=1466107831', 0, 1, NULL);
INSERT INTO games VALUES (58704, 244710, 'Shelter', 'Experience the wild as a badger sheltering your cubs from harm. On your journey, you will be stalked by birds of prey, encounter perils of the night, cross fierce rivers, escape forest fires and face the looming threat of starvation. Food is to be found, but is there enough for everyone?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/244710/header.jpg?t=1737643204', 0, 0, NULL);
INSERT INTO games VALUES (58705, 244730, 'Divekick', 'Divekick is the world’s first two-button fighting game. It distills the essence of the fighting game genre into just two buttons with no d-pad directional movement. Includes two extra playable characters: Fencer from Nidhogg and Johnny Gat from Saints Row!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/244730/header.jpg?t=1696358611', 0, 0, NULL);
INSERT INTO games VALUES (58706, 244750, 'Aztez', 'Aztez is a highly stylized, brutally satisfying beat ''em up set in the world of the Aztec Empire. Take on the role of an elite close combat unit and undergo missions on behalf of the Empire in the turn-based metagame, and fight against warriors and mythological foes alike using 8 unique weapons in real time combat mode.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/244750/header.jpg?t=1501796182', 0, 0, NULL);
INSERT INTO games VALUES (58707, 244770, 'StarMade', 'The ultimate space sandbox. Participate in epic fleet battles, form alliances, strive to dominate entire galaxies and harness the universe’s resources for your industrious empire or the destruction of others. Customise your experience, the universe is yours!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/244770/header.jpg?t=1666989240', 0, 0, NULL);
INSERT INTO games VALUES (58708, 244810, 'Foul Play', 'Play as the daemon-hunter Baron Dashforth in a side-scrolling co-op brawler set entirely on the grand spectacle of a theatre stage that rewards performance over pummeling. Perform shattering takedowns and reversals!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/244810/header.jpg?t=1646934277', 0, 0, NULL);
INSERT INTO games VALUES (128493, 244850, 'Space Engineers', 'Space Engineers is a sandbox game about engineering, construction, exploration and survival in space and on planets. Players build space ships, space stations, planetary outposts of various sizes and uses, pilot ships and travel through space to explore planets and gather resources to survive.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/244850/8b4024ca64963c836319bb89fab74f308f6ace05/header.jpg?t=1745864500', 0, 0, NULL);
INSERT INTO games VALUES (58710, 244870, 'Electronic Super Joy', 'Electronic Super Joy is a brutally hard platformer set in a world of pulse-pounding electronic music. Run, jump, smash &amp; fly your way through 45+ weird &amp; different levels, with low-gravity, world rotation, giant monsters &amp; swarming missiles.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/244870/header.jpg?t=1568997299', 0, 0, NULL);
INSERT INTO games VALUES (58712, 244910, 'Homesick', 'Explore an abandoned building, encountering puzzles and clues to discover what happened, as you try to escape in both your nightmares and the waking world. Be immersed in the hauntingly beautiful 3D atmosphere in this puzzle exploration mystery game.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/244910/header.jpg?t=1447358228', 0, 0, NULL);
INSERT INTO games VALUES (58715, 245150, 'The Novelist', 'The Novelist asks one central question: can you achieve your dreams without pushing away the people you love? The game focuses on Dan Kaplan, a novelist struggling to write the most important book of his career while trying to be the best husband and father he can be.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/245150/header.jpg?t=1702827348', 0, 0, NULL);
INSERT INTO games VALUES (58716, 245170, 'Skullgirls 2nd Encore', '--Main Stage Game at Evo 2022!-- The ultimate Skullgirls experience: Featuring 14 hand-animated characters, fully voiced story mode, countless palettes, and unparalleled GGPO-based multiplayer netcode.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/245170/header.jpg?t=1737508709', 0, 0, NULL);
INSERT INTO games VALUES (58689, 245280, 'ENSLAVED™: Odyssey to the West™ Premium Edition', 'Follow a gripping, surprise-filled journey as two dissimilar characters form an uneasy partnership in order to survive through a perilous, post-apocalyptic America. 150 years in the future, war and destruction have left the world in ruins with few humans remaining and nature having reclaimed the world.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/245280/header.jpg?t=1580374672', 0, 0, NULL);
INSERT INTO games VALUES (58690, 245300, 'Disney Epic Mickey 2:  The Power of Two', 'Unleash the power of the brush in an all new co-op adventure. Join Mickey and Oswald in an epic battle to save the magical world of Wasteland and change it forever. Interact with your favorite characters like never before in the most heroic adventure yet.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/245300/header.jpg?t=1741822630', 0, 0, NULL);
INSERT INTO games VALUES (58691, 245370, 'Etherium', 'Etherium is a real-time strategy game set in a science-fiction universe, where three factions battle it out for a mysterious and rare resource known as ‘Etherium’.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/245370/header.jpg?t=1728650181', 0, 0, NULL);
INSERT INTO games VALUES (58692, 245410, 'Wizardry 6: Bane of the Cosmic Forge', 'FULL-COLOR ANIMATED graphics DIGITIZED sound (NO add-on cards required)HARD DISK supported11 Races, 14 Professions (with rankings!)Weaponry, Physical and Academia SkillsSix Spellbooks, 462 CombinationsNon-Player CharactersAn arsenal of over 400 researched itemsVaried Fighting ModesPrimary and Secondary AttackContinuous JourneyUnlimited...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/245410/header.jpg?t=1676665371', 0, 0, NULL);
INSERT INTO games VALUES (58693, 245430, 'Wizardry 7: Crusaders of the Dark Savant', 'For the First TimeOutdoor CampaignsFull Soundtrack and EffectsTrue Point &amp; Click Mouse InterfaceAuto-MappingUnprecedented Depth of StoryBegin your adventure in Crusaders of the Dark Savant. Import your characters from Bane of the Cosmic Forge or create a new party capable of surviving the rigors of a strange alien world.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/245430/header.jpg?t=1676665410', 0, 0, NULL);
INSERT INTO games VALUES (58694, 245450, 'Wizardry 8', 'A New Wizardry for a New GenerationThe universe is in the throes of violent upheaval and change. Vast and mysterious forces are preparing for the final confrontation. A small group of heroes from distant lands must plunge into the heart of the maelstrom, to uncover long-forgotten secrets, and bring about a new era.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/245450/header.jpg?t=1676665352', 0, 0, NULL);
INSERT INTO games VALUES (58695, 245470, 'Democracy 3', 'Have you ever wanted to be president? or prime-minister? Convinced you could do a better job of running the country? Let''s face it, you could hardly do a worse job than our current political leaders.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/245470/header.jpg?t=1728241133', 0, 0, NULL);
INSERT INTO games VALUES (58696, 245490, 'Trials Fusion™', 'Trials Fusion is the gold-standard platform racer for the next-generation of gaming. Built upon the Trials franchise’s proven gameplay foundations, Fusion challenges players endlessly in both classic and all-new ways.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/245490/header.jpg?t=1747656869', 0, 0, NULL);
INSERT INTO games VALUES (58697, 245620, 'Tropico 5', 'Return to the remote island nation of Tropico and expand your Dynasty’s reign from the early colonial period to beyond the 21st Century, facing new challenges including advanced trading mechanics, technology and scientific research, as well as cooperative and competitive MULTIPLAYER.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/245620/header.jpg?t=1730814202', 0, 0, NULL);
INSERT INTO games VALUES (58698, 245730, 'Flashback', '20 years after the original game’s launch, Conrad is enlisted back to active service for the triumphant return of one of the most acclaimed franchises in gaming history.It’s not a reboot. It’s Flashback re-imagined.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/245730/header.jpg?t=1679996337', 0, 0, NULL);
INSERT INTO games VALUES (58681, 246070, 'Hack ''n'' Slash', 'Hack ‘n’ Slash is a puzzle action game about hacking -- reprogram object properties, hijack global variables, hack creature behavior, and even rewrite the game’s code. The only way to win is not to play...by the rules!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/246070/header.jpg?t=1727389160', 0, 0, NULL);
INSERT INTO games VALUES (58682, 246090, 'Spacebase DF-9', 'In Spacebase DF-9, you''ll build a home among the stars for a motley population of humans and aliens as they go about their daily lives. Mine asteroids, discover derelicts, and deal with the tribulations of galactic resettlement in Earth''s distant future.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/246090/header.jpg?t=1727389223', 0, 0, NULL);
INSERT INTO games VALUES (58683, 246110, 'MASSIVE CHALICE', 'MASSIVE CHALICE is a tactical strategy game set on an epic timeline from Double Fine Productions. As the Immortal Ruler of the nation, you''ll take command of its heroes, forge heroic marriages to strengthen your Bloodlines, and battle a mysterious enemy known as the Cadence in a 300 year war.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/246110/header.jpg?t=1727390984', 0, 0, NULL);
INSERT INTO games VALUES (58684, 246300, 'Paranormal', 'Experience the horrors of a haunting that''s never the same twice. Paranormal is a 3D fully dynamic haunting experience. The player takes the role of Mattel Clarke, an artist who has a haunted house. Mattel decides to film the hauntings with his camera, which is the viewpoint of the game.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/246300/header.jpg?t=1593441480', 0, 0, NULL);
INSERT INTO games VALUES (58686, 246420, 'Kingdom Rush  - Tower Defense', 'Get ready for an epic journey to defend your kingdom against hordes of orcs, trolls, evil wizards and other nasty fiends using a vast arsenal of towers and spells at your command!Fight on forests, mountains and wastelands, customizing your defensive strategy with different tower upgrades and specializations!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/246420/header.jpg?t=1739880223', 1, 0, NULL);
INSERT INTO games VALUES (58687, 246580, 'The Typing of The Dead: Overkill', 'Typing of the dead: Overkill fuses the horror and comedy of the legendary House of the Dead series with unique typing mechanics in order to deliver a truly original gaming experience! This gruesome shooter puts you in the middle of a mutant outbreak in Bayou county.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/246580/header.jpg?t=1603130707', 0, 0, NULL);
INSERT INTO games VALUES (58688, 246620, 'Plague Inc: Evolved', 'Plague Inc: Evolved is a unique mix of high strategy and terrifyingly realistic simulation. Your pathogen has just infected ''Patient Zero'' - now you must bring about the end of human history by evolving a deadly, global Plague whilst adapting against everything humanity can do to defend itself.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/246620/header.jpg?t=1749032348', 1, 0, NULL);
INSERT INTO games VALUES (58669, 246840, 'FATE', 'Play (or Re-play) This Classic Dungeon Crawler!During the golden days of action RPGs, FATE was a powerhouse, winning runner-up for PC Magazine’s Role-Playing Game of the year. Popular enough to spawn 3 sequels, this was one of the premier dungeon crawlers of its time.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/246840/header.jpg?t=1731926322', 0, 0, NULL);
INSERT INTO games VALUES (58671, 246900, 'Viscera Cleanup Detail', 'In Viscera Cleanup Detail, you step into the boots of a space-station janitor tasked with cleaning up after various horrific sci-fi horror events. Instead of machineguns and plasma-rifles, your tools are a mop and bucket. That hero left a mess, and it''s up to you to deal with the aftermath.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/246900/header.jpg?t=1666984711', 0, 0, NULL);
INSERT INTO games VALUES (58673, 246940, 'Lords of the Black Sun', 'Take command of one race to join the struggle for supremacy in the galaxy. As the leader of your empire you are tasked with exploring the stars, colonizing new worlds, managing your empire and conquering whoever dares to oppose you.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/246940/header.jpg?t=1578330560', 0, 0, NULL);
INSERT INTO games VALUES (58674, 246960, 'Giana Sisters: Twisted Dreams - Rise of the Owlverlord', 'Giana Sisters: Twisted Dreams - Rise of the Owlverlord is a blistering platformer with morphing worlds, featuring seven brand new levels, a new boss and new gripping tracks from Chris Hülsbeck and Machinae Supremacy! Dash through tricky levels and transform the whole world at will in this fast-paced platformer.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/246960/header.jpg?t=1736956676', 0, 0, NULL);
INSERT INTO games VALUES (58676, 247000, 'Talisman: Digital Classic Edition', 'The officially licensed multiplayer version of the classic fantasy adventure board game, Talisman, based on the 4th Edition of the game. On your travels, you will need strength, courage and some good dice rolls to survive the dangers you face and beat your opponents to the centre of the board!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/247000/header.jpg?t=1740585372', 0, 0, NULL);
INSERT INTO games VALUES (58677, 247020, 'Cook, Serve, Delicious!', 'One of the few hardcore restaurant sims in existence, Cook, Serve, Delicious! is a deceptively easy game to learn but incredibly challenging to master as you progress through your career from owning a terrible zero star cafe into a five star world famous restaurant.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/247020/header.jpg?t=1745434129', 0, 0, NULL);
INSERT INTO games VALUES (58678, 247080, 'Crypt of the NecroDancer', 'Crypt of the NecroDancer is an award winning hardcore roguelike rhythm game. Move to the music and deliver beatdowns to the beat! Groove to the epic Danny Baranowsky soundtrack, or select songs from your own MP3 collection!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/247080/header.jpg?t=1745447262', 1, 0, NULL);
INSERT INTO games VALUES (58679, 247140, 'Soundodger+', 'Dodge the music and dance through a mesmerizing ballet of choreographed bullets, each synced to music from over a dozen international artists. Push your creativity and skills with the fully-featured Level Editor and never run out of things to dodge.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/247140/header.jpg?t=1719713949', 0, 0, NULL);
INSERT INTO games VALUES (58680, 247240, 'Volgarr the Viking', 'Return to the Golden Age of arcades with a hardcore action platformer that pulls no punches! Possesses all the hallmarks of true classics like Super Ghouls ''N Ghosts (SNES), Rastan Saga (Arcade), Castlevania (NES) and more with precise controls, high challenge, and meticulous design.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/247240/header.jpg?t=1717702867', 0, 0, NULL);
INSERT INTO games VALUES (58657, 247350, 'Artemis Spaceship Bridge Simulator', 'Artemis is designed for anyone who watched Star Trek and dreamed of what it would be like to sit on the bridge of a star ship. Artemis simulates a spaceship bridge by networking several computers together. You cannot play Artemis single-player!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/247350/header.jpg?t=1518791376', 0, 0, NULL);
INSERT INTO games VALUES (58658, 247370, 'Mutant Mudds Deluxe', 'Love pixels? Fond of platformers? Is there a special place in your heart for the 8-bit and 16-bit era? Want to have fun? Yes!? Well, you’ve come to the right place, my friend. Mutant Mudds Deluxe is a “12-bit” action platformer full of pixels and platforming fun!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/247370/header.jpg?t=1732336528', 0, 0, NULL);
INSERT INTO games VALUES (58659, 247430, 'Hitman: Contracts', 'Enter the world of a HITMAN - a world of crime, sin and greed. Delve into the mind of Agent 47 and encounter his greatest adversaries, completing the work that made him so brutally efficient and shaped him as an assassin. Eliminate your targets by any means necessary. There are no rules... only the contract, signed in blood.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/247430/header.jpg?t=1744238518', 0, 0, NULL);
INSERT INTO games VALUES (58660, 247660, 'Deadly Premonition: The Director''s Cut', 'Play as special agent Francis York Morgan in this open-world action-adventure as you solve the case of the Red Seed Murders and survive in a small, quirky American mountain town where supernatural creatures and a mysterious raincoat-clad, axe-wielding killer seek to end his investigation for good.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/247660/header.jpg?t=1728655653', 0, 0, NULL);
INSERT INTO games VALUES (58662, 247870, 'Redshirt', 'Redshirt is the comedy sci-fi sim about social networking aboard a space station, starring the station''s most ambitious low-ranking peon: you! Navigate the professional and interpersonal politics of the ubiquitous &quot;Spacebook&quot; to curry favor among friends and colleagues.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/247870/header.jpg?t=1726039757', 0, 0, NULL);
INSERT INTO games VALUES (58663, 247910, 'Sniper Elite: Nazi Zombie Army 2', '** Please note: a remastered and improved edition of this game is now available in Zombie Army Trilogy.**Experience a terrifyingly intense co-op campaign for up to four players in this gut-wrenching sequel to Steam best-seller, Sniper Elite: Nazi Zombie Army.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/247910/header.jpg?t=1589878293', 0, 0, NULL);
INSERT INTO games VALUES (58664, 247950, 'Sacred 3', 'Sacred 3 is an arcade Hack ‘n’ Slash game for up to 4 players. Choose a hero and fight cooperatively against the rise of evil. Victory is Ours. Glory is Mine.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/247950/header.jpg?t=1649170805', 0, 0, NULL);
INSERT INTO games VALUES (58638, 248170, 'Clickteam Fusion 2.5', 'Game and software creation has never been easier or quicker than with Clickteam Fusion 2.5! Discover the tool used by so many multimedia professionals, game creators, and creative people from all walks of life.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/248170/header.jpg?t=1668809964', 0, 0, NULL);
INSERT INTO games VALUES (58639, 248190, 'Knytt Underground', 'The legendary Knytt series continues with Nifflas’ latest creation; Knytt Underground. In this Knytteration; humans have long since abandoned the planet after practically destroying it in a war, five hundred years ago.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/248190/header.jpg?t=1667318301', 0, 0, NULL);
INSERT INTO games VALUES (58640, 248290, 'Reach for the Sun', 'Version 1.2 Out Now!Strategy mode is now available on the plant selection screenThis mode uses a set number of turns with no time limit. Plants will automatically collect resources between turns. Keep your plant balanced and try to maximize your resources on every turn to fruit each flower before winter comes!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/248290/header.jpg?t=1629230392', 0, 0, NULL);
INSERT INTO games VALUES (58641, 248310, 'Freedom Planet', 'Fight your way across the celestial world of Avalice where cats are green, motorcycles drive up walls and monster girls do most of the buttkicking! Freedom Planet is a cartoony, combat-based platform adventure that pits a spunky dragonoid and her friends against an alien attack force.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/248310/header.jpg?t=1745527925', 1, 0, NULL);
INSERT INTO games VALUES (58642, 248330, 'Dino Run DX', 'DINOSAURS. PIXELS. PYROCLASTIC DOOM WALLS. MASSIVE INDIE CROSSOVERS. Dino Run DX has all of that and more. Come rediscover the original runner and escape extinction all over again.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/248330/header.jpg?t=1747663360', 0, 0, NULL);
INSERT INTO games VALUES (58643, 248350, 'Omegalodon', 'Omegalodon is a third-person multiplayer action game where players compete by attacking/defending the city. The Red Team is comprised of police and soldiers armed with an array of military vehicles and explosive weaponry. The Green Team is comprised of Omegalodon, a 100-foot shark monster, and the Enviros, equipped with a healing beam.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/248350/header.jpg?t=1447358441', 0, 0, NULL);
INSERT INTO games VALUES (58645, 248390, 'Craft The World', 'Craft The World is a unique sandbox strategy game, the mix of Dungeon Keeper, Terraria and Dwarf Fortress. Explore a random generated world populated by dangerous creatures, build a dwarf fortress, gather resources, and craft all the items, weapons, and armor you need.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/248390/header.jpg?t=1747907043', 1, 0, NULL);
INSERT INTO games VALUES (58646, 248450, 'Salvation Prophecy', 'Salvation Prophecy is a military space epic. Human, mutant, and robotic factions are at war for galactic domination. Battles rage as space fleets collide. Invaders clash against fortified enemy colonies. Yet the greatest danger is the impending annihilation foretold by an apocalyptic prophecy.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/248450/header.jpg?t=1489426973', 0, 0, NULL);
INSERT INTO games VALUES (58647, 248470, 'Doorways: Prelude', 'Doorways is an immersive horror adventure, featuring a complex story and deep atmosphere.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/248470/header.jpg?t=1724087882', 0, 0, NULL);
INSERT INTO games VALUES (58651, 248550, 'Megabyte Punch', 'Megabyte Punch is a fighting/beat ‘em up game in which you build your own fighter! As you travel through different environments, you battle other creatures to get their parts. Parts have their own powers and bonuses, like gun arms for a shoot ability or powerful hips for a devastating pelvic thrust attack.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/248550/header.jpg?t=1667226801', 0, 0, NULL);
INSERT INTO games VALUES (58653, 248610, 'Door Kickers', 'Door Kickers is an innovative realtime strategy game that puts you in charge of a SWAT team and lets you command them during a tactical intervention.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/248610/header.jpg?t=1725309217', 0, 0, NULL);
INSERT INTO games VALUES (58654, 248710, 'Iesabel', 'In the times of darkness, only the mightiest of heroes can save the world. Stand out against the evil all by yourself in epic single player mode. Swarms of bloodthirsty monsters, loads of epic gear to collect, dozens of skills to obtain. Grab your sword and fling yourself into action now!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/248710/header.jpg?t=1568803228', 0, 0, NULL);
INSERT INTO games VALUES (58655, 248730, 'A Walk in the Dark', 'In this action platformer you play as a cat, Bast, running through a dark fantasy world. You’ll be running, jumping and sliding with smooth and precise controls designed to make you feel like a cat. But it wont be easy. In the dark you never know what lies in the shadows.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/248730/header.jpg?t=1667158666', 0, 0, NULL);
INSERT INTO games VALUES (58635, 248800, 'Dysfunctional Systems: Learning to Manage Chaos', 'From Dischan Media, creators of the highly acclaimed Juniper''s Knot, comes Dysfunctional Systems: Learning to Manage Chaos.Dysfunctional Systems is a visual novel series featuring Winter Harrison, a student mediator from a utopian world. Learning to Manage Chaos is the first entry in the series.What is a mediator?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/248800/header.jpg?t=1669298710', 0, 0, NULL);
INSERT INTO games VALUES (58636, 248820, 'Risk of Rain (2013)', 'Risk of Rain is an action platformer with roguelike elements. With permanent death as a primary feature, players will have to play their best to get as far as possible. Fight on a mysterious planet with randomly spawning enemies and bosses, either alone or with 3 friends in online co-op.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/248820/header.jpg?t=1749246192', 0, 0, NULL);
INSERT INTO games VALUES (58637, 248860, 'NEO Scavenger', 'NEO Scavenger is a game where you must survive in the wasteland long enough to figure out who you are. Each turn, you must decide where to go, how to scavenge for supplies, and how to deal with anything and anyone you encounter.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/248860/header.jpg?t=1748455771', 0, 0, NULL);
INSERT INTO games VALUES (58630, 248970, 'Vector', 'Vector is an exciting, arcade-style game featuring you as the exceptional free runner who won’t be held down by the system. In this totalitarian world freedom and individually is nothing more than a distant dream. But the heart of a freerunner is strong, and so you break free.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/248970/header.jpg?t=1728651356', 1, 0, NULL);
INSERT INTO games VALUES (58631, 249050, 'Dungeon of the ENDLESS™', 'Dungeon of the ENDLESS™ is a Rogue-Like Dungeon-Defense game, in which the player and their team of heroes must protect the generator of their crashed ship while exploring an ever-expanding dungeon, all while facing waves of monsters and special events as they try to find their way out...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/249050/header.jpg?t=1689949161', 0, 0, NULL);
INSERT INTO games VALUES (58632, 249130, 'LEGO® Marvel™ Super Heroes', 'LEGO® Marvel™ Super Heroes features an original story crossing the entire Marvel Universe. Players take control of Iron Man, Spider-Man, the Hulk, Captain America, Wolverine and many more Marvel characters as they unite to stop Loki and a host of other Marvel villains from assembling a super-weapon capable of destroying the world.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/249130/header.jpg?t=1745537557', 0, 0, NULL);
INSERT INTO games VALUES (58633, 249190, 'Ancient Space', 'Ancient Space is a story driven single player real time strategy game where you take command of a fleet embarking on a scientific mission to chart undiscovered reaches of space called ‘The Black Zone’. Overcome overwhelming odds and fight for your life and the survival of your ship and its crew.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/249190/header.jpg?t=1709830515', 0, 0, NULL);
INSERT INTO games VALUES (58634, 249230, 'Risen 3 - Titan Lords', 'The world has been abandoned by its gods and is scarred from the rampage of the Titans. Humanity is struggling to regain strength. You, however, have more pressing concerns: your own life has been shattered and you must set off to reclaim what is lost amidst the darkness spreading throughout the world.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/249230/header.jpg?t=1601972818', 0, 0, NULL);
INSERT INTO games VALUES (58619, 249330, 'Unholy Heights', 'Welcome to Unholy Heights, a mashup of Tower Defense and Apartment Management Simulation!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/249330/header.jpg?t=1728448231', 0, 0, NULL);
INSERT INTO games VALUES (58620, 249360, 'Zafehouse: Diaries', 'Stuck in a remote, abandoned town, you must lead five survivors with conflicting motivations, fragile relationships and fiery prejudices to safety from the roving undead. A sophisticated engine generates new survivors, towns and content so every adventure is a different experience, and you can use built-in editors to add yourself and...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/249360/header.jpg?t=1707437841', 0, 0, NULL);
INSERT INTO games VALUES (58621, 249550, 'NEStalgia', 'NEStalgia is an original MORPG inspired by the glory days of traditional console RPGs. Essentially &quot;Dragon Warrior 3 meets World of Warcraft&quot;, NEStalgia is an amalgam of the best generations of RPG gaming. You can play solo, in private games with friends, or online with hundreds of other players!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/249550/header.jpg?t=1478229593', 0, 0, NULL);
INSERT INTO games VALUES (58622, 249570, 'The Castle Doctrine', 'The Castle Doctrine is a massively-multiplayer game of burglary and home defense. It''s 1991, and things are bad. You''re a guy with a house and family. Other players are coming to take what''s yours. Build security to stop them. Study their houses, buy tools, and break in to take what''s theirs.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/249570/header.jpg?t=1724974424', 0, 0, NULL);
INSERT INTO games VALUES (58623, 249590, 'Teslagrad', 'A journey begins... A treacherous tower... Unravel its mysteries!Discover the secrets kept in the long abandoned Tesla Tower!Magnetism and other electromagnetic powers will help you explore a non-linear world of beautiful hand-drawn environments, in a steampunk-inspired vision of old Europe.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/249590/header.jpg?t=1710497488', 0, 0, NULL);
INSERT INTO games VALUES (58625, 249630, 'Delver', 'Delve into the shifting dungeons on your hunt for the Yithidian orb, but getting it might just be the easy part. Delver is a single player first-person action roguelike dungeon crawler, just like you wished they used to make.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/249630/header.jpg?t=1626454365', 0, 0, NULL);
INSERT INTO games VALUES (58626, 249650, 'Blackguards', 'What happens when the only hope of a threatened world lies not with heroes in shining armor, but in the hands of a band of misfits and criminals? Blackguards, a new turn-based strategy RPG, explores this very question. You will discover over 180 unique hex-based battlegrounds within a dark and mature story of crime, drugs, and murder.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/249650/header.jpg?t=1736357228', 1, 0, NULL);
INSERT INTO games VALUES (58627, 249680, 'Marlow Briggs and the Mask of Death', 'A new breed of WARRIOR returns, committed to destroying the enemies of FREEDOM When ONE angry man, has a world to protect - There is only ONE future – HIS OWN No-nonsense hero Marlow never shied away from danger or trouble. But now he faces his ULTIMATE challenge.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/249680/header.jpg?t=1447358520', 0, 0, NULL);
INSERT INTO games VALUES (58628, 249870, 'Scribblenauts Unmasked: A DC Comics Adventure', 'In Scribblenauts Unmasked: A DC Comics Adventure, Maxwell unites with Batman™, Superman™ and the rest of The Justice League™ to restore order to the DC Comics Universe. Challenge your imagination as you battle the mightiest villains in an exciting, action-filled adventure through GOTHAM CITY™, METROPOLIS™, ATLANTIS™ and other iconic...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/249870/header.jpg?t=1729804459', 0, 0, NULL);
INSERT INTO games VALUES (58593, 249950, 'Forge Quest', 'Forge Quest is a dungeon crawling rpg set in a voxel world. Explore the land full of chickens on a light hearted quest to become a hero. Delve deep into the randomly generated dungeons to battle monsters, find treasure and craft your equipment. Invite your friends to join your world and help you in your adventure.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/249950/header.jpg?t=1675390086', 0, 0, NULL);
INSERT INTO games VALUES (58594, 249990, 'FORCED: Slightly Better Edition', 'FORCED is a challenging 1-4-player game with co-op at its heart! A mix of tactical arcade action, RPG elements and puzzles will forge you and your friends together. As slaves in the toughest gladiator school of them all, you will face a plethora of unique trials - designed to be your death!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/249990/header.jpg?t=1667808676', 0, 0, NULL);
INSERT INTO games VALUES (58595, 250030, 'Lilly Looking Through', 'What Lilly sees is about to change her life forever.... Help our heroine through a variety of enchanting environments brimming with magic and wonder, as she seeks to rewrite the past, change the present, and unlock the ultimate mystery. Geeta Games presents an animated point-and-click adventure for all ages: Lilly Looking Through.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/250030/header.jpg?t=1447358562', 0, 0, NULL);
INSERT INTO games VALUES (58596, 250050, 'Life Goes On: Done to Death', 'A comical puzzle platformer where you must die to progress. The bodies you leave behind are your only tools to solve puzzles on your quest to find the Cup of Life.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/250050/header.jpg?t=1749359641', 1, 0, NULL);
INSERT INTO games VALUES (58598, 250110, 'Assault Android Cactus+', 'Assault Android Cactus is an intense arcade style twin stick shooter - pick from one of nine unique synthetic heroines and blast your way through overwhelming robots hordes to save the ship from its own workforce. Supports single player and local co-op game modes.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/250110/header.jpg?t=1744898145', 0, 0, NULL);
INSERT INTO games VALUES (58599, 250180, 'METAL SLUG 3', '“METAL SLUG 3”, the masterpiece in SNK’s emblematic 2D run &amp; gun action shooting game series, still continues to fascinate millions of fans worldwide to this day for its intricate dot-pixel graphics, and simple and intuitive game controls, heads out to the Steam gaming platform!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/250180/header.jpg?t=1727159336', 1, 0, NULL);
INSERT INTO games VALUES (58600, 250260, 'Jazzpunk: Director''s Cut', 'Jazzpunk is a comedy adventure set in an alternate reality Cold War World, plagued with corporate espionage, CyberCrime, and sentient martinis. Gameplay is inspired by spoof comedy films and cartoons of yesteryear, with a focus on weird gadgets, exotic locales, and open-world style exploration.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/250260/header.jpg?t=1710253452', 0, 0, NULL);
INSERT INTO games VALUES (58601, 250320, 'The Wolf Among Us', 'From the makers of the 2012 Game of the Year: The Walking Dead, comes a thriller based on the award-winning Fables comic books. As Bigby Wolf you will discover that a brutal, bloody murder is just a taste of things to come in a game series where your every decision can have enormous consequences.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/250320/header.jpg?t=1734104991', 0, 0, NULL);
INSERT INTO games VALUES (58602, 250340, 'Blockland', 'Blockland is a non-linear sandbox game with no set goals, giving players the freedom to design and construct elaborate structures. Styled as a tiny minifigure, players build inside of the virtual world using bricks reminiscent of toy blocks.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/250340/header.jpg?t=1724376947', 0, 0, NULL);
INSERT INTO games VALUES (58604, 250380, 'Knock-knock', 'There is an unusual cabin deep in the woods. It had served as a laboratory and a dwelling for three generations of Lodgers.But as of late the latest Lodger has been noticing weird changes in familiar surroundings; things are missing, noises and rattle heard. Something odd is coming out of the woods.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/250380/header.jpg?t=1669134410', 0, 0, NULL);
INSERT INTO games VALUES (58605, 250400, 'How to Survive', '“A real Gem” – Destructoid at E3 “Offers a different experience for zombie game veterans” – Co-Optimus“Has a lot more going for it than smashing brains and gory, red goo ... With a surprisingly deep crafting system” – GamesRadarYou''re shipwrecked on an isolated island, a desperate castaway in a total freakshow world. How will you survive?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/250400/header.jpg?t=1570016597', 0, 0, NULL);
INSERT INTO games VALUES (58607, 250500, 'Super Amazing Wagon Adventure', 'Super Amazing Wagon Adventure is a fast-paced 2d shooting game with a random story. You control a group of three migrants traveling west along a wagon trail. The game consists of short scenes that are sequenced together in a semi-random way to tell a crazy adventure story.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/250500/header.jpg?t=1742839859', 0, 0, NULL);
INSERT INTO games VALUES (58608, 250520, 'UnderRail', 'Underrail is an old school turn-based isometric indie role playing game that focuses on exploration and combat. The game is set in a distant future, when the life on the Earth’s surface has long since been made impossible and the remnants of humanity now dwell in the Underrail, a vast system of metro station-states that, it seems, are...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/250520/header.jpg?t=1728564887', 0, 0, NULL);
INSERT INTO games VALUES (58610, 250560, 'Fight The Dragon', 'A COMMUNITY CREATED Hack''n Slash RPG where players can team up and tackle exciting adventures made by other community members in our in-game Adventure Construction Kit - It''s DIABLO meets LITTLE BIG PLANET!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/250560/header.jpg?t=1493098267', 0, 0, NULL);
INSERT INTO games VALUES (58611, 250580, 'Paranautical Activity: Deluxe Atonement Edition', 'Paranautical Activity combines the classic FPS action of games like Doom and Quake, with the randomness and difficulty of modern roguelikes like Binding of Isaac and Spelunky.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/250580/header.jpg?t=1593028220', 0, 0, NULL);
INSERT INTO games VALUES (58613, 250620, 'Among the Sleep - Enhanced Edition', 'Among the Sleep: Enhanced Edition is a new and improved version of the award winning first person horror adventure. In the game you play as a small child trapped in a weird nightmare where you go looking for your mom.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/250620/header.jpg?t=1678873027', 0, 0, NULL);
INSERT INTO games VALUES (58614, 250640, '[Old Edition] Croixleur Sigma', 'Wielding magical blades, four girls fight back encroaching waves of monsters in this exhilirating hack &amp; slash action game!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/250640/header.jpg?t=1574755420', 0, 0, NULL);
INSERT INTO games VALUES (58615, 250660, 'Bunny Must Die! Chelsea and the 7 Devils', 'From the creator of the Gundemonium Collection comes a thrilling new 2D action-platformer! Help Bunny escape the Devils’ Labyrinth and defeat the 7 Devils in this hilariously over-the-top action-platformer game. Battle through a large, connected map filled with unique enemies, traps, and puzzles.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/250660/header.jpg?t=1564702619', 0, 0, NULL);
INSERT INTO games VALUES (58616, 250700, 'Super Time Force Ultra', 'Super Time Force Ultra is an insane platformer filled with robots and dinosaurs and fun and time travel... sometimes all at the same time!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/250700/header.jpg?t=1746133326', 0, 0, NULL);
INSERT INTO games VALUES (58618, 250760, 'Shovel Knight: Treasure Trove', 'Shovel Knight: Treasure Trove is the complete Shovel Knight collection, containing all 5 games in the epic saga! Dig, blast, slash, and bash your way through a fantastical, 8-bit inspired world of pixel-perfect platforming, memorable characters, and world-class action-adventure gameplay.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/250760/header.jpg?t=1723577994', 1, 0, NULL);
INSERT INTO games VALUES (127714, 250900, 'The Binding of Isaac: Rebirth', 'The Binding of Isaac: Rebirth is a randomly generated action RPG shooter with heavy Rogue-like elements. Following Isaac on his journey players will find bizarre treasures that change Isaac’s form giving him super human abilities and enabling him to fight off droves of mysterious creatures, discover secrets and fight his way to safety.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/250900/header.jpg?t=1731977365', 0, 0, NULL);
INSERT INTO games VALUES (58575, 251060, 'Wargame: Red Dragon', 'The new reference in RTS at its best! The Wargame series returns to duty, larger, richer and more spectacular than ever before. In Wargame Red Dragon, you are engaged in a large-scale conflict where Western forces clash against the Communist bloc.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/251060/header.jpg?t=1725003090', 1, 0, NULL);
INSERT INTO games VALUES (58576, 251110, 'INFRA', 'INFRA puts you into the boots of a structural analyst on a routine mission. Quickly though, your task turns into a fight for survival, all caused by deep-rooted schemes of the past. Your tools are simple: your camera and the wits to navigate a labyrinth of debris.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/251110/header.jpg?t=1693680015', 1, 0, NULL);
INSERT INTO games VALUES (58577, 251150, 'The Legend of Heroes: Trails in the Sky', 'Hailed as one of the largest, longest and most meticulously detailed turn-based JRPG series of all time, this first chapter in the ongoing Trails saga sets the stage for what''s quickly become Ys developer Nihon Falcom''s most popular and best-selling franchise in their entire 30+ year history.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/251150/header.jpg?t=1740447099', 0, 0, NULL);
INSERT INTO games VALUES (58578, 251170, 'Damned', 'Damned is a randomized online horror game for up to 5 players (4 survivors and 1 monster). You’ll be able to play as one of four people trapped in different haunted places (hotels, hospitals, etc).', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/251170/header.jpg?t=1712854142', 0, 0, NULL);
INSERT INTO games VALUES (58579, 251210, 'Hive', 'Officially licensed version of the &quot;Mensa Select&quot; award-winning board game! Hive is a board game with a difference. There is no board! The pieces are added to the playing area thus creating the board.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/251210/header.jpg?t=1483560538', 0, 0, NULL);
INSERT INTO games VALUES (58580, 251230, 'Livelock', 'Livelock is a co-operative top-down shooter where you play solo or with up to two allies to break the cycle of infinite war between machines. As one of the remaining Capital Intellects, your role is to unlock Eden and revive humanity.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/251230/header.jpg?t=1712608261', 0, 0, NULL);
INSERT INTO games VALUES (58581, 251270, 'Corpse Party', 'A group of friends unknowingly perform an occult ritual that traps them in an otherworldly elementary school. Here, the vengeful spirits of young children threaten their lives and their sanity, and the only hope of survival is to uncover the chilling details behind the murders of those trapped before them...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/251270/header.jpg?t=1740426499', 0, 0, NULL);
INSERT INTO games VALUES (58582, 251290, 'The Legend of Heroes: Trails in the Sky SC', 'Picking up shortly after The Legend of Heroes: Trails in the Sky, Estelle travels across Liberl in search of Joshua. The journey involves more than seeking loved ones, however, as the Bracer Guild also tasks her with unraveling the mysteries behind the newly unveiled Society of Ouroboros.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/251290/header.jpg?t=1740438857', 0, 0, NULL);
INSERT INTO games VALUES (58584, 251370, 'Escape Goat', 'Escape Goat is a puzzle platformer where you take control of a goat, who has been imprisoned for witchcraft, and overcome traps and obstacles to escape the Prison of Agnus. Fear not, for with your supreme agility, sturdy horns, and the help of a magic mouse friend, you can turn the tables on foes and use the environment to your advantage.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/251370/header.jpg?t=1668622448', 0, 0, NULL);
INSERT INTO games VALUES (58585, 251410, 'Dark Matter', 'Dark Matter is a 2.5D side-scrolling survival horror game, set in a derelict spaceship besieged by a sinister alien presence, and infested with deadly parasites. As the Ensign, you must explore fetid hallways and abandoned facilities, scavenging for parts and blueprints, expanding your arsenal to up to four deadly weapons and freely...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/251410/header.jpg?t=1725032809', 0, 0, NULL);
INSERT INTO games VALUES (58586, 251430, 'The Inner World', 'The Inner World – A 2D-Point’n’Click Adventure Together with the help of the mysterious thief Laura, his best intentions and no clue whatsoever, Robert sets off on his adventure to discover the secret of the wind''s disappearance. Will the young adventurer be able to save his world?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/251430/header.jpg?t=1717679220', 0, 0, NULL);
INSERT INTO games VALUES (58588, 251470, 'TowerFall Ascension', 'TowerFall Ascension is the definitive version of the hit archery combat game. Inspired by classics from the golden age of couch multiplayer, it''s a 4-player local party game centering around hilarious, intense versus matches. The core mechanics are simple and accessible, but hard to master and combat is fierce.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/251470/header.jpg?t=1715114308', 0, 0, NULL);
INSERT INTO games VALUES (58589, 251490, 'Gravity Ghost', 'Gravity Ghost is a physics game with a twist. Run, jump, and soar around planets, using gravity to glide through the air. Explore a shattered galaxy and rescue its survivors, armed with powerups and mysterious terraforming powers. Meet the 7 magical guardians and best their challenges. There''s no killing, no dying, and no way to fail.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/251490/header.jpg?t=1447358644', 0, 0, NULL);
INSERT INTO games VALUES (132105, 251570, '7 Days to Die', '7 Days to Die is an open-world game that is a unique combination of first-person shooter, survival horror, tower defense, and role-playing games. Play the definitive zombie survival sandbox RPG that came first. Navezgane awaits!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/251570/header.jpg?t=1746547982', 1, 0, NULL);
INSERT INTO games VALUES (58541, 251630, 'The Impossible Game', 'The super-addictive and very, very hard platform game finally arrives on Steam - it''s quite possibly the world''s hardest game! As well as five classic Impossible Game levels, this desktop version includes an EXCLUSIVE new Level Editor.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/251630/header.jpg?t=1711724959', 0, 0, NULL);
INSERT INTO games VALUES (58543, 251690, 'Speedball 2 HD', 'Speedball 2 HD is a modern reincarnation on the classic, futuristic cyberpunk sports game Speedball, originally developed by the Bitmap Brothers and first released for the Atari ST in 1990. A brutal mix of handball and ice hockey placed at break-neck pace.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/251690/header.jpg?t=1607939946', 0, 0, NULL);
INSERT INTO games VALUES (58544, 251730, 'Legend of Grimrock 2', 'Legend of Grimrock 2 is a dungeon crawling role playing game with a modern execution but an oldschool heart. A group of four prisoners have shipwrecked on the secluded Isle of Nex. The island is filled with ancient crumbled ruins, mysterious shrines and a vast underground network of dungeons.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/251730/header.jpg?t=1447358653', 0, 0, NULL);
INSERT INTO games VALUES (58545, 251810, 'Leadwerks Game Engine', 'Leadwerks Game Engine is the easiest way to make 3D games and VR experiences. Learn everything you need with our comprehensive tutorials. Build games with the world''s most intuitive game development system. Sell your games with a royalty-free license or share them with the world for free.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/251810/header.jpg?t=1739165818', 0, 0, NULL);
INSERT INTO games VALUES (58546, 251830, 'Stick it to The Man!', 'Hard hat tester, Ray, has a bizarre accident and wakes up with a giant pink spaghetti arm sticking out of his brain! With his awesome new powers he can read minds and change the world with stickers but he’s on the run for a crime he didn’t commit. Can you help Ray out of this sticky situation?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/251830/header.jpg?t=1592572419', 0, 0, NULL);
INSERT INTO games VALUES (58547, 251850, 'Master Reboot', 'Imagine a world where death is no longer final, where precious memories are saved to enjoy forever, where your soul is immortal. Master Reboot is a haunting first-person sci-fi adventure.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/251850/header.jpg?t=1727964678', 0, 0, NULL);
INSERT INTO games VALUES (58548, 251870, 'Go! Go! Nippon! ~My First Trip to Japan~', 'The week you spend in Japan will certainly be memorable!!! Get a taste of the foreign travel offered by printed guidebooks. Enjoy a tour around Japan from the comfort of your own home!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/251870/header.jpg?t=1748835260', 0, 0, NULL);
INSERT INTO games VALUES (58550, 251950, 'WWII Online', 'WW2 Online is a player-driven simulated wargame with a tactical FPS and strategic layer. You’ll fight a global war on one world server and experience unmatched combined arms gameplay on a vast scale.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/251950/0de03363720e69e2a8f89981d02647da285c1cbf/header.jpg?t=1743989914', 0, 1, NULL);
INSERT INTO games VALUES (58551, 251990, 'Long Live The Queen', 'Rule the world or die trying!Being a Princess is not an easy job. Being a Queen is even harder. Especially when you''re only fourteen years old, and the reason you''ve inherited the throne is that your royal mother has just met an untimely end.Now power is up for grabs.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/251990/header.jpg?t=1736618263', 0, 0, NULL);
INSERT INTO games VALUES (58552, 252010, 'Oniken: Unstoppable Edition', 'When a global war nearly decimated humankind, an evil military organization called Oniken takes advantage of the situation to dominate and oppress the few remaining survivors. Even though any resistance to this organization seemed hopeless, a small rebel movement organizes strikes against Oniken.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/252010/header.jpg?t=1675458792', 0, 0, NULL);
INSERT INTO games VALUES (58553, 252030, 'Valdis Story: Abyssal City', 'Assume the role of Wyatt in this Action/Exploration Platformer as you explore the ruins of a holy city that was lost many years ago. Battle various types of demons, angels, and a new threat known only as the “Ferals”, using swordsmanship, martial arts, and sorcery.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/252030/header.jpg?t=1544621869', 0, 0, NULL);
INSERT INTO games VALUES (58554, 252050, 'Construction Machines 2014', 'Become a boss of a construction company. Demolish old houses, flatten the ground, fill foundations with concrete and build new buildings - this is what you do. Sit behind the wheel of different construction machines - from trucks and diggers to huge cranes.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/252050/header.jpg?t=1558092198', 0, 0, NULL);
INSERT INTO games VALUES (58555, 252070, 'Gimbal', 'Gimbal is the multiplayer shooter with buildable vehicles. Customize your weaponry, engines, and accessories, and then take to the skies against other pilots in real time.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/252070/header.jpg?t=1719697417', 0, 0, NULL);
INSERT INTO games VALUES (58557, 252110, 'Lovers in a Dangerous Spacetime', 'Explore a neon galaxy in your very own battleship in this 1- to 4-player couch co-op adventure.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/252110/header.jpg?t=1745967822', 1, 0, NULL);
INSERT INTO games VALUES (58558, 252130, 'Divide By Sheep', 'Divide By Sheep is a mind-bending math puzzler about friendship and slicing sheep in half with lasers. The Grim Reaper flooded the world, and it''s up to you to save critters stranded on islands. Insane math skills required.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/252130/header.jpg?t=1727198809', 0, 0, NULL);
INSERT INTO games VALUES (137689, 252190, 'Defender''s Quest 2: Mists of Ruin', 'Rise above the Mirk and protect your ship from dangers unknown in the latest entry in the classic Defender’s Quest tower defense series!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/252190/header.jpg?t=1738970205', 0, 0, NULL);
INSERT INTO games VALUES (58560, 252250, 'Maia', 'Maia is a colony building game set in the not-so-distant future. Your colonists make planetfall on a hostile world and you must ensure their survival and their safety, constructing their off-world habitat from almost nothing and sheltering them from a dangerous, often deadly environment.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/252250/header.jpg?t=1742843011', 0, 0, NULL);
INSERT INTO games VALUES (58562, 252310, 'Syder Arcade', 'Killing zombies never gets old, but sometimes you just need a break. Get back to some serious old-school gaming with Syder Arcade! Syder Arcade is a love letter to Amiga games of the ‘90s, no coins, no upgrade grinding, just your tenacity and a motherload of alien invaders.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/252310/header.jpg?t=1719823178', 0, 0, NULL);
INSERT INTO games VALUES (58563, 252330, 'Slender: The Arrival', 'Slender Man returns more terrifying than ever. You''re on your own. No one to help you. No one to hear you scream. Relive the horror all over again with cutting edge visuals for the 10th Anniversary Update and experience survival horror at its finest.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/252330/header.jpg?t=1726514166', 0, 0, NULL);
INSERT INTO games VALUES (58564, 252350, 'Double Dragon: Neon', 'BRO-TACULAR! Legendary martial artists, Billy and Jimmy Lee return in this creative re-imagining of the classic beat ‘em up, Double Dragon Neon. Fight your way through countless henchmen including Linda and Abobo on your way to rescue the love of your life, Marian!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/252350/header.jpg?t=1738277444', 0, 0, NULL);
INSERT INTO games VALUES (58565, 252370, 'The Shivah', 'Russell Stone is a Jewish Rabbi at a poor synagogue in New York City. He is a devout man with a problem. Membership is way down and he lacks the funds to keep his synagogue open. Things are looking very bleak, and he has grown progressively more cynical and bitter with the passage of time.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/252370/header.jpg?t=1728040385', 0, 0, NULL);
INSERT INTO games VALUES (58566, 252390, 'DwarfCorp', 'Build a colony of ruthless capitalist Dwarves in a strange fantasy land.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/252390/header.jpg?t=1617492440', 0, 0, NULL);
INSERT INTO games VALUES (58567, 252410, 'SteamWorld Dig', 'SteamWorld Dig is an action-adventure puzzler with strong Metroidvanian influences set in the SteamWorld Universe. You’ll need to dig deep into the earth, gather resources to upgrade your tools and abilities, take on enemies, solve challenging puzzles and uncover the secrets to save a dying town.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/252410/header.jpg?t=1746215433', 0, 0, NULL);
INSERT INTO games VALUES (58569, 252450, 'StarDrive 2', 'StarDrive 2 is an exciting and evolutionary step forward for the StarDrive franchise. In this eagerly anticipated sequel, the core mechanics have evolved to incorporate a turn-based strategic layer, featuring spectacular realtime battles.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/252450/header.jpg?t=1599049935', 0, 0, NULL);
INSERT INTO games VALUES (58570, 252470, 'Space Pirates And Zombies 2', 'Design and then improve the ultimate mothership. Explore a persistent living galaxy populated by 200 unique captains that can do everything you can do. Survive the zombie infection and then fight them back. Make allies and start your own faction. Build your empire. Also includes Sandbox Mode.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/252470/header.jpg?t=1666986052', 0, 0, NULL);
INSERT INTO games VALUES (58571, 252530, 'OMSI 2: Steam Edition', 'Off to the next round! Experience a new omnibus simulator with OMSI 2 and start discovering Spandau while driving the omnibus. OMSI 2 is the successor of the well-known and awarded omnibus simulator &quot;OMSI - The Bus Simulator&quot;.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/252530/header.jpg?t=1742297436', 0, 0, NULL);
INSERT INTO games VALUES (58572, 252550, 'Qbeh-1: The Atlas Cube', 'QBEH-1 is an atmospheric 1st-person puzzle platformer that takes players on a quest through a series of divergent worlds. Each world is filled with new puzzles that require special cubes to solve as well as fun secrets to uncover. Includes a LEVEL EDITOR and STEAM WORKSHOP support!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/252550/header.jpg?t=1447358682', 0, 0, NULL);
INSERT INTO games VALUES (58573, 252570, 'Depths of Fear :: Knossos', 'Depths of Fear :: Knossos, a Greek-themed, 1st Person, Roguelike stealthy action-adventure where you play as Theseus out to kill the rampaging horror the Minotaur. Succeed in the beast’s slaughter or learn the meaning of fear trying. You will run. You will hide. You will fight. You will die.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/252570/header.jpg?t=1712953520', 0, 0, NULL);
INSERT INTO games VALUES (129176, 252710, 'The Last Express Gold Edition', 'Step aboard the 1914 Orient Express in this award-winning mystery adventure from Prince of Persia creator Jordan Mechner. Described as one of the best adventure games of all time, The Last Express is an intrigue-filled adventure set aboard the luxurious Orient Express.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/252710/header.jpg?t=1738840479', 0, 0, NULL);
INSERT INTO games VALUES (135329, 252950, 'Rocket League®', 'Rocket League is a high-powered hybrid of arcade-style soccer and vehicular mayhem with easy-to-understand controls and fluid, physics-driven competition. Rocket League includes casual and competitive Online Matches, a fully-featured offline Season Mode, special “Mutators” that let you change the rules entirely, hockey and...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/252950/d56cf9d01073d893677fb9e7e257b79fd7939ee3/header.jpg?t=1741975345', 1, 0, NULL);
INSERT INTO games VALUES (137827, 253330, 'Neverending Nightmares', 'Experience true psychological horror as you explore nightmares inspired by the creator''s struggles with depression and OCD. The defenseless protagonist must avoid monstrous manifestations of what haunts his subconscious in his quest to wake up into reality.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/253330/header.jpg?t=1734669147', 0, 0, NULL);
INSERT INTO games VALUES (58535, 253370, 'Axis Game Factory''s AGFPRO v3', 'Axis Game Factory’s AGFPRO v3.0 – for PC, MAC and LINUXWe just released version 3.0 of AGFPRO &amp; Premium - there are a TON of new features, assets and functionality that have been added, giving users the ability to create amazing game levels and maps like NEVER BEFORE!!Major features to AGFPRO 3.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/253370/header.jpg?t=1578604957', 0, 0, NULL);
INSERT INTO games VALUES (58537, 253410, 'Ravensword: Shadowlands', 'From the award winning studio that brought you Ravensword: The Fallen King and Aralon: Sword and Shadow, comes Ravensword: Shadowlands. After the fall of Ravengard, the world descended into chaos. The Kingdom of Tyreas stood alone against a sea of dark elven invaders. The Ravensword was lost, and the dark times began.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/253410/header.jpg?t=1447358711', 0, 0, NULL);
INSERT INTO games VALUES (58538, 253430, 'CastleMiner Z', 'CastleMiner Z is an infinite world filled with deep places to explore, and horrifying monsters to slay. Build structures out of blocks, craft weapons and tools from raw materials, and explore the vast and frightening world around you.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/253430/d88d93e32f38411e36dbca08ce8a9e872772e0b5/header.jpg?t=1744955476', 0, 0, NULL);
INSERT INTO games VALUES (58539, 253510, 'WARMACHINE: Tactics', 'Turn-based tactical combat set in the award-winning world of the Iron Kingdoms. Command your custom squad of steam-powered robots and elite warriors in raging battles dominated by magic and mechanika. Battle in online multiplayer and play the epic 21-mission single player campaign!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/253510/header.jpg?t=1513301228', 0, 1, NULL);
INSERT INTO games VALUES (128035, 253710, 'theHunter Classic', 'The most realistic hunting experience awaits. Explore 12 reserves and hunt 45 unique species, ranging from waterfowl to big game. Over 100 weapons from state-of-the art rifles to bows. Customize your load-out with stands, blinds and dogs. Play alone or in multiplayer with up to 7 friends.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/253710/header.jpg?t=1669020103', 0, 1, NULL);
INSERT INTO games VALUES (135704, 253770, 'Bus-Simulator 2012', 'Catch the bus and let it take you to a detailed, virtual world.Are you ready to explore a picturesque German city behind the wheel of a realistically modeled, freely accessible bus? Then take a look at “Bus Simulator 2012” by the well-known developer studio TML!Every technical detail of the original bus has been reproduced true-to-live.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/253770/header.jpg?t=1654101942', 0, 0, NULL);
INSERT INTO games VALUES (132499, 254820, 'Ground Control Anthology', 'The year is 2419. War has devastated Earth, and mega-corporations take to the stars to fight over colonised planets. Your employer, the Crayven Corporation, chose you to command an army of ground and air forces. You thought it would be just another brush-fire war. You were wrong.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/254820/header.jpg?t=1579791410', 0, 0, NULL);
INSERT INTO games VALUES (137622, 261550, 'Mount & Blade II: Bannerlord', 'A strategy/action RPG. Create a character, engage in diplomacy, craft, trade and conquer new lands in a vast medieval sandbox. Raise armies to lead into battle and command and fight alongside your troops in massive real-time battles using a deep but intuitive skill-based combat system.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/261550/header.jpg?t=1742509686', 1, 0, NULL);
INSERT INTO games VALUES (129457, 261640, 'Borderlands: The Pre-Sequel', 'Launch into the Borderlands universe and shoot ‘n’ loot your way through a brand new adventure that rockets you onto Pandora’s moon in Borderlands: The Pre-Sequel!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/261640/header.jpg?t=1728608128', 1, 0, NULL);
INSERT INTO games VALUES (128162, 262060, 'Darkest Dungeon®', 'Darkest Dungeon is a challenging gothic roguelike turn-based RPG about the psychological stresses of adventuring. Recruit, train, and lead a team of flawed heroes against unimaginable horrors, stress, disease, and the ever-encroaching dark. Can you keep your heroes together when all hope is lost?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/262060/header.jpg?t=1747999109', 1, 0, NULL);
INSERT INTO games VALUES (137182, 265810, 'The Sandbox', 'READY FOR CRAFTING VIRTUAL WORLDS ON YOUR PC?The acclaimed world-building game featuring a unique mission-based approach is coming onto PC via Steam Early Access. With over 16 million players on mobile &amp; tablets versions and 1,500,000 pixel blocks creations shared in the Online Gallery to date, this PC version is taking world...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/265810/header.jpg?t=1447359567', 0, 0, NULL);
INSERT INTO games VALUES (127583, 267610, 'Woodcutter Simulator 2013', 'Woodcutter Simulator 2013 allows the player to control and operate an entire lumber mill. From clearing woods to the evacuation of the logs, the player has to undertake all arising tasks to complete numerous missions – from cutting trees for demanding customers to producing woodchips for heating purposes.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/267610/header.jpg?t=1641989276', 0, 0, NULL);
INSERT INTO games VALUES (135666, 268500, 'XCOM® 2', 'XCOM 2 is the sequel to XCOM: Enemy Unknown, the 2012 award-winning strategy game of the year. Earth has changed and is now under alien rule. Facing impossible odds you must rebuild XCOM, and ignite a global resistance to reclaim our world and save humanity.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/268500/header.jpg?t=1646157374', 1, 0, NULL);
INSERT INTO games VALUES (140167, 268650, 'From the Depths', 'Over 1000 unique components allow you to build and command voxel vehicles from the deep ocean to outer space! Forge strategies, allegiances and fleets strong enough to destroy eight deadly factions of the planet and reign supreme. A genre-defying mashup of simulation, building, RTS and RPG.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/268650/header.jpg?t=1734963834', 0, 0, NULL);
INSERT INTO games VALUES (136494, 269210, 'Hero Siege', 'Hero Siege brings you the loot with a legion of playable character classes, procedually generated world, over 1000 unique items, endless replayability and a wide variety of dungeons and dangerous zones to explore!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/269210/header.jpg?t=1736850054', 1, 0, NULL);
INSERT INTO games VALUES (137399, 270110, 'Block Story™', 'There isn’t much better than a wide open game world in which you have essentially no limits and can alter the very landscape in which you play – that is, unless you add dragons, of course…', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/270110/header.jpg?t=1748131456', 1, 0, NULL);
INSERT INTO games VALUES (136703, 270880, 'American Truck Simulator', 'Experience legendary American trucks and deliver various cargoes across sunny California, sandy Nevada, and the Grand Canyon State of Arizona. American Truck Simulator takes you on a journey through the breathtaking landscapes and widely recognized landmarks around the States.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/270880/header.jpg?t=1748107300', 1, 0, NULL);
INSERT INTO games VALUES (132329, 271260, 'Star Control®: Origins', 'Star Control is a space role-playing game in which you command Earth''s first interstellar starship on a mission to save the Earth from hostile alien empires.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/271260/header.jpg?t=1741099382', 0, 0, NULL);
INSERT INTO games VALUES (128552, 274500, 'Brigador: Up-Armored Edition', 'Pilot a mech to hunt down and destroy the oppressive government of a cyberpunk autocracy. In this fast-paced, top-down shooter, use overwhelming firepower to destroy columns of tanks and level buildings. Unlock up to 56 unique vehicles and 40 weapons.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/274500/header.jpg?t=1748016835', 1, 0, NULL);
INSERT INTO games VALUES (132757, 274900, 'Murder Miners', 'The #1 rated Xbox Live Indie Game. Halo-inspired. Destructible/constructible environments. Vehicles. Zombie survival. Hookshots. Infection mode: Be the zombie &amp; eat the dead to level up your zombie abilities. Community playdates are still hosted every week, join us!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/274900/header.jpg?t=1739220160', 0, 0, NULL);
INSERT INTO games VALUES (135754, 275100, 'Shelter 2', 'As a powerful Lynx, you will make your way through vast open landscapes. In the harsh tundra, you will raise and strengthen your cubs by mastering your skills for hunting prey. Do everything you can to prepare your little ones for the vicious entities dwelling in the wilderness.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/275100/header.jpg?t=1737643060', 0, 0, NULL);
INSERT INTO games VALUES (136143, 277680, 'About Love, Hate and the other ones', 'About Love, Hate and the other ones is a puzzle game, in which you influence your surroundings by the force of Hate and the power of Love. Find a way through caves and ice, castles and factories, all by the might of your puzzling!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/277680/header.jpg?t=1706637452', 0, 0, NULL);
INSERT INTO games VALUES (127699, 280680, 'Krita', 'Krita is a powerful, open source and community-driven digital art tool for illustrators, concept designers, animators, comic book artists, game developers, and anyone who wants to express themselves through the creation of visual art.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/280680/header.jpg?t=1724367020', 1, 0, NULL);
INSERT INTO games VALUES (127923, 281280, 'Mashed', 'Compete over 13 challenging and diverse environments using whatever means necessary to batter and bruise your opponents into submission, and claim victory for yourself!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/281280/header.jpg?t=1572397858', 0, 0, NULL);
INSERT INTO games VALUES (132819, 281920, 'Splatter - Zombiecalypse Now', 'You like top-down-shooter with a film-noir singleplayer campaign, challenging fights against zombies and monsters, gory splatter effects and destructible level environments? Fight your way through an apocalyptic city in the single player story mode, and test your skills in the survival mode.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/281920/header.jpg?t=1739463870', 0, 0, NULL);
INSERT INTO games VALUES (131324, 281990, 'Stellaris', 'Explore a galaxy full of wonders in this sci-fi grand strategy game from Paradox Development Studios. Interact with diverse alien races, discover strange new worlds with unexpected events and expand the reach of your empire. Each new adventure holds almost limitless possibilities.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/281990/header.jpg?t=1746546960', 1, 0, NULL);
INSERT INTO games VALUES (137668, 282400, 'SuperPower 2 Steam Edition', 'SuperPower 2 is the only global geopolitical simulation game which allows players to control entire countries. Players control countries in 3 major areas: political, economic and military, but this time, in a beautiful real-time 3D environment.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/282400/header.jpg?t=1725014542', 0, 0, NULL);
INSERT INTO games VALUES (130681, 284050, 'Sanitarium', 'Originally released in 1998 on PC, and awarded as the Adventure Game of the Year, The timeless horror point-and-click, Sanitarium, is returning to frighten the bravest adventure game fans.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/284050/header.jpg?t=1747902851', 0, 0, NULL);
INSERT INTO games VALUES (139823, 284160, 'BeamNG.drive', 'A dynamic soft-body physics vehicle simulator capable of doing just about anything.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/284160/header.jpg?t=1743607220', 1, 0, NULL);
INSERT INTO games VALUES (131976, 285900, 'Gang Beasts', 'Gang Beasts is a silly multiplayer party game with surly gelatinous characters, brutal slapstick fight sequences, and absurd hazardous environments, set in the mean streets of Beef City.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/285900/header.jpg?t=1732109683', 1, 0, NULL);
INSERT INTO games VALUES (128183, 285920, 'TerraTech', 'TerraTech is an open-world, sandbox adventure game, where you design and build your own creations through a mix of crafting, combat and discovery. Design vehicles from a huge library of blocks. Scavenge, craft and buy new parts to survive and become the ultimate planetary prospector.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/285920/header.jpg?t=1749411619', 1, 0, NULL);
INSERT INTO games VALUES (137374, 286160, 'Tabletop Simulator', 'Tabletop Simulator is the only simulator where you can let your aggression out by flipping the table! There are no rules to follow: just you, a physics sandbox, and your friends. Make your own online board games or play the thousands of community created mods. Unlimited gaming possibilities!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/286160/header.jpg?t=1720948345', 0, 0, NULL);
INSERT INTO games VALUES (136495, 288060, 'Whispering Willows', 'Interact with the spirits of the dead, solve the puzzles of the mysterious mansion and help Elena find her missing father in the horror/adventure puzzle game: Whispering Willows.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/288060/header.jpg?t=1746837495', 0, 0, NULL);
INSERT INTO games VALUES (132613, 291480, 'Warface: Clutch', '𝗪𝗮𝗿𝗳𝗮𝗰𝗲: 𝗖𝗹𝘂𝘁𝗰𝗵 𝗶𝘀 𝗮 𝗰𝗼𝗻𝘁𝗲𝗺𝗽𝗼𝗿𝗮𝗿𝘆 𝗠𝗠𝗢 𝗳𝗶𝗿𝘀𝘁 𝗽𝗲𝗿𝘀𝗼𝗻 𝘀𝗵𝗼𝗼𝘁𝗲𝗿 𝘄𝗶𝘁𝗵 𝗺𝗶𝗹𝗹𝗶𝗼𝗻𝘀 𝗼𝗳 𝗳𝗮𝗻𝘀 𝗮𝗿𝗼𝘂𝗻𝗱 𝘁𝗵𝗲 𝘄𝗼𝗿𝗹𝗱. 𝗜𝘁 𝗼𝗳𝗳𝗲𝗿𝘀 𝗶𝗻𝘁𝗲𝗻𝘀𝗲 𝗣𝘃𝗣 𝗺𝗼𝗱𝗲𝘀, 𝗰𝗼𝗺𝗽𝗲𝗹𝗹𝗶𝗻𝗴 𝗣𝘃𝗘 𝗺𝗶𝘀𝘀𝗶𝗼𝗻𝘀 𝗮𝗻𝗱 𝗿𝗮𝗶𝗱𝘀 𝘁𝗵𝗮𝘁 𝘆𝗼𝘂 𝗰𝗮𝗻 𝗰𝗵𝗮𝗹𝗹𝗲𝗻𝗴𝗲 𝘄𝗶𝘁𝗵 𝗳𝗶𝘃𝗲 𝗱𝗶𝘃𝗲𝗿𝘀𝗲 𝗰𝗹𝗮𝘀𝘀𝗲𝘀 𝗮𝗻𝗱 𝗮 𝗰𝗼𝗹𝗼𝘀𝘀𝗮𝗹 𝗰𝘂𝘀𝘁𝗼𝗺𝗶𝘇𝗮𝗯𝗹𝗲 𝗮𝗿𝘀𝗲𝗻𝗮𝗹.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/291480/0cfe8822d016fd4d61875df9297fc7744b347adb/header.jpg?t=1748359241', 1, 1, NULL);
INSERT INTO games VALUES (128018, 291550, 'Brawlhalla', 'An epic platform fighter for up to 8 players online or local. Try casual free-for-alls, ranked matches, or invite friends to a private room. And it''s free! Play cross-platform with millions of players on PlayStation, Xbox, Nintendo Switch, iOS, Android &amp; Steam! Frequent updates. Over sixty Legends.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/291550/71448f1f413d5aac25b8dd08068f0f284f7bacf7/header.jpg?t=1747253897', 1, 1, NULL);
INSERT INTO games VALUES (138305, 291650, 'Pillars of Eternity', 'Prepare to be enchanted by a world where the choices you make and the paths you choose shape your destiny. Obsidian Entertainment, the developer of Fallout: New Vegas™ and South Park: The Stick of Truth™, together with Paradox Interactive is proud to present Pillars of Eternity.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/291650/header.jpg?t=1683221851', 0, 0, NULL);
INSERT INTO games VALUES (129227, 292030, 'The Witcher 3: Wild Hunt', 'You are Geralt of Rivia, mercenary monster slayer. Before you stands a war-torn, monster-infested continent you can explore at will. Your current contract? Tracking down Ciri — the Child of Prophecy, a living weapon that can alter the shape of the world.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/292030/ad9240e088f953a84aee814034c50a6a92bf4516/header.jpg?t=1749199563', 1, 0, NULL);
INSERT INTO games VALUES (129419, 292480, 'Magical Battle Festa', 'TEOS, an agency of holy mages, holds a tournament to find the best magic users in the world to take on a dark threat looming on the horizon. Choose your mage and take to the arena in this fast-paced competitive fighting game that mixes troop formations and fast action.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/292480/header.jpg?t=1573203065', 0, 0, NULL);
INSERT INTO games VALUES (136552, 293320, 'Coma: Mortuary', 'Coma:Mortuary is the introduction part of a trilogy about events in the world of the dead. The game''s genre is Adventure-Ambient with Horror-quest element.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/293320/header.jpg?t=1721799513', 0, 0, NULL);
INSERT INTO games VALUES (131739, 293760, 'Automation - The Car Company Tycoon Game', 'Make your dream cars a reality with Automation’s unparalleled car and engine design tools. Gain a competitive edge through smart engineering and business decisions to help you build an automotive empire. Will you become an industry leader, or just a footnote in automotive history?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/293760/header.jpg?t=1738203029', 0, 0, NULL);
INSERT INTO games VALUES (136553, 294020, 'Merchants of Kaidan', 'Regain your riches, restore your honor and avenge your father''s murder. A challenging trading game with lots of RPG elements.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/294020/header.jpg?t=1568803756', 0, 0, NULL);
INSERT INTO games VALUES (129059, 294100, 'RimWorld', 'A sci-fi colony sim driven by an intelligent AI storyteller. Generates stories by simulating psychology, ecology, gunplay, melee combat, climate, biomes, diplomacy, interpersonal relationships, art, medicine, trade, and more.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/294100/header.jpg?t=1749524368', 1, 0, NULL);
INSERT INTO games VALUES (132926, 296710, 'Monstrum', 'Monstrum takes the traditional survival horror formula and remixes it completely with procedurally generated levels, permadeath, and AI driven predators, ensuring that nowhere on its derelict cargo ship is ever truly safe.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/296710/header.jpg?t=1748505684', 0, 0, NULL);
INSERT INTO games VALUES (136585, 299460, 'Woodle Tree Adventures', 'Woodle Tree Adventures is an old school platform game with a catchy and unique art style! Explore a total of 6 worlds and save the lands with the magical water drops you''ll find through your journey, bringing back peace and balance and finally becoming the new hero!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/299460/header.jpg?t=1748104281', 0, 0, NULL);
INSERT INTO games VALUES (136452, 301280, 'Skin Deep', 'Skin Deep is an immersive first-person shooter. We got sneezing. We got things getting stuck in your feet. Stalk through a vast non-linear starship and sneak, subvert, and sabotage to survive in this stellar sandbox. You''re outnumbered, outgunned, and have no shoes. Welcome to Skin Deep!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/301280/header.jpg?t=1746226385', 1, 0, NULL);
INSERT INTO games VALUES (139601, 301300, 'Chicken Invaders 4', 'They came without warning, squawking menacingly, their ruffled feathers darkening the sun. Invading intergalactic chickens, out to punish humanity for our oppression of their earthly brethren. Now they''re back, and they''re having Earth for dinner!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/301300/header.jpg?t=1695975404', 0, 0, NULL);
INSERT INTO games VALUES (132612, 301320, 'NoLimits 2 Roller Coaster Simulation', 'NoLimits 2 is the ultimate roller coaster simulation that lets you experience authentic roller coaster thrills. Climb into the world''s most famous roller coasters and experience the excitement in real time. Or design a new roller coaster that is engineered to your specifications.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/301320/header.jpg?t=1724402893', 0, 0, NULL);
INSERT INTO games VALUES (130064, 301970, 'Screencheat', 'Screencheat is a ridiculous competitive split-screen first-person shooter where everyone is invisible, so players are forced to look at each other’s screens to win. Supporting both local and online multiplayer, combat in Screencheat is fast and furious with a wide variety of one-hit kill weapons.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/301970/header.jpg?t=1747870310', 1, 0, NULL);
INSERT INTO games VALUES (128583, 301980, 'Disney Pirates of the Caribbean: At Worlds End', 'Pirates of the Caribbean: At World''s End invites players into the world of the films - and beyond. Live and die by the sword while playing as Captain Jack Sparrow, Will Turner and Elizabeth Swann.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/301980/header.jpg?t=1741735040', 0, 0, NULL);
INSERT INTO games VALUES (137728, 303310, 'The House in Fata Morgana', 'A gothic suspense tale set in a cursed mansion. &quot;The House in Fata Morgana&quot; is a full-length visual novel spanning nearly a millennium that deals in tragedy, human nature, and insanity.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/303310/header.jpg?t=1725518929', 1, 0, NULL);
INSERT INTO games VALUES (136677, 303390, 'Dead Bits', 'Quilly was abducted by aliens, now, he has to fight for his freedom! Destroy cube aliens with guns, bats and inteligence... avoid traps and more. Dead Bits is a first-person shooter with original dubstep soundtrack for Windows and Mac.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/303390/header.jpg?t=1652177901', 0, 0, NULL);
INSERT INTO games VALUES (129493, 304390, 'FOR HONOR™', 'Fight alone or with friends in For Honor, a third-person hero-based melee fighting game. Enter the chaos of war as a Knight, a Viking, a Samurai, a Wu Lin, or an Outlander. Fight in brutal PvP and team-oriented modes, or play the thrilling story campaign.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/304390/header.jpg?t=1745501188', 1, 0, NULL);
INSERT INTO games VALUES (135797, 305620, 'The Long Dark', 'THE LONG DARK is a thoughtful, exploration-survival experience that challenges solo players to think for themselves as they explore an expansive frozen wilderness in the aftermath of a geomagnetic disaster. There are no zombies -- only you, the cold, and all the threats Mother Nature can muster.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/305620/header.jpg?t=1745525398', 1, 0, NULL);
INSERT INTO games VALUES (130228, 306760, 'Obduction', 'A new sci-fi adventure from Cyan, the creators of Myst. Abducted far across the universe, you find yourself on a broken alien landscape with odd pieces of Earth. Explore, uncover, solve, and find a way to make it home.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/306760/header.jpg?t=1747419107', 0, 0, NULL);
INSERT INTO games VALUES (136949, 307960, 'IL-2 Sturmovik: Battle of Stalingrad', 'IL-2 Sturmovik: Battle of Stalingrad is the continuation of the legendary IL-2 Sturmovik series that has set the standard for PC combat flight games for more than ten years. This new entry into the series will offer virtual pilots an even more accurate simulation of the most famous air battles.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/307960/header.jpg?t=1739291145', 0, 0, NULL);
INSERT INTO games VALUES (136079, 308040, 'Back to Bed', 'Guide Bob the sleepwalker to the safety of his bed by taking control of his subconscious guardian, Subob. Explore a surreal and hand-painted dream world, avoid dangers and get Bob safely back to bed.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/308040/header.jpg?t=1729500405', 0, 0, NULL);
INSERT INTO games VALUES (136678, 308060, 'Black The Fall', 'After decades of toil, an old machinist plots his escape from Communism, through manipulation and scheming. Along the road, he befriends the most unlikely creature, an abandoned robot. Could they solve the puzzles and flee this bleak world together?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/308060/header.jpg?t=1728396116', 1, 0, NULL);
INSERT INTO games VALUES (136261, 311120, 'The Stalin Subway: Red Veil', 'With the death of Stalin, all those who surrounded him, are now fighting for the supreme power and control over the nation. Lena, our heroine, has found that her husband has been kidnapped and possibly murdered. She has no clue about who did it, but she knows whom to ask.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/311120/header.jpg?t=1692008820', 0, 0, NULL);
INSERT INTO games VALUES (131492, 311210, 'Call of Duty®: Black Ops III', 'Call of Duty®: Black Ops III Zombies Chronicles Edition includes the full base game plus the Zombies Chronicles content expansion.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/311210/header.jpg?t=1748022663', 0, 0, NULL);
INSERT INTO games VALUES (129356, 311310, 'Naval Action', 'Or were you deaf or were you blind when you left your two fine legs behind, Or was it sailing on the sea when you got the cannonball to your knee, I too was young and I was slim and I had a leg for every limb, But now I’ve got no legs at all, they were both shot away by a cannonball.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/311310/header.jpg?t=1736789986', 1, 1, NULL);
INSERT INTO games VALUES (131264, 311560, 'Assassin’s Creed® Rogue', 'Introducing Assassin’s Creed® Rogue, the darkest chapter in the Assassin’s Creed franchise yet. As Shay, you will experience the slow transformation from Assassin to Assassin Hunter. Follow your own creed and set off on an extraordinary journey through New York City, the wild river valley, and far away to the icy cold waters of the North...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/311560/header.jpg?t=1738230827', 1, 0, NULL);
INSERT INTO games VALUES (136004, 312660, 'Sniper Elite 4', 'Discover unrivalled sniping freedom in the largest and most advanced World War 2 shooter ever built. Experience tactical third-person combat, gameplay choice and epic longshots across gigantic levels as you liberate wartime Italy from the grip of Fascism.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/312660/header.jpg?t=1681207252', 0, 0, NULL);
INSERT INTO games VALUES (133436, 314030, 'Guilty Gear X2 #Reload', 'As humanity endeavored to better themselves, they created the biological marvel known as Gears. Originally intended as the next step of human evolution, they were instead fitted for war and turned against their own creators.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/314030/header.jpg?t=1634717936', 0, 0, NULL);
INSERT INTO games VALUES (139877, 318600, 'The Flame in the Flood', 'A rogue-like river journey through the backwaters of a forgotten post-societal America. Forage, craft, evade predators.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/318600/header.jpg?t=1749201410', 0, 0, NULL);
INSERT INTO games VALUES (74880, 321060, 'Gender Bender DNA Twister Extreme', 'The ultimate cult classic gender bender romantic comedy! Play through 13 massive chapters, each with their own unique protagonist. Swap genders, turn into a slime monster, become a mermaid! It''s Gender Bender DNA Twister Extreme!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/321060/header.jpg?t=1667089717', 0, 0, NULL);
INSERT INTO games VALUES (74885, 321270, 'UNLOVED', 'Based on the community award-winning Doom2 mod with the same name by the same creator, UNLOVED is reimagined in the Unreal Engine 4 to bring forth the unspeakable terror in new ways. Play coop with your friends, increase your skills, mod your weapons and face the horror that this unearthly place holds...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/321270/header.jpg?t=1728018391', 0, 0, NULL);
INSERT INTO games VALUES (74886, 321290, 'Dandelion - Wishes brought to you -', 'Dandelion -Wishes brought to you- is a female-oriented game developed by Cheritz. The game was released in South Korea in August, 2012. The English translation for Dandelion was released on Nov, 2012. Dandelion is known as a unique dating simulation with a sensational storyline and charming characters.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/321290/header.jpg?t=1572854270', 1, 0, NULL);
INSERT INTO games VALUES (74871, 321400, 'Supraball', 'Play football in first person view and develop your own tactics and tricks. Play with up to 9 of your friends or join alone. No Pay2Win!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/321400/header.jpg?t=1725021447', 0, 1, NULL);
INSERT INTO games VALUES (74872, 321410, 'Command: Modern Air / Naval Operations WOTY', 'Command: Modern Air/Naval Operations is the ultimate military simulator for modern military conflicts. Designed with a huge emphasis on detail, realism, accuracy and flexibility, Command allows you to simulate and direct any historical or hypothetical air or naval engagement from 1945, at any scale, including strategic nuclear war.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/321410/header.jpg?t=1726823534', 0, 0, NULL);
INSERT INTO games VALUES (74856, 321800, 'Icewind Dale: Enhanced Edition', 'Icewind Dale: Enhanced Edition revives the classic RPG with fresh updates for modern players. Build a party of Dungeons &amp; Dragons heroes and explore the frozen tundra in this retro fantasy adventure.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/321800/header.jpg?t=1746122443', 1, 0, NULL);
INSERT INTO games VALUES (74857, 321830, 'Cavern Kings', 'Cavern Kings is an infinite action platformer designed to make every playthrough unique and interesting. Cavern Kings aims to explode with special effects in classical arcade fashion and create interesting synergies with its powerup system.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/321830/header.jpg?t=1637709342', 0, 0, NULL);
INSERT INTO games VALUES (74859, 321870, 'Silence of the Sleep', 'You play as a man called Jacob Reeves. A man who has lost his reason to live. He throws himself into a blackness to end his misery, but instead of it being the end he wakes up without a memory of his life before.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/321870/header.jpg?t=1583133850', 0, 0, NULL);
INSERT INTO games VALUES (74865, 321960, 'Might & Magic® Heroes® VII', 'Might &amp; Magic® Heroes® VII makes a triumphant return bringing you the essence of turn based strategy gaming. Set in a fantasy universe with RPG progression with a strong story narrative, you will embark on a journey that you will never forget!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/321960/header.jpg?t=1692823130', 1, 0, NULL);
INSERT INTO games VALUES (74866, 321980, 'Hardland', 'In the year 1018, an adventurer from Samarkand drifts to Hardland. Solve a mystery by delving into the different sides of this fantasy world. Hardland is a bustling kingdom filled with secrets. A kingdom that wants you to listen.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/321980/header.jpg?t=1639869266', 0, 0, NULL);
INSERT INTO games VALUES (74869, 322110, '20XX', '20XX is a roguelike action platformer that you can play with a friend. Jump and shoot your way through ever-changing levels, collect awesome new powers, and battle mighty bosses in the name of saving the human race maybe!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/322110/header.jpg?t=1588889694', 1, 0, NULL);
INSERT INTO games VALUES (137715, 322170, 'Geometry Dash', 'Jump and fly your way through danger in this rhythm-based action platformer!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/322170/header.jpg?t=1703006148', 0, 0, NULL);
INSERT INTO games VALUES (74843, 322190, 'SteamWorld Heist', 'Command a steam-driven pirate crew in a series of epic tactical shootouts in SteamWorld Heist. This is turn-based strategy with a twist: You manually aim the guns of your robots, allowing for insane skill shots and bullet-bouncing action!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/322190/header.jpg?t=1726132166', 0, 0, NULL);
INSERT INTO games VALUES (74844, 322210, 'Guns, Gore & Cannoli', 'Guns, Gore &amp; Cannoli - An over-the-top, comical and fast-paced action game with hand-drawn graphics set in the Roaring Twenties. An all-you-can-shoot fest where you embody Vinnie, a mobster with a mission in a city controlled by gangsters and plagued by zombies. Featuring up to 4-man local co-op.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/322210/header.jpg?t=1749489215', 0, 0, NULL);
INSERT INTO games VALUES (74845, 322290, 'Gurumin: A Monstrous Adventure', 'Gurumin: A Monstrous Adventure is a cute and clever action RPG featuring real-time combat, 3D graphics, 90+ items, mini-games, multiple endings, a rocking soundtrack, 35+ hours of playtime, tons of fully voiced characters by an all-star cast of voice actors, and more!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/322290/header.jpg?t=1729180996', 0, 0, NULL);
INSERT INTO games VALUES (138428, 322330, 'Don''t Starve Together', 'Fight, Farm, Build and Explore Together in the standalone multiplayer expansion to the uncompromising wilderness survival game, Don''t Starve.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/322330/f0620dadd4666d8fe9e588cfbaba5fbaea4722b5/header.jpg?t=1746133902', 1, 0, NULL);
INSERT INTO games VALUES (74849, 322450, 'FRAMED Collection', 'Rearrange the panels of an animated comic book to craft the story of a noir-styled spy adventure in the FRAMED Collection--a compilation of the multi-award winning puzzle games FRAMED and FRAMED 2.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/322450/header.jpg?t=1731733313', 1, 0, NULL);
INSERT INTO games VALUES (74850, 322500, 'SUPERHOT', 'SUPERHOT is the smash-hit FPS where time moves only when you move. No regenerating health bars. No conveniently placed ammo drops. It''s you, alone, outnumbered and outgunned. Snatch weapons from fallen enemies to shoot, slice and dodge through a truly cinematic hurricane of slow-motion bullets.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/322500/header.jpg?t=1726509130', 1, 0, NULL);
INSERT INTO games VALUES (74855, 322680, 'BLACKHOLE', 'BLACKHOLE is an award-winning hardcore platformer with over 15 hours of story-driven sci-fi comedy and gravity-twisting puzzles. Complete Edition out now!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/322680/header.jpg?t=1721994713', 0, 0, NULL);
INSERT INTO games VALUES (74823, 322750, 'Drifting Lands', 'Drifting Lands is an hybrid of classical horizontal shoot''em''up with a lot of strong gameplay elements coming straight from the action-RPG genre. If you want an original diablo-like game or you want a different kind of shoot''em''up, you''re in the right place!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/322750/header.jpg?t=1561711627', 0, 0, NULL);
INSERT INTO games VALUES (74824, 322770, 'Vanishing Realms™', 'Vanishing Realms is an immersive RPG designed exclusively for Virtual Reality. Grab your sword and fight life-sized monsters in epic face-to-face melee combat. Explore mystic domains, outwit magical wards, seek lost artifacts, wield sorcery and steel to take on denizens of the Undead Realm.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/322770/header.jpg?t=1571039700', 0, 0, NULL);
INSERT INTO games VALUES (74825, 322780, 'Worlds Adrift', 'We''re tired of endless grinding, mini-maps and predetermined fun. That''s why we intend to redefine MMOs and empower our players to find their own destiny, write their own stories, and leave a lasting impression on the world they helped us create. How will you impact it and what will your legacy be?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/322780/header.jpg?t=1574697194', 0, 0, NULL);
INSERT INTO games VALUES (74826, 322850, 'Pro Cycling Manager 2015', 'Become the sporting director of one of the pro cycling circuit''s 90 teams, and compete in a thrilling 2015 season. Participate in over 200 competitions (550 stages) and the ultimate challenge: the prestigious Tour de France 2015 and its official route.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/322850/header.jpg?t=1565101912', 0, 0, NULL);
INSERT INTO games VALUES (74827, 322900, 'War, the Game', '''War, the Game'' is a RTS for pc in realistic present day setting.The controls are intuitive, the game rules are simple and transparent.The game focuses on strategy and the use of ones brain to complete the scenarios.The map is a spherical version of earth. That''s new.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/322900/header.jpg?t=1572453229', 0, 0, NULL);
INSERT INTO games VALUES (74828, 322920, 'theHunter: Primal', 'Hunt - Explore - SurviveThe most realistic prehistoric survival game ever created. Featuring a huge Cretaceous environment populated by horrifying dinosaur all-stars, such as T-Rex, Triceratops, Utahraptor, Velociraptor and Quetzalcoatlus.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/322920/header.jpg?t=1548884078', 0, 0, NULL);
INSERT INTO games VALUES (74836, 323060, 'Tharsis', 'Succeeding in Tharsis requires you to make the best of what you have, even if it happens to be a pair of snake eyes. Certain factors may be outside of your control, but that doesn’t mean they can’t be overcome. Tharsis is not a game about facing the odds. It’s a game about changing them.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/323060/header.jpg?t=1702627319', 0, 0, NULL);
INSERT INTO games VALUES (135685, 323190, 'Frostpunk', 'Frostpunk is the first society survival game. As the ruler of the last city on Earth, it is your duty to manage both its citizens and infrastructure. What decisions will you make to ensure your society''s survival? What will you do when pushed to breaking point? Who will you become in the process?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/323190/b6789fad23dddff0de8918fa565968daa1322629/header_alt_assets_4.jpg?t=1748439240', 1, 0, NULL);
INSERT INTO games VALUES (74837, 323220, 'Vagante', 'Vagante is an action-packed platformer that features permanent death and procedurally generated levels. Play cooperatively with friends both locally and online, or adventure solo in this challenging roguelike-inspired game.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/323220/header.jpg?t=1665169876', 0, 0, NULL);
INSERT INTO games VALUES (74811, 323320, 'Grow Home', 'Experience the freedom of unbounded climbing as you take control of BUD, a procedurally animated robot on a quest to save his planet. Create your own path through an alien world as you control and ride a giant plant on a vertical journey to the stars.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/323320/header.jpg?t=1694556095', 0, 0, NULL);
INSERT INTO games VALUES (74812, 323380, 'The Magic Circle', 'In this darkly comedic story, you are the hero of an unfinished fantasy game, and your designers have failed you. Steal the power of a game god - trap their creations, swap behaviors and body parts, crafting your own unique solutions to free-form puzzles. Can you release a game ...from the inside?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/323380/header.jpg?t=1572638858', 0, 0, NULL);
INSERT INTO games VALUES (74814, 323470, 'DRAGON BALL XENOVERSE', 'DRAGON BALL XENOVERSE revisits famous battles from the series through your custom Avatar and other classic characters. New features include the mysterious Toki Toki City, new gameplay mechanics, new animations and many other amazing features!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/323470/header.jpg?t=1701323766', 0, 0, NULL);
INSERT INTO games VALUES (74816, 323580, 'Jotun: Valhalla Edition', 'Jotun is a hand-drawn action-exploration game set in Norse mythology. In Jotun, you play Thora, a Viking warrior who died an inglorious death and must prove herself to the Gods to enter Valhalla. Impress the Gods!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/323580/header.jpg?t=1726491392', 1, 0, NULL);
INSERT INTO games VALUES (74819, 323670, 'Super Indie Karts', 'Super Indie Karts is a classic retro 16 to 64-bit style karting game, with Time Trials, Grand Prix, Splitscreen GP, Mission Mania, and Battle Mania! Featuring 48 racetracks, with many more coming soon. You don''t have to wait until completion though as you can join the race now with Early Access!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/323670/header.jpg?t=1737595236', 0, 0, NULL);
INSERT INTO games VALUES (74822, 323720, 'Decay: The Mare', 'Sam is an addict who ends up in an institution named “Reaching Dreams”, hoping to kick his drug problem and sort out his miserable life. But during the first night, something goes horribly wrong and he gets stuck in an endless nightmare…', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/323720/header.jpg?t=1716976978', 1, 0, NULL);
INSERT INTO games VALUES (74798, 323850, 'Move or Die', 'Move or Die is an absurdly fast-paced 4-player local and online party game where the mechanics change every 20 seconds! It''s THE friendship-ruining game.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/323850/header.jpg?t=1728465590', 1, 0, NULL);
INSERT INTO games VALUES (74803, 324120, 'Verde Station', 'What do you trust most — what you see, what you''re told, or your instincts? On a year long solo mission aboard Verde Station, you will test your wits and question everything, but you may not find answers. Welcome to solitude.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/324120/header.jpg?t=1666983352', 0, 1, NULL);
INSERT INTO games VALUES (74804, 324140, 'Kalimba', 'Jump, switch and fly your way through mind-bending subterranean puzzles in this stunning new platforming adventure from the award-winning Press Play!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/324140/header.jpg?t=1577993615', 0, 0, NULL);
INSERT INTO games VALUES (74805, 324160, 'CLANNAD', 'From the world renowned visual novel studio Key, the highly rated story of CLANNAD is now available on Steam! Improved visuals, achievement integration, and Dangopedia make this the best version of CLANNAD to date.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/324160/header.jpg?t=1711546691', 0, 0, NULL);
INSERT INTO games VALUES (74806, 324170, 'Pyrite Heart', 'When a feud with her brother gets too hot, Princess Ahri Remono, a young woman with a heart of fire, accepts a challenge that she cannot thrive in the world outside the Imperial Palace. In her first day in class, the boisterous princess finds a potential rival in the student body president.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/324170/header.jpg?t=1667476015', 0, 0, NULL);
INSERT INTO games VALUES (74807, 324190, 'CodeSpells', 'Craft any magical spell you can imagine using the most powerful tool there is: code. CodeSpells is currently an unguided, sandbox experience for the bravest wizards who want to help the developers steer the game''s development.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/324190/header.jpg?t=1600127747', 0, 0, NULL);
INSERT INTO games VALUES (74809, 324260, 'VoidExpanse', 'Explore the vast reaches of VoidExpanse -- mine asteroids, upgrade your ship, trade, complete missions, advance your character and survive fast-paced combat with hostile aliens and mercenaries in the rich and exciting Sci-Fi universe of VoidExpanse!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/324260/header.jpg?t=1567744660', 0, 0, NULL);
INSERT INTO games VALUES (74782, 324310, 'Bus Simulator 16', 'Get behind the wheel of 13 realistic city buses licensed by known city bus manufacturers such as Mercedes-Benz and MAN. Keep an eye on the traffic code and drive your passengers safely to their destinations through five characteristic city districts.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/324310/header.jpg?t=1741870329', 0, 0, NULL);
INSERT INTO games VALUES (74787, 324510, 'Boundless', 'Shape your citizen, forge your destiny and sculpt your world in this epic voxel sandbox MMO built on endless possibility.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/324510/header.jpg?t=1664896924', 0, 0, NULL);
INSERT INTO games VALUES (74788, 324520, 'Defense Zone 3 Ultra HD', 'The sequel to the hit strategy game, with new weapons, landscapes, and options.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/324520/header.jpg?t=1667406596', 1, 0, NULL);
INSERT INTO games VALUES (74789, 324570, 'Halo: Spartan Strike', 'Halo: Spartan Strike makes you a Spartan supersoldier battling evil forces. Delve into 30 challenging missions through cities and jungles using a devastating arsenal of weapons, abilities and vehicles including the iconic Warthog against the Covenant and Promethean enemies. *DirectX feature level 10 required*', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/324570/header.jpg?t=1667852209', 0, 0, NULL);
INSERT INTO games VALUES (74791, 324650, 'Gemini: Heroes Reborn', 'Gemini: Heroes Reborn is a first person action-adventure that allows users to enter into the role of Cassandra, on a journey to unlock incredible powers, unique in the Heroes Universe.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/324650/header.jpg?t=1453179566', 1, 0, NULL);
INSERT INTO games VALUES (74792, 324680, 'Impossible Creatures Steam Edition', 'Impossible Creatures is a 3D RTS game that pits the player against an evil villain. Using Earth’s most formidable animals as building blocks, the player must create an army of genetically-altered mutant monsters in a titanic struggle to protect an unsuspecting world.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/324680/header.jpg?t=1727859869', 0, 0, NULL);
INSERT INTO games VALUES (74793, 324710, 'To Be or Not To Be', 'Guide Hamlet, Ophelia and Hamlet Sr. to hundreds of hilarious deaths in Ryan North''s chooseable-path edition of Shakespeare''s Hamlet!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/324710/header.jpg?t=1716210457', 0, 0, NULL);
INSERT INTO games VALUES (74795, 324740, 'The Warlock of Firetop Mountain', 'The Warlock of Firetop Mountain is a tabletop adventure come to life! This fantasy solo RPG combines unique, simultaneous turn-based combat with a journey that changes based on each figurine you take into Firetop Mountain! Which hero will you take into Zagor''s lair THIS time?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/324740/header.jpg?t=1726371740', 0, 0, NULL);
INSERT INTO games VALUES (74774, 324760, 'Monster Truck Destruction', 'Can you handle a 1500HP Monster Truck that can crash cars, get massive air and pop wheelies with a blip of the throttle? Monster Truck Destruction is here to satisfy all of these needs plus more!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/324760/header.jpg?t=1570769772', 1, 0, NULL);
INSERT INTO games VALUES (74776, 324800, 'Shadow Warrior 2', 'Shadow Warrior 2 is the stunning evolution of Flying Wild Hog’s offbeat first-person shooter starring the brash warrior Lo Wang, who must again wield a devastating combination of guns, blades, magic and wit to strike down the demonic legions overwhelming the world.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/324800/header.jpg?t=1728689727', 0, 0, NULL);
INSERT INTO games VALUES (74777, 324810, 'TOXIKK™', 'FRAG LIKE IT''S 1999! TOXIKK plays as if today''s military shooters never existed: Designed as a spiritual successor to the FPS giants of the late 90s and early 2ks, TOXIKK carefully evolves their mechanics with modern technology and fresh ideas elaborated with Arena-FPS enthusiasts.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/324810/header.jpg?t=1644043937', 0, 1, NULL);
INSERT INTO games VALUES (74779, 325090, 'Deep Dungeons of Doom', 'This game is only for the brave. Dungeons await, each one deeper, each one more perilous and each one more challenging than the last.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/325090/header.jpg?t=1671026504', 0, 0, NULL);
INSERT INTO games VALUES (74780, 325120, 'Notch - The Innocent LunA: Eclipsed SinnerS', 'This is an isolated town, a town of memories that have been forgotten by its people. However, this small town has not been quiet and peaceful since the murders began... Time passes by, where are the sinful spirits going? Are my memories reality, or just a dream?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/325120/header.jpg?t=1630746350', 0, 0, NULL);
INSERT INTO games VALUES (74767, 325210, 'Arctico', 'Explore Arctico with your dog sled, kayak, and parachute! Build and customize your base camp, gather resources and samples, set up labs, and take good care of your dogs in this peaceful island.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/325210/89e50d84e0abd8a0fe73dd04f5661880865a630f/header_alt_assets_6.jpg?t=1749144482', 0, 0, NULL);
INSERT INTO games VALUES (74772, 325420, 'Homebrew - Patent Unknown', 'Unleash your creativity and craft anything from flying cars to jet-powered toilets.Fair warning: there''s a learning curve. But once you''ve got it, the sky''s the limit for your creations!While active development is paused, we focus preserving the game and keeping it accessible.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/325420/header.jpg?t=1719789927', 0, 0, NULL);
INSERT INTO games VALUES (74762, 325520, 'Fire: Ungh’s Quest', 'FIRE is an exploration-adventure with intuitive puzzle design. Without losing many words it tells a savagely hilarious story. Journey into the Stone Age and face the most challenging task of this era: The search for fire!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/325520/header.jpg?t=1591885179', 0, 0, NULL);
INSERT INTO games VALUES (140062, 325610, 'Total War: ATTILA', 'Against a darkening background of famine, disease and war, a new power is rising in the great steppes of the East. With a million horsemen at his back, the ultimate warrior king approaches, and his sights are set on Rome… The next instalment in the multi award-winning PC series that combines turn-based strategy with real-time tactics,...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/325610/header.jpg?t=1724864047', 0, 0, NULL);
INSERT INTO games VALUES (74764, 325730, 'The Hive', 'The Hive is a strategy game with RPG elements where you assume command as the insectoid hivemind. Build and expand your underground colony, harvest resources, and evolve your swarm using DNA. Will you survive in this hostile yet beautiful underworld?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/325730/header.jpg?t=1745853009', 0, 0, NULL);
INSERT INTO games VALUES (74761, 325930, 'Viking Squad', 'Grab your trusty sword, strap on a fearsome helmet, and plunge into the chaotic fray of Viking Squad! In this three player co-op brawler you must put a stop to the wildly mischievous Loki and reopen the gates to Valhalla. Find a friend for local co-op couch play or find a match online!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/325930/header.jpg?t=1660780705', 0, 0, NULL);
INSERT INTO games VALUES (74751, 326150, 'Death Skid Marks', 'Death Skid Marks is a rogue-like car combat game about what so many of us have experienced: a road trip to a music gig… only in this game, things get violent. The game uniquely blends top down arcade action and RPG mechanics.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/326150/header.jpg?t=1661178384', 0, 1, NULL);
INSERT INTO games VALUES (74752, 326160, 'Shroud of the Avatar: Forsaken Virtues', 'SHROUD OF THE AVATAR: FORSAKEN VIRTUES is a multiplayer fantasy RPG that sets the player on a path filled with peril and tough choices as they explore a persistent realm that can be shared with other Avatars. It is the spiritual successor to Richard Garriott’s Ultima games.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/326160/header.jpg?t=1648783162', 0, 1, NULL);
INSERT INTO games VALUES (74753, 326180, 'Sinister City', 'Who would name their town Sinister City? Vampires, of course! When John discovers his bride-to-be has been kidnapped by Sinister City''s number one bloodsucker, there''s only one thing to do - search for hidden objects! And kill vampires! Or at least insult them until they give your girl back.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/326180/header.jpg?t=1728890055', 0, 0, NULL);
INSERT INTO games VALUES (74754, 326190, 'Alchemy Mysteries: Prague Legends', 'Follow orphan Eva on a trip to mystical Prague in Alchemy Mysteries: Prague Legends.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/326190/header.jpg?t=1482754414', 1, 0, NULL);
INSERT INTO games VALUES (74755, 326340, 'River City Super Sports Challenge ~All Stars Special~', 'This is the River City sports challenge! The Rule is simple, be the # 1 in 4 events by all means. That''s it! Hitting and kicking? Of course! Wooden swords dumbbells and even bombs are available to use. The great sports challenge where anything''s possible has just begun!!!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/326340/header.jpg?t=1667791280', 1, 0, NULL);
INSERT INTO games VALUES (74758, 326410, 'Windward', 'Windward is an action-filled multiplayer sandbox game that puts you in control of a ship sailing the high seas of a large procedurally-generated world.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/326410/header.jpg?t=1740963914', 0, 0, NULL);
INSERT INTO games VALUES (74741, 326460, 'ShellShock Live', 'Demolish your friends with hundreds of upgradable weapons shot from your customizable tank in this action-packed online multiplayer tanks game. Earn XP to level up and unlock new tanks, weapons, and gear. Fight against or alongside your friends for strategic team or free-for-all matches.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/326460/header.jpg?t=1683306935', 0, 0, NULL);
INSERT INTO games VALUES (74743, 326480, 'If My Heart Had Wings', 'An animated visual novel of a lovely and bittersweet tale of youth, you play as Aoi Minase in this romantic-comedy as he meets various young girls in his hometown and works together with them to revive their school’s glider-flying “Soaring Club” in order to realize their shared dream of flight.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/326480/header.jpg?t=1728283310', 0, 0, NULL);
INSERT INTO games VALUES (74727, 326720, 'Instant Dungeon!', 'Instant Dungeon! mixes dungeon exploration with arcade action in the vein of the classic maze games from the 80s. Let Instant Dungeon! create a new dungeon just for you, complete with glittering treasures, vicious monsters, brutal boss battles, wild power ups and most importantly fun, Fun, FUN!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/326720/header.jpg?t=1478035923', 0, 0, NULL);
INSERT INTO games VALUES (74729, 326840, 'Heart&Slash', 'Fight as Heart, an innocent robot fighting to escape the grip of mindless machines in a future where humans are no more. A fast-paced 3D brawler with roguelike elements set in a colorful yet desolated world.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/326840/header.jpg?t=1668678291', 0, 0, NULL);
INSERT INTO games VALUES (74735, 327030, 'Worms W.M.D', 'The worms are back in their most destructive game yet. With a gorgeous, hand-drawn 2D look, brand new weapons, the introduction of crafting, vehicles and buildings plus the return of some much-loved classic weapons and gameplay, Worms W.M.D is the best worms experience ever.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/327030/header.jpg?t=1741368076', 0, 0, NULL);
INSERT INTO games VALUES (74736, 327060, 'FEIST', 'A desperate, savage survival experience full of stunning visuals, dynamic creatures, and a haunting soundtrack.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/327060/header.jpg?t=1666984601', 0, 0, NULL);
INSERT INTO games VALUES (74737, 327090, 'Out of Reach', 'You’re a castaway stranded in the middle of nowhere. Storm is gone, the worst certainly not. Look for food and resources, craft gear, make shelters. These are the basics, you need much more to stay alive on this cut-off-the-world, yet not desert island. Build &amp; burn, sail &amp; explore, be Out of Reach!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/327090/header.jpg?t=1724757086', 1, 0, NULL);
INSERT INTO games VALUES (74738, 327140, 'Tilt Brush', 'Tilt Brush lets you paint in 3D space with virtual reality. Unleash your creativity with three-dimensional brush strokes, stars, light, and even fire. Your room is your canvas. Your palette is your imagination. The possibilities are endless.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/327140/header.jpg?t=1726856282', 0, 1, NULL);
INSERT INTO games VALUES (74713, 327220, 'Anna''s Quest', 'With her telekinesis, unorthodox use of torture instruments, a knack for improvisation and the help of a shady fox she makes her way from the peaks of Glass Mountain to the deepest dungeon.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/327220/header.jpg?t=1734992194', 0, 0, NULL);
INSERT INTO games VALUES (74714, 327260, 'Super Life of Pixel', 'Join Pixel as he quests through gaming history, teleporting across the most iconic video game systems of generations past. He’ll have to jump, dodge and play smart if he wants to survive all the traps, puzzles and enemies waiting to take him down at every turn.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/327260/header.jpg?t=1545342515', 0, 0, NULL);
INSERT INTO games VALUES (74715, 327310, 'The Marvellous Miss Take', 'The stealth genre gets turned on its head in The Marvellous Miss Take – the only heist adventure that invites you to steal with style! Use cunning, guile and the art of deception to grab the loot and escape without getting caught by the guards!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/327310/header.jpg?t=1657711181', 0, 0, NULL);
INSERT INTO games VALUES (74718, 327390, 'Sid Meier''s Covert Action (Classic)', 'Sid Meier''s Covert Action - A Techno-Thriller From the Case Files of Max Remington.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/327390/header.jpg?t=1689356790', 0, 0, NULL);
INSERT INTO games VALUES (74719, 327400, 'Sid Meier''s Colonization (Classic)', 'The New World lies before you with all its peril, promise and infinite possibility. Your colonists anxiously follow you to shore. The treasures of an entire continent await you.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/327400/header.jpg?t=1726253764', 0, 0, NULL);
INSERT INTO games VALUES (74720, 327410, 'A Bird Story', 'An experimental short from the creator of To the Moon &amp; Finding Paradise: A simple &amp; surreal 1-hour interactive animation about a boy and an injured bird, told without dialogues.If you''re looking for To the Moon-like experience, I''d suggest playing Finding Paradise first.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/327410/header.jpg?t=1726196470', 1, 0, NULL);
INSERT INTO games VALUES (74721, 327440, 'Hail to the King: Deathbat', 'Deathbat is a 3rd person, overhead dungeon crawler action RPG in the vein of The Legend of Zelda, Gauntlet Legends, and Diablo. The game’s story is based on the mythical origin of the Deathbat, Avenged Sevenfold’s logo and mascot.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/327440/header.jpg?t=1447364091', 1, 0, NULL);
INSERT INTO games VALUES (74724, 327510, 'WASTED', 'Get wasted or get wasted trying in WASTED, a roguelike post-apocalyptic pub crawler. Fight tooth and nail, bullets and baseball bats in search of Booze, gain strange mutational Hangovers, and explore the Coolers in search of powerful weapons, armor, and a nice stiff drink to top it all off.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/327510/header.jpg?t=1721335621', 0, 0, NULL);
INSERT INTO games VALUES (74725, 327560, 'Near Death', 'Stranded at an abandoned Antarctic research base with no hope of rescue, you must battle a deadly blizzard in a desperate fight to find your way home.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/327560/header.jpg?t=1702826489', 0, 0, NULL);
INSERT INTO games VALUES (74696, 327670, 'Ironcast', 'Puzzlequest meets FTL in this Steampunk Victorian era roguelite.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/327670/header.jpg?t=1667318712', 0, 0, NULL);
INSERT INTO games VALUES (74698, 327740, 'TRON 2.0', 'Over 35 levels of challenging gameplay -- Race at the speed of light, fight off computer Viruses and engage in violent digital combat.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/327740/header.jpg?t=1741820401', 0, 0, NULL);
INSERT INTO games VALUES (74700, 327860, 'Salt', 'Salt is an open world exploration game where you sail from island to island looking for loot and new discoveries! Relax and explore at your own pace, picking a direction and setting sail across a vast ocean filled with quests, merchants, ruins, pirates, and other mysterious places.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/327860/header.jpg?t=1659464610', 0, 0, NULL);
INSERT INTO games VALUES (74701, 327880, 'Sublevel Zero Redux', 'Sublevel Zero Redux is a roguelite six-degree-of-freedom shooter in a universe where reality is falling apart. Use your zero-g gunship to fight through a vast underground facility, looting advanced weapons to destroy hordes of deadly enemies.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/327880/header.jpg?t=1589293679', 0, 0, NULL);
INSERT INTO games VALUES (74702, 327890, 'I Am Bread', 'You are bread. Your mission, become toast! Take on all hazards to deliciousness as you head on an epic adventure in one of the the toughest games ever baked. All of the game modes (including Bagel Race) are now unlocked so there''s sure to be something to suit everyone''s taste!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/327890/header.jpg?t=1739399026', 0, 0, NULL);
INSERT INTO games VALUES (74705, 327930, 'Darklands', 'Deep in the twilight of the Black Forest, you and your companions crouch before the robber-knight''s tower. Hans, the alchemist, places his mysterious potion by the door. Ebhard the friar implores Saint Dunstan to bless your weapons and armor. And you and Gretchen grip naked long swords, praying your plate mail won''t squeak.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/327930/header.jpg?t=1602618288', 0, 0, NULL);
INSERT INTO games VALUES (74707, 327950, 'Sword of the Samurai', 'Enter Japan in the age of warring states. At the center of this role-playing, action-adventure simulation of combat, statesmanship and intrigue, you are a samurai warrior struggling for honor!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/327950/header.jpg?t=1689356979', 0, 0, NULL);
INSERT INTO games VALUES (74711, 328070, 'Reflex Arena', 'Reflex is a competitive Arena FPS that combines modern tech with the speed, precision and freedom of a 90s shooter. If you sunk countless hours into the Quake or Unreal series, Reflex will feel like a welcome return of the old school shooter feel.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/328070/header.jpg?t=1520508771', 0, 0, NULL);
INSERT INTO games VALUES (74683, 328080, 'Rise to Ruins', 'A brutal godlike village sim that melds the god game, management, and tower defense genres! Fight off hoards of monsters at night, and expand your village in the day time. Inspired by games like Black and White, Rimworld, and Dwarf Fortress but not quite like any of them.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/328080/header.jpg?t=1695161904', 0, 0, NULL);
INSERT INTO games VALUES (74685, 328220, 'Wild Season', 'Wild Season is a farming-life sim that takes its foundations from the greats within the farming simulation, visual novel, and RPG genres and delivers them with a twist. Rebuild your farm to its former glory and beyond, befriend the townspeople and maybe find your one true love (of either gender!), and solve the secret of Bedford Valley.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/328220/header.jpg?t=1458649910', 0, 0, NULL);
INSERT INTO games VALUES (74686, 328270, 'Leviathan: The Last Day of the Decade', '&quot;Leviathan: The Last Day of the Decade&quot; is a detective story told by a dweller of a cruel dark fantasy world affected by the pandemic. The world ruled by a five noble-born kins under the suzerainty of the undead Plague King.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/328270/header.jpg?t=1614157532', 0, 0, NULL);
INSERT INTO games VALUES (74691, 328470, 'Slave Zero', 'It''s 500 years in the future. Man and machine are virtually one, and the greatest megacity in the world is locked in a brutal war. Your mission: steal the largest, most sophisticated bio-mechanical attack weapon ever designed...and kick some serious ass!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/328470/header.jpg?t=1602618343', 0, 0, NULL);
INSERT INTO games VALUES (74692, 328500, 'Potatoman Seeks the Troof', 'Potatoman will put your reflexes and worldview to the test as you journey through scorching deserts, dark forests, busy cities, the tallest mountains and eventually your own potato-consciousness in search of the ultimate answer. Are you prepared to face the TROOF?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/328500/header.jpg?t=1588696190', 0, 0, NULL);
INSERT INTO games VALUES (74695, 328590, 'Don''t Knock Twice', 'Don''t Knock Twice is a first-person horror game based on a psychologically terrifying urban legend. One knock to wake her from her bed, twice to raise her from the dead. Supports VR on HTC Vive and Oculus Rift for the ultimate horror experience!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/328590/header.jpg?t=1727964579', 1, 0, NULL);
INSERT INTO games VALUES (74671, 328730, 'Letter Quest: Grimm''s Journey', 'Ever wondered what would happen if you crossed Scrabble with an RPG? Now you don''t have to, because Letter Quest is here! Help Grimm and Rose, a couple of adorable grim reapers, defeat monsters, ghosts, evil bunnies and more using the power of words!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/328730/header.jpg?t=1593028821', 0, 0, NULL);
INSERT INTO games VALUES (74673, 328760, 'SanctuaryRPG: Black Edition', 'SanctuaryRPG: Black Edition is a humorous and strategic turn-based dungeon crawling ASCII adventure. Drawing heavy inspiration from both Roguelikes and Japanese RPGs, the game offers a robust action-RPG inspired combat system.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/328760/header.jpg?t=1614781262', 0, 0, NULL);
INSERT INTO games VALUES (74681, 328940, 'The Deer God', 'The Deer God is a breathtaking 3D pixel art adventure that will challenge your religion and your platforming skills. It''s a game about survival, reincarnation, and karma; all set in a breathtaking and unique 3D pixelized world. Feast your eyes on the beautiful lighting, day and night system, and vast landscapes.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/328940/header.jpg?t=1447364283', 0, 0, NULL);
INSERT INTO games VALUES (74651, 329050, 'Devil May Cry 4 Special Edition', 'The smash-hit stylish action game DMC4 is back and better than ever, boasting new playable characters and game modes!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/329050/header.jpg?t=1644282580', 0, 0, NULL);
INSERT INTO games VALUES (74652, 329070, 'SpyParty', 'SpyParty is a competitive espionage game about subtle human behavior. A Spy hides in plain sight at a fancy cocktail party, trying to accomplish missions while blending in with the other guests, while a Sniper with a single bullet looks inward, searching for the Spy.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/329070/header.jpg?t=1726041201', 0, 0, NULL);
INSERT INTO games VALUES (74653, 329130, 'Reassembly', 'A spaceship building and universe-exploration game. Collect resources, expand and grow your fleet, and conquer your personal galaxy. Stellar ambience by Peaks.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/329130/header.jpg?t=1656135184', 0, 0, NULL);
INSERT INTO games VALUES (74654, 329190, 'Volo Airsport', '**Development of this game is discontinued** - Take to the skies and fly past mountains in a wingsuit. Try to hug the cliffs at over 250 km/h or cruise at high altitudes and admire the scenery.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/329190/header.jpg?t=1608979814', 0, 0, NULL);
INSERT INTO games VALUES (74655, 329200, 'Astray', 'Astray is a first-person horror/puzzle game set in an abandoned museum based on unusual cultures, legends, and supernatural themes. But something more sinister lurks beneath the surface..', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/329200/header.jpg?t=1619434865', 0, 0, NULL);
