INSERT INTO games VALUES (74645, 329860, 'Catlateral Damage', 'Catlateral Damage is a first-person destructive cat simulator where you play as a cat on a rampage, knocking as much stuff onto the ground as possible.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/329860/header.jpg?t=1745442140', 0, 0, NULL);
