INSERT INTO games VALUES (74625, 330100, 'BossConstructor', 'Scavenge modules, combine them in the deadliest and most efficient ways imaginable, and fly your very own spaceship through alien space with BossConstructor. Thousands of procedurally generated galaxies await you and your space-faring collection of assembled modules to explore them.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/330100/header.jpg?t=1654779699', 0, 0, NULL);
