INSERT INTO games VALUES (74627, 330270, 'Warlocks vs Shadows', 'Slay monsters. Defeat epic bosses. Collect magical gear. Become a Warlock and save the universe.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/330270/header.jpg?t=1478069130', 1, 0, NULL);
INSERT INTO games VALUES (74628, 330350, 'Robotex', 'Life on Earth is unsustainable. Humanity must seek a new home but the only planet found is very hostile. You were sent on a expedition to slay the monsters inhabiting the surface of this planet. In this adventure you end up being the villain. Game contains two basic controls, many puzzles and lots of guns and enemies.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/330350/header.jpg?t=1726270553', 1, 0, NULL);
INSERT INTO games VALUES (74632, 330460, 'Celestial Command', 'Mine asteroids, salvage space debris, design your own small or massive spacecraft using individual functional components, complete missions, and engage in battles against enemies in a vast galaxy with realistic physics based on orbital mechanics or in a classic physics mode.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/330460/header.jpg?t=1699181351', 1, 0, NULL);
INSERT INTO games VALUES (74614, 330580, 'Shark Attack Deathmatch 2', 'Combat in Shark Attack Deathmatch 2 is savage, gritty, and brutal. Players hunt each other down in various game modes with the constant threat of terrifying sharks joining in on the bloodshed. Tear divers apart as you take on the role as the ocean''s top apex predator, The Great White.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/330580/header.jpg?t=1675792361', 1, 0, NULL);
