INSERT INTO games VALUES (74620, 330720, 'Flashpoint Campaigns: Red Storm Player''s Edition', 'You are the commander of either NATO or Soviet forces locked in battle on the ground in 1980’s Central Europe. As commander, it is your task to provide the battle plan orders to your units. You need to know your mission objectives, strength and weakness of both your forces and you enemy, lay of the land, weather, and time of day in order...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/330720/header.jpg?t=1726823564', 0, 0, NULL);
INSERT INTO games VALUES (74622, 330820, '2064: Read Only Memories', '2064: Read Only Memories is a cyberpunk thriller that explores the social challenges of tomorrow through classic adventure gaming. A journalist-turned-detective teams up with Turing, the world’s first sapient machine, to unmask a conspiracy that will shake the foundations of Neo-San Francisco.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/330820/header.jpg?t=1712088920', 0, 0, NULL);
