INSERT INTO games VALUES (74613, 330990, 'Demon Hunter: Chronicles from Beyond', 'Discover your true identity and face a mysterious entity from another dimension!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/330990/header.jpg?t=1584464438', 1, 0, NULL);
