INSERT INTO games VALUES (74596, 331650, 'Carmageddon TDR 2000', 'Yes, it''s the game literally... SOME of you asked for! And so, in the spirit of &quot;well, alright then, if you insist...&quot; we present the third game in the Carmageddon series, in the knowledge that some of you Carma fans out there would like to have a complete Carmageddon collection in your Steam library. Nothing wrong with that.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/331650/header.jpg?t=1727865293', 0, 0, NULL);
