INSERT INTO games VALUES (74580, 331970, 'Disney''s Treasure Planet: Battle of Procyon', 'Disney''s Treasure Planet: Battle at Procyon is a 3D RTS game focusing on space combat.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/331970/header.jpg?t=1571778010', 0, 0, NULL);
