INSERT INTO games VALUES (74564, 332330, 'PixelJunk™ Shooter Ultimate', 'CAN YOU SAVE THE SCIENTISTS ON APOXUS PRIME?PixelJunk™ Shooter Ultimate is a twin-stick shooter with equal elements of action and puzzle solving.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/332330/header.jpg?t=1667297620', 0, 0, NULL);
INSERT INTO games VALUES (74565, 332360, 'Spriter Pro', 'Spriter makes it easy for anyone, regardless of experience, to create 2D game animations using a technique called Modular Animation. Individual sprite pieces can be attached to bones and then easily animated with the powerful, yet easy to use toolset.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/332360/header.jpg?t=1667385572', 0, 0, NULL);
INSERT INTO games VALUES (74570, 332480, 'Phoenix Force', 'Phoenix Force is a shoot ''em up about a group of phoenixes that fight big and strong mythological creatures in over 100 levels. It takes the boss battle as the foundation for every level, creating engaging and challenging fast battles that will require your best strategies and reflexes.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/332480/header.jpg?t=1659727370', 1, 0, NULL);
INSERT INTO games VALUES (74571, 332490, 'Battle Fleet 2', 'Welcome Admiral! Select your fleet, assign weapons, and sink the enemy fleet by controlling each of your ships down to setting the aim and range of each weapon''s shot. Features include full open world Pacific &amp; Atlantic campaigns, cross-platform multiplayer and awesome turn-based naval battles.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/332490/header.jpg?t=1734351060', 0, 0, NULL);
INSERT INTO games VALUES (74572, 332500, 'GRAV', 'GRAV is a sand box experience where you explore a multitude of planets, hunt strange alien creatures, build and defend outposts, craft weapons and armor, and attempt to survive against other players in a hostile environment.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/332500/header.jpg?t=1478820787', 0, 0, NULL);
INSERT INTO games VALUES (74575, 332570, 'Amazing Frog?', 'Amazing Frog? is the original open world buffet of bonkers physics sandbox mayhem. For one to four players.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/332570/header.jpg?t=1748881133', 0, 0, NULL);
INSERT INTO games VALUES (74549, 332610, 'Mystik Belle', 'A colorful pixel-art metroidvania/point-and-click adventure hybrid about magic, cute witches and joys of vandalism.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/332610/header.jpg?t=1728320042', 0, 0, NULL);
INSERT INTO games VALUES (74556, 332790, 'Darkness Assault', 'The number of missing in the city increased. People talk about the experiments on human beings. And now, only you can figure out if it was true. Especially because you have no choice. Mysteriously, you find yourself in a terrible location 40 meters underground. Your name is Katrine, and you do not remember anything about your past.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/332790/header.jpg?t=1479023300', 0, 0, NULL);
INSERT INTO games VALUES (74557, 332800, 'Five Nights at Freddy''s 2', 'Welcome back to the new and improved Freddy Fazbear''s Pizza! As always, Fazbear Entertainment is not responsible for death or dismemberment.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/332800/header.jpg?t=1579635993', 0, 0, NULL);
INSERT INTO games VALUES (140035, 332950, 'Dark Deception', 'Death awaits you in Dark Deception, a story-driven first-person horror maze game. There''s nowhere to hide &amp; nowhere to catch your breath. Run or die - it''s your choice. Trapped in a realm of nightmarish mazes with a mysterious woman, your only hope of survival is to find a way to escape.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/332950/header.jpg?t=1693784243', 1, 1, NULL);
INSERT INTO games VALUES (74540, 333210, 'Kaiju-A-GoGo', 'Choose your giant monster! Destroy cities around the world! Rule the Earth in this light action-strategy game that harkens back to the classic PC monster city-stomping games of yesteryear!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/333210/header.jpg?t=1667938541', 0, 0, NULL);
INSERT INTO games VALUES (74541, 333250, 'Forward to the Sky', 'Reveal the story of the sky tower! Forward to the Sky is a third person action adventure game in the sky tower ruin. You are going to collect all the crystal pieces to connect the story and everything will be revealed once Princess reaches the top level.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/333250/header.jpg?t=1577159949', 1, 0, NULL);
INSERT INTO games VALUES (74544, 333300, 'ADOM (Ancient Domains Of Mystery)', 'ADOM (Ancient Domains Of Mystery) is one of the most successful roguelike games ever created, boasting a brilliant mix of story, RPG, exploration, and intensely strategic &amp; flexible combat. The Steam version adds various features like achievements, difficulty level customization &amp; play modes.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/333300/header.jpg?t=1728905558', 0, 0, NULL);
INSERT INTO games VALUES (74525, 333420, 'Cossacks 3', 'Cossacks 3 is the return of RTS classics. Obtain resources, build cities and research technologies while taking command of great armies, crushing enemies in grand historical warfares on land and sea!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/333420/header.jpg?t=1678808308', 0, 0, NULL);
INSERT INTO games VALUES (74526, 333430, 'Sinking Island', 'Walter Jones, a billionaire had planned on opening up a resort for the rich and famous, but was killed before his dream could be achieved. It''s up to Detective Jack Norm to crack the case by interviewing the people on Sinking Island to get valuable clues. A game from Benoit Sokal.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/333430/header.jpg?t=1709847350', 0, 0, NULL);
INSERT INTO games VALUES (74531, 333600, 'NEKOPARA Vol. 1', 'What''s NEKOPARA? Why, it''s a cat paradise! Kashou Minaduki, the son of a long line of Japanese confection makers moved out to open his own shop &quot;La Soleil&quot; as a patisserie.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/333600/header.jpg?t=1656892670', 0, 0, NULL);
INSERT INTO games VALUES (137897, 333640, 'Caves of Qud', 'Caves of Qud is a science fantasy roguelike epic steeped in retrofuturism, deep simulation, and swathes of sentient plants. Come inhabit an exotic world and chisel through layers of thousand-year-old civilizations.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/333640/header.jpg?t=1748542836', 0, 0, NULL);
INSERT INTO games VALUES (74511, 333880, 'Braveland Wizard', 'Braveland Wizard - old school turn-based strategy game is back! The graduate of the Academy of Magic is ready for new adventures.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/333880/header.jpg?t=1713375721', 0, 0, NULL);
INSERT INTO games VALUES (74512, 333930, 'Dirty Bomb®', 'Work together or die alone! Fight to restore peace to London or tear it down for profit in the most challenging team based shooter around.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/333930/header.jpg?t=1745569968', 0, 1, NULL);
INSERT INTO games VALUES (74513, 333950, 'Medieval Engineers', 'Medieval Engineers is a sandbox game about engineering, construction and the maintenance of architectural works and mechanical equipment using medieval technology. Players build castles; construct mechanical devices and underground mining. There is an entire planet to explore!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/333950/header.jpg?t=1726043012', 0, 0, NULL);
INSERT INTO games VALUES (74515, 333980, 'AKIBA''S TRIP: Undead ＆ Undressed', 'In Tokyo’s popular ”Electric Town” district, Akihabara, vampires called “Synthisters” walk among us. You must identify and dispose of them the only way you know how – by engaging them in hand-to-hand combat in order to strip them of their clothes so their bodies melt away in the sunlight.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/333980/header.jpg?t=1740441159', 0, 0, NULL);
INSERT INTO games VALUES (74518, 334040, 'Down To One', '42 Players Start. Only 1 will survive.Down to One is a competitive survival shooter in a large, interactive, open-world environment. Start out with nothing, and use anything you can find in the environment to survive, and eliminate other competitors over the course of a brutal round.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/334040/header.jpg?t=1696714961', 0, 0, NULL);
INSERT INTO games VALUES (74519, 334070, 'Hektor', 'Experience terrors only madness can conjure in HEKTOR, a psychological horror game set in a world that literally moves with your every twist and turn.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/334070/header.jpg?t=1511370920', 0, 0, NULL);
INSERT INTO games VALUES (74521, 334120, 'Armikrog', 'Armikrog is a unique stop motion clay animated point and click adventure game from the creators of Earthworm Jim and the Neverhood. Unravel the mysteries of the fortress that holds Tommynaut and his blind alien talking dog Beak-Beak captive through exploration and puzzle solving!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/334120/header.jpg?t=1628277215', 0, 0, NULL);
INSERT INTO games VALUES (74523, 334190, 'Insanity''s Blade', 'Take a father’s journey to hell in order to save the souls of his wife and child. Insanity''s Blade: The Chronicles of Thurstan is the first in a series of games based around the journey of a sword possessed by a father''s powerful grief and hatred. This is the tale of the sword''s creation.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/334190/header.jpg?t=1579539494', 0, 0, NULL);
INSERT INTO games VALUES (74524, 334210, 'Fortified', 'Fortified is an explosive strategy shooter where players will defend the Earth against a menacing Martian invasion in the 1950s. Play as one-of-four pulp inspired heroes as they fight swarms of terrifying robots with an arsenal of Cold War era weapons and experimental technology.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/334210/header.jpg?t=1622741821', 0, 0, NULL);
INSERT INTO games VALUES (74493, 334230, 'Town of Salem', 'Inspired by the party games Werewolf and Mafia, Town of Salem is a game of murder, mystery and deception.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/334230/header.jpg?t=1723907185', 0, 0, NULL);
INSERT INTO games VALUES (74499, 334310, 'Plebby Quest: The Crusades', 'Survive ambitious rulers dreaming of an empire, outsmart treacherous neighbors longing to burn your spoils, and navigate the religion’s predictably unreasonable demands; you need ask only one question as you build your legacy – “Will you burn them, or be burnt?”', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/334310/header.jpg?t=1723791348', 1, 0, NULL);
INSERT INTO games VALUES (74503, 334420, 'Out There: Ω Edition', 'Out There is an award-winning space exploration game blending roguelike, resource management and interactive fiction.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/334420/header.jpg?t=1611396181', 0, 0, NULL);
