INSERT INTO games VALUES (74484, 334850, '1931: Scheherazade at the Library of Pergamum', '1931: Scheherazade at the Library of Pergamum is the latest story-driven RPG from Black Chicken Studios, inc., spinning tales of pulp adventure, exotic locations, occult horror, and romance that''ll require well-honed skills.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/334850/header.jpg?t=1447365390', 0, 0, NULL);
INSERT INTO games VALUES (74486, 334940, 'Yoku''s Island Express', 'Meet Yoku, the pint-sized postman protagonist of Yoku''s Island Express! Use a unique blend of pinball mechanics, platforming and open world exploration to unlock the secrets of Mokumana Island, help the locals, awaken ancient deities and much more in this amazing new tropical adventure!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/334940/header.jpg?t=1726495927', 1, 0, NULL);
INSERT INTO games VALUES (74489, 335000, 'Tormentum - Dark Sorrow', 'TORMENTUM is a dark Point &amp; Click adventure game.The dreamlike, nightmarish atmosphere of the game was inspired by works of painters H.R. Giger and Zdzislaw Beksinski. The game''s final look and feel was also strongly influenced by the universes of games such as Demon''s Souls or Dark Seed.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/335000/header.jpg?t=1680196339', 0, 0, NULL);
