INSERT INTO games VALUES (74466, 335100, 'Dwarf Tower', 'Dwarf Tower is a turn-based tactics game of tower building and spellcasting. Each turn you develop your tower by placing blocks, constructing rooms, and play various spells. Your tower can have Libraries (store spells), Crystals (generate mana), Dwarf Dwellings (give you dwarves to repair the tower) and some other rooms.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/335100/header.jpg?t=1687334236', 0, 0, NULL);
INSERT INTO games VALUES (74467, 335120, 'Serpent in the Staglands', 'A true role-playing adventure. Set in the icy Staglands, this party-based CRPG has you take the role of a trapped god on a perilous journey across a beautiful, deadly peninsula.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/335120/header.jpg?t=1598897193', 0, 0, NULL);
