INSERT INTO games VALUES (74472, 335300, 'DARK SOULS™ II: Scholar of the First Sin', 'DARK SOULS™ II: Scholar of the First Sin brings the franchise’s renowned obscurity &amp; gripping gameplay to a new level. Join the dark journey and experience overwhelming enemy encounters, diabolical hazards, and unrelenting challenge.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/335300/header.jpg?t=1721683416', 1, 0, NULL);
INSERT INTO games VALUES (74457, 335670, 'LISA: The Painful', 'The miserable journey of a broken man...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/335670/header.jpg?t=1748451503', 1, 0, NULL);
INSERT INTO games VALUES (74461, 335790, 'Words for Evil', 'Words for Evil is a fast paced word game combined with a fantasy RPG. It features everything you expect from an RPG, including combat, hero progression, loot and more, all built on top of word game mechanics.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/335790/header.jpg?t=1693754584', 0, 0, NULL);
INSERT INTO games VALUES (74463, 335830, 'Distant Star: Revenant Fleet', 'BAFTA award winning fleet-based RTS meets rogue-lite. In Distant Star: Revenant Fleet, build your fleet of up to 5 ships from a choice of 8 classes and traverse a randomly generated galaxy to defeat the Erebus Platform. NOW AVAILABLE ON MAC AND LINUX', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/335830/header.jpg?t=1555064119', 0, 0, NULL);
