INSERT INTO games VALUES (74440, 336060, 'Raptor: Call of The Shadows - 2015 Edition', 'The great action-crazed, guns blazing, shoot ‘em up game comes back straight out of the ‘90s. Raptor: Call of the Shadows and its futuristic world are ready to challenge your flying skills.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/336060/header.jpg?t=1720813494', 0, 0, NULL);
INSERT INTO games VALUES (74441, 336080, 'Vietnam ‘65', 'It is 1965 and the US ground war in Vietnam is in full swing. As a US Army commander, wage a counter-insurgency (COIN) war to secure the Ia Drang valley, on the border with Cambodia.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/336080/header.jpg?t=1670926105', 0, 0, NULL);
