INSERT INTO games VALUES (74445, 336150, 'Virtual Pool 4', 'Play 8-Ball, 9-Ball, Snooker, Billiards, Pub Pool, 27 games total! “So realistic it will make your real life pool game better!”Two career play modes, trick shots, video tutorials, multi-player online. Virtual Pool 4 is the most comprehensive cue sport game ever!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/336150/header.jpg?t=1447365626', 0, 0, NULL);
INSERT INTO games VALUES (74451, 336240, 'Typoman', 'Slip into the role of an unusual HERO and find the last letter to restore hope in a merciless world.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/336240/header.jpg?t=1729544694', 0, 0, NULL);
