INSERT INTO games VALUES (74421, 336420, 'Bloodsports.TV', 'Co-Op Hero Defense set in a deadly post-apocalyptic Sweden. Team up with your friends and protect the Missile Silo against horrific beasts and outlaws.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/336420/header.jpg?t=1729083945', 0, 0, NULL);
INSERT INTO games VALUES (74424, 336610, 'Outcast 1.1', 'Outcast 1.1 is an enhanced version of the critically acclaimed action-adventure game developed in 1999 by Appeal for the PC.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/336610/header.jpg?t=1731427181', 0, 0, NULL);
INSERT INTO games VALUES (74411, 336940, 'Basingstoke', 'Basingstoke is a tense rogue-like that mixes stealth and arcade action. Explore the smouldering ruins of Basingstoke, a world of reanimated undead and ferocious alien monsters. Scavenge as you go, crafting equipment to help you in your mission: escape Basingstoke!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/336940/header.jpg?t=1593159572', 0, 0, NULL);
INSERT INTO games VALUES (74412, 337000, 'Deus Ex: Mankind Divided', 'You play as Adam Jensen, an experienced covert operative operating in a world that despises his kind: augmented humans. Choose from an arsenal of state-of-the-art weapons and augmentations to build your playstyle, and decide who you''ll trust, to unravel a vast worldwide conspiracy.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/337000/header.jpg?t=1748540912', 0, 0, NULL);
INSERT INTO games VALUES (74413, 337040, 'Deadnaut', 'Deadnaut is Screwfly Studios'' second game and follow up to cult hit, Zafehouse: Diaries. Deadnauts, so named because they’re unlikely to return, must explore, investigate and fight their way through the derelict ships of dead civilisations. Every mission is unique and no two locations are the same.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/337040/header.jpg?t=1707437853', 0, 0, NULL);
INSERT INTO games VALUES (74414, 337070, 'Dimmdrive :: Gaming Ramdrive @ 10,000+ MB/s', 'Play Steam Games @ 10,000+ MB/s :: Load games instantly with the Dimmdrive software. Dimmdrive fully integrates with all Steam games.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/337070/header.jpg?t=1523338486', 1, 0, NULL);
