INSERT INTO games VALUES (74391, 337320, 'Paint the Town Red', 'Paint the Town Red is a chaotic first person melee combat game set in different locations and time periods. The voxel-based enemies can be punched, bashed, kicked, stabbed and sliced completely dynamically using almost anything that isn''t nailed down.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/337320/header.jpg?t=1747124279', 1, 0, NULL);
INSERT INTO games VALUES (74392, 337340, 'Finding Paradise', 'A story-driven experience about two doctors traversing backwards through a dying man''s memories to fulfill his last wish.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/337340/header.jpg?t=1728926654', 1, 0, NULL);
INSERT INTO games VALUES (74393, 337350, 'Flywrench', 'Flywrench is a frenetic action game from the makers of Nidhogg about piloting an aerobatic ship through the depths of space.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/337350/header.jpg?t=1715637551', 0, 0, NULL);
INSERT INTO games VALUES (74394, 337360, 'Dead Island Retro Revenge', 'Time for some 16-bit retro revenge! When his beloved cat gets kidnapped, Max sets out across a zombie-infested California to get him back by force!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/337360/header.jpg?t=1707734177', 1, 0, NULL);
INSERT INTO games VALUES (74398, 337490, 'Four Sided Fantasy', 'A game about the limits of your screen. Four Sided Fantasy is a seamless experience where you wrap the screen to solve mind-bending puzzles. Play as a man and woman who attempt to find each other throughout four seasons in a year, constantly separated by the boundaries of the screen.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/337490/header.jpg?t=1626375840', 0, 0, NULL);
INSERT INTO games VALUES (74402, 337680, 'Star Hammer: The Vanguard Prophecy', 'Take command of Naval Strike Group 7 and lead your fleet to victory in full 3D tactical space combat. Star Hammer: The Vanguard Prophecy is a sci-fi strategy saga that will test your skills as both capital assault ship Captain and naval fleet Commander.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/337680/header.jpg?t=1726823616', 0, 0, NULL);
INSERT INTO games VALUES (74404, 337720, 'The Sea Will Claim Everything', 'An adventure in the Lands of Dream.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/337720/header.jpg?t=1459092295', 0, 0, NULL);
INSERT INTO games VALUES (74408, 337850, 'Avernum 2: Crystal Souls', 'Huge indie fantasy role-playing adventure in a massive, underground land. Packed with over 100 towns and dungeons and an epic story. Fight to complete up to three distinct game-winning quests. Master over 60 spells and abilities. Hunt for hundreds of magical artifacts. Over 50 hours of gameplay.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/337850/header.jpg?t=1724976631', 0, 0, NULL);
INSERT INTO games VALUES (74372, 337930, 'Nameless ~The one thing you must recall~', 'Nameless ~The one thing you must recall~ is a visual novel game designed for female audiences. It was distributed by the publisher, Cheritz, in English, Korean, and Japanese on Nov. 11th, 2013 and now it is available on Steam.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/337930/header.jpg?t=1572854507', 1, 0, NULL);
INSERT INTO games VALUES (74379, 338060, 'Mahjong Pretty Girls Battle', 'Japanese “Pretty Girls” gathered for a hot Mahjong battle!23 different sexy girls to choose from!Voices of all girls are included, squealing in ecstasy when they win!Based on authentic Japanese Mahjong rules.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/338060/header.jpg?t=1726634749', 0, 0, NULL);
INSERT INTO games VALUES (74387, 338140, 'Venetica - Gold Edition', 'In a fantastical Venice, The Corpus are deceived by a cunning necromancer. Transformed into an undead fiend, the conniving imposter is hell-bent on destroying the reinstated Death and the council of Corpus. Only Scarlett, the daughter of Death, can stand in his way.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/338140/header.jpg?t=1662621634', 0, 0, NULL);
