INSERT INTO games VALUES (74389, 338190, 'Just Get Through', 'Just Get Through is a randomly generated platformer with roguelike elements. Featuring a destructible environment, sandbox mode, user-created levels, various gamemodes, hardcore mode, color palettes, deadly traps, explosions and more.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/338190/header.jpg?t=1567625310', 0, 0, NULL);
INSERT INTO games VALUES (74362, 338320, 'Pixel Heroes: Byte & Magic', 'Enter the world of PIXEL HEROES and prepare yourself for a thrilling RPG/Roguelike experience like you have never seen before!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/338320/header.jpg?t=1717760548', 0, 0, NULL);
INSERT INTO games VALUES (74365, 338390, 'The Technomancer', 'The Technomancer is a sci-fi RPG that offers players plenty of dynamic combat action based on 4 skill trees dedicated to 3 combat styles and the destructive electrical powers of the Technomancers.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/338390/header.jpg?t=1712312994', 0, 0, NULL);
INSERT INTO games VALUES (74353, 338800, 'Seven Kingdoms 2 HD', 'Get ready for an exciting real-time strategy game experience like no other with Seven Kingdoms 2! Say goodbye to the monotony of resource gathering and army building, its unique gameplay offers a thrilling blend of city management, trade, industry, espionage, diplomacy, and conquest!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/338800/header.jpg?t=1683130376', 0, 0, NULL);
INSERT INTO games VALUES (131070, 339040, 'Disney''s Chicken Little', 'Based on Walt Disney’s feature 3D animation film Chicken Little, Chicken Little the action-packed video game catapults you into the hair-raising adventures of the movie and beyond.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/339040/header.jpg?t=1741733002', 0, 0, NULL);
INSERT INTO games VALUES (74338, 339130, 'Morningstar: Descent to Deadrock', 'Crash-landed on a desolate, alien planet, what should''ve been a routine work-for-hire job for Powell has become a deadly mission to save the merchant vessel Morningstar and her crew.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/339130/header.jpg?t=1478025584', 0, 0, NULL);
INSERT INTO games VALUES (74340, 339190, 'Dead Synchronicity: Tomorrow Comes Today', 'A dying reality, a universe that’s fading away. A merciless world thatgets sick and vanishes. No past, no present, no future; only the impending moment of “dead synchronicity” ahead. Will you be able to stop it?Because, otherwise... what will you do when Time dissolves itself?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/339190/header.jpg?t=1716976884', 0, 0, NULL);
INSERT INTO games VALUES (74341, 339200, 'Oceanhorn: Monster of Uncharted Seas', 'Oceanhorn: Monster of Uncharted Seas combines captivating storytelling, breathtaking 3D visuals and exciting gameplay into one epic action-adventure experience. In the game you explore the islands of Uncharted Seas, a world filled with many dangers, puzzles and secrets.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/339200/header.jpg?t=1667398786', 1, 0, NULL);
INSERT INTO games VALUES (74342, 339210, 'RESCUE 2: Everyday Heroes', 'HOW MANY LIVES WILL YOU SAVE?Experience your city through the eyes of a lifesaver and find out what it means to be a genuine &quot;Everyday Hero&quot;! Keep track of several fire stations, a variety of vehicles, a wide range of equipment and specialized staff so that you''re always prepared for anything.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/339210/header.jpg?t=1654107362', 0, 0, NULL);
INSERT INTO games VALUES (74343, 339230, 'ZOMBI', 'London is falling. Are you prepared? The Last Blight is upon us. It was foretold. For the second time in history, a great plague has shrouded London in a fog of death. Big Ben tolls as thousands of unprepared die, or worse, are infected by a sickness more gruesome than death.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/339230/header.jpg?t=1680018023', 0, 0, NULL);
INSERT INTO games VALUES (74348, 339350, 'Choice of Robots', 'Your robots will change the world! Will you show them the true meaning of love, or conquer Alaska with your robot army? A 300,000-word epic interactive sci-fi novel.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/339350/header.jpg?t=1734025689', 0, 0, NULL);
INSERT INTO games VALUES (74318, 339400, 'Runestone Keeper', 'Runestone Keeper is a roguelike dungeon crawler that blends classic RPG elements and turn based strategy. Heroes, monsters, equipment, events, magic and skills, traps and devices, shrines and altars, Goddesses and merchants. Choose your weapon and begin an epic adventure!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/339400/header.jpg?t=1583574534', 0, 0, NULL);
INSERT INTO games VALUES (74319, 339440, 'Critical Annihilation', 'Critical Annihilation is a Twin-Stick SHMUP (Shoot-em Up) made entirely out of tiny voxels. We take advantage of voxel technology to hype up the explosive gameplay. Everything is destructible to its core.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/339440/header.jpg?t=1666010788', 0, 1, NULL);
INSERT INTO games VALUES (74323, 339510, 'Psy High', 'Interactive teen supernatural mystery! You and your friends have developed magical psychic powers. Solve the case, save your school, find a date for prom!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/339510/header.jpg?t=1734115125', 0, 0, NULL);
INSERT INTO games VALUES (74325, 339570, 'Enemy', 'The video games you played as a kid, mashed together and remade into a tactical role-playing game.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/339570/header.jpg?t=1447366373', 0, 0, NULL);
INSERT INTO games VALUES (74326, 339580, 'Ember', 'Ember is a homage to classic role-playing games (RPG) that features a deep branching story, endless exploration across dynamic and living environments, a robust skill system, and an intricate crafting system.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/339580/header.jpg?t=1591259546', 0, 0, NULL);
INSERT INTO games VALUES (74306, 339790, 'rFactor', 'rFactor is a realistic easily extendable racing simulation from Image Space Incorporated. It offers the latest in vehicle and race customization, great graphics, outstanding multiplayer, and the height of racing realism.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/339790/header.jpg?t=1478097701', 0, 0, NULL);
INSERT INTO games VALUES (74307, 339800, 'HuniePop', 'HuniePop is a unique sim experience for PC, Mac and Linux. It''s a gameplay first approach that''s part dating sim, part puzzle game, with light RPG elements, a visual novel style of presentation, an abrasive western writing style and plenty of &quot;plot&quot;.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/339800/header.jpg?t=1736461926', 0, 0, NULL);
INSERT INTO games VALUES (74312, 339910, 'Uncraft World', 'Save the galaxy and its hot goddesses from eternal cubification ! Now with 50+ levels, Online play, 27 hero skins, Level Editor and Workshop integration !', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/339910/header.jpg?t=1562168496', 0, 0, NULL);
INSERT INTO games VALUES (74313, 340000, 'Headlander', 'Launch into the ultimate head trip as you blast through psychotic robots in a retro 70''s sci-fi action adventure from Double Fine Productions. It is a world of automation, a utopia gone wrong in which all of humanity have transferred their minds into robotic imposter bodies and are ruled by a computer.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/340000/header.jpg?t=1727390283', 0, 0, NULL);
INSERT INTO games VALUES (74316, 340050, 'Survivalist', 'It''s one year after the collapse of civilization and self-centered hedge fund manager Joe Wheeler emerges from his specially constructed bunker in search of food. This is a huge open-world RPG where you have the freedom to play how you want - but your choices have consequences.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/340050/header.jpg?t=1729189143', 0, 0, NULL);
INSERT INTO games VALUES (74317, 340070, 'Battle Ranch: Pigs vs Plants', 'Fight off hordes of enemy pigs in this 200 level strategy, tower defense, and time management game.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/340070/header.jpg?t=1574484045', 0, 0, NULL);
INSERT INTO games VALUES (74274, 340150, 'Basement', 'Basement is a strategy game, where you start doing illegal business to fund the development of your dream video game. It won''t be easy, so get ready to deal with other gangs, cops, crazy junkies, mysterious investor and even ghosts from the past.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/340150/header.jpg?t=1584560370', 0, 0, NULL);
INSERT INTO games VALUES (74275, 340170, 'FINAL FANTASY TYPE-0™ HD', 'FINAL FANTASY TYPE-0 HD brings an immersive world, memorable characters and the production value known of the series, together with high quality gameplay and storytelling truly worthy of the FINAL FANTASY name.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/340170/header.jpg?t=1615560326', 1, 0, NULL);
INSERT INTO games VALUES (74281, 340270, 'TIMEframe', 'Time is relative. Sometimes 10 seconds can feel like an eternity... In TIMEframe you will discover a world in slow motion. Explore the remnants of a mysterious civilization on the brink of destruction.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/340270/header.jpg?t=1601828148', 0, 0, NULL);
INSERT INTO games VALUES (74282, 340280, 'Cubot', 'At first sight, Cubot is a puzzle-game with a minimalist gameplay, just move color cubes towards tiles of the same color. It''s really easy, but it will be a torture for your mind to complete all levels of the game because the apparent simplicity of the game is in contradiction with the complexity of the level-design.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/340280/header.jpg?t=1447366545', 0, 0, NULL);
INSERT INTO games VALUES (74284, 340320, 'Sinless + OST', '&quot;Before we knew it, what we once knew as ''freedom'' became nothing more but a faint and distant memory.&quot; Venture forth and discover the truth behind the seemingly perfect OmniCare society in Sinless: a unique point and click and visual novel hybrid, set in an original cyberpunk reality.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/340320/header.jpg?t=1691582607', 0, 0, NULL);
INSERT INTO games VALUES (74286, 340340, 'Domestic Dog', 'Have you ever wanted to be a dog? Well now you can, kinda...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/340340/header.jpg?t=1736063295', 0, 0, NULL);
INSERT INTO games VALUES (74288, 340360, 'Tomb of Tyrants', 'Claim and defend the Tomb of Tyrants against greedy adventurers by matching tiles to build a deadly dungeon full of traps, minions, and more!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/340360/header.jpg?t=1650557532', 0, 0, NULL);
INSERT INTO games VALUES (74297, 340490, 'Subterrain', 'Uncompromising Sci-Fi survival on Mars! Manage the entire colony single-handed! Craft, Research, Explore and Fight against evolving mutants. Vast open world and randomly generated levels to explore! Can you survive long enough to escape the horror?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/340490/header.jpg?t=1679102493', 0, 0, NULL);
INSERT INTO games VALUES (74299, 340520, 'Tallowmere', 'Raise your shield. Indulge Lady Tallowmere and her lovingly violent dungeons. New rooms are created every time you play. How deep can you delve?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/340520/header.jpg?t=1745460979', 1, 0, NULL);
INSERT INTO games VALUES (74303, 340580, 'Armed with Wings: Rearmed', 'You are the sword; cut down your foes with steel and thunder. You are the wings; explore the skies and uncover unreachable mysteries. Embark on a journey through a vicious world ruled by darkness and imperial tyranny - the lands of Blackmist.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/340580/header.jpg?t=1568813137', 0, 0, NULL);
INSERT INTO games VALUES (74252, 340730, 'Sunrider Academy', 'You are Kayto Shields, an ordinary man thrown into an extraordinary adventure. Control Kayto''s day to day life as well as his responsibilities as club manager in this stat management sim.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/340730/header.jpg?t=1677887345', 0, 0, NULL);
INSERT INTO games VALUES (74258, 340830, 'Razenroth', 'Razenroth is an action shooter with a dark atmosphere, enriched with the elements of roguelike and RPG. All the levels, weather conditions, distribution and quantity of key elements are generated randomly. Thanks to this fact, a single game is different each time.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/340830/header.jpg?t=1667146430', 0, 0, NULL);
INSERT INTO games VALUES (74265, 341000, 'Mad Games Tycoon', 'Form your own game studio set in the early 1980s in a small garage. Develop your own game ideas, create a team and develop megahit video games. Research new technologies, train your staff and upgrade your office space, going from a lowly garage to a huge building. Expand your business and dominate the world market for video games!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/341000/header.jpg?t=1740737867', 1, 0, NULL);
INSERT INTO games VALUES (74266, 341020, 'Chronicles of Teddy', 'Chronicles of Teddy : Harmony of Exidus is a 2D Adventure / Action game with a Pixel Art Retro finish. Help Tarant in a quest, in which you will have to fight, use your sense of direction and hearing to accomplish your mission.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/341020/header.jpg?t=1748868322', 1, 0, NULL);
INSERT INTO games VALUES (74267, 341030, 'Colonial Conquest', 'Colonial Conquest is a conquest simulation set in the Victorian age of warfare and expansion of the late 1800''s and early 1900''s.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/341030/header.jpg?t=1748868328', 0, 0, NULL);
INSERT INTO games VALUES (74229, 341150, 'Age of Fear 2: The Chaos Lord GOLD', 'Play as either Bel''Kara, a seductive Succubus at odds with the Underworld, or Katzok, a brutal Orc Chieftan fighting for his clan''s dominance. The Age of Fear series is a deep and complex turn-based strategy (full of humour!) that fuses a tabletop wargame with RPG elements.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/341150/header.jpg?t=1730542582', 0, 0, NULL);
INSERT INTO games VALUES (74236, 341310, 'Greyfox RPG', 'You play as a new arrival to a foggy and mysterious town. You find yourself waking up in the bodies of the town''s inhabitants at pivotal moments of their lives. Make tough choices as you discover the truth about this town called Greyfox.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/341310/header.jpg?t=1574484237', 0, 0, NULL);
INSERT INTO games VALUES (74239, 341390, 'Vulture for NetHack', 'Vulture for NetHack is an isometric graphical interface for the roguelike engine: NetHack.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/341390/header.jpg?t=1629410276', 0, 0, NULL);
INSERT INTO games VALUES (74243, 341500, 'Camera Obscura', 'An ancient tower in a forgotten land. A lone photographer on a desperate search. Facing dangerous animals, crumbling architecture, and perilous pitfalls, can you reach the summit of the Tower, and perhaps, redemption?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/341500/header.jpg?t=1745463422', 0, 0, NULL);
INSERT INTO games VALUES (74247, 341550, 'Super Cyborg', 'Super Cyborg is an old school non-stop hardcore run''n''gun action game! You are an elite battle cyborg who is sent in to investigate a series of anomalies on a mysterious island. The merciless alien known as the ''Xirxul life form'' has been awakened by unwitting scientists and now: all humanity is in danger!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/341550/header.jpg?t=1572862070', 0, 0, NULL);
INSERT INTO games VALUES (74221, 341800, 'Keep Talking and Nobody Explodes', 'Find yourself trapped alone in a room with a ticking time bomb. Your friends have the manual to defuse it, but they can''t see the bomb, so you''re going to have to talk it out – fast!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/341800/header.jpg?t=1699020889', 1, 0, NULL);
INSERT INTO games VALUES (74223, 341870, 'TEMBO THE BADASS ELEPHANT', 'Shell City is plunged into a state of emergency after coming under attack from the devastating forces of PHANTOM. As the National Army struggle to contain the terrifying war machines, they call upon the only thing that stands between Shell City’s obliteration and its salvation; the peanut chompin’, villain stompin’, TEMBO THE BADASS...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/341870/header.jpg?t=1608208561', 0, 0, NULL);
INSERT INTO games VALUES (74191, 341940, 'Hatred', 'Hatred is a violent twin-stick shooter, in which you take the role of The Antagonist fighting against all of humanity.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/341940/header.jpg?t=1727965684', 0, 0, NULL);
INSERT INTO games VALUES (74192, 341950, 'Lux Delux', 'Lux Delux is a fast-paced turn-based-strategy game of risk and world domination, with so much more! Highly moddable, Lux has over 900 maps, diverse random map generators, a biohazard mode, an AI SDK, and an online multi-player league.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/341950/header.jpg?t=1496362802', 1, 0, NULL);
INSERT INTO games VALUES (74199, 342180, 'Arizona Sunshine®', 'Built exclusively for VR, Arizona Sunshine® puts you and up to 3 fellow survivors in the midst of a zombie apocalypse. Survive solo or in co-op, handle weapons with real-life movements, and explore a post-apocalyptic world in VR. Putting the undead back to rest is more thrilling than ever before.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/342180/header.jpg?t=1742289083', 1, 0, NULL);
INSERT INTO games VALUES (74200, 342190, 'Skyworld', 'Claim command over the VR battlefield! Skyworld puts you at the helm of a kingdom at war in VR. Put the power of your own full army – even dragons – at your fingertips, conquer all Skyworlds in a royal campaign, and wage war against friends online. This is wargaming as it was meant to be played.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/342190/header.jpg?t=1742289196', 1, 0, NULL);
INSERT INTO games VALUES (127763, 342200, 'MechWarrior Online™ Legends', 'MechWarrior Online™ Legends is a tactical, ''Mech-based online shooter set in the vast BattleTech Universe. Assume the role of an elite MechWarrior, piloting powerful BattleMechs, fighting for supremacy over the Inner Sphere.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/342200/header.jpg?t=1747763217', 0, 1, NULL);
INSERT INTO games VALUES (74204, 342260, 'Nevermind', 'Nevermind ushers you into dark and surreal worlds within the minds of trauma patients. When played with supported biofeedback technology, Nevermind picks up on indications of fear—lashing out if you allow your feelings of anxiety to get the better of you.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/342260/header.jpg?t=1653872858', 1, 0, NULL);
INSERT INTO games VALUES (74205, 342300, 'Zombie Kill of the Week - Reborn', 'Zombie Kill of the Week - Reborn is a challenging, fast paced, 2D survival shooter! Featuring a compelling single player survival mode and cooperative multiplayer for up-to four players, this is one zombie firefight you''re not going to want to miss!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/342300/header.jpg?t=1572354200', 0, 0, NULL);
INSERT INTO games VALUES (74206, 342310, 'RIOT: Civil Unrest', 'As civil crisis deepens and inequality tears the very fabric of society the discontentment of the masses manifests itself in violent public disturbances and civil disorder. Play as the police or the angry horde as RIOT – Civil Unrest places you in some of the world’s most fractious disputes.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/342310/header.jpg?t=1738068720', 0, 0, NULL);
INSERT INTO games VALUES (74207, 342350, 'Into The Gloom', 'It''s a retro horror game featuring eerie black, white, and red visuals. Embark on an exciting adventure across 18 suspenseful levels while evading &quot;The Shadow&quot; and discovering five possible endings. Immerse yourself in a chilling atmosphere with haunting environments and unsettling sounds.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/342350/77fb6b0fcc5dcf2a1151bb7c75fd79c01a8f8f62/header.jpg?t=1741255111', 0, 0, NULL);
INSERT INTO games VALUES (74209, 342380, 'Sakura Angels', '日本語バージョンダウンロード開始されました。Two girls, blessed with magical powers, are faced with the task of saving the lonely protagonist from the clutches of a mysterious witch and ancient evil, sealed away long ago by his ancestors. What does this sorceress want from our protagonist?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/342380/header.jpg?t=1667480222', 0, 0, NULL);
INSERT INTO games VALUES (74210, 342450, 'Sword Daughter', 'Choose a path to adventure! Will you sneak into the dragon''s lair, or challenge the beast openly? Will you fight for vengeance or for glory? Will you be tempted by elven romance? Will you be buried underground forever? Relive classic 1980s fantasy in this remastered gamebook.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/342450/header.jpg?t=1666992050', 0, 0, NULL);
INSERT INTO games VALUES (74176, 342490, 'Shipwreck', 'Shipwreck is a top down adventure game in which you must travel the land, explore dungeons, and defeat monsters to earn safe passage off the island on which you are stranded.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/342490/header.jpg?t=1712428310', 0, 1, NULL);
INSERT INTO games VALUES (128316, 342560, 'Airships: Conquer the Skies', 'Construct mighty steampunk airships and fly them into battle, waging war and conquering the skies!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/342560/header.jpg?t=1748006276', 1, 0, NULL);
INSERT INTO games VALUES (74184, 342580, '12 Labours of Hercules', 'Accompany Hercules on a quest to rescue his wife, kidnapped by the evil Hades in 12 Labours of Hercules! You''ll meet heroes from Ancient Greece as you vanquish beasts, repair roads and construct wonders in this stunning Time Management game!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/342580/header.jpg?t=1730105652', 1, 0, NULL);
INSERT INTO games VALUES (74187, 342640, 'Pixel Privateers', 'Pixel Privateers is a Squad Based Tactical RPG “Loot ‘Em Up” that will send your team of mercenaries through a mysterious wormhole on a quest to gather technology for your employer. An entire galaxy awaits - full of worlds to explore, factions to encounter, and epic gear to collect!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/342640/header.jpg?t=1498149668', 0, 0, NULL);
INSERT INTO games VALUES (74148, 343070, 'World of Subways 4 – New York Line 7', 'The series &quot;World of Subways&quot; features some of the most interesting Subway Routes of the world for the PC. Once again World of Subways 4 comes back to New York, perhaps the most exciting city in the world. The whole gaming world takes place in the 70ies/80ies and is created in its typical look.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/343070/header.jpg?t=1704810527', 0, 0, NULL);
INSERT INTO games VALUES (74149, 343090, 'SimpleRockets', 'I am excited to release my first game on Steam! SimpleRockets was released in 2013 for mobile and I''ve put a ton of work into it to get it ready for PC and Mac. It was inspired by KSP, and it offers a simpler 2D experience for building rockets and exploring space with realistic orbital mechanics.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/343090/header.jpg?t=1709675043', 0, 0, NULL);
INSERT INTO games VALUES (74150, 343100, 'Overture', 'Overture is an action-adventure roguelike which draws heavy inspiration from hits such as Diablo, Realm of The Mad God, Zelda, and The Binding of Isaac. Explore vast randomly generated dungeons and slay hordes of cunning enemies!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/343100/header.jpg?t=1614781615', 0, 0, NULL);
INSERT INTO games VALUES (74157, 343270, 'Disillusions Manga Horror', 'Spoopy !- DiS and Vigil are two friends who visit the haunted residence the newspapers have been covering recently. Unbeknownst to them, however, the place is not as abandoned as the press makes out... - Be drawn into exploring the mysterious past of the psychotic murderer who once called the place home?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/343270/header.jpg?t=1499584049', 0, 0, NULL);
INSERT INTO games VALUES (74161, 343360, 'Particula', 'Destroy negativity, clear your mind! Particula brings you a new perspective in gaming, helping you to concentrate and relax. A three players co-op tower defense experience with a relaxing soundtrack, smooth visuals and gameplay.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/343360/header.jpg?t=1652177957', 0, 0, NULL);
INSERT INTO games VALUES (74166, 343440, 'Crash Drive 2', 'Get ready for ridiculous fun in this multiplayer free-roaming stunting game. Drive a bus, tank or monster truck and speed across huge open worlds. Level up your car, participate in random events and discover secret areas. Buy now and get a free copy to gift to your friend!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/343440/header.jpg?t=1599138737', 0, 0, NULL);
INSERT INTO games VALUES (74142, 343560, 'Bob Was Hungry', 'Bob Was Hungry is a challenging precision platformer with many levels designed to truly test your platforming skills. Play alone or online with 2-8 player co-op and make your way through countless perils to feed your bob!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/343560/header.jpg?t=1447367416', 0, 0, NULL);
INSERT INTO games VALUES (74146, 343710, 'Kholat', 'The most terrifying journey of your life set in the beautiful winter scenery of the Ural Mountains. Uncover the horrific mystery behind the Dyatlov Pass Incident. Narrated by the famous Sean Bean.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/343710/header.jpg?t=1589292099', 1, 0, NULL);
INSERT INTO games VALUES (74133, 343780, 'Cat Goes Fishing', 'Start out on an island with a basic rod. Progress into a radar-wielding master fisher-cat scouring the sea for the biggest and baddest fish. Each fish has unique behaviors that you will learn to exploit as you tailor your arsenal of fishing rods to suit your style of play. Mrrrow!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/343780/header.jpg?t=1722198432', 0, 0, NULL);
INSERT INTO games VALUES (74139, 343860, 'Tacoma', 'Tacoma is a sci-fi narrative adventure from the creators of Gone Home. Set aboard a high-tech space station in the year 2088, explore every detail of how the station’s crew lived and worked, finding the clues that add up to a gripping story of trust, fear, and resolve in the face of disaster.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/343860/header.jpg?t=1683128309', 1, 0, NULL);
INSERT INTO games VALUES (74129, 344340, 'Front Office Football Seven', 'Put yourself in the Front Office with Front Office Football, the professional football simulation from Solecismic Software. Manage your roster through trading, free agency and the amateur draft. Create game plans, organize depth charts and watch your franchise thrive for decades.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/344340/header.jpg?t=1572331872', 0, 0, NULL);
INSERT INTO games VALUES (74117, 344410, 'Magnetic: Cage Closed', 'Magnetic: Cage Closed is a first person puzzle game where the player manipulates magnetic forces to accomplish their goals. The mechanics are focused around a single tool: The Magnet Gun which allows you to create electromagnetic fields with either positive or negative charges.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/344410/header.jpg?t=1572427914', 0, 0, NULL);
INSERT INTO games VALUES (74118, 344440, 'Sacra Terra: Angelic Night', 'Use your cunning to defeat the demons of the Seven Deadly Sins and rescue humanity from destruction!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/344440/header.jpg?t=1705482532', 1, 0, NULL);
INSERT INTO games VALUES (74119, 344480, 'Quell', 'An enchanting game of logic and relaxation.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/344480/header.jpg?t=1490797389', 1, 0, NULL);
