INSERT INTO games VALUES (74116, 344770, 'fault - milestone two side:above', 'fault - milestone two side:above is a Cinematic Visual Novel that takes place right after the events of milestone one. Please note that this novel is a direct sequel to fault - milestone one and contains massive spoilers of the first story. Play through of the first title is highly advised.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/344770/header.jpg?t=1667230393', 1, 0, NULL);
