INSERT INTO games VALUES (73915, 349250, 'Copy Kitty', 'Boki can copy the special abilities of any foe and then combine up to 3 of them into a unique super-weapon! Blast through hordes of evil robots in cyberspace, while training to become a superhero!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/349250/header.jpg?t=1681233034', 0, 0, NULL);
INSERT INTO games VALUES (73917, 349270, 'Mosaic', 'Enter a world that’s utterly surreal and eerily familiar. Escape the mundanity of your existence in an experience that will stay with you. Mosaic is a narrative-driven modern adventure game with a story that lasts about 2-3 hours.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/349270/header.jpg?t=1692101206', 1, 0, NULL);
INSERT INTO games VALUES (73924, 349500, 'Cubicle Quest', 'Cubicle Quest is a game about how life can suck. Dead end jobs, repetitive obligations, irritating coworkers... Cubicle Quest takes all of those things and turns them into enemies you can fight in an old-school RPG.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/349500/header.jpg?t=1488235490', 0, 0, NULL);
INSERT INTO games VALUES (73907, 349790, 'Galaxy of Pen & Paper +1', 'Turn-based RPG about a group of players rolling dice in the year 1999! Create your own game master and RPG party, as they roleplay, explore distant planets in their imagination, fight weird aliens and save the galaxy in the era of dial-up internet and floppy disks! (Includes +1 Edition content)', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/349790/header.jpg?t=1726496056', 0, 0, NULL);
INSERT INTO games VALUES (73913, 350010, 'Time Mysteries: Inheritance - Remastered', 'Face the Time Traveller to save the future!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/350010/header.jpg?t=1582015785', 1, 0, NULL);
INSERT INTO games VALUES (73894, 350070, 'Environmental Station Alpha', 'Explore an abandoned space station in this retro-themed explorative action platformer.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/350070/header.jpg?t=1728679412', 0, 0, NULL);
INSERT INTO games VALUES (73895, 350080, 'Wolfenstein: The Old Blood', 'Wolfenstein®: The Old Blood™ is a standalone prequel to the critically acclaimed first-person action-adventure shooter, Wolfenstein®: The New Order. This adventure spans eight chapters and features the hallmarks of MachineGames – thrilling action, immersive story, and intense FPS combat.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/350080/header.jpg?t=1699548921', 0, 0, NULL);
INSERT INTO games VALUES (73897, 350110, 'TransOcean 2: Rivals', 'In TransOcean 2: Rivals you face a new challenge as the boss of your own shipping line in both single-player and - for the first time - multiplayer mode: The international competition has gotten a lot tougher and the battle for the most lucrative contracts has only just begun.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/350110/header.jpg?t=1726480354', 0, 0, NULL);
INSERT INTO games VALUES (73904, 350500, 'Fly in the House', 'There’s a fly in your apartment! Hunt it down and squish it! Damn, that fly is fast! If a fly swat won’t get it, use furniture. If that doesn’t work, use anything you can find… just squish it! The more you smash, the more points you earn.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/350500/header.jpg?t=1724994087', 0, 0, NULL);
INSERT INTO games VALUES (73883, 350640, 'Sherlock Holmes: The Devil''s Daughter', 'Experience a fantastic adventure with unique gameplay that blends investigation, action and exploration in a breath-taking thriller that will test the limits of your nerves and intelligence. Play as the great detective and track down evil in the darkest corners of London and the human soul…', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/350640/header.jpg?t=1667551536', 1, 0, NULL);
INSERT INTO games VALUES (73886, 350740, 'The Bug Butcher', 'A fast paced action shooter inspired by the arcade classic Super Pang! Use a wide selection of weapons and powerups to tear through increasingly challenging levels.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/350740/header.jpg?t=1574062445', 0, 0, NULL);
INSERT INTO games VALUES (73887, 350770, 'Giana Sisters 2D', 'Giana Sisters 2D is a HD remake of the beloved Nintendo DS game from 2009. It features full controller support, precise, intuitive controls and a smooth learning curve. All balanced for hours of fun and challenge.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/350770/header.jpg?t=1729170240', 0, 0, NULL);
INSERT INTO games VALUES (73888, 350780, 'MANOS: The Hands of Fate ~ Director''s Cut', 'Retro platforming action in this adaptation of a terrible movie.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/350780/header.jpg?t=1617144326', 0, 0, NULL);
INSERT INTO games VALUES (73892, 350910, 'Streets of Fury EX', 'Fight the gangs of Paris in this action packed Beat''Em up. Up to 4 players can join in, to cooperate, or fight against each other! Many unlockables, game modes, crazy combos and devastating furies await you in this deep fighting game.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/350910/header.jpg?t=1707746119', 0, 0, NULL);
INSERT INTO games VALUES (73853, 351030, 'Pixel Puzzles Ultimate Jigsaw Puzzles', 'The Number 1 Jigsaw Puzzle Game.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/351030/header.jpg?t=1745448489', 0, 1, NULL);
INSERT INTO games VALUES (73857, 351090, 'Regency Solitaire', 'Experience romantic Regency England in this sumptuous solitaire game. Play your cards right as you tour historic London, Brighton and Bath, and help Bella create a dazzling ballroom. Unlock gameplay features with your makeover project and improve Bella’s chances of finding true love!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/351090/header.jpg?t=1739805360', 0, 0, NULL);
INSERT INTO games VALUES (73858, 351100, 'Niffelheim', 'Your avatar is a brave warrior who has fallen in battle. But instead of well-deserved peace in Asgard, his soul is trapped in the harsh world of Niffelheim. Survive in this hostile world, ransack the neighbor lands, explore dangerous dungeons and find your way to Valhalla', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/351100/header.jpg?t=1745494549', 1, 0, NULL);
INSERT INTO games VALUES (73860, 351150, 'DRAGON: A Game About a Dragon', 'DRAGON: A Game About a Dragon is a colorful and lovingly hand-drawn Action RPG inspired by the 16-bit era. Finally, YOU get to play as the dragon! Breathe fire, fight knights, hoard gold, and find treasure! A refreshingly lighthearted game with an endearing story.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/351150/header.jpg?t=1492972182', 0, 0, NULL);
INSERT INTO games VALUES (73861, 351160, 'Poop Clicker', 'Have you always wanted to be a king, but all the kingdoms are already taken? Try to be the Poop King in the Poop Clicker game! A magical unicorn, sweet corn and others will help you with this! Unlock special upgrades, but take your time, because haste makes waste!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/351160/header.jpg?t=1743452963', 0, 0, NULL);
INSERT INTO games VALUES (73864, 351230, 'Counter Spell', '&quot;Counter Spell&quot; combines elements of classic role playing games with modern stealth-based shooters. Single player, multiplayer coop, and competitive multiplayer are all supported with different game modes for each. An open, streaming world makes for an exciting sandbox to adventure in!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/351230/header.jpg?t=1537808649', 0, 0, NULL);
INSERT INTO games VALUES (73866, 351290, 'SURVIVAL: Postapocalypse Now', 'Want to survive? - Arm yourself and survive. Crafting, shooting, transport and much more awaits you in the Survival game. What happened to the world around and why he died - you may find out. But is this the main question now?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/351290/header.jpg?t=1680276700', 0, 0, NULL);
INSERT INTO games VALUES (73870, 351340, 'Belladonna', 'Belladonna is a gothic adventure game, twisted and dark. Take the role of a corpse girl rising from the dead in an abandoned laboratory, and unravel the mysteries concerning your own death and reanimation.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/351340/header.jpg?t=1748869324', 0, 0, NULL);
INSERT INTO games VALUES (73876, 351480, 'Age of Fear: The Undead King', 'Play as either Sir Edward, a noble Knight defending the Human Kingdom, or Krill, a wicked Necromancer with an unearthly lust for power! The Age of Fear series is a deep and complex turn-based strategy (full of humour!) that fuses a tabletop wargame with RPG elements.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/351480/header.jpg?t=1730479824', 0, 0, NULL);
INSERT INTO games VALUES (73845, 351490, 'Intergalactic Bubbles', 'Blast your way through space in this innovative 3D bubble puzzler! Bounce, bobble, swing, and explode bubbles across the universe. Intergalactic Bubbles advances the classic match-3 genre into the 21st century with stellar graphics, 3D action, and upgrades.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/351490/header.jpg?t=1649966974', 1, 0, NULL);
INSERT INTO games VALUES (129607, 351510, 'Quiplash', 'For 3-8 Players and an Audience of thousands! Your phones or tablets are your controllers! The gut-busting, say-anything, no-rules party game!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/351510/header.jpg?t=1725046271', 0, 0, NULL);
INSERT INTO games VALUES (73849, 351700, 'UnReal World', 'The cult classic open-ended wilderness survival roguelike RPG taking place in the ancient North. Throughout the years, UnReal World has been praised for its incredible depth, realism, atmosphere and immersion. Lose yourself in the most intricate, detailed and enchanting iron-age game world.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/351700/header.jpg?t=1709133401', 0, 0, NULL);
INSERT INTO games VALUES (73829, 351860, 'Cultures - Northland', 'The Vikings are back! Get this RTS classic!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/351860/header.jpg?t=1736356920', 0, 0, NULL);
INSERT INTO games VALUES (73830, 351870, 'Cultures - 8th Wonder of the World', 'Solve the mystery surrounding the 8th Wonder of the World with your heroes and banish evil from the Earth! Play this RTS-Classic.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/351870/header.jpg?t=1736356966', 0, 0, NULL);
INSERT INTO games VALUES (73831, 351900, 'Pregnancy', '''Pregnancy'' is an interactive short story where the player attempts to influence the decisions of a 14 year old girl about the future of her pregnancy.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/351900/header.jpg?t=1539110393', 0, 0, NULL);
INSERT INTO games VALUES (73832, 351910, 'Valhalla Hills', 'Lead your people. Survive the wilderness. Fight for honor. Reclaim your eternal reward. A brand new strategy game from the developers of Cultures and The Settlers II.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/351910/header.jpg?t=1736357022', 1, 0, NULL);
INSERT INTO games VALUES (73833, 351920, 'Crazy Machines 3', 'Crazy Machines 3 is the latest, greatest, most amazing and craziest part of the series and fascinates once more with physic-based puzzles. Build your own crazy machines and share your awesomeness across the world thanks to the Steam® Workshop.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/351920/header.jpg?t=1716975816', 1, 0, NULL);
INSERT INTO games VALUES (73834, 351940, 'The Descendant', 'In THE DESCENDANT, the end of the world is only the start. With what remains of humanity protected in underground Ark facilities, your mission is to keep survivors alive, while discovering a far greater conspiracy buried within Ark-01.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/351940/header.jpg?t=1719406361', 0, 0, NULL);
INSERT INTO games VALUES (73835, 351970, 'Tales of Zestiria', 'In a world torn by war and political skirmishes, accept the burden of the Shepherd and fight human darkness to protect your world from Malevolence and reunite humans and Seraphim.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/351970/header.jpg?t=1718967588', 0, 0, NULL);
INSERT INTO games VALUES (73818, 352220, 'King of Dragon Pass', 'Create your own epic saga of survival, mythology and diplomacy! Rule your clan, make strategic decisions that affect the game world, win battles and expand your influence in this unique mix of RPG, strategy and story-telling.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/352220/header.jpg?t=1736860362', 0, 0, NULL);
INSERT INTO games VALUES (73819, 352240, 'The Westport Independent', 'The Westport Independent is a censorship simulator taking place in a post-war country, governed by the recently elected Loyalist Party. As the editor of one of the last independent newspapers in the country, your job is to remove and edit the content of your paper, affecting the people’s opinion of both the rebels and the Loyalist...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/352240/header.jpg?t=1612200730', 0, 1, NULL);
INSERT INTO games VALUES (73796, 352400, 'LEGO® Jurassic World', 'Following the epic storylines of Jurassic Park, The Lost World: Jurassic Park and Jurassic Park III, as well as the highly anticipated Jurassic World, LEGO Jurassic World™ is the first videogame where players will be able to relive and experience all four Jurassic films.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/352400/header.jpg?t=1745540350', 0, 0, NULL);
INSERT INTO games VALUES (73797, 352430, 'Farlight Explorers', 'Extract and gather resources from different planets. Manage the supply of electricity, water, food and oxygen of your base in order to survive. Automate the creation of new products. Build a spaceship to transport your products to other places...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/352430/header.jpg?t=1603182080', 0, 0, NULL);
INSERT INTO games VALUES (73800, 352520, 'The Silent Age', 'Experience a post-apocalyptic world like never before in The Silent Age, a thrilling point-and-click adventure game. Use time travel to unravel the mystery behind humanity''s disappearance and save the world from extinction. Start your journey now!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/352520/header.jpg?t=1725043677', 0, 0, NULL);
INSERT INTO games VALUES (73802, 352550, 'Urban Empire', 'Urban Empire is a ‘City Ruler’, pioneering a new breed of strategy game that combines city builder features with political scheming and adds profound social and historical events into the mix, creating a whole new gameplay experience.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/352550/header.jpg?t=1730815714', 0, 0, NULL);
INSERT INTO games VALUES (73804, 352610, 'The Way We All Go (2015)', 'A horror/romance visual novel with numerous choices and over 20 endings. Set in Japan in the 1980s, our protagonist, Atcchan, must navigate his relationship between his two estranged childhood friends, one of whom might be a yandere. Will he live to see the end of his summer vacation?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/352610/header.jpg?t=1735682038', 0, 0, NULL);
INSERT INTO games VALUES (73808, 352720, 'The Universim', 'Jump straight into managing your own planets as you guide a civilization through the ages. Build the ultimate empire in The Universim, a new breed of God Game in development by Crytivo.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/352720/header.jpg?t=1731528807', 1, 0, NULL);
INSERT INTO games VALUES (73812, 352780, 'An Octave Higher', 'Fall into the magically complicated world of Overture as the three main characters embark on an adventure that will shake their lives and the world around them. Will they fan the flames of the growing revolution, or will they be the key to extinguishing it?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/352780/header.jpg?t=1572720419', 0, 0, NULL);
INSERT INTO games VALUES (73790, 352890, 'Caravan', 'Are you ready to embark on a journey through deserts and dangers? Will you be able to safely navigate your fellowship through the lands of the Orient and uncover your destiny? Through strategic trading and traveling you will overcome obstacles and adversity.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/352890/header.jpg?t=1736357302', 1, 0, NULL);
INSERT INTO games VALUES (73792, 352950, 'Better Late Than DEAD', 'Awaking on an island with no memory, you have just one memento of the life you led before… A child''s photograph. Who is this? You must search the island for useful tools that will aid in your escape. As time passes and hopes of survival hang by a thread, you realise that this island is not as it seems.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/352950/header.jpg?t=1726150318', 0, 0, NULL);
INSERT INTO games VALUES (73795, 353090, 'Chicken Invaders 5', 'Chicken Invaders puts you at the forefront of a battle against invading intergalactic chickens, bent on revenge for our oppression of Earth chickens. This time, the chickens have hatched a devious plan to block out sunlight and freeze Earth to death!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/353090/header.jpg?t=1695975407', 0, 0, NULL);
INSERT INTO games VALUES (73784, 353330, 'Love at First Sight', 'After falling in love at first sight with the shy Sachi Usui, an injury-ridden, single-eyed high school girl, the protagonist tries to win over her lonely and isolated heart. A pure, heart-warming romance game where the apple of your eye only has one eye!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/353330/header.jpg?t=1580427973', 0, 0, NULL);
INSERT INTO games VALUES (73787, 353380, 'Steam Link', 'Extend your Steam gaming experience to your mobile device, TV, VR headset or PC - all you need is a local network or internet connection. In addition, the Steam Link app now supports Remote Play Together. Now you can join games hosted on a friend’s PC just by clicking a link.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/353380/header.jpg?t=1702342298', 1, 0, NULL);
INSERT INTO games VALUES (73788, 353540, 'Stephen''s Sausage Roll', 'A simple 3d puzzle game.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/353540/header.jpg?t=1589230122', 0, 0, NULL);
INSERT INTO games VALUES (73789, 353550, 'House of Caravan', 'Taking place in a single mansion in Candlewood, northeast USA, in the early 20th Century, House of Caravan is a sinister adventure filled with dark secrets and vexing puzzles.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/353550/header.jpg?t=1574484301', 0, 0, NULL);
INSERT INTO games VALUES (73766, 353560, 'Plug & Play', 'Run, hit, switch, fall, love, plug, pull. And push.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/353560/header.jpg?t=1749299388', 0, 0, NULL);
INSERT INTO games VALUES (73771, 353640, 'Train Valley', 'Build railways, manage traffic and stay accident-free. Play in Europe, America, Japan and USSR in 1830-2020. Complete the story mode from the Gold Rush of 1849 to the first manned spaceflight, and then explore the random mode. Management. Construction. Trains. Welcome to Train Valley!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/353640/header.jpg?t=1734688642', 0, 0, NULL);
INSERT INTO games VALUES (73772, 353700, 'The Deadly Tower of Monsters', 'Fire up your ray guns, crystal swords, and laser whips, and get ready for thrills and chills! With three incredible movie stars playing out decidedly B-level sci-fi exploits, Dick Starspeed, Scarlet Nova, and Robot will have you ready to jump off the side of the tower—right into adventure!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/353700/header.jpg?t=1603130568', 0, 0, NULL);
INSERT INTO games VALUES (73757, 354140, 'Five Nights at Freddy''s 3', 'Thirty years after Freddy Fazbear''s Pizza closed it''s doors, the events that took place there have become nothing more than a rumor and a childhood memory, but the owners of &quot;Fazbear''s Fright: The Horror Attraction&quot; are determined to revive the legend and make the experience as authentic as possible for patrons, going to great l', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/354140/header.jpg?t=1579635991', 0, 0, NULL);
INSERT INTO games VALUES (73758, 354160, 'WRC 5 FIA World Rally Championship', 'Find all the cars, all the drivers and all the official rallies of the 2015 FIA World Rally Championship in THE racing simulation standard. Realistic driving on different road surfaces, dynamic damage, day/night system, weather… Experience all the sensations of rally racing in WRC 5!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/354160/header.jpg?t=1748860144', 0, 0, NULL);
INSERT INTO games VALUES (73764, 354380, 'Assassin’s Creed® Chronicles: China', 'The first entry in the Assassin’s Creed Chronicles saga takes place in China, 1526, as the Ming dynasty starts to crumble. You embody Shao Jun, the last remaining Assassin of the Chinese Brotherhood, returning to her homeland with a vendetta.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/354380/header.jpg?t=1747656056', 1, 0, NULL);
INSERT INTO games VALUES (73765, 354400, 'Tadpole Treble', 'Embark on a thrilling adventure through sheet music in Tadpole Treble! Escape predatory piranhas, flirtatious tadpoles and more as you make your way back home. Shoot for the top of the leaderboards, or create your own stages and music in Composition Mode!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/354400/header.jpg?t=1473703105', 0, 0, NULL);
INSERT INTO games VALUES (132429, 354430, 'STAR WARS™ - X-Wing Special Edition', 'Against the overwhelming might of the Empire stands a small but growing Rebel Alliance. Scattered resistance groups are uniting and what is needed most now are Starfighter pilots. Will you join their struggle to end this tyranny and become a hero of the Rebellion?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/354430/header.jpg?t=1741819222', 0, 0, NULL);
INSERT INTO games VALUES (73753, 354680, 'Adventures of Bertram Fiddle 1: A Dreadly Business', 'A classic point and click adventure game, featuring weird and wonderful characters, beautiful animation and a fantastic soundtrack. &quot;It is quite possibly one of the finest point-and-click comedy murder mystery adventure games set in Victorian London you will play today&quot; - Bertram Fiddle', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/354680/header.jpg?t=1691512549', 0, 0, NULL);
INSERT INTO games VALUES (73726, 354740, 'Echoes of Aetheria', 'Two nations finally achieve peace, marked by a momentous royal wedding. But just as they seal it with a kiss, a group of soldiers sabotage the wedding and kidnap the bride! Follow the story of Lucian, Ingrid, and Soha, as they uncover the secrets of the conspiracy and expose the true villains!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/354740/header.jpg?t=1722350287', 0, 0, NULL);
INSERT INTO games VALUES (73738, 355050, 'Sky Force Anniversary', 'Legendary shoot-''em-up makes its way on the PCs! Abundant explosions, truly epic boss fights and beautifully crafted 3D environments are here to keep you entertained. Sky Force Anniversary offers single player experience and local cooperative mode for 2 players.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/355050/header.jpg?t=1667208034', 1, 0, NULL);
INSERT INTO games VALUES (73739, 355060, 'Sébastien Loeb Rally EVO', 'Sébastien Loeb Rally EVO brings off-road racing to a whole new level of simulation and engagement. It will enable you to drive the best rally cars from the past up to the present day in the most exciting off-road events across the globe.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/355060/header.jpg?t=1747661156', 0, 0, NULL);
INSERT INTO games VALUES (73744, 355130, 'MotoGP™15', 'Are you ready for the new challenges of MotoGP™15? Compete against MotoGP™, Moto2™, and Moto3™ riders on the 18 circuits of the 2015 championship in a bid to win the world champion title!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/355130/header.jpg?t=1728477936', 0, 0, NULL);
INSERT INTO games VALUES (73746, 355150, 'gravilon', 'An inventive, thought-provoking puzzle platformer. Use powerups in each environment, and your own inherent gravity-bending powers, to complete each level. The more you play, the more story details you''ll uncover.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/355150/header.jpg?t=1511231788', 0, 0, NULL);
INSERT INTO games VALUES (73747, 355170, 'Sam & Max Hit the Road', 'Grab your nightstick, squeal like a siren, and Hit the Road with Sam &amp; Max, Freelance Police, as they attempt to crack their toughest case.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/355170/header.jpg?t=1741810817', 0, 0, NULL);
INSERT INTO games VALUES (73748, 355180, 'Codename CURE', 'Codename CURE is a first person, co-operative zombie game with support for up to five players, providing dynamic, fast-paced zombie fragging with both objective, and survival-based missions.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/355180/header.jpg?t=1727353650', 1, 1, NULL);
INSERT INTO games VALUES (73706, 355240, 'NEO AQUARIUM - The King of Crustaceans -', 'YOU GET TO CONTROL UNIQUE CREATURES LIKE LOBSTERS, CRABS AND BARNACLES, IN A WILD WATER WORLD THAT EXCEEDS ALL HUMAN SENSE.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/355240/header.jpg?t=1728471116', 0, 0, NULL);
INSERT INTO games VALUES (73707, 355250, 'STAR WARS™: TIE Fighter Special Edition', 'The Imperial Navy is called upon to eradicate the last of the rebellion and restore law and order. As an Imperial navy starfighter pilot, you will safeguard imperiled lives thoughout the galaxy. Join the Emperor''s cause in eliminating the Rebel uprising as the Empire strikes back!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/355250/header.jpg?t=1741818379', 0, 0, NULL);
INSERT INTO games VALUES (73708, 355270, '199X', 'In 199X, you control Clara. That''s the problem.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/355270/header.jpg?t=1447370533', 0, 0, NULL);
INSERT INTO games VALUES (73714, 355400, 'Diesel Guns', '&quot;Diesel Guns&quot;- is an Arcade Multiplayer Online Car Combat (AMOCC) game set to deliver the same thrill you remember from classic AMOCCs like „Twisted Metal“ and „Vigilante 8“.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/355400/header.jpg?t=1642708759', 0, 0, NULL);
INSERT INTO games VALUES (73721, 355520, 'The Albino Hunter (Original)', 'Kalymn Nox is the Albino Hunter; even his pretentious and slightly racist title can keep him from waking up broke after a night of drinking.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/355520/header.jpg?t=1724991341', 0, 0, NULL);
INSERT INTO games VALUES (73722, 355530, 'Last Word', 'In a society where having the last word means having power over others, a small party is disrupted by a gentleman who politely issues orders via one-way intercom.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/355530/header.jpg?t=1726629749', 0, 0, NULL);
INSERT INTO games VALUES (73688, 355630, 'Leo’s Fortune - HD Edition', 'An award-winning platform adventure game where you hunt down the cunning thief who stole his gold. Beautifully hand-crafted levels bring the story of Leo to life, offering a journey full of challenges. Revisit this classic adventure as it celebrates its tenth anniversary.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/355630/header.jpg?t=1724790320', 1, 0, NULL);
INSERT INTO games VALUES (73691, 355680, 'Overland', 'Take care of a group of travelers on a post-apocalyptic road-trip across the United States in this turn-based survival game.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/355680/header.jpg?t=1667408697', 1, 0, NULL);
INSERT INTO games VALUES (73694, 355760, 'Drizzlepath', 'In Drizzlepath you are set on a journey to the top of the Mountain of Fire. It aims to be an atmospheric, relaxed and enigmatic experience. Downloadable soundtrack included.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/355760/header.jpg?t=1728893182', 0, 0, NULL);
INSERT INTO games VALUES (73695, 355790, 'Styx: Shards of Darkness', 'Styx returns in a new stealth adventure! Explore and master huge open environments, sneak past or assassinate new enemies and bosses, and experiment with the new array of lethal abilities and weapons in our goblin assassin''s arsenal.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/355790/header.jpg?t=1739798099', 1, 0, NULL);
INSERT INTO games VALUES (73696, 355800, 'Space Run Galaxy', 'Space Run Galaxy is the sequel to Space Run, the game from one-man studio Passtech, which seduced hundreds of thousands of players with its dynamic and original gameplay. By twisting the tower-defense game style, Space Run offered an addictive real-time spaceship construction strategy experience.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/355800/header.jpg?t=1728650267', 0, 0, NULL);
INSERT INTO games VALUES (73699, 355860, 'Albino Lullaby: Episode 1', 'Albino Lullaby is a horror adventure game that doesn''t rely on jump scares or gore. Escape from a surreal psychological nightmare as the world dynamically twists and contorts around you.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/355860/header.jpg?t=1478193061', 0, 0, NULL);
INSERT INTO games VALUES (73702, 355970, 'Home is Where One Starts...', 'Home is Where One Starts... is a short, first-person exploration game in the same vein as Dear Esther or Gone Home. It’s a story about childhood, hope, and the miracle of memory. You play as a little girl from a broken home somewhere in the American South.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/355970/header.jpg?t=1666986251', 0, 0, NULL);
INSERT INTO games VALUES (73703, 355980, 'Dungeon Warfare', 'Dungeon Warfare is a challenging tower defense strategy game where you become a dungeon lord to defend your dungeons with deadliest of traps and insidious contraptions against greedy adventurers and wanna-be heroes.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/355980/header.jpg?t=1725504075', 1, 0, NULL);
INSERT INTO games VALUES (73662, 356040, 'Sheltered', 'Sheltered is a deep and emotional survival management game. You take on the role of protecting four family members who, after a global apocalypse, have found their way to a deserted shelter.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/356040/header.jpg?t=1729175647', 0, 0, NULL);
INSERT INTO games VALUES (73671, 356190, 'Middle-earth™: Shadow of War™', 'Experience an epic open-world brought to life by the award-winning Nemesis System. Forge a new Ring of Power, conquer Fortresses in massive battles and dominate Mordor with your personal orc army in Middle-earth™: Shadow of War™.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/356190/header.jpg?t=1747346596', 1, 0, NULL);
INSERT INTO games VALUES (73673, 356250, 'Gathering Sky', 'Guide a flock of birds on a playful journey across the sky.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/356250/header.jpg?t=1639684682', 0, 0, NULL);
INSERT INTO games VALUES (73674, 356260, 'Stalingrad', 'Stalingrad is a real-time strategy title that places gamers in the middle of the most dramatic periods of World War II, covering major events from June 1942 till January 1943.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/356260/header.jpg?t=1721994265', 0, 0, NULL);
INSERT INTO games VALUES (73682, 356400, 'Thumper', 'Thumper is rhythm violence: classic rhythm-action, blistering speed, and brutal physicality. You are a space beetle. Brave the hellish void and confront a maniacal giant head from the future.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/356400/header.jpg?t=1677622045', 1, 0, NULL);
INSERT INTO games VALUES (73683, 356420, 'Interloper', 'Interloper is an online multiplayer real-time strategy game with matches that take only 5 minutes. Instead of destroying your opponent, you win by claiming domain. By predicting your opponent''s movements, you corner them to claim the entire map.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/356420/header.jpg?t=1576535261', 0, 1, NULL);
INSERT INTO games VALUES (73684, 356430, 'Chris Sawyer''s Locomotion™', 'Explore a vast and detailed world and build a Transportation Empire!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/356430/header.jpg?t=1668116367', 0, 0, NULL);
INSERT INTO games VALUES (73685, 356450, 'Creature Romances: Kokonoe Kokoro', 'A short love story with a twist: the love of your life is 50% human, and 50% grasshopper.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/356450/header.jpg?t=1726604921', 0, 0, NULL);
INSERT INTO games VALUES (132806, 356500, 'STAR WARS™ Galactic Battlegrounds Saga', 'Lead the great armies of the Star Wars™ Episode II: Attack of the Clones saga in intense real-time strategy clashes. Enter the fray as the Galactic Empire, Rebel Alliance, Wookies, Trade Federation, Gungans or Royal Naboo to determine the course of the Galactic Civil War.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/356500/header.jpg?t=1741813559', 0, 0, NULL);
INSERT INTO games VALUES (73647, 356530, 'The Confines Of The Crown', 'Madeleine Valois is a prince''s companion. It is her responsibility to keep him out of trouble - not to let him walk blindly into a political minefield, not to let him get arrested for a crime he didn''t commit, and definitely not to let him fall in love with her...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/356530/header.jpg?t=1666987728', 0, 0, NULL);
INSERT INTO games VALUES (73651, 356570, 'Party Hard', 'It''s 3:00 a.m. Your neighbours are having a loud party. Stop them. Party Hard is tinyBuild''s award-winning stealth strategy game about ruining parties by any means.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/356570/header.jpg?t=1739395561', 0, 0, NULL);
INSERT INTO games VALUES (73653, 356650, 'Death''s Gambit: Afterlife', 'Death''s Gambit: Afterlife is a challenging 2D action platformer with deep RPG elements. As an agent of Death bound to his service, unravel the mystery of Siradon and discover the true price of immortality.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/356650/header.jpg?t=1744756224', 1, 0, NULL);
INSERT INTO games VALUES (73636, 356880, 'Eron', 'Eron is a 2D platform game that allows the player to actively switch between two parallel realms. The player will have to depend upon this power to finish each level.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/356880/header.jpg?t=1613074049', 0, 0, NULL);
INSERT INTO games VALUES (73637, 356890, 'One More Line', 'ONE MORE LINE is a highly addictive, one button, space disco, skill timing game! Steam edition features 2-4 player local multi-player and no advertising. All for a very low price! Can you put a price on fun though?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/356890/header.jpg?t=1732757843', 0, 0, NULL);
INSERT INTO games VALUES (73638, 356910, 'Battle Fantasia -Revised Edition-', '&quot;Battle Fantasia&quot;, the fantasy RPG themed 2D Fighting game is now appearing on Steam, and &quot;REVISED&quot; with the latest balances and improved visual effects! Comes with FREE Soundtrack DLC!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/356910/header.jpg?t=1671432278', 0, 0, NULL);
INSERT INTO games VALUES (73641, 357190, 'ULTIMATE MARVEL VS. CAPCOM 3', 'Marvel and Capcom join forces to deliver the most frenetic 3 vs 3 tag battles ever with Ultimate Marvel VS Capcom 3. This release comes fully loaded, including all previous DLC, Marvel VS. Capcom : Official Complete Works.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/357190/header.jpg?t=1644282901', 0, 0, NULL);
INSERT INTO games VALUES (73644, 357290, 'Red Lake', 'Red Lake - horror shooter with elements of quest.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/357290/header.jpg?t=1725633905', 0, 0, NULL);
INSERT INTO games VALUES (73619, 357300, 'Snakebird', 'Do you like puzzles, fruit and the notion of crossing a snake with a bird for no good reason? If the answer to at least one of those questions is yes, then Snakebird might be the game for you. Solve your way through this headscratcher of a puzzle game and help the snakebirds sate their hunger.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/357300/header.jpg?t=1732195053', 0, 0, NULL);
INSERT INTO games VALUES (73620, 357310, 'Oriental Empires', 'Turn based 4X strategy game, recreating the civilizations of ancient China. Develop your land, build great cities, raise huge armies and fight epic battles, with hundreds of soldiers fighting right on the game map. Advance your technologies, culture and religion to create one of mankind’s biggest empires.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/357310/header.jpg?t=1728468084', 0, 0, NULL);
INSERT INTO games VALUES (73622, 357330, 'Space Beast Terror Fright', 'S.B.T.F. is a very hard arcade-style / rogue-like / perma-death first person shooter. You play as Marines who must brave dark, claustrophobic and terrifyingly intense Space Beast infested spacecraft in order to extract critical data and lucrative upgrades. Can you make it out alive?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/357330/header.jpg?t=1676281440', 0, 0, NULL);
INSERT INTO games VALUES (73629, 357670, 'Home Improvisation: Furniture Sandbox', 'Build beautifully precise or wildly creative furniture! Decorate an entire house with your creations. 4 players can play locally, or invite an online player to help you build! Full support for the HTC Vive, including local and online multiplayer', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/357670/header.jpg?t=1469725368', 0, 0, NULL);
INSERT INTO games VALUES (73634, 357780, 'Defend Your Life: TD', 'Defend Your Life! Is tower defense set in human body where players are fighting against villain hordes of viruses and bacteria. Levels and units correspond to reality of human anatomy.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/357780/header.jpg?t=1729248674', 0, 0, NULL);
INSERT INTO games VALUES (73606, 357900, 'Make it indie!', 'Claw your way through the abyss of the mind and survive the horrors that stalk you as you attempt to survive seven days as... an Indie Developer.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/357900/header.jpg?t=1693047094', 0, 0, NULL);
INSERT INTO games VALUES (73613, 358070, 'Earthtongue', 'Care for a miniature ecosystem in a strange world, exert limited influence to encourage the growth of different fungi and bugs and try to maintain the balance of life.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/358070/header.jpg?t=1743490402', 0, 0, NULL);
INSERT INTO games VALUES (73615, 358090, 'D4: Dark Dreams Don’t Die -Season One-', 'This is the story of a man with a very strange fate. His name is David Young. Two years ago, his wife was murdered by an unknown assailant, and Young suffered a blow to the head that cost him his memory. His wife''s final words: “Look for D.”', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/358090/header.jpg?t=1729070604', 0, 0, NULL);
INSERT INTO games VALUES (73616, 358130, 'Curious Expedition', 'Curious Expedition is a roguelike expedition simulation set in the late 19th century. Together with famous personalities you will venture on unprecedented expeditions to regions never explored before for fame, science and treasures.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/358130/header.jpg?t=1745320650', 1, 0, NULL);
INSERT INTO games VALUES (73597, 358360, 'Raptor: Call of the Shadows (1994 Classic Edition)', 'Become a mercenary of the future and pilot the super-tech Raptor. Embark on interplanetary missions to knock off top competitors of MegaCorp, battle against hordes of relentless enemies and spend the bounty to expand your devastating arsenal, which can be upgraded with 14 hardcore weapons!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/358360/header.jpg?t=1720813487', 0, 0, NULL);
INSERT INTO games VALUES (73580, 358750, 'Sunrider: Liberation Day - Captain''s Edition', 'Liberation Day will come... but you will be betrayed. Experience the stunning continuation of Sunrider Mask of Arcadius in this hardcore turn based tactics game with heavy story elements.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/358750/header.jpg?t=1666988884', 0, 0, NULL);
INSERT INTO games VALUES (73582, 358770, 'The Reject Demon: Toko Chapter 0 — Prelude', 'When a human is destined to die, the demons ferry their souls to the afterlife. ‘The Reject Demon: Toko’ is the story of Toko herself, a demon who has been kicked out of hell. Toko cannot ferry human souls to the underworld, and every day she stays on earth has her becoming increasingly human.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/358770/header.jpg?t=1513925885', 0, 0, NULL);
INSERT INTO games VALUES (73584, 358830, 'Good Robot', 'Good Robot is a fast-paced roguelike shoot-em-up that pits you against thousands of robots out to violate your warranty. Explore a procedurally generated sci-fi metropolis and the depths of corporate depravity, but never stop shooting...unless, of course, you''re a Bad Robot. You''re not, are you?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/358830/header.jpg?t=1725109057', 0, 0, NULL);
INSERT INTO games VALUES (73586, 358920, 'Star Control I and II', 'Explore a vast universe with pulse-pounding action, side-splitting humor, and hair-raising plot twists in these 2 classic space adventure games.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/358920/header.jpg?t=1667930835', 0, 0, NULL);
INSERT INTO games VALUES (73587, 358960, 'Canabalt', 'Escape the destruction of your city with just one button! The game that popularized the infinite runner genre is back with two-player mode and new challenges.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/358960/header.jpg?t=1667408434', 0, 0, NULL);
INSERT INTO games VALUES (73557, 359040, 'The Music Machine', 'A teenage girl and the vengeful ghost possessing her stumble onto horrors of cosmic proportions as the latter searches for a way to murder the former.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/359040/header.jpg?t=1723596153', 0, 0, NULL);
INSERT INTO games VALUES (73558, 359050, 'Shower With Your Dad Simulator 2015: Do You Still Shower With Your Dad', '&quot;Shower With Your Dad Simulator 2015: Do You Still Shower With Your Dad?&quot; is a fast paced shower-simulation where you shower with your 8-bit dad.It''s good, clean fun!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/359050/header.jpg?t=1723593366', 0, 0, NULL);
INSERT INTO games VALUES (73562, 359100, 'Q.U.B.E. 2', 'Q.U.B.E. 2 is the sequel to the hit first-person puzzle game Q.U.B.E. You are Amelia Cross, a stranded archaeologist who has awoken among the ruins of an ancient alien landscape. With the distant help of another survivor you must solve the puzzles of this mysterious world and find a way back home.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/359100/header.jpg?t=1717070275', 0, 0, NULL);
INSERT INTO games VALUES (73563, 359140, 'Kick Ass Commandos', 'Lock and Load! It''s time to Kick-Ass. Grab your machine gun, flamethrower, rocket launcher, and grenades. Assault the enemy base and free commandos to join your team while you destroy everything in sight. Make your way through enemy bunkers to rescue your comrades, and kill everyone you encounter!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/359140/header.jpg?t=1691192003', 0, 0, NULL);
INSERT INTO games VALUES (73566, 359220, 'MX vs. ATV Unleashed', 'Take on the racing world in an attempt to knock off motocross and ATV riders in over 50 technical supercross and rugged outdoor tracks.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/359220/header.jpg?t=1727858012', 0, 0, NULL);
INSERT INTO games VALUES (73567, 359230, 'Lethis - Path of Progress', 'Lethis - Path of Progress is a city-builder in a victorian steampunk setting.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/359230/header.jpg?t=1572359819', 0, 0, NULL);
INSERT INTO games VALUES (73572, 359310, 'Evoland 2', 'Evoland 2 is an unique RPG, with its graphic style and gameplay changing as you progress through a deep storyline based on time travel.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/359310/header.jpg?t=1737537707', 0, 0, NULL);
INSERT INTO games VALUES (73574, 359350, 'Defunct', 'Defunct is an indie adventure game with a focus on flow, speed and an engaging world. You are a broken robot that accidentally falls out of a giant cargo ship onto a post-human Earth, now inhabited by robots. You have to get back to your ship before it’s too late!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/359350/header.jpg?t=1653300806', 1, 0, NULL);
INSERT INTO games VALUES (73576, 359400, 'Why Am I Dead At Sea', 'Why Am I Dead At Sea is an adventure game where you solve the mystery of your own murder. As a ghost, you will have to possess people and use them to investigate your surroundings. But in this place no one is who they seem...and everyone has a secret.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/359400/header.jpg?t=1733182967', 0, 0, NULL);
INSERT INTO games VALUES (73578, 359440, 'Artifact Adventure', 'The horribly toxic Swamp King has risen once again! Gather your party and set out on an open world, retro-styled, RPG adventure. Powerful mystical artifacts are scattered about the world, each able to grant you new powers. Which will you choose? What is your destiny?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/359440/header.jpg?t=1576136802', 0, 0, NULL);
INSERT INTO games VALUES (135255, 359550, 'Tom Clancy''s Rainbow Six® Siege', 'Tom Clancy''s Rainbow Six® Siege is an elite, tactical team-based shooter where superior planning and execution triumph.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/359550/header.jpg?t=1742315874', 1, 0, NULL);
INSERT INTO games VALUES (73548, 359580, 'Uncanny Valley', 'Uncanny Valley is a survival horror game that includes a mix of exploration, puzzle solving and a bit of action with a lot of optional story content. We''re trying to preserve the old survival horror kind of gameplay instead of following the modern trend of creating a third person shooter with horror elements.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/359580/header.jpg?t=1679426801', 0, 0, NULL);
INSERT INTO games VALUES (73549, 359600, 'Assassin’s Creed® Chronicles: Russia', 'Join Nikolaï Orelov in his search for redemption as you journey through an iconic, propaganda art style Russia in 2.5D gameplay. • Survive the aftermath of October Revolution &amp; travel accross Russia. • Experience the thrill of being a stealthy Assassin in an exclusive modern setting.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/359600/header.jpg?t=1692034902', 1, 0, NULL);
INSERT INTO games VALUES (73550, 359610, 'Assassin’s Creed® Chronicles: India', 'Embody Arbaaz in his quest for retribution through a colourful depiction of Colonial India in 2.5D stealth gameplay. • Travel across an amazing 19th Century India and its legendary landmarks. • Experience the thrill of a stealthy assassin with a unique set of skills and weapons such as the double kill moves and the chakram.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/359610/header.jpg?t=1692034847', 1, 0, NULL);
INSERT INTO games VALUES (73553, 359650, 'Star Trek™ : 25th Anniversary', 'Beam aboard the USS Enterprise to join Captain Kirk and his intrepid crew in this classic adventure game. Eight original missions, each styled as episodes of an imagined fourth season of Star Trek: the Original Series, featuring the voice talents of the original actors!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/359650/header.jpg?t=1670527270', 0, 0, NULL);
INSERT INTO games VALUES (73556, 359810, 'Hare In The Hat', 'Evil magician holds the Hare imprisoned. Your quest is to save him! Join the fabulous adventure in perfect mix of hidden object, puzzle and room escape genres!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/359810/header.jpg?t=1662330474', 0, 0, NULL);
INSERT INTO games VALUES (73538, 359900, 'The Incredible Adventures of Van Helsing III', 'Van Helsing, monster hunter will face the most difficult trials of his life as he is trying to destroy his nemesis. The civil war is over in Borgovia, but the future still looks grim. The city of weird science is in ruins and a strange cult prophesises the coming of the end times.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/359900/header.jpg?t=1572445840', 0, 0, NULL);
INSERT INTO games VALUES (73539, 359920, 'Highlands', 'Highlands is a hand-drawn turn-based strategy game with unique characters, resource management and RPG elements where the focus is directed toward decision-making.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/359920/header.jpg?t=1478048479', 0, 0, NULL);
INSERT INTO games VALUES (73540, 359940, 'Shadows Peak', 'Shadows Peak is an atmospheric, open-world horror game focused on exploration that doesn''t hold your hand. You play as a writer who has decided to visit a mysterious place called Shadows Peak to gather materials for a new book about legends.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/359940/header.jpg?t=1684511593', 1, 0, NULL);
INSERT INTO games VALUES (73545, 360150, 'How To Survive: Third Person Standalone', 'Driven by community suggestion, 505 Games and EKO Software introduce you to a new single player 3rd person view experience that allows you to re-play the zombie crafting adventure &quot;How to Survive&quot; from a deeply immersive point of view.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/360150/header.jpg?t=1463562158', 0, 0, NULL);
INSERT INTO games VALUES (73546, 360170, 'How to Survive 2', 'Dead or Alive? Make up your mind, stranger. We don’t like that undead business here in Louisiana…Survive solo or with friends as you look to fulfill your basic needs of food, water and shelter, crafting your own tools and weapons while you secure your camp and face flesh hungry zombies.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/360170/header.jpg?t=1591259378', 1, 0, NULL);
INSERT INTO games VALUES (73525, 360380, 'Tiny Bridge: Ratventure', 'This mind-bending game will challenge you to create complex structures to get your woodland creatures over vast chasms. In a bridge-builder first, you''ll guide your creatures and construct your bridges in real time. Use the weight of various creatures to balance your structures as you build them.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/360380/header.jpg?t=1574483895', 0, 0, NULL);
INSERT INTO games VALUES (73529, 360510, 'Into the Stars', 'Take the role of Captain in this Space Survival Simulation as you explore a massive star system in search of a new home for humanity. Outfit your ship, hand pick your crew and set off on a journey through an open-world where you must scavenge resources, shelter civilians and outrun a hostile alien force.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/360510/header.jpg?t=1725032440', 0, 0, NULL);
INSERT INTO games VALUES (73532, 360550, 'Cursed Sight', 'Being able to control fate would be a blessing for many. To Miyon, it is her greatest curse.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/360550/header.jpg?t=1737937005', 0, 0, NULL);
INSERT INTO games VALUES (73535, 360640, '12 Labours of Hercules II: The Cretan Bull', 'Accompany Hercules in his quest for the Cretan Bull!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/360640/header.jpg?t=1530694120', 1, 0, NULL);
