INSERT INTO games VALUES (73316, 365810, 'Flying Tigers: Shadows Over China', 'FLYING TIGERS: SHADOWS OVER CHINA is an air-combat action game based on the historical events of America’s secret volunteer squadrons that defended China against Japan in the China-Burma-India theatre of World War 2.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/365810/header.jpg?t=1697523602', 0, 0, NULL);
