INSERT INTO games VALUES (73322, 365890, 'Heroes of Normandie', 'Take one of the most modern, fun and engaging board games created in recent years. Match it with cutting-edge technology. Add a ridiculously well-crafted art style and a ton of extra content. This is the recipe to one of the most thrilling, charming and captivating strategy games you will ever find.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/365890/header.jpg?t=1726823989', 0, 0, NULL);
INSERT INTO games VALUES (73323, 365900, 'Pixel Dungeon', 'Pixel Dungeon is an exciting and extremely popular roguelike (more than 2 million mobile installs!). Explore the depths of Pixel Dungeon, collect useful items and fight fierce monsters to find the Amulet of Yendor - the ultimate artefact of this game world!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/365900/header.jpg?t=1447373246', 0, 0, NULL);
INSERT INTO games VALUES (73324, 365960, 'rFactor 2', 'rFactor 2 is a realistic, easily extendable racing simulation that offers race customization, great graphics, outstanding multiplayer and the height of racing realism. It features mixed class road racing with ultra realistic dynamics, an immersive sound environment and stunning graphics.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/365960/header.jpg?t=1727871590', 0, 0, NULL);
INSERT INTO games VALUES (73326, 366000, 'Rogue System', 'Our goal is to depict the possibilities of space exploration &amp; combat within a realistic environment- to emphasize the &quot;science&quot; in science-fiction. Key features to include: proper orbital mechanics for all objects in space, detailed ship system control, functionality, inter-dependency &amp; damage reaction.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/366000/header.jpg?t=1666095303', 0, 0, NULL);
INSERT INTO games VALUES (129713, 366090, 'Colony Survival', 'Colony Survival is a unique first-person strategy game developed by a two-man team. Build your own colony in a voxel world. Command guards, farmers, miners and other colonists. Defend your colony against the horde of monsters that attacks every night!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/366090/header.jpg?t=1735250022', 1, 0, NULL);
INSERT INTO games VALUES (73333, 366220, 'Wurm Unlimited', 'Wurm Unlimited is the standalone version of the fantasy sandbox world Wurm Online, the MMORPG where the players are in charge! A pioneer in the ideas of player influence, crafting and adventure, it is now one of the most deep and feature packed true sandbox experiences available.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/366220/header.jpg?t=1748866954', 0, 0, NULL);
