INSERT INTO games VALUES (72877, 378110, 'Hack RUN', 'Ever wanted to be a hacker? Hack your way into the heart of a mysterious organization to uncover their secrets. Hack RUN® is a game which uses ''old school'' command prompts (like DOS or UNIX) that simulate a real operating system. Learn the commands of each system to help you navigate through your adventure.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/378110/header.jpg?t=1736944143', 0, 1, NULL);
INSERT INTO games VALUES (72880, 378270, 'Putrefaction', 'Putrefaction is a First Person Shooter with horror elements, lots of enemies and weapons, heavily inspired by old-school shooter classics.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/378270/header.jpg?t=1667015081', 0, 0, NULL);
INSERT INTO games VALUES (72847, 378360, 'Ymir', 'Ymir is a 4X multiplayer strategy game combined with a city builder where each player develops a civilization of pigmen starting at the stone age.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/378360/header.jpg?t=1660744127', 0, 0, NULL);
INSERT INTO games VALUES (72848, 378370, 'Nomad', 'Try and survive in the world of Nomad. Build a base and protect it from raiding players. Scavenge food, weapons and medical supplies across the island. Team up with others and make a base. Make your mark on the world of Nomad.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/378370/45aceac526e60a66e23e617cbebbd82ae94353e2/header_alt_assets_0.jpg?t=1748356627', 0, 1, NULL);
INSERT INTO games VALUES (72857, 378540, 'The Surge', 'Welcome to CREO, the megacorporation saving the world! A catastrophic event has knocked you out during the first day on the job… you wake up equipped with a heavy-grade exoskeleton, in a destroyed section of the complex.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/378540/header.jpg?t=1727864911', 1, 0, NULL);
INSERT INTO games VALUES (72859, 378580, 'Untamed: Life Of A Cougar', 'Experience the life of a mountain lion in the brutal wild, Fight and maintain your territory, find a mate and raise cubs of your own which will grow into adults as your parenting skills are put to the test. Hunt prey, both big and small as you level up to become an effective and lethal hunter.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/378580/header.jpg?t=1574195305', 0, 0, NULL);
INSERT INTO games VALUES (72861, 378610, 'Valley', 'Explore the vast and beautiful world of Valley using the power of the L.E.A.F. suit: a fierce exoskeleton that grants exceptional speed and agility along with the phenomenal ability to manipulate the life and death of all living things.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/378610/header.jpg?t=1726514352', 0, 0, NULL);
INSERT INTO games VALUES (72837, 378660, 'Blues and Bullets', 'Blues and Bullets is a dark and violent crime thriller. Set in an alternative Eliot Ness &amp; Al Capone story, Blues and Bullets blends a stunning script with detective work to deliver an amazing interactive experience.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/378660/header.jpg?t=1458041192', 0, 0, NULL);
INSERT INTO games VALUES (72839, 378720, 'Thea: The Awakening', 'Thea: The Awakening is a turn-based strategic survival game inspired by the Slavic mythology and set in a procedural dark fantasy world infused with non-linear story and unique combat system.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/378720/header.jpg?t=1748852652', 0, 0, NULL);
INSERT INTO games VALUES (72841, 378770, 'ESCHATOS', 'An alien menace has descended on Earth! Defend the world from UFO invasion in this superb arcade shooter from Qute. Use your weapons effectively, deflect enemy bullets with your shield, and recapture the Moon from alien infestation!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/378770/header.jpg?t=1698788862', 0, 0, NULL);
INSERT INTO games VALUES (72843, 378800, 'Police Tactics: Imperio', 'In POLICE TACTICS: IMPERIO you start your career as an aspiring police chief in Newport Falls, a city that is dirty and corrupt to its core. You are responsible for upholding law and order. Coordinate the emergency vehicles and personnel of the municipal precinct and put a stop to crime.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/378800/header.jpg?t=1729175314', 0, 0, NULL);
INSERT INTO games VALUES (136248, 379210, 'Wayward', 'You awake to discover yourself no longer in the company of good men or a fine seafaring vessel. Treasure... you remember something about treasure. Wayward is a challenging turn-based, top-down, wilderness survival roguelike. Explore, build, and most importantly survive in these unforgiving lands.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/379210/header.jpg?t=1734502102', 0, 0, NULL);
INSERT INTO games VALUES (72829, 379420, 'Polynomial 2 - Universe of the Music', 'Polynomial 2 is an amazing visual candy which tends to be a space shooter and a music visualizer. Immersive on screen, mind-blowing in VR.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/379420/header.jpg?t=1737712743', 0, 0, NULL);
INSERT INTO games VALUES (72830, 379430, 'Kingdom Come: Deliverance', 'Story-driven open-world RPG that immerses you in an epic adventure in the Holy Roman Empire. Avenge your parents'' death as you battle invading forces, go on game-changing quests, and make influential choices. Explore castles, forests, villages and other realistic settings in medieval Bohemia!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/379430/header.jpg?t=1741619061', 1, 0, NULL);
INSERT INTO games VALUES (72824, 379720, 'DOOM', 'Now includes all three premium DLC packs (Unto the Evil, Hell Followed, and Bloodfall), maps, modes, and weapons, as well as all feature updates including Arcade Mode, Photo Mode, and the latest Update 6.66, which brings further multiplayer improvements as well as revamps multiplayer progression.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/379720/header.jpg?t=1692892793', 0, 0, NULL);
INSERT INTO games VALUES (72828, 379980, 'Panzermadels: Tank Dating Simulator', 'Panzermadels! The first dating simulator to deliver a thoughtful look at tanks, and the men who date them!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/379980/header.jpg?t=1660434621', 0, 0, NULL);
INSERT INTO games VALUES (72813, 380020, 'Three Heroes', 'A magic world, epic heroes, bright graphics, excellent humor and absorbing gameplay – “Three Heroes”!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/380020/header.jpg?t=1568038386', 0, 0, NULL);
INSERT INTO games VALUES (72817, 380150, 'STASIS', 'STASIS The isometric, point-and-click, sci-fi horror adventure game! In the distant future aboard a seemingly abandoned spacecraft, John Maracheck awakes from stasis. He must push himself to new physical and emotional limits and unravel the mysteries around him.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/380150/header.jpg?t=1745837938', 0, 0, NULL);
INSERT INTO games VALUES (72818, 380220, 'Hover Junkers', 'Engage in multiplayer VR gunfights that capture real gun play like no FPS you''ve played before. Pilot and fortify Hover Junkers as you physically walk, duck, dodge and aim in cross ship combat.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/380220/header.jpg?t=1667677745', 0, 0, NULL);
INSERT INTO games VALUES (72801, 380580, 'SpaceCorn', 'You''re a unicorn in an alien planet. Now what?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/380580/header.jpg?t=1456616065', 0, 0, NULL);
INSERT INTO games VALUES (139847, 380600, 'Fishing Planet', 'Fishing Planet® is a free-to-play and highly realistic first-person online multiplayer fishing simulator. Developed by avid fishing enthusiasts to bring you the full thrill of actual angling on your PC.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/380600/header.jpg?t=1749258616', 0, 1, NULL);
INSERT INTO games VALUES (72802, 380660, 'Killing Time at Lightspeed: Enhanced Edition', 'Browse social media at the speed of light. Watch your friends grow old in the blink of an eye. Realise there''s nothing you can do about it. Tell your friends you love them one last time.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/380660/header.jpg?t=1477605768', 0, 0, NULL);
INSERT INTO games VALUES (72803, 380670, 'Final Approach', 'Take control of the skies like never before in a full Virtual Reality world! Airplanes on fire, commuter aircraft low on fuel, mid-air collisions, emergency helicopter rescues, military exercises and so much more!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/380670/header.jpg?t=1510949215', 0, 0, NULL);
INSERT INTO games VALUES (72806, 380750, 'Anima: Gate of Memories', 'A third-person action RPG that brings to life the world of Gaia from the Anima: Beyond Fantasy RPG table-top books. Explore a deep and multifaceted story where your choices and actions directly impact the journey and decide the fate of the characters.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/380750/header.jpg?t=1748947919', 0, 0, NULL);
INSERT INTO games VALUES (72781, 381020, 'Sky Rogue', 'Sky Rogue is a fwooshy rogue-lite action flight simulator! Blow things up over land, sea, and air, on an infinite number of procedurally-generated islands. Go toe-to-toe with enemy aces or assault giant flying aircraft carriers, but watch out for volleys of missiles; when you die, you''re dead.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/381020/header.jpg?t=1660334660', 1, 0, NULL);
INSERT INTO games VALUES (72783, 381100, 'The Men of Yoshiwara: Kikuya', '&quot;The Men of Yoshiwara&quot; is a popular romance game for women. At the end, to whom is it that you will be talking of love? Vocal opening song/English text', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/381100/header.jpg?t=1667192258', 0, 0, NULL);
INSERT INTO games VALUES (72784, 381120, 'Shoppe Keep', 'Run an adventurers shop – a serious business in a fantasy environment. Stock your store with dangerous weapons, fancy hats, sturdy armour and magical potions.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/381120/header.jpg?t=1726150362', 0, 0, NULL);
INSERT INTO games VALUES (132194, 381210, 'Dead by Daylight', 'Trapped forever in a realm of eldritch evil where even death is not an escape, four determined Survivors face a bloodthirsty Killer in a vicious game of nerve and wits. Pick a side and step into a world of tension and terror with horror gaming''s best asymmetrical multiplayer.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/381210/header.jpg?t=1746584187', 1, 0, NULL);
INSERT INTO games VALUES (72790, 381260, 'Orion Trail', 'Dare to travel the absurd and dangerous Orion Trail, where only the luckiest, bravest, and most stubborn captains will make it all the way to the end. Become famously incredible or incredibly dead in this single player choose-your-own-space-adventure!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/381260/header.jpg?t=1727895906', 0, 0, NULL);
INSERT INTO games VALUES (72768, 381750, 'RC Simulation 2.0', 'Drive all kinds of RC Cars, Boats, Rock Crawlers, Planes or Quadcopters on any of the 250+ Workshop Tracks. The game includes an in-game Track Editor and Vehicle Painter to create tons of scenarios and Paint schemes. RC Sim is made by a solo developer and still is in development.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/381750/header.jpg?t=1572587305', 0, 0, NULL);
INSERT INTO games VALUES (72769, 381780, '80 Days', '1872, with a steampunk twist. Phileas Fogg has wagered he can circumnavigate the world in just 80 days. Travel by airship, submarine, mechanical camel, steam-train and more. Race other players and a clock that never stops in TIME Magazine''s Game of 2014.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/381780/header.jpg?t=1736524091', 0, 0, NULL);
INSERT INTO games VALUES (72747, 382050, 'Eon Altar', 'A role-playing game like no other. Your smartphone is your character! Eon Altar brings modern technology to the social experience of couch co-op gaming. Voice your character, choose which secrets to keep and what lies to tell. Gather your friends, order a pizza and descend to the depths of Eon Altar!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/382050/header.jpg?t=1572484279', 0, 0, NULL);
INSERT INTO games VALUES (72750, 382090, 'Dungeon Nightmares II : The Memory', 'Dungeon Nightmares II is a first-person psychological horror that takes you through a journey of discovering what nightmares are.The game is inspired by classic roguelike games which include 100% procedural-generated maps and permadeath.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/382090/header.jpg?t=1548753368', 0, 0, NULL);
INSERT INTO games VALUES (72751, 382110, 'Virtual Desktop Classic', 'Virtual Desktop is an application developed for the Oculus Rift / Rift S, HTC Vive, Valve Index and WMR headsets that lets you use your computer in VR. This app is NOT for the Oculus Quest or Pico headsets. You can browse the web, watch movies, Netflix or even play games on a giant virtual screen.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/382110/header.jpg?t=1720789559', 0, 0, NULL);
INSERT INTO games VALUES (72754, 382140, 'SKYHILL', 'World War III is over, the world''s infested with mutants and your supplies are running out. Fight your way down this damned hotel, from your penthouse on top to the first floor. Craft weapons, search for food and reach the exit. Otherwise you''ll be torn apart, starve to death or maybe both...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/382140/header.jpg?t=1725005037', 1, 0, NULL);
INSERT INTO games VALUES (72758, 382260, '8Bit Fiesta - The Drinking Game', '8Bit Fiesta brings everything you need to the table with its action packed local multiplayer mayhem including a built in drinking game! Choose between a ton of characters and challenge your friends and prove yourself worthy the title &quot;King of the Fiesta&quot;.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/382260/header.jpg?t=1723586951', 0, 1, NULL);
INSERT INTO games VALUES (72760, 382300, 'Kidnapped', 'Kidnapped is a psychological story-driven horror game, featuring emphasis on exploration, puzzle solving and combat. Kidnapped dynamically changes as the player progresses, and aims to unnerve the player. Traverse a two hundred year old manor, dark damp caves, an eerie forest and more.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/382300/header.jpg?t=1475255729', 0, 0, NULL);
INSERT INTO games VALUES (135257, 382310, 'Eco', 'Build a civilization of real people, working together to advance society and stop a meteor, all without destroying the ecosystem in the process.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/382310/header.jpg?t=1726567790', 1, 0, NULL);
INSERT INTO games VALUES (72762, 382330, 'Killers and Thieves', 'Become the leader of a medieval thieves'' guild in Killers and Thieves from the co-creator of the Banner Saga series. Train a team, steal loot and master heists throughout a sprawling city to take your revenge.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/382330/header.jpg?t=1495605075', 0, 0, NULL);
INSERT INTO games VALUES (72764, 382380, 'The Amber Throne', 'Amber Throne is a turn-based JRPG-styled game about a girl in a desert world beneath a mysterious floating castle, and her quest to reach it.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/382380/header.jpg?t=1497733205', 0, 0, NULL);
INSERT INTO games VALUES (72745, 382560, 'Hot Lava', 'The Floor is Hot Lava! Run, jump, climb, and surf across nostalgia-packed environments flooded with hot molten lava. Explore alone, or join your friends. And whatever you do, don’t touch the floor.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/382560/header.jpg?t=1720817765', 1, 0, NULL);
INSERT INTO games VALUES (72736, 383080, 'Sakura Clicker', 'The latest entry in the Sakura series is more action-packed than ever before! Sakura Clickers is a fast-paced, exciting adventure, full of content, in which you defeat your foes with the power of your mouse!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/383080/header.jpg?t=1578342456', 0, 1, NULL);
INSERT INTO games VALUES (136602, 383120, 'Empyrion - Galactic Survival', 'Build and explore in a true space sandbox survival adventure. Construct mighty capital vessels, sprawling planetary settlements, and vast space stations in your galactic journey to discover the mysteries of Empyrion!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/383120/header.jpg?t=1709747913', 0, 0, NULL);
INSERT INTO games VALUES (72738, 383150, 'Dead Island Definitive Edition', 'Welcome to the zombie apocalypse experience of a lifetime – and now more beautiful than ever. Caught in the midst of an epic zombie outbreak on the tropical island of Banoi, your only thought is: Survive!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/383150/header.jpg?t=1725361899', 0, 0, NULL);
INSERT INTO games VALUES (72739, 383180, 'Dead Island: Riptide Definitive Edition', 'Welcome to the zombie apocalypse experience of a lifetime – more beautiful than ever. Caught in an epic zombie outbreak on the tropical island of Banoi, your only thought is: Survive!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/383180/header.jpg?t=1725362483', 0, 0, NULL);
INSERT INTO games VALUES (72740, 383230, 'Dungeon Souls', 'Dungeon Souls is an action-adventure roguelike dungeon crawler which draws heavy inspiration from Nuclear Throne, Risk of Rain, and Overture. Explore vast procedurally generated dungeons, collect loot, and slay hordes of challenging enemies!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/383230/header.jpg?t=1694567639', 0, 0, NULL);
INSERT INTO games VALUES (72742, 383270, 'Hue', 'Hue is a vibrant, award-winning puzzle-adventure, where you alter the world by changing its background colour.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/383270/header.jpg?t=1747737955', 0, 0, NULL);
INSERT INTO games VALUES (72707, 383460, 'Sound of Drop - fall into poison -', 'Nestled in the heart of Tokyo, the quaint little aquarium, Manten Aquarium. Numerous urban legends have arisen from here. On the night of the full moon the waters turn to blood and man faced fish lurk within.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/383460/header.jpg?t=1610484894', 0, 0, NULL);
INSERT INTO games VALUES (72715, 383690, 'Mu Complex', 'Play as a hacker and take control of an ultra secret company to reveal the darkest secrets. But beware , you seem not to be alone and what you will discover could change the world ...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/383690/header.jpg?t=1453828583', 0, 0, NULL);
INSERT INTO games VALUES (72720, 383740, 'Marble Age: Remastered', 'Marble Age is a turn-based historical strategy where your task is to turn a small Ancient Greek village into a flourishing Polis, powerful enough to conquer the known world!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/383740/header.jpg?t=1667297975', 0, 0, NULL);
INSERT INTO games VALUES (72723, 383790, 'The Ship: Remasted', 'You find yourself aboard a series of luxury 1920s cruise ships – a guest of the mysterious Mr X who has engineered your presence on board to take part in a murderous game.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/383790/header.jpg?t=1628761687', 0, 0, NULL);
INSERT INTO games VALUES (72726, 383840, 'Nimbatus - The Space Drone Constructor', 'Command the Nimbatus and craft drones out of hundreds of different parts. Survive unknown threats in a fully destructible, procedural universe, compete against other players in different arenas or enjoy complete creative freedom in the sandbox.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/383840/header.jpg?t=1729081907', 1, 0, NULL);
INSERT INTO games VALUES (72728, 383870, 'Firewatch', 'Firewatch is a single-player first-person mystery set in the Wyoming wilderness, where your only emotional lifeline is the person on the other end of a handheld radio.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/383870/header.jpg?t=1738795199', 0, 0, NULL);
INSERT INTO games VALUES (72694, 383980, 'Rivals of Aether', 'RIVALS OF AETHER is an indie fighting game where warring civilizations summon the power of Fire, Water, Air, and Earth. Play with up to four players either locally or online.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/383980/header.jpg?t=1721063075', 0, 0, NULL);
INSERT INTO games VALUES (72701, 384110, 'Pathologic Classic HD', 'Pathologic Classic HD is the Definitive Edition of the original Cult Classic Psychological First-Person Survival game. In this unforgettable experience, players control one of three unique characters as they try to save a mysterious town from a deadly plague that cannot be stopped.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/384110/header.jpg?t=1604189746', 0, 0, NULL);
INSERT INTO games VALUES (135614, 384300, 'CPUCores :: Maximize Your FPS', 'Maximize your FPS :: Use CPUCores to isolate and constrain OS + non-game processes and dedicate CPU resources to be used exclusively for your games! CPUCores fully integrates with all Steam games!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/384300/header.jpg?t=1739668443', 1, 0, NULL);
INSERT INTO games VALUES (72688, 384310, 'Dead In Bermuda', 'DEAD IN BERMUDA is a survival management game with RPG and adventure elements. Lead a team of 8 survivors from a plane crash. Assign them to tasks, gain experience, develop your survival skills, research and craft new items, explore the island and solve its mysteries.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/384310/header.jpg?t=1737635388', 0, 0, NULL);
INSERT INTO games VALUES (72676, 384490, 'NECROPOLIS: BRUTAL EDITION', 'NECROPOLIS: BRUTAL EDITION is a major update featuring a new playable adventurer (The Brute), a completely new outdoor environment (The Black Forest), and lots of new enemies, weapons, armor, traps, potions, scrolls, and other big improvements to the game.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/384490/header.jpg?t=1711112928', 0, 0, NULL);
INSERT INTO games VALUES (72677, 384500, 'Zombie Party', 'Zombie Party is a retro rampage of fun and over-the-top action, while still giving the players a deep and engaging Action-RPG Rogue-like experience! Go on a time traveling adventure, or delve deep into procedural dungeons full of gold, loot, and secrets!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/384500/header.jpg?t=1748867482', 0, 0, NULL);
INSERT INTO games VALUES (72678, 384550, 'Painters Guild', 'Painters Guild is a management sim where you control an art academy in the Italian Renaissance. Paint artwork as beautiful as the Mona Lisa. Hire painters like Leonardo da Vinci and millions of randomly generated ones. Expand and customize your guild with furniture and more.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/384550/header.jpg?t=1728582539', 0, 0, NULL);
INSERT INTO games VALUES (72679, 384570, 'Zanzarah: The Hidden Portal', 'The legends speak of a long forgotten prophecy... of a shining hero and of perilous adventures... of sinister powers, strange worlds and swarms of fairies ... but they said nothing of a girl with a big heart instead of a big sword!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/384570/header.jpg?t=1705065765', 0, 0, NULL);
INSERT INTO games VALUES (72681, 384630, 'Aviary Attorney', 'The hottest bird lawyering game to come out of 1840s France! Join Jayjay Falcon and his witty apprentice, Sparrowson, as the two take on clients, interview witnesses, collect evidence, and deliver justice to the guilty.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/384630/header.jpg?t=1717762618', 0, 0, NULL);
INSERT INTO games VALUES (72683, 384680, 'MechaNika', 'If it''s not cool, it will disappear. If you''re not cool, hide. MechaNika is here.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/384680/header.jpg?t=1732634173', 1, 0, NULL);
INSERT INTO games VALUES (72684, 384690, 'Umihara Kawase', 'Umihara Kawase is a girl who uses a fishing hook as a grappling hook. You’ll need quick reflexes to swing your way through the branching surreal environments. Use your brains to figure out the best way through. They say fish is brain food—you’re going to need it!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/384690/header.jpg?t=1726110091', 0, 0, NULL);
INSERT INTO games VALUES (72658, 384740, 'CAT Interstellar', 'A short story inspired by Robert Heinlein''s:The Moon Is a Harsh Mistress', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/384740/header.jpg?t=1708695896', 0, 0, NULL);
INSERT INTO games VALUES (72659, 384750, 'EVEREST VR™', 'Experience what it feels like to climb Mount Everest through a sequence of immersive first person locations as you strive to reach the top of the world. Incomparable visual fidelity combined with player agency in a VR journey that feels both real and emotionally stunning.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/384750/header.jpg?t=1510656404', 0, 0, NULL);
INSERT INTO games VALUES (72665, 384960, 'Vengeance', 'Old-modern-school shooter with a focus on the player. Play one of the fastest multiplayer games out there with dozens of weapons and a challenging recoil. Play fast. Play the past!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/384960/header.jpg?t=1725376758', 0, 0, NULL);
INSERT INTO games VALUES (72639, 385240, 'Ultimate Arena', 'Pick and create characters to fight to the death in this action-packed nonsensical arena simulation.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/385240/header.jpg?t=1593125807', 0, 0, NULL);
INSERT INTO games VALUES (72640, 385250, 'Paint it Back', 'Use logic as your paintbrush to restore lost works of pixel art. Try the demo!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/385250/header.jpg?t=1567808631', 0, 0, NULL);
INSERT INTO games VALUES (72644, 385330, 'Stray Cat Crossing', 'Stray Cat Crossing is an indie pixel horror game about an encounter with a mysterious little girl named Cat. Explore a surreal world filled with colorful characters, challenging riddles, and dark secrets.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/385330/header.jpg?t=1447376978', 0, 0, NULL);
