INSERT INTO games VALUES (72654, 385560, 'Shadow Complex Remastered', 'ChAIR’s fresh twist on classic side-scrolling design with modern gameplay is amplified in Shadow Complex Remastered. 10+ hrs of exploration and fast-paced combat from award-winning original game, updated with graphical enhancements, dynamic melee take-downs, and new Master Challenges.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/385560/header.jpg?t=1470279978', 1, 0, NULL);
