INSERT INTO games VALUES (72615, 385800, 'NEKOPARA Vol. 0', 'Please note that NEKOPARA Vol. 0 is a fandisc for NEKOPARA Vol. 1What''s NEKOPARA? Why, it''s a cat paradise! This is a story just before Kashou opened &quot;La Soleil&quot;.Enjoy a page from the leisurely, daily lives of Shigure and the Minaduki household''s catgirls!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/385800/header.jpg?t=1726605114', 0, 0, NULL);
