INSERT INTO games VALUES (72583, 386260, 'Microcosmum: survival of cells', 'Microcosmum: survival of cells. Join the wonderful and amazing world of microorganisms.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/386260/header.jpg?t=1741359867', 1, 0, NULL);
