INSERT INTO games VALUES (72392, 392080, 'Wayward Terran Frontier: Zero Falls', '2d space combat like no other. From the perspective of a single crew member, explore the fully destructible interior of any ship in a massive living world. Engage in space combat with no hitpoints where you know your enemy is dead when you see them fall out of their ship into the cold dark of space.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/392080/header.jpg?t=1723326539', 0, 0, NULL);
INSERT INTO games VALUES (72394, 392110, 'ENDLESS™ Space 2', 'ENDLESS™ Space 2 is a Strategic Space Opera, featuring the compelling “just one more turn” gameplay, set in the mysterious ENDLESS™ Universe. As the leader of your civilization, will you impose your vision and build the greatest stellar empire?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/392110/header.jpg?t=1728046125', 1, 0, NULL);
INSERT INTO games VALUES (72400, 392280, 'The Franz Kafka Videogame', 'An original puzzle/adventure game inspired by the writings of Franz Kafka.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/392280/header.jpg?t=1732425410', 1, 0, NULL);
INSERT INTO games VALUES (72379, 392580, 'WARSHIFT', 'Unique mix of Action, RTS and RPG gameplay elements that forms an innovative game genre. You can build base, manage troops, and then come down to keep your enemy at gunpoint in the dynamic battle and customize your main characters.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/392580/header.jpg?t=1705088833', 0, 0, NULL);
INSERT INTO games VALUES (72372, 392970, 'New York Mysteries: High Voltage Collector''s Edition', 'Fearless journalist Laura is again brought in to investigate strange murders taking place in New York. Immerse yourself in an exciting crime story and solve the mystery of a dangerous criminal surrounded by lightning!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/392970/header.jpg?t=1678439449', 1, 0, NULL);
INSERT INTO games VALUES (72373, 393080, 'Call of Duty®: Modern Warfare® Remastered (2017)', 'One of the most critically-acclaimed games in history, Call of Duty: Modern Warfare is back, remastered in true high-definition, featuring improved textures, physically based rendering, high-dynamic range lighting and much more.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/393080/header.jpg?t=1748021557', 1, 0, NULL);
INSERT INTO games VALUES (72347, 393200, 'Bad Rats Show', 'Bad Rats Show is a physics puzzle game where the rats exact their bloody revenge against their main enemies: the Cats. Solve puzzles in 2D and 3D maps using physics, objects and specially trained Rats. All new Rats and Cats, but with the same classic and questionable Bad Rats humor.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/393200/header.jpg?t=1624719536', 0, 0, NULL);
INSERT INTO games VALUES (72356, 393380, 'Squad', 'Squad is a tactical FPS that provides authentic combat experiences through teamwork, communication, and realistic combat. It bridges the gap between arcade shooter and military realism with 100-player battles, combined-arms warfare, and base building.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/393380/0b19b50aabea356bd8f534fbe7d6db9bd227810a/header.jpg?t=1748639190', 0, 0, NULL);
INSERT INTO games VALUES (72358, 393420, 'Hurtworld', 'Hurtworld is a hardcore multiplayer survival FPS with a focus on competitive gunplay and strategic map control. Built for hardcore gamers, Hurtworld aims to punish.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/393420/header.jpg?t=1597169414', 0, 0, NULL);
INSERT INTO games VALUES (72359, 393430, 'Ice Lakes', 'Ice Lakes is a modern ice fishing simulator with different single and multiplayer game modes and sandbox approach to wintertime fishing. Use and customize wide selection of fishing gear and learn how changing season, bottom topology, time of day and weather conditions affects fish behavior.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/393430/header.jpg?t=1711379282', 1, 0, NULL);
