INSERT INTO games VALUES (72346, 394160, 'ARCADE GAME SERIES: PAC-MAN', 'First released in arcades in 1980, the masterpiece PAC-MAN comes to Steam! Move PAC-MAN up, down, left, and right to avoid the ghosts and gobble up all the Pac-Dots!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/394160/header.jpg?t=1654679168', 0, 0, NULL);
