INSERT INTO games VALUES (72302, 395160, 'Toby: The Secret Mine', 'A challenging puzzle platformer inspired by games like Limbo and Badland.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/395160/header.jpg?t=1667115395', 0, 0, NULL);
