INSERT INTO games VALUES (72284, 395570, 'We Are The Dwarves', 'We Are The Dwarves is a real-time tactical adventure where you take control of three Dwarven astronauts and lead them through the hordes of enemies in the depths of their Universe.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/395570/e1c54ab138d88bc461fd52802f46d1af6779b94f/header.jpg?t=1748940690', 0, 0, NULL);
