INSERT INTO games VALUES (72291, 395860, 'The Last Dream: Developer''s Edition', '“Reality and dreams are about to become entwined…..” The Last Dream: Developer''s Edition&quot; is a casual adventure game which, despite having some classic casual elements, will also offer a greater challenge for more experienced gamers.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/395860/header.jpg?t=1726513505', 1, 0, NULL);
INSERT INTO games VALUES (72294, 395900, 'Backgammon Blitz', 'Loved by millions, played for centuries, backgammon is a two-player strategy game quite unlike any other. The goal is simple: race to get your checkers off the board first. The deceptively deep rules and rhythm of backgammon has secured it as a favourite among casual and veteran players alike.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/395900/header.jpg?t=1591041284', 0, 0, NULL);
