INSERT INTO games VALUES (72270, 396160, 'Secret Of Magia', 'Secret of Magia is an action RPG. Explore a huge world and free your people from the tyranny of an evil, supernatural dictator.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/396160/header.jpg?t=1574484701', 0, 0, NULL);
