INSERT INTO games VALUES (72255, 396480, 'Battlevoid: Harbinger', 'Battlevoid: Harbinger is a hard sci-fi space exploration game blending roguelike, turn-based, star map strategy, and real-time space battles. You are a young commander venturing out into enemy territories, to unknown galaxies, never knowing what you will face as you jump out from hyperspace.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/396480/header.jpg?t=1667225465', 0, 0, NULL);
