INSERT INTO games VALUES (72249, 397160, 'Aurora Dusk: Steam Age', 'An amazing mix of RPG, strategy, simulation, sandbox and survival game. Aurora Dusk looks like many other games, but instead of being alone, you live in a community. You can play one or more villagers and evolve from the Wood Age to the Steam Age.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/397160/header.jpg?t=1667050290', 0, 0, NULL);
