INSERT INTO games VALUES (49168, 400510, 'The Final Take', 'Relive dark footage recorded from the perspective of multiple characters in this unique first person horror.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/400510/header.jpg?t=1716282140', 0, 0, NULL);
