INSERT INTO games VALUES (49174, 400660, 'Reverse Crawl', 'A dungeon crawl where YOU are the dungeon! Lead your minions in tactical turn-based combat against the pesky heroes, and unlock a variety of evil Powers. With a dynamic campaign system and a branching storyline, &quot;Reverse Crawl&quot; lets you experience an RPG from a whole new angle!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/400660/header.jpg?t=1630602136', 0, 0, NULL);
INSERT INTO games VALUES (49176, 400740, 'VERGE:Lost chapter', 'Our hero decided to escape from the hustle and bustle of the city and get out into nature to relax in a cabin that was in the mountains.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/400740/header.jpg?t=1737613194', 0, 0, NULL);
INSERT INTO games VALUES (136148, 400750, 'Call to Arms - Gates of Hell: Ostfront', 'Call to Arms - Gates of Hell is a realistic RTS/ RTT game that offers endless replay value. Command all types of troops in historical singleplayer, dynamic campaign, PvP and PvE battles. Are you ready for some serious immersion in World War 2?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/400750/dbbd1ee41869ac2bae52511ab9d171e1aba441e4/header.jpg?t=1747846873', 0, 0, NULL);
INSERT INTO games VALUES (49177, 400790, 'The Juicer', 'The game is a cheerful shooter with a user-friendly gameplay in an original setting.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/400790/header.jpg?t=1630080950', 0, 0, NULL);
INSERT INTO games VALUES (49178, 400800, 'MXGP2 - The Official Motocross Videogame', 'MXGP2 - The Official Motocross Videogame is the evolution of the previous Milestone’s Motocross game MXGP. The game is based on the 2015 FIM Motocross World Championship license.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/400800/header.jpg?t=1728479097', 0, 0, NULL);
INSERT INTO games VALUES (49166, 400910, 'Rabi-Ribi', 'Dodge bullets, missiles and lasers in battle as you wrap your head around that bunny girl costume! Combo away with your mighty Piko Hammer or spam various spells from afar with your fiery fairy friend. Explore and explode through Rabi-Rabi Island as you collect power-ups and uncover secrets...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/400910/header.jpg?t=1728971155', 1, 0, NULL);
INSERT INTO games VALUES (49167, 400940, 'Budget Cuts', 'Budget Cuts is a VR stealth game where you dexterously zip, sneak or rambo your way forward through thrilling, oil-splatter filled combat!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/400940/header.jpg?t=1743712406', 1, 0, NULL);
INSERT INTO games VALUES (49157, 401190, 'Dinosaur Hunt', 'Dinosaur Hunt is an intense action shooter that will take you on an epic journey of hunting the world’s most horrifying animals!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/401190/header.jpg?t=1641647940', 0, 0, NULL);
INSERT INTO games VALUES (49164, 401360, 'The Aquatic Adventure of the Last Human', 'Explore the ruins of the human race and discover the thriving wildlife that blossomed after our extinction in this underwater action/adventure. Encounter monstrous creatures and let curiosity guide you through an inevitable voyage of extinction.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/401360/header.jpg?t=1726781161', 0, 0, NULL);
INSERT INTO games VALUES (49150, 401680, 'POSTAL Redux', 'POSTAL Redux is a high definition remake of the classic dark and surreal twin-stick isometric shooter. Take control of The POSTAL Dude as he fights to survive in a world gone mad with violence.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/401680/header.jpg?t=1726332234', 0, 0, NULL);
INSERT INTO games VALUES (49151, 401690, 'Life in Bunker', 'You''ve been elected as the new Bunker Warden! Now you must take control over a group of fellow bunker residents and try to make them last until the surface becomes habitable.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/401690/header.jpg?t=1709491055', 0, 0, NULL);
INSERT INTO games VALUES (49152, 401710, 'Flinthook', 'Live the life of space captain Flinthook! Armed with your mighty hookshot, your uncanny slow-motion powers and your trusty blasma pistol, plunder and fight your way through an infinite variety of randomly-assembled spaceships for treasure, loot and fame!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/401710/header.jpg?t=1724179628', 0, 0, NULL);
INSERT INTO games VALUES (49153, 401760, 'Drone Swarm', 'Drone Swarm is a very unique take on tactical games. Control 32,000 drones in quick, fast-paced fights. Combine your swarm abilities and counter constantly evolving attacks of your opponents. Survive varying enemy waves, get upgrades to your swarm, and make it to the next system alive!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/401760/header.jpg?t=1704198503', 1, 0, NULL);
INSERT INTO games VALUES (49129, 401810, 'Poi', 'Poi is a 3D platformer featuring two kids on a grand adventure to unravel the mysteries of the Milky Way Globe. Explore uncharted lands, compete in challenge levels, meet quirky characters and defeat comical creatures on a journey to become a Master Explorer.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/401810/header.jpg?t=1707598524', 0, 0, NULL);
INSERT INTO games VALUES (49134, 402020, 'The Park®', 'Set in a creepy amusement park hiding a dark and sinister secret, The Park is a first-person psychological horror experience focused on exploration and storytelling.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/402020/header.jpg?t=1708367139', 0, 0, NULL);
INSERT INTO games VALUES (49136, 402040, 'The Guest', '''The Guest'' is a gloomy adventure full of enigmas where the exploration of your surroundings comes to prominence; puzzles, secrets and riddles will help you discover who has locked you in this somber hotel room and most importantly, why.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/402040/header.jpg?t=1619774882', 0, 0, NULL);
INSERT INTO games VALUES (49137, 402060, 'Californium', 'Taking the form of a first-person experience of a bad trip, Californium pays homage to sci-fi legend Philip K. Dick by transporting you into the life of a writer searching for his own identity. Explore, solve the riddles and conduct your investigation. Will you find what’s behind the simulacra ?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/402060/header.jpg?t=1727787771', 0, 0, NULL);
INSERT INTO games VALUES (49139, 402120, 'Deathstate: Abyssal Edition', 'Deathstate is a roguelike bullet hell adventure set in a bizarre world of dimensional exploration. Play as a number of unique characters trying to discover the fate of Professor Elinberg who opened a portal to the void. Are you ready to venture deep into the abyss?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/402120/header.jpg?t=1572362427', 0, 0, NULL);
INSERT INTO games VALUES (49140, 402130, 'FlatOut 4: Total Insanity', 'FlatOut 4: Total Insanity™, where reckless driving has never been this much fun. FlatOut 4: Total Insanity™ blends everything everyone has ever loved about FlatOut into one offering. Gamers will also be introduced to all new and exciting features, game modes, and vehicles which will soon become personal favorites.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/402130/header.jpg?t=1739636648', 0, 0, NULL);
INSERT INTO games VALUES (49142, 402160, 'Star Command Galaxies', 'Take command in the ultimate starship simulator: Star Command Galaxies. Become a Captain, recruit your crew, customize and upgrade your starship, battle alien vessels, teleport to away missions and repel boarding invaders in this real-time strategy simulation adventure from indie studio Warballoon.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/402160/header.jpg?t=1729281192', 0, 0, NULL);
INSERT INTO games VALUES (49144, 402180, 'Sakura Swim Club', 'In Sakura Swim Club, follow the story of Kaede, just your average guy. Upon transferring to a new school, he meets two beautiful girls in the swim club. Things haven''t gone well for the swim club lately, but with Kaede''s help, that all changes.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/402180/header.jpg?t=1667502326', 0, 0, NULL);
INSERT INTO games VALUES (49148, 402260, 'Dead Secret', 'Dead Secret is a first-person horror mystery set in rural Kansas in 1965. A reclusive professor is dead and it’s up to you to crack the case before you become the next victim. Investigate the murder and explore the story Time Magazine called “captivating” and “deeply creepy” .', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/402260/header.jpg?t=1727305586', 0, 0, NULL);
INSERT INTO games VALUES (49121, 402310, 'Overfall', 'Set sail in Overfall, a whimsical roguelike turn-based RPG of diplomacy and danger. Recruit unlikely heroes, forge alliances or crush your foes across ever-shifting seas to find a lost king. Every run is fresh with procedural worlds, permanent death, branching story encounters, and hand-drawn art.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/402310/header.jpg?t=1740744846', 0, 0, NULL);
INSERT INTO games VALUES (49122, 402330, 'Press X to Not Die', 'A ridiculous live-action B-movie adventure you will never forget! You wake up to find your town in chaos. Everyone has gone crazy and is just attacking each other! A cryptic message is the secret to survival-- Press X to not die!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/402330/header.jpg?t=1747726154', 0, 0, NULL);
INSERT INTO games VALUES (49125, 402530, 'The Last Door: Season 2 - Collector''s Edition', 'In Season 2 of The Last Door, the search for his missing client will bring psychiatrist John Wakefield deeper into a conspiracy of darkness and closer to the heart of madness than ever before.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/402530/header.jpg?t=1700829755', 0, 0, NULL);
INSERT INTO games VALUES (49127, 402570, 'Atlas Reactor', 'SEASON 6 NOW LIVE! The battle for Atlas continues as a hot (some might even say fiery) new freelancer enters the scene.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/402570/header.jpg?t=1561741026', 1, 0, NULL);
INSERT INTO games VALUES (49109, 402620, 'Kindred Spirits on the Roof', 'During lunch one day, Toomi Yuna meets two &quot;Kindred Spirits&quot; on the roof of her school. When they insist she help them nurture young love, Yuna finds herself playing &quot;yuri cupid&quot; to six unique and adorable couples. Can she remain aloof or will the promise of a &quot;yuritopia&quot; reach her too?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/402620/header.jpg?t=1747412718', 0, 0, NULL);
INSERT INTO games VALUES (49112, 402710, 'Osiris: New Dawn', 'Osiris: New Dawn is an unforgiving near future space survival game with a cinematic feel and elements of horror. Play as a Mission Specialist in single or multiplayer to build your planetary base, pilotable vehicles, and controllable drones as you explore a dangerous solar system far from Earth.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/402710/header.jpg?t=1745496432', 0, 0, NULL);
INSERT INTO games VALUES (49113, 402750, 'Giant Machines 2017', 'Take control over seven of the biggest industrial machines in the world. During the 14 mission campaign you will punch through the snows of Greenland, plow the steppes of Wyoming and travel all the way to sunny Florida. Your hard work will be completed by launching a space shuttle into space.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/402750/header.jpg?t=1618229445', 0, 0, NULL);
INSERT INTO games VALUES (49117, 402880, 'Age of Barbarian Extended Cut', 'Age of Barbarian Ex is an action hack ''n ''slash game inspired to 80s, fantasy and sword-and-sorcery genre. Muscular barbarians, scantily clad girls, hordes of bloodthirsty monsters, a lot of gore, a pretty epic story and an addictive soundtrack! What''s best in life?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/402880/header.jpg?t=1738166381', 0, 0, NULL);
INSERT INTO games VALUES (49102, 403180, 'Draw a Stickman: EPIC 2', 'Imagination is the key, as you enter a magical storybook full of mystery and wonder, unusual creatures, and enigmatic puzzles! Create your own original Stickman and then watch it come to life in DRAW A STICKMAN: EPIC 2! Jump in to this action-packed adventure that allows for endless creativity!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/403180/header.jpg?t=1588968640', 1, 0, NULL);
INSERT INTO games VALUES (49103, 403190, 'Planetbase', 'Guide a group of space settlers trying to establish a base on a remote planet. Grow food, collect energy, mine resources, survive disasters and build a self-sufficient colony in a harsh and unforgiving environment.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/403190/header.jpg?t=1743274197', 0, 0, NULL);
INSERT INTO games VALUES (49107, 403290, 'Burly Men at Sea', 'A branching folktale misadventure about a trio of large, bearded fishermen. Shape a custom tale that begins again where it ends, through waters where lurk creatures from Scandinavian folklore.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/403290/header.jpg?t=1728423364', 1, 0, NULL);
INSERT INTO games VALUES (49079, 403400, 'ARCADE GAME SERIES: DIG DUG', 'First appearing in arcades in 1982, Dig Dug finally comes to Steam! Control Dig Dug to make underground tunnels and inflate or crush the enemies!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/403400/header.jpg?t=1654680019', 0, 0, NULL);
INSERT INTO games VALUES (49080, 403410, 'ARCADE GAME SERIES: Ms. PAC-MAN', 'Developed in America and first released in 1981, Ms. PAC-MAN finally comes to Steam! Move Ms. PAC-MAN up, down, left, and right to avoid the ghosts and gobble up all the Pac-Dots!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/403410/header.jpg?t=1654680064', 0, 0, NULL);
INSERT INTO games VALUES (49081, 403430, 'ARCADE GAME SERIES: GALAGA', 'First appearing in arcades in 1981, the masterpiece GALAGA finally comes to Steam! Move the fighter left and right and destroy the waves of incoming aliens!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/403430/header.jpg?t=1580375648', 0, 0, NULL);
INSERT INTO games VALUES (49085, 403560, 'Eaten Alive', 'Eaten Alive is a Point and Click, Adventure, Horror game with Puzzle and Mystery game-play elements. Take control of ''Mia'' six years after the apocalypse began, the dead don''t stay dead and the earth is in a permanent state of darkness. This game contains adult themes.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/403560/header.jpg?t=1447378097', 0, 0, NULL);
INSERT INTO games VALUES (49086, 403590, 'Klepto', 'Welcome to Klepto where there''s no place like a burglarized home. In this burglary simulation you''ll explore, terrorize and loot your way to success in a variety of open-world sandbox neighborhoods. **VR is NOT required for this game.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/403590/header.jpg?t=1483746730', 0, 0, NULL);
INSERT INTO games VALUES (49087, 403640, 'Dishonored 2', 'Reprise your role as a supernatural assassin in Dishonored 2. Declared a “masterpiece” by Eurogamer and hailed “a must-play revenge tale” by Game Informer, Dishonored 2 is the follow up to Arkane’s 1st-person action blockbuster &amp; winner of 100+ ''Game of the Year'' awards, Dishonored.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/403640/header.jpg?t=1726161101', 0, 0, NULL);
INSERT INTO games VALUES (49092, 403700, 'Zero Punctuation: Hatfall - Hatters Gonna Hat Edition', 'HATFALL is a high-energy game of skill and hat-wearing born from Zero Punctuation, the hit online video series from The Escapist, created by the man behind ZP, Ben ''Yahtzee'' Croshaw.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/403700/header.jpg?t=1448033332', 0, 0, NULL);
INSERT INTO games VALUES (49066, 403830, 'The Consuming Shadow', 'The Consuming Shadow is a procedural survival horror adventure in which you must explore the land, fight your way through randomly-generated dungeons and try to stay sane in your quest to save the world from the invading Ancients.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/403830/header.jpg?t=1448084885', 0, 0, NULL);
INSERT INTO games VALUES (49070, 403940, 'Dungelot: Shattered Lands', 'Dungelot: Shattered Lands takes you on an epic roguelike dungeon-crawler adventure to defeat zombie cows, splat giant evil mushrooms, and generally get back home in one piece. Deceptively simple, ever so addictive.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/403940/header.jpg?t=1725623359', 0, 0, NULL);
INSERT INTO games VALUES (49071, 403950, 'Conquest of Elysium 4', 'Conquest of Elysium 4 is a quick turn based fantasy strategy game with a touch of rogue-like. The game is full of depth, details and monsters. There are also a huge number of factions, each with its own unique gameplay and magic rituals.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/403950/header.jpg?t=1713538862', 0, 0, NULL);
INSERT INTO games VALUES (49072, 403970, 'The Dwarves', 'A few heroes are facing hundreds of foes – are you even able to lead the coolest fantasy people to victory against the dark hordes? Explore a vast world, fight tactical real-time battles, and experience the fantastic story based on the bestseller &quot;The Dwarves&quot;.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/403970/header.jpg?t=1727857917', 0, 0, NULL);
INSERT INTO games VALUES (49075, 404040, 'Lords of Magic: Special Edition', 'Urak, once peaceful, is now a land of darkness, chaos and death. The people yearn for a champion to drive away the forces of evil. That champion is you.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/404040/header.jpg?t=1579791461', 0, 0, NULL);
INSERT INTO games VALUES (49064, 404200, 'WARTILE', 'Wartile is a cool-down based strategy game in which you control a warband of Viking figurines in a miniature universe inspired by Norse mythology. Unravel its secrets and rein the powers of the gods.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/404200/header.jpg?t=1748630392', 0, 0, NULL);
INSERT INTO games VALUES (49051, 404530, 'Voxel Turf', 'Voxel Turf is a block based urban sandbox. Build cities, blow up buildings, complete missions or fight for territory. Build a real estate empire, or perhaps just drive around and blow stuff up. Its your choice!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/404530/header.jpg?t=1568446688', 0, 0, NULL);
INSERT INTO games VALUES (49053, 404590, 'Vikings - Wolves of Midgard', 'Vikings – Wolves of Midgard takes you to the Shores of Midgard, a world based upon the mythology and history of the Vikings, but with a fantasy twist. Battle the fearsome Jotan, hordes of terrifying undead monstrosities and the beasts of Ragnarok, as you strive to survive the growing cold of Fimbulwinter.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/404590/header.jpg?t=1730815839', 0, 0, NULL);
INSERT INTO games VALUES (49054, 404620, 'The Political Machine 2016', 'Run for President of the United States as one of dozens of past or present presidential candidates or create your own ideal candidate. Give speeches, go on talk shows, hire unsavory operatives, and do whatever it takes to win on election day.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/404620/header.jpg?t=1578339666', 0, 0, NULL);
INSERT INTO games VALUES (49058, 404680, 'Hob', 'Transform the world of Hob! A new action-adventure from Runic Games, the award-winning studio behind Torchlight I and II. It''s your chance. Make it home.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/404680/header.jpg?t=1729011187', 1, 0, NULL);
INSERT INTO games VALUES (49059, 404690, 'This Book Is A Dungeon', 'Auto-cannibalism. Demonic Seduction. Occult Rituals. Bloodfeasting Worms. This dark, horrific Twine-based dungeon crawler pairs edgy interactive fiction with grisly pixel art and light RPG elements. Navigate this sprawling narrative-driven labyrinth bristling with otherworldly doom.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/404690/header.jpg?t=1748869327', 0, 0, NULL);
INSERT INTO games VALUES (49032, 404820, 'Ragdoll Runners', 'Ragdoll Runners is a physics-based athletics game where you control independently the two legs of an athlete in 8 events of different types: sprint, long jump, triple jump, hurdles. Play against the computer, with 3 friends on the same PC or online against other players'' records.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/404820/header.jpg?t=1469796954', 0, 0, NULL);
INSERT INTO games VALUES (49041, 405180, '123 Slaughter Me Street', 'Welcome everyone to 123 Slaughter Me Street! A criminal on the run, you find yourself evading police as you make your escape down an alley. You see an old fire escape and scramble up to the roof of an abandoned building; you are safe here. As the patrol cars drive past, you slip into the shadows.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/405180/header.jpg?t=1722570409', 0, 0, NULL);
INSERT INTO games VALUES (49016, 405290, 'Charlie Murder', 'It’s a punk rock apocalypse! Team up with your friends to lead embattled punk rock band Charlie Murder in their epic quest to save the world from rival death metalers Gore Quaffer and their legions of evil.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/405290/header.jpg?t=1666985760', 0, 0, NULL);
INSERT INTO games VALUES (49017, 405310, 'LEGO® MARVEL''s Avengers', 'Avengers Assemble! The best-selling LEGO® MARVEL videogame franchise returns with a new action-packed, Super Hero adventure.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/405310/header.jpg?t=1745541213', 0, 0, NULL);
INSERT INTO games VALUES (49021, 405500, 'Dangerous Golf', 'Not your traditional Golf game. Humorous destruction and over the top trickshots are the way to score big. Smash up the toilets, make a big mess in the Kitchen, destroy priceless antiques in the Palace. This is golf played indoors where the more expensive the object the higher its game value.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/405500/header.jpg?t=1626416166', 0, 0, NULL);
INSERT INTO games VALUES (49026, 405610, 'Flight of the Paladin', 'Flight of the Paladin is a fast-paced top-down shooter where you play as a knight of valor and light vanquishing the nightmarish creatures of darkness. Featuring multiple game modes, Steam Achievements and Leaderboards!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/405610/header.jpg?t=1547591746', 0, 0, NULL);
INSERT INTO games VALUES (49027, 405640, 'Pony Island', 'Pony Island is a suspense puzzle game in disguise. You are in limbo, trapped in a malevolent and malfunctioning arcade machine devised by the devil himself. It is not a game about ponies.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/405640/header.jpg?t=1720913107', 0, 0, NULL);
INSERT INTO games VALUES (49030, 405710, 'Staxel', 'Grow your farm, meet the villagers, and join your friends online in building your world.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/405710/header.jpg?t=1659690961', 0, 0, NULL);
INSERT INTO games VALUES (138385, 405820, 'Turok', 'A world where time has no meaning - and evil knows no bounds. Torn from a world long gone, the time traveling warrior Turok has found himself thrust into a savage land torn by conflict.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/405820/header.jpg?t=1591116079', 0, 0, NULL);
INSERT INTO games VALUES (49006, 405830, 'Turok 2: Seeds of Evil', 'Having defeated the Campaigner, Turok throws the Chronocepter into a waiting volcano to destroy it. Unfortunately the blast awakens an even deadlier force - The Primagen. Once again a Turok is tasked with restoring peace to the land and stopping the Primagen from merging Earth with the nether world.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/405830/header.jpg?t=1726511823', 0, 0, NULL);
INSERT INTO games VALUES (49008, 405900, 'Disgaea PC', 'The hotheaded Laharl seeks to be the next big Overlord in the Netherworld...and will destroy anyone that gets in his way! With his devious vassal Etna and the angel trainee Flonne as his unlikely allies, he must battle his way to supremacy and retake the throne in this over-the-top RPG adventure!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/405900/header.jpg?t=1732584484', 1, 0, NULL);
INSERT INTO games VALUES (48989, 406080, 'Ant War: Domination', 'Emerge from the ant hill with a handful of ants and a dream... to conquer the world. Train your ants, manage their daily workload, and travel across the town in search of new land. Sharpen your pincers and be ready to fight everyone from beetles and slugs, to the town police and the army!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/406080/header.jpg?t=1727981363', 0, 0, NULL);
INSERT INTO games VALUES (48993, 406130, 'DarkMaus', 'DarkMaus is an indie action RPG with challenging, skill-based combat that punishes careless play.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/406130/header.jpg?t=1455644929', 0, 0, NULL);
INSERT INTO games VALUES (48994, 406150, 'Refunct', 'Refunct is a peaceful, short first-person platformer about restoring a vibrant world.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/406150/header.jpg?t=1695751806', 1, 0, NULL);
INSERT INTO games VALUES (48996, 406170, 'Vortex: The Gateway', 'Vortex: The Gateway is an open world survival horror game with two game modes. If you want to survive then be alert, sneak, build and fight. Meanwhile life back on Earth changes dramatically. What changes? You will get bits of information through your adventure. Prepare for the worst!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/406170/header.jpg?t=1572873834', 0, 0, NULL);
INSERT INTO games VALUES (48998, 406290, 'Twilight Struggle', 'Twilight Struggle is a two-player game where players play as either the US or USSR during the Cold War. Using actual events from history, players must plan out their strategies in order to obtain world dominance. Play Twilight Struggle and change the course of history.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/406290/header.jpg?t=1647893895', 0, 0, NULL);
INSERT INTO games VALUES (49001, 406350, 'KartKraft™', 'No seatbelts, no suspension, no downforce. This is pure head to head racing at 90mph...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/406350/header.jpg?t=1739801558', 0, 0, NULL);
INSERT INTO games VALUES (48973, 406550, 'Umineko When They Cry - Question Arcs', 'Umineko When They Cry is the 2nd series of Sound Novel released by 07th Expansion. The steam version features renewed character sprites which is swappable from the classic art.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/406550/header.jpg?t=1725518183', 0, 0, NULL);
INSERT INTO games VALUES (48977, 406720, 'Alekhine''s Gun', 'It is the height of the Cold War, a time of global uncertainty and civil unrest. You are Agent Alekhine, a highly skilled Russian assassin, driven by a moral compass that leads you headfirst into a covert operation unsanctioned by the country you previously served.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/406720/header.jpg?t=1721993879', 0, 0, NULL);
INSERT INTO games VALUES (48983, 406850, 'Crush Your Enemies', 'Go back to the awesome glory days of Real-Time Strategy games. Crush Your Enemies has everything you love of the genre: Planning, choosing different types of units, managing resources, taking enemy territory and outwitting your opponent with the ingenious formations of your men.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/406850/header.jpg?t=1728639686', 0, 0, NULL);
INSERT INTO games VALUES (48985, 406870, 'Eventide: Slavic Fable', 'Explore the exciting world of slavic legends!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/406870/header.jpg?t=1581942581', 1, 0, NULL);
INSERT INTO games VALUES (48954, 406970, 'The Uncertain: Last Quiet Day', 'The Uncertain is an story-driven adventure game set in a post-apocalyptic world. Experience the mysterious vibe of each of carefully explored locations, solve diverse puzzles, make fateful decisions and discuss intriguing matters to find out the whole truth being kept from you.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/406970/header.jpg?t=1742919382', 0, 0, NULL);
