INSERT INTO games VALUES (48817, 411560, 'Reveal The Deep', 'Reveal The Deep is a short exploration game set in the wreck of a 19th century steamship. Navigate through expansive levels, uncovering the stories of the ship''s demise and it''s passengers. Keep your nerve, your wits about you, and prepare to reveal the secrets of the deep.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/411560/header.jpg?t=1613734760', 0, 0, NULL);
INSERT INTO games VALUES (48818, 411570, 'Zombie Exodus', 'It starts with a daring escape from a zombie-infested city; it ends at Zombie Exodus, when a horde of zombies swarms outlying settlements like locusts.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/411570/header.jpg?t=1734026157', 0, 0, NULL);
INSERT INTO games VALUES (48830, 411830, 'SENRAN KAGURA SHINOVI VERSUS', 'The non-PC buxom shinobi of SENRAN KAGURA, the brawler series that’s as over-the-top with its fighting mechanics as it is with its gratuitous depictions of female ninja in various forms of undress, invade the PC realm for the first time in HD and 60fps glory.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/411830/header.jpg?t=1741904625', 0, 0, NULL);
INSERT INTO games VALUES (48800, 411960, 'TY the Tasmanian Tiger', 'G''day, Mate. Explore the wilds of Australia with TY the Tasmanian Tiger, the charming Aussie platformer.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/411960/header.jpg?t=1732762435', 0, 0, NULL);
INSERT INTO games VALUES (48801, 411970, 'TY the Tasmanian Tiger 2', 'STREWTH! It''s time to go back Down Under with this fully remastered version of TY the Tasmanian Tiger 2: Bush Rescue. Rang, bite, smash and glide your way around the Australian Outback and stop the evil machinations of the diabolical BOSS CASS in this open world adventure.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/411970/header.jpg?t=1732762479', 0, 0, NULL);
INSERT INTO games VALUES (48802, 411980, 'TY the Tasmanian Tiger 3', 'CRIKEY! TY is back with a brand new adventure, in this fully remastered version of TY the Tasmanian Tiger 3: Night of the Quinkan. Pick up your rangs; pull on your shorts, and prepare to rescue the SOUTHERN RIVERS from a brand new threat - the QUINKAN...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/411980/header.jpg?t=1732762521', 0, 0, NULL);
INSERT INTO games VALUES (48804, 412020, 'Metro Exodus', 'Flee the shattered ruins of the Moscow Metro and embark on an epic, continent-spanning journey across the post-apocalyptic Russian wilderness. Explore vast, non-linear levels, lose yourself in an immersive, sandbox survival experience, and follow a thrilling story-line that spans an entire year in the greatest Metro adventure yet.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/412020/header.jpg?t=1725363713', 1, 0, NULL);
INSERT INTO games VALUES (48805, 412050, 'HordeZ', 'If you are looking for a on-rails arcade experience that blends between classics like Doom, Left 4 dead and House of the Dead then we got you covered! Fast and simple gameplay that will bring you into a creepy world of zombies and demons. Show your skills to the world through our global leadboard system!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/412050/header.jpg?t=1715713537', 0, 0, NULL);
INSERT INTO games VALUES (48787, 412460, 'Villagers', 'Villagers is a beautifully illustrated and richly detailed town-building game where you build a thriving community using the people and resources around you. Success or failure depends on your ability to create a town that can grow and prosper, and overcome the harsh realities of medieval life!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/412460/header.jpg?t=1498133639', 0, 0, NULL);
INSERT INTO games VALUES (48791, 412520, 'Evil Defenders', 'Evil Defenders is a fun, frenetic defense game: build and upgrade your towers, сast spells to repel enemy forces, use special landmarks and defend the Lands of Evil from invaders! Feel free to play the game in many different ways through unique tower upgrades, a deep skill tree and 100 in-game achievements.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/412520/header.jpg?t=1557994874', 0, 0, NULL);
INSERT INTO games VALUES (48799, 412670, 'Bullet Heaven 2', 'Bullet Heaven 2 is a bullet-hell shoot-em-up inspired by games like Touhou and Jamestown. It''s all about shooting every cute thing that moves, while dodging hundreds of shiny bullets per second!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/412670/header.jpg?t=1720824433', 0, 0, NULL);
INSERT INTO games VALUES (48773, 412740, 'Audioshield', 'Block the beats! Audioshield puts you at the point of impact for every hit in your songs. Block incoming orbs with your shields and feel the music. Works with any song!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/412740/header.jpg?t=1568409238', 0, 0, NULL);
INSERT INTO games VALUES (48775, 412770, 'Boogeyman', 'Live your childhood nightmare and try to survive against the Boogeyman. Equipped with only your flashlight, survive each night until the morning light.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/412770/header.jpg?t=1717081475', 0, 0, NULL);
INSERT INTO games VALUES (48776, 412830, 'STEINS;GATE', 'Developed by 5pb. and Nitroplus, STEINS;GATE was awarded Famitsu magazine''s coveted annual Game of Excellence award and was voted one of the most emotionally charged “tear-inducing games” ever made, in a Famitsu poll.　It is a gripping and moving Visual Novel, which has already spawned manga and anime adaptations.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/412830/header.jpg?t=1715703398', 0, 0, NULL);
INSERT INTO games VALUES (48777, 412880, 'Drift Streets Japan', 'Racing Game about Illegal Night Street Racing. Nice Cars and Advanced Engine Tuning. Most Realistic and Best Physics. Most Quality Graphics. Drive the Large Japan Highway with traffic. Feel the Real experience, try to drift with car cockpit camera.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/412880/header.jpg?t=1742680508', 0, 0, NULL);
INSERT INTO games VALUES (135361, 413150, 'Stardew Valley', 'You''ve inherited your grandfather''s old farm plot in Stardew Valley. Armed with hand-me-down tools and a few coins, you set out to begin your new life. Can you learn to live off the land and turn these overgrown fields into a thriving home?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/413150/header.jpg?t=1711128146', 1, 0, NULL);
INSERT INTO games VALUES (48762, 413410, 'Danganronpa: Trigger Happy Havoc', 'Investigate murders, search for clues and talk to your classmates to prepare for trial. There, you''ll engage in deadly wordplay, going back and forth with suspects. Dissect their statements and fire their words back at them to expose their lies! There''s only one way to survive—pull the trigger.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/413410/header.jpg?t=1731312195', 0, 0, NULL);
INSERT INTO games VALUES (48763, 413420, 'Danganronpa 2: Goodbye Despair', 'Jabberwock Island—You and your classmates were ready for fun in the sun until Monokuma returned to restart his murderous game! Trapped in a kill-or-be-killed situation, your only hope rests in solving the island’s mysteries.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/413420/header.jpg?t=1731312064', 0, 0, NULL);
INSERT INTO games VALUES (48752, 413710, 'Blood and Gold: Caribbean!', '''Blood &amp; Gold: Caribbean!'' is a blend of economic strategy and open-world RPG, set in the pirate era of XVII Century Caribbean. The game is based on the significantly improved Mount &amp; Blade: Warband engine.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/413710/header.jpg?t=1576832149', 0, 0, NULL);
INSERT INTO games VALUES (48744, 414080, 'Life is Hard', 'Life is Hard is a godsim town simulator game developed by a two-man-team. Your main aim here is to manage your town. Expand your domain, prevent famine, make war, trade with others, attract new people. Make history!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/414080/header.jpg?t=1628984719', 0, 0, NULL);
INSERT INTO games VALUES (48746, 414120, 'Modbox', 'Modbox is a multiplayer game creation sandbox for Desktop+VR', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/414120/header.jpg?t=1665704693', 0, 0, NULL);
INSERT INTO games VALUES (48749, 414190, 'Junk Jack', 'Make the world truly yours in Junk Jack, a relaxing sandbox experience focused on building and improving your home. Discover new planets, tame and breed creatures, cook foods, collect animal companions, farm exotic plants, collect fish, grow flowers, play with your friends!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/414190/header.jpg?t=1579003834', 0, 0, NULL);
INSERT INTO games VALUES (48734, 414340, 'Hellblade: Senua''s Sacrifice', 'From the makers of Heavenly Sword, Enslaved: Odyssey to the West, and DmC: Devil May Cry, comes a warrior’s brutal journey into myth and madness. Set in the Viking age, a broken Celtic warrior embarks on a haunting vision quest into Viking Hell to fight for the soul of her dead lover.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/414340/header.jpg?t=1726851372', 1, 0, NULL);
INSERT INTO games VALUES (48739, 414510, '5089: The Action RPG', '5089 is a deep &amp; complex action RPG featuring strong sandbox roots. VR is supported, but not required. Watch the tutorial &amp; VR videos next to the trailer! Everything is procedurally generated, like terrain, enemies, weapons, items &amp; quests. Planet Xax''s war rages on... how is that possible?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/414510/header.jpg?t=1568814385', 0, 0, NULL);
INSERT INTO games VALUES (48742, 414660, 'Vampire Legends: The True Story of Kisilova', 'Discover the source of dreadful evil!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/414660/header.jpg?t=1580998651', 1, 0, NULL);
INSERT INTO games VALUES (48720, 414700, 'Outlast 2', 'Outlast 2 introduces you to Sullivan Knoth and his followers, who left our wicked world behind to give birth to Temple Gate, a town, deep in the wilderness and hidden from civilization. Knoth and his flock are preparing for the tribulations of the end of times and you’re right in the thick of it.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/414700/header.jpg?t=1618944453', 0, 0, NULL);
INSERT INTO games VALUES (48721, 414720, 'Astrox: Hostile Space Excavation', 'Exiled to a deep space mining sector, you are left with a crappy ship, a laser, and a small mining beam. It is up to you to survive by working your way through the galaxy. Mine asteroids, refine and trade the ore, buy upgrades for your ship, hunt pirates... you get it.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/414720/header.jpg?t=1451287512', 0, 0, NULL);
INSERT INTO games VALUES (48723, 414740, 'RAID: World War II', 'RAID: World War II is an action-packed four player cooperative shooter set during a time when the Nazi war machine was still winning, and hope was in short supply.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/414740/header.jpg?t=1747224652', 0, 0, NULL);
INSERT INTO games VALUES (48727, 414920, 'Corgi Warlock', 'Corgi Warlock is a 1-4 player side-scrolling fantasy action game, where one brave Corgi will take on the Skeleton Bunny King''s army! Against the power of Narwhals, Fencing Bears, and Crazed Unicorns, it takes more than your average Corgi to survive the King''s onslaught... it takes a CORGI WARLOCK.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/414920/header.jpg?t=1534379698', 0, 0, NULL);
INSERT INTO games VALUES (48728, 414950, 'Star Nomad 2', 'A space trader &amp; combat sim meets squad-RPG, large scale conquest, choice driven gameplay with fluid &amp; punchy tactical real-time combat set in a dynamic open-world sandbox.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/414950/header.jpg?t=1592045253', 0, 0, NULL);
INSERT INTO games VALUES (48731, 415030, 'One More Dungeon', 'One More Dungeon is a first person shooter roguelike with procedurally generated levels and pixel-art graphics.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/415030/header.jpg?t=1662105004', 0, 0, NULL);
INSERT INTO games VALUES (48713, 415170, 'Engare', 'Engare is a game about motion and geometry. Part puzzle game, part drawing tool, Engare is all about your geometric imagination. It’s a meditation on the dynamics of simple machines and the beauty buried deep within repeating motion.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/415170/header.jpg?t=1677570385', 0, 0, NULL);
INSERT INTO games VALUES (48715, 415200, 'Motorsport Manager', 'Have you got what it takes to become the manager of a high-performance motorsport team? Motorsport Manager is a highly detailed, best-in-class management game for fans of motorsport. You’ll hire the drivers, build the cars and embed yourself in the dynamic world of racing.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/415200/header.jpg?t=1711458333', 0, 0, NULL);
INSERT INTO games VALUES (48719, 415350, 'Shooting Stars!', 'This game is the answer to one of the most important questions in life: “I can haz lazer kitty?“ Yes you can!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/415350/header.jpg?t=1568814601', 1, 0, NULL);
INSERT INTO games VALUES (48697, 415420, 'Nyan Cat: Lost In Space', 'Play with the most celebrated flying cat in human history. Drink milk, eat ice-cream, collect coins, buy gorgeous boosts, fly like a superhero (sorry... supercat), jump onto platforms made of cake, avoid angry dogs, and discover the infinite space.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/415420/header.jpg?t=1478250717', 0, 0, NULL);
INSERT INTO games VALUES (48699, 415590, 'Earthfall', 'NOW AVAILABLE! When the Earth falls to an extra-terrestrial invasion, humanity becomes an endangered species. Earthfall is a four-player cooperative shooter that challenges players to survive hordes of ruthless alien drones and their inscrutable masters.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/415590/header.jpg?t=1542219242', 1, 0, NULL);
INSERT INTO games VALUES (48700, 415600, 'Kart Racing Pro', 'Kart Racing Pro is a realistic karting simulator. The aim is to create a software useful as a training tool for real drivers, based on a scratch built physics engine that accurately simulates kart dynamics and setup options.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/415600/header.jpg?t=1594311317', 0, 0, NULL);
INSERT INTO games VALUES (48704, 415740, 'OmniBus', 'OmniBus is next-to-last gen physics game about the most powerful bus in the universe that can’t stop or even slow down for reasons incomprehensible to the simple human mind.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/415740/header.jpg?t=1587058079', 0, 0, NULL);
INSERT INTO games VALUES (48708, 415850, 'BAD END', 'It''s rumored that those who play ''BAD END''- a Visual Novel will die in REAL LIFE if they make the wrong decision in the game itself.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/415850/header.jpg?t=1749022888', 0, 0, NULL);
INSERT INTO games VALUES (48665, 415880, 'Disc Jam', 'A fast-paced action-sports game that pits 2-4 players against each other in a frantic combination of air hockey and tennis. Players scramble to retrieve and throw a glowing disc while unleashing devastating abilities and defending their end zone.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/415880/header.jpg?t=1720056456', 0, 0, NULL);
INSERT INTO games VALUES (48668, 415920, 'Voidspire Tactics', 'An indie turn-based Tactics RPG with a heavy emphasis on exploration, character progression, and highly tactical combat. Create your own deeply customizable party of Warriors, Sorcerers, and Shiftcloaks to take on the Spire!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/415920/header.jpg?t=1666991852', 0, 0, NULL);
INSERT INTO games VALUES (48669, 415950, 'Yohjo Simulator', 'This is a little girl simulator. You control Yagi, a 3rd grade elementary school girl, and wander around town. There''s no goal in this game. You need to decide the goal for yourself. It''s the same as in life. This is an amazingly realistic simulator.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/415950/header.jpg?t=1632161928', 0, 0, NULL);
INSERT INTO games VALUES (128371, 416000, 'Orange Season', 'Make your farmer’s dream come true in Orange Season. With your parent’s help, you’ve finally saved enough money to buy a plot of land in the charming farmer’s village of Orange Town. Build a thriving farm as you grow crops, raise animals, fish, and mine materials to establish your farm in town.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/416000/header.jpg?t=1729760398', 1, 0, NULL);
INSERT INTO games VALUES (48675, 416060, 'Westboro', '2039. Water is no longer environmentally sustainable supply. The complicated and unstable situation resulted in violent uprisings among themiddle-class across the globe. The world approaches its first week in state of emergency...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/416060/header.jpg?t=1538246820', 0, 0, NULL);
INSERT INTO games VALUES (48676, 416080, 'The Odyssey: Winds of Athena', 'As the Greek Goddess Athena, control the wind, seas, and air to guide the hero Odysseus home from the Trojan Wars. The incredibly realistic water current simulation will amaze and challenge you, as you use your powers to protect the Hero''s fleet.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/416080/header.jpg?t=1574484228', 0, 0, NULL);
INSERT INTO games VALUES (48682, 416190, 'Vehicle Simulator', 'Vehicle Simulator is an open world flying/sailing simulator with accurate physics and dynamics, simulating well the various boats, planes and land vehicles included. The game allows the user to modify and experiment with scenery making and vehicle design by way of extreme modability, with a large library of existing mods and add-ons.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/416190/header.jpg?t=1663856845', 0, 0, NULL);
INSERT INTO games VALUES (48684, 416210, 'Block''hood', 'Block’hood is a neighborhood-building simulator that celebrates the diversity and experimentation of cities and the unique ecosystems within them. Budding city planners will have access to 200+ building blocks to combine and to create unique neighborhoods and discover the implications of their designs.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/416210/header.jpg?t=1721868419', 1, 0, NULL);
INSERT INTO games VALUES (48645, 416380, 'The Hurricane of the Varstray -Collateral hazard-', '【About &quot;The Hurricane of the Varstray&quot;】&quot;The Hurricane of the Varstray&quot; is a vertically scrolling shoot''em up with a SF story: in the distant future, to defend the Earth against the invasion of mystery mechanical structures, 4 girls head to &quot;the Varstray sector,&quot; far away from the Earth and considered as the v', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/416380/header.jpg?t=1727761865', 0, 0, NULL);
INSERT INTO games VALUES (48651, 416590, 'Emily Wants To Play', 'It’s 11pm and the last house on your route. The windows are boarded up, the yard is overgrown, but the lights are on and the front door is open… strange place to deliver a pizza. You’re getting soaked from the rain, so you hesitantly step inside the house. You shouldn’t have done that.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/416590/header.jpg?t=1737656106', 1, 0, NULL);
INSERT INTO games VALUES (48652, 416600, 'Full Metal Furies', 'From the creators of Rogue Legacy comes a &quot;true-cooperative&quot; action RPG. FULL METAL FURIES puts an emphasis on team play with a unique combat system where everyone is important. Play on the couch, alone or with friends, or make it an online party for up to four players!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/416600/header.jpg?t=1689347261', 1, 0, NULL);
INSERT INTO games VALUES (48655, 416640, 'Diabolical', 'As a criminal mastermind, choose a lair, rob a bank, hire a minion, and steal the world''s largest ball of aluminum foil! Or, destroy the world. FINE.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/416640/header.jpg?t=1734114840', 0, 0, NULL);
INSERT INTO games VALUES (48657, 416680, 'Zombie Night Terror', 'Prepare yourself for the most thrilling night of your life! Something strange has happened and people everywhere are turning into blood thirsty walking corpses. But guess who’s the brains behind this hungry undead army? YOU! So spread this pandemic and wipe humanity off the planet.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/416680/header.jpg?t=1582640712', 1, 0, NULL);
INSERT INTO games VALUES (48662, 416770, 'SquareCells', 'SquareCells is an ambient logic puzzle game.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/416770/header.jpg?t=1667313768', 0, 0, NULL);
INSERT INTO games VALUES (48663, 416790, 'The Metronomicon: Slay The Dance Floor', 'A Rhythm Role-Playing Game! Fight party crashing monsters with the power of music! Level your party and upgrade your gear while dancing to the beat of some groovin'' tunes. Grab a friend and combine forces in all game modes in The Metronomicon: Slay the Dance Floor!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/416790/header.jpg?t=1746833580', 0, 0, NULL);
INSERT INTO games VALUES (48635, 416870, 'Kitty Powers'' Love Life', 'From the creators of ‘Kitty Powers’ Matchmaker’, ‘Kitty Powers'' Love Life’ is a brand new take on the community/relationship sim genre, with a very British twist. Build and run your very own village for newly matched couples, under the watchful eye of your boss, outrageous drag queen Kitty Powers!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/416870/header.jpg?t=1667128773', 0, 0, NULL);
INSERT INTO games VALUES (48641, 417290, 'Ghost of a Tale', 'Ghost of a Tale is an action-RPG game in which you play as Tilo, a mouse and minstrel thrown into a perilous adventure. Through stealth and cunning you’ll be able to explore the secrets of Dwindling Heights Keep and navigate its dangers.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/417290/header.jpg?t=1667033370', 0, 0, NULL);
INSERT INTO games VALUES (48631, 417750, 'Left Alone', 'Left Alone plunges you into a first-person psychological horror journey, where darkness and memories intertwine. As secrets emerge from shadows, use your wits to solve puzzles and explore haunting, forgotten locations. Every step echoes with the past; can you face the truths that await?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/417750/header.jpg?t=1736250445', 0, 0, NULL);
INSERT INTO games VALUES (48613, 417860, 'Emily is Away', 'Emily is Away is an interactive story. Create a screenname and choose your path through the branching narrative.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/417860/header.jpg?t=1619107266', 0, 1, NULL);
INSERT INTO games VALUES (48614, 417880, 'Everybody''s Gone to the Rapture', 'Featuring a beautiful, detailed open-world and a haunting soundtrack, Everybody’s Gone to the Rapture is non-linear storytelling at its best.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/417880/header.jpg?t=1717621115', 1, 0, NULL);
INSERT INTO games VALUES (48620, 418030, 'Subsistence', 'Subsistence is a sandbox, first person, solo or co-op, PvE open-world survival game. Struggle through changing seasons to build a base, develop technology and gear-up in the hostile environment. Defend yourself from wildlife, the elements and AI hunters (who also build bases in the world).', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/418030/header.jpg?t=1734721808', 1, 0, NULL);
INSERT INTO games VALUES (48621, 418040, 'hocus', 'perspective illusion puzzle based on M.C. Escher drawings and impossible shapes', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/418040/header.jpg?t=1627169404', 0, 0, NULL);
INSERT INTO games VALUES (48623, 418070, 'Turbo Pug', 'It''s time to unleash your inner pug! Turbo Pug is a casual runner with difficult, random, procedurally generated levels. Enjoy random weather and try to avoid getting zapped by lightning. Unlock new costumes for your pug and new characters to play as. Please try not to squish your pug!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/418070/header.jpg?t=1474358256', 0, 0, NULL);
INSERT INTO games VALUES (48596, 418180, 'Tempest: Pirate Action RPG', 'Tempest is a Pirate Open World Action RPG where you rove the seas across three continents filled with dozens of colonies and forts, hundreds of quests and countless ships to plunder. Customize your ship, trade, challenge fellow pirates and face mythical monsters such as the Kraken and Leviathan!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/418180/header.jpg?t=1738596157', 0, 0, NULL);
INSERT INTO games VALUES (48597, 418190, 'Helen''s Mysterious Castle', 'A young girl with a hidden past sets off on an epic and mysterious journey in hope of learning more about her own origins in this beautifully rendered, classic-style RPG adventure.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/418190/header.jpg?t=1574409844', 0, 0, NULL);
INSERT INTO games VALUES (48598, 418240, 'Shadow Tactics: Blades of the Shogun', 'Shadow Tactics is a hardcore tactical stealth game set in Japan around the Edo period. A new Shogun seizes power over Japan and enforces nationwide peace. In his battle against conspiracy and rebellion, he recruits five specialists with extraordinary skills for assassination, sabotage and espionage.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/418240/header.jpg?t=1749228498', 1, 0, NULL);
INSERT INTO games VALUES (48599, 418250, 'Polaris Sector', 'Can anyone build an empire in a place like this? Other factions are naturally suspicious of newcomers and may wage war at the first sign of unidentified craft. Here, a natural death is an uncommon luxury.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/418250/header.jpg?t=1726824221', 0, 0, NULL);
INSERT INTO games VALUES (48603, 418300, 'Wick', 'Wick is a survival horror game where ghost stories are brought to life. Explore a local legend about the long lost children in the woods who can still be seen... but only by those who dare to enter alone by candlelight.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/418300/header.jpg?t=1667238123', 0, 0, NULL);
INSERT INTO games VALUES (48604, 418340, 'RWBY: Grimm Eclipse', 'RWBY: GRIMM ECLIPSE is a 4 player, online co-op, hack and slash game based upon Rooster Teeth’s international hit series RWBY.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/418340/header.jpg?t=1539886295', 0, 0, NULL);
INSERT INTO games VALUES (48606, 418370, 'Resident Evil 7 Biohazard', 'Fear and isolation seep through the walls of an abandoned southern farmhouse. &quot;7&quot; marks a new beginning for survival horror with the “Isolated View” of the visceral new first-person perspective.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/418370/header.jpg?t=1728436752', 1, 0, NULL);
INSERT INTO games VALUES (48608, 418440, 'Tick Tock Isle', 'Strike is inadvertently transported into the past while attempting to repair a mysterious, abandoned clock tower.  Endeavoring to return to the future, Strike must fix both the time machine and the island’s dysfunctional family who are responsible for much of the clock’s disrepair.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/418440/header.jpg?t=1747536686', 0, 0, NULL);
INSERT INTO games VALUES (48609, 418460, 'Rising Storm 2: Vietnam', 'Red Orchestra Series'' take on Vietnam: 64-player MP matches; 20+ maps; US Army &amp; Marines, PAVN/NVA, NLF/VC; Australians and ARVN forces; 50+ weapons; 4 flyable helicopters; mines, traps and tunnels; Brutal. Authentic. Gritty. Character customization. And napalm in the morning.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/418460/header.jpg?t=1731945332', 1, 0, NULL);
INSERT INTO games VALUES (48611, 418530, 'Spelunky 2', 'Spelunky 2 builds upon the unique, randomized challenges that made the original a roguelike classic, offering a huge adventure designed to satisfy players old and new. Meet the next generation of explorers as they find themselves on the Moon, searching for treasure and missing family.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/418530/header.jpg?t=1663719294', 1, 0, NULL);
INSERT INTO games VALUES (48588, 418620, 'The TakeOver', 'The Takeover is a side-scrolling beat''em up inspired by 90''s classics such as Streets of Rage and Final Fight. Battle solo or alongside a friend in local co-op while listening to awesome tunes from Little V Mills, Richie Branson, James Ronald and industry legend Yuzo Koshiro!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/418620/header.jpg?t=1576924056', 0, 0, NULL);
INSERT INTO games VALUES (48590, 418650, 'Space Pirate Trainer', 'Space Pirate Trainer is the official trainer for wannabe space pirates in VR. Pick up your blasters, put on your sneakers, and dance your way into the Space Pirate Trainer hall of fame.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/418650/header.jpg?t=1667031863', 0, 0, NULL);
INSERT INTO games VALUES (48592, 418910, 'Idle Civilization', 'Take command of a pair of villagers and help them build a mighty civilization that will spread across the world and conquer it. Idle Civilization is a civilization builder management game where you will oversee the growth of your people into a mighty kingdom through building, research, warfare, religion, diplomacy, culture, heroic...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/418910/header.jpg?t=1466630966', 0, 0, NULL);
INSERT INTO games VALUES (48594, 418950, 'DreadOut: Keepers of The Dark', 'DreadOut: Keepers of the Dark is a new standalone horror game that takes place in the DreadOut universe. In this missing chapter, you will help Linda face the challenges of the DreadOut world with even more dangers lurking within.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/418950/header.jpg?t=1733398712', 0, 0, NULL);
INSERT INTO games VALUES (48586, 419460, 'That Dragon, Cancer', 'An immersive, narrative videogame that retells Joel Green’s 4-year fight against cancer through about two hours of poetic, imaginative gameplay that explores themes of faith, hope and love.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/419460/header.jpg?t=1456855096', 0, 0, NULL);
INSERT INTO games VALUES (48580, 419480, 'Starpoint Gemini Warlords', 'Strategy from the front lines! Starpoint Gemini Warlords combines 3rd person capital spaceship combat with 4X strategy and RPG gameplay elements. Build mighty war fleets and send them into battle or lead them into combat yourself. Become the Warlord and conquer the Gemini system!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/419480/header.jpg?t=1732638771', 0, 0, NULL);
INSERT INTO games VALUES (138982, 419520, 'Lifeless', 'Immerse yourself in the post-apocalyptic co-op world of Lifeless, where base building and crafting are key. Collect weapons, gear, and food as you embark on thrilling missions to level up in a vast open world. But stay alert—relentless zombies lurk around every corner!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/419520/123d9757a97c470fdc56c6683aea4edb96827520/header.jpg?t=1749555056', 0, 1, NULL);
INSERT INTO games VALUES (48558, 420000, 'Home Design 3D', 'Home Design 3D is the reference interior design and home decor application, allowing you to draw, create and visualize your floor plans and home ideas.Design your dream projects simply and easily, in 2D and/or 3D. Get a good idea of your next home or simply have fun!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/420000/header.jpg?t=1674822778', 1, 0, NULL);
INSERT INTO games VALUES (48561, 420060, 'Candle', 'Candle is an adventure with challenging puzzles. Play as Teku, a young novice on a dangerous journey to rescue his tribe''s shaman from the evil tribe of the Wakcha. But the way is littered with sinister traps and difficult obstacles.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/420060/header.jpg?t=1736856305', 1, 0, NULL);
INSERT INTO games VALUES (48563, 420100, 'CLANNAD Side Stories', 'Delve further into the world of CLANNAD and experience the stories beyond the original visual novel adventure. Known as CLANNAD Hikari Mimamoru Sakamichi de in Japan, This Steam version features high resolution assets and is translated into English for the very first time.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/420100/header.jpg?t=1656892484', 0, 0, NULL);
INSERT INTO games VALUES (48564, 420110, 'NEKOPARA Vol. 2', 'Business is booming for La Soleil, the patisserie run by Kashou Minaduki with his two catgirls, Chocola and Vanilla, his sister Shigure, and the Minaduki family''s four catgirl sisters.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/420110/header.jpg?t=1656892360', 0, 0, NULL);
INSERT INTO games VALUES (48569, 420180, 'Chronicle of Innsmouth', 'Chronicle of Innsmouth is a point''n''click adventure inspired by Lucas'' retro classics from the 90s and H.P. Lovecraft''s works. Investigate, gather info and solve enigmas to unveil the secrets of the cursed town of Innsmouth, a forsaken place surrounded by horrifying rumors.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/420180/header.jpg?t=1665046333', 0, 0, NULL);
INSERT INTO games VALUES (48572, 420290, 'Blackwake', 'Blackwake is a multiplayer naval FPS focused on teamwork and cooperation. Fire the cannons, sink enemy ships or board them with firearms and steel.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/420290/header.jpg?t=1709060640', 0, 1, NULL);
INSERT INTO games VALUES (48547, 420440, 'Atlantic Fleet', 'Turn based tactical and strategic naval combat. Atlantic Fleet puts you in command of the Allies or Kriegsmarine (German Navy) in the longest military campaign of WWII, The Battle of the Atlantic.Take command of surface ships, submarines as well as carrier and land based aircraft in the deadly struggle for control of Atlantic shipping...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/420440/header.jpg?t=1731023234', 0, 0, NULL);
INSERT INTO games VALUES (48549, 420520, 'Lost Technology', 'Lost Technology is a simulation game in which over 100 characters comprising a total of 12 different factions battle to conquer each other’s territories. The faction chosen at the beginning will determine the conversations and events that occur throughout the game between the player and the other factions.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/420520/header.jpg?t=1728472109', 0, 0, NULL);
INSERT INTO games VALUES (48550, 420530, 'OneShot', 'OneShot is a surreal top down Puzzle/Adventure game with unique gameplay capabilities. You are to guide a child through a mysterious world on a mission to restore its long-dead sun. The world knows you exist.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/420530/header.jpg?t=1747673318', 1, 0, NULL);
INSERT INTO games VALUES (48552, 420560, 'Firefighting Simulator - The Squad', 'Firefighting Simulator lets you experience what it means to fight fires up close as an active part of a major US city''s firefighting crew - together with up to 3 friends in the co-op multiplayer- or in the single player mode.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/420560/header.jpg?t=1741101935', 1, 0, NULL);
INSERT INTO games VALUES (48554, 420660, 'Burnin'' Rubber 5 HD', 'Burnin'' Rubber 5 HD is a remastered update of one of the most played action games on the web. Unlock over 30 challenges, 50 cars and multiple explosive weapons. Master 3 different challenge modes and hone your skills to take on the biggest end boss ever.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/420660/header.jpg?t=1709910094', 0, 0, NULL);
INSERT INTO games VALUES (48556, 420740, 'The Deed', 'A keenly dark twist on the traditional murder mystery setting, The Deed is an Adventure/RPG game about getting away with murder. Arran Bruce, the rightful heir to Dunshiel House, returns home to settle a score with his estranged family.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/420740/header.jpg?t=1748879179', 0, 0, NULL);
INSERT INTO games VALUES (48534, 420840, 'BLARP!', 'BLARP! is a fun-filled physics game build for the HTC Vive. BLARP! uses our intuitive understanding of motions and physics to create an active / addictive experience that is playable by anyone who has ever swung a racket, played with a yoyo, or held a rope.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/420840/header.jpg?t=1459814635', 0, 0, NULL);
INSERT INTO games VALUES (48539, 420930, 'CHKN', 'Behold, the miracle of life… packed into cubes! Create fantastic creatures in an open-world sandbox game like no other. Explore, craft, and survive—all with the help of your very own creations.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/420930/header.jpg?t=1707592917', 0, 1, NULL);
INSERT INTO games VALUES (48542, 420980, 'Army Gals', 'Can you survive with three women in the middle of nowhere. In this Survival, Romance Visual Novel adventure.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/420980/header.jpg?t=1711226044', 0, 0, NULL);
INSERT INTO games VALUES (48543, 421040, 'Plantera', 'In Plantera you build your own garden and watch it grow with new plants, bushes, trees and animals. As you play and expand your garden you will attract Helpers, round blue creatures that will help you with your harvesting tasks.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/421040/header.jpg?t=1738938729', 1, 0, NULL);
INSERT INTO games VALUES (48544, 421050, 'Deponia Doomsday', 'Can you change Deponia''s fate? Do you have what it takes to change Rufus'' past, present and future without accidently destroying the whole planet? Fight time itself in this action-packed, platypus-tastic and insanely hilarious story.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/421050/header.jpg?t=1734630557', 0, 0, NULL);
INSERT INTO games VALUES (48546, 421120, 'Samorost 3', 'Samorost 3 is an exploration adventure and puzzle game from the award-winning creators of Machinarium and Botanicula. Travel across space to nine unique worlds teeming with colorful challenges, creatures and surprises to discover, brought to life with beautiful artwork, sound and music.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/421120/header.jpg?t=1743606050', 1, 0, NULL);
INSERT INTO games VALUES (48527, 421170, 'Indivisible', 'Indivisible is a hand drawn action RPG platformer from Lab Zero, creators of the critically acclaimed Skullgirls! Set in a huge fantasy world, Indivisible tells the story of Ajna, a fearless girl with a rebellious streak who sets out on a quest to save everything she knows from being destroyed.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/421170/header.jpg?t=1677520885', 1, 0, NULL);
