INSERT INTO games VALUES (48520, 421740, 'Goetia', 'Goetia is a point &amp; click adventure where you play the ghost of a young lady. You are Abigail. Abigail Blackwood.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/421740/header.jpg?t=1726574540', 0, 0, NULL);
INSERT INTO games VALUES (48522, 421810, 'OH! RPG!', 'Heroes always win! But what happens to those who don''t? Play as unique and colorful characters as the world comes to an end after our heroes'' utter defeat.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/421810/header.jpg?t=1730473739', 0, 0, NULL);
