INSERT INTO games VALUES (48498, 422810, 'River City Ransom: Underground', 'Alex and Ryan must take to the streets to help a new crop of fighters. You''ll earn money, unlock moves, and upgrade your skills in a sprawling city. This modern take on an old classic features over 500 unique street fighting moves, dozens of weapons, and fun online multiplayer modes.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/422810/header.jpg?t=1573536636', 0, 0, NULL);
INSERT INTO games VALUES (48499, 422860, 'Holodance', 'Released into Early Access as one of the first two VR rhythm games April 5, 2016, Holodance constantly evolved and continues to evolve: Punch orbs with your hands, slice drops with laserblades, shoot drones with guns or dance with dragons, with lots of different kinds of beatmaps!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/422860/header.jpg?t=1609413124', 0, 0, NULL);
