INSERT INTO games VALUES (48502, 422910, 'Creeper World: Anniversary Edition', 'Imagine an enemy that is everywhere and moves like a giant, organic mass across the map. Imagine your base and your people surrounded by a blanket of crushing destruction from all directions. Your only hope, well what hope? Then you take the high ground and pound this enemy into oblivion.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/422910/header.jpg?t=1688931505', 0, 0, NULL);
