INSERT INTO games VALUES (48466, 423490, 'Air Missions: HIND', 'Air Missions: HIND is an action combat flight simulator based on the Russian Mi-24 Hind assault helicopter. You will be deployed to the battlefield either on your own or with a friend.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/423490/header.jpg?t=1503144339', 0, 0, NULL);
