INSERT INTO games VALUES (48469, 423590, 'The Little Acre', 'While searching for his father, Aidan travels to a strange new world. Lily - his heroic daughter - sets off after him. Fully voiced and with hand-drawn animations, The Little Acre is a lovingly crafted adventure developed by Pewter Games with Executive Producer Charles Cecil.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/423590/header.jpg?t=1637664791', 0, 0, NULL);
