INSERT INTO games VALUES (48443, 424280, 'Iron Snout', 'Iron Snout is a fast, colorful and brutal fighting game in which you will be helping a piglet fight for its life against hordes of wolves.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/424280/header.jpg?t=1729102840', 0, 1, NULL);
INSERT INTO games VALUES (48445, 424370, 'Wolcen: Lords of Mayhem', 'Carve your path in this Hack’n’Slash free from class boundaries. Purify a world shattered by corruption, and uncover the grim secrets and forgotten horrors lurking in the shadows of this forsaken land as you rise in Power. Your Inner aspect beckons—will you answer?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/424370/header.jpg?t=1731003158', 1, 0, NULL);
