INSERT INTO games VALUES (48430, 424840, 'Little Nightmares', 'Take on the role of Six, a lone child lost in a massive metal vessel known as the Maw, surrounded by dangerous, distorted versions of adults. You’ll need to do your best to escape in one piece or your fate will be worse than you ever dared dream.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/424840/header.jpg?t=1730127751', 1, 0, NULL);
INSERT INTO games VALUES (48438, 425210, 'Shadwen', 'Shadwen is a 3rd person stealth-action game where the only rule is to remain unseen. Stay hidden - or the ruthless guards will kill you on sight!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/425210/header.jpg?t=1725011383', 0, 0, NULL);
INSERT INTO games VALUES (48439, 425220, 'One Piece Burning Blood', 'The game that all One Piece fans have been waiting for. One Piece Burning Blood is a dynamic and colourful new fighting game featuring the world’s most famous pirate: Monkey D. Luffy.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/425220/header.jpg?t=1701310074', 1, 0, NULL);
INSERT INTO games VALUES (48422, 425580, 'The Room Two', 'Unique events transport you to the halls of a long-forgotten crypt. The only means of escape lies locked within a stone pedestal, along with a note from your mysterious ally. His words promise assistance, but only serve to entice you into a compelling world of mystery and exploration.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/425580/header.jpg?t=1646758355', 0, 0, NULL);
