INSERT INTO games VALUES (48401, 425770, 'Answer The Question', 'This game is called answer the question you get infinite questions its a game about math. If you are studying and want to play a game choose this one this game has addition so start playing and get smart!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/425770/header.jpg?t=1533207997', 0, 0, NULL);
INSERT INTO games VALUES (48407, 426000, 'HunieCam Studio', 'In HunieCam Studio players take control of a sleazy cam girl operation. Rake in stacks of filthy internet money and attract as many disgusting fans as you can in this fast paced, click happy and thoroughly perverted take on the business tycoon / management sim genre!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/426000/header.jpg?t=1709077221', 0, 0, NULL);
INSERT INTO games VALUES (48398, 426310, 'Perception', 'An award-winning narrative thriller about a blind woman’s journey to uncover the truth about the mansion from her nightmares, or else become one of its victims.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/426310/header.jpg?t=1601655486', 0, 0, NULL);
INSERT INTO games VALUES (48399, 426330, 'MetaHuman Inc.', 'As the CEO of a corporation that sells superpowers to the highest bidder, you''ll harness dark magic and travel through time to inflate your stock prices!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/426330/header.jpg?t=1734114747', 0, 0, NULL);
INSERT INTO games VALUES (48389, 426630, 'Bubsy Two-Fur', 'Bubsy returns in the first authorized digital release of his first two games! What could paws-ibly go wrong?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/426630/header.jpg?t=1726253711', 0, 0, NULL);
INSERT INTO games VALUES (48390, 426690, 'Narcissu 10th Anniversary Anthology Project', '&quot;Life is like a waiting room, except people don''t leave in the order they enter.&quot; Narcissu is a thought provoking visual novel series about terminal illness, living, dying, and the relationship between those leaving and those left behind. There are no miracles, no heroes, no villains in this story.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/426690/header.jpg?t=1726605219', 0, 0, NULL);
INSERT INTO games VALUES (48391, 426790, 'Grow Up', 'Leaping from mind-boggling heights, bouncing off Champolines, soaring inches from floating islands, BUD can do it all - that look of mild terror, that’s his daredevil face. Help the adorable little robot collect MOM’s scattered ship parts and return them to the moon.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/426790/header.jpg?t=1694556130', 0, 0, NULL);
INSERT INTO games VALUES (48381, 427030, 'Xuan-Yuan Sword: The Gate of Firmament', 'The “Xuan-Yuan Sword” is an epic oriental RPG series with 25 years of history.It elaborates on the very heart of this series, the idea of &quot;one, looking at the same thing from different angles, may come to different conclusions. &quot; through a variety of historical incidents in different times.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/427030/header.jpg?t=1728970889', 0, 0, NULL);
INSERT INTO games VALUES (135495, 427100, 'Fernbus Simulator', 'The world of coach drivers awaits you! Drive along motorways and country roads to the bus stations in over 40 cities in Germany. Thanks to the cooperation with FlixBus and true-to-the-original MAN buses, you will experience the game world in a realistic way.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/427100/header.jpg?t=1734607106', 0, 0, NULL);
INSERT INTO games VALUES (48383, 427190, 'DEAD RISING®', 'You are Frank West. A hard-edged photojournalist hellbent on investigating the mystery at Willamette Mall. It''s swarming with zombies. You have 72 hours. Chop ''till you drop!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/427190/header.jpg?t=1701219182', 0, 0, NULL);
INSERT INTO games VALUES (48384, 427240, 'Cosmic Trip', 'Cosmic Trip is an award-winning real-time strategy VR game. Build a base, command a flying drone army, and attack/defend hostile enemies on strange alien planets.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/427240/header.jpg?t=1725382268', 1, 0, NULL);
INSERT INTO games VALUES (48385, 427250, '8-Bit Armies', '8-Bit Armies is a retro Real-Time Strategy game. With a colorful, blocky voxel art style, 8-Bit Armies is Petroglyph''s most fast-paced, friendly, and accessible RTS game to date. Featuring a campaign of 25 single-player missions, 12 co-op missions, multiplayer and skirmish modes.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/427250/header.jpg?t=1667950296', 0, 0, NULL);
INSERT INTO games VALUES (48386, 427290, 'Vampyr', 'London, 1918. You are newly-turned Vampyr Dr. Jonathan Reid. As a doctor, you must find a cure to save the city’s flu-ravaged citizens. As a Vampyr, you are cursed to feed on those you vowed to heal.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/427290/header.jpg?t=1727792911', 0, 0, NULL);
INSERT INTO games VALUES (131971, 427410, 'Abiotic Factor', 'Abiotic Factor is a survival crafting experience for 1-6 players set in the depths of an underground research facility. Caught between paranormal containment failure, a military crusade, and chaos from a dozen realms, the world’s greatest minds must survive against the universe’s biggest threats.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/427410/header.jpg?t=1749248979', 0, 0, NULL);
INSERT INTO games VALUES (48373, 427470, 'Democracy 3 Africa', 'Democracy 3: Africa is the new standalone ''re-imagining'' of the hit political strategy game ''Democracy 3''. Set entirely in countries on the continent of Africa, D3:A puts you in charge of these countries and challenges you to stay in power whilst fixing each country''s problems, improving the quality of life for your electorate, and...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/427470/header.jpg?t=1478025016', 0, 0, NULL);
INSERT INTO games VALUES (48374, 427490, 'Shadowhand: RPG Card Game', 'Shadowhand is a strategic RPG card game. Duel powerful enemies in 18th Century England with unique solitaire-style turn-based combat. Equip your character strategically to sneak, slice and blast through foes!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/427490/header.jpg?t=1739805452', 0, 0, NULL);
INSERT INTO games VALUES (48375, 427520, 'Factorio', 'Factorio is a game about building and creating automated factories to produce items of increasing complexity, within an infinite 2D world. Use your imagination to design your factory, combine simple elements into ingenious structures, and finally protect it from the creatures who don''t really like you.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/427520/header.jpg?t=1730307306', 1, 0, NULL);
INSERT INTO games VALUES (48377, 427570, 'Dawn of Andromeda', 'Dawn of Andromeda is a pausable, real-time 4X space strategy game providing an accessible, fun and immersive experience, introducing fresh ideas to the genre. Build your empire, colonize new planets, interact with other factions and characters, research technologies and build great fleets.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/427570/header.jpg?t=1599049257', 0, 0, NULL);
INSERT INTO games VALUES (48379, 427660, 'NightCry', 'NightCry is set on a cruise ship, and you have been invited along for the cruise of a (possibly short) lifetime. While your surroundings are luxurious and the guests are friendly, not everything is as it should be. The guests and the crew start to turn up dead, the victims of some foul murderer.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/427660/header.jpg?t=1707120082', 0, 0, NULL);
INSERT INTO games VALUES (48346, 427700, 'Zwei: The Ilvard Insurrection', 'In a world where magic and technology exist side by side, vampire princess Alwen must reclaim her ancestral castle and her magic alongside her unlikely ally, treasure hunter Ragna Valentine. They may make for an odd pair, but when they combine their talents, the sky’s the limit!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/427700/header.jpg?t=1732150962', 0, 0, NULL);
INSERT INTO games VALUES (48347, 427730, 'Who''s Your Daddy?!', 'Who''s Your Daddy is a casual multiplayer game featuring a clueless father attempting to prevent his infant son from certain death. Play with up to 7 of your friends, and test your parenting skills in a competitive setup with wacky physics and over 69 potentially ominous household items.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/427730/header.jpg?t=1738384540', 0, 0, NULL);
INSERT INTO games VALUES (48348, 427760, 'A Chair in a Room : Greenwater', 'Explore your surroundings as the protagonist of your own horror story as you immerse yourself in this tense VR thriller set in America’s Deep South. Navigate your way through your memories, piecing together the clues and puzzles, to solve the mystery of how you have awoken in the sinister Greenwater Institute, known only as Patient No.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/427760/header.jpg?t=1569944887', 0, 0, NULL);
INSERT INTO games VALUES (48351, 427810, 'CALENDULA', 'How to play a game that doesn''t want to be played? Calendula is an experimental meta game about trying to play a game. Use your logic to thrive against conventions and get surrounded by a dark atmosphere.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/427810/header.jpg?t=1483011894', 0, 0, NULL);
INSERT INTO games VALUES (48352, 427820, 'Hitman GO: Definitive Edition', 'Hitman GO is a simple to play, but difficult to master turn-based strategy game set in a stunning interpretation of the Hitman universe.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/427820/header.jpg?t=1699905509', 0, 0, NULL);
INSERT INTO games VALUES (48355, 427880, 'P.A.M.E.L.A.®', 'Explore, fight, and survive as an awakened sleeper, in a fallen utopian city ravaged by a horrific disease. With an array of hi-tech weapons, highly immersive UI, full-body awareness, and much more, P.A.M.E.L.A. delivers an intense and unforgiving survival experience.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/427880/header.jpg?t=1592627503', 0, 0, NULL);
INSERT INTO games VALUES (48357, 427910, 'Zavix Tower', 'Zavix Tower is an old-school, party-based, first-person CRPG with rogue-like elements, an upgrade-able and persistent town, and turn-based combat.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/427910/header.jpg?t=1502899420', 0, 0, NULL);
INSERT INTO games VALUES (48359, 427940, 'Industries of Titan', 'Create a sprawling industrial city. Compete with other rival corporations on Titan for resources, territory, and power. Seek victory via technology, influence, warfare, or the wealth extracted from your citizens. Stake your claim to the Industries of Titan in this innovative sim/strategy game!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/427940/header.jpg?t=1738282281', 1, 0, NULL);
INSERT INTO games VALUES (48360, 427950, 'The Withering', 'Have you ever thought or imagined how our world would look like after an apocalyptic event? What would we do if some of us were to survive? What world would we live in and what challenges would we face? What would you do?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/427950/header.jpg?t=1574036965', 0, 0, NULL);
INSERT INTO games VALUES (48362, 427980, 'Aozora Meikyuu', 'Aozora Meikyuu is a short Romance Visual Novel with focus on a cute girl.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/427980/header.jpg?t=1744391888', 0, 0, NULL);
INSERT INTO games VALUES (48366, 428080, 'Racket: Nx', 'Racquetball meets Breakout inside a giant pinball machine! Racket: Nx is a new kind of game that challenges the limits of what you can do with a racket and ball in VR.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/428080/header.jpg?t=1728901280', 1, 0, NULL);
INSERT INTO games VALUES (48334, 428340, 'Marmoset Hexels 3', 'Marmoset Hexels™ is a grid-based painting tool for vector art, pixel art, design, and animation. A geometric canvas grid lets artists create complex pixel and vector designs with the stroke of a brush.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/428340/header.jpg?t=1573072092', 0, 0, NULL);
INSERT INTO games VALUES (48336, 428370, 'Windlands', 'A first person grappling hook exploration game.Soar through the ruins of a fallen world and discover the secrets of the ancients. Designed with full Virtual Reality support for the HTC Vive and Oculus Rift, also works great in Non VR.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/428370/header.jpg?t=1728560087', 0, 0, NULL);
INSERT INTO games VALUES (48344, 428550, 'Momodora: Reverie Under The Moonlight', 'Momodora: Reverie Under The Moonlight is the fourth installment in the beloved Momodora series of 2D platformers. Unleash ravaging combos against a variety of formidable monsters and deftly dodge your way through a cursed land to seek audience with the Queen and dispel the evil that threatens all life.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/428550/header.jpg?t=1734415917', 1, 0, NULL);
INSERT INTO games VALUES (48307, 428660, 'Deliver Us The Moon', 'Deliver Us The Moon is a Sci-Fi thriller set in an apocalyptic near future, where Earth''s natural resources are depleted. A lone astronaut is sent to the moon on a critical mission to save humanity from extinction.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/428660/header.jpg?t=1743082153', 1, 0, NULL);
INSERT INTO games VALUES (48308, 428690, 'Youtubers Life', 'Become the most successful youtuber on the planet! Create videos, get subscribers, attend events, interact with your fans… and grow your channel. Live a youtuber’s life!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/428690/header.jpg?t=1739458749', 1, 0, NULL);
INSERT INTO games VALUES (48310, 428750, 'Neon Chrome', 'A masterful combination of top-down shooter and endless replayability with procedural levels. Blast your way through walls &amp; enemies with guns and cybernetic abilities. Install perks from cyber chambers and upgrade your character stats after each death. Can you stop the Overseer?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/428750/header.jpg?t=1714816134', 0, 0, NULL);
INSERT INTO games VALUES (48313, 428860, 'Red Haze', 'You know, my dear, it isn''t safe... To wander and creep while oh so weak. In the abandoned, the rotten, the decayed. Society has forgotten you; it won''t lift a finger for that which is tossed away. You''re just prey that the true prowlers who lay in shadows await to feast upon.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/428860/header.jpg?t=1712742551', 0, 0, NULL);
INSERT INTO games VALUES (48315, 428880, 'The Quest', 'The Quest is a beautifully hand-drawn open world role playing game with old school grid-based movement, turn based combat and intricate quests. Explore a huge world, full of challenging mysteries and dangerous monsters!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/428880/header.jpg?t=1745577207', 0, 0, NULL);
INSERT INTO games VALUES (48316, 428900, 'Linea, the Game', 'The goal of the game is to survive for more than 60 seconds on each level, dodging platforms and objects, listening to bitpop soundtracks. Four levels, online-records, achievements and trading cards are waiting for you.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/428900/header.jpg?t=1569104273', 0, 0, NULL);
INSERT INTO games VALUES (48325, 429050, 'Feed and Grow: Fish', 'Hunt and eat other fish - simply, grow into larger beasts!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/429050/header.jpg?t=1615737978', 0, 0, NULL);
INSERT INTO games VALUES (48290, 429330, 'Stikbold! A Dodgeball Adventure', 'Stikbold is a glorious and intense sport which will put your friendships to the test with fast-paced, hard-hitting and occasionally hilariously unfair action! Or play the co-op story mode to unlock the full roster of quirky sporting heroes and earn achievements.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/429330/header.jpg?t=1747738016', 0, 0, NULL);
INSERT INTO games VALUES (48296, 429470, 'Space Pilgrim Episode I: Alpha Centauri', 'Captain Gail Pilgrim has been flying starships since she was a kid, ferrying passengers between planets and space stations across the galaxy. She has no reason to expect that this latest trip to Alpha Centauri will be anything special, even if her passengers are a little more diverse than usual....', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/429470/header.jpg?t=1748878104', 0, 1, NULL);
INSERT INTO games VALUES (48298, 429490, 'Resilience Wave Survival', 'Resilience: Wave Survival is a physics based endless wave survival shooter. Explore to Search for Weapons and Ammo to help Defeat the Enemies, better find food and water too if you want to Survive for longer, but Beware of the Tripods stalking the lands.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/429490/header.jpg?t=1588266241', 0, 0, NULL);
INSERT INTO games VALUES (48300, 429530, 'Falcon 4.0', 'Falcon 4.0 breaks the sight-and-sound barrier with its cutting-edge graphics, realism, dynamic campaigns and multiplayer gameplay.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/429530/c7633d149013580bb5b6ab31d73f087a203a8b62/header.jpg?t=1748700098', 0, 0, NULL);
INSERT INTO games VALUES (48302, 429570, 'The Walking Dead: Michonne - A Telltale Miniseries', 'The Walking Dead: Michonne - A Telltale Miniseries stars the iconic, blade-wielding character from Robert Kirkman''s best-selling comic books.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/429570/header.jpg?t=1729702885', 0, 0, NULL);
INSERT INTO games VALUES (48269, 429610, 'The Emerald Maiden: Symphony of Dreams', 'Save your family from an ominous undersea facility!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/429610/header.jpg?t=1580113079', 1, 0, NULL);
INSERT INTO games VALUES (48270, 429620, 'Dungeon Rushers', 'A Heroic-Parody tactical RPG combining dungeon crawler’s gameplay and turn-based fights. Dive in an off-beat universe, manage your team and craft mighty gear to equip them! Build your own dungeon by hiding traps and monsters in your galleries, then challenge other players to clean it!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/429620/header.jpg?t=1727785864', 0, 0, NULL);
INSERT INTO games VALUES (48271, 429660, 'Tales of Berseria™', 'Players embark on a journey of self-discovery as they assume the role of Velvet, a young woman whose once kind demeanor has been replaced and overcome with a festering anger and hatred after a traumatic experience three years prior to the events within Tales of Berseria.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/429660/header.jpg?t=1701306268', 0, 0, NULL);
INSERT INTO games VALUES (48274, 429700, 'Squirbs', 'Squirbs is a challenging puzzle-platformer in which you control two cute blue Squirbs simultaneously with one set of controls. Looking for an awesomely difficult game? That''s Squirbs.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/429700/header.jpg?t=1492978565', 0, 0, NULL);
INSERT INTO games VALUES (48275, 429720, 'IMSCARED', '&quot;I need a Heart in order to open it&quot;', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/429720/header.jpg?t=1728130146', 0, 0, NULL);
INSERT INTO games VALUES (48276, 429780, 'Bunny Hop League', 'Inspired by old school first person shooters, Bunny Hop League takes you right back to the golden age of gaming, when hopping, strafing and surfing were all the rage.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/429780/header.jpg?t=1560789144', 0, 0, NULL);
INSERT INTO games VALUES (48278, 429830, 'Unseen Diplomacy', 'Unseen Diplomacy casts you as an elite member of The British Espionage Tactical Initiative, defeating the plans of evil-doers around the world. With a real-life obstacle course using every inch of your room-scale space, created by Steam VR, you will run and roll &amp; sneak your way through lairs.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/429830/header.jpg?t=1747819485', 0, 0, NULL);
INSERT INTO games VALUES (48257, 430020, 'Dance of Death', 'A mysterious and fascinating quest in Hidden Object genre.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/430020/header.jpg?t=1657310627', 0, 0, NULL);
INSERT INTO games VALUES (48258, 430070, 'Never Again', 'Never Again - Horror/first-person Quest. The main essence of the game is research locations and puzzles, plunging in the dramatic story of a little girl suffering from asthma.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/430070/header.jpg?t=1667031239', 0, 0, NULL);
INSERT INTO games VALUES (48263, 430210, 'Megaton Rainfall', 'Become an indestructible interdimensional superbeing in this first-person superhero game, and save Earth from an alien invasion. Be careful though - you are so powerful you can destroy entire skyscrapers (unintentionally) when you miss your otherworldly target...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/430210/header.jpg?t=1572861367', 1, 0, NULL);
INSERT INTO games VALUES (48242, 430960, 'Lucy -The Eternity She Wished For-', 'If there was a robot that could laugh, cry and smile. ...Does it have a soul?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/430960/header.jpg?t=1725007683', 1, 0, NULL);
INSERT INTO games VALUES (48244, 431120, 'Tethered', 'Thirteen unique islands await your guiding hand in this beautiful and engrossing real-time strategy game, unlike anything you have experienced before!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/431120/header.jpg?t=1491855883', 0, 0, NULL);
INSERT INTO games VALUES (48246, 431180, 'WolfQuest: Classic', 'LIVE THE LIFE OF A WILD WOLF! As a two-year-old gray wolf in Yellowstone National Park, hunt elk and moose, find a mate, and then establish a territory and raise your pups.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/431180/header.jpg?t=1743443109', 0, 0, NULL);
INSERT INTO games VALUES (48250, 431240, 'Golf With Your Friends', 'Why have friends if not to play Golf... With Your Friends! Nothing is out of bounds as you take on courses filled with fast paced, exciting, simultaneous mini golf for up to 12 players!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/431240/header.jpg?t=1748528368', 0, 0, NULL);
INSERT INTO games VALUES (48251, 431250, 'Mushroom Wars', 'Mushroom Wars is a dynamic real-time strategy game, where smart strategy meets furious action in epic PvP and PvE battles.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/431250/header.jpg?t=1725961335', 0, 0, NULL);
INSERT INTO games VALUES (48252, 431260, 'Cursed', 'Her future, as well as of the whole world depends on her ingenuity and bravery. The path to her fiancé is blocked by ghosts, dragons, demons and other creatures from beyond. Will she overcome her fears? Will she find her beloved? Play &quot;Cursed&quot; and find out!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/431260/header.jpg?t=1482755001', 0, 0, NULL);
INSERT INTO games VALUES (48220, 431450, 'Alchemist''s Awakening', 'Enter a world full of magic, mystery, beautiful landscapes and dangerous creatures. Build your own destiny, by yourself or with some friends, gather materials, use elements as attacks, recombine them into building blocks... and use your Alchemist''s power to give life to any shape you built.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/431450/header.jpg?t=1729018158', 0, 0, NULL);
INSERT INTO games VALUES (48228, 431590, 'Earn to Die 2', 'Earn to Die 2 is a 2D side-scrolling driving and upgrade game where you steer vehicles through a zombie apocalypse, literally smashing through zombie hordes along the way. Throughout the game you will unlock new vehicles, upgrading them into the ultimate zombie-smashing machines!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/431590/header.jpg?t=1748407923', 1, 0, NULL);
INSERT INTO games VALUES (48229, 431600, 'Automobilista', 'AUTOMOBILISTA places you in the driving seat of an advanced racing simulator, featuring elite brazilian racing series along with a wide range of racing vehicles and international tracks for a uniquely diverse motorsports experience.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/431600/header.jpg?t=1572643369', 0, 0, NULL);
INSERT INTO games VALUES (48233, 431650, 'Phoning Home', 'A tale of survival about two shipwrecked robots - ION and ANI - on their life-defining journey in this unique genre-mix of exploration, puzzle and survival.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/431650/header.jpg?t=1728543200', 0, 1, NULL);
INSERT INTO games VALUES (48235, 431700, 'Age of Fear 3: The Legend', 'Play as either Nairi, an imprisoned Dryad fighting for her freedom, or Gilrock, a drunken Dwarven Lord on a quest to restore his family''s honour (or just to kick some arse!). The Age of Fear series is a deep and complex turn-based strategy that fuses a tabletop wargame with RPG elements.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/431700/header.jpg?t=1730542191', 0, 0, NULL);
INSERT INTO games VALUES (48236, 431730, 'Aseprite', 'Aseprite is a pixel-art tool to create 2D animations, sprites, and any kind of graphics for games.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/431730/header.jpg?t=1748037227', 1, 0, NULL);
INSERT INTO games VALUES (48238, 431750, 'Iron Sea Defenders', 'Man the guns! The enemy fleet is on the horizon! Defend your fort from attacks – show your tactical skill.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/431750/header.jpg?t=1686114545', 0, 0, NULL);
INSERT INTO games VALUES (48239, 431770, 'Rivalry', 'Rivalry is a hotseat game where two players take turns moving their rag-doll character’s limbs and weapons until one is victorious. While the beginning stages of each game captures the strategic essence of swordplay, as damage and limbs are taken, the endgame turns rather Pythonesque.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/431770/header.jpg?t=1470025500', 0, 0, NULL);
INSERT INTO games VALUES (48195, 431930, 'Kabounce', 'Kabounce™ is the multiplayer pinball sport game where you are the ball. Experience fast-paced online arena combat, rack up combos and points and score to win. Take the action offline with single player time-attack parkour modes!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/431930/header.jpg?t=1603471014', 1, 0, NULL);
INSERT INTO games VALUES (48196, 431940, 'Wildfire', 'Master the elements in this stealth game where everything burns. Use your elemental powers to start fires, freeze water, and move earth as you outsmart superstitious enemies in this mischievous 2D stealth game.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/431940/header.jpg?t=1693977724', 1, 0, NULL);
INSERT INTO games VALUES (48198, 431960, 'Wallpaper Engine', 'Use stunning live wallpapers on your desktop. Animate your own images to create new wallpapers or import videos/websites and share them on the Steam Workshop!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/431960/header.jpg?t=1739211362', 1, 0, NULL);
INSERT INTO games VALUES (48199, 432010, 'World''s Dawn', 'Bring life back to a sleepy seaside village by building friendships, finding love, harvesting crops, tending livestock, competing in festivals, fishing, mining, discovering magical secrets and more!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/432010/header.jpg?t=1608679104', 0, 0, NULL);
INSERT INTO games VALUES (48201, 432100, 'Negligee', 'A story of love and lingerie as you are thrust into the role as manager of the shop ''Negligee'' alongside three beautiful women.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/432100/header.jpg?t=1725662080', 0, 0, NULL);
INSERT INTO games VALUES (48214, 432350, 'Epic Battle Fantasy 5', 'A turn-based RPG adventure, full of video game references, juvenile dialogue, and anime fanservice... and also strategic combat, monster catching, and tons of treasure hunting! Updated with tons of new content!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/432350/header.jpg?t=1720824507', 1, 0, NULL);
INSERT INTO games VALUES (48215, 432370, 'Sethian', 'Sethian is a sci-fi puzzle game in which you master a fictitious language. The only surviving speaker is an ancient computer. Does it hold the answers behind the disappearance of the Sethianese people?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/432370/header.jpg?t=1478711120', 0, 0, NULL);
INSERT INTO games VALUES (48160, 432980, 'INVERSUS Deluxe', 'INVERSUS is is a competitive and cooperative arcade shooter for 1 to 4 players online or on the couch. Fight for territory in a dynamic negative-space map where open paths for your team are the walls of your opponent''s team. Strategize and trap the enemy to win!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/432980/header.jpg?t=1745735041', 1, 0, NULL);
INSERT INTO games VALUES (48162, 433000, 'Lost Lands: The Golden Curse Collector''s Edition', 'Lost Lands: the Golden Curse is an adventurous hidden object game-quest with puzzles and mini-games scattered through the boundless spaces of the fantasy world – from the volcano valleys to the Druid forest, from the deep caves to the floating islands.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/433000/header.jpg?t=1678439047', 1, 0, NULL);
INSERT INTO games VALUES (48163, 433100, 'The Town of Light', '12 March 1938, Renée, 16, was ripped out of her world, her only fault was that of not knowing her place in the world.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/433100/header.jpg?t=1614236975', 0, 0, NULL);
INSERT INTO games VALUES (48167, 433170, 'Die Young', 'Kidnapped for no clear reason to a dazzling yet mysterious island on the Mediterranean Sea, a young girl has to find a way to escape. Armed with only her wits, agility, and the will to stay alive, she must make her getaway or Die Young.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/433170/header.jpg?t=1609754218', 0, 0, NULL);
INSERT INTO games VALUES (48171, 433280, 'Warlords Battlecry III', 'Warlords Battlecry III is the next installment in the award-winning Warlords Battlecry series. Builds upon the famous features of previous Battlecry titles such as the outstanding AI, innovative gameplay and hero system that has made this brand renowned throughout the RTS genre.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/433280/header.jpg?t=1681167161', 0, 0, NULL);
INSERT INTO games VALUES (48172, 433300, 'Marvel: Ultimate Alliance', 'Marvel Ultimate Alliance lets players create their ultimate team from the largest Super Hero alliance ever as they engage in an epic quest to determine the fate of the Marvel Universe.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/433300/header.jpg?t=1532625861', 0, 0, NULL);
INSERT INTO games VALUES (48173, 433320, 'Marvel: Ultimate Alliance 2', 'As Civil War is stirred, Iron Man leads the Pro-Registration side while Captain America spearheads the stand on Anti-Registration.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/433320/header.jpg?t=1532625846', 0, 0, NULL);
INSERT INTO games VALUES (48145, 433530, 'Heliborne Collection', 'Rotary-wing aviation and helicopter combat with a dynamic battlefield and the support of ground forces. Appreciated for MMO elements and an addictive gameplay loop. Use tactics and make strategic decisions or fly around and shoot in historically accurate maps.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/433530/header.jpg?t=1732096612', 0, 0, NULL);
INSERT INTO games VALUES (48146, 433550, 'DARQ: Complete Edition', 'DARQ tells the story of Lloyd, a boy who finds himself in the middle of a lucid nightmare. Unable to wake up, Lloyd has to face his fears and decipher the meaning of the dream.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/433550/header.jpg?t=1743034565', 1, 0, NULL);
INSERT INTO games VALUES (48150, 433600, 'A Legend of Luca', 'A Legend of Luca is a VR FPS Rogue-Like! Every run you explore vast dungeons as a freed slave caught in a war between gods. Fight hordes of monsters in search of powerful upgrade combinations to kill a god and unlock new classes.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/433600/header.jpg?t=1707945224', 0, 0, NULL);
INSERT INTO games VALUES (48121, 433850, 'Z1 Battle Royale', 'Z1 Battle Royale is a Free to Play, fast-paced, action arcade, competitive Battle Royale. Staying true to its &quot;King of the Kill&quot; roots, the game has been revamped and restored to the classic feel, look, and gameplay everyone fell in love with. Play solo, duos, or fives and be the last ones standing.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/433850/header.jpg?t=1579626820', 1, 1, NULL);
INSERT INTO games VALUES (48124, 433910, 'Neon Drive', 'Neon Drive is a slick retro-futuristic, ''80s inspired arcade game that will make your brain melt. You''ve been warned.From beautiful cityscapes and ocean roads to exploding enemy spaceships, Neon Drive has it all.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/433910/header.jpg?t=1668515112', 0, 0, NULL);
INSERT INTO games VALUES (48127, 433950, 'Bit Blaster XL', 'Bit Blaster XL is a fast-paced, retro arcade shoot ''em up (shmup) inspired by the classic quarter-munchers of the ‘80s. Easy to pick up, hard to put down, boost, dodge, shoot, and chase high scores in this addictive, old-school action game!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/433950/78163a0d17719e45ec372fffe960478bc84183cf/header.jpg?t=1745903625', 0, 0, NULL);
INSERT INTO games VALUES (48129, 434000, 'Paws - A Shelter 2 Game', 'Traverse a vast world as a young lynx cub. Paws – A Shelter 2 Game is a standalone, single player, adventure game with loss and friendship as its central themes. Venture out in the world and make your way home.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/434000/header.jpg?t=1747743452', 0, 0, NULL);
INSERT INTO games VALUES (48130, 434020, 'Last Hope - Tower Defense', 'Zombie Tower Defense: Join the ongoing war, in an open world, against the undead zombie horde. Choose between multiple powerful heroes all with unique epic gear and skills! With the wide variety of towers you can create your own perfect strategy.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/434020/header.jpg?t=1572618009', 0, 0, NULL);
INSERT INTO games VALUES (48131, 434030, 'Aerofly FS 2 Flight Simulator', 'Aerofly FS 2 Flight Simulator lets you explore the world of flying in a quality never seen before. Fly a large selection of highly detailed aircraft or a helicopter with interactive 3D cockpits. Aerofly FS 2 currently features over 200 airports in the south western USA and global elevation and satellite imagery.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/434030/header.jpg?t=1670005140', 0, 0, NULL);
INSERT INTO games VALUES (48132, 434050, 'Duke Nukem 3D: 20th Anniversary World Tour', 'Frag like it’s 1996 – this time with even more asses to kick! Join the world’s greatest action hero in Duke Nukem 3D: 20th Anniversary World Tour as he saves Earth once again, kicking alien ass and saving babes across the globe along the way.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/434050/header.jpg?t=1749246073', 0, 0, NULL);
INSERT INTO games VALUES (132185, 434170, 'The Jackbox Party Pack 3', 'The threequel to the party game phenomenon features the deadly quiz show Trivia Murder Party, the say-anything sequel Quiplash 2, the surprising survey game Guesspionage, the t-shirt slugfest Tee K.O., and the sneaky trickster game Fakin’ It.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/434170/header.jpg?t=1728584278', 0, 0, NULL);
INSERT INTO games VALUES (48086, 434210, 'It''s Spring Again', '&quot;It''s Spring Again&quot; - an educational game for children ages two and up. It uses game mechanics to teach children about the seasons.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/434210/header.jpg?t=1746808812', 0, 0, NULL);
INSERT INTO games VALUES (48090, 434250, 'Masked Shooters 2', 'Masked Shooters 2 puts you on the front line of a dangerous gunfight that can only end in victory or defeat; there will be no white flags to wave. As a covert ops soldier, you have access to advanced weapons that will blow your enemies away, if you know how to use them.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/434250/header.jpg?t=1706319897', 0, 0, NULL);
INSERT INTO games VALUES (48091, 434260, 'My Name is Mayo', 'This is a clicking adventure that simulates the real-life tapping of a Mayo Jar! You will unveil its story and (maybe) you will learn from it!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/434260/header.jpg?t=1561950401', 0, 0, NULL);
INSERT INTO games VALUES (48094, 434290, 'Typefighters (Steam Edition)', 'Typefighters is a competitive multiplayer game where two players battle each other using their typing skills. Its variety of modes does not only emphasise typing speed and correctness, but also other skills like reaction time, sustained attention, creativity, tactics and anticipating the opponents moves.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/434290/header.jpg?t=1667054237', 0, 0, NULL);
INSERT INTO games VALUES (48099, 434370, 'Buried: An Interactive Story', 'Buried is a playable, interactive story told through stunning photos, a haunting soundscape, and gripping text. You play the role of Roger Hastings, a logger who awakens to find his friends missing, uncovering something that should have stayed hidden...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/434370/header.jpg?t=1682187875', 0, 0, NULL);
INSERT INTO games VALUES (48101, 434420, 'The Chosen RPG', 'The Chosen is a heroic RPG. Will you be able to unravel the mysterious plot against you and become the Chosen?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/434420/header.jpg?t=1574484919', 0, 0, NULL);
INSERT INTO games VALUES (48103, 434460, 'Rock of Ages 2: Bigger & Boulder™', 'The greatest rock-racing, tower defense, art history game is back! Like the title says, Bigger &amp; Boulder cranks up the surrealism and gameplay with chaotic 4P multiplayer, new time periods, and improved graphics, physics, and destructibility powered by UE4 to be, well… BIGGER AND BOULDER.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/434460/header.jpg?t=1667562890', 0, 0, NULL);
INSERT INTO games VALUES (48112, 434570, 'Blood and Bacon', 'This Co-op Shooter , has Day and Night levels, multiple maps, players will take on 25 enemy types and numerous bosses, like Gargantuan Monsters and Minibosses every 10 days as you explore, shoot and run for your life against the onslaught of porcine monstrosities.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/434570/header.jpg?t=1736946173', 0, 0, NULL);
INSERT INTO games VALUES (48116, 434620, 'Pythagoria', 'Pythagoria is a brain-teasing number puzzle game.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/434620/header.jpg?t=1734124787', 0, 0, NULL);
INSERT INTO games VALUES (48058, 434650, 'Lost Castle / 失落城堡', 'Lost Castle is an action RPG beat''em up with roguelike elements and randomized dungeons for up to four players online and local!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/434650/header.jpg?t=1735803076', 0, 0, NULL);
INSERT INTO games VALUES (48062, 434730, 'Half Dead', 'Half dead is a multiplayer sci-fi game about a violent TV show. The players'' goal is to survive in a network of rooms full of traps.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/434730/header.jpg?t=1667305615', 1, 0, NULL);
INSERT INTO games VALUES (48046, 435100, '2Dark', '2Dark is a stealth adventure game developed by Frédérick Raynal, the pioneer of survival horror games and creator of Alone in the Dark®. Make your way through the lairs of psychopaths, unravel intrigue where madness mingles with horror, and, above all, save the kids!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/435100/header.jpg?t=1725289242', 0, 0, NULL);
INSERT INTO games VALUES (48047, 435120, 'Rusty Lake Hotel', 'Are you ready to serve the guests in the Rusty Lake Hotel? Solve all mysteries in this dark and eerie puzzle game. Rusty Lake Hotel is a point-and-click adventure by the creators of the Rusty Lake &amp; Cube Escape series.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/435120/header.jpg?t=1746052885', 1, 0, NULL);
INSERT INTO games VALUES (48049, 435150, 'Divinity: Original Sin 2 - Definitive Edition', 'The critically acclaimed RPG that raised the bar, from the creators of Baldur''s Gate 3. Gather your party. Master deep, tactical combat. Venture as a party of up to four - but know that only one of you will have the chance to become a God.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/435150/header.jpg?t=1725653917', 1, 0, NULL);
INSERT INTO games VALUES (48053, 435300, 'We Know the Devil', 'WE KNOW THE DEVIL is a visual novel about teens reluctantly fighting the devil at summer camp. Follow meangirl Neptune, tomboy Jupiter, and shy shy Venus as they get to know each other--but one always gets left out.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/435300/header.jpg?t=1593110459', 0, 0, NULL);
INSERT INTO games VALUES (48056, 435400, 'Hidden Folks', 'Search for hidden folks in hand-drawn, interactive, miniature landscapes. Unfurl tent flaps, cut through bushes, slam doors, and poke some crocodiles! Rooooaaaarrrr!!!!!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/435400/header.jpg?t=1726589872', 1, 0, NULL);
INSERT INTO games VALUES (48036, 435490, 'Pierhead Arcade', 'Play in your own virtual arcade with unlimited tokens.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/435490/header.jpg?t=1725082371', 0, 0, NULL);
INSERT INTO games VALUES (48037, 435530, 'The Final Station', 'Travel by train through a dying world. Look after your passengers, keep your train operational, and make sure you can always reach the next station. Make your way through swarms of infected at each station. Explore mysterious and abandoned stations looking for supplies and survivors.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/435530/header.jpg?t=1739397971', 0, 0, NULL);
INSERT INTO games VALUES (48044, 435840, 'The Preposterous Awesomeness of Everything', 'The Preposterous Awesomeness of Everything is a satirical point-and-click adventure game, about progress, politics and propulsive nozzles. It features fun verbs, irrelevant ducks and satirical shenanigans. I think you''ll like it :)', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/435840/header.jpg?t=1667228271', 0, 0, NULL);
INSERT INTO games VALUES (48035, 436290, 'Children of Zodiarcs', 'A story-driven, tactical RPG set in the fantasy realm of Lumus; a world divided by affluence and poverty. Take control of Nahmi and her fellow outcasts, utilising a brand new deck and dice based combat system to strike a blow to the noble Lords’ and Ladies’ unquenchable thirst for profit.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/436290/header.jpg?t=1592490528', 0, 0, NULL);
INSERT INTO games VALUES (48010, 436320, 'Raw Data', 'Built from the ground up for VR, Raw Data’s action gameplay, intuitive controls, challenging enemies, and sci-fi atmosphere will completely immerse you within the surreal world of Eden Corp. Go solo or team up and become the adrenaline-charged heroes of your own futuristic technothriller.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/436320/header.jpg?t=1688151692', 0, 0, NULL);
INSERT INTO games VALUES (48013, 436390, 'Prison Run and Gun', 'The recent events in a state prison, involving Jake from Team Hot Guns was a perfect moment for some prisoners to escape - you are one of them.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/436390/header.jpg?t=1730187066', 0, 0, NULL);
INSERT INTO games VALUES (48017, 436490, 'Firebird - La Peri', 'Enter a realm of enchantment with &quot;FIREBIRD - La Péri&quot;, and play the role of Iskender, a prince seeking the &quot;flower of immortality&quot;. You will appear on the stage, visit the ethereal world of La Péri, and witness a magical and poetic encounter as one of the characters...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/436490/header.jpg?t=1560517919', 0, 0, NULL);
INSERT INTO games VALUES (48018, 436500, 'Diaries of a Spaceport Janitor', 'Diaries of a Spaceport Janitor is an anti-adventure game about picking up trash in an alien bazaar. Play as the Janitor, an Alaensee girlbeast with a municipally-subsidized trash incineration job and dreams of leaving the planet of Xabran''s Rock far behind her.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/436500/header.jpg?t=1692115240', 0, 0, NULL);
INSERT INTO games VALUES (48020, 436520, 'Line of Sight', 'Fast paced FPS with high customizational freedom. From game mode customization to an in depth weapon tuning and attachment system up to detailed character customizations, while it was developed so you can choose to either go for high performance or graphical fidelity without an high end PC.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/436520/header.jpg?t=1639431233', 0, 1, NULL);
INSERT INTO games VALUES (48022, 436560, 'Kings and Heroes', 'Kings and Heroes is no longer available.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/436560/header.jpg?t=1658177339', 0, 0, NULL);
INSERT INTO games VALUES (48001, 436670, 'The Legend of Heroes: Trails in the Sky the 3rd', 'Half a year after Trails in the Sky SC, Father Kevin Graham takes on a routine mission on behalf of the Septian Church. He and his partner are then plunged into a realm that follows an unnaturally strict set of rules and is as intent to open old wounds as it is to keep them behind closed doors.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/436670/header.jpg?t=1732302247', 0, 0, NULL);
INSERT INTO games VALUES (47989, 437000, 'GUILTY GEAR 2 -OVERTURE-', 'The ultimate melee action [GUILTY GEAR 2 -OVERTURE-] is now on Steam!! Pushing [Gameplay] and [Entertainment] to the extremes, with a splash of [Competitiveness] -- That''s GUILTY GEAR 2 for you.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/437000/header.jpg?t=1671012068', 0, 0, NULL);
INSERT INTO games VALUES (47997, 437160, 'The Lion''s Song: Episode 1 - Silence', '„The Lion''s Song: Episode 1 – Silence&quot; draws the player into the life of a talented young composer, Wilma, preparing for her breakthrough concert, the defining moment of her career. Searching for inspiration she escapes from the pressure for success to the solitude of the Austrian Alps.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/437160/header.jpg?t=1725041691', 0, 1, NULL);
INSERT INTO games VALUES (47999, 437220, 'The Culling', 'Battle Royale is back! In a remote island paradise, 16 contestants have 25 minutes to explore, scavenge items, craft weapons, build traps, hunt and kill each other. Only one will be crowned the winner, do you have the guts to survive?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/437220/header.jpg?t=1553531711', 0, 0, NULL);
INSERT INTO games VALUES (48000, 437250, 'A House of Many Doors', 'Explore the House, a parasite dimension that steals from other worlds, in a train that scuttles on mechanical legs.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/437250/header.jpg?t=1731511998', 0, 0, NULL);
INSERT INTO games VALUES (47975, 437420, 'The Secret Order 3: Ancient Times', 'Find a way to destroy the ancient artifacts!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/437420/header.jpg?t=1582282891', 1, 0, NULL);
INSERT INTO games VALUES (47980, 437570, 'GoNNER', 'GoNNER is a tough as hell procedurally-generated 2D platformer with roguelike elements, following the largely misunderstood and altruistic Ikk on a journey to cheer up his only friend in this world - a giant landbound whale named Sally - by searching for just the right trinket in the deep and dark places nearby.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/437570/header.jpg?t=1726577234', 1, 0, NULL);
INSERT INTO games VALUES (47982, 437630, 'State of Mind', 'State of Mind is a futuristic thriller game delving into transhumanism. The game explores themes of separation, disjuncture and reunification, in a world that is torn between a dystopian material reality and a utopian virtual future.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/437630/header.jpg?t=1744397930', 1, 0, NULL);
INSERT INTO games VALUES (47956, 437920, 'Tricky Towers', 'With your brilliant robe and magic powers, it’s time to build some Tricky Towers! Stack your bricks in this land of fable, whose marvelous tower will be the most stable? Battle your friends and rise to fame, in this frantic physics game.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/437920/header.jpg?t=1730451129', 1, 0, NULL);
INSERT INTO games VALUES (47960, 438030, 'Dead6hot', 'Fast-paced shooting in a frantic atmosphere! Pick-up-and-play, like the good old days! Local multiplayer!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/438030/header.jpg?t=1454448826', 0, 0, NULL);
INSERT INTO games VALUES (47961, 438080, 'Surfingers', 'Surf as far as you can. Through the oceans, caves, snowy hills and deserts full of sand.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/438080/header.jpg?t=1568806430', 0, 0, NULL);
INSERT INTO games VALUES (129620, 438100, 'VRChat', 'Join our growing community as you explore, play, and help craft the future of social VR. Create worlds and custom avatars. Welcome to VRChat.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/438100/header.jpg?t=1733413042', 0, 1, NULL);
INSERT INTO games VALUES (47965, 438130, 'Root Double -Before Crime * After Days- Xtend Edition', 'Rescue squad captain Watase Kasasagi wakes up without his memories in the middle of his most critical mission yet-- a nuclear meltdown at a research facility. In an unfamiliar place and without his years of training, he must rescue the survivors and escape...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/438130/header.jpg?t=1656892623', 0, 0, NULL);
INSERT INTO games VALUES (47966, 438140, 'Star Realms', 'Star Realms is a hugely popular space combat deckbuilding game. Download and play today (note: base set is required to play online) to find out why Star Realms is the winner of SXSW 2014 Board Game of the Year, 7 Golden Geek Awards from BoardGameGeek, and 2 Dice Tower awards!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/438140/header.jpg?t=1727703137', 0, 1, NULL);
INSERT INTO games VALUES (47968, 438180, 'Super Mustache', 'Super Mustache is a vintage styled platformer, filled to the brim with 8 bit pixel art juice! Join Captain Super Mustache in a journey to save the planet Uranus. If you enjoyed classic platformer games from the golden era of video games, then you’re going to love this.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/438180/header.jpg?t=1453919773', 0, 0, NULL);
INSERT INTO games VALUES (47931, 438270, 'Learn Japanese To Survive! Hiragana Battle', 'The ideal introductory course to the Japanese language! Learn how to read and write Japanese characters (Hiragana) at a steady pace. A full-blown RPG specifically designed to keep you engaged. By playing along, you’re going to be introduced to the Japanese language like never before!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/438270/header.jpg?t=1696493771', 0, 0, NULL);
INSERT INTO games VALUES (47938, 438420, 'Zenith', 'Zenith is an action RPG coated in humor. Adventuring! Exploring ruins! Saving the world! You know the drill. A single player game with an actual story. No oneiric or do-it-yourself crap. You won''t need to piece the story together by yourself as if it was a swedish chair. We promise.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/438420/header.jpg?t=1721577900', 0, 0, NULL);
INSERT INTO games VALUES (47939, 438430, 'Valentino Rossi The Game', 'The most complete MotoGP™ game ever! Join Valentino Rossi’s VR|46 Riders Academy and train with him in order to become the new champion of the 2016 MotoGP™ season!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/438430/header.jpg?t=1742574123', 0, 0, NULL);
INSERT INTO games VALUES (47943, 438480, 'Rock ''N'' Roll Defense', 'Rocked by an explosive soundtrack, choose your band, place your equipments and defend the Rock ''N'' Roll from everyone and everything who try to pull it down, on a totally hardcore tower defense!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/438480/header.jpg?t=1725480615', 1, 0, NULL);
INSERT INTO games VALUES (47944, 438490, 'GOD EATER 2 Rage Burst', 'Swear your oath as a GOD EATER and drive back the supernatural harbingers of Earth’s destruction. Buy GOD EATER 2 Rage Burst and get GOD EATER Resurrection FOR FREE', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/438490/header.jpg?t=1703657122', 0, 0, NULL);
INSERT INTO games VALUES (47947, 438640, 'LEGO® STAR WARS™: The Force Awakens', 'The No. 1 LEGO® videogame franchise triumphantly returns with a fun-filled, humorous journey based on the blockbuster film. The game will also feature brand new story content from the Star Wars Universe that explores the time between Star Wars: Return of the Jedi and Star Wars: The Force Awakens.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/438640/header.jpg?t=1745615896', 0, 0, NULL);
INSERT INTO games VALUES (47928, 439190, 'Stories: The Path of Destinies', 'Stories: The Path of Destinies is an Action RPG, an enchanted storybook filled with madcap fantasy tales, each told by a zippy narrator attuned to the player’s choices and actions.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/439190/header.jpg?t=1706386352', 0, 0, NULL);
INSERT INTO games VALUES (47909, 439250, 'Space Pilgrim Episode III: Delta Pavonis', 'Still reeling from the life-changing events of the previous episode, Gail seeks out a safe haven with her father in the Delta Pavonis system. However, she soon learns that the politics of Planet Leto can be as treacherous and unpredictable as the local weather.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/439250/header.jpg?t=1743096319', 0, 0, NULL);
INSERT INTO games VALUES (47912, 439340, 'Tavern Tycoon - Dragon''s Hangover', 'Run your fantasy RPG tavern - let travellers take shelter for the night and serve ''em the best mead of their life with a good dose of humor.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/439340/header.jpg?t=1573457690', 0, 0, NULL);
INSERT INTO games VALUES (47916, 439490, 'BLUE REVOLVER', 'Fight, fly, flourish! BLUE REVOLVER is a manic arcade-style shoot-em-up built for newcomers and psychos alike. Powerful special weapons cut through tough areas, while an adaptive difficulty system tailors the game to your skill level as you evade and counter a maniac environmental force!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/439490/header.jpg?t=1732199941', 0, 0, NULL);
INSERT INTO games VALUES (47919, 439700, 'Z1 Battle Royale: Test Server', 'Z1 Battle Royale is a Free to Play, fast-paced, action arcade, competitive Battle Royale. Staying true to its &quot;King of the Kill&quot; roots, the game has been revamped and restored to the classic feel, look, and gameplay everyone fell in love with. Play solo, duos, or fives and be the last ones standing.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/439700/header.jpg?t=1623781388', 0, 0, NULL);
INSERT INTO games VALUES (47886, 440310, 'Project Arrhythmia', 'A musical bullet-hell where all things beautiful are deadly. Dodge well little nanobot, you don''t have much time.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/440310/header.jpg?t=1736728834', 0, 0, NULL);
INSERT INTO games VALUES (47889, 440420, 'True Fear: Forsaken Souls Part 1', 'True Fear: Forsaken Souls takes the best of the psychological thriller, blending in fun and intuitive gameplay mechanics. Episode 1, the first in a trilogy, will long be remembered.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/440420/header.jpg?t=1740671105', 1, 0, NULL);
INSERT INTO games VALUES (47892, 440520, 'VirtualHere For Steam Link', 'Add support for XBox One wireless, steering wheels, microphones, flight sticks, and other controllers to Steam Link!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/440520/header.jpg?t=1472864713', 0, 0, NULL);
INSERT INTO games VALUES (47893, 440540, 'Ara Fell: Enhanced Edition', 'Take in the beauty of a magical world floating above the clouds, then take on a menacing race of vampires hidden in the dark. Ara Fell combines the best parts of Japanese-style roleplaying games with the best parts of western RPGs. The new Enhanced Edition features a slew of new features!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/440540/header.jpg?t=1669279915', 0, 0, NULL);
INSERT INTO games VALUES (47894, 440550, 'Atomik: RunGunJumpGun', 'Atomik: RunGunJumpGun is a tough as nails game that puts a gravity-defying weapon in your hands. One button lets you fly, the other blasts obstacles out of the way. With a cast of crazed characters, challenging gameplay, and a pulsing musical score, it delivers twitchy platforming goodness.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/440550/header.jpg?t=1579700600', 1, 0, NULL);
INSERT INTO games VALUES (47895, 440630, 'The Brookhaven Experiment', 'Brookhaven is a VR survival shooter for the HTC Vive. Players will have to use the weapons and tools provided to survive ever more terrifying waves of horrific monsters in an attempt to figure out what caused the beginning of the end of the world, and, if they''re strong enough, stop it from happening.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/440630/header.jpg?t=1715711024', 1, 0, NULL);
INSERT INTO games VALUES (47873, 440730, 'Survival Zombies The Inverted Evolution', 'Survival Zombies is a bloody chaotic survival first person shooter that pits heavily armed players against humanity''s greatest fear - hordes of undead.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/440730/header.jpg?t=1747501356', 0, 0, NULL);
INSERT INTO games VALUES (47876, 440760, 'Cube Destroyer', 'Cube Destroyer is a top-down shooter with a dynamic gameplay.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/440760/header.jpg?t=1516981371', 0, 0, NULL);
INSERT INTO games VALUES (47881, 440880, 'The Count Lucanor', 'Pixel adventure inspired by classics like Zelda and Silent Hill.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/440880/header.jpg?t=1741006380', 1, 0, NULL);
INSERT INTO games VALUES (137228, 440900, 'Conan Exiles', 'An online multiplayer survival game, now with sorcery, set in the lands of Conan the Barbarian. Survive in a vast open world sandbox, build your home into a kingdom, and dominate your enemies in single or multiplayer.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/440900/header.jpg?t=1741979833', 1, 0, NULL);
INSERT INTO games VALUES (47883, 441010, 'Mount Your Friends 3D: A Hard Man is Good to Climb', 'Join in the great simulated sportslike experience of friend mounting! Assemble a team and climb your way to the top! Mount Your Friends 3D brings mounting to the third dimension, with the same classic innuendo that made you slightly uncomfortable back in the day.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/441010/header.jpg?t=1723905475', 0, 0, NULL);
INSERT INTO games VALUES (47884, 441050, 'Polandball: Can into Space!', 'Crazy fun rocket simulator game with countryballs theme. Can Polandball into Space? Try to find out!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/441050/header.jpg?t=1598044171', 0, 0, NULL);
INSERT INTO games VALUES (47866, 441280, 'Pharaoh Rebirth+', 'An ancient evil has been set loose, and Jonathan cursed in the process. Jonathan must now collect seven holy grails from around all of Egypt to cleanse himself of the curse of Sehur the First. Be delighted by the quirky humor, charming characters, and the beautifully designed world, in Pharaoh Rebirth+!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/441280/header.jpg?t=1674468236', 0, 0, NULL);
INSERT INTO games VALUES (47868, 441380, 'PAC-MAN™ CHAMPIONSHIP EDITION 2', 'The much-awaited sequel to PAC-MAN™ CHAMPIONSHIP EDITION! Featuring eye-popping 3D graphics and funky visuals! New modes include Score Attack and an Adventure mode!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/441380/header.jpg?t=1654694529', 0, 0, NULL);
INSERT INTO games VALUES (47869, 441440, 'Sometimes Always Monsters', 'Join a cross-country bus tour as a newlywed author, and combat vicious rumors that you''re a plagiarist. Truth isn''t important, when you control the narrative.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/441440/header.jpg?t=1729528132', 0, 0, NULL);
INSERT INTO games VALUES (47854, 441550, 'STAR WARS™ Rebellion', 'It is a time of great upheaval. The first Death Star has been destroyed, marking a major victory for the Rebellion. But the Empire remains strong. As commander, you must choose to take control of either the Rebel Alliance or the Galactic Empire. Your goal: complete domination of the galaxy.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/441550/header.jpg?t=1741815690', 0, 0, NULL);
INSERT INTO games VALUES (47857, 441670, 'Jelly Killer', 'Jelly Killer - Retro Platformer The Adventures Of A Young Bioweapon. In this game you will act like the young bioweapon. You will encounter lots of traps and puzzles. You will have to possess human bodies to pass the game to the end. Good luck!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/441670/header.jpg?t=1458860484', 0, 0, NULL);
INSERT INTO games VALUES (47860, 441790, 'Fragmented', 'Stranded in a hostile alien world, you must fight to survive. Hunt, harvest, craft, advance skills, and build using local resources along with technology from your voyage.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/441790/header.jpg?t=1667141517', 0, 0, NULL);
INSERT INTO games VALUES (47861, 441830, 'I am Setsuna', 'Inspired by the timeless classic Chrono Trigger, I am Setsuna is a great homage to the JRPG masterpieces of yesteryear. Journey with Setsuna as she prepares to make the ultimate sacrifice and save the people of her land.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/441830/header.jpg?t=1727789730', 0, 0, NULL);
INSERT INTO games VALUES (47863, 441870, 'OutDrive', 'Put the pedal to the metal or your girl will die! Experience the atmosphere of the world inspired by 80s with their neon lights, VHS tapes and synth pop. Buckle up! Gaming experiment in genre of music runner - not a game, aesthetic concept.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/441870/header.jpg?t=1667329514', 0, 0, NULL);
INSERT INTO games VALUES (129609, 442070, 'Drawful 2', 'For 3-8 players and an audience of thousands! Your phones or tablets are your controllers! The game of terrible drawings and hilariously wrong answers.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/442070/header.jpg?t=1728584390', 0, 0, NULL);
INSERT INTO games VALUES (47845, 442080, 'Riders of Icarus', 'Take the battle to the sky with fantastical flying mount combat unlike anything you’ve seen before in Riders of Icarus, the new unprecedented action-adventure MMORPG experience that lets you ride and fight on the back of the realm’s most dangerous winged beasts…dragons.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/442080/header.jpg?t=1747351888', 0, 0, NULL);
INSERT INTO games VALUES (47846, 442120, 'Pinball FX3', 'Pinball FX3 is the biggest, most community focused pinball game ever created. Multiplayer matchups, user generated tournaments and league play create endless opportunity for pinball competition.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/442120/header.jpg?t=1727782816', 0, 1, NULL);
INSERT INTO games VALUES (47849, 442210, 'Switchcars', 'Escape alien beasts across varying environments and eras, in more than 1300 unique vehicles! Add your own vehicles and props with the included editor.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/442210/header.jpg?t=1619801842', 0, 0, NULL);
INSERT INTO games VALUES (47842, 442500, 'Age of Gladiators', 'Age of Gladiators is a single-player strategy/management sim set at the height of the bloody gladiatorial games in ancient Rome. As your fighters increase in level, it will be up to you to decide how to forge their attributes and abilities.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/442500/header.jpg?t=1742986883', 0, 0, NULL);
INSERT INTO games VALUES (47834, 442780, 'STRAFE: Gold Edition', 'STRAFE® is the worlds bloodiest roguelike first-person shooter! Featuring mind melting secrets and persistent gore that allows you to paint levels red with the excessive entrails of your enemies. 30+ weapons, 20+ enemies, &amp; a red hot soundtrack.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/442780/header.jpg?t=1659053915', 0, 0, NULL);
INSERT INTO games VALUES (47838, 443000, 'DUAL GEAR', 'DUAL GEAR is a Tactical Action Turn-Based Strategy Game inspired by Japanese Mecha. To go beyond the traditional, DUAL GEAR engages the player to pilots their mechs with Real-Time Action Shooting while experiencing the high pressure of Tactical Turn-Based Layers!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/443000/header.jpg?t=1688012238', 0, 0, NULL);
INSERT INTO games VALUES (47806, 443810, 'This Is the Police', 'This Is the Police is a strategy/adventure game set in a city spiraling the drain. Taking the role of gritty Police Chief Jack Boyd, you''ll dive into a deep story of crime and intrigue. Will Jack reach his retirement with a nice stack of bills, or will he end up broken ... or worse?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/443810/header.jpg?t=1725011264', 0, 0, NULL);
INSERT INTO games VALUES (47809, 443860, 'Riptide GP: Renegade', 'Experience a future of illicit hydrojet racing, where armored riders kick out death-defying stunts over massive waterfalls, dodge cops, and boost across surging waves. Unlock new vehicles, characters, and customization features as you take down bosses and build your crew in Career mode.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/443860/header.jpg?t=1738821778', 0, 0, NULL);
INSERT INTO games VALUES (47811, 443970, 'S2ENGINE HD', 'S2 ENGINE HD is a complete general-purpose software kit for developing and running videogames, specifically dedicated to PC game hobbyists and enthusiasts. Its simplicity lets them turn on their computers and create amazing visuals in minutes just as if they were professionals.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/443970/header.jpg?t=1724097676', 0, 0, NULL);
INSERT INTO games VALUES (47813, 444000, 'Super Night Riders', 'A modern arcade racing game inspired by the retro classics.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/444000/header.jpg?t=1726255642', 0, 0, NULL);
INSERT INTO games VALUES (47779, 444090, 'Paladins®', 'Paladins is the ultimate fantasy team-based shooter experience, with over 50 customizable Champions fighting in 5v5 action across a diverse Realm of modes and maps!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/444090/header.jpg?t=1713560419', 0, 1, NULL);
INSERT INTO games VALUES (47781, 444140, 'Sonicomi', 'Super Sonico is a cheerful, hardworking college student and amateur musician who''s about to make her modeling debut. As her personal photographer, you will be responsible for Sonico''s image, balancing the needs of your clients with your own vision for Sonico''s future.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/444140/header.jpg?t=1730126973', 0, 0, NULL);
INSERT INTO games VALUES (129509, 444200, 'World of Tanks Blitz', 'Tanks, not war: jump into a free-to-play MMO action shooter with over 400 tanks. Enjoy stunning graphics and intuitive touch controls. Engage in 7vs7 battles, strategize with your team to conquer diverse maps. Customize tanks, unlock upgrades, and dive into adrenaline-pumping action on mobile and PC', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/444200/2689c89c7ec030248e74892eff635e7f848a73dc/header.jpg?t=1749074569', 1, 1, NULL);
INSERT INTO games VALUES (47787, 444220, 'Asteroid Bounty Hunter', 'Asteroid Bounty Hunter is a space shooter mixed with interesting boss fights and breathtaking visuals, with a reward system to take your skill to another level.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/444220/header.jpg?t=1613073758', 0, 0, NULL);
INSERT INTO games VALUES (47789, 444260, 'Mindless Running', 'Mindless Running - it''s a classic runner with story mode. Explore a randomly-generated world while listening to a unique soundtrack!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/444260/header.jpg?t=1493570649', 0, 0, NULL);
INSERT INTO games VALUES (47793, 444350, 'HACK_IT', 'HACK_IT presents players with a fully immersive hacking experience, you’ll meet characters and find out things you never imagined. Including interactive apps that will give you the power to shutdown servers and retrieve passwords.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/444350/header.jpg?t=1462463863', 0, 0, NULL);
INSERT INTO games VALUES (47800, 444490, 'POLYWAR', 'A fast paced multiplayer FPS game that focuses on creative weapons and game mechanics that reward skillful killing!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/444490/header.jpg?t=1512241872', 0, 0, NULL);
INSERT INTO games VALUES (47763, 444590, 'Skautfold: Shrouded in Sanity', 'Discover the secrets of the estate, as you look for answers among the violent inhabitants. A strange and repelling madness took hold of the servants roaming the halls, and they will attack on sight, for their madness is one rooted in a deeper understanding of cosmic insignificance.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/444590/header.jpg?t=1688449515', 0, 0, NULL);
INSERT INTO games VALUES (47766, 444690, 'TRAPPED', 'Something has gone terribly wrong in TRAPPED Alaska. Except for you, and a handful of survivors, the whole town has been emptied. Everywhere, what should be water has been replaced by a black semi-sentient sludge that seems to change everything it touches. And it’s rising...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/444690/header.jpg?t=1748115440', 1, 0, NULL);
INSERT INTO games VALUES (47768, 444720, 'Inexistence', 'Discover a vast world full of mysteries and action in this Metroidvania-style game inspired by the classics of the 16-bit era.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/444720/header.jpg?t=1465913884', 0, 0, NULL);
INSERT INTO games VALUES (47771, 444800, 'NO THING', 'The year is 1994 and it is the future. NO THING is a minimalistic surreal action game set in totalitarian regime of future. Tells the story of an office clerk who is sent with important message to the Queen of Ice.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/444800/header.jpg?t=1600179581', 0, 0, NULL);
INSERT INTO games VALUES (47774, 444880, 'Death Stair', 'Missing the days of split screen multiplayer or wanting to play with actual in-person friends in the same room? Death Stair is a local multiplayer stair climbing game. Play locally with maximum three friends and race to the finish while the fourth, armed to the teeth with an arsenal of unconventional ammo types, does everything to stop...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/444880/header.jpg?t=1474436616', 0, 0, NULL);
INSERT INTO games VALUES (47775, 444940, 'UBERMOSH:BLACK', 'UBERMOSH:BLACK is the second volume of the arcade series UBERMOSH. Cut bullets with your sword, shoot with heavy guns and splatter enemies with a rage fueled psionic wave.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/444940/header.jpg?t=1699491285', 1, 0, NULL);
INSERT INTO games VALUES (47778, 445020, 'Frozen Synapse 2', 'Frozen Synapse 2 is the sequel to the award-winning turn-based tactical game. Command your squads in a vast procedurally generated city: enter any building, perform any mission, execute any strategy.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/445020/header.jpg?t=1536857782', 0, 0, NULL);
INSERT INTO games VALUES (47749, 445110, 'Tasty Planet: Back for Seconds', 'Control a tiny ball of grey goo with the ability to eat anything smaller than itself. The more it eats, the bigger it gets! Eat rats, dinosaurs, gladiators, samurai, pyramids, volcanoes... Everything! Soon you''ll be eating the entire planet.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/445110/header.jpg?t=1678413164', 0, 0, NULL);
INSERT INTO games VALUES (47753, 445190, 'Expeditions: Viking', 'Circa 790 AD. A small band of Norse warriors lands on the shores of England. History may have forgotten their names, but their actions live on. As the chieftain of your clan, let ambition guide your choices in the party-based RPG Expeditions: Viking. How will history remember you?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/445190/header.jpg?t=1660137029', 0, 0, NULL);
INSERT INTO games VALUES (47755, 445220, 'Avorion', 'A procedural co-op space sandbox where players can build their own space ships out of dynamically scalable blocks. Fight epic space battles, explore, mine, trade, wage wars and build your own empire to save your galaxy from being torn apart by an unknown enemy.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/445220/header.jpg?t=1741975895', 0, 0, NULL);
INSERT INTO games VALUES (47757, 445310, 'Might and Magic: Heroes VII – Trial by Fire', 'Five years after the epic events of Might &amp; Magic Heroes VII, lead the new Fortress faction to define the destiny of the Dwarves and shed light on some of the darkest chapters of their history.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/445310/header.jpg?t=1692823199', 1, 0, NULL);
INSERT INTO games VALUES (47728, 445800, 'Love Language Japanese', 'Enter your first year at Koto Gakuen and discover Japanese language through easy to learn lessons and compelling mini games. Meet new friends and unveil their story and maybe find love through your adventures.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/445800/header.jpg?t=1556598822', 0, 0, NULL);
INSERT INTO games VALUES (47732, 445980, 'Wizard of Legend', 'Wizard of Legend is a no-nonsense, action-packed take on wizardry that emphasizes precise movements and smart comboing of spells in a rogue-like dungeon crawler that features over a hundred unique spells and relics!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/445980/header.jpg?t=1729183632', 1, 0, NULL);
INSERT INTO games VALUES (47733, 446000, 'Stellar Monarch', 'Asymmetric space empire builder where you feel like the Emperor, not a logistics officer. No micromanagement, grand scale, fast paced, audiences, assassins, imperial court, disloyal admirals.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/446000/header.jpg?t=1726476790', 0, 0, NULL);
INSERT INTO games VALUES (47735, 446020, 'Jalopy', 'Build, repair, refuel and drive a dilapidated old car on a grand journey through the territories of the former Eastern bloc. Explore Germany, CSFR, Hungary, Yugoslavia and Bulgaria', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/446020/header.jpg?t=1729246106', 1, 0, NULL);
INSERT INTO games VALUES (47741, 446120, 'Bunker Punks', 'Bunker Punks is a fast paced rogue-light FPS set in a dystopian future. Run a group of revolutionaries and raid corporate strongholds for supplies, weapons and armor. Customize your bunker, train your gang and tear down the corporate government.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/446120/header.jpg?t=1568763293', 0, 0, NULL);
INSERT INTO games VALUES (47713, 446310, 'Sabres of Infinity', 'Wage a war of gunpowder and magic! As a gentleman-officer of the Royal Dragoons, will you sacrifice your fortune? Your honour? Your men? Your own life?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/446310/header.jpg?t=1734030054', 0, 0, NULL);
INSERT INTO games VALUES (47714, 446330, 'Guns of Infinity', 'As commander of a squadron of cavalry, what will you sacrifice to win the war of gunpowder and magic? Fight for power, riches, love, or glory!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/446330/header.jpg?t=1734030070', 0, 0, NULL);
INSERT INTO games VALUES (47715, 446380, 'Sophie''s Curse', 'You got a job, which is to take care of an old man during the night in a recently purchased house; this house does not have electricity and you have to rely on some kind of hand crank generators to light the place up, but there is something in the darkness draining their power, don’t let it happen!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/446380/header.jpg?t=1749327354', 0, 0, NULL);
INSERT INTO games VALUES (47716, 446390, 'Onechanbara Z2: Chaos', 'Onechanbara Z2: Chaos is the latest entry in the Onechanbara series. Two sets of buxom vampire sisters battle through over a dozen stages of high-octane real-time swordplay. Fight off the invasion in gruesome detail, occasionally transforming into a demon for short bursts of added power and speed.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/446390/header.jpg?t=1728663743', 0, 0, NULL);
INSERT INTO games VALUES (47724, 446540, 'Smash Up', 'Smash Up is the digital adaptation of the award-winning (and totally awesome) card game. Smash together two factions, and destroy your opponent with a wild and wacky combination of pirates, nerds, zombies, wizards and more!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/446540/header.jpg?t=1670502597', 0, 0, NULL);
INSERT INTO games VALUES (47693, 446620, 'Zombie Training Simulator', 'Are you ready for the zombie apocalypse? We''ve done the research and want to make sure you''re prepared. When the news reports the zombies are here and your friend gives you a call, &quot;They''re here. I need you,&quot; how will you respond? That''s right, you''ll say &quot;On my way. We''ve got this thanks to ZTS!&quot;', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/446620/header.jpg?t=1728938277', 0, 0, NULL);
INSERT INTO games VALUES (47694, 446640, 'Space Pilgrim Episode IV: Sol', 'Locked away in the most secure prison in the galaxy, with little hope of escape, Gail Pilgrim faces the most difficult ordeals of her life. Her only hope lies in trusting those who she has come to regard as her friends.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/446640/header.jpg?t=1748878190', 0, 0, NULL);
INSERT INTO games VALUES (47698, 446800, 'Transport Fever', 'Transport Fever is a railroad-focused tycoon game. Players start in 1850 and build up a thriving transport company. As an emerging transport tycoon, the player constructs stations, airports, harbors and makes money by connecting areas requiring transport services. Build up your own Empire!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/446800/header.jpg?t=1709312016', 0, 0, NULL);
INSERT INTO games VALUES (47699, 446810, 'Blossom Tales: The Sleeping King', 'Explore a huge open game world in classic action-adventure fashion! Prove your worth by fighting through monster-infested dungeons to save the Kingdom of Blossom!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/446810/header.jpg?t=1726659079', 0, 0, NULL);
INSERT INTO games VALUES (47701, 446840, 'Splasher', 'Splasher is a fun and challenging 2D Platformer filled with humor and surprises. Armed with a paint cannon, you’ll face the dangers of the Inkorp mega-factory in order to save your companions, the Splashers, and put an end to the Machiavellian projects of the evil boss, Le Docteur.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/446840/header.jpg?t=1656581950', 0, 0, NULL);
INSERT INTO games VALUES (47708, 447020, 'Farming Simulator 17', 'Take on the role of a modern farmer in Farming Simulator 17! Explore farming possibilities in a new North American environment. Drive over 250 farming vehicles and equipment from over 75 manufacturers, including new brands such as Challenger, Fendt, Valtra or Massey Ferguson.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/447020/header.jpg?t=1658488796', 1, 0, NULL);
INSERT INTO games VALUES (47710, 447120, 'Where the Water Tastes Like Wine', 'Where the Water Tastes Like Wine is a Narrative-Adventure game about traveling, sharing stories, and surviving manifest destiny.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/447120/header.jpg?t=1599638565', 0, 0, NULL);
