INSERT INTO games VALUES (47682, 447190, 'Pub Encounter', '&quot;Pub Encounter&quot; is a romance game where you can fall in love with one of several middle-aged men.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/447190/header.jpg?t=1667201452', 0, 0, NULL);
