INSERT INTO games VALUES (47661, 447820, 'Day of Infamy', 'Experience close-quarters battles in iconic WWII settings. Defend the line, storm the beach, torch the enemy, or use a radio to call in fire support. Day of Infamy is a teamwork-oriented shooter that will keep you on your toes and coming back for more with its diverse game modes and authentic arsenal.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/447820/header.jpg?t=1738783161', 1, 0, NULL);
