INSERT INTO games VALUES (47678, 448080, 'Fibbage XL', 'NOTE: This game first appeared in The Jackbox Party Pack. It’s Fibbage XL – The Hilarious Bluffing Party Game in standalone form! Fool your friends with your lies, avoid theirs, and find the (usually outrageous) truth. “The mayor of Rabbit Hash, Kentucky is a ____.” Baby? Rabbit? Ham sandwich? Go!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/448080/header.jpg?t=1725046195', 0, 0, NULL);
