INSERT INTO games VALUES (47624, 448370, 'IS Defense', '„IS Defense” is a game set in politically-fictional 2020 – where the expansion of ISIS went out of hand. The player takes the role of NATO’s stationary machine-gun operator, deployed to defend the shores of Europe.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/448370/header.jpg?t=1713951885', 0, 0, NULL);
INSERT INTO games VALUES (47627, 448400, 'Hidden Object 6-in-1 bundle', 'Play six incredible hidden-object games full of mystery and unpredictable twists!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/448400/header.jpg?t=1705471904', 1, 0, NULL);
