INSERT INTO games VALUES (47504, 451570, 'Demetrios - The BIG Cynical Adventure', 'The Journey of an Idiot. 8 to 12 hours of fun!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/451570/header.jpg?t=1745442823', 0, 0, NULL);
