INSERT INTO games VALUES (47486, 451840, 'Out of Ammo', 'Out of Ammo is an intense VR Tower Defense / FPS hybrid strategy game that will have you constructing defenses, calling in artillery, issuing orders, and taking direct control of your soldiers in order to survive a relentless enemy onslaught.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/451840/header.jpg?t=1728950008', 0, 0, NULL);
