INSERT INTO games VALUES (47496, 451990, 'Cranks and Goggles', 'Cranks &amp; Goggles is a top down racing game set in the roaring 20s. The game’s engine utilizes real physics in order to mimic the unstable (and quite dangerous) nature of the period’s automobiles.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/451990/header.jpg?t=1553603200', 0, 0, NULL);
INSERT INTO games VALUES (47498, 452060, 'Caveblazers', 'Caveblazers is a challenging and brutal roguelike platformer. Journey into a mysterious cave, fighting orcs and goblins with an abundance of weapons and magical items! Make friends along the way, then watch in despair as they are crushed in to a bloody pulp under a troll''s fist.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/452060/header.jpg?t=1724766962', 0, 0, NULL);
