INSERT INTO games VALUES (47481, 452510, 'UNDER NIGHT IN-BIRTH Exe:Late', 'Dramatic Stylish 2D Fighting Action 「UNDER NIGHT IN-BIRTH Exe:Late」 now on Steam!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/452510/header.jpg?t=1671432712', 0, 0, NULL);
INSERT INTO games VALUES (47482, 452570, 'Battle Chef Brigade Deluxe', 'Battle Chef Brigade pairs combo-based hunting and puzzle-based cooking in a hand drawn, fantasy adventure. Cook your way into the Brigade while subduing Victusia’s destructive monsters. Follow Mina and Thrash in the single-player campaign or challenge your friends in Local Multiplayer and Daily Cook-Offs.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/452570/header.jpg?t=1748895395', 0, 0, NULL);
INSERT INTO games VALUES (47465, 452860, 'Mad Bullets', 'Mad Bullets, the wackiest shooter is here to put your reflexes and laughing muscles to an intensive test. You can forget about boring stories, complicated controls and irritating tutorials, and jump right into a mind blowing, high-speed action.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/452860/header.jpg?t=1478250686', 0, 0, NULL);
