INSERT INTO games VALUES (47454, 453300, 'A Healer Only Lives Twice', 'All You Need Is Heal! Monsters have cornered you in the dungeon corridors. As a newly hired Priest, your duties are to use your magical abilities to heal your comrade, a Knight on the front-line, and provide support during battle. Will these two brave souls live to see the light of day again?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/453300/header.jpg?t=1670925667', 0, 0, NULL);
INSERT INTO games VALUES (47455, 453310, 'Blackwood Crossing', 'Blackwood Crossing is a story-driven first-person adventure game. An intriguing and emotive tale exploring the fragile relationship between orphaned siblings, Scarlett and Finn. When their paths cross with a mysterious figure, an ordinary train ride evolves into a magical story of life, love and loss.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/453310/header.jpg?t=1573645795', 0, 0, NULL);
INSERT INTO games VALUES (47457, 453340, 'Hustle Cat', 'You are Avery Grey, the newest employee at a popular cat cafe called A Cat''s Paw. The coffee''s good and the staff is friendly (and kinda cute!) but mysterious. One day, you find a strange book in the basement, with letters you can''t quite read...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/453340/header.jpg?t=1584463902', 0, 0, NULL);
INSERT INTO games VALUES (47461, 453480, 'Shadowverse CCG', 'Four million battles every day. One Shadowverse. Japan''s #1 strategic card game. Made by card gamers for card gamers.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/453480/header.jpg?t=1743065691', 1, 1, NULL);
INSERT INTO games VALUES (47418, 453690, 'Dark Quest 2', 'Dark Quest 2 is a turn based RPG where you control a party of heroes on your epic quest to defeat the evil sorcerer and his minions.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/453690/header.jpg?t=1728561132', 0, 0, NULL);
INSERT INTO games VALUES (47421, 453720, 'Last Will', 'Your deranged and mysterious Grandfather is dead, and in his last will and testament, he gave his entire fortune and mansion to you. But on one condition. You have to visit his mansion and collect the riches for yourself. But once the door shuts behind you, you realize that this is no easy task.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/453720/header.jpg?t=1714391339', 0, 0, NULL);
INSERT INTO games VALUES (47424, 453750, 'Tyto Ecology', 'Build your biome! With an empty biodome as your canvas, add plants and animals from three different ecosystems. Observe interactions like hunting, blooming, and even decomposing! Will your biodome last for decades, or will it experience a total ecosystem collapse? You’re in control!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/453750/header.jpg?t=1662040746', 0, 0, NULL);
INSERT INTO games VALUES (47427, 453790, 'Candice DeBébé''s Incredibly Trick Lifestyle', 'Candice DeBébé''s Incredibly Trick Lifestyle is a saucy, scandalous 3D Action RPG about a young woman with a heart, voice and fake tan of gold.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/453790/header.jpg?t=1740841964', 0, 0, NULL);
INSERT INTO games VALUES (47444, 454060, 'Blueprint Tycoon', 'Build your settlement, gather goods, ensure maximum efficiency and make a profit!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/454060/header.jpg?t=1725191233', 0, 0, NULL);
INSERT INTO games VALUES (47445, 454070, 'Boundel: The Second Era', 'This is the time of guilds, wizards, warriors, blacksmiths, tailors, scribes, alchemists, woodworkers, animal tamers, brewers, traders, traitors and murderers. The Second Era begins!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/454070/header.jpg?t=1579292030', 0, 1, NULL);
INSERT INTO games VALUES (47447, 454100, 'Dungeon Escape', 'Challenging 2D platformer with simple graphics and a great chiptune soundtrack.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/454100/header.jpg?t=1726344070', 1, 0, NULL);
INSERT INTO games VALUES (128287, 454120, 'Starbase', 'Starbase is a hybrid voxel/vertex-based space MMO with a fully destructible and infinitely expanding universe, with a focus on building and designing spaceships and stations, exploration, resource gathering, crafting, trading, and combat.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/454120/header.jpg?t=1730718967', 0, 0, NULL);
INSERT INTO games VALUES (47449, 454140, 'First Person Tennis - The Real Tennis Simulator', 'First Person Tennis uses the most innovative physics engine to reproduce the real tennis shots in VR. Thanks to the support of a big community and professional tennis players, the game is in an endless development to reach an incredible level of realism.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/454140/b5a3fd6a6b9aaa2591fe41d3d2053f3747c0f4e9/header.jpg?t=1744355497', 0, 0, NULL);
INSERT INTO games VALUES (47450, 454160, 'Dark Fear', 'Dark Fear is a pixel horror game with RPG and adventure game elements. Explore a diverse landscape filled with forests, mountains, lakes and deserts. Make allies in the local village, upgrade your weapon and armor, go hunting/fishing and fight your way to the truth by slaying your foes, solving puzzles and helping people with their...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/454160/header.jpg?t=1650314970', 0, 0, NULL);
INSERT INTO games VALUES (47397, 454250, 'The Eyes of Ara', 'Explore a vast, mysterious castle riddled with secret rooms and challenging puzzles in this award-winning puzzle adventure.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/454250/header.jpg?t=1728859137', 1, 0, NULL);
INSERT INTO games VALUES (47399, 454320, '[the Sequence]', '[the Sequence] is a logic construction puzzler.Let your mind be your guide: Lay down seven different kinds of modules as your roadblocks to get you (portrayed as a binary data point) to a sweet destination.Apply an out-of-the-box thinking to get you to the next level!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/454320/header.jpg?t=1614154788', 0, 0, NULL);
INSERT INTO games VALUES (47401, 454350, 'Days of War: Definitive Edition', 'Days of War is an online FPS that re-imagines the team-based, close quarters, nonstop action of classic World War II multiplayer shooters.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/454350/header.jpg?t=1612022033', 0, 0, NULL);
INSERT INTO games VALUES (47402, 454380, 'Champions of Breakfast', 'A fast-paced arcade shooter breakfast-hell.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/454380/header.jpg?t=1667928512', 0, 0, NULL);
INSERT INTO games VALUES (47404, 454410, 'GIGA WRECKER', 'Become more than human and save mankind from total annihilation! From legendary developer Game Freak comes an action adventure like no other - manipulate the world around you and smash the evil Ajeet to smithereens!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/454410/header.jpg?t=1553785513', 1, 0, NULL);
INSERT INTO games VALUES (47408, 454530, 'Decisive Campaigns: Barbarossa', 'Command a true operational structure. Can you balance and prioritize three different Theatres in order to achieve your objective?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/454530/header.jpg?t=1726824380', 0, 0, NULL);
INSERT INTO games VALUES (129786, 454650, 'DRAGON BALL XENOVERSE 2', 'DRAGON BALL XENOVERSE 2 builds upon the highly popular DRAGON BALL XENOVERSE with enhanced graphics that will further immerse players into the largest and most detailed Dragon Ball world ever developed.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/454650/header.jpg?t=1748015990', 1, 0, NULL);
INSERT INTO games VALUES (47381, 454890, 'Project Starship', 'Project Starship is an arcade bullet-hell with random mechanics. No match will ever be the same. Who will you be? Garret or Gwen? Will you save the world from the mighty cthulhu?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/454890/header.jpg?t=1592220636', 0, 0, NULL);
INSERT INTO games VALUES (47383, 454950, 'Mainlining', 'After MI7 has been hacked, your primary goal is to bring a cyber-criminal network to justice. Played entirely from your computer''s desktop, Mainlining is a thrilling point and click hacking adventure that features a gripping narrative which will have you hooked from the very first case.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/454950/header.jpg?t=1728313376', 0, 0, NULL);
INSERT INTO games VALUES (47358, 455120, 'Stay Close', 'Stay Close is open-world horror game, with options for single-player and co-op. It has an unique and new gameplay approach unseen so far in any other game. You''ll find yourself in a creepy and anomalous town, what is your next move?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/455120/header.jpg?t=1514157048', 0, 0, NULL);
INSERT INTO games VALUES (47366, 455400, 'PAC-MAN 256', 'PAC-MAN 256 is the maze that never ends. But the Glitch is coming for you…', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/455400/header.jpg?t=1580375468', 0, 0, NULL);
INSERT INTO games VALUES (47355, 455820, 'Omensight: Definitive Edition', 'Omensight is an Action Murder Mystery game. In order to prevent the apocalypse, you are fated to repeat the last day of the world until it can be saved. Investigate clues, fight enemies, and solve the murder of the Godless-Priestess.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/455820/header.jpg?t=1706386498', 0, 0, NULL);
INSERT INTO games VALUES (47357, 455910, 'STAR WARS™: Rogue Squadron 3D', 'It is a time of great rejoicing in the galaxy. Luke Skywalker, with the help of Wedge Antilles, has blown up the Death Star. But there is little time to celebrate. The mighty Empire is gathering strength for a determined, all-out assault on the Rebel forces.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/455910/header.jpg?t=1741817733', 0, 0, NULL);
INSERT INTO games VALUES (47326, 456430, 'Christmas Adventure: Candy Storm', 'Chtistmas Adventure: Candy Storm – is a funny Christmas Hidden Object game with puzzles and mini-games of varying difficulty.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/456430/header.jpg?t=1657310630', 0, 0, NULL);
INSERT INTO games VALUES (47329, 456540, 'STAR WARS™: Rebel Assault I + II', 'ake your T16 through Beggar''s Canyon...Then dodge asteroids and blast TIE fighters in a deep space rumble... tackle a fleet of menacing AT-ATs on the icy tundra of Hoth...and ultimately annihilate Vader and the evil Empire with a kamikaze trench run on the infamous Death Star.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/456540/header.jpg?t=1741818065', 0, 0, NULL);
INSERT INTO games VALUES (47332, 456670, 'Hand of Fate 2', 'A new hero rises to challenge the Dealer in Hand of Fate 2! Master a living boardgame of infinitely replayable quests - unlock new cards, build your adventure, then defeat your foes in brutal real-time combat! Draw your cards, play your hand and discover your fate!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/456670/header.jpg?t=1747355466', 1, 0, NULL);
INSERT INTO games VALUES (47334, 456750, 'The Room Three', 'Lured to a remote island, you find yourself confined within the rooms of an ominous mansion. You must draw upon all your puzzle-solving ability to navigate a series of trials devised by a mysterious figure known only as “The Craftsman”. Do you have what it takes to escape?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/456750/header.jpg?t=1646758393', 0, 0, NULL);
INSERT INTO games VALUES (47322, 457010, 'StarsOne', 'You’ll see an unexplored world full of dangers, mysteries and adventures. You will explore randomly generated planets, develop industry, conduct trade, plant colonies, explore outer space.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/457010/header.jpg?t=1682455852', 0, 0, NULL);
INSERT INTO games VALUES (139902, 457140, 'Oxygen Not Included', 'Oxygen Not Included is a space-colony simulation game. Deep inside an alien space rock your industrious crew will need to master science, overcome strange new lifeforms, and harness incredible space tech to survive, and possibly, thrive.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/457140/header.jpg?t=1741894890', 1, 0, NULL);
INSERT INTO games VALUES (47296, 457210, 'SEUM: Speedrunners from Hell', 'Like a bastard child of Quake 3 and Super Meat Boy, SEUM: Speedrunners from Hell is truly hardcore and focuses on speed and fast reaction.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/457210/header.jpg?t=1725006616', 0, 0, NULL);
INSERT INTO games VALUES (47300, 457320, 'HoloBall', 'HoloBall plunges players into an action-sports arcade arena inspired by one of the most iconic games of all time. Use your paddles to hit, smash and curve the HoloBall past your opponent to score. Learn and master skillshots to outmatch your increasingly difficult opponents.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/457320/header.jpg?t=1511896157', 0, 0, NULL);
INSERT INTO games VALUES (47308, 457480, 'Domino Sky', 'Domino Sky is a physics based game where you place and topple domino pieces to solve puzzles. Free build mode also available.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/457480/header.jpg?t=1732725094', 0, 0, NULL);
INSERT INTO games VALUES (47311, 457530, 'My Lady', 'You are Miss Bauxmont, the heiress to the Bauxmont estate. With your mother always away on business trips, you find yourself infatuated with your personal butler. For several years, you have vied for his attention, but to no avail. However, you are now 17 and your mother has plans for you involving a certain suitor who has come into town.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/457530/header.jpg?t=1459205076', 0, 0, NULL);
INSERT INTO games VALUES (47313, 457570, 'Camp Sunshine', 'Camp Sunshine is a 16-bit blood-soaked Horror RPG that pits you as Jez, who is dropped off at Summer Camp. He awakes in the middle of the night to discover blood everywhere, a rampaging killer on the loose dressed in a mascot costume and himself involved in a deadly game of cat and mouse!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/457570/header.jpg?t=1633693100', 0, 0, NULL);
INSERT INTO games VALUES (47314, 457580, 'The Visitor', 'The Visitor is a VR horror experience about an unexpected visitor calling to your door in the middle of the night. The game relies heavily on atmosphere, utilizing a dark environment to make the player both as nervous and uncomfortable as possible.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/457580/header.jpg?t=1565364579', 0, 1, NULL);
INSERT INTO games VALUES (47315, 457600, 'Emerge: Cities of the Apocalypse', 'Part turn-based resource management, part real-time defense shooter, Emerge places you into a futuristic world, ravaged by a zombie Apocalypse.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/457600/header.jpg?t=1532956039', 0, 0, NULL);
INSERT INTO games VALUES (47319, 457680, 'OPUS: The Day We Found Earth', 'Dive into the boundless galaxy and embark on an emotional adventure! Help little robot Emeth to fulfill a century-old promise by finding Earth in order to save Mankind—so step into the spaceship, operate a deep space telescope, and find out what’s out there in the unknown.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/457680/header.jpg?t=1709177024', 1, 0, NULL);
INSERT INTO games VALUES (47277, 457710, 'Road Madness', '«Road Madness» is an Arcade Racing Game with some action elements.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/457710/header.jpg?t=1686008759', 0, 0, NULL);
INSERT INTO games VALUES (47278, 457730, 'Mushroom Wars 2', 'In Mushroom Wars 2, enemy tribes of feisty mushroom creatures face off in short but fierce RTS battles. Step into the shoes of a fearless Mushroom Commander, choose a hero to lead your army, and take control of the battlefield in a variety of multiplayer modes or challenging story campaign.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/457730/header.jpg?t=1725961262', 1, 0, NULL);
INSERT INTO games VALUES (47279, 457760, 'The Signal From Tölva', 'The Signal From Tölva is an open-world first-person shooter set on a distant, haunted, future world. Unlock savage weapons and recruit robots to fight alongside you as rival factions struggle to discover the source of the mysterious signal. What you discover will decide the fate of a world.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/457760/header.jpg?t=1522430832', 0, 0, NULL);
INSERT INTO games VALUES (47284, 457860, 'Apollo 11 VR', 'Apollo 11 VR is the story of the greatest journey ever taken by humankind. This VR experience is a recreation of the events which took place between July 16th and July 24th 1969. Now for the first time ever you get to experience this historic event through the eyes of those who lived through it.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/457860/header.jpg?t=1542120297', 0, 0, NULL);
INSERT INTO games VALUES (47287, 457960, 'Holopoint', 'Holopoint is pure archery madness. Fight your way through waves of responsive targets, samurai, and highly dangerous ninjas - all while drawing, nocking, and shooting your arrows as quickly as possible.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/457960/header.jpg?t=1725386476', 0, 0, NULL);
INSERT INTO games VALUES (47289, 458000, 'March of the Living', 'Roguelike-like inspired by FTL and popular zombie fiction. Guide a group of survivors to a rumoured safe haven.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/458000/header.jpg?t=1478024238', 0, 0, NULL);
INSERT INTO games VALUES (47265, 458470, 'Grim Legends 3: The Dark City', 'Hunt monsters in the gothic city!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/458470/header.jpg?t=1584462389', 1, 0, NULL);
INSERT INTO games VALUES (47266, 458480, 'Mythic Wonders: The Philosopher''s Stone', 'Find the Philosopher''s Stone!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/458480/header.jpg?t=1580998784', 1, 0, NULL);
INSERT INTO games VALUES (47273, 458580, 'Windlands 2', 'Windlands 2 is a built-for-VR fantasy action adventure game, use grappling hooks and a bow to explore the vast mysterious world to take down gigantic titans alone or with friends.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/458580/header.jpg?t=1728568222', 0, 0, NULL);
INSERT INTO games VALUES (47238, 458710, 'Kingdom Rush Frontiers - Tower Defense', 'Command your troops through an epic (mis)adventure as you defend exotic lands from dragons, man-eating plants, and ghastly denizens of the underworld -all with flashy new towers, levels, heroes, and more goodies to help you crush your foes in this Fantasy Action Tower Defense game!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/458710/header.jpg?t=1739880547', 1, 0, NULL);
INSERT INTO games VALUES (47239, 458730, 'Conception II: Children of the Seven Stars', 'It''s time for classmating! Monsters have invaded the world of Aterra, and only a few special individuals, imbued with the power of the Star God, are equipped to fight it. Combine your Star power to make magical Star Children to boost up your forces in battle!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/458730/header.jpg?t=1715700386', 0, 0, NULL);
INSERT INTO games VALUES (47240, 458750, 'FireAlpaca SE', 'FireAlpaca SE is painting software for Windows/Mac that has evolved as a higher brand of the regular version of FireAlpaca. We provide a professional creative environment where your creativity can be visualized immediately.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/458750/header.jpg?t=1738720242', 1, 0, NULL);
INSERT INTO games VALUES (47242, 458770, 'WRC 6 FIA World Rally Championship', 'On a race track, the car makes all the difference. In a rally, it''s the driver. Fog, mud, punctures... you have to deal with it all. WRC 6 includes all of the official 2016 content, 11 Super Special Stages on a 1:1 scale, local split-screen multiplayer and free access to the entire 2017 eSports WRC.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/458770/header.jpg?t=1725354005', 1, 0, NULL);
INSERT INTO games VALUES (47244, 458830, 'Snooker Nation Championship', 'Dream of playing in the World Snooker Championship? Indulge your snooker fix, and play along with the televised version of the sport with Snooker Nation Championship', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/458830/header.jpg?t=1563966710', 0, 0, NULL);
INSERT INTO games VALUES (47245, 458920, 'Carnival Games® VR', 'Carnival Games VR brings an immersive virtual reality experience, allowing you to explore the park, interact with patrons and play up to 12 different games. Enter a themed Carnival Alley where you can play a game and earn tickets for virtual prizes or unlock another game.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/458920/header.jpg?t=1568755246', 0, 0, NULL);
INSERT INTO games VALUES (47249, 459010, 'Ghost Town Mine Ride & Shootin'' Gallery', 'Explore an abandoned tourist attraction, test your shot at the Shootin'' Gallery, then board the mine cart ride for a descent into Hell! A thrilling new horror experience for the HTC Vive. Can you make it out Alive?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/459010/header.jpg?t=1666997067', 0, 0, NULL);
INSERT INTO games VALUES (47253, 459080, 'YIIK: A Postmodern RPG', 'Experience YIIK: A Postmodern RPG 1.5 (I.V) update with revamped battles and cutscenes. A child relinquishes her name for a birthday invite, hoping to find her brother. Alex''s reality unravels, guided by a mysterious cat, witnessing a woman vanish, igniting an obsession that threatens his world.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/459080/header.jpg?t=1733116766', 0, 0, NULL);
INSERT INTO games VALUES (47254, 459090, 'Masquerada: Songs and Shadows', 'Masquerada is a single-player tactical RPG set in a Renaissance-inspired city of magic, where real-time combat can be paused to set up elemental combos powered by Venetian-styled masks. Come for gorgeous hand-drawn art; stay for the rich lore &amp; a thoughtful, fully-voiced tale of intrigue &amp; tragedy.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/459090/header.jpg?t=1730740424', 0, 0, NULL);
INSERT INTO games VALUES (47225, 459220, 'Halo Wars: Definitive Edition', 'Halo Wars: Definitive Edition is an enhanced version of the real-time strategy classic, Halo Wars, updated to run natively on PC. Halo Wars: Definitive Edition includes improved graphics, new achievements and all of the DLC created for the landmark real-time strategy game.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/459220/header.jpg?t=1667852215', 1, 0, NULL);
INSERT INTO games VALUES (47227, 459310, 'The Hero Project: Redemption Season', 'America''s #1 reality show for heroes is back for another season! Harness your superpowers to steal the spotlight, win votes, and save your sister!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/459310/header.jpg?t=1734030086', 0, 0, NULL);
INSERT INTO games VALUES (139533, 459820, 'Crush Crush', 'Welcome to Crush Crush - the Idle Dating Sim! Meet, flirt, and fall in love with a motley cast of girls in this heartfelt and hilarious game.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/459820/header.jpg?t=1748193681', 0, 1, NULL);
INSERT INTO games VALUES (47220, 459940, 'Deer Man', 'Deer Man is a short Interactive Storytelling experience. You play as Jacob''s memory, where you will have an incredible encounter with Deer Man &amp; the dark side of his love for the wildlife. If you love animals, this is for you!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/459940/header.jpg?t=1590205451', 0, 0, NULL);
INSERT INTO games VALUES (47196, 460160, 'The Leisure of Grisaia', 'This side story to &quot;The Fruit of Grisaia&quot; is a character-driven visual novel featuring some of the same characters. This time, it''s Michiru who takes the lead role in this slapstick comedy. A laugh-out-loud side story detailing the Mihama girls'' school hijinks.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/460160/header.jpg?t=1742527209', 0, 0, NULL);
INSERT INTO games VALUES (47202, 460340, 'Guards', 'Four heroes are facing a horde of evil! Ultimate abilities, magic artifacts, hero upgrades and clever tactics... All these will help to defeat the Boss.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/460340/header.jpg?t=1576156796', 0, 0, NULL);
INSERT INTO games VALUES (47203, 460430, 'The Letter - Horror Visual Novel', 'When seven people fall prey to a vicious curse, they will discover that horror rests not from the shadows lurking about, but within themselves. To what ends will one go in order to survive?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/460430/header.jpg?t=1697729294', 0, 0, NULL);
INSERT INTO games VALUES (47181, 460700, 'Song of the Deep', 'From the creators of Ratchet &amp; Clank, Song of the Deep is a metroidvania-style action-adventure game following a young girl’s quest into the unknown to find her missing father. It combines underwater discovery, skill, and suspense with a powerful story.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/460700/header.jpg?t=1725992916', 0, 0, NULL);
INSERT INTO games VALUES (47184, 460790, 'Bayonetta', 'PlatinumGames’ universally acclaimed action masterpiece finally comes to PC. Experience the over-the-top stylish action in 60fps at unlocked HD resolutions. The definitive way to play: being bad never felt so good.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/460790/header.jpg?t=1721737243', 0, 0, NULL);
INSERT INTO games VALUES (47185, 460810, 'Vanquish', 'PlatinumGames’ revolutionary sci-fi action shooter slide-boosts onto PC. Battle legions of future-tech enemies using a vast arsenal of weapons, including all DLC. Fully unlocked framerate and gorgeous HD resolutions up to 4K. The definitive way to play: war has accelerated.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/460810/header.jpg?t=1721737247', 0, 0, NULL);
INSERT INTO games VALUES (47189, 460950, 'Katana ZERO', 'Katana ZERO is a stylish neo-noir, action-platformer featuring breakneck action and instant-death combat. Slash, dash, and manipulate time to unravel your past in a beautifully brutal acrobatic display.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/460950/header.jpg?t=1719982207', 1, 0, NULL);
INSERT INTO games VALUES (47190, 460960, 'The Deed: Dynasty', 'Getting away with murder has never been easy. These three members of a proud and noble family are separated by five centuries, but have in common a vengeful and murderous intent. Plans must be formed, blood must be spilled and evidence must be planted ...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/460960/header.jpg?t=1748879253', 0, 0, NULL);
INSERT INTO games VALUES (47163, 461170, 'Bucket Detective', 'A dark comedy/horror game by Jesse Barksdale, creator of the static speaks my name. Help a cult complete a ritual in exchange for divine inspiration to finish writing your terrible novel. A story-focused experience which takes around 45 minutes to complete.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/461170/header.jpg?t=1587168383', 0, 0, NULL);
INSERT INTO games VALUES (47134, 461430, 'EmergeNYC', 'EmergeNYC is a simulation of New York City''s Emergency Services. Drive over 30 different Emergency Vehicles with up to 32 of your friends through busy City Streets with blazing sirens and air horns. Take the role of a firefighter, medic, or police officer and ride with your friends to emergencies', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/461430/header.jpg?t=1619220828', 0, 0, NULL);
INSERT INTO games VALUES (47145, 461620, 'Predynastic Egypt', 'Do you know how did Ancient Egypt looked like before the Great Pyramids? Lead the future Egyptian citizens all the way through the historical hardships to the Unification of Lower and Upper Egypt, and you will find out!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/461620/header.jpg?t=1667300408', 0, 0, NULL);
INSERT INTO games VALUES (47146, 461640, 'Sins Of The Demon RPG', 'Follow the journey of Kenshi, a wandering demon hunter, and his brother, a demon cat seeking a way to return to his true form. Can they find a way to end the curse and save Lanistra?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/461640/header.jpg?t=1574484706', 0, 0, NULL);
INSERT INTO games VALUES (47148, 461700, 'Seduce Me 2: The Demon War', 'Seduce Me 2: The Demon War is the sequel to the popular free-to-play otome game, Seduce Me the Otome. It follows the story of Mika Anderson as she is suddenly thrown into the Abyssal Plains right before she is about to be married to one of the five Incubi Brothers featured in the first game.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/461700/header.jpg?t=1464047764', 0, 0, NULL);
INSERT INTO games VALUES (47156, 461840, 'Zenge', 'Relaxing puzzle game, telling the story of Eon through gorgeous art and music.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/461840/header.jpg?t=1729158931', 1, 0, NULL);
INSERT INTO games VALUES (47159, 461870, 'Police Simulator: Patrol Duty', 'Experience the exciting day-to-day life of an US police officer in Police Simulator: Patrol Duty. Discover a large, lively and freely-accessible US city powered by Unreal®Engine 4 and ensure the safety in your district.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/461870/header.jpg?t=1683202525', 0, 0, NULL);
INSERT INTO games VALUES (47122, 461890, 'NORTH', 'Dealing with the issue of the contemporary refugee crisis while at the same time being deeply rooted in a classical cyberpunk atmosphere à la Blade Runner, NORTH features a dark synthpop soundtrack, a sprawling mega-city and weird monster-like inhabitants.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/461890/header.jpg?t=1693079809', 0, 0, NULL);
INSERT INTO games VALUES (47123, 461950, 'Beat Cop', 'A retro, pixel art style adventure in New York, inspired by ’80s cop shows. You are Jack Kelly and you’ve been framed for murder. Now as a regular beat cop you have to find out, who did that. Expect thick crime story, a lot of black humour and all the other things you can find on the streets of Brooklyn.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/461950/header.jpg?t=1701878616', 1, 0, NULL);
INSERT INTO games VALUES (47128, 462100, 'Starr Mazer: DSP', 'The UNFP''s been kicked in the teeth by a G''ell invasion force and their last and only hope is a planetary outpost and its fleet of experimental DSP MkI Forward Assault Fighters and anyone marshal enough to strap into one and forcefully accept some apologies.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/462100/header.jpg?t=1564963090', 0, 0, NULL);
INSERT INTO games VALUES (47090, 462680, 'BalanCity', 'BalanCity is a city building / balance physics game. It''s a mixture between old school SimCity and Jenga. You must build the tallest towering city over a balancing platform while keeping your citizens happy.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/462680/header.jpg?t=1585592395', 0, 0, NULL);
INSERT INTO games VALUES (47093, 462770, 'Pyre', 'Pyre is a party-based RPG from the creators of Bastion and Transistor. Lead your band of exiles to freedom through a series of mystical competitions in the Campaign, or challenge a friend to a fast-paced ritual showdown in the head-to-head Versus Mode.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/462770/header.jpg?t=1729114062', 0, 0, NULL);
INSERT INTO games VALUES (47094, 462780, 'Darksiders Warmastered Edition', 'Deceived by the forces of evil into prematurely bringing about the end of the world, War – the first Horseman of the Apocalypse – stands accused of breaking the sacred law by inciting a war between Heaven and Hell.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/462780/header.jpg?t=1736838436', 1, 0, NULL);
INSERT INTO games VALUES (47098, 462930, 'AdVenture Communist', 'The world''s greatest communism simulator!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/462930/header.jpg?t=1721081621', 0, 1, NULL);
INSERT INTO games VALUES (47099, 462940, 'Making History: The Second World War', 'Choose a nation and prepare for the greatest conflict in human history, World War II. Build your military and industrial power, form alliances and race to achieve the advanced technologies that will bring total victory in this global-wide turn-based Grand Strategy struggle.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/462940/header.jpg?t=1692108100', 0, 0, NULL);
INSERT INTO games VALUES (47100, 462960, 'Caveman World: Mountains of Unga Boonga', 'Caveman World: Mountains of Unga Boonga is a retro inspired platformer adventure game set in fantasy prehistoric time. You play as a Caveman, exploring various levels and overcoming physical obstacles. Levels become increasingly more difficult as you encounter enemies, obstacles, traps and more!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/462960/header.jpg?t=1748874256', 0, 0, NULL);
INSERT INTO games VALUES (47104, 463030, 'Bottle (2016)', 'Bottle is a short game which you play as a man of solitude. It is about the mood of melancholy in the winter nature.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/463030/header.jpg?t=1728894132', 0, 0, NULL);
INSERT INTO games VALUES (47061, 463110, 'Farnham Fables', 'When Naigye and her niece Cally visit the castle, a surprise encounter with King Farnham leads to a short story about his three sons visiting a village of native lizard people.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/463110/header.jpg?t=1573428119', 0, 0, NULL);
INSERT INTO games VALUES (47065, 463150, 'BARRIER X', 'Dodge! Shoot! Go faster! Break the sound barrier in this unbelievably fast game and go straight for the first place in the leaderboard of BARRIER X!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/463150/header.jpg?t=1568226582', 0, 0, NULL);
INSERT INTO games VALUES (47067, 463170, 'Jagged Alliance: Rage!', 'Jagged Alliance is back – With a new take on turn-based tactics, adventure elements and the well-known quirky mercenaries! Set 20 years after the first Jagged Alliance, this spin-off lets you experience a road trip into a jungle hell to test your mind and body to the limits!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/463170/header.jpg?t=1741703503', 1, 0, NULL);
INSERT INTO games VALUES (47069, 463210, 'State of Anarchy', 'Simplistic top-down shooter that will put a smile on your face. Fulfill your inner sociopath as you mow down enemies with guns and cars alike, in a bid to pull off the world''s largest heist!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/463210/header.jpg?t=1517225734', 0, 0, NULL);
INSERT INTO games VALUES (47070, 463220, 'Dungeon of Zolthan', 'Dungeon of Zolthan is a casual, arcade-style metroidvania platformer where your goal is to defeat Zolthan; a powerful mage that lives inside the dungeon. Using an array of powerups and your own wit and guile, guide your character through Zolthan''s Dungeon!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/463220/header.jpg?t=1488334671', 0, 0, NULL);
INSERT INTO games VALUES (47072, 463270, 'Ghost 1.0', 'A mysterious agent, capable of becoming a digital ghost, sneaks aboard the Nakamura Space Station. This is where the fun begins: the station is well-protected with its heavy defences, never-ending arsenal of weapons, and mysterious artifacts. It will all have to be destroyed.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/463270/header.jpg?t=1706997523', 0, 0, NULL);
INSERT INTO games VALUES (47073, 463290, 'Kismet', 'Kismet is a daily fortune-teller who delivers eerily accurate tarot and astrology readings from inside a beautifully detailed, magical, transforming Gothic cabin.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/463290/header.jpg?t=1638898723', 0, 1, NULL);
INSERT INTO games VALUES (47075, 463350, 'Storm Of Spears RPG', 'Prepare for an epic 10 hour adventure in the world of Galager. Sura, the world''s most sought-after mercenary, leads a band of sell-swords in a last-ditch effort to save the world. Prepare for the Storm of Spears!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/463350/header.jpg?t=1574484820', 0, 0, NULL);
INSERT INTO games VALUES (47054, 463850, 'Muddy Heights® 2', 'Poop you way to victory...again! In Muddy Heights 2, you play as a person who has had a little bit too much to eat and needs to relieve himself by any means possible. Poop off various heights onto people and vehicles to score points. Complete level goals to gain cash to buy more food.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/463850/header.jpg?t=1572926987', 0, 0, NULL);
INSERT INTO games VALUES (47059, 463930, 'The Dweller', 'The Dweller is a puzzle game where you play as the MONSTER! It''s time to get rid of all those pesky archaeologists snooping around in your lair. SCARE them, CRUSH them, DEVOUR them! ELIMINATE THE INTRUDERS!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/463930/header.jpg?t=1568807276', 0, 0, NULL);
INSERT INTO games VALUES (47027, 463980, 'Solitairica', 'Solitairica takes RPG combat and challenging roguelike progression to a fresh new place—the world of solitaire! Using a variety of magical items and powerful spells, battle your way through a horde of ever-changing enemies and defeat the horrible Emperor Stuck.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/463980/header.jpg?t=1717087990', 0, 0, NULL);
INSERT INTO games VALUES (47032, 464060, 'RUINER', 'RUINER is a brutal action shooter set in the year 2091 in the cyber metropolis Rengkok. A wired psychopath lashes out against a corrupt system to uncover the truth and retrieve his kidnapped brother under the guidance of a secretive hacker friend.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/464060/header.jpg?t=1708036132', 1, 0, NULL);
INSERT INTO games VALUES (47035, 464100, 'Codex of Victory', 'In this sci-fi turn-based strategy with real-time base-building elements, you’ll be defending human territories against the transhuman Augments. Expand your HQ, and manufacture and upgrade an army of advanced drones to wage interplanetary war for Humanity!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/464100/header.jpg?t=1669899503', 0, 0, NULL);
INSERT INTO games VALUES (47038, 464150, 'Regalia: Of Men and Monarchs', 'Regalia: Of Men And Monarchs is a tactical RPG set in a cheerful fantasy world full of weirdness and wonder. Assemble your party, go adventuring, manage your kingdom, make new friends, and defeat your opponents in challenging turn-based combat.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/464150/header.jpg?t=1720100322', 0, 0, NULL);
INSERT INTO games VALUES (47042, 464260, 'Xeno Crisis', 'Xeno Crisis is an arena shooter in which up to two players take control of battle-hardened marines embarking on a deadly mission to confront an alien menace! Run and gun your way through thousands of adversaries, searching for survivors, and ultimately facing the origin of the outpost''s demise.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/464260/header.jpg?t=1592932356', 0, 0, NULL);
INSERT INTO games VALUES (47043, 464340, 'Syberia 3', 'The next generation in adventure games, Syberia 3 takes you inside an enchanting, mysterious universe full of life for you to explore in 3D. Plunged into the heart of a world inhabited by a cast of interesting characters, you''ll discover and experience a fabulous tale as imagined by Benoit Sokal.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/464340/header.jpg?t=1743167602', 1, 0, NULL);
INSERT INTO games VALUES (47044, 464350, 'Screeps: World', 'Screeps: World is an open source MMO RTS sandbox game for programming enthusiasts, wherein the core mechanic is programming your units AI. You control your colony by writing JavaScript which operates 24/7 in the single persistent open world filled by other players on par with you.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/464350/header.jpg?t=1736689576', 0, 0, NULL);
INSERT INTO games VALUES (47045, 464360, '3030 Deathwar Redux - A Space Odyssey', '3030 Deathwar is a unique mix of Adventure and Space Sim. Explore star systems, mine and hunt pirates in top-down mode. Leave your ship and switch into classic Adventuring mode, where you explore derelicts, talk to shady characters or head over to the space bar for a drink.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/464360/header.jpg?t=1728853119', 0, 0, NULL);
INSERT INTO games VALUES (47012, 464450, 'DoDonPachi Resurrection', 'The legendary bullet-hell shoot-’em-up series has come to Steam! DoDonPachi is ressurected after a Blissful Death with enough modes to satisfy the beginner and the expert player alike. Tonight we dine in bullet hell!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/464450/header.jpg?t=1737123621', 0, 0, NULL);
INSERT INTO games VALUES (47018, 464620, 'Siralim 2', 'Siralim 2 is an old-school monster catching RPG. Summon and customize hundreds of creatures to fight for you as you battle your way through endless dungeons. Find rare treasure and use it to upgrade your castle, empower your creatures, craft powerful artifacts, learn new spells, and much more.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/464620/header.jpg?t=1682260276', 0, 0, NULL);
INSERT INTO games VALUES (46987, 464850, 'Don Bradman Cricket 17', 'Don Bradman Cricket 17 brings a new revolutionary control system delivering the best batting, bowling and fielding experience by providing you an even greater level of variety and precision of play. You Are Invincible!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/464850/header.jpg?t=1494387343', 0, 0, NULL);
INSERT INTO games VALUES (46988, 464880, 'Stars in Shadow', 'Stars in Shadow is a turn-based 4X strategy game and a vivid tribute to the genre classics. Compete with alien factions to explore and colonize nearby starsystems, build fleets to defend against rivals, negotiate or conquer them. Win by unifying the galaxy, through diplomacy or force.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/464880/header.jpg?t=1728468596', 0, 0, NULL);
INSERT INTO games VALUES (46990, 464920, 'Surviving Mars', 'There will be challenges to overcome. Execute your strategy and improve your colony’s chances of survival while unlocking the mysteries of this alien world. Are you ready? Mars is waiting for you.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/464920/header.jpg?t=1745481288', 0, 0, NULL);
INSERT INTO games VALUES (46996, 465020, 'Sector Six', 'Sector Six is a side-scrolling, sci-fi shooter with a silhouette aesthetic, procedural loot, extensive customization, and story missions.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/465020/header.jpg?t=1748891205', 0, 0, NULL);
