INSERT INTO games VALUES (47007, 465200, 'Fury Unleashed', 'Shoot your way through the pages of an ever-changing comic book in this fast-paced roguelike. Play solo, in local or online co-op, expand your weaponry, and upgrade your hero with each run. All that to find out why has your creator lost his faith in you and to prove him wrong.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/465200/header.jpg?t=1748606260', 1, 0, NULL);
INSERT INTO games VALUES (47008, 465240, 'Serious Sam VR: The Last Hope', 'Serious Sam is back! And this time it''s REAL!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/465240/header.jpg?t=1728689200', 0, 0, NULL);
INSERT INTO games VALUES (47009, 465280, 'Yesterday Origins', 'John Yesterday becomes immortal following an occult ritual. However, not everything goes to plan. He and his girlfriend Pauline must embark on an investigation to try to reproduce the immortality ritual. But his former acquaintances have other plans for him...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/465280/header.jpg?t=1683877469', 0, 0, NULL);
