INSERT INTO games VALUES (46952, 465780, 'New Retro Arcade: Neon', 'Emulate your favorite arcade games in an environment engrossed with retro realism and extremely detailed surroundings. Be filled with nostalgia and realise what arcade life felt like back in the 80’s/early 90’s.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/465780/header.jpg?t=1728581355', 0, 0, NULL);
INSERT INTO games VALUES (46972, 466110, 'Shaolin vs Wutang', 'Shaolin vs Wutang is a INDIE love letter to Martial Arts and classic Kung Fu films. Made for casual game fans not intended for Hardcore Fighting Game players.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/466110/header.jpg?t=1667135061', 0, 0, NULL);
INSERT INTO games VALUES (46973, 466130, 'White Day: A Labyrinth Named School', 'Notorious cult-classic Korean horror. Sneak into school at midnight to return your sweetheart''s diary and get caught in a terrifying game of cat and mouse. Explore haunted hallways, solve classic survival horror puzzles and escape the clutches of a killer Janitor who is out for your blood.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/466130/header.jpg?t=1741786299', 1, 0, NULL);
INSERT INTO games VALUES (46937, 466240, 'Deceit', 'Test your instincts at trust and deception in an action-filled, multiplayer first-person shooter. You wake up in unknown surroundings to the sound of the Game Master’s unfamiliar voice, surrounded by five others. A third of your group have been infected with a virus, but who will escape?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/466240/header.jpg?t=1734441940', 1, 1, NULL);
INSERT INTO games VALUES (46941, 466300, 'Planescape: Torment: Enhanced Edition', 'Uncover secrets of past lives in this story-rich, tactical roleplaying game set in Sigil, a dark fantasy city at the heart of the Dungeons &amp; Dragons multiverse. Explore the planes, survive combat alongside a party of bizarre companions, and solve puzzles unlike any ever seen in the genre.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/466300/header.jpg?t=1746122996', 1, 0, NULL);
INSERT INTO games VALUES (46947, 466500, '35MM', 'Post-apocalyptic story about two travelers who set out on a long journey in the wasteland, left by people after the global epidemic.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/466500/header.jpg?t=1726734088', 0, 0, NULL);
