INSERT INTO games VALUES (46917, 466630, 'The Pedestrian', 'I can see the signs in my sleep now, always guiding me closer. Will this really work? Have we almost achieved the impossible?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/466630/header.jpg?t=1683644396', 0, 0, NULL);
INSERT INTO games VALUES (46921, 466740, 'ARAYA', 'ARAYA is a first person horror game. Players will get a new thrilling experience inside a Thai hospital. The story will be told from the perspectives of 3 different characters. Players will explore different areas of the hospital in order to piece together the mysterious murder case of Araya.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/466740/header.jpg?t=1572763987', 0, 0, NULL);
INSERT INTO games VALUES (46924, 466800, 'The Dope Game', 'To escape the city of Starkham and start your new life, your friend Preston sets up a meeting with the local loanshark, Sweaty Mike. After foolishly borrowing $2,000, you embark on a timed mission to sell as many illicit substances as possible. Based on John E. Dell''s 1984 classic game Drugwars.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/466800/header.jpg?t=1711094757', 0, 0, NULL);
INSERT INTO games VALUES (46927, 466840, 'Super Space Pug', 'Super Space Pug is a classic arcade shmup. Take control of ''Demetrius the Third''(Space Pug) to defend your personal space from the evil, fish flinging cats and random rocks because its a space shmup, and without rocks it would be rather non-space-y.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/466840/header.jpg?t=1465423856', 0, 0, NULL);
