INSERT INTO games VALUES (46934, 466940, 'The Sandbox Evolution - Craft a 2D Pixel Universe!', 'Use your godly powers to craft amazing pixel worlds or destroy the universe! Play with physics, over 200 elements and controllable heroes. Make your own games or levels, and then share your creations online. There are no limits to your creativity and imagination!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/466940/header.jpg?t=1513117405', 0, 1, NULL);
INSERT INTO games VALUES (46887, 467520, 'Power & Revolution', 'In Power &amp; Revolution, become a Head of State of one or several countries of your choice and extend your influence on the world, or play as a legal or illegal opposition leader and get ready for the conquest to power!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/467520/header.jpg?t=1515589969', 0, 0, NULL);
INSERT INTO games VALUES (46890, 467660, 'Paranormal Activity: The Lost Soul', 'AVAILABLE TO PLAY IN NON-VR (KEYBOARD/MOUSE AND CONTROLLER) VR HEADSET NO LONGER REQUIRED.“PARANORMAL ACTIVITY: THE LOST SOUL” immerses you in a terrifying realistic environment with haunting atmosphere, and the need to survive.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/467660/header.jpg?t=1724356625', 0, 0, NULL);
INSERT INTO games VALUES (46894, 467760, 'Trapper''s Delight', 'In Trapper''s Delight players compete to construct deadly labyrinths and then try to escape in one piece. Lure your friends into your deadly trap in local and online multiplayer or test your skills in singleplayer challenges.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/467760/header.jpg?t=1563624499', 0, 0, NULL);
INSERT INTO games VALUES (46898, 467820, 'Zero G Arena', 'Zero G Arena is an arena shooter with zero gravity, ragdoll physics, grappling beams and magnet boots', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/467820/header.jpg?t=1575196661', 0, 0, NULL);
INSERT INTO games VALUES (46866, 467930, 'SMASHING THE BATTLE', 'In the year 2085, a huge multiplex construction site becomes a victim of a massive-scale hacking incident. Due to the hack, the construction robots start to attack the workers onsite.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/467930/header.jpg?t=1688092473', 0, 0, NULL);
INSERT INTO games VALUES (46869, 467960, 'Home Behind', 'In Home Behind, you take on the role of a refugee cast out from your homeland by a band of rebels. Your home and the peace you enjoyed has been destroyed, and your family has disappeared. Can you survive the struggle, famine, and sickness to make it to the safety of Europe?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/467960/header.jpg?t=1683700362', 0, 0, NULL);
INSERT INTO games VALUES (46870, 468050, 'The Last Time', 'The Last Time features the narrative depth and emotional impact of a modern adventure title, delivered with the graphical style and game mechanics of a classic point-and-click. Play as Jack Glover, a frail old man who must come out of retirement to face his demons.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/468050/header.jpg?t=1474798244', 0, 0, NULL);
INSERT INTO games VALUES (46856, 468490, 'Neon Space', 'Neon Space is a fun and simple but at the same time highly addictive game.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/468490/header.jpg?t=1696797376', 0, 0, NULL);
INSERT INTO games VALUES (46853, 468820, 'Titans of Space PLUS', 'Just how big is big? Journey through this holographic Solar System, and then squint your eyes in the intense light of a few of the largest known stars. Enjoy various accidentally-educational activities along the way. Great care has been taken to ensure a comfortable VR experience. VR optional.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/468820/header.jpg?t=1586980270', 0, 0, NULL);
INSERT INTO games VALUES (131874, 469600, 'Legion TD 2 - Multiplayer Tower Defense', 'An infinitely replayable multiplayer and single-player tower defense. Defend against waves of enemies and destroy the enemy''s king before they destroy yours. Legion TD 2 is a one-of-a-kind game of tactics, teamwork, and prediction. Party as 1-8 players.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/469600/header.jpg?t=1741363845', 1, 0, NULL);
INSERT INTO games VALUES (46847, 469610, 'Rick and Morty: Virtual Rick-ality', 'Rick and Morty: Virtual Rick-ality smashes together the absolute VR chaos of the award-winning Job Simulator with the ridiculous, all-out, take-no-prisoners comedy of Rick and Morty.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/469610/header.jpg?t=1580412692', 0, 0, NULL);
INSERT INTO games VALUES (46849, 469720, 'Monsters'' Den: Godfall', 'The popular dungeon-crawling RPG series returns! Take your party into procedurally-generated dungeons, fight in turn-based battles, loot and level up! Explore the land and uncover the mysteries of the Godfall!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/469720/header.jpg?t=1741260789', 0, 0, NULL);
INSERT INTO games VALUES (46828, 469730, 'Super Mega Neo Pug', 'Turbo Pug is back! and this time, he''s airborne! Fly through deserts, green fields and more stunning environments. Dodge an onslaught of enemies and go head to head with giant bosses! Unlock new costumes for Turbo Pug and new creatures to play as. Please try not to squish your pug!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/469730/header.jpg?t=1474358522', 0, 0, NULL);
INSERT INTO games VALUES (46829, 469790, 'Linelight', 'Linelight is an elegant puzzle game set in a world of lines.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/469790/header.jpg?t=1593859494', 0, 0, NULL);
INSERT INTO games VALUES (46830, 469800, 'Evolution Board Game', 'Predators lurk, food is scarce, you must adapt - or go extinct. Evolve your species to survive and dominate as you explore the campaign or go head-to-head with the skill-based matchmaker.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/469800/header.jpg?t=1706717806', 0, 0, NULL);
INSERT INTO games VALUES (46831, 469820, 'Genital Jousting', 'Genital Jousting tells the story of &quot;John&quot;, a penis who needs to find a date for his high school reunion. Genital Jousting is also an online and local multiplayer party game about flaccid penises and wiggly anuses for up to eight players at once.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/469820/header.jpg?t=1720783422', 0, 0, NULL);
INSERT INTO games VALUES (46834, 469920, 'hackmud', 'hackmud is a text-based multiplayer hacking simulator for keyboard-compatible personal home computers. Crack protected systems and solve puzzles as you explore the abandoned internet of the future. Write scripts to protect your winnings and trick other players. Lose everything. Get it back.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/469920/header.jpg?t=1732749426', 0, 0, NULL);
INSERT INTO games VALUES (131529, 470220, 'UNO', 'UNO makes its return with new exciting features! Match cards by color or value and play action cards to change things up. Race against others to empty your hand before everyone else in Classic play or customize your experience with House Rules.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/470220/header.jpg?t=1747655982', 0, 0, NULL);
INSERT INTO games VALUES (46816, 470260, 'Event[0]', 'Event[0] is a sci-fi narrative exploration game where you build a relationship with a lonely spaceship computer to get home to Earth.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/470260/header.jpg?t=1515241553', 0, 0, NULL);
INSERT INTO games VALUES (46820, 470310, 'TROUBLESHOOTER: Abandoned Children', 'TROUBLESHOOTER: Abandoned Children is the first season of a turn-based strategy SRPG that takes place in the world of Troubleshooter.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/470310/header.jpg?t=1747107944', 1, 0, NULL);
INSERT INTO games VALUES (46812, 471010, 'Seven: Enhanced Edition', 'Seven: Enhanced Edition is an open-world, isometric stealth and action role-playing game, in which you play as Teriel, a master thief sent on a mission that will shake the foundations of the Vetrall Empire. Includes the Drowned Past expansion.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/471010/header.jpg?t=1589292453', 0, 0, NULL);
INSERT INTO games VALUES (46800, 471330, 'VERSUS SQUAD', 'Versus Squad is a fast action twin-stick shooter from the creator of Nation Red. Build your own sandbox defense and battle thousands of zombie mutants in top down combat! Face up to a dozen bosses. Simultaneously. Collect loot, build and repair. Play single player, on-line or local coop!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/471330/header.jpg?t=1669304601', 0, 0, NULL);
INSERT INTO games VALUES (46803, 471550, 'Nine Parchments', 'Nine Parchments is a co-operative blast''em up game of magic mayhem from Frozenbyte, creators of the Trine series!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/471550/header.jpg?t=1725007138', 0, 0, NULL);
INSERT INTO games VALUES (46807, 471660, 'Kingspray Graffiti VR', 'Hanging out with friends, bombing walls, and smashing bottles would be much more fun with out the jail time.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/471660/header.jpg?t=1518090345', 0, 0, NULL);
INSERT INTO games VALUES (46795, 471810, 'Death Squared', 'Death Squared is a co-op puzzle game about cooperation, communication, and robot explosions. You should buy it!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/471810/ee319cde346eef381669f3807c2461d40f87d5fd/header_alt_assets_1.jpg?t=1747120614', 1, 0, NULL);
INSERT INTO games VALUES (46790, 472420, 'Duke Grabowski, Mighty Swashbuckler', 'Duke Grabowski: Mighty Swashbuckler is a classic point-and-click adventure, created with love by an indie team that includes LucasArts alumni, Bill Tiller (The Curse of Monkey Island, Steven Spielberg''s The Dig, Indiana Jones and the Infernal Machine).', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/472420/header.jpg?t=1493400716', 0, 0, NULL);
INSERT INTO games VALUES (46789, 472870, 'Higurashi When They Cry Hou - Ch.3 Tatarigoroshi', 'Higurashi When They Cry is a sound novel. The music, backgrounds and characters work together to create a world that is the stage of a novel for the user to read. They laugh and cry and get angry. The user takes the point of view of the protagonist to experience the story.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/472870/header.jpg?t=1725522979', 0, 0, NULL);
INSERT INTO games VALUES (46774, 473560, 'Cosmic Dust & Rust', 'Cosmic Dust &amp; Rust is a tower defence game set in space. Upgrade your ship, build turrets and defence systems, undergo side missions and take control of your ship manually and use its cannons and super weapons to destroy your enemies.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/473560/header.jpg?t=1463512379', 0, 0, NULL);
INSERT INTO games VALUES (46777, 473690, 'Absolver', 'Absolver is an online multiplayer combat game where players are placed behind the mask of a Prospect under control of the Guides, the new rulers of the fallen Adal Empire, who will determine your worth in joining their elite corps of Absolvers.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/473690/header.jpg?t=1728689155', 0, 0, NULL);
INSERT INTO games VALUES (135698, 473770, 'BallisticNG', 'BallisticNG is a high speed, all thrills anti-gravity combat racer and open modding environment developed as a tribute to old school classics such as Wipeout, Rollcage and Jet Moto.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/473770/header.jpg?t=1746111732', 0, 0, NULL);
INSERT INTO games VALUES (46754, 473910, 'The Nest', 'The Nest has been reborn, and now it is Multiplayer! Join friends or strangers to battle for control of the last reserves of &quot;crypto&quot; in the system. Try multiple classes, maps and game modes, and choose to support the enigmatic Angroid, or the treacherous DieOS.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/473910/header.jpg?t=1548963665', 0, 1, NULL);
INSERT INTO games VALUES (46755, 473920, 'Corinne Cross''s Dead & Breakfast', 'A story-driven adventure game about a haunted bed &amp; breakfast. A dead &amp; breakfast!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/473920/header.jpg?t=1667679993', 0, 0, NULL);
INSERT INTO games VALUES (46756, 473950, 'Manifold Garden', 'Rediscover gravity and explore an Escher-esque world of impossible architecture. Witness infinity in first-person and master its rules to solve physics-defying puzzles. Cultivate a garden to open new paths forward, where an eternal expanse awaits.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/473950/header.jpg?t=1603220474', 1, 0, NULL);
INSERT INTO games VALUES (46759, 474020, 'Ragnorium', 'Lead a team of cloned settlers and build a home on a new planet. Start from the Stone Age, construct sturdy shelters, hunt for food, and fight off dangers. Make your team stronger and better equipped to survive.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/474020/header.jpg?t=1728689092', 0, 0, NULL);
INSERT INTO games VALUES (46762, 474210, 'BUTCHER', 'BUTCHER is a fast-paced, blood-soaked 2D shooter where carnage is the only way forward. Become a ruthless cyborg tasked with eradicating humanity, leaving nothing but blood, guts, and destruction in your wake. There''s no such thing as too much violence in this grim, retro-styled gorefest.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/474210/header.jpg?t=1741358342', 0, 0, NULL);
INSERT INTO games VALUES (46763, 474220, 'Soldat 2', 'Soldat 2 is a 2D deathmatch shooter with real guns, ragdoll violence and physics-based movement. Based on classic Soldat with team game modes, ranked multiplayer, bots and built-in customization and level editing. Made by MM - creator of the original.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/474220/header.jpg?t=1727253409', 0, 0, NULL);
INSERT INTO games VALUES (46753, 474750, 'Reigns', 'Sit on the throne as a benevolent (or malevolent) medieval monarch of the modern age and swipe your royal controller either left or right to impose your will upon the kingdom.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/474750/header.jpg?t=1728689014', 1, 0, NULL);
INSERT INTO games VALUES (46741, 474890, 'Uncrewed', 'Uncrewed is a real-time strategy game with the ability to design units from scratch. Unlike in more traditional RTS, units obey the laws of physics, making design choices especially important.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/474890/header.jpg?t=1744394239', 0, 0, NULL);
INSERT INTO games VALUES (46743, 474960, 'Quantum Break', 'From Remedy Entertainment, the masters of cinematic action games, comes Quantum Break, a time-amplified suspenseful blockbuster. The Quantum Break experience is part game, part live action show—where decisions in one dramatically affect the other.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/474960/header.jpg?t=1682524073', 1, 0, NULL);
INSERT INTO games VALUES (46744, 474980, 'Cat President ~A More Purrfect Union~', 'Find love, in a world where cats run the U.S. government!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/474980/header.jpg?t=1701476741', 0, 0, NULL);
INSERT INTO games VALUES (46749, 475150, 'Titan Quest Anniversary Edition', 'For its 10 year anniversary, Titan Quest will shine in new splendour. This Anniversary Edition combines both Titan Quest and Titan Quest Immortal Throne in one game, and has been given a massive overhaul for the ultimate ARPG experience.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/475150/header.jpg?t=1725002025', 1, 0, NULL);
INSERT INTO games VALUES (46750, 475190, 'Scanner Sombre', 'Scanner Sombre is a 3d horror cave exploration game where darkness is your greatest foe. Illuminate the unseen with your LIDAR scanner, revealing the eerie beauty and peril of the abyss. From the creators of Prison Architect, this immersive adventure uses light and shadow for a haunting experience.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/475190/header.jpg?t=1739424284', 1, 0, NULL);
INSERT INTO games VALUES (46732, 475240, 'ORCS', 'ORCS is an action/platformer 2D old school inspirated by classic like Castlevania and Ghosts ''n Goblins.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/475240/header.jpg?t=1480991923', 0, 0, NULL);
INSERT INTO games VALUES (46733, 475490, 'Major\\Minor', 'A highly engaging visual novel, with memorable characters and multiple endings. Traverse worlds, solve a murder mystery -- and partake in political revolution. Inspired by greats such as Steins;Gate, Tales of Symphonia, Persona 4 and Future Diary. An unforgettable science-fiction/fantasy adventure!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/475490/header.jpg?t=1725548265', 0, 1, NULL);
INSERT INTO games VALUES (46736, 475550, 'Beholder', 'You’re a state-installed landlord in a totalitarian country. Place listening devices, steal and sneak into your tenants’ apartments. Use what you uncovered to report anyone capable of plotting against the state. You MUST! But WILL you?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/475550/header.jpg?t=1745830980', 1, 0, NULL);
INSERT INTO games VALUES (46716, 476240, 'KNIGHTS', 'KNIGHTS is a minimalist puzzle game based on a single chess piece, the titular knight. A simple enough to pick up and relaxing experience.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/476240/header.jpg?t=1636745215', 0, 0, NULL);
INSERT INTO games VALUES (46719, 476420, 'Heart of Crown PC', 'Which princess will you promote in this battle of succession? Heart of Crown is a deck-building card game with online play, scenario campaigns, and free play which offer a wide variety of challenges and enjoyment to be had.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/476420/header.jpg?t=1589815121', 1, 0, NULL);
INSERT INTO games VALUES (46726, 476530, 'Children of a Dead Earth', 'The most scientifically accurate space warfare simulator ever made. Now with Steam Workshop!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/476530/header.jpg?t=1726719703', 0, 0, NULL);
INSERT INTO games VALUES (46708, 476600, 'Call of Duty®: WWII', 'Call of Duty® returns to its roots with Call of Duty®: WWII - a breathtaking experience that redefines World War II for a new gaming generation.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/476600/header.jpg?t=1748041216', 1, 0, NULL);
INSERT INTO games VALUES (46709, 476620, 'Call of Duty®: WWII', 'Call of Duty® returns to its roots with Call of Duty®: WWII - a breathtaking experience that redefines World War II for a new gaming generation.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/476600/header.jpg?t=1748041216', 1, 0, NULL);
INSERT INTO games VALUES (46710, 476650, 'The Silver Case', 'The Silver Case – the debut title from world-renowned developer SUDA51 has been fully remastered and localized to English for the first time ever!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/476650/header.jpg?t=1613724291', 0, 0, NULL);
INSERT INTO games VALUES (46713, 476700, 'Island 359™', 'Island 359 is a Virtual Reality survival game for the HTC Vive and Oculus Touch. Players will scrounge for weapons, upgrades, food, and other items they can find to survive for as long as they can against hordes of dinosaurs, as they explore the increasingly dangerous, beautiful, and expansive island.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/476700/header.jpg?t=1626902447', 0, 0, NULL);
INSERT INTO games VALUES (46700, 477160, 'Human Fall Flat', 'Human Fall Flat is a hilarious, light-hearted platformer set in floating dreamscapes that can be played solo or with up to 8 players online. Free new levels keep its vibrant community rewarded.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/477160/601a86df5fb603914ec6ec06792abd0dc4abe4e8/header_alt_assets_24.jpg?t=1749030392', 1, 0, NULL);
INSERT INTO games VALUES (46705, 477270, 'Lightblade VR', 'Lightblade VR is a virtual reality training simulation for self-illumintated plasma blades. This is a childhood dream come true! Get trained by your personal robot and deflect all incoming laser beams!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/477270/header.jpg?t=1470089258', 0, 0, NULL);
INSERT INTO games VALUES (46687, 477730, 'Eador. Imperium', 'Hire heroes, build an army, prevail in battles and try to keep your empire intact in the face of grave danger. Eador. Imperium is a new chapter in Eador series, known for its unique blend of grand strategy, turn-based tactics and RPG elements.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/477730/header.jpg?t=1571149138', 0, 0, NULL);
INSERT INTO games VALUES (46688, 477740, 'Zero Escape: The Nonary Games', 'Kidnapped and taken to an unfamiliar location, nine people find themselves forced to participate in a diabolical Nonary Game by an enigmatic mastermind called Zero. Why were they there? Why were they chosen to put their lives on the line? And more importantly, who can be trusted?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/477740/header.jpg?t=1715699741', 0, 0, NULL);
INSERT INTO games VALUES (46690, 477770, 'Ride 2', 'The fastest and most iconic bikes in the world''s biggest digital garage!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/477770/header.jpg?t=1728470230', 0, 0, NULL);
INSERT INTO games VALUES (46693, 477870, 'Yomawari: Night Alone', 'A quiet evening stroll takes a turn for the worse as a tragic accident befalls a little girl and her dog. When her sister goes missing later in the night, the little girl decides to venture out into the eerie darkness to search for her loved ones as evil spirits haunt the alleyways and streets of her once-peaceful town.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/477870/header.jpg?t=1732665491', 0, 0, NULL);
INSERT INTO games VALUES (46680, 479010, 'Kodon', 'Kodon is a 3D sculpting software for VR and Desktop. We make beginners experts with our intuitive, easy to learn interface, and invite experts to become gods through speed, immersion and feel.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/479010/header.jpg?t=1704150000', 0, 0, NULL);
INSERT INTO games VALUES (46668, 479100, 'Music Wars Empire', 'Take the role of a manager or CEO of a record label, and try to make your mark on the music industry!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/479100/header.jpg?t=1716307428', 0, 0, NULL);
INSERT INTO games VALUES (46666, 480430, 'Hide and Shriek', 'Scare or be scared in this FREE adrenaline-pumping multiplayer game full of hijinks and mischief! Set traps, cast spells, and scare the living hell out of your opponent to win!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/480430/header.jpg?t=1675332629', 1, 1, NULL);
INSERT INTO games VALUES (46667, 480450, 'Floppy Heroes', 'Floppy Heroes is a ragdoll physics brawler with dismemberment, a wide range of weapons and armor, very simple controls, and custom battles playable with up to 6 local players.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/480450/header.jpg?t=1482400679', 0, 0, NULL);
INSERT INTO games VALUES (46658, 480490, 'Prey', 'In Prey, you awaken aboard Talos I, a space station orbiting the moon in the year 2032. You are the key subject of an experiment meant to alter humanity forever – but things have gone terribly wrong. The space station has been overrun by hostile aliens and you are now being hunted.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/480490/header.jpg?t=1741275660', 0, 0, NULL);
INSERT INTO games VALUES (46659, 480640, 'Pathfinder Adventures', 'Pathfinder Adventures translates the best-selling Pathfinder Adventure Card Game into an entirely new breed of digital card game, where players adventure collaboratively to battle monsters and villains, and acquire new feats, items, weapons, and allies.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/480640/header.jpg?t=1726058377', 0, 0, NULL);
INSERT INTO games VALUES (46654, 481110, 'The Bunker', 'The Bunker is an award-winning interactive psychological horror movie. You are John, born underground the day the bombs fell, now alone and trying to survive. But when an alarm goes off, a catastrophic chain of events begins. Unlock the dark secrets of your past as you try to escape The Bunker.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/481110/header.jpg?t=1727965361', 1, 0, NULL);
INSERT INTO games VALUES (46655, 481180, 'System Crash', 'System Crash is a story-driven cyberpunk collectible card game inspired by Blade Runner and Neuromancer. When corporations own everything and the line between man and machine is blurred, your only option is to fight to survive!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/481180/header.jpg?t=1671717611', 0, 0, NULL);
INSERT INTO games VALUES (46656, 481190, 'Stable Orbit - Build your own space station', 'Design, build and control your own space station. Mission command and control is in your hands and only careful planning and vigilant supervision will keep your crew and space station safe.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/481190/header.jpg?t=1667209601', 0, 0, NULL);
INSERT INTO games VALUES (46652, 481510, 'Night in the Woods', 'NIGHT IN THE WOODS is an adventure game focused on exploration, story, and character, featuring dozens of characters to meet and lots to do across a lush, vibrant world.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/481510/header.jpg?t=1706292417', 0, 0, NULL);
INSERT INTO games VALUES (46649, 482300, 'Investigator', 'Investigator is a first-person exploration game with horror elements, where the events take place in a world of extreme weather cataclysms.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/482300/header.jpg?t=1722681228', 0, 0, NULL);
INSERT INTO games VALUES (46642, 482400, 'System Shock', 'A first-person fight to the death in the depths of space!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/482400/header.jpg?t=1747063472', 1, 0, NULL);
INSERT INTO games VALUES (46643, 482450, 'Nitroplus Blasterz: Heroines Infinite Duel', 'The hit crossover 2D fighter finally makes its way to PC, updated to the latest arcade version for character balancing, added background animations and additional winning poses. It also includes all DLC from the console release, such as additional fighters Homura and Heart, in a single value package.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/482450/header.jpg?t=1741824648', 0, 0, NULL);
INSERT INTO games VALUES (46637, 483770, 'Autobahn Police Simulator 2', 'Start your even more exciting career as law enforcer on Europe’s fastest road now with the successor to the popular Autobahn Police Simulator. For the first time in Autobahn Police Simulator 2 you can use the Character Creator to customize your own in-game character.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/483770/header.jpg?t=1726491690', 0, 0, NULL);
INSERT INTO games VALUES (46629, 483950, 'SMILE GAME BUILDER', 'SMILE GAME BUILDER is a game making software. Programming is NOT a required skill! All necessary materials are included such as 3D models, graphics, music and more. NOW, all you need is your creativity!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/483950/header.jpg?t=1705548158', 0, 0, NULL);
INSERT INTO games VALUES (46630, 483960, 'Purino Party', 'Purino Party takes one part puzzle game, and one part visual novel - romancing cute girls included - and combines them for a laid-back yet addictive gameplay experience!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/483960/header.jpg?t=1742524783', 0, 0, NULL);
INSERT INTO games VALUES (46632, 483980, 'Mad Father', 'Witness the tale of a most foolish family. A remake of the classic horror exploration game makes its way to Steam.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/483980/header.jpg?t=1735191803', 1, 0, NULL);
