INSERT INTO games VALUES (46626, 484870, 'Battle Dome', 'Have a virtual shootout with other players! Work by yourself or with teammates to achieve victory. Will you survive the Battle Dome?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/484870/header.jpg?t=1549963013', 0, 0, NULL);
INSERT INTO games VALUES (46628, 484900, 'Aven Colony', 'Build a new home for humanity in Aven Colony. Discover Aven Prime - an alien planet of deserts, tundras, and wetlands light years from earth. Build your colonies into massive, sprawling cities whilst dealing with the challenges faced when settling on a new world.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/484900/header.jpg?t=1726588686', 0, 0, NULL);
INSERT INTO games VALUES (46610, 484950, '恶魔迷宫 | Evil Maze', 'Random Iiem and Skills + Hidden elements RPG + Strategy ARPG The game starts in a dark underground maze where a female officer is confined in a prison. She wants to get out of this nightmare maze! Would you like to help her?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/484950/header.jpg?t=1702900523', 0, 0, NULL);
INSERT INTO games VALUES (46612, 485030, 'PLANET ALPHA', 'PLANET ALPHA, a beautiful alien world filled with mystery and danger. Pursued by relentless enemies, you must harness the power of night and day as you struggle to survive.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/485030/header.jpg?t=1741698419', 1, 0, NULL);
INSERT INTO games VALUES (46613, 485040, 'Nurse Love Addiction', 'Follow Asuka Osachi, a ditzy girl training to become a nurse at Teito Nursing School. Experience her story with her classmates as they discover love, medicine, and adulthood.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/485040/header.jpg?t=1734022626', 1, 0, NULL);
INSERT INTO games VALUES (46574, 485350, 'Winter Novel', 'Snow, dullness, depression. Constant dissatisfaction with work and superiors and feeling like there is no escape. Is this what life will always be? Perhaps… but I can always hope for change to be just around the corner!…', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/485350/header.jpg?t=1668887297', 0, 0, NULL);
INSERT INTO games VALUES (46576, 485370, 'Mad Combat Marines', 'Are you ready to eliminate hordes of enemies and have fun as you compete against people from all over the world? Mad Combat Marines is here for you and it delivers all of that in an incredibly action-packed challenge!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/485370/header.jpg?t=1685799868', 0, 0, NULL);
INSERT INTO games VALUES (46577, 485380, 'Welcome to the Game', 'Welcome to the Game is a creepy horror/puzzle game that takes you into the world of the Deep Web. Explore the Deep Web with the sole purpose of trying to find a Red Room, an online service / website that allows you to see and participate in interactive torture and murder.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/485380/header.jpg?t=1478826657', 0, 0, NULL);
INSERT INTO games VALUES (46579, 485400, 'Mechajammer', 'A tactical cyberpunk turn-based RPG set on an off-world grindhouse jungle colony. Skulk through the shadows or charge in guns blazing. Recruit a unique party for large squad-based assaults as your adventure plunges you deep into the city’s secrets.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/485400/header.jpg?t=1648216001', 0, 0, NULL);
INSERT INTO games VALUES (46582, 485460, 'The Banner Saga 3', 'Banner Saga 3 is the epic conclusion to a sweeping viking saga six years in the making. This strategic RPG, acclaimed for its strong story and compelling characters has won over 20 awards and been nominated for 4 BAFTA awards.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/485460/header.jpg?t=1642181012', 0, 0, NULL);
INSERT INTO games VALUES (46585, 485510, 'Nioh: Complete Edition', 'Ready to die? Experience the newest brutal action game from Team NINJA and Koei Tecmo Games. In the age of samurai, a lone traveler lands on the shores of Japan. He must fight his way through the vicious warriors and supernatural Yokai that infest the land in order to find that which he seeks.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/485510/header.jpg?t=1749099959', 1, 0, NULL);
INSERT INTO games VALUES (46589, 485610, 'Soccer Online: Ball 3D', 'Soccer simulator. Control one player and kick the ball high or low, hard or lightly, curve, dribble and perform tricks. Play online or with bots. Join over a million players who have already played. Buy now and have fun or wishlist for later.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/485610/0becb5b8e325d08101422223602d6e68abafa9e5/header.jpg?t=1745755576', 1, 0, NULL);
INSERT INTO games VALUES (46595, 485670, 'Mini Golf Arena', 'Mini Golf Arena is an exciting multiplayer mini golf game for up to 24 players online. Build &amp; play custom maps together with your friends.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/485670/header.jpg?t=1667070812', 0, 0, NULL);
INSERT INTO games VALUES (46597, 485690, 'Hope Lake', 'The Hope Lake Boarding School was abandoned long ago, when one of its teachers drowned by accident. Many years later, all of the female students began to disappear, one by one. Visit the place where it all began. Try to pick up the maniac''s trail and put a stop to his crime spree.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/485690/header.jpg?t=1657308419', 0, 0, NULL);
INSERT INTO games VALUES (46607, 485870, 'Super Duper Party Pooper', 'Created by solo developer Nikola Kostic - Have you ever wanted to poop on party goers but were too socially awkward to just go for it? Well, Super Duper Party Pooper is about to change all that, the player will find themselves in the middle of a raw human story of existential panic.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/485870/header.jpg?t=1631224663', 0, 0, NULL);
INSERT INTO games VALUES (46559, 485890, 'Summer Sale', 'Experience Winter Sale without losing money.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/485890/header.jpg?t=1482208650', 0, 0, NULL);
INSERT INTO games VALUES (46560, 485900, 'Hardware Engineers', 'Hardware Engineers is a simulation game where you have to manage a IT business. In a world where technology expands every day, you will need to learn how to be competitive.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/485900/header.jpg?t=1561117451', 0, 0, NULL);
INSERT INTO games VALUES (46564, 485980, 'Syrian Warfare', 'Real Time Strategy with a high degree of realism. The game is based on a true story.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/485980/header.jpg?t=1727877519', 0, 0, NULL);
