INSERT INTO games VALUES (46540, 486380, 'Shigatari', 'Shigatari is a samurai role-playing game with historical artwork.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/486380/header.jpg?t=1578855434', 0, 0, NULL);
