INSERT INTO games VALUES (46553, 486650, 'Potato Thriller', 'Known for deep frying his victims, Potato Man is the most notorious serial killer out there...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/486650/header.jpg?t=1682359428', 0, 0, NULL);
