INSERT INTO games VALUES (46518, 486780, 'Fruit Ninja VR', 'Step inside the Fruit Ninja universe and experience a slice of virtual reality like never before. Play Fruit Ninja VR now!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/486780/header.jpg?t=1700711378', 1, 0, NULL);
