INSERT INTO games VALUES (46531, 487220, 'Freebie', 'Freebie is a casual game where you launch a ball against a paddle and hit a green surface. Be careful not to hit the red surfaces or you''ll lose a life!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/487220/header.jpg?t=1487735849', 0, 0, NULL);
INSERT INTO games VALUES (46508, 487370, 'Akin', 'In this puzzle, you only have to draw one continuous line. There are 96 puzzles on &quot;Normal&quot;-mode and 96 puzzles in &quot;Time&quot;-mode. Each puzzles can have many different solutions. This is game is Steamworks integrated with achivements, badges, trading cards and more.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/487370/header.jpg?t=1739461915', 0, 0, NULL);
