INSERT INTO games VALUES (46505, 488280, 'Gun Done', 'Gun Done - it''s a timekiller arcade game about brave heroes', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/488280/header.jpg?t=1712565936', 1, 0, NULL);
INSERT INTO games VALUES (46506, 488300, 'Infinite Air with Mark McMorris', 'Join pro snowboarder Mark McMorris and an elite crew of riders in a vast, open-world snowboarding experience. Compete in authentic events, drop in on any mountain peak by helicopter, and design your own snow parks to shred with the World Editor.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/488300/header.jpg?t=1572541032', 0, 0, NULL);
INSERT INTO games VALUES (46478, 488310, 'Eleven Table Tennis', 'We''re obsessed with creating the most realistic VR table tennis simulator the world has ever seen. After 5 years and countless hours of hard work, we believe that we have accomplished that goal.: : : [Play over Oculus Link/AirLink/Virtual Desktop Not Recommended: the tracking will be much worse]', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/488310/header.jpg?t=1638826667', 1, 0, NULL);
INSERT INTO games VALUES (46485, 488550, 'Dream Car Builder', 'Design your car from scratch: from the frame to the suspension and race it!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/488550/header.jpg?t=1576305639', 0, 0, NULL);
INSERT INTO games VALUES (46488, 488660, 'Just Deserts', 'Just Deserts is a sci-fi action dating sim where you play as a soldier who must protect a city from mysterious alien attack, while at the same time you will also be seeking to capture the heart of your dream girl(s)! Theme song by Vesuvia [Ecky], vocal track by iMochi', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/488660/header.jpg?t=1738224219', 0, 0, NULL);
