INSERT INTO games VALUES (46476, 489020, 'iGrow Game', 'iGrow Game is a single player cannabis growing game for windows PC. iGrow game is the only cannabis growing game available in 3D and in first person. Start your own cannabis growing factory in a grimy tower block based in the UK. Your goal is to take over and become the best grower around using the best equipment.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/489020/header.jpg?t=1629049598', 0, 0, NULL);
