INSERT INTO games VALUES (46440, 489600, 'The Golf Club VR', 'The Golf Club VR is built off the foundation laid by HB Studios’ original award winning game released in 2014, The Golf Club, taking advantage of the original game’s stunning visual presentation and over 130,000, two kilometer² procedurally and user-generated courses.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/489600/header.jpg?t=1487967580', 0, 0, NULL);
