INSERT INTO games VALUES (46442, 489630, 'Warhammer 40,000: Gladius - Relics of War', 'Warhammer 40,000: Gladius – Relics of War brings you to a world of terror and violence. Four factions will engage in a brutal war for dominance over the planet’s resources. In the first turn-based 4X strategy game set in Warhammer 40,000 you will lead one of four unique factions.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/489630/header.jpg?t=1747933905', 0, 0, NULL);
INSERT INTO games VALUES (137737, 489830, 'The Elder Scrolls V: Skyrim Special Edition', 'Winner of more than 200 Game of the Year Awards, The Elder Scrolls V: Skyrim Special Edition brings the epic fantasy to life in stunning detail. The Special Edition includes the critically acclaimed game and add-ons with all-new features.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/489830/header.jpg?t=1721923149', 0, 0, NULL);
