INSERT INTO games VALUES (46427, 489940, 'BATTALION: Legacy', 'BATTALION: Legacy recaptures the core of classic shooters in the final iteration of Battalion 1944. Return to the simple days of playing first person shooters with your friends. Grab your bolt action rifle in ''rifles only'' mode or compete in 5v5 Search and Destroy.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/489940/header.jpg?t=1660846889', 0, 1, NULL);
