INSERT INTO games VALUES (46416, 490280, 'Realms of Magic', 'Embark on a journey through the Old Kingdom in Realms of Magic - a sandbox RPG where you customize your character, choose your path, and immerse yourself in the fantasy world as a knight, wizard, miner, lumberjack, farmer, and more. After all, this is YOUR adventure.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/490280/header.jpg?t=1745487219', 0, 0, NULL);
