INSERT INTO games VALUES (46400, 491000, 'Gravity Cat', 'Gravity Cat - it''s a puzzle-platformer. You play as a cat who has an ability to change the gravity.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/491000/header.jpg?t=1575410544', 0, 0, NULL);
INSERT INTO games VALUES (46403, 491040, 'Bot Vice', 'Show off your skills &amp; reflexes in this frantic gallery shooter action arcade, filled with bullets, bots and explosions! You play as Erin Saver, carrying out her personal vendetta against the criminal Wildbots.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/491040/header.jpg?t=1725009331', 0, 0, NULL);
INSERT INTO games VALUES (46406, 491090, 'Ant Queen', 'Begin a journey like no other, become the Ant Queen and establish your empire. Ant Queen is a simulation game where you breed different types of ants to ultimately conquer your surroundings and achieve a stable ant colony.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/491090/header.jpg?t=1470926942', 0, 0, NULL);
INSERT INTO games VALUES (46375, 491280, 'Drift Horizon Online', 'Drift Horizon Online- Drifting simulation game!- Nice &amp; optimized graphics!- Realistic car sounds (Blow off, Exhaust, Backfires, Skids, etc)!- Realistic physics!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/491280/header.jpg?t=1742680514', 0, 0, NULL);
INSERT INTO games VALUES (46376, 491330, '12 Labours of Hercules V: Kids of Hellas (Platinum Edition)', 'With your help, Hercules must return the kids home, blow up the factory that produces the evil toys, and lead a strategic operation to destroy Ares'' command transmitter in 12 Labours of Hercules V: Kids of Hellas!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/491330/header.jpg?t=1502273387', 0, 0, NULL);
INSERT INTO games VALUES (46386, 491530, 'Notruf 112 | Emergency Call 112', 'Emergency Call 112 – The Fire Fighting Simulation is an exciting, fully detailed simulation of the eventful life of a big city fire department. It was developed in cooperation with and modelled on the fire brigade of Mülheim, Germany. Mülheim has one of the largest and most modern fire stations in Europe.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/491530/header.jpg?t=1667832079', 0, 0, NULL);
INSERT INTO games VALUES (131845, 491540, 'The Bus', 'The Bus is the next generation of city bus driving simulation. Sell tickets and transport passengers with various buses on different lines across the German capital Berlin on a realistic scale of 1:1.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/491540/header.jpg?t=1747290783', 0, 0, NULL);
INSERT INTO games VALUES (46369, 491950, 'Orwell: Keeping an Eye On You', 'Big Brother has arrived - and it’s you. Investigate the lives of citizens to find those responsible for a series of terror attacks. Information from the internet, personal communications and private files are all accessible to you. But, be warned, the information you supply will have consequences.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/491950/header.jpg?t=1744397709', 0, 0, NULL);
