INSERT INTO games VALUES (46344, 492230, 'Space Hulk: Tactics', 'Space Hulk: Tactics is a faithful adaptation of the board game Space Hulk, set in the Warhammer 40,000 universe, bringing a unique twist to the cult classic formula. Engage in bloody battles as either a squad of Terminator Space Marines or the deadly alien Genestealers.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/492230/header.jpg?t=1712314110', 0, 0, NULL);
