INSERT INTO games VALUES (46324, 493580, 'Hidden Object - 12 in 1 bundle', 'Play awesome stories with this 12 in 1 Hidden Object Games Bundle : Investigate, solve mysteries in these games with various themes !', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/493580/header.jpg?t=1570011107', 0, 0, NULL);
INSERT INTO games VALUES (46290, 493720, 'Haven Moon', 'Haven Moon will transport you to a mysterious world where you have to explore abandoned islands and solve their secrets to find a treasure. In this Myst-like game inspired by Jules Verne’s universe, use your senses and intelligence to find your way through secret passages and curious machinery.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/493720/header.jpg?t=1667202967', 0, 0, NULL);
