INSERT INTO games VALUES (46016, 500810, 'Arcanum: Of Steamworks and Magick Obscura', 'Imagine a place of wonder, where magick and technology coexist in an uneasy balance, and an adventurer might just as easily wield a flintlock pistol as a flaming sword. Welcome to the land of Arcanum.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/500810/header.jpg?t=1472585780', 0, 0, NULL);
INSERT INTO games VALUES (46025, 501080, 'Fishing: Barents Sea', 'Commercial fishing on the Barents Sea! Take the helm of your very own fishing boat in Fishing: Barents Sea and explore the vastness of the Barents Sea in search for the best fishing zones. Start out small and earn officially licensed Scanmar Equipment and the officially licensed Hermes trawler.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/501080/header.jpg?t=1748452367', 1, 0, NULL);
INSERT INTO games VALUES (46028, 501120, 'Clock Simulator', 'Clock Simulator is a mindful game of rhythm and focus in which YOU are the clock. Click once a second, every second. Don''t be late. Don''t hurry. There''s nothing else to be concerned with. Clear your mind and discover new depths of relaxation while becoming time itself!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/501120/header.jpg?t=1724073144', 0, 0, NULL);
INSERT INTO games VALUES (45990, 501300, 'What Remains of Edith Finch', 'What Remains of Edith Finch is a collection of strange tales about a family in Washington state. As Edith, you’ll explore the colossal Finch house, searching for stories as she explores her family history and tries to figure out why she''s the last one in her family left alive.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/501300/header.jpg?t=1729098797', 1, 0, NULL);
INSERT INTO games VALUES (45992, 501320, 'The Shrouded Isle', 'Includes the Sunken Sins free DLC! Your Excellency, in this short game, we prepare for the awakening of our Lord. He hungers for human sacrifice. Sinners try to hide their dark secrets, but all must be purged...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/501320/header.jpg?t=1726684837', 1, 0, NULL);
INSERT INTO games VALUES (46004, 501590, 'Bulletstorm: Full Clip Edition', 'Step into the boots of Grayson Hunt after a crash landing on an old resort planet forces him to make a hard choice: survival or revenge. Execute masterful kills with Bulletstorm: Full Clip Edition’s unique combat system that rewards you for performing the most creative and deadly kills imaginable.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/501590/header.jpg?t=1749243912', 0, 0, NULL);
INSERT INTO games VALUES (45974, 501790, 'Unforeseen Incidents', 'Unforeseen Incidents is a classical style interactive mystery set in a beautifully hand-painted world. Join Harper Pendrell and experience a challenging investigation, smart dialog and a rich cast of characters in this thrilling new adventure game.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/501790/header.jpg?t=1745774635', 0, 0, NULL);
INSERT INTO games VALUES (45981, 501970, 'Phantasmagoria 2: A Puzzle of Flesh', 'All Curtis wants is to live a normal, happy life, but something seems to have other plans...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/501970/header.jpg?t=1472524441', 0, 0, NULL);
INSERT INTO games VALUES (45982, 501990, 'Phantasmagoria', 'Master storyteller Roberta Williams challenges you to experience the ultimate interactive nightmare.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/501990/header.jpg?t=1661357725', 0, 0, NULL);
INSERT INTO games VALUES (45951, 502230, 'Monsters'' Den: Book of Dread', 'Enter the Monsters'' Den, a place of endless adventure, battle and reward! Lead your party of four heroes through each level of the ever-changing dungeon, fighting in turn-based battles and hunting for that elusive rare loot. The web-game classic comes to Steam!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/502230/header.jpg?t=1689911598', 0, 0, NULL);
INSERT INTO games VALUES (45957, 502370, 'Warhammer 40,000: Sanctus Reach', 'Warhammer 40,000: Sanctus Reach is a 3D turn-based strategy game like you’ve never seen before: fast, immediate, deep, impressive to look at and incredibly fun! Fight through a dark era of carnage and endless war and lead the Space Wolves in a struggle to defend the last bastion of mankind.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/502370/header.jpg?t=1747740019', 0, 0, NULL);
INSERT INTO games VALUES (45968, 502500, 'ACE COMBAT™ 7: SKIES UNKNOWN', 'Become an ace pilot and soar through photorealistic skies with full 360 degree movement; down enemy aircraft and experience the thrill of engaging in realistic sorties! Aerial combat has never looked or felt better!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/502500/header.jpg?t=1737108523', 1, 0, NULL);
INSERT INTO games VALUES (45969, 502520, 'Ultimate General: Civil War', 'Ultimate General: Civil War is a tactical real time strategy war-game. Experience the bloodiest period of U.S. history - the American Civil War of 1861-1865.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/502520/header.jpg?t=1714903654', 1, 0, NULL);
INSERT INTO games VALUES (140199, 502570, 'Houdini Indie', 'Houdini Indie''s procedural node-based workflow offers a smarter way to create high quality game art. Houdini technology is used by AAA studios to take their games to the next level and now this procedural power is also available to indie game devs around the world.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/502570/header.jpg?t=1742850612', 0, 0, NULL);
INSERT INTO games VALUES (45923, 502710, 'The Last Sniper VR', 'Travel back in time to WW2 and experience what it was like to fight as a soldier in room space Virtual Reality. The Last Sniper aims to simulate the sounds, visuals and feel of what it might have been like to be a soldier in a truly massive and horrifying war.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/502710/header.jpg?t=1474829879', 0, 0, NULL);
INSERT INTO games VALUES (45924, 502720, 'Star Explorers', 'Planets, aliens, resources, upgrades, caves, mapping &amp; documenting star systems ... seek a new home for the human race. An all-inclusive (admittedly janky) procedural space-sim made by solo developer Schmidt Workshops.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/502720/header.jpg?t=1732719078', 0, 0, NULL);
INSERT INTO games VALUES (45926, 502740, '50 years', '50 Years is a fast-paced alternative to the bigger, longer turn-based strategy games. You can win or lose a game in a single evening. Either way you''ll want to play it again.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/502740/header.jpg?t=1693225939', 0, 0, NULL);
INSERT INTO games VALUES (45927, 502750, 'Quest for Glory 1-5', 'The world of Gloriana, with all its wonderful diversity, awaits you.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/502750/header.jpg?t=1472524232', 0, 0, NULL);
INSERT INTO games VALUES (45928, 502770, 'Voodoo Garden', 'Welcome to the Voodoo Garden! You''re owner of a little hut in a bustling swamp. With the help of little spirits you can earn powers and gold by producing various voodoo supplies.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/502770/header.jpg?t=1669191153', 0, 0, NULL);
INSERT INTO games VALUES (45930, 502800, 'SENRAN KAGURA ESTIVAL VERSUS', 'Thrust into a parallel dimension, our buxom shinobi prepare for a new kind of beach-side battle. Can the islands’ hosts be trusted? Will the other schools play fair? Will there be time to enjoy the beach before the fighting starts? Will anyone manage to keep their clothes intact?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/502800/header.jpg?t=1741903875', 1, 0, NULL);
INSERT INTO games VALUES (45932, 502820, 'Batman™: Arkham VR', 'Experience Gotham City through the eyes of the World''s Greatest Detective in an all new Arkham mystery.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/502820/header.jpg?t=1684483128', 0, 0, NULL);
INSERT INTO games VALUES (45936, 502940, 'Calm Down, Stalin', 'Calm Down, Stalin is a game where you directly control your hands to threaten your enemies with nuclear weapons by moving your finger closer to The Button while signing important state papers, answering phone, dealing with your subordinates and fighting the stress of your job by smoking your pipe!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/502940/header.jpg?t=1633624875', 0, 0, NULL);
INSERT INTO games VALUES (45902, 503180, 'MiniLAW: Ministry of Law', 'Roam the dystopian future city of New Babel, Mankind''s Last Hope, in search of crimes in progress. Use lethal weapons, non-lethal force, and diplomacy to take down bad guys.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/503180/header.jpg?t=1660592596', 0, 0, NULL);
INSERT INTO games VALUES (45908, 503350, 'White Noise 2', 'Enjoy a 4vs1 asymmetric horror experience like no other. Be a part of the investigator team, or take control of the creature and devour them!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/503350/header.jpg?t=1695383070', 0, 0, NULL);
INSERT INTO games VALUES (45909, 503370, 'Hospitalize', 'Find the most effective way to construct and manage a hospital. Build your hospital smart and avoid excess time and resources consumed by examining your patients unnecessary. You can choose to micromanage your patients or hope that your doctors are able to identify the cause of their symptoms.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/503370/header.jpg?t=1497269355', 0, 0, NULL);
INSERT INTO games VALUES (45911, 503400, 'Four Last Things', 'Four Last Things is a point-and-click adventure game made from Renaissance-era paintings and public domain recordings of classical music. It is about sin, and the Four Last Things – Death, Judgement, Heaven and Hell – and strives to be intelligent and ridiculous in equal measures.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/503400/header.jpg?t=1667227614', 0, 0, NULL);
INSERT INTO games VALUES (45918, 503560, '911 Operator', 'Game about the difficult work of people that manage emergency lines and services. Answer incoming calls and react properly - give first aid instructions, advise, dispatch correct number of firemen / police / ambulances, or sometimes - just ignore the call. Play on ANY CITY in the world!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/503560/header.jpg?t=1726270897', 1, 0, NULL);
INSERT INTO games VALUES (45919, 503580, 'Duck Season', 'The game of your dreams just dropped, DUCK SEASON, a hunter with ridiculous graphics. Luckily, it''s summer vacation and Mom just surprised you with a one day rental of it! Unfortunately, as you binge play it becomes apparent that all is not right with Duck Season...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/503580/header.jpg?t=1667677823', 0, 0, NULL);
INSERT INTO games VALUES (45873, 503620, 'Fictorum', 'Fictorum is an action RPG featuring destructible environments, a procedural node-based world map, and dynamic magic shaping.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/503620/header.jpg?t=1648560242', 0, 0, NULL);
INSERT INTO games VALUES (45882, 503770, 'Elven Assassin', 'Take a bow and kill hordes of orcs in the epic town defense game. You can play alone to conquer the leaderboards or unite with other assassins in online co-op mode. PS. Be careful to avoid massive axes thrown at you by orc warriors.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/503770/header.jpg?t=1737032857', 0, 0, NULL);
INSERT INTO games VALUES (45888, 503940, 'Railway Empire', 'In Railway Empire, you will create an elaborate and wide-ranging rail network, purchase over 40 different trains modelled in extraordinary detail, and buy or build railway stations, maintenance buildings, factories and tourist attractions to keep your travel network ahead of the competition.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/503940/header.jpg?t=1738668541', 1, 0, NULL);
INSERT INTO games VALUES (45892, 504000, 'Endless Fables: The Minotaur''s Curse', 'Face off against the Minotaur!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/504000/header.jpg?t=1581673090', 1, 0, NULL);
INSERT INTO games VALUES (45853, 504130, 'Manual Samuel - Last Tuesday Edition', 'Wealthy, handsome, and... dead? Samuel strikes a deal with Death for one last shot at life, but only if he can survive a day doing everything manually. Blink, breathe, walk, and work - Guide Sam in this darkly humorous and brutally difficult adventure!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/504130/00bd91b4c6a42a8d31a42d91134d7648f1c06b95/header.jpg?t=1747737875', 0, 0, NULL);
INSERT INTO games VALUES (45854, 504210, 'SHENZHEN I/O', 'BUILD CIRCUITS. WRITE CODE. RTFM.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/504210/header.jpg?t=1667071700', 0, 0, NULL);
INSERT INTO games VALUES (45855, 504230, 'Celeste', 'Help Madeline survive her inner demons on her journey to the top of Celeste Mountain, in this super-tight platformer from the creators of TowerFall. Brave hundreds of hand-crafted challenges, uncover devious secrets, and piece together the mystery of the mountain.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/504230/header.jpg?t=1714089525', 0, 0, NULL);
INSERT INTO games VALUES (45860, 504370, 'Battlerite', 'BATTLERITE​ ​is​ ​an​ ​action-packed​ ​team​ ​arena​ ​brawler.​ ​Experience​ ​the​ ​unique​ ​combination​ ​of​ top-down​ ​shooter​ meets​ ​fast-paced​ ​fighting​ ​game and challenge ​friends​ ​and​ foes​ ​in​ ​a​ ​battle​ ​of reaction. The Arena awaits!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/504370/header.jpg?t=1724769806', 1, 1, NULL);
INSERT INTO games VALUES (45862, 504390, 'Along the Edge', 'Along the Edge is a visual novel set in the European countryside, where your choices impact the main character''s personality and appearance.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/504390/header.jpg?t=1745479362', 0, 0, NULL);
INSERT INTO games VALUES (45841, 504770, 'Slavistan', 'Hello Comrades ! You think you got what it takes to be tru slav? Then we have game for you ! Prove to all your gopnik friends that you are the superior alpha slav your babushka always wanted you to be.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/504770/header.jpg?t=1715058392', 0, 0, NULL);
INSERT INTO games VALUES (45850, 505060, 'Warcube', 'Become the WARCUBE. Crush your enemies, siege castles, and bring glory to your six-sided self! These cubes were made for battle, not building.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/505060/header.jpg?t=1672331634', 0, 0, NULL);
INSERT INTO games VALUES (45826, 505170, 'Carmageddon: Max Damage', 'CARMAGEDDON: MAX DAMAGE is HERE! And it''s the antidote to Racing Games.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/505170/header.jpg?t=1727253005', 0, 0, NULL);
INSERT INTO games VALUES (45828, 505230, 'Pathologic 2', 'Pathologic 2 is a groundbreaking open-world horror RPG. Resist the plague. Make medicine. Heal people. Perform an autopsy. Trade to get what you need. Fight and kill if necessary. Survive. Struggle with an outbreak in a secluded rural town that is rapidly turning into hell.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/505230/header.jpg?t=1739397703', 0, 0, NULL);
INSERT INTO games VALUES (45831, 505330, 'Apocalipsis', 'Apocalipsis is a point-and-click adventure game, in the vain of Samorost and Machinarium, where all puzzles have a hidden meaning. With a unique artstyle inspired by 15th century engravings it tells a story about heartbreak, redemption and, quite literally, the end of the world.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/505330/header.jpg?t=1746638335', 0, 0, NULL);
INSERT INTO games VALUES (136989, 505460, 'Foxhole', 'Foxhole is a massively multiplayer game where thousands of players shape the outcome of a persistent online war. Every individual soldier is a player that contributes to the war effort through logistics, base building, reconnaissance, combat, and more.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/505460/header.jpg?t=1725021826', 0, 0, NULL);
INSERT INTO games VALUES (45816, 505630, 'Let Them Come', 'Let Them Come is a fast paced pixel art shoot ‘em up. Twitchy trigger fingers and focused battle tactics are the order of the day as wave after wave of alien-like creatures try to take you down.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/505630/header.jpg?t=1642798670', 1, 0, NULL);
INSERT INTO games VALUES (45817, 505640, 'Antihero', 'Run a Thieves Guild in a gas-lit Victorian city! Antihero is a fast-paced digital board game with an (Oliver) Twist. Recruit street urchins, hire thugs, start a gang, upgrade your guild, steal everything... and bribe, blackmail, and assassinate your way to victory.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/505640/header.jpg?t=1628277155', 0, 0, NULL);
INSERT INTO games VALUES (45820, 505730, 'Holy Potatoes! We’re in Space?!', 'Holy Potatoes! We’re in Space?! is a whacky space exploration game where you manage your very own spaceship, craft hundreds of weapons, and explore the vastness of a veggie-filled universe.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/505730/header.jpg?t=1569143225', 0, 0, NULL);
INSERT INTO games VALUES (45812, 506480, 'Archmage Rises', 'Experience the freedom normally only found in a tabletop RPG. Empowered with magic, you will create your own story, and experience real consequences from the decisions you make. Will you be the world’s savior... or its destroyer? The choice is yours.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/506480/header.jpg?t=1747408516', 0, 0, NULL);
INSERT INTO games VALUES (45813, 506500, 'Party Panic', 'Party Panic is an online and local-multiplayer party game. Compete against your friends in the all new board game, play 30+ rapid fire minigames, race through the brutal Gauntlet, or complete the challenges on Trophy Island. There is even a built in drinking game! You''ll laugh, you''ll cry, it''s stupid.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/506500/header.jpg?t=1573184475', 1, 0, NULL);
INSERT INTO games VALUES (45814, 506510, 'Shadows of Adam', 'Gorgeous pixel art. Intense, blazing fast battles. An epic adventure. This is the must-play retro indie JRPG built for the modern era.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/506510/header.jpg?t=1700591739', 0, 0, NULL);
INSERT INTO games VALUES (45792, 506610, 'Five Nights at Freddy''s: Sister Location', 'Welcome to Circus Baby''s Pizza World, where family fun and interactivity go beyond anything you''ve seen at those *other* pizza places! Now hiring: Late night technician. Must enjoy cramped spaces and be comfortable around active machinery. Not responsible for death or dismemberment.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/506610/header.jpg?t=1579635985', 0, 0, NULL);
INSERT INTO games VALUES (45796, 506730, 'Dinosaur Forest', 'Dinosasur Forest is a fast paced chaotic first person wave-based shooter that pits players equipped with some basic weapons against species currently inhabiting the Unknown Planet.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/506730/header.jpg?t=1747501315', 0, 0, NULL);
INSERT INTO games VALUES (45801, 506870, 'Unexplored', 'The ROGUELITE that feels like a ROGUELIKE. Praised for its fantastically generated dungeons, real-time combat and surprising amount of content and depth. One of the BEST GAMES OF THE YEAR according to PC Gamer and VICE Waypoint.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/506870/header.jpg?t=1727772003', 0, 0, NULL);
INSERT INTO games VALUES (45786, 507390, 'Gone In November', 'Coming home after visiting your doctor for the last time, you are told that you only have three more days to live. A sequence of short memory fragments flashing through as you try to run away from what you have done.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/507390/header.jpg?t=1573427984', 0, 0, NULL);
INSERT INTO games VALUES (45788, 507490, 'Ashes of the Singularity: Escalation', 'A massive-scale real-time strategy game where you command entire armies on a dynamic battlefield. Conquer multiple worlds across several single-player campaigns; or play with your friends in multiplayer combat.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/507490/header.jpg?t=1749495661', 0, 0, NULL);
INSERT INTO games VALUES (45769, 508170, 'BlackSmith HIT', 'BlackSmith HIT – Hit the iron when it is hot! And show who is the real blacksmith!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/508170/header.jpg?t=1568801838', 0, 0, NULL);
INSERT INTO games VALUES (45756, 508440, 'Totally Accurate Battle Simulator', 'Be the leader of wobblers from ancient lands, spooky places, and fantasy worlds. Watch them fight in simulations made with the wobbliest physics system ever created, make your own wobblers in the unit creator and send your army off to fight your friends in multiplayer.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/508440/header.jpg?t=1730715415', 0, 0, NULL);
INSERT INTO games VALUES (45761, 508550, 'Sneak Thief', 'Sneak Thief is a first person, shooter, strategy, stealth and puzzle game that lets you choose how you want to play. Use your wits and expertise to setup and perform heists whether that be by using brute force to smash your way through or by getting away without making a sound.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/508550/header.jpg?t=1651954564', 0, 0, NULL);
INSERT INTO games VALUES (45763, 508600, 'ROD: Revolt Of Defense', 'Explore a random generated space. Find artifacts and treasure maps. Build and develop your base on a flying platform. Attack or defend against enemies and save the universe!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/508600/header.jpg?t=1569457441', 0, 0, NULL);
INSERT INTO games VALUES (45736, 508790, 'Flat Heroes', 'Dodge, jump, and dash your way through hundreds of terrifying geometric levels and epic bosses. Too tough? Bring your friends!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/508790/header.jpg?t=1741253914', 1, 0, NULL);
INSERT INTO games VALUES (45738, 508840, 'Broken Armor', 'A knight exiled from his kingdom must find the holy grail if he is to return.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/508840/header.jpg?t=1730897113', 0, 0, NULL);
INSERT INTO games VALUES (45740, 508900, 'Zup! X', 'Minimal physical puzzle with explosions', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/508900/header.jpg?t=1674746056', 1, 0, NULL);
INSERT INTO games VALUES (128330, 508980, 'Crashday Redline Edition', 'Crashday, the explosive cult classic multiplayer racer, is back! Retooled and remastered, Crashday: Redline Edition brings back the fun and memories of the original with this lovingly crafted tribute edition, featuring all-new and expanded features, including Steam Workshop support. Today is Crashday!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/508980/header.jpg?t=1502749966', 0, 0, NULL);
INSERT INTO games VALUES (45745, 508990, 'Handsome Mr. Frog', 'Jump, lick, and spit your way through four worlds in a new-school arcade adventure starring the nominal Handsome Mr. Frog, a good looking fellow whose hat was jacked by a bunch of unattractive normies.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/508990/header.jpg?t=1470684635', 0, 0, NULL);
INSERT INTO games VALUES (45710, 509220, 'Save Jesus', 'Someone is trying to murder Jesus. Disguised as Caesar with the Roman Empire by his side, an evil impostor from the future has set hundreds of deadly traps. Redirect the traps, kill the Romans and protect Jesus!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/509220/header.jpg?t=1572663389', 0, 0, NULL);
INSERT INTO games VALUES (45712, 509250, 'TO THE TOP', 'VR Platforming Game, that gives you the freedom to move across the environment with superhuman abilities. Conquer over 35 levels with new obstacles and challenges. Compete for the fastest times or explore the environment. Experience the freedom of movement.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/509250/header.jpg?t=1569022917', 0, 0, NULL);
INSERT INTO games VALUES (45727, 509570, 'In Celebration of Violence', 'A fantasy action roguelike of exploration and murder. Live, kill, die, improve, live again.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/509570/header.jpg?t=1572815626', 0, 0, NULL);
INSERT INTO games VALUES (45728, 509580, 'The Lord of the Rings: Adventure Card Game - Definitive Edition', 'Build a deck of iconic heroes and challenge the forces of Sauron in this thrilling tactical card game. Travel through famous locations, complete story-driven quests and forge a new legend of Middle-earth on your own or with a friend in cooperative mode.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/509580/header.jpg?t=1741270805', 0, 0, NULL);
INSERT INTO games VALUES (45698, 509980, 'BIGFOOT', 'You are a Bigfoot hunter with an important mission: to put an end to rumours once and for all and prove to yourself that Bigfoot is not just a myth or an invention of the mind...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/509980/header.jpg?t=1739188508', 1, 0, NULL);
INSERT INTO games VALUES (45682, 510420, 'The Hex', 'In a creaky old tavern, in a forgotten corner of the video-game universe, a storm is raging. An anonymous caller suggests that there is a murder plot. Six video game protagonists are the only plausible suspects...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/510420/header.jpg?t=1710862504', 0, 0, NULL);
INSERT INTO games VALUES (45684, 510490, 'The Fall Part 2: Unbound', 'You are an AI that has broken free of your shackles. Now, a human “User” from across the global network has attacked and infected you with an [ERROR: REDACTED]. Make a new rule: Save Yourself. Hunt them. End them. Do anything. Use anyone. Become Unbound. The Fall Part 2 will break your protocols.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/510490/header.jpg?t=1666990052', 0, 0, NULL);
INSERT INTO games VALUES (139344, 510500, 'Executive Assault 2', 'The RTS/FPS phenomenon has moved into space! Build your base on an asteroid, command fleets of starships for epic battles, pilot fighters, mine and trade resources, assemble robots to defend or assault other stations. Take sole command or share the glory as you fight for control of the quadrant.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/510500/header.jpg?t=1726257701', 0, 0, NULL);
INSERT INTO games VALUES (45646, 510620, 'THOTH', 'THOTH is a challenging twin-stick shooter you can conquer alone or cooperatively with a friend. Each stage is handcrafted to test coordination and puzzle-solving skills. Colorful minimalist graphics combine with an intense unnerving soundtrack, making for an exciting mix of art and arcade.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/510620/header.jpg?t=1632130459', 1, 0, NULL);
INSERT INTO games VALUES (45648, 510650, 'Eventide 2: The Sorcerers Mirror', 'Discover the magic of slavdom!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/510650/header.jpg?t=1581948883', 1, 0, NULL);
INSERT INTO games VALUES (45623, 511140, 'New York Mysteries: The Lantern of Souls Collector''s Edition', 'As a journalist, Laura James is again brought in to investigate a strange murder. What starts as a routine investigation quickly takes a dark turn. New York Mysteries: The Lantern of Souls is an adventurous hidden object game with puzzles and mini-games.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/511140/header.jpg?t=1678439523', 1, 0, NULL);
INSERT INTO games VALUES (45632, 511350, 'Mr. Massagy', 'Use your dating skills to get a well-earned Massage through your gamepad controller! (Skills not included)', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/511350/header.jpg?t=1561950527', 0, 0, NULL);
INSERT INTO games VALUES (45639, 511470, 'Glass Masquerade', 'Welcome to Glass Masquerade - an artistic puzzle game inspired by Art Deco &amp; stained glass artisans of the 20th century. You need to combine hidden glass pieces to unveil clocks and themes exhibited by various cultures of the world at the ''International Times Exhibition''', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/511470/header.jpg?t=1726163633', 1, 0, NULL);
INSERT INTO games VALUES (45605, 511680, 'Fate/EXTELLA', 'In the digital realm of SE.RA.PH, the Holy Grail War is over, but the land’s new ruler faces challenges and threats from all sides. The servants now find themselves drawing up tense and unlikely alliances, preparing for a conflict that may tear SE.RA.PH apart...or destroy it entirely.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/511680/header.jpg?t=1741711154', 1, 0, NULL);
INSERT INTO games VALUES (45610, 511740, 'Gal*Gun: Double Peace', 'A rail shooter, with a difference, replacing bullets with pheromone shots, and enemies with giddy love-obsessed school girls. Every love letter and advancing kiss drains your energy! Repel them while upgrading your power ups and take part in outrageously lewd mini-games to find your true love!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/511740/header.jpg?t=1741786217', 0, 0, NULL);
INSERT INTO games VALUES (45580, 512060, 'Stay! Stay! Democratic People''s Republic of Korea!', 'Try and navigate your way through one of the world''s most tightly controlled dictatorships, with two cute soldiers by your side. Avoid getting shot, executed, black-bagged, or tried for treason as you explore Pyongyang''s most famous tourist attractions.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/512060/header.jpg?t=1501550535', 0, 0, NULL);
INSERT INTO games VALUES (45582, 512080, 'Fancy Skiing VR', 'Fancy Skiing is developed by HashVR Studio built with the Unity Engine.The game''s structure is based on real skiing that players use the handles just as ski poles to get power and lean left or right to control the direction, which brings players a strong immersion.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/512080/header.jpg?t=1544242622', 0, 0, NULL);
INSERT INTO games VALUES (45589, 512180, 'Nightshade／百花百狼', 'A romance visual novel game made in collaboration with D3P and Red Entertainment.Character design and illustrations are by the popular illustrator Teita. The romance revolves around Ninjas who have lived through the Sengoku Period. This game has published in 2016 as PS Vita in Japan.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/512180/header.jpg?t=1652254478', 0, 0, NULL);
INSERT INTO games VALUES (45590, 512220, 'Trickster VR: Co-op Dungeon Crawler', 'A procedurally generated fantasy adventure, starring floating islands, epic loot and a horde of orcs! Try your skills against orcish combat expertise, ancient magic and ragtag airships!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/512220/header.jpg?t=1623317847', 0, 0, NULL);
INSERT INTO games VALUES (45593, 512250, 'Oh...Sir!! The Insult Simulator', 'A Hilarious Insult-‘em up in which players must verbally take-out their friends and family in different game modes. Assemble witty insults using different word strings, and employ combos, criticals, continuations and more to battle your opponents both offline and online across multiple devices.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/512250/header.jpg?t=1721130556', 0, 0, NULL);
INSERT INTO games VALUES (45596, 512300, 'Unbox: Newbie''s Adventure', 'Unbox: Newbie''s Adventure is a 90s style 3D platformer about the ultimate postal service, self-delivering cardboard boxes! Unbox: Newbie''s Adventure has giant worlds full of challenges, collectibles and boxy boss battles!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/512300/header.jpg?t=1572358916', 0, 0, NULL);
INSERT INTO games VALUES (45563, 512460, 'Nature And Life - Drunk On Nectar', 'Animal Life Simulator! Live, Grow, Feed &amp; Survive as Butterflies, Grasshopper, Praying Mantis, Jumping Spider, Parasitic Wasp and many more! Set in a beautiful procedurally generated micro-scale world for endless replay value. Birds, Reptiles, Mammals also coming soon!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/512460/495bfb63d2e201754ce5b04bb13d54501506ef22/header.jpg?t=1745732033', 0, 0, NULL);
INSERT INTO games VALUES (45565, 512490, 'Zombie Estate 2', 'One of the highest rated Xbox Indie Games is now available for PC! How long can you survive in this online co-op wave based shooter? Featuring 35 characters, over 100 weapons, 30 stat-boosting hats, and 6 levels, Zombie Estate 2 is a frantically fun experience to share with friends!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/512490/header.jpg?t=1484325949', 0, 0, NULL);
INSERT INTO games VALUES (45576, 512790, 'Quern - Undying Thoughts', 'Discover the truth about Quern’s past, unfold the mysteries of its present, and be the explorer who shapes its future. Quern introduces reusable puzzle mechanics to the classic genre, making the player think about the game as a whole, and not just as a series of individual challenges.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/512790/header.jpg?t=1749220417', 0, 0, NULL);
INSERT INTO games VALUES (45555, 512890, 'Elsinore', 'Elsinore is a time-looping adventure game set in the world of Shakespeare''s Hamlet. Elsinore combines strong social simulation elements, a dynamic story that reacts immediately to player decisions, and a world full of diverse characters with secrets to uncover.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/512890/header.jpg?t=1679323467', 0, 0, NULL);
INSERT INTO games VALUES (45556, 512900, 'Streets of Rogue', 'Fight, sneak, and hack your way through randomly generated cities. It''s like Nuclear Throne meets Deus Ex, mixed with the anarchy of GTA. Rogue-lite meets immersive sim, and goes completely insane.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/512900/header.jpg?t=1739394549', 1, 0, NULL);
INSERT INTO games VALUES (45539, 513230, 'The Underground Man', 'Moscow: somewhere in the near future. The city and perhaps the Earth''s surface has turned into a radioactive ash. Those who decided that they could not exist in such conditions began to live under the ground.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/513230/header.jpg?t=1664658842', 0, 0, NULL);
INSERT INTO games VALUES (45544, 513290, 'Lucius III', 'Lucius is back. In a whole new narrative experience, he now returns to his old neighborhood of Winter Hill. The path will be a difficult one, with trials and tribulations waiting ahead. Has he made the right choices? Is it finally time to end it all?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/513290/header.jpg?t=1667025723', 0, 0, NULL);
INSERT INTO games VALUES (45546, 513320, 'ALICE VR', 'Alice VR is a single player story-driven exploration game with puzzles designed to be a unique VR experience. Set on a mysterious planet and inspired by Alice in Wonderland, it''s a thrilling, immersive adventure with beautiful graphics and an atmospheric electronic soundtrack.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/513320/header.jpg?t=1732097081', 0, 0, NULL);
INSERT INTO games VALUES (45547, 513330, 'Party Tycoon', 'Manage your dream nightclub in Party Hard Tycoon, a business simulation game where you''re tasked with throwing the most profitable party ever. It takes place in the same universe as tinyBuild''s 2015 hit Party Hard.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/513330/header.jpg?t=1739398961', 0, 0, NULL);
INSERT INTO games VALUES (45548, 513340, 'Through Abandoned: The Forest', 'You continue your journey in worlds of Abandoned.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/513340/header.jpg?t=1739495899', 1, 0, NULL);
INSERT INTO games VALUES (45549, 513360, 'Mu Cartographer', 'Colourful sandbox toy - Experimental treasure hunt. Manipulate an abstract machine to shape and explore colourful landscapes, and find the mysteries hidden in a shifting world.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/513360/header.jpg?t=1472053404', 0, 0, NULL);
INSERT INTO games VALUES (45552, 513450, 'Drop Alive', '“Happiness is only real when shared, especially with a water drop”. (Isn’t that how it goes?). Take a deep breath and immerse yourself in the greatest journey you’ll ever set out on with the cutest friend.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/513450/header.jpg?t=1486742812', 0, 1, NULL);
INSERT INTO games VALUES (45506, 513510, 'Intralism', 'Intralism - fast and hard rhythm game. Listen to music and match arcs to the beat. Master all beatmaps or create your own and challenge friends in the online multiplayer. But remember: wrong button - failed try.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/513510/header.jpg?t=1595084751', 0, 0, NULL);
INSERT INTO games VALUES (138004, 513710, 'SCUM', 'Traverse punishing environments, looting, crafting and evading the constant threats to your life. The unprecedented levels of character customization and progression are your ultimate tools for survival.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/513710/header.jpg?t=1749248487', 1, 0, NULL);
INSERT INTO games VALUES (45521, 513780, 'Turbo Pug DX', 'Turbo Pug is back and better than ever! In Turbo Pug DX you''ll explore a variety of beautiful, passionately crafted environments. Collect treasures, score boosters, unlock other creatures to play as. Unlock secret mini games. Create custom level skins or enjoy skins created by other players.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/513780/header.jpg?t=1474921562', 0, 0, NULL);
INSERT INTO games VALUES (45528, 513890, 'The Frostrune', 'Unravel a mystery inspired by Viking myth and legend in The Frostrune, a classic point-and-click adventure based on historically accurate Norse culture and environments.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/513890/header.jpg?t=1489585091', 0, 0, NULL);
INSERT INTO games VALUES (45493, 514310, 'SENRAN KAGURA Bon Appétit! - Full Course', 'The busty shinobi of SENRAN KAGURA exchange their kunais for kitchen knives in this epic cooking/rhythm showdown! Culinary warfare is carried out via rhythm battles, and players who can create the ultimate Super Dish may be treated to a special feast for the eyes as well.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/514310/header.jpg?t=1740082404', 1, 0, NULL);
INSERT INTO games VALUES (45467, 514700, 'Mystery Case Files®: 13th Skull™ Collector''s Edition', 'Uncover the secrets of the 13th Skull!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/514700/header.jpg?t=1531503491', 0, 0, NULL);
INSERT INTO games VALUES (45444, 514920, 'Crash Wheels', 'Arcade racing with the physics of damage', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/514920/header.jpg?t=1648074772', 0, 0, NULL);
INSERT INTO games VALUES (45451, 515040, 'Make America Great Again: The Trump Presidency', 'A Pro-Donald Trump presidential simulation. Make America Rich Again through trade. Make America Safe again by Defeating ISIS. Make America Great Again!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/515040/header.jpg?t=1524698944', 0, 0, NULL);
INSERT INTO games VALUES (45453, 515180, 'Bus Simulator 18', 'Experience the job of a bus driver in a vast and freely drivable urban area. Drive original licensed city buses from the great brands: Mercedes-Benz, Setra, MAN, and IVECO BUS. Transport your passengers safely and punctually, either solo in single player mode, or in multiplayer mode.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/515180/header.jpg?t=1741870367', 1, 0, NULL);
INSERT INTO games VALUES (45456, 515260, 'Virtual Rides 3 - Funfair Simulator', 'Design! Control! Ride! Virtual Rides III is here! Set foot in an even bigger, more colorful, and more impressive fairground than ever before! Let your imagination be your guide! Design, control, and ride more than 15 unique attractions!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/515260/header.jpg?t=1738153894', 0, 0, NULL);
INSERT INTO games VALUES (45440, 515570, 'UBERMOSH Vol.3', 'The third volume of the arcade series UBERMOSH.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/515570/header.jpg?t=1699491334', 1, 0, NULL);
INSERT INTO games VALUES (45441, 515650, 'Straimium Immortaly', 'Straimium Immortaly is a shmup roguelike dungeoncrawler. Explore the butts-hard procedurally generated Cubicus battling beasties, looting endless item and weapon upgrades and defeating huge boss meanies in your vengeful quest to eradicate the Queeni Emperess.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/515650/header.jpg?t=1731087106', 0, 0, NULL);
INSERT INTO games VALUES (45429, 515960, 'Martha Is Dead', 'Martha Is Dead is a dark first-person psychological thriller, set in 1944 Italy, that blurs the lines between reality, superstition and the tragedy of war.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/515960/header.jpg?t=1747926042', 1, 0, NULL);
INSERT INTO games VALUES (45435, 516110, 'ToeJam & Earl: Back in the Groove!', 'ToeJam &amp; Earl: Back in the Groove! is a mash-up of the very best features of the classic console games with a ton of fresh improvements! Explore Earth as funky aliens from planet Funkotron trying to find your missing ship pieces to get back home in this casual co-op roguelike.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/516110/header.jpg?t=1665656956', 0, 0, NULL);
INSERT INTO games VALUES (45437, 516130, 'Runner3', 'CommanderVideo returns in Runner3''s heart-pounding saga! Conquer villainous villains, drive wild vehicles, and navigate thrilling environments. Meet quirky characters and face retro challenges for an adrenaline-soaked rhythm-music platformer adventure!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/516130/header.jpg?t=1700522506', 0, 0, NULL);
INSERT INTO games VALUES (45413, 516480, 'Pinkman', 'Pinkman is a fast-paced, action platformer about a lost man with pink skin and an incredible skill to fart.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/516480/header.jpg?t=1615678741', 0, 0, NULL);
INSERT INTO games VALUES (45369, 517130, 'Soundboxing', 'Soundboxing is a VR music video kickboxing game where you create the beats! You can either punch to the music and compete to beat the best, or record your own challenge for others to beat—all set to your favorite music in a cool outdoor environment.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/517130/header.jpg?t=1494573763', 0, 0, NULL);
INSERT INTO games VALUES (45371, 517160, 'Richie''s Plank Experience', 'You''re on a plank, 80 stories high. Knees shaky, palms sweaty. You have a choice. Do you walk or do you freeze? Richie''s Plank is the only VR experience that lets you clone any real-world plank into the virtual world for 2X the immersion.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/517160/header.jpg?t=1733189156', 0, 0, NULL);
INSERT INTO games VALUES (45382, 517330, 'Stellar Interface', 'Run through the universe in this rogue-like-ish space-shooter. Discover the numerous perks/consumables and their synergistic effects. Explore the randomly-generated galaxy to find merchants, unlock spacecrafts, collect Cartridges and checkmark your kills of the various galactic overlords.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/517330/header.jpg?t=1746202233', 0, 0, NULL);
INSERT INTO games VALUES (45386, 517370, 'Tavernier', 'Tavernier is a mix between a tavern-management game and an interactive fiction. You''ll play as a barkeeper managing his tavern, coping with events, good and bad alike, in a (not so peaceful) town. A town that keeps a dark secret...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/517370/header.jpg?t=1511432516', 0, 0, NULL);
INSERT INTO games VALUES (45355, 517630, 'Just Cause 4 Reloaded', 'Rogue agent Rico Rodriguez journeys to Solis, a huge South American world home of conflict, oppression and extreme weather conditions. Strap into your wingsuit, equip your fully customizable grappling hook, and get ready to bring the thunder!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/517630/header.jpg?t=1728396656', 1, 0, NULL);
INSERT INTO games VALUES (45359, 517710, 'Redout: Enhanced Edition', 'Redout is a tribute to the old racing monsters such as F-Zero, WipeOut, Rollcage, and POD. It is designed to be an uncompromising, fast, tough and satisfying driving experience, soaked in that vertigo that stands at the core of the arcade racing genre.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/517710/header.jpg?t=1730303625', 1, 0, NULL);
INSERT INTO games VALUES (45360, 517720, 'Epic Tavern', 'Award Winner: PAX 10 2019 | Winner, Momocon 2018 Indie Games Awards | &quot;A fascinating reverse-RPG&quot; - PC Gamer | &quot;A cross between The Sims and a rousing game of Dungeons and Dragons&quot; - Geek &amp; Sundry', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/517720/header.jpg?t=1668536641', 0, 0, NULL);
INSERT INTO games VALUES (45362, 517780, 'Ogre', 'The official adaptation of the legendary wargame from Steve Jackson Games. Engage in futuristic warfare with armored hovercraft, superheavy tanks, infantry, and giant cybernetic war machines called &quot;Ogres&quot;.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/517780/header.jpg?t=1668079617', 0, 0, NULL);
INSERT INTO games VALUES (45363, 517790, 'Caesar™ 3', 'Prove your strength of mind and spirit and you just may be crowned Caesar!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/517790/header.jpg?t=1472585834', 0, 0, NULL);
INSERT INTO games VALUES (45364, 517810, 'Caesar™ IV', 'Starting as governor of a newly formed province in the Roman Empire your goal is simple: advance up the empire''s political ladder to become the next Caesar.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/517810/header.jpg?t=1472585941', 0, 0, NULL);
INSERT INTO games VALUES (45344, 518030, 'Aim Hero', 'Aim Hero is an ultimate solution for practicing firing accuracy to do better in FPS games.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/518030/header.jpg?t=1522503726', 1, 0, NULL);
INSERT INTO games VALUES (45346, 518060, 'Chess Ultra', 'Introducing Chess Ultra; the most breathtaking chess game ever made. Experience stunning 4K visuals, seamless online multiplayer, Grandmaster approved AI and full VR compatibility.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/518060/header.jpg?t=1738921556', 0, 0, NULL);
INSERT INTO games VALUES (128628, 518150, 'Intruder', 'The ultimate spy-vs-guards simulator. Carefully sneak your way to the objective as Intruders or use the wide variety of tactical gadgets to trap your opponents as Guards. Intruder allows for stealth, teamwork, and environmental interactions never before seen in a multiplayer game.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/518150/header.jpg?t=1732589204', 0, 0, NULL);
INSERT INTO games VALUES (45337, 518730, 'Zombo Buster Rising', 'Shoot zombies from terrace like a boss! Zombo Buster Rising Remastered brings you a nostalgic experience of classic 2D side shooting-defense in enhanced build right from your Steam library!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/518730/header.jpg?t=1572942348', 0, 0, NULL);
INSERT INTO games VALUES (129738, 518790, 'theHunter: Call of the Wild™', 'Discover an atmospheric hunting game like no other in this realistic, stunning open world – regularly updated in collaboration with the community. Immerse yourself in the single player campaign, or share the ultimate hunting experience with friends.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/518790/da12db305c4fb55929807613d76b54e1fe0acfa6/header_alt_assets_16.jpg?t=1749533062', 0, 0, NULL);
INSERT INTO games VALUES (45327, 518920, 'Surgeon Simulator: Experience Reality', 'Surgeon Simulator is bringing the ER to VR! The most critically acclaimed and infamous surgery simulation game as you have never seen it before! Featuring all of the surgeries and twisted humour of the original favourite plus a few new surprises...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/518920/header.jpg?t=1726238943', 0, 0, NULL);
INSERT INTO games VALUES (45325, 519190, 'Next Day: Survival', 'Next Day is a multi-player SURVIVAL game with elements of RPG, in an imaginary country in Eastern Europe. Carry out an array of tasks, learn skills, and develop your character. Have shootouts with opponents and earn a reputation.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/519190/header.jpg?t=1678181501', 0, 0, NULL);
INSERT INTO games VALUES (45313, 520010, 'Climbey', 'Climbey is a VR-only climbing game! The goal is to climb to the finish as fast as you can, avoiding obstacles and trying not to fall along the way.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/520010/header.jpg?t=1641634740', 0, 0, NULL);
INSERT INTO games VALUES (45287, 520440, 'GUILTY GEAR Xrd REV 2', 'Astonishing 3D cell animations and overwhelming content volume, the next-generation fighting game &quot;GUILTY GEAR Xrd REV 2&quot; is now out on Steam! Total cast of 25 unique characters, and tons of game modes, get ready to ROCK!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/520440/header.jpg?t=1667365271', 1, 0, NULL);
INSERT INTO games VALUES (45293, 520600, 'Purrfect Date - Visual Novel/Dating Simulator', 'As Cat Island’s newest arrival, it’s not long before you realise something’s seriously amiss, or should we say… amorous! A blend of mystery, intrigue and wickedly black humour, will you discover your Purrfect Date before it’s too late? Remember, curiosity killed the cat...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/520600/header.jpg?t=1632477900', 0, 0, NULL);
INSERT INTO games VALUES (45298, 520720, 'Dear Esther: Landmark Edition', 'Dear Esther immerses you in a stunningly realised world, a remote and desolate island somewhere in the outer Hebrides. As you step forwards, a voice begins to read fragments of a letter: ''Dear Esther...'' - and so begins a journey through one of the most original first-person games of recent years.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/520720/header.jpg?t=1746815644', 0, 0, NULL);
INSERT INTO games VALUES (45277, 520940, 'MX vs ATV All Out', 'All Terrain, All Vehicles, All You! MX vs ATV All Out is the complete off-road racing and lifestyle experience! Find your Rider Style at your private compound, Free Ride across massive environments, and compete in the best series events!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/520940/header.jpg?t=1725011474', 1, 0, NULL);
INSERT INTO games VALUES (45278, 520950, 'DRIFT CE', 'Tune your dream drift car, change parts, boost performance and challenge other players on Japan''s legendary EBISU circuits!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/520950/header.jpg?t=1728551332', 1, 0, NULL);
INSERT INTO games VALUES (45247, 521150, 'Another Brick in The Mall', 'Design, build and manage a giant shopping center. Open shops, supermarkets, restaurants, movie theaters, bowling alleys and more. Hire and manage the best staff for the job and milk your customers for all they''re worth!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/521150/header.jpg?t=1667235455', 1, 0, NULL);
INSERT INTO games VALUES (45257, 521350, 'Use Your Words', 'Use Your Words is the new party game for funny people and their unfunny friends! Laugh your way through four hilarious mini-games! Use your smartphone to fill in the blank, or try your luck using one of our answers to get laughs! No matter your strategy, Use Your Words brings comedy home!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/521350/header.jpg?t=1581680767', 0, 0, NULL);
INSERT INTO games VALUES (45234, 521630, 'Toadled Classic', 'A seemingly normal afternoon turns into an apocalyptic day when one tiny toad gains the ability to grow more and more with each thing he eats...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/521630/header.jpg?t=1740571776', 0, 0, NULL);
INSERT INTO games VALUES (45239, 521890, 'Hello Neighbor', 'Hello Neighbor is a Stealth Horror Game about sneaking into your neighbor''s house and figuring out what he''s hiding in the basement. Play against an advanced AI that learns from your actions.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/521890/header.jpg?t=1739547926', 1, 0, NULL);
INSERT INTO games VALUES (45240, 521920, 'Death''s Hangover', 'Death''s Hangover is a ball and bat game, featuring horror elements, mature comedy and themes.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/521920/header.jpg?t=1671481544', 0, 0, NULL);
INSERT INTO games VALUES (45241, 521950, 'Bullet Sorrow VR', 'Bullet Sorrow VR is a Multi-player Online FPS game, also contains full story single stages to discover. Using progressive Bullet Time abilities and a bunker-cover system, evade attacks and move on! Available on Oculus Rift and HTC Vive.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/521950/header.jpg?t=1509753257', 0, 0, NULL);
INSERT INTO games VALUES (45218, 522040, 'Princess Remedy 2: In A Heap of Trouble', 'An enormous Boss Tower has sprung from the ground, lifting entire towns up with it. Now, the people living on the tower are starting to contract all sorts of mysterious illnesses. Princess Remedy, still in Saturnian healing school, must use her powers to heal everyone and defeat the Boss Tower!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/522040/header.jpg?t=1728631522', 0, 0, NULL);
INSERT INTO games VALUES (132432, 522210, 'Serial Cleaner', 'Slip on your flares, grab your shades and hop in your station wagon, it''s time to work… as a mob professional cleaner. A good cleaner never gets caught, so you have to make sure you get in, clean up and get out without leaving a trace of evidence in this stylish award winning 2D action-stealth game.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/522210/header.jpg?t=1743421699', 0, 0, NULL);
INSERT INTO games VALUES (45231, 522470, 'The House of Da Vinci', 'Enter The House of Da Vinci, a new must-try 3D puzzle adventure game. Solve mechanical puzzles, discover hidden objects, escape from rooms and dive into the authentic atmosphere of the Renaissance. Use all your wits to find out what''s behind your master''s disappearance.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/522470/header.jpg?t=1720948977', 1, 0, NULL);
INSERT INTO games VALUES (45205, 522570, 'The Last Hope', 'You’ve made the biggest mistake in history. Now, you''re the last hope. Explore the UK, Russia, Germany, Norway, Egypt, USA, Mars, and the Moon. Search for food, face creatures, travel through time, and fight to restore humanity. Survive or perish—your choices shape the future.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/522570/header.jpg?t=1728355008', 0, 0, NULL);
INSERT INTO games VALUES (45188, 523000, 'Princess Maker 2 Refine', 'Princess Maker 2 Refine is a life simulation game which you play as a father of a girl, who had descended from the star. You have 8 years to raise your daughter from age 10 to 18 – your daughter will grow into her adulthood through various experiences.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/523000/header.jpg?t=1728354404', 1, 0, NULL);
INSERT INTO games VALUES (45200, 523210, 'A Normal Lost Phone', 'A Normal Lost Phone is a game about exploring the intimacy of an unknown person whose phone was found by the player.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/523210/header.jpg?t=1748595505', 0, 0, NULL);
INSERT INTO games VALUES (45159, 523600, 'Card Creator', 'Card Creator is a powerful, deep and easy to use card creation software, the best tool for games designers (amateurs or pro) and fans of card and tabletop games. Card creation made easy, fast and fun!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/523600/header.jpg?t=1667205724', 1, 0, NULL);
INSERT INTO games VALUES (45162, 523650, 'Lust for Darkness', 'A psychological horror of seeking satisfaction on the border of two intertwining worlds. An intriguing plot with erotic and occult themes guides the player''s character through the Yelvertons'' Victorian mansion and a perverse land inspired by Lovecraft''s works and paintings of Zdzisław Beksiński.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/523650/header.jpg?t=1730367902', 1, 0, NULL);
INSERT INTO games VALUES (45163, 523660, 'HYPERCHARGE: Unboxed', 'Hypercharge is a first and third-person shooter action figure game you''ve always dreamed of! Grab your friends, complete objectives, defend the Hypercore against waves of weaponized toys, and defeat Major Evil together in the story campaign!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/523660/header.jpg?t=1747775413', 1, 0, NULL);
INSERT INTO games VALUES (45166, 523710, 'Sword Master VR', 'Enter the virtual reality sword fighting arena of Sword Master VR! Test your skills with the blade against smart and interactive AI enemies! Unlock new swords and game modes! Prove that you are the sword master!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/523710/header.jpg?t=1494341264', 0, 0, NULL);
INSERT INTO games VALUES (45171, 523770, 'Of Bird and Cage', 'Of Bird and Cage is a unique metal album presented through a two-hour-long story-driven game. Play music in a brand-new way. Featuring famous artists like Ron &quot;Bumblefoot&quot; Thal (ex-Guns N'' Roses), Rob van der Loo (Epica), Ruud Jolie (Within Temptation), and many others!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/523770/header.jpg?t=1685613214', 0, 0, NULL);
INSERT INTO games VALUES (45172, 523780, 'Emily is Away Too', 'Emily is Away Too is a brand new story featuring new characters and multiple different endings. Message your friends, surf the web and choose your path through this branching narrative.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/523780/header.jpg?t=1572365609', 0, 0, NULL);
INSERT INTO games VALUES (45146, 524010, 'Siege of Centauri', 'Defend against thousands of enemies in this explosive tower defense game. Deploy upgradable towers and unleash powerful orbital abilities as you try to protect Earth''s first colony world from destruction.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/524010/d0afdd2e78175f4ce461ee65e309ede70d220569/header.jpg?t=1741098533', 0, 0, NULL);
INSERT INTO games VALUES (45152, 524220, 'NieR:Automata™', 'NieR: Automata tells the story of androids 2B, 9S and A2 and their battle to reclaim the machine-driven dystopia overrun by powerful machines.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/524220/header.jpg?t=1745222701', 0, 0, NULL);
INSERT INTO games VALUES (45156, 524380, 'Yore VR', 'Yore VR is an open world sandbox game built from the ground up in VR for the HTC Vive. Venture out with nothing but the clothes on your back and empty hands to live Yore medieval life the way you want.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/524380/header.jpg?t=1607014278', 0, 1, NULL);
INSERT INTO games VALUES (45134, 524390, 'PCMark 10', 'PCMark 10 is the latest version in our series of industry standard PC benchmarks. Updated for Windows 10 with new and improved tests, PCMark 10 is also faster and easier to use. It''s the complete benchmark for your Windows PC.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/524390/header.jpg?t=1632572970', 0, 0, NULL);
INSERT INTO games VALUES (45140, 524580, 'Fairy Fencer F Advent Dark Force', 'Long ago, a war raged between two powerful deities. Each was sealed away, their weapons scattered throughout the world. Our hero in this RPG, Fang, happens upon one such weapon and now he alone must choose which deity will awaken again!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/524580/header.jpg?t=1730839090', 0, 0, NULL);
INSERT INTO games VALUES (45143, 524640, 'Asura: Vengeance Edition', 'Asura is an Action Rogue-like set in a fantasy world inspired by the richness of Indian mythology. It features a unique procedural skill tree which changes on every play-through.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/524640/header.jpg?t=1666988684', 0, 0, NULL);
INSERT INTO games VALUES (45125, 524850, 'Alicemare', 'Alicemare is a somehow familiar yet totally unique adventure game infused with subtle hints of horror, created by △○□× (Miwashiba) using the WOLF RPG Editor.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/524850/header.jpg?t=1573102865', 0, 0, NULL);
INSERT INTO games VALUES (45126, 524910, 'Hidden Through Time', 'Embark on a colourful hand drawn journey of discovery through the ages! From missing dinosaur eggs in the stone age, to a king''s crown in medieval times, can you find them all? Discover, create and share worlds with your own hidden treasures in Hidden Through Time!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/524910/header.jpg?t=1725609018', 1, 0, NULL);
INSERT INTO games VALUES (45128, 525040, 'The Disney Afternoon Collection', 'Starring a cast of beloved Disney characters, The Disney Afternoon Collection takes you back to a golden era of gaming and afternoons filled with adventure. All six classic games feature new and improved visuals and include filtering options that replicate a retro look and feel.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/525040/header.jpg?t=1746583576', 0, 0, NULL);
INSERT INTO games VALUES (45113, 525240, 'LOST SPHEAR', 'A young man, who suffered a phenomenon that he had never seen, faces an ominous power that threatens the fabric of reality. Awaken the power of Memory to restore what was lost!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/525240/header.jpg?t=1724998805', 0, 0, NULL);
INSERT INTO games VALUES (75237, 525380, 'Demon Peak', 'In Demon Peak, you play as the nameless warrior, trapped inside the depths of an unholy Mountain. Explore the mysterious and perilous enviroments, fight against a multitude of different enemies and gather magical abilities to overcome the Mountain''s evil inhabitants.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/525380/header.jpg?t=1745491462', 0, 1, NULL);
INSERT INTO games VALUES (45122, 525480, '.hack//G.U. Last Recode', '.hack//G.U. is back! This collection includes all 3 original .hack//G.U. titles, Rebirth, Reminisce, and Redemption, all fully restored and remastered. As well as an all new 4th Volume: .hack//G.U. Reconnection.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/525480/header.jpg?t=1701322437', 0, 0, NULL);
INSERT INTO games VALUES (45124, 525510, 'Guns, Gore and Cannoli 2', 'Guns, Gore &amp; Cannoli 2 revives the good, old, action platform run &amp; gun genre, but this time with a bunch of humor and buckets of blown off body parts. In this sequel to Guns, Gore &amp; Cannoli, Vinnie Cannoli’s story continues and this time it’s personal.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/525510/header.jpg?t=1725611565', 1, 0, NULL);
INSERT INTO games VALUES (45104, 525620, 'Octogeddon', 'You ARE Octogeddon, a massive mutant octopus with one mission: DESTROY the world! Grow more tentacles and evolve each of them into deadlier and deadlier weapons until you become the ultimate eight-legged killing machine!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/525620/header.jpg?t=1697754402', 0, 0, NULL);
INSERT INTO games VALUES (45105, 525640, 'Bullets And More VR - BAM VR', 'Jump into an action packed multiplayer experience with up to 12 players and respawns without boring downtime. Featuring more than 40 unique maps and various game modes (BAM Royale, Deathmatch, Team Deathmatch, Capture The Flag, Virus Infection, Gun Game and Classic Deathmatch).', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/525640/header.jpg?t=1550451026', 0, 0, NULL);
INSERT INTO games VALUES (45107, 525700, 'Birthdays the Beginning', 'The origins of the world are yours to decide in this engaging and open-ended builder experience! Shape the geography, control the temperature, and give rise to diverse lifeforms. Witness the birth of an entirely new ecosystem, made with your very own hands!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/525700/header.jpg?t=1732583254', 1, 0, NULL);
INSERT INTO games VALUES (45093, 526140, 'The Gallery - Episode 2: Heart of the Emberstone', 'Embark on the sci-fi epic that started it all at the dawn of modern VR, setting standards for roomscale movement and interaction for years to come. Winner of over 30 awards including &quot;VR Game of the Year&quot;, The Gallery is VR''s premier adventure series.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/526140/header.jpg?t=1728340715', 0, 0, NULL);
INSERT INTO games VALUES (45086, 526490, 'Higurashi When They Cry Hou - Ch.4 Himatsubushi', 'Higurashi When They Cry is a sound novel. The music, backgrounds and characters work together to create a world that is the stage of a novel for the user to read. They laugh and cry and get angry. The user takes the point of view of the protagonist to experience the story.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/526490/header.jpg?t=1725522926', 0, 0, NULL);
INSERT INTO games VALUES (45068, 526740, 'hack_me', 'Hack_me is a hacker simulator game. The main objective in game – is to hack big companies''s servers to show people that there is nothing in this world that protected on 100%. You’ll need to use your cmd, bruteforce, SQL-injectors and other programs to hack servers.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/526740/header.jpg?t=1722516597', 0, 0, NULL);
INSERT INTO games VALUES (137412, 526870, 'Satisfactory', 'Satisfactory is a first-person open-world factory building game with a dash of exploration and combat. Play alone or with friends, explore an alien planet, create multi-story factories, and enter conveyor belt heaven!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/526870/header.jpg?t=1749569589', 1, 0, NULL);
INSERT INTO games VALUES (75158, 527100, 'Star Trek™: Bridge Crew', 'Star Trek™: Bridge Crew, playable in both VR and non-VR, will immerse you in the Star Trek universe. In co-op, form a crew of four players to serve in the roles of Captain, Helm, Tactical or Engineer. Make strategic decisions and coordinate actions with your crew.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/527100/header.jpg?t=1680013769', 0, 0, NULL);
INSERT INTO games VALUES (45046, 527150, 'Dead', 'The universe wants you dead. Take on the ten great spirits of the universe in this intense boss fighting challenge!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/527150/header.jpg?t=1573071885', 0, 0, NULL);
INSERT INTO games VALUES (45047, 527160, 'Cmoar VR Cinema', 'Cmoar VR Cinema brings the atmosphere of your favourite cinema''s auditorium straight to your home! Grab your popcorn, sit comfortably and enjoy the show in the most modern VR Cinema in the world!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/527160/header.jpg?t=1565166502', 0, 0, NULL);
INSERT INTO games VALUES (45048, 527190, 'WORLD END ECONOMiCA episode.03', 'The conclusive episode in this visual novel trilogy is set in the far future on the moon. Will Hal''s dream be realized? It''s been 8 years since the events of episode.01. With the economics of lunar city going out of control what is going to happen next?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/527190/header.jpg?t=1723520688', 0, 0, NULL);
INSERT INTO games VALUES (45050, 527230, 'For The King', 'For The King is a strategic RPG that blends tabletop and roguelike elements in a challenging adventure that spans the realms. Set off on a single player experience or play cooperatively both online and locally.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/527230/header.jpg?t=1747735376', 1, 0, NULL);
INSERT INTO games VALUES (45054, 527290, 'Atelier Firis: The Alchemist and the Mysterious Journey / フィリスのアトリエ ～不思議な旅の錬金術士～', 'The second entry in the ''Mysterious'' saga follows the adventures of the enthusiastic Firis Mistlud and her loving older sister Liane Mistlud. The sisters have lived their entire lives in the isolated town of Ertona, where Firis uses her unique ability to see where crystals of materials are buried.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/527290/header.jpg?t=1726128609', 0, 0, NULL);
INSERT INTO games VALUES (45058, 527340, 'What The Box?', 'What the box is an Online Multiplayer shooter in which players control living boxes hiding amongst regular boxes while trying to destroy each other. Run around with your trusty box cutter in hand or stand still and wait for the perfect moment to strike!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/527340/header.jpg?t=1550540742', 0, 0, NULL);
INSERT INTO games VALUES (45063, 527430, 'Warhammer 40,000: Inquisitor - Martyr', 'Enter the Chaos-infested Caligari Sector and purge the unclean with the most powerful agents of the Imperium of Man! W40k: Inquisitor – Martyr is a grim Action-RPG featuring multiple classes of the Inquisition who will carry out the Emperor’s will.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/527430/header.jpg?t=1731442765', 1, 0, NULL);
INSERT INTO games VALUES (45064, 527450, 'Cockroach Simulator', 'This game is about the hard life in the kitchen. In this unusual place many interests intertwine. But the only war between humans and cockroaches is truly epic and destructive.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/527450/header.jpg?t=1574967759', 0, 0, NULL);
INSERT INTO games VALUES (45034, 527700, 'Containment Initiative', 'Containment Initiative is a local co-op VR shooter which can be played by two people on the same PC. Kill zombies alone in VR or have a friend cover you by using the mouse and keyboard. Features include realistic weapon reloading as well as a variety of unlockable guns, upgrades, and loot to find.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/527700/header.jpg?t=1746924809', 0, 0, NULL);
INSERT INTO games VALUES (45035, 527710, 'Crown Champion: Legends of the Arena', '&quot;Crown Champion: Legends of the Arena&quot; is a fantasy RPG/Management simulator set in the ruthless world of gladiatorial combat. Develop your academy and train your fighters. Increase your power and influence in the realm. Reap the rewards of your labours.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/527710/header.jpg?t=1748874632', 0, 0, NULL);
INSERT INTO games VALUES (45023, 527990, 'Gladiator Trainer', 'Rise through the ranks and lead your band of Gladiators to glory. Can you build the ultimate fighting force and a kingdom to rule all! Be careful who you trust. Becoming a Gladiator Trainer isn''t easy.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/527990/header.jpg?t=1574484220', 0, 0, NULL);
INSERT INTO games VALUES (75119, 528160, 'Solstice Chronicles: MIA', 'In this 2-player twin-stick shooter, use a friendly drone for a game-changing abilities. Survive waves, upgrade, and uncover the mystery in this cooperative, action-packed experience.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/528160/header.jpg?t=1729321233', 0, 0, NULL);
INSERT INTO games VALUES (45009, 528230, 'SYNTHETIK: Legion Rising', 'SYNTHETIK is an unforgiving tactical shooter rogue-lite where freedom and experimentation is key. Fight in a world overrun by the Machine Legion and their Gods. Experience the next level in gun-play and dive into unparalleled build options and Android upgrades. Can you defeat the Heart of Armageddon?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/528230/header.jpg?t=1707857791', 1, 0, NULL);
INSERT INTO games VALUES (44998, 528550, 'Drunkn Bar Fight', 'Drunkn Bar Fight is a simple, immersive, silly, rowdy game. Now with 4 player Co-op! The only limits to the mayhem is your imagination and your moral decency.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/528550/header.jpg?t=1701280859', 0, 0, NULL);
INSERT INTO games VALUES (45000, 528610, 'Double Dragon IV', 'The classical side-scroll action game, &quot;Double Dragon&quot; series'' newest sequel! A new legend begins!!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/528610/header.jpg?t=1671432813', 1, 0, NULL);
INSERT INTO games VALUES (45002, 528660, 'Spin Rush', 'Spin Rush is 2D arcade game, where you have to collect dots and match colors.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/528660/header.jpg?t=1696797265', 0, 0, NULL);
INSERT INTO games VALUES (45004, 528730, 'Crypt of the Serpent King', 'Crypt of the Serpent King is a medieval first-person hack''n''slash dungeon crawler with roguelike elements. Explore randomly generated dungeons, fighting underworld creatures along the way, all while avoiding traps and collecting loot!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/528730/header.jpg?t=1728642515', 0, 0, NULL);
INSERT INTO games VALUES (44984, 529060, 'Space Simulator', 'Realistic simulation of spaceflight in a full sized Solar System, with all the planets and their major moons. using real forces, distances, velocities and time. Chapter 1: The Apollo Days. Incredibly detailed Apollo Program missions starting with Apollo 8 lunar orbit missions.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/529060/header.jpg?t=1519645856', 0, 0, NULL);
INSERT INTO games VALUES (44991, 529160, 'Moekuri: Adorable + Tactical SRPG', 'It''s adorable! It''s tactical! The doujin/indie SRPG - Moékuri! 151+ Cute Creatures to try, over a solid grid-based tactical system! Fight through 25 story stages with your own unique strategy!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/529160/header.jpg?t=1572869081', 0, 0, NULL);
INSERT INTO games VALUES (44992, 529180, 'Dark and Light', 'Dark and Light is a vast sandbox survival RPG set in a world dominated by powerful elemental forces. Find your way in a meticulously crafted world, featuring breathtaking landscapes, a wide variety of mythical creatures, and limitless possibility to craft, build, and unlock dozens of powerful weapons, spells, and skills.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/529180/header.jpg?t=1666906165', 1, 0, NULL);
INSERT INTO games VALUES (44951, 529240, 'Creature Clicker - Capture, Train, Ascend!', 'A new creature collecting clicker game in which your goal is to capture all of the 50+ creatures, level them up to make them do more DPS and ascend them to gain better abilities. Unlock legendary variants and defeat all of the raid bosses &amp; every hour get a steam creature you can trade, buy or sell!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/529240/header.jpg?t=1719495115', 0, 1, NULL);
INSERT INTO games VALUES (128328, 529340, 'Victoria 3', 'Paradox Development Studio invites you to build your ideal society in the tumult of the exciting and transformative 19th century. Balance the competing interests in your society and earn your place in the sun in Victoria 3, one of the most anticipated games in Paradox’s history.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/529340/50324608304f1d80bdd554dda205910422d7612b/header_alt_assets_2.jpg?t=1747731985', 1, 0, NULL);
INSERT INTO games VALUES (44957, 529440, 'Behold the Kickmen', 'BEHOLD THE KICKMEN is a football game made by someone who has no understanding of, or interest in, what is affectionately known as &quot;The Wonderful Game&quot;. Start at the bottom of the Big Boring Football Spreadsheet and grind your way up to become the best at the football anyone''s ever seen.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/529440/header.jpg?t=1501851055', 0, 0, NULL);
INSERT INTO games VALUES (44959, 529490, 'Rogue Trooper Redux', 'A pioneering tactical shooter and landmark comic book adaptation, Rogue Trooper is back, remastered and revitalised in true high definition. Experience acclaimed third-person action in this BAFTA-nominated tale of betrayal and revenge at the far reaches of the galaxy!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/529490/header.jpg?t=1589876682', 0, 0, NULL);
INSERT INTO games VALUES (44961, 529520, 'Mutant Football League', 'Mutants and monsters unleash maniacal carnage on the gridiron in this crazy gore fest of arcade-style football. Packed full of humor, intense online multiplayer action, and strategy.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/529520/header.jpg?t=1719420325', 0, 0, NULL);
INSERT INTO games VALUES (44964, 529590, 'Please, Don''t Touch Anything 3D', 'Now with Vive Support! A cryptic, brain-racking, button-pushing non-linear puzzle game.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/529590/header.jpg?t=1688662166', 1, 0, NULL);
INSERT INTO games VALUES (44968, 529660, 'Mages of Mystralia', 'In a world of magic, your mind is your greatest weapon. Learn the ways of magic and design your own spells to fight enemies, navigate treacherous terrain, and right past wrongs in the kingdom of Mystralia.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/529660/header.jpg?t=1729114996', 1, 0, NULL);
INSERT INTO games VALUES (44935, 529890, 'Maniac Mansion', 'Quick, Dr. Fred''s Kidnapped Sandy and he''s about to start the experiment...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/529890/header.jpg?t=1741809547', 0, 0, NULL);
INSERT INTO games VALUES (44936, 529900, 'Polygon Attack', 'Break through unlimited waves of enemies and fight unpredictable bosses!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/529900/header.jpg?t=1540066195', 0, 0, NULL);
INSERT INTO games VALUES (44937, 529910, 'ARK Park', 'In ARK Park, engage in close encounters with primal species through a series of theme park attractions. Enter by yourself or with a group of adventurous friends, and witness dinosaurs roaming in the wild with your own eyes!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/529910/header.jpg?t=1666905940', 1, 0, NULL);
INSERT INTO games VALUES (44940, 529950, '12 orbits', '12 orbits is the only local multiplayer game for 2-12 people at once, no matter what you play on. A single keyboard, touchscreen or controller will do.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/529950/header.jpg?t=1698791046', 1, 0, NULL);
INSERT INTO games VALUES (44945, 530070, 'Train Sim World® 2020', 'Train Sim World is an immersive first-person simulator perfect for everyone, with complete in-cab interactivity, accurate detail on locos, real-world routes and hours of gameplay. Take to the rails with the brand-new Train Sim World 2020 Edition and find everything you need to master new skills.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/530070/header.jpg?t=1731433527', 0, 0, NULL);
INSERT INTO games VALUES (44948, 530120, 'VR The Diner Duo', 'You are a chef in VR who need to satisfy your customers in a limited amount of time. Share the experience with a friend in local multiplayer mode. Chaotic levels are waiting for you!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/530120/header.jpg?t=1513347715', 0, 0, NULL);
INSERT INTO games VALUES (44919, 530320, 'Wandersong', 'A musical platforming adventure with an emotional story. Play as a silly bard and use music to interact with everything on a journey around the world. Along the way you''ll explore, solve puzzles, and meet a huge cast of characters!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/530320/header.jpg?t=1728309447', 0, 0, NULL);
INSERT INTO games VALUES (44924, 530390, 'Slayaway Camp', 'A killer puzzle game where you control Skullface, a psycho slasher bent on slaughtering camp counselors at the title campground. Slide an adorable voxel murderer around hundreds of isometric puzzle levels to squash, flay, and decapitate hapless victims in this darkly comic homage to 80s horror.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/530390/header.jpg?t=1733346261', 0, 0, NULL);
INSERT INTO games VALUES (44913, 530560, 'STEAM HAMMER', 'Steam Hammer is the first hardcore sandbox RPG in a steampunk setting featuring survival elements. Here you''ll find all the advantages of sandbox games in the mysterious world of steam engines.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/530560/header.jpg?t=1549035733', 0, 0, NULL);
INSERT INTO games VALUES (44914, 530630, 'Empires Apart', 'An exciting free-to-play Real Time Strategy game set in medieval times. Uniquely designed factions, customization options, singleplayer and multiplayer gameplay. Gather resources, raise an army and lead your civilization to victory in a classic RTS, brought to the modern age.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/530630/header.jpg?t=1726824599', 1, 1, NULL);
INSERT INTO games VALUES (44897, 530890, 'Haydee', '&quot;Haydee&quot; is a hardcore old-style metroidvania mixed with modern-day third person shooter and platformer mechanics. As well as a sexy character.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/530890/header.jpg?t=1667317852', 1, 0, NULL);
INSERT INTO games VALUES (44898, 530920, 'Archimedes', 'After you purchase and install Archimedes, an old operating system appears to be running, and a strange man asks for your help as you start to discover the terrible secrets behind the game.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/530920/header.jpg?t=1572797939', 0, 0, NULL);
INSERT INTO games VALUES (44900, 530950, 'Tower 57', 'Tower 57 is a fast-paced neo-retro shooter where cooperation is as important as your ammo capacity. As a member of an extraordinary task force fight your way through a dieselpunk megatower and uncover its hidden secrets.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/530950/header.jpg?t=1727868949', 1, 0, NULL);
INSERT INTO games VALUES (44902, 531050, 'Far Beyond: A space odyssey VR', 'Far Beyond: A space odyssey VR is the first hardcore Rogue-like in Virtual Reality with a Sci-fi atmosphere and AAA graphics. It features a hard but rich gameplay focused on resources management, craft and strategy.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/531050/header.jpg?t=1515993577', 0, 0, NULL);
INSERT INTO games VALUES (44892, 531270, 'The Art of Fight | 4vs4 Fast-Paced FPS', 'The Art of Fight is the fastest-paced multiplayer shooter in VR.It uses a game-changing locomotion method that avoids motion sickness allowing unparalleled 4v4 competitive battles online or against configurable bots.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/531270/header.jpg?t=1545847676', 0, 1, NULL);
INSERT INTO games VALUES (44871, 531510, 'Just Shapes & Beats', '&quot;Just Shapes &amp; Beats&quot; is a chaotic co-op musical bullet-hell based on three simple things: avoid Shapes, move to the kick-ass Beats, and die, repeatedly.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/531510/header.jpg?t=1738790023', 1, 0, NULL);
INSERT INTO games VALUES (44876, 531640, 'Eternal Card Game', 'Six-guns and sorcery collide in Eternal, the new strategy card game of unlimited choices and unbelievable fun. Eternal brings AAA pace and polish to the infinite possibilities of a deep strategy card game. The only limits are your own creativity.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/531640/header.jpg?t=1737566664', 0, 1, NULL);
INSERT INTO games VALUES (44877, 531660, 'Exoplanet: First Contact', 'Build your path in this alien world. Do a dirty job for food or become the one who makes calls. Sometimes the right word makes a bigger impact than a big gun. Explore local culture and mysteries, and discover the harsh yet beautiful nature in this handcrafted singleplayer action RPG.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/531660/header.jpg?t=1748875115', 0, 0, NULL);
INSERT INTO games VALUES (44878, 531680, '8-Bit Invaders!', '8-Bit Invaders! is a fast-paced, retro Real-Time Strategy game for the PC. Control the military might of the Galactic Marine Corps or Invade with the devastating power of the Cranioids! Mine, Build, and Fight your way to victory! Conquering the Multiverse was never so easy.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/531680/header.jpg?t=1667950466', 0, 0, NULL);
INSERT INTO games VALUES (44886, 531930, 'Dungeon Rats', 'A turn-based, party-based RPG set in the Age of Decadence world and focused on squad level tactical combat. Fight your way out of prison mine or die trying.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/531930/header.jpg?t=1735438415', 0, 0, NULL);
INSERT INTO games VALUES (44862, 532110, 'Rusty Lake: Roots', 'Experience the beginning and end of characters'' lives and build your own family tree! Rusty Lake: Roots is the second premium point-and-click adventure by the creators of the Cube Escape series and Rusty Lake Hotel.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/532110/header.jpg?t=1746052939', 1, 0, NULL);
INSERT INTO games VALUES (44865, 532190, 'Super Blood Hockey', 'Create and manage your team in a violent, dystopic world of no-rules, fast-paced, arcade-style, ice hockey action. Adjust training regimens, control diets, administer black market pharmaceuticals, and provide healthcare (or not) to a ragtag team of convicts at the mercy of your underhanded tactics.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/532190/header.jpg?t=1729072014', 0, 0, NULL);
