INSERT INTO games VALUES (44869, 532320, 'de Blob', 'The evil I.N.K.T. Corporation has declared ''Color is a Crime!'' and leeched Chroma City of all its beauty and interest. The race to rescue Chroma City has just begun, and only de Blob can save the world from a black-and-white future with his unique abilities to color the world back to life.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/532320/header.jpg?t=1725285154', 1, 0, NULL);
