INSERT INTO games VALUES (44828, 533300, 'Zup!', 'Minimal physical puzzle with explosions', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/533300/header.jpg?t=1674745921', 1, 0, NULL);
