INSERT INTO games VALUES (44804, 534290, 'Cursed Castilla (Maldita Castilla EX)', 'Cursed Castilla (Maldita Castilla EX) is an arcade action platformer full of creatures from medieval myths from Spain and the rest of Europe, as well as from chivalric romances. The extended version of the classic Maldita Castilla, originally created by the indie Locomalito.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/534290/header.jpg?t=1746007754', 0, 0, NULL);
INSERT INTO games VALUES (44807, 534370, 'Pure Farming 2018', 'Use the latest technology and state-of-the-art licensed machines to manage all aspects of modern farming. Travel between Europe, Asia, and both Americas to plant region-specific crops such as hemp, coffee beans, and olives. Farm your way thanks to three unique game modes tailored to both simulation veterans and newcomers to farming games.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/534370/header.jpg?t=1639505951', 0, 0, NULL);
INSERT INTO games VALUES (135938, 534380, 'Dying Light 2 Stay Human: Reloaded Edition', 'Humanity is fighting a losing battle against the virus. Experience a post-apocalyptic open world overrun by hordes of zombies, where your parkour and combat skills are key to survival. Traverse the City freely during the day, but watch the monsters take over during the night.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/534380/header.jpg?t=1739988558', 1, 0, NULL);
