INSERT INTO games VALUES (44650, 539470, 'Police Stories', 'A fresh take on top-down shooters with an emphasis on tactics that forces you to make split second decisions. Neutralize criminals, rescue civilians and defuse bombs in Single Player mode or Co-op. And remember - shooting first is not an option!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/539470/676ca8b7da835e3c527e16ce3a18d69002883ac0/header.jpg?t=1749303946', 1, 0, NULL);
