INSERT INTO games VALUES (44612, 540610, 'Delicious! Pretty Girls Mahjong Solitaire', 'The Pretty Girls are back and they''re delicious! Check out an upgraded version of Zoo''s top selling Mahjong Solitaire with 8 new girls and a candy flavored theme. Match tile pairs to reveal a Pretty Girl in a sexy outfit hiding underneath. As you clear stages, the girls get more and more delicious!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/540610/header.jpg?t=1726635628', 0, 0, NULL);
