INSERT INTO games VALUES (44606, 540880, 'Rose of Winter', 'Rose of Winter is a charming visual novel with adventure, romance, and heartbreak. Choose one of four princes to take on your adventure, and make decisions to unlock multiple endings.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/540880/header.jpg?t=1561410603', 0, 0, NULL);
INSERT INTO games VALUES (44599, 541200, 'GTTOD: Get To The Orange Door', 'RISE. FALL. REPEAT. Ascend to the level of the Gods as you battle your way out of a shattered and chaotic dimension in this fast paced parkour FPS rogue-like.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/541200/header.jpg?t=1719522871', 0, 0, NULL);
INSERT INTO games VALUES (44600, 541210, 'Cold Waters', 'Spiritual Successor to the Microprose Classic “Red Storm Rising”.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/541210/header.jpg?t=1731022734', 0, 0, NULL);
INSERT INTO games VALUES (44601, 541230, 'Alien Shooter TD', 'Innovative Tower Defense inspired by legendary Alien Shooter series! The game was created in keeping with the best traditions of Sigma''s games, no concessions of any kind - everything is just like in real life!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/541230/header.jpg?t=1710345172', 1, 0, NULL);
INSERT INTO games VALUES (44603, 541300, 'Survive the Nights', 'Survive the Nights is a unique FPS survival game focusing on teamwork, fortification, creativity &amp; strategy. Secure a structure or roam free, the choice is yours. Gameplay focuses on realistic survival, post zombie infestation. Prepare during the day for nightfall. How many nights will you survive?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/541300/header.jpg?t=1739193792', 1, 0, NULL);
INSERT INTO games VALUES (44582, 541310, 'Tiny Thor', 'Jump into this challenging retro platformer! Play as Thor, use his mighty hammer and unique items to explore the Northern Realms. Beware of mythical creatures blocking your path to become a god!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/541310/header.jpg?t=1727774558', 0, 0, NULL);
INSERT INTO games VALUES (137734, 541570, 'Sally Face - Episode One', 'Delve into a dark adventure following the boy with a prosthetic face and a tragic past. Unravel the sinister mysteries of Sally''s world to find the truth that lies hidden beneath the shadows.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/541570/header.jpg?t=1748961941', 0, 0, NULL);
INSERT INTO games VALUES (44590, 541640, 'Disney Infinity 1.0: Gold Edition', 'Enjoy Disney Infinity with a Full Toy Box! Disney Infinity 1.0: Gold Edition gives you the freedom to create stories and play experiences with all Disney Infinity 1.0 Characters and Playsets Unlocked and ready for you to mix, match and mash up to invent just about any adventure you can imagine.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/541640/header.jpg?t=1571776415', 0, 0, NULL);
INSERT INTO games VALUES (44591, 541660, 'Disney Infinity 2.0: Gold Edition', 'Enjoy Disney Infinity with a Full Toy Box! Disney Infinity 2.0: Gold Edition invites you to enter the worlds of Disney Storytelling and Marvel Adventures with all Disney Infinity 2.0 Characters and Playsets Unlocked to enjoy experiences only Disney, Marvel, and your imagination can bring to life.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/541660/header.jpg?t=1571776448', 0, 0, NULL);
INSERT INTO games VALUES (44592, 541670, 'Disney Infinity 3.0: Gold Edition', 'Enjoy Disney Infinity with a Full Toy Box! Disney Infinity 3.0: Gold Edition includes Star Wars with the existing collection of Marvel and Disney characters and worlds, and NOW with all Characters and Playsets Unlocked. Embark on adventures as big as your imagination in the 3.0 Toy Box!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/541670/header.jpg?t=1571776454', 0, 0, NULL);
INSERT INTO games VALUES (44568, 541930, 'Panoptic', 'Panoptic is a local multiplayer VR game that pits you against a friend, where you play as either the giant Overseer or tiny Challenger in a stealthy game of cat and mouse. Will the Challenger slip away undetected through the crowds, or will the Overseer track them down with their powerful laser eye?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/541930/header.jpg?t=1613494458', 0, 0, NULL);
INSERT INTO games VALUES (44571, 542050, 'Forgotton Anne', 'Step into a hand-animated realm of wonder in which everyday objects take on a life of their own. Uncover the Forgotlings’ mysteries &amp; harness magical forces as you embark upon a quest to return home.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/542050/header.jpg?t=1741613604', 1, 0, NULL);
INSERT INTO games VALUES (44576, 542200, 'Animal Lover', 'Evil forces have turned these five hunky beefcake time-displaced boys into animals! You''ve got to help cure them and maybe even fall in love! Mystery! Intrigue! Romance! No furries, despite the title! A dating sim by Wilson Taylor, Maia Gross and Travis Tohill.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/542200/header.jpg?t=1572306160', 0, 0, NULL);
INSERT INTO games VALUES (44552, 542350, 'Castle of no Escape 2', 'Explore 6 x 6 x 6 = 216 rooms of randomly generated hazards and enemies while collecting the necessary artefacts. Hundreds of monsters are roaming inside, guarding the sword shards — the last known thing to be capable of defeating the demonic castle owner.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/542350/header.jpg?t=1661361953', 1, 0, NULL);
INSERT INTO games VALUES (44553, 542400, 'Pixel Gladiator', 'Distant future… Brutal gladiatorial battles is a top-rated show, extremely popular all over the Universe. You’ve been sent to the abandoned planet as one of the participants of the show. Your goal is to survive as long as possible, fighting back deadly creatures in the focus of billions of viewers.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/542400/header.jpg?t=1632143003', 0, 0, NULL);
INSERT INTO games VALUES (44534, 542770, 'Castle Must Be Mine', 'Castle Must Be Mine is a KingdomRush-like tower defense game. But developed for VR. In addition to constantly collecting Coins to building and upgrading defensive towers, also need to make full use of all kinds of skills and props to stop the &quot;enemies&quot; into your castle.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/542770/header.jpg?t=1531488180', 0, 0, NULL);
INSERT INTO games VALUES (44545, 543010, 'Bush Hockey League', 'Aggressive hockey is back! Experience hockey the way it was meant to be played in this old school arcade style hockey game where blood on the ice is just another day at the rink. Big moustaches, no helmets, dirty hits, bench-clearing brawls, goalie fights, and stick fights – that’s Bush Hockey League.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/543010/header.jpg?t=1509148890', 0, 0, NULL);
INSERT INTO games VALUES (44546, 543030, 'Slap The Fly', 'You will embody a fly, a spider, a bee or a human. Your mission thus is to survive or to slap the fly !', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/543030/header.jpg?t=1478722886', 0, 0, NULL);
INSERT INTO games VALUES (44516, 543240, '√Letter - Root Letter -', 'When a letter is delivered 15 years late - you discover an old pen-friend was involved in a murder, before she disappeared. Travelling to her hometown, you must investigate the murder, using her past letters as clues to uncover the disturbing truth.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/543240/header.jpg?t=1700020104', 0, 0, NULL);
INSERT INTO games VALUES (44517, 543260, 'Wonder Boy: The Dragon''s Trap', 'Boasting beautiful, hand-drawn animations and a re-orchestrated soundtrack, the cult classic returns with a unique blend of exploration, action, and adventure!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/543260/header.jpg?t=1738848243', 0, 0, NULL);
INSERT INTO games VALUES (44524, 543390, 'Aeon', 'A primitive god in ancient Greek mythology who controls time, is resurrected in the virtual world, Inspired by &quot;The Matrix&quot; and &quot;Deadpool&quot; (remember,the slower you move the slow time goes）', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/543390/header.jpg?t=1664086028', 0, 0, NULL);
INSERT INTO games VALUES (44528, 543460, 'Dead Rising 4', 'Dead Rising 4 marks the return of photojournalist Frank West in an all-new chapter of one of the most popular zombie game franchises of all time. With an unmatched level of weapon and character customization, ambitious new features including new zombie classes and EXO Suits, Dead Rising 4 delivers a heart-pounding experience as players...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/543460/header.jpg?t=1644282464', 1, 0, NULL);
INSERT INTO games VALUES (44501, 543870, 'NARUTO SHIPPUDEN: Ultimate Ninja STORM 2', 'NARUTO SHIPPUDEN: Ultimate Ninja STORM 2 is a tour de force of Naruto thrills and spills. Impressively faithful to the universe of the anime, the game takes players through the Shippuden story arc. Ultimate Ninja STORM 2 has been remastered in HD.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/543870/header.jpg?t=1701323477', 0, 0, NULL);
INSERT INTO games VALUES (44502, 543900, 'METAL GEAR SURVIVE', 'METAL GEAR SURVIVE builds upon MGSV’s stealth action gameplay with elements of exploration and survival creating a bold new experience. *An internet connection is required to play the game.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/543900/header.jpg?t=1718869280', 1, 0, NULL);
INSERT INTO games VALUES (44478, 543980, 'Zombie Exodus: Safe Haven', 'Zombies rise again at the dawn of Apocalypse! In this companion to the smash-hit Zombie Exodus, can you survive the early days of society''s collapse?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/543980/header.jpg?t=1734032095', 0, 0, NULL);
INSERT INTO games VALUES (44485, 544310, 'Jumps', 'Enter a world of sky islands and jump your way to the finish, you must complete each level with a certain amount of jumps! and HURRY, you must complete each world in under a certain amount of time.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/544310/header.jpg?t=1721895956', 0, 0, NULL);
INSERT INTO games VALUES (44486, 544330, 'Snake Pass', 'Slither, coil and climb your way to the top of Haven Tor in this one of a kind physics based, puzzle platform adventure from award winning independent studio Sumo Digital!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/544330/header.jpg?t=1747992036', 0, 0, NULL);
INSERT INTO games VALUES (44490, 544390, 'NITE Team 4 - Military Hacking Division', 'NITE Team 4 is a military hacking simulation game that explores the world of cyberwarfare and features realistic mission scenarios.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/544390/header.jpg?t=1634299183', 0, 0, NULL);
INSERT INTO games VALUES (139931, 544550, 'Stationeers', 'Stationeers puts you in control of the construction and management of a space station to run by yourself or online with your friends. Complex atmospheric, electrical, manufacturing, agriculture, and gravitational systems require your thought and management at all times!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/544550/header.jpg?t=1738899337', 1, 0, NULL);
INSERT INTO games VALUES (44463, 544610, 'Battlestar Galactica Deadlock', 'In Battlestar Galactica Deadlock™ you’ll take command of the Colonial Fleet in defense of the Twelve Colonies during the First Cylon War. Lead many different types of ships in this 3D tactical game. Every decision counts, your strategy will be vital – can you ensure mankind’s survival?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/544610/header.jpg?t=1745952509', 0, 0, NULL);
INSERT INTO games VALUES (44470, 544750, 'SOULCALIBUR VI', 'Bring more than your fists to the fight! Featuring all-new battle mechanics and characters, SOULCALIBUR VI marks a new era of the historic franchise. Welcome back to the stage of history!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/544750/header.jpg?t=1718967845', 1, 0, NULL);
INSERT INTO games VALUES (138292, 544920, 'Darwin Project', 'In Darwin Project, ten inmates must survive the elements, track each other, fight, craft tools, and use their social skills to be the last one standing. It''s a unique take on battle royale with a Show Director to influence the match and Spectator Interactions to create a one-of-a-kind game show.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/544920/header.jpg?t=1734022522', 1, 1, NULL);
INSERT INTO games VALUES (44441, 544970, 'Milkmaid of the Milky Way', 'Milkmaid of the Milky Way is an award-winning point-and-click adventure game in rhyme that combines a gripping story with puzzles and exploration. What happens when a young milkmaid sees an alien craft in a fjord in 1920''s Norway?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/544970/header.jpg?t=1666984737', 0, 0, NULL);
INSERT INTO games VALUES (44443, 545040, 'Feather', 'Feather is a multiplayer game about exploration, relaxation and immersion. Transform yourself into a bird, take flight, and enjoy a zen-like, picturesque landscape on your own terms. Swoop, glide, and backflip your way around mysterious locations to uncover hidden paths that only birds can follow!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/545040/header.jpg?t=1747870530', 1, 0, NULL);
INSERT INTO games VALUES (44444, 545050, 'Badiya: Desert Survival', 'Badiya is a Sandbox Survival RPG set in the WWI era desert lands. Badiya challenges you to brave the sands, take part in wars, ply the spice routes, or hunt for treasure as you strive to fulfill your ambitions.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/545050/header.jpg?t=1617198526', 0, 0, NULL);
INSERT INTO games VALUES (44451, 545270, 'NBA Playgrounds', 'Classic NBA arcade action is back! Take your “A” game to the playground and beat the best in high-flying 2-on-2 basketball action. Practice your skills offline, play with up to three others and take your talents online to posterize your opponents with acrobatic jams and ridiculous displays of skill.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/545270/header.jpg?t=1538774766', 0, 0, NULL);
INSERT INTO games VALUES (44422, 545410, 'A Trip to Yugoslavia: Director''s Cut', 'A TRIP TO YUGOSLAVIA is an experimental interactive game with a theme of the old VCR player (with the ability to REWIND, PAUSE and FASTFORWARD).', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/545410/header.jpg?t=1693066487', 0, 0, NULL);
INSERT INTO games VALUES (44427, 545540, 'The Infectious Madness of Doctor Dekker', 'YOU are a psychiatrist, trying to solve a murder whilst treating the unusual patients of the recently deceased Doctor Dekker. Type a question - patients reply in full screen video and have questions for you too but be careful what you say. Your words determine their eventual fates, and your own!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/545540/header.jpg?t=1730113024', 0, 0, NULL);
INSERT INTO games VALUES (44432, 545600, 'Vigilantes', 'Vigilantes is a combat focused, turn-based tactical RPG set in the crime riddled city of Reiker. The game offers hardcore squad-level combat in a gritty neo-noir setting, intel gathering through surveillance and interrogation, a detailed character system, base facilities, crafting, and more.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/545600/header.jpg?t=1635504890', 0, 0, NULL);
INSERT INTO games VALUES (44437, 545690, 'VOI', 'Do you think 1 + 1 = 0 is correct? So what do you think about &quot;black + black = white&quot; statement?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/545690/header.jpg?t=1614020594', 0, 0, NULL);
INSERT INTO games VALUES (44403, 545980, 'Voodoo Vince: Remastered', 'The classic character platformer is back after 13 years and newly remastered! Help Vince run, jump and fight his way through cemeteries, swamps and an evil carnival as he seeks to save his creator Madam Charmaine from the clutches of Kosmo The Inscrutable.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/545980/header.jpg?t=1744067351', 0, 0, NULL);
INSERT INTO games VALUES (44406, 546050, 'Puyo Puyo™Tetris®', 'Two puzzle game juggernauts collide as global phenomenon Tetris® and SEGA’s famous Puyo Puyo™ combine in a super mash-up of ferocious competition, adorable looks, and addictive puzzle fun!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/546050/header.jpg?t=1718358784', 0, 0, NULL);
INSERT INTO games VALUES (44408, 546080, 'Coffin of Ashes', 'Delilah is an ordinary school girl who accidentally discovers an old mansion on a rainy night. As her exploration in the mansion continues, she finds many mysterious phenomena that can''t be explained. In this mansion covered by ashes, what''s the secret hidden deep underground?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/546080/header.jpg?t=1630753168', 0, 0, NULL);
INSERT INTO games VALUES (44383, 546430, 'Pathway', 'Explore the strange unknown with Pathway, a strategy adventure set in the 1930s great wilderness. Unravel long-forgotten mysteries of the occult, raid ancient tombs and outwit your foes in turn-based squad combat!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/546430/header.jpg?t=1732203926', 0, 0, NULL);
INSERT INTO games VALUES (132794, 546560, 'Half-Life: Alyx', 'Half-Life: Alyx is Valve’s VR return to the Half-Life series. It’s the story of an impossible fight against a vicious alien race known as the Combine, set between the events of Half-Life and Half-Life 2. Playing as Alyx Vance, you are humanity’s only chance for survival.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/546560/header.jpg?t=1673391297', 1, 0, NULL);
INSERT INTO games VALUES (44374, 546930, 'Machine Hunt', 'Machine Hunt is a first person, fast paced, chaotic shooting game that pits heavily armed players against machines that have only one goal, destroy humanity.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/546930/header.jpg?t=1747501265', 0, 0, NULL);
INSERT INTO games VALUES (44343, 546980, 'Midnight Carnival', 'Midnight Carnival is a Visual Novel with a dark and disturbing story and theme.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/546980/header.jpg?t=1496249282', 0, 0, NULL);
INSERT INTO games VALUES (44359, 547340, 'LoveKami -Divinity Stage-', 'MoeNovel''s exciting new original title, LoveKami -Divinity Stage-, debuts on Steam in English, bringing a fun and energetic tale filled with magic and music!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/547340/header.jpg?t=1573642394', 0, 0, NULL);
INSERT INTO games VALUES (44360, 547360, 'BREAK ARTS II', 'Faster than anyone. Stronger than anyone. And more stunning. Customize your robot for “cyber battle racing” in a game that offers all the thrills of racing, battle, and customization. Online, Offline, Time-Attack... which mode will you dominate?!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/547360/header.jpg?t=1734440171', 1, 0, NULL);
INSERT INTO games VALUES (44363, 547410, 'Peak Angle: Drift Online', 'Peak Angle: Drift Online is a real-time massively multiplayer online (MMO) simulator for PCs running on Windows platform. The concept of the game is based on drifting competitions in Player vs Player mode.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/547410/header.jpg?t=1693543587', 0, 0, NULL);
INSERT INTO games VALUES (44333, 547480, 'Carly and the Reaperman - Escape from the Underworld', 'Join the adventure of Carly and the Reaperman in the Underworld! Master platforming to avoid dangers, solve puzzles and build your way to through dozens of fun and challenging obstacles to the finish line - play alone or with a friend!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/547480/header.jpg?t=1698244314', 1, 0, NULL);
INSERT INTO games VALUES (44336, 547590, 'Pinball FX2 VR', 'Creating a brand new way to play pinball that deftly combines the look and feel of digital pinball with the sensation of a real-world experience, Pinball FX2 VR is the premiere place for pinball action in VR!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/547590/header.jpg?t=1727783443', 0, 0, NULL);
INSERT INTO games VALUES (44338, 547680, 'Guild Quest', 'You’ve just bought yourself a new island and it’s time to fill it up with QUESTS! Collect guildians, upgrade their guildhalls, and unleash them onto your own custom quest lines.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/547680/header.jpg?t=1497477445', 0, 1, NULL);
INSERT INTO games VALUES (44315, 547900, 'Front Office Football Eight', 'Put yourself in the Front Office with Front Office Football, the professional football simulation from Solecismic Software. Manage your roster through trading, free agency and the amateur draft. Create game plans, organize depth charts and watch your franchise thrive for decades.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/547900/header.jpg?t=1613806720', 0, 0, NULL);
INSERT INTO games VALUES (44316, 547910, 'The Survey', 'In the end, everybody gets what they deserve. The sins of the past always manifest within the minds of the sinners. An eternity of suffering awaits, welcome to The Survey.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/547910/header.jpg?t=1645436617', 0, 0, NULL);
INSERT INTO games VALUES (44301, 548340, 'Abode', 'Abode is an escape room puzzle game. You will have to find, combine and utilize tools and furniture in the room to unveil all its secrets.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/548340/header.jpg?t=1622787433', 0, 0, NULL);
INSERT INTO games VALUES (44303, 548370, 'Rezrog', 'Test your fighting spirit as you take your party of brave adventurers on an epic quest to restore peace to the lands of Rezrog in this table-top inspired, turn-based, dungeon crawler. Upgrade your skills &amp; tactically exploit enemy weaknesses as you try to handle everything the dungeons will throw at you.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/548370/header.jpg?t=1631541797', 1, 0, NULL);
INSERT INTO games VALUES (137615, 548430, 'Deep Rock Galactic', 'Deep Rock Galactic is a 1-4 player co-op FPS featuring badass space Dwarves, 100% destructible environments, procedurally-generated caves, and endless hordes of alien monsters.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/548430/header.jpg?t=1745514515', 1, 0, NULL);
INSERT INTO games VALUES (44309, 548570, 'RAGE 2', 'RAGE 2 brings together two studio powerhouses – Avalanche Studios, masters of open world insanity, and id Software, creators of the first-person shooter – to deliver a carnival of carnage where you can go anywhere, shoot anything, and explode everything.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/548570/header.jpg?t=1706806221', 1, 0, NULL);
INSERT INTO games VALUES (44291, 548840, 'A Rose in the Twilight', 'A girl awakens in a castle void of color and time, affixed with the Curse of Thorns upon her back. After meeting a sleeping giant, the two work together to escape. Help them unravel the mystery of the thorns and the history behind the somber castle.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/548840/header.jpg?t=1732583049', 0, 0, NULL);
INSERT INTO games VALUES (44271, 549080, 'Tank Warfare: Tunisia 1943', 'Tank Warfare: Tunisia 1943 - tactical battalion level combat simulation. During the Tunisian Campaign in winter 1943 German Panzer battlegroups launch a counteroffensive against the Allied forces to drive them out of Eastern Dorsal.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/549080/header.jpg?t=1712088793', 0, 0, NULL);
INSERT INTO games VALUES (44273, 549100, 'GravNewton', 'Challenge all your skill and quick thinking ability in this precision platform game, where you are a bitrom who controller over gravity called Newton, who is trying to escape from a deformed creature that relentlessly follows him in subspace.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/549100/header.jpg?t=1722340192', 0, 0, NULL);
INSERT INTO games VALUES (44279, 549240, 'Beans: The Coffee Shop Simulator', 'Beans is a sardonic ''tycoon'' simulation game about hipsters running a coffee shop replete with dismal puns, coffee, chiptunes, and mystery!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/549240/header.jpg?t=1746724062', 0, 0, NULL);
INSERT INTO games VALUES (44252, 549860, 'One Night Stand', 'After a night of fun, passion, and one too many drinks, you wake up the next morning to find a complete stranger lying naked beside you in bed. What do you do?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/549860/header.jpg?t=1730879575', 0, 0, NULL);
INSERT INTO games VALUES (44259, 550010, 'Happy Room', 'Welcome to the laboratory! Here tests are taken upon highly durable human clones using newest weapon technologies. Your goal is to head these tests.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/550010/header.jpg?t=1647542460', 1, 0, NULL);
INSERT INTO games VALUES (44260, 550080, 'VALKYRIE DRIVE -BHIKKHUNI-', 'VALKYRIE DRIVE -BHIKKHUNI- is the all-new all-action brawler from the creators of SENRAN KAGURA. The girls of Bhikkhuni are infected with the mysterious VR-Virus and the only way to control it is to fight.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/550080/header.jpg?t=1594636252', 0, 0, NULL);
INSERT INTO games VALUES (44232, 550310, 'Root Of Evil: The Tailor', 'You will play a telepath named James. He has the ability to connect with the soul thus he can understand their past. He was hired to explore what happened in the previous 20 years in a haunted house This is the puzzle game!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/550310/header.jpg?t=1586603506', 1, 0, NULL);
INSERT INTO games VALUES (44233, 550320, 'art of rally', 'Race in the golden era of rally. Drive iconic cars from the 60s to Group B on challenging stages through stylized environments inspired by real worldwide locations. Will you master the art of rally?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/550320/header.jpg?t=1738502268', 1, 0, NULL);
INSERT INTO games VALUES (44234, 550340, 'Umineko: Golden Fantasia', 'The tag-team fighting game based on the original &quot;Umineko When They Cry&quot; series, finally released on Steam, in English and with improved rollback netplay!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/550340/header.jpg?t=1725518107', 0, 0, NULL);
INSERT INTO games VALUES (44245, 550590, 'Archaica: The Path of Light', 'Archaica is an atmospheric puzzler with lasers and mirrors, that introduces a mystical and ancient world, full of challenging puzzles. In this game, we become the Light Bearer who is sent on a quest to walk the legendary Path of Light and save the world from impending disaster.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/550590/header.jpg?t=1739824314', 0, 0, NULL);
INSERT INTO games VALUES (44224, 550670, 'What The Heck, Dude?', 'What The Heck Dude? is a drunk fight simulator with realistic physics. You are going to find yourself in different life situations, and every time you will have to start a fight. No matter where are you and what you are doing, your only task is to spoil the event and initiate a brawl.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/550670/header.jpg?t=1709391718', 0, 0, NULL);
INSERT INTO games VALUES (44229, 550840, 'Fresh Body', 'Defeat your enemies , take their body parts to replace yours and become another strong boss yourself.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/550840/header.jpg?t=1678833959', 0, 0, NULL);
INSERT INTO games VALUES (44222, 551110, 'Wayout', 'Relax, clear your mind and find the way out.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/551110/header.jpg?t=1627832282', 1, 0, NULL);
INSERT INTO games VALUES (44208, 551170, 'Onmyoji', 'Onmyoji is a turn-based fantasy strategy game with PVP or PVE battles, where you can strengthen your beloved shikigami to build your dream tactical team and defeat various demons to become the ultimate onmyoji. Cross-platform play available for both Steam and English mobile versions.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/551170/header.jpg?t=1589523174', 0, 1, NULL);
INSERT INTO games VALUES (44209, 551190, '123 Slaughter Me Street 2', 'In this exciting prequel to the hit game &quot;123 Slaughter Me Street&quot;, we find out the deep dark secrets that lead up to the madness of this series. You find yourself confused with blood on your hands in a dark house with only a flashlight to guide you.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/551190/header.jpg?t=1722570479', 0, 0, NULL);
INSERT INTO games VALUES (44215, 551450, 'Furious Angels', 'Furious Angels is a brutal score attack shooter with different waves each day. Compete on the leaderboards, transform into a flying tank and shred the skies to pieces!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/551450/header.jpg?t=1666986277', 0, 0, NULL);
INSERT INTO games VALUES (138872, 551620, 'Approaching Infinity', 'Approaching Infinity is a turn-based space RPG in the spirit of the sci-fi classics, with endless progression and exploration. Fight tactical battles or use diplomacy. Seek powerful artifacts. Quest, mine, trade, and craft. Level up forever or attempt 10 victories in hardcore or adventure mode.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/551620/header.jpg?t=1746033307', 0, 0, NULL);
INSERT INTO games VALUES (44197, 551700, 'Gunheart', 'Gunheart is an online co-op RPG shooter where you and your friends become customizable robotic bounty hunters trying to make a buck at the edge of the galaxy. Encounter menacing aliens, explore exotic locations, unlock new gear, and rake in cash to boost your rig.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/551700/header.jpg?t=1676569542', 0, 0, NULL);
INSERT INTO games VALUES (44201, 551770, 'ECHO', 'After a century in stasis the girl En arrives at her destination: A Palace out of legend. Out here, using forgotten technologies, she hopes to bring back a life that shouldn’t have been lost. But nothing could prepare her for what she’ll face in the ancient halls below.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/551770/header.jpg?t=1747988640', 0, 0, NULL);
INSERT INTO games VALUES (44204, 551860, 'Abandon Ship', 'Take command of an ''Age of Sail'' ship and her crew, exploring a vast, story-filled world that reacts to your decisions. Engage enemy vessels, fortifications and sea monsters in brutal tactical combat, all framed in an art style inspired by classic Naval Oil Paintings.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/551860/header.jpg?t=1747235888', 0, 0, NULL);
INSERT INTO games VALUES (44183, 552080, 'IronWolf VR', 'IronWolf VR is a roomscale submarine game playable either singleplayer or online co-op with motion controls. Built from the ground up for VR, each part of the submarine has been crafted for an optimal VR experience.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/552080/header.jpg?t=1726481766', 0, 0, NULL);
INSERT INTO games VALUES (134974, 552100, 'Brick Rigs', 'Build your own vehicles or download one of the more than 200,000 creations already uploaded to the Workshop and experience the dynamic driving and destruction physics of Brick Rigs!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/552100/header.jpg?t=1749200940', 0, 0, NULL);
INSERT INTO games VALUES (44188, 552160, 'Hade', 'Hade is a minimalist logic game with severely difficult puzzles softened by relaxing ambient music.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/552160/header.jpg?t=1548172360', 1, 0, NULL);
INSERT INTO games VALUES (44166, 552440, 'The Talos Principle VR', 'The Talos Principle VR is a virtual reality version of Croteam''s critically acclaimed first-person puzzle game in the tradition of philosophical science fiction.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/552440/header.jpg?t=1710246995', 1, 0, NULL);
INSERT INTO games VALUES (44167, 552450, 'Serious Sam VR: The First Encounter', 'Serious Sam VR: The First Encounter is a frantic arcade action FPS, featuring singleplay and co-op campaign, various multiplayer modes, all presented in glorious VR and with different locomotion movements.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/552450/header.jpg?t=1569336466', 0, 0, NULL);
INSERT INTO games VALUES (44168, 552460, 'Serious Sam VR: The Second Encounter', 'Serious Sam VR: The Second Encounter is a sequel to Serious Sam VR: The First Encounter - frantic arcade action FPS, featuring singleplay and co-op campaign, various multiplayer modes, all presented in glorious VR and with different locomotion movements.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/552460/header.jpg?t=1569336553', 0, 0, NULL);
INSERT INTO games VALUES (136026, 552500, 'Warhammer: Vermintide 2', 'The critically acclaimed Vermintide 2 is a visually stunning and groundbreaking melee action game pushing the boundaries of the first person co-op genre. Join the fight now!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/552500/header.jpg?t=1747931220', 0, 0, NULL);
INSERT INTO games VALUES (44174, 552590, 'The Sexy Brutale', 'The Sexy Brutale — a never-ending masked ball featuring intrigue, murder and the (quite possibly) occult! Relive the same mysterious day where the guests at the casino mansion are being murdered by the staff over and over again...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/552590/header.jpg?t=1746524519', 0, 0, NULL);
INSERT INTO games VALUES (44176, 552620, 'ATOM RPG: Post-apocalyptic indie game', 'ATOM RPG is a post-apocalyptic indie game, inspired by classic CRPGs: Fallout, Wasteland, Deus Ex, Baldur''s Gate and many others.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/552620/header.jpg?t=1743568860', 0, 0, NULL);
INSERT INTO games VALUES (44136, 552700, 'WORLD OF FINAL FANTASY®', 'CAPTURE, CUSTOMISE AND EVOLVE! Embark on a magical journey with siblings Reynn and Lann as they explore the vast land of Grymoire to rediscover their past and save the future.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/552700/header.jpg?t=1724998897', 1, 0, NULL);
INSERT INTO games VALUES (44142, 552880, 'STARDROP', 'STARDROP is an interactive sci-fi cinematic experience.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/552880/header.jpg?t=1651755513', 0, 0, NULL);
INSERT INTO games VALUES (44147, 552970, 'Sumoman', 'Sumoman is an adventure puzzle platformer with advanced physics, destructible objects and the ability to reverse time. Solve various physical puzzles, trying to keep the unstable Sumoman on his feet in challenging environments.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/552970/header.jpg?t=1726568323', 0, 0, NULL);
INSERT INTO games VALUES (133489, 552990, 'World of Warships', 'Immerse yourself in thrilling naval battles and assemble an armada of over 600 ships from the first half of the 20th century — from stealthy destroyers to gigantic battleships. Change the look of your ship, choose upgrades to suit your play style, and go into battle with other players!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/552990/32c2a96365c4ea5906860006238e0ed556f44fd5/header.jpg?t=1749027424', 1, 1, NULL);
INSERT INTO games VALUES (44127, 553260, 'Realpolitiks', 'Become the leader of any contemporary country in this streamlined real-time grand strategy game. Use diplomacy, espionage, military and economic power to deal with other nations, while tackling issues such as terrorism, financial crises and medical epidemics, all in an effort to achieve global domination!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/553260/header.jpg?t=1726486964', 0, 0, NULL);
INSERT INTO games VALUES (44129, 553310, 'Lethal League Blaze', 'Banging beats and mad style, Lethal League Blaze is the most intense ball game you can play online with up to 4 players.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/553310/header.jpg?t=1699872274', 0, 0, NULL);
INSERT INTO games VALUES (44104, 553420, 'TUNIC', 'Explore a land filled with lost legends, ancient powers, and ferocious monsters in TUNIC, an isometric action game about a small fox on a big adventure.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/553420/header.jpg?t=1719583787', 1, 0, NULL);
INSERT INTO games VALUES (44109, 553480, 'The Pirate''s Fate', 'Embark on a swashbuckling adventure in The Pirate''s Fate, a visual novel experience with a unique twist: the story, the crew, and who you are transform based on your choices. Seek treasure, find love, and choose your fate.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/553480/header.jpg?t=1572320597', 0, 0, NULL);
INSERT INTO games VALUES (44112, 553540, 'Phantom Brigade', 'Phantom Brigade is a hybrid turn-based &amp; real-time tactical RPG with an innovative timeline-based command system. See the future, predict enemy actions, and plot your counterattack on the timeline! Outnumbered and out-gunned, lead the Brigade''s campaign to retake their war-torn homeland.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/553540/header.jpg?t=1738282266', 1, 0, NULL);
INSERT INTO games VALUES (44117, 553640, 'ICEY', 'ICEY is a 2D side-scrolling action game and a META game in disguise. As you follow the narrator''s omnipresent voice, you will see through ICEY''s eyes and learn the truth about her world. The narrator will constantly urge you in one direction, but you must ask, &quot;Why? Why am I following his directions?“ Obey? Rebel?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/553640/header.jpg?t=1726730514', 0, 0, NULL);
INSERT INTO games VALUES (44120, 553760, 'Einlanzer', 'Einlanzer is a full-scale, epic fantasy role-playing game. The 40+ hour story of Einlanzer is deep, thought-provoking, and emotional, while remaining light-hearted and fun at times. Expect a strategic battle system, massive scope, regularly added content, and difficult moral decisions.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/553760/header.jpg?t=1727114725', 0, 0, NULL);
INSERT INTO games VALUES (137671, 553850, 'HELLDIVERS™ 2', 'The Galaxy’s Last Line of Offence. Enlist in the Helldivers and join the fight for freedom across a hostile galaxy in a fast, frantic, and ferocious third-person shooter.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/553850/6a629d747768128d768a7e05a042adeb558d1f85/header.jpg?t=1748015354', 1, 0, NULL);
INSERT INTO games VALUES (44093, 554310, 'Rage Wars', 'Get prepared for the FIRST EVER shooter game based on Rage Comics ! Rage Wars is a well-made action game with a variety of weapons, worlds and enemies to challenge with.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/554310/header.jpg?t=1479454168', 0, 0, NULL);
INSERT INTO games VALUES (44072, 554600, 'Learn Japanese To Survive! Katakana War', 'Learn the basics of Japanese in this interactive role-playing game! No experience needed – start reading and writing in Japanese!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/554600/header.jpg?t=1696493693', 0, 0, NULL);
INSERT INTO games VALUES (44074, 554620, 'Life is Strange: Before the Storm', 'Life is Strange: Before the Storm is a new three part standalone story adventure set three years before the events of the first game. This time play as Chloe Price, a rebel who forms an unlikely friendship with Rachel Amber in a dramatic new story in the BAFTA award winning franchise.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/554620/header.jpg?t=1728636264', 0, 0, NULL);
INSERT INTO games VALUES (44082, 554750, 'Axis Football 2017', 'Axis Football is an American football simulation featuring massive customization and a complete franchise mode', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/554750/header.jpg?t=1512054595', 0, 0, NULL);
INSERT INTO games VALUES (44051, 555000, 'GOAT OF DUTY', 'Goat of Duty is a fast-paced multiplayer shooter where goats armed to the horns bleat face to face in a relentless deathmatch. Ram and troll your friends, own the craziest goatstumes, and put your skills to the test in the quirkiest FPS ever. Are you ready to become the GOAT of goats?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/555000/header.jpg?t=1654793603', 0, 0, NULL);
INSERT INTO games VALUES (44054, 555050, 'Racket Fury: Table Tennis VR', 'Face 16 opponents in 4 distinctive cups and step into the most intense table tennis experience! Take on challenging rivals in the singleplayer campaign to climb the ladder of the Crown Galaxy! Get involved in heated exchanges with players from all over the world who, just like you, are hungry to win', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/555050/header.jpg?t=1685174237', 0, 0, NULL);
INSERT INTO games VALUES (44059, 555150, 'The First Tree', 'A beautiful, 3rd-person exploration game centered around two parallel stories: a fox trying to find her missing family, and a son reconnecting with his estranged father in Alaska. Uncover artifacts from the son''s life as he becomes intertwined in the fox’s journey towards The First Tree.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/555150/header.jpg?t=1666985580', 1, 0, NULL);
INSERT INTO games VALUES (138183, 555160, 'Pavlov', 'Pavlov vr is a multiplayer shooter in VR with heavy focus on community features. Realistic reloading features and fast paced combat as part of the core experience. Play the #1 most popular VR shooter on PC today.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/555160/header.jpg?t=1740613949', 0, 0, NULL);
INSERT INTO games VALUES (44062, 555210, 'Trick and Treat - Visual Novel', 'Trick &amp; Treat is a Visual Novel that test your instincts by making choices that can get you out from the cursed forest or drive you to death… or maybe just maybe your choices can guide you to something more?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/555210/header.jpg?t=1604630263', 0, 1, NULL);
INSERT INTO games VALUES (44063, 555220, 'Detention', 'Detention is an atmospheric horror game set in 1960s Taiwan under martial law. Incorporated religious elements based in Taiwanese/Chinese culture and mythology, the game provided players with unique graphics and gaming experience.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/555220/header.jpg?t=1574836686', 1, 0, NULL);
INSERT INTO games VALUES (44026, 555290, 'Little Briar Rose', 'Little Briar Rose is a very special, stained glass-styled adventure game inspired by the Sleeping Beauty fairy tale.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/555290/header.jpg?t=1673810467', 0, 0, NULL);
INSERT INTO games VALUES (44030, 555400, 'Collision Course', 'A comet is hurtling toward the planet! Sneak, scavenge and blast your way through an immersive prehistoric world filled with Humans, Dinosaurs, Droids and Mother Nature’s fury!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/555400/header.jpg?t=1667068864', 0, 0, NULL);
INSERT INTO games VALUES (44033, 555510, 'MachiaVillain', 'Machiavillain is an evil mansion management and strategy game, inspired by Dungeon Keeper, Prison Architect and all the horror movie clichés! Build your own manor, raise your monsters, set up your traps, and exterminate your victims. But to gain reputation you''ll have to slay by the horror movie rules!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/555510/header.jpg?t=1572630276', 0, 0, NULL);
INSERT INTO games VALUES (44035, 555570, 'Infestation: The New Z', 'The New Z is a FREE TO PLAY multi-game mode experience. SURVIVE with friends and gather loot, stash and trade. Go into wars against other groups in a massive OPEN WORLD or face them 5 v 5 in COMPETITIVE.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/555570/header.jpg?t=1732531912', 0, 1, NULL);
INSERT INTO games VALUES (44010, 555880, 'Sairento VR', 'VR was made for this. Perform triple jumps, wall runs, power slides and slow time down while blasting away at a foe before landing to deliver a blade attack on another. Kit yourself with katanas, firearms, bows, throwing glaives and legendary relics. Keep upgrading as you play. PURE CYBER NINJA FUN.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/555880/header.jpg?t=1657760694', 1, 0, NULL);
INSERT INTO games VALUES (44014, 555950, 'Danganronpa Another Episode: Ultra Despair Girls', 'Komaru Naegi has been imprisoned inside a mysterious apartment for over a year. Her rescue is derailed when hundreds of Monokumas suddenly attack. She teams up with Toko Fukawa to survive the rampaging Monokumas, escape the crafty Monokuma Kids, and uncover the secrets of the city.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/555950/header.jpg?t=1715701294', 1, 0, NULL);
INSERT INTO games VALUES (44017, 556050, 'Hyper Jam', 'Battle it out local and online in this neon-soaked arena brawler full of lethal weapons, stackable perks, furious combat and a killer synthwave soundtrack.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/556050/header.jpg?t=1667005878', 1, 0, NULL);
INSERT INTO games VALUES (44023, 556180, 'Mysterium: A Psychic Clue Game', 'Mysterium is a cooperative deduction game set in the 1920s in which a ghost guides a group of psychics to uncover a murderer, as well as the weapon and location of the murder, using only visual clues.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/556180/header.jpg?t=1741270717', 0, 0, NULL);
INSERT INTO games VALUES (43999, 556240, 'Disoriented', 'A first-person puzzle game. Simply walk to the door.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/556240/header.jpg?t=1705485861', 0, 0, NULL);
INSERT INTO games VALUES (44005, 556340, 'King Kaiju', 'Live the Dream! Be the Monster! Smash your way through a completely destructible virtual reality city. A simple and silly sandbox game for your inner Kaiju. RRRRRAAAAAAARRRRRRRRRR', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/556340/header.jpg?t=1629897981', 0, 0, NULL);
INSERT INTO games VALUES (43982, 556640, 'Gladius | Gladiator VR Sword fighting', 'Gladius is an immersive VR sword fighting game set in ancient Rome. As a gladiator, you will choose your weapons, train against different enemies, and finally fight for your freedom in an epic battle against the mightiest warriors and mythical creatures of the time. Win the crowd and you will win your freedom.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/556640/header.jpg?t=1736708471', 0, 0, NULL);
INSERT INTO games VALUES (43987, 556740, 'LEGRAND LEGACY: Tale of the Fatebounds', 'Join the Fatebounds as they travel the world of Legrand in a desperate attempt to stop the Mugna Feud, a war of unparalleled savagery, and uncover the sinister forces behind it!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/556740/header.jpg?t=1667205501', 1, 0, NULL);
INSERT INTO games VALUES (43991, 556820, 'Warbands: Bushido', 'Warbands:Bushido is a miniatures board game arena with cards, miniatures, dice and beautiful terrains to fight on, with both multiplayer battles boardgamers are used to, and challenging single-player scenarios.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/556820/header.jpg?t=1612864528', 0, 1, NULL);
INSERT INTO games VALUES (43995, 556860, 'Gladiator School', 'Gladiator School is a Tycoon-style simulation game. You play as the master of a newly formed school for gladiators. Your job is to prepare and train recruits before you send them away to fight for their survival and entertain the crowd in the arena.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/556860/header.jpg?t=1728421430', 0, 0, NULL);
INSERT INTO games VALUES (43961, 557340, 'My Friend Pedro', 'My Friend Pedro is a violent ballet about friendship, imagination, and one man’s struggle to obliterate anyone in his path at the behest of a sentient banana.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/557340/header.jpg?t=1745954928', 1, 0, NULL);
INSERT INTO games VALUES (43962, 557400, 'Midas Gold Plus', 'Discover Midas Gold Plus, an engaging idle clicker set in a mythical world! Harness King Midas'' golden touch, build a legendary city, and unlock powerful champions. Master unique gameplay styles, explore pet battles, and conquer rival cities. Delve into this ancient tycoon adventure today!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/557400/header.jpg?t=1683545403', 0, 1, NULL);
INSERT INTO games VALUES (43963, 557410, 'Dream Quest', 'Play cards! Kill monsters! Level Up! Dream Quest is a roguelike deckbuilding game inspired by the likes of Ascension, Magic: the Gathering, and Shandalar. Explore randomly generated levels as one of 13 classes in short, 30 minute, sessions.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/557410/header.jpg?t=1481264404', 0, 0, NULL);
INSERT INTO games VALUES (43966, 557520, 'Torn', 'Torn is a dark science-fiction mystery. Explore the abandoned mansion of Dr. Lawrence Talbot, an eccentric scientist missing for 64 years. Use the Gravity Tool to activate Talbot’s machines, then transport to the strange dimension known as “The Parallel.”', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/557520/header.jpg?t=1680629664', 1, 0, NULL);
INSERT INTO games VALUES (43969, 557600, 'Gorogoa', 'Gorogoa is an elegant evolution of the puzzle genre, told through a beautifully hand-drawn story designed and illustrated by Jason Roberts. Winner of Debut Game at the 2018 BAFTA Games Awards, as well as Best Mobile Game and the Innovation Award at the GDC 2018 Choice Awards.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/557600/header.jpg?t=1729099787', 1, 0, NULL);
INSERT INTO games VALUES (43970, 557630, 'Hello Charlotte EP2: Requiem Aeternam Deo', 'A eulogy for happiness, and a lament for connection that never was.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/557630/header.jpg?t=1734718895', 1, 1, NULL);
INSERT INTO games VALUES (43936, 557750, 'Giants: Citizen Kabuto', 'Before man climbed down from the trees to shop in megastores and drink cappuccino, before the Earth wadded itself into a ball, there was the Island. A fragment from a long-lost planet. Upon the surface of this paradise wandered Kabuto the giant. Little does he know, it was home to others before him.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/557750/header.jpg?t=1668561686', 0, 0, NULL);
INSERT INTO games VALUES (43954, 558100, 'Art of War: Red Tides', 'Art of War: Red Tides is a fair multiplayer strategy game that allows different teams on the same platform (e.g. smartphones, PC, etc.) to battle against each other. You will encounter players around the world!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/558100/header.jpg?t=1530625372', 0, 1, NULL);
INSERT INTO games VALUES (43925, 558110, 'Odyssey - The Story of Science', 'Odyssey is an enchanting and innovative science adventure game. Help Kai and her family escape their captors on the Wretched Islands - and learn the history of astronomy, mechanics, and scientific reasoning as you read Kai''s journal and solve puzzles along the way!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/558110/header.jpg?t=1527435860', 0, 0, NULL);
INSERT INTO games VALUES (43926, 558260, 'Gravel', 'Gravel is the ultimate off-road experience. The most extreme racing game that will let you try out amazing stunts in the wildest places on the planet!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/558260/header.jpg?t=1728478622', 0, 0, NULL);
INSERT INTO games VALUES (43929, 558420, 'Stories Untold', 'Stories Untold is a compilation tape of four experimental adventures, including a remaster of the original hit episode “The House Abandon”.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/558420/header.jpg?t=1687975548', 0, 0, NULL);
INSERT INTO games VALUES (43931, 558450, 'Fibrillation HD', 'Immerse yourself in an adaptation of an old story about Ewan Berrington.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/558450/header.jpg?t=1723603132', 1, 0, NULL);
INSERT INTO games VALUES (132736, 558990, 'Opus Magnum', 'Opus Magnum is the latest open-ended puzzle game from Zachtronics, the creators of SpaceChem, Infinifactory, and SHENZHEN I/O. Design and build machines that assemble potions, poisons, and more using the alchemical engineer’s most advanced tool: the transmutation engine!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/558990/header.jpg?t=1667070364', 1, 0, NULL);
INSERT INTO games VALUES (43907, 559100, 'Phantom Doctrine', 'The year is 1983. The world teeters on the verge of destruction as the Cold War tightens its icy grip. East or West: trust no one, question everything. The fate of humanity rests in your hands as you pit spy versus spy in tactical Phantom Doctrine.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/559100/header.jpg?t=1728639836', 0, 0, NULL);
