INSERT INTO games VALUES (43560, 568750, '甜点恋人 / Pastry Lovers', 'Pastry Lovers is an adventure simulation game that sets in a fantastic Pastry Kingdom. Sakura, the main character, grows into a pastry master and gains romantic love.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/568750/header.jpg?t=1545103424', 0, 0, NULL);
INSERT INTO games VALUES (43537, 569480, 'Kingdoms and Castles', 'Kingdoms and Castles is a city-building simulation game about growing a kingdom from a tiny hamlet to a sprawling city and imposing castle. Make trade agreements, alliance, and war with neighboring AI controlled kingdoms. Each villager and resource is individually simulated.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/569480/6e6352d6778d92aaafc110ca81e77812e0415fb4/header_alt_assets_9.jpg?t=1743536979', 1, 0, NULL);
INSERT INTO games VALUES (43541, 569530, 'Sky Noon', 'Sky Noon is a First-Person Shooter with Brawler mechanics. Players are equipped with a grappling hook, a lasso and an arsenal of weapons and abilities. There is no health in Sky Noon - players eliminate their enemies by pushing and pulling them off the Floating Frontier.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/569530/header.jpg?t=1667240838', 0, 0, NULL);
INSERT INTO games VALUES (43544, 569610, 'Distant Space', 'Distant Space are present the arcade game of cosmic fights in arcade style of the 80''s, this is a game where you can control the spaceship and forced to destroy extraterrestrials, which are moving in the certain order.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/569610/header.jpg?t=1728933575', 1, 0, NULL);
INSERT INTO games VALUES (43520, 569800, 'LEAVES - The Journey', 'Travel to the mystic lands of Mononino and help the Treefruities to recover the lost leaves of their home tree. Search for clues to master the many puzzles and challenges on your journey.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/569800/header.jpg?t=1646934024', 1, 0, NULL);
INSERT INTO games VALUES (43521, 569810, 'LEAVES - The Return', 'Mononino and the Treefruities fared well without you - until another disaster scattered the leaves of their home tree. Once more, take on the journey and challenging puzzles along the way.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/569810/header.jpg?t=1646934476', 1, 0, NULL);
INSERT INTO games VALUES (43522, 569860, 'Thimbleweed Park™', 'In Thimbleweed Park, a dead body is the least of your problems. Switch between five playable characters to uncover the surreal secrets of this strange town in a modern mystery adventure game from the creators of Monkey Island and Maniac Mansion. The deeper you go, the weirder it gets.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/569860/header.jpg?t=1667234024', 0, 0, NULL);
INSERT INTO games VALUES (43527, 569970, 'Chosen 2', 'Chosen 2 is a heroic RPG sequel to Chosen.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/569970/header.jpg?t=1574484110', 0, 0, NULL);
INSERT INTO games VALUES (43528, 570000, 'Old Friend', 'Lose yourself in a vibrant and interactive psychedelic dance party brimming with joyful insanity.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/570000/header.jpg?t=1482429710', 0, 0, NULL);
INSERT INTO games VALUES (43514, 570420, 'X Rebirth VR Edition', 'X Rebirth VR Edition is tailored to be an immersive VR experience, based on X Rebirth: Home of Light. TRADE, FIGHT, BUILD, THINK in the X Universe - the biggest sandbox this side of the galaxy.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/570420/header.jpg?t=1728401171', 1, 0, NULL);
INSERT INTO games VALUES (43516, 570490, 'SHENZHEN SOLITAIRE', 'NO ENGINEERING, ALL PROCRASTINATION! SHENZHEN SOLITAIRE is a brand-new solitaire variant originally developed for SHENZHEN I/O, and is now available as a standalone game! It''s simple but challenging, and oddly addictive.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/570490/header.jpg?t=1618420451', 0, 0, NULL);
INSERT INTO games VALUES (43487, 570780, '古剑奇谭(GuJian)', '《古剑奇谭：琴心剑魄今何在》（《古剑奇谭》）由网元圣唐旗下上海烛龙自主研发，于2010年7月正式发行，是国内首部全程配音的大型3D仙侠类单机角色扮演游戏。 游戏采用架空的历史设定，在其中融入了众多真实的人文地理风貌，通过合适的方式，将这些带有浓郁古韵和中国味的风物呈现在玩家的眼前。', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/570780/header.jpg?t=1726190878', 0, 0, NULL);
INSERT INTO games VALUES (43496, 570940, 'DARK SOULS™: REMASTERED', 'Then, there was fire. Re-experience the critically acclaimed, genre-defining game that started it all. Beautifully remastered, return to Lordran in stunning high-definition detail running at 60fps.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/570940/header.jpg?t=1726158603', 1, 0, NULL);
INSERT INTO games VALUES (43497, 570950, 'Devilated', 'Devilated is an ultraviolent RPG old-school shooter where you brutalize and cannibalize your demonic foes in equal measure. Eat their face before they eat yours.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/570950/header.jpg?t=1743744377', 0, 0, NULL);
INSERT INTO games VALUES (43473, 571260, 'THE KING OF FIGHTERS XIV STEAM EDITION', 'THE KING OF FIGHTERS XIV finally hits STEAM! KOF XIV is back with its classic 2D gameplay and &quot;3-on-3 TEAM BATTLE&quot; game system but evolved to 3D! 58 charismatic fighters are about to clash in this new chapter of KOF!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/571260/header.jpg?t=1727160512', 1, 0, NULL);
INSERT INTO games VALUES (43474, 571310, 'SteamWorld Dig 2', 'SteamWorld Dig is back! Dig deep, gain riches and unearth the terrors of the underworld in this platform mining adventure influenced by classic Metroidvania style games.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/571310/header.jpg?t=1726132098', 0, 0, NULL);
INSERT INTO games VALUES (43481, 571530, 'Superdimension Neptune VS Sega Hard Girls', 'A collaboration project between ASCII Media Works’ Dengeki Bunko and SEGA, the Sega Hard Girls are made up of various Sega consoles, including the Dreamcast, Sega Saturn, and Mega Drive! These anthropomorphized consoles are girls with an array of personalities and spunk, and this time they are teaming up with Neptune and IF for an...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/571530/header.jpg?t=1730856582', 0, 0, NULL);
INSERT INTO games VALUES (10677, 571720, 'One Piece: Unlimited World Red - Deluxe Edition', 'A remaster of the latest installment of the “Unlimited” series, with over 50 DLC’s included', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/571720/header.jpg?t=1701324600', 0, 0, NULL);
INSERT INTO games VALUES (10678, 571740, 'Golf It!', 'Embark on an exciting journey with Golf It! Seize your putter, rally your friends, and immerse yourself in an epic minigolf adventure. Conquer countless courses, create lasting memories, and refine your skills to emerge as the ultimate minigolf champion. Your thrilling golfing odyssey begins here!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/571740/header.jpg?t=1707842297', 1, 0, NULL);
INSERT INTO games VALUES (10681, 571880, 'Angels with Scaly Wings™ / 鱗羽の天使', 'You, the player, are an ambassador for Earth sent through a mysterious portal into the world of dragons. Explore a town full of secrets and the people who keep them in this compelling sci-fi visual novel with slice of life and dating sim elements.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/571880/header.jpg?t=1741776098', 0, 0, NULL);
INSERT INTO games VALUES (43469, 571890, 'Shapelab', 'Shapelab is a unique VR 3D modeling application offering an intuitive interface and a variety of powerful polygon mesh-based sculpting tools to create high-quality 3D assets. Add VR to your 3D modeling workflow and experience a new dimension of creativity with Shapelab!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/571890/header.jpg?t=1747301536', 0, 0, NULL);
INSERT INTO games VALUES (10671, 572220, 'MageQuit', 'A wizard brawler about spell drafting and beard envy, MageQuit allows up to 10 mages to battle it out online or locally. Beards grow longer with each kill; the wizard with the longest beard after 9 rounds wins!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/572220/header.jpg?t=1738884731', 0, 0, NULL);
INSERT INTO games VALUES (10653, 572410, 'Steel Division: Normandy 44', 'Steel Division: Normandy is a tactical real-time strategy (RTS) game that pits players against AI enemies in a single-player campaign -- or against several opponents in massive 10-on-10 multiplayer battles.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/572410/header.jpg?t=1747211830', 0, 0, NULL);
INSERT INTO games VALUES (43435, 572430, 'Party Hard 2', 'It''s 3am and you just want to get some sleep. Welcome back to Party Hard! Stop parties using hundreds of new ways, incidentally destroy a drug syndicate, and save the Earth from an alien invasion. May the chickens be with you!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/572430/header.jpg?t=1739397633', 1, 0, NULL);
INSERT INTO games VALUES (10661, 572700, 'Nancy Drew®: Sea of Darkness', 'Set a Course for Danger and Discovery!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/572700/header.jpg?t=1734463423', 0, 0, NULL);
INSERT INTO games VALUES (10664, 572730, 'Nancy Drew®: The Silent Spy', 'Defuse a Toxic Plot and Reveal the Truth Behind Kate Drew’s Death!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/572730/header.jpg?t=1734468268', 0, 0, NULL);
INSERT INTO games VALUES (10665, 572740, 'Nancy Drew®: The Secret of Shadow Ranch', 'Take a Wild Ride into Terror and Trickery to Rein in a Ghostly Secret!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/572740/header.jpg?t=1734467808', 0, 0, NULL);
INSERT INTO games VALUES (10651, 572890, 'Pikuniku', 'Pikuniku is an absurdly wonderful puzzle-exploration game that takes place in a strange but playful world where not everything is as happy as it seems. Help peculiar characters overcome struggles, uncover a deep state conspiracy, and start a little revolution in this delightful dystopian adventure!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/572890/header.jpg?t=1719983069', 1, 0, NULL);
INSERT INTO games VALUES (10630, 573060, 'LOGistICAL', 'LOGistICAL is a strategy puzzle game where you transport different cargoes to complete all the towns throughout the country. The whole game is a huge puzzle while each town is its own little piece of puzzling. Plenty of towns are easy enough. LOGistICAL covers all of Australia.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/573060/header.jpg?t=1589237392', 0, 0, NULL);
INSERT INTO games VALUES (10633, 573090, 'Stormworks: Build and Rescue', 'Join a world where you design, create and pilot your own air sea rescue service. Release your inner hero as you battle fierce storms out at sea to rescue those in need.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/573090/f0c0d1b4b5bb814ec3a27e8295e7b40a70590755/header_alt_assets_11.jpg?t=1743064727', 0, 0, NULL);
INSERT INTO games VALUES (10634, 573100, 'Battlefleet Gothic: Armada 2', 'Battlefleet Gothic: Armada 2 is the new real-time strategy game adapted from Games Workshop’s famous tabletop game that portrays the epic space battles of the Warhammer 40,000 universe.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/573100/header.jpg?t=1734021141', 0, 0, NULL);
INSERT INTO games VALUES (10636, 573120, 'Dead In Vinland', 'DEAD IN VINLAND is a survival/management game, mixed with RPG and adventure elements, about a Viking family trying their best to survive on a mysterious island.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/573120/header.jpg?t=1737635313', 0, 0, NULL);
INSERT INTO games VALUES (10637, 573130, 'Aporia: Beyond The Valley', 'CRYNEGINE Indie Game of 2017. Featuring an incredibly detailed ancient world and a breathtaking soundtrack, Aporia: Beyond the Valley takes open world storytelling to new heights of adventure.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/573130/header.jpg?t=1747579359', 0, 0, NULL);
INSERT INTO games VALUES (10638, 573170, 'Fidel Dungeon Rescue', 'A critically acclaimed roguelite where you can REWIND to find the optimal path through monsters, treasure and secrets. Quick to play. No grinding. No filler. Deep gameplay.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/573170/header.jpg?t=1607725858', 0, 0, NULL);
INSERT INTO games VALUES (10644, 573320, 'Underhero', 'Underhero is an RPG-platformer where the chosen hero has failed, and an underling of the evil king takes his place as the new hero. Use timing-based combat to defeat enemies as you venture across the land, face off against quirky bosses, and save the kingdom from your own evil boss, Mr Stitches!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/573320/header.jpg?t=1727275124', 0, 0, NULL);
INSERT INTO games VALUES (43388, 573410, 'AI War 2', 'The most devious and acclaimed artificial intelligence in strategy gaming is better than ever. A grand strategy/RTS hybrid that reverses many conventions of both genres. Take territory without attracting attention, build your empire with care, and adapt to an ever-evolving galactic battleground.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/573410/header.jpg?t=1741478882', 0, 0, NULL);
INSERT INTO games VALUES (10650, 573490, 'Interstellar Transport Company', 'Build a galactic transportation empire and supply humanity with everything it needs to colonize the stars. In this sci-fi logistics simulator, grow your company from a local transport agency into an interstellar logistics behemoth! Singleplayer, vs AI, and online multiplayer.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/573490/header.jpg?t=1567967692', 1, 0, NULL);
INSERT INTO games VALUES (10590, 574030, 'Score a goal (Physical football)', 'It''s a physical game, whose main task is to score the ball into the goal. On your side and against you, only the laws of physics. All the controls in the game by using the computer mouse. Depending on the level will be various conditions of interaction of the player with the surrounding world.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/574030/header.jpg?t=1671307380', 1, 0, NULL);
INSERT INTO games VALUES (10592, 574050, 'DRAGON QUEST HEROES™ II', 'DRAGON QUEST HEROES II is a hack-and-slash Action RPG that sends you on a new adventure to restore order to a once peaceful world filled with monsters and battles of epic proportions. Up to 4 players can play in cooperative multiplayer to defeat an unknown threat looming over the Seven Realms!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/574050/header.jpg?t=1727790087', 1, 0, NULL);
INSERT INTO games VALUES (10594, 574080, 'Fog of War', 'Tactical Multiplayer FPS shooter with a story based on the events of the World War II. Strategic battles with a variety of vehicles, including artillery. Multiple game modes. Ranks, titles, awards, career.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/574080/header.jpg?t=1709368260', 0, 0, NULL);
INSERT INTO games VALUES (10595, 574090, 'MOTHERGUNSHIP', 'MOTHERGUNSHIP is a bullet-hell FPS where you craft your own guns, fight gigantic bosses, and defeat a robotic alien armada that conquered Earth. Face off against overwhelming odds in brutal, non-stop combats where thinking on your feet is the only way to survive.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/574090/header.jpg?t=1712009893', 0, 0, NULL);
INSERT INTO games VALUES (10601, 574180, 'Rem Survival', 'Tackle starvation, dehydration, thermal conditions, radiation poisoning, and toxic gas inhalation while trying to keep your sanity intact. Shack up, cook some chicken, and make friends or enemies as you discover, explore, learn, build, and develop your skills needed for a true survival experience.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/574180/header.jpg?t=1744848621', 0, 0, NULL);
INSERT INTO games VALUES (10607, 574310, 'The Mooseman', 'You are the Mooseman and you have the ability to see all that is hidden to the mortal eye. You are about to visit three layers of this universe - the first one is the Lower World where dead reside…', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/574310/header.jpg?t=1746280820', 0, 0, NULL);
INSERT INTO games VALUES (10580, 574560, 'Dude, Stop', '&quot;So, I made a game, right? I filled it with harmless funny puzzles, narrated it a little bit, and then players started making fun of it! They broke the game, ignored my rules! They... they... laughed at me! As if it was some kind of a joke! Why do they have to be so mean?!&quot; - developer of Dude, Stop', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/574560/header.jpg?t=1709822542', 0, 0, NULL);
INSERT INTO games VALUES (10586, 574720, 'Little Big Workshop', 'Manage your workers, stations, machines and create awesome stuff as your little big workshop grows into your dream factory!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/574720/header.jpg?t=1741702987', 1, 0, NULL);
INSERT INTO games VALUES (10588, 574760, 'Starship Theory', 'Starship Theory is a ship building survival game. Mine and trade to gather resources. Plan and construct new upgrades. Train and manage crew. Fight to survive.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/574760/header.jpg?t=1617034710', 0, 1, NULL);
INSERT INTO games VALUES (10558, 574820, 'Cat or Bread?', 'A game about cat and bread.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/574820/header.jpg?t=1494284266', 0, 0, NULL);
INSERT INTO games VALUES (10563, 574980, 'Them''s Fightin'' Herds', 'Them’s Fightin’ Herds is a 2D fighting game featuring a cast of adorable animals designed by acclaimed cartoon producer Lauren Faust. Beneath the cute and cuddly surface, a serious fighter awaits!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/574980/header.jpg?t=1725487544', 1, 0, NULL);
INSERT INTO games VALUES (10540, 575330, 'Oh...Sir! The Hollywood Roast', 'The boys are back , and they look better than ever! Oh…Sir! The Hollywood roast is a brand new spinoff to the surprise indie hit 0f 2016, Oh…Sir!! The Insult Simulator. This time around we’re taking tinsel town down a few notches, whilst classing up the joint.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/575330/header.jpg?t=1721130549', 0, 0, NULL);
INSERT INTO games VALUES (10547, 575480, 'WAGAMAMA HIGH SPEC', 'Narumi Kouki, our hapless protagonist, writes a risque romcom for a weekly manga magazine. Due to its content, he''s kept it a secret from everyone except the two closest to him: Mihiro and Toa.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/575480/header.jpg?t=1726606399', 0, 0, NULL);
INSERT INTO games VALUES (10557, 575640, 'Zup! 3', 'Minimal physical puzzle with explosions', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/575640/header.jpg?t=1674746592', 1, 0, NULL);
INSERT INTO games VALUES (10504, 575650, 'Lily''s Day Off', 'Lily''s Day Off is a visual novel, but not in the typical sense. As you progress in this game, your actions drastically change characters, story lines, and outcomes.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/575650/header.jpg?t=1741091387', 0, 0, NULL);
INSERT INTO games VALUES (10517, 575820, 'I Hate Running Backwards', 'I Hate Running Backwards is a never-ending adrenaline packed shoot''em down roguelite that puts the emphasis on destruction and fighting never ending waves of enemies while time traveling through procedurally generated worlds!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/575820/header.jpg?t=1681755358', 0, 0, NULL);
INSERT INTO games VALUES (10527, 575950, 'Blood Feed', 'Blood Feed - The Mystery of Insectville is FPS depthless and mindless shooter, where you, smashing through the waves of bugs, insects and hordes of most disgusting things that ever roamed the earth, need to unravel the mysterious dissapearance of the whole town, including your family.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/575950/header.jpg?t=1747501200', 0, 0, NULL);
INSERT INTO games VALUES (10532, 576030, 'MHRD', 'MHRD is a hardware design game, in which you design various hardware circuits in a hardware description language. The hardware circuits you design get more complex as you go until you create a fully functional CPU design.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/576030/header.jpg?t=1707994633', 0, 0, NULL);
INSERT INTO games VALUES (10489, 576260, 'Winds Of Trade', 'Winds Of Trade is a strategy game about running an ocean trading company in the 18th and 19th centuries. Building your trading empire will not be your only goal! Ruthless pirates, shady smugglers, wartime and fierce competitors will make the way to the top a long and hard road for you!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/576260/header.jpg?t=1713425955', 0, 0, NULL);
INSERT INTO games VALUES (10492, 576310, 'Oracle', 'ORACLE is a single player, open world experience with dozens of locations to explore, great soundtrack and an awesome story ready to be unraveled.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/576310/header.jpg?t=1488499549', 0, 0, NULL);
INSERT INTO games VALUES (10475, 576770, 'Low Magic Age', 'Adventure and fight in a medieval fantasy open world! Build heroic characters with various abilities, travel through villages, cities, or perilous dungeons. Strategic turn-based combat system and advanced character building - Fog of war, charging and flanking, and more in the fast-paced Arena mode.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/576770/header.jpg?t=1748397422', 0, 0, NULL);
INSERT INTO games VALUES (43230, 577080, 'A Dump in the Dark', 'Your cheeks will quiver in fear, as ghastly ghouls accost your rear. You will gape in horror, as you face the dark. Only your rump can guide you through.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/577080/header.jpg?t=1657655247', 0, 0, NULL);
INSERT INTO games VALUES (129107, 577230, 'Three Kingdoms The Last Warlord', 'The Last Warlord is a Turn-based strategy game. The game is based on the famous Chinese historical novel. The Three Kingdoms (A.D. 190 – 280) was the tripartite division of China between the states of Wei, Shu, and Wu.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/577230/header.jpg?t=1744784076', 1, 0, NULL);
INSERT INTO games VALUES (10442, 577410, 'The Pit: Infinity', 'Enter a legendary alien facility dug deep into the Feldspar Mountains... a massive Pit, built by the ancient Suul''ka. Enter The Pit again for the first time, in this unique Roguelike / FPS hybrid!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/577410/header.jpg?t=1667939361', 0, 0, NULL);
INSERT INTO games VALUES (10444, 577460, 'Zoop! - Hunter''s Grimm', 'For Sarai and Nicholas, life is simple: search for monsters, kill the monsters, get the reward, and get frosty chocolate milkshakes.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/577460/header.jpg?t=1574483870', 0, 0, NULL);
INSERT INTO games VALUES (10446, 577480, 'Higurashi When They Cry Hou - Ch. 5 Meakashi', 'Higurashi When They Cry is a sound novel. The music, backgrounds and characters work together to create a world that is the stage of a novel for the user to read. They laugh and cry and get angry. The user takes the point of view of the protagonist to experience the story.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/577480/header.jpg?t=1725522897', 0, 0, NULL);
INSERT INTO games VALUES (10448, 577530, 'Pixel Ripped 1989', 'Pixel Ripped 1989 is a wacky multi-dimensional homage to the early days of gaming. The player embarks on a journey into the screen of a classic videogame and beyond.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/577530/fe168e446437e3baf9437ac6d9dac4c84b891c47/header.jpg?t=1749226700', 0, 0, NULL);
INSERT INTO games VALUES (10426, 577670, 'Demolish & Build 2018', 'Your company is going global. Use big machines to demolish huge buildings or go close and personal and use your hammer. Buy land properties, upgrade your machines and hire workers in different parts of the world.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/577670/header.jpg?t=1726148393', 0, 0, NULL);
INSERT INTO games VALUES (10427, 577690, 'Spooky''s Jump Scare Mansion: HD Renovation', 'Can you survive 1000 rooms of cute terror? Or will you break once the cuteness starts to fade off and you''re running for your life from the unspeakable hideous beings that shake and writhe in bowels of this house? They wait for you, they wait and hunger for meeting you.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/577690/header.jpg?t=1663381711', 0, 0, NULL);
INSERT INTO games VALUES (10429, 577730, 'Idle Evolution', 'A game combination of genres time-manager / strategy / educational. Simple and addictive whose currency are the atoms and the goal is to have their control and reach the final evolution. God created the world in 6 days... and you?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/577730/header.jpg?t=1746372335', 1, 0, NULL);
INSERT INTO games VALUES (10435, 577940, 'Killer Instinct', 'The legendary fighting franchise is back with over-the-top action, a wild cast of combatants, rocking reactive music, and C-C-C-COMBO BREAKERS!!! Choose your ultimate combatants each with fluid animations, unique combat tactics, and enthralling special attacks.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/577940/header.jpg?t=1721325025', 0, 1, NULL);
INSERT INTO games VALUES (130887, 578080, 'PUBG: BATTLEGROUNDS', 'PUBG: BATTLEGROUNDS, the high-stakes winner-take-all shooter that started the Battle Royale craze, is free-to-play! Drop into diverse maps, loot unique weapons and supplies, and survive in an ever-shrinking zone where every turn could be your last.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/578080/841ea38bc58cabb70aef65365cf50bc2d79329d9/header.jpg?t=1746590920', 1, 1, NULL);
INSERT INTO games VALUES (10415, 578210, 'A-Tech Cybernetic VR', 'Built exclusively for VR, A-Tech Cybernetic''s Story Mode will offer hours of explosive fun, while Swarm Mode will test your grit in a sci-fi nightmare scenario. Stop the mutant invasion at a futuristic megacorp, controlling an arsenal of weapons with real life movements!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/578210/header.jpg?t=1715712836', 0, 0, NULL);
INSERT INTO games VALUES (43186, 578310, 'BRAIN / OUT', 'Brain / Out is a multiplayer shooter with a nostalgic post-Soviet feel. Experience dynamic battles and exterminate your enemies with a large arsenal of modern weaponry. Lock''n''load!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/578310/header.jpg?t=1604127364', 1, 1, NULL);
INSERT INTO games VALUES (43188, 578330, 'LEGO® City Undercover', 'Join the Chase! In LEGO® CITY Undercover, play as Chase McCain, a police officer who''s been tasked with going undercover to hunt down the notorious – and recently escaped – criminal Rex Fury and putting an end to his city-wide crime wave.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/578330/header.jpg?t=1745612336', 0, 0, NULL);
INSERT INTO games VALUES (10423, 578540, 'Perfect Gold - Yuri Visual Novel', 'In this short, coming-of-age yuri visual novel, play as Marion LaRue and Audrey Clary as they explore the magical city of Castlecoast and get a second chance at love and friendship.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/578540/header.jpg?t=1697729684', 0, 0, NULL);
INSERT INTO games VALUES (10393, 578620, 'GORN', 'GORN is a ludicrously violent VR gladiator simulator, made by Free Lives, the developers of Broforce and Genital Jousting.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/578620/header.jpg?t=1740671868', 0, 0, NULL);
INSERT INTO games VALUES (10394, 578650, 'The Outer Worlds', 'The Outer Worlds is an award-winning single-player RPG from Obsidian Entertainment and Private Division. As you explore a space colony, the character you decide to become will determine how this player-driven story unfolds. In the colony''s corporate equation, you are the unplanned variable.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/578650/header.jpg?t=1738037605', 1, 0, NULL);
INSERT INTO games VALUES (10398, 578720, 'A Mortician''s Tale', 'A Mortician''s Tale is a short, story-driven game about a mortician tasked with running a funeral home.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/578720/header.jpg?t=1668540508', 0, 0, NULL);
INSERT INTO games VALUES (10403, 578850, '64.0', '64.0 is a minimal fast-paced arcade game, where you shoot the squares that have the same color as the background.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/578850/header.jpg?t=1691435831', 1, 0, NULL);
INSERT INTO games VALUES (10407, 578900, 'Demonheart', 'Discover the secrets of the witches and demons in this dark fantasy romance game, featuring a female protagonist whose personality is completely up to the player thanks to extensive dialog choices.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/578900/header.jpg?t=1724973813', 0, 0, NULL);
INSERT INTO games VALUES (10409, 578930, 'LOVE 2: kuso', 'kuso is the sequel to LOVE, and is a challenging yet fair platformer with a simple aesthetic. You have the ability to run, jump, and leave your own checkpoint. Make your way through acid, long jumps, disappearing platforms, bouncers, giant saws, and much more in this dreadful mechanical world.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/578930/header.jpg?t=1584755181', 0, 0, NULL);
INSERT INTO games VALUES (10411, 579020, 'Constructor', 'You can’t rise to the top without taking a few others down. If that means engaging in a workplace accidents, dodgy deals, and a shifty trick or two then so be it! You''re going to need every trick in the book if you want to go from small-time slumlord to property tycoon!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/579020/header.jpg?t=1728918773', 0, 0, NULL);
