INSERT INTO games VALUES (10389, 579180, 'Ys VIII: Lacrimosa of DANA', 'Ys returns with a brand new adventure for the first time in 8 years! Adol awakens shipwrecked and stranded on a cursed island. There, he and the other shipwrecked passengers he rescues form a village to challenge fearsome beasts and mysterious ruins on the isolated island.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/579180/header.jpg?t=1732666782', 0, 0, NULL);
INSERT INTO games VALUES (10379, 579760, 'The Journey Down: Chapter Three', 'The final chapter of The Journey Down, a classic point-and-click saga with an Afro-Caribbean vibe. Get ready to embark on an epic journey of brain-teasing adventure!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/579760/header.jpg?t=1680618482', 0, 0, NULL);
INSERT INTO games VALUES (10381, 579820, 'Robinson: The Journey', 'When the Esmeralda crashes on Tyson III, Robin is left stranded. He must rely on his wits – and HIGS, an AI unit from the ship – to survive. As he searches for the lost crew and comes face-to-face with dinosaurs, Robin discovers that Tyson III is not the paradise once promised.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/579820/header.jpg?t=1505808553', 0, 0, NULL);
INSERT INTO games VALUES (10382, 579840, 'Bloody Trapland 2: Curiosity', 'Take on the hard yet fair world of Bloody Trapland. Jump, slide, dash and dodge your way through the many deadly levels. Find secrets, solve puzzles, unlock mysteries and unravel the story. Go at it alone or bring your friends along for a co-op experience like no other. 1-4 players online and/or splitscreen.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/579840/header.jpg?t=1665126851', 0, 0, NULL);
INSERT INTO games VALUES (43136, 579940, 'Race for the Galaxy', 'Explore, Settle, Develop, Trade, Consume, or Produce? Which do you need most? Which of Earth''s former colonies will be most successful at settling the galaxy, now that JumpDrive exists? Who will discover the secrets of the mysteriously vanished Alien Overlords? Your goal: to build the most prosperous and powerful space empire!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/579940/header.jpg?t=1573172455', 0, 0, NULL);
INSERT INTO games VALUES (10369, 579950, 'Marvel''s Guardians of the Galaxy: The Telltale Series', 'From Earth to the Milano to Knowhere and beyond, and set to the beat of awesome music, this five-part episodic series puts you in the rocket-powered boots of Star-Lord in an original Guardians adventure.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/579950/header.jpg?t=1560522214', 0, 0, NULL);
INSERT INTO games VALUES (10372, 580040, 'Formata', 'Lead. Fight. Win.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/580040/header.jpg?t=1584982956', 0, 0, NULL);
INSERT INTO games VALUES (43142, 580170, 'My Lovely Daughter', 'My Lovely Daughter is an alchemist simulator that explores the depth of a father’s grief and how far he will go to resurrect his daughter. Contains dark and disturbing subject matters, might not be suitable for children or those who are easily disturbed.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/580170/header.jpg?t=1726811396', 0, 0, NULL);
