INSERT INTO games VALUES (43129, 580720, 'Carrier Deck', 'Carrier Deck is a fast paced time management game where you play as the Air Boss on board the CVN-76 in the midst of active war.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/580720/header.jpg?t=1737984846', 0, 0, NULL);
