INSERT INTO games VALUES (10181, 585890, 'Sweetest Monster', 'A middle-aged man has an encounter with a cute catgirl in the dead of night - but all is not as it seems.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/585890/header.jpg?t=1728687943', 0, 0, NULL);
INSERT INTO games VALUES (10182, 585900, 'Harvest Moon: Light of Hope Special Edition', 'In celebration of Harvest Moon''s 20th Anniversary comes an all new Harvest Moon title for Steam! Harvest Moon: Light of Hope Special Edition! The game encompasses twenty years of the spirit that have made the franchise what it is today!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/585900/header.jpg?t=1670001474', 0, 0, NULL);
INSERT INTO games VALUES (10183, 585910, 'Wild Guns Reloaded', 'Wild Guns Reloaded is a fast-paced arcade-style shooter, mixing the Wild West with steampunk. Play as Clint, Annie, Doris, or Bullet the dog with his sentry drone. Grab some friends and play together for some four player action!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/585910/header.jpg?t=1714507873', 0, 0, NULL);
INSERT INTO games VALUES (10194, 586140, 'BlazBlue Centralfiction', 'Combining a 2D fighting game with a visual novel, the BlazBlue series continues on with massive fan support! The latest installation, BlazBlue: Centralfiction, serves as the ending to the Azure Saga, revealing the hidden truth of the world!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/586140/header.jpg?t=1653281343', 1, 0, NULL);
INSERT INTO games VALUES (42966, 586200, 'Street Fighter 30th Anniversary Collection', 'Celebrate Street Fighter’s historic legacy with the Street Fighter 30th Anniversary Collection. In this collection of 12 Street Fighter games, four groundbreaking titles let you hop online and relive the arcade experience through the online Arcade Mode or play with friends.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/586200/header.jpg?t=1720492165', 1, 0, NULL);
INSERT INTO games VALUES (10198, 586210, 'OVRdrop', 'OVRdrop is a Utility Application for SteamVR that can mirror a Desktop Window, an entire Monitor, or a WebCam into a Cross Game SteamVR Overlay.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/586210/header.jpg?t=1587297347', 0, 0, NULL);
INSERT INTO games VALUES (10205, 586350, 'UBERMOSH:WRAITH', 'UBERMOSH:WRAITH is the fourth volume of the arcade series UBERMOSH.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/586350/header.jpg?t=1699491375', 1, 0, NULL);
INSERT INTO games VALUES (10175, 586750, 'Sonny', 'Undead. Unstoppable. A challenging, turn-based indie sci-fi RPG that brings the beloved classic into the modern era with all new content and gameplay.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/586750/header.jpg?t=1726581583', 0, 0, NULL);
INSERT INTO games VALUES (10179, 586880, 'Mini Ghost', '&quot;Mini Ghost&quot; is a mini metroidvania in the 80''s MSX art style and gameplay. It''s the mini prequel of Ghost 1.0.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/586880/header.jpg?t=1616400828', 0, 0, NULL);
INSERT INTO games VALUES (10142, 586950, 'The Wizards - Enhanced Edition', 'Become a powerful Wizard and take fate into your own hands! Immerse yourself in a beautiful fantasy world and destroy your enemies by casting spells with hand gestures!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/586950/header.jpg?t=1727958710', 0, 0, NULL);
INSERT INTO games VALUES (10143, 586960, 'Upside Down', 'Upside Down will immerse you in an incredible adventure. Sharpen your reflexes for this fast-paced, precise puzzle-platformer.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/586960/header.jpg?t=1696796863', 0, 0, NULL);
INSERT INTO games VALUES (10146, 587000, 'First Strike', 'FIRST STRIKE is a fast paced real time strategy game where you play one of the twelve biggest nuclear superpowers of the world – from known superpowers like the USA to an upstart hellraiser like North Korea – and try to be the last one remaining when the whole world blows to smithereens.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/587000/header.jpg?t=1732268051', 1, 0, NULL);
INSERT INTO games VALUES (10149, 587100, 'Ys SEVEN', 'Experience the first “modern-era” Ys game, now off the small screen for its worldwide PC debut! Features a full party system, dozens of unique combat skills, and a massive overworld to explore. Uncover the secret of the Five Great Dragons, and help Adol Christin save the day once again!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/587100/header.jpg?t=1732151647', 0, 0, NULL);
INSERT INTO games VALUES (10150, 587110, 'Ys: Memories of Celceta', 'World-famous red-haired adventurer Adol Christin awakens in the unfamiliar land of Celceta, remembering nothing more than his name. Join Adol and his new friends as he embarks on an adventure to map the wilderness and reclaim his memories in this beloved action RPG from Nihon Falcom.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/587110/header.jpg?t=1731453459', 0, 0, NULL);
INSERT INTO games VALUES (10153, 587220, 'Jet Island', 'Slide anywhere on your hoverboard at extreme speeds! Explore the massive open world of Jet Island! Learn to skate on any surface, swing from tall buildings, fly in ways you never knew were possible! Defeat the 4 giant boss fights! Get ready to experience complete freedom in VR!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/587220/header.jpg?t=1593104730', 0, 0, NULL);
INSERT INTO games VALUES (10154, 587260, 'Tokyo Xanadu eX+', 'Tokyo Xanadu eX+; a massive action RPG from the masters of the genre, Nihon Falcom! When high school student Kou Tokisaka encounters the nightmare realm known as the Eclipse, his world is forever changed.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/587260/header.jpg?t=1518095072', 0, 0, NULL);
INSERT INTO games VALUES (10123, 587420, 'Cart Racer', 'Get a new gaming experience as a racer in a shopping cart! Play for the brutal and steep Cart Racer. Overcome obstacles in the city, in the sea, in the ancient castle and the snowy mountains!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/587420/header.jpg?t=1649158763', 0, 0, NULL);
INSERT INTO games VALUES (10124, 587430, 'I Expect You To Die', 'Test your problem-solving skills in this virtual reality escape-the-room puzzle game. Play as a secret agent armed with telekinetic abilities on a mission to stop Zoraxis, an evil corporation with plans for world domination.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/587430/header.jpg?t=1725025973', 1, 0, NULL);
INSERT INTO games VALUES (10126, 587450, 'Saurian', 'Saurian is a survival-simulation experience about living the life of a dinosaur. Starting from the egg, you must survive to adulthood amidst the perilous Hell Creek ecosystem of 66 million years ago, meticulously reconstructed with the help of professional paleontologists.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/587450/header.jpg?t=1602287862', 0, 0, NULL);
INSERT INTO games VALUES (10128, 587470, 'Chroma Lab', 'Chroma Lab is a VR particle physics sandbox. Surround yourself with hundreds of thousands of colorful particles that stick together like a fluid which you can interact with using a variety of tools.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/587470/header.jpg?t=1511812703', 0, 0, NULL);
INSERT INTO games VALUES (10131, 587520, 'Dungeons of Sundaria', 'Adventure through epic dungeons facing fearsome creatures either solo or with a group of friends. Master your class, loot everything, and destroy the foul creatures of the deep! Will you become a hero of legend?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/587520/header.jpg?t=1703180854', 0, 0, NULL);
INSERT INTO games VALUES (10133, 587580, 'Nature Treks VR', 'Latest Update: Animal Kingdom. Explore tropical beaches, underwater oceans and even take to the stars. Discover over 60 different animals. Command the weather, take control of the night or create and shape your own world. Relax and immerse yourself into the Nature Treks VR experience.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/587580/header.jpg?t=1668000120', 0, 0, NULL);
INSERT INTO games VALUES (137699, 588030, 'Derail Valley', 'Drive massive trains and build your career in a vast open railway network. For both PC and VR.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/588030/header.jpg?t=1747663360', 0, 0, NULL);
INSERT INTO games VALUES (10110, 588040, 'WILL: A Wonderful World / WILL：美好世界', 'Become a god and help change the fate of people, even the world! In WILL: A Wonderful World, you will receive letters written by characters living in urban cities. By rearranging the order and combinations of sentences in these letters, you are going to alter the destiny of whomever that wrote them.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/588040/header.jpg?t=1727165269', 0, 0, NULL);
INSERT INTO games VALUES (10113, 588110, 'One Dog Story', 'One Dog Story is an engaging pixel adventure game with RPG elements, gameplay that’ll get you hooked for hours, and well-developed characters. You wake up in an underground laboratory, free again after a horrific accident. Prepare to explore this expansive game world and its many secrets and mysteries.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/588110/header.jpg?t=1587995456', 1, 0, NULL);
INSERT INTO games VALUES (10116, 588160, 'Pizza Connection 3', 'Mamma mia... Long awaited by fans around the world, the new installment of the cult series &quot;Pizza Connection&quot; returns to the PC with even more flavour and extra cheese. Make ''em a pizza they can''t refuse!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/588160/header.jpg?t=1573225375', 0, 0, NULL);
INSERT INTO games VALUES (10117, 588190, 'Tower!3D Pro', 'Tower!3D Pro will put you in the position of an airport tower controller, one of the most stressful job on the world!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/588190/header.jpg?t=1631486945', 0, 0, NULL);
INSERT INTO games VALUES (10102, 588690, 'Peace, Death!', 'Peace, Death! is an arcade simulator with difficulties. In this game you play as the Reaper working for your boss, Death, and send clients to Heaven, Hell, or Purgatory.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/588690/header.jpg?t=1712565789', 1, 0, NULL);
INSERT INTO games VALUES (10104, 588730, 'Majotori', 'How many lives will your ignorance ruin?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/588730/header.jpg?t=1726860776', 0, 0, NULL);
INSERT INTO games VALUES (10077, 588950, 'Kingsway', 'Kingsway is the #1 operating system for daily tasks such as skeleton smashing and loot-organizing. Trouble sorting through all your potions and swords? Don''t worry! Kingsway can help you manage, and with an easy to use interface you''ll have time leftover for a peaceful stroll through the underworld.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/588950/header.jpg?t=1734680274', 0, 0, NULL);
INSERT INTO games VALUES (10078, 588970, 'Oik', 'Casual physics puzzle', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/588970/header.jpg?t=1572196200', 1, 0, NULL);
INSERT INTO games VALUES (10089, 589200, 'Dreadhalls', 'You are trapped deep inside a massive dungeon. Explore it, survive it and find a way to escape. Your only weapons will be stealth, your own courage, and a faint light. Dreadhalls is an intense and scary experience, not for the faint of heart. You have been warned!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/589200/header.jpg?t=1726477398', 1, 0, NULL);
INSERT INTO games VALUES (129637, 589290, 'Holdfast: Nations At War', 'Fight on multiple fronts in Holdfast: Nations At War - A multiplayer first and third-person shooter set during the great Napoleonic Era and WW1. Charge into battle with over 150 players per server!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/589290/9ed0c9a2b2db1ec48352d824329275468d2b8b0e/header.jpg?t=1745594510', 1, 0, NULL);
INSERT INTO games VALUES (10055, 589360, 'Ni no Kuni™ II: Revenant Kingdom', 'Join the young king Evan as he sets out on an epic quest to found a new kingdom and, with the help of some new friends, unite his world, saving its people from a terrible evil.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/589360/header.jpg?t=1718968277', 0, 0, NULL);
INSERT INTO games VALUES (10063, 589500, 'Shovel Knight: Shovel of Hope', 'Shovel Knight is a sweeping classic action-adventure game with awesome gameplay, memorable characters, and an 8-bit retro aesthetic. If you love games with perfect platforming, beautiful art, infectious music, lovable bosses, humor and levity, and real heart… Shovel Knight is for you!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/589500/header.jpg?t=1701228316', 1, 0, NULL);
INSERT INTO games VALUES (10064, 589510, 'Shovel Knight: Specter of Torment', 'Take control of Specter Knight, servant to the Enchantress, in a quest to recruit a cadre of knights and create the Order of No Quarter. Experience perfect platforming, world-class visuals, impeccable stage design, incredible music, and even meet a friend or two in Shovel Knight: Specter of Torment!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/589510/header.jpg?t=1701228346', 1, 0, NULL);
INSERT INTO games VALUES (10065, 589530, 'Hakuoki: Kyoto Winds', 'Romance 12 handsome warriors and the samurai of the Shinsengumi, uncover their dark secrets, and conquer your demons in this historical fantasy visual novel! Your narrative choices unlock multiple branching storylines and 30 different endings!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/589530/header.jpg?t=1730839650', 0, 0, NULL);
INSERT INTO games VALUES (10066, 589590, 'Kindergarten', 'Welcome to Kindergarten! Have fun trying to learn and share...and not die. That''s important too. In a school that''s just not quite right, it''s important to be friendly...and take out those that aren''t.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/589590/header.jpg?t=1713346624', 0, 0, NULL);
INSERT INTO games VALUES (10043, 589760, 'Revhead', 'Revhead is a car racing simulation game, where you have to build your own race car. You start your journey somewhere in a small village in Australia. You have to think as a real Revhead! You can buy or sell cars and components, fix and tweak your car to make it the fastest around.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/589760/header.jpg?t=1737982676', 0, 0, NULL);
INSERT INTO games VALUES (10045, 589780, 'The Red Strings Club', 'The Red Strings Club is a cyberpunk narrative experience about fate and happiness featuring the extensive use of pottery, bartending and impersonating people on the phone to take down a corporate conspiracy.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/589780/header.jpg?t=1728690203', 0, 0, NULL);
INSERT INTO games VALUES (10047, 589860, 'SoulSet', 'SoulSet is a mystery/romance visual novel, in which you can try to avoid death and pursue a relationship with both male and female characters. You play as Mariko, who finds herself trapped in an eerie mansion with five other people who claim to have no recollection of their past. Who will you trust?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/589860/header.jpg?t=1733518795', 0, 0, NULL);
INSERT INTO games VALUES (10049, 589940, 'Eye of the Temple', 'Embark on a VR adventure to explore a vast and treacherous temple and uncover the ancient legend of the Eye. Keep your balance as you step between moving blocks, dodging hazardous traps and solving environmental puzzles with just your torch and whip in hand.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/589940/header.jpg?t=1745445273', 1, 0, NULL);
INSERT INTO games VALUES (10042, 590380, 'Into the Breach', 'Control powerful mechs from the future to defeat an alien threat. Each attempt to save the world presents a new randomly generated challenge in this turn-based strategy game.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/590380/header.jpg?t=1748969437', 1, 0, NULL);
INSERT INTO games VALUES (10024, 590590, 'Remnants of Naezith', 'With the powers granted to him by the dragon, Kayra will destroy the Remnants of Naezith, enchanted fragments of the dragon''s body, to prevent anyone from exploiting their power for evil. Rush and swing through levels to top the leaderboards in this fast-paced, grappling hook precision platformer.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/590590/header.jpg?t=1726653354', 1, 0, NULL);
INSERT INTO games VALUES (10029, 590690, 'Sprint Vector', 'Welcome to Sprint Vector Championship Intergalactica, where the physical thrill of extreme sports meets the unhinged energy of a zany game show! Run, jump, climb, drift, and fly at extreme velocity as you race up to 8 players and battle obstacles in this frenetic VR adrenaline platformer!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/590690/header.jpg?t=1565043590', 0, 0, NULL);
INSERT INTO games VALUES (10003, 591370, 'Production Line : Car factory simulation', 'Production line is the new car factory management/simulation/tycoon game that pushes your organisational and entrepreneurship skills to the limit. Can you build the ultimate optimised, free-flowing car production line whilst beating the competition and still turn a profit?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/591370/header.jpg?t=1667143467', 0, 0, NULL);
INSERT INTO games VALUES (10004, 591380, 'Bomb Squad Academy', 'Save the world one wire at a time with Bomb Squad Academy, a puzzle game where you have to defuse bombs under a time constraint.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/591380/header.jpg?t=1546009501', 0, 0, NULL);
INSERT INTO games VALUES (10006, 591420, 'Zup! 4', 'Minimal physical puzzle with explosions', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/591420/header.jpg?t=1674746703', 1, 0, NULL);
INSERT INTO games VALUES (10007, 591460, 'Parkasaurus', 'Parkasaurus is a dinosaur tycoon management simulation where you take care of your dinosaurs by constructing well-designed exhibits, researching specialized technologies, and maximizing profits to expand into the ultimate dinosaur theme park. Do you favor development for guests or your dinosaurs?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/591460/header.jpg?t=1746109399', 1, 0, NULL);
INSERT INTO games VALUES (9990, 591630, 'Candleman: The Complete Journey', 'Despite only being able to burn for 10 seconds, a little candle journeys into the darkness, with the purpose of seeking light.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/591630/header.jpg?t=1703139699', 1, 0, NULL);
INSERT INTO games VALUES (9997, 591790, 'BREACH IT', '&quot;BREACH IT&quot; is tactical multiplayer attack - defend type shooter. As an attacker destroy walls, doors with C4, hammers or tons of bullets to get to the enemy from an angle they would not expect. If you''re on defending team, then it''s time to get to work! Board doors, reinforce walls and get to position!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/591790/header.jpg?t=1733347956', 0, 0, NULL);
INSERT INTO games VALUES (9975, 592030, 'Just In Time Incorporated', 'Become a death prevention insurance agent at Just In Time Incorporated and grab bullets, grenades, or even a fire extinguisher to save your clients from gruesome death. With the power of hyper-glove technology, time slows down but you won’t have to!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/592030/header.jpg?t=1639066042', 0, 0, NULL);
INSERT INTO games VALUES (9983, 592260, 'Dungeon Painter Studio', 'Dungeon Painter Studio is a powerful encounter map design tool, with a lot of features: Layers and groups Easy import of custom art Easy export to roll20, FG, TS, and other VTT All objects are editable Filters (Drop Shadow, Glow, Bevel, Tint...) One click D20 random generator dungeons import Export to multipage pdf for print 1 inch, 1.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/592260/header.jpg?t=1559739837', 0, 0, NULL);
INSERT INTO games VALUES (9963, 592480, 'Knights And Bikes', 'Saddle up for a bike-riding, frisbee-throwing, goose-petting, friendship-building, treasure-hunting, story-driven adventure for 1 or 2 players!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/592480/header.jpg?t=1660812592', 0, 0, NULL);
INSERT INTO games VALUES (9967, 592580, 'PRO EVOLUTION SOCCER 2018', '''Where Legends Are Made'' encapsulates the return of PES, with an unparalleled gameplay experience.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/592580/header.jpg?t=1543425596', 1, 0, NULL);
INSERT INTO games VALUES (9957, 593030, 'Strategic Command WWII: War in Europe', 'Strategic Command WWII: War in Europe is a deeply immersive turn based strategy game covering the greatest conflict in modern history!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/593030/header.jpg?t=1721036117', 0, 0, NULL);
INSERT INTO games VALUES (9943, 593150, 'Ooblets', 'Ooblets is a relaxing and offbeat farming, town life, and creature collection game. Manage your farm, grow and train your ooblets, explore strange lands, and have dance-offs!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/593150/header.jpg?t=1696517972', 0, 0, NULL);
INSERT INTO games VALUES (9948, 593280, 'Cat Quest', 'The multi award-winning Action RPG. Some say ''Diablo with Cats'' others a ''Super-cute Skyrim'', whatever your take, Cat Quest''s loot-fuelled cat-venture is as beautifully crafted, as its combat and magic are ultra-satisfying. Universally adored by critics - it''ll have you purring for joy!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/593280/header.jpg?t=1727256698', 0, 0, NULL);
INSERT INTO games VALUES (9951, 593490, 'Empire Architect', 'Empire Architect is an ancient city-building real time strategy game, with elements from grand strategies sprinkled in for good measure. The levels are procedurally generated, and you have limited control over your subjects', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/593490/header.jpg?t=1538288494', 0, 0, NULL);
INSERT INTO games VALUES (9933, 593640, 'Papetura', 'Papetura is a short atmospheric adventure game, with unique world handmade entirely out of paper, and beautiful fragile music. It tells the story of two little creatures whose house is in danger of being burned down.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/593640/header.jpg?t=1749069832', 1, 0, NULL);
INSERT INTO games VALUES (9928, 593900, 'Tender Loving Care', 'You are about to enter a fantasy quite unlike anything you''ve ever seen or felt before - a fantasy built from the stuff of your very own mind. Tender Loving Care is not just a finely crafted suspense story; it''s an exploration into your innermost perceptions, opinions, and attitudes.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/593900/header.jpg?t=1569518070', 0, 0, NULL);
INSERT INTO games VALUES (9908, 593960, 'Lorelai', 'The little she had was taken away, but Lorelai refuses to give up, she will fight. And not even death will stop her from getting it all back...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/593960/header.jpg?t=1741370579', 0, 0, NULL);
INSERT INTO games VALUES (9913, 594040, 'SERIES MAKERS TYCOON', 'Series Makers makes your dreams come true. Produce your own TV series and build your own TV studio with your team. Dominate the TV landscape and fight your way up for worldwide success!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/594040/header.jpg?t=1686304222', 0, 0, NULL);
INSERT INTO games VALUES (9914, 594050, 'Red Alliance', 'Red Alliance is an atmospheric, dark action thriller single player game with elements of horror. The game takes place in Eastern Europe where the society is under oppressive regime enforced by a mysterious scientist whom the player must stop to restore justice.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/594050/header.jpg?t=1698336567', 0, 0, NULL);
INSERT INTO games VALUES (9916, 594130, 'Winds of Change', 'Lead The Rebellion, build your army, and shape the world with your choices. A story-heavy adventure game with multiple endings, romance options, and non-linear storytelling. A vast fantasy world waiting to be explored. Inspired by Dragon Age, and Mass Effect. Fully voice acted by a stellar cast!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/594130/header.jpg?t=1725548063', 0, 0, NULL);
INSERT INTO games VALUES (9920, 594220, 'The Living Remain', 'The Living Remain is a virtual reality first person adventure shooter where players immerse themselves in a world where the undead have taken over. You must survive the horde of undead using an arsenal of weapons in a story driven campaign loaded with a variety of interactive environments.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/594220/4f38f980f9fca26b8d28c14094ff9fe3e3fee1d3/header.jpg?t=1747633519', 1, 0, NULL);
INSERT INTO games VALUES (9925, 594330, 'Visage', 'Visage is a first-person psychological horror game. Explore a mysterious ever-changing house in a slow-paced, atmospheric world that combines both uncannily comforting and horrifyingly realistic environments, and enjoy a genuinely terrifying experience.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/594330/header.jpg?t=1607559678', 1, 0, NULL);
INSERT INTO games VALUES (9926, 594350, 'Attack Helicopter Dating Simulator', 'As a helicopter, your daily activities may include, morning maintenance, aerial attack runs, and delivering hell-fire missiles on noncombatants for democracy. Or you know, dating other helicopters. It is a visual novel after all...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/594350/header.jpg?t=1699285171', 0, 0, NULL);
INSERT INTO games VALUES (42659, 594570, 'Total War: WARHAMMER II', 'Strategy gaming perfected. A breath-taking campaign of exploration, expansion and conquest across a fantasy world. Turn-based civilisation management and real-time epic strategy battles with thousands of troops and monsters at your command.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/594570/header.jpg?t=1747123491', 1, 0, NULL);
INSERT INTO games VALUES (132052, 594650, 'Hunt: Showdown 1896', 'Hunt: Showdown 1896 is a new era of the addictively unforgiving extraction shooter. In corrupted backwaters lost to history, fight back alone – or with friends – against timeless evil. Twisted monsters and other ruthless Hunters stand between you and your Bounty. Risk everything as Hunt consumes you', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/594650/header.jpg?t=1746432020', 0, 0, NULL);
INSERT INTO games VALUES (9876, 595140, 'Immortal Redneck', 'Immortal Redneck is a FPS set in Egypt with rogue-lite elements. Frantic gameplay, twitch controls and an arcade-style feel meet randomly generated dungeons, a complete skill tree, permanent death and 9 classes with different traits.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/595140/header.jpg?t=1745480617', 1, 0, NULL);
INSERT INTO games VALUES (9880, 595280, 'Throne of Lies®: Medieval Politics', 'The 3D online multiplayer game of social deduction and mischief, inspired by medieval politics and the Werewolf/Mafia (1986) genre. Gather ''round the tabletop, uniting allies of the realm with strategy to distinguish friend from foe.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/595280/header.jpg?t=1730186391', 0, 1, NULL);
INSERT INTO games VALUES (9865, 595420, 'Franchise Hockey Manager 4', 'The Most Hockey Ever! Franchise Hockey Manager 4 is the deepest, most authentic hockey strategy game available. FHM 4 is officially licensed by the NHL®, includes real 2017-18 rosters, packs even more features than any of its predecessors, and takes the series to a whole new level in terms of realism and gameplay.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/595420/header.jpg?t=1633690569', 0, 0, NULL);
INSERT INTO games VALUES (9866, 595430, 'Sky Knights', 'Prove your skills as a pilot in this action-packed multiplayer dogfighting game. Take part in 4 vs 4 battles and outmaneuver opponents, master a variety of jets and weapons, support allied ground troops, and land on the runway. Only a well-orchestrated team of pilots can bring down the enemy bases.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/595430/header.jpg?t=1653756438', 0, 0, NULL);
INSERT INTO games VALUES (9867, 595440, 'CPU Invaders', 'Invaders are living inside your computer. You shouldn''t let that happen! Interact with your desktop while playing, watch Youtube videos, chat with your friends and more! CPU Invaders overlaps the game itself with your computer screen.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/595440/header.jpg?t=1648312067', 0, 0, NULL);
INSERT INTO games VALUES (9868, 595460, 'Flix and Chill', 'A dating simulator where your end goal is to get your date to &quot;Flix &amp; Chill&quot; with you. Do you have what it takes to do the bowchickawowow?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/595460/header.jpg?t=1488218749', 0, 0, NULL);
