INSERT INTO games VALUES (9871, 595520, 'FINAL FANTASY XII THE ZODIAC AGE', 'FINAL FANTASY XII THE ZODIAC AGE - This revered classic returns, now fully remastered for the first time for PC, featuring all new and enhanced gameplay.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/595520/header.jpg?t=1746070496', 1, 0, NULL);
