INSERT INTO games VALUES (9594, 602770, 'Clatter', 'Create and command your own customizable squads of fighting robots in this turn-based, arena tactics game.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/602770/header.jpg?t=1657904216', 0, 1, NULL);
INSERT INTO games VALUES (9598, 602890, 'hack_me 2', 'hack_me 2 is a story about hacker-beginner, who is going to confront to new World Order, where is no place for personal secrets.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/602890/header.jpg?t=1722516626', 0, 0, NULL);
INSERT INTO games VALUES (127954, 602960, 'Barotrauma', 'Barotrauma is a 2D co-op submarine simulator – in space, with survival horror and RPG elements. Steer your submarine, complete missions, fight monsters, fix leaks, operate machinery, man the guns and craft items, and stay alert: danger in Barotrauma doesn’t announce itself!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/602960/header.jpg?t=1749411231', 1, 0, NULL);
INSERT INTO games VALUES (9605, 603020, 'Skautfold: Usurper', 'Usurper is a Metroidvania Action-RPG. With Eldritch horrors having been unleashed by the outer-worldly Citadel, your job is to rid London of its terrors. Use the new &quot;Guard&quot; system that rewards skillful play and accuracy, to uncover the massive structure and defeat the nightmares lurking within.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/603020/header.jpg?t=1688449424', 0, 0, NULL);
INSERT INTO games VALUES (9580, 603260, 'The Cat Games', 'Do you like cats? Then this is the purrfect game for you!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/603260/header.jpg?t=1669185816', 0, 0, NULL);
INSERT INTO games VALUES (9582, 603320, 'Age of Defense', 'Age of Defense is a tower defense game full of mind-blowing mayhem. There are tons of monsters and tough defenders in the game each of which fits perfectly into a funny cartoonish setting.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/603320/header.jpg?t=1738267951', 0, 0, NULL);
INSERT INTO games VALUES (42287, 603390, 'Stone Story RPG', 'An auto-RPG with strategic combat, deep crafting and programming elements, animated entirely in ASCII-art. In a realm of perpetual darkness, a single stone could change everything...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/603390/header.jpg?t=1749445314', 1, 0, NULL);
INSERT INTO games VALUES (9546, 603530, 'A Robot Named Fight!', 'A Robot Named Fight is a Metroidvania roguelike focused on exploration and item collection. Explore a different, procedurally-generated labyrinth each time you play and discover randomized power-ups to traverse obstacles, find secrets and explode meat beasts.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/603530/header.jpg?t=1666986913', 0, 0, NULL);
INSERT INTO games VALUES (9552, 603700, 'The Low Road', 'Lie, blackmail, and steal your way down The Low Road. Rookie agent Noomi Kovacs must navigate her way through the world of corporate espionage in this dark spy comedy set in the 1970s.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/603700/header.jpg?t=1682728580', 0, 0, NULL);
INSERT INTO games VALUES (9554, 603750, '- Arcane Raise -', 'Arcane Raise is a role-playing video game franchise, wherein a group of resurrected hunters known as Shades, fight alongside humans against monsters in a post-apocalyptic world overrun by an infestation. Do you have what it takes to survive this hostile land?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/603750/header.jpg?t=1529633754', 0, 0, NULL);
INSERT INTO games VALUES (9556, 603800, 'ReThink', 'As an inmate of a government-controlled Correctional Facility in the year 2275, you have the right to prove yourself worthy of being part of Society again. Show your skills in logical thinking by solving puzzles of varying size, type and difficulty in this first-Person puzzle game, and redeem your freedom!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/603800/header.jpg?t=1725027552', 0, 0, NULL);
INSERT INTO games VALUES (9557, 603810, 'A Girls Fabric Face', 'A brutal murder has taken place. To that, you find yourself investigating what has happened through cameras set up in the house. Upon investigating you find yourself determining that not everything is as it seems. In the end, you are faced with an important decision to truly understand what happened to the girls with the fabric face.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/603810/header.jpg?t=1489463178', 0, 0, NULL);
INSERT INTO games VALUES (9559, 603850, 'Age of History II', 'Age of History II is a grand strategy wargame that is simple to learn yet hard to master.Your objective is to use military tactics and cunning diplomacy to either unify the world, or conquer it.Will the world bleed out or bow before you? The choice is yours..', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/603850/header.jpg?t=1733070399', 1, 0, NULL);
INSERT INTO games VALUES (9564, 603940, 'Pixel Shopkeeper', 'Be a Pixel Shopkeeper! Collect items using inventory management puzzle mechanics. Sell your wares, decorate your shop, craft new products, and expand! Train to beat tougher dungeons, unlock new classes and decor, and furnish your shop smartly to maximize profits!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/603940/header.jpg?t=1701490047', 0, 0, NULL);
INSERT INTO games VALUES (42270, 603960, 'Star of Providence', 'Star of Providence is a top down action shooter with procedurally generated elements. Explore a large, abandoned facility in search of incredible power, fighting dangerous foes and gaining new weapons and upgrades as you progress.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/603960/header.jpg?t=1745609218', 0, 0, NULL);
INSERT INTO games VALUES (42281, 604240, 'Shotgun Farmers', 'Missed shots grow guns in this multiplayer shooter. Fire your bullets into the ground to plant your ammo. The longer it grows the more ammo you will get!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/604240/header.jpg?t=1747107282', 1, 0, NULL);
INSERT INTO games VALUES (9543, 604330, 'The Crown of Leaves', 'Roui, a resilient city dandy, a half-educated jeweler and the author of scientific magic articles, was met with a colossal failure and must return to his homeland Latori.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/604330/header.jpg?t=1619967087', 0, 0, NULL);
INSERT INTO games VALUES (9527, 604450, 'Another Adventure', 'Just another stupid adventure game', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/604450/header.jpg?t=1535924363', 0, 0, NULL);
INSERT INTO games VALUES (42258, 604490, 'Running Through Russia', 'Running Through Russia - funny runner with a bunch of memes about Russia and russian people.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/604490/header.jpg?t=1527014016', 0, 0, NULL);
INSERT INTO games VALUES (9530, 604540, 'Empire of Sin', 'Empire of Sin is a new strategy game brought to you by Romero Games and Paradox Interactive that puts you at the heart of the ruthless criminal underworld of 1920s Prohibition-era Chicago.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/604540/header.jpg?t=1700227131', 1, 0, NULL);
INSERT INTO games VALUES (9523, 604740, 'Danger Zone', 'Danger Zone is a vehicular destruction game from seasoned genre veterans Three Fields Entertainment. Step into the shoes of a dangerous driver and cause the biggest car crashes ever seen in a video game. Danger Zone combines real physical crashes with explosive gameplay.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/604740/header.jpg?t=1560524014', 0, 0, NULL);
INSERT INTO games VALUES (9525, 604780, 'aMAZE', 'aMaze is a straight-forward and surprisingly-difficult celebration of the simple beauty of the maze.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/604780/header.jpg?t=1745493515', 1, 0, NULL);
INSERT INTO games VALUES (140209, 605230, 'Grey Hack', 'Grey Hack is a massively multiplayer hacking simulator game. You''re a hacker with full freedom to act as you wish on a vast network of procedurally generated computers.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/605230/1346f58eb7166cc7a70ac267129593f9f1e0c728/header.jpg?t=1746574569', 0, 0, NULL);
INSERT INTO games VALUES (9511, 605450, 'In Death', 'Created exclusively for VR, In Death is a Roguelite Shooter set in the godless afterlife. Battle through procedurally generated levels and dungeons in intense ranged combat, coupled with a unique locomotion system perfectly attuned to your fighting style.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/605450/header.jpg?t=1715907411', 0, 0, NULL);
INSERT INTO games VALUES (128160, 605740, 'Flashing Lights - Police, Firefighting, Emergency Services (EMS) Simulator', 'Play solo or in up to 10-player multiplayer co-op! Flashing Lights is an open world police, firefighting and EMS simulator game with plenty of opportunity for role-play or more relaxed fun with friends. Become the law or save lives! Discover leagues of player-created mods!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/605740/header.jpg?t=1748446782', 0, 0, NULL);
INSERT INTO games VALUES (9502, 605830, 'Organ Quarter', 'Organ Quarter is a VR survival horror game built from the ground-up for hand-tracked virtual reality. Explore labyrinthine environments, engage in tense combat, carefully manage your resources and solve horrifying puzzles in this homage to the slow, methodical survival horror experiences of the ''90s', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/605830/header.jpg?t=1705586091', 1, 0, NULL);
INSERT INTO games VALUES (9486, 606230, 'Thea 2: The Shattering', 'In the dark lands inspired by Slavic myth, life is a struggle for survival against ever increasing odds, be it natural or malevolent. Can you lead your flock to prosperity in this innovative blend of 4X strategy, RPG and card game?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/606230/header.jpg?t=1726817593', 0, 0, NULL);
INSERT INTO games VALUES (9487, 606280, 'Darksiders III', 'В Darksiders III вы вернетесь на мертвую Землю в роли ЯРОСТИ, которая намерена найти и уничтожить Семь смертных грехов. Самая загадочная из четырех всадников, ЯРОСТЬ должна преуспеть там, где потерпели неудачу другие: восстановить равновесие сил на Земле.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/606280/header.jpg?t=1725285714', 0, 0, NULL);
INSERT INTO games VALUES (9492, 606370, 'Romancing SaGa 2™', 'Sit upon the throne of the Varennes Empire and control several generations of rulers in a valiant battle against the Seven Heroes.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/606370/header.jpg?t=1717001404', 0, 0, NULL);
INSERT INTO games VALUES (9479, 606500, 'HellSign', 'HellSign is an investigative action RPG that pits you against the horrors of the afterlife, let loose on a small town. As a hunter, you’ll plan, hunt, and kill to pay the bills and piece together the fragments to your past. Just remember - a smart hunter is always prepared.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/606500/header.jpg?t=1671402329', 0, 0, NULL);
INSERT INTO games VALUES (9465, 606680, 'Silver', 'Silver, a corrupt and sinister sorcerer, rules the land of Jarrah with an iron fist. He and his henchmen have abducted the village women as part of a pact with the almighty god, Apocalypse. Now, only one man can put a stop to Silver and his minions. That man is you, David, a promising young knight whose wife is among the captured.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/606680/header.jpg?t=1727857764', 0, 0, NULL);
INSERT INTO games VALUES (9467, 606710, 'Sphinx and the Cursed Mummy', 'Sphinx and the Cursed Mummy is an original 3rd person action-adventure inspired by the mythology of ancient Egypt. Travelling the world via magical portals to foil the evil plans of Set. Sphinx''s journey will require all his wits, agility, and special powers.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/606710/header.jpg?t=1747753561', 1, 0, NULL);
INSERT INTO games VALUES (9469, 606730, 'Sine Mora EX', 'Sine Mora EX is a side-scrolling shoot''em up that provides a unique challenge, where time is the ultimate factor. Mixing classic shooter sensibilities with contemporary presentation, Sine Mora EX is a gorgeous shoot''em up offering both a Story Mode that weaves an excessive tale and an Arcade Mode.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/606730/header.jpg?t=1732704837', 0, 0, NULL);
INSERT INTO games VALUES (9471, 606800, 'Startup Company', 'Startup Company is a business simulation sandbox game where you’re the CEO of a new company. Your job is to build your very own website and compete against the largest tech giants on the planet!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/606800/header.jpg?t=1727681373', 1, 0, NULL);
INSERT INTO games VALUES (9474, 606860, 'Nephise', 'Nephise is a short and atmospheric puzzle game with narration. It is a relaxing and mysterious experience especially with the help of its music.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/606860/header.jpg?t=1728894434', 0, 0, NULL);
INSERT INTO games VALUES (9476, 606880, 'GreedFall', 'Engage in a core roleplaying experience, and forge the destiny of a new world seeping with magic, and filled with riches, lost secrets, and fantastic creatures. With diplomacy, deception and force, become part of a living, evolving world - influence its course and shape your story.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/606880/header.jpg?t=1727794180', 0, 0, NULL);
INSERT INTO games VALUES (9477, 606890, 'Masters of Anima', 'Delve into an original adventure and defy the forces of evil in strategic, action-packed battles. Summon and control large armies of up to 100 Guardians thanks to intuitive and innovative gameplay and make quick tactical decisions to prevail.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/606890/header.jpg?t=1728650322', 0, 0, NULL);
INSERT INTO games VALUES (9448, 606960, 'CRIMSON METAL Classic 1999', 'CRIMSON METAL - Far from Perfect, brutal and merciless.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/606960/header.jpg?t=1728937222', 0, 0, NULL);
INSERT INTO games VALUES (9453, 607050, 'Wargroove', 'Take to the battlefield with Wargroove, a strategy game for up to 4 players! Choose your Commander and wage turn-based war on battling factions. Design and share maps, cut-scenes and campaigns with easy-to-use editors and in-depth customization tools!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/607050/header.jpg?t=1730825639', 1, 0, NULL);
INSERT INTO games VALUES (9454, 607080, 'Psychonauts 2', 'Combining quirky missions and mysterious conspiracies, Psychonauts 2 is a platform-adventure game with cinematic style and tons of customizable psychic powers.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/607080/header.jpg?t=1745521663', 0, 0, NULL);
INSERT INTO games VALUES (9436, 607880, 'Accel World VS. Sword Art Online Deluxe Edition', 'Svart Alfheim and the Accelerated World have begun to merge. In the midst of the chaos, Yui has gone missing. Kirito must challenge the Seven Kings of pure color from the Accelerated World to gain access to her location.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/607880/header.jpg?t=1678742186', 1, 0, NULL);
INSERT INTO games VALUES (9437, 607890, 'Sword Art Online: Hollow Realization Deluxe Edition', '2026, Sword Art: Origin, a new VRMMORPG has emerged. Kirito meets a mysterious NPC and receives a cryptic message. This game is definitively not the same as the one he escaped years ago…', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/607890/header.jpg?t=1718967044', 1, 0, NULL);
INSERT INTO games VALUES (9426, 608120, 'AFTERBURN', 'Your daily dose of air combat. Super easy to pick up, minimum requirements and vibrant visuals. Setup your aircraft and jump into action!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/608120/header.jpg?t=1684481176', 0, 0, NULL);
INSERT INTO games VALUES (9418, 608530, 'TARTARUS', 'Can the cook save the ship?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/608530/header.jpg?t=1514495770', 0, 0, NULL);
INSERT INTO games VALUES (9412, 608800, 'Guns of Icarus Alliance', 'Own the skies in steam-powered airships! Guns of Icarus Alliance is a team-based online game that pits co-op crews against both rival teams and an AI that learns your tactics. Players become part of the story as each battle shapes history in an ever-changing steampunk world.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/608800/header.jpg?t=1569260269', 0, 0, NULL);
INSERT INTO games VALUES (9410, 608990, 'The Archotek Project', 'The Archotek Project focuses on a multiplayer experience, giving you the chance to play with your friends or with new people on dedicated servers. Play as the dinosaur as you explore vibrant and exotic locations within the game, taking control of unique species from the fossil record.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/608990/header.jpg?t=1689758239', 0, 1, NULL);
INSERT INTO games VALUES (9409, 609110, 'Blazing Chrome', 'In Blazing Chrome, bring your best pal and kick some metal butts to free the humankind while enjoying a classic run’n’gun, fully loaded with action and exciting fights!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/609110/header.jpg?t=1738771217', 1, 0, NULL);
INSERT INTO games VALUES (9401, 609150, 'STAR OCEAN™ - THE LAST HOPE -™ 4K & Full HD Remaster', 'Explore the galaxy on your quest, make allies and enemies among the alien races you encounter, and uncover a danger so great that it threatens all of creation.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/609150/header.jpg?t=1724832639', 0, 0, NULL);
INSERT INTO games VALUES (9408, 609490, 'Minit', 'Minit is a peculiar little adventure played sixty seconds at a time.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/609490/header.jpg?t=1747943427', 1, 0, NULL);
INSERT INTO games VALUES (9399, 609920, 'Hotshot Racing', 'Hotshot Racing is a blisteringly fast arcade-style racing game fusing drift handling, razor-sharp retro visuals and an incredible sense of speed to create an exhilarating driving experience.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/609920/header.jpg?t=1747736850', 1, 0, NULL);
INSERT INTO games VALUES (9389, 610180, 'The Jackbox Party Pack 4', 'The fourth pack in this storied party game franchise features Fibbage 3 and its new game mode, Fibbage: Enough About You; the twisted web game Survive the Internet; the dating contest Monster Seeking Monster; the deranged debate match Bracketeering; and the one-up art game Civic Doodle.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/610180/header.jpg?t=1728584458', 0, 0, NULL);
INSERT INTO games VALUES (9390, 610190, 'WARRIORS ALL-STARS', 'A battle of heroes where everyone is the lead! The very first all-stars title for Koei Tecmo! For the first time in Warriors series, flashy action combines both the traits of the original series and new exiting elements such as “Musou Rush”, open scenarios and multiple endings!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/610190/header.jpg?t=1748481855', 1, 0, NULL);
INSERT INTO games VALUES (9370, 610360, 'Zup! Zero', 'Minimal physical puzzle with explosions', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/610360/header.jpg?t=1674747696', 1, 0, NULL);
INSERT INTO games VALUES (9371, 610370, 'Desperados III', 'Desperados III is a story-driven, hardcore tactical stealth game, set in a ruthless Wild West scenario. Play smart if you want to succeed. A good plan can make the difference between survival and finding yourself at the business end of a pistol.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/610370/header.jpg?t=1725010859', 1, 0, NULL);
INSERT INTO games VALUES (42102, 610380, 'Ratty Catty', 'Ratty Catty is a Multiplayer / CO-OP hide &amp; seek game about the adventures of a domestic cat Catty and hazel dormouse Ratty, who eats the foods in the house, feeds its babies, and lives in a small rat nest.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/610380/header.jpg?t=1666985281', 1, 0, NULL);
INSERT INTO games VALUES (9375, 610500, 'Willy-Nilly Knight', 'Willy-Nilly Knight is the great story, based on the legend of King Arthur. Immerse yourself in a single-player, isometric, story-driven RPG with real-time gameplay and turn-based combat, set in the colorful fantasy universe. Will you find the power to save the world in the war of gods? Find your answer.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/610500/header.jpg?t=1510314927', 0, 0, NULL);
INSERT INTO games VALUES (9353, 610750, 'Games&Girls', 'An episodic Visual Novel about a Gamer and his life with cute girls.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/610750/header.jpg?t=1620643068', 0, 0, NULL);
INSERT INTO games VALUES (9355, 610810, 'Your Friend Hana', 'You don''t know what do to? Just ask Hana! You can chat with Hana, ask her any question and as an oracle she will answer you. Enter specific keywords and she will tell you different stories!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/610810/header.jpg?t=1491545685', 0, 0, NULL);
INSERT INTO games VALUES (9357, 610860, 'Shogo: Mobile Armor Division', 'You will know the true power of giant robots!Anime-influenced graphics and gameplay designFight on foot or pilot a giant mech in both open and urban environmentsAn interesting storyline with two possible endings', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/610860/header.jpg?t=1670451384', 0, 0, NULL);
INSERT INTO games VALUES (9358, 610900, 'Sumatra: Fate of Yandi', 'Lost and alone after a terrible landslide, Yandi must find his way home in this old-school point and click adventure set deep in the Sumatran jungle! Will he make it out alive?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/610900/header.jpg?t=1717420562', 0, 0, NULL);
INSERT INTO games VALUES (9363, 611040, 'Tube Tycoon', 'The only game of its kind where you can feel like a real internet celebrity! Record videos, interact with your subscribers, buy better equipment and gain fame!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/611040/header.jpg?t=1712750319', 0, 0, NULL);
INSERT INTO games VALUES (9340, 611150, 'your sisters', 'Who needs one desktop girl when you can have a whole squad? Meet your adorable chaos crew, always cute, sometimes weird and fun. Your Sisters is a little dose of dopamine for your boring desktop.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/611150/49c3e42569e04936e9da545ce43e517c584cbd95/header.jpg?t=1747073683', 0, 0, NULL);
INSERT INTO games VALUES (9341, 611160, 'Karnage Chronicles', 'A true VR Action RPG built from ground up to fully immerse you in what VR has to offer.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/611160/header.jpg?t=1680744659', 0, 0, NULL);
INSERT INTO games VALUES (9342, 611180, 'Super Street: The Game', 'STREET RACING AT HEART Super Street: The Game is the official arcade racing game for Super StreetTM, the world’s number one in automotive tuning culture. Build your ride, part by part, from scrap and use it to tear up asphalt in a wealth of different game modes and environments.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/611180/header.jpg?t=1739866706', 0, 0, NULL);
INSERT INTO games VALUES (9347, 611300, 'Task Force', 'Task Force is the ultimate tactical shooter sandbox that focuses on close quarters infantry combat. It''s made by a small indie team of 3 developers that strive to create exceptional action simulation games.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/611300/header.jpg?t=1722541876', 0, 0, NULL);
INSERT INTO games VALUES (9348, 611350, 'Evil Tag', 'Four teenagers have to pass the rite of student initiation. To do this, they must read a spell from the ancient book in the basement of the abandoned house and spend a night there. They thought it would be fun...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/611350/header.jpg?t=1649159353', 0, 0, NULL);
INSERT INTO games VALUES (9337, 611500, 'Quake Champions', 'Step into the Arena. Compete against players from around the world in this fast-paced shooter that combines the dark mythos of the original Quake with the skill-based competition of Quake III Arena. Become a Champion.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/611500/header.jpg?t=1741893844', 0, 1, NULL);
INSERT INTO games VALUES (9321, 611660, 'Fallout 4 VR', 'Fallout 4, the legendary post-apocalyptic adventure from Bethesda Game Studios and winner of more than 200 ‘Best Of’ awards, including the DICE and BAFTA Game of the Year, comes in its entirety to VR.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/611660/header.jpg?t=1607445202', 0, 0, NULL);
INSERT INTO games VALUES (9322, 611670, 'The Elder Scrolls V: Skyrim VR', 'A true, full-length open-world game for VR has arrived from Bethesda Game Studios. Skyrim VR reimagines the complete epic fantasy masterpiece with an unparalleled sense of scale, depth, and immersion. Skyrim VR also includes all official add-ons.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/611670/header.jpg?t=1564002443', 0, 0, NULL);
INSERT INTO games VALUES (9327, 611750, 'Welcome to Hanwell', 'Open world horror set in a city in which your worst nightmares have become an everyday part of life. Explore a dense open world of terror, every building a unique location with it''s own story to tell. Strung together by the remenants of Hanwell.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/611750/header.jpg?t=1724325777', 0, 1, NULL);
INSERT INTO games VALUES (9328, 611760, 'Don''t Escape: 4 Days to Survive', 'Survive through four days at the end of the world in this post-apocalyptic point-and-click thriller where your choices could keep you alive... or not.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/611760/header.jpg?t=1726580887', 0, 0, NULL);
INSERT INTO games VALUES (9330, 611790, 'House Party', 'House Party is an edgy comedy adventure game inspired by classic comedies of the ''90s. Every decision changes your story and every character has something to reveal. There’s also a button to take your pants off.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/611790/baa245f042e4dff2a9c140d72dfb145906c4998d/header.jpg?t=1743609114', 0, 0, NULL);
INSERT INTO games VALUES (9331, 611800, 'Jidousha Shakai', 'Jidousha Shakai is an open world racing game with unrivaled customization to spark the new coming of open world racers. Control every inch of your cars appearance to give it your unique touch. If you''d like to experience Jidousha Shakai in it''s fullest form we need your help today!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/611800/header.jpg?t=1602753897', 1, 0, NULL);
INSERT INTO games VALUES (9298, 611980, 'Oik 2', 'Casual physics puzzle', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/611980/header.jpg?t=1570935177', 1, 0, NULL);
