INSERT INTO games VALUES (9277, 612390, 'Dandara: Trials of Fear Edition', 'In a bizarre universe where the oppressed are on the brink of oblivion, Dandara has awoken to reshape the world.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/612390/header.jpg?t=1726577284', 1, 0, NULL);
INSERT INTO games VALUES (9279, 612470, 'Bio Inc. Redemption', 'Bio Inc.: Redemption is a realistic simulation and strategy game in which you make life or death decisions. Create a deadly illness to infect and torment your victim or play as the head of a medical team and hopefully find a cure to save your human patient. Will you be the plague or preserve humanity?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/612470/header.jpg?t=1733857397', 0, 0, NULL);
