INSERT INTO games VALUES (9099, 618740, 'Beat Hazard 2', 'Experience your music collection as never before with this intense music driven arcade shooter. Each of your songs will have its own unique ebb and flow based on the music.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/618740/header.jpg?t=1745498287', 0, 0, NULL);
INSERT INTO games VALUES (9066, 618850, 'Pumpkin Days', 'Pumpkin Days is a traditional farming RPG. Pick one of three towns to start your farming adventure. Farm, fish, mine, catch bugs, raise animals, and more. Help fill out the museum to stop a factory from being built on the island. Unless you wish to side with the factory. The choice is yours.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/618850/header.jpg?t=1666983702', 0, 0, NULL);
