INSERT INTO games VALUES (9068, 618950, 'Agatha Knife', 'Embark on a whimsically twisted adventure with Agatha, a child torn between her love for eating meat and her friendships with animals. Join her as she discovers religion and creates her own, Carnivorism, to convince animals that the sacrifice of their flesh is the secret to their eternal happiness.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/618950/header.jpg?t=1740741685', 1, 0, NULL);
