INSERT INTO games VALUES (9072, 619080, 'SOS', 'In SOS: BR, You are 1 of 32 players on La Cuna Island, forced to fight to the death. Along with your wits, you will have to equip yourself. Guns are certainly an option, but melee weapons are just as deadly. Keep your eyes open for footprints and other indicators that help you stalk your enemies...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/619080/header.jpg?t=1544476555', 1, 0, NULL);
