INSERT INTO games VALUES (41768, 619280, 'Gloom', 'Afflicted by severe amnesia, you drift deep into the Common Dream. You scour for the lost pages of the Necronomicon, while clinging on to any little purpose you have left. Faced with mad dreamers, horrible abominations and eldritch deities, you feel drawn to the dark Abyss deep within.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/619280/header.jpg?t=1573752302', 0, 0, NULL);
INSERT INTO games VALUES (9051, 619390, 'Oddworld: Soulstorm Enhanced Edition', 'Oddworld: Soulstorm is the explosive second game in a brand new Oddworld Quintology that tells the continuing story of Abe and his comrades as they discover further crimes against Mudokonkind and look for the spark that will ignite a revolution.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/619390/header.jpg?t=1728644606', 0, 0, NULL);
