INSERT INTO games VALUES (129146, 619540, 'Darkwater', 'Darkwater is a cooperative extraction horror game for 1-4 players. Command a submarine trapped under the ice of an alien planet. Battle enemy vessels and deep sea abominations as you hunt for resources. Do what it takes to survive.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/619540/1cfdc7c9670fb4267803d6b26778b0bec120de74/header.jpg?t=1745340971', 1, 0, NULL);
