INSERT INTO games VALUES (9034, 619820, 'Heroes of Hammerwatch II', 'A rogue-lite action-rpg that offers extensive persistent progression. Build your town, upgrade and equip your heroes, before taking on the the ever-changing Dark Citadel - either solo or with a team of friends.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/619820/header.jpg?t=1738105739', 0, 0, NULL);
INSERT INTO games VALUES (9036, 619880, 'ATOMEGA', 'Grow, fight, collect and evade in the last cosmic arena the very end of time. Acquire MASS to evolve your EXOFORM from the nimble ATOM to the godlike OMEGA and compete for fun and dominance in a fast-paced, multiplayer shooter. ATOMEGA™ !', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/619880/header.jpg?t=1692032229', 1, 0, NULL);
INSERT INTO games VALUES (9019, 620190, 'Gunsmith', 'Build up your own arms manufacturing company. Find your factory, buy resources, produce a wide range of military equipment to sell to the highest bidder. Good or bad? That''s up to you, who you do business with is your choice. Don''t ask, don''t tell, get paid. After all, war is about making money.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/620190/0d77a21f3f872ef34bf05872978bd0e2f0518713/header.jpg?t=1746547354', 0, 0, NULL);
INSERT INTO games VALUES (9020, 620210, 'Fatal Twelve', 'Shishimai Rinka was a high schooler who ran a small café named Lion House in place of her grandmother. She lived her life much like any other person her age, but one day, she was caught up in an explosion while returning home on the train alongside her friend, Hitsuji Naomi.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/620210/header.jpg?t=1726606558', 0, 0, NULL);
INSERT INTO games VALUES (9021, 620220, 'Catmaze', 'Catmaze is a fairy metroidvania inspired by Slavic myths. Age-old tales will come to life in the unforgettable adventure of Alesta, a sorceress whose courage guides her through mysterious paths and dark forests in search of the lost road to Nav, the world of the dead.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/620220/header.jpg?t=1745847678', 0, 0, NULL);
INSERT INTO games VALUES (9005, 620590, 'Ancestors Legacy', 'Ancestors Legacy is a squad-based real time strategy with a strong focus on tactics. Inspired by medieval European history, it brings to life four different nations and their conflicts, usually solved by war.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/620590/header.jpg?t=1713951716', 0, 0, NULL);
INSERT INTO games VALUES (135114, 620980, 'Beat Saber', 'Beat Saber is a VR rhythm game where you slash the beats of adrenaline-pumping music as they fly towards you, surrounded by a futuristic world.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/620980/header.jpg?t=1749135147', 1, 0, NULL);
INSERT INTO games VALUES (8994, 621060, 'PC Building Simulator', 'Build and grow your very own computer repair enterprise as you learn to diagnose, fix and build PCs. With real-world licensed components and comprehensive hardware and software simulation, you can plan and bring your ultimate PC to life.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/621060/header.jpg?t=1653555111', 1, 0, NULL);
INSERT INTO games VALUES (8995, 621070, 'Legends of Ellaria', 'Legends of Ellaria is a unique blend of sandbox action-RPG and real-time strategy. Build a new kingdom for your people, construct and manage its cities, command your troops in epic battles and join them fighting in third-person action, and live adventures in an immersive high fantasy world.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/621070/header.jpg?t=1617292832', 0, 0, NULL);
INSERT INTO games VALUES (9001, 621220, 'Nantucket', 'Chase after Moby Dick, and live through the Golden Age of American whaling in this seafaring strategy game. Set sail around the world, manage your ship and crew, and live Ishmael''s story, the sole survivor of the Pequod, a few years after the events narrated by Herman Melville in his masterpiece.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/621220/header.jpg?t=1719346796', 0, 0, NULL);
INSERT INTO games VALUES (8983, 621810, 'Strain Tactics', 'Strain Tactics is a real-time-with-pause tactical game, where you command a squad of soldiers to liberate earth from an alien infestation. Using your helibase, deploy your custom squad and provide air support. Remember to keep your crew sane and motivated while staying clear of alien contamination!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/621810/header.jpg?t=1508843505', 0, 0, NULL);
INSERT INTO games VALUES (8984, 621830, 'WRC 7 FIA World Rally Championship', 'Take on all the challenges of the 2017 World Rally Championship: the official cars and drivers, 13 countries, 52 Special Stages, every surface, more powerful cars, more demanding physics, longer races, and an eSports mode to keep you on the edge of your seat all year round.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/621830/header.jpg?t=1725354050', 1, 0, NULL);
INSERT INTO games VALUES (8967, 621930, 'Attack of the Earthlings', 'Take on Galactoil, a comically dysfunctional intergalactic energy corporation, and its larger-than-life employees in a tactical-stealth game that fuses satisfying strategic gameplay and dark comedy in a quirky single-player story.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/621930/header.jpg?t=1748505738', 1, 0, NULL);
INSERT INTO games VALUES (8972, 622040, 'Zooicide', 'Zooicide is a casual team-based multiplayer game featuring animals fighting against humans within a playfully dangerous environment, the zoo.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/622040/header.jpg?t=1508622533', 0, 0, NULL);
INSERT INTO games VALUES (8977, 622220, 'Fate/EXTELLA LINK', 'History, legend, and sci-fi collide in the latest chapter of the Fate/EXTRA saga! Join 26 Heroic Spirits from all across time as they hack and slash their way across the battlefields of SE.RA.PH, a digital realm for the last survivors of Earth.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/622220/header.jpg?t=1741822729', 1, 0, NULL);
INSERT INTO games VALUES (8951, 622420, 'Stay Alive: Apocalypse', 'You ever played a Sandbox Survival Zombie RPG? You heard it right. In &quot;Stay Alive: Apocalypse&quot; we will offer you an indie zombie survival game which is in a sandbox, random generated world and presents RPG elements.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/622420/header.jpg?t=1581796409', 0, 0, NULL);
