INSERT INTO games VALUES (8961, 622650, 'Bendy and the Ink Machine', 'Bendy and the Ink Machine® is the first person puzzle action horror game that will forever ruin your childhood love of cartoons.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/622650/header.jpg?t=1746814533', 0, 0, NULL);
INSERT INTO games VALUES (8965, 622720, 'Weedcraft Inc', 'Weedcraft Inc explores the business of producing, breeding and selling weed in America, delving deep into the financial, political and cultural aspects of the country''s complex relationship with this troublesome and promising plant.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/622720/header.jpg?t=1728690277', 0, 0, NULL);
