INSERT INTO games VALUES (8935, 622870, 'Within the blade', 'Bloody stealth platformer, about the ninja in which you cut the enemies into pieces.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/622870/header.jpg?t=1637246438', 0, 0, NULL);
