INSERT INTO games VALUES (8907, 623880, 'World of Speed', 'World of Speed is a next generation online racing game for fans of high speeds and powerful cars. Modern graphics and responsive controls allow players of any level to feel the thrill of modern street racing.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/623880/header.jpg?t=1545802678', 0, 0, NULL);
INSERT INTO games VALUES (8911, 623940, 'HIVESWAP: ACT 1', 'A hand-drawn tribute to hilarious ''90s adventure games (with none of the accompanying frustration). Play as Joey Claire, a puzzle-solving teen snatched out of her time (1994) and place (Earth) and stranded on a hostile alien planet on the brink of rebellion.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/623940/header.jpg?t=1623696220', 0, 0, NULL);
