INSERT INTO games VALUES (8844, 625680, 'Way of the Passive Fist', 'Way of the Passive Fist is a unique and colorful arcade brawler. Parry, Dodge and Dash to outwit and outlast your enemies on a desolate planet ruled by raiders, mutants and fanatical sun worshipers. It''s a new kind of tactical fighting in the licensed arcade brawler for the 90s cartoon you wish existed.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/625680/header.jpg?t=1668230463', 0, 0, NULL);
