INSERT INTO games VALUES (8808, 628070, 'Romance of the Three Kingdoms XI with Power Up Kit', '&quot;Romance of the Three Kingdoms 11 with Power Up Kit&quot; is an expanded version of &quot;Romance of the Three Kingdoms 11,&quot; which was released in 2006 as the 11th game in the series. The grand battles that shaped the course of Chinese history are shown in 3D space! In Administration, players freely develop cities.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/628070/header.jpg?t=1736924676', 0, 0, NULL);
