INSERT INTO games VALUES (8781, 628770, 'Tangledeep', 'Enter the magical world of Tangledeep, a beautifully polished dungeon crawler inspired by classic 16-bit RPGs! Colorful characters, a unique job system, tons of skills, items, and diverse environments with deep, turn-based roguelike gameplay. A different adventure every time you play!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/628770/header.jpg?t=1733986601', 0, 0, NULL);
