INSERT INTO games VALUES (8705, 631570, 'Whispers of a Machine', 'Whispers of a Machine is a Sci-Fi Nordic Noir that tells the story of Vera, a cybernetically augmented detective in a post-AI world, who investigates a string of murders and unravels a dark conflict over forbidden technology.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/631570/header.jpg?t=1726577495', 0, 0, NULL);
INSERT INTO games VALUES (8683, 631830, 'Sarcophag', 'Casual game for attentiveness', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/631830/header.jpg?t=1570935624', 1, 0, NULL);
INSERT INTO games VALUES (8690, 631980, 'Immortal Planet', 'Immortal Planet is an action RPG with challenging combat that rewards patience and punishes recklessness. Explore the crumbling remains of a society of immortals trapped in endless cycles of rebirth. Fight your way to discover the planet''s mystery and escape its curse.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/631980/header.jpg?t=1563970828', 0, 0, NULL);
INSERT INTO games VALUES (8692, 632000, 'CrossCells', 'CrossCells is an ambient logic puzzle game.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/632000/header.jpg?t=1560433944', 0, 0, NULL);
INSERT INTO games VALUES (8696, 632070, 'The Fidelio Incident', 'The Fidelio Incident is a single-player, first-person thriller set off the coast of Iceland. Inspired by Beethoven''s only opera Fidelio. After a violent plane crash, Stanley must search a desolate frozen island in search of his wife Leonore while covering up any traces of their bloody Irish past.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/632070/header.jpg?t=1500848151', 0, 0, NULL);
INSERT INTO games VALUES (8670, 632200, 'Kuro survival', 'In the game, we live as Kuro''s life, a young ninja got a bad situation in the forest of monster. Kuro have to fight against a ton of monster to stay alive. With blade and shurikens, Kuro hope that he can come back to home soon. Together, help Kuro reunite with his waifu.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/632200/header.jpg?t=1748336977', 0, 0, NULL);
INSERT INTO games VALUES (101129, 632300, 'Hobo: Tough Life', 'Hobo: Tough Life is an urban survival role-playing game where you play as a homeless person. Play alone or team up in online co-op. Explore the streets of Praslav, scavenge for food and supplies, beg, steal, and do whatever else it takes to survive the forthcoming winter.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/632300/header.jpg?t=1683874995', 0, 0, NULL);
INSERT INTO games VALUES (8674, 632350, 'Cyberdimension Neptunia: 4 Goddesses Online', 'In this hack ''n'' slash adventure co-developed with Tamsoft and Compile Heart, the 4 Goddesses enter an online fantasy game inspired by... themselves! Choose from 12 characters with unique playstyles and skills to fight in realtime brawls, customize with accessories, and play online with others!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/632350/header.jpg?t=1730834000', 0, 0, NULL);
INSERT INTO games VALUES (135631, 632360, 'Risk of Rain 2', 'Escape a chaotic alien planet by fighting through hordes of frenzied monsters – with your friends, or on your own. Combine loot in surprising ways and master each character until you become the havoc you feared upon your first crash landing.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/632360/header.jpg?t=1747421657', 1, 0, NULL);
INSERT INTO games VALUES (8676, 632470, 'Disco Elysium - The Final Cut', 'Disco Elysium - The Final Cut is a groundbreaking role playing game. You’re a detective with a unique skill system at your disposal and a whole city to carve your path across. Interrogate unforgettable characters, crack murders or take bribes. Become a hero or an absolute disaster of a human being.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/632470/header.jpg?t=1727256511', 1, 0, NULL);
INSERT INTO games VALUES (8661, 632800, 'Beyond Eden', 'Beyond Eden is a Boy''s love visual novel set in the Victorian era, centering on the themes of love-hate and revenge. As protagonist Alex, the player may proceed to destroy an aristocratic family while pursuing complex relationships with 6 different male characters. Does the fall await beyond Eden?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/632800/header.jpg?t=1691477413', 0, 0, NULL);
INSERT INTO games VALUES (101090, 633060, 'Orwell: Ignorance is Strength', 'Step into the shoes of a government official in a top-secret department of the Orwell surveillance program. Given the power to both uncover and fabricate &quot;the truth&quot;, how far will you go in the service of your country? Season 2 of Orwell, the award-winning surveillance thriller.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/633060/header.jpg?t=1744397596', 0, 0, NULL);
INSERT INTO games VALUES (8668, 633110, 'FAST BEAT LOOP RACER GT | 環狀賽車GT', 'Straight from coin-op to your PC comes the fuel soaked, turbo fired, 1 to 4 players arcade action of FAST BEAT LOOP RACER GT. Race your friends around the world as you compete on 48 tracks set against the cityscapes of Tokyo, Osaka, Shanghai and Beijing.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/633110/header.jpg?t=1584592683', 0, 0, NULL);
INSERT INTO games VALUES (101093, 633230, 'NARUTO TO BORUTO: SHINOBI STRIKER', 'Battle as a team of 4 to compete against other teams online! Graphically, SHINOBI STRIKER is also built from the ground up in a completely new graphic style. Lead your team and fight online to see who the best ninjas are!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/633230/header.jpg?t=1748556203', 1, 0, NULL);
INSERT INTO games VALUES (41364, 633360, 'Remothered: Tormented Fathers', 'Remothered: Tormented Fathers is the pure and realistic survival horror videogame', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/633360/header.jpg?t=1721511824', 1, 0, NULL);
INSERT INTO games VALUES (8658, 633460, 'Tannenberg', 'Experience authentic First World War action with 64 player battles of maneuver on the Eastern Front. Grab your rifle, ready your sabre and keep your gas mask close as you prepare to play a part in one of the most significant conflicts in history!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/633460/header.jpg?t=1734529640', 0, 0, NULL);
INSERT INTO games VALUES (8645, 634160, 'Cattails | Become a Cat!', 'Become a cat! Cattails is a unique animal simulation RPG. Hunt for food, fight invading cats, explore to gather herbs, and socialize with other cats in an expansive open world. Get married and raise a family of kittens, befriend your neighbors, and learn to live in the dangerous wilderness!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/634160/header.jpg?t=1723659443', 0, 0, NULL);
INSERT INTO games VALUES (8642, 634410, 'A Story Beside', 'Step into the shoes of Lyric, the humble innkeeper in a quiet mountain village, as she reflects upon a lifetime of poignant memories, heartwarming friendships, and bittersweet choices — proving along the way that you don''t have to slay dragons to be the hero of your own story.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/634410/header.jpg?t=1677291794', 0, 0, NULL);
INSERT INTO games VALUES (8627, 635200, 'Distrust: Polar Survival', 'DISTRUST is an isometric survival adventure with procedural generation on an Arctic research station lost in the endless dark of a polar night. A story-rich fiction with multiple endings that suits both singleplayer fans and co-op enthusiasts.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/635200/header.jpg?t=1748493906', 1, 0, NULL);
INSERT INTO games VALUES (101046, 635260, 'CarX Drift Racing Online', 'CarX Drift Racing Online is your chance to immerse yourself in the real world of drifting. Get together with friends, tune your car and burn some tires!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/635260/69573f247d63cee371694f3e0392dab568ef384d/header.jpg?t=1749481123', 1, 0, NULL);
INSERT INTO games VALUES (8631, 635310, 'Ski Sniper', 'Have you ever wondered how difficult is to shoot a ski jumper on the fly with a sniper rifle? :) Ski Sniper gives you perfect opportunity to find out!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/635310/header.jpg?t=1600256651', 0, 0, NULL);
INSERT INTO games VALUES (8632, 635320, 'Last Day of June', 'A deep, interactive adventure about love and loss, beautifully depicted and offering an intense cinematic experience. What would you do to save the one you love?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/635320/header.jpg?t=1634642828', 1, 0, NULL);
INSERT INTO games VALUES (41315, 635940, 'Little Busters! English Edition', 'Capturing the hearts of countless fans since 2007, Little Busters! is an emotional visual novel from Key, the minds behind Angel Beats! and CLANNAD. This special English release supports touch controls and dynamic switching between English and Japanese text, and is in HD for the first time on PC.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/635940/header.jpg?t=1732683318', 0, 0, NULL);
INSERT INTO games VALUES (8607, 636100, 'Tesla vs Lovecraft', 'Tesla vs Lovecraft is an intense top-down twin stick arena shooter from the creators of Crimsonland and Neon Chrome. Play as the enigmatic inventor Nikola Tesla harnessing the static energy to power up Tesla-Mech and give the lovecraftian nightmares a lesson in horror!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/636100/header.jpg?t=1666993707', 1, 0, NULL);
INSERT INTO games VALUES (8608, 636150, 'Cyberhunt', 'Cyberhunt is a retro procedurally generated twin stick shooter, that takes you back to the sweet to the sweet arcade machines era!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/636150/header.jpg?t=1725479849', 1, 0, NULL);
INSERT INTO games VALUES (8609, 636170, 'Reaching for Petals', 'Reaching for Petals is a poetic adventure about love, loss, and ambition. You will travel to the peak of the ever-reaching mountain to uncover the true nature of your mysterious and seemingly unguided journey.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/636170/header.jpg?t=1561502993', 0, 0, NULL);
INSERT INTO games VALUES (8615, 636320, 'Depth of Extinction', 'Explore a flooded world and save humanity from a terrible threat in this turn based, tactical RPG with roguelike elements', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/636320/header.jpg?t=1745607831', 0, 0, NULL);
INSERT INTO games VALUES (8591, 636450, 'Rez Infinite', 'The legendary action-shooter finally comes to PC, and in style! Blast your way through mind-melting visuals and amazing beats, all in your quest through cyberspace to save a world on the verge of collapse. Playable on your desktop or in fully immersive VR.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/636450/170fa2690cb09f56a8e5f6cf10e31593679833c9/header.jpg?t=1741715104', 0, 0, NULL);
INSERT INTO games VALUES (8593, 636480, 'Ravenfield', 'Fight upon the Ravenfield together with your Blue allies! Take down those pesky Reds using helicopters, tanks, guns, and active ragdoll physics!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/636480/header.jpg?t=1664197939', 0, 0, NULL);
INSERT INTO games VALUES (8577, 636970, 'Tales Of Glory', 'Tales Of Glory is setting a new standard for medieval melee fights, bringing best of both worlds by combining large scale battles and full physics one vs many combat, everything packed into a 30+ hours sandbox campaign', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/636970/header.jpg?t=1620557346', 0, 0, NULL);
INSERT INTO games VALUES (8582, 637090, 'BATTLETECH', 'Take command of your own mercenary outfit of ''Mechs and the MechWarriors that pilot them, struggling to stay afloat as you find yourself drawn into a brutal interstellar civil war.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/637090/header.jpg?t=1726497883', 0, 0, NULL);
INSERT INTO games VALUES (8583, 637100, 'Sonic Forces', 'The fate of Sonic the Hedgehog’s world is in your hands – Join the Uprising.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/637100/header.jpg?t=1721835292', 1, 0, NULL);
INSERT INTO games VALUES (8566, 637650, 'FINAL FANTASY XV WINDOWS EDITION', 'Take the journey, now in ultimate quality. Boasting a wealth of bonus content and supporting ultra high-resolution graphical options and HDR 10, you can now enjoy the beautiful and carefully-crafted experience of FINAL FANTASY XV like never before.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/637650/header.jpg?t=1737963877', 1, 0, NULL);
INSERT INTO games VALUES (8567, 637670, 'Secret of Mana', 'The memorable adventure of Randi, Primm and Popoi is reborn as Secret of Mana! Originally released in 1993, Secret of Mana is by far the most popular title in the “Mana” series and has now undergone a much-awaited full 3D remake!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/637670/header.jpg?t=1724999058', 1, 0, NULL);
INSERT INTO games VALUES (8553, 638000, 'When Ski Lifts Go Wrong', 'Ride into a hilarious construction puzzler; packed with over 100 creative physics-based challenges, sports and bloody disasters! Build contraptions to help every passenger reach their destination. Enjoy the sports by controlling your riders away from (or towards if you feel like it) peril!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/638000/header.jpg?t=1743421609', 1, 0, NULL);
INSERT INTO games VALUES (8556, 638070, 'Murderous Pursuits', 'Murderous Pursuits is a kill-or-be-killed Victorian stealth-em-up for 1-8 players in which you must hunt and kill your quarry before your hunters do the same to you, all while avoiding witnesses.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/638070/header.jpg?t=1594630262', 1, 0, NULL);
INSERT INTO games VALUES (8558, 638160, 'Moero Chronicle', 'Io is a man who has no luck with the ladies, and now he''s tasked with recruiting Monster Girls to save the world in this moe-filled dungeon RPG! Recruit 50 Monster Girls! Combine their Moe Traits! Build relationships with them and find out just how cute a monster can be!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/638160/header.jpg?t=1732645826', 0, 0, NULL);
INSERT INTO games VALUES (8559, 638200, 'Capitalism 2', 'Create and control the business empire of your dreams. This in-depth strategy game covers almost every aspect of business that could be encountered in the real world.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/638200/header.jpg?t=1681189915', 0, 0, NULL);
INSERT INTO games VALUES (8560, 638230, 'Journey', 'Explore the ancient, mysterious world of Journey as you soar above ruins and glide across sands to discover its secrets.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/638230/header.jpg?t=1729099361', 1, 0, NULL);
INSERT INTO games VALUES (41250, 638510, 'dotAGE', 'Village elder, help us! The Apocalypse is approaching, and we need your guidance to survive. Assign your workers and build a thriving village against the pending doom. DotAGE is the merciless survival roguelite turn-based city builder. Will you fulfill the Prophecy?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/638510/header.jpg?t=1745477725', 0, 0, NULL);
INSERT INTO games VALUES (41226, 638650, 'Sword Art Online Re: Hollow Fragment', 'Take on the role of Kirito, the hero of the popular Sword Art Online anime series, and explore a fantasy world alongside attractive companions! Take down tough enemies in strategic battles and communicate with your companions in real time!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/638650/header.jpg?t=1703657343', 0, 0, NULL);
INSERT INTO games VALUES (8532, 638850, 'Animallica', 'In Animallica you are racing against extinction after a deadly virus ravaged the world. As the lone survivor of the last conservation center on Earth, the fate of every single animal and plant species lies in your hands.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/638850/header.jpg?t=1661759072', 0, 0, NULL);
INSERT INTO games VALUES (41235, 638970, 'Yakuza 0', 'SEGA’s legendary Japanese series finally comes to PC. Fight like hell through Tokyo and Osaka as junior yakuza Kiryu and Majima. Take a front row seat to 1980s life in Japan in an experience unlike anything else in video gaming, with uncapped framerates and 4K resolutions. A legend is born.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/638970/header.jpg?t=1741340656', 0, 0, NULL);
INSERT INTO games VALUES (8536, 638990, 'UNDYING - "KINGDOM"', 'As Anling’s zombie infection sets in, her days are numbered. The struggle to survive is made ever more paramount as she must ensure her son Cody stays alive. She must teach him how to survive in this new world at any cost…', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/638990/header.jpg?t=1717684359', 1, 0, NULL);
INSERT INTO games VALUES (8522, 639130, 'Ultrawings', 'Ultrawings is an aerial-themed, open-world flight game where you use your virtual hands to fly multiple aircraft to complete a variety of missions across a beautiful, island-themed world!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/639130/header.jpg?t=1625745550', 0, 0, NULL);
INSERT INTO games VALUES (8523, 639170, 'Minecraft: Story Mode - Season Two', 'Together with old pals and new comrades alike, Jesse embarks on a brand new journey filled with tough choices, good times, and at least one temperamental llama.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/639170/header.jpg?t=1556548671', 0, 0, NULL);
INSERT INTO games VALUES (8517, 639270, 'Operation Warcade VR', 'Relive the experience of playing the classic war arcade in a totally amazing way, thanks to virtual reality and the innovative immersion system that will make it possible for you to travel inside the video game.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/639270/header.jpg?t=1623923818', 1, 0, NULL);
INSERT INTO games VALUES (8514, 639490, 'Umineko When They Cry - Answer Arcs', 'This is the 2nd half of the Umineko When They Cry sound novel series, featuring episodes 5 through 8. This steam version features multi-language options, swap-able renewed character sprites, as well as the original BGMs and un-cut content.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/639490/header.jpg?t=1568926029', 0, 0, NULL);
INSERT INTO games VALUES (8509, 640120, 'Youropa', 'A platform puzzle paint adventure about breaking rules, being upside down and thinking outside the box.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/640120/header.jpg?t=1671044415', 1, 0, NULL);
INSERT INTO games VALUES (8497, 640380, 'UBERMOSH Vol.5', 'The fifth volume of the arcade series UBERMOSH.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/640380/header.jpg?t=1699491422', 1, 0, NULL);
INSERT INTO games VALUES (8498, 640590, 'The LEGO® NINJAGO® Movie Video Game', 'Find your inner ninja with the all-new LEGO NINJAGO Movie Video Game! Play as your favorite ninjas to defend Ninjago from the evil Lord Garmadon. Master the art of Ninjagility by wall-running and high-jumping, and battle foes to rank up and upgrade the ninja''s combat skills.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/640590/header.jpg?t=1729804932', 1, 0, NULL);
INSERT INTO games VALUES (8477, 640820, 'Pathfinder: Kingmaker — Enhanced Plus Edition', 'Pathfinder: Kingmaker - Enhanced Plus Edition is the first isometric party-based cRPG set in the Pathfinder fantasy universe. Enjoy a classic RPG experience inspired by games like Baldur''s Gate, Fallout 1 and 2 and Arcanum. Explore and conquer the Stolen Lands and make them your kingdom!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/640820/header.jpg?t=1738262487', 0, 0, NULL);
INSERT INTO games VALUES (8483, 640990, 'Fashioning Little Miss Lonesome', 'When two handsome young men spot the perfect girl to be their first model and help make a name for themselves, they''re determined to go for broke and make her shine—but first they''ll have to get her out of her house! Can these two really give such an anti-social recluse the makeover she needs to be a star?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/640990/header.jpg?t=1725524870', 0, 0, NULL);
INSERT INTO games VALUES (100888, 641080, 'Trials® Rising', 'Explore over-the-top action and physics-bending motorcycle racing in the latest opus of the Trials franchise. With new tracks in exotic places all over the world and more ways to compete, Trials® Rising is the best one yet.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/641080/header.jpg?t=1680017258', 0, 0, NULL);
INSERT INTO games VALUES (130614, 641320, 'Cooking Simulator', 'Play one of the best cooking games! Take control of a highly polished, realistic kitchen equipped with all kinds of utensils and stands. Unlock and master over 80 recipes or use dozens of lifelike ingredients to cook everything you like. A simulator spiced up with a dash of real-life physics!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/641320/header.jpg?t=1748530212', 1, 0, NULL);
INSERT INTO games VALUES (41169, 641780, 'The Drone Racing League Simulator', 'The DRL Simulator is the premier FPV racing game and simulator. The DRL Sim offers a robust, evolving feature set, including high-intensity drone racing. It packs tracks that DRL''s real world pilots compete on, with more added every season. And, it''s the only place to fly DRL''s exclusive drone, the Racer4!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/641780/header.jpg?t=1666986076', 0, 0, NULL);
INSERT INTO games VALUES (8471, 641960, 'BOXVR', 'Designed to give us back the fun we lost in exercise, BoxVR is the award-winning VR fitness game where you jab, weave and uppercut your way through workouts in time to adrenaline-pumping music.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/641960/header.jpg?t=1647099948', 1, 0, NULL);
INSERT INTO games VALUES (8473, 641990, 'The Escapists 2', 'Craft, Steal, Brawl and Escape! It’s time to bust out of the toughest prisons in the world as you return to the life of an inmate in The Escapists 2, now with multiplayer! Have you got what it takes to escape?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/641990/header.jpg?t=1726561627', 0, 0, NULL);
INSERT INTO games VALUES (8464, 642090, 'Coming Out on Top', 'The acclaimed gay dating sim. Have a sweet, sexy, or bizarrely comedic adventure with the man of your choice!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/642090/header.jpg?t=1667067157', 0, 0, NULL);
INSERT INTO games VALUES (8448, 642560, 'Art Of Gravity', 'Art Of Gravity is a voxel/physics based puzzle game, revolving around the theme of destroying abstract figures, which results in mesmerizing displays of dance of gravity.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/642560/header.jpg?t=1729158935', 1, 0, NULL);
INSERT INTO games VALUES (8452, 642610, 'Shape of the World', 'A serene first person exploration game in a surreal, organic world that reacts to your presence. Journey through a psychedelically colorful ecosystem of flourishing flora, rambling waterfalls, burgeoning mountains, glowing monoliths and graceful creatures. A 1-3 hour escape from work, anxiety and stress.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/642610/header.jpg?t=1748860141', 1, 0, NULL);
INSERT INTO games VALUES (8454, 642650, 'Pepper''s Puzzles', 'Pepper''s Puzzles is a collection of logic games also known as Nonogram, Picross or Griddlers.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/642650/header.jpg?t=1666987590', 0, 0, NULL);
INSERT INTO games VALUES (8443, 642770, 'Vinyl Reality - DJ in VR', 'Vinyl Reality is the most realistic and authentic simulation of DJing with vinyl in VR. Load and mix your own tracks with two fully-functional turntables and a DJ mixer. Easily record or stream sets from awesome audio reactive stages. Personalize your experience with custom environments and avatars.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/642770/header.jpg?t=1687883901', 0, 0, NULL);
INSERT INTO games VALUES (8440, 643200, 'Keep in Mind: Remastered', 'Keep in Mind follows Jonas, a man haunted by alcoholism, depression, and grief. One night, he awakens to a shadowy mirror world where beasts lurk and stars don''t shine. Lost and scared, Jonas must face the twisted beasts if he ever wishes to return home and learn the truth about his darkness.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/643200/header.jpg?t=1746832591', 0, 0, NULL);
INSERT INTO games VALUES (8438, 643620, 'Night Trap - 25th Anniversary Edition', 'Night Trap tells the story of five teenage girls spending the weekend at the Martin home. As a member of the Special Control Attack Team, your job is to monitor the home and protect the girls using an intricate system of cameras and traps as it is being invaded by vampires.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/643620/header.jpg?t=1502943133', 0, 0, NULL);
INSERT INTO games VALUES (8421, 643810, 'Fugl', 'Soar with the wind as a shape-shifting bird. Explore worlds teeming with life. Discover and morph into hundreds of animal species. Relax and enjoy the freedom of Fugl.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/643810/header.jpg?t=1733693617', 1, 0, NULL);
INSERT INTO games VALUES (8422, 643820, 'ShadowSide', 'ShadowSide is a First Person Exploration game. A policeman Alex Carter has been watching over the tranquility in the town for many years. He protects the people from robbery and crime. Nothing but a routine.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/643820/header.jpg?t=1722681290', 0, 0, NULL);
INSERT INTO games VALUES (8425, 643880, 'Strikey Sisters', 'Say hello to a fantasy themed action arcade brick breaker! Featuring cute characters, silly humor, powerful magic, crazy bosses, and even local 2 player co-op mode!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/643880/header.jpg?t=1725009289', 0, 0, NULL);
