INSERT INTO games VALUES (8430, 643960, 'Cursed Treasure 2', 'Why be good when you can be... bad? Cursed Treasure 2 is an addictive tower-defense game that puts the power of darkness at your fingertips. Build towers of powerful orcs, demons, and undead, and master powerful spells, to protect your precious hoard from all manner of no-good do-gooders.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/643960/header.jpg?t=1726580592', 0, 0, NULL);
INSERT INTO games VALUES (8414, 644390, 'D&D Lords of Waterdeep', 'Lords of Waterdeep is an award winning strategy board game, set in the Dungeons &amp; Dragons world of Waterdeep. Play as one of the masked Lords of the City of Splendor. Intrigue abounds as you recruit adventurers, via your agents, to quest on your behalf and spread your influence.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/644390/header.jpg?t=1647889655', 0, 0, NULL);
INSERT INTO games VALUES (8395, 644480, 'Outbreak: The New Nightmare', 'Return to the roots of co-op survival horror as you face monstrous hordes, scrounge for supplies and attempt to survive the nightmare. You have one life. Make it count!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/644480/header.jpg?t=1669392760', 0, 0, NULL);
