INSERT INTO games VALUES (8388, 645090, 'Zup! 5', 'Minimal physical puzzle with explosions', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/645090/header.jpg?t=1674747380', 1, 0, NULL);
INSERT INTO games VALUES (100775, 645630, 'Car Mechanic Simulator 2018', 'Build and expand your repair service empire in this incredibly detailed and highly realistic simulation game, where attention to car detail is astonishing. Find classic, unique cars in the new Barn Find module and Junkyard module. You can even add your self-made car in the Car Editor.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/645630/header.jpg?t=1747866076', 1, 0, NULL);
