INSERT INTO games VALUES (8359, 645790, 'Home Wars', 'Do you hate bugs and arachnids? Seeing them creeps you out? Would you like them to disappear off the face of the Earth? GOOD! This is the right game for you! In HW you’ll play as a General of a toy soldiers army, with the sole purpose of saving the owner’s house from the invasion of those damn Bugs.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/645790/header.jpg?t=1726326784', 0, 0, NULL);
