INSERT INTO games VALUES (7996, 655730, 'This Strange Realm Of Mine', 'This Strange Realm Of Mine is a First Person Shooter mixed with poetry and psychological horror. Graphic style is 3D mixed with pixel art.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/655730/header.jpg?t=1739387667', 0, 0, NULL);
