INSERT INTO games VALUES (40616, 656600, 'Slash It Ultimate', 'Play the rhythm of a song through various game modes and compete with other players!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/656600/header.jpg?t=1696796772', 1, 0, NULL);
