INSERT INTO games VALUES (7464, 668320, 'Perilous Warp', 'Perilous Warp is a fast-paced indie retro-shooter inspired by the classic 3D-actions. Communication with a distant space colony has been lost, and you bravely step into the teleporter with the desire for glorious adventures. But do not expect to win in a heartbeat!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/668320/header.jpg?t=1616988854', 0, 0, NULL);
INSERT INTO games VALUES (7465, 668350, 'Higurashi When They Cry Hou - Ch.6 Tsumihoroboshi', 'Higurashi When They Cry is a sound novel. The music, backgrounds and characters work together to create a world that is the stage of a novel for the user to read. They laugh and cry and get angry. The user takes the point of view of the protagonist to experience the story.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/668350/header.jpg?t=1725522856', 0, 0, NULL);
INSERT INTO games VALUES (7468, 668430, 'V-Racer Hoverbike', 'V-RACER HOVERBIKE is a fast-paced futuristic racing game in VR (HTC VIVE, OCULUS RIFT and Windows Mixed Reality). Available for Arcades on SpringboardVR', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/668430/4aeb3203d9f384b37c7ea018fa98f8e643e95d3d/header.jpg?t=1741710490', 0, 0, NULL);
INSERT INTO games VALUES (40103, 668550, '8Doors: Arum''s Afterlife Adventure', '8Doors is a story-driven Metroidvania-style action platformer heavily influenced by Korean folktales. Play as ‘Arum’, a brave girl that has entered the realm of the afterlife in search of her father’s soul and guide her through the ''8 Doors of Purgatory'' to solve the mysteries that lie deep within.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/668550/header.jpg?t=1740637876', 1, 0, NULL);
INSERT INTO games VALUES (7431, 668580, 'Atomic Heart', 'In a mad and sublime utopian world, take part in explosive encounters. Adapt your fighting style to each opponent, use your environment and upgrade your equipment to fulfill your mission. If you want to reach the truth, you''ll have to pay in blood.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/668580/header.jpg?t=1749247374', 1, 0, NULL);
INSERT INTO games VALUES (7432, 668590, 'Omen Exitio: Plague', 'Investigate a paranormal disease that threatens to eradicate humanity in this unsettling Lovecraftian adventure, inspired by the choose-your-own-adventure gamebooks of the 80s and 90s. Your choices will determine the story, your character’s destiny… and the future of humanity.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/668590/header.jpg?t=1741015939', 0, 0, NULL);
INSERT INTO games VALUES (7436, 668630, 'Tricolour Lovestory', 'Time flies and never comes back. But with an incredible 1-million-word script and 100+ original CGs, this game will take you back to when you were young, simple and pure. Go and get the love of your life back, start something new, or end everything in flame, that''s for you to decide!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/668630/header.jpg?t=1737807487', 0, 0, NULL);
INSERT INTO games VALUES (7454, 668980, 'Forsaken Remastered', 'Scavengers from all over the galaxy have come to a dead Earth to loot the remains of the technology that can found in underground tunnels. You must fight your way past the scum of the universe. As you prepare for deadly combat, you are going to quickly learn that the future is... Forsaken!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/668980/header.jpg?t=1591116064', 0, 0, NULL);
INSERT INTO games VALUES (7417, 669050, 'Mutiny!!', 'Mutiny!! is set in a world of fantasy, and adventure. A realm where airships can sail among the clouds as well as the sea, entering the flogiston to journey to other planes. There’s treasure spread out over many planes if you’re brave or curious enough to find it!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/669050/header.jpg?t=1513925607', 0, 0, NULL);
INSERT INTO games VALUES (7419, 669290, 'Espire 1: VR Operative', 'The future of VR action is now. Experience unprecedented stealth gameplay as you step into the shoes of the deadly Espire Agents with Espire 1: VR Operative. Sneak, shoot or do both. The choice is yours.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/669290/header.jpg?t=1737334451', 1, 0, NULL);
INSERT INTO games VALUES (137216, 669330, 'Mechabellum', 'Mechabellum is a rewarding tactical wargame where you gain victory by adapting your strategy and outthinking your opponents. Command a mechanized army in battles against humans or AI, customize your units and strategically place them on the battlefield to watch them destroy your enemies.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/669330/header.jpg?t=1748371669', 1, 0, NULL);
INSERT INTO games VALUES (7394, 669500, 'Himeko Sutori', 'Himeko Sutori is a tactical, turn-based RPG that combines intimate character development with epic battles featuring hundreds of unique characters. With the included campaign editor, you can make new worlds and new adventures, making Himeko Sutori your story.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/669500/header.jpg?t=1707457954', 0, 0, NULL);
INSERT INTO games VALUES (7413, 669950, 'BDSM: Big Drunk Satanic Massacre', 'BDSM is the first satirical action RPG where you get to play Lou, Satan’s son! Get some booze, kill the traitors, save Hell and rescue the hottest demoness from the clutches of those nasty people and mega-corporations!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/669950/header.jpg?t=1744107061', 1, 0, NULL);
INSERT INTO games VALUES (7373, 670160, 'D''LIRIUM', 'An experimental 2D-shooter with the elements of a horror game. D''lirium brings together some mechanics back from 90s classics. Non-linear levels, search for the keys, violence and a lot of other things. Including the colourful ponies.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/670160/header.jpg?t=1738482540', 0, 0, NULL);
INSERT INTO games VALUES (7378, 670260, 'Solace Crafting', 'Embark on an adventure set in a fantasy survival RPG. Visit a borderless, open world where you manage resources to construct your base and new types of equipment to support your conquest.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/670260/header.jpg?t=1710424571', 1, 0, NULL);
INSERT INTO games VALUES (7361, 670750, '0°N 0°W', 'Ready for a wild trip of psychedelic sights and sounds? 0°N 0°W is a chill, first-person walking sim for everyone, where each run is a fresh adventure!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/670750/7d976fad872d1ae7ebee0f45d0546a5623d259e3/header.jpg?t=1746400068', 1, 0, NULL);
INSERT INTO games VALUES (7307, 671390, 'Metropolis: Lux Obscura', 'A unique game with a film noir atmosphere, seductive wanton women, and dirty dangerous secrets. Gameplay is based on a motion comic with a non-linear plot mixed with MATCH3 puzzle fights.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/671390/header.jpg?t=1730574160', 0, 0, NULL);
INSERT INTO games VALUES (7308, 671440, 'Rise of Industry', 'Put your entrepreneurial skills to the test in the first title in the ROI series as you create &amp; optimise intricate production lines. As an early 20th-Century industrialist, grow your empire &amp; adapt to an ever-changing business landscape with unexpected events that could lead to boom…or bust.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/671440/header.jpg?t=1728037038', 0, 0, NULL);
INSERT INTO games VALUES (7313, 671510, 'DESOLATE', 'DESOLATE is a first person horror survival experience. Form a research team with up to 4 players and explore an open world filled with mysteries and unsolved questions, or do it all on your own.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/671510/header.jpg?t=1672159128', 1, 0, NULL);
INSERT INTO games VALUES (7319, 671620, 'Beast Battle Simulator', 'Beast Battle Simulator is a physics based battle-simulation sandbox game featuring dinosaurs, animals, and humans. Kamikaze Zebras VS. T-Rex with laser guns, Lions VS. medieval knights; anything is possible! Watch as the beasts dismember and rip each other apart in gory detail!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/671620/header.jpg?t=1519435286', 0, 0, NULL);
INSERT INTO games VALUES (7284, 671860, 'BattleBit Remastered', 'BattleBit Remastered is a low-poly, massive multiplayer FPS, supporting 254 players per server. Battle on a near-fully destructible map with various vehicles!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/671860/header.jpg?t=1730393449', 1, 0, NULL);
INSERT INTO games VALUES (138507, 671970, 'Junkyard Simulator', 'Did you ever wish to work in a junkyard? Now you can, with Junkyard Simulator. They are many roads leading to success - whichever you take depends on your decisions.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/671970/header.jpg?t=1747065414', 1, 0, NULL);
INSERT INTO games VALUES (7299, 672150, 'LOGistICAL 3: Earth', 'LOGistICAL 3: Earth is a strategy puzzle game where you transport different cargoes to complete all the towns throughout the planet. The whole game is a huge puzzle while each city is its own little piece of puzzling. Plenty of cities are easy enough plus a bunch of tougher challenges.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/672150/header.jpg?t=1613084518', 1, 0, NULL);
INSERT INTO games VALUES (7269, 672630, 'Academia : School Simulator', 'Design, build, and manage a high school with terrific teachers and fantastic facilities or simply let your students poop in the bushes? Academia : School Simulator is a management/tycoon game where you get to decide!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/672630/header.jpg?t=1726498028', 0, 0, NULL);
INSERT INTO games VALUES (7243, 673000, 'High Hell', 'High Hell is a neon-soaked, arcade-action first-person shooter from Terri Vellmann (Heavy Bullets) and Doseone (Enter the Gungeon, Gang Beasts).', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/673000/header.jpg?t=1659054648', 1, 0, NULL);
INSERT INTO games VALUES (7250, 673130, 'AMID EVIL', 'A retro FPS for the ages! Once branded a HERETIC. Now YOU have been chosen as our champion! Reclaim our sacred weapons. Take back our ancient lands. If you can stand... AMID EVIL.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/673130/ac7a568968bcfcdf78c215b920b77e67deadd54c/header.jpg?t=1743245671', 0, 0, NULL);
INSERT INTO games VALUES (7253, 673210, 'Frontier Pilot Simulator', 'FPS is a Sci-Fi cargo pilot sim, with an engaging emergent mission-driven storyline, with a real-time economy with free flight and trading, on an alien world to explore. All in customizable upgradeable, well-simulated VTOL craft with real weather, and flight dynamics.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/673210/header.jpg?t=1742900273', 0, 0, NULL);
INSERT INTO games VALUES (7213, 673260, 'Starblast', 'Fun, fast paced online multiplayer arcade space shooter. Take control of your spaceship, mine asteroids, increase your stats, upgrade to different types of spaceships with improved stats and weapons. Fight against other players and collect their gems.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/673260/header.jpg?t=1672736345', 1, 0, NULL);
INSERT INTO games VALUES (7220, 673450, 'Time Lock VR 1', 'TimeLock VR is an Escape the Room with Action elements where you take control over the time!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/673450/header.jpg?t=1746538262', 0, 0, NULL);
INSERT INTO games VALUES (39856, 673600, 'Prison Boss VR', 'Prison Boss VR is a crafting and trading game turning your VR space into a jail cell! Craft cigarettes, alcohol and cookies for other inmates! Customize your cell as your reputation grows! Earn cash until you can’t store it anymore and become the Prison Boss!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/673600/header.jpg?t=1746736389', 0, 0, NULL);
INSERT INTO games VALUES (7228, 673610, 'Airport CEO', 'Build and manage an international airport!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/673610/header.jpg?t=1725232871', 0, 0, NULL);
INSERT INTO games VALUES (7181, 673750, 'Super Bunny Man', 'A physics-based co-op platformer about a guy in a rabbit costume! Team up with a friend or three (local or online) to beat levels, find hidden carrots and race against the clock. Experience bunny madness. Embrace carrot chaos. Become Super Bunny Man.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/673750/header.jpg?t=1732013337', 1, 0, NULL);
INSERT INTO games VALUES (7182, 673800, 'Zup! XS', 'Experimental minimal physical puzzle with explosions.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/673800/header.jpg?t=1674751142', 1, 0, NULL);
INSERT INTO games VALUES (7186, 673850, 'Neofeud', 'Neofeud is a Dystopic Cyberpunk adventure game in the vein of Blade Runner, but with an overlay of Game of Thrones-like political intrigue, and 1366x768, hand-painted, stylized visuals.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/673850/header.jpg?t=1729837691', 0, 0, NULL);
INSERT INTO games VALUES (7188, 673880, 'Warhammer 40,000: Mechanicus', 'MECHANICUS II ANNOUNCED! Take control of one of the most technologically advanced factions in the Imperium: the Adeptus Mechanicus. In this turn-based tactical game, your every decision will weigh heavily on the outcome of the conflict. Will you be blessed by the Omnissiah?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/673880/header.jpg?t=1747933345', 1, 0, NULL);
INSERT INTO games VALUES (39878, 673950, 'Farm Together', 'Grow your own farm all by yourself, or cooperate with your friends in this unique, relaxing farming experience!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/673950/header.jpg?t=1725022743', 1, 0, NULL);
INSERT INTO games VALUES (7197, 674020, 'World War 3', 'World War 3 is a free-to-play tactical online multiplayer FPS where the world is your battleground. Outgun the enemy in thrilling, team-based skirmishes with a huge arsenal of weapons, vehicles, gadgets, and drones at your disposal.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/674020/header_alt_assets_2.jpg?t=1741627690', 1, 1, NULL);
INSERT INTO games VALUES (7198, 674090, 'Sky Haven Tycoon - Airport Simulator', 'Build your own airport in Skyhaven! Live out your airplane tycoon and simulation game fantasies and make the best surroundings and strategy for both airline manager and passenger alike. Schedule flight plans, build terminals, landing strips and more and create an airport tycoon empire in Skyhaven.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/674090/header.jpg?t=1669065139', 0, 0, NULL);
INSERT INTO games VALUES (7201, 674140, 'Bugsnax', 'Catch mysterious living snacks and feed them to your friends in this unusual island adventure!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/674140/header.jpg?t=1731435409', 1, 0, NULL);
INSERT INTO games VALUES (39850, 674500, 'Total Tank Simulator', 'Commander in the ranks. Soldier at heart. Choose a faction and deploy and command your army into massive physics-driven WWII battles to the last man standing. Destroy everything on sight with an insane amount of units that will behave tactically.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/674500/header.jpg?t=1696602077', 1, 0, NULL);
INSERT INTO games VALUES (7172, 674520, 'Fight''N Rage', 'Fight’N Rage is a brand new old-school side-scroller beat’em up. Inspired by the classics from the “golden age”, and with an art style that mimics the aesthetic from the 90''s arcade gems, this game pays homage to all classic gameplay features that makes this genre one of the best from its time!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/674520/header.jpg?t=1676503282', 0, 0, NULL);
INSERT INTO games VALUES (7141, 674750, 'Yet Another Zombie Defense HD', 'Top-down zombie shooter with tower defense elements featuring up to 4 players local and online co-op. Build your base by day, defend it by night, put your skills to the test to stay alive as long as possible! Darkness is coming. How long can YOU survive?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/674750/header.jpg?t=1731073134', 1, 0, NULL);
INSERT INTO games VALUES (7145, 674850, '2MD: VR Football Classic', '2MD VR Football Classic is a room-scale two-minute drill VR arcade experience that allows players to become a virtual quarterback! Draw your own plays before taking them on the road to victory. Featuring customization, fast-paced gameplay, an action packed bonus game, and more.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/674850/header.jpg?t=1637286931', 0, 0, NULL);
INSERT INTO games VALUES (7149, 674930, 'Boyfriend Dungeon', 'Date your weapons! Romance swords, daggers, and polearms to level them up in this “shack-and-slash” dungeon crawling adventure.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/674930/header.jpg?t=1748542948', 0, 0, NULL);
INSERT INTO games VALUES (7150, 674940, 'Stick Fight: The Game', 'Stick Fight is a physics-based couch/online fighting game where you battle it out as the iconic stick figures from the golden age of the internet.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/674940/header.jpg?t=1730715399', 0, 0, NULL);
INSERT INTO games VALUES (7153, 675010, 'MudRunner', 'MudRunner is the ultimate off-road experience putting the players in the driver seat and dares them to take charge of incredible all-terrain vehicles, venturing across extreme Siberian landscapes with only a map and compass as guides!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/675010/header.jpg?t=1729687266', 0, 0, NULL);
INSERT INTO games VALUES (7126, 675170, '303 Squadron: Battle of Britain', 'The enemies are close, would you dare to join the Squadron? Tweak planes in a 1st person mechanic mode, set the clouds on fire in aerial fights sim and discover extra missions in an open world of RAF Base. Enjoy a gameplay based on a real history and become the Ace of Sky.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/675170/header.jpg?t=1748430373', 0, 0, NULL);
INSERT INTO games VALUES (7130, 675240, 'Shining Song Starnova', 'Take the stage in Shining Song Starnova!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/675240/header.jpg?t=1677888594', 0, 0, NULL);
INSERT INTO games VALUES (7131, 675260, 'Batman: The Enemy Within - The Telltale Series', 'In this latest chapter from the award-winning studio behind Batman - The Telltale Series, both Bruce Wayne and Batman will be forced into precarious new roles. The Riddler has returned to terrorize Gotham City, but his gruesome puzzles merely foreshadow an even greater crisis.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/675260/header.jpg?t=1734105400', 0, 0, NULL);
INSERT INTO games VALUES (7066, 676420, 'SiNKR', 'SiNKR is a minimalist puzzler using various contraptions to sink pucks. Responsive ambient music. No holes left behind.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/676420/header.jpg?t=1691340533', 1, 0, NULL);
INSERT INTO games VALUES (7067, 676430, 'PUSH', 'Can you push all the buttons?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/676430/header.jpg?t=1729158938', 1, 0, NULL);
INSERT INTO games VALUES (7072, 676500, 'Time Warpers', 'Time Warpers is the evolution of the popular incremental game Time Clickers. With features like gun customization, optional permadeath &amp; co-op with friends, it combines a first person shooter with the seemingly endless progression &amp; upgrades of a clicker game.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/676500/header.jpg?t=1684692230', 0, 0, NULL);
INSERT INTO games VALUES (7081, 676630, 'Attentat 1942', 'Attentat 1942 is a historically-accurate adventure about World War 2. Face moral dilemmas and existential struggles as you uncover the troubled past of your family.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/676630/header.jpg?t=1730723264', 0, 0, NULL);
INSERT INTO games VALUES (7041, 676820, 'Subsurface Circular', 'When the truth is buried, go underground. Step into this new take on text-based adventure from the award-winning team behind Thomas Was Alone and Volume. A short story that hands you the fate of the world above, as a detective looking for answers on the Subsurface Circular.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/676820/header.jpg?t=1561982896', 0, 0, NULL);
INSERT INTO games VALUES (7043, 676840, 'Contagion VR: Outbreak', 'Contagion VR: Outbreak will immerse you into the middle of a zombie apocalypse. Relive stories of the survivors in the Single Player campaign, take your time in Free Roam, or check out the Firing Range!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/676840/header.jpg?t=1667310833', 0, 0, NULL);
INSERT INTO games VALUES (7050, 677020, 'Eventide 3: Legacy of Legends', 'Discover a forgotten land in the clouds!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/677020/header.jpg?t=1579787917', 1, 0, NULL);
INSERT INTO games VALUES (7055, 677120, 'Heroes of Hammerwatch', 'Heroes of Hammerwatch is a rogue-lite action-adventure. Explore and battle your way through procedurally generated levels on your own or with up to 3 friends.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/677120/header.jpg?t=1727923147', 0, 0, NULL);
INSERT INTO games VALUES (7056, 677160, 'We Were Here Too', 'As your final hour approaches, a large structure looms up in the distance, towering above the relentless storm. Discover the truth behind this dark castle in a communication-based, cooperative puzzle adventure.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/677160/header.jpg?t=1744724313', 1, 0, NULL);
INSERT INTO games VALUES (7034, 677340, 'The Colonists', 'Build a new home for your team of robots as they begin a new life for themselves on a distant planet where they can fulfil their ultimate dream: to be human.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/677340/header.jpg?t=1746466260', 1, 0, NULL);
INSERT INTO games VALUES (7037, 677480, 'Outpost Zero', 'Outpost Zero blends the genres of Multiplayer Base Building Survival and Simulation games in a Sci-Fi universe. On a lawless alien world, robotic scouts are tasked with building an Outpost for human colonists. Command AI minions, colonize the planet, and survive the perils of Gaiya.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/677480/header.jpg?t=1727200427', 0, 0, NULL);
INSERT INTO games VALUES (7013, 677620, 'Splitgate', 'Splitgate is a free-to-play, fast-paced multiplayer shooter that features player-controlled portals. This sci-fi shooter takes the FPS genre to a new dimension with its portal mechanics, delivering high-flying, multi-dimensional combat.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/677620/header.jpg?t=1663343172', 1, 1, NULL);
INSERT INTO games VALUES (6987, 678310, 'Pinball Deluxe: Reloaded', 'Cool retro pinball game with customizable tables. A flippin'' good time!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/678310/header.jpg?t=1672478602', 0, 0, NULL);
INSERT INTO games VALUES (39644, 678520, 'Gal*Gun VR', 'Put the VR headset on and enter a world where you are the most popular guy around! Dreams do come true! The legendary arcade-shooting game &quot;Gal*Gun&quot; is here in VR!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/678520/header.jpg?t=1667195180', 0, 0, NULL);
INSERT INTO games VALUES (6973, 678900, 'Farmer''s Dynasty', 'Live – Build – Farm: Enjoy a unique mix of farming, constructing and life simulation that takes you to the countryside and holds plenty of challenging gameplay in stock!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/678900/header.jpg?t=1741770597', 1, 0, NULL);
INSERT INTO games VALUES (6978, 678950, 'DRAGON BALL FighterZ', 'DRAGON BALL FighterZ is born from what makes the DRAGON BALL series so loved and famous: endless spectacular fights with its all-powerful fighters.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/678950/header.jpg?t=1733508969', 1, 0, NULL);
INSERT INTO games VALUES (6979, 678960, 'CODE VEIN', 'In the face of certain death, we rise. Team up and embark on a journey to the ends of hell to unlock your past and escape your living nightmare in CODE VEIN.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/678960/header.jpg?t=1701310785', 1, 0, NULL);
INSERT INTO games VALUES (6980, 678970, 'Modern Tales: Age of Invention', 'Foil the plan for world domination!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/678970/header.jpg?t=1581327890', 1, 0, NULL);
INSERT INTO games VALUES (132423, 679110, 'Werewolf: The Apocalypse - Earthblood', 'You are Cahal, a powerful Garou who chose to go into exile after losing control of his destructive rage. He can transform into a wolf and a Crinos, a huge ferocious beast. Master your three forms and their powers to punish those who defile Gaia.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/679110/header.jpg?t=1733310866', 1, 0, NULL);
INSERT INTO games VALUES (6933, 679750, 'Catch & Release', 'Catch &amp; Release places you on a beautiful mountain lake and lets you freely explore and row around while you choose your fishing spot and take in the scenery.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/679750/header.jpg?t=1667396194', 0, 0, NULL);
INSERT INTO games VALUES (39571, 679900, 'Swords & Souls: Neverseen', 'Swords &amp; Souls: Neverseen is a unique RPG where leveling up takes skill! Create, train and upgrade your character as you please, discover The Neverseen and its eccentric locals, and battle across the lands to foil an evil witch''s plans!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/679900/header.jpg?t=1746137100', 0, 0, NULL);
