INSERT INTO games VALUES (6455, 691320, 'Gun Club VR', 'Take to the range with an arsenal of the world’s most powerful weaponry in Gun Club VR. Addictive gameplay and unsurpassed realism combine to make Gun Club VR the ultimate virtual weapon simulator. The only thing missing is the smell of the gunpowder.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/691320/header.jpg?t=1670805417', 0, 0, NULL);
