INSERT INTO games VALUES (6432, 691690, 'Ash of Gods: Redemption', 'Ash of Gods: Redemption is a turn-based RPG that combines tactical combat, CCG elements, and a constantly evolving story in which no one is safe from death, including the main characters.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/691690/header.jpg?t=1731166901', 0, 0, NULL);
INSERT INTO games VALUES (6437, 691770, 'Eiyu*Senki – The World Conquest', 'A mysterious hero from the heavens and the young ruler of Zipang, Himiko, set their sights on ending the eternal war burning around them, but to bring peace to the world they must first conquer it.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/691770/header.jpg?t=1730126147', 0, 0, NULL);
INSERT INTO games VALUES (6439, 691830, 'Avernum 3: Ruined World', 'Wander free through this epic, indie fantasy adventure. Explore a huge world that evolves as time passes. Towns fight battles. Refugees flee. Disasters happen. Features cunning adventures, great depth, and unlimited freedom. Be a merchant or bounty hunter, buy a home, save the world!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/691830/header.jpg?t=1724976703', 0, 0, NULL);
INSERT INTO games VALUES (6414, 692100, 'Infliction', 'Wander through an interactive nightmare set within the confines of a once-happy household. Piece together the mystery behind a harrowing series of events while struggling to survive encounters with an entity that relentlessly stands in the way of finding absolution.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/692100/header.jpg?t=1603315422', 0, 0, NULL);
INSERT INTO games VALUES (6402, 692840, 'Underworld Ascendant', 'From the creative minds behind the System Shock, Thief and Underworld® series. Enter The Stygian Abyss, a dangerous, highly interactive dungeon world. Mix and match dozens of combat, stealth and magic skills to develop your own unique style of play. Become The Ascendant.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/692840/header.jpg?t=1623195185', 0, 0, NULL);
INSERT INTO games VALUES (6403, 692850, 'Bloodstained: Ritual of the Night', 'Bloodstained: Ritual of the Night is an exploration-focused, side-scroller action RPG by Koji Igarashi. Play as Miriam, an orphan scarred by an alchemist''s curse that slowly crystallizes her body. Battle through a demon-infested castle and defeat its master to save yourself, and all of humanity!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/692850/header.jpg?t=1749094828', 1, 0, NULL);
INSERT INTO games VALUES (6404, 692890, 'Roboquest', 'Roboquest is a fast FPS Roguelite in a scorched futureworld. You''re a rebooted Guardian, ready to kick some metal ass! Fight with your buddy or by yourself and annihilate hordes of deadly bots in ever-changing environments.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/692890/header.jpg?t=1748353552', 1, 0, NULL);
INSERT INTO games VALUES (6370, 693580, 'Goblins of Elderstone', 'This Goblin Tribe Simulator brings a challenging blend of chaos and creativity to the city-building genre. Build dwellings, manage your resources, defend your goblins, and grow your tribe to face other races and even the Gods! Do you have what it takes to control the chaos and rule the unruly?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/693580/header.jpg?t=1721192346', 1, 0, NULL);
INSERT INTO games VALUES (6353, 693700, 'Prime Mover', 'Retrace the path of the Prime Mover to uncover the story of the Byte of Burden! Prime Mover is an open-ended puzzle game about designing circuit boards.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/693700/header.jpg?t=1572339742', 0, 0, NULL);
INSERT INTO games VALUES (6339, 694280, 'Zombie Army 4: Dead War', 'Hitler’s hordes are back for more in this spine-chilling shooter from the makers of Sniper Elite 4! Abominable occult enemies, epic weapons and a harrowing new campaign for 1-4 players await in 1940s Europe, as you fight to save humankind from undead Armageddon!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/694280/header.jpg?t=1734452546', 1, 0, NULL);
INSERT INTO games VALUES (6348, 694500, 'Army Men RTS', 'Army Men RTS brings you back to the days of staging battles with tiny plastic soldiers in your backyard...except these green soldiers carry out your every command!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/694500/header.jpg?t=1568748488', 0, 0, NULL);
INSERT INTO games VALUES (6330, 694770, 'Vestaria Saga I: War of the Scions', 'A prince in flight, charged with defending the last of the royal family, determined to secure a future for his kingdom, unaware he would be fighting for stakes greater still.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/694770/header.jpg?t=1745568235', 0, 0, NULL);
INSERT INTO games VALUES (6321, 695050, 'Rain of Reflections: Set Free', 'Rain of Reflections is an atmospheric, dystopian adventure game with exploration and deep character interactions. Its turn-based strategic confrontations are uniquely centered around a motivation mechanic.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/695050/header.jpg?t=1572876316', 0, 0, NULL);
INSERT INTO games VALUES (38994, 695100, 'Smoke and Sacrifice', 'Smoke and Sacrifice sees Sachi, a mother forced to give up her son, adventure into a grotesque underworld on a quest that will lead her to a darker truth.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/695100/header.jpg?t=1747737518', 1, 0, NULL);
INSERT INTO games VALUES (138067, 695330, 'SEASON: A letter to the future', 'Leave home for the first time to collect memories before a mysterious cataclysm washes everything away. Ride, record, meet people, and unravel the strange world around you in this third-person meditative exploration game.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/695330/header.jpg?t=1705518574', 0, 0, NULL);
INSERT INTO games VALUES (6310, 695600, 'This Grand Life', 'A life simulator that leans heavily into the personal finance aspect. Pay taxes, take out mortgages, trade stocks, buy real estate, start businesses, or grind your way to victory as an employee.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/695600/header.jpg?t=1729213776', 0, 0, NULL);
INSERT INTO games VALUES (6282, 695920, 'Super Seducer : How to Talk to Girls', 'Learn state-of-the-art seduction secrets from the master himself, Richard La Ruina, in this incredibly valuable live action seduction simulator.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/695920/header.jpg?t=1667053258', 1, 0, NULL);
INSERT INTO games VALUES (6296, 696140, 'No Heroes Here', 'No Heroes Here is a frantic co-op game for 1 to 4 players, available in local and online modes. Craft and use several items effectively whilst coordinating your ragtag band of non-heroes to defend castles and survive! ...Oh, as well as saving the Kingdom in the meantime!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/696140/header.jpg?t=1726857314', 0, 0, NULL);
INSERT INTO games VALUES (6254, 696170, 'SENRAN KAGURA Peach Beach Splash', 'The buxom shinobi of SENRAN KAGURA are back, and they''ve traded their katanas for water guns in this Third-Person Splasher! Customize your team, lead them through battles across a sprawling single-player campaign, or go online and take on teams worldwide. Come on in; the water''s great!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/696170/header.jpg?t=1732061360', 1, 0, NULL);
INSERT INTO games VALUES (6255, 696180, 'Bullet Witch', 'An army of demons has driven humanity to the brink of extinction. The only thing standing in their way? A woman in black, with a long gun like a witch’s broom and magical powers to match. Mow down hordes of monsters and reignite the spark of mankind’s resistance!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/696180/header.jpg?t=1738970807', 0, 0, NULL);
INSERT INTO games VALUES (6257, 696220, 'Folklore Hunter', 'You are a hunter, world renowned for slaying supernatural beasts. Take on contracts and track down cryptids from all over the world. Gather resources, set traps, prepare your equipment, use your hunter instincts and hunt down the beast, before it hunts you.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/696220/header.jpg?t=1698226542', 0, 0, NULL);
INSERT INTO games VALUES (6262, 696370, 'BROKE PROTOCOL', 'A fully moddable city sandbox with jobs, NPCs, apartments, garages, gangs, and more. Broke Protocol is an open-world action game focused on roleplaying and custom content. Define your goals and identity in a persistent, reactive world where you write your own story.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/696370/header.jpg?t=1743996672', 0, 1, NULL);
INSERT INTO games VALUES (6267, 696480, 'The Norwood Suite', 'Explore the mysterious Hotel Norwood in this surreal first-person adventure. Curious characters, forgotten secrets, and head-nodding music await your arrival.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/696480/header.jpg?t=1741277937', 0, 0, NULL);
INSERT INTO games VALUES (6270, 696530, 'Lake Ridden', 'Lake Ridden is a story-driven, first-person puzzle game! A cozy supernatural adventure where you unravel a mysterious past, trying to find your sister. Luckily, you are not alone...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/696530/header.jpg?t=1588514919', 0, 0, NULL);
INSERT INTO games VALUES (6272, 696560, 'Bouncing Duck Simulator', 'Bouncing Duck Simulator allows you to fulfill your wildest dreams. Bouncing a rubber duck around, bouncing a pink rubber duck around, bouncing... more ducks? Don''t be shy, you gotta bounce them all!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/696560/header.jpg?t=1738927236', 0, 0, NULL);
INSERT INTO games VALUES (6237, 697550, 'It Lurks Below', 'It Lurks Below is an action-oriented, survival RPG in a randomly generated world. Fight through the massive underground dungeon, customize your character with random items and find out what evil lurks below.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/697550/header.jpg?t=1688951943', 0, 0, NULL);
INSERT INTO games VALUES (6207, 697650, 'The 25th Ward: The Silver Case', 'In the bayside area of Kanto, a murder with unknown motivations sets off a series of seemingly random events bringing together peculiar individuals, one of whom is detective Tokio Morishima. When their ambitions begin to collide, a truly shocking pattern emerges…', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/697650/header.jpg?t=1732662146', 0, 0, NULL);
INSERT INTO games VALUES (6215, 697860, 'Cathodemer', 'Cathodemer is a realtime video production instrument with a CRT display simulator. It features analog-style RGB signal oscillation synthesis, input source mixing and manipulation, recursive color shape synthesis, sprite animation engine and various classic video effects.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/697860/header.jpg?t=1581644537', 0, 0, NULL);
INSERT INTO games VALUES (6202, 698260, 'Star Shelter', 'Star shelter is a space survival game built from the ground up for VR. You are stranded in space, you must climb around in Zero-G, explore, scavenge, craft, hack and fight to survive. You have to build, arm and upgrade your own space station in order to escape the cosmic graveyard.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/698260/header.jpg?t=1593873292', 0, 0, NULL);
INSERT INTO games VALUES (6187, 698540, 'Dungeon Warfare 2', 'Become a dungeon lord to defend your dungeons with the deadliest of traps and insidious contraptions against greedy adventurers and wannabe heroes.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/698540/header.jpg?t=1735002223', 1, 0, NULL);
INSERT INTO games VALUES (6192, 698640, 'Deep Sky Derelicts', 'Deep Sky Derelicts is an original combination of turn-based strategy and RPG, enriched with tactical card combat and popular roguelike elements. Explore derelict alien ships, fight, loot and upgrade your gear, all in distinctive retro-futuristic comic book aesthetic style.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/698640/header.jpg?t=1721723774', 0, 0, NULL);
INSERT INTO games VALUES (6195, 698670, 'Scorn', 'Scorn is an atmospheric first-person horror adventure game set in a nightmarish universe of odd forms and somber tapestry.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/698670/header.jpg?t=1706178006', 1, 0, NULL);
INSERT INTO games VALUES (6196, 698700, 'Rise of the Third Power', 'Rise of the Third Power is a retro-themed, console-style roleplaying game, loosely based on the political climate of Europe in the late 1930''s. The story takes place in the land of Rin during the height of the Age of Sail, following the events that would lead to the greatest war in human history.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/698700/header.jpg?t=1678461958', 0, 0, NULL);
INSERT INTO games VALUES (6160, 698780, 'Doki Doki Literature Club!', 'The Literature Club is full of cute girls! Will you write the way into their heart? This game is not suitable for children or those who are easily disturbed.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/698780/header.jpg?t=1681943582', 0, 1, NULL);
INSERT INTO games VALUES (129225, 699130, 'World War Z', 'World War Z is a heart-pounding coop third-person shooter for up to 4 players featuring massive swarms of hundreds of zombies, focused on fast-paced, gruesomely spectacular action.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/699130/header.jpg?t=1733932481', 1, 0, NULL);
