INSERT INTO games VALUES (6177, 699180, 'Human-powered spacecraft', 'A nostalgia-infused pixel clicker in a comedy wrapper.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/699180/header.jpg?t=1730596795', 1, 0, NULL);
