INSERT INTO games VALUES (6158, 699600, 'PEG', 'Blue eats blue. Red eats red. Until one of each remains. A puzzler that is deceptively simple but hard to master.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/699600/header.jpg?t=1736570495', 1, 0, NULL);
