INSERT INTO games VALUES (6130, 700030, 'Life is Feudal: MMO', 'Experience the hardcore reality of the Middle Ages. Master survival, engage in deep-rooted RPG elements, navigate a bustling economy, build communities, and employ diplomatic strategy to thrive in Abella''s vast expanse.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/700030/header.jpg?t=1719250150', 1, 1, NULL);
INSERT INTO games VALUES (6112, 700160, 'Semblance', 'Semblance is an innovative platformer with deformable terrain, set in a beautiful minimalist world. It’s a game that asks, what if you could deform and reshape the world itself? Semblance takes the idea of a ‘platform’ in a platformer and turns it on its head.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/700160/header.jpg?t=1680797529', 1, 0, NULL);
