INSERT INTO games VALUES (6032, 701870, 'Swarm Queen', 'Swarm Queen is a quick-to-learn but tactical and challenging tug-of-war strategy game about insectoid aliens trying to murder each other.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/701870/d818e138c949d1ebcbb2f73a3e72de5d1d244de3/header.jpg?t=1745895584', 0, 0, NULL);
INSERT INTO games VALUES (38729, 702050, 'The Song of Saya', 'Bear witness to a love that will change the world, in this classic horror romance visual novel from acclaimed writer Urobuchi Gen.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/702050/header.jpg?t=1730127388', 0, 0, NULL);
INSERT INTO games VALUES (6046, 702110, 'THE LAST BLADE 2', 'This widely revered NEOGEO masterpiece is finally available on STEAM! Not only a perfect port of the original game, the STEAM version of THE LAST BLADE 2 will allow players from across the globe to fight against each other online / locally in epic battles in online Multiplayer Mode.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/702110/header.jpg?t=1727159656', 0, 0, NULL);
INSERT INTO games VALUES (6047, 702120, 'THE KING OF FIGHTERS ''97 GLOBAL MATCH', 'KOF ’97 is the final entry in the Orochi Saga, the original storyline of the KOF series, which is still played by enthusiastic fans around the world. KOF ’97 makes a return with new features such as online matchmaking, a new gallery mode, and custom menu BGM settings!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/702120/header.jpg?t=1727160211', 0, 0, NULL);
INSERT INTO games VALUES (6028, 702670, 'Donut County', 'Donut County is a story-based physics puzzle game where you play as an ever-growing hole in the ground. Meet cute characters, steal their trash, and throw them in a hole.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/702670/header.jpg?t=1729099497', 1, 0, NULL);
INSERT INTO games VALUES (6029, 702680, 'Wattam', 'Wattam is a game about the joys of friendship and discovery, from the imagination of Keita Takahashi (creator of Katamari Damacy and Noby Noby Boy) and developer Funomena.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/702680/header.jpg?t=1729099524', 1, 0, NULL);
