INSERT INTO games VALUES (140528, 703080, 'Planet Zoo', 'Build a world for wildlife in Planet Zoo. From the developers of Planet Coaster and Zoo Tycoon comes the ultimate zoo sim. Construct detailed habitats, manage your zoo, and meet authentic living animals who think, feel and explore the world you create around them.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/703080/header.jpg?t=1745397696', 1, 0, NULL);
INSERT INTO games VALUES (6003, 703320, 'Hidden & Dangerous 2: Courage Under Fire', 'Hidden &amp; Dangerous 2 is a first and third person tactical shooter that builds upon the tremendous success of Hidden &amp; Dangerous. You lead a small squad of Allied soldiers deep behind enemy lines, to carry out secret missions during World War II.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/703320/header.jpg?t=1568749287', 0, 0, NULL);
INSERT INTO games VALUES (6010, 703510, 'Wooden Battles', 'Build a wooden fort, place your units, watch the mayhem!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/703510/header.jpg?t=1728248978', 0, 0, NULL);
INSERT INTO games VALUES (5982, 703840, 'Animal Super Squad', 'Animal Super Squad is a physics-based adventure game that lets you play as your favorite animal. Speed through a world full of dangers and bananas. Create your own levels, share them with the community, or forget all that nonsense and just play other people’s stuff.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/703840/header.jpg?t=1592321907', 0, 0, NULL);
