INSERT INTO games VALUES (5963, 704030, 'Professional Farmer: Cattle and Crops', 'Professional Farmer: Cattle and Crops takes you out into the countryside and impresses with its depth and attention to detail! Experience how exciting the profession of a farmer can be. Work your fields with original machines or coordinate these tasks with your workers.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/704030/header.jpg?t=1710754767', 0, 0, NULL);
INSERT INTO games VALUES (5971, 704270, 'Generation Zero®', 'Generation Zero is a stealth-action shooter where you wage guerilla warfare against lethal mechanical enemies. Explore a vast open world map inspired by the Swedish Cold War era, take part in the resistance alone or with up to three friends in seamless co-op.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/704270/header.jpg?t=1733993638', 0, 0, NULL);
