INSERT INTO games VALUES (5947, 704360, 'SACRALITH : The Archer''s Tale', 'SACRALITH: The Archer''s Tale is a VR bow-and-arrow shooter. Help your AI companions as you pass various locations together toward the game''s main goal: the magic stone called Sacralith that grants you power over dragons.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/704360/header.jpg?t=1586630333', 0, 0, NULL);
INSERT INTO games VALUES (5950, 704450, 'Neverwinter Nights: Enhanced Edition', 'Return to the Forgotten Realms in this bestselling Dungeons &amp; Dragons roleplaying game. Combines all the content of Neverwinter Nights Diamond Edition with all-new enhanced features. Includes 100+ hours of award-winning adventures and the tools to create your own!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/704450/header.jpg?t=1746124805', 0, 0, NULL);
INSERT INTO games VALUES (5953, 704510, 'Mercury Fallen', 'A sci-fi colony management sim with a focus on exploration, expansion, and survival. Rebuild your underground facility, manage colonists and robots, and uncover the mysteries of an alien world light-years from Earth. Dig deep, expand across the surface, and shape your new home.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/704510/header.jpg?t=1740434366', 0, 0, NULL);
INSERT INTO games VALUES (5955, 704640, 'Evolution of Ages: Settlements', 'Evolutiuon of Ages is a game of managing resources in the ruins of our world. Recruit characters and level their skills and equipment from the stone age until the space age, while trying your best to avoid the very thing that led to our destruction previously.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/704640/header.jpg?t=1591971058', 0, 0, NULL);
INSERT INTO games VALUES (5925, 704860, 'Keepsake', 'Keepsake was a labor of love developed 10 years ago by us as an independent studio. For its anniversary, we thought it would be great to see it live again on steam and gain a new following, as we feel that it is still relevant today.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/704860/header.jpg?t=1543945622', 0, 0, NULL);
INSERT INTO games VALUES (5940, 705120, 'Death Coming/死神来了', '''Death Coming'' is a non-linear puzzle game where you must harvest human souls ‘Final Destination’ style. However, pesky mortals are not your only problem, as the Agents of Light will do everything they can to stop you.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/705120/header.jpg?t=1641371368', 1, 0, NULL);
INSERT INTO games VALUES (5902, 705280, 'Hakoniwa Explorer Plus', 'Get ready for a voxel art action game featuring an unprecedented level of freedom! A whole range of cute girl monsters are waiting to punch, kick, wrap you up, suck your blood, and eat you right up.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/705280/header.jpg?t=1671601709', 0, 0, NULL);
INSERT INTO games VALUES (5903, 705290, 'Strange Telephone', 'Strange Telephone is a 2D adventure game in which the player explores strange worlds created with merely 6 digits, and has multiple endings.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/705290/header.jpg?t=1576210954', 0, 0, NULL);
INSERT INTO games VALUES (5895, 706020, 'Fade to Silence', 'Fade to Silence is a single-player and co-op survival adventure set in a post-apocalyptic world that is frozen in an eternal winter. Snow and ice have shaped a merciless landscape. Nature is corrupted. Monstrous creatures out of an Eldritch horror dream roam the frozen wasteland.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/706020/header.jpg?t=1602757610', 0, 0, NULL);
INSERT INTO games VALUES (5880, 706560, 'Jimmy and the Pulsating Mass', 'One day, Jimmy looked inside.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/706560/header.jpg?t=1719548889', 0, 0, NULL);
INSERT INTO games VALUES (139848, 707010, 'Will To Live Online', 'Will To Live is a MMORPG-shooter whose action takes place in a severe post-apocalyptic world. Explore the world, engage in fights with mutants and other survivors, join the clans in the struggle for existence and prove your right to Live.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/707010/header.jpg?t=1734421809', 0, 1, NULL);
INSERT INTO games VALUES (38533, 707030, 'POSTAL 4: No Regerts', 'POSTAL 4: No Regerts is a satirical and outrageous comedic open world first person shooter and the long-awaited true sequel to what’s been fondly dubbed as &quot;The Worst Game Ever™&quot;, POSTAL 2!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/707030/header.jpg?t=1726332007', 0, 0, NULL);
INSERT INTO games VALUES (5844, 707300, 'Hatsune Miku VR', 'World-famous virtual singer Hatsune Miku invites you to join her on stage in in this VR music game! Aim for a perfect score as she sings and dances to some of her most iconic songs.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/707300/header.jpg?t=1681245769', 1, 0, NULL);
