INSERT INTO games VALUES (5811, 708580, 'The Exorcist: Legion VR - Chapter 1: First Rites', 'The Exorcist: Legion VR is an episodic VR experience set in the academy-award winning world created by horror maestro William Peter Blatty. Each chapter features a unique demonic entity that will test your courage and resolve. Available for HTC Vive and Oculus Rift. Not for the faint-hearted.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/708580/header.jpg?t=1585770303', 0, 0, NULL);
