INSERT INTO games VALUES (5733, 710230, 'Urban Strife', 'Old school TBS, post-apoc survival and RPG. Recruit deranged locals in your militia, ally local factions and fight those you hate. Haul loot back and rebuild your shelter, doctor your wounds, and fix your guns. People need feeding, booze needs brewing and there is an end of the world to enjoy.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/710230/header.jpg?t=1748299221', 0, 0, NULL);
INSERT INTO games VALUES (5739, 710470, 'Little Witch Academia: Chamber of Time', 'Uncover the mysteries at Luna Nova Academy and experience the magical world of Studio Trigger style Japanese animation in Little Witch Academia: Chamber of Time.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/710470/header.jpg?t=1630582197', 0, 0, NULL);
INSERT INTO games VALUES (5704, 710610, 'Don''t Sink', 'Capture islands, sink ships, defend your towns, and discover an exciting world full of adventure.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/710610/header.jpg?t=1681142428', 0, 0, NULL);
INSERT INTO games VALUES (5712, 710710, 'Pizza Game', 'Every boy have a secret. One of them is bones.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/710710/header.jpg?t=1567933102', 0, 0, NULL);
