INSERT INTO games VALUES (5317, 720250, 'Welcome to the Game II', 'Welcome to the Game II is an atmospheric horror / strategy / puzzle game that takes you into the world of the deep web in search of the shadow web. Play as an investigative reporter trying to solve a case of a mysterious woman broadcasting for help as masked men are on the hunt to kill her.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/720250/header.jpg?t=1596752454', 0, 0, NULL);
INSERT INTO games VALUES (5319, 720280, 'Fox Hime', 'Yan is a college student with a special guardian girl named Mori at his side. &quot;If my girlfriend is as beautiful as Mori, then my life must be blessed by the gods...&quot; Unknowingly, another girl is entering his life...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/720280/header.jpg?t=1733127648', 0, 0, NULL);
INSERT INTO games VALUES (5324, 720350, 'Mundaun', 'Mundaun is a lovingly hand-penciled horror tale set in a dark, secluded valley of The Alps. Explore various areas full of secrets to discover, survive hostile encounters, drive vehicles, fill your inventory, and solve a variety of handcrafted puzzles.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/720350/header.jpg?t=1709316632', 1, 0, NULL);
INSERT INTO games VALUES (5330, 720560, 'Vigil: The Longest Night', 'Embark on a journey through the longest night with Leila, a valiant member of the Vigilant Order. Delve into the hidden truths shrouded in eternal darkness, unravel the mystery surrounding Leila''s enigmatic sister, and confront the eldritch horrors lurking in a world that has lost the light of day.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/720560/header.jpg?t=1740983178', 1, 0, NULL);
INSERT INTO games VALUES (130749, 720620, 'TaleSpire', 'TaleSpire is a beautiful way to play pen and paper RPGs online. Bring your stories to life and embark upon campaigns together with your friends, regardless of where you are in the world.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/720620/header.jpg?t=1729261244', 0, 0, NULL);
INSERT INTO games VALUES (37984, 721180, 'Dustborn', 'Ragtag crew? Check. Musical gear? Check. Tour bus and robot driver? Check. Stolen package? Check! Embark on a perilous road-trip across a Divided States of America. Use the power of words to shape relationships with your crew, get out of trouble and reach your final destination.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/721180/header.jpg?t=1741774338', 0, 0, NULL);
INSERT INTO games VALUES (5306, 721700, 'Holomento', 'Holomento is an Indie Permadeath Action-RPG focusing on the dangerous quest of passing through the mysterious Eventide Hollow – and rebuilding it step by step.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/721700/header.jpg?t=1726567856', 0, 0, NULL);
INSERT INTO games VALUES (5270, 722060, 'Dominions 5 - Warriors of the Faith', 'In Dominions 5 you take control of a powerful being that rules a nation and aspires to godhood. The type of Pretender Gods can vary from magically powerful arch mages to huge titans or large monuments. Dominions is a deep 4x turn based strategy game with a very large variety of spells and units.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/722060/header.jpg?t=1667484710', 0, 0, NULL);
INSERT INTO games VALUES (5272, 722180, 'SURV1V3', 'Forget what you have played so far, SURV1V3 is a unique realistic zombie survival fps game expressly designed for VIRTUAL REALITY that will let you test your survival skills. Play the thrilling story in single mode or coop with your friends (up to 4 players) and survive the apocalypse!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/722180/header.jpg?t=1668208940', 0, 0, NULL);
INSERT INTO games VALUES (5259, 722560, 'RAD', 'RAD is a 3D action rogue-like set in a post-post-apocalyptic world, where humanity has faced armageddon not once, but twice.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/722560/header.jpg?t=1612913061', 0, 0, NULL);
INSERT INTO games VALUES (37950, 722730, 'Cogmind', 'Cogmind is a sci-fi roguelike epic in which you play a robot building yourself from components found or salvaged from other robots. Explore a living, breathing world through turn-based tactical combat, or sneak, hack, and fly your way to victory.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/722730/header.jpg?t=1747025130', 0, 0, NULL);
INSERT INTO games VALUES (139589, 722960, 'CASE 2: Animatronics Survival', 'CASE 2: Animatronics Survival is a horror game that is available in two modes. Online mode lets one or more players take on the role of animatronics, ready to crush everyone and everything. The other three are survivors. How did this happen? You’ll have to find out!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/722960/header.jpg?t=1698422457', 1, 0, NULL);
INSERT INTO games VALUES (5230, 723270, 'Rumu', 'Rumu is an intimate, narrative-driven adventure that follows the path into sentience of a robot vacuum cleaner.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/723270/header.jpg?t=1719898076', 0, 0, NULL);
INSERT INTO games VALUES (5236, 723390, 'Hunt Down The Freeman', 'Just another mission, or so you thought… until aliens from another dimension start invading Earth before a scientist with a crowbar hospitalizes you after wiping out your entire squad. Just when you thought you were finished, a man with a briefcase offers you the chance for another beginning.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/723390/header.jpg?t=1682529968', 0, 0, NULL);
INSERT INTO games VALUES (5192, 724250, 'Princess Maker 5', 'Discover magic in our world with Princess Maker 5! A lone princess needs your care in a realm where fantasy meets reality. Guide her growth and shape her destiny. Create unforgettable memories as you raise her.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/724250/header.jpg?t=1728628113', 1, 0, NULL);
INSERT INTO games VALUES (5195, 724300, 'Roof Rage', 'Roof Rage is a Martial Arts Platform Fighter featuring epic rooftop battles. Play with up to 8 players locally or 1vs1 online.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/724300/header.jpg?t=1735479476', 1, 0, NULL);
INSERT INTO games VALUES (5203, 724470, 'Lazy Galaxy', 'Lazy Galaxy is a mix between RTS and idle/clicker game. Lead an evil (albeit lazy) alien race to conquer the universe!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/724470/header.jpg?t=1708453688', 1, 0, NULL);
INSERT INTO games VALUES (5184, 724740, 'Lines X', 'Beautiful &amp; relaxing Numberlink puzzles.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/724740/header.jpg?t=1646329023', 1, 0, NULL);
INSERT INTO games VALUES (5170, 724970, '神舞幻想 Faith of Danschant', 'A 3D ancient and fantasy RPG console game is created by Beijing Joyfun. Users will have a fabulous adventure and start their own legend in a fictional world based China’s traditional mythology.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/724970/header.jpg?t=1632301868', 0, 0, NULL);
INSERT INTO games VALUES (5155, 725270, 'Necrobarista', 'In a back-alley cafe, the dead are granted one last night to mingle with the living. Necrobarista follows a dynamic and diverse cast of characters as they navigate Melbourne''s hipstery coffee culture, the questionable ethics of necromancy, and the process of letting go.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/725270/header.jpg?t=1646642086', 1, 0, NULL);
INSERT INTO games VALUES (5158, 725330, 'Zelle', 'Zelle is a occult adventure game. You can explore the inside and outside of the castle using adventure game mechanics and battle demons with strategic mouse clicks. Your goal in this game is to bring the protagonist home.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/725330/header.jpg?t=1590748792', 1, 0, NULL);
INSERT INTO games VALUES (5139, 725480, 'Slap City', 'Slap City is a Seriously Fun platform fighter with a perfect mix of characters from the Ludosity universe. Play Locally or Online. Slap it hard in Ranked or fast and loose in Slap Ball game mode. We are the original inventors of Clutch Technology.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/725480/header.jpg?t=1670503996', 0, 0, NULL);
INSERT INTO games VALUES (5120, 725780, 'Play With Me: Escape Room', 'See how a game created by the very Jigsaw would look like! Use the available objects, outwit tricky illusions and optical puzzles and above all, answer the question – will you dare to Play with Me?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/725780/header.jpg?t=1749467209', 1, 0, NULL);
INSERT INTO games VALUES (5136, 726110, 'Overcrowd: A Commute ''Em Up', 'Design and build the most efficient metro stations known to man! Excavate. Expand. Set staff priorities. And manage the commuter flow. Overcrowd is a 2.5D management/tycoon/simulator set below the bustling city of Lubdon Town.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/726110/header.jpg?t=1723628048', 1, 0, NULL);
INSERT INTO games VALUES (5096, 726200, 'Hostil', 'Hostil is a short emotional interactive tale about a young astronaut who has crashed on a extremely dangerous planet. No one will come to rescue him and his only hope is to move forward.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/726200/header.jpg?t=1676114194', 0, 0, NULL);
INSERT INTO games VALUES (5098, 726250, 'Unknightly', 'Unknightly is a medieval VR stealth game designed from the ground up for virtual reality. You assume the role of a retired master-thief as he is drawn back into a life once thought left behind.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/726250/header.jpg?t=1603807702', 0, 0, NULL);
INSERT INTO games VALUES (5104, 726360, 'BOOBS SAGA: Prepare To Hentai Edition', 'Imagine that you''re a young woman with some tasty curves; and it can only mean one thing - you''re a perfect sacrifice to the Boobs King! Avoid traps, fight monsters or hide from them, solve puzzles, dance. And remember: the main goal is to save your BOOBS! Boobs Saga - is a satirical action.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/726360/header.jpg?t=1728283927', 0, 0, NULL);
INSERT INTO games VALUES (5117, 726590, 'NBA 2K Playgrounds 2', 'NBA arcade action is back with NBA 2K Playgrounds 2! Pick your team, get ready to jam, and Ball Without Limits!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/726590/header.jpg?t=1609970621', 1, 0, NULL);
INSERT INTO games VALUES (5087, 726830, 'Vacation Simulator', 'The latest VR sensation from the creators of ‘Job Simulator’, now with free DLC! Welcome to Vacation Simulator: a rough approximation of VACATION inspired by real human NOT JOBBING. Reallocate your bandwidth and get ready to splash, s’more, snowball, and selfie your way to optimal relaxation.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/726830/header.jpg?t=1710255671', 0, 0, NULL);
INSERT INTO games VALUES (132343, 726840, 'City Game Studio: Your Game Dev Adventure Begins', 'Manage a game studio from the dawn of the gaming industry in 1976. Your journey starts with small indie titles and grows into a gaming empire. Develop, design, and conquer the industry. From humble beginnings to gaming legend – it’s your story, your studio, your legacy!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/726840/header.jpg?t=1745416045', 1, 0, NULL);
INSERT INTO games VALUES (5059, 727130, 'Between the Stars', 'Become the Captain of an interstellar cruiser and journey across the galaxy to save the Republic. During your journey you will have to make important decisions, improve the weaponry of your ship and fight against numerous enemies.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/727130/header.jpg?t=1734604471', 0, 0, NULL);
INSERT INTO games VALUES (5034, 727570, 'After the Collapse', 'ATC is a base building game set in a post-apocalyptic world featuring urban environments. Build a base across several layers with dozens of survivors. Fight other factions for the control of the remaining production centers and explore the world to find long forgotten resources and technologies.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/727570/7e5219f89c8bb23ea6f010254cbde66fc74789b2/header.jpg?t=1747848787', 0, 0, NULL);
INSERT INTO games VALUES (5045, 727850, 'ELDERBORN', 'ELDERBORN - a Metal AF* Slasher with brutal FPP melee combat and souls-like/RPG character progression. In the times of legend, barbarian tribes need a new dark messiah. Be that merciless slayer. Uncover ancient secrets in the city of doom. Forge your own destiny! *Action Fantasy.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/727850/header.jpg?t=1740582228', 1, 0, NULL);
INSERT INTO games VALUES (5048, 727910, 'Titanic: The Experience', 'Experience the Titanic in all of its glory, witness the iceberg collision and the sinking of the most famous ocean liner. Relive that fateful night on April 14th 1912 and experience what that night was like.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/727910/header.jpg?t=1638774361', 0, 0, NULL);
INSERT INTO games VALUES (5031, 728240, 'Adventure Time: Pirates of the Enchiridion', 'Ahoy! The Land of Ooo is underwater and it’s up to Finn and Jake to find out why. Join our heroes as they explore the high seas, search for hidden clues, interrogate shady suspects and fight pirates to solve the mystery and save their waterlogged world!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/728240/header.jpg?t=1669902198', 0, 0, NULL);
