INSERT INTO games VALUES (4998, 729000, 'Wytchwood', 'Wytchwood is a crafting adventure game set in a land of gothic fables and fairytales. As the old witch of the woods, explore a strange countryside, collect magic ingredients, brew sorcerous spells, and pass judgement upon a capricious cast of characters.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/729000/header.jpg?t=1705693631', 1, 0, NULL);
INSERT INTO games VALUES (5000, 729040, 'Borderlands Game of the Year Enhanced', 'Discover the original co-op shooter-looter, crammed with new enhancements! As one of 4 trigger-happy mercenaries with RPG progression, equip bazillions of guns to take on the desert planet Pandora.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/729040/header.jpg?t=1728609218', 0, 0, NULL);
INSERT INTO games VALUES (4971, 730050, 'Verdant Skies', 'Verdant Skies is a life simulation game born from a love for games like Harvest Moon and a desire to create something unique with modern gameplay and deep storytelling. Ensure the success of the colony as you make friends and pursue romance with a diverse cast of characters.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/730050/header.jpg?t=1736896480', 0, 0, NULL);
INSERT INTO games VALUES (4952, 730310, 'DYNASTY WARRIORS 9', 'Experience the thrill of one versus thousands in an all new open world setting with DYNASTY WARRIORS 9! Travel through Ancient China depicted on a single, vast, open-world map, master the new State Combo System, and watch the Three Kingdoms story unfold through a cast of 90 playable characters!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/730310/header.jpg?t=1748480390', 1, 0, NULL);
