INSERT INTO games VALUES (4939, 730820, 'The Curse of Monkey Island', 'The only pirate adventure that asks the question: What''s sharper, your sword or your wit?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/730820/header.jpg?t=1683094733', 0, 0, NULL);
INSERT INTO games VALUES (4940, 730830, 'Escape from Monkey Island™', 'Fourth in the legendary Monkey Island series of graphic adventures!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/730830/header.jpg?t=1741736369', 0, 0, NULL);
INSERT INTO games VALUES (4941, 730840, 'Burger Shop', 'Make burgers, shakes and more in this exciting food-making game that has been enjoyed by millions of fans everywhere.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/730840/header.jpg?t=1730763662', 1, 0, NULL);
