INSERT INTO games VALUES (37614, 731040, 'The Invincible', 'Rethink human’s dominion in The Invincible: a story-driven adventure set in a hard sci-fi world by Stanisław Lem. Discover planet Regis III as scientist Yasna, use atompunk tools looking for a missing crew and face unforeseen threats. Make choices in a philosophical story that’s driven by science.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/731040/header.jpg?t=1745409303', 0, 0, NULL);
INSERT INTO games VALUES (4900, 731490, 'Crash Bandicoot™ N. Sane Trilogy', 'Your favorite marsupial, Crash Bandicoot™, is back! He’s enhanced, entranced and ready-to-dance with the N. Sane Trilogy. Relive all your favorite moments in Crash Bandicoot™, Crash Bandicoot™ 2: Cortex Strikes Back and Crash Bandicoot™ 3: Warped, now in fully-remastered graphical glory!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/731490/header.jpg?t=1742399696', 0, 0, NULL);
INSERT INTO games VALUES (4886, 731920, 'Government Simulator', 'Government Simulator is a is a simple economic and political simulation game based on real-world data. Take control of a whole country, like the USA, Germany, France, Russia, or Austria. Change laws, taxes and budgets based on real world statistics and data, and see what happens.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/731920/header.jpg?t=1567514420', 0, 0, NULL);
INSERT INTO games VALUES (37590, 732050, 'Voxel Tycoon', 'Voxel Tycoon — a management sim set in the infinite voxel world. Mine resources and process them into goods on your custom factories. Set up supply chains and passenger routes with a huge fleet of trains, trucks, and buses, and turn small towns into prosperous megacities with a thriving economy!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/732050/header.jpg?t=1720810923', 1, 0, NULL);
INSERT INTO games VALUES (4897, 732240, 'SpaceBourne', 'Spacebourne is an open space exploration game with Rpg elements. Its world consists of different factions at war. You as an expert pilot need to choose your side or be on no one''s side and create a force of your own. Load up your weapons, Ready your ship and warp to adventure.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/732240/header.jpg?t=1595077678', 0, 0, NULL);
INSERT INTO games VALUES (4872, 732370, 'Juicy Realm', 'Juicy Realm is a roguelike game in which players must square off against bizarre fruits all across the world. The line between the animal and the plant world has become blurred, and the food chain has been completely disrupted.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/732370/header.jpg?t=1644166479', 1, 0, NULL);
INSERT INTO games VALUES (4875, 732430, 'Superflight', 'Superflight is an intense, easy to learn wingsuit game with an infinite number of beautiful procedurally generated maps. A great game to relax for half an hour and chase your latest highscore!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/732430/header.jpg?t=1691583493', 0, 0, NULL);
