INSERT INTO games VALUES (4863, 733050, 'Lines Infinite', 'Beautiful &amp; relaxing Numberlink puzzles.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/733050/header.jpg?t=1646329039', 1, 0, NULL);
INSERT INTO games VALUES (4865, 733070, 'Sudoku Universe / 数独宇宙', 'Making the best Sudoku game on Steam.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/733070/header.jpg?t=1646329044', 1, 0, NULL);
INSERT INTO games VALUES (4866, 733110, '8-Bit Adventures 2', 'Pilot your Airship, prepare your party, and explore a vast World Map in 8-Bit Adventures 2 – an exciting, emotional tribute to the Golden Age of JRPGs. Dynamic turn-based battles &amp; pixels with personality!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/733110/header.jpg?t=1737025215', 0, 0, NULL);
INSERT INTO games VALUES (4868, 733210, 'Neversong', 'Help little Peet hack-and-slash his way through a beautifully haunting coma. A hand-drawn action-adventure through a dreamy world filled with fleshy monsters, insane grown-ups, and sad children looking for their mommies.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/733210/header.jpg?t=1733168966', 1, 0, NULL);
INSERT INTO games VALUES (4829, 733300, 'My Big Sister', 'My name is Luzia...and this story isn''t about me, it’s about my sister. Do you still wish to hear it?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/733300/header.jpg?t=1748876453', 0, 0, NULL);
INSERT INTO games VALUES (4830, 733340, 'Hakuoki: Edo Blossoms', 'Continue your journey to Edo in Hakuoki™: Edo Blossoms, where you play as the heroine Chizuru Yukimura. Romance the famous warriors of the Shinsengumi as you enter a fantasy drama of battles and self-discovery. Your narrative choices unlock multiple branching storylines and 30 different endings!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/733340/header.jpg?t=1730839510', 0, 0, NULL);
