INSERT INTO games VALUES (4816, 733790, 'Not Tonight', 'Person of European Heritage #112: Welcome to Relocation Block B, your new home. Your designated role is ''Bouncer''. Work hard, stay out of trouble, and we might let you stay in the UK.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/733790/header.jpg?t=1728054964', 0, 0, NULL);
INSERT INTO games VALUES (4817, 733800, 'Frosty Nights', 'Frosty Nights is a First Person hybrid horror game that focuses on atmosphere and suspense.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/733800/header.jpg?t=1717081709', 0, 0, NULL);
INSERT INTO games VALUES (4824, 733990, 'I Can''t Believe It''s Not Gambling', 'Do you love opening loot crates, but hate the tedious gameplay sessions in between? Our marketing department has the game for you! Unbox random items! Get stuff, but not what you really want! Skate legal and ethical lines! Remember kids, its only a video game, so grab your parents credit card!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/733990/header.jpg?t=1727115028', 0, 0, NULL);
INSERT INTO games VALUES (4828, 734120, 'Bonbon', 'A thirty-minute childhood-horror walking-sim about toys and a giant rat. A short, single-sitting experience.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/734120/header.jpg?t=1714573833', 0, 0, NULL);
INSERT INTO games VALUES (4802, 734920, 'MEANDERS', 'MEANDERS is a sparkling adventure through a series of funny and relaxing challenges in a colourful setting.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/734920/header.jpg?t=1569935305', 0, 0, NULL);
INSERT INTO games VALUES (4787, 735280, 'EMERGENCY 20', 'Coordinate your team of first responders in the anniversary edition of EMERGENCY! Featuring 10 remastered classic EMERGENCY missions and three full campaigns, EMERGENCY 20 is the complete package for both experienced and new rescue commanders!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/735280/header.jpg?t=1667223561', 0, 0, NULL);
INSERT INTO games VALUES (4788, 735290, 'Genesis Noir', 'A noir adventure spanning time and space. When a love triangle between cosmic beings becomes a bitter confrontation, you''ll witness a gunshot fired by a jealous god—otherwise known as The Big Bang. Jump into the expanding universe and search for a way to destroy creation and save your love.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/735290/header.jpg?t=1726269785', 1, 0, NULL);
INSERT INTO games VALUES (4790, 735350, 'Bottle: Pilgrim Redux', 'Bottle: Pilgrim is a story of loss, regret and redemption, which reminds us that while we cannot change the things we have done, we can always learn from our mistakes.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/735350/header.jpg?t=1728895560', 0, 0, NULL);
INSERT INTO games VALUES (4777, 735580, '11-11 Memories Retold', '11th November 1916, a young photographer leaves Canada to join the western front in Europe. The same day, a German technician is told that his son is missing in action. Both want to preserve their humanity and come back alive to their loved ones.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/735580/header.jpg?t=1687265453', 0, 0, NULL);
INSERT INTO games VALUES (4763, 736190, 'Chinese Parents', 'In this casual sim set in China, you step into the shoes of an average kid from birth towards the end of your high school. Study hard, have fun, make friends and face your ultimate challenge, the “Gaokao”. What will your life be after that? And when you have a child, will you be a Tiger Parent?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/736190/header.jpg?t=1720164674', 0, 0, NULL);
INSERT INTO games VALUES (4765, 736220, 'Squad 44', 'Team up and join the frontline in Squad 44, the most authentic tactical WW2 shooter. Experience ruthless realism with an immense arsenal of faithfully recreated weapons and vehicles across massive WW2 battlefields.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/736220/header.jpg?t=1739990879', 0, 0, NULL);
INSERT INTO games VALUES (4741, 736260, 'Baba Is You', 'Baba Is You is a puzzle game where the rules you have to follow are present as blocks you can interact with. By manipulating them, you can change how the game works, repurpose things you find in the levels and cause surprising interactions!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/736260/header.jpg?t=1747950287', 1, 0, NULL);
INSERT INTO games VALUES (4753, 736570, 'The Crooked Man', 'There was a crooked man, and he walked a crooked mile... This is the first title in the series known as The Strange Man, developed by Uri Games. Experience the myriad horrors awaiting David as he moves into his new house.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/736570/header.jpg?t=1735192097', 1, 0, NULL);
INSERT INTO games VALUES (4729, 736810, 'The Raven Remastered', 'London, 1964. An ancient ruby is stolen from the British Museum. At the crime scene: a raven feather. Is somebody trying to follow in the footsteps of The Raven, the legendary master thief who disappeared years before?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/736810/header.jpg?t=1725012456', 0, 0, NULL);
INSERT INTO games VALUES (137251, 736820, 'Knights of Honor II: Sovereign', 'Become the king and fight over Europe in this fresh take on medieval real-time grand strategy. Manage provinces, gather armies, initiate diplomacy, and dabble in espionage. The path is open: become the true Sovereign of your people and bring them to glory.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/736820/header.jpg?t=1725000879', 1, 0, NULL);
INSERT INTO games VALUES (4732, 736850, 'We. The Revolution', 'As a judge of the Revolutionary Tribunal, preside over complicated cases of ordinary citizens, dangerous criminals, and enemies of the revolution in revolutionary Paris. Make judgments, plot political intrigue, and try to not lose your own head!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/736850/74689d1844373b54577f002dae32597b4d600088/header.jpg?t=1742230864', 0, 0, NULL);
INSERT INTO games VALUES (4714, 737520, 'Flynn: Son of Crimson', 'Our valiant hero Flynn possesses the ability to influence a mysterious energy and modify his style of combat, transforming him into a force to be reckoned with. Inspired by the golden age of the SNES, Flynn: Son of Crimson is the 2D action adventure that’ll take you right back to the 90s!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/737520/header.jpg?t=1657279781', 1, 0, NULL);
INSERT INTO games VALUES (4699, 737890, 'Catastronauts', 'Can you deal with unrelenting disaster and hold your ship together long enough to destroy the enemy invaders? Repair systems, extinguish fires, arm the torpedoes, avoid deadly solar flares, destroy your friends and clone them back again; it''s all in the life of a Catastronaut!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/737890/header.jpg?t=1667224374', 0, 0, NULL);
INSERT INTO games VALUES (4657, 738520, 'Breathedge', 'Survive in outer space! Together with your immortal chicken, discover the truth behind your sudden spaceship crash. Craft tools, pilot vehicles, and even control space stations to survive and explore the wreckage.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/738520/header.jpg?t=1746537136', 1, 0, NULL);
INSERT INTO games VALUES (4658, 738530, 'New Gundam Breaker', 'Collect Gunpla parts with friends, and make the ultimate Gundam! Defeat your enemies with your Gunpla model, collect their parts, and use them to make and battle with your own custom Gundam in this all-new Gunpla action game!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/738530/header.jpg?t=1691057875', 1, 0, NULL);
INSERT INTO games VALUES (4659, 738540, 'Tales of Vesperia: Definitive Edition', 'Celebrate the 10th anniversary of Tales of Vesperia and the return of this fan-favorite with the Definitive Edition!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/738540/header.jpg?t=1701311642', 1, 0, NULL);
INSERT INTO games VALUES (4660, 738550, 'Spike Volleyball', 'Spikes, blocks, floaters… Master the skills and tactics of indoor volleyball! With 50 men''s and women''s national teams, Spike Volleyball draws you deep into the realistic action of one of the most complex and spectacular team sports played today.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/738550/header.jpg?t=1725291174', 1, 0, NULL);
INSERT INTO games VALUES (4665, 738610, 'Train Station Simulator', 'Train Station Simulator is a station builder and manager game. Create and maintain your dream station! Ride the rails and operate your ultimate grand central empire!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/738610/header.jpg?t=1666961895', 0, 0, NULL);
INSERT INTO games VALUES (4646, 739080, '9 Monkeys of Shaolin', 'The true rebirth of iconic beat ''em up genre in vein of old-school video games! As a simple Chinese fisherman Wei Cheng you have to avenge the death of your friends and family slaughtered in a pirate raid at your peaceful village.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/739080/header.jpg?t=1749470865', 0, 0, NULL);
INSERT INTO games VALUES (4648, 739130, 'The Executioner', 'The Executioner puts you in the shoes of a man who tortures people for a living while trying to retain his own sanity. In this game the monster isn’t lurking behind you. You are the monster, if you choose to become one.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/739130/header.jpg?t=1638527469', 0, 0, NULL);
INSERT INTO games VALUES (4651, 739190, 'AntVentor', 'AntVentor is a point &amp; click adventure game. You find yourself in a photorealistic macroworld where you immediately manage to ruin the life of the main character, ant, and foil all his plans for making his dream come true. Can you help get everything back in order?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/739190/header.jpg?t=1668624177', 1, 0, NULL);
INSERT INTO games VALUES (4640, 739540, 'Break the Game', 'This game is about Kevin, He''s been stuck in his gaf̶̨s̨fẃ̵̕ HEY, YOU, STAY AWA̸̧͘Y, IT''S ME KEVIN, THERE''S NO POINT, D҉Ò̷̕N̸̕͏''T-- Follow him in this adventurous and humor-filled story to ｄ̶̢͙̟̦̺̰̫̙̋̊͐̐͑͋̈́̕̕͝ ｄｉｅ', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/739540/header.jpg?t=1728290051', 0, 0, NULL);
INSERT INTO games VALUES (127977, 739630, 'Phasmophobia', 'Phasmophobia is a 4 player online co-op psychological horror. Paranormal activity is on the rise and it’s up to you and your team to use all the ghost-hunting equipment at your disposal in order to gather as much evidence as you can.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/739630/header.jpg?t=1747947938', 0, 0, NULL);
INSERT INTO games VALUES (4624, 739650, 'Drake Hollow', 'Build and defend villages of vegetable folk from deadly feral beasts in the blighted world of The Hollow. Explore, gather, and fight! You can even invite your friends. Can you craft the perfect village?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/739650/34df6854822edf785d244fbd14a6f57c5242eca8/header.jpg?t=1749201338', 0, 0, NULL);
INSERT INTO games VALUES (136811, 739720, 'Penkura', 'Embark on an odyssey to a distant alien world through an ancient singularity. Establish your base, engineer indispensable bots, create cutting-edge equipment, and unravel the mysteries of civilizations lost in time. Welcome to a universe where the mind has defeated death.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/739720/header.jpg?t=1748777832', 0, 0, NULL);
INSERT INTO games VALUES (4638, 739980, 'Let''s not stay friends', 'Friendship is a wonderful thing… unless you are friends with a girl who has no idea you have feelings for her! Inske, a student of magical arts, is troubled by the upcoming outdoors exam, and can''t even imagine that someone might want to use the test as an opportunity to get close to her.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/739980/header.jpg?t=1726280197', 0, 0, NULL);
INSERT INTO games VALUES (4601, 740080, 'Deadly Days', 'Deadly Days is a unique strategic rogue-lite in the zombie apocalypse. Manage and protect a group of survivors and help them to stop the catastrophe. Discover and use a large number of wild and crazy objects, even wilder and crazier survivors, special abilities, and deadly weapons.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/740080/header.jpg?t=1739540868', 1, 0, NULL);
INSERT INTO games VALUES (4603, 740130, 'Tales of Arise', '300 years of tyranny. A mysterious mask. Lost pain and memories. Wield the Blazing Sword and join a mysterious, untouchable girl to fight your oppressors. Experience a tale of liberation, featuring characters with next-gen graphical expressiveness!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/740130/header.jpg?t=1735264482', 1, 0, NULL);
INSERT INTO games VALUES (4614, 740290, 'Irony Of Nightmare', 'In the Irony of Nightmare things aren''t always as they seem. Those who decide to solve all puzzles of the game, not only will unravel true secret of house, but also will open completely different ending of the story.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/740290/header.jpg?t=1636097877', 0, 0, NULL);
INSERT INTO games VALUES (4581, 741140, 'Baldr Sky', 'Kou Kadokura, a cyber officer, seeks to uncover the truth behind the tragedy that ended his once peaceful life. A war looms, and the answers he’s looking for are locked away in him... So why can''t he remember anything? Unravel the mysteries hidden in his lost memories through this fast-paced mech action game!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/741140/header.jpg?t=1656892413', 0, 0, NULL);
INSERT INTO games VALUES (4583, 741250, 'The Sand Man', '“I’ll tell you a scary story. It’s so scary you might not be able to take it. It’s the story of the Sand Man...” This is the second title in the Strange Man series, developed by Uri Games. Unable to sleep and exhausted, Sophie wanders into a town where everything sleeps. That is where the terror begins...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/741250/header.jpg?t=1735192236', 1, 0, NULL);
INSERT INTO games VALUES (4562, 741430, 'Titanic VR', 'Witness the sinking of RMS Titanic. Explore the shipwreck. Titanic VR is a diving simulator and immersive interactive story. With over 6 hours of game-play Titanic VR you will leave with a greater understanding of the historic tragedy that unfolded in 1912.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/741430/header.jpg?t=1550047969', 0, 0, NULL);
INSERT INTO games VALUES (4566, 741510, 'The Hong Kong Massacre', 'Blast your way through the streets of Hong Kong in a fast-paced, top-down shooter. Inspired by classic action movies, The Hong Kong Massacre places you at the center of a hard-boiled revenge story, filled with brutal, cinematic shootouts and vivid underworld locations.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/741510/header.jpg?t=1741889791', 0, 0, NULL);
INSERT INTO games VALUES (4572, 741670, 'Easy Red', 'The invasion has begun. Land by sea, launch from gliders, fight in the fields, in the beaches and in the skies. it is time to free France.[/b]', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/741670/header.jpg?t=1589680912', 0, 0, NULL);
INSERT INTO games VALUES (4551, 741820, 'Prey: Typhon Hunter', 'Fight overwhelming odds to escape a secret TranStar moon base where the enemies you encounter, the hazards you face, the goals you complete, and the loot you collect are different each time you play. With changing environments as dangerous as they are dynamic, the Mooncrash campaign for Prey will offer a fun, infinitely replayable...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/741820/header.jpg?t=1569613424', 0, 0, NULL);
INSERT INTO games VALUES (4556, 742120, 'DRAGON QUEST® XI: Echoes of an Elusive Age™ - Digital Edition of Light', 'DRAGON QUEST® XI: Echoes of an Elusive Age™ follows the perilous journey of a hunted Hero who must uncover the mystery of his fate with the aid of a charismatic cast of supporting characters.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/742120/header.jpg?t=1727792014', 0, 0, NULL);
INSERT INTO games VALUES (4536, 742250, 'OPUS: Rocket of Whispers', 'Rocket of Whispers is an award-winning post-apocalyptic adventure that follows two survivors on a journey to launch a space burial for the lost souls of their desolate world. Help them search the snowy wasteland for supplies and the courage to say goodbye.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/742250/header.jpg?t=1709176976', 1, 0, NULL);
INSERT INTO games VALUES (4537, 742300, 'Mega Man 11', 'Mega Man is back! The newest entry in this iconic series blends classic, challenging 2D platforming action with a fresh new visual style. The new Double Gear system boosts Mega Man''s speed and power for a new twist to the satisfying gameplay the series is known for.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/742300/header.jpg?t=1701220165', 0, 0, NULL);
INSERT INTO games VALUES (4541, 742420, 'Saints Row', 'Welcome to Santo Ileso, a vibrant fictional city in the American Southwest. In a world rife with crime, where lawless factions fight for power, a group of young friends embark on their own criminal venture, as they rise to the top in their bid to become Self Made.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/742420/header.jpg?t=1726748689', 1, 0, NULL);
INSERT INTO games VALUES (4542, 742460, 'Marble Skies', 'Marble Skies is a fast paced 3D-platformer where you control your marble through various levels and try to get the best time for each one. Complete all the levels in your own time, or challenge your friends to get on top of the leaderboards!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/742460/header.jpg?t=1641676093', 0, 0, NULL);
INSERT INTO games VALUES (4547, 742520, 'Astrologaster', 'Astrologaster is a comedy game set in Shakespeare’s London. Play as ''Doctor'' Simon Forman and treat his patients using astrology. A story-driven adventure based on a truly ridiculous story.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/742520/header.jpg?t=1611763525', 0, 0, NULL);
INSERT INTO games VALUES (4530, 742700, 'Empire Deluxe Combined Edition', 'Empire Deluxe Combined Edition is the latest in the classic Empire Series of games, which has spanned almost five decades. Empire Deluxe is a game about taking cities. Starting with just one, the city enables a commander to produce units. These units in turn can directly attack or support the attack of more cities.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/742700/header.jpg?t=1528518694', 0, 0, NULL);
INSERT INTO games VALUES (4518, 743130, 'MewnBase', 'MewnBase is a space-cat survival and base-building game. Scavenge around a barren planet for items to keep you fed. Explore and collect resources. Craft items and grow your base to help you survive.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/743130/header.jpg?t=1698732681', 0, 0, NULL);
INSERT INTO games VALUES (4529, 743390, 'DISTRAINT 2', 'You are Price, a man who sold his humanity to get a partnership from a leading company: McDade, Bruton &amp; Moore. DISTRAINT 2 follows on from the events of the first game. It''s a sinister tale about restoring hope and finding your purpose.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/743390/header.jpg?t=1732098854', 1, 0, NULL);
INSERT INTO games VALUES (4500, 743450, 'Monster Prom', 'You have 3 weeks to get a date for Monster Prom! Go through absurd and funny situations, raise your stats and seduce one of your classmates. Beautiful art, bold, unapologetic dialogue and hard choices make up this Multiplayer (1-4 players) Dating Sim. Be your worst self.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/743450/header.jpg?t=1747133303', 0, 0, NULL);
INSERT INTO games VALUES (4507, 743640, 'Achievement Clicker', 'Feel like a real Achievement hunter! Earn Achievements, upgrades and get the most Achievements on steam!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/743640/header.jpg?t=1742221070', 0, 0, NULL);
INSERT INTO games VALUES (4486, 743860, 'Wild West Online', 'Welcome to the emergent open world, Wild West-themed action PVP online game featuring non stop players vs player battles, world exploration, resource gathering, and much, much more.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/743860/header.jpg?t=1545343726', 0, 0, NULL);
INSERT INTO games VALUES (4487, 743890, 'Mega Man X Legacy Collection', 'Mega Man X Legacy Collection includes the legendary 16-bit titles and the series’ exciting foray into the 32-bit era: Mega Man X, Mega Man X2, Mega Man X3, and Mega Man X4. Test your skills in the new X Challenge mode, which pits players against two deadly bosses at once.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/743890/header.jpg?t=1669873820', 0, 0, NULL);
INSERT INTO games VALUES (4488, 743900, 'Mega Man X Legacy Collection 2', 'Complete the exciting Mega Man X saga with four action-packed titles! This collection showcases the evolution of the series with Mega Man X5, Mega Man X6, Mega Man X7, and Mega Man X8. Test your skills in the new X Challenge mode, which pits players against two deadly bosses at once.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/743900/header.jpg?t=1669873839', 0, 0, NULL);
INSERT INTO games VALUES (4496, 744050, 'Space Invaders Extreme', 'The critically acclaimed update to the Space Invaders franchise has arrived to invade Steam with greatly improved graphics and audio! Packed with pulsing, vibrant visuals enhanced further by interactive sound. The invaders have evolved, the question is: can you keep up?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/744050/header.jpg?t=1696963117', 1, 0, NULL);
INSERT INTO games VALUES (4497, 744060, 'Groove Coaster', 'Riding the rhythmic rails of success from smart phone, into the arcades, now GROOVE COASTER arrives on Steam! Are you ready to ride a roller coaster of sound and light through a universe of music?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/744060/header.jpg?t=1729573645', 0, 0, NULL);
INSERT INTO games VALUES (4471, 744190, 'Rusty Lake Paradise', 'Rusty Lake Paradise is set on a small remote island which is cursed by the ten plagues of Egypt. Solve all the mysteries of this dark, macabre puzzle adventure. Paradise builds upon the distinctive atmosphere and excitement from the Rusty Lake series.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/744190/header.jpg?t=1746052913', 1, 0, NULL);
INSERT INTO games VALUES (4475, 744270, 'Rise of Ages', 'Rise of Ages is a sandbox game, allowing you to explore, build, found cities, make wars and evolve technologies to reach the highest level of a civilization and then travel to other planets! The game begins in prehistory and will advance ages, one by one, as the player evolves.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/744270/header.jpg?t=1548926608', 0, 0, NULL);
INSERT INTO games VALUES (4461, 744670, 'WORLDS AT WAR (Monitors & VR)', 'A fun, addicting &amp; high-adrenaline dog-fighting ''sim-lite'' horde-mode game. Worlds At War thrusts the player into the aftermath of an alien invasion. A multi-national ragtag group of surviving fighter pilots and crew man a small carrier-group, roaming the oceans, trying to survive against all odds.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/744670/header.jpg?t=1575965061', 0, 0, NULL);
INSERT INTO games VALUES (4437, 745000, 'Card Crawl', 'Card Crawl is a solitaire style Dungeon Crawler played with a deck of cards.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/745000/header.jpg?t=1726558860', 0, 0, NULL);
INSERT INTO games VALUES (4438, 745010, 'Mechanic Miner', 'Put your mechanical skills to the test in a physics-based sandbox where ingenuity and creativity are the ultimate key to survival. Construct fantastical machines, gather resources, acquire new technologies to battle dangerous enemies and use your imagination to shape your world.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/745010/header.jpg?t=1726305327', 0, 0, NULL);
INSERT INTO games VALUES (4404, 745330, 'StrikeForce Kitty', 'Comedic puzzle-adventure with strong RPG influences. Take away costumes from the foxes, create the most mad combinations of clothes, explore the world, find secrets and save the princess from the clutches of the cunning king!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/745330/header.jpg?t=1726401400', 1, 0, NULL);
INSERT INTO games VALUES (4384, 745880, 'Touhou Tenkuushou ~ Hidden Star in Four Seasons.', '桜を見ながら西瓜を割り、紅葉を見ながら鍋をつつく こんな季節に誰がした！ イレギュラーでシーズナルなシューティング幻想！', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/745880/header.jpg?t=1668044347', 0, 0, NULL);
INSERT INTO games VALUES (4387, 745920, 'Temtem', 'Temtem is an online creature-collection adventure. Tame 165 unique creatures across 7 vibrant islands, battle other tamers, tackle mythical Lairs, chase Luma &amp; Umbra variants, and breed your favorite Tems - with friends by your side! Dive into a colorful monster catching adventure, so Temtem up!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/745920/header.jpg?t=1745480798', 1, 0, NULL);
INSERT INTO games VALUES (4391, 745960, 'A Sky Full of Stars 仰望夜空的星辰', 'The starry sky spreads far and wide overhead... This story full of love, comedy, and excitement follows our protagonist and his stargazing friends as they grow together. &quot;A Sky Full of Stars&quot; is a coming-of-age astronomy tale by the same team who brought you &quot;If My Heart Had Wings&quot;.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/745960/header.jpg?t=1612502056', 0, 0, NULL);
INSERT INTO games VALUES (4401, 746140, 'Walking Zombie: Shooter', 'The Walking Zombie is a stationary FPS with an online co-op mode in a world full of zombies to kill. Buy and upgrade your weapons, kill all enemies in 200 levels and destroy mighty boss monsters before they eat you alive!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/746140/header.jpg?t=1729248763', 0, 0, NULL);
INSERT INTO games VALUES (4364, 746400, 'Speed Dating for Ghosts', 'Branching dialogue! Hard choices! A cemetery''s worth of phantoms, wraiths, and poltergeists lookin'' for love in all the blight places.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/746400/header.jpg?t=1617835652', 0, 0, NULL);
INSERT INTO games VALUES (4369, 746510, 'Duck Season PC', 'An experimental first person narrative sending you back to Summer 1988 and you have a one day rental of Duck Season. Dive into the mystery and work through the hidden secrets spilling out of the cursed cartridge. The full hit VR game playable on your traditional flat screen!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/746510/header.jpg?t=1667678098', 0, 0, NULL);
INSERT INTO games VALUES (4375, 746580, 'HARDCORE MECHA', 'HARDCORE MECHA is a 2D platformer action focusing on a better handling. The Campaign mode offers rich gameplay and seamless in-game cut-scenes for an immersive experience. Choose your favorite mecha, experience the fast-paced hardcore competitive battle of steel in Multiplayer!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/746580/header.jpg?t=1661221178', 1, 0, NULL);
INSERT INTO games VALUES (37265, 746710, 'Cypher', 'Cypher is a first person puzzle game about cryptography.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/746710/header.jpg?t=1667310781', 0, 0, NULL);
INSERT INTO games VALUES (4351, 746940, 'Nippon Marathon', 'Crazy, physics-driven, four-player marathon across Japan. Combining classic racers like Micro Machines and the insanity of TV''s Takeshi''s Castle, smash through offices and shopping malls and hurl fruit at your opponents in a party game unlike anything you''ve played before!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/746940/header.jpg?t=1741786671', 1, 0, NULL);
INSERT INTO games VALUES (4322, 747200, 'Keplerth', 'Welcome to Keplerth! Try to survive on a hostile alien planet in this 2D sandbox RPG, where you can choose to live alone or fight side by side with your friends in the online multiplayer mode. Survive, build, farm, fight, and explore your way to victory in this open-world adventure!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/747200/header.jpg?t=1745569465', 0, 0, NULL);
INSERT INTO games VALUES (4332, 747340, 'Unforgiving - A Northern Hymn', 'Unforgiving - A Northern Hymn is a first person horror game heavily inspired by Swedish folklore and the Nordic mythology to create the nightmares that''s been haunting Swedish children for many generations.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/747340/header.jpg?t=1625813197', 1, 0, NULL);
INSERT INTO games VALUES (4333, 747350, 'Hellblade: Senua''s Sacrifice VR Edition', 'The VR Edition of the critically acclaimed BAFTA award-winning Hellblade: Senua''s Sacrifice. From the makers of Heavenly Sword, Enslaved: Odyssey to the West, and DmC: Devil May Cry, comes a warrior’s brutal journey into myth and madness.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/747350/header.jpg?t=1707499243', 1, 0, NULL);
INSERT INTO games VALUES (4299, 747660, 'Five Nights at Freddy''s: Security Breach', 'In Five Nights at Freddy’s: Security Breach, play as Gregory, a young boy who’s been trapped overnight inside of Freddy Fazbear’s Mega Pizzaplex. With the help of Freddy himself, Gregory must uncover the secrets of the Pizzaplex, learn the truth, and survive until dawn.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/747660/header.jpg?t=1686587905', 1, 0, NULL);
INSERT INTO games VALUES (4309, 747910, 'Disassembly 3D', 'Disassembly and destruction physics sandbox simulator. Detailed models of objects and vehicles and their internal parts. Disassemble objects successfully to unlock weapons mode and destruction. Fight evil mannequins with everything you got in physical combat!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/747910/header.jpg?t=1611135393', 0, 0, NULL);
INSERT INTO games VALUES (4317, 748040, 'State of War : Warmonger / 蓝色警戒 (Classic 2000)', 'Enjoy an unforgettable blast from the past with this classic real-time strategy experience. This all-inclusive bundle includes the original 22 missions from State of War (2000), and 16 additional missions from its sequel, State of War: Warmonger (2003).', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/748040/header.jpg?t=1554376557', 0, 0, NULL);
INSERT INTO games VALUES (4287, 748300, 'Treasure Hunter Simulator', 'Dive into the exciting world of finding long forgotten treasures. Grab your metal detector and set off to explore the countryside. What today looks like a peaceful meadow might have been the scene of a fierce battle in the past, hiding now the valuable artefacts. Ready to dig in the past?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/748300/header.jpg?t=1742476626', 1, 0, NULL);
INSERT INTO games VALUES (4291, 748360, 'MY HERO ONE''S JUSTICE', 'Fight for your justice in MY HERO ONE''S JUSTICE! The popular manga and anime series clashes head-to-head and Quirk-to-Quirk in this 3D arena fighter.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/748360/header.jpg?t=1586211367', 1, 0, NULL);
INSERT INTO games VALUES (4292, 748370, 'STAND OUT VR : VR Battle Royale', 'Kill, build, drive, do parkour, fly, make friends, eat... Compete to be the last man alive on huge islands filled with deadly weapons and vehicles. Play the way you want, this is Battle Royale.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/748370/header.jpg?t=1697660924', 0, 0, NULL);
INSERT INTO games VALUES (4297, 748490, 'The Legend of Heroes: Trails of Cold Steel II', 'Civil war has broken out across Erebonia. After his narrow escape from Trista, Rean will take up his sword again on a journey with his Divine Knight, Valimar, in search of his friends from Class VII and a way to end the conflict before its price becomes far too dear...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/748490/header.jpg?t=1732061866', 0, 0, NULL);
INSERT INTO games VALUES (4259, 748610, 'Airport Madness 3D: Volume 2', 'Our second volume of Airport Madness 3D compliments the first one with eight new airports, new aircraft, more gates, and sharper detail. Volume Two offers New York John F. Kennedy, Toronto Pearson, Miami, London City, San Francisco, Lukla Nepal, Hong Kong, and Chicago O''Hare.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/748610/header.jpg?t=1742228123', 0, 0, NULL);
INSERT INTO games VALUES (4271, 748890, 'Choice of Rebels: Uprising', 'Lead the revolt against a bloodthirsty empire! You grew up under the iron fist of the Hegemony. Now is your chance to end their blood-fueled magic, as you forge a ragtag outlaw band into a rebel army.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/748890/header.jpg?t=1734037947', 0, 0, NULL);
INSERT INTO games VALUES (4275, 748970, 'Zen Chess: Mate in One', 'Zen Chess: Mate in One is a minimalist chess puzzle game. Solve mate-in-one problems in a beautifully designed chess board.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/748970/header.jpg?t=1729622217', 1, 0, NULL);
INSERT INTO games VALUES (4245, 749250, '7th Sector', 'Welcome to the 7th Sector, set in a mysterious cyberpunk world. Immerse yourself on this intricate path, solving different puzzles, facing its dangers and collecting scattered information to discover the story of this world.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/749250/header.jpg?t=1725974043', 0, 0, NULL);
INSERT INTO games VALUES (4221, 749800, 'PixelJunk™ Monsters 2', 'PixelJunk™ Monsters is back with the simple, yet highly strategic real-time tower defense gameplay gameplay of the original title, now with updated graphics and brand new multiplayer modes!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/749800/header.jpg?t=1715700492', 0, 0, NULL);
INSERT INTO games VALUES (4224, 749840, 'The Boogie Man', '&quot;You are the player, and must chase the Boogie Man. If you catch him, you win! And that''s the happy ending, but if you don''t...&quot; This is the third title in the Strange Man series. Keith tours a castle with his wife, Helena. Sit back, and enjoy tonight''s entertainment: A horrific display of murder.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/749840/header.jpg?t=1735192164', 1, 0, NULL);
INSERT INTO games VALUES (4229, 749890, 'The Hanged Man', '&quot;You''re a demon child. Someday, you''ll be burning in hell for your sins.&quot;. This is the fourth and final title in the Strange Man series, developed by Uri Games. Will was running away from home with his mouse buddy Pop, until the two of them wandered into an abandoned building. What secrets lie hidden within?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/749890/header.jpg?t=1735192320', 1, 0, NULL);
INSERT INTO games VALUES (4232, 749960, 'Townsmen VR', 'Townsmen VR uses the exciting possibilities of virtual reality to further enhance the classic city building game with entirely new gameplay experiences and interactive mechanics. It combines elements of a God-game simulation and a classic building game with the interactive possibilities of VR.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/749960/header.jpg?t=1736956236', 1, 0, NULL);
INSERT INTO games VALUES (4196, 750130, 'The Sinking City Remastered', 'Powered by Unreal Engine 5, The Sinking City Remastered brings the eerie, atmospheric world of Oakmont back to life with enhanced gameplay and fully relit environments, perfect for both newcomers and returning players.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/750130/1a084caa949bfe97451e6782d536ffc69c6ffefc/header_alt_assets_1.jpg?t=1749117416', 1, 0, NULL);
INSERT INTO games VALUES (4197, 750170, 'Diesel Railcar Simulator', 'Drive vintage diesel trains, shifting gears manually and trying to reach a perfect score. Create new routes, trains and timetables. Share your creations and download new content from the Workshop.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/750170/header.jpg?t=1721488966', 0, 0, NULL);
INSERT INTO games VALUES (4198, 750200, 'AWAY: The Survival Series', 'In this story-based adventure, play as a tiny sugar glider in your very own nature documentary. Glide among the trees, fight dangerous predators, and explore beautiful environments as you embark on a high-flying journey to save your family.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/750200/header.jpg?t=1739840210', 0, 0, NULL);
INSERT INTO games VALUES (4202, 750290, 'Slice of Sea', 'Slice of Sea is a peaceful adventure and puzzle game. You play as Seaweed, a sea creature clearly out of their element. Explore desolate world of dust, all hand-drawn on paper in unique art style. Collect items, solve puzzles and lead Seaweed back home to the sea.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/750290/header.jpg?t=1748509146', 1, 0, NULL);
INSERT INTO games VALUES (4210, 750470, 'War Brokers', 'War Brokers is a fast paced, first person, 3D shooter focused on fun and tactical choices. Players start on an equal footing with access to all weapons and vehicles. A player''s skill and tactical choices will win the day.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/750470/header.jpg?t=1616476404', 1, 0, NULL);
INSERT INTO games VALUES (4192, 750520, 'Arcade Tycoon ™ : Simulation Game', 'Build stunning Arcade Centre’s, purchase a range of arcades machines, manage troublesome staff in this colourful and humorous simulation management game. Inspired by Two Point Hospital, Let''s Build A Zoo and Megaquarium.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/750520/header.jpg?t=1718872694', 0, 0, NULL);
INSERT INTO games VALUES (127403, 750920, 'Shadow of the Tomb Raider: Definitive Edition', 'As Lara Croft races to save the world from a Maya apocalypse, she must become the Tomb Raider she is destined to be.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/750920/header.jpg?t=1729014037', 1, 0, NULL);
INSERT INTO games VALUES (4170, 751440, 'VR Kanojo / VRカノジョ', 'This is Steam version.&quot;all characters in this game are 18+&quot;We have a trial version here.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/751440/header.jpg?t=1741979131', 0, 0, NULL);
INSERT INTO games VALUES (4171, 751450, 'Nanairo Reincarnation', 'Join spirit detective Kagami Makoto and his demon familiars as they hunt down the wandering ghosts disrupting the peace of his small town.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/751450/header.jpg?t=1580429808', 0, 0, NULL);
INSERT INTO games VALUES (4134, 751500, 'TINY METAL', 'Craft unique strategies and outmaneuver your foes in TINY METAL, a turn-based Japanese wargame! With new tactical options, you will command over 16 tactically diverse units, flank, assault, deploy heroes from orbital dropships, and focus the firepower of multiple units to even out otherwise disastrous odds.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/751500/header.jpg?t=1578462858', 1, 0, NULL);
INSERT INTO games VALUES (4140, 751630, 'After the Fall®', 'From the team that brought you Arizona Sunshine® comes an epic VR action FPS with intense co-op gameplay at its core. Team up with friends and take on a hostile VR world filled with ferocious undead--mutated and twisted by the relentless cold.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/751630/header.jpg?t=1725370665', 1, 0, NULL);
INSERT INTO games VALUES (4147, 751780, 'Forager', 'The highly popular and quirky &quot;idle game that you want to actively keep playing&quot;. Explore, craft, gather &amp; manage resources, find secrets and build your base out of nothing! Buy land to explore and expand!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/751780/header.jpg?t=1699372258', 1, 0, NULL);
INSERT INTO games VALUES (4149, 751820, 'Black Future ''88', 'Black Future ’88 is a Synth-Punk roguelike 2D action Shooter. Vertically climb an always evolving procedural tower to reach the top and kill its insane owner…before your heart explodes. Shoot, slash, dash and upgrade yourself to survive the endless waves of Homicidal AI, Traps &amp; Colossal Wardens.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/751820/header.jpg?t=1666052970', 0, 0, NULL);
INSERT INTO games VALUES (4091, 752470, 'CINERIS SOMNIA', '&quot;I hope that someday, you''ll dream of me.&quot; -- CINERIS SOMNIA is a 3D adventure through a beautifully strange and mesmerizing world - and a young girl''s cruel and forlorn dreams.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/752470/header.jpg?t=1573792455', 0, 0, NULL);
INSERT INTO games VALUES (4092, 752480, 'Sniper Elite VR', 'Grab your rifle, gaze down the scope and take aim in this stealth-action WW2 first-person shooter built exclusively for VR. With an explosive campaign, astonishing immersion, authentic weaponry, and signature gunplay from the award-winning Sniper Elite series', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/752480/header.jpg?t=1643711030', 1, 0, NULL);
INSERT INTO games VALUES (4100, 752590, 'A Plague Tale: Innocence', 'Follow the grim tale of young Amicia and her little brother Hugo, in a heartrending journey through the darkest hours of history.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/752590/header.jpg?t=1727793332', 1, 0, NULL);
INSERT INTO games VALUES (4113, 752900, 'Prehistoric Hunt', 'Dive into intense dinosaur hunting adventures with your friends. Complete hunting contracts for Preton Corporation. Gather rewards, improve your equipment and become a master hunter. Are you the hunter or the hunted?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/752900/header.jpg?t=1713127333', 0, 0, NULL);
INSERT INTO games VALUES (4114, 752910, 'Cookies vs. Claus', 'Cookies vs. Claus is an action-packed battle game. With a range of characters to choose from, you can battle as your favorite cookie or take on a squad as a holiday character. Through both single and multiplayer, experience a unique asymmetric shooter that combines elements of FPS and battle arena games. THIS IS COOKIES VS. CLAUS!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/752910/header.jpg?t=1575401516', 0, 0, NULL);
INSERT INTO games VALUES (4073, 753220, 'Mhakna Gramura and Fairy Bell', 'Written in the style of a children’s book, Mhakna Gramura and Fairy Bell is a Cinematic Novel about two children named Mhakna and Sebiarno that escape the wretched Mullbear Orphanage with the help of a Fairy named Bell, who promises eternal happiness as long as they agree to never grow up.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/753220/header.jpg?t=1667226362', 1, 0, NULL);
INSERT INTO games VALUES (4080, 753420, 'Dungreed', 'Dungreed is a 2D side-scrolling action game with 2D Rogue-LITE elements. You become an adventurer exploring a continuously evolving dungeon to prevent the town from being destroyed. Eliminate enemies, use a variety of weapons and magic, eat food, and defeat evil in the dungeon!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/753420/header.jpg?t=1734348632', 1, 0, NULL);
INSERT INTO games VALUES (4065, 753590, 'Hellbound', 'Classic First Person Shooter style game. Like the good old days. An action game focused on speed, gore, guns, and metal music. Inspired by the 90s’ classics with modern visuals and audio!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/753590/header.jpg?t=1727046815', 0, 0, NULL);
INSERT INTO games VALUES (4068, 753640, 'Outer Wilds', 'Named Game of the Year 2019 by Giant Bomb, Polygon, Eurogamer, and The Guardian, Outer Wilds is a critically-acclaimed and award-winning open world mystery about a solar system trapped in an endless time loop.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/753640/header.jpg?t=1729097431', 1, 0, NULL);
INSERT INTO games VALUES (4069, 753650, 'Due Process', 'A PVP tactical FPS about PLANNING &amp; EXECUTION. Sound strategy and good teamwork are essential for victory because new PROCEDURALLY-GENERATED MAPS are delivered every week. You''ll face a new tactical challenge every round.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/753650/header.jpg?t=1747512420', 0, 0, NULL);
INSERT INTO games VALUES (4052, 753930, 'God''s Basement', 'God''s Basement is a first-person, narrative-driven, single player horror game. Uncover the secrets of an afterlife shrouded in mystery, as an entity known as &quot;The Operator&quot; leads you deeper into the fringes of a seemingly eternal purgatory.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/753930/header.jpg?t=1645483541', 1, 0, NULL);
INSERT INTO games VALUES (4061, 754040, 'Piggy Poggy Pog', 'Piggy Poggy Pog - is quite a complex, nice-looking 2D platformer in which you must escape from the farm playing for a pig named Poggy . In this game you go through the levels, collecting a certain number of acorns.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/754040/header.jpg?t=1720879118', 0, 0, NULL);
INSERT INTO games VALUES (4064, 754120, 'Ninja Stealth 3', 'After a long vacation our ninja is a little rusty, can you help him with his training? Ninja Stealth III brings you 30 new challenging levels, are you ready?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/754120/header.jpg?t=1738797822', 0, 0, NULL);
INSERT INTO games VALUES (36961, 754150, 'Rolling Line', 'Build your own model railway tracks and scenery or explore pre-made layouts, including 1000s of player-made layouts and mods on the Steam Workshop! Play in virtual reality and on PC!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/754150/header.jpg?t=1748303583', 0, 0, NULL);
INSERT INTO games VALUES (4049, 754530, 'IL-2 Sturmovik: Cliffs of Dover Blitz Edition', 'Scramble to intercept in your RAF Spitfire or Hurricane. Or join huge formations of German or Italian Fighters and Bombers as they roar across the Channel towards London. Decide the fate of Britain!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/754530/header.jpg?t=1721725991', 0, 0, NULL);
INSERT INTO games VALUES (4033, 754890, 'Firmament', 'Firmament is a new puzzle-adventure game by the legendary game studio behind the best-selling games Myst and Riven. Featuring deep storytelling and world-building, discover the story of this seemingly abandoned world as you explore and unlock the mysteries of 3 unique Realms… and beyond!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/754890/header.jpg?t=1730853629', 1, 0, NULL);
INSERT INTO games VALUES (3994, 755410, 'Vengeful Rites', 'Embark on an epic adventure designed exclusively for VR! Use your own hands to cast magic, fire bows and slice through your enemies on your quest to exact vengeance against the evil Dragore. Learn new spells and craft new gear to become the greatest Serafin Warrior of all time! Demo available.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/755410/header.jpg?t=1726543382', 0, 0, NULL);
INSERT INTO games VALUES (3997, 755470, 'The World Next Door', 'An addictive mix of lightning-fast puzzle battles, powerful storytelling and immersive visual novel elements, The World Next Door follows Jun, a rebellious teen girl trapped in a parallel realm inhabited by magical creatures, who must find her way home before time runs out.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/755470/header.jpg?t=1746806954', 0, 0, NULL);
INSERT INTO games VALUES (3999, 755500, 'ONE PIECE World Seeker', 'Leave your compass behind and join Luffy as he embarks on a brand new action-packed adventure where you can experience the powers of the legendary Gum-Gum fruit to uncover hidden secrets on an original, never-before-seen island!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/755500/header.jpg?t=1701311545', 1, 0, NULL);
INSERT INTO games VALUES (3982, 755980, 'DEPLOYMENT', 'Deployment is an intense competitive top-down shooter game. Infosoldiers, made of pure information, fight in an endless war between governments and megacorporations to rule over the digital systems that control the world. Deploy your troops from up to five different classes!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/755980/header.jpg?t=1745661250', 0, 0, NULL);
INSERT INTO games VALUES (3967, 756530, 'TOKYO GHOUL:re [CALL to EXIST]', 'It may not be stylish, but... Live.Eat or be eaten. TOKYO GHOUL:re [CALL to EXIST] is a co-op survival action game that lets you experience the exciting world of Tokyo Ghoul and Tokyo Ghoul:re for yourself.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/756530/header.jpg?t=1580310681', 1, 0, NULL);
INSERT INTO games VALUES (128118, 756800, 'Contraband Police', 'Take over the duties of a border guard inspector in a communist country of the 80''s. Smuggling, corruption and forgery are the order of the day here. Be vigilant and earn the respect of your superiors.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/756800/header.jpg?t=1748528010', 1, 0, NULL);
INSERT INTO games VALUES (3947, 756880, 'NVL', 'NVL - an amazing adventure game in the genre of RPG. An interesting combat turn-based system as in JRPG. Beautiful anime girls with pantsu.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/756880/header.jpg?t=1683109972', 0, 0, NULL);
INSERT INTO games VALUES (3920, 757210, 'EMERGENCY 4 Deluxe', 'Coordinate firefighters, police, medical personnel and specialists in the classic EMERGENCY 4 Deluxe! Now with the previously untranslated bonus missions in English.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/757210/header.jpg?t=1667222935', 0, 0, NULL);
INSERT INTO games VALUES (3924, 757300, 'Truberbrook / Trüberbrook', 'Enjoy an adventurous vacation to a 1960''s parallel universe! A Sci-Fi-Mystery Adventure Game with handmade scenery.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/757300/header.jpg?t=1717681834', 1, 0, NULL);
INSERT INTO games VALUES (3925, 757310, 'Sable', 'Embark on an unique and unforgettable journey and guide Sable through her Gliding; a rite of passage that will take her across vast deserts and mesmerizing landscapes, capped by the remains of spaceships and ancient wonders.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/757310/header.jpg?t=1726577678', 0, 0, NULL);
INSERT INTO games VALUES (3926, 757320, 'Atomicrops', 'A twin-stick, bullet-hell, roguelite where you must cultivate and defend the last farm in a post-apocalyptic wasteland. Farm mutated crops, upgrade your weapons, marry townsfolk, and kill every mutant creature that tries to invade your homestead! Yee-haw!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/757320/header.jpg?t=1749468018', 1, 0, NULL);
INSERT INTO games VALUES (3927, 757330, 'qop 2', 'qop 2 is a minimalistic puzzle which goal is to get the cube to finish using 4 directions in space.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/757330/header.jpg?t=1674748089', 1, 0, NULL);
INSERT INTO games VALUES (3935, 757480, 'Broken Reality', 'A humorous adventure set in a 3D parody of the internet. Diverse puzzles, beautiful worlds, friends, experiences, upgrades and more, await those who ''log on''!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/757480/header.jpg?t=1715805195', 0, 0, NULL);
INSERT INTO games VALUES (3878, 758190, 'Dragon Cliff', 'Dragon Cliff is a Semi-Idle RPG game with deep and complex itemization/skill systems to support endless character builds. Players are to collect adventurers, kill monsters, advance talent trees, enchant/reforge equipment, discover scrolls and finally assemble the most powerful adventure team!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/758190/header.jpg?t=1646649681', 0, 0, NULL);
INSERT INTO games VALUES (3884, 758320, 'Cursed Lands', 'Defeat the evil lurking in Castle Of N''Mar in this RPG/dating sim game. Recruit your team in any order you want, use the optional social talents to win the battles, play as male or female and fully customize your avatar. Five romance per gender, including the unique Naga Enok and Sylrissa!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/758320/header.jpg?t=1684499584', 0, 0, NULL);
