INSERT INTO games VALUES (3889, 758480, 'Ukrainian ball in search of gas', 'You play as a man turned into a ball and you need to steal all the gas from the forest at all costs.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/758480/header.jpg?t=1512740171', 0, 0, NULL);
INSERT INTO games VALUES (3890, 758500, 'Loot Box Quest', 'The spiritual successor to DLC Quest! Earn that sense of pride and accomplishment in the way that only repetitive clicking can deliver. It''s a clicker game, so chill out, have a few chuckles, and watch numbers get bigger while the industry burns around us all.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/758500/header.jpg?t=1668183887', 0, 0, NULL);
