INSERT INTO games VALUES (36295, 770810, 'Good Pizza, Great Pizza - Cooking Simulator Game', 'Ever wanted to know what it feels like to run your own cozy Pizza shop? Do your best to fulfill pizza orders from customers while making enough money to keep your shop open. Upgrade your shop with new toppings and equipment to compete against your pizza rival, Alicante!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/770810/header.jpg?t=1746237894', 1, 0, NULL);
INSERT INTO games VALUES (3370, 771350, 'Achievement Clicker 2018', 'Feel like a real Achievement hunter! Earn Achievements, upgrades and get the most Achievements on Steam!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/771350/header.jpg?t=1737738033', 0, 0, NULL);
INSERT INTO games VALUES (3375, 771420, 'Primal Light', 'Inhabit Krog, a mysterious blue creature in a red loincloth, as he traverses a labyrinth of ladders, levers, traps, and monsters. Explore the nooks and crannies of a bizarre and evocative world as you hack and slash your way to victory, leaving a graveyard of grotesque bosses in your wake.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/771420/header.jpg?t=1613945936', 1, 0, NULL);
INSERT INTO games VALUES (3353, 771810, 'The spy who shot me™', 'The spy who shot me™ is a comedy retro FPS inspired by classic shooters of the 90s.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/771810/header.jpg?t=1674060770', 0, 0, NULL);
INSERT INTO games VALUES (3316, 771920, 'TOGETHER VR', 'Come! Indulge yourselves in your own private den and create sweet and loving memories with her!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/771920/header.jpg?t=1728268333', 1, 0, NULL);
INSERT INTO games VALUES (3325, 772180, 'Cricket Club', 'Attack, defend, and swing your way to glory in front of a packed crowd at one of the most beautiful cricket venues in the world. Your skills will be pushed to the limit as you face up to a challenging range of bowlers; from slow and steady to fast and frightening', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/772180/header.jpg?t=1585712475', 0, 0, NULL);
INSERT INTO games VALUES (3333, 772290, 'Rainswept', 'Rainswept takes you on an emotional adventure in a small town shaken by a double shooting. Join Detective Stone and unravel a tangled web of love, relationships, and unresolved trauma in this character-driven murder mystery game.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/772290/header.jpg?t=1749387991', 0, 0, NULL);
INSERT INTO games VALUES (3298, 772430, 'Hero of the Kingdom III', 'Lovely adventuring RPG series. Casual, story-driven journey and quests. An ancient evil awakened in the kingdom. Travel through the four valleys to become a hero and save the kingdom on the brink of destruction.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/772430/header.jpg?t=1741103345', 0, 0, NULL);
INSERT INTO games VALUES (3304, 772540, 'Battle Royale Trainer', 'Battle Royale Trainer lets you practice your combat skills with a wide range of weapons, scopes and attachments against AI opponents and targets, honing your skills until you can snap-shoot, control recoil and head-shot your opponents at any distance like a pro.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/772540/header.jpg?t=1746730500', 1, 0, NULL);
INSERT INTO games VALUES (3271, 773370, 'Exo One', 'A strange signal... an alien craft... an interplanetary, gravity-defying journey through space and time.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/773370/header.jpg?t=1740395793', 0, 0, NULL);
INSERT INTO games VALUES (3284, 773580, 'Game Dev Studio', 'Welcome to your own Game Dev Studio! How will you run your own offices and ascend to greatness in the gaming industry?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/773580/header.jpg?t=1666983506', 0, 0, NULL);
INSERT INTO games VALUES (3252, 773670, 'Delete', 'Let the number tell you what to do', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/773670/header.jpg?t=1702294961', 1, 0, NULL);
INSERT INTO games VALUES (3255, 773790, 'Ostriv', 'Ostriv is a city-building game that puts you in a role of a governor of an 18th century Ukrainian town to challenge your creative skills and management abilities.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/773790/header.jpg?t=1731437983', 0, 0, NULL);
INSERT INTO games VALUES (3258, 773840, 'ExoCross', 'ExoCross is an offroad racing game introducing 4CPT vehicle physics (4-way contact patch traction technology). A soft-body tire model allows for competitive time attack and multiplayer wheel to wheel racing.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/773840/header.jpg?t=1726851754', 0, 0, NULL);
INSERT INTO games VALUES (3263, 773951, 'Freeman: Guerrilla Warfare', 'In the anarchic world of Freeman: Guerrilla Warfare, only the mightiest warlord rules. Start with a pistol and a few militias, you will set yourself on a wild and ambitious journey towards world domination. Enjoy the immersive combination of intense FPS and sandbox strategy.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/773951/header.jpg?t=1619178850', 0, 0, NULL);
INSERT INTO games VALUES (3229, 774091, 'Ostalgie: The Berlin Wall', 'The confrontation between the East and the West is coming to an end, but not between East and West Germany. The old party leaders are still sitting in their offices, not changing anything and waiting for exclamations from Moscow. But their end is close – Gorbachev and Kohl have already decided...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/774091/header.jpg?t=1728371865', 0, 0, NULL);
INSERT INTO games VALUES (135679, 774171, 'Muse Dash', 'Paradise of parkour &amp; rhythm game ★★★ — Muse Dash!!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/774171/header.jpg?t=1727602742', 1, 0, NULL);
INSERT INTO games VALUES (3235, 774181, 'Rhythm Doctor', 'Save patients with your rhythm mastery! Rhythm Doctor is a rhythm game where you heal patients by defibrillating in time to their heartbeats. Learn each patient''s unique heartbeat and defeat boss viruses trying to sabotage your rhythm, all set to heart-pumping, soul-soothing music.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/774181/header.jpg?t=1741877372', 1, 0, NULL);
INSERT INTO games VALUES (3237, 774201, 'Heaven''s Vault', 'An archaeologist uncovers a lost history in an ancient space Nebula. Award-winning narrative adventure game with hieroglyphic language puzzles, from the creators of 80 DAYS.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/774201/header.jpg?t=1736524066', 0, 0, NULL);
INSERT INTO games VALUES (3240, 774241, 'Warhammer: Chaosbane', 'In a world ravaged by war and dominated by magic, you must rise up to face the Chaos hordes. Playing solo or with up to four players in local or online co-op, choose a hero from four character classes and prepare for epic battles wielding some of the most powerful artefacts of the Old World.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/774241/header.jpg?t=1726153445', 1, 0, NULL);
INSERT INTO games VALUES (3246, 774351, 'Citystate', 'Create a 21st century micro-nation and experiment with economic and political ideals. Futuristic skyscrapers or spreading slums, the Nation relies on your economic and city planning skills.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/774351/header.jpg?t=1707216823', 0, 0, NULL);
INSERT INTO games VALUES (3247, 774361, 'Blasphemous', 'Blasphemous is a brutal action-platformer with skilled hack’n slash combat set in the nightmare world of Cvstodia. Explore, upgrade your abilities, and perform savage executions on the hordes of enemies that stand between you and your quest to break eternal damnation.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/774361/header.jpg?t=1749138567', 1, 0, NULL);
INSERT INTO games VALUES (3217, 774461, 'The Jackbox Party Pack 5', 'It’s the biggest Party Pack yet, including the return of the classic pop culture trivia mash-up YOU DON’T KNOW JACK: Full Stream; the game of hilarious hypotheticals Split the Room; the lyric-writing, robot rap battle Mad Verse City; the inventive drawing game Patently Stupid; and the outer space fling-fest Zeeple Dome.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/774461/header.jpg?t=1728584545', 0, 0, NULL);
INSERT INTO games VALUES (3220, 774511, 'Megadimension Neptunia VIIR', 'This enhanced version of 2016’s Megadimension Neptunia™ VII features smoother graphics courtesy of a new engine, a revamped battle system, and a whole new VR experience. Now, their dimensions and yours are connected!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/774511/header.jpg?t=1730845112', 0, 0, NULL);
INSERT INTO games VALUES (3222, 774541, 'Species: Artificial Life, Real Evolution', 'Play with evolution! Species: ALRE is a scientifically-grounded, emergent simulation of natural selection. Creatures evolve and speciate in response to in-game mutation and selection forces, allowing you to experience and tinker with evolution in real-time.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/774541/header.jpg?t=1570386790', 0, 0, NULL);
INSERT INTO games VALUES (3225, 774651, 'MIGHTY GUNVOLT BURST', 'Enter a virtual world of cyber-landscapes and unravel the mystery behind its creation! &quot;Mighty Gunvolt Burst&quot; is a retro-style 2D side-scrolling action game with an authentic feel. Play as &quot;Beck,&quot; &quot;Gunvolt,&quot; or &quot;Ekoro,&quot; and experience their new stories in this unique parallel universe.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/774651/header.jpg?t=1667207469', 0, 0, NULL);
INSERT INTO games VALUES (3205, 774791, 'Surgeon Simulator 2', 'It’s time to ‘scrub in’ in this physics-based surgery sim. Unearth the mysteries of the Bossa Labs Medical Facility and save Bob’s life.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/774791/header.jpg?t=1732133384', 1, 0, NULL);
INSERT INTO games VALUES (3206, 774801, 'Crab Champions', 'Claw your way across exotic islands combining fluid movement with fast paced combat to become a Crab Champion in this third person roguelike shooter.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/774801/header.jpg?t=1743354499', 0, 0, NULL);
INSERT INTO games VALUES (3207, 774811, 'YUMENIKKI -DREAM DIARY-', 'As long as I have dreams in my heart, I can never escape. I can never awaken from my dreams. Maybe if I follow the dream just past this doorway, then someday I can wake up again...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/774811/header.jpg?t=1749557593', 1, 0, NULL);
INSERT INTO games VALUES (3196, 775500, 'SCARLET NEXUS', 'Choose between Yuito and Kasane, elite psionics each armed with a talent in psychokinesis and their own reason to fight. Complete both of their stories to unlock all the mysteries of a Brain Punk future caught between technology and psychic abilities.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/775500/header.jpg?t=1703662938', 1, 0, NULL);
INSERT INTO games VALUES (3175, 775900, 'MotoGP™18', 'Become the star of the 2018 MotoGP™! Compete as a professional rider and race against all the champions of the MotoGP™ on 19 official tracks. Enjoy an even more immersive gaming experience thanks to the new features introduced in the game.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/775900/header.jpg?t=1728477141', 0, 0, NULL);
INSERT INTO games VALUES (3178, 775940, 'Rise of Liberty', 'Rise of Liberty is a FPS single-player massive Revolutionary War battle simulator. Fire deafening cannons into the thick of the battle, stand in line formation and fire devastating volleys into the enemy. Gather your men for these monumental battles and defeat the enemy!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/775940/header.jpg?t=1632524848', 1, 0, NULL);
INSERT INTO games VALUES (3153, 776340, 'Gay World', '2 Minigames - In 1 mode you play as a officer Gaypolice who must arrest all straight people. In 2 modes you play as a straight person, travelling to GAYLAG, where you need to squat on bottles.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/776340/header.jpg?t=1695905319', 0, 0, NULL);
INSERT INTO games VALUES (3160, 776490, '永远消失的幻想乡 ～ The Disappearing of Gensokyo', '&quot;The Disappearing of Gensokyo&quot; is a Touhou Project doujin game from MyACG Studio, a Chinese doujin game fan circle. We have re-imagined Touhou as an ARPG, creating this &quot;Danmaku-Shooting-ARPG&quot;. We hope this game will be a good experience for those who are both new and knowledgeable of Touhou!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/776490/header.jpg?t=1667007869', 1, 0, NULL);
INSERT INTO games VALUES (3142, 776960, 'Mouse (Sneaking)', 'In this runner game, you play as a mouse who has stolen cheese as much as you can.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/776960/header.jpg?t=1691507119', 1, 0, NULL);
INSERT INTO games VALUES (3108, 777150, 'Adventure Land - The Code MMORPG', 'Adventure Land is an experimental Indie MMORPG. ANYONE can Code not just one, but up to 4 characters! You can play manually, use the given default Javascript Code, or learn programming to do more! Going open-source at 10,000 installs!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/777150/header.jpg?t=1671375251', 0, 0, NULL);
INSERT INTO games VALUES (3124, 777390, 'Flyout', 'Build and fly realistic aircraft. Use free-form fuselage and wing editor tools and tune your engines to recreate aircraft from any era or design your own.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/777390/header.jpg?t=1700236817', 0, 0, NULL);
INSERT INTO games VALUES (3129, 777470, 'The Infinite Black 2', 'Command a fleet of ships to hunt aliens, trade resources and loot treasure! Form corporations with your friends while fighting a never-ending intergalactic war in this open-world online space adventure!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/777470/header.jpg?t=1702313783', 0, 0, NULL);
INSERT INTO games VALUES (3100, 777770, 'WAR PARTY', 'War Party is a strategy game where you enter a prehistoric world of Dinosaurs, Cavemen and Magic! Build up your chosen faction, gather resources, explore the land and command them against enemy tribes and wildlife! Will your story be about Life, Death or Balance? Can you survive?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/777770/header.jpg?t=1749489416', 0, 0, NULL);
INSERT INTO games VALUES (3081, 778330, 'Squirm', 'After a previous adventure, you and your rat friend stop for a snooze. When you wake up, the rat is gone and strange creatures have appeared across the land as if from out of nowhere! What has happened while you were asleep? Where is your rat friend?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/778330/header.jpg?t=1612575161', 0, 0, NULL);
INSERT INTO games VALUES (3085, 778390, 'Corpse Party: Book of Shadows', 'An anthology series that serves as a Corpse Party sequel, prequel, midquel, and alternate universe tale all in one. Rejoin old friends for a deeper dive into the haunted halls of Heavenly Host Elementary...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/778390/header.jpg?t=1731452686', 0, 0, NULL);
INSERT INTO games VALUES (3086, 778400, 'Corpse Party: Sweet Sachiko''s Hysteric Birthday Bash', 'Vengeful spirit Sachiko Shinozaki is having a birthday bash, and the lovable cast of damned souls from the Corpse Party series is invited! Join the revelers as they do their best to keep Sachiko happy and survive her twisted games in this midquel to Corpse Party and Corpse Party: Book of Shadows.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/778400/header.jpg?t=1732213611', 0, 0, NULL);
INSERT INTO games VALUES (3057, 778610, 'Foto Flash', 'Foto Flash is an adventure game about two things: HOT BABES and FUNKY TRACKS. If you''re into that then this is the game for you! Can you get enough photos in time to save the pin-up magazine? Explore the streets of Sala City and meet a cast of quirky characters in this tongue-in-cheek adventure.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/778610/header.jpg?t=1528411252', 0, 0, NULL);
INSERT INTO games VALUES (3035, 779090, 'Umfend', 'The glass sphere burst in the night of 1996. The world of distortion opened its gates and took away from you someone very important. However, in 2005, the past emerges again to hunt you once more. An atmospheric horror about love and time.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/779090/header.jpg?t=1736087392', 0, 0, NULL);
INSERT INTO games VALUES (3039, 779130, 'Virtual Fighting Championship (VFC)', 'VFC captures the spirit of classics like Street Fighter and Tekken with a fresh VR twist. Enjoy finely tuned gameplay that rewards real-life skills while delivering exciting, over-the-top action. Play online or train with unique NPCs—jump in and have fun your way! discord at discord.gg/2r9tz4b', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/779130/header.jpg?t=1732315593', 0, 0, NULL);
INSERT INTO games VALUES (3002, 779330, 'Ninja Tycoon', 'Recruit Ninjas, Hire Workers, build your base, train your Ninjas and send them on Missions!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/779330/header.jpg?t=1725191268', 1, 0, NULL);
INSERT INTO games VALUES (3003, 779340, 'Total War: THREE KINGDOMS', 'Total War: THREE KINGDOMS is the first in the award-winning series to recreate epic conflict across ancient China. Combining a gripping turn-based campaign of empire-building &amp; conquest with stunning real-time battles, THREE KINGDOMS redefines the series in an age of heroes &amp; legends.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/779340/header.jpg?t=1740720569', 1, 0, NULL);
INSERT INTO games VALUES (3007, 779430, 'Full Ace Tennis Simulator', 'Full Ace Tennis Simulator is for those seeking unequaled tennis depth and fun.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/779430/header.jpg?t=1713850629', 0, 0, NULL);
INSERT INTO games VALUES (3014, 779590, 'Scavenger SV-4', 'Scavenger SV-4 is a highly replayable atmospheric first-person science fiction game. Part simulator, part roguelike, it has elements of action, combat, resource management, and a dash of horror. It is not quite like any game you have played before.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/779590/header.jpg?t=1720905437', 0, 0, NULL);
INSERT INTO games VALUES (2973, 780210, 'Freeways', 'You are a traffic engineer. Draw freeway interchanges. Optimize for efficency and avoid traffic jams!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/780210/header.jpg?t=1740437151', 0, 0, NULL);
INSERT INTO games VALUES (2976, 780280, 'Summer Funland', 'Get ready for the awesome VR experience that is Summer Funland! Spectacular attractions and pure fun abound. A crazy rollercoaster, hilarious mini-games, an incredibly fast-paced motorcycle ride through Gotham, underwater voyage and space trip – Summer Funland will blow you away!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/780280/header.jpg?t=1606724384', 0, 0, NULL);
INSERT INTO games VALUES (2977, 780290, 'Gloomhaven', 'Lead your band of mercenaries in the land of Gloomhaven, work with unsavoury individuals, shape the fate of the region, fight your way through horrific places and get rich or die trying in this ruthless Tactical-RPG.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/780290/header.jpg?t=1741257524', 0, 0, NULL);
INSERT INTO games VALUES (2979, 780350, 'Unruly Heroes', 'LET''S KUNG FU THEM ALL! Play solo or co-op and take control of four unlikely heroes that battle a diverse lineup of enemies, show off your Kung-Fu skills and journey west across stunning different environments in order to hunt for the scattered remnants of the Sacred Scroll.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/780350/header.jpg?t=1639664687', 1, 0, NULL);
INSERT INTO games VALUES (2984, 780500, 'Suzy Cube', '3-D platforming perfection full of variety, peril and smiles around every corner!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/780500/header.jpg?t=1726073424', 1, 0, NULL);
INSERT INTO games VALUES (2955, 780750, 'Snake Classic', 'We all know we love snakes, right? Even if you afraid of snakes, u was in love by playing Snake game on your mobile phones while you was young. There was no sensor screen by the way, and all the buttons u press was manually pressed. And it was like playing piano - incredible!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/780750/header.jpg?t=1528049846', 0, 0, NULL);
INSERT INTO games VALUES (2934, 781130, 'Creatura', 'Seed, Breed, Create. From single cell organisms to complex ecosystems. Evolve every part of your own unique aquarium / terrarium by applying scientifically accurate principles of natural and artificial selection, in Creatura - ultimate Virtual Evolution Vivarium Simulator.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/781130/header.jpg?t=1742376204', 1, 0, NULL);
INSERT INTO games VALUES (2911, 781480, 'Tech Support: Error Unknown', 'Things are not what they seem at your new tech support specialist job. While resolving customer issues, you soon find yourself in the middle of a conspiracy. Will you side with your employer, join a rogue hacktivist group bent on destroying them, assist the police or stand alone?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/781480/header.jpg?t=1725031838', 0, 0, NULL);
INSERT INTO games VALUES (2902, 782140, 'Re-Legion', 'Become The Prophet in a world of the future without the future! Lead your Cult in this cyberpunk RTS in the fight against evil corporations and heretics. Choose your creed, convert citizens, create an army and take over the city!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/782140/header.jpg?t=1721723687', 0, 0, NULL);
INSERT INTO games VALUES (2906, 782250, 'Hush Hush - Only Your Love Can Save Them', 'A Visual Novel with a twist - improve skills, charm girls, and learn dangerous secrets... by any means necessary.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/782250/header.jpg?t=1741049164', 0, 0, NULL);
INSERT INTO games VALUES (2909, 782330, 'DOOM Eternal', 'Hell’s armies have invaded Earth. Become the Slayer in an epic single-player campaign to conquer demons across dimensions and stop the final destruction of humanity. The only thing they fear... is you.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/782330/header.jpg?t=1702308063', 1, 0, NULL);
INSERT INTO games VALUES (2859, 783170, 'INSOMNIA: The Ark', 'INSOMNIA is a dieselpunk sci-fi RPG about the slowly degrading remnants of human society attempting to survive on an abandoned space metropolis. Develop your character, explore lovingly handcrafted locations, interact with peculiar NPCs and factions and try to stay alive in this brutal world.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/783170/header.jpg?t=1733910510', 0, 0, NULL);
INSERT INTO games VALUES (2862, 783210, 'Aggressors: Ancient Rome', 'A mix of deep gameplay and rich historical flavor, Aggressors: Ancient Rome lets you relive history as the ruler of one of the mighty civilizations of the ancient Mediterranean. Choose one of twenty available factions and conquer the world.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/783210/header.jpg?t=1726262611', 0, 0, NULL);
INSERT INTO games VALUES (2852, 783590, 'Age of Gladiators II: Rome', 'Age of Gladiators II: Rome is a single-player strategy/management sim set at the height of the bloody gladiatorial games in ancient Rome. As your fighters increase in level, it will be up to you to decide how to forge their attributes and abilities. Build your story. Build your empire.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/783590/header.jpg?t=1742987174', 0, 0, NULL);
INSERT INTO games VALUES (2829, 783840, 'Lakeview Valley', 'Murder rpg set in the small town of Lakeview Valley. Become the most popular home-owner or succumb to your dark desires. The choice is yours.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/783840/header.jpg?t=1593170914', 0, 0, NULL);
INSERT INTO games VALUES (136159, 784080, 'MechWarrior 5: Mercenaries', 'The year is 3015. The battlefields are dominated by war machines known as BattleMechs. Level entire cities and decimate the enemy in your BattleMech. Follow a quest for glory and revenge. Manage an expanding mercenary company. Fight alongside your friends with a four-player PvE co-op.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/784080/header.jpg?t=1726272873', 0, 0, NULL);
INSERT INTO games VALUES (2842, 784150, 'Workers & Resources: Soviet Republic', 'Build a soviet republic from an impoverished country into a rich industrial superpower in a city builder with intricate production chains and a fully simulated global economy. Manage the lives of your citizens from education to work and party loyalty to criminal activity.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/784150/header.jpg?t=1749229464', 1, 0, NULL);
INSERT INTO games VALUES (2820, 785260, 'Team Sonic Racing™', 'Team Sonic Racing combines the best elements of arcade and fast-paced competitive style racing as you face-off with friends in intense multiplayer racing.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/785260/header.jpg?t=1704380717', 1, 0, NULL);
INSERT INTO games VALUES (2794, 785480, 'Titanic: Adventure Out Of Time', 'Intrigue and adventure await you on board the Titanic, the most famous ocean liner in history. As a British secret agent on a vital mission, it is up to you to change the course of history as you explore the world’s most luxurious ocean vessel in all its original splendour.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/785480/header.jpg?t=1569518079', 0, 0, NULL);
INSERT INTO games VALUES (2799, 785740, 'This Is the Police 2', 'Interpret the law as you see fit! Run the sheriff’s department, manage your cops, make tough decisions – and try to keep out of prison yourself – in this story-driven mixture of adventure, strategy, and turn-based tactical combat.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/785740/header.jpg?t=1727253481', 1, 0, NULL);
INSERT INTO games VALUES (2802, 785770, 'Emergency Call 112 – The Fire Fighting Simulation 2', 'Emergency Call 112 – The Fire Fighting Simulation 2 is the consequent further development of the successful first part, which lets every Firefighter Fan experience the way a professional fire brigade works.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/785770/header.jpg?t=1744019378', 0, 0, NULL);
INSERT INTO games VALUES (2804, 785790, 'WHAT THE GOLF?', 'A silly physics-based golf parody where every golf course is a new surprising type of golf, some brilliant or hilarious, others so absurd you will ask yourself: WHAT THE GOLF?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/785790/header.jpg?t=1738146767', 1, 0, NULL);
INSERT INTO games VALUES (2807, 785850, 'Valthirian Arc: Hero School Story', 'Build a school for RPG heroes in a mix of simulation and role-play adventure. As Principal of a school for the warriors and mages of the future, you must build your Academy to train the best in the land. Place and upgrade facilities, form teams of the best students and send them out on epic quests!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/785850/header.jpg?t=1741786623', 1, 0, NULL);
INSERT INTO games VALUES (2810, 785880, 'OVERWHELM', 'You''re outnumbered, low on ammunition and the paranoia sets in. This is an action horror-world where enemies get power-ups and you don’t.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/785880/header.jpg?t=1572457100', 0, 0, NULL);
INSERT INTO games VALUES (2811, 785890, 'Hexologic', 'Immerse yourself in the beautiful world of Hexologic. Solve challenging, yet rewarding puzzles, listen to relaxing music, dive deep into the game’s atmosphere and fall in love in with Sudoku again!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/785890/header.jpg?t=1742551852', 1, 0, NULL);
INSERT INTO games VALUES (2752, 786520, 'SAO Utils: Beta', 'SAO Utils provides you a customizable Full-Dive 3D app launcher with varieties of themes, desktop widgets and powerful utilities.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/786520/header.jpg?t=1667681548', 0, 0, NULL);
INSERT INTO games VALUES (2755, 786580, 'Gleaner Heights', 'Experience the old-school charm of classic farming games with the suburban gothic atmosphere of certain 90''s TV shows, along with contemporary game mechanics. Farming, crafting, combat, romantic relationships and mysterious events await!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/786580/header.jpg?t=1667031435', 0, 0, NULL);
INSERT INTO games VALUES (2737, 787070, 'Super Ledgehop: Double Laser', 'Cutie anime girl realizes her cool big bro is missing?? Cheese it up with Chizuru and SHOOT TO THE BEAT OF THE SONG in this top down bullet hell shooter! Absorb enemy bullets using your waveshines to utilize their bullets as your own! Show those cheeseheads that you''re better!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/787070/header.jpg?t=1732217858', 0, 0, NULL);
INSERT INTO games VALUES (2721, 787480, 'Phoenix Wright: Ace Attorney Trilogy', 'Become Phoenix Wright and experience the thrill of battle as you fight to save your innocent clients in a court of law. Play all 14 episodes, spanning the first three games, in one gorgeous collection.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/787480/header.jpg?t=1727757690', 1, 0, NULL);
INSERT INTO games VALUES (2722, 787510, 'Muv-Luv Alternative Total Eclipse Remastered', 'As mankind races to create new weapons to turn the tide in its war against alien invaders, Yuuya, a hot-headed American pilot, is assigned to work with a beautiful but cold Japanese officer on a top-secret project. Can they learn to work together in time to make the weapon that saves us all?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/787510/header.jpg?t=1740993794', 0, 0, NULL);
INSERT INTO games VALUES (2691, 787740, 'Construction Simulator 2 US - Pocket Edition', 'The mobile hit Construction Simulator 2 is available on Steam! Experience one of the most comprehensive construction simulators for mobile devices, optimized for your PC.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/787740/header.jpg?t=1741870042', 1, 0, NULL);
INSERT INTO games VALUES (2696, 787810, 'Rogue Heroes: Ruins of Tasos', 'Rogue Heroes is a topdown, roguelite adventure game inspired by the Zelda franchise. Play solo or team up with your friends to combat procedurally generated dungeons and take down the evil Titans that threaten to overwhelm the land of Tasos!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/787810/header.jpg?t=1729002478', 0, 0, NULL);
INSERT INTO games VALUES (2699, 787860, 'Farming Simulator 19', 'The best-selling franchise takes a giant leap forward with a complete overhaul of the graphics engine, offering the most striking and immersive visuals and effects, along with the deepest and most complete farming experience ever.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/787860/header.jpg?t=1674664652', 1, 0, NULL);
INSERT INTO games VALUES (2701, 787930, 'American Railroads - Summit River & Pine Valley', 'Buy - Transport - Profit: Manage your own late 1800s railroad company, load and deliver freight, customize your vehicles and invest in upgrades while enjoying the realistic driving- and physics experience in a majestic mountain scenery.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/787930/header.jpg?t=1667206267', 0, 0, NULL);
INSERT INTO games VALUES (2713, 788100, 'Neon Abyss', 'Neon Abyss is a frantic, roguelite action-platformer where you run ‘n’ gun your way into the Abyss. Featuring unlimited item synergies and a unique dungeon evolution system, each run diversifies the experience and every choice alters the ruleset.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/788100/7105869c3cf24c4fe65284ba978e23d2f691c372/header.jpg?t=1749365999', 0, 0, NULL);
INSERT INTO games VALUES (2672, 788270, 'Exiled Kingdoms', 'Roam freely through a huge open world full with dangers, ancient secrets and adventure. An old-school action-RPG with a challenging environment, tough choices and a unique setting. Explore, fight, make friends and enemies... and above all, Roleplay!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/788270/header.jpg?t=1583416492', 0, 0, NULL);
INSERT INTO games VALUES (2647, 788630, 'Gaia Beyond', 'Gaia Beyond is a handcrafted 2D Action-RPG, an exploration mix built around the core features fighting, mining and trading. Your decisions are footprints within a vast non-linear solar system. Forge alliances among numerous factions and develop relations with hundreds of NPCs.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/788630/header.jpg?t=1715826689', 0, 0, NULL);
INSERT INTO games VALUES (2650, 788690, 'Psychonauts in the Rhombus of Ruin', 'Psychonauts in the Rhombus of Ruin is an all-new Virtual Reality adventure that takes players back into the mysterious and paranormal world of the Psychonauts for the first time in over ten years!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/788690/header.jpg?t=1727390435', 0, 0, NULL);
INSERT INTO games VALUES (2651, 788700, 'ValeGuard', 'ValeGuard is an RTS, Town-Management hybrid game that combines Turn-Based City-Building with Real-Time Combat. Each day you construct your defenses, train troops, and prepare for attack. When enemies come in the night, you defend with towers, troops, and heroes with powerful abilities.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/788700/header.jpg?t=1667839988', 0, 0, NULL);
INSERT INTO games VALUES (2616, 789660, 'Buggos', 'Lead your hive to victory in ''Buggos'', an RTS Auto Battler! Customize your swarm with 120+ evolutions and conquer humanity. Strategy meets bug chaos!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/789660/header.jpg?t=1733265442', 0, 0, NULL);
INSERT INTO games VALUES (2625, 789760, 'DEAD OR SCHOOL', 'Underground dwelling girl Hisako is aiming for the surface in a zombie infested Tokyo. Hack and slash RPG! Obtain weapons and gear from enemies, and customize your skill tree to create your own unique and powerful a character!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/789760/header.jpg?t=1601950406', 0, 0, NULL);
INSERT INTO games VALUES (2587, 790060, 'The Void Rains Upon Her Heart', 'Help her heart battle tough bosses in this Boss Rush, Bullet-hell with rogue-like elements. Fight through several randomly chosen boss battles leading up to a final battle. Each defeated monster will give her random gifts that power up her heart. Don''t let her heart break!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/790060/header.jpg?t=1737510154', 0, 0, NULL);
INSERT INTO games VALUES (2561, 790410, 'Futanari Quest', 'Futanari Quest is a hot hentai RPG with yuri themes. Take the role of Yui, a young woman who is blessed/cursed with a brand-spanking-new dick!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/790410/header.jpg?t=1697188245', 0, 0, NULL);
INSERT INTO games VALUES (2564, 790540, 'THE QUIET MAN™', 'THE QUIET MAN™ delivers an immersive story driven cinematic action experience seamlessly blending high-production live action, realistic CG and pulse-pounding action gameplay.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/790540/header.jpg?t=1562596695', 1, 0, NULL);
INSERT INTO games VALUES (2573, 790740, 'Tick Tock: A Tale for Two', 'You and your friend are trapped in a mystical world. As time ebbs away you must solve increasingly complex puzzles to escape. Cooperation is key as neither of you have the full picture! Play on two devices, local or remotely, all you need is a voice connection.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/790740/header.jpg?t=1732790016', 1, 0, NULL);
INSERT INTO games VALUES (2539, 790820, 'Valkyria Chronicles 4 Complete Edition', 'A Continent Engulfed in the Bitter Flames of War! Commander Claude Wallace and his childhood friends set out to fight in a desperate war, but bone-chilling blizzards, waves of imperial soldiers, and the godlike powers of the Valkyria stand between them and victory.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/790820/header.jpg?t=1722504577', 1, 0, NULL);
INSERT INTO games VALUES (2541, 790850, 'Undead Horde', 'Become a necromancer and raise the dead - Undead Horde is a necromantic action game with elements from RPG, strategy and hack''n''slash. Maraud through the lands of the living, raze their villages and steal their treasures. Ultimately you''ll take over the whole kingdom of the living!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/790850/header.jpg?t=1725017054', 1, 0, NULL);
INSERT INTO games VALUES (2556, 791180, '1 Screen Platformer', 'This is a SHORT, 2D PLATFORMER with TIGHT CONTROLS about exploring a single level to get past a bunch of TRAPS. There is an EASY mode and a HARD mode depending on your skill level.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/791180/header.jpg?t=1601939209', 0, 0, NULL);
INSERT INTO games VALUES (2523, 791330, 'Fallen ~Makina and the City of Ruins~', 'Fallen takes you on an adventure with Makina into the Ruins of Gardona. What fate awaits Makina and her friends on their travels as they descend further into the ruins? Find out in this JRPG classic!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/791330/header.jpg?t=1749034321', 0, 0, NULL);
INSERT INTO games VALUES (2501, 791770, 'Try To Fall Asleep', 'John Herrin survived a horrible accident, damaging his brain and memory. Through falling asleep, he can rediscover his unfortunate past in his dreams, but due to his brain damage he''ll start to see visions and hallucinations, and falling asleep won''t be as easy as it seems at first...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/791770/header.jpg?t=1736594594', 0, 0, NULL);
INSERT INTO games VALUES (2511, 792040, 'Detective Di: The Silk Rose Murders', 'A thrilling point-and-click adventure game where you play as Di Renjie, ancient China''s most famous and gifted investigator, as he tracks a serial killer in the heart of the Tang Dynasty''s capital city.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/792040/header.jpg?t=1645121224', 0, 0, NULL);
INSERT INTO games VALUES (2515, 792100, '7 Billion Humans', 'Automate swarms of office workers to solve puzzles inside your very own parallel computer made of people. A thrilling followup to the award winning Human Resource Machine. Now with more humans!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/792100/header.jpg?t=1667105092', 1, 0, NULL);
INSERT INTO games VALUES (2516, 792120, 'FIGHT KNIGHT', 'FIGHT KNIGHT is a first-person dungeon-brawler! Grid-based dungeon crawling meets action-packed real time enemy encounters. Fight your way through puzzles and enemies to save those trapped in the Tower''s eternal night!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/792120/header.jpg?t=1667599530', 0, 0, NULL);
INSERT INTO games VALUES (2484, 792300, 'The Beast Inside', 'The Beast Inside is a unique, gripping twist on thriller and survival horror. Immerse in the story of long-buried secrets, personal tragedies, and madness. Play as two protagonists bounded by dark heritage. Combat the enemies, solve riddles and experience real terror in the 3D-scanned environment.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/792300/header.jpg?t=1669227434', 0, 0, NULL);
INSERT INTO games VALUES (2451, 792660, 'The Operational Art of War IV', 'The Operational Art of War IV is the new generation of operational wargames. With more flexibility than before and with a new array of exciting features, it will make you relive the most iconic battles from the dawn of the 20th Century to modern day, including the ones that never occurred!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/792660/header.jpg?t=1575553567', 0, 0, NULL);
INSERT INTO games VALUES (2454, 792710, 'Levelhead: Platformer Maker', 'Deliver those goods, real good - or get turned into scrap trying! Precision platforming, genre-bending power-ups, a challenging campaign, and a galaxy full of jokes await you in Levelhead!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/792710/header.jpg?t=1748617917', 1, 0, NULL);
INSERT INTO games VALUES (2472, 792990, 'Identity', 'Identity is a new breed of massively multiplayer online role-playing game where hundreds of players interact in a world of absolute freedom. It''s the actions of players which determine your fate and the fate of the world you live in.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/792990/header.jpg?t=1661647538', 0, 0, NULL);
INSERT INTO games VALUES (2441, 793350, 'Swarmlake', 'Swarmlake is an ultra-intense first-person shooter ballet about fighting a record-breaking swarm.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/793350/header.jpg?t=1695751879', 1, 0, NULL);
INSERT INTO games VALUES (2442, 793370, 'KIDS', 'A game of crowds.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/793370/header.jpg?t=1749298219', 1, 0, NULL);
INSERT INTO games VALUES (2447, 793460, '112 Operator', 'Manage emergency services in any city in the world! Take calls and dispatch rescue forces. Handle difficult situations, now depending on the weather, and traffic. Help the citizens through cataclysms and natural disasters, becoming a better emergency number operator every day!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/793460/header.jpg?t=1726474654', 1, 0, NULL);
INSERT INTO games VALUES (2423, 793690, 'Final Assault', 'Final Assault is a WWII themed Action Strategy Game that capitalizes on the full power of Virtual Reality. Command massive ground battles as the skies erupt in dynamic dog fights and bombing runs. Combat requires quick thinking and fast reflexes. Fight the battle, win the war!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/793690/header.jpg?t=1738081107', 0, 0, NULL);
INSERT INTO games VALUES (2402, 794260, 'Outward Definitive Edition', 'No remarkable journey is achieved without great effort. In Outward, the cold of the night or an infected wound can be as dangerous as a predator lurking in the dark. Explore the vast world of Aurai solo or in Co-op. The Definitive Edition features both DLCs and quality of life improvements.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/794260/header.jpg?t=1725433863', 1, 0, NULL);
INSERT INTO games VALUES (2376, 794490, 'Journey Of Life', 'You have experienced the sudden loss of your wealth, which has compelled you to abandon your previous life and begin anew. By venturing into the game world, you can construct settlements and forge alliances with other players, ensuring that you will always have exciting challenges to undertake.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/794490/header.jpg?t=1677446504', 0, 0, NULL);
INSERT INTO games VALUES (2378, 794540, 'Neo Cab', 'A visual novel about emotional survival in an automated world. Play as Lina, the last human cab driver. It’s your first night driving the lonely streets of Los Ojos, and your best friend has just disappeared. Stay on the road. Stay on the search. Stay human.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/794540/header.jpg?t=1729758784', 1, 0, NULL);
INSERT INTO games VALUES (2379, 794550, 'Grapple Force Rena', 'Swing, climb, grab, and throw in this action platformer where you can grapple anywhere! Using Rena''s magic bracelets, hook onto any surface to swing wherever you like, or grab your foes to send them hurtling into each other!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/794550/header.jpg?t=1745528120', 0, 0, NULL);
INSERT INTO games VALUES (2381, 794580, 'SNK HEROINES Tag Team Frenzy', 'Take control of SNK’s most iconic female characters and battle it out in this crazy tag fighting game featuring a plethora of cute costumes and accessories! With one button special moves and a deep but simplified combo system this is a great game for fighting game fans and newcomers alike!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/794580/header.jpg?t=1572597745', 1, 0, NULL);
INSERT INTO games VALUES (2391, 794800, 'Clue/Cluedo: Classic Edition', 'The official digital version of Hasbro’s classic mystery board game, Cluedo (Clue). Roll the dice and launch into a murder investigation. Whodunit? With what weapon? Where? You’ll need all your brain power to find the answers you need, as you race your friends and family to the truth!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/794800/b53a7b2070558728da452e83322028e617085c72/header.jpg?t=1748350571', 0, 0, NULL);
INSERT INTO games VALUES (2396, 794860, 'eSail Sailing Simulator', 'eSail Sailing Simulator is an authentic yacht sailing experience with numerous tutorials, sailing, mooring and anchoring modes, charting, challenges, races, Live Sailing mode, ''Learn Yachting with eSail'' and more.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/794860/header.jpg?t=1740408837', 0, 0, NULL);
INSERT INTO games VALUES (2362, 794960, 'The Sojourn', 'The Sojourn is a first-person puzzle game set in an immersive colour-drenched world of light and darkness. Think your way through dozens of puzzles as you traverse parallel worlds, awaken mysterious artifacts and overcome challenging obstacles on an unforgettable journey.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/794960/header.jpg?t=1725031362', 0, 0, NULL);
INSERT INTO games VALUES (2373, 795420, 'The Darkside Detective: A Fumble in the Dark', 'Delouse your room with sage and pack up your travel-sized ouija board, it’s time to re-enter Twin Lakes - America’s 34th most haunted city. Join Detective McQueen as he puzzles his way through 9 chilling cases, risking life and pixelated limb to solve the macabre mysteries that plague the poor town.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/795420/header.jpg?t=1746828483', 0, 0, NULL);
INSERT INTO games VALUES (2285, 796860, 'Police Enforcement VR : 1-King-27', 'Police Simulator Built From The Ground Up For Virtual Reality!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/796860/header.jpg?t=1665690986', 0, 0, NULL);
INSERT INTO games VALUES (2289, 796940, 'Red Embrace', 'A normal graveyard shift at a dingy diner in San Francisco... until a mysterious customer arrives, bringing with him a war between vampires.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/796940/header.jpg?t=1612041851', 0, 0, NULL);
INSERT INTO games VALUES (2247, 798290, 'MXGP PRO', 'Adjust your bike''s configuration like a mechanic and win a race with the new Pro Physics. Practice in the Compound, a vast area where you can freely explore or compete against the AI. All the official tracks and riders from the 2017 season await you!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/798290/header.jpg?t=1728478979', 0, 0, NULL);
INSERT INTO games VALUES (2252, 798460, 'Ni no Kuni Wrath of the White Witch™ Remastered', 'Journey back to the other world in Ni no Kuni: Wrath of the White Witch™ Remastered. LEVEL-5’s classic tale returns better than ever, with improved graphics and performance.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/798460/header.jpg?t=1719503515', 0, 0, NULL);
INSERT INTO games VALUES (2255, 798490, 'Othercide', 'As Humanity’s last hope, lead your army to combat in an intricate dance of spectacular actions and counters, using an original Dynamic Timeline System, and face fearsome bosses in epic battles.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/798490/header.jpg?t=1748892649', 1, 0, NULL);
INSERT INTO games VALUES (2256, 798510, 'SUPER DRAGON BALL HEROES WORLD MISSION', 'SUPER DRAGON BALL HEROES WORLD MISSION is a Tactical-Card game packed with exhilarating confrontation, deep card game strategy and a thrilling storyline taking place in the wide Dragon Ball Heroes universe!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/798510/header.jpg?t=1747851825', 0, 0, NULL);
INSERT INTO games VALUES (2243, 798810, 'Natural Locomotion', 'Move naturally in virtual reality in any SteamVR game that supports trackpad/stick locomotion. More immersion, more comfort!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/798810/header.jpg?t=1664605878', 0, 0, NULL);
INSERT INTO games VALUES (129476, 798840, 'Panzer War : Definitive Edition', 'Panzer War delivers intense tank combat, featuring a realistic damage system where every hit counts. Skip the grind—access all tanks instantly and dive into battle. Unleash your creativity with the Tank and Map Designer, crafting custom scenarios for endless gameplay possibilities.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/798840/header.jpg?t=1724776074', 1, 0, NULL);
INSERT INTO games VALUES (2224, 799070, 'Zup! 8', 'Minimal physical puzzle with explosions', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/799070/header.jpg?t=1674747595', 1, 0, NULL);
INSERT INTO games VALUES (2202, 799510, 'Squidlit', 'Every day is a wonderful day for invertebrates! Come join the Squidlits of Blipston for a squishy adventure of spoopy castles, muffins, and wiggles! Made with classic handheld technology in mind, Squidlit strives to be the closest modern recreation of GameBoy game-design methods on the market.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/799510/header.jpg?t=1639522884', 0, 0, NULL);
INSERT INTO games VALUES (2208, 799600, 'Cosmoteer: Starship Architect & Commander', 'Design and simulate the starships of your dreams! Command your ship or fleet in epic battles and manage your crew while exploring a dangerous galaxy. Play alone or with friends, test your ships in online PvP, and let your imagination reach for the stars!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/799600/header.jpg?t=1747786985', 0, 0, NULL);
INSERT INTO games VALUES (2211, 799640, 'Dungeon Munchies', 'Hunt down monsters to cook and eat them! You’ve been revived in a massive underground complex and you must leave this bizarre facility. Aided by the undead Necro-Chef Simmer, you must stay safe, get fed, find a way to get out', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/799640/header.jpg?t=1734081207', 1, 0, NULL);
INSERT INTO games VALUES (2194, 800270, 'Terraforming Mars', 'The taming of the Red Planet has begun! Corporations are competing to transform Mars into a habitable planet by spending vast resources and using innovative technology to raise temperature, create a breathable atmosphere, and make oceans of water.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/800270/header.jpg?t=1741270803', 0, 0, NULL);
INSERT INTO games VALUES (2169, 800600, 'Wayhaven Chronicles: Book One', 'Your first case as a detective is forcing you to open your eyes to a world bigger than you thought. Or maybe it''s better to keep them closed. Seems the supernatural didn’t get the memo that nothing exciting ever happens in the little town of Wayhaven.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/800600/header.jpg?t=1734033202', 0, 0, NULL);
INSERT INTO games VALUES (2170, 800620, 'Fallen Hero: Rebirth', 'They called you a hero; you call them fools. Use your telepathy romance old friends and fight new enemies as you become the greatest villain Los Diablos has ever known!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/800620/header.jpg?t=1734033216', 0, 0, NULL);
INSERT INTO games VALUES (2142, 801290, 'Diabolic', 'The game is set in a dark pixel fantasy world. Destroy hordes of monsters ruling over what once was a prosperous land. 10 levels filled with various enemies await, you, each requiring a different approach to defeat. Like in any RPG, leveling up is the core element of the game', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/801290/header.jpg?t=1531063169', 0, 0, NULL);
