INSERT INTO games VALUES (129000, 833360, 'Star Valor', 'Choose your own destiny as you explore an open-world procedurally generated galaxy where anything is possible. Become a miner, a trader, a bounty hunter, a pirate, or perhaps a jack of all trades. Start off small and build your way to the top but remember with every action, comes consequences.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/833360/header.jpg?t=1742773907', 1, 0, NULL);
INSERT INTO games VALUES (938, 834280, 'Fishing Sim World®: Pro Tour', 'Fishing Sim World: Pro Tour features an authentic career mode where you work your way up to an elite angler competing against over 100 of the best anglers in the world across Bass, Carp and Predator fishing whilst unlocking sponsorship opportunities, gaining career earnings and social media followers as you go.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/834280/header.jpg?t=1745825901', 0, 0, NULL);
INSERT INTO games VALUES (913, 834740, 'Circle Empires', 'Circle Empires is a fresh take on the RTS genre, featuring a fast-paced approach to conquering the world.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/834740/header.jpg?t=1732025776', 1, 0, NULL);
INSERT INTO games VALUES (915, 834760, 'Robot Wants It All', 'Robot wants stuff! Go get it for him in this compilation of the metroidvania Robot Wants series, including an all-new Robot adventure!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/834760/header.jpg?t=1727906788', 0, 0, NULL);
INSERT INTO games VALUES (909, 834910, 'ATLAS', 'Set sail for the ultimate pirate experience! Embark on a grand adventure alongside thousands of other players in one of the largest game worlds ever built (and even claim a piece of it to call your own). Build your ship, assemble your crew, sail the high seas, and become a pirate legend!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/834910/header.jpg?t=1694646023', 0, 0, NULL);
INSERT INTO games VALUES (896, 835430, 'La-Mulana 2', 'The long-awaited sequel to La-Mulana, La-Mulana 2 follows Lumisa Kosugi as she explores the ancient ruins of La-Mulana. Desperate to find the cause of the recent slew of monsters appearing from the ruins, Lumisa discovers the &quot;other&quot; La-Mulana: the ruins known as Eg-Lana.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/835430/header.jpg?t=1710992311', 0, 0, NULL);
INSERT INTO games VALUES (135591, 835570, 'Conqueror''s Blade', 'Conqueror''s Blade gives you a chance to be a true warlord. Commanding medieval troops in epic 15 vs. 15 siege battles, conquering cities with allies in the open world or fighting against players from all over the world – it''s you who make the choice.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/835570/c6840cc494582096a58f026e3049aa970d43c051/header.jpg?t=1746601485', 1, 1, NULL);
INSERT INTO games VALUES (133032, 835960, 'The Talos Principle 2', 'The Talos Principle 2 is a thought-provoking first-person puzzle experience that greatly expands on the first game''s philosophical themes and stunning environments with increasingly mind-bending challenges.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/835960/header.jpg?t=1744286741', 1, 0, NULL);
INSERT INTO games VALUES (866, 836450, 'Heaven Will Be Mine', 'HEAVEN WILL BE MINE is a visual novel about making terrible life decisions in the midst of a hot-blooded battle between giant robots. Select one of three terribly behaved girls to fight and/or make out with each other in their struggle for the fate of space.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/836450/header.jpg?t=1593110610', 0, 0, NULL);
INSERT INTO games VALUES (842, 837350, 'King of the Hat', 'A 2D party platformer where you fight with a hat! Throw your hat to attack, defend and bait opponents. But watch out! If someone jumps on your hat... you die!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/837350/header.jpg?t=1715111749', 1, 0, NULL);
INSERT INTO games VALUES (844, 837400, 'Fated Kingdom', 'Fated Kingdom is an old school digital board game sandbox for 2-4 players with shared physical space and no rules enforced by computer. The Kingdom of Kinmarr is falling apart, and to survive in this dark times, players need to roll the dice, draw cards from the decks and move along a game board.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/837400/header.jpg?t=1667035631', 0, 0, NULL);
INSERT INTO games VALUES (847, 837460, 'Batbarian: Testament of the Primordials', 'Batbarian: Testament of the Primordials is a snarky action-adventure puzzle game with a good dose of humor. Explore hundreds of secret-filled rooms, fight big bosses, gather companions for your party and use the powers of Pip—your bat buddy—to solve puzzles and escape the eldritch abyss!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/837460/header.jpg?t=1732066122', 1, 0, NULL);
INSERT INTO games VALUES (809, 837470, 'Untitled Goose Game', 'It''s a lovely morning in the village and you are a horrible goose.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/837470/header.jpg?t=1699052664', 1, 0, NULL);
INSERT INTO games VALUES (811, 837510, 'Pixel Game Maker MV', 'Use Pixel Game Maker MV to make your own 2D action games! The latest Maker title provides a simple, fun way to make games with zero coding! PGMMV: Powerful enough for pro developers, simple enough for beginners.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/837510/header.jpg?t=1747272033', 0, 0, NULL);
INSERT INTO games VALUES (814, 837590, 'Operation Thunderstorm', 'The year is 1942. The British government decides to launch one of the most risky operations of World War II. The targets are the most important figures of the Third Reich. After several months of research, MI6 chose three people: the chances of eliminating them are slim to nothing.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/837590/header.jpg?t=1587033959', 0, 0, NULL);
INSERT INTO games VALUES (822, 837880, 'You Suck at Parking® - Complete Edition', 'You Suck at Parking® is the only racing game where your goal is to stop and parking your ride is more important than your driving skills. It’s a hot race against the clock as you drift, cruise, and go airborne over 250 frustratingly fun, wild levels.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/837880/header.jpg?t=1747736056', 1, 0, NULL);
INSERT INTO games VALUES (801, 838310, 'Bloodstained: Curse of the Moon', 'Battle with swords and whips in this retro-style action game brought to you by game creator Koji Igarashi and Inti Creates! Play as Zangetsu, a demon slayer bearing a deep grudge, who must travel through perilous lands to defeat a powerful demon lurking in a dark castle.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/838310/header.jpg?t=1727748384', 0, 0, NULL);
INSERT INTO games VALUES (802, 838330, 'Warlords Awakening', 'Prepare yourself as you step into a world writhing in chaos. Warlords Awakening, a remastered MMORPG that will place you on a journey to become an Elite Lord with an action packed story and ominous monsters around every corner. Explore and conquer the world of Epheia together with the cute and dashing pets to choose from.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/838330/header.jpg?t=1561658705', 0, 0, NULL);
INSERT INTO games VALUES (804, 838350, '太吾绘卷 The Scroll Of Taiwu', '&quot;The Scroll of Taiwu&quot; is an indie game themed around Chinese mythology and wuxia. Players assume the role of the mysterious &quot;heir of the Taiwu clan&quot; in an alternate ancient China, working through generations of heirs to defeat a powerful hereditary enemy and shape the fate of the human world.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/838350/header.jpg?t=1747131002', 0, 0, NULL);
INSERT INTO games VALUES (806, 838380, 'DEAD OR ALIVE 6', 'DEAD OR ALIVE 6 is fast-paced 3D fighting game, produced by Koei Tecmo Games, featuring stunning graphics and multi-tiered stages that create a truly entertaining competitive experience.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/838380/header.jpg?t=1729051740', 1, 0, NULL);
INSERT INTO games VALUES (766, 838630, 'Deadliest Catch: The Game', 'Enter the dangerous world of king crab fishing in the deadly Bering Sea! Take command of your own fishing vessel, use realistic equipment, combat hazardous Alaskan waters and become the world''s best crab catcher!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/838630/header.jpg?t=1724956753', 0, 0, NULL);
INSERT INTO games VALUES (751, 839310, 'Signal Simulator', 'Game inspired by SETI. Take the role of a scientist to find an extraterrestrial signal .Control massive Radio Antennas by using interactive control in your Observatory. Detect , download and decode unknown or story telling signals. Manage and Maintain an electrical system to improve your systems and make it more efficient.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/839310/header.jpg?t=1572336684', 0, 0, NULL);
INSERT INTO games VALUES (759, 839450, '7''scarlet', 'The remote town of Okunezato is shaped like a crescent moon and shrouded in dark myths and legends. Take on the role of a brave young woman journeying into the unknown to uncover dangerous truths and locate her missing brother with her childhood friend.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/839450/header.jpg?t=1693958088', 1, 0, NULL);
INSERT INTO games VALUES (721, 839630, 'Survisland / 实境求生', 'Survisland is a super hardcore sandbox survival game that pays great attention to restoring the real survival experience. The character has rich and realistic actions and reactions to , and the process logic of making props is no different from reality.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/839630/header.jpg?t=1729136751', 0, 0, NULL);
INSERT INTO games VALUES (727, 839770, 'Phoenix Point', 'The acclaimed strategy game from the creator of X-COM. Fight tactical battles on procedural maps against a foe that adapts to your tactics. Manage diplomacy and economy on a global scale. Research, explore, overcome. Now includes Steam Workshop support for mods!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/839770/header.jpg?t=1663608331', 0, 0, NULL);
INSERT INTO games VALUES (730, 839870, 'Wilmot''s Warehouse', 'Wilmot''s Warehouse is a puzzle game about keeping a warehouse running in tip-top shape. Just remember where you put everything, because when the service hatch opens, you''ll need to find the things people want quickly, in order to earn the coveted Performance Stars.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/839870/header.jpg?t=1727168648', 0, 0, NULL);
INSERT INTO games VALUES (733, 839930, 'My Car', 'Choose from one of two different car models! Customize it in your own way, then try it on the track!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/839930/header.jpg?t=1731171731', 0, 0, NULL);
INSERT INTO games VALUES (737, 840010, 'Garden Paws', 'You have inherited your grandparents farm as they set off to travel the world. Work with Frank at the local construction shop to finish off the final touches on your new home. Aid Frank and Mayor Wilson in building up the town so it may reach it''s full potential.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/840010/header.jpg?t=1697331980', 0, 0, NULL);
INSERT INTO games VALUES (701, 840140, '武侠乂 The Swordsmen X', 'The Swordsmen X is an adrenaline-fueled free-roaming competitive action game that pits 100 players against each other in a battle royale. Players can wield a diverse arsenal of martial weapons, including bows, daggers, and other ranged attacks, in their fight for survival.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/840140/header.jpg?t=1588046169', 0, 0, NULL);
INSERT INTO games VALUES (705, 840210, 'Arkham Horror: Mother''s Embrace', 'Inspired by the award-winning board game franchise, Arkham Horror: Mother’s Embrace is an investigation game served with turn-based combat, set in the cult universe of H.P. Lovecraft.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/840210/header.jpg?t=1741270543', 0, 0, NULL);
INSERT INTO games VALUES (712, 840390, 'Spacebase Startopia', 'Spacebase Startopia captivates with its original mixture of economic simulation and empire building strategy paired with classic RTS skirmishes and a good dose of humor.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/840390/header.jpg?t=1730811193', 1, 0, NULL);
INSERT INTO games VALUES (679, 840720, 'Sword Art Online: Lost Song', 'Enter the VRMMO world of the much-loved anime SWORD ART ONLINE! In Alfheim Online, a world of fairies and magic, you become the hero of the series, Kirito, and together with your wondrous friends try to conquer the floating land of Svart Alfheim.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/840720/header.jpg?t=1700237973', 0, 0, NULL);
INSERT INTO games VALUES (682, 840800, 'Outlaws of the Old West', 'Outlaws of the Old West is a massively multiplayer survival MMO with a huge world, thousands of items and a modular building system. Survive the wild, build your own homestead, defeat villainous bandits and work with others to tame the Wild West.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/840800/header.jpg?t=1666906353', 0, 0, NULL);
INSERT INTO games VALUES (692, 840930, 'Bing Bong XL', 'Bing Bong XL is a fast-paced, minimalist arcade score chaser with simple one-button controls. Dodge obstacles, collect points, and survive as long as possible in this addictive ‘just-one-more-round’ challenge. Perfect for quick sessions or while waiting in queue for another game!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/840930/header.jpg?t=1745903664', 0, 0, NULL);
INSERT INTO games VALUES (652, 841770, 'Siralim 3', 'Siralim 3 is a mechanically deep, monster taming RPG. Summon and customize over 700 different creatures to fight for you as you battle your way through randomly generated dungeons. Find rare treasure and use it to craft new items, empower your creatures, learn new spells, and much more.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/841770/header.jpg?t=1735221113', 0, 0, NULL);
INSERT INTO games VALUES (637, 842100, 'Daymare: 1998', 'DAYMARE: 1998 is a third-person survival horror game that recreates the mood of iconic titles from the ''90s, with a fresh storyline. An incident that turns a small town into a deadly zone, three characters to play with and little time to find the truth, before its mutated citizens abruptly end your mission.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/842100/header.jpg?t=1684411952', 0, 0, NULL);
INSERT INTO games VALUES (128054, 842780, 'NavalArt', 'Design your own warships, equip them with a variety of armament, and bring them out to the ocean!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/842780/header.jpg?t=1742220057', 0, 0, NULL);
INSERT INTO games VALUES (615, 842910, 'The MISSING: J.J. Macfield and the Island of Memories', 'J.J. scours Memoria Island to find her best friend, who has gone missing during a camping trip. In order to save her best friend, she puts her own body and life on the line, reviving infinitely, as she presses forward. Why did she go missing? What is going on in this world?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/842910/header.jpg?t=1671433223', 1, 0, NULL);
INSERT INTO games VALUES (592, 843200, 'Alien Hominid Invasion', 'Old friends and bitter enemies await as you invade Earth alongside a Mothership full of alien friends! Blast, beam, and bite your way through an endless swarm of enemies as you and up to three of your fellow hominids cause mayhem with a huge arsenal of weapons, mutations, and acrobatic maneuvers.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/843200/header.jpg?t=1733783105', 1, 0, NULL);
INSERT INTO games VALUES (595, 843260, 'The Bard''s Tale Trilogy', 'The Bard''s Tale Trilogy is a complete remaster of the iconic series that helped define the RPG genre. Featuring updated graphics and optional quality of life gameplay features, this is the ideal way to experience the dungeon crawling challenge that made the original games beloved classics.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/843260/header.jpg?t=1667322591', 0, 0, NULL);
INSERT INTO games VALUES (130816, 843380, 'Super Animal Royale', 'It’s a fight for furvival! Super Animal Royale is a 64-player, frenetic, top-down 2D battle royale where murderous animals fight tooth, claw, and machine gun across an abandoned safari park.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/843380/header.jpg?t=1743700356', 1, 1, NULL);
INSERT INTO games VALUES (601, 843390, 'Vertigo 2', 'Vertigo 2 is a single-player VR adventure. Explore the depths of the vast Quantum Reactor as you descend to finish your journey home.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/843390/header.jpg?t=1732293919', 0, 0, NULL);
INSERT INTO games VALUES (604, 843430, 'Righty Tighty XL', 'Righty Tighty XL is a fast-paced, minimalist arcade score chaser with simple one-button controls. Turn right, collect points, and return them to the goal zone while dodging obstacles. An addictive ‘just-one-more-round’ challenge, perfect for quick sessions or while waiting in queue!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/843430/header.jpg?t=1745903553', 0, 0, NULL);
INSERT INTO games VALUES (605, 843440, 'Pivot XL', 'Pivot XL is a fast-paced, minimalist arcade score chaser with simple one-button controls. Pivot, dodge obstacles, and survive as long as possible in this addictive ‘just-one-more-round’ challenge. Perfect for quick sessions or while waiting in queue for another game!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/843440/header.jpg?t=1745903582', 0, 0, NULL);
INSERT INTO games VALUES (549, 844040, 'RUSH', 'Are you ready for the ultimate thrill ride? Take a dive into the adrenaline-pumping world of wingsuit flying with RUSH! Soar down mountainsides at breakneck speeds. Weave through canyons, dodge outcrops, and plummet down sheer drops as you race towards the finish line.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/844040/header.jpg?t=1567474657', 0, 0, NULL);
INSERT INTO games VALUES (559, 844260, 'Rustler (Grand Theft Horse)', 'Become a medieval thug in a crazy open-world action game, full of pop-culture references. Complete insane quests, kill heroes, steal horses, fight guards, rob peasants, listen to some bard music, and much more! All packed in old-school gameplay style!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/844260/header.jpg?t=1726271406', 1, 0, NULL);
INSERT INTO games VALUES (523, 844330, 'The Goatman', 'The Goatman is an Online CO-OP hunting game. It all began on February 23, 2019 with a call for help from the Greenfield village. It was alleged that a mysterious creature like a half goat and half demon attacked people and animals. Upon this call, a military research team set out.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/844330/header.jpg?t=1589557834', 0, 0, NULL);
INSERT INTO games VALUES (527, 844420, 'Demon''s Rise - Lords of Chaos', 'Turn-based, tactical RPG where players command a powerful band of warriors.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/844420/header.jpg?t=1604078788', 0, 0, NULL);
INSERT INTO games VALUES (534, 844590, 'Hypnospace Outlaw', 'Greetings Enforcer, and thank you for enlisting in the Hypnospace Patrol Department! As the world falls into its slumber, Hypnospace becomes a bustling global village. These virtual streets aren''t going to police themselves!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/844590/header.jpg?t=1736424814', 0, 0, NULL);
INSERT INTO games VALUES (537, 844660, 'Heart of the Woods', 'A fantasy yuri visual novel filled with magic, fairies, and a ghost girl. When Maddie and her best friend, Tara, journey to a remote forest village to investigate rumors of the supernatural, they find a whole lot more than they bargained for.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/844660/header.jpg?t=1733112624', 0, 0, NULL);
INSERT INTO games VALUES (500, 844850, 'Tower Hunter: Erza''s Trial', 'Tower Hunter: Erza’s Trial contains core elements of roguelite games, presented in a toon render style. The player explores a mysterious tower with Erza, vanquishes mutant monsters and defeats bosses to acquire a Hunter’s License and become the most powerful Battle Maiden.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/844850/header.jpg?t=1667443834', 1, 0, NULL);
INSERT INTO games VALUES (506, 844930, 'Fox Hime Zero', 'Yan, a student of natural history, encounters a cute and mysterious girl with fox ears while conducting routine scientific research at a remote observation cabin. This might be a &quot;blessing&quot; for the intrepid in the golden age of geographical discovery...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/844930/header.jpg?t=1732677098', 0, 0, NULL);
INSERT INTO games VALUES (511, 844980, 'I Am Your President', 'Play as a fictional US president in this satirical narrative strategy! Lead Democrats or Republicans to make America great again. Again.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/844980/header.jpg?t=1724766675', 0, 0, NULL);
INSERT INTO games VALUES (459, 845880, 'Touhou: Scarlet Curiosity', 'The world of Touhou comes alive in this beautiful action RPG (featuring “bullet hell” elements, of course!). Infamous vampire Remilia Scarlet and her dutiful maid, Sakuya, set off to chase rumors of a massive monster, all while sending baddies flying with fluid action and signature skills!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/845880/header.jpg?t=1731454537', 0, 0, NULL);
INSERT INTO games VALUES (460, 845890, 'Moonbreaker', 'Moonbreaker is a turn-based strategy, tactical skirmish game. The game is designed to be a true digital miniatures experience, set in an expansive sci-fi universe crafted by Brandon Sanderson. Direct Captain and Crew in gripping, ever-changing competition and adventure.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/845890/header.jpg?t=1726810180', 1, 0, NULL);
INSERT INTO games VALUES (469, 846030, 'ΔV: Rings of Saturn', 'A physics-based mining sim, set in the thickest debris field in Sol. Every action has a reaction, lasers are invisible without a medium, and your thrust is a potent weapon. Find trade, adapt your equipment to your playstyle, hire a crew to help. Unravel the mysteries of the rings, or just get rich.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/846030/header.jpg?t=1746706378', 0, 0, NULL);
INSERT INTO games VALUES (473, 846110, 'The friends of Ringo Ishikawa', 'A highschool gang leader Ringo Ishikawa trying to live through his last autumn before graduation. With his best friends.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/846110/header.jpg?t=1741029247', 1, 0, NULL);
INSERT INTO games VALUES (450, 846470, 'Moss', 'Moss is an action-adventure puzzle game from Polyarc tailor-made for the VR platform. It combines classic components of a great game—compelling characters, gripping combat, and captivating world exploration—with the exciting opportunities of VR.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/846470/header_alt_assets_9.jpg?t=1742850366', 1, 0, NULL);
INSERT INTO games VALUES (434, 846770, 'DYSMANTLE', 'Ascend from your shelter. Ruin everything. Escape the wretched island. ⚔️🔨🎣🌱🌵🍰 Explore. Fight. Level up. Survive. Gather. Craft. Harvest. Hunt. Build. Farm. Solve puzzles. Fish. Cook. Live. Enjoy the bittersweet post-apocalypse.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/846770/header.jpg?t=1730985288', 1, 0, NULL);
INSERT INTO games VALUES (436, 846800, 'Diner Bros', 'Diner Bros is a cooking and restaurant management game. Cook and serve meals as fast as you can, but don’t get the orders wrong or else your customers will get angry – and hungry! Upgrade your restaurant and hire staff to help you… or play with your friends in 2-4 local co-op!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/846800/header.jpg?t=1730262534', 1, 0, NULL);
INSERT INTO games VALUES (440, 846870, 'Yooka-Laylee and the Impossible Lair', 'Yooka-Laylee and the Impossible Lair is a brand-new 2.5D platformer from some of the key creative talent behind ''Donkey Kong Country''. As the colourful buddy duo you must tackle a series of stunning, 2.5D levels and explore a puzzling 3D Overworld rich with secrets and surprises!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/846870/header.jpg?t=1729002447', 0, 0, NULL);
INSERT INTO games VALUES (441, 846880, 'The Chronicles of Quiver Dick', 'The Chronicles of Quiver Dick is a Crude Comedy RPG that has one goal and one goal only: To make you laugh! Play as Quiver Dick, a legendary storyteller and former badass, as he embarks on one of many downright crazy and entirely messed up adventures!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/846880/header.jpg?t=1660325441', 0, 0, NULL);
INSERT INTO games VALUES (414, 847370, 'Sunset Overdrive', 'Sunset Overdrive transforms an open-world apocalypse into your tactical playground. Zip, grind and wall-run across Sunset City with an unconventional arsenal. Hyper-agility, unique weapons, and customizable abilities deliver an explosive and irreverent adventure in the end times.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/847370/header.jpg?t=1667851405', 0, 0, NULL);
INSERT INTO games VALUES (368, 848030, 'Roundguard', 'Roundguard is a bouncy dungeon crawler with pinball physics, lots of loot, and a randomized castle full of oddballs. Press your luck against hordes of dangerously cute monsters and challenging roguelike elements in this all-round bouncy adventure!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/848030/header.jpg?t=1747958280', 1, 0, NULL);
INSERT INTO games VALUES (369, 848050, 'GP Bikes', 'GP Bikes is a realistic motorcycle simulator, based on a scratch built physics engine that accurately simulates motorcycle dynamics and setup options.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/848050/header.jpg?t=1700585971', 0, 0, NULL);
INSERT INTO games VALUES (385, 848350, 'Katamari Damacy REROLL', 'The beloved roll-em-up game returns with fully updated graphics, completely recreated cutscenes and in full HD!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/848350/header.jpg?t=1708327061', 0, 0, NULL);
