INSERT INTO games VALUES (286, 850050, 'Achievement Idler: Red', 'Achievement Idler:Red is an Achievement spam &quot;game&quot; that you start up to idle in the background and get the achievements.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/850050/header.jpg?t=1526224837', 0, 0, NULL);
