INSERT INTO games VALUES (64959, 881320, 'The LEGO Movie 2 Videogame', 'Bricksburg is in ruins and Emmet''s friends have been taken! Team up with Emmet and a host of heroic characters to save their friends from the strange inhabitants of the Systar System. Journey into outer space, discover new worlds, and test your Master Building skills.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/881320/header.jpg?t=1745612855', 1, 0, NULL);
