INSERT INTO games VALUES (139514, 881690, 'The Slater', 'Get ready to kill drug dealers, crime bosses and anyone who stands in your way as you seek revenge for your father’s murder. The Slater is a story-driven first-person stealth-action-puzzle game that puts you in the shoes of a former cop Mark Slater.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/881690/header.jpg?t=1667027397', 0, 0, NULL);
