INSERT INTO games VALUES (64907, 882100, 'XCOM®: Chimera Squad', 'XCOM: Chimera Squad delivers an all-new story and turn-based tactical combat experience in the XCOM universe.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/882100/header.jpg?t=1603903072', 1, 0, NULL);
