INSERT INTO games VALUES (64892, 882710, '東方幕華祭 TouHou Makuka Sai ~ Fantastic Danmaku Festival', 'Fantastic Danmaku Festival is a Touhou Project fanfiction STG with colourful danmaku, beautiful remix music and original music. Besides the characters we know in Touhou Project, there is also a brand new original character named Nix in this game! With the Scarlet Devil mansion as their stage, the girls are soaring in the sky of Gensokyo!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/882710/header.jpg?t=1675842097', 0, 0, NULL);
