INSERT INTO games VALUES (64872, 883100, '360 No Scope Arena', '360 No Scope Arena is an online multiplayer shooter with a twist: you have to spin around before you can shoot your gun. Every kill is a &quot;360 No Scope&quot; in this arena. Every shot is a trick shot. This game rewards pure aiming skill above all else.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/883100/header.jpg?t=1561605966', 0, 0, NULL);
