INSERT INTO games VALUES (64415, 895480, 'Fates of Ort', 'Fates of Ort is a retro fantasy RPG focused on strategic action, in a land where time is frozen when you stand still. Cast powerful spells - but beware, they will cost you your life.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/895480/header.jpg?t=1728571750', 0, 0, NULL);
INSERT INTO games VALUES (64385, 895620, 'Spellcaster University', 'Develop a prestigious university of mages. Build rooms, train your students, fight orcs, slay the bureaucrats, manage your budget... a director''s life is not a quiet one.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/895620/header.jpg?t=1730108830', 0, 0, NULL);
INSERT INTO games VALUES (64395, 895870, 'Project Wingman', 'Project Wingman is a flight action game that lets you take the seat of advanced fighter jets and become a true ace. Fight in various missions and gamemodes ranging from intense aerial dogfights to large scale ground assault in an alternate scorched earth setting.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/895870/header.jpg?t=1625008344', 1, 0, NULL);
INSERT INTO games VALUES (64367, 896160, 'Evil Bank Manager', 'What could be better than having a million dollars, a billion? This will not make you all powerful in the world, your goal will not only be to make lots of money, but to print money and become a Federal reserve system', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/896160/header.jpg?t=1619160958', 0, 0, NULL);
INSERT INTO games VALUES (130650, 896440, 'Eternal Edge +', 'Eternal Edge + is a casual Action-Adventure role-playing game following Cross, an Age-old warrior who is trying to wake his lost Wife from an Eternal slumber. Only together can they defeat the Skeleton King.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/896440/header.jpg?t=1740067988', 1, 0, NULL);
INSERT INTO games VALUES (64379, 896460, 'Lucah: Born of a Dream', 'FOR THE POWER AND GLORY; NOW AND FOREVER', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/896460/header.jpg?t=1736569468', 0, 0, NULL);
INSERT INTO games VALUES (64381, 896520, 'Stay Out of the House', 'Can you escape the home of a cannibal serial killer? It''s only a matter of time until you''re dinner!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/896520/header.jpg?t=1689365167', 0, 0, NULL);
INSERT INTO games VALUES (64365, 896750, 'Koral', 'Koral, a love letter to the ocean. Dive into the beautiful underwater world as a sea current. Solve puzzles to bring back to life coral reefs and spread the beauty of the oceans in different sea ecosystems.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/896750/header.jpg?t=1735906369', 1, 0, NULL);
INSERT INTO games VALUES (64349, 896890, 'VR Paradise - Steam Edition', 'VR Paradise is a virtual Strip Club for educated grown ups who own a VR headset.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/896890/header.jpg?t=1743820744', 0, 0, NULL);
INSERT INTO games VALUES (64359, 897030, 'Paratopic', 'Smuggle contraband VHS tapes across the border. Discover the remnants of illicit industry. Prepare for an assassination. This is Paratopic, an atmospheric retro-3D horror adventure through a cursed fever dream.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/897030/header.jpg?t=1728407642', 0, 0, NULL);
INSERT INTO games VALUES (64334, 897220, 'Summer Pockets', 'From the creators of Angel Beats! and CLANNAD, Key, comes their latest emotional, award-winning journey. Follow protagonist Takahara Hairi as he travels to the secluded island Torishirojima, where he rediscovers what it means to enjoy summer vacation.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/897220/header.jpg?t=1732683225', 0, 0, NULL);
INSERT INTO games VALUES (64340, 897410, 'Esports Life Tycoon', 'Manage your own esports squad, expand your gaming house, and defeat legendary teams to become the best in the world!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/897410/header.jpg?t=1736782214', 0, 0, NULL);
INSERT INTO games VALUES (64343, 897450, 'The Survivalists', 'A living world full of surprises, secrets and danger awaits in The Survivalists, an adventure-filled survival sandbox set in The Escapists universe. Explore, build, craft and even train monkeys with up to three friends in a desperate bid to survive. Have you got what it takes to be a Survivalist?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/897450/header.jpg?t=1729002422', 1, 0, NULL);
INSERT INTO games VALUES (76646, 897730, 'Among Trees', 'Escape to an enchanting, living sandbox surrounded by wildlife and nature. Scavenge materials and craft tools to turn your small cabin into a warm, well-supplied home. Survive by fishing, cooking and growing your own food. Be careful though, the forest is as dangerous as it is wonderful.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/897730/header.jpg?t=1636537260', 0, 0, NULL);
INSERT INTO games VALUES (64320, 897820, 'Reigns: Game of Thrones', 'Reigns: Game of Thrones is the heir to the award-winning HBO® TV series Game of Thrones® and the smash-hit swipe ‘em up series Reigns from Nerial and Devolver Digital.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/897820/header.jpg?t=1728946888', 1, 0, NULL);
INSERT INTO games VALUES (76657, 897930, 'Demonheart: Hunters', 'Embrace or resist the demonic influence around you. Romance your companions in this RPG with an emphasis on conversation choices and character interactions.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/897930/header.jpg?t=1724973705', 0, 0, NULL);
INSERT INTO games VALUES (76638, 898450, 'UBERMOSH:SANTICIDE', 'SANTICIDE is the sixth volume of the arcade series UBERMOSH. A must buy for arcade and top-down enthusiasts.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/898450/header.jpg?t=1699491466', 1, 0, NULL);
INSERT INTO games VALUES (76643, 898580, 'Premium Bowling', 'Premium Bowling is as close to real bowling as you''ll get without picking up a physical bowling ball. Start the game and play like you''re in a real bowling alley. Experience the realism in every throw, every hit, and every strike!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/898580/e545fc6b76e8e3b04543471607ed9191b2f59b84/header.jpg?t=1740567985', 1, 0, NULL);
INSERT INTO games VALUES (64270, 898650, 'The Shapeshifting Detective', 'The Shapeshifting Detective is a supernatural murder mystery FMV game where you play as a detective who can shapeshift into other characters, allowing you to unlock secret conversations and private encounters.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/898650/header.jpg?t=1727962647', 1, 0, NULL);
INSERT INTO games VALUES (64274, 898720, 'Kubifaktorium', 'Build, manage and grow a thriving colony in Kubifaktorium. The game features different biomes to explore, plenty of resources to exploit, complex machinery to build and interesting production chains to master.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/898720/header.jpg?t=1654779804', 0, 0, NULL);
INSERT INTO games VALUES (64275, 898750, 'Super Robot Wars 30', '30 years on, the battle for our world''s future continues. Super Robot Wars is a tactical RPG that brings characters and robots from a variety of mecha anime together to battle their mutual foes.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/898750/header.jpg?t=1703657069', 1, 0, NULL);
INSERT INTO games VALUES (64278, 898800, 'Constructor Plus', 'Constructor Plus is the definitive building simulation for the modern day tycoon. Build your dream town full of crackpot undesirables, businesses, and quirky tenants whilst fending off your rivals in the eagerly awaited sequel to Constructor HD. With almost 3 times more content, building just got bigger!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/898800/header.jpg?t=1575426423', 0, 0, NULL);
INSERT INTO games VALUES (64281, 898890, 'Endling - Extinction is Forever', 'As the last mother fox on Earth, your cubs need all your care to survive in a merciless world that slowly destroys itself. You have to help them, teach them and save them. And you should never forget that extinction is forever – in the real world and in this 2023 BAFTA award winning experience.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/898890/header.jpg?t=1741703103', 1, 0, NULL);
INSERT INTO games VALUES (64283, 898920, 'Axis & Allies 1942 Online', 'Play the classic board game, Axis &amp; Allies 1942 2nd Edition! Act as WWII powers in a turn-based strategy game that fits your screen and schedule— get notified on your turn and command armies at your own pace! Team up with friends, challenge the world’s top players, or go solo vs. A.I.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/898920/header.jpg?t=1746125912', 0, 0, NULL);
INSERT INTO games VALUES (64267, 899310, 'Iron Danger', 'Iron Danger is a tactical combat puzzler with a unique time manipulation mechanic. A never before seen combination that blends the tactical depth of turn-based games with the exciting action of real-time games.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/899310/header.jpg?t=1736357047', 1, 0, NULL);
INSERT INTO games VALUES (64243, 899390, 'Xenon Racer', 'It’s the year 2030, the era of flying vehicles. A one-off championship for wheel based vehicles has been organised, with cutting-edge electric cars boosted by Xenon gas. Drift through cities like Tokyo and Dubai as fast as you can and claim eternal glory!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/899390/header.jpg?t=1721813147', 1, 0, NULL);
INSERT INTO games VALUES (76601, 899440, 'GOD EATER 3', 'Set in a post-apocalyptic setting, it’s up to your special team of God Eaters to take down god-like monsters devastating the world. With an epic story, unique characters, and all new God Arcs and Aragami, the latest evolution in ACTION is here!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/899440/header.jpg?t=1701317278', 1, 0, NULL);
INSERT INTO games VALUES (131656, 899770, 'Last Epoch', 'Uncover the Past, Reforge the Future. Ascend into one of 15 mastery classes and explore dangerous dungeons, hunt epic loot, craft legendary weapons, and wield the power of over a hundred transformative skill trees. Last Epoch is being developed by a team of passionate Action RPG enthusiasts.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/899770/bf7bf6df7fea6b22c6ea451d5af5aacf3a7cadfa/header.jpg?t=1747331839', 1, 0, NULL);
INSERT INTO games VALUES (64237, 899970, 'NEKOPARA Extra', 'About half a year before the opening of the patisserie, La Soleil where the catgirls work with Kashou. Back when Chocola and Vanilla were still kittens when they first arrived at the Minaduki household and before they opened up to the other catgirls.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/899970/header.jpg?t=1677711850', 0, 0, NULL);
INSERT INTO games VALUES (64239, 900010, 'Meeple Station', 'Build your way to success! Trade your way to the top! Explore your way to infamy! Do it all your way!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/900010/header.jpg?t=1664495001', 0, 0, NULL);
INSERT INTO games VALUES (64240, 900040, 'ELEX II', 'In this sequel to the vintage Open World RPG ELEX, Jax must once again unite the free people of the Science-Fantasy world of Magalan against a new threat - the Skyands, who want to change the face of the planet forever.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/900040/header.jpg?t=1744710699', 0, 0, NULL);
INSERT INTO games VALUES (64226, 900270, 'Reventure', 'The one and only non-linear adventure with 100 different endings. Don''t just wishlist me. I''m not that expensive... also, look at those reviews!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/900270/header.jpg?t=1726659631', 1, 0, NULL);
INSERT INTO games VALUES (64233, 900400, 'Sacred Fire: A Role Playing Game', 'A text-based RPG full of choice and action. Fight for survival in the midst of the Roman invasion of ancient Caledonia. Strategize one dice roll at a time as emotions affect your performance. Use willpower to outsmart opponents, gain allies, wage war, or strive for peace. How will your story end?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/900400/header.jpg?t=1748501228', 0, 0, NULL);
INSERT INTO games VALUES (64216, 900883, 'The Elder Scrolls IV: Oblivion® Game of the Year Edition Deluxe (2009)', 'PUBLISHER UPDATE - This is the product page for The Elder Scrolls IV: Oblivion Game of the Year Deluxe Edition, released in 2009.---The Elder Scrolls IV: Oblivion® Game of the Year Edition presents one of the best RPGs of all time like never before. Step inside the most richly detailed and vibrant game-world ever created.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/900883/header.jpg?t=1745343032', 0, 0, NULL);
INSERT INTO games VALUES (64219, 901147, 'Earthworm Jim', 'Jim wasn''t always a studly super-worm. He was once just a spineless, dirt-eater with no real mission in his life... But then something unexpected happened. The evil Psy-Crow was transporting a super suit, built by the genius Professor Monkey-For-A-Head, to Queen Pulsating, Bloated, Festering, Sweaty, Pus-Filled, Malformed,...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/901147/header.jpg?t=1634573795', 0, 0, NULL);
INSERT INTO games VALUES (64220, 903040, 'The Castles of Burgundy', 'Stefan Feld''s highly decorated board game &quot;The Castles Of Burgundy&quot; by Ravensburger is getting its digital version on Steam! Enjoy against the challenging AI or friends a beautiful digital version of the classic board game!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/903040/header.jpg?t=1704802634', 1, 0, NULL);
INSERT INTO games VALUES (76537, 903950, 'Last Oasis', 'Nomadic Survival MMO. Build wooden walking machines to travel to new lands. Create clans and fight for territory. Resources deplete fast, so take your sword and scavenge, pirate, and trade to stay alive.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/903950/header.jpg?t=1743622020', 0, 0, NULL);
INSERT INTO games VALUES (64183, 904360, 'Family Man', 'You owe us money, Joe, and we plan to collect. We don''t care where it comes from, but you''d better not skip town on us. Otherwise your family will be searching the river for your body.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/904360/header.jpg?t=1736424699', 0, 0, NULL);
INSERT INTO games VALUES (64184, 904380, 'Vambrace: Cold Soul', 'Vambrace: Cold Soul is a story-driven roguelite set amidst a frozen landscape. Plan expeditions, then journey to the cursed city surface with your party. Wield unique powers, avoid traps, brave strange encounters, and survive deadly combat in this gothic fantasy adventure!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/904380/header.jpg?t=1721908243', 1, 0, NULL);
INSERT INTO games VALUES (64191, 904520, 'Red Embrace: Hollywood', '1996—Los Angeles, CA. A young newcomer is turned into a vampire and thrust into the dark underworld of society, forced to sink or swim. You are that newcomer.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/904520/header.jpg?t=1620422478', 0, 0, NULL);
INSERT INTO games VALUES (64152, 904540, 'Indiana Jones® and the Infernal Machine™', 'The year is 1947. The Nazis have been crushed, the Cold War has begun and Soviet agents are sniffing around the ruins of the fabled Tower of Babel. What are they up to? The CIA recruits renowned archeologist and adventurer, Dr. Henry &quot;Indiana&quot; Jones, to find out.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/904540/header.jpg?t=1741737426', 0, 0, NULL);
INSERT INTO games VALUES (64153, 904570, 'TOK', 'Tok is a game where you will have to solve a puzzle by connecting all dots with lines.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/904570/header.jpg?t=1574545534', 1, 0, NULL);
INSERT INTO games VALUES (64160, 904750, 'Zniw Adventure', 'Zniw Adventure is a hand-drawn point and click adventure game with a strong 90''s vibe and cartoon animations. Play as Zniw - a yellow female dinosaur who is on a mission to find the ultimate gift for her mother''s hatchday!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/904750/header.jpg?t=1646294981', 0, 0, NULL);
INSERT INTO games VALUES (64171, 904960, 'Cine Tracer', 'Cine Tracer is a realistic cinematography simulator. The player operates real world based cameras, sets up lights, and directs talent/actors in stunning next gen environments created in Unreal Engine 4.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/904960/header.jpg?t=1693760507', 0, 0, NULL);
INSERT INTO games VALUES (64140, 905340, 'Heave Ho', 'Heave Ho tasks up to four players with a simple goal – don’t fall to your death! Players will use their own two hands and the outstretched grip of their friends to grapple across each level on their way to victory.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/905340/header.jpg?t=1627311427', 1, 0, NULL);
INSERT INTO games VALUES (64149, 905490, 'Deck Hunter', 'Deck Hunter is a roguelike card game. The World of Klanojh has been cursed by Glatta, the Goddess of Anger. Build your deck, make combos, defeat fantasy creatures and help Avery to face the evil and restore the balance!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/905490/header.jpg?t=1612787558', 0, 0, NULL);
INSERT INTO games VALUES (64098, 905970, 'Steel Crew', 'Join a Tank as a Driver, Gunner or Commander and team up with and against other Tanks in Tank Vs Tank combat where tactics and communication is key', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/905970/header.jpg?t=1635441159', 0, 0, NULL);
INSERT INTO games VALUES (64102, 906050, 'Hentai Case Opening', 'Hentai Case Opening is a totally classic case opening simulator with a slight Japanese touch ...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/906050/header.jpg?t=1731171309', 0, 0, NULL);
INSERT INTO games VALUES (64103, 906100, 'Observation', 'Observation is a sci-fi thriller uncovering what happened to Dr. Emma Fisher, and the crew of her mission, through the lens of the station’s artificial intelligence S.A.M.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/906100/header.jpg?t=1710929850', 1, 0, NULL);
INSERT INTO games VALUES (64105, 906120, 'POLYBIUS', 'POLYBIUS is a fast, trippy tunnel shooter playable on a normal screen or in VR. 50 levels of blissful trance shooting action are set to a blistering soundtrack. The PS4 version was EDGE Magazine''s VR GOTY in 2017, and the PC version of the game was even used as the basis for a NIN music video.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/906120/header.jpg?t=1742484213', 0, 0, NULL);
INSERT INTO games VALUES (64063, 906930, 'LEAP', 'LEAP is a fast-paced, multiplayer first-person shooter featuring epic large scale battles, each with players armed to the teeth. Fight for either the United Earth Defense Coalition (UEDC) or the rebel Exo-Terrans - whoever pays the most, wins your trigger finger and excessive arsenal.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/906930/header.jpg?t=1729087108', 0, 0, NULL);
INSERT INTO games VALUES (64043, 907270, 'eSports Legend', 'Esports Legend is a Esports club simulator. You are here to make a unknown amateur team world-famous within several seasons!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/907270/header.jpg?t=1646642652', 0, 0, NULL);
INSERT INTO games VALUES (64050, 907470, 'Iris.Fall', 'Iris.Fall is a puzzle adventure game featuring striking visuals and a spellbinding theme of &quot;light and shadow&quot;.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/907470/header.jpg?t=1641371769', 1, 0, NULL);
INSERT INTO games VALUES (76385, 907650, 'Stronghold: Warlords', 'Besiege Great Khans, Imperial warlords and Shōgun commanders in Stronghold: Warlords, the latest ''castle sim'' from Firefly Studios. Command AI warlords across the battlefield as you build a castle economy and new gunpowder-fuelled siege engines!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/907650/header.jpg?t=1742483639', 1, 0, NULL);
INSERT INTO games VALUES (64020, 907670, 'Super Crush KO', 'Super Crush KO is a fast-paced brawler set in a vibrant, near-future city. Zip up your favourite neon jacket and combo your way through swarms of deadly robots to save your kidnapped kitten and, while you’re at it, save humanity from an AI apocalypse.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/907670/header.jpg?t=1697494367', 1, 0, NULL);
INSERT INTO games VALUES (64038, 908070, 'Mystic Vale', 'Are you ready to lead your druidic clan and cleanse the Valley of Life? Mystic Vale is a stunning digital version of the Origins award-winning AEG card game. Debuting the unique Card Crafting System, players take turns building powerful combos in order to stop the curse. Play online or local hotseat.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/908070/header.jpg?t=1683804472', 0, 0, NULL);
INSERT INTO games VALUES (64015, 908360, 'Monomyth', 'MONOMYTH is an immersive, first-person dungeon-crawling RPG inspired by the genre''s late classics. Embark on a journey through a vast and highly interactive game world as you unravel the mysteries hidden beneath the ancient fortress of Lysandria.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/908360/090191ea1b93be1254342ebac09830228558fc1a/header_alt_assets_0.jpg?t=1748460666', 0, 0, NULL);
INSERT INTO games VALUES (63987, 908520, 'fpsVR', 'Utility for SteamVR for keeping track of FPS, frame time and other performance metrics in the in-game overlay. Easily change SteamVR settings in the fpsVR settings overlay in the SteamVR dashboard. Headset cable twist tracking and other useful features.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/908520/header.jpg?t=1737491094', 0, 0, NULL);
INSERT INTO games VALUES (63994, 908740, 'VALHALL: Harbinger - Beta Testing', 'VALHALL is a blend of multiple genres, combining first &amp; third person directional physical combat slasher with a survival experience set in a brutal world of Vikings. Survive, feel Thor''s power, become an einherjar, and enter the ultimate battlefield!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/908740/header.jpg?t=1739644865', 0, 0, NULL);
INSERT INTO games VALUES (76334, 909080, 'Cube Escape: Paradox', 'The tenth Cube Escape follows the story of detective Dale Vandermeer who finds himself trapped in two different universes and needs to escape. Cube Escape: Paradox will be released together with the accompanying Paradox: A Rusty Lake Film.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/909080/header.jpg?t=1667254447', 1, 1, NULL);
INSERT INTO games VALUES (63980, 909320, 'Ruinarch', 'Ruinarch is an evil god simulator and sandbox game where you mess with people’s lives for hilarious results! Make them vampires, werewolves or bard haters and cackle as the drama unfolds. Once you’re done, unleash a malicious buffet of spells and custom plagues to wipe them out and start anew!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/909320/header.jpg?t=1716910799', 0, 0, NULL);
INSERT INTO games VALUES (76294, 909660, 'Vagrus - The Riven Realms', 'Embark on a perilous journey across a realm forsaken by the gods and devastated by an arcane cataclysm. Accompanied by a hardy crew, you must trade, fight, and explore your way to success as the leader of a traveling company in Vagrus, an award-winning turn-based post-apocalyptic fantasy RPG.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/909660/header.jpg?t=1747766363', 0, 0, NULL);
INSERT INTO games VALUES (63967, 909820, 'Songbird Symphony', 'Musical Metroidvania, with pixel art to die for. Guide orphaned chick ''Birb'', on a platform adventure, as he faces off against the denizens of the forest in rhythm-action boss battles. Acclaimed for its gorgeous animation, and heart-warming storytelling, as Birb strives to discover his true origins.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/909820/header.jpg?t=1741786975', 0, 0, NULL);
INSERT INTO games VALUES (63939, 909970, 'Tech Corp.', 'Tech Corp. is a game where you try to become the biggest tech company in the world . Your goal is to become the next big shot in the tech industry. The game also takes place through history. Starting in the early 90''s and going to present time.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/909970/header.jpg?t=1564073964', 0, 0, NULL);
INSERT INTO games VALUES (107090, 910450, 'Warhammer Quest 2: The End Times', 'Warhammer Quest 2: The End Times is the sequel to a turn based strategy classic, Warhammer Quest. It’s stunning visuals and deep tactical gameplay are an addictive mix that is a feast for the senses.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/910450/header.jpg?t=1685691468', 1, 0, NULL);
INSERT INTO games VALUES (63924, 910490, 'Killsquad', 'Hack and slash? Check. Twin-stick-shooter? Check. 4 player coop to slay hordes of aliens &amp; bosses with your friends? Check. Skills, upgrades, weapons, gears, talismans and more to make you stronger? Check. Wake up, bounty hunter. We have a mission for you. Time to clean up the scum of the galaxy.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/910490/header.jpg?t=1678348175', 1, 0, NULL);
INSERT INTO games VALUES (63929, 910630, 'Arcade Spirits', 'Arcade Spirits is a romantic visual novel that follows an alternative timeline where the 1983 video game crash never occurred. It''s 20XX and you''ve just started a new job at the Funplex game arcade. Who will you meet along the way? Will you find the romance you''re seeking?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/910630/header.jpg?t=1741786721', 0, 0, NULL);
