INSERT INTO games VALUES (63897, 910880, 'Mad Tower Tycoon', 'Design your own skyscraper with more than 100 Floors. Rent offices, apartments or shops and build a financially lucrative skyscraper. Build cinemas, bars or a theater to satisfy your visitors and create an effective transport system with elevators and stairs.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/910880/header.jpg?t=1740737808', 1, 0, NULL);
