INSERT INTO games VALUES (63749, 914690, 'Hentai Shooter 3D', '&quot;Hentai Shooter 3D&quot; - First person shooter with spirit of good old days .', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/914690/header.jpg?t=1747155717', 1, 0, NULL);
