INSERT INTO games VALUES (106536, 925100, 'The Elder Scrolls Online - Elsweyr', 'Dragons return to Tamriel in The Elder Scrolls Online: Elsweyr, part of the Season of the Dragon year-long adventure! Explore the savannahs and canyons of Elsweyr, defend the home of the Khajiit from an ancient evil, and command the undead with the Necromancer class.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/925100/header.jpg?t=1591806644', 0, 0, NULL);
INSERT INTO games VALUES (106547, 925440, '神社的百合香 ~ Floral Aroma in the Shrine', '《Floral Aroma in the Shrine》is a short Vision Novel Touhou Project Fan Fiction game. The main story is about a love story of Reimu and Marisa. Player will be playing as Marisa and experience her side of the story happened in Hakurei Jinja.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/925440/header.jpg?t=1648133373', 0, 0, NULL);
