INSERT INTO games VALUES (106527, 925570, 'The Uncertain: Light At The End', 'The Uncertain is a story-driven adventure game set in a post-apocalyptic world. Humanity disappeared from the face of the Earth and has been replaced by robots. Together with Emily, one of the survivors, you will have to witness how people try to live in a world ruled by robots.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/925570/header.jpg?t=1726494679', 0, 0, NULL);
