INSERT INTO games VALUES (112971, 1073900, 'Brukel', 'A first-person exploration game based on the actual memories of a 92-year-old grandmother, told to players in her own voice. Take pictures of what remains of her abandoned childhood home to uncover the dark, traumatic events that she had to fight through as a teenage girl.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1073900/header.jpg?t=1745956880', 0, 0, NULL);
