INSERT INTO games VALUES (112945, 1074030, 'Melon Journey: Bittersweet Memories', 'Melon Journey: Bittersweet Memories is a story-exploration game about getting caught up in the outlandish happenings of a small town where melons are illegal. Silly and cute on the surface, but are things really as peaceful as they seem?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1074030/header.jpg?t=1730849847', 1, 0, NULL);
INSERT INTO games VALUES (112948, 1074070, 'Dust to the End', 'Nuclear war ended human civilization, but it could never uproot the evil within our hearts. Fight, trade, negotiate, raid– do whatever it takes to survive in the wasteland. You will have to be as clever as ruthless to thrive in a broken world, torn by war, cruelty, hunger and slavery.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1074070/header.jpg?t=1741674924', 0, 0, NULL);
INSERT INTO games VALUES (112949, 1074080, 'SENRAN KAGURA Peach Ball', 'SENRAN KAGURA has transformed into a wild pinball game! Bounce your ball along the curves of a crazy theme park, starring a ninja girl who thinks she''s an animal! (Yep, you heard right!) Build up points to unlock special challenges, which showcase the girls'' charms!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1074080/header.jpg?t=1730937024', 1, 0, NULL);
INSERT INTO games VALUES (112941, 1074620, 'Adore', 'Adore is an action creature-collecting game where you build your team of unique creatures and go on a journey to resurrect the God of the Creatures.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1074620/header.jpg?t=1700164396', 0, 0, NULL);
INSERT INTO games VALUES (112909, 1074630, 'Call Of Unity', 'Soldier Unity prepare for battle! Grab a weapon from the arsenal and go conquer Unity''s battlefields!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1074630/header.jpg?t=1733529861', 0, 0, NULL);
INSERT INTO games VALUES (112905, 1075080, 'Falcon Age', 'Bond with a baby falcon and go on an adventure. Falcon Age is a first-person, single-player action adventure where you’ll play as Ara in her fight to reclaim her cultural legacy in the lost art of falcon hunting against a force of automated colonizers.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1075080/header.jpg?t=1666983847', 0, 0, NULL);
INSERT INTO games VALUES (130646, 1075190, 'A Game of Thrones: The Board Game - Digital Edition', 'A Game of Thrones: The Board Game – Digital Edition is the digital adaptation of the top-selling strategy board game from Fantasy Flight Games.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1075190/header.jpg?t=1742483806', 0, 0, NULL);
INSERT INTO games VALUES (112895, 1075400, 'Doctor Who: The Edge Of Time', 'A new mysterious enemy threatens to tear apart the universe and only you can stop them! Doctor Who: The Edge Of Time lets players embark on an adventure through space and time. Travel across the universe, visit alien locations, pilot the TARDIS and solve the mystery of the controlling force behind the Reality Virus.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1075400/header.jpg?t=1698340942', 0, 0, NULL);
INSERT INTO games VALUES (112901, 1075740, 'Banners of Ruin', 'Assemble your party. Answer the call. Win the war. Build a deck and fight a series of turn-based combats with up to 6 party characters through the city of Dawn''s Point. Each character can unlock a set of unique cards and abilities that can augment your deck in powerful, exciting ways.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1075740/header.jpg?t=1727786787', 1, 0, NULL);
INSERT INTO games VALUES (112884, 1075980, 'NinNinDays', 'A sullen main character and a clumsy female ninja living together?! In this romantic adventure game set in Akihabara, you''ll laugh and you''ll cry over the entertaining lifetyle of a slightly erotic female ninja and the main character''s cohabitation!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1075980/header.jpg?t=1729048787', 0, 0, NULL);
INSERT INTO games VALUES (112865, 1076160, 'Command: Modern Operations', 'Command: Modern Operations is the next generation in cross-domain modern wargaming. It enables you to simulate every military engagement from post World War II to the present day and beyond. The scale is primarily tactical/operational, although strategic scale operations are also possible.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1076160/header.jpg?t=1741014923', 0, 0, NULL);
