INSERT INTO games VALUES (112850, 1076550, 'SAMURAI SHODOWN V SPECIAL / サムライスピリッツ零スペシャル', 'SAMURAI SHODOWN V SPECIAL, which was the last game made for SNK’s NEOGEO back in 2004, finally makes its way onto Steam. It features everything fans expect from a fighting game such as training mode, online matches, etc.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1076550/header.jpg?t=1580721821', 0, 0, NULL);
INSERT INTO games VALUES (112857, 1076750, 'Dream Engines: Nomad Cities', 'A survival city-building game with flying cities. Build, automate, and defend a flying city that travels between procedurally generated maps to survive in a wacky, nightmare-infested, post-apocalyptic world full of strange science and dreams.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1076750/header.jpg?t=1745568921', 0, 0, NULL);
INSERT INTO games VALUES (112861, 1076880, 'Air Marty', 'Experience 64 endings in a web of insane mini games and hand drawn artwork as Marty tries his dang ol'' best to enjoy his family vacation.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1076880/header.jpg?t=1585087256', 0, 0, NULL);
INSERT INTO games VALUES (112829, 1076920, 'Generals & Rulers', 'What will be the strategy game if you throw out all the grind from it, all the boring annoying actions and leave only strategy and tactics? It became interesting to us and as a result we received Generals &amp; Rulers. Try it now!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1076920/header.jpg?t=1637144371', 0, 0, NULL);
INSERT INTO games VALUES (112845, 1077290, 'SuperSmash: Physics Battle', 'SuperSmash is a physics base multiplayer fighting game.Character is fully driven by physics engine,and there are lots of different weapons and maps.It will provide you totally different battle experience.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1077290/header.jpg?t=1606062359', 0, 0, NULL);
INSERT INTO games VALUES (112808, 1077410, 'Hentai Sweet Girls', 'This game is a classic memory game with several levels of difficulty and beautiful arts. All characters appearing in this game are over 18 years of age. Enjoy ;-)', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1077410/header.jpg?t=1615895565', 0, 0, NULL);
INSERT INTO games VALUES (112810, 1077430, 'There''s a Butcher Around', 'There''s a Butcher Around, a brutal hide &amp; seek. Bill the butcher has escaped from the asylum and is looking for new victims. During the game you will have to find a place to hide, remembering that your friends are also trying to hide from the butcher. Every round, Bill the butcher chooses a spot to investigate, are you well hidden?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1077430/header.jpg?t=1589974427', 0, 0, NULL);
INSERT INTO games VALUES (112811, 1077450, 'Wally and the FANTASTIC PREDATORS', 'Your best friend wants to cheer you up, so he tries his best to make a dungeon for you to explore. Explore his wholesome, weird-as-heck, scrappy rogue-lite oozing with charm and humor for 1-2 Players.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1077450/header.jpg?t=1693940978', 1, 0, NULL);
INSERT INTO games VALUES (112815, 1077520, 'The Light Remake', 'There is only you, the abandoned remains of a former life and the flourishing nature that feels great in the absence of man. This world is both gloomy and empty, but so incredibly beautiful.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1077520/header.jpg?t=1732375576', 0, 0, NULL);
