INSERT INTO games VALUES (112798, 1078200, 'Spirits Abyss', 'Spirits Abyss is a roguelite platformer with destructible terrain. Cast into the Abysm you must explore its diverse depths battling phantasmic meanies and plundering its useful treasures to find a way home... but does something nestle beyond the realmic veil of death?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1078200/header.jpg?t=1731087019', 0, 0, NULL);
