INSERT INTO games VALUES (112759, 1079160, 'Touhou Kikeijuu ~ Wily Beast and Weakest Creature.', '誰が強いのか、誰が賢いのか、誰が正しいのか　畜生の理に則って、全て弾幕で決めよう！ ワイルドでビーストライクなシューティング幻想！', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1079160/header.jpg?t=1667287141', 0, 0, NULL);
INSERT INTO games VALUES (112761, 1079210, 'Spark the Electric Jester 2', 'Fast paced 3D action platformer.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1079210/header.jpg?t=1572743803', 0, 0, NULL);
