INSERT INTO games VALUES (112749, 1079800, 'Pistol Whip', 'Enter: the ultimate action hero. Pistol Whip is a physical action-rhythm game where film-inspired gunplay and blood-pumping beats collide. Blast, duck and dodge your way through fever dream Scenes, build unique rhythms in a ballet of bullets and claim glory on the leaderboards. Includes mod support!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1079800/header.jpg?t=1729189081', 1, 0, NULL);
