INSERT INTO games VALUES (112514, 1085510, 'Garfield Kart - Furious Racing', 'Garfield, the famous lasagna-loving cat is back to take on Jon, Odie and company in a no-holds-barred racing game!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1085510/b124a0dbf4fdc5b984268f92921f246ecba04c9c/header.jpg?t=1746451638', 0, 0, NULL);
INSERT INTO games VALUES (138077, 1085660, 'Destiny 2', 'Destiny 2 is an action MMO with a single evolving world that you and your friends can join anytime, anywhere, absolutely free.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1085660/header.jpg?t=1748375367', 1, 1, NULL);
INSERT INTO games VALUES (112525, 1085750, 'Sex with Stalin', 'As a young time traveler, you receive the opportunity to meet the greatest dictator of all time — Stalin. And then what? Everything''s up to you! Speak with Joseph, reveal his most hidden secrets, give him advice, and help the vozhd come to world domination! Or... show him what true love is!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1085750/header.jpg?t=1694460338', 0, 0, NULL);
INSERT INTO games VALUES (112505, 1086010, '198X', 'Part 1 of arcade epic 198X. A coming-of-age story told through multiple games and genres. Experience the thrill of shooting, driving, jumping, fighting and role-playing in 5 full-blown arcade stages – combined with cinematic pixel-art storytelling.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1086010/header.jpg?t=1724087378', 0, 0, NULL);
INSERT INTO games VALUES (112491, 1086410, 'Golf Around!', 'Golf Around! is a multiplayer Mini Golf game with crazy golf courses. In addition, you can easily play and create custom levels! For 1 to 12 players.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1086410/header.jpg?t=1729799631', 1, 0, NULL);
INSERT INTO games VALUES (112471, 1086640, 'Dude Simulator 3', 'Dude Simulator 3 is an open world sandbox game. It is your friend’s birthday tomorrow. You have already bought him a present, now you only have to give it to him. But your friends lives in another city, quite far from you.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1086640/header.jpg?t=1714423651', 1, 0, NULL);
INSERT INTO games VALUES (112479, 1086850, 'Garden of the Sea (VR)', 'You wake up on a small island in a magical world. Grow your garden, nurture local creatures, furnish your home or adventure across the seas to explore more islands and gather new resources. This world is for you.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1086850/header.jpg?t=1743707511', 1, 0, NULL);
INSERT INTO games VALUES (129127, 1086940, 'Baldur''s Gate 3', 'Baldur’s Gate 3 is a story-rich, party-based RPG set in the universe of Dungeons &amp; Dragons, where your choices shape a tale of fellowship and betrayal, survival and sacrifice, and the lure of absolute power.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1086940/48a2fcbda8565bb45025e98fd8ebde8a7203f6a0/header.jpg?t=1748346026', 1, 0, NULL);
INSERT INTO games VALUES (112462, 1087270, 'Franchise Hockey Manager 6', 'Franchise Hockey Manager returns for the 2019-20 season with plenty of additions to the deepest, most authentic hockey strategy gaming experience you can find. Choose one of 32 leagues around the globe and select a team to guide to glory, including a chance at the ultimate prize, the Stanley Cup®.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1087270/header.jpg?t=1633690504', 0, 0, NULL);
