INSERT INTO games VALUES (112445, 1087760, 'The Gunk', 'The Gunk is an action-adventure game in which you play as Rani, part of our duo of gritty space haulers. As they’re struggling to bring in funds, they chance upon an untouched planet brimming with life. They came in search of valuable resources, and it looks like they’ve hit the jackpot…', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1087760/header.jpg?t=1748881792', 0, 0, NULL);
