INSERT INTO games VALUES (112392, 1088710, 'Yakuza 3 Remastered', 'Kazuma Kiryu has earned his retirement on the sandy beaches of Okinawa. But when a deadly power struggle arrives on his doorstep, he’ll have to walk the streets of Kamurocho to escape his past for good. Complete The Dragon of Dojima’s journey.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1088710/header.jpg?t=1741336858', 1, 0, NULL);
INSERT INTO games VALUES (112395, 1088770, 'Car Mechanic Simulator VR', 'Become a real car mechanic in a very realistic, highly detailed simulator in a fully VR World. REPAIR, PAINT, TUNING with dozens of different tools and almost thousands of parts. BUY old vehicles, restore them, and SELL them at a profit. DRIVE and test all rebuilt cars.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1088770/header.jpg?t=1725042207', 1, 0, NULL);
