INSERT INTO games VALUES (112387, 1089090, 'ONE PIECE: PIRATE WARRIORS 4', 'ONE PIECE: PIRATE WARRIORS 4 is the latest evolution of PIRATE WARRIORS action! Based on the concept of &quot;experiencing a real ONE PIECE battlefield,&quot; buildings will come crashing down during the action and attacks will throw up smoke and dust, placing you in the thick of the ONE PIECE world!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1089090/header.jpg?t=1718095269', 1, 0, NULL);
