INSERT INTO games VALUES (112362, 1089790, 'Winter Resort Simulator', 'Are you ready for the winter? Winter Resort simulator lets you operate detailed Doppelmayr cable cars and snow vehicles such as Pistenbully snowcats. Set in a realistic alpine landscape, you are responsible for managing your ski resort and keeping your guests happy.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1089790/header.jpg?t=1726493337', 0, 0, NULL);
