INSERT INTO games VALUES (112367, 1089840, 'Armored Brigade', 'Armored Brigade is a real-time tactical wargame, focusing on realism and playability. In Armored Brigade the Cold War has turned hot, and Europe is once again torn apart by conflict. An &quot;Iron Curtain&quot; divides the Western Powers gathered together under the NATO banner from the Soviet Union', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1089840/header.jpg?t=1726825455', 0, 0, NULL);
INSERT INTO games VALUES (132804, 1089980, 'The Henry Stickmin Collection', 'A choose-your-own-path where failing is more fun than succeeding.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1089980/header.jpg?t=1619212064', 0, 0, NULL);
