INSERT INTO games VALUES (131317, 1135260, 'The Falconeer', 'Soar through the skies aboard a majestic warbird, explore a stunning oceanic world and engage in epic aerial dogfights, in this BAFTA-nominated air combat game from solo developer, Tomas Sala.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1135260/header.jpg?t=1745931769', 1, 0, NULL);
INSERT INTO games VALUES (132621, 1136380, 'Ultimate Fishing® Simulator 2', 'Fish around the globe using float, bottom, spinning, or casting gear, and catch over 60 realistic fish species. Play solo or online in normal, realistic, or sandbox mode! Explore stunning locations, switch to an underwater cam, and fill your trophy room!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1136380/header.jpg?t=1749122991', 1, 0, NULL);
INSERT INTO games VALUES (131322, 1139980, 'Travellers Rest', 'Craft, farm, build and cook! In Travellers Rest you will have to use all the available tools to become the best tavern keeper in the realm. Create unique dishes and drinks to please your customers as you discover the world and its colorful characters.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1139980/bee918eb87986ad85ed3836863a0b6cc7b439c22/header.jpg?t=1747982666', 1, 0, NULL);
INSERT INTO games VALUES (138867, 1142220, 'Beat Aim - Rhythm FPS Trainer', 'Beat Aim - rhythm aim trainer designed for FPS players with AI generated maps. Makes improving your aim incredibly fun while listening to your favorite songs. Open any music and customize level generation. Combination of osu! and KovaaK''s trainer.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1142220/header.jpg?t=1725359494', 0, 0, NULL);
INSERT INTO games VALUES (136436, 1142500, 'Fun with Ragdolls: The Game', 'Become a ragdoll and create your own environments in Sandbox Mode, explore worlds created by others, or just flop around your destructible sets! Fun with Ragdolls: The Game lets you enjoy everything you love about ragdolls!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1142500/header.jpg?t=1712862481', 0, 0, NULL);
INSERT INTO games VALUES (140491, 1142710, 'Total War: WARHAMMER III', 'The cataclysmic conclusion to the Total War: WARHAMMER trilogy is here. Rally your forces and step into the Realm of Chaos, a dimension of mind-bending horror where the very fate of the world will be decided. Will you conquer your Daemons… or command them?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1142710/header.jpg?t=1747123128', 1, 0, NULL);
INSERT INTO games VALUES (135036, 1142830, '9-nine-:Episode 3', '9-nine-: Episode 3 is the latest chapter in this series of supernatural mystery visual novels with the focus now shifted towards a new heroine, Haruka Kosaka.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1142830/header.jpg?t=1726605743', 0, 0, NULL);
INSERT INTO games VALUES (138557, 1143810, 'Black Skylands', 'Become the captain of an airship and explore the world of the skies, gather resources and build powerful weapons, uncover ancient secrets and fight beneath your ship''s sails.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1143810/header.jpg?t=1748265466', 0, 0, NULL);
INSERT INTO games VALUES (137553, 1144200, 'Ready or Not', 'Лос-Суэнос. Полиция Лос-Суэноса сообщает о всплеске преступности в городе. Отряды спецназа направлены для урегулирования таких опасных ситуаций, как захват заложников, угрозы взрыва и перестрелки с подозреваемыми.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1144200/header.jpg?t=1747153161', 0, 0, NULL);
INSERT INTO games VALUES (130175, 1144400, 'Senren＊Banka', 'Senren＊Banka is a Japanese-style visual novel produced by Yuzusoft, a Japanese developer of romance VNs. This game commemorated Yuzusoft''s 10th anniversary. It won numerous awards on the year of its release in Japan for its art, music, and characters.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1144400/header.jpg?t=1747875750', 0, 0, NULL);
INSERT INTO games VALUES (136726, 1145350, 'Hades II', 'Battle beyond the Underworld using dark sorcery to take on the Titan of Time in this bewitching sequel to the award-winning rogue-like dungeon crawler.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1145350/header.jpg?t=1741889622', 1, 0, NULL);
INSERT INTO games VALUES (136958, 1145360, 'Hades', 'Defy the god of the dead as you hack and slash out of the Underworld in this rogue-like dungeon crawler from the creators of Bastion, Transistor, and Pyre.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1145360/header.jpg?t=1715722799', 1, 0, NULL);
INSERT INTO games VALUES (132524, 1145630, 'BEAST: False Prophet', 'BEAST is a brutal, gridless tactical RPG that sends players to the dark ages rife with plague and raiders. Join forces with your warband, develop your skills, and unleash your inner beast to shred through your enemies. But take heed, as your choices have consequences – in and out of battle.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1145630/header.jpg?t=1743422888', 0, 0, NULL);
INSERT INTO games VALUES (130460, 1147860, 'UFO 50', 'UFO 50 is a collection of 50 single and multiplayer games that span a variety of genres, from platformers and shoot ''em ups to puzzle games, roguelites, and RPGs. Our goal is to combine a familiar 8-bit aesthetic with new ideas and modern game design.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1147860/header.jpg?t=1736122321', 0, 0, NULL);
INSERT INTO games VALUES (135799, 1147940, '3dSen PC', '3dSen - the unique emulator - breathes new life into 8-bit classic NES games by magically converting 2D pixel graphics into 3D voxel art. Experience your favorite retro like never before.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1147940/header.jpg?t=1732707743', 0, 0, NULL);
INSERT INTO games VALUES (131249, 1148760, 'I Was a Teenage Exocolonist', 'Spend your teenage years on an alien planet in this narrative RPG with card-based battles. Explore, grow up, and fall in love. The choices you make and skills you master over ten years will determine the course of your life and the survival of your colony.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1148760/header.jpg?t=1739821920', 0, 0, NULL);
INSERT INTO games VALUES (140241, 1149460, 'ICARUS', 'ICARUS is a PvE survival game for up to eight players. Explore a savage wilderness in the aftermath of terraforming gone wrong. Survive the Open World, complete timed Missions or build your Outpost. Explore, build, craft and hunt while seeking your fortune and prospecting for exotic matter.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1149460/header.jpg?t=1737051079', 1, 0, NULL);
INSERT INTO games VALUES (131350, 1149620, 'Gas Station Simulator', 'Buy an abandoned gas station and restore it to its full glory. Renovate, upgrade and expand upon the offered services to keep up with your clients demands.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1149620/48c850ef462f6204631212d82ad52e4812cb30b2/header_alt_assets_23.jpg?t=1749218356', 1, 0, NULL);
INSERT INTO games VALUES (129748, 1150080, 'Azur Lane Crosswave', 'In the middle of each nation''s normal training routine, a Joint Military Exercise was enacted. A select few from each nation were chosen to participate in this rigorous event. But, how did this event come to be? Are there other ulterior motives at play?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1150080/header.jpg?t=1730833361', 0, 0, NULL);
INSERT INTO games VALUES (137144, 1151340, 'Fallout 76', 'Bethesda Game Studios welcome you to Fallout 76. Twenty-five years after the bombs fall, you and your fellow Vault Dwellers emerge into post-nuclear America. Explore a vast wasteland in this open-world multiplayer addition to the Fallout story.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1151340/d9499c2250789cb72f12db771982a106014cf9ae/header.jpg?t=1749404768', 1, 0, NULL);
INSERT INTO games VALUES (136233, 1153410, 'JDM: Japanese Drift Master', 'Discover Japan’s legendary car culture in JDM: Japanese Drift Master! Take on challenging roads with refined simcade physics, immerse in the story through manga pages, and explore an open world inspired by stunning real-life areas. Every turn invites you to master the art of drift.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1153410/7a2223dff24456e54907fa6083790bb52e7b354a/header.jpg?t=1749633210', 1, 0, NULL);
INSERT INTO games VALUES (132375, 1153430, 'Love wish', 'Love Wish is an easy, fun and challenging jigsaw puzzle.♪(^∇^*) Put the pieces together to restore the full picture of the girls. Collect their photos and animations and remember this wonderful moment❤', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1153430/header.jpg?t=1703481299', 1, 0, NULL);
INSERT INTO games VALUES (133462, 1157220, 'Nebuchadnezzar', 'Create and customize cities in Nebuchadnezzar, a classic isometric city-builder where careful planning and define your rise as a ruler in ancient Mesopotamia.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1157220/165365f59a47432aa31c8379df9eb3424ce29bc9/header.jpg?t=1747831118', 1, 0, NULL);
INSERT INTO games VALUES (140022, 1157700, 'Pro Wrestling Sim', 'Pro Wrestling Sim is a text-based pro-wrestling booking simulator. Control a wrestling promotion, decide your roster, and create storylines, feuds and matches where the winners and losers are in your hands.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1157700/header.jpg?t=1710785798', 0, 0, NULL);
INSERT INTO games VALUES (129852, 1157740, 'Iron Meat', 'Iron Meat is a run-and-gun arcade shooter that immerses players in an apocalyptic future overrun by &quot;The Meat,&quot; an iron-ravenous mass mutating everything in its path. Blast your way through retro-inspired stages and bosses to uncover the shocking horrors behind secret experiments on the Moon.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1157740/header.jpg?t=1733424742', 1, 0, NULL);
INSERT INTO games VALUES (139819, 1158160, 'Coral Island', 'Coral Island is a vibrant and laid-back reimagining of farm sim games. Be who you want and experience enchanting island living at your own pace—live off the land, nurture animals, build relationships with a diverse cast of townsfolk, and make the world around you a more vital and harmonious place.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1158160/header.jpg?t=1740706311', 1, 0, NULL);
INSERT INTO games VALUES (129224, 1158310, 'Crusader Kings III', 'Love, fight, scheme, and claim greatness. Determine your noble house’s legacy in the sprawling grand strategy of Crusader Kings III. Death is only the beginning as you guide your dynasty’s bloodline in the rich and larger-than-life simulation of the Middle Ages.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1158310/header.jpg?t=1745933101', 1, 0, NULL);
INSERT INTO games VALUES (135655, 1158890, 'White Shadows', 'The wolves are watching! Venture through a captivating but brutal dystopia where our young adventurer Ravengirl will travel through this huge city’s brightest highs and delve to its darkest depths on her perilous journey of discovery and finding her destiny where hope seems in short supply.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1158890/header.jpg?t=1746629219', 1, 0, NULL);
INSERT INTO games VALUES (127487, 1158940, 'Blazing Sails', 'Fight for survival in Blazing Sails, a fast-paced pirate PvP game! Create your own unique pirate and ship. Band together with other players to command your mighty vessel! Explore different game-modes, maps, weapons, ship types and more while eliminating other crews in epic battles on land and sea!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1158940/header.jpg?t=1744285471', 0, 0, NULL);
INSERT INTO games VALUES (132224, 1159690, 'Voidtrain', 'Become a crew member of an Interdimensional Express Train! Discover a new world full of mysterious creatures, enemies and places. Upgrade and customize your train, gather new materials and build better weapons. Play solo or online сo-op with up to 4 people.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1159690/header.jpg?t=1748258218', 1, 0, NULL);
INSERT INTO games VALUES (135691, 1160330, 'Fight of Animals', 'Animal memes such as Power Hook Dog, Mighty Fox, Magic Squirrel and more are now become Fighters!! Simple Controls &amp; Funny Animals &amp; Exciting Battles!!! Choose your favorite animal and join the fight!Players are able to fight through arcade mode become the King of Animals!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1160330/header.jpg?t=1732008563', 0, 0, NULL);
INSERT INTO games VALUES (131235, 1160360, 'Miscreation: Evolve Your Creature!', 'Evolve your creature to survive Yggsdrasil! You are a newborn blob at the base of the divine tree. Collect legs, arms, tails, wings and other parts, then combine them in your own body to become the optimal creature!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1160360/header.jpg?t=1748561366', 0, 0, NULL);
INSERT INTO games VALUES (139582, 1161830, 'Age of Reforging:The Freelands', 'Welcome to medieval high-freedom sandbox adventure CRPG!You''ll be a reforger in freelands chosen by the Goddess to embark on medieval adventure tour at your own pace, gathering teammates, seeking survival, and craft your unique legend!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1161830/469a3b6eb8f1511d6a93d4314e0a21f689d56bc6/header.jpg?t=1747876075', 1, 0, NULL);
INSERT INTO games VALUES (139503, 1162520, 'Richman10', '&quot;Richman10&quot; is a classic chess game in which players earn money by luck (dicing) and strategy (buying land and buying cards) to defeat other players. Fine arts adopt pure 3D Q version of the original painting style. Game modes include: story mode, biography mode, multi-person hot seat mode, network mode.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1162520/header.jpg?t=1662618961', 0, 0, NULL);
INSERT INTO games VALUES (136105, 1162750, 'Songs of Syx', 'Songs of Syx is a fantasy city-builder where you start off as an insignificant colony and build, scheme, and fight your way towards a metropolis and empire. The mechanics are complex and true to life, where small events can spiral into the collapse of kingdoms. Try the unlimited demo first!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1162750/header.jpg?t=1736514836', 0, 0, NULL);
INSERT INTO games VALUES (130972, 1162960, 'Angry Video Game Nerd I & II Deluxe', 'Control &quot;The Nerd&quot; in a retro-inspired action platformer! It''s two games in one, remixed and rebalanced to bring you the ultimate experience of Nerd Rage. Featuring stylized pixel art inspired by classic games, a highly energetic soundtrack, and challenging levels -- plus a special NEW chapter!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1162960/header.jpg?t=1709579508', 0, 0, NULL);
INSERT INTO games VALUES (132350, 1166860, 'Rival Stars Horse Racing: Desktop Edition', 'With stunning, realistic horses, an in-depth breeding system, and a range of exciting game modes, Rival Stars Horse Racing offers horse fans the ultimate racing and riding experience. Take the reins and become an equestrian legend!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1166860/header.jpg?t=1748557692', 1, 0, NULL);
INSERT INTO games VALUES (131384, 1167450, 'DAEMON X MACHINA', 'Pilot your fully customizable Arsenal mech and join your fellow mercenaries in defending humanity from the corrupted machines and gigantic robots in this post-apocalyptic action game!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1167450/header.jpg?t=1748019726', 0, 0, NULL);
INSERT INTO games VALUES (129544, 1167630, 'Teardown', 'Спланируйте идеальное ограбление в симулированном воксельном мире, где можно разрушать абсолютно все. Проламывайте стены взрывчатками или транспортом, чтобы проложить короткий путь. Ставьте объекты друг на друга, чтобы подняться. Используйте окружающую среду максимально неожиданными способами.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1167630/header.jpg?t=1747313145', 0, 0, NULL);
INSERT INTO games VALUES (136595, 1172380, 'STAR WARS Jedi: Fallen Order™', 'A galaxy-spanning adventure awaits in Star Wars Jedi: Fallen Order, a 3rd person action-adventure title from Respawn. An abandoned Padawan must complete his training, develop new powerful Force abilities, and master the art of the lightsaber - all while staying one step ahead of the Empire.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1172380/header.jpg?t=1748950986', 1, 0, NULL);
INSERT INTO games VALUES (131376, 1172470, 'Apex Legends™', 'Apex Legends is the award-winning, free-to-play Hero Shooter from Respawn Entertainment. Master an ever-growing roster of legendary characters with powerful abilities, and experience strategic squad play and innovative gameplay in the next evolution of Hero Shooter and Battle Royale.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1172470/b7e2d0c4b5f34b6751269c359070f706ff6d59fe/header.jpg?t=1749122685', 1, 1, NULL);
INSERT INTO games VALUES (138691, 1172710, 'Dune: Awakening', 'Rise from survival to greatness and challenge the power of an Imperium in Dune: Awakening, a multiplayer survival game on a massive scale. Survive the sandworm, craft your ornithopter, build a fortress, and ascend to power on an open world Arrakis shared with hundreds of other players.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1172710/e934cbd04b40a615b3306797bd7be76610904f0e/header.jpg?t=1749603269', 1, 0, NULL);
INSERT INTO games VALUES (132880, 1176470, 'Terra Invicta', 'An alien invasion has fractured humanity into seven ideological factions each with a unique vision for the future. Lead your chosen faction to take control of Earth’s nations, expand across the Solar System, and battle enemy fleets in tactical combat.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1176470/header.jpg?t=1749229404', 0, 0, NULL);
INSERT INTO games VALUES (130973, 1178790, 'Shiren the Wanderer: The Tower of Fortune and the Dice of Fate', 'The Classic Roguelike Wanders Onto Steam! Adventure with Shiren the Wanderer and his sidekick Koppa, the talking ferret, through a world filled with cunning monsters, deadly traps and countless treasure.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1178790/header.jpg?t=1715703235', 0, 0, NULL);
INSERT INTO games VALUES (135800, 1179890, 'Pull Stay', 'Pull Stay is a wacky Beat ''em up game with Tower Defense mechanics. Use your fists or set crazy traps to repel enemies from rushing into your house! As a guardian robot, defend your buddy Susumu who has been a shut-in for years!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1179890/420408d4f1514d6d6a0470c9901bc5b82d4c53d1/header.jpg?t=1749585078', 1, 0, NULL);
INSERT INTO games VALUES (137117, 1180250, 'DIVINATION', '&quot;What if you''re born into this world without your permission?&quot; DIVINATION is a very short visual novel where you act as a fortune teller in a futuristic world. Talk and listen to people''s stories, then foresee their future using the runes they had drawn.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1180250/header.jpg?t=1725347159', 0, 0, NULL);
INSERT INTO games VALUES (130141, 1184250, 'Finnish Army Simulator', 'Military service, just like you remember it! Or if you don’t, you’ll feel like you do.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1184250/header.jpg?t=1690792674', 0, 0, NULL);
INSERT INTO games VALUES (136569, 1184370, 'Pathfinder: Wrath of the Righteous - Enhanced Edition', 'Embark on a journey to a realm overrun by demons in a new epic RPG from the creators of the critically acclaimed Pathfinder: Kingmaker. Explore the nature of good and evil, learn the true cost of power, and rise as a Mythic Hero capable of deeds beyond mortal expectations.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1184370/header.jpg?t=1749628787', 0, 0, NULL);
INSERT INTO games VALUES (127868, 1184560, 'Phantom Breaker: Omnia', 'Phantom Breaker Omnia is a fast-paced 2-D anime fighting game that features 20 unique characters, pitted against one another to make their greatest wishes come true. The ability to choose between 3 fighting styles will appeal to seasoned gamers while making the game accessible to newcomers.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1184560/header.jpg?t=1718316820', 0, 0, NULL);
INSERT INTO games VALUES (131113, 1184990, 'Huuma Mina: The Secret of Immortality', 'In legend, Huuma Mina is an immortal ninja with silver hair and silver eyes. A mad scientist, Arakawa Murasaki, tries to capture her in order to research her secret of immortalization. However, will Murasaki succeed in her study? Will science be able to reveal the secret of immortalization?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1184990/header.jpg?t=1745510685', 0, 0, NULL);
INSERT INTO games VALUES (139504, 1188250, 'GLOWCOMA: chapter 1', 'GLOWCOMA: chapter 1 is a Sci-Fi FPS survivor horror game.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1188250/header.jpg?t=1574497660', 0, 0, NULL);
INSERT INTO games VALUES (136467, 1188930, 'Chrono Ark', 'Chrono Ark is a singleplayer roguelike that combines elements from deckbuilders and party-based RPGs. Recruit, train, and build a team of unique Investigators to restore the Twisted World!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1188930/header.jpg?t=1730548823', 1, 0, NULL);
INSERT INTO games VALUES (138378, 1189100, 'Rise Of The White Sun', 'A Giant Strategy Sandbox experience set in Warlord China. *Tons of playable factions! *Communist insurgents, * Boxers like rebels, *Greedy warlords, *Mongol riders, *A mad russian baron, *Shanghai gangsters, *And armored trains!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1189100/header.jpg?t=1743699593', 1, 0, NULL);
INSERT INTO games VALUES (131801, 1189230, 'Door in the Woods', 'This game is a venture into an alternative timeline in which graphics and sensible game design were never invented.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1189230/header.jpg?t=1575892969', 0, 0, NULL);
INSERT INTO games VALUES (129320, 1190000, 'Car Mechanic Simulator 2021', 'Work your way to a service empire. Get your hands dirty in a highly realistic simulation game that pays major attention to details. Pay a visit to a new Auction house and buy cars in various conditions. Expand your range of services by investing in a new work space and equipment.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1190000/header.jpg?t=1748939380', 1, 0, NULL);
INSERT INTO games VALUES (137550, 1190970, 'House Flipper 2', 'Clean your worries away with this relaxing renovation simulator! Buy, fix, sell, and become a local legend. Or grab your power tools and build anything from scratch! With the online 2-4 players co-op mode, you can play both in sandbox and story mode together.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1190970/a8c4bf872d073e27e96c2179e19a5cd9971bfd2e/header.jpg?t=1749333838', 1, 0, NULL);
INSERT INTO games VALUES (135283, 1191580, 'Nexomon', 'Catch, evolve and collect over 300 unique Nexomon! Assemble the ultimate Nexomon team to save your friends and save the world! Clash against legendary champions and become a hero in this epic journey!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1191580/header.jpg?t=1667379894', 0, 0, NULL);
INSERT INTO games VALUES (130573, 1191630, 'Shantae and the Seven Sirens', 'Shantae is back in an all-new tropical adventure! In her fifth outing, the Half-Genie hero gains new Fusion Magic abilities to explore a vast sunken city, makes new Half-Genie friends, and battles the Seven Sirens in her biggest, most thrilling quest yet!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1191630/header.jpg?t=1717695728', 1, 0, NULL);
INSERT INTO games VALUES (131179, 1191660, 'Rebel Transmute', 'Rebel Transmute is a challenging 2D action-platformer epic with heart! Explore the twisting caverns of an alien planet, augment your play-style to fit your strengths, battle deadly bosses, and uncover a dark truth as Moon Mikono searches for her long lost mother.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1191660/header.jpg?t=1748381537', 1, 0, NULL);
INSERT INTO games VALUES (139077, 1192380, 'TOTALLY BASEBALL', 'Play the full sport of Baseball (every position) on your own or with your friends! (No subscription needed!)', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1192380/header.jpg?t=1702324670', 0, 0, NULL);
INSERT INTO games VALUES (138771, 1192440, 'The Monster Breeder', 'Turn-based fantasy gladiatorial game with monster breeding. Crossbreed various species to create monster hybrids for gladiatorial combat. Manipulate creatures’ traits with surgery, magic, and alchemy. Manage your enterprise, craft items and upgrade your base. Fight in the arena for gold and glory!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1192440/1a1a5e94de86e3be7e853504fc9693f7957123a2/header.jpg?t=1746618706', 0, 0, NULL);
INSERT INTO games VALUES (131962, 1192900, 'IRON REBELLION', 'Climb inside a colossal, crushing war machine, where every switch, lever, and round of ammunition is at your command. Physically interact with every support system and navigation stick as if you were truly in the cockpit. Customize and outfit your mech to outsmart and assert your superiority.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1192900/header.jpg?t=1736357978', 0, 0, NULL);
