INSERT INTO games VALUES (129266, 1260320, 'Party Animals', 'Fight your friends as puppies, kittens and other fuzzy creatures in PARTY ANIMALS! Paw it out with your friends remotely, or huddle together for chaotic fun on the same screen. Interact with the world under our realistic physics engine. Did I mention PUPPIES?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1260320/header.jpg?t=1749110461', 1, 0, NULL);
INSERT INTO games VALUES (128822, 1262240, 'Plants vs. Zombies: Battle for Neighborville™', 'Kick some grass in Plants vs. Zombies: Battle for Neighborville, the wackiest shooter yet!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1262240/header.jpg?t=1747167474', 1, 0, NULL);
INSERT INTO games VALUES (135335, 1262460, 'Zompiercer', 'Take control of the train which will become your haven on the rails. Collect resources, craft equipment, construct a cozy house on railway cars, and travel through the carefully handcrafted locations to explore the story of a zombie apocalypse world.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1262460/3d0eb5e1b9c22ba69e94e0f3bf7acc88779b4409/header.jpg?t=1749141355', 1, 0, NULL);
INSERT INTO games VALUES (128823, 1262540, 'Need for Speed™', 'Ready to own the streets? Get behind the wheel of iconic cars and floor it through Ventura Bay, a sprawling urban playground. Explore overlapping stories as you build your reputation – and your dream car – and become the ultimate racing icon.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1262540/header.jpg?t=1716834386', 0, 0, NULL);
INSERT INTO games VALUES (128824, 1262560, 'Need for Speed™ Most Wanted', 'The open-world action in Need for Speed Most Wanted gives you the freedom to drive your way. Hit jumps and shortcuts, switch cars, lie low or head for terrain that plays to your vehicle’s unique strengths. Fight your way past cops and rivals using skill, high-end car tech and tons of nitrous.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1262560/header.jpg?t=1605151411', 0, 0, NULL);
INSERT INTO games VALUES (128825, 1262580, 'Need for Speed™ Payback', 'Set in the underworld of Fortune Valley, you and your crew were divided by betrayal and reunited by revenge to take down The House, a nefarious cartel that rules the city’s casinos, criminals and cops. In this corrupt gambler’s paradise, the stakes are high and The House always wins.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1262580/header.jpg?t=1692306558', 0, 0, NULL);
INSERT INTO games VALUES (128826, 1262600, 'Need for Speed™ Rivals', 'Erase the line between single player and multiplayer in this street-racing rivalry between Cops and Racers. Seamlessly join a world where your friends are already racing and chasing.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1262600/header.jpg?t=1625518950', 0, 0, NULL);
INSERT INTO games VALUES (131677, 1264250, 'Fishing: North Atlantic - Enhanced Edition', 'Commercial fishing in North Atlantic! Discover majestic world of Canadian Nova Scotia while admiring the vast diversity of ocean life. Search for the ocean gold with upgradable fishing boats and various fishing gear as you progress in your fisherman career.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1264250/header.jpg?t=1748452340', 1, 0, NULL);
INSERT INTO games VALUES (139534, 1264520, 'Vibrant Venture', 'Vibrant Venture is a singleplayer 2D adventure platformer game featuring a quirky cast of characters! The game features four playable characters with multiple unique abilities that can be combined for extremely versatile, fluid and fun movement!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1264520/header.jpg?t=1741460298', 0, 0, NULL);
INSERT INTO games VALUES (128080, 1265800, 'Hubris', 'Hubris is a VR action-adventure game set in a unique and colourful Sci-Fi universe, with immersive movement options, including swimming, climbing, and jumping. Players will have to gather resources, craft food and upgrade their weapons to fight off alien wildlife, droids, and humanoid enemies.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1265800/header.jpg?t=1708101058', 1, 0, NULL);
INSERT INTO games VALUES (139696, 1265920, 'Life is Strange Remastered', 'Experience the BAFTA award-winning story of Life is Strange now beautifully remastered with enhanced visuals and vastly improved animation using mocap technology.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1265920/header.jpg?t=1748420882', 0, 0, NULL);
INSERT INTO games VALUES (131752, 1266540, 'Ships At Sea', 'Experience the thrill of navigating a wide range of ships. In single- and multiplayer modes, immerse yourself in tasks such as service, cargo transport, and commercial fishing as you explore the breathtaking open world of Norway´s Islands and its stunning scenery. The ocean is within your reach!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1266540/header.jpg?t=1748452304', 0, 0, NULL);
INSERT INTO games VALUES (139606, 1266690, 'Dark Deception: Monsters & Mortals', 'Dark Deception: Monsters &amp; Mortals is a multiplayer horror party game with multiple modes where players take on the role of monsters or mortals from Dark Deception''s universe (and other universes) and fight for soul shards in nightmarish mazes!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1266690/header.jpg?t=1742358507', 0, 0, NULL);
INSERT INTO games VALUES (136232, 1268750, 'Starship Troopers: Extermination', 'Starship Troopers: Extermination is a 16-player co-op FPS that puts you on the far-off frontlines of an all-out battle against the Bugs! Squad up, grab your rifle, and do your part as an elite Deep Space Vanguard Trooper to take back planets from the Arachnid threat!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1268750/header.jpg?t=1743712972', 0, 0, NULL);
INSERT INTO games VALUES (132078, 1269020, 'No Plan B', 'Carefully plan your team''s tactics in close quarters battles. Use the timeline to synchronize each door breach, grenade throw and room entry with precision. Watch your team execute your plan autonomously in epic cinematic replays. Take on challenging roguelike campaigns or standalone missions.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1269020/header.jpg?t=1743098166', 1, 0, NULL);
INSERT INTO games VALUES (139081, 1269710, 'Kainga: Seeds of Civilization', 'Welcome to the mystical world of Kainga, an unusual roguelite village-builder! Take control of a Thinker and, with the help of your people, grow a unique town to complete short challenges while discovering the world and adapting to the pressures of the environment, beasts and other tribes.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1269710/header.jpg?t=1739647551', 0, 0, NULL);
INSERT INTO games VALUES (135514, 1272080, 'PAYDAY 3', 'PAYDAY 3 is the much anticipated sequel to one of the most popular co-op shooters ever. Since its release, PAYDAY-players have been reveling in the thrill of a perfectly planned and executed heist. That’s what makes PAYDAY a high-octane, co-op FPS experience without equal.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1272080/header.jpg?t=1748272922', 1, 0, NULL);
INSERT INTO games VALUES (131149, 1273080, 'Raptor Boyfriend: A High School Romance', 'Raptor Boyfriend: A High School Romance is a dating sim about a teen girl who moves to a small secret community of cryptids. Romance a magical Fairy, a sensitive Sasquatch and a bold Velociraptor. A satirical 90''s teen drama about trying to find love in your last year of high school.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1273080/header.jpg?t=1668442656', 0, 0, NULL);
INSERT INTO games VALUES (130729, 1273100, 'Builders of Greece', 'Immerse yourself in the beautifully recreated golden age of Hellenic city-states. Builders of Greece is a city management game that lets you display your strategic and economic mastery. Build your Polis from scratch, make meaningful decisions, trade, fight and expand to become the ultimate ruler.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1273100/fd93182e6ba9e037ae1793246cb46b783eed4790/header.jpg?t=1746621456', 0, 0, NULL);
INSERT INTO games VALUES (135394, 1273440, 'OverDrift Festival', 'Become the star on festival of car culture and sports. Drift races and Free Style Drift tours on public roads with traffic. Huge game world, iconic tracks. Unique collection of cars. Wide range of tuning and styling options. Accurate physics: a sense of speed and lateral g-forces.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1273440/header.jpg?t=1724747397', 0, 0, NULL);
INSERT INTO games VALUES (131828, 1274600, 'The Last Faith', 'A dark, gothic fusion of metroidvania and soulslike. The Last Faith thrives on merciless and precise combat with a huge range of weapons, firearms, and custom executions at your disposal. Let nothing stand in your way.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1274600/header.jpg?t=1725452590', 1, 0, NULL);
INSERT INTO games VALUES (130171, 1277930, 'Riddle Joker', 'For decades, superpowers and psychic abilities were thought to be mere science fiction, but the discovery of a certain particle called the &quot;Astron&quot; at the end of the 20th century proved to the world that these wondrous phenomena were real.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1277930/header.jpg?t=1747875621', 0, 0, NULL);
INSERT INTO games VALUES (136363, 1278540, 'Esports Godfather', 'E-sports Godfather is a Deck-building game simulating MOBA e-sports. You will play a role as team coach and build your team. You need to train players and make strategies in various game versions, beat other teams and finally, take the Champion of the World. Be nobody, or lead your team to dominate!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1278540/header.jpg?t=1736225046', 0, 0, NULL);
INSERT INTO games VALUES (131861, 1282200, 'The Test: Hypothesis Rising', 'The second chapter in The Test trilogy. Answer a series of in-depth questions to reveal hidden truths about yourself and unlock secrets to discover how your life can change drastically with just a few, slight modifications. ...But are you sure you want the answers you seek?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1282200/header.jpg?t=1746587550', 0, 0, NULL);
INSERT INTO games VALUES (128827, 1282690, 'Crysis® 3', 'The fate of the world is in your hands. New and old enemies threaten the peace you worked so hard to achieve 24 years ago. Your search for the Alpha Ceph continues, but this time you''ll also need to expose the truth behind the C.E.L.L. corporation.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1282690/header.jpg?t=1694101866', 0, 0, NULL);
INSERT INTO games VALUES (127996, 1283970, 'YoloMouse - Game Cursor Changer', 'Use YoloMouse to change those obscure game cursors. Never lose your cursor in a heated battle again!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1283970/header.jpg?t=1747992177', 0, 0, NULL);
INSERT INTO games VALUES (136033, 1284190, 'The Planet Crafter', 'A space survival open world terraforming crafting game, designed for 1 to 10 players. Alter the ecosystem of an inhospitable planet to render it habitable for humanity. Survive, gather resources, and build your base. Then, generate oxygen, warmth, and pressure to create a brand new biosphere.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1284190/3279e7783d71c91bb5f5b951baf0c5280879e934/header_alt_assets_10.jpg?t=1748077331', 1, 0, NULL);
INSERT INTO games VALUES (130575, 1284820, 'Desktop Kanojo', 'This is a desktop mascot that can be placed anywhere on your desktop to bring more fun to your desktop', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1284820/header.jpg?t=1736386799', 1, 0, NULL);
INSERT INTO games VALUES (140484, 1286220, 'Sea Power : Naval Combat in the Missile Age', 'From the lead designer of Cold Waters, Sea Power lets you control NATO and Warsaw Pact forces in modern naval conflict campaigns. Use your advanced naval weaponry and sensors to respect rules of engagement and defeat the enemy forces in a tense fight for initiative and air/naval supremacy.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1286220/header.jpg?t=1746189414', 0, 0, NULL);
INSERT INTO games VALUES (136941, 1286350, 'BPM: BULLETS PER MINUTE', 'BPM is a rhythm-action FPS rogue-like where you must shoot, jump and dodge to the beat of an epic rock soundtrack. Delve into a randomly generated dungeon where one missed note can lead to your death. Gain game-changing abilities and loot powerful weaponry to defeat your ancient enemy: Nidhogg.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1286350/header.jpg?t=1667228772', 0, 0, NULL);
INSERT INTO games VALUES (132631, 1286580, 'Ship of Fools', 'Ship of Fools is a seafaring cooperative roguelite. Set sail, man the cannons and battle sea monsters through the tempestuous seas of the Archipelago. Are you fool enough to stop the Aquapocalypse?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1286580/993ef36d084850f29ee6c3f0a14777b91d465a51/header_alt_assets_2.jpg?t=1747757665', 1, 0, NULL);
INSERT INTO games VALUES (135396, 1286680, 'Tiny Tina''s Wonderlands', 'Embark on an epic adventure full of whimsy, wonder, and high-powered weaponry! Roll your own multiclass hero then shoot, loot, slash, and cast on a quest to stop the Dragon Lord.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1286680/header.jpg?t=1737970341', 1, 0, NULL);
INSERT INTO games VALUES (132786, 1286830, 'STAR WARS™: The Old Republic™', 'STAR WARS™: The Old Republic™ is a free-to-play MMORPG that puts you at the center of your own story-driven saga. Play as a Jedi, Sith, Bounty Hunter, or one of many other iconic STAR WARS roles in the galaxy far, far away over three thousand years before the classic films.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1286830/header.jpg?t=1745945988', 0, 1, NULL);
INSERT INTO games VALUES (139210, 1289310, 'Helltaker', 'Helltaker is a short game about sharply dressed demon girls.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1289310/header.jpg?t=1620755466', 0, 1, NULL);
INSERT INTO games VALUES (139913, 1289810, 'Siralim Ultimate', 'Siralim Ultimate is a monster-catching, dungeon-crawling RPG with a ridiculous amount of depth. Summon over 1200 different creatures and travel through randomly generated dungeons to acquire resources, new creatures, and loot.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1289810/header.jpg?t=1745441880', 0, 0, NULL);
INSERT INTO games VALUES (138372, 1290330, 'Time Wasters', 'Time Wasters is a space shooter bullet heaven roguelite. Equip and upgrade weapons, destroy swarms of enemies, and collect Time &amp; Space Cubes to bend the timeline to your advantage.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1290330/header.jpg?t=1736381331', 1, 0, NULL);
INSERT INTO games VALUES (139320, 1292020, 'Armoured Commander II', 'In this roguelike wargame, take command of a tank and its crew in the Second World War, joining one of over 50 campaigns across Europe, North Africa, Southeast Asia, and the Pacific. Fight with and against over 800 historically-based unit types, where each day is a struggle for survival.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1292020/header.jpg?t=1734251830', 0, 0, NULL);
INSERT INTO games VALUES (127636, 1292690, 'Corruption of Champions II', 'Corruption of Champions II is an erotic text-based adventure RPG in which you contend with an invasion of perverse demons into your home realm. Romance friends and enemies such as catgirl clerics and kitsune mages, transform your body, and try to defeat the spreading corruption - or surrender to it!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1292690/header.jpg?t=1715086969', 0, 0, NULL);
INSERT INTO games VALUES (132561, 1293160, 'The Medium', 'Discover a dark mystery only a medium can solve. Travel to an abandoned communist resort and use your unique psychic abilities to uncover its deeply disturbing secrets, solve dual-reality puzzles, survive encounters with sinister spirits, and explore two realities at the same time.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1293160/header.jpg?t=1743602524', 0, 0, NULL);
INSERT INTO games VALUES (135976, 1293820, 'YOU and ME and HER: A Love Story', 'YOU and ME and HER: A Love Story is the visual novel medium in its purest form. Will Shinichi choose Miyuki, the beautiful queen bee of the school, or the endearingly awkward misfit Aoi? With art by Tsuji Santa, these beautifully rendered romances will stay with you forever.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1293820/header.jpg?t=1730126497', 0, 0, NULL);
INSERT INTO games VALUES (130706, 1294760, 'HARD BULLET', 'HARD BULLET is a physics-based action game, where enemies flood the neon-lit city bringing destruction to its streets. Use slow-motion, a huge arsenal, and brutal combat to survive and unlock new weapons. Prepare for the next RIDE by mastering your skills in Sandbox and Arena modes.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1294760/header.jpg?t=1748447096', 1, 0, NULL);
INSERT INTO games VALUES (136181, 1294810, 'Redfall', 'The town of Redfall is under siege by a legion of vampires who have cut the island off from the outside world. Trapped with a handful of survivors, slay alone or squad up in open-world FPS action.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1294810/header.jpg?t=1715094761', 1, 0, NULL);
INSERT INTO games VALUES (134978, 1295500, 'Warhammer 40,000: Battlesector', 'Warhammer 40,000: Battlesector is a fast-paced turn-based strategy game set in the grimdark universe of the 41st Millennium. Pick your force, develop your army, field mighty heroes and fight for victory using superior strategy, awesome abilities, and devastating weaponry.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1295500/header.jpg?t=1747933584', 1, 0, NULL);
INSERT INTO games VALUES (139609, 1295660, 'Sid Meier''s Civilization VII', 'The award-winning strategy game franchise returns with a revolutionary new chapter. Sid Meier''s Civilization® VII empowers you to build the greatest empire the world has ever known!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1295660/header.jpg?t=1747775524', 1, 0, NULL);
INSERT INTO games VALUES (132260, 1296450, 'Dust & Neon', 'Rain down hell on the robot army in DUST &amp; NEON, an award-winning best-in-class post-apocalyptic shooter where twitchy-finger gunslingers are rewarded with fame and glory.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1296450/header.jpg?t=1699463400', 1, 0, NULL);
INSERT INTO games VALUES (130951, 1296610, 'Peglin', 'Peglin is a Pachinko Roguelike - Fight enemies by collecting special orbs and popping pegs to deal damage. Acquire special relics that radically change the game and ensure no two runs are the same. Aim carefully to survive in this unique turn-based RPG!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1296610/header.jpg?t=1744561439', 1, 0, NULL);
INSERT INTO games VALUES (130952, 1296830, '暖雪 Warm Snow', '''Warm Snow'' is a Rogue-like action game with a background set in a dark fantasy world, where the eerie ''Warm Snow'' holds sway. You will play as the Warrior ''Bi-an'' on a crusade against the Five Great Clans, in order to save a world teetering on the brink of destruction.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1296830/header.jpg?t=1748250516', 1, 0, NULL);
INSERT INTO games VALUES (127948, 1299170, 'Ova Magica', 'Stardew Valley meets Pokémon! Experience a content-rich JRPG game inspired by the classics! Raise cute blob creatures, take care of your farm and make friends with the people of Clover Town.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1299170/68121ccc3c352d517acece328df1f5115db78763/header.jpg?t=1748528660', 0, 0, NULL);
INSERT INTO games VALUES (131141, 1299400, 'Understand', 'Understand is an experimental puzzle game about guessing rules. In each level, you have to figure out the rules through trial and error, then draw a line satisfying all rules.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1299400/header.jpg?t=1728560533', 1, 0, NULL);
INSERT INTO games VALUES (135481, 1300600, 'Blind Drive', 'An audio-based black comedy action arcade game - Blind Drive is a video game you can play with your eyes closed! 1st person hyper-realistic audio adventure meets fast paced arcade gameplay, driven by an insane B-movie plot.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1300600/header.jpg?t=1745910212', 0, 0, NULL);
INSERT INTO games VALUES (131378, 1304400, 'The End of Dyeus', 'Go in a quest for Dyeus in a primitive and cryptic open world ! Face mysterious assailants in intense and fast paced sword fights, and survive against a carnivorous fauna. Will you uncover the truth about Dyeus?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1304400/header.jpg?t=1748019637', 0, 0, NULL);
INSERT INTO games VALUES (131421, 1304430, 'Viking Frontiers', 'Survival of your people - that''s the only thing that matters. Become the leader of a newly founded Viking settlement and lead it to safety and glory. Gather, build, craft, hunt, raid and follow your Gods to endure hardships of nature and save your clan from violent destruction.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1304430/header.jpg?t=1747476787', 0, 0, NULL);
INSERT INTO games VALUES (102675, 1304610, 'Lab Rat', 'A metrics-obsessed AI will monitor, profile, and entertain you as you progress through over a hundred genre-bending puzzles in this delightfully satirical adventure.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1304610/27211c6a47dbd860cb5e8213e488e991082796ac/header.jpg?t=1744973588', 0, 0, NULL);
INSERT INTO games VALUES (135166, 1304930, 'The Outlast Trials', 'Red Barrels invites you to experience mind-numbing terror, this time with friends. Whether you go through the trials alone or in teams, if you survive long enough and complete the therapy, Murkoff will happily let you leave… but will you be the same?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1304930/50246c247bf813b707c2c7cee7b7ad29148e0228/header.jpg?t=1745332104', 1, 0, NULL);
INSERT INTO games VALUES (102652, 1305080, 'GearBlocks', 'Explore a world of creative building, interactive machines, and gears - lots of gears. Build all things mechanical: cars, trucks, cranes, tanks, gearboxes, engines, clocks, anything you can think of. Test your creations to destruction in challenging scenarios, and share them in the workshop!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1305080/header.jpg?t=1727545250', 0, 0, NULL);
INSERT INTO games VALUES (102661, 1305300, 'Love Love School Days', 'The protagonist is trapped in the world of a love game. Can you return to the real world again...? Try to escape while running away from the gal game heroine A love simulation-style survival horror game!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1305300/header.jpg?t=1677216852', 0, 0, NULL);
INSERT INTO games VALUES (102662, 1305310, 'Drox Operative 2', 'Drox Operative 2 is a starship action RPG with warring alien races, fierce space battles, a dynamic, evolving galaxy, and co-op multiplayer for Windows and Linux.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1305310/header.jpg?t=1724973993', 0, 0, NULL);
INSERT INTO games VALUES (102668, 1305420, 'Agrou', 'Your new favorite Werewolf game! Seat around the fire with friends, play a villager, a werewolf or another type of character and use strategy to win!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1305420/header.jpg?t=1642178505', 1, 0, NULL);
INSERT INTO games VALUES (102607, 1306620, '[Chilla''s Art] Missing Children | 行方不明', 'Missing Children | 行方不明 is a Japanese horror-themed adventure game about a bully detective searching for reported missing children.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1306620/header.jpg?t=1657960435', 0, 0, NULL);
INSERT INTO games VALUES (102608, 1306630, 'Lost Ruins', 'Lost Ruins is a 2D side-scrolling survival action game, where you play as a young girl that has awoken in a strange and foreign place without her memories. Explore a dark and dangerous world, battle hideous monsters, and topple incredible bosses.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1306630/header.jpg?t=1699433832', 1, 0, NULL);
INSERT INTO games VALUES (102609, 1306720, 'Mayhem Brawler', 'Mayhem Brawler is an urban fantasy themed beat ''em up that brings back the 90s arcade vibe to present day. With comic book style art and kick-ass soundtracks, it offers a unique experience that you can tackle solo or as co-op with friends while defining the next step in the story with your choices.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1306720/header.jpg?t=1743162376', 1, 0, NULL);
INSERT INTO games VALUES (102600, 1307090, 'Barro Racing', 'Jump!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1307090/header.jpg?t=1738798261', 0, 0, NULL);
INSERT INTO games VALUES (102589, 1307550, 'Craftopia', 'Craftopia is the brand new multiplayer survival action game made in Japan. We combined many features we find enjoyable, such as hunting, farming, hack-and-slash, building, automation to develop this game.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1307550/0358effe133395e89a754ef3089c3e217ae1d877/header_alt_assets_9.jpg?t=1745915016', 0, 0, NULL);
