INSERT INTO games VALUES (130915, 1407450, 'The World of Kungfu: Dragon and Eagle', 'Make a name for yourself in this old-school Wuxia RPG. Explore the chaotic lands of ancient China and engage in challenging turn-based battles to change the world of kungfu forever.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1407450/header.jpg?t=1741226613', 0, 0, NULL);
INSERT INTO games VALUES (132888, 1408230, 'Walkabout Mini Golf VR', 'Escape into a fun and beautiful world filled with the best mini golf courses you’ve ever seen! Play by yourself, meet someone new, or challenge your friends in a private game with up to 8 people. Extremely realistic physics create the perfect experience for hardcore golfers and casual players alike.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1408230/header.jpg?t=1746115969', 1, 0, NULL);
INSERT INTO games VALUES (135611, 1411020, 'Perennial Order', 'Perennial Order is a 2D plant horror boss rush with challenging one-hit-death combat. Set in an atmospheric Dark Age world plagued by nature-infested horrors, explore a lore-filled and eldritch land alone or in two player co-op, all in a realistic painterly style.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1411020/header.jpg?t=1740409242', 1, 0, NULL);
INSERT INTO games VALUES (128006, 1411910, 'Fallen Aces', 'The A.C.E.S, watchful guardians of Switchblade City, are being taken down, one by one. Now it''s up to one man, with two fists, to get to the bottom of it all. Fallen Aces is a crime noir FPS that plays right out of the ''90s and looks like it''s right outta the comics.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1411910/header.jpg?t=1748862476', 0, 0, NULL);
INSERT INTO games VALUES (130880, 1416050, 'Shovel Knight Dig', 'Meet new friends and foes, visit strange lands, and outfit yourself in your quest to keep the entire land from collapsing underfoot! Jump, slash, and dig your way down an ever-changing chasm of mystery in Shovel Knight Dig, an all-new Shovel Knight adventure!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1416050/header.jpg?t=1723577948', 1, 0, NULL);
INSERT INTO games VALUES (135548, 1417420, 'Endless Furry Killer 2020', 'Endless Furry Killer 2020 is the game that lets you kill furries endlessly! Shoot furries in a endless 2D top down action packed adventure! Fun for the whole family!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1417420/header.jpg?t=1721423591', 0, 0, NULL);
INSERT INTO games VALUES (138002, 1419850, 'Saleblazers', 'Fight. Sell. Survive. Live off the land, build your perfect shop, and defend against nightly horrors in this open world survival shop simulator for 1-8 players.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1419850/header.jpg?t=1749590670', 1, 0, NULL);
INSERT INTO games VALUES (127682, 1420350, 'Fraymakers', 'Fraymakers is the ultimate customizable platform fighting game, featuring a cast of some of indie gaming''s biggest icons. Duke it out with up to 4 players and call on assists to help out in the heat of battle. Create and play custom characters, stages, modes, and more for infinite fun!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1420350/header.jpg?t=1738894537', 0, 0, NULL);
INSERT INTO games VALUES (129729, 1420540, 'CATch the Stars', 'CATch the Stars is a minimalist puzzle with a pleasant and original soundtrack. Click on the right star, solve the puzzles and form constellations with a beautiful and relaxing environment. No score, no timer and no pressure.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1420540/header.jpg?t=1748014564', 0, 0, NULL);
INSERT INTO games VALUES (138107, 1420740, 'Your amazing T-Gotchi!', 'A cute game where you care about a green anime girl!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1420740/header.jpg?t=1645016083', 1, 0, NULL);
INSERT INTO games VALUES (136882, 1421290, 'Battle Shapers', 'Battle Shapers is an action-packed, sci-fi FPS roguelite in which you shoot and smash your way through swarms of corrupt robots. Wield powerful weapons, abilities, and game-changing new powers stolen from ruthless Overlords.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1421290/78e3460cf67c4475e21507540fbdd1c42f1f31a6/header.jpg?t=1747316390', 0, 0, NULL);
INSERT INTO games VALUES (130057, 1422130, 'SimRail - The Railway Simulator', 'SimRail is new, advanced railway simulator. Master high-speed long-distance EMU, heavy freight hauls and suburban trains. Travel 500 km of geodetic-data based real routes. Become train dispatcher and control the traffic according to the schedule or cooperate with other players on multiplayer mode.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1422130/header.jpg?t=1742504686', 0, 0, NULL);
INSERT INTO games VALUES (128697, 1422440, 'Cataclismo', 'Design and build fortresses brick by brick to stand against endless hordes of Horrors in this real-time strategy game with resource management, siege defense, and exploration. Lead from the ramparts, push back the darkness, and hold fast against the creatures of the Mist.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1422440/header.jpg?t=1749229287', 1, 0, NULL);
INSERT INTO games VALUES (127995, 1424330, 'Wobbledogs', 'A 3D pet simulation where you raise your own personal hive of mutating dogs, physically simulated all the way down to their guts! Wobbledogs is a casual and chill sandbox for players of all ages who want to care for their very own virtual pets in a surprising, unique, and stress-free environment.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1424330/header.jpg?t=1747991855', 1, 0, NULL);
