INSERT INTO games VALUES (129750, 1426010, 'STASIS: BONE TOTEM', 'Get ready for a thrilling underwater adventure with classic point-and-click gameplay. Explore with three characters simultaneously. Featuring atmospheric isometric graphics, rendered video, and a soundtrack by Mark Morgan, BONE TOTEM takes you on a journey to hidden places deep below the waves...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1426010/header.jpg?t=1745838151', 0, 0, NULL);
