INSERT INTO games VALUES (128304, 1432850, 'Farewell North', 'Play as a border collie and restore color to your human’s world in an atmospheric journey through the northern isles of Scotland. Explore land and sea, uncover hidden paths, herd animals and free wildlife to bring color back to her world, while revealing an emotional story about saying farewell.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1432850/header.jpg?t=1748006018', 0, 0, NULL);
