INSERT INTO games VALUES (35842, 1682060, 'Warriors of the Nile 2', 'Warriors of the Nile 2 is a fast-paced Roguelite strategy game. This time our Warriors are equipped with a more unique combat style. Freely choose the adventure route, use the skill tablets to strengthen characters, lead your squad to repel the Roman legion.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1682060/header.jpg?t=1745569592', 0, 0, NULL);
INSERT INTO games VALUES (35801, 1683100, 'Ultra Age', 'Slash your way through a futuristic Earth overrun with ruthless mutants and powerful robots. Now including ‘Rebirth Project,’ the all-new rogue-lite side mission that can be accessed from the main menu! (DLC installation is required.)', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1683100/header.jpg?t=1727835898', 1, 0, NULL);
INSERT INTO games VALUES (35803, 1683150, 'Railroader', 'You and your fellow railroaders are the lifeblood of your railroad, just like it is the lifeblood of the communities it serves. Switch cars at industries. Keep people moving while running local passenger trains. Run trains with a purpose in transition era Appalachia – in Railroader!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1683150/header.jpg?t=1727358779', 0, 0, NULL);
INSERT INTO games VALUES (35811, 1683320, 'Power & Revolution 2021 Edition', 'A new expansion of the ultra-realistic simulator of today''s world where you play as the head of state or as the opposition! New Features for 2021: administration of the EU, Covid vaccinations, Biden''s Challenge, political coalitions, diplomatic negotiations, worldwide tax and free-trade agreements.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1683320/header.jpg?t=1697805014', 0, 0, NULL);
INSERT INTO games VALUES (35812, 1683340, 'Kayak VR: Mirage', 'Kayak VR: Mirage is a jaw-dropping and exhilarating journey through beautiful locations, made for Virtual Reality. Maneuver our fully physically accurate kayak around checkpoints and crown yourself the fastest, or take it easy and use the free roam mode and enjoy the scenery.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1683340/header.jpg?t=1733999303', 1, 0, NULL);
INSERT INTO games VALUES (35770, 1683560, 'Ravager', 'Ravager is a role-playing game where you play a young dragon, determined to reclaim his birthright. To do so, you will need to build your power, ally with dark forces, evade justice, and whet your monstrous appetites.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1683560/header.jpg?t=1749027432', 0, 0, NULL);
INSERT INTO games VALUES (35727, 1684170, 'Fetish Locator Week Two', 'The second installment of the Fetish Locator Trilogy is here! Find out what''s next for our protagonist as he''s thrown into a lewd frenzy with over 20 girls! How will your prior choices ultimately affect things? Test your limits as you seduce and romance your way to the top in Fetish Locator!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1684170/header.jpg?t=1728388520', 1, 0, NULL);
INSERT INTO games VALUES (35738, 1684350, 'The Thaumaturge', 'The Thaumaturge is a character-driven RPG with a rich story, morally ambiguous choices, and turn-based combat. In a city on the brink of change, use your mystical powers to read emotions, uncover motives, and command folklore-inspired demons — while resisting the temptation of your own pride.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1684350/header.jpg?t=1747302029', 0, 0, NULL);
INSERT INTO games VALUES (35741, 1684410, 'Seal World', 'Meet silly seals, eat fibsh, swim, and relax!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1684410/header.jpg?t=1748617885', 0, 0, NULL);
INSERT INTO games VALUES (35710, 1684670, 'Best Forklift Operator', 'Welcome to the world of warehouses, transport, and forklifts. Join us and show that you deserve to be called the best forklift operator.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1684670/header.jpg?t=1728557233', 0, 0, NULL);
INSERT INTO games VALUES (35712, 1684720, 'Hitler Hates Anime', 'Take Adolf Hitler under your control and with the power of mighty dildo destroy all naughty anime girls!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1684720/header.jpg?t=1745247995', 1, 0, NULL);
INSERT INTO games VALUES (35723, 1684930, 'CULTIC', 'Death is only the beginning. Crawl from your grave and gear up to fight your way through the ranks of a mysterious and twisted cult. You, your guns, and your dynamite will have to shoot, slide, blast, duck, dodge, and maybe throw a gib or two to survive in this old-school-inspired shooter.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1684930/header.jpg?t=1729157129', 0, 0, NULL);
INSERT INTO games VALUES (35612, 1686940, 'Bopl Battle', 'A couch/online game where you battle your friends with unique and wild abilities. There are many choices such as a shrink ray, creating black holes, stopping time and attaching a rocket engine to the stage to send it flying. Choose a combination that synergizes well to win the round!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1686940/header.jpg?t=1746784732', 1, 0, NULL);
INSERT INTO games VALUES (35617, 1687000, 'Fading Afternoon', 'Seiji Maruyama is a middle-aged yakuza recently released from prison. Known as &quot;Gozuki&quot; (one of the demon generals from Buddhist mythology) he is the power that his oyabun counts on. But there is one thing his aniki is not taking into account: Maruyama is getting old.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1687000/header.jpg?t=1726265729', 1, 0, NULL);
INSERT INTO games VALUES (35581, 1687250, 'ARIA: Genesis', 'Blast, bomb and bang you way to finding a cure that can save your boyfriend from dying. After all, how else will you be able to enjoy his di- I mean, his amazing personality for years to come?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1687250/header.jpg?t=1725157457', 0, 0, NULL);
INSERT INTO games VALUES (35593, 1687550, 'Bear''s Restaurant', 'The award-winning indie adventure game finally arrives on Steam—now with more content than ever before! A story of love, loss, and fine dining that’s sure to warm even the most jaded of hearts.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1687550/header.jpg?t=1728660264', 1, 0, NULL);
INSERT INTO games VALUES (35558, 1687950, 'Persona 5 Royal', 'Don the mask and join the Phantom Thieves of Hearts as they stage grand heists, infiltrate the minds of the corrupt, and make them change their ways!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1687950/header.jpg?t=1733297467', 1, 0, NULL);
INSERT INTO games VALUES (35564, 1688100, 'Cat Museum', 'Immerse yourself in the bizarre art style and the surreal world of Cat Museum, a 2D side-scrolling puzzle-adventure game. Solve the strange puzzles with your mischievous cat, and unveil the truth behind the mysterious museum.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1688100/header.jpg?t=1742370578', 0, 0, NULL);
INSERT INTO games VALUES (35546, 1688580, 'A YEAR OF SPRINGS', 'Experience the stories of Haru, Erika, and Manami, a trio of friends navigating their feelings of love, connection, and just wanting to belong.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1688580/header.jpg?t=1748663912', 1, 0, NULL);
INSERT INTO games VALUES (35555, 1688750, 'Dan Sing Sing AMV Maker for Vroid VRM and MMD', 'DAN☆SING! is a tool to help you create music video with your avatar with few clicks. You would upload your VRM avatar file, VMD motion file, webM video and music into it. This provides alternative solution to Miku Miku Dance. There is a lot of improvement space. We will keep pushing the boundary.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1688750/header.jpg?t=1721008287', 1, 0, NULL);
INSERT INTO games VALUES (35525, 1689080, 'Mercury Abbey', 'In a mansion surrounded by mist, as the curse made by the Alchemist and Fairy reappears, the danger is quietly lurking in the darkness, awaiting its visitors.Follow Harrod and Willie to unravel an incredible story in Mercury Abbey, and go on an adventure that you would only find in mystery novels.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1689080/header.jpg?t=1745568860', 0, 0, NULL);
INSERT INTO games VALUES (35496, 1689350, 'My life as an archeologist', 'Click your way through 100 levels of archeological treasure hunting, loot and improve your equipment, uncover build-defining artefacts on every boss, choose between three different classes and find the one that best fits your playstyle! Research monsters cards and improve every run!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1689350/header.jpg?t=1722344919', 0, 0, NULL);
INSERT INTO games VALUES (128367, 1689500, 'Dune: Imperium', 'The award-winning board game of strategy and intrigue in the iconic universe of Dune. The Spice must flow.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1689500/header.jpg?t=1748562558', 1, 0, NULL);
INSERT INTO games VALUES (139213, 1689620, 'BLEACH Rebirth of Souls', 'Awaken the blade within you and reverse your fate in BLEACH Rebirth of Souls! Engage in thrilling battles with powerful sword abilities and characters from this legendary anime franchise.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1689620/header.jpg?t=1749592879', 1, 0, NULL);
INSERT INTO games VALUES (35511, 1689640, 'Warden''s Will', 'Warden’s Will is a fast paced movement shooter roguelite, playable solo or in up-to 3 player co-op. Choose your Warden, master unique movements and abilities, and overpower hordes of robots in intense battles. Fly, dash, smash, and turn bullet-hell into bullet-heaven!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1689640/1f1012efedb6869b85d22aef3709008940f718c8/header.jpg?t=1743758353', 1, 0, NULL);
INSERT INTO games VALUES (35479, 1689870, 'Meridian 157: Chapter 3', 'You have ventured this far, now there is no turning back. Uncover the island’s dark history by travelling through crumbling caverns and mysterious laboratories, but be warned, some may not be too welcoming of your presence…', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1689870/header.jpg?t=1627577047', 0, 0, NULL);
INSERT INTO games VALUES (35482, 1689910, 'Dōkyūsei: Bangin'' Summer', 'Dōkyūsei is a seminal classic of the dating sim genre that first blew Japan''s mind in 1992. This updated remake adds HD art, optional modern features, and for the first time ever, a global release.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1689910/header.jpg?t=1724911841', 0, 0, NULL);
INSERT INTO games VALUES (35417, 1691190, 'Rogue Waters', 'Rogue Waters is a Pirate Tactical Turn-Based Rogue-lite. Play as Captain Cutter, commanding your ship and crew through procedurally generated encounters to seek revenge. Recruit, train, and upgrade crew, use powerful sea creatures, and engage in dynamic naval and melee combat to gain the upper hand.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1691190/header.jpg?t=1748339686', 1, 0, NULL);
INSERT INTO games VALUES (35424, 1691320, 'Hellbreach: Vegas', 'Hellbreach: Vegas is a Wave-based First-Person Shooter for 1-4 players, made with passion by a one man dev team! Set your loadout, kill, and earn cash. Take a spin on the various slot machines and level up to improve your survival chances. Are you ready to try your luck?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1691320/header.jpg?t=1747921210', 1, 0, NULL);
INSERT INTO games VALUES (132057, 1691420, 'START AGAIN: a prologue', 'timeloop depression station ✦ In Stars and Time''s prototype-thingy-thing', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1691420/header.jpg?t=1747947939', 0, 0, NULL);
INSERT INTO games VALUES (35383, 1692240, 'Fortune''s Run', 'Explore a decaying industrial world left behind in humanity''s never-ending race to conquer the stars. Beneath its iron skies, desperate souls kill and steal for passage to the still-plentiful frontier worlds. Sink or swim in this high-octane first-person shooter with immersive sim elements.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1692240/header.jpg?t=1724977565', 0, 0, NULL);
INSERT INTO games VALUES (35384, 1692250, 'F1® 22', 'Enter the new era of Formula 1® in EA SPORTS™ F1® 22 the official videogame of the 2022 FIA Formula One World Championship™.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1692250/header.jpg?t=1709056193', 0, 0, NULL);
INSERT INTO games VALUES (35368, 1692700, 'SimplePlanes VR', 'SimplePlanes VR is a flight sim with an ever-expanding collection of hand-crafted aircraft to download and fly for free. Airplanes, helicopters, cars, boats, and more are available and new crafts are added every day.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1692700/header.jpg?t=1726260115', 0, 0, NULL);
INSERT INTO games VALUES (35320, 1693040, 'Synthwave Burnout', 'The lost highway awaits you to take you beyond the horizon. Relax and let the sounds of synthwave open the way into the realm of neon - a world of revived imagination and fantasy, more real than reality itself.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1693040/c71c74f6e28621f8ed383d35f0c84cc51b751c5b/header.jpg?t=1747130918', 1, 0, NULL);
INSERT INTO games VALUES (35316, 1693980, 'Dead Space', 'The sci-fi survival-horror classic returns, completely rebuilt to offer an even more immersive experience — including visual, audio, and gameplay improvements — while staying faithful to the original game’s thrilling vision.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1693980/header.jpg?t=1749125590', 1, 0, NULL);
INSERT INTO games VALUES (35287, 1694420, 'Card Survival: Tropical Island', 'Card Survival is a card-based survival experience. Stranded on a desert island you must use your wits and skills to stay alive. Use cards and combine them together to explore, gather resources and craft useful tools.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1694420/header.jpg?t=1711408884', 1, 0, NULL);
INSERT INTO games VALUES (35243, 1694510, 'Barista Simulator', 'Barista Simulator, master the art of brewing with over 30 coffee recipes. Start with a basic setup, upgrade your café, manage your staff, and build your very own coffee haven. Are you ready for the ultimate coffee journey?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1694510/header.jpg?t=1730550324', 0, 0, NULL);
INSERT INTO games VALUES (35247, 1694600, 'THE HOUSE OF THE DEAD: Remake', 'THE HOUSE OF THE DEAD: Remake is a remade version of the game introduced in 1997 in arcade platform. A classic arcade rail-shooter receives a whole new entourage and gameplay changes to suit modern gaming standards.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1694600/header.jpg?t=1726575165', 0, 0, NULL);
INSERT INTO games VALUES (35235, 1694960, 'Furry Feet', 'Furry Feet...Or Paws if you prefer. Does anything else has to be said?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1694960/header.jpg?t=1715036190', 0, 0, NULL);
INSERT INTO games VALUES (35213, 1695670, 'ScrewUp', 'Screwup 1.0 The update includes new features such as a new combat system, official server system, exploring new islands by ship, NPC trading, and rare item trading. There are also new hunting and pet systems, as well as many other features that will be added in future updates.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1695670/header.jpg?t=1690523968', 0, 0, NULL);
INSERT INTO games VALUES (35216, 1695791, 'Halo 3 Mod Tools - MCC', '', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1695791/header.jpg?t=1670445790', 0, 0, NULL);
INSERT INTO games VALUES (35222, 1695830, 'Baldur''s Gate: Dark Alliance', 'A new legacy begins...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1695830/header.jpg?t=1654887460', 0, 0, NULL);
INSERT INTO games VALUES (35223, 1695840, 'Fear Therapy', 'Fear Therapy, is a multiplayer(1-4) and single player psychological horror game.Try to complete the quests and leave the horror house before it is too late! Satan getting angrier every second and nothing holding it back.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1695840/header.jpg?t=1685651338', 1, 0, NULL);
INSERT INTO games VALUES (35190, 1696080, 'Deadwater Saloon', 'Dive into the wild west as a saloon owner in a volatile frontier town. Customize your character and face the consequences of your choices as you forge friendships and enemies of townsfolk, travellers, outlaws and lawmen. Build the most famous saloon in the territory, or be overwhelmed and destroyed.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1696080/header.jpg?t=1727395049', 0, 0, NULL);
INSERT INTO games VALUES (35196, 1696220, 'FixFox', 'Arriving on a curious planet, Vix and her toolbox Tin explore space, fixing machines with unconventional tools and eating cozy meals with kind robot locals. On an epic adventure, the duo repairs an interstellar beacon, constructs giant mechs, and unravels a cosmic mystery that transcends existence.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1696220/header.jpg?t=1746170141', 1, 0, NULL);
INSERT INTO games VALUES (35178, 1696440, 'The Matchless Kungfu', 'The Matchless Kungfu is an open world sandbox RPG game based on a WuXia background. You can play any martial arts role you imagine in this wild world. Travel through the great wilderness, or be the leader of the group. The most important thing is, build your own story and live the experience!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1696440/header.jpg?t=1748418674', 1, 0, NULL);
INSERT INTO games VALUES (35149, 1696720, 'PsiloSybil', 'An old-school, tough-as nails classic linear 3D platformer with a faithful PS1 cartoony aesthetic. 25 fully original levels, boss fights, collectibles, time-trials, and many secrets.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1696720/header.jpg?t=1727872823', 0, 0, NULL);
INSERT INTO games VALUES (35154, 1696810, 'Railroads Online', 'Build your dream railroad across a huge open world! You can build tracks and stations, drive detailed locomotives, and transport goods to earn money and experience. Play exciting Online Multiplayer sessions with your friends or create your very own sandbox!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1696810/header.jpg?t=1741682161', 0, 0, NULL);
INSERT INTO games VALUES (35162, 1696960, 'Lake Haven - Chrysalis', 'This game serves as a prequel chapter for the upcoming game ''Lake Haven''. Detective Zeke Reynold is called to investigate what he assumes will be another case he''ll quickly forget, but what he finds will be sewn into the fabric of his existence forever.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1696960/header.jpg?t=1674683345', 0, 0, NULL);
INSERT INTO games VALUES (35140, 1697700, 'Who''s Lila?', 'A reverse-detective adventure, where you control your character''s face', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1697700/header.jpg?t=1725418523', 0, 0, NULL);
INSERT INTO games VALUES (35141, 1697720, 'The Heilwald Loophole', 'The Heilwald Klinikum used to be one of the most renowned medical facilities in Germany. That all changed when that curious loophole appeared...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1697720/header.jpg?t=1643994518', 0, 0, NULL);
INSERT INTO games VALUES (35111, 1697880, 'Junkyard Truck', 'Junkyard Truck is an open-world off road driving and mechanic simulator. Build, upgrade, and maintain your old off road truck. Make money using your skills in driving, scavenging, gambling, or moonshine brewing. Try to build a truck capable of taking on the difficult challenges around the map.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1697880/header.jpg?t=1707594358', 0, 0, NULL);
INSERT INTO games VALUES (35125, 1698220, 'Teslagrad 2', 'Lumina, a young Teslamancer, finds herself stranded after her airship crash lands in Wyrmheim, a remote and treacherous land to the North. Embark on a dangerous adventure, exploring a gigantic, abandoned tower looming over a fjordside valley, on a quest to get Lumina home and back to her family.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1698220/header.jpg?t=1725488586', 1, 0, NULL);
INSERT INTO games VALUES (35094, 1698520, 'Simple Fish Adventure', 'Simple Fish Adventure is an unusual short physics-based platformer. Jump like a fish, think like a fish, be a fish! Overcome obstacles and suffer. Also includes co-op for up to 4 players.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1698520/header.jpg?t=1628276236', 0, 0, NULL);
INSERT INTO games VALUES (129815, 1699480, 'KLETKA', 'KLETKA is a co-op (up to 6 players) horror game about going down in an elevator that is trying to eat you. Feed the elevator, explore deadly floors and descend deeper.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1699480/53bead10825063725bd6287afea8a4292517d936/header.jpg?t=1746460784', 1, 0, NULL);
INSERT INTO games VALUES (35017, 1699860, 'Parkour Tag', 'Parkour Tag is a platforming PvP game that faces two-players off in a competitive game of movement. Run vertically or horizontally on any wall, jump, double jump, slide, vault and more to outmaneuver your opponent and claim victory!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1699860/header.jpg?t=1729571972', 0, 0, NULL);
INSERT INTO games VALUES (35038, 1700270, 'Lucky Tower Ultimate', 'Escape from an incredibly dangerous, randomly generated tower in a slapstick, roguelite adventure that looks like a cartoon and feels like a joke. Slashy slashy!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1700270/header.jpg?t=1745531006', 0, 0, NULL);
INSERT INTO games VALUES (135159, 1700870, 'Clanfolk', 'Clanfolk is a colony sim set in the Scottish Highlands. Harness your environment to survive - fish, gather, hunt, and farm as you prepare for the winter. Build an inn, trade with other clans, have children and marry them off - live life and prosper across the generations.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1700870/header.jpg?t=1749229290', 1, 0, NULL);
INSERT INTO games VALUES (34982, 1701190, 'Chessformer', 'Chessformer is a grid-based puzzle platformer with Chess pieces. The goal in each level is to capture the opposing king, who is lazy and never moves, so don''t worry about losing any pieces.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1701190/header.jpg?t=1642521385', 0, 0, NULL);
INSERT INTO games VALUES (34989, 1701380, 'Cricket 22', 'Cricket 22 delivers the Ashes, the Big Bash, The Hundred, and a multitude of other fan-favourite competitions! All-new mechanics, commentary, and a captivating, narrative driven career mode, will immediately immerse you in the ultimate cricket experience to date.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1701380/header.jpg?t=1725870623', 0, 0, NULL);
INSERT INTO games VALUES (34951, 1701520, 'Afterimage', 'Afterimage is a hand-drawn 2D action adventure that emphasizes fast-paced combat with diversified character builds, non-linear levels, and a gripping story set in the ruins of a fantasy world.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1701520/header.jpg?t=1725487708', 1, 0, NULL);
INSERT INTO games VALUES (34962, 1701800, 'Lunistice', 'Lunistice is a 3D Platformer created with simple &amp; fun gameplay and a cute PS1/SEGA Saturn inspired artstyle in mind. Take the role of Hana the Tanuki and jump and fight through her dreams!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1701800/header.jpg?t=1730909127', 0, 0, NULL);
INSERT INTO games VALUES (140452, 1702010, 'Sengoku Dynasty', 'Sengoku Dynasty is the ultimate feudal Japan experience: build villages, grow your community, and shape the open world through combat or economy. The choice is yours alone - or that of up to 4 players in multiplayer co-op!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1702010/header.jpg?t=1748034668', 1, 0, NULL);
INSERT INTO games VALUES (34940, 1702330, 'Rune Factory 5', 'As the newest ranger of a peacekeeping organization known as SEED, protect your community by rounding up rowdy monsters and going on special missions. Cultivate your farm and friendships alike while unravelling rune-related mysteries!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1702330/header.jpg?t=1738960230', 1, 0, NULL);
INSERT INTO games VALUES (34945, 1702390, 'Voor De Kroon', 'Fight for control during the Friso-Hollandic Wars. Set in the medieval 13th century, the game features a strategy campaign and historical battles. Fight with your army in 3rd person battles and command your troops.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1702390/header.jpg?t=1747693712', 0, 0, NULL);
INSERT INTO games VALUES (34904, 1703340, 'The Stanley Parable: Ultra Deluxe', 'The Stanley Parable: Ultra Deluxe is an expanded re-imagining of 2013''s The Stanley Parable. You will play as Stanley, and you will not play as Stanley. You will make a choice, and you will become powerless. You are not here to win. The Stanley Parable is a game that plays you.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1703340/header.jpg?t=1712065263', 1, 0, NULL);
INSERT INTO games VALUES (34881, 1703610, 'I Just Want to be Single!! Season One', 'The anti-dating sim where you make friends instead of girlfriends! Balance between heartbreak and heartache! Will you graduate without a single friend? Or will you survive long enough to reject them all?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1703610/header.jpg?t=1740433930', 0, 0, NULL);
INSERT INTO games VALUES (34858, 1704080, 'Bean Stalker', 'Bean Stalker is a climbing action-adventure game. As a Stalker, you need to craft, loot and fight endless hordes of enemies to finally defeat the greatest one: the spirit of the tree. All of this in a procedurally generated environment with a touch of steampunk style.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1704080/header.jpg?t=1728301071', 0, 0, NULL);
