INSERT INTO games VALUES (33949, 1725640, 'Sudocats', 'Sudoku for cat people. Cats are wonderful creatures but you better not put them together without proper introduction. So, plan ahead to display them in the right order so they get along!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1725640/header.jpg?t=1729025686', 1, 0, NULL);
