INSERT INTO games VALUES (33883, 1726730, 'You Must', 'In the social network, the main character plays the quest &quot;Hide and Seek&quot;, but this time the organizers decided to move the quest to the real world. They indicate the coordinates of the place where the quest item was hidden, the one who finds it first will receive a cash prize.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1726730/header.jpg?t=1688032181', 0, 0, NULL);
INSERT INTO games VALUES (33884, 1726750, 'Hidden Cats in Santa''s Realm', 'It''s Christmas time! The Santa''s Icy Realm is in full steam!! Join the fun and search for all the Hidden Cats one by one among the elves to reveal the final colored art. More than 970 hidden objects! This time with an extra bonus level, SNOWBALL FIGHT!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1726750/header.jpg?t=1726414608', 0, 0, NULL);
INSERT INTO games VALUES (33885, 1726760, 'Curse Crackers: For Whom the Belle Toils', 'Curse Crackers is a fast-paced acrobatic platformer where you bounce, vault, and fight your way through a whimsical world with the help of your loyal companion. Eat snacks, collect items, and travel the world to stop Bonnie and her band of troublemakers!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1726760/header.jpg?t=1746791558', 0, 0, NULL);
