INSERT INTO games VALUES (33868, 1727420, 'Midinous', 'Midinous is a grid-based non-linear MIDI sequencer usable with any Digital Audio Workstation or hardware that accepts MIDI messages. Midinous can also generate its own simple sounds either for reference, or for normal use.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1727420/header.jpg?t=1718155362', 0, 0, NULL);
INSERT INTO games VALUES (33835, 1728660, 'Rush Rally Origins', 'The definitive top down racer', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1728660/header.jpg?t=1689001301', 1, 0, NULL);
