INSERT INTO games VALUES (33782, 1729300, 'PlayForm: Human Dynamics', 'PlayForm is an experimental physics sandbox. Physically simulated humans run, jump, climb, push, pull and smash their way through diverse worlds. Have fun with various tools and obstacles to create thrilling situations and experience next-gen physics.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1729300/header.jpg?t=1678944883', 0, 0, NULL);
INSERT INTO games VALUES (33762, 1729940, 'The Tribe Must Survive', 'The Tribe Must Survive is a survival base builder strategy game set in a harsh Lovecraftian Stone Age. Build your camp, overcome disasters and uncover new areas. Manage fears and diminish internal conflicts, as your Tribe grows. Every decision matters. Will your Tribe survive?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1729940/header.jpg?t=1727958378', 0, 0, NULL);
INSERT INTO games VALUES (33738, 1730360, 'I''m on Observation Duty 4', 'A spot the difference -type of puzzle horror game about monitoring live surveillance camera footage and spotting anomalies. Anomalies range from furniture movement to intruders. Fix anomalies by filing reports. You will need sharp eyes and good memory. The goal is to survive the entire night.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1730360/header.jpg?t=1726305201', 0, 0, NULL);
INSERT INTO games VALUES (33708, 1730650, 'REQUISITION VR', 'REQUISITION VR is a first physics-based co-op game where you can use duct tape to link any objects together to create a unique weapon. You can experiment with crafting, connecting any unthinkable combinations: a katana + a circular saw, or an axe + a ball. Inspired by Dead Rising &amp; Walking Dead: S&amp;S', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1730650/header.jpg?t=1694080127', 0, 0, NULL);
INSERT INTO games VALUES (33710, 1730680, 'Klonoa Phantasy Reverie Series', 'KLONOA is a 3D side-scrolling action game series whose first title was released by Namco in 1997. Set in a unique universe populated by a range of original characters, the game follows the hero, Klonoa, as he sets off on a journey to save the world.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1730680/header.jpg?t=1708327336', 1, 0, NULL);
