INSERT INTO games VALUES (136034, 1732190, 'FATAL FRAME / PROJECT ZERO: Maiden of Black Water', '“FATAL FRAME / PROJECT ZERO: Maiden of Black Water” comes to Steam for the first time to celebrate the 20th anniversary of the horror-adventure series FATAL FRAME / PROJECT ZERO. The game is set on sacred Mt. Hikami, a site of many mysterious and terrifying incidents.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1732190/header.jpg?t=1749026283', 0, 0, NULL);
