INSERT INTO games VALUES (124510, 1885750, 'Betrayal At Club Low', 'Tonight you''re on a rescue mission, infiltrating a nightclub that was once a coffin factory. Will you succeed? Will you fail? Or will your night take an unexpected detour? Roll the Pizza Dice and find out!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1885750/header.jpg?t=1741277850', 0, 0, NULL);
INSERT INTO games VALUES (124482, 1886070, 'USAC: Code Breach', 'USAC: Code Breach™ is a unique coop experience set in a cyberpunk universe. As a special police unit, you and your partner are called in to investigate the unexpected shutdown of a high-tech research facility. Between reflection and action, you must survive a situation that is beyond you.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1886070/header.jpg?t=1729186951', 0, 0, NULL);
INSERT INTO games VALUES (124451, 1887020, 'Robber Knight', 'RPG/Strategy. Lead your army through intense battles, make decisions that influence the story, and conquer vast lands. Play solo or fight side by side with up to 4 friends.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1887020/header.jpg?t=1737045826', 0, 0, NULL);
INSERT INTO games VALUES (129136, 1887400, 'ANTONBLAST', 'ANTONBLAST is a fast-paced explosive action platformer that''s all about destruction. Play as the enraged Dynamite Anton (or his cranked-out coworker Annie) and use your Mighty F’n Hammer to demolish bizarre worlds, tussle with screen-filling bosses, and steal your Spirits back from Satan!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1887400/header.jpg?t=1749059717', 0, 0, NULL);
INSERT INTO games VALUES (131938, 1887840, 'Another Crab''s Treasure', 'In a vibrant undersea kingdom on the verge of collapse, a hermit crab embarks on a treasure hunt to buy back his repossessed shell. The second game from AGGRO CRAB.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1887840/header.jpg?t=1748555967', 1, 0, NULL);
INSERT INTO games VALUES (124421, 1888070, 'Drain Mansion', 'You wake up in an unknown dark abandoned mansion and don''t remember how you got there. Your goal is to escape this mansion and get back home safely, but the traps and demons lurking there won''t make it easier. Can you escape this mansion or give in to the temptation?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1888070/header.jpg?t=1728883212', 1, 0, NULL);
INSERT INTO games VALUES (127897, 1888160, 'ARMORED CORE™ VI FIRES OF RUBICON™', 'A new action game based on the concept of the ARMORED CORE series that uses the knowledge gained from FromSoftware''s recent action game development.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1888160/header.jpg?t=1748630736', 1, 0, NULL);
INSERT INTO games VALUES (128155, 1889620, 'AI Roguelite', 'World''s first RPG in which all entities are AI-generated and all game mechanics are AI-directed.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1889620/header.jpg?t=1748331136', 0, 0, NULL);
INSERT INTO games VALUES (136890, 1892030, 'Dummynation', 'Geopolitical management game with real-time shifting borders and a streamlined gameplay, designed to minimize all burdensome chores while allowing an absolute strategic control, from military recruitment and deployment, to diplomatic and economic management.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1892030/header.jpg?t=1732689880', 1, 0, NULL);
INSERT INTO games VALUES (137058, 1894430, 'Plan B: Terraform', 'Terraform a lifeless rock into a lush and habitable world. Build trucks, trains and sprawling factories on an enormous hexagonal planet. Grow its population to millions. Enjoy a dynamic simulation of atmosphere, temperature, water and forests.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1894430/header.jpg?t=1748360176', 1, 0, NULL);
INSERT INTO games VALUES (137322, 1895880, 'Ratchet & Clank: Rift Apart', 'Blast your way through an interdimensional adventure with Ratchet and Clank – now on PC! Help them take on an evil emperor from another reality as you jump between action-packed worlds and beyond at hyper-speed!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1895880/header.jpg?t=1717621710', 1, 0, NULL);
INSERT INTO games VALUES (133323, 1898290, 'LEGO® Bricktales', 'In this puzzle-adventure, use an intuitive brick-by-brick building mechanic to solve puzzles and bring your creations to life! Experience a charming story as you explore beautiful LEGO® dioramas and help the people inhabiting them.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1898290/header.jpg?t=1740669584', 1, 0, NULL);
INSERT INTO games VALUES (140610, 1898610, 'Hands of Necromancy', 'Hands of Necromancy is a Dark Fantasy FPS metroidvania, inspired by classics such as Heretic and made with the GZDoom engine. Wield weapons, magic or transform into a fearsome monster to slay your foes, then raise them as undead servants and unleash even more carnage to become a master Necromancer!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1898610/header.jpg?t=1745442279', 0, 0, NULL);
INSERT INTO games VALUES (138536, 1901370, 'Ib', 'A 2D exploration adventure game set in a creepy, mysterious art gallery.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1901370/header.jpg?t=1735124072', 1, 0, NULL);
INSERT INTO games VALUES (137847, 1902650, 'Come See My Hole', 'The Metaverse, NFT''s, Virtual Reality, Augmented Reality, Web3. Come See My Hole is none of these things. In Come See My Hole, you stand next to a hole in the ground.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1902650/header.jpg?t=1713211616', 0, 0, NULL);
INSERT INTO games VALUES (135981, 1902690, 'Fate/Samurai Remnant', '“Your wish shall perish...” A Holy Grail War begins in Edo Japan. A brand new Fate action RPG presented by TYPE-MOON and KOEI TECMO GAMES.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1902690/header.jpg?t=1748479059', 1, 0, NULL);
INSERT INTO games VALUES (127976, 1902960, 'Lost Records: Bloom & Rage', 'Embark on a new narrative journey by the creators of Life is Strange. Film your summer of 1995 and create memories of a lifetime with your new friends. 27 years later, confront the dark secrets that made you all promise to never speak again after that fateful summer.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1902960/header.jpg?t=1749648578', 1, 0, NULL);
INSERT INTO games VALUES (140027, 1903340, 'Clair Obscur: Expedition 33', 'Lead the members of Expedition 33 on their quest to destroy the Paintress so that she can never paint death again. Explore a world of wonders inspired by Belle Époque France and battle unique enemies in this turn-based RPG with real-time mechanics.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1903340/be3305b02d4db0dffa3458537118423bf2792d7e/header.jpg?t=1749620180', 1, 0, NULL);
INSERT INTO games VALUES (132765, 1903560, 'Atomic Picnic', 'Atomic Picnic is a Roguelike Shooter with Explosive Synergy! Dominate chaotic battles by cutting through swarms of monsters! Team up with friends or take them on solo! Unleash devastating combos by combining and evolving powerful upgrades to conquer The Zone.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1903560/93d39d9aecdfbda7ba3b2418dd7b5c6680f2e2c2/header.jpg?t=1745434703', 0, 0, NULL);
INSERT INTO games VALUES (130790, 1904790, 'Agatha Christie - Murder on the Orient Express', 'Step on board the legendary Orient Express and immerse yourself in the most famous detective suit in a race against the clock to unmask the murderer.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1904790/header.jpg?t=1743171940', 1, 0, NULL);
INSERT INTO games VALUES (132352, 1906020, 'Drums Rock', 'Drums Rock is an arcade drums game for VR, follow the rhythm of rock with your drums and smash the demons. Live a unique campaign: with different levels, challenges, songs and worlds. Drums Rock is an ideal game to feel like a rock hero, while destroying hordes of demons to the rhythm of rock!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1906020/header_alt_assets_8.jpg?t=1740073290', 1, 0, NULL);
INSERT INTO games VALUES (131355, 1910860, 'Grimlord', 'Grimlord is a Dark Fantasy Action Souls-like RPG - on VR. Awakened in a monastery deep in the Lonely Mountains, you walk in an epic quest as the adventurer standing before the darkness and striving for the light against the tyrannical Grim Lord.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1910860/17c278f26c948bf60bb2b3d8d78d2cc5c0ff98a0/header.jpg?t=1748340291', 1, 0, NULL);
INSERT INTO games VALUES (131468, 1911610, 'Windblown', 'Brave the Vortex and dash your way to greatness in this lightning-fast action roguelite for 1-3 players from the crafters of Dead Cells. Absorb the powers of fallen warriors, rebuild their weapons, and WIPE THE FLOOR with those Sentinels in search of that perfect run!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1911610/header.jpg?t=1747326264', 1, 0, NULL);
INSERT INTO games VALUES (138150, 1911860, 'Grit and Valor - 1949', 'A dieselpunk real-time tactics roguelite set in an alt-history World War 2. Grit and Valor – 1949 puts you in command of an elite Mech Squadron. Think fast and battle the Evil Axis forces to liberate Europe. Upgrade your Mechs and Pilots and develop new strategies to neutralise the enemy HQ!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1911860/8d6027785099e9cf91c676099cca211500a73ab9/header_alt_assets_0.jpg?t=1748961096', 1, 0, NULL);
INSERT INTO games VALUES (137413, 1915380, 'Garden Life: A Cozy Simulator', 'Garden Life is a relaxing gardening game in which you create your dream garden in a peaceful, colourful world. Plant and add ornaments at your own pace, transforming an overgrown forgotten plot into a flourishing community garden.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1915380/header.jpg?t=1726215919', 1, 0, NULL);
INSERT INTO games VALUES (136035, 1915510, 'Yao-Guai Hunter', 'Yao-Guai Hunter is a Wuxia roguelike deck-building game. In a world where Yao-Guai roam free, player battles with various evil beings, collecting cards and learn inner skills. Encountering various adventures in the martial world.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1915510/e9bd4c56f88da596de468c52b648fcf878de3956/header.jpg?t=1747656778', 1, 0, NULL);
INSERT INTO games VALUES (131208, 1915550, 'Nemesis: Lockdown', 'In Nemesis: Lockdown, you''re part of a team exploring an alien-infested space base. Craft, hide and fight to make it out of its dark, threat-filled corridors. Fulfill your objective even if it means betraying your allies, but remember - this time, you are not the hunter. You are the PREY.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1915550/header.jpg?t=1724323885', 0, 0, NULL);
INSERT INTO games VALUES (135659, 1920480, 'River City Girls 2', 'The River City Girls are back! Misako, Kyoko, Kunio, and Riki - joined by newcomers Marian and Provie - hit the streets for an all-new beat-''em-up adventure! Team up for local or online co-op and explore a massive world packed with new abilities, enemies, locations, and more!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1920480/header.jpg?t=1746049994', 1, 0, NULL);
INSERT INTO games VALUES (131939, 1921900, 'The Testing Chamber', 'For every action, there is a reaction... For every choice, a result... Dive deep into your subconscious as you wander the halls of The Testing Chamber &amp; join hundreds of thousands of other players in one of the biggest &amp; most successful social experiments ever performed.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1921900/header.jpg?t=1748283874', 0, 0, NULL);
INSERT INTO games VALUES (129731, 1922010, 'Breachers™', 'Supports cross-play with Quest and PSVR2 player base. Breachers™ is a tactical 5v5 VR FPS. Plan your assault or orchestrate your defense as a team through intense close-quarters combat. Climb, vault, rappel, swing, shoot and strategize your way to victory in stunning environments.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1922010/08f14e65b035fdf2697a2bd4e12c359b4da84253/header.jpg?t=1747834164', 1, 0, NULL);
INSERT INTO games VALUES (128838, 1922560, 'Plants vs. Zombies™ Garden Warfare 2: Deluxe Edition', 'Ready the Peashooters and prepare for the craziest, funniest shooter in the universe: Plants vs. Zombies Garden Warfare 2.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1922560/header.jpg?t=1747234782', 0, 0, NULL);
INSERT INTO games VALUES (131587, 1924400, 'Hand of Doom', 'Sign a contract in blood! Travel throughout the planes of existence slaying or befriending powerful doomlords in this wizard simulator inspired by the FMV games and dungeon crawlers of the early 90''s. Learn powerful spells to solve puzzles and combat the dark forces amassing against you.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1924400/header.jpg?t=1730135149', 0, 0, NULL);
INSERT INTO games VALUES (130192, 1927920, 'Real Feel', 'Discover the next level of virtual sex simulation with Real Feel. Utilizing the latest graphic rendering technologies, combined with state of the art physics and animations systems that together produce a seemingly realistic adult film simulation that you control and interact with.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1927920/976983c43b35738c9b39a5e1fd8f72124389bbef/header.jpg?t=1749139374', 0, 0, NULL);
INSERT INTO games VALUES (137109, 1928090, 'Cook Serve Forever', 'Bathe in the sights, sounds, and story of Cook Serve Forever, a narrative cooking game where you serve delicious recipes to the hungry masses of Helianthus.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1928090/451dc8f447d55360d1e6959e8c81253efca43f28/header_alt_assets_0.jpg?t=1745942739', 0, 0, NULL);
INSERT INTO games VALUES (139797, 1931180, 'Lost Skies', 'Chart a course in a breathtaking, but fractured world. Explore ancient ruins, master advanced technology, and craft your very own skyship to brave nature’s fury and colossal threats in Lost Skies. Team up with friends or go it alone in this awe-inspiring cooperative survival adventure.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1931180/header.jpg?t=1749557065', 0, 0, NULL);
INSERT INTO games VALUES (136013, 1934570, 'South of Midnight', 'South of Midnight is a new action-adventure from Compulsion Games. Explore the mythos and confront mysterious creatures of the Deep South in this modern folktale while learning to weave an ancient power to surmount obstacles and unravel your family’s hidden past.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1934570/header.jpg?t=1744907120', 1, 0, NULL);
INSERT INTO games VALUES (139941, 1934680, 'Age of Mythology: Retold', 'From the creators of the award-winning Age of Empires franchise, Age of Mythology: Retold goes beyond history to a mythical age where gods, monsters, and humans collide.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1934680/header.jpg?t=1747265721', 1, 0, NULL);
INSERT INTO games VALUES (139892, 1936360, 'Escape From Mandrillia: Local Asymmetric VR vs PC', 'Local VR vs PC horror game: 1 VR player controls a lone robot trying to escape an underground lab; up to 2 PC players control giant alien monkeys. Customize your experience with gameplay modifiers, ranging from tense survival stealth to brutal nonstop action!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1936360/header.jpg?t=1749577477', 0, 0, NULL);
INSERT INTO games VALUES (138089, 1937500, 'Let''s School', 'Dive into the exhilarating role of a headmaster entrusted to revive your alma mater! Beyond just bricks and mortar, train teachers, recruit students. Sculpt your school into a unique educational haven! Let''s School!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1937500/header.jpg?t=1719545353', 1, 0, NULL);
INSERT INTO games VALUES (128839, 1938010, 'WILD HEARTS™', 'Master ancient tech to hunt down giant beasts. WILD HEARTS™ is a twist on the hunting genre where technology gives you a fighting chance against giant nature-infused beasts. Hunt alone or with friends.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1938010/header.jpg?t=1748945663', 1, 0, NULL);
INSERT INTO games VALUES (132208, 1938090, 'Call of Duty®', 'The Call of Duty® experience supports Call of Duty®: Black Ops 6, Call of Duty®: Modern Warfare® III, Call of Duty®: Modern Warfare® II and Call of Duty®: Warzone™.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1938090/42640a95e70bcf4695876cb30a5e9dd1517622f5/header.jpg?t=1748536349', 1, 0, NULL);
INSERT INTO games VALUES (138466, 1940200, 'Chill Town', 'A unique blend of a Soothing Simulation and an Idle Game with Music, Decoration, Fishing, Cooking, Farming and more...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1940200/header.jpg?t=1747340529', 0, 0, NULL);
INSERT INTO games VALUES (135296, 1940340, 'Darkest Dungeon® II', 'Darkest Dungeon II is a roguelike road trip of the damned. Form a party, equip your stagecoach, and set off across the decaying landscape on a last gasp quest to avert the apocalypse. The greatest dangers you face, however, may come from within...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1940340/header.jpg?t=1746646884', 1, 0, NULL);
INSERT INTO games VALUES (133409, 1942110, 'Bootstrap Island', 'Stranded in the 17th century after a brutal shipwreck, you awaken alone on a deadly tropical island. To survive, you’ll need to learn fast - facing wild beasts, nature’s wrath, and uncovering secrets hidden deep in the jungle. Every step is a fight for your life.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1942110/494fe9f23d2a6ff384acc9ad04e83f02fec1c4ae/header_alt_assets_1.jpg?t=1749202757', 0, 0, NULL);
INSERT INTO games VALUES (135953, 1942280, 'Brotato', 'Brotato is a top-down arena shooter roguelite where you play a potato wielding up to 6 weapons at a time to fight off hordes of aliens. Choose from a variety of traits and items to create unique builds and survive until help arrives.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1942280/header.jpg?t=1748254134', 1, 0, NULL);
INSERT INTO games VALUES (139177, 1943950, 'Escape the Backrooms', 'Escape the Backrooms is a 1-4 player co-op horror exploration game. Traverse through eerie backrooms levels while avoiding entities and other danger to try and escape. Free content updates with new levels and game modes keep the community rewarded.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1943950/header.jpg?t=1721158394', 1, 0, NULL);
INSERT INTO games VALUES (131985, 1946700, 'Layers of Fear', 'All stories must come to an end, even twisted and eerie ones. The canvas. The stage. The novel. This narrative-focused psychological horror experience is ready for its final brushstrokes, its curtain call, its final chapter. Are you ready to return and face your fears one last time?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1946700/header.jpg?t=1732889537', 1, 0, NULL);
INSERT INTO games VALUES (137999, 1948800, 'Yi Xian: The Cultivation Card Game', 'Yi Xian: The Cultivation Card Game is an online DBG which contains a PVE mode called Uncharted Realms and a PVP mode. Every game is a deck building from scratch. Players can have stronger decks by changing cards, and then build more powerful routines to defeat all opponents to win.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1948800/66f90f4c33944465c47118844ec14d0a7c931c39/header.jpg?t=1748268031', 0, 1, NULL);
INSERT INTO games VALUES (139839, 1954160, 'To Pixelia', 'Meet the Pixelians and discover the ultimate life simulator in To Pixelia. As you climb your career ladder of choice, step into the world of politics, art, sports, music, and even crime. Live your dream life in pixels!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1954160/777c070fbbf186cb70d3374c5d6e0a8081c1e349/header.jpg?t=1747167304', 1, 0, NULL);
INSERT INTO games VALUES (132048, 1955340, 'Super Raft Boat Together', 'The world''s been flooded. All you have left is your Super Raft Boat… and your friends! Work together to expand your raft while fending off the strangely violent (and wealthy??) creatures of the sea in this multiplayer roguelike shooter. Will your crew survive and reach the Final Island?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1955340/header.jpg?t=1727297331', 0, 0, NULL);
INSERT INTO games VALUES (138744, 1957760, 'Islands & Trains', 'Craft tiny railway dioramas in a stress-free island sandbox. No rules or timers - just design, build, and enjoy.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1957760/121551ba96debeb13c2f51a589779c3e62b7abb6/header.jpg?t=1749289593', 0, 0, NULL);
INSERT INTO games VALUES (135311, 1957780, 'Ghosts of Tabor', 'Ghosts of Tabor is VRs only FPS PVP and PVE survival game where you will use your wits, skills and resources to survive. Inspired by games such as Escape from Tarkov and DayZ, featuring different scenarios from scavenging to looting and crafting. Will you survive long enough to make it out alive?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1957780/header.jpg?t=1748546195', 0, 0, NULL);
INSERT INTO games VALUES (130661, 1958340, 'Cube Chaos', 'Cube Chaos is a complex strategy roguelike about placing units to create giant armies, factories, combos, or self replicating murder crabs, overwhelming and outsmarting your opponents. Build and adapt new strategies each run using a ludicrous variety of units, perks and more.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1958340/header.jpg?t=1747657965', 0, 0, NULL);
INSERT INTO games VALUES (135552, 1960480, 'AutoForge', 'A 2D automation sandbox adventure. Build an automated factory with Mana-powered machines, progress through an expansive tech tree, explore a vast and wonderful world, upgrade yourself with ancient technologies, and defend it all from invasions.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1960480/07f52da3313f0f320f4b15b9a9cd548ee987afb3/header.jpg?t=1747754804', 1, 0, NULL);
INSERT INTO games VALUES (127698, 1960900, 'Judero', 'A handmade action/adventure game based on the rich folklore of the Scottish Borders.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1960900/header.jpg?t=1727103724', 0, 0, NULL);
INSERT INTO games VALUES (138756, 1961600, 'Darfall', 'Darfall is a hero-based RPG city-building game that puts you in the role of a hero who must protect their home and help it grow! During the day, grow your hero’s might, find epic loot, master new abilities, and fortify your settlement. At night, survive the hordes of undead, until you triumph.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1961600/header.jpg?t=1747821042', 1, 0, NULL);
INSERT INTO games VALUES (131830, 1962660, 'Call of Duty®: Modern Warfare® II', 'Call of Duty®: Modern Warfare® II drops players into an unprecedented global conflict that features the return of the iconic Operators of Task Force 141.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1962660/header.jpg?t=1710969334', 1, 0, NULL);
INSERT INTO games VALUES (132379, 1962663, 'Call of Duty®: Warzone™', 'Welcome to Call of Duty®: Warzone™, the massive free-to-play combat arena. Experience thrilling modes &amp; new gameplay features in Verdansk and Rebirth Island.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1962663/54bd6a40eb3759aca46966aadd4c4d0d84b2713e/header.jpg?t=1748534520', 1, 1, NULL);
INSERT INTO games VALUES (130933, 1963040, 'The Lost Village', 'Once there was a prosperous village of Martials, now none of it remains. As the son of the former Master, you will lead your followers to rebuild this village. Recruit followers and enter the mysterious illusional domain, acquire lost wonders. Will you see the rebirth of ancestors’ glory again?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1963040/header.jpg?t=1747708126', 0, 0, NULL);
INSERT INTO games VALUES (133311, 1963210, 'VALKYRIE ELYSIUM', 'Long ago, Ragnarok—the End Times—loomed upon the realms. The All-Father Odin, with the last of his strength, created an emissary of redemption, Valkyrie; her sole task being the salvation of a doomed world.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1963210/header.jpg?t=1684724115', 1, 0, NULL);
INSERT INTO games VALUES (129316, 1963370, 'No One Survived', 'This is a multiplayer cooperative open world construction survival sandbox game, where you and your friends must find supplies and build shelters in this world. You have to keep an eye on your character''s needs state at all times, a bad state is likely to lead to death.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1963370/header.jpg?t=1733802692', 1, 0, NULL);
INSERT INTO games VALUES (136187, 1964200, 'Phantom Rose 2 Sapphire', 'Phantom Rose 2 is a roguelike deckbuilding game. Fight and collect powerful cards as Aria, trying to survive in her cherished school that’s being ravaged by evil creatures.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1964200/header.jpg?t=1712779391', 1, 0, NULL);
INSERT INTO games VALUES (138981, 1966720, 'Lethal Company', 'A co-op horror about scavenging at abandoned moons to sell scrap to the Company.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1966720/header.jpg?t=1748737442', 0, 0, NULL);
INSERT INTO games VALUES (130934, 1967430, 'Ghost Trick: Phantom Detective', 'Ghost Trick: Phantom Detective, the classic puzzle-solving mystery adventure directed by Ace Attorney creator Shu Takumi, is back! This long-awaited HD remaster features upgraded visuals and sound and new gallery content.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1967430/header.jpg?t=1727757992', 1, 0, NULL);
