INSERT INTO games VALUES (65728, 2096610, 'Crysis 3 Remastered', 'Experience the single-player experience from the iconic first-person shooter, Crysis 3, optimized to take advantage of today''s hardware in Crysis 3 Remastered.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2096610/header.jpg?t=1709652109', 0, 0, NULL);
