INSERT INTO games VALUES (139372, 2097570, 'StarVaders', 'Pilot a powerful mech to fight off the alien invasion in this ULTIMATE fusion of deckbuilding and grid-based tactics. Discover game-breaking combos, rewind time to alter your fate, and protect the future of humanity in this endlessly replayable roguelike.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2097570/header.jpg?t=1748973257', 1, 0, NULL);
INSERT INTO games VALUES (65643, 2097720, 'Black Market of Bulletphilia  ~ 100th Black Market.', '東方Project第18.5弾。上海アリス幻樂団による弾幕シューティング！ 市場は２種類あった？　魔理沙が闇市場の調査（＆カード蒐集）に大奮闘！ アビリティカードを駆使して遊ぶ、ハイスピードでブラックなシューティング幻想！', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2097720/header.jpg?t=1660460514', 0, 0, NULL);
INSERT INTO games VALUES (65619, 2099080, 'Hidden Cats in London', 'Meow meow! Kittens are hidden in London, let''s find them all. A short and pleasant experience! Start with a Beautiful monochromatic illustration, relax and find all the cats one by one to reveal the final colored art. Play through different modes, find special cats, and unlock bonus levels!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2099080/header.jpg?t=1726415336', 0, 0, NULL);
INSERT INTO games VALUES (137850, 2099110, 'The Classrooms', 'The Classrooms is a procedural, liminal-space, found-footage, survival horror game. Explore The Classrooms and discover the various anomalies it contains; from malicious entities, to harmless oddities. And remember, it''s different every time you play, so your found footage is uniquely yours.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2099110/header.jpg?t=1746726067', 1, 0, NULL);
INSERT INTO games VALUES (65580, 2099220, 'Mobmania', 'Mobmania is a four (4) player co-op real-time bullet-hell action rogue-like where you kill enemies, buy items after leveling up, and survive long enough against thousands of monsters and bosses until the final fight against the Witch.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2099220/header.jpg?t=1715831934', 0, 0, NULL);
INSERT INTO games VALUES (65533, 2100150, 'Shadow of the Depth', 'Shadow of the Depth is a top-down action Roguelite game. Delve into a dungeon world of light and shadow to eradicate the monsters that ravage your home. Be prepared to step into the abyss before you!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2100150/header.jpg?t=1745462937', 1, 0, NULL);
