INSERT INTO games VALUES (65495, 2101250, 'Nebula', 'Survive in the deep void of the galaxy against thousands of invaders! Nebula is a challenging bullet hell, twin stick shooter where you have to face endless waves of space enemies. Additional map resources and space drones can provide you a support but be wary, they can as well become a deadly trap.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2101250/header.jpg?t=1732296235', 0, 0, NULL);
