INSERT INTO games VALUES (11651, 2289390, 'Crab God', 'Crab God is an atmospheric underwater strategy game. Guide your Crabling colony through wild ocean depths, and defend the egg of the next Crab God.Restore and protect diverse coral reefs, making a difference in the real world as you progress in-game. Make waves, praise the claw!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2289390/header.jpg?t=1742312800', 1, 0, NULL);
INSERT INTO games VALUES (11664, 2289650, 'Mini Airways - ATC simulator', 'Mini Airways is a real-time management game where you play the role of an air traffic controller. Clear your aircraft to takeoff &amp; land, direct them to the destination...and most of all don''t let them crash!! London, Tokyo, Shanghai... Test your ATC skills in distinctive maps around the globe!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2289650/749b34d69dfb32b31cf848b647cc8537bb82fc73/header.jpg?t=1745810237', 1, 0, NULL);
INSERT INTO games VALUES (11614, 2290180, 'Riders Republic', 'Jump into a massive multiplayer playground! Bike, ski, snowboard, or wingsuit across an open world sports paradise.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2290180/header.jpg?t=1747653963', 1, 0, NULL);
INSERT INTO games VALUES (11604, 2291020, 'ANONYMOUS;CODE', 'Hack Into God', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2291020/header.jpg?t=1715703521', 0, 0, NULL);
INSERT INTO games VALUES (11605, 2291060, 'EARTH DEFENSE FORCE 6', 'Live the future of despair.The year is 2024 AD. The survivors fought against the remaining threats while trying their best to continue their recovery.Three years passed in the year 2027. In a new world without hope, the time has come to once again resist the fate of the Earth.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2291060/header.jpg?t=1737512603', 1, 0, NULL);
