INSERT INTO games VALUES (69417, 2291760, 'Papa''s Freezeria Deluxe', 'Return to Calypso Island to serve seasonal sundae treats in Papa''s Freezeria Deluxe! Craft sundaes in the Freezeria for all your quirky customers while earning tips, points and Special Recipes. Switch gears and take a trip in the Food Truck to concoct your own chilly creations and see who shows up!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2291760/header.jpg?t=1700157490', 0, 0, NULL);
INSERT INTO games VALUES (11571, 2291850, 'Underground Blossom', 'Underground Blossom is a new adventure game by Rusty Lake. Fulfil various tasks at every station to find the metro that will take you through each important event from Laura Vanderboom''s life.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2291850/header.jpg?t=1713632188', 1, 0, NULL);
INSERT INTO games VALUES (11581, 2292060, 'Spell Disk', 'Build unique synergy spell combos to destroy the hordes of monsters and bosses in this rogue-lite action game.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2292060/header.jpg?t=1744224039', 1, 0, NULL);
INSERT INTO games VALUES (11550, 2292260, 'STAR WARS™: Dark Forces Remaster', 'The evil Empire is currently creating a doomsday army behind a veil of secrecy. However, they are no match for the Rebel Alliance''s covert operations division. Your mission is to infiltrate the Empire and put an end to their plans for terror and domination.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2292260/header.jpg?t=1748544233', 0, 0, NULL);
INSERT INTO games VALUES (11518, 2292650, 'Escape From Mystwood Mansion', 'In this first-person puzzle escape room game, you are trapped in the mysterious Mystwood mansion. Explore the mansion and find hidden compartments while solving puzzles and deciphering codes to find a way out. Will you escape or linger to uncover the mansion''s final secret?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2292650/header.jpg?t=1748507520', 0, 0, NULL);
INSERT INTO games VALUES (136705, 2292800, 'Blacksmith Master', 'Manage your own medieval smithy in Blacksmith Master and supervise the entire process from mining ores and gems to designing and selling finished products. Forge everything from weapons and armor to tools and cooking utensils to fund your craft and become the Blacksmith Master.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2292800/a4e8efa3d8a738c3011f6b50dd57475a7ba2c782/header.jpg?t=1749477920', 1, 0, NULL);
INSERT INTO games VALUES (11469, 2293680, 'Crestfallen: Medieval Survival', '👑 Hail to the King! In Crestfallen: Medieval Survival, players clash for dominance over the realm through strategic castle 🏰 building and fierce combat. Craft epic armor, forge deadly medieval weapons⚔️, and build a kingdom worthy of legend 📜. Create a Guild 🐉, trade goods, and prevail! 🌟', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2293680/header.jpg?t=1733080069', 0, 0, NULL);
