INSERT INTO games VALUES (11446, 2294660, 'The Quinfall', 'Embark on an adventurous journey to explore the Quinfall universe. Be a part of unique battles and an immersive story with dozens of different professions in the depths of medieval times in an all-new MMORPG experience.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2294660/f409bf38047232c0c9c21813d359c0e2667a580e/header.jpg?t=1740799193', 1, 0, NULL);
INSERT INTO games VALUES (139369, 2294730, 'MILFs of Sunville - Season 2', 'MILFs of Sunville is an adult game about a young guy forced to leave his luxurious life in a big city behind and return to a college in a small town of Sunville. This is a VN, filled with beautiful girls, romance, moral choices mixed with quality graphics and hot close-up animations.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2294730/1efd9b6f8c9fc60a9012694157d3366f8070d113/header.jpg?t=1749456917', 0, 0, NULL);
