INSERT INTO games VALUES (11388, 2296380, 'I Expect You To Die 3: Cog in the Machine', 'Outwit your most cunning adversary to date in the latest installment of this popular, spy-themed VR puzzle series. Wield new gadgets, visit action-packed locales, and wear custom disguises as you dive back into the world of espionage in this escape room game.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2296380/header.jpg?t=1724689495', 1, 0, NULL);
