INSERT INTO games VALUES (69103, 2299900, 'Felvidek', 'In Felvidek, a JRPG set in 15th century Slovakia, you embrace the role of an alcoholic knight Pavol. Meet diverse and interesting characters to help you drive out the Hussites and Ottomans who blight this land.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2299900/header.jpg?t=1748904703', 0, 0, NULL);
