INSERT INTO games VALUES (11256, 2300300, 'Growth', 'Growth is a cozy, hexagonal-grid based soft-strategy game. Explore and populate a procedurally generated world by utilizing unique abilities of animals. Growth blends the beauty of cozy exploration with challenging navigation around obstacles.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2300300/header.jpg?t=1736266234', 1, 0, NULL);
