INSERT INTO games VALUES (11172, 2302140, 'q.u.q.', 'q.u.q. is a surreal visual novel about a somewhat crude girl that wanders a desert.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2302140/header.jpg?t=1732673098', 1, 0, NULL);
