INSERT INTO games VALUES (11078, 2304440, 'Creatures of Ava', 'Let your empathy guide you as you play an exciting action-adventure, creature-saver game. Understand and tame the creatures of Ava and let them lead you through a variety of ecosystems – all in the hopes of saving the planet from a life-consuming infection.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2304440/header.jpg?t=1737382876', 0, 0, NULL);
