INSERT INTO games VALUES (68874, 2305840, 'Cat Quest III', 'In Cat Quest III you play as a purrivateer in a freely explorable 2.5D open-world swarming with Pi-rats. You can sail the seas in your ship for treasures galore! But prepare for peril, as the Pirate King aims to hunt you down...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2305840/f7da72faf8053958400677c4411b15816e78460c/header.jpg?t=1749029403', 1, 0, NULL);
