INSERT INTO games VALUES (10780, 2311990, 'Rack and Slay', 'The rogue-like dungeon crawler where you''re a billiard ball! Push monster balls into holes or traps in randomly generated levels. Stack up countless game-changing items to create broken builds. Find combos to create your own synergies and customize your playstyle. Rack and Slay!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2311990/header.jpg?t=1746347932', 0, 0, NULL);
