INSERT INTO games VALUES (68503, 2315020, 'Froguelike', 'Your choices matter in Froguelike where you play as a frog on a mission to eat all the bugs. Level up, choose new tongues and upgrades, become unstoppable and run straight into the swarm! Unlock all frogs, tongues, items and chapters to become the most powerful frog in the pond.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2315020/header.jpg?t=1745413411', 0, 0, NULL);
