INSERT INTO games VALUES (128842, 2362420, 'Mass Effect 2 (2010) Edition', 'Are you prepared to lose everything to save the galaxy? You''ll need to be, Commander Shepard. It''s time to bring together your greatest allies and recruit the galaxy''s fighting elite to continue the resistance against the invading Reapers.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2362420/header.jpg?t=1708017054', 0, 0, NULL);
INSERT INTO games VALUES (132789, 2366980, 'Thank Goodness You''re Here!', 'Thank Goodness You''re Here! is an absurd comedy slapformer set in the bizarre Northern English town of Barnsworth. As a traveling salesman, take the time to see the sights and meet the locals, who are very eager to give you a series of increasingly odd jobs…', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2366980/header.jpg?t=1733154706', 1, 0, NULL);
INSERT INTO games VALUES (136655, 2368300, 'Warside', 'Welcome to Warside, the fast-paced turn-based tactics game. With a single-player story campaign, multiplayer support, and a built-in map editor, the fight for victory never ends. Choose your Commander, assemble your forces, and battle your way to victory.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2368300/d3ca48b32d06d648a009f1ba8ac458410ae7f124/header.jpg?t=1748977355', 1, 0, NULL);
INSERT INTO games VALUES (137293, 2375780, 'Beam Eye Tracker', 'Turn your webcam into an AI-powered head &amp; eye tracker and ditch the bulky tracking hardware. Enable gaming extensions like OpenTrack for immersive eye and head tracking. Gain insights and improve your gameplay using the eye tracking overlay or enhance your live streams.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2375780/header.jpg?t=1744846008', 1, 0, NULL);
INSERT INTO games VALUES (137876, 2379910, 'Dystopika', 'A city-building sandbox for futuristic cities. No goals, no management, just creativity and dark cozy vibes.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2379910/header.jpg?t=1746528667', 1, 0, NULL);
INSERT INTO games VALUES (135314, 2382520, 'Erenshor', 'Erenshor is a single player nod to the MMORPGs of the past. Partner up with our signature &quot;Simulated Players&quot; to experience all of the joys of open-world MMORPG gameplay on your own schedule and without the time commitments. There are thousands of items, quests, raids, and secrets to discover!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2382520/header.jpg?t=1748833173', 0, 0, NULL);
INSERT INTO games VALUES (129858, 2383990, 'Ghostbusters: Spirits Unleashed Ecto Edition', 'This is an asymmetrical game of hide and seek. In true form to IllFonic’s past titles, this title is a 4v1 setup where players will either play as part of a team of new Ghostbusters or a singular Ghost.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2383990/header.jpg?t=1749079792', 1, 0, NULL);
INSERT INTO games VALUES (139846, 2385530, 'PGA TOUR 2K25', 'Take your best shot at glory in PGA TOUR 2K25! In a 2K-first, compete in three prestigious major tournaments. Personalize your game with expanded MyCAREER, MyPLAYER and Course Designer options. Challenge friends across ranked, casual, and cross-platform multiplayer.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2385530/header.jpg?t=1747234543', 1, 0, NULL);
INSERT INTO games VALUES (133073, 2387380, 'Bare Witness', 'Bare Witness is an adult visual novel set at the fictional Plattsburgh College of the Arts in New York. With lots of potential branching paths and 11 primary endings, you may find yourself returning again and again to pursue one or more of the six love interests that catch your eye.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2387380/header.jpg?t=1747812890', 0, 0, NULL);
INSERT INTO games VALUES (129736, 2389040, 'ShapeHero Factory', 'ShapeHero Factory is a game that fuses the factory simulation, roguelite, and tower defense genres. Use different shape combinations to mass-produce a variety of heroes, who will then fight all on their own. All you need to worry about is building the optimal factory to manufacture them.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2389040/59cb8dd40fc57435ce2aec87b6147532241eee2a/header.jpg?t=1749718599', 1, 0, NULL);
INSERT INTO games VALUES (99696, 2390230, 'The Chef''s Shift', 'The Chef’s Shift is a fast-paced typing game in a restaurant setting, where you’ll both cook &amp; serve food to hungry customers, all done by TYPING.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2390230/header.jpg?t=1749118142', 0, 0, NULL);
INSERT INTO games VALUES (99697, 2390260, 'Topple Tactics', 'Topple Tactics is a physics-based multiplayer tower defense game where one huge player controls the map by placing towers and using abilities, whilst the little players level up their stats and equipment to reach the end of the map and defeat the huge player!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2390260/header.jpg?t=1729731143', 0, 0, NULL);
INSERT INTO games VALUES (99645, 2391870, 'MareQuest: An Interactive Tail', 'A terrible darkness threatens a world of overwhelmingly adorable mares. Can a new cute mare with amnesia save the world or will she lose more than her memories along the way?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2391870/header.jpg?t=1694750193', 0, 0, NULL);
INSERT INTO games VALUES (99646, 2391900, 'Champion Shift', 'Unleash mighty Champions in this thrilling co-op bullet heaven. Shift into battle, create builds with unique abilities, and battle endless enemies to stop the Dominion''s path of conquest. Rev through high octane missions, conquer epic bosses, and become an absolute legend!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2391900/header.jpg?t=1725673028', 0, 0, NULL);
INSERT INTO games VALUES (99625, 2392230, 'The Groom of Gallagher Mansion', 'Hunt down a beheaded ghost to save your college club from losing funding! It''ll be a piece of cake— wait, what do you mean he wants to marry you!? The Groom of Gallagher Mansion is spooky comedic romantic visual novel full of laughs and scares all around!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2392230/header.jpg?t=1741049182', 0, 0, NULL);
INSERT INTO games VALUES (99626, 2392280, 'TDS - Tower Defense Strategy', 'TOWER ▪ DEFENSE ▪ STRATEGY. Control Vessels. Utilize their uniquely deep set of towers. Create an everchanging defense. Play with friends. Protect your Basin at all costs. An absolute Tower Defense, Real-Time Strategy Hybrid', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2392280/d8d6368fd41aa54781ff592651f256118cd7a7c6/header.jpg?t=1748238456', 1, 0, NULL);
INSERT INTO games VALUES (99602, 2392520, 'Power & Revolution 2023 Edition', 'The latest edition of the ultrarealistic world simulator where you play as the Head of State or as the opposition! New Additions: dive deeper into the war in the Ukraine with artillery, trenches, mines, troop morale, etc; detailed immigration management; the justice system; and children.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2392520/header.jpg?t=1697805035', 0, 0, NULL);
INSERT INTO games VALUES (99592, 2393160, 'Nice Day for Fishing', 'The world needs you Adventurer! Embark on an RPG pixel adventure where you’ll play as Baelin the humble fisherman, who must rise-up to become the hero of Honeywood. Battle fish with precision timing and magic spells, upgrade your abilities, defeat evil and rebuild Honeywood.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2393160/header.jpg?t=1748534969', 0, 0, NULL);
INSERT INTO games VALUES (99575, 2393770, 'Bang Average Football', 'Experience the thrill of the beautiful game in Bang Average Football - the fast-paced, addictive, easy-to-learn football game for 1-4 players! Play against your friends for footballing glory in multiplayer, or turn a hopeless club into national champions as player-manager in Story mode!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2393770/header.jpg?t=1727562809', 0, 0, NULL);
INSERT INTO games VALUES (99538, 2394650, 'Crypt Custodian', 'Crypt Custodian is a charming metroidvania about cleaning up the afterlife. Play as Pluto - a mischievous cat who has died, and is sentenced to be the afterworld''s janitor... FOREVER! Hang out with other doomed ghosts, battle beasts, and explore a vastly expansive landscape.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2394650/header.jpg?t=1733682818', 1, 0, NULL);
INSERT INTO games VALUES (99524, 2395210, 'Tony Hawk''s™ Pro Skater™ 1 + 2', 'Play the fully-remastered Tony Hawk’s™ Pro Skater™ &amp; Tony Hawk’s™ Pro Skater™ 2 games in one epic collection, rebuilt from the ground up in incredible HD.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2395210/header.jpg?t=1739565029', 0, 0, NULL);
