INSERT INTO games VALUES (99442, 2396980, 'Fate/stay night REMASTERED', 'Seek the root of the Fate franchise. Return to where it all began.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2396980/header.jpg?t=1726036301', 0, 0, NULL);
