INSERT INTO games VALUES (99334, 2399160, 'Soulash 2', 'Soulash 2 is a sandbox RPG roguelike with a procedurally generated open world, simulated history, skill-based progression system, customizable abilities, material-based crafting, building, trading, and the possibility of total mayhem. Will you save your world or destroy it?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2399160/96980dc8ca1c241f2c798860efbd6ddf80939476/header_alt_assets_1.jpg?t=1747404909', 0, 0, NULL);
