INSERT INTO games VALUES (99308, 2399420, 'Le Mans Ultimate', 'Le Mans is a continually evolving story... powered by emotion, speed and glory. Le Mans Ultimate - the official game of the FIA World Endurance Championship and 24 Hours of Le Mans.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2399420/header.jpg?t=1749552077', 0, 0, NULL);
INSERT INTO games VALUES (72136, 2399730, 'FRONT MISSION 1st: Remake', 'FRONT MISSION 1st: Remake is an immersive, tactical turn-based RPG, placing you in command of the awe-inspiring Wanzers – powerful military machines.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2399730/header.jpg?t=1728550756', 0, 0, NULL);
INSERT INTO games VALUES (99323, 2399830, 'ARK: Survival Ascended', 'ARK is reimagined from the ground-up into the next-generation of video game technology with Unreal Engine 5! Form a tribe, tame &amp; breed hundreds of unique dinosaurs and primeval creatures, explore, craft, build, and fight your way to the top of the food-chain. Your new world awaits!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2399830/header.jpg?t=1744843097', 1, 0, NULL);
