INSERT INTO games VALUES (72125, 2400340, 'Touhou Juuouen 〜 Unfinished Dream of All Living Ghost.', '東方Project第19弾は、対戦型弾幕シューティング！ ダークで元気いっぱいで、ちょっぴり可愛い妖獣たちの狂宴をお楽しみに。', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2400340/header.jpg?t=1691917973', 0, 0, NULL);
INSERT INTO games VALUES (99277, 2400430, 'Capcom Fighting Collection 2', 'Capcom''s new fighting collection hits the stage! Choose from fan-favorite games like Capcom vs. SNK 2: Mark of the Millennium 2001 and Project Justice to 3D action games like Power Stone and Power Stone 2 in this collection of eight classic fighting games!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2400430/header.jpg?t=1747369054', 1, 0, NULL);
INSERT INTO games VALUES (72101, 2400510, 'Dungeons & Degenerate Gamblers', 'Battle your way through a seedy tavern filled with gambling addicted townspeople in this Blackjack Roguelike Adventure. From aces and face cards to tarot cards, business cards and more, create your unique deck to beat the house.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2400510/header.jpg?t=1745381624', 0, 0, NULL);
INSERT INTO games VALUES (72105, 2400640, 'NanoApostle', 'NanoApostle is a dark sci-fi boss rush action game featuring intense reaction-based combat and the unique &quot;Destruction Point&quot; system. Play as Anita, a child augmented with lethal nanomachines, as she battles against twisted cybernetic experiments to escape a top-secret facility.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2400640/header.jpg?t=1741939067', 1, 0, NULL);
