INSERT INTO games VALUES (72117, 2400880, 'Haunted Investigation', 'Haunted Investigation is a spine-tingling horror game that will test your nerves and keep you on the edge of your seat. Whether you choose to play alone or with another friend (up to 2 players), you''ll be immersed in a world of terror and suspense as you explore an abandoned mansion.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2400880/header.jpg?t=1747945835', 0, 0, NULL);
INSERT INTO games VALUES (72091, 2401230, 'Clone Drone in the Hyperdome', 'Cut robots apart in VR. Feel your sword disintegrate their metal bodies. Now you live and die in the Crashloop, a roguelike tournament to the death. Lock swords! Shoot shurikens from your wrist! This is CLONE DRONE... in the HYPERDOME!!!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2401230/header.jpg?t=1743425655', 0, 0, NULL);
INSERT INTO games VALUES (99247, 2401410, 'Cabernet', 'Cabernet is a 2D narrative RPG set in a 19th century Eastern European inspired world, with a modern twist. Guide Liza, a young vampire in her new unlife among the unsuspecting townsfolk. Will you retain your humanity or descend further into the horror you have become?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2401410/header.jpg?t=1748618633', 0, 0, NULL);
INSERT INTO games VALUES (99234, 2401970, 'Ace Attorney Investigations Collection', 'Miles Edgeworth''s dramatic turnabouts take center stage! Experience both Ace Attorney Investigations games in one gorgeous collection! Investigate crime scenes and solve tough, intriguing cases through logic and deduction. When Edgeworth''s past and present collide, his future begins!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2401970/header.jpg?t=1747359314', 1, 0, NULL);
INSERT INTO games VALUES (99208, 2402280, 'Werewolf: The Apocalypse — The Book of Hungry Names', 'Save the living earth with Rage and spirit! Can your shattered werewolf pack defeat a Wyrm Spirit that manifests as a lie that you want to believe?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2402280/header.jpg?t=1744307125', 0, 0, NULL);
