INSERT INTO games VALUES (99098, 2404880, 'Car Dealer Simulator', 'Uncover a goldmine in the used car market! Sniff out deals, buy low, modify, and sell high. Your journey from amateur grease monkey to car dealer magnate awaits. How fast will you rise in this lucrative venture?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2404880/77ad6970ce80e055eaa65153f5b78ec863805c49/header.jpg?t=1749646208', 1, 0, NULL);
INSERT INTO games VALUES (99108, 2405060, 'KIBORG', 'KIBORG is a relentless rogue-lite beat’em up where you enhance your body with new cybernetic implants each run. You’ve been sent to the worst prison in the galaxy for crimes you didn’t commit. Death won’t provide an escape, but a violent reality show may offer a way out.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2405060/16f43836785f5ae5fba0c0859a9b21e54b6d50f9/header.jpg?t=1747765621', 1, 0, NULL);
INSERT INTO games VALUES (99066, 2406180, 'Knights Within', 'Knights Within is a hack&amp;slash horde shooter with roguelite elements. Design custom loadouts, navigate procedurally generated levels and utilize random power-ups. Either solo or with friends, can you survive endless waves of enemies to ensure humanity''s survival?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2406180/header.jpg?t=1749574242', 0, 0, NULL);
INSERT INTO games VALUES (99006, 2406770, 'Bodycam', 'Bodycam is the first ultra-realistic multiplayer, first-person shooter game made using the latest technologies of the next-gen game engine Unreal Engine 5. Get ready to dive into fast-paced Bodycam actions, where every bullet counts and every choice can decide over the victory or loss of your team.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2406770/9100175e3c279f604e3b32e9b4979c1226d837c4/header.jpg?t=1747489582', 1, 0, NULL);
