INSERT INTO games VALUES (98940, 2408820, 'Luma Island', 'Travel to Luma Island to go on an epic adventure by yourself or with your friends and family. Build your dream farm, master professions, collect magical Lumas, find treasures and unravel the mysteries of the island.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2408820/header.jpg?t=1737540641', 1, 0, NULL);
INSERT INTO games VALUES (71767, 2409110, 'REAL WEB LEGENDS: Carter''s Quest', 'Fight, solve puzzles, and learn the secrets of Homunculi in this character-action RPG experience. Create and customize your own Homunculus, develop new techniques and combos with an array of weapons, and fight to end a centuries-long conflict.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2409110/header.jpg?t=1732125401', 0, 0, NULL);
INSERT INTO games VALUES (98925, 2409360, 'Pixel Cafe', 'Step into Pixel''s shoes in this one-of-a-kind journey that bridges time, memories, and the aroma of fresh coffee. Dive deep into a city balancing its past and future. Engage in intense arcade challenges, immerse yourself in heartfelt stories, and navigate a world crafted in pixel art.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2409360/header.jpg?t=1732964339', 0, 0, NULL);
INSERT INTO games VALUES (98902, 2409780, 'Breeze of Passion', 'Breeze of Passion is an adult game about a young guy who moves to a small seaside town to help with the family business. This VN is full of beautiful girls, hot MILFs, and unexpected plot twists, along with high-quality graphics and hot animation', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2409780/header.jpg?t=1749486130', 0, 0, NULL);
INSERT INTO games VALUES (98879, 2410170, 'The Nameless: Slay Dragon', 'The Nameless: Slay Dragon is a gamebook-adventure flavored turn-based RPG In short - how to slay the immensely powerful and cunning evil dragon? You will play as a young man having a bloody feud with a dragon, and face powerful, sinister and tricky enemies with friends....', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2410170/header.jpg?t=1748560267', 1, 0, NULL);
INSERT INTO games VALUES (71617, 2412490, 'Abandoned Souls', 'Abandoned Souls is a horror game, shown through a GoPro lens. You play as a vlogger who specializes in urban exploration.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2412490/header.jpg?t=1689326294', 0, 0, NULL);
INSERT INTO games VALUES (71603, 2413050, 'Retrowave World', 'Neon lights, palm trees, synthwave, chrome robot women, speeding 80s supercars... Welcome to Retrowave World!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2413050/header.jpg?t=1730991435', 1, 0, NULL);
INSERT INTO games VALUES (98664, 2414270, 'Sunderfolk', 'Sunderfolk is a shared turn-based tactical RPG adventure where your phone becomes the controller. Inspired by gathering around a table with friends, it is built with a couch co-op experience in mind. Up to four players adventure across the magical and dangerous Sunderlands.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2414270/header.jpg?t=1748999832', 0, 0, NULL);
