INSERT INTO games VALUES (97241, 2445990, 'Bloomtown: A Different Story', 'Bloomtown: A Different Story is a narrative JRPG mixing turn-based combat, monster taming and social RPG set in a seemingly pleasant 1960s Americana world. Join Emily and her group of friends to save their cozy town from the demonic creatures that live in the hearts of its residents!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2445990/header.jpg?t=1744099999', 1, 0, NULL);
INSERT INTO games VALUES (97226, 2446550, 'STAR WARS™: Battlefront Classic Collection', 'Play the classic STAR WARS™ Battlefront games, online and offline in this definitive collection.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2446550/header.jpg?t=1715189030', 0, 0, NULL);
INSERT INTO games VALUES (97230, 2446600, 'Dark Deity 2', 'Verroa is a peaceful continent on the brink of war as the Asverellian Empire seeks to expand - at your homeland’s expense. Command unlikely heroes, fight challenging turn-based battles, and watch hardship forge iron into steel. Dark Deity is back, bigger and better than before!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2446600/ba631fcd21217bba16e7f043f57d3e34d4ed2235/header.jpg?t=1744268945', 0, 0, NULL);
INSERT INTO games VALUES (97233, 2446680, 'Drive Me to Hell', 'As the night darkens and you set out for home, an unsettling occurrence takes place on the road. Will this lead you to hell? Unveil the truth in a bone-chilling driving horror game that will keep you on the edge of your seat!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2446680/header.jpg?t=1738070680', 0, 0, NULL);
INSERT INTO games VALUES (97134, 2448930, 'Starstruck Vagabond', 'A space captain accidentally freezes themselves for two thousand years, finding themselves in an unfamiliar galaxy. Fortunately, there''s always someone who needs cargo delivered.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2448930/header.jpg?t=1720105234', 0, 0, NULL);
INSERT INTO games VALUES (97138, 2449040, 'Cursorblade', 'Cursorblade is a bullet hell game where you play as the cursor, fighting your way through waves of enemies. Combine weapons and items to become more powerful with your own unique builds. Slash, dodge, upgrade, and repeat!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2449040/header.jpg?t=1738837476', 0, 0, NULL);
INSERT INTO games VALUES (97119, 2449430, 'Incremental Factory', 'Craft and automate an industrial empire from scratch! Experience a strategic game teeming with challenges as you manage resources, overcome hurdles, and optimize production chains. Are you ready to conquer the challenges of Incremental Factory? Your journey starts here... The Factory Must Grow!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2449430/header.jpg?t=1725333080', 0, 0, NULL);
INSERT INTO games VALUES (97065, 2450120, 'Naughty College 18+', 'Welcome to the world of Naughty College 18+ - an immersive visual novel for adults. In this game, you will witness the unique story of a young university professor who unintentionally becomes not only a mentor but also the object of passionate love for three seductive students.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2450120/header.jpg?t=1743600145', 1, 0, NULL);
INSERT INTO games VALUES (97066, 2450130, 'Sex Hotel Simulator 🏩', 'Welcome to the captivating world of &quot;Sex Hotel Simulator,&quot; where you''ll take on the role of a brothel owner and elevate it to the pinnacle of fame and success!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2450130/header.jpg?t=1743600656', 1, 0, NULL);
INSERT INTO games VALUES (97077, 2450400, 'Trash of the Titans', 'It''s turn-based fantasy tactics with trash animals. Defend your trash from invading rats, and eat your trash to upgrade your team. Think your way out of ruin by using the shape of each level to your advantage. Be creative, and try to not die.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2450400/header.jpg?t=1725728484', 0, 0, NULL);
INSERT INTO games VALUES (97081, 2450450, 'MEGATON MUSASHI W: WIRED', 'Launch a counteroffensive to take back the Earth from alien invaders in this mecha action RPG.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2450450/header.jpg?t=1732696320', 0, 0, NULL);
INSERT INTO games VALUES (97052, 2450700, 'Drug Lord Tycoon', 'Start from nothing and rise to the top as you expand your criminal empire in Drug Lord Tycoon.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2450700/header.jpg?t=1722431262', 0, 0, NULL);
INSERT INTO games VALUES (97056, 2450820, 'Radiant Silvergun', 'Set on the earth and in space on July 14, 2520 A.D., the film explores the mystery of mankind''s extinction. Various terrains become battlefields. Enemies attack from all directions. There are 23 bosses in total. Aim for a high score by making full use of score bonuses and level-up weapons!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2450820/header.jpg?t=1705276203', 0, 0, NULL);
INSERT INTO games VALUES (96965, 2452920, 'Ouros', 'Ouros is a calming puzzle game about forming beautiful curves in a serene space. Find your flow as you nudge, bend, and stretch curves into pleasing shapes, and discover the inherent mathematical beauty of Ouros.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2452920/header.jpg?t=1718394528', 1, 0, NULL);
INSERT INTO games VALUES (96968, 2453060, 'Dreamcore', 'Step into the surreal with Dreamcore, a body-cam styled psychological horror game that plunges you into the eerie beauty of &quot;liminal spaces.&quot; Unravel the mysteries of Dreamcore’s non-linear worlds and uncover its hidden secrets. Can you discover what lies beyond the edge of reality?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2453060/d2ba50499857c673c06038ffa2c77114cfcd9956/header_alt_assets_1.jpg?t=1749321784', 0, 0, NULL);
INSERT INTO games VALUES (96873, 2454570, 'Race of Life - Act 1', 'Race of Life is an adult visual novel. You play as Jake Miller, a divorced Professor who has taken up teaching after his past mistakes cost him his lucrative job and his marriage. When tragedy strikes, Jake must use every ounce of skill, smarts and ruthlessness to save the one he loves the most.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2454570/header.jpg?t=1748594798', 0, 0, NULL);
INSERT INTO games VALUES (96883, 2454890, 'DEATH IN UNISON', 'Survive the world''s deadliest psychopaths. Experience a unique 2-player co-op experience that puts your teamwork and communication to the test. Complete your duties alone or with a partner in a prison like no other.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2454890/header.jpg?t=1727572986', 0, 0, NULL);
INSERT INTO games VALUES (96824, 2455640, 'Romancing SaGa 2: Revenge of the Seven', 'In this non-linear RPG, rule and expand the Empire of Varennes across multiple generations. Discover a vast array of story experiences as you fight the Seven Heroes in an epic battle that plays out over thousands of years.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2455640/header.jpg?t=1744796260', 1, 0, NULL);
INSERT INTO games VALUES (96840, 2455920, 'Mimic Logic', '&quot;Mimic Logic&quot; is an automatically generated logic puzzle roguelike. Listen to the statements of the treasure chests, find the lying mimics, and open the rest of the treasure chests! Opening a mimic results in a game over.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2455920/header.jpg?t=1717805799', 0, 0, NULL);
INSERT INTO games VALUES (96816, 2456350, 'The Scourge | Tai Ương', 'The Scourge game tells stories revolving around urban legends from the 1990s in Saigon, Vietnam. The male protagonist is trapped by past sins caused by his and his family''s mistakes. Now, he must confront and overcome the consequences to find a path to redemption, and you are him.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2456350/header.jpg?t=1730176325', 0, 0, NULL);
INSERT INTO games VALUES (96785, 2456740, 'inZOI', '&quot;Every life becomes a story&quot; Create your unique story by controlling and observing the lives of ''Zois''. Customize characters and build houses using inZOI''s easy-to-use tools to live the life of your dreams and experience the different emotions of life created by its deep and detailed simulation.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2456740/89acee5c3d965af802002617d6c130e5e03bd240/header.jpg?t=1749740105', 1, 0, NULL);
INSERT INTO games VALUES (96791, 2456960, 'The 7th Guest VR', 'The iconic supernatural mystery, The 7th Guest, has been brought back to life with cutting-edge VR technology, that delivers an atmospheric story like no other. Explore the foreboding mansion, solve challenging puzzles, and uncover its dark secrets.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2456960/header.jpg?t=1725374672', 1, 0, NULL);
INSERT INTO games VALUES (96768, 2457220, 'Avowed', 'Avowed is a first-person fantasy RPG set in the world of Eora, where your choices carve a path through war, intrigue, and ancient mysteries. Navigate a land in turmoil, forge powerful alliances or deadly rivalries, and wield magic and steel to shape the fate of the Living Lands—and your own destiny.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2457220/header.jpg?t=1744647242', 0, 0, NULL);
INSERT INTO games VALUES (96740, 2457540, 'Cardfight!! Vanguard Dear Days 2', '&quot;Cardfight!! Vanguard,&quot; has newly come to digital game! Over 3,000 cards for the Standard format! A brand-new original story shares the world of anime series unfolds! Enjoy your own cardfight experience!!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2457540/header.jpg?t=1738198582', 0, 0, NULL);
INSERT INTO games VALUES (96726, 2458210, 'Tamer Vale', 'Tamer Vale is a turn based card battler, where a collective of Elven heroines, known as Tamers, journey forth beyond the safety of their hidden valley to find and confront the sources of corruption in the land, and bring balance to it using their special rituals!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2458210/header.jpg?t=1737698265', 0, 0, NULL);
