INSERT INTO games VALUES (96671, 2459550, 'Emberward', 'Build twisting mazes with tetromino blocks and deploy unique towers in this engaging roguelite tower defense game!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2459550/header.jpg?t=1748348376', 0, 0, NULL);
INSERT INTO games VALUES (96675, 2459750, 'Yohane the Parhelion - NUMAZU in the MIRAGE -', 'Yohane the Parhelion is an official spin-off of &quot;Love Live! Sunshine&quot;. 『Yohane the Parhelion - NUMAZU in the MIRAGE -』 is a deckbuilding roguelite set in that world! A mysterious mirror world that changes each time it''s entered. After countless choices, Yohane chooses...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2459750/header.jpg?t=1747963176', 0, 0, NULL);
