INSERT INTO games VALUES (130831, 2461850, 'Senua’s Saga: Hellblade II', 'The sequel to the award winning Hellblade: Senua’s Sacrifice, Senua returns in a brutal journey of survival through the myth and torment of Viking Iceland. Intent on saving those who have fallen victim to the horrors of tyranny, Senua faces a battle of overcoming the darkness within and without.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2461850/header.jpg?t=1741278194', 1, 0, NULL);
