INSERT INTO games VALUES (96252, 2470300, 'Hookah Haze', 'It''s the year 2xxx. The inexperienced Toru Sumiki lands a job managing Hookah Haze, a new hookah lounge on the outskirts of Akihabara, where they meet three eccentric girls. The story unfolds as the girls gradually open up to them, connecting through their fondness for hookah...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2470300/header.jpg?t=1734650873', 0, 0, NULL);
INSERT INTO games VALUES (96091, 2473480, 'Tails of Iron 2: Whiskers of Winter', 'Embark upon a vast, snow-ravaged kingdom in Tails of Iron 2, sequel to the critically acclaimed action-RPG. As Arlo, heir to the Warden of the Wastes, adventure through harsh northern lands, home to giant beasts and ragtag bandits, in an epic quest to overcome an ancient, blood-starved evil.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2473480/header.jpg?t=1738133334', 1, 0, NULL);
INSERT INTO games VALUES (96102, 2473710, 'Abyss School', 'Solve hidden items and puzzles while avoiding abyssal zombies and traps at school.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2473710/header.jpg?t=1716817087', 1, 0, NULL);
INSERT INTO games VALUES (96072, 2473890, 'DDinosaur with Double D''s', 'DDinosaur has felt alone for millions of years now... Will she be able to find love without revealing her biggest secret? That she''s a Dinosaur...with double D''s.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2473890/header.jpg?t=1742335789', 0, 0, NULL);
