INSERT INTO games VALUES (96023, 2475490, 'Mouthwashing', 'The five crew members of the Tulpar are stranded in the empty reaches of space, shrouded in perpetual sunset. God is not watching.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2475490/header.jpg?t=1745685014', 1, 0, NULL);
