INSERT INTO games VALUES (95921, 2477090, 'Mosa Lina', 'a hostile interpretation of the immersive sim, where nothing is planned, and everything works', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2477090/header.jpg?t=1748648390', 1, 0, NULL);
INSERT INTO games VALUES (95925, 2477140, 'Twilight Town: A Cyberpunk FPS', 'Twilight Town: A Cyberpunk FPS is a brutal, funny, bloody FPS game with an advanced gore system. Featuring 15 beautiful levels, a variety of weapons and a deeply engaging story that follows the journey of a young man and his friend tackling on a criminal underground to give his AI wife a real body.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2477140/header.jpg?t=1712868045', 0, 0, NULL);
