INSERT INTO games VALUES (95870, 2478970, 'Tomb Raider I-III Remastered Starring Lara Croft', 'Play the original three Tomb Raider adventures with all expansions and secret levels in this definitive collection.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2478970/header.jpg?t=1711475398', 0, 0, NULL);
INSERT INTO games VALUES (95836, 2479290, 'Computer Repair Shop', 'Become a dishonest computer repairman, steal rams. Burn the motherboards!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2479290/header.jpg?t=1745101890', 1, 0, NULL);
INSERT INTO games VALUES (95838, 2479320, 'Pesticide Not Required', 'Mow down countless crops and corrupt critters while crafting game-breaking builds! Pesticide Not Required is an action roguelite bullet heaven game with farming sim elements that offers a myriad of stats and special character traits to create wildly diverse run possibilities.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2479320/header.jpg?t=1748877224', 1, 0, NULL);
