INSERT INTO games VALUES (26034, 2591010, 'Silent Depth 2: Pacific', 'Silent Depth 2: Pacific is a lite sub-sim. You enter the Silent Service at the command of a Gato class submarine on War Patrols during World War 2. How long will you survive, and ultimately how much tonnage you sink is down to skill and cunning.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2591010/header.jpg?t=1746189557', 0, 0, NULL);
