INSERT INTO games VALUES (131881, 2697930, 'Commander Quest', 'Congratulations! You just found a ''one of a kind'' roguelike that combines deck-building card game and auto battle strategy game! Consider unit counters, then create powerful synergy by breaking down the boundaries between the battlefield and cards, then lead your army to victory!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2697930/29d318e42feef8ab10203ca27ff8baa70413dd3d/header_alt_assets_0.jpg?t=1749720570', 1, 0, NULL);
INSERT INTO games VALUES (138414, 2698780, 'ContractVille', 'Plan, design, build, and decorate your dream house in an open-world. Smash walls, sketch your layout, then build and decorate every inch—inside and garden. In an open world, tackle each renovation solo or with up to 4 friends. Pick up that hammer and start creating - Your dream house is waiting!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2698780/a1e80268b835eb1ab857b0b7dccbcb0e10a82ed7/header.jpg?t=1748951965', 1, 0, NULL);
INSERT INTO games VALUES (137834, 2698870, 'Midnight Murder Club', 'A heart-pounding and hilarious horror party game set in a pitch-black mansion. Armed with a flashlight, a revolver, and proximity chat, you and up to five friends sneak, shout, and stumble your way through tense shootouts, chaotic traps, and total darkness.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2698870/header.jpg?t=1748902572', 1, 0, NULL);
INSERT INTO games VALUES (138317, 2698940, 'The Crew Motorfest', 'Welcome to Motorfest, the ultimate open-world driving experience. Explore the Hawaiian islands of O''ahu and Maui. Celebrate the best of car culture through 20+ themed campaigns (street racing, offroad, drift...) and collect hundreds of iconic vehicles. Enjoy the game free for five hours!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2698940/header.jpg?t=1741704730', 1, 0, NULL);
INSERT INTO games VALUES (140120, 2701660, 'DRAGON QUEST III HD-2D Remake', 'DRAGON QUEST III HD-2D Remake is a stunning reimagining of the beloved masterpiece and narrative beginning to The Erdrick Trilogy.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2701660/header.jpg?t=1747991212', 1, 0, NULL);
INSERT INTO games VALUES (21910, 2701700, 'Maestro', 'Step into a gorgeous opera house with Maestro, the VR orchestra conducting rhythm game that''s the essence of elegance, control, and high-society french sophistication.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2701700/header.jpg?t=1744121127', 1, 0, NULL);
INSERT INTO games VALUES (21853, 2702490, 'TETRACHROMA', 'TETRACHROMA is a block stacking puzzle action game with a new color changing mechanic inspired by Reversi. Manage the constantly changing colors of the board to clear 15+ lines with a single piece.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2702490/header.jpg?t=1743374944', 0, 0, NULL);
INSERT INTO games VALUES (21860, 2702700, 'HEARTSHOT', 'HEARTSHOT is a story driven VR espionage thriller where fast, chaotic gunplay meets retro-inspired cinematic environments. Armed with high-tech magnet gloves, seize weapons from fallen enemies and manipulate your environment as you make your way through a mysterious subterranean complex.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2702700/header.jpg?t=1709522674', 0, 0, NULL);
INSERT INTO games VALUES (21815, 2703850, 'Rooftops & Alleys: The Parkour Game', 'Ever felt like the world was missing that one Parkour/Freerunning game? That game that scratches that itch that other games just don''t? Rooftops &amp; Alleys aka TheParkourGame is here to deliver! In this game, there''s is no ''hold button to parkour'' mentality. Here, you, the player is in control!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2703850/7a62174321720853b2b79ab1dfd554e8f0a491f7/header.jpg?t=1749145934', 0, 0, NULL);
INSERT INTO games VALUES (21708, 2706170, 'Get To Work', 'You are poor and bald. Get to Work.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2706170/header.jpg?t=1735594455', 1, 0, NULL);
INSERT INTO games VALUES (21715, 2706300, 'MILF''s Plaza', 'MILF''s Plaza is an erotic visual novel with a non-linear plot in a unique 2D style! The main character, full of ambition and eager for thrills, is ready to do anything to find his place in the sun. But his life is only turning out to be more complicated...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2706300/header.jpg?t=1748604612', 0, 0, NULL);
INSERT INTO games VALUES (21630, 2707490, 'Tower Factory', 'Tower Factory is a tower defense and automation game with roguelite elements. Optimize resource production using conveyor systems while defending against monster waves. Can you find and destroy the enemy tower before it''s too late?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2707490/215bfb84ff8e3780e0f4b63c78678311f3875f54/header.jpg?t=1743170915', 1, 0, NULL);
INSERT INTO games VALUES (21649, 2707940, 'FPV Kamikaze Drone', '&quot;FPV Drone Kamikaze&quot; is a fast-paced action game where players control a combat drone from a first-person perspective. The objective is to destroy enemy equipment in war using maneuvers and explosive devices. Speed and strategy will be the keys to victory.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2707940/header.jpg?t=1746874927', 0, 0, NULL);
INSERT INTO games VALUES (21627, 2708280, 'ESCAPE FROM BOYKISSER', 'ESCAPE FROM BOYKISSER is a psychological horror game that immerses the player in the sterile rooms of BACKROOMS.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2708280/header.jpg?t=1737707876', 1, 0, NULL);
INSERT INTO games VALUES (21629, 2708450, 'Oh Deer', 'One Hunter, and up to four more friends disguised as deer, in this thrilling game of hide-and-seek where every move could be the last. Will you blend in with the herd or stand out? Oh Deer...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2708450/c110a0154e044bed656611b8e6fe8aa888010abe/header.jpg?t=1742266552', 0, 0, NULL);
INSERT INTO games VALUES (21610, 2708950, 'Corruption Town', 'Control Agnes as she tries to resist the temptations of the lecherous men around her. Manage the Limping Duck, a shady inn where the wretched go to have a drink and ogle Agnes! It''s your choice to help her succumb to corruption or fight it!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2708950/header.jpg?t=1747164655', 0, 0, NULL);
INSERT INTO games VALUES (21517, 2710950, 'Revenge Of The Colon', 'Revenge of the colon is a story driven, single-player, atmospheric, body horror game with multiple endings. Perform colonoscopies on five patients and discover the horrors concealed deep within them. PS1 horror style!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2710950/header.jpg?t=1717442100', 1, 0, NULL);
INSERT INTO games VALUES (21405, 2713690, 'Shattered Minds', 'Unleash your mind-controlling powers in this open-world visual novel. Build your harem, take over buildings, and slowly bring the town and its citizens under your influence. Shape destinies, forge relationships, and indulge in your desires in a world full of thrilling adventures.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2713690/header.jpg?t=1746204210', 0, 0, NULL);
INSERT INTO games VALUES (21370, 2714620, 'Duck Detective: The Ghost of Glamping', 'You are the one and only Duck Detective, a depressed and recently divorced duck who must quack the case. Inspect evidence, make de-duck-tions, and solve this no-murder mystery!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2714620/header.jpg?t=1747928530', 0, 0, NULL);
INSERT INTO games VALUES (21380, 2714970, 'Backrooms Media', 'Backrooms Media is a 1-4 player co-op horror that plunges you into unsettling, hyper-realistic liminal spaces. Navigate eerie environments filled with lurking horrors. Group up with your friends to face the terror of the endless backrooms together and... try to escape.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2714970/header.jpg?t=1743514901', 1, 0, NULL);
INSERT INTO games VALUES (21330, 2715650, 'Humans are not that against Lizardwomen', 'Once again vile lizards descended upon the lands of Hyperborea, and their plans are as wicked and perverse as ever! It''s time to take a swig of the fortifying waters of Baikal and repel these reptile temptresses! We''ll push them against the wall and show them the true might of our heroic spears!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2715650/header.jpg?t=1745771187', 0, 0, NULL);
INSERT INTO games VALUES (21310, 2716110, '[Chilla''s Art] Jisatsu | 自撮', 'Jisatsu | 自撮 is a Japanese found footage mockumentary horror game.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2716110/header.jpg?t=1708152942', 1, 0, NULL);
INSERT INTO games VALUES (21322, 2716400, 'The Rise of the Golden Idol', 'The Award-winning detective saga returns in this standalone sequel to The Case of the Golden Idol. Uncover the truth behind 20 strange cases of crime, death and depravity in the 1970s. The world has changed dramatically - the sins of humanity have not.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2716400/header.jpg?t=1738770402', 1, 0, NULL);
INSERT INTO games VALUES (21266, 2717080, 'Merry XMerge', 'Merry XMerge is a good board game for all ages this Christmas. Put together Christmas cakes and candies to make them more attractive. Merry Christmas.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2717080/header.jpg?t=1709108842', 0, 0, NULL);
INSERT INTO games VALUES (21276, 2717260, 'I''m counting to 6...', 'Turning onto an old road, the main character gets into an accident due to thick fog. Now he''s trying to find someone who can help him. Forced to enter an old house, the main character finds himself trapped, from which it is not so easy to get out.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2717260/header.jpg?t=1739089616', 0, 0, NULL);
INSERT INTO games VALUES (21252, 2717750, 'Tobla - Divine Path', 'In Tobla - Divine Path, creative puzzle gameplay, a story inspired by classics like Portal™, and impressive 3D graphics come together. Step into the role of Mort and tackle the challenging puzzles and cynical comments of the cunning goddess Tobla to find your way home.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2717750/header.jpg?t=1731936058', 1, 0, NULL);
INSERT INTO games VALUES (138361, 2717880, 'The Rogue Prince of Persia', 'Sprint on the walls with a unique 2D movement, flowing seamlessly into fast-paced acrobatic combat as you tear through an army invading your capital city, in this action-platformer roguelite installment in the Prince of Persia series.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2717880/header.jpg?t=1747922184', 1, 0, NULL);
INSERT INTO games VALUES (21231, 2718240, 'PolyPine', 'A forest simulator where you grow trees and create habitats for animals, plants and insects. Click on animals to make them poop, hunt, dig, cut and twerk! Start with a few basic seeds and attempt to grow a thriving ecosystem.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2718240/header.jpg?t=1746781436', 0, 0, NULL);
INSERT INTO games VALUES (133114, 2719060, 'Mirage Feathers', '「Maybe one day, I won''t have to fight when I fly.」', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2719060/header.jpg?t=1745394993', 1, 0, NULL);
INSERT INTO games VALUES (21191, 2719160, 'Contractors Showdown : ExfilZone', 'Contractors Showdown delivers adrenaline-fueled VR combat with two distinct modes: fast-paced Battle Royale and the immersive, tactical Exfil Zone. Customize your loadout, complete missions, and fight to survive in dynamic, high-stakes battles. Gear up, squad up, and dominate the VR battlefield!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2719160/bcec6bbe83ea4dcd64cd2dfd27aca11494f5811b/header.jpg?t=1747400065', 1, 0, NULL);
INSERT INTO games VALUES (21193, 2719200, 'SAMURAI WARRIORS 4 DX', 'The sparks of destiny ignite in this rich depiction of the Warring States period that features a total of 55 different officers. The deluxe edition contains more than 150 previously released DLC from &quot;SAMURAI WARRIORS 4,&quot; including costumes, weapons, customization parts, scenarios, and BGM!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2719200/header.jpg?t=1748480881', 0, 0, NULL);
INSERT INTO games VALUES (21198, 2719290, 'Night Raider', 'Night Raider is a thrilling adventure exploration shooter game. Players need to carry weapons into the city occupied by zombies, as far as possible in various buildings to collect necessary supplies, evacuate alive to bring supplies back to the camp. But you have to face are not just zombies...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2719290/header.jpg?t=1740748475', 0, 0, NULL);
INSERT INTO games VALUES (21179, 2719940, 'The Bonerooms', 'The Bonerooms is a goofy horror-themed multiplayer game about surviving in a living maze. What will be your downfall? The spooky inhabitants of the maze, or your fellow players?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2719940/header.jpg?t=1744482540', 0, 1, NULL);
INSERT INTO games VALUES (21186, 2720010, 'Rogue Fable IV', 'Storm the lair of the immortal wizard Yendor in this fast paced, turn based, traditional rogue-like. The massive scope, deep mechanics and challenging gameplay that define the genre distilled into dense and highly varied one hour runs.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2720010/header.jpg?t=1734629153', 0, 0, NULL);
INSERT INTO games VALUES (21136, 2720950, 'Grunn', 'A gardener gets hired for maintenance work over the weekend. A simple task, but strangely some tools are missing… The owner of the garden isn''t around, and their house is off-limits. Perhaps new tools can be found in the mysterious town, or maybe some of the reserved townsfolk have seen them?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2720950/header.jpg?t=1749654083', 1, 0, NULL);
INSERT INTO games VALUES (21072, 2722360, 'Escape Memoirs: Safe House', '&quot;Escape Memoirs: Safe House&quot; is a co-operative reverse escape-room puzzle game. You are a member of a criminal organization who must break into one of their own safe houses to fetch some important tools. Do you think you have what it takes to overcome the puzzles that stand in your way?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2722360/header.jpg?t=1734637582', 0, 0, NULL);
INSERT INTO games VALUES (20929, 2725260, 'ENDER MAGNOLIA: Bloom in the Mist', 'Decades after the events of ENDER LILIES, Homunculi — sorrowful, artificial life forms — roam the land. In this dark fantasy Metroidvania, face formidable enemies and explore a bewitching post-apocalyptic world. Humans and Homunculi — what awaits at the end of the quest for their salvation?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2725260/header.jpg?t=1740447961', 1, 0, NULL);
INSERT INTO games VALUES (20895, 2726450, 'Windowkill', 'Windowkill is a twin-stick shooter, but the game window itself is constantly closing in on you. Shoot the window edges to push it around your screen as you fight and dodge enemies and bosses in their own windows.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2726450/header.jpg?t=1740381741', 1, 0, NULL);
INSERT INTO games VALUES (20898, 2726490, 'Hamster Hunter', 'You come home for an annual family reunion, only to find your family missing with an eerie note left by your father. After you discover what has happened you SEEK REVENGE!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2726490/header.jpg?t=1737173714', 0, 0, NULL);
INSERT INTO games VALUES (137835, 2727650, 'WHAT THE CAR?', 'An absurdly silly adventure full of racing, laughs, and unexpected surprises. Roll, sprint, jump, fly and sneeze your way to victory on the racetrack and beyond!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2727650/header.jpg?t=1746014048', 1, 0, NULL);
INSERT INTO games VALUES (20814, 2729000, 'Cats and Seek: Dino Park', 'Hi, this time we''re going to follow John and Emily on a date to Dino Park. Turns out, not only are there lots of dinosaurs, but there are also many cats playing and hiding there 🐱🦕 ! Let''s play hide and seek with the cats in Dino Park!   Can you find them all? ❤️', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2729000/header.jpg?t=1745565073', 1, 0, NULL);
INSERT INTO games VALUES (20798, 2729480, 'NightClub Simulator', 'Step into the wild world of Nightclub Simulator VR! Experience an exclusive party where you can dance, mingle, fight, or flirt your way through a chaotic nightclub scene. Interact with lifelike NPCs, build relationships, cause a little mayhem, or just enjoy the music. Your night, your rules.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2729480/header.jpg?t=1749607572', 0, 0, NULL);
INSERT INTO games VALUES (87879, 2730540, 'Card-en-Ciel', 'Card-en-Ciel is a roguelite card-battling RPG featuring over 300 different cards and 50 unique vocal songs! Play as Neon, the &quot;Gaming Chair Detective&quot; famous for solving net-crimes, as he encounters a strange new case when he dives into an in-development game world.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2730540/header.jpg?t=1735027250', 1, 0, NULL);
INSERT INTO games VALUES (20691, 2731870, 'Ys X: Nordics', 'Explore uncharted islands, engage in fast-paced action combat, and experience the high seas adventures of unlikely allies Adol and Karja in Ys X: Nordics!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2731870/header.jpg?t=1732666948', 0, 0, NULL);
INSERT INTO games VALUES (20701, 2732100, 'Medieval Blacksmith', 'Medieval Blacksmith is a blacksmithing simulation set in a magical medieval world. Play as a blacksmith with no past, craft legendary weapons from daggers to spears, and forge your path to becoming the world’s greatest. Dive into a story filled with adventure and endless creative possibilities!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2732100/header.jpg?t=1744617075', 1, 0, NULL);
INSERT INTO games VALUES (20646, 2732820, 'The Great Rebellion', 'The Great Rebellion is a cyberpunk 2D sidescrolling run''n''gun roguelite using mouse/twinstick-shooter controls. It features randomly generated levels, multiple difficulty modes (including optional permadeath), a dynamic soundtrack and an upgradeable player character.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2732820/header.jpg?t=1734710743', 0, 0, NULL);
INSERT INTO games VALUES (20651, 2732960, 'Command & Conquer™ Generals Zero Hour', 'Command &amp; Conquer Generals Zero Hour brings you closer to the enemy than ever before. Engage opposing forces at hot spots around the globe as you match strategies and arsenals against the new masterminds of modern war.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2732960/header.jpg?t=1741704775', 1, 0, NULL);
INSERT INTO games VALUES (20558, 2735510, 'Once a Porn a Time 2', 'Once a porn a time 2, is an adventure style visual novel with high-quality animations, Oriental Princesses, Romances and other strange creatures that you have to bang.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2735510/header.jpg?t=1718456845', 0, 0, NULL);
INSERT INTO games VALUES (20518, 2736480, 'Hidden Cats in Berlin', 'HALLO! Our cats are now in the awesome city of Berlin! Let''s search for them. A short and pleasant experience in a big and lovely illustration! Start with a Beautiful monochromatic scenario, relax, and find all the cats to reveal the final colored art.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2736480/header.jpg?t=1749157390', 0, 0, NULL);
INSERT INTO games VALUES (20529, 2736690, 'Void Sols', 'Death is but a lesson in the geometric gloom. Step into a hand-crafted souls-like as a forsaken triangle, carving your path through the remnants of this abstract fantasy. Fight powerful angular enemies and uncover twisted secrets as you liberate an oppressed world.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2736690/header.jpg?t=1742813723', 1, 0, NULL);
INSERT INTO games VALUES (20479, 2737300, 'Parking Garage Rally Circuit', 'Retro Arcade Rally Racing... in Parking Garages?!? Precision driving with tight simple controls and arcade physics, all in a Sega Saturn style presentation', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2737300/header.jpg?t=1738274612', 1, 0, NULL);
INSERT INTO games VALUES (20435, 2738380, 'Internet Cafe & Supermarket Simulator 2024', '&quot;Internet Cafe &amp; Supermarket Simulator 2024&quot; is a comprehensive simulation game that combines the management of both an internet cafe and a supermarket. Step into the role of a shop owner, apply your business acumen, and expand your empire step by step.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2738380/header.jpg?t=1735714505', 1, 0, NULL);
INSERT INTO games VALUES (20442, 2738490, 'Sol Cesto', 'Sol Cesto is a tactical and frantic roguelite where mastering your luck is key. Choose a hero, upgrade them using cursed teeth and magical items, and descend to the bottom of an ever-changing dungeon. In this dark world, every action has consequences…', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2738490/header.jpg?t=1749484297', 1, 0, NULL);
INSERT INTO games VALUES (20450, 2738670, 'PMC Promiscuity', 'Take on the role of a recruit (and stress-relief) joining the famous monster girl private military company: Manticore International!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2738670/header.jpg?t=1743965479', 0, 0, NULL);
INSERT INTO games VALUES (20419, 2738940, 'Voids Vigil', 'Blast through robotic hordes in this arena auto-battler rogue-lite Brotato-like. Use auto-firing weapons and drones, timely dashes and special abilities to reach the Void where a final Conservator awaits convergence. Spend your Cogs wisely within the varied shops to create unique builds!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2738940/header.jpg?t=1741624519', 0, 0, NULL);
INSERT INTO games VALUES (104835, 2739590, 'Mad Island', 'This survival game is packed with features including crafting, exploring, building, excavation, farming, fishing, capturing creatures, torture, battle, and a story with many forks along the way. The objective is to escape the island, but is that really your only choice?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2739590/header.jpg?t=1747326361', 0, 0, NULL);
INSERT INTO games VALUES (20404, 2739630, 'of the Devil', 'Immerse yourself in neon, smoke, and high-stakes legal gambles as a Defense Attorney with uniquely Killer insights in this episodic, diabolically stylish visual novel adventure game.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2739630/header.jpg?t=1739321843', 0, 1, NULL);
INSERT INTO games VALUES (20374, 2739830, 'King Arthur: Legion IX', 'Dive into a unique blend of turn-based tactics and character-centric RPGs. Lead the skilled Roman tribune Gaius Julius Mento as he navigates through the dark fantasy realm of Avalon.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2739830/header.jpg?t=1748866301', 0, 0, NULL);
INSERT INTO games VALUES (87599, 2740280, 'Tactic Boxing', 'Tactic Boxing is a boxing game with ragdoll physics, local multiplayer, career mode and manager mode.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2740280/header.jpg?t=1742554336', 1, 0, NULL);
INSERT INTO games VALUES (20345, 2741490, 'At Tony''s', 'At Tony''s is a first-person horror experience taking place in a haunted pizzeria. The last night shift worker vanished mysteriously, it''s your turn to step in to help the family''s business.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2741490/header.jpg?t=1716050815', 0, 0, NULL);
INSERT INTO games VALUES (20349, 2741560, 'SimCity™ 3000 Unlimited', 'SimCity 3000 Unlimited brings you the classic strategy gaming of SimCity 3000 with all-new scenarios that open up a whole world of city planning and building possibilities! The thrills of the classic SimCity 3000 are here again!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2741560/header.jpg?t=1716690294', 0, 0, NULL);
INSERT INTO games VALUES (20353, 2741620, 'Exiled', 'Charlotte is missing. Decode an ancient language, investigate a mystery, and stay away from ancient monsters in this compact puzzle thriller.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2741620/header.jpg?t=1725111836', 0, 0, NULL);
INSERT INTO games VALUES (136196, 2742830, 'Monster Train 2', 'Monster Train returns with all new clans, new enemy factions, new challenges, new modes and more! Defend your Pyre in the classic three-tiered, vertical gameplay that made the original roguelike deckbuilder a hit.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2742830/header.jpg?t=1749559111', 1, 0, NULL);
INSERT INTO games VALUES (20250, 2743850, 'Tricky Madness', 'Tricky Madness is an upcoming arcade snowboarding game with a focus on speed and big air inspired by classics like SSX and 1080. Race down the mountain, explore secret areas, catch big air and perform Wicked tricks.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2743850/bae2bc7f86b2a656fc062d216e71a65b024e9178/header.jpg?t=1748307941', 0, 0, NULL);
INSERT INTO games VALUES (20255, 2744010, 'Urban Jungle', 'Use luscious plants to turn your ordinary home into a green haven in Urban Jungle. Find the best place for each plant in your small apartment and enjoy gardening without worries. And don''t forget to pet your cat!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2744010/e9a4256dc66573a9059d0c3612b903090bdaf4fa/header_alt_assets_2.jpg?t=1749209270', 1, 0, NULL);
