INSERT INTO games VALUES (18197, 2800450, 'Planetaries', 'Experience a vast Sci-fi open-world survival TD game set on a distant planet deep in the universe. Craft, build, mine, trade, explore, and survive in this alien world. Collect Data and defend against waves of enemies seeking to banish you. Enjoy the adventure in Singleplayer or Multiplayer.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2800450/header.jpg?t=1742224330', 0, 0, NULL);
INSERT INTO games VALUES (18222, 2800900, 'Rift Riff', 'Jump a rift, fight off monsters, plunder their world. A strategic mix of juicy tower loadouts, varied monster behaviors, and forgiving mechanics.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2800900/9058dd5d52e4cf0fb9d8bfc0b600979008c06f4c/header.jpg?t=1748602231', 1, 0, NULL);
INSERT INTO games VALUES (18158, 2802110, 'SPY-der PIG', 'This is Obstacle game. Agent Spy-der Pig with the mission of destroying the most powerful thing in the dark world. The higher you go, there will be more obstacles and challenges. Let''s fight together with Mr.derPig to see who will get to the best position in this journey.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2802110/header.jpg?t=1709108494', 0, 0, NULL);
INSERT INTO games VALUES (18123, 2803280, 'Dragon Is Dead', 'Dragon is Dead is a hack-and-slash, roguelite action platformer. It offers tons of customization fun with different character skill trees and legendary equipment.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2803280/2f4992193b3cacfdd9dd3fdf65eaf58a5d6005aa/header.jpg?t=1749214589', 1, 0, NULL);
INSERT INTO games VALUES (18047, 2805060, 'Diabotical Rogue', 'Welcome to our online first-person shooter that combines fast-paced combat and roguelike upgrades. Choose from 4 base suits each with their unique flair. Improvise. Adapt. Overcome your opponents and teammates alike.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2805060/header.jpg?t=1721130299', 1, 0, NULL);
INSERT INTO games VALUES (18013, 2806230, 'Gaming Cafe Life', 'Manage your very own gaming cafe!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2806230/header.jpg?t=1725339049', 0, 0, NULL);
INSERT INTO games VALUES (131569, 2806640, 'The Talos Principle: Reawakened', 'Step back into a world of thought-provoking puzzles, philosophical intrigue, and breathtaking visuals with The Talos Principle: Reawakened - a first-person puzzle masterpiece for both new players and long-time fans alike.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2806640/header.jpg?t=1745519936', 1, 0, NULL);
INSERT INTO games VALUES (17973, 2807150, 'Worshippers of Cthulhu', 'LEAD the CULT OF CTHULHU. Decide the fate of your followers, perform eldritch rituals, and master the art of city-building in a world where the line between sanity and madness blurs. Can you endure the horrors you unleash?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2807150/4b6d6babb3cea575f820cf008d0fcc3d38384102/header_alt_assets_5.jpg?t=1748003417', 0, 0, NULL);
INSERT INTO games VALUES (17847, 2810780, 'Forsaken Frontiers', 'Step into the frozen unknown in Forsaken Frontiers, a cooperative analog horror adventure set in the unforgiving embrace of an everlasting winter.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2810780/header.jpg?t=1748224685', 0, 0, NULL);
INSERT INTO games VALUES (17694, 2814610, 'The DeLuca Family - Season 1', 'The DeLuca Family is a story-driven adult game. Try to win over the ladies of the house and increase in the ranks in the crimeworld. Choose your playstyle with three modes - full experience (Text-based rpg game), story+freeroaming, or VN-Mode. But no matter the mode, lots of lewd!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2814610/header.jpg?t=1709075519', 0, 0, NULL);
INSERT INTO games VALUES (17635, 2816950, 'Yaoling: Mythical Journey', 'Yaoling: Mythical Journey is a creature collecting Eastern fantasy RPG featuring an world filled with rich stories and unique Yaolings. Tasked to uncover a mysterious evil, you embark on a journey with your Yaolings, forming new friendships, engage in intense battles, and face countless challenges!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2816950/header.jpg?t=1734684567', 0, 0, NULL);
INSERT INTO games VALUES (17586, 2817620, 'Machinika: Atlas', 'Machinika: Atlas is an indie puzzle game and is the direct sequel to Machinika: Museum, you play as a museum researcher who just land on Atlas. Will you unravel the mysteries of the alien vessel? Solve cryptic puzzles to find out what happened!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2817620/header.jpg?t=1744988611', 1, 0, NULL);
INSERT INTO games VALUES (17566, 2818150, 'Cattle Country', 'Howdy partner! Welcome to Cattle Country, the Cozy Cowboy Adventure Life Sim. Become a determined pioneer traveling west to start a new life. Make a home in the mountains, take on bandits, discover dastardly plots, build a farm, develop your town, and make friends with fellow residents.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2818150/header.jpg?t=1748355228', 0, 0, NULL);
INSERT INTO games VALUES (135088, 2818260, 'Vigor', 'Outlive the apocalypse! Dive into intense Encounters and extract the most valuable spoils the Outlands have to offer! Loot, shoot, and build to become the absolute Outlander and explore the landscape of a post-war Norway in Vigor, a free-to-play looter shooter.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2818260/b0667aea31eb1eef22c3b994072846cbd6122a50/header.jpg?t=1748946933', 0, 1, NULL);
INSERT INTO games VALUES (17470, 2819970, 'Jeepney Simulator 2', 'Embrace your inner jeepney driver once again in the big, bustling streets of Manella City! Pick up passengers, calculate change, and weave through traffic in this one-of-a-kind driving game. Bring your friends, customize your jeepneys, and face rising quotas. Will you survive? or fade into history?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2819970/header.jpg?t=1732797532', 0, 0, NULL);
INSERT INTO games VALUES (17464, 2820800, 'Night Bus', 'Night Bus is a thrilling public transit simulator that costs less than a bus ticket! It''s your first night on the job: Pick up passengers, take their fares, enjoy the beautiful countryside, and please ignore That Which Has No Eyes.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2820800/header.jpg?t=1746402261', 0, 0, NULL);
INSERT INTO games VALUES (137521, 2820820, 'Jotunnslayer: Hordes of Hel', 'Hordes of Hel is a gripping roguelike horde-survivor game set in the dark realms of Norse Mythology. Fight waves of enemies to earn divine blessings of ancient Viking Deities, explore hostile worlds and face powerful bosses. Become a god-like warrior in this ultimate showdown.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2820820/f04a3de568056d451b0b14e4b1cc941d7bf6bad1/header_alt_assets_1.jpg?t=1747818191', 1, 0, NULL);
INSERT INTO games VALUES (17418, 2821800, 'Drill Core', 'Corporate greed meets strategic planet-mining in Drill Core! Drill to the heart of planets while managing workers, researching cutting-edge tech, and fortifying against alien attacks. Will you prioritize efficiency and risk your workers'' safety, or focus on defense for survival?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2821800/86bc8c56afd939f707cfdb5257d52f13cbc34435/header.jpg?t=1748265023', 1, 0, NULL);
INSERT INTO games VALUES (17425, 2821890, 'PegIdle', 'PegIdle is a Pachinko idle game! Aim and shoot your balls to clear all the pegs on the board. Recieve gold by hitting the golden pegs or by landing balls into the moving bucket. Purchasing auto ball drop will automaticly drop balls onto the board. Spend your gold on new balls and ball upgrades!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2821890/header.jpg?t=1748891080', 1, 0, NULL);
INSERT INTO games VALUES (17401, 2822370, 'Chocolate Factory Simulator', 'Enter the world of steam and sugar and become a master chocolatier in Chocolate Factory Simulator. Craft gourmet chocolate for your customers in your steampunk workshop with the help of your automaton assistant Nougat.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2822370/header.jpg?t=1746452004', 1, 0, NULL);
