INSERT INTO games VALUES (17341, 2823890, 'Center Station Simulator', 'Mine, farm, manufacture components and build a wide range of machines in an infinite basement. Forget primitive tasks thanks to automation! And sell your products to your customers! Build a parking, a gas station...', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2823890/header.jpg?t=1741046065', 0, 0, NULL);
