INSERT INTO games VALUES (17155, 2827810, 'Ark of Charon', 'Build a mobile fortress on the back of a giant and mysterious walking Tree and embark on a journey in this merge of tower defense and colony simulation.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2827810/header.jpg?t=1734656963', 1, 0, NULL);
