INSERT INTO games VALUES (16102, 2853130, 'Astrodle', 'Ready for some chill time in space? Astrodle has you covered. Watch the numbers soar as you upgrade your ship and travel the stars. Oh, and you might just become a god.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2853130/header.jpg?t=1718804789', 0, 0, NULL);
INSERT INTO games VALUES (16083, 2853590, 'Void War', 'Command an ancient starship and fight your way to the heart of a dying Empire. Fend off attacks from demented cultists, craven space pirates, and xenophobic Imperial soldiers. Discover powerful artifacts and use them to build your ship into a fearsome war engine.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2853590/header.jpg?t=1748894007', 0, 0, NULL);
