INSERT INTO games VALUES (16056, 2853840, 'Family Breeding', 'Family Breeding is a 2D visual novel with top-notch artwork where you play as a young man living together two women, your mother and your sister. Your family has a different tradition. The women of the family are expected to get get knocked up by the family head, which in this case, it''s you.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2853840/header.jpg?t=1727136398', 0, 0, NULL);
INSERT INTO games VALUES (16010, 2854740, 'Nunholy', 'In a world overrun by vampires, a group of nuns with their own stories have arrived at the Hunters'' Guild. They are ready to wield any power—even that of demons—to defeat their enemies. What fate awaits them on this perilous journey?', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2854740/header.jpg?t=1742485802', 1, 0, NULL);
INSERT INTO games VALUES (16012, 2854780, 'Froggo''s Adventure: Verdant Venture', 'A Simple and Bite-sized retro 2D Platformer about a frog on another side-scrolling adventure', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2854780/header.jpg?t=1730379348', 0, 0, NULL);
INSERT INTO games VALUES (16002, 2855480, 'PARASiTE FLOWER', 'PARASiTE FLOWER is a beautiful yet disturbing side scroller game where you slowly uncover the story of Ari.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2855480/header.jpg?t=1711228069', 0, 0, NULL);
INSERT INTO games VALUES (15963, 2856450, 'Dimensionals', 'Dimensionals is the hottest roguelike turn-based RPG with tons of Heroes to collect and level up. Build a party of 3 heroes and combine hundreds of skills to create insane combos in the ultimate tactical challenge. Fight through an epic story told in the style of voice acted comic book cutscenes.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2856450/b3527a7183bca76826b7a5f3db2b9f9d586c4138/header.jpg?t=1746057103', 0, 0, NULL);
