INSERT INTO games VALUES (15895, 2858370, 'Voxel Project VR', 'Voxel Project offers an immersive sandbox experience set in a fully destructible voxel environment. Explore a dynamic world teeming with vehicles, dynamic fire mechanics, enemy NPCs, voxel gore, weapon customization, and a bunch of additional features to discover.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2858370/header.jpg?t=1749420424', 0, 0, NULL);
INSERT INTO games VALUES (15888, 2859200, 'Alex Hill: Whispers at White Oak Inn', 'A young woman died near the White Oak Inn. Now, her spirit is roaming around, and an employee is receiving strange letters. What dark secrets wait to be found? The clock is ticking and you, as Alex Hill, must uncover the truth before it’s too late.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2859200/header.jpg?t=1743693980', 0, 0, NULL);
