INSERT INTO games VALUES (15798, 2861150, 'Working Sakuya', 'This game is a visual novel game consisting of animation for adults.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2861150/header.jpg?t=1713626551', 0, 0, NULL);
INSERT INTO games VALUES (15717, 2863160, 'Projekt: Passion - Season 2', 'Continue the story of Projekt: Passion. Now with EVEN MORE sex, comedy, sex, and all those things that everyone loves. Continue your fun-filled space adventure and continue developing your relationships with the girls you''ve come to know and love.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2863160/header.jpg?t=1743786032', 0, 0, NULL);
INSERT INTO games VALUES (15697, 2863640, 'The Midnight Walk', 'Follow The Midnight Walk in a dark adventure from the minds behind Lost in Random. Befriend a lost lantern creature and light your way through a world of wonder and terror. Outsmart monsters and marvel at details in a landscape handcrafted with real clay and animated in a stop motion style.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2863640/header.jpg?t=1747815075', 1, 0, NULL);
