INSERT INTO games VALUES (15435, 2869860, 'Monster Prom 4: Monster Con', 'Can you find love at the nerdiest convention ever? &quot;Monster Con&quot; goes back to the multiplayer dating sim formula: go through absurd and funny situations as you find love among six sexy monsters! Who will you romance? The mimic who cosplays? The idol clown? Or the eldritch cutie? (There''s also Liam)', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2869860/1692e630c198bd5a8d6ea33366e374b11a46a28b/header.jpg?t=1748518603', 0, 0, NULL);
