INSERT INTO games VALUES (89964, 3371930, 'Only False', 'Only False is a party game that blends bluffing and strategy, spiced up with a dash of dark humor. In Only False, a game for those who can’t get enough lies, you’ll sometimes lie like a politician, and sometimes think as strategically as Sun Tzu.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/3371930/header.jpg?t=1747739131', 0, 0, NULL);
