INSERT INTO games VALUES (114944, 3375580, 'Lustful Dead 🔞', 'Survive, seduce, and fight in a zombie-infested dorm! Loot resources, battle sexy zombies, rescue girls, and build your ultimate survival harem.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/3375580/header.jpg?t=1740603908', 1, 0, NULL);
INSERT INTO games VALUES (114929, 3376250, 'Nine-Ball Roulette', 'This will be the most thrilling pool game you have ever played. Join up to 3 of your friends in this exciting pool roulette game! Eliminate each other with pool until only one person is left.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/3376250/header.jpg?t=1740056570', 1, 0, NULL);
INSERT INTO games VALUES (131379, 3376990, 'Kabuto Park', 'Enjoy summer in Kabuto Park! Catch the cutest bugs, train them and win the Summer Beetle Battles Championship in this tiny bug collection game! Upgrade your equipment to find rarer, stronger and shinier little friends.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/3376990/header.jpg?t=1748452052', 0, 0, NULL);
