INSERT INTO games VALUES (129697, 3379650, 'Dark PGT', 'Dark PGT – A Souls-like game in an alternate universe of future USSR on Unreal Engine 5. You will play the role of alcoholic-schizophrenic experiencing psychological disorders and hallucinations. Travel to a village in 2030 to unravel all its secrets and solve all its problems.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/3379650/header.jpg?t=1747109203', 0, 0, NULL);
