INSERT INTO games VALUES (137802, 3399950, 'Your Mother', '《Your Mother》is a computer desktop companion. Experience the love and kindness from mothers.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/3399950/header.jpg?t=1746350967', 1, 0, NULL);
