INSERT INTO games VALUES (129762, 3400930, 'Guilty as Sock!', 'Enter a chaotic courtroom where socks play lawyers, prosecutors, and judges! Use absurd evidence, craft wild arguments, and deliver verdicts in this hilarious online party game. Improvise, strategize, and shout &quot;Objection!&quot;—because in Guilty as Sock!, chaos always wins!', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/3400930/header.jpg?t=1749219111', 0, 0, NULL);
