INSERT INTO games VALUES (129763, 3410310, 'Make Good Choices', 'You’re just trying to get home. It’s only a quarter mile. One street. What could go wrong.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/3410310/header.jpg?t=1737678394', 0, 0, NULL);
