INSERT INTO games VALUES (136480, 3431040, 'That''s not my Neighbor', 'It''s 1955, and for unknown reasons, doppelgangers are more common than usual. Therefore, the Department of Doppelganger Detection (D.D.D.) has taken action. You are the doorman of an apartment complex, and you must decide whether to let in those who claim to be your neighbors.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/3431040/header.jpg?t=1741708884', 1, 0, NULL);
INSERT INTO games VALUES (136831, 3435260, 'Dice With Death', 'Dice With Death is a Dicebuilding Roguelike – Unfortunately you have already died. Fortunately, Death is up for some friendly competition. Collect new dice and relics, create damage stacking combos, and even cheat Death himself to emerge victorious.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/3435260/header.jpg?t=1749672263', 0, 0, NULL);
INSERT INTO games VALUES (137542, 3438800, 'Doodle Empires', 'Doodle Empires is an alternate history sandbox game all about drawing your own nations with your own histories and stories in a variety of maps. Watch your world take shape and evolve over time, and decide which nations will rise and which nations will fall.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/3438800/header.jpg?t=1748639971', 0, 0, NULL);
