INSERT INTO games VALUES (131762, 3447410, 'The Test: Reality Check', 'The Test: Reality Check is one of multiple installments in an ongoing social experiment that can be classified as an atmospheric, psychological-simulation with horror elements. Dive deep into your own psyche to find answers to questions you''ve kept locked away, hidden from yourself for far too long.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/3447410/header.jpg?t=1748283868', 0, 0, NULL);
