INSERT INTO games VALUES (117831, 3539440, 'Metal Garden', 'Travel through an overgrown megastructure, and discover what lies beyond it. Metal Garden is a short, atmospheric singleplayer FPS game.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/3539440/b6b52855135acced1935c231bc5a2961e35b1a5b/header.jpg?t=1748524534', 0, 0, NULL);
