INSERT INTO games VALUES (128386, 3571560, 'LUST Eternal 🔞', 'LUST Eternal 🔞 – A brutal, fast-paced shooter where you rise from the ashes, armed with a shotgun and a thirst for carnage. Slaughter demons, crush Hell’s guardians, and claim your sinful rewards with seductive succubi. Hell is yours—will you conquer or indulge? 💀🔥', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/3571560/953f37267e336ba76cb7117032eb23926da9dd35/header.jpg?t=1747994377', 1, 0, NULL);
INSERT INTO games VALUES (127803, 3593780, 'Lumberjacked', 'You wake up in a strange cabin deep in a mysterious forest, axe in hand, with only one way forward—through. Chop trees, sell logs, purchase and upgrade gear, and uncover the secrets hidden deep in the forest.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/3593780/6bb8d9571a6fc64d7d3a86d81c90036933a8e660/header.jpg?t=1748882996', 0, 0, NULL);
INSERT INTO games VALUES (129433, 3598130, 'Big Rigs: Over the Road Racing', 'Get ready for some brake jamm''in, CB talk''in, convoy roll''in action across America! From Portland Oregon to Miami Florida, you''ll be hauling loads and trying to stay one step ahead of the law as you climb into your Big Rig for non-stop driving action.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/3598130/9246a1154a6af6af07a3eac9dd6e7dbf07504b0d/header.jpg?t=1747302444', 1, 0, NULL);
INSERT INTO games VALUES (121799, 3624190, 'Dune: Awakening Beta Weekend', '', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/3624190/e934cbd04b40a615b3306797bd7be76610904f0e/header.jpg?t=1749553554', 0, 0, NULL);
INSERT INTO games VALUES (135247, 3625270, 'MateEngine', 'MateEngine is a lightweight desktop companion app with full custom VRM model support. Bring 3D anime-style characters to life on your screen with idle animations, drag and dance features, and low resource usage and open-source.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/3625270/74c6a7e3aab640bb218c6e1590028918f7d1dd6d/header.jpg?t=1748903478', 1, 0, NULL);
INSERT INTO games VALUES (128982, 3632530, 'Violated Princess', 'Violated Princess is an intense, mature-themed roguelike survivor game where waves of relentless enemies threaten to consume both body and soul', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/3632530/dba6cd736bd9cce1b81880cab29ad04c665b1007/header.jpg?t=1749745864', 0, 0, NULL);
INSERT INTO games VALUES (137411, 3667230, 'The Deadseat', 'A horror game where you play a hand-held console in the backseat during a long drive home.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/3667230/6fec8f4b856c515bd053112ab5fe8d3e1b84fc35/header.jpg?t=1749948354', 0, 0, NULL);
INSERT INTO reviews VALUES (1, 10, 32953, 'This game is fire. Love meeting 46 year old Russian dads that just came home from work and are drinking beer. My new friend Vlad is crazy at this game. Was invited to a party in Smolensk, however sadly couldn''t attend.\r\n\r\nWould recommend.', 'this Game the best i''ve ever played in my entire miserable life \nBUT\nDon''t buy this game for Multiplayer, This Game is infested with Fake cloned servers that will give you Malware when joining them', 'Overwhelmingly Positive', 96.62, 18.58, 23.92);
INSERT INTO reviews VALUES (2, 20, 4018, 'Played for 10 minutes. Accidentally TK''d somebody. Then they spammed my IP address so I uninstalled just as fast as I downloaded this gem. 10/10', 'If you''re from TF2 like me, expect this game to be kinda different. The game can get hectic and long just like TF2. There''s not a lot of players and not a lot of servers.\n\nI''d say don''t buy it, mostly because of a lack of players and servers (EDIT: although it may be different in other countries idk). If you still want to buy it, though, buy it when it''s on a sale. In the United States, the game costs a bit less than 1 USD when it''s on sale.', 'Very Positive', 86.34, 0.17, 5.43);
INSERT INTO reviews VALUES (3, 30, 2082, 'this is my favorite game to play at 2 AM because i join a lobby and find two old men who were probably alive during this war talking in voice chat, a hacker, and at least 12 bots', 'Fun old school game, but unfortunately too many cheaters.', 'Very Positive', 88.81, 0.63, 1.65);
INSERT INTO reviews VALUES (4, 40, 1217, 'gordon freenman x doomguy x quake marine threesome hentai \r\n\r\n\r\nwait this isn''t google', 'Plays like Quake but with a Half-life aesthetic. I can see where the fun value is at, but unless you have a bunch of retro-appreciating friends, finding an active public server is quite difficult.', 'Very Positive', 82.50, 0.80, 0.37);
INSERT INTO reviews VALUES (5, 50, 11994, 'Opposing Force is so good. So many sick weapons and cool new enemies. For how short it is it really packs a punch.', 'The first 3/4 (or so) of this expansion is really enjoyable, with interesting set pieces, fights and puzzles that I think meet the quality standards that the original game established. Even so, the last 1/4 of it is so bogged down by tedious, frustrating and unfair fights that I can''t recommend it.\r\n\r\nThere are essentially only two ways I felt when I died in this part of the game (which I did over and over probably >100 times): either that I was taking stupid risks out of sheer impatience with t', 'Overwhelmingly Positive', 95.38, 2.55, 4.42);
INSERT INTO reviews VALUES (6, 60, 2855, 'this game has certainly changed my life. one day I went on a date and I told my partner "ricochet is a futuristic action game that challenges your agility as well as your aim, ricochet features one-on-one and team matches played in a variety of futuristic battle arenas." I have now been married to her for 20 years. thanks gabe newell for this wonderful experience that allowed me to find true love.\n\n\nI would like a ricochet 2 btw so that I can have a husband alongside my wife', 'Source 2 port when?', 'Very Positive', 85.88, 0.08, 0.08);
INSERT INTO reviews VALUES (7, 70, 52679, 'funny scientist scream, game makes me cream\n\ngame is from the middle ages but it still holds up\n\nword of warning: this game seems a lot faster paced than you think it is. play slow and think combat situations through methodically, or you''ll be living medkit-to-medkit at 10hp for half the game \n', 'It''s simply not a fun game. It feels like you go from room to room and mow down endless enemies, without any purpose. Halfway through I became so tired and frustrated of the repetitiveness that I had to force myself to keep playing. There is a story to it, but for one it''s extremely bare-bones and not explained well at all. And, for two, it''s trickle fed to you between 50 rooms each consisting of the same monotonous enemies. The only reason I bought this game was because it was $1, and I thought', 'Overwhelmingly Positive', 96.45, 50.15, 8.37);
INSERT INTO reviews VALUES (8, 80, 6915, 'Honestly condition zero: deleted scenes NEEDS a source remake. Such a fun campaign.', 'This game was fun, so was classic offensive.\n\n#AllowClassicOffensive', 'Very Positive', 91.19, 17.65, 0.48);
INSERT INTO reviews VALUES (9, 100, 1474, 'A single-player campaign of Counter-Strike is an alien concept to many, but it does exist! In the Hard setting, this is extremely difficult, which is good for CS veterans. Even though I''m personally acquainted with how Goldsrc AI works, this was still a tough game to play through. This feels somewhat like a mix of Call of Duty with Tom Clancy games. The plot changes completely every mission, so there''s no full story at all. Deleted Scenes plays out like a Half-Life game, with maps loading one af', 'Uh... So far my playthrough has not been great. Glitched textures, A content block I never enabled, Game crashing as soon as I use the fiber optic camera, Just a ton of problems. UPDATE: Hit the F key on Miami heat...Game crashed.', 'Very Positive', 92.40, 8.48, 0.38);
INSERT INTO reviews VALUES (10, 130, 8973, 'Blue Shift is definitely underrated. Sure it wasn''t as good as Opposing Force but it was still enjoyable.', 'every single time i load in the game barney just starts uncontrollably unloading his magazine and shoots at walls and other shit made me kill 3 scientists by accident\n\nthank god i only bought this when it was a dollar during the anniversary r', 'Very Positive', 92.46, 1.87, 2.28);
INSERT INTO reviews VALUES (11, 400, 74274, 'There are no enemies, no open world, and barely any plot at first glance. But you do have a portal gun to solve puzzles — or just entertain yourself by falling into an infinite loop. Your companion is the sarcastic AI GLaDOS, who promises you cake but does it in such a tone that you start suspecting you''re more of an ingredient than a guest.\n\nThe gameplay makes you feel smart—at least until you get stuck trying to figure out where to place a portal without face-planting into a wall. Portal is li', 'glados died and gave me no robot sex', 'Overwhelmingly Positive', 98.64, 11.83, 0.63);
INSERT INTO reviews VALUES (12, 440, 25221, 'They removed the Bots as of July 1. I still suck at this game but at least they removed them.', 'Trying to add a matchmaking/quickplay system has only harmed this game then it has ever helped it, even before casual, back to the time when quickplay was added, there were reports of community servers struggling to properly fill up there player slots, alongside complaints of being shoved into servers filled with valve bots, or servers with virus ridden MOTDs, quickplay had many many flaws, but community servers still had thrived. \n\nBut by the time casual was added? So many community servers now', 'Mostly Positive', 72.46, 333.72, 9283.68);
INSERT INTO reviews VALUES (13, 570, 6092, 'Ainda vou precisar de algumas horas a mais para poder avaliar corretamente...', 'This game is dead... full of bots.. unfair penalties.... matchmaking its terrible... and you cannot say anything to a russian troll because you get muted for life.... \n\nI am out...', 'Very Positive', 88.99, 29604.47, 9068.22);
INSERT INTO reviews VALUES (14, 620, 158809, 'God, it''s amazing how well this game holds up even after more than a decade. Both the singleplayer and co-op experiences are top tier in their own way. The voice acting is simply spectacular, the story is intriguing and the puzzles get progressively harder throughout the game (thus providing you with a nice learning curve). This sequel overall is a great step up from the first game and a must-have for virtually any gamer I''d say.', 'I don''t really want to get on a high horse about violent video games but I do think this one is too excessive. This game has you murdering civilians freely as a main objective and there isn''t much of a story. One of the weapons is just you urinating. Turned it off on the petition quest. Too hamfisted for nothing, maybe its a context thing and I had to be there. Crass, childish, not for me unfortunately!', 'Overwhelmingly Positive', 98.85, 16.52, 15.45);
INSERT INTO reviews VALUES (15, 630, 115, 'Years ago I created my steam account just to play this game.', 'Not the most interesting game (in my opinion), but okay to pass time with friends.', 'Very Positive', 94.78, 14.13, 2.83);
INSERT INTO reviews VALUES (16, 730, 1323943, ' More cheaters than on Tinder \n\nOverall great game, just plagued with cheaters.', 'A year has passed. Armory update is a cash grab with no real gameplay value. VAC nowhere to be found, no new maps, the CSGO community has been wiped off the face of the earth. Disgusting company', 'Very Positive', 86.20, 846.08, 2150.25);
INSERT INTO reviews VALUES (17, 1500, 557, 'The style of graphics is unique. Both pixel style, and yet of higher quality. A point and click game to build Darwinians, protect them, train them, and eradicate the red virus. Inventive story line.\r\n\r\nIt can be a bit fiddly to figure out at first as the guidance is a bit lacking - but you get the hang of it. Hit <H> when something is selected for specific guidance, <SPACE> to deselect and ask for help again for something more generic. Once you have met the objectives, hit <ESC> and leave the lo', 'Truly a pioneer for its time. Nowadays that means lots of interface, pathing and broken level issues. Navigating those is the only challenge in this game. Did teach me not to use grenade launcher uphill. There is that.', 'Very Positive', 83.12, 25.02, 1.58);
INSERT INTO reviews VALUES (18, 1640, 591, 'Oldie but goodie, especially for fans of turn based strategy games like Heroes and Might and Magic series. This game does have issues running on newer systems so be sure to download and install the following mod into your game directory after installing:\r\n\r\nhttps://www.moddb.com/games/disciples-ii-dark-prophecy/downloads/disciples-wrapper-v160\r\n\r\n\r\n', 'Doesn''t work. Tried multiple times over the years.', 'Mostly Positive', 78.85, 11.90, 0.20);
INSERT INTO reviews VALUES (19, 2610, 1145, 'THIS GAME NEEDS A REMASTER IM SO SERIOUS', 'Do not buy the Steam version, it''s crap. Crashes all the time and you can''t do the high FPS mod. Get it on GOG instead.', 'Very Positive', 92.05, 14.15, 0.35);
INSERT INTO reviews VALUES (20, 3050, 142, 'Great classic rally game! Would recommend!', '2025 review!!!!!!\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n@ss', 'Mostly Positive', 77.46, 0.50, 6.80);
INSERT INTO reviews VALUES (21, 3330, 2155, 'My dad always played this when I was little, man I thought it looked boring.\n\nI was incredibly wrong, this is incredibly addictive and loads of fun to play, but I just wish he was still around to school me on how he completed the game.', 'game is 100% luck based. making it extremely frustrating', 'Very Positive', 94.85, 3.87, 6.37);
INSERT INTO reviews VALUES (22, 3350, 202, 'There are better versions of this game, but I still recommend it because there''s nothing really wrong with it. I bought this version primarily because of the nostalgia of listening to Skaven tracks and the fact I used to play it on my laptop at my friend''s restaurant in the mid 2000''s while I waited for him to have lunch with me. (The browser version was free back then.) If you don''t have any specific reason to play this version, it might be worth your while to check out a later version.\n\nMy fri', 'I find the game too confusing', 'Very Positive', 88.12, 6.63, 3.80);
INSERT INTO reviews VALUES (23, 3360, 114, 'the guy in the corner of the screen is so hot', 'this is an insult to my intelligence', 'Very Positive', 93.86, 2.45, 6.72);
INSERT INTO reviews VALUES (24, 3380, 257, 'I miss my grandmother, this game has brought me back a lot of good memories of sitting on the floor in her office whilst she played her PopCap games. It brings back a lot of nostalgia.', 'This game is utter slop, legit the worse pop cap has ever put out. As a huge fan of the devs, this is embarrassing.', 'Very Positive', 94.94, 0.30, 8.17);
INSERT INTO reviews VALUES (25, 3390, 1033, 'What if instead of Feeding Frenzy it was 𝓕𝓻𝓮𝓪𝓴𝔂 𝓕𝓻𝓮𝓷𝔃𝔂 and you touched all the fish...', 'Bought this for nostalgia reasons, as I played a ton of it as a kid. I''m telling you now, don''t waste the 5 bucks. This is full of early 2000s jank, and not the charming type. The player character handles really badly, the hitboxes are aggravating, and the view radius is abysmally small so you continually run into predators that happened to be just on the edge, especially when you''re in a mid-size where you''re so big you take up most of the center of the screen, but still vulnerable to one or tw', 'Overwhelmingly Positive', 97.39, 1.65, 8.23);
INSERT INTO reviews VALUES (27, 3410, 242, 'One hand on my mouse and one hand on my heavy weapon', 'Pls Nerf Mission 9', 'Very Positive', 81.82, 12.70, 4.77);
INSERT INTO reviews VALUES (29, 3430, 151, 'Great nostalgia game, i remember it being one of my first games ever played on the good old pc with spec processor pentium 4,256mb ram and ATI Radeon 7000 64MB, brings back so many good memories and there  simply no flaw in it, a relaxing point and click with nice ambient music and nice sounds and gameplay overall.', 'Well...that was disappointing. I admit this game was an impulse buy for me. I grabbed it without much research because I thought it was a throwback to the old Pizza Tycoon game of years gone by.\nSadly it is not.\nIt is essentially an acarde memory game. Match pizza orders with shops that sell the pizza in question. This is not  a tycoon game and it is NOT a ''Build Your Own Pizza Simulator'' wherein you try to construct innovative pizzas to sell in your restaurant.\n\nThis game is gets a negative vot', 'Overwhelmingly Positive', 98.01, 1.12, 0.17);
INSERT INTO reviews VALUES (31, 3480, 8033, 'I love being pegged! It''s fun, relaxing, engaging, and takes my mind off my earthly problems!!! Oh, you mean the game? Oh... it''s fine.. I guess.', 'This game changed my life. Ever since I''ve played Peggle my life has turned around. My wife came back, my hair grew back, I bought oil, and I hear a sudden Ode to Joy whenever I open a door. \r\nThank you, Peggle.', 'Overwhelmingly Positive', 97.77, 11.35, 3.93);
INSERT INTO reviews VALUES (65, 3600, 128, 'Quite a nostalgic game with plenty of play time. I remember playing this game 14 years ago when I was a kid on my grandparents'' desktop. It''s well worth the five dollars for a few hours of fun.', 'Fun game, sometimes hard to find items, and very repetitive scenes. I actually couldn''t wait to be done.', 'Very Positive', 83.59, 18.80, 9.85);
INSERT INTO reviews VALUES (67, 3620, 1218, 'My mom used to play this game on our family computer over a decade ago and my siblings and I all loved to watch. I found it on steam and it was very nostalgic watching our mom play this game again. She still has the skills! I''m very happy to have found this game again:)', 'Way too much RNG luck than actual skill to pass some of the later levels (lv50 onwards) you will feel cheated by the game, unless you get lucky with power ups and have a good start you are screwed!', 'Very Positive', 94.91, 4.08, 17.05);
INSERT INTO reviews VALUES (68, 3700, 1226, 'I don''t know how to put it, but this game, despite its age, remains the most atmospheric of this series of games: all these explosions, shots, screams, even the noise of the surroundings makes it clear that this is not some kind of shooter, like Call Of Duty - this is a simulator of an ordinary soldier, where you can rely only on yourself. Unlike other parts, this one conveys the experience of a sniper best of all. No enemy marks. You yourself must determine the distance to the target and make a', 'fucking trash', 'Mostly Positive', 71.37, 18.73, 4.55);
INSERT INTO reviews VALUES (69, 3710, 795, 'Baltimore police simulator 2003', 'I hate it. At first, it looks promising (it seems to be an old version of ''Ready or Not'' mixed with ''Killing Floor''). But then it loses balance, removes the capture mechanics, and goes all in on Killing Floor-style gameplay. The result? The game gets old fast. Why? Because, unlike Killing Floor, most enemies in this game are bland, either walking toward you or jumping at you. The only good enemies are humans since the AI is kind of smart, they take cover or run for their weapon if disarmed. But,', 'Very Positive', 88.43, 3.48, 5.30);
INSERT INTO reviews VALUES (70, 3720, 2287, 'Cheat codes, humanzee. just type it in, then hit control c for moneys.\nyou''ll have to look up the rest.', 'I absolutely don''t recommend this game.  95-98% of my time was leaving it running while I was asleep or at work to let the money build.  It''s incredibly buggy.  It''s also got a less effective management system than Majesty, the RTS that worked on bribing your minions.  Honestly a really bad game.  You spend a ton of time just waiting for stuff to happen even while you''re playing it.  \n\nIf you hate yourself and play it anyway, make sure you have another screen or a laptop or something to watch vi', 'Very Positive', 94.27, 22.10, 124.02);
INSERT INTO reviews VALUES (71, 3730, 1585, 'God.... Xenomorphs are so hotttttttt.........', 'No... bad game. No tutorial, frame rate drop where I don''t do a damn thing. No direction or objectives as to where the heck to go.  Not explaining anything.  I have no idea WTF I''m suppose to do. I can''t see stuff half the time (heard of flashlights) Had game freeze on me twice when starting the game. Bug where I fell through the floor the raises and lowers you to other levels.  Frame rate drop was worse as the alien.  Game is near unplayable', 'Very Positive', 88.20, 1.20, 0.23);
INSERT INTO reviews VALUES (72, 3800, 288, 'I wish modern Xbox studios would bring this back. This game felt incredible back on the original Xbox but does not adapt well to the PC experience.  Definitely one of the games of all time tho.', 'Good game that I played on xbox 360 long ago. Allows you to make some choices in the story line. Definitly shows its age now. \n\nI don''t recommend this game though because I couldn''t get it to run unfortunately. It keeps crashing, so I suspect that it has something to do with a poor port.', 'Mostly Positive', 79.17, 3.90, 0.08);
INSERT INTO reviews VALUES (73, 3810, 298, 'Classic Vampire themed Slasher .. Solid Game', 'First things first, BloodRayne isn''t a bad game and its far from that. I don''t recommend it to anyone if you''re playing on a newer operative system. The game will crash, the game will glitch, the game will run "too fast", the voice will get cut. I got tired of messing with the game files and ended buying the GOG version and problem solved. I don''t know why the game hasn''t been optimised on Steam too. Such a shame.\n\nIn the current state of this game (on Steam) I can''t recommend it.', 'Mostly Positive', 73.83, 12.68, 0.32);
INSERT INTO reviews VALUES (74, 3830, 8289, 'Imagine if Tim Burton and Jim Carrey went to therapy together but ended up opening a summer camp for training people to break into each other’s minds.\n\nThe gameplay feels like a soulful platformer: you jump, collect and lose yourself on levels that look like the designers brainstormed after three cups of coffee and two cups of mushroom tea.\n\nPsychonauts is when you expected action but got therapy and realized you kind of love it.', 'I really hate steam reviews that judge the game solely by how the game functions on the reviewers hardware. but this game is labeled as "playable" on Steam Deck, and that label is downright shameful.\n\nOut of the box the game does not support the steam decks default controls, or resolution. the game only shows keyboard icons, despite having the ability to show controller ui graphics. and more specifically. the camera will not stop spinning no matter what control changes I make. this game has so m', 'Overwhelmingly Positive', 95.86, 42.90, 1.47);
INSERT INTO reviews VALUES (75, 3900, 1776, 'Probably the best Civ we''re ever going to get. The new ones are prettier but this one is the peak.', 'Crashes constantly.  Alt-tab locks up my computer and forces me to manually restart it.  This game is wonderful but the steam version simply does not run on current hardware.', 'Very Positive', 92.79, 14.95, 85.12);
INSERT INTO reviews VALUES (76, 3920, 4308, 'The best Privateer and Pirate game that i have ever played. You can play as a Privateer and work for your chosen faction or engage in high seas Piracy by attacking everyone including the faction that gave you a letter of marque. You can also recreate Henry Morgan''s 1671 sacking of Panama. The game does well in finding the balance between fun and history(thank god there is no scurvy and syphilis lol)', 'I love this game , however I recently was in the mood to play a 2K game again and was greeted by a TOS that wanted full access to my PC.  They wanted to have permission to view my search history, see what browsers I use and the topping on the cake was forced arbitration if they do anything illegal against me.  This really pisses me off and I will never buy a game that has the 2K label on it ever again.  Its a shame because they use to make some of my favorite games.  I will not support a company', 'Very Positive', 94.87, 149.40, 46.72);
INSERT INTO reviews VALUES (77, 3980, 499, 'ello govnah', 'Super buggy. I''ve spent more time finding ways to get the game to work correctly than is reasonable. I''ve tried verifying the cache, reinstalling the game, changing graphics settings, changing the compatibility, doing some other work-arounds as suggested by others. \n\nAnd for the last 24 hours every time I try to play the game it crashes after about 10 seconds, even after a reinstall. \n\nSteam refuses to give me a refund for a known broken game, so buyer beware. Make sure you read other reviews of', 'Mostly Positive', 73.75, 20.35, 8.53);
INSERT INTO reviews VALUES (78, 3990, 257, 'teehee its the middle expansion no one ever checks (civ 4 is goated, see my beyond the sword review)', 'Game crashes due to "memory allocation failure" every time just before the game ends.  Never get to see the actual ending, even though I''m always ahead. Very frustrating!', 'Very Positive', 93.00, 0.23, 11.23);
INSERT INTO reviews VALUES (79, 4000, 497815, 'its a good game extreme ragdolls and unrealistic lighting navemash doesnt work and building things are very hard but its an amazing game so i sugest it.     also i know noone is going to read this so im gay.', 'shittiest server experience that i ever had in gaming. half of servers requires you to download 2 gigs of content on average, other half will fucking kill your ssd and your time with 20+ gigs of shit content that you absolutely dont need. In aditttion all these servers are laggy as hell. Every gamemode except dark rp, murder and ttt are basically dead. This game servers were killed by its community.  Only play solo/with friends on ur own server.', 'Overwhelmingly Positive', 97.02, 392.20, 70.75);
INSERT INTO reviews VALUES (88, 4500, 14763, 'A gravity anomaly annihilated a military platoon shooting at me, very generously and kindly allowing me to pick all the ammo and sausages off of their corpses without having to spend any resources of my own', 'I gave this game a try twice but I just can''t see it through to the end. I came very close to beating it but after dying repeatedly in a section with 15 enemies shooting at once only to clear it to then be greeted to 20 enemies shooting at once... I quitted. It feels like I''m playing COD in Veteran but with worse gunplay. This game sucks balls man I really wanted to like it but it''s just too dated and the inta kills from the enemies ruined it for me. u.u', 'Very Positive', 94.47, 12.28, 9.85);
INSERT INTO reviews VALUES (89, 4520, 139, 'Game suffers from a very annoying audio bug on modern hardware that causes static and clipping to be heard fairly regularly during dialogue, although it''s not really noticeable during combat. There are some supposed fixes out there but none of them worked for me, the game is otherwise fantastic and I personally think it''s still very much worth playing. Your best bet is to turn the music off and lower the sfx and speech volumes a few notches, that tends to make the issue a little easier to live w', 'Very nice concept, but the lack of Saving-opportunities makes you play passages again and again.\nSad, because it has great potential.', 'Mostly Positive', 74.82, 9.58, 1.67);
INSERT INTO reviews VALUES (90, 4530, 108, 'A relic from when game studios still experimented with their games and didn''t have to template themselves to "AAA" models. \n\nFull spectrum is as described, squad based, tactical real time. You move one of two squads which you can split into two further fire teams at a time. Combat is lethal and dangerous. Most of the player''s job is moving the men around, cover saves lives, flanking is the only surefire way to defeat the enemy. Make no mistake, this game is hard to learn because it plays really ', 'I get what they were trying to do, but this game plays terribly. It''s trying to be tactical, but all I wanted to do was just directly control a soldier the whole time and get the job done myself. Why do I need to mess around with commands to flank the enemy, when in a FPS, I can just do it. It feels like it robs you of agency for the sake of being ''deep and tactical''', 'Mixed', 69.44, 16.80, 0.97);
INSERT INTO reviews VALUES (91, 4560, 2603, 'I love the micromanaging this game displays - from allowing your units to crawl, grab cover, and use grenades, to customising the items units can use as they level up. \n\nThere is no resource gathering in this game unlike other RTSs on the market, which I find great as it means that the game can focus on the fights, and boy are they beautiful - amazing rag-doll physics and environmental destruction.', 'you need dlcs to play something else than like one campaign bruh wtf, the game also crashes a lot', 'Very Positive', 93.85, 271.22, 0.17);
INSERT INTO reviews VALUES (92, 4570, 5231, 'If you''e played StarCraft, you''ll figure out how to play this game pretty quickly.  There are mechanics differences yes and I''m sure the meta is completely different when it comes to strategy, but at the end of the day it''s an RTS game using Warhammer 40k units.  Allegedly, Warhammer served as inspiration for StarCraft (Space Marines = Terrans, Tyranids = Zerg, Eldar = Protoss).\r\n\r\nI only really played the campaign of this game but I enjoyed it.  I had never played the tabletop version of 40k be', 'The negative feedback is only for the Anniversary Edition. The game itself is AWESOME and I keep coming back to it multiple times a year from when it first launched.\n\nDont buy the Anniversary Edition! You can get the basegame and all DLC cheaper from key retailers. Plus there is no benefit of having the Anniversary Edition. None. Zero. Nada. None of the old issues are fixed. Higher resolution screens still are not properly supported (instead of fixing this, they just cut the option of picking hi', 'Very Positive', 94.88, 14.17, 0.10);
INSERT INTO reviews VALUES (93, 4580, 4579, 'Thank you for giving us ALL of the other Dawn of War expansions even if we had only purchased one a long time ago. That was a pretty cool thing to do.', 'These old strategy games are really good but it seems that if you didn''t grow up with them, getting into them later is pretty hard. I dunno if its something with my game file or what but on vanilla normal difficulty by about 10 turns in all the AI has ultra-fortified bases and will have enemies in your base 3 minutes in every single time, and their armies have vanguards like 8-10 units deep which is seemingly impossible for normal players. \n\nVery regularly games will become unwinnable because by', 'Overwhelmingly Positive', 96.61, 59.75, 443.42);
INSERT INTO reviews VALUES (94, 4700, 15538, 'One of the best Total war games i have finished all factions main campaign also dlcs even if it was released in 2006  this game is still a masterpiece i have 2.300 hours in this game and its enough to understand why i rate this strategy game 10/10 one of the best total war game ever i recommend this game if you are fan of total war games.', 'I wish I could recommend this game but the way the camera controls is atrocious. This is the only game I have ever played where I am just completely turned off by the way it handles with the camera sliding down like it''s on a quarter pipe skate ramp when you zoom in to look at your units. to you not being able to angle the camera to look directly down or up to survey the map.\n\nIf you can get past that then go for it, I cannot. That''s the only area where I will say newer Total wars have genuinely', 'Overwhelmingly Positive', 95.78, 2344.17, 2.18);
INSERT INTO reviews VALUES (95, 4720, 1798, 'Finally, a game that appeals to MY male fantasy (killing crackheads)', 'Great game, fantastic game, if you can get it working. A 20 year old game has no reason to be missing half of it''s entire audio library. Condemned: Criminal Origins has existed on Steam for 20 years and collected revenue as an incomplete product.', 'Very Positive', 87.76, 4.88, 3.43);
INSERT INTO reviews VALUES (96, 4760, 8486, 'My grandpa gave me the demo disk for this game in the mid 2000''s and the rest is history. It''s good.', 'Not Recommended', 'Very Positive', 94.79, 5.83, 2.43);
INSERT INTO reviews VALUES (97, 4770, 460, ' ᠌', 'More like a mixed review.\nThe campaign is really really short and if you know hot to play Rome Total War it is totally a piece of cake without any challenge. After you done one run nothing else is to do.', 'Mostly Positive', 73.04, 86.53, 5.78);
INSERT INTO reviews VALUES (98, 4800, 160, 'An awesome old game. Very nice graphics for the time, still ok today.\n\nI saw people saying lots of crashes...I''ve played the first 5 campaign scenarios and 4 hours without a single crash. I have a low end machine too ... a ryzen 4800h with an rtx 3050 and I''m on windows 11.\n\nVery worth buying still. The only real con for me is that I cannot remap the arrow keys to wasd. Minor nitpick.\n\nEdit: It''s 2 weeks later. Still not a single crash. Whatever problems people were having seems to be gone.', 'This version doesn''t have cinematics enabled in playthrough, and there is a sound glitch that made a loop of what seems like every sound, in any game mode. Despite verifying files and replacing what was corrupt or missing, the sound continues no matter what. Game is fun but not if I can''t enjoy it.', 'Very Positive', 84.38, 23.78, 24.92);
INSERT INTO reviews VALUES (99, 4850, 682, 'This game is still brilliant, it''s almost like an accelerated simulation of a certain phase of our civilization. The nostalgia hits hard with this one. This game is a must have for anyone who loves great RTS in general.', 'After a few sessions of play the game is crashing.\r\nWhen starting the gamei am getting a pop-up message"Display mode 1024x768 not found. Cossacs should not run."\r\n\r\nI can still open the game, but the change resolution option is not availaible. I can play only in 1024x768 mode', 'Very Positive', 87.98, 9.90, 66.70);
INSERT INTO reviews VALUES (100, 4870, 114, 'A classic RTS, its major distinction being the nearly unattainable 8000 unit capacity. Map options are quite versatile, as are the nations to choose from. The one downside is that MOD1, which brings many imporvements, is unavailabe for the Steam version. Nevertheless, Cossacks is an excellent game.', 'game keeps crashing no matter what I do', 'Very Positive', 80.70, 20.42, 90.05);
INSERT INTO reviews VALUES (101, 4880, 179, 'Cossacks: European Wars is Ukrainian Game Developer GSC Game World''s foray into post-Age of Empires warfare (Aoe I was about Classical Antiquity, II ranged from the Dark Ages to the late Medieval Age and III was about the Age of Discovery, i.e. warfare taking place in the 16th and 17th century).\n\nThe best thing about this game is the building set: unlike Age of Empires, EACH civilization possesses its own, unique set of buildings, all of them very detailed and true to their real-life counterpart', 'I cant PLAY WITH MY DAD CUZ YOUR GAME CRASHED ALL THE TIME SO PLEASE FIX IT PLEASE', 'Mostly Positive', 74.86, 15.28, 0.98);
INSERT INTO reviews VALUES (102, 4890, 280, 'I spended, like, more than thousand hours in this game when I was younger. I occupied all Europe, playing in each country, twice.\nI love this game so much as I hate it. This game had a BIG point in my life as a gamer. This is a HISTORY for me.', 'This game is one of the most enjoyable Napoleonic games on steam, however its so full of crashes and barely starts that I would recommend for those seeking to purchase this game to either wait until an update comes in the future to fix the steam issues, or pass over this game. As the user submitted fixes online are almost all broken by now.', 'Mostly Positive', 78.21, 26.08, 21.58);
INSERT INTO reviews VALUES (104, 4920, 5322, 'make natural selection 3 and my life is yours', 'This was the greatest game on the internet between 2012 and 2015, but was taken over by the NSL hackers and server buddies. The community thinks nothing of  feasting on greens. The majority of the players are cheating in some way whether it be wall hacks, aim bots or just general smurfing.\r\nThe game itself is still great but as soon as you get into the community you will quickly uninstall.', 'Very Positive', 85.38, 8.27, 2784.98);
INSERT INTO reviews VALUES (106, 6000, 9428, 'This definitely needs a remaster ASAP. First-person Star Wars squad shooter is underrated.', 'Potentially enjoyable if you''re a huge Star Wars fan that wants to play as a trooper and doesn''t mind very mediocre FPS mechanics. For the rest of us, it is a highly linear and very simplified take on "tactical" shooters. I also didn''t find the guns satisfying to shoot, and I say that as someone who often enjoys old FPS games (like Rainbow Six 3).', 'Overwhelmingly Positive', 95.66, 0.95, 2.43);
INSERT INTO reviews VALUES (107, 6010, 854, 'I LOVE GAME! pure childhood this game can be hard i guess but having played it 100s of times it makes a good afternoon or a chill play.  the pixal art is amazing and with all the tricks they used to make it its been a good 32 years with this game in my life', 'The game is good. However, the quality of this port is questionable. Seeing as the original DOS files are included, you may have a better experience using those with ScummVM, as I have.\nAlso, I really do not recommend getting this here. Disney''s newest ToS is required, and apparently signing those gives Disney a license to get away with whatever they want, including wrongful death.\n', 'Very Positive', 93.56, 34.85, 0.15);
INSERT INTO reviews VALUES (198, 6020, 6978, 'spend 10 bucks and download movie battles 2 mod. you''re welcome', 'Not ideal for modern hardware. Gameplay itself is good, though several cutscenes either freeze up or spawn the player in as if it were a playable mission but makes it incapable of progression unless you use console commands.\n\nNOTE: Some console commands (such as "com_maxfps 30"), downloadable third-party software and running the game as administrator with compatibility mode set to Windows XP Service Pack 3 may remedy these situations for some but I have experienced little to no such luck.', 'Overwhelmingly Positive', 95.74, 85.27, 31.90);
INSERT INTO reviews VALUES (199, 6030, 2625, 'An elegant game from a more civilized age.', 'This is why I never recommend buying things from Steam. Just buy it from GOG. At least GOG games work. Steam games always gives issues and never works.', 'Very Positive', 91.01, 55.42, 25.30);
INSERT INTO reviews VALUES (200, 6040, 713, 'too bad it''s over already. I''ll be brief : this could be my favourite point and click ever, I played most of the classics as MI, indiana jones, Gabriel knight, etc etc but this is the best all around. Mature, coherent plot with concrete characters, amazing OST and very inspired puzzles, designed to make you experience alien technology and get an understanding of their culture. Pretty hard yes, but never unfair. No walkthrough required at any point. Also it played perfectly with 0 issues from sta', 'The game is a gem, but small screen is too small, full screen is bigger than the actual screen so you don''t see may be 1/3 of the screen from the right and bottom edges with a black stripe on the left.', 'Very Positive', 92.15, 16.65, 105.02);
INSERT INTO reviews VALUES (201, 6060, 34286, 'This game is great. I can''t wait for Star Wars Battlefront III. Also looking forward to George Lucas making episode 7 now that he''s done with the prequels.', 'I love this game, but sometimes while playing the screen would turn black and I can''t see sh1t\n\nPlease fix this it''s very annoying', 'Very Positive', 94.92, 65.88, 16.43);
INSERT INTO reviews VALUES (202, 6080, 672, 'I wanna kiss all the girls in my amusement park', 'Doesn''t save automatically. Also doesn''t let me flirt and kiss with someone the same gender as my character.', 'Very Positive', 94.20, 8.58, 10.57);
INSERT INTO reviews VALUES (203, 6090, 194, 'imagine a remaster of this gem', 'Shame I can''t recommend this game, because the cutscenes are really the only thing worth interacting with. Watch them, they''re amazing!\n\nThe game itself is a highly repetitive arcade shooter. How repetitive? Once you''ve played the first mission you''ve pretty much played every mission. No, sorry! There''s also a turret section every 4th level, they''re the boss fights. The game doesn''t really challenge you in different ways, so much as gives you different objectives for the same challenge. Environm', 'Very Positive', 91.75, 5.25, 14.98);
INSERT INTO reviews VALUES (204, 6120, 918, 'It was ahead of its time. It was a Mexican God of war In 2D aesthetic. Made soul efforts In the Xbox arcade in the late 2000''s. It was awesome.', 'I USED TO LOVE THIS GAME.  NOT ANYMORE.  F U C K Y O U EA.  THE CENSORSHIP IS UNACCEPTABLE!! \r\nTHIS IS OUTRAGEOUS.  WHEN I PLAYED THIS GAME I BOUGHT BECAUSE OF THE TARANTINO STYLE THAT IS WHAT MAKES THIS GAME COOL. \r\nNOW YOU JUST CENSORED BECAUSE OF A BUNCH OF WOKE MORONS PIECES OF SHITE!!!\r\n\r\nI TRULY HOPE THIS WOKE GARBAGE NON-SENSE ENDS UP IN THE MOST SAD WAY FOR THOSE WHO PROPAGATE THIS INSANITY!', 'Very Positive', 87.58, 13.05, 9.82);
INSERT INTO reviews VALUES (206, 6200, 977, 'Go to Nexus and download yourself Ghost Master - Complete Edition. And enjoy this masterpiece again', 'Old graphics make this game mostly unplayable', 'Very Positive', 89.87, 24.20, 0.35);
INSERT INTO reviews VALUES (208, 6220, 1369, 'car physics are better than those in most 2024 racing games.', 'Not Recommended', 'Very Positive', 91.45, 0.12, 5.55);
INSERT INTO reviews VALUES (209, 6250, 355, 'This whole series is a good turn based ww2 strat. They''re pretty fun and cheap.', 'Sadly broken as of late, it''s asking for a product key', 'Mostly Positive', 79.44, 1.18, 22.52);
INSERT INTO reviews VALUES (211, 6300, 719, 'https://steamcommunity.com/sharedfiles/filedetails/?id=437731989\nhttps://steamcommunity.com/sharedfiles/filedetails/?id=427609193\nhttps://steamcommunity.com/sharedfiles/filedetails/?id=435260166', 'On the plus side - Dreamfall has mostly wonderful characters and a very good story with one of my favorite settings ever imagined for a video game. The graphics also hold up pretty well for being nearly twenty years old. \n\nBut my friends, it is 2024. We don''t have to do this anymore. We don''t have to pretend that cameras setups and mechanics like this were ever worth slogging through just for a good story. Sure, back in 2006 we didn''t have anything better. Back in that distant and cold past we w', 'Very Positive', 82.34, 15.50, 8.82);
INSERT INTO reviews VALUES (212, 6310, 1275, 'Very much a strong contender for the greatest adventure game ever made.', 'Nice storyline, but it is so buggy.   Messes up Windows monitor settings every time I play it, and you can''t use the quit menu with your mouse, you have to remember to press "Y" whenever you want to leave the game.', 'Very Positive', 89.88, 14.30, 22.35);
INSERT INTO reviews VALUES (214, 6400, 135, 'this game needs a sequel. so underrated. a modern version of this would kick so much ass', 'More frustrating than fun.', 'Very Positive', 90.37, 53.75, 11.08);
INSERT INTO reviews VALUES (215, 6420, 569, 'This is the WAY!\r\n\r\nOne of my all time favorites. I had the original on disc, yes, this game is that old, but also that good. Don''t miss out!', 'Hi there. the game itself is brilliant !!! the gameplay excellent.... BUT the support sucks hard. there is still no fix for the mission "the chance" at professional level. the game still crashes every time at the end of the mission.\n if you sell a product then make it work ! very frustrating ! it is such a pitty .... :(', 'Very Positive', 86.64, 46.77, 8.55);
INSERT INTO reviews VALUES (216, 6510, 765, 'let me play lost planet 2 cowards', 'Played this again after nearly 20 years since release and, boy, does it not hold up. An interesting premise and a handful of cool ideas that are absolutely mired by frankly pointless missions (most of the combat feels gratuitous and, frequently, can be almost entirely run past until the boss fight), dated controls (doubly so their settings), overwhelming knockback that will stunlock you, some miserable boss fights, and a TERRIBLE story. Not even enjoyable bad, just awful to sit through. I finish', 'Mostly Positive', 78.17, 1.13, 7.25);
INSERT INTO reviews VALUES (218, 6800, 1162, 'This was my childhood game, although I cracked it back then. I didn’t dare to play it at the time, just sat and watched my dad play. Back then, I was like his biggest fan. Now I can afford to buy the full version of this game and confidently play it, but unfortunately, he’s no longer here to see it. I bought this game to play again and to keep some memories of my childhood. Dad, I miss you <3', 'i cant play this game even after buy this game .when i open the game it only show just a black screen if anybody knows this please reply to this', 'Very Positive', 90.10, 17.12, 0.18);
INSERT INTO reviews VALUES (219, 6810, 332, 'As the new title (under the name Origins) is being developed and set to release this year, I thought I''d revisit the classics. I didn''t have much success with Destination Berlin as it simply crashed whenever launched, but it was fun checking out the very first episode and its expansion.\n\nBeyond the Call of Duty was released a year after the original Commandos. How many of you remember those times? With expansion packs, not DLCs. Strategy games often had one before the sequel came out. The expans', 'It doesn''t run on modern PCs well and crashes often. Even then, it is really playable on the 800x600 resolution size and if you even try to play it on windowed mode to accommodate this limitation, the game freezes and becomes unplayable.', 'Very Positive', 86.75, 1.05, 5.03);
INSERT INTO reviews VALUES (220, 6830, 914, 'If you are planning to buy these 2 games: Commandos 2: Men of Courage & Commandos 3: Destination Berlin, I have some advice for you. If you buy it as a memory of your childhood, it is okay. This game is also my childhood. But if you buy it to play, you should consider carefully because you will encounter some problems if your computer is using Windows 10/11.', 'when i had windows 10 on my PC it would run no problem .now updated to windows 11 it will not run even using all the fixes provided by the community to run. whats a waste i cannot play one of my favorite games again', 'Very Positive', 82.82, 24.15, 4.33);
INSERT INTO reviews VALUES (221, 6840, 322, 'thats what a nazi would say', 'After Commandos 1 and 2 this one is just a ridiculous joke', 'Mixed', 53.11, 10.62, 1.03);
INSERT INTO reviews VALUES (222, 6850, 1528, 'The most unrealistic part of this game is the fact that Russian civilians run to the guards after seeing a man in a suit carrying a sniper rifle.', 'It requires hours of trial and error to make it work on a modern machine. Don''t buy it.', 'Mostly Positive', 79.45, 103.88, 14.53);
INSERT INTO reviews VALUES (223, 6860, 5891, 'This game was next level for it''s time, but playing this after being grown up, i realize there are tons of weirdly sexual stuff in this game. The entire development team was feeling freaky that year.', 'Its clear that Hitman: Blood Money is a fan favourite and a bit of a all-time classic, so it pains me to say I can not recommend it. It runs well, looks fine and has some incredibly well made levels that allow players to explore and discover a wealth of assassination options that are available to them. Sadly, it is a real pain to control. After 5 hours of trying to get to grips with the mouse & keyboard controls and the context sensitive button prompts, I gave in to frustration and brought my ti', 'Very Positive', 94.21, 11.70, 5.75);
INSERT INTO reviews VALUES (224, 6870, 429, 'This game was very good, and i wish that they would focus on making a new game in that same setting, with new missions and better grafics', 'I want to start by mentioning that I loved Battlestations and still do, however it did not age well, I played it in the 360 which was a mostly smooth experience, but same cannot be said for this. Its not really the fault of the devs, its just an old game, so you need to do many work arounds to get the game running the way you want it, controls are weird, and to get the controls working on a controller its a pain, and even then it does not work normally, the controller binding is weird and the au', 'Mostly Positive', 78.09, 7.22, 1.83);
INSERT INTO reviews VALUES (225, 6880, 1836, 'We can''t judge a 2005 game with 2025 standards. \nActually, it was pretty fun at that time.', 'unrealistic the CIA would never support a Socialist revolution', 'Mixed', 62.64, 11.18, 10.10);
INSERT INTO reviews VALUES (226, 6900, 1651, 'First of all, only play this game if you consider yourself incredibly patient. You cannot save midlevel and you are going to have to watch the same cutscenes, shoot the same people, sneak around the same hallways, etc. over and over again. This game is also extremely bad at signposting / telegraphing. There are moments where it feels like the game goes out of its way to teach you that you cannot do something that you actually can. Some of the levels I thought were most difficult became incredibl', 'It''s unplayable garbage and is not optimized for PC.', 'Mixed', 64.45, 17.47, 0.42);
INSERT INTO reviews VALUES (227, 6910, 9753, 'By the way, Denton, stay out of the ladies restroom. That kind of activity embarasses the Agency more than it does you.', 'This game is listed as having full controller support, which was a major factor in deciding to buy it.\nThe game does not support a controller.', 'Overwhelmingly Positive', 95.45, 5.52, 0.10);
INSERT INTO reviews VALUES (228, 6920, 1458, 'Deus Ex: Invisible War is an immersive sim that blends RPG and FPS mechanics, offering players multiple ways to tackle missions.\nThe ability to choose between a male and female protagonist was quite impressive for a game released in 2003.\nGameplay variety is excellent, allowing both stealth and direct combat approaches.\nHowever, enemy AI is weak, and the game suffers from noticeable graphical issues. \nThe universal ammo system, combined with more bugs and a less engaging story, makes this game w', 'Amazing experience - was able to remind myself how to close down NVIDIA Shadowplay, Steam Overlay, set single core, set up different compatibility modes (INCLUDING Win 98 OMG THAT WAS a NOSTALGIC MOMENT Y''ALL!!!!); \nAlso, realized how cool to Google around and download different mods, patches, and fixes all across GitHub and the internet - literally felt like a true JC Denton hacker!\n\nOw, what about the game? Sorry, completely forgot to mention - It''s just doesn''t work after character creation. ', 'Mixed', 58.92, 11.48, 0.55);
INSERT INTO reviews VALUES (229, 6980, 1479, '“Float like a butterfly, sting like a bee.” -Muhammad Ali\n"Pff, hold my beer", - said Garrett and fell asleep with the guard. Because even thieves want to sleep', 'I cant get passed the training part because i cant get the lock pick I am so frustrated with it', 'Very Positive', 80.87, 2.38, 10.48);
INSERT INTO reviews VALUES (230, 7000, 1934, 'Goated game prob my favorite in the trilogy all the levels are different paced and have a different vibe to them also i became forklift certified', 'Didn''t age well, and what is this character design? Come on!', 'Very Positive', 86.45, 2.27, 12.87);
INSERT INTO reviews VALUES (231, 7010, 351, 'Has a problem with crashing but theres some workarounds that help, fantastic game as a kid and a great game now as an adult. Recommend it to anyone into older games', 'Gmanlives said it was good so I bought and beat it years ago. It''s trash. Don''t let the "lost Deus Ex game" comments fool you.', 'Mostly Positive', 73.50, 19.13, 7.62);
INSERT INTO reviews VALUES (232, 7020, 244, 'Can''t believe how much I enjoyed this game, I thought that the nostalgia made me remember this game being good but I''m happy to say that even now it was a blast to play.\nStrongly recommend.', 'The game does not recognise my Xbox 360 controller and the keyboard option does not work either so it is rubbish! I want a refund please!', 'Overwhelmingly Positive', 95.08, 5.58, 0.12);
INSERT INTO reviews VALUES (233, 7110, 1454, 'Jade Empire showcases early Bioware at its absolute best. The immersive world, clever and impactful story and memorable characters are why it''s one of my favourite RPGs. The two paths your character can take makes replayability enjoyable as well.', 'It''s pretty shocking that this game is being sold on Steam. I''ve spent hours trying to get it to work, since I loved the original and never got to finish it. Steam doesn''t take any responsibility for fixing this game, so you''re on your own or get a refund. Once every year or so, I spend another afternoon trawling the web trying to look for fixes, but probably I''ll just refund it eventually.', 'Mostly Positive', 74.55, 29.90, 0.18);
INSERT INTO reviews VALUES (234, 7200, 1366, 'I''ve been playing this game for 13 years, still can''t get A-01 author time 10/10', 'Would be a 10/10 game if not for Ubisoft!    F*** Ubisoft!', 'Overwhelmingly Positive', 95.10, 193.95, 2.38);
INSERT INTO reviews VALUES (235, 7210, 276, 'Competent classic point-and-click adventure with (although not original) for video game standards well fleshed out writing. Genre-classic pixel hunting and a number of instances of repeating the same action on the same object at different times for different results may annoy. \n\nLong-ish. 12 hours would be fast; 20 not very slow. At currently 2,99€ for the five game Pendulo adventure pack it''s a steal.', 'Many crucial items blend with environment and/or are too small to see.\nA lot of points can be interacted with only if some mandatory trigger happened.\nAlso, several nonsensical solutions.\n\nAll this makes the game far from the brightest star in the point-and-click genre.\nThe game is dirt cheap on sale if you want it, but I would rather recommend watching it on youtube.', 'Mixed', 66.30, 23.70, 7.90);
INSERT INTO reviews VALUES (236, 7220, 115, 'A mild thumbs up, only to see what happens next in the series. I live for the peanut butter puzzle in the first game, and this game does have the invention puzzle I love, but as a whole there are just less goofy and weird stuff that made the first one so charming. Also the story and characters are just not good.', 'Recommended as part of the Runaway trilogy, well, sure, I guess, but I have a hard time recommending this by itself. This game combines all the flaws of Runaway: A Road Adventure (pixel hunting, and to be repeated same interactions most of all) with none of its redeeming qualities; protagonist has gone from nice-guy to bro-doofus; every other character is seemingly (also) used as an irritant alone. The writing is all over the place, and with the game ending on a true low note.\n\nFirst point-and-c', 'Mixed', 48.70, 9.50, 29.78);
INSERT INTO reviews VALUES (239, 7510, 532, 'I played this back when it could be found on Xbox 360. I enjoyed it back then however I will admit that the fighting is lacking in some areas but if you really try hard and learn to use the spells in mid-air you can run through the pro difficulty barely using the healing pause menu option. I played through it twice scoring both endings and I would recommend it to anyone that wants a simple story with no side quest to get in the way.', 'Sure, there''s a lot of booty in this game, but have you considered that the game itself *is* booty? \r\n\r\nBut really though, this is one of the worst things I''ve played in a while.', 'Mixed', 52.82, 10.98, 2.10);
INSERT INTO reviews VALUES (240, 7520, 2091, 'it feels like if you described elder scrolls to a blind guy and you put him infront of a computer and told him to make that game. 2', 'I don''t recommend this game unless you love pain and trash ass games like I do. There''s something charming about the poop feeling of this game. Everything is jank and wrong, but I still play this pile of crap from time to time. I would love to talk to the devs and pick their brain. I bet they do a lot of drugs', 'Mixed', 54.42, 38.32, 17.23);
INSERT INTO reviews VALUES (241, 7530, 123, 'I really enjoyed this game i got for 90%. Along with the whole Two Wolrds collection for under $10. I DO NOT recommend buying at full price as the game lacks proper content and detail. It''s pretty much a slap together tower defence that give you something to do while downloading another game. If yu get the coupon then get it but It''s not worth it to pay full price.', 'Some reason I can only play the demo', 'Mostly Negative', 38.21, 4.92, 0.35);
INSERT INTO reviews VALUES (242, 7600, 1688, 'Really great!!! Recommended for fans of the Civ series. Has a similar feel - very addictive and very fun.\nHowever, I think the average person would enjoy this. Playing with AI and watching everone''s railroad grow and create a web is incredible!\n\nAs for other reviewers talking about the crashing - There''s a guy under the guides for this game that has a simple patch for this game - all you have to do is change two digits of the code. It''s super easy, works great, and you don''t have to use some ran', 'While the game is great, it is completely unstable.  No meaningful effort has been made to get this game stable.  It should have never been listed on Steam if no one was willing to patch this game.  It is not just on modern hardware,  This game has had the same crashing issues for 20 years when I bought the CD version and ran it on a Pentium 4 system.  The game still crashes in the same manner it did back then.\n\nThe game is too unstable to be enjoyable.  You just never know which track or statio', 'Mostly Positive', 71.27, 19.12, 2.68);
INSERT INTO reviews VALUES (243, 7670, 12298, 'After all these years of Bioshock being released, it is still a wonderful classic that needs to be experienced to the highest degree by anyone. The story is well-crafted, the mechanics are addicting, and the ambience and sound effects are beyond the time that it was created for, and still is even to this day. I can not express this enough, do yourself a favor, and would you kindly buy this game?', 'Unnecessary blasphemy\nI will never understand the western belief that all scripts must contain a character saying Jesus Christ like it''s a curse word.\nThere are thousands of video games and movies and television show in other countries that can go without doing that once.\nIs it contractual? Is it an obligation? It is so unnecessary.', 'Very Positive', 93.38, 26.72, 10.32);
INSERT INTO reviews VALUES (244, 7800, 866, 'The history behind this game is so bizarre. Co-founder of Budgie and Head of Halo: Combat Evolved makes his own studio, Wideload Games, as an experiment to see how being the head of an indie game dev studio would be. The goal in mind with the studio was to create conservatively-budgeted game titles that would sell well in the games market; Stubbs was the game that would test that premise. Only 12 employees actually worked on the main components of this game, while the Boss would hire up to sixty', 'There is a lot of charm in this game but it''s a chore to play in the later levels where you are getting one shot with pinpoint accuracy by tanks and rpgs and then getting sent back 5 - 10 minutes to attempt to cheese it or get lucky again.\nPlay until the police station dance contest as it''s the clear highlight of the game and just goes downhill from there.', 'Very Positive', 90.76, 9.67, 5.62);
INSERT INTO reviews VALUES (245, 7830, 1200, 'One time, when I was a kid around 2008, I decided to play this game for a bit before heading to school. I got so entranced by it that I only realized the time about 3 hours after I was meant to be at school. I was 8 at the time, panicked completely and almost cried from the failure on my part. It was the first and last time I was really late for school.\n\nI found the game on steam a month ago, and I''ve once again been hooked again. A few days ago, I had a test that I had to sleep for, and I got s', 'Worst controls ever experienced in a video game', 'Very Positive', 86.50, 32.30, 5.03);
INSERT INTO reviews VALUES (247, 7860, 530, 'Amnesia: The Bunker if it was good', 'If you''re able to get it working, then pretty unique atmosphere and good boomer shooter mechanics. Wasn''t able to make it more than 5 minutes through first level even with community patches applied. Most of my playtime was spent trying to fix. Until somebody can figure out how to get this thing working right on modern systems, not worth it even on sale.', 'Mostly Positive', 70.00, 1.43, 1.27);
INSERT INTO reviews VALUES (248, 7940, 10117, 'Ppl are still playing online. CoD4 classic is better than most of latest shooters lol', '50,000 players used to game here, now its a ghost town.', 'Very Positive', 92.13, 0.65, 26.50);
INSERT INTO reviews VALUES (249, 8000, 2451, ' Took me about 15 hours or so to complete very good game for its age lots of bugs that I had to work around but overall was enjoyable and challenged the few brain cells I have left. Shoot gorilla puzzle puzzle puzzle shoot person puzzle puzzle puzzle shoot bear puzzle puzzle puzzle', 'Your brains will be raped.', 'Very Positive', 80.17, 20.87, 0.27);
INSERT INTO reviews VALUES (250, 8080, 946, 'I wish the Kane & Lynch series would make a comeback someday!', 'I heard this game blows. I wouldn''t know though because i cant get it to even launch.', 'Mixed', 58.35, 7.13, 0.67);
INSERT INTO reviews VALUES (251, 8100, 169, 'It is a dumb old-school shooter with dumb over-the-top voice lines and action with very dumb AI. So don''t expect much just turn off your mind and enjoy the dumb shooting.\n\nOh I had to turn off the microphone in windows because no sound on my headset without it. Wierd, but this is an old game, this is just a small hickup', 'Why are completely broken games still allowed to be sold? Any settings but the lowest ones give me black screen and every time I get hit by an enemy the game stops for 1 to ~6 seconds.', 'Mixed', 41.42, 3.75, 0.10);
INSERT INTO reviews VALUES (252, 8140, 1991, 'I was 14 when this game was released. It was the first video game i bought myself with my own worked for money.\nThe story behind this game. The graphics behind it, its all absolutely amazing. This game finish up the Legends trilogy of Lara Croft (Anniversaries, Legends, Underworld) and is a perfect finish to what a Tomb Raider game was originally meant to be.', 'Unplayable because in the second level the dice that are supposed\nto be placed on platforms as weights suddenly fly across the room. So you don''t get any further.', 'Mostly Positive', 74.13, 1.35, 0.42);
INSERT INTO reviews VALUES (253, 8170, 1202, 'for anyone trying to play this in 2025 and beyond, try going into your game files for the install location and deleting the file labelled as:\r\nxlive.dll\r\n\r\ni did this and it allowed me to play the game\r\n\r\nif doing only that doesn''t work, you might need a Games For Windows Live Client downloaded, which you can google search for a Zip for that.', 'Since  this has been taken off the store im guessing they aren''t going to fix a major issue which does not let you play the game on windows 10/11\n', 'Mixed', 67.55, 5.35, 0.32);
INSERT INTO reviews VALUES (254, 8190, 18574, 'One of my favorite games of all time. The main story and the side missions are great, but the ability to just leave and do whatever you want cannot be understated. There''s nothing like the sheer amount of joy and the feeling of freedom I get when I do something crazy like sneak onto a military base to steal a plane, fly across the entire map shooting at everything I see, and then crash the plane into an oil rig (parachuting out at the last second, of course).', 'Played the game and it was crashing every 10 minutes. Re Installed it and now game won''t launch no matter what i do. Stuck on updating executable\n\nEdit: Fixed this by downloading a patched executable. But this is ridiculous...how you pay for a game and can''t even play it properly. So  i will keep my review as negative', 'Very Positive', 91.54, 21.48, 5.00);
INSERT INTO reviews VALUES (257, 8330, 132, 'grandma kept sucking me dry, taunting me in the process', 'It''s a damn tragedy that Poker Night 1 and 2 are now delisted, and this crap is the only Telltale poker game you can purchase. Barely any funny conversations, animations are stiff as fuck, atmosphere is horrible. I get that this was Telltale''s first game and this was a crucial stepping stone for them to later achieve greatness, but it''s really not worth it even for less than a quid.', 'Mostly Positive', 79.55, 3.52, 0.15);
INSERT INTO reviews VALUES (258, 8400, 789, 'This game is PURE fun on a level that few games ever achieve. It is truly the definitive standard of twin stick shooters. I would personally rank it on the same level of arcade masterpiece as Tetris or Breakout. The only flaw I can point to is the sense of tilt when losing a life. You may go five minutes in a round without dying, but once you do, it seems guaranteed that you will die again in the next 30 seconds and your score multiplier will struggle to regain momentum. This could very well jus', 'The game would be timeless.  Unfortunately time has rendered it unplayable on either of my two modern gaming rigs.  CTD on one and just a black screen on the other.  What a shame.  I really loved this game.', 'Very Positive', 91.38, 29.42, 2.85);
INSERT INTO reviews VALUES (259, 8500, 5193, 'Relaxing. Soothing. I hang out in high security areas just mining and meditating. I know there is more to this game but I am getting what I need from it right now, this way!', 'Game is fun but ends up being a second job at some point if you want to do anything great. Used to play back when you could be wardecked without structures. Now they need a structure but you still have the gate gankers killing you all the time. I was playing just for the industry/mining and pve. Game will throw you into pvp even if you don''t want to. \nWith the new updates you cant build or mine anything good without going into low or null sec. High sec (PVE Zone but not really) is pointless.\nCam', 'Mostly Positive', 78.84, 379.88, 381.60);
INSERT INTO reviews VALUES (260, 8600, 523, 'The game rocks in 2024,with a bit googling it runs amazing and few mods easy to get you will enjoy,i own all SimBin racing sims and often run them one after the other,RACE 07 has the best career mode and for its age looks great and feels amazing,very complete game,get it costs as much as a coffee and a croissant at a cheap cafe,the tires loosing grip sound will get you hooked', 'i cant load the game i got riped off\n', 'Very Positive', 90.63, 2.62, 0.40);
INSERT INTO reviews VALUES (262, 8790, 139, 'One of the best sims ever created. And for the 2 euro price or whatever it goes for on sales, it''s quite frankly a steal.\nThe base game without mods is a 10/10, you can mod it to make it an 11/10 game.\n\nA timeless gem.', 'Absolute gem but difficult to keep it working on win10', 'Very Positive', 92.09, 8.70, 1.85);
INSERT INTO reviews VALUES (263, 8800, 2595, 'Civilization IV is honestly the greatest civilization to exist out of all of them. I only stopped playing it because I felt like I had to play the newer CIV versions. \n\nBtS expansion without a doubt is how Sid Meier originally conceptualized and is his Magnum Opus. Doom Stacks, Leonard Nimoy technology discovery narration, baba freaking yetu is the CIV IV theme song!!!!!!! So much customization in this game makes the newer versions feel so empty and lackluster. Religion was actually cool in this', 'Some of the most badly programmed cheating AI I have ever witnessed in gaming. This is the weakest point of the series until VI.', 'Overwhelmingly Positive', 96.72, 8.98, 310.28);
INSERT INTO reviews VALUES (264, 8850, 5683, 'BioShock 2: Ah yes, the sequel nobody asked for but we all secretly played anyway. Because who doesn’t want to experience the joys of underwater single parenting while being constantly harassed by philosophy majors on bath salts? Truly the dream.', 'Have just finished BS1; a fantastic and totally worthwhile game. \n\nSadly, BS2 does not run reliably at all, I have crashed 7 times within the first 30 mins of the game. Various fixes have been posted over the years, and some have helped but I still crash every 10 minutes or so. \n\nSuch a shame. And it shouldn''t be sold in this state.', 'Very Positive', 87.37, 44.67, 20.27);
INSERT INTO reviews VALUES (265, 8870, 45903, ' How to skip 2K launcher \nType   "BioShockInfinite" -run %command%        in Steam launch options :)\n', 'Why did you add the 2k launcher and sign in for a 10 year old single player game...', 'Very Positive', 91.32, 11.15, 1.98);
INSERT INTO reviews VALUES (266, 8930, 76133, 'After playing Civ 7 for a bit, it made me further appreciate Civ 5 with the Vox Populi mod as the best in the series by far. \n\nA shame how Civ 7 is a regression in many aspects from Civ 5, a game released 15 years ago....', 'A great game, but currently unplayable due to a recent update. DO NOT BUY IT until they''ve fixed it. \n\nWhy it''s not off the shelves is beyond me', 'Overwhelmingly Positive', 95.57, 914.90, 2243.22);
INSERT INTO reviews VALUES (268, 9010, 3836, 'This, along with the recent mod "RealRTCW 5.0, which upgrades the game to far better graphics, and that''s just the start. Probably the best Wolfenstein game! I play at 4K, 120hz and it''s just so good to play an old gem! Buy it now!', 'You play on the wrong team', 'Very Positive', 91.71, 8.17, 0.78);
INSERT INTO reviews VALUES (269, 9050, 4076, 'This game is a gem.\r\n\r\nSome people hate on it because it didn''t stay "true" to the originals. But most people love it for what it proposed and delivered.\r\n\r\nIn any case, I love the originals, love 2016 and Eternal as well. \r\n\r\nBUT I WOULD ALSO LOVE A NEW DOOM TAKE LIKE THIS ONE.', 'Its like if you made a level for a game, and then made the same level for the next mission, and then made the same level for the next mission,  and then made the same level for the next mission,  and then made the same level for the next mission,  and then made the same level for the next mission,  and then made the same level for the next mission,  and then made the same level for the next mission,  and then made the same level for the next mission,  and then made the same level for the next mi', 'Very Positive', 89.35, 15.17, 9.02);
INSERT INTO reviews VALUES (270, 9060, 374, 'Another great dark fantasy classic from the boomer shooter era. Each class changes up the play through quite a bit so  you can easily get a lot of fun out of it. Some of the maps can get quite confusing so you may want to look up a solid walk through ahead of time!', 'Very tedious and a pain to run properly.', 'Mostly Positive', 76.74, 10.05, 5.88);
INSERT INTO reviews VALUES (271, 9180, 1022, 'Best game of my childhood', 'SCORE: 5/10 - MEDIOCRE\nI remember being amused by these goofy-looking but ruthlessly challenging Commander Keen games as a kid, and was hoping to indulge myself in some quality gaming nostalgia. Unfortunately, this product is just a lazy DOSBox port with blurry graphics and an awkward user interface. In recent years, other classic id Software games like DOOM and Quake received revisions to make them better adapted for modern computers. To make my recommendation, this product requires a revision ', 'Very Positive', 93.35, 3.95, 2.23);
INSERT INTO reviews VALUES (272, 9200, 6433, 'It''s flawed, but it''s also underrated as f**k. Had it come from a different developer, this would have been all the... Rage.\n\n...I''ll show myself out.', 'The game is interesting for maybe 5 hours, but it one of those red-screen-health games where you spend half the game hiding behind cover. The entire thing is uninspired and boring. John Goodman is here for some reason. The combat sucks, racing is eh at best, level design is good for two levels then just repeats forever, story is eh, world is eh.', 'Mostly Positive', 73.34, 21.72, 27.63);
INSERT INTO reviews VALUES (273, 9219, 6433, 'It''s flawed, but it''s also underrated as f**k. Had it come from a different developer, this would have been all the... Rage.\n\n...I''ll show myself out.', 'The game is interesting for maybe 5 hours, but it one of those red-screen-health games where you spend half the game hiding behind cover. The entire thing is uninspired and boring. John Goodman is here for some reason. The combat sucks, racing is eh at best, level design is good for two levels then just repeats forever, story is eh, world is eh.', 'Mostly Positive', 73.34, 21.72, 27.63);
INSERT INTO reviews VALUES (274, 9310, 1076, 'My pronouns before DOW~WA: He/Him\r\n\r\nMy pronouns after: Guards/Men', 'Love the lore of this game but gameplay-wise, the units path-finding is absolute GARBAGE borderline unplayable. Some of the missions are just bad, specially mission 4, is just dumb.\n\nWord of advice, if you plan to get this game, play in "normal" or "easy" difficulty because "hard" is just unplayable. Units are just stupid as shit! they sometimes literally go left when you told them to go right, exacly the opposite of what your commanding them to do. \n\nHorrid unit path-finding along with multiple', 'Very Positive', 87.27, 15.28, 24.02);
INSERT INTO reviews VALUES (275, 9340, 435, 'Best RTS of its generation. I have played more hours than shown on this STEAM review. If you like RTS, this is the one. COH2 is good as well, not as good as COH1 and derivatives. Have not played COH3 yet.', 'Doesn''t work with Windows 11', 'Very Positive', 90.34, 60.70, 34.43);
INSERT INTO reviews VALUES (276, 9350, 1165, 'Still holds up today and is an excellent example of how wonderful RTS games were before companies focused the genre around competitive game play, and pushing out casual players.', 'For being an RTS game, the actual unit AI does *NOT* hold up. You will not be able to do formations, you will not be able to move units competently across the battle field. Troops will relentlessly slam into each other which creates a massive traffic jam, with the only solution being to micro-mange your entire army. This singular, but massive flaw has completely turned me off from playing this game.', 'Very Positive', 88.24, 46.27, 2.53);
INSERT INTO reviews VALUES (277, 9420, 5545, 'Game was released in 2007. 17 years later still has working networking code, dual monitor support and runs on monitors whose resolution and aspect ratio had yet to be imagined.\nStill Good fun', 'The game it self is great, but the only active community is FAF, and they''re ran by racists and nazis. The mods openly abuse their powers and nothing is done about it. They allow racism openly, it''s messed up in this era.', 'Overwhelmingly Positive', 96.50, 40.45, 3063.15);
INSERT INTO reviews VALUES (278, 9450, 7664, 'if this game get a reforged version with updated grafic and other new things from Redux Mod or others, this would be the best rts game', 'RTS reddit slop. Only good RTS was Warcraft III. Stay away from everything else that devolves into ridiculous high APM ADHD. This game barely runs on modern systems too, and the mods that are the ''definitive'' experience bricked the game when I tried them. The 40k setting is a dogshit wannabe MCU reddit fest and every 40k game is hot garbage.', 'Overwhelmingly Positive', 95.04, 68.37, 0.17);
INSERT INTO reviews VALUES (279, 9460, 423, 'bought this game to relive my childhood, spend two sittings and two cups of tea to finish the entire game because i remember everything like the back of my neck (i have no idea what i am talking about)\n\nnot the best game in terms of gameplay and mechanics, but has an amazing soundtrack and sound design (i love you whoever made the sounds for both the M1B and blackbear''s gun + autoloader) and is the only game i know that has a stage where you fight tanks under an ongoing nuclear strike\n\n5/10 over', 'Since apparently the multiplayer is shut down you would only be considering buying this for the campaign and I''m here to tell you DON''T.\n\nI bought this for $5 for the nostalgia and even that couldn''t save the campaign experience. The story is about as generic as a military shooter could possibly get. The writing is pretty bad, the gun play has not aged well, the missions are super cliche and boring, enemies are braindead, your allies are braindead, terrible enemy spawns sometimes up your ass, an', 'Mixed', 66.90, 10.03, 3.60);
INSERT INTO reviews VALUES (280, 9480, 7792, 'Without patches the game runs terribly, the Steam version is even worse because the .exe file hasn''t been updated like the GoG version. That being said with patches the game runs a lot better and is playable at 60+fps. Download the Juiced patch, Gentleman''s of the Row patch, and make sure to get the GoG .exe file and you''ll have an absolute blast! The videos linked below have the files and the patches needed!\n\nhttps://www.youtube.com/watch?v=IoCWxAdc5gc\nhttps://www.youtube.com/watch?v=0c7vg0y8IV', 'It''s absolutely disgusting how this game has been treated, but also what they did to the man who was actively attempting to fix it. For those unaware; There was a man that was actively working on fixing the game, who was dying of cancer, and his only wish was to fix the game. They promised him that they would finish the project after his death, but rather than do what they promised, as soon as he passed, they canceled the project. \nAbsolute fucking scum bags. DO NOT support this shit ball compan', 'Mostly Positive', 74.22, 10.55, 1.45);
INSERT INTO reviews VALUES (281, 9500, 155, 'game is better than sex', 'The 15th anniversary update broke this game, and there''s no sign they''re fixing it. No achievements, no level editor, nothing but a faster "improved" version of the story (easy mode only). Go into the beta branches and enable the old version if you want most of the features.', 'Mixed', 61.94, 11.80, 4.92);
INSERT INTO reviews VALUES (283, 9730, 135, 'It is a little laggy but considering that the game is 18 years old that is to be expected. Fun game!', 'The game is unplayable on win11 due to constant crashes. Hotfixing it with online tutorials doesn''t work on modern hardware.', 'Mostly Negative', 39.26, 53.87, 4.13);
INSERT INTO reviews VALUES (284, 9760, 198, 'One of the best RTS out there even after 21 years.\r\nModern warfare at its best - balanced, challenging and still looks great', 'I liked the game very much back in the day it was released so I bought 2 copies on Steam since the game seems to have LAN multiplayer to play with my friend. We used Hamachi and wanted to play... but apparently LAN dosent work in this game as we didnt see each other in LAN game list. Suffice to say I wasted money on this and I cannot recommend it, seeing how they managed to broke such a simple thing as LAN functionality in a game whose normal boxed version has normal working LAN MP\n\nSMALL UPDATE', 'Mostly Positive', 78.28, 77.13, 16.60);
INSERT INTO reviews VALUES (285, 9800, 298, 'Hitman 2 but the enemies can throw grenades and you have less health, incredible', 'Stealth so realistic, you’ll fail missions for sneezing in the same province as a guard. Good luck figuring out what you did wrong, the game sure won’t tell you just like the convoluted guides to get the game to actually work. Imagine Hitman if he graduated from the School of Stiff Animations, had no budget, and used cardboard for disguises and yet still somehow managed to better than the hitman games.', 'Mostly Positive', 70.47, 14.75, 16.12);
INSERT INTO reviews VALUES (287, 9880, 160, 'Knife dad is love, knife dad is life', 'Purchased the full game for 60 bucks and all my characters are gone years later.', 'Mixed', 55.00, 2.33, 56.12);
INSERT INTO reviews VALUES (288, 9900, 829, 'If you are a fan of Star Trek, then this game is worth trying. Make sure to set the resolution sliders to max, and it can look pretty good, even today. The missions are fun, and the community is helpful.', 'Ground combat is total butt. The monetization is total butt. The progression is total butt and based around that total butt monetization. They add more paid content instead of fixing existing bugs. Just move on to anything else.', 'Mostly Positive', 76.00, 612.37, 96.63);
INSERT INTO reviews VALUES (289, 9940, 591, 'Good character writing and entertaining jokes.\nKit Ballard is a great protagonist but this game was very small, it would be nice to see a sequel that is an action adventure open world game like the old Ty games. Get on it Krome.\nWe''ll probably never get another game but if you like the Ty series then you should like this game too.', 'I''ve never had any game, let alone a 2.5D platformer, give me motion sickness before, but somehow this game has managed to do that. I think the camera moves and bounces around way too fast in order to follow Kit. Enemies also have the ability to combo you and you cannot counter until the attack animation is over, and by that time you''re dead. Really kills the fluidity of what is supposed to be a fast paced game.', 'Very Positive', 81.73, 10.75, 2.67);
INSERT INTO reviews VALUES (293, 10090, 31975, 'No anime and celebrity character skins, no 20 dollar weapon blueprints that turn your gun into a dragon. Just a gritty, bleak, and brutal WW2 shooter.\r\n\r\nCall of Duty needs to start taking itself seriously again.', 'Why is this game so expensive in 2024', 'Very Positive', 92.42, 18.53, 62.48);
INSERT INTO reviews VALUES (294, 10100, 246, 'You played KQ in your youth? Let''s be friends.', 'Love this game for it''s sentimental value. That being said, if you never played this game and have no idea what it is, do not touch it. You need FBI/CIA level of investigative powers to finish this game. It''s quite crazy.', 'Very Positive', 86.59, 195.22, 7.62);
INSERT INTO reviews VALUES (295, 10110, 249, 'I played the first Space Quest when it came out when I was 9 years old. Adventure games like these are no longer made, but the 80s and 90s were the golden years of adventure gaming. Exploring, learning to use collected items for ingenious, devious, and sometimes downright silly outcomes was part of the joy. Part of the fun of these games was finding all the ridiculous ways you could die in a sci fi setting and seeing what the hilarious developers had to say about your failures. If you''re into co', 'Terrible.  1-3 are an absolute waste of time. 4 was a decent idea, but largely just full of Boomer nerd programmer humor. 5 has music that wants you to shove a screwdriver through your ear and out the other. Just watch the playthroughs on 2x speed and you''re good.  They''re short games...unless you want to try and figure out the most frustrating mess of typing and even knowing what''s on the screen.  6 I have yet to watch the playthrough...but I doubt I will bother updating this considering these ', 'Very Positive', 85.14, 20.43, 0.23);
INSERT INTO reviews VALUES (297, 10130, 556, 'https://steamcommunity.com/sharedfiles/filedetails/?id=677767622\nhttps://steamcommunity.com/sharedfiles/filedetails/?id=678608163\nhttps://steamcommunity.com/sharedfiles/filedetails/?id=602874837', 'Why is Valve selling broken games on their platform?\nThx for the clown <3', 'Mostly Positive', 76.62, 4.97, 0.08);
INSERT INTO reviews VALUES (299, 10150, 4520, 'In the year of our Lord 2024, gaming is in serious need of "power trip" games and since you can''t buy Spider-man: Web of Shadows, X-Men Origins: Wolverine, or Infamous anywhere on PC, Prototype is your only choice. As far as choices go it''s really great even 15 years later. I have fond memories spreading havoc in New York and booting up the game today felt exactly the same. Well, bad controls aside that is. It has some frustrating elements, that''s for sure, but you get used to them really quickl', 'Game doesn''t run at all on modern systems. Keeps crashing, don''t buy.', 'Mostly Positive', 75.38, 12.80, 0.10);
INSERT INTO reviews VALUES (300, 10180, 15819, '1. Open the game\r\n2. Admire my childhood\r\n3. Help Afghans with training\r\n4. Shoot that old wrinkly fuck in his head 12 times for each year that passed after seeing ghost killed\r\n5. Beat the Campaign\r\n6. Load into Museum\r\n7. Shoot the same old wrinkly fuck with every gun i can.', 'Activision took down a non-profit passion project mod to remaster Modern Warfare 2 that required you to purchase Modern Warfare remastered. Don''t support them. Don''t buy this game.', 'Very Positive', 91.15, 13.10, 0.58);
INSERT INTO reviews VALUES (301, 10190, 4099, 'played\r\nhard r''d by a kid who i killed\r\ngot to nuke the kid\r\nhe cried and called me many slurs\r\nyou can be a communist\r\nyou can plant bombs at an airport\r\n10/10', 'A huge waste of time.\nCOD MW2 Multiplayer means, trying to play with players who have been playing this game non-stop for 20 years on sh*tty maps\nand even alt-tab doesn''t work', 'Very Positive', 90.07, 17.12, 27.50);
INSERT INTO reviews VALUES (302, 10220, 1885, 'WARNING: THIS GAME DOES NOT EXIST. DO NOT BUY IT.', 'I regret everything', 'Mostly Negative', 38.99, 1.68, 2.30);
INSERT INTO reviews VALUES (307, 10270, 329, 'If you have never played a Disciples game, I recommend playing 2 first (Gallean''s Return or Rise of the Elves are both great). This game is amazing and oozes style and atmosphere, however it is not as tightly designed as 2 and is the inferior game (though I still love it).', 'I see that creators of this game never ever finished entire campaing! Human story - mission 1 - it got 2 buildings full whit end game monsters! Even at maxed 17 level basic units i cant kill them! I wasted soo much time trying... Some secondary mission cant be completed, some npc are gone. Some shops wont work, coz shopkeeper is agressive and immortal at the same time, simply refuse to die... Lots of the research spells are moronic, like Undead - reduce resistance vs air... Rogues are nerfed to ', 'Mixed', 56.23, 8.67, 102.63);
INSERT INTO reviews VALUES (309, 10500, 11401, 'Get the Empire2 mod and install from ModDB. I Promise it will make anyone''s bad opinion on this game go away. Such a good game that just needed the proper modern day tweaks', 'I can not emphasize this enough. The AI is BROKEN. The era is fine, the game mechanics are fine - I keep coming back and trying this game for that reason alone. Making firing lines and researching combat doctrines is awesome. But the game is KILLED by the AI literally failing to act. Siege battles are downright impossible because any attempt to get them on the walls has a 50% chance that the AI simply shuts down and they refuse to move entirely. If you are trying to climb walls with infantry to ', 'Very Positive', 89.66, 112.17, 36.15);
INSERT INTO reviews VALUES (311, 10680, 7432, 'this game is an all time classic that i revisit every couple years. playing as the aliens or predators is extremely fun and you feel like an apex predator, and playing as the marines has you on edge most of the time. the game also holds up graphically in my opinion. this game needs a remaster/remake ASAP!', 'Steam broke this and many other games including Fear 3, ACM and AVP. \n\nI''m sad. This game needs to be delisted or fixed by steam.', 'Very Positive', 89.52, 17.02, 68.87);
INSERT INTO reviews VALUES (313, 11040, 264, 'Well... Mostly fine. This is a P&C / Adventure / Puzzle game. The graphics are old but nice. The music is good. The story is adequate, not the brightest thing though. \n\nBugs, some minor things, nothing is game-breaking but save before the final stuff, just to be safe. No crashes.\n\nOverall, entertaining but frustrating at times. The puzzles go from spotting some things to pure moon logic. It is almost impossible to not look for the guide a few times (at least all the solutions are included). Also', 'Way too old and clunky for today''s standards.', 'Mixed', 67.05, 19.65, 0.62);
INSERT INTO reviews VALUES (314, 11050, 143, 'I would only recommend this to people that really enjoy point-click adventure games. It contains many difficult puzzles, and it requires significant attention to detail. I stuck with it, because I found the story interesting.', 'This game has one good thing going for it: the puzzles are truly excellent. Not too hard, no too easy, some really satisfying. But the rest of the game is all over the place. Voice acting is hit and miss, locations are usually really good, but the story is pretty nonsensical in a lot of respects. It starts off like a simple, detective-esque game, then it becomes very dark very fast (with things like  on-screen cannibalism, burning someone alive and watching it decompose in front of you, seeing s', 'Mostly Positive', 76.22, 9.45, 9.62);
INSERT INTO reviews VALUES (316, 11140, 334, 'A very nice palette cleanser after the previous Frogwares Sherlock games. The controls are much easier to handle, the inclusion of a first-person perspective really helps. The game also had (this is quite subjective but I’d still like to mention it) a much more interesting story with fun characters compared to the previous instalments. The puzzles were nice and I really like the inclusion of a sort of fast travel mechanic and a strategy guide to help you out. Massive improvement and (in my opini', 'The story was captivating enough to keep me longer than 30 mins this time before I rage-quit. The game mechanics are absolutely infuriating. if you miss to click on a tiny little detail (even if it is TOTALLY UNIMPORTANT) you cannot advance the story. I have been looking for almost 2 hours now what I missed. I know exactly how story is going to progress and what the next step is, but i am simply not allowed. I consulted 3 different guides and watched a youtube playthrough of the section- and I S', 'Mostly Positive', 71.86, 5.87, 9.87);
INSERT INTO reviews VALUES (317, 11150, 292, 'Loved it. Massive upgrade after the first game, and a lot of new features. The game feels exactly like reading a Sherlock Holmes story, even the kids and the brother were added. Fans of Sherlock would definitely like it and it''s a good standalone detective game as well.', 'I wanted to like this. I gave it a chance. I like other old games in this series and got used to some of its antics. But this game broke me. \r\nI can get passed some of the annoying usual things, like having to find very speciffic spots on the screen to advance the story, but the game has a few places where you can reach a game over. It doesn''t hint you in advance that they''re coming, so you can lose, return to the main screen and then use a load file from a far point in which you saved last, and', 'Mixed', 52.74, 8.15, 6.32);
INSERT INTO reviews VALUES (318, 11180, 230, 'A lot of people have quite negative opinions on this game, mainly because the game does hide quite little things around and sometimes in dark places. In my opinion, the game is okay, but i recommend playing it with high brightness and in casual mode without time limit, then you can search as much as you are willing and the harder things you can just find with hints. Music is a banger tho.', 'WOW this game is NOT good. I know it''s old but WOW. Finding the hidden objects is incredibly difficult when the objects are TINY and put in places where they practically BLEND INTO THE BACKGROUND. The absolute worse offenders of this is having to find strands of hair or shoe prints or ashes in dark areas or areas with a lot of details. Most of my time searching was squinting and rapidly clicking around and praying to God. The story is simple but unrewarding and gets complicated near the end, and', 'Mostly Negative', 37.83, 2.28, 2.88);
INSERT INTO reviews VALUES (319, 11190, 500, 'I''m playing Frogwares games in release order and this is the first game I can wholeheartedly recommend.\n\n- Atmospheric, grim, gritty, exactly what is expected from Jack the Ripper story\n- Puzzles mostly make sense and are just difficult enough, I''ve opened the guide only out of laziness\n- Many features that make you feel like you truly do detective work\n\nAlso, interactable zones highlight is the best thing that happened to Point&Click genre since ever, but unfortunately, the button is not listed', 'I seriously can not see why this had so many positive reviews. I bought it as a bundle so at least I didn''t lose a lot of money but sanity is another thing. This game dragged on, and on, and on and on..... with boring dialogue and poor game play. If I wasn''t such a stubborn old cow I''d have bailed after the first session but meh I hate to be beat lol.\nThe game is nauseating to play in 1st POV which is why I spent as much time on it (I had to keep pausing), I finally gave up and changed camera. T', 'Mostly Positive', 77.20, 10.60, 16.83);
INSERT INTO reviews VALUES (320, 11200, 268, 'Game is fun. Shorter than the previous, sort of like a spin-off. Worth getting it along-side the original on sale.\n\nIf you crash, install legacy PhysX: https://www.nvidia.com/en-us/drivers/physx/9_12_1031/physx-9-12-1031-legacy-driver/\n\nIf you get graphical glitches, espetially around water: turn off Anti-Aliasing.', 'My system is from ibuypower and I can''t get it to run this game at all so it will remain in my hidden list and never touched again.', 'Mixed', 63.43, 3.72, 0.08);
INSERT INTO reviews VALUES (321, 11230, 112, 'the most hardcore racing game 10/10 should be GOTY', 'It''s on sale for $0.29 right now, but you''re better off just buying a gumball instead. It''s four cents cheaper and you can blow bubbles.', 'Mixed', 66.07, 0.68, 0.12);
INSERT INTO reviews VALUES (322, 11240, 332, 'It''s surprisingly fun and entertaining', 'I have no idea why I bought this game 8 years ago and then never played it till the other day.\n\nSome people may find some charm in it but I struggle to find it, and I grew up playing games like this, its like they copied the early 2k''s video game design language but picked all the 30% positive review scored ones from PCGamer reviews.', 'Mixed', 54.82, 9.63, 0.35);
INSERT INTO reviews VALUES (324, 11260, 114, 'Pacific Storm Allies is a hilarious and chaotic experience! I never expected to be laughing while dodging enemy fire and managing my fleet. The blend of strategy and unexpected events keeps you on your toes—one moment, I''m launching a surprise attack, and the next, I''m frantically trying to rescue my ships from a rogue wave. The graphics are vibrant, and the sound effects really pull you into the action. It’s like being in a naval comedy where the ocean has a mind of its own! If you''re looking f', '1.5/5\nThe game is incredibly noob unfriendly. I was there only for the steam cards anyways.\nFirst thing you do is get faced by walls of text and match settings but you basically have no idea what to play and what to do. AFAIR it has a tutorial but I couldn''t bare it. Simply a boring junky strategy game with 3d environment and effects.', 'Mixed', 46.49, 4.55, 1.67);
INSERT INTO reviews VALUES (325, 11280, 540, 'It was an experience to play on the last server before it crashed forever.\nRIP Penguins arena. We will miss you.', 'A lot of bugs, but no fun', 'Very Positive', 92.96, 3.42, 1.37);
INSERT INTO reviews VALUES (326, 11340, 243, 'Its fun and there are no other games like this. I expect something big from this creator in the future', '>reset the game''s profile to play anew\n>create a completely new player\n>screw you, the agency''s progress/unlocks are tied to Steam achievements\nWell, screw you too I guess.\n\ned: Also, maniacally re-enables fullscreen (and associated messing with the resolution of all other windows on the desktop thank you w10) every freaking time despite explicitly setting it to off and triple-checking if it saved. Even setting it in the config file directly does''t help.', 'Mostly Positive', 75.72, 0.15, 13.92);
INSERT INTO reviews VALUES (327, 11370, 139, 'The game captures the look, feel and atmosphere of the books quiet well with attention to detail and this is the main reason to recommend the game for fans of Enki Bilal''s work who have a thirst to play a game inspired by that work. \r\nThe game is an old school linear point a click adventure with many ways to die with some scenes requiring quick thinking with no time to ponder. You will probably die several times before figuring out what needs to be done (not to worry you have the option restart ', 'Broken.\nIf I try to use chains to block one door - it is OK, but it doesn''t work on the same door in another place in moment of rush. If I take some item so early before it supposed to be used, I have a broken game.\nInstead of the game I''ll better buy the artbook... But it doesn''t exist, at least in Steam.', 'Mixed', 51.80, 4.63, 1.13);
INSERT INTO reviews VALUES (328, 11390, 416, 'THE game of my childhood! Fun gameplay and vehicles, amazing rock soundtrack', 'An open-world driving game with decent graphics, but frustrating missions, broken physics, repetitive music, and a completely bland, inconsistent story.', 'Mixed', 58.17, 17.53, 0.28);
INSERT INTO reviews VALUES (329, 11450, 2121, 'Words can''t describe how this game appeals to the reptilian brain of many fantasy lovers. The sheer amount of charisma and personality this game has needs to be studied.\n\nOne could only hope for Overlord 3 by some miracle', 'Finally playing this some 15 years after I bought it.. The game is charming and the idea is decent. It''s a no for me because I find the controls to be very clunky. You can accomplish everything you want to accomplish, but it takes way more mouse movement than it should and for some reason that makes me not want to see this game to the end.', 'Very Positive', 91.94, 18.23, 3.60);
INSERT INTO reviews VALUES (330, 11480, 264, 'They just released a patch for this ancient gem of a game. Wildly unexpected!', 'I honestly don''t understand all the positive reviews.  I found the controls to be horrible and the game tedious.  I rather play the original Sudden Strike game than this.', 'Very Positive', 82.95, 17.22, 0.80);
INSERT INTO reviews VALUES (331, 11550, 150, 'I used to play this game when I was a kid, its amazing! Great story and mechanics!', 'I loved this game back in the day. Was really looking forward to playing it again. But without controller support this game is horrible. Its sad to leave a negative on this game but the mouse/keyboard set up is garbage.\r\n\r\n DO NOT PURCHASE UNIT THEY ADD CONTROLLER SUPPORT.', 'Mostly Positive', 77.33, 1.57, 0.35);
INSERT INTO reviews VALUES (332, 12130, 2397, 'If you bought this game on Steam, you''ve successfully downloaded a pirated copy of Rockstar''s Manhunt.\r\nIf you bought this game on steam and try to play it, it will never launch. If you do get it to somehow launch, you will get hit by Rockstar''s anti-piracy measures preventing you from progressing past 5 minutes. You are playing a pirated copy after all. Maybe next time do not download a pirated game from Steam. hope you learned your lesson.\r\nIronically, this happens because Rockstar attempted t', 'For those who are still unaware, what many are considering bugs in this game are actually anti-piracy measures. At some point, Rockstar decided to remove, SecuROM, the copy protection for this game. Without that program, their crack protection software was unable to verify the authenticity of the game, therefore treating any person owning the Steam version of this game as a pirate. Yes, as of right now, Rockstar is selling a pirated copy of the game that punishes anyone who buys it. \nIf you look', 'Mixed', 67.58, 7.33, 12.35);
INSERT INTO reviews VALUES (333, 12150, 4514, 'Just thought I should say this to anyone who is struggling to play the game on Windows 11. I spent 2 days trying to get the game to work, however it kept randomly crashing, sometimes after 10 minutes and other times as soon as I booted up the game. I followed every guide, downloaded every fix, but nothing seemed to work. Until some random comment on reddit from awhile ago suggested to change steam.exe affinity to 1 cpu in task manager. As soon as made this change the game worked. I''ve so far bee', 'dude this game will not start, I''ve tried everything. even guides won''t help, fix your crap. windows 11 users don''t even bother buying.', 'Very Positive', 94.44, 6.13, 0.72);
INSERT INTO reviews VALUES (334, 12180, 141, 'works well on steam deck! still good 2024', 'won''t run unless you have a commodore 64', 'Very Positive', 85.11, 53.73, 0.67);
INSERT INTO reviews VALUES (335, 12200, 13325, 'I love this game. Why Rockstar hasn''t done another one yet is truly baffling. This was an actual masterpiece and does deserve a remake and a sequel.', 'I want to preface this by saying: Bully is an absolutely PHENOMENAL game that I highly recommend anyone to play, especially if you''re already a fan of open world GTA-style games. This review is not for the game Bully itself, but instead for specifically the PC port of the game that''s available for purchase on Steam. \r\n\r\nVisually and gameplay-wise, this is a pretty damn good port for an older title in my opinion. It definitely feels like the lighting and textures got a bit of an upgrade since the', 'Very Positive', 80.44, 14.58, 13.87);
INSERT INTO reviews VALUES (336, 12220, 2954, 'It''s fun, but after you''re done with both TLaD and TBoGT theres no point in playing it, so due to that the game will give you about 40 hours of playtime.', 'Because of motherfucking SecuROM, this motherfucking game doesn''t run on motherfucking 6th generation Intel processors. Motherfuckers.', 'Mixed', 69.67, 2571.85, 16.55);
INSERT INTO reviews VALUES (338, 12320, 1138, 'Better than diablo 4.\nIt''s a classic.', 'Doesn''t worth it\n\nJust to run the game on modern hardware you must to workaround with some mods and configs. It''s not too complicated, but if you place game in the store you must be sure it works without any tricks', 'Mostly Positive', 79.53, 44.10, 0.15);
INSERT INTO reviews VALUES (339, 12330, 350, 'Who said the xbox controller never worked with this game???\nIt was the one thing the reason i never brought it.\nas guess what as soon as i started the game it found my controller i re - config the buttons and i am good to go.\n\nany one else out there wants too know yes xbox one controller works great. \nand with it on sale what a steel.', 'not for me , but an ok space game, u may like it ,do some research first..i didnt', 'Very Positive', 81.43, 0.95, 1.85);
INSERT INTO reviews VALUES (340, 12360, 1843, '1) Install the game;\n2) install the mode which adds the music from Flatout 2 ("Flatout: Ultimate Carnage - Combined Music" on ModDB);\n3) play.\n\n2006-2007 are returned.\nGameplay still rocks.', 'The game has been "enhanced" in the "Collector''s Edition" (no collector value there whatsoever, it''s a digital release, DRM''ed with Steam). This edition REMOVES MULTIPLAYER both online and LAN. The company didn''t have even decency to port it to Steamworks. Menus are still not controllable with mouse but only with arrow keys, enter, escape, etc. Console controller mappings cannot be rebound, gear shifting is set on the over the trigger bumper buttons: RB, LB. Game is highly frustrating to play du', 'Very Positive', 87.47, 25.13, 25.68);
INSERT INTO reviews VALUES (341, 12370, 115, 'I played many TRPGs, but this is the one I always come back to, because its simply the best one with right mods. For two decades the 1.13 mod is in development, adding tremendous amount of features, aiming to make the game as realistic a possible. If you dont mind sprite graphics and ready to spend some time learning the numerous features, hotkeys and mechanics you''ll find out that it has an almost infinite replayability. The mods I use are 1.13 (latest from github repo) + Wildfire Map Pack for ', 'Won''t start.', 'Very Positive', 89.57, 64.92, 1.47);
INSERT INTO reviews VALUES (343, 12390, 112, 'It''s a Good old half-life style fps game, i heard people calling this game a half-life 2 clone but i think this game has a lot of fun moments with variation of weapons and cheesy but great voice acting and the perks that comes from a game made in Source engine makes this game a good and enjoyable game for half-life lovers even if its not half-life, 7/10', 'Exodus from the Earth brought back bad memories of playing Chaser.\r\n\r\nThe assets and map designs feel like they have a lot of thought and effort put behind them. The gameplay is actually fun but the game ultimately felt like a chore because the enemy positioning is just horrendous. Take a basic linear corridor shooter and just line camping enemies in the corridors all aiming directly at the path you must take to progress further. Now take those enemies and ensure they are positioned above you, b', 'Mixed', 56.25, 8.80, 11.15);
INSERT INTO reviews VALUES (349, 12470, 255, 'super complete game, obviously grafics are old but still very cool. Much better than port royale 3 or 4 tbh', 'Don''t bother - the Steam edition requires unreasonable amount of fiddling around with compatibility settings. Sure, it''s an old game, it''s to be expected etc. BUT the GOG version works out of the box. So... yeah. Don''t repeat my mistake.', 'Mostly Positive', 72.16, 111.12, 0.08);
INSERT INTO reviews VALUES (351, 12500, 674, 'It''s getting close to 20 years old now, but it is still my favourite match 3 game. Yes the story is crap, the AI cheats and the battles get repetitive, but it is still worth playing after all of this time.  Plus you can find the expansion that never officially released for the PC in the discussions, which is a bonus.', 'The AI cheats AF', 'Very Positive', 85.76, 19.73, 3.13);
INSERT INTO reviews VALUES (352, 12510, 101, 'i love the old school graphics the way the software creators thought of every detail of a prison', 'Game sucks', 'Very Negative', 19.80, 8.12, 3.42);
INSERT INTO reviews VALUES (353, 12520, 267, 'my grandma bought me this game back when she was alive so ive been playing this game since i was like 4. lot of good memories playing it. i recently turned 18 and my grandmas passing was 10 years ago so this game has a lot of sentimental value.', 'It''s no American (Euro) Truck Simulator, but then again it came out a decade prior. Worth a few hours at best.', 'Mostly Positive', 76.40, 50.28, 1.20);
INSERT INTO reviews VALUES (361, 12640, 255, 'Love it! :)', 'This game tends to crash quite a lot and it''s really frustrating. My playtime would be a lot less so far if I din''t have to relaunch the game all the time.\n\nAnd so far, I mostly just fought rats, i just couldn''t be bothered to continue the game', 'Mostly Positive', 74.90, 80.37, 9.00);
INSERT INTO reviews VALUES (363, 12690, 157, 'One of the best old hunting game i remember playing it with my father and being afraid of facing animals like lions or cougar now i finally came back myself and hunted them 10/10', 'Can''t play all modes except challenge mode, game never saves, etc. are not available.', 'Very Positive', 82.80, 3.67, 2.02);
INSERT INTO reviews VALUES (364, 12710, 906, 'I really wish this series got revived. It''s been a decade since the last game went down like a sheep on fire.\nHonestly even if it got a proper reboot i wouldn''t mind so long as it won''t be forgotten.', 'Plagued by a litany of technical issues. Mouse input may straight up not respond if your mouse polling rate is too high. If the polling rate is suitable for the game, it the game may still think you''re holding down one or other buttons when you''re decisively not. Minions will get stuck inside of props littered around the environment, minion pathing apparently sends them on a straight line to you (meaning they simply won''t return from long distances. or if a box is in the way), textures aren''t pr', 'Very Positive', 92.72, 19.37, 16.72);
INSERT INTO reviews VALUES (365, 12810, 1707, 'Amazing game, a true classic. I still hold onto hope that a new one will be released one day.', 'Sadly for now I have to give this game a thumbs down. I have a high end PC, but the games frame rate is making it unplayable. As soon as I get to the main menu it starts stuttering.\n\nI have tried running in windowed, changing to different resolutions, lowering the graphics, switching to gamepad normal, with V-sync and without, removed different graphical settings. Nothing has worked, but if anyone knows how to fix then please comment on this review. I have looked online and no information has fi', 'Very Positive', 85.53, 84.72, 0.28);
INSERT INTO reviews VALUES (366, 12900, 6039, 'Import the most metal song you can think of, and try to beat it on hard mode ;)', 'You''ll enjoy this game a lot if you have a big library of pirated music.\nUnfortunetely does not play well with music streaming services.', 'Overwhelmingly Positive', 95.48, 0.12, 3.38);
INSERT INTO reviews VALUES (369, 13500, 1473, 'Absolute Masterpiece ....the memories this game hold is priceless', 'MAKE CONTROLLER SUPPORT YOU A**HOLES.', 'Very Positive', 81.33, 0.30, 11.33);
INSERT INTO reviews VALUES (370, 13520, 4258, 'FC1 the enemy will engage you beyond the render distance if you''re in the open. This is what happens when enemies are actually aware of how much of a threat the main character poses.', 'don''t buy this game just because you are curious. It''s not fun at all but instead a like chore to finish', 'Mostly Positive', 77.13, 11.23, 9.08);
INSERT INTO reviews VALUES (371, 13530, 993, 'Probably my favourite and most replayed Prince of Persia back in the day. Seeing these old titles get a remaster would be amazing....', 'Absolutely the worst installment in this f*cking series. The parkour is broken and glitches out all the time. The combat is the weakest and the story is absolute dogsh!t and you can''t even skip the cutscenes.', 'Mostly Positive', 78.55, 2.08, 11.40);
INSERT INTO reviews VALUES (372, 13540, 829, 'This game makes me want to buy a Dodge and wear Axe', 'This is made by Ubisoft so I warn against buying it because who knows they might decide to delete this from your library one day if they feel like it since we are supposed to "get comfortable with not owning" our games', 'Mostly Positive', 79.37, 11.37, 9.93);
INSERT INTO reviews VALUES (373, 13560, 1955, 'A message to UBISOFT.\r\n\r\nGuys, this was the golden era. The two coolest things on this planet in no particular order are; The Matrix\r\nand Splinter Cell. What a fantastic game, its over 22 Year old and destroys anything you have made in the last 15 years... If you want to save your company... you know what to do ... OVER AND OUT', '2025. Aged very poorly, despite the fact it already was disgusting, outdated garbage when it was made in 2002. The classic Ubisoft''s crap in a nutshell', 'Very Positive', 87.72, 15.05, 14.75);
INSERT INTO reviews VALUES (374, 13570, 3320, 'Game is the pinnacle of save scumming. Played this on Expert difficulty where one or two shots means you''re dead. I can now confidently say I have beaten the game without taking damage once and possibly have the capability to now be Sam Fisher in real life and take out anybody without suffering real life consequences. \n\nThe bomb defusal part sucked though, I have played that shit so many times I can replicate Shetland''s speech word for word.', 'Best game in the series. Stuck with a terrible company.\n\nDesperately needs official controller support.', 'Very Positive', 93.01, 19.17, 0.37);
INSERT INTO reviews VALUES (375, 13580, 912, 'Well lots of people are speaking how this game does not work properly. After I installed the 1.02 patch from one of the guides game worked like a charm. I only had 2-3 crashes, everything else worked fine.', 'Ubi would make more money fixing the ports of DA and Pandora tomorrow than their last 6 "AAA" titles, but they are neurologically disabled.', 'Mostly Negative', 30.59, 7.65, 24.32);
INSERT INTO reviews VALUES (376, 13600, 2055, 'Honestly incredible on the OLED Steam Deck so far. Super optimized running at the 90Hz refresh, incredible attention to detail for the time, colors pop, stylistically over the top. Music is fantastic, character models look great, environments are immersive, and at some points you take step back and say wait a minute... This is Ubisoft. What happened? They used to create some truly inspiring titles that pulled you in and had some flare. Now its sticking to Division and Assassins creed for dear li', 'I should make it clear from the start that this isn''t as much a review of the game as a review of the experience playing it on Steam. If you''re gonna mald over that, you can read another review; there''s no shortage of ''my childhood nostalgia'' posts for these games on Steam. If I were to rate the game itself, it would probably be 6 out of 10; the game is decent. The graphics are good for the time, the soundtrack is fantastic, and the lack of story focus or cinematic sequences in favour of raw gam', 'Very Positive', 83.45, 2.47, 7.40);
INSERT INTO reviews VALUES (379, 15000, 269, 'No uplay', 'If I walked into an EB Games in 2008 with no prior knowledge of the Rainbow Six franchise and saw this on the pre-owned shelf for $2, I probably would’ve picked it up and thought it was a fine shooter. Nothing special, but enjoyable nonetheless. The problem is that I’ve played all of the previous Rainbow Six games; recently, in fact. For a franchise which is well-known for essentially inventing the tactical shooter genre as a whole, it’s a little disheartening to see a game which isn’t much more', 'Mixed', 56.13, 11.92, 4.95);
INSERT INTO reviews VALUES (380, 15080, 864, 'This pisses me off just as much as it did when I was seven.', 'If you got an "error 2:0000065558" message when trying to launch the game or just anything simiilar, that is beacuse you installed the game on an E:/ drive or just a drive steam was NOT installed on. You''d have to move it to the same drive you installed steam on. Thanks ubisoft. :steamfacepalm:', 'Very Positive', 85.42, 0.62, 1.40);
INSERT INTO reviews VALUES (381, 15100, 9522, 'BEFORE PLAY, GET THIS MOD ASAP: ( https://www.nexusmods.com/assassinscreed/mods/81 )it makes it so that AC1 won''t try to ping a dead ubisoft server and stops the random freezing,\nReally good game (Minus the freezing without the mod) it''s overall a really good. Don''t play the newer AC games before this there is no fast climbing, 8.5/10 would replay again', 'Freezes every minute for 10 seconds because this junk is trying to connect to Ubisoft''s crappy servers from 1674. Ubisoft is quite possible the most incompetent studio around today.', 'Mostly Positive', 78.88, 5.15, 0.37);
INSERT INTO reviews VALUES (382, 15120, 3331, 'Its simply a shame what they did to the Rainbow Six series with Siege. They practically ruined it and turned it into Call of Duty Siege. \n\nRainbow Six Vegas 1-2 was peak gaming. I miss those days. I will always love this game. \n\nA good story/terrorist hunt mode too.', 'Game keeps crashing. I''m glad ubisoft is dying and especially after removing T-hunt from siege', 'Very Positive', 84.21, 71.77, 5.18);
INSERT INTO reviews VALUES (383, 15130, 1710, 'Good thing I bought this couple weeks ago for about $2', 'Great game - leaving negative review due to Ubisoft removing this version from Steam and replacing with a buggy, Denuvo ridden version for a 20 y/o single player game.\nIt''s also nice to see that Ubisoft have carte blanche to just ignore Steam''s TOS with no consequences. \nRecommend either buying from GOG (an actual respectable store) or emulating.\n\n', 'Very Positive', 82.69, 9.28, 0.27);
INSERT INTO reviews VALUES (385, 15170, 1212, 'Game of my childhood.\nI played countless hours and had even a game date with a girl and the winner should receive a nice price....I think she let me win...aw the memories!', 'Trying to find the tear of asha is way to difulcult  to find . you spend hours trying to find it and when you finally give up you can''t move on to the next. This is bull shit', 'Very Positive', 85.31, 29.65, 225.10);
INSERT INTO reviews VALUES (386, 15190, 952, 'My guy Baker can''t sprint. He can''t hold his gun steady for 2 seconds. He can''t jump over knee-high obstacles and even when aim is dead on, he can''t hit the broad side of a barn.\n\nThis truly is one of the most immersive WW2-shooters.', 'Brought back some real good memories from playing this as a kid. Cant recommend purchase though, there''s a glitch in the steam version of the game in chapter 6 that keeps you from finishing the mission and moving on. The Platoon Sgt gets stuck in the sidewalk in the same spot every time and there''s no way to unstick him. And as he needs to enter the factory so you can speak with him to finish the mission, you cant complete the game.', 'Very Positive', 85.82, 8.40, 6.38);
INSERT INTO reviews VALUES (387, 15200, 663, 'This game works fine for me on Windows 11 after you set the Compatibility settings. Run as XP SP2, and disable fullscreen optimizations. I can''t see the intro video when I start the game, but if you hit enter or click it will skip it. It''s also a nice sub game for it''s time and it''s fun today.', 'This game would not load.  Period.  Brand new gaming laptop.  I researched the game for "work arounds."  Too much effort for a "might work."  Despite the fact it never loaded I got "credited" for 4.9 hours of play.  Therefore no refund.  Can you tell I''m upset with Steam for selling a product that has documented failures with other customers?', 'Mostly Positive', 72.40, 1.25, 5.08);
INSERT INTO reviews VALUES (388, 15210, 1388, 'There''s a reason this game is at or near the top of the charts for Submarine games - even after 20 years. In short, it''s damn near perfect. But I''ll be honest - if you like instant gratification, guns-a-blazing action then look elsewhere. This game relies on planning and stealth. You may spend hours stalking your prey for that perfect kill. And much like the real-life events it portrays, you will slowly turn from the "hunter" into the "hunted" as the allies slowly figure things out and improve t', 'A positive review is not available in your region.', 'Very Positive', 86.60, 181.45, 2.85);
INSERT INTO reviews VALUES (389, 15240, 188, 'Still one of the best submarine games out there after all these years from introduction. Graphics and Gameplay are still semi competitive modern. The range of MODS and so forth for it are very numerous and expand the gameplay by considerable margins. I still give SH4 5-Stars.', 'does not work anymore after update...', 'Very Positive', 85.64, 148.92, 11.93);
INSERT INTO reviews VALUES (390, 15270, 508, 'What a pleasant find. As long as I''ve been playing survivor horror, I hadn''t heard about this one until I read about it on some top 10 list. Sure, it is an older game with some flaws...the lack of a quick turnaround action as well as no map being the top issues...but it was still a fun experience. The ship sway being built into the game is something I don''r really remember in any other title. It had a few genuine scares and a real creepy atmosphere. If you are a fan of Resident Evil, the Thing o', 'Cold Fear is a nearly 20 year old game, so some imperfections like the camera are to be expected. But other mechanics like not having a manual save menu option/save room or not having an accessible map are just a little frustrating. The game’s story is most like the first Resident Evil movie in that it makes sense the more you willfully turn your brain off. Unless Cold Fear is something you are nostalgic for, I can’t imagine this being something anyone needs to play in 2024.', 'Very Positive', 82.28, 10.43, 2.48);
INSERT INTO reviews VALUES (392, 15300, 1015, 'When the name Clancy meant something instead of being the usual Ubisoft slop with his name slapped on it. The best Ghost Recon and it isn''t even close.', 'not working\n', 'Very Positive', 93.50, 25.48, 44.92);
INSERT INTO reviews VALUES (393, 15320, 1575, 'whoever gives this game a negative review will get The Curse of Ra. I cast 1 million bees in your car.\n\nIf you buy this game, it gives you immediate access to IL-2 BAT mod from the SAS website, which gives you like well over 2 thousand aircraft across decades of aviation history, and hundreds of maps plus so many other things including incredible campaigns. Somehow after 20 years it is still actively updated.\n\n1946 my beloved, you truly are the greatest there ever was, and possibly ever will be.', 'no longer runs without a lot of work on windows 11. Answer from devs is to re-buy the game on their launcher', 'Very Positive', 88.51, 14.50, 4.95);
INSERT INTO reviews VALUES (394, 15370, 851, 'I remember playing this game with my dad back in 2010, it''s just as good.', 'This game is not functional on Widows 10/11', 'Very Positive', 90.72, 84.38, 173.45);
INSERT INTO reviews VALUES (395, 15380, 119, 'after so many hours, i still have no idea how to build walls', 'After playing, and acutally finishing the campaign of Heroes V, I thought this would be a great expansion with a new faction.  I was sorely disapointed.  And unless some major changes have been made since playing it, several features that made Heroes V great have been removed, including the tracking bar of how much energy you have to use for necromancy which now makes it difficult to play that faction.  Save your time and money and buy Tribes of the East, which has the new Dwarf faction, and a n', 'Very Positive', 83.19, 366.88, 5.02);
INSERT INTO reviews VALUES (396, 15390, 1127, 'Feels like band of brothers. 2024 needs something like this.', 'Hindsight is 20/20. This series had so much potential, and this game single handedly killed it. I remember hating this game when I was younger without even playing it, because the writing was on the wall. Now that I played through it years later, I realize my feelings were justified. This game wants to be Call of Duty, but fails. It wants to be taken seriously, but is so over the top, ridiculous, and cliched with its story, it fails. It also tries to retain the gameplay of the first game despite', 'Very Positive', 89.62, 11.88, 7.17);
INSERT INTO reviews VALUES (397, 15400, 103, 'Great game', 'It''s like this hot spanish girl you fell in love and spend the time of your life with. But after a few months it dawns on you that you are not compatible for a long term relationship.\n\nThis game is very unique, very beautiful and encourages you experiment a lot. It shows you how to be creative, build something and invites you to experiences you never had anywhere else. But ultimately the dread of routine sets in and you are starting to realise that this is not going to be a match for a lifetime.', 'Mostly Positive', 73.79, 95.77, 45.57);
INSERT INTO reviews VALUES (398, 15500, 459, 'This game is honestly really good. \n\nI know it''s not the on-brand version of Katamari, but it still holds up to the level of quality those have. \nThoroughly enjoyed, hope the creators are ambitious enough for a sequel. \n\nLiterally played it 4 times, and maxed achievements c:', 'It''s just a worse katamari. Lacking in the interesting movement and objects of those games. Go replay any of those instead.', 'Mostly Positive', 78.43, 6.20, 1.18);
INSERT INTO reviews VALUES (399, 15520, 556, 'insanely good arcade with insane replay value with epic "funny" jokes', 'I got this game in a bundle in 2011 because I wanted Portal 2 to come out quicker.  Now, it sits at the top of my library, the title annoying me a little more each time I see it.\r\n\r\nI think I played it once over a decade ago and felt nothing while playing it.', 'Very Positive', 83.27, 18.32, 0.47);
INSERT INTO reviews VALUES (400, 15560, 401, 'Extremely challenging yet extremely gratifying game that is great for jump in, jump out kind of quick gameplay. The concept is very simple: You drop from a very VERY high building and have to get the highest possible score by falling through score rings scattered throughout your fall. Lots of variety with an exhilarating sense of speed and a very hard to master gameplay. The UI looks and feels so punk rock and although seemingly chaotic at first, will click with you in no time as the aesthetic i', 'So someone took those weird Minecraft levels where you jump down a hole & made a videogame out of them? I like the idea... but I''m already bored after 16 minutes & I don''t think I will ever want to play this again. It makes no sense to get the first game, as this sequel contains all the previous games levels, & is available for exactly the same price, while offering no graphical upgrades or other improvements. That being the case, the first game really ought to be removed from Steam.', 'Very Positive', 85.04, 1.52, 0.27);
INSERT INTO reviews VALUES (401, 15620, 4188, 'It''s 2024, I''ve had this game in my library highly recommended by a friend for 15 years and decided to finally play it yesterday. It''s 3am the next day and I don''t want to stop. It''s so good!!! I don''t know why I didn''t play it before, so regretting it now, wondering if I should get Dawn of War I and play that as well; I probably will! Highly recommended!!!', 'It would be better if you finally release a new patch for all your games and add support for 16 core processors so that people with such systems can play now.', 'Very Positive', 86.01, 50.95, 109.02);
INSERT INTO reviews VALUES (402, 15700, 1269, 'The 90s had some seriously weird auteur stuff slip through the cracks, and thank god. Such a strange, unique world that holds up to this day, except for the really nasty controls, which pretty much on their own make the game really hard. If you''re prepared for a frustrating puzzle platformer, the story and atmosphere takes care of the rest. I still quote the cutscenes to this 20 years after playing it', 'I bought this game because I remembered that I tried it once when I was like 10 years old or something like that.\r\n\r\nLittle did I know that this game was made by a masochist.', 'Very Positive', 89.28, 18.73, 3.93);
INSERT INTO reviews VALUES (403, 15710, 821, 'first game to ever sell 1 abeillion copies', 'Aged poorly, way more difficult than I remember, unresponsive and buggy.  Loads of unfair deaths. Softlock yourself every hour forcing you to restart parth. A save system out of the 80s making you lsoe progress. A game sold on Steam should be optimized for M+K as well I don''t care how old it is, I don''t care that you are a DArk souls player playing with a brick on PC cause the devs won''t opmtimize for pc either. If you are making money off it optimize it for PC usage. But of course Caddicarius a', 'Overwhelmingly Positive', 95.86, 22.48, 15.57);
INSERT INTO reviews VALUES (404, 15740, 703, 'Please add sex with Big Tiddy Goth Chicks', 'Game is great on Xbox, no bugs at all on Xbox. But by god I don''t know what they did it to it when transferring it to pc but jesus christ the amount of bugs in this game you could call it a god damn cockroach infestation. I am seriously wondering how they managed to screw this game so hard it made it basically impossible to play not from the controls which are horrible on pc by the way but the visual bugs because the half the time your character is invisible or a hodge podge of level assets stuc', 'Mostly Positive', 77.10, 1.25, 5.48);
INSERT INTO reviews VALUES (405, 15750, 1055, 'One of the great cult classics. As a child, a friend of mine had Halo CE, at game stop I begged my mom for halo, I cried when she saw the M rating and said no, I think the game stop worker felt bad for me, he handed me a demo video for this game. I watched the demo video on a DVD player with a flip screen at least a few hundred times until my parents finally bought it for me on easter. This game is probably the most nostalgic game for me. I don''t personally know a single person who has played th', 'Another unfortunate misfire in the Oddworld series; maybe not on the level of Munch, but nowhere near the quality of the Abe’s games either. Just like Munch went 3D because it was cool, Stranger became a first-person shooter because it was cool, even though it was a notoriously tricky and expensive genre to do right at the time.\n\nThere are some theoretically interesting, unusual mechanics here, but they don’t add up to a good gameplay. The core shooting is slow and repetitive, the environments a', 'Very Positive', 87.11, 29.25, 13.72);
INSERT INTO reviews VALUES (418, 16100, 141, 'This is the best game I''ve played in my life. Red dead? NO. FNAF? NO. God of War? NO. Elden Ring? NO. None of these FAKE LOSER GARBAGE GAMES can even hold a CANDLE to the shining star that is Virtual Villagers: A New Hope. For starters, the visuals are perfect. They leave just enough to the interpretation of the viewer while still evoking a nostalgic feeling deep within your soul. The audio is delightful. I often say "hey" in the cadence of my villagers in day-to-day life. The lore runs so deep,', 'I''ve no issue with games that require long-term thinking and management, especially offline, but the way that Virtual Villagers: A New Home currently stands makes the experience unbearable and mind-numbing. For a game that requires some micro-managing, using any keyboard shortcuts that minimize the game''s window causes there to be a display error which is generally temporary but there have been instances where it remains even when the game is closed. Unlike other Last Day of Work products, this ', 'Very Positive', 88.65, 28.97, 2.80);
INSERT INTO reviews VALUES (420, 16120, 152, 'Fantastic and nostalgic game. But before you buy it here, the game is free for download from the developers'' website here: http://www.ldw.com/plant_tycoon.php\nThey also have free downloads for some of their other original games like Virtual Villagers, and Fish Tycoon. I would normally also recommend considering still supporting the developers by buying the games here, but all their newer games rely heavily on micro-transactions, which I despise, so do with that information what you will.', 'my game data doesn''t save. I need to start over and over T_T', 'Very Positive', 92.11, 21.30, 190.17);
INSERT INTO reviews VALUES (422, 16180, 108, 'this game was my childhood game i was pretty young and couldn''t read English when i used to play it on my dads PC so i couldn''t go far in the game but now that im an adult i thought i should play it again and its as good as i remember and very nostalgic', 'i dont like this 1 cus there isnt many food sources and alot more player interaction its more science and healing not to much of anything else and the more focus is on science and player interaction above all else so its not as good as the lost children or tree of life', 'Very Positive', 90.74, 12.12, 3.13);
INSERT INTO reviews VALUES (424, 16300, 105, 'Beautiful little game. Feels more personal and intimate than anything else I''ve played.', 'https://www.youtube.com/edit?o=U&video_id=W0vs3lZJHzc\n\nIt''s not everyday that a twin stick shooter is created with such a chill atmosphere and gameplay that blends well with it''s soundtrack.  The aesthetic both audio and visual presented in this game is top notch.\n\nIt''s a unfortunate shame that the gameplay comes up very lacking.  The controls map poorly to an analog stick making the aming very imprecise.  The trade off between max move speed vs fire rate on the surface would create player choic', 'Overwhelmingly Positive', 95.24, 3.38, 0.65);
INSERT INTO reviews VALUES (425, 16450, 2747, 'F.E.A.R. 2 is a big upgrade over F.E.A.R,  The graphics are good, its even more scary and gives you jump scare, combat and mecha suit is fun, shooting feels improved and better here, worth every penny.\n\nSchool level is the most scariest of all, worth playing this game, you will enjoy it and graphics look amazing even now', 'This game has nothing on the original. Everything that made the original so enjoyable is sadly lacking in this sequel. The guns suck because they lack power, the slow motion is boring compared to the original, and you can no longer lean around corners. Overall, this game feels like a downgraded cod campaign with horror themes - a real shame because the original (despite being 20 years old) is one of the most enjoyable fps campaigns I''ve ever played.', 'Very Positive', 80.05, 21.75, 7.88);
INSERT INTO reviews VALUES (427, 16600, 180, 'Unironically the most difficult entry in the Trials franchise, but it''s still a lot of fun once you get the hang of the controls. Although it''s a shame that it never goes on sale here because I feel like $10 is a bit of a steep asking price, considering the fact that Evolution costs just as much with a lot more content.', 'The original web version also had a more intuitive difficulty progression, gradually easing players into the mechanics and challenges. In comparison, Trials 2 Second Edition can feel punishingly difficult from the start, which might deter new players. The original''s straightforward and addictive gameplay loop was its strongest suit, and while the sequel offers more depth, it sometimes feels like it sacrificed approachability for sophistication.', 'Very Positive', 82.78, 4.38, 49.13);
INSERT INTO reviews VALUES (429, 16710, 181, 'This game makes me want to FUCK the BEES.\n\n', 'This is a hard game to review. I definitely enjoyed parts of the story and was overall quite interested in what would have happened in part 2 (there is a youtube channel with the cutscenes that would have been in part 2). \r\n\r\nThe reason for not recommending this game comes down to a few points:\r\n- the game introduced quite a few challenges throughout, such as providing minimal directions on how the game worked. This led to me having to google controls early on to see how I was supposed to intera', 'Mostly Positive', 71.82, 5.18, 3.02);
INSERT INTO reviews VALUES (430, 16720, 913, 'Link to review: https://backloggd.com/u/RedBackLoggd/review/1887470/\r\n\r\nTl;dr -  Though I believe it was unfairly-maligned by critics, Velvet Assassin doesn’t hold enough pros to warrant the label of overlooked gem. That said, if you’re in the market for a classic stealth game with consistent mechanics and cool visuals, then you can’t go wrong checking it out either.\r\n', 'I regret to leave a negative review for Velvet Assassin due to an inability to launch the game, encountering the persistent error: "Failed to init Ageia physics SDK." This issue stems from the game''s reliance on outdated PhysX software, specifically the Ageia PhysX SDK, which is no longer supported in modern systems.\n\nTo address this, players are required to install the NVIDIA PhysX Legacy System Software, a solution that is not straightforward for all users. Notably, this workaround is primaril', 'Mixed', 57.50, 9.78, 0.23);
INSERT INTO reviews VALUES (431, 16730, 1074, 'Please Add Steam Achievements.', 'I was excited when I saw this on the Steam Store recently, and decided to spend the $5 to play it. While I had a lot of fun with the nostalgia this game has to offer for being nearly 20 years old, I was super disappointed with the end result. Legendary has a game breaking bug at the very end of the campaign where your character glitches through the elevator doors every time you go inside, and it completely prevents you from going to the final part of the game. Extremely disappointed, and it seem', 'Mixed', 56.24, 0.55, 9.82);
INSERT INTO reviews VALUES (432, 16810, 789, 'old but good game, also download the mod WeThePeople voor a nice colonization experience~!', 'I would recommend to play the original instead. It''s better. This isn''t as cozy and beautiful and adds some layers of unnecessary complexity that takes out the fun vs the original version.', 'Very Positive', 87.20, 82.80, 0.87);
INSERT INTO reviews VALUES (433, 16900, 13260, 'Its hard to decide if you should or should not get this game. Tactical.. Sometimes. military... for sure its got the uniforms and some amazing guns. But its sometimes not a welcoming community for new or even experienced players. Everyone believes they have the "Right Way" of playing the game. I''ve waited so long to right a review and now I think its time.\n\n  I''ve been playing for years. Lone wolf or joining servers. It can be a lot of fun if you get a good group together, and even mods really c', 'This is a game the same way flappy bird is. There''s no variety or reason to play it for more than 30 minutes, it''s utterly mindless and every so often I''ll come back to play it for 20 minutes hoping something of substance was added. It''s still, after 7 years of being on steam, a shooting gallery of braindead AI worse than something you''d find in a 1980s arcade game. There''s still no friendly AI or interesting mission generation to make the game remotely interesting, which is tremendously disappo', 'Very Positive', 89.54, 323.77, 18.02);
INSERT INTO reviews VALUES (434, 17020, 366, 'It''s time Hi-Rez.\nGive me back my boy.', 'Game is dead. The streamer who made it spike briefly is just a phony and their followers are sheep.', 'Very Positive', 80.87, 34.98, 25.37);
INSERT INTO reviews VALUES (436, 17100, 283, 'Children of the Nile: Enhanced Edition is your standard city builder with plenty of scenarios to test the player''s ability to adapt to given environments along with events that range from predictable to unpredictable. With how much information is available to players within the tutorial stages and information boxes for every clickable NPC, structure, and cartographic symbol on the world map, the game is readily learnable for those versed and those unversed in its genre. Technically speaking, the', '2024 checking in. I absolutely love this game and recently went back for some old school pyramid building. Unfortunately nowadays this game crashes every time I try to load ANY developed map and often when sending troops. Boo! Great in its day; sadly I must now advise finding something else.', 'Very Positive', 82.69, 6.77, 233.33);
INSERT INTO reviews VALUES (437, 17120, 109, '10/10 one of the best ever made, shame it''s old now', 'Children of the Nile Alexandria is the expansion pack to Children of the Nile and where the main game survived solely on the fact that the city builder genre is almost dead, forcing fans to either suffer through it or starve, the expansion pack is starting to make starvation look mighty delicious.\n\nAlexandria does not address any of the main game''s problems or deficiencies, it simple adds a few campaign and a few new buildings.\n\nUnfortunately the maps are few and broken, missing base resources m', 'Very Positive', 82.57, 23.32, 67.47);
INSERT INTO reviews VALUES (438, 17140, 173, 'been playing this here and there for over a decade. nothing really like it. arpg city builder. watch the Accursed Farms video on it. wish there were more games like this. more refined.', 'Hinterland is the strange marriage of core game mechanic that many would consider best suited for a hardcore audience and an execution that caters heavily to a casual audience. The result is a seemingly confused game. Action RPG with strategy elements that''s geared towards 20-30 minutes gaming sessions.\n\nIt''s also a game that you feel is missing something. The gameplay has a very arcade feel to it due to the lack of any sort of metagame or campaign, every round being a one off attempt at a high ', 'Very Positive', 80.92, 10.60, 48.97);
INSERT INTO reviews VALUES (440, 17330, 1391, 'Before DLC plague our games, this is how an expansion was meant to be. As always Crysis Warhead was epic, brutal and interesting.', 'DEAR CRYTEK, PLEASE WORK ON CRYSIS 4.', 'Very Positive', 84.47, 17.93, 5.13);
INSERT INTO reviews VALUES (442, 17390, 35046, 'very good game u r sperm eating other sperm until you become bigger sperm then u are walkin g sperm than later you are flying sperm in space', 'As someone who spent hundreds of hours on Spore using my father''s formally subscribed EA account, I can say Spore is a fantastic game. Especially if you enjoy UGC, life simulators, and strategy games... However, I beg of you,\nPlease do not buy the Steam version of Spore, otherwise you will need to contact EA''s support in order for them to transfer your copy onto the EA App, which is a nightmarish process..\n\nThis Tomfoolery was caused by EA''s dismantling and replacement of Origin to EA.. Leaving ', 'Very Positive', 92.45, 3.88, 0.28);
INSERT INTO reviews VALUES (443, 17410, 14254, 'There is something special about this game. For me it''s not the parkour perse, and not even the storyline... But there is just something appealing that this game has. The environment, the vibes, the soundtrack... It''s just so nice.', 'Delist EA. Forcing third-party accounts and banning for inactivity with no appeal is predatory.', 'Very Positive', 86.74, 21.47, 3.30);
INSERT INTO reviews VALUES (444, 17440, 1156, 'goob', '\r\nshould be free', 'Very Positive', 89.10, 17.45, 12.63);
INSERT INTO reviews VALUES (445, 17460, 9477, 'They should have cloned everybody involved in this project and replaced all future game studios with the clones. The publishers however should have been sterilized.', 'Game is ruined for me by the terrible EA app that never works.', 'Very Positive', 93.86, 39.83, 0.18);
INSERT INTO reviews VALUES (446, 17470, 11465, 'heres a bright idea Kendra why dont YOU leave that little command room of yours and do some of these stupid chores im out here shooting this walking lard ball that kills itself to send out its little grimblies while you''re going "erm isaac i need the wumbus card to open the grimblybork" maybe I don''t care Kendra maybe I wanna go find my hot ghost gf instead', 'Delist EA. Forcing third-party accounts and banning for inactivity with no appeal is predatory.', 'Very Positive', 90.84, 15.37, 3.07);
INSERT INTO reviews VALUES (447, 17480, 5335, 'Good graphics. Fancy weapons. Good AI. Cheap price. Working good on my Entry level GPU. Definitely worth it.', 'Steam isn''t issuing CD Keys with this game, so you can''t play LAN games with your friends.\n\nThe game itself is awesome.... but playing against your friends is what really made this shine.  Sadly, without a valid CD Key you can''t do anything but play solo.', 'Very Positive', 83.54, 27.23, 287.85);
INSERT INTO reviews VALUES (451, 17710, 970, 'this game is like a combination between Battlefield and Team fortress 2 and call of duty and its very fun to play too bad it got left 4 dead', 'i really want this game to succeed. its a fun combination of RTS and FPS that is extremely rare to find. there are, however, two problems that make this not recommended.\n\nfirst and foremost, dead game. has been dead for a while, and games like this tend to need players to unlock its best gameplay.\n\nbut the most important thing that holds this back is the bots. i''ve played countless RTS games against AI and the likes. there are plenty of RTS games where there also is little to no players, but i e', 'Mostly Positive', 78.04, 4.93, 3.87);
INSERT INTO reviews VALUES (453, 18000, 302, 'You''re not. Gonna Get. The Final Boss Tamed.', 'Audio issues render the game unplayable for me.', 'Very Positive', 91.06, 6.70, 0.20);
INSERT INTO reviews VALUES (454, 18020, 121, 'If you liked Episode One, Episode Two is worth continuing on to. Same fun Super Mario RPG-style ATB system with active counter-attacking, special attacks which by the time they''re fully upgraded are an actual challenge to land for full damage, and a humorous Apocalypse-in-the-making storyline. Oh and it''s short enough to not overstay it''s welcome if you''ve got limited gaming time on your hands.', 'Look, if you really loved Episode 1 go for it, because it''s more of the same.', 'Very Positive', 85.95, 8.15, 11.63);
INSERT INTO reviews VALUES (455, 18040, 441, 'I am a 52 yo father, probably one of the oldest people playing DeathSpank. I am a single father to my Son, who is 14 now. My son found this game at Christmas, so we installed it on his computer and he started playing. By the end of the week he had 24 hours on this game. This was horrible for me, as it was already hard for me to find ways to spend time with my son, as he is always out with his friends or just watching YouTube. So I decided to make a Steam account and get this game to see if I cou', 'For a game as predictably tiring as DeathSpank, the $15 price tag is a tough sale as most of what the product has to offer are bevies of meaningless side quests, mind-numbingly self-justifying humor and a plot that should have never left the drawing board. Of course, this video game does have some merit when players have the opportunity to experiment with various weapon and item combos as well as absorb the impressive scenery and attention to visual details, but that is all it has to offer in te', 'Very Positive', 94.33, 0.63, 1.47);
INSERT INTO reviews VALUES (457, 18050, 142, 'If you ever encounter a save file crash, follow this link and to a file download (yes it''s safe, I''ve had the save file crash jumpscare)\r\n\r\nhttps://community.pcgamingwiki.com/files/file/957-deathspank-thongs-of-virtue-continue-game-crash-fix/#google_vignette', 'Funny like the first part. Did not have any problems running on windows 11 at first and I really liked it. Then after approx. 15h it was not able to load the savegame anymore.\n\nThat''s a no go.', 'Very Positive', 85.92, 30.53, 14.93);
INSERT INTO reviews VALUES (458, 18070, 113, 'Recommend', 'it certainly feels like a product of its time. i don''t think what''s here is truly terrible, but honestly there are way better games you could be out there playing if you want some sort of looting game with a story. humor is... fine, presentation is ok, but there''s just nothing outstanding here unless you want a deathspank game, or to see what kinda games they were putting in game bundles 10-15 years ago.', 'Mostly Positive', 76.11, 13.77, 1.02);
INSERT INTO reviews VALUES (460, 18110, 276, 'Was once a great game.', 'This game was awesome when it came out, the balance was good, the weapon did everything you could want. those were the good days, I could switch from defense to offense to sniping, all with a single gun. There was never a situation that you could blame anything but yourself for your death. The future was bright and I thought that this could very well be the next counter-strike in terms of e-sports.\n\nBUT, then came the firepower DLC, free DLC that took AWAY the gun that we loved, with no way to b', 'Very Positive', 88.41, 2.25, 12.60);
INSERT INTO reviews VALUES (461, 18120, 135, 'This game is a masterpiece. The audio, the visuals, the gameplay and the characters. The dialog made me cry. I''ve played this game twice already and both times I had a completely different experience. It''s beautiful, and I will continue playing this game until the end of me. I bought a whole new gaming PC, two RTX 4090s, an i9 13900, 64 gigabytes of RAM, making sure I can play this wonder at 4k 240 FPS. I don''t just recommend this game, I''m telling you to play it. If you don''t, you are missing o', 'Unstoppable Gorg is a tower defense game of the sub-genre I call "pointlessly manic" -- to play it properly you must fail a level repeatedly while figuring out a sequence, and then click 8 billion times per round and hope against hope that something random doesn''t get in the way of the exact movement/clicking sequence "strategy" that the hardest difficulty requires to 100%. Repeat until you beat... or in the case of this game, don''t bother. Because it''s not even worth it. The orbit gimmick is st', 'Mostly Positive', 74.07, 0.82, 1.02);
INSERT INTO reviews VALUES (462, 18300, 249, 'A cute little ball game. One of the crappier ones with strange physics, more akin to Slickball than Ballance, but still pretty fun. Unless you''re going for The Impossible achievement. Then it''s not so fun anymore.', 'This game was off to a grueling start when I got myself stuck against a wall in the hub world within the first minute (and somehow got a "7 seconds of airtime" achievment while doing so). After restarting the level, all the doors locked themselves for no good reason, forcing me to restart yet again.\n\nThings only went downhill from there. The level design itself was boring, unimaginitive, and generally extremely easy, consisting of platforms made of dated textures suspended in vast amounts of emp', 'Mostly Positive', 77.51, 5.50, 9.57);
INSERT INTO reviews VALUES (470, 18500, 3296, 'Defense Grid remains the digital equivalent of comfort food—familiar, predictable, and engineered to satisfy without nourishing. You''re paying not for innovation but for the dopamine hit of perfectly arranged towers executing predetermined strategies. The game''s greatest achievement is making you feel clever for arriving at the exact solution the designers intended all along.', 'Absurdly unbalanced, clunky. Towers will attacknot the first but the last enemy. Also often the enemy not at all, but the ground and air.', 'Overwhelmingly Positive', 96.30, 5.10, 14.83);
INSERT INTO reviews VALUES (472, 18700, 231, 'I had this game back on the Wii when I was 9, I never got to really finish it because I was 9 and unfortunately an idiot- as are most people at that age. I am now, like, 25. Still an idiot, but able to finish this game! And it was very much worth it. The music is great, the visuals are unique and add a lot to the experience of the game. I cannot recommend it any further. Please play And Yet It Moves.', 'Outdated, don''t buy. The only thing you''re getting is a black screen with background music that can''t be escaped unless you restart your entire system.', 'Mostly Positive', 76.62, 4.57, 0.10);
INSERT INTO reviews VALUES (473, 18820, 171, 'Think Mario Kart on PC, nuf said :-).', 'Don''t bother.  It''s buggy and just plain not fun.  \n\nIf you want a good Mario-Kart style racing game for the PC, pick up Sonic & All Stars Racing.', 'Very Positive', 80.12, 4.35, 0.43);
INSERT INTO reviews VALUES (474, 19200, 196, 'A highly sopisticated Tron like game where you alternate between controlling a 65 year old man, and a 65 year old man driving a vehicle with all the handling of a refrigerator precariously perched atop a unicycle.', 'Tron-inspired retro visuals and sound accompany flawed gameplay. Locked 30 fps and poor performance', 'Mostly Positive', 74.49, 5.68, 0.38);
INSERT INTO reviews VALUES (477, 19800, 521, 'Playing this game today makes you really question the direction gaming has taken. This game has heart. It was made by people who love what they are doing , and it shows.', 'There was too many tutorials and too many controls i just got confused cuz of how many controls there was like where you want ur soldiers to fire or charge to go to its just too much for me to understand', 'Very Positive', 85.03, 10.48, 0.52);
INSERT INTO reviews VALUES (478, 19830, 1211, 'Last true Rainbow game, Vegas games are OK but still they got nothing on R6 1 to 3.... man it is so sad looking at Siege.', 'You don''t need to play this. Cool idea, played Rogue Spear alot as a kid, but they are not good games. If you don''t want to lose operatives you either have to learn where each and every enemy is and take care of them yourself, or re run the sim over and over and hope you get a good run. If your spotted by a enemy you''ve got to go completly still and hope your crosshair focuses fast enough for you to get the shot, even using the auto aim feature I''m just not getting hits when I feel like I should', 'Very Positive', 91.91, 7.60, 3.57);
INSERT INTO reviews VALUES (479, 19900, 8723, 'It''s not the best Far Cry, but it''s the one most committed to realism, immersion and having a really lonely and oppressive setting, which I have to respect.', 'This game is amazing in my opinion, but I just wish Ubisoft shove a 50 foot pole inside their own rectum.', 'Mostly Positive', 78.38, 12.07, 1.62);
INSERT INTO reviews VALUES (480, 19980, 1671, 'It''s been 16 years. The art style still holds up. The chemistry between the Prince and Elika is still good. Some challenging puzzles as well.WHERE IS MY SEQUEL UBISOFT?', 'Any slightly above average game that isn''t heaped with praise or extraordinarily successful will always end up being hailed as a hidden game cult classic genre defining watershed deeply emotional and beautiful. This game is fine for 2 or 3 hours but it is not worth the double digit hours you''ll put into it, forgetting how much you pay.\n\nThe gameplay is nearly braindead, and if you have played any uncharted or assassins creed game, the charm of fluid parkour wears off extremely quickly. The same ', 'Mostly Positive', 77.86, 15.37, 13.08);
INSERT INTO reviews VALUES (482, 20500, 3671, '"Mason, drive the Killdozer through the government buildings."\r\n"OK, Commander!"', 'If you want fun destruction, I’d suggest playing The Finals over this one. The story here is nothing to write home about, and the vehicles are pretty awkward.', 'Very Positive', 90.98, 30.45, 40.47);
INSERT INTO reviews VALUES (483, 20510, 5036, 'Game aged like milk, but it''s the kind of milk that has an interestingly bad aftertaste, so you keep drinking it anyway, not sure if it''s skim milk, or expired.', 'I think I understand why so many hate on this game. To start, yes the bleed mechanic is super annoying and adds nothing to the gameplay besides annoyance, it doesn''t make the gun fights any more tense it just makes them frustrating due to having to use 400,000 bandages for 1 gunshot wound. Speaking of frustrating, it feels as if they made the guns less accurate and even after upgrading an AK74 to max for accuracy it still wasn''t hitting shit at 30 yards. \n\nover all I tried to enjoy this game and', 'Very Positive', 81.43, 11.98, 12.00);
INSERT INTO reviews VALUES (484, 20530, 1496, 'play it with "Dash Faction" - a community launcher which fixes a lot of things and makes the game better playable on modern hardware. it also give u widescreen resolution etc. \nvia ingame console u can change the fov and weapon fov, but for some guns the player model isn''t rendered if using higher values than default. \n\nwithin the installation window there is an option to use the dash patcher version straight over the steam version, so basically if u launch the game thru steam - it starts the pa', 'Doesn''t hold up. Balancing is completely wack once the mercenaries show up, the story ends super abruptly, and it barely even uses its own gimmick.', 'Very Positive', 85.36, 1.12, 21.72);
INSERT INTO reviews VALUES (485, 20540, 863, 'The best strategy game of all time for....still relevant today...the one I return from time to time....they dont make like this anymore', 'No online multiplayer option. Unbelievable!', 'Very Positive', 93.86, 307.35, 1.78);
INSERT INTO reviews VALUES (486, 20550, 592, 'I dont care what anyone says, this game is my childhood', 'It''s a drastic downgrade from the first one, only play it if you wanna know how it plays like, the plot is bad, the gameplay is bad, the level design is bad, the vehicle sections are either pretty bad or just some stupid rail shooter levels and to top it of, the destruction has been tuned down to being merely a gimmick.\n\nThis is by far the worst game in the series, I don''t think it has much redeeming qualities... \n\nThe only reasons to play this game is if you''re a completionisit, a curious minde', 'Mixed', 52.70, 1.23, 3.62);
INSERT INTO reviews VALUES (487, 20570, 953, 'The game perfectly captures the Warhammer 40K atmosphere with intense battles and moral choices that shape your squad’s loyalty. A must-play for fans of the lore and dark storytelling.\n\nRating: ★★★★☆ (4/5)', 'Campaign pull across is pathetically managed, if you think, hey i''ve completed Dow2 i''ll get the expansion, that''ll be fun, wrong.  you go from an elite killing machine to losing all of your good kit and being easliy killed by chaos cultists in h2h. Enemy health has skyrocketed and its neither fun, nor interesting to play. avoid.', 'Very Positive', 89.61, 2.35, 3.55);
INSERT INTO reviews VALUES (490, 20820, 458, 'It is a brilliant game. Most likely the definitive breakout/arkanoid game there is. It fixes my gripes with the original formula of these games (slow pacing) while adding more elements to it. Great bosses and a good music/artstyle makes to boot.', 'Brick breaker games are hard to get right, and this one doesn''t get it right. Half the game is just holding "blow", \r\npretty much no strategy involved. Fun for the first half of each level, then extremely frustrating as you wrestle with the balls to break the last blocks. Boring and unispired level design.', 'Overwhelmingly Positive', 95.63, 2.85, 1.08);
INSERT INTO reviews VALUES (491, 20900, 19370, 'When I first played The Witcher, I was in middle school and I had pirated the game. Like most middle schoolers, I wasn’t very smart and the only thing I really looked for in a game was how many bad guys I could murder. I finished the game and quickly forgot about it. Only after I was in college did I realize to the full extent the awful choices that I had made during my first playthrough of The Witcher. My crimes were beyond description. I killed street dogs and innocent travelers just to loot 2', 'I''m trying to play the witcher the 1st game but every time I beat and finish the intro chapter, my game won''t load the next chapter. I tried to refund it but because it was over 2 hours of play steam won''t let me. I just want to play the game i bought or get my money back because i can''t play it.', 'Very Positive', 85.55, 58.03, 8.35);
INSERT INTO reviews VALUES (492, 20920, 24668, 'Those who skipped Witcher 2 and played Witcher 3 are seriously missing out on a great story and characters. The gameplay is a bit outdated and difficult to get used to but overall it''s still a fantastic game. Trust me do give it a try. You''ll fall in love with this game in no time.', 'I remember beating this and while the story was very good (MUST know the lore), I just didn''t really enjoy the game overall. It was more of the combat, game mechanics and overall game play than anything else. A lot of game fads at the time were thrown in like Quicktime stuff senseless quests and alchemy that really wasn''t that useful. It was pretty tedious going back and forth with some of the side quests and the combat was clunky and somewhat worse than the original game.\n\nSum: Other than the g', 'Very Positive', 88.05, 17.53, 20.08);
INSERT INTO reviews VALUES (493, 21010, 356, 'bro this old game worked on modern PC from first try AAAND IT HAS CONTROLLER SUPPORT !!\n', 'This is just part 1. As a standalone game, it''s about 3 hours long. Technically you could play the full game as Rorschach or as Nite Owl separately but it''s not worth it. The game is very repetitive, no real diversity in enemies and the combat is simply fast punch, slow punch or dodge, very simple. It''s a promotional game, what is there to expect.', 'Mixed', 69.94, 1.48, 3.17);
INSERT INTO reviews VALUES (494, 21030, 145, 'its very fun not as many missions as the first one but still good. Cant belive games came out in 2009 they look amazing for the time 7/10. plus you can beat it before the 2 hour mark so you can refund it. It is basically free.\n7/10', 'batman arkham if it suuuuuuuuuuuuuuucked\r\n\r\nthe gimps having belly jiggle physics was amusing at least', 'Mostly Positive', 74.48, 1.68, 2.08);
INSERT INTO reviews VALUES (495, 21090, 7105, 'Game is fun thus far, but has some sort of FPS bug. If your going to get the game, follow this guide, otherwise your likely not going to be able to get above 40FPS\n\nhttps://steamcommunity.com/app/21090/discussions/0/343785380897389173/', 'The ghost child won''t get me a beer when I tell her to.', 'Very Positive', 93.46, 12.55, 6.30);
INSERT INTO reviews VALUES (496, 21100, 2904, 'This isnt that bad as people say. It did good job at gameplay, but bad at graphics and story. Horror element is better in previous games. It had some parts that scared me a little bit. I remember in the first fear when Alma apeared in garage, it gave me hearth attack. 7 out of 10. Sorry for bad english.', 'An awful way to kill end a franchise. \n\nEverything about this game is amateurish. It plays like a mediocre fan-made game, whose dev team never really understood what made F.E.A.R. good in the first place. It feels like they took any element they could from other games in the genre, to throw away the most generic and uninspired shooter you could defecate in 2011. \n\nThis game has nothing interesting to offer in the franchise. Everything is a downgrade from the previous F.E.A.R. games. The overall ', 'Mixed', 61.91, 0.35, 6.25);
INSERT INTO reviews VALUES (497, 21110, 606, 'Becomes really bugged on modern systems. In addition to the fact that the well-known .dll fix has to be applied for it work at a proper FPS at all (just like with the base game), this expansion will refuse to load some saves altogether unless you switch the video settings to medium or lower. To add insult to injury, some areas make it impossible to save, freezing the game as soon as you try to do so. Not a bad expansion, but these problems make it less fun.', 'It''s a great addition to the basic game. More horror, more amazing gunplay. There''s not that much new content, it follows mostly the main game.\r\nShame that I have to drop a negative review. Optimization is a disaster. It''s nearly unplayable and frustrating.', 'Very Positive', 85.64, 4.32, 4.25);
INSERT INTO reviews VALUES (8686, 21120, 410, 'This was one of the first FPS games I bought for myself when it originally released. I couldn''t get over how real the enemies felt. Over a decade later and it still has some of the most responsive enemy AI. Absolutely holds up! This expansion just adds to the overall package.', 'A filler episode of the FEAR saga. Weak story, weak level design. It still has the same horror vibes and great gunplay from the main game.\r\nIf only the performance wasn''t this bad. The game is unplayable between the FPS drops and the stuttering.', 'Very Positive', 85.12, 2.25, 4.63);
INSERT INTO reviews VALUES (498, 21130, 2917, 'Yet another nostalgic game. Glad to see that most of the lego games are on Steam. Sad there isn''t any achivements for the Lego Harry Potter games though.', 'This game corrupted my graphics drivers. I can not make this up', 'Very Positive', 83.61, 45.60, 20.40);
INSERT INTO reviews VALUES (502, 21690, 12843, 'This game opens with a close-up of Sheva''s ass. Mid way through, Jill rips her top open to let her girls breathe. It all ends with a shirtless Wesker in a volcano telling Chris how he really feels. It''s bizarre. Great game.', 'Apparently, saving progress is too advanced for this "modern" game. I spent two hours scouring forums, tweaking settings, and performing more troubleshooting than Chris Redfield does bicep curls. Did it work? Of course not...\nResident Evil 5, you were supposed to be a survival horror game, not a save file horror story.\nIf Capcom ever re-releases this game, I hope they include a warning: “Progress not included.”\n\nP.S. I now have PTSD every time I see the words "Save Successful." Thanks for that, ', 'Very Positive', 84.08, 20.23, 1.88);
INSERT INTO reviews VALUES (503, 21780, 580, 'Still a great game!!! brings back a lot of memories, wish they could remake or remaster this great game.', 'Didn''t age well. Wonder why Driver San Francisco is not on Steam, that game was a blast.', 'Very Positive', 87.76, 11.45, 1.00);
INSERT INTO reviews VALUES (504, 21800, 622, 'real gamers will remember this game in the 360 days', 'Play the russians and spam tanks, play the europeans and spam transports and engineers, play the US and fall asleep because they''re boring. The game isn''t as good as I remember, and it has a lot of really annoying jank.', 'Very Positive', 81.19, 3.10, 42.43);
INSERT INTO reviews VALUES (505, 21980, 1547, 'Before Red Dead Redemption There was this.', 'Have to go into audio settings and change your audio devices'' default sound format to DVD quality just so this POS doesnt crash on start. Insane that its been on steam this long and Techland''s lazy azz hasnt gone back and fixed this since 2009.', 'Very Positive', 82.55, 20.40, 4.25);
INSERT INTO reviews VALUES (506, 22000, 2398, 'I''m surprised EA never bought and destroyed this game with in app purchases pay to win and ads.', 'World of goo 2 is on the epic store only', 'Very Positive', 92.70, 10.65, 3.28);
INSERT INTO reviews VALUES (507, 22100, 1978, 'Good game, but both "Mount&Blade Warband" and "Mount&Blade 2 Bannerlord" are better versions of the same game (the mod list might differ, though)', 'why does this gmae lok so old bro is this made in 2008 or something??? lol wtf step it up dude', 'Very Positive', 91.15, 2.33, 0.73);
INSERT INTO reviews VALUES (508, 22120, 1393, 'Penumbra: No combat edition.\nA continuation of the storyline that started in Penumbra improved greatly in comparison to its predecessor by removing the awkward combat, while simultaneously deepening the creepy atmosphere that was later distilled to near perfection in Amnesia. Instead of fighting, running away and cowering in closets is the new modus operandi to get past the few horrible things separating us from the sometimes obtuse puzzles that make up the second half of the Penumbra formula. D', 'trash 2', 'Very Positive', 93.75, 9.47, 10.12);
INSERT INTO reviews VALUES (509, 22130, 310, 'Very enjoyable strategy even with crude graphics on modern standards.', 'This game is not worth buying now.   After playing it a time or two it now cheats as the AI player does things impossible if a Human controls the countries.    An example is the Italian in a game landed 20 plus divisions in Palestine without the British fleet in the Eastern Med even engaging the ships or seeeing them even after they land the troops on the way back to Taranto.   \nAfter that the German Player invaded England with out the UK fleets or ships seeing the ships, attacking the ships unl', 'Very Positive', 84.19, 589.63, 655.60);
INSERT INTO reviews VALUES (510, 22140, 494, 'If you had a sinking feeling of abandonment after solving the final puzzle in Penumbra Black Plague, this is basically a quick fix to what might actually be a larger problem in your life.. \r\nRequiem is a short puzzle-focused DLC that adds a conclusion (sort of anyways..) to the ending of Black Plague. To put it bluntly, this is a rather mediocre DLC that could easily have been way better had the writing been sharper and the puzzles felt less arbitrary. Since this is bundled together with the res', 'Even if you count this game as DLC to the 2nd Penumbra game, this game sucks. It has minimal lore and plot, it has little to no explanation of what happens and it somehow doesn''t continue the story in any way (no spoilers)\r\n Tuurngait or some mutant kills Philip and Requiem is his death hallucinations\r\nThe game contains no enemies, has much less intense moments and mechanics...\r\nIt''s very short, trimmed or even cut.\r\nIt was mediocre, but the build up of the Black Plague created killed it with no', 'Mixed', 51.82, 7.38, 6.30);
INSERT INTO reviews VALUES (511, 22180, 1792, 'Played this one in October 2024.\nThe game was really amazing, It had a little bit of everything even though most of the things were puzzles, gotta say I loved the idea of killing the monsters first but after a while the game wasn''t "horror" anymore, the only thing that was slightly really horror was the worm monster and the chases scenes.\nFrom what I''ve heard there were supposed to be three episodes or games but they only made two?\nI will check them out and play them.\nOverall it was a really goo', 'This game has an incredible atmosphere and an amazing soundtrack. The menu theme is incredibly powerful, and the story is interesting. The morse code puzzle is insanely creative. \r\n\r\nI''m giving this a thumbs down because the gameplay is that bad. Early 00s jank is one thing, but this may in fact be the worst combat mechanics in any video game I''ve ever played. The drag/click system is just outrageously clunky, and hiding from the 100 dogs you run into inevitably results in getting caught at some', 'Very Positive', 88.84, 3.62, 9.30);
INSERT INTO reviews VALUES (512, 22200, 1373, 'Zeno Clash is a relic, a fascinatingly ugly experiment in first-person brawling wrapped in dated Source engine tech. Its surreal aesthetic and brutal combat offer a jarring departure from convention. Yet, it exists now mostly as a curiosity, a node in Steam''s network designed to funnel you towards bundle purchases. Play it to experience the weirdness, but recognize it as digital taxidermy – interesting to look at, fundamentally dead, and propped up by a system that values your engagement far mor', 'I expected violence, but not animal cruelty.\n\nThe first thing the game had me do was kick a bunch of innocent chickens. Shortly after, an NPC tears the heads off multiple chickens and I was required to shoot their headless bodies as they floundered around.\n\nThis may not bother most people, but it is not something I want to see in a game, and I *definitely* don''t want to be required to partake in it to advance in the game. I would not have purchased it if there was any indication of this on the s', 'Very Positive', 89.08, 2.22, 0.28);
INSERT INTO reviews VALUES (513, 22230, 1718, 'I''m ROCK hard brother 10/10', 'Sort of a tower defense game, sort of a physics puzzle solver. You are a rock and you are trying to roll down a ramp down to a goal while people try to stop you or break your rock. The aesthetic is fun--kind of a cut-paper theater thing that goes through historical eras, a little like Monty Python animations. But the gameplay itself is tedious and repetitive. Controlling the boulder isn''t fun because it''s slow and unresponsive (as a big rock would be). And setting up defenses gets chore-ish afte', 'Very Positive', 91.91, 29.30, 4.07);
INSERT INTO reviews VALUES (514, 22300, 9249, 'Played this after new vegas and can''t understand the hate it gets... Great story, great gameplay, the game crashed like twice in my entire playthough. Overall great game!', 'Unplayable without extensive modding on any operating system past windows 7, This is contradictory to needing windows 10 or later versions to receive continued updates from the steam client. Will crash every five minutes, and in between crashing will suffer from audio and visual bugs. Either patch the game or take it off the steam store.', 'Mostly Positive', 79.87, 9.35, 79.13);
INSERT INTO reviews VALUES (515, 22310, 820, 'Genuinely one of the worst games I have ever played. If "The Room" were a videogame, this would be it. It is so bad it is entertaining! The short playtime (less than 2 hours to beat the campaign) helps make this more palatable. 1/10 (But I recommend you play it!)\n', 'there is a lot wrong with this game but the bug i found that killed it for me was where the game cuts in and out of the program its self making it unplayable', 'Mixed', 69.15, 1.58, 0.33);
INSERT INTO reviews VALUES (516, 22320, 16399, 'Please remaster this game Todd!!! This was my favorite game as a kid and I would buy this 100 times like you wanted us to do with Skyrim! Give the people what they want. Morrowind remastered.', 'You have to read, no quest markers, the directions are sometimes wrong, and mods have fixed all these problems for decades. Don''t play if you want to discover some 80% of the Elder Scrolls lore and have to actually learn how to play as a character since it''s not a combat adventure. Magic system is far too expansive with far too much freedom and acceptable abuse, especially when you can''t strip enchantments off things but have to actually learn the spells to apply, and grand souls are so rare it''', 'Overwhelmingly Positive', 95.62, 72.78, 105.77);
INSERT INTO reviews VALUES (517, 22330, 30887, 'Im just here reading comments, hoping you young guys got the inside scoop on the remake. i''m 38 years old and it kinda feels like this game and ES6 may be the last games i enjoy. Not sure yet if that''s from me aging or the quality of games with good story telling has gone down the crapper. Prolly both.. Sure hope they put this out soon!', 'Poorly optimized game with a boring setting, uninteresting plot, and a broken level scaling system that makes the game unplayable long term', 'Overwhelmingly Positive', 95.58, 34.23, 259.30);
INSERT INTO reviews VALUES (518, 22340, 1539, 'In order to get the Steam version to not crash in the prologue I had to torrent an iso of the retail CD version (which runs even worse), install the fan made patch (which isn''t compatible with the Steam version because BS legal reasons, or at least the patch I found), play past the tutorial, and then copy the save to my Steam directory.  It''s been said that the GoG version is better so do with that info what you will, I myself am a masochist.  If you''re tech illiterate, then you''re best off just', 'DO NOT BUY THIS ON STEAM BUY IT ON GOG, PATCHES DON''T WORK ON STEAM VERSION YOU CAN''T FINISH THE DAMN GAME THEY ROBBED ME OF MY VICTORY', 'Mixed', 62.70, 20.38, 34.88);
INSERT INTO reviews VALUES (519, 22350, 1480, 'Nechayev is down, get him back and moving again!', 'Brink was supposed to be revolutionary. The graphics, weapon customization, and parkour system was never seen before and everyone''s jaw dropped. I remember staying up late at night as a kid waiting for it to install on release day, only to be greeted by a buggy, unoptimized mess. Looks like the devs had focused too much on the flashy aspects, and not on actually providing something playable (which as I reflected on it after, made sense that all the press releases and demos focused only on the pa', 'Mixed', 55.74, 37.42, 14.17);
INSERT INTO reviews VALUES (522, 22370, 28214, 'Nestle (enclave) got mad I was selling water that wasnt stolen so I blew up their operations base and exploded their chatgpt president, w game', 'Impossible to play. I literally got it, installed it, hit play and it simply won''t run. Took the time to look online for a solution and everyone on the internet seems to have a different issue with this game to run.\n\n The fact that you guys have for sale a game that is not fixed to run on a modern computer is a total scam. Will refund for sure.', 'Very Positive', 80.16, 29.23, 0.25);
INSERT INTO reviews VALUES (523, 22380, 146959, 'Very good game. a lot of choices, outcomes, funny dialogues, can be good, bad, or neutral. Unfortunately the game won''t allow you to kill children', 'How are there so many positive reviews when this game is basically unplyable thanks to crashes, infinie loading screens, and corrupting save files!??!?', 'Overwhelmingly Positive', 96.26, 141.67, 50.58);
INSERT INTO reviews VALUES (524, 22450, 540, 'I would like to thank the absolute state of the gaming industry for making me dig through the past and unearth games from before the clown ages.', 'I can see the appeal for an older title and why others would like it, and if i''d played it at the time it was released, sure i''d probably have loved it...but now it just seems a bit boring, clumsy and repetitive from the get go for me unfortunately, nothing really inspiring me to push on or care about what is happening.\r\n\r\nProbably better if the co-op was still a thing!', 'Mostly Positive', 73.33, 14.32, 1.80);
INSERT INTO reviews VALUES (525, 22500, 192, 'A delightful draught of fantasy tropes, compelling card effects, and simple addictive play.', 'I will remove this negative review only after you at least remove 5 machine activation limit. Obviously I would prefer no DRM whatsoever but to force people to email you to request renewal needs to change. Even if it''s old game and DRM, you still sell it today.', 'Very Positive', 85.94, 8.35, 0.52);
INSERT INTO reviews VALUES (526, 22600, 1823, 'If worms has a million fans, then I am one of them. If worms has ten fans, then I am one of them. If worms has only one fan then that is me. If worms has no fans, then that means I am no longer alive. If the world is against worms, then I am against the world.\r\n\r\n-Sun Tzu', 'There''s only 2 Worms games worth playing:\nWorms World Party for 2D\nWorms Mayhem for 3D\n\nTeam 17 peaked with those two games and every other game is just weird experimentations with an online community doomed to die within a year of release.\n\n', 'Very Positive', 84.91, 33.33, 26.33);
INSERT INTO reviews VALUES (527, 22610, 474, 'When this game came out I didn''t have the computer strong enough to run this game.\nNow I do.\nThe game is actually pretty good for what it is.\nA horror - sci-fi - shooter.\nGo here...shoot that thing over there...collect that there and so on....\nIt''s not a game that the spoiled generation would appreciate I suppose.\nThis game here you need to try if you love video-games for more than just the latest graphics and player count.', ' Misleading!! \ndo not be fooled. despite the clear title through extensive research i found no feasible way to breed the aforementioned alien. -80billion/10', 'Mostly Positive', 76.16, 9.30, 0.58);
INSERT INTO reviews VALUES (528, 22650, 163, 'the first game i ever bought on steam.  so why not give it a thumbs up after 15 years.  im not entirely sure if its good or not.  but hey.  for a dollar at the time of writing.  if you complain, im not sure what to say about you.  cheers', 'Not a game but a mess,\nCamera is a joke. Aiming is everywhere. Optimization, don''t know what is it.\nFrame drops to 0, input delays, firing gun without mouse input, mic problem on solo/disabled (this is a guess because background mic on off sound), do not know what cause what and yet to find. Replayed a lot of locations (couldn''t move thanks to frames and needed to reload etc.) and probably try to finish and waste more time because already wasted enough :/\nMehh just mehh\nEdit: After finishing the', 'Mostly Positive', 71.78, 2.78, 7.58);
INSERT INTO reviews VALUES (529, 22670, 154, 'What a way to wrap up a massively enjoyable trilogy reboot series!  Team17 really brought the story telling to another level in the final installment, got me fully invested and truly gripped my full attention.  To be fair, there are certainly a few spots of jank specifically in Descent with some awkwardly executed Resident Evil style camera sections, but nothing egregious enough to take away from the overall solid gameplay.  I''m glad I finally managed to finish this series (albeit about 15 years', 'If having a good time was a disease, this game is the cure', 'Mostly Positive', 71.43, 4.93, 4.72);
INSERT INTO reviews VALUES (532, 23310, 1761, 'Absolutely love this game. A shame you can''t buy it anymore. Totally unique, it did not deserve its fate.', 'Don''t pay a penny for this.\n\nNot sure why this game is highly rated by anyone. The characters are forgettable at best and the protagonist is downright unlikeable. The game prefers to keep the player in a state of guessing what the lore might be as opposed to showing or telling how the world and setting are supposed to work and on the rare occasions that explanations are given, they come in the form of clunky, expository dialogue (really monologues with other characters present but not contributi', 'Mostly Positive', 79.27, 151.42, 2.28);
INSERT INTO reviews VALUES (533, 23380, 136, 'match 3 game with some rpg leveling', 'Game kinda sucks. I was thinking that it would be better with it being a square/popcap colab, but it''s not.', 'Mixed', 58.82, 122.35, 0.67);
INSERT INTO reviews VALUES (534, 23400, 154, 'Childhood memory.', 'Old and Broken', 'Very Positive', 83.12, 18.25, 0.47);
INSERT INTO reviews VALUES (535, 23420, 140, 'I first started off playing startegy games using hex games, then with my first computer when I played a demo of CIv 1 for the Atari STE. Since then I have played most of the TW series. Especially countless hours on Rome Total War especially modded and yes I like Rome 2 with mods. \n\nRecently this year I have started to get into the Paradox titles starting with Crusader Kings 1. \n\nI therefore recomend Europa Universalis: Rome - Gold Edition very much.\n \nIt''s Ironic to think that this game has cont', 'it continues to crash', 'Mixed', 60.71, 37.40, 95.17);
INSERT INTO reviews VALUES (536, 23450, 382, 'Do you love the Roman empire?\nDo you love building cities and manage them but on a simple level?\nDo you love to bring the glory and might of Rome on those filthy barbarians every morning?\n\nThen why are you still reading this? GO PLAY GRAND AGE ROME ! \n\nHighly recommended!', 'This is not working with Windows 11, neither in compatibility modes.\nDownloaded the missing DLL files (which i will never use for anything i suppose), tried everything for an hour now.\nThis is shouldn''t be sold here anymore.', 'Mostly Positive', 74.61, 261.88, 0.93);
INSERT INTO reviews VALUES (538, 23460, 101, 'my childhood', 'Fairly run of the mill point and click adventure game.\n\nGraphics are good enough, although the framerate can be quite poor.  Characters are good enough but very cliche.  Writing is good enough.  Puzzles are good enough.  Loading times are irritatingly slow.\n\nAll in all everything about this game is good enough, but there''s nothing to make it stand out.  A competent but unremarkable adventure.', 'Very Positive', 80.20, 0.25, 9.22);
INSERT INTO reviews VALUES (539, 23490, 442, 'Tropico 3 is a mirror reflecting our collective comfort with authoritarianism as long as it happens to someone else. Its entertainment value derives precisely from the psychological distance between player and consequences—the same mechanism that enables actual dictatorships to function. You''ll enjoy it most if you don''t think too deeply about why you''re enjoying it.', 'You can re-bind all of the hotkeys except the ones that I most want to be able to re-bind; the ones that pan the camera; you have to use the arrow keys. There is a wall on the left side of my PC desk; this means that I would have to insert my keyboard into the wall to be able to play this game comfortably. You also can''t disable edge-scrolling, or scroll by holding the middle mouse-button, & there is no ''hold to scroll'' button that could be bound to the middle mouse button. The game has no sex a', 'Very Positive', 90.05, 16.32, 0.28);
INSERT INTO reviews VALUES (540, 23500, 241, 'Puzzle Quest: Galactrix offers an engaging blend of match-3 puzzles and RPG elements set in a sci-fi universe. The hexagonal grid and directional gravity add a fresh twist to the gameplay, enhancing strategic depth. While the variety of mini-games and ship customization options provide depth, some players might find certain mechanics, like the leapgate hacking, a bit repetitive. Overall, it''s a fun and challenging experience for fans of puzzle-RPG hybrids.', 'Game crashes constantly on Windows 11, apparently it runs on .net 3.5 runtime so it''s old and buggy', 'Mixed', 46.47, 58.22, 38.42);
INSERT INTO reviews VALUES (541, 23530, 633, 'Yall don''t fw Earth Defense Force like me. Forever doomed to live in the shadows of helldivers 2', 'The battles go on forever and the enemies take forever to die.\n\n5/10 I didn''t really like it. 🗿', 'Very Positive', 87.36, 4.22, 3.13);
INSERT INTO reviews VALUES (548, 24200, 116, 'I''m a big guy for character customizations. More than anything else i have a sort of nostalgia for this game.', 'Good combat. Worst endgame I''ve ever seen. Extremely pay to win and very predatory, gambling addicts beware. If you want some mindless superhero action it''s good,\n\nBUT that''s all you''re getting unless you dump 1k+$ or years of dead content grind + 100$, plus you need to be enslaved by a league to get sizable buffs. You won''t be taken to any content that isn''t pure faceroll if you didn''t meet these conditions. Also devs might break your powerset(class) in any given hotfix so you have to pay to ch', 'Mostly Positive', 70.69, 61.38, 1830.83);
INSERT INTO reviews VALUES (549, 24240, 8362, 'Paayday 2 child game.... look to cartoon grapfix to make kid player happy like children show.. payday2 cartoon world with rainbow unlike Payday The Heist with dark corridorr and raelistic gun.. Payday 2 like playhouse. Payday 2 playor run from Payday the heist fear of dark world and realism. Payday the Heist game for real man and not dumbass like hmmmm payday 2 playors, payday the heist very good players try hard always win whil payday 2 players cheat with perks.Payday the heist beter', 'This shit is impossible hard.\nCan''t finish 1st mission on easy.', 'Very Positive', 92.65, 18.62, 1.00);
INSERT INTO reviews VALUES (550, 24400, 319, 'Amazing game that needs a remaster. Impossible to play on modern systems', 'DO NOT BUY. The game''s unplayable on modern hardware and Windows 10/11. During the tutorial battle it hangs for me, I have an AMD GPU, that apparently also causes problems. This is criminal and the developers should be forced to either patch the game or remove it from Steam entirely, possibly refunding anyone who was only able to play the game for 5 minutes like I did before it hanged and then hanged again on further tries.', 'Mixed', 66.46, 8.42, 0.15);
INSERT INTO reviews VALUES (552, 24420, 441, 'Loved the game from when i was a kid, and returned to replay it a couple of times. This steam replay I just finished was, like, the fourth or fifth one, and I don''t regret it for one bit. \nIt''s a beautiful game of exploration and loneliness, wonder and challenge. \nThe soundtrack is amazing, the game mechanic of singing songs to "cast" the abilities blew my mind when i first played it, the art style and visuals still hold up till this day even though it''s quite old.\nIt is a project of love and pa', 'The game starts well with exploration in a quiet ambiance.\r\nBut the game play feels slow and sluggish when action starts, and the whole game lacks some rythm. There are no really equipment or level upgrades, so it''s more of a basic metroid vania.', 'Very Positive', 88.44, 17.85, 20.02);
INSERT INTO reviews VALUES (554, 24480, 214, 'The camera and mechanics might feel a little dated, it is still quite a bit of fun to play a game like this in Arthurian Britain.', 'I... I don''t why I let my self see this entire thing through.\n\nKing Arthur II is a barely functioning Total War like RTS with a light sprinkling of RPG elements. The game runs horribly and physically hurts too play (if you can get that far), along with graphics looking like they were created on a fancy potato. But while I do wish to never play this play again, that is not to say that this game didn''t have promise. The story isn''t half bad and a lot mechanics could''ve been fun; I reckon if this w', 'Mixed', 56.54, 90.80, 28.43);
INSERT INTO reviews VALUES (558, 24670, 842, 'all im going to say is\n\nhttps://www.youtube.com/watch?v=hAWbjBMhEq4', 'Trainz 12 doesn''t work well on modern CPUs. It requires a fast clock speed. Modern CPUs usually have slower clocks with more cores and threads, but TS12 isn''t capable of using the extras cores and threads. I assume it would work on a more expensive system with a fast clock, but if you have something like that, a later version of the game would probably be preferable. On an older CPU, like an i3, you probably need and earlier verion of the game.', 'Mostly Positive', 76.96, 3.82, 88.55);
INSERT INTO reviews VALUES (559, 24720, 3730, 'You know it''s a good game when it still has an active playerbase 16 years after release, without updates.', 'cant play online on steam, need to download it on ea platform, which takes at least 24h since they won''t allow you to contact them unless you have a 24h old forum question (most of the time), so in other words I paid for a incomplete game with no online features, the same you could get for free from piracy. So Ea is a very strong argument for piracy supporters, that''s all I''m going to say on the topic.', 'Very Positive', 90.67, 304.12, 28.83);
INSERT INTO reviews VALUES (560, 24780, 5041, 'Ok for any newer computer users, definitely use the advanced launch options and the game works normally without crashing.\n\nHere''s an advanced launch thingy I found off of reddit that worked for me\n-d:soft -intro:off -CPUCount:1 -f -CustomResolution:enabled -r1920x1080x32 -w', 'Good game but not treated right, no way to increase resolution, crashes frequently. Sim City 4 is showing its age and it would be nice to have a remastered version, this version simply isn''t worth the money, Game is awesome but dont expect it to look or run great on modern systems.', 'Very Positive', 81.15, 15.02, 4.17);
INSERT INTO reviews VALUES (561, 24790, 4022, 'Still the best online multiplayer strategy game and its 2025. Surprised no one else came out with similar.', 'CD Version is better. The update they put out for this nerfs you to oblivion in the campaign and gives the AI unlimited resources.', 'Very Positive', 88.69, 129.88, 33.07);
INSERT INTO reviews VALUES (562, 24800, 1379, 'It''s like a porno but they replaced sex with alternative history, time travel and Tim Curry.', 'Bought this game through steam 15+ years ago. It''s the only EA game I have installed and I just got randomly and unjustly banned by EA for violating their "User Agreement or Terms of Sale". I have absolutely no idea why I got randomly banned by EA and they won''t tell me. This game doesn''t even have multiplayer. I appealed the ban and they say it''s justified. This negative review is also justified. Thanks.', 'Very Positive', 86.22, 8.25, 49.27);
INSERT INTO reviews VALUES (563, 24810, 2417, 'Well, Steam only counts the time you played the version on Steam. But I played... phew... countless hours of this game back then in the EA Launcher. I still have it on DVD somewhere. I can only recommend it.', 'I bought two copies of this game for myself and a friend. Unfortunately, Steam uses the same CD key for every copy of this game, so we cannot play multiplayer. In Windows, resolving this involves editing the registry. In Ubuntu, this game must be run with the proton compatibility wrapper, so editing an emulated registry gets a little more tricky. I have not successfully used protontricks to edit proton''s registry for this game in this way, and really, this step should not be required anyway. If ', 'Very Positive', 94.46, 8.25, 1.02);
INSERT INTO reviews VALUES (564, 24870, 843, 'Shame you can''t get this anymore', 'The control realism is really bad, and the video intro of the car grid before every race is very annoying!', 'Mostly Positive', 71.17, 3.38, 11.18);
INSERT INTO reviews VALUES (565, 24880, 979, 'EA''s Grand Theft Auto James Bond Nazi Mod Type Game.', 'Video settings DO NOT WORK, you have to manually go into your config file and edit the changes yourself. Not a big deal, but im sure it will make some smooth brain refund the game because they cant fathom a quick google search.\n\nNo video/control options in the menu ingame; you can tell right away that this is just a straight up console rip with no effort put into fixing any bugs/optimizing for pc hardware. \n\nIts great to see this on steam, but this is a very lazy attempt of porting over an other', 'Very Positive', 92.03, 11.42, 0.18);
INSERT INTO reviews VALUES (566, 25000, 4540, 'This game is like ordering a pizza but instead of getting a pizza I got a ball of dough, a bucket of tomato sauce, a block of cheese, a cheese grater and directions to the nearest corner shop.', 'Game feels like unfinished mess. I was playing it way before, when it was just a tech demo with fighting system. And you know what? They fucked up the fighting system so badly. Parrying is now feels like d20, because 50% of the time it does not work. Plot is fucked up too. It''s worse than lvl1 side quests in MMOs, it''s literally not needed here. And the useless dialoge window pops up after every death, it''s annoying as fuck. The game feels like pre alpha that you''ve downloaded from itch for free', 'Very Positive', 85.18, 3.33, 0.85);
INSERT INTO reviews VALUES (567, 25010, 228, 'Dropkicked a wolf into a tree so hard it died', 'If you''re looking to play Lugaru, just buy Overgrowth. They remade this game within Overgrowth so you can just play it there. The original version is pretty bad. The combat is clunky, maps are ugly looking even for it''s time, sound effects are annoying, etc. It''s vastly inferior to Overgrowth''s Lugaru combat-wise. The story is the same old edgy crap. Turner is such an edgelord, god. He''s like a gary stu anime character.\n\ntl;dr - Just buy Overgrowth instead. It comes with Lugaru and 2 other games', 'Very Positive', 88.16, 1.92, 0.30);
INSERT INTO reviews VALUES (569, 25600, 102, 'From my child hood time playing this, to the music, and multiple dynamic ways to play this in not strict way. I love coming back to play this first one over and over to remember it again after a while, glad it had such along development over all and had so much detail put in too. Honestly wish the final book 3 ending was more open to different scenarios, but was still a fun game till the end anyways', 'Eschalon: Book I presents an intriguing premise that could have captivated modern players. However, the game suffers from the passage of time in several key areas. The interface is clunky and lacks adequate scaling options, making it feel dated. Additionally, the mechanics and overall gameplay can feel archaic, and the writing often comes across as amateurish, detracting from the experience.\r\n\r\nGraphically, while the visuals are decent, the heavy reuse of assets creates a repetitive feel through', 'Very Positive', 85.29, 56.40, 13.77);
INSERT INTO reviews VALUES (571, 25700, 144, 'very weird fun game ive played on the xbox360 but as a demo iits possibly been 8 or 10 years since ive played this game its odd kinda like the maw and spoition man i recomend this wacky game to play give it a shot if you want', 'Wasn''t a bad game but not worth the price tag and community is dead.  If you can get it on sale and play with friends then it''s worth $5 but otherwise I would skip this one.', 'Very Positive', 86.11, 0.47, 5.37);
INSERT INTO reviews VALUES (572, 25800, 905, 'getting the hang of it i guess. getting two expansions along with the game is great but it shouldnt be called complete when its missing two other expansions. still a good game though.', 'TOO LONG', 'Very Positive', 86.96, 428.40, 4.92);
INSERT INTO reviews VALUES (574, 25830, 1028, 'i say it plainly knights of honor is an awsome strategy game where you get to manage your own medievil kingdom. the game offers deep stratagy gameply, from managing resources and building armies to engaging in diplomacy and epic battles. the graphic design although old keeps me really immersed in the medevil wourld as well as the soundtrack, and the challenge of expanding your empire and outsmarting rivals keeps you hooked. plus, theres a lot of humor in the interactions between character that a', 'I love the game but not on Steam, why? it''s only updated to 1.3 and it should be 1.5. So going to refund and get it on the other site.', 'Very Positive', 91.83, 32.77, 1.17);
INSERT INTO reviews VALUES (577, 25890, 2694, 'eh, it''s a ok game\nwill any one even look at this?\nwhy...16 likes, so there are people who are looking at this thx', 'The game was originally designed to run on 32 bit machines.  The game freezes frequently on 64 bit machines.  Evidently, Paradox used to have an alternate version on their tech support site to allow for 64 bit machines but appear to have removed it so this game is now effectively unplayable on newer machines.', 'Mostly Positive', 77.58, 27.13, 215.68);
INSERT INTO reviews VALUES (578, 25900, 843, '💔I first played this game when it came out in 2008💔\n💔I consider it a legendary game of its time💔\n💔That''s why I recommend her💔\n\n', 'Late mid-game to end-game is flawed with ridiculous amount of enemy troops. It''s waaay to grindy. I honestly angry about spending 65 hours and not finishing it.', 'Very Positive', 87.31, 67.77, 65.20);
INSERT INTO reviews VALUES (579, 25910, 155, 'Great strategy game.  So many ways to play.  State against State', 'Difficult to understand this game. It feels like all nations are just overdriving army production.', 'Mostly Positive', 78.71, 15635.17, 9.22);
INSERT INTO reviews VALUES (580, 25930, 110, 'For those experiencing Crashes, Try run it in compatibility mode Windows XP ServicePack3. Since then I haven''t have a single crash. I''m still in windows 10.', 'Randomly crashes, very annoying to the point I just give up!!! Use to love this game.  Back to Cleopatra.', 'Mixed', 55.45, 24.48, 29.97);
INSERT INTO reviews VALUES (581, 25980, 628, 'Writing this purely because of all the noobs stating "unplayable because of difficulty" - no it is not. Is it hard? Yes. Do different maps require different strats? Yes. Some require you to turtle/level up and then go for dens, other make you go for dens right away.\n\nI beat this game multiple times and still come back every so often to beat it again because it is quite unique.\n\nIf you enjoy a challenge where strategy and thought is important because YOU are not the one beating things you have to', 'I just got the game in the 2024 winter sale and I cannot possibly recommend it. I just tried the 3rd mission like 5 times in a row and it''s completely impossible. I actually set a timer and I had 17 skeletons raiding my settlement 31 seconds in. I can''t build anything because every 20-30 seconds they send 5-7 skeletons and wolves to attack the settlement. It''s literally unplayable due to the super long build times. It literally takes like 10 minutes to build a ranger outpost, meanwhile your gett', 'Mixed', 64.01, 129.90, 4.20);
INSERT INTO reviews VALUES (582, 25990, 356, 'Ah Majesty. For those that don''t know this nifty little title, it''s a game that came out nearly a quarter of a century ago, back when the Real-Time Strategy genre was king. Majesty offered an alternate take. Not quite an RTS, as the player was never given proper control of the troops. The player is a king of some lovingly satirical version of a fantasy kingdom, responsible for building up his town and inviting heroes to come and inhabit it, with the promise of adventure and, of course, pay. The ', 'issue ; game has issues and works horrible i can'' seem finish a game', 'Overwhelmingly Positive', 95.22, 2.35, 5.03);
INSERT INTO reviews VALUES (583, 26000, 194, 'Was looking for a similar looking game of my childhood, found this instead.\nI don''t regret it, very fun game and easy to learn.\nCamera controls are a bit meh though.', 'A very poorly and boringly made game. Almost no story, poorly made camera and buttons.\nThe game seems to be made more for a joystick but it can''t be used.\nThe levels are repeated and it quickly becomes boring and you are immortal so you can''t lose, the only way to replay the level is if you haven''t found something, which is quite rare.\nThe levels are few and the additions do not make it more interesting.\nYou only eat animals and enemies, but you can''t do other things, which would have made the g', 'Very Positive', 84.02, 0.13, 4.35);
INSERT INTO reviews VALUES (585, 26500, 216, '16 years of dev support.', 'Dev decided to wipe everyone''s savegames.', 'Very Positive', 89.35, 16.73, 0.22);
INSERT INTO reviews VALUES (586, 26800, 3398, 'Ayo man, they got this game right, if you drink and you get drunk if you smoke weed and you get high play this shit, this shit call braid', 'Did you really delist the original, still fully functional version of Braid from Steam just to divert people towards buying the superfluous, more expensive remake? Bold strategy.', 'Very Positive', 91.11, 10.68, 4.78);
INSERT INTO reviews VALUES (587, 26900, 167, 'I lack thinking outside the box..', 'This isn''t a bad game, just not worth the price. I acquired it through a bundle, and I had fun for the most part, but quickly yearned to be done with it. \r\nThe selling point of the game, (as the name would suggest), is the physics, \r\nyet the physics can be rather iffy. There were times where the ball rides an invisible barrier \r\nthat is not even close to the drawing. Overall, steer clear of this one, but if you really want to play it,\r\nget it with the NOITA bundle.', 'Very Positive', 86.23, 0.17, 7.07);
INSERT INTO reviews VALUES (588, 27000, 541, 'If you''re thinking about playing this game ever, you should do it sooner rather than later. The engine it''s built on is so old that it''s impossible for the developers to ever update, so it''s doomed to eventually be completely unplayable as PCs progress past the ability to run it. \r\n\r\nI was able to get it running with minimal issues, and even if I did struggle, it would have been absolutely worth the time to me.', 'the story is really bad', 'Mostly Positive', 76.52, 6.03, 0.32);
INSERT INTO reviews VALUES (589, 27020, 209, 'I suspect that you will either love or hate this. And if you don''t love it, it is expensive for what it is.  I enjoy it very much but that''s maybe because I enjoy graveyards in real life.  I think this  very short piece of cinema (it isn''t a game) manages to capture that melancholic feeling of knowing we must die really well. \nTwo points worth mentioning: it won''t stop unless I press the "windows" key and then press "stop" on the steam screen.  And the subtitled song is in Dutch.', 'what even. No. No, I did not enjoy this, no, absolutely not. That song that plays is in such poor taste and is SO out of place. Really bad, not fun to look at, not fun to hear, no.', 'Mixed', 55.98, 1.15, 0.17);
INSERT INTO reviews VALUES (595, 27900, 121, 'If there was a title field, I''d to call the review "Prepare to die.recurrent".\nDespite some players considering this game a bad copy of Portal, it''s not. You don''t even have a portal gun! Well, definitely it''s poor made. Looks like HL1 age game. With better textures.\nBut.\nIt''s good game if You like puzzler FPS. This game lacks of balance, and the chance of Your death occurance converge to 1 while You being progress to ending. Mobs will kill You, traps will kill You, You will kill Yourself. So, p', 'Just don''t buy it, trust me.', 'Mostly Negative', 38.84, 3.43, 3.68);
INSERT INTO reviews VALUES (597, 27940, 206, '  I love this game with all my heart.  Dead Horde is a state of the art game with next gen graphics and game mechanics.  The resolution is at a sharp 480p with a smooth 10fps.  What I really enjoy about this game is the focus on player interconnectivity.  The game forces you to play with your friends, to make it a more enjoyable experience.  There may be a ton of bugs, but those just help the game shine more.  I reccomend this game greatly.', 'The game is OK but is repetitive. Go forward, if zombies appear keep shooting going backwards so they get in line and kill them all in the same spot, then continue move forward. You''ll get bored quickly.', 'Mostly Negative', 33.50, 0.45, 6.37);
INSERT INTO reviews VALUES (598, 28000, 2610, 'one of the best games of all-time... stuck in one of the worst games of all-time', 'I''d rather lick and kiss the sphincters of exhausted truck drivers and clean sweaty toilet seats in public restrooms with my tongue than play for another second. The only way I could vent my anger was by taking it out on my infant son—thanks for that, IO Interactive.', 'Mostly Positive', 70.15, 3.57, 36.88);
INSERT INTO reviews VALUES (602, 29180, 385, 'Great game. I got it on mobile first then here. The simple take on the "eat smaller thing and become bigger" game loop popularized by a nearly infinite amount of browser game gets a simple and gameplay changing twist. You have to expel/spend your inner mass, making yourself smaller, in order to move. Genius. So much fun for a quick session in the morning to start the day.', 'Beautiful looking game. One of the least enjoyable I''ve ever wasted time on.', 'Very Positive', 88.57, 3.75, 7.95);
INSERT INTO reviews VALUES (608, 29800, 1266, 'Granted steam only shows 1.2 hours, however played this offline during 2024 during the early part of the year on my spare time, EXTREMELY enjoyable and fun, engaging, and fast pace megaman legends-esk game play\\ sonic depending on your upgrades\\ play style. I really encourage to give this a try - two dollars is Easy for the amount of enjoyment you get.', 'Do not recommend, there are no achievements to be hunted and achieved and from memory kinda boring. \nFeel free to say otherwise but im good thanks.', 'Mostly Positive', 78.28, 1.18, 3.53);
INSERT INTO reviews VALUES (609, 29900, 321, 'DE, remaster this and put it in Warframe as a secret. Or resell it for $10, like something please this is such a fun game. It''s buggy, sure, but the bugs are all funny. The gameplay is still solid, story is entertaining, just fix the post processing and the 16:9 resolution please I beg you.', 'its a fun game to go back to but if you have a AMD GPU "DO NOT BUY THIS GAME". you can only play it if you have a Nvidia GPU, found that out after I switch to them.', 'Very Positive', 86.60, 6.82, 3.65);
INSERT INTO reviews VALUES (610, 31100, 185, 'I love it when the autistic cheese man wreaks havoc on the town with his freaky ahh dog\n\nSome puzzles were hard to complete but that''s probably cuz I''m stupid or smth\n\nAnyway 10/10 game it made me wanna get freaky with Wallace', 'Well, i didn''t like it. I thought it will be relaxing easy pastime, but i''m stuck on the first episode with the freeing the roboMouse. I dropped cheese under the bed, but the game wanted me to throw cheese at the officer''s helmet - but WHERE THE F*** I CAN FIND THE OTHER 2 PIECES OF GODDAMN CHEESE?\nThere was no cheese in the refrigerator or in the basement, it was lying with an Indian seller on the street, but i couldn''t take it! I didn''t find cheese anywhere else', 'Very Positive', 90.81, 9.30, 1.73);
INSERT INTO reviews VALUES (613, 31170, 428, 'French people were not real before this game invented France', 'It''s a point and click adventure game which had a brief uptick in the nineties and probably should have stayed there. The humor is pretty good, better than other humorous games. But the problem with these kinds of games is that the solution is always bizarrely illogical, like Grim Fandango, which means you have to repeat actions over and over, which kills comedy.', 'Very Positive', 88.55, 23.72, 4.67);
INSERT INTO reviews VALUES (618, 31220, 240, 'very good. but i wish that telltale game could buy poker night at the inventory or bring back the tf2 items', '\nI will never recommend a game where the devs force you to watch visual ugliness like Depth of Field, Motion Blur, Anti-Alasing and Film Grain.   All these ugly things that degrade your gaming visual experience.\n\nIn this case it''s film grain.  They seem to think that smearing dirt on your screen and not letting you disable it is a good thing. Glad this company isn''t around anymore, the less dev companies that force blur on us the better.', 'Very Positive', 93.33, 10.30, 0.08);
INSERT INTO reviews VALUES (623, 31270, 1203, 'Fun short visual novel with puzzles. Most puzzles are quite easy but some are pretty hard.  Story has horror/mystery & comedy elements. \nReminds me of the game "Professor Layton".\n\nCool hand-drawn style. Great voice acting & music.\nhttps://steamcommunity.com/sharedfiles/filedetails/?id=3388613080\nhttps://steamcommunity.com/sharedfiles/filedetails/?id=3389526672\nWorth checking out👍', 'Didn''t much care for any of the puzzles. I liked the story even though it was short and the artwork was good. But the puzzles were only difficult because the rules were confusing or because they lacked context. Otherwise they were all pretty easy. Only had to use a pen and paper on a few.', 'Very Positive', 88.45, 5.62, 3.38);
INSERT INTO reviews VALUES (624, 31280, 4615, 'If you do not own this game, your life is incomplete and you will never be able to fill that void in your heart. The game is that good.', 'son of a whore why didnt i buy both when i had the chance', 'Very Positive', 88.67, 6.05, 0.83);
INSERT INTO reviews VALUES (625, 31290, 810, 'The game deserves a definitive edition and new season.\nNot unlisting from the store... -_-', 'awful', 'Very Positive', 89.01, 13.92, 7.12);
INSERT INTO reviews VALUES (627, 31700, 199, 'I played the shit out of this game in the middle of the Costa Rican Rain Forest.  It was a split house, so there was a roof over the kitchen and over the bedroom, the middle of the house was open with a huge tree.  The sloths would come down the tree into the kitchen, took them forever to get down.\n\nAnd I would scare the shit out of them by screaming at this game ( not intentionally)', '아무 생각 없이 게임에 처음 들어가니 FPS로 적과 싸우는데 내 총이 머스캣이더라. 한방 쏘고 재장전해야 하더라. 이걸 들고 기관총 쏘는 적과 싸우라고? 제정신이냐? 한참 나중에 무기 변경 가능하다는걸 알긴 했는데, 이미 5번은 죽었다.', 'Very Positive', 85.93, 61.58, 0.07);
INSERT INTO reviews VALUES (628, 31800, 142, 'This game made me terrified of developing photographs.', 'This one is bad; one of the worst ones I have ever played (the other one being Secret at Shadow Ranch, which I would not recommend getting that one either. If you want to know why, check out my review on the Secret of Shadow Ranch, because there are a bunch of problems in that game too). The puzzles in this game are mind boggling, really frustrating, because most of them come without any tips or clues, leaving you to figure it out on your own. \n\nOne of the most infuriating parts in this game is ', 'Very Positive', 83.10, 12.42, 12.33);
INSERT INTO reviews VALUES (629, 31810, 304, 'My favourite part of Nancy Drew. I played it as a teenager and now as an adult, and it''s still great.\n\nNice plot and story, interesting side characters with their own stories and motivations, some mystery and an unsolved case in the past, an investigation with Nancy''s friends through the gameplay, and of course various puzzles.\n\nThe dolls in the game are unforgettable.', 'Played multiple other Nancy Drew games, but this one simply does not run on Windows 10. FPS drops makes playing anything past the first 10 minutes unbearable. To sell a game that does not run on modern operating systems is unacceptable.', 'Overwhelmingly Positive', 97.37, 5.10, 0.18);
INSERT INTO reviews VALUES (630, 31820, 200, 'i relate to Joy now (not at the end tho)', 'what I didn''t like:\n- awkward navigation\n- can only see the journal notes and task list by going back to the hotel room (important to check, as game Nancy doesn''t always see the same things I as player see)\n- unable to ask questions when I want to (even when there was a task to call Paula about it)\n- the requirement to play the stupid arcade games -- the final straw for me\nOn the plus side\n+ I learned about how to use a lathe\n+ the story line and characters were interesting -- I''m sure by the en', 'Very Positive', 93.50, 2.05, 8.15);
INSERT INTO reviews VALUES (631, 31830, 335, 'my favorite part was wanting to blow my brains  at the family tree puzzle', 'this is the fourth nancy drew game i purchase and complete as an adult, and it''s by far the least fun. the setting is beautiful and the story could be cool, but a lot of puzzles are really annoying and nonsensical to the point that it just feels like work. i had to look up many things (while in the other games i''ve only been looking up 1 thing). if you''re looking to play one of these games i would strongly recommend that you try another one, this one is more infuriating than fun.', 'Very Positive', 89.25, 12.53, 18.70);
INSERT INTO reviews VALUES (632, 31840, 240, 'One of the best Nancy Drew games out there. Great puzzles, music, vibes.. It''s an older game so the graphics aren''t great but I grew up playing these games so they are very nostalgic for me.', 'I wanted more orca :( but the puzzles were less fun and more tedious. not my favorite of nd.', 'Very Positive', 93.75, 15.18, 7.25);
INSERT INTO reviews VALUES (633, 31850, 234, 'Being the 15th Nancy Drew game that I''ve played, Ghost Dogs of Moon Lake had many wonderful qualities of some of my favorite Nancy Drew games! Hilarious dialogue between characters, great suspects, somewhat easy to solve clues, and a fun location to explore were all pluses! Not overly scary, but did have some elements of this near the beginning of the game. More chores to do than actual puzzles to solve in this game which for me personally required me to not need any cheats like in all of the ot', 'do chores for unlikable people simulator', 'Very Positive', 93.16, 7.73, 0.78);
INSERT INTO reviews VALUES (634, 31860, 180, 'Henry Bolet.', 'It is a terrible nonsense game', 'Very Positive', 91.67, 8.07, 20.47);
INSERT INTO reviews VALUES (636, 31880, 199, 'The coziest Nancy Drew game for me! It''s not as dramatic as the game description makes it sound haha\n\nIt has such a warm sunny vibe to it and the mystery feels very safe and  there was no pressure-inducing life-threatening puzzle in the end . It doesn''t feel as lonely or spooky as many other Nancy Drew games and we get to call Carson Drew for a change (I know Bess and George are Nancy''s BFFS, but they are literally almost in every game).\n \nThere is a nice balance between the "interrogating" part', 'Secret of the Old Clock is not one of my favorite ND games. Setting the game in 1930 for Nancy''s anniversary was interesting and well-executed, however most of the rest of the game wasn''t. There are some puzzles that are good, but a lot of them are frustrating and difficult to get through. There are a few good character moments as well, but not many. If you like the original books, it is an amalgamation of the first four, which is also not my favorite aspect. I have a long history of dislike tow', 'Very Positive', 89.95, 4.93, 14.40);
INSERT INTO reviews VALUES (637, 31890, 169, 'Great educational game! Lots of puzzles but you also learn so much about the ancient Mayan culture!', 'Certainly one of the weakest ND adventure, which involves a lot of backtracking, passing time to advance time in order for things to happen and endless phone calls, which help deepen the story a bit, but unfortunately all main characters remain shallow and unrealistic. I would only recommend this to people, who want to finish all ND games.', 'Very Positive', 88.17, 5.97, 4.87);
INSERT INTO reviews VALUES (638, 31900, 142, 'One of my favorite volumes to go back to. The ending is slightly lackluster, but the story throughout and puzzles/mini games are so chill and fun. Super fun being the first game to be able to play as the Hardy boys as well. It''s not as intense as some of the other games, but just so relaxing and fun.', 'Creature of Kapu Cave is one of the messiest Nancy Drew games in the entire series. The story is convoluted and confusing, and the motives and basically the entire mystery surrounding the culprit are only revealed at the very end. This leaves it impossible to solve the case on your own because the game essentially keeps the story hidden from you. I do not enjoy most of the puzzles in this game or the characters. The only saving graces, in my opinion, are the setting, option puzzles like necklace', 'Mostly Positive', 72.54, 27.57, 13.22);
INSERT INTO reviews VALUES (639, 31910, 164, 'This game is great. It''s my most played Nancy Drew game for a reason. The puzzles are well thought out, the setting and cast are charming, and the story is super fun.', 'I’ve played a handful of Nancy Drew games and enjoyed each one. I did not enjoy this one. Several of the puzzles were too challenging especially the chemical puzzle at the end. The ending was lackluster. You can pass on this one.', 'Very Positive', 81.71, 25.10, 27.40);
INSERT INTO reviews VALUES (640, 31920, 164, 'SCOPA!!!!!!!!!!!!!!', 'Annoying mini games.', 'Very Positive', 89.02, 18.50, 0.85);
INSERT INTO reviews VALUES (641, 31930, 191, 'I played this game with my 9 year old daughter. She thought it was a very good game and very adventurous. She liked the minigames and the puzzles. Some of them she thought were kind of difficult and didn''t enjoy, even on Junior Detective. There is a lot of busywork in the game that extends playtime. Overall, a good experience with lots of exciting parts but nothing scary or gruesome.', 'whoever made the ice and fox + geese puzzle should be in jail', 'Mostly Positive', 73.82, 12.55, 5.62);
INSERT INTO reviews VALUES (646, 32150, 327, 'Had this for years. Played in chunks . most played game in my library. keeps the mind sharp .', 'Phenomenal game; I never play it anymore because it occasionally crashes when I tab out of it.\n\nWould recommend if the bug were fixed, but there''s no sign the developer still cares.', 'Overwhelmingly Positive', 98.78, 459.58, 118.75);
INSERT INTO reviews VALUES (647, 32160, 129, 'Video games have yet to surpass this one.\n\nOkay for real though this game is disgustingly fun. I''d kill for it to have Online Multiplayer though.', 'Not worth it. The campaign only takes 45 minutes to complete. All you do is bowl against an ai zombie opponete for half a dozen games. Your unseen zombie opponet doesn''t scale. They''re just as hard or easy to beat in the first game as they are in the last. Unless you want to play another six games in a row there''s no reason to play it again after that. The powerups add a fun element to the game (either helping you or screwing over your opponet). But there''s no online multiplayer. Shared computer', 'Very Positive', 93.80, 16.23, 4.68);
INSERT INTO reviews VALUES (649, 32310, 181, 'Great game ! it follows the movie ,', 'I wouldn''t recommend this game to anyone.\r\nIt''s a classic point-and-click game - punishing, unclear, annoying to control.\r\nIf you don''t want to follow a guide then be prepared for hours of running around being lost. \r\nBetter click on everything you see.', 'Mostly Positive', 75.14, 0.08, 6.93);
INSERT INTO reviews VALUES (650, 32330, 1551, 'You can purchase a slave child who''s also the cheapest character in the game. What did they mean by this?', 'I got this game hoping to relive some of my childhood nostalgia and share it with my spouse, but we''re finding that the steam version has a LOT more trouble with characters being capable of navigating the level geometry. I don''t know why, I never ran across these troubles when I played it on Xbox 360 as a kid, but this steam port just doesn''t function. Several levels are vastly more difficult and even unplayable due to some glitch where characters simply cannot jump or move on certain ground sur', 'Very Positive', 85.24, 19.62, 5.45);
INSERT INTO reviews VALUES (651, 32340, 415, '(ASK ME ABOUT LOOM)', 'I didn''t like the writing.', 'Very Positive', 89.64, 8.00, 1.83);
INSERT INTO reviews VALUES (652, 32350, 354, 'I would like this game rebooted with modern tech to help better control the star fighter, same story, same missions just new tech..and maybe better control schema.', 'The sequel game, Jedi Starfighter is such a vast improvement it''s not even comparable. This game is not fun. Story isn''t interesting, characters are mid. Seriously just go out and play Jedi Starfighter.', 'Mixed', 53.95, 2.52, 6.58);
INSERT INTO reviews VALUES (653, 32360, 2888, 'Great point-and-click game, but the controls are overly complicated. Sometimes, even when I’m sure what to do, it doesn’t work because I’m using "Use" instead of "Give." Sometimes it’s "Push," and I’m doing "Pull." I know that’s how the game was originally designed, but I really wish there were an alternative option. Everything else—story, humor, puzzles—is perfect.', 'The Secret of Monkey Island was yet another game that is heralded as an amazing game that can do no wrong. And once again, I come away completely disappointed and wondering what everyone else was playing. This game took me 8 hours to complete and that was with liberal use of the hint system. I don’t know how anyone could have played this game before the special edition put in a hint system. Just about everything you’re supposed to do is so convoluted and illogical that there is no way you would ', 'Overwhelmingly Positive', 95.98, 9.08, 8.20);
INSERT INTO reviews VALUES (654, 32370, 21082, 'Kids, let me tell you a story about a game company made up of passionate gamers called BIOWARE, that once, were not EA slaves, and used to make artistic masterpieces. This game is one of those. A must play for any self-respecting rpg enjoyer. There are also mods out there - graphics, gameplay enchantments, widescreen fixes and more. KotOR is still kicking strong. Get it! Play it! Profit!', 'I am not signing Disney''s new Eula. I''ve owned this game for over a decade. let me play it without signing their "we can do whatever we want to you and you can''t sue us ever" contract. If you think that''s a joke, it''s not! someone who bought a Disney+ subscription took their SO to a Disney owned Restaurant and their SO died to an allergy attack the staffed assured them would not happen. Disney, when sued, tried to make the matter disappear by proving that the Disney+ EULA was signed by the griev', 'Very Positive', 91.21, 26.40, 59.70);
INSERT INTO reviews VALUES (655, 32380, 1319, 'Played this game when I was a kid on a Windows 98 and it''s just as gritty as I remember it.\r\nThis one isn''t just about nostalgia, I definitely feel like this is one of the best SW games next to Jedi Academy as far as story and gameplay are concerned. \r\n10/10', 'Don''t get me wrong, it''s good, I like the story and the actors for Kyle Katarn and Jan are great.  But the game is in desperate need of a remaster.  I didn''t grow up with this game and beyond the first couple of levels this is more of a pain to play and really shows it''s age.  I like to play this in short bursts because I generally like old games, I preferred dark forces'' gameplay but I would recommend outcast and academy over DF2 any day.', 'Mostly Positive', 79.68, 7.83, 3.73);
INSERT INTO reviews VALUES (656, 32390, 594, 'Ah, another important game from my childhood before Disney got their filthy hands on the IP  and made Star Wars squeal like a pig.', 'In 1998 Lucas Arts decided to release a game, where you can literally stuck in the dead end in last level if you will go in wrong direction. In 1998, the same year that saw releases of such FPS classics as Half-Life, Sin and Unreal. Game design and level design in this game is a massive step back even in comparison with original Dark Forces II. Sure, original game had some quirks with its maps, but overall it was a pleasant classic Star Wars experience. This game... this game isnt. Dont be foole', 'Mixed', 65.49, 6.52, 18.40);
INSERT INTO reviews VALUES (657, 32400, 1735, 'I would seriously recommend playing this version of the game, using "The Force Engine" port, over the Remaster.  Remaster is fine for what it is I suppose, but 40$ for an arguably worse looking experience to what has already been available for years first in the XL engine and now even better in The Force Engine is kinda lame.  The game looks way better with the original pixelart textures and cutscenes, the Remaster just kinda has that uncanny meh look to it for me.', 'Jabba''s ship is one of the worst levels I''ve ever played in a video game. Also in the fuel station level, having a door that completes the level glitch shut if you hit a switch more than once is dogshit game design. Idc if this game is from the 90''s, that doesn''t exempt it from criticism of bugs.', 'Very Positive', 89.16, 5.88, 3.57);
INSERT INTO reviews VALUES (659, 32430, 4809, 'If you''re a Steam Deck owner turned off from purchasing this game due to its "Unsupported" rating, don''t be. I played through the opening Darth Vader level, and everything worked great! The game and cutscenes ran smoothly. When I first booted the game up, there was an option to choose between Xbox and keyboard controls. Choose Xbox, and you''re good to go! For best video results, I recommend turning on FSR or forcing the game to run at 1080p. The Steam Deck can''t show 1080p, but I noticed a diffe', 'I requested a refund on the grounds that the mandatory EULA provided by Disney waives my rights to sue them for any reason. Given the wrongful death lawsuit filed by Jeffrey Piccolo in 2023 was attempted to be dismissed due to this same clause in a Disney+ subscription, I consider this game to be functionally unplayable.', 'Mostly Positive', 74.61, 0.37, 0.65);
INSERT INTO reviews VALUES (660, 32440, 13641, 'This isn''t just the greatest game of all time, it is the single greatest thing that has ever been made by mankind. This game might as well be the whole reason humanity even exists. Playing just a second of this masterpiece will change your life forever, the story telling is so beautiful, so captivating, so deep, so mind blowingly profound that it will have you smiling, laughing, crying, questioning everything you have ever known, and rethinking your stance on the meaning of life itself. The grap', 'Wonderful game. I love it. I really do.\nYou can hack and shoot your way through lovingly created Lego versions of all the Star Wars movies. There are extra areas in each level that can be accessed later when you return with new characters. The multiplayer is also very well done. The humour is spot on despite the complete lack of dialogue.\n\nStill, I really do not recommend getting this here. Disney''s newest ToS is required, and apparently signing those gives Disney a license to get away with what', 'Overwhelmingly Positive', 96.71, 1153.37, 3.83);
INSERT INTO reviews VALUES (661, 32450, 644, 'This game is a classic. It brings me back good memories when my parents were yelling in the background. 10/10 game.', 'Worse than the original. Half the game is Crystal Skull.', 'Very Positive', 81.68, 58.17, 24.55);
INSERT INTO reviews VALUES (662, 32460, 1409, 'Best of the bunch in my opinion (even with the notorious ending).\r\n\r\nAlso the best monkey island "remaster" because you don''t need to do any tricks to get voice acting to work on the superior original graphics.\r\n\r\nI mean, seriously, jesus... What''s with the "remastered" graphics. Very ew', 'Well, this was a really frustrating experience. Even though I had really good memories from playing this in my childhood, and I was really expecting to love this Special Edition (as I did with the first Monkey Island), it just wasn''t good.\n\nCompared to the first one, the puzzles of this one are really nonsensical and poorly designed so they''re impossible to guess (and that''s even though I remembered some of them!). I had to check a walkthrough and the solution often left me wondering how I was s', 'Very Positive', 94.46, 13.12, 7.13);
INSERT INTO reviews VALUES (663, 32470, 24448, 'Game is fantastic, however two people that I play this with have suffered appendicitis whilst playing. While unlikely, lighting doesnt strike twice and I believe there is a correlation.', 'I love EAW but this is completely unenjoyable! I''ve played for years but the difficulty is WAY too hard, i lose 10/10 fights. The AI takes over everything almost instantly. Good game but again its way too hard.', 'Overwhelmingly Positive', 97.77, 431.92, 12.80);
INSERT INTO reviews VALUES (664, 32500, 3009, 'Great game, botched PC port. Expect lots of crashes and having to download FPS unlocking patches.', 'I adore this game and would love nothing other than to fulfill my nostalgic needs. But please fix the crashing. I cant progress through the game after the first mission cause it crashes before the final cutscene when I steal Vader''s tie fighter. Please make a fix ASAP', 'Mixed', 59.99, 4.98, 0.58);
INSERT INTO reviews VALUES (665, 32510, 3748, 'my wife child left with nothing but this game. I turned to alcohol which did not fill the void. But lego star wars III filled the void like no other thing could. this game could make the saddest of gods weep with joy. My wife and son came back after seeing my joy and tried to take it from me. I murdered them both and continued to play this game until I turned to dust.', 'I will be one of the few to say this isn''t a very good game. Nostalgia blinds the many. But not me. The ground war levels are long, tedious, boring, repetitive, and thumb hurting. And some of the space missions are needlessly impossible. It is easier to complete one of them using the speedrun method than the intend one.\n\nHowever it is a Lego game so it isn''t completely terrible.', 'Very Positive', 94.45, 23.42, 47.68);
INSERT INTO reviews VALUES (666, 32610, 101, 'I am partial to delta force games as it was my first PC game addiction back in 1998. I like the delta force series games just because of the endless maps. Its not always about graphics, it''s about game play and how much fun you have playing.  I love games that have no boundries and you can hunt someone for miles before you finally get them. Plus all the close quarters maps where you seem to die every 2 seconds but get in a few kills before you die. My kind of game. I love the delta force series!', 'Broken game, requires a login to a dead website to do anything other than view the menu screen.', 'Mixed', 53.47, 9.22, 5.30);
INSERT INTO reviews VALUES (667, 32620, 305, 'Is that an enemy? Oh it''s a cactus. Is that an enemy? Oh it''s a cactus. Is that an enemy? Oh it''s a cactus. Is that an enemy? Oh it''s a cactus. Is that an enemy? Oh it''s a cactus. Is that an enemy? Oh it''s a cactus. Is that an enemy? Oh it''s a cactus. Is that an enemy? Oh it''s a cactus.', 'Not working properly, cannot understand the problem. Earlier it was working good', 'Very Positive', 89.18, 10.63, 32.88);
INSERT INTO reviews VALUES (668, 32630, 267, 'Everyone keeps talking about the singleplayer.... What?!?  The entire allure of this game was the online play.  TONS of custom maps that were painstakingly crafted by brilliant people.  All the maps you would try to create in the Mission Editor.\n\nThis game was amazing online. I can''t even begin to describe it and the amount of depth the Mission Editor added to a relatively simple fps.', 'This game feels like an alfa version of the first game. Textures are odd. Weird enemy animations. Something is off about the sound too.', 'Very Positive', 86.89, 1.03, 0.62);
INSERT INTO reviews VALUES (669, 32640, 162, 'My first real FPS shooter. Even had a progression system! Me and my dad played all the time back in the day. You''re still able to play but there''s a few small steps to take before, as the Novaworld servers aren''t up anymore. There is no real ADS unless you''re using a weapon with a scope. Great game 10/10, glad to see a new one coming out!', 'does this game able to play multiplayer?', 'Very Positive', 87.65, 12.38, 0.28);
INSERT INTO reviews VALUES (672, 32680, 233, 'Bring this back! great shooter', 'I indeed enjoyed Black Hawk Down, but while the base game felt like taking part in actual military operations, Team Sabre feels like a mindless action film. Obviously, being an expansion pack Team Sabre looks and plays like the base game, with the inclusion of a few more weapons. The main distinction is the addition of two new campaigns. While the Colombian jungles are a welcomed new experience, the Iranian missions feel rushed and recycled from the base game. Furthermore, missions are extremely', 'Very Positive', 89.70, 3.23, 8.03);
INSERT INTO reviews VALUES (677, 32750, 152, 'Oh this brings back some happy memories, I am not as good as I used to be, obviously I am old and slower now ! ! !  Still love it !', 'got a sysdump.txt saved and haven''t been able to play the game again.  don''t know how to fix it.', 'Very Positive', 90.13, 8.55, 321.37);
INSERT INTO reviews VALUES (678, 32760, 180, 'I played SO much of this game as a teenager, crazy good campaign and phenomenal multiplayer. If anyone out there remembers the 2000-2002 era of Tachyon clans I was in Phoenician Republic and later New Dawn. I still remember clans like Iconian Knights. Multiplayer is dead now obviously but imo Tachyon is still worth playing even now, the graphics hold up alright and the mechanics are still excellent., especially the "slide" function".', 'I expected Tachyon: The Fringe to be a lot more slower, simulator type of game but no its actually a pretty fast paced, action oriented game more then anything else. The game is, obviously, very old but there are some interesting things in it here and there. Mainly the story and the voice acting which is pretty well I did have some weird sounding voice acting but like it wasn''t cuz of the acting itself it just sounded as if there was something wrong with the audio you know? Like an audio bug or ', 'Very Positive', 90.56, 0.97, 7.42);
INSERT INTO reviews VALUES (679, 32770, 176, 'this game deserves a remaster', 'I think this game has malware. It crashed my PC and damaged my graphics card. Uninstalling ...', 'Very Positive', 90.34, 4.77, 2.03);
INSERT INTO reviews VALUES (680, 32900, 178, 'As old as Restaurant Empire II is, nothing on the market comes near to this game!', 'An example of a good game being rendered nigh-unplayable thanks to technology advancing. The core gameplay - managing a chain of boutique restaurants across the globe you build one piece of kitchen equipment and dinner table at a time - remains excellent to this day. The font for the user interface, however, is freaking tiny on anything but a non-HiDPI monitor, and it only supports a very specific set of resolutions. All that means is unless you''ve got an old monitor which doesn''t support HiDPI,', 'Very Positive', 80.34, 6.07, 4.40);
INSERT INTO reviews VALUES (681, 33100, 759, 'Game from my childhood; It''s short and sweet and a time capsule from the early 2000s when times were simpler.', 'Buy it on GOG. The developers here are gaslighting idiots, I''m refunding.', 'Very Positive', 94.73, 4.25, 1.53);
INSERT INTO reviews VALUES (682, 33110, 152, 'da', 'It is very hard to beat certain levels because aliens teleport continuously even when teleport machine is not in sight. So, if you spend time finding secrets or ammo, aliens will teleport continuously and you won''t have ammo to kill all of those aliens. I dropped this game and won''t return to playing it.', 'Mixed', 63.82, 27.57, 5.60);
INSERT INTO reviews VALUES (683, 33120, 528, 'I finished the first one and got this one when it was on sale. This game is a sequel to the first game but has many improvements over the first game. The story I guess is that there are aliens and you have to take them out again like the first one. In this one, you can get different weapons for each class you use instead of just one weapon in the game. You get pistols, shotguns, rifles, explosives, laser weapons, and other arsenal weapons compared to the first game. You can level up to use stats', 'I genuinely don''t understand how people give this a positive review when the original game has far better features and is an actual remaster, where this is the original game packaged in a way to be played on modern systems.\n\nThis doesn''t even go beyond 1024x768 which is what my broke ass was never lucky enough to use back in the day, I had to run 800x600 for most games I played to make sure I was getting perfect framerates. And this was the resolution I was running up until World of Warcraft and', 'Very Positive', 90.34, 3.52, 0.08);
INSERT INTO reviews VALUES (684, 33130, 270, 'Zombie Shooter is a short isometric sc fi zombie based where you have to stop an infection that has spread through a scientific base. It''s as if Serious Sam and Dead Rising were insectivated by the tangle of creatures that will come at you. Hordes and hordes of exploding blood and weapons to love and kill in this short zombilistic ride.', '"Congratulations, you have complete the game".\r\n\r\nWhatever Serious Sam critics think Serious Sam plays like, this is it. You run backwards and shoot hordes of enemies, except these ones are zombies with huge health pools and they just get bigger as the game goes on. At its core, the game is mindless. On a deeper analytical level, it is COMPLETELY mindless. I beat the game pretty much maining the mini gun and just holding mouse1... I did not die once but death is debatable when you have lives tha', 'Very Positive', 84.81, 10.80, 2.08);
INSERT INTO reviews VALUES (685, 33180, 159, 'Must play. We need more like that BUT WITH online coop.', 'В целом ок,но игра словно недоработана.Атрибут точности никак не влияет на меткость(что забавно),ну и самое неприятное,невозможность добраться до тайника в 12 миссии', 'Very Positive', 81.13, 14.67, 26.28);
INSERT INTO reviews VALUES (686, 33220, 2253, 'Great game, even better together. what a shame ubisoft completely cut out coop support.  use scc-lan-restore on github to restore coop functionality and use ZeroTier instead of hamachi for emulating lan since its newer, faster, and more stable.\n\nStill looking for the time to replay this game on pc, just wanted to post this to help others who also enjoyed this game in coop on xbox 360 in the past.', 'F*** Ubisoft. They shut down the game servers for Splinter Cell: Blacklist, one among a huge list of other games. No longer have access to all coop & multiplayer content & DLC, some of which I PAID $ FOR. Boycotting\n\n"Get Comfortable With Not Owning Games" - Ubisoft', 'Mixed', 67.87, 6.12, 21.83);
INSERT INTO reviews VALUES (687, 33230, 15935, 'right click ubisoft game -> go to properties -> general -> launch options -> add this line ''-skiplauncher''\r\n\r\nNow you''re no longer held hostage by shitty 3rd party launchers', 'Another classic game locked away behind a terrible and broken 3rd party launcher. Can''t even launch the game :(', 'Very Positive', 86.08, 25.70, 0.23);
INSERT INTO reviews VALUES (688, 33320, 1172, 'If i had to rank each PoP game-\r\n1. Warrior Within\r\n2. Forgotten Sands\r\n3. Two Thrones\r\n4. Sands of Time\r\n\r\nGameplay and parkour wise, best out of all. My childhood game, i will always cherish it.', 'Fully understand now why people want Ubisoft to bankrupt and shut down for good. It brought  all on itself. \nHere’s another story for its disrespectful customer service today: Last night by a mere chance, I am shocked to find this game along with the deluxe content dlc key I’ve brought several years ago can no longer be activated due to Ubisoft stored the DE dlcs on a server which Ubisoft one-sided decided to shut down 2 years ago without notifying a paying customer like me. So any of us who’ve ', 'Mostly Positive', 70.14, 4.80, 0.12);
INSERT INTO reviews VALUES (690, 33460, 1920, 'https://steamcommunity.com/sharedfiles/filedetails/?id=3012267225\n\nThe game works after following the above guide to bypass the Ubisoft launcher. I receive two errors for missing files after starting the game but it launches immediately after without issue.\n\nStill fun, glad I got to replay this.', 'I loved this game, it was my zen garden but unfortunately Ubisoft broke it. As of Nov 2024 update it is clear they still have no intention of fixing the game. As long as you require ubisoft connect to play From Dust do not waste your money. I can only hope one day someone will create a patch to cut out connect so it is playable again.', 'Mixed', 62.55, 4.93, 144.67);
INSERT INTO reviews VALUES (691, 33520, 444, 'The Best Tropico', 'Crashes on Win11, I''m really sorry :(', 'Very Positive', 87.84, 314.87, 0.23);
INSERT INTO reviews VALUES (692, 33530, 107, 'This is the best Tropico game they have ever created. Still my top favorite of all time games. I wish they would do a delux version of this edition. It is the most different of all the other games.', 'The game is worth the low price, but it requires adjustments to function properly.', 'Very Positive', 80.37, 49.18, 7.78);
INSERT INTO reviews VALUES (694, 33570, 408, 'Seriously, I have been waiting for a worthy successor to Patrician III for 22 years. I wonder if it''s going to happen in my lifetime. If there is anyone left doubting this game, just buy it.', 'A beautiful simulation of the golden age of trade in the Baltic - this game encouraged me to learn so much about the history of the Hanseatic League and what Europe looked like in the 14th century. \r\n\r\nThis older version is really lovely, and was way underrated in its time. It has since been replaced by successor product Patrician 4. That product is very similar, with plenty of quality-of-life improvements; so I recommend purchasing that unless you are approaching this with a collector''s mindset', 'Very Positive', 80.39, 302.75, 101.92);
INSERT INTO reviews VALUES (696, 33600, 480, 'Just as with music or cars, some things were better off before! Well today''s New game developers need to take a page out of this game''s book! How is it even possible that a game made years ago can be this incredible? It''s literally EVERYTHING an epic point n click adventure should be! It''s got dozens of scenes, even more characters, tons of hotspots, objects and puzzles. The storyline is interesting and the humor is just perfect. The graphics are excellent, dialog perfect and it''s a pretty long ', 'This game was a mess. Sometimes, it was a standard adventure game. Occasionally, you had to do things quickly (which the engine couldn''t handle), or you''d die. Too many puzzles were laborious to complete rather than clever. Many times you had to exhaust all conversation topics with every on-screen character until a new possibility would appear--again, laborious. At 91% in, I couldn''t bear to deal with the gruelingly slow Mayan dials and tiles, so I quit without finishing.', 'Very Positive', 89.38, 16.00, 8.68);
INSERT INTO reviews VALUES (697, 33610, 351, 'I hated the camera movement, but the game is classic broken sword which I loved. The 3D motion and controls took me a few hours to get used to but it was fun overall!', 'what are these controls', 'Mixed', 57.83, 14.78, 0.50);
INSERT INTO reviews VALUES (698, 33620, 191, 'This game is also realistic busting criminals and high speed. Great graphics and yes the driving is is fun. There are a lot of cases that needs to be solved and you get rated in stars maximum 5.\nDo not go wasting the stars. I do recommend this game.', 'Basically a Racing Game with the characters and a story from the German TV Series "Alarm for Cobra 11". It is a solid gameplay expirience but it dosen''t run good on Windows 10 and new PCs.\n\nDriving around and crashing in people is fun but too much crashes and tehnical problems.', 'Very Positive', 86.39, 0.20, 7.50);
INSERT INTO reviews VALUES (699, 33650, 213, 'I mean, you get a lot of puzzles for the price.  From Sudoku and link a pix to crosswords and wordsearch, etc.  Gets stale a little too quickly.  But what a bargain!', 'It''s a reasonably fun diversion, but there are a few things that make it so that I can''t recommend it. First and foremost being that it''s not too hard to find puzzles of a similar ilk online for free -- and often with better interfaces. (Just compare the Link-a-Pix in the game to the same found on Conceptis''s own website.)  The second problem is that some of the games aren''t really puzzles per se... showing the user a picture and asking them to memorize it for three questions isn''t a puzzle, it''', 'Very Positive', 87.32, 5.30, 58.38);
INSERT INTO reviews VALUES (701, 33670, 195, 'great story line, linear action, thought provoking turn based action', 'This early version of D3 is bug-ridden so I cannot recommend it, get D3:Reincarnation instead.', 'Mixed', 48.72, 336.67, 101.93);
INSERT INTO reviews VALUES (702, 33680, 822, 'A small piece of gaming history, akin to some of those old flash games of many years ago.  Solid little platformer.  As you can see, I have barely 1 and a half hours on it with all achievements, game 100% complete.  Worth dropping a fiver to the dev in my opinion.', 'WORST GAME OF ALL TIME. TERRIBLY PROGRAMMED EVERY TIME I ALT TAB OUT OF THE GAME I HAVE TO CLOSE OR MINIMIZE IT TO GO BACK IN. GAME IS NOT EVEN SCARY THE SCARIEST PART OF THIS GAME IS THE FUKKEN DIFFICULTY ITS SOOOO ANNOYING I HATE THIS GAME AND EVERYTHING IT STANDS FOR NEVER PUT YOURSELF THROUGH THIS TORTURE', 'Very Positive', 90.75, 1.50, 2.53);
INSERT INTO reviews VALUES (706, 33770, 170, 'Good game this!', 'Broken on Windows 10\n\nCan''t use cursor in the game. It runs, but when I click anything in the game it minimizes.', 'Mostly Positive', 76.47, 104.22, 0.13);
INSERT INTO reviews VALUES (708, 33900, 1619, 'Please add sex with Big Tiddy Goth Chicks', 'UI needs a little work.', 'Very Positive', 83.94, 0.57, 25.33);
INSERT INTO reviews VALUES (709, 33910, 148, 'This game was THE SHIT back in the days. It''s better to play Arma 3 or Arma Reforger from now on tho!', 'singleplayer sucks bc horrible AI\r\nmultiplayer dead', 'Mostly Positive', 73.65, 86.22, 18.15);
INSERT INTO reviews VALUES (710, 33930, 8703, 'I wish I could go back in time and experience this game for the first time again. The community and game play was phenomenal. I remember the PC I was using could only run this game at like 12FPS. I would do it all again. so many memories...', 'I''m sure there are many who enjoy it, but it wasn''t for me. More mil-sim than video game much of the time.', 'Very Positive', 92.91, 520.00, 11.88);
INSERT INTO reviews VALUES (713, 33990, 124, 'I purchased this game for 2 euros, which, on the minimum wage in my nation, will take about 10 minutes to earn. \nAnd that''s about as far as I''d go—this game may be worth 10 minutes of your labour, but certainly not 10 euros. \n\nThe main problem with this game is that it stumbles around for about 7 hours trying to build something gripping and engaging, and when it finally succeeds at immersing you into the story it simply ends; there''s no closure to any of the main plot points and everything is le', '4/10\n\nDidn''t finish the game. It crashed and I wasn''t bothered to repeat the 20min of the lost gaming.\nMost of the cast can''t act to safe their life. \nThe story is mediocre at best.\nDialog... clearly written by a person with English as a second language. It''s not that bad but very noticeable.', 'Mixed', 42.74, 9.00, 6.40);
INSERT INTO reviews VALUES (714, 34010, 2493, 'First it returned to GOG and now it''s back on steam! Game preservation is amazing', 'The game itself is a flawed gem (more "flawed" than "gem" to be honest) that deserves its spot on Obsidian''s amazing repertoire. If you can brave its clunky and cumbersome mechanics, the story and C&C have aged really well. However what I''ll be reviewing is its Steam version instead of the game itself. As of August 2024 the Steam version is identical to the disc release in 2010 with the 1.1 retail patch and has none of the improvements of the GOG version. For the same price. Therefore the GOG ve', 'Very Positive', 84.32, 4.15, 43.47);
INSERT INTO reviews VALUES (716, 34030, 9485, 'Great game if you are mildly autistic and have a fixation on Napoleonic warfare.', 'It''s a great game, but the ai is so braindead it takes most of the fun away, almost every battle in the campaign ended up having the austrians mindlessly charge into my line and create a giant mosh pit.', 'Very Positive', 91.18, 495.62, 25.85);
INSERT INTO reviews VALUES (717, 34190, 1412, '9 red bulls, a pack of Marlboros, and an afternoon free... oh yeah it''s Sonic and Sega All Stars Racing time.\n\nEDIT: Thanks for the gold, kind stranger! This is heccin'' epic!', 'I have both a 360 and ps3. Since the 360''s store is down, the only way to play the dlc is through the ps3. However, that version is limited to 720p 30fps, so I also got the PC version for the better resolution and framerate. Unfortunately, this port doesn''t have online play or the dlc so it''s not completely the definitive version. The first problem I ran into with the game was that it had performance issues and wouldn''t hit 60, and I knew my laptop should have been able to handle it. Thankfully,', 'Very Positive', 88.39, 2.52, 1.43);
INSERT INTO reviews VALUES (718, 34330, 20186, 'Good game, already got over 1130 hours but still haven''t take over the whole Japan yet.', 'Fuck you corpos for destroying a great game! Can''t run mods, and without em still crashes, thx assholes', 'Very Positive', 92.43, 1168.60, 1366.80);
INSERT INTO reviews VALUES (719, 34410, 163, 'A game where you can see the young Hitman before he went bald and got a barcode', 'The hardest stealth game ever made (Not the best designed mind you) unintentionally that answers the age old question of what would happen if MGS 2/3, a rip off of Hitman: Blood Money and Arma had sex and also NO POLISH? You play as a peice of toilet paper (With as much personality as wood) that can be killed by anything anytime in any way by enemies who are dumb as bricks but have MASSIVE vision cones if you aren''t crawling. He only has enough strength to pull the trigger everything else he fuc', 'Very Positive', 81.60, 6.18, 1.08);
INSERT INTO reviews VALUES (726, 34600, 189, 'the only bad thing is the crashes', '"your version of Order of War is cracked, press Okay to exit" yeah yeah yeah ok buddy guy', 'Mixed', 67.72, 1.35, 1.97);
INSERT INTO reviews VALUES (731, 34820, 208, 'Great Game', 'Back then, it was a good game. I played this a lot. The controlls and gameplay are really good, a good game. Unfortunately, graphics aged badly, what makes replaying it a cumbersome experience. On top of this, it doesn''t run well on Windows 10.', 'Mostly Positive', 78.37, 46.48, 0.63);
INSERT INTO reviews VALUES (732, 34830, 1831, 'https://steamcommunity.com/sharedfiles/filedetails/?id=458803901\nhttps://steamcommunity.com/sharedfiles/filedetails/?id=480938999\nhttps://steamcommunity.com/sharedfiles/filedetails/?id=464809565', 'I''d rather eat Swiss Chalet rotisserie chicken than attempt to play this again.', 'Mixed', 54.01, 4.75, 2.33);
INSERT INTO reviews VALUES (733, 34870, 3723, 'Rating result: "I mean its alright like",  6.5/10\n\nThe graphic is good, but the gameplay full of bugs. The AI is kind of dumb as I thought. Story is B tier and short but not bad as call of duty modern warfare 3''s.', 'It''s a decent game overall. While the storyline is just okay, the gameplay really shines with its great sniper mechanics. However, the multiplayer mode leaves much to be desired. The maps feel bland and the sniping action isn''t as engaging as it could be. If you''re in it for the solo sniper experience, you''ll find some enjoyment here, but don''t expect too much from the multiplayer aspect.I would recommend buying it when it''s on heavy discount; otherwise, don''t go for it.\n', 'Mixed', 69.33, 6.58, 62.15);
INSERT INTO reviews VALUES (734, 34900, 5201, 'Honestly was really bad until it became the best game I''ve ever played.\nRats 4 lyfe', 'good', 'Very Positive', 81.25, 0.12, 0.13);
INSERT INTO reviews VALUES (736, 35000, 1350, 'Breath of the Wild on PC', 'PC Port''s got a bug that I can''t get past: no audio during actual gameplay time. Audio''ll come through during cutscenes'' dialogue timing, but then there''s 0 audio at all outside the cinematics. Just silence.', 'Very Positive', 88.67, 10.23, 0.97);
INSERT INTO reviews VALUES (739, 35130, 1522, 'https://steamcommunity.com/sharedfiles/filedetails/?id=2275016182\nhttps://steamcommunity.com/sharedfiles/filedetails/?id=2793626363\nhttps://steamcommunity.com/sharedfiles/filedetails/?id=2793626380', 'doesn''t run on win11 :(', 'Very Positive', 92.18, 6.78, 1.90);
INSERT INTO reviews VALUES (740, 35140, 25405, 'Batman: Arkham Asylum is a game where you, as a rich guy in a bat costume, punch literally everyone — clowns, thugs, and even a really big crocodile. The whole thing takes place in a psych ward that feels more like a villain''s theme park than a treatment center. Gameplay is simple: sneak, punch, repeat. But it makes you feel like the Batman — just with slightly less depression (well, almost).\n\nFinal verdict: the best punching mental illness away simulator!', 'I can see why people like this game and i respect that. I came into this game with too high expectations and thats my fault. The combat is fun but overall ive just been bored. Im gonna move onto city next tho. I hope i enjoy that one more because i am pretty dissapointed. The writing was just... cringy honestly. nothing really scared me or made me genuially invested sadly', 'Overwhelmingly Positive', 96.45, 69.23, 7.92);
INSERT INTO reviews VALUES (744, 35450, 11184, 'Not many people playing this game today, but back in 2015 i had a lot of fun playing this. People running around getting blown to pieces by artillery shells, my whole squad got mown down by MG42. Even driving tanks is as much as scary being an infantrymen. I also still got PTSD from this game especially the grain elevator, yes that one famous building in stalingrad where in real life history it was one of the most violent and intense battle in WW2. 10//10 Devs, thank you Tripwire Interactive.\n', 'Only multiplayer and i wanted single player', 'Very Positive', 93.96, 101.35, 0.08);
INSERT INTO reviews VALUES (745, 35460, 537, 'I am a 52 yo father, probably one of the oldest people playing The Ball. I am a single father to my Son, who is 14 now. My son found this game at Christmas, so we installed it on his computer and he started playing. By the end of the week he had 24 hours on this game. This was horrible for me, as it was already hard for me to find ways to spend time with my son, as he is always out with his friends or just watching YouTube. So I decided to make a Steam account and get this game to see if I could', 'This game has puzzles and action. But whichever you focus on, you won''t have a good time.\n\nStory is like... you got a ball and that''s important. Take care of it.\nPuzzle part is like... mediocre. Not special. Do here, do that and voila. Watch cut scene.\nAction is like... just annoying. Your tool doesn''t directly hurt the enemies. Only your ball can. Kill ''em with physics... Maybe fun on paper but terrible execution on actual game.', 'Mostly Positive', 76.16, 0.52, 5.82);
INSERT INTO reviews VALUES (746, 35480, 471, 'This is a game that always calls me back, no matter how long it''s been. The gameplay is simple and easy to learn. Easy 30hrs with another glorious 30 ahead.', 'Very arcade/basic game, wish there was a Dwarfs!? 2 which expanded the game play loop/maps.', 'Mostly Positive', 78.77, 31.62, 8.03);
INSERT INTO reviews VALUES (748, 35700, 4458, 'A fun blend of fantasy and magic, Trine evokes the timeless charm of a classic fairy tale. Even years after its release, the ability to switch between characters in its platformer setting, each with their own unique mechanics, remains engaging. I’ve spent the first few hours playing in single-player mode, and it’s been a joy. Next on my list? Trying it out in local co-op', 'The graphics are so blurry that it hurts my eyes. The screenshots posted for the game are not artistically blurred, it just looks that bad. If you''re a fan of the Trine series, this one is only ok. Don''t buy this if you''re new to the series. Start with Trine 4 or 5. I regret buying this because this added nothing to the Trine experience and I''m only disappointed with how they attempted to upscale this game.', 'Very Positive', 94.46, 2.57, 0.52);
INSERT INTO reviews VALUES (749, 35720, 5622, 'Magical mushrooms, goblins and forests. Frogs that jumps on the castle and trolls who stands with the witches. Marshpits and dungeons that mophines into a danger that you will have to survive. The Princess that needs to be saved by three amazing heroes who stand with their strength and weaknesses. But together as strong as a Trine that brought them together into blue colored night.', 'Behind colorful visuals hides highly tedious and non-inventive gameplay. \n\nBeautiful, but EXTREMELY boring.\n\nHuge disenchantment.', 'Overwhelmingly Positive', 95.11, 4.98, 11.28);
INSERT INTO reviews VALUES (752, 36000, 166, 'I played this game for a total of 2 minutes and I realized its true purpose. As a CIA agent I found this game to be a spectacular mechanism of legal torture. I have used this in Afghanistan, Iraq, Ukraine, Syria, and Hoboken NJ. After cleverly sitting a terrorist down in a very friendly manor and coaxing them to play Buckets of Blood, the game does the rest of the work for me. After being attracted to the simplicity of the game, shortly thereafter you are racked by terrible sounds and even worse', 'Used to play this a lot when I was still in school and for some reason this latest(?) version is horrible :( \nThe hit reg is awful, the enemy AI is bad and the whole menu while you are in game is glitched. \n\n4/10 \n', 'Mixed', 59.04, 0.78, 0.25);
INSERT INTO reviews VALUES (757, 37000, 551, 'I get to meet hot women and kill fucked up men with my gay little colors, it''s amazing.', 'The game is unfinished, half-baked and full of shallow poeticisms. It spends more time creating pretense than creating a coherent gaming experience. Spare yourself this nonsense.', 'Very Positive', 82.58, 13.33, 51.00);
INSERT INTO reviews VALUES (758, 37210, 222, 'Steam hear me out PLEASE add a port for chocolatier 2 and 1, theres only the 3rd sequel but i REALLY want to play the other ones and i cant even play them because it doesnt work properly and keeps crashing! Please steam i NEED the other two versions, i''d play hundreds of dollars to play them...', 'crashes every 10-15 min', 'Mostly Positive', 72.52, 46.27, 12.23);
INSERT INTO reviews VALUES (761, 37240, 240, 'This is one of my favorite games brings back so much nostalgia.', 'This game was definitely a core childhood memory for me (´｡• ᵕ •｡''). I used to play it all the time, so naturally, I was curious to revisit it. At first, I was a bit hesitant to buy it because of the mixed reviews, and honestly, they weren’t wrong (・・;)\n\nWhen you launch the game, the interface is quite glitchy and laggy. The mouse tends to ghost and leaves a faint trail across the screen, which was a bit distracting. Correct me if I''m wrong but I also vaguely remembered using right-click instead', 'Mostly Negative', 36.25, 8.22, 6.97);
INSERT INTO reviews VALUES (762, 37260, 104, 'Played a demo for this as a kid, but never got to play it. Happy I finally got the chance, I very much enjoyed it!', 'Sights & Sounds\nA bumpy brick road\n\n While I wouldn''t condemn the artwork as merely bad, I do find it a little dull. With the noir motif, you typically expect everything to dark and dingy, but the entire game takes place at night and within mostly dimly-lit environments. I''m all for moodiness in my mystery games, but the visuals began to look a bit stale by the time the credits rolled\n There were also some weird inconsistencies with perspective and character design that kind of bothered me. Envi', 'Very Positive', 94.23, 5.77, 5.05);
INSERT INTO reviews VALUES (775, 37400, 371, 'If you like point and click adventure games, get these!  I was wary that the simple graphics might indicate lower quality, but that''s absolutely not the case. I liked the second game better than the first, but both are good, and in many ways more skillfully (and lovingly) crafted than modern point and click games.', 'Not the greatest point-and-click adventures I''ve played. Granted, I paid maybe a dollar or two, but most of my time spent with them was disappointing. The humor and writing is pretty decent, but the puzzles are nonsensical and the gameplay is irritating (it''s one of those games that has about six or seven actions you have to scroll through to find the thing you''re supposed to be doing). The art is awful but I suppose deliberately so, and I got used to it. Still, not a ton of fun, unless you''re h', 'Very Positive', 87.87, 5.92, 4.50);
INSERT INTO reviews VALUES (778, 37600, 472, 'I like how the gameplay ideas seem like they grow from the scene naturally, and how intuitive the puzzles are as if you are playing some real world toys.\n\nWhen you  take the . out from i and the title shows up , when you  trigger the chained reactions on lvl 10 , when you  light the stars to build the window , true art out of ten.', 'it is a rage game', 'Very Positive', 91.95, 3.00, 0.63);
INSERT INTO reviews VALUES (800, 38210, 128, 'Are you inching towards suicide but haven''t really made up your mind yet? Then this game is perfect for you! Within half an hour you''ll be sucking dicks for money so you can afford a bigger shotgun to blow your skull inside out!\nAnd best of all, it''s child-friendliness and local multiplayer mode make it fun for the whole family!', 'A game that looks like it was made for a 5 year old and has a story based around corruption and enslavement. Only get this if you want your child to learn about corruption or enslavement.', 'Mostly Positive', 75.78, 41.07, 0.30);
INSERT INTO reviews VALUES (801, 38230, 109, 'This is a mixed review. It is good and it is bad. The good is in the concept and the type of ideas that you would hope to see in a game of this genre. It has good options for room variations and decorations. It has the parts that make up an in depth game with a tutorial, campaign, and a sandbox mode. It has a lot of settings available for personal customization. It has in depth management systems. \n\nThe problem now is that all of the aforementioned is clunky. The key bindings are odd...but funct', 'Potential to be a really good fun game.\r\n\r\nToo many bugs that are clearly not gonna be fixed.\r\n\r\nRooms never being used..\r\nPool empty..\r\nOutside buildings not used..\r\nRestaurants empty..\r\nAdvertisement campaigns having ZERO affect.', 'Mixed', 44.95, 2.32, 82.68);
INSERT INTO reviews VALUES (802, 38400, 10155, 'It''s kinda like Star Wars in that no matter how good some of the sequels were, and how much I love it, part of me kinda wishes the Fallout series ended with the first one. Not even close to perfect, but nothing beats the first playthrough. Steeped in atmosphere, awash with interesting artistic direction, this is a game made by people with genuine vision. Everybody needs to play it. It''s not even that hard, back in the 90s it was assumed your average gamer could just jump into a game like this wi', 'Censorship: Not Even Once\n\nIn all honesty, Fallout: A Post Nuclear Role Playing Game was an enthralling RPG experience then and even now (regardless of contemporary meddling). Alas, I can not recommend purchasing this product on Steam as the version offered contains language and content changed/removed for the sake of not upsetting modern audiences. The universe within the Fallout universe is somewhat of an unforgiving hellscape, so why attempt to water it down when that is what attracted people', 'Overwhelmingly Positive', 95.12, 88.32, 70.65);
INSERT INTO reviews VALUES (803, 38410, 7951, 'After having sex with a mob bosses daughter, a bug occurred where my companions disappeared. The only way to fix it, was to have sex with his wife.', '6/10 - Game finished @ 50 hours and I stand by everything below in the original review at half-way point. I play with no mods - this was the vanilla experience and in 2024 it''s ok to skip this one. Unfortunately multiple end game bugs first starting in San Fran and new ones at the enclave base ruined the end a bit. Comments below from people thinking I don''t know how the levelling system nor turn based games work... that''s not it. This game is too long for it''s own good. The story absolutely doe', 'Very Positive', 94.33, 34.33, 51.92);
INSERT INTO reviews VALUES (804, 38420, 1415, 'Tactics is canon, 76 is not.', 'Unlike most of the other negative reviews, the game worked fine for me on Windows 10, I just genuinely don''t like the game.\n\nDespite being a huge fan of classic Fallout, this one really doesn''t do it for me. In fact I thought it was pretty miserable for basically my entire playthrough.\n\nIt''s like, imagine playing Fallout 1 or 2, but you have to individually control six different characters with different inventories, the entire game is just linear missions with no real option for any non-combat ', 'Mostly Positive', 79.36, 1.65, 25.55);
INSERT INTO reviews VALUES (805, 38430, 269, 'This is a FPS urban-themed game from 1999 (or possibly 2000?), think along the lines of DOOM or Quake but better. The single-player campaign is fun and great, though can be very challenging, especially at a higher difficulty. The multiplayer community is still active and plays different game modes to keep things interesting. I highly suggest playing for both single player and multi-player. Yeehaw!', 'i', 'Mostly Positive', 78.07, 827.18, 0.33);
INSERT INTO reviews VALUES (806, 38440, 439, 'My gambling addict friend said if I post a review on Sacrifice  and it gets 350 likes and 150 Awards that he will buy me a case of beer, some vodka, and bottle of wine.. So I''m just gonna leave this here..', 'Steam версия не запускается даже с учетом эмулятора voodoo 2. Сама игра 10/10 уникальный представитель своего жанра (MMORPG+RTS)', 'Very Positive', 92.71, 0.92, 0.28);
INSERT INTO reviews VALUES (807, 38450, 176, 'Back in the days when most shooters were all shades of brown and the mouse was a weird device, this was a cool game with unique enemy designs, levels and almost James Bond-esque music. Today we have an aged game that you can play after reading the guides, installing patches and breaking your fingers to satisfy the controls. Even considering the nominal price, too little effort has been put into making the game playable by the current owner of the game. Looks like trying to milk a dead cow... gam', 'current version of this game is barely playable, it needs to be updated.', 'Mostly Positive', 77.84, 4.90, 0.18);
INSERT INTO reviews VALUES (808, 38460, 118, 'The first MDK was much better because it was spectacular in gameplay and graphics/effects. \nAmazing sniper zoom, cool environments with the mirrors and T-Fighter-ish ships, the absurd humor.\nThe board surfing, air gliding, take a lift from a bomber, camouflage as a robot and so on!\n\nThis game is also very nice, but it''s not that spectaculair anymore, but nice enough to play this days.', 'Doesn''t work. I''m trying to play, it will load but after selecting a new game it starts the movie and everything is distorted and you can see some parts of the pictures in form of vectors. After that, starts with a black screen and a text that comes letter by letter in slow motion and just a row is written in about two minutes.', 'Mostly Positive', 77.12, 1.25, 6.03);
INSERT INTO reviews VALUES (809, 38480, 106, 'COW LAUNCHED!', 'Way too expensive for what''s offered. These are the dos versions of the games, not the snes and n64, running on dosbox meaning there''s no direct controller support. Also, games 2 and 3 aren''t that great. If you really want to play these games I''d suggest you avoid this release and find other means to play them', 'Mixed', 41.51, 1.13, 0.20);
INSERT INTO reviews VALUES (811, 38600, 863, 'A childhood favorite', 'I bought this game, because I thought it would be fun to play with my mother, as solitaire is her favourite game to play while watching TV... O what little did I know the horrible gut wrenching grind fest this game would turn into. If you like to collect achievements like myself, 28/30 achievements are "Faerie" easy to obtain ;) however if you''re a perfectionist, also like myself, that last egg can prove to be a bit of a doozy to obtain, with one of the Faerie Solitaire guide creators loosely ca', 'Very Positive', 90.73, 9.30, 347.00);
INSERT INTO reviews VALUES (812, 38700, 759, 'Fun puzzle game with a great sense for difficulty.\r\n\r\nIf playing on Steam Deck, use TDP limit.  For some reason this will eat up battery.', 'This game is not for tbe feint of heart. I bought this game thinking it was going to be a fun somewhat relaxing puzzle platformer game and boy was I wrong!\n\nThis game is HARD, you will get frustrated, rage quit and uninstall this game. I must''ve installed/uninstalled this game.5 times before finally giving up.\n\nThe levels are well designed, there are unlockables that help with puzzles but the puzzles are too difficult for me - to the point where frustration turns into anger.\n\nI cannot recommend ', 'Very Positive', 86.56, 6.62, 1.85);
INSERT INTO reviews VALUES (813, 38720, 530, '6/10 (IMO, actual score could be around 7-8/10)\r\n\r\nDecent Puzzle game, confusing at times due to camera not allowing to see in different angles.\r\n\r\nIf you love puzzles, this is a good one, otherwise i''d recommend looking for other type of stuff since it can be somewhat frustating to someone like me(though you can always use the hint system which lets you finish if you have trouble doing them, however to me was like the ultimate option and let me feel defeated xd)', 'Has ads in the game.', 'Very Positive', 88.30, 5.33, 2.75);
INSERT INTO reviews VALUES (814, 38740, 855, 'I love edging', 'you have to join a steam group to play all the levels. lmao', 'Very Positive', 91.58, 3.27, 0.75);
INSERT INTO reviews VALUES (815, 39000, 137, 'My name is stephen hawking, welcome to jackass', 'Installs AMD Dual Core optimizer which runs at startup. Froze my computer first 2 times trying to start it. It does have text to speech tho.', 'Very Positive', 83.94, 11.65, 0.70);
INSERT INTO reviews VALUES (816, 39110, 183, 'Square Enix made a H.O.G.  :D', 'Don''t care for the story portion, it was a substandard typical mystery plot that is highly predictable. The backgrounds are pretty and the music is alright, but overall the game itself it not something that I can recommend to others. The hidden object portion was alright the first few scenes, but then you come back to the same scenes and the objects are in the exact same spots as last time and you have to find them again? Not exactly challenging. I liked some of the mini games but not enough to ', 'Very Positive', 80.33, 2.85, 2.28);
INSERT INTO reviews VALUES (817, 39120, 823, 'For people who are looking for and old school mmorpg like World of warcraft that isn''t World of warcraft, this is the right game. I refuse to believe that this game is dying. Curious to see if this is true? Then come join and play with the last survivors of Telara!', 'This game is complete trash. The developer who currently owns it, are a waste also. They delete RANDOM characters from years ago and will not respond to customer support tickets. As someone who bought this as a collector''s edition when it was a disc decades ago, I will no longer provide it a second look,. Along with ANY games from this developer/publisher.  Game is dead, and they are the reason.', 'Mostly Positive', 74.12, 162.68, 488.27);
INSERT INTO reviews VALUES (818, 39140, 15250, 'Disgruntled ex-employee enters high security facility to drive his collector''s edition katana through the now former CEO.\n\nUnable to fight against the resulting nepotism, other former disgruntled employees and associates set out to save the world from corporate greed using shiny magic rocks.\n\nUnemployed girl selling her flower on the streets for 1 gil still finds the audacity to quiet quit and takes a nap.\n\n10/10, game did a better job saving the planet than paper straws.', 'Im not sure whats going on here. This is a single player game from 1997. Why I am being forced to create an account with a 3rd party company that didnt exist when this game was made. I bought this game. There is no reason for this. FF8 didnt require a 3rd party account. FF7 remake didnt require a 3rd party account. Why are you being exclusive and weird square enix? When you pull stunts like this, it makes me really not like you. It makes me view all of the products that you have stuck your hands', 'Very Positive', 91.53, 65.03, 54.72);
INSERT INTO reviews VALUES (819, 39190, 2035, 'My grandfather always loved this game and so I played it alot with him as a child and will always love it just like him.\n\nLove you grandpa, thank you for standing up for me when my parents tried to abuse me <3', 'I previously said the game does not work. I would like to amend that to the game does not work but if you download dgVoodoo you can make it work. Bought this for the childhood nostalgia, very happy with being able to get it to work. Still a bad review because the game does not work on its own. Do not buy it unless you''re prepared to trouble shoot getting it to work.', 'Mostly Positive', 79.51, 14.97, 0.62);
INSERT INTO reviews VALUES (820, 39200, 1284, 'remaster plz. xDDD', 'Don''t buy if you have windows 10. None of the fixes for the missing mouse issue works anymore. The only fix is downloading a code editor and redirecting the games paths to your graphics card. Which windows compatibility mode should do but doesn''t. You would think steam would be aware of this issue and would post a warning or an actual fix other than requiring you to alter the games code with 3rd party programs so you could play it. Love spending days researching a fix for things that should work', 'Mostly Positive', 73.44, 11.33, 152.33);
INSERT INTO reviews VALUES (823, 39510, 2234, 'A jewel between jewels!! To play the essence of gothic 1, with better playability, new plot, dragons ...\n\nI always will remember when my gf then, my wife now, gifted me tNotR expansion, all this new world, beasts & PNJs\n\nAWESOME!!\n\nhttps://steamcommunity.com/sharedfiles/filedetails/?id=2951158169', 'Price increased\n40 PLN to 92 PLN\n10 euro to 20 euro\nITS NOT POLISHED, price in euro is lower than PLN\ngood job THQ', 'Very Positive', 87.15, 104.58, 0.10);
INSERT INTO reviews VALUES (824, 39520, 202, 'Such a charming game! I adore the soundtrack and the atmosphere. The game isn''t super complex but it goes so deep. I play this at least once a year in the colder seasons.\r\n\r\nToo bad these games don''t receive much love.', 'it''s a good "just one more turn" game. very addictive. the first time losing a family member hit unexpectedly hard, and the "you are about to die" message is the creepiest notification i''ve ever seen in a game.\r\n\r\nbut there is a well-known bug that causes player''s saves to become corrupted after a certain number of in-game years, and the developers have done nothing to fix it. in fact, you''ll need to browse old german gaming forums to find fan-made fixes, which rarely work anymore. i cannot desc', 'Mixed', 62.38, 74.57, 12.23);
INSERT INTO reviews VALUES (825, 39530, 685, 'I''m surprised that this game isn''t talked about more. Playing Painkiller for the first time in 2025, I noticed how much of its DNA is in the new wave of fast-paced shooters: the level structure and challenge system for power-ups came back in Doom 2016, the simplified bunny-hopping for speed came back in Dusk, the system for collecting enemy souls to activate a special mode where you''re overpowered came back in Amid Evil...\n\nThis is a super fun game that has aged remarkably well. Coming out in 20', '- Bad controls\r\n- Boring bosses\r\n- Very unstable, crashes often\r\n- difficulty is as inconsistent as the mechanics of gameplay\r\n\r\nIn this day and age there is zero reason to play this, there are many much better classics AND many much better new indie retro shooters\r\n', 'Very Positive', 85.40, 25.48, 5.65);
INSERT INTO reviews VALUES (826, 39540, 804, 'One of the greatest games of all time imo. I''ve spent countless hours playing ever since I was 10 years old, Would Highly recommend to people who love strategy fantasy RPGs.', 'Nice game mixing RTS and RPG, but it shows its age (first release 2003, way before its release on Steam in 2009).\nToday, I would recommend it only to completionists and from nostalgia. Those people can overlook the annoying game controls (e.g. inventory, quest list, casting system).\nTo everyone else – find yourself some newer offspring from this category or wait for a remaster.', 'Very Positive', 82.84, 407.93, 101.48);
INSERT INTO reviews VALUES (827, 39550, 365, 'You still can''t walk faster in this one either and the magic is a bit limited compared to the first one but everything else is improved: graphics, story, unit/race variety, map exploration, streamlined progression system, you get to play with and as a dragon later on in the story, and just overall content. \n\nOh and Ya Boi Flink McWinter  gets time to shine, the Prof.Twiddle questline is fun, and there''s the equivalent of you leading an army to victory while resolving the regrets of a ghost so yo', 'While i enjoyed the first game and got bored with the expansions for it, this brings no improvement upon what was already present in the first game and it feels like another expansion than a stand alone game. I looked up the story online and this has to be the most boring ''fantasy'' game i have ever came across. I''m not going to waste 25 to 30 hours of my time to play this poorly written slop.', 'Mixed', 64.11, 234.47, 0.62);
INSERT INTO reviews VALUES (828, 39560, 210, 'Make no mistake, Painkiller: Resurrection is flawed. There are too many faults ranging from the game causing you to fall from the map to freezing whenever you bunny hop to skip certain areas within levels. Some level designs are well made while others cause you to go through tiny gaps or mountains filled with many rocks. The soundtrack features new combat and ambient music while some are retained from the previous game. Despite these flaws, I''ve had a thrill playing this game on its hardest diff', 'Hot buggy garbage compared to the rest of the titles in the PK franchise. Honestly, you can skip this one, unless you are a masochist like myself who has to complete everything. :/', 'Mostly Negative', 27.62, 10.58, 14.90);
INSERT INTO reviews VALUES (829, 39630, 134, 'It''s a bit of a pain to set up, but the setting is very worth it. The voice acting is so terrible that it winds up being great, the music is pretty unique, and the art direction really makes this game stand out.', 'I''ve played the demo of this game as a kid and was very excited to finally be able to play the full game. Sadly, the Steam version turned out to be an uncontrollable mess. Even on the lowest possible sensitity setting moving your mouse slighty to the left or right will end up in a turn of up to 120°. However, moving your mouse up or down seems to be much more affected by the settings. \n\nCombined with the fact that you can''t save during missions (at least in the ones I''ve played) this is a recipe', 'Mixed', 69.40, 13.67, 0.55);
INSERT INTO reviews VALUES (831, 39650, 263, 'Poverty Simulator', 'DON''T BUY!!! More bugs than a wenches blanket.\n\nThis game has the potential to be an absolute classic. I bought a hard copy years ago and loved it... At first but then the bugs began to show, frustrating game breaking bugs. Having to re-load the entire game every few minutes to continue playing. \nSeeing it on steam years later I bought it thinking "steam would have made them fix it surely" nope.\nHaving played the game on three different systems over the years I can tell you the bugs are persista', 'Mixed', 66.92, 23.50, 42.52);
INSERT INTO reviews VALUES (833, 39670, 473, 'It gets repetitive sooner rather than later, but even though the story is not sufficiently developed, it is still an "Enjoyable" game in the short term, although forgotten for not being very imaginative ღ', 'It''s really mediocre even by 2003 standards. This game is a generic shooter, with a lot of ideas mixed together, that quickly ends up being awful to play. \n\nThe level design is horrible. You have huge levels filled with nothing but dead ends. It constantly feels like you have to escape a repetitive maze that serves also as a shooting gallery, because the devs remembered at the last moment that the game is supposed to be a first-person shooter. Everything feels amateurish and unfinished. The leve', 'Mixed', 68.29, 1491.23, 14.87);
INSERT INTO reviews VALUES (834, 39680, 1542, 'Ever wanted to topple the medieval 1%? This game lets you stick it to the nobles and the church—all from your mom''s basement. 10/10 would rebel again.', 'This game poses as an innocent simulator game, which is in many way superior to any other simulator game I''ve played, However, it holds something sinister in the later aspects of the game... particularly the option to sell your soul to the devil for an additional 20 years of life when reaching the max level. Some users might not mind this... but this game, although pretending to be Christian friendly, with the option to both run a Protestant or Catholic Church, is absolutely not Christian friend', 'Mostly Positive', 79.38, 83.17, 175.12);
INSERT INTO reviews VALUES (835, 39690, 698, 'Why so many negative reviews?  I''ve recently played this game for the first time, and for a game that was released in 2010 it still holds up somewhat today.  Sure the gameplay mechanics is very simple, but the overall experience was enjoyable. I''m just posting this review to boost up the score a bit.', 'Immediately crashes to deskop on launch now', 'Mixed', 55.16, 25.58, 5.55);
INSERT INTO reviews VALUES (836, 39800, 1185, 'I started playing this at 9:00 AM and 5 minutes later it was midnight.\n', 'This game could be so much more. It''s barely a game. More like a lazy smartphone app. Compared to games like vampire survivors or halls of torment, this is very very basic.', 'Very Positive', 90.72, 4.55, 0.72);
INSERT INTO reviews VALUES (838, 40100, 4794, 'Graphics = 10/10\nFun = 10/10\nPlayability= 10/10\nHappy 13th anniversary!\nThe only thing I would like is to have Supreme Commander 3..', 'If you lliked the first game, do not buy this!\nAll the progress made with UI in Forged Alliance is gone. All the intricacies are gone.\nThe Research System is stupid and of course you can''t affect it in the settings of a skirmish (like unlocking everything from the start).\nThe unit variety is gone. The new experimentals are stupid and the ones which are supposed to be the new versions of the old ones are downgrades. Why does the Fatboy 2 not have a shield and can''t produce units?\nYou can no longe', 'Very Positive', 86.94, 53.73, 1.40);
INSERT INTO reviews VALUES (841, 40300, 2148, 'graphics are meh \r\nsoud is decent \r\nstory is okeish \r\nthis game hits me right in the Nostalgy 10/10', 'Although i play this game every few years for nostalgia reasons, i cant really recommend it.\n\nThe first chapter is excellent, but after that it just goes downhill and becomes a 5/10', 'Very Positive', 83.61, 34.32, 90.60);
INSERT INTO reviews VALUES (843, 40330, 153, 'This game is a quintessential old-school point-and-click adventure. Overall, it is well-designed, featuring an intricate story and solid gameplay that provide great satisfaction. If you''re a fan of this genre, it''s definitely worth trying at least once. Despite the passage of time since its release, it still holds great value for rediscovery.', 'This game was so incredibly boring and I also couldn''t stand Nina''s extremely stupid comments any longer. \n\nDespite the negative review, I would like to point out that the game runs smoothly, even though it is ''a bit older''. For anyone who wants to try out the game: go ahead, on sale it only costs $0.99. And what I call ''extremely stupid comments'' may be, to others, a good sense of humor. Who knows.\n\n', 'Very Positive', 84.97, 9.35, 1.37);
INSERT INTO reviews VALUES (845, 40350, 210, 'Nobody will read my review so I will eat 1 tablespoon of mustard for every like this gets.\n', 'I am very unhappy with this game and the service I received from Steam support.I paid $10 to Steam for this game and downloaded it to my Steam account.However,when I tried to start the game from the title page it would not start despite me playing the demo ok beforehand.The start title is in grey printing as is configuration the other 3 titles like read me and exit in white and function.I have written to Steam support on several occasions and sent a screenshot of the problem.I note that from the', 'Very Positive', 90.48, 11.98, 11.60);
INSERT INTO reviews VALUES (846, 40380, 387, 'They truly don’t make racing games like this anymore. For one dollar, Nail’d gave me more enjoyment than the latest Need for Speed ever could. It feels like developers genuinely cared about the games they created back then. Today’s racing scene feels soulless, devoid of love, passion, and any real effort. It’s disheartening, which is why I take such pleasure in exploring and playing older racing titles. Flying ATVs? What more could you want?', 'Cannot get xbox controller to work.', 'Mostly Positive', 79.59, 11.10, 1.48);
INSERT INTO reviews VALUES (847, 40390, 974, 'May not be the best Piranha Bytes game, but it is a Piranha Bytes game nonetheless - very enjoyable niche game that scratches the itch no other company or RPG game can address to this day.', 'Risen 2: Dark Waters\nI have a very weird relationship with this game. Risen 1 is one of my favourite and most nostalgic games and although I wanted to continue the story with Risen 2, I just couldn''t. Besides constant problems with crashes and file compatibility, the pirate theme is just not interesting to me, besides Pirates of the Caribbean with Johnny Depp and AC Black Flag, I have no interest in pirate stories. I also don''t like how our main protagonist, that in Risen 1 managed to overpowere', 'Mostly Positive', 75.77, 54.98, 3.05);
INSERT INTO reviews VALUES (848, 40400, 849, 'This game truly feels like you are an underdog fighting an impossible battle. It manages to be one of the most emotional RTS games I''ve ever played, despite not really having much of a story at all. You feel the hope, desperation, and dread of your people, which makes victory infinitely satisfying.\r\n\r\nIf you''re someone who enjoys playing RTS games against AI opponents, especially if you prefer "turtling" in those games, then you will probably enjoy AI War.', 'I''m sure its a great game and all, but the UI is like piloting an excel spreadsheet. Learning how to play this game is about as much fun as doing my taxes.', 'Very Positive', 86.45, 20.77, 2.60);
INSERT INTO reviews VALUES (851, 40700, 4302, 'When I was very little, my dad had come across this game. He bought the game, off the original page of Amanita Design. I remember those late nights, when my dad would play the game. And the music would be playing, i''d watch him also play it as well. \n\nNow I am going to finish the game, and I love the game due to nostalgia. Also the environments, and art are so pretty. Even the music hits different than any other game.', 'I don''t want to have anything to do with a company that raises money to support terrorism against another country. Give me my money back.', 'Very Positive', 94.44, 4.68, 7.08);
INSERT INTO reviews VALUES (852, 40720, 727, 'Samorost 2 is a point-and-click adventure game in which you play as a gnome trying to save his dog, who was kidnapped by aliens. As a sequel to the first Samorost game, Samorost 2 does a good job of "scaling up" the first game. It''s quite a bit longer than the first (my first playthrough took just over an hour, compared to the 15 minutes it took for me to beat the original Samorost), and the puzzles are slightly more complex, with some requiring timed or repeated clicks to solve. Still, the game', 'What started to be a lovely game, turned into a bug nightmare by midgame with buttons only working when restarting the level. And then they dont not work at all. Doublechecked a playthrough video to see that it''s not my fault, it''s the programming. Even if the game would receive a generally positive review, can''t finish the story, therefore it''s a negative experience.', 'Very Positive', 88.72, 1.17, 1.67);
INSERT INTO reviews VALUES (853, 40800, 12698, 'This game has a sick sense of humiliation by beating you down to the ground with each level and forcing you to play through them over and over again until you can complete each level without dying. This game taught me that with the power of love, I can overcome death-defying obstacles like homing missiles and moving saw blades to rescue my lover from an angsty evil post-embryo doctor. I have successfully maneuvered through every instance of challenge this game has to offer me, now it is time for', 'I hope the creator of this shit burn in hell. My parents and my neighbours hate me because of this game. I almost broke my hand 2 times while playing the stupid game.So,if you love your life never I mean never get this game.', 'Very Positive', 94.10, 130.10, 3.72);
INSERT INTO reviews VALUES (854, 40950, 2817, 'Turns out there''s actually a game behind the TikTok edits, and it''s awesome.', 'Everything firefly makes is garbage. This game was good when it came out on CD. then they updated it and broke it. Not to mention i got it given to me for their crap job on Strong hold 3. Firefly is the the reason why I will never pre order a game again, This product predates the steam return option being available. It also represents everything wrong with the new standard of games that rush to release then patch and try to fix broken programming. Or in this case abandons and just rips off fans.', 'Very Positive', 94.64, 17.87, 22.90);
INSERT INTO reviews VALUES (855, 40960, 1996, 'Nostalgia. I remember stronghold 2 was the first game i installed on my PC when i bought it and first place and its the best among the series in my opinion although I haven''t played stronghold 1 & warlord but among those I played stronghold 2 shines with magical brightness.\r\nThe game gives many options to build your castle and combined with incredible amount of details the game contains; stronghold 2 presents itself as one of the best castle sims have been ever made.\r\nYou have to take care of go', 'Good game and fun to play. Perfect nostalgia. The maps are  a bit small though with to little building space. Still, can´t recommend it because of its consant crashes. If you play it save frequently or lose you progress frequently. Your choice.', 'Very Positive', 90.33, 44.65, 18.10);
INSERT INTO reviews VALUES (856, 40970, 5829, 'The voice acting in this game is top notch. Ever wondered wondered what it was like to listen to someone get burned alive? How about the sound someone makes when they''ve met their untimely demise from being struck by a stone thrown from a sling? No? How about the sound of one choking and gargling on their own blood as they''re cut down to size from the steel of a fierce knight or bludgeoned to death by an English man flailing a mace? Also no? Well that''s good to hear. However, if you''re looking f', 'I''ve spent hours looking online on how to get the game to open, no way i can recommend a game that doesn''t even open and nothing online fixes the issue. Don''t waste your money.', 'Overwhelmingly Positive', 97.39, 88.22, 1.37);
INSERT INTO reviews VALUES (857, 40980, 955, 'I like watching the dudes get the resources', 'fun when it work but keeps crashing way to much  and the AI pathing is terrible in some quests', 'Very Positive', 87.23, 40.10, 25.73);
INSERT INTO reviews VALUES (858, 41000, 2283, 'https://steamcommunity.com/sharedfiles/filedetails/?id=1415384655\nhttps://steamcommunity.com/sharedfiles/filedetails/?id=1407210927\nhttps://steamcommunity.com/sharedfiles/filedetails/?id=1414947609', 'This game really fucking sucks im going to be so honest.\n\nI have never seen a shooter punish exploration, and ammo/health resupplying as much as this game.  1 armor pickup? spawn 20 enemies. have 10 shells across the map you slowly trod your way to get? spawn in the tankiest enemies that''ll eat up that ammo you just got.  I stopped collecting health pickups because i swear to fuck every single health pickup that doesn''t spawn in front of you is tied to enemies that''ll immediately eat it up.\nI al', 'Very Positive', 91.50, 13.85, 1.37);
INSERT INTO reviews VALUES (859, 41014, 206, 'https://steamcommunity.com/sharedfiles/filedetails/?id=1417018575\nhttps://steamcommunity.com/sharedfiles/filedetails/?id=1426385556\nhttps://steamcommunity.com/sharedfiles/filedetails/?id=2319753453', 'Serious Sam HD: The Second Encounter is a relentless string of cheap shots, monster closets, instant deaths, bombastic weapons, and irreverently juvenile humor. Serious Sam is designed around ever escalating crescendos of over-the-top violence that will likely see you quicksaving mid-battle with the prescient expectation that a giant enemy will spring over that wall in the distance firing rockets that you couldn''t possibly avoid in time that will kill you, instantly. If the idea of a die-rinse-r', 'Very Positive', 90.29, 0.00, 0.00);
INSERT INTO reviews VALUES (860, 41050, 1081, 'Certainly a serious game with very serious enemies and serious bossfights', 'Aged like milk', 'Overwhelmingly Positive', 95.56, 1.97, 7.22);
INSERT INTO reviews VALUES (861, 41060, 526, 'One of the best game of my childhood. I''m Serious.', 'Like first one.', 'Very Positive', 94.87, 13.28, 2.33);
INSERT INTO reviews VALUES (862, 41070, 5709, 'I''ve seen some people saying that Serious Sam 3 is a boring FPS game because it is just all about defeating waves of hordes. Come on, bros. That is the best selling point of this game. Serious Sam is a place where you can take a full rest from a long day of work. What you need to do here is just grab some beer, and enjoy killing numerous enemies.\n\nIn this game, you have only one task: shooting whatever that can move. If it moves, you kill it, that''s all about this game. If you are expecting some', 'there are way too many enemies in the game even on easy difficulty\n\nskill issue/10 would uninstall again :3', 'Very Positive', 86.32, 176.73, 8.62);
INSERT INTO reviews VALUES (863, 41100, 255, 'Amazing piece of a game.. it has very unique controls, nothing seen in any other game I know. Prepare to experience something new, highly recommended! :)', 'Чувак, ты сделал отличную игру, но сейчас запускать и играть в ЭТО - та ещё попа-боль.  Я в курсе, что у Тебя есть уже лругой проект (в списке, пока не играл), и, возможно, следующий.  НО, может быть, Ты вернешься назад на десяток лет, обновишь шедевр?  С тебя - несколько десятков часов работы (кроме разешения монитора и чувствительности мыши никего особо трогать не надо), с клиентов - некий заработок и +авторитет.  Обещяю купить "нововую специальную" версию - хотя, это, конечно, копейки...', 'Very Positive', 88.63, 12.40, 3.88);
INSERT INTO reviews VALUES (864, 41300, 508, '7/10 - Fun little 2D action multiplayer flying game. Unfortunately almost no players online in 2024.', 'No 64-bit support for Mac OS, yet it''s listed as if it does.', 'Overwhelmingly Positive', 95.08, 21.50, 0.87);
INSERT INTO reviews VALUES (866, 41500, 3288, 'While on modern standards Torchlight is janky it''s still a decent experience.\r\n\r\nThis game has such low pc requirements that you can probably play it at 120fps on a Samsung fridge.', 'Torchlight is a nice and somewhat cute timekiller, perfect to spend an evening mindlessly clearing a dungeon after a hard day.\n\nProblem is that as a game, it is extraordinarily boring mess of grind, poor gameplay design choices, dull skill trees, dull champion/boss fights and a difficulty "curve" which looks like jigsaw line. I completed it on the hardest level (Very Hard without permadeath), and wouldn''t waste my time on this ever again.\n', 'Very Positive', 91.73, 63.85, 79.55);
INSERT INTO reviews VALUES (870, 41700, 9162, 'One of the greatest games of all time, bar none. HOWEVER you should buy it NOW, even though S.T.A.L.K.E.R. 2 is less than a week away (for real this time!) because xrMPE just made finished their CO-OP mod!!! You can play the whole campaign co-op with up to four players. And if you already own the game, go get it now! The mod is FREE!!\n\nhttps://www.xrmpe.online/', 'Where do I begin? I am a american who grew up with the stalker games being released. These games originally released in the Russian language and there was no Ukrainian language at the time. Did you know this game is based off of the 1979 film Stalker that was created from Andrei Tarkovsky  A Soviet and Russian Screenwriter? And that movie is based off of the book Roadside Picnic written by russian and soviet authors Arkady Strugatsky and boris Strugatsky (both brothers). Stalker it self is a rus', 'Overwhelmingly Positive', 95.52, 146.55, 31.13);
INSERT INTO reviews VALUES (872, 41740, 174, 'My gambling addict friend said if I post a review and it gets 350 likes and 50 Awards that he will buy me a case of beer, some vodka and 1 kg of lemon So im just gonna leave this here.\nМой друг-игроман сказал, что если я опубликую отзыв и он наберет 350 лайков и 50 наград, он купит мне ящик пива, немного водки и 1 кг лимона, так что я просто оставлю это здесь.', 'For being a game devoted to "fun," the constant reminders across the screen asking "Are you having fun?" serve to make me aware of the lack of fun.  I played it to the end (one end of two), and only stuck it out to check it off a list of games I have in my library.  It is short (less than 6 hours).  The physics of the game are frustrating (especially at the end when flying comes in).  The humor is not my style, but it may be yours...  The story is terrible.  Making your own vehicles serves littl', 'Very Positive', 82.76, 0.27, 3.65);
INSERT INTO reviews VALUES (873, 41800, 464, 'I love this game!', 'Seriously\r\n\r\nHow can anyone give this game a positive review when it is all behind a pay wall, I mean sure most of it is cheap, but having pretty much nothing after buying it then having to buy everything one bit at time. seems shifty. Just not for me. I do not like paying for what i consider "should of been in the original release" content.', 'Mostly Positive', 76.29, 10.83, 8.22);
INSERT INTO reviews VALUES (874, 41900, 666, 'While the graphics or the gameplay haven''t really stood the test of time, the snarky storytelling of a horny drunkard''s adventure is top notch.', 'Buggy couldnt control character in tutorial after summon. Starting again didnt help.', 'Mostly Positive', 76.43, 113.52, 0.80);
INSERT INTO reviews VALUES (876, 42120, 563, 'Good fun game shame its abandoned by players and somehow TF2 is still alive and this isnt', 'Played during the initial release >10 years ago. Bought it yesterday to see if it was alive. Launched the game, didn''t work, lobbies are dead. Started a refund request. Steam denied it 3x times because I have >2 hours of play time from a free weekend ALMOST FIFTEEN YEARS AGO. Actually predatory behavior. Don''t waste your money buying this game if you''ve played it before and think you''ll get your money back, because you won''t.', 'Mostly Positive', 71.05, 0.12, 9.63);
INSERT INTO reviews VALUES (877, 42140, 112, 'Fatshark Quality (which also includes a random crash), and you will have to install nvidia physx otherway it will not run.\n\n5/10 or 6/10 game. (i suggest get it on a sale)\n\nThe game is not bad but its not amazing game but its not bad, is well designed, the gameplay involves platform puzzle in which you will face ground that you can only step ones. There will be also some timed puzzle events that becomes a little annoying, there is no shame in searching resolves in youtube.\n\nIts an ok game. But p', 'I finished this game after 11 years (one of the games I just pucharsed and left to rot quite literally).\r\n\r\n4/10\r\n\r\nNice graphics\r\nDecent Gameplay (its playable)\r\nSemi-boring story (easy to understand but i guess it was more targeted to children)\r\nNot Hard (in fact quite easy, the only "hard" stuff would be more akin to finishing 100% all levels)\r\n\r\nFrom my own POV however:\r\nGameplay was really boring and tedious (you need to move a bird for extra points all the time, for a self completionist it', 'Mixed', 66.07, 13.07, 7.27);
INSERT INTO reviews VALUES (879, 42170, 406, 'Krater exists in technological hospice—a once-living game world now terminal on most systems. Its permanent character death mechanic now applies to the game itself. Buy only if you accept your purchase is less ownership than temporary visitation rights to digital content already marked for deletion.', 'Repetitive and boring. Endless dungeon crawl of the same set of 3-4 groups of enemies, walk 3 seconds, kill and repeat. Sadly nothing changed after a few hours hoping it would get better.\n\nDidn''t realise each character is level limited and you''ll stop earning XP. Your first set of characters are tier 1 level 1-5. You''ll need to recruit tier 2 characters to access 1-10, then tier 3 for level 1-15. Apparently you can pay to upgrade their tier later in the game.\n\nDefault keyboard mapping is very ba', 'Mixed', 54.93, 2.43, 8.40);
INSERT INTO reviews VALUES (881, 42210, 275, 'I played this game in 2002 with my 6 year old daughter. And then we played every single Nancy Drew through the last one in 2019 when she was 23 years old. Tonight the two of us continued the tradition by introducing it to my 8 year old grand daughter. It is a family legacy now.', 'Not one of my favorite Nancy Drew games... Extremely slow paced and boring. Also, not much story at all.', 'Mostly Positive', 79.27, 5.35, 4.73);
INSERT INTO reviews VALUES (882, 42220, 185, 'This was probably my favorite Nancy Drew game of all time.', 'As someone who grew up with Nancy Drew, and is now re-playing the games as an adult...I have mixed feelings about The Captive Curse. This is the first game I decided to re-play in the series, because it is one of the least memorable.  I was hoping I might appreciate it more since it was basically like playing a new game. Much to my disappointment, it is the same dull, slightly annoying game I played 8 years ago. While there are some thrilling aspects, and I enjoy the setting of an old German cas', 'Very Positive', 88.11, 42.87, 10.53);
INSERT INTO reviews VALUES (883, 42230, 131, 'A classic Nancy Drew game that you can never go wrong playing. ♥', 'I love the Nancy Drew game. I played many as a kid and have continued to do so into adulthood for the nostalgia. This one was one of the few I got as a Christmas present one year during high school. I don''t remember being this frustrated by it. Even now, I struggled with understanding some puzzles and had to look up hints. The story wasn''t as captivating as the others either. Though, I do have a soft spot for Pa. I''d say this game is better for those familiar with the Nancy Drew games. If you''re', 'Mixed', 69.47, 6.57, 5.95);
INSERT INTO reviews VALUES (884, 42500, 154, 'It was a blast playing this game, 10/10.', 'Super fun :( But we never could play more than 3 players the 4th player would just be kicked for no reason at all.', 'Mixed', 63.64, 15.60, 3.90);
INSERT INTO reviews VALUES (885, 42670, 2875, 'Old but gold. Honestly, I prefer playing this game to most 2024 releases. I''m not saying all 2024 games are bad, but I feel that about 90% of them are.', 'I was playing the game in hard mode, It is fully game-able. It has a unique Story line and different game-play. *2025*\nThe things that make it not so likeable game is because at places it is just blocking players progress  and I have seen unwanted graphical errors so many places, its just saddening ( not recommending as I have come across unplayable graphical errors . User cannot comprehend the play at all or would want to close application).', 'Very Positive', 91.90, 8.60, 17.12);
INSERT INTO reviews VALUES (886, 42680, 6417, 'Words cannot explain how freaking cool the original 2007-2011 Modern Warfare campaign is. Makes you feel like an absolute badass doing some badass work. Video games aren''t supposed to be a chore, they''re supposed to be a playable movie. Infinity Ward & Treyarch had it right, back then. So good.', 'lower the price', 'Very Positive', 87.94, 35.98, 0.42);
INSERT INTO reviews VALUES (887, 42700, 13437, 'Replayed it on PC 10 years after my last walkthrough and it was one of the best singleplayer experiences I had in a while.\n\nIt wasn''t just a nostalgia trip, Black Ops has the best CoD campaign ever.\n\n(Also lower the price, fucking rats)', 'Someone within Activision has cronic symptoms of Schizophrenia and presents somewhat of a sociopatic disorder to charge this price for a soon to be 15 year old game.\n\nThis employee may be trying to sabotage the company by forcing its customers to PIRATE their games over such erratic and nonsensical price tag. Maybe they should take a look at it.', 'Very Positive', 90.67, 7.33, 187.55);
INSERT INTO reviews VALUES (888, 42710, 1408, 'I''ll be honest, I didn''t play a lot of Call of Duty: Black Ops'' MP mode, mostly playing a bit for the relatively easy achievements, which don''t even require you to play against other people.\r\n\r\nAt any rate, I''ll say this: even though I played exclusively against bots, it was fun and engaging, with all the markings you''d expect from a Call of Duty game: killstreaks, ranking up, all that stuff. I''d say it''s still enjoyable in 2025.', 'pirate this game. i hate activision', 'Very Positive', 89.99, 1.55, 15.73);
INSERT INTO reviews VALUES (890, 42850, 191, 'While this game will always hold a special place in my heart and I do recommend it as an overall experience, in my mind Darkest Hour is simply a better version of AoD. THAT BEING SAID, this game is part of my childhood and honestly incredible. Might be on the more dated end but credit must be given where it is due. ALSO it''s leagues better than Hearts of Slop 4.', 'You can be ahead in every conceivable metric and still consistently lose every single battle possible. It makes no sense and quickly becomes pointless and obvious that your decisions strategically DO NOT MATTER in the slightest. Garbage no matter what anyone tries to say about this trash.', 'Very Positive', 84.29, 643.12, 45.57);
INSERT INTO reviews VALUES (891, 42890, 493, 'A friend of mine once described this game as the only legitimate heir to Master of Orion 2. \r\n\r\nHaving played it a fair bit now, I agree. If MoO2 was a favourite of yours and you can handle a game that takes a bit of time to understand and get in to, you might have a lot of fun with this.', 'This is not a Space Opera simulator if that''s what you were hoping for. This is one of those games that''s actually more like a board game. When you entering combat even if one side has 1000 ships and the other has 20, it only lets the sides 8 vs. 8 it and when units die reinforcements trickle in which means if someone rock-paper-scissors hard against someone else, 20 cheaper ships can easily win against infinite other ships. If you''re looking for a sense of realism or immersion, look elsewhere.', 'Very Positive', 88.84, 726.75, 15.65);
INSERT INTO reviews VALUES (893, 42910, 8467, 'Magicka is a comical indie action-adventure game where you play as an unassuming wizard attempting to save the world from evil. That might sound cliche though its intentional and the game is full of jokes and satire. You have 8 different elements to choose from and you can combine them into powerful spells with devastating effects. You will need to think fast on your feet as to which spells are best for the given situation thus you will need to use strategy as some levels are quite challenging. ', 'Do not buy this game, or downgrade it. The current steam version is one big bug, the game will permanently crash, it is nearly unplayable. Pretty bad customer support if you ask me', 'Very Positive', 83.56, 75.53, 19.82);
INSERT INTO reviews VALUES (898, 42960, 8916, 'Old but gold. Better than Victoria 3 in terms of warfare, otherwise it''s garbage in comparison to everything else. Send a small 10 stack to china and solo the entire country''s 1 million peasant army. Machine guns and poison gas attack cut through primitives like butter. The broken economy system is Trump''s wet dream: build a few random factories and max out taxes and tariffs and you''ll never worry about money ever again. Your people can be starving and riot but your faithful army is ready to mas', 'Trash game', 'Very Positive', 92.83, 548.77, 2971.33);
INSERT INTO reviews VALUES (899, 42980, 118, 'had fun, invaded central america as sweeden', 'Trash. If you add political factors to a game, you will spoil it. Paradox not only do this, but also never listen to players. If you buy this game, you can do nothing, including refund, when Paradox add something you don''t like to it. Paradox Interactive should close down.', 'Mixed', 69.49, 1.48, 0.08);
INSERT INTO reviews VALUES (900, 42990, 521, 'A competent galactic 4X game! BUT...get ready for that 2012 interface and gameplay mechanics. If you can get past some of the dated elements, the game is a worthy one to play.', 'Giving up on this game pretty much. I played the first one a lot. There are something I saw on the second that I liked that I wish would have been introduced in the first. I watched a few YouTube tutorials on how to play. The user interface is way worse than the first one. TBF the game never crashed on me yet... I shouldn''t have to watch hours of how to play in order to get the basics of the game.\nHere''s hoping maybe someday we''ll get a Sword of the Stars III with what people actually wanted fro', 'Mostly Negative', 38.39, 56.65, 0.63);
INSERT INTO reviews VALUES (901, 43000, 443, 'I was really hesitant to pick this game up for a long time because of its reception and score. But now, after completing it, i am really curious why? Is it because of the genre change? Yes, it''s definitely not Armored Core, but it''s still a solid B-tier game. There is some varied gameplay to enjoy in various locations. There’s no junk, there are almost no bugs (except for the one mission that seems to crash randomly), and it doesn’t overstay its welcome. Also, as in any Front Mission game, the w', 'Runs great until you reach the mission War Hero (the first on foot mission) which is so early in the game. The game hard crashes at random times throughout the mission forcing you to restart the whole thing every time. There are about 15+ "Fixes" the internet has to offer, from the simply stupid suggestion of turning it off and on to the outrageously absurd suggestion of completely buying a new "old" computer just to get through this one mission. This game is completely broken, don''t buy it. Unl', 'Mixed', 59.59, 8.12, 2.92);
INSERT INTO reviews VALUES (902, 43100, 134, 'Another classic game I originally played on the Wii. Always had the same zoo: monkeys, and only monkeys. Got it again recently and, though it isn''t complete like on the Wii, it still has its charm.', 'I paid 30$ for this game and i don''t even get to see the Elephant and crocodile. my 2 most favorite animals ever! world of zoo was my most favorite childhood game on the planet and this is how you reward me!? please for the love of god, game devs, update this game and bring back every single animal from the Wii! that includes the Antelopes, the Penguins, and the Bears!!! PLEASE!!!!!', 'Very Positive', 80.60, 2.20, 6.48);
INSERT INTO reviews VALUES (903, 43190, 258, 'The definition of a B-Game.\nThis game is like multiplayer cooperative third person shooter evil dead. \nThere isn''t much like it, seriously. The closest comparisions I could make would\nbe gears horde mode and left 4 dead but those don''t quite fit the bill.\nHidden gem, as far as I''m concerned.', 'This feels like a bad version of the original Killing Floor.', 'Very Positive', 84.11, 11.78, 2.48);
INSERT INTO reviews VALUES (905, 43600, 276, 'this is the second nancy drew game i have played and i really liked it :)  i really enjoyed going around and talking to the characters. the puzzles were quite easy and the game was short, but i still think the game was a lot of fun and i like the concept. a fun game if you want to play detective for a day!', 'The game itself, I LOVE. I''ve played almost all the Nancy Drew games and I replay them constantly. \r\n\r\nWhat I hate is that it''s almost unplayable due to the screen flashing in my face like a rave at every dialogue screen or whenever I have my inventory open. I''ve played this game on CD before, (before I had a Steam account), so this is some sort of weird bug with Steam? It flashes in my face until I exit out of those screens. If I had epilepsy, I wouldn''t be able to boot up the game. It''s really', 'Very Positive', 89.13, 5.13, 5.33);
INSERT INTO reviews VALUES (907, 44340, 442, 'I would recommend this game for someone seeking a more casual experience in a tactical shooter. The game hasn''t aged the best and can feel janky at times. I actually prefer this game''s predecessor Dragon Rising. \n\n6/10 for a decent console tactical shooter.\n', 'They should have called it Operation Crashpoint. It''s every few minutes.', 'Mixed', 55.66, 16.58, 21.22);
INSERT INTO reviews VALUES (908, 44350, 2829, 'https://steamcommunity.com/sharedfiles/filedetails/?id=2801090195\nhttps://steamcommunity.com/sharedfiles/filedetails/?id=2801543728\nhttps://steamcommunity.com/sharedfiles/filedetails/?id=2799923518', 'About 50% thru, no issues and suddenly the game crashes and clocks that as a DNF. WTF. Uninstalling immediately. "Drifting" is a joke. Impossible to chain, impossible to properly initiate and hold even with a hand brake & a "drift". I play to destress. Not to deal with this BS.', 'Mostly Positive', 75.79, 29.25, 39.85);
INSERT INTO reviews VALUES (911, 44690, 114, 'Don''t listen to negative recent reviews,the game rocks in 2024,with a bit googling it runs amazing and few mods easy to get you will enjoy,i own all racing sims and often run them one after the other,gt legends has the best career mode and for its age looks great and feels amazing,very complete game,get it  costs as much as a  coffee and a croissant at a  cheap cafe,the tires loosing grip sound will get you hooked', 'NOT WORKING ON WINDOWS 10. It worked wel on win 7 but unable to launch te game in windows 10. \n\nPlease fix so I can enjoy this game againg', 'Very Positive', 90.35, 1.52, 0.12);
INSERT INTO reviews VALUES (912, 45100, 524, 'Amazing alternative game to gift to Germans who can''t play more... intensive games.\n\nEDIT: Never mind. They decline it.', 'I bought this game because I thought it would be a fun little horse game but turns out it''s rubbish and has nothing in it.\nWhen you first join the game, it gives you one instruction, join the barn, but once you join the barn and name your horse it gives you NOTHING, there''s no tutorial teaching you anything, there''s nothing telling you about the currencies, it doesn''t tell you where to go next or even show you a little bit of the ropes. I thought for $5 how bad could it be? It''s awful. Do not wa', 'Very Positive', 81.68, 0.82, 0.78);
INSERT INTO reviews VALUES (914, 45300, 399, 'as an oap I can get a little bit negative when learning new stuff on the pc,  this destroys the learning process so I like to keep it simple and that is what this game does. I especially like viewing the target at the press of a button and then swinging back on release. The closing speeds on bombers seem to be a tad slow but other wise no complaints.', 'Game will not work on modern systems. Crazy that it is still up for sale on Steam when developer stopped supporting the product a long time ago. No matter how cheap the price might be on sale, it is still too much for a game that won''t even launch.', 'Mixed', 61.90, 2855.75, 3.42);
INSERT INTO reviews VALUES (915, 45400, 338, 'A really fun and unique game that combines aspects and themes of tower defense, bullet hell, strategy, and arcade style gameplay together. A super simple concept to get into that is a ton of fun to experience.', 'Do you like Qix? Do you like hex-editing those porno Qix clones on MAME so you can see the hot anime boob? Do you like squinting? Do you like medieval music? Do you like cheap ass games? Well then come hither, prithee milud, to this Qix clone with admittedly-bitchin'' medieval music where you have to squint to figure out what the fuck is going on and the whole thing is literally just Qix / those porno Qix clones that are balls-hard and you have to load cheats in order to survive long enough to se', 'Very Positive', 92.60, 6.75, 1.35);
INSERT INTO reviews VALUES (918, 45450, 158, 'very fun and easy to get into, the sountrack also slaps', 'I don''t like games with time pressure. For me, gaming is relaxation, time pressure and stress I have enough at work.', 'Very Positive', 90.51, 3.67, 17.58);
INSERT INTO reviews VALUES (919, 45720, 181, 'I can write a review for Lost Planet and you can''t, ha!', 'Crapcom updated the game today (29 may 2025) after 3.5 years of silence, ignoring everyone who had questions about it, despite promising that they would "let us know about the process of the investigation"\n\nThe problem with this update is they simply used a technique that is similar to the Xliveless to "fix" the game. This means the Games for windows live Calls are mostly gone, so while the game does work now, you lose out on all the features that was locked behind GFWL. (Achievements, Online an', 'Mixed', 56.91, 3.52, 65.02);
INSERT INTO reviews VALUES (920, 45740, 3254, 'Dead Rising 2 is the pinnacle of the series, expertly building upon the foundations of the first game while introducing innovative features that elevate the experience to new heights. The addition of seamless co-op gameplay allows you to team up with a friend, taking the zombie-slaying mayhem to unprecedented levels of fun and chaos. With its refined gameplay, expanded arsenal, and cooperative capabilities, Dead Rising 2 is the ultimate survival horror experience that surpasses its predecessor i', 'Great game, but horribly broken on pc. Also has missing dlc. I get that exclusivity deals exist, back then much more than they do now in fact, but there''s no need to hold them hostage any longer.', 'Mostly Positive', 77.41, 141.50, 24.62);
INSERT INTO reviews VALUES (921, 45760, 4867, 'Incredibly stupid, ugly game that is a blast to play', 'Its a big doo doo', 'Very Positive', 89.95, 170.90, 1042.98);
INSERT INTO reviews VALUES (922, 45770, 1637, 'why did they give frank such a ginormous ass in this game i''d love to play it but my huge boner gets in the way of my controller from staring at frank''s massive dumpy especially with that one piece bathing suit equipped capcom tried to make him older and out of shape but they only made him hotter thanks alot capcom you turend me gay for a man twice my age', 'No controller support in 2025. Having to download two separate programs isn''t controller support.', 'Mostly Positive', 77.89, 18.55, 57.72);
INSERT INTO reviews VALUES (925, 46250, 170, 'Melee combat feels awful, hitboxes are probably inconsistent, random objects can send you flying, your rockets have massive knockback on enemies but it appears that they actually pull the player character towards the explosion or at least downwards, you can get stuck on, in (?), next to and possibly under(?) enemies and some bossfights seem to involve quite a lot of luck. \r\n\r\nDespite this (or, in some situations, because of this) I have had more fun with this janky trainwreck than with most othe', 'I played and beat the first game, and i like it, an lot, then i heard about this prequel thinking it was also an nice game\ni was wrong, this garberg should be ILLEGAL to sell, bugged to an point to not be playables, such as, script erros as on the DAMN TANK LEVEL,graphics that look shit, and you can do nothing, since it will CRASH the DAMN GAME, terrbile gameplay WORST THAN ORIGINAL and all other shit i could say it\nand worst, you will paying way more than the original game to have an buggy mass', 'Mostly Positive', 72.94, 7.07, 34.35);
INSERT INTO reviews VALUES (926, 46260, 156, 'The game which every space game fan should be familiar with.\nInteresting story, fun dialogues and controls similar to EVE-Online.\n\nThe game was made by Elite-Games team, which is not an ordinary developer. \nIt''s an old Russian space games fan community, which was formed in 1999. It started with the forum related to X-Tension, and then more games were added, Freelancer, X3, Elite, all the good space games, and it grew into a big community with forum, guides and comprehensive database for space ga', 'Mouse doesn''t work properly on modern systems. There are a few ''fixes'' in the discussions but none of them worked for many of us. You might be lucky.', 'Mostly Positive', 74.36, 31.82, 0.42);
INSERT INTO reviews VALUES (927, 46270, 111, 'great real time strategy, wish someone could upscale it to modern systems', 'Basically unplayable on newer systems, probably due to legacy problems. Could not get the game to work smoothly. Framerate issues even when put in compatibility mode.', 'Mostly Positive', 71.17, 43.98, 0.15);
INSERT INTO reviews VALUES (929, 46290, 113, 'Someone said the game would not run on modern Systems with NVIDIA cards.\r\nI have a Geforce 3070 and the game runs fine, not a single crash so far.\r\nI recommend playing the game on NOVICE difficulty for the first campaign.', 'no longer works on Win 10 /11', 'Mixed', 57.52, 106.17, 7.12);
INSERT INTO reviews VALUES (933, 46370, 152, 'Plays Super Good For A Game Made in 2010', 'its not holding up well in 2025', 'Mixed', 61.84, 7.70, 34.32);
INSERT INTO reviews VALUES (935, 46400, 117, 'This is an isometric action RPG. Everything you love about the Diablo games, or Torchlight, or Titan Quest/Grim Dawn has been toned down quite a bit here. Not as many classes or skills or equipment options. I haven''t even run into any side quests yet. So, in essence, this is a poor man''s sci-fi version of Diablo. However.... this is a poor man''s SCI-FI version of Diablo. Fighting robots and mutants and aliens on spaceships and distant worlds is a very cool idea for this genre. The graphics aren''', 'I enjoyed ''Greed: Black Border'' for its classic isometric RPG elements, but the game has some significant issues. The boss fights were particularly difficult, which took away from the fun. The real deal breaker, though, was the game crashing with a script error right after I defeated the final boss. I missed out on the ending video entirely—thank goodness for YouTube, where I was able to watch it. This technical flaw really dampened what could have been a satisfying conclusion.', 'Mixed', 45.30, 18.02, 31.30);
INSERT INTO reviews VALUES (936, 46410, 158, 'This game was so peak. And i may just be biased since i was very addicted to it for around decade ago with a physical copy of the game that was lost. To this day i can never forget the seminar rooms ost... It''s still probably is my favourite spellcasting game even though there aren''t that large variety of spells except upgrading them to a better one... And spin to win cyclone is still the best way to play the game, or soul meteor if you''re going for soul magic route... or just go both if you cou', 'This game is old, and it shows but it is slightly better than it appears. I nearly gave up due the poor control but with changing the camera behind the character, it was playable. The game initially bombed out at the start, but changing the config as suggested by others made it work for me. \n\nI even said I was having fun when I got to bash up the bully - three times! Voice acting is great even though the speech was a bit slow than ideal. The initial positive impression soon turned negative howev', 'Mostly Positive', 72.78, 11.77, 1.57);
INSERT INTO reviews VALUES (937, 46440, 137, 'Dont buy it', 'Advance Wars Declares War On Future Wars: When the Past Judges the Future\n\n\n\nOrange Star''s finest—and their frenemies—gather to play a turn-based strategy game that promises to be the future of tactical warfare. What follows is a hilarious disaster.\n\n\n\nAct 1: The Great Gaming Summit\n\nScene: The Orange Star Lounge. Tables are piled high with snacks, and a dusty game box labeled Future Wars sits ominously at the center. Andy beams with excitement.\n\nAndy: "Alright, everyone, you’re in for a treat! ', 'Mostly Negative', 29.93, 0.22, 1.50);
INSERT INTO reviews VALUES (938, 46450, 223, 'If you are a fan of old school Fire Emblem and similar games, this is likely to be a very enjoyable experience.\r\nThe story isn''t particularly complicated, but what there is is none the less satisfying with some interesting twists. There aren''t many different locations to visit, but it none the less does a decent job of using what it does have well - and even plays it for humour at one point, highlighting that you have been to a location before.\r\nThe actual strategic systems are a bit clunky, but', 'The game glitches constantly.  You get stuck in combat mode or a character gets frozen in place.  You have to save and get out of the game and go back in to fix it.  Otherwise, it''s fine.  The game is fully misogynistic but in a humorous way.  Turn based combat works fine, but any time you have npc allies, they will attack you instead of the enemy.  If I hadn''t gotten it in a three-game pack for 2.00, I would feel ripped off.', 'Mixed', 53.81, 24.83, 9.28);
INSERT INTO reviews VALUES (939, 46460, 230, 'Underrated game. Music is good. The creepy atmosphere is good One of my favourites. Recommend it if you like and enjoy point & click games like I do. \n7/10', 'Scratches is the Victorian mansion version of Gone Home: explore an empty house, rummage through the previous owner''s things, slowly unlock access to more rooms of the house, and eventually unravel a mystery that is only slightly more interesting than the one in Gone Home.\n\nI know this game was removed from Steam years ago, and I have heard that it is quite difficult to obtain a key for it now (I bought my copy years ago and only just now got around to playing it). I am posting this review to sa', 'Very Positive', 82.61, 21.00, 5.80);
INSERT INTO reviews VALUES (940, 46480, 398, 'Its a shame that this game is sandwiched in between a lackluster prequel and a god awful sequel. If u play any game in this series pick this one.', 'Download dgVoodoo and drop the appropriate DLLs into the game''s installation folder to avoid issues on newer hardware.\n\nYet another reason why Steam needs a "meh" button. The story, up until the ending, is fine and has you wanting to progress to solve the case, but the puzzles range from annoying, to impossible to solve without a walkthrough. The worst are presented as logic puzzles, but logic only gets you so far and you ultimately need to make some wild guesses to reach the solution. A good pu', 'Very Positive', 81.66, 8.43, 13.27);
INSERT INTO reviews VALUES (941, 46490, 217, 'good game just needed a youtube toutorial to finish it lmao besides the game machnism is little buggy if you skipped one item or clue u will stuck', 'If you were at all intrigued by the original, pretend this doesn''t exist.', 'Mixed', 40.55, 20.97, 9.53);
INSERT INTO reviews VALUES (942, 46500, 1329, 'https://steamcommunity.com/sharedfiles/filedetails/?id=455764396\nhttps://steamcommunity.com/sharedfiles/filedetails/?id=524459830\nhttps://steamcommunity.com/sharedfiles/filedetails/?id=456413315', 'Another recent reviewer said they hated Syberia because it disrespects your time, and this is exactly correct. Nearly everything you do is done in service of padding the play time without providing meaningful content. Very little feels necessary, and even less feels rewarding.\n\nSyberia is billed as a puzzle game, but you''ll find no puzzles here, only tasks. These tasks, with very few exceptions, amount to either fetch quests, or pixel hunts, or sometimes both. I call them ''tasks'' because they''re', 'Very Positive', 84.88, 8.23, 10.20);
INSERT INTO reviews VALUES (943, 46510, 559, 'I spent my childhood here. Thank you for the unrepeatable memories', 'It''s a classic, the vibe is great, the story is lovely.\r\nBut playing this game is such a hassle.\r\nToo many useless location in between the main locations and you have to get to this end of the map to the other end with no skippable walking animation.\r\nToo many conditions must be met for an option to show up.\r\nPlayed this for 3 hours, out of which for 2 hours I just walked probably.', 'Very Positive', 85.15, 2.12, 3.72);
INSERT INTO reviews VALUES (945, 46540, 264, 'Outbreak is an intense and thrilling game that keeps you on the edge of your seat. The gameplay is engaging, and the graphics are impressive. I highly recommend it to fans of action and survival games!', 'Has potential, but terrible controls combined with anti-user interface makes it not fun to play. It would be okay, if it was ten year old game ... but its just two years :-(', 'Mostly Negative', 36.36, 4.47, 1.45);
INSERT INTO reviews VALUES (946, 46550, 157, 'Okay, listen, umm.. this is not as I don''t like this game, buuut.. I guess, too much time passed after the last play. And it was cool back then. I loved this game deeply. All this creepy atmosphere, all dialogues, being scared about the ending (since there is a bad one), all these animations, dark tone of locations.. And I felt it, for some time! In first 20-30 mins. Then, everything is gone. \nFirst, it doesn''t want to work properly, I got some bugs, and I was irritated by some music, that put m', 'This is has to be the worst designed point and click i ever played to this day. Story is your standard B-movie like mystical thriller, nothing special in that regard. VA are atrocious, listening to americans pretending to be french physically hurts. Narrative presentation is... also atrocious. Developers tried to create non linear game and failed hard. Often dialogs make no sense, as character start to blabber about things that did not happened at that moment or protagonist had no clue at that p', 'Mixed', 48.41, 6.58, 11.15);
INSERT INTO reviews VALUES (947, 46560, 480, 'Really fun game. Its not an action game, more tactics. Unfortunatly, it doesn''t play unless you install this performance fix:\r\n\r\n(https://www.moddb.com/games/robin-hood-the-legend-of-sherwood/downloads/robin-hood-performance-fix1)\r\n\r\n', 'This game is great but DO NOT BUY IT ON STEAM the stem edition is horrible and will not work. The screenshots they use on the title are not even from this actual game but one called desperados. Buy it somewhere else they butchered it for steam', 'Mixed', 61.04, 4.78, 0.08);
INSERT INTO reviews VALUES (948, 46570, 108, 'This seems to be the only out of the trilogy that is playable.. quite sad really as the humour seems top  class and has a few funny references but I would say the only negative is its a bit too dark thats all.', 'Terrible experience\n\nI really enjoyed the first game, it was a fun game, simple, just being a parody \n\nThe second one, well, it''s full of bugs, the camera is your worst enemy, no minimaps, no compass, very easy to get lost, most quests are broken, the story is simple but I actually was enjoying it, I put 10 hours on this game, I was visiting everything and talking to everyone, until I realized the main quest was bugged and I just can''t advance, this i beyond frustrating\n\nIs a very old game so th', 'Mixed', 44.44, 3.75, 14.75);
INSERT INTO reviews VALUES (955, 46750, 147, 'First off, only get this game on sale. Even though I recommend it, I don''t for $13. It''s more of a under $5 game. Also if you are looking for a really creepy game that keeps you on your toes, and/or have balls of steel, then this game might not be for you. This game has a few good jump scares but for the most part you end up losing the fear until the jump scare puts you back into it. And if you are pretty comfy with most horror games then the jump scares will make you jump a bit then be like "Me', 'Weird, creepy point and click adventure/puzzle game that''s better played with a guide.', 'Mixed', 59.18, 9.53, 10.82);
INSERT INTO reviews VALUES (957, 46770, 226, 'I have no idea if the game is good or bad but it has some pretty cool emojis.', 'This is a strategy game were you, control your Nation of choosing and lead them to a new age of ligth or darkness. You can try to remain neutral in a world at war, join a faction or make your own. What ever you pick, the game will be interesting and unpredictable. However, unlike the first Making History game, this game has several issues; like crashes, wrong ideologies in several countries, and a horrible menu. The game is fun, the graphics are better than the previous one but that doesn''t make', 'Very Positive', 82.30, 2.52, 28.80);
INSERT INTO reviews VALUES (962, 47000, 342, 'Fantastic game!', 'Do not buy. A very good game, but force crashes every time on launch.\n\nThis has been reported to the devs numerous times in the discussion, but Devs apparently don''t care.', 'Very Positive', 85.96, 37.32, 0.08);
INSERT INTO reviews VALUES (966, 47400, 1586, 'This deserves to be in a much better standing than mostly negative, i don''t understand the hate?\n\nThe game is a 3d version of the original, just a different plot, modernised and good graphics, music has been changed a bit and a few good extra tracks thrown in, Its still a lot of fun.\n\nTo be honest, wish i bought and played it sooner, its good. get it.', 'Pick up this game on a dirt cheap offer you''ll maybe get a few hours of game-play out of it before you lose interest.\n\nSeriously, what the hell Firefly? How do you produce magnificent gems like Stronghold 1 & 2 and royally botch the third so badly? Was your budget cut, are you merging with Ubisoft or EA? How do you strip so many features from the existing games and call it a squeal!? \n\nYou had perfect results from Stronghold 2. Your castle felt alive. You could watch feasts & dances, Had a funct', 'Mostly Negative', 26.36, 2.68, 14.35);
INSERT INTO reviews VALUES (970, 47540, 256, 'Fantastic game, there''s a great pace during the combat and the battles get better & better. The music fits in such a perfect fashion, it''s quite magnificent. I''ve certainly got my monies worth anyway.', 'Reinstalled after not playing this for years.  I played for a while last night and it was fine, now it won''t run.  All I get is a black screen. Reinstall didn''t fix it.  Looks like its broken.', 'Very Positive', 81.64, 387.50, 113.28);
INSERT INTO reviews VALUES (972, 47780, 10416, 'Dead Space 2 is even better than Dead Space 1. It has all of the good things the first game has and builds upon them, has almost none of the bad ones, the graphics are better, Isaac now actually has a personality, the game has many setpiece sequences and the gameplay is faster, gorier and even more fun. It''s one of those games that I consider a perfect sequel.', 'Delist EA. Forcing third-party accounts and banning for inactivity with no appeal is predatory.', 'Very Positive', 93.38, 16.15, 5.15);
INSERT INTO reviews VALUES (973, 47790, 2240, 'This game was slept on. The single player campaign was really fun, stunning graphics, very emotional, very authentic seeming. It made you seem as though you were actually involved in the fight. It''s such an shame the series had to die.', 'Not easily backwards compatible for Windows 11. Actually, not at all.', 'Mostly Positive', 79.64, 7.70, 20.32);
INSERT INTO reviews VALUES (976, 47890, 19660, 'I love this game. It reminds me of the good old days!! I love putting my Sims into the pool then surrounding them with a fence, and slowly drowning them as they get more and more exasperated.', 'This game simply does not work on modern hardware or windows 11. It is an incredible game but EA must be held accountable for continuing to sell an unplayable game', 'Very Positive', 87.19, 3085.72, 29.17);
INSERT INTO reviews VALUES (977, 47920, 1009, 'You have to disable steering delay/damping in the config file (DampeningEnabled="0") and it plays great.', 'EA Licensing prevents the user who PAID FOR THE GAME to uninstall/reinstall the game more than 3 times. If you do this, you will be locked out of the game you paid for and unable to play. \r\n\r\nMakes you want to kick the teeth out of all the EA weenies that thought this was a good idea.', 'Mixed', 59.76, 27.73, 43.20);
INSERT INTO reviews VALUES (978, 48000, 11773, 'Played the game a few years ago and finally decided to come back and get the last achievement recently.  The first run may take a few hours and experienced players can finish within a hour.  Overall a good indie and recommended to play.\n\nTo complete the game in one sitting with no more than 5 deaths is not easy but very doable after some practice.  It’s essential to know how to solve each puzzle quickly and save death counts for those areas require accurate timings.  Using chapter select to prac', 'The first half is decent. But puzzles in the second half rely on timing and extreme precision rather than thinking. Given how janky and awful the platforming is, the game significantly drops in the second half.', 'Very Positive', 91.86, 16.87, 3.40);
INSERT INTO reviews VALUES (979, 48110, 1403, 'SH5 as a base game is very buggy and not worth playing but with The Wolves of Steel megamod (from subsim) it is basically SH3 with first person and better graphics, if you like sim games, get it BUT with mods.', 'Dear Ubisoft, you guys are disgusting. A great game that ubisoft never deserved to have. Seriously, dont buy this, its probably the best sub game ever but wont run because ubisoft is the Stellantis of the game world, just dont.', 'Mixed', 41.70, 11.23, 38.03);
INSERT INTO reviews VALUES (982, 48190, 7922, 'You play Ubisoft''s new Assassin''s Creed games like Valhalla or Mirage, none of which have the gameplay and storyline of the Ezio trilogy.\n\nThe legacy of Ubisoft is kept alive by this trilogy.', 'Ubisoft you MUST get rid of the Ubisoft Connect launcher for singleplayer games on Steam. There''s no other way around it. You either put them on Steam with no launcher or don''t put them on Steam entirely.', 'Very Positive', 86.39, 30.98, 27.80);
INSERT INTO reviews VALUES (983, 48220, 3781, 'https://steamcommunity.com/sharedfiles/filedetails/?id=3468987527\nhttps://steamcommunity.com/sharedfiles/filedetails/?id=3468987041\nhttps://steamcommunity.com/sharedfiles/filedetails/?id=3468987129', 'I wanted to play this game after some years, and my old ubisoft account has dissappeared without a chance to recover the account, and if I create a new account, what do you think? the activation code is registered to the old account so I can''t play my game. Ubisoft I hope you get bankrupt greedy aholes.', 'Mostly Negative', 37.61, 135.83, 112.40);
INSERT INTO reviews VALUES (984, 48240, 6717, 'Always loved this game but a little disappointed to see all the negative activation/DRM/License stuff. I was gonna get the rest of the DLC but now i''m unsure about Ubisoft & their Licensing Policy. Will this game still be active in 10 years? Do I even own it? If I don''t a Game I''m not spending my heard earned Money on it, sometimes I come back to old Games years later! If the Games industry is gonna be a dictator then I''m out of Gaming altogether or just won''t buy any new ones.', 'game refuses to play\nhad to pirate a copy to get it to work\nno wonder ubisoft is going bankrupt', 'Mixed', 54.52, 134.70, 9.97);
INSERT INTO reviews VALUES (985, 48700, 53840, '+ Fun gameplay loop\r\n+ After a while everything becomes automatic and you can just zone out and enjoy\r\n+ Excellent total conversion mods\r\n- I need to go to bed', 'it looks very dated, it''s deeply frustrating to play, and lacks depth. i''ve tried quite hard to give this game its fair shake, but i think it''s too niche for me to recommend to a general audience.', 'Overwhelmingly Positive', 97.73, 376.10, 36.77);
INSERT INTO reviews VALUES (986, 48720, 3172, 'day 36: joined the polish commonwealth thinking it was a good idea. took a fort by myself, got paid in salted fish and a rusty pistol. mercenaries are threatening to leave because i can’t pay them in bread. cossacks burned down my village. there''s a siege tomorrow.', 'Mod, not a game.', 'Very Positive', 82.16, 11.25, 10.00);
INSERT INTO reviews VALUES (987, 48800, 953, 'Ok, it''s an older game.  The graphics remind me sometime from Microsoft Flight Sim 2004(9).  That''s not a bad thing.  However it''s not HD either.  I''m running Win 10.  At times the game has a glitch or something and crashes.  So I save game play often.  I find the the controls work with keyboard/mouse and game pad.  This is not a fast in your face running in circles type of game like Forza, where it''s always hands on the controls.  Many times the ships are slow, you''re waiting out period before ', 'Game is broken and refuses to launch, fix your legacy software BEFORE YOU PUT IT ON STEAM', 'Mixed', 50.16, 8.02, 1.38);
INSERT INTO reviews VALUES (989, 48950, 276, 'One of the best competitive strategy games out there. Only thing it''s really missing is a map maker.', 'At first blush, this game seemed like it would be pretty good - but that feeling doesn''t hold up over time.   While there are 4 different factions in the game, they share the same 4 units.  The single player campaign quickly becomes tedious when all battles consist of the same exact strategy,  I can imagine this game might be more enjoyable multiplayer, but that aspect is pretty dead.', 'Very Positive', 88.77, 7.47, 6.75);
INSERT INTO reviews VALUES (994, 49540, 4091, 'I remember going to the GameStop at our local mall with my mom to preorder this game as a birthday present, since it was coming out just a few days after my birthday. Not a perfect game by any means, but I have some good memories with this one... Thanks, mom.', 'I''ve seen alot of good reviews lately trying to paint this game as an overhated, underrated gem of an experience. Do NOT get it twisted. This game is absolute trash. The story is almost laughably bad. The characters are so incredibly moronic that the plot happens in spite of them. \nBUT. The Pulse Rifle is fun to shoot. The Aliens go pop when you shoot them. It''s delightfully trash.', 'Mixed', 56.88, 14.10, 26.17);
INSERT INTO reviews VALUES (995, 49600, 3446, 'Those hundred gigabytes of pirated music will come in handy now!', 'cant/wont sync to music any more', 'Overwhelmingly Positive', 95.07, 5.42, 26.47);
INSERT INTO reviews VALUES (996, 49800, 179, 'I’ll be honest, I didn’t even know Guns Of Icarus had a predecessor until I looked on the Wikipedia page earlier this month. This entry displays many characteristics of what I would assume to be inspirations (Laputa: Castle In The Sky, Mad Max, maybe even a little Star Wars or Fifth Element), and I feel that a lot of said inspiration was also lost during the development of the following entries. Then again, I haven’t played any of the Icarus games in over a decade, so maybe I’m just misrememberi', 'Stop.  Don''t buy this game.  This is NOT "Guns Of Icarus Online", which is probably the game you''re here to buy.  This game is three years old, has terrible graphics and equally bad gameplay, and is not the game you''re looking for.\n\nAgain, let me reiterate.  The game you are looking for is "Guns Of Icarus Online", not "Guns Of Icarus".  If you don''t want to take my word for it, look at the screenshots for both; the difference in quality is pretty clear.', 'Mostly Negative', 39.11, 2.33, 0.52);
INSERT INTO reviews VALUES (998, 49900, 147, 'This game is awesome and super fun. Sadly there is no multiplayer crowd left. So unless you are planning to have a super fun lan party then don''t buy this game.', 'Boring, dead, confusing and ugly.', 'Mixed', 65.99, 23.73, 0.17);
INSERT INTO reviews VALUES (999, 50000, 149, 'Nimbus is a lot of fun and very pretty, and it''s basically just as challenging as you want it to be. There are a lot of optional levels, you can configure how you want the checkpoints to work, and your time records don''t unlock any content or anything so it doesn''t matter if you don''t care about trying to accomplish them.\n\nHowever...\n\nIf you _are_ interested in time records, be aware that Nimbus has one enormous bug: it bases its records on how much time elapses in the real world between the beg', '1/10. Game blows. Ignoring the questionable game design, the main premise of this game is to challenge the player with awkward controls. Both in game and out of game (settings). For example, configuring the gamepad is not intuitive--how do you delete a mis-binding to multiple keys?--and no in game keyboard remapping. Stupid! Fortunately, I didn''t pay very much for this game, but it was too much. I may revisist this title to give it a second chance, but doubt it. RGH', 'Very Positive', 94.63, 35.75, 0.18);
INSERT INTO reviews VALUES (1001, 50130, 9762, 'STILL THE BEST MAFIA EVER\n\nif you want to play this game, just play the classic version.\ni highly not recommend playing the definitive edition version, as it has a lot of bugs and performance issues and only has a few graphic improvements.', 'Basically can''t run on modern hardware. No one has any real idea why. No working solutions as far as I can find.', 'Very Positive', 91.29, 6.55, 0.60);
INSERT INTO reviews VALUES (1003, 50620, 3002, 'Christianity is quite awesome for Fantasy Games.', 'Unplayable on newer systems even with dll fix and Windows 98 compatibility mode.\nPlay the Warmastered edition instead.', 'Very Positive', 87.14, 37.23, 2.28);
INSERT INTO reviews VALUES (1012, 50990, 120, 'A true classic hidden object game. I was very pleasantly surprised to find this game would run on my current PC as so many of these older games just can''t function. Challenging enough to make you think and actually hunt through the scenes but not so complicated to feel like you can''t actually finish.', 'I''m sorry, but every time i tried to change the size to full screen the game bugged out and was literally unplayable, because it would open two of the small windows and skip between the two at rapid speed.\nI was looking forward to playing this, but sadly due to technical errors i can''t :/', 'Very Positive', 91.67, 4.62, 0.15);
INSERT INTO reviews VALUES (1013, 51000, 101, 'Relaxing nostalgia trip.\r\nA wonderful game, whose polish and shine hasn''t rubbed away over the years. The atmosphere is flawlessly downcast, accompanied by a phenomenal soundtrack; While the game''s puzzles and object scenes are interesting enough to use your brain to a satisfying degree. (With optional hint/skip button just in case.)\r\nEven without the previous plot, the story tells itself to a capacity of understanding for a one-off playthrough to make sense.\r\nThe journal is really detailed too,', 'This one kinda sucks. Get it on sale. There are better HOGs out there.', 'Very Positive', 82.18, 4.87, 3.87);
INSERT INTO reviews VALUES (1014, 51010, 119, 'I LOVE THIS GAME!!!!!!!! IT DOESN''T EVEN MATTER THAT I CAN''T CHANGE THE RESOLUTION!!!!! I ENJOY ALL 3 PIXELS', 'I used to play the Facebook version when I was younger, which I enjoyed, but this version functions differently, and from my experience playing, the islanders age *way* too fast while you''re gone, and die off very quickly, which I never had trouble with in the other version. \nUnfortunately I couldn''t refund it because despite not being able to play much at a time, I''d played for 11 hours - the issue of the islanders aging too quickly, even despite being on the "slow" time setting, only became ob', 'Very Positive', 83.19, 7.63, 11.58);
INSERT INTO reviews VALUES (1017, 51060, 108, 'I played this game when it first came out 15 years ago at another site.  I remember that it had been hugely popular back then but had forgotten so many of the details.  I was very happy to see that it plays fine on Windows 10 and had no problems at all.  A very unique puzzle game that is delightful with a large variety of puzzles, some harder than others.  This is the first of three in the series and is continued in the next two "Drawn" games.  The art style and music are so well done creating a', 'WARNING:\nIf you press any of the main menu buttons that involve changing the game resolution, the game permanently bricks. Even if you uninstall it and reinstall, erase all files, delete steam cloud, or do anything, the game will be permanently broken never be able to start up again. Do not buy, at least not on steam.', 'Very Positive', 85.19, 4.70, 0.15);
INSERT INTO reviews VALUES (1019, 55000, 180, 'great game back  in its day still good today.', 'Very cool style, both with the sound-track and the story elements. The gameplay is simple and fun. I as really excited to try this out after finding it in my library from some long ago sale.\n\nIt is, unfortunately, not functional. Specifically there is no save system. Super strange to have a campaign with no save. After playing it a few times just leaving it on when I had to go do something else though I also realized that there is virtually no "content" in the campaign. The very cool animal-alie', 'Very Positive', 85.56, 0.13, 1.15);
INSERT INTO reviews VALUES (1021, 55040, 892, 'Honestly, it''s my favourite game in the zombie genre. It is a very cool concept that sadly is not used more often and that is actually managing evacuation efforts and fighting zombies from a government/military point of view. The mechanics of the game are pretty simple but allow for much replayability especially if you use mods such as Ground War. Mechanics are also great for getting into the mindset of so many military officials in the movies and games that simply carpet-bomb the entire parts o', 'Game is very interesting, but achievements doesn''t work no more :-(', 'Very Positive', 90.13, 19.07, 8.27);
INSERT INTO reviews VALUES (1022, 55110, 1247, ' Gear of war in red army version\nquite nice FPS title like gear of war mix in halo serial, the environment repair system is really kool, massive option of the weapons for you to choice, still the enemy hp are too high, need way too many ammo to take down one single enemy, there offer smooth save system.\n\nthere are mech and vehicle for you in story, quite a lot of content and creative to create this game that I personal admiral this game developer, story is serviceable and smooth, not too stupid ', 'Who ever designed these enemies deserves to be promoted to unemployed gamer.', 'Mixed', 66.64, 9.03, 7.18);
INSERT INTO reviews VALUES (1023, 55140, 1634, 'Please add sex with Big Tiddy Goth Chicks', 'Great in the sense of freestyle / arcade and that is it. Unless your in fifth gear all the time, you will case every single jump. No tempo / rhythm to this game. Definitely not a sim at all.', 'Very Positive', 88.74, 5.70, 6.03);
INSERT INTO reviews VALUES (1024, 55150, 11015, 'I feel like I should hold a funeral service for this game after this week. It''s been neglected for years but there were enough of us to keep PvP going to some degree. This will likely be the end of that. RIP SM1. Thanks for all the fun and no thanks for all the BS host migrations, glitches and hackers. Otherwise good sh!t. Rest easy you beautiful broken game...', 'I''m only giving this a negative because sega decided to re price this game at $59 when it was $19 since 2021. This game which came out in 2011 is a good singleplayer experience, but I implore anyone interested in playing this in preparation  for spacemarine 2 to steer clear. Sega and these greedy devs should be ashamed. Please don''t spend your money until they reprice it back to $20', 'Very Positive', 92.21, 2575.80, 3.20);
INSERT INTO reviews VALUES (1025, 55230, 18575, 'Saints Row: The Third is a fun, chaotic open-world game filled with humor, crazy missions, and over-the-top action.\nThe characters in the game were really fun and unique, with hilarious dialogue.\nCustomizing characters and the voice acting were amazing. I played through all the DLCs except one where the AI was really bad, but the rest were great.\nDefinitely, out of the entire Saints Row series, this was the best experience for me.\n7.5/10', 'Tried to download and play it but couldn''t enjoy it with the constant stutter that occurred every ten seconds or so. It''s a shame how many of these old games are unplayable and often times the remasters are just as bad or worse. A great game but you''d be better off buying an old console and playing it on console in my opinion unless they release a re-remaster that isn''t buggy.', 'Very Positive', 94.37, 19.27, 0.75);
INSERT INTO reviews VALUES (1026, 56400, 4316, 'Very good game trying to figure out how to scam steam Because its so forgotten by the devs they forgot to put it on sale', 'It would be better if you finally release a new patch for all your games and add support for 16 core processors so that people with such systems can play now.', 'Very Positive', 90.11, 14.57, 142.68);
INSERT INTO reviews VALUES (1027, 56437, 4317, 'Very good game trying to figure out how to scam steam Because its so forgotten by the devs they forgot to put it on sale', 'It would be better if you finally release a new patch for all your games and add support for 16 core processors so that people with such systems can play now.', 'Very Positive', 90.11, 14.57, 142.68);
INSERT INTO reviews VALUES (1030, 57200, 214, 'Puzzle Dimension provides probably 100 levels of very smart and intelligent puzzle design.  Because of its 3D environments you really need to plan your path well.\r\n\r\nYou are a ball that rolls around pre-determined maps where you collect flowers.  Once you''ve collected all of the flowers the end level portal opens up.  Maps start out very simple where you can move from one path block to another.  As you proceed further into the game you will find hidden blocks, spikes, icy blocks where you can''t ', 'I just dislike the way the camera works, having to constantly rotate it to see where you need to go.\n\nFor me, that''s a gamebreaker.', 'Very Positive', 89.72, 53.82, 0.18);
INSERT INTO reviews VALUES (1031, 57300, 12264, 'A game that started my horror obsession when I was a child.\n\nMy favorite thing in this game, that you can download and play with this forever because it have a ''custom story'' mode.\nAfter 10 years this can still make me scare the sh*t out of me.\n                      10/10                                                     It''s really a legend for every horror game lover!', 'Not even an hour into the game, i hear footsteps and hide in a cabinet.\ni then was so scared that i exited the game and refunded.\n\n0/10 My pants will need to be washed 1,000,000 after playing this game.', 'Overwhelmingly Positive', 95.99, 1138.23, 0.63);
INSERT INTO reviews VALUES (1032, 57400, 1133, '', 'Slow response.\nCounters are poorly registered.\n', 'Overwhelmingly Positive', 98.50, 17.25, 27.47);
INSERT INTO reviews VALUES (1033, 57620, 231, '⠀', 'I played this game on Steam a few years ago without ever creating a login account. Now, I can’t play it unless I have a Patrician IV login. Why do I have to go through all this hassle just to play an older game I already paid for? It’s sucks. \r\n', 'Mixed', 51.08, 13.53, 14.83);
INSERT INTO reviews VALUES (1034, 57650, 460, 'I love the different take on Dungeon Crafting that is presented in Dungeons. The idea of luring the heroes in, making them as happy as possible, and then sucking the soul energy from them as they die is truly diabolical and befitting of the genre. Years prior to purchasing this bundle, I bought Dungeons on CD and decided to get the bundle for all the added content that I do not have. \r\n\r\nMy only criticism of the game is that the initial tutorial level didn''t seem to clearly explain the goals for', 'I came here after jumping in the series with Dungeons 3. What a sobering experience it was.\r\n\r\nAfter reading by all that it is NOT the later games and not DK, but is about getting heroes happy and then "harvesting them, I went through the act of trying it. The first 3 levels I played were still part of the into into the game mechanics but oh boy was it clunky and no intuitive. Cutscenes are weird and distort your already confused world view. You have a weird character skill tree that sort of loo', 'Mixed', 42.17, 49.17, 19.48);
INSERT INTO reviews VALUES (1035, 57680, 253, 'I would really recommend the game. Great immersive story given with dignity to European history it really deserves. The gameplay is really great and includes both combat and puzzles. Still good graphic (keep in mind the year the game was released). To add some ctiticism, I would say there are minor correction to the story, but they are really minor.', 'Buyer beware, this game requires account creation & key activation through a non-functional Kalypso launcher. I recommend getting it on GOG as a third party won''t prevent you from playing on that platform.', 'Mixed', 69.57, 22.02, 11.17);
INSERT INTO reviews VALUES (1036, 57690, 4869, 'If being a dictator is your life long dream then I suggest choosing Tropico 4. Some of the new woke Tropicos cant compete with the good old days of oppressing an entire island with the press of a button. In the newer tropicos if you try to oppress them, your people, like redditors, leave their homes (in game) and try to cancel your regime using protests. This forces you to deal with them by putting up radios and guard towers. However, my dream of becoming a dictator doesnt involve managing my po', 'Tropico 4 has depth and an excellent vibe despite some confusion.\n\nThe mechanics all appear to be connected with a sense of balance, but certain details are not clear, especially regarding some of the buildings - How many of them do you need? Where are you supposed to put them? Do they need free space around them? Why do they disappear? Some are obvious, but others are left unexplained. Some of the mission goals should have offered detailed hints.\n\nYou don''t seem to need to play "optimally" to p', 'Very Positive', 91.29, 63.88, 36.63);
INSERT INTO reviews VALUES (1038, 57740, 546, 'distinctive gameplay, despite some bugs and design problems;\nenemy balancing & AI is quite a problem, you can''t really make any tactics whenever a bunch of armored AI try to push you', 'at about 3 hours in across 2 seshions(forgive my bad spelling) my game started lagging badly,and for no explainable reason,i have a good computer(i7-8700 and nvidia 1650) yet i got frame rates averaging 7 highs of 20 and lows of 1 i cant blame my isp cause this is a single player offline game,my mercs are for some reason ret@rded,running into each other facing the opposite direction i tell them to look in,shooting each other on accident or simply not shooting at all,and if that wasnt bad enough ', 'Mixed', 69.05, 97.47, 4.10);
INSERT INTO reviews VALUES (1040, 57900, 3620, 'At the time this game came out it was judged by the contemporary standard of gaming. \r\n\r\nNow that we have seen where games have gone, this is nothing but a breath of fresh air and nostalgia for times long gone.\r\n\r\nHAIL TO THE KING!!!!', 'got banned from a server for calling someone a P***y in the game where the main character calls everyone a P***y', 'Mixed', 66.57, 6.58, 7.22);
INSERT INTO reviews VALUES (1041, 58200, 197, 'Jolly good game! It features everything a bold adventure has to feature and playing it is a lot of fun. What else to ask for?', 'https://youtu.be/U-hQ5FimXZA\n\nTrying very hard to be funny but missing the mark with the drag caused by puzzle design issues keep either side of the formula from landing.', 'Very Positive', 87.82, 16.25, 0.62);
INSERT INTO reviews VALUES (1044, 58520, 542, 'You like Blood Bowl? This is the best version and value for money. Done.', 'It was like I was playing against loaded dice. save yourself the frustration and pay no heed to the glaze because its thick. This is nothing like the board game I remember which was brutal and unforgiving but dice rolls did not fail every play.', 'Mostly Positive', 79.89, 20.12, 3.00);
INSERT INTO reviews VALUES (1045, 58550, 255, 'First off, I am recommending this game only for diehard fans of A Song of Ice and Fire, or anyone that wants an entertaining way of exploring the history of Westeros.  Obviously, this isn''t the HBO branded Game of Thrones you might be used to so the art or characters may look a little bit different.  \n\nThe way you play this game is a very dumbed down version of any RTS you may think of, build units, take towns and castles, kill your enemy.  The way any single player vs AI or multiplayer game wor', 'Bought and played it around the start of the Game of Thrones hype-train, and it was a massive letdown. \n\nThe screenshots show a dragon unit, but this is for the campaign only. In fact, a lot of the game is campaign only, the skirmish mode is extremely dull, with units largely being awkward or just not good. The combat and strategy is usually only decent with the rogue/spies, everything else was hardly even secondary.\n\nI wish the game had updates or something, it could have been much better, but ', 'Mostly Negative', 30.20, 35.75, 14.45);
INSERT INTO reviews VALUES (1046, 58560, 125, 'Banana!', 'Man, this game was so offensive on so many levels. Sexist, racist, ableist (the word ret*rded is actually used), and extensively mocking mental illness to boot. Pendulo: you''re alienating a large proportion of your audience. It''s lazy, cruel, unprofessional - and completely unnecessary. If you''re struggling to tell stories or make jokes that aren''t discriminatory, maybe it''s time to hire some new writers. A real shame, because some of the puzzles were genuinely engaging.', 'Very Positive', 88.00, 7.65, 8.32);
INSERT INTO reviews VALUES (1047, 58570, 273, 'Jugado y completado en 7 horas.\r\n\r\nLos gráficos de escenarios y personajes son muy atractivos y están muy bien animados. Las conversaciones son divertidas. Los puzzles, en general, no son complicados. La historia es ingeniosa y nada convencional, tal vez demasiado extraña, a mi me ha costado entrar. Si hay algo que no me ha gustado demasiado es la manera en que las distintas partes de la aventura se van presentando, recurren a un narrador para llevar la continuidad entre esas partes, y a mi me h', 'not for me. tried twice to play. not engaged first time and gave up after a few hours. second time tried harder. game was not bad, just not engaging for me, but i was determined to finish.\nbut.... for those like me with hearing issues, (relatively mild in my case) the music puzzle was not solvable......being so close to the end i was ticked off at having to give up so late in the game. why not include a skip option for those of us who dont have the ability to solve such puzzles?\nif your hearing ', 'Mostly Positive', 76.92, 7.32, 11.35);
INSERT INTO reviews VALUES (1048, 58610, 1344, 'recommended, i just developed my own strategy of using scout helies X attack helies to attack their command units at there spawn locations and render them crippled, then finish them off in cold blood like the animals they are.', 'I like playing single player and this is just too brutal a learning curve for me. Just a simple pause function would help without having to download a mod or cheat.', 'Mostly Positive', 75.89, 41.53, 25.92);
INSERT INTO reviews VALUES (1056, 61500, 568, 'Very old and enjoyable gameplay similar to Heroes of Might & Magic series. It has a lot of nostalgia elements today because of its simplicity on one side and complexity on the other. It has problems on modern computers to run, so you have to run it with compatibility mode and also apply unofficial fix, to prevent ingame crashes.', 'This shit is unplayable as it constantly crashes. the game is 11/10 but the crashes are infuriating, fk steam for selling this game in this state', 'Mostly Positive', 76.58, 363.27, 6.50);
INSERT INTO reviews VALUES (1057, 61510, 187, 'Age of Wonders II: The Wizard''s Throne is the sequel to Age of Wonders the epic fairytale classic.\r\nI owned the box edition along with Age of Wonders and Age of Wonders: Shadow Magic back in 2004, so it''s somewhat of a nostalgic title for me.\r\nTo get this to work on Window''s 10, I had to set compatibility to XP Service Pack 3, Disable Full-screen optimisations and Run this program as an administrator.\r\nAlso, for configuration i had to untick Allow Resolution Changes and Use Direct3D. However, th', 'Game is outdated and should not be bought to play it on modern systems since it crashes frequently.', 'Mostly Positive', 79.68, 94.97, 1.37);
INSERT INTO reviews VALUES (1058, 61520, 327, 'I think it''s the best game of AOW series.', 'Game is outdated and should not be bought to play it on modern systems since it crashes frequently.', 'Very Positive', 88.69, 94.72, 0.30);
INSERT INTO reviews VALUES (1059, 61600, 194, 'Zen Bound 2 has very simple mechanics, is relaxing, allows multiple solutions for each level, and is truly beautiful.', 'Ironically, this game is pretty stressful to me. I can feel my shoulders tensing up as I play it. I have come back to this game on-and-off for probably a year, and nope, it''s still not relaxing or particularly fun. While it is untimed and has pleasant sound and visuals, It doesn''t control well. Maneuvering the objects feels harder than it should be, and when the rope "sticks" to an object, it''s irritating to detach it. The gameplay just doesn''t flow well. I can see this being better with smoothe', 'Very Positive', 94.33, 6.77, 2.33);
INSERT INTO reviews VALUES (1060, 61730, 194, 'Fun game. Characters are cute and the animations are well done. Music and sound effects are also very well done. 10/10.', 'Does not work on Windows 10 or Windows 11. The developers seemed to have given up giving support. Do not purchase this game.', 'Very Positive', 93.81, 13.55, 3.93);
INSERT INTO reviews VALUES (1061, 62000, 345, 'fun for a short period of time and easy too get achievements.', 'https://youtu.be/r7WjhMGtLhw\n\nHonestly a very strong implementation of a ''plate spinning'' game, but despite that with nothing to chase but high scores players will have to be very dedicated to this title to find value.', 'Very Positive', 91.30, 4.97, 0.93);
INSERT INTO reviews VALUES (1062, 62100, 483, 'Want a to revel in the pure puzzling that the Tetris piece can deliver? Then check out this Cheapness affordable gaming review of Tricky Towers and Chime \r\n\r\nhttps://youtu.be/XN52F5foo1A\r\nQuick text review of Chime only:\r\nPart 2 - Chime was made by Zoe Mode and published by One Big Game. This cheap gaming review shows how:\r\n-It has nice, clean visuals with some flashing and mild changing background effects (If there isn''t much to see)\r\n-Great pure puzzler excellently repurposes the Tetris shapes', 'Unfortunately, Chime is a bit of jumble of conflictings idea.\n\nOn the one hand, it''s a relaxing ambiance with soft music and soft colors.\n\nOn the other hand, it''s a super fast paced gameplay\n\nTheses 2 sides can''t merge, and you end up with a frantic game where the music is just a total afterthought, you could definitely play it without music. As for the free mode, it''s just too void of content to really be an interesting, relaxing experience.', 'Overwhelmingly Positive', 95.03, 7.52, 4.28);
INSERT INTO reviews VALUES (1063, 63000, 419, 'I LOVE THIS GAME!!!!\nLove it since I was a kid on the ps3. PLEASE bring back local couch co-op, like everyone else agrees that is the best way to enjoy this game with friends. Thank you.', 'The screen tearing make this unplayable. It would be easily fixed by the devs but they no longer support this game, which is unfortunate.', 'Very Positive', 84.96, 0.70, 0.90);
INSERT INTO reviews VALUES (1065, 63200, 692, 'Valve''s Deadlock, but a dozen years earlier. Ahead of it''s time.', 'Dead by now, but It was incredible when it was released. One of the most fun online games of that year.', 'Very Positive', 81.50, 2.22, 53.18);
INSERT INTO reviews VALUES (1067, 63380, 2567, 'I wouldn''t of missed. \nJuly 14, 2024', 'When you start the game, you get an ad trying to sell you a jacket IRL.\r\nWhen you quit the game, you get to stare at an ad for other games the publisher has to offer for 30 sec.\r\nOn top of that, the gameplay itself is clunky and mediocre.\r\n\r\nThank you, but no thank you, I didn''t buy the game to get locked into ads.', 'Very Positive', 86.64, 13.27, 117.33);
INSERT INTO reviews VALUES (1068, 63500, 229, 'That''s was fun', 'Swords and Soldiers HD is another of these mobile-like games that''s made it onto PC and it''s immediately apparent when you play it that it was not created for any kind of sophisticated controller. Even this incredibly simple gameplay is in sore need of a keybinding or two.\n\n That being it''s not a terrible game. The simplicity does have some advantages and the cutesy humor helps you endure it.\n\n It is however, not a game I''d recommend anyone buy at anything remotely close to what they''re asking f', 'Very Positive', 89.96, 8.40, 45.73);
INSERT INTO reviews VALUES (1069, 63610, 968, 'If you are like me and have a fondness, or even a preference, for the old-style, ''slideshow'', point-and-click format for adventure games, you should absolutely pick up and play this one. It''s dirt cheap, it was updated in 2018 to run great on modern OS''s, and it''s the finest game of this type ever made. The sheer detail and work that went into it are clear to see, and make it a joy for me to go through even if the actual gameplay and puzzling is a bit too esoteric for me to get through without h', 'While the world building, story, exploration, and (most) puzzles were very good, I can''t recommend this. While the experience started out quite enjoyable, a few cryptic puzzles and let down the experience as the game went on. In particular, there was one "puzzle" involving finding a hidden button with no indication of its placement in order to  unlock the fish statue elevator , as well as finding a vent that was hidden only due to the restrictive camera in the room with  the frog bait trap . Add', 'Very Positive', 89.46, 11.98, 14.80);
INSERT INTO reviews VALUES (1073, 63650, 131, 'Culled from the various online attempts years ago, this is much less a game and more a lyrical and spiritual journey with puzzles, lonely and challenging vistas, and some of the most compelling soundtrack selections in games. The MMO lives on at mystonline.com, but there are many positives in playing this version first.', 'Wow, this is absolute garbage.  I''m sure the devoted fanbase loves it, but after finishing Myst 1-4 this is ... this is horrible. \n\nThe controls are the biggest negative.  Controlling your character is just a chore.  I dont understand why you cant strafe left and right while just walking/running.  The camera kept being problematic with constant rubberbanding whenever I try to look to the left or right quickly in first person.   I read the reviews, I decided I should stick with it till I at least', 'Mostly Positive', 76.34, 0.88, 0.33);
INSERT INTO reviews VALUES (1074, 63660, 716, 'click click click click click click click click click click click click click click click click click click click click click click click click click click click click click click click click click click click click click click click click click click click click click click click click click click click click click click click click click click click click click click click click click click click click click click click click click click click click click click click click', 'The navigation is too old and clunky.  Recommend Myst 2014 instead.', 'Very Positive', 86.87, 8.53, 25.33);
INSERT INTO reviews VALUES (1075, 63700, 497, 'wii motion controls will always be better than the fu**ing mouse', 'Waaay too simple and short for $10', 'Very Positive', 82.29, 1.63, 1.45);
INSERT INTO reviews VALUES (1076, 63710, 1140, 'he''s like a gay little wiener with legs', 'The complete lack of a checkpoint system makes this an extremely frustrating game. Skip this one and get the 2nd game in the series instead - BIT.TRIP Presents Runner2.', 'Very Positive', 85.35, 10.30, 1.85);
INSERT INTO reviews VALUES (1077, 63800, 222, 'Fun game, just wish the camera didn''t have to bounce around so much.', '"Sometimes a bad is just a bad game."\n\nTo the people who liked the game: If there had been a bit more polish, more time to make a better UI, make more creative assets, if this game just had a little bit more... HEART then maybe it really could have been a fun, turn-based, hex-grid board game. I wanted to like this game. It felt reminiscent of maybe some other hex-based strategy board games you already know and love and have multiple copies of stacked next to those old D&D books? Hello, am I talk', 'Mixed', 59.91, 25.58, 4.77);
INSERT INTO reviews VALUES (1079, 63910, 425, 'Can''t believe how good this game holds, to this day. I''m playing it on 4k monitor and the fact that a game made in 2010 even HAS a 4k graphics option is insane. Many of the current games perform worse, which just shows how much care went into making this title.\nI know it might not look very exciting to the new players, but to me it''s been a comfort game for many years. Highly recommend for cozy evenings of exploring.', 'Game is good, one of my favourite childhood classics But Polish Language doesn''t work despite advertised as containing such which is big let down as I wanted to experience the game same way I did as a child. Don''t buy if you look for Polish', 'Very Positive', 91.76, 347.02, 62.23);
INSERT INTO reviews VALUES (1080, 63940, 499, 'This is called Men of War: Vietnam because it is the equivalent of the torture methods used in that war.', 'Played 9/15 missions of the campaign, 6.5 of those were entirely about controlling 6 dudes through a jungle, where you have to stealth 80%+ since you''re outnumbered 10 to 1 with no reinforcements. Also, as someone who has only played this game and no other Men of War games, this is very obviously just Men of War with new guns and visuals, pretty sure all the icons are the same as well. No options for skirmish too.\n\nJust buy the original or Assault Squad instead of this unless you really want it,', 'Mixed', 57.31, 9.67, 30.22);
INSERT INTO reviews VALUES (1081, 63950, 360, 'Cliffs of Dover is an excellent World War 2 flight simulator, recreating what it is like to be a British or German combat pilot during the Summer of 1940. HOWEVER, it is excellent only if you use the Team Fusion patch. Let me make that clear. Cliffs of Dover should have been an excellent product from the first. Its vision and the designed scope of improvement over other WW2 flight sims was, and still is, truly next generation. However, the sim was a commercial flop - for a variety of reasons. \n\n', 'Wont start - I''ve hit play som many times and it never initiates', 'Mixed', 64.72, 415.18, 15.03);
INSERT INTO reviews VALUES (1083, 64000, 1851, 'Men of War Assault Squad is the best WW2 real-time tactics game! I''ve been following this game series ever since the original ''Soldiers Heroes of WW2''. When I tried the demo back then, and realized that you can take the shells out of your broken tank to load a stolen anti-tank gun, and you can scavenge the fallen bodies for weapons and ammunition, and you can take cover behind virtually everything, and you can drive tanks through buldings, I was immediately sold.\n\nThis amazing level of detail an', 'Why is it called Men of war and not woman of war smh', 'Very Positive', 88.82, 93.73, 0.73);
INSERT INTO reviews VALUES (1087, 65270, 198, 'Hidden gem of a game. The game is obviously dated at this point but its just a good fun game. You can take an entire building apart bit by bit with a sledge hammer or blow it up in one go and send debris across half the city.', 'I purchased this game because it had good reviews. The cold hard truth remains that this game is crap. So unrealistic and down right lame it truly is. The parts of the buildings you knock down instead of replicating cement is more like knocking down cardboard. Badly coded and poorly made. I wanted to blow up buildings my way, but this game forces you to place many explosives in a way that is fake and generic. A complete waste of money and time. Maybe a small child could enjoy this lame a-s-s gar', 'Very Positive', 86.36, 12.95, 3.92);
INSERT INTO reviews VALUES (1088, 65300, 1001, 'It''s criminal that this game doesn''t get more attention. I feel like I haven''t even scratched the surface in terms of skill at this game. The movement is some of the most satisfying I''ve played in any 2D platformer. It may feel a little awkward to get used to at first, but once you get it, it feels amazing. Learning each level until you can get SS rank is also super fun and satisfying. Each level is also only a minute or two long at most, which makes it super easy to restart a level if you mess ', 'The way character controls immediately turned me off the game. Way too floaty. You tap a directional button, the character runs a quarter of a screen, automatically hops over corners and obstacles when you don''t want it too, get magnetized to walls and ceilings when you don''t want to, just feels much worse to control than other platformers I played.', 'Very Positive', 94.11, 14.40, 0.98);
INSERT INTO reviews VALUES (1089, 65400, 126, 'This game is proof that rock- solid game design can outlast the passage of time. \nIt may have updated graphics yes but the design is still untouched- and even manages to show up a lot of modern games', 'Just bought the game.  Will not load.', 'Very Positive', 82.54, 0.98, 0.73);
INSERT INTO reviews VALUES (1092, 65540, 2478, 'In order to rid of jankiness, crashes and to increase graphical fidelity, use OpenGothic which offers Vulkan renderer on Linux, Metal renderer on macOS and Vulkan&DX12 renderer on Windows.\n\nhttps://github.com/Try/OpenGothic?tab=readme-ov-file#opengothic\n', 'I love series, I love old Gothic, thx for this to Piranha Bytes. \n\nNow, best part, after increasing price almost 2x, go F yourself THQ with your community manager who responded on the price increase ''you had 20 years to buy it''.', 'Very Positive', 83.94, 0.13, 0.35);
INSERT INTO reviews VALUES (1093, 65560, 223, 'Mindless close quarters slaughter. \nCould be fun for some.', 'Absolutely secondary and boring experience, absolutely no new features or additions. You can skip it.', 'Mixed', 42.15, 15.57, 0.30);
INSERT INTO reviews VALUES (1094, 65600, 244, 'Don''t listen bad votes. \r\nIt''s still on G3 engine running preety well wihout any addons on old lap.\r\nDon''t read bad votes if you''re real GOTHIC FAN, PLAY 1,2,3 ;)\r\n', 'Gothic 3 forsaken bugs', 'Mixed', 40.16, 39.70, 9.17);
INSERT INTO reviews VALUES (1095, 65610, 198, 'GOOD SOLID 5 TO 6 hours of fun, runs smoothly. old school RPG, catch on sale well worth a play.', 'This should be legally removed not just for being a horrible game, but stealing a story and running it into the dirt.  Exploration is limited to zones that open, a straight forward path, and the most you can really choose is what weapon class you want to max out.  Objects that you can collect have little glow bugs flying around them making it way too easy.  Also they ruined the story line of Gothic by mix matching characters from the old, that are not like them at all.  Lee would never work with', 'Mixed', 46.97, 11.48, 12.33);
INSERT INTO reviews VALUES (1096, 65730, 249, 'This is nice for a simulator. Scenery is better than expected. Learning to fly helos in the sim is a learning curve,\r\nnot like real life', 'Terrible performance on modern computers. Awful controls, awful gameplay with lags, crashes, and just general unhelpfulness. I tried the career mode to check the story and see if the game ever gives you the options to buy helicopters on your own as it promises but could never finish it because of terrible game design. Do not even think of buying this. Too late to refund for me.', 'Mixed', 59.84, 75.68, 38.12);
INSERT INTO reviews VALUES (1097, 65740, 496, 'Its a good game overall. The units are clumsy and seems to get stuck often.  It feels like FPS 80% and RTS 20%. In terms of game balance, if  you can find the right combo of equipment, the game becomes easy.  I only found MKII amour, plasma, gatling, and missiles are useful in battle, other weapons are mostly for decoration. The campaign mode is knda easy. For most missions, alI did I was to pick out all turrets defences with a manta and then send in the walrus after. Enemy carrier is not diffic', 'Terrible AI for both enemy and friendlies, mission objectives don''t activate properly and hitboxes for enemies is wonky, if it''s free sure but not worth paying ANY money to own, a pack of gum is a better buy.', 'Mixed', 47.98, 76.60, 11.85);
INSERT INTO reviews VALUES (1098, 65780, 394, 'I can''t afford ArmA 3\n\nEdit: I FINALLY BOUGHT ARMA 3!!!', 'The controls are fucking dogshit. You have to use the entire fucking keyboard just to walk. Fucking bitch ass garbage shit.', 'Mostly Positive', 75.89, 10.22, 2.92);
INSERT INTO reviews VALUES (1099, 65790, 958, 'Back when white people still made videogames', 'This game just shows its age way too much. \n\nThe AI can shoot you from beyond rendering distance. The character models of both factions look the same from anything greater than medium distance. AI that are attacking are extremely hesitant to shoot for some reason, which means any mission where you are attacking is borderline unplayable. \n\nAll of this makes it very hard to play it as a tactical shooter. It''s much easier to simply cheese the game, especially with long missions, which are further h', 'Very Positive', 89.87, 52.67, 93.63);
INSERT INTO reviews VALUES (1100, 65800, 8222, 'Great tower defense. But the Christmas level is a scam, to complete it you will need several characters of the maximum level, which will take a whole year to level up, given that the recommended level for completing it is 65. When I lost at this level it ruined my last Christmas and New Year.', 'Would be cool if you cared about more than selling the same game 3x. I get that this is the best version of the game, Thats only because you dropped the ball on the newer two. The control scheme, graphics and camera on this version are horrendous, or id just chalk the next two versions up as a loss. Stop punishing us for trying to support you and update and give DLCS to Awakened ffs. terrible devs', 'Very Positive', 92.91, 5.18, 4.85);
INSERT INTO reviews VALUES (1101, 65930, 2823, 'I know it''s largely forgotten amongest the XCOM fanbase but i dunno i still very much find it''s style of gameplay enjoyable and fun but i guess that''s largely because i enjoy having control over my actions instead of relying on rng.\n\nNot to say the other titles are bad for that, i''m just less interested in them because of that.\n\nEven if we don''t get another XCOM like it i''m hoping to find more games that take this games ideas and improve upon them.', 'Story is weak.\nSpoiler: Interrogation of an infiltrator is so pathetic, he changes opinion in 3 sentences from "Mosaic will crush you" to literally "omg you have freedom, my people want to have freedom from Mosaic too".\nSuch a disappointment.\n', 'Mixed', 64.01, 43.58, 13.60);
INSERT INTO reviews VALUES (1102, 65980, 9811, 'I remember waiting for this game to release all the way back in 2014. While the initial release of the game did feel incomplete, the added expansions make the game a lot better. I personally was disappointed by CIV VI and felt that perhaps we judged Beyond Earth a little too harshly. \r\n\r\nI personally love the non-linear tech tree, the nuanced approach to alien life, aquatic cities, the music, the atmosphere, the artwork, and the general premise of the game. \r\n\r\nIf you were a huge fan of Civ V an', 'No longer playable: starting a game, even without mods, will immediately crash with an access violation exception, and none of the solutions found online helped me', 'Mixed', 57.61, 140.55, 25.62);
INSERT INTO reviews VALUES (1103, 67000, 358, 'This is a brilliant music-based game. Beautiful artwork interspersed with game-play you can choose intensity level on. My favorite is listening to some very chill electronic music and fly around while I trip on my substance of choice. Very recommend much amazing!', 'It''s interesting to play audio music and see how the world around you reacts with lights and even shooting ships and other things down but I got tired of it quickly because I had played the other one a lot which was the driving one.', 'Mostly Positive', 74.02, 11.55, 0.28);
INSERT INTO reviews VALUES (1104, 67370, 3316, 'For the game released 13 years ago this is banger. WHATDAYA WANNA SEE IS HERE, MONKEY! Stylization like comics is really good, feels like Dishonored or Wolf Among Us but even better. Hub locations make u feel like real mob boss, literally Scarface. Story is craaazy good, but it ends in a cliffhanger and we dont have the darkness 3 obviously so u need to go read comics after playin. Game is niether short nor long, it''s perfecto - 7 hours to complete campain plus there''s some extra missions. Der w', 'game looks like trash.First game was actually good.', 'Very Positive', 89.45, 8.15, 0.42);
INSERT INTO reviews VALUES (1105, 70000, 4623, 'I am the 14-year-old son, probably one of the youngest players of this game. I’m a single son to my 45-year-old father. I got this game for Christmas in 2023 from my uncle, so we installed it on my computer, and by the end of the week, he had 24 hours on it. This was hard for him, as it was already tough to find time with him since I was always out with friends or watching YouTube. So, he created a Steam account, got the game, and tried to play alongside me. He was stuck, so I hosted a game for ', 'Not Recommended', 'Very Positive', 87.97, 1.67, 4.00);
INSERT INTO reviews VALUES (1106, 70100, 262, 'I have no idea what I''m doing, oops and I''m in.', 'aguagauugaugugauuaagugaugauagugauauaaaaaa', 'Mixed', 69.47, 10.27, 1.63);
INSERT INTO reviews VALUES (1108, 70120, 130, 'Someone please get me out of jail for hacking the government servers.', 'omfg bad', 'Mostly Negative', 25.38, 0.90, 0.10);
INSERT INTO reviews VALUES (1109, 70300, 4304, 'Don''t be fooled by my short playtime on Steam, I have another 80 hours on 3DS. This isn''t even that long of a game, probably only about 5-10 hours. However it''s incredibly fun and leaves you wanting more after beating it, which it gives you! The level editor and player levels add hours of fun on top of this already brilliant game, and better yet, all of the hand picked custom levels are brilliant! (Quite rare for user made content to be this good in any game!)', 'I think this is a neat idea, but I had zero fun while playing this game. I want to play games to have fun.', 'Overwhelmingly Positive', 96.82, 16.50, 3.23);
INSERT INTO reviews VALUES (1110, 70400, 5352, 'the best game of all time, unable to be recreated, egyptian pyramid levels of alien technology were granted to the devs and then revoked upon this masterpiece''s completion.\r\nonly excuse for nothing resembling this game being released in the last 10 years', 'Fun for like an hour then predictable and boring. If you want to play a merchant and actually have fun, play "Moonlighter" instead.', 'Overwhelmingly Positive', 96.21, 13.58, 3.38);
INSERT INTO reviews VALUES (1111, 70420, 470, 'A hidden gem. Fun to speedrun too even if you''ve never done it before!', 'i played this because it''s the prequel to recettear, but i just can''t bring myself to finish it. there''s not much to it, you slash and you cast magic, marvelous.', 'Mostly Positive', 75.32, 580.22, 4.60);
INSERT INTO reviews VALUES (1113, 70600, 1526, 'Best worms game there ever was! Team17 are stupid for sticking to 2D!', 'This is one of my most beloved games from childhood, and i''m sad to see that this release is so bad. It has mouse shaking/stutter problem (this resolved it for me - https://github.com/ermaccer/Worms4UHD.MouseFix) and delay in multiplayer is really bad. The player whose turn it is makes their move, and the rest will see those actions 4-5 seconds later. I guess this isn''t that bad if you play with randoms (which you won''t find) but if you play with friends on Discord it really ruins the experience', 'Very Positive', 86.76, 84.95, 3.32);
INSERT INTO reviews VALUES (1114, 70620, 237, 'to me, worms crazy golf is like a normal worms golf game\n', 'im gonna punch these worms...', 'Very Positive', 84.81, 0.32, 2.58);
INSERT INTO reviews VALUES (1115, 70640, 263, 'Look, we all know Worms and how good it is. Im not gonna lie, I wont be playing it again when theres better versions out there like Worms Armaggedon, but this is gaming history, so you and I need to have on our libraries. Runs flawlessly on DOSBox on modern systems.', 'Works fine on Win10 for me, but really shows its age. The mouse feels laggy, the controls are stiff, the AI lands almost very shot, and the field of view is tiny. It was great at the time, but it''s too hard to go back to now.\n\nA great bit of nostalgia, but better remembered with rose-tinted glasses.', 'Very Positive', 84.41, 0.37, 0.25);
INSERT INTO reviews VALUES (1117, 70900, 233, 'They do not make games like this anymore. Deep as an ocean.', 'Two thumbs down on this one. The UI is nearly impenetreable and there is no tutorial at all. It just throws you in and assumes you''ll be able to figure things out. The diplomacy system makes no sense and 9 times out of 10 you won''t even be aware people are trying to give you "diplomatic missions" until you get the alert that your time is up. The system for setting up trade routes and supply runs to even out resources in your empire is so convoluted that even after a *long* time trying to figure ', 'Very Positive', 85.84, 120.52, 7.80);
INSERT INTO reviews VALUES (1118, 71000, 342, 'This is a great game, for as far as it goes.\nUnfortunately compared to other Space sims, there''s just not a lot of ongoing content here. Somewhere around the 25-30 hour mark, maybe sooner, you''ll simply run out of things to do.\nIf you can get this for 80-90% off, for a couple of bucks, then I''d recommend it.\nFull price? No.', 'the devs seem to love making the same exact game over and over and charging more for the exact same thing\nanyways abandonware', 'Mostly Positive', 75.44, 38.02, 10.57);
INSERT INTO reviews VALUES (1119, 71250, 9323, 'stage called casinopolis\r\nspent 14 minutes playing sonic pinball because thats the point of the level\r\nyou got a emerald for it\r\neggman takes the emerald at the end of the level\r\n10/10 game', 'Great game, awful port. Downgraded graphics, letterboxed to 4:3, launcher that hasn’t been touched since 2004, and bugs compared to the original 1998 releases.\nIf you use the SADX Mod Installer (https://sadxmodinstaller.unreliable.network/) it can become the best version of the game.\nRecommended but only if you’re willing to install mods, otherwise stay away.', 'Very Positive', 92.70, 5.45, 93.18);
INSERT INTO reviews VALUES (1120, 71340, 12410, 'Y''all better not delist this\n\nEdit: They will not be delisting this fully and instead include this game with bundles, however, you will now have to pay double the price for this game which is  still pretty scummy in my opinion, but this also means that the modding community is safe! Ggs bois.', 'You see this negative review and you wonder what I don''t like about it. That''s the thing. It''s great. But SEGA went and added this game as part of Sonic X Shadow Generations. So if you get that Sonic X Shadow Generations game instead, you get this game AND a second campaign starring Shadow the Hedgehog. \nSo I do recommend Sonic Generations, just not this version of it.', 'Very Positive', 93.93, 88.90, 16.10);
INSERT INTO reviews VALUES (1121, 72000, 266, 'Extremely underrated', 'Rating:3/10\r\nCompletion difficulty:3/10\r\nI respect the devs a lot for patching the game this year after so long so it can work on newer machines. However, I did not enjoy playing the game much. The art style and concept are unique, but the puzzles are  slow to solve and very fiddly. Important stuff can break easily, forcing you to restart, or you may have to fiddle with a light setup to make things work. I''d only play it if you''re a big fan of unique puzzles.', 'Very Positive', 83.46, 3.78, 11.77);
INSERT INTO reviews VALUES (1123, 72850, 101732, 'Spent more time modding and playing this game than I did going to school.\nI think when I die scenes of skyrim will flash before my eyes and I will be at peace\n10/10\nvirtually unplayable without mods', 'The game is obviously amazing, one of the last "great games", but scummy bethesda removed all dlc from the store for the vanilla version to force players to buy the "special edition".', 'Very Positive', 92.54, 421.38, 359.98);
INSERT INTO reviews VALUES (1124, 72900, 116, 'This is going to be a hard one to review. This is not my type of game. I played it for about 2 hours before I gave up.\n\nIt''s a game similar to Final Fantasy Tactics, with more narrative and less combat. The setting is interesting, and the way the delivery is handled is very good.\n\nThe artwork is decent. The writing is amazing. But the game is slow-paced and there''s a lot of minor things that doesn''t grab me. I definitely recommend the game to someone who enjoys adventure games with light combat.', 'The gameplay seems pretty decent (and the battle mechanics particularly interesting), but after thirty minutes or so I''ve had to set this game aside (at least for the moment) because I simply can''t take any more of the purple prose, especially given how often it descends into complete doggerel in what is presumably an attempt to sound "poetic." This isn''t even remotely funny-bad, as Bulwer-Lytton contest entries, but simply painful-bad, the hail-like slew of obstreperous adjectives hurtling down', 'Mixed', 64.66, 2.75, 0.75);
INSERT INTO reviews VALUES (1125, 73010, 355, 'When it came out it was a very nice niche game but with today standards it cant compare because you really dont have much to do and only buying busses, etc. and creating a network for transportation. You can do the same in cities skylines and also many more.', 'Paradox is a terrible company supporting woke culture and expensive DLC.  Forums are full of woke moderators and if you say anything against the woke narrative, you''ll cop a ban.', 'Mostly Positive', 71.55, 27.85, 77.53);
INSERT INTO reviews VALUES (1126, 73020, 616, 'Fun game, wish we had more games like this. I recommend this game.\n\nHowever keep in mind this game as an issue with FPS/Refresh Rate which can be fixed, Google search "PSA: Game-breaking building speed bug; build speed tied to in-game FPS, more fps = longer build times".', 'Normally I am not one to complain when a game is too hard but some of the missions are close to impossible. There are some missions where you can place a structure (guild or guard tower, it doesn''t matter) the instant the game starts and you don''t even make it 1/2 of the way through construction before you get swarmed and the structure is destroyed. This is supposed to be a RTS, right? There is no strategy in that. When you have to reload and hope that your castle gets attacked (higher HP) so yo', 'Mostly Positive', 71.43, 89.47, 95.73);
INSERT INTO reviews VALUES (1128, 73170, 896, 'better than hoi4', 'A lot of the reviews seem to be based on nostalgia. The UI and Combat are atrocious, there is little to do other than build factories and armies. There is no flavor. War is tedious and slow. The logistics aspect is overly simple. For two dollars, might as well get it. But don''t expect it to be fun if you''re used to something like Hearts of Iron 4 or Eu4.', 'Very Positive', 91.41, 76.28, 8.93);
INSERT INTO reviews VALUES (1130, 73210, 229, 'Left over from the making of CK2 set in Japan.\nBroken, filled with holes, completely aggravating, damned near unplayable. and so much fun. I really do enjoy this game\nBuy it on discount and get sucked in, and whatever you do don''t compare it to Crusader Kings 2, your asking to be disappointed.\nSoundtrack is real good too.', 'Paradox being paradox', 'Mixed', 62.45, 37.18, 1.60);
INSERT INTO reviews VALUES (1131, 73230, 602, 'Timless game\r\n', 'I wrote a detailed review as to why I wouldn''t recommend this game, which included constructive criticism and very specific details. I even turned on comments. Got a message that there was something wrong with my review. Feel free to guess why I wouldn''t recommend this game to other players. \r\n\r\nDon''t buy this game. I''m also starting to get annoyed with Steam, since I lost a long and well written review.\r\n\r\nSince a description is required to post a review, I''ll describe it as follows: An older R', 'Overwhelmingly Positive', 98.84, 167.23, 217.07);
INSERT INTO reviews VALUES (1132, 78000, 3397, 'My grandma walked in on me playing this game and said "Is this like that Candy Crush game I play a lot?", before laughing uncontrollably. Except that did not happen, she''s dead. I miss you grandma. Great game!', 'do not buy this game or even install it it broke my pc and is malware', 'Overwhelmingly Positive', 95.58, 26.23, 1.00);
INSERT INTO reviews VALUES (1134, 80200, 345, 'It''s a very satisfying and challenging game to play, nothing out there quite like it. Couple of downsides are that you need an unofficial patch to fix a late game solution (which the game is "unwinnable" without) and some actions don''t make sense (Japan got stuck in a permanent economic super depression, nothing fixed it), but aside from those it''s pretty good for the price and being an almost 14 year old game', 'Complex game that is not offer sufficient explination on its concepts.\r\nUI does not help me.\r\nSound design is like a blade in my ears.\r\n\r\nThe fate of this game is the recycling bin.', 'Mostly Positive', 78.84, 33.63, 34.18);
INSERT INTO reviews VALUES (1136, 80310, 889, 'It''s good, but not as great as I thought it would be. This is an earlier Wadjet Eye game and they''ve come a long way since then. I loved Unavowed. It absolutely deserves all the praise its received. This game is considered among their best. Having finally played it and just finished it, I could see it being great at the time, but superior efforts make it feel a bit amateurish for lack of a better term. The voice acting is decent. Delta Six''s voice actor sounded so wooden for the entire game. The', 'I have come back to this game twice trying to give it a fair try. I like the setting and the story is interesting, I have played and enjoyed other Wadjet Eye games (Techno Babylon) so I expected similar quality with this one. This is an earlier game (The first?) put out by Wadjet though and it kinda does seem a bit rough, The voice acting is one of the biggest complaints in that regard.\r\n\r\nI ended up deciding this was not worth continuing because the awkward gun-fighting parts seemed to be a big', 'Very Positive', 86.28, 8.53, 3.30);
INSERT INTO reviews VALUES (1137, 80330, 920, 'I accidentally reviewed the wrong Blackwell like a doofus, so here''s my review on the whole series: https://steamcommunity.com/id/magerama/recommended/80360/\nThese games could use an additional bump anyway (and them bloody numbers). Since I''m here, gotta say the first game isn''t entirely representative, they only get bigger and better. Doesn''t mean you should skip it, still a great adventure. But expect improvements, don''t drop the series if Legacy didn''t do it for you. I promise you''ll get back', 'This game was so frustrating. The characters were unlikeable, the plot was illogical, and it''s very short, with an abrupt and unsatisfying ending. The puzzles were completely insane logic, like, sure, I''ll just go back to the psychiatric hospital to steal some diuretic pills so that I can drug my neighbor''s dog into needing to pee so I can take it to a ghost girl who likes dogs, because that will convince the ghost girl that she''s dead. Obviously. Who wouldn''t think "now where can I steal some d', 'Very Positive', 88.15, 3.42, 2.35);
INSERT INTO reviews VALUES (1138, 80340, 415, 'https://steamcommunity.com/sharedfiles/filedetails/?id=2547577107', 'Im sad to say that this game absolutely killed the franchise for me! The first one was a struggle but this one is like a trip to the toilet! Evertything in this game is such a bore!', 'Very Positive', 93.73, 4.93, 2.93);
INSERT INTO reviews VALUES (1139, 80350, 351, 'https://steamcommunity.com/sharedfiles/filedetails/?id=2559008604', 'The tightest gameplay of all Blackwell episodes up to this point-- yet the most fractured storyline. Enjoyed the first half, said "WAT?" aloud to myself repeatedly during the second half. A shame, because I was looking forward to finally recommending one of these... but I still just can''t. Like the other episodes I''ve played in this series, "good idea, poor execution."', 'Overwhelmingly Positive', 95.73, 5.00, 1.18);
INSERT INTO reviews VALUES (1140, 80360, 359, 'I accidentally reviewed the wrong Blackwell, meant to write this under the first one, Legacy. But whatever, all of them are great anyway. This one has less reviews, so maybe it''s for the best!\nI''m quite an elitist when it comes to point & clicks, but I think that even in the 90''s when there was plenty of competition the series would stand out. I''m even inclined to claim that Blackwell would be considered a classic by now. Because it has it all: charismatic characters with believable motivations,', 'Forth, longest, worst.  That''s sums it up.  Like the other Blackwell games, it leaves things open for yet another sequal.  If you play all four games back to back, they get close to the length you''d expect  a single game to be.  Deception, despite not being a departure in any respect from the others, "feels" like worse game.', 'Overwhelmingly Positive', 96.66, 5.68, 3.77);
INSERT INTO reviews VALUES (1141, 90200, 297, '2013, 15, 17, 19, and 22 are all only about twice the price of this and all big improvements, so get any of those instead even if you''re on a tight budget. 2013 was where the game started to feel complete, but each number up comes with a big jump in quality of life features.\nBuy a newer version, but this was a really fun game in it''s time.', 'I spent more time climbing a 3D mountain made in sketchup than playing anything, I loved it', 'Very Positive', 84.85, 101.45, 1.33);
INSERT INTO reviews VALUES (1144, 91100, 397, 'It''s like Blur, but mid air. It''s a great neat game, flight controls are arcadey but responsive. blasting rival to smithereens is very satisfying.', 'Sound: 6\nGraphics: 7\nStory: 3\nGameplay: 4\nCommands: 5\nFun: 5\nTime to load / lag: 9\nBugs / Problems: 8\nFinal score: 5', 'Very Positive', 89.17, 0.30, 0.58);
INSERT INTO reviews VALUES (1145, 91200, 542, 'Anomaly: Warzone Earth\n\nHas a total of 6 trading cards.', 'This is a boring and poorly made game.\nThe game is an escort and a puzzle in one, but poorly designed. It looks like a mobile game.\nIf the little man wasn''t there and you were using the skills without him, it would be better.\nBad balance and bugs. Almost no development or upgrades.\nQuite a boring game.', 'Very Positive', 82.29, 1.22, 6.10);
INSERT INTO reviews VALUES (1146, 91330, 368, 'always will have great memories of this game', 'Bug, bug aaaaaand BUG!!!!', 'Mixed', 59.78, 30.33, 16.73);
INSERT INTO reviews VALUES (1147, 91600, 1318, 'Some pretty weird decisions makes this a somewhat unique tower defense game, for better or for worse. In most cases, for worse.\n\nFor instance, there are levels with up to 30 waves. Although there are checkpoints every few waves, this is one of those FPS/TD hybrids, so you can''t just build your maze and afk, because the game expects you to do the heavy lifting with your weapons; meaning, you''ll have to babysit them by being the main source of DPS, even at higher upgrade levels. This is compounded', 'Core gameplay is nice.\n\nBut UX has issues.\nFor example: You cannot build towers in tactical view, as far as i can tell, even though that''s where it makes most sense. Why does it not automaticalyl build a tower base, but require you to explicitly build 2 objects?\nSome weapon, tower, level descriptsions are lacking in detail making it hard to plan. E.g you have to choose available towers before a level, but lack information to make informed decisions without trial and error.\n\nAnd audio is broken i', 'Very Positive', 90.97, 25.57, 1.30);
INSERT INTO reviews VALUES (1148, 91700, 4758, 'The roughest gem out there. This game crashed once and now it refuses to start up again and I swear it changed my pc''s resolution or UI size permanently and nothing can fix it. 10/10', 'i respect this game for what it is, but it is not for me. i am too old to have the patience for it anymore. when it came out, if i had played it i would have been in heaven.', 'Very Positive', 85.50, 23.08, 0.52);
INSERT INTO reviews VALUES (1149, 91800, 101, 'I remember playing the demo of Cloning Clyde on my dad''s old XBOX 360 when I was just a little homonculous.', 'I first bought Cloning Clyde on XBLA after playing the trial. I saw that it was on Steam, and decided I''d buy it to not only support the devs, but also because I enjoyed it as a platformer/puzzle type game.\n\nI like this game. I really do. I know it says I don''t recommend it despite liking it, but here''s why; there''s NO replayability. It''s one of those games where after you beat the game and the ten challenge levels (which are a joke), there''s NOTHING else to do besides playing the levels over ag', 'Very Positive', 90.10, 4.58, 5.60);
INSERT INTO reviews VALUES (1151, 91900, 315, 'Fun arcade racing game with mayhem, variety and fast bug-free destruction', 'came with the video card 10 some odd years ago. was fun-ish. tried to go back and play it now and it locks up my whole machine. not worth my time and energy debugging if the devs wont keep it up to date.', 'Very Positive', 83.81, 3.33, 4.47);
INSERT INTO reviews VALUES (1152, 92000, 1251, 'What do you mean you don''t get the water powers until the last 15 minutes.', 'I really wanted to like this game. The unique setting, a likeable protagonist and really impressive water physics are the positives, but the combat is unsatisfying, the story has lots of unexplained things and seems unfinished and bugs and crashes rear their ugly head at the worst moments.\r\n\r\nThe special "water bending" power could shake things up, but are unlocked too late in the game and you can only use it to fight some grunts and the (annoying) final boss; after that the game simply ends and', 'Mixed', 61.07, 8.18, 5.53);
INSERT INTO reviews VALUES (1153, 92100, 435, 'DETOUR\n\nHas a total of 5 trading cards.', 'Detour falls short with its overly simplistic graphics and shallow gameplay that quickly feels repetitive. While the concept of routing trucks past obstacles has potential, the limited mechanics and lack of depth make it hard to stay engaged. Overall, it’s a strategy game that misses the mark.\n\nRating: ★★☆☆☆ (2/5)', 'Mixed', 48.05, 0.35, 2.37);
INSERT INTO reviews VALUES (1157, 92300, 370, 'not bad', 'The game is okay for a quick playthrough, but if you want to go for achievements i can''t recommend it. Controlls felt aweful.\nBosses are too random with their patterns. No retry- button. You can''t skip the boss entrance scene. It was too annoying for me to finish the achievements.', 'Mostly Positive', 71.89, 0.18, 7.32);
INSERT INTO reviews VALUES (1161, 92800, 1859, 'I have no idea what you are even supposed to do \nBut the Fishcake is nice!', 'im too dumb for this game', 'Overwhelmingly Positive', 95.75, 0.25, 0.22);
INSERT INTO reviews VALUES (1163, 93200, 443, 'Ah, Revenge of the Titans. Probably one of the first games I ever bought on Steam over a decade ago, returning to this game was nostalgic. This is a surprisingly good tower defense game that packs a bunch of pixelated charm and a banger soundtrack. There''s a decent amount of challenge too, with multiple levels requiring clever turret placement and retries as the Titans adjust to your setups. Looking up a guide can alleviate a lot of the rising difficulty towards the end, if you''re feeling stuck.', 'This would be very enjoyable, were it not for the insane difficulty. I don''t mind a hard game - I''ve played all the Souls - but this is just not fun.\n\nThe first couple of missions are nice, the style''s great and the sound effects fit extremely well, but ultimately, it''s just impossible.', 'Very Positive', 80.59, 49.23, 8.83);
INSERT INTO reviews VALUES (1164, 94000, 387, 'Best Game EVAR', 'Dinner Date is an experimental game, pushing at the edges of what a game can be. You play as Julian Luxemburg, a 27 year old British man who has been set up on a date with a 20 year old Japanese woman named Meiko. As the evening wears on, it becomes clear that Meiko will not be arriving for that date, leaving Julian alone with his thoughts. \n\nThis is not a game with gameplay in the traditional sense. While the player can move Julian’s arms through a series of keyboard inputs and decide how much ', 'Mixed', 51.42, 0.65, 0.33);
INSERT INTO reviews VALUES (1165, 94200, 497, 'Avoid this game', 'got this game back in 2011, decided to play it on my Deck and just crashes to desktop. Apparently the issue has been around for a while now and the devs have a plus version out and did not bother to fix this vesion.\n', 'Very Positive', 94.37, 148.55, 14.93);
INSERT INTO reviews VALUES (1166, 94300, 1033, 'Well, as a person from The Neverhood... era, every now and then I have a need in experiencing some clay, fingerprints, close-ups  etc.\nGood game, deep\nI guess... now I want to become a father', 'You have to play all chapters together to get the ''full game'' (each is very short on their own) but if you insist on getting this game I strongly recommend you only buy ONE chapter first, to test out its performance and ensure you will find it playable. I bought all chapters together and regret it, the game is beautiful and I want to love it but it was an extremely frustrating experience, massive lag and fps drops, frequent crashes to desktop. Likely due to a combination of being made in flash a', 'Very Positive', 89.84, 35.85, 15.48);
INSERT INTO reviews VALUES (1167, 94400, 3985, 'Probably one of the greatest modern couch VS games ever conceived. A must have classic even if you plan to play alone. This is one of the best arcade experiences you''ll have. Period.', 'A game that is as wide as a puddle and equally deep. There is a fair argument to be made for the value of the game in terms of a sit-down with your friends on the couch type of game, but even in that framework I find this game to be less than tepid. A $10 pricetag for a game that has less quality and content than a flash game of yore. I would argue this game would only be worth it if it is free. The game is relatively fun, but there is zero depth.', 'Very Positive', 91.04, 3.53, 0.08);
INSERT INTO reviews VALUES (1172, 94590, 393, 'Dale Cooper from Twin Peaks if he was the main character in Professor Layton''s Fargo/Gravity Falls crossover.', 'Unfortunately fails to improve on the first game and even regresses in parts. Conclusion to the story is absolutely nonsensical, puzzle variety is poor despite short length, difficulty is flat and on the easy side (without any harder optional puzzles), rules are not precisely written and can be confusing. It''s amazing visually and has a great mysterious vibe, but that''s it.', 'Very Positive', 86.26, 4.90, 4.50);
INSERT INTO reviews VALUES (1176, 95300, 390, 'Classic game, so relaxing.  A great little game to decompress after work. A quiet little meditation.', 'Capsized provides a fun alien world to plow through, but the tools provided to the player could feel a lot better.\n\nBiggest positives:\n+ Diverse environment filled with an interesting mix of tribal aesthetics, alien fauna, and ancient technology\n+ Variation in objectives between levels adds some interest to the combat\n\nOther notes:\n-- Many awkward interactions with the environment; the character is constantly getting caught or stuck on things.\n-- Certain frustrating segments may be enough to mak', 'Very Positive', 82.56, 95.43, 3.33);
INSERT INTO reviews VALUES (1177, 95400, 1196, 'I''m writing this review more for the memory, I had played this with a girl I loved deeply and though co-op puzzle games always frustrated me, this one absolutely being no exception, I spent a good few hours on a pleasant evening working with her to endure that frustration and enjoy something she grew up on. I can''t realistically speak for the game in its entirety, I never completed it, but that evening will always be in my mind for a good many years more and my strongest praise for this game com', 'One of the most mechanically difficult games I''ve ever played. If you have a friend you''re trying to get rid of, play this game with them.', 'Very Positive', 91.39, 3.92, 8.10);
INSERT INTO reviews VALUES (1179, 95900, 148, 'childhood game', 'A long slog through war as a bumbling French merc attempting to find out the truth about her father.  Gameplay is extremely repatative, though there are a couple stealth missions to break up the dry combat missions.  Your wingman AI is completely useless and you can offer them no orders.   Ultimately you get to make a decision at the end of the game which was actually rather interesting to get too, but the amount of gameplay was almost too much to bear.', 'Mostly Positive', 73.65, 10.57, 6.25);
INSERT INTO reviews VALUES (1180, 96000, 1587, 'https://steamcommunity.com/sharedfiles/filedetails/?id=1522522537', 'The minigames were too long and annoying. Combined with no alternate gamestyle or skip function, I just exited the game as I didn''t think the mild entertainment if I powered through was worth the time investment.', 'Very Positive', 86.96, 7.72, 4.17);
INSERT INTO reviews VALUES (1181, 96100, 2654, '‎', 'The game starts off pretty good, but then it gets annoying, especially when gravity fails and you fly past the created gravity field over and over again.', 'Very Positive', 84.02, 199.92, 0.85);
INSERT INTO reviews VALUES (1183, 96800, 147, 'Fast paced quake-style game with interesting elements.\n\nCry engine 3. Gorgeus graphics. Great soundtrack. Fluid. Competitive. Varied power-ups. Potential.\n', 'As a fan of Unreal Tournament and Arena Shooters in general, Nexuiz was a game I had high hopes for. Comparing it to Unreal Tournament may not be fair but obviously it never got to that level and the few players stopped playing.\n\nNowadays I''m pretty sure you can''t play online and trying to play against  bots also crashed the game. Even though I do not think anyone would  buy this game, Nexuiz still should be delisted.\n\n', 'Mixed', 55.10, 1.95, 0.30);
INSERT INTO reviews VALUES (1185, 97000, 1101, 'The story of how a tiny guy gain weight, and becomes the largest hole in the entire Universe.\nbodybuilders will appreciate 👍\n10/10', 'Not much here. \n\nThe premise of playing as astronomical objects is neat, but the execution is poor. The missions are all the same, the physics are unrealistic, and there''s really not much to do. It''s worth buying on sale for the novel premise, but it probably won''t hold your interest for more than a couple hours.\n\nView my other reviews here', 'Very Positive', 91.10, 20.38, 9.62);
INSERT INTO reviews VALUES (1188, 97130, 147, 'Kohan needs modern sequels with rpg elements', 'the AI doesnt allow you to build up an army. makes the game not fun if you cant win', 'Very Positive', 90.48, 10.33, 5.42);
INSERT INTO reviews VALUES (1189, 98100, 171, 'Still unsure what happened', 'It''s an art piece that took 20 minutes to see everything, with all the gameplay of a Powerpoint presentaton and almost the exact same screen transitions.', 'Mostly Positive', 71.93, 1.53, 0.33);
INSERT INTO reviews VALUES (1190, 98200, 875, 'Awesome game, created the entire genre that is now popularized by titles like Breach & Clear, Breach & Clear: Deadline, and No Plan B.  Excellent, strategic gameplay, an incredible amount of ways for each level to play out, a high skill ceiling, you can be as intricate, well thought out, and professional as you want to be here, as you''re given every action and tool  you need to lay out your best plans, check your corners, and take the shots. \r\n\r\nHighly recommended, even after all this time.', 'I respect a pioneer, but honestly it doesn''t hold up. Many modern games do this kind of gameplay better.', 'Very Positive', 89.83, 9.08, 4.75);
INSERT INTO reviews VALUES (1191, 98300, 840, 'So the game still works in 2024 to play open the game files and run gamesw it will allow you to play it still amazing game 100% worth the play.', 'Doesn''t launch on Windows 11 because of GFWL shitware being required.\n\nIf anyone knows a fix, letting me know would be much appreciated.\n\nEDIT: Actually, it may be due to having a high CPU core count, if anyone wants to investigate.', 'Very Positive', 89.29, 12.83, 34.25);
INSERT INTO reviews VALUES (1192, 98400, 1815, 'A flawed shooter with great non-stop action, made by a talented team that''s still finding their footing. Beautiful to look at, but suffers from a lot of visual clutter during combat making it hard to make out what you''re seeing. Writing is absolutely horrendous, which renders the comic story scenes between levels useless.\r\n\r\nThe game is hard. You will die on normal if you''re careless or don''t utilize your weapons properly.', 'Maybe too fast paced for my taste, it really requires fast reflexes and me at my 50''s I don''t really do that anymore.\nIts pretty and has decent sound design. The aiming is wonky, jumping is odd, overall it feels like a meh, experience. There are all sort of upgrades in the game but I am not even sure if I have used any of them?\n\nI mean its ok. But not something i would recommend at least in 2024', 'Very Positive', 81.98, 6.92, 6.27);
INSERT INTO reviews VALUES (1194, 98600, 183, 'Small puzzle like game, saw a demo of it and looked interesting, however not the best thing really so if you like a casual game with some challeges then this is the game for you.', 'Pass unless you''ve completely run out of indie puzzles\r\nI remember enjoying this game 10 years ago, but it didn''t age too well. Very little content for the price, no replay value. 2-3h to 100% the base game, same for the DLC. Cloying soundtrack.', 'Mostly Positive', 78.69, 1.58, 7.42);
INSERT INTO reviews VALUES (1195, 98800, 3128, 'Short Answer: Look at my playtime, that''s real, loved every moment.\r\n\r\nLong Answer: Over a decade after its release I''ve found nothing quite like it. It''s what I''d call an "Open Book" roguelike. Instead of relying on keeping key information from you, it makes everything you need to know available to you and then just pits you against brutally unfair odds and you figure out how to be even more unfair in response. Even on the hardest difficulty mode vanilla you can stack the nonsense higher and wi', 'got to selection screen picked my stuff no start button.  Tried EVERYTHING I can think of,', 'Very Positive', 94.25, 1724.77, 0.22);
INSERT INTO reviews VALUES (1197, 99100, 201, 'Played through the game coop and yes it''s unpolished and there is a ton of jank but we had a blast and I''m looking forward to going through it again.', 'This game is boring, bad and broken. Not worth the price or effort.', 'Mostly Negative', 30.85, 8.75, 6.75);
INSERT INTO reviews VALUES (1199, 99300, 510, 'Renegade Ops is probably the most fun I''ve had in a twin stick shooter.\r\nYou have 7 characters in total and it took me almost 10 hours to complete the game using only one character.\r\nThat being said...it would take me 70 hours to finish with all 7....i think.\r\nNevermind the fact that one of the characters is Gordon Freeman from Half-Life...i thought that was so cool.\r\nThe game is great and cheap so it''s definitely worth a try.\r\n', 'I really wanted to like this game after discovering it but I just can''t. You just have little means of preventing yourself from getting hit because your vehicles are very sluggish and the levels have very little space to maneuver in, the game reflects this by spawning copious amounts of health pickups making combat a game of randomness.\n', 'Very Positive', 85.69, 9.63, 2.95);
INSERT INTO reviews VALUES (1200, 99400, 151, 'This is the Dollar Tree version of God of War', 'It''s a pretty poor copy of ps2 era God of War, but that''s what attracted me to it in the first place. Just shows you how impressive those games still are by today''s standards in how incredibly short Garshasp falls in comparison. You get what you pay for when it comes to this one, but I will say it did not bore me through its meager runtime.', 'Mixed', 49.67, 25.58, 2.75);
INSERT INTO reviews VALUES (1202, 99700, 195, 'Cool puzzle game with a simple but great story and art style, some puzzles can be a bit annoying though but overall really great game', 'For the Price point of $10 I would not recommend this game, the music is dull as is the levels. The levels don''t get any challenging and stay at a constant difficulty set. Yes, there was some levels that stumped me and took several tries before completing, but the game was more frustrating on the simple fact that it never threw a challenge and felt more like a task completing each level. I noticed on some levels the reuse of old puzzles from earlier maps and some puzzles could be skipped all tog', 'Very Positive', 92.31, 1.87, 7.98);
INSERT INTO reviews VALUES (1203, 99830, 131, '2 minute TLDR:\r\n\r\nCrysis 2 continues the story from where 1 left off, but now you play as Prophet. Deliciously slick gunplay, great graphics and more streamlined mechanics to toy with, culminating in some truly epic gunfights to remember. While the story is still action focused, it''s there, doing it''s thing. Absolutely worth grabbing for a weekend of fun.', '1 and 3 are better.', 'Very Positive', 93.13, 58.20, 32.43);
INSERT INTO reviews VALUES (1204, 99900, 102, 'I started playing this game to get the free tf2 items. However, while playing I got fond of it. Its really fun so I recommend this to not just TF2 players but everyone.', 'Lets be honest, you played this for the tf2 hat', 'Mostly Positive', 77.45, 9.62, 9.02);
INSERT INTO reviews VALUES (1207, 102200, 161, 'Why don''t they make more games like this?!\n\nSimple card playing mechanic that''s fun and addicting. Then you have a vaguely interesting storyline that your character has to make his way through.\n\nIf you like Puzzle Quest (1st one), you''ll love this game! \n\nSeriously, they need more games like this!', 'This is more of a card-battler style of game than it is a mostly casual deck building game, though there are elements of selecting cards to boost your abilities in the games. It is an interesting mix of solitaire style card layout for you and your opponent, yet you must mix and match cards to create a poker hand in order to do deal damage. If there is a chest, you need to create the hand it asks for in order to open it an gain access to different types of cards; each type either does a different', 'Mostly Positive', 76.40, 23.83, 31.57);
INSERT INTO reviews VALUES (1209, 102500, 8013, 'It''s got fluid combat, a pretty flexible class system, interesting lore and world to explore, and strong visuals (vibrant, colorful art style). My biggest complaint is that KoA''s chock-full of fetch and kill quests that become repetitive real fast. The story''s also not very memorable; it starts off strong, but it kind of fizzles out towards the end.\n\nOverall, it''s a fun game, but I think it would''ve been a lot better if it had co-op/multiplayer, as at times it feels like an MMO-lite.', 'Hiding DLC for older version of the game is a crime.', 'Very Positive', 87.88, 120.80, 87.53);
INSERT INTO reviews VALUES (1210, 102600, 3519, 'A lot of fun! Sometimes you almost feel bad for the Orcs ... Almost.\n\nRecommend it 110%!\n\nPS: I hate you Armored Ogres! No pity for them!', 'Doesn''t work in proton in linux - Keys aren''t functional and game needs to be restarted every level.', 'Overwhelmingly Positive', 96.22, 16.12, 2.23);
INSERT INTO reviews VALUES (1212, 102840, 672, 'God of War 2D\nI Want Shank 3 \nMy wife said if this review gets 100 likes and 50 awards, she will let me play all week without seeing the sun or touching the grass.\n\n', 'It is impossible to play without a gamepad.', 'Very Positive', 80.65, 4.72, 4.85);
INSERT INTO reviews VALUES (1213, 102850, 229, 'If anyone has a problem with EA/Origin login just read this post -> https://steamcommunity.com/sharedfiles/filedetails/?id=3183980501\n\nLong story short you have to redeem a code from Steam on EA library to activate WARP on EA, install it, open it, then just close the game and open it on steam. It should open normally now (I dont understand, how this thing worked out, but it did)\n\nHope it helped! :3', 'DO NOT BUY IT!\nEA broke it, you cannot play it here. It asks you to login in origin, but will say it''s offline and cannot connect despite being online. EA is such a trash company, it''s insane.', 'Mixed', 62.45, 5.90, 0.20);
INSERT INTO reviews VALUES (1214, 104000, 108, 'A 2011 time capsule best left buried. Play it to laugh at your past self’s standards, then uninstall before it infects your library with existential dread.', 'I''m sure most of you guys are familiar with the term ''tower defense''. It''s a game where you build and upgrade towers to defeat waves of enemies and, later on, bosses trying to destroy your . If you''ve seen one of them you''ve seen pretty much all of them. Somehow I do enjoy playing them, even though most of them are simply clones. This one is ok I guess. Graphics are nothing special and it does what it''s supposed to do. However, there are definitely better tower defense games around, so get this ', 'Mostly Positive', 72.22, 1.75, 0.25);
INSERT INTO reviews VALUES (1217, 104200, 1380, 'BEEP\n\nHas a total of 5 trading cards.', 'Its not for me.\ngot it a decade ago for a few cents.\nnever got it to work until now, and in my opinion it aged like milk, and not in a good way.', 'Very Positive', 81.88, 1.02, 2.28);
INSERT INTO reviews VALUES (1218, 104600, 460, 'unfortunately it is very broken. i still recommend it because it''s very cheap.', 'pretty disappointing. a lot of the interactive elements don''t work anymore, its kinda low quality, and some random douche bought the thefinalhoursofportal2 domain and now its just some random WoW website. valve has completely abandoned this.', 'Mostly Positive', 78.26, 3.77, 0.30);
INSERT INTO reviews VALUES (1219, 104900, 11467, 'I love you mr disonours', 'No one is on and the bots are brain dead.\nIdea is fun but not for solo players', 'Mostly Positive', 78.32, 1.17, 2.05);
INSERT INTO reviews VALUES (1220, 105000, 575, 'I''ll keep this short. - If you like the Broken Sword series, then you''ll  Love  this game!', 'While i enjoyed overall the game, the bugs present are quite a sad state of affairs, especially for a supposed refined release. Multiple times the prompts switch automatically to russian, lots of crackles and pops in the audio tracks, sometimes lines of dialogue get pushed aside automatically without left-mouse clicking and, oh, yeah, THE ENGLISH CREDITS CUT THROUGH A FEW SECONDS IN. The fact that this was never caught nor patched out in all these years is genuinely embarassing, and without much', 'Mixed', 64.52, 23.93, 16.53);
INSERT INTO reviews VALUES (1221, 105100, 196, 'TLDR: GOOD, BUT ONLY BUY THIS ON SALE! \n\nThis is a fine little point-and-click puzzler with a beautiful art style and puzzles that are mostly satisfying. It is the first chapter of the game ''Lumino City'', which means there is a mystery and story that goes unresolved in this game. The drawbacks are that this seems to have been made for mobile. The gameplay window is tiny and means you might click on things you intend to investigate and miss the target. It is also a very short game, and frankly sh', 'Disappointed. Overall this game is not bad, but the puzzles are extremely difficult and the gameplay is entirely too short for the $7 they are charging. I purchased this game on sale for $3, and I still don''t think that amount of money was worth it. If this game were $1 or less, I would be writing a much more positive review. If you love point and clicks with great artwork like I do, then you''ll find this game to be just ok. Instead of this game, I would recommend the game "Tiny Bang Story". I g', 'Mixed', 50.00, 1.05, 1.40);
INSERT INTO reviews VALUES (1222, 105300, 179, 'They weren''t kidding when they wrote up the description for this little gem. Brutally simple to learn, simply brutal to master, Critical Mass is the kind of game literally anybody can just pick up and waste hours upon hours of their lives playing, all in a vain attempt to top the charts. And don''t think for a second I mean any of that in a bad way. Far from it; Critical Mass possesses a fun, addictive quality rivaled only by the likes of Tetris and similar titles.\n\nIn case you still have doubts,', 'I hate bashing on Ozzie companies. ;p And this isn''t an evil, unplayable game. My first impression was good, I played it for a bit, expected to play more, had it installed forever, yet every time I fire it up, I close it after 5 minutes.\n\nIt''s a match 3 game with some 3D tetris elements. The concept is good. The graphics are polished. The music isn''t bad. The controls feel annoying at first, but they''re actually mostly okay. The problem is, the gameplay doesn''t feel satisfying. It expects (and r', 'Mixed', 66.48, 3.07, 1.38);
INSERT INTO reviews VALUES (1223, 105420, 140, 'i need twisted pixel to stop focusing on vr games and to go back to their roots like this franchise, comic jumper, the maw, etc\nwe need our meth and cocaine supplements from the splosion man franchise', 'The game seems broken on modern PCs. Controls dont register right, no fixes known.', 'Very Positive', 84.29, 12.45, 0.60);
INSERT INTO reviews VALUES (1224, 105600, 556960, 'work for 10h? nah, bro\nbuild an arena inside the jungle for 10h while simultaneously being attacked by projectiles coming from offscreen every 0.2s, dodging poisonous darts like neo, then dying to some turtle falling from the sky dealing 3/4 of your max hp? hell yeah, brother. And the worst part? I would do it again 10/10', 'Sadly sold out to political investor/extremists..\n\nThere''s not even a good argument to be made to make these changes, removing gender is just removing content/potential content/value from a game, For this game specifically it''s just an annoying propagandist message (I don''t remember if gender added anything specific). \n\nBut for many games that follow suit, they''re just removing stuff for no good reason, Stardew for example has mechanics and dialogue tied to gender, Animal Crossing used to have L', 'Overwhelmingly Positive', 97.72, 503.82, 518.75);
INSERT INTO reviews VALUES (1226, 105800, 352, 'PIxeljunk Eden (2012)\n\nFun little game, you play as this little blob guy that can jump and swing upwards to collect like pollen orbs to make new branches sprout out to climb higher. That''s about the game. It''s fun for a little while, but gets somewhat repetitive quickly. Fun game to play between other games or downtime. I don''t like the time limit you have to complete missions, it would have been much more enjoyable to just take it easy at your own time. Nothing wrong with a time limit, I person', 'This is a favorite game of mine from back in the PS3 era. However the issue is for quite some time every time I boot the game, its resolution is jacked and my control doesnt want to respond. For those willing to take some time messing around in the games files to get the resolution working its still an incredibly unique gem of a game deserving a play through. But it seems the PC version takes some love to get working.', 'Very Positive', 83.52, 4.43, 6.93);
INSERT INTO reviews VALUES (1227, 107100, 17261, 'the roots of hades. this is what started it all for supergiant. great replayability, relatively short game (8 hours for the first run), a classic.', 'It''s ok. The writing is straight up bad and the gameplay is nothing special, but it does try to have a coherent aesthetic/vibe and there''s a good amount of polish/professionalism. Still, like the rest of the Supergiant catalog, this game is the definition of bland, corny "high mid"', 'Overwhelmingly Positive', 96.35, 12.38, 13.77);
INSERT INTO reviews VALUES (1228, 107200, 1839, 'SPAZ delivers competent space combat wrapped in progression systems designed to extract maximum engagement from minimal content—a mathematical exercise in stretching 10 hours of unique gameplay into 40 hours of perceived value. You''ll enjoy it until the moment you recognize the patterns, then wonder why you ever did.', 'Game wont start, but it was running somehow in a process in the background so now i cant even return it~! What the hell.', 'Very Positive', 92.01, 9.87, 2.65);
INSERT INTO reviews VALUES (1229, 107300, 926, 'Old school classic.', 'Another derivative RPG (they say parody but it means the same thing really), better off for a sketch in a comic on animation then a paid for product.\r\n\r\nOr as an RPG maker game. Pick up any of the games this is trying to emulate (superficially). Nothing I saw with my playthrough felt like it was worth the time.', 'Very Positive', 83.80, 1.18, 1.18);
INSERT INTO reviews VALUES (1230, 107310, 2092, 'Ignore the small amount of hours. I played both Breath of Death and this back on the Xbox Live Arcade days. They are both hilarious tributes to the NES/SNES JRPGs and deserve a lot of love. as of this writing (steam winter sale), they are bundled together for less than $1 and are absolutely worth it even for the full prices individually not on sale. Do not listen to the haters that expect too much out of a 2011 indie JRPG parody. it is great fun, especially if you are into old school JRPGs\n', 'Another near miss for me. Better then the parody game that was Breath of Death VII, has more of its own identity, beyond going "hehe member that thing RPGs do?" *giggle* while actually doing said thing and thats it.\r\n\r\nAnd in a way with the complete over saturation of "old gods" lore in games in recent years it almost feels more timely then every to make a twist on it and honestly anything that disrepects the source given the creator of said genre is a bonus.\r\n\r\nBut ultimately there was nothing ', 'Very Positive', 92.59, 4.10, 3.15);
INSERT INTO reviews VALUES (1231, 107410, 106639, '10/10 Game\n\nI love how I can drive into people''s vehicles and fling them into space and also made me realise 10 FPS is playable.', 'This game has so much potential but for whatever reason, the developers made it so needlessly convoluted and confusing that it''s honestly unplayable. Prepare to be frustrated beyond where you thought you could go. Every single small action takes nine thousand key combinations so you will never know how to do anything. Even the campaign is so infuriatingly hard, not because of actual difficulty, but because the controls are so horribly bad and everything is explained in the least helpful way poss', 'Very Positive', 91.65, 2041.08, 9.60);
INSERT INTO reviews VALUES (1232, 107600, 645, 'Adictive, simple, but adictive.', 'Beautiful, catchy music, but chasing something as ephemeral as a score is deeply unsatisfying.', 'Overwhelmingly Positive', 96.59, 1176.43, 0.45);
INSERT INTO reviews VALUES (1235, 108500, 274, 'This is probably my favourite small indie game.  The sprite-work and soundscape are appealing and great at keeping the player engaged.  I found the narrative to be engaging and the short journal entries paced well enough that I was excited to read them every time they popped up.  There have been next to no bugs throughout my three playthroughs so the game feels well crafted.  The platforming does feel a little janky but not to the point where it ever seriously messed up my gameplay.  Finally, th', 'The controls are wonky (no mouse control, have to fully use keyboard or controller despite Steam having no controller compatible label on the library page) and even switching to didn''t help all the issues I was having.  The sound design is also really off-putting.  I like puzzle games but I can easily tell both of these issues are going to ruin what enjoyment I could have gotten.', 'Very Positive', 89.42, 33.08, 0.43);
INSERT INTO reviews VALUES (1236, 108600, 127104, '-got a acc with the game for cheap\r\n-load in\r\n-random percs\r\n-20mins in cant hear nothing, thought it was a bug\r\n-got jumped by 5 zombies, died\r\n-turned out my character was deaf\r\n-11/10', 'pros: most realistic zombie survival game \r\n\r\ncons: most realistic zombie survival game', 'Very Positive', 94.27, 22.88, 5.28);
INSERT INTO reviews VALUES (1237, 108700, 342, 'I played the Death Rally game that was made in the 90s from Steam that I got for free and finished it. I wanted more and decided to wait for a steam sale to come to get this game. Got it for less than 3 euro. So you start off as a guy in the road trying to escape from the police then gets captured and is forced to do this death rally racing game. You start off with a slow car making your way to faster cars. You get a gun that fires until it locks on to an enemy. Shame it doesn''t just shoot when ', 'I was expecting a more glorious version of the original. Instead it''s more like a different game with some really iffy physics and an unsatisfying progression. You already had the perfect game to build on to - how could you screw this up? Nice graphics though, but that''s all there is to it...it doesn''t feel like Death Rally :(', 'Mixed', 68.13, 5.13, 96.97);
INSERT INTO reviews VALUES (1238, 108710, 13857, 'Alan Wake is one of the most atmospheric and engaging psychological thriller games I have ever played. Developed by Remedy Entertainment, it follows the story of a bestselling writer, Alan Wake, who travels to the small town of Bright Falls with his wife to escape writer’s block. However, things quickly take a dark turn when his wife disappears, and he finds himself trapped in a supernatural nightmare, with shadowy enemies hunting him and pages of a manuscript he doesn’t remember writing coming ', 'An interesting story and premise, but bogged down by repetitive, mind-numbing, often infuriating gameplay. The game essentially boils down to, go to his place, kill monsters on the way, get some plot coupons, rinse and repeat. And it''s all topped off by a disappointingly easy "boss fight" and a dull, unsatisfying ending. \r\n\r\nWould''ve been better as a TV series.', 'Very Positive', 88.66, 4.53, 12.27);
INSERT INTO reviews VALUES (1239, 108800, 3193, 'Crysis 2 is not about Nomad anymore, it''s about Prophet, aliens and New York. I replayed this game at least 5 times and 3 of them on the maximum difficulty. It is a great game, the stealth is the best part of it. What saddens me is that there''re no achievements in this game.\nBeautiful environments and an exciting story. If you were a fan of the first, you won''t be disappointed with Crysis 2.', 'Delist EA. Forcing third-party accounts and banning for inactivity with no appeal is predatory.', 'Very Positive', 82.40, 32.33, 3.85);
INSERT INTO reviews VALUES (1242, 109600, 108, 'After playing this game for a while, i have to say i have enjoyed many hours of game play. Yes, you can pay ( with a ton of cash, it is not cheap) to obtain the end-game enchantnments and mounts quicker but nothing that you can not get with spending some time grinding out content. The best possible thing for any new player coming into the game would be to find a good guild. This will save you tons of time. Money can not buy you skill, i see 3.2 item players out dps and out play 4.3 players every', 'I made a purchase on Neverwinter on the undersatnding that I would receive a "First Time Buyer''s Pack" The text on screen says (accessed by presing Alt then "Y" ) "You will receive this item through in-game mail after transfering at least 500 Zen to your account" (I transfered 1000 Yen through steam wallet) Then when I make an in game ticket the company says it does not apply to Steam transactions. Which they never told me in the first place. Then they tell me if I want a refund go to Steam. To ', 'Mostly Positive', 70.37, 3248.00, 85.08);
INSERT INTO reviews VALUES (1249, 110800, 14536, 'L.A. Noire is one of the few games out there that forces the player not to strategize, but to analyze. You’re studying the human face, gathering evidence and coming to conclusions based on that evidence. I just love the whole 1940s vibe so much the cars, style, music. Say what you will about the quality of the game, but to this day it is still one of the most distinct ones out there. Rockstar should give L.A. Noire another shot it would do really well.\n', 'Oh, I see you''ve played this game before, please login to play! Don''t remember your password, no problem, here''s a link to reset it! Oh, by the way, THAT is not the account you used to play THIS game on, so you can''t login with it. No other accounts will be accepted for THIS game, even if you have an account you are able to use to play other games of ours that you''ve also purchased from the same platform. We''re sorry that at some point you changed your email and we updated all your /other/ games', 'Very Positive', 83.90, 34.30, 18.78);
INSERT INTO reviews VALUES (1252, 111100, 110, 'Classic physics-based gameplay and a goofy presentation.  Speeding through levels is fun, and losing all of your snugglies is expected.  It''s good cheap fun!', '\nLight physics based game where you drive your truck while avoiding to lost your fav plushies. Gameplay is ok and reminds titles like Elastomania but level design is rather poor and game is missing on something more interesting. For one playthrough it might be managable. There isn''t much variety and forest stages take most of the game. Music is a little bit oomfy-poomfy. You gain different medal for completing stage under certain amount of time or delivering all the plushies to the end of level.', 'Very Positive', 89.09, 2.02, 5.40);
INSERT INTO reviews VALUES (1254, 111400, 176, 'An unfairly maligned title. Don''t suck at top-down shooters. Play with people you know. Harder difficulties are exceptionally fun. : achievements are fixed!', 'I would happily pay for this game to not show up in my library.', 'Mostly Negative', 37.50, 53.87, 0.23);
INSERT INTO reviews VALUES (1255, 111600, 304, '\r\nStack weapons and blaze your guns like there''s no tomorrow while jumping on some platforms. Obviously not the best "Serious" game out there but from a few that are available as a kind of spin off titles this one seems good enough. Remember that stacking too many guns at once might overheat your PC! *double wink*\r\n', 'One of those "let me play the fucking game" games. Every 3 minutes the Gameplay is interrupted by a cutscene, some dialogue or other shit. Maybe it gets better later but I really can''t be bothered.', 'Very Positive', 82.24, 6.10, 0.32);
INSERT INTO reviews VALUES (1256, 111800, 263, '⣿⣿⡻⠿⣳⠸⢿⡇⢇⣿⡧⢹⠿⣿⣿⣿⣿⣾⣿⡇⣿⣿⣿⣿⡿⡐⣯⠁ ⠄⠄\n⠟⣛⣽⡳⠼⠄⠈⣷⡾⣥⣱⠃⠣⣿⣿⣿⣯⣭⠽⡇⣿⣿⣿⣿⣟⢢⠏⠄ ⠄\n⢠⡿⠶⣮⣝⣿⠄⠄⠈⡥⢭⣥⠅⢌⣽⣿⣻⢶⣭⡿⠿⠜⢿⣿⣿⡿⠁⠄⠄\n⠄⣼⣧⠤⢌⣭⡇⠄⠄⠄⠭⠭⠭⠯⠴⣚⣉⣛⡢⠭⠵⢶⣾⣦⡍⠁⠄⠄⠄⠄\n⠄⣿⣷⣯⣭⡷⠄⠄⢀⣀⠩⠍⢉⣛⣛⠫⢏⣈⣭⣥⣶⣶⣦⣭⣛⠄⠄⠄⠄⠄\n⢀⣿⣿⣿⡿⠃⢀⣴⣿⣿⣿⣎⢩⠌⣡⣶⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣆⠄⠄⠄\n⢸⡿⢟⣽⠎⣰⣿⣿⣿⣿⣿⣿⢀⣾⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣦⠄⠄\n⣰⠯⣾⢅⣼⣿⣿⣿⣿⣿⣿⡇⣾⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⡄⠄\n⢰⣄⡉⣼⣿⣿⣿⣿⣿⣿⣿⢸⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣧⠄\n⢯⣌⢹⣿⣿⣿⣿⣿⣿⣿⣿⢸⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⠄\n⢸⣇⣽⣿⣿⣿⣿⣿⣿⣿⣿⠸⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⠄\n⢸⣟⣧⡻⣿⣿⣿⣿⣿⣿⣿⣧⡻⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⠄\n⠈⢹⡧⣿⣸⠿⢿⣿⣿⣿⣿⡿⠗⣈⠻⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⡇⠄\n⠄⠘⢷⡳⣾⣷⣶⣶⣶⣶⣶⣾⣿⣿⢀⣶⣶⣶⣾⣿⣿⣿⣿⣿⣿⣿⣿⣿⠇⠄\n⠄⠄⠈⣵⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⢸⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⠄⠄\n⠄⠄⠄⠸⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⠘⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⠇⠄⠄', 'It''s... not a great game. It''s not bad, but it''s not good either. The puzzles are just too simple, and it''s frustrating when you make a mistake because levels are long and without checkpoints (and they really need checkpoints). So yeah, even I - the puzzle fanatic - wouldn''t approve this.', 'Mostly Positive', 77.57, 0.97, 5.97);
INSERT INTO reviews VALUES (1257, 112100, 348, 'avadon', 'Not for me...the level progression is soooo simplistic it''s like *Dumber Diablo* yet it claims to be some kind of deep story driven CRPG. It''s not, its a party based ARPG at best and the story is dull, so is the world. If you think Spiderweb stuff is deep well written fantasy with a fascinating world and lore you need to get out more and play more games/read more books.', 'Very Positive', 82.18, 9.77, 66.23);
INSERT INTO reviews VALUES (1258, 113020, 2536, 'Lots of fun, one of my all time favourite games. Can''t wait for the sequel.', 'Beware people with colorblindness such as myself, when you are playing co-op with others, it almost impossible to tell which character you are playing as, causing many frustrations when you think you are controlling your character but instead trying to control someone else''s and the colorblindness mode does slim to nill to actually fix that problem.', 'Very Positive', 92.63, 49.77, 2.57);
INSERT INTO reviews VALUES (1259, 113200, 22770, 'They should add some more DLC to the game, like one you are reborn, then another where you play with your afterbirth, then you play with your afterbirth again, probably one where you repent, and then an online one where you repent online.', '\nFrom the gameplay point of view this game is outstanding. Rogue like with dozens of random items with various unusual effects and multum of enemies. Each run is different I mean seriously, levels, items and monster placement are random generated. Controls are simple but works as they should. Big negative for repulsive visuals that resembles some terrifying doodles from abducted by monsters child that wanted to tell the story of his life.\n', 'Very Positive', 94.76, 3.07, 5.02);
INSERT INTO reviews VALUES (1260, 113400, 173, 'Honestly one of the highest quality games i''ve ever played. The anti-cheat is phenomenal, after nearly 5 years of playing this game I barely noticed any players cheating in this video game! You can count on the reliable staff to solve any issues or help you with any problems you may have. Speaking of the staff, one of their best qualities is that they listen to every single word that the community has to say... they REALLY deliver, honestly they''re some of the most reliable and knowledgable peop', 'easy to hack and to get hacked have fun pay to win players', 'Mixed', 43.93, 3094.45, 992.20);
INSERT INTO reviews VALUES (1262, 115100, 1771, 'Probably one of the best games you could play during Halloween month. Is just simple yet fun and extremely soulful. The credits of the game are pics of the developers as kids wearing their Halloween costumes- that''s a kind of fun you don''t see in games a whole lot.', ' Geeked Up Reviews: 1.5/5 \n\n *DISCLAIMER* \nAll review scores are indicative of my personal enjoyment of the game and are not meant to be taken into consideration for the quality of the reviewed game(s). A negative review means I genuinely came away from a game feeling as if I had wasted my time.', 'Overwhelmingly Positive', 95.26, 9.45, 0.13);
INSERT INTO reviews VALUES (1263, 115110, 642, 'It''s a game for children, but done in a very charming way with rather unique game mechanics. Quite short, and with fairly easy puzzles - an enjoyable romp.', 'Nah.', 'Very Positive', 91.43, 18.55, 3.63);
INSERT INTO reviews VALUES (1264, 115120, 646, 'Remember when this game was called Trenched?', 'Pretty sure this is a cryto miner, as I cannot understand how a Xbox360 game could use more memory than almost all modern games I''ve played. Its so poorly optimised that, and uses so much memory that the game causes constant stuttering and audio issues, even while playing single player. The devs have also advised one of the best ways to fix this is to turn off your pc''s anti virus and other protections.', 'Very Positive', 85.29, 2.52, 1.67);
INSERT INTO reviews VALUES (1265, 115200, 179, 'Still to this day one of the best games about Napoleonic wars, hands down. Moreover, highly addicting and makes you wanna replay campaign after campaign.', 'game keeps crashing, waste of money.', 'Mixed', 57.54, 14.18, 36.22);
INSERT INTO reviews VALUES (1266, 115210, 221, 'Evil Age of Empires. Cursed game and hard to beat the AI.', 'dont fall for being told american conquest is a dlc pack for cossacks3 as the american conquest and it dont even work and it  has nothing to do with cossacks3 and im not happy that steam has resorted to that type of selling tatic so im deleting the american conquest and ill not be buying anything else from steam', 'Mostly Positive', 71.04, 6.55, 0.47);
INSERT INTO reviews VALUES (1267, 115220, 180, 'The game can be played by installing the program and cossacks patches from github.com/FunkyFr3sh/cnc-ddraw \nI love this game, there''s no RTS quite like it apart from Cossacks', 'game keeps crashing even if I uninstall and reinstall game . error note keeps occurring .', 'Mostly Positive', 70.56, 9.88, 1214.23);
INSERT INTO reviews VALUES (1268, 115300, 6418, 'Words cannot explain how freaking cool the original 2007-2011 Modern Warfare campaign is. Makes you feel like an absolute badass doing some badass work. Video games aren''t supposed to be a chore, they''re supposed to be a playable movie. Infinity Ward & Treyarch had it right, back then. So good.', 'lower the price', 'Very Positive', 87.94, 35.98, 0.42);
INSERT INTO reviews VALUES (1269, 115800, 2313, 'That was beautiful. A relaxing time with a good story. 100%-ing this game is very difficult so I won''t attempt it but I recommend this one for sure.', '2/5\r\nThis game is visually stunning, every building, every shrub, ever cloud is detailed and unique.  Every level has its own color scheme with some unique character designs.  But goddamn the gameplay is a total mess.  The abilities feel so strange, needing to pick up a person to use a weapon/ability just does not work well.  Your gun shoots below center too, which makes it incredibly uncomfortable when 3+ enemies are thrown at you in close quarters, especially since owlboy himself can''t kill an', 'Very Positive', 85.91, 11.07, 4.52);
INSERT INTO reviews VALUES (1270, 116100, 105, 'Great game for little kids breaking into video games.', '- Feels unfinished\n- Controls and collision detection are a bit off.\n- Speed is rather slow\n\nNote: One cool feature this game has.\n\nWhen you lay a bomb behind you, a little rear view window pops up and stays on screen until someone hits your bomb. So you can see if your placement was any good... Thumbs up for that..', 'Mixed', 61.90, 18.57, 3.93);
INSERT INTO reviews VALUES (1272, 200010, 1263, 'Saw this on a video a while back, and I''ve finally gotten to play it.\r\nThe Portal comparisons are inevitable, but I think they are well-deserved. Good story mode, replayable for high scores, and makes physicists cry. Just ask me, I''m one of them.', 'I first played this about 14 years ago when It first came out. I remember being really excited for it because the Portal Creative lead was also taking the lead on this one. I remember even back then being dissappointed by this game and I still am now. On a game play level, it is a very decent game. The dimension shifts all come together to create a fun, mechanically deep puzzle game with emergent game play solutions. My main issue is the direction of everything else.  The visuals are bland, the ', 'Very Positive', 83.85, 5.72, 7.47);
INSERT INTO reviews VALUES (1274, 200080, 343, '*SPOILERS*\r\n\r\nAITA for tricking my girlfriend and her family into thinking their dead mom is haunting their hotel so that she will move to the city with me?', 'I am picking back up this review series of playing every Nancy Drew game. The reason it fell off was because of this game. Every other Nancy Drew in the series up until this point has had about 6 or less hours of game play. Then, this game was next in line and destroyed my momentum. \r\n9 HOURS, the playtime of this game doubled many other games i played so far, and you want to know why? No direction. Although the story is cool and it is unique being in Japan and all that, But Herinteractive could', 'Very Positive', 80.76, 10.80, 9.15);
INSERT INTO reviews VALUES (1275, 200130, 144, 'Hardly anyone else uploads games like this one Steam, only alternatives are stuff like Wordle, which is a bit different from this. I mostly enjoy this as a calm casual puzzle game that isn''t too complex. Reminds me of the (mixed) puzzle books I got as a kid, they were similar to this and they don''t really make them like that as much anymore. If you want more complex stuff, play the chess games, I''m not into chess as much. My favourites are dominos, go fish, games like this and jigsaw puzzles.', 'Don''t get me wrong. This game isn''t too bad...thing is the first game was much better. They replaced the presents with a wheel you spin for letters and hint tokens. They changed some of the mechanics for some games (example: Fitword is kinda wonky. Instead of typing or drawing the letters, you have to drag and drop the words, and it''s slightly annoying to do that.) Some instructions are vague (for example: Backwords. You have to shade in the wrong letters rather than the right letters, which is ', 'Mostly Positive', 78.47, 5.92, 8.08);
INSERT INTO reviews VALUES (1276, 200150, 261, 'I''ve finally purchased  a pc that can handle this program without locking up. B.C. adds a lot of fun to the game. But need a fast pc to run it. I really like the graphics and sound. I think this program would appeal more to a younger person than some seriously old experienced chess expert. Just my humble opinion.', 'It will Crash to desktop and in most games the game skins will go to all black what makes it hard to keep track of your side\n\n', 'Mixed', 50.19, 10.88, 4.73);
INSERT INTO reviews VALUES (1277, 200170, 2177, 'Пацєтко пацєтко сє вродило Пацєтко', 'The game itself is just fine. Works just as well as all the others. It''s the Multiplayer that sucks. I bought the 4-pack for the purpose of playing the game WITH family/friends and, unfortunately, we can only connect to one another about 1-in-5 tries and THEN only about HALF the time does it progress past "waiting for other players".  If you like playing Worms alone then, that''s great, enjoy. But, if you bought the game specifically for multiplayer with anyone other than complete randos, then...', 'Very Positive', 83.14, 23.02, 2.08);
INSERT INTO reviews VALUES (1279, 200210, 120, 'When u start this game\nYou''re gonna hate it\nThen, u quit\nU come back\nAnd u start again\nThen u start playing', 'You die way too easily, so much as getting your fingers twisted will kill you. You aren''t given enough storage space without spending a ridiculous amount of money on in game currency as well. This game feels like a cheap trap for kids with their parents credit cards. It''d be fun if it wasn''t so hard to get decent gear and collect things but the game really isn''t. No, you either get really good at running around and dodging and never make a mistake or you die and lose everything. You only get eig', 'Mostly Positive', 78.33, 2692.92, 53.60);
INSERT INTO reviews VALUES (1280, 200230, 261, 'Fun game, love the physics, love the vehicle selection. Dislike is the multiplayer does not work, and also doesn''t have a track editor.', 'This game started out VERY FUN. I was initially impressed. Then, as you move into more difficult races, they become impossible no matter the vehicle or settings you use. This made it nearly unplayable and I had to move on.', 'Mixed', 67.05, 0.40, 10.00);
INSERT INTO reviews VALUES (1281, 200260, 23029, 'I still find myself coming back to this game every two years or so. It reminds me of when times were simpler, and as I get older, the game feels as solid as ever! If you haven''t play one of the greatest superhero games, then this is my recommendation to try. The game has great replay value (except Riddler, fuck him) and the entire franchise goes on sale often. If you''re looking to sink your teeth into the world of the Dark Knight, then wait for that sale, buy ''em all, you won''t regret it!', 'gotta be the worst series of games I''ve ever fucking played thx.', 'Overwhelmingly Positive', 95.91, 59.05, 10.03);
INSERT INTO reviews VALUES (1282, 200370, 271, 'Great game!\n', 'The tutorial sucks. It cites things that are buried in menus. Instead of opening up options as you progress, like most tutorials, they just throw a bunch of stuff you don''t need at the start and then want you to dig thru it all. Might as well just go to the first level. \n\nThe controls suck. How do i rotate anything? No clue. can''t build anything how or where i want it because i have absolutely no clue how to rotate the object I''m trying to place. Even how it pauses things automatically when i go', 'Mixed', 60.52, 144.62, 0.97);
INSERT INTO reviews VALUES (1286, 200510, 24074, 'This is a PSA: Steam has finally updated their side and the game now works. You need a clean installation for it to work. \n\n\n XCOM: Enemy Unknown is a great game, definitely recommend. Shame it took so long for Steam to update the game on their end to actually -work- without the Take2 Launcher.', 'Game no longer launches correctly - Gets stuck on "Updating Executable" for a while and then quits. Persistent problem affecting many people for the past month with no fixes.', 'Very Positive', 93.04, 4.85, 36.38);
INSERT INTO reviews VALUES (1287, 200550, 143, 'one of my fav dungeon game ever!', 'game is not letting me play without setting up a kalypso account', 'Mostly Negative', 37.06, 3.92, 5.62);
INSERT INTO reviews VALUES (1288, 200670, 122, 'Fantastic graphics and an OG excellent game', 'As long as I could play it, I had fun.\nUnfortunately, the game is unplayable and crashes very often because of a sound bug. If you''re lucky, you can play for a whole hour. If you''re unlucky, the game crashes after 10 minutes.', 'Mostly Negative', 29.51, 5.77, 3.55);
INSERT INTO reviews VALUES (1289, 200710, 17053, 'It''s the game I''ve been playing the most offline lately (because I''ve been an earthquake victim and haven''t had a stable internet connection since February 6). In one word, amazing.', 'Why do I require a runic login which doesn''t work and the password reset option is known to not work, but is still up to make people waste even more of their time to do? What an absolute waste of players time. Just let me play via steam multiplayer and stop with all of these logins within logins within logins that don''t work.', 'Very Positive', 93.48, 3.37, 15.25);
INSERT INTO reviews VALUES (1290, 200900, 3488, 'Everyone should play Cave Story. It’s an absolute classic, and you can even snag it for free at cavestory(dot)org.\n\nMy first time playing Cave Story coincided with my decision to binge the Chris Chan documentary. The crushing difficulty of Cave Story paired with the unrelenting cringe of the Chris Chan’s saga seared both into my memory forever.\n\nIf endurance is the measure of greatness, then I’m officially a legend after surviving that week.', 'f nicalis for leaving this game to rot btw. i advocate for the piracy of every game they''ve published because you know damn well the money isn''t going to the original devs', 'Very Positive', 91.80, 30.00, 3.90);
INSERT INTO reviews VALUES (1291, 200910, 899, 'I''m reviewing all my 600+ gamed. This is 18th.\n\nAs a game designer, I''ve seen a lot of people trying to make fighting rhythm games. This is the only one I''ve played that did it well enough. It''s not perfect, the art is a bit janky, but the gameplay is original and pretty well done. A very nice curiosity.\n\n\nAlso did you know, it was called Sequence before.', 'Before the Echo is a game that struggles to define its audience. Marketed as a rhythm game, it falls short of delivering on that promise. The gameplay revolves around managing three different screens: one for gaining mana via directional inputs tied to a beat, another for avoiding damage by inputting directions, and a third for casting spells based on specific inputs. The problem is that only the mana-gathering screen has any rhythmic elements, while the others lack any designed rhythm, making i', 'Very Positive', 89.77, 13.62, 6.33);
INSERT INTO reviews VALUES (1292, 200960, 282, 'Classic', 'I went on a classic crpg buying spree years ago but am only now playing the geneforge series. I played a whole lot of the dev''s other series of games. They are fun and highly nostalgic games that, if you really dig the old school style, will provide literally hundreds of hours of play time in a single run of the game. \n\nThat being said, I use linux to play this and it''s just hurting with bugs. If I max the resolution with the game resolution tool its unplayable, I can''t move my cursor anywhere a', 'Very Positive', 93.26, 25.70, 7.62);
INSERT INTO reviews VALUES (1300, 201270, 20187, 'Good game, already got over 1130 hours but still haven''t take over the whole Japan yet.', 'Fuck you corpos for destroying a great game! Can''t run mods, and without em still crashes, thx assholes', 'Very Positive', 92.43, 1168.60, 1366.80);
INSERT INTO reviews VALUES (1301, 201271, 650, 'Say what you will about this getting re-released at a higher price, this is the singular masterpiece of the entire franchise. The decline of Total War is incredibly sad, and it''s unbelievable that - well over a decade later - we have yet to receive another gunpowder Total War. It seemed inevitable they''d go back after this DLC''s success, especially on the heels of Napoleon''s popularity. But no, we get Pharaoh. CA isn''t getting another dime for me until they rediscover their most successful formu', 'Awesome game. Horrible moneygrab re-releasing this just because it was popular. The corporate world is so disgusting.', 'Mixed', 64.62, 0.00, 0.00);
INSERT INTO reviews VALUES (1302, 201290, 560, 'A fun space age RTS that i can enjoy with others and on my own good qulity and graphics decent story line and just fun a small lerning curve but if u lern it u will be ready for just about anything even sins of the solar empire 2', 'outdated version of Sins of a Solar Empire: Rebellion so unless this is on sale and Rebellion is not and you want to see if its a game for you dont buy this', 'Mostly Positive', 78.39, 3.73, 0.32);
INSERT INTO reviews VALUES (1303, 201420, 386, 'Toki Tori 2 is often described as a Metroidbrania, which is why I decided to give it a shot. And I can totally see why—it fits the mold if you define a Metroidbrania as a game where progress comes from gaining knowledge rather than abilities.\n\nIn other words, from the very beginning, you have everything you need to go anywhere—you just don''t realize it yet. Take the starting area, for example: you begin next to a high cliff, and since the character can’t climb, you naturally head in the opposite', 'Charming puzzle game with clever mechanics, but with too slow pacing and missing features', 'Very Positive', 84.72, 13.13, 1.77);
INSERT INTO reviews VALUES (1304, 201480, 309, 'It''s recommended ONLY for SS fans like me who want something new in our beloved universe, For others it''s not good place to get familiar with SS series, better go dive in two very first games: SS Classic: TFE and SS Classic: TSE.', '\nForget about furious running and shooting this is RPG Sam... Walk around the map and fight some random encounters. Gameplay is somewhat turn based and each action takes one turn. You can choose between shooting, swapping weapons or using an item. While in action phase you''re able to dodge incoming enemies and bullets by going up or down. Music feels a bit melancholic but it''s not the main con. What drives me insane are encounters which happen too frequently. On top of that gameplay gets repetit', 'Mixed', 44.34, 1.88, 5.47);
INSERT INTO reviews VALUES (1305, 201490, 240, 'been playing this game for many many years, always fun', 'why iam forced to create account before lunching game? i already pay you money, i dont want another spam on my email from you.', 'Very Negative', 18.75, 9.98, 28.05);
INSERT INTO reviews VALUES (1306, 201510, 1278, 'at least it''s better than overwatch 2 lol', 'Game is shit a bought it just to help a friend with a multiplayer achievment', 'Very Negative', 18.62, 1.02, 0.08);
INSERT INTO reviews VALUES (1307, 201570, 150, 'Really Hidden Gem', 'This is an amazing game. Played it a while back, maybe +10 years ago.\r\n\r\nIn an attempt to re-visit this game with my daughter, I''m unable to play it, as it seems to launch, but only get a black screen.\r\n\r\nWould recommend in 2025 if this game would launch and was playable.', 'Mostly Positive', 70.00, 12.30, 5.22);
INSERT INTO reviews VALUES (1308, 201790, 5931, 'A masterpiece, Orcs must die 2 took everything about the first game and turned it up to 11. More maps, more characters, more ways to slay orcs, multiplayer, cleaner graphics. The original was great, this here is what I would call a nearly perfect game for what it wants to do, its a super fun tower defense game that is accessible even to people who have never played tower defense games before. Its best enjoyed with a multiplayer partner, but can absolutely be enjoyed solo. Its a game that is just', 'According to wireshark game attempts to communicate with steam network service via ports that steam network service locked somewhat recently.\nIs understandable, game seemingly picks a random port from a very wide range.\nIn layman''s terms, coop is no longer functional and it''s extremely unlikely it will ever work again.', 'Very Positive', 92.02, 23.67, 0.55);
INSERT INTO reviews VALUES (1309, 201810, 23645, 'In real world where social media owning scumbags throw up Nazi salutes, play this fantastic game where you can give them the good ol'' G.I. Robot treatment.', 'The game itself is fine but there are a ton of technical issues. Game is locked to 60 FPS, audio is extremely low even at max settings, nauseating head bob and screen shake that cannot be turned off, and worst of all the game hard crashes frequently requiring a full system restart and does not seem to play well with AMD hardware. I would love to play this game, if only it worked.', 'Very Positive', 89.81, 30.97, 1.05);
INSERT INTO reviews VALUES (1310, 201830, 736, 'https://steamcommunity.com/sharedfiles/filedetails/?id=364763806\nhttps://steamcommunity.com/sharedfiles/filedetails/?id=716769523\nhttps://steamcommunity.com/sharedfiles/filedetails/?id=370357645', 'Many of the QTEs are horribly bugged.', 'Mixed', 67.66, 8.12, 1.18);
INSERT INTO reviews VALUES (1311, 201870, 5605, 'Back when Assassin''s Creed was Assassin''s Creed. Badass characters, beautiful city, amazing story, great soundtrack.\nI wish Assassin''s Creed games still had this spirit. Nowadays it is just A$$a$in''$ greed.', 'Ubisoft, in their infinite, never-ending profound fucking idiocy, deleted entire segments of this game when they wiped out all the defunct multiplayer content. Important, story related content is now inaccessible, namely the "Lost Archive", and the Animus Island Desmond restored memory segments. Naturally, they have no intention of ever fixing their error. Watching this unfathomably incompetent company go down in flames in the upcoming years will be a hollow victory, but one I''ll savor nonethele', 'Very Positive', 82.02, 7.38, 116.82);
INSERT INTO reviews VALUES (1312, 202070, 116, 'GET TO DA CHOPPA!!!', 'It seems petty to downvote a game that''s delisted and not even available for sale, but holy **** is this game unnecessarily unfair. Even on normal, the game expects perfection on every stage. Perfection, as it throws endlessly respawning RPG soldiers, entire walls of AA cannons, EMP snipers, multiple tanks, and swarms of jets... usually while you''re trying to perform a pick up.\r\n\r\nScoring is inconsistent, too. Sometimes you''ll 5 star a stage on your first try, just flying through and not caring ', 'Very Positive', 84.48, 3.13, 5.10);
INSERT INTO reviews VALUES (1313, 202130, 251, 'Very cool game with funny comedic plot where you can control dungeon development and multiple minions. Make raids, protect your dungeon from intruders, expand dungeons, do missions and attack various beings on your conquest. Unfortunately, can crush and kill your quick save making you start a chapter over, but main save didn’t suffer.', 'I was enjoying this game, right up until the puzzle with the colors and the switches. I have memory issues from a TBI, so when the advisor gave me the clues, I wasn''t able to memorize them so I could solve the puzzle. I didn''t realize I''d purchased a memory game and wouldn''t have spent money on this had I known the developers put these types of puzzles in their game. Sure, I could google the solution, but the issue is how early it showed up; there''s bound to be more of these types of puzzles. As', 'Mixed', 43.82, 15.15, 15.08);
INSERT INTO reviews VALUES (1314, 202170, 6063, 'A gaming website I used to use is apparently shutting down so I''m going through my old posts to see if there''s anything I want to archive, below is a comment I made about this game there about 11 years ago, with an added caveat at the end:\n\nPeople need help with achievements. Firstly about safes . I stayed on the map 1 safe. He''s in the house Fat . How to get there ? So trying to pass - the gate is closed , and around like no other opportunity to enter . And what is the mission I was nepomnyu , ', 'Amazing game, german low violence version sucks though and doesn''t run properly.', 'Very Positive', 93.81, 54.82, 11.20);
INSERT INTO reviews VALUES (1315, 202200, 783, 'It is 2006, I''m spending my hours playing Gal Civ 2 and Oblivion, life is good.\r\n\r\nIt is 2025, I"m spending my hours playing Gal Civ 2 and Oblivion, life is good.\r\n\r\nBut seriously, this is an old but gold game that recently got an update so it runs on a modern resolution. Fantastic level of customization, the right level of cheese and humor, and it''s dirt cheap. If you''re looking for a space 4x that isn''t Endless Space or maybe Stellaris, this is a great choice.', 'Didn''t really do it for me.', 'Very Positive', 80.20, 43.88, 125.65);
INSERT INTO reviews VALUES (1316, 202310, 545, 'Dont look at it as a Ridge Racer game, it has nothing to do with those. Look at this as another game by the people that made the OG Flatout games and Wreckfest.\n\nDriving is fun, there is lots of action and a nice aesthetic. The tracks are made with the included track editor and the tracks sadly suffer from that. All the tracks feel rather samey and are basically all straights connected by 90 degree corners. Still, this did not hinder my enjoyment.\n\nThe cars feel very Ridge Racer, both in style a', 'T.R.A.S.H.\n\nThe Atari Jaguar has racing games with better controls & physics.\n\nPaid $1.99 on sale and I still feel cheated.  BugBear & their tryhard take on Ridge Racer must be blacklisted for this abomination.\n\nStay away friends.', 'Mixed', 59.08, 6.32, 4.87);
INSERT INTO reviews VALUES (1318, 202530, 1495, 'This game made me contract depression. I lost my job because of this game and I will blame it for my personal shortcomings too. Love you Sega!!! <3<3<3', 'terrible, i have no clue what drove sega to thinking this was a good continuation of... the classics.\n\nits SOOO UGLY the game just looks horrendous, why is sonic only kind of cell shaded. The special stages fucking suck AND LET YOU RETRY THEM IN THE PAUSE MENU BUT NOT WHEN YOU FAIL ???? The homing attack feels so awful WHY DO YOU BOUNCE OFF SHIT\n\nYou can''t even say the music saves it like other sonic games, it all sounds the same...\n\nthat final boss drove me to sui', 'Mostly Negative', 38.26, 38.87, 2.98);
INSERT INTO reviews VALUES (1319, 202670, 235, 'I did enjoy this game even if it wasn''t as groundbreaking as I thought it''d be after such a long wait for it''s release. The graphics were marginally better. I still had a lot of fun with the puzzles, getting to know the different characters, seeing Bess and George in person, and exploring River Heights. The town was SO crazy to turn against Nancy like that. I would say scare factor was like 1/5 and overall game play 3/5.', 'This is my second Nancy Drew game after playing Danger on Deception Island as a kid, and unfortunately, it doesn''t really compare. In Alibi, having to switch between characters was really tedious, there were repetitive interviews, and not as many puzzles/mini-games as I would''ve liked. I don''t understand why there was a massive map with rabbit hole locations when you end up spending the whole game at 4 locations. Feels like an attempt to deliberately waste my time and make the game feel longer r', 'Very Positive', 90.64, 6.27, 5.68);
INSERT INTO reviews VALUES (1320, 202690, 138, 'I bought this game''s hard copy as a 14-16 year old like 15 years ago at Gen Con.  At the time, I was starting a life-long interest with ancient history.  This game was an INCREDIBLE part of my early development, and I went on to study Classical History at University.  During that time, I learned just how painstakingly accurate, beautiful, and incredible this game is.  Phillip of Macedon - as I and the game devs agree - is far more interesting than his son, Alexander the Great: a self made man, a', 'shit it doesnt work on windows pc and when it does its very slow', 'Very Positive', 94.93, 0.22, 286.12);
INSERT INTO reviews VALUES (1321, 202710, 580, 'What an old, clunky, strange take on a MOBA - it''s dated, slow-paced and charmingly ugly, but for all of those reasons I love it!\nForget playing against people, you''ll have to make do with bots but even so, it''s a lot of fun. The different characters are unique enough that you''ll have a completely different play-style according to whomever you choose, and it takes some real practice to master each of them.', 'The game Does not work and there is no fix. \nyou cant create a Stardock account because there site is down and has been down for quite some time.\nthere is no fix there is no work around.\nthe game is 100% unplayable without a Stardock account.', 'Mostly Positive', 73.28, 58.93, 0.32);
INSERT INTO reviews VALUES (1323, 202750, 3001, ' American Nightmare shifts from the classic horror of the original AW1 to a psychological action thriller, delivering an engaging narrative. With its layered storytelling, nightmarish time-loop structure and unique narrative style... it creates an intense and captivating experience. ', ' BORING and LAZY  \nYou can literally just run through the entire game and the enemies will never bother chasing you down', 'Mostly Positive', 74.98, 9.37, 2.43);
INSERT INTO reviews VALUES (1325, 202970, 11390, 'NOT WORTH THE $$$$ today, should be worth 10 or less, servers are dead and its crazy how greedy activision is.\n\nmay be a lengendary game but its long past now', 'Classic game but greedy Activision keeps it at full price a decade later', 'Very Positive', 84.76, 9.62, 1.22);
INSERT INTO reviews VALUES (1326, 202990, 3909, 'Besides the weird issue of joining a server with ludicrous ping for no apparent reason or the frustrating random disconnects. It''s still Bo2, with the addicting gameplay loop of older cods, with a great campaign and one of the best zombies experiences to date. The game is worth picking up for $19.99 on a Steam sale.', 'Trash game, all the guns deal zero damage when hip-fired. More specifically, hip-fire spray is extremely inconsistent even from point blank range. As others said, public lobbies are in a terrible state at the moment. I would rather play Overwatch for 6000 hours straight, study all the characters'' feet, and O/D in the process. 0/10 bo2 fell off...', 'Very Positive', 92.50, 59.97, 12.97);
INSERT INTO reviews VALUES (1327, 203140, 11926, 'So, Hitman: Absolution is a third person stealth-action game but to me it felt more as an modern shooting game not stealth game which it should have been.. moreover the game''s linear story-play was very bland which was not at all interesting to play. The game''s intro was pretty good and would make one feel as if they are in for a banger but little did they know that just after 2 missions the whole point of the game would be to go from one point to another and just kill one person with little to ', 'Removed the online contracts game mode without removing the achievements making 100% unattainable. \n\n(edit: You can self host a server, but why even shut down the better part of the game, still leaving it negative for being planks.)', 'Very Positive', 87.19, 21.63, 19.58);
INSERT INTO reviews VALUES (1328, 203160, 46942, 'The end credit started with,\n "We hope you enjoyed playing Tomb Raider. We have worked our hardest to bring you the best game we could possibly make. Thank you for taking time to complete our game." \n\n This is exactly what is missing from most of the modern game dev companies. They have no passion for their games and the game companies don''t even care about creating "the best game they can possibly make". They are just busy forcing crappy propagandas and microtransactions with their games. \n\nThi', 'I have put 13 hours into this game. All this time is me trying to replay this game in the hope that I will enjoy it, Unforrtuneately I just can''t get into it.', 'Very Positive', 94.37, 30.02, 13.03);
INSERT INTO reviews VALUES (1329, 203210, 387, 'Ye. :D\n\nWell, was fun in 2012. ;D', 'A variant of Alien Invaders with some form of progression in it. You can build and upgrade your tank in a few ways, but you don''t have a lot of different playstyles to go with. The game is a score attack game, so if you are into that you might enjoy it. However, the gameplay is basic. Also, when you play the game you probably want to disable the blurring and special effect, as they only obscure you vision... But even then, this game grew boring really quickly on me, so I cannot really recommend ', 'Very Positive', 92.25, 2.15, 2.00);
INSERT INTO reviews VALUES (1331, 203350, 362, 'The whole first ''King''s Bounty I'' games are lots of fun, lovely graphics, fun writing and loads and loads of TBS fights and quests. I just bought the first in the series because I liked the graphics but after finishing them I bought the others too (so in all ''Armored princess'', ''Legend'', ''Crossroads'', ''Dark Side'' and ''Warriors of the North'' this last one I''ve played for the largest part but not yet completely finished ).\n\nThis game is a bit buggy so save regularly (sometimes it crashes while doi', 'well i completed this game 100% just because its a kings bounty and i love this series but this game got to be THE worst kings bounty (not counting 2) the story didnt interest me at all even after 120 hours it was basicly pain playing and the amount of crashes i got completly randomly is uncountable. if you are a hardcore kings bounty fan you might want to catch it bc only dark side and this one have steam achievements. if youre a normal sane person please play crosswolrds/Armored Princess inste', 'Mostly Positive', 75.97, 536.15, 127.40);
INSERT INTO reviews VALUES (1332, 203510, 525, 'Played dark souls. This game was actually harder. can''t shake of the shame of getting beaten by lolis.', 'I really hate to say that I don''t recommend this game. The pixel art is crazy stupid good in this and it''s very nostalgic of early japanese games. I researched and found that the developer Lizsoft was a doujin company or basically it''s like a fan-made game? There was a name mentioned in the credits who seemed to have done the majority of the work, but I couldn''t find anything about that person online.\n\nThe game falls short in the controls, it just doesn''t feel responsive enough. However, I could', 'Very Positive', 82.86, 17.17, 0.63);
INSERT INTO reviews VALUES (1334, 203630, 629, 'I have enjoyed playing this game for quite some time and I can tell you that you will enjoy it too. Have fun.', 'Feels like a cheap mix between CIV and HoMM. On the surface it looks very interesting, but no. Wasn''t that good several years ago and by today''s standard, it''s low tier in the genre', 'Very Positive', 86.33, 3316.28, 12.78);
INSERT INTO reviews VALUES (1335, 203650, 851, 'Tails You Fat Turd Lift Me Higher!', 'its better than sonic 4 ep 1. \n\nbut that not saying much.....\n\njust get like any other sonic game like the new sonic generations.', 'Mostly Positive', 72.62, 0.30, 11.37);
INSERT INTO reviews VALUES (1336, 203750, 1681, 'Hard to believe that SEGA hasn''t made a sequel already, this game is good, runs good, and looks good from beginning to end.', 'takes almost 1 hr to setup controller , and still doesn''t work with controller some main bindings are not work,vibrations are also doesn''t work. even sometimes you cannot play with mouse and keyboard don''t waste your money in this one.finding numerous results on internet but none of those are worked,i brought this because i see his style is like gears of war but this game inputs are very bad maybe gear of war is gears of war none of game take his place.', 'Very Positive', 84.83, 20.93, 1.37);
INSERT INTO reviews VALUES (1337, 203770, 22296, '>i serve the hre loyally for generations \r\n>my rulers provide quality service on the emperor''s council, well liked by nearly everyone, one of them became a saint\r\n>i help defend southern italy from the byzantines and muhammadians\r\n>a syphilis ridden lunatic revokes all of my titles and no one comes to my defense\r\n\r\n10/10 game', 'So far the game is complete garbage.  Can''t play for more then a few hours before some over powered computer empire just comes along and wipes me out cause I am basically prevented from raising an army because I am not allowed to increase my levy size.  Completely unplayable when your slightly larger neighbor can raise an army 2 or 3 times the size you can and there is completely nothing you can do about it.  Will not be buying CKIII or any of the DLC''s for CKII.', 'Very Positive', 92.84, 294.33, 291.25);
INSERT INTO reviews VALUES (1338, 203830, 778, 'kinda meh, but I guess I''d still recommend it compared to not recommending it  \r\n  \r\nthe option to highlight interactions really helps a lot if you''re stuck, and you can just use the mouse wheel to move through the inventory    \r\nyou could also turn it off if you don''t want it', 'Graphics, audio and general story are ok (esp. if you know thr RPG).\r\n\r\nBut: Most puzzles are boring, with lots of running back and forth.\r\nAlso, solutions are often unrealistic - trial and error sometimes works better than logical thinking.\r\n\r\nBuy it for a story in the world of The Dark Eye, but don''t buy it if you are looking for a good point-and-click adventure.', 'Very Positive', 84.19, 7.45, 13.38);
INSERT INTO reviews VALUES (1339, 203990, 122, '''Roger Wilco''', 'This is actually mostly okay, but it has some annoying QoL problems that keep me from wanting to keep pushing with it.  \n\nNamely; the second boss that just killed me.  It left the screen, but then at some point returned to the screen, killing me instantly, leaving me no alert that it was coming from X direction.  It''s basically a gotcha! trap.  An I wanna be the guy moment.  \n\nI have already attempted to get into another game from this same dev: Zangeki Warp and I dropped that one quite early to', 'Very Positive', 83.61, 7.80, 0.18);
INSERT INTO reviews VALUES (1340, 204030, 4103, 'I fucking love this game. I''ve played it so many times that I know the layout of Albion better than the layout of my own house. I can''t even begin to review this game objectively: just buy it. As of 11/06/2024, it''s £2; that''s less than a coffee.\n\nAlso there''s some really good overhaul mods (one of which was made by me) for once you''ve played through it once/played it to death.', 'Big fan of the game back on the OG Xbox and I''d happily recommend that.\nThis version however, doesn''t support controllers at all. That alone kills my recommendation for this version.', 'Very Positive', 90.74, 270.53, 9.53);
INSERT INTO reviews VALUES (1341, 204060, 939, 'Sword and Sworcery is an interesting game to come back to all these years later after I initially played it on mobile when I was a child. On the one hand, the graphics and soundtrack are still beautiful, and overall I would say I enjoyed the experience- on the other, it''s MASSIVELY dated in some places. Some of the lolsorandom and early 2010s-era hipster humor dialogue makes me want to actually die, and though this can''t be helped since it was initially designed for mobile, some of the moment to', 'I couldn''t get into it which was disappointing considering the other reviews. Maybe just not my thing.', 'Mostly Positive', 79.77, 3.03, 0.67);
INSERT INTO reviews VALUES (1342, 204100, 21707, 'Max Payne 3 is the greatest 3rd person shooter of all time, the combat and gunplay are unmatched to this day. Wish we would get Max Payne 4.', 'game is decent,however issue i have is with this dogshit of rockstar launcher,why every companny thinks they can make their own buggy launcher and force people to use them,doesnt work nor they really try to fix it,launcher is more anoyying than game is fun at this point so i will just give up on game and refund it i cant even run it because launcher isnt working,i hope same happens to rockstar that did with ubisoft at this point,too much bs presented and anyone who played rockstar games will tel', 'Very Positive', 84.40, 16.53, 0.35);
INSERT INTO reviews VALUES (1343, 204120, 922, 'Another nostalgic game done! Like the first Lego Harry Potter, disappointed that they''re aren''t any steam achivements, even though both games have them on Xbox One and 360. But other than that 10/10 game.', 'stutters and drops to 30 fps. dont waste your money on this piece of s**t', 'Very Positive', 88.07, 27.12, 0.83);
INSERT INTO reviews VALUES (1344, 204180, 745, 'Unique gameplay\nTry it if you want to challenge yourself', 'It''s a reasonable idea for a pick-up-and-play game, but you''ve seen all the game has to offer after just a couple of levels. And it doesn''t take long to realise that the execution of the idea is flawed in that there''s no point trying to think ahead as whatever you try to do in preparation will screw-up the path you''ve laid directly in front of your cursor. \nIt''s not intuitive; you never really get used to how you need to move in order to create the wave shape you require within the half a second', 'Very Positive', 81.61, 76.10, 0.80);
INSERT INTO reviews VALUES (1346, 204240, 1226, 'https://steamcommunity.com/sharedfiles/filedetails/?id=303931164', 'I eventually give up to walk through the game, I finally admit 4.6 Archway nonsense. \n\nA hard puzzle is a thing, a stupid-designed puzzle requires almost hacking and ultra-lucky action timing is another thing.\n\nNot recommended, it''s a pity for the great art style and gravity inspiration.', 'Very Positive', 85.24, 9.13, 4.65);
INSERT INTO reviews VALUES (1347, 204300, 6912, 'With the talks of deadlock going around and stuff, I was reminded of this childhood favorite and went back to see if it was still kicking. Unfortunately, it''s not. Turns out the devs behind it went bankrupt last year and the official servers are down. \nThe game is still playable online through an old build of the game in the beta tabs, an old build that goes back to 2016. Fan discords and third party que systems are in place to make matches possible. It''s just such a shame that there''s so much c', 'This game used to be incredible, however with such a small, isolated community comes toxic players.\n\nThis game is unapproachable for new and returning players, as the bots do not offer a significant challenge and matchmaking lobbies are filled with players who have simply been playing the game longer than you. There is no skilled matchmaking, so picking up and learning this game is just not worth the mental effort.\n\nSadly, Atari won''t be able to revive a game reliant on its online, when new play', 'Very Positive', 84.71, 400.32, 313.72);
INSERT INTO reviews VALUES (1348, 204340, 3024, 'Really wish they''d remake this game or make another cartoony Serious Sam. I''m tired of 3-4''s realism artstyle.', 'Game profiles are not saved. Steam Cloud is not working. Fix it all please. \nAnd I''ve been waiting for an update for years, since 2021, please release a new update!!', 'Very Positive', 86.94, 3.85, 42.62);
INSERT INTO reviews VALUES (1349, 204360, 40358, 'Castle Crashers is, always has been, and forever will be the greatest thing ever produced. Masterpiece.', 'Extremely shallow combat.  *Extremely* shallow.  99% of the game is just button mashing the attack.  Double Dragon for NES had more moves than this game and it came out over twenty years earlier.  Despite that, Castle Crashers is very fun at first, especially with friends, but the game gets very old very fast due to stupidly simple combat mechanics.', 'Overwhelmingly Positive', 96.95, 73.42, 4.38);
INSERT INTO reviews VALUES (1352, 204450, 9231, 'Super fun classic FPS! Great narration throughout the story, and a sweet ending. The gameplay is also good and feels very satisfying.', 'There''s some great aspects to this game, but you can''t run it with a modern CPU without going into task manager and manually disabling CPU cores everytime you want to start the game.', 'Very Positive', 94.58, 12.52, 3.00);
INSERT INTO reviews VALUES (1353, 204530, 1825, 'It has potential, it''s fun for a short while, then it gets very repetitive, it could have more customizations for the marines, etc., in modern times a co-op against the PC would be fun!\n\n================\n\nTem potencial, é divertido por um curto tempo, depois fica muito repetitivo, poderia ter mais personalizações dos marines e etc, nos tempos modernos um coop contra o PC seria divertido!', 'Hard difficulty is honestly unplayable. Even with flak cannons, maxed mini guns, and several turrets. You cannot do anything in the game. Soon as you gain a checkpoint, you lose another. The game is insanely interesting but, the difficult spike is literally impossible. How are people expected to move forward if you cannot literally move forward? There is no strategy the game has to offer that allows you to be flexible. The waves are endless, the soldier spawns are consistent, and the damn infest', 'Very Positive', 94.68, 12.87, 22.85);
INSERT INTO reviews VALUES (1356, 204630, 1076, 'I played this back in 2014. It was meh back then, and it''s still meh today. A barebones GTA with 80s references.  After completing the story, there''s not really much to do. Side missions are available. Buy the game on sale. Your mileage may vary. Either you''ll enjoy it, or you''ll refund it within 2 hours.\r\n\r\nRating: 7/10', 'I bought this hoping to relive some gaming nostalgia, as I originally played this on the PSVita. Fortunately, I was instantly reminded why I didn''t play it as much. Overall, I want to like this game; I really do (as it reminded me of GTA 2), but It just didn''t hit the same. The gameplay just sucked; I even tried playing on my SteamDeck, which changed nothing at all.', 'Very Positive', 87.73, 8.72, 0.08);
INSERT INTO reviews VALUES (1357, 204860, 147, 'Cool Real Time Strategy game. Not much of a play-again game, because no matter what you do you have the same outcome usually.', 'Your gun won''t hit an enemy right in front of you, enemy''s gun can hit you 100m away.', 'Mixed', 68.03, 19.95, 0.40);
INSERT INTO reviews VALUES (1358, 204880, 7196, 'One of the best real time strategy games ever made. If you love RTS you have to try it. Still eminently playable in 2025, it doesn''t feel dated at all.', 'I like it. but it disables alt-f4, so when I''m getting my ass kicked by the AI there''s no rage quit option.\r\n\r\nI always thumbs down games that disable alt-f4.', 'Very Positive', 94.64, 660.93, 66.53);
INSERT INTO reviews VALUES (1359, 204940, 105, 'I played it to the end and I enjoyed it, so I can''t in good conscience give this a thumbs down. But it''s definitely a game showing its age, and there is not much of a reason to play this over CK2 or CK3, unless you''re curious to see where the series began.', 'Crusader Kings is a grand strategy title from 2004.  The systems are very complex and there is no tutorial!  I found the manual online and read through it, but still found this a very difficult game to get into.  I had no idea what I was doing, and managed to flounder around for a couple of hours in order to try and figure it out, but it was just too much hard work!  I''m going to try Crusader Kings 2 to see whether I get on any better with that.', 'Mixed', 59.05, 88.23, 2.00);
INSERT INTO reviews VALUES (1360, 205020, 333, 'Still worth playing in 2025. Perfect handmade design.\nPlayed before on other device but I have to say that it''s better on PC.', 'Hours:Price not worth it as I got <6 hours. I did use the hint book on a couple puzzles, but I think I also sat there dumbfounded for an equal amount of time. The graphics are really cool. The game crashes a lot and depending where it crashes you''ll have to repeat puzzles, and I don''t think there''s a manual save option.\r\nSome of the time I spent not knowing what to do was because I clicked on something that I needed but it didn''t register so I thought it wasn''t usable.', 'Very Positive', 85.89, 5.20, 5.73);
INSERT INTO reviews VALUES (1364, 205100, 36613, 'RIP Viktor Antonov... Your work made us discover the beauty of Dunwall which still remains one of my favorite places in a video game.\n\nThanks for everything.', 'ZeniMax joining the "slapping EULAs onto old games" trend with an updated agreement that: "includes my express consent to ZeniMax’s use of Anti-Cheat Tools as described herein", and claims; "The Game is a Service offered by ZeniMax and is only playable online."\nAcquire Dishonored elsewhere, Steam is happy to let these companies bloat their old games with malicious DRM.', 'Overwhelmingly Positive', 97.40, 46.20, 134.77);
INSERT INTO reviews VALUES (1365, 205230, 284, 'Indie classic. This game came out when indies where becoming a thing, the bloom can be too much, I get it. But I think it has everything an indie should strive for at it''s core, nice gameplay, and funny jokes', 'Played this game on and off since its release, just beat it, and let me say, its not worth it. very obnoxious floaty controls, the whole warioware kill gimmick facilitates a bunch of shitty bullet sponges. There are ton of weapons but very few enemies worth using them on. Stylish i guess, but man why did i need to finish this game?', 'Mostly Positive', 79.58, 2.90, 9.10);
INSERT INTO reviews VALUES (1370, 205610, 554, '⠀', 'Compared to Port Royale 2, which is very good, this Port Royale 3 has much more difficult naval battles, info on enemy ships too low, automated battles option always loses, your automated ships are non-intelligent and hopeless at Naval battles, will always lose, unless controlled manually. I would have expected a "Nr. 3" to be better than "Nr.2" but sadly no, only grafics and some "easier trades" are implemented, while making the naval battles much worse.', 'Mostly Positive', 70.22, 4.97, 9.92);
INSERT INTO reviews VALUES (1371, 205650, 1108, 'It may not be perfect or groundbreaking, but it’s an adventure game with a surprisingly engaging story. If you''re a fan of the genre and can overlook some clunky controls and dated visuals, it''s a solid experience worth checking out.', 'It was almost ok. \r\nI did finish it, so it was enjoyable enough for me to do so, but half of the story is incoherent, the movement is frustrating at times (you move through corridors with similar backgrounds, but when you move from one screen to another the directions invert and you lose orientation. That happens a lot).\r\nThere were some nice riddles but some that were tesious or annoying.\r\nSherlock himself is the least likeable that I met so far in this series of games.\r\n\r\nIf you like the previ', 'Mostly Positive', 76.26, 9.62, 12.73);
INSERT INTO reviews VALUES (1372, 205690, 108, '1000 Amps is a neat little, overlooked, puzzle-y metroidvania. Definitely worth a look for fans of the genre.', 'exploration puzzle platformer\nSteam Deck: Playable, but pretty much requires an external mouse\n\n*sigh*  This game.  I wanted to like this game.  A metroidvania without guns and an interesting sound design.  Heck, I wanted to LOVE it.  It''s a really interesting idea.  Sure, the level design can be weak, being VERY fond of unrecoverable falls that make you go the LONG (really, really long) way around to try again.  And the controls can be a bit wonky.  But there was a steady feeling of progress an', 'Mostly Positive', 77.78, 1.88, 7.35);
INSERT INTO reviews VALUES (1374, 205730, 398, 'It''s a small game with a cool and beautiful art style, featuring unique gameplay with quirky creatures and eerie backgrounds.\nA small game. A small flying saucer game. A small hidden gem-like game.', 'not metroidvania, adventure, or exploration. This game starts strong with these elements, but after the first zone it gives up on all of those elements and becomes a walking-simulator with nice environments but zero challenge except for a periodic boss fight. The powerups aren''t useful: you improve your blaster by collecting 1, 3, and then 5 powerups, yet your blaster isn''t your main weapon in many situations. Other collectibles have zero gameplay: art and videos. The game ends on a whimper, I f', 'Very Positive', 87.94, 8.62, 5.83);
INSERT INTO reviews VALUES (1376, 205830, 106, 'Fun, engaging and challenging. I don''t like the lack of post game content though. Luxor 3 had a puzzle mode, free play & endless levels. Even with Evolved''s lack of post game content, I did find it fun.', 'The gameplay is, well, Luxor (which is a good thing!), but the graphics give me a headache and a half.', 'Overwhelmingly Positive', 98.11, 42.63, 29.87);
INSERT INTO reviews VALUES (1377, 205840, 358, 'Yesterday was a lot of fun, but it passed too quickly!', '60/100\n\nA decent experience for a thrifty price. This game is a simple point and click adventure with the unusual treat of good attempts at story and characterization. I think the story itself might have been best served as a graphic novel for its linearity and also because it feels a bit incomplete. With gameplay functioning on logic, any off-the-cuff elements that betray the atmosphere of a certain location or puzzle always lead me to think that something was lost in translation, or could have', 'Mostly Positive', 79.89, 3.32, 7.52);
INSERT INTO reviews VALUES (1379, 205910, 1614, 'Its been a decade since I bought this game and I still think about it from time to time. Great game give it a play.', 'Fun game but....\r\nThe game is prone to crashing and not only that it can crash the Steam itself. I had to force restart my PC entirely.\r\nNot gonna risk my PC for any game specially small and non optimized ones.\r\nSo play at your own risk', 'Very Positive', 91.95, 1.05, 2.43);
INSERT INTO reviews VALUES (1380, 205990, 619, 'This game needs to be released with a current update with current technology. The fact that Paradox Games released this program with an editor included really opens the game up to managing everything from Papyrus to almost anything you can imagine. Great game with versatility and a crap load of fun.', 'This game is in many ways a good game and there are many reviews on this game that don''t do it justice. Monsters and magics are fun, with many interesting and enjoyable additions since the first game. Many of the game play elements are just as good. Things like the city limit were, at least from my own opinion, a good addition as well. Removing tedious gameplay at the late game.\n\nWhat this game did wrong is the very thing it sold itself on. Having multiple traversable worlds. It took an open wor', 'Mixed', 64.62, 753.98, 122.42);
INSERT INTO reviews VALUES (1384, 206190, 8088, 'Now you''re thinking with wires.\n\nI''ve had this game in my library for a long time (at least a decade, sheesh) but never got around to fully experiencing it. Like other reviewers have mentioned, it''s a short game, and the puzzles never really get too complex, but it has just the right amount of humor and subterfuge shenanigans to balance out its shortcomings. The story is decently intriguing, pokes fun at itself and various tropes, and makes neat references to old detective fiction. Some of your ', 'Stop reading negative reviews and buy this game!', 'Overwhelmingly Positive', 97.80, 8.28, 5.42);
INSERT INTO reviews VALUES (1387, 206370, 204, 'العاب السينو ثلاثه رايقه و ما فيه زيها', 'Хуйня ебаная, в рот а-а-а делал разраба, слишком сложная', 'Overwhelmingly Positive', 95.10, 2.32, 4.00);
INSERT INTO reviews VALUES (1389, 206420, 23091, 'OMG you can get a handjob from a robot. gg 10/10 \nRight click saint row the fourth, go to properties, select betas and select legacy you will thank me later\n\n', 'as of april 2025, by default, epic games online services gets installed automatically.\nEDIT: you can play legacy version without epic games services, look in the game properties', 'Very Positive', 84.28, 5.18, 33.73);
INSERT INTO reviews VALUES (1390, 206440, 18456, 'There are no good graphs, no good gameplay, but there is a touching story，its enough for this game.', 'Played in English (NOT IOS/Linux) and after 4 times completing the end of the game the achievement still will not work.', 'Overwhelmingly Positive', 95.65, 8.35, 6.47);
INSERT INTO reviews VALUES (1395, 206760, 121, 'It''s not really a bad game even though it''s broken in a lot of places, it''s just derivative of the other Painkiller games and kind of pointless. First off, don''t play on the hardest difficulty because you can get soft locked because of a fatal error and it will overwrite your save. Beyond that, close the game and restart it if the map gets all screwy and stops functioning properly, and the game runs OK. \r\n\r\nThe whole key to the Painkiller franchise is just to overwhelm the player with enemies an', 'Yet another lazy mod with the same assets as the original game trying to pass as a separate game. The same gameplay as Redemption, yet twice as expensive... If it isn''t on a 80%+ sale, why would you buy this? o.0 \nJust... why? Were these made by some obsessed Painkiller fans who play nothing else?', 'Mixed', 43.80, 12.00, 0.13);
INSERT INTO reviews VALUES (1397, 207020, 155, 'To be so small and simple looking, very challenging and intense small races that are really fun! A 3 minute race can end up forcing you to focus and you end up with a sigh of relief at the end of it when you win!', 'game doesnt start anymore....', 'Very Positive', 81.94, 7.47, 17.72);
INSERT INTO reviews VALUES (1398, 207040, 281, 'The gameplay is nice: a combination of R-Type and friends'' "they are actually shooting at you, dodge them" enemies interwoven with bullet-heck mechanics. Speaking of mechanics, the game mechanics are a lot of fun - and speaking of R-Type, the game gives you a nice variety of ships to play around with. Several game modes, from story mode to arcade to boss battles; it definitely strives to keep you entertained, and it even provides a low difficulty mode for people who might approach this sort of s', '3/10\r\n\r\nEuroshmup slop. Very pretty art, but that''s mostly it. The amount of downtime in the game is ludicrous and it lacks any interesting patterns or tight/consistent mechanics.', 'Very Positive', 83.63, 0.35, 0.33);
INSERT INTO reviews VALUES (1399, 207080, 602, 'A decent and intriguing documentary about how making video games makes you mentally ill. \n\nMy condolences to all indie devs that suffer from video game making. <3', 'This movie showed that indie developers are not strong passionate people but maximum freaks and crybabies, with Fez not age well at all (watch the video - Phil Fish: Gaming''s Most Hated Developer), in fact everything is much simpler, do not take movies like this as the reality of game development, better just listen to different real developers on youtube or talk to the developers directly', 'Overwhelmingly Positive', 95.35, 2.23, 7.15);
INSERT INTO reviews VALUES (1400, 207140, 9495, 'Most underrated party game out there. Actually 2D Mario Kart. If you''re doubting whether to buy this; just buy it.', 'crashes constantly. very embarrassing for me i looked like a fool in front of all my friends. Unbelievable.', 'Very Positive', 94.60, 4.53, 0.87);
INSERT INTO reviews VALUES (1401, 207170, 3153, 'Not sure why the recent reviews are mixed, this is a great game. A bit obscure at times with its puzzles, and a little clunky by modern standards, but still a fun game. Seeing as one of the recent negative reviews is "How the ♥♥♥♥ attack in this game? Non key works." when the game TELLS you that all you need to do is right click to attack, I can only assume the negative reviews were left by morons.', 'Can''t recommend this, and I''m almost 50 years old and played Eye of the Beholder when it came out.\r\nIt''s just an extremely player hostile game, the designers seemed to think "old school" means "obtuse". It''s not 1984 anymore, tell me how to play your game and let me fix character mistakes.\r\nI got to level 3, it was a dumb gauntlet of getting attacked by spiders. As an old pro at Eye of the Beholder I knew how to loop them around and slant fights in my favor - then the designers started forcing m', 'Very Positive', 92.61, 15.97, 3.93);
INSERT INTO reviews VALUES (1404, 207250, 226, 'One of the first games I ever bought on steam, very simple concept and was fun to play when I had some free time.', 'I had a blast playing this, it was a blast as it blew up my windows 98.', 'Mixed', 69.47, 6.83, 5.82);
INSERT INTO reviews VALUES (1405, 207320, 1166, 'I don''t remember playing this game for 105 hours but I was still drinking in 2012 so it''s hard to say.\n\nI am going to start this game again now.', 'This game is an absolute turd. Skip it. The boss fights come down to a simple enough pattern but you must repeat the same janky animated combat pattern over and over and over and over for 10-15 minutes because they doubled the health pool of a boss. Your deaths from a boss will come from pure boredom. Yes, I was able to kill a boss taking zero damage. So this doesn''t come from a place of "notgud". \n\nYou also have one button combat. So there''s almost zero depth.  I regret getting stuck owning thi', 'Very Positive', 93.48, 105.75, 8.42);
INSERT INTO reviews VALUES (1406, 207350, 1727, 'I don’t know whether to feel happy or a little melancholic now that I’ve finally caught up with most of the older Ys games. As someone who adores old school action RPGs and holds a deep love for the early 2000s era of Ys, I know I’m going to miss the simplicity and atmosphere of these games dearly. I adored Ys I & II, and Oath in Felghana was so addictive that it quickly became one of my all time favorites.\n\nYs games just have a gentle, simple, and nostalgic charm that never fails to captivate m', 'The ugliest and weakest Falcom game I''ve ever played. Boring repetitive maps that forces a lot of backtracking, obscure dated game mechanics, boring lowpoly repetitive rooms, obtuse graphic and terrible control configuration... Another basic port that is slowly fading away for its ancient design and lack of interest in updates.\n\nThe music is great as always in the saga and character design is cool. Maybe the story was good but the gameplay really made me lose any interest in keeping on with this', 'Very Positive', 93.80, 13.52, 4.28);
INSERT INTO reviews VALUES (1407, 207420, 407, 'Arkanoid + Zelda Minish Cap\n\n8/10\n\nI was not expecting to like this game as much as I did, but it was a very nice surprise. I bought it as a Tribute Games'' fan that wanted to try their whole repertoire and soon found myself addicted to this game. While simple, the game is ingenious in the way it works around the usual shortcomings of the brick breaker/breakout/arkanoid subgenre. You have 2 "magic abilities" with 2 variations (one being normal and the other being precision based upon pressing a b', 'Wizorb could have been good, but there''s nothing really rewarding in this game. A few upgrades that aren''t really good and frustrating levels where blocks can''t be broken just made me give up. I don''t recommend this game.', 'Mostly Positive', 75.18, 15.47, 2.22);
INSERT INTO reviews VALUES (1408, 207430, 261, 'A lot of people dislike this game for what I think are missed expectations. If you''ve ever played early PC dungeon crawlers you''d recognize what this game is trying to do, and frankly it does it very well. Hack, Slash, Loot is effectively a turn-based fast paced RPG and has a pretty fun gameplay loop.\n\nWhy do people dislike it?\n\nYou''ll die. A lot.\nThis game is kinda like the new pokemon roguelike mods. This game is based on one of the original rogue-likes. Death is inevitable but the reward for ', 'Global Stats at the time of writing:\n\nTotal Player Deaths - 11276782\nTotal Successful Quests - 16292\n\nThe game is minimal to a fault. It''s not simply that we''re at the mercy of RNG, the whole thing is incredibly unbalanced. You can see from the stats above that having a successful run is incredibly unlikely. Because this is a traditional roguelike (vs a rogue-lite) there''s nothing to be gained from those failures either. Also, the UI is unwieldy and the art is squished. I had many, many deaths m', 'Mixed', 57.47, 4.88, 2.37);
INSERT INTO reviews VALUES (1409, 207490, 2356, 'Probably the last game I bought the way games are supposed to be bought. Randomly went into a GameStop and went “the cover for this rocks, I''ll just get it.” And god does it rock.\n\nRayman 3 was one of the first games I had ever interacted with; I remember watching my dad play it when I was a kid. But Origins is wildly different from 3, and as the name confusingly implies, the game is not a prequel but simply a return to form. It’s the closest a Rayman game has ever come to consistency in the ser', 'Rayman Origins is my favorite childhood game, but running it on modern systems is a nightmare. The boot-up screen is so pixelated that you can count every individual pixel, which is ridiculous ''cause it looks fine on the Xbox 360. The main menu barely functions, and if you unplug a device or even just open Discord - the game crashes.\n\nSo sadly, I’ve gotta say this:\n\nFuck You, Ubisoft.', 'Very Positive', 93.51, 12.08, 1.00);
INSERT INTO reviews VALUES (1410, 207530, 302, 'To this day, the first stage of Noitu Love 2 is the perfect summary about what I personally like about action games. There are too many explosions (which means ''just the right amount'') and it''s just so much fun to blast through enemies. \r\nThe controls may take some getting used to, since you rarely get platformers with mouse aiming and you *could* say that it maybe it has too many special moves, since really you can just get through most of the game, just by punching things.\r\nHowever, having the', 'No controller support. I''m sorry but I just can''t play a game like this with kbm controls. Shame because I liked the first.', 'Very Positive', 93.05, 3.43, 0.27);
INSERT INTO reviews VALUES (1411, 207570, 126, 'It''s a great game. I had a great time playing it, each puzzle is a satisfying and fun challenge.', 'A lot of reviews will say similar things, but I''m going to say this is rough enough to not recommend except to puzzle gods with days to spare. I don''t have the patience to learn these weird systems and put up with this disorienting camera that makes me actually sick. The store page shows pictures of mostly simple puzzles, and nothing in motion to demonstrate the disorienting design and controls. If you are considering this after all these years, check out a walkthrough to see if you are interest', 'Very Positive', 94.44, 20.65, 1.80);
INSERT INTO reviews VALUES (1412, 207610, 22562, 'After multiple playthroughs, it remains one of the best story-driven games. Thank you Telltale.', 'The girl I loved in the game died 10 minutes after I loved her?', 'Overwhelmingly Positive', 96.94, 42.80, 6.97);
INSERT INTO reviews VALUES (1415, 207690, 1923, 'Special thank''s to developers and all people who bought Amanita Design games to support Ukraine.\nrussian angry kids lowered steam rating', 'Bloody hypocrites!', 'Overwhelmingly Positive', 95.42, 4.98, 6.37);
INSERT INTO reviews VALUES (1417, 207730, 156, 'While the singleplayer side of things seems dim and underdeveloped the multiplayer with friends is a huge blast. 1v1 can bring 2 hour wars of attrition or quick sweeps with rush builds that either get crushed with well-thought defense placements or heavy investment for the countering unit(s). Many people are bashing this game for the lack of depth and while the game certainly does lack depth, it can teach a deep appreciation for rts games with it''s handful of interesting mechanics to even someon', 'Three strikes ANNNNNDDDD...it''s out.\n\n1)  Nobody plays this game so If you don''t have friends that play this game you won''t find anyone to play against. \n \n2)  The single player "campaign" is horrible, the computer AI is really exploitable and it''s just really boring.\n\n3)  It doesn''t work for a lot of people and the dev doesn''t support the title anymore so you are pretty much on your own on getting it to run.', 'Mostly Negative', 25.64, 4.95, 6.22);
INSERT INTO reviews VALUES (1418, 207750, 604, 'I had to download another program to make it work, since it''s so old, but that was quick and easy. Symphony is a relaxing rhythm game. It''s simple, but it''s fun and i''m enjoying unlocking different weapons and power ups.', 'It''s innovative, but its polish as a bullet-hell game is questionable, and the music doesn’t integrate well with the gameplay. It almost feels like playing a bullet-hell game with random music in the background.\n', 'Very Positive', 87.25, 1.48, 21.62);
INSERT INTO reviews VALUES (1419, 207790, 227, 'its a w\r\n', 'Jane''s Advanced Strike Fighters is a game with potential that is hindered by its lack of depth and polish. It offers a fun, accessible flight combat experience but fails to stand out in a crowded genre. Casual players might enjoy its straightforward approach, but those looking for a more immersive and realistic flight sim may be disappointed.', 'Mostly Negative', 33.04, 44.75, 5.27);
INSERT INTO reviews VALUES (1420, 207930, 198, 'Not bad, there are some other bugs and balance at times, but nothing serious.\nThe game is quite simple.\nBest with a discount.', 'The game is a fine run-of-the-mill sidescroller RPG, but it''s painfully easy & the Fourth Act has multiple moments that have bugs which make the game unable to continue. It''s unacceptable, and I wish the devs hadn''t abandoned this game.', 'Mixed', 66.16, 6.10, 9.05);
INSERT INTO reviews VALUES (1421, 208110, 164, 'If you''re thinking of buying this, then you''re probably invested enough in the franchise to complete it, despite it being a lackluster entry. \r\n\r\nThe game isn''t lacking in presentation, but its narrative distance from the previous Myst games makes it feel more like a sequel to URU, rather than a main entry in the series. This game is fairly short and its story told through exposition and audio logs, rather than exploration and puzzle solving. It is underwhelming in the areas where prior entries ', 'After entering the first of the four relevant ages, I kept getting the same game breaking bug where that little creature that is supposed to summon the wind kept freezing up so I couldn''t go near it or pick up the stone slate anymore. I had it several times up to the point that I gave up. On top of it, the game just looks lame compared to the other four parts. Even with their dated graphics, they easily outclass this one. Myst 5 looks horrible without real life actors nor does it have any sort o', 'Mixed', 58.54, 3.82, 2.32);
INSERT INTO reviews VALUES (1422, 208140, 4244, 'Not really sure why I can write a review for this game since I''ve never owned it in my life. Hi I guess?', 'This game is broken on modern PCs and you shouldn''t buy it. \n\nShame on the devs for continuing to sell it.', 'Mostly Positive', 78.75, 2.73, 46.30);
INSERT INTO reviews VALUES (1423, 208200, 4881, 'Great game, some of you youngins'' that are comparing this game poorly against Doom 2016 may not realize this game and it''s engine came out approx 20 years ago, it was one of the first games that actually supported a working GPU, supporting Hardware T&L, you may not realize this game was a pioneer with that and in its time, it was very damn impressive.. Of course it won''t stack up to a game that came out over a decade later. That''s just advances in technology for ya, great game!', 'Does not start', 'Very Positive', 84.47, 4.42, 0.10);
INSERT INTO reviews VALUES (1424, 208400, 892, 'I''m still suffering PTSD from this game as I''m writing this, completing a two-week intense playthrough. Don''t let the cute graphics fool you, this game is not for the faint of heart: it is a long and difficult slog, which I think would be fair to describe as a tactical RPG. It is only made that much more difficult as some of the rules are opaque and everything is almost too simple and straightforward.\r\n\r\nIn addition to challenging combat, the game creates and develops an immersive subterranean w', 'Welcome to Save-scumming - the video game. 99% of all problems you come across in this game are solved by not dealing with them and returning to them later. The best tactic in this game is Safe often and have multiple saves files at the same time... Tactics exist, but most of the difficulty does not come from mechanics it comes from Innate Spell resistance and Damage automatically scaling with level. \r\n\r\nThis game has a following, but if you are looking for some Retro game that brings tactics an', 'Very Positive', 92.04, 58.03, 33.93);
INSERT INTO reviews VALUES (1426, 208480, 5002, 'One of the best ones in the series, but its a shame the series has been rinsed, gutted and buried with newer games', 'I love getting flashed by a white screen every tiny loading screen.\nManaged to lost my save file due to using Ubsisoft version once and then Steam version.\n\nEdit: Game bugged out and did not grant me completion of the recruit missions so I am locked of 100% and found out that because you have to go trough the launcher you can''t play in offline mode.\n\nIf someone gifts you this they must hate you.', 'Mixed', 66.05, 20.23, 103.28);
INSERT INTO reviews VALUES (1427, 208520, 860, 'Please make a sequel or make a new with this concept, i very like this concept but still hope for better overall game aspects', 'Imagine having a 99% probability of shooting someone, point-blank, WITH YOUR GUN ALREADY IN THEIR FACE, and missing all five shots, just for on the next turn, you get one-shot sniped with a pistol, by an unseen enemy who is two stories below, behind eight concrete walls and two cars, and was born legally blind, who somehow, still kills you with a 2% chance, Thats just with the numbers the game displays, which apparently have ZERO correlation with the actual game mechanics, because enemies do not', 'Mixed', 61.16, 207.68, 115.88);
INSERT INTO reviews VALUES (1428, 208580, 16816, 'best Star Wars game to this day. If you are on a modern 120hz+ monitor, go into to nvidia control panel. click on manage 3d settings, click over on program settings, add the game exe to the list. set the fps limit to 80. this will stop a bug that causes your character to stop moving after combat.', 'A really good RPG, but only if you’re part of the lucky minority that can run the game with none of the huge technical problems it is suffering from.', 'Very Positive', 94.01, 88.47, 8.82);
INSERT INTO reviews VALUES (1429, 208600, 426, 'Outstanding space sim, especially VR version is amazing (I found vr_beta more stable than lfae). Funny how it is much better than most contemporary VR games. Perfectly playable with gamepad or HOTAS. The only drawback is no ultrawide support in non VR version, but that''s just cosmetics in compare to overall quality.', 'If you can work out how to start the game....you have a IQ of 200.\nWhy cant there be a Start button, and you play.\nAll the shit you have to do, Just to start.......has me lost.\nThere should be a quick start or some sort of way to help you start of.\nAn hour of my time was spent trying to get any were close to play.....I GOT NO WHERE........total crap this is.', 'Very Positive', 85.45, 58.03, 1.32);
INSERT INTO reviews VALUES (1433, 208650, 43390, 'How to put all of Gotham''s most dangerous villains behind bars, beat up a thousand bandits, solve all the puzzles, nearly go insane, and save the entire city in ONE night? Yes, its Arkham Knight. Plus funny dialog from the bandits on the radio like “If I were Batman, I wouldn''t put the baddies in jail, I''d kill them right away,” LOL.', 'I don''t like timed missions and I don''t like driving games, and I really don''t like timed driving missions (there''s a LOT). Asylum and City were fantastic.But, I can''t get into this idea where Batman outsources absolutely everything to minions and machines. When you''re soaring above Gotham it''s easier to get a layout of the land, but from street level everything looks exactly the same. It would be one thing if the Batmobile was optional, or just a speedy way to travel, but it''s forced down your ', 'Very Positive', 91.48, 31.98, 15.30);
INSERT INTO reviews VALUES (1434, 208670, 291, 'It''s extremely mid, still better than most of modern slop, so great as a palate cleanser for the right price.\n\nServiceable combat, story and voice acting. Pretty environment and models. Good vibes overall.\n\nRecommended with the right expectations.', 'Gooned and refunded 👎👎👎👎👎👎👎👎', 'Very Positive', 80.76, 12.35, 0.18);
INSERT INTO reviews VALUES (1436, 208730, 785, 'Pretty good game, grapics are ooutdated but at least we have something, if you are a GOT fan you will defenetly enjoy this one.', 'gameplay sucks and honestly ruins the game for me and makes it boring. the story itself is intriguing but its just not worth the gameplay', 'Mixed', 69.94, 5122.95, 12.52);
INSERT INTO reviews VALUES (1437, 208750, 1966, 'Nobody reads the reviews anyways, so i''ll just say i''m gay\n', 'Despite being a fan of metroidvanias and mythology, I had to drop the game after giving it 3 attempts and I rarely drop any content. I''d rather read/watch anything else mythology related or play any other popular metroidvanias.', 'Very Positive', 90.08, 6.58, 2.38);
INSERT INTO reviews VALUES (1438, 209000, 18418, 'the best arkham game\n\nmust have mods: reshade,upscale, center camera, knights gliding and grapnel system', 'Game is good but mine bugged and i can''t play it no more. I''m at locate black mask (access gcpd server) after i open the door my batman became no where. It''s just a moon and blank space, the batman always gliding and can''t do anything. I can''t play it no more, idk how to fix it.', 'Very Positive', 88.62, 52.02, 8.73);
INSERT INTO reviews VALUES (1439, 209060, 428, 'Got it for the banger soundtrack, stayed for the absurd robots and 3D bullet-hell goodness.\n\nProject Pantheon 14/275', 'There''s no fembot porn 👎', 'Very Positive', 84.81, 3.13, 4.23);
INSERT INTO reviews VALUES (1440, 209080, 6299, 'What once was, the developers should release a remastered version... this game was great fun and underrated.', 'completely and utterly dead\ni miss the old days', 'Very Positive', 91.74, 4.80, 0.85);
INSERT INTO reviews VALUES (1441, 209120, 903, 'MAKE THIS AVAILIABLE TO BUY AGAIN!', 'I want to make it clear i adore and love this game even if others don''t like it and i can understand the gem system being the biggest issue with which im onboard with getting it removed if its even a possibility.\n\nSo do i recommend this game HELL YES!!!! HOWEVER don''t buy it anywhere unless you are willing to do a work around to make it run.\n\nCapcom stated 3 years ago already that they would be transitioning older titles to Steamworks so far the only game i know they did this with is Resident Ev', 'Mixed', 54.49, 23.68, 25.93);
INSERT INTO reviews VALUES (1442, 209160, 5966, 'I personally liked the campaign and multiplayer can be fun at times but extinction is one of the greatest and most underrated game modes in cod history', '10 years later, Activision still prices this mid, recycled game for full price. Not even worth %50 off', 'Mixed', 57.63, 13.80, 0.30);
INSERT INTO reviews VALUES (1443, 209170, 571, 'this game gives me so much nostalgia when i was 6 years old and playing it during summer this was one of my most special cods i just dont understand why it get so much hate and all fr fr.', 'Multiplayer of this game is completely dead - so not worth the buy due to that.\r\nIf you want SP or play the Aliens mode with friends then you need DLC-s otherwise you can only buy 1 map.\r\n\r\nThere are probably small communities that kep hosting events in MP etc.. But other then that this game is long forgotten', 'Very Positive', 89.14, 56.02, 78.97);
INSERT INTO reviews VALUES (1444, 209190, 380, 'My wife said if this review gets 100 likes and 50 awards, she will let me play all week without seeing the sun or touching the grass.\n', 'Sadly, I''m one of the people that after the third chapter got severe and constant slowdown (There''s literally no way of fixing this according to the devs). Also, the game starts up in window mode because “xinput1_3.dll not found” and I can''t use my controller (The better way of playing this game). I looked online, on discussions and guides, but I couldn''t find a solution. The worst part is that this game is probably not getting updated, as it has been abandoned for at least 2 years by the commun', 'Very Positive', 88.68, 4.93, 4.87);
INSERT INTO reviews VALUES (1445, 209230, 312, 'Lovely game, but the crash was quite annoying.\n\nMy mom would give it a 9/10.', 'The game mechanics were fun, but the story is crap! I read the book 2-3 days prior to playing this game, and the story in the book is way better than what was put in the game. I was really looking forward to seeing how particular scenes from the book would be shown in a HO game, but most of the characters from the book are not in the game including the bad guy! How do you not include the story''s bad guy in this game? And since most characters weren''t in the game, that means most scenes from the ', 'Very Positive', 88.46, 6.80, 5.77);
INSERT INTO reviews VALUES (1446, 209270, 311, 'This game used to be so sick, RIP', 'eh its ok', 'Mostly Positive', 73.63, 9.48, 31253.75);
INSERT INTO reviews VALUES (1447, 209330, 176, 'This is a game that is hard to suggest for others,  unless you are an other who likes it.   I love this game.  It is a fun game.   The music is moody and setting,  the aesthetic ugly but fitting.   Over-complicated but just the right amount of complexity.   It is relaxing yet frustrating.  But I like it and have played it off and on for years.  Why?  I don''t know.  But try it,  if you like it,  welcome to the small club of those of us who find this curiosity, enjoyable.   It is better than the s', 'A great argument against procedural generation. Very repetitive, and poor interface doesn''t help.\nA pity, it has(had?) potential and I really wanted to like this game.', 'Mixed', 63.64, 86.33, 2.72);
INSERT INTO reviews VALUES (1449, 209370, 1261, 'I need to go back in time to kill Confucius', 'This started out like Her Story, where you watch and read records about a family drama. This one is set in space in the far future and involves two noble families of Korean descent who died aboard a ship.\r\n\r\nIt''s well written and all, but I found the UI incredibly clumsy. You also need to know something about how some Asian surnames work and the gender politics with women and status (which was very low). There was a lot of clicking back and forth, checking for new logs, and there''s even an MS DO', 'Very Positive', 94.53, 4.40, 2.33);
INSERT INTO reviews VALUES (1451, 209520, 162, 'If you can ignore the ease in which your little mini motor racing car can be spun out by competitors (and the massive clusters that this causes), and if you can get over the questional physics in a(n admittedly) minority of maps, then this game is a fantastic racer.\n\nIf you grab it while it''s on sale for about $2.50, then the game is a fantastic addition to a gaming library.', 'The artstyle and graphics are beautiful. The tracks are fun. But is it a good game?\nNo! The AI drivers behave like they''re alone on track, constantly bumping into each other and the player. And as if that''s not enough the smallest collisions slow you down to a crawl, spin your car around and thus make you vulnerable for yet more AI drivers to crash into you, repeating the cycle. But if you manage to get a good start and survive the first 10 seconds the AI drivers will take each other out every t', 'Mixed', 67.90, 3.03, 2.17);
INSERT INTO reviews VALUES (1453, 209630, 203, 'I wouldn''t have played this game if it had no reference to the Cthulhu Mythos. And I think it makes a good impression in this respect. I liked how the levels, story and atmosphere changed more and more in a dark and threatening direction. The magnetism puzzles were clever and challenging but not that great that I want more of them. But it''s definitely worth playing.', 'There is no tutorial.  I want to return it.', 'Mostly Positive', 78.33, 21.60, 0.68);
INSERT INTO reviews VALUES (1454, 209650, 5643, 'still one of the most underrated Call Of Duty in history', 'too expensive for a 10 year old game', 'Mixed', 58.04, 11.10, 0.65);
INSERT INTO reviews VALUES (1455, 209660, 297, 'Zombies.. pretty... I must say... I dare sayy.. quite exquisite', 'Horrible optimization, the third zombies map is literally unplayable because it always crashes , lots of performance bugs and in general the zombies suck', 'Very Positive', 81.14, 12.57, 57.02);
INSERT INTO reviews VALUES (1456, 209670, 1267, 'A great game left out in the rain by the developers. You can get the whole game for free and open source since the original creators did put out the code themself. I was really debating on if giving this a positive or negative rating was better, in the end is up to you how you spend money. The workshop is great so I would understand if that was a deciding factor. Personally I have no gripes with the game, only annoying thing they put in it was adverts for Planetoid Pioneers inside it. Planetoid ', 'amazing potential, completely abandoned game, however there is a community revival  project that has improved the game in basically every way. What currently exists without the community project is an inconsistent strategy sim with broken achievements. Save your money, find this game elsewhere if you really want to try it out with the Cortex Command Community Patch', 'Mostly Positive', 79.79, 139.13, 6.38);
INSERT INTO reviews VALUES (1458, 209730, 167, 'Reminds me of those old school dungeon crawler games like Dungeon Seige 1 and 2!', 'R.A.W. Realms of Ancient War is a very poor Diablo clone, It has terrible graphics, weird physics and controls very bad. Not recommended', 'Mixed', 52.69, 0.20, 0.48);
INSERT INTO reviews VALUES (1460, 209790, 145, 'An excellent puzzle game with a lovely soundtrack that reminds me of the tv series Fringe.', 'Sometimes less is not more, and what some people might find minimalist and artistic, is in fact, just annoying and obtuse.\n\nIt is difficult to understand what is going on in this game, from the controls, to actually solving the puzzles. Eventually you find your way to the bare basics control list, but even then there is a severe lack of a tutorial. I suppose the name of this game is trial and error, but to be honest, I don''t find that very fun or entertaining.\n\nI played and did as much as I coul', 'Very Positive', 86.90, 5.07, 1.73);
INSERT INTO reviews VALUES (1461, 209830, 574, 'My favorite game of all time. It''s fairly simple and straightforward, but the atmosphere and story and dialogue are among the very best. I would love if this ever got some sort of literary or film adaptation.', 'Fell in love with atmosphere and scares, but survival mechanics was too punishing. It felt like I beat a half of the game, but I''ve just barely got everything for a working stove. Main issue was a map. It''s disorienting and game doesen''t gave me enought shortcuts in my poinion so I need to do alot of backtracking with a map like that. I''ve just dropped it after I''ve reach a basement, because suffering throught another disorienting maze of a map was too much for me', 'Very Positive', 87.63, 6.65, 3.08);
INSERT INTO reviews VALUES (1464, 209950, 395, 'I am not sure how many years ago I bought this or how many of my over 1,700+ hours of game play were from me leaving the game open in the background since I often play it in between other things, but today I finally completed all the achievements!  \nYes I recommend it especially if you get it on sale, it''s highly addictive. It''s essentially like a match three game but it takes a more tactical forethought and planning.', 'You can take the game out mobile but you can''t take mobile out the game.', 'Very Positive', 92.41, 1769.92, 0.13);
INSERT INTO reviews VALUES (1467, 210550, 213, 'space', 'It does get old pretty quickly, just saying.', 'Very Positive', 88.26, 6.43, 7.90);
INSERT INTO reviews VALUES (1468, 210770, 4277, 'NOTE: I have around 200 hours on my old account on this game.\n\nAwesome game, unfortunately, it''s dead (multiplayer is really hard to find).\n\nSanctum 3 would be very much appreciated.', 'Game will not create a save file and none of the fixes from multiple forum posts going all the way back to the launch would fix it. Very disappointing. The game seemed like it had potential.', 'Very Positive', 92.40, 0.52, 2.03);
INSERT INTO reviews VALUES (1469, 210950, 329, 'ni🅱️🅱️as whom''st''ve played this game grew up to be based gigachads', 'Don''t buy it. So many bugs and deleted levels! In addition to listed problems, multiplayer is broken. It''s terrible version of perfect game.', 'Very Positive', 91.19, 154.12, 35.82);
INSERT INTO reviews VALUES (1470, 210970, 8181, 'A game of puzzles, by puzzles, and for puzzle. While it may sometimes feel like an aimless intelligence test, filled with challenges that might not fully satisfy as a traditional game, as a pure puzzle experience dedicated to puzzles, it’s nothing short of paradise. This puzzle game contains more puzzles than the word ''puzzle'' appears in this short paragraph.\n\n\n퍼즐 풀코스 파티!', 'This is the game that made me realize I am not into pure puzzle solving games at all.\n\nClever, occasional, and relatively simple puzzle solving challenges and rewarding exploration in games like "Zelda: A Link to the Past," love it. The kind of puzzles that the Witness was asking me to solve with no other interesting gameplay? I''m not exaggerating when I say I''d prefer to be slapped in the face with a dead fish.\n\n', 'Very Positive', 83.27, 9.23, 1.55);
INSERT INTO reviews VALUES (1472, 211050, 212, 'A normal game of chess but with epic animations and epic environments. Highly recommend to chess players.', 'trash game fuck off wasted of money can''t even run on my m4', 'Mixed', 66.98, 3.20, 2.82);
INSERT INTO reviews VALUES (1473, 211120, 209, 'It was fun', 'mate, fix your mulitplayer its been 3years im still on turn 3', 'Mostly Positive', 71.29, 5.25, 4.02);
INSERT INTO reviews VALUES (1474, 211160, 472, 'Everything is great about this game even if it gets repetitive, the combat makes this game so epic and this is a childhood favourite. I am so happy i can play this game it is worth it.', '30FPS lock, controller support is janky at best. it supports modern resolutions which is neat but definitely better games to play out there.', 'Mixed', 57.42, 16.28, 0.68);
INSERT INTO reviews VALUES (1475, 211180, 190, 'best game ever, i remember playing this a long time ago when i was 5, then it got removed from the app store but today 10 years later i found it on steam and i have had the best day ever playing this game again, 10/10 would recomend.', 'Unmechanical is short (~2 hours). Many of the puzzles are very fiddly. But the environments are nice to look at. \n\nFor the asking price I feel there are stronger puzzle game experiences. Most of the puzzles here are one-off and there is little to no "revisit with a new twist" style puzzling where the sum of your knowledge comes into play. Don''t get me wrong, some of the individual puzzles are entertaining. \n\nHowever, I feel like too much of the development effort was spent on the environment bac', 'Very Positive', 90.00, 7.23, 2.48);
INSERT INTO reviews VALUES (1476, 211260, 1356, 'Quite fun, and super snappy controls, but game speed is linked to framerate so make sure to set your refresh rate to 60Hz before playing.', 'This game is both annoying and frustrating. It has two buttons, one for jumping and the other one for literally everything else. For a precision platformer, it needs a dedicated button for each action cause only two buttons just doesn''t work well. As far as I''m aware, there''s no way to change this button layout to have each action tied to a dedicated button. So far, only two levels into the game and dealing with this is discouraging me from continuing. I''m still going to see the game through the', 'Very Positive', 83.55, 6.07, 3.45);
INSERT INTO reviews VALUES (1478, 211340, 641, 'So, yeah... I''m so normal about this game', 'Magical Diary is a anime graphic novel roleplaying game set in a life and school simulation. This is a pretty specific genre, but surprisingly there''s some competition. \n\nAfter playing through Magical Diary I cannot give it a recommendation. Compared to games like Academagia and Long Live the Queen, Magical Diary is has a story that''s too linear, gameplay that''s too simplistic, and RPG mechanics that are too shallow. It might be good for younger audiences, but for those who enjoy the challenge o', 'Very Positive', 93.45, 399.47, 4.83);
INSERT INTO reviews VALUES (1479, 211360, 104, 'A very chill puzzle/platformer, with charming pixel graphics, and fun music. Was able to finish the 100 levels in just under three hours, spent 2-3 sessions just pushing through level after level. Good replayability, each level offers three tiers of timing, the top 2 for those looking for an additional challenge. Had a absolute blast playing this game.', 'I want to really like this game. I really, really, do. I want to love it and squeeze it and never let go. Instead, I find myself thinking that the quit button is a more and more appealing option as I hear the same song loop over and over again and struggle to find enjoyment with Offspring Fling''s basic and short bursts of puzzle platforming.', 'Very Positive', 89.42, 3.20, 2.07);
INSERT INTO reviews VALUES (1480, 211400, 3999, '"Keep going, don''t stop!" - That''s what she said...   about this game.', 'DO NOT BUY the 2012 version! \n\nThere is a Director''s cut upgrade that came out in 2016 that does not link to the main game page. I bought the wrong version and can''t get a refund. Don''t make the same mistake. I only played a short while and do really like the game, so I intend to get the upgraded version on discount, but want to let people know to save their money. Older versions of games should be taken down or at least provide a warning that a newer version is available. Total BS.', 'Mixed', 69.52, 4.98, 0.20);
INSERT INTO reviews VALUES (1481, 211440, 168, 'A simple platforming game with some basic puzzles. Nothing too crazy. The game is fun, but controls are a little wonky. The character feels heavy and not very responsive, but at times requires precision to go through a hole quickly or land on a specific small platform, while avoiding lots of enemies. Some enemies patrol predictably, while others are chaotic, which is frustrating.\n\nThere are a few different puzzle types that you learn which are mixed and matched together to form some harder chall', 'Dishonest Trailer:\n\nIn a world full of puzzle platformers, where timing is everything and patience is a limited resource…\nComes a game with charm, color, and the power to test the limits of your sanity —\nThis is THE ADVENTURES OF SHUGGY.\n\n🌟 MEET SHUGGY 🌟\n\nHe’s a tiny vampire with a giant mansion, armed only with determination, a jump button, and an endless supply of retries.\nStep into his shoes as you:\n\n    Spin entire rooms,\n\n    Manipulate time,\n\n    And navigate puzzle after puzzle that seems', 'Very Positive', 85.71, 9.08, 0.95);
INSERT INTO reviews VALUES (1482, 211500, 655, 'Labor of Love Award 2024\r\n\r\nThis is one of the best and at the same time the most underrated racing simulator.\r\nA huge amount of work has been done this year and recent updates are amazing!\r\n\r\nI wish there were more players, hope future updates and LFM will be a game changer.', 'Among the main motorsport simulators, I consider RR to be the worst, with inconsistent AI depending on each circuit, for example with F3 in Hungary the cars don''t make turns and crash into each other, the Macau circuit is useless because getting around the Harpin depends on luck, among other polishing problems such as not saving the cloud configuration, lack of dynamics in the onboard camera, replays that are saved on the HD, no possibility of connecting to the game without internet etc etc etc', 'Very Positive', 85.50, 29.82, 133.72);
INSERT INTO reviews VALUES (1483, 211580, 212, 'nice game if you have friends and i found some nice people to help me ...\n\ngood memories but i did suffer for many things in this game xD\n\ni hope the other game "Wanderlust Adventures" is better...\n\nbad game as single !! what make the game good is people to play with only ...\n\n\n\n', 'So this is a hack n'' slash RPG with crappy graphics.  That is kool. What they don''t tell you is that you only get 50% of the exp for beating a level unless you manage to beat the level doing as little damage as possible to all the enemies so that you get very high combo numbers. (Yes it''s true, I asked the developer) You don''t get extra experience for beating a level again. Nor do you get experience for their challenge levels. You can only try to get more experience by getting the higher combo n', 'Mixed', 51.42, 127.98, 10.92);
INSERT INTO reviews VALUES (1484, 211600, 2338, 'Thief Gold is simply unbelievable as a game. It''s a bit dated perhaps, but the gameplay is top notch, as long as you like stealth games. The story is immersive, the atmosphere is tense and eerie, and there are lots of creative twists and turns. For me, this is one of the greatest of all times and I''ve been gaming since the late 1970s. (Yep, I''m old, but I still love games.)', 'if you are planning to buy this game or have gotten it on a sale for cheap like I have and intent to play it. please don''t play on higher diffculty than normal. the higher difficulty gold requirement will all but guarantee you will be looking at a walkthrough for on most levels, especially on a first playthrough. \n\nthe diehard thief fan will convince you to play on a higher difficulty than normal, DO NOT TRUST THEM. Only pain and staring at a walkthrough await you after wandering around a level ', 'Very Positive', 92.77, 34.70, 30.18);
INSERT INTO reviews VALUES (1485, 211740, 1337, 'Thief 1 minus the zombie, monsters and horror bullshit and greatly expanded level design.', 'like the first . lost mostly\r\ni didnt like it that much but glad that i tried this franchise\r\nif only it got a better map,  i would like this sh!t', 'Overwhelmingly Positive', 95.29, 11.55, 10.33);
INSERT INTO reviews VALUES (1486, 211780, 772, 'A bargain bin classic! What it lacks in quality and refinement it makes up for with charm and pure fun. Sadly, the PC version lacks split-screen co-op, which is the best feature.', 'This game was my favorite game in the WORLD! this game on here needs some help though, you cannot fall off ledges without having Bradley float into the sky i hope you can figure out how to fix that.', 'Mixed', 68.65, 16.25, 0.37);
INSERT INTO reviews VALUES (1488, 211820, 51375, 'Note: This game itself isn''t the best without mods, in many ways like a bethesda game.  However, its got a massive host of mods that ultimately expand on it, some, such as frackin universe, are essential albeit a mixed bag, but in the end are worth it.  The huge combination of planets you can find and mods that expand on that, the base building imo is actually cooler than terraria in a number of ways even(more furniture and decorations overall), and the expression players can put in is up there.', 'I have 300 hours. I''ve 100 percented the game. I''ve played for years.\n\nThis is coming from someone who really wanted to give this game the benefit of the doubt:\n\nThe management of this studio doesn''t deserve your time or money. They will never address the massive gaping hole in content and balancing this game needs. The modding scene has some extremely talented people - talented people who deserve to be working with better projects then this, and ones where the dev teams respect them and their w', 'Very Positive', 88.98, 2325.70, 302.53);
INSERT INTO reviews VALUES (1489, 211900, 237, 'fun game me like is complicated tho so keep that in mind also warning the animals will try and murder you atleast once', 'A quicker, smaller, and less robust version of Dominions 3. While this may sound fun, the game resembles a battle simulator with little of the strategic thought or depths found in Dominions 3. Unless you want a stripped down version of Dominions 3, avoid Conquest of Elysium 3.', 'Very Positive', 81.86, 8.07, 7.45);
INSERT INTO reviews VALUES (1490, 211970, 129, 'I was reading the other reviews and was very surprised when I started playing this game. The car handling is very good and the tracks are fun to drive and the scenery is very realistic and I prefer being in the car than the view of the car driving. The sound effects and commentary are just right and not annoying like some games. I am enjoying seeing all the Ferrari cars from the early models up to testarossas and the likes very impressive.\r\n\r\nFANTASTIC GAME TO COME BACK TO OVER AND OVER IT IS VE', 'Its just okay. It''s basically a bare bones version of Need for Speed: Shift 2 with only Ferarris. The physics and feedback is nearly identical except dumbed down. Just like how Need for Speed: Porsche Unleashed celebrates Porsches, this game is similar but with Ferraris and not nearly as much content and creativity put into it. The game can be fun at times but the overwhelming majority of it is boring and very repetitive and a low variety of features. There''s a Campaign mode, quick race, and Tim', 'Mixed', 53.49, 7.57, 15.25);
INSERT INTO reviews VALUES (1491, 212010, 548, 'Unironically provides better immersion than Starfield', 'Beware. This game requires an Internet connection. This is not on the store page. There is no link to some EULA that mentions it. You need an Internet connection. If Steam is set to Offline Mode, or if Steam is online and you don''t have an active Internet connection, the game will crash after the launcher.', 'Mixed', 69.89, 2.37, 0.67);
INSERT INTO reviews VALUES (1492, 212030, 315, 'One of those nostalgic games from the past decade. Challenging and very fun especially the coop mode.', 'Constantly pops up messages to parry, but when you parry, other enemies just instantly hit you anyways or the boss takes 2 hits, parries you mid-hitstun, then hits you for guaranteed damage\r\nConstantly moves the camera around so you can''t see **** on some maps\r\nThrows you v 5 enemies including boss at once with a kit that can barely handle one enemy\r\nHas a tiny, boring moveset; you mash X until it says to hold X or mash A, which may also tell you to do the other one, then you hit the enemy until', 'Mostly Positive', 79.37, 8.32, 0.22);
INSERT INTO reviews VALUES (1493, 212050, 350, '***FLASHING LIGHT WARNING***\n\nI''m shocked by just how much this ''real world'' (no fantasy, no ''extreme'' sci-fi) point & click adventure game got its hooks into me. There are twists and turns in this that I *still* think about, years after I first played this game.\nA number of puzzles in this are very challenging but every puzzle in this is *fair*. Strongly recommend.', 'Can''t recommend this one, couldn''t keep playing even though I wanted to like it. \n\nIt doesn''t hold up to the other wadjet eye games in terms of how naturally the story unfolds or how the puzzles/gameplay feel. The story and characters are interesting, but there are too many puzzles that really weren''t needed or were obnoxious to solve without a walkthrough, also including some dialogue that was just painful to read and listen to because it was obviously filler material, too much backtracking to ', 'Very Positive', 88.00, 15.35, 3.17);
INSERT INTO reviews VALUES (1497, 212480, 6366, 'Its nice and fast.  The transform mechanic works amazing.  This game is about 20x better than any Mario Kart game I''ve ever played, and I love Mario kart.', 'No longer works at when starting up it will give an error that game is already running even after reistalling the game multiple times and there is no fix either all comments ti fix are all fake, and i was able to play when i bought a while back, i am very dissapointed that there is no fix from the developers.', 'Very Positive', 93.25, 2234.15, 11.13);
INSERT INTO reviews VALUES (1499, 212630, 2311, 'The game has aged like the finest of all wines.\n\nI miss what Ghost Recon used to be. \n\nI miss what Ubisoft  used to be.', 'This game rocks but sadly the company that runs it is quite possibly one of the most greedy shitty game companies out there, players that purchased the DLC of this game before they delisted it are completely unable to play the Raven Strike singleplayer campaign DLC because the ability to activate DLCs is simply not possible. That entire DLC is just like lost media now I guess. Not only did the players who paid for it get scammed by this bs, new players literally cannot experience the full ghost ', 'Mixed', 66.21, 38.52, 51.52);
INSERT INTO reviews VALUES (1500, 212680, 44592, 'What if instead of Faster than Light it was called Freakier than light and instead of stopping the rebels you gave them backshots?', 'great idea, terrible execution, even on the so called easy mode it seems like its scripted to just throw events at you that trainwreck your progress that are simply impossible to overcome, i expect that on higher difficulties, not "easy".', 'Overwhelmingly Positive', 95.72, 86.98, 11.32);
INSERT INTO reviews VALUES (1502, 212780, 172, 'from a village in bulgaria to manchester', 'This game always keep crashing for me while I tries to do so. Hopefully, it must solved the problem or waiting for newest game of NSS6.', 'Mixed', 57.56, 20.97, 34.07);
INSERT INTO reviews VALUES (1504, 213030, 377, 'This was my first Penny Arcade game and I liked the quirky conversations. The mechanics did not stay fresh through the entire play through but it was so fun at the beginning I think it levels out.', 'I''m a little disappointed in this game. I truly am. The previous Penny Arcade games, in their 3D environment, semi-free-roaming capabilties, witty dialogue, character customization, and comic book-styled cutscenes were excellent, but this one...\nI just can''t bring myself to keep playing. It''s become a 2D RPG-stylized game, and though it started out pretty alright, the required battling, which for the most part, is every enemy you see on screen, really started to bore the living fecal matter out ', 'Very Positive', 89.12, 6.22, 5.45);
INSERT INTO reviews VALUES (1506, 213330, 3028, 'Batman doesn''t kill but Lego Batman does.', 'Honestly while not a bad game, the open world feels a little under utilized. The voice work was enjoyable though. I just believe there was more creativity in the 1st lego batman game.', 'Very Positive', 94.45, 7.20, 26.12);
INSERT INTO reviews VALUES (1509, 213610, 15776, 'This game was so good they made a whole movie about it.\nThen that movie was so good that it completely humiliated Disney so hard that they tried buying out SEGA.', 'Absolute trash port. Crashes on startup. Could only get it to run in windowed mode. Played for all of 5 minutes before it crashed my explorer.exe then it froze. Don''t even bother with this.', 'Very Positive', 90.28, 8.33, 0.15);
INSERT INTO reviews VALUES (1511, 213670, 28764, 'A ubisoft game without the ubisoft launcher, you think you would look at formulas that work and replicate that prior to your company going bankrupt.', 'I love South Park.\nI love Trey Parker and Matt Stone for not holding back and making fun of absolutely everything.\nbut I also loathe the publisher Ubisoft, so the negativity is for them and only for them, NOT the game.', 'Overwhelmingly Positive', 97.06, 2.27, 3.80);
INSERT INTO reviews VALUES (1514, 214170, 1397, 'One of the best game soundtracks of all time. Great game from Larian. Just wish they would "remaster" it for current systems.', 'Interesting only as a historical artifact.', 'Very Positive', 85.11, 82.57, 2.85);
INSERT INTO reviews VALUES (1515, 214250, 1271, 'I highly recommend this game it''s short but not too short I beat in just over 4 hours with 98% completion but mainly bought it because I originally played it when i was younger on my ps3 (didn''t get too far because I sucked at stamina management lol) if you have time I recommend giving this gem a try. Anyways thank you for reading this you''re a legend! P.S  I Am (still) Alive', 'TL:DR\nIf it''s on sale and you think it looks interesting, buy it. Otherwise, this game is not worth your money.\n\nActual Review:\nI first played this game when the demo came out on the PS3 and just recently found out it was on Steam, it was only $4 so I decided to get it. One of the most mediocre games I''ve ever played. The story is generic with the interesting ideas being ignored, the combat is repetitive and gets boring quick, but the climbing mechanics are decent. There are a lot of good ideas ', 'Mixed', 62.23, 4.87, 5.17);
INSERT INTO reviews VALUES (1516, 214340, 2877, 'Years ago, I finished a pirated version of this game. Now, I’ve bought it to show my respect and support for the developers.\n\nPoint-and-click games aren’t the most popular genre, so there isn’t a huge selection to choose from. However, this game stands out as one of the best I’ve ever played, along with Tales of Monkey Island.\n\nI’m not sure if I’ll manage to complete the whole series this time, but I’m definitely enjoying it. The art, the dialogue, the interactions - it’s all fantastic. I highly', 'Art design is very good, and dialogs are a gem on itself,\n\nBut to progress on the story, you have to collect things from many places, and most of the time it''s not intuitive what to do next; it''s really hard to make progress without a guide', 'Mostly Positive', 77.69, 7.78, 2.67);
INSERT INTO reviews VALUES (1517, 214360, 728, 'Good game. Only complaint is that you can notice the low refresh rate when moving the playing field around.  Otherwise a solid game.', 'company shut down. game doesn''t work for multiplayer. dont buy', 'Mixed', 68.54, 3.75, 31.85);
INSERT INTO reviews VALUES (1518, 214420, 609, 'This game has super fried vibes overall with wacky weapon systems and addicting 3D tank combat. Overall a fried experience 10/10 recommend.', 'Was good while it lasted. empty now.', 'Very Positive', 85.88, 23.32, 55.32);
INSERT INTO reviews VALUES (1519, 214490, 24413, 'this game has such insane optimization that the whole game is available on mobile and you can even play a demo for free if you want to.\nits graphically identical to the pc version, and has no content cut out.\nnowadays some people can get doom to run on a mcdonald''s kiosk, in a few years people will be getting alien isolation to run on pregnancy tests.', 'Stellar art direction, vibe, really perfectly nails the world, tone, characters, and creature.\n\nGameplay is just... not that fun, though.\n\nFighting non-alien enemies is meh. The alien itself feels very programmatic and random; you really just need to cower until you get a window, and then make a break for it quite often. First few interactions, it''s heart-pounding. After dying the third time, it''s prettymuch old news and loses it''s shine. After two hours of this, it actually gets annoying. Like ', 'Very Positive', 92.32, 80.70, 16.02);
INSERT INTO reviews VALUES (1520, 214510, 4452, 'I own 19 different lego games. I am unbiased. Game good. Sam lego. Also Frodo. My opinion is important', 'DO NOT GET if you have a Chromebook with steam beta. Issue with lava/water texture causing it to be a flashing epileptic hazard that can be seen through walls and incredibly buggy. In order to fix it you''ll have to jump through hoops and other obstacles but it involves having a background in coding before attempting to install Proton GE which may or may not work.', 'Very Positive', 89.71, 9.68, 0.63);
INSERT INTO reviews VALUES (1522, 214560, 6964, 'Mark of the Ninja is a well-crafted stealth game with smooth controls and fluid animation. The levels encourage creative stealth, but the game can feel a bit too simple for those looking for more challenge. It’s fun but doesn’t offer much depth beyond the gameplay.', 'Platformers and stealth games are definitely not my thing. I bought this on sale hoping it would suit my play style better than most. Unfortunately, it doesn''t, it''s too difficult for me on the default (and I couldn''t see a way to change this).\n\nI found the graphics, sound, game mechanics, and settings all to be lacking to some degree. The gameplay and stealth mechanics in particular felt incredibly shaky and poorly executed. I could never remember which buttons did what I wanted, because the ga', 'Overwhelmingly Positive', 96.70, 5.80, 0.60);
INSERT INTO reviews VALUES (1524, 214590, 346, 'Play the cute Fairy game...\nSo it beats dafuq out of you like your father should have....', 'Single player Smash Bros against Muks and Grimers.', 'Very Positive', 89.88, 8.38, 0.70);
INSERT INTO reviews VALUES (1525, 214630, 181, 'I LUV BLAKEPS MEC EDITION\nITS FUN PLEYING WIT MY ASPYR FRIENDS\nSO MANY PEEPUL PLEY THIS GAEM\nI CAN THINK OF JUST OVER 2 SERVERS THAT PEEPUL ACTUALLY PLEY ON!!!!!1!\nI WOOD RECUMMEND THIS GAEM TO ANYONE WIT A MEC', 'All ye Mac peasants! I am one of you who games on mac! Take heed! This game is unkind to those that play zombie mode! Hark! All ye who may have macbooks that can''t run this game on medium or low settings, forgo this game, tis a pity to play on weak hardware together with our small breed of gamers of House Apple!', 'Mixed', 60.22, 39.88, 5.02);
INSERT INTO reviews VALUES (1526, 214700, 1037, 'Before you read the rest of the reviews, remember this: Steam''s primary userbase is Gamers, and Gamers can be really, really stupid. If you''re at all into narratives; an English major, a screenwriter, an aspiring game dev; check this out. Filmic language brought into the interactive, a full decade before AAA studios like Remedy started to do the same. Could you get the same basic experience from watching a playthrough on YouTube? Sure, but you could also get the same basic experience of a novel ', 'Man I like the whole idea here but it''s just toooo short to justify itself\nRecommended by: Experiences Worth Experiencing', 'Mixed', 68.08, 0.70, 0.70);
INSERT INTO reviews VALUES (1527, 214730, 975, 'The best game of my childhood, the developers are great, thank you.', 'Space Rangers 2 was one of the best game of this genre, then someone came up with the dumbest idea ever of adding a non-sensical faction that threw the balance of the game out the window.\n\nEasily one of the best examples of how to take a good game and make is horrendous.\nRemove the pirate faction, its that simple.  You ruined a good game.', 'Very Positive', 87.69, 15.93, 152.98);
INSERT INTO reviews VALUES (1528, 214770, 1850, 'No one is Going to read this review so i want to confess that I''m Mexican and I love spicy food and it comes out of my ass', 'Guacamelee! Gold Edition is a hollow attempt to merge Metroidvania with Mexican folklore, resulting in a mismatched cacophony of mediocrity wrapped in a garish, Day of the Dead-themed wrapper. The game revels in its ''humor,'' but its jokes land with the grace of a piñata stuffed with cement—forced, cringeworthy, and utterly devoid of wit.\n\nThe combat is as repetitive as it is uninspired, relying on a tired combination of button-mashing and awkward platforming segments that feel more like punishme', 'Very Positive', 92.32, 5.13, 4.95);
INSERT INTO reviews VALUES (1529, 214790, 775, 'Tip: When Edmund McMillen says "It''s peanut-butter jelly time!", every gosh diddly darn person on the North-Western continent sits down and has a peanut butter and jelly sandwich.', 'This game is another huge waste of time that I intensely regret buying. The games are stupid, uninteresting, and mechanically broken. Really nothing worth playing in the whole bundle, such a waste of time.', 'Very Positive', 89.55, 14.97, 1.67);
INSERT INTO reviews VALUES (1530, 214830, 656, 'This doesn''t have Another Goddess from the PSP. This game''s Hero 30 mode is straight ripped from the 360 version, so it has the Time Beast arc instead. However, it has both the Classic and Neo versions of Evil Lord, Princess, and Knight 30, but if you want to play the Classic versions with the Neo graphics, that''s not an option. If you want to play the Neo versions with the Classic graphics, that''s only possible on the 360 version. (In fact, the game chooses the mode for you based entirely on yo', 'The game is repetitive and I don''t see the point of it. Someone had a clever idea for a game concept, but it just doesn''t work when implemented.', 'Very Positive', 87.96, 14.08, 3.03);
INSERT INTO reviews VALUES (1531, 214870, 922, 'Painkiller: Hell & Damnation remains a timeless classic, delivering unadulterated gaming bliss. A refreshing throwback to an era where games focused solely on entertainment, free from extraneous distractions.\n\nA true testament to the power of straightforward, skill-driven gameplay, this title continues to captivate audiences with its intense action and uncompromising challenge.\n\nIf you''re seeking an unapologetically fun gaming experience, look no further.', 'Missing entire levels and removes some of my favourite enemies. The Orphanage and City levels now suck ass and fail to create the original atmosphere. Get the original.', 'Mostly Positive', 72.23, 53.95, 8.65);
INSERT INTO reviews VALUES (1532, 214910, 133, 'I''m not done yet, I still have missions to go but could someone tell me how the heck do you beat the bomber before he drops his bombs', 'Air Conflicts: Pacific Carriers is an interesting take on the Pacific War, with the Japanese campaign especially bringing a more human element to the story. As a history buff, especially concerning the war in the Pacific, this game has piqued my interest for some time. However, there are several historical inaccuracies, and gameplay becomes repetitive after the fifth hour or so. I have encountered multiple graphical bugs, and a game crash at the end of the final Japanese mission. If you can get ', 'Mixed', 47.37, 54.33, 12.37);
INSERT INTO reviews VALUES (1533, 214950, 29849, 'I''ve only put a couple of hours into the game, LOVE IT, it can be very laggy at times especially during naval battles but apart from that it is my favourite Total War game!', 'While a technical upgrade over the first game, this game sequel has many jarring design flaws. On top of that many pricey dlcs that refuses to get cheaper after 11 years. Some graphical assets look poorly done, especially the cloth or armour worn by elephants that have weird gaps. I severely resent the provincial system of this game that complicates game play, contrasting the simplicity the system of the original. Only mods make this enjoyable.', 'Very Positive', 84.93, 2965.30, 28.83);
INSERT INTO reviews VALUES (1534, 214970, 729, 'one of the many platformer shooter games that made my childhood\nstill fun to replay years later ❤️', 'Unfortunately very disappointing. The physics system is an active detriment to the gameplay experience and is only ever properly utilized in the most basic of "push thing to crush enemy" setups or when a boss needs to do something dramatic. It is more used as a level hazard than as any kind of system for the player to interact with in an engaging way.', 'Very Positive', 93.28, 4.93, 2.15);
INSERT INTO reviews VALUES (1537, 215160, 938, 'Holy cow did I love this game and the sequels.  I mean, I think it''s spoiled me for all other games.  How am going to find another game with phenomenal voice actors, beautiful graphics, and gut busting humor?  Not to mention really good puzzles. I can''t believe I had never heard of this game before until recently.  I wish I could play all three of them again for the first time.', '3/5 for me, had some good moments, had some not-good moments.\nGameplay-wise, it was pretty good. Nothing was laggy or buggy on my end, and I''m not always the best at puzzle games so I had a walkthrough open to reference as needed, but most things were pretty straightforward. I LOVED the spacebar being a key to show all the interactable things around you, it really helped me realize when I was finished in a room since I only had so many interactable things visible. I wish more puzzle games had th', 'Very Positive', 88.81, 24.78, 14.52);
INSERT INTO reviews VALUES (1538, 215280, 3455, 'This is far and away one of the best games I''ve ever played, even with the Legends version. Legends has some extra content and rebalances most of the game for single player, though it is also missing content, is absolutely predatory in its monetization, and removes some of the more interesting mechanics which set the game apart from other mmos of the era. However, I still recommend it to anyone who enjoys a good secret society story.\r\n\r\nThe world and quests are this game''s strongest points, as a', 'The Secret world was great, this Re-release was awful it, it took away what made The Secret World Unique and enjoyable while seeking to bilk those that had lifetime etc more money for everything that was already purchased.  Why Funcom is Failcom 90% of the games they seem to trash and then abandon', 'Mixed', 68.68, 141.03, 56.80);
INSERT INTO reviews VALUES (1541, 215470, 2536, 'i think there''s dinosaurs in it, i like dinosaurs. I don''t like the little guys who try to shoot the dinosaurs, they are bad, dinosaurs are cool, little guys suck.', 'its dead', 'Mostly Positive', 78.27, 8.52, 0.43);
INSERT INTO reviews VALUES (1542, 215510, 580, 'The best 5€ of my life', 'Just a time passing game, nothing special, repetitive missions and game play, opponents are dumb, same move will guarantee you kill them and pass the level, couldn''t finish it.', 'Mostly Positive', 75.34, 4.88, 2.43);
INSERT INTO reviews VALUES (1543, 215530, 3026, 'I''m sure 99% of people don''t read reviews. That''s why I confess that I love young, beautiful women.', 'The glitches in this game make it impossible to play. The very first boss I came across (the scarecrow) will not drop its damn shield. I ran around for 20 minutes fighting the enemies its spawned and taking swipes at him as well until I had depleted all my potions and ended up dying. Twice I did this a the scarecrow just puts up a shield immediately and will not drop it. How am I supposed to play a game where the bosses glitch into god mode and cannot be defeated? And I really wanted to enjoy th', 'Very Positive', 80.63, 47.80, 11.72);
INSERT INTO reviews VALUES (1545, 215630, 211, 'I unironically love this game. Is it a Great Value Dragon Age knockoff? Probably. Yes. Also lets you romance your sister :)', 'Game does not work in windows 11 kalypso launcher just fails to launch game. No issues on steam deck....they not even blood related.', 'Mixed', 69.19, 28.05, 13.52);
INSERT INTO reviews VALUES (1546, 215670, 877, 'While it''s a short game, there are a variety of ways to finish the ''story'', and decisions you make throughout the game influence these endings. I finished my first play through in less than an hour on my Steam Deck, and I was extremely impressed with the game, the feel and the story. \n\nIf you enjoy a quick exploration/horror, with some player decision influencing the end result, this is worth a few bucks.', 'Home is frustratingly slow and does not match the pace shown in the trailer. Much of the playtime is spent watching short cut scenes of climbing up or down a ladder or stairs, or opening a door. The story is unimaginative with fairly predictable options, and the "horror" aspect is limited to fake pixel blood and text, you won''t find any real frights in the game. I played it through to one ending hoping for a twist in the plot or an exciting setting, but that never happened. Don''t waste your time', 'Mixed', 69.44, 0.77, 1.20);
INSERT INTO reviews VALUES (1547, 215690, 435, 'What an improvement from the previews entry and the lore got expanded a lot but my god WTF is these people smoking?', 'Personally, i found myself quite dissapointed with this. After playing the first game i was eager to play the sequel in order to explore more of the world of zenozoik and discover how the story ends for ghat and deadra. However, I felt the sequel, despite the improved combat and visuals, was quite rushed and underbaked. I felt that the encounters weren''t as fun as the first game and the bosses were incredibly underwhelming, the final boss in particular. As much as the combat in this game was inc', 'Very Positive', 86.21, 7.37, 9.00);
INSERT INTO reviews VALUES (1548, 215710, 185, '100% after 15h, fun', 'too difficult to gain gold. Consumables are necessary to master the later difficulties.  you can tell this game was built with micro transactions in mind.', 'Very Positive', 87.57, 17.22, 23.75);
INSERT INTO reviews VALUES (1551, 215930, 423, 'One of the best tactical squad games of its time.', 'Absolute disgrace. Playing on a seconf difficulty. The enemies can hit heads with pistols on a range the top mercs in the game hit 1/20 tries.', 'Mostly Positive', 70.21, 304.30, 13.32);
INSERT INTO reviews VALUES (1552, 216090, 223, 'This is truly my favorite game. I downloaded Steam solely because I saw this game was available on this platform. It never ceases to keep me engaged and in a positive mood! I recommend everyone give this game a try. I promise you will love it!', ' a review of the game go home dinosaurs from tthe perpective of a profesional venttriliquisst!\r\n\r\nplayyd this game with my puppet and we had a ton of fun. fun levels fun cool game design my puppet was playing and i was on the side giving hilariouis commentary like oneypleais haha. you have to watch our lets play chanel it is literally the most hilarous show on all of youtubes so funny btw,,  let get to the rewview, so the game has alot of fun mechancics to play around with and especially the fir', 'Very Positive', 92.83, 16.03, 5.27);
INSERT INTO reviews VALUES (1553, 216130, 103, 'Its a halfway decent space RTS.  The gameplay is nowhere near as interesting as the promotional photos, however its still fun enough to play on rare occasion.  Worth $5, not $15', 'Requires registering with email to do anything besides look at the title screen. \n\nThe title screen was in low resolution.\n\nMusic on the title screen was not very good.', 'Mostly Negative', 33.01, 2.92, 1.27);
INSERT INTO reviews VALUES (1555, 216260, 553, 'i loved this cricket more than cr 24', 'DBC14 crashes often on Windows 11. I tried all of the tricks to make it work, but to no avail. It''s difficult to relax during a Test match, wondering if and when it will freeze.', 'Very Positive', 85.35, 4.12, 3.03);
INSERT INTO reviews VALUES (1556, 216290, 141, 'A captivating experience that leaves you wanting more.', 'Gateways is an interesting little game. The comparisons to Portal are bound to occur, so let’s just come right out and say what everyone is thinking: “This is a low-budget, 2D portal clone”.\n\nIt’s almost true. You can only make portals on certain walls, you can only have two portals at any given time, and at no point do you get any actual weapons to fight the few but deadly hostile lab things. That’s pretty much where the comparisons end though.\n\nI’m going to roll out this review in a bit of an ', 'Very Positive', 90.07, 10.13, 4.62);
INSERT INTO reviews VALUES (1559, 216890, 1002, 'This is in my humble opinion, the best of all the Blood Bowl games.  I''ve tried the all, and even with the newest graphics, I find this the best value for dollar.  It''s frustrating to be expected to keep buying the newest versions of every Blood Bowl, to continuously have to purchase the full game at a premium price, and have to pay extra for "DLC" of the same teams you''ve bought over and over again.\r\n\r\nBuy this version and don''t concern yourself with the fancy graphics and save yourself a lot o', 'I''ve played the DND style of it with rules, dice and etc but this is a confusing mess. The no is because the game is complicated and RNG is a bitch. This game isn''t for me but if you love other bloodbowl related items this might be for you.', 'Mostly Positive', 79.34, 476.88, 1.12);
INSERT INTO reviews VALUES (1560, 217100, 460, 'Decided to play this on a whim today after finishing the original DS version, since it''s been sitting in my library for years (funny story behind that, I got it through a steam trade with some person who was very insistent about wanting to trade for my duplicate cards but then acted all uppity when I wanted to trade for this game even though it had been put on offer; after the trade was complete I have yet to trade with anyone again). I''m giving it the same score as that one even though the gene', 'This game is wayyy better on ds. This is a pile of poop tbh', 'Mixed', 46.09, 10.87, 4.60);
INSERT INTO reviews VALUES (1562, 217140, 1382, 'Write a review for Rise of the Triad\nPlease describe what you liked or disliked about this game and whether you recommend it to others.\nPlease remember to be polite and follow the Rules and Guidelines.', 'Removed Tea-Bag achievements.', 'Mixed', 67.95, 5.28, 4.90);
INSERT INTO reviews VALUES (1563, 217200, 3401, 'this games statement on the socio-economic state of the world really says something about how we as a people underestimate the fundamental concept of a worm, something so easily killed by us humans must resort to militaristic wars against each other, simply just to prove one is "right"', 'fuck ass gun sprayed down my worms at 1 hp that fuck ass guy shouldve lost but sudden lost saved his little ass he better pray for the day i get an uzi irl and i drive by on that punk ass bitch', 'Very Positive', 93.65, 1.25, 2.70);
INSERT INTO reviews VALUES (1564, 217270, 113, 'One of the old cool games for the Commador 64. \r\nThis is the same game but, with of course, much better graphics than back in the Mid-80''s. CRT monitors. Very pixelated indeed but was so cool for it''s time.\r\nLevels are or seem to me, been a long time certainly due to technology improvements, more challenging. \r\nHave not made it to the end yet but not addicted as before to make the conquest, but if the same ending, I already know what it is to expect .', 'I played the original Karateka on several platforms growing up. I feel like the original was very underrated, as the combat has more depth than it may seem on the surface. Timing and spacing are critical elements in the original, as well as which attack you choose can make the difference between eating a counter or not.\n\nThis remake had so much potential and does a lot of things really well. Sadly, the combat is not one of them. This essentially boils down to QTEs on defense, and the camera angl', 'Mostly Positive', 75.22, 8.82, 0.75);
INSERT INTO reviews VALUES (1565, 217290, 180, 'Game is more addictive than cocaine.', 'I looked into Din''s Curse after reading some reviews of it. The novelties it brings - randomized worlds, dynamic events, time-sensitive quests - are all extremely interesting and full of exciting potential. Unfortunately, the game never rises to meet said potential. After playing through two and a half towns I feel as though I''ve more or less gotten the idea. \n\nGo to a town, win and fail some quests, occasionally have to rush back to town to defend an attack... rinse and repeat.\n\nIf the dynamic ', 'Very Positive', 83.89, 37.65, 4.22);
INSERT INTO reviews VALUES (1566, 217690, 587, 'Beautiful game that unfortunately makes you do 3 back flips mid air while juggling a bowling ball with your chin. The game will make you download their own launcher and then you''ll have to create an account, verify account, put in a key, etc. Just a bunch of nonsense. The worst thing is that the launcher feels like something straight out of 2008. That being said, if you''re willing to do all that to play this game you won''t be disappointed. \nThis game does what so few games in the horror genre ar', 'Tried to play after having not played for a while. Apparently Kalypso feels the need to force you to sign up with them in order to continue playing. The game is not very impressive in general so giving people another reason not to do business with you was probably a bad move.', 'Mixed', 56.39, 6.03, 1.92);
INSERT INTO reviews VALUES (1567, 217790, 312, 'This is a cool little game if you know what you''re buying, for this is not a flight simulator. If you''re familiar with Star Wars: Rogue Squadron or Jedi Starfighter you know what you''re in for! This is basically a WW2 version of those games. The flying feels nice, the cartoony graphics are nice enough to look at, the game doesn''t outstay its welcome as it only took me 2 hours to beat. But as such, I''d only recommend this during a sale; I paid 1,5€ for this and I don''t regret it. I also must ment', 'the will not start.wtf', 'Mostly Positive', 77.88, 3.60, 1.08);
INSERT INTO reviews VALUES (1568, 217920, 524, '6.5/10\nThis game made a big deal as being a throwback shooter in in the 2010s, when really it was just mid2000s shooter, the game, and feeling very much like we have bulletstorm at home. Alien rage also came out during the phase where CI games finally figured out that games need to have some effort put into the them and should have more than 2 hours of content, along with the sniper ghost warrior games. \nOverall, the gameplay is pretty much a mid2000s corridor shooter, which ironically in this d', 'Great game except boss levels get more stupid as you go. Not worth the fight, even at easy level you have no ammo. I killed last 3 bosses with my pistol. Also you have to keep hearing the same dialog over and over, at level 8 I have had enough.Not worth my time.', 'Mixed', 68.13, 8.02, 17.27);
INSERT INTO reviews VALUES (1571, 218060, 1061, 'mario talks to me every time i open the game', 'While a fun game, there''s some HUGE control issues here - no keyboard friendliness and NO way to change any buttons. Makes it incredibly frustrating to play.', 'Very Positive', 93.59, 10.20, 0.22);
INSERT INTO reviews VALUES (1572, 218090, 551, 'Wargaming distilled to its very essence. AI is merciless. Read the manual and/or a guide before playing. \n\nFun fact: I kid you not, this was made by the guy who made Winamp.', 'Excessively difficult and obtuse', 'Mostly Positive', 77.86, 29.45, 3.78);
INSERT INTO reviews VALUES (1573, 218230, 330, 'You thought Battlefield was war. You were wrong. \n\nThis is war. \n\nBattles with hundreds of people fighting on each side in Combined arms battles with air and land vehicles across maps that are more than 100 square kilometres. Grab your 980ti and hold on tight, because you''re in for a treat.', 'SUPER PAID TO WIN........', 'Mostly Positive', 74.24, 527.82, 56.25);
INSERT INTO reviews VALUES (1574, 218410, 1857, 'Great game! Great if bored and just want something to play on the go casually, but you can get into the loop and spend hours! The only reason I am writing this review is because at one point they ask if you want to like their socials, and if you say no, they still give you the reward and you engage in funny dialogue, thats the right attitude!', 'I''m disappointed in this game. I expected more from a title with 95% positive reviews. It''s a mediocre tower defense game, offering typical TD mechanics with little innovation. The only unique feature is the healing mechanic, where enemies can damage your towers, and a special tower can heal them. \n\nThe RPG elements are shallow as well. There are only two types of items—armor and weapons—but they lack interesting effects. All items merely add a bonus to attack or defense. The "skill tree" offers', 'Overwhelmingly Positive', 95.75, 114.60, 4.52);
INSERT INTO reviews VALUES (1575, 218510, 145, 'Surprisingly fun', 'controls are terrible.', 'Mixed', 55.17, 1.32, 1.43);
INSERT INTO reviews VALUES (1576, 218620, 170218, 'Payday 3 was a fantastic game to remind us how payday 2 is better', 'locking my guns i paid for because i need to join a group that im already in or make a starbreeze nebula account. nonsense.\n\nFUCK YOU OVERKILL AND FUCK YOU STARBREEZE NEBULA', 'Very Positive', 87.88, 95.18, 197.03);
INSERT INTO reviews VALUES (1577, 218640, 2920, 'Early childhood education is this important.\n\n\n패륜 시뮬레이터.', 'I stopped playing at chapter "Fatal Affair".\n\nWhile I absolutely love the concept of this game, it is so hard to come up with ways to kill in a massive house without any tips. Sure, you have a notebook but Lucius doesn''t write anything down unless you have seen something specific. If the game had a better notebook or better tips or even highlighted items in the house, it would be a lot more fun. I don''t like running around for hours in a huge mansion and having to end up looking at the wiki page', 'Mostly Positive', 79.73, 48.12, 3.50);
INSERT INTO reviews VALUES (1579, 218680, 5027, 'It''s incredibly good. Reminds me of my childhood on the Nintendo DS. That''s all I have to say. Very fond memories, would recommend.', 'I can''t recommend despite this game RULING.\n\nGame will hard crash, it will be an entirely white screen, game will not respond, and task manager itself cannot cleanse my PC of it when it does this. Requires PC restart. Makes me sad.', 'Very Positive', 93.63, 17.05, 0.27);
INSERT INTO reviews VALUES (1581, 218740, 160, 'It''s a fun little game.', 'Oh good, yet another timed sequence where if you don''t hit 50 perfect jumps in a row, you have to restart the level... \n\nGorgeous graphics and music don''t offset how relentlessly tedious this game can be.  And I liked VVVVV!', 'Mixed', 69.38, 0.67, 11.85);
INSERT INTO reviews VALUES (1582, 218760, 277, 'Super easy to learn and a lot of fun if you love to create.', 'Doesn''t work on Windows 11.', 'Very Positive', 88.81, 19.23, 12.20);
INSERT INTO reviews VALUES (1583, 218820, 801, 'Its great, played thru the whole game, a bunch of things could be better that are explained in other reviews. not that long ago there was alot less on steam in the pixel art platformer department and this was a stand out for its time of release', 'Everything about this game is awesome but the Timer kills it. Unless you like speed runs you will not enjoy this game. I would not mind the timer so much if they gave you enough time but they don''t. What makes it worst is there are branching paths you can take and you will not see most of them because you are trying to beat the timer. \n\nI beg for an update that removes that timer because this game looks beautiful, but the timer makes it unplayable.', 'Mostly Positive', 73.91, 173.18, 0.88);
INSERT INTO reviews VALUES (1585, 219150, 37156, 'I don''t know who I am.  I don''t know why I''m here.  All I know is that I must kill.  This meme fits the game perfectly.  I don''t understand what the story is talking about even after two runs, but it doesn''t stop me from enjoying the beauty of pure violence.  This fast paced game is straight to the point, to kill or to be killed, hesitation is defeat. \r\n\r\nAchievements requires some effort but not really that difficult.  Chapter 5 is your best friend for collection related achievements.  Don Juan', 'Honestly, I have never played a game that I like the idea of so much but frustrates me so quickly that I just quit after only a few minutes because of the absolutely insanely inconsistent AI and the janky gameplay.', 'Overwhelmingly Positive', 96.79, 22.70, 0.33);
INSERT INTO reviews VALUES (1586, 219190, 317, 'great retro pew pew aesthetic with decent bunch of upgrades, but has poor clarity and legibility of threats during fights.. there''s perhaps too much neon stuff flying around to understand whats what..', 'Half the times I was hit or died were solely the cause of enemy attack colors blending in, appearing out of thin air, or just being choppier than any other title from Puppygames. The strobing effect can be disabled, but the base graphics are no less spasmatistic and eye-burning.', 'Very Positive', 85.80, 3.75, 4.77);
INSERT INTO reviews VALUES (1587, 219200, 182, 'Puppy games never disappoint in not disappointing us . Woof Woof. \n\nI could have finished the game a lot earlier but I fell for the cuteness of these miniature futuristic droids that were spamming my screen with beams and bullets. So it took me but time. \n\nOverall, it felt like a joyous roller coaster ride that is neither too fast nor too high, but just a ride that will bring you back to the starting point in a wham. In between, you may get a little bored but when the finishing line seems to be ', 'Can''t get it to run in fullscreen, even after following the suggestion in the pinned post. :(', 'Very Positive', 83.52, 24.00, 0.18);
INSERT INTO reviews VALUES (1588, 219640, 22059, 'As I wander the lifeless maps, I recall epic battles that used to take place, now just empty halls echoing the glory of what was. Grounds that used to be defended adamantly are now easily toured at leisure. How did we come to this? At what point did we let go of greatness in favor of mediocrity? The sad truth is not many of those who''ve succumbed to the decline will ever even realize what they''ve lost. Lament for the loss of what was, and dread what is to come.', 'Abandoned game from a company who incited a content creator to suicide for criticising the developer.\nRIP Soter Dave', 'Very Positive', 81.45, 85.80, 32.65);
INSERT INTO reviews VALUES (1589, 219680, 1138, 'Though I am (in my opinion, justifiably) bitter about the devs making billions and then simply abandoning the game, I must admit that this game taught me to be a man, go to war, die for my country. Consider a six-pack of cough syrup for a 3-D experience.', 'frankly, i got this in lieu of a textbook for a ludomusicology course. it''s more of a walking simulator with zero objectives... except maybe make "music" by "walking" past in-game objects. i can see why ludology academics salivate over this game''s contribution to emergent gameplay, but i''m not quite sure if i can call this a "game"... more of an interactive artwork? a virtual exhibition not dissimilar to dc''s artechouse, perhaps?', 'Very Positive', 82.69, 1.82, 1.25);
INSERT INTO reviews VALUES (1591, 219740, 32311, 'Hands down, the absolute best, most addictive game I''ve ever played. The tension between having to explore in order to learn how to do new things and not wanting to die makes you actually care about each decision you make, and dying HURTS. Just don''t look up "how to do stuff" on the internet, it will ruin the game for you. The whole point is to have to learn how to do things by yourself. And die trying. And curse a lot. And restart with great vengeance and furious anger.', 'I''m going to break the mold a little bit and leave an honestly-negative review. I really enjoy challenging open-world (ish) survival RPGs, but this title, while endearing and interesting, was just far too annoying. Mildly punishing, sure, and I know that it requires a careful, time-learned balance to increase survivability, but...all of the various cycles and gameplay mechanics just felt tedious and I had a hard time determining what should keep me engaged. I am fairly critical of cartoon or cut', 'Overwhelmingly Positive', 96.22, 247.57, 2.27);
INSERT INTO reviews VALUES (1592, 219760, 249, 'I think this might just be a hidden gem of a game for me. Not sure why this gets Mixed reviews when it’s clearly superior to the first game, albeit with its own quirks. \n\nBeyond Divinity introduces gameplay elements I’ve never seen before in an RPG, the most fascinating of which being the ability to essentially create your own abilities, tailoring them all the way down to what icon represents them. \nIt does have its difficulty spikes so I recommend saving regularly and/or lowering the difficulty', 'Gameplay wise it''s the same as Divine Divinity. It works well enough but just has some problems purely because of how old it is, but none of those problems are unfixable. The reason I''m leaving this negative review though is purely just because of how boring and drawn out the story is. I''m almost 12 hours into the game and almost nothing has happened story wise. You wake up in a dungeon with the task "escape" and then you spend the next few hours just running around a labyrinth with no story pro', 'Mixed', 45.78, 2.47, 11.58);
INSERT INTO reviews VALUES (1593, 219780, 1663, 'Five homeless people began "Power Ranger Posing" in front of me, before fucking obliterating my ass. 10/10 best experience ever.', 'Traitors larian studios who spat on my real-time & real-time-with-pause childhood. 0/10. Larian, go f yourself with your turn-based trash that destroyed a sequel. And that a-hat who labels it as funny - why the hell are you here? This is a real-time game, not a turn-based one... go back to your turn-based rubbish.', 'Very Positive', 80.16, 42.25, 37.43);
INSERT INTO reviews VALUES (1594, 219830, 1811, 'Steep learning curve.\r\n\r\nNobody will read my review so I Will Eat 1 Tablespoon of ketchup For Every Like this gets.', 'The game is legitimately incredible.\n\nThe player base sucks.', 'Very Positive', 82.00, 4.40, 37.82);
INSERT INTO reviews VALUES (1595, 219890, 9842, 'Honestly, Antichamber is indescribable, but I played it in 2013 and loved it. Then I forgot the name of it, but it left a mark on my soul.\r\nEventually I had one of those random thoughts while doing dishes like "No way, Antichamber was the name of that game" and then I bought it again to experience the wonder.\r\n10/10', 'because there is no way to rebind, i now cannot progress because it needs me to press middle click.\r\nwhy would you not put the option to rebind keys in your game?', 'Overwhelmingly Positive', 95.05, 3.85, 3.55);
INSERT INTO reviews VALUES (1596, 219910, 883, 'I am about a third to a half way through Harvey''s New Eyes, and can already tell this is a recommended game based on my likes. The game is adorable, hilarious (dark and witty humor driven), and also disturbingly intriguing.\r\n\r\nI have had zero performance issues with the game so far, giving me a problem free gaming experience.\r\n\r\nI absolutely love the voice overs and voice acting. The music is also a hit.\r\n\r\nIn all, this is an easy recommend for me. If you like mouse driven games with an interest', 'Encountered the game-breaking bug, and since I try to avoid walkthroughs, wasted so much time trying to figure out what went wrong. I found out this bug has been around for years and still isn''t fixed. I stopped playing as the frustration was topped with the fact that the devs never bothered to fix it, so why should I continue to play a game they clearly don''t love. Can''t recommend with the bug still around.', 'Very Positive', 84.60, 9.20, 6.17);
INSERT INTO reviews VALUES (1597, 219990, 36642, 'I play this game because I''m too old for Torchlight, too stupid for Path of Exile, and too much of an armchair activist to buy Diablo.\n\n', 'Its a great game, but a recent update has broken the controls on the Steam Deck. If that''s how you play your games like me, I can''t recommend this game right now.', 'Overwhelmingly Positive', 95.13, 29.63, 181.88);
INSERT INTO reviews VALUES (1598, 220090, 518, 'this game has such charm and the story is so fun!! i love it so far and i really think you should try this out if you are a lover of classic point n click adventures!!', 'Not Recommended', 'Very Positive', 86.87, 2.07, 2.48);
INSERT INTO reviews VALUES (1599, 220200, 71470, 'better than KSP2 by a long shot. Unbelievably moddable. May require a NASA PC if you add too many parts. Kill little green frogs in a multitude of ways. Commit genocide under the cover of a space program. 10/10 would recommend', 'I GOT JEBADIAH LOST ON THE MUN AND THEN I CRASHED A NUKE INTO THE LIVING CENTER AND GOT FIRED', 'Overwhelmingly Positive', 95.69, 105.38, 15.95);
INSERT INTO reviews VALUES (1600, 220240, 38093, 'game good \r\nubisoft bad\r\n\r\nwhy the fuck do i need an internet connection to play a singleplayer game\r\njust to load your stupid 3rd party launcher? f off ubisoft i hope you go under', 'Hate for Ubisoft for not allowing me to play the game.\r\nI bought the game on Steam but you require to run it through Ubisoft connect that is laggy: require to login every time, sometimes fails and require to restart it, then 50% chance it will suspend my password and require to change it, then by changing it that often it''s easy to make a mistake while reentering it again and again and in result your account is blocked for 1h and you can''t play it.\r\nNice user experience!', 'Very Positive', 85.48, 18.50, 37.83);
INSERT INTO reviews VALUES (1601, 220260, 1675, 'Carried my childhood', 'broken', 'Very Positive', 90.03, 178.82, 0.23);
INSERT INTO reviews VALUES (1602, 220440, 6231, 'I love how this game uses the name Dante\r\nLike instead of Dante acting like a cool demon slayer, he just acts like how someone named Dante would act irl; Right up there with names like Hunter and Bryce', 'Gameplay and visually, this game is great but I can''t recommend it knowing that there is a Definitive Edition for consoles that is way better than this but somehow never saw the light of day for PC.\n\nI''d suggest consoles or emulator.', 'Very Positive', 91.04, 9.03, 18.33);
INSERT INTO reviews VALUES (1603, 220460, 438, 'Pretty fun game, great concept. Little rough around the edges. Hilarious how ahead of it''s time this game is in a way. It''s almost like a PvE extraction game long before that craze took off. It''s well worth it''s price in my opinion.\r\n\r\nI think my only problem with it is just that I don''t really like the respawning enemies much. They just respawn too quickly and make it less strategic to use resources. Instead you end up using things like the mag launcher to bust up sections and clear enemies. I''', 'I wish I could launch this game into space. \r\n(I also wish I could give a neutral review) \r\n\r\nCargo Commander is a pretty straightforward title. You play as a guy who''s stranded in space with the job of salvaging cargo from random other ships that collide with yours. In said ships you''ll find a bunch of random cargo, enemies, weapons and pickups. And that''s it. That''s the game. \r\n\r\nYou basically rinse and repeat the same loop albeit changing up what boxes show up via enterring random coordinate ', 'Very Positive', 85.16, 72.38, 21.83);
INSERT INTO reviews VALUES (1604, 220660, 1010, 'Better than the second one.', 'This game is abandonware.\nWhile the bones of it are good the performance especially towards the late game is borderline unplayable, instead of fixing what could have been great, the developer ditched it for a sequel, which was also ditched instead of fixed.\nDo not get it, it is only really playable with mods, there are other 4xs out there more worth your money.', 'Mixed', 41.68, 4.73, 35.62);
INSERT INTO reviews VALUES (1605, 220740, 696, 'Maybe chaos isn''t random at all—maybe it''s just the way things are meant to be.', 'Chaos on Deponia has frustrating puzzles that can feel too obscure and tedious. The humor may not be for everyone, and the story can drag on. The gameplay is often repetitive, making it less enjoyable for those not into point-and-click games.\n\nif you want it buy it on discount , its not worth the full price!!!', 'Very Positive', 84.05, 2.57, 3.42);
INSERT INTO reviews VALUES (1606, 220780, 3530, 'I''ve been struggling a lot and finding it increasingly difficult to approach games these days and it''s really gotten me down for quite a while now. This has truly been a wonderful reprieve!  The music is instantly fun and magnetic in the way it invites my attention. The design is seamless while communicating both a playful, colorful vibe while contrasting that with bleak and even dystopian undertones. TWA is a timeless work of art and masterpiece in its own right and it never stops being fun.', 'Boring. Sluggish movement, no coyote time, frequent physics bugs. Repetitive, annoying music. Boring.', 'Very Positive', 93.23, 9.92, 2.27);
INSERT INTO reviews VALUES (1607, 220820, 1016, 'Awesome game! Crimsonland on wheels with zombies. Takes ~8 hours to beat Story mode. Also works great on Steam Deck.', 'Game wont even start!', 'Very Positive', 84.55, 7.92, 0.98);
INSERT INTO reviews VALUES (1608, 220860, 1355, 'You will get a few of them right and it will surprise you when it happens.', 'It''s kind of un-fun to play. It did occasionally make me laugh. But the game encourages you to try every possibility, and most of the outcomes are uninspired.', 'Very Positive', 84.06, 3.23, 2.38);
INSERT INTO reviews VALUES (1611, 220980, 139, 'If you want to get CryEngine go here: https://www.cryengine.com/\nIt''s version 5. Version 3(the one steam has.) is subscription based, version 5 is free.', 'CRYENGINE has been a strong platform in impressive titles for years.  It contains some amazing visual technologies, and the post-processing effect defaults out of the box are great.  It comes with things like the incredibly powerful RENDERDOC utility for profiling your draw calls and timings, which is always useful in game development.  In general it is good engine for major projects and for workflows that involve multiple people/teams.  Unfortunately that''s not what their new Engine-as-a-Servic', 'Mostly Positive', 71.22, 0.13, 1.43);
INSERT INTO reviews VALUES (1612, 221020, 2054, 'Felt like posting a positive review just to combat the insanity of some of these negative reviews. This is a prime example of the brutal unfair nature of the Internet, which apparently hasn''t got any better since the 10+ years this was released. There are literally reviews on this game spouting absolute trash like "i''m sure the original dev has died" and "they cut and ran with the money"... guys, do a 5 minute bit of research like some of us decent folk have and you''ll see that one of the devs a', '\nThis game is ABANDONWARE, do not buy even if on sale.\n\nIt was a neat little city builder when it worked, and I did enjoy it, but that was some time ago and this really needs to be de-listed from the steam store.', 'Mostly Negative', 25.32, 0.42, 74.68);
INSERT INTO reviews VALUES (1613, 221040, 11634, 're6 is the best game ever it has the best story, gameplay, characters, enemies, acting and levels of all time 10 / 10 a perfect masterpiece nothing wrong with it whatsoever', 'In the Xbox 360 version, Chris and Piers had a quick time event where they passionately kissed at the end of the story.\r\n\r\nIn this version, they completely removed this section.\r\n\r\n', 'Mostly Positive', 72.72, 9570.88, 17.05);
INSERT INTO reviews VALUES (1614, 221180, 374, 'Eufloria HD is an outstanding game that masterfully blends relaxation with challenge, making it one of the most captivating indie games I''ve ever experienced. The minimalist art style and ambient soundtrack create a serene atmosphere that pulls you into its unique world. Despite its calm exterior, the game offers strategic depth, requiring careful planning and resource management as you grow your seedlings and conquer asteroids. The balance between peaceful exploration and intense tactical decis', 'This game is currently not playable on my PC. Just saw that there was a recent update and hoped it had been fixed but no. The game loads but there is no visible text. Cool game when it works but don''t waste your money on a broken game.', 'Very Positive', 89.30, 25.40, 7.80);
INSERT INTO reviews VALUES (1616, 221260, 5210, 'Used to watch jacksepticeye playing this. A very fun and nostalgic experience, can''t go wrong with this game. :)', 'Good game but achievements locked behind paid dlc', 'Overwhelmingly Positive', 95.78, 14.58, 33.20);
INSERT INTO reviews VALUES (1617, 221540, 1677, 'I only need 4 co op achievements to unlock them all. This is still the best Tower defence game around. Help me. I''m 46. This is on my bucket list. Time is short lol.', 'I came looking for a deeper version of Defense Grid and I found a tower defense that doesn''t feel like the first game much at all. There is definitely a tonal shift with the lighter but annoyingly large amount of banter and the tower design themselves. the biggest example is the Cannon tower whose looks and sound effects feel alot weaker. It is mechanically weaker too and most towers also feel weaker, but you do get more money, but that means each placement is less impactful and each tower feels', 'Very Positive', 85.21, 144.77, 2.68);
INSERT INTO reviews VALUES (1618, 221640, 11858, 'This is a really fun and challenging arcade style game where you point an arrow through obstacles of increasing speed, complexity, and shape. There are numerous levels in the game and it has a great soundtrack. Just today I completed the final stage and that stage was significantly harder than any other stage by a long shot. It took me a couple weeks of on and off playing, but it was worth it because doing well in this game is satisfying and gets you into a flow state. I would recommend this to ', 'Bad controls, too reliant in RNG, little variation on music, too short. Avoid. 5/10', 'Overwhelmingly Positive', 97.20, 20.67, 1.20);
INSERT INTO reviews VALUES (1619, 221680, 10356, 'helps with the basics of guitar. I would still recommend learning to read tab or proper sheet music, but you can get good at the technique by playing this game. If you ACCIDENTALY downloaded a cracked, pirated version of the game with all the DLC, you could ACCIDENTALY move the DLC folder from that version to the DLC folder of this version and HYPOTHETICALLY not have to pay for any of the DLC.', 'Ubisoft, congratulations! You’ve somehow managed to ruin a game from 2014—in 2025—by re-releasing it on Steam without its original content. A game that was once great is now just a hollow shell, all because you want to force players into subscribing to Rocksmith+, your greedy, overpriced service.\n\nNo, thanks, Ubisoft. I’m not interested in paying again for something I already owned, only to get less. This is just another shameless cash grab, and you’ve officially hit a new low. Greedy company...', 'Very Positive', 86.19, 73.13, 70.05);
INSERT INTO reviews VALUES (1620, 221810, 1329, 'I played this game for the first time as a young kid on xbox 360 and found myself seeking it out again over and over for years. This game is very fun and memorable with a lot of replay value and also funny! One of my favorites.', 'It''s fine, but it really doesn''t respect your time. For every minute spent working out a puzzle, there are four spent just moving around the level in the most basic manner. Walk here, climb that, jump there: repeat, repeat, repeat. Each run consists of four common areas and three character specific areas. There are seven characters and you can only take three on a run. That means you have to "play" through most of the content - most of it brain dead platforming - three times if you want to see e', 'Very Positive', 84.65, 14.47, 3.28);
INSERT INTO reviews VALUES (1621, 221830, 193, 'This is a great humorous point and click adventure game set in the same universe as the others in the series featuring many of the characters that appear through the series.  They are worth the buy if you enjoy these types of games.  It features a great set of comical characters in a fantasy world with some references to other fantasy stories and some challenging yet not to difficult puzzles.  It is worth the full price but it goes on sale often enough, and I picked up the whole bundled series o', 'https://youtu.be/2ariYgTPh60\n\nLacking some of charm and energy of the main line series there is just a lack of umph to bring players in early.', 'Very Positive', 80.83, 14.15, 0.45);
INSERT INTO reviews VALUES (1622, 221910, 27898, 'Died in broom closet, destroyed mind control machine, escaped to countryside, ignored Narrator, entered blue door, killed a baby, played Minecraft and portal, fell into abyss, entered red door, went to happy place, committed suicide to leave happy place, got lost, followed adventure line (Trademarked), turned on mind control machine, got nuked, ordered 1000 boxes, went insane, killed Narrator, almost escaped floor 760, went to Heaven.\n\nAll in 93 minutes and in that order\n427 out of 10', 'I just- Don''t enjoy it. Honestly I don''t get it. The point is to explore the number of ways you can find alternate endings, but after a few hours you''ve tried everything you can think of and it''s just boring. I''ve seen people say the point is the experience, but I don''t even find the experience enjoyable. Novel at first, but that''s it. It gives me a slight headache playing- essentially nothing.\n\nMaybe I just don''t get it, but it feels like it''s just- not really a game? It''s kind of interact-able', 'Very Positive', 92.33, 1.77, 5.10);
INSERT INTO reviews VALUES (1623, 222140, 209, 'I''ve been in Steam for more than 10 years and this one is the first game that I ever bought. \n\nVery good game if you want something chill', 'IF YOU HAVE A STEAM DECK PLEASE BE CAREFUL!!!!\n\nI know from experience this is a wonderful game. I had it on the Kindle Fire back in the day, and I am confident anyone would enjoy it. However, the issue lies with the fact that I am a steam deck user. I use another monitor (connected via HDMI) while in desktop mode, which is how I was hoping to play the game. Install goes well, no issues. I click on the game to open, and my monitor shuts down. PUDDLE is stretched vertically on half of my screen, ', 'Mixed', 68.90, 12.88, 0.60);
INSERT INTO reviews VALUES (1624, 222160, 135, ' Very short Point & Click puzzle adventure game\n\nThis was actually a mobile phone game first if I recall correctly and it shows. Instead of tapping, you just click. \nThe game is just a succession of screens with various puzzles. Some are complicate, most are pretty simple. There is a hint system which can help you if you are stuck too long but you shouldn''t need it too much.\n\nThe story is loosely based on Hamlet by Shakespeare and contains most of the characters although the art is very special ', 'Insufferable title aside, Hamlet is a fine and relatively uneventful point and click adventure. And when compared to mif2000’s Franza Kafka Video Game, this game feels like a more sincere and focused effort. The game’s over reliance on fast precision clicking puzzles makes the game difficult to recommend, but there are still absolutely redeeming qualities here too (I personally enjoyed the boss battle sections). If you liked point and clicks from the early 2010s this might something to add to yo', 'Mixed', 55.56, 3.88, 0.20);
INSERT INTO reviews VALUES (1626, 222420, 649, 'For those who grew up in the 90s or 2000s,\nwho has never been to an arcade or restaurant that had a KOF 98 machine on display... you got tokens and played this wonderful game on those arcade controls and in the end you got GAME OVER and ran out of tokens?\nAt these times you are feeling like a nostalgic old man like me too!\nand this King of Fighters 98 is without a doubt the BEST KING OF FIGHTERS of the franchise!!\nI have more memories and it was the one I played the most on various KOF 98 machin', 'This game is good, but this version is disappointing. Basically, this version is not a port, but an emulation of the arcade version. The best version of KOF 98 UM is the Playstation 2 version, which is actually a port of the game, with more content. The PS2 version has 3D scenarios (but you can also choose 2D scenarios), has rearranged music, has a gallery and you can also edit the color palette of the characters. All these extra content I mentioned do not exist in the Steam version, which is ca', 'Very Positive', 92.30, 30.40, 6.63);
INSERT INTO reviews VALUES (1627, 222440, 924, 'It''s very possible that SNK simply shot and murdered all 3 American Sports Team characters and thats why they''ve only ever been in 2 games. They''re in less games than Choi Bounge who is a one foot tall gremlin creature that runs around like a little rat and pokes you with his big claw hands. Some things just don''t make a whole lot of sense I guess.', 'This game is good, but this version is disappointing. Basically, this version is not a port, but an emulation of the arcade version. The best version of KOF 2002 UM is the Playstation 2 version, which is actually a port of the game, with more content. The PS2 version has a gallery, you can edit the color palette of the characters and you have access to the Neo Geo version of the original KOF 2002. All these extra content I mentioned do not exist in the Steam version. SNK chose the easy way to ma', 'Overwhelmingly Positive', 96.32, 4.10, 16.72);
INSERT INTO reviews VALUES (1628, 222480, 3386, 'Resident Evil Revelations 1 was great. The story was fine. This story was set between the events of Resident Evil 4 And Resident Evil 5. The graphics look good. The gameplay system was great. The raid mode was great and it was fun to play co-op with friends. It''s hard to do on solo without your partner. There is nothing much to say about this game. This game was decent and cool bosses. This game was an underrated Resident Evil Spin-Off Series. 8/10', 'Resident Evil Revelations fails to deliver a satisfying experience, feeling more like a chore than a compelling survival horror game. The gameplay lacks excitement, with dull and unintuitive enemy design that makes encounters feel uninspired. The constant need to scan environments for items quickly becomes tedious rather than engaging, and the puzzles offer little challenge or enjoyment. Perhaps the most frustrating aspect is the horrendous user interface, which is clunky and poorly designed. Ov', 'Mostly Positive', 75.25, 77.30, 21.27);
INSERT INTO reviews VALUES (1633, 222640, 356, 'Probably my favourite combat and levelling system of any tatctical RPG I''ve played, has very nice art with unique locations and characters. Be prepared to spend a decent amount of time on puzzles though, especially if you''re terrible at them like me. Definitely worth getting at full price which is good because I''ve never seen it go on sale', 'This is not an RPG, in any meaningful sense. This is a series of combat encounters, interspersed with on-rails narrative. It''s extremely boring. For example:\n\nA boss you encounter early on (the Chimera) has 999 armour (physical and magical). However, there is someone you speak to ahead of time who ''reduces the armour by 90%''. In an RPG, you might have a conversation with that person and negotiate with them to intervene in the combat. In this game, it''s automatic. The listed stats (999 armour) ar', 'Mostly Positive', 78.37, 34.05, 9.77);
INSERT INTO reviews VALUES (1634, 222660, 173, 'I had once played this game 10 years ago on my brother''s PS3. I thought I would never play it again until I looked up "spaceship rythm game PS3" some time ago and was astonished to see it still had a steam page. Super fun game with great music and awesome graphics and fun features.', 'It was OK to play this once-through, but I didn''t have enough fun to play higher difficulties and perfect my gameplay.', 'Very Positive', 86.13, 12.17, 3.93);
INSERT INTO reviews VALUES (1635, 222730, 2397, 'I say this: It was quite fun for a few hours but the fun fades out after a while.\nNice graphics and the idea is good but it becomes tedious remembering all the synergies and there is only so much you can do.', 'The tips/instructions are in practically microscopic font and there is no way to make it bigger. It''s super maddening to try to figure out how to play this game.', 'Mostly Positive', 78.18, 4.10, 8.43);
INSERT INTO reviews VALUES (1636, 222750, 2298, 'A competent RTS that transforms humanity''s closest brush with self-extinction into entertainment, letting you play weekend general without the inconvenience of actual corpses or nuclear fallout. The game''s greatest achievement is making you feel strategic rather than sociopathic.', 'I play single player, so this is only relevant to that - the game has no way to slow or pause time, which means that you, the human, are busy fighting with the interface or micromanaging your troops, while the AI is just doing things. Overall, the game has promise, but honestly I lose half my choppers to them flying right into AAA while I''m busy trying to manuever my troops into a pincer or whatever. It''s just a normal QOL feature that most strategy games offer, but I guess the entire Wargame  l', 'Very Positive', 86.64, 14.40, 3.78);
INSERT INTO reviews VALUES (1638, 222880, 35655, 'This game is pretty much dead, but every now and then you can still find a server with people in it. I just play coop, so that''s the lens I''ll be talking about the game through.\n\nMuch of what I love about this game is what many would call bad design. You die in 1 hit to pretty much anything. Explosives will kill you, your zipcode, and every neighboring zipcode. There''s one voice for each faction that''s pitch shifted depending on role (Only 2 pitches, as far as I know). The effects of armor are..', 'Was a good game but if your PC is running windows 11 like mine dont even bother downloading the game because it will literally freeze your PC because of battleye', 'Very Positive', 92.37, 144.30, 28.67);
INSERT INTO reviews VALUES (1639, 222980, 1085, 'Shocked I never reviewed this one, amazing time killer, especially for the price, seeing the screen shots still makes me feel the warm glow of my crappy toshiba laptop on my legs.', 'Utterly boring.\nI''ve only played 17 minutes in total and every second is a grind. The combat is slow and awful. The coins you can collect disappear in seconds, necessitating the need to run into enemies. There are copious amounts of places to search which end up tedious. You have to refill you ammo constantly.\nIt feels like a troll game. Surely there must be more to it but I don''t have the patience to find out.\nThere''s nothing about this game I can recommend. The graphics are beyond simple. Mayb', 'Very Positive', 86.82, 2.45, 0.28);
INSERT INTO reviews VALUES (1641, 223100, 4858, 'Close enough, welcome back Timesplitters 2\n\nNo but actually, this game contains the entirety of TS2 within it used for a little easter egg and there''s a community patch that can delete everything else and just leave you with a modern port of TS2. It regularly goes on sale for cheap, and it''s worth it for that alone in my eyes.', 'i wouldnt say its bad but its just not good enough', 'Mixed', 68.26, 0.55, 11.77);
INSERT INTO reviews VALUES (1642, 223220, 534, 'Like me, it has many issues. But also like me, it''s quite pretty and easy to control. Play it, but keep a punching pillow handy.', 'Hitboxes are not precise. Sound design is horrible.\nAs a platformer Giana Sisters: Twisted Dreams is mediocre at best.\nI would like to give a neutral rating for this game, but since I can''t - I tend more to a negative recommendation.\n\nMy rating 5/10, not recommended.', 'Very Positive', 80.90, 13.12, 3.83);
INSERT INTO reviews VALUES (1643, 223330, 399, 'My name is commander Shepard and this is my favorite pirate game.', 'One of multiple games published by BlackMark Studio using the same assets as previous Sea Dogs games \n\nThey all appear to be the same engine, assets, animations, textures and mechanics, rehashed over and over again: Sea Dogs 2, Sea Dogs: To Each His Own, Sea Dogs: City of Abandoned Ships, and most recently, Caribbean Legend. I can''t claim I understand why they''re just republishing the same stuff over and over again without so much as a texture, animation, lighting or engine upgrade, but I can sa', 'Mixed', 57.14, 179.07, 0.08);
INSERT INTO reviews VALUES (1644, 223410, 431, 'OPP baybee', 'Perpetuum is an older game from 2014.  It''s a venerable 10 years old at the time of this review.  It''s a very unusual specimen, so let''s go into what this was supposed to be. \n\nIt''s a battlemech based open world sandbox mmo survival game with an EvE Online level of complexity, you''ll definitely see some things that look a lot like spreadsheets, but there''s more action here than EvE. \n\nThis was originally sold around $30 USD plus subscription, and that model failed.  Actually they''ve since made i', 'Mostly Positive', 71.46, 1035.92, 4.73);
INSERT INTO reviews VALUES (1645, 223430, 191, 'IT IS A GOOD GAME :D like descent :D\nIT HAS GEOMOD ENGINE! SO U CAN DIG THROUGH ENTIRE ASTEROID! :D\nGREAT STORY GREAT DIALOGUE! (EVEN FUNNY X-D)\nBUT YES IT HAS SOME BUGS AND CAN BE CHALLENGING TO FIND AMMO AND STUFF BUT THAT''S PART OF THE CHALLENGE\nWINNING THAT SPACE RACE WAS ALMOST IMPOSSIBLE BUT AFTER TRYING AGAIN AND AGAIN X-D', 'Miner Wars 2081 promises epic space battles, but instead gives you a frustrating game of resource micro-management. Every amenity on your ship - from ammunition to oxygen to fuel - is limited, and runs out rather quickly. Even if the vast, bland environments were actually worth looking around, the game simply wouldn''t allow you any exploration due to your limited resources. When you finally actually do get to fighting, the balance is atrocious, with some enemies barely leaving a scratch on your ', 'Mostly Negative', 30.89, 16.63, 2.63);
INSERT INTO reviews VALUES (1646, 223450, 150, 'would be best game oat but the final achievement wont work', 'Really disapointed. You appear to need an xbox controller to even play it and even then the controls are imprecise and the actual gameplay is simple and not that psychedelic (it seems the between level bits are more psychedelic than the game itself). The game is very simplistic - like tetris with only one shape. Do yourslef a favor if you want a psychedelic game go buy Space Giraffe (or any other Llamasoft game really)', 'Very Positive', 83.33, 12.57, 0.20);
INSERT INTO reviews VALUES (1647, 223470, 38314, 'Really educational and wholesome game where you''re tasked to do different chores such as buying milk, going to doctors appointments and getting signatures for a petition. I think it''s amazing there''s a game like this to help kids learn how to complete jobs in a fun and creative way! :) <3', 'Postal dudes penis is censored 💔💔💔💔', 'Overwhelmingly Positive', 97.12, 30.05, 1.97);
INSERT INTO reviews VALUES (1648, 223490, 471, 'More fun than Minecraft, or some other building games that I''ve played so far IMHO.', 'Official release date will be 2069 with this development speed. \n\nDespite that, graphical it is nice and you can make nice structures. But it just lacks content and development speed. Do i recommend the game cause of that? No, unfortunately not. Rather spend your money on something else :)', 'Mixed', 42.68, 9.23, 16.70);
INSERT INTO reviews VALUES (1649, 223510, 792, 'An incredible experience to be honest. The mechanics are good and the story is interesting. Give it a try.', 'I appreciate what this game is trying to do, but I couldn''t find a resolution/FOV combo that felt comfortable. I kept getting motion-sick.\nSo between trying to focus through the fever-blur and feeling a little ill, I couldn''t get much into the game.\nI really like the mapping aspect, but I could not figure out how to make any useful medicines. The movement was really slippery. When I got bored, I couldn''t keep playing. Sorry :(', 'Mostly Positive', 77.90, 21.20, 0.72);
INSERT INTO reviews VALUES (1650, 223630, 134, 'i wish this game wasnt dead', 'You will have a hard time finding players. You will rarely have more than 8 people on the entire planet at any given time. This alone should be warning enough. You need human players, there are no bots.\n\nI do not know why so few players stick to the game. While I like the gameplay, it requires more patience than action. It''s about airships, and ships move, turn and fire slowly.\n\nOnly buy while it is on sale. Not because of the money, but a sale gives a temporary rise in players.', 'Mixed', 66.42, 19.80, 41.27);
INSERT INTO reviews VALUES (1651, 223710, 129, 'The Door Won''t Budge: The Game', 'you will have more fun trying to get this game working than actually playing it', 'Mostly Positive', 72.87, 2.50, 1.35);
INSERT INTO reviews VALUES (1652, 223730, 159, 'I love FLY''N it''s a very cute game, the sound affects are adorable and the art is so beautifully done. But be WARNED this game is very challenging and difficult as you progress further through it. I got about Quarter way through and had to give up, just got to difficult for me. But if you do like a challenging beautiful and cute platformer game, then i do recommend picking up this game, even though it was difficult for me, i have absolutely no regrets having it in my library.\n\nBelieve me it''s a ', 'Flyn is an absolutely gorgeous 2d platformer that includes some elements of exploration as well as slight hints of puzzling. You can get further abilities the more you progress in the game, which varies your gameplay experience, while you can also revisit older levels for 100% completion. The music enhances the relaxed atmosphere of the game and its art style should be envied by accomplished titles. \n\nThe reason I do not recommend it for the average player is that I have found the difficulty lev', 'Very Positive', 92.45, 14.98, 3.30);
INSERT INTO reviews VALUES (1653, 223750, 367, 'The developers have don a great job.  It works!  The flight model is accurate and it loads! unlike MFS', 'It is a fun game but I prefer to not sacrifice all my mortal possessions and make a blood pact with the devil to just buy one aircraft expansion', 'Very Positive', 86.65, 1187.88, 2.80);
INSERT INTO reviews VALUES (1654, 223810, 1675, 'This is a very old school game. It really shows its age and may turn off most players due to its archaic mechanics, but there''s a charm here that''s undeniable. It''s also packed with a ton of lore that comes up in the rest of the series. If you''re a fan of Ys or just want to experience some old school action adventure, this is a worthy game to play.\n\nI should also note that the game is fun to play but there are, what I think, some unfair difficulty spikes. The most egregious is the final boss whi', 'I was so close to being able to recommend this one, but HOOOOLY, that final dungeon was the most atrocious nonsense I''ve ever sat through in a JRPG. \r\n\r\nI can get over the weird nonsensical battle system, but not that disaster of an tower.', 'Very Positive', 88.24, 12.42, 9.12);
INSERT INTO reviews VALUES (1655, 223830, 2593, 'It''s basically XCOM. And I love XCOM. It''s not XCOM. Nothing is XCOM except XCOM, but this is pretty good. It can get a little repetitive, but that''s when you load your whole squad with rocket launchers and go have a blast.\n\nThe game is stable on vanilla, I tried using the Community Edition with Lore+ and Armored Assault mods, but the game crashed like every 10 minutes with those. I reinstalled and haven''t had a crash in days.\n\nIf you never played XCOM before, this is a good place to start your ', 'Why instant negative?\nThe game does not provide larger fonts in 4k resolution, I cannot read any description texts.', 'Very Positive', 86.35, 276.57, 8.02);
INSERT INTO reviews VALUES (1656, 223850, 7079, '3DMark is a popular benchmark tool. It originally was  developed by Underwriters Labs but now a separate team within UL handles 3DMark. Originally the TimeSpy component was used to benchmark graphics capabilities. Now CPU and SSD are added to the mix to balance out the comparisons.\n\nThis tool will run on Window 10 x64 fine. 4GB is fine but more is desirable.  I  have used this tool for years and it is useful to check new machines out with.', 'I have to pay extra to be able to skip the damn timespy demo... if this was a free app, alright, fair enough, but it isn''t.', 'Very Positive', 92.61, 11.52, 7.83);
INSERT INTO reviews VALUES (1657, 223870, 270, 'A straight improvement from the first game in every way. The bump system has been further refined so even though it''s not too different from the first game, its slightly more consistent with how you approach enemies and such. A lot of the foreshadowing and setup of the story in Ys I pays off really well with the climax of this game, which is surprising considering how far they can prioritize a narrative for a game that originally came out in the 80s. Exploration is also way more intricate compar', 'They somehow took the first game and made it even more insufferable -- these first two games in the series just skip them and watch on youtube these suck big time', 'Overwhelmingly Positive', 95.93, 8.55, 7.93);
INSERT INTO reviews VALUES (1659, 224040, 157, 'Real good, endearing little romp. \n\nThe Behind-the-Scenes unlocks are incredibly wholesome.\n\nIts a real shame all this talent is wasted on fucking VR "games"\n\nCome back, Twisted Pixel :(', 'They were too busy memeing they forgot to make a game that was fun to play. Love all their other games, though.', 'Mostly Positive', 75.80, 4.90, 4.90);
INSERT INTO reviews VALUES (1660, 224260, 290, 'The best free game available on Steam. It doesn''t demand a lot considering the system requirements, so it will probably even run on a potato pc. In this game, teamwork is the most important element, especially if you are new and don''t know how to handle the zombies or how to finish a map (e.g. where to find the objectives or the extraction zone). Compared to other zombie games, such as L4D/2 or Killing Floor, this one is more slow-paced, yet offers an highly realistic and tactical gameplay. The ', 'Bad game L4D2 is much much better then this game', 'Very Positive', 82.07, 2223.85, 2.87);
INSERT INTO reviews VALUES (1662, 224300, 566, 'bought the game on my sream deck and wont let me play keeps asking for me to insert disc', 'As much as I love the previous LoK games this one just doesn''t fucking do it. Monotonous slog of constant enemies that take way too long to kill with a battle system that isn''t fun at all. Backtrack through ENTIRE stages MULTIPLE (And I mean MULTIPLE) times to solve a single puzzle. Just fuck everything about this garbage. The story takes an absolute shit on itself, I''m 8 hours in and have 0 fucking answers to anything. I''m tired of hitting shit ass stone statues that don''t fucking die surrounde', 'Very Positive', 82.51, 0.23, 14.68);
INSERT INTO reviews VALUES (1663, 224460, 2488, 'It''s a good puzzle game using light and shadows. Don''t expect an action packed game. This game is mostly for the "sit down"/casual gamer. I enjoyed it. All in all it is a charming game and well worth playing.', 'The Story is gross, the gameplay is very buggy, soundtrack is awful, the artstyle is repulsive.\n\nAvoid this at all costs and save your money, the Community Manager of Compulsion Games even mentioned said ''i hate gamers'', especially and i quote "white males gamers were a mistake", which is incredibly racist and don''t deserve to have a platform on Steam.', 'Very Positive', 89.55, 2.95, 8.47);
INSERT INTO reviews VALUES (1664, 224480, 5937, 'Growing up I thought this game was hard because the youtubers i watched struggled hard while playing. Turns out that they are just incredibly dumb. Peak game though.', 'more liberal propaganda', 'Very Positive', 94.02, 5.67, 0.12);
INSERT INTO reviews VALUES (1665, 224500, 2090, 'This game was my first entry into games like Rimworld.  Its somewhere in between games like Rimworld, Oxygen not included, and dwarf fortress.  If you like those style of games this is worth a shot.  If you dont know those games, this is also a good starting place for those, as its a bit simpler but still has good depth to it.  downside is probably that there is no endgame that i know of. Mostly just survive as long as possible.', 'Gnomoria is Gnomor.', 'Mostly Positive', 74.11, 317.50, 26.48);
INSERT INTO reviews VALUES (1666, 224740, 508, 'Tl;dr version of what is going on: \nGaslamp Games is gone and won''t be able to continue the development but the community has come togheter and is working on completing the game with projects like the CECOMMPATCH (which is at the time of this writting currently at version 0.9.5) which can be found at the "CE Community Patch" steam group and the official Clockwork Empires forums. Now the community would really love to get their hands on the in-game engine access which would make their job a hell ', 'I believe this game is 100% GONE! Since the release date - Oct 25, 2016. And this is the year 2025...\nThank you for this wonderful game while it lasted.', 'Mixed', 42.91, 128.72, 36.50);
INSERT INTO reviews VALUES (1667, 224760, 6013, 'Loved this game. Phil Fish got done a bit dirty. Wish he could have conducted himself better but this game only makes me wonder what more we could have seen from him. Still, for his only title it''s nothing short of a masterpiece.', 'Fuck you Phil Fish, fall damage is the stupidest addition imaginable for this puzzle platformer. (keyword: PLATFORMER) The man has guaranteed there''ll be no sequel, and adamantly refused to port this game from the 360 library for 2 years. In the fashion of Nintendo games, it took 10 years for fans to mod this game because a dev (an indie dev, no less!) refuse to engage with their fans. \n\nIndie Game The Documentary''s coverage of Fish, despite dating back to 2012, is an indictment of triple-A gami', 'Very Positive', 91.39, 21.18, 1.77);
INSERT INTO reviews VALUES (1668, 224820, 1040, 'Really fun arcade-style game, unfortunately it''s being delisted from Steam in 2 weeks so grab it now if you''re interested. The base game is on sale for $1.39 and the DLC is $3, I recommend both.\n\nEdit: The game is relisted, and back in the hands of the original devs! I still highly recommend it.', 'I know this game has mostly positive reviews, but for me, it''s mostly an exercise in frustration. I hate being time in video games, so this makes me feel like I need to hurry; yet the entire game is designed to be a literal death trap. PLUS the game is literally insulting you the entire time, which doesn''t help. I barely have any free time anymore, so this isn''t my idea of fun. \n\nUnless you have an ocean of both patience and free time, I would not recommend getting this game.', 'Overwhelmingly Positive', 96.73, 91.17, 6.85);
INSERT INTO reviews VALUES (1669, 224860, 223, 'Arma Tactics\n\nHas a total of 6 trading cards.', 'Game was alright when it was released 10 years ago but playing the game now is impractical. Due to some online server down that''s needed to allow the game to run, the game cannot be booted as it has an "ERROR (ERR_REGISTRY_EMPTY)". This game is no longer longer playable.', 'Mostly Negative', 32.74, 1.20, 1.58);
INSERT INTO reviews VALUES (1670, 224940, 465, 'So many years we wait for any life sign from the series...\nGuys, the Copium Tanks are finally emptied and the coin landed on it''s edge. We are back.', 'Buggy, laggy, no option to change weird control scheme.  No controller compatability despite the original game coming out on controller.  Runs better on a PS2 than on a 2.5k pc that can run Helldivers.  Apparently if you mod it it fixes these issues.  My advice?  Wait until it goes on sale for 2 dollars like I did, incase you cant mod it', 'Mixed', 63.44, 1.60, 0.18);
INSERT INTO reviews VALUES (1671, 224960, 1823, '+ can softlock\n+ can unintentionally skip half of the level\n+ cutscenes don''t work\n+ janky controls and camera\n+ perky tits\nit''s all there', 'Stupid clunky hoe proves the nostalgia blindness people have for older games with these Mesopotamian age controls.\nWhy does a successful jump feel like a luxury?!', 'Very Positive', 83.49, 16.40, 12.35);
INSERT INTO reviews VALUES (1672, 224980, 515, 'This game takes Lara to Egypt in a story-driven. Its intricate puzzles and interconnected levels are rewarding but can feel frustrating at times. While the graphics capture the ancient setting well, the stiff controls show their age. Despite its flaws, it’s a challenging and memorable entry for classic fans.', 'Compared to other parts, the game starts.\nHowever, the resolution is so bad that I couldn''t play it', 'Very Positive', 81.36, 26.28, 0.12);
INSERT INTO reviews VALUES (1673, 225000, 318, 'A nostalgic trip through Lara Croft’s past adventures, weaving together untold stories with familiar gameplay. Though it doesn’t reinvent the formula, it’s a solid entry that gives fans more of what they love—clever puzzles, action, and exploration. It''s a fitting, if bittersweet, continuation of Lara’s legacy after the events of The Last Revelation.', 'The game doesnt even start.\nA quick black screen and you think the game is starting now. No... You are just too spoiled by other games.', 'Mixed', 69.81, 12.30, 0.17);
INSERT INTO reviews VALUES (1674, 225020, 675, 'SooOooO i personally don''t like the game its controls are horrific and the fist time i load it it would even play as i got an error massage i had to downloaded an external component form a 3rd party to get it to work ! \n\nthe reason i leave a positive review is because my mother loves this game and the whole tomb raider series and if i say something bad she wont talk to me ever again', 'Well, Tomb Raider fans know what''s going on with this game.\nIt''s not my thing. The controls can make you really aggressive. Starting the game is also scary.', 'Mixed', 58.52, 25.32, 2.17);
INSERT INTO reviews VALUES (1675, 225080, 16310, 'I love this game. The graphics feel like I''m in the 2010s. The gameplay is great, but it gets annoying sometimes when I play with one controller with the two characters at the same time. Some of these games have graphic content, just a bit of detail. The graphics were amazing. I love the story and some of this story is sad. I highly recommend playing with your controller. If you don''t have it. Just play with your keyboard. Some achievements in this game are pretty easy. I really do this original', 'This game I''m sure is very good. I bought two copies so I could play with my Brother. .... BUT IT''S NOT CO-OP!!!.  There''s a remake that actual local co-op was added and a warning "Brothers: A Tale of Two Sons remake was originally designed as a single player game''''.', 'Very Positive', 94.43, 2.82, 0.40);
INSERT INTO reviews VALUES (1676, 225160, 1801, 'Great game if you want to learn about Japanese and Chinese history, it''s really faithful.', 'this a good game. it seems broken cuz of an update. i can''t play the game tired unistalling the game restart my computer and steam. it still doesn''t work  if your interested i''ll recommend you wait until they update the game.', 'Very Positive', 89.56, 7.50, 1.12);
INSERT INTO reviews VALUES (1677, 225260, 5685, 'Look it isn''t perfect, it''s not very hard, it has some pacing issues, and even a little buggy.\r\nBut its got great music, a unique timeless type of look and good voice acting. \r\n\r\nIt''s hard to describe but you really want to give it a chance!', 'If you got a PS3 or a 360 this game is amazing, If you are rocking modern hardware this game is kind of a disappointment, It doesn''t run well and tends to crash unfortunately which is sad, because my memories of this game are very good, It''s just no one cared about PC ports back in 2013.', 'Very Positive', 93.60, 10.43, 0.28);
INSERT INTO reviews VALUES (1678, 225280, 269, 'Incredible execution on the voodoo theme. Outstanding overall design. GG!', 'Refund requested: it claims to offer local co-op play, but the local co-op entails you spawning as a shadow clone of player 1, with no options to have your own character. You can''t customise as player 2, you can''t grab items, you can''t interact with in-game objects, and you ''spawn'' as part of player 1 (i.e. you share a health bar, you share the exact same gear and set-up, and you are differentiated only by being a ''shadow'' version of player 1''s character).\n\n', 'Very Positive', 85.13, 32.48, 0.23);
INSERT INTO reviews VALUES (1679, 225300, 923, 'The butler in Lara''s mansion made me cry as a child because I could not understand how he could find me wherever I hid. \nNow I could finally get my revenge by locking his a$$ in the freezer. \n10/10 Trauma resolved', 'bullshit, controllers dont work with this, i want a fucking refund I''m definitely getting the remastered one', 'Very Positive', 85.27, 1.98, 0.20);
INSERT INTO reviews VALUES (1680, 225320, 557, 'Tomb Raider 3 has a plot that is the same as the first Tomb Raider, it lacked originality!\n\nBUT... What was different? Lara''s voice, weapon sounds and graphics improved by about 10% compared to its predecessors, but the graphics engine is still the same!\n\nThe only thing I found really ridiculous was putting the monkey in the game to give Lara the freedom to shoot and kill the monkey!\n\nAnyway, Tomb Raider 3 Adventures of Lara Croft is an excellent game!', 'Only if you are a big fan of Tomb Raider. The game is extremely hard, it requires to have a guide or walkthrough. I believe it is a waste of time without it as it will take a huge amount of time to progress through the game, mostly by trial and error. There are far better and more balanced games out there.', 'Very Positive', 84.56, 8.62, 48.57);
INSERT INTO reviews VALUES (1681, 225360, 381, 'Fun vampire game! It can be little janky at times, dialog is sometimes a bit cringy, and the graphics are definitely NOT top of the line by any means. That being said, the art style is cool (kinda cell-shady), and once I got the hang of the different powers and movement (even though it doesn''t always work the way you want it to), I found it fun. Not bad for a nearly 10 year old game.', 'I finished this game because I wanted to play something random in my library. Please do yourself a favor and don''t suffer through it.', 'Mixed', 48.56, 12.35, 4.85);
INSERT INTO reviews VALUES (1682, 225420, 575, 'This game was ahead of its time. Nowadays of course there are better alternatives but it is still very nice and nostalgic to play.', 'I love the genre, but this game''s controls and mechanics make it unplayable for me. I tried 2-3 times and every time I start with some new hope I get to like this game, I fail :]', 'Mixed', 54.09, 9.43, 2.82);
INSERT INTO reviews VALUES (1683, 225540, 43037, 'Mass destruction goes brrrr. I don''t even know the story behind this game, I''m here just for the chaotic gameplay.', 'Needs constant internet, I can''t play in remote areas. Offline only works for a while then I''m kicked off..\r\nI did not buy a game, but an online service. Why I can''t play a game that I bought?', 'Very Positive', 86.09, 3.07, 51.37);
INSERT INTO reviews VALUES (1684, 225600, 1853, 'Please add sex with Big Tiddy Goth Chicks', 'Had some potential but in the end... the fat lady always sings.', 'Mixed', 69.94, 1.80, 13.78);
INSERT INTO reviews VALUES (1685, 225640, 1084, 'This game is huge. I''ve never finished it and I''ve started it probably a dozen times with different characters. There''s always something new to run into and the game''s open world lets you decide which direction to go next,', 'This game''s camera controls make it utterly unplayable.  There might be good game play under there somewhere, but no one will ever find it.', 'Mostly Positive', 75.74, 321.33, 0.50);
INSERT INTO reviews VALUES (1686, 225840, 119, 'This is the best "Where the fu c k  do I go" game ever', 'https://www.reddit.com/r/HalfLife/comments/4nd8ao/savesvencoop_sven_coop_developer_controversy/', 'Overwhelmingly Positive', 95.80, 37.70, 2374.55);
INSERT INTO reviews VALUES (1687, 226120, 140, 'Short and sweat, you can knock out a game in 30 mins or so, shame there''s no save on exit/autosave as lost a cracking game to a crash, but for what it is, it''s fine', 'Not much can be said for Weird Worlds: Return to Infinite Space and that is exactly its problem. There is little to no content within the game and many of the events are uninspired and random, with some items making slight differences in changing said events or battles. There are no incentives to continue playing after one''s first playthrough, irrespective of scoreboards and the possibility of experiencing events ever so slightly, so why would any consumer buy this product unless they want to ge', 'Mostly Positive', 75.71, 10.03, 1.25);
INSERT INTO reviews VALUES (1689, 226560, 379, 'I am still playing through this, but I am giving this one a recommend as I have been having fun with it. It is fairly linear, but I am digging the story. I got it on sale and I recommend you do the same.', 'No save game slot except current game. You can get trapped and have to start all over from begining. Story gets weak at the end. End levels aren''t fun and seem cheap. DLC is terrible. Just made to be near impossible difficult. I hate the art style IMHO. Nor really a prequel.', 'Mixed', 55.67, 2.03, 17.42);
INSERT INTO reviews VALUES (1690, 226620, 752, 'A wonderful little game with tons of replay value. I have spent a long time replaying it.', 'I discovered this game by reading a book about procedural generation and was interested by the novel mechanics and to see how they implemented what I read about. In Desktop Dungeon you regain health and mana by exploring, which quite refreshing.\n\nHowever, the dungeons are not very well designed, and you can end up more often than not being forced to over-explore at level 1 without sometimes even finding opponents that you can fight in a decent radius. Another set of "problems" I ran into was som', 'Very Positive', 86.84, 1248.37, 8.87);
INSERT INTO reviews VALUES (1691, 226700, 7859, 'Pretty intense game. Nice survival mode. Haven''t played in a while. Going to see what''s changed since I last played. You gotta watch your back on this game. Can''t trust anyone.', 'game was good in its prime with friends, but was always known as "Scam - the Game" definitely dont download or buy anything from these devs lol', 'Mostly Negative', 31.28, 262.40, 140.72);
INSERT INTO reviews VALUES (1692, 226720, 923, 'Get it on sale. not the most amazing game and defo a victim of its era in gaming 2012 ish games. but it has enjoyable enough characters and some neat gameplay and story ideas. \nnot as good as lost planet 1\nLost Planet is like a beautiful quirky Anime OVA and Lost Planet 3 is the tropey western netflix adaption.', 'It still makes me sad that we went from Lost Planet 2 to this, I was disappointed back on my Xbox and i''m still disappointed now in 2025 on my PC.\r\n\r\nThe gameplay is okay, But they forced it to be something it wasnt. This was never meant to be a deadspace ripoff but here we are . . The last Lost Planet, Murdered cause some loser who had power at the time decided to change the formula.', 'Mixed', 61.32, 10.02, 8.48);
INSERT INTO reviews VALUES (1693, 226740, 692, 'You can kill and eat a child.', 'I really enjoyed the concept, a choose your own adventure where not only do your choices determine your development, but your environment''s too. However, the game is just way too short. I reached the "best" ending in under two hours with next to no effort. The $10 entry is much too expensive for this fairly shallow experience. I do appreciate the honesty by using the Casual label though.', 'Mostly Positive', 77.75, 5.60, 2.17);
INSERT INTO reviews VALUES (1695, 226820, 249, 'I usually play RPGs, crafting and survival games. I sometimes forget how diverse and totally different games can be. This game is 9.5/10. It''s a blast, the story is great, the puzzles are really challenging and you often feel like a story book detective. A few minor things where needlessly difficult to spot (looking at you hammer), otherwise it would have been 10/10. The whole experience was very challenging, meaningful and fun, and rather creepy at times. I highly recommend that even if you fee', 'Probably my least favorite. This one is a bit creepy, music is really good and puzzles are quite hard at times. Story is awfull, in my opinion (and my friend''s), it''s really blank and gets worse near the finale. It''s REALLY dark in some areas, to the point you sometimes miss the important items to progress. Overall it''s ok, but i wouldn''t recommend it.', 'Very Positive', 94.38, 14.38, 7.73);
INSERT INTO reviews VALUES (1696, 226840, 4504, 'Since I absolutely loath AOW4 and all of its lorebreaking and forced parity etc. I have come back to this old and dear friend.\r\nOne of my favorite games of all time, probably in the top 3.\r\n\r\nIt is still a great game to play! Highly recommend for new players!', 'game is pretty ok, not worth full price. Now there is this bad log in thing. I dont want to be forced to log into a game thats gonna be played offline or single player. I bought the game when there wasnt a log in, but now there is a log in and I cant return the game.', 'Very Positive', 82.13, 1241.98, 0.65);
INSERT INTO reviews VALUES (1697, 226860, 6515, 'Been a long time MOO2 fan girl.  I like the very close game play mechanics to MOO2, and the remake.  I like the variety and the beauty of the procedural generated galaxy when you begin a new game.  Truly an experience that you never seem to have duplicated which is very cool.  The diversity of Races both Major and Minor are incredible.  If you''re a Civ 5 and up fan, then this science fiction option surely will take your empire managing fix to a new exciting level.  I began the GAL CIV journey wh', 'I''ve tried to like this game but I HATE it! Let''s see, colonize a planet, invest resources into it, then it just gets ANNEXED out from under your control. Who thought that would be fun?!?', 'Mostly Positive', 77.81, 11.27, 75.80);
INSERT INTO reviews VALUES (1698, 226960, 178, 'I like the concept of Zachtronics games, but I''m straight up not big brain enough for most of them. This one however doesn''t require a nobel price to beat, it''s challenging but not impossible and very fun. \r\n\r\nYou don''t see deckbuilders as a real-time game often, and it works quite well here. The initial campaign is a bit short, but between ng+ and the two expansions there is plenty of content available.\r\n\r\nThe story is told via well drawn comic strips, and the steampunk graphics look great.\r\nOv', 'Ruined itself with an obnoxiously unnecessary timer instead of just playhing turn based like it should have been.\n\nWhy do some devs get so hooked on bad ideas to ruin otherwise good ones?  The videos and screen shots sure implied it was gonna be a good tbs... then they slapped a timer on that serves absolutely no gameplay function other than to minimize the strategic thinking.', 'Mostly Positive', 73.03, 29.48, 0.10);
INSERT INTO reviews VALUES (1699, 227000, 2314, 'A b''sodding good game even in 2024!', 'couldn''t get into this game, feel like it didn''t age very well (i tried playing it in 2023)\nnot my usual style of game i will say, so if you like point & click types you may enjoy this a lot more than i did\ngave it a shot and wanted to like it but ultimately didn''t', 'Overwhelmingly Positive', 97.41, 7.33, 0.35);
INSERT INTO reviews VALUES (1700, 227020, 155, 'If you''ve played Patrician IV and/or Port Royale 3, this is "the same, but different".  Which some might find off-putting, and which I sure as heck wouldn''t recommend at full price.  But I got it on a Steam sale for $6 USD, and it was a steal at that price.  It''s a maritime trading game with city-building elements and a nice politics/intrigue game mechanic that fits the setting along with a nice sense of progression that''s a welcome add to the series.\n\nIf you''re not already a fan of this genre, ', 'If you have a monitor from the last decade, you''ll be unable to play the game. The game launches with everything halfway off the screen. I thought it was the stupid Kalypso launcher that was causing problems, so I tried setting up an account with them to hopefully bypass it. I was wrong. It''s just the game itself. The fact that it''s still for sale is a scam. Avoid.', 'Mixed', 60.00, 105.15, 21.05);
INSERT INTO reviews VALUES (1701, 227060, 234, 'Good game, good addition to the series.\r\nWell designed scenario play\r\nSandbox is  enjoyable, AI doing good challenges, but after  so many factions played becomes a bit repetitive.\r\nExperiencing some performance issues (lag in time progress and click delay) in sandbox late phase.', 'Saw this game and liked the idea, thought I would support the developers and buy this, even though I knew it was unfinished, spent 20 euros to get it, played it a bit and then didnt play for a while in hopes that it would get improved. That wasnt the case, developement was stopped and I sat there with an incomplete game and 20 euros less. Dont make the mistake I did.', 'Mixed', 59.40, 673.85, 6.73);
INSERT INTO reviews VALUES (1702, 227080, 597, 'I think I found something special, I wish more people could see what I saw, how deep this little game really goes. But then I realized - I would not wish that kind of knowing on anybody. Theraputic', 'I give this game a rank D+ (50-55%)\nForgettable game - sadly nothing really good here..\nSee my profile for more details about my reviews.\n\nI give Papo & Yo about 52%. It is not bad, but it is quite forgettable. And sadly a D+ makes it a Thumbs Down on Steam. I don''t think my little review will hurt the Very Positive reviews, though, so if you are very interested in this game, you still should give it a try, you can get it for quite cheap on sale.\n\nNow I know a D+ in my review system says ''''nothi', 'Very Positive', 94.64, 11.58, 4.93);
INSERT INTO reviews VALUES (1703, 227100, 1613, 'Looking fuhrer good time? You''ve come to the reich place\n', 'No gameplay depth. Everything is very monotonous and gets boring after an hour of playing.', 'Very Positive', 87.91, 4.55, 3.68);
INSERT INTO reviews VALUES (1704, 227160, 1204, 'This is probably the most realistic space simulation I have ever played. \nYou spend a really long time designing the perfect spaceship, equipped with high tech engines, weapons, cargo holds, medical bays, mess halls, crew quarters, and reactor cores. You believe you''re prepared for anything space has to offer, whichso far, isn''t very much. \nAkin to NASA, the Developers are going to need a lot more funding before anything new can be discovered in the final frontier.', 'Unfinished dead game', 'Very Negative', 16.45, 11.28, 8.25);
INSERT INTO reviews VALUES (1705, 227180, 478, 'fun building game', 'This developer should never be allowed to develop a game again. It should actually be a crime', 'Mixed', 52.93, 258.98, 4.80);
INSERT INTO reviews VALUES (1706, 227200, 525, 'I played this game for 10 hours, 12 years ago, and it still sticks in my memory.', 'I liked the idea of this game, but it got fairly repetitive and dull quite fast.', 'Very Positive', 91.05, 10.62, 0.98);
INSERT INTO reviews VALUES (1707, 227220, 854, 'I bought the game in 2013, and I only played (and finished) it now. \nIt''s cool and unique, with strategic gameplay based on traps. Old, but still good.', 'Honestly: pretty weak. Maybe if you REALLY love combined tower-defense / third person hybrids... and at a discount. It was rough around the edges, some excusable (the graphics), some inexcusable (mediocre voice acting, lack of balance). Over all, I recommend you avoid.', 'Very Positive', 88.06, 15.72, 23.65);
INSERT INTO reviews VALUES (1708, 227260, 725, 'Very good app.\nHowever, I advice the devs to and new videos and photos for showcasing windows 11 on steam and their website because people might think that the app is only for old windows versions.', 'Ahhh, DisplayFusion. Don''t let my hours fool you; it launches with my PC. I don''t recommend this software because I only use it for my ultra-wide, given that it allows me to "physically split" or simulate three separate monitors. It does its job, but it''s not the best at it. Plus, the setup process is super tedious compared to software like MS PowerToys— as they''re just way more seamless and user-friendly. They just feel less complicated and niche compared to Display Fusion. \n\nMoreover, Display ', 'Very Positive', 84.69, 0.25, 0.60);
INSERT INTO reviews VALUES (1709, 227300, 126731, 'Come home tired af\nSit down in my chair\nOpen this game\nGrab the longest delivery route they got\nCommit various traffic violations and flip my truck\nSleep late at night, happy as a clam.', 'The developers wont release the Russian DLC. We just want to play the game and they let politics and petty narcissism damage what this game can be. Release the DLC, let the players have the full game already, stop abusing your customers.', 'Overwhelmingly Positive', 97.57, 105.73, 48.50);
INSERT INTO reviews VALUES (1710, 227380, 420, 'This game is more enjoyable than the original simply because when i die im not out .75 cents like back in the day. \r\n\r\nAbsolutely 100% recommend this game', 'The animation''s great and all, but the player is not watching it, they''re watching the indicator at the bottom of the screen to know what to press next. It''s like a frustrating game of Simon says. You''d probably would''ve been better off watching a playthrough on YouTube or something.', 'Mostly Positive', 75.95, 10.92, 0.08);
INSERT INTO reviews VALUES (1711, 227560, 116, 'As many already know, this is a re-launch of the original game entitled The Scourge Project: Episodes 1 & 2. I enjoyed the first game immensely, but I knew how broken and bug filled the game was. But the developers have really worked hard because dang, this game is great. It looks ten times better, runs ten times smoother, and best of all, I have not encountered a single bug. Although I played through the original twice already, this one still feels like a fresh new game. They really did an amaz', 'Update/re-launch of a three plus year old co-op popamole cover shooter.  Unless you enjoy facing countless number of generic bullet sponge enemies best to avoid.', 'Mixed', 63.79, 8.63, 4.57);
INSERT INTO reviews VALUES (1712, 227580, 1239, 'Tile-matching game, got hard at times but wasn''t too bad. Gets a little grindy, music isn''t too bad.', 'It''s not the first of a kind game I have played but honestly this game didn''t bode me well and I know its not going to for a big set of players.\n\nThe game is designed to progress on the basis of matches you make, just like an old-school 3 at once match tiles but few flaws made this game unplayable for long time.  You can''t even make sense of using your eyes in the game as some botched timer pushes the player aside to the left the more you wait for a pair. Sometimes the level gets over before it ', 'Very Positive', 89.51, 9.02, 9.88);
INSERT INTO reviews VALUES (1713, 227600, 1267, 'I came back to this  for my second playthrough and a 100% run before playing Epic Mickey as a warm-up with our favorite mouse. There aren''t really many good Disney games on Steam. I think Castle of Illusion works better as a Genesis game, but when I played it as a teenager, I initially thought it was cool—and I still do, just not as much as I used to. Some of the magic got lost in time and perhaps that was inevitable. \n\nIt''s a very simplistic platformer and can easily be finished within 2 hours.', 'i feel robbed \n2 bucks for only 3 hours game play ):\nshame', 'Very Positive', 89.27, 6.30, 3.90);
INSERT INTO reviews VALUES (1714, 227760, 199, 'peak', 'It''s bad yeah.', 'Mixed', 65.33, 15.57, 1.67);
INSERT INTO reviews VALUES (1715, 227780, 1125, 'i love the part when sam says "im about to get serious..... sam. classics." and starts revolutioning everywhere', 'Serious Sam Fusion is pretty much the same thing but better', 'Very Positive', 88.71, 1.53, 1.85);
INSERT INTO reviews VALUES (1716, 227860, 4145, 'Great idea but well its abandoned by the developers so if you want the game dont expect much more then advertised', 'I do like it, but development ended way too quickly. Definitely not worth a purchase anymore; super sad that it went this way, had a ton of potential.', 'Mixed', 55.03, 9.17, 64.77);
INSERT INTO reviews VALUES (1717, 228180, 1608, 'Honestly one of the best screen recording tools I have ever used. It is dependable, keeps improving, and has become one of the few recorders I truly trust. It has helped me so much during my YouTube journey and I am really glad my little brother recommended it to me. Thanks bro, you have been one of the few people who actually supported me through this.\n\nI definitely recommend Action! if you are looking for a solid and easy-to-use screen recorder. I only lost one video with it, which is still a ', 'Not recommended for purchase\nThe developer did not respond to the issue of the program not running, and it seems that the problem cannot be solved\nNo one needs a software that cannot run\n\n------\n\nThe program has been unable to run since the last update, and your behavior has been very troubling me. Why are there always so many problems?', 'Very Positive', 80.53, 561.00, 7.83);
INSERT INTO reviews VALUES (1718, 228260, 1256, 'Simply the greatest 4x game ever made. \n\nAnything that "betters" this will upgrade it only in terms of technological capabilities. No 4x before or since Fallen Enchantress has ever been so ambitious, and done so well. \n\nAOW4 is the closest we''ve got, but everything AOW4 has, FE already had, and then some. \n\nHighly underrated, underappreciated, and misunderstood.', 'Crashes frequently from the mid-game on.\r\n\r\nOther than that and the lack of mods, I like it a lot. \r\nSadly I don''t think it is ever getting fixed.', 'Mostly Positive', 78.74, 43.87, 128.80);
INSERT INTO reviews VALUES (1719, 228280, 8699, 'I wanted to refund the game at first because I did not understand how the game worked. I could not refund it, so I decided I am going to beat the game. I looked up guides for how to play and suddenly the game opened up to me. Currently going through as a generalist wizard and having a blast. I understand why this game is considered a classic now, highly recommend to anyone who enjoys fantasy rpgs and willing to learn.', 'I was surprised to find this game opens with a quote from Nietzsche, is very limited in non-white portraits, and contains a portrait that''s very clearly an anti-Semitic caricature of a Jewish man with a giant hooked nose. That''s an immediate refund for me. Don''t expect the modern views of BG3, this is very clearly that old school white nationalist 90s type of Dnd that was exclusive to nonwhite nonmale people trying to play.\n\nhttps://baldursgate.fandom.com/wiki/Portraits?file=Dwarf_%28male%29_MAN', 'Very Positive', 92.39, 31.20, 0.25);
INSERT INTO reviews VALUES (1721, 228380, 17786, 'Not many games are pure dumb fun, but this one sure is. The less you focus on winning and the more you focus on causing chaos, the more fun it becomes.', 'Personally I would not recommend if your playing outside of multiplayer. For the most part the AI drives like any other AI in any other game minus the part where they have any disregard of other drivers when rounding corners. In my opinion the AI doesn''t drive Agressive/reckless enough. Nor do they drive different lines, as they will all default to the same driving line. Which honestly makes playing with them the same as any other racing game. All I''m saying for a game about wrecking, the AI dri', 'Very Positive', 87.30, 74.87, 5.42);
INSERT INTO reviews VALUES (1722, 228400, 1707, 'This was my entry game to the Ace Combat franchise, I understand it completely ruined the experience for the AC fans but this game held a special place in my heart.\nI loved this game as a kid.', 'I''ve tried to play this game on three, maybe four, different occasions. I think this is the last time i''m installing it. It''s a terrible game. The dog fighting mechanics is discombobulating.', 'Mixed', 49.21, 11.20, 2.93);
INSERT INTO reviews VALUES (1724, 228760, 690, 'I still remember looking back to this in 2014 and admitting that I will never have the money nor the specs to play it. Years later, the inner kid was fulfilled. The game is fun but not as much as the OGs.', 'Evil ubisoft scammers stole my license to the game and are holding it hostage, even with original proof of purchase. Password to unnecessary secondary Ubisoft account mysteriously changed and they refuse to recover, not bullshitting.. Unfortunately... Worst publisher in the business.\n\nCommon issue if you read around.', 'Mostly Positive', 78.12, 5.38, 28.78);
INSERT INTO reviews VALUES (1725, 228960, 208, ' This game deserves a sequel.', 'I found that the user interface, particulary the mouse control/selection has a lot of issue. The art direction is top-notch, but the gameplay itself gets meh very quickly. The randomness of the result of some actions is very annoying, as it will make or break a game too often. Doing all the right things and losing because all of the enemies are in cover, and missing every single 80% "roll" is no fun at all.', 'Very Positive', 90.38, 12.15, 1.28);
INSERT INTO reviews VALUES (1726, 229480, 802, 'All the fun of Golden Axe (complete with half naked, well oiled human barbarian) , Streets of Rage, Metal Slug, Battle Axe , and Wild Guns. Do yourself a favor and play this with a controller , put on some headphones to enjoy the tunes, and relive those classic Friday evenings after school playing your Genesis until 3:00AM. \n\nI give this 4.5 fireworks out of 5!', 'It says it has full controller support. It does not.\r\nShitty cash grab port.', 'Very Positive', 84.91, 3.35, 1.08);
INSERT INTO reviews VALUES (1727, 229520, 196, 'Dungeon Hearts\n\nHas a total of 5 trading cards.', 'Frustrating match-3 game with repetitive gameplay, poor controls and overwhelming difficulty', 'Mixed', 63.27, 0.87, 1.80);
INSERT INTO reviews VALUES (1729, 229580, 584, 'Not really the most fulfilling experience. The OST is nice, and some of the visuals are cool, but most of the puzzles are just tedius. I wish there were more to adventure. I got lost quite often and sometimes level''s bugging or items not working properly led me on when I should;ve been able to figure things out. I can''t really wholeheartedlly recommend but if it seems appealing and is cheap it may be worth it. Game crashes semi often though.', 'Extremely slow-paced with a lot of confusing parts.  No real hints or "ah-ha" moments on solving puzzles.  Graphics and textures are appealing to the eye and the soundtrack is a plus.\n\nThe story appears weak, unstructured, and no clear objective or goal to accomplish, just a lot of wandering around.\n\nSimple review and not worth much detail, but I can''t recommend this game to anyone, even for free.', 'Mixed', 53.77, 9.42, 0.45);
INSERT INTO reviews VALUES (1730, 229600, 101, 'Just played it while I was drunk and somehow it was good.', 'This game was released before Itch(dot) io existed. A shame, as that was the place for an interesting experience like this to be. Unfortunately, I can''t give a positive review for something that should be for free.', 'Mixed', 48.51, 0.90, 1.25);
INSERT INTO reviews VALUES (1733, 229870, 236, 'The fallen', 'Great game, very in depth and satisfying movement and shooting mechanics, perhaps the best in a fps game I''ve played so far. \n\n It''s just too bad it''s dead. \n\nNot recommended with its current population in NA .', 'Very Positive', 81.36, 37.92, 1091.32);
INSERT INTO reviews VALUES (1737, 230050, 3522, 'Gameplay wise nothing to write home about, but still hilariously relevant in terms of the video games industry. Good for a quick and cheap laugh.', 'Incredibly superficial nothing game making a incredible heavy handed one note point. Its a basic as heck platformer (and not fun) that even 11 years ago you could have found some amazing projects for free with some actual depth to them.\n\nThis should have been nothing more than an animation on youtube. The fact they charge for this only serves to be a hypocrisy of its own point really.\n\nPretty sure I had this as part of a humble bundle way back when, but this being in it adds no value, probably o', 'Very Positive', 86.23, 6.55, 2.55);
INSERT INTO reviews VALUES (1738, 230150, 110, 'Tự Tạo Cỗ Máy Di Chuyển Để Vượt Qua Thử Thách', 'This is one of the stranger games you can play.  You traverse through various levels using creatures made up of "legs" and "muscles".  At the start these are all creatures designed by the developer but later you make your own.  I found it to be a very interesting concept but the design was lacking.  Creatures just don''t behave like anything you would expect and getting them to do what you want is a chore.  It can become quite frustrating at times.  Designing them sounds like fun but making anyth', 'Mostly Positive', 79.09, 42.33, 12.70);
INSERT INTO reviews VALUES (1739, 230210, 190, 'Been looking forward to this for a while as a fan of Scratches and Serena, feeling great about it and very interested in the story and puzzles!\n\n', 'The game its point and click and they don''t even put a clearly description the photos look like the game its first person and like you have a walk option but in reality you cant what a waste the game have huge potential to be a first person horror game without point and click.', 'Very Positive', 85.26, 19.75, 0.15);
INSERT INTO reviews VALUES (1740, 230230, 5336, 'My wife said if this review gets 50 likes and 5 awards, she will buy a case of beer, guys help me out.', 'Great game, but purchasing it brings the Enhanced Edition along. That version is less prone to bugs, is fully voice-acted, and comes with a ton of balacing changes, additions, and improvements. So I''d say to only play this Classic version in case something is preventing you from playing the Enhanced one. ', 'Very Positive', 90.18, 2.65, 3.20);
INSERT INTO reviews VALUES (1741, 230270, 2090, 'To whoever designed these levels: I hope that once you die, you are transported to your own personal purgatory where you are forced to 100% the game for all of eternity so you can suffer for your sins. 9/10, great game.', 'Good foundation but the lack of checkpoints makes so many levels very tedious\n\nAlso annoying how the game changes the colour palette every f***ing time you unlock one and you have to change it back', 'Overwhelmingly Positive', 95.50, 17.67, 1976.55);
INSERT INTO reviews VALUES (1742, 230290, 16682, 'It is very fun and realistic, but they should add a flattening options for planets to make them more life like.', 'added 300 earths to the solar system and made jupiter a black whole, thought it would be fun untill i had to reinstal windows', 'Overwhelmingly Positive', 96.52, 90.33, 0.52);
INSERT INTO reviews VALUES (1743, 230650, 139, 'my tactics dont work because almost all my players are alcoholics or gambling addicts. GOTTA LOVE IT!!! cant blame them tho....', 'gets to 23 days then says no more memory available and stays on the white. I''m using a MSI GE66 Raider. I''ve looked for solutions but can''t find any on forums', 'Mixed', 42.45, 30.60, 14.68);
INSERT INTO reviews VALUES (1744, 230700, 1391, 'this game tricks you into thinking its a normal sidescroller until you are in the temple of the sun and then you realize this is actually the one of the most schizophrenic bastard puzzle games of all time. great game, i have psychosis now.', 'I want to like this but I can''t recommend it. \n\nIts fun to explore the ruins and it feels great to finally progress through an area and unlock more tools. The atmosphere is great and the music is a vibe.\n\nThe puzzles however are incredibly obtuse, some of the solutions are obvious and simple early on but some are impossible to figure out without a walkthrough, with the solution often being in a completely different area with no real indication. I could look past the puzzles, but the real killer ', 'Very Positive', 81.74, 2.50, 35.92);
INSERT INTO reviews VALUES (1747, 230840, 506, 'Already liked this game when I first played it a few years ago but they seem to have made some improvements with an update. The scares are a lot more intense now and the map is better. Really nice game if you''re a horror fan.', 'I wanted to recommend this game.  Their are things about the game which are good an enjoyable.  Their are some annoying bugs tho.  After iv ran through the sewer part of the game their is a metal door which is open but its bugged, iv seen on YouTube you are meant to go through it, its open but I cant fit through it I cant walk into it, its just static an I cant walk through the open door something invisible blocks my path.  After many attempts game resets an re starts install, uninstall, quite a', 'Mixed', 48.22, 3.92, 21.87);
INSERT INTO reviews VALUES (1748, 230860, 400, 'Please, please, please, make Cannon Brawl 2. Thanks. Me. - From: me. Love, me. Me. I am the greatest. Me. You have no choice - My friend over discord. I''ve known him my whole life. He dosnt have this game yet. Me.', 'Is it a fun game?\nYes it indeed is but I cannot recommend it because nobody plays it, this game is so much fun multiplayer but that doesn''t really work if there is no one to play.', 'Very Positive', 91.25, 32.57, 8.60);
INSERT INTO reviews VALUES (1749, 230980, 170, 'The mysterious 2D platformer is very easy to get lost in. The gorgeous minimalist style & distinct colors between blocks makes learning the game super duper simple - but with the randomness of the blocks, it is difficult to master. It is similar to TETRIS''d, but with a bit more depth & progression. This is without a doubt a hidden gem from an earlier era of Steam & still worth your attention today.', 'Pretentious, boring, and bad.\r\n\r\nThere''s apparently some hidden mechanics that give you a couple more hours of "gameplay".   I have no desire to discover them.  ick.', 'Mostly Positive', 78.24, 8.05, 3.83);
INSERT INTO reviews VALUES (1750, 231040, 218, 'It''s a simple indie rhythym game with puzzles and platforming but it is very charming and if you like a jazzy disco music I can recommend it for sure.', 'I can''t recommend this game at full price.  Fun for the first couple levels, then gets tedious and repetitive.  Several level breaking bugs on the last couple levels of the game that require complete restarts, buggy controls (using xobx 360), final game breaking bug that doesn''t fix even with restart on last level keeping me from being able to complete the story.  The soundtrack is good, along with the level backgrounds, and overall aesthetic but I found myself just trying to finish for the sake', 'Mostly Positive', 79.82, 4.18, 5.88);
INSERT INTO reviews VALUES (1752, 231140, 606, 'My gateway city builder to Cities: Skylines.\n\nBeware the traffic and debt monsters, as they will stop at nothing to ruin your sprawling metropolis.\n\nThere''s just something special about dropping down a bunch of building zones and watching your city grow before your eyes and trying to prevent the mayhem that ensues shortly after.', 'The ripoff\r\n\r\nWe all know this was a ripoff and a bad one of sim city. Overly complex controls and awful UI can''t be hidden by a polish which is what they tried to do, prettier graphics attempting to hide rush job mechanics.', 'Mixed', 49.67, 18.03, 0.18);
INSERT INTO reviews VALUES (1753, 231160, 3328, 'To use mouse: In Steam go to game properties > Betas > enable Compatibility.\n\nGreat puzzle platformer, you need keys to progress to new areas, but there''s no item unlocks after the intro, so your second layer of progression is mastering the Swapper tool. 6-hour story for me. The claymation art style is really cool.', 'Seems broken at the moment. I recall playing this for a bit and not finishing, but coming back to it now there''s a weird issue with my mouse cursor sticking so I can''t select anything in the menu before getting into the game. The achievements/hidden terminals seem broken too, and cause the game to crash once you''ve found one. Good luck.', 'Very Positive', 93.72, 11.57, 0.45);
INSERT INTO reviews VALUES (1754, 231200, 2317, 'Not to sound too pretentious, but I honestly never experienced a video game with this much depth, both when it comes to understanding the human condition, and as a critique of the state of our contemporary world. I guess Disco Elysium comes close, maybe. This game actually makes me see the world differently the same way depressing Russian literature did, and describes the environment of its creation the same way it did, too. I suggest recommending this game to snobbish intellectuals to make them', 'Kentucky Route Zero is a "capital A" arthouse game, which makes it a tough sell as a commercial product. I liked its themes of displacement, and the game is at its best when it is moving quickly between stunningly framed tableaux and evocative character vignettes. However, the majority of the experience is brutally slow, and I lost patience well before Kentucky Route Zero was finished introducing its large cast of characters, which muted the overall impact of the story.\n\nI respect what Kentucky ', 'Very Positive', 82.65, 11.63, 10.17);
INSERT INTO reviews VALUES (1755, 231310, 252, 'This game has been an anomaly that I saw on steam like, a decade ago, thought it looked neat, and never actually bought or played until just now when it went on sale for $3 and I happened to see it and got curious about it again. So... what is it, then?\n\nWell, it''s a neat idea for a game that was never really gonna land for most people and frankly doesn''t have enough puzzle depth to justify its abstractness, but I like the vibes and the concept enough that I''d still say it''s worth poking at - on', 'I want to like this game, it has many of that I typically like in a game, Space, exploration, and puzzles. But it feels too... abstract?  I enjoyed the side A tutorial? but the puzzles on the b side seemed less polished and somewhat broken. It was an interesting concept and I am sure there is an audience for it I am just not it.', 'Mixed', 61.51, 20.28, 1.03);
INSERT INTO reviews VALUES (1756, 231330, 535, 'Its first person indiana jones, with a bit more focus on action than puzzle solving, though there are some puzzles and traps to solve none of them are too difficult. The focus here is the FPS action, with fire fights with Nazis, Russians, and the undead on occasion. It''s a fun time with a decent enough length for the price. The gun play might not be anything to write home about but the environments and action are good for what they are.', 'This is what i am going to say about this GAME, see...\nIt tries to be Indiana Jones, see, but the execution is horrible, see. It is not just action adventure-searching for gold/treasure game, it also involves bloody puzzles, see. I just started out and i am already lost on what I have to do next, because of bloody puzzles, see. I dont want to watch bloody walkthroughs just to get further in game, see...', 'Mostly Positive', 73.46, 13.42, 0.98);
INSERT INTO reviews VALUES (1757, 231430, 27493, 'One of the greatest RTS games ever made and significantly better than 3 which is an absolute pos game. My recommendation if you want the dlc for this game is to go online and find a cheap steam key for the "all out war edition" usually around 8$. Gives you every single dlc in the game including all playable factions, so don''t waste your money on individual dlc which will cost you a fortune.', 'I don''t even know where to start. The gameplay can be satisfying at times but almost every other aspect of the game is downright frustrating and/or pathetic. Had I known that the campaign was strictly Russia vs Germany, I wouldn''t have bought it. Had I known how greedy the game is with all the microtransactions and extra dlc you have to buy for a complete game, I wouldn''t have bothered. \r\n\r\nYou cannot play as either British or American forces unless you pay extra. Furthermore, you cannot play as', 'Very Positive', 84.55, 36.07, 9.80);
INSERT INTO reviews VALUES (1759, 231740, 1154, 'Play a game of D&D without real friends and it''s little weird. Also you can even get the pizza guy to play with you.\r\n\r\nQuite a nice ''chill'' RPG, get it on sale, it''s fun.', 'A charming, silly game. However, I can''t get myself to complete it due to it''s incredibly grindy, stale gameplay of clicking the screen until the HP sponges are dead. None of the enemies are unique and changing classes mid campaign is a hassle to get them up to the proper level, especially in the late game.', 'Mostly Positive', 79.12, 10.33, 37.43);
INSERT INTO reviews VALUES (1760, 232010, 1824, 'Saving the world? Easy.\nCreating my own civilization and leading it to world domination? Easy.\nCatch all Pokémon? Easy.\nMake my way through hell? Easy.\n\nParking a truck backward? Impossible. Great game though.', 'I hate this game how do you back in to deliver the stuff', 'Very Positive', 81.25, 0.50, 1.90);
INSERT INTO reviews VALUES (1761, 232050, 824, 'Excellent game, if you like HOMM chances are that you are going to like it as well.\r\n\r\nInstall community developed patch on top of it for quality of life\r\nhttps://www.moddb.com/mods/fixers-of-the-broken-world/downloads/fixers-vanilla-patch', 'If you look at my hours played, I''m a big fan of this game. However, playing it again now after many years, it''s a crash fiesta (on Windows 10 at least). Sometimes, you get a day of playing it without any crash. Sometimes - today - it crashes almost every turn. \n\nThe game used to always have some issues in the past, almost exclusively during saves and loads. As I don''t Ironman, I didn''t particularly mind them as the game was so good. But, for me at least, they were rare. Now it can crash at a my', 'Mixed', 60.19, 79.43, 3627.38);
INSERT INTO reviews VALUES (1762, 232090, 40872, 'Killing Floor 2 is very good game,the players are very friendly,no one is toxic,you can always find a game,custom servers are also great and MONEY RAIN', 'fun game and design a nice followup to KF1, terrible execution and poorly programmed cluster f$%k hard drive bleder. a 2016 game that is 100GB and takes 10 minutes to startup the dam thing and constantly bugs and frame drops even to this day, the devs are more focused on creating hats than fixing the script.', 'Very Positive', 88.12, 339.87, 321.57);
INSERT INTO reviews VALUES (1763, 232430, 10569, 'So I played this back when it dropped. On launch, August 15th 2013. I see a lot of more recent reviews giving it some beef. I need to say my piece because its starting to annoy me. This game came out when nothing like it existed before (or least in a major release). It walked and achieved so games like What remains of Edith Finch and many others like it can run. This game was even at the heart of a huge debate online of what truly classifies as a game, the walking sim debate. It was that polariz', 'There''s not much of a game here: just walking around a house looking at things while teen drama journals are voiced into your ears. The 90''s nostalgia present in the game is nice but what little this game does could be achieved by looking at some thirty year old photos while reading a teen girl''s diary.', 'Mostly Positive', 77.26, 4.97, 1.55);
INSERT INTO reviews VALUES (1765, 232750, 1282, 'https://steamcommunity.com/sharedfiles/filedetails/?id=3104068520\nhttps://steamcommunity.com/sharedfiles/filedetails/?id=3104068562\nhttps://steamcommunity.com/sharedfiles/filedetails/?id=3104068603', 'I tried to like the game/series, I played the technomancer first and couldn''t get into either game. The combat is just so bad and not fun,', 'Mostly Positive', 73.32, 13.08, 3.38);
INSERT INTO reviews VALUES (1766, 232770, 1324, 'only my p*nis understands me', 'Looking back at POSTAL, it was never anything more than a generic, top-down shooter with much of its memorable qualities lying in its senseless violence and schizoid visuals. Although the product was made free on Steam recently, perhaps an attempt to take advantage of the unspoken market of unsupervised children on the Internet, there is nothing more that can be truly derived from shriveling POSTAL as all the controversy regarding violent video games had died in the mid-2000s and much of its ent', 'Very Positive', 86.40, 4.25, 7.68);
INSERT INTO reviews VALUES (1767, 232790, 3395, 'good game but whoever invented those wire puzzles that generate different for every player... i hate u', 'I love the art, music, writing and general talent behind this game. There''s an incredible documentary about it''s development and kickstarter backing that I really recommend. Most of your enjoyment of Broken Age will probably come out of the first few hours during Act 1, where the puzzles are mostly light and the story feels really intriguing. But this game man, ooooh man this game. Act 2 is a very different story. These puzzles. They are really bad. Reallyyy bad.\n\nThere are many "Monkey Wrench" ', 'Very Positive', 82.36, 6.85, 7.53);
INSERT INTO reviews VALUES (1768, 232890, 4017, 'I connected more with the first version\n\nThat''s not bad either', ' 4/10. I''m surprised this game has mostly positive reviews. It runs poorly, the UI is barely improved from previous games, and the graphics customization is limited. I''m disappointed in it. It felt like a cash grab when they released it 10 years ago, and in those 10 years they haven''t done anything to improve it. If it wasn''t for the nostalgia, this game would get 1/10.', 'Mixed', 68.68, 20.35, 40.55);
INSERT INTO reviews VALUES (1769, 232910, 2025, 'i have gotten my $10 worth of fun out of this game', 'Developers can''t even bother to properly display your splits, showing the time difference to your last run instead of your PB. Couldn''t find a fix for this anywhere, I''d rather deal with landing bugs in TMNF than the game lying to me about how well I am doing when grinding a new PB.', 'Very Positive', 83.75, 1080.38, 3.53);
INSERT INTO reviews VALUES (1770, 232950, 160, 'It''s a good game for the most part, cheap and good quality for what it is, though its easily completed quite quickly, and by modern game standards it is old in quality, so I''d strongly suggest not to play this unless you really want to or have it for a child or something.', 'Whoever designed this game has very little understanding of engineering, and their physics engine is incredibly flawed.', 'Mixed', 43.75, 7.80, 7.23);
INSERT INTO reviews VALUES (1771, 232970, 210, 'Do you remember Blue Thunder? How about Airwolf? \n\nIf so, you''re old just like me, but you''ll probably love this game.', 'I played a bit of this game years ago and enjoyed it. Unfortunately it''s recently become unplayable due to crashing when launching the game. If you read some of the reviews on the steam page and check the forums you can see other people complaining about this, and there doesn''t seem to be a fix (trust me I tried and nothing worked). I would hold off on buying until this issue is fixed, if it ever is...', 'Very Positive', 87.14, 1.00, 0.63);
INSERT INTO reviews VALUES (1772, 233130, 7929, 'Man this game is so wang, I can''t believe I missed out on this wang. Back then my computer was not wang enough to play it. But now I''m running it on full wang. And damn, even though it is an old wang, my God it still looks beautiful. It never gets old trying to dismember all the wang in this game. The wang between the characters is funny, the secrets and pop culture wang is nice to find, the weapons satisfyingly wang, and I''m surprised this quality of wang is not seen nowadays. Getting this game', 'Imagine my disappointment the first time I opened this shitty game and it was in fact NOT a Shadow the Hedgehog musou, but some gay ass Korean COD clone. 1/10. @Koei @SEGA sue these assholes into oblivion', 'Very Positive', 93.50, 20.98, 4.63);
INSERT INTO reviews VALUES (1773, 233150, 2481, '''Luftrausers'' is an entertaining arcade shooter that is a lot of fun due to the numerous variations. The game only requires 5 keys to play. The arrow keys and X. But that''s more than enough. Each game lasts a few minutes, or longer depending on how good you are.\nYou play a plane that consists of 3 individual parts that you can change and unlock, which always opens up new possibilities to defeat the hordes of planes and ships, which is the primary goal of the game. Definitely worth buying for a f', 'Crashing mess...and I am not even talking about the plane.\n\nRefunded!', 'Very Positive', 91.54, 182.77, 0.35);
INSERT INTO reviews VALUES (1774, 233190, 289, 'Underrated', 'Couch-Coop-Olayers here...\r\n\r\nFirst two levels where fun. After that it went repetetive and felt like L4D2 on wish.com.\r\n\r\nEndboss was pretty disappointing too.\r\n\r\n3/10', 'Mostly Positive', 79.58, 4.78, 5.63);
INSERT INTO reviews VALUES (1775, 233210, 129, 'It is a game illustrating a historical event which changed entire country', 'Story line is not good, could of been overlooked if Flight physics were more realistic. I would love to see more Vietnam war games because I am a Huey Fan but this one is just no good, If I could get a refund and return I would...', 'Mostly Negative', 35.66, 90.43, 1.03);
INSERT INTO reviews VALUES (1776, 233230, 1019, 'Kairo is a weird game, and I mean that as a compliment.\n\nIt''s a 3D first-person puzzle game, through and through. I don''t know why some people chose the walking sim tag, as I feel the vibe is completely different to that of games like Gone Home, Tacoma, or the Suicide of Rachel Foster. In those games, puzzle solving is almost secondary, and you''re there to soak in the detailed environments. Kairo, on the other hand, is a world made of impossibly gigantic megastructures of raw concrete that have ', 'A very vague and abstract exploration game with a highly uneven puzzle difficulty. Some of them you’ll probably solve just by randomly stepping on or bumping into things, some are straightforward symbol-matching, some can get you stuck due to technicalities (like pressing unspecified buttons in the wrong order or missing the sound of activation), while some are so out there that most guides don’t even explain them, only provide the solution. To be fair, the latter ones are usually optional, but ', 'Mostly Positive', 74.48, 6.25, 4.73);
INSERT INTO reviews VALUES (1777, 233270, 10124, 'Simultaneously one of the most generic and unique games Ubisoft will likely ever put out. It''s brevity is one of its strong points, not overstaying it''s welcome like most of Ubisoft''s games usually do. The soundtrack is fantastic, visuals hold up well and the weapons feel powerful. There is the annoyance of the having to wait for the game to check for online services which are no longer supported, here is a link to a patched .dll file to fix this issue. https://www.reddit.com/r/farcry/comments/n', 'Have to use Ubisoft Connect to play the game, and it forces synchronization of achievements. Can''t reset progress on their end, so a fresh play through is unattainable.\n\nGood game, would recommend if it didn''t need a secondary launcher', 'Very Positive', 85.71, 5.62, 7.72);
INSERT INTO reviews VALUES (1778, 233290, 4025, 'The story is good so far and I enjoy the concept. Game play is decent with pretty simple puzzles to solve. I really like the style and have found it quite enjoyable.', 'An interesting concept, but monotonous and generally boring, lacking ideas and elaboration.', 'Very Positive', 82.21, 8.83, 6.83);
INSERT INTO reviews VALUES (1779, 233310, 125, 'Avadon 2: The Corruption is another great entry in the Avadon series by Spiderweb Software and has a lot of choices and interesting characters. Also introducing a new character type in the Tinkermage. Which is personally my favorite. Overall, this is a great retro-style turn-based CRPG with a lot of fun and charm.', 'I don''t know why but Avadon 2 just doesn''t have the allure of its predecessor. Maybe I''m too old for this now, maybe it just has a much worse story/writing. I find myself drudging through the game rather than enjoying it, so I wouldn''t recommend it. The setting just isn''t that interesting and feels super repetitive and pointless. I thought I had killed Redbeard in Avadon 1? So here we go all over again? \r\n\r\n(Avernum 1 was much more enjoyable -- just finished that game before starting this one).', 'Mostly Positive', 78.40, 89.55, 19.73);
INSERT INTO reviews VALUES (1780, 233350, 451, 'If I win the lottery this game is having a remake', 'Gameplay is solid, but there are some technical issues. Camera is broken, using skills in battle are terrible, block sometimes work, robot boss couldnt be killed because restoring  thing recover full hp(i manage to kill him running from mele attack and shoot in eye). Game have potential, but rare save points, long skill animations, enemy having sponge HP, chest not rewarding, rare useful items and backtrack with forced encounters cause frustration.', 'Very Positive', 88.25, 22.55, 8.42);
INSERT INTO reviews VALUES (1781, 233370, 378, 'This is a classic old-school style point-and-click adventure with some quality graphics, superb voice acting, and a brilliant orchestral soundtrack.  It has a strong nostalgic feel of a Poirot / Pink Panther whodunnit.\n\nMy one criticism is that the puzzles are pretty simple - sometimes you feel you are just clicking things for the character to reveal the story.  However, the atmosphere and superb voice acting will keep you hooked in, and it''s worth sticking with it to the end to reveal the true ', 'Chapter 2 and 3 are MISSING!!', 'Mostly Positive', 71.96, 15.38, 31.68);
INSERT INTO reviews VALUES (1783, 233450, 33184, 'This is a fun game. It''s challenging. Although there are times where the simulation seems to be not performing tasks for unknown reasons, you can typically figure it out after some time. I''d say the biggest challenge in this game is just getting a fully functioning prison that can house 50 inmates without constant danger and incidents. \n\nYou have to really balance how fast you expand and build. It''s a lot of trial and error. Every addition to your prison needs a few days of time to settle in bef', 'Extremely intrusive EULA by Paradox. I played this a lot back in 2015 and wanted to come back to it, but then I saw the Paradox launcher and their EULA. Now I have to say goodbye to this game. Never gonna play it as long as this EULA is in effect. I payed for this game a decade ago and now I can''t play it unless I agree to let you spy on me. Terrible. \n\n"Paradox may collect information from you when you use the Game. Such information includes your SteamID, computer configuration, gameplay behavi', 'Very Positive', 89.07, 3518.42, 115.17);
INSERT INTO reviews VALUES (1784, 233470, 2832, 'This game evolves, much like the transformation of RPG games over the years.\n\n\n진화하는 게임.', 'Was really enjoying myself until the final boss. The game went from fun and interesting to ridiculously frustrating, they made a really weird/idiotic development decision at the end game. After dying multiple times and being forced out to the menu multiple times then forced to watch the dialogue over and over again, I quit and uninstalled; will never pay for another game by these developers. Trash.', 'Very Positive', 80.16, 5.63, 3.47);
INSERT INTO reviews VALUES (1787, 233550, 867, 'As a child I never beat this game. \nI''m aware if you know all the solutions within the game it would take less than 15 mins to beat this game.\n\nAs an adult this was worth $10 to me. Finally beating a game (found out I was only 30 seconds away from beating it as a child after I beat it today) I never completed before. Did it in an hour as well. Glad I got to relive the experience. \n\nNow time to watch a speedrunner do this in 6 mins.', 'I loved this game when I was a kid. Unfortunately it does NOT work on Steam Deck despite being tagged as Steam Deck verified. \nWhenever I try to load a game (I can get to the start menu fine) it crashes back to the Steam OS. \nI posted this issue a year ago and lots of people have reported the same issue (just check the Steam forums for this). There has been no fix.', 'Very Positive', 82.35, 1.42, 1.47);
INSERT INTO reviews VALUES (1788, 233610, 3976, 'Alright\nWho was it that put extremely good and compelling psychological horror in MY vroom vroom car parkour game?', 'This game looks awesome, has an interesting story presentation, and the soundtrack is a banger, but by god I just can''t recommend this game....\nThe air control and the wall jump/"grip" mechanics especially make this way too fucking frustrating.\nIf you like rage games or are just a cracked MLG nut, this might be for you. For me, it''s just fucking impossible. I can''t even get halfway through the second campaign and I''ve just hit a wall I can''t get past. So I''m done.', 'Very Positive', 93.84, 4.63, 2.57);
INSERT INTO reviews VALUES (1789, 233680, 299, 'Love the app. An interesting UI with lots of power for brush creation.\n\nI don''t mind paying for updates. But never use subscription.\n\n', 'Sadly I dont recommend this pogram, its not very friendly for new artists + I have big issue the pogram need take long time, to delete the line/backwards. When in Pain Tool Sai theres no such thing, its work immediately.\nAlso the whole gui is complicated for me as well.', 'Very Positive', 81.61, 5.00, 0.23);
INSERT INTO reviews VALUES (1790, 233700, 865, 'Достойный рогалик', 'The game is too much RNG dependent to the point is unwinnable. Too many mechanics that are mostly depend on luck.', 'Very Positive', 83.35, 20.68, 76.58);
INSERT INTO reviews VALUES (1791, 233720, 8294, 'real doctor training. i am now an overqualified sturgeon', 'this is so ass the controls are terrible', 'Very Positive', 83.22, 14.68, 0.63);
INSERT INTO reviews VALUES (1792, 233740, 2107, 'Playing this game in easy mode... and I still get my @$$ handed to me ON EASY MODE!! \r\nTEN OUT OF TEN STARS\r\nActually a great game set up as a parody of *well you know* but executed so well\r\nSPOILER\r\nradiation bad', 'The game itself is actually pretty solid but it STILL DOESN''T FULLY F$$KING WORK!!! At least 2 Achievements are STILL unattainable! A gameplay mode is STILL completely inaccessible! (I fully uninstalled the game 7 years ago, and reinstalled it this WEEK. It''s the most up to date version of the game, and even the version I was playing when I stopped because of the above issues were over half a f$$king decade old at that point.)\n\nPokemon Uranium is a fan-made game that was released FOR FREE whose ', 'Very Positive', 89.70, 6.42, 5.85);
INSERT INTO reviews VALUES (1793, 233800, 170, 'release me from my indentured servitude, i dream of arma modding, they are all nightmares, i wake up in bouts of sweat and anguish, i see LODS in the walls, "object builder has crashed" flashes in my eyes like the numbers in masons head from black ops.', 'literally the biggest piece of shit modding tools you''ll ever come across. creating something for arma will require you to go through TONS of trial and error before you''re happy with what you''ve made and even then it won''t truly be what you wanted. the tools are extremely outdated almost as if they are from the 1990s. this software is nowhere near perfect and if you ever think about getting into it, just turn back now and maybe try modding some other game because this is not the one to be wastin', 'Very Positive', 84.71, 502.75, 137.75);
INSERT INTO reviews VALUES (1794, 233840, 693, '\r\nWorms Clan Wars is a timeless gem I''ve played daily for over a decade. As someone with legendary grenade skills in the Jack Connexion , I can appreciate the precision and planning the game demands. Despite minor flaws, it’s a game that never gets old, blending chaos and strategy in a way that’s both challenging and endlessly fun. If you love strategy games, Worms Clan Wars is a must-play.', 'Worms Clan Wars is a fun turn-based artillery game, but it seems to have a significant issue with supporting the standard gaming resolution of 1920x1080. This impacts the game''s playability, on my Nvidia and Intel setups, and it''s surprising that a patch addressing this hasn''t been released yet. \n\nDespite the game''s other merits, it would be challenging to endorse it wholeheartedly until such a time when its creators attend to this critical technical matter, which in 2024 seems rather unlikely.\n', 'Mostly Positive', 71.14, 101.93, 0.27);
INSERT INTO reviews VALUES (1795, 233860, 42282, '>Started as a slave\r\n>stole a fish\r\n>ran from fundimentalists I stole the fish from\r\n>got my legs chopped off by the fundimentalists \r\n>crawled for hours through the desert\r\n>got captured by cannibal robots and got my skin peeled off\r\n10/10 worth it', 'I''ve eyeballed this game several times on the Steam store and it always interested me. I really wanted to like it. Seeing it on sale I tried to give it a shot but honestly it just seemed like an exercise in frustration more than fun. After three attempts where I got beat down by roving gangs of starving bandits (who seemed content to beat up a similarly impoverished stranger than their impoverished lackies) the game does a really bad job of telling you when you should just start a new game. \n\nYo', 'Overwhelmingly Positive', 95.05, 445.90, 1.32);
INSERT INTO reviews VALUES (1796, 233980, 1734, 'played 30 hours of single player (beat the game multiple times) and the rest is all multiplayer, really fun game IF you have someone else to play with cause otherwise MP is a grind and will take a long long time to complete. if on linux, use proton since the native build isnt updated and join the unepic games discord server to find people to play with (try not to get carried, it kinda ruins the fun). some MP maps are very bs and filled with hidden walls, multiple paths, trolls, etc so just know ', 'Spent 19 hours playing all the way to the hall, only to be blocked by the "hardest boss in game" where almost every attack can kill you faster than you can heal. Even if you managed to reduce its health to 50%, it will then spawn unkillable enemy that will constantly hitting you and pushing you off ledge.\r\n\r\nThis is not "hard but fun". This is pointlessly hard and totally luck based (unless you got that 1 or 2 correct build out of the hundred possible "wrong build").', 'Very Positive', 84.66, 170.03, 21.65);
INSERT INTO reviews VALUES (1798, 234140, 24311, 'Driving through the desert. I came across a den of wild ones on a plateau. Killed them all. Suddenly I saw a nibbled body, went to him, pressed E. Some kind of cutscene started. For some reason I thought that it was a familiar person to Max, that now he would sit and remember him with sadness, saying that this is how fate sadly dealt with him\n\nNo.\n\nMax was just hungry and stuck his hand in the giblets to eat the opryroshchis\n10/10', 'while the core mechanic is fun, the game is VERY repetetive. after the first zone you have seen it all and the story is not very original,. For hardcore mad max fans it''s probably worth the time, but that''s about it.', 'Very Positive', 91.24, 72.18, 23.27);
INSERT INTO reviews VALUES (1799, 234160, 350, 'It''s a arcade version of SSZero. One of my favorite offline time wastes.', 'hilariously terrible', 'Very Positive', 81.71, 0.27, 0.12);
INSERT INTO reviews VALUES (1800, 234190, 2135, 'this and the reciever2  is good for practicing gun handling virtually', 'Whats the point of buying this? its a tech demo', 'Very Positive', 86.84, 3.70, 0.22);
INSERT INTO reviews VALUES (1801, 234270, 1591, 'This is a game based on a book.\r\nThat being said , the story was top notch.\r\nI liked the hand drawn style and voice acting a lot.\r\nHonestly this game was a very big surprise I did not expect to get involved in the story as much as I did.\r\nLately i prefer playing games that aren''t adrenaline packed and yet keep me interested.\r\nI highly recommend this.', 'There has been a long running and rather annoying bug related to a red scarf which means you have to go back and load a pre-set game from Steam, thereby wiping out all of your choices made to that point - a fairly major part of the gameplay.  There is no way of knowing what those preset choices were, either.', 'Very Positive', 92.58, 20.43, 5.93);
INSERT INTO reviews VALUES (1806, 234390, 772, 'You''ll wonder how a cluster of 10 pixels can be so terrifying.', 'The game is broken and freezes on windows 11 .', 'Very Positive', 89.12, 35.90, 1.07);
INSERT INTO reviews VALUES (1807, 234490, 130, 'I rush onto my bros all the time.', 'Upon starting the full retail version of the game you are greeted with a EULA for what is stated to be the DEMO VERSION of the game that includes some truly pernicious terms of service and also some plainly rude language telling the customer that if you try any funny business you will incur a bunch of legal costs through arbitration, also it is unclear about the scope and nature of the data collection the game will be doing or why a simple platformer needs to store any personal information about', 'Mixed', 56.92, 0.40, 0.12);
INSERT INTO reviews VALUES (1809, 234650, 6623, 'Turn-based strategy games are having somewhat of a revival the past few years and Shadowrun is a MUST-HAVE for anyone who enjoys turn-based strategic combat. The original comes with one campaign, but to buy the game for the campaign is to miss it''s true value: it comes with an editor that allows you to create your own campaigns and it''s fairly simple to use. It ships with highly detailed documentation so even if you don''t know how to use it out of the box, it only takes 5 minutes of reading the ', 'another visual novel masquerading as an cRPG, just like Colony Ship. No decisions, u just go through screens in order and I mean IN ORDER, u can''t even leave a bar until u did everything there, most characters don''t talk, and in dialogues u need to agree to everything. Very buggy, 3h of gameplay and I''ve encountered 3 bugs. Unresponsive too, u need to wait for everything to refresh after every action (like looking at sth, or picking up an item). Fighting is like Fallout 1. Story seems good tho, ', 'Very Positive', 89.08, 3.93, 3.48);
INSERT INTO reviews VALUES (1810, 234670, 3385, 'Please add sex with Big Tiddy Goth Chicks', 'I consider this the worst part of the series, the ending of the game is not only drawn out, it is also indecently difficult, and this was done only because of the short time to complete the plot. So besides this, for all your efforts in the end you get the most sucking ending where they even forgot about Sasuke as if he wasn’t even in the plot!\r\nThe gameplay looks better than the second one, of course, but that''s all the game offers, optimization problems still interfere, and the plot looks good', 'Very Positive', 89.10, 3.08, 7.62);
INSERT INTO reviews VALUES (1811, 234710, 4097, 'https://steamcommunity.com/sharedfiles/filedetails/?id=2700910399', 'This is like playing poker in hell. Whoever invented and insists upon Claptrap''s existence should be investigated.', 'Very Positive', 86.65, 11.38, 30.77);
INSERT INTO reviews VALUES (1812, 234920, 150, 'Tried to save a guy trapped on a flaming plane. He died. Lost an arm trying to save an old woman from a jaguar. She died. Ate some mushrooms. Tripped the fuck out.\n\n10/10 would do shrooms again.', 'Art is good, execution didn''t land for me', 'Mostly Positive', 76.67, 0.48, 0.93);
INSERT INTO reviews VALUES (1813, 234940, 302, 'was amazing spectacle', 'Having read what the game was supposed to be, I was ultimately disappointed by what it is.\n\nThe painted scenes looked boringly ok. The music was solid as well as the voice acting, but the story, which was supposed to be about a man on the run and espionage, was too off point most of the times. It started with some intrigue, and goes off on tangents about the character changing his clothes and what hes doing rather than the game that is afoot. And you are not making decisions that affect the outc', 'Very Positive', 81.79, 3.08, 3.33);
INSERT INTO reviews VALUES (1815, 235210, 1324, 'Underrated metroidvania ninja game.', 'Cannot recommend this game now that they sneaked in a DRM no one asked for.', 'Very Positive', 83.23, 2.13, 12.85);
INSERT INTO reviews VALUES (1816, 235250, 603, '- This is a great Tower Defense game—challenging but well-balanced, neither too hard nor too easy.\r\n- The fun lies in creating intricate mazes to make the enemies’ path as long as possible.\r\n- However, some towers feel underutilized, almost like they’re just there for show.\r\n- Each level allows you to select only four types of towers, adding to the strategic depth.\r\n\r\nOverall, 8/10.', 'The game is alright but I find the grind for level ups just to barely complete a stage annoying like I get the game can''t be easy but sometimes it is more difficult than it should be nearing levels of impossible without grinding levels getting upgrade tokens for the skill tree to give you a smaller increase to your chances of success even turning down the difficulty to normal instead of hard makes little change. I have 6 hours on this game and only got to about stage 7 and only perfected about 3', 'Very Positive', 83.08, 49.13, 6.67);
INSERT INTO reviews VALUES (1817, 235320, 579, 'Actual peak strategy game that i have been playing since around 2003 and i always return to.', 'Without any lens of nostalgia having never played this before, and getting it with silica since the price is cheaper that way - to me it is a clunky and obtuse RTS. There''s not even really a skirmish mode with any maps to try and fight against the AI besides one map that seems to be it''s own campaign-like scenario map.\n\nWelp, shrug. Maybe back in the day it was cool for some RTS players. Now, not so much - there are better RTS''s out there - and I say that as someone who likes oldschool RTS games', 'Very Positive', 90.67, 16.90, 0.18);
INSERT INTO reviews VALUES (1818, 235360, 372, 'At times frustrating and needlessly esoteric, this is nevertheless a solid Tower Defense game with a card-collecting mechanic that tends to be a bit too random to be 100% useful. Depending on your luck with drops, you may have to spend extra time grinding some levels to advance. HUGE hint: Lightning is OP - but is also one of the most expensive towers in the game.', 'This game is a testament to what can be both good, and unbelievably bad in gaming.\n\nI -LOVE- tower defense games, to the point of friends making fun of me for playing anything in the genre now matter how bad it looks. I picked this one up on a whim and right off the bat I could tell this game was set up with a mobile market in mind. \n\nThey build RNG into your potential power by making upgrades random drops, and build the maps around having gotten said random upgrades. So inevitably, you will rea', 'Mostly Positive', 73.39, 111.70, 6.25);
INSERT INTO reviews VALUES (1819, 235380, 1444, 'Pretty good once you get the hand of goals to get experience for Troops, commit research, use of Support functions (Artillery etc). Just wish there were more units to command.', 'The developer abandoned in 2023. Their final patch was supposed to allow you to play offline after their servers were shut down, but it didn''t work. The game does not register that you have completed a mission after the tutorial. Missions unlock when you complete other missions. Do you see the problem here? You cannot progress. If you are looking to buy this game, do not. Steam should pull this game from the store in my opinion.', 'Mixed', 48.06, 55.90, 1.83);
INSERT INTO reviews VALUES (1820, 235520, 157, 'Great graphics and very interesting game play. If you like games that take a good strategy and evolving abilities your going to really love this one. It''s one of those games that once you get it you think, wow this was under priced! I''ve paid more for junk games but this one really delivers.', 'Game is pretty cool, cool sandbox aspects and all that, but the game is honestly not fun as its just a pain to get through. everything feels weak and the enemies feel incredibly strong.', 'Mostly Positive', 77.71, 7.00, 4.78);
INSERT INTO reviews VALUES (1821, 235540, 7775, 'A few facts about the game:\r\n- the original game has about 7 hours of content. If you count all DLCs it''s about 16 hours.\r\n- after you finish the game it''s just a grind to get better gear. You most likely need many hundreds of hours to get the best gear\r\n- rng is totaly stupid - you are most likely to get items for a class you don''t play\r\n- single player sucks because bot AI is broken - they often fall from ledges, they don''t do any quest action (i.e. carry bombs, destroy target), they don''t alw', 'I bought the game because it had the ''single player'' tag, so I naturally thought I''d be able to play a story mode by myself, but the only option the game gives you is online multiplayer. you can''t just play the game yourself.', 'Very Positive', 83.55, 40.87, 0.23);
INSERT INTO reviews VALUES (1822, 235600, 7729, 'Me add offline mode me  STOP CRASHING \n\nGo to properties General Tab then add this to Launch Options  -offline -offline_mode It will stop the crashing every 30min.\n\nDon''t expect any multiplayer or co-op as Ubisoft has already shutdown its blacklist servers back in October 2022 and this is also most probably the reason why the game crash every 20-30min.', 'dont waste your time. ubisoft connect is garbage, and you cant even get your ubisoft games to open, even if you have the connect app and have linked your account. how tf is ubisoft not bankrupt yet? dont tell me that clown show R6 seige is still carrying these dogs after 10 years.', 'Mostly Positive', 74.73, 49.30, 0.17);
INSERT INTO reviews VALUES (1823, 235620, 608, 'This game is very tricky and easy to understand, but VERY hard to master. (I remember playing it either as an older teen or within my earlier young adult years.)\n\nTo die for? Not really. It also has some weir,d un-neccesary glitches that need bugfix patches.\n\nBut is it worth a try when discounted? Certainly!', 'A fun game, housed in a broken, unstable platform. Would be very enjoyable if the game didn''t constantly crash.', 'Mostly Positive', 70.07, 2.60, 1.58);
INSERT INTO reviews VALUES (1824, 235660, 121, 'The best turn-based strategy ever made', 'LOL! not even worth writing anything about it!', 'Mostly Positive', 71.07, 38.33, 0.17);
INSERT INTO reviews VALUES (1826, 235800, 3353, 'This game was made in 2015, so if you''re new to this and wondering where to get MP3 files without getting a virus, I definitely wouldn''t tell you. Piracy is a crime and a  very  serious one at that. There are murderers and pedophiles on the loose in America, but God forbid poor Timmy downloads GOT Season 3, Episode 9, they absolutely need to be fined $100,000 and put into jail for 5 years because they don''t want to subscribe to Max.\n\nI definitely would never pirate any form of digital media what', 'If you can, get the original. This is worse in almost every way. Sure, they added some modularity, but the gameplay itself is worse, and the gameplay is what it should be about. \nBricks are harder to see, colors are not as easy to recognize, and the camera movement makes my head hurt. Nothing was a problem in the first one.', 'Very Positive', 80.58, 2.28, 0.12);
INSERT INTO reviews VALUES (1827, 235820, 288, 'Easy gameplay. Great soundtrack and overall very entertaining.', 'worst sonic game', 'Very Positive', 82.99, 6.43, 1.63);
INSERT INTO reviews VALUES (1828, 235900, 744, 'deciding to make a pokemon fan game will be the worst mistake of your life, so do it', 'There is no option to make text boxes appear letter by letter. Instead, text just flashes onto the textbox almost instantly. Had to install RPG Maker VX instead.', 'Very Positive', 93.55, 103.55, 8.15);
INSERT INTO reviews VALUES (1829, 235980, 154, 'It plays very differently from the original Blocks That Matter game offering challenging puzzles that are not exceedingly difficult. The level design is excellent, always introducing basic puzzle concepts early and building a foundation for the player to put them to use later in more challenging levels.', 'Overpriced considering it''s not a good game unless your around the age of 8 or the parant of one.\nGame have a serious need of more fun and inspiring mechanics.\nController is more like point-and-click which in RPG''s and some forms of arcades is fine or even realy fun, but for this game and it''s setting, it''s just terrible not to mention that even if u use a 360 (Or similiar) controller, u only change from using mouse-point and click to using the stick to move the mouse and the A-button to move...', 'Overwhelmingly Positive', 98.05, 28.88, 0.15);
INSERT INTO reviews VALUES (1831, 236090, 9060, 'An amazing game that continues to hold up even in the year of 2024. \n\nThe only bad thing I could ever say about this game was that we never got a sequel for it.\n\nI desperately want a sequel.', 'Good game. Dev is unfortunately far-right. Spend your money elsewhere.', 'Very Positive', 94.93, 14.80, 28.33);
INSERT INTO reviews VALUES (1832, 236110, 2117, 'Good Grind game not too much nor too little', 'horrible ui, \nhorrible business practices,\nyou wanna preview a skin in the shop and assume you can by clicking it? \nwell, oops you didnt pay enough attention and lost $8 by clicking too fast and support tells u all sales are final.\n\nwhat garbage business practices.', 'Mixed', 64.86, 848.67, 6.72);
INSERT INTO reviews VALUES (1833, 236130, 257, 'AWESOME', 'This is a seriously weak 4x game, along the same lines as galactic civ, and definitely a far cry from MOO 2. The interface is seriously clunky, not even having basics like side scrolling. The tech tree is pretty weak, its largely just the same set of technologies that you just add refinement to, so you never get anything interesting, just level 2 lasers, level 3 lasers, etc. The graphics are also pretty mediocre, though most people aren''t playing 4X games because they are visually stunning. If y', 'Mixed', 58.37, 117.42, 8.30);
INSERT INTO reviews VALUES (1834, 236150, 2220, 'If you like traipsing around space getting yourself into trouble while exploring, this is a decent game for it.\n\nSo while the campaign wasn''t terribly gripping, it didn''t matter much for me because with these games it''s all about the free roam shenanigans.', 'i tried to like it, but it fought me every step of the way. \nit checks all the space sim boxes but falls flat on every part.\n\nI was hunting for an "Escape Velocity: Nova" type game and this wasn''t it.', 'Mostly Positive', 72.16, 6.78, 13.28);
INSERT INTO reviews VALUES (1836, 236370, 3429, 'Bought this game so long ago it was about space sharks, now its about robots.', 'If they''re no longer going to finish the game, is it disingenuous to continue to sell it?', 'Mixed', 51.59, 3.75, 0.80);
INSERT INTO reviews VALUES (1837, 236390, 778, 'I feel like a meth addict relapsing every time i re-download this game.', 'Hail the snail. Feed it. Pray to it. And play Mother Russia if you want to have atleast a *tiny* chance of having fun. This game is more like a subscription than something you download, and you keep coming back every time because maybe it will be fun this time? It never will. Watching videos of warthunder is like drugs, but playing it is like the aftermath. You end up in your chair at 03:27 am contemplating life after getting your five millionth spaamraam up your afterburner, or a infrared missi', 'Mixed', 68.64, 623.73, 618.22);
INSERT INTO reviews VALUES (1838, 236430, 14657, '10 years ago I got invaded by a hacker named "I''ll Kill the Blacksmith" while in the safe area of Majula where combat is normally impossible on my very first run of the game. He proceeded to kill the blacksmith then left. I think about this atleast once a month. 10/10 great game even without a blacksmith.', 'Can''t even EscapismMaxx properly with this game cause my character is a twinkhon and gives me GD', 'Very Positive', 84.85, 116.37, 84.70);
INSERT INTO reviews VALUES (1839, 236450, 2945, 'I love pacman.\n\nI love crack.\n\nSo I love this game.', 'Game crashes when you hit Alt + F4', 'Overwhelmingly Positive', 95.86, 1.40, 7.80);
INSERT INTO reviews VALUES (1841, 236510, 1903, 'GOTY, best game ever made, they don''t make them like this anymore (thank god)', 'goldeneye meets rainbow six - and dont get along', 'Mostly Negative', 36.21, 1.05, 0.13);
INSERT INTO reviews VALUES (1842, 236690, 4723, 'Better than BB3. Has almost everything you need. Graphics are great. Gameplay solid.', 'Dice rolling game. Your dice are pretty random, but the AI teams dice are pretty obviously some kind of rigged.  I''ve played enough dice games, and enough of this game, to notice.  when the computer team fails a dice roll its a surprise, it will only happen a handful of times every game. You arent playing against the enemy team, you are playing against the predictable RNG of the opponents dice, and the randomness of your own. games arent much fun when they dont follow the rules they set for the ', 'Mostly Positive', 77.77, 62.55, 46.58);
INSERT INTO reviews VALUES (1843, 236730, 192, 'Anomaly 2\n\nHas a total of 6 trading cards.', 'not to bot bad of game but it dont play linux unless proton or good old WINE. or form your win box.\n', 'Mostly Positive', 72.92, 0.43, 0.10);
INSERT INTO reviews VALUES (1844, 236790, 203, 'Bought tons of bugs for only 0.60 dollars !!!! Its the cheapest bug pack out there. What are you waiting for buy and you will be facing with the bugs u have ever never experienced in your miserable life.\n', 'I know the game is OLD, however it was working then it just started crashing endlessly... Now I can not even continue with the tutorials as the game launches starts-up and crashes... WOW, not worth the effort!\n\nNOT RECOMMENDED!!! I requested a refund\n\n Recommendations \n YouTube \n TikTok ', 'Very Negative', 18.23, 0.18, 0.47);
INSERT INTO reviews VALUES (1845, 236930, 591, 'https://steamcommunity.com/sharedfiles/filedetails/?id=2559007906', 'I want to like this game. I really do. I liked the rest of the series, and I was looking forward to seeing where it was all going. Unfortunately, where it was all going was to a really unsatisfying conclusion.\n\nThe gameplay and art design are good, the voice acting is top notch, and most of the characters are well written. Unfortunately the story itself, both on its own and as the conclusion of the series, is really disappointing.\n\nA lot of the plots points either make no sense are poorly resolv', 'Overwhelmingly Positive', 97.12, 6.30, 3.95);
INSERT INTO reviews VALUES (1847, 237350, 142, 'Its like SpeedBall with robots at a rave, But British so everyone waits their turn.', 'Love the concept. I have been looking for a turn based simultaneous football game forever. Unfortunately this one is plagued by a LOT of problems.\n\nFor starters, the Tutorial only covers the very basic concepts of the rules. It doesn''t explain stats, free agency, positions, equipment, roster management or anything other than "here''s how to run and pass." Secondly, the game has some pretty major glitches. Twice now I have had to concede matches because the game completely broke. It kept running t', 'Mostly Positive', 73.24, 3.87, 4.68);
INSERT INTO reviews VALUES (1848, 237370, 171, 'as a noob youtube playthrough person i enjoy using this software. Its so CPU and RAM light even though its packed with so much.\n10/10 I dare anyone not to like this. Files are saved as AVI but compressed in MJPEG (Moving Jpeg) so for my Half-Life 2 sries. 30 mins at 1080p is 10-15gb. Compress it to 720p in Sony Vegas and bang >1gb\nFor Assassins Creed 4 its more like 20GB but its Jpeg formatted so obviously the mpre colours used the bigger the file. Still... Its an EPIC peice of software. GET IT ', 'The first few days I used Playclaw everything worked fine, I was able to record for more than an hour in 1080p without much lag or frame drops... Then things started to get messy when I tried it on various games and started playing with the settings. The software gives error messages right from the start and it doesn''t work with every game, while Fraps does.\n\nSure, Fraps has a higher impact on performance but overall you can record anything (including the desktop) without having to worry about t', 'Mixed', 63.16, 21.23, 131.22);
INSERT INTO reviews VALUES (1849, 237430, 713, 'Backtracking through this series after first playing Rome. Conquistador is entertaining as you try to wrangle a band that never -quite- gets along, all while engaging in a solid turn based strategy as you make a name for yourself in the new world.', 'Sad girl power fantasy that craps all over real history.', 'Mostly Positive', 77.00, 23.40, 5.52);
INSERT INTO reviews VALUES (1851, 237550, 130, 'With some tweaks this is now nearly the game it ought to be and if u love the original trilogy or want to have a look give it a shot.', '大而无当。\r\n首先是满屏幕密密麻麻根本没用的法术和技能，连开发者自己都不得不在说明书中点出了几个最有用的技能——全部技能数量5倍于此。大量技能和法术都是基于“模拟真实世界“设计的（对于桌游规则的粗暴移植，类似dnd 3）而没用考虑到视频游戏的可操作性。\r\n开放世界地图极大但是几乎全是空的，城里全是填坑的雷同npc。在系统和地图上做拟真真的是舍本逐末，还不如直接地城踢门。\r\n战斗机制在低级时特别难用，1级时按最优build构建出来的人物，敌我法术和普攻都很难命中，战斗中70%以上的miss。', 'Mixed', 42.31, 19.93, 18.88);
INSERT INTO reviews VALUES (1852, 237570, 206, 'An adventure you''ll never forget.', 'Combat-focused finale with weak story, repetitive gameplay, underwhelming ending, and disappointing shift from earlier character-driven entries.', 'Very Positive', 83.98, 10.35, 2.50);
INSERT INTO reviews VALUES (1853, 237740, 1925, 'This game is so hard, it would actually be easier to go outside in a thunderstorm and try to dodge rain. It would be easier to walk barefoot, without your toes or heels touching the floor. It''d be easier to pick fly shit out of pepper... while wearing boxing gloves! \n\nVery fun game, especially for AVGN fans!', 'Play the deluxe  edition  way less cheaper  death''s', 'Very Positive', 88.73, 6.30, 2.98);
INSERT INTO reviews VALUES (1855, 237850, 1882, 'First, I must mention that I did it with a little help of a guide found here on steam. That''s why it took only 15 hours to complete, I guess it would have been much longer without. \r\nNow that is settled, I have to say that I really enjoyed the game. I''ve played the Longest Journey when it came out back then, I must confess I do not remember it well but still have the feeling of a good game. So I''ve decided to give the sequel a try. \r\nAfter Dreamfall, that was a bit clumsy, I found Dreamfall Chap', 'The first game was one of my favorite childhood games. The second one was pretty nice as well. But this has so much left wing political messaging and cringe worthy characters that it honestly just put me off. It''s like the game took a complete 180. Later on I realized that the first two games were made by Funcom while this one was made by the studio responsible for Dustborn so now it all makes sense.', 'Very Positive', 80.45, 15.52, 2.08);
INSERT INTO reviews VALUES (1856, 237870, 3055, 'I am still sad they abandoned this game. It had so much potential and was a ton of fun! i truly hope they come back and finish it. to this day, it had the most unique crafting system ive ever seen in any game and it was probably ahead of its time. Please come back, this game had such good bones and even more potential!!!', 'We should get refunds.', 'Mixed', 58.69, 62.38, 2.98);
INSERT INTO reviews VALUES (1857, 237890, 1205, 'I''m never gonna finish this game like I did on the PS3. Played it on PS3, never gonna finish it. Only bought it here because it is what it is.', 'Let me start by saying I really wanted to like it. It''s only $4, and I love SRPG-esque games. It even comes included with a bunch of add-ons for free. So I thought this would be a home-run. But...even though I really tried to like it, I just can''t. The combat just feels weird and bad and outdated. That''s all I''ll say about that. As far as the story goes...well, I havent even gotten far into the story, but so far it is just WEIRD. Dude wakes up from a dream and decides to risk it all for some ran', 'Mixed', 68.71, 3.78, 0.93);
INSERT INTO reviews VALUES (1858, 237930, 15806, 'Short and sweet; great story. Can''t believe I owned this for 8 years before finally completing...', 'Maybe my hope got too high for this game. IMO its obviously overrated because of its art. The combat seems deep and fun with lots of potential in the first hour cause you could customize your skills in many different ways, but soon I found every encounters more or less feel like the same. You just deal as much damage as you could in turn(), then play hide and seek until the cooldown is back. The encounters are not difficult but quickly feel like a chore. And the bad control handling didnt help a', 'Very Positive', 93.85, 11.47, 3.63);
INSERT INTO reviews VALUES (1859, 237950, 174, 'It''s a classic game, with solid base building, story, and character development.  It doesn''t take the "disposable soldiers" approach that other x-com style games take,  and encourages you to play the way most folks used to save scum to play x com.', 'Doesn''t start. Probably too old.', 'Mixed', 69.54, 527.73, 67.67);
INSERT INTO reviews VALUES (1861, 237990, 7594, 'The game is nice, not great, but nice. This is a game you''ll play for the story (which is good), not for the game play (which is ok).', 'I feel like this game shouldn''t actually be a game. The actual gameplay parts are pretty subpar and can actually be frustrating at worst or boring at best. If this was just a choose-you-own adventure movie it would be great.  Interesting story and lore, amazing artwork, good voice acting, good dialogue, meaningful (yet harsh) decisions. You could even remove the choices aspect and it''d still be a great film. That is where the talent lies in this game and they have done that part very very well. ', 'Very Positive', 88.27, 16.43, 32.68);
INSERT INTO reviews VALUES (1862, 238010, 12681, 'For a 12 year old game, it still holds quite well even among new games now. If you like Dishonored, it has a lot of similarities, like having multiple ways to complete objectives. At first the visuals is what attracted me. But after completing the game the first time. It was the story that made this game outstanding and memorable.  At the beginning you got a typical revenge/redemption story. Around the middle was like conspiracies and at the End was like philosophical / existential pondering. A ', 'You''d think that a decade-old game would run well on modern machines which far exceeds the recommended hardware requirements but it is so laggy and stutter every few minutes that it just borders on unbearable. This is really apparent in open areas such as the Detroit map or the China map which stutters heavily as you move through various linear paths and alleyway. The game itself is good but the experience of playing it is not because of the terrible stutter.\n\nIf you need to go online and find s', 'Very Positive', 91.58, 118.02, 31.97);
INSERT INTO reviews VALUES (1863, 238050, 211, 'This Apogee package is a gift for fans! Because these games are very good, each one is fun, and they work 100% well in DOSBox.\nAnd of course, for those who enjoy FPS games like Wolfenstein 3D, DOOM, Duke Nukem 3D, Catacomb 3D... You''re in for a treat!\nThe wait was worth it!', 'A very basic conversion. Simply the base games with Dosbox. No real customization options. You can''t even set a strafe right/left, but only a ''strafe'' button, meaning you can only strafe by hitting that button and turning left/right.\n\nNo meaningful video options\nNo meaningful sound options\nPoor mouse/keyboard options, making these two games almost unplayable.\n\nThe games are good, but I cannot recommend in current state.', 'Very Positive', 92.89, 10.18, 0.93);
INSERT INTO reviews VALUES (1865, 238090, 6697, 'There are 6 campaign missions and 4 DLC missions I can play. Those are fun and the game looks great.\n\nToo bad there is a game breaking bug in campaign mission 6 so it''s impossible to complete it to get to the rest of the game.', 'I played this game until a few days ago, when, while I was playing, the game suddenly closed. In vain I tried to turn it on, it doesn''t want to start anymore. I''m not very specialized in installing games and I can''t find help on steam to solve the problem. Now I''m a bit sorry that I bought them, but it was one of the few games I know how to play and I was just playing to disconnect.', 'Mostly Positive', 78.12, 13.50, 22.60);
INSERT INTO reviews VALUES (1866, 238210, 4749, 'I originally played this game in highschool but would learn it was formative to how i would approach my love life as i only date evil women with a god complex. want me to go shoot some alien hive mind that you created from your fuck up 42 years prior at your previous place of employment? yes babygirl i gotchu. 10/10 game.', 'The head of Nightdive Studios, Steven Kick, supports political assassination. That''s a no from me dog.', 'Overwhelmingly Positive', 95.11, 35.30, 0.52);
INSERT INTO reviews VALUES (1867, 238240, 1563, 'No more support for the game but still fun!', 'This game is already abandoned. So stay away.', 'Mostly Negative', 30.52, 87.38, 2.57);
INSERT INTO reviews VALUES (1869, 238280, 895, 'I''ve been playing this in VR and its pretty damn fun tbh. this is not the sort of game id imagine would benefit from a VR experience but its actually a blast to play, also its a very pretty game for what it is. i certainly see this as a bit of a hidden gem regardless of playing in VR or flatscreen. a great game!', 'Game is kind of fun, until it isn''t. You pretty much have to rely on luck to advance, it gets far too difficult at low levels and there isn''t any incentive to progress at all.', 'Mostly Positive', 74.41, 7.57, 0.22);
INSERT INTO reviews VALUES (1870, 238320, 25773, 'super family friendly and educational... the part in the DLC where you are strapped to a table has a math lesson, do that part in front of your kids', 'I decided to try Outlast for a Halloween playthrough and man was this eye-opening. So many people herald this game as an amazingly scary-fun game and this illustrates perfectly how nobody has actually played this game. In fact, the trophies show this, by the fact that the first one you get (turning on the generators) only 47.6% of players have received this. This is in chapter one! You know how long you’re scared in this game? The first five minutes of driving up to the asylum and seeing the sha', 'Overwhelmingly Positive', 96.05, 12.07, 3.28);
INSERT INTO reviews VALUES (1871, 238370, 3000, ' love this game, but my friends are poor and don''t buy the game :/\nThis game is better than CS2', 'Was able to play the tutorial one day just fine, but now it''s asking for account creation and linking and if you decline the game just won''t load. Fuck off with that bullshit', 'Mostly Positive', 74.67, 7.82, 0.18);
INSERT INTO reviews VALUES (1872, 238460, 22994, 'The game is super fun but the pricetag is misleading. It doesn''t cost 15$, it also costs like 1-2 friendships.', 'Just another jump around platformer. The story isn''t interesting, the challenges aren''t exciting, the animation isn''t spectacular. It all kind of reeks of an old flash game. One without anything memorable.', 'Overwhelmingly Positive', 97.19, 76.00, 1.47);
INSERT INTO reviews VALUES (1873, 238530, 269, 'Innovative and challenging gameplay, a ton of different levels, obstacles and challenges and overall a very rewarding and fun experience.\r\n\r\nThe game doesn''t pull punches, and players are expected to survive at least 3 minutes against unforgiving enemies which end your game in a single hit. I think for some this could be a frustrating experience if you struggle against certain enemies or are bad at the game. But for me it was a fun and rewarding experience to figure out how to exploit enemy patt', 'Why is this so much less fun than the original? It feels like everything kills you instantly in this one.', 'Very Positive', 91.45, 15.50, 1.92);
INSERT INTO reviews VALUES (1874, 238630, 129, 'This game has no right being as good as it is. Honestly, one of the best 2d beat em ups ever. It is easily in the competition for the best or one of the best. It''s such a good game for a group or couple to play as well. It''s also way bigger than you''d expect. It''s actually just surprising how good this game is. There''s some RPG mechanics, all kinds of levels, all kinds of characters, and I think it has a great set of moves for one of these. Absolutely underrated.', 'Every element of this product is miserable and sophomoric. From the rock ''em, sock ''em combat to the recycling of levels and character designs, Fist Puncher is pure, diluted waste that should have never ventured outside the 360 Xbox store — its digital garbage patch. If you have never experienced being bored to tears, this video game will certainly introduce you to that experience.', 'Mostly Positive', 74.42, 13.72, 3.20);
INSERT INTO reviews VALUES (1875, 238750, 1672, 'I love this game. Just wish it was more clear where to go. I waste a lot of game play just googling what to do next and how my characters were bad so I had to start over. Warrior mode is very difficult and frustrating, but I keep playing it so...I love it?', 'Now that "Ubisoft Connect" is required to play this game, I won''t be playing it anymore.\r\n\r\nGo to he1111 in a handbasket, Ubisoft.', 'Mixed', 64.00, 113.40, 13.67);
INSERT INTO reviews VALUES (1876, 238870, 239, 'Citadels\n\nHas a total of 5 trading cards.', 'Bad game. Don''t waste your time with this one. Go play Strongholds', 'Very Negative', 12.55, 1.22, 39.85);
INSERT INTO reviews VALUES (1877, 238890, 156, 'I absolutely love this game. Very original and wel executed. A few more factions would have made this an instant classic for me. No idea how this game can get so many negative reviews but it is right up my alley. Been playing it for years, many hours offline, and will continue to do so. Thank you Arcen Games!', 'It has a cool concept but suffers from tedious gameplay, poor execution, and repetition.', 'Mixed', 49.36, 122.75, 1.43);
INSERT INTO reviews VALUES (1878, 238910, 241, 'For a $10 game, I think I got my money''s worth.', 'Not my thing. I expected a team strategy game, I got a turn-based roguelike dungeon crawler where you control one mech at a time and swap them out like they are stances or armor sets as opposed to actual units.\n\nAfter getting over my confused expectations, I still found the game lacking. It''s closer to a puzzle game wherein the goal is to maximize use of your resources (ammo, health, etc) to clear the boards in hopes of collecting loot you can use in upcoming missions.\n\nI can see the appeal, but', 'Very Positive', 85.06, 305.35, 1.45);
INSERT INTO reviews VALUES (1879, 238930, 265, 'Whatever, I like it and I''ll continue to play it in small bursts.  Put coins in slots, random interesting events happen, your family goes through the ages making a name for themselves.  Sad to see no movement on a sequel, but that gives me plenty of time to some day finish this game.', 'Nice idea, but it just didn''t translate into a fun experience.', 'Mixed', 60.38, 19.78, 4.38);
INSERT INTO reviews VALUES (1880, 239030, 37035, '-Checks literally everything for 20 minutes\n\n"Hmm, seems fine"\n\n-Gets fined for incorrect number of eyelashes', 'cant sex with jorji', 'Overwhelmingly Positive', 97.28, 3.10, 10.43);
INSERT INTO reviews VALUES (1881, 239070, 2445, 'Amazing modern version of gauntlet, love the pixel art and crt filters', 'A decent game, but with some pretty frustrating flaws.\n\nPermadeath is super annoying in a co-op. Losing all your progress and then playing through the exact same dungeon again is super demotivating. We tried playing with infinite lives, but then it trivialized the game -- there was no penalty at all for death.\n\nAlso, the fact that every player controls every menu simultaneously led to a let of misclicks. My partner opened a vendor while I was attacking things, and my button press bought somethin', 'Very Positive', 87.98, 7.37, 1.82);
INSERT INTO reviews VALUES (1882, 239090, 295, 'people need to play this game', 'Samurai GUNN is an older game from 2013.  It''s a venerable 12 years old at the time of this review, but feels like it''s much, much older, and that''s the first of many problems.\n\nThis is basically a ripoff of Super Smash Bros, a local PvP focused arena platform brawler, but with two distinct differences, instead of a variety of Nintendo characters, it''s Kurosawa style samurai with over the top blood effects everywhere.  Secondly and most distinctively, the graphics, gameplay and everything else a', 'Very Positive', 93.22, 44.58, 7.03);
INSERT INTO reviews VALUES (1883, 239120, 1589, 'I broadly recommend all Final Fantasy games.\r\n\r\nExcept 7 and 13.', 'Played mostly on steam deck\r\n\r\nHad a save that was close to 100% completion, all cheevoes, jobs 99, beastiary etc.  Wanted to play it on PC.  Installed it, checked that saves were synced.  Booted on PC.  Found an ancient save that wasnt even 40% done.\r\n\r\nCheck steam deck, my massively progressed save was gone and replaced with the PC one.\r\n\r\nGo fuck yourself.  80+ hours gone.  Absolute fucking joke.', 'Very Positive', 80.05, 125.77, 112.68);
INSERT INTO reviews VALUES (1884, 239140, 88604, 'Spent an entire night on a pole because i couldnt make it to a safe house 10/10', 'Game refunded, I just bought it to leave a review and warn everyone that the company is very scummy.\n\nThe game bundle with all 27 DLCs used to cost $9.99, but they knew they would get a lot of publicity from the launch of their new game and the 10th anniversary, so they decided to increase the price on December 12, and now it costs over $20... Thanks, but I don’t like it when companies take advantage of their consumers like that.\n\nSeeing how many new buyers there are, their trick sadly worked.', 'Very Positive', 94.32, 18.03, 0.12);
INSERT INTO reviews VALUES (1885, 239160, 7184, 'I don''t understand. I''m a big fan of immersive sims / stealth games. I almost passed this game because of majority of people calling this game "mid" - and I am so incredibly glad I haven''t. \n\nThis game might have been mid back in the golden era of gaming (which doesn''t mean it''s mid, it''s just not masterpiece), but in 2025? It''s one of the best games I have played in a long long time, extremely underrated in my opinion.\n\nAlso- asylum chapter was hella scary. Whoever level designer was- get that ', 'The original Thief games were nice, but then Dishonored came and it changed the formula. And Thief wanted to do the same but it simply couldn''t.\nDishonored is way more enjoyable and fun compared to this.', 'Mixed', 67.73, 26.47, 9.22);
INSERT INTO reviews VALUES (1886, 239200, 4126, 'Now I''m scared of pork. The game throws me into a dark, eerie world where monstrous, mechanical pigs hunt me down with their glowing eyes and creepy grunts. Every time one of those twisted, mechanical swine came at me, my heart raced and my palms sweated. Thanks to Amnesia: A Machine for Pigs, pork isn''t just dinner—it''s a terrifying reminder of my nightmarish encounters. I can''t even look at a piece of bacon without shuddering.\n\n\n돼지돼지야.', 'Not only did this game crash for me 3 times in the 30 minutes that I played, when I first launched the game, there was already a profile called "Hi", which absolutely was not me. When I clicked continue it spawned me 10 minutes into the first area. This game is cursed and I''m never installing it again.', 'Mixed', 64.93, 4.35, 0.52);
INSERT INTO reviews VALUES (1887, 239350, 10036, 'i spawned in and immediately died to an explosion that had nothing to do with me. spelunky', 'I want to make myself clear. I don''t dislike this game because its difficult, but because its too unpredictable and straight up unfair to the player. You have a chance to die from simply spawning in and a random enemy causes a chain reaction that kills you OR the enemies spawn so close to you that you get almost no reaction time. Procedural generation is a nightmare, often leading to instances where its difficult or near impossible to not take damage because of how the map spawned. When a player', 'Very Positive', 92.06, 376.52, 1.50);
INSERT INTO reviews VALUES (1888, 239430, 531, 'Inspired by Portal but is its own thing. Short, makes little sense, but a pleasant experience and I wanted it to last a bit longer which is always a good sign. Don''t pay too much for it, it is short.', 'Why is this rated so highly? It''s infuriating. So many puzzles based on janky nondeterministic physics... if you want a good puzzle series, play Portal or The Talos Principle\r\n\r\nAlso the game''s story is pretty shit and the graphics suffer from ghosting', 'Mostly Positive', 79.28, 3.65, 0.68);
INSERT INTO reviews VALUES (1889, 239700, 343, 'This is a great story that hits a lot harder in 2024 than I imagine it did when it originally released. That said, while the story is superb, the execution is lacking. Having the ability to read a visual novel in essentially any order you want means that there can be no real pacing, something that is only sort of addressed with the real life time gates and later game file unlocks. After reading the last file and getting my ending dialogue, I was left with a feeling of "that''s it? there''s nothing', 'I own the game but I will never play it. It has an intentionally impossible achievement (not coded in) to poison your Steam Achievements forever just so it can make a Final Fantasy VII reference. I hope Valve eventually requires all achievements be possible or be removed in future. If developers had the choice between keeping servers online or pulling from the store entirely we would have less impossible achievements on the platform. \n\nNonsense like this game pulls should just be against TOS per', 'Very Positive', 85.13, 6.23, 0.87);
INSERT INTO reviews VALUES (1890, 239800, 1004, 'Great indie game from back in the day.', 'sucks.', 'Very Positive', 92.23, 5.65, 1.33);
INSERT INTO reviews VALUES (1891, 239840, 1485, 'It''s janky. Fairly unstable. Apparently has troubles running on modern systems.\r\n\r\nBut damn, is it a good game. I''ve always liked the idea of a base-building game where you go out and loot a billion pounds of shit across the city to make a safe haven for people during a zombie apocalypse, and by god, that''s what this is. It''s also got some pretty damn good writing, especially with environmental storytelling. A bit dated in some of the references, but that''s okay because they''re references from a', 'The story line  (as far as i managed to play) is really nice, the hidden quests etc. You really feel like you have to fight the zombie apocalypse BUT! The game is crashing left right and center!!! You want to go to sleep? Crash! You want to go to an area? Crash! You want to go upstairs? Crash! You get the point. Apart from the constant crashing that can get you off the immersion the rest are pretty good. I would recommend the game if it was cheaper but 20€ for a game that it is crashing all day ', 'Mostly Positive', 70.71, 126.83, 10.38);
INSERT INTO reviews VALUES (1895, 240440, 707, 'peak game, honestly one of those games that you might have played as a kid then forgot about it till your older, then played it again and understood a lot more and really enjoyed it. 10/10.', 'I really wanted to like this game. There are a lot of cool concepts and gadgets that you get as the game progresses, but I found myself wondering when the tutorial was going to end. About an hour in, I realized that this was the game. Unfortunately, the puzzles are very discrete - they never really build off of each other. And they are so simple. I spent more time handling the glitches and poor game mechanics than I did actually thinking about how to solve the puzzles. I think that if you go in ', 'Very Positive', 92.08, 3.75, 11.18);
INSERT INTO reviews VALUES (1896, 240600, 320, 'This is a game that puts the racing experience front and center. The physics model of the pros at Milestone is a piece of art that has only matured over the years. The sensation of speed might not be there but the handling of the bikes is almost perfect.\n\nhttps://steamcommunity.com/sharedfiles/filedetails/?id=3262215532', 'This game is terrible, I can''t even turn left in a curve without crashing. How am I supposed to drive in this game? this is ridiculous. I can''t even ask for a refund, but I don''t care, I prefer to permanently remove this game from my gallery.', 'Mostly Positive', 79.38, 6.72, 0.30);
INSERT INTO reviews VALUES (1897, 240620, 156, 'this is what i would consider an unpolished Gem, everything is there. classes, leveling up, skills, pets, map exploring, bosses, easter eggs even an arena with endless monster waves and more., but as said before it has tons of bugs and you need to be constantly every 2 or 3 hours making a back up because the game can crash safe file get corrupted and lose everything. but for a game you can get for 1$ on discount is worth it beating my 1$ per hour of fun rule by a mile. as im typing this review i', 'Wanderlust Adventures is the follow-up to Leth''s 2011 game,  Wanderlust: Rebirth. It''s an Action RPG with online multiplayer, and it plays like a pseudo-MMORPG. The game boasts a huge open world to explore with randomized dungeons to keep action fresh and entertaining. There are 4 character classes to choose from, each with their own strengths and weaknesses. I decided to give this game a try after Rebirth. Leth promised players that he''d listen to their suggestions and improve upon what was lac', 'Mixed', 57.69, 48.62, 1.32);
INSERT INTO reviews VALUES (1899, 240720, 38672, 'Good game.\nWhen they are old enough, this will be the first game my children play. \nThey will not be allowed to play any other game, until they beat this one.', 'how to enjoy getting over it \r\n1.buy the game\r\n2,fall down\r\n3.uninstall and realize you lost money\r\n4,get over it', 'Very Positive', 84.61, 9.37, 4.33);
INSERT INTO reviews VALUES (1900, 240760, 3106, 'Just like my ex, Wasteland 2 is tough, full of tough choices, and has more issues than Vogue. Still love ''em both though! 10/10 would navigate this emotional and explosive minefield again.', 'I lost interest mid-playthrough. Everything feels really flat and linear - both story and gameplay. It ends up being a turn-based combat simulator instead of an RPG.', 'Very Positive', 81.29, 0.47, 53.20);
INSERT INTO reviews VALUES (1901, 240970, 292, 'An incredible followup to an already incredible game, well worth sinking hours and hours into trying for good times in time attack, finding any secrets in the story, or going for a new high score in infinite mode. You cannot go wrong with Half-Minute Hero if you had any love for the first game or old JRPGs', 'KAMGUSTA''S MINI REVIEW\n\nI had high expectations for this one, but game failed on delivering. It''s not "30 seconds", as the core gameplay is finding ways to reset your clock counter, multiple times. And it is not "RPG", as it is divided in dozen stories ("quests"), every one starting from scratch - you also can''t upgrade stats, manage battles or do whatever you are supposed to do in a RPG. I''d call it a puzzle game set in a Final Fantasy theme. Dialogs are long and boring. Humor is MIA. WTF guys?', 'Very Positive', 91.44, 164.83, 8.75);
INSERT INTO reviews VALUES (1902, 241000, 306, 'This is admittedly a hard nut to crack right now. I gotta admit is does feel like it should be in Early Access since I''ve already ran into some minor bugginess and for the UI, which is on the edge of, sort of flirting with intuitive...but not quite yet there. \n\nIn fact I kept running into walls on paths that the UI clearly was trying to lead me down. I felt at times like a blind man being led by a seeing eye dog who also happens to be blind. This is pretty frustrating given the layers of complex', 'Some cool ideas, but incomplete, buggy, broken, and abandoned.', 'Mostly Negative', 37.91, 4.47, 28.10);
INSERT INTO reviews VALUES (1903, 241240, 673, 'great physics-based puzzler about making rube goldberg machines (ball hits scissors, cuts rope, basket falls on mouse, etc.). it''s essentially the same as the incredible machine from 1992 (only available on gog for some reason), made by the same developer. hundreds of levels, dozens of mechanics, everything unlocked from the start.\n\nlooks and controls are a bit mobiley and finicky, especially selecting placed items, but controls are rebindable. servicable sfx, really annoying music (kevin macleo', 'I wish there was an option to use the graphics from the original Incredible Machine game, because the animations and "whimsical characters" look trash. Everything looks so cartoonish and warped that my 6yo confused the mouse for a wasp, because it has a weirdly thin body and its ears are shaped pretty much like insect wings.\n\nThe addition of elements like zombies and brains are unwelcome, and make the game much less appropriate for younger kids (especially when they''re included in the tutorial l', 'Very Positive', 92.57, 5.17, 1.78);
INSERT INTO reviews VALUES (1904, 241260, 2104, 'Despite being a 10 year old game, this has held up pretty well. The story and cases are pretty solid; there''s only one case that felt a bit lacklustre (5). The minigames can be slightly tedious at times, but they''re all skippable. It is definitely replayable as well.\n\nThere are a few cons, one being that the puzzles are a little too easy to figure out, but I can understand why that is.\n\nThe other is the constant fast-travelling. The game isn''t open-world, so you have to constantly fast travel to', 'Mysteries YES!!!\nPuzzles YES!!!\n Sherlock Holmes YES!!!\ntrying to find the one trigger to progress the story after you have been around the entire map 7 times and talked to every single person.....no..........\n- over priced for a ten year old game\ni think Watson is possessed by a demon. he casts no shadow and teleports around the map\nwould love to finish the game but sick of looking things up in a guide to get to the actual gameplay and puzzles', 'Very Positive', 90.07, 29.43, 2.95);
INSERT INTO reviews VALUES (1905, 241300, 128, '- A sequel with some new game mechanics.\n- It''s a simple card battler game with funny/weird looking aesthetic\n- Cohesive plot with humor sprinkle around it\n- Might not be for everyone, but it is the a sequel of a game from the nostalgic ittle dew series.\n- Simple, Ok-Humor, Ok-Plot, not very time consuming.', 'Nothing special: silly humor, bland game design.', 'Very Positive', 89.06, 14.82, 0.82);
INSERT INTO reviews VALUES (1906, 241320, 310, 'she ittle on my dew til i', 'This game ended up being mostly puzzles, some of which were actually very difficult to solve on my own. I was honestly hoping the combat would have been more fleshed out. This will not scratch the itch you might have if you played the older Legend of Zelda games.', 'Very Positive', 91.94, 14.23, 3.63);
INSERT INTO reviews VALUES (1907, 241410, 695, ' The pros:  Chilled, goofy vibe with charming music and visuals. Satisfying gameplay, particularly ballista headshots, multikills and castle demolition. A surprising variety of mission objectives with multiple different ways to complete them, decent progression, and a reasonable challenge when played on ''hard'' difficulty.\n\n The cons:  A minority of the missions feel like filler that could have been omitted without any negative effect on the pros. Online multiplayer is empty. \n\n The unexpected:  ', 'too tedious with timers etc - 2/10', 'Very Positive', 87.34, 27.70, 4.07);
INSERT INTO reviews VALUES (1908, 241540, 8830, 'https://steamcommunity.com/sharedfiles/filedetails/?id=247008957\nhttps://steamcommunity.com/sharedfiles/filedetails/?id=270089575\nhttps://steamcommunity.com/sharedfiles/filedetails/?id=247598449', 'It''s just too old, too janky. It crashes, the day/night system where you can''t pass time or rest, your companions just randomly leave and go back to base where you then can''t get them to go with you again, etc. Too many problems, but then also to release an update as a paid new version is infuriating. I liked the game enough that I''d have considered SoD2 or SoD3, but probably not with this kind of shady dev BS.', 'Very Positive', 81.68, 31.37, 3.27);
INSERT INTO reviews VALUES (1909, 241600, 9949, 'A classic roguelike, worth a play for historical reasons. Rogue Legacy 2 really does blow it out of the water, but I go back to play it from time to time for the happy memories.', 'Ridiculously difficult. You die in just a few hits, and if you don''t earn enough money for upgrades in a single run, the entire run is wasted.', 'Very Positive', 91.92, 46.20, 0.82);
INSERT INTO reviews VALUES (1910, 241620, 259, 'Amazing dark fantasy CRPG. Investigate heretics, burn them at the stake and fight armies of hellspawn in underground dungeons.', 'An interesting premise, but disappointing result.', 'Mixed', 66.41, 47.47, 3.18);
INSERT INTO reviews VALUES (1913, 241720, 505, 'Guncraft is a great game.', 'fucking boring', 'Mixed', 50.89, 30.82, 1.03);
INSERT INTO reviews VALUES (1914, 241760, 103, 'Possibly the most underrated game I''ve ever played.  It''s really fun', 'This games been out for over 8 years, less than 200 steam users have reviewed it in that time: i''m someone who started playing this game late starting on 10-06-2024. Once i started searching for any mods that might improve the god awful gameplay especially with the food stamps rng (lol) i noticed that building my character with the added risk of running yellow skull rooms only depends if the rng is going to give you health for hardmode or damage for normal/easy mode, tech power isn''t really expl', 'Mixed', 66.02, 56.85, 14.88);
INSERT INTO reviews VALUES (1916, 241910, 582, 'There''s something beautiful about someone who knows exactly when to walk away. But honestly? Who cares! :p', 'I would only recommend this one if you have played the first two and want to see the rest of the story.\n\nOtherwise unfortunately the quality of puzzles drop dramatically in this installment. It depends heavily on mini-game type of puzzles instead of well-designed point-and-click goodness, and some puzzle solutions are nonsensical, doubles the amount of trial-and-error. I felt that even the writing (excluding the usual silliness Deponia series has in its dialogue) was poorer than before.\n\nOnly a ', 'Very Positive', 82.82, 2.67, 9.92);
INSERT INTO reviews VALUES (1917, 241930, 31282, 'Thank you Monolith for two of the most amazing games I''ve ever played. \nIt''s truly sad that Monolith is shutting down, \nI wish we had more Middle Earth or LOTR games from you guys.\nIf anyone haven''t play these two Middle Earth games, you must try. They are AMAZING.\n', 'It''s good, but they dont deserve money for their toxic patent on the nemesis system.', 'Very Positive', 91.70, 39.82, 26.53);
INSERT INTO reviews VALUES (1918, 242050, 27792, 'Hey UbiSlop, can you please shift delete your ubislop launcher and let steam open the game, this will finally allow me to open the game without trying to keep re-entering the password again and again like a spastic forgetful idiot. Oh wait that''s your launcher not me', 'This game is a never buy, even on discount for the following reason: "requires third party account with Ubisoft Uplay"\n\nWhat does this mean? well as someone who bought this game years back let me tell you!  You have to download and install a new launcher outside of steam that is buggy, crashes constantly while you are in-game and hogs computer resources while spying on your PC. Then after a year or two of inactivity (you finished playing the few single-player games you bought and did something e', 'Very Positive', 86.20, 136.22, 58.93);
INSERT INTO reviews VALUES (1920, 242130, 363, 'This game''s play is in many ways similar to Ace Combat 4. It is simple compared with Ace Combat 7 or Project Wingman, but has the same Arcade/flight style with multiple modes, including campaign and shorter challenge missions. its an older game, but still good. you''ll do best to use both a controller, and your keyboard. The art style is a Cel shade, which works in respect to what they were going for and there are a lot of variety of aircraft and variants. it isn''t as splashy as some of the newer', 'This game is something of a tragedy in a lot of ways. It has a brilliant art style. It has a blistering aircraft roster. It has solid fundamental gameplay and A.I. \n\nBut its content store is unfinished, the game crashes to desktop incessantly, and it appears to be incompletely coded.\n\nIf the developers were actually present to account for and address these issues, then Vector Thrust could be a legitimately good game. But instead, the game is incomplete, crawling with technical issues that make i', 'Mixed', 46.56, 128.92, 6.85);
INSERT INTO reviews VALUES (1921, 242530, 165, 'A game for real MEN.   Perfect port.', 'Terrible port with broken steam co-op and laggy controls making an already infuriatingly difficult game almost impossible to play. Not worth buying even on sale.', 'Mostly Positive', 74.55, 10.97, 2.08);
INSERT INTO reviews VALUES (1922, 242550, 3565, 'Pretty good of a game in general and them finally adding achievements is pretty nice too.\r\n\r\nExcept 1 Million Lums...', 'The game is fantastic however requires an internet connection to connect to uplay every time you wish to play the game. This is painful when trying to play on steam deck. Leaving a negative review in the hope that one day this restriction will be removed.', 'Very Positive', 85.78, 35.82, 1.27);
INSERT INTO reviews VALUES (1923, 242570, 1074, 'Love Warhammer 40K, love this rendition of Space Hulk!  Works well, follows the rules (mostly), just fun.', 'I idiotically spent £22 on the PC version of a port of a tabletop boardgame that was horribly imbalanced.\n\nBe happy you can''t make the same mistake!', 'Mostly Positive', 70.30, 703.13, 0.72);
INSERT INTO reviews VALUES (1925, 242680, 9020, 'This is the holy grail of roguelike twin stick shooters, it shines in simplicity along with a merciless challenge that borrows deep from excellent Arcade game design. Don''t wait for a sale, it''s worth every penny.\n\nAnd just a heads up for a higher frame rate and gamepad users, use the open beta 64 (2023) branch of the game for 60 / 120 fps bc the base game is locked at 30 fps, there''s also 16:9 aspect ratio support under this beta if you feel like playing it that way bc the game was originally d', 'too addicting, can''t stop playing', 'Overwhelmingly Positive', 96.60, 12.55, 280.50);
INSERT INTO reviews VALUES (1926, 242700, 3709, 'soupman gets his wife killed by a clown and becomes hitler. is he stupId?', 'Cannot for the life of me get the meter burn to work.', 'Very Positive', 82.21, 5.17, 0.72);
INSERT INTO reviews VALUES (1927, 242760, 169421, 'Ive had a long running theory that this is a simulation of having your plane crash outside of the safezone surrounding disney world in florida and then having to fight the local flordians corrupted by the tap water that gives them the urge to do dumb shit all the time.\n\n\ngames fun!', 'The game loop is boring. The cannibals are annoying. The crafting is lame. The resources (like airplane meals) constantly regenerating destroys immersion.\r\n\r\nThere''s no point to base building when the map is so spread out that there''s no point to ever come back to a main base. There''s nothing you can build there that''s worth the effort.', 'Overwhelmingly Positive', 95.33, 11.78, 11.73);
INSERT INTO reviews VALUES (1928, 242780, 259, 'I really recommend this to anyone who likes good adventure and detective games! However, do keep in mind that the story is very intense, including some visual imagery that could upset some', '-Incredibly buggy\n-Crashes very often\n-Archaic UI design\n-Incredibly slow animation (also awful animation)\n\nThe only positive is the story but guess what? I didn''t get to finish it because of how often the game crashes. Very strongly not recommended.', 'Very Positive', 80.69, 18.68, 11.95);
INSERT INTO reviews VALUES (1929, 242820, 1257, 'this game is too good to be this cheap. short but hard enough to keep us on our toes.\nif you''re a sucker for rhythm and minimalistic games like us, YOU HAVE TO PLAY THIS.', 'First half of the game is no bad, but in the second half you need to replay a lvl from the start point, without checkpoints on the lvl itself.', 'Overwhelmingly Positive', 95.07, 1.67, 2.00);
INSERT INTO reviews VALUES (1930, 242840, 442, 'What a neat game, really awesome experience getting to see the game respond to your spoken words', 'The good, the concept of using your own voice to cast spells is amazing. This game actually does a decent job with the spells and voice mechanics. Some of the rooms are beautifully designed and had lots of work put into them creating a mystical atmosphere. The bits of story and lore from journal entries and inscriptions left me wanting to uncover the secrets of the ruins I was trapped in. These positives however were not enough.\n\nThe bad, it has huge performance issues and the recommend GPU is i', 'Mostly Positive', 75.79, 12.42, 4.27);
INSERT INTO reviews VALUES (1931, 242860, 17327, 'As a History Buff, The Accuracy and Details really stick out to me. As a Racist, the in game text Chat is appealing.', 'Really want to give this a postive review because it''s fun but saturday night with a sale and there''s 48 players total online.\n\nsorry to say, dead game.', 'Very Positive', 88.45, 10.88, 0.52);
INSERT INTO reviews VALUES (1932, 242880, 2231, 'It feels as if this game was never truly finished. Regardless, I enjoyed it thoroughly. It''s terrifying and gratifying.', 'This game can be a lot of fun and is pretty unique, but on a playthrough I just had a fragment end up being stuck inside a rock with no way of getting it, so a game breaking bug, man, if you were almost done the game and your last fragment was like that? Could drive a man to insanity, thankfully in my case it was only my 2nd one. So that''s why I''m giving it a negative review just as a warning for some people, if you can forgive that and would start over after an "Aww shucks" then go for it.', 'Mostly Positive', 79.74, 18.20, 15.57);
INSERT INTO reviews VALUES (1933, 242920, 25160, 'Folks leaving bad reviews in 2025 were not around a decade ago when this masterpiece dropped and changed everything. There''s a million banished clones and nearly every city builder of the last decade was hugely inspired by this game.\n\nIf you don''t remember staying up til 4am the night that this game dropped because you couldn''t put it down, then you won''t understand the significance of the game. At the time it dropped it was revolutionary, and it''s a core memory for anybody who was around at the', 'I have to call this one out. Its not broke but it could have been better. I cant categorize this one as what I call ''a real game''. Its fun for a day, but my complaint is that all you do is gather food, tools, and clothes. Citizens can go to a bar or church too. I could have thoughts of a thousand more things they could have added. It seems like one of those games they spent 2 months developing, then forgot about it. Its not the worst game and its playable, but I learned in life to be selective o', 'Very Positive', 89.98, 112.53, 32.27);
INSERT INTO reviews VALUES (1934, 242940, 293, 'Absolutely one of my favourite games of all time. The humor and story never get old. Eddie knows.\n\n\n\n\nMy playtime here is low as i used an original CD version since years. I just wanted this game in my library.', 'Classic steam selling broken versions of games. Another GoG exclusive.', 'Mostly Positive', 79.86, 1.53, 1.97);
INSERT INTO reviews VALUES (1935, 242960, 596, 'Play it whit Blood Omen 2: Conceptual Edition\r\nLink : https://www.moddb.com/mods/blood-omen-2-conceptual-edition/downloads/blood-omen-2-conceptual-edition1', 'I love this game and series.  But it is almost unplayable on steam.  crashes, freezes, can''t tab out without something going wrong. no controller support.   soul reaver 1& 2 now have remasters coming out.  please give the rest of the series some love and attention.', 'Mixed', 65.10, 18.32, 0.93);
INSERT INTO reviews VALUES (1936, 242980, 485, 'You can''t leave without your buddy, Superfly.', 'john romero has made me his bitch', 'Mixed', 61.86, 2.98, 0.15);
INSERT INTO reviews VALUES (1937, 243000, 284, 'It''s the worst David Cage game. Play it for the shitpost, especially if you have a couch and some Canadian friends.', 'i can''t believe omikron killed david bowie', 'Mixed', 69.37, 1.40, 1.47);
INSERT INTO reviews VALUES (1938, 243020, 154, 'I see a lot of reviews are stating incorrect information. Contrary to what some people indicate, the game does run perfectly fun on Windows 11. I tried it on both a desktop and a laptop. Both worked fine. Contrary to what some people indicate, this is not a port or an emulation of the PS1 version: this is instead the native PC version, that uses a Glide wrapper so that we can use the 3DFX version. Contrary to what some people indicate, you can choose your resolution (I am playing at 2560x1440) a', 'i''m legitimately disappointed in the steam release of Pandemonium. A quick test run with a PS1 emulator from back in the day has shown that the emulator has better quality than the steam port. In every respect. \n\nWhile I don''t endorse piracy, having purchased the game only to find a running the PlayStation disc version through a PS1 emulator is of a better quality is quite honestly shocking and disappointing.\n\nWould I recommend the game? Yes\nWould I recommend this product? Hell no.', 'Mixed', 61.04, 12.02, 0.52);
INSERT INTO reviews VALUES (1939, 243040, 622, 'I love this game to death, I originally played it on a CD-ROM in the 2000''s, and it''s just as interesting and charming as it ever was. Highly recommend playing through the tutorials and campaign to fully experience the game''s sense of humor.\n\nIf you''re playing on a modern computer, switch on the beta in your steam config for some better hardware and resolution support. But honestly, play it at a smaller 3:4 resolution, because there aren''t any GUI scale options and it''s crazy hard to read at eve', 'Game has never even gotten to start screen for me.  A warning to others that if it doesn''t open then don''t keep trying, because if you go past 2 hours of ''time'' in whatever way Steam counts it then you will be refused a refund.  So, I''m now stuck with a never functioning ''game.''', 'Very Positive', 90.51, 3.92, 34.05);
INSERT INTO reviews VALUES (1940, 243060, 103, 'Urban Chaos, my number 1 nostalgia game. This was my first big purchase as a kid back in 1999. I was 9 years old when I bought this game with my own money. This game is the most special to me. Im very glad this game is available on Steam, although I still have the original CD. Sadly I do encounter the same problem with this Steam version as with my original CD. Every now and then when there is a dialogue (and there are quite a few) the game crashes. It''s very annoying since the game has no mid-s', 'Was excited when I saw this on Steam and I bought it, as I wanted to relive the classic game. My excitement was short lived as within a few minutes of me playing the first mission "RTA", the screen went black. I restarted my PC and tried again and this time, when I was about to complete the first mission, the whole game froze and I had to force close the game. Utterly disappointing, as I loved this game back in the day.', 'Mixed', 65.05, 3.42, 1.08);
INSERT INTO reviews VALUES (1941, 243160, 112, 'What about Mushroom 1, Mushroom 2, Mushroom 3, Mushroom 4, Mushroom 5, Mushroom 6, Mushroom 7, Mushroom 8, Mushroom 9, or Mushroom 10?', 'A Platforming Puzzle game with the core mechanic being Luck!?\n\nImagine playing Mario. Now instead of the jump button being jump, have it set to 50% chance to Jump and 50% chance to Shoot Fire Flower.\n\nMix that with the later levels that require perfect platforming and fast timing, this game is more frustrating than enjoyable.\n\n', 'Very Positive', 87.50, 0.52, 6.45);
INSERT INTO reviews VALUES (1942, 243200, 905, 'My favorite point and click games of all time! Was definitely an improvement from Chains of Satinav, as I found the puzzles to be a little more straight forward and enjoyable. Loved the characters and the story, and the ending definitely stuck with me. Would love a third game more than anything!!!', 'N.O.P as in nop! The guy character rarely annoying with poor voice over, hoped to have female protagonist in this one, alas this pesky dude still in the game. And just general poor quality, although some areas I see got improved.', 'Very Positive', 88.95, 7.73, 11.13);
INSERT INTO reviews VALUES (1943, 243220, 357, 'Lovely. Black and Glow. Easy puzzles, wonderful music.', 'I like playing with different DAWs and synthesizers. Patching synths together with MIDI and jamming a session is a lot of fun. I''ve also always liked taking any kind of sound and seeing what I can do with it using programs like Audacity.\n\nTo me, all the above is much more fun than FRACT OSC. I really wanted to like it since it seems right in my wheelhouse for fun, but it''s not. What comes to mind is what a reviewer said about Zachtronics games - a Turing Tarpit but on a different level of frustr', 'Very Positive', 87.11, 14.37, 1.82);
INSERT INTO reviews VALUES (1945, 243360, 197, 'vroom', 'Evil ubisoft scammers stole my license to the game and are holding it hostage, even with original proof of purchase. Password to unnecessary secondary Ubisoft account mysteriously changed and they refuse to recover, not bullshitting.. Unfortunately... Worst publisher in the business.', 'Mostly Positive', 79.19, 142.02, 26.17);
INSERT INTO reviews VALUES (1946, 243450, 470, 'تمت كتابة هذا النص باستخدام ترجمة جوجل.', 'Tracks are bad and there''s a stupid stars system to unlock tracks, I don''t care I just want to play !', 'Mostly Positive', 77.02, 12.98, 1.38);
INSERT INTO reviews VALUES (1947, 243470, 17111, 'Game #25 of My Backlog Clearing Journey \nStatus:  Completed\n\nI don''t care, this game slaps hard. Thinking about it and seeing what this series came to, completely abandoning the tone and ideas behind the original, makes me sad as hell, dude.', 'Ubisoft F**ked me F**ked me hard cant play any ubisoft titles because i recently changed my account and I " on " dont own this game F**k Ubisoft connect', 'Mostly Positive', 73.61, 41.43, 0.25);
INSERT INTO reviews VALUES (1948, 243780, 457, 'tons of childhood memories with this game. From PSP, to PS Vita, and of course I needed to have it on Steam as well. I love how playful it is.', 'More of a puzzle game than a tower defense game.', 'Very Positive', 87.96, 16.45, 0.53);
INSERT INTO reviews VALUES (1949, 243800, 1123, 'It''s like Flatout, Mario kart and Twisted Metal had a threesome and had the baby born in Texas and after that moved to Croatia to find jobs.\n', 'Very grateful I got this as at under $4. CONTROLLER DOES NOT WORK. DO NOT BUY', 'Very Positive', 88.07, 4.52, 0.18);
INSERT INTO reviews VALUES (1951, 243930, 1468, 'Oh boiiii, the Devs CLEARLY didn''t finished the game on the hardest difficulty and said: "Yes, this final boss seems fair and balanced. Release it!"\r\n\r\nAside from that, I decided to buy and try this old beautuy from my childhood now that I am older and I just wanted to ask. Spider, why are you doing this?\r\n\r\nYou gave us a goth-ice baddie and proceeded to lock her in the bad route of the game? Shame on you, the game is fine overall as it follows Spider formula of a dark fantasy RPG with the same ', 'They should rename this game The Shit-cher.\n\nNah, I''m just kidding. It''s not that bad, it''s just also not that good either. It seems like a competent 360-era hack and slash, but then you start to notice the smell: the checkpoints start getting farther apart, the quests start becoming fetch quests, and the voice acting does NOT get any better. The story is trying so hard to have the characters from The Witcher in the world of Dragon Age, but it''s just so poorly written. The protagonist is one of ', 'Mixed', 64.03, 23.18, 5.93);
INSERT INTO reviews VALUES (1952, 243970, 3432, 'This game is amazing, don''t listen to people who say otherwise. :3', 'Stealth Xcom. That about sums it all up though, I can''t really point to any breakaway feature. For it''s effectively simplified mechanics it sticks around far past it''s welcome. That''s the thing I would say drags it into the red. They took a 10 minute story and stretched it across many hours of gameplay that isn''t sustainably interesting for that long. I remember lowering the difficulty on the last series of what should have been climactic missions not because it was too hard but because I just w', 'Very Positive', 90.88, 372.18, 7.95);
INSERT INTO reviews VALUES (1953, 244030, 1113, 'Very good game.\nIt offers surprisingly much for its price, in fact 2 games in one. One where you build a rover and launch/drive it and another game which is a survival game on foot as human. Give it some love and it will grow well. :)\nIt is an amazing survival simulator.\n\nOf course it have bugs! But nothing too ruining or so.', 'I really loved this game but it was never finished.\n\nIt is a buggy mess and content is scarce. I actually was able to finish the game but I felt beat and it wasn''t rewarding at all. \nThe best part about this game is the beginning stages, once you are actually a human on mars it turns into a nightmare.\n\nLack of content is really meh. This game had potential but was abandoned.', 'Mixed', 52.47, 148.42, 51.97);
INSERT INTO reviews VALUES (1954, 244050, 259, 'I found this to be a good game, with a lot of content available. Since this is a simulation, it has the things you expect, good graphics, good fidelity (I''ve never flown an actual WW1 fighter, but things seem right to me FWIW), and enjoyable. \n\nI say enjoyable for me, but it may not be everyone''s cup of tea. It aims for the same realism as DCS, and coming from some time in DCS I think it compares favorably. Because of the setting, I didn''t have to spend 10 hours programming a joystick and wading', 'Christ. The sim is great, but everything around it is not. You have to create an account on the RoF website, log in every time you play, activate all DLC bought on Steam on their website, etc. And sometimes their codes just don''t work and you have to contact customer service to try to fix it.\n\nThat was my mistake, though - I should''ve just straight refunded this game when that happened. Their customer service is no joke one of the worst I''ve ever experienced. They treat you like a scammer, ask t', 'Mixed', 63.32, 57.52, 4.95);
INSERT INTO reviews VALUES (1955, 244070, 267, 'Simple, quick, and cheap fun with a satisfying amount of depth.\nNicely captures the feeling and aesthetic.\nWhat more do you want for the price?', ' Played it on iOS, it''s a fun game if you want a quick little maneuver-em-up.  Unfortunately, I couldn''t get it to not crash.', 'Mostly Positive', 71.16, 20.80, 0.20);
INSERT INTO reviews VALUES (1956, 244090, 146, 'this game has decently thrilling battle engagements. The dogfights are intense and demand strategic maneuvering, with every encounter feeling like a high-stakes chess match in the sky depending on the difficulty you play on lol. The game strikes a balance between accessibility for newcomers and depth for veterans, ensuring that players are consistently engaged. While the missions can occasionally feel repetitive, the excitement of outmaneuvering enemies and delivering precise strikes keeps the a', 'compared to Ace Patrol, Pacific Skies really leaves a lot to be desired, there''s more bugs and if anything less features. Also it seems in Pacific Skies damage is linked to the difficulty whereas in Ace Patrol it isn''t. this manifests in pacific skies as downing planes in a single attack vs having to make a few passes in Ace Patrol. (this may be a reflection of the technological advancement between ww1 and ww2 however for gameplay purposes it''s a miss)', 'Mixed', 68.49, 11.48, 2.20);
INSERT INTO reviews VALUES (1957, 244160, 7460, 'Instead of playing the "new" homeworld 3 by the self insert narcissists at gearbox, play this collection instead.\nWell, buying it might encourage gearbox to further screw it up.\nBut compared to homeworld 3, this much much older collection will make you feel more like you are in a grand space strategy game, (instead of power fantasy of a middle aged women in middle management).\nYou will also get to experience many game mechanics the developers had the funds and time to implement instead of modeli', 'Game crashes before loading screen. If you decide to purchase it make sure to test it right away so you can request a refund.', 'Very Positive', 87.44, 16.40, 0.22);
INSERT INTO reviews VALUES (1958, 244210, 51734, 'its okay on its own but if you get content manager, add the Shutto Expressway map and drive at night listening to spotiy, its amazing', 'Game itself isnt bad but everything else about it is, the ui, the performance, the compatibility. its a good sim racing game but horrible when it comes to quality of life.', 'Very Positive', 92.84, 74.77, 6.22);
INSERT INTO reviews VALUES (1959, 244410, 160, 'Here you can realize the plans of the Reich.', 'They''ve been releasing the ''Supreme Ruler'' title ever since 1983 and the original Z-80/DOS version.  That version is the only one they''ve ever finished.  SR 1936 here was ''fully released and finished'' just a couple months ago (summer 2014) and in many peoples opinions is far from finished.  Not to worry though, they''ve already got SR Ultimate on Early Release.. this''ll be about the 5th iteration of the title and just as unlikely to be actually a finished game as the others.', 'Mostly Positive', 71.88, 11.85, 109.28);
INSERT INTO reviews VALUES (1960, 244430, 1135, 'A 10 year-old remaster of a 24 year-old remake of a 31 year-old game.', 'I liked the game. It''s indeed a great classic that inspired games such as Outer Wilds. I love the lack of hand holding. I truly believe games should at least have a setting for hand holding. It can be very frustrating for some, that''s understandable, I was in many instances in my playthrough, but for people who likes not having them, there should be an option. This game really encourages the player to explore, experiment, and be curious. I love it.\r\n\r\nHowever, it''s hard for me to overlook the is', 'Very Positive', 89.07, 7.45, 26.07);
INSERT INTO reviews VALUES (1961, 244450, 15971, 'The greatest game ever created for the PC. By a mile. With the mods there are endless scenarios of victory and defeat. Been playing since 2014, 8000 hours and still play every day over and above my hundreds of other games.....', 'They took away single player skirmish against AI and placed it behind a 10 dollar DLC. I never write reviews but I will never recommend a game that takes content away that was already in the game when I purchased it just to have to spend more money to access it again.', 'Very Positive', 91.74, 8693.68, 148.05);
INSERT INTO reviews VALUES (1962, 244590, 117, 'If you like LAZORS, Flying through the air and balls, you''ll love this game. Action-packed game with constant battles for the ball and land possesion. Never a dull moment with this game. Form a group with some friends, start a team, develop tac-tics and play agains the people of the game, or sign up for the frequent community tournaments. Or play by yourself with whoever else is online. Cool consept, amazingly well executed, awesome design and great gameplay. \nReally cool game, loads of updates,', 'Game is great, community is non-existent', 'Mostly Positive', 78.63, 210.55, 10.12);
INSERT INTO reviews VALUES (1964, 244710, 1517, 'idk when i got to 180 hours but ok.\nits a cute game and its fun', 'Basically a walking sim with minimal gameplay. The artistic elaboration is not bad / quite fitting and overall I would rate it as a niche, mediocre game.\n\nIt takes 30-60 minutes to complete the whole game which is not enough to justify the price tag of 15€. If you can work with these type of games, you can get it at a 75-90% price discount.\n', 'Very Positive', 86.29, 180.12, 3.12);
INSERT INTO reviews VALUES (1965, 244730, 970, 'My wife said if this review gets 50 likes and 5 awards, she will buy a case of beer, guys help me out.\n', 'Divekick is broadly comedic in both premise and execution, and its aggressively simplistic controls were enough to make me curious about the game. However, like most fighting games, there isn''t much of a single player experience, and unfortunately I think that Divekick is too weird to garner enough broad appeal to retain traction for competitive or casual multiplayer so far outside of its original release.', 'Very Positive', 91.34, 0.43, 1.15);
INSERT INTO reviews VALUES (1966, 244750, 138, 'If you feel like bashing someone to oblivion, do play this game.', 'Super odd singleplayer fighting game, just doesn''t vibe with me.', 'Mostly Positive', 78.26, 12.62, 0.83);
INSERT INTO reviews VALUES (1967, 244770, 1705, 'What they really need to do is add full mod support allow access to basically every file for solo devs to bring this game back.', 'Honestly, after playing this game when it had its own launcher and playing it a bit on Steam, I''ll just say this.\n\n\nPlay Avorion instead, it''s 10x the game Starmade will ever be.', 'Mixed', 66.98, 0.43, 15.33);
INSERT INTO reviews VALUES (1968, 244810, 246, 'A fun Co-op, with an interesting story! I''d definitely give it a go if you''re looking for a good night with a friend.', 'Not Recommended.\r\nDoesn''t let you to family share the game.', 'Mostly Positive', 75.61, 4.50, 1.48);
INSERT INTO reviews VALUES (1970, 244850, 65290, 'I recommend this game but with a hitch.\n\nIt''s a decent game but the base game building menu is cluttered by items locked behind DLC. You can still see these items if you own the base game but do not own the DLCs. The devs should really add a way to filter out building items that you do not own from showing in the build menu.', 'I cannot support this kind of game design ... \n1) Make a very nice tech demo. \n2) Add useless cosmetic crap and small incremental changes \n3) Never actually  add gameplay ... just empty sandbox nothing. \n4) After 12 years of development you kind of add NPCs but its lame, pointless, and terribly implemented.  \n5) Rely 1000% on mods to ALMOST make this a game.  \n6) Launch the sequel ...', 'Very Positive', 89.87, 403.70, 292.38);
INSERT INTO reviews VALUES (1971, 244870, 1536, 'A game that is simply unforgettable.', 'Jank ruins an otherwise good game.', 'Very Positive', 88.61, 10.58, 2.23);
INSERT INTO reviews VALUES (1973, 244910, 702, 'https://steamcommunity.com/sharedfiles/filedetails/?id=3330236777\nhttps://steamcommunity.com/sharedfiles/filedetails/?id=517995832\nhttps://steamcommunity.com/sharedfiles/filedetails/?id=3331429932', 'game bugged out on me in second area nightmare. the area where i was supposed to go to break the door wasnt lit up so i was stuck there and gave up.', 'Mostly Positive', 74.50, 2.15, 0.87);
INSERT INTO reviews VALUES (1976, 245150, 444, 'Very fun and unique game.\r\nAlso the main character''s voice actor is goated.', 'I cannot recommend this game, for a number of reasons.\n\nThe game *is* visually pleasing, with a pleasant art style, the story seems to be well-written, and the game runs well on a Windows 10 machine with no tweaking needed (no need to run in compatibility mode). That said:\n\nAccessibility is bad.\n\nVery small text, difficult to read, even at 2560 x 1440 . No Text or UI scaling options. Only resolution options (max is 2560 x 1440).\n\nThe game uses several different fonts, some of which are hard to r', 'Mostly Positive', 78.60, 3.17, 1.45);
INSERT INTO reviews VALUES (1977, 245170, 11703, 'I do not care about all of the buttshots or whatever else, all I want is Big Band''s actual story back.', 'Used to be a great passion project by dedicated developers who slowly betrayed each other until everyone was ousted and the IP was bought out and sterilized by some outside company looking to only turn a profit.', 'Very Positive', 87.18, 46.75, 5.83);
INSERT INTO reviews VALUES (1978, 245280, 2736, 'Solid game even in 2024\nbeat it,no game breaking bugs .\nenjoyable through and through\nrating 94', '  not impressed in the slightest. feels like a PS1 game. boundary restrictions and unclear paths. The camera doesnt know where to aim. was probably great 10 years ago. not great now.', 'Very Positive', 84.28, 15.37, 1.10);
INSERT INTO reviews VALUES (1979, 245300, 465, 'They removed the multiplayer function... that''s the whole point of the game...\n\nAnd yet... it''s still not bad?\n\nReally, the only negative thing about this game is the graphics that haven''t aged all too well. But the puzzles, story and gameplay? Easily enjoyable by all ages, don''t let Mickey''s face being on the game fool you.', 'i''ve played this game in the past on the wii and hey this game is not bad at all!! \ni love and will always love the epic mickey series, but this port in specific just removes a feature thats crucial for the entire game to function, local co-op!!\nor even co-op in general, this is literally a singleplayer version of the game whose name is "Disney Epic Mickey 2: The Power of Two", bear in mind that the "two" is you and a dumbahh cpu cause u cant play multiplayer at all\n\nthat being said, this game i', 'Mostly Positive', 74.84, 14.17, 0.30);
INSERT INTO reviews VALUES (1980, 245370, 280, 'this game was definetly made by developers who had at least basic knowledge of how to code', 'Game crashes after every match.\nVery sad, cause the gameplay seems fun so far.', 'Mostly Negative', 37.86, 1.20, 2.55);
INSERT INTO reviews VALUES (1981, 245410, 140, 'I recommend this game. Here are some tips:\nInstall the automap mod before starting the game,\nread the game manual to choose character races,\nforget about high ''karma'' and ''personality'', \nhowever, maximize other class-specific stats,\nmake coffee and now you are ready to begin a great adventure.\nP.S. develop your ninjutsu and spellcasting skills, it will help a lot in boss battles.', 'Big Wizardry fan. Played all of them when they originally came out, but Dosbox versions on Win 11 are just unplayable in their modern versions. This needs the TLC that Digital Eclipse gave Wizardy 1 or InXile gave to Bard''s tale. All these titles, the original Heroes of Might and Magic series, the Ultima series, and etc, deserve to be preserved for the next generation of gamers and be playable on today''s machines. I can''t recommend it in its current state.', 'Mostly Positive', 76.43, 139.13, 0.22);
INSERT INTO reviews VALUES (1982, 245430, 164, 'This game might be the greatest arpg of all time.  But, that requires that you play it in a time preinternet and pre information overload.  Once upon a time, you just rolled a few characters and made the best of the adventure.  Now, you know everything before the game unfolds and spend 100 hrs rerolling levels and character creation...\n\nJust like everything else in modern life, information over load kills beauty and joy.  \n\nNow its just a shit game where you spend 5x as much time rerolling and s', 'After spending over an hour building my characters and ready to play the game, I was surprised to see that a code word was necessary in order to play! I was ordered to look up page 25, 4th paragraph, 3rd line, 5th word on the manual (?). When I purchased the game I was not informed I would need a manual. And as you all well know, if you don''t get your game played within a VERY short period of time and if it doesn''t work, you''ve lost your money! I looked up the "manual" on Steam, tried everything', 'Very Positive', 88.41, 150.27, 1.12);
INSERT INTO reviews VALUES (1983, 245450, 727, 'the very first encounter killed my whole party\n\nedit: after over 100 hours im still on the brink of death', 'Ok, this game has a lot of great ideas, but the combat system is so annoying that I can''t bear it anymore.\nAnd I''m not talking about difficulty - the game is relatively simple if you know what to do (at least on the "Normal" difficulty). The problem is, battles are abundant and boring.\nIt looks like this: you''re exploring an interesting location, suddenly a group of enemies appears nearby. And by "group" I mean "large group". 10 freaking bandits, for example. Or, like, 15 giant wasps. Wizardry 8', 'Very Positive', 88.58, 158.20, 3.05);
INSERT INTO reviews VALUES (1984, 245470, 4684, 'my country have no democracy, so i have to retreat to this simulated world 😭😭😭', 'should let you dodge the bullets', 'Mostly Positive', 74.36, 12.58, 3.83);
INSERT INTO reviews VALUES (1985, 245490, 1400, 'UBISOFT SUCKS\n\nGame is great, alot of fun, but the fact i have to have UBISUCK launcher even though the game is in Steam. Fuck that. Fuck Ubisoft.', 'I was so excited to play this game, single player, on a flight on my Steam Deck. Turns out you have to be online to play it at all. If I could still refund it, I would.', 'Mixed', 64.57, 3.72, 22.67);
INSERT INTO reviews VALUES (1986, 245620, 4702, 'Communism Is The Future', 'I really enjoy Tropico 4 in the past, still played occasionally . So I bought this one. Here are some problems with this T5: 1) The Era system and how you must advance means you are stuck with certain playing strategies. 2) A lot less control such as salaries. 3) too much unrest that can''t be explained. 4) A lot of things lack explanation.\r\nOn the good side, farming is good.', 'Mostly Positive', 76.35, 16.48, 61.78);
INSERT INTO reviews VALUES (1987, 245730, 218, 'A pretty faithful remake. No it''s not a AAA modern game but very good update of a classic.', 'Cannot access this game on any device that I was able to from my only Steam acct and I never had to register this with another acct and can''t.', 'Mixed', 50.00, 1.15, 4.70);
INSERT INTO reviews VALUES (1988, 246070, 441, 'This is not a game for everyone. This is not a normal game.\r\nUndeniably an experimental and really chaotic idea of a game. I have to give them even more credit for daring such a feat of a game.\r\n\r\nThis is not exactly a game about hacking or a game about programming.\r\nIf anything, as simple as possible, this is a "programatic" "hacking" puzzle game.', 'Great idea, but this game is let down by game-breaking bugs and tedious gameplay.', 'Mixed', 56.24, 16.67, 8.55);
INSERT INTO reviews VALUES (1989, 246090, 2848, 'Seems like a good product with a lot of content and good music. \nI haven''t tried it yet, but a community guide says it''s a good idea to download the community patch.\n\nFeelings: 90s bullfrog (theme hospital), Star Trek.', 'This game was abandoned in an alpha state in Early Access. It should not be available for sale at all never-mind discounted.\nSo much potential wasted. Go buy Space Haven instead.', 'Very Negative', 16.29, 1.62, 5.13);
INSERT INTO reviews VALUES (1990, 246110, 977, 'This game will have you strategizing who your great, great, great grandson will lose their virginity to.', 'I started off really liking Massive Chalice but slowly lost the appeal.\n\nIt''s turnbased combat with continuing a lineage of different kingdoms, which sounds cool as hell! But the truth is the combat is fine but there are only three classes with each having 3 or 4 sub classes. Which is fine, but it''s not enough to keep it interesting. And building a lineage is interesting at first. But after the first third of the game all you''ll be doing is getting pop ups after pop ups about someone died. So yo', 'Mostly Positive', 72.26, 20.67, 13.53);
INSERT INTO reviews VALUES (1991, 246300, 300, 'Paranormal is a great game to scare yourself senseless with - no two playthroughs are quite the same so you cant even predict the next haunting event, meaning you can never prepare yourself\n\nI think it''s well worth the money, regardless of any glitches or bugs - its worth the experience', 'Abandoned game', 'Mixed', 57.33, 0.33, 10.98);
INSERT INTO reviews VALUES (1993, 246420, 4172, 'One of the best tower defense games of all time. An incredbily charming game with very satisfying gameplay that gets you thinking. You get bonus points if you played this on Armor Games like I did in 2012.', 'Looks great, plays well. My only issue is that I constantly feel underpowered. Which makes the gameplay feel more like a chore than fun. I would love a way to grind up gold gain somehow, or even grind up heroes so they are permanently better. And im playing on casual.', 'Overwhelmingly Positive', 96.26, 24.25, 7.25);
INSERT INTO reviews VALUES (1994, 246580, 2091, 'In 2009, I was a child at GameStop with my parents. They grabbed a copy of House of the Dead: Overkill for the Wii. The nerd at the cash register kept darting his eyes back and forth between me and my captors as he continuously mentioned that this video game contained "a lot of f-bombs". Trying to dissuade them from buying it. He wasn''t successful.\n\nNow look at me, I''m playing a version of that same game in 2025 except I''m typing the "f-bombs". I''m pressing combinations of keys on my keyboard to', 'bought it twice and returned it twice a year appart on different steam sales...\n\nthe game does not work on windows 10 for me, with an rtx4090 , tried to use all the tips to fix it, compatibility mode, ini tweaks, dll''s updated, direct x updates, fullscreen 0, \n\nnothing works, the game simply won''t start, and others say the same on the steam user forums, might be a random bug that affects some pc''s and not others as not every complains. \n\nIn any case, what a shame.', 'Very Positive', 86.99, 6.90, 0.18);
INSERT INTO reviews VALUES (1995, 246620, 22962, 'One of the best sound designs in any game, some of the best gameplay mechanics, and you can destroy france, so it is an amazing game.', 'I really do want to recommend it given how much I''ve played; I wish there was a neutral review option. The premise of Plague Inc is original and gameplay can be quite fun at first, but it quickly becomes dull, predictable, and linear over time, with some RNG frustrations.\nMaking a disease and infecting countries starts to feel monotonous in the main gamemode the more playthroughs you go through, and I''m often trying to find ways just to make it not feel as boring as every playthrough starts to f', 'Very Positive', 93.98, 13.22, 47.73);
INSERT INTO reviews VALUES (2000, 246840, 3227, 'I have a special place in my heart for FATE, as it was the first video game I ever played, courtesy of the Windows XP demo (haha!). Little did I know, it would spark a lifelong passion for gaming, particularly for dungeon crawlers and fantasy games. I vividly remember the day I started playing and the countless hours I spent on my old PC, enthralled by the game''s captivating world. Even though it was just a demo at the time, FATE ignited a love for gaming that has only grown stronger with time.\r', 'Beat this game years ago and decided to pick it up on steam only to find out they disabled the console! wtf way to ruin someones fun. I feel like if we have beat the game and there isnt online access then we should be allowed to access console and do what we want within reason', 'Overwhelmingly Positive', 96.28, 4.80, 0.12);
INSERT INTO reviews VALUES (2002, 246900, 9856, 'I play this game inbetween university classes. A few months ago a dude came up asking what I was playing, and he watched me play for a while before getting it himself and joining me. Long story short, were dating now and we meet almost every day to play this together. this is a 10/10 game and a 10/10 wingman.', 'If you look online many people have had issues with the inability to connect to multiplayer for the past 8 years and the developers response has been to blame it on an incompatibility between the game engine and your router/isp. If the game works for you immediately after install, great. If it doesn''t, don''t even bother. Just refund it. I have spent hours going through everything that has been suggested with nothing working.', 'Very Positive', 93.43, 85.97, 0.52);
INSERT INTO reviews VALUES (2004, 246940, 262, 'this abandonned game ended up being garbage.', 'Remember? When the game name was even different? How bad does a game have to suck that you have to change the name only for it to suck more?', 'Mostly Negative', 21.76, 128.75, 0.82);
INSERT INTO reviews VALUES (2005, 246960, 124, 'Giana Sisters: Twisted Dreams - Rise of the Owlverlord\n\nHas a total of 5 trading cards.\n', 'Too hard to be enjoyable.\nSame problems as the first game. Sound design is not good, controls are not tight enough and the hitboxes are not precise.\n\nMy rating 5/10, not recommended.', 'Very Positive', 83.87, 0.62, 1.33);
INSERT INTO reviews VALUES (2007, 247000, 3355, 'This game is as near 100% accurate and realistic depiction of what it would be like to be an actual hero wandering around a magical fantasy kingdom: Life is completely and utterly unfair, and nobody ever gets what they want or deserve.', 'Going to go back to the actual board game.\n\nThe dice in this game are rigged and are unfair.\n\nNot kidding.\n\nStatistically impossible number of 1''s.', 'Mostly Positive', 78.42, 9.75, 17.12);
INSERT INTO reviews VALUES (2008, 247020, 2902, 'The embodiment of Manifest destiny! \nExpand and generate profit, cook all you can find and eat until you''re too fat to move.\nIf it moves, you can eat it.\n', 'This is way more of a dexterity game than a cooking game.  I would prefer an actual cooking game.', 'Overwhelmingly Positive', 95.21, 4.20, 2.92);
INSERT INTO reviews VALUES (2009, 247080, 12015, 'A game I have over 500 hours in. Do I recommend it? No. No, I don''t, not unless you have 500 hours to dedicate to addiction and Danny Baranowsky''s epic hits. \r\n(Get it. Do it man, get the game. Give yourself over to the pretty colours and dancing.)', 'Well, apparently me, a professional musician who plays numerous instruments for decades and recorded dozens of albums, can''t get the rhytm right to the beat. Ok, sure.', 'Overwhelmingly Positive', 95.82, 705.57, 0.13);
INSERT INTO reviews VALUES (2010, 247140, 402, 'strong game and a tremendous experience\nsoundtrack makes me feel like a sophisticated youth with 8 woodstock bracelets (in a good way)', 'not good = not fun, bad quality even on utra. more like soundodger-', 'Very Positive', 92.54, 56.08, 5.15);
INSERT INTO reviews VALUES (2011, 247240, 1028, 'Don''t let playtime fool you....I have played this on a different platform. But picking it up on steam to try it on the Deck....yes please!\n\nIf you remember Rastan from the arcades and loved it...you will know what you are getting into with this. Volgarr is tough. This is how arcade action games were. It is all about dying and learning as you do. \n\nThe game feels great, and like old school...jumping and not being able to control myself is still frustrating but fun. Level design is done nicely, bu', 'Volgarr advertises itself as being a hardcore old school platformer and that it is, it''s harder than Brock Lesnar if he was made out of diamonds. Which would be ok because difficult platformers are fun and cool - Super Ghouls And Ghosts, Super Meat Boy, Ninja Gaiden, Mega Man. All fun and cool.\n\nVolgarr takes the piss though, you pretty much have to memorise every jump and enemy encounter and if you do it any different to how the game wants you to then you will die. Not very fun and cool.\nIt pla', 'Very Positive', 83.46, 1.70, 2.38);
INSERT INTO reviews VALUES (2013, 247350, 277, 'Collaborative games, playing WITH other players, is far more fun than PvP, and Artemis is an excellent opportunity to collaborate! Tuesday nights at 8PM Eastern/5PM Pacific there''s a game using the free TeamSpeak audio client: Install that, then join Artemis Eastern Front! Saturdays there''s another Artemis group game, the Terran Stellar Navy. Both have DIscord servers to help new players customize their setups.', 'I have no friends', 'Very Positive', 89.17, 6.08, 1.27);
INSERT INTO reviews VALUES (2014, 247370, 209, 'Probably the one game that is better known for its demo on the 3DS over anything else', 'PLEASE READ BEFORE BUYING\n\nI''d love to recommend this game but there''s a game breaking bug and it seems very few people know about it. The game runs way too fast. You can change it in the options in windowed mode and then set it to fullscreen. If you do it in that order then you''re fine but if you switch to fullscreen before changing the game speed then you''re screwed. It says Alt+Enter takes you out of fullscreen but that flat out doesn''t work so you''re stuck with playing the game at super spee', 'Mostly Positive', 75.12, 5.93, 3.27);
INSERT INTO reviews VALUES (2015, 247430, 1237, 'nice game , if want to play this on win10 or 11 and you''re having some kind of slow motion and your game is like freezing, you better go to the game folder and find hitman contracts .ini file and \n add these:\nWINDOW 1\nthen StartUpperPos from 2,2 to 0,0.\n\ni wasnt finder of this issue but i did search for it and i wanted to share the solution with you.', 'This shit doesn''t even work on modern pc''s. Even walking in the very first scene is impossible. the closer i got to the door, the slower 47 got, before stopping completely. Don''t sell games that don''t work.', 'Very Positive', 84.64, 5.92, 0.15);
INSERT INTO reviews VALUES (2016, 247660, 1933, ' We are gonna miss you a lot David Lynch. \nThanks for everything.', 'For the PS3 and Xbox 360 this game worked. For PC this game is unplayable.. It does''nt work at all so don''t waste your money on this broken whatever it is. Look at all the forums online about this game crashing and not working at all. I literally is unplayable for everyone. Not just me. Idk why its even allowed to be in the steam store. Sad cause as a kid i loved this game.', 'Mixed', 65.60, 2.22, 5.33);
INSERT INTO reviews VALUES (2018, 247870, 200, 'It makes me sad to see this game has a "Mixed" review score as to me it is the prototypical example of the kind of game that should be "mostly positive;" you can absolutely find substantial things to dislike about the game, but in my opinion at least some of those things are so deliberately designed and part of the brilliant satire of the whole thing that they are not negatives in the traditional sense.  I will not explain.\n\nNo just kidding, I will.  So all right, FIRST OFF part of why you might', 'Synopsis: Redshirt is mildly fun, cute, but vastly overpriced nerdservice.  \n\nWhile it tackles an old saw with a new seemingly innovative twist of vicariously experiencing a space adventure from the perspective of a nobody who experiences life vicariously through social networking (wow how meta), the end result is a cute and at first funny menu game that shows itself pretty shallow with time.  At first you smirk at all the little references and sarcastic jokes and puns, but then after hours of s', 'Mixed', 40.50, 5.70, 5.67);
INSERT INTO reviews VALUES (2019, 247910, 1289, 'The game is top-end, I advise everyone.', 'Zombie shooting on five maps from Sniper Elite 2. Looks like a set of maps for the co-op DLC for the 2 part.', 'Very Positive', 84.56, 9.13, 22.05);
INSERT INTO reviews VALUES (2020, 247950, 744, 'So far, this is the best version of Gauntlet(tm) I have played on pc through steam.\nMy wife & I beat it in under 25hrs -- playing duo co-op, with 2 controllers, on our tv, in one weekend, eating delivery pizza. It is relatively short in terms of content. But so were the old arcade games back in the 1900''s when we were kids.\n\nI have played no other versions of Sacred.', 'If you remember old school sacred, don''t waste your time with this one.', 'Mostly Negative', 25.67, 34.62, 1.13);
INSERT INTO reviews VALUES (2021, 248170, 717, 'Scary fact: behind clickteam there is a france', 'please fix the ability to export packed exes again, nobody can export games normally anymore because every .exe file is now an extreme false positive blocked by everything in existence, like discord and several game uploading sites\neven my computer thinks my game is a virus the second it watches me give birth to it a little notification pops up and goes Scanning... Scanning... like im in some futuristic dystopian society where they banned video games and the robots are making sure my game isn''t ', 'Very Positive', 88.15, 165.12, 203.85);
INSERT INTO reviews VALUES (2022, 248190, 176, 'i''m really not sure what to think about this game, but I think I can at least say it''s one of the most interesting 2D exploration games I''ve ever played. the worst character portraits known to man hide a story that''s both deeply personal and serious yet extremely flippant at the same time. the map is way too big but it''s also cathartic to work your way through bit by bit, dealing with some occasionally cleverly designed challenges. maybe it''s because I haven''t played Within a Deep Forest and Sai', '30 minutes of fetch quests and then the game ends. Not much to be excited about here.', 'Very Positive', 82.39, 16.38, 0.62);
INSERT INTO reviews VALUES (2023, 248290, 181, 'A cute little simulation game. I wouldn''t pay the full price ($10), but I believe I made an okay deal when I got it for $5 on sale. The game doesn''t offer too much gameplay time (aka replay value is pretty low, at least until they release more type of plants and maybe more extra stuff, if they ever do), but again - for $5 it''s pretty much a fair deal. It''s definitely not worth any more than that, though.', 'For $5, you can experience rasterized graphics that only a Flash website could love and compete against garden pests and an eventual winter. In all seriousness, there is little to no reason to call this video game but rather an interactive biology teaching resource as a result of its non-gameplay and bare minimum attempt at demonstrating botany and gardening through edu-entertainment. Reach for the Sun belongs on a website or digital portfolio, not on the Steam store page.', 'Mixed', 63.54, 3.22, 3.62);
INSERT INTO reviews VALUES (2024, 248310, 2424, 'Don''t go into this game expecting a Sonic the Hedgehog clone.\n\nWhile Freedom Planet was originally a Sonic fan game, the physics and gameplay are completely different. So temper your expectations to avoid disappointment.', '"I swear, if the heroine yells ''Cyclon'' one more time, I''m going to refund this game." \nSpoiler: She did.', 'Overwhelmingly Positive', 96.00, 3.82, 0.40);
INSERT INTO reviews VALUES (2025, 248330, 769, 'you''re as beautiful as the day i lost you..', 'not worth the 5$ it hardly has any levels its really easy and just not that much fun', 'Very Positive', 94.93, 2.23, 0.83);
INSERT INTO reviews VALUES (2026, 248350, 261, 'Fun game, with a passionate few people trying to keep it alive (see top of discussions for discord server)\r\n\r\nShame the dev left this game behind, could do with bots or a steam sale to reinvigerate the community and bring new people', 'exploded on youtube when it came out now completely abandoned\nenough said\nservers still work if u and a group a friends have it\nits in a sad state though', 'Mixed', 65.90, 0.97, 21.90);
INSERT INTO reviews VALUES (2028, 248390, 4436, 'Even after so many years, still getting updates and still a superb game', '10 DLC''s released in 10 years.\r\n0 bugs fixed in 10 years.', 'Very Positive', 82.84, 128.43, 223.73);
INSERT INTO reviews VALUES (2029, 248450, 151, 'Stands differenciated among other similar games... it''s worth buying (...and, of course, playing!)', '***WARNING SPOILER ALERT***\n\nWhen I first started playing this game I thought it would be the game I had long waited for.  A space type game where you both command and fight, both in space and land.  Although it wasn''t quite what I had hoped it to be after playing for a little while, I still enjoyed the concept, and enjoyed playing it.  When I became the faction leader I proceeded to concentrate on expanding my Empire while gradually destroying my enemies.  I was doing really good, and then came', 'Mixed', 68.21, 14.20, 14.87);
INSERT INTO reviews VALUES (2030, 248470, 214, 'Not a bad little game when taking into account the small dev and the fact is quite old at this point. This is chapter 1 and 2 out of 4. \n\nI seen a lot of the reviews were critical of the game being too dark and quite clunky. Both valid points. The darkness is a bit excessive but I was able to find my way around with relative ease. Chapter 1 is the worst offender for this. Chapter 2 was certainly creepier and the better of the 2. The story begins to take shape a little here. Puzzles are simple an', 'Nah ameo, te juro que lo intenté, pero el mapa es mas molesto que macabro, no veo un soto papá, quedará para cuando ya no quede otro.', 'Mixed', 56.54, 3.73, 0.52);
INSERT INTO reviews VALUES (2034, 248550, 293, 'this game is childhood relived i remember spending hours playing this as a browser game with my brother for hours replaying the first level a million times now it was totally worth it to buy this game and the developers completely deserve that people buy this', 'I had much higher hopes for this game... The levels lack any real substance and most of the upgrades are generic/mediocre at best. There are "150" different weapons or something like that, and by different-- they mean different in name not what they do.\n\nIn general the gameplay is mostly fun, albeist repetative and lacking any need for skill. Some of the level design is very frustrating and can make the game less enjoyable (think having a drill leg, and drilling into instant death because the le', 'Very Positive', 93.52, 41.27, 55.32);
INSERT INTO reviews VALUES (2036, 248610, 3571, 'My mexican homie played this game with me, he got to play as ICE for once instead of being the one arrested', 'Avoid at all costs. Devs and moderators behind this game are extremely unprofessional and biased. They do not respond properly to constructive criticisms of their games and will ban you if you leave honest feedback or point out issues. The community for the DK games is extremely toxic also, when it has no place to be considering how small it is. Doorkickers was apparently abandoned for the second game(see review for that). It still has a ‘Coming Soon’ section in the campaign that they decided to', 'Very Positive', 93.11, 5.53, 8.15);
INSERT INTO reviews VALUES (2037, 248710, 227, 'Finaly after latest patch I can recommend this game. \n\nThere are still some small bugs like a health bar or some other minor bugs, but in general game is quite good. Graphic is quite good, story also not bad. I''m glaad to say that after update game is finally playable and brings a lot of joy.', 'Bee War-Ned...\nDoo Not Buy...\nTiz Too Bad...', 'Mostly Negative', 20.26, 28.85, 2.97);
INSERT INTO reviews VALUES (2038, 248730, 178, 'When it wants to work, it''s enjoyable. Unfortunately prone to crashes as a result of software decay.\nSemi-functional on the Steam Deck.', 'I want to like this game so much, but I can''t. The music and art direction are phenomenal, and create a unique atmosphere that few games can achieve; but the game itself was just not well developed. I love challenging platformers, but the engine and physics of this game were programmed to screw you over. I''d estimate a whopping 90% of all deaths are the fault of the game, not the player. And that''s being lenient.\n\nSometimes the levels can be really fun, but often they''re just not. Not unfun in a', 'Mostly Positive', 78.65, 1.83, 8.55);
INSERT INTO reviews VALUES (2039, 248800, 535, 'Chapter 2 is on hiatus because you nerds didn''t buy this. I hate you all.\n\nUPDATE: CHAPTERS 2 & 3 GOT KICKSTARTED GG\n\nUPDATE 2: KICKSTARTER FAILED LMAO', 'I just finished this first episode and I must say it was absolutely fantastic!  It''s been a long time since a VN I''ve played had a story that was so engaging and held my interest so much.  I mean, the art is very well done, the music is excellent and the story itself is something that''s rather unique and it was very well written to top everything off.\n\nI could go on and on about how great this visual novel is.  But like others, I can''t, in good conscience, recommend anyone purchase this game.\n\nY', 'Mostly Positive', 75.33, 4.43, 3.18);
INSERT INTO reviews VALUES (2040, 248820, 14757, 'in the rain,..... straight up "risking" it..., and by it.,,.. hahaa.,,..,well lets just say.,.,,.my commando', 'HOW DARE YOU LOCK ME OUT OF A 12 YEAR OLD GAME BY UPDATED THE EULA TO ADD PREDATORY SPYWARE TERMS!\nTake-Two needs to keep their slimey hands off these games, ruining it by forcing eula so now i cant even play it. first you ruin borderlands and now this? worst company i will actively avoid any game by gearbox or take-two, thanks hopoo for selling out your players for some quick easy cash, i will never support yall either. i want a REFUND for all these games that have been basically locked out cau', 'Very Positive', 93.50, 46.98, 98.93);
INSERT INTO reviews VALUES (2041, 248860, 3545, 'I beat a man half to death for his shoes, decided to show him mercy and let him live. He came back with a friend, a wrench and a lesson. \n\nMercy to your enemies is cruelty to yourself.', 'A shoe lasts about week before it falls apart. All buildings are completely stripped of doors, plumbing, wiring, and woodwork. The concept of a door is alien to you, anyway. You need to drink a full bottle of water every two hours, or your sleep is interrupted. The whole world is populated by dogs, who have nothing to do and nothing  to eat, except you. So all dogs of the entire world stand in line to wake you whenever you try to sleep. When you do manage to sleep, you wake up from the sound of ', 'Very Positive', 89.17, 93.22, 78.78);
INSERT INTO reviews VALUES (2042, 248970, 280, 'best childhood game ever\r\n', 'i hope whoever designed bonus 1-9 choke on their own saliva \r\n\r\n\r\n\r\n (this is a joke review great game tho) ', 'Very Positive', 86.43, 27.22, 12.80);
INSERT INTO reviews VALUES (2043, 249050, 6472, 'Such a good game. I have all the Endless games made by Amplitude Studios. You will love the visuals, the music, the game-play. Everything is high quality and worth. All the DLC''s are well priced and the studio has regularly updated the games. 5 stars for me.', 'I enjoy the vibes and art direction a lot, but man this is just not fun. It feels you''re marching, where each stride takes an hour but once your foot hits the pavement its chaos for <30 seconds', 'Very Positive', 87.67, 103.07, 4.18);
INSERT INTO reviews VALUES (2044, 249130, 7005, 'Played this as a kid. I don''t know how I found the time to get over a thousand hours. I don''t know how my younger self did it. Lotta memories with this one, that''s for certain.', 'I hate LEGO games', 'Very Positive', 93.48, 1449.10, 34.85);
INSERT INTO reviews VALUES (2045, 249190, 198, 'hidden #💎', 'take it back and do it over, not ready for sale ,', 'Mixed', 43.94, 1.73, 14.73);
INSERT INTO reviews VALUES (2046, 249230, 1431, 'Imagine a game where pirates, demons, and random bugs team up to give you the ultimate fantasy adventure experience. You start off dead, lose your soul in the first five minutes, and then spend the rest of the game doing errands for people who clearly don’t care about your problems.\n\nThe combat system feels like you''re waving a butter knife in slow motion. Want to block? Good luck, because the enemy AI has the brainpower of a caffeinated squirrel.\n\nThe half of the quests involve you picking up j', 'It could be a good game, but with a terrible combat system in which you receive 3 attacks before raising your sword, all of this regardless of the opponent''s distance and your ranged attacks are generally useless.\r\nIn short, the gameplay gets boring in a short time.', 'Mixed', 67.23, 75.75, 4.47);
INSERT INTO reviews VALUES (2047, 249330, 654, 'stressful when i dont want the wife of the skeleton family to die in battle as she brings in the money for rent as being a therapist', 'Very repetitive. Require to major in animes or furries in decent college to ignite his own imagination to make it interesting. Sadly I failed\n<번역>\n반복적이다. 애니나 퍼리 전공을 좋은 대학교에서 한 게 아니면 상상력이 잘 안불타서 재미가 없을것. 난 재미없었다.', 'Very Positive', 90.21, 1.08, 1.50);
INSERT INTO reviews VALUES (2048, 249360, 257, 'A text-based adventure-style survival horror management game where you are the one running this monkey farm!\n\nPROS\n+ Cheap and compact\n+ Generally fair but unforgiving difficulty\n+ Minimalistic yet effective sound design\n+ Clever, immersive TTRPG-inspired interface\n+ Infinite replayability thanks randomly-generated playthroughs\n+ Built-in editor to create your own custom survivours and adventures\n+ Highly-engaging, if not downright addictive gameplay that perfectly encapsulates the tone and atmo', 'No matter what you do, your people will fight with each other. Really its more like dysfunctional relationship simulator.', 'Mixed', 66.15, 74.17, 5.87);
INSERT INTO reviews VALUES (2049, 249550, 223, 'It''s a good game. You can play locally with friends or on a hosted server (there are about 3). It''s basically Dragon Quest meets WoW. I do hope they open-source it one day so the community can keep building on it.\r\n\r\nIt''s a bit grindy, but so are WoW and Dragon Quest.', 'This game is still available for sale despite being dead for almost a decade. Don''t buy.', 'Mixed', 63.23, 176.20, 0.30);
INSERT INTO reviews VALUES (2050, 249570, 239, 'While the game seems dead at the moment, the game itself is excellent. Its more unforgiving than it needs to be, for example having to empty your entire backpack just for leaving a house seems pretty unnecessarily harsh.  But for the most part the game''s concept and execution is fantastic.', 'Good idea, deeply flawed execution.  You are not given enough resources to protect your own meager safe, nor go out and rob someone else''s.  \n\n  I have a feeling only those who have been playing a long time have been able to experience the intricate trap building that should be accessible to every player in this game; and is in fact the primary allure of purchasing The Castle Doctrine in the first place.  For new players, however, the game is simply a race to rip off someone else whose stash is ', 'Mixed', 43.10, 10.75, 9.78);
INSERT INTO reviews VALUES (2051, 249590, 770, 'The perpetual unity and segregation of positive and negative electrons will make this game attractive to platform gamers of all ages. The trailer really pulled me in but what sticks with you the most is the compelling story, drawing you closer to a an electrically charged finale. Polar opposites to games I usually play but I really enjoyed it. \n \nIt also has magnets and stuff.', 'Conceptually nice, but controls felt a bit weird. The boss fights were really frustrating and felt unpolished.', 'Mostly Positive', 79.35, 10.78, 2.88);
INSERT INTO reviews VALUES (2053, 249630, 1752, 'It''s like Barony but good', 'Whilst Delver has some merits, I ultimately can''t recommend the game because it''s abandonware that is labelled as complete. From dungeon branches that are just one or two rooms with a poorly-hidden key "puzzle", that were clearly banged out as placeholders or filler, to giant, ominous doors that can''t be opened, that are labelled to a section of dungeon that doesn''t exist - the game is full of truncated, amputated content.\n\nThe content that remains is relatively undeveloped and samey - you see t', 'Very Positive', 87.50, 3.88, 12.00);
INSERT INTO reviews VALUES (2054, 249650, 1229, 'Misleading title, all of the guards featured are white.', 'Broken achievements, many crashes, bugs, lags.', 'Mixed', 58.91, 402.77, 3.97);
INSERT INTO reviews VALUES (2055, 249680, 1048, 'Very fun game except for the wildly moving camera angles!  Used an Xbox controller.  Definitely worth the sale price I paid for it!  :D', 'This would be a great action combat game if it weren''t for the annoying platforming mini-games that come up every so often.\r\nIf you don''t mind that stuff you should probably get this game.', 'Very Positive', 91.32, 12.05, 5.00);
INSERT INTO reviews VALUES (2056, 249870, 1108, 'i love scribbling my nauts', 'this game fucking haunted my childhood. i played it when i was like 15 so this is what i remember from it: the game requires hyperspecific bullshit answers for every problem and has such contrived scenarios that actually drove me insane. i hate this game, i genuinely hate it and every time i see it in my steam library i get another wave of rage. fuck this game', 'Very Positive', 81.23, 7.87, 10.67);
INSERT INTO reviews VALUES (2058, 249950, 349, 'Better than Diablo 4', 'What ever you do DO NOT BUY this game. It no longer  works.\nYou can watch gameplay videos that show you how to get started\nbut they no longer work. Only thing you can do is name your player\nbut there is NO Way to start the game.', 'Mostly Positive', 79.08, 17.25, 0.08);
INSERT INTO reviews VALUES (2059, 249990, 1143, 'great character customization even with only 3 abilities. Fun and challenging stages.  Good single player and better with a friend.', 'This shouldn''t have been allowed to call itself a single-player game, in my opinion. It isn''t one, and absolutely requires other human players, or you''ll have as miserable a time as I did trying to play it.\n\nDon''t recommend, especially given its age at this point.', 'Mostly Positive', 71.83, 23.10, 0.23);
INSERT INTO reviews VALUES (2060, 250030, 111, 'Beautiful game', 'The art used for the game is really nice. It''s nice to look at and works well with the calm vibes and music it offers. The concept is pretty cool, too. \n\nThe puzzles are simple and easy to figure out once you understand it. \n\nI don''t know if it''s worth the price though...\n\nI''d give it it a 7/10', 'Mostly Positive', 76.58, 4.33, 3.40);
INSERT INTO reviews VALUES (2061, 250050, 703, 'A puzzle game where brute forcing it is sometimes an option. Overall it''s funny and challenging so I would recommend.\r\n\r\n\r\n(Forget the cup. Your mission is Jeff)', 'The physics of the game is terrible.\nFor several levels I can see what''s meant to be done but the climbing and jumping are just impossible to execute.', 'Very Positive', 94.59, 4.97, 0.97);
INSERT INTO reviews VALUES (2063, 250110, 957, 'Premiere twin-stick shooter. Casual play is forgiving and has lots of variety. Local co-op is chaotic fun. The iceberg goes pretty deep with skill achievements and S+ rankings even before you get to score optimization, of which I''ve barely scratched the surface.', 'meh, i got boreed.', 'Overwhelmingly Positive', 95.51, 96.78, 1.90);
INSERT INTO reviews VALUES (2064, 250180, 2408, 'HEAVY MACHINE GUN.', 'Every time I try playing it it fucking changes my display configuration to Portrait mode, who the fuck wants to have their PC in Portrait mode', 'Very Positive', 88.95, 3.62, 0.25);
INSERT INTO reviews VALUES (2065, 250260, 5149, 'I don''t know how to explain Jazzpunk. I love Jazzpunk. I feel I have played an unhealthy amount of Jazzpunk, but to all of those who have dedicated time and effort into this game, in speed running, casual play throughs, or other methods, I salute you. While I have changed my ideas of gaming, and my library has changed, Jazzpunk stays at the same position it always has. My top pick, and I would pick it for game of the year if I could, an all around favorite. I spent time to try and get every inte', 'it didnt load', 'Very Positive', 94.06, 83.12, 167.87);
INSERT INTO reviews VALUES (2066, 250320, 16898, 'The big ((bad)) detective and wolf sheriff Bigby, in his life in Fabletown, where fairy tales and happy endings are more unusual and drastic than expected, tries to solve various incidents for the not so well-being of its citizens. In this journey he will find himself in a plot of intrigue that will bring risks to all the citizens of Fabletown. \n\nBased on the Fable comic book saga, The Wolf Among Us is a narrative story involving choices that can affect the characters'' situations. Teltalle is kn', 'Not allowed to think when playing? Fine, keep your game.', 'Overwhelmingly Positive', 97.68, 48.65, 4.18);
INSERT INTO reviews VALUES (2067, 250340, 2390, 'I was groomed through Blockland in 2013. Good times.', 'god this game is tragic\nit could''ve been something so much more. hell it grew up as the middle child with roblox and minecraft.\nfast forward to now, those two may as well be CEOs of the gaming industry.\nbut this game? it got addicted to crack and fell down a ditch it never recovered from.\nplease. skip this one and buy something else. it''s a lost cause.\n\nand to those who might remember me, hope you''re doing well out there.', 'Mostly Positive', 72.05, 35.57, 1025.05);
INSERT INTO reviews VALUES (2069, 250380, 385, 'A solid immersive game with plenty of room for reflection and personal thought. I''m still surprised that it got more hype than Pathologic. But this is a good project by Ice-Peak Lodge.', 'Your random scripts ruined the whole expirience! Also interrupting player''s actions when an anomaly appears was a terrible idea.', 'Very Positive', 83.90, 2.72, 7.30);
INSERT INTO reviews VALUES (2070, 250400, 4581, 'How to Survive was the first game my first love invited me to play together. It was exciting—surviving on an island filled with zombies, scavenging for resources, and crafting weapons side by side. The game itself was fun, but what made it special was playing it with her.\r\n\r\nUnfortunately, we only made it through a few chapters before she disappeared. Just like that, I was left to finish the first half of the game alone. It was a strange feeling—continuing something that was meant to be a shared', 'A somewhat janky zombie survival game. Combat is mostly boring. After I accidentally crafted a boomerang, I had no real reason to use anything else. At first, I tried to craft a flamethrower, but it was too hard for me to track all the ingredients randomly thrown around inexpressive islands without a proper map of transitions. The story is neither immersive nor entertaining and the "sudden twists" have no real weight to them.\nSadly, I can''t find any features that would let me earnestly recommend', 'Mostly Positive', 76.38, 28.77, 7.18);
INSERT INTO reviews VALUES (2072, 250500, 1457, 'The true story of the Oregon trail, that Ronald Reagan and my 2nd grade teacher hid from us all', '\nSeriously but there are better games of this type and this one is pretty much overrated.\n', 'Overwhelmingly Positive', 95.61, 0.57, 0.57);
INSERT INTO reviews VALUES (2073, 250520, 4489, 'It just occurred to me after playing Underrail for 5 Years with 500+ hours that I haven''t made a review for it yet. Well, it''s like the classic Fallouts, but if you made it truly open world, gave it an engaging storyline from start to finish, made the combat addicting where the enemy ai will punish you logically, have memorable characters and interesting world building as to why the world of Underrail is underground, and allows you to make EXTREMELY deep and replayable character builds (wanna ma', 'This is a very, very good game. While the reputation for being difficult is well deserved, the official forums have endless builds for all difficulties that can make it trivial to dive into the game and play how you want. Even more so if you opt to play a psi build.\n\nUnfortunately, the developer is a raging transphobic racist who''s discord is widely know as a cesspit on the unofficial subreddit. I''m talking real nazi shit. \n\nGet it on a steep discount if you like games that mimic FO1/2 gameplay ', 'Very Positive', 87.19, 559.60, 230.13);
INSERT INTO reviews VALUES (2075, 250560, 689, 'Best memories playing this game were using the dungeon creation tool to try and stack as many treasure chests as possible with as few enemies as possible or by making a map with just an absolutely ridiculous number of easy to kill enemies and farming loot that way.\n\nSandbox style gaming just hits different.', 'Great game, great premise, but one very huge flaw in its design.  The game is based around player created adventures but lacks a fair implementation of advertising any new adventures.\n\nSearching for adventures at first glaces seems to be very complex but after a while you you notice a poor design choice.  Only the top 24 adventures will ever be displayed in a search, no matter how many tags you select.  What does this mean?  Only adventures with a high rating will ever be visible to other player', 'Mostly Positive', 77.50, 18.18, 92.02);
INSERT INTO reviews VALUES (2076, 250580, 473, 'For a nearly decade old roguelike, it''s pretty fun. As many have said, the genre has already been improved upon significantly since launch, but this game stands out thanks to its voxel aesthetic, plus it has some really cool secrets. Dev screwed themselves by sending death threats to Gabe Newell, and imo that should not be overlooked but looking at the game for what it is, it''s a pretty fun time for 10 bucks.', 'I had never played Atonement Edition and boy this game really shows how much better the average indie game has gotten over the years. Yeah it''s not unplayable but Paranautical Activity has maybe the worst menus I''ve ever seen, is ugly as hell, and quickly gets repetitive. And I mean FAST. Environment design is almost completely absent and this feels like a product of the time when "lol random" was peak internet comedy. I wish I hadn''t played this again so I left it with fonder memories. Play alm', 'Mostly Positive', 70.82, 31.40, 0.37);
INSERT INTO reviews VALUES (2078, 250620, 2867, 'I played this game for nostalgia because I remember watching one content creator doing lets play about this one when I was a kid', 'Short game, quite unique, but not amazing.\nI was intrigued by the idea of playing a little kid and having a few horror-ish element, but the game proves itself very limited and a bit clunky at times. \nA fun experience, but not my first pick.', 'Very Positive', 88.07, 3.80, 2.03);
INSERT INTO reviews VALUES (2079, 250640, 140, 'Croixleur Sigma is two things. It''s a pretty neat and enjoyable, if shallow, arena action game that you''ll probably burn out on if you spend too much time playing. It is also a game where you play as a gay sword magician girl with twin tails. The decision of whether or not to buy this game is in your hands, I am simply relaying the facts.', 'Support for this version got dropped and they re-released it with DLC attached. No free upgrade or discount for owners of this original so you have to buy the game all over again to get a supported version. Trash dev + publisher don''t support them.', 'Mostly Positive', 70.00, 2.10, 0.65);
INSERT INTO reviews VALUES (2080, 250660, 202, 'This metroidvania has 3rd Strike parries, what''s not to love?', 'Bunny Must Die! is a cute metroidvania exponent, as we call this genre today, but you sensibly consider it a Metroid clone - design is quite similar to Nintendo''s classic title. It is enjoyable for its audiovisual style, but only if you are accustomed to some japanese excesses - the style is bizarre and exaggerated. Even its game design is appreciable. But what ruins everything is its control and collision system. Collisions are very stiff and controls are terribly inaccurate - sometimes you''ll ', 'Mixed', 67.33, 22.18, 10.82);
INSERT INTO reviews VALUES (2081, 250700, 444, 'Super Time Force Ultra: A Time-Twisting Riot of Action and Humor\n\nGet ready to have your mind and reflexes thoroughly scrambled with Super Time Force Ultra, the electrifying platformer from Capybara Games. This game defies conventional gameplay with its ingenious time-manipulation mechanics, allowing you to rewind, replay, and strategize in ways you never thought possible. The over-the-top action is paired with a hilarious narrative and a cast of bizarrely awesome characters, each adding their o', 'STFU has a fantastic idea but there are annoyances preventing the game from reaching its full potential. It’s a 2D contra like shooter with time manipulation mechanic done differently compared to other games. When you die, you can go back in time and unleash a second copy of yourself while the first copy remains active in the level and repeating what you did before dying. You will need this to get through obstacles and multitask. You can do this with different characters that you will slowly unl', 'Very Positive', 89.86, 11.17, 10.90);
INSERT INTO reviews VALUES (2083, 250760, 9715, 'one of the best and the most painful platformers ever. its really sad that shovel knight is being forgotten over time, even tho it is still better than 99.9% games nowadays', 'This game made me really mad and I really tried to enjoy it. If you''re not good at platformers, or have medium frustration tolerance, this game is gonna make you upset.', 'Overwhelmingly Positive', 95.82, 28.20, 22.80);
INSERT INTO reviews VALUES (2084, 250900, 127365, 'The Binding of Isaac – a game that answers the question: ''What if Zelda had a baby with a B-horror movie, and their grandparent was RNG?\nYou cry, throw poop, die a thousand times... and come back for more. Every run is like a Kinder Surprise: you either get something awesome or end up in hell with your build.\n10/10 – best tear therapy ever.', 'I bought this because I like rogue-likes and this game always comes up as one of the best in the genre.\n\nMaybe the game is showing it''s age at about 10 years as of the date of purchase, but there''s really nothing I enjoyed about this game.  The graphics are uninteresting, with everything some shade of grey or brown.  There are apparently a ton of items and things to unlock, but nothing I found seemed to do much or really told me anything about what it did.  I hated the controls.  Moving the char', 'Overwhelmingly Positive', 97.26, 381.02, 291.78);
INSERT INTO reviews VALUES (2086, 251060, 7901, 'great game the only game I know that you can rush a leopard 2 with North Korean T-34''s and win also they still add content to it even though it''s a decade old so mad respect to the devs even though they are french', 'After 10 years, they''ve come back and started banning people for talking shit in the chat.\nI wasn''t banned but they''ve literally abandoned the game for years, then started banning the small (But dedicated) community they have.\nIf you''re thinking about buying this game, don''t.\nJust wait for Broken Arrow to come out, it''s a better game all around.', 'Very Positive', 88.13, 52.43, 169.63);
INSERT INTO reviews VALUES (2087, 251110, 2222, 'One of my favorite games. Despite its simplicity (it''s a walking simulator), the game captivates with its atmosphere and attention to detail. It''s amazing how the developers managed to create so many locations that feel so realistic.\n\nYou can spend hours exploring locations and finding different bits of lore and secrets. At the same time, you as a player must understand the plot of the game yourself from the documents you found. And the more you find the more layers you will peel in your path to', 'Love the environments and characters, hate how confusing and unintuitive the puzzles are. Half the time I have no clue what to do, in what order, or even where to go. By now I''ve gotten so frustrated that I don''t feel like playing anymore, even though I really wanna see the rest of the world and such.\r\n\r\nI play plenty of slow-paced exploratory and puzzle games and thus really don''t mind that type of gameplay, but this ain''t it chief.', 'Very Positive', 87.71, 42.20, 3.42);
INSERT INTO reviews VALUES (2088, 251150, 5987, 'To my friends reading this; please play this series so I have someone to talk to about it.\n\nStart here and in 12 games & 800ish hours you''ll be all caught up. It''s barely a commitment :)', 'Gameplay isn''t bad but the story is terrible. The writers basically full on support rape which was rather surprising. Basically the girls in your group almost get kidnapped and raped and in they are like No big deal people raping people is perfectly fine lets go have tea.  I am sitting there going...So bracers normally allow girls to be kidnapped and raped in this world and they think that is fine? There is a ton of other terrible parts in the story that just don''t make any sense. Pretty much th', 'Very Positive', 93.69, 104.25, 182.23);
INSERT INTO reviews VALUES (2089, 251170, 1152, 'Please add sex with Big Tiddy Goth Chicks', 'I can''t believe how terribly this game runs. It actually runs so badly that it feels like it was a deliberate effort to do so.', 'Mixed', 67.62, 3.60, 0.57);
INSERT INTO reviews VALUES (2090, 251210, 165, 'totally recommend if you are a fan of the board game and want to practice against AI.', 'Multiplayer network not working as of 11/12/24.\nNow this is completely useless other than to play vs the cold ai. Go get the physical game pieces instead.', 'Very Positive', 80.61, 8.95, 16.28);
INSERT INTO reviews VALUES (2091, 251230, 290, 'Not bad for its age recommend to get it on sale  if you like top/down shooter                                                                                                                     🟢 CO-OP/SOLO top-down shooter with great game play\n🟢 Good graphics\n🟢 3 different classes provide 3 different play styles\n🟢 Variety of weapons with upgrade option\n\n🔴 Being a linear campaign, it''s very short (4~5 hours, although it is replayable\n🔴 Okay story', 'Could be fun.  Ultimately buggy and frustrating.', 'Mostly Positive', 76.55, 29.70, 8.17);
INSERT INTO reviews VALUES (2092, 251270, 874, 'Yuuya kizami the kinda fella to get invited to Diddy''s house.', 'I was hoping for a puzzle/detective game with horror elements, but it''s a horror/gore game with puzzle elements. I got bored after a bit. The music is banging though\r\n', 'Very Positive', 89.93, 22.47, 3.68);
INSERT INTO reviews VALUES (2093, 251290, 2445, 'One of the best experiences I had in a game in my life, it had absolutely everything I needed in a game like this.\nCan''t believe I started this series in 2024!!!! This game is a hidden gem.\n10/10 Masterpiece for sure.', 'I''m an old timer thats played hundreds of rpgs over the years and I find this game way to hard , Even on easy mode some of the main battles took too long and very frustrating. Some bosses never run out of healing power and just drag on until you run of healing and one of your party member is dead. Graphics were great but not game that i will play again.', 'Overwhelmingly Positive', 97.79, 135.87, 8.00);
INSERT INTO reviews VALUES (2095, 251370, 330, 'Escape Goat\n\nHas a total of 5 trading cards.', 'I don''t know why but the game doesn''t launch anymore. As soon as I click to launch, it closes automatically, sadly.', 'Very Positive', 94.85, 0.90, 4.75);
INSERT INTO reviews VALUES (2096, 251410, 144, 'I have been playing games since 1982 and have played a lot! I bought this because it reminded me of a game called Obliterator, that I played on the Atari ST in 1988, by the developer Psygnosis. I wanted a bit of nostalgia and retro and boy did I get it but with modern trappings. This is a very good retro side scrolling adventure, with good atmosphere. It is fairly straightforward and so good to play short sessions late at night when your brain is too tried for something more complicated. I think', 'very buggy, the controller support is absolutelly terrible, settings are very limited, you cannot change the voices volume and the subtitles are barely legible in 1080p.\nbasic things like the flashlight do not work as intended, which is critical to gameplay.\nthe game has the foundations for something good but the final product is just very bad.\n', 'Mixed', 42.36, 2.27, 0.37);
INSERT INTO reviews VALUES (2097, 251430, 431, 'This is a point-and-click adventure with a unique world and captivating story. Embark on a quirky, charming journey with hand-drawn art and witty dialogue.', 'The game is rather bugged, and it''s truly heartbreaking T_T\nThe art is awesome! The plot and the universe itself are pretty unique and addictive, but THESE BUGS ARE HORRIBLE! They literally make it impossible to play the game. And there are several (just check the discussion feed). My personal one - after cutscenes the game freezes and won''t let me do anything. All I see is the crossed circle icon every time I try to click on something. Such a bug has not been described anywhere (steam, reddit, ', 'Very Positive', 86.77, 1.78, 8.90);
INSERT INTO reviews VALUES (2099, 251470, 1662, 'As you can tell from the number of hours I played this game, I love it!!\r\n\r\nThe game is extremely fun in all multiplayer modes, the mecanics are easy to learn, hard to master (especially adv techs), but the movements feel soooo great after that! All game modes are playable in solo (except versus ofc), but they''re better in multiplayer. Unfortunately the game doesn''t offer online, but parsec works really well as an alternative!! The OST and pixel art are also really good.\r\n\r\nI''ve played this game', 'Great game, terrible PC port.\r\n\r\nThe game lacks any rebinds, you move with the arrow keys and shoot with the "X" key, also you jump with the "C" key, don''t like those bindings? Fuck you!\r\n\r\nWhat about vsync, graphical settings? The only setting that is available is vsync on or off, which is good, but the framerate is uncapped -which in a pixel art game like this one only means one thing-, 1000+fps; oh and the nvidia max framerate limiter doesn''t work for this game, is simply not compatible.\r\n\r\nS', 'Very Positive', 94.46, 1153.80, 0.97);
INSERT INTO reviews VALUES (2100, 251490, 119, 'Everytime I play this it just gets better. Even when I was too young to understand the plot, this game brought me to tears. I''ll always hold this game close to my heart.', 'After an hour, I can''t recommend this game. It''s adorable and the story I saw looks like it''s shaping up to be heartbreaking, but the gameplay is tedious and doesn''t look to be evolving much.\n\nI might continue to play after that, but for a damning, nauseating interface flaw. After each stage/level/room, the game returns to the main map, Unfortunately, when it does so, the camera always starts oriented "north" on the topmost part of the map, and then quickly pans and rotates to your current posit', 'Overwhelmingly Positive', 96.64, 11.77, 1.23);
INSERT INTO reviews VALUES (2103, 251570, 115362, 'Is this game good? Yes. Is it worth 44 dollars? no. 1.0 release was just so they could charge more for the game. Its litterally the same exact game with the same bugs and issues before 1.0. Get it on sale or dont get it', '     Frankly, after over a decade of Early Access and constantly changing and reworking things, you''d expect the devs to have settled on an appealing vision for the game, optimized and fleshed it out, and polished it up for release. They''ve had plenty of time, game sale money, and experience to do so, and yet the so-called 1.0 update is a glorified Alpha just like the 21 Alphas before it. No change in update files at all from the test build, very little optimization to the point of destroying pe', 'Very Positive', 88.09, 56.92, 1572.82);
INSERT INTO reviews VALUES (2105, 251630, 795, 'i love seeing people call this a GD ripoff when the original version of this came out in 2009 and GD came out in 2013. this version was on steam before the GD steam version came out. smartest GD players, i swear', 'This game is absolutely a knockoff of the "Geometry Dash." I would recommend you to play the original game, since it tends to have more features.', 'Very Positive', 84.28, 2.52, 1.75);
INSERT INTO reviews VALUES (2107, 251690, 198, 'Had this on my Amiga back in the day, great to see a Bitmap Brothers game on here and now again on my PC, whilst this seems to be the only one here''s hoping more appear! This is exactly as I remember it, fun and silly, and keeps you coming back for that promotion or that elusive cup win! ICE CREAM!', '- Controller doesn''t work in game, only in menus (No Steam Input, seriously??)\n- No wide-screen resolution support - seriously 21:9 is pretty common now\n\nPathetic. Calling this a HD reincarnation is pathetic. And disappointing because the original game is awesome and fondly remembered.', 'Mixed', 65.66, 0.22, 0.08);
INSERT INTO reviews VALUES (2108, 251730, 1943, 'Imagine if the developers of a game decided that we will take everything from the first game, put it in a second game but expand every property 100-fold. That''s LoG2....it''s like LoG but on steroids.\n\nGet this if you like old school dungeon-crawlers with good atmosphere and endless options.\n\nOh and did I mention there is an integrated dungeon creator and player made content? Yeah....just buy it already!', 'If you enjoy watching a 7-foot-tall minotaur in your party get their ass kicked by a tiny rat man who inexplicably has 10K hitpoints while they fail to hit them 10 times in a row, this is the game for you.', 'Very Positive', 90.12, 31.88, 2.22);
INSERT INTO reviews VALUES (2109, 251810, 207, 'pretty good. but if you''re gonna publish a game or something, remind the people downloading it to install al sound stuff. they need it.', 'After hours sinking in doing a videogame, the developer decided to nuke FileSystem in the library in a way that now it doesn''t work. Looking into moving to another game engine.', 'Mixed', 69.57, 76.30, 9207.03);
INSERT INTO reviews VALUES (2110, 251830, 346, 'got to make a man pregnant 10/10 game :)\n.\n.\n.\n.\non a serious note i love this game although its very short. It was my first ps4 game so for that it will always have a place in my heart<3', 'It just didn''t resonate with me. I found the characters to be off putting and the style to be the same. The voice acting was really good, but that''s about it.', 'Very Positive', 94.80, 5.45, 1.13);
INSERT INTO reviews VALUES (2111, 251850, 328, 'https://steamcommunity.com/sharedfiles/filedetails/?id=533953934\nhttps://steamcommunity.com/sharedfiles/filedetails/?id=531641662\nhttps://steamcommunity.com/sharedfiles/filedetails/?id=499710868', 'The sound design is absolutely horrendous, the game relies on cheap audio jumpscares that are tripple the volume of the already unbearably loud game where you cant even separately change the volume level of for example sound effects, its all just mushed up in one audio level. The game is severely lacking in explanations, I''m not one to argue for games to hold your hand along the way but for gods sake, dont just throw the player into cold water and leave them wondering whether the game is bugged ', 'Mostly Positive', 75.30, 4.87, 3.32);
INSERT INTO reviews VALUES (2112, 251870, 963, 'Bau Bau~', 'A girl touched me. Too scary.', 'Very Positive', 89.41, 9.33, 2.43);
INSERT INTO reviews VALUES (2114, 251950, 149, 'Ambitious and hardcore WWII MMO—clunky but rewarding for those who love realistic combined battles with infantry, tanks or planes!', 'why are you starting to make checkpoint? You haven''t been able to finish WW2 online for 26 years! bugs, shooting through walls, people constantly using a second account to check the enemy''s position and the administration not giving a damn about it all, even if they are already online... I don''t know why you''re so proud of having a Guines record? 26 you are making a game that doesn''t work lol sometimes they manage to fix a small thing, but they break 10 other, just like the wall in the bunker lo', 'Mostly Positive', 73.15, 138.52, 1343.88);
INSERT INTO reviews VALUES (2115, 251990, 4643, 'this is literally harder than dark souls', 'By being far too open-ended, it turns what could have been a fun CYOA into a trial-and-error chore.\nSome skills are barely used, while others are crucial for every playthrough.\nSome skills you only need to invest a little, while others you have to max out.\nGiven that there''s 24 skills and little advance notice of events/foreshadowing, it''s very difficult to win organically on your first run, which you can do in most other CYOAs.', 'Very Positive', 94.87, 3.67, 1.38);
INSERT INTO reviews VALUES (2116, 252010, 316, 'Its retro enough that I can say this is a good game.\nThe difficulty feels right and it feels like a modern version of contra', 'This is one of those games you found back in the day on a 200 in 1 bootleg Famiclone cartridge, that only had an official released in Japan.\nIt was probably the best game on the cartridge, and by best, I mean the best of the shitty 200 games on that cursed cartridge.\nSo you play it over and over in the hopes that you can get the best out of the game, but after the 10th attempt, you say fuck it, and move on to the next bootleg cartridge, hoping to find Super Contra or Ninja Gaiden instead, anythi', 'Mostly Positive', 79.43, 3.40, 3.13);
INSERT INTO reviews VALUES (2117, 252030, 1639, 'A hidden gem for Metroidvania lovers.', 'Was having a good time, then came the part to back track as one normally does in a medtroidvania. And, it turns out the enemies scale to your level. Tell me, what the fuck is the point in even having levels, when everything is your level? You don''t get any stronger. A couple hours in, at every single turn, it takes 3-4 hits to kill something, more if a boss. Not continuing, 0/10, because no game should ever have dynamic scaling.', 'Very Positive', 82.00, 22.50, 10.93);
INSERT INTO reviews VALUES (2118, 252050, 117, 'tfrttfgrtrt', 'the worst rated game i own on steam, worse than bad rats\n\ndid not run \n\nunfortunately its been a decade since I purchased so can''t refund', 'Very Negative', 7.69, 0.33, 0.22);
INSERT INTO reviews VALUES (2119, 252070, 104, 'You can build your own spaceships and bring them into simulated space battles', 'Sounds like more fun than it is. Held back by the complexity of getting even a rudimentary ship working. If the idea of having a lot of control over tiny details in your ship is appealing you''ll probably like this.\n\nWhen I''ve played there are always less than 100 or so people on. It''s hard to play with people of similar skill level and the bots range from brain dead to impossible.', 'Mostly Positive', 77.88, 110.53, 2.48);
INSERT INTO reviews VALUES (2121, 252110, 1771, 'LOVE to play this game with my wife and mistress', 'Not fun with only two people where one of the people is autistic and bad at switching tasks. Gets pretty frustrating. The sounds of the beam weapon are really grating on the ears. Switching to beginner difficulty is helpful but this game still isn''t fun. This game does become tolerable and maybe even slightly fun if you have 3 or more people playing. \r\n\r\nI don''t recommend this game for a first date. Or for someone you''ve been dating especially if they suck at fast paced games. BOPL battle is mor', 'Very Positive', 93.79, 16.32, 8.50);
INSERT INTO reviews VALUES (2122, 252130, 285, 'A very good thinking game. A lot of fun. If you like thinking games, I can highly recommend this one.', 'can''t load any levels on GNU/Linux, tried with many versions of Proton\ncan''t exit fullscreen mode', 'Very Positive', 92.63, 8.17, 9.03);
INSERT INTO reviews VALUES (2124, 252190, 175, 'Beautifully nostalgic of the original Defender''s Quest. You can tell devs put hundred of hours into crafting this game. I recall fondly enjoying the first title about 10 years ago if not more, being as one of the top notch tower defense along the kinds of Bloons and I can tell this one will be much of that as well. \n\nEach map is carefully crafted to be challenging whilst remaining fun and not too brain-busting. The art style is unique and while the general HUD might feel archaic to some, i think', 'The first defenders quest is one of the greatest tower defense games of all time. It has an incredibly memorable cast, and a storyline that is simple but told well. A marriage of great game play, story, and art, that I put multiple hours into. \nIt''s sequel feels like a fan game that didn''t understand the genius of the first game.\nDefenders Quest 2 is practically it''s own thing, with very sparse tie in''s into the first game. It''s a downgrade in every aspect from the first game. The characters fee', 'Mixed', 57.14, 1.28, 14.37);
INSERT INTO reviews VALUES (2125, 252250, 664, 'If you like Sci fi Sandboxer games, this might be for you. \nThere are some design kinks that need to get worked out tho, and of course it still requires some content. But for all its worth i give it my approval.\nSimon, the developer really cares for what his players think about the game and you should totally join their forums as well, to give feedback and get yourself into the process of making this one awesome Sci Fi Game.\n\nOriginal Text:\nYeah no more early access games for me. \nI really love ', 'I''d love to recommend this game. I''ve had it for years, and despite the bugs, glitches, and most recently crashes (One play per install, if it glitches or crashes I have to uninstall, then reinstall) the concept is there. The potential is there.  Sadly, it seems to be a dead game, and if it isn''t dead, it should be placed in hospice.', 'Mixed', 40.36, 3.17, 264.62);
INSERT INTO reviews VALUES (2127, 252310, 264, 'Once again, Steam seems to have removed my original in-depth review of a game (my review was positive and had nothing wrong or inappropriate about it) so I''m tired of this re-writing stuff and  cannot be arsed again... So just "Yes, I recommend it, it''s pretty good. That''s all." :(', 'Not Recommended', 'Very Positive', 85.23, 4.20, 2.82);
INSERT INTO reviews VALUES (2128, 252330, 3390, 'the man said "its slendin time" and then slended all over the place\r\n\r\n10/10', 'At no point in this game does slender arrive. He was here before i was. Game dont make sense, Slender in game less than me, Only me arrive. New name Thee_dean.jpeg arrival', 'Very Positive', 86.96, 4.92, 2.57);
INSERT INTO reviews VALUES (2129, 252350, 1013, 'If it doesn''t launch, find the exe and set the compatibility to xp service pack 3.', 'Do not buy this game as it will not run on newer graphics cards.  Search for ''double dragon neon not launching'' and you will find a few Steam forum threads that explain that there is no solution.  Really crappy of the developer to not provide compatibility options for newer cards.  Don''t waste your money until they provide a fix.', 'Mostly Positive', 79.47, 1.47, 2.70);
INSERT INTO reviews VALUES (2130, 252370, 416, 'Rabbinical response: So you''re asking me if I think this is a good game? (if you know you know)', 'Wadget Eye games are amazing but I can''t recommend this. It''s over in less than an hour, somewhat unsatisfying and one-dimensional, and the puzzles are bad. Worth playing if you''ve played all the others and are interested in what their early work looked like.', 'Very Positive', 84.13, 2.67, 1.12);
INSERT INTO reviews VALUES (2131, 252390, 126, 'There a true gem in here but it needs some polish\n\nThe AI is often confused and seems intent to getting to rooms by making a hole in the roof. Forges and anvils just made my dwarfs skip over them over and over.\n\nBut you can tell a game is going to be really good because your willing to put up with the bugs. \n\nThe years working on this have not been wasted but it does need pushed over the finish line.', 'Game is abandoned and unfinished. Do not download.', 'Mixed', 54.76, 23.20, 3.65);
INSERT INTO reviews VALUES (2132, 252410, 2801, 'Steamworld Dig is a fun Steampunk Western Metrovanian with some mining thrown in for good measure. It''s not a combination I would have thought of, but it works really well. The core loop is to dig, fight, and then return to the surface to sell your loot and buy new equipment, allowing you to delve deeper into the mysterious mine. It got its hooks into me immediately and didn''t let go until I saw the credits roll. Also, its a perfect Steamdeck game if that is your jam.', 'The game is short, 6-7 hours if you are slow, but you are also sick of it before its over. Mostly because you have to waste so much time climbing back up to the surface and then going back down.  You cannot even refill water at the surface, the water respawns inside near one of the entrances but in small quantities so you have to go in and out a few times. It just pads out the game time which by its own achievements can be finished in less than 2 and a half hours.', 'Very Positive', 93.72, 4.67, 6.88);
INSERT INTO reviews VALUES (2134, 252450, 1399, 'Kind of a simpler "Master Of Orion". Plus RTS space battles. \n\nThe tutorial crashed on me, but everything else was perfect. Every setting on high, Ultra-widescreen supported. It just worked. Typical 4x game. It''s been in my library forever, just dug it out today to pass a few hours during the hurricane. \n\nRunning in Linux Mint. (NOTE: I don''t think this runs in Windows anymore... It''s time to move Linux folks. No more excuses. :-) )', 'Bought this game back when i first seen it in a YouTube video over a little space 4X with custom ships and races. Was fun until some time around the windows 10 push for updates that resulted in the game not running for me or several others from what the reviews show. Loved the game until the DLC disabled some of the content as well as threw some of the race bonus away without modifying them to fit the then reworked balance. I have not been able to play this game for about 3 years so far and i ha', 'Mixed', 54.97, 4.22, 11.03);
INSERT INTO reviews VALUES (2135, 252470, 2025, 'The game play is fun, the dialogue is funny, the story is... The game play is fun and the dialogue is funny.', 'I bought this game because i enjoyed the first one.\r\n\r\nThe first one was straight forward, there was a game design that made you progress no matter what.\r\n\r\nWith this one, i got stuck in unending cycle of battling other factions and there was nothing i could do about it, and in order to progress i had to gain territory, which i couldn''t do because i was at war with other factions, and i couldn''t declare peace because game mechanics.\r\n\r\nSo after 20 hours, i am stuck. What a disappointing game. I ', 'Mostly Positive', 77.93, 37.80, 23.55);
INSERT INTO reviews VALUES (2136, 252530, 2170, '-Buy game while in Promotion\n- I recommend to buy at least this dlcs: OmniNavigation (GPS) and Auxi expansion (Multi-tool to change FoV, Adjust the driver''s seat, such as height, set dynamic weather (sun, rain, fog, snow, etc.) more easily, etc.)\n-Download and apply 4GB Patch\n-Download MEP OMSI TOOLS (Another tool, to help you install new buses, maps and sync hof with all vehicles with ease)\n-Download and apply DXVK (DirectX-over-Vulkan), link for the guide: https://steamcommunity.com/sharedfile', 'Made it so difficult for new players who have no idea what to do, the tutorial is also bad at explaining', 'Very Positive', 81.15, 289.82, 0.80);
INSERT INTO reviews VALUES (2137, 252550, 341, 'Really enjoyed this game , played it multimple times manny years. I keep koming back to this game as a relaxing non stresful option. Definetly recomend it', 'I played part of this game in 2018, never got even close to finishing it. As I''ve been replaying old puzzle games, I decided to try again. After half an hour, I remembered why I didn''t like this one as I kept falling while trying to jump over gaps. If frustrating platformers disguised as puzzle games and rage quitting are your thing, then this is for you.', 'Very Positive', 84.16, 62.37, 15.38);
INSERT INTO reviews VALUES (2138, 252570, 227, 'While its pretty janky and has the sort of quality you would expect from a one man dev team that was made a decade ago with what was probably a small budget. It has a vibe and setting that you really don''t see that often, along with a gameplay loop that once you get a hang of is pretty solid, especially with how each of the different monsters function. overall I''m pretty happy with my purchase and would recommend it to anyone who finds it interesting.', 'Great mythological concept and atmosphere ruined by poor execution, unfair difficulty, bad performance and frustrating progression.', 'Mostly Positive', 71.37, 3.97, 2.50);
INSERT INTO reviews VALUES (2139, 252710, 179, 'this fucking RULES. get the original version though, this one''s an ios port and while it''s instantly compatible with modern systems, it makes the game feel cheap', 'while story is intriguing and grounded in semi historical events, voice acting is superb, dialogues are quite interesting and motion capture from 90s gives you strong feeling of interacting with real people, unfortunately i cant recommend this game.\nFor todays standards it has a clunky and frustrating navigation, 15fps is a recepie for diziness and 101 death achievemnt simply brute forces you to go explore all possible routes and choices in not appealing way.\n\ni have zero sentiments to this game', 'Mostly Positive', 77.65, 0.18, 10.02);
INSERT INTO reviews VALUES (2140, 252950, 224974, 'I don''t know why Steam keeps asking me to review a game they no longer sell, but I''m tired of seeing the notification so here''s my review. I guess their persistence worked.\r\n\r\nAvoid this game at all costs. You can no longer buy it on Steam, but it is now free to play from a different source. I would advise that you forget that you ever heard of this game and move on with your life. For the right kind of person, this game is video game meth. It will consume your soul and make you question your ow', 'I bought this many years ago from steam. Now I need an epic games account to even play local multiplayer. I do not want to make an epic games account. I want to play the game I bought. Absolute fraud and illegal in many countries. Shame on you.', 'Very Positive', 86.94, 3977.50, 343.18);
INSERT INTO reviews VALUES (2141, 253330, 822, 'Watched my husband play this a few times. Now that family sharing is on, I finally get to enjoy this!\n\nAmazing atmosphere, everything comes together for the perfect storm of creepy hellishness. Almost poo''d myself a few times!', 'Not particularly an engaging game. You''re just aimlessly moving from one corridor to the next, hoping to finish the level to be able to get some explanation from the cutscene. \n\nThe storyline is rather minimal, leaving a lot of room for theory crafting, but I wish there was more of that so I could relate to the main character. I found them quite annoying as they have a very low stamina bar, which is more apparent while being chased by creatures or sprinting your way trying to get this game done ', 'Mostly Positive', 72.51, 0.43, 2.95);
INSERT INTO reviews VALUES (2143, 253370, 106, 'EDIT: This is a more updated review than my previous one.\n\nI''ve used AGF for a while now and I have a lot more experience using the tools. I like the accessiblity of this program, as it is quick and easy to make complex landscapes and basic buildings and structures. They have also greatly increased the amount of different terrain textures and objects that you can place into your world. If you want to make anything fantasy medieval, there are plenty of objects and prebuilt buildings for you to us', 'This is a very fun and nice idea. BUT it has no grounds to it. I can''t make skills and things. Really, all you can do is make a cool map. It should be called Axis Map factory. I want a REFUND.', 'Mixed', 62.26, 27.75, 13.55);
INSERT INTO reviews VALUES (2145, 253410, 122, 'I loved this game when I first played it on mobile. And I still love it. This was my go to when I wasn''t playing Elder Scrolls: Oblivion back in the day. Definitely recommend Ravensword to anyone. Fun and enjoyable in my opinion and worth the few bucks. If you want to wait for discount price even better. I have found my own game config settings which I use on most games now since I started using them for skyrim to tweak graphic settings. Some tweaks to shadows, lighting and etc goes a long way. ', 'Uninspired grind grind grind grind.  After a few hours of almost nothing but killing goblins, boars and bears I''m giving up.  I have no clue what the point of the story is supposed to be, what the world is, why I should care, and my character is already level 10.  Maybe it gets better later on, but I couldn''t bring myself to kill the same dozen infinite-respawning bears again and again to find out.', 'Mixed', 61.48, 15.17, 6.03);
INSERT INTO reviews VALUES (2146, 253430, 5503, 'A lot of us who play this very old and rough game play it because we grew up with it. It holds a very special place in my heart as this is one of the last childhood games I have access too. If you know you know.', 'I love this game but with the dev pivoting AI usage in his latest version of the game i dont reccomend supporting his new project to remaster this game, it is a dream come true for me but i do not wish to support any dev''s using ai, and i predict that the next game will likely be ai unreal 5 slop', 'Very Positive', 85.10, 62.12, 7.83);
INSERT INTO reviews VALUES (2147, 253510, 366, 'Super fun game. I''ve loved the tabletop for many years. I didn''t know this videogame existed until recently, I missed the boat on it being popular and no one plays anymore. But it''s still fun to see the tabletop game animated and the singleplayer is fun.', 'To anyone who hasn''t yet wasted their money on this joke, please avoid. Privateer Press are on life support and do not care about this shovelware.\n\nSteam should delist this garbage, it''s an insult.', 'Mixed', 49.73, 29.57, 45.37);
INSERT INTO reviews VALUES (2149, 253710, 234, 'this                    is                           AIDS', 'Want to start the game? Yes, you can\nWant to shoot some animals? Pay us and you can\nWant a new weapon? Pay us and you will have one\nWant to do anything? Pay us a lot and you can do everything', 'Mixed', 41.88, 0.15, 1.62);
INSERT INTO reviews VALUES (2150, 253770, 381, '.', 'Cancer simulator', 'Mostly Negative', 33.33, 18.83, 0.33);
INSERT INTO reviews VALUES (2152, 254820, 104, 'A classic rts about controlling the ground', 'Game does not work in Windows 7 nor any compaitablity modes. Do not buy!', 'Very Positive', 86.54, 11.30, 0.08);
INSERT INTO reviews VALUES (2155, 261550, 90109, 'Ultimately I enjoy playing the game, but I have huge reservations in recommending it. \n\nFundamentally the combat is unique, and the experience of starting out is fun. However, the mid to late game is a terrible grind due to baffling decisions such as having enemy lords escape _within days_, and enemy armies teleporting to crisis spots . Some great mods exist, but this should not in any way be required. \n\nI think the overall issue here is that the devs have created branched features and have no c', 'Game is dead, no proper Updates since years. Could have been an amazing game, but everything is just barely in the state so it works but nothing more. No love, nothing special. Just an awesome foundation.\n\nQuite sad to be honest.', 'Very Positive', 87.19, 1388.87, 263.88);
INSERT INTO reviews VALUES (2156, 261640, 18260, 'It was five years ago when i started this game and i gave up becoz i didnt like it. but i decided to give it another chance and after sevrl hours i noticed that i want to play more and now i got all achvmnts', 'This isn''t a live service game. If I purchased a game with a certain ToS, then they shouldn''t be able to update it (outside of legitimate reasons like there being a flaw, something being unclear, etc.). It basically boils down to: "I purchased a product, ToS says I can play. Logged on to play again, many years after the game launched, now the ToS says I need to install spyware and give them as much info as the government to keep playing, for a game that didn''t need this for a decade in order to ', 'Mostly Positive', 75.90, 102.42, 1.50);
INSERT INTO reviews VALUES (2157, 262060, 53468, 'Very hard game to review. It''s pretty much the epitome of an abusive relationship.\nIt''s a game that you''d beg your best friend to play but wouldn''t wish it on your worst enemy.\nIt''s a game that you''ll love to hate and resent yourself for loving it.\nIt''s a game where skill is mocked and luck is a bipolar parent.\nAnd it''s addictive as crack.\nYou''ve been warned.', 'Well polished game. However, the core game design is all about stressing out the player. It would have been ok if you are young and not much going on in your life. But I just can''t manage to play this stressful game after a full day of work. Every time I try this game, I''m too stressed out about unfair game mechanic and hopeless situations I end up on. This game looks so appealing but I fucking hate this game.', 'Very Positive', 90.84, 109.15, 13.00);
INSERT INTO reviews VALUES (2158, 265810, 340, 'The original sandbox game. It''s a shame it doesn''t get updated anymore. Game is fun, but making things is difficult.', 'fix the mobile version.', 'Mixed', 51.18, 1.50, 0.72);
INSERT INTO reviews VALUES (2159, 267610, 160, 'This game is an absolute mastery and a strong contender for game of the year.\n\nFrom the beautiful landscapes, to the immersive sound-design that makes you almost smell the fumes as you use your ®Stihl chainsaw to effectively harvest lumber.\n\nAlthough the first-person aspects of the games are great and feature the most fluid controls i''ve ever witnessed, the game truly shines in management mode. The game accurately represents the daily dealings of a small lumberyard, as a 17 year veteran of that ', 'At least I got this one is RUNNING, but figuring out how to do anything is really PATHETIC... Why Bother?\n\nNOT RECOMMENDED!!! I requested a refund\n\n Recommendations \n YouTube \n TikTok ', 'Mostly Negative', 22.50, 0.12, 0.15);
INSERT INTO reviews VALUES (2160, 268500, 41940, 'Im an old man that lost the ability to sit down and play games without loosing interest. This one though, Ive really become fond of. Even though its exciting in its way you can lean back and control almost all of it with only the mouse and when the family comes by to disturb you nothing will happen while you attend to them.\r\n\r\nFive out of five old man farts', 'Do not buy games that make you pay them so that they can steal from you.\n\n"By installing and using the Software, you consent to the information collection and usage terms set forth in this section and Licensor''s Privacy Policy, including (where applicable) (i) the transfer of any personal information and other information to Licensor, its affiliates, vendors, and business partners, and to certain other third parties"', 'Very Positive', 85.62, 6.88, 135.17);
INSERT INTO reviews VALUES (2161, 268650, 9063, 'didn''t know i needed a fucking degree in engineering and naval architecture just to build a tiny sail boat. only to be destroyed by literal sci fi spaceships', 'I really truly do love FTD but as of the camera update I cannot recommend it. Undoing a system that everyone was familiar with and comfortable with for years is nonsensical, the old controls were absolutely fine and did not need to be completely overhauled in favour of a complex and confusing mess. To emphasise the point previously what would take a single button press now takes three and utilises half the keyboard to do so. This change was not needed and only stands to make learning this game a', 'Very Positive', 89.68, 16.83, 1627.77);
INSERT INTO reviews VALUES (2162, 269210, 11637, 'This game is nice and fun, and I don''t really mind some classes being bought as DLC, but the slot limit is really nefarious for a business model. They should at least give players 3 slots.', 'Once you entered a store and seen a game.\nNowdays you enter a game and see a store.', 'Mixed', 61.39, 129.88, 9.05);
INSERT INTO reviews VALUES (2165, 270110, 532, 'Played this game as a kid and got the chance to replay it, simple but great!!!', 'Don''t buy this game, it''s a total mess\n\nThis minecraft ripoff is 12 years in development, 12 years cash grabbing on multiple platforms while pretending to be something. \n\nThey are selling you this ancient mobile game with no patching whatsoever, not bringing anything new to the table like if it was a new game. They even have some leftovers from the ads they had on mobile!\n\nPeople code minecraft clones in 12 days as their school projects yet these guys haven''t even yet rewritten their crap fully ', 'Mostly Positive', 79.32, 54.23, 95.45);
INSERT INTO reviews VALUES (2168, 270880, 82871, 'Was going 90 on a 45. saw a fellow semi-truck in the distance (he betrayed me later). I continued at my speed expecting that  the fellow semi-truck would also speed up/move out of the way. however this jerk hit his breaks at the last minute, I swerved out of the way. unfortunately going 90 on a 45 towards oncoming traffic was a perfectly fine idea. that is when I noticed a POLIS officar. having no where to swerve off to again, all I could do was state "this is a aye caramba moment" I then crashe', 'They totally messed up the controls. I play with a controller and I cannot get the same layout I had before the update back. Uninstalling. Sucks cause this was my chill out game.', 'Overwhelmingly Positive', 97.32, 3.48, 77.77);
INSERT INTO reviews VALUES (2169, 271260, 1607, 'I am so mad that the fake Star Control game is actually decent.  It can''t touch Star Control 2 and the story makes no sense in context with the Ur-Quan stuff but as a stand-alone game, I am enjoying traveling a galaxy that I don''t have memorized.', 'I have been yearning for this game for so long, being a fan of the SC2 and even participating in fan-made off-shoot projects (none came to fruition, unfortunately), but, alas, it is barely a shadow.  Boring, repetitive, uninspired.  I can enjoy occasional jokes and references (including those to the original, however week and irrelevant they may be), but there is no core, no drive, no purpose.\n\nAlso, original (SC1 and SC2) battles relied heavily on 16-position orientation of the vessels - and no', 'Mostly Positive', 76.98, 30.18, 23.80);
INSERT INTO reviews VALUES (2172, 274500, 3697, 'The game so damn good I bought it the next day after pirating it', 'Mediocre at best. Absolutely not worth full price. Glad I got this on sale.\n\nAll the freelance missions are identical. You always have to kill three captains, take out some orbital guns, take out some depots, take out the garrison, and take out some structures, and comms towers. Rinse and repeat. This was the main point that I wanted when I bought this game which was free play mode with some light mech customization and fun gameplay but it gets very boring and repetitive extremely quickly. The o', 'Overwhelmingly Positive', 95.48, 47.87, 5.20);
INSERT INTO reviews VALUES (2173, 274900, 3091, 'someone tell k dot and drake to hop on this game for a 1v1', 'https://www.youtube.com/watch?v=lhvzNa-xUYo\n\nway to drop the ball.', 'Very Positive', 90.33, 2.65, 3.05);
INSERT INTO reviews VALUES (2174, 275100, 1859, 'Even after so many years, I still can''t forget how I lost my only kitten on the very last day!\n\nI was heartbroken! I called out for him and searched everywhere but couldn''t find him anywhere. It was a very emotional moment when I finally realised that he was lost all alone forever in those swamps... And the fact that the other three kittens stayed with me until they were old enough to leave didn''t make me feel any better. I kept thinking only of him and how I hadn''t properly kept an eye on him. ', 'I liked the first game. It was short and overpriced, but it had a nice story with unique levels, each of which had it’s own distinctive threat you were forced to deal with, and limited resources made it so that your cubs were actually at risk of starving to death.\n\nI really don’t see the appeal of this one, and after thoroughly reading through the notes I took during my playthrough, I actually kind of despise it. The story here is only slightly longer than the original, yet the game has a 66% pr', 'Very Positive', 87.95, 1.67, 18.83);
INSERT INTO reviews VALUES (2175, 277680, 265, 'An amazing game that keeps you coming back.', 'Short puzzle game without story or anything special going for it really.\n\nI liked the simplistic art style. The soundtrack was lovely at times, but annoying at others. Specially the characters repeating “I love you” and “I hate you” got old quickly.\n\nMost levels were intuitive and easy. Sometimes my brain just went “nope” and I had to stare at the level for a while to find the solution obvious. Some levels break when you restart them (aka. the character is inside another object). Usually you can', 'Very Positive', 86.79, 10.60, 9.77);
INSERT INTO reviews VALUES (2179, 280680, 2409, 'good gameplay but gets tough like halfway through the game, would NOT recommend comp too many sweats', 'I suck at drawing', 'Overwhelmingly Positive', 96.39, 10.85, 0.68);
INSERT INTO reviews VALUES (2180, 281280, 223, 'This is my friend Mark''s favorite game!', 'wont lunch no mether how i try to troubleshoot\n', 'Mostly Positive', 79.82, 9.57, 0.63);
INSERT INTO reviews VALUES (2181, 281920, 659, 'I got the game on sale and didn''t play it until I beat other games I had in my Steam collection. I did have fun playing the game and did beat it so here''s my review of this game. The game is pretty much a guy who gets into a zombie apocalypse and has to fight zombies, monsters, and robots to reach the end to find the source of the zombie apocalypse. The game gets you guns like the pistol, shotgun, rifle, grenade launcher, rocket launcher, laser rifle, and flamethrower from what I remember. You f', 'Controls don''t work, neither gamedpad nor m/kb, and the game''s thus unplayable.', 'Very Positive', 86.49, 3.07, 1.18);
INSERT INTO reviews VALUES (2182, 281990, 70649, 'buy it. spend 500 hours learning it. get bored for a while, come back. remember nothing. spend 500 more hours relearning it. 12/10', '4.0 update was meant to improve performance and the final result is that the game is about 25% slower now than before. Thanks.\r\n', 'Very Positive', 87.70, 1196.60, 1414.90);
INSERT INTO reviews VALUES (2183, 282400, 961, 'If only there was a modern version of this game but enhanced.', 'I loved this game, but when you play as a smaller country and buy arms from a larger country, you do not get the correct stats as even though it may be an advanced unit, your own skills get stuck to it rather than the stats you bought it for. Makes buying arms from the US or Russia a waste. Might as well build all your own.', 'Mostly Positive', 78.77, 241.23, 16.72);
INSERT INTO reviews VALUES (2186, 284050, 563, 'This is toxic yaoi the likes of which the world has never seen.....', '2/5 Wonderful, but doesnt work well on steam, alot of crashes.', 'Very Positive', 93.25, 10.82, 5.22);
INSERT INTO reviews VALUES (2187, 284160, 165108, ' Car is fast \n Car is realistic \n Car is destructible \n Car go boom ', 'Stop looking at the negative reviews and buy the goddam game!', 'Overwhelmingly Positive', 97.66, 16.25, 25.48);
INSERT INTO reviews VALUES (2188, 285900, 22920, 'I don’t understand what’s stopping the developers from making a workshop on Steam, if it’s so difficult for them to make at least one map a year, then let the fans do it.', 'Good game, but we need more map or game mode update. A steam workshop would be nice tho.', 'Very Positive', 84.62, 4.62, 12.37);
INSERT INTO reviews VALUES (2189, 285920, 12561, 'Not a game that requires much thought; mostly turns into which ''tech'' has the most guns but still a very chill and fun experience if you enjoy building.', 'Dev''s got in bed with EPIC Games and refused to answer a question despite having a week to do so about Epic Online Services, Epic games activity trackers, and the posibility of signing the unfair EPIC Games ToS document which removed your right to sue EPIC Games for any reason including personal injury & loss of life...\r\n\r\nas it stands I can''t in good faith support a company that''s as bad as EPIC Games and after my 192 hours in TerraTech I''ve uninstalled the game and am removing all of this dev ', 'Very Positive', 92.71, 34.37, 192.80);
INSERT INTO reviews VALUES (2190, 286160, 28764, 'Great Tabletop Sim for just sitting there, unused, reminding me everyday that i have no friends.', 'You''re one of those people that look for the review from the player with the most hours to know if the game is good or bad. I know it. I could smell your armpits from around the corner.\nI ran this game on the background in order to get your attention.\n\nThis game does not even run for me. In the 935 hours i have played at the time of this review, i am still waiting for the main menu to load. I would say that I like or dislike the game but that seems impossible as all this time i have been unable ', 'Overwhelmingly Positive', 96.28, 0.55, 2547.70);
INSERT INTO reviews VALUES (2191, 288060, 458, 'For a ten year old game I thought this was pretty good and I chose to play this for some spooky vibes during Halloween. The art is excellent. It''s not a very long game and the puzzles aren''t too difficult. I enjoyed piecing together the story via scrolls gathered throughout the game, the main character''s diary, and talking to ghosts through Elena''s spirit form. \n\nThe story centers around a huge mansion that is owned by a man named Wortham Willows who becomes the mayor of the town. Wortham is the', 'DO NOT BUY THIS GAME, NOT WORTH IT. All the images are just clickbait because the mechanics of these thing is just text or unlocking more of the maze. I do not encourage this types of game that make you go very slowly around and it''s based on reading (also it doesn''t tell you what to do or the objective) and i think if you have the game so based on reading, make it a book, heck i would prefer reading a book than buying this game because of the extremely slow pace. So i suggest just looking at th', 'Very Positive', 81.44, 6.47, 0.18);
INSERT INTO reviews VALUES (2199, 291480, 404, 'Well they deleted my account...so i deleted the game...', 'Just lost my account because of their great migration system. Good job my.com now I have to start all over again with the name of xXPu$$ySl@y3rXx.', 'Mixed', 50.74, 57.35, 38.03);
INSERT INTO reviews VALUES (2200, 291550, 1572, 'abo ibrahim', 'every second is this game is filled with anoverwhelming sense of despare and its cripples your mental health', 'Very Positive', 83.08, 1101.20, 1569.15);
INSERT INTO reviews VALUES (2201, 291650, 10144, 'Masterpiece unfortunately hidden behind a slow and uninteresting start. Top notch world, characters, and story, with a mostly good real time with pause combat system behind it. This feels like the real spiritual successor to the Baldur''s Gate games, unlike the actual BG3 which is more akin to a Dragon Age Origins. I played this directly after BG1 and was actually shocked at how faithful Pillars feels to those games. I''m gonna give this five big booms on the boom meter. BOOM! BOOM! BOOM! BOOM! BO', 'Extreme punishment for wandering off the beaten path.  This game feels like playing on a ladder with a bunch of e-sport min/maxers where every new area is a new chance to wipe your team if heaven forbid you didn''t pick the optimum class and select at every level the optimum spells, and pause combat at the optimum times to deliver the perfectly matched spells or feats.  Where''s the story? Can''t tell through all the blood spatters that used to be my party.', 'Very Positive', 86.90, 44.52, 120.87);
INSERT INTO reviews VALUES (2202, 292030, 222421, 'Imagine you''re working in a 9-5 corporate job, you''re done with your work, you come back home, log onto Steam, see your games list for 5 seconds, buy a game on sale that you''re never going to play and then switch off your PC and go to a bar. While having a drink, you think of the good times when games used to be fun and authentic. But then you tell yourself, the problem isn''t the games, its you. "Its not that games aren''t fun anymore, you have gotten older".\r\n\r\nAnd then I play Witcher 3. And sud', 'I seriously have no idea how people like this shit\nThis is some of the worst combat I''ve ever seen in my life\nI can''t complete one mission without the dumb AI, technical glitches or the horrendous camera ruining the experience.\nI tried to push through because the world is beautiful and the story is somewhat intriguing but I can''t play this dogshit anymore', 'Overwhelmingly Positive', 96.82, 134.68, 7.63);
INSERT INTO reviews VALUES (2203, 292480, 107, 'good game with good short story ignore the people who are talking about the controller its easy to fix the issue', 'This may look like a fast paced game but it''s really shallow and repetitive. Most of the game can be beaten by using the basic attack sequence that always launch your enemy>jump>air attack sequence>ranged attack, and out of that there isn''t anything more complex that you can pull in this game, I didn''t find any way to break out of the basic combo(and neither did the CPU on me), you can''t link different attacks and there isn''t any button combinations other than attack while dashing and hold butto', 'Mostly Positive', 73.83, 23.32, 3.93);
INSERT INTO reviews VALUES (2204, 293320, 214, 'Coma: Mortuary\n\nHas a total of 9 trading cards.', 'It''s a slow-paced horror game with generic dialogue, awkward FMVs, misplaced music, and puzzling, uninspired jump scares.', 'Mixed', 42.06, 1.42, 4.73);
INSERT INTO reviews VALUES (2205, 293760, 9894, 'I bought this game almost a decade ago.  The developers promised superchargers as "coming soon".  \n\nThey came out today.  \n\nThe game is significantly better than when I bought it, with major upgrades across the board. The devs have a strong roadmap and a consistent track record.  It''s well worth the asking price.', 'If you want this game to play the campaign it''s not worth it. The time goes by too quick for it to be really enjoyable, and it''s buggy as heck managing your factories. I have had a playthrough fail because of bugs rather than any decisions I made. The campaign needs a lot of work.', 'Very Positive', 93.24, 177.15, 11.23);
INSERT INTO reviews VALUES (2206, 294020, 167, 'Massively underrated. 87/100', 'This game has too much randomness. They even wrote it in the guide that, while some cities specialize in a certain trade good (they produce it, so it is cheaper), OTHER merchants (you don''t see them) can buy the goods before you. Effectively, this means that no matter where you go, prices are completely random. Just some places sometimes have them significantly cheaper. But they can even have the price higher for their own product because "other merchants bought too much of it".\r\n\r\nRandom events', 'Mixed', 61.08, 11.53, 36.52);
INSERT INTO reviews VALUES (2207, 294100, 105337, 'This game not only teaches you management skills, it also teaches you people skills. Using the statistical analysis in the game as it pertains to peoples moods (irl) will help you understand and appreciate the specific nature of those around you, with their different proclivities and traits, and how they fit into a functional society. For instance, when I play this game, my mother gets very angry. But I now understand this is because I am a night owl and interrupted sleep gives her a hefty debuf', 'Rimworld = great game.\r\n\r\nMy problem: 35$ for base game is a really, REALLY good deal, but it doesn''t make sense for all the dlc to add up to $125 with the base game price, even just adding content that should''ve been a part of the base game.', 'Overwhelmingly Positive', 98.04, 779.67, 1028.13);
INSERT INTO reviews VALUES (2209, 296710, 1224, 'Decent horror game, wait for a sale to get it at 3 or 4 euros.', 'After spending about an hour avoiding a monster, cameras, and failing to get the sub escape in a run, I managed to get all the elements for the liferaft escape, after escaping from the monster for long enough to pump the raft completely, the problems started. First of all, it took me a good while to figure out how to get it hooked, and once I did that and moved it with the crane, it bugged out, I accidentally jumped on it while it was still on the ship, at the lower deck and I almost couldn''t ge', 'Very Positive', 89.79, 8.32, 8.13);
INSERT INTO reviews VALUES (2213, 299460, 720, '⠀', 'Wood have had a better time eating bark. Ok its not that bad but even with this game having 0 budget it shouldn''t have cost money. The camera getting stuck constantly and checkpoints basically being useless, soured my mood towards it.\n\n3.5/10\n\nThis is clearly made by one person and they have potential to do much better but I just can''t genuinely recommend a game that is not very fun and has to many blatant flaws. \n\nI did buy the sequel and just by the trailer alone I can tell they''ve improved dr', 'Mixed', 67.78, 13.93, 1.97);
INSERT INTO reviews VALUES (2215, 301280, 787, 'Initially within my first thirty minutes of play I was going to leave a negative review. If it''s an FPS where are the guns? Why do enemies take so many thrown objects to kill? Why can''t I do stealth takedowns? Then I found something, to some inconspicuous but to me a goofy scheme, the peel of a banana, I threw it at a guard''s feet, the man tripped and got stunned, executed shortly after. What if I used a bar of soap instead? The same result. Deodorant and a lighter? IED. Hack grenade and an enem', 'The game is supposedly using an OpenSource reimplementation of the IdTech 4 engine and it has the same FPS lock of 63/62 as Quake 4 from 2005.\n\nIDK if Quake4Tweaker or whatever that tool was works with this game, but I do know that I shouldn''t have to use such crap in 2025.\n\n\nP.S. I don''t want to play the game and use up my 2 hours of time before they patch and fix it. Because if they won''t fix it, I don''t want it. There really is no technical reason why any 3D game should have a locked framerat', 'Overwhelmingly Positive', 95.81, 8.53, 0.18);
INSERT INTO reviews VALUES (2216, 301300, 301, '10 years ago my dad brought a physical copy of this game home and we used to play through the whole game almost every weekend. He passed away earlier this year due to his cancer and completing this game and getting the chance to play it one more time reminded me of all the good times and memories I had with my dad and how dun this game was. This one''s for you dad', 'Not recommended.', 'Overwhelmingly Positive', 97.01, 16.90, 6.40);
INSERT INTO reviews VALUES (2217, 301320, 1005, 'This is software, not a game. It doesn''t hold your hand at all during start up, so read the manual or find some YouTube tutorials (or cheat like I did and learn off a friend with 1000+ hours alredy under his belt) otherwise you''ll get lost pretty fast. Once you get the hang of it, it''s pretty fun. Recreate your favourite coaster, or make a Eurofighter with Maurer spinner cars, take a browse of the Steam Workshop and you''ll quickly realise how endless the possibilities are. You don''t even have to', 'This is NOT a bad Simulator! In fact it simulates a roller coaster very well!\nBUT i did purchase it for VR only and even if my PC can handle all normal VR games without any issues - the VR Mode in NoLimits 2 is either completely broken (Engine overloaded) or it is super demanding on both CPU and GPU.\nI did even try to use FOV Stancil (limited rendered space) but most coasters get fps drops and bigger maps are unplayable.\n\nThe Demo did not give me the impression that it was so bad - in fact i had', 'Overwhelmingly Positive', 96.62, 52.55, 1.30);
INSERT INTO reviews VALUES (2218, 301970, 603, 'I love the mechanic of this game. Finally, years training my screen cheating ability against my brother as a youth have not been wasted. If you got some friends to come along with you and play this one. I absolutely recommend it.', 'my friend recommended this game, we played a match and i found it incredibly frustrating. probably a skill issue.\n\nwould be cool if there was a way to still see other players from my screen.', 'Very Positive', 91.54, 2.13, 0.20);
INSERT INTO reviews VALUES (2219, 301980, 128, 'Good game in terms of childhood favourites BUT the trailer is false advertising.\n\nThe trailer shows the PS3/Xbox 360 port which honestly back in 2007 we should have all gotten but nope we got the PS2 version ported over instead which looks horrible in comparison and it just shows utter laziness on the devs part if we did not even get a half decent looking port.\n\nI grew up on this which is the only reason I''m giving a positive rating.\n\nOtherwise if you aren''t buying this purely for nostalgia then', 'This Steam version is complete shit.\nCut and bug.\nRegardless of the fact that it''s an old classic from when Disney wasn''t such shit, it just smelled.\nThis game is not even worth half the price.\nFuck you Disney.', 'Mixed', 66.41, 2.18, 6.10);
INSERT INTO reviews VALUES (2220, 303310, 1662, 'Greatest of all time. Zenith of the medium. Hallmark of media. Gold standard of storytelling. Apogee of creativity. Vertex of invention. Crest of ingenuity. Acme of imagination. Pinnacle of innovation. Epic of epics. Legend among legends. Peak fiction.\n\nIf you have eyes that can read the text, ears that can hear the music and a few dollars to spare, you have to try out this visual novel. An emotional tale that uses different perspectives to show the full depth of the story perfectly. Truly an ex', 'ive been looking forward to playing this game because of the gorgeous art and the wonderful ost but the incestuous relationships were a deal breaker. if you like incest then this game is perfect for you', 'Very Positive', 94.65, 70.27, 1.00);
INSERT INTO reviews VALUES (2221, 303390, 1403, 'My childhood game', 'There''s clearly no signs of intelligent life in this crapware.', 'Mixed', 50.39, 84.37, 4.08);
INSERT INTO reviews VALUES (2223, 304390, 51513, 'Pls don''t let this game die. It is too special. There is no other game like this. Ppl are complaining about broken matchmaking but that''s because there''s less than 10k players left and a daily max of 5k players on steam (avg 2800 at one time). It''s insane that they''re still updating this game but I''m glad they are. I suck at comp games but I still love it', 'The actual gameplay, mechanics, fashion, and cinema of the game are all solid 10/10s, and the best I''ve seen of any fighting game. Its so complicated (but in a good way), and has so much depth and mindgames to it, which makes it extremely fun. So why would I give it a negative review?\r\n\r\nBecause of the god damn community. You guys are literally the worst community I''ve ever had the disfortune of meeting, and I''m ashamed to be a part of it. Every game I play seems to have either 4 stacks, toxic c', 'Mostly Positive', 70.20, 353.37, 645.40);
INSERT INTO reviews VALUES (2224, 305620, 37119, 'Excellent game.\n\nDo not listen to the haters whining about no episode 5. The community said they wanted DLC for sandbox mode prioritized over story content, so the developers listened and provided. Episode 5 is coming out in late 2024 as they stated many times already.', 'It''s been YEARS, and the story still isn''t finished. Releasing DLC for an incomplete game and coming out of Early Access unfinished. Meanwhile, they already have a page for The Long Dark 2. I will never support this company again.', 'Very Positive', 88.99, 496.45, 64.15);
INSERT INTO reviews VALUES (2227, 306760, 2312, 'I''m 68 and the only games I was ever interested in were the Cyan games. I found MYST a few years after it''s release, but all the others I literally had to get when they were actually first released.  I have to admit I had to have hint help on all of them, being old and no computer experience previously. I have to give kudos to the gamers that actually beat these games on their own, my guess they started as young children. \r\n\r\n On my first attempt at Obduction I was pretty lost, as basically a no', 'I have very mixed feeling with this game, cause it does a lot well. The puzzles are great, the environments are interesting, and it really captures the essence of Myst and Riven. But while I love the idea of the open world, exploration based games - I don''t feel like Obduction implemented it well. Exploring, solving puzzles, and discovering the mechanics of the game requires A TON of backtracking and this game has very slow and unsatisfying movement. This made the game and all its puzzles feel l', 'Mostly Positive', 77.94, 100.50, 7.57);
INSERT INTO reviews VALUES (2229, 307960, 4974, 'Most of the bad reviews here are honestly just weird. Weird ass complaints. War Thunder is not a more detailed simulation, that is a crazy thing to say. The only game with full fidelity cockpits is DCS. Il-2 Cliffs of Dover has higher fidelity cockpits but it is old and has a whole host of other problems. This is the best WW2 sim on the market, bar none. This has the best VR support of any sim on the market, bar none. It also runs way better than DCS or war thunder in VR. Its the only sim I play', 'Could have been incredible, but buying the game gives you <1% of the content. I get that it is a 10 year old game, but they have taken the nickel and dime-ing to a whole new level. All of the menus are just full of 50 locked options and one unlocked one. To be real, they should have made it a free to play game a long long time ago if they wanted to focus on paid content like they have.', 'Mostly Positive', 79.33, 676.42, 0.50);
INSERT INTO reviews VALUES (2231, 308040, 244, 'Back to Bed\n\nHas a total of 6 trading cards.', 'The controls are clear and comprehensive and the game runs smoothly. I loved the theme and the art design is just beautiful, but the puzzles become very repetitive and more about perfect timing rather than solving the level. After a while, it''s uninteresting and the satisfaction of solving levels quickly wanes.', 'Mostly Positive', 75.00, 0.63, 1.03);
INSERT INTO reviews VALUES (2232, 308060, 313, 'A brave escape from the cold grip of communism.\nFreedom and peace are never simply granted.\nThe road to freedom is, indeed, always a hard one.\n\n\n프리덤 이즈 낫 프리.', 'Some frankly bad game filled with black fiction on communism. It would be better if the developers spent more time on gameplay. The authors should be sent back to school to learn history lessons.', 'Mostly Positive', 77.96, 1.78, 1.37);
INSERT INTO reviews VALUES (2235, 311120, 196, 'Russian Jank 2: Unfair edition', 'Olyan élmény volt mintha harapófogóval tépnék le a körmődet és kezelés helyett inkább rászarnak még a sebre, szívjál még. \r\n\r\nA játék nehéz, bugos és szar, de FreddyD-ért végig kellett vinnem.', 'Mixed', 46.43, 2.03, 7.18);
INSERT INTO reviews VALUES (2236, 311210, 107065, 'Dont deny it, its 2024 (or later) and you''re only buying this for zombies.\r\n\r\n\r\nIt''s worth the cost. do it.', 'To anyone who is even looking at this steam page, please for the love of god do not buy this game unless you know what you are doing. This game, along with all the other pre-MW2019 CoDs on Steam, are riddled with security exploits allowing people to perform RCE and install RATs on your PC, and grab your IP address.\n\nIf you want to get this game for MP, just forget about it. If you want to get it for Zombies, please install the T7 community patch, play offline, and you *should* be fine.\n\nEver sin', 'Very Positive', 89.88, 108.40, 166.07);
INSERT INTO reviews VALUES (2237, 311310, 5316, 'I had a great operation going in the War server and then it was gone. All my hard work the past year went up in flames when they removed the server. I had dozens of ships and crafting facilities. I had permits for new ships and other valuables. I went to the peaceful side after they removed it and now have to start all over again. It was highway robbery what this new company did to many of the loyal following. All I want is what I have accumulated in the War server back. I''m not asking for anyth', 'As a veteran player and someone who truly loved the game...I have no desire to play the game in its current state. Adding ammo/powder to the game has destroyed the fun and I will NOT waste hours of my time (that is already demanded by the game), just to save up enough money to fire the guns maybe 50 times before you are out of powder. Naval Action... what ACTION LOL.', 'Mixed', 52.93, 1788.05, 1697.40);
INSERT INTO reviews VALUES (2238, 311560, 6458, 'Now that i have completed Assassin''s Creed Rogue 100% on steam i think it''s time i make this review. and in my opinion i think Shay''s story is right up there with Ezio (But not better then ezio''s story since ezio IS assassin''s creed, he made the franchise and ubisoft will never write a character as good as him again) but this game is really underrated. and it''s sad that it''s the least talked about game in the series. which makes no sense to me for rogue is incredibly unique on how it FLIPS the p', 'It will force you to launch through ubisoft launcher.  The launcher will add the game to your account then wont ever let you launch it again.  Voiding your steam game and basically robbing you of your money.  Don''t buy it.  Boycot this godawful crap company if you know whats good for you.', 'Very Positive', 85.61, 59.15, 69.42);
INSERT INTO reviews VALUES (2240, 312660, 14738, 'any game where you can shoot a nazis testicles off deserves the noball peace prize 10/10', 'This game is a very weak link compared to games 3 and 5 of the series. It feels as though the enemy hitregister is inconsistent, the walking and crouch-walking pace are incredibly slow, and the detection range on rifles is unclear and ridiculously far, even when using the silenced carbine. \n\nIf you plan on buying this installment to the franchise, do yourself a favor and buy Sniper Elite 5 instead. The next game has improved everything in every way, and the new features and game modes FAR outmat', 'Very Positive', 90.93, 9.92, 19.98);
INSERT INTO reviews VALUES (2242, 314030, 285, 'Bridget is in this one too.', 'I mean it’s alright but I think I wasted my money on this because I already have accent core plus on my psp also with a press of the button the game just closes and the controller I connected would just stop working sometimes and I blame the game for that because the controller works fine on any other game', 'Very Positive', 86.67, 45.03, 0.27);
INSERT INTO reviews VALUES (2246, 318600, 1255, 'I''m very sad. I''ve been playing this game since its release on PlayStation because of a Saudi YouTuber. I was truly captivated by the art style, music, and the very interesting concept of the game. The flood reminds me of the Moomins anime. The game is full of potential, and my sadness stems from the fact that the developers abandoned it. I wish they would make some fixes and improvements. The developers have really beautiful and interesting ideas, but I see them abandoning their games and not g', 'Check your network traffic. This game is making calls to Google analytics. They sold you out.', 'Mostly Positive', 78.41, 47.30, 14.87);
INSERT INTO reviews VALUES (2249, 321060, 158, 'Basically a genderbending romp through what early 2000s deviantart was like.', 'I highly believe in giving things a fair chance before I throw my chips into a bowl, so, after having actually played it, I can say that this game is rather callous to Transgendered issues, at least over the course of the first two routes (if there is places it does this better, please let me know)\n\nYou can generally tell what is going to happen long before it does. Since each character tells you precisely what they include (How many endings, what types of strangeness they will encounter) any re', 'Very Positive', 84.18, 2.83, 17.37);
INSERT INTO reviews VALUES (2254, 321270, 652, 'Great game. \nGreat aesthetics, there is an enjoyable grind, it is fun to co-op with others. \nDefinitely worth buying. \nWill review again at 100 hours played.', 'The RNG leveling system is zero fun. I''ve opened about 8 Demon Chests and rolled for random trinkets about 25 times and have not obtained a single ring. I''m stuck at level 77 and can''t solo the level 30-50 zone. All of my Demon Chests have been obtained from getting carried which doesn''t feel good. I want to play and enjoy the game but the progression is not good.\n\nUpdate:\nI am enjoying the game. I just wish I could play solo AND make meaningful progress. I made it to level 180 by just getting c', 'Very Positive', 81.13, 26.42, 133.57);
INSERT INTO reviews VALUES (2255, 321290, 490, 'hot man\n\n', 'Personally, I love this game, but it might be because of nostalgia. Its not really worth this much money. The story is fun, but the romance is non existent, there''s just no chemistry between Heejung and her love interests. (I still need to do the wizards route so we will see after that). The game mechanics aren''t anything amazing, and the game shows its age. I love the interactions, and the fact that the mc herself has mental problems that she struggles with but still comes on top of all of this', 'Very Positive', 85.31, 4.72, 43.38);
INSERT INTO reviews VALUES (2259, 321400, 176, 'Playing with balls has never been so funny.', 'I refunded the game of that reasons:\n\n1 - There is no enough players to play with (Most servers are empty)\n2 - Many bugs with the launcher and stupid stuff.\n3 - I don''t feel much fun while playing.\n\n$5 USD is enough for the game.', 'Mixed', 65.91, 1026.53, 0.92);
INSERT INTO reviews VALUES (2260, 321410, 331, 'If you liked Harpoon, computer version or otherwise, you will love this. If you aren''t familiar with modern sensors and weapons systems, you will probably not enjoy this. The learning curve would be steep.', 'Freezes a lot', 'Mostly Positive', 79.15, 150.62, 45.82);
INSERT INTO reviews VALUES (2267, 321800, 1799, 'If you like Baldurs Gate 3, check out this blast from the past. One of BG3s predecessors, and a real fun ride. Plus you can create all of your party members, and none of them try to touch your no no spot.', 'Icewind Dale: Enhanced Edition is a fun game, but one that I probably should have just left as a memory. The game did not age well. For me especially, being that I already knew the story and the far outdated and messy user interface, controls, and design left me with a bogged down experience. This was not the fun nostalgia ride that I found in Baldur''s Gate I & II.\r\n\r\nThe game was relatively trouble free, though I did have some minor issues time to time. Nothing that I experienced was game break', 'Very Positive', 90.49, 28.93, 69.97);
INSERT INTO reviews VALUES (2268, 321830, 120, 'Cavern Kings\n\nHas a total of 5 trading cards.', 'incomplete and no longer in development but still on sale in early access', 'Mixed', 62.50, 1.23, 11.33);
INSERT INTO reviews VALUES (2270, 321870, 215, 'Profound struggles of regret and rebirth unfold in the liminal spaces bridging life and death, reality and fantasy, memory and hallucination. These blurred spaces become stages where individuals confront their past and explore new beginnings. Here, the boundaries of existence and perception are tested, as regret intertwines with hope, leading to self-awareness and transformation.', 'This is a stylish psychological indie horror game with a cool atmosphere. However, clunky character controls, slow character animations, cumbersome inventory management, annoying monster encounters in which you can die, and a lack of manual and auto-save features before you die from these monster encounters made this game frustrating and unplayable for me. After solving a puzzle, a monster killed me and threw me to a much earlier save point, and I had to start again to solve the same puzzle. Unf', 'Mostly Positive', 74.88, 5.38, 1.32);
INSERT INTO reviews VALUES (2276, 321960, 2434, 'Best HOMM since HOMM3. For sure it''s a modern version of a classic. I recommend if you enjoy the series.', 'Terrible!!!! after 9 hours of playing UBISOFT all the sudden wants an activation key WHICH WAS NEVER PROVIDED!!! No activiation code on game both in Ubisoft Launcher as well as Steam launcher.  Steam does not supply one in the game management tab and UBISOFT support has been useless saying it''s Steam''s fault.... \n\nContacted Steam support who refused to refund this game confirming that as long as companies like Ubisoft allow you to play at least 2 hours or own the game for 2 weeks, they are then ', 'Mixed', 52.22, 6.18, 10.42);
INSERT INTO reviews VALUES (2277, 321980, 383, 'Excellent game with a unique playstyle and artwork. Really wish the game could''ve been finished 100% and it didn''t have crash issues.', 'Abandonware.', 'Mixed', 68.41, 55.10, 0.85);
INSERT INTO reviews VALUES (2280, 322110, 2617, 'This game had me addicted like crazy.  Even I am shocked that I put about 80 hours into it.  I very rarely can actually play a game for that many hours. \n\nIf you''re into the idea of a roguelite game in the style of Mega Man, you can''t do any better than this.  I love the music and the gameplay is stellar.  The graphics kind of have that "flash game" look but I found them pleasing to look at and very colorful.  The game also performs great and is smooth as silk at high framerates.\n\nYou won''t be d', 'Gotta be one of the most overrated games I''ve ever played. This is not a worthy successor to Mega Man X. The procedural generation is awful, the stage design is the most low effort trash, just floating platforms over pits 95% of the time. The game is way too easy at the start, and gets progressively more absurd as it goes on. Then an extreme abrupt difficulty spike in the final two stages, which are twice as long and 10 times harder than the rest of the game put together. It just feels unbalance', 'Very Positive', 92.70, 80.77, 2.67);
INSERT INTO reviews VALUES (2281, 322170, 183462, 'Geometry Dash was actually based on a true event back in 1982. A man with a square-head was hated by everyone. He was soon brought to an arena where he was forced to jump over sharp spikes to survive...', 'do not play this game. this game is an extremely dangerous drug. it''s nothing but pointlessness, level after level of where you continuously sit and waste away, and addictive to the point where you waste hours of your time and ruin your life. i have spent tons of time playing this game and i regret all of it. for your own good, stay away from this game and quit it while you still can', 'Very Positive', 93.65, 17.32, 2750.57);
INSERT INTO reviews VALUES (2282, 322190, 2233, 'This game is a really fun turn-based tactical shooter. However, it falls apart at the higher difficulties due to the alarm mechanic which forces a slower turn based gameplay into a rush as more enemies pile in which can quickly overwhelm you. This is even worse towards the end of the game as you get enemies which can teleport and shoot on the same turn with two or three enemies spawning each turn. This game definitely rewards quicker strategy over slow turn based turtling combat like XCOM. The 1', 'I would give this a neutral rating.\nThe game itself is great but the writing is strangely propagandistic, always portraying women as strong and masculine (except for the farmer of course) whilst portraying men as bumbling baffoons. Strong men are given a backstory that makes them seem pathetic or weak in some other way. This forced trope gets pretty annoying after a while.', 'Very Positive', 94.04, 69.58, 6.90);
INSERT INTO reviews VALUES (2283, 322210, 960, 'Fun little game.\n\nAttention - even though Steam will tell you that the game has problems running on Steam Deck with no option to make adjustments on the graphics etc it really runs smoothly and you can customize graphics to your liking 👌🏻', 'The game is not a run and gun.  In fact it''s like Battletoads.  You have to remember all the points where the enemy appears.  Every now and then the game makes it impossible by changing the algo.    If you want a fast paced game, stay away.  If you want an ULTRA slow paced shooter, get it.  \n\nPersonally the game sucked.  I can''t see why people give it such high ratings due to the game just popping enemies from behind and from the blind.   It interrupts the game flow too much.     Also having to ', 'Very Positive', 89.79, 3.50, 4.60);
INSERT INTO reviews VALUES (2284, 322290, 331, 'I played this game a lot as a kid on my PSP, and only recently became aware it’s on Steam, and I’m super glad to be replaying it again. The soundtrack is really good, and the game feels really nice once you understand the controls (which become quite intuitive pretty quickly.) Also, Parin is a really charming protagonist!', 'ugh, this game is rough to get into...', 'Very Positive', 93.35, 22.18, 8.73);
INSERT INTO reviews VALUES (2285, 322330, 77516, 'Start the game. Die. Start again make it to day 5, die. Start yet again, don''t know what your doing at all. die to hounds on day 7. Play with friends. Grind for 12 hours everyday, barely making it to over day 20. Start again. Spend another 12 hours on a world, make it to day 30. Die to winter. Start another world. Kill yourself in the end.', ' Don''t Starve Together is a unique survival game that is fun with friends, though gets same-y fast. \n\nThis is definitely just my own taste in the games I play, because this type of game isn''t my normally in my wheelhouse. So, understandably, my perspective on this game is going to be that of someone who isn''t really into this type of game usually. It is fun, and you can really get a lot of value out of it with a group of friends, but I really, really find myself tiring of it quickly. I wouldn''t ', 'Overwhelmingly Positive', 95.71, 64.98, 9.13);
INSERT INTO reviews VALUES (2289, 322450, 453, 'The most confusing part about this game wasn''t the story and its twists, nor was it the gameplay, it was the fact that the Australian government was credited as one of the producing companies', 'When I started playing I found it quite interesting. But after a while it ceased to be fun. The reason being the puzzles are too easy to be satisfying. And in order to make the puzzles "hard" they are made artificially contrived. What that means is, the actual puzzles themselves are easy and you know the solution, but they are timed and/or have to re-use same panels again and again making it either annoying, or tedious or both. \n\nPuzzles tend to be fun when you spend most time figuring out the s', 'Very Positive', 90.29, 3.02, 2.78);
INSERT INTO reviews VALUES (2290, 322500, 15572, 'i finished the story in 3 hours so wait for a sale but This is the most innovative shooter i''ve played in years! This is the most innovative shooter i''ve played in years! This is the most innovative shooter i''ve played in years! This is the most innovative shooter i''ve played in years! This is the most innovative shooter i''ve played in years! This is the most innovative shooter i''ve played in years! This is the most innovative shooter i''ve played in years! This is the most innovative shooter i''v', 'It''s a good game, however, the developers, especially the CEO, are egotistical assholes who will take your money then remove content you paid for years later, while still selling the games at full price with marketing material that still advertises the content they took away.\n\nI highly recommend just pirating their games if you really want to play them. Do not encourage shitty behavior.', 'Very Positive', 90.62, 3.65, 3.47);
INSERT INTO reviews VALUES (2295, 322680, 195, 'velice dobrá hra sice jsem si ujebal mezerník ale hra tě na dlouhou dobu zabaví', 'Its boring piece shit, that I regret not refunding,', 'Mostly Positive', 73.33, 4.60, 0.75);
INSERT INTO reviews VALUES (2296, 322750, 111, 'I will edit my review later, but I just think that this game, while flawed in unfortunate ways, and stubbornly irritating at times, is overall a bit underrated, especially at the current price.', 'It''s not a bad game, but... it''s just not very good.\n\nThe combat (at least in the first few levels) is very slow. More importantly, the weapons and skills just don''t have any oomph. This game needs some juice in its combat. Even with skills that cause explosions and instantly vaporize the smaller enemies, it just felt... blah.\n\nThe UI is serviceable but obnoxious. In particular, the game says it plays best with a controller, but then forces you to use a cursor even with the controller. It also d', 'Mixed', 69.37, 65.47, 0.57);
INSERT INTO reviews VALUES (2297, 322770, 2027, 'The base game is a basic dungeon crawl, but with some nice mechanics. Melee combat allows blocking/parrying, you can climb ropes or chains, and there are traps and puzzles as well as monsters.\r\nBut it is in the DLC (The Sundered Rift) that the game really finds its stride, with a wider variety of monster types, more mechanics and more story.\r\nThe graphics are a bit cartoony, but that is ok. The only flaws are sometimes it is impossible to drop items (especially planks for crossing pits and chasm', 'Purchased the game while in Early Access expecting content updates (as typical with early access games). Find an announcement for a new content update, just to see that the developer, instead of updating the game with it (as typical with early access games) decided to make it a 15$ expansion for a 20$ game that is no more than 3 hours long.\n\nIf you are looking for a good VR dungeon crawler that doesn''t have as greedy devs as this one, play Karnage Chronicles or VR Dungeon Knight', 'Very Positive', 90.97, 9.93, 3.32);
INSERT INTO reviews VALUES (2298, 322780, 3503, 'its September 2024.   i really miss this game. i really wish this game can be revived as this is was and is very treasured by the community. o7', 'I miss this game. \nI escaped the real world for a couple of hundred very short hours, during the hardest time of my life, thanks to worlds adrift. \nWhen the game shut down it felt like losing a real friend. Knowing I''d never get to float between islands again. \nI come back over and over hoping to hear their voice again, but I never will. \nR.I.P World''s Adrift, and thank you for having existed, if only briefly.', 'Mixed', 62.15, 129.27, 407.73);
INSERT INTO reviews VALUES (2299, 322850, 102, 'Pro-cyclist mode is very fun, easy to enjoy but hard to master. Besides that, it is basically the same game of 2014 with better graphics and very well optimized for modest computers.\n\nIt is so relaxing to look at the roads, cities and villages while ordering actions to your team from time to time...\n\nHighly recommended.\n\nCyanide/Focus: congratulations for the "hype" of these days! Not dissapointed at all!', 'This game would be great if the developers were concerned at all about what people that paid $40 for. The idea and concept of the game is fantastic. The fact that the AI riders seem to react differently to my rider then the other 199 AI riders is flat ridiculous. Im not the top ranked rider so why can any other rider decide to breakaway but if I do or follow a breakaway the pack is right on my heels? How are riders able to maintain when they are completely out of both bars of energy? If that hap', 'Mixed', 46.08, 18.90, 232.57);
INSERT INTO reviews VALUES (2300, 322900, 134, 'Abso-lutely.', 'Mix in a real set of awkward controls that doesn''t use the keyboard to its full advantage, to an incredibly difficult game that does not seem to want to allow freedom outside an optimal strategy, and you have a game I wanted to stop playing after 20 minutes, but tried to suffer through more. In addition, the implementation of tutorials is down right HORRIBLE, which is crucial in an RTS game. This may be for the masochistic RTS fan, but stay far away if otherwise.\n\nMore commentary and gameplay fo', 'Mixed', 52.24, 140.07, 2.35);
INSERT INTO reviews VALUES (2301, 322920, 1736, 'THE LAZY DEVS NEED TO BRING THIS GEM OF A GAME BACK!!!!! It''s so much better than Call of the WIld it''s actually unreal. F***ing great game. Shame on them for abandoning it with ZERO statement', 'The developers took the money and ran. Delisted the game from steam, couldn''t be arsed to fix anything, left it in a sorry state.\n\nEveryone who bought the game, including myself should have got a refund', 'Mixed', 56.74, 51.93, 78.68);
INSERT INTO reviews VALUES (2309, 323060, 1195, 'Love the game just wish they didnt abandon the type of game play. I''m fine with the no longer be update or expanded... make another with the same game play call it Tharsis 2  or something. Did it really sell that bad????????', 'Well, I was going to post a good review, but I re-installed the game and discovered it NO LONGER WORKS. Not only that, but the developers know it''s broke, know how to fix it, and choose not to. Be aware when purchasing. Yes, you can fix it on your end with a batch file or something, but should you have to?', 'Mostly Positive', 71.80, 19.87, 55.48);
INSERT INTO reviews VALUES (2310, 323190, 36227, 'Little Timmy came to us as a refugee, got put into the coal mines on a 24h emergency shift and died. \r\nAll in one day!\r\nWhat more could you want?', 'I''m sick of this game pushing updates that are nearly 1gb in size ALL for the sole purpose of pushing new ads to me in game. The game hasn''t had an actual content update in several years but these ad updates come every few months. If they wanted to package the ads in with some bug fixes, or even small content additions then I could have a totally different opinion on this. Instead they use my data, and my HDD as their own personal ad delivery service and I can''t stand it.  They abuse the steam t', 'Very Positive', 92.64, 35.53, 180.75);
INSERT INTO reviews VALUES (2311, 323220, 2448, 'Genuinely overlooked roguelite with a fleshed out levelling system and all of the cruel-but-fair fun of games like Spelunky. This game has a charm that is both addicting and infectious; every secret mechanic you and your friends discover is a euphoric revelation in itself, and is best enjoyed without outside information.', 'It''s Spelunky.\r\n\r\nIf you like Spelunky, this is a great twist on it, but I hate Spelunky.', 'Very Positive', 89.50, 266.68, 0.70);
INSERT INTO reviews VALUES (2317, 323320, 2796, 'Amazing, amazing game. One of those games you played as a kid and replay as an adult, and it’s even better the second time.', 'Honestly, I thought  this game was too boring  to continue. And I reached this stage of boredom fairly quick.  The world felt flat and empty.  Maybe  I am just not the target audience and it will be more appealing to kids. But honestly... I do think that there are more appealing, games available , also for kids.  Cute robot tho.. Still a no for me.  \n\n', 'Very Positive', 93.49, 7.85, 0.17);
INSERT INTO reviews VALUES (2318, 323380, 908, 'Such a based game.\r\nMany games released in 10s tried too hard to do this "this game knows you exist" thing which eventually became so overdone that many good examples of that trope now can only annoy you. However I think The Magic Circle is an exception that stood the test of time, mainly because this "meta" thing serves the narrative purpose and translates the main ideas of the game really well. Bad and arrogant creators drive their games into development hell on the one side and crazy fans and', 'didn''t click with me. the framing and narrative devices felt hamfisted.', 'Very Positive', 90.97, 3.88, 0.95);
INSERT INTO reviews VALUES (2320, 323470, 6786, 'yo i have the worst pc on the word i can''t even play roblox on it or 1v1.lol and this game worck good for me man i love this game', 'The game is basically redundant now because Xenoverse 2 features the story and every single stage/character from the first game. \n\nJust buy the Hero Patrol DLC for Xenoverse 2.', 'Very Positive', 85.91, 29.42, 50.77);
INSERT INTO reviews VALUES (2322, 323580, 1013, 'You have impressed the Gods!', 'Devs dont you understand that you need to create a reasonble map location? I dont want to waste my time trying to decipher where am I. That game looks amazing but I not in the mood to keep walking around', 'Mostly Positive', 77.59, 12.73, 0.42);
INSERT INTO reviews VALUES (2325, 323670, 318, 'its missing a proper online multiplayer mode to be perfect', 'I''d rather play Retro Kart Rush if I want to play a Kart game on Steam.\n', 'Very Positive', 84.59, 0.80, 0.43);
INSERT INTO reviews VALUES (2328, 323720, 446, 'It is a point-and-click adventure game with a psychological horror atmosphere. The combination of polished graphics, atmospheric sound, and challenging puzzles creates a compelling experience. It feels like playing Resident Evil or Silent Hill reimagined as a point-and-click adventure.', 'Terribly aged game that unlikely fit the usual Daedalic quality you can hope for', 'Mostly Positive', 72.42, 2.13, 8.55);
INSERT INTO reviews VALUES (2330, 323850, 3227, '23423423', 'Cool fast paced fun with friends, when you can play it, because the game crashes contantly :(', 'Very Positive', 85.56, 0.80, 1.55);
INSERT INTO reviews VALUES (2335, 324120, 171, 'Cute little puzzle game. I liked it', 'As one of the other (positive) reviewers said, "There is no direct entertainment value in this game".\n\nHeed that warning.\n\nObviously a lot of people really enjoyed this, so I can''t say it''s bad.  However, I will say that it''s not really a "game", so adjust expectations accordingly.  I found it to be ultimately a particularly unengaging, only marginally interactive, "experience".  As another (negative) reviewer said, basically a "walking simulator".\n\nAgain, lots of positive reviews here (which is', 'Mostly Positive', 72.51, 2.52, 0.88);
INSERT INTO reviews VALUES (2336, 324140, 113, 'Fun and challenging platformer to play either alone or with a friend!\nGood gameplay, good soundtrack and very easy to get into, but hard to master.', 'Bafta chafta...puzzle plattformer', 'Very Positive', 82.30, 5.17, 0.27);
INSERT INTO reviews VALUES (2337, 324160, 1843, 'if you love depression, sadness, and absolute agony, this game is for you :''D', 'I hate the art style. The girls look like bugs. But I was willing to put that aside since my friend was raving about how good the story is. BUT THE MAIN GIRL IS SO ANNOYING TO ME. SPEAKING TO HER FEELS LIKE SPEAKING TO A CHILD??? i don''t get the appeal. She''s supposed to be in high school, but it seemed like she has the mental capacity of a toddler. Is that supposed to be endearing??? I don''t want to be in a relationship with a kid.', 'Overwhelmingly Positive', 97.02, 1.55, 26.05);
INSERT INTO reviews VALUES (2338, 324170, 178, 'Short and sweet vn. There were some typos which isn''t uncommon for these types of games. I loved the character development and the visuals were flawless.', 'Mediocre execution of a decent premise. I love tsundere protagonist (i.e. Cinderella Phenomenon, Variable Barricade, etc.). However, Ahri and her love interests are too one-dimensional to make for a compelling romance story. It''s cute although she clearly has better chemistry with one love interest over the other (poor Kenta). If the game was maybe a little longer, or maybe free?, I wouldn''t be so fussed but I just don''t think it''s worth the price. It''s just too bare bones. Go play Cinderella Ph', 'Mixed', 65.17, 3.37, 1.87);
INSERT INTO reviews VALUES (2339, 324190, 186, '(probably) WONT BE FINISHED.\r\nif you''re up for exploring documentation and trying out things, then have fun :)\r\n\r\nI''d say the devs do deserve the pay. they worked hard, and what they''ve achieved is amazing. and the price is really low.\r\n\r\nthis could be the best game ever made... but I hate to admit, its development stopped before it actually became an actual game, and now its crumbling apart... saddest thing ever.', 'This game could of been so cool it had so much potential the devs sold the bag truly sad\n', 'Mostly Negative', 37.63, 17.08, 3.23);
INSERT INTO reviews VALUES (2341, 324260, 380, 'Good quality but extremely basic space game. Ill give it a thumbs up, but 5 out of 10 kind.', 'It''s not bad just really in need of polish. Void Expanse does a lot of things just fine just not well enough to make it stand out. If you''re a fan of such games you''d probably enjoy it a bit but not necessarily more than anything else.', 'Mostly Positive', 73.68, 22.27, 12.72);
INSERT INTO reviews VALUES (2343, 324310, 720, 'Well... what should i start with about this game.... its not euro truck sim 2 thats for sure... but its still fun enough to play.  In many ways it is not like euro truck sim 2... such as the fact that you cant simply go out for a drive without being on a route.   the buses also do not drive as well as the trucks in euro truck sim 2... they are pretty janky when taking corners.  There is no damage system but you still have to pay for any repairs after the route ends.  There should be a save syste', 'The game is quite boring compared to other games that are cheaper.', 'Mixed', 63.33, 40.03, 0.98);
INSERT INTO reviews VALUES (2348, 324510, 1311, 'This game is Wonderful. You get the feel of Minecraft, with the added bonus of claiming "Territory" in the form of Beacons and plots of land. this game, while it does have a Micro-transaction feature, it is truly Free-to-Play, because the same currency that you can spend money on, is earned through objectives in the game. The interface is easy to understand, and the tutorials/objectives are clear and concise. Wildlife, fauna and flora, the unique crafting options. even skills for your character ', 'The game itself is great.\n\nUnfortunately, without any update in years, the game has been stagnant and the player base has been slowly dying. After the new owners of this game acquired it, they only seem to have plans to keep the servers going with no other communication for anything that could potentially be in the works to revitalize the player base, or even instill confidence that the game is in the right hands. They have poor communication skills and leave the remaining active player base in ', 'Mostly Positive', 74.14, 12.05, 1044.67);
INSERT INTO reviews VALUES (2349, 324520, 219, 'Maybe the best tower defense game ever. Great challenging play. \r\n\r\nWould be better if the screen scaled better, so I would not ever have a menu on top of the battle field (I mean on a PC there is a ton of visual real estate).', 'The game would be great if you weren''t restricted with the cash you need to purchase weapons & upgrades. The cash comes from the kills you inflict. No weapons no kills, they walk right by you and flip you the BIRD!!', 'Mostly Positive', 78.08, 285.13, 84.37);
INSERT INTO reviews VALUES (2350, 324570, 770, 'Game''s alright. Gets a bit boring after the first 1000 hours.', 'Halo: Spartan Strike is a fast-paced and enjoyable top-down shooter that integrates smoothly into the Halo universe, set during the events of Halo 2. The gameplay is fun and offers a solid Halo experience in a condensed format, making it easy to pick up and play.\n\nWhile the game is relatively short, taking around 6 hours to complete, there is a significant design flaw that hampers the overall experience. In order to unlock the final 6 missions of the 30 available, players are forced to achieve a', 'Mostly Positive', 77.14, 5673.60, 5.97);
INSERT INTO reviews VALUES (2352, 324650, 149, 'I played this game when it first came out on Xbox in 2016, out of nostalgia I bought this game and played through it again. I can say that while the game suffers from that classic case of "Marvel camp" in dialogue writing, it''s still a good time and well worth the 3~4 hours of gameplay this game offers. The graphics hold up decently well, the characters are likeable enough, and the puzzles are surprisingly fun. Well worth the 3.38 CAD I payed.', 'No clue why the reviews are flooded with people that have 6+ hours in the game; I beat the game in 2.5 and only racked up more to see how long the "TK 1000 objects" achievement would take. \nJanky enemy AI, bad story, and zero difficulty/stakes. Some funny moments from game mechanics but it really hasn''t aged well overall.\n\nYou''re better off downloading a custom HL2 campaign and using the gravity gun.', 'Mostly Positive', 79.19, 3.45, 3.93);
INSERT INTO reviews VALUES (2353, 324680, 1118, 'Haven''t played this game much yet but it seems solid', 'Both support and the CEO are absolute morons. When I first booted up AoE4, it automatically unlocked 2 achievements for me, which are now permanently unlocked on my Microsoft account. I reached out to Relic''s support, their CEO Justin, and Microsoft support, all of whom told me that it was "impossible" to re-lock these achievements.\n\nAbsolutely unacceptable, disgusting company.', 'Overwhelmingly Positive', 96.51, 5277.35, 2.22);
INSERT INTO reviews VALUES (2354, 324710, 188, 'On the one hand, I feel the experience is better conveyed through the original book format; on the other hand, I made Ophelia become a serial-killer (multiple times) and committed cannibalism. So I''d say YEAH good enough', 'is this supposed to be funny?', 'Very Positive', 89.36, 5.55, 0.42);
INSERT INTO reviews VALUES (2356, 324740, 294, 'THIS is the fighting fantasy done right . The atmosphere , the interface , the fighting style , the way we can choose character that have some diffrent in skill. for anyone who so into fighting fantasy , you can buy this one and you will not be disappointed.', 'This is not a good game for anyone who cares about what is happening in a game. It has a cool look and interesting sounds, but I think far too much time must have been spent on these things and not nearly enough time on developing a well thought out game which makes sense. As someone who has played rpg games for over 30 years I see it through that lens. As an rpg game it is similar to playing with the worlds laziest, most unprepared and most arbitrary dungeon master ever, though he does have som', 'Mostly Positive', 77.21, 0.27, 1.25);
INSERT INTO reviews VALUES (2358, 324760, 118, 'best monster truck game ever, if it dont crash', 'Writing this review to say its a buggy mess.\nThe most destructive thing you can do this game is buy it, cause its boring and a waste.\nHey Devs! You know that email you sent to Nerdcubed? yeah he made a pretty nice video about that you scum.', 'Mixed', 61.02, 5.90, 0.12);
INSERT INTO reviews VALUES (2360, 324800, 8483, 'Fast-Paced adrenaline pumping FPS. Many weapons and Weapon Modifications. Variety of Enemies, amazing bosses, side missions. I enjoyed this game.', 'Refund requested.\n\nGame puts a woman inside your brain who never stops talking.\nI cannot handle it. I am sorry. This horror game is too scary for me.', 'Very Positive', 87.29, 24.18, 0.98);
INSERT INTO reviews VALUES (2361, 324810, 994, 'scratches that unreal tournament itch, when epic themselves have abandoned the series.', 'Frag like it''s 1999\nForever unfinished game like it''s 2019', 'Very Positive', 83.90, 3.18, 12.67);
INSERT INTO reviews VALUES (2363, 325090, 157, 'Deep Dungeons of Doom\n\nHas a total of 6 trading cards.', 'It''s a mobile game, you hit block, or attack on a timer.', 'Very Positive', 88.54, 0.92, 0.27);
INSERT INTO reviews VALUES (2364, 325120, 155, 'Came here looking for your average horror VN and found a gem.\n\nOnly two things I didn’t like:\n- Some dialogues are painfully long without advancing the plot.\n- The “building” of the scenery at the beginning of the story doesn’t make sense at all (Regarding the parents leaving his child go into a forest for days in order to pursue a killer).', 'Abysmal writing', 'Mostly Positive', 71.61, 24.68, 0.80);
INSERT INTO reviews VALUES (2367, 325210, 926, 'It''s nice and simple, but it would be great if they added the purpose of building something apart from your own desire.\nAnd maybe adding some more things to do and explore around the map would not hurt.\n\nCan''t say it''s a fantastic game, but it still deserves a thumbs up, if you like chill journeys and driving dog sleds.', 'The game has really good potential, but I cant recommend it for any co-op experience.\nWhen people join, there is a chance their dogs get stuck in the air forcing the host to reset the lobby. When trying to restart the lobby, the host gets an infinite loading screen. \nAlso got soft locked when someone built something while another player was looking in that same menu. \nThe game is chill and everything is really charming, but its just frustrating to constantly deal with soft locks.', 'Mostly Positive', 73.11, 8.35, 0.82);
INSERT INTO reviews VALUES (2372, 325420, 653, 'I absolutely LOVE this game and I wouldn''t have it any other way.  The price is amazing and the amount of resources it uses on my computer are next to nothing.  I also love how active the developers are in the community.\n\n\nUpdate 6-21-18\nThe game has changed quite a bit since my original review (2-14-15), with a lot more skookum (good) stuff added, but the quality of gameplay has not suffered at all (it''s actually much better, and more optimized). There is a steep learning curve, but if you choo', 'It''s a good game, but it has been abandoned. RIP', 'Mostly Positive', 70.75, 2210.95, 13.03);
INSERT INTO reviews VALUES (2375, 325520, 149, 'Fire: Ungh’s Quest\n\nHas a total of 5 trading cards.', 'For a Daedelic game I was quite dissapointed. \n\nThe artwork is really fun, and the soundtrack is good, but some of the puzzles are quite abstract, I would often look at an object and not know what it is, leading to random clicking to find out where to go or what to do. It felt as if they tried to save time developing multiple language packs so they just invented stuff. The videos make it look better than it is.\n\nAs others have mentioned the game is also really short (I would recommend getting it', 'Very Positive', 81.88, 0.53, 5.38);
INSERT INTO reviews VALUES (2376, 325610, 12447, 'This is a really easy game for beginners, especially if you play the 2 easiest factions in all of total war history: The western and eastern roman empire. They are so easy you can just stomp everybody on turn 1 and you have the best starting infantry. Limitaneii borderguards are sooooo good they have super high melee attack and get so many kills', 'Game has great potential, but horrible loading times & performance makes it a chore to play. Better to avoid buying this game and play another better performing game.', 'Mostly Positive', 79.98, 267.33, 943.92);
INSERT INTO reviews VALUES (2378, 325730, 214, 'I thoroughly enjoyed. A fairly short campaign but i''d love to see more.', 'interesting idea, story doesnt make sense and combat is not a challenge in the slightest. other than lacking any real soul, its buggy as hell no pun intended. i''m glad i got it on sale', 'Mixed', 69.63, 15.48, 1.77);
INSERT INTO reviews VALUES (2382, 325930, 134, 'Great game to help scratch that hard to reach itch left over from Castle Crashers. Note that you need to be in the same exact row as the enemies to make contact with their hit-box. This is particularity difficult if they can fly and can make fighting them a bit tedious. Still addictively fun. 7/10', 'the lane-based gameplay is just kind of annoying, and the combat is shallow and repetitive. it''s just not all that good. i wish it was more fun because it''s quite pleasing aesthetically.', 'Very Positive', 85.07, 4.05, 3.88);
INSERT INTO reviews VALUES (2387, 326150, 350, 'Death Skid Marks\n\nHas a total of 12 trading cards.', 'It''s a randomized rogue-ish game. But it''s also a fast paced action game.\n\nThis sounds great. But it''s honestly not very good at all. The problem comes with a really inconsistant execution. A lot of the bosses are "puzzle bosses" that you can only beat with a specific build or playstyle. But you don''t know what sort of boss you''re going to encounter. This leads to the game being "rock paper scissors", but on a 30 minute time delay. You may have lost the game just as you started, because of the c', 'Very Positive', 92.57, 3.08, 2.08);
INSERT INTO reviews VALUES (2388, 326160, 709, 'Recommended for people not afraid for old school rpg. not alot of indication but alot of fun.', 'i bought this Game for more than 30€\nNow its Free.\n\nFuck that Shit.', 'Mixed', 49.65, 105.92, 2.02);
INSERT INTO reviews VALUES (2389, 326180, 479, 'For a five hour game, I thought this game was a fun satire point & click game, decent but cheesy voice acting, and aged animations. The ending was a funny twist though! I think it was a refreshing spin on Dracula''s usual story being retold these days, where it''s Dracula chasing after his lost love. Instead, it''s Dracula wanting his daughter to be marry someone who knows what he''s doing in show and business. Some of the puzzles were tedious but fun to play through. Except for the jewel puzzle, th', 'Casual puzzle game with mediocre graphics.\n\nI''m not sure why this game ended up in my library, I probably would never play something like this today but apparently I put 8 hours into it and finished it some time ago.\n\nProbably worth a quick spin if you can get it very cheap, but there are so many similar games out there now that are probably better quality and a better use of your time.\n\n', 'Mixed', 65.97, 4.85, 8.28);
INSERT INTO reviews VALUES (2390, 326190, 328, 'Point and click hidden item/puzzle game, a pretty quick play but for a few dollars if you like these kinds of games it''s not the world''s worst purchase. Only a few settings in the map but it''s an interesting little story. The voice acting makes up for the very old graphics and animation.', 'It is a hidden object game with an interesting mechanic that you don’t really see often - you sometimes have to use items from your inventory on hidden object scenes. But that is about the one good thing I can say about it. \n\nOn the bad side of things I found the game confusing, the voice acting is extremely loud even if you have all the volume sliders in the settings all the way down and the game is in a weird 3D-ish kind of map where in each room you can turn around to face 4 different directi', 'Mostly Positive', 72.26, 5.62, 4.57);
INSERT INTO reviews VALUES (2391, 326340, 102, 'BeatEmUps (brawler) = KungFuMaster -> RiverCity (Kunio-kun) -> DoubleDragon', 'I was wondering why the direct sequel to River City Ransom never came to the west.\nIf I recall the original for this was a Japan exclusive on the NES (Or Famicom if you''re a stickler.)\nThis could have used more polish when "remaking" it, my main issues with this game being (especially the first thing in this list):\n\n-Randomized Stat Gains: The single player campaign uses Random Number Generation for your created characters stats, these let you move faster, hit harder, not die better, etc. \nThese', 'Mixed', 68.63, 0.18, 27.15);
INSERT INTO reviews VALUES (2394, 326410, 1924, 'One of my favorite games of all time is Sid Meier''s Pirates. And I''ve always been searching for a game that fills the same niche for me but just gives me more ''game'' in various ways. Assassins Creed Black Flag probably came the closest actually, despite the pirate aspects of the game just being an add-on to an Assassin''s Creed game. Sunless Sea hit a lot of the same notes for me too, although I ultimately didn''t like how grimdark and difficult the game was.\nI love pirate games, but I''m also not ', 'HAHA! If you wanted an arcade game where you can reverse your ship and wind doesn''t have any meaning, be my guest and purchase this game.\nI hoped it would be similar to Sid Meier''s Pirates but only with the combat and trading element.', 'Very Positive', 80.56, 1.53, 1.68);
INSERT INTO reviews VALUES (2396, 326460, 16742, 'It''s one of the only fun PvP game in 2024.\nIt takes a long time to get the fun weapons and upgrades, but when you''re there it''s a blast.', 'do not download, After a few hundred hours this game is dying and no one moderates the game. Hackers now freely have started to roam and 90 percent of people are toxic and racist', 'Very Positive', 93.46, 87.80, 380.40);
INSERT INTO reviews VALUES (2398, 326480, 2006, 'The VN That Made The Better Half Of 2024 Particularly Memorable For Me. If You''re Interested In VNs And Not Sure Where To Start, I Highly Recommend If My Heart Had Wings - Get It On Sale, Get The Patches And You''re Good To Go.  Twin Loli Route Is Peak AF - Also One Of Them P*sses On You ', '༶•┈┈୨♡୧┈┈•༶\n\nThis game is insanely long. I couldn''t enjoy it once I found out that the original game had CP in it, and that there''s degenerates on here who are leaving bad reviews crying that the CP was cut out. It had some wholesome scenes, but it''s ruined for me, especially since there are some sus CP-ish scenes that weren''t cut (such as the minors in the bath and in towels together)', 'Very Positive', 92.27, 66.13, 6.00);
INSERT INTO reviews VALUES (2402, 326720, 113, 'Simple, fast-paced roguelike with unlockable modes, spooky twists, solid mechanics and fun power-ups', 'I was totaly bored in 10 minutes. Pacman may have beem cutting edge entertainment in 1981, but things have moved on.', 'Very Positive', 88.50, 1.00, 0.17);
INSERT INTO reviews VALUES (2404, 326840, 343, 'robot yaoi', 'I would have enjoyed this game a lot if it wasn''t for it''s horrendous implementation of its keybind. For whatever reason the dev didn''t consider Shift, mouse 4 and mouse 5 viable keybinds. For an action game such as this those are very important. \r\nAlso in game you can equip 3 weapons. So you would expect to bind weapons in numbers right? \r\nWRONG the dev somehow try to fix what has been working for decades.\r\nSo this is his "ReVoLuTiOnArY" mechanic.\r\nTo use a "Left weapon" you gotta hold a key...', 'Very Positive', 82.22, 13.90, 0.28);
INSERT INTO reviews VALUES (2410, 327030, 3986, 'WORMS! I LOVE WORMS! Sometimes I pretend to be a worm in my living room, wriggling around the ground looking for little morsels to eat. It''s so much fun to just let loose! My dream is to turn my backyard into a worm haven and be buried there. God I love worms. Wriggling little worms. Worms. Worms. Worms! WORMS!', 'Objectively one of the worst designed intros. Why is it necessary to make a STARTLINGLY LOUD and UNSKIPPABLE intro. With intro sound that is NOT affected by any volume settings of the game. You have no choice but to take off your headset or potentially suffer ear damage every time you boot the game. Horrible. I hope for the devs of this game to be tied down with ear shattering volume skibidi toilet playing on repeat into earbuds until their ears bleed.', 'Very Positive', 83.84, 28.88, 4.90);
INSERT INTO reviews VALUES (2411, 327060, 225, 'Easy controls (only C and X), yet the game itself is extremely difficult and unforgiving.\n\n2 hours in, only finished 1/5 of the game...if died within a level, it has to start over from beginning, but I''m getting better and better after repeating the same level 10 times, so that''s really good?\n\nDifficulty level will increase in later levels, so this little game, 30 minutes a day, will take me a month to finish my first run, or I''ll eventually give up. \n\nA good game for those who love challenges.', 'Runs smoothly for the most part and very atmospherical. But it is rare that I play a game that is so brutal towards the player, and the last 60 minutes was spent fighting the final boss. Then it went from enjoyable to annoying really fast. And can''t say that I am a fan of the lack of health bars.', 'Mixed', 69.78, 1.82, 3.67);
INSERT INTO reviews VALUES (2412, 327090, 1058, 'If an animal attacks you, you can escape if you are not wearing armor.\nWearing armor will make you significantly slower, so it''s easier not to wear anything unnecessary.', 'I feel completely at loss. I did get the game in a sale with 90% of discount, and still feel like I should be pay to play this atrocious game. the graphics are like a playstation game, the first console. It''s so ugly that I think my first cellphone could run it.\n\nIt''s just bad. Even for just a few cents its pretty expensive for what it is.\n\nThis game is just a offense for every game developer out there.\n\nDon''t buy it, don''t play it, I do not recommend in any way.', 'Mixed', 53.59, 55.73, 0.22);
INSERT INTO reviews VALUES (2413, 327140, 413, 'Effectively, it is a VR art studio, where you can make basically whatever you like.', 'This app is highly outdated compared to other creative VR apps. It is such a shame that a big company like google still charges 20€ for this and doesn''t update it. It lacks many important features like 3D brushes, layers, infinite scaleability and animation  like it''s compedetors Quill and MasterpieceVR.\n\nMost brushes are useless from an artist perspective, but "looks cool" for a new VR-user. Therefore, Tilt brush feels less like an "unleasher  of creativity" and more like a "wow VR is cool" - e', 'Very Positive', 92.25, 7.60, 17.80);
INSERT INTO reviews VALUES (2416, 327220, 658, 'https://steamcommunity.com/sharedfiles/filedetails/?id=1687640967\nhttps://steamcommunity.com/sharedfiles/filedetails/?id=1687640556\nhttps://steamcommunity.com/sharedfiles/filedetails/?id=1688165338', 'It''s a pretty bland point and click adventure. If this was released in 2005, maybe I would rate it higher.\n', 'Very Positive', 87.39, 11.62, 7.32);
INSERT INTO reviews VALUES (2417, 327260, 136, 'Very Good', 'It''s a cute idea, but it didn''t really do it for me.', 'Mostly Positive', 72.06, 2.47, 0.98);
INSERT INTO reviews VALUES (2418, 327310, 103, 'A simple but fun stealth game', 'Stealth game for one-handed. If you have two hands, there are many many many better stealth games. The mouse-only control is super frustrating for experienced stealth gamers. You have no idea when she is gonna crouch, run or break glasses - they are all done by left-clicking!!!', 'Very Positive', 82.52, 5.67, 0.70);
INSERT INTO reviews VALUES (2421, 327390, 108, 'Please please please do a modern retake on this. I love this and seeing it in an updated skin would be absolutely amazing.', 'This game is super old and hard to use. Controls are difficult. Seems to run reasonably well though, so if you used to play this game back in the day it will probably work well, but if you''ve never played before, don''t bother with this one.', 'Very Positive', 93.52, 38.53, 0.17);
INSERT INTO reviews VALUES (2422, 327400, 591, 'I was about 20 when this game came out and I am 51 now. The gameplay has stood the test of time, Easy to while away the hours pressing your matters in the new world.', 'The game was fun and promising until the combat system showed its ugly face. The combat is beyond frustrating and it turns the game experience sour. Too bad.', 'Overwhelmingly Positive', 96.11, 503.87, 44.02);
INSERT INTO reviews VALUES (2423, 327410, 2776, 'Small, short, and simple, \nyet calm, peaceful, and pure.\n\n╰┈➣', 'It was a cute story but not enough interaction in game. It''s fine but I wouldn''t play it again.', 'Very Positive', 84.33, 2.12, 3.65);
INSERT INTO reviews VALUES (2424, 327440, 145, '10 years ago and better than concord\n', 'oh why did i bought this. dont buy even if you''re no. 1 fan of the band. just watch the gameplay on youtube. the dev should be crucified', 'Mostly Positive', 74.48, 0.12, 1.05);
INSERT INTO reviews VALUES (2427, 327510, 544, 'Dude really came back after half a decade and dropped a patch to make the gameplay loop Just Work.\r\nEveryone thought we needed the ability to carry multiple stacks of the same item, turns out we just needed to be able to carry 1000+ of whatever in a single stack. Stackable loot automatically deposits itself into your inventory when you search a container. The old gameplay loop was opening every locker and checking to see if you could get a "free" medistim instead of using one of the precious few', 'After reading the reason for some of the mechanics such as unloading a weapon im thinking this game takes itself to seriously for how it looks.', 'Mostly Positive', 79.96, 105.88, 86.82);
INSERT INTO reviews VALUES (2428, 327560, 643, 'https://steamcommunity.com/sharedfiles/filedetails/?id=2843978547', 'A great premise but disappointing execution. The game is very linear. You can roam wherever you want in theory, but if you go somewhere before being explicitly told to, you can''t interact with any plot-relevant items, you''ll use up valuable resources, and you may end up making the whole thing harder for yourself because some parts of the world only function once. You''ll have to come back later when you''re told to go check that area out anyway.\r\n\r\nThe resource economy and amount of backtracking a', 'Very Positive', 91.76, 4.98, 3.23);
INSERT INTO reviews VALUES (2430, 327670, 588, 'I bought the game a long time ago and often find myself coming back to it. Sure, the RNG aspect can make things challenging, but there are ways to prepare for and work around it.\n\nHint - select skills that can help you get out of situation when RNG makes you stuck, since RNG may have you killed even with best equipment. And having the best equipment isn’t essential in the beginning. However, if you manage to survive, you’ll have the opportunity to acquire it later turn or two before bosses. Care', 'I wanted to like it because it has a fun theme and sense of humour. Unfortunately the dominant strategy is to grind XP in easy fights, and if you don''t it becomes frustratingly hard. Also lags quite badly for such simple graphics on my laptop.', 'Mostly Positive', 73.47, 39.70, 14.70);
INSERT INTO reviews VALUES (2432, 327740, 459, 'FPS+RPG with an emphasis on vertical platforming and jump puzzles\ntruly one of a kind. it even runs on monolith''s immaculate engine designed for the pentium 2\n\nbe sure to check out the Killer App Mod (available on MODDB for widescreen fixes, modern system compatibility, and cut content available in the XBOX port only)! it''s as close to the intended way to play as you''re gonna get without the period appropriate hardware', 'Doesn''t work well', 'Very Positive', 90.41, 19.63, 0.33);
INSERT INTO reviews VALUES (2434, 327860, 1499, 'I bought this April 10th 2016, but just started playing it on August 31, 2024.  I paid $9.89 for it back then and I see it''s gone up 50% since since then.   Its a bit of a strange game and I don''t think the devs thought it out too much.  They made some things super simple, like being able to summon your ship out of your inventory at any time and other things super difficult, like trying to figure out mapping and which way you''re going.', 'For what appears to be a minimalist game, it really put a strain on my laptop. Gameplay felt boring enough that I just decided to uninstall.', 'Mostly Positive', 75.85, 7.48, 1.47);
INSERT INTO reviews VALUES (2435, 327880, 372, 'very cool', ' Like running around the house at full speed, blindfolded, lights off with two broken toes and a broken nose. Just couldn''t see the point and can''t find the fun.', 'Very Positive', 85.48, 0.87, 1.07);
INSERT INTO reviews VALUES (2436, 327890, 3144, 'bread', 'Unfinished, unoptimised, and kind of unfun. 5/10\n\nI tried this back in 2015/16 when it was early access, and it was ok. Very difficult, the bread moves all slow and clunky, but that''s kind of the point of the game. I thought I''d leave it to bake more.\n\nFast forward 9 years or so, and it still says welcome to early access on the fridge. It has more modes, but my steam deck really really struggles with rampage mode. The camera is an absolute pain and the bread still moves slow and clunky.\n\nOnly ge', 'Mostly Positive', 77.10, 1.80, 4.27);
INSERT INTO reviews VALUES (2439, 327930, 175, 'Worth playing? Oh yes, just bear in mind it''s a 30+ year old game, so you''ll have to do some homework with the manual before you can even hope to make your party. Be sure to check the steam guides for further help. Also, keep this handy so the copy protection doesn''t catch you with your pants down.\n\nWith all that said, the game is a fun romp through the Holy Roman Empire in the late middle ages, right at the turn of the century. It''s quite ambitious in the amount of ground it tries to cover, but', 'Been trying to install the game. Keep getting a disk write error after game download. Any help would be appreciated.', 'Very Positive', 89.71, 44.63, 1.23);
INSERT INTO reviews VALUES (2441, 327950, 116, 'This game might be the ancient ancestor of Crusader Kings, Mount and Blade and  Total war series.\n\nOld but gold. please give this game a chance.\n\n11/10', '(This game is ancient and runs like DOSBOX, the controls being designed for atari or whatever it was. Still played on my win10 just fine. I figured what I had to out, others may not have the patience for that project) Unfortunately I never got the chance to play this GREAT GAME as a kid, it was slightly before my time. However having played it since I can see that it truly is unique in its immersion, even to today''s standards. You play a daimyo making your personal decisions and in personal cont', 'Overwhelmingly Positive', 95.69, 70.33, 1.37);
INSERT INTO reviews VALUES (2445, 328070, 1098, 'This game was absolutely lit, If you devs read this you made a extremely high quality game. Unfortunately just bad timing :/', 'Congratulations of wasting money on developing a quake live clone that too way to long to develope.\nYou not only wasted money but also extracted some players from a small dying community. Will always get my negative review because of that. Enjoy your 10 players community since day one\n\nBesides that, the game is actually good and solid.', 'Very Positive', 85.70, 13.60, 0.32);
INSERT INTO reviews VALUES (2446, 328080, 5015, 'I''ve been playing this game for a long time, and I love it. Rise to Ruins has a high difficulty curve in my opinion, and some game mechanics (pathing, figuring out city layout, building proper mazes for tower defense) add to the difficulty, but in an engaging way- it feels like one more mechanic to overcome. I love the simplicity of the graphics; the rising difficulty level; the strategies you can come up with and implement; the balance of each part of your society... I didn''t expect to like thi', 'Fantastic game if you like RTS and tower defense. Unfortunately, the dev has abandoned it.\n\nI bought the game years ago, when updates actually released still. I understand that life gets in the way of things. The development cycle would make for a good read if you have the time to dig it up. IIRC, he had cancer, went bankrupt, hit it big on stocks, promised a bunch, delivered half, and announced a new game that hasn''t gone anywhere.\n\nI recently picked up Rimworld and was immediately reminded of ', 'Very Positive', 88.00, 252.13, 32.62);
INSERT INTO reviews VALUES (2448, 328220, 158, 'My opinion of this game:\nCurrently it is too buggy to play. Many functions don''t work properly, the controls aren''t good. I would like to play more with the mouse, because the IJKL-Controlling is seriously bad. \nBut although there are these problems, the game still has a good start:\nThe story is really interesting, since it''s completely different from the ones in the Harvest Moon games.\nThe graphics are fancy, never seen that beautifil HUDs and GUIs.\nAnd most important: The characters are indivi', 'This game was abandoned do NOT buy, please try wonderful games like Fields of Mistria, Stardew Valley, or My Time at Sandrock for cozy sims.', 'Mostly Negative', 24.68, 4.42, 15.10);
INSERT INTO reviews VALUES (2449, 328270, 122, 'meh\n', 'Didn''t understand half of it. Too many plot holes and incomprehensible choices.', 'Mixed', 62.30, 10.13, 7.43);
INSERT INTO reviews VALUES (2454, 328470, 133, 'Used to play this bad boy in win 98 , good times', 'I played this on Dreamcast back in the day, so I was excited to play a version with better frame rates, controls, sound, more enemy types, etc., basically closer to how the game was intended without the limitations of the Dreamcast.\n\nIt''s a decently fun game, but as folks have noted, higher resolutions throw off your crosshairs quite a bit.  And for me, it crashes A LOT.  Sometimes it would take several attempts just to get it launched.  I''m about 70 minutes in, and it crashed midway through a l', 'Very Positive', 82.71, 1.95, 1.70);
INSERT INTO reviews VALUES (2455, 328500, 184, 'Potatoman is still missing to this day.\n\nIf you have any information, please contact your local police department immediately.\n\nThank you.\n\n', 'This is the only game i feel sort of bad paying $4 for, the game was fun sure but only like $.99 worth of content', 'Very Positive', 84.78, 1.52, 2.65);
INSERT INTO reviews VALUES (2458, 328590, 251, 'This game was pretty alright. Not much in the way of gameplay mechanics or puzzles - mostly a walking sim. But, I liked what I played enough - prolly a 5.5/10 for me; a bit above average, but barely so. I think that $20 is a steep price for it - I got it on a bundle, so the value was there for me. I also got stuck only once - and, that''s only because the way forward was a little miss-able (partially because it was different than just going into a door or exploring a door that was previously lock', 'Bad walking simulator with bad jump scares, incoherent story and short af.\n\nAlso: DOES NOT WORK WITH THE INDEX CONTROLLERS', 'Mostly Positive', 73.71, 1.85, 1.82);
INSERT INTO reviews VALUES (2464, 328730, 173, 'Does anyone here remember Bookworm Adventures? That was the best game PopCap ever made.\r\n\r\nNow imagine taking said peak, making it accessible to modern software, and adding some new upgrades and gimmicks to play around with. That''s Letter Quest.', 'Personally, I can''t recommend this game because when I played it I felt like I was just playing a mobile game I bought off the google play store or something. The setting is cute, the art is cute, but besides that it''s not very interesting. It''s also somewhat punishing where I think when you die you have to restart the level and early on (or the entire game) there''s no reliable method of healing. If you really want a game based around using spelling/words as a puzzle just go buy Words of Evil. I', 'Overwhelmingly Positive', 96.53, 9.83, 0.27);
INSERT INTO reviews VALUES (2466, 328760, 831, 'The Black Edition is good but I think that the BLACKED Edition would appeal more to the senses 😉', 'Juvenile, unfunny "humour". Gameplay manages to be at the same time complicated and boring.\nIf you like repeatedly typing 1, 2, 3, 4 on your keyboard, and if you think the mere mention of potatoes is hilarious, then play this game. Otherwise, don''t.\nI asked for a refund, even though I paid less than €1 for it.', 'Very Positive', 92.42, 0.75, 1.27);
INSERT INTO reviews VALUES (2474, 328940, 177, 'this game makes me bug tf out and has caused visceral rage even as a child when this was available for free on my crappy samsung galaxy. 10/10 would recommend if you like pretty pixel art and are slightly masochistic', 'Boring music, bland visuals that wash together, messy collision boxes, confusing redundant respawn mechanics when thats like the entire message of the game and a preachy one at that, where if a predator kills itself on spikes you are evil and are punished by being made a snake where you can no longer platform in this platforming game so presumable was just waiting to die to come back as something else (even though I had babies to respawn as to begin with).\r\n\r\nHonestly for such a simple game with', 'Mixed', 58.76, 1.90, 4.02);
INSERT INTO reviews VALUES (2479, 329050, 4967, 'For anyone that''s worried about the "The game won''t launch" reviews, this has either been fixed or only applies to certain hardware, I''m using a Geforce RTX 4070 super and an Intel core I9 12th generation and it launches just fine for me.\r\nIf you have troubles launching the game please comment your specs down below for anyone interessted to be able to check if the game will run for them.', 'Capcom needs to fix this game. Its ridiculous for customers to have to use hex editors just to make your game run. This honestly should be removed from steam until they fix this', 'Very Positive', 86.41, 24.43, 12.12);
INSERT INTO reviews VALUES (2480, 329070, 818, 'its a really fun game 10/10 would recommend but 25 dollars is a little much', 'Awesome one of a kind game concept that has a terribly unmotivated dev that seems to have made a game for him and his friends to mess around in. Dev has no plans to complete the game even after well over $20,000 in revenue :( can''t be recommending an extremely overpriced and unfinished mess of a concept build. This game has and never will go on sale so please go spend your $25 on literally any other game and you''ll be much happier.', 'Mostly Positive', 77.51, 0.58, 7.32);
INSERT INTO reviews VALUES (2482, 329130, 2344, 'Yeah it''s pretty good, I suppose.', 'it just kinda feels mildly unfinished and jank', 'Very Positive', 94.33, 1855.70, 19.40);
INSERT INTO reviews VALUES (2483, 329190, 110, 'very relaxing', 'Can''t believe that some people recommend buying this product and no other game. (I''m calling it a product because its a long way from a game). This is severely unfinished, it resembles the quality that comes from a game developer class playing around with flavour of the moment game engine. There is not much to do right now, except to fall to your inevitable "death" - which isnt in the game yet either. It is a playground being the point, well a playground should be fun.\n\nComparing this simulator ', 'Mixed', 66.36, 3.42, 0.53);
INSERT INTO reviews VALUES (2484, 329200, 118, 'Astray is a great addition to the first person horror genre fallowing in the tradition of games like Penumbra and Amnesia. The game was the perfect length for the mystery to unravel in satisfying chunks. The graphics were very atmospheric, and the game mechanics worked perfectly. At the end i was shocked to see the credits contained only two names, for that reason alone i would recommened this game as a true achievement in indie gaming, I have played hundreds of small  dev-team games, and this w', 'First half isn''t horrible, but it just tries so hard to be Amnesia, but this time you can clip out of the map, usually by accident, and die! I actually was able to skip a section I had no clue what to do in by jumping into the wall until I popped into the other side of the wall. And the AI is honestly more funny than scary. Getting it to chase you is practically invited since you''re the same speed and it loses aggro at the most stupid things, like a closed door or just going to a different heigh', 'Mixed', 62.71, 2.12, 2.50);
INSERT INTO reviews VALUES (2491, 329430, 4393, 'Realistic.  Varied map.  Good cardio, but the game will keep your heart rate up.  Good mix of character and abilities.', 'I like the game. I hope my hundred plus hours speaks to how much I liked it. The only thing is, the game is super buggy and can be frustrating. There are times that while on missions, despite there being multiple people with you, somehow no one helps you while you''re being attacked? The are also times when you go inside a room and whoever you are with follows you, but they just stand near the door making your character unable to leave and you''re just running around the room hoping they would mov', 'Mostly Positive', 78.17, 303.00, 102.78);
INSERT INTO reviews VALUES (2492, 329440, 2236, 'Sonic Lost World is truly one of the Sonic games of all time.  The best part of the game is when Sonic said "It''s sonic time," and then sonic''d all over the generic villain group.', 'Where Sonic Lost World excels in the occasional fun level, it is vastly overshadowed by the soulless cloning of Mario Galaxy themes and gimmicky level design. The bosses are creative at best and offensive at worst. This game, for the most part, is not worth playing.', 'Mixed', 59.88, 6.22, 5.52);
INSERT INTO reviews VALUES (2493, 329460, 164, 'There is literally NOTHING to dislike about this game,it has great music, fun gameplay, lot of achievements, cool concept, it has two of my favourite things: Dinosaurus and Aliens. Only thing what puts it down a bit, is to its one of the harder platformers, so if you want you can go whit something easier.', 'one of the worst video games ever made, no controller support', 'Very Positive', 92.68, 21.30, 0.10);
INSERT INTO reviews VALUES (2497, 329650, 149, 'Right now the only reasonable way to experience NAM is to run it through the EDuke32 environment, an external download which vastly enhances and unbreaks it.\r\n\r\nThis old game has RNG hitscan up the ass and every map is absolutely filthy with hidden preset mines and enemy spawns that you''re going to have to memorize. Set your expectations properly and you should be able to at least beat the game on Boot difficulty. Read a guide or two just so you understand the controls, the original game came wi', 'Controls are hard and can''t be adjusted.  Doom style game.  Not overly fun.  Just *meh*.', 'Mostly Positive', 74.50, 3.53, 0.23);
INSERT INTO reviews VALUES (2503, 329830, 752, 'Perfect example of how the derogatory term "walking simulator" should be used with extreme caution, and definitely not in this case : yes, you will just walk for approximately 1 hour, picking up a couple keys and reading clues, and yet the creator managed to tell an interesting and (very) sad and bleak story.  The music was also really good, the ambient tracks perfectly suit the overall atmosphere', '\nAvoid at all costs or get rekt by boring gameplay.\n', 'Mostly Positive', 79.26, 1.97, 4.00);
INSERT INTO reviews VALUES (2504, 329860, 783, 'Bugged, wont let me unlock last cat and 100 percent game. :(\n\nedit: Contacted mods and they fixed it for me, I''d still be cautious when you try and get the achievements but :)!!!', 'I loved the idea behind this game, but it made me extremely motion sick. I''ve been playing games across several genres, including VR games, and I usually do not have this sort of issue.\n\nIf it weren''t for this issue, I think I would like the game and would probably recommend it.', 'Very Positive', 88.12, 10.93, 0.57);
INSERT INTO reviews VALUES (2505, 329970, 1259, 'I enjoyed the game play, and truly did sink a lot of time into the game, but I also am a devout Catholic, and I don''t feel comfortable with the sacrilegious tone the new update took. If you don''t mind that, and enjoy games that tend towards being a bit harder, you''ll probably like this game. I''ll probably be retiring it, though.', 'Shallow.\nThe gameplay has about two levels to it, and then you''re through the discovery phase and everything is just repetition with different-colored sprites. Needs about two more years in the "feature add" phase before release - but wait, it''s already released! Guess that''s not happening, then.', 'Very Positive', 83.64, 102.62, 47.17);
INSERT INTO reviews VALUES (2506, 330020, 6855, 'Children of Morta is a very well crafted roguelite. \nSomehow they managed to make all characters feel good, balanced and fun to play, it also has some of the most beautiful pixel art I have ever seen, beautiful arts and incredible animations, great responsive combat, fun story and good soundtrack too.\nOverall, it is easy to recommend Children of Morta is you are into roguelites.\n\nNothing matters more than FAMILY- Diesel, Vin... Probably.', 'Co-Op Horribly Bugged. YOU WILL LOSE YOUR SAVE PROGRESS! BUYER BEWARE! \n\nPlayed for 2 and a half hours solo, Hopped in a friend of mine''s game to play.  He had JUST finished the prologue and unlocked multiplayer, we played ONE match and then he had to go.  I go back to find my save was overwritten with his!  All of my character''s progress GONE, levels, GONE. Was focusing on Linda, the archer, got her up to level 9, Now she''s level 2...   I don''t have it in me to start over.  I wish I''d seen a re', 'Very Positive', 89.00, 16.82, 5.88);
INSERT INTO reviews VALUES (2507, 330100, 151, '⣿⣿⡻⠿⣳⠸⢿⡇⢇⣿⡧⢹⠿⣿⣿⣿⣿⣾⣿⡇⣿⣿⣿⣿⡿⡐⣯⠁ ⠄⠄\n⠟⣛⣽⡳⠼⠄⠈⣷⡾⣥⣱⠃⠣⣿⣿⣿⣯⣭⠽⡇⣿⣿⣿⣿⣟⢢⠏⠄ ⠄\n⢠⡿⠶⣮⣝⣿⠄⠄⠈⡥⢭⣥⠅⢌⣽⣿⣻⢶⣭⡿⠿⠜⢿⣿⣿⡿⠁⠄⠄\n⠄⣼⣧⠤⢌⣭⡇⠄⠄⠄⠭⠭⠭⠯⠴⣚⣉⣛⡢⠭⠵⢶⣾⣦⡍⠁⠄⠄⠄⠄\n⠄⣿⣷⣯⣭⡷⠄⠄⢀⣀⠩⠍⢉⣛⣛⠫⢏⣈⣭⣥⣶⣶⣦⣭⣛⠄⠄⠄⠄⠄\n⢀⣿⣿⣿⡿⠃⢀⣴⣿⣿⣿⣎⢩⠌⣡⣶⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣆⠄⠄⠄\n⢸⡿⢟⣽⠎⣰⣿⣿⣿⣿⣿⣿⢀⣾⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣦⠄⠄\n⣰⠯⣾⢅⣼⣿⣿⣿⣿⣿⣿⡇⣾⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⡄⠄\n⢰⣄⡉⣼⣿⣿⣿⣿⣿⣿⣿⢸⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣧⠄\n⢯⣌⢹⣿⣿⣿⣿⣿⣿⣿⣿⢸⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⠄\n⢸⣇⣽⣿⣿⣿⣿⣿⣿⣿⣿⠸⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⠄\n⢸⣟⣧⡻⣿⣿⣿⣿⣿⣿⣿⣧⡻⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⠄\n⠈⢹⡧⣿⣸⠿⢿⣿⣿⣿⣿⡿⠗⣈⠻⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⡇⠄\n⠄⠘⢷⡳⣾⣷⣶⣶⣶⣶⣶⣾⣿⣿⢀⣶⣶⣶⣾⣿⣿⣿⣿⣿⣿⣿⣿⣿⠇⠄\n⠄⠄⠈⣵⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⢸⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⠄⠄\n⠄⠄⠄⠸⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⠘⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⠇⠄⠄', 'This game is abandoned by the developer.\nThe Java version is outdated resulting the game not starting up correctly, you can fix this by updating the version manually.', 'Mostly Positive', 72.19, 2.25, 0.90);
INSERT INTO reviews VALUES (2508, 330180, 115, 'Cool game got it less then a dollar', 'Poor control delay issues kinda hamper what I''d otherwise think was a neat game, if a bit.. derivitive of other.. better.. games.', 'Very Positive', 86.09, 0.37, 0.13);
INSERT INTO reviews VALUES (2509, 330270, 114, 'First 10 min impresion. I really like it i like 2d games. I was waiting for this game to come out. I only play with 1 charachter so far. I will try to update my impresion. But so far so good.', 'Do NOT buy this game, devs dropped it completely. Multiplayer still does not work.', 'Mixed', 51.75, 2.37, 3.93);
INSERT INTO reviews VALUES (2510, 330350, 279, 'Dont know why does this game have so many negative reviews, its a great game and it uses very little RAM so you can run it on the background and get steam cards while playing something else', '\nGameplay is really lackluster similar to flappy birds... Artstyle is really nice though but for a game like this there should be more focus put on decent controls - it would be a much better experience!\n', 'Mostly Negative', 22.94, 2.95, 2.57);
INSERT INTO reviews VALUES (2514, 330460, 365, 'This game is so much fun, re-playability is there with endless customisations.', 'Absolute buggy mess, went to go visit other planets in the same system only to find nothing but asteroids. Tried to go back to previous planet just to be told "you cannot warp to planets you already visited" and had to run off to another system that, in the end, was the exact same as the last one. No Story, No Direction, repetitive gameplay', 'Mixed', 66.30, 98.78, 8.10);
INSERT INTO reviews VALUES (2518, 330580, 653, 'Quite a fun game.\nNice enough diversity with its maps, a couple of different weapons to choose from, and playing as a shark can be pretty fun.\nWould recommend if you have a few mates to play with.', 'I couldn''t play the game, there was no one there.', 'Very Positive', 81.32, 6.63, 4.78);
INSERT INTO reviews VALUES (2520, 330620, 108, 'drama lol', 'I love strategy games and was exited for this game and buy this gamme. The game pace is too slow, repetitive and get boring pretty fast. Even on the fastest setting.', 'Mostly Positive', 75.00, 21.15, 2.82);
INSERT INTO reviews VALUES (2524, 330720, 146, 'Neat system where the player gives ''desired'' orders to units and then time passes intermittently as the units attempt to perform queued actions. Varied and relatively contemporary units along with detailed terrain/cover provide a rewarding play experience. \n\nGreat for playing slowly in the background through a day.', 'I bought this game and really wanted to like it, but the interface is absolute crap, the controls are clunky, nothing about the game is intuitive, movement of a single unit is a painstaking series of clicking and plotting, there are no hotkeys, everything is accessed only via a hidden right-click menu option. This game sucks, it is a total miscarriage and abortion.', 'Very Positive', 87.67, 34.40, 2.15);
INSERT INTO reviews VALUES (2526, 330820, 554, 'This game is so much more then just a visual novel, the amount of items and people you can interact with that give often extremely funny dialogue is insane and so much of it is completely optional. Plus I wasn''t expecting any voice acting let alone the game being fully voiced and everyone did a fantastic job, all this combined with great characters and a pretty compelling mystery makes this one of my favorite games. Also banger ost', 'The reason I didn''t finish the game were some of the characters. They''re such unlikeable, overused tropes.', 'Very Positive', 84.12, 29.30, 4.47);
INSERT INTO reviews VALUES (2527, 330840, 5321, 'I know this game is no longer available — at least not on Steam — but I still wanted to share my thoughts. Just a heads-up: even if it ever does make a return, it ends on a cliffhanger that will sadly never be resolved.\n\nI watched Game of Thrones, though I never made it all the way through. I mean, how could I not start? There are dragons! Even better, this game features the voice of female Hawke from Dragon Age — well, technically just in an extremely minor background role — but still, Dragon A', 'Like a lot of game of thrones media its just not the same anymore, loved it at the time but now can''t really play it anymore, especially with a very unsatisfying ending.', 'Mostly Positive', 71.58, 18.08, 58.02);
INSERT INTO reviews VALUES (2529, 330990, 132, 'It''s pretty decent.\n\nThe art is ok, the story is ok, the hidden objects are ok, the puzzles are ok, a few achievements are a headache, and that''s about it.\n\nIt''s not the best, nor the worst. If you''re not picky, you may enjoy it.', 'The hidden object scenes often have multiple items that match a clue but only one of them counts. It''s very frustrating. For example, for the clue "compass", they''ll mean a magnetic one, but also include in the scene the kind you use to draw circles.\n\nAlso the music gave me a headache so I had to turn it off within minutes.', 'Mixed', 59.09, 8.77, 3.67);
INSERT INTO reviews VALUES (2531, 331160, 804, 'Perfect game for my 1,341 euro pc', 'Didnt face issues running it on new hardware but the gameplay is boring af', 'Very Positive', 87.94, 17.28, 0.40);
INSERT INTO reviews VALUES (2532, 331190, 181, 'Pros: artstyle, soundtrack, and general tightness of the controls. There''s a good stealth platformer idea here.\nCons: Less a difficulty curve, more a difficulty mountain range that peaks and valleys at irregular intervals. Less a stealth game, more a precision platformer, emphasis on precision. Enemies spot you quicker than they turn around, but it''s really about the timed jumping and use of your cloak. \nPlay at your own risk. Mark of the NInja or Shadow Tactics, this is not', 'A game about jumping between platforms and avoiding enemy sight and cameras. There''s no clear instruction but you have an invisible ability and when it is activated, you move extremely slow and jump low so you need to be carefully timing the movements to avoid being spotted. Overall, this game feels plain due to simple mechanics and frustrating due to strict landing and timing control. By the end of each level I didn’t feel fun or satisfaction, only exhaustion.', 'Mostly Positive', 79.01, 5.42, 0.55);
INSERT INTO reviews VALUES (2533, 331200, 371, 'I touched grass', 'I spent more time on this game than the developers.', 'Mixed', 67.92, 0.43, 1336.97);
INSERT INTO reviews VALUES (2542, 331440, 751, 'WELL WORTH THE PRICE. Played for 5 hours, got every achievement. The game is royally challenging considering the permanent death unless you have a specific build set up for your character. If you just grab random gear on the ground and you''re generally inexperienced, you will lose fairly easy.', 'Just ran around one-shotting everything. No description as to what any of the stats do. No option to exit the game without force close.', 'Mostly Positive', 78.96, 5.58, 2.57);
INSERT INTO reviews VALUES (2546, 331480, 764, 'This game may not be perfect, but it''s beautiful in every sense. Although it''s relatively short, a game''s value isn''t determined solely by its length. What truly matters is the experience and emotions you feel during that time, and in that regard, this game feels like reading a truly wonderful storybook.', 'the game itself is alright... Played it four times, only to have it crash and lose all the progress.., would not recommend overall.', 'Very Positive', 89.79, 5.07, 7.62);
INSERT INTO reviews VALUES (2547, 331500, 1095, 'great goofy rts fun, fantastic with friends', 'Only a handful of maps. Barely any content in this game. No single player campaign or map editor to make more maps.', 'Very Positive', 84.84, 16.02, 0.10);
INSERT INTO reviews VALUES (2551, 331600, 2657, '5 dollars on sale is a steal but it has contoller issues. You want to get the most used community layout, edit that community layout, remap the RB button to the letter O, and then double check the remapped controls in the game settings. When you map your controls with the edited community layout, it will show keyboard bindings now, don''t worry about that, its normal. You will also want to configure the camera controls to the right analogue stick. You have now have a fully functional Pirate Warri', 'there''s been a bug from 2018/2019 until now and it never get fix at all. During the submit battle and conclusion war, the game either keep crash, or black screen, or keep going to main menu. Those people recommend to put on lower resolution and all bullshit it never work at all', 'Mostly Positive', 76.33, 1.23, 187.85);
INSERT INTO reviews VALUES (2553, 331650, 116, 'Bloody, stupid, brutal - all these adjectives were always automatically attached to everything where the word Carmageddon appeared.\r\n\r\nCarmageddon TDR (the death race) 2000 contains ten very different environments, each with 6 missions waiting for you. Simply put, two types of missions alternate. One type is a classic race with opponents and time for several laps, where you are additionally limited by time. The second type is some kind of special missions where you have to complete a task for wh', 'I have nothing to say about this game, however I can tell that the reviews that say "the opponents teleport behind you or in-front of you while at full speed" and if they''re racing, they "constantly teleport to get that 100% grip" are both true facts. Both happen off-screen btw with an exception that I''ve already just mentioned in the first sentence.', 'Mostly Positive', 75.00, 81.25, 2.27);
INSERT INTO reviews VALUES (2554, 331670, 1317, 'This does not come with friends in the box.', 'The last party pack you should ever get. The only game that''s really worth it is Drawful, but you can just buy Drawful 2 as a standalone game.', 'Very Positive', 91.34, 1.57, 1.15);
INSERT INTO reviews VALUES (2555, 331690, 434, 'https://steamcommunity.com/sharedfiles/filedetails/?id=1646766801\nhttps://steamcommunity.com/sharedfiles/filedetails/?id=1697103595\nhttps://steamcommunity.com/sharedfiles/filedetails/?id=1697461677', 'The first 2 hours are amazing. The first 2 chapters and the overall art-style of this game hooked me instantly. The soundtrack, the pixel art, the retro-style cartoon cutscenes and all those little pop-culture references are all well done, and they perfectly set up that 80s Americana feeling. \n\nAlas! That was the only good things about Crossing Soul. The rest you''ll get is a bland and uninspired adventure. It''s served with a disappointing story, that has nothing interesting to offer. The charact', 'Mostly Positive', 71.66, 9.15, 14.73);
INSERT INTO reviews VALUES (2557, 331750, 527, 'This game is like that scene where critic Anton tastes the first bite of ratatouille.', 'I cant get past the tutorial level, the laser machine where I have to line up the 3 BnL icons has a BUG', 'Overwhelmingly Positive', 95.64, 3.93, 0.43);
INSERT INTO reviews VALUES (2560, 331870, 2085, 'In Aer Memories Of Old we are reincarnated in the role of a young woman on a pilgrimage with the mission of healing the lands of the gods in heaven that have already been forgotten by a destructive corruption called the Void. In this game you will fly like a freed bird and walk with strength and courage on your shoulders through different locations where you will learn the history of this universe and also meet the supreme beings who reside in it. A short but memorable and meaningful journey int', 'AER: Memories of Old offers an interesting atmosphere, with a beautifully crafted art style and an immersive soundtrack that draws you into its world. However, its narrative fails to maintain that same magic, ultimately pulling you out of the experience. Given that flight and exploration are the core mechanics, it is surprising how unpolished the flying feels. This is something that should have been the game''s strongest feature.\n\nI genuinely wanted to love this game. I spoke to every character, ', 'Very Positive', 87.29, 23.17, 4.83);
INSERT INTO reviews VALUES (2562, 331920, 256, 'I can''t count the time I invested in this game. I owned it as a CD-Rom back in the late 90s, when the original game came out. Back when PetrolAir was called ArabAir and some voices were different. Airline Tycoon is by far no game for everyone. It can be repetetive and get boring to most people. But I love this game so much. Back in the days I sat at my PC as a young boy with my grandpa and we would play night after night until we owned every route with a couple of hundred aircrafts. It was a bla', 'The game has been broken for the past few years. It is extremely glitched and barely loads.', 'Mostly Positive', 79.69, 49.67, 21.38);
INSERT INTO reviews VALUES (2563, 331970, 175, 'Good game, been playing it for 20 years 👍\n\nIt suffers from all the pains of playing early 2000s games, but def worth it!', 'I like the idea, but the game is unplayablely slow and as far as I know there''s no way to change it in game or with mods. Shame because I WANT to like this but I''ll die of old age before I finish it.', 'Very Positive', 93.71, 30.80, 6.12);
INSERT INTO reviews VALUES (2566, 332200, 3845, 'It''s been many years and this game and its soundtrack still live rent free in my head. I''ll hear a song or random electronic noise that reminds me of the game and instantly feel nostalgic. It''s a really fun game that keeps you questioning everything you know about the in-game world. It also has a lot of extremely difficult optional puzzles / hidden areas which add to the game''s aura of mystery. 10/10!', 'Enemies are too bullet spongy which makes guns feel weak and makes backtracking tedious. Map is boring. Music is just okay. Overrated game.', 'Very Positive', 90.87, 43.73, 3.05);
INSERT INTO reviews VALUES (2568, 332260, 187, 'I Can''t Wait To Become a Mater National Fugitive.', 'I tried to change controls on both controller and keyboard but neither of them changed. I have scrolled through hundreds of the guides to try and fix it, but no luck(original controls sucks i hate them). Just wanted to try everyone''s childhood game but unfortunately, i couldn''t have a try.', 'Very Positive', 88.24, 10.17, 0.60);
INSERT INTO reviews VALUES (2570, 332330, 132, 'Criminally underrated.\n\nEverything from the controls, the level design, the music, the  perfect  difficulty; This is a game dev at the top of their game.', 'Unfortunately this game has a skipping audio / music bug that they were aware of back in 2016 but never fixed. The music is a large part of the game, using different audio layers depending on the action occuring on screen.\n\nIt is jarring when the music intermittently cuts out at different points and I can''t recommend it for this reason.', 'Very Positive', 86.36, 15.37, 0.15);
INSERT INTO reviews VALUES (2571, 332360, 106, 'if you are a beginner at animation i recommand this, has its own problems true but great for beginners and for simple sprite animation', 'Way too many bugs appears when you start to go deeper in the engine\n\nUnless you get it for at 50% off, do not waste your money with this below average software\n\nTry DragonBones, it''s better and free\n\nAlso the developers pretty much gave up on this software.', 'Mixed', 67.92, 1403.93, 417.47);
INSERT INTO reviews VALUES (2576, 332480, 187, 'I just got my steam deck and so far this is one of my favourite games to play on it in handheld mode. Phoenix Force is a bullet hell type game where you face endless boss battles. It is quite difficult, as you die in one hit, but as you progress through the worlds your phoenixes become stronger, not to mention you rescue new characters to play as. \n\nI am really glad that the phoenixes share a level, because power orbs are limited I feel like it would have given players no reason to try the new c', 'A really mediocre shmup with mouse controls and a level structure similar to Candy Crush Saga. The game feels and looks like a mobile game from its graphics, mouse controls (aka touch screen), and UI.\n\nThe level up system is so basic. Get currency. Press level up button. Get currency. Press level up button. Wow. So complex. Unga bunga no thought. It felt like it was built to be some P2W premium currency that they didn''t implement in this version.\n\nThe gameplay consists of fighting a boss or mult', 'Mostly Positive', 78.61, 12.03, 1.05);
INSERT INTO reviews VALUES (2577, 332490, 236, 'Amazing game. Well-designed, very few bugs if any, and loads of fun. Easy to pause if work or RL calls.', 'Nice graphics, but unrealistic ships armaments unless you customize the battles - why are there not historical warships  when there is plenty of available data.  Mostly a game of guessing ranges without range finders. Hard to tell a ship''s turning radius or expected placement after a move (inadequate distance/space markers on playing area). Really wanted s good naval simulation that did not require controlilng every aspect of a ship... this is not it.  Very sad.', 'Mostly Positive', 75.42, 23.03, 6.62);
INSERT INTO reviews VALUES (2578, 332500, 2711, 'Enjoyed it for what it was when it came out.\n\nShame it''s abandoned though... R.I.P.\n\nHonestly someone should buy up all these unfinished games with potential and bring them back rather than trying to do more sci-fi open world survival crafting games from scratch...', 'It should be a crime to still sell an abandoned game on the steam store.', 'Mixed', 45.81, 15.48, 4.10);
INSERT INTO reviews VALUES (2581, 332570, 7169, 'Hello during like 2015-2018 me and my best friend played this game all the time only 80 hours but that 80 hours was with him only and Oct 3, 2024 around 1:48 he shot and killed him self. I just want to thank the devs and the founder of the game for letting me spend 80 hours playing this game with him. His name was chandler waters', 'The Christmas update has ruined the game for me. Please remove the grinches. You can’t walk 10 without being killed by one.', 'Very Positive', 94.23, 83.80, 95.87);
INSERT INTO reviews VALUES (2583, 332610, 117, 'This game is very short if you play all day but it can be Hard at some points but keep trying and you shall succeed. At sorta random i was able to beat the game without giving up. The bosses were difficult (the spider was the hardest. The werewolf was a joke since i leveled my fire up. If you lvled ur  fire the bosses should be no hassle except for the final boss. Since you have to use the mech suit. Good job DarkFalzX you did a really good job on the game i enjoyed every bit of the game. It was', 'this is like every mediocre GBA platformer (if it''s even appropriate to call it that) that you saw on the shelf but never bought', 'Very Positive', 83.76, 11.10, 0.73);
INSERT INTO reviews VALUES (2590, 332790, 158, 'To briefly state the pros and cons of this game\r\n\r\n+ I liked the heartbeat sound when we were running and when we were close to or finished our energy bar\r\n+ The game gives us most of the necessary materials in abundance\r\n- There are very few NPC types in the game\r\n- I think it would be nice if we could see where the character is on the map\r\n- It would be nice if there was a save system', 'Silent Hill-inspired top-down game with repetitive design, flawed mechanics and poor enemy variety.', 'Mixed', 43.04, 3.43, 1.63);
INSERT INTO reviews VALUES (2591, 332800, 12667, 'Here''s my top 10 favorite fnaf character based on their gameplay\n\nNumber 10\nToy chica.\nShe come through the left vent and she flash you in the hallway I mean you flash her in the hallway.\n\nOk thats it', 'I feel there is a lac of big titty anime girls in this game, still turned me on tho', 'Very Positive', 93.16, 11.80, 14.15);
INSERT INTO reviews VALUES (2595, 332950, 523, 'the monster in the game', 'this game is so fucking bad it is not even funny you stay on a level for an hour then find the next one to be harder, you die to traps more than you die to the actual enimies and the last level there is a bear that got raped so much that her name is mother and she has like 50 children, not only that but she pops out babies on command, just showing how much of a hoe she was back in her high school days, she needed her stomache to stay open because instead of the normal 9 months to produce a baby ', 'Very Positive', 88.53, 7.22, 9.47);
INSERT INTO reviews VALUES (2599, 333210, 156, 'BIG MONSTER KILL CITY!!!!\n\nGOOOOOOOD MONSTER!!!!!\n\nSMASH!!!!! BOOM!!!!! POW!!!!! BANG!!!!!', 'Oh no, they say, he''s got to go\nGo go Godzilla~ ♪\n~Blue Öyster Cult\n\nIt all started in 1989. I know, I know. Another one of those long and boring reviews that start with old geezer talking ''bout ancient history. But it''ll all make sense, bear with me. Anyway. Like I said, it all started in 1989, when MAXIS released Will Wright''s Sim City. Naturally. I mean, it was only 1989 and MAXIS was founded by Will and Jeff Braun only a couple of years ago. No EA on the horizon for a pretty long time. The g', 'Mixed', 59.62, 3.47, 128.13);
INSERT INTO reviews VALUES (2600, 333250, 569, 'Played it a bit, it’s not bad.', 'For around 3 hours of gameplay, even 50% off is too expensive\n\nI''m probably being a bit harsh but it sums up what I remember of my experience playing this game.\n\nForward to the Sky doesn''t really break any new ground, in terms of graphics, combat, platforming, or story. Just looking at the screenshots, you can see it looks like maybe PS2 or even PS1-era - and all the best detail seems to have gone into the main character. The scenery gets old fast, the combat gets old fast, and the platforming..', 'Mostly Positive', 75.92, 6632.83, 3.12);
INSERT INTO reviews VALUES (2603, 333300, 978, 'I''ve played this game for about 30 years.', 'To preface, I love rogue-likes and have played some of the most arcane in the genre -- to include one of the most complex: Cataclysm: Dark Days Ahead. This love isn''t enough to overcome how much this game sucks. The experience is clunky AF. The UI is nearly unmanageable and includes no QoL. Frequently necessary meals must be made of LEAD, considering they weigh more than just about anything else in the game. What a frustrating, not fun mess. And to put it out there -- I was meeting a great deal ', 'Very Positive', 86.81, 915.28, 1.53);
INSERT INTO reviews VALUES (2608, 333420, 3068, 'Love this game . complete strategy. Lots of fun. Sad it''s no update. Give us Cossacks 4 Please !', 'DO NOT BUY IF YOU ARE USING AN AMD GPU \n\nAlmost all units are invisible and some animations doesn''t work so units moves while being frozen. This problem has not been solved for more than 4 years so it is easy to say that developers don''t care at all.', 'Mostly Positive', 78.10, 2243.72, 0.93);
INSERT INTO reviews VALUES (2609, 333430, 102, 'A crime scene investigation game where you gather clues, interrogate suspects, and piece together evidence like fingerprints, footprints, photos, items, and conversations - to solve key questions. The story is interesting and keeps you guessing until the very end.\r\nHowever, some slow-paced animations, such as waiting for elevators, taking the stairs or walking through long halls, can drag a bit since they can''t be skipped or sped up.\r\nAll in all, I enjoyed the game.', 'Этот квест можно описать только одним словом - убогий.\r\nПлохая графика и анимации, отсутствует элементарная анимация губ (все разговаривают с закрытым ртом). Он ощущается как что-то дешевое, слепленное на коленке.', 'Mostly Positive', 71.57, 16.18, 7.78);
INSERT INTO reviews VALUES (2614, 333600, 7683, 'CATS CATS CATS CATS CATS CATS', 'I bought this game thinking it was going to be really good because of the reviews. What I didn''t know is that this is actually not a game. You''ll just have to click and click to follow the story and that''s it, nothing else to do. I respect others opinions about how great this game is, but this just isn''t for everyone.', 'Very Positive', 94.10, 6941.92, 1.70);
INSERT INTO reviews VALUES (2615, 333640, 8914, 'I''ve never reviewed a game on Steam, but I feel compelled because the developers asked. They deserve it.\nQud stands on its own as a roguelike, RPG, and video game.\nQud stands on its own as a work of fantasy and science fiction.\nQud stands alone as a work of art. You can''t play the Mona Lisa, but you can play Qud.\n\nBrian and Jason, thank you. Your game is a major achievement of the human imagination. My life is better for it. Live and drink, water-sibs.', 'I''m sorry but these kind of games (also Dwarf Fortress and Rimworld) "create stories" like mid-2000''s web based plot generators. "A  entered  and  all your , so now your   is  and  ". Haha so rnadom, so unique - I mean, sure... but that level of storytelling is juvenile at best and AI-generated slop at worst.\n\n"A   attacked  so " is not character development; it''s just word salad.\n\nThe game''s systems might be interesting but the way some people sell it as a "a story / world / histories generator', 'Overwhelmingly Positive', 95.16, 451.02, 0.45);
INSERT INTO reviews VALUES (2622, 333880, 142, 'Extremely similar to the first title in the series. Turn based strategy game with units. A few minor improvements with the talents and some unique powers. I like the story that is here, however small it may be. There is unfortunately a grinding mechanic with the addition of caves for exp and gold that can take quite a bit of time, especially if trying to 100% achievements. All in all I would get it on sale, not a bad game but perhaps not worth 10$. It''s frequently on sales so if you might be int', 'While this fun little mobile game series is not bad, it is not worth your time in 2025. There are thousands of games better than this one on steam. \r\nAlso it has annoying bug with text centered and going out of bounds on top and bottom which is just unforgivable.', 'Mostly Positive', 77.46, 7.20, 5.92);
INSERT INTO reviews VALUES (2623, 333930, 840, 'One of my most favorite releases from Splash Damage. Only downfall was the card system. A balanced progression system with paid skins or something of that nature would have sustained this game better.', 'This is the most unbalanced game I have ever played do not pick up this game untill they have fixed the balance issues.', 'Very Positive', 82.26, 24.63, 4.78);
INSERT INTO reviews VALUES (2624, 333950, 3966, 'Worth the buy if you are a fan of Space Engineers. Great physics based sandbox with one of a kind mechanics.\nKeen Software originally started this game beside space engineers, they had a vision for both games and kept to that vision. After some time however, the player base of Medieval Engineers just couldn''t keep up with space engineers. So, Keen Software, instead of firing the Medieval Engineers team and ABANDONING the game, they combined the two teams together to work collectively on both gam', 'This game is unfinished, barely has any content, and is abandonware. A few years ago, Keen Software House announced they were done working on it and handed development over to a group of community members, who have seemingly abandoned it as well. On the day of writing this, 1/27/2025, the most recent update was in december of 2024, before that was june of 2022, both were minuscule patches and their steam "patch notes" are identical, akin to "fixed a few inventory and server bugs and improved per', 'Mixed', 49.90, 15.70, 19.52);
INSERT INTO reviews VALUES (2626, 333980, 1501, 'Yakuza but with a tighter budget and more fanservice. Fun by yourself, not fun around the homies or any close relatives', 'Interesting game and it looks like it''s fun. \nUnfortunately, this is a poor PC port which also happens to crash pretty often.\nHad to refund.', 'Very Positive', 85.61, 0.82, 0.75);
INSERT INTO reviews VALUES (2629, 334040, 808, 'My gambling addict friend said if I post a review and it gets 350 likes and 50 Awards that he will buy me a case of beer, some vodka and 1 kg of lemon So im just gonna leave this here.\nМой друг-игроман сказал, что если я опубликую отзыв и он наберет 350 лайков и 50 наград, он купит мне ящик пива, немного водки и 1 кг лимона, так что я просто оставлю это здесь.', 'Yikes.', 'Mostly Negative', 36.01, 0.23, 88.25);
INSERT INTO reviews VALUES (2630, 334070, 170, 'Unfortunately, this game is getting a lot of bad reviews. Most of them saying that the game is too short, and that there really isn''t a huge threat because the monster doesn''t really chase you and rarely shows up. That being said, it''s still a great horror game, and keep in mind that it was developed by only 5 people.  And for 5 people to create this type of horror game that goes on for 2 hours (only if you know EXACTLY what you''re doing) is impressive. Furthermore, eventhough the monster might ', 'Game is just not for me. I love puzzle games and psychological horror, but this is overwhelmingly a walking simulator with vague puzzles. I do like the room changes. Makes it hard to navigate and question your sanity. My general rule is that if I can''t get into a game or lore within the first hour, I probably won''t enjoy the rest. In this case, I game it nearly 2 hours before I got bored. Others may enjoy it, but it''s just not for me.', 'Mixed', 62.94, 9.25, 1.68);
INSERT INTO reviews VALUES (2632, 334120, 589, 'I was a huge fan of clay animation from childhood. I especially remember “The Neverhood,” which had a big impact on my growing up. I really enjoyed playing Armikrog, despite a few moments where there were bugs in the gameplay. It was an amazing experience with not boring puzzles and a whole storyline. I cannot imagine the amount of work that was accomplished by the developers. Thanks to the developers for the time travel experience back to childhood!', 'As much as I love point-and-click games and stop-motion animation, I''m afraid this game just doesn''t cut it for me and it probably won''t with you either. Take my advice: Avoid this game altogether and play The Neverhood. Sure the game''s out of stock everywhere and the developer doesn''t even exist anymore, but if you can somehow find the old files online, you can get the game working on your PC no problem with the help of ScummVm.', 'Mixed', 60.78, 5.27, 6.35);
INSERT INTO reviews VALUES (2634, 334190, 141, 'Fun platformer! Controls are a bit stiffer than they should be, and it would be nice to aim at least upwards, but it still plays well and is for the most part a fair challenge. Only serious complaint I''d make is that you can''t play as Finn or the priestess in single player, only in co-op.', 'Not recommended. There are better games out there. I guess this feels more like a sega game or arcade game than an nes game to me. I don''t care for the throwing infinite weapons as fast as possible bullet hell style for a side scroller game. Makes the throwing mechanic kinda useless when you can just spam the x button constantly.. also looks weird when you swing your weapon and it throws ninja stars constantly or whatever the weapons are.  Maybe if I played it a bit further I might feel differen', 'Mostly Positive', 75.18, 3.42, 0.72);
INSERT INTO reviews VALUES (2635, 334210, 145, '★☆☆☆☆\n\nUndercooked Orcs Must Die! clone stylised in 50s US comics. Unreal Engine makes it look even cheaper than it is. Not deep, but have unique features like full commanding of summoned troops.\nDevs probably ran out of money and gave up In the half of the way, so game balanced poor. Beatable in singleplayer due to easy upgrades swaps, but most players didn''t pass further 7 level.\n\nIf you are advanced OMD fan then it''s good training ground while you waiting for Robot Entertainment killing your ', 'Crashes sooooooo much, within 4 hours it crashed 8 times between 4 people. Fun enough but cant recomend.', 'Mostly Positive', 75.86, 9.88, 4.73);
INSERT INTO reviews VALUES (2636, 334230, 24431, 'Play this game if you are into politics. Basically what you do is lying and gas lighting someone. Highly recommended. 9/11', 'I''d like to say first that I used to play this game all the time back in the day when it was a free browser game. It used to be a lot of fun. Now it''s dead. You will sit in queue forever, and a ranked game will never pop. Your only option if you ever want to play the game is to go to ranked practice. Coordinated groups will go into the lobbies and take turns leaving seconds before the game launches to stall the lobby indefinitely. The same accounts keep doing it, but the devs/mods don''t ban them', 'Very Positive', 88.16, 88.22, 0.35);
INSERT INTO reviews VALUES (2642, 334310, 405, '7/10 Quite a nice strategy/tactics game. I had enough fun!\n3 interesting campaign missions. I''m gonna buy the DLC, to play the other 2.\nMy subjective "fun" grade is 7/10 (which is quite good, but not totally at the top).', 'way too grindy, there near no strategy to the game your ever stronger them your enemies and can defeat them or your not and trying to beat them is a wast of time.', 'Very Positive', 81.23, 100.20, 28.25);
INSERT INTO reviews VALUES (2646, 334420, 570, 'This game barely gets a thumbs up from me, mostly because of its fresh concept, great art, and nice music. However, the core issue is that the game is 90% luck. No matter how skilled you are, you’re constantly at the mercy of random events that dictate your success.\r\n\r\nYou can spend hours capturing new ships, researching tech, and gathering resources, only to have it all wiped out by an arbitrary event that drains your fuel or resources, leaving you stuck in a solar system with no way to recover', 'It is 100% random. This is not a game system. It is just a random outcome generator.\nI know about probability and managing odds. This is not it. You can go to a planet rich on fuel have a random event destroy your probe and now you cant get fuel and you are stranded in space. Game over.\nPersonally I do not get the appeal. \n', 'Mixed', 65.79, 28.45, 1.82);
INSERT INTO reviews VALUES (2650, 334540, 881, 'BattleTech, Robotech, Mechwarrior & Heavy Gear...What do they all have in common? They are all glorious & have no (official) VR modes. That''s a disappointment. Then there''s Vox Machinae. This will do.....', 'Couldn''t get through the excruciatingly slow tutorial and subsequent forced interactions around the ship. I did eventually find there''s a "skip the story go to mission" but it really didn''t help much as then you''re just slowly plodding around in a mech and getting lines delivered poorly to you. Also how many teeth do humans have in this universe, cause it seems like a LOT.\n\n', 'Very Positive', 88.65, 11.43, 0.67);
INSERT INTO reviews VALUES (2656, 334850, 130, '1931: Scheherazade at the Library of Pergamum\n\nHas a total of 10 trading cards.\n', 'I really enjoyed the story from what I have played in this visual novel. My issue on why I am not recommending this game is because I kept failing every check and then kept increasing stress and then back to more failing checks and it became frustrating when I felt like no matter what quest I was doing I could not pass any checks. Maybe I was doing something wrong but I just could not do anything to get any check to pass.', 'Mostly Positive', 70.77, 1.88, 1.97);
INSERT INTO reviews VALUES (2658, 334940, 1649, 'I have beaten this game 3 times on the Switch, I adore it. There is no other game quite like Yoku''s Island Express, and that makes me very sad.\n\nSo sad I bought it again on PC just to support to devs and type this and say, make a sequel! D:', 'It´s a really good game for those who like pinball, so it probably won´t be for me. I don´t even know why I bought it.', 'Overwhelmingly Positive', 96.60, 0.92, 1.45);
INSERT INTO reviews VALUES (2661, 335000, 1334, 'it is like siberia, you get on a train towards adveture', 'Graphically interesting, but hampered by sub-par worldbuilding and dull gameplay.', 'Very Positive', 92.88, 3.97, 3.68);
INSERT INTO reviews VALUES (2664, 335070, 480, 'After years of having RC cars on and off. I''m finally getting into the hobby. Been playing this for a few months, and even with a 360 controller, I have gotten used to throttle input, steering into corners, jumping and balancing. Very useful. My only issue is the cars are so fucking DATED the tracks are DATED. They need to open this up for mods or AT LEAST make it possible for the community to make tracks. The developers do not understand. If you make this MOD friendly, people will buy it becaus', 'depth perception is wierd and I dislike the microtransactions, to play it one even has to build their own gamepad adapter because the real adapter has been discontinued for years, with they actually updated the game instead of filling it with more microtransactions, mod support would be nice too', 'Very Positive', 84.79, 26.77, 2.73);
INSERT INTO reviews VALUES (2666, 335100, 119, 'I could have sworn I wrote a review already. Why? Because I fucking love this game. This game is so goddamn fun to play with a friend, I love it so much. Sadly I believe that connecting isn''t really possible anymore. I might be wrong though! If it''s possible, then get this goddamn game, it''s fantastically fun!', 'Dwarf Tower is a minimalist competitive building game, where you try to ruin your opponent''s tower while keeping your own stable. It is okay, and it is only a dollar, so it might be worth checking out. I played it a bit, tried out some different strategies.\n\nI''m mainly downvoting this because I personally don''t want to play it again. I don''t think it has aged well compared to similar games. Also the achievements are apparently out of order, so probably check the discussions if that''s a concern.', 'Mostly Positive', 71.43, 7.42, 1.37);
INSERT INTO reviews VALUES (2667, 335120, 136, 'Serpent in the Staglands is a very good, traditional CRPG.  It took me a while to get a handle on the game''s mechanics, but it was worth it because the game was well made.\n\nI heavily relied on the Steam guides written by other gamers.  The guides helped with the learning curve quite a bit.', 'Nah. I get wanting to make your game "old school" and stuff, that''s why I bought it, but it shouldn''t mean it''s clunky, buggy and just plain tedious. Targeting sucks, my characters can''t remember the order I put them in, the pathfinding is weak, terrible save/load times, just plays like a brick in general. And I get the "our game is difficult" gimmick, after having my whole party wiped out by a fox (oh, wow, yeah, super difficult, super oldschool) I managed to familiarize myself with the combat/', 'Mixed', 60.29, 63.02, 12.77);
INSERT INTO reviews VALUES (2668, 335190, 206, 'QP stole my liver again', 'so this is a short game, with a lame story. nothing real funny, feels like wannabe pokemon, but with a dnd twist. \r\nits quite a short game overall UNLESS you want all the achievements.. \r\nhow long does it take if u wang the achievements? oh u know could take 3 hours .. could take 500 hours!!!!!!!! depends on your RNG... hope u like grinding......', 'Very Positive', 85.44, 7.65, 27.00);
INSERT INTO reviews VALUES (2672, 335300, 30905, 'Unpopular opinion but Dark Souls 2 is my favorite game in series.', 'Despite beeing darksouls, it feels like a bad darksouls clone. Everything bad about the series is fully there, but everything good is just clunky copy. I really wanted to like this game, but I just cant.', 'Very Positive', 83.05, 131.45, 8.43);
INSERT INTO reviews VALUES (2684, 335670, 9797, '- Saw a youtube video recommended in my feed.\n- Bought game at 11 p.m. in a Saturday.\n- Thought I will just take a quick look to the game for about 30 minutes.\n- Finished the game in one session.\n- Slept at 10 a.m. the next day to understand more about this game.\n\nGame was not bad.', 'I really like the idea of the game... but going through the actual execution of it is too painful to bear.', 'Overwhelmingly Positive', 95.76, 12.50, 22.27);
INSERT INTO reviews VALUES (2688, 335790, 315, 'As a guy who loves lexicography (the study of dictionaries) this game was exactly what I wanted. It spits out obscure words I will never use ever in my daily life, not even in scrabble, as they are not in the collins or merriam-webster dictionaries. If you want to play a fun rpg game, this is not it. This is a masochistic crossword puzzle. Whenever people say there is no word for the day after tomorrow, and make fun of defenestration for being present in the language, I am quick to make them reg', 'Uncomfortably tiny window on 4k monitors that can''t be adjusted. No fullscreen mode either.\n\nThis game was available from 2014. The developer had released another game in 2023, so there is no excuse as to why the issue with this title has not been resolved within those 9 years.\n\nI felt it necessary to post this as a warning as the game is still up for sale.', 'Very Positive', 80.00, 9.15, 0.08);
INSERT INTO reviews VALUES (2690, 335830, 203, 'I don''t get why the reviews are mixed; the price is a little high for what Distant Star is, but it''s a worthwhile sale purchase if FTL makes you want to play a similar-but-fleet-oriented-strategy game.  It''s pretty straightforward, but the variety of ship classes helps with replayability, there are lots of solid combinations to play around with, I like the ship designs, and I really like the quests that reveal that you are not necessarily the good guys in this war.  From a practical perspective,', 'Game has a few good Ideas and seems to be Interesting and fun at first - but this drops really early into the game. Engagements often take to long and are most of the times longer then they should because of bad design decisions. For example the escort mission - you have to escort a transport ship into a station. The transport ship stops everytime enemies appear and just stands still, without any good reason why. There is also a Circle around the point where they arrive, indicating that they are', 'Mixed', 62.07, 85.15, 0.83);
INSERT INTO reviews VALUES (2694, 335920, 114, 'Absolutely charming little musical adventure.', 'Boring, repetitive, easy, short and pricey. Kids at ages 7-8 may enjoy but not for adults.', 'Very Positive', 90.35, 2.98, 0.68);
INSERT INTO reviews VALUES (2699, 336060, 326, 'Classic jet fighter (Star fighter-type)  platform. Cool system of turning kills to cash and letting you build your fortune on skill.\r\n\r\nUsed to play this as a kid. Thank you for bringing back my childhood on steam!', 'Paid for, downloaded, installed. Tried to play but game only uses keyboard - no mouse. No way. Requested refund.', 'Mostly Positive', 73.31, 6.70, 0.08);
INSERT INTO reviews VALUES (2700, 336080, 282, 'Very unique approach to a war game.  Easy to learn and every game starts with a slightly different map so you get a new experience each time.  I was really pleased with it.', 'It''s just boring. Feels like a low-budget early 2000''s game you''d take to CEX after 30mins gameplay.', 'Very Positive', 80.85, 83.77, 0.35);
INSERT INTO reviews VALUES (2703, 336130, 512, 'I had to really mull over what score to give Shardlight, more than I usually have to at least. On the one hand, this is a truly beautiful game, maybe Wadjet Eye''s prettiest game. The background and portrait art is sublime, some of the best I''ve seen in a point & click game to date. The music is excellent too and the voice acting is the same high standard you''d expect from Wadjet. Storywise, Shardlight is nothing if not engaging, with a setting that seems a touch derivative at first, but soon rev', 'This game was visually appealing and had a female protagonist. In the intro, I thought we were going to get good writing. Unfortunately, the writing ended up being the worst part of the game. The protagonist was inconsistent to the point of absurdity. I could not believe I had to do the things required by the game''s plot, especially the way she interacted with the villain.', 'Very Positive', 89.45, 4.27, 7.28);
INSERT INTO reviews VALUES (2704, 336150, 463, 'This game it has a story for me. I wanted to buy it long time ago, that time was a lower version. Finally I was able to get my hands on it, and I love it.', 'I''D RATHER BUY WINRAR!!', 'Very Positive', 80.56, 971.30, 0.13);
INSERT INTO reviews VALUES (2710, 336240, 349, '　\n　 O\n　ЯE\n  　H', 'Great concept but again ... another game with a weird control.', 'Very Positive', 83.67, 6.02, 2.08);
INSERT INTO reviews VALUES (2712, 336300, 205, 'Good enough? Despite its weak moments. Sadly, suffers from some of the same issues other city builders ail.', 'Bought this game due to the recommendation of people who liked games such as Ceaser and Pharaoh. This game was fun for a bit, but after awhile I realized I was tuning out and just letting the game continue at speed 3 while I waited for "X" to happen. \n\nThe gameplay is okay, but you''ll spend most of your time trying to debug why your supply chain isn''t giving a resource to the right building when you have 50! of them available.', 'Mostly Positive', 79.51, 7.62, 8.45);
INSERT INTO reviews VALUES (2714, 336420, 127, 'Good, old Abandoned Game. Can still be fun solo to a point. can make achievement progress on 3 of the 4 classes solo, though will need at least 1 person for the healer, better with a group of friends. Hero Tower defense, Limited Maps,classes and characters, but i enjoyed whats here. Pick it up if you have buddies and need a new game to play occasionally.\nBuy it on Sale, 3/5', 'This game really is a much needed break from the regular arena brawlers and games that are played frequently.', 'Very Positive', 86.61, 76.67, 13.35);
INSERT INTO reviews VALUES (2717, 336610, 266, 'A classic from my childhood. A bit hard to play nowadays, but nonetheless enjoyable. Great soundtrack as well.', 'While interesting.  The game was just too old for me.', 'Very Positive', 87.97, 17.13, 9.48);
INSERT INTO reviews VALUES (2728, 336940, 157, 'Played it a bit, it’s not bad.', 'Remember trying this back in the day and decided to pick it up again. Quickly remembered why I dropped it. The game implies you''ll be battling enemies with a bunch of weapons but in reality weapons are rarely ever found and break quickly. Levels are long (up to 20 minutes sometimes) and with some having chokepoints there''s very little margin for error when you die in one hit.\n\nAnd God is it frustrating when you have to restart. Death feels less like ''well that was a silly mistake I can learn fro', 'Very Positive', 82.80, 6232.07, 4.63);
INSERT INTO reviews VALUES (2729, 337000, 15798, 'An incomplete masterpiece, i cant even imagine how good it could be if it was in the better hands, incredible level design , god i just love these IS games.\nAnd Fk Square Enix, for it ruining every game that i love.\nR.I.P.', '\nThere are two things you can do to make your players angry.\nThe first is to have an abrupt, unceremonious ending with no closure and the second is', 'Mostly Positive', 74.86, 33.50, 5.28);
INSERT INTO reviews VALUES (2730, 337040, 112, 'If you enjoy strategy games that pose varying levels of difficulty (if sentinels are involved then it gets a lot tougher) then this may be a game for you.  Personally, the custom character creation is my favourite part of game.  Then comes the fact that every level you encounter has a COMPLETELY different layout, unknowing of what may lay behind every door and if the decision to open a door or blast open a door may:\n\n1. Get your Deadnaut ''decapitated'' by a sentinel.\n2. Get your Deadnaut dragged ', 'I really, really wanted to like this game. I love the unique UI and play style. I love the concept. I typically love rogue-like games. It has a lot of cool quirks. It just checks a lot of boxes.\n\nHowever, for all the excellent design, it seems like it''s just RNG about whether or not you succeed. You don''t carry anything forward for winning or succeeding, so you never "evolve" your strategy. My best runs so far simply involve strapping on the heaviest armor I could find and equipping the simplest', 'Mixed', 65.18, 23.20, 6.97);
INSERT INTO reviews VALUES (2731, 337070, 257, 'I recently upgraded my gaming rig to 192 GB of DDR5. This may seem to be overkill, but I remembered this program existed. While NVMe offers considerable performance, it obviously doesn''t compare to a RAM Disk.\n\nSo this software DOES work, you just need enough memory to actually be able to use it. Unfortunately, it does appear to be abandoned at this point, with the last update being released in 2018, and a feature that still hasn''t been added, which is the "Dynamic Drive Size" feature.\n\nIt allow', 'I have to manually remove the symbolic link for a game if Dimmdrive doesn''t shutdown cleanly. Seems to happen due to a bug sometimes as well. If you don''t manually resolve the issue no number of Dimmdrive restarts will fix the issue as recommended by the error message.\n\nAlso doesn''t work for workshop items.\n\nIf I have to manually mess with the symbolic links myself then I don''t need this app.', 'Mixed', 58.75, 30.90, 29.58);
INSERT INTO reviews VALUES (2732, 337150, 1043, 'pros: don''t have to set all the cards up, workshop items\ncons: can''t cheat', 'I really wanted to enjoy this game. Tried for a long time to unlock variants permanently only to have some of them be straight up not working. Today was the last straw. As of today, I can no longer recommend this game. It is no fun alone, no one I know wants copies, and AGAIN, I am tired of RNG being the only reason I''m not unlocking things.\n\nI rather it be use X to beat Y at Z or groups or teams or something.', 'Very Positive', 93.29, 27.15, 50.83);
INSERT INTO reviews VALUES (2735, 337270, 131, '?#&‼ it', 'sooooo boring. not worth a dollar.', 'Very Positive', 83.97, 12.13, 0.20);
INSERT INTO reviews VALUES (2738, 337320, 12863, 'Been playing since 2016, very good game, quite solid with plenty of options be it for a challenge or just to unwind and blow off steam, if you are considering a purchase, would very much recommend, its worth every penny.', 'unblur penis', 'Overwhelmingly Positive', 95.86, 1146.93, 5.50);
INSERT INTO reviews VALUES (2739, 337340, 4756, 'Thank you for being there for me when I was lonely in the past.\nThank you for watching over my humble life in the present.\nThank you for helping me learn to love myself in the future.\n\n\n실수와 후회로 점철된 내 못난 인생을\n아름답고 소중하게 사랑하는 방법.', 'This was just boring. Overstayed its welcome. I wasn''t even half way when I wanted it to end.\nFelt more like an experiment with a game engine than a good game/story. \n\nShame really, To The Moon is one of my favourite games.', 'Overwhelmingly Positive', 98.17, 5.92, 9.35);
INSERT INTO reviews VALUES (2740, 337350, 263, 'ecstasy', 'It''s a well-crafted game, but there are so many variables that its hard to say any victory is truly yours. A lot of the times it felt like I was playing a level until my muscles contorted and the game played out in such a way that I was able to get to the end. Stopped playing at Mercury because it stopped being fun, don''t know if I''ll return.', 'Very Positive', 94.68, 0.78, 2.68);
INSERT INTO reviews VALUES (2741, 337360, 215, 'It is much more interesting to play it through a smartphone or tablet, but not on a PC.', ' Review after 100% achievements = don''t buy it.', 'Mixed', 57.21, 0.45, 77.65);
INSERT INTO reviews VALUES (2745, 337490, 179, 'Interesting. I think this is the first puzzle game where I really questioned if I actually solved the puzzle correctly. Don''t get me wrong, I LOVE the mechanics of this game and art style isn''t bad. But there seems to be...a tendency to feel buggy. I managed an entire playthrough with only a few eyebrow raising "was that a bug or an intended mechanic" moments...except at the end when I got softlocked (I think?) during my New Game+ playthrough. Except somehow I already got the New Game+ Completio', 'bug riddled game', 'Mostly Positive', 76.54, 1.68, 3.65);
INSERT INTO reviews VALUES (2749, 337680, 108, 'It''s the Star Wars Armada Miniatures game on the PC and it''s great.\nI''ve played the first 3 missions and found it really interesting.\nYou can rebalance your shields, use special abilities (missiles so far), aimed fire or auto fire for your normal guns and there''s firing arcs that you need to position the enemy in while trying to position yourself outside the enemies firing arcs as much as possible.\nTurn based combat where the decisions are made and then the results are played out for a set perio', 'For a tactical game, I''m not seeing alot of tactics...\r\n\r\nI don''t want to be down on this. It''s a fresh enough setting that sees us fighting back against chitinous horrors, not on the ground a la Starship Troopers, but instead in space against hordes of starfaring bioships.\r\n\r\nThat is very, very cool to me...but it doesn''t make up for the, I''ll say lack of information. The user interface is clunky as sin and I literally couldn''t tell everything that was happening with the ships, whether mine or ', 'Mostly Positive', 77.78, 5.83, 3.67);
INSERT INTO reviews VALUES (2751, 337720, 153, 'Genuinely left this game feeling inspired and a bit more enlightened!\r\n\r\nThe brilliant thing about this game is that, despite the epic quest you go on to uncover ancient secrets and overthrow tyrannical governments, ultimately it''s all in service of fixing a nice person''s house, which feels just as important as the other stuff. You can''t fix the Underhome without saving the Isles because the problems with the Isles ARE the problem with the Underhome, just like all of the people of the isles are ', 'A caveat: I don''t like adventure games and I never will. But some I dislike less than others, and this isn''t one of them.\nThis is a time-capsule of early 2010s British leftism. Expect constant talk about austerity, rebuttals of the "poors are just lazy" argument, and references to people like Margaret Thatcher, Tony Blair, and Angela Merkel. Expect clumsy, juvenile British "humor". If the words ''silliness'', ''whimsy'', ''quirky'', and ''lol-random'' fill you with dread, come no closer.\nIn some sense t', 'Overwhelmingly Positive', 95.42, 4.05, 2.18);
INSERT INTO reviews VALUES (2755, 337850, 184, '500 mb game that is truly greater than 200 GB modern games. Need I say more?', 'First off: I want to say that if you enjoy exploration, then you should prob get one of the Avernum games. Although I personally enjoyed Avernum 1 more, that was simply because Avernum 1 was my first Avernum game. However, if I were to start over, I''d probably just go straight for Avernum 2 as it has a more interesting story. Now onto the actual review:\n\nIt suffers all the issues from the first game, except this time I''m no longer really exploring as much as I''m trying to get through the story a', 'Very Positive', 92.39, 65.32, 16.82);
INSERT INTO reviews VALUES (2758, 337930, 442, 'There is so much emotion in this story. It''s one of my favorites I adore how it can change from silly to dark so easily. It deals with some heavy themes, but I do feel they are done well.', 'I have tried to play this game so many times and it just doesnt work. ive tried everything that i can think of and it just doesnt work. does anyone have a fix for this? i dont want to have wasted 30 dollars on this. i love this developer but its just not letting me play the game.', 'Very Positive', 92.31, 181.42, 0.35);
INSERT INTO reviews VALUES (2765, 338060, 134, 'Peak', 'They won''t fix the game.\nEvery times I finished one game,it''s restart all the progress.\nOption doesn''t work every times when I clicked its  the game got error,\nand dev doesn''t fix anything.\n\nPS : there will be touhou mahjong version I will wait for that one.', 'Mostly Positive', 73.13, 0.43, 1.83);
INSERT INTO reviews VALUES (2773, 338140, 274, 'Unlike GTA V, all houses in this game are accessible.', 'unplayable. i dont mind dated visual, but its just unbreable when its keep crashing in midd battle. shame though, its have all the charms that make old game appealing.', 'Mostly Positive', 74.45, 22.90, 5.87);
INSERT INTO reviews VALUES (2774, 338170, 2076, 'Great Game, GAME SUCKS', 'The closest I''ve ever come to suicide.', 'Very Positive', 92.24, 8.25, 5.30);
INSERT INTO reviews VALUES (2775, 338190, 110, 'this reminds me of my irl ex boyfriend idk why even tho we didnt play it together or anything', 'Meh...', 'Very Positive', 86.36, 2.47, 0.22);
INSERT INTO reviews VALUES (2780, 338320, 189, 'Great little game. Highly recommended if you''re into oldskool RPGs and looking for something small, different and fun. It needs a second part!!!', 'Pixel Heroes was pretty fun for the first hour. But it became very repetitive. Every fight is basically the same. There''s just not enough meat on the bones here. I''d love to see a sequel though, with improved graphics and UI, and more gameplay.', 'Mostly Positive', 71.96, 48.42, 1.17);
INSERT INTO reviews VALUES (2783, 338390, 1473, 'This is really overlooked, but great RPG! i am blown away from how amazing the world, the lore, and the story is. I am quite frankly astonished that more people haven''t heard of it. it really do deserve more hype. Yes it''s a little buggy, but even with that the RPG elements shines through! and the atmosphere is amazing!  The game is a little bit janky, but full of heart. so get the game! it goes on sale all the time!', 'It would be nice if there was a warning on the steam page about the incompatibility with modern PCs.', 'Mixed', 68.64, 30.73, 0.10);
INSERT INTO reviews VALUES (2792, 338800, 182, 'playing this game for 20 years. Super fun.', 'I want to recommend this game but it crashes constantly on modern computers. I can play games like Cyberpunk on max settings but I can barely play this game.', 'Very Positive', 80.22, 3.65, 1.85);
INSERT INTO reviews VALUES (2801, 339040, 285, 'this is such a great God of War sequel, it perfectly picks up at the end of God of War with Kratos becoming in new God of War after defeating Ares, and beginning his revenge against Zeus, help help help help help help help help help help help help help. This is such a great sequel to Portal, this gameplay and physics are are as good and maybe even better than the original, Wheatly is the best part of this game.', 'The Goose Chase on hard mode is more challenging than any Souls boss fight.', 'Mixed', 66.32, 2.83, 3.57);
INSERT INTO reviews VALUES (2805, 339130, 206, 'Just how I remember it from years ago. Paid for this one as a thank to the developer.\r\n\r\nDo take note that for ultrawide resolution, the game appear to be working but it''s impossible to play since things will be appearing outside the field of view and impossible to click on them.', 'For the seasoned fan of point-and-click graphical adventures, this game could provide a reasonable morsel to tide you over between other releases. It was entertaining enough to play for the time it lasted, but it''s short (about two hours), the voice acting is abysmal, and the story is not particularly gripping or compelling. The great mysteries of the planet never really get plumbed, many of the puzzles have solutions that strain plausibility, there''s an awful lot of pixel hunting (the only part', 'Very Positive', 90.78, 2.65, 2.45);
INSERT INTO reviews VALUES (2807, 339190, 404, 'This was a neat game to get into. The premise was very interesting. It is a little slow at the start, but kind of hooked me after that. I was very curious to see what was behind the event that shattered their world. The ending is a bit of a cliffhanger, but it didn''t leave me frustrated. Things were explained pretty well about the how and why of what was happening, even if we didn''t get to see whether or not a good outcome was able to be obtained.\n\nNow, knowing from the start that it is supposed', 'Pros:\n- Interesting story.\n\nCons:\n- Puzzles that lead nowhere, some puzzles can''t be solved and are simply meaningles headache;\n- No ending.', 'Mostly Positive', 75.50, 7.15, 5.55);
INSERT INTO reviews VALUES (2808, 339200, 645, '7/10 zelda clone. Boss fights arent great. Mind you any reason I spawn with half hearts after dying? So everytime I die I have to scrounge for hearts in pots that barely drop just to try the fight again. Nothing super unique in the game. Not really challenging either.\n\nOtherwise its fun exploring and a decent game to play for the length it is. It shines in some ways while others dont. I think the world could have been more open/less linear and more exploring in any order.', 'I was enjoying the game until I encountered a game-breaking bug that made one of the puzzles unsolvable, which clearly demonstrates a lack of playtesting.\n\nNormally this wouldn''t be too terrible, I''d just reload a previous save, but I can''t because this game only has autosaving!\nThat means that if I want to complete the dungeon I''d have to replay the last 10 hours of content!\n\nNeedless to say, I''m incredibly annoyed, and therefore won''t be recommending the game or even bothering to review the ga', 'Very Positive', 80.00, 16.55, 10.35);
INSERT INTO reviews VALUES (2809, 339210, 105, 'gg', 'This is a very old game so cannot expect much. But for those who want have an experience of playing firefighting game. Don''t play this. So much clicking manually and even simple action like extinguish the fire cost you 2-3 click to start from picking up the equipment to connecting the hose then looking at the fire next to you until you click extinguish it. Fire on the high building is much more terrible some: connecting to dry raiser, getting divider climb up and down the fire ladder and stuff..', 'Mixed', 58.10, 13.85, 0.78);
INSERT INTO reviews VALUES (2810, 339230, 1292, 'Average day in Birmingham', 'Definitely not gonna log into uplay to play a singleplayer game i bought on Steam. Get rid of this nonsense!', 'Mixed', 61.61, 12.25, 0.92);
INSERT INTO reviews VALUES (2816, 339350, 1663, 'If you''re new to Choose Your Own Adventure / Interactive Fiction / Choice of Games, I would suggest starting here, like I am. It''s funny, easy to get into, and it has a super wide range of choices and outcomes, but you can finish a playthrough in a single session if you have a few hours.', 'Really loved the game at first, but then it injected politics out of nowhere. Look, it doesn''t matter if you''re for it or against it, the point is this: people most often play games to ESCAPE the real world, not to have it rubbed into their faces. I don''t care what side you root for...I just wanna enjoy games and forget that the world sucks for a bit.', 'Overwhelmingly Positive', 96.15, 6.45, 0.92);
INSERT INTO reviews VALUES (2817, 339400, 116, 'The game in a nutshell: It''s basically Minesweeper with RPG elements. \n\nIt''s actually pretty enjoyable though, it gives one the initial impression of being a very simple game until you actually try to master it. \n', 'I would highly recommend a game like Desktop Dungeons any day of the week over this game. Unfortunately, this game is all about the grind, and an unfair amount of random chance with little to no variation.\n\nYes, I know, Roguelike games are supposed to be full of all kinds of random chance, they are supposed to be unfair, and yes there is a charm and a fun in that. This game takes it to a level where, when combined with the grind, it is just not fun. It becomes monotonous, and then annoying.\n\nThe', 'Mostly Positive', 75.00, 9.28, 4.72);
INSERT INTO reviews VALUES (2818, 339440, 160, 'Fun game with huge potential, sadly abandoned by the dev :(', 'Game has been completely forgotten about and abandoned.... Super fun game,for the first 20 mins.. after a while though, it just becomes boring. This game needs more content to be worth your money. And it needs a Dev team that cares.', 'Very Positive', 87.50, 0.53, 30.73);
INSERT INTO reviews VALUES (2822, 339510, 126, 'It''s hard to tell this game is good or bad .It''s just an average drama about " teenagers and their superpower save the wolrd ", but it''s ok ,I guess . As an adult ,it''s kind hard to relate to teenagers\n\nAnd for those readers who are not  English native speakers,  compare to others ,this game is easier and don''t contain many difficult words,so it''s a good choice to pick this one as your first COG game', 'Short, but alright. The options felt a bit restictive to me though and it felt a bit generic. Didn''t really get as invested in it. Cliches aren''t nessacarily bad, just could''ve been better.  I''d say I enjoyed Mecha Ace and Choice of Robots more. Maybe it''s just my tastes getting in the way. Fortunately I think there''s a demo for one to try out.', 'Mostly Positive', 78.57, 2.67, 2.52);
INSERT INTO reviews VALUES (2824, 339570, 118, 'This land has seen better days. The four warlords that rule it are harsh indeed and their legions of minions will destroy any who would challenge them.\n\nThat''s where you come into play with your tactical skills and squad of hopeful heroes that are most likely headed to certain oblivion. But one day the enemy shall be vanquished if you persevere and you''ll be known as the savior of this land. \n\nMaybe there will even be enough of it left to recognize you as such.', 'What a sorry game', 'Very Positive', 83.90, 93.28, 11.30);
INSERT INTO reviews VALUES (2825, 339580, 704, 'The game is okay. It has decent gameplay, a story that is easy to follow, although I did miss some quest markers in my map overview at times, and not a huge world. Didn''t like the click to walk mechanism, but that is a personal preference.\n\nHowever the lack of a skill bar was really an issue for me, you just have 3 action buttons where only items can be assigned to. Now there already isn''t a skill tree, so any skills you have are gear dependent and can later be added to gear with runes. But to u', 'Too many, way too many crashes to be playable. Avoid it.', 'Mostly Positive', 76.56, 13.03, 1.47);
INSERT INTO reviews VALUES (2834, 339790, 308, 'remind me of ex wife who living in Alabama 500 oval race track circuit ;) \n\nNote: a great generic alternative of simulator racing and driving games at the 2005 , still available now at 2024 , not expensive even without the steam sales , after buy and install this games , just download all the greatest mods, cars and tracks on rfactor 1 available on the internet google. Age like fine and clean old red ferrari ;D \n\nHonorable mention : automobilista 1 ( like rfactor 1.6 ;)\n\nFor your sim racer or ca', 'nah got sick of it after 3000 hours', 'Very Positive', 91.88, 36.70, 3057.63);
INSERT INTO reviews VALUES (2835, 339800, 19692, 'I try to play the game and at this point I don’t want to see any sexual content I just want to beat the game ngl 🫡', 'THIS IS THE WORST GAME EVER!!!!! Its very inapropiate and it is not recommended. This game will be reported and it is not for children', 'Overwhelmingly Positive', 96.34, 9.82, 5.23);
INSERT INTO reviews VALUES (2840, 339910, 141, '+18 workshop mods are the best!', 'Worst rage game ever!\n\nThe controls are way too sensitive, the levels give absolutely no room for error, and team mode doesn''t work for me.\n\nAnd yet I can''t stop playing it because of both the addicting qualities of all rage games and the fact that the game rewards you with hot anime women.\n\nBuying this game will leave you addicted to a game that raises your frustration and anger levels to maximum. Save yourselves, it''s too late for me.', 'Very Positive', 81.56, 5.62, 14.22);
INSERT INTO reviews VALUES (2841, 340000, 463, 'This game is awesome, and Double Fine makes nonstop bangers- was checking their steam library to see if anything new was in the works and figured I''d post a review since I need to be better about writing them!', 'an odd game, which i got bored of fast', 'Very Positive', 88.77, 11.30, 1.97);
INSERT INTO reviews VALUES (2844, 340050, 1304, 'The developer deserves major respect for releasing a patch that supports the Steam Deck and allows playing on Linux. The game itself is a hidden gem, sloppy but nice. There''s something almost spiritual about the way it captures survival and human interaction.', 'Really tried, but god no\r\n\r\nSome old games need to stay in the past, and this is definitely one of them, Mechanics are awful, music is wtf, and just the entire thing is confusing as f. Just give it a miss, it is a top down micro manage mishap. Avoid', 'Very Positive', 81.06, 10.55, 13.83);
INSERT INTO reviews VALUES (2845, 340070, 324, 'Battle Ranch: Pigs vs Plants\n\nHas a total of 5 trading cards.', '\nA very bad Plants vs Zombies rip off.\n', 'Mixed', 40.12, 0.43, 3.72);
INSERT INTO reviews VALUES (2846, 340150, 1209, 'It''s an athmospheric little management game about the competetive world of the illicit medication complex with a focus on means of production and personnel management.\nSoundtrack, artstyle, gameplay and technical stability are all to my liking. I''ve returned to this little gem often over the years and the only critique is, that it leaves you wanting for more... which is good, except there isn''t more to come.', 'Yet another abandoned game. This game is fun in the beginning, but becomes very difficult less than half way through. There''s very little explanation on how in depth mechanics work that leave you confused on where or what you''re doing wrong, until you have to watch a Youtube video. I wouldn''t recommend this game, maybe on sale for $5, but that''s it.', 'Mostly Positive', 76.34, 86.05, 4.62);
INSERT INTO reviews VALUES (2847, 340170, 1452, 'Great 9/10 game and an underrated Final Fantasy game that delivers an engaging Action-RPG oriented gameplay, brings a lot memories of me playing this game on PSP. Sadly this game is stuck at 30 FPS, and this port doesn''t play well on 30 FPS. The motion blur was intense and even its turned off, you''ll still feel very dizzy.\nHowever, thanks and credits to Banz99 from Github (https://github. com/Banz99/Final-Fantasy-Type-0-Hd-Unlocker) (remove the space on .com) for fixing this issues that Square E', 'Game desperately deserves a proper remake, modding to fix the 30fps + 1080p cap can''t save how awful it feels to play.\n\nCould truly be something special if it was given a better budget and rebuilt from the ground up, including bringing back multiplayer support.', 'Mixed', 60.61, 6.03, 6.03);
INSERT INTO reviews VALUES (2853, 340270, 184, 'Atmospheric walking sim where you explore civilization about the get vaporised by a meteor. Game is set in 10 second timeframe that has been slowed down into 10 minutes and to discover everything you''ll have to play through it couple times.', 'Wait a second.....this isn''t Majora''s Mask.....whole lotta nothing tbh.', 'Mostly Positive', 79.35, 1.10, 1.32);
INSERT INTO reviews VALUES (2854, 340280, 115, 'Cubot\n\nHas a total of 5 trading cards.\n', 'The game is not bad, but I’m giving it a negative review because they spelt “Controller” wrong in the options menu (and I was banned from the forums for creating a post about it, before I created this review).\n\nScreenshot of the spelling error: imgur.com/FqG3kWj.png\n\nIt has been nearly three years, and this still hasn’t been fixed. I feel like they’re leaving it in just to mess with me.\n\nI will change this review to a positive review when the error is fixed.', 'Very Positive', 87.83, 0.70, 0.57);
INSERT INTO reviews VALUES (2856, 340320, 107, 'Unexpectedly, you think the game is picking up and taking you somewhere interesting only to snuff it out. When art mimics real life I guess...', 'honestly pretty decent, but no saving other than one autosave, so if you bug near end and it saves it like that ( and it pretty much will) you will have to start over. which sucks because i want to recommend it but, no.', 'Very Positive', 85.05, 2.62, 8.58);
INSERT INTO reviews VALUES (2858, 340340, 245, 'I got to experience the life a dog, and I got to say it was amazing. Dogs have a really great care-free life.', 'If this looks like Pewdiebait to you, you are probably right. I usually suck at distinguishing pewdiebait from real games, but this game is not very interesting when you start playing it. It''s more like having to do chores as a dog. Boring as hell. Sure, there are some fun dogs, but as soon as it dies it''s gone and you will have to hope for something that doesn''t suck as much. It seems alright at first, but soon you will start to notice that within every 5 seconds you have to fix one of the bars', 'Very Positive', 83.27, 2.85, 1.08);
INSERT INTO reviews VALUES (2860, 340360, 181, 'Good game, install the beta for full 4k resolution.', 'It''s a very cool premise, but the execution is awful.  The game''s mechanics are confusing as hell and poorly explained, and as a result you just sorta flail around doing random stuff.  Ideally this game would make the player feel like an evil mastermind filling a lair with fiendish traps, but since resources are generated essentially randomly and what everything does is so unclear none of that comes across.  Just a mess.', 'Very Positive', 81.22, 10.75, 1.15);
INSERT INTO reviews VALUES (2869, 340490, 480, 'Don''t generally write reviews, especially on an 8 year old game, but just wanted to commend this game for doing what it does well. It''s fairly simple in design, but it''s challenging, creates a sense of progression as you go along and has just enough variety to keep you going. I''ve spent way more on games that I''ve put much less time in. Well worth it.', 'In spite of the fact I''m still actively playing the game, at least for a bit yet, I can''t recommend it to new players.\r\n\r\nContamination soured the mid-game for me. It''s a measure, from 0 to 100, of the main character''s contamination from the environment, given by an ambiguous orb in the bottom left. This value grows at a rate proportionate to the current contamination level, and at a certain point, causes HP drain. Getting hit raises it, and the only way to lower it is decontamination pills, whi', 'Mostly Positive', 78.12, 47.85, 25.10);
INSERT INTO reviews VALUES (2871, 340520, 314, 'Banger game. Like discovering an old system this game is how that feels. Unlimited jumps and no weapon cool down makes this game one of a kind. One man is all you need sometimes.', 'No. Just no.\n\nThe game fancies itself cleverer than it is. The game is possibly the jankiest roguelike I have ever played (and I have played probably too many).\n\nAs some have said, if you''re a massive masochist, then maybe this is your miserable cup of tea. I, however, am not.', 'Very Positive', 89.17, 176.73, 0.90);
INSERT INTO reviews VALUES (2875, 340580, 188, 'The art style''s amazing.\r\nThe gameplay''s exciting.\r\nWish he could remake the rest of the series too.', 'bruh no', 'Very Positive', 86.70, 8.88, 2.03);
INSERT INTO reviews VALUES (2879, 340730, 617, '"The only measure of a guy''s happiness is the number of times they''re been blown off by a girl in a week" - A Wise Segg Demon said', 'Nice side story for fans of the Sunrider series, however get ready for a whole lot of tedious stat management.\r\n\r\nAfter completing a route and spending all that time raising statistics, pay off wasn''t that great even with the uncensored patch. I just have no willpower to go through the entire Cera school year to finish another route with the sheer monotony of doing the same thing over and over again.\r\n\r\nIt does get easier as the school year progresses assuming you bought the important stuff from', 'Very Positive', 83.31, 24.60, 10.75);
INSERT INTO reviews VALUES (2885, 340830, 189, 'Nobody will read my review so I will eat 1 Tablespoon of Spicy Ketchup for every like this gets.\n', 'The beginning just doesn''t look promising at all and he progress seems to be too slow, while it''s not really comfortable to start with, there isn''t even an autocast for the only (ranged) attack that you get at the beginning besides the cooldown/resource based attack you also have.\nThe UI isn''t intuitive, for example Escape button doesn''t close other menus but instead just opens the main one, the map can''t be transparent so it''s not too comfortable to walk with it and there''s no minimap.', 'Mostly Positive', 78.31, 5.67, 0.48);
INSERT INTO reviews VALUES (2892, 341000, 1283, 'This game was my favorite game dev sim game until its sequel dropped. Honestly, can''t play this anymore now. But respect for what it brought then', 'Abysmal UI. Filled with pointless micromanagement. Completely unintuitive and unrewarding gameplay. If you are looking for a game company themed tycoon game, get Game Dev Tycoon instead, it is indefinitely better in every regard.', 'Very Positive', 88.85, 27.35, 2.47);
INSERT INTO reviews VALUES (2893, 341020, 140, 'I honestly feel that a "mixed" score for this game is not representative, though its hard to accurately represent what I feel about it with the simple "thumbs up/down" system. \n\nNegative reviews on steam do address some of the jank that is in the game, and they do a fair assessment. But its still a good game, with lots to love, and where you can really feel that the developers cared about it. \n\nIt has beautiful art and animation, and I absolutely love the cute characters. The music is also great', 'Zelda II inspired Metroidvania, but just like Zelda II I find the combat to be irritating and unsatisfying. And exploring isn''t as fun as others in the genre, it just feels too slow.', 'Mixed', 67.86, 78.68, 2.73);
INSERT INTO reviews VALUES (2894, 341030, 125, 'Good strategy game, if you are into that sort of game.', 'The game has extremely little challenge with a very basic gameplay loop where you rapidly start to steamroll everyone else. If you''re looking for a strategic game about the time period around Scramble for Africa and such the game series Victoria by Paradox is a better one, even with 3 being controversial.', 'Mixed', 57.60, 19.65, 11.18);
INSERT INTO reviews VALUES (2903, 341150, 198, 'Classic loved every second of it.', 'tl;dr version:  It''s not fun, nor is it particularly tactical.\n\nThere are so many things wrong with the beginning of this game that it makes me completely uninterested in continuing to see if it ever gets better.  Your main melee units can''t be controlled.  They just swing randomly at the nearest dude, which is almost always not who you want them to attack.  Your units can only move in straight lines, so attempting to get more than one guy on the same target is a chore.  Your units permanently d', 'Very Positive', 83.33, 68.87, 1.98);
INSERT INTO reviews VALUES (2910, 341310, 797, '⠀', 'why do i keep buying these crummy rpgs?', 'Mostly Positive', 73.02, 5.95, 1.50);
INSERT INTO reviews VALUES (2913, 341390, 141, 'After performing the invocation ritual, there are so many bugs on the last floor of this game. It just keeps crashing is nearly unplayable. It also crashed at the castle without having a backup to restore. However, I found the save file and it had a .e extension i removed the .e and the game reloaded to the castle. I''m not sure if the castle crash is spawning so much issue with the final floor.\n\nSince that save file seems to be there forever I am now back down to the vibrating square on what is ', 'NetHack itself is cool. And while Vulture adds much-needed graphics to NetHack, it doesn''t do that great of a job with the interface.\n\n1. Not all possible commands are exposed, so you still need to know the keyboard controls to NetHack, or at least have a reference\n2. The interface is cumbersome to use. If I want to shoot a monster it takes multiple mouse clicks. Something as basic as shooting should be a single click, or keystroke\n3. The interface doesn''t remind the player of what keystrokes co', 'Mostly Positive', 75.18, 376.27, 4.75);
INSERT INTO reviews VALUES (2917, 341500, 424, '⠀', 'An interesting concept, but it gets very repetitive. It feels like a slog almost halfway through the game. Hitboxes and platforming were definitely questionable. \nThe story is essentially just some text throughout the game in the form of mementos. The endings also don''t hit too hard either. \nEven at the $1.99 it feels like it should have been a free flash game back in the day.', 'Mixed', 61.56, 5.03, 6.28);
INSERT INTO reviews VALUES (2921, 341550, 241, 'It puts the "C*NT" in CONTRA.\n\nOnly 8.5% of all players have beat this on EASY difficulty. \n\nThat says it all right there.', 'An extremely parochial and unsophisticated take on Contra that''s as uninteresting as it is unfinished.', 'Very Positive', 85.89, 1.97, 5.12);
INSERT INTO reviews VALUES (2932, 341800, 7579, 'also able to play by yourself if you dont have any friends if you print it out. also my brother is stupid and makes it way harder than it ever needs to be', 'playing this game makes me realize that my friend is a waste of space in this earth and should not be born at the first place. I think his mother dropped him at the hospital. fyi, my friend cannot differentiate between a o and 0 and proceed to blame me when we are on the simon says.', 'Overwhelmingly Positive', 98.39, 7.72, 0.12);
INSERT INTO reviews VALUES (2934, 341870, 246, 'This game is not only a Donkey Kong Country-like, it''s also a Wario Land-like. It''s like Pizza Tower and AntonBlast, but BEFORE Pizza Tower and AntonBlast!', 'The game is super buggy and freezes on me whenever I try to start a new game. Also, the game controls don''t work with a joystick controller even though it says it does. Total waste of money.', 'Mixed', 69.92, 17.45, 0.15);
INSERT INTO reviews VALUES (2938, 341940, 8689, 'It''s basically like The Sims\nWalking around in the neighbourhood and interacting with other people, visiting their homes, getting groceries, satisfying your needs ect', 'Refunded.\n\nLook, I get the idea. At the time this caused a big stink in the mid-2010s, it was smack dab in the middle of another wave of absolute horse manure culture war outrage against video games. These devs were pUsHiNg tHe BoUnDaRiEs oF fReE sPeEcH... which I''m all for, don''t get me wrong. But the game''s ass. Its controls are trash. The AI''s trash. There''s little variety in what are supposed to be shockingly brutal execution animations, many of which are tame compared to the kind of shit Ma', 'Very Positive', 81.16, 0.25, 1.43);
INSERT INTO reviews VALUES (2939, 341950, 143, 'So much fun. It''s like risk but with community maps and genuinely incredible bots. Cannot recommend enough', '+Lots of maps\n+Fun to play \n+On certain maps bots do offer a bit of challenge (mostly because it turns into a 1vs5)\n\n-Has multiplayer, but no one playing it\n-Graphic glitches \n-Worst user interface I''ve seen in years', 'Very Positive', 86.71, 14.23, 23.58);
INSERT INTO reviews VALUES (2946, 342180, 5080, 'This title is absolutely worth playing but you should make sure that it is your first VR game or at least your first VR first person shooter. I beat the game in 3.6 hours and it is, to be honest, a zombie shooter-styled tech demo. This game was released in 2016 and it is definitely showing it''s age. If you are brand new to VR, I would recommend playing Job Simulator, The Lab, Arizona Sunshine, Vertigo, Bonelab/Boneworks, Into the Radius, and then Half-Life: Alyx, in that order. Do not play Alyx ', 'F*ck you, that''s why! Also, e9,99 extra get''s you an upgrade to the REMAKE. What do you get? Multiplayer. But do note that the Multiplayer was also in this game, but taken out. Because I guess they''d earn more if you spend €9,99 extra. Serioulsy, scummy.', 'Mostly Positive', 78.66, 3.57, 13.23);
INSERT INTO reviews VALUES (2947, 342190, 137, 'Super fun tabletop card game in VR. It plays well and has plenty of hours of entertainment.', 'keepas crashing', 'Mostly Positive', 75.91, 9.37, 2.92);
INSERT INTO reviews VALUES (2948, 342200, 110, 'Fun multiiplayer game.  Rounds last less than 15 minutes.   Not really meant for care bears, if you don''t like dying a lot either practice or play Doom on the "don''t hurt me daddy" setting.  Building Mechs and trying out different combinations and strategies is fun and most people are pretty friendly as they shoot you to pieces.  Been playing for nearly a decade and still love the geme.', 'dead', 'Mostly Positive', 74.55, 23.82, 2034.03);
INSERT INTO reviews VALUES (2952, 342260, 137, 'I played through this game with my friends about 6 years ago, and to this day, something will suddenly remind one of us of this game and we''ll reminisce about it. Such an inventive premise. Each section keeps you guessing as to what it''s all about up until the very last moment, and when it''s revealed, everything that came before makes sense in retrospect. I actually came to the store page just now to check to see if any other games had been developed by Flying Mollusk. It seems that the lead cre', 'Don''t get a cheap heart monitoring mouse for this game bc it won''t work properly and the game will perpetually think you''re in stress mode and you will have a bad time.', 'Mostly Positive', 71.53, 6.83, 2.02);
INSERT INTO reviews VALUES (2953, 342300, 283, 'BIG chunk of my childhood, lovely game will never get old when you got friends with you, cant forget Zombie Kill of the Week.', 'Boring', 'Very Positive', 92.23, 10.82, 5.80);
INSERT INTO reviews VALUES (2954, 342310, 708, 'No updates at all\nkinda complicated but really fun once you get the hang of it\nversus mode :D\nworkshop maps :skull:\nbad reviews are because people don''t know how to play\n\n', 'abandoned game', 'Mixed', 62.71, 6.68, 5.22);
INSERT INTO reviews VALUES (2955, 342350, 133, 'Kilo Yankee Sierra: The Game', 'Annoying puzzles that are not fun at all.', 'Mostly Positive', 78.95, 7.42, 0.23);
INSERT INTO reviews VALUES (2957, 342380, 815, 'Sakura Angels is packed with magical waifus and an ancient evil storyline, but let''s be real—it''s all about the waifu moments and the *plot*. With magical girls protecting the protagonist and plenty of character interactions, it has all the ingredients for a perfect visual novel experience. Could use a few more headpats and some deeper customization, but overall, it delivers the *content* you’re here for desu ne.', 'The art is pretty good.  \nAnimation effects is generally pretty bad.\nThe story is pretty bad.\nThe voice acting of the two main girls is ok. Voice acting of the other girls is poor.\n\nIf you have nothing else to play and you really want to see some cute waifus it could be ok.  But I think most any other VN or decent game on Steam is going to be a better use of your time.', 'Very Positive', 83.07, 50.35, 1.80);
INSERT INTO reviews VALUES (2958, 342450, 102, 'I understand this is an adaptation of an old "choose your own adventure" book. I LOVED those in the 80s! So coming from this mindset and with the beautiful graphics and soundtrack they put this in, I will give it a "thumbs up".\nOtherwise you might be disappointed because it is very short and some scenes/changes in feeling come very abruptly. You can''t really compare it to a modern VN, so keep that in mind!', 'Pretty, but the story felt a bit inconsistent and creepy.', 'Mixed', 50.00, 3.52, 1.60);
INSERT INTO reviews VALUES (2960, 342490, 145, '“I can’t believe it’s not Zelda!”-type of action/adventure game.\n\nThat sound quite harsh to type out but it is how the game feels, a very middling, average substitute in a genre and on a platform with several other alternatives that are joggers in both quality and entertainment value. There are some nice aspects to the game, emulating the GBC-style screen scroll of older games and the N64 player style border around the game in full screen mode is charming. The puzzles are satisfying for the most', 'Difficult to imagine the combat being worse than it is.', 'Mostly Positive', 77.93, 3.42, 2.25);
INSERT INTO reviews VALUES (2967, 342560, 4375, 'A desperate war between a mercenary company and a death cult. The discovery of what man can do to another for ideology and fickle politics. The pointlessness of the suffering. Conquerors of a land that has become a graveyard, devoid of resources and beauty. War is hell, and the funny airships game has opened my eyes to the absurd horror of it all.', 'The game is both great and terrible in some ways. Overall I really enjoyed it, but I would not recommend it. There is a lot of freedom in building a ship and making a reasonable frigate as well as making weird barely flying orc-like big shoota thing is wonderful! But there is a great problem with UX/UI. For example - I have no idea what happens during a fight. If my side is shooting and hitting or not. It''s lacking proper signs of effects if the ship is damaged, something simple as health bar wo', 'Overwhelmingly Positive', 96.46, 23.25, 5.48);
INSERT INTO reviews VALUES (2969, 342580, 775, '12 Labours of Hercules\n\nHas a total of 5 trading cards.', 'Not Recommended', 'Very Positive', 90.45, 1.63, 2.53);
INSERT INTO reviews VALUES (2972, 342640, 456, 'With support, this game could have really been something. \n\nI enjoyed it.', 'Not much in the way of content, could be a good game one day but not worth $6 (sale price) currently. Every planet feels the same, using ablities doesn''t feel good and switching between crew members feels hard in the middle of a fight. Weapon stats feel pointless and the "Ship" screen is confusing and feels needlessly complex. I expected a lot more from the people (Relogic; published this game) who brought us the masterpiece that is Terraria. One day it may be a good game but it needs a lot of w', 'Mixed', 69.52, 2.85, 1.67);
INSERT INTO reviews VALUES (2986, 343070, 189, 'My name is Earl,and I was a motorman and I drove this train for 7 years,an it reminds me when I worked for NYC transit. It is so real,like I was back on the job,I hope you enjoy this game/simulator as I do.', 'OK, I know that this game models the 1980s and that''s before I was born. I heard that the subway was in a worse shape back then. The graphics aren''t great; I love NYC and I feel like the model gives NYC a bad name because it looks so bad though it''s true that some subway stations are gross. The humans look really creepy. The graphics are worse than those in Train Simulator Classic. The keyboard controls are unwieldy; too many things can only be controlled through the keyboard but not the mouse, ', 'Mixed', 67.72, 18.18, 1.22);
INSERT INTO reviews VALUES (2987, 343090, 197, 'I remember enjoying these games a lot more on tablet. For PC the game needs some fixes / optimizations. For instance: The icons to control the craft are all scattered far across the bottom edges of the scree. This is a long ways to drag the mouse on a PC. The button for staging is all the way to left while speed control is all the way to the right. This could certainly be optimized for PC gaming and larger monitors but sadly it hasn''t.\n\nWorth it on sale (Don''t expect updates for a mobile port).', 'Like many people have said already this game is a moble port to pc... that being said it is fun for a little bit but after that you get bored very fast. in order to make this a actual game it needs alot more content, more ways to customize your rocket and better ways to keep them attacted to eachother. donot buy.', 'Very Positive', 83.25, 3.78, 5.28);
INSERT INTO reviews VALUES (2988, 343100, 368, 'Sometimes I just enjoy an impossible twin-stick shooter than can kick my ass fast, and that''s Overture. Too much grind to be considered an enjoyable roguelike, but I think the classes and the challenge can keep you going. Or not. That''s ok, too, we all have skill issues.', 'Kind of a neat bullet heaven game, but there''s way too much going on at all times. Can hardly tell what''s happening because most of the screen is covered.', 'Mixed', 69.29, 7.62, 0.17);
INSERT INTO reviews VALUES (2995, 343270, 191, 'Disillusions Manga Horror\n\nHas a total of 6 trading cards.', 'Disillusions Manga Horror is the bottom of the barrel. That barrel being a septic tank.', 'Mixed', 59.69, 0.72, 6.03);
INSERT INTO reviews VALUES (2999, 343360, 200, '⠀', '"Boring and bland"\r\n-a smart man', 'Mixed', 61.50, 3.63, 0.52);
INSERT INTO reviews VALUES (3004, 343440, 505, 'I played this game so much with my brother as a kid until it was lost to memory. Decided to do a deep search to find it again and am thrilled to see it''s on steam. I is every bit as fun as it was as a kid. Has a small playerbase, but if you get a lobby with other people it will be a hell of a time. 10/10 I cannot for the life of me find anything worth criticising in this game', 'Худшая игра за свои деньги. МАЛО ВОЗМОЖНОСТЕЙ!!!\r\n', 'Very Positive', 88.51, 4.52, 1.92);
INSERT INTO reviews VALUES (3005, 343560, 188, 'Bob Was Hungry\n\nHas a total of 6 trading cards.', 'Too many blind drops/jumps and obscured insta-kills for my taste. Some levels are nigh-impossible to complete on the first go without dying because you simply can''t see the spikes until a nano-second before you land on them. That''s what makes Super Meat Boy so great. It''s 100% fair. If you die, it''s because YOU messed up. Not because you couldn''t see the spikes until you landed on them. There are several instances in this game of Bob getting hidden behind a tree or the camera angles hides him be', 'Very Positive', 87.23, 1.12, 1.30);
INSERT INTO reviews VALUES (3009, 343710, 793, 'You can feel a sense of despair and isolation in the harsh environment and desolate landscape. The greatest fear I felt in this game was that I am terrible with directions—yet I am the one who must escape this place and end my disappearance.', 'I love the story and the soundtrack, but I didn’t enjoy the gameplay. The concept of realism and map is okay, but it would be nice to have a possibility to mark something on it. Also, movement problems. Our character cannot jump, it gets tired fast and gets killed easily. There is something wrong with the balance. Recommended only for patience and true walking simulator fans.', 'Mixed', 62.80, 5.78, 1.22);
INSERT INTO reviews VALUES (3013, 343780, 6522, 'The cat really goes fishing. 10/10, have played it for 37 hours, will probably play it for 37 more', 'harder than playing dark souls and elden ring at the same time, only for the truest of masochists and the most hardcore gamers', 'Very Positive', 94.77, 37.78, 0.62);
INSERT INTO reviews VALUES (3019, 343860, 2150, 'This game feels very surreal in our current political climate (2025). Please everyone, remember we''re all human. Take care of one another. Stand up for one another. Don''t let corps take advantage of you!', 'If it''s on offer then go for it but I don''t think it''s worth the price considering it''s not even 2 hours long.\nStory is okay, characters are based on DEI though (Overweight white woman, asian male doctor, black female leader etc) - everyone needs a unique race, weight or disability which is weird. And the random political twist at the end has no build up for it. It just kinda happens and then the credits roll. \nThe gameplay and visuals are decent but It has very janky movement and most of the ti', 'Very Positive', 89.77, 3.58, 1.52);
INSERT INTO reviews VALUES (3030, 344340, 122, 'ITS GOOD FOR WHAT IT IS', 'Very poor product for $25. There''s no tutorial, and its a very unfriendly UI. There might be a good game buried beneath it, but I will probably never know. This is coming from somebody who has thousands of hours sunk into grand strategy games which have enormous depth and a sports fan, to whom this game should come somewhat naturally. \n\nSave your money, there are better f2p browser equivilents to this game. \n\nI''ve bought some pretty big clunkers in the past, but nothing that has dissapointed me ', 'Mostly Positive', 79.51, 51.97, 1.15);
INSERT INTO reviews VALUES (3031, 344410, 147, 'kind of like portal but with magnets instead of portals, so in other words not really like portal at all, its fun though if u want a game with similar puzzle design to portal but with some different and new mechanics to play with', 'It''s Portal from Temu', 'Mixed', 67.35, 7.25, 3.03);
INSERT INTO reviews VALUES (3032, 344440, 125, 'This was one of my favorite game when I was a kid. The art style the story everything was perfect! I love this game so much wish they can make more of this game series', 'trash', 'Very Positive', 90.40, 8.47, 3.10);
INSERT INTO reviews VALUES (3033, 344480, 160, 'I first played Quell on the iPhone 10 years ago and rediscovered it here.\nIt is a cool puzzle game that definitely challenges your brain.\nThe built-in guide makes the game easy to understand.', 'Quell is a mobile app that''s been dumped on Steam as if it was a real PC game (it''s not)... it''s a cash grab from greedy mobile devs.  The game is a very simple pathing puzzle game.  You control a blue pixel blob.  You can move in any direction, but once you start moving, you don''t stop until you hit a wall.  Basically this is the same game as the countless Russian "Chocolate Makes You Happy" ClickTeam Fusion asset flips infesting Steam.From a technical perspective, as a mobile app, this doesn''t', 'Overwhelmingly Positive', 97.50, 2.60, 9.57);
INSERT INTO reviews VALUES (3035, 344630, 107, 'Remember when 3D girls were this cute ?,\n\n Neither do i \n\n\nAnd never forget ''''no waifu no laifu''''', 'I can''t read another word. After chapter 2 finished I was fed up.\n\n\n\nI don''t mind a visual novel that does something different - I started out thinking the premise seemed like a cool idea - some kid down on his luck with no place to go gets ''rescued'' into a school exclusively for girls. Apparently the school has a funding problem and is willing to test opening the doors to boys as well, but the test is based on this single kid.\n\nIt starts out innocently enough but the sequence of events is just ', 'Very Positive', 90.65, 16.55, 2.23);
INSERT INTO reviews VALUES (3036, 344740, 715, 'This is a good ass game. You can complete it in an hour or two, sure, but it is worth the price. \n\nGameplay is fast, action packed robot bashing fun. Like playing Armored Core with a light mech. And the customization options both give you awesome tools to hack some bots and also play into the planing.\n\nThe game demands that you plan your path ahead and taunts you to put holes on that plan by giving you some extra cash and goodies so you are always thinking about what compromises you will take so', 'The difficulty spike from the tutorial to just the second ship is pretty sharp.  The battles went from a single enemy at a time to a hoard of ships that blend in with the walls and were tough to keep track of.  The controls felt a bit stiff as well, with aiming and moving not feeling as fluid as they needed to be to keep up with all the enemies and projectiles onscreen.  It''s just more stressful than fun.', 'Very Positive', 82.80, 3.03, 0.35);
INSERT INTO reviews VALUES (3037, 344760, 7837, 'It''s sad, this game was abandoned despite it''s huge popularity long, long ago.\r\n it is what it is, but damn is it a shame.', 'Can someone buy this game from codehatch and update it because still to this day... this was one of the best sandbox games i ever played. Great memories and left to ruin by the devs. Needs it''s code handing over to someone who cares ''cause there isn''t a chance they are making money on it anymore.', 'Mixed', 53.17, 0.18, 94.87);
INSERT INTO reviews VALUES (3038, 344770, 467, 'While the updates for this story are painfully slow, the world building, character development, and general concepts are some of the most interesting I''ve seen in a VN. Milestone Two adds some focus on two new characters: Sol and Mil. I hope Fault - Milestone Two Side: Below doesn''t take too long as it''s still in production. There are also prequels that were released that I''ve yet to explore, but the Fault universe feels so complex that unearthing new stories and characters and jumping out of ch', 'Didn''t give me the option to drink sea slug semen 0/10', 'Overwhelmingly Positive', 96.79, 22.50, 9.70);
INSERT INTO reviews VALUES (3042, 344840, 203, 'Warning:  the complete game isn''t playable due to a PHP problem (per their support).  So the cd-key won''t work.  But the single player parts are pretty fun and are worth the sale price ($5 at present).  Support staff are good people...', 'So, GSB 1 was my very first steam purchase.  I loved that game.  And this game had a a lot of potential and hype for me.  It was initially fun, but then several updates broke it.  The dang thing won''t even boot anymore, and I''ve only gotten better computers.  It doesn''t appear to be a hardware issue, it consistently states it is missing files to boot/run, even on a clean install.  In the interim, the developer moved onto another project.  I get it.  It was just a let down to have built my excite', 'Mostly Negative', 36.95, 7.50, 3.72);
INSERT INTO reviews VALUES (3043, 344850, 919, 'Solid management game with factory building. The factory building part is a lot more intricate than I first thought. As you play, you slowly realize that you don''t need to make the best drug with the least side-effects to make the most profits. Balancing profits and drug quality is an integral part of the game while taking into account the drugs being offered by competitors. Pricing strategy, marketing, and other components are not as critical as they may seem at first, but it is important to pr', 'This is more of a reminder to myself of why I don''t like the game rather than a review. You pretty much have a choice between infinite money creative mode and various timed challenges. Neither are what I look for in an automation game.', 'Mostly Positive', 78.67, 43.05, 8.60);
INSERT INTO reviews VALUES (3044, 344860, 222, 'I love this game so much! I grew up with it and it burrowed its way into my brain forever. Replaying it is still fun :)\n\nThe class system starts to outstay its welcome at higher levels and you might find yourself locked into a build that doesn''t work. But overall the game still holds up and is very charming. The Steam release has some new content as well.\n\nI love the characters so much, especially how they have a chance to talk and reply to each other in battle. They have so much personality des', 'This game starts off well, and has a good story but the gameplay becomes repetative and the whole game looks like it was made in scratch.\nI personally think that it was a waste of money, and I would not reccomend it.', 'Overwhelmingly Positive', 96.40, 37.55, 3.00);
INSERT INTO reviews VALUES (3047, 344910, 205, 'I''m sure 99% of people don''t read the reviews. So you may not know that Naruto can be a bit harsh sometimes. You may not know this, but Naruto also grew up without a father. In fact, he never met either of his parents and never had any friends.', 'Not optimized enough to be enjoyed. Has potential.', 'Mixed', 55.61, 1.98, 0.50);
INSERT INTO reviews VALUES (3049, 345010, 256, 'For such a small development team with limited funds and an Early Access state, the game is amazingly stable. Granted I''ve played for about 4 hours as of writing this, but I have the graphics maxed out and have not experienced a single crash. The game could be a bit better optimized, but I wouldn''t expect that at this stage. There''s a few little strange graphical glitches but nothing game breaking. For example, if you buy a new ship your UI doesn''t reflect the new stats unless you go back to the', 'The developer of this game has many good ideas, but is trying to reinvent the wheel, and does it at a snails pace. Many people say "yes, but it''s early access!", yes it is early access, it''s been that way for a very long time now, and I suspect it will stay that way.\n\nGraphics, Interface, controls, documentation, storyline, and many other things are poor or missing entirely.\n\nDeveloper does not implement major game design based on the communities likes, nor takes ideas that worked well in other ', 'Mixed', 67.58, 16.92, 268.53);
INSERT INTO reviews VALUES (3054, 345090, 422, 'Tower defense games are my guilty pleasure when I want to chill out. This game doesn''t do anything innovative but it just nails the sweet spot for me in terms of  difficulty and progression. There are a lot of levels and the end game is  challenging requiring you to think a little instead of spamming the same towers if you don''t grind the upgrades. I have more hours on this game than Skyrim because i could always just play a level when I had a spare bit of time even if  I was tired. A must buy i', 'There''s a game breaking, game killing glitch that happens if for some reason your computer crashes or the light go out while playing it, it simply won''t start again, not even in a different computer. The game is fun but i can''t recommend it, this issue has been know for years aparently and the delevoper has''t fix it yet', 'Very Positive', 84.12, 85.02, 5.82);
INSERT INTO reviews VALUES (3055, 345120, 123, 'I have no clue what just happened but it was pretty cool :)', 'I didn''t know it was going to be so difficult having played the original flash game and seeing it wasn''t THAT bad. And yet, the game not only demands precision platforming, but also has the nerve to make you build and lose velocity where your character doesn''t stop or start moving immediately, causing you to conveniently slide into the many obstacles it will throw your way, as if dying upon being hit wasn''t punishing enough. The last straw was this room full of lasers and an acid pool with narro', 'Mostly Positive', 77.24, 3.32, 0.95);
INSERT INTO reviews VALUES (3058, 345200, 269, 'personal favorite in the tasty planet franchise, fun gameplay and NANO SHARK IS SO FUCKING HOTTTTT OH MY GODDDD HER DEEP VOICE AND GOTH EMO AESTHETIC MAKE ME WANT TO LIVE A HAPPY LIFE WITH HERRRRR', 'its fine if you''re bored but it gets repetitive very quickly', 'Very Positive', 88.10, 3.45, 0.78);
INSERT INTO reviews VALUES (3061, 345260, 1326, 'I have played it for years.', 'BUYER BEWARE ! ! ! !    Let be begin by saying I LOVED this game back in the day and played it for hours and hours and hours.  Of course, . . .  that was on the "old" computers.  Now I have a nice new computer and I buy it on Steam.  I''m feeling great.  I start playing and I am soooo happy.  Then it just boots me out of the game.  I go back in, and after a few turns, it boots me out of the game again, and so on, and so on, and so on.   I wanted to keep playing, but, what is the use?   About the ', 'Mostly Positive', 70.14, 3533.90, 315.70);
INSERT INTO reviews VALUES (3066, 345330, 121, 'While I haven''t reviewed many games on Steam, I had to make an exception for Eden Rising: Supremacy. I''ve bought into plenty of Early Access titles that have made me swear to never believe in the hype again. Thankfully, Eden Rising has bucked the trend and made me believe that developers can produce EA games that are full featured and fun - while still having plenty more in store for those who eagerly await the next patches. Below is the story of the one crucial moment that made me a believer, a', 'Not solo friendly.  There is a solo option but it eventually becomes not viable.\nTower defense aspect is weak. Towers are near useless, as things just run right past them.  Even if towers did damage, though, they have an "energy bar" for how many attacks they can do at any given time.\nDon''t buy this game if you are interested in the tower defense part of it.\nExploration is fun until you run into enemies that are the equivalent of a raid boss with hyper fast attack speed.\n', 'Mostly Positive', 75.21, 54.10, 9.20);
INSERT INTO reviews VALUES (3068, 345350, 2044, 'Lightning didn''t do anything wrong. People weren''t ready for this game when it came out. Still stands the test of time and is gorgeous. Really was fun when I got to replay it. Love the garb system. It''s similar to dresspheres from ff10-2. Story''s great and bosses are challenging. Also has stellar music.', 'Didn''t realize the entire game rushes you and puts you on a timer.  Immediately ruins the experience in a game I want to take my time, explore, enjoy at my own pace.  I played 13, and heavily enjoyed 13-2, but its sad that they ruined this game with a timer.', 'Very Positive', 80.04, 40.77, 0.67);
INSERT INTO reviews VALUES (3069, 345370, 465, 'easy for my stupid brain who was too lazy to use ren''py cus i hate coding. It''s like as basic as can be, so don''t expect any like crazy features. I will say most of the plugins haven''t been updated in awhile so that was pretty annoying. This game itself hasn''t been updated in quite some time, but its easy if ur just starting out making visual novels.', 'Worked on a game and invested a few days on it, just to find out that:\n1. I can''t publish to Android\n2. No online support\n3. Documentation is outdated', 'Very Positive', 85.38, 37.53, 97.18);
INSERT INTO reviews VALUES (3070, 345390, 1061, 'Not gonna lie, King''s Quest is a really fascinating game.\n\nThe story is engaging and easy to follow, giving players a chance to witness how Graham became the legendary king he is today. The puzzles are a mix of creative, challenging, and occasionally frustrating, but in a way that still makes them fun. While some of the later chapters were a hit or miss, the overall experience was memorable.\n\n7/10 – A game that holds a special place in my heart.', 'Nothing special here.', 'Very Positive', 89.26, 27.77, 0.37);
INSERT INTO reviews VALUES (3071, 345430, 301, 'This is probably one of the most visually stunning and beautiful games I''ve had the privilege to play. I first saw the game by accident while watching a play though by YouTuber Fooster. Just a few minutes in and I decided that the game looked intriguing and captivating enough for me to buy and play rather than watch. And I was in no way disappointed. The story is enchanting and in places immensely atmospheric. The developers obviously don''t take themselves too seriously as there are humorous ele', 'I gave it the college try. Visually, it is very nice. Plot-wise, it could use some work. It''s not a bad game, it''s just not for me.', 'Very Positive', 87.38, 9.27, 0.97);
INSERT INTO reviews VALUES (3076, 345610, 637, 'juicy yuuji', 'extremely cringe localization', 'Very Positive', 93.41, 102.62, 31.85);
INSERT INTO reviews VALUES (3081, 345660, 525, 'Cool motorbikes', 'Entire garage lost after game crashed.\nBullshit save system.', 'Mixed', 69.90, 3.72, 7.20);
INSERT INTO reviews VALUES (3087, 345820, 1021, 'I remember this game being a lot less weirder when I was younger', 'Squid baron is too hot', 'Very Positive', 94.71, 8.83, 17.00);
INSERT INTO reviews VALUES (3088, 345860, 247, '\nDecent shooter with multiple ships to choose from so everyone will find his favorite setup. Different waves of enemies and bullet patterns - by any means it''s not boring. Colorful visuals and good soundtrack but might get repetitive over time. Fairly short as there''s only 6 stages in total. Backgrounds are kinda lacking but that''s ok since there is enough action going on. This one is very easy as I beat it on first try without dying so don''t stress it and just play it!\n', 'It''s honestly not that good, even though I somehow accumulated 10 hours on it over the years. The many ships feel just gimmicky when the core gameplay suffers from underwhelming score mechanics, pointless enemy placement, and the lack of interesting bullet patterns or ANY stage variety. Most of the bigger ships don''t even move, they just sit there.\n\nAs some other reviewer pointed out, by now there are at least a dozen or so better indie Shmups on Steam, let alone Cave and Co. Pick up Gunvein, Ze', 'Very Positive', 80.57, 4.22, 10.55);
INSERT INTO reviews VALUES (3094, 346110, 245656, 'This game made me shed a tear, not because of the beauty of it, not because of the countless years of memories I have from playing this game with friends, no, it was not a single tear of joy, but a tear of sadness. Not because of the pain I feel when hackers destroy my base or when random players give me swamp fever, but I shed tears of sorrow when I looked at what was taking up my storage on my computer and I saw Ark, and it took up half of my storage space, half a terabyte, "why?" I asked as I', 'Game company is using AI slop to market new awful dlc, save your money devs clearly do not gaf about the players and just want to line their pockets', 'Very Positive', 81.25, 147.30, 157.05);
INSERT INTO reviews VALUES (3097, 346140, 120, ' best hidden object game I''ve play in a long time. The 1st game was worth the price of the bundle.', 'Twisted Lands: Shadow Town is not user-friendly and it''s a challenge just to complete the game on easy mode when the hint button takes you in the opposite direct of the nearest task you need to complete. It has no map-fast travel feature either. Meaning, you have to click through the entire map one scene at a time numerous times. Not sure about the other 4 games, but this one should be avoided.', 'Mixed', 58.33, 73.73, 15.30);
INSERT INTO reviews VALUES (3099, 346180, 395, 'first game I ever bought a decade ago and it is fucking lit', 'While I was hoping that the third time would be the charm on new-to-me games today, this is the most immediately unplayable of the bunch, and is arguably even more broken on a fundamental level than the other two, to the point of it being unplayable.\n\nDemerits:\n\n- The “Back” button in the options menu does nothing when you click it, and ESC exits the game without saving anything.\n\n- No reason exists, other than to over-complicate things, why you need to click and hold in a direction to fire your', 'Mostly Positive', 78.48, 12.13, 1.98);
INSERT INTO reviews VALUES (3107, 346420, 189, 'Updated: (reversed negative review)\n\nJust when i thought The Spatials was done with updates and changes, leaving some annoying things in the game, i was just responded to on the forums by the devs, and it turns out they are changing some of the things people wanted to see changed.  I can easily reccomend The Spatials, and the devs behind it.', 'Works well on deck. Gameplay though i found it a bit boring and repetitive.', 'Mixed', 69.31, 10.57, 3.65);
INSERT INTO reviews VALUES (3111, 346460, 204, 'YO THIS SHIT IS TIGHT! TAKES A WHILE TO GETS MY HOTAS RIGHT BUT THEN ITS FUN AS HELL', 'There is a good game in here but it''s covered up in a lack of play testing. Lots of weird UI issues that you just have to figure out, lack of polish. In the garage when you are messing with your skimmer you can''t save it mid-build, it has to be complete first. You can''t easily move the camera around you have to change states first, move the camera, then go back to messing with the skimmer. If you are trying to adjust the angles on your specific item and the UI for it happens to be over a mountin', 'Very Positive', 81.86, 15.63, 5.07);
INSERT INTO reviews VALUES (3112, 346470, 267, 'I''ve played just about every teem tennnis game from GBA to N64 to PSP to virtua tennis , most of them to completion on the hardest setting. This is one of the most fun and realistic, but I do like many of them. Some I do not like are AO tennis, matchpoint.', 'Arcade game suitable for mobiles at best. Very overpriced.', 'Very Positive', 94.76, 95.08, 61.10);
INSERT INTO reviews VALUES (3116, 346560, 649, 'This game is not your typical RPG. It doesn''t involve rolling dice or button-mashing battles. Instead, it''s a casual game where you click on text, items, and possible battle outcomes. The story follows a brother and sister escaping a tough situation, only to find themselves in another strange situation. To progress through the story, you click through multiple zones and complete quests.\n\nThe story, while not particularly remarkable, fits the bill for a short, casual game with a "good versus bad"', 'This game has autosaves/1 save slot only and at no point does it warn you that some of the content will be missable if you reach a certain point in the main quest. Because of this I will not be able to fully complete the game, and I''m not slogging another 6 hours to try to complete the quest again. This game should have a manual save feature and it''s baffling not to have one in current year.\n\nIn addition the middle portion of the game is a slog having to build and supply up your ship, it took li', 'Very Positive', 94.30, 7.40, 5.38);
INSERT INTO reviews VALUES (3120, 346730, 181, 'I wish this game revives.\nBut it may won''t.\nJust like all those good old days.\n\nhttps://steamcommunity.com/sharedfiles/filedetails/?id=1243379668', 'Gears of War Takes on Gocco of War\n\n\n\nMarcus Fenix:  What in the ever-loving hell is this? It’s like Gears of War tried to join a Saturday morning cartoon and got rejected.\n\nDom Santiago:  Who asked for this? This looks like Gears got drunk and hooked up with a kid’s art project. Where’s the grit? The gore? The war?\n\nSam Byrne:  You mean the adorable little characters with giant heads aren’t doing it for you, Dom?  Look! Even the taunts are cute!\n\nBaird:  Cute is not the problem, Sam. The contro', 'Very Positive', 84.53, 634.95, 1.82);
INSERT INTO reviews VALUES (3125, 346810, 304, 'Wonderful strategy game with enough variation and opportunities for success and failure that at the end of it you feel like you have accomplished something.', 'Game does not work.', 'Mostly Positive', 75.99, 10.77, 74.68);
INSERT INTO reviews VALUES (3127, 346850, 459, 'I used to play this all the time as a kid because it was the only game I had, so I''m glad I was able to find it again here.', 'i shit myself on the plant level', 'Very Positive', 91.29, 7.07, 8.17);
INSERT INTO reviews VALUES (3128, 346900, 275, 'Overall this game is great. This game is fun if you want to play it for 5 hours or 20 mins. would recommend. There is also a mobile version.', 'The game is a fun click and dick around type game but for the special events it cheats by having bot accounts play against you. within a hour or so a bot/fake account this developer made has reached level 9 of 12. I spent 30 bucks worth of upgrades which were about 14 days of power ups and im level 3.5. If the developer removed the fake accounts so you had a chance of winning the events and getting the items for free it would be a worthwhile buy. But it isn''t so fuck them and fuck this game', 'Very Positive', 85.09, 40.75, 376.42);
INSERT INTO reviews VALUES (3130, 346940, 2693, 'Best gameplay in the Shadowrun series reboot (especially playing as a Decker). Dragonfall has the better story but SR:Hong Kong''s story is still good overall. The music is great too.', 'I really enjoyed Shadowrun and Dragonfall. Honestly, in those games the writing felt a bit "teenage fan-fiction" at times, but it sufficed. Here, it''s just bad. It''s amateur in every sense, but the worst part is it goes on and on and ON. NPCs have long, pointless backstories and dialog options that I think the writer felt would help flesh out the world more, but it all becomes a blur of mind-numbing tedium. Whoever wrote this has never heard the expression, "Sometimes less is more". This is REAL', 'Very Positive', 87.04, 180.33, 17.18);
INSERT INTO reviews VALUES (3132, 346970, 250, 'game is legit really cool and ties it all together with the art style\r\n\r\nmuch like happy wars this game is dead, but also REALLY good and quality\r\nthis game is small, but this game cares\r\n\r\nand so should you', 'have to pay for private lobies with an external provider', 'Very Positive', 82.80, 5.73, 0.17);
INSERT INTO reviews VALUES (3137, 347160, 371, 'I would give this game a 9.5 out of 10\r\nIt''s one of the best shoot-em up''s I have ever played and that''s since the mid 80''s.\r\nThe music is amazing, the upgrades and combination effects they have on each other, the enemies and bullet hell bosses are brilliant.\r\nThe graphics are top notch and the hidden levels and bosses all add to the experience.\r\nA true labour of love, and speaking of lovem I would love to have this on an arcade cabinet!', 'Brutally hard 2D sidescolling schmup.\n\nLove the pixel art.\nMain thing that turned me off from this one is the lack of build variety and difficulty. Most upgrades don''t have a large impact, meaning that to progress farther into the game you''ll need to rely more on skill than finding broken combos. The problem with that is most bosses you''ll need to fight multiple times to understand what they are doing, and since they all look similar it can be hard to tell what attacks they are going to do. On t', 'Very Positive', 88.68, 44.73, 0.97);
INSERT INTO reviews VALUES (3138, 347170, 238, 'The good: straight out of the box, jump into action with an Xbox controller to complete the Mach loop. That’s thanks to recent updates.\n\nThe bad: everything else. You have to approach it as a beta version of a sim made in 2005. Large amount of bugs, bad graphics, bad audio, horrible scenery. The fidelity is on MS Flight Sim 2004 level.\n\nAnd yet I recommend it! It’s a nice change from DCS or Falcon or P3D if you can afford it, everything is simplified, it’s ready to go.\n\nGet it on discount.', 'At time of writing it’s been in early access for 8 years. \nWait for it to be released before parting with any cash.', 'Mixed', 52.10, 0.83, 1.62);
INSERT INTO reviews VALUES (3145, 347290, 183, 'cps小于8的谨慎考虑游玩', 'I''ll keep this short and sweet as I''m just rehashing/confirming what others have already said. \n\nRise and Shine is a decent, but didn''t really scratch my 2d shooting puzzle platformer itch. It looks great, you tell a lot of work went into the visuals. Locations are diverse and the references were pretty great. \n\nMy biggest complaint, and reason I probably won''t try start another playthrough, is the mechanics. For anyone who has played these types of games. It''s pretty standard to allow shooting/', 'Mixed', 65.03, 1.40, 1.93);
INSERT INTO reviews VALUES (3147, 347400, 138, 'I have waaaaaaaay too many hours on this engine making games and apps just for my own personal hobbyist entertainment, I should probably make something to sell at this point.\n\nI would recommend this to anyone that wants something that gives you the tools to make something extremely basic and simple, eventually as you get familiar with it and start delving into it deeper you can end up getting into some more advanced forms of design you''d never imagine you''d ever have the capacity to do before yo', 'We have a game engine at home.', 'Mostly Positive', 76.09, 4324.53, 4.77);
INSERT INTO reviews VALUES (3148, 347430, 627, 'Very easy HO game with neither mini games nor HO scenes posing any issue. Graphics and animations are good, the story is not noteworthy but it keeps you going in a logical manner. The game is short and all in all decent.', 'Frankenstein: Master of Death turned out to be a very mediocre game. It is made according to the canons of HOG, but absolutely talentless and carelessly.', 'Mostly Positive', 73.68, 4.92, 5.03);
INSERT INTO reviews VALUES (3155, 347560, 374, 'why i buy this game', 'It''s your run-of-the-mill abandonware. Which is a shame because it does seem to have potential.\n\nSeriously though, don''t bother. It''s just an unfinished & unpolished intro to a story.', 'Mixed', 67.91, 4.55, 3.48);
INSERT INTO reviews VALUES (3158, 347610, 180, 'It''s one that I have replayed many times, mostly because it doesn''t suck', 'Well, three out of four games crashed my entire computer multiple times, so no, I don''t really think I can recommend this.', 'Very Positive', 94.44, 146.67, 10.75);
INSERT INTO reviews VALUES (3159, 347620, 199, '✧˖°. ⋆｡˚(✿ᴗ͈ˬᴗ͈)｡･:*˚:✧｡', '你是不是有病？买你游戏都快成赛博案底了，不能做能不能别做，整这种dlc出来想干什么？我就想知道你做这种dlc出来还卖钱是图什么？赚的到多少钱？以后遇到国产gal我真得跑，一群弱智做游戏跟没脑子一样', 'Very Positive', 86.93, 7.72, 0.93);
INSERT INTO reviews VALUES (3161, 347670, 400, 'Need a seqeul and multiplayer.', 'I mean ... the game overall is a bit fun but it gets repetitive really fast and the controls are real pain ...', 'Very Positive', 84.50, 11.18, 21.28);
INSERT INTO reviews VALUES (3164, 347710, 108, 'Game is a little old but in a retro way. fun story and the puzles  are fun and get you thinking out of the box.', 'mediocre.', 'Very Positive', 81.48, 5.00, 11.87);
INSERT INTO reviews VALUES (3165, 347720, 556, 'This game is probably the least sincere, awful looking, and weirdest thing I''ve ever played.\n\nAnd then it somehow becomes the most sincere, strangely wonderful looking and *WEIRDEST* thing I''ve ever played.\n\nRock on, Soda Drinker Pro. You''re one in a million', 'The game is fine, but the moronic VA keeps calling it "soda" when every rational person calls it by its real name POP! If someone calls it soda they should be drug out into the street and skinned alive. it''s POP not soda!', 'Very Positive', 94.42, 3.80, 6.77);
INSERT INTO reviews VALUES (3168, 347800, 624, 'As a metroidvania, it''s ok.\nAs a mysterious and atmospheric experience, it''s great.\nAs the achievement of a solo dev, it''s outstanding.', 'Dont understand the hype for this ... the art and music and atmosphere are all well done but the core gameplay mechanics of exploration and combat are so bad, and it ends in a crappy "what?"-style anti-climax that just craps all over your character.\r\n\r\nThere is so much forced backtracking with poorly placed fast travel. Most of your combat will be spent dashing in hyper-armor waiting for your guns to come off cooldown. The map is designed in a way as to not show what is in the rooms, even though', 'Very Positive', 85.26, 11.02, 10.25);
INSERT INTO reviews VALUES (3171, 347940, 287, 'I have 0 recollection of buying or playing this game. Wtf? \n\nIt looks really great and the fact I just noticed the dev is back into the project it''s getting me hyped!\n\nJust giving a thumbs up in hopes it continues and encourage more work on it!\n\n', 'Pretty sure the dev''s have given up on the project and just plan on collecting money until the game just falls into the blackhole that is the steam store. I do not reccomend this game until the devs return and start updating it again. I''ll review again when the game goes further.', 'Mixed', 68.29, 13.88, 12.80);
INSERT INTO reviews VALUES (3176, 348200, 436, 'Finally after a decade of having this, I figured out why it''s incredible...  it just works!  You can write text into it, save it as different chapters (like tabs) and have a Steam Cloud powered saving text editor ready for whatever typing needs you have, and setting the background image to my window is also a great feature --- the editor''s colours can also be customised quite a bit to make it just perfect.  You can pin this to the Windows taskbar and open it instantly without any launcher or spl', 'No autosave? Seriously?', 'Very Positive', 88.53, 616.43, 33.27);
INSERT INTO reviews VALUES (3181, 348300, 109, 'Chip''s Challenge 2 is a tile-based action-puzzle game. It improves on its predecessor in pretty much every way.\n\nLike the first game, you navigate Chip (and this time, in some levels, his girlfriend Melinda, with slightly different mechanics) through a level, avoiding deterministically-moving enemies and collecting computer chips to open the gate to the exit.\n\nI recommend trying Chip''s Challenge 1 first (it''s free). If you like the overall concept, you''ll like Chip''s Challenge 2. It has better l', 'I really wanted to like this game. I generally enjoyed the first, even with some annoying levels, and this was pretty cheap so it seemed worth a shot. And admittedly, there are some good moments here, especially with being able to drop items on the ground. Being able to move teleporters was a fun idea too. The game shines when it uses some clever combinations of this.\r\n\r\nThe problem is that there''s a solid amount of levels with serious problems. Hiding things that will kill you underneath blocks', 'Very Positive', 87.16, 56.47, 18.60);
INSERT INTO reviews VALUES (3183, 348360, 401, 'I am smol BIG brain.', 'It''s pretty boring and a slog to 100%. The game is very repetitive and has you unlocking the same elements over and over again across all of the different episodes and quests. Some of the unlocks are pretty clever and creative with how you combine things, but most of the time this game is really boring and I just rushed to completion.\r\n\r\n5/10', 'Mostly Positive', 74.06, 6.98, 3.12);
INSERT INTO reviews VALUES (3190, 348510, 225, 'silly game with silly mechanics. i had a fun time only pulling over women, illegally arresting them, and killing innocents who did nothing wrong!', 'so boring ;(', 'Mostly Negative', 33.78, 0.50, 0.42);
INSERT INTO reviews VALUES (3192, 348550, 3770, 'alright hear me out hear me out\r\n\r\n\r\n\r\nwhat if there was a second sol badguy', 'anime coomer gimmicky spam fest', 'Overwhelmingly Positive', 97.59, 9.05, 42.77);
INSERT INTO reviews VALUES (3197, 348670, 203, 'Time to make a review for this game \n\nThe game is kinda great wish the devs could work on it a bit more needs to have alot of improvement like the controls of the game and the movements of the character and they should remake the game design if they can then i would really spend money on this game over all i rate it 5.1/10 its great', 'Getting straight to the point, this game is not worth buying in current state. However, the devs are planning on doing a lot of nice things. Definitely will try again when made F2P.', 'Mixed', 54.68, 3.65, 3.37);
INSERT INTO reviews VALUES (3207, 348910, 112, 'Really nice solitaire game just like the previous one they made.\n\nIf you care about getting all the achievements you will have to beat the game 3 times which can be a bit annoying, especially if done in a short time period, but if you take your time with it, it should be fine.\n\nLinux version of the game works without any issues.', 'If you buy a game with "faery solitaire" in the title, you shouldn''t  expect innovative, mind-blowing gameplay. I didn''t and would have been quite happy if this one was basically a copy paste of the older ones. The originals had a silly story,  some pictures and a solitaire. It''s something to do inbetween dealing with global crises. \n\nThis one hasn''t got solitaire... it''s a simple matching game with a vindictive rng that likes cards with the same pictures stacked neatly on top of eachother. Inst', 'Mostly Positive', 79.46, 40.47, 10.00);
INSERT INTO reviews VALUES (3213, 349040, 16691, 'According to statistics, every 2 owners of this game became Hokage', 'Well, I can''t recommend this game anymore. Not because it''s bad. It''s great! But a Steam update broke DLC validation for this specific game somehow, apparently, so you don''t get to use any of the DLC you own for it.\n\nTo make things worse, if you try to load the game with an old savefile from back when the DLC worked, the game will tell you you have to **delete the save** and start over to continue.\n\nThis shit sucks but I guarantee that BADGAI SCAMCO will never put forth the money and effort to f', 'Very Positive', 90.47, 7.07, 52.08);
INSERT INTO reviews VALUES (3216, 349140, 121, 'Corrosion: Cold Winter Waiting \n\nHas a total of 5 trading cards.', 'I tried it on two separate occasions, got to roughly the same point each time (very early in the game, I think) gave up and ended up letting it idle for the trading cards. This is just too dated for me, I think. There is a detailed guide available, and it sounds like anyone who wants to play this is going to get acquainted with it. I respect the work that goes into something like this but I just can''t recommend it.', 'Mostly Positive', 70.25, 1.28, 3.73);
INSERT INTO reviews VALUES (3219, 349220, 438, 'An interesting and unique game with lots of ways to research and obtain info. It does give you the option to have higher levels of gameplay but they require more of your personal info so not for me. Still there is lots to do and sometimes can be a bit difficult. Overall a fun game which makes you sort of feel like your an agent. \r\n', 'If you would value your real life time not being interrupted, and your right to not have to disclose your personal information, then do not buy this game. If that type of stuff doesn''t matter to you, then go ahead, it looks like it could have been a fun game. For me, I have no time to allocate to an advanced form of LARPing.\n\nEdit: Personal information includes email, phone number just to go from lowest clearance to the next clearance level.\n\nEdit 2: Previously had  "and home/mailing address" af', 'Very Positive', 87.44, 13.80, 0.25);
INSERT INTO reviews VALUES (3221, 349250, 277, 'I do not say this lightly: Copy Kitty is one of the greatest games I''ve ever played.\n\nI can''t remember the last time a game consistently made me so happy, while leaving no doubt in my mind that the devs made it with genuine enthusiasm and passion. They thought of everything, went the extra mile, and just kept going and going! Play as both characters on normal and hard, play all the endless modes, the boss rushes... All of it is worth it. I can''t even tell you why exactly, because it''s a spoiler.', 'Controls are really bad, graphics are somewhat ok, enemies are bad too.', 'Overwhelmingly Positive', 98.56, 106.07, 0.25);
INSERT INTO reviews VALUES (3223, 349270, 167, 'This game was originally going to be called "Depressed/ADHD/Gender Non-Conforming Norwegian Living In Late Stage Capitalism Simulator" but they had to shorten that down to "Mosaic"', 'blip.. blop.. blip.. blop.. blip.. blop.........', 'Mostly Positive', 76.05, 3.42, 10.13);
INSERT INTO reviews VALUES (3230, 349500, 243, 'fun little time killer with an interesting ans funny story\r\n', 'Doesn''t leave you any room to breathe', 'Mostly Positive', 79.42, 7.53, 0.63);
INSERT INTO reviews VALUES (3242, 349790, 194, 'I will say that this one gets tedious even for me after a while, and I have to take a break. I do love the game design, though. You can build your own missions, and you can choose your own skills, after a certain level. You have a nice selection of choices for your character construction, too. \r\n\r\nI''ve more than gotten my money''s worth of entertainment from this game, and will get more in the future. That sounds strange in English. LOL', 'Too painful to play.', 'Mixed', 60.31, 3.28, 0.42);
INSERT INTO reviews VALUES (3248, 350010, 167, 'Hidden Object, Strategy, Mini Games, Time Travel, Story line  - This game has it all. Interesting but same -o  every level starts the same but different encounters. Different Characters but Main character is connected to all in some way. I just kept playing, it keeps drawing you in. Usually, I play awhile then come back. This one I played and came back twice I just couldn''t stop.', 'One of the most uninspired HO games I''ve played. There is way too many HO scenes and they are not really well balanced, some of the first ones are brutal in difficulty while the last ones seemed much easier. Also, expect to play the same one 7 times or so with different arrengements.\r\n\r\nThe flow is weird, you will have cutscenes that end abruptly and start with something else immediately. The characters look like a fever dream when the are animated. I guess they were modeled in 3D and then creat', 'Mixed', 47.90, 10.68, 3.12);
INSERT INTO reviews VALUES (3250, 350070, 1080, 'The developer went and fixed the game and added achievements even almost 10 years after release. If that''s not dedication and deserving of respect, I don''t know what is! Truly a labor of love.\n\nIt also helps that the game is just as good, with an atmosphere that''s almost unmatched in indie Metroidvanias. There''s that constant feeling of something genuinely being off, and I love it. Looking forward to ESA 2!', 'I tried really hard to like this game, but it frustrated me too many times. First, the hook shot is quite finicky, which sucks because you have to use it a LOT. Like, constantly. After falling during a very long hook shot sequence ten times in a row and having to start all over again, you start to get annoyed.\n\nSecond, the combat is brutal, and though there is a difficulty selector, you can''t change it after creating your save file, so you''d better hope you guessed the correct difficulty before ', 'Very Positive', 83.61, 37.85, 5.45);
INSERT INTO reviews VALUES (3251, 350080, 8135, '"Wolfenstein: The Old Blood" is a great addition to the series and has more action and gore than New Order, has improved stealth but Old Blood might feel too linear and there''s no character depth like we saw in New Order. In Old Blood it''s a very linear story-line and even the gameplay is shorter than New Order. If you remove the time it takes to complete all achievements and collectibles, this game will be completed in just 6-7 hrs or so. Hence in terms of story-line Old Blood took a hit but th', 'I love Wolfenstein: The New Order, and have earned all the achievements in it, but this game sets you up for one of the worst stealth missions I have ever played and I just cannot bring myself to play more of it.', 'Very Positive', 88.89, 38.23, 0.62);
INSERT INTO reviews VALUES (3253, 350110, 197, 'Easy game to learn, hard game to master. If you like Business, Sims, Strategy. Then this is the game for you. Real ships, ports and freight. Real consequences for bad decisions and rewards for good decision.', 'The 2nd game is 60% a copy of part 1, but it''s a shame that they removed the sailing a ship yourself or put it out of sight', 'Mixed', 49.75, 361.30, 0.17);
INSERT INTO reviews VALUES (3260, 350500, 109, 'old man sam has purry form', 'Installed it, played it for a bit and uninstalled it.\nTheres just not that much here.\n\n Adding ''unlockables'' dosen''t make it a 10 hour experience, it just means you have to play for longer to get what little is there.', 'Mixed', 51.38, 18.73, 0.82);
INSERT INTO reviews VALUES (3267, 350640, 2681, 'First and foremost, it''s important to note that, while skipping mini-games or OTEs is available in this game, doing so will result in missing their associated achievements. \n\nSo, if you''re aiming for 100% completion, don’t skip them and remember that those tasks need to be completed manually; otherwise, you’ll end up wasting a massive amount of time replaying them later on (trust me, I learned this the hard way T^T).\n\nThis is one of the easiest games in the Sherlock Holmes series. It''s great for', 'Not Worth It. The Prequel had great optimization but this one was having a lot of frame drops and stutters so it ruined my experience.', 'Mostly Positive', 78.81, 32.10, 5.03);
INSERT INTO reviews VALUES (3270, 350740, 330, 'Awsome game. i play it with my 9 years old daughter and we have a lot of fun (and she is good !)', 'Lol this game sucks... boring and repetitive... just stand in one area and kill bugs... no exploration, no secrets to uncover... good thing it''s only 1.50$', 'Very Positive', 89.39, 31.32, 0.12);
INSERT INTO reviews VALUES (3271, 350770, 108, 'overall a decent 2d plataform its colorfull and fun most of the time there are moments the game have very cheap moments like level 7-7 but its also fair give you 5 lives on the stage you left so there is not game over also there is the retro based level overall a good game for retro 2d plataform lovers', 'Giana Sisters 2D is a pretty bad platformer. The character designs are cute and the soundtrack is peppy, but that''s unfortunately where the positive points come to a screeching halt. \n\nIt quickly becomes apparent just how one-note and basic the level design is, once you''ve played a couple levels you''ve seen all the game has to offer, including the boss! Because the game makes you fight the exact same boss with the exact same mechanics after each of the 8 worlds. The platforming ranges from piss ', 'Mixed', 53.70, 3.13, 2.97);
INSERT INTO reviews VALUES (3272, 350780, 119, 'This game is pretty charming, if a bit rough-edged. If you''re familiar with the AVGN games, then the game feel will be familiar- this walked so they could run. The cutscene art is fantastic, with very solid spritework as well- all the gags were very readable & charming. All this to say that this game was almost impossible to play on my PC & I lucked out that my Steam Deck could run it.\n\nBelow is my original review.\n\nI would love to recommend this game, but it''s unfortunately unplayable for me. I', 'This is so lame.  Even a decade ago, it would''ve felt like nothing but hack references but playing it in 2024 shows how shallow and thoughtless the entire game is.  It''s probably one of the worst games I have in my entire library.  Yowza, how does this have any positive reviews at all?', 'Very Positive', 85.71, 0.87, 0.28);
INSERT INTO reviews VALUES (3276, 350910, 417, ' Man I wish there was a game where I can beat up people on the streets while being Nostalgia Critic.\n\n', 'Poorly thought out meme game. Annoying lanes lock you into fighting only certain groups of enemies, and enemies are really bad about coming after you. They''d rather wait in whichever lane you''re not in, grouping up such that they can strike you if you try to hop over to join them.\n\nThis beatemup has blocking for the obvious reason that enemy encounters are designed for mashing. Spacing and orientation are less of a priority than filling up the screen with enemies, many of whom can ignore hits of', 'Overwhelmingly Positive', 96.88, 1.12, 0.82);
INSERT INTO reviews VALUES (3279, 351030, 283, 'I really am enjoying Pixel Puzzles, it''s one of those games that kind of sneaks up on you and turns out to be much more fun than you expected.  While it is a free game with downloadable content in the form of extra puzzles there is plenty in the base game to keep you busy and the new content is pretty good and certainly adds to the game.  Would recommend this for anyone that is a fan of jigsaw puzzles, puzzles in general or just wants to play something a little different.', 'Stop adding achievements without a possibility to earn them!', 'Very Positive', 80.21, 42.70, 1716.42);
INSERT INTO reviews VALUES (3283, 351090, 444, 'I don''t know who decided bridge and Bridgerton needed to have a baby, but that person is a genius.', 'I would rate this neither if i could.\r\n\r\nIf you''re itching for solitaire and have not played many of the modern versions of it, this one is not bad.\r\nBut it''s nothing special either.\r\n\r\nThe story line is pretty unnecessary as there is nothing about it that actually plays into the mechanisms of the game. There are only 2 really, find the key(s) to open locked stacks and clear an amount of royal cards to unlock stacks. There are also stage "challenges" that increase this difficulty: usually gettin', 'Overwhelmingly Positive', 97.30, 14.57, 11.52);
INSERT INTO reviews VALUES (3284, 351100, 453, 'rpg roam around barbarian chop trees collect resources food items for potions, wood, mine for ore to build armor and equipment, build buildings castle furnace oven, sawmill distiller for potions, defend your castle, from skeletons and other barbarians, kill other barbarians, kill wolves buffalo bear spiders skeletons trolls, wolves sheep and other stuff, trap animals for skins of sheep whool, do quests collect items to fullfill quest criteria, fun little game.', 'Game has very nice artwork and a fun concept, but requires too much grinding to even stay at the same level without losing progress. It''s possible to get completely stuck due to resources being finite and the incredibly high rate at which armor, weapons and tools wear out.\r\n\r\nExamples:\r\n-  a full set of iron armor will break after fighting only a handful of wolves. But crafting a new set of iron armor requires... several wolf hides!!! There is hardly any net gain.\r\n- Boss fights will deplete you', 'Mixed', 67.99, 67.02, 5.53);
INSERT INTO reviews VALUES (3286, 351150, 219, '\nI liek 2 play wit my crayons.\n', 'I like the artstyle and the character, but unfortunately the game keeps crashing for me on the 4th boss. I''ve tried lots of stuff to try to get it to not crash but none of them work (admin mode, verifying files, lower resolution, turn off music/sounds, etc.) The game spikes in memory use before the crash. It happened on Toxic 3 too but that one resolved itself after the second load.\nIf the game didn''t have this severe crashing issue I would likely rate positive if the crashing is fixed, even if ', 'Mixed', 69.41, 2.88, 2.20);
INSERT INTO reviews VALUES (3287, 351160, 294, 'This game is amazing.\r\nFrom the gameplay to the lore, this game is for casual and hardcore gamers alike. The lore is extremely rich and deep and it will keep you invested. I recommend this to anyone.', 'enjoyed the game up untill 87 hours in the game, where my progress just gets deleted as if i never played the game.', 'Mostly Positive', 73.81, 131.35, 87.32);
INSERT INTO reviews VALUES (3290, 351230, 101, 'nothing fancy but a good fun/cost ratio for me.', 'There''s a lot of awful designs in this game. I casted a blizzard spell (I believe) and it completely obscures the entire screen in sparkly stars to name one. Wow.\n\nThe game is very unfun if you want to play it seriously. It''s better to just mess around with it with a friend if anything.\n\nEdit: I see a couple of people disagreeing with my review, so I''ll be a little more in depth. I reviewed this game during the time it was not "reforged". So my review does not reflect the state of the game prese', 'Very Positive', 86.14, 21.17, 0.55);
INSERT INTO reviews VALUES (3292, 351290, 2428, 'Used to play this game back in the day miss those old days', 'gAME Is pOTAt0', 'Mixed', 47.82, 21.82, 0.27);
INSERT INTO reviews VALUES (3296, 351340, 300, 'Very short, the whole game plot is felt like the beginning of something reals... for just getting to sudden end. Game is playable and rather pleasant but don''t overpay for it, buy only with a good discount.', 'A simple point-and-click game inspired by the Gothic, Frankenstein specifically and with a few references to the ideas of Romanticism. There is a lot of reading to do for such a short game; this doesn''t bother me, but it might to someone else. So, there''s a lot of story to the game but the puzzles are not very engaging.\n\nPros: Spooky art style and lesbians are always a win for me. The soundtrack is nice and melancholic, not much variety, but I liked it.\n\nCons: The gameplay and puzzles are simple', 'Mostly Positive', 71.33, 1.62, 2.48);
INSERT INTO reviews VALUES (3302, 351480, 206, 'It''s First Edition Dungeons and Dragons laid out for you, but with a DM who takes no prisoners and gives nothing away. It''s a combination of RPG and Wargame in which you can take the glory when everything goes right, but you also get a kicking when it all goes pear-shaped. You can choose to buy the entire package at a suitable discount during a sale, or pick at the individual adventures. Either way, you get a huge amount of simple content that you can return to not too long after your first rage', 'Most annoying game ever!\r\n\r\nArchers never hit, have no health, and no defence.  They are useless.  Then you run into a scenario where if you don''t have a bunch of them, the enemy sappers will slaughter all your troops with no chance to win at all.  \r\n\r\nThen later on, after restarting the game so you can kill the sappers, you run into enemies that can charm your elite troops and you are forced to slaughter your own best troops.\r\n\r\nDon''t bother with this shity game!', 'Very Positive', 91.75, 7.50, 6.27);
INSERT INTO reviews VALUES (3303, 351490, 385, 'intergalactic Bubbles is the best game that has ever been created. I recommend buying this and playing as much as you can. The fact the game runs natively on GNU+Linux is all you need to know.', 'I played the Linux version of the game exclusively so I have no idea if the Windows one has the same problem, but the game is really bad at recognizing that you matched 3 balls of the same color which is just a little tiny bit of a problem for a match 3 game. The graphic could be a bit better too.\n\nThat aside it is nice to play a match 3 from a different perspective than the usual ones, shame it is not better.', 'Mostly Positive', 78.44, 13.22, 20.23);
INSERT INTO reviews VALUES (3304, 351510, 890, 'Racism has been given a point system', 'i dont lke it', 'Very Positive', 93.82, 0.12, 22.38);
INSERT INTO reviews VALUES (3308, 351700, 957, 'It''s really fun to be an iron age Finnish man surviving against the elements. \r\nJust needs more music or forest ambience playing in the background.\r\n\r\nBe warned: You must have powerful autism to enjoy this game', 'I''m sure this is a good survival simulation but I''ll probably never find out.  I haven''t had to memorize a bunch of keyboard commands since the early 90''s.  The user interface is just way too clunky to engage my interest any further.  Bring it up to, say, an early 2010''s interface and I''ll take a look again.  Game on!', 'Very Positive', 93.63, 167.10, 3.38);
INSERT INTO reviews VALUES (3315, 351860, 179, 'This is the most nostalgic game from my childhood. I enjoyed every second of it. A true classic!', 'Brilliant, underrated game.\n\nThis was my first game ever played. I perfectly remember how amazing the simulation and the city building was. Not even Settlers had the intricacies that Cultures has.\n\nThis is presumably the 2''nd game in the Cultures series although not shown explicitly anywhere. I did not find the original around, unless taking the GOG version.\n\nThis is the ultimate society simulation and city building strategy game. People live, work, die - of old age, hunger. Each person has a pr', 'Mostly Positive', 76.54, 0.08, 4.57);
INSERT INTO reviews VALUES (3316, 351870, 117, 'good game, just dont alt tab\r\n\r\n\r\n\r\nif you do make that mistake, change the resolution and change it back, it does fix it :)', 'Sadly does not even load for me on Win10.  Game complains that it requires DirectX7 and won''t start.\nHave tried all compatibility modes with no luck and not much about the error when I search online.\n\nCannot recommend for people on Win10 64bit.\n\nStill, only cost me 80p or something so there''s that.', 'Very Positive', 81.20, 13.17, 0.15);
INSERT INTO reviews VALUES (3317, 351900, 173, 'I''ve been waiting 9 months for this game!', 'Just save your money.  I know this game only costs the same as a cup of coffee at Starbucks, but seriously... get the coffee.  You''ll enjoy it far more.  I only bought this game because somebody else linked me to it, and I thought to myself "What in the holy hell?  This has got to be the most terrible idea for a game ever."  So naturally I bought it, so I could review it for some friends.  Sadly enough, it still wasn''t the worst game I''ve ever played... but damned if they didn''t aim for the titl', 'Mixed', 54.91, 0.65, 0.47);
INSERT INTO reviews VALUES (3318, 351910, 227, 'my fave game. Just lack replayability. Overall, good game', 'Boring game. You sit for a very long time, waiting for resources to be farmed for you. There is no interaction with NPCs.', 'Mixed', 54.19, 44.80, 5.27);
INSERT INTO reviews VALUES (3319, 351920, 2401, 'This game is... ok, I guess.\n\nIt reminds me of the old Incredible Machine games that I played in the 90s.  (Yes, I''m old.)  But it lacks the same character, and the interface is quite lacking.\n\nConnecting the different parts of the machines can be fickle, and gears are really annoying (trying to match the teeth up to get it to fit).  However, they''re decently fun puzzles, and the machines are mildly entertaining.\n\nIt''s currently on sale for $0.99 (90% off), and I''d say it''s worth that price.  I ', 'actually kindve impressive how horribly it runs for how simple it is', 'Very Positive', 93.54, 2.20, 1.95);
INSERT INTO reviews VALUES (3320, 351940, 338, 'To be honest, i am kinda of impressed with this game. The history that this game is based on is simply amazing. I was just anxious to get to the next episode every time. The graphics are cartoon type and the history deppends on the choices you make. Every choice you make will have consequences on how the game progresses and what will be the end of the game. I highly recommend this game, buy the other episodes, it is worth it!', 'I would describe most of the game as busywork to get from point A to whatever point they''re tryna make with the story, everything here is sloppy and can''t be bothered to even try to be looked into.', 'Mostly Positive', 74.56, 7.52, 9.45);
INSERT INTO reviews VALUES (3321, 351970, 3501, 'My first game in the Tales series. It has a beautiful story and a sad ending. I hope that the other games in the series will be as this one.', 'Honestly I have tried to play this game like 5 times but everytime i come to the same conclusion...its just...meh.\nThe game play loop is uninteresting, the overland travel is sluggish, and the story isn''t really exciting.', 'Mostly Positive', 78.46, 203.07, 12.88);
INSERT INTO reviews VALUES (3333, 352220, 306, 'what need have i for other games when this one exists?', 'The game explains it self very poorly you''ll need a lot of patience and I believe 8 hours is enough for me.\r\nSome of your actions and choices are very un-clear as to the result.\r\nReading the manuel does not clear some stuff up.\r\n', 'Mostly Positive', 78.76, 352.88, 8.45);
INSERT INTO reviews VALUES (3334, 352240, 109, 'A nice little game to play. It''s a bit short but when the game costs 0$ can''t really complain about the length.', 'Look at the time i spent playing this game. Yup, that is a single playthrough. 12 turns, that is all.\n\nReplay value seems minor as there are hard repurcussions for extremes, so there is no Papers Please-esque payoff to certain actions. \n\nThat said, this game has a lot of potential, and if the gameplay lasted for longer than 12 weeks (turns) i would be able to recommend this game. \n\nAs it is now, however, why would i pay 10 euro for a game that entertains me for a shorter time than most Youtube c', 'Mixed', 60.55, 10.20, 0.42);
INSERT INTO reviews VALUES (3340, 352400, 3010, 'great game, this deserves a sequel covering the entire franchise when Jurassic world rebirth comes out', '"Lego Jurassic World" is standard Lego fair but lacks the charm and care of the previous entries. There are a lot of references for "JP" fans but overall the game felt like it was going through the motions. I do like "Jurassic Park" but I have to wonder if it was a good fit for a Lego game then again ''Indian Jones" worked well. \n\n   "Lego Jurassic World" is quite a janky experience that really could have used more polish. The game has glitches which is fine but the abundance of them is the probl', 'Very Positive', 89.34, 92.07, 26.03);
INSERT INTO reviews VALUES (3341, 352430, 126, 'It''s kind of like an Early Access 3D FPS Factorio, without the Alien Insects. \n\nIt''s not quite there yet. Lots of bugs. Random crashes. Missing content. ( Early-Access ) It can get a bit grindy at times. But I have seen regular updates, so there is hope.\n\nFor me? $15 - $20 is the price I pay to go the movies for a couple hours entertainment. I figure I got my moneys worth out of this game. So as long as they keep working on it, I''ll give it a thumbs up.\n\nThat said, If $15 is your entire gaming b', 'I have played a number of games like this.  I held off on a review in hopes it would be developed more.  6 years after they launched, this game is apparently abandoned.  The game is a mess.  It is not fun.  It is a complete waste of money.  I got it cheap, so I kept it instead of demanding a refund in hopes it would become something.  That was a mistake.  DO NOT BUY.', 'Mixed', 57.14, 18.28, 0.68);
INSERT INTO reviews VALUES (3344, 352520, 2713, 'The Silent Age is a good point & click game. It''s a great story, the puzzles are not too difficult to solve, the graphics are nice and the ambiant is weird. I recommend it!!! 💗💗💗', 'The mystery at hand, simple puzzles, and time travel mechanic was just enough to pull me through to the conclusion. I did like the environmental art, the audio, and the ambiance they created together. In the end however, it was unsatisfying to complete the story arc. Of particular disappointment, the voice acting of the protagonist was the weakest of the cast and really put a dampener on my immersion - repeated faux stuttering was enough to cause a grimace or two. It’s a 4/10 from me unfortunate', 'Very Positive', 93.22, 38.97, 3.98);
INSERT INTO reviews VALUES (3346, 352550, 736, 'I really wanted Urban Empire to be a different game than it was. \r\n\r\nFirst some positives: The UI is really beautiful (although difficult to navigate) and everything looks pretty great overall until you try to move the camera around. I loved the concept of needing to manage political factions that morph, wax and wane over time! I also really enjoyed the core mechanic of managing player-defined districts. Some really cool ideas.\r\n\r\nSadly, it falls a little short. The game runs fitfully, and I''m n', 'It''s an unfinished and abandoned game. It crashes half the time. Steam should remove this game. It is a ripoff. Probably won''t waste my money on anything else from steam because of this.', 'Mostly Negative', 28.12, 37.13, 34.28);
INSERT INTO reviews VALUES (3348, 352610, 117, 'While there isn''t much horror to this VN, with only a handful of the 21 endings leading to our MC''s unfortunate demise. And for the most part the horror doesn''t happen until the later part of those routes. But behind all that is a touching, and sometimes depressing, story about friendship with all the complicated feeling intertwined all stemming from a few miscommunications.\n\nThere is quite a lot of padding and build up, but for me it didn''t feel like it took away too much from the story. It kep', 'it has some really cool moments and is a fun homage to higurashi if you''ve played that, but the page says horror/romance when it is absolutely 90% romance and maybe 10% horror at best. others will like it, but that kinda split really doesn''t interest me', 'Very Positive', 88.03, 47.68, 3.73);
INSERT INTO reviews VALUES (3352, 352720, 4868, 'Incredibly slow. And natural disasters can kill a game. Played for about 7 hours and my population platued. Hit a fire storm and lost half my pops because they couldnt get to the bunkers in time.\n\nIts fun and Im going to try again but can''t recommend until there is a way to go beyond x2 time. With parts of the game being a 20-30 minute waiting period this game is fun but plan to have it up on a second monitor while you watch TV on another screen. Leaving a positive review because it is good, but', 'I wanted to like this game. I''m a huge fan of every genre this game embodies, but this game is very unpolished, almost as though it''s unfinished, and suffers from a lot of bugs. Additionally it''s poorly optimized, and playing is a very frustrating and punishing experience. I couldn''t recommend it for the full price, maybe if it were on sale for under $10. It had a lot of potential, but it''s under-cooked.', 'Very Positive', 80.81, 13.75, 33.88);
INSERT INTO reviews VALUES (3356, 352780, 209, 'I wish I had played this sooner. The opening scene starts with a banger soundtrack and a fascinating magic system, which both lead to an immersion I don''t really think the marketing captures. One small downpoint is that the controls are pretty mouse focused - you can''t navigate the screen with keyboard/controller buttons. I definitely think this game is worth playing!\n\nI should note that the story comes with some seriously mature and adult themes, which as one of the characters (E.) should show ', 'I could not get invested in the story or the characters outside of the Franz. Elise makes no believable actions for either of the longer two endings. I want the time spent reading through all of the dialogue back. The fast forward option stops on its own in random spots and doesn''t even work at times when it should.', 'Mostly Positive', 79.90, 5.22, 4.88);
INSERT INTO reviews VALUES (3360, 352890, 191, 'Caravan\n\nHas a total of 6 trading cards.\n', 'Wasting time and money due to the randomness of events and you cannot predict and take precautions to prevent these events. No matter how hard you try, you will reach a point where you will restart the game from the last save checkpoint.', 'Mostly Positive', 72.25, 0.87, 11.55);
INSERT INTO reviews VALUES (3362, 352950, 231, 'Warning, if you jump to high, this game becomes a limp simulator 10/10 would limp again!', 'I sometimes play games with bad reviews basically as case studies and usually I get to find something not horrible or not as bad as expected, but damn, if you don''t get anything good at all in the first 30 - 45 minutes of a game, like NOTHING at all, it probably won''t give you sometime good enough in the next hour or two to be able to compensate the time invested.\n\nO also, perfomance wise it awful.', 'Mostly Negative', 28.14, 0.22, 0.67);
INSERT INTO reviews VALUES (3365, 353090, 465, 'Changed the way I see life, and chickens too', 'As a fan of the Chicken Invaders series, i was quite disappointed with this entry. Even though it''s more of the same -which is good- there are some changes this time around which harm the enjoyment a lot more than they help it. \nExtending a theme from CI4, your ship often rotates (not freely) to add some variety to the levels, but this time around there is a stronger emphasis on pointing you the wrong way and making you wait until you''re able to shoot the remaining foes. Furthermore there is an ', 'Overwhelmingly Positive', 96.56, 7.45, 15.05);
INSERT INTO reviews VALUES (3370, 353330, 587, 'wholesome and cute i want to lick sachis eye', 'This game is total CR**...  Don''t bother wasting your time OR MONEY.  The ONLY REDEEMING QUALITY is the artwork of Sachi.. It''s cute.\r\n\r\nStory is almost a ZERO out of 10.  And you can tell that besides Sachi''s artwork no love was put in making this game.  EVEN the developer confesses that it was a rush job, and he hated doing it after he started, AND that he had to meet a deadline so basically he just spewed out trash.\r\n\r\n0/10.', 'Very Positive', 94.38, 3.43, 4.15);
INSERT INTO reviews VALUES (3373, 353380, 3690, 'what the hell its $1 right now with the ICEY bundle lol, go grab it!\n\nEDIT: during the time i posted this there was a deal going on but it is now no longer available...i say if you can get this on sale like i did for around $20, then its a definite buy if your confident in your internet connection', 'I think the video quality and lag are fine and and the ability to remotely control my desktop to open a web browser was a nice suprise. When it works its great but a lot  of games I''ve tried end up having problems and most sessions involve me bouncing back and forth from my living room to my den to see why the video stopped updating or the audio muted..\n\nEventually it might get there but currently its way too unstable and every new steam update seems to introduce a new and different set of probl', 'Mostly Positive', 73.31, 0.00, 0.00);
INSERT INTO reviews VALUES (3374, 353540, 972, 'If you get frustrated with the difficulty, just remember that the dumber you are, the more value you get for your dollar!', 'If you played Baba is you, Can of Wormholes, and Patrick''s Parabox, this game may (or may not) be up your alley \n\nFor me however I couldn''t get into it. There was no puzzley "ah ha!" moment for me. It just feels like a claustrophobia simulator.', 'Overwhelmingly Positive', 97.02, 24.73, 0.72);
INSERT INTO reviews VALUES (3375, 353550, 258, '⠀', 'A dull, confusing puzzle game with repetitive mechanics, poor storytelling, and minimal engagement', 'Mixed', 63.18, 6.38, 1.92);
INSERT INTO reviews VALUES (3376, 353560, 2029, 'This is about what love is.', 'sir i thought this was a puzzle game', 'Very Positive', 84.87, 0.13, 0.23);
INSERT INTO reviews VALUES (3381, 353640, 1222, 'This game... makes me so UNBELIEVABLY ANGRY! I hate this game SO MUCH. BUT I CANNOT STOP PLAYING IT. EVERYTHING IS FINE UNTIL U MISS A SINGLE TURN AND THEN EVERYTHING BACKS UP AND THE TRAINS GO EVERYWHERE AND THEY ALL EXPLODE AND YOU. LOSE. This game is 90% rage bait and 9% crying. But that 1% of satisfaction... I think it''s worth it... unless that''s just Stockholm Syndrome', 'This is not a train management sim. Its a time-pressure spinning plates type puzzle game with a notably bad UI. Its track laying and demolition system is just horrendous that they prove to be bigger hindrances than the level''s obstacles. Which is unfortunate since the game is pretty look at and the music is nice but you won''t have time to appreciate it since you cannot build while the game is paused and you have to manually switch tracks to guide each train.\r\n\r\nWhile its a competently made game ', 'Very Positive', 87.81, 17.43, 5.45);
INSERT INTO reviews VALUES (3382, 353700, 596, 'When you buy an Ace Team game, you never really know what you are getting into, but it is always worth it!', 'The game has a lot of charm, the story is imaginative and funny, but the gameplay is very lackluster.\n\nThe combat is extremely bland, and combat is the bulk of the gameplay. All three playable character are identical except for one skill. In order to open a path, you are forced to backtrack because you play as the wrong character.\n\nThe whole game felt like an overstretched Psychonauts level.\n', 'Very Positive', 90.77, 4.80, 5.28);
INSERT INTO reviews VALUES (3392, 354140, 5954, 'this game is over hated for no reason it''s a very fun game and should be more chill then the other five nights at Freddy''s games and I really like the game it''s got some issues like the phantoms are annoying as heck but spring trap is one of the best Character also so exited for him being put in dead by daylight 10/10', 'i have played many games in my lifetime and none of them have been worse than this one. please save yourself $7 and do not touch the game. they don''t even tell you how to play. oh my god, there are so many other things i could''ve done with the last 112 minutes of my life. guys please, i am trying to save you. do not buy this game. the other two FNAF games - BANGERS. this one, TERRIBLE! i don''t know what scott was smokin while playing this game but just listen to me.', 'Very Positive', 89.05, 3.73, 1.78);
INSERT INTO reviews VALUES (3393, 354160, 258, 'WRC 5 is a new beginning for the series, and when viewed in that light, Kylotonn’s efforts come out quite well. There’s several issues, both big and small that detract from the game as a whole, but underneath it all there’s a rallying game that’s just a good bit of fun. When it’s just you and your co-pilot racing through a forest, barely making it through a series of tight twists and turns, that’s really what matter.\n\nhttps://steamcommunity.com/sharedfiles/filedetails/?id=3329598495', 'This game is an absolute mess. Horrible physics, handling and feel. Graphics are worse than I expected. Wrc 4 is definitely a better buy. Well hey, at least this runs great! I constantly got over 300+ fps with a 4060 laptop.', 'Mixed', 64.34, 5.27, 0.20);
INSERT INTO reviews VALUES (3399, 354380, 908, 'better than odyssey and valhalla', 'Shove your piece of shyte launcher deep in your arse and fuck off.', 'Mostly Positive', 70.81, 6.38, 0.10);
INSERT INTO reviews VALUES (3400, 354400, 198, 'An absolute treasure! Tadpole Treble is a brilliant labour of love. The detail that went into this just blows me away! The soundtrack is cracked and you can make your own levels with your own bops after you play through the short but sweet story. Gameplay feels like a mix of dodge''em with some rhythm elements. It felt natural enough to get the hang of and didn''t overstay its welcome. I will say the inconsistency between all the fonts felt more patchwork than polish but the art of everything else', 'I just didn''t enjoy this game. I wanted to, I love the music and the art style but I just didn''t like avoiding so many objects and it didn''t feel like I could get all the bubbles without getting damaged. I play rhythm games to enjoy the music and collect things, maybe it''s just too much of a hybrid for me. I wouldn''t not recommend it, but I wouldn''t recommend it either I suppose?', 'Overwhelmingly Positive', 96.46, 3.98, 0.33);
INSERT INTO reviews VALUES (3401, 354430, 267, 'Make your life easier and grab the XWVM mod(basically, this game ported to the Unity engine.) Easy to setup and can use modern day controllers. Peak Star Wars flight simmming.', 'Selling 30 years old game for 10$ and not giving it keyboard support is just ridiculous...', 'Mostly Positive', 74.91, 3.37, 0.08);
INSERT INTO reviews VALUES (3405, 354680, 293, 'Short but super entertaining, I loved it', 'A short, very easy point and click game that''s set in world that''s a parody of the Victorian era, featuring a posey attitude and alleys that smell like a turd! Sadly, it was a mixed experience.\n\nProtagonist has no personality except that of your average satirical british gentleman, and his accomplice- Gaven, is not a big talker and his only skill and use is that he''s... strong. Unlikeable characters, a big minus.\nPuzzles are also incredibly easy to figure out. Basically you click all the interac', 'Very Positive', 88.05, 1.62, 1.65);
INSERT INTO reviews VALUES (3409, 354740, 111, 'simple throwback. simple story. for anyone who wants a relaxing 90''s rpg experience with all the QOL upgrades.', 'not good', 'Very Positive', 81.08, 8.07, 2.08);
INSERT INTO reviews VALUES (3421, 355050, 749, 'One of the classic vertical shoot ''em up games that''s been revamped for the modern systems.\r\nWill run on modest hardware, and while it isn''t verified, this runs on the Steam Deck without issue.\r\n\r\nGet the Anniversary & Reloaded bundle at sale. Absolutely worth it.', 'Okay. As a sky force veteran myself, there are a lot of things to go over. Now for anyone who has never played this game before, or has only played the mobile game before, there are a lot of issues with the way this game works. \r\n\r\nPros: Grinding-heavy game, fully upgraded plane in one day of grinding (Not optimal if you have a 9-5 or other high time committing activity) No in-game purchases whatsoever.\r\n\r\nCons: No description for cards, the options of turning off autofire don''t seem to work, so', 'Very Positive', 89.72, 12.23, 36.75);
INSERT INTO reviews VALUES (3422, 355060, 268, 'If you want this game to work flawlessly, set the game''s core affinity to only performance cores (for Intel CPUs) and always play in windowed mode. The game also uses FSAA so if you set the anti-aliasing to x8 it''ll use a lot more resources than just FXAA or TAA.\r\n\r\nThe career can get annoyingly difficult with the timed cone challenges, but other than that this game is an underrated gem that has that 90''s era rally feel to it. I have a soft spot for this game.', 'The game is litteraly trash, when you launch it, it just doesnt let you use the up arrow, and when you connect a wheel and try to control the car, it wont even budge, its just pressing accelerate in n gear, and the tutorial is even only ''''forward'''' and ''''backwards'''' as its first steps, it has some potential, but it was thrown away, hopefully it gets fixed, also the game is hard to understand, i litteraly had to ask myself a MILLION TIMES is it a dlc or a game, cause i was scared of losing my gam', 'Mixed', 56.72, 29.18, 0.77);
INSERT INTO reviews VALUES (3427, 355130, 240, 'Want to let know it is working on steamdeck', 'RIDE is superior in every category.', 'Mostly Positive', 79.58, 0.92, 2.78);
INSERT INTO reviews VALUES (3429, 355150, 347, '⠀', 'this is so mysterious and strange\n\nits kind of interesting in concept but in execution it is essentially just lines and a square and some slightly clunky controls', 'Mixed', 45.53, 5.17, 0.27);
INSERT INTO reviews VALUES (3430, 355170, 637, 'A game about a gay couple who saves big foot from a Elvis impersonator.', 'Sam & Max Hit the Guide.', 'Overwhelmingly Positive', 95.45, 6.37, 5.43);
INSERT INTO reviews VALUES (3431, 355180, 140, 'Looked up gay dolphin porn, this came up. Was very pleased.', 'how do i delete games?', 'Very Positive', 85.71, 0.60, 1.10);
INSERT INTO reviews VALUES (3434, 355240, 182, 'It''s never been better than this', 'WHAT THE FLYING TOASTER FUQ?! CONTROLS ARE SO WHACK NO BLOCK BUTTON AND RANGE ATTACK IS USELESS, JUST MASH MELEE.... COOL IDEA EXECUTED TERRIBLY.', 'Very Positive', 82.97, 2.87, 0.53);
INSERT INTO reviews VALUES (3435, 355250, 412, 'I joined the Imperial Navy to drink ice cold blue milk and kick some Rebel ass, and I''m all out of blue milk. Long live the Empire!', 'I''m sure it''s great and all, but trying to find out how to get the controls to work on the Steam Deck is awful. If someone manages to figure out a great control scheme, I''d give it a second shot. If you don''t want to do that, avoid it.', 'Very Positive', 81.31, 21.18, 0.28);
INSERT INTO reviews VALUES (3436, 355270, 132, 'The main character hates Pokemon Mystery Dungeon which ALMOST makes me want to not recommend this game.\n\nBut I do enjoy pretentious four-wall breaking narratives, even if it was sort of a pain in the ass to navigate the clunky city sections.\n\nStill a worthwhile play.\n\nRIP, Clara.', 'The bad: I was disappointed that this isn''t really a game. The entire "game" is on rails, and even many of the interactions yield the same dialogue (or at best a small deviation before returning to the main dialogue), so at best this is the illusion of the game. Honestly writing additional dialogue would not have strained development and would have been pretty easy to do considering the game, so it comes off as lazy. Sure you move the character and press a button to examine things and trigger di', 'Very Positive', 90.91, 1.98, 3.00);
INSERT INTO reviews VALUES (3442, 355400, 123, 'dank childhood', 'Trash', 'Mixed', 62.60, 0.45, 2.10);
INSERT INTO reviews VALUES (3449, 355520, 141, '⠀', 'Not Recommended', 'Very Positive', 82.27, 6.97, 4.00);
INSERT INTO reviews VALUES (3450, 355530, 192, 'A unique way to use RPGMaker.', 'An experimental little game, don''t think it really worked out, but I appreciate the attempt.', 'Very Positive', 84.38, 12.67, 2.02);
INSERT INTO reviews VALUES (3453, 355630, 147, 'LF is another game I got to play on Apple Arcade before with mixed impressions. I couldn’t complete it because the controls felt off, it wasn’t clear how certain controls worked and it got frustrating near world 4 or 5. The steam version was recently on sale for €1,74 and I got curious enough to give it another try. This version feels better but I can’t say for certain nor can I pinpoint clear improvements. The bigger screen definitely makes things easier to spot and the controls feel tighter ev', 'in Spetember 2024 they Posted the Removal Announcement - or just developer decleared he will abandon this game... \n\nIn January 2025 Game still sold on Steam\n\n\nCan not recommend this Developer and this behaivor.', 'Very Positive', 92.52, 9.38, 2.30);
INSERT INTO reviews VALUES (3456, 355680, 261, 'Worth playing, but only on sale. It''s about 6 hours of gameplay and doesn''t have a lot of replay value unless you want to challenge yourself. It''s primarily a puzzle game; figure out the sequence of moves for your character (and their extremely limited action points and inventory) and restart the level if you mess up. The overland journey is atmospheric but has no real story to speak of.', 'The game is quite good. However I would like to say no to Overland for now, because the UI should be much more readable and accessible. It''s painful to learn how and in what situation people are left behind. What are the meaning function of certain items. Are they junk? This helmet block attacks? Hey I got two cars, let''s go team, buckle up! Oh, half of the the team left behind, no two cars option. Anyway, I hope the devs will do the necessary quality of life changes, because it would be a shame', 'Mostly Positive', 75.86, 6.95, 8.10);
INSERT INTO reviews VALUES (3459, 355760, 271, 'This is a art piece. Not a game. \r\nYou launch this to chill, walk around, look at your environment, etc.\r\nYou will do that for nearly 40 minutes', 'Not really a game since there are no rules or ways to score a win. Achievements are based on whether you reached a checkpoint or not as you followed the trail to the mountain peak.', 'Mixed', 51.29, 4.45, 0.88);
INSERT INTO reviews VALUES (3460, 355790, 1917, 'I died and the character in the game told me in the cutscene: "You are ugly and You will never get laid."\nsuper realistic game 10/10', 'This game is impossibly difficult when it comes to being able to parry enemies, even on the easiest difficulty available, if you don''t get the parry timing perfectly, you die in 2 hits. After a frustrating 30 deaths (literally) and reloads to my last check point (i really wanted to give the game a chance and learn how to parry but it was next to impossible, only succeeding once), i gave up and decided this game is far too difficult and not worth the time. Also, When alerting the enemies it takes', 'Very Positive', 83.36, 3.40, 5.33);
INSERT INTO reviews VALUES (3461, 355800, 453, 'A must have in Tower Defense genre.', 'forces online play, but servers down so game is not playable, needs to be removed from store', 'Mostly Positive', 70.42, 120.58, 0.53);
INSERT INTO reviews VALUES (3464, 355860, 228, 'Save got soft locked, looked up ending\r\nStill one of the most original and exciting games I''ve played recently, I hope episode 2 is soon.\r\n\r\nCan''t score as it''s not a full game yet.', 'I got this cause it looked different, was interested in the style. What you get is a pretty easy walking sim with no real puzzle elements.\n\nThey also kept saying the second part would come soon and here were are in 2024.', 'Mixed', 68.42, 2.05, 1.50);
INSERT INTO reviews VALUES (3467, 355970, 357, 'Home Is Where One Starts… May not have the overall polish or the emotional peaks that Gone Home or Dear Ester have, but there is something relatable in its simplicity. Even if your home life wasn’t as turbulent as the narrator’s, many can relate to the desire to escape the community we grew up in. The game gracefully lets you stew in the nostalgia and pain that comes from the passage of time. And shows that you can leave a place but you can’t run from how it’s shaped you.', 'I liked the artistic element of the game but other than that I didn''t liked it that much. When I opened the game there weren''t any objectives or tasks, I had to wander around the map not knowing what my purpose was. Game was not fun, sorry.', 'Mostly Positive', 76.75, 0.12, 1.20);
INSERT INTO reviews VALUES (3468, 355980, 895, 'Dungeon Warfare is a very nice tower defense strategy game in which you have to stop a horde of invading heroes in each level.\n\nTo achieve this goal, you have a variety of traps and weapons at your disposal and combining them in the right places leads to success.\n\nThere are a lot of levels and if they aren''t enough for you, you can create your own.', 'Too easy (beat all the maps I played first try with the 1hp modifier), too slow (even at 4x speed), boring enemies, turrets, maps and upgrades, highly repetitive music, rudimentary graphics (which could easily be ignored if the rest was compelling) and troubled UI ("start game" button blocking map info, can''t zoom out far enough to easily keep an eye on everything, no reason to zoom in). Feels like a gamejam effort with little to offer but an unfulfilled premise.', 'Overwhelmingly Positive', 95.08, 51.62, 0.68);
INSERT INTO reviews VALUES (3471, 356040, 2396, 'I absolutely love this game. I remember it as a kid when it first came out but never played it until a couple months ago and man does it still hit. I''ve heard horrible things about the sequel which is such a shame because I love the gameplay and art style. 10/10 so peak dude', 'a dull game with a lot of aspects that don''t work, this war of mine is far better, similar cost and style', 'Mostly Positive', 76.92, 52.73, 50.80);
INSERT INTO reviews VALUES (3480, 356190, 33213, 'Game is fun, the nemesis system is masterpiece, it is fun, engaging and interactive.\n\nDev is bad, patent the nemesis system, they are st**id, gr**dy, short sighted\n\nEDIT: oops not the dev, but warner bros\n\nEDIT 2: The problem is not the patent itself, but they patented, and just put it asides, no innovation, and also preventing other people from developing something more fun with the mechanic', 'they had to do recent sale because people are boycotting their game since they holding rights to the nemesis system and preventing other companies from making great games with it as well, and they even renwed their patent recentl for it so we have to wait almost 20 years for another great nemesis system game since WB isnt making a new one .....they are no better than scalpers at this point especially after siding with amber turd', 'Very Positive', 88.13, 50.57, 93.93);
INSERT INTO reviews VALUES (3482, 356250, 139, 'Gorgeous interactive art experience with stunning visuals, amazing music, and a light narrative arc. It''s a short and pretty linear experience and you don''t have a lot of control or agency as the player, but if you go into it expecting something like an abstract music visualizer with narrative and interactive elements you''ll enjoy it.', 'Bought this because it''d been advertised as being relaxing and peaceful. Sadly I''d have to categorise it as actually quite stressful and rather upsetting, as you constantly lose birds to frustrating and opaque mechanics. Without any sufficient tutorial, choice of difficulty, or really any introduction to the mechanics, I "lost" my first game. My entire flock had died. Frankly, I really didn''t want to repeat this experience, so I quit and haven''t touched it since. Thus I cannot recommend this gam', 'Very Positive', 90.65, 0.82, 0.10);
INSERT INTO reviews VALUES (3483, 356260, 141, 'wow they made red orchestra into an rts very cool', 'They added a stupid launcher with ads almost two decades after release. That''s criminal. Be ashamed.', 'Very Positive', 83.69, 247.92, 1.25);
INSERT INTO reviews VALUES (3491, 356400, 2982, 'It''s a great game to play when upset. Because there is no RNG, just the same patterns you have to hit with precision, you can enter a zen like state. As you repeat a level to get S rank your muscle memory and reflexes improve and since you are focusing so much on the game it takes your mind off what was annoying you, as well as providing a sense of fulfillment after you complete a few S ranks.', 'Starts off strong.  But then the game ups the difficulty by having the player memorize what happens after blind corners rather than relying on reacting fast enough.  I like reacting but I don''t like memorizing.  Memorizing is boring.', 'Very Positive', 92.09, 8.50, 1.35);
INSERT INTO reviews VALUES (3492, 356420, 120, 'A ingeniously made game reminds me of the first time I played something like starcraft or chess, it is perfectly designed. Has balanced games which are quick and complex. Can''t believe this game never caught on with mainstream steam multiplayer games. 9.5/10 Great game design.', 'MP is dead', 'Very Positive', 86.67, 9.80, 1.73);
INSERT INTO reviews VALUES (3493, 356430, 351, 'Buy the game and download openloco which is an ongoing development of this game.', 'Who decided to build roads like in Rollercoaster Tycoon? idiots...\nOriginal TT just a way to go (dosbox)!', 'Very Positive', 85.19, 6.18, 0.27);
INSERT INTO reviews VALUES (3494, 356450, 117, 'how does a bat participate in track and field', '|Creature to Koi Shiyo! -Kokonoe Kokoro-| - 1/10.\nQuote: <''No way am I touching that ugly monster bitch.''>\nChar: Ichinose Itsumi.\nOST: -\nInfo: 1h40m (EN), 100% (All endings and all achievements), \nTierlist: kusoge', 'Mostly Positive', 75.21, 1.30, 1.75);
INSERT INTO reviews VALUES (3496, 356500, 2401, 'The game is a classic, however it desperately needs a remaster cause the base game is pretty ugly and painful to play.', 'The game simply does not work on modern hardware. Not optimized, crashes before it will even start. VERY dissapointed.', 'Very Positive', 92.50, 2.98, 0.18);
INSERT INTO reviews VALUES (3499, 356530, 154, 'The MC is great, I think she was the high part of the game for me. I like how she is strong and capable, but clearly flawed', 'Very Little content for the price of the game. The music is good standalone but doesn''t mesh with the game play.', 'Very Positive', 88.96, 6.93, 0.57);
INSERT INTO reviews VALUES (3503, 356570, 3056, 'Who hasn''t been there? \nI mean, we''ve all been there, I''ve probably been there a dozen times.\nYou just want to sleep peacefully after a hard day''s work but the neighbors suddenly start partying wildly. \nSo just kill them all!', 'Fuck I want to like this game. My nostalgia watching Jacksepticeye years ago made me thrilled to play it. However apparently I was wearing rose tinted glasses because MY GOD this game is just... slow and boring. It tries to play into the slasher theme but it ends up feeling boring and slow as most of the game is simply RNG and rolling a good run. Didnt commit a crime? Get blamed and hunted anyways. Walking by casually? Bouncer jumps you and pushes your shit in for nothing, even at public events.', 'Very Positive', 86.13, 8.27, 6.27);
INSERT INTO reviews VALUES (3505, 356650, 2017, 'I got this game free on epic, just bought it on steam to pop a review that its awesome', 'This game was really good and a really fun metroidvania, albeit with some balancing issues with adds and such during boss fights, situations where you could be ping ponged between enemies and such, but that''s all fine and acceptable. What isn''t acceptable is to have the re-fights be excruciatingly hard by just making the boss tankier, hit for more, spam attacks, and throw out adds at a rate where you simply cannot avoid and/or block them all. I would honestly be fine with this, it''s a good chall', 'Very Positive', 80.76, 0.17, 29.85);
INSERT INTO reviews VALUES (3514, 356880, 120, 'Eron\n\nHas a total of 5 trading cards.', 'A very nice concept indeed, but the lack of checkpoints as well as the lack of music continuation, means song beginnings are always heard, which can be rather frsutrating considering they sound like good songs. I feel that the lack of character exlpanation leaves me disconected from the protagonist, and wishing there was at least a shred of dialogue to give me the oppurtunity to get pulled in. The scenery is very beautiful, but seems zoomed out WAY too far, leaving the the mysterious protagonist', 'Mixed', 60.83, 2.17, 0.37);
INSERT INTO reviews VALUES (3515, 356890, 110, 'This is a Gem - One session in I can see this will be addictive - solo and multiplayer options - love this in my library.', 'The gameplay loop is interesting but the novelty wears off very quickly, while getting all the achievements takes a lot longer. And I''m not the person to usually nitpick hypercasual games like this one, but when a game presents skill-based achievements within a game where the player''s skill can be undermined by the randomness of the game mechanic, it defeats the purpose of being an achievement, since it becomes luck-based rather than skill-based. This game lacks a consistent method of playing, s', 'Mixed', 63.64, 0.20, 7.15);
INSERT INTO reviews VALUES (3516, 356910, 107, 'the theme is unique and the combos aren''t terribly long. think of it like aquapazza or street fighter 4 but with daisuke ishiwatari voicing one of the characters', 'Couldn''t even get a controller to function on here so I couldn''t get past the start screen. Also it wouldn''t even boot up for the first 10 minutes, so I''ll take that as a message to not play this game and go back to Granblue.', 'Mostly Positive', 70.09, 1.03, 0.23);
INSERT INTO reviews VALUES (3519, 357190, 3688, 'I don''t own a controller so I have to use the keyboard but I can still hit the craziest combos with Vergil just by typing like Flint Lockwood.', 'This game is not easy to learn, the playerbase is insanely skilled. If this game is for you, you dont need to be reading reviews, otherwise, there are better uses for your money, as unless you have hundreds of hours to devote to a game with no ranked play or local scene, this is effectively a single player game.', 'Very Positive', 92.27, 28.75, 15.80);
INSERT INTO reviews VALUES (3522, 357290, 197, 'Atmospheric horror story of the 2000s', 'Very bad.', 'Mixed', 43.65, 4.52, 34.62);
INSERT INTO reviews VALUES (3523, 357300, 693, 'They say it''s easier to fool someone than to convince someone they''ve been fooled, but Snakebird only needed 30 minutes to convince me I''m retarded.', 'Snakebird is a 2015 hardcore puzzle game by Noumenon Games. The long and short of why this review is negative, is that, from the overwhelmingly positive review score and friendly appearance, I expected a nice and relaxing puzzle game. Unfortunately, this game is one of those "if you don''t think 50 moves ahead and execute the moves exactly as the developer intended, then you''re just going to be bashing your head against a wall or running a step-by-step YouTube guide in the other window and bashin', 'Overwhelmingly Positive', 95.24, 2.17, 1.15);
INSERT INTO reviews VALUES (3524, 357310, 782, 'A distinctly Chinese (with hints of Mongol and Korean) 4X style game. Somewhat minimalist tactical battles (stack v stack in automatic combat). A fun economy to master. Alright diplomacy (which is normally pretty weak in 4X, so IDK).\r\n\r\nI somehow keep coming back to it.', 'Boring combat and not much to the rest of the gameplay either. The AI isn''t able to properly defend itself so you can just deathball superior forces without any real difficulty, even on the hardest difficulty level', 'Mostly Positive', 73.53, 197.62, 12.93);
INSERT INTO reviews VALUES (3526, 357330, 1071, 'Fantastic game, gets way easier when you learn how to read the map. Would be great with friends but all mine are too afraid :-(', 'This game is a Great Game but I hardly ever find a lobby that works and is actually with good players. Every once in a blue moon I''ll have a great team but that only ever happens 5 times over the time I played this which is a shame this game is so much fun but is saturated by bad service. If you have friends and I mean close friends pls buy this game! But if u just want to play this solo for fun don''t bother. I hate to give this game a not recommend but it''s just the technical aspect that kills ', 'Very Positive', 91.32, 37.28, 6.58);
INSERT INTO reviews VALUES (3533, 357670, 165, 'fake ikea', 'This is a unique little game which makes building furniture so much more complicated and hilarious. Unfortunately… that’s really all there is to it. I got bored of the concept pretty fast. It’s fun with a friend, but it gets old quick.', 'Mixed', 68.48, 11.83, 1.58);
INSERT INTO reviews VALUES (3538, 357780, 242, 'This game uses the Kingdom Rush series as a template.  It has similar layout and logic, including heros, tower types, paths and upgrades design.  The graphics are very good and add to the enjoyment of playing the game.   It also has its own innovations that all work well, making it something more than "a game you have played before". It takes a lot of talent, skill and programming to put out a game like this one.  \n\nIt should be noted that this game is pitched to be more difficult than the Kingd', 'This is pretty much a Kingdom Rush clone with a different theme, and not nearly as good. Don''t bother with it.', 'Mostly Positive', 75.62, 51.90, 2.02);
INSERT INTO reviews VALUES (3542, 357900, 191, 'Weirdly enough, I didn''t hate the game. \n\nUseless tip: Don''t give up ;)', '1/5\nThis is NOT a game. That is all you have to know.', 'Mixed', 43.46, 0.20, 2.62);
INSERT INTO reviews VALUES (3549, 358070, 138, 'Beautiful game, beautiful soundtrack; I feel like an overprotective mother trying to get all of my kids to play nice with each other.', 'Ehhhhhhhhhhhhhhhhhhhh I expected better', 'Very Positive', 89.13, 47.82, 0.85);
INSERT INTO reviews VALUES (3551, 358090, 1007, 'D4 is my favorite unfinished game. It left many unanswered questions. \nWho killed little peggy? \nWhat happened to D4 Season 2? \nI documented everything that went wrong in a feature retrospective.\nThe Devastating Drama of D4: Dark Dreams Don''t Die.\nhttps://www.youtube.com/watch?v=yU8DC5hY1ig', 'The game itself is great, but it''s unfinished and never will be finished.', 'Very Positive', 80.93, 10.97, 6.50);
INSERT INTO reviews VALUES (3552, 358130, 1237, 'Amazing game. From start to finish. The sequel is also great, but I''m happy to have started with this one because it''s different and in no way inferior.', 'I understand the point is, as a roguelike, that the game is meant to be failed and tried again but when just about every rng decision is weighted against the player and the game will magically have safe points disappear off the map then it''s just not fun. \r\n\r\nCan''t recommend even as a fan of roguelikes.', 'Very Positive', 86.90, 44.22, 25.83);
INSERT INTO reviews VALUES (3564, 358360, 132, 'I''m finally old enough to purchase the full version. \nBeat the crap out of the shareware version when I was a lad.', 'I hate when I have to do all sorts of technical gymnastics to get a game working even if it''s a one time thing.\nI can forgive open world types which one can forgive for being buggy and therefore needing ports.\nIf you have more patience than me then I can confirm that this does run and I liked the original back in the day so I suspect so will you.', 'Very Positive', 94.70, 0.73, 0.13);
INSERT INTO reviews VALUES (3571, 358750, 418, 'This game not good as Mask of Arcadius. Many plots or visual novel lines are kind of build after another in short term. But, turn romance ok, and the game itself is not bad at all, just don''t give it too much high standard.', 'a chore to play', 'Very Positive', 81.82, 29.77, 9.53);
INSERT INTO reviews VALUES (3573, 358770, 114, 'Let me start by saying if you want something even more... ero... then please check out this developer''s (Lupiesoft''s) other titles. \n\nBut let me talk about The Reject Demon a bit. The western art style is quite refreshing. A wide variety of characters for many tastes. The music is good as well, a decent variety. Wish there was a bit more though. No VA currently.\n\nThere are no choices, so just single playthrough and you''ll see everything. I played the demo and a lot has been added and changed sin', 'I would like to start this review off with a disclaimer, this chapter is AMAZING! \n\nBUT, I am noticing a trend of VNs lately releasing things episodically, and there is nothing wrong with that IF you have an ACTUAL release schedule in place already. Right now this game is nothing but a tease with the promise of a game that will come.....eventually. No set release dates, no real promises, and very little information is given other than, ''we have two games coming out before releasing the other cha', 'Very Positive', 82.46, 3.23, 3.60);
INSERT INTO reviews VALUES (3575, 358830, 139, 'It works with Proton 7.0-6 on Linux/Debian 11 Operating System.\nFuncionou com Proton 7.0-6 no Sistema Operacional Linux/Debian 11.', 'Can''t recommend this game\n\nI absolutely love rogue-like games, but Good Robot is more Bad Robot. It''s extremely bland and repetitive. The areas are always the same, but with a different tint of color. There''s a lot of different enemies, but they feel the same altogether. Sure some explode, some shoots in an area of effect way, some just shoot in a straight line. But they''re boring nonetheless. There''s upgrades, but they provide more damage, more hp, higher fire rate, and so on, nothing that exci', 'Very Positive', 89.21, 0.93, 0.45);
INSERT INTO reviews VALUES (3577, 358920, 125, 'One of the best games in history. Seriously.', 'Can''t adjust screen location and it won''t save keyboard bindings. Till these are fixed I don''t recommend playing it.', 'Mostly Positive', 78.40, 0.22, 0.30);
INSERT INTO reviews VALUES (3578, 358960, 105, 'Canabalt\n\nHas a total of 5 trading cards.\n', 'A lazy port of a mobile game. They''ve literally taken the phone game and stretched it''s blocky graphics to fit a monitor. Not even worth the 99¢ they charged when it was on phones.', 'Very Positive', 93.33, 0.53, 0.12);
INSERT INTO reviews VALUES (3579, 359040, 349, 'One of the best walking simulators. There is an ending, but there''s no rush to get to it, you''re free to explore anywhere and everywhere and only after exploring all locations does the game move you along. The horror comes from the story that unfolds, the environment, and the dialogue of our protagonists on the journey and, wow, there are a few uncomfortable topics; when there is music playing, it''s well-made.\n\nThe ending is expected but striking nonetheless, and the final message shared between', 'huh? ', 'Very Positive', 90.26, 1.87, 0.27);
INSERT INTO reviews VALUES (3580, 359050, 4674, 'Sometimes I go into the wrong shower on purpose.', 'daddy started jorking it on me', 'Overwhelmingly Positive', 96.02, 236.43, 0.38);
INSERT INTO reviews VALUES (3584, 359100, 534, 'It a Good game. Portal like which is a good point to me. I really enjoyed discovering more and more mechanics as the game goes. It did not particularly found it hard but its very smooth to guide you toward your goal. The story is good and I won''t say more than that so that you get a chance to discover it by yourself ;).', 'RATING: 3/7 "FINE"\n\nThe game is pretty, and the puzzles are neat, although the story is bad to a distracting degree. Maybe worth it if you''re really hungry for 1st person 3D puzzles, but only if you mute the dialogue. That still leaves the pacing messy though, do to the unskippable narrative elements. Overall, it doesn''t have that many strong drawbacks, but its strengths are also lacking enough to leave it not a recommendation.', 'Very Positive', 80.71, 4.72, 3.33);
INSERT INTO reviews VALUES (3585, 359140, 107, 'Dave Lizewski if he was a commando', 'Oh, I liked this game since the first mission, really! It reminds me Guerilla Wars on NES. I played 3 missions, I''m thrilled, but I can''t continue because I can''t stand camera shaking. Every second of the game something''s blowing up, firing, and all these actions are accompanied by camera shaking. There is no option to reduce or disable it.\n\nAlso, gamepad doesn''t work, only left stick is working, it''s definetelly a technical bug. I don''t really want to play it with mouse and keyboard.\n\nIf these ', 'Very Positive', 92.52, 9.57, 0.20);
INSERT INTO reviews VALUES (3588, 359220, 420, 'WHAT I REALLY MEANT TO SAYYYYYYYYYYYYYYYYY\n\nIS I''M SORRY FOR THE WAYYYYYYYYYYYYYY\n\nI AM', 'better play it on emulator, crash starting race. + doesnt  support controller....', 'Mostly Positive', 71.67, 1.12, 0.28);
INSERT INTO reviews VALUES (3589, 359230, 534, 'It''s got some rough edges and interface oddities, but this is a pleasant throwback to older-style city builders such as Pharaoh. The art''s what really impressive, though. Good, but not groundbreaking or massive.', 'animated by silly billies, praises communism and calls it progress, among other woke garbage in there', 'Mixed', 62.36, 42.23, 5.15);
INSERT INTO reviews VALUES (3594, 359310, 912, 'This game changes, much like a museum adapting to transcend time and genres.\n\n\n변화하는 게임.', 'As many others have said, I wish Steam had a "meh" rating. Evoland II starts off interesting, but has very little to actually call its own - its main two gimmicks are the changing art styles and its mash-up of genres. The art is well made (if generic) and it IS a neat concept, but it doesn''t have any of the same puzzle elements that the original Evoland had, it just changes depending on what time period you''re in. \n\nThe genre-mashing is interesting in concept but irritating in practice. Don''t li', 'Very Positive', 85.86, 17.43, 13.15);
INSERT INTO reviews VALUES (3596, 359350, 293, 'This game was amazing, I thought to myself as I was about 50 minutes into playing it. I was thinking about all the future areas to explore and mess around in as I had only just begun playing the game. Only ten minutes later, I finished the game. Everything about this game I love... but its just way too short.\n', 'This is a momentum based game that primarily focuses around time attacks and beating levels quickly, optimizing how you play the levels, etc. It wasn''t for me and I don''t think it will be for you unless that sounds like fun.', 'Very Positive', 88.74, 4.03, 0.82);
INSERT INTO reviews VALUES (3598, 359400, 322, 'This is of the best mystery yarns I’ve read/played in ages, with a fun Earthbound-esque visual style and fun chiptune soundtrack.\n\nI picked it up thinking I’d just give it a try, and then devoured the entire game in a single day over the course of 5 hours. If I hadn’t already stayed up past midnight, I’d have unlocked the last 4 achievements.\n\nExceptionally written, uniquely designed, and surprisingly moving, this dark tale is a STEAL at $5. If you were interested enough to click on the listing,', 'awful', 'Overwhelmingly Positive', 95.03, 4.73, 2.33);
INSERT INTO reviews VALUES (3600, 359440, 130, 'Artifact Adventure\n\nHas a total of 6 trading cards.', 'There is a lot to dislike about this game and all of the dislike involves boneheaded design decisions. You would expect aged graphics, pixels, etc but not the stupid design elements.  Being able to save only in towns which are far apart is not the worst.  The worst is that the character in the lead of your party  always gets the ability or boost, you don''t know what it will be and you only get one chance.  If your warrior is in front and the ability is a magic one then it is wasted.  Each charac', 'Mostly Positive', 74.62, 1.48, 11.35);
INSERT INTO reviews VALUES (3601, 359550, 601606, '72% of Siege players are new to using McDonald''s Wi-Fi, unless they are on the enemy team. In this case, they are ex-pro players with a well-coordinated team of five people. 10/10', 'This game makes me suicidal. Everything about this game is shit especially the servers and hitboxes. You can shoot a guy, and it won''t do one bit of damage. You get railed by a fucking shield every fucking round. I would rather play Rust and get a rock stuck in my a$$. DO NOT PLAY THIS GAME if you want to get a girlfriend and lose your virginity.', 'Very Positive', 84.47, 391.10, 514.18);
INSERT INTO reviews VALUES (3603, 359580, 188, 'Uncanny Valley convinced me from the first moment.\nIt somehow reminds me a lot of Silent Hill.\n\nWe play a man named Tom who is plagued by nightmares and is looking for a job as a night watchman in the middle of nowhere to pass the nights with work.\n\nEvery decision has a consequence, there is no possibility to save yourself, which creates a new feel and the game has a high replay value.', 'My EYES!', 'Mixed', 55.85, 4.35, 11.78);
INSERT INTO reviews VALUES (3604, 359600, 296, 'This is the 3rd game in the Assassin''s Creed Chronicles series, a side-scrolling platformer. \nWhile previous installments featured weapons like daggers and chakrams tailored to each setting, this installment introduces new equipment such as rifles and mechanical wrenches, as well as sniper points, providing a fresh feel not seen in previous Assassin''s Creed games. Cutscenes and stages are mostly composed of rigid straight lines and black and red colors, reminiscent of the intense atmosphere foun', 'Shove your piece of shyte launcher deep in your arse and fuck off.', 'Mixed', 48.99, 4.03, 0.10);
INSERT INTO reviews VALUES (3605, 359610, 324, 'This is the 2nd game in the Assassin''s Creed Chronicles series, a side-scrolling platformer. \nCompared to its predecessor, this game features a wider variety of skills, diverse enemies, traps, stealth elements, and time attack mechanics, making it even more challenging. The Indian setting captivates with its unique patterns and beautiful colors, which are particularly striking in the game''s visuals.', 'Shove your piece of shyte launcher deep in your arse and fuck off.', 'Mixed', 59.88, 3.82, 0.08);
INSERT INTO reviews VALUES (3608, 359650, 109, 'An old classic game based on one of the most iconic shows of all time. Voice performances by all the principal actors, most of whom aren''t with us anymore, make this game a sentimental treasure. The missions feel like episodes of the original show. Multiple possible solutions to the game''s puzzles, with both good and bad outcomes, make for a lot more replay value than you would expect from the old point-and-click genre. Find a way to score 100% on all missions, or do a blooper run to finish a ca', 'This interface is atrocious.', 'Very Positive', 91.74, 41.30, 0.63);
INSERT INTO reviews VALUES (3611, 359810, 107, 'Hare In The Hat is a game where you solve cleverly thought out puzzles to free a hare from his cage. The puzzles are definitely challenging and requires a lot of thinking which makes it fun. There are some insanely difficult puzzles that tests your ability. Recommended if you are up for some challenge.', 'This game is frustrating. I honestly didn''t enjoy it at all. Also if you''re an achievement hunter, make sure you get the DLC too or you''ll be stuck at 50% achievements. I finished the game but I seriously feel like that was 3 hours of my life I can''t get back.', 'Mixed', 52.34, 5.73, 3.65);
INSERT INTO reviews VALUES (3612, 359900, 450, 'The Incredible Adventures of Van Helsing 3 - This is the second best one in the trilogy if you ask me. In my personal order: 1, 3, 2. Further continuation of what the first 2 built on and it was a great experience playing this in coop again because there was no desyncing (not that it stopped us making backups of our characters to be sure).\n\nThis is the final instalment of the game and we as a group of buddies (Eazy, my wife and I) thoroughly enjoyed playing this together and having a bunch of la', 'Compared to the other games, it''s VERY easy, the skills are dumbed down and it''s just... boring.\r\n\r\nIf you REALLY wanna play it, buy it on a bundle, on sale. Otherwise, don''t waste your time', 'Mixed', 60.44, 16.97, 7.82);
INSERT INTO reviews VALUES (3613, 359920, 128, 'This is probably one of the best hidden jewels all over steam...\nIf you like storytelling games with a strong tactical and role play element...search no more,This is it!\nIt plays a lot like a board game,but with a type of artistic quality and simple mechanics only possible in a computer game.\nMy main reason to make this review,is related to the fact of how little attention it was able to get...If you were looking in the first weeks,during and after release,you probably know"HIGHLANDS",if not...i', 'It''s fun, though short. But the frequent ''here, charge through a level with few or no resources'' missions suck, and the last level is ''here, charge through a level with NO resources so you can''t use any special abilities at all.'' It''s not even annoying as much as it is dull and disappointing as an endpoint to the game. \r\n\r\nOh, and a character you meet early is the villain and you could have basically solved this by stabbing them in an early mission. And the motivation is dumb. Not great. \r\n\r\nNea', 'Mostly Positive', 73.44, 19.57, 6.77);
INSERT INTO reviews VALUES (3614, 359940, 127, '- Very nice game taken account that only one independent developer made because got two such a large open world areas etc.. many do only some short 30-40min mostly boring  horror games with very small game world.\n\n- But if not taken that account game world feels sometimes little bit boring especially part two when you need run over the same area again and again and do boring fps stylish shooting with crappy enemy animations/AI\n\n- Controls/game play sometimes are very janky/annoying example get s', 'If you have any trouble you can just crouch. Literally nothing can hit you.', 'Mostly Positive', 71.65, 12.20, 3.82);
INSERT INTO reviews VALUES (3619, 360150, 371, '.', 'Can not recommend this kind of jank...', 'Mixed', 52.02, 28.17, 0.87);
INSERT INTO reviews VALUES (3620, 360170, 1920, 'The first game was a little bit better than this one but still.\r\nIt is the same thing  with a few new enemies and clunky gameplay (the game is made for consoles, wich is why the controls are a bit clunky)\r\n\r\n((**Remember to grab the machete on your first run on the middle locker room or arsenal room on Kovac''s bunker you will need it to chop wood and make arrows and other things**))\r\n\r\nThe camp mechanic is....meh but it gives you another reason to go out and murder zombies, everything you do wil', 'Didn''t have the same charm as the first one. I would suggest you go play that one instead.', 'Mixed', 66.25, 53.98, 0.27);
INSERT INTO reviews VALUES (3621, 360380, 261, 'Tiny Bridge:Ratventure offerts charming puzzles, but repetitive gameplay dampens the fun.\n\nRating: ★★★☆☆ (3/5)', 'Maybe just not my type, but I find it rather frustrating. The levels seem simple enough to make me want to complete them, but there is no joy in it, I feel more a technical challenge than intellectual.', 'Mixed', 54.02, 3.47, 2.87);
INSERT INTO reviews VALUES (3625, 360510, 243, 'This is a slightly above average $17 - $20 game.  It''s not going to change your life, and it''s not gonna occupy you for weeks at a time, but it''s a nice graphic wrapper for a rogue like game, set in space.\n\nIs the game perfect?  No.  It locks up on occasion.  Sometime when it locks up, you have to reboot your computer.  If you leave it at the loading screen for a long time, like more than 15 minutes, it''s locked up on me each time.\n\nThere are some variables in the game play, but with it not bein', 'Had this for years and only now tried it out. \nIt was boring, I flew around for 45 mins and the only thing that happened was citizens defecating in the streets, then they started a riot.\n\nI''m not going back to those poop filled streets, but I highly recommend star trek bridge crew.', 'Mostly Negative', 38.27, 8.50, 1.13);
INSERT INTO reviews VALUES (3628, 360550, 124, 'Cursed Sight\n\nHas a total of 12 trading cards.', 'The music and the art are really good for an indie game. However, writing needs a lot more work. It felt clumsy and choice of words were weird or didn''t really suit within the story.\n\nTo me, it looked like the writer doesn''t have much experience, or is very young. Having good beta viewers or editors for the text would have been a good idea.\n\nIt looked good, but I just couldn''t enjoy it, because writing and good characters are what I look for in my visual novels.', 'Very Positive', 82.26, 0.97, 2.28);
INSERT INTO reviews VALUES (3631, 360640, 538, '12 Labours of Hercules II: The Cretan Bull\n\nHas a total of 5 trading cards.', 'Basically the same as the previous game in the series. Not great.', 'Very Positive', 88.48, 2.25, 9.85);
INSERT INTO reviews VALUES (3632, 360650, 257, '12 Labours of Hercules III: Girl Power\n\nHas a total of 5 trading cards.', 'Basically the same as the previous game in the series. Not great.', 'Very Positive', 82.10, 1.20, 9.17);
INSERT INTO reviews VALUES (3635, 360740, 4989, 'Downwell feels like a phone game (stay with me) from the golden age of phone games, when they were actually great games just for small screens. I beat this 100% on steam and on my playstation VITA, its 3$. Buy it and beat it till you''re sick of it.', 'Autism required.', 'Overwhelmingly Positive', 96.99, 12.42, 3.20);
INSERT INTO reviews VALUES (3636, 360830, 1950, 'Wtf is with the hate against this game? From actual Banjo-Kazooie fans too, yikes. Game is great! Has the same feel and magic as the original Banjo games, not as many worlds but you can EXPAND each of the worlds, so they became like as big as 2 worlds back in the old games. So it cancels that issue out lol. Characters are funny, graphics are actually pretty nice, and music is from the same composer. Honestly, what''s not to love? Game doesn''t have THAT bad reviews, but it deserves even more posit', 'Bought for coop. Found out coop means the second player can basically spectate as a bumble bee', 'Mostly Positive', 75.13, 25.13, 0.32);
INSERT INTO reviews VALUES (3641, 360940, 3852, 'If you have a good amount of friends, or don''t mind bots and the occassional random joining the fray, this is the game for you. Otherwise, I would avoid. What a shame this underrated gem didn''t pan out.', 'The game is not bad, but there are too many cheaters.', 'Very Positive', 81.00, 5.10, 1.03);
INSERT INTO reviews VALUES (3644, 361040, 206, 'Doom & Destiny Advanced\n\nHas a total of 5 trading cards.', 'Well, I really liked the original. The mechanics were straightforward. I feel like I have to make tons of unfun decisions with consequences all the time. You have to choose how to allocate lvl up points. There are like 8 or 10 stats. It''s just... work, to figure out what you want to build. \n\nAll the characters have a BUNCH of classes. Instead of being cool, it feels super limiting. Like, you can only roll bolders out of the way if you have the correct class. But sometimes I don''t want to play as', 'Very Positive', 87.86, 1.03, 4.10);
INSERT INTO reviews VALUES (3649, 361190, 153, 'Evolving by consuming nutrients, customizing abilities, exploring vivid worlds and completing various quests.', 'Sparkle 3 Genesis is better than its predecessor, due to its clear direction and manual revolution mechanic. Still, the product instantaneously loses all its entertainment value when players reach the unbeatable level three. Whether it is due to a design or technical flaw, said level''s quota can not be completed to full due to there being missing elements in the mission area, therefore making progress come to a screeching and permanent halt. This video game is considered unplayable and unpolishe', 'Mixed', 50.98, 2.65, 1.35);
INSERT INTO reviews VALUES (3651, 361230, 157, 'This is a well-polished Metroidvania that leans more heavily on combat than exploration. The writing is some of the most engaging and original stuff I''ve seen out of a game in a long, long time, and it will inevitably become a cult classic in 20 or 30 more years.', 'Fighting is repetitive.   There are times that all your moves are on cooldown and you can''t even do anything.  You can swap out some moves for others but I don''t enjoy this type of combat at all, I just feel like I''m spamming these buttons repeatedly.\n\nIt''s almost like a beat ''em up, but I would much rather play any other one of those because at least my moves won''t be on cooldown and there will be less silly dialogue.\n\nVisuals were nice though.', 'Very Positive', 91.08, 34.13, 0.22);
INSERT INTO reviews VALUES (3653, 361280, 4928, 'Started digging for oil, accidentally created a mole empire instead. Best unintentional rodent tycoon simulator.', 'Required to be online for singleplayer', 'Very Positive', 92.80, 22.95, 6.47);
INSERT INTO reviews VALUES (3654, 361300, 1506, 'If you like the Streets of Rage series and also enjoy shooting up heroin then this game is definitely for you!', 'The strike zone is too narrow, it is difficult to hit the opponents, the plot is boring, I did not have the patience to go through it.', 'Very Positive', 84.20, 10.93, 2.38);
INSERT INTO reviews VALUES (3655, 361320, 269, 'Got this dirt cheap in the Winter Sale after watching Jerma''s chaotic stream. Within an hour of first starting this up, my casino had been voted "most popular establishment for Trailer Trash", several people were on lying the floor unconscious, there was vomit everywhere and there had already been a fire at the Pasta Italiano.\n\n10/10. Thank you Jerma.\n\nP.S. No problems running the game on Windows 10.', 'i can''t do this anymore', 'Very Positive', 85.50, 1.43, 2.15);
INSERT INTO reviews VALUES (3658, 361360, 191, 'A very nostalgic game for me, I went through and got all the achievements. It''s definitely worth the $10.', 'While there''s so much going for this game (artwork, storyline, nostalgia), I can''t recommend it because of the bonkers puzzles. There is no logic to the majority of them and this game is impossible to get through without a walkthrough. Frustrating!', 'Very Positive', 91.62, 5.05, 5.05);
INSERT INTO reviews VALUES (3660, 361420, 50286, 'Great game, helped me through one of the worst stages of my entire life and distracted me from every bad thing.\nGood quality and there is no lack of anything at all.\n10/10', 'This game is fun, but the studio doesn''t deserve your money anymore. Don''t buy the DLC, don''t buy the microtransactions, just get the game and nothing else.\nWhy you shouldn''t give them your money:\n- The game is quite buggy. If you look at an item wrong then it will fall through the floor. If you''re playing multiplayer and you move too quickly then YOU will fall through the floor and then either die from fall damage or die from lack of oxygen. If you''re going through a tunnel and you place someth', 'Very Positive', 91.82, 45.35, 388.82);
INSERT INTO reviews VALUES (3662, 361550, 902, '\r\nI have kind of deja vu with this game because I''m not sure if I already played it years ago or not... it seems kinda familiar though and not sure why but it reminds me of Syberia games.\r\n', 'Interesting, but feels like dead museum instead of be a game. And this museum doesn''t really expect someone to enter itself: I go to this garden dome and was trapped by possibility to go in and impossibility to go out. Feels like game wants from me to action in specific way, while give me opportunity to explore territory from even beginning of game.\nThis game is tagged like "Sci-fi" but has elements of magic, that, personally, destroy mine expectations and immersion. And you don''t really know, b', 'Mixed', 62.86, 5.42, 0.53);
INSERT INTO reviews VALUES (3667, 361670, 259, 'This game is an absolute blast and easily fits in the top 10 best game experiences of my life.\r\nIt is a niche game mostly for Star Wars fans or Joystick flying fans. If you''re one or both than this is your game.\r\nDisclaimer: I used to play this when it came out but for nowadays I would always recommend installing the XWAUpgrade mod. It will bring the entire game up to day and playable on modern systems with enhanced features while fully keeping the game and campaign intact. It is a free must hav', 'I wanted to like this as a throwback but. Unfortunately this game REQUIRES a joystick (flightstick specifically) to play. Tried remapping, tried utilizing a PS5 and gamecube controller as a flightstick stand in... Do NOT buy this game unless you have a flightstick specifically for flight sim type games. Will NOT work on keyboard/mouse and will NOT work with controllers such as PS5/XB/GC as a stand in', 'Very Positive', 83.78, 2.43, 0.15);
INSERT INTO reviews VALUES (3669, 361690, 163, 'It was the only game(s) in town for many aspiring stick-jockeys, in terms of space-based dogfighting combat. . .\nNowadays, in an age graphical fidelity, it feels a lot like ''flying'' around in your basic Windows starfield screensaver. . .\n\nThere are 4 titles available in this series, and this is the last & most-comprehensive of them.\nThat''s why I grabbed it, to get the most-complete package with options for multiplay -- however, I don''t have any nostalgia goggles to ultimately color my experience', 'Selling 30 years old game for 10$ and not giving it keyboard support is just ridiculous...', 'Very Positive', 80.37, 1.47, 0.15);
INSERT INTO reviews VALUES (3672, 361850, 163, 'A great game with the interface of a House of 1000 doors. The story is pretty cool and the graphics really nice. The voices are mostly pretty good. The minigames and HOS´ are varying from easy to hard. All in one a really good HIO with no problems or contras. I can really highly recommend it.', 'It''s just normal HO games, like those Artifex Mundi game, this game''s graphics are towards realistic style, however, for some odd reason, this game runs like trash on my site.\n\nMy Frames are dropping, by moving the cursor, the frame is worst than bit rate...\n\nIt''s nothing too special in this one, you might as well skip this one.\nI am only saying this because it runs like cr@p for me.', 'Very Positive', 92.64, 8.92, 8.00);
INSERT INTO reviews VALUES (3677, 361990, 674, 'goated game', 'I was enjoying the atmosphere and the game play until I realized I had no idea how to make the game progress. Perhaps others that have more patience than I will get further.  I looked up the reviews of this game to see what the deal was and I see multiple people saying you need to have a guide on hand to get through this game.  Huh?  I don''t want to have to read a walk through guide or watch someone else play the game, when "I" want to be the one playing the game.  Perhaps I''ll try this again wh', 'Very Positive', 91.84, 16.97, 0.88);
INSERT INTO reviews VALUES (3680, 362090, 170, 'This is where it all begun! Though it''s rough compared to the sequels, some of its mechanics remain my favorite in the series.', 'I can appreciate that this was a bit of an experiment, and thus the creator didn’t follow through with an evolving story or any real goal. But that’s exactly what will make you quit playing, whether it be 2 hrs in or 200 hrs in, it all amounts to nothing. It’s kind of a waste, because the ideas are great and a lot of the systems are interesting, they’re just kind of there though. This just isn''t for me.\n\n5/10', 'Very Positive', 86.47, 36.15, 1.07);
INSERT INTO reviews VALUES (3685, 362350, 234, 'Fun board game.', 'I''m glad I paid for something that no longer exists.  Thanks Steam!', 'Mixed', 58.12, 11.42, 0.90);
INSERT INTO reviews VALUES (3689, 362410, 104, 'Adam''s Venture Chronicles\n\nHas a total of 6 trading cards.', 'Maybe it''s strange to critique game about puzzles for having puzzles, but I was not expecting very "artificialy done" type here like random math\\logic puzzles.\n\nIt feels cheap to have core adventure gameplay just to be a vehicle to start Nancy Drew activities in most bizzare and random places. Near every puzzle here doesn''t make any sense in a game world - how we have modern-english poem riddles and roman numeral math around Gates of Eden? How water aqueduct tied to random city gate? \n\nI like ne', 'Mixed', 59.62, 1.20, 3.05);
INSERT INTO reviews VALUES (3690, 362490, 8224, 'I waited for this game for 9 years. I gave up waiting. I gave up waiting for Sui Generis a really long time ago too. The game is still great, probably the greatest sword fighting game ever made, has lots of content in the story mode and practically infinitely repayable in the Arena mode. But fuck me man, it''s been over 10 years since that Kickstarter. I finished school and graduated from the uni and will probably get married before this releases. If the community had access to the engine, there''', 'there should be a timecap and a money back guarantee on "early access" games.\nit''s been almost a decade now - and the game is still unfinished.\n\nAs much as i like the game as a concept, it''s still just a concept that never gets finished... that is why i am not investing into "early access" anymore time or money. frustrating.', 'Very Positive', 81.80, 48.45, 161.52);
INSERT INTO reviews VALUES (3692, 362620, 5201, 'dangerously addicting to simulation/buillding game players like myself. I thought I was having an issue with the game and made a post on reddit. One of the developers had me send a save file and got back to me so quickly and helped explain the game to me (there was on issue, i was just dumb). I love the care for this game by the developers and plan to sink many many hours into it.', 'Ironically, given its subject matter, Software Inc has fallen to massive feature creep. Everything you could possibly imagine about running a computing company, from server management to stock trading, is modelled. You might find that fun, but there''s simply too much going on for me.\n\nIf you''re going to have that level of complexity, you need good tutorials - pop up boxes telling you what to click, without telling you *why*, aren''t good tutorials. This game has been in early access since 2015 - ', 'Very Positive', 94.54, 110.05, 2.42);
INSERT INTO reviews VALUES (3695, 362680, 7449, 'fran is just like me fr. i would also do absolutely anything to find my cat, even if it meant losing my mind in the process', 'I swear it''s nostalgia clouding everyone''s thoughts on this game. That, or the art style. \r\n\r\nI used to love this game, but having replayed it again after several years, I found myself getting so annoyed going through it. Around the third chapter, it becomes nonstop dialogue- and it''s so poorly written. Every single person talks like they''re a child, context is constantly misunderstood, and logic just doesn''t exist for anyone in the game. It''s unbearable. And it''s a lot. A. Lot. Of. Talking. Jus', 'Overwhelmingly Positive', 96.67, 13.80, 10.18);
INSERT INTO reviews VALUES (3700, 362810, 173, 'Really fun 1-4 players (online and offline) brawler, the controls are simple and the game is really easy to get into. but still requires skill and fast reflexes to be really good at this game. the game has many characters with different attacks and special attacks so each one plays different than the other, the movement is fluid and the controls are tight and responsive. you can test your skills with bots too in case you have no one to play against. \nhighly recommended especially with this cheap', 'this game could be good but as it is it has very bad balancing problems, and a nauseateing effect on the background, and a humoungos difficulty spike. I give it 2/5 stars', 'Very Positive', 85.55, 4.67, 0.23);
INSERT INTO reviews VALUES (3703, 362870, 504, 'You will open this software and wonder why are things the way they are. You''ll struggle to figure out how to make an autotile properly (Especially the animated water autotiles). You''ll scream at the fact that you cant just type into the editor, and a lot of the code is done through DROP-DOWN MENUS. \r\nbut then, these quite intense limitations will start to embed deep into your subconscious mind. and you''ll be going about your daily activities when suddenly you get an amazing idea for a world that', 'A really, REALLY fickle piece of software imo. Importing custom textures/assets is a nightmare and overall it''s just not a very beginner friendly piece of software/engine. \n\nI''d recommend buying one of the later editions instead of this one - XP has been working wonders for me so far and has tons more features to boot. Many great things were done with RPGM 2K but it''s best left untouched.', 'Very Positive', 93.06, 1749.18, 54.95);
INSERT INTO reviews VALUES (3704, 362890, 63610, 'The fact the games core was made 30 years ago is baffling. We went wrong some where along the way.\n\nIt is oddly refreshing to play a game that has no map, arrows, or quests... you just have to use your eyes and brain.', 'It looks quite pretty but plays worse than the original. Especially the HECU firefights feel clunkier and less dynamic. If I''m just being nostalgic then may the gods of the Internet smite me and my Steam account, and turn this into a positive recommendation.', 'Overwhelmingly Positive', 95.06, 11.03, 30.07);
INSERT INTO reviews VALUES (3706, 362930, 8395, 'Incredible game. Changed my life. I used to be a divorced alcoholic before Garfield kart put me back on my feet. Every victory was an absolute joy and every loss was a chance to grow and learn. I am still divorced and drink heavily but at least I can play Garfield cart too.', 'my girlfriend has been playing this for 52 hours after i shared library''s to her, and she hasnt gotten off once, please return her, i miss her :( 💔', 'Very Positive', 89.97, 0.10, 0.68);
INSERT INTO reviews VALUES (3708, 362960, 6085, 'If there was ever a game that deserved to be brought back from the dead, it''s Tyranny. The absolute lack of any marketing killed what may well have been the best Isometric RPG of it''s time. The setting is a fun Nobledark world where you are the Higher Authority of a Totalitarian State. What that actually means is left completely in your hands.\n\nThe Magic System also deserves special attention as one of very few games that allow you to make some pretty legit combos without either remembering a Fi', 'I waffled between posting a negative or positive review on this one. As I did get 42 hours of fun play out of it. \r\n\r\nBUT!\r\n\r\nThis game is not finished. The ending is left WIDE open. I finished the game and was really, really confused that it was done. I honestly thought there would be 1-2 more acts left in the game. It''s as if you are reading a great, great fantasy book and are about half way through the book and are truly looking forward to reading the rest of the book. You come to a fairly la', 'Very Positive', 86.11, 153.40, 42.78);
INSERT INTO reviews VALUES (3713, 363150, 849, 'Good game to play when retired', 'This game is NOT PLAYABLE on Windows 11 Home !! I''m so regret for bought this game.  \n\nFor more detail: Processor Intel(R) Core(TM) i7-7700HQ CPU @ 2.80GHz   2.80 GHz\n\nBeware!!!', 'Mixed', 68.32, 2990.87, 0.22);
INSERT INTO reviews VALUES (3719, 363330, 230, 'Mind Snares: Alice''s Journey is a good hidden object game with some puzzles not to difficult and some nice designs. I recommend it!!! 💗💗💗', 'Recommend for easy achievements only. Never would have thought I''d see a story like this mixed together with the elements. All in all, would give a C.', 'Very Positive', 88.26, 30.05, 6.78);
INSERT INTO reviews VALUES (3720, 363360, 904, 'Can someone pick this game back up and continue development?  There is so much potential for this game. I like the idea for a more Co-op/ PvE type of play. Hirable Ai to do specific duties and have them susceptible to damage that will need both food and medical when needed. Oh the joy it would be.', 'I''m adding mine to avoid people wasting their money on this game.\nIt''s an abandonware.\n\nConcept was cool but updates were slow and ultimately, it died before being born.', 'Mixed', 67.48, 302.15, 204.13);
INSERT INTO reviews VALUES (3722, 363420, 163, 'A fun little roguelike with a nice card-randomizing system for your powers. It''s been a minute since I''ve played this but I remember having fun with it.', 'Do you like having to replay the entire game everytime you die? in that case sure, it''s a great game but it''s certianly not for me. \n\nAlso, progression in the game feels like its based entirely on luck, if you can''t find any good glyphs right from the get go, you might aswell restart and try again.', 'Very Positive', 91.41, 15.28, 24.67);
INSERT INTO reviews VALUES (3724, 363440, 2047, 'megaman 1: the worst designed mess I''ve ever played\r\nmegaman 2: pretty fun :3\r\nmegaman 3: the other worst designed mess I''ve ever played, but harder', 'I love these games, but this is a bad port. The CWU-01P fight is basically impossible because the bosses projectiles are invisible. Something similar happens on the Metal Man stage in Mega Man 2 where Mega Man will just disappear and you have to dodge between those spikey chandelier things. I''ve seen online that this is a common issue and I''ve seen people defending it saying that it''s true to the hardware. I''m sorry, but no. Sprite flickering was normal for the NES, it was not normal for sprites', 'Very Positive', 86.71, 27.77, 17.40);
INSERT INTO reviews VALUES (3725, 363460, 258, 'sik ass game, cant get to the egg in time bc i suck but still fun!!!!!', 'uhhh. i dont actually have an excuse for this purchase', 'Very Positive', 86.43, 0.83, 0.40);
INSERT INTO reviews VALUES (3726, 363490, 186, 'For $ .19 I''d say snatch it up. First off it has steam cards so I can actually make a profit of buying this game. On top of that it''s a small Dev team and I always like supporting smaller Dev teams because they aren''t yet polluted with all the politics of big studios. They are very responsive to thier community as well, they actually LISTEN to feedback and make changes accordingly. That''s commendable and there is something to be said about that. Oh yeah and the game itself isn''t all that terribl', '\nYou know what? Just forget it and play next game in your library.\n', 'Mostly Negative', 34.41, 2.25, 5.80);
INSERT INTO reviews VALUES (3730, 363530, 247, 'good game', 'Went back to try this again. Wasn''t worth it. Game still broken and unplayable. Was a staff member for the RA2 community for years, so believe me, please don''t waste your money on this broken game that the devs refuse to fix. Should be removed from Steam.', 'Mostly Negative', 27.94, 28.78, 3.32);
INSERT INTO reviews VALUES (3732, 363600, 764, 'dumb game 10/10\r\n', 'Was on sale for $1.30 (w/ Tax) so you may be wondering why even bother refunding? It doesn''t respect your time as it''s Tedious and click heavy just as many others have claimed. If you somehow find this enjoyable, I salute you, but I recommend doing something else to save your time and hands.', 'Mostly Positive', 71.73, 36.03, 0.88);
INSERT INTO reviews VALUES (3733, 363610, 105, 'Botology\n\nHas a total of 6 trading cards.', 'Poorly localized game with broken English, confusing tutorials, convoluted mechanics, repetitive gameplay, and poor design.', 'Mostly Negative', 26.67, 1.08, 1.68);
INSERT INTO reviews VALUES (3738, 363680, 3447, 'The game pretends that you''re the admiral of a sector fleet... then proceeds to treat you like a thrall on the gun deck who isn''t loading the cannons fast enough. \n\nMultiplayer is dead, so can''t really speak to it, but single player is.... interesting.\nHonestly, it''s very tricky, the combat is brutal, and the computer will absolutely punish as badly as it can, even on easy mode, if you make a mistake or misstep. At first it''s frustrating, even maddening. But eventually the Stockholm syndrome set', 'game really does not requires a lot of thinking. You need to be like Maru. If your finger rpm is great, well, you will win, if not.\n\nThat is not strategic thinking. It is micro managment\n\n\nI do not recommend this game', 'Mixed', 67.19, 41.57, 8.73);
INSERT INTO reviews VALUES (3740, 363860, 275, 'They have a major update that by teases is gonna make this game from a solid 8/10 to at least a 9/10 imo\nSlept on game. Fun characters. All can be unlocked in game no microtransactions\nAmazing art style and I got 38 hours out of it just to 100% it and enjoyed every min of the 38 hours.\nW Game\nW Devs\nCan''t wait for the major update to come back and play more', 'game should be called midforce', 'Mostly Positive', 75.64, 42.60, 8.53);
INSERT INTO reviews VALUES (3741, 363890, 3439, 'I been using this to make a game called Corrupted Worlds the development has been going on since November 2024. And its an amazing engine for beginners', 'nah the fact that an update to the engine to allow a search feature is £8 wtf? just add it to the engine like every other engine... what is this? an engine or a game... lmfao', 'Very Positive', 90.32, 320.77, 9.98);
INSERT INTO reviews VALUES (3744, 363930, 1920, '-Buy it\n-Farm Cards\n-Sell Cards\n', 'Dead Age is a turn-based survival RPG with zombies.\nThe gameplay is simple and doesn’t offer much new.  \nMaps, enemies, and combat become repetitive and boring fast.  \nIt’s a bit fun and relaxing but nothing special.  \n3.5/10', 'Very Positive', 81.35, 4.38, 12.18);
INSERT INTO reviews VALUES (3748, 363970, 304, 'In Clicker Heroes, you play as John Mouse, and aim to collect all 151 Heroes!', 'Don''t.', 'Very Positive', 90.13, 577.40, 1992.75);
INSERT INTO reviews VALUES (3749, 363980, 246, 'Forget Me Not: My Organic Garden\n\nHas a total of 7 trading cards.\n', 'no automation, slow, clunky. the story is good, but the tasks are too tedious to push through to get to it. the pop ups alerting you of a new quest interrupts your flow, and takes longer than needed to get off your screen.\n\n buttttttttttt the art and the colors are quite nice, even though the white background is blinding.', 'Very Positive', 82.93, 1.15, 1.17);
INSERT INTO reviews VALUES (3751, 364050, 226, '⠀', 'These camera rotations gave me a headache.', 'Mixed', 53.10, 5.43, 9.88);
INSERT INTO reviews VALUES (3759, 364300, 237, 'For an early access game, my first impression is a positive one. Unfortunately, Space Rogue is held up to the high standards of Faster Than Light (FTL), even though it is a different company, designing a completely separate game. It does, however, have large amounts of borrowed UI and  game mechanics, making it appear much like FTL. The game is very similar to FTL in many respects and at the same time it is its own game. If you enjoyed FTL and want to try a new type of strategy for this budding ', 'I had a longer more detailed review all typed up but it somehow got dropped.\n\nLong story short: Space Rogue is a poor copy clone of FTL and it doenst improve on much of anything other than the graphics and sound and unfortunatly neither is a good change and actually makes the experience worse. In fact takes several steps back in terms of the balance and playability....\n\nThumbs down. No reason to play Space Rogue if you have FTL already.', 'Mixed', 59.07, 13.35, 0.60);
INSERT INTO reviews VALUES (3760, 364360, 17919, 'As of the current steam xmas sale, if you own Warhammer 3 -\n - this is the most price per quality and quantity content ratio you will get probably ever. Highly reccomended.', 'This game SHOULDN''T cost $52, 8 years after release.', 'Very Positive', 82.20, 18.53, 824.57);
INSERT INTO reviews VALUES (3763, 364390, 591, 'This is the 2nd game of the Devil Came Through Here Trilogy.  Another great story just like the Cat Lady, although some of the game plots are open for interpretation.  The game is fully voiced and done well.  Overall a great experience as a mild horror game. \r\n\r\nMost of the achievements are easy to get.  The endings B and C achievements could be a little bit tricky.  For reference, first run took me 5+ hours,  subsequent runs are around 2-3 hours.  \r\n', 'The Cat Lady is still Harvester''s best game, though all of them are flawed. If you really liked that game then you should probably play this one as it is connected and features some crossover lore that ALMOST saves the rest of the game. I didn''t care about Joe and Ivy the way I did about Susan and Mitzi, though, and I don''t think this one gets to the deeper levels that the other games do. Agnes is probably the most memorable character here and absolutely the most likable. The plot feels like a n', 'Very Positive', 93.57, 17.22, 3.85);
INSERT INTO reviews VALUES (3764, 364420, 1852, 'sean please finish this game and i''ll owe you my life', 'The game is unfinished and abandoned.', 'Mostly Positive', 79.00, 565.12, 28.03);
INSERT INTO reviews VALUES (3767, 364510, 175, 'I played much of the free version before it was fully released, and even on Steam. A fun game that tickles that need to loot and improve your ship. This game is one of the reasons why I never passed the CPA exam all those years ago. Not going to lie I was very disappointed that the game doesn''t have a "Part 2" yet because I was very excited to recently get to the end of the current chapter. \n\nI feel like the game would be improved by a few quality of life UI features, but otherwise gameplay is s', 'It is dry, repetitive, there are no ship upgrades, your weapon permanantly turns off when your reactor overloads, forcing you to turn it back on rather than just stopping firing. And the economy is wonky; half your loot can only be sold to a specific geezer who in turn only buys a specific amount of said loot.\n\nExploration is cracked as well, with the stargates in weird positions, and your sensor range pretty low so you gotta go through the real boring grind of meandering across the entire syste', 'Very Positive', 87.43, 31.10, 10.20);
INSERT INTO reviews VALUES (3768, 364630, 125, 'AirMech Command\n\nHas a total of 7 trading cards.', 'Trash', 'Mixed', 64.00, 1.00, 12.98);
INSERT INTO reviews VALUES (3769, 364640, 164, 'FreeCell Quest\n\nHas a total of 13 trading cards.\n', 'At first it is fun enough. But after a while the levels get more difficult, ok. The (distracting) damage you get increases a lot. Even with getting better equipment. Losing a level / dying loses you money. Which you need  a lot to get better stuff. Resting costs more money. Traveling spawns random encounters a.k.a. replay this level now!! I don''t want to replay levels I already finished, but it is the only way to get money when you ''hit a wall'' in your progress.\r\nOnce you start losing, you land ', 'Very Positive', 82.93, 2.30, 12.35);
INSERT INTO reviews VALUES (3781, 364810, 100, 'I remember playing this game when it was new and coming back to it after so many years and for such a cheap price, I highly recommend Star Trek fans give this a try. There are a couple of instant game over points from story choices, so keep that in mind and make many saves.\r\n\r\nThe game uses live recordings, but with early PC gaming green screens and compression, so expect the visuals to be a bit lacking. But it''s work it to see Shatner, Takei and Koenig return to their characters in the Monster ', 'It''s incredibly tedious with long boring missions that you''ll fail and have to do over again several times.\r\n\r\nMany old games hold up well today.  This one does not.  It''s based on the idea that you should make a game take a long time so the customer feels they got a lot out of it.  That''s one part of gaming I''d like to leave in the past.', 'Very Positive', 81.00, 11.50, 0.82);
INSERT INTO reviews VALUES (3782, 364820, 177, 'Follow the directions under other posts about making it work on windows 10, its one value change in one readme file, its very simple. also remember that older games do not auto save, and that they can be glitchy.  the first thing you should do is either play the Federation or Klingon campaigns. Only those campaigns have full game tutorials. after that have fun!', 'very buggy even with adjusting the patch in file settings. will randomly freeze up computer. if you have graphics on low/med its bearable. mind you this is early 2000''s game and i run windows 10 and have 16gb ddr5 ram/ ryzen 3 3600 series CPU', 'Mixed', 61.58, 56.85, 6.30);
INSERT INTO reviews VALUES (3789, 364930, 378, 'The original card game in Japan, Koi-Koi Japan is a very good card game with some nice designs and a good soundtrack. I highly recommend it!!! 💗🌸💗', 'I enjoyed Koikoi mode and some campaign modes.\r\nBut the challenges in campaign were ridiculously restricted.\r\nThere was no fun to play Koikoi when it required specific hands.\r\nIf you''d like to play just koikoi, I highly recommend this game.\r\nOtherwise it''s nothing.', 'Overwhelmingly Positive', 95.50, 44.05, 38.03);
INSERT INTO reviews VALUES (3790, 364940, 151, 'yayPonies', 'Game simply doesn''t even work as intended. \n\nGo to the character creator, and it hard crashes your whole pc. Waste of money outdated software.', 'Mostly Positive', 70.20, 0.15, 0.17);
INSERT INTO reviews VALUES (3793, 365020, 300, 'revolutionary', 'wemon are scary :(', 'Mixed', 57.67, 0.40, 2.20);
INSERT INTO reviews VALUES (3803, 365160, 1375, 'Average Canadian Winter simulator with the added horror element of being in quebec.', 'For a solid 12 hours I loved this game and thought for sure I''d be posting a positive review and recommending it to any fans of atmospheric, slow burn detective games. Then the ending happened. By far the most rushed, poorly thought out and disappointing ending to a game I''ve played. Everything leading up to it was stellar - but on a dime the game completely changes into a very poorly handling first person shooter and does away with all the evidence and clue building you''ve been enjoying for 10 ', 'Very Positive', 82.18, 7.40, 14.63);
INSERT INTO reviews VALUES (3806, 365260, 147, 'One of my all time favorite games. worth having, worth playing. still play this game on my phone while killing time. easy to learn , a challenge to master. By far the best sub war game simulator Ive played to this date.', 'Lacks the gameplay depth and graphics of Silent Hunter 4 and 5. A bit too arcade-y for me.', 'Very Positive', 91.16, 0.78, 1.08);
INSERT INTO reviews VALUES (3810, 365300, 151, 'The only complaint about Transmissions: Element 120 is that it''s too short! \n\nMORE, PLEASE!', 'It''s pretty boring. If you just threw 90% of what was in the base game of HL2 into a mod, this would be it. They changed the gravity gun into a ''rocket jump cannon'' - kinda unremarkable to me. I also ran into bugs a few times with the new door-unlocker gadgets where they wouldn''t open; kinda unnecessary anyway, if you ask me. The final battle, it''s unclear if you are supposed to fight or run to an escape location because the striders take SO MUCH DAMAGE. I haven''t played HL2 lately, but I rememb', 'Very Positive', 94.04, 2.73, 1.62);
INSERT INTO reviews VALUES (3815, 365360, 13197, 'Really fun game, but...\nThe only problem is there are so many anti-tactical things that stop you from being able to plan. "If bad luck makes your plan fail it wasn''t a good plan" How am I meant to make a plan when I have no idea on the terrain, very limited troop placement, inconsistent enemies and task difficulties and vague mechanics. It''s a shame because it''s a really fun game and I would recommend it but the steep learning curve also comes with a frustrating realisation that the game is more', 'This game is very interesting. The problem I eventually had came as I was reading the slogan on the main page, "losing and comebacks are part of the game". After 100ish hours, I determined there aren''t really comebacks in the game, either you play perfectly, or you just lose. I sometimes enjoy this experience, I usually prefer punishing games - harder difficulty, overcoming adversity. But in this case I slowly realised that I actually wasn''t having fun while losing... I was just trying as hard a', 'Very Positive', 89.16, 63.85, 162.80);
INSERT INTO reviews VALUES (3818, 365450, 7247, 'The game has a really cool and stylish UI, but for users who have been using Linux for a long time, it seems a bit "like a square peg in a round hole". I hope the game has more attention to detail. I use arch btw', 'This is one of those games where I wish there was a neutral option. On one hand, this game has nice graphics and music. On the other, it''s a very sensationalized game with not a lot of progression.\n\nI wouldn''t buy this game if you want to build real knowledge or skill, for that try Greyhack, Hackmud, or Bitburner. But for a fun little game to kind of introduce you to the world of hacking games, it''s worth the price (on sale.)', 'Very Positive', 94.27, 0.70, 1.65);
INSERT INTO reviews VALUES (3826, 365660, 308, 'i love skateboarding', 'There are many games which require a degree of masochism to play due to how hard they are; Super Meat Boy and Cuphead spring to mind. These are fantastic games despite (but also perhaps due to) their difficulty as they reward the player''s reflexes and skill.\n\nOlliOlli2 is not one of those games for the basic fact that the inputs do not feel anywhere near as tight as OlliOlli 1 (which I''ve completed on RAD mode). It''s one thing to get bitch-slapped by a game for being a scrub but when the game do', 'Very Positive', 86.36, 9.55, 5.97);
INSERT INTO reviews VALUES (3831, 365770, 264, 'If you crave more Metal Gear Solid 1 VR missions, this is the closest non-MGS game your going to get.', 'After playing this game, I decided to go to the local Arby''s and try to steal all of their meat. I moved around the store the same way that I did in this game. An hour later, they found me in their freezer. I couldn''t get the door open.', 'Very Positive', 80.68, 1.85, 0.50);
INSERT INTO reviews VALUES (3833, 365810, 241, 'Fun little game to play with a HOTAS. Great story from WWII history as well. The AVG or Flying Tigers had a flawless record in dogfights again the Japanese in superior planes. The Flying Tigers were just so much better. General Chennault was really somethin''', 'crashes upon launch. Every. Single. Time.', 'Mostly Positive', 73.86, 27.58, 0.98);
INSERT INTO reviews VALUES (3834, 365820, 101, 'blud are you dumb? are you getting rude to man? BOP!', 'scammed you have to purchase other stuff, waste of time 100% wrong schemy scammy desperate tricky tactics', 'Mostly Positive', 72.28, 0.00, 0.00);
INSERT INTO reviews VALUES (3839, 365890, 110, 'The special quirks are initially hard to acomadate (coming from an old-school wargamer) - but it provides a very satisfying experience after the teething pains.', 'don''t waste your fucking money, the cunt won''t even launch, fuck this', 'Mixed', 68.18, 125.57, 0.08);
INSERT INTO reviews VALUES (3840, 365900, 249, 'Old school dungeon crawler rogue like.   Simple graphics but very cheap and has a certain appeal.  Uses grid based movement and attacking.', 'Game no longer launches when I attempt to open via steam', 'Very Positive', 85.54, 17.77, 5.43);
INSERT INTO reviews VALUES (3841, 365960, 3281, 'I''m revisiting rFactor 2 after a couple of years away, mainly because I;m really enjoying Le Mans Ultimate.\nThe improvement in the whole experience, especially the front end, is really impressive.\n\nThis is back on my list of driving Sims to play', 'I didn''t pay a lot for it since it was on a discount, but you''re basically buying just the engine here, and all the cars and tracks are in payable DLCs.\n\nNeedless to say, I don''t like this sort of business model, so this gets a "thumbs down" from me, regardless how good of a sim it is.', 'Mostly Positive', 76.96, 366.22, 0.18);
INSERT INTO reviews VALUES (3843, 366000, 162, 'Nothing quite like it, besides Alliance Space Guard, or maybe a heavily modded Space Engineers, or a DCS set in space. All other major titles fall short, and Rogue System Reboot may never get around to being finished with the involvement with ISI.', 'Buyer beware! This is Abandonware.\n\nAmbitious. Could have been great.', 'Mixed', 61.11, 30.33, 7.68);
INSERT INTO reviews VALUES (3847, 366090, 5557, 'Not going to let this game go unnoticed anymore, as far as it goes, this game is amazing, the Devs are dedicated and on point to things their community wants. That''s already more than most companies these days.\n\nFactory/city management simulation done really well, its honestly very peaceful and enjoyable. The threats scale with your population and the designs are limitless, your colony can starve and you have to rebuild it, making outposts and sending resources to friends in the same game. freed', 'I make a stand, right here, right now, against people of colour.', 'Very Positive', 91.65, 393.02, 1.92);
INSERT INTO reviews VALUES (3851, 366220, 1435, 'After having played for a bit over 5000 hours, I still can''t really make up my mind if Iove or hate this game. I promise if I make it over 10k, I will finally get off the fence on that question and come back and let you guys know.', 'Do not buy, Do not play, if you are interested at all, flame the Devs on the forum and continue reporting their financials for review, they have been farming a small community of addicted players for decades now and delivered about 4 innovative updates in all of this time, Also Wurm Unlimited was abandoned and sectioned away from Wurm Online content or development/upkeep/service support entirely, these are the scum of the Cosmos, they should all be in prison suffering for the rest of their lives', 'Mostly Positive', 70.59, 5744.37, 1479.67);
INSERT INTO reviews VALUES (3853, 366240, 507, 'Solid fighter from the days when men were men, German aristocrats sought to save a fallen world, and pro-wrestling was to be taken seriously as a martial art.', 'really bad. got banned for calling a kof hater deranged on the forums. def not buying shiddy of da wimps now :)', 'Overwhelmingly Positive', 96.45, 10.73, 1.18);
INSERT INTO reviews VALUES (3854, 366250, 946, 'Thank goodness, you can play with unlimited credits!! I never got to beat the original arcade game when I was little! Now, thanks to this version, you can beat the whole game in about an hour without spending a single extra coin! And that''s pretty dope, if you asked me!!', 'Great Game! Bad port.\r\n\r\naudio and controls delayed. frame rate dives to 5fps when more than 5 enemies on the screen.', 'Very Positive', 86.05, 2.00, 1.52);
INSERT INTO reviews VALUES (3855, 366260, 244, 'Metal Slug X is a "revised" version of this title, it includes different weapon placements, some different times of day, just in general is a different game for very subtle reasons, but enough reasons, that end up becoming a significant change.\r\n\r\nI personally got this game for fairly cheap on a sale on one hand to complete my collection of MS games, as well as to check the differences; turns out this is the game I played as a child at the arcades and not the revised version like I thought. I pe', 'Big metal slug fan. Loved these at the arcade. The first one works great and everything is locked on in number one. Number 2 though, Jesus...... they made it TERRIBLY bad. The biggest and most annoying thing by far which makes this game pretty much unplayable is the simple fact that you cannot aim DOWN. A lot of the fights, there are enemies that are below you and you can''t even shoot at them.... Literally an entire boss fight with them right below you and you can''t aim down to shoot them. WTF w', 'Very Positive', 85.25, 1.02, 0.52);
INSERT INTO reviews VALUES (3858, 366320, 1177, 'A decent platformer with beautiful visuals and art. However, it lacks certain elements like map navigation. Sometimes you feel a bit lost and don''t know what exactly you have to do or where to go. \nStill giving the thumbs up, because it''s short and overall a solid game.', 'I was really excited to play this game because the art and music are absolutely beautiful but I was ultimately forced to drop it. The game is frequently buggy, with unclear direction and confusing platforming and progression. If you have a higher tolerance for non-linear games, this may be for you but it really wasn''t for me', 'Very Positive', 80.80, 13.00, 1.85);
INSERT INTO reviews VALUES (3862, 366440, 697, 'This game was SO good when it first came out in 2016. Here I am 9 years later in 2025, still thinking about this game. :/ I hope one day this IP gets made again. Or at least another game like it. Two teams, one player on each team playing an RTS game getting upgrades for the team, infrastructure, etc. The rest of the players on the team are the actual foot soldiers for the RTS player. SUCH a dope concept. RIP Savage Resurrection. \n\nSide note: Ironic the game is called Savage RESURRECTION. yet th', 'Don''t be misguided by the positive reviews this game is DEAD. There is no one online and there is no single player content. Devs made it pretty clear that they won''t be supporting this game anymore. AGAIN, DO NOT BUY.', 'Mixed', 49.78, 9.08, 37.65);
INSERT INTO reviews VALUES (3870, 366640, 144, 'Played it a few years ago and liked it quite a lot. The story is sadly unfinished and the game is generally a bit buggy/sloppy in some feedback during combat. But the mechanics themselves with combos, area effects and parry meter are fun. Each character has various abilities that were also relevant outside of combat in puzzles and exploration.\n\nI feel this game could''ve been great with a bit more money thrown in it''s direction. As is it''s still a fun game and I occasionally think of replaying Sh', 'Even for less than $2 it''s so awful it''s not worth the risk of anyone thinking you''re a furry.', 'Mixed', 63.19, 29.03, 1.98);
INSERT INTO reviews VALUES (3877, 366870, 617, 'Wow. I didn''t expect this plot twist at the end and I already knew there would be one. So that''s a plus. What I didn''t find so good were the knife fights. You have to defend yourself with your knife against the deep sea fauna and with every knife attack there''s a time delay because you''re underwater and wearing a diving suit. It''s realistic, but you have to time your attacks perfectly or you''ll get hit. And I was almost always hit. Several times. I found that annoying. Fortunately, you can often', 'None of it really feels good. The walking, the narration, the story, the menus. They all seem to be trying to do something but I don''t feel like it comes together. Play Soma instead (it even lets you turn off the monsters now).', 'Mostly Positive', 76.50, 7.68, 0.67);
INSERT INTO reviews VALUES (3878, 366910, 555, 'Mod support would revive this game.\nBut that will never happen.', 'Gave this game a chance at $1. Really want to like this game. I can see some grind but the lander is just horrible to pilot. You do not need the atmosphere to kill you, you can easily kill yourself just trying to pilot the lander through the atmosphere. The Dev need to turn down the planet''s environment effects like 15-20% and make the lander 2-3x tougher. Also there is not much resources to get. Getting gas is pretty hard since you have to pick it up mid-flght using the lander is this horrible ', 'Mixed', 49.01, 63.85, 4.35);
INSERT INTO reviews VALUES (3881, 366970, 159, 'A funny, easy to learn, hard to master game, if you played the original, this is more of that, a great game overall, you need a bit of practice to fully enjoy the game, but after a while, it just feel good to complete a level, specially when you get the par time.', 'not worth it.', 'Very Positive', 90.57, 18.17, 1.18);
INSERT INTO reviews VALUES (3883, 367000, 130, 'kinda fun', 'I love Minesweeper and have been wishing for a game that builds on the original in a way that feels significantly additive. This unfortunately is not that. Looking for regular Minesweeper with minimal added variation? Then this is it. But my quest for a true follow up to the original continues.', 'Very Positive', 89.23, 4.32, 1.42);
INSERT INTO reviews VALUES (3885, 367020, 115, 'Played the game trying to get the girls to love me \n\nEnded up with a boy\n\n10/10 realism', 'I wanted to like "No One But You", I really did. But it has so many problems that I just can''t recommend it. There''s a lot of ideas in here that could have been great, but all the plotholes and inconsistencies really weigh it down. This VN also tries way too hard to be very emotional and tug on your heartstrings, but it doesn''t work with poor pacing and one-dimensional characters. NOBY takes a lot of inspiration from common Japanese VNs, but fails to understand what makes those elements from tha', 'Very Positive', 82.61, 8.12, 6.18);
INSERT INTO reviews VALUES (3897, 367270, 2206, 'Good game if you like offline bot games.\r\n\r\nThere is offline progression. \r\n\r\nI think the devs should focus more on single player content as the player base is extremely low.', 'I do like it, I bought it years ago - but it is abandonware. Devs surfaced to drop a patch 6 months ago and disappeared again. I have no idea why the reviews are "very positive" as it absolutely will not be finished.', 'Very Positive', 82.09, 3.67, 4.88);
INSERT INTO reviews VALUES (3902, 367450, 5701, 'I''ve gotten about 32 people killed because I keep funnelling the funds to my friends in Palermo.', 'Some of the worst, least helpful tutorialization I''ve ever seen. Unless you''re an architect IRL and already have an external understanding of bridge construction, I do not recommend it.', 'Very Positive', 89.91, 0.83, 1.87);
INSERT INTO reviews VALUES (3903, 367500, 21355, 'Bought this game on sale, didn''t read a review, didn''t research the game, didn''t know anything about it. Just saw a ridiculously cheap game and thought, oh what the hell I''ll just buy it... I waited 3 months then played it...\n\nOH MY GOD THE FIGHTS ARE AMAZING! IMAGINE BUYING SOMETHING ON A WHIM AND IT TURNS OUT TO BE EPIC! so far id give this game a 9/10', 'Honestly, I tried to like this. I was hoping it would fill the RPG need like Skyrim or similar. It isn''t terrible and honestly  there is huge potential here. I found after a few hours I simply lost interest, It is likely me more than the game.', 'Very Positive', 88.42, 5.37, 5.37);
INSERT INTO reviews VALUES (3904, 367520, 131920, 'I like to believe that all the events in the lore are a realistic documentation of what happened under some Austrialian''s backyard over the course of a week.', 'I loved this game until I started violently bursting to Hornet R34. Now, every time I replay the game, I instantly combust. This is really frustrating, and I don''t know if I''m going to be able to play Silksong when it releases. I tried going to therapy, but they called up the local mental hospital, and I was trapped in a white room for a week. Would not recommend.', 'Overwhelmingly Positive', 97.19, 29.83, 73.92);
INSERT INTO reviews VALUES (3906, 367570, 369, '\nPlayable.\n', 'Circles where you have to jump between inside and out - to avoid obstacles or go to the next rim.\n\nI have to say I wish there was a "meh" recommendation.  Not sure if the game just isn''t for me or there is a control problem, where the switch-over timing has to be perfect or a combination due to my age.  Got to down vote reluctantly.', 'Very Positive', 86.99, 0.28, 0.33);
INSERT INTO reviews VALUES (3907, 367580, 3825, 'HOOK is composed of lines, dots, and various wifi icons.', 'Much better if this game could be 2x shorter but in this state it is widened a lot', 'Overwhelmingly Positive', 96.68, 2.80, 1.35);
INSERT INTO reviews VALUES (3909, 367670, 1320, 'I don''t know why steam says I have like 7 minutes in controller companion but i''ve been using it for years. super useful, real simple to use, love it. lets me be super lazy and use my pc from a distance with just my controller, and there''s a simple bind for shutting it on and off. much love to whoever made this', 'fucking thing won''t launch anymore.', 'Very Positive', 90.45, 0.10, 0.23);
INSERT INTO reviews VALUES (3916, 368000, 128, '100ft Robot Golf\n\nHas a total of 6 trading cards.', 'Online doesn''t work, and the mecha gameplay is so severely unbaked that all you''re really left with is a golf game that relies on its silly presentation and art style to make it interesting. Unfortunately, it''s not nearly enough to carry the game. Maybe it''s more enjoyable in the singleplayer story, but that''s not why I bought this.', 'Mixed', 69.53, 1.15, 0.57);
INSERT INTO reviews VALUES (3919, 368070, 4153, 'Sniper Ghost Warrior 3 is an immersive and intense tactical shooter that puts you in the role of an elite sniper deep behind enemy lines. The open-world design allows for strategic freedom, letting you approach missions in a variety of ways—whether you prefer long-range precision, stealthy takedowns, or all-out action. The game’s environments are vast and detailed, creating an engaging atmosphere that enhances the thrill of each mission.\n\nThe sniping mechanics are incredibly satisfying, with rea', 'I''ve never played such an unfinished, unrefined, unloved pile of rubbish in my life. I almost quit at the prologue after hearing the voice acting alone.\n\nEdit: I''ve finished the game and I have to reiterate, don''t even smell this game, I have never seen such a shit story. Don''t even buy this on 90% off discount, it''s not worth your money.\n', 'Mixed', 67.42, 5.50, 22.93);
INSERT INTO reviews VALUES (3923, 368160, 116, 'Even if it is at world ends 👍', 'Much better then the first episode by fixing the music and background issues from the first. Really offputting to deal with the changes in character and location names.  The story is still disjointed and gives a sour feeling due to a lack of conflict until the very end of the story (like the first) plauges this visual novel.\n\nNot worth the time investment. Feels like a incomplete product.', 'Overwhelmingly Positive', 96.55, 12.73, 12.60);
INSERT INTO reviews VALUES (3924, 368180, 103, 'Just finished 100% the game. It might be an unfinished product in certain areas and is a simplistic game, but the movement and levels are really fun', 'This game is unfinished. I played through about 3 hours before realizing many of the tracks are to glitchy to play reliably. The handling of the marble just feels wonky compared to more polished older games like Marble Blast Ultra. Don''t purchase this game if you are looking for that experience.', 'Mostly Positive', 77.67, 26.30, 4.33);
INSERT INTO reviews VALUES (3926, 368230, 3277, 'Fantastic game with simple controls. Be warned, though, as you WILL eventually be outscaled by the enemy, at which point I highly recommend you just upgrade to Kingdom: New Lands (It''s this game, but evolved!)', 'I love the idea and style of the Kingdom games, but I just can’t recommend this one. The inability to control archer placement — your main line of defense — makes for a maddening experience. Too often, you’ll lose runs simply because archers bunch up on one side while the other is left undefended, or worse, sit idle in old towers. There’s real strategy here, but too much of the game revolves around fighting the placement AI instead of the enemy.', 'Very Positive', 87.49, 31.63, 20.48);
INSERT INTO reviews VALUES (3928, 368260, 10460, 'Dude this game would''ve skyrocketed if it wasn''t for some questionable design choices and questionable marketing. I love the game but the weird middle-school "drama" and increasing friend levels (weird hangouts and trying to please people) was awkward. I''m all for cheesy comic book dialogue from the golden era but let''s be real, I really wish it was darker in tone. It''s "dark" in the sense that it has that late 90s-early 2000s edgy angst. It''s like watching Blade but they took out the cursing an', 'If you buy this game, talk to everyone in the Abbey before doing anything at the Forge.\n\nThere is an easily reproducible save breaking bug (Faithbreaker bug) that stops Story Missions from spawning that happens near the end of Act 1 that has existed since release that Firaxis could/would not fix after being reported and confirmed existing since Day 1. Even after the release of four paid DLCs over several months.\n\nLost 2 saves to this bug. First near release when I didn''t know about it. Second af', 'Very Positive', 83.46, 173.73, 98.38);
INSERT INTO reviews VALUES (3931, 368340, 9329, 'Still the only video game to make me ugly cry. Some shows and movies have made me cry but this was the first game and oh my god. \n\nPlease play it. Pretty pretty please. You will be so happy with your decision.', 'Crosscode is not a bad game. I decided to buy it because the demo was fantastic with its nostalgic graphics, charming characters, good writing, and fast, responsive combat. \n\nBut after playing through the full game, I found that maneuvering through the maps quickly became a chore, the overwhelming amount of puzzles needed to progress areas became tiring, and the itemization where you have to gather different components to purchase gear felt like a needless grind. \n\nI REALLY wanted to like this g', 'Very Positive', 93.70, 68.07, 56.48);
INSERT INTO reviews VALUES (3932, 368360, 3467, 'ted was on a expedition for 20 days he comes home and gives me 1 soup and a broken gas mask 10/10 game', 'Buy Remastered', 'Very Positive', 81.31, 7.15, 2.15);
INSERT INTO reviews VALUES (3933, 368370, 4774, 'This game is like a breath of fresh air in the FMVverse. Unlike many other games in this genre, here you don''t choose from any options and decide how the story should progress, instead all you do is type keywords into a video database and watch clips. That''s literally it, nothing else to it. \n\nOnce you discover a certain percentage of the clips, the game ends. It''s up to you if you want to find the rest of the clips - you''ll be rewarded with an achievement at least.\n\nThe game doesn''t have a whol', 'You have to watch 271 random clips of a woman talking.', 'Very Positive', 88.48, 2.50, 1.63);
INSERT INTO reviews VALUES (3934, 368430, 541, 'https://steamcommunity.com/sharedfiles/filedetails/?id=1270466211\nhttps://steamcommunity.com/sharedfiles/filedetails/?id=794774979\nhttps://steamcommunity.com/sharedfiles/filedetails/?id=916015747', 'How this game was made on a budget of $43,833 baffles me, it has some awful voicework and overall terrible execution in just about every aspect. It''s a full blown scam full price since it barely even takes 2 hours to complete, the ending is rushed but the story is very boring so not that important. There are thousands of better indie horror games out there for a fraction of the price.\n\nTL;DR\nSave some money and buy literally any other indie horror game.\nKickstarter scammers', 'Mixed', 67.65, 4.73, 2.80);
INSERT INTO reviews VALUES (3935, 368450, 114, 'Using a Kaleidoscope to the sound of Moonlight Sonata may have been one of the strangest and most beautiful things I''ve experienced in games. \n\nRememoried is a peculiar walking simulator with more than 20 different levels, focused on precision jumping and enigmatic puzzles. The big different mechanic is the "memory" factor which, when walking and changing direction, completely changes the elements of each level, making the gameplay interesting.\n\nIf you like games that challenge normality, explor', 'weird mechanics and controls. weird echo in voice acting. i just swing my mouse to look around couple times and its game over.', 'Mixed', 55.26, 7.97, 0.53);
INSERT INTO reviews VALUES (3937, 368500, 9105, 'RARE UBISOFT W, I literally reinstalled Syndicate and I unlocked 89% of my achievements. Amazing.', 'There is a real chance that this just outright wont start. For a lot of people it crashes just after intro videos when the game says "press any key to continue"\r\n\r\nThe game is good. But cant recommend it if I cant play it.', 'Mostly Positive', 78.76, 104.83, 7.58);
INSERT INTO reviews VALUES (3939, 368590, 165, '5/10', 'the game feels repetitive and frustrating at times. The puzzles can be confusing, and the controls feel clunky. The story isn’t very engaging, and it lacks variety. It’s a short game, but not very memorable or enjoyable.', 'Mixed', 59.39, 5.82, 32.28);
INSERT INTO reviews VALUES (3941, 368610, 419, 'this is definitely a game. a game that you play. a game where you have some gameplay. you play the game. do you like playing games? yes you do otherwise you wouldnt be here. anyway you can definitely play this game. no questions asked. how many times will you play? for how long? you decide your fate. in this game of games. its a game type of thing. you wouldnt understand unless you played. done reading now? feel informed and ready to make a financial decision? good. cause i have nothing else to ', 'This is really one of those gams I wish there was a mixed or just ''informative'' review for. \n\nThis game isn''t really bad, but it is completely flat. There is very little mechanical complexity and I haven''t felt challenged at any point. I haven''t finished it and maybe it gets "harder" once you get to the point where there is nothing left to level in the skill tree and you want to make it to the 100th floor but even if that is true the mechanics would be the same and there just isn''t much meat on ', 'Very Positive', 94.51, 16.80, 7.43);
INSERT INTO reviews VALUES (3942, 368640, 154, 'A dark and gloomy yet charming fairy tale, featuring exceptional design, captivating art style, innovative mechanics, and challenging gameplay.\n\n\n녹용과 반딧불이.', 'I liked the way this game tells its story, the soundtrack is fine and it sure is a unique side-scrolling puzzle game; I''ll give it that much.\r\n\r\nHowever, the gameplay is actual torture. Everything feels slow, RNG is rigged against you and finishing a stage feels like arriving at home after a dentist visit - it has this "Finally it''s over" feeling of relief, and leaves you exhausted.\r\n\r\nThe 100% achievement journey includes a collectathon for the true ending, beating some stage specific challenge', 'Mixed', 62.34, 11.42, 9.52);
INSERT INTO reviews VALUES (3948, 368730, 750, 'I would like to review this game\nBut there is no time to explain', 'Main gameplay mechanic of a nearly uncontrollable beam gun that pushes you everywhere as you try to complete super meat boy-like levels was just frustrating and not really fun. Coupled with super low fidelity art design and bare bones parody story prompt, just didn''t have a good time enough to keep playing.', 'Very Positive', 80.40, 2.93, 0.27);
INSERT INTO reviews VALUES (3954, 368860, 760, 'i like killing ever one i see and then rob ever building and die by jumping off the big building', 'I was scammed into this updateless game many years ago, now it resides as a stain in my steam library.', 'Mostly Negative', 30.79, 21.03, 10.98);
INSERT INTO reviews VALUES (3959, 368990, 791, 'I don''t get all this negativity from people!\nit say it on the title clearly...  Despair ', '\nRUN FOR YOUR LIIIIIIIIFFFFFFFFFEEEEEEEEEEEEEEEEEEEEEEE!!!!!!!!\n', 'Mostly Negative', 33.25, 0.27, 0.58);
INSERT INTO reviews VALUES (3960, 369000, 203, '⠀', 'You need to play this game 60 fps if you want to jump consistently if you play at 144 fps or more you only jump 50% of the time even with a full charge.', 'Mixed', 66.50, 14.65, 13.07);
INSERT INTO reviews VALUES (3964, 369070, 872, '💋', 'The visuals are great but the gameplay is extremely stiff. The game demands you play exactly how it wants you to. You must fight every encounter in a particular order otherwise you will not progress. Reminds me most of the original castlevania games, but those at least had more variety in the weaponry opposed to this. You have a basic set of abilities and a parry you have to rely on about 80% of the time. On the whole its trying to emulate the difficulty of retro games without giving you the too', 'Mixed', 69.84, 23.68, 6.82);
INSERT INTO reviews VALUES (3967, 369110, 405, 'I get why this game has mixed reviews, it''s very janky. Half the times I died were because of some weird quirk with the game''s physics, like I landed on a floor wrong and couldn''t jump, or I went near an explosion after it went off and the hitbox was still there, or I got stuck in the animation of opening a door. And this game is very punishing when you make small mistakes, it''s risky just moving around, so it incentivizes you to go slowly and carefully. That would normally be fine in a stealth ', 'Died multiple runs in a row because the game just ate jump inputs. Game is janky and made an awful first impression, outside of the great art style.', 'Mixed', 62.22, 42.57, 0.80);
INSERT INTO reviews VALUES (3973, 369290, 156, 'Amazing management game where you take on the role of ATC and make sure the flights don''t crash. Gets intense after sometime. Definitely recommended if you are into flights!!!', 'Im a fan of games like ATC Chaos on the DS. This is not a full ATC experience. All you are doing is approving pushback, cross runway and take off. That''s it! Arrivals are automatic! I would pay maybe $2 for this. Not worth $10!', 'Mostly Positive', 76.92, 3.28, 0.62);
INSERT INTO reviews VALUES (3976, 369420, 263, 'Pretty exciting game all in all!\nA creepy, dark story that sort of worked out in the end.\n\nP.S. This game is not a sequel to the first 9 clues.', 'Meh - long and boring, Poor entry in the Artifex catalog', 'Very Positive', 85.93, 5.12, 4.83);
INSERT INTO reviews VALUES (3977, 369440, 376, 'decided to redownload this game as it was one of the only soulslikes i deleted because it just felt so janky at the time i played it but this was coming after playing remnant 1-2 as well as fromsoft games, so of course it was gonna feel reallly bad. i came back to it for the summer sale and grabbed it again and this time around, i actually enjoyed it. the vibe of the game is really dope, the exploration is fun and the game becomes a lot easier once you know how to level up your guns and stats pr', 'The artstyle is so good, but the movements and combat are clunky and the mob placement are just there to screw you over.', 'Mixed', 64.89, 10.97, 8.98);
INSERT INTO reviews VALUES (3979, 369530, 556, 'This game is Amazing. As it is, its a bunch of 4X systems mashed together with a mount and blade over world style of map movement. Main difference is that time does not stop when not on the overworld, allowing for fleets to reinforce you or your enemy (my favorite feature BTW). \r\n\r\nIt has many rough edges and could do with a lot of polish but its like 4 years old now so that''s not happening. Which is a shame, this game has the potential to be something truly special and i think would have been m', 'I have an RTX 4090 and performance was AWFUL. it turns out the game engine doesn''t recognize it as a GPU lol.', 'Very Positive', 80.76, 45.27, 0.25);
INSERT INTO reviews VALUES (3985, 369830, 170, 'Finished it few days ago. It was in my backlog for around 20 years since as a kid I saw a review or just advertisement in some gaming press (don''t remember exactly what I saw). FMV, real actor in toon world, Christopher Lloyd, everything made a big impression on me. Finally, as a new year resolve, I recollected old memories and started to play games I wanted to try as a kid.\n\nI was afraid if it would turn out be mediocre at best, but in fact, it''s the opposite: I''ve got everything I expected for', 'bizzarrro', 'Overwhelmingly Positive', 95.88, 9.30, 0.18);
INSERT INTO reviews VALUES (3989, 370020, 763, 'Don''t let outdated graphics fools you, this one is solid turn-based tactics with good RPG-part. Yes, it is illegitimate child of WH40k and CBT (far more features of former), and this is awesome. Often such a games has a weak point in the form of absence of plot - this is not a case. Well, this is neither Azimov nor Heinlein, but solid if generic space opera to glue missions together.\r\nWell, what''s about gameplay? This is awesome part. Very different classes, every of which can be customized  and', 'There''s no UI scaling. Unplayable in modern screen sizes.', 'Very Positive', 94.36, 31.12, 0.47);
INSERT INTO reviews VALUES (3992, 370060, 409, 'Finished this game in 3 days. It is a great game!', 'I want to like this game. It has some fun mechanics and there are portions of the game that have progression that feels good, but I''ve hit the 4hr mark and the last two hours have been forcing myself to see if something good is coming. The UI is buggy and limited, a lot of the progression is really shallow, and though it does a commendable job at trying to include some of the more overlooked aspects of running a shop, the management aspects are so clunky and crude that you end up trading one mic', 'Very Positive', 84.84, 109.70, 4.15);
INSERT INTO reviews VALUES (4004, 370240, 1803, 'Better than any of the new ones at least', 'WE BACK FOR MORE REVIEWS FUCK YOU 2YEARS NO SERVICE LOOKING ASS, Bitchass rONIE 2K LOOKING ASS. Fuck you                    \n - Tharshigan Kumarakulasingam', 'Mixed', 50.03, 511.33, 242.47);
INSERT INTO reviews VALUES (4006, 370280, 150, 'Calm clicking to 100%', 'i like some visual novels but this one just isnt it. the voice of the main caracter is annoying AF, there is this weird creepy clown music in the background and every 20-40 sentences the chapter ends and you have to click the next one which totaly breaks the immersion... alas i would love to recommend but there are too many design flaws which makes it so i have to force myself to read every sentence. that being said, I only read the prologue and chapter 1 and 2... story wise it could be worth so', 'Very Positive', 94.00, 1.50, 0.12);
INSERT INTO reviews VALUES (4011, 370360, 2411, '"I''m something of a programmer myself"\r\n-me after making the most spaghetti ass incomprehensibly slow program known to mankind', 'AWFUL game! I don''t understand how this could possibly have Overwhelmingly Positive!\nWho is this game for? It doesn''t teach you anything. It just tests you. If you already know how to program, this is probably a bore. And if you do, you''re just gonna be confused. Terrible, terrible, terrible.', 'Overwhelmingly Positive', 97.64, 16.73, 5.37);
INSERT INTO reviews VALUES (4013, 370460, 156, 'It''s great! My brother bought it for my birthday um 2 or 3 years ago? I couldn''t find the mind to play it with the arcade stick he also bought me same birthday, until now! And I''m impressed with how much fun I''m having, I''m not much of a fighting game know it all, more like the opposite, so I don''t know what all the extra super abilities are or much about guarding. It looks like I''ll have to learn from the online copy of the ps2 original AH1 Manual, it''s in english. The 3rd one doesn''t seem to h', 'This is a short version of the game.\nThe full version is "Arcana Heart 3 LOVEMAX SIXSTARS!!!!!! XTEND"', 'Very Positive', 82.69, 9.78, 0.12);
INSERT INTO reviews VALUES (4015, 370510, 353, '\r\nRoll the ball. Actually not a bad game... Expect something a bit different then you might think at first glance. Controls are mouse based so gameplay is very tricky. Each stage will have different angle limitations which allow for shorter or more extended movement. Ball is very fragile so mind the heights as well excessive speed. Good and simple arcade game that again is not bad. Music and sounds are ok. Not too long and simple but still enjoyable.\r\n', 'Not good enough to be worth the challenge\n\nThe game is artificially difficult, requiring extreme precision at times. Poor controls and weird physics don''t help. Skip this one.', 'Mixed', 58.36, 4.08, 4.38);
INSERT INTO reviews VALUES (4016, 370540, 274, 'I find this game enjoyable overall.  The winter months as german can be a bit of a chore, but it''s a great game.', 'if you have time to lose for thousand useless click to just see the result of your move and then wait 5mn in small scenario up to an hour to let poor ai compute ,then buy the game.\n\nit''s just too much useless information and really boring game.\nlook like i''m back in late 80''s \nlove strategy games but pass on this one.\nbuy heart of iron or panzer corps ,those are really enjoyable and rewarding', 'Very Positive', 90.88, 869.63, 4.32);
INSERT INTO reviews VALUES (4033, 370870, 204, 'Had it on my wishlist for a while and regret not getting it sooner. Car go boom.', 'Sorry, but I tried really hard to like this game.  The whole thing seems unfinished.  For me it had a tendency to crash at the very end of missions.  Some of the animations don''t seem to run correctly, and I''ve even seen textures that look misaligned.\nI can''t help but feel that there is actually a really good game buried in here, but it just needed another 6 months of development before release.\nThere are some good elements to the game, it''s definitely not terrible.  But I can''t recommend it in ', 'Mixed', 69.61, 11.05, 28.93);
INSERT INTO reviews VALUES (4034, 370910, 1181, 'i thought this was a game with lots of items combining and banging your head against the wall until something finally works but its really chill and straight forward', 'I liked the game at the start, until it became all about supernatural things that never really get explained. Also, the gameplay becomes tedious and puzzles feel far-fetched. I can''t imagine playing this without a guide. But even with a guide, I can''t recommend the game as a whole. Too weird, and not in a good way.\r\n\r\n', 'Very Positive', 92.55, 8.25, 5.75);
INSERT INTO reviews VALUES (4039, 371010, 152, 'I love the game, but the way you control the space navigation is annoying AF. Also that got worse bc suddenly my horizontal axis were glitched and everything went wrong so it was me fighting with the controllers and leaving my enemies alone lmao', 'Carefull - Still "Early Access" in terms of obvious UI bugs and ship controlling. (Like the ''Resume'' button not working in the pause menu - ONE of THREE buttons. And Quit is just closing without confirmation). I got 13 issues ... THIRTEEN .. ISSUES / BUGS .. in the first 5 game minutes (like the tutorial not continueing after I am suppose to press ''H'', if a havester got allready commanded by right clicking). And did you ever hold SHIFT and then right-cliked/pressed M? Opened research and jump ov', 'Mixed', 68.42, 4.33, 0.78);
INSERT INTO reviews VALUES (4042, 371180, 449, 'I can feel Jesus inside of me', 'Bad enough to turn you into an atheist. Or if you are an atheist, you''ll pray to any God that will release you from this pain.\n\nIt''s like Wolf 3D but\n\nall the weapons suck except the machine gun feeder\nall of the regular enemies are hit scanners\nevery level looks exactly the same\nthe bosses are the easiest enemies because they''re the only ones that don''t hit scan\nenemies shooting you around corners\nenemies shooting you through closed doors\nenemies shooting you through solid fucking walls\nenemies', 'Very Positive', 92.43, 0.15, 6.73);
INSERT INTO reviews VALUES (4043, 371190, 110, 'yea this game''s nice\r\n\r\nwhat I especially like is how non-recruited people do have a purpose unlike soi4 - here, I can press gang literally the entire population of my minor country into the cities only to realize that I need to import all my food from china and nobody is available to operate the artillery', 'I highly do NOT recommend this game. If you wish to play as one of the major powers AND simply conduct battles for the various territories/zones (similar to Risk or Axis & Allies) then you MAY get some fun out of this. However, playing as any other nation OR playing a non-aggresive strategy as a major power is a waste of time. My major problems are as follows:\n1) Agriculture/Food:  I played games as Spain, Canada, Australia to see how it may be possible to become a major exporter of food to alli', 'Very Positive', 84.55, 125.98, 43.27);
INSERT INTO reviews VALUES (4044, 371200, 867, 'I bought this game Friday. I played 23 hours. I just finished it. It''s Tuesday.\n\nI didn''t play it on the easiest setting, nor was it the most difficult. \n\nBut considering in the last 4.5 days, an almost 10 year old game had me completely engaged for 23 hours.... I''d definitely say it was worth the $16 or whatever I paid for it.', 'Older version of the game which is more grindy, apparently? I thought the grind was the worst part of the "Lightspeed Edition." I think I got these together as a bundle. Lightspeed is fun (if grindy) this one must be unplayably slow.', 'Mostly Positive', 79.70, 23.22, 2.15);
INSERT INTO reviews VALUES (4058, 371450, 121, 'Awe\n\nHas a total of 6 trading cards.', '\r\nThis game is waste of time.\r\n', 'Mixed', 69.42, 1.08, 3.92);
INSERT INTO reviews VALUES (4061, 371520, 538, 'Just found this game recently and I''m very impressed, especially since it only cost 99 cents!  I would call it Port Royale meets Railroad Tycoon.  It certainly doesn''t have the depth of those two games but it does have a lot of good elements from both and a campaign that walks you through how to get started.  It still took me like 10 restarts to get everything working correctly, though, particularly since it overwrites the autosave every time you enter a city; if you screwed something up and did', 'It had potential to be a good game but there are freeze (PC/Win10) issues that have been left unresolved from 2018.\nGame freezes after 12h of game play. No one bothers to comment on the thread. \nPractically abbandonware.\nI hope it changes. Otherwise, do not bother buying this dead piece of software.\n', 'Mixed', 69.33, 29.82, 35.25);
INSERT INTO reviews VALUES (4063, 371550, 148, 'Very hard game\nIt has a fun and complex combat system\nThe NPC''s look very nice\nVery nice music\nNice artstyle\n10/10', 'This game will not run at all.\nLiterally getting the same error over AND OVER:\n"Det gick inte att skapa processen <C:\\Users\\me\\AppData\\Local\\Temp\\IXP000.TMP\\a_bastards_tale.exe>.\nAnledning: INDOWS\\system32\\advpack.dll"\n\nI''ve tried all the solutions, and I can''t even start the damn game. 0/10', 'Very Positive', 81.08, 4.42, 0.17);
INSERT INTO reviews VALUES (4064, 371570, 192, '49/50 achievements - roughly 190hr.\n50/50 achievements - roughly 315hr.', 'Pretty bland experience even for a tap idle game. No variety to anything and many balancing issues. mage doesn''t even attack just heals? weird. You will easily max out some achievements while some take forever to complete. I just know this will be a slog to get the achievements in this game. yawn.', 'Mixed', 61.98, 319.37, 243.80);
INSERT INTO reviews VALUES (4067, 371660, 11810, 'Hands down I think this is the best Far Cry game Ubisoft has ever released. I have played 3, Blood Dragon, 4, some of 5, a little bit of 6 and Primal and there''s something incredibly fascinating about this setting.\n\nCompared to the other Far Cry games I''ve played, I actually feel vulnerable in this game - but cave bears, sabertooth tigers, cave lions, wolves and other predators waiting to ambush you at night.\n\nI also LOVE that there are no guns and no cars. All you have is a club, a bow, a spear', 'I actually love this game but because of Ubisoft and their stupid always online BS with Ubisoft Connect if Ubisoft Connect is down then you can''t play this single player game with no online components. They even disabled the "Play Offline" options in UC. Utter garbage. I regret giving Ubisoft money for this, no one should encourage their insane, corporate brain rot behavior.', 'Very Positive', 85.40, 70.45, 28.90);
INSERT INTO reviews VALUES (4068, 371670, 245, 'What a hidden gem of an indie game! What a beautiful game! If you are an oldschool gamer and up to some challenging platforming, look no further!  You gonna love this.\n\nThere is something about the Cry Engine games, they just look so good when someone knows how to develop with it. It''s incredible how a game from 2015 manages to look better than so many UE5 games made in 2023, 2024.  The lighting is amazing, the water is  amazing (better looking than in modern games), the color palette, the textu', 'Tech demo with terrible gameplay, buggy mechanics and repetitive music', 'Mostly Negative', 37.96, 1.77, 1.57);
INSERT INTO reviews VALUES (4077, 371970, 6090, 'its like elden ring if it was a completely different game', 'I actually really like this game, but when I quit it told me to give it a salty review - and who am I to contradict a loading menu tip?\nTastes nice on chips, liberally add to pasta water and ensure a rolling boil before adding the dry pasta.\nThis has been my salty review.', 'Very Positive', 92.64, 52.90, 2.42);
INSERT INTO reviews VALUES (4083, 372210, 219, 'A simple little cat platformer with a cute art style. The stages are fairly easy and the game is short, but it does give off a creepy vibe in the sound department. It''s a nice little experience for the price.', 'There''s just nothing fun about this, it''s boring and repetitive sold purely on the basis that it has cats in it and they are cute.', 'Very Positive', 87.67, 2.08, 7.33);
INSERT INTO reviews VALUES (4088, 372350, 109, 'Saw this posted years ago on plebbit (garbage website now, stay the F away) and added the game to my wishlist. Years later I finally bought it. Super fun literal rail shooter. A little confusing at first but easily figured out. Why are you reading my review still? Buy it already ya putz.', 'Looks like it could be a fun game but I played a few levels and got some pretty bad motion sickness.', 'Very Positive', 89.91, 2.20, 0.27);
INSERT INTO reviews VALUES (4089, 372360, 2698, 'Does 30 fps suck?\nYes, of course it does.\n\nDoes this game suck?\nNo, of course it doesn''t.\n\nEdit: it runs at 60 using Lossless Scaling. It''s glorious.', 'This game does not work. The comments section if full of people like me who load the game and have a black screen. No one has any answers on the forums, besides some third-party software that might fix the issue. Check the forums yourself before you waste your money on a product that isn''t supported, or even works.', 'Very Positive', 84.84, 42.50, 0.68);
INSERT INTO reviews VALUES (4091, 372390, 209, 'I love this software. While I haven''t used any other game recording software with which to compare it, I know that it is good because even a goober-noob-face like myself can go from zero to recording all of my gameplay in no time at all. The controls and settings are intuitive and it captures video flawlessly. I have never used the streaming, so I can''t attest to its functionality. The fact that I am even writing a review is a testament to how much I like it, as I am typically too lazy and shy t', 'I WANT MY MONEY BACK, this is not a game I played, its software that doesnt work, It sat in the background while I tried to figure it out. After two attempts I conclude, piece of junk I WANT MY MONEY BACK..... Oh, and yes; DONT BUY. I hate wasting money, if I dont get a refund I will use every means possibel on and off Steam to ensure nobody else gets suckered by this shit.', 'Mostly Positive', 77.03, 816.55, 4.07);
INSERT INTO reviews VALUES (4100, 372690, 136, 'Very fun game with built in workshop and level editor support :thumbs:    - I swapped the default note keys out from 1 2 3 4 5 to Z X C V B. \n\nOh and also awesome music :D', 'Coming from a background of community-driven rhythm game engines, this 5-key rhythm game does not offer much different to community-driven equivalents asides the exclusive chiptune & pixel-art aesthetic. The content and technical competency is good, just nothing to get excited about.', 'Very Positive', 82.35, 3.48, 8.57);
INSERT INTO reviews VALUES (4110, 372930, 116, 'This is actually a pretty great HOG puzzle adventure game. It''s a modern HOG, meaning that there are no classic HOG scenes where you just find objects; instead, you solve small puzzles on every HOG scene. It also has collectibles and extra stuff to find in every area. Very decent playtime too, almost 9 hours! When I read it had to do with the mafia, I thought I might not get into it, since it''s a topic I''m not particularly fond of; however, the story barely touches upon that, and instead focuses', 'The game would be fun if it wasn''t glitchy as %$%.  It crashes every so often for no apparent reason but I was still enjoying the play-through, despite this, until I ran into a game-breaking bug and couldn''t continue.  After reading some of the discussions and researching online, I realized mine was just one of several game-breaking bugs and it doesn''t appear the developers have any intention of fixing them.', 'Very Positive', 90.52, 8.63, 18.72);
INSERT INTO reviews VALUES (4111, 372940, 123, 'I enjoyed playing this game. The story was nice and well thought out. \n\nPros:\n + Gameplay.\n + Graphics.\n + Music and sound effects.', 'great game BUT(and it is a big BUT) my partner thinks i have purchase the testgame.Before the game starts i get a advertisement fore other games from the same creator,  and in the middle of the game i have got the question(pop up,inbetween levels ) if i like the game.I have to rate it.And this for a collectors item.\nSo,even the fact that i like the game,i have to review it negativly(sorry for my english)', 'Very Positive', 94.31, 38.03, 10.12);
INSERT INTO reviews VALUES (4119, 373180, 1300, 'Honestly I barely touched the game, I just bought it in honor to the cinematografical masterpiece Kung Fury is.', 'Hackerman plays like buttcheeks in the story mode.', 'Very Positive', 89.38, 1.57, 5.20);
INSERT INTO reviews VALUES (4120, 373240, 107, 'Only recommended on heavy sail or better on kinguin or whatever. Don''t pay more than 1 or 2 bucks. Don''t get me wrong, it''s a nice short puzzler or to be precise a point and click adventure with good atmosphere and sound, but never expect a mind bending diamond of the genre. For example two annoying searches for quest related items (lockpicking tool and the route map) broke me a bit, because I needed help from the internet- ingame help function is displayed to short and not everything is shown a', 'wow, this is really bad', 'Mixed', 60.75, 8.72, 1.00);
INSERT INTO reviews VALUES (4124, 373390, 2411, 'GOD WE NEED THIS BACK PLEASE GIVE US THE SEQUEL honestly the best and most underrated game', 'Played for about an hour and enjoying the game. I''m engrossed, having a lovely time when it crashes. I reboot and and have to start the entire thing over. Now I have to watch an hour''s worth of unskippable videos just to get back to where I left off.\n\nThis could be prevented by any one of the following.\n1. An autosave feature\n2. Allowing the player to skip videos\n3. Properly debugging the game so it doesn''t crash abruptly', 'Overwhelmingly Positive', 95.11, 7.13, 6.25);
INSERT INTO reviews VALUES (4125, 373420, 10428, 'I feel like this game is very underrated when compared to Original Sin 2 and Baldur''s Gate 3. Those games are great, but the first Divinity: Original Sin still holds up as well. I heavily recommend playing this game co-op with a dedicated partner, as it has more co-op mechanics than Larian''s other titles have, such as mechanics for making decisions as a group (which can get a little awkward when you play singleplayer, because you can end up arguing with yourself), and the fact that you always cr', 'This game is amazing. The story is fantastic. The gameplay is fun, BUT I would never recommend this game. The game design in Act 2 and prior to the conclusion is so BAD and so BROKEN that it genuinely sucks the soul out of you. I''m convinced 90% of these reviewers have forgotten what it''s like to play this game for the first time not knowing where to go. \r\n\r\nAct 2 is lvl based areas in a full circle and it does not do a great job of guiding you in the right direction. I managed to get halfway th', 'Very Positive', 87.04, 202.00, 65.43);
INSERT INTO reviews VALUES (4138, 373750, 175, 'Me eat shroom. Brown good. Blue bad—BIG BLEH! Drink water—BAD BLEH! Sleep tree. Belly angry all night.\nDay two: Pick bush snack. Go water. Uh-oh! Big tooth Tyranno drink all water! Name him Punk Face. Run for puddle. Trike horn yell, ‘MOVE!’. Me find new water. Day three, new water. No find. Day four, fire stick? No fire. Day five, sneaky Trodoons come. Me maybe die. But spear sharp!', 'Can I get my money back for this, because it was absolutely disgraceful. The only thing i liked about this game was the lightning. You can get an amazing game, like PRIMAL CARNAGE for the same amount of money. It would vitaly improve the game if you could add more dinosaurs. Thanks.', 'Very Positive', 93.14, 6.58, 0.65);
INSERT INTO reviews VALUES (4139, 373770, 1854, 'cutie patootie', '\r\nSuper mini RPG with vampires I guess. Lots of dialogs, lots of mystery. Not always obvious where to go next. This is a trilogy so it might take some hours to complete. For me it lack spine to be interesting enough. I don''t know play it if you like RPG with vampires and lots of pixels - I''ll give it a pass.\r\n', 'Overwhelmingly Positive', 96.98, 5.02, 4.33);
INSERT INTO reviews VALUES (4145, 373920, 183, 'it can be off at times, but essentially, for the price it was listed at (20$, bought for 5$) this is a good experience for the price point', 'I love 40k, but it pains me to see constantly a lot of bad games from the license from devs that clearly don''t quite know what they are doing.\n\nA lot of the voice acting is really sub par and distracting which is bad for such a  story focused game, and when it isn''t is giving you moments of cheap and hard to dodge hazards, terrible animations, and combat that comes down to spamming left click when you have a single enemy to deal with because you stunlock them, or alternitively the rest of the en', 'Mixed', 53.55, 1.57, 0.53);
INSERT INTO reviews VALUES (4146, 373930, 1508, 'I absolutely love this game and this entire series. My only issue with the game is that I have already played all of the scenarios and need more!', 'The original sudden strike games were iconic.  You controlled thousands of units in epic massive battles that were realistic.  In this one you basically control a small squad, and your infantry will heal back to full health no matter that they just took 5 tank shells to the head.', 'Mostly Positive', 79.24, 330.72, 57.53);
INSERT INTO reviews VALUES (4147, 373970, 263, 'As others have said, this is very similar to Bookworm Adventures. Simple but still a lot of fun, especially when enemies start throwing various effects at you later on.\n\nEDIT: That said, it *reaaaaally* needs a better dictionary.', 'I''m eternally aggravated that they didn''t bother adding a decent dictionary. \n\nThe available plays and the available English words do not overlap. I understand if you make a family friendly game you don''t want profanity, but if I manage to spell "deoxygenated" I want some goddamn credit for it.', 'Very Positive', 93.54, 13.57, 4.50);
INSERT INTO reviews VALUES (4150, 374030, 1163, 'Virginia is a good narrative game where you play as a FBI agent and have to investigate on a missing person case and your partner. The designs are beautiful and the soundtrack is just amazing. the game could have been perfect if the characters could talk. The story is so interesting that I couldn''t stop playing until I knew the ending. I highly recommend it!!! 🪶❤️', 'do.not.buy.this.\n\nI never leave bad reviews but this was a complete waste of time. I LOVE these types of games. And despite the mixed reviews I figured I would give it a shot. Even lack of gameplay doesn''t bother me, what bothers me is when the story is INCOMPLETE. The supposed main case is never solved, there''s not a proper ending, everything makes zero sense. And I even LIKE trippy dream movies, but the plot itself is not good. It would be a lot better if there was some sort of dialogue. I don', 'Mixed', 60.45, 10.38, 1.63);
INSERT INTO reviews VALUES (4151, 374040, 4679, 'This is one of the few PC games which are split-screen co-op. It''s great for kids and non-gamers. This game was the perfect fit for a couch gaming session for me and my wife. We played and beat it and we enjoyed every moment.', 'This game has small boring maps with nothing to do on them.', 'Very Positive', 83.59, 60.52, 0.30);
INSERT INTO reviews VALUES (4152, 374060, 156, 'This is a horror-themed Walking Sim.  It''s psychological, immersive, dark, and suspenseful.  There are a few minor attempts at jump-scares, but they probably won''t frighten anybody over the age of ten, so I don''t think it classifies as a true horror game.  There is only one section, in the mines, where "monsters" will chase you, but they don''t see too well in the dark, and thus are actually quite easy to avoid.\n\nIn this game, you are playing as journalist Christopher Adams.  Starting out, you go', 'Stairs could of been better if they added on check points when you reach certain part of the mine maze, made it controller friendly, and not try to make it all dark all the time no matter how much you turned the gamma up.', 'Mixed', 62.82, 7.98, 5.93);
INSERT INTO reviews VALUES (4157, 374190, 965, 'Playing Infernax was the most fun I''ve ever had playing a metroidvania (one of my favourite genres).  It is a Zelda-like Metroidvania with a relatively short campaign, but unbelievable replayability.  There is a moral system with multiple different endings, access to different spells and alternate characters you can play as that give the game a completely different feel.  They have also added local co-op (and the option to play 2 characters solo).  There are several unlockable cheats, may of whi', 'Way too hard to be fun', 'Very Positive', 93.78, 32.00, 4.35);
INSERT INTO reviews VALUES (4159, 374280, 479, 'İİ', 'You know it''s bad when CS:GO''s bots are more realistic than the low-budget spinbots in this game.  \n\nCraziest thing is that AbsolutSoft could gain a lot of money from across the world if they put more effort into actually balancing the game around being fun to play instead of creating artificial win/loss scenarios based on skewed detection range, accuracy, and reaction time of their bots.  They could add a server browser just like Contract Wars instead of a blind playlist queue that inevitably t', 'Mixed', 59.50, 338.58, 64.37);
INSERT INTO reviews VALUES (4160, 374320, 101177, 'I play it often, always choose knight, level up the Longsword to 1 or 2, run some drills around the castle.  Very re-playable for an autist like me,\n\nDo NOT offer a pale tongue to Rosaria until you get the Silvercat Ring.', 'Love the game but how the FUCK are you gonna ask 60 Euros for a 9 year old game? And thats not even including the dlc which is another 25 euros, crazy stuff. Buy elden ring or the other games instead at this price lol.', 'Very Positive', 94.01, 1046.47, 638.30);
INSERT INTO reviews VALUES (4162, 374400, 109, '<3', 'The voice recognition is ok but this could also be a problem with my speaking ability or my hardware. The software in general is very handy and works well but I do not see any benefit currently. In all the games that I played the voice commands were so slow compared to just pushing the buttons. It''s kind of cool to controll a game with your voice or do stuff on keyboard and do paralell stuff with voice but in generell doing everything with the keyboard is faster and better in action passed games', 'Mostly Positive', 75.23, 3.57, 0.18);
INSERT INTO reviews VALUES (4175, 374900, 829, '6/10. The controls are abysmal, riddled with bugs at every turn. The few mechanical puzzles are both annoying and utterly unnecessary. Honestly, the only thing that kept me slogging through this mess was my love for Agatha Christie.', 'This game is a wonder in making you feel you''re way above average intellect. \r\nThe observation skills of Poirot are those of a 10-year old kid, to the point you''re going to be surprised on how obvious the things you should be observing were. \r\nThe "little grey cells" moments are just amazing in a bad way: the conclusions are so mind-bogglingly obvious you probably got them way before Poirot even tries to think about them. You''d think the best detective in the world probably noticed something you', 'Mostly Positive', 77.93, 7.80, 5.45);
INSERT INTO reviews VALUES (4185, 375120, 187, 'You don''t have to make "much better games" (as mentioned in the end credits). This shmup is on point, great graphics and unique puzzle twist. Hard, but doable stages - even for a moderate skill level.\r\nDevs on my radar now!', 'Auto fire only during boss fights is just heinous. The levels are randomly generated, and I''ve had several cases where its impossible to clear the path and advance (not just in instances where you need a certain gimmick to clear objects). Could have been a solid little shmup with a twist except for these issues. Also very short.', 'Mostly Positive', 79.14, 12.62, 4.10);
INSERT INTO reviews VALUES (4186, 375130, 265, 'This is one of the greatest Choose your Own Adventure stories I''ve played from Choice of Games. There is almost no way of playing the same game twice if you are not actively thinking about which choice is which for this one. It''s fun, and the story and characters are very well thought out. I love reading this one!!', 'This game prides itself on having no graphics or sound, only text, so one would imagine that the text would be very well written.\nAs someone who reads at least one book a week, I feel qualified to judge the quality of writing within a few minutes, and I treated this game as I would treat a book, so 12 minutes in the game was enough for me to know that the writing is mediocre at best.\nThe premise is also ridiculous. You get some choice in who your character is, but it feels like the game is pushi', 'Overwhelmingly Positive', 95.47, 6.37, 0.20);
INSERT INTO reviews VALUES (4188, 375180, 158, 'Started with a shag van ended up with a pedo van 10/10', 'Lunch Truck Tycoon takes place on a dystopian, late-capitalist island known as Lunch Island; a horrible place where the same 20 second song is played over loudspeakers on loop at all locations. The days pass by in a rushed blur, yet it is always lunch time on Lunch Island. Strictly segregated by socioeconomic class, the island population is comprised of hunderds of silent and exhausted clones stemming from the same 5 or 6 white people and one brown man in a gray suit, creating an uncomfortable a', 'Mixed', 61.39, 0.52, 4.23);
INSERT INTO reviews VALUES (4190, 375200, 435, 'WINGED CLOUD\n\nRELEASE CHAPTER 2 AND MY SOUL IS YOURS', 'This game basically sets that stage for the second part (to be released next month), so you don''t get any major story payoffs here, sadly.  The story isn''t horrible for what it is... my biggest complaint, honestly, is that the writing can be so cheesey at parts- like how they constantly mention how so-and-so turned around, making her boobs jiggle slightly, and it comes across as awkward.  Also, I found that the choices I made didn''t tend to make much of a difference.  You might make one decision', 'Very Positive', 89.66, 10.68, 3.62);
INSERT INTO reviews VALUES (4193, 375250, 135, '100% fox''s friend yapping too much\n100% pricy pizza\n100% worth it, got it on -87% discount\n100% got scammed from the supplier', 'It would have been fine if all you had to do was make pizza, earn money, and be able to use new toppings.\nIn reality, it seems that a variety of factors influence the game, such as the choices you make in the story, the time of day you open your shop, and the amount of money you earn.\nOn my first playthrough, I didn''t get to increase the number of dough types, and I finished before I''d used many of the toppings.\nWhat bothers me most so far is how slowly ingredients are replenished when they run ', 'Very Positive', 91.11, 3.30, 2.55);
INSERT INTO reviews VALUES (4201, 375440, 256, 'Essentially, it''s a Western RPG Persona. Who wouldn''t love that. Sweet and charming, just enough of a throwback to old role-playing games (especially Quest for Glory) without drowning in nostalgia. On my fourth playthrough on two platforms, and I really do hope they make that sequel.', 'I''ve never played quest for glory but played the demo and really enjoyed it. Found it fun. So bought this game but then got to experience past the demo and hated how restrictive everything felt. The time limit to do things is so severe I hated it and it ruined my feeling of enjoyment. I felt frustrated and annoyed I could barely do anything.  I can''t recommend this game so I requested and got a refund. As it''s not a game I can happily keep playing. Also it seems like trying the demo got rid of a', 'Very Positive', 90.23, 87.20, 0.77);
INSERT INTO reviews VALUES (4202, 375460, 237, 'BEST AFK GAME', '16bit Trader offers an old-school trading simulation, but it quickly becomes repetitive and lacks depth. The concept of buying low and selling high across different towns sounds engaging, but the gameplay feels monotonous with minimal strategy involved. The quests are simplistic, and the progression is slow, which makes it hard to stay invested. The 16-bit graphics might charm fans of retro aesthetics, but the overall experience feels shallow. I wouldn’t recommend it unless you’re looking for a ', 'Mostly Negative', 32.07, 749.70, 75.23);
INSERT INTO reviews VALUES (4203, 375480, 3214, 'Imagine a pixelized Diablo 2 with better movement mechanics and you have arrived at Chronicon. The flow of the game is nice, with even some obvious takeaways from the golden classic D2. The class customization is wonderfully done, the only weird curve ball for me at the beginning was building the items from Left to Right as opposed to the normal Top to Bottom approach for skill customization. A few nuances, such as changing settings for LT and the toggle button for loot names on the ground as we', 'Absolutely hate the UI and how zoomed in the game feels like. It is like it was made in the 2000s without modern screens in mind.', 'Very Positive', 94.77, 34.65, 2.68);
INSERT INTO reviews VALUES (4205, 375510, 424, 'lgbtqia+  word', '9 years in early access is self explanatory.', 'Mixed', 43.40, 4.53, 2.53);
INSERT INTO reviews VALUES (4210, 375600, 292, 'Such a great game when you can find people to play with. So happy to see new people trying it out during this sale!', 'fun game great concept, not worth 10$ by a long shot right now, theres 4 maps and 5 planes, no single player anything aside from the tutorial, just a sheer lack of content.\n\nThe few games I''ve played have been scarily one sided, and once one team gets ahead it seems they just camp the spawning points and stomp the other team, not fun for either side really. \n\nAt the moment I''m massively dissapointed in this game. Here''s to hoping that as it''s early access progresses it will get better.', 'Mostly Positive', 75.00, 21.70, 0.27);
INSERT INTO reviews VALUES (4213, 375750, 241, 'This ranks among my top games of all-time, from concept to execution to enjoyability, and I don''t see it falling from that spot anytime soon. Every part of it so clearly demonstrates the sheer passion the developer put into this game, including the incredible pixel art, the well-balanced levels (most of them, at least), the quips characters make after each round, the fact that crossplay between PC, mobile, and Switch is seamless (and that there''s crossplay at all!), the emergent complexity for e', 'I''m sure it''s a fun game, but they had pretty much no pr or hype before totalbiscuit made a video on it. For a game relying this much on multiplayer the matchmaking is awful due to a overcomplicated custom host system.\n\nIt''s pretty much impossible to play the game online. (with strangers)\n\nEDIT:\nPS\nIf you have 4 friends to play with then the shit multiplayer system obviously doesen''t matter to you. But not having a queue system still lowers the value of the game. A functional multiplayer queue w', 'Very Positive', 90.87, 22.72, 0.18);
INSERT INTO reviews VALUES (4217, 375820, 1373, '01110100 01101000 01101001 01110011 00100000 01100111 01100001 01101101 01100101 00100000 01101001 01110011 00100000 01110000 01100101 01110010 01100110 01100101 01100011 01110100 01101100 01111001 00100000 01101111 01110000 01110100 01101001 01101101 01101001 01111010 01100101 01100100 00100000 01100110 01101111 01110010 00100000 01101000 01110101 01101101 01100001 01101110 01110011 00100000 01110111 01101000 01101001 01100011 01101000 00100000 01101101 01100001 01101011 01100101 01110011 00100', 'i get about 3 fps on levels with rain in the window,  making it unplayable, and I cannot find a solution.', 'Very Positive', 93.01, 5.28, 1.10);
INSERT INTO reviews VALUES (4218, 375840, 191, 'If you want a basic entry for music production, and you don''t need any fancy bells and whistles, this is a decent platform to get started with. If you want something a bit more advanced, Rytmik Studio is your best shot (needs a beefy computer)', 'The software is okay. It is just too bad that I cannot recommend buying on Steam. Because you cannot buy it on Steam! After all, "This software is licensed, not sold."\nAlso, considering that Audacity is free, well-documented, and dramatically more capable, I don''t see why you would get this.\nAnd does this seriously need 3D graphics support to run? This is a music editor, right? You know the drill folks: PROTON_USE_WINED3D=1\n', 'Very Positive', 84.29, 545.05, 0.10);
INSERT INTO reviews VALUES (4221, 375900, 742, 'This game is one of the best couch coop racing games. It has great couch coop features, 2 to four ppl driving one car, splitscreen and hot seat. It''s rly a couch coop gem!!! Bad reviews are mainly because of the Ubisoft launcher. Pleas keep up the support for this awesome game.', 'ubisoft, remove your stupid malware launcher pls', 'Mixed', 64.56, 6.82, 14.73);
INSERT INTO reviews VALUES (4222, 375910, 2835, 'This was my first Anno game.  I didn''t write a review when I first played through because I didn''t have the perspective of the other entries.  And after reading the reviews, it seems like a big deal.  Here''s the plain and simple.  Anno 1800 was a better game up until you get near the end game, then it becomes your life.  The level at which you have to min/max is incredibly, incredibly in-depth...and for a min/maxer like myself, that seemed liked a good thing.  \r\n\r\nBut it wasn''t for me; however, ', 'Strong no -\n\nthis review is not about the game, it is about the Ubisoft support. Do not buy the game at this time, some of its functionalities are not working and it is blocking you from finishing some quests. The supposrt promised to deal with the issue 2 months ago, but did nothing about it so far. Don''t dump 40 euros in the game that is not working and has no prospect in being playable again. I am writing this review on June 11 2024 - if you are reading this now, don''t even think of buying th', 'Mixed', 69.03, 180.22, 26.52);
INSERT INTO reviews VALUES (4229, 376210, 49081, 'Terrible game. You work for hours to grow a dinosaur. You learn to love this creature, help it live a full life, have children of it''s own, only to watch it starve to death in a poorly placed hole you can''t jump out of. 10/10 will do again.', 'I''ve played 100+ hours of this game, it was fun at first but I''ve determined a few things that turned me away and made me lose interest;\n- Development is INCREDIBLY SLOW, practically a crawl and this game has been in development for 9 YEARS. Legacy was scrapped in favor of Evrima which had things start all over again, it feels like the Devs don''t really know what they want to do.\n- The map is too large with too little players to support it. There are mountains separating you from others and it i', 'Mostly Positive', 79.26, 1375.23, 137.03);
INSERT INTO reviews VALUES (4232, 376300, 1024, 'thank you guilty gear xrd sign for introducing the world the best character that will ever come out of this series. i am eternally grateful for bedman', 'That Guilty Gear series bundle is such a con. Was I wrong to assume this would be the up to date version of Xrd? Well it''s not. You want Guilty Gear Xrd REV 2 which isn''t included.', 'Very Positive', 91.99, 8.48, 3.30);
INSERT INTO reviews VALUES (4238, 376520, 445, 'This is a very good game.\nWitty, funny, with clever puzzles.', 'newgrounds.com at the time had better adventure games and they where all free', 'Very Positive', 89.21, 4.80, 8.03);
INSERT INTO reviews VALUES (4242, 376680, 498, '2024-08-13 , THE ONLINE WORKS ! what is that bullshit YOU SAID . the online WORKING . so buy the game and come play with us', 'No online game , false advertise .', 'Very Positive', 81.33, 3.02, 1.12);
INSERT INTO reviews VALUES (4243, 376730, 443, 'I played Monument around 2 years ago and i hated it but i decided to give it an another go as it sat in my   library and....its actually okay? its a small arena shooter that isn''t too crazy but does the job of killing some time. The game is pretty ugly, the weapons look wierd and the levels look pretty ugly too while their layout is fine. The enemies are fine, their design is nothing special but i think they fit pretty well into the game. Monument has no lore and there''s little to no horror in t', 'An extremely short, rather mediocre old school FPS - took around 45 minutes to finish all 6 levels and find the secrets. You run around a small map collecting keys and killing enemies. The enemies run straight at you, and shoot directly at you. They''re all quite basic. The worst part is the enemies constantly spawning directly in front, behind, or on top of you. The final boss was pretty underwhelming, it''s just a scaled up bullet sponge version of one of the enemies.\n\nIt''s certainly not horribl', 'Mostly Positive', 72.01, 6.78, 5.52);
INSERT INTO reviews VALUES (4249, 376870, 3414, 'I bet if this game and its sequel were still available for purchase, the sales for this would skyrocket after the showing of the Minecraft movie. You know it''s bad when even RTGame feels he has to apologise to this game.\nIt''s really a shame. This game and its sequel really weren''t that bad. I wish more people would appreciate them, now more than ever.', 'horrible game. 0/10. does not compare to upcoming masterpiece "the minecraft movie" starring jason momoa and kung fu panda.', 'Mostly Positive', 72.61, 19.87, 20.57);
INSERT INTO reviews VALUES (4258, 377060, 241, 'Im gonna recommend it only because the potential for this game is there and im hoping with enough interest the developers will continue to work on this game because this game is awesome despite being unfinished. They goy the controller scheme and the whole idea of the game right. With a little but of more work this game is up there with the other sims. Aggressive inline deserves more love.', 'They should give the Lead to another Studio.\nGreat Game but plays like an Pre-Alpha Game - Devs stopped working on that long Time ago.\nDon''t buy unless you''re ok with an Pre-Alpha Game with no Updates for about 19,99$', 'Mixed', 62.24, 0.57, 18.23);
INSERT INTO reviews VALUES (4260, 377080, 342, '"Fight fire with fire, and hallucinogenic Filipino dove powers with hallucinogenic Filipino dove powers!"\nthis game is amazing, you can be a magical girl, children have a tank, you can punch said tank, the king truly is like a frog leg, the seagulls are racist to you, and Anghel is amazing.\n10/10, Nikola Tesla would''ve loved it', 'I wish I could give this a ''recommended'', but I can''t because of the technical issues. There was lag on the text and the screen would often freeze and crash. My computer was easily capable of playing the first game so I''m not sure what went wrong here. I bought this game a long time ago and only played it recently so it''s possible the ''Dove Actually'' version fixes these issues, but I didn''t want to buy the game again.\n\nAs for the content. It is a good showcase of the original characters, but has', 'Overwhelmingly Positive', 95.61, 5.37, 7.52);
INSERT INTO reviews VALUES (4263, 377140, 241, 'Sorry', 'I enjoyed this game a lot so far.\nThe graphics are average, but ok. The balancing (weapons, strength of walls, rescources, Sharks etc.) is very well done and the amount of content is absolutely ok for an early access alpha game that has just been released. On top of that, patches come out very frequently and the devs and admins in the forum seem very friendly and communicative. \n\nBut I''m not going to recommend to purchase this game atm, because it is absolutely overun by hackers. I played a lot ', 'Mixed', 49.38, 13.68, 46.58);
INSERT INTO reviews VALUES (4265, 377160, 165390, 'what if fallout was named freakyout and instead of surviving the wasteland you survived the freakyland', 'the next gen update makes the game simply unplayable (string freezes, frequent crashes). The devs don''t seem to care about it', 'Very Positive', 83.41, 82.72, 178.47);
INSERT INTO reviews VALUES (4276, 377450, 108, 'Pretty good graphics & a good storyline. Most of the puzzles aren''t that complicated to figure out. I recommend this whole series.', 'I like this game. Great hopa.\nI only give it a negative review because they make so much advertisement for their games. Everytime you start the game you get a screen "click here for more games" and even when you finished the game. Yeah I get it.', 'Very Positive', 94.44, 20.40, 4.38);
INSERT INTO reviews VALUES (4277, 377460, 193, 'Space Invaders-type game where you shoot chickens and eggs, with Star Wars and Star Trek reference in it.', 'Chicken invaders 3  although nostalgic is quite a boring game. If you played the first Chicken Invaders you played them all, with very little diversity the game will have you beating the same 10 stages all over again. With a few achievements to get, this game offers little to no goals after beating it for the first time.\n\n5/10 - Nostalgic but over all meh kinda game...', 'Very Positive', 93.78, 9.25, 12.45);
INSERT INTO reviews VALUES (4280, 377530, 574, 'Classic. The best game with all the best elements of traditional Chinese culture. The game is also very fun to play.', 'As of this moment I cannot recommend this.  It has lots of crashing issues, and even some text that isn''t translated. I mean it is a good game, but how are you meant to play a game filled with loading screens when it crashes on loading screens.', 'Very Positive', 84.49, 323.58, 89.42);
INSERT INTO reviews VALUES (4282, 377600, 138, 'Don''t watch a playthrough.\nDon''t read more reviews.\nPlay it.\n', 'I really want to like this game, but it doesn''t launch on Steam Deck and it doesn''t display properly (all stretched out) on my monitors - with no settings anywhere to even pop into a properly-sized windowed mode. I''m outta luck, but you may fare better.\n\nThe game itself seems fun. The music''s great! Love the pixel art. It feels like a fun zany NES title.', 'Very Positive', 89.13, 4.65, 0.20);
INSERT INTO reviews VALUES (4284, 377670, 283, 'I got all 7 endings and did all 4 routes and it was amazing. The steam description really doesn''t do it justice, on one hand it''s a emotional roller coaster of a mystery-thriller novel following a series of crime and on the other hand it''s a light hearted slice-of-life novel. It starts off slow but picks up when you meet Gonzou. The characters are good, the plot always has you guessing and just gradually understanding the main character was enjoyable. \n\n Spoilers \n I liked the reveal of Kyouhei ', '"The devil on G-string" is NOT the same as "the devil in a G-string" do not misread it. i was expecting a totally different game', 'Very Positive', 91.87, 83.92, 0.18);
INSERT INTO reviews VALUES (4285, 377680, 637, 'It''s Alright', 'This game changed my life.', 'Very Positive', 83.99, 732.65, 2.45);
INSERT INTO reviews VALUES (4286, 377690, 171, 'Excellent game, Aria x Melody  <3\nI got some really strong Tenchi Muyo vibes (Lyria reminds me of Ryoko, actually even read her scenes with her voice in mind). Great game, worth full price and I''m glad it goes beyond the innocent love phase', 'PROS: - good story that is full of content. took me forever across two days to finish.  - choices have actual effect from what ive seen. - this game also has good drawing and some beautiful scenes.                       CONS: - story is sort of basic, with heavy focus on the dangum romance - battle animations are boring as all git out - satanic themes and lots of lesbian stuff and racy outfits. as a Christian man i cannot reccomend to other born again christians.       SIDE NOTE: they mention a ', 'Very Positive', 93.57, 3.72, 32.32);
INSERT INTO reviews VALUES (4289, 377760, 108, 'Fox & Flock\n\nHas a total of 8 trading cards.\n', 'It''s difficult to criticize cheap games, but I found myself not pleased with my overall experience of the game. The length of the main part of the game is to be expected, so no problems there. However, there is so little replay value even with the quick game option. No multiplayer is a glaring example. My experience with the game in both story and quick play has been to repeat the same moves repeatedly until the ai eventually makes a mistake. If the aim of the game is to win, then I find this to', 'Very Positive', 87.04, 1.63, 4.60);
INSERT INTO reviews VALUES (4290, 377840, 5911, 'I got severe nostalgia and emotional trauma from this game. I want to go back to being a kid, and play this game while my mom cooks in the other room. Hopefully we get to go to the Final Fantasy in the sky one day.\r\n\r\n10/10', 'Woke environmentalist messaging. Protagonist is a rip off of a saiyan (Tail + Trunks hair + powerful). Tbh nothing original is brought to the table, and the graphics looks like Food Fight.\n\nNobody in the world ever remembers the main villain of this game. Because its boring asf. Theres a reason Nintendo is smart enough to not put characters in this game in Smash.', 'Very Positive', 94.18, 17.92, 32.92);
INSERT INTO reviews VALUES (4291, 377860, 695, '\r\nLegendary bullet hell type shooter where you shoot bugs on some distant planet. Plenty of modes to choose from like novice, original, arrange, 1.5 version and besides that no difficulty options. Soundtrack is nice but sounds need a little more bump in the settings (super quiet). Lack of some goodies like switching slowdowns on and off and some filters would be nice to see. Gameplay is very short - only 5 stages. Overall it plays good and visuals are decent. Recommended.\r\n', 'Typical CAVEshit where you brainlessly swipe side to side & hoard bombs to spam at the end of the game. Why this style of shmup became the standard, I''ll never know.', 'Overwhelmingly Positive', 96.98, 4.10, 10.07);
INSERT INTO reviews VALUES (4292, 377870, 303, 'can''t get over how good the music is, but also how much the dlc mode gameplay adheres to the systems of the originals games they are based on. sure, it''s expensive dlc, but they do put in effort into them - but they go on sale. anyway good game', 'Remote play together does not work on this game and is an advertised option', 'Very Positive', 81.19, 2.53, 1.12);
INSERT INTO reviews VALUES (4294, 377900, 452, 'It''s amazing how many times over the years I''ve come back to this simple little sim. I keep wishing for a sequel to push the idea even further, but it''s still well worth the price.', 'I wanted to like this so much!  I love the visual style, the little blocks and things, the way you can schedule and re-arrange your schedule - all of that feels great.  I like moving up and down the building and the cute nods to various characters from movies / tv shows.\n\nBut... this just doesn''t feel like a sim game to me. The viewers are random, you can''t influence it other than rejecting a few each day. The advertising system is arcane, I could barely figure it out. It was difficult to see mu', 'Mostly Positive', 75.00, 73.57, 1.70);
INSERT INTO reviews VALUES (4296, 377950, 146, 'Works on Steam Deck!\n', 'Jamestown goes far beyond what you''d expect from shoot ''em up lore, offering a very creative interplanetary steampunk setting. Unfortunately, that was the only thing that impressed me. The game does feature charming pixel art, some unlockable content and a few modes to add variety, but stages are too short, sound design is quite weak and the ship mechanics didn’t really grab me.', 'Very Positive', 90.41, 0.65, 3.65);
INSERT INTO reviews VALUES (4303, 378110, 104, 'Very good Game. Entertained me well.\nStory at the End is a little bit WTF, but the gameflow is nice.\nYou dont need any programming skills just a little bit free brainspace and maby google for binary decoding.', 'This is a unique game. It''s a hacking style / text adventre game that requires you to think and unless you plan on playing it all in one sitting, take old fasioned notes.  The story unfolds via email converstations that lead you to more emails that lead you to more emails.\n\nThe first half of the game is reading emails to get the next users email account password. It even requires you to visit external sites which adds a bit of immersion, but also runs you into the ground. Once of the sites in ga', 'Very Positive', 82.69, 2.12, 1.22);
INSERT INTO reviews VALUES (4306, 378270, 165, 'Heavy horrors for all the old-school shooter classics lunatics!', 'Doom 3 for people who smoke inside, wear tracksuits, and have an additional chromosome. There''s a fucking reason why only 2% of the people who own this game finish it.\r\n\r\n"Is it because it''s the Dark Souls of video games?? Are you a casul who hates difficulty??" I hear you saying, ashing all over your tracksuit, half-eaten chunks of red Crayon spraying everywhere -- your favorite flavor.\r\n\r\nWhy yes, this game is difficult to finish. The levels are all linear tunnels that connect to big arenas. T', 'Mixed', 67.88, 8571.37, 1.58);
INSERT INTO reviews VALUES (4309, 378360, 472, 'Oink.', 'Needs a better combat system.\r\n\r\nEither allow people to control their units in combat or give the ai a bit more intelligence\r\n\r\nthere is no reason my ranged units should be running face first into the enemy''s melee units just because they are faster than my melee units', 'Mostly Positive', 71.82, 28.68, 321.87);
INSERT INTO reviews VALUES (4310, 378370, 184, 'Just another clone of Minecraft+Dayz+Rust.\n\nSooo Yeah thats what im gonna say :)\nPretty Enjoyable with Friends', 'Probably the worst crafting and inventory system ever seen in a survival game.', 'Mixed', 67.39, 2.30, 12.32);
INSERT INTO reviews VALUES (4319, 378540, 4104, 'I can''t believe how quickly I fell in love with this game. It has good story premice, amazing setting and very brutal combat system. Weapon impact is beyond fantastic, you can slice off body parts from enemies and also feel the weight of your tools of justice. Level design is pretty solid, you always making progression to unlock new parts of maps (which are HUGE) or shortcuts. Exploration is always rewarded.\nOverall in my opinion The Surge is a very underrated game, it deserves much better.', 'I really tried with this game. I even liked it for a good chunk but there are so many small things about it that are just pure bullshit. First off the game explains less then nothing about boss fights or quite a few combat mechanics. Your first boss fight is a huge red flag of this. You enter this boss fight blind and it tells you nothing about how to beat it, but did you know if you beat it another way you get one of the best heavy weapons in the game? Thank you for making it that was so I miss', 'Mostly Positive', 76.92, 60.38, 25.02);
INSERT INTO reviews VALUES (4321, 378580, 107, 'So started out my game trying to avoid the amorous advances of a male mountain lion, wanted to explore the surronding area. After a few adventures I stalked through a piece of heavy vegetation and found myself two metres away from a hunters big bad rifle, I swiftly pounced mauled the hunter senseless then threw him off a cliff. I scampered down after him to have nice tasty breakfast of Cletus but unfortunately it seems human meat is off the menu...I was then killed by his hunting dogs in brutal ', 'This is one of those games that feels like a really promising beta release that could be amazing with a bit of cleanup and polish. Unfortunately, this game is out of beta and hasn''t been updated in nearly a decade. (The studio''s website linked in the game doesn''t exist anymore! Spooky!)\n\nThe controls are terrible, the ui is passable at best and actively hinders the experience at worst, the constant animal noises are grating, and it commits the ultimate crime of having really ugly baby animals.\n\n', 'Mixed', 63.55, 22.53, 49.57);
INSERT INTO reviews VALUES (4323, 378610, 4251, 'I thought this was a fun, shorter game. It looks great for a game released 10 years ago and I found the mechanics to be fun. It isn''t challenging, really. But I enjoyed it as more of a casual experience. It was certainly a breath of fresh air for me as I''ve mostly been jumping from massive open world to massive open world. The game had good progression, kept things fresh and introduced new mechanics frequently and I found the story to be a nice bow to tie everything together and didn''t detract f', 'To be honest it seemed cool initially but the gameplay loop is the same which is run from point a to b while being a collectathon. Some may enjoy personally its not for me.', 'Very Positive', 91.20, 2.42, 0.68);
INSERT INTO reviews VALUES (4325, 378660, 483, 'only two episodes, but they are well done. great voice acting, interesting setting and mood, fantastic music. worth a few hours of your time', 'Game has no continuation, stops at episode 2, don''t buy it.\n(could have been good but doesn''t really matter anymore)', 'Mixed', 54.66, 5.83, 0.28);
INSERT INTO reviews VALUES (4327, 378720, 2127, 'this and its sequel are two of my favourite games. if you play civ but start way more games than you finish you are going to love this game', 'The game itself if addictive but they''ve made it impossible to progress. I''ve restarted several times and every time the computer just kills you off. You think you''re building up to something then bam, your entire team is killed in a natural disaster or surprise attack by someone way more powerful or something. I was playing on regular difficulty. \r\nThis last time I thought I''d play it super safe, stay close to my town, build up my team on small things before venturing out. The computer sent som', 'Very Positive', 89.89, 865.58, 37.08);
INSERT INTO reviews VALUES (4330, 378770, 172, 'yousuke yasui my beloved', 'I don''t understand how Eschatos receives high praise and I''ve played a lot of shmups, including Qute''s Judgement Silversword. It''s not a terrible game, but there''s a few issues that make this game annoying.\n\nScoring in this game is honestly frustrating. You have a score multiplier that goes up after successfully defeating a few waves. Every death and enemy missed drops the multiplier by 1. Dying once, especially towards the end of the stage, can easily drop your multiplier due to popcorn enemies', 'Overwhelmingly Positive', 95.93, 15.65, 2.28);
INSERT INTO reviews VALUES (4332, 378800, 137, 'Good Like this Piece of Pizza\n⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⢰⣿⣿⣿⣿⣿⣿⣿⣷⣦⡀\n⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⢠⣷⣤⠀⠈⠙⢿⣿⣿⣿⣿⣿⣦⡀\n⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⣠⣿⣿⣿⠆⠰⠶⠀⠘⢿⣿⣿⣿⣿⣿⣆\n⠀⠀⠀⠀⠀⠀⠀⠀⠀⢀⣼⣿⣿⣿⠏⠀⢀⣠⣤⣤⣀⠙⣿⣿⣿⣿⣿⣷⡀\n⠀⠀⠀⠀⠀⠀⠀⠀⢠⠋⢈⣉⠉⣡⣤⢰⣿⣿⣿⣿⣿⣷⡈⢿⣿⣿⣿⣿⣷⡀\n⠀⠀⠀⠀⠀⠀⠀⡴⢡⣾⣿⣿⣷⠋⠁⣿⣿⣿⣿⣿⣿⣿⠃⠀⡻⣿⣿⣿⣿⡇\n⠀⠀⠀⠀⠀⢀⠜⠁⠸⣿⣿⣿⠟⠀⠀⠘⠿⣿⣿⣿⡿⠋⠰⠖⠱⣽⠟⠋⠉⡇\n⠀⠀⠀⠀⡰⠉⠖⣀⠀⠀⢁⣀⠀⣴⣶⣦⠀⢴⡆⠀⠀⢀⣀⣀⣉⡽⠷⠶⠋⠀\n⠀⠀⠀⡰⢡⣾⣿⣿⣿⡄⠛⠋⠘⣿⣿⡿⠀⠀⣐⣲⣤⣯⠞⠉⠁\n⠀⢀⠔⠁⣿⣿⣿⣿⣿⡟⠀⠀⠀⢀⣄⣀⡞⠉⠉⠉⠉⠁⠀\n⠀⡜⠀⠀⠻⣿⣿⠿⣻⣥⣀⡀⢠⡟⠉⠉⠀⠀⠀\n⢰⠁⠀⡤⠖⠺⢶⡾⠃⠀⠈⠙⠋\n⠈⠓⠾⠇', 'It starts out great at the start but the more you progress the more it demands out of you which yes is realistic and I like that, but when the UI is difficult to navigate and you spend 5+ minutes just trying to find officers and cars on the map it becomes tiresome and annoying. Officers do not go back to the predefined patrol that you want them to after you dispatch them to a crime scene and there are general bug issues. So if you forget where your officers were on the last callout, you can spen', 'Mixed', 54.01, 4.10, 2.38);
INSERT INTO reviews VALUES (4335, 379210, 856, 'I''ve had this game for years, but I never got into it because it just throws you in the deep end and the wiki wasn''t super helpful for a long time. For some reason, though, it always called me back even though I would usually fumble around and die before I actually got anything done.\r\nThe past few days though, on probably my fifth try on learning this game, it all clicked and I started to understand what it''s all about, and I''ve been loving every second of it! This is a roguelike survival game, ', 'Interface, interface interface. Why does stuff not stack in your inventory, just gives me finger RSI from all the scrolling. Why if i have an axe equipped do i still need to go to my inventory to use it. Only gave it a quick play, but immediately got turned off this by what feels like an interface that was designed to be obtuse.', 'Very Positive', 86.45, 36.30, 1.25);
INSERT INTO reviews VALUES (4340, 379420, 115, 'Gameplay is very okay, no QOL - abandonware, but it looks very pretty if you stretch it across 3 monitors, best music visualiser I''ve seen. \n\n I am so enthusiastic about this Visualizer I got in contact with the developer who had to move on from this project to find a job which pays the bills. I expressed my enthusiasm for the game and my joy of the experience I have had so far and a few small qol things that I''d like to see in the game and some problems I had encountered but couldn''t solve.\n\nHe', 'Don''t buy if you are trying to add your own music in 2024. \nThis app ix longer supported by devs. This game is (almost) pointless without the functionality to add your own music.', 'Mostly Positive', 78.26, 107.18, 0.23);
INSERT INTO reviews VALUES (4341, 379430, 55621, 'Remember Oblivion? Not the gameplay, not the plot, but the feeling you had when you first got out of the sewer. This is the first real rpg in a long time who reminds me of this.', 'I tried to enjoy it, I really did, but the combat was absolutely terrible.\r\n\r\nThe world, quests and feeling of progression are incredible, but when you have to actually fight (main quest, sometimes you can''t kill your enemies stealthy) the game becomes a chore: it''s not fun and it''s janky; a peasant with a stick can, somehow, parry every single attack you throw at it with the best weapon in the game and with a lot of strength.\r\n\r\nIf you can ignore that, there is a great game underneath, but not ', 'Very Positive', 83.52, 31.55, 42.80);
INSERT INTO reviews VALUES (4348, 379720, 79369, 'Other games: 20 min. intro and tutorial.\n\nDoom: Here is a gun. Shoot everything.', 'Just here to say that despite "Overwhelmingly positive" this game isn''t gonna be everyone''s thing.\n\nI got 4 hours in and did not find the combat very enjoyable. \n\nMaybe it gets better... but I probably won''t return to it.\n\n', 'Overwhelmingly Positive', 95.65, 13.73, 4.15);
INSERT INTO reviews VALUES (4352, 379980, 1063, 'Great game but I''m disappointed I couldn''t bang ISU-152 or Char-B1 or Bob Semple ;(', 'I thought, until the abrupt end of this game, that I would be recommending it without hesitation.  The historical jokes are spot on and well written and there are many references to the strengths and weaknesses of the tanks these girls represent.  The whole VN has a great humorous vibe and sucks you in with smart humor.  However after two hours, just when any other VN like this would be starting to get deep, the game abruptly ends no matter what choices you have made up until that point.  It''s a', 'Very Positive', 92.10, 29.17, 2.37);
INSERT INTO reviews VALUES (4355, 380020, 148, 'The controls are horrible. Every time I play Alyosha my shots are mostly innaccurate even If I''m right infront of the enemy. The Bandit Archers are the most annoying enemy in the game, They are always running away, It''s hard to catch them with the walking speed you get with these Three Bogatyrs and you have to stay still to attack which made the things even more difficult and It''s even more difficult If you have to protect some villagers. \n\nOn the other hand the game has really nice graphics, am', 'One of the most frustrating games I have ever played. The basic game is fun but as soon as you have to protect someone or get across the map in 30 seconds the game becomes an agonizing frustrating pile of crap. Then there''s being locked in focus with an enemy. I can''t imagine this was actually play tested. Terrible game. I''ve played games with 15% rating that are better than this. Save yourself the headache.', 'Mixed', 43.92, 4.03, 6.57);
INSERT INTO reviews VALUES (4359, 380150, 880, 'This game offers a compelling blend of horror and sci-fi. Set in a dystopian future, the game follows the protagonist as he navigates a derelict spaceship in search of his missing family. The game excels in creating a tense atmosphere through its detailed isometric graphics and eerie sound design. The puzzles are challenging yet logical, providing a satisfying sense of progression. While the narrative is engaging, I think the pace is slow, character movements are janky the controls somewhat clun', 'I don''t have patience for obscure puzzle games with the "try everything with everything until something works" design philosophy.', 'Mostly Positive', 78.52, 76.95, 1.37);
INSERT INTO reviews VALUES (4360, 380220, 586, 'I had so much fun with this game when you could find players. im sad its dead. I wish there were bots to play with.', 'NO BOTS? I WOULD BE IRATE IF I SPENT 20 BUCKS.', 'Mixed', 60.41, 5.83, 0.72);
INSERT INTO reviews VALUES (4366, 380580, 197, 'best game ever', '\nPINK UNICORN... what is this doing in my library?!\n', 'Mixed', 58.38, 0.28, 3.97);
INSERT INTO reviews VALUES (4367, 380600, 223, 'Fish...', 'Just a non stop hammering of ads, despite having bought almost every pack... So, they will bombard you with numerous other packs.  So they are making money, thats for sure, graphics are dated, gameplay is buggy, the only thing it has going for it. It''s the only real fishing game on steam or really anywhere that still has comps and some clans to join.  \r\nIt''d be fine if the everything wasn''t bugged.\r\nlike almost everything.', 'Mixed', 65.92, 69.80, 299.08);
INSERT INTO reviews VALUES (4368, 380660, 115, 'wow. what an amazing concept. highly recommend to play this game. \r\n\r\nyour on a spaceship headed away from home, its ok, you still have social media to stay connected to your friends and family. the app you have works similar to twitter, you can like and comment on peoples posts, get instant messages and read the news. the only issue is youre a bit late to the party most of the time as the time difference means that 1 minute for you could mean a year back home. an event is well over before you c', 'Premise sounded cool, but the execution felt rough around the edges and it didn''t make a whole lot of sense.\r\n\r\nFelt like a waste of time, but so is browsing social media, so I guess that makes sense?', 'Very Positive', 81.74, 0.67, 3.38);
INSERT INTO reviews VALUES (4369, 380670, 268, 'This game is still amazing even eight years after launching. I can''t believe it hasn''t been ported to the Quest platform. Surely it would sell really well on there.\r\nSteam is incorrectly showing that I''ve only played four hours of this game; I''ve actually played tens of hours.  I''ve had this game pretty much since it launched back when I had the original HTC Vive. I''ve since placed it on Vive Pro, and more recently via Steam Link on the Quest 3 and most recently using the PSVR2 adaptor. It looks', 'Too many tedious tasks. It is fun at first but very quickly gets stale doing the same thing over and over.\nSure there''s some variety, but they get stale too. The price is also way too high for this game.\nIf it was under $15 might be worth it. Otherwise, not much fun beyond the initial moments.\n', 'Very Positive', 93.66, 4.90, 0.85);
INSERT INTO reviews VALUES (4372, 380750, 234, 'I enjoyed the gameplay and scenery of the game', 'Pathetic bad port. \nCan''t rebind keys and no keyboard prompt.\nGame crash when press Escape in game.', 'Mixed', 67.95, 403.85, 0.27);
INSERT INTO reviews VALUES (4380, 381020, 774, 'excellent game with tons of replayability, well worth its price. the base game has loads of customizability and things to mess around with, but when you''re done with the vanilla sandbox the workshop has plenty to keep you busy!', 'Incredibly punishing difficulty curve. Even when clearing days 1 though 5 perfectly, day 6 and beyond jack up the difficulty to the point of instantly punishing you for even minor mistakes due to scaling enemies 4 fold, or tracking missiles doing 3/4 of your health, even with top tier aircraft.', 'Very Positive', 93.02, 49.40, 8.97);
INSERT INTO reviews VALUES (4382, 381100, 188, 'I loved this Dogenzaka game. I''ve been writing quite a few reviews lately, Destiny princess, my butler, pub encounter, office lovers and now this one. To keep things short I''ve gone down an otome rabbit hole of Dogenzaka Games and I am loving the games I''ve played by them so far. \n\nThe Good:\nThe Men of Yoshiwara: Kikuya is really well done, each route has such variety and creativity put into them I loved all the Characters so much. The characters and stories are so well done it was really hard t', 'Do yourself a favor and don''t buy this. The story is written so poorly. Absolute cringefest and predictable storyline. Played two routes and wanted to shoot myself every second of it. The remaining hours played were idle times as I hated this game so much that I closed my laptop and didn''t touch my laptop for 30 hours.', 'Mostly Positive', 70.21, 30.27, 32.52);
INSERT INTO reviews VALUES (4383, 381120, 1528, 'i loved this game, i still do and play it when i get nostalgic. too bad they abandoned it.', 'The game was abandoned to sell a second game, which was also abandoned.', 'Mixed', 64.99, 36.52, 0.58);
INSERT INTO reviews VALUES (4387, 381210, 220303, 'This game is not fun, until it''s fun. But then it''s not, but then it is. \r\nThanks for coming to my ted talk.', 'BHVR has been scamming players by having skins region locked but still having them available for purchase in those regions, and then refusing to give players refunds when they can''t use said skins. Do not give them any money.', 'Very Positive', 80.66, 165.68, 2733.88);
INSERT INTO reviews VALUES (4390, 381260, 102, 'Fun little game. Its like a digital storybook game. It gives you little scenes and you decide how to deal with it, based on your skills and potential resource gains/loss. The longer missions really require you to balance your strengths with your resources, or you will run out. Good humor too, in satirizing the numerous Sci-Fi tropes. Recommended', 'The writing''s not bad, it''s just not good enough to carry a game that is essentially just a series of slot machines. Particularly since it''s got a bit of a doom spiral mechanic where past losses make future losses more likely.', 'Mixed', 69.61, 56.45, 1.25);
INSERT INTO reviews VALUES (4399, 381750, 174, 'need multiplayer mode because i cant play with my father and friends and local multiplayer and worly wild multiplayer need for the game and the track editor needs a calculation to the slidebars option but over all its a pretty good game it just needs some little tweaks!!!!', 'not the best the ai dosnt work well idk if its my system but the game still needs a lot of work', 'Mixed', 66.09, 11.02, 4.20);
INSERT INTO reviews VALUES (4400, 381780, 894, 'This is *close* to being a masterpiece. If you like ''choose your own adventure'' stuff, get this game- immediately.', 'Laden with steampunk, LGBTQ nonsense, and anti colonialism at every turn. What a disgrace to the original works.', 'Very Positive', 92.28, 9.97, 2.37);
INSERT INTO reviews VALUES (4410, 382050, 450, 'Loved this game. Sad it had to be discontinued.', 'DO NOT BUY AS THE REQUIRED APP TO PLAY THE GAME CAN NO LONGER BE GOTTEN AND STEAM SHOULD PULL THIS DOWN AS IT JUST STEALING YOUR MONEY WHEN THERE IS NO WAY TO PLAY IT.\n\nAlso even if you find the APK and install it that way it still won''t let you use it as it thinks you didn''t pay for it when the app is FREE and only usable if you got the game so why does it matter if I brought the app its FREE anyway.\n\nBut other than that, if there is ever a way to play it again it is worth giving a go.\n\nSTEAM P', 'Very Positive', 86.44, 3.93, 3.40);
INSERT INTO reviews VALUES (4413, 382090, 137, 'Dungeon Nightmares is back, and it’s better than ever! It takes the classic formula we all loved and adds some new twists, more to discover, and even more ways to meet a horrifying end. At least now we can pick up where we left off instead of starting over from Night 1 every time, right?\n\nBut honestly, just the atmosphere alone is enough to freak me out. The ambient sound design? Top-notch. The dev clearly learned from the first Dungeon Nightmares and dialed everything up to 11. Every creak, eve', 'game looks boring and cheap jump scares got it on sell 59 cents', 'Mostly Positive', 75.91, 0.92, 0.62);
INSERT INTO reviews VALUES (4414, 382110, 1480, 'It''s great for porn and even video games.', 'Dev abandoned the software and doesn''t provide quest support, only updates the meta store version anymore on top of aggressively responding to negative reviews', 'Mostly Positive', 70.95, 57.85, 53.47);
INSERT INTO reviews VALUES (4417, 382140, 586, 'https://steamcommunity.com/sharedfiles/filedetails/?id=532033966', 'No skill required at all. Completely based on luck.\nI don''t mind RNG, when I feel like I can use my brain to work around it. But that''s impossible, as there is really no strategy to the game. It''s just rolling of the dice on each run.', 'Mixed', 68.77, 10.75, 0.45);
INSERT INTO reviews VALUES (4421, 382260, 170, 'Fun game for local multiplayer with friends.', 'I am making this review after playing the single player mode as a quest to beat all the steam games i have so ignore my review if you are looking for the coop part.\n\nThe single player campaing is similar to the bloody trapland gameplay.. a lot of cheap of deaths and that''s it.\nThe hitboxes of the objects that kill you are giant, a lot of times you wrongly jump on the plataform as it doesn''t has a good coyote jump mechanic and often you will go a little too much or to little on platform jumps..i ', 'Very Positive', 92.35, 48.58, 2.95);
INSERT INTO reviews VALUES (4423, 382300, 131, 'With Kidnapped the opinion of players are quite differing but everyone got his own one, related to what to like or to dislike, investing and expecting so as being fair to the whole thing. For me, I liked the short story what kept me going, means it never got bored and I wanted to pass thru so it has a certain degree of motivation. Sure that one must not expect too much, neither from the story nor from the quality but worth playing it is. The chapters are differing, the mansion part is good, the ', 'First mansion level feels interesting/good and promising for spooky nice atmospheric game little bit amnesia feeling. but after that level game changes very trash and it''s getting worse all the time when you play forward because boring levels and stupid gameplay/plot so maybe 4/10 not worth of money.', 'Mixed', 46.56, 2.22, 1.88);
INSERT INTO reviews VALUES (4424, 382310, 6263, 'was really good but locked a lot of new decorations behind a paywall now after last big update. and this game is 30 dollars...\nits not just a dlc to buy its each one is bought ingame with credits. thats right a PAYED game has bought in game credits. purely disgusting. other than that the game is great lmao', 'Actively harmed the ability to mod the game, mostly cosmetic things...\nand now they''re releasing a "cosmetic-only" micro-transaction shop in the next update, alongside a mechanic where people''s opinions on how your structure looks can give you a mechanical advantage, meaning that a mere cosmetic item can indeed have a mechanical value.\nOn top of this, the game has shifted away from it''s original gameplay and vision that made me and my friends wish to engage with it. It''s grindier, focuses more o', 'Mostly Positive', 79.07, 171.12, 79.55);
INSERT INTO reviews VALUES (4426, 382330, 114, 'The game has interesting inventory and NPC management, and a gorgeous art style, but doing the actual heists plays very miserably and is what makes me hesitant to play this often. I''d only recommend someone to play this game only for ideas to develop their own fantasy thieves guild management game.\n', 'Lost to the UI boss. The game''s control are very unintuitive and this isn''t helped by the lack of any meaningful tutorial. Interactions are also not consistent. It feels like whatever playtesting this game got, it got with the devs standing over thesholders of the play testers instructing them how to play the game.\n\nAlso the guard AI is weird as fuck. Why are guards patrolling inside multiple buildings? Why does me running into a building not trigger reaction, but leaving one door open causes th', 'Mixed', 43.86, 1.50, 0.55);
INSERT INTO reviews VALUES (4428, 382380, 143, 'Basically a JRPG, “The Amber Throne” is most distinguishable by its artistic graphics and beautiful music that you will rarely see and hear in games of this type. You start the game as a warrior-princess just woken up from hibernation into a world in turmoil, and you need to muster your skills, gather resources and assemble your companions to ascend to the Amber Throne and deny your rivals to gain access to its power. The plot is quite intriguing, although the story isn’t exactly descriptive and', 'It''s an RPG in the loosest sense. \r\n\r\nPositives: \r\nArt is great\r\nMusic is good\r\nPacing is a through line. No grinding..also*\r\nOverarching story and concepts are really great.\r\n\r\nNegatives: \r\n*No grinding. Not challenging at all for experienced gamers.\r\nNo content\r\nExplorations is not rewarding\r\nSide quests result in nothing of benefit\r\nStory writing is not fleshed out and often confusing or missing key content.\r\nCharacters help with nothing in narration or moving the story along in any meaningfu', 'Very Positive', 81.82, 23.87, 23.58);
INSERT INTO reviews VALUES (4431, 382560, 2473, '2010''s drama youtuber background gameplay ahh game', 'For the sale price it would have been a fun game to fill the time, but I have one big issue. \n\nBy default you are opted into data collection in the settings menu. If you would like to turn that off, you will have to sacrifice the ability to play online and unlock cosmetics. In this PAID game, you are required to have your data harvested in order to play online. Ridiculous.', 'Very Positive', 93.33, 2.77, 0.47);
INSERT INTO reviews VALUES (4439, 383080, 119, 'Leonardo da Vinci could write with one hand and draw with the other at the same time.\nWell i can play this with one hand and fap at the same time.\n\nCoincidence? I think not.', 'who played 0.2 hours of this on my steam account? wtf\n\nedit: it was me', 'Mostly Positive', 79.83, 1.12, 0.32);
INSERT INTO reviews VALUES (4441, 383120, 17419, 'I like the fact you have 3 mode of playing this game. The internet is so toxic, so solo or coop is perfect for me. I don''t need or want the drama, and with this game I don''t get it. Thank you.', 'Game has tons of glitches as of 030325 the instead of fixing the original the company makes new DLC''s that work even worse. The workshop is the ONLY thing saving this game and because of the ship designers this game has a great open world to fly massive ships of all kinds in. The game is very time consuming I have over 380 hrs and I don''t even like this game.', 'Mostly Positive', 79.25, 133.08, 397.78);
INSERT INTO reviews VALUES (4442, 383150, 8517, 'It might be a terrible game from the early 2010s, but it''s MY awful game from the early 2010s, I remember coming home from school and booting this up, and the nostalgia still hits good\r\n', 'fun at begining, but after a while it just feel repetitive. zombie feel all the same, weapon upgrade is meh, looting is not that excited.', 'Very Positive', 81.73, 86.77, 19.88);
INSERT INTO reviews VALUES (4443, 383180, 2258, 'Fun to coop. If you''ve ever had a banquet microwave meal meant for children it may be tempting to skip the horrible corn that tastes like plastic and eat the nuggets and brownie first. This is wrong, all real men finish the corn, then the fries, then the nuggets, then the spongy brownie. This game is the same way. It may be tempting to skip to dying light, an objectively better game, but all real men will eat the corn that is dead island and dead island riptide.', 'Dead Island: Riptide Definitive Edition is a decent zombie survival game that can be fun to play with friends. However, I don’t recommend it. The game can be quite shaky and even headache-inducing at times, which really takes away from the experience. The graphics are fine, but the gameplay gets repetitive after a while, and it doesn’t feel very engaging in the long run. For someone who hasn’t played the first game, this didn’t leave the best impression, and I''d recommend Dying Light instead. 6/', 'Mostly Positive', 73.74, 10.62, 50.78);
INSERT INTO reviews VALUES (4444, 383230, 811, 'Kinda fun little game. Not a lot of substance though.', 'Not fun', 'Mostly Positive', 74.48, 0.55, 0.25);
INSERT INTO reviews VALUES (4446, 383270, 729, 'I absolutely adore this game! It’s a brilliant puzzle-platformer and you literally swap colors to solve puzzles, and ngl it’s SO satisfying. The whole vibe is cute. we are a boy searching for our lost mother, is touching, it’s mechanics and how insanely pretty it looks that had me hooked from the very first minute! Every puzzle feels fresh and rewarding I’m completely in love with it. If you’re into puzzle games, IT IS A MUST-PLAY', 'Fiddlesticks made a good puzzle game then started on an NFT game, hope it flops.', 'Very Positive', 92.04, 4.82, 6.87);
INSERT INTO reviews VALUES (4448, 383460, 182, 'I don''t usually write Steam reviews but someone asked for horror recs, and this one immediately came to mind. I played it 8 years ago and I still think about this game. As a horror enthusiast, not a lot unsettles me, but the atmosphere here is just genuinely unnerving. The art, the soundtrack, the dialogue - they just combine in a way that few VNs (or horror games in general) manage to pull off to immerse you in the story. Well worth the read.', 'This stuff is from 2014. Plays like a 2010 horror pixel 2d RPG, which I very much adore, but in VN form. Think of Ib and Mad Father... but boring.\r\n\r\nI just cannot bother with the mediocre writing + bland scenarios to be honest. Not my cup of tea, probably.', 'Very Positive', 84.62, 10.37, 3.57);
INSERT INTO reviews VALUES (4456, 383690, 111, 'Let me start by saying that the game is fun, and with enough internet kudos-fu, experience, you can still work out how to solve these problems by yourself given you have access to the internet (mailer.mucomplex.com), and can change system-critical settings (for TLS applications) like the machine''s non-NTP clock time in order for the game to generate the right time-based code or allow access.\n\nThe game is aging, and activity on the social media accounts has stopped since around May of 2023, meani', 'This used to be such a good game, and I would have recommended this game before, but the code that is needed to proceed on one of the levels is no longer being generated (I''m guessing it''s when twitter became x and the developer didn''t update the game to account for this), so the game is now unplayable from this point on.', 'Mostly Positive', 77.48, 9.95, 26.48);
INSERT INTO reviews VALUES (4461, 383740, 114, 'Desperately needs a ''Remove Kebab'' DLC for post-1000AD game.', 'This game is not a strategy game it''s a rage game thb, I think it''s so crazy how RNG based this "strategy" game is to the point where the hard mode difficulty on sparta is impossible without crazy RNG draws or some kind of crazy step by step plan that hopes that you don''t get a negative RNG event, I like this game and I''ve been playing for a few years but I play 10 hours every few months. To be honest if I liked this game and thought it was a good strategy game I would have more hours on it but ', 'Mostly Positive', 77.19, 8.90, 64.95);
INSERT INTO reviews VALUES (4464, 383790, 349, 'Still love this epic game .. shame player base is now gone !', 'Abandoned nearly upon release, which is a shame as this game had a huge amount of potential. It baffles me why they dont just make it F2P.', 'Mixed', 57.88, 1.98, 0.67);
INSERT INTO reviews VALUES (4467, 383840, 1176, 'It s true the game play is quite repetitive outside of the drone building, which is why I recommend the "programmer" class. You''ll get almost all the buffs from the other classes without any of the downsides, however your drone has to be funny autonomous: no inputs once you start the level. \n\nThis forces you to sensors and logic games to control all of your drone''s movements, giving you mush more to do in the editor, while simultaneously removing the tedious aspects of normal game play.', 'For some reason despite the very engaging engineering system the game has the mechanics are seemingly intentionally designed to infuriate you and waste your time. I have come to this conclusion after dying 8 times to an early game enemy (boombug). The geniuses who designed this game decided to make a suicide enemy whose explosion range is the exact same as your initial laser cannons range that you can only damage when it runs away from you. This means that to not die when killing a boombug you h', 'Very Positive', 81.29, 199.03, 5.15);
INSERT INTO reviews VALUES (4469, 383870, 52004, 'Got it. Opened it. Played it. Finished it.\r\nIn one breath, without breaks. That was a wonderful experience. I got so close to the main characters that I started forgetting who I am.\r\nBreathtaking.', 'I want to love this game. The dialog, the characters, and the world building makes me feel so immersed. Then its all taken away by the simplicity of ending. I don''t care if there something big going on or something small. Its simply you don''t see any result of it all. Its a grand burger with lots of condiments, but it has no meat inside the burger ;-;. I want to see the end credits. I want to see the result of this game, whether the main character gained something or not. Nothing happened and my', 'Very Positive', 89.00, 8.05, 13.75);
INSERT INTO reviews VALUES (4474, 383980, 26359, 'this is like fortnite if it was a fighting game and the cosmetics did something and are free.\r\nin other words its nothing like fortnite', 'its ok but not worth 30 bucks', 'Overwhelmingly Positive', 96.55, 9.93, 3.68);
INSERT INTO reviews VALUES (4481, 384110, 1678, 'This game has done irreparable damage to my psyche, I can''t, in good conscious, recommend it to anyone. Luckily for me, this game has also completely destroyed my moral compass, everyone should go play this game right now.', 'favourite game', 'Very Positive', 87.90, 79.27, 15.17);
INSERT INTO reviews VALUES (4489, 384300, 2760, '', 'CPUCores is often advertised on /r/pcmasterrace and claims that you will have higher fps however, with an AMD FX - 8350 it hasn''t made much of an impact on my games. To top this off, YOU CAN DO THIS ALL FOR FREE WITH A DIFFERENT PROGRAM!!! as found on Reddit also can be explained  here. \nAlso after is was announced that this was deemed  "snake oil" the creator of that thread was banned from this steampage. *asshole move*\nI would not recommend buying this  and I also recommend you do some researc', 'Mostly Positive', 73.59, 0.00, 0.75);
INSERT INTO reviews VALUES (4490, 384310, 169, 'This is hard (maybe?) and the gameplay is clumsy, but it''s pretty okay. Probably would be better on mobile.', 'This game is impossible. im in a jungle but can only gather 3-4 wood a day??', 'Mostly Positive', 71.60, 5.92, 3.93);
INSERT INTO reviews VALUES (4493, 384490, 2624, 'I love this game. I was part of the QA team for it many, many years ago and after all this time, having worked on countless other games, this one has stuck with me and I always felt like it was special. I think it''s a shame it isn''t more well known and stopped being updated shortly after release.\n\nThe creative director for the game "Dennis Detwiller" had "Currently creating my opus NECROPOLIS" on his LinkedIn but left the company after it released. Probably because it was his passion project but', 'A great potential that was never realized. I always feel a bit sad about it whenever I see it''s name pop up in my library.', 'Mixed', 58.92, 13.70, 33.52);
INSERT INTO reviews VALUES (4494, 384500, 231, 'Kinda fun. no more developer update but the game itself is not that bad. Dont buy it if you want to online play with friend. Server doesnt work anymore. But local coop is still ok I think.\r\nYou will spend more time on doing "Slot machine glitch" rather than the actual game if you dont want to grinding to death by playing classic mode. Plus I think slot machine is fun. Slot machine glitch actually make the game more fun because you get ton of money to buy new weapons and other things.\r\nText in th', 'WARNING: Multiplayer ONLINE CO-OP Does not work... i bought this game especially to play with friends online so am a bit letdown to see that you cant even get on a game online. feeling very disappointed because the game looks really fun. maybe ill give it a go as a solo experience but the fact that online coop is advertised and that is doesn''t work is a big letdown', 'Mostly Positive', 75.32, 13.35, 0.25);
INSERT INTO reviews VALUES (4495, 384550, 232, 'This is the cutest, most adorable management game ever. Made for art history nerds. \r\nAs a management game, it is quite robust: the mechanics are intuitive and very easy to understand, but the game is still pretty hard even for seasoned management game lovers. \r\nThe little art history jokes are amazing: even though it is a very small game, I keep finding stuff that make me laugh. For example, the city news! They give some historical context but the way they''re written is so simple and silly, I a', 'I''m a really big art history person, so when I saw this game I was excited. Playing and installing it was easy and simple, it runs on almost nothing. Before playing it I knew nothing of the flash games and beta builds, I bought it on the art relationship alone. I''m not a real big gamer.\n\nThe game is probably not worth the price it is pushing now, I would dump it into the under $5 category. After about two hours I had pretty much capped out the usability of the game and it just turns into a repet', 'Mixed', 67.67, 2.83, 6.43);
INSERT INTO reviews VALUES (4496, 384570, 279, 'underrated masterpiece can''t wait for the remake', 'It''s easier to download the piracy version with all the patches than to suffer with this piece of shit.\r\n\r\nYou can’t just upload something to the Steam platform and leave everything in the same form in which it was all at the time of release.', 'Mixed', 68.10, 97.17, 33.87);
INSERT INTO reviews VALUES (4498, 384630, 892, 'Ace Attorney, but with French birds. Needless to say, I''m obsessed.', 'the aesthetic and atmosphere are great, but the game is extremely buggy. loaded my game up and my save file was unusable, after checking to discover this issue is common and was known about years ago, i didnt feel any motivation to replay to where i was.\r\n\r\ni understand this is a small game probably made by a limited team, but technical issues to this extent mean i cant recommend it to anyone. its not going to be fixed at this point, years later', 'Very Positive', 94.51, 5.97, 3.00);
INSERT INTO reviews VALUES (4500, 384680, 190, 'It''s a simple game with hit-or-miss humor - sometimes it''s funny, but other times it feels forced. The art style is kinda cute, and the pop culture references are fun. However, the controls are kinda awful and I wish there was a way to see all dialogue options at once instead of having to cycle through them one by one. \n\nStill, it''s a charming game, but ultimately very average.\n\nScore: 5.5/10 - Average', 'I thought this game could be a little relatable and fun since it shows a female interested in mechanics with simple drawings. I was wrong. This game is dark and not even funny. All it does is complain about life and make horrible scenarios. It''s also gross and shows nudity like women flashing their privates at construction sites, and tells a bleak story. I won''t play anymore of it to even finish and see if it gets better cause it''s just so bad. You can be a female or anyone who enjoys mechatroni', 'Very Positive', 85.79, 6.13, 1.32);
INSERT INTO reviews VALUES (4501, 384690, 133, 'how tf did these wizards program rope physics this good on the snes', 'they should use this game to torture terrorists', 'Very Positive', 91.73, 4.93, 0.08);
INSERT INTO reviews VALUES (4503, 384740, 506, '“CAT Interstellar” is a short adventure game in 3D, where you assume control of a robotic unit named “DOG”, deployed on the surface of Mars to assist with its terraforming and with a dangerous mission into the planet’s depths. For a small independent project like this, the game feels quite impressive and packs some interesting content in the best hard-sci-fi spirit, like high-tech but decaying planetary base, fully sentient androids that will make a comment or two as you pass them by, Mars surfa', 'Save your money, there''s not enough here to even prove that the dev is capable of making a full game. This could best be described as a small tech demo.', 'Mostly Positive', 72.73, 5.72, 3.62);
INSERT INTO reviews VALUES (4504, 384750, 219, 'Very nice photo-realism experience.  It takes about 30 mins to go through the whole experience.  Not sure it should have cost $24.00, but I guess it is a good way to introduce people to VR if you have friends over.\n\n', 'Go and look at Everest on Google Earth VR and you will have a very similar experience. If that isn''t enough and you want the low res experience of walking across one ladder and a 50m rope climb, you will love this. I felt robbed.', 'Mixed', 47.95, 1.62, 0.82);
INSERT INTO reviews VALUES (4510, 384960, 206, '- The game feels like mix between csgo and cod4,which is good.\n- Works great under linux. \n- They are adding old features such as leaning to sides,prone etc...\n- This game looks like it will be targeted towards competitive gaming.\n', 'Ehh.\n\nIt''s not bad but it''s not good either, it has no soul, it''s just a plain generic shooter with barely any content to play with.\nAt least it has offline bots.\nGameplay isn''t so bad but at this point, we could be playing Counter Strike, Call of Duty: Modern Warfare with the bots mod or anything else really.\n\n5/10 - If the developer could put more work onto this game, it could be something but game has been abandoned a long time ago now so... Get the game on sale for no more than 1$.', 'Mostly Positive', 76.70, 6.40, 0.08);
INSERT INTO reviews VALUES (4524, 385240, 589, 'father, i crave new content', 'Can''t make custom characters without game crashing please fix. I want to make this positive when they do.', 'Very Positive', 85.06, 10.18, 14.52);
INSERT INTO reviews VALUES (4525, 385250, 351, 'Well worth it. Great puzzle arts, however it lacks some quality of life features like marking cells / counting them, which makes it a bit harder than it has to be.', 'this is a fantastic game and great value for money and even has a demo with plenty of puzzles. I''ve put dozens of hours into it and I still have at least 20 master pictures left to do and there''s workshop support too with additional puzzles. the music is a matter of taste, I don''t really like it, but the ui could definitely use some work. I''m sure it''s fine on mobile devices but on pc there''s just too much unnecessary clicking. not a huge deal but worth mentioning.\n\nwhy the thumbs down then? bec', 'Overwhelmingly Positive', 98.01, 17.12, 149.12);
INSERT INTO reviews VALUES (4529, 385330, 419, 'In my search for hidden gem RPG Maker games, finding something truly meaningful and special like this game is a rarity. When I started playing, I was immediately charmed by the art style and the wonderfully twisted aesthetic. As I kept playing, the game kept surprising me with how creative it could be. And then, that magical moment occurs where it all begins to come together, and things start falling into place. It crafts one of the most meaningful and emotional experiences that could come from ', 'hot garbage', 'Very Positive', 93.32, 1.70, 0.08);
INSERT INTO reviews VALUES (4533, 385380, 852, 'This is a very interesting game that, as you might could tell, scratches a very similar itch as Terraria, however this game is nowhere near as wide and yet much deeper. There are mechanics in the game that I can barely even begin to scratch the surface of, and lead me to believe there is a very high skill ceiling indeed. It''s pet system is very unique and very fun, the moment to moment is very engaging and there''s plenty of content to explore. I can heartily recommend it, except... The game was ', 'yay! 1.0 finally here after all these years, time to reinstall and play the hell outta the completed game!\neagerly dive into the change notes, excited to see all the updates and additions... and am immediately done because the only change is making the tutorial functional.\nso much for complete, devs calling it 1.0 because they''re done, not because the game is\n\ndon''t waste your time or your money on the devs last ditch effort to squeeze out a few bucks before completely abandoning this', 'Mostly Positive', 76.41, 43.85, 56.93);
INSERT INTO reviews VALUES (4539, 385560, 255, 'This game is a LEGEND. \r\n\r\nOriginally I played it on XBOX years ago, but still an excellent experience all these years later on PC. It really feels like a KONAMI game, but I guess it isn''t. \r\n\r\nApproved, and then some!', 'ugh, painful to play', 'Very Positive', 85.88, 55.02, 4.02);
INSERT INTO reviews VALUES (4545, 385710, 467, 'cheap, fun, short. levels are managable. not too easy not too hard. fun platformer. with a unique splatter illumination of the layout that makes the level easier the more you die. \nit was a treat.', 'I do appreciate hard games, but not the "this stage takes 5 seconds from end to end but you''ll spend 1 hour to conclude it" kind of difficult.', 'Very Positive', 86.08, 2.13, 1.45);
INSERT INTO reviews VALUES (4546, 385730, 953, 'If you''re looking for the best way to relive in the attitude era in Universe mode, sadly this is it.', '재미는\n잘모르겠고 복잡한게임', 'Mixed', 57.29, 110.17, 1.92);
INSERT INTO reviews VALUES (4548, 385800, 4808, 'Made me lost interest in real women.', 'I dont think ill ever understand peoples obsession with these games, this was boring as high hell for me', 'Very Positive', 93.78, 154.40, 0.72);
INSERT INTO reviews VALUES (4561, 386070, 7150, 'It''s like if they remade Total Annihilation but with round planets instead of a flat planet like Earth.', 'Incredibly annoying, as you have no control over your own troops or have to micromanage every single task.\r\nSince there is nothing in between, the best ways to win are also the most boring ones.\r\nA time sink that just does not get any better.', 'Very Positive', 86.62, 22.45, 57.55);
INSERT INTO reviews VALUES (4562, 386080, 118, 'divertido se voce nao esperar gameplay igual de um darksouls', 'Pharaonic is a game bogged down by repetitive gameplay and lack of meaningful progression. From the very beginning, the combat shows little evolution, and players will quickly notice that the same types of enemies are constantly being reused. The enemies are mostly humanoid warriors wielding various weapons, and even the bosses are essentially larger versions of regular foes with bigger weapons. This makes the game feel monotonous, and the leveling system is rendered pointless as enemies level u', 'Mostly Positive', 75.42, 9.07, 1.18);
INSERT INTO reviews VALUES (4568, 386180, 548, 'has gotten great since closed beta, lot of differences, only thing ill say theres some rela P2W players....they really got nothing btr to do than spend loads of money on items in the market just so they can win....Its sadm, kinda wish they would make this more creation rather than ppl just buy the best stuff on the market', 'Love the game, really, BUT there''s too many queues and not enough players for it all. To top it off, the game is quadruple dipped in monetization. As it is, I sometimes think I''d rather see the game dead and buried than shambling on, oblivious to its own community''s needs.\n\nRight now, I''m sitting here building vehicles with the battle walker legs. If I want to actually PLAY with them, I can play one PVP mode, which is just kill/collect to score. There''s a PVE mode based on the classic ruleset, b', 'Mixed', 60.40, 417.40, 246.52);
INSERT INTO reviews VALUES (4570, 386260, 488, 'I find that sometimes it makes me sad.', '1. The game’s controls are terrible. Players need to command swarms of cells or antibodies to move around, similar to games like StarCraft or Warcraft. However, every single command requires first left-clicking to select the unit, then right-clicking to issue the order—even if the selected unit hasn’t changed. This happens every second! Shouldn’t a proper design allow players to keep issuing commands with just right-clicks as long as the selected unit remains the same?\r\n\r\n2. There are many level', 'Mostly Positive', 78.89, 22.13, 3.90);
INSERT INTO reviews VALUES (4571, 386280, 134, 'Where to start?  If I gave reviews any credence I would never have bought this game.  As it turns out, I had a real blast.  I can honestly say that It''s the best ''piratey'' environment I''ve experienced and I''ve played a fair chunk of the games available in the genre.  Initially combat is really poor, your ship gets very easily beaten and you''re often left wondering what to do next.  As you level up and get to know the areas things begin to make more sense.  You will always get the feeling that so', 'I''ve never, ever played a game that forced me to give my personal data to "activate the game with Internet", whatever the fuck that even means. And when you try to do something as simple as adjust the resolution, the game can''t handle it and just gives you a black screen. The most pathetic, amateurish excuse for a video game I''ve ever seen. I''ve played games made by a single developer costing way less that had more polish than this deplorable borderline malware piece of shit product. Fuck you.', 'Mixed', 44.78, 57.40, 0.13);
INSERT INTO reviews VALUES (4576, 386360, 757, 'Great game, has a few glitches and crashes every now and then but overall a good game even after 1000+ hours of play I still have things to learn.', 'Another game ruined by the community. Blatant hacking with no consequences.', 'Mostly Positive', 78.20, 1571.28, 210.52);
INSERT INTO reviews VALUES (4581, 386480, 251, 'Would recommend game if it''s on sale, make periodic saves if you''re after all achievements so you can just load them so it''s easier to get without having to restart the game.', 'got boring really fast, the 3 hours are on background for the badges because i bought it in the summer sale and probably couldnt refund it anyway', 'Mixed', 61.75, 48.37, 3.05);
INSERT INTO reviews VALUES (4584, 386520, 144, 'I played this along time ago and it was one of my first COG game. I have since played multiples and it sits comfortably at my second favorite of all the games. The most important part of any of these games is the choices, and in this game the choices seem to matter, which is ironic considering the overall story being about choice or fate, freedom vs. force of will. For a game about fate, it never pushes you one way or another but allows you to make a choice, and in my playthrough came to a very ', 'Too many of the choices are just picking the same thing over and over again.', 'Very Positive', 85.42, 7.88, 0.28);
INSERT INTO reviews VALUES (4588, 386590, 725, 'I''ve had the game for a bit but just played it for the first time today. For some odd reason I feel like its thematically a bit like Icarus but instead of paying $1500 for 30 pieces of a game you get a condensed version of the experience in a $20 single package. You farm, grind and build on one main map and enter anamoly''s that seem to be temporary maps with extreme conditions, more resources and more powerful enemies. I haven''t played it much yet but if you like games that are full of skills, l', 'You claim you not making money or enough to matter, but you expect ppl to pay for something you have all but abandoned. If you were actually working on this game then ppl would be interested in playing, but they aren''t paying for a dead game. So if you wanna make money on it, then fix it and stop the lame excuses', 'Mixed', 49.52, 2.85, 3.00);
INSERT INTO reviews VALUES (4590, 386620, 1570, 'It''s a very fun rhythm game, probably the best of the series as it stands now.', 'CSD 2 is supposed to be the most balanced one between CSD and CSD 3. It have more food choices than CSD, and better customizations for the restaurants than CSD3. However, it also introduce the rigid, dreadful copper-silver-gold medal systems that put so much pressures on having a perfect day. The burger level had stumped me for months. I don''t know how to enjoy this game anymore.', 'Very Positive', 90.45, 96.88, 15.58);
INSERT INTO reviews VALUES (4595, 386700, 105, 'BEAUTIFUL ASS ART FOR A SUPER OBSCURE GAME ALWAYS REMEMBERED IT CAUSE OF THE NICE ASS COLOURS. STILL THINK ABOUT IT EVERY SO OFTEN GG OIL BLUE', 'I''m surprised that no one in the review section has mentioned that this game feels like a poorly ported tablet to PC game. Pixelated resolution / crap options menu, no key bindings, unnecessary mouse clicking, ''1 hour remaining'' message obscuring your way while your trying to play, setting speeds on the machine which reset every day (where the hell is the ''set to max speed'' button on here). This either needs patches or mods in order to make it an actual PC game.\n\nIf your going to play through th', 'Mostly Positive', 75.24, 5.68, 10.65);
INSERT INTO reviews VALUES (4598, 386770, 134, 'Great game, but not so great port. Recommended only IF you don''t mind not having in-depth graphics options, always requiring Internet Connection, and can snag it on sale for a good price. Otherwise, grab this on GOG if you want to play this in Offline Mode\nhttps://www.gog.com/game/caladrius_blaze\nhttps://www.pcgamingwiki.com/wiki/Caladrius_Blaze', 'I really dont care too much about the resolution being locked to 720p. what is a dealbreaker to me however, that the volume sliders are broken. The voice slider does absolutely nothing, instead the VA is tied to SE. Bullet/Shooting SFX is too loud and makes it hard to listen to the awesome BGM while playing. On the other hand voices will be too low if I lower SE in the options.\n\nSo yeah, i agree that this is a lazy PC port. It seems it only got updated once after release in 2017. I may check out', 'Mostly Positive', 79.10, 2.12, 0.95);
INSERT INTO reviews VALUES (4600, 386880, 1531, 'I swear this game is actually pretty good you get some alien monster motherfer called the rape come and rake you', '\r\nI never found "rake" but I lost 2 hours searching.\r\n', 'Mixed', 65.90, 3.48, 5.77);
INSERT INTO reviews VALUES (4615, 387290, 28829, 'So, I''ve bought this game a two days ago and never had THE TIME to actually play it.\nWell, I played it and ... I never thought I would cry so much. I wish I had played it earlier.\nI lost my 3-year-old at the begging of this year, and grieve hasn''t gone yet. I''ve been feeling very depressed and this game gave my heart such a warm hug that I can''t explain...\nThis is truly an art form. Loved the story even more.\nI watched the credits to the last person, and I''d like to say to each of them a very wa', 'If you like long sections of "make one mistake and then restart the entire level" this is the game is for you. each one of these run away sections is designed to make you fail until you memorize 30-40 obstacles that will all force a restart without any checkpoints. it results in spending hours to grind out one 10 minute level by forcing you to die hundreds of times until you do all 30-40 things perfect in a row.', 'Very Positive', 94.17, 4.53, 27.15);
INSERT INTO reviews VALUES (4616, 387370, 267, 'great game', 'Since the game is no longer being developed or supported at this time, i can''t recommend it. But, at $4 currently, it might be worth wasting a few bucks & couple of hours on. I lost interest in it after only playing for 17 hours.', 'Mixed', 66.29, 147.08, 17.75);
INSERT INTO reviews VALUES (4632, 387930, 130, 'Almost 10 years and this is the first game I bought it when I created and using Steam in 2016 \n\nI know this is worst game and nothing cool but it''s the memory about buying it', 'Extremely bad product.\r\nI do not recommend buying.\r\nno atmosphere, everything happens very slowly and boringly.\r\nThe only pluses are good wallpapers for the profile, for which I bought this game.', 'Mixed', 46.15, 3.83, 2.08);
INSERT INTO reviews VALUES (4634, 387990, 44605, 'i mean game is pretty fun but there being like 0 updates is very disappointing', '    Please do not be fooled by the recent physics update--the game is not being actively developed. The last dev log is from over two years ago, and during that time there has been zero communication from the developers on progress or plans for the next big update. The new features in the ''surprise'' patch address none of the crafting, combat, or progression issues that have been frustrating people since survival mode was added. This useless update will show the game as "Recently Updated" during ', 'Very Positive', 91.30, 9.03, 139.15);
INSERT INTO reviews VALUES (4638, 388060, 315, 'First of, the soundtrack for the first level is awesome.\n\nI like this more then teh base game. Wasn''t interested n escaping at all. Though playing a 2015 indie game in 2024 on a beast of a pc is prob underwhelming for me xD\n\nI like this game more then the original. Some don''t That''s fine\n\nZombies', 'The Escapists: The Walking Dead is a game that sounds like a cool idea at first—melding the prison escape mechanics of The Escapists with the zombie-filled world of The Walking Dead—but it turns out to be one of the weaker entries in the Escapists franchise. While the game retains the pixel art charm and offers some decent crafting mechanics, it falls flat in several key areas.\n\nOne of the biggest issues is the lack of freedom compared to the original Escapists. Instead of the open-ended, sandbo', 'Mixed', 56.83, 29.27, 4.47);
INSERT INTO reviews VALUES (4639, 388080, 2698, 'good app but paywalling dark mode is certainly one of the Decisions of all time', 'Barely Functions, the auto detect alone decides whether or not you get to use the application, I have to repeatedly reopen it, Has problems with infinitely loading and some applications refuse to work no matter what I do. \nJust use this instead: \n\nhttps://github.com/invcble/NoMoreBorder/releases/tag/v1.2.1', 'Very Positive', 82.84, 35.03, 35.12);
INSERT INTO reviews VALUES (4640, 388090, 7925, 'i came in my pants on my first jumpscare, highly reccomend. im also gay, unrelated', 'cant sex nightmare fredbear', 'Very Positive', 92.73, 1.88, 4.48);
INSERT INTO reviews VALUES (4643, 388210, 1882, 'Did you play this game back in the day? Sliding floppy disks into your 486 or similar? If the answer is yes, then you have to buy it.  Its an outstanding remaster, true to the original, updated just enough so as to not lose any of the charm.  My teenage brain definitely tackled the puzzles more effectively than my more logical adult brain! It was just as sniggeringly funny as it was the first time around, a proper nostalgia trip.  Maybe its time for Sam and Max next...', 'holy cow this is boring', 'Overwhelmingly Positive', 97.72, 13.02, 1.97);
INSERT INTO reviews VALUES (4648, 388320, 611, 'This game really captures the fervour of revolution. Even knowing how in real life ultimately all the hopes and dreams were crushed by religion it''s hard not to get involved and carried away by it while playing. That is indicative of good writing and masterful atmosphere that really captures and takes you back into that place and time. Voice acting is also top notch.\n\nGameplay-wise this is obviously inspired by the Telltale games but with even less gameplay, so if your looking for puzzles and ex', 'The "chapters" are 1-5 minutes of cinematics with a few QTE''s & choices; the playtime clocking in at less than 2 hours. The story feels incomplete as if they just stopped developing the story abruptly.\n\nRATING: 2/10', 'Mostly Positive', 76.76, 4.98, 3.78);
INSERT INTO reviews VALUES (4649, 388340, 264, '👍', 'Super Hipster Lumberjack is clearly advertised a person''s first game. I could have told you that, though. It''s a 2.5D platformer in an untextured world that feels like the result of someone just following an hour long Unity YouTube tutorial.\n\nAs a first game project, congratulations. However, it''s nowhere near a state that should be released to the public - let alone sold for any amount of money. Lots of polish, a few textures, and some gameplay variety would''ve gone a long way.', 'Mostly Positive', 79.92, 0.22, 0.10);
INSERT INTO reviews VALUES (4653, 388410, 4463, '!!!! BEFORE YOU PLAY THE GAME DOWNLOAD THE BETA VERSION BY RIGHT CLICKING GAME -> PROPERTIES -> BETAS -> publicbeta !!!!\nThis is important because the Deathinitive Edition has some bugs that get fixed by doing that (but it will still have some due to THQ being shut down back then and it was never FULLY fixed but the beta solves most of your issues)\nThat aside, this is one of the best games I have ever played if not the best.\nThe world design, the OST, the gameplay, it''s all nothing but incredibl', 'The game need''s some kind of update. \nThe game get''s stuck on the loading screen after you unpause or get out of the inventory screen', 'Mostly Positive', 75.22, 63.13, 0.37);
INSERT INTO reviews VALUES (4657, 388450, 189, 'If you like Match-3 games and the horror genre, you''ll probably enjoy this one. You can choose to play timed or untimed, and there are (I think) 100 levels in total, so it''ll take you some time to get through! There is a barebones story - there is an evil in town plaguing everyone, and you work your way through different locations to find and eventually get rid of it. Graphics and music are not bad, and the game has sufficient mechanics and bonus items to keep things interesting as the levels pr', 'Poorly made match 3\n\n- chains punish the player\n- power ups spawn randomly so there is 0 strategy possible other than starting a new save and not buying the bad ones.\n\nDo not buy if you''re looking for a decent match 3\n', 'Overwhelmingly Positive', 97.35, 13.62, 10.43);
INSERT INTO reviews VALUES (4663, 388620, 111, 'DungeonUp\n\nHas a total of 6 trading cards.', 'Way too many bugs! The game has a system to buy items using souls you get from defeating previous bosses yet you will encounter gamebreaking bugs for creative uses.\n\nIf you attempt to bypass the red door on 10th floor using any wall-destroying or teleport item it will get stuck there and you won''t be to fight the skeleton king or able to progress to the next floor!', 'Very Positive', 81.98, 1.37, 7.18);
INSERT INTO reviews VALUES (4668, 388750, 835, 'Very good, I liked it and my hand enjoyed it, but very hard to play with one hand :(', 'why do i keep buying these, i dont like fighting games.', 'Very Positive', 93.29, 15.18, 8.28);
INSERT INTO reviews VALUES (4669, 388800, 741, 'Azure Striker Gunvolt 1 is the beginning of a masterpiece of a series. However this version is not the same as the striker pack and lacks the resolution increases that the striker pack has. If you want to get into this series this game does the job but i don''t come back to this one even close to as often of its sequel. \n\nOverall great game just not my favorite way to play it. 7/10', 'Classic case of Inti PC Port. You''ll get a better experience just pirating the Switch Port on PC. Controller settings menu doesn''t let you save without specific Keyboard inputs, character portraits are still the native 3DS resolution and unnecessary pixelated, all menus use the Nintendo style AKA B=Confirm A=Back...\n\nJust many unnecessary things that turn a good game meh', 'Very Positive', 81.51, 11.25, 0.55);
INSERT INTO reviews VALUES (4673, 388880, 6632, 'Bought this game and played it multiple times on different platforms. Bought it on the huge sale going on right now to support the devs, and to write this review to encourage others to pick it up.', 'Do not support his developer anymore they are removing access to their games from itch.io. This includes being unable to download it if purchased prior to its removal. Yet to happen with steam but time will tell, this behaviour should not be tolerated.', 'Very Positive', 92.26, 0.12, 1.47);
INSERT INTO reviews VALUES (4678, 388980, 136, 'Great application for those who who want to make race tracks anytime anywhere and it is relatively straight forward to use. Would recommend', 'This is unfinished software, the developer now rambles about political topics on social media and doesn''t update the software. It''s not exactly cheap either. Avoid!', 'Mixed', 61.03, 22.83, 48.10);
INSERT INTO reviews VALUES (4680, 389050, 128, 'This game is nowhere near small enough to fit in my pocket 0/10', 'If they didn''t abandon this It would''ve been one of my favorite games\n\nIt''s just...unfinished...', 'Mostly Positive', 72.66, 70.18, 0.13);
INSERT INTO reviews VALUES (4684, 389220, 225, 'I used to watch youtbers play this game, now I can finally play this game after like 6 years :D', 'So many bugs, horrible controls, extremely short time limits, explosions that ignore your sound settings. Frustrating; not fun.', 'Mixed', 65.78, 0.45, 0.75);
INSERT INTO reviews VALUES (4693, 389510, 1413, 'This game is... unlike anything I''ve ever experienced. However, calling Wild Animal Racing a game is misleading, because it is far more than just any simple game. It is an art piece, which can truly compete with the works of famous artists such as Van Gogh, Leonardo Da Vinci and Salvador Dali, it showcases a great expertise in artistic expression. The characters (with exception of the communist hippo) are extremely compelling and have a striking appearance. The game, though taking place during t', 'When I played this game i felt like I was playing Forza Horizon. Amazing experience. Absolutely recommended. I lost 13 brain cells.', 'Overwhelmingly Positive', 95.05, 1.17, 12.47);
INSERT INTO reviews VALUES (4696, 389650, 125, 'Schmup bullet hell ahoy!\r\n\r\nI really enjoyed this for the few hours I played it. I was never able to beat it, though, the difficulty is a bit much for me, which was kind of disappointing.', 'Uninspired, generic, boring. \n\nBad visuals, bland music, aggressively mediocre combat and gameplay.\n\nAlso minor, but (of course) multiplayer is dead. Could''ve added AI team mates for game longevity.\n\nDisappointing over all.', 'Very Positive', 92.80, 13.40, 0.37);
INSERT INTO reviews VALUES (4697, 389670, 425, 'A high-quality anti-gravity racer akin to Wipeout! Really enjoy the progression, customization and career content. Worth full price.', 'Of course, visuals are stunning. Speed sensations are actual too in Pacer (ex-Formula Fusion).\nBut there''s no more support, no mods, no nothing to it anymore. Nobody plays online, no relevant activity on the Discord.\nI had fun for a couple of hours, then, at higher levels in campaign, gold medals are unobtainable. Because you have to kill 8 competitors in 5 minutes, which is more than 1.5 per minute, pretty high expectation. On tracks where you get ammunition too rarely, that''s frustrating. No s', 'Mostly Positive', 72.94, 8.15, 7.90);
INSERT INTO reviews VALUES (4700, 389700, 122, 'OMG favourite game ever 10/10!!!\n\nIts so good that i speedran it in only 15 min. With such complicated story I was left speechless!!!\n\nI loved the asmr in my left ear <3\n\n', '\nDisaster.\n', 'Mostly Negative', 30.33, 0.22, 4.12);
INSERT INTO reviews VALUES (4702, 389730, 29974, 'Just came back to Tekken7 after Tekken8 showed me what true disappointment looks like - and it feels like I’ve been upgraded to a real fighting game again.', 'Fun game, but not fun anymore when you have to pay to unlock characters. What happen to achievements to unlock characters or story progression. Happy got it on sale, but not paying for any dlc.', 'Very Positive', 91.10, 1356.15, 14.10);
INSERT INTO reviews VALUES (4705, 389900, 183, 'Pretty great game but making it work on Windows 10 is a hassle. Once you set it up tho, it works like a charm.', 'It has downloaded, but when play is clicked, it does nothing. How do you get it to play?\r\nIf it will not play, once again I want my money back. I love Hogs of War and this is very disappointing.', 'Mixed', 49.18, 6.00, 5.92);
INSERT INTO reviews VALUES (4709, 390030, 291, 'Hard to master but feels good to play. I''d say I''m average for reaction time in first person shooters and I still managed to complete it.\nThe setting(music and graphics) reminded me of Blood Dragon.', 'boring', 'Mostly Positive', 77.32, 10.83, 0.48);
INSERT INTO reviews VALUES (4716, 390290, 265, 'Such a twisted, peculiar little game that has sounds and imagery that will stick with you long after you''re done with the game. There''s just some highly inspiring art being displayed here and the dark, almost unhinged 90s cartoons aesthetic is truly like something out of Cartoon Network''s "What a Cartoon Show". \n\nOn a side note, Bulb Boy very much reminds me of another oddity from the late 90s which I really was fond of called "Nightmare Ned". That interactive kids title was also like a 90s cart', 'an interesting point and click adventure with a cool (and gross aesthetic). unfortunately, it comes with game breaking bugs. an item necessary to progress disappeared from my inventory and i couldn''t progress. I checked the forums, devs response is to delete save and try again. So i do, only for the same bug to occur earlier in the game with a different item. \n\ni know the game is short, probably 3 hours maximum. kind of the main reason i wanted to play this. but how many times am i going to have', 'Very Positive', 86.79, 6.13, 1.93);
INSERT INTO reviews VALUES (4717, 390310, 270, 'This game is truly incredible. I also played this game back then on Wii when I was still a kid. This is basically my childhood game and I am so glad that they have it now on Steam. I read the previous reviews saying it had lots of bugs and issues. Now I am playing at 2024, although I also had some issues but they were so minor it did not bother me much. I love how I am able to play this game now and understand the overall story. I think it''s still worth the pay. They''ll use it anyway to continuo', 'This port isn''t good which is a real shame since the game itself is a hidden gem, it''s as simple as that. Just play the Wii version.', 'Mixed', 63.33, 31.43, 2.30);
INSERT INTO reviews VALUES (4719, 390340, 484, 'This game is hilarious, you have to be in the right mindset to play, don''t expect the best game and don''t take it seriously and it is fun', 'This game, is like drinking orange juice and then brushing your teeth, the rest of the resident evil series is the orange juice,\nits good, nice as a morning beverage, and is a great source of vitamin D. this game, this is the toothpaste.', 'Mixed', 41.74, 0.27, 0.37);
INSERT INTO reviews VALUES (4722, 390520, 802, 'what a fking ni..', 'Do NOT go near any bridges in this game', 'Very Positive', 90.15, 13.95, 0.33);
INSERT INTO reviews VALUES (4724, 390560, 393, 'Until 7/21/20, the entirety of this game was behind a $30 paywall (which I paid), meaning that you had no access to any of this game''s content whatsoever without paying for it completely, regardless of how much of that content you intended to explore; with that, the complaints about some of the game''s features being behind a $20 paywall make little sense to me, but hopefully can be addressed in the future. Per the game itself, I very much like it and the online with crossplay is fantastic for th', 'Having to spend 20 dollars to play with your friends is absolutely ridiculous', 'Very Positive', 84.99, 52.58, 7.45);
INSERT INTO reviews VALUES (4726, 390610, 161, 'I think they''re supposed to be the circles of hell, or at the very least the endless cycle of suffering that makes me want to drop gaming as a whole', 'A pretty accurate Dante''s Inferno simulator, screaming of the damned  included.', 'Very Positive', 91.30, 9.30, 0.63);
INSERT INTO reviews VALUES (4727, 390660, 140, 'Short simple Madness clone, but has an overpowered intro cutscene', 'This game made me question the existence of steam''s quality control department.', 'Mostly Positive', 74.29, 0.52, 0.10);
INSERT INTO reviews VALUES (4729, 390720, 373, 'Close enough, hello 2025 america', 'missing gay robot sex', 'Very Positive', 92.49, 10.87, 0.70);
INSERT INTO reviews VALUES (4730, 390730, 159, 'easy is the normal mode.', 'It''s not a very good or well put together game.  I''m not expecting to steamroll everything but I can play Touhou on Lunatic difficulty, but I can''t even pass level 3 on Easy in Sora.  Between the too many guns to care, the inability to properly hit an enemy with a shot before they hit you, and the overall chunkiness and poor feeling of the controls, this is one bullet hell you should absolutely pass up.', 'Very Positive', 90.57, 5.92, 4.98);
INSERT INTO reviews VALUES (4737, 391000, 138, 'Used to play these games when I was a kid with my sister\r\nbringing back a lot of good memory''s from childhood', 'The game itself is fun, I''ve always liked the Farm Frenzy series, HOWEVER every single one of these games has something in every level that constantly flashes like I''m having a seizure at a disco. For example, the Viking game every time I click on the boat, the entire screen is constantly flashing until I close out of the boat. Do NOT buy until they fix this issue.', 'Very Positive', 94.20, 3.25, 3.32);
INSERT INTO reviews VALUES (4740, 391070, 359, 'Had a personal challenge for this game: Every time i died, i had to do 10 push ups, now i''m so ripped i can participate in the next Mr. Olympia.\n', 'Buggy demo ultrasimple spaceship shooter', 'Mostly Negative', 32.31, 4.18, 2.33);
INSERT INTO reviews VALUES (4742, 391140, 114, 'Got this game cheap from a badge coupon, thinking it''s one of those mid/bad games.\n\nI was positively surprised at how fun it is.\n\nIt''s easy to play but hard to master. At first, I found some of the weapons annoying, but after a while, I discovered that each has its unique playstyle and is fun overall.', 'At first glance I kinda liked this game. A unique backwards shoot em'' up. In order to keep moving you need to gain momentum from shooting enemies in a close proximity below you and use the explosion as forward force. Or fly over the green or blue boost pads along the level. You can also unlock a teleport ability to switch “lanes” quickly. This Movement mechanic was new and exciting... for about ten minutes.  Unresponsiveness become a problem as soon as I tried taking the game seriously. Infinite', 'Very Positive', 86.84, 6.48, 16.82);
INSERT INTO reviews VALUES (4748, 391220, 27643, 'Okay so first thing first... I''m totally biased towards the game, the "Tomb Raider" series has to be my favourite game series of all time. So we will talk about the pros first and of course there are few cons too, just one or two.\n\nPROS: This game''s atmosphere is stunning you know things are serious when everything is dark and serious kind of tone. The world building is amazing, when the game starts we are in Syria exploring a tomb which was perfect and then the snowy mountains where it became e', 'Rise of the Tomb Raider is a tragic example of a once-glorious franchise stumbling into the abyss of mediocrity, laden with QTEs that are as annoying as a swarm of pesky mosquitoes at a picnic. The game''s open world is as grindy as a teenager''s teeth on a piece of gum, stretching the player''s patience thinner than a cheap pair of tights.\n\nThe dialogue in this mess is about as deep as a puddle on a sidewalk after a light drizzle, with characters spouting off one-liners that make you cringe harder', 'Very Positive', 92.45, 40.45, 18.07);
INSERT INTO reviews VALUES (4751, 391260, 476, '⠀', 'I tried playing this game for 3 hours... Didn''t understand any form of story or direction... Monsters are overpowered in every area... They use stun or paralyze skills that don''t fade and kill you with chain attacks... I seriously tried to play through, but it''s crazy frustrating, items lower and raise skills but you don''t know till you buy them... Your skills you find don''t really add any impact to battle experience or do increased damage... Just a lazy effort.\n\nI appreciate the effort of makin', 'Mixed', 69.75, 5.38, 2.67);
INSERT INTO reviews VALUES (4753, 391280, 161, 'Doing some Steam roulette to clear out backlog. I did play this for like 30 mins when it came out, but haven''t touched it since. \n\nTried it out again after all these years and its ''ok''. Went through most of the bronze league, but found that I was severely wounded all the time and didn''t manage my status properly. I feel like the game is pretty mid, so it kind of depends on what you are looking for. Its a pretty basic management game which goes with the age of the game. I would probably have to p', 'This game has some great mechanics. Negotiating contracts for party members, gaining fame and competing against other agencies in the leagues. Balancing quests between factions. Lots of class types and skills, good research tree and some random events to test your RNG luck. \n\nAll of that however is overshadowed by how slow the combat is. Turned based combat is fine, but this game really slows that down. You have to click "end turn" after each action of each party member. Instead of just having i', 'Mixed', 60.25, 2.20, 1.18);
INSERT INTO reviews VALUES (4761, 391420, 185, '⠀', '\r\nAsteroids like game where you avoid getting into radar zone and navigate your way to the wormhole. Pretty bad if you ask me. Not recommended.\r\n', 'Mostly Positive', 72.43, 6.55, 3.83);
INSERT INTO reviews VALUES (4766, 391540, 137689, 'Funni skeletons and some weird animals 10/10 \nFlower bad >:(\nPlaying this game fills you with Determination', 'This game is horrible in pretty much every way possible.The story is bad,music is trash and the characters are extremely unlikable.10/10 would play again', 'Overwhelmingly Positive', 96.59, 709.07, 16.97);
INSERT INTO reviews VALUES (4775, 391720, 4935, 'I couldn''t really come up with much to say about this game besides that I got it on sale for 2 bucks and that''s about the right price anyone should pay for this. \n\nIt''s a psychological horror which isn''t particularly scary, the gameplay is repetitive and boring, and the puzzles can be solved without thinking unless you want to explore the multiple endings (at least I think it has multiple endings judging by the cheevos). On the other hand, I liked the story and visuals. \n\nHonestly, the game is o', 'I recently played Layers of Fear, and my experience was a mixed bag. While not terrible, I found it mostly dull, and what should have been a quick 4-hour playthrough stretched over several days.\r\nThe story, meant to be the game''s main hook, didn''t quite resonate with me. It felt underwhelming overall, though I have to admit the plot twist—especially near the ending—was well-executed and added some intrigue.\r\nOn the positive side, the puzzles were decent and kept me engaged at times. The walking ', 'Very Positive', 87.58, 2.93, 4.83);
INSERT INTO reviews VALUES (4776, 391730, 1543, 'I had bought this years ago and had difficulty playing due to lack of key binding options and my missing a limb. Ended up returning it. Happy to say that they have updated key bindings/accessibility and I''m able to play easily now! I don''t think I''m very far in yet but having a blast. The base building options are fun/cute, the hack/slash combat style paired with mob AOE makes you have to strategically move, and the snarky characters are great. Overall if you like this type of game I would recom', 'Screen shake is not possible to turn off. This was unfortunately unplayable for me.', 'Very Positive', 87.56, 19.58, 0.22);
INSERT INTO reviews VALUES (4782, 392000, 240, 'This is a pretty good game just after you beat all the levels the game kinda gets boring also s.t.e.a.m. please bring back tron evolution', 'It just doesnt run???', 'Very Positive', 80.00, 8.77, 0.42);
INSERT INTO reviews VALUES (4785, 392070, 115, 'very very epic and it has a great soundtrack', 'Pile of hot steaming uninspired garbage.\n', 'Very Positive', 84.35, 6.75, 0.42);
INSERT INTO reviews VALUES (4786, 392080, 323, 'I am personally enjoying the gameplay loop and the intricacy of the spaceship building system in this game. \n\nA word of caution though, game is still in early development, and the dev team is small so the updates roll at the pace you''d expect from a small studio.\nThat said, they are working actively on the game and are very active on discord and responding to player inquires when possible, so I am in full support of their endeavour.', 'I wanna like this game because it''s got a cool idea, but the walky-around bit is really cumbersome. And it assumes I''ve got a flashy gamy mouse because my missiles are bound to a button I do not have.', 'Mixed', 65.63, 94.72, 0.35);
INSERT INTO reviews VALUES (4788, 392110, 9070, 'This remains one of my all-time favorite turn-based strategy games. Indeed, one of my favorite games of all time. It''s got great gameplay, really deep interesting stories and characters that come out of the Endless universe, and incredibly good gameplay. Each faction has its own characteristics and encourages different play-styles and the mission system gives each play-through its own character and unique feel, not to mention an effective forward drive that makes it constantly playable. Also, th', 'As a years-running fan of 4X games, i do NOT recommend. The devs put a lot of heart and soul into the design of this game, but the game WAS made 8+ years ago and, i gotta say, whoever was given the reigns after the groundwork was laid? They let this game fall to the wayside. There are issues that could have EASILY been remedied from the start. My faction of choosing from the start, the "Vodyani" were very appealing for their style and Spiritual fanaticism. However, about the start of mid-game i ', 'Very Positive', 83.22, 566.23, 9.43);
INSERT INTO reviews VALUES (4794, 392280, 185, 'Will help you kill an hour or two. Some puzzles are clever, or make you feel clever. Some are meh. I got it for like a dollar or something and feel like I got my money''s worth. I wouldn''t buy it full price.', 'Please save your time and money. This is the first time I give this opinion in a review but that’s the conclusion I came to after trying the game twice.\r\n\r\nThe idea of a Franz Kafka Video game is a nice one and might deliver even in a simple game some interesting moments and hours of (maybe even intellectual stimulating) fun. But this game does not deliver this. In my personal opinion except for the name of the game and the protagonist named after him it has nothing to do with the famous author ', 'Mixed', 52.97, 2.20, 4.95);
INSERT INTO reviews VALUES (4800, 392580, 412, 'What a shame that the development was stopped, otherwise we could get a great twist of MOBA, RTS and TTS. Also the graphics is impressive for an old game', 'Great game and ambitious, incredibly made by one guy.\n\nBut performance is so terrible, maybe because the game is old, I don''t know. But I legit couldn''t play past an hour or so, my eyes were killing me with all the screen tearing, fps drops and more.', 'Mixed', 66.50, 1.12, 0.82);
INSERT INTO reviews VALUES (4812, 392970, 134, 'This playthrough took me 7.5 hours on advanced mode for both main game and bonus chapter.  You are Laura, an investigative journalist, who is a well manicured female whose hair is never out of place even after climbing a tower!!  You are sent to investigate a series of murders where only a pile of ash remains at the crime scene.\nThere is a supernatural feel to this game, but all is not as it seems!  I felt the story ran out of steam and fell rather flat at the end.  It felt as if the devs didn''t', 'Like another reviewer, I''m having problems with the game forgetting my save point.  I had completed the main game a few days ago and exited the game without starting the bonus game.  When I started the game today, I couldn''t play the bonus game because it was loading from a save point about 20-30 minutes before the end of the main game (including loss of the achievements I had earned after that point in the game).  Since it wasn''t that far back, I decided to play through and finish the main game', 'Very Positive', 90.30, 7.48, 9.28);
INSERT INTO reviews VALUES (4813, 393080, 5840, 'Activision are slimey asf with the cease and desist of the H2M mod after the steam sale had passed. Even after many of us put in hours which exceeds the refund period, they knew what they were doing with shutting down the entire operation.', 'Only bought this game for the mod, and the crap I had to do in order to get the base game to run was ridiculous. \n\nYou shouldn''t be selling a game that I need to boot up in safe mode just to turn off settings and get it to run.\n\nEdit: They pulled the plug on the only thing that we were looking forward to. Fuck these scumbags.', 'Mostly Negative', 39.79, 26.77, 0.35);
INSERT INTO reviews VALUES (4816, 393200, 441, 'This game makes you philosophical, when you see a Jebus rat making a ball clip through the walls to trigger a suicide vest of a politically correct rat, making the ball fly to the sky to be picked up by a tractor beam of a pope rat, pulling the ball into the goalpost that triggers a nuke to be dropped onto a cat.', 'It''s better than the first game and that''s a problem, it actually functions which is not what I wanted', 'Very Positive', 82.31, 6.90, 12.05);
INSERT INTO reviews VALUES (4825, 393380, 77760, 'honestly one of my favorite star wars games, and the devs even threw in a little mini game called squad to boot! 10/10', 'Squad is a labor of love.\n\nWhat I mean by that, is that no other game that I am aware of comes even close to the level of play-ability, practicality, and unique game play that can be experienced on this game. I have had moments with friends that exceeded excitement beyond any FPS i have ever played, or action/military movie I have ever watched. There is a role, and way to play for everyone out there in this game.\n\nSquads largest folly, and reason you must know before buying is the community. Squ', 'Very Positive', 85.92, 74.75, 915.93);
INSERT INTO reviews VALUES (4827, 393420, 4721, 'a cheater can remove all entities wow such a good game', 'Unfortunately the game is dead.', 'Mixed', 62.83, 518.02, 48.33);
INSERT INTO reviews VALUES (4828, 393430, 229, 'Like Pro Pilkki but with better graphics and few other extras. Not forgetting the VR support which is really fun. If you like ice fishing, highly recommended. Better with friend than alone.', 'No more updates!.. sad', 'Very Positive', 87.77, 13.23, 11.33);
INSERT INTO reviews VALUES (4830, 393520, 1985, 'I wish there was a neutral or mixed option, because there''s plenty I liked and disliked here. There''s great visuals and music, the platforming and puzzling is solid, and the story, while somewhat confusing and escalating in stakes very rapidly, is at least  rousing you with it as it unfolds.\n\nBut the game forgets halfway through that it''s supposed to be a metroidvania and stops giving any new abilities, the combat ranges from meh to bad, and most of the bosses have annoying gimmicks and poor tel', 'Nice for a one time play through, but  the game does not give proper explanation of what mechanics do or gives enough movement speed to clear some obstacles. Also in no way is this game suitable for teenagers. The themes and visuals are very heavy. With that being paired with the cartoony visuals, any parent looking to purchase this for their child may find them coming to them traumatized.', 'Very Positive', 84.13, 12.32, 26.37);
INSERT INTO reviews VALUES (4836, 393750, 119, 'it is a good puzzle game', 'I played this through some years ago. Now I thought I''d play it again, but I can''t get the controller to work properly with it in Windows 11. I guess I could use keyboard and mouse, but this wasn''t interesting enough to suffer the joint pain.', 'Mixed', 67.23, 3.38, 8.07);
INSERT INTO reviews VALUES (4842, 393920, 140, 'I love this game. Layout is fantastic, game is as well. It does take a little while to get used to the pricing. But it is still tons of fun. No play through is the same. I keep coming back to it!', 'This is first game I have every requested a refund on in steam. I have recent game I dont care for, but I just figure my fault. This game is really simple and boring. You just click a button and watch entire day go by with no way to intereact with the customers. I would think you have sales people bringing you people wanting to haggle down price of cars etc etc, but instead it just jushes you through day with no abilitiy to make any managment decisions. Which is really disapointing for game with', 'Mixed', 50.00, 57.22, 0.42);
INSERT INTO reviews VALUES (4844, 393980, 201, 'Its not to bad for the price.\n\nThe game also has a very nice BGM, wish they would sell a soundtrack for it', 'The Mahjohng part of the game is cool and engaging...other than that. Can''t really give the game much praise in their whole ''Hentai sells'' perspective (If you wanted to be all crank''d up I''d preffer Hunie Pop).  Nothing special about this game, but if you''re really bored...find something els to play, unless you just have $$$ to burn.', 'Very Positive', 85.07, 2.35, 1.50);
INSERT INTO reviews VALUES (4849, 394160, 528, 'What are you looking at reviews for this game??? Have you never heard of Pac-Man???', 'Controls are so bad, the game is barely playable.', 'Very Positive', 89.02, 1.55, 1.28);
INSERT INTO reviews VALUES (4850, 394220, 113, 'its harb', 'Hard. Not hard in the sense that it''s difficult like getting over it. Hard in the sense that it''s just straight up unfair.', 'Very Positive', 84.07, 7.18, 0.22);
INSERT INTO reviews VALUES (4855, 394310, 3388, 'An interesting game for one playthrough.', 'It seems you can''t speed up dialogues or cutscenes, you can''t increase the speed you walk. this gets extremely frustrating. \nApparently a design choice because the game is rather short and reading these VERY SLOW textboxes make up a large part of the game.\nThe fights also seems to be heavily dependent on RNG, random dice rolls.\nI don''t recommend this game', 'Mostly Positive', 72.90, 12.80, 1.72);
INSERT INTO reviews VALUES (4860, 394510, 9593, 'Pretty good game, they should make a second one. Make it 3rd person instead of top down. They could call it something like Helldivers: Back 2 Hell, or maybe just Helldivers 2. I bet it''d have huge potential.', 'Every button you press could be a disaster. If you trust your teammates, you’re already dead. If you trust yourself, you’re also dead. \n\nThis game isn''t for me. At first, it’s chaotic fun but this gets boring over time. Even if this game was free, I still wouldn’t keep it in my library. I’d rather "democracy" my way into uninstalling it.', 'Very Positive', 91.63, 10.68, 0.43);
INSERT INTO reviews VALUES (4861, 394540, 196, 'Cute classic game. Double jumps, guns, aliens and conspiracies. Has a big exploration component that will turn you into an intrepid space adventurer.', 'I was having fun with this game until I got to the third boss. It''s just way too hard even on normal mode. The save point is way too far away from the fight. Having be chased by lava while getting shot at while you climb to the top just to get unloaded on the moment you get there is just too much. I don''t play games like this to have to be perfect, I need some help, like some health packs that aren''t insanely expensive, or just some check points right before a boss.\r\n\r\nEither way, the fun was su', 'Mostly Positive', 73.47, 2.88, 1.30);
INSERT INTO reviews VALUES (4863, 394600, 179, 'Wow I didn''t expected the game to be THIS short, after learning for a bit it''s not that hard either. Could complete all Achievement in one sitting if skilled enough.\n\nIf you can get it for free or ultra dirt cheap in sales (Which the full price already is) you can give it a try', 'As a Gunvolt fan...no. Skip this. It was nice seeing Stratos again, he made me smile, nothing else did. The game is really easy most of the time, except for a few bosses with cheap attack patterns that aren''t super well telegraphed (looking at you, Brandish), and it also does nothing really interesting with its stages, making it easy to lose the attention of the player. This isn''t so bad since the game is super short so it would be reasonably inoffensive to have a brief, non-challenging experien', 'Mostly Positive', 73.74, 2.27, 2.13);
INSERT INTO reviews VALUES (4864, 394690, 9985, 'great casual game. kind of like the original VR chat. you can be whatever you want and play how you want. lots of minigames and you can create your own home if you want. i made a home theater specifically to watch gundam in.', 'Fun idea but the social element is really bad. Players are very very often needlessly hostile and/or clique-ey. My advice is to ignore this aspect of the game and play it purely either for the mini-games or with your own friends that you know personally. This is a pretty major caveat considering interacting with the community is an instrumental part of the game''s feature set. The mini-games are decently fun and so is the condo-building but the community is just really bad', 'Very Positive', 90.28, 29.77, 61.60);
INSERT INTO reviews VALUES (4867, 394760, 900, 'Shout out to the golden era of iOS gaming 2010-2018. For years, I ditched PC gaming for mobile gaming, and this series was one of my go-to mobile games. It''s corny as hell, but it scratches the right itch for zombie infested space shooters, loot collecting, log reading story telling (system shock), etc. It has several game modes and difficulties. For the era it came out in, the visuals worked.', 'Dead effect 2 Is best described as killing floor 2 meets borderlands style sci-fi looter shooter. It''s one of those ios/mobile ports that out stays it''s welcome 10 hours in. Be prepared to vigorously smash your spacebar to open lockers....lol. Runs under unity engine with an art style that mimics killing floor 2''s unreal engine 3. DE 2 suffers from the odd indie jank moment/freeze up. Stuffed with a metric ton of grinding achievements, as you would expect from a mobile port. Better options out t', 'Mostly Positive', 74.56, 4.17, 87.72);
INSERT INTO reviews VALUES (4870, 394850, 117, 'Had hundreds hours of fun playing this with my brother. Still playing every now and then till this day.\nMy favorite landfall game.', 'game is not good', 'Very Positive', 80.34, 3.38, 0.18);
INSERT INTO reviews VALUES (4871, 394870, 285, '⠀', 'Worst broken unpolished, shitty control mess ive ever played... and i''ve played Elmo''s Letter Adventure...', 'Mostly Positive', 73.68, 4.65, 0.15);
INSERT INTO reviews VALUES (4873, 394970, 3114, 'this game is like a burger, if burgers were made of\n- great challenging gameplay\n- great story\n- great mood/vibes\n- amazing music\n\na quality hopoo game <3', 'Too difficult to be fun.  Its not like its challenging difficult, just annoying.  Tons of little things compound into one huge mound of shit.  Good music.', 'Overwhelmingly Positive', 95.54, 1.63, 4.22);
INSERT INTO reviews VALUES (4878, 395160, 177, 'Simple platformer with +- 3 hours of gameplay. \nOf course it is very similar to L-game, but it is less atmospheric and complicated(and feels MUCH cheaper). I think it will be good to play somewhere in the plane\\train, where you do not really need to feel the atmosphere of the game. Music is decent sometimes, like ob levels after the snowy ones and one with the minecart. Talking about minecarts, floor with the railways is really bugged, so I had to restart this level multiple times. There are als', 'Normally i let games stand on their own merit but in some cases you have to adress the elephant in the room. Limbo was a massively influential title at the time, it still is in some ways although INSIDE has overshadowed it nowadays. Still though, the fact remains that following Limbo''s success an influx of games came to be trying to ride this wave. At best adding their own unique spin or at worst, as is the case with this game, copy it without understanding what made Limbo so great in the first ', 'Mixed', 53.11, 3.10, 2.47);
INSERT INTO reviews VALUES (4879, 395170, 1196, 'Cheap in "price" but better than most of expensive games released nowadays! Amazing story, Amazing music and an amazing ending 😭', 'A moral of the story that has already been shouted at you on the store page, before you even play the game, and still it has to tell you the moral of the story once you''ve played for a few minutes. Less trust in the audience to figure out the message than stuff made explicitly for small children.', 'Very Positive', 89.97, 4.62, 0.13);
INSERT INTO reviews VALUES (4881, 395200, 1118, 'I remember when I was a young little boy, always hopping on to youtube to watch people play this game. Now I''m here, finally getting the chance to play a quick yet stunning masterpiece. I''d like to thank my grandmother for giving me the chance to play this game', 'Game cant run on modern hardware let alone a steamdeck the game came out in 2015 how in the hell is it this badly optimized almost 10 years later garbage game engine', 'Very Positive', 81.22, 9.37, 0.62);
INSERT INTO reviews VALUES (4883, 395270, 310, 'Life is a grinding machine indeed.', 'A Wolf In Autumn is a short psychological horror game with a setting judging by the developer''s own early steps in creating games. You find yourself in the mind of a child trapped in a cage of trauma and confusion from the start. Although the story has a formality and narrative that is interesting to appreciate, the mechanics are a little grating. The atmosphere tries to be fearful at a certain point but often fails in its shades. It''s a game that I''d question positively or negatively, but in vi', 'Mostly Positive', 76.45, 1.52, 4.33);
INSERT INTO reviews VALUES (4885, 395350, 194, 'Spent 10 minutes lost in an office building\n\n10/10 just like real life', 'ISN''T BACON FUCKING HILARIOUS, I MEAN IT''S SUPER INTERESTING AND FUNNYLLOLOLLOLOLOLLLOOL. But seriously, this game is repetitive, and has no replay value whatsoever, except for achievements.', 'Mixed', 60.31, 1.07, 0.97);
INSERT INTO reviews VALUES (4892, 395500, 153, 'Really short metroidvania. Didn''t really expect much but I''d say it delivered. If you think otherwise you can probably complete the game and still be able to refund using Steam''s 2 hour refund policy.', 'Rot Gut - a simplistic side-scrolling shoot''em up set in a greyscale pixelated film-noir city - is a game I cannot recommend, even for its low asking price ($1.69 USD was my ticket to entry at the time of writing). It''s insultingly brief and unbelievably easy. Usually, I won''t bother with writing a review for a game unless I''ve put a significant amount of time into it (100 or more hours) or have unlocked every achievement, which normally requires a great deal of time and effort. However, it took', 'Very Positive', 86.93, 0.43, 0.35);
INSERT INTO reviews VALUES (4896, 395570, 332, 'Nice tactical puzzle while there is just one character under control. Become a mess when there are two.I cannot handle two at the same time. Never saw third dwarf and probably never will. Still recommending.', 'Not even worth the $1 I paid!  The controls are horrible!  You have to use a controller!', 'Mixed', 65.96, 6.72, 0.13);
INSERT INTO reviews VALUES (4899, 395620, 216, 'dark souls joke', 'Fun, a little bit repetitive, optional caves on the world map do not pose much difficulty (some puzzle can be tough though). Dungeons are very similar. Navigating the map can be confusing (ok, but some parts are confusing as if designed for confusing the player).\nCombat can be difficult. So I switched to easy mode (an in-game option). So NO combat is difficult now (just mashing attack button will do it, generally). Except that the final boss combat which is still too difficult. There is no very ', 'Very Positive', 86.11, 7.13, 15.47);
INSERT INTO reviews VALUES (4903, 395860, 127, 'Except for the awkward voice acting at points and a few annoying puzzles, I stayed for the sweet story. Highly recommend this gem.', 'Painful voice acting (with the voice actor reading a typo aloud - how do you even manage that?) and gameplay more focused on solving obtuse puzzles rather than the usual even mix between HO scenes and mini games. Not as enjoyable as I''d hoped. Get it cheap or watch an LP if you like HOGs.', 'Mostly Positive', 77.17, 4.67, 0.38);
INSERT INTO reviews VALUES (4906, 395900, 138, 'I just started playing Backgammon Blitz and so far I like it very much. I am going to start using some of the features that apply to the game. I think it be very benefitial to the game. I love the game of Backgammon.', 'Very complex to run for such a simple game. The steps I need to take to play online with friends are just confusing and it almost always crashes mid game. Not recommending.', 'Mixed', 53.62, 7.45, 1.42);
INSERT INTO reviews VALUES (4915, 396090, 160, 'First time playing, everyone loved me but the libruls. The the UN got pissy with me over some environemental shit. Made the huge mistake of letting in refugees and ask UN for moneybecause EVERYONE hated that, I was hoping to get friendly with the nation of the refugees as well as scoring free cash from UN. After this everything went downhill, everyone hates me, tax was raised to 55% from 13% to cover expenses. Ive lost all popular support and im just sitting in my office waiting to get assassina', 'I''ve went back and forth on deciding whether to up or downvote this game and I have decided to downvote. The reason for my downvote is simple, after a couple play throughs you realize the game lacks depth. I have failed in only my first play through and then scored over 900 on all play throughs afterward. Did I just magically become a genius? No, it is because I found the trick to succeeding every single time. I of course ignored this flaw because I thought the developers were going to continue ', 'Mostly Positive', 71.25, 9.68, 8.73);
INSERT INTO reviews VALUES (4916, 396160, 312, '⠀', '\nRPG maker inbound!\n', 'Mostly Negative', 36.22, 6.73, 4.63);
INSERT INTO reviews VALUES (4917, 396230, 148, 'This novel was a fantastic read for anyone who enjoys alot of backstory ,which will keep you hooked for hours. I would like to see the rest of the books to come out as there are so many questions i am dieing to find an answer to.', 'I found this game to be interesting up to the point where they bagan to charge additaonal cash for opening more powers or content in the game play.  SO the base price you pay for this interactive story is NOT all you have to pay for for the entire experiance. SOME warning would be nice, before purchasing what I thought was a compleate game. Thought I should post this so some people could know.', 'Mostly Positive', 79.05, 8.40, 19.88);
INSERT INTO reviews VALUES (4920, 396310, 287, 'One more game that I will never recommend to anyone.', 'It''s a nice artwork, but I can''t really count it as a game. There''s really only one riddle appearing in this whole "game", the story is finished after 3 hours (I''ve wasted a bit more time with trying out unnecessary things) and it would have disappointed me even more if I would have paid the full price for it. So if you wish to pay for a short story-time, go ahead! But if you are looking for a game, then better check for something else. The fact that the confusing game-bug is still not removed y', 'Very Positive', 82.58, 1.90, 3.93);
INSERT INTO reviews VALUES (4922, 396350, 357, 'Twin shooter with nice simple graphics.\n\nGood:\nBosses are very good and there is a lot of them.\n\nBad:\nThis kind of controls are difficult to master.', 'It''s too short i''m afraid. 61 min. and you will have beaten the game. There are some unlocks that give you reason to go back through. The story is shallow. The gamelpay is the one thing that is just fun though.', 'Overwhelmingly Positive', 96.36, 5.30, 1.02);
INSERT INTO reviews VALUES (4925, 396480, 562, 'Great game, just wish you could turn off the flash when jumping/arriving to the next system.\nI think I may prefer this over FTL, tough call.\n\nEDIT:  OMG THERE IS AN OPTION!!!  You just need to scroll down in the settings.', 'A game where to play, you have to grind for a better starting ship, for HOURS (and it''s not exagerated), by just dying over and over on hard mode. The dev took the time to fix the amount of XP you get by doing that (reducing it), but never balanced anything else to make the game enjoyable from the start.\nThere is no knowledge diff as usually in roguelikes.\nFrom what I understood, it''s a game developped for mobiles at first, but the dev didn''t care to balance it for pc.\n\nSo, don''t waste your time', 'Mostly Positive', 78.29, 24.05, 2.53);
INSERT INTO reviews VALUES (4929, 396640, 252, 'it deserves way more players than it gets', '"Spelunky is one of my favorite video games. I would love to see a version of Spelunky with wider branches, more action, and crazier mechanics."\n\nThe Monkey''s Paw listened, and the finger curled.\n\nThere''s an amazing game under the hood here that I''ll never get to play because of the frustratingly clunky controls.\n\nThis is not "clunky because the mechanics are unique and the movement takes time for adjustment".\n\nThis is "I know exactly what I want my character to do, but the controls defy all int', 'Very Positive', 89.29, 60.98, 1.47);
INSERT INTO reviews VALUES (4930, 396650, 1222, 'This was one of the first visual novels I ever played and it basically spoiled me for the rest of the genre. Play it. It''s great.', 'not very good but not terrible\n', 'Overwhelmingly Positive', 95.09, 11.67, 2.57);
INSERT INTO reviews VALUES (4933, 396710, 617, 'Great game. The music and visuals are phenomenal and the game feels great, if your using a controller that is. The combat is simple but it doesn''t need to be too complex. The stages are fun but they drag on for a little too long. The art style is one of the best parts of the game. I do have to say, some of the collectibles are too easy to get, and some are easier to get than actually beating that part of the level. Also, the game is way too easy up until world 4, where there is a noticeable diff', 'The gameplay is painfully simple, from shallow button-mashing combat to barebones platforming with lacking variety in both level design and enemy types. Coupled with the long-winded levels, this makes the game a dull experience that overstays its welcome by the time you''re midway through the game. I''ve also gotten softlocked/stuck a few times during levels and was forced to restart.', 'Very Positive', 94.33, 13.92, 13.77);
INSERT INTO reviews VALUES (4935, 396750, 4920, 'Game definitely worth taking a flyer on for a buck fifty... the whole galaxy is your shooting gallery!', 'There are only three ships for you to choose from, and most of your runs will be exactly the same. There is practically no enemy variety, with about 4 common enemy types and likewise almost no weapon variety. This lack of variety makes the game grow quickly repetitive and boring as all your runs will end up being exactly the same. Would only recommend if *heavily* discounted.', 'Mostly Positive', 77.95, 3.17, 7.35);
INSERT INTO reviews VALUES (4936, 396790, 311, 'Dracula''s Legacy\n\nHas a total of 5 trading cards.', 'Glitchy puzzle game with outdated visuals, mediocre voice acting and inconsistent puzzles', 'Mostly Positive', 74.28, 0.70, 2.07);
INSERT INTO reviews VALUES (4937, 396800, 118, '12 Labours of Hercules IV: Mother Nature (Platinum Edition)\n\nHas a total of 7 trading cards.', 'It''s a waste of time with boring, unpolished gameplay and a shallow plot — repetitive and uninspired.', 'Very Positive', 87.29, 0.52, 2.57);
INSERT INTO reviews VALUES (4940, 396860, 158, 'It was an enjoyable story that provided some insight into North America''s history and Native American culture. The narrative was brief, which limited character development, and there were no choices to make throughout the game. The visuals were nice. Overall, it was a solid visual novel.', 'Sometimes you get to the end of a story and think - what was the point?', 'Very Positive', 85.44, 6.88, 3.25);
INSERT INTO reviews VALUES (4942, 396900, 2125, '2 minute TLDR:\r\n\r\nGrip is a ton of fun, for people who are fans of the old Rollcage series. While not perfectly polished, the little snags the game does have don''t massively hold it back from being enjoyable alone or with friends.', 'good concept, failed execution. the idea of a game where the track seemingly has no boundaries and you can flip, invert and tumble your vehicle as you race with an array of weapons can be appealing to the eye at first, but after playing a couple of races it just feels like that''s all i''m doing; flipping, inverting and tumbling with no sense of direction. so yeah...not my cup of tea.\n\nI commend the concept though. It reminds me of those R/C cars that can flip and invert and keep riding. Taking th', 'Very Positive', 87.67, 62.77, 0.27);
INSERT INTO reviews VALUES (4946, 397060, 734, 'This is one of the best games I''ve had the pleasure of playing. I don''t say that often and love the experience. Thanks so much to the developers and the human beings I''ve had the pleasure to play with. The experience is so detailed and immersive that it reminds me of the 90''s playing magic the gathering. I have to give this game my highest recommendation if you love card games or chess. It''s awesome!', 'Paid product AND in-game pay-time purchases. I hate developers like these', 'Very Positive', 83.79, 1154.98, 5.08);
INSERT INTO reviews VALUES (4949, 397150, 181, 'fun', 'game was shit when i played it and the dev thought wayyy to highly of themselves. the game was never ready for EA and because of one persons greed 16 "devs" lost their jobs. They continued to sell this game after development halted for over a year. So glad i saw the "cliff ahead" sign and jumped ship.', 'Mixed', 59.12, 106.87, 0.27);
INSERT INTO reviews VALUES (4950, 397160, 193, 'This game is an absolute hidden gem. If you''re looking for a long RPG with persistent characters and levels that stay with you, try this out. It''s genuinely fantastic. It also has a civilization style ''age advancement'' as the campaign or the missions progress. \n\n The only downsides with it is there appears to be a memory leak after a few hours that causes maps to run sorta bluh but you can quit and finish easily. The game also seems weirdly choppy when characters move, and if a sequel is made it', 'Developer abandoned the game, and until that changes this will be a hard no for me.', 'Very Positive', 81.35, 86.53, 29.45);
INSERT INTO reviews VALUES (4956, 397270, 339, 'I love gay women bc I''m a gay woman, I gotta go read more sonohana now I think this is the start of a new hyperfixation. Shame this is the only one on Steam.', '（The English translation is generated directly by machine from Chinese text (excluding some plot information), which may be completely unreadable. Those interested in a high-quality English translation are welcome to provide a retranslation） 以“爱”为名的权力暴力。所谓的“爱”只是上位者践踏边界、物化伴侣的工具。不建议普通百合作品爱好者及女同玩。\n不是纯爱战士的人可以忽略这条评价。据说steam版本删去了大量内容，剧情有缺失，仅从我看到的steam汉语版本进行评价，可能会和原始完整版的内容有区别，对于别的版本不予评价，婉拒别的版本玩家指点。\n　　全篇插叙，开头讲了两名女主角相遇一周年已经谈恋爱很久之后在学校里散步的场景 ，中间 是回忆 ，结尾是 女主角们在房间里的场景。 \n　　开头：公共空间的权力暴力，所谓的“爱”需要依靠践踏对方的尊严来证明\n虽然', 'Very Positive', 89.38, 2.78, 8.78);
INSERT INTO reviews VALUES (4959, 397330, 154, 'I''ve played the second game before, cause it was the only one that came to Brazil at the time. I had the oportunity to play this one years later. Somethings were strange about the gameplay but this revamp they gave was really good. Loved it a lot. ♥', 'I just can''t recommend LBA these days. While many will remember it fondly, and there is certainly nostalgia value in playing it again now, there''s just so much wrong with it. Wonky controls with an isometric camera, constraints around field of view, static camera placement and resolution, to say nothing of the technical limitations of the time in way of audio and visuals. Wonky animations and a bizarre focus on combat with a magic ball that requires accurate throws without the visual cues needed', 'Very Positive', 86.36, 32.83, 11.75);
INSERT INTO reviews VALUES (4960, 397350, 1137, 'If you are here, you already know about this badass classic.', 'You have to hope that by luck you avoid natural disasters long enough to get started, then odds are you simply get overwhelmed by the enemy.  No strategy whatsoever.  The battle scenes are impossible to control, and the game speed settings are either way to fast or painfully slow.', 'Overwhelmingly Positive', 96.48, 41.07, 4.18);
INSERT INTO reviews VALUES (4962, 397390, 197, 'Great deck builder!!', 'The game is a buggy mess that creates more frustration then it does enjoyment. Its built like rogue-like, so the bugs are compounded by game design that basically comes down to rng. Some strategy can be used but for the most part a run can fall apart fast, and then it dies a slow, boring death.', 'Mixed', 69.54, 28.40, 3.25);
INSERT INTO reviews VALUES (4965, 397430, 908, 'any intelligence i have today is the result of zoombinis for the cd-rom', 'I really wanted to enjoy this remake, I''m a fan of the original game that I played as a child. However, this game lacks basic options like volume control (between SFX and Music), no graphics options (I was getting some screen tearing) and the game is missing some sound effects for the zoombinis movements, which becomes apparent and annoying at the very first puzzle. The fact this hasn''t been corrected since 2015 is frustrating and disappointing. And for that, I say play the original.', 'Very Positive', 94.27, 21.80, 0.30);
INSERT INTO reviews VALUES (4967, 397460, 1272, 'Highly recommend this game. We played this pack during a family gathering, and the grandparents enjoyed themselves.', 'not horny :(\n', 'Overwhelmingly Positive', 95.83, 3.67, 5.75);
INSERT INTO reviews VALUES (4968, 397500, 197, '⠀', 'I dunno, the story is just boring but I like the 2d graphics of it though.', 'Mostly Positive', 70.56, 5.30, 0.08);
INSERT INTO reviews VALUES (4969, 397540, 56118, 'Amazing game if you skip cutscenes and mute the story cause it''s cringe', 'This game has become a spyware, do not install it or accept the EULA agreement, if you want to play... the seas are the best option sailor', 'Very Positive', 81.63, 75.73, 7.38);
INSERT INTO reviews VALUES (4978, 397950, 9217, 'This game is just simply good. Some levels are a bit tedious but other than that, pretty fun game! :D', 'awful progression, one level could be impossible, and then the next could be child difficulty', 'Very Positive', 93.72, 330.47, 11.78);
INSERT INTO reviews VALUES (4982, 398000, 313, 'This is the first video game I ever played in my life, I can''t say in words how much I love this game and how many times I played it.... Everytime I want to jump back in to my chiildhood I play it and it"s always a great time! I''ll never get tired of this game, it is timeless!', 'awful controls. awful camera controls. awful puzzles, its just all so obnoxious. watch the longplay of this game instead, because otherwise you just gonna suffer', 'Overwhelmingly Positive', 98.72, 17.83, 0.73);
INSERT INTO reviews VALUES (4983, 399810, 4439, 'I write this review because of a noticeable group of people who played this game expecting more action into it. This is supposed to be an first person RPG and not a FPS, focused almost exclusively to the story; no side stories and limited exploration. Think of this as an Immersive Visual Novel with choice making for the endings with a 3h playthrough in average definitely worth the play.', 'Let me be clear that this review has nothing to do with the gameplay of this game, it''s the lack there of and the fact that I can''t play it at all. I''m running a RTX4090, i9 13900K, and 64 GB of ram. Way above specs listed and yet it''s usually crashing before I even start a new game. It crashes when I look at the settings that were set to auto and it crashes on the lowest possible settings. The furthest I''ve seen is the opening text of a new game file.', 'Mostly Positive', 76.50, 23.97, 0.25);
INSERT INTO reviews VALUES (4984, 400250, 180, 'after playing for approximately 4 minutes i understand now that this is the only game i will ever play for the rest of my life.  the multiplayer aspect of this game is just amazing. you can race your friends from one side of the island to another, and it gets really competitive at times because no one knows who won since everyone is floating blue balls. hopefully they release a patch to track our competitive progress in a ranking ladder system!\n\n10/10 masterpiece', '\nAnother relaxing experience where you wander around aimlessly losing your precious time. You don''t have to play it though.\n', 'Mixed', 50.56, 0.22, 6.52);
INSERT INTO reviews VALUES (4985, 400510, 116, '⠀', 'It took me less than five minutes to discover the true potential of this game. The horrible voice acting and annoying VCR style overlay really made this feel authentic. The poor animation made the enies truly terrifying. And nothing was scarier than the horribly recorded sound effects used. Truly a masterpiece of this age.\n\nIn all seriousness, I used a coupon and got this for less than a dollar, and I would have rather used that money to purchase Necco Wafers.', 'Mixed', 51.72, 3.00, 1.03);
INSERT INTO reviews VALUES (4988, 400580, 216, 'Really engrossing atmosphere and some of the routes blew me away, the mechanics are interesting but made the replaying ultimately tedious, detracting a bit from the drive to explore some really great narrative. (Time played not accurate, probably spent a day idle)', 'I bought it because I was wanted to play a tactical mystery game, but after a while Black Closet felt like a lesbian dating simulator...', 'Very Positive', 91.20, 31.08, 25.87);
INSERT INTO reviews VALUES (4989, 400630, 1078, 'It''s like paper mario''s weird dutch cousin with racism. It''s really fun.', 'Often I find myself playing highly rated indie games and they end up having the same elements. Unique art style, heavy focus on story, plenty of humour and unusual moments/mechanics that you don''t commonly find in games. Another common aspect I find within these games is shallow gameplay and poor level design. Wuppo is no different. I can understand why a lot of people praise it highly but if you value gameplay and level design over art style and story than I think you should look elsewhere. If ', 'Very Positive', 93.32, 2.13, 1.83);
INSERT INTO reviews VALUES (4991, 400660, 336, 'Pros: charming art style, goofy story line & interesting cast of characters, has a tutorial, soundtrack fits the theme, basic combat mechanics, after defeat you can retry the battle again, multiple endings, new game + can be unlocked, endless mode can be unlocked, rats are overpowered!\r\n\r\nCons: locked at 30fps, only 3 save slots, no graphical settings, RNG, during combat units will overlap each other visually – there is no 3D screen rotation, when summoning minions - it will not let you decide w', '"You are the dungeon" - unfortunately this is not the case.  It''s a turn based combat game which although cute, is little more than a process of clicking on the enemy and watching it''s health bar drop.  Although probably worth the money to people who like this sort of thing, it''s not for me and I don''t think the brief description summed up the game very well - If I''m the dungeon, I want the heroes to come to me!', 'Very Positive', 89.29, 5.37, 0.45);
INSERT INTO reviews VALUES (4993, 400740, 306, 'So we all just playing this for the background?', 'like me and everyone else here, i''m guessing you bought it for the background', 'Mixed', 45.42, 8.25, 2.60);
INSERT INTO reviews VALUES (4994, 400750, 9364, 'It''s the Arma of RTS''s. Destruction, lighting things on fire and having the fire spread, unit options are huge, direct control of any unit. This blows every other WW2 RTS out of the water and is a true labor of love.', 'Taking direct control of any unit you want doesn''t make up for the AI''s inability to do anything on their own.', 'Very Positive', 84.75, 372.82, 6.58);
INSERT INTO reviews VALUES (4995, 400790, 155, 'Better than Elden Ring', 'bought this game for 50p\nthats a good deal\n£9.29?\nwho the hell is buying this', 'Overwhelmingly Positive', 95.48, 3.03, 1.37);
INSERT INTO reviews VALUES (4996, 400800, 240, 'MXGP2 is a fun game, with plenty to see and do. Obviously, fans of Motocross will get the most out of it, but there are way worse driving simulations out there.\n\nhttps://steamcommunity.com/sharedfiles/filedetails/?id=3335860802', 'this game runs horrible, 24gb ram + rtx 3050 but the game still stuttering like hell, i run heavier game smoother that this piece of garbage', 'Mostly Positive', 70.00, 4.25, 4.70);
INSERT INTO reviews VALUES (4998, 400910, 2561, 'Rabi-Ribi is perhaps my favorite game that''s impossible to recommend. It proves that you can make an excellent Metroidvania while being completely unbeholden to any of Metroid or Castlevania''s aesthetics or conventions. But most people will take one look at the box art and screenshots and immediately disregard the game, waving it aside as a "gooner game." And it''s easy for me to say that those people are wrong, and that the game''s aesthetic has no bearing on its amazingly-executed exploration, f', 'Sexualized minors', 'Overwhelmingly Positive', 95.94, 46.33, 16.53);
INSERT INTO reviews VALUES (4999, 400940, 1339, 'hitman but vr', 'Horrible save system, game put me in a soft lock where I endlessly was killed by a security bot and couldn''t reasonably escape from it, basically ruined my entire playthrough and couldn''t do anything about it.', 'Very Positive', 80.96, 3.62, 5.55);
INSERT INTO reviews VALUES (5002, 401190, 1590, 'ARK can pack up.', 'Complete achievement spamming jank. Spams 1000+ achievements at load up, most of them having nothing to do with the game but random crap the developer put in from other users like profile, community, twitch, and non-steam links, random messages, and other crap. The game itself took some tinkering to not look like I was playing on a broken VoodooFX card from 1998, and even when I finally could see what I was shooting at, wow is the game a twitchy mess of nothing. Blobs slightly resembling dinosau', 'Mixed', 66.73, 1.75, 0.33);
INSERT INTO reviews VALUES (5009, 401360, 278, 'Very pretty game with interesting themes. Not too much too do outside of the bosses which are mostly fun, though very unforgiving. You will call fish slurs you never thought you would before.', 'The game looks nice on screenshots, but on screen, it looks like an EGA game (16 color low resolution game from 1980). I encountered a bug within the first 5 min of gameplay. The intro is not skippable, controls can''t be redefined except in main menu, which means quitting without saving your game. The animations are inexisting. Looks like a game made in a week, for a game jam. The gameplay is not interesting for the little I played (10 minutes). I prefer asking for a refund rather than going on ', 'Mostly Positive', 70.50, 8.17, 0.17);
INSERT INTO reviews VALUES (5012, 401680, 2800, 'The Earth is hungry. Its heart throbs and demands cleansing. The Earth is also thirsty.', 'Still has crash issues with 10 and 11th gen CPU''s can we please get a permanent fix for this?', 'Very Positive', 92.86, 9.45, 19.27);
INSERT INTO reviews VALUES (5013, 401690, 171, 'i have played on and off for 7 years and it is well its old very old but has stood the test of time so i recommend this game but get it on discount do not get it for full price my review is overall good.', '5.1 hours to understand all the mechanics and beat it, with 100% the achievements.  Not worth $15.99.  \n\nThe AI is clunky and unresponsive, mutiple time works gets in the way of others, or walk on the other side of walls, or not respond to their jobs.  \nThe UI is terrible, and unintuitive.  You end up clicking through 5 different menus and views to do two actions...like swapping from construcing pipes to wanting to view the overworld.  I''ve requested a refund.\nLastly, it''s easy.  Bare bone''s bui', 'Mixed', 60.23, 21.13, 5.12);
INSERT INTO reviews VALUES (5014, 401710, 413, 'Wait for it to go on sale, and you won''t regret picking it up.', 'Ça aurait pu être un de mes jeux préférés, mais la difficulté est ridicule. Le système de déplacement est original mais complexifie tellement le jeu. La plupart du temps je sais ce qu''on attend de moi, mais je ne peux pas le réaliser. Dommage.', 'Mixed', 69.01, 3.88, 8.75);
INSERT INTO reviews VALUES (5015, 401760, 153, 'One Of My Favourite Strategy Games, It''s Just A Shame How Short It Is\n', 'this game is so incredibly bad, for some reason it desides to remove all of the most powerful upgrades from you, leaving you to die no matter how hard you try, i got really good at this game in a short time, then after the rewind thing, it just revoked all my strongest upgrades, and put me against even stronger enimies than before, so i couldnt win any level without dying at least once, every attack delt 12% of my hull integrity, and enemies started to attack the location of the ARGO without me ', 'Mixed', 64.71, 19.57, 4.83);
INSERT INTO reviews VALUES (5018, 401810, 329, 'Criminally underrated 3D platformer.', 'It''s a mediocre Mario clone. Why did I enjoy it then? Perhaps Mario is such a good game, even bad clones end up being fun. \n\nDo with that what you will, but I don''t think I can recommend it.', 'Very Positive', 92.71, 5.02, 9.32);
INSERT INTO reviews VALUES (5023, 402020, 1660, 'The game was just my speed! Due to the game art emphasizing the park''s chipmunk character, you''d be forgiven for thinking this was some kind of Five Nights at Freddy''s animatronic jumpscare game - it''s not. Instead, it''s more of a traditional ''walking sim'' as much as those can be considered to have traditions. \r\n\r\nYou''re playing the perspective of a mother running after her bratty kid who ran back into the park after it closed. You are walking along, exploring, and reading as the story unfolds. ', 'A Game So Bad I Had to Create an Entire YouTube Essay to Explain Why\n\nI''m not even joking, I legitimately created an entire YouTube essay to explain how fascinatingly bad this game is. You can watch it here: https://www.youtube.com/watch?v=YiuZxycCAvE', 'Mostly Positive', 71.20, 1.83, 1.52);
INSERT INTO reviews VALUES (5025, 402040, 369, 'While the story and exploration aspects may not be outstanding, the game excels as a puzzle experience, offering a short yet enjoyable room-escape adventure.', 'I thought long and hard about what to rate this and overall, I think it is an ok game. Barring the issues with resolution and occasional menus not working, the puzzles themselves are interesting in general. Some are just plain frustrating, and then there is the RNG achievement that required countless reloading. If you''re interested, I''d wait for a steep sale.', 'Mixed', 69.65, 2.22, 4.82);
INSERT INTO reviews VALUES (5026, 402060, 170, 'Californium is a good adventure game with a great story, a weird ambiant and some colored deisigns. For his low price, I recommend it!!! ❤️', 'Good idea, bad execution, great art. \n\nThe thought behind it is kinda "dickish" but the gameplay was "dickish" as well. It plays so horribly I was just frustrated instead of involved. Bug when I fell down through nondimension without barrier forced me to repeat last chapter didn''t help as well.', 'Mixed', 69.41, 35.95, 3.77);
INSERT INTO reviews VALUES (5028, 402120, 235, 'This is like  the much more difficult predecessor of the auto-battler/shooter genre that exploded with Vampire Survivor.  If you want a bit of a challenge...or a lot of challenge because its super hard  on hard lol but definitely reasonable on normal.  Check it out, it''snot bad for full price, even better if you catch it on sale\n\n8.5/10', 'Deathstate isn''t a bad game by any means, but it''s boring, and that''s the worst thing to say about a bullet-hell inspired rogue-like with lovecraft thrown in. All normal attacks are handled automatically by the game; leaving you to move, dodge and use any special abilities. The majority of your time is going to be moving slowly around levels waiting for enemies to die. This becomes worse when fighting bullet sponge elites and bosses.\n\nI managed to beat the game on my third try, and I haven''t fel', 'Very Positive', 86.81, 20.32, 2.38);
INSERT INTO reviews VALUES (5029, 402130, 427, 'Well its a racing game alright, its just not FlatOut. Instead of dynamic crash physics, somewhat realistic driving and competative ai we got cars that emulate what it feels like driving bumber carts on ice and butter with ai  sharing a combined 0,2 braincells.\r\nI am only giving it a possitive review because of how funny the physics are.', 'I want to like this game, it''s a great franchise. But I can''t. The game play is just aggravating. \n\nIt is WAY too easy to spin our or flip over from even the smallest bump and the more you upgrade your car, the easier it is to go out of control. It looks like you  can make some adjustments in the settings I tried without much luck. \n\nThere are some levels where you can''t even see where you are going. It is either too dark or there are too many things flying around on the screen to make any sense', 'Mixed', 47.31, 5.02, 2.10);
INSERT INTO reviews VALUES (5031, 402160, 260, 'I still vividly remember tracking the release of the original Star Command on IOS when I was a kid, and fondly recall finishing my first of a handful of playthroughs sitting through AP Bio as a high school freshman. The experience was more linear than I had hoped for, but the style was charming and the gameplay was novel for the time and platform. I was always a fan of FTL, and this scratched a similar itch while also being distinct enough to warrant its own existence. I was excited when Galaxie', 'This game still feels unfinished. Mobile version is preferable to this, even with it lacking the features of this version. This game feels like a scam especially to those who have been around since the Kickstarter days. If you are looking for a spaceship management game where your crew can get up to outer space shenanigans buy Space Haven instead. It is actually polished and has many more features despite the fact it is still in early access. I am convinced nobody would prefer this game unless t', 'Mixed', 44.23, 1.03, 2.02);
INSERT INTO reviews VALUES (5033, 402180, 1119, 'is good game, takes a bit to learn how to control one handed', 'No amount of "Free" can ever give me back the time I wasted to finish this slop.', 'Very Positive', 84.27, 48.85, 6.37);
INSERT INTO reviews VALUES (5037, 402260, 385, 'This is a pretty straightforward murder mystery adventure game, but it has some fun ''scares'' that might make you classify this as horror or thriller. The walking mechanic is non-existent, like old-school adventure games where you click the ''edge'' of a scene to move in that direction... that makes some of the ''scare'' scenes extra tense because you don''t get to mash a RUN button! The puzzles were simple and fun, and I say this as someone who does not like complex puzzle games. I hate having to che', 'VIVE OWNER REVIEW\n\nI hope the developers see this comment. If they do and fix the issues I mention I will definitely re-purchase (I have requested a refund). This *could* be an excellent scary game but for a few major issues. First, the game is not room-scale enabled. If I deviate from my original standing position even slightly I can see a headless corpse of my own body just to the side of me. Since jumpscares often work by putting a scary person/monster close to your viewpoint I find myself co', 'Very Positive', 82.08, 2.50, 0.53);
INSERT INTO reviews VALUES (5039, 402310, 217, 'This game is a fantastic blend of roguelite and tactical gameplay. The developers did an excellent job merging the two genres, and I’m honestly surprised it hasn’t gained more attention on Steam. The replay value is solid, with numerous class, companion, and equipment unlocks that keep things fresh every time you play.\r\n\r\nI especially enjoyed how the story evolves as you get stronger, with multiple endings to uncover. It adds a layer of depth to the experience, making each run feel rewarding.\r\n\r', 'I won''t be forced to play classes I don''t want to grind for classes I want to play.\r\nThere are other games to play classes I want to play and I can get to playing them right now.\r\nRefunded.', 'Mostly Positive', 74.19, 31.97, 0.68);
INSERT INTO reviews VALUES (5040, 402330, 1206, 'live-action choose your own story adventure game that tests your reflex skills with dynamic quick time events. The story is simple but hilarious and the actors give this kind of awkard "office" tone that makes the delivery of some lines even funnier when they''re said', 'I don''t want to write anything mean, so I''ll keep it short and sweet. I really don''t recommend spending any amount of money on this game.', 'Very Positive', 89.22, 5.52, 0.77);
INSERT INTO reviews VALUES (5043, 402530, 388, 'The ending was disappointing, but everything else was just as good or better than season 1', 'Not impressed with this game, actually. High hopes, but lots of issues with the game. Wishing it wasn''t built on Adobe AIR, firstly, and that engine might have something to do with the Achievements not working, on two different ubuntu linux systems. The story is a bit rough, with no voice-overs, little music, and few audio effects. So much of the game is just the quiet tap-tap-tap of the footsteps.\n\nThe puzzles were not intuitive many times, because they designers were going for a surprise revea', 'Very Positive', 94.07, 9.10, 4.28);
INSERT INTO reviews VALUES (5045, 402570, 779, 'Man I miss this so much', 'what the hell?\n i buy this game for 20 dollars and now they decide to make it free? can i have my 20 dollars back?', 'Very Positive', 92.17, 82.12, 57.90);
INSERT INTO reviews VALUES (5046, 402620, 618, 'Wait a minute... there''s something bothering me about this place...\n\nMy GOD, this lesbian school doesn''t have a fire escape!', 'The absolute slowest of slow burns - positively glacial. The story progress is barely perceptible, and has been a significant source of frustration.\r\nAnother source is the unrealistic ignorance about love and their own bodies these girls have. This idealized innocence will probably not be palatable to Western readers - it seems to be a cultural thing from in Japan and that area. The Eastern influence on the writing is glaringly obvious, perhaps painfully so, and to my eye it just makes the girls', 'Overwhelmingly Positive', 97.25, 17.05, 6.73);
INSERT INTO reviews VALUES (5049, 402710, 8073, 'Look, so many people are dissing on this game. Look, it''s a decently good game. It might not be worth buying, but if you''ve had it for a long time, don''t dishon it. It''s now decently good and fun to play. It still has its main story with a couple of changes here and there, but it''s still a decently fun game.They''re finally finishing development.', 'Devs have officially publicly announced they have abandoned this game, oops sorry, """sunsetting it."""\n\nGood lord what a joke of a studio you guys are. Remove this off steam.\n\nEdit: They removed it off the store. Rip bozos. Never make a game again. Any game that has the name Brian McRae associated with it needs to be avoided like the plague in the future.', 'Mixed', 51.93, 660.73, 10.95);
INSERT INTO reviews VALUES (5050, 402750, 180, 'The game is good, but some game physics are just abismal', 'this game is a good laugh. "Start up the hydraulic excevator", yes but almost every excevator is hydraulic. Every machine has a mechanical handbrake with sounds recorded from a car, not realistic at all. And then you have hydraulic pressure building up so that you need to vent it. "highly" realistic that you just vent out oil on the ground. hauling 300 tonnes in a machine that is probably 100 tonnes on a regular road is not legal. and to add insult to injury, it feels like the rig weighs 10 kg s', 'Mixed', 66.67, 5.68, 2.00);
INSERT INTO reviews VALUES (5054, 402880, 424, 'This game is a guilty pleasure of mine. It''s not perfect by any means, if anything its pretty jank and often annoying (both in terms of controls and cheap deaths) but it clearly had a lot of TLC poured into it, you can feel the love and care that was put into the whole thing.', 'Good game ruined by janky controls.  \r\nI don''t know who thought it''s a good idea to put "double-tap movement key to dash" in a game that requires precision alignment around instant-death mechanics such as spike traps and pits.  \r\nIf there was a way to disable the double tap binding and have a dedicated dash/sprint key I would recommend this game, but in the current state it just makes for a frustrating experience.', 'Mostly Positive', 75.94, 8.15, 5.87);
INSERT INTO reviews VALUES (5065, 403180, 479, 'w game so nostalgic', 'On steam, there is no book of seasons. was good but rotted to basically nothing. also the fact that drawn below costs money now. i loved this game, when i heard about the book of seasons, i returned to it, only to realise the new update is missing from steam. I suggest you play something else', 'Very Positive', 87.06, 5.53, 13.43);
INSERT INTO reviews VALUES (5066, 403190, 5391, 'Fun game, a little easy after you get the hang of each planet, Happy they are making PB2 more in depth mechanics, can''t wait. WOOOOOOOO!!!!!!!!!!!!', 'My ONLY negative about this game is that there is NO PAUSE allowed.  \nYou can hit ESC and stop the game and look at the "Encyclopedia" but you cannot examine the terrain or look at your statuses of resources or do any planning.\nMeanwhile your Oxy or H2O or Energy is running out.\nAnd the developers want it that way.\nHard to learn the game without a pause to at least see the terrain, your buildings'' statuses, your resources, etc.\nGeme looks really good as city builder, but even in real life you do', 'Mostly Positive', 77.24, 528.92, 2.02);
INSERT INTO reviews VALUES (5070, 403290, 125, 'A nice little game telling 12 small stories of adventurous journeys, taking path between three routes, each of which will make you choose between two choices, leading to another pair of last choices until you loop back to the beginning, ready to take on another of those 12 stories. :P\n\nThe stories are short and the actions simple, but sometimes you''ll have to wait a bit as the characters transition from a scene to the next one, but it''s not a problem unless you wanted to hurry through the game i', 'This game has a strong core idea and certain well-executed parts. You can tell where work and heart went into it - the music, for example, has this kind of a capella, homemade sound that makes me think it took time and passion to create. As a game, though, it''s lacking in some ways that turned me off from it.\n\nThe controls for PC are irritating. They don''t break the game or anything, but at no point do they feel good, and at times for me they didn''t work without trying a couple of times. The lit', 'Mostly Positive', 74.40, 6.83, 3.58);
INSERT INTO reviews VALUES (5073, 403400, 331, 'OH MY GOODNESS IT IS JUST HOW IT WAS ON MY DS AT MY GREAT GRANDPAS FUNERAL!!! LOVE IT SOOOOO MUCH!!', 'Constant down arrow input,  Can''t play.  The irony....multi million dollar games without a bug.  An 8 bit program from 1982?  Bugs', 'Very Positive', 90.94, 7.70, 9.68);
INSERT INTO reviews VALUES (5074, 403410, 242, '#freemspacman', 'I''d forgotten how utterly crap this game is. I remember Pacman fondly as part of the very beginnings of gaming, but i''d forgotten how quickly this game goes from ''kinda fun'' to ''feels unbeatable and i want to do something else now''.\n\nIts about 10 minutes.', 'Very Positive', 89.26, 1.22, 0.15);
INSERT INTO reviews VALUES (5075, 403430, 553, 'good game, brought my dad back with the milk', 'Great game, and an incredibly influential game. As featured in the equally influential cult film, WarGames. However... this version has digital movement, which it wasn''t designed for. Therefore, the emulation is crap and it''s more difficult than it''s intended to be. I guess buying this absolves you of any piracy sins.', 'Very Positive', 90.42, 2.68, 0.33);
INSERT INTO reviews VALUES (5079, 403560, 153, 'No one ever sees my reviews, just know its good and move along.\n', 'Space Cat Studios should remake this one and keep in mind Sterling came out as non-binary. \n\n', 'Mostly Negative', 29.41, 4.55, 3.33);
INSERT INTO reviews VALUES (5080, 403590, 155, 'I like the idea of this game, but the game needs a lot of work. I will buy it again once the game gets more updates.', 'just down right terrible. game is so bad you play it to have fun with the bugs and glitches than you do the actual content of the game', 'Mostly Negative', 23.23, 0.70, 1.55);
INSERT INTO reviews VALUES (5081, 403640, 18432, 'I never play a single player campaign game twice....until Dishonored 2. Completing it in low and high chaos is like playing two dif games. Such a blast. RIP Arkane, this game is a masterpiece.', 'It feels extremely linear compared with the first one. Yes, there are multiple paths to get to your objectives but those paths are really singular and settled. You can chose among lets say 3 paths and that''s it. Way less access to roofs and other vantage points that made the first one easier, yes, but also made you really feel like an assassin and gave a sense of freedom and the hability to move across the whole level quickly. Altogether I liked this one way less than the first one.', 'Very Positive', 88.04, 34.92, 56.17);
INSERT INTO reviews VALUES (5086, 403700, 258, 'Its not much more than a novelty, with the quality/depth of a Newgrounds game. Might be worth it if you want to support Fully Ramb-I mean Zero Punctuation.', 'The game talked to me and said it was not for me maybe it is for you?', 'Very Positive', 84.88, 3.52, 2.00);
INSERT INTO reviews VALUES (5088, 403830, 273, 'before you start you can select "kill myself" which will genuinely end the game\r\n\r\nbest game best game', 'It''s not a terrible game, it''s fairly okay but there are some baffling design decisions from somebody that reviews videos games for the last 2 decades it kinda feels like he should''ve known better. \r\n\r\nMakinbg you spend perk points to unlock the harder challenges so you''re weaker than before and also having very limited perk points means |''ll have to wipe my progress to do the other half of the challenges to have a decent chance.\r\n\r\nIt''s also a game that seems to expect and want you to fail unti', 'Overwhelmingly Positive', 95.24, 0.42, 93.23);
INSERT INTO reviews VALUES (5092, 403940, 141, '5/10', 'Dungelot: Shattered Lands is boring..\n\nIt could be a very good game if only developer polished mechanics bit more.\nAt current stage first impression is good, then it all falls apart.\n\nGame mechanics are "borrowed" from Runestone Keeper, but are changed in a way that everything is rather far too easy. This causes you to feel sleepy and not engaged. You just click those tiles without much thinking.\nFor instance, encountering archers is meaningless because most of the time you carry ranged weapons ', 'Mixed', 62.41, 24.78, 14.97);
INSERT INTO reviews VALUES (5093, 403950, 418, 'Simple little game yet holds some complexities that make it engrossing.  Be prepared to get mobbed because the AI doesn''t mess around.', 'I love Dominions and have played it over several versions and hundreds of hours.\n\nI bought CoE3 a while back, and did not enjoy it.  The reviews of CoE4 were so positive, I thought I should try again.\n\nUnfortunately, I didn''t have much fun.  Playing felt mostly like a chore.  And the endless wandering stacks of independents are simply ridiculous and arbitrary.  They get very monotonous quickly, even though they are made up of a diversity of mobs.', 'Very Positive', 89.47, 20.55, 45.82);
INSERT INTO reviews VALUES (5094, 403970, 457, 'Combat is clunky and sometimes confusing.\r\nAnd sometimes your guys feel weak,\r\n\r\nBut the game itself is very fun.\r\nStory is engaging.\r\nAnd there''s dwarfs.', 'dialog is not good, ui is bad, combat is medium', 'Mostly Positive', 71.55, 20.17, 1.90);
INSERT INTO reviews VALUES (5097, 404040, 412, 'When is remake?  Of all the $h1t @$$ games being remade how has no one picked up this gem?', 'it doesn''t work it just crashes.', 'Very Positive', 93.20, 40.47, 108.78);
INSERT INTO reviews VALUES (5102, 404200, 285, 'Quite a good game. Very unique style. It looks great', 'Instead of making more maps, which shouldn''t be an issue in a game this simplistic, the devs instead essentially force you to replay the existing ones up to 3 times to get good gear. The combat itself is also very simplistic and gets old quickly, so it''s definitely not something that can keep you hooked. Not worth the time IMO.', 'Mostly Positive', 72.98, 5.93, 3.97);
INSERT INTO reviews VALUES (5112, 404530, 445, 'I wish this game was still being worked on.  But, I definitely got my moneys worth.', '-The idea is kinda cool , but the game itself is not good, there is an idea of game there but everything is very clunky, gameplay is stiff and there is no sense of direction beyond the tutorial text, control scheme kinda bed (same button to skip text and exit vehicle?) the tutorials kinda does not folow an order of progression (the game doesn''t guide you to buy or aquire your first gun but instead give you tutorial missions to rob a gun store)\r\n-AI progress in the map faster than you can think, ', 'Very Positive', 87.42, 92.42, 4.10);
INSERT INTO reviews VALUES (5114, 404590, 811, 'great gameplay. local and online coop. a gem of a game', 'The difficulty spike from level 1 to level 2 is just insane.\nThe boss in level two turns into a damage sponge and kills you in 7 hits that are extremely difficult to avoid', 'Mixed', 62.89, 202.17, 9.97);
INSERT INTO reviews VALUES (5115, 404620, 544, 'this game is really fun if you play it like you''re going back in time to try to change the timeline', 'So probably not that surprisingly this Political Machine is almost exactly the same as the previous 2012 version. And yes its early access, but really that does not mean that much, they’re going to add a few issues as they arise throughout the next year probably, and yes it does have the current political heavy weights, but that does not change the gameplay in any significant way.\nIt lacks depth, depth I’m sure the audience this game appeals to would not be turned off by. On top of that the game', 'Mostly Positive', 77.94, 2.20, 18.75);
INSERT INTO reviews VALUES (5119, 404680, 1826, 'This game is the definition of a hidden gem, everyone should know about for all kinds of reasons and yet if is completely forgotten. For it has an absolutely gorgeous cell shaded art style and pretty much everything looks incredible. It is essentially a 3D metroitvania, a 3D plarformer, a puzzle game and it even has some sweet combat. The result is a beautiful adventure that is in many ways one of a kind.', 'Technically very poor. Stutters incessantly and crashes after a while', 'Very Positive', 89.27, 5.80, 7.13);
INSERT INTO reviews VALUES (5120, 404690, 143, 'Cool and unique. Not totally my style but it''s pretty fun if you like Choose Your Own Adventures and dungeon crawlers.', 'It was a nice read, but its just too short. It could be finished in a half hour if it didn''t reset back to the start with every loss. Resetting so far is a real loss, its hard to be engrossed when you spend a minute or two clicking through pages you had already read, some of which move at their own dramatic pace. Its something you would probably find interesting and appreciate when its free on a site, but if you plan to buy it I would wait until its a price your willing to pay for an hour or les', 'Very Positive', 81.12, 0.20, 0.98);
INSERT INTO reviews VALUES (5124, 404820, 121, 'It''s a fun and challenging game to play locally, at first even combining some steps can be hard.\nPersonally my favorite event when playing this game was Triple Jump, but i would recommend fro starters to practice the 10, 30, 60 and 100 to practice those sprint mechanics.', 'as a rage game, this game surely works, but it is extremely annoying how random these controls can be, even after 131 hours I feel the controls are inconsistent, the only reason I played so much was because I was a dumb kid who enjoyed the simplicity, I have played it these 2 last days just to get the achievements because I am achievement hunting, and I hated every second of it, it wasn''t fun when it started and I wasn''t excited when it ended I was simply in relief. so I will not recommend it un', 'Very Positive', 87.60, 38.78, 131.32);
INSERT INTO reviews VALUES (5133, 405180, 166, '123 Slaughter Me Street if it was peak:\r\n\r\n\r\nThe Follower has been found dead shot 123 times on Slaughter Me Street', 'I did not want to follow, freak, glaze, OR geek. Or however the song goes.', 'Very Positive', 85.54, 0.42, 0.37);
INSERT INTO reviews VALUES (5136, 405290, 1346, 'i remember playing this game on the Xbox 360 with my younger brother and we would never actually beat the game but man did we have fun and now that ive beaten all of the bosses i can say this is my favorite game', 'Game erases your progress half way through.  Also seems to be rendered unbeatable by no way forward after progressing about 3 quarters of the way through.  Going backwards doesn''t help either.', 'Overwhelmingly Positive', 96.06, 14.38, 7.00);
INSERT INTO reviews VALUES (5137, 405310, 1816, 'Great game had it when i had a 3DS only issue with this game is that when you start playing after you download it you need to click and hold windows and R and type %appdata% in the box that shows up, than go to Warner Bros. Interactive Entertainment, Than go to LEGO Marvel''s Avengers, one-cs you get in there you delete file GUI3. I have to do it every time I play but its better that having to uninstall it again. Hope this tip helps. took me forever to get it figured out.', 'The game overall is great. However, some reason when I open it it crashes and yes my pc is good enough to run the game', 'Very Positive', 84.36, 8.47, 2.85);
INSERT INTO reviews VALUES (5141, 405500, 122, 'I love this game to death. It''s clear a lot of hard work and effort was put into it. It looks great, it feels great, every combo and object smashed is super cathartic and the party mode is super fun to play with friends. It''s extremely well made for such a small team and I wish them well.\n\nOn the other hand, I do have to be fair and I have two huge annoyances. I bought this on Steam because I played this on my PlayStation and yet there is no PlayStation Controller support which is extremely disa', 'no controller support for a game thats on consoles. hard pass. If you played this on PS and expect it to use your PS controller on steam(like it should) you will be dissapointed. does not work 1/10', 'Mostly Positive', 73.77, 3.07, 0.10);
INSERT INTO reviews VALUES (5146, 405610, 120, 'Flight of the Paladin\n\nHas a total of 5 trading cards.\n', '\nJust imagine worst game you can ever play... that''s it.\n', 'Mixed', 42.50, 0.35, 5.63);
INSERT INTO reviews VALUES (5147, 405640, 7575, 'Daniel Mullins, I wasn''t familiar with your game. \n\nAn utterly bonkers, dark and twisted puzzle adventure that is meta af. \n\nFor my money, one of the best indies I''ve ever played and I haven''t even finished it yet. \n\nI''d be sure to check out Mullins'' other two games ASAP after this. Bravo.', 'I''ve heard people gush about this game for years and diligently avoided spoilers as best I could so I could go in blind and get the full experience. But that was a wasted effort. It''s just another low budget "haunted" game, with are annoying and tedious puzzles. I don''t understand why everyone made such a big deal about it. It wasn''t the first ''haunted'' game, right? 9 isn''t that long ago, right?', 'Very Positive', 94.51, 3.13, 0.48);
INSERT INTO reviews VALUES (5150, 405710, 1816, 'I do like this game, it has sadly however been abandoned by the developers. It will not get any more updates.', 'This game is really, really fun, but despite announcements that it is "finished", it feels more like it was just abandoned. It''s just really obvious at certain points that there was supposed to be... more. Character quest lines "end" awkwardly in what seems like the middle of the story. One random character has a dramatically longer and more detailed plot line, to the point that it really sticks out, so I think the intention was to do that with all the characters and they just gave up?\n\nIt''s a s', 'Mostly Positive', 79.79, 39.05, 68.40);
INSERT INTO reviews VALUES (5153, 405820, 2222, 'I had a good childhood because I grew up with boomer shooters like this one on the N64', 'The head of Nightdive Studios wished for death and harm to his political opposition on social media. That is unacceptable.', 'Very Positive', 94.73, 2.28, 0.13);
INSERT INTO reviews VALUES (5154, 405830, 1465, 'Since I was 10 finally I''ve defeated The Primagen by myself and saved the universe.', 'After the attempted assassination of a former president, Sticker Mule, a printing company that worked with Nightdive, came out to speak against political violence and promote acceptance and nonviolence to each side of the political spectrum. In reaction, Steven Kirk of Nightdive said, "You''ve lost my business. Anyone who supports this monster deserves to go down with him."\n\nThis is a disgusting manner. So, if Nightdive wants to devide everyone based on politics, then I will return the favor to t', 'Very Positive', 92.42, 22.32, 18.48);
INSERT INTO reviews VALUES (5156, 405900, 2500, 'The epitome of Yarikomi games, mastering its depths through repetitive play.', '9 Years after this game''s release on steam it still doesn''t work well with AMD graphics cards, big layering issues in the castle and INVISIBLE (literally transparent texture) base panel on battles. This is just on the first half hour btw.\n\nJust sad coming from a reputable publisher like NIS America, and being the first game of a long standing, popular saga. Even sadder when 2 years later they released an improved version (Disgaea 1 Complete) for Switch and PS4, with extra content and QoL changes', 'Very Positive', 88.36, 28.45, 0.48);
INSERT INTO reviews VALUES (5163, 406080, 159, 'Ant War: Domination\n\nHas a total of 8 trading cards.', 'This is not the same version of the original game. It has been altered to be more grindy, and the randomness in the daily events has been removed. Moving your nest feels pointless. Allocating ants to nurses or workers for the increased gains was significantly nerfed, it feels like there''s no point in putting more than 5% ant on them. Putting anything on warrior ants causes whatever you end up battling to have scaled stats against your stats, and does not seem to increase your stats nor increase ', 'Mixed', 57.23, 1.37, 2.87);
INSERT INTO reviews VALUES (5167, 406130, 278, 'Squeak squeak, mmm cheese', 'Wanted to play this for a long time, sadly lack of ui/text scaling (and tiny unreadable texts) are a no-go for me', 'Very Positive', 82.73, 6.32, 0.33);
INSERT INTO reviews VALUES (5168, 406150, 7385, 'A short yet healing game that greets you warmly and brings a smile to your face.\n"Hello?"', 'There is really nothing to this game.... It is only 30 minutes and has basically zero depth. I thought I had just finished the first level, but apparently that was the whole game. Would not recommend, even if it would be free it feels like a waste of time.', 'Overwhelmingly Positive', 95.78, 0.70, 0.37);
INSERT INTO reviews VALUES (5170, 406170, 102, 'OK so this is a first impression as you will see I don''t have that many hours in gameplay. However I have got to say that this game keeps you on your toes. There is no time to chill out and have a picnic. Provided you have the right strategy you should be able to survive. People say they die too quickly, that is just because their strategy sucks. Keep getting thirsty? Then build your base where you know there is a water fruit node nearby! Keep getting hungry? Pull your finger out and do some hun', 'During the Greenlight era, many were invited to a group with a promise of a free copy of this game. When they "ran out of keys", they kicked us out of the group. This game was made by a bunch of lying crooks. The game itself is not bad though. Just kidding, it''s rushed early access hot garbage that someone decided to put a 1.0 on it and call it done.', 'Mixed', 53.92, 20.98, 0.15);
INSERT INTO reviews VALUES (5172, 406290, 1340, 'The definitive PVP tabletop game. Dice rolls are a load of bull, but they always are.', 'Don''t buy this. Played 6 straight games, last one with a +10 handicap, and still lost them all.', 'Very Positive', 87.31, 336.43, 4.07);
INSERT INTO reviews VALUES (5175, 406350, 1493, 'As of February 10th, 2025, the servers are up, and you can log in to the game without any issues.\nA workaround for low FPS is to type "-EnableGRPC=false" in the launch options (without quotes).\n\nThe game itself isn''t bad and can be quite entertaining. KK has a solid foundation with 5 classes of carts and around 10 laser-scanned tracks that you can race on with AI.\nIt would be awesome if another developer bought the project and continued its development.\n\nKK usually doesn''t go on sale (the studio', 'Game has been problematic from the start, now it''s completely unplayable and steam wont even issue a refund, absolute scam and needs to be removed from the steam store.', 'Mostly Positive', 72.00, 6.97, 0.25);
INSERT INTO reviews VALUES (5178, 406550, 1541, 'An autistic 9 year old is speaking, listen and learn', 'The best "It gets good eventually" simulator', 'Overwhelmingly Positive', 95.33, 93.15, 8.28);
INSERT INTO reviews VALUES (5182, 406720, 122, 'Not quite on the same level as the other Death To Spies games, but fun none the less.\r\nRuns well on Linux.', 'It''s not very good! I was hoping for a janky, silly experience when I saw the game. I admit I was not going in expecting greatness. What I got was the occasionally funny bug surrounded by an absolute slog of a video game dominated by slow and boring cutscenes accompanied by uninteresting still images of 3D models, and stealth gameplay that makes me hate stealth gameplay. It''s difficult to tell why your suspicion level is ever what it is, it''s impossible to tell when you are out-of-sight, and eve', 'Mixed', 54.92, 11.75, 7.73);
INSERT INTO reviews VALUES (5188, 406850, 168, 'Crush Your Enemies\n\nHas a total of 6 trading cards.\n', 'This game does largely achieve its goal of being a small-scale, lightweight RTS, but that just didn''t really click for me, and I found the writing and humor pretty grating.', 'Mostly Positive', 79.76, 0.68, 2.37);
INSERT INTO reviews VALUES (5190, 406870, 286, 'A strange bat creature runs you off the road! You are a botanist on your way to find an endangered flower, but your day takes a dark spin. You must now stop the evil Boruta to save both Slavic creatures and your captured grandmother! Story and characters based around Slavic fairytale. \n\nThis story is wonderfully narrated and has plenty of cuts scenes that keep you enthralled. Characters are cute and nothing scary, only slightly ominous - so great for younger players. It offers casual, advanced a', 'I can recommend it as a HO game. As for the story, however, I must say that I have rarely been this bored with an Artifex Mundi production.', 'Very Positive', 91.96, 5.40, 6.17);
INSERT INTO reviews VALUES (5194, 406970, 602, 'https://steamcommunity.com/sharedfiles/filedetails/?id=2024161148\nhttps://steamcommunity.com/sharedfiles/filedetails/?id=2038271622\nhttps://steamcommunity.com/sharedfiles/filedetails/?id=2023053491', 'By all means, if it''s on sale give it a try. But between the monotonous character dialogue, the buggy movement, the boring descriptions, and the subpar animations, the game wasn''t all that enjoyable. The audio kept cutting off. The controls for the chase sequences didn''t functions smoothly, and the obstacles didn''t have proper collision. The player character is egregiously slow, and running hardly improves it. You only get one chance to listen to each dialogue option per play-through, and there ', 'Mixed', 66.28, 4.97, 3.22);
INSERT INTO reviews VALUES (5196, 407020, 112, 'I didn''t hate this game. If you are achievement hunting, there is a official guide you can find and use (someone linked it in the "guide" section) but it is a walking simulator that can tell quite a few stories with only nature sound and music. You walk to the right, only stopping when the music plays (until you have learned which spot triggers) and an event can occur. Some of the events are triggered by other events, I ended up having to follow the guide to understand them....but it''s still a s', '2.5/5\nIf you are old enough to buy beer, it means you won''t find this game as interesting as if you were a teenager. It makes good between the lines points about life but those are fundamentally obvious to anyone who existed for more than 0.01sec in this world. If you want then buy it when it''s on a discount, maybe you can get lucky when buying the bundle (my bundle of 3 games couldn''t be purchased, steam support said it''s publisher''s fault lol). It also has achievements and cards.', 'Mostly Positive', 75.89, 4.70, 1.47);
INSERT INTO reviews VALUES (5201, 407130, 3074, 'Its a very fun game to play. The restoring of the tanks is fun and highly detailed. Also when you dig up tanks  is very fun. The museum you can unlock makes the game perfect for ww2 historians or people who just like tanks.   10/10 would recomend', 'The game is abandonware, only a few tanks have detailed models. The devs aren''t putting out updates beyond enabling/disabling the seasonal missions.\n\nThey decided they''d rather work on their other game, generic tank combat game #53 and go bankrupt making that rather than work on the game that people actually liked.', 'Very Positive', 89.53, 95.80, 179.67);
INSERT INTO reviews VALUES (5204, 407230, 248, '⠀', 'I got softlocked because the game asks me to do a purchase to progress the story. However, you are unable to gain money in this game other than in specific events, and you can just spend it all on items without knowing of such roadblock, and the last event that you can gain money from, gives 1 coin less than the progression requires, which makes me feel like this was intentional... And no, you cannot sell said bought items. That would be too simple, would it ?\n\nThis is awful game design and the ', 'Mixed', 61.69, 3.68, 4.23);
INSERT INTO reviews VALUES (5206, 407300, 118, 'I''m sure 99% of people don''t read the reviews. So you may not know that Naruto can be a bit harsh sometimes. You may not know this, but Naruto also grew up without a father. In fact, he never met either of his parents and never had any friends.', 'I wanted to like this more than I did. The game is based on a Brazilan myth and you play Mary, a woman trying to escape a monster who is out to kill 7 virgins named Mary. You have to solve a couple inventory puzzles and listen to some journal entries to try to figure out how to escape or defeat the monster. There are multiple endings that you can experience.\n\nSadly, the majority of the gameplay consists of wandering around a maze where everything looks pretty much the same. There''s no map or any', 'Mixed', 69.49, 2.05, 4.75);
INSERT INTO reviews VALUES (5207, 407310, 169, 'Ninpo!💢 Triplets! 💢 The art of pregnancy! 💢💢💢', 'I bought this VN thinking it have a pretty good story for a short VN with cat girls like the NekoPara series & I thought it be at least close to the quality in terms of how good the story was in compared to the NekoPara series was but I was sorely mistaken. While the artwork is decent enough & like that its got a 16:9 resolution over the unfortunately more common 4:3 resolution that isn''t enough to make up for 1 what I think is 1 of the big sell points for VNs which is the story. The 3 MC for th', 'Overwhelmingly Positive', 95.27, 2.60, 15.85);
INSERT INTO reviews VALUES (5209, 407330, 818, 'dungeons n baddies', 'These are the achievements i cannot get Essence of the Void, Fortune, Burning Soul, An Ancient Mariner so 4 of these are broken for me and there is no way in hell i''am re-doing this whole game, i''am pretty sure i got the warp gem from the abyss nothing, got the Captain Bonny companion nothing, got Dual-ability for Yomi nothing, got all 6 luck statues nothing, this game is frustrating and very broken, I do not reccomend anyone to even try for 2,500 and 5,000 enemies either.', 'Very Positive', 93.77, 19.38, 6.23);
INSERT INTO reviews VALUES (5210, 407340, 106, 'This game is literally DELICIOUS. The story is funny and wholesome, though I honestly preferred the bad endings lol. Also the outfits are adorable! Pretty decent overall, there''s no complex lore or insane plot twists, just simple slice-of-life for a few hours with an amazing aesthetic and cute UI.', 'I''m here for the food. 🍰🍡🍓\n\nAs an avid visual novel fan, I was excited to dive into this game. The food illustrations are absolutely stunning, and the achievements are adorable. The concept itself is quite interesting, and reading about the game''s premise, characters, and names, as well as seeing the sketches, was genuinely engaging. But...\n\nIt doesn’t feel fully developed. The writing comes across as amateurish, and the UI is frustrating to navigate. While the text is technically readable, the ', 'Very Positive', 87.74, 3.30, 2.00);
INSERT INTO reviews VALUES (5212, 407420, 344, 'When i seen this game i was like .. :| wait !? what ?! :))) ..i rubbed my eyes and again :)) what the hell ?! :)) and bought the game and see what is really about ...\n\nWhen i started play i was like very happy that i found it as despite being just a simple shooter is a very fun game with our Lord Gaben where you can release or not Half Life 3 and much more ..is a game you definitely have to have it and play ! especially if you love our Lord ! you will also see lots of easter eggs so to say from ', 'not fun or funny', 'Mixed', 50.29, 1.55, 0.68);
INSERT INTO reviews VALUES (5213, 407530, 2149, 'It was good when the ark hype was crazy during 2015-2017', 'It''s criminal that this game is still being sold, considering that the servers are seemingly permanently down.', 'Mostly Positive', 73.52, 26.00, 0.20);
INSERT INTO reviews VALUES (5214, 407560, 594, 'it''s pretty good, pretty fun, just sucks that it seems the devs have abandoned it, your friends/viewers can''t even vote to give you items anymore because the voting link generation server seems to be broken.\r\nBut besides that little detail, it''s a very fun game', 'This game is very rough with one achievement that cannot be obtained normally the servers also shut down making a pretty big feature no longer available. 4/10', 'Mixed', 66.50, 16.45, 39.18);
INSERT INTO reviews VALUES (5215, 407600, 114, 'i''m positive the issues shown in the old reviews are solved, i havent encountered any slowdown, the only things i have encountered is audio levels going up and down randomly during gameplay, audio levels going down every successive time i pause the game, the game not keeping my settings upon relaunching the game, and the game not letting me pick other games besides raiden even when i hovered over them.\n\nit has its issues but i enjoy playing it.\ni hope the problems will be solved, but it''s to be ', 'ポートは完全に台無しだ！雷電はもっと良く扱われるべきだった！！', 'Mixed', 50.00, 7.38, 0.25);
INSERT INTO reviews VALUES (5221, 407780, 186, 'Excellent Penumbra or Amnesia-like game... Scratched an itch even Frictional hasn''t been able to scratch lately with their releases.', 'the game does not feel good to move around in', 'Very Positive', 90.32, 10.87, 13.18);
INSERT INTO reviews VALUES (5222, 407810, 887, 'very fun, looks gorgeous for an older game, surprising combat depth and variety once you unlock the full kit.  highly recommend for linear old school single player FPS fans', 'Hard Reset Redux is incredibly mediocre. The gunplay feels super boring—you''re basically just unloading tons of ammo into wave after wave of robot enemies, and they don''t even react until they eventually explode. It''s not satisfying at all. The levels are also pretty bland, with a dark urban cyberpunk vibe that doesn''t really change much each level. Everything looks the same because of the reused assets, and there''s no real sense of place in the city.\n\nIf you''re after a solid FPS with fun gunpla', 'Very Positive', 81.51, 5.95, 1.80);
INSERT INTO reviews VALUES (5224, 407840, 1969, 'don''t remember this but it was probably worth $1', 'I''ve played flash games with higher quality to be honest', 'Mixed', 49.92, 1.42, 1.12);
INSERT INTO reviews VALUES (5228, 407980, 155, 'this is the second best game ive ever played', 'This game changed my life again.', 'Mostly Positive', 79.35, 12.08, 2.53);
INSERT INTO reviews VALUES (5229, 408000, 101, 'The only reason I decided to play this game is because I watched AZZMAN play it when I was younger', 'Dont get this game even if it''s free. This game isn''t R18 and the patch isn''t provided.', 'Mostly Positive', 71.29, 11.05, 0.43);
INSERT INTO reviews VALUES (5233, 408120, 283, 'It''s important to know what you''re getting into here. This is a very different sort of game. I had wanted to to play Cibele for quite a while after writing an essay on ''Tacoma'' in college which Nina was also involved in. Quite simply, Nina Freeman has made an absolute work of art in ''Cibele''. While short, it is sublime. I think she has a lot to be proud of in this title. A marvellous game and I hope to find many more like it. If you are open to becoming immersed in a story of great quality, go f', 'not good', 'Mixed', 69.61, 1.55, 0.88);
INSERT INTO reviews VALUES (5236, 408280, 413, 'quirky - check\r\nnice pleasing artwork - check\r\nincomprehensible dialogue sounds (to me at least) - double check\r\npuzzles - check\r\nText combat - check!\r\n\r\nDidn''t expect the game to be this fun though - my only gripe is that it''s short. But I''ll still recommend it. It does give a short break from lengthy titles and let your kid play without worries on inappropriate stuff.', 'The art is amazing but the story, length and gameplay were not. Very disappointing. The game only took 1.2 hours to beat and 100%.', 'Very Positive', 82.32, 1.57, 1.23);
INSERT INTO reviews VALUES (5239, 408410, 1065, '9.4/10\n\nGreat mix of tower defense and star fighter mechanics. DLC is also fun, but probably easier to justify buying only when on sale. \n\nHad a couple bugs, but that might just be my out of date PC.', 'I love tower defense games, so I gave this one a try. Overall, the game is well made. Graphics are okay for the age, the sound and narration is good too.\n\nWhy a negative rating? Although the game is advertised as a fusion of tower defense and vertical shooter, the tower defense element comes up far too short. Without the support of the small ship that you control, any placement of the towers is completely irrelevant. It feels like the turrets are just a graphical add-on without any significant f', 'Very Positive', 92.68, 52.70, 2.75);
INSERT INTO reviews VALUES (5241, 408520, 726, 'Games alright. A bit short', 'I''m aware this is a VR game from 2017 and in 2017 I probably would have rated it as good ... but, let''s face it, once the initial fascination has worn off, you start looking at how much game there actually is. And in case of Form there''s little beyond what you give toddlers or really young kids to play with. Fit a shape into the right hole, remember a sequence of four ... it''s so low level and trivial that it takes more time to figure out what the game needs you to do than to actually do it. Yes', 'Very Positive', 90.36, 0.85, 1.28);
INSERT INTO reviews VALUES (5242, 408640, 130, 'Yes, it couldve done some things better and its not as good as Guardian Heroes. So what?\n\nIf i would compare every game i play to the very best or one of the best games of all time, i could barely play anything at all anymore. \n\nCode of Princess gave me a funtime with its competent combat system, nice soundtrack and colorful artstyle. PC Port is also decent and does its job. Only real bad thing, the Localisation is a joke. The mismatch between japanese voices and english subtitles is quite obvio', 'NOTE TO FUTURE COMPLETIONISTS: THIS GAME REQUIRES ONLINE CO-OP TO 100%, EXPECT TO HAVE TO FORM A PRIVATE LOBBY WITH OTHERS AND PLAY FOR ABOUT 4-6 HOURS TO COMPLETE.\n\nThis has been an interesting experience, not because I was astounded, but because this is SUCH a mixed bag. It''s a 3DS game originally, and this is a PC Port of it. The game itself is alright, it''s VERY short at about 3 hours to finish the main story, most of that playing out with a visual novel style narrative that is broken up by ', 'Mixed', 60.00, 6.37, 11.82);
INSERT INTO reviews VALUES (5243, 408650, 164, 'You can think that it''s Portal. But you will be wrong. Short and fun puzzle game. Looking forward for Part 2. Recommended for all puzzle games fans.\nAnd yes, they have a cake for you :)', 'It''s a cool concept, and it has really good colorblind support, but it has one major flaw that makes the game completely insufferable: you can''t undo mistakes. Do a single thing wrong, and you have to start the level over from the start. Most levels are not short either. Trying to solve the puzzles is an exercise in tedium; you''ll spend more time re-doing stuff you''ve already done than making more attempts to solve the part you''re actually at.', 'Mostly Positive', 73.17, 5.67, 0.43);
INSERT INTO reviews VALUES (5244, 408740, 361, 'its a good game u get to play as an esport player and manage a esport team with dif sides to the game either side is good so its good to play and have fun but it does get tireing after a bit of play time but its a good game to play on occasions', 'promised multiplayer, promised live match simulations, promised tons in the old website. Now all removed and out of Early Access. Good Job.', 'Mostly Negative', 34.35, 5.62, 5.85);
INSERT INTO reviews VALUES (5248, 408900, 243, 'Nice while it lasted ! Same devs went on to do Abiotic Factor, great game too. Check it out !', 'I''ll keep this short; The idea of the game is great but the execution isn''t great as of now. I''ve come across a few crashes already in my 9 hours of playing it, the melee combat of the monster is very basic and the main reason I don''t recommend it is the Dev''s. After the incident with TDL they aren''t really worth of trust and I literally don''t trust them enough to keep up with this game.\n\nIt might get better, it might not.', 'Very Positive', 82.30, 2.60, 0.85);
INSERT INTO reviews VALUES (5251, 408960, 151, 'You know it is a great game when six hours fly by and you want so much more and there is so much more. The more I play the more I like, my clan is starting to grow in power and I am starting to explore more and getting to know the game. This game seems to take the best parts of Dins Curse, Depths of Peril, and Drox Operative and mash it all up into one fantastic game. I love the character progression so much, you can mix it up anyway you want. I will be playing this much much more. It is in Beta', 'So far.. I''m not convinced.  Graphics have never been a feature of Soldak games but its about time they advanced.  The whole quests / rep system / npc system was way ahead of the pack but again I dont see that it had advanced.  I bought into this on the strength of the last games - I expected more than what appears to be the same character classes from Dins Curse with the same skills / limitations .  Perhaps a lack of imagination on my part but I would have liked to seen more modern character cl', 'Mostly Positive', 78.81, 129.50, 47.97);
INSERT INTO reviews VALUES (5252, 408990, 456, 'Feels unfinished but I''ve spent too much time and had too much fun in this game to speak badly about it.', 'I''ll mirror what others have said about this tragic abandonware, it deserved more love. I enjoyed the little time I spent, but I was ultimately unable to survive long enough to build a castle/kingdom (as shown in the video) - the onslaught of enemies always eventually overwhelmed my small village. Given some time for QoL improvements and balance, I really think we''d have a runaway indie hit on our hands, even by today''s standards. Cute graphics, relatively fun building mechanics, and some challe', 'Mixed', 43.20, 53.32, 23.80);
INSERT INTO reviews VALUES (5257, 409100, 482, 'An emotional journey of a pet cat, very humorous writing and challenging yet fun platformer game. Controls are sometimes clunky but it''s bearable. You can slap mouses and have to sneak past dogs to reach your destinations. Recommended to purchase on a sale.\n\nhttps://steamcommunity.com/sharedfiles/filedetails/?id=3356817929', 'graphically, it''s cute and pretty, but it controls like an absolute nightmare. jumping momentum is inconsistent, and you instantly pass out from falling too far, despite BEING A CAT.\n\nit''s lovely that profits from the game go to charity for cats, but the game itself is flawed.\n\nI won''t deny that it has a lot of heart, but I can''t recommend it for its gameplay.', 'Very Positive', 82.78, 13.43, 0.58);
INSERT INTO reviews VALUES (5258, 409160, 110, 'One of the best heist games I''ve ever played! The setting of the beautiful mansion and the lighting was amazing. The ambiance, was amazing too, with the creepy voices in the elevator setting the mood quite nicely!\n\nTruly an experience to be remembered! 10/10!', 'Essentially the stanley parable disguised as a stealth game, minus the witty dialogue.', 'Overwhelmingly Positive', 95.45, 1.25, 0.38);
INSERT INTO reviews VALUES (5262, 409320, 140, 'The environment is good, the story is cliche and the combat is average. But overall the game is quite nice, although it has a lot of empty space and walking back and forth. When you get to the end of the game you REALLY know the ship. I would have preferred a smaller and more focused experience, but it''s cool nonetheless.', 'A rough game.\r\nGreat scary athmosphere, but not worth the poor combat and constant backtracking.\r\nLevel design is full of invisible walls that you will constantly snag on.\r\nEnemies dont take much damage from inviromental hazards and glitch out on predictlable obstacles.', 'Mostly Positive', 73.57, 8.87, 3.87);
INSERT INTO reviews VALUES (5268, 409450, 369, 'I think i like this one even more than Legend of Grimrock now, while in Grimrock you needed to do pretty much everything manually, this one give you an option auto attack enemies and put skills in a queue.\r\n\r\nThe game also have 4 classes with 3 different specializations with a skill tree for each, so the gameplay goes pretty deep, and i really like the plot, you control a group of prison guards that need to venture in a dungeon full of monsters to hunt down the escaped criminals, who are all dea', 'I love old school revivals, but this is somewhat misguided.\n\nThe encounters are designed around a very specific party setup to an extent that if you don''t have that setup, you have no chance against bosses.\nThis leaves little freedom of choice and for me that''s a no-go in this kind of game.\n\nI would have refunded this but unfortunately you''ll find out too late how linear it is.', 'Very Positive', 84.28, 11.02, 4.28);
INSERT INTO reviews VALUES (5275, 409590, 2368, 'Do not be swayed by these nerds complaining the game is abandoned. What is here is good. If you think the concept looks interesting and think you''d enjoy it, you most likely will. Let''s not forget the game is only $10 and a lot of the negative reviews have 20-50+ hours (that many hours on a $10 game ain''t bad imo). Leaving negative reviews SOLELY because the dev is rumored to have lost his life after being drafted into the Ukraine military. \r\nThe concept is insanely ambitious and works exactly a', 'Game is dead.\nNo updates in years.\nDo not buy.', 'Mostly Positive', 70.40, 7.43, 6.55);
INSERT INTO reviews VALUES (5276, 409600, 110, 'Contract With The Devil\n\nHas a total of 7 trading cards.', 'Buggy, $hity, point and click/find the hidden object game. Don''t even know how this got in my library.', 'Mixed', 67.27, 1.28, 5.32);
INSERT INTO reviews VALUES (5279, 409660, 501, 'Cowabunga? Cow-a-fuckin''-piece-of-dog-shit!', 'Controls are diarrhea fuck farts.', 'Very Positive', 93.01, 2.28, 9.67);
INSERT INTO reviews VALUES (5282, 409710, 23757, 'An awesome game with a few tricks and twists to the storyline that make it unforgettable. The graphics have been enhanced for the remastered version with support for 4k. Music is old fashion and adds to the atmosphere of the game. I really can''t say enough about this game and sorry for the short review but I had to post something. Enjoy and highly recommended\n1', 'The changes to the TOS relating to the unwanted mandatory download of the 2k Launcher are unacceptable.  This is an eight year old single-player game and these changes fundamentally change the nature of the product I bought and pose an unnecessary  and unjustifiable privacy and security risk, and waste my computer''s system resources and intenet bandwidth.  Unfortunately, 2k has now joined the growing list of game publishers I won''t do business with.\n\nAnd to those who point out that Steam is spyw', 'Very Positive', 80.84, 108.38, 1.55);
INSERT INTO reviews VALUES (5283, 409720, 10710, 'Ah yes, Bioshock 2. The black sheep of the family if only because it wasn''t directed by daddy Ken Levine. Some people argue that "it''s just not the same", others say that Bioshock 2 is actually the best game in the series. \n\nI personally think it''s the latter. Bioshock 2 does everything Bioshock 1 did but better. Combat feels much more refreshing and dynamic. The story feels more personal and emotional. And we get to see Rapture not only in different places but from different angles too: be it o', 'The game crashes randomly time to time and there is no real solution to fix this. Either ruining the immersion to save every 5 minutes or get used to lose hours of gameplay..', 'Mixed', 69.38, 17.40, 27.63);
INSERT INTO reviews VALUES (5286, 409850, 290, 'Don''t hear a lot of people talking about this one but it is good.', 'Censored......wish I knew before I bought it', 'Mostly Positive', 75.52, 4.07, 4.07);
INSERT INTO reviews VALUES (5287, 409870, 389, 'Phantom Brave 2 is real', 'This may be the worst game I''ve ever played in my entire life. Game does extremely little to explain why you only get 4 minions to summon at the start, and why literally only one of them, Ash, makes any difference in the fights. The other 3 minions are literally garbage that do 0-1 damage per hit. Not only that, your minions will disappear on you after a certain amount of turns, and you can''t summon any more. So you just have to close the application or wait til your inevitable death. Literally ', 'Very Positive', 86.38, 61.62, 1.03);
INSERT INTO reviews VALUES (5288, 409890, 258, 'I finished this game twice. I loved it.', 'For reference my favourite in the genre is the Elminage series; It''s a shame because Strangers of Sword City is almost there with decent ideas and game systems but it just didn''t click with me. I realized after a while I was just grinding for stupid loot boxes that never gave me what I needed to gear up the Nth frontliner that replaced a previous one that was sent to the hospital for the next 5 hours of play. The feeling of never really moving forward is what killed the fun for me.', 'Mixed', 68.99, 65.90, 14.37);
INSERT INTO reviews VALUES (5289, 409910, 131, 'It''s a game that is fun to come back to after trying a whole lot of other tactical turn based crpg''s that were either too complex or too unforgiving. Oh, and can you save mid battle.... of coarse you bloody well can (other developers please take note).', 'It has it''s moments, but suffers from being way too repetitive, with almost no tactics/strategy in combat. Almost every encounter plops you down right in front of the enemy group, and you just rush in and start using cooldowns. During my playtime I only saw 2 fights that didn''t follow this formula, and in the end they didn''t play all that differently due to being a long corridor rather than a giant square arena. The game feels like playing a turn based MMO, so if you''re into that sort of thing, ', 'Very Positive', 83.21, 76.73, 23.98);
INSERT INTO reviews VALUES (5293, 410110, 1068, 'I used to play this with my dad before he left us. Now I play it with my mom and we can call it full family project now. Since me and mom now the real family!', 'I remember buying this game years ago and not liking it very much. I finally got around to doing a full playthrough just today and overall, it''s not a bad game but it''s also not that great either in my opinion. This game has some of the clunkiest combat mechanics of any Hotline Miami like that I''ve ever played. Most of the weapons require you to manually load them by right clicking before you can shoot by left clicking which is hard to get used to early on. This game also has a rather unusual re', 'Mostly Positive', 74.91, 4.57, 9.78);
INSERT INTO reviews VALUES (5297, 410210, 249, 'Ampersand\n\nHas a total of 5 trading cards.', 'A poorly made racing game with terrible controls and over the top, blown out visual effects. There''s no way to rebind the controls from X/Z/arrows or use windowed mode, as there''s no options menu at all. The game doesn''t tell you how to play or what the controls are, just drops you right in. It''s buggy, boring, and not worth your time or money.', 'Mostly Negative', 29.72, 0.95, 3.73);
INSERT INTO reviews VALUES (5298, 410320, 5687, 'Its a good game but it has a lot of bugs', 'tried solo, was kinda boring\n\ntried online, was called slurs and got told to go fuck myself\n\ncool experience i guess', 'Overwhelmingly Positive', 96.48, 10.95, 1.93);
INSERT INTO reviews VALUES (5300, 410340, 5640, 'This isn''t a ''Game'', it''s more of a training simulator. You ''Will" need a real radio (RC Controller) to fly. Trying to use a game controller will make you pull your hair out and quit using the SIM. Now, if you are willing to get something like a Radiomaster Boxer Crush, you''ll be ready for flying against other people, or flying a real FPV. If you can fly a Line of Site drone (DJI) and thats it, You can''t fly an FPV until you practice on something like this. This SIM is super realistic. two thumb', 'awful tutorial .dont enter calibration mode,theres no back button ,you need to restart the game to continue.while in the game theres no menu button(yep,you need to restart to continue),default senitivity is too high(atleast on DS5 and on Steam Deck.fix these stuff!cmon those have existed in the game minimum 2years', 'Very Positive', 94.88, 40.53, 1.23);
INSERT INTO reviews VALUES (5303, 410430, 116, 'Is good', 'This game was confusing as hell. The English is horrible. At the end of the game the names got switched around. This has to be the weirdest game i ever played!.', 'Mixed', 57.76, 4.97, 4.23);
INSERT INTO reviews VALUES (5309, 410670, 736, 'Cool, different and old school looking game.', 'i got stuck in an area because whenever a random encounter occurred the game would crash', 'Very Positive', 91.03, 2.52, 2.90);
INSERT INTO reviews VALUES (5310, 410710, 1193, 'I’m captivated by how this creation still holds up after 30 years (even in its remastered form). \n\nAn immersive sim-shooter set in its own isolated world (a spaceship, in this case), yet it feels like an open universe. I love how smoothly it plays, staying faithful to the formula it pioneered. It’s remarkable how its legacy continued through the BioShock and Dishonored series. As Ken Levine aptly put it, “the spirit of System Shock is this: the player drives the game, not the designer.” \n\nAnd ev', 'System Shock Classic: Unbearable. Movement is incredibly inconvenient.\n\nSystem Shock Enhanced: At least I can move, but I still can’t properly look around. Half the screen is cluttered with UI, and the fake 3D sprites rotate like cräp.', 'Very Positive', 91.11, 1.32, 0.15);
INSERT INTO reviews VALUES (5313, 410820, 245, 'It''s pretty fun but not that hard. It''s definitely a bullet hell, don''t get me wrong, but with the vast majority of bullets being slow, it isn''t too difficult. There''s lots of enemy, boss, and item variety, especially when you factor in the DLC, with each enemy being unique. The only major gripe I have is that primary weapons don''t drop very often. I only get one or two per run if I''m lucky. \n\nPick it up when it''s on discount, it''s still a pretty decent game.', 'It''s not a bad game for a run or two, but it suffers from the same one-two issue combo as most roguelikes: balance is non-existing, yet there''s not enough difference between different runs.\nAlso it can be very hard to tell apart your bullets and the enemy''s bullets, even with fairly basic weapons: with certain weapons/upgrades/friendly drones, you''ll be lucky to even notice there''s an enemy somewhere under the 100s of overlapping effects.', 'Very Positive', 90.61, 4.12, 40.48);
INSERT INTO reviews VALUES (5314, 410840, 217, 'Fun but too difficult at times to advance and you have to start over. Really cool concept overall.', '"No we are no longer working on Rock God Tycoon (actively) and we have both since moved on to new projects/jobs."\n\nAnd yet the game is telling me in a popup right at the start that you are still working on it.', 'Mostly Positive', 72.35, 26.62, 5.43);
INSERT INTO reviews VALUES (5315, 410850, 560, 'A very energetic and funny "Warriors" game. Slash away at thousands of monsters while listening to light-hearted and inspiring dialogue. The controls are very responsive and the action feels good. A game worth your time despite its age!', 'DO NOT BUY IF YOU''RE ON WINDOWS 8/10/11 AND HAVE AN NVIDIA CARD!\n\nIt refused to start even after I did all the recommended fixes, by trail and error I discovered it would start if I disabled "Full Screen" but it looked like trash and there is no "border-less" mode. Couple of minutes in it crashed so bad I had to reset the computer and that is as far as I''m able to "play" the game.\n\nKoei Tecmo knows about these issues but only warns you AFTER you bought the game that it will be unstable on anythi', 'Mixed', 64.11, 7.03, 0.25);
INSERT INTO reviews VALUES (5316, 410890, 756, 'Mion best girl', 'horrible ass loli content ass fanservice ass what the fuck is the point even the plot is actually good so why. literally disgusting', 'Overwhelmingly Positive', 96.69, 29.10, 1.35);
INSERT INTO reviews VALUES (5317, 410900, 7814, 'I love this game, this game doesnt love me. I build a nice fort and try to defend it. Players seem to enjoy breaking my stuff. Im terrible at the game but i have fun. Great fun. Highly recommend', 'I recently played Forts, and I honestly don''t understand the hype around this game. The concept seems promising at first—building and defending forts while launching weapons at your opponent''s base—but the execution is seriously lacking. The controls feel clunky, and the building mechanics are unintuitive and frustrating. It often feels like the game punishes you for experimenting with different strategies, and the learning curve is unnecessarily steep.\n\nThe matchmaking is terrible too. I kept g', 'Very Positive', 93.32, 510.12, 13.53);
INSERT INTO reviews VALUES (5319, 410970, 320, 'This is an outstanding game. I have played it many times since it''s original release, and it still is a great game. Once you master it though it is a bit easy to beat, and the harder levels just mean that the AI enemies cheat a lot, but still fun. As great as this game is, the remakes are not awesome (the new MoO is good). Remnants of Precursors is the true evolution of this game, play it, its good.', 'Can''t load DOSBOXConf to improve it. I started with the modding guide on Steam, but given the tedium and lack of skill, I can''t even get to step 1. Need to find a fix for a fix for a fix. You need to understand your system and the DOSBOX program well enough to make them talk, so it''s not as simple as reading the steps. \n\nIt''s a great game, I got hooked, but in that hooking, I recognized I wanted the improvements. It runs, but there is a lag that will get to bug you after a while. Sadly, I''m goin', 'Very Positive', 90.31, 359.32, 1.65);
INSERT INTO reviews VALUES (5320, 410980, 1138, 'Legendary. Started playing it again recently and I wondered "when did we stray so badly from the nice path we were upon", as a civilization', 'Amazing game but it all of a sudden stopped working, and Valve/Steam is absolutely of no use. I have stopped buying games on Steam due to situations like this.', 'Overwhelmingly Positive', 96.22, 451.35, 205.43);
INSERT INTO reviews VALUES (5321, 411000, 474, 'Sorcery 1 is without a doubt my favourite videogame EVER. \nVisually, narratively and audibly it''s a great game with an encapsulating story. \n\nBut there is something extra, that just makes this game so special and precious to me, a feeling of pure nostalgia and emotion. I don''t know what it is that makes me feel that way, but something about it takes me back to my childhood and revitalises my imagination and fantasy. It''s classic, it''s obscure and it''s charming!\n\n10/10 The perfect game for me. \n', 'I actually think it''s kind of scummy spreading the different story parts across multiple games so if a person only bothers to negatively review one, the others'' reviews still remain positive.\n\nThe game is boring. Read my part 3 review if you want to know more.', 'Very Positive', 91.14, 27.57, 7.45);
INSERT INTO reviews VALUES (5324, 411080, 150, 'Kinda like a FPS Pac Man\n\nThis is another one of them little time killers ! The game is like Pac man and the movie The Running Man lol You need to run around blasting all that moves or blast anything in your way. You then collect the orbs White Points , Green Health and Red Rockets.\n\nThe Dev or Devs are still adding and Tweaking it atm but it runs pretty sweet as is. I think for the $0.99 cents price tag this is one you might want to pick up and im sure in time they will add more but if not its ', 'Unfinished crap.\nDoesn''t even have a proper gamemenu, and the game slows down randomly, and that''s totally annoying.\nDefinitely don''t buy it!', 'Mostly Positive', 75.33, 0.48, 0.50);
INSERT INTO reviews VALUES (5327, 411300, 5025, 'My wife said if this review gets 50 likes or 5 awards, she will buy a case of beer, guys help me out', 'For reasons that don''t matter here, I replayed Gothic and Gothic 2 just half a year ago. Those are old games, very old. The graphics are dated, the UI is obsolete, there are no autosaves, and so on. But they''re just so much better designed.\n\nElex is clearly a spiritual successor, but the graphics are the only thing that make you realize it was created much later. There''s no pacing here, and no progression. The story is a mess. The dialogue is long-winded and seems to take ages to get to the poin', 'Mixed', 67.82, 53.08, 3.50);
INSERT INTO reviews VALUES (5328, 411310, 114, 'If you like hardcore, oldschool RTS, with NO base management, but developing units, this one is for you.\r\nIt''s an old game, but runs smoothly, the resolution is ok :)\r\n\r\nFinally found a gem, what has a proper single player mode, with story and everything.', 'Mediocre and outdated. Game is over 20 years old and it shows.', 'Very Positive', 87.72, 9.73, 0.12);
INSERT INTO reviews VALUES (5330, 411330, 316, 'Dear Mr. and Mrs. Roland Shepard:\r\n\r\n         This is one of the most difficult letters i have been required to write.', 'This game hasn''t aged well. I got sick to death of the sudden deaths from enemies that just all hone in on you and ignore your AI squad. The same AI squad who don''t do anything other than force you to take point and yell "help me out Shepherd!".\n\nIt was made at a time when a lot of PC first games started to experiment with console first releases. Much like Deus Ex: Invisible War, Call of Duty 3 and Brothers in Arms it features clunky controls, terrible FOV and bloated crosshairs which are woeful', 'Mixed', 69.30, 1.73, 2.78);
INSERT INTO reviews VALUES (5333, 411370, 1624, 'Super awesome and cool game but i hate that stupid cat if ur gonna buy it for that cat don''t do it you should buy it for kohaku instead she is better', 'a super crummy fighter', 'Very Positive', 94.89, 658.63, 2.27);
INSERT INTO reviews VALUES (5339, 411560, 881, 'Great underwater puzzle-platformer game with a high emphasis on exploration. The experience is really short but extremely satisfying. If you like the kind of lovecraftian underwater, cosmic, oppressive horror, you''ll enjoy it for sure. The sound and the atmosphere it creates with the lo-fi pixel art art-style is superb. Sadly, the game has lost support from the developer, and you have to go through some hassle to make it run, but if you leave that aside (which is totally solvable with guides her', 'broken rn?', 'Very Positive', 82.29, 2.05, 2.27);
INSERT INTO reviews VALUES (5340, 411570, 144, 'A fun but difficult zombie chose your own adventure style game. \r\n\r\nMy first playthrough was based off of decisions I would have made in each specific situation and experienced my first death on the Oil Rig, around the games midpoint. I ended with ''Ending 4'' out of 9 possible endings. \r\nThe single start to finish run took me six hours of gameplay and Just one Steam trophy - I could see collectors easily getting frustrated with this game. \r\nThe most impressive thing is how much tension a text bas', 'Okay game. Needs a method to track what you have already seen. Lack of save states is cool at first but becomes frustrating if you want all of the achievements.', 'Very Positive', 84.03, 12.37, 45.65);
INSERT INTO reviews VALUES (5352, 411830, 1668, 'Someone asks me my favorite game\n\nBorn to say Senran Kagura\n\nforced to say Elden Ring \n\nEdit: I do not regret 100% Senran', 'wtf is this shitty camera system, shit gives me an aneurysm', 'Very Positive', 94.96, 73.75, 1.12);
INSERT INTO reviews VALUES (5356, 411960, 2209, 'Honestly, this game was my childhood growing up back on PS2. It was refreshing to play it again. I highly recommend this game to anyone!!', '13 hours wasted, was at 99% completion died for the first time and turns out hardcore mode isn''t just a hard mode in fact it just deletes your save file NO WHERE DOES THE GAME TELL YOU THIS. Beyond pissed off that i just wasted my fucking time. Don''t buy till the DEVS TELL YOU THAT DYING DELETES YOUR SAVE!!!!!!!!!!!', 'Overwhelmingly Positive', 97.96, 0.93, 13.37);
INSERT INTO reviews VALUES (5357, 411970, 624, 'THE UNDER RATED GOAT', 'Too easy to overwrite a save, not even a dialogue box to ask if I''m sure. I just permanently lost 27 hours worth of gameplay because of a simple mistake I made while looking away for a split second.', 'Very Positive', 94.39, 1.87, 26.98);
INSERT INTO reviews VALUES (5358, 411980, 201, 'ahhh my child. it may have been crappy but its my crappy.', 'It''s the second game all over again just shorter and worse. Frankly, it feels like a DLC. They didn''t bother improving any of the gameplay issues, they just added more. The crab vehicle you use to navigate the hub area is a clunky mess. Half the missions are awful racing, while the other half are some mech suit levels. The developers were so utterly lazy, that they decided to recycle every single mech level, forcing you to access each of them twice with an alternative mech. The only positive I c', 'Very Positive', 81.59, 2.05, 19.93);
INSERT INTO reviews VALUES (5360, 412020, 31807, 'Metro Exodus is a masterpiece. Only the silence of the main character is a major problem. The game has breathtaking artistic direction and visual quality. The staging is exceptional, it allows one to drawn in abyss deep characters. It is tough to imagine a better adaptation for the novel of Glukhoovsky', '3 hours in and im still watching unskippable cutscenes with terrible dialogue. fuck you anna', 'Very Positive', 86.94, 83.17, 3.93);
INSERT INTO reviews VALUES (5361, 412050, 287, 'I bought this game yesterday, I genuinely enjoy horror genre games, the Clive Barker games, Doom, Resident Evil, whatever. Left4Dead was probably my last really passionate survival game(s) I spent way to much time playing. I am a 40 year old gamer and really don''t get rattled by much. Let me just say, I was NOT prepared for how immersive this game was in VR. My very first play session lasted about a min, I got overwhelmed with Zombies and I actually said NOPE and took the headset off. I had to a', 'HordeZ is a VR zombie shooter that''s more like a buggy, repetitive snoozefest. The graphics are so bad, you''ll think you''re playing on a potato. The controls are so clunky, you''ll feel like you''re trying to dance the tango with a zombie. And don''t even get me started on the AI. These zombies are dumber than a box of rocks.\n\nAt £12.99, HordeZ is a total rip-off. It''s basically a VR tech demo that''s been stretched out to fill a few hours. If you''re looking for a fun and immersive zombie survival g', 'Very Positive', 84.67, 12.47, 0.30);
INSERT INTO reviews VALUES (5375, 412460, 113, 'This game is great.  It''s got a good balance between being challenging and allowing you to build & design your village.  One of my top favorite games that I can play on Linux.', 'Not a bad game, but, at the end, a "copy and paste" of Banished.\n\nThey are quite... the same game!\n\nBut Banished is more polished and complex, and have a better price.\n\nThis game could be worth of playing only at the half of the current price, not more.', 'Mostly Negative', 38.05, 56.43, 0.53);
INSERT INTO reviews VALUES (5379, 412520, 158, 'Very good game, simple to learn but allows a lot of different ways to win and lose. Very enjoyable.', 'Not a very good TD game, have to grind the same levels over and over to earn enough points to upgrade your towers to be able to beat the next level, maps feel identical to others in it''s same "zone"\nKingdom rush is a better TD.', 'Mostly Positive', 72.15, 34.43, 0.98);
INSERT INTO reviews VALUES (5387, 412670, 313, 'Do not let this game name deceive you, this game should be named Bullet Hell 2 instead. After completing all the stages on heavenly mode, all I see are flashes of bullets and explosions. Bullet Heaven 2 is suitable for all kinds of players, with 3 modes ranging from normal to heavenly. There are many characters and level customisations, you can also customise how you earn points as well. Although this is an old game, it is still a hidden gem and you can tell that the developer put his heart into', 'In spite of being called Bullet heaven, its really just a bullet hell.\r\n\r\nWorks fine on steam deck, though there is no 16:10 ratio resolution option.\r\n\r\nFunctionally fine, just not for me, a bullet heaven in this setting would be fun though.', 'Overwhelmingly Positive', 98.08, 37.98, 3.47);
INSERT INTO reviews VALUES (5389, 412740, 2123, 'good in its own right, but its track generation is what really elevates it. removes the roulette of whether a song i like has a chart in other rhythm games.', 'Idk if I missed something, but this was a pretty poor VR experience. The ui is very unconventional and primitive, the gameplay was very lackluster, and playing to the beat never felt very impactful. Even the music was meh. Nothing really to write home about. The shield gameplay would''ve been great if used in a different game and refined a bit. The core gameplay of the shield feels pretty good, but not enough to redeem the entire game. Overall just feels like a discount Beat Saber and even then i', 'Mostly Positive', 79.60, 7.22, 0.77);
INSERT INTO reviews VALUES (5391, 412770, 296, 'boogerman', 'Not scary and not really fun, to be honest. You''re just stuck on your bed pointing at things. The monsters are kind of cool, though.', 'Mostly Positive', 79.39, 1.52, 1.05);
INSERT INTO reviews VALUES (5392, 412830, 4314, 'If you’re feeling depressed or mentally exhausted, this visual novel is perfect for you.\nIt’s a relaxing and beautiful story about a group of young people enjoying themselves under the pretext of scientific experiments, with nothing bad happening to them at all.\nThe characters are very charming, and thankfully, nothing bad happens to them at all.\nThe ending is also excellent (and, nothing bad happens to them at all).\n\n', 'I made it 19 hours in, then it occurred to me that I didn''t care what happens to any of these characters.', 'Overwhelmingly Positive', 95.60, 59.73, 19.30);
INSERT INTO reviews VALUES (5393, 412880, 1422, 'My gambling addict friend said if I post a review on Drift Streets Japan and it gets 350 likes and 150 Awards that he will buy me a case of beer and some vodka So im just gonna leave this here.', 'who could have anticipated that the $5 game that is constantly on sale for $0.49 has stolen assets??', 'Mixed', 59.99, 4.17, 5.85);
INSERT INTO reviews VALUES (5399, 413150, 352037, 'Fun and peaceful game. It never gets boring with all the additions. I am 58 and have tried to play other games but often get stressed out but I feel quite calm and relaxed playing Stardew Valley, it is better than all the others! Thank you.', 'this game will ruin your life, thanks to my addiction to this game, my GF left me, I lost my job, and I now live in an old van, selling plasma and delivering pizzas.', 'Overwhelmingly Positive', 98.91, 92.40, 3376.83);
INSERT INTO reviews VALUES (5402, 413410, 14606, 'I would 100% recommend. This was my first visual novel and let me tell you it did not disappoint. The story is really compelling, shocking, and has a ton of twists. All the characters have depth to them and overall all of them feel like fully fleshed out character. The game play is also pretty good, the controls are good. Overall if you haven''t I would 100% recommend playing.', 'It''s so ass', 'Overwhelmingly Positive', 95.82, 20.30, 66.83);
INSERT INTO reviews VALUES (5403, 413420, 11457, 'Danganronpa 2: Goodbye Despair was so good now that I finished each and every part of it, I am left with the feeling of loss and emptiness. I really wish I could replay this game again ugh. The characters and story were just so unique and the mystery surrounding this island made this game so fun. This is peak danganronpa and I inhaled this game so fast and just couldn''t stop. Every mystery was so well thought of, the minigames were so pleasant and didn''t feel like a chore, magical monomi was..ok', 'Don''t buy this game. It will install a virus into your brain called liking Komaede Nagito.', 'Overwhelmingly Positive', 96.23, 67.70, 81.00);
INSERT INTO reviews VALUES (5414, 413710, 748, 'I can''t plunder enough to fund my 20 spanish pikemen help me please, the food is starving, I''m running low on men, my water bottle is bankrupt, my funds are dry\nShit''s fucked', 'I bought this game when i came down bad with a serious case of wanting to cosplay a sexy pirate doing epic pirate things. It looked mount and blade-y which i thought would be great but my god it''s a terrible game. It''s boring, unintuitive most of all, and in all the ways original mount and blade was but somehow worse.\r\n\r\nlike the features it has feels like they should be good but they really aren''t. You can have a mount and blade ship battle and swing from the rigging to board other ships, you c', 'Mixed', 57.62, 9.32, 23.02);
INSERT INTO reviews VALUES (5422, 414080, 134, 'I really love working on this game!\nIf I stop loving it, I''ll change my review.', 'Crashes upon starting, after the Unity Personal Edition logo flashes.', 'Mixed', 50.00, 0.80, 7.32);
INSERT INTO reviews VALUES (5424, 414120, 173, 'good game but never seen a update', 'Its ok. I know what it says on the tin, but this is _really_ just a bunch of physics minigames. The physics are not that amazing either.', 'Very Positive', 85.55, 0.78, 0.20);
INSERT INTO reviews VALUES (5427, 414190, 337, 'The longer you play the more the game crashes.', 'I feel somewhat bad for leaving such a negative review about a game I played and enjoyed all the time on mobile several years ago, but I don''t recommend playing this game in 2024. This game has died a long time ago, and while there are some cool gimmicks about it, it''s simply far too tedious and bland. It also hurts that this game is VERY achievement unfriendly, and it''ll take you 250 hours at MINIMUM to get all of them, which I find to be incredibly stupid. If you REALLY like sandbox games and ', 'Mostly Positive', 77.15, 131.85, 319.87);
INSERT INTO reviews VALUES (5430, 414340, 27684, 'Okay, so this is a game helps to understand how it feels like when suffering from a mental illness.  The constant whispering and illusions are definitely damaging the sanity.  The lacking of clues on sealed doors, unexplained portals and broken paths are not helping either.  Maybe there are clues in the whispers, but I’ll rather keep them muted.  In the end, I have to play a few adult games to lift my spirits before coming back to finish the game.\n\nAchievements are not missable except for the No', 'I have no clue how this game is "Very positive".\nThe graphics and cinematic are good, if this game was a movie, it would be good.\nHowever, this is not an actual game, it is merely a walking simulator with spaced boring repetitive fights and time consuming puzzles.\n\nIf you really want to experience the game, just watch a youtube playthrough and save your time and thumb finger (from holding the joystick forward)', 'Very Positive', 90.12, 10.75, 0.90);
INSERT INTO reviews VALUES (5435, 414510, 270, 'The best two-player and chill game that can be played.', 'When you die, you lose things from your inventory. Sometimes, this is a health kit, or energy, or ammo. Sometimes, it''s parts. \r\n\r\nHowever. It can also be parts from fully constructed guns. You need all three parts of a gun for it to function. If you die, you can lose an extremely vital part of your weapon and become entirely defenseless. Buying a cheap part also won''t work- You get an enormous 40% damage penalty if the parts have enough of a level disparity.\r\n\r\njust why', 'Very Positive', 82.22, 33.13, 9.60);
INSERT INTO reviews VALUES (5438, 414660, 208, 'This is an old hidden object puzzle game, that bases itself on a story about vampire attacks on a small town. It''s straight forward and engaging. The art is of it''s time but it''s very pretty, the characters are quite b movie in their deliveries which may make you laugh occasionally. \nHowever the art is a bit fuzzy and can make getting the hidden items difficult, it''s short like allot of these games so you will blast through it.\nOverall this is a nice game if you like Gothic horror and vampires, ', 'Very old, the scenes are poor quality, and the voice acting is very bad. It''s outright difficult to tell what you''re looking for because the scenes are so compressed and grainy. The sound mixing and the recording quality of the voices is also terrible, even without the amateur acting of the VAs.', 'Very Positive', 86.54, 5.85, 3.02);
INSERT INTO reviews VALUES (5439, 414700, 9137, 'Outlast 2 is a game where you play as a hard Christian believer who goes to an atheist community to purify and convert them all into good god-loving Christians.\n\nit''s perfect for educating your children about the bible.\n10/10', 'A Frustrating Horror Misstep\r\nOutlast 2 aims for unrelenting terror but stumbles into frustration. Set in a creepy Arizona desert with a disturbing cult, the atmosphere is grimly immersive, and the visuals are hauntingly detailed. But the gameplay feels like a relentless ghost train of cheap jump scares and trial-and-error stealth that wears thin fast. The constant chase sequences, paired with clunky controls and inconsistent enemy AI, make surviving more annoying than scary.  \r\nThe story, cente', 'Very Positive', 85.51, 756.08, 10.62);
INSERT INTO reviews VALUES (5440, 414720, 378, 'This is a great little game. If you''ve ever played Eve Online this is like a pared down single player off-line version of that. It''s a small download and works well.', 'Decent game, but rather simple, so many similar games are better including a different version of Astrox.', 'Very Positive', 83.86, 122.38, 24.07);
INSERT INTO reviews VALUES (5442, 414740, 1464, 'I used an AA Gun to blow open the doors to a bank. \n\nThen set Nazi Flags on fire to signal a bomber plane, in order to crack the bank vault open. \n\nIt was incredibly based.', 'Idk why but nobody plays it, 6 people online at 7pm 💀\nBot''s cant carry anything which makes missions take 3x the amount of time.\nI wish i played it at release with actual people but now it''s dead sadly.\n\nIf you wanna play it find 3 friends that are willing to play with you beforehand, otherwise avoid.', 'Mixed', 66.73, 44.35, 1.38);
INSERT INTO reviews VALUES (5446, 414920, 160, 'Corgi Warlock\n\nHas a total of 6 trading cards.', 'The game doesn''t show anything but a black screen for me, on Linux using Proton- so it''s completely entirely unplayable.\n', 'Mostly Positive', 76.88, 0.78, 4.28);
INSERT INTO reviews VALUES (5447, 414950, 118, 'If you''re like me and enjoy dogfights in space, smuggling pirated wares or just transporting trade goods to make the most profit available, this game is for you.  This top-down space combat/trade scenario gives you everything it promises.  It''s a similar feel to an old favorite of mine, Freelancer.  While (obviously) the game play is different given the 2d environment the combat is no less engaging, exciting and challenging.  Star Nomad 2 has a fairly robust trading system that keeps you interes', 'I really really really wanted to enjoy this game, as top down space shooters are one of my favorite types of game. Unfortunately there is nothing that this game gives that is not simply done better by another game. \nFirst off, the UI for the game is completely offputting and at times terribly obstructing. \nThe combat feels like a stripped down version of the combat from Starsector, but you are actively encouraged to avoid combat in the first few hours of the game because enemy ships will complet', 'Mixed', 68.64, 60.53, 1.42);
INSERT INTO reviews VALUES (5450, 415030, 240, 'Fun for cheap, the jump scares for monsters is actually more fun than youd think, not really meant TO be beaten but rather to see if you can make it to the next floor with a new character next time. 6/10', 'Quite an unfun and unexciting roguelite. I really wanted to play a dungeon crawler/fps/rogue hybrid, and i wanted to like it but ultimately, i couldn''t. It''s quite minimalistic, i don''t have a problem with that but it never manages to be entertaining. Limp and sluggish gameplay, little to no sensations, lackluster sound design and audio cues (enemies hidden in corners making no noise...), boring dungeons that are all more or less the same but somehow get progressively more annoying.  Playing One', 'Mostly Positive', 74.58, 2.23, 3.23);
INSERT INTO reviews VALUES (5455, 415170, 279, 'This is a relaxed game, though it may seem it''s trying to make you lose your cool. Chill out and enjoy the ride.\r\n\r\nBe advised, this can last as long as you want; still, the amount of levels puts this game as a short one, perhaps too short.\r\n\r\nI got this on a sale and wasn''t disapointed.', 'Badly designed puzzle game. Much of it is just trial and error. It develop general principles on such drawings. For instance, how radius proportion or frequency affects say the number of main humps or something to that effect. The position placement tool being imprecise also contributes to this. It''d be better if, for instance, you could create a precise subdivision at different radius. Even with the right solution its just trial and error to get it just right. Granted, programming something to ', 'Very Positive', 93.91, 1.95, 1.57);
INSERT INTO reviews VALUES (5457, 415200, 4944, 'The ultimate Motorsport Team Manager, much better than the officially licensed F1 manager.', 'The issue with this game, as it always is, is you do the work of a dozen people all at the same time.  Even though you hire a designer you have to decide how to design the car and which components to produce. You have to market your team constantly. You have to decide tire choice and do race strategy. I want to hire a designer and have them design the car. I want to hire a strategist/tire person. I want to hire a marketer. I want to run a team, I do no want to be the team.  All the components ar', 'Very Positive', 90.49, 35.50, 375.52);
INSERT INTO reviews VALUES (5461, 415350, 133, 'spanish or english ?', 'The memes are pretty cringe at this point and the achievements do not work.', 'Very Positive', 80.45, 5.08, 0.83);
INSERT INTO reviews VALUES (5464, 415420, 513, 'fun', 'A relic of the past that kept updating itself to the point of being detached to the original concept. \n\nThe base game was fun, and it''s a blast from the past in terms of nostalgia and references, but it is filled with too much bloat that I cannot recommend it.', 'Very Positive', 89.08, 8200.17, 1.17);
INSERT INTO reviews VALUES (5466, 415590, 751, 'Pretty fun.\nWent in not expecting a lot, but was pleasantly surprised.\nA game I can definitely see others having a good time with.', 'it keeps kicking me from the game when i start it\r\n', 'Mixed', 67.51, 2.67, 9.60);
INSERT INTO reviews VALUES (5467, 415600, 421, 'After Playing This I Went To My Local Track And The Kart Felt Too Arcade\r\n', 'Very basic and even though other steam games work fine this refuses to recognise my steering wheel/pedals, so the only way to play is with the keyboard, so useless.', 'Very Positive', 89.55, 104.85, 3.87);
INSERT INTO reviews VALUES (5471, 415740, 333, 'whybeare return to us my king', 'Don''t get me wrong, this game is a quirky little oddity on Steam, but it''s not fun to play. You, literally, just use the stick to steer an out of control bus you can''t speed up, slow down, or turn sharply (cos if you try turn in anything but 5 degree nudges, you flip over and end up having to restart the level). The time limits for medals in game feel insanely cruel, because how the hell am I supposed to go faster than "you can''t go faster"? And the whole hat gimmick and random theme levels? Not', 'Mostly Positive', 78.68, 7.28, 1.45);
INSERT INTO reviews VALUES (5475, 415850, 194, 'BAD END is an horror Visual Novel with multiple choices and 14 different endings.\n\nI''ll start this review by mentioning that the game is still relatively short, but nevertheless a solid 2-3 hours of playtime to get all endings. The artstyle is great, the music is relatively good too (the one track with banging on metallic railings is quite annoying to be honest xD) and the writing is alright. The writing doesn''t have any typos but it does feel very emotionless and it''s it could''ve been much bett', 'The concept is interesting, but it''s held back by predictable plot twists and bland death scenes.  Add in the short length and the abrupt, poorly-executed true ending, and there''s just not much I can recommend about it.  At best, it''s a cheap way to entertain yourself for an hour or two.', 'Very Positive', 82.47, 2.22, 1.43);
INSERT INTO reviews VALUES (5477, 415880, 434, 'Come yall let''s makes this game fun again', 'Just bought on sale. Played the game for 6 hrs during free weekend back in 2019, now I tried to refund it noticing that it doesnt have online multiplayer in function. Steam wont refund.. Sad. Great game but steam wild. I am only writing negative because I dont think you can enjoy the game without online features\n', 'Very Positive', 82.72, 0.67, 14.22);
INSERT INTO reviews VALUES (5480, 415920, 226, 'I played this game then immediately bought and played the next 3 games by this dev. Please help.', 'not fun', 'Overwhelmingly Positive', 96.46, 33.53, 12.32);
INSERT INTO reviews VALUES (5481, 415950, 127, 'Goat simulator with a loli', 'there is nothing to this game its just a unreal map that you can climb some stuff and hit some objects.\nits a small map this feels like playing a stundent project or something. from what little i played of the meme game goat sim that started this fad there is at least stuff to do and interact with in that.\nwe paying £3.50 for a baren map now boys?\nthe one pro is that one of the two npcs is based of that guy in the isnlanders shirt from the japanese gay porno meme so thats something\nshould have p', 'Mixed', 57.48, 0.28, 0.18);
INSERT INTO reviews VALUES (5485, 416000, 247, 'Eu não considerei ruim, apenas foi um erro ter encerrado o Early Access tão rápido.', 'I have put 500 hours into the game. Back when Hudell was in charge, I would have recommended it to the moon and back. I made a new save and replayed it every time there was an update. Once he stepped down, everything changed. The graphics were improved, but that was about it. \n\nThe controls feel terrible to play with. They redid the game on a new engine from the ground up, so the previous fluid controls were replaced with a clunky mess (at least on PC), that makes playing extremely frustrating. ', 'Mixed', 59.51, 2.55, 529.28);
INSERT INTO reviews VALUES (5488, 416060, 110, '⠀', 'Combat is awful and non immersive. You will spend a lot of time just being stunned locked by enemies. Especially in the later missions. The non immersive aspect comes from downing small groups of enemies with other groups paying no mind to you, regardless of all the gunfire. \n\nThe levels are all samey in both appearance and in game-play. The only strategy is, "move forward, kill enemy, move forward, kill two more enemies. Make sure to shoot enemy before they shoot you so as not to get stun locke', 'Mixed', 65.45, 14.98, 13.00);
INSERT INTO reviews VALUES (5489, 416080, 112, 'They said I''m goddess Athena.\nSo at 2nd level I sinked all ships, turned off game and went play with my divine boobs.', 'I always thought Athena was the goddess of war and wisdom, not wind. That aside, interesting concept but the controls feel kinda jank.', 'Mixed', 58.04, 2.33, 2.80);
INSERT INTO reviews VALUES (5495, 416190, 161, 'RIP Ilan Papini 1963-2024 Thank you for this great simulator.', 'Not a bad game but it''s a bit odd. I wouldn''t recommend it though due to its price. It''s not worth £18.99 any day if you got it cheap in a sale then fair enough.', 'Very Positive', 85.09, 20.85, 0.72);
INSERT INTO reviews VALUES (5497, 416210, 590, 'Unplayable on the Deck 🥴😟', 'a bit boring, one you built there is nothing to see other than your static building and production stats, this game should be more interactive and immersive like activity of people inside building, production animation, water should be flowing, tree should be moving if theres wind, sandbox should reward player with something challenging to achieve', 'Mostly Positive', 70.00, 28.73, 5.65);
INSERT INTO reviews VALUES (5509, 416380, 103, '\r\nSHOOT DA WOOP!\r\n', 'why do i buy bullet hells?', 'Mostly Positive', 72.82, 4.63, 4.80);
INSERT INTO reviews VALUES (5515, 416590, 914, 'emily touched me i dont want to play anymore', 'Do not trust her guys, she doesnt want to play :(', 'Mostly Positive', 77.02, 3.78, 1.58);
INSERT INTO reviews VALUES (5516, 416600, 957, 'Probably the best co-op experience that I’ve ever had. An underrated gem that has a lot more than meets the eye.', 'This game is cryptic as hell, and not all that fun to play.\n\nGood luck solving the puzzles on your own, I guarantee you''ll have to either look up the solution online, or spend hours trying to figure out what the heck they''re asking you to do.', 'Very Positive', 90.80, 2.17, 37.83);
INSERT INTO reviews VALUES (5519, 416640, 109, 'writing this so steam stops bugging me to write a review', 'As much as I love "choose your own adventure" games, I wouldn''t recommend this one.  Why?  Because while you''d think your choices would matter like in other similar games, they really don''t.  Most choices you face lead to the same exact results and I don''t mean it as in the long run.  Let''s say you have the choice between killing or not killing someone.  First run through you''ll go with one choice and next one pick the opposite choices figuring the story would be entirely different but no.  If y', 'Mostly Positive', 77.06, 3.63, 5.45);
INSERT INTO reviews VALUES (5521, 416680, 1036, 'i wish i could have sex with this game', 'its extremely fun at first, you begin unlocking abilities and variants and such, then it quickly ramps up in difficulty and becomes  extremely annoying to play because of its trial and error way of playing.\n\nif you want to play approx. half of the game, buy it. if you want to torture yourself with a game where a single mistake can end your entire run and force you to restart, since there are no save files, buy this.\n\npersonally, i never even could finish the last chapter\nmost of the community le', 'Very Positive', 92.57, 251.93, 17.80);
INSERT INTO reviews VALUES (5526, 416770, 726, 'Any puzzle game from Mathew Brown is a work of art.', 'Fun enough puzzle game - numbered tiles and lines showing the pure amount rather than the distribution add a world of deduction that is great to work through - but as is the case with all of Matthew Brown''s logic puzzles 100%ing it is made unbearable through the mistakes mechanic.', 'Very Positive', 89.81, 8.30, 5.40);
INSERT INTO reviews VALUES (5527, 416790, 216, 'Sleek artwork and interesting concept, mixing rhythm beat and battles\n\nGood quality and variety of music included, though the voice acting included is terrible.\n\nTerrible controls, especially if using joystick or in a Deck, and the battle animations do break the flow of the rhythm beats, so the only reason to get the game would be for the battle system, which is fairly interesting and certainly unique.\n\nOverall, overpriced compared to its full fledged competition. Passable, but not memorable. 6/', 'I had to rage quit after I couldn''t even finish the basic tutorial. No help on the screen or options.', 'Very Positive', 85.65, 7.73, 0.53);
INSERT INTO reviews VALUES (5531, 416870, 179, 'so good. sad there isn''t more. greatest thing since the hunger games.', 'The concept of the game is great. However, the game becomes unbearable when you unlock everything. Everything becomes repetitive and slow. But it is still playable :)', 'Very Positive', 91.62, 176.98, 34.08);
INSERT INTO reviews VALUES (5537, 417290, 1886, 'Good lord I love it. Been looking for stealthy games with intricate interiors, like Dishonored and Thief. They are few and far between. This game is awesome. Main character is so cute but I feel tense playing it. I feel like it''s a cross between Ratatouille and Halloween (a strange combo) with a Skyrim-y backdrop. Amazing', 'Game will not start on my computer.  I''ve tried reinstalling it 3x and it freezes on the opening scene with the flame.  I have not had this trouble with any other Steam games I''ve played.', 'Very Positive', 90.30, 17.20, 0.17);
INSERT INTO reviews VALUES (5544, 417750, 375, '👍', 'What attracted me to this game was the bright flashlight i saw in Left Alone''s clip on Steam.  But wait, erm, you''re not supposed to use the batteries all the time in the pitch black!!!  Yes folks, aren''t i silly, i used my flashlight all the time in the dark and ran out of batteries.  The flashlight was not bright for very long and i think it would have been more honest if Left alone had not made out that you used a bright flashlight. i will have to go back to reviewing games i like on Steam, o', 'Mostly Positive', 73.33, 6.62, 5.37);
INSERT INTO reviews VALUES (5546, 417860, 204, 'I put my name as Brad.\nJokes on you Emily.', 'you just listen to some girl complain about her problems', 'Very Positive', 86.27, 0.87, 0.57);
INSERT INTO reviews VALUES (5547, 417880, 1170, 'https://steamcommunity.com/sharedfiles/filedetails/?id=3316942498\nhttps://steamcommunity.com/sharedfiles/filedetails/?id=3314376586\nhttps://steamcommunity.com/sharedfiles/filedetails/?id=3313117591', 'Never have I wanted "Maybe" as a recommendation option this bad.  This is really, frustratingly, almost a very good experience if not for the glacial movement speed.  They claim movement is limited so you don''t miss things, but I DEFINITELY missed many things because I just can''t bring myself to ooze over the vast, beautifully detailed landscape to backtrack 14 times at the speed of a slime mold.  Whatever moron insisted on keeping it this way after doubtless serious pressure during testing shou', 'Mixed', 69.32, 4.10, 5.73);
INSERT INTO reviews VALUES (5553, 418030, 6651, 'This game offers the real survival concept. It''s hard and grindy (not for everyone) but hey if you really want a survival game that has great gameplay this is it. Building a base, farming, foraging, fishing, hunting, exploring underwater caves, and what I like most is raiding enemy base and looting a plane''s cargo. No zombies or wierd creepy enemies. It''s you vs. the wilderness. I wish the dev make a new content.', 'I like and have played several craft/survival games. This game however got the best of me. Maybe I''m just bad at the game mechanics...but I died, A LOT! Plus I made the mistake of placing my base about as far away from the spawn point as possible. So if the cold didn''t kill me (which it did several times) then the beasts who had leveled up by killing me many times before...when a bear or a wolf etc, kills you, they level up. Thus tipping the balance so that as you''re running back to your far awa', 'Mostly Positive', 70.32, 278.27, 7.05);
INSERT INTO reviews VALUES (5554, 418040, 309, 'This is a game I love to boot up when I''m tired or sick. It gives me something to do and relax with when I am unable to invest fully into a story or PvP.', 'The game itself is good. You can play for relaxing time. But the UI is bad!\n\nThere is no option to start game in window mode, or it is full screen only. There is a way to escape from full screen mode but that is inconvenient. \n\nEach menu shows only icon but no tips which is really bad because you have to click into it to know what it is and if you found that it is not what you want, you have to go back but all the process is very very SLOW!\n\nI would like to recommend this game but the UI is bad,', 'Very Positive', 88.35, 6.25, 1.72);
INSERT INTO reviews VALUES (5556, 418070, 1312, '-Full HD\n-60 FPS\n-No bugs\n-Many pugs\n', '\r\nAnother pug game which essentially is a mobile game where you jump only. Nope.\r\n', 'Very Positive', 92.15, 4.53, 4.03);
INSERT INTO reviews VALUES (5560, 418180, 755, 'A great looking game.  However when I tried to change the settings to make the game run more efficiently, the main menu got scrambled up, and I cannot play the game on the PC anymore.  I don''t know if it''s a bug or something on my end, but from the time I played the game, it is really fun and a lot better than Uncharted Waters Online in my opinion.  Especially in sea battle.  A lot more realistic.   If the issue I had is with the game, then I hope it gets fixed so I and others can continue to en', 'Why this gets a bad review is the random pop ups PAUSING you in the middle of play saying hey, check out our other game, absolutely atrocious and you should be ashamed to have such bullshit in your game. \n\nI refunded because of this.\n\nSo if you like random pop ups, this game is for you!', 'Mixed', 66.09, 3.82, 0.55);
INSERT INTO reviews VALUES (5561, 418190, 437, 'this game rules, it is short and efficient little micro rpg with a really unique battle system! the story is kind of generic but it''s still charming. \n\nat only six hours long and costing $2 it is extremely worth playing through \n\n(i played through the game using easyrpg so steam wasn''t keeping track most of the time fwiw it took me about 6 hours to beat)', 'As usual I find myself becoming increasingly pessimistic the more I play video games and I wonder why I even do so. This is probably one of the better designed games I''ve played that is RPG maker, and an actual RPG. the looks are charming, but I have to say that I loath the deterministic combat system. Everything about it reminds me of NWN1 or Eternal Senia or other games that give you exactly one character. As usual with all of these games, when they focus on turn based combat with arbitrary sy', 'Very Positive', 91.76, 0.08, 41.37);
INSERT INTO reviews VALUES (5562, 418240, 8745, 'This is a fun and difficult strategy game where you have to think a lot and watch the guards'' paths and pay attention to their field of vision, because if the guards find a body, they will keep coming over to patrol.\nThere isn''t a lot of gameplay in this game. Each mission does the same thing, just with different locations, paths, and number of guards.\nFor casual players, I would only recommend buying this game when it''s on sale.', 'Very boring game, RTS + sneaking + strategy games are not popular anymore in nowadays.\nThe most I press in this game is F5 and F8, I don''t even know what I''m playing, the game or pressing the keys.\n\nIf I have to save a file before I can do a certain action, and then depending on how the enemy reacts and the character dies, then I have to repeat the previous steps, so it''s just a test for mistakes, not a tactical game.\nThis makes no sense at all, this game is not entertaining in any way, it''s jus', 'Overwhelmingly Positive', 95.05, 17.63, 6.67);
INSERT INTO reviews VALUES (5563, 418250, 220, 'Distant Worlds 1/2 does not work on Steam Deck. Stardrive 1/2 does not work on Steam Deck. Sword of the Stars 1 does not work on Steam Deck. If you want an RTS/4x that isn''t Sins of a Solar Empire... this is pretty much your only option... and it runs great. The game is a bit buggy, but so is every space 4x.', 'Could''ve been successor to Space Empires V... but is abandoned game with playability killed by micromanagement (unless you decide to play small map) so in effect: a time waster.', 'Mixed', 63.64, 5.40, 117.63);
INSERT INTO reviews VALUES (5567, 418300, 198, '10 / 10 , i love this game', 'There really just isn''t that much to say about Wick. You wander around the woods and get jump scared.', 'Very Positive', 83.33, 2.28, 0.42);
INSERT INTO reviews VALUES (5568, 418340, 5902, 'Rwby and Blake I''d smash can''t lie', 'It was a cash grab (8 year later)', 'Mostly Positive', 79.14, 57.53, 14.23);
INSERT INTO reviews VALUES (5570, 418370, 24839, 'I was beaten, harassed, and captured by a man that looks like Walter White if Walter decided to try his own product.', 'I HATE THIS GAME!! I hate how it made me scream like I’ve never screamed before. this game doesn’t care about your nerves, your comfort, or your sanity. It just wants to scare the life out of you', 'Very Positive', 94.36, 5.38, 9.77);
INSERT INTO reviews VALUES (5572, 418440, 130, 'I enjoyed this. For less than a dollar on sale worth it, just wish it had achievements.', 'The music was the best part, and the family dynamics were cute, but it was really frustrating going from room to room just hoping something would happen, had to end up looking up a guide to even know what I was supposed to do.\n\nView more honest reviews on my youtube channel CozyAriGames <3', 'Very Positive', 90.00, 3.43, 4.72);
INSERT INTO reviews VALUES (5573, 418460, 26018, 'I hate this fucking game, I hate being shot at by people I can''t fucking see because every map fucking sucks.\n\n10/10, unbelievably realistic.', 'If you are looking at this review i''m sorry to say you missed this games glory years\n\n\nThe servers are empty, cheaters are everywhere and the voice chat no longer works. But back when this game was in its prime it was without a doubt the best Fps i have played in the last two decades, this game was indescribably fun. The dopamine i could get consistently from this game is only matched by something like halo 2. I am truly sad that this game will never see those times ever again and others will no', 'Very Positive', 89.24, 14.05, 515.57);
INSERT INTO reviews VALUES (5575, 418530, 13414, 'Spelunky 2 will make you loathe existence and question why play videogames in the first place. The level of suffering you will be inviting into your life when purchasing this game cannot be overstated. Agony has a name and it is Derek Yu.\n10/10 an absolutely excellent platforming roguelite, beat Cosmic Ocean or no balls.', 'compared to spelunky HD this game is just... not fun. \r\n\r\nspelunky was a very streamlined and straight forward experience, it was extremely hard, but rarely unfair and its short length was one of its strengths. spelunky HD was a game that seemed pretty shallow on the surface, but when you really got into it you''d start noticing how deep it actually is. the secrets, the mechanics, the tools and whatnot all played into what made spelunky HD so great, little of that is present in the sequel.\r\n\r\non ', 'Very Positive', 93.48, 537.18, 34.03);
INSERT INTO reviews VALUES (5577, 418620, 486, 'A really really fun campy side scrolling beat em up', 'The gamepad doesn''t work in this crappy game.', 'Very Positive', 82.30, 3.30, 1.70);
INSERT INTO reviews VALUES (5579, 418650, 2239, 'This is the game that made me buy a VR system.  Played it in a mall and went directly to the store.  Feels like being inside Galaga.  You shoot drones with a variety of handguns, with laser-bats and transparent shields for defense.  Buy it!', 'Really mid.', 'Overwhelmingly Positive', 95.13, 32.00, 0.28);
INSERT INTO reviews VALUES (5581, 418910, 127, 'If you like games like travian, tribalwars, imperia-online etc. but the idea of other people crushing your town when you were asleep or needed a week for work/study frustrated you. Or finding that you have nothing to do for a hour while resources are gathering.Well idle civilization is the anwser for you my friend! \n\nBuild things, let it run in the background for a few hours, then build some more. After making some progress you will be able to attack other NPC towns, go on an adventure with a he', 'Abandoned game, don''t waste your money on it.', 'Mixed', 45.67, 26.23, 3.30);
INSERT INTO reviews VALUES (5583, 418950, 325, 'Horor indonesia', 'I wanted to love these games because i go into part 2. but the trial and error is too much for just horror games. really kills the experience.', 'Very Positive', 82.46, 0.40, 8.57);
INSERT INTO reviews VALUES (5590, 419460, 979, 'Life-changing experience. Some of the hardest 2 hours of my life. \n\n100% would recommend\n100% don''t want to play it again\n\nThank you for making this', 'Oh boy. This is one of those cases where the straight yes/no binary of Steam reviews really just isn''t enough, as TDC is an experience where what you get out of it will vary *massively* depending on one significant factor - whether you are a Christian believer. \r\n\r\nThe story of Joel, a little boy with brain cancer that proves untreatable, and his family is elegantly and touchingly told through visual metaphors (the cancer as a dead and twisted tree in a tranquil wood, for instance, or the titula', 'Very Positive', 88.25, 2.08, 2.37);
INSERT INTO reviews VALUES (5591, 419480, 1866, 'Awesome game. It''s like Mount and Blade Bannerlords in space but you play as a big ass ship.', 'Unless you intend to play this on gamepad with nothing else plugged into your computer, don''t bother. Devs have apparently decided for us that we arent allowed to do it any other way. Could have easily enough included a line in the local config files that disabled controller, nevermind going the REALLY complicated route of prompting the user to select gamepad or m & k.\n\nFor the sake of clarity, this isnt a case of "I dont like playing with gamepad so I won''t". After hitting play from steam, game', 'Mostly Positive', 76.05, 40.15, 0.38);
INSERT INTO reviews VALUES (5592, 419520, 107, 'The game optimization greatly improved as the day of patch 06/19/2016, was well optimized, now it worth buying the game, I hope the developers release a lot of update, I hope that all who put their negative analysis so because of bad optimization, delete, and put your positive review to ensentivar developers and other players to play\n\nA Otimização do jogo melhorou muito como o patch do dia 19/06/2016 ,ficou bem otimizado,agora sim vale apena comprar o jogo ,espero que os desenvolvedores lançam m', 'do not buy the game the game is dead the devs have shut the game down you cant play it at all', 'Mixed', 42.99, 10.37, 1.93);
INSERT INTO reviews VALUES (5597, 420000, 1053, 'we used this to design our house for renovation instead of cad software lmao. Nice and simple, works like a charm.', 'This application used to work a couple of years ago. I tried using it again today after re-installing the software and found it to be completely unusable. Demo houses no longer load, menus fail to properly display (with infinite menus), and the main screen is completely black. This application is defunct and is clearly no longer being supported by the developers.\n\nThis game is abandoned. Other recent reviews also mention the black screen and infinite menus. Don''t waste your money.', 'Mostly Positive', 73.88, 40.17, 11.85);
INSERT INTO reviews VALUES (5600, 420060, 312, 'I was looking for games for my 4yo son to play and I found this one on a list of games for toddlers somewhere on the Internet and I must say this game is NOT for toddlers. Sure the art is nice and all for kids but the puzzles and game progression process actually requires the player to think what the developer might have done instead of just looking for clues.\n\nThis game is HARD and so nicely done!', 'I purchased this game years ago and only played for 30 hours so I decided to try it again wondering why I never played more. I started a brand new game to understand the game play mechanisms and then I realized why I stopped playing. I found this game extremely difficult to navigate the controls and movement of the character along with no clear direction as to what to do I found myself dying over and over with no way to get help from the game to understand how to progress. After about 20 min of ', 'Mostly Positive', 73.40, 15.50, 30.62);
INSERT INTO reviews VALUES (5602, 420100, 109, 'Only realistically worth it if you loved the base game AND when it''s on sales, as many other reviews point out it''s simply a bunch of audio collections with backgrounds and like an average of 4 drawings per episodes, with 16 episodes, they total around 6h of autoplay and doesn''t have any interactions, the stories mainly focus on the past and future of the characters and should only be considered a small DLC to the base game\r\n\r\nI genuinely think the funniest part about it is that it has performan', 'Incredibly dull and forgettable stories on forced auto mode. No thanks.', 'Mostly Positive', 75.23, 7.60, 0.13);
INSERT INTO reviews VALUES (5603, 420110, 2909, 'My arm still hurts from the first game, I swear if i could use both arms I could become a bodybuilder', 'The only thing that made me laugh while playing this game was Vanilla calling the MC a predator. Other than that, disgusting game. Main two catgirls pressure their sisters to have sex with MC. MC has sex with someone he sees as a sister. His little sister is pushy and happy with MC sexing up her "pet". Saying having sexual relates with your family members strengthens bonds... Of course the catgirls are okay with polygamy so MC can fuck them all! But wait, only with their sisters.', 'Overwhelmingly Positive', 96.91, 0.45, 18.73);
INSERT INTO reviews VALUES (5608, 420180, 116, 'It depicts the story in Lovecraft''s Shadow over Innsmouth quite accurately, although of course lacking many of the details. Thankfully, the old drunkard Zadok is in it. The ending is also different from the original. Overall, it is an easy-ish point-and-click adventure game with some tense live-action sequences. One specific sequence mirrors the famous ''live action'' part in the original story to a tee (you''ll know what I mean if you''ve read it).', 'The game began as a very decent adventure, but near the end it devolved into QTE feeding frenzy at -20 AGI and -20 DEX modifiers. Such a shame.', 'Mostly Positive', 73.28, 6.55, 15.50);
INSERT INTO reviews VALUES (5611, 420290, 10706, 'I paid for this game', 'Can''t start the game at all. Instantly stops.', 'Very Positive', 83.64, 97.85, 0.53);
INSERT INTO reviews VALUES (5616, 420440, 1059, 'My Bismarck just got sunk by a Hms Hood via forward magazine explosion, Not Historically accurate. 1 star for historical battles.\n\n\nI give this game 5 stars for the Mechanics and visuals tho', 'Ok I really tried to give this game some good honest playtime before I made my updated and final review. Played it for almost 200 hours, and while I enjoyed the single combat and the Campaign games, the Battle for the Atlantic campaign is where this game really showed its ugly side. \r\n\r\nI can totally understand all the negative reviews here now. I played as the Allies, and quickly discovered that buying capital ships is a bad idea. I fared much better against the Axis AI when I bought 30 destroy', 'Very Positive', 86.59, 87.87, 186.47);
INSERT INTO reviews VALUES (5618, 420520, 357, 'This game is an absolute steal at the price point it''s sold at. The mix of the turn-based strategy map and real time tactics battles works like Total War, but if you play the story mode (called Prologue in the mode selection) the game goes through a lot of story events, which reminds me of the Nobunaga''s Ambition series. However, if you don''t like that and would prefer a more sandbox way of playing the game with no events or stories, you can just play Free Mode or Random Scenario. The game is ve', 'The game has a ton of issues in terms of balance, play, and UI. The potential is there for this to be a great game. They probably will not continue it though. Everything is tiny, super small and hard to read and process. The battles are ok though they lack any real tactical depth. Primarily because of specific heros, or units that just wreck armies especially those that summon golems. Sometimes you just have to send a wave of bodies and hope that a flank works. Selecting units is a pain. Heros a', 'Very Positive', 86.27, 58.20, 14.25);
INSERT INTO reviews VALUES (5619, 420530, 27674, 'I may have only started this game because of Indie Cross, but man this was so peak. If I didn''t play till 5 am, would have cried at the end. Nothing about the store page or indie cross could have prepared me for this experience. Highly recommend going in blind if possible.', 'stop looking at the negative reviews and buy the game', 'Overwhelmingly Positive', 98.32, 8.50, 25.22);
INSERT INTO reviews VALUES (5621, 420560, 2229, 'Very Unrealistic but still fun. I work as a FF and thought it would be a funny Gimmick to try it out and see how close to the real thing it is. A minute in, the comms dispatch reports that fire is spreading and that there is possibility for backdraft. backdraft is no joke but also extremely rare in the real world. Backdraft conditions are created by an oxygen limited environment and not one where fire can spread freely and have smoke billowing out of the roof. The ladder truck also gets assigned', 'Could not have been a bigger waist of money, Bought the game when it came out a few years back and gave it the benefit of the doubt hoping it would get major improvements, especially to fire physics.(hence a fire game). I re-installed it this past week a year of not playing to find it is worse now than ever before. Since its release, these developers have not touched this monstrosity of an unplayable game. I have always been a fan of Astragon and their previous simulation games. It just seems li', 'Very Positive', 81.88, 0.38, 29.42);
INSERT INTO reviews VALUES (5623, 420660, 152, 'This game was a huge part of my childhood and Im glad to see its still around. Ill admit the controls arent as good as i remember and maybe thats due to nostalgia but it holds up well. Love the slow mo, the explosions and music. Cant wait for burning rubber 6.', 'shit game the cars dont turn well and you cant full speed', 'Very Positive', 88.82, 4.78, 1.17);
INSERT INTO reviews VALUES (5625, 420740, 881, 'Kill your sister, claim the inheritance.\nSacrifice your humanity, execute the perfect crime.\nGain everything, and lose everything.', 'terrible', 'Very Positive', 91.83, 1.60, 1.00);
INSERT INTO reviews VALUES (5629, 420840, 156, 'bl aerp !!!!', 'Perhaps I''m missing some core game mechanic here, but I don''t quite see the epic appeal of BLARP! Or, at least, I''m at a loss to explain why so many other reviewers thought it was the cat''s pyjamas.\n\nAs far as I can tell, there are only two controls (i.e. the right trigger attracts blarps to the wand, left trigger generates a shield), two game mechanics (elastic attraction and shield-based deflection), and one goal (get a blarp to strike the numbered ball).\n\nSure, the spacey mood music is nice a', 'Very Positive', 94.87, 1.35, 0.88);
INSERT INTO reviews VALUES (5634, 420930, 894, 'i created horrors beyond my comprehension in this game (i dont understand them)', 'I''m a retard for buying this game when it was 15$. The game had potential', 'Mostly Positive', 78.64, 4.28, 0.32);
INSERT INTO reviews VALUES (5637, 420980, 165, 'Army Gals is one of the more interesting visual novels on Steam...\nIt has it''s dull moments, but overall it''s exciting. There''s plenty of choices you can make, which will produce MULTIPLE different endings. Personally, I wouldn''t try to "perfect" this game. All it takes is one wrong move, and the ending you''re aiming for could be lost! So don''t overthink it, and enjoy Army Gals for what it is.', '6/10. I really liked the "straightforward" writing, story setting, choices, and some of the h-scenes, but there''s a painful amount of bad endings and (more negatively) experimentation to get the very specific combinations of choices that are required to reach the "better" and "good" endings. I used a guide after getting a couple bad endings in a row (and was apparently set towards bad endings from early choices), and it still felt like a chore to reach the better endings, and often only provided', 'Very Positive', 89.09, 5.52, 20.47);
INSERT INTO reviews VALUES (5638, 421040, 1644, 'perfect adhd bait to run on your second monitor while working. cute graphics, funny sounds, little blue blobs - what else do you need, really? a very wholesome experience.', 'Very boring and repetitive. I will keep playing for the achievements. By playing I mean opening it 1 time per day. Less than 2h in, without any active play, and Ive already unlocked every bush/crop/animal and tree. Looks more as a prototype made ''game''.', 'Very Positive', 84.85, 26.12, 4.88);
INSERT INTO reviews VALUES (5639, 421050, 909, 'Great Game, don''t listen to the negative reviews. This is a classic Deponia game just like the first 3. Definetly worth it. If you played the first 3, this is a must.', 'Unlike first 3 parts this one is a spit in the fans'' faces. Gameplay is fun and so on, but the story? That''s not what I really wanted. THERE IS NO HAPPINESS, IF YOU ARE LOOKING FOR IT STORYWISE > DON''T BUY this part NOR PLAY IT and imagine the end yourself. IF you don''t care - go on, there is another load of toxicity and trolling if you are up to it. My recommendation is based on personal dissapointment and offense.', 'Mostly Positive', 79.76, 19.05, 13.92);
INSERT INTO reviews VALUES (5641, 421120, 1452, 'I absolutely loved this game. It took me forever to finish all achievements, though. No regrets.', 'I see Ukraine politics mentioned in my feed, I downvote. Get that flag out my face, thank you very much.', 'Very Positive', 94.49, 5.93, 5.00);
INSERT INTO reviews VALUES (5643, 421170, 1207, 'Genuinely love this game despite is deleting all of my saves after I arrived at the monk temple and opened the game again. Genuinely no clue how it happened. :c\nEDIT: If I''m alt tab-ed while booting it up it seems to be what deletes the files. Even if I''m just in my browser while it''s open not in fullscreen. I still highly recommend the game despite the fact this is now the SECOND time it''s wiped my save files.', 'The game is literally unfinished and the studio was usurped. Purchasing this game means rewarding one dickbag who ruined everything. \n\nAs for the game itself, the platforming gets really old really fast. Controls are so poor that I continually end up using a different traversal move than the one I input with no particular explanation as to why. The combat system makes random encounters a repeated slog, especially without the freedom to just run from battles.', 'Mostly Positive', 72.33, 44.00, 18.98);
INSERT INTO reviews VALUES (5645, 421190, 146, 'Amazing game. Smaller player base but still heavy games on scheduled events. Join the discord and find full lobbies and some awesome people. I have an older video up on my YouTube channel, but will be posting many new ones soon. Channel name is LOW RENT HERO. What can I say. It’s one of the best and most interesting shooters out there. A hero shooter unlike no other. The only polished hero shooter in vr. And it actually outclasses all flat screen hero shooters. Some of the most interesting game ', 'Totally, entirely, and utterly dead.', 'Mostly Positive', 74.66, 16.63, 0.53);
INSERT INTO reviews VALUES (5649, 421630, 146, 'Oh. My. God. If anyone here is even remotely considering buying this game. Do it. I''ve only played through it once, but this game has made me do the following with only text on a screen;\n-cry\n-scream\n-rant about it for 3 hours straight\n-want to throw my computer at my wall\n10000/10 recommend.', 'Before I praised this game. I suggested people SHOULD buy this. That''s before I signed up on their website had the chance to talk to one of their owners. I think people should read this BEFORE buying. What he says this is a direct quote.\n\n"Choice Of Games embodies the same view of Antia Sarkeensian." End quote\n\nShe is a person who mislead people several times, calls games sexist or objective to females. I was told not to buy their games unless I did agree with her world view. This is one of Owne', 'Overwhelmingly Positive', 95.21, 4.50, 4.33);
INSERT INTO reviews VALUES (5650, 421660, 215, 'Harmonia gave me a mixed feeling as I couldn’t decide whether or not it was a well-written story. The first half was a bit too slow while the later half made up for it. Personally, I think the writer tried a bit too hard to make Harmonia a heartwrenching story, hence, the narrative when developing the conflict between characters feels forced and unnatural. The ending left me unsatisfied with a “happy” closure without bothering to explain the process to achieve said “happy” closure other than “ti', 'The whole game is barely 3 hours long and feels like a rehash of planetarian, with a similar setting, similar developments, and a similar message. I don''t imagine anyone but die-hard key fans enjoying it for what it''s worth.', 'Very Positive', 93.49, 9.45, 2.58);
INSERT INTO reviews VALUES (5652, 421700, 252, 'UOOOOHHH 😭😭 I LOVE CUNNYYY 😭😭💢💢😭😭💢😭😭', 'This is supposed to have Steam trading cards.  It doesn''t!\n\nEDIT: Game released Dec 22. Card released Jan 9.  Still thumbs down.', 'Very Positive', 88.49, 2.17, 5.68);
INSERT INTO reviews VALUES (5654, 421740, 333, 'Although it might not be great for your eyes, I recommend playing this game with the lights off and using headphones for the best experience.', 'Encountered a game breaking bug after 8 hours. Very disappointing, I am not sure if I''m willing to start over, though i was enjoying the game. The thing is, i discovered afterwards in a guide posted on Steam, that this is a long known bug and I cannot fathom why it wasn''t patched out. Seriously bummed right now.', 'Mostly Positive', 78.68, 4.62, 8.27);
INSERT INTO reviews VALUES (5656, 421810, 160, '⠀', 'trash', 'Mixed', 65.62, 2.58, 1.17);
INSERT INTO reviews VALUES (5664, 422110, 130, 'Underrated gem', 'one player mode sucks. you know you''re playing against AI for real. that''s not human reflexes....', 'Overwhelmingly Positive', 96.92, 3.48, 2.63);
INSERT INTO reviews VALUES (5671, 422510, 673, 'This game is absolutely crazy. I played it for 715.8 hours while trying to get the top score.', 'When we play pinball we are aiming for high scores, to beat other people. Practically the only thing that makes the game replayalbe is corrupted, the 100 first players on the  global leaderboard are all cheaters with the exact same impossible bugged score, and the dev did not solve this issue, did not do a clean up or taken action to prevent this from happening. \n\nToo expensive for a one tricky pony with a faulty leaderboard, refunded.', 'Overwhelmingly Positive', 95.10, 715.88, 0.28);
INSERT INTO reviews VALUES (5677, 422810, 1069, 'Alex Mauer sucks.', 'The final boss is the 2020 election and no, you aren''t gonna win no matter how hard you vote', 'Mostly Positive', 73.71, 14.17, 18.05);
INSERT INTO reviews VALUES (5678, 422860, 163, 'Oh - my - god. I just played this game (Oculus Rift with Touch Controllers in a 2.0 x 1.8m large space) for two hours in total and I love it. This is the program everybody was talking about when we said that computer players in future will be muscular fitness monsters because of VR. I downloaded several songs from OSO like Funky Town and ABC by the Jackson Five, fired this program up and had lots of fun moving violently until I ended up as a sweaty meatball. Since I had not finished the (tutoria', 'As a Vive owner, Audiosheild completely blows it away, . \nIf you are looking for a precise rhythm/ reaction game you may enjoy it. The story mode is like some lame Disney dragon thing. You can''t really move around as you have to catch the balls at the exact time at the exact forward x & y axis. If your hand is too close to your body, you "miss". If it is too far forward, "you miss", which for me felt very restritive. I don''t want to stand perfectly still like a robot while listening to music. Af', 'Very Positive', 87.73, 11.98, 0.57);
INSERT INTO reviews VALUES (5680, 422900, 963, 'Buy the game, play the campaign, then in the menu go to "EXCHANGE" and filter for Text: c. wars remastered\r\nAnd then go play all the fun maps I made :)\r\nHave fun!', 'Loads of fun until mission 15 where suddenly there is a cannon on the other side of the map which one-shots one or more of your ships once per minute with no warning and no way to block the shot. Spent a solid couple hours doing my best to try different strategies, follow walkthroughs, to no success. Learning that the following mission features two of those cannons was enough for me to quit and uninstall. Too bad, was loving the game up until that point.', 'Very Positive', 92.21, 274.93, 7.92);
INSERT INTO reviews VALUES (5681, 422910, 663, 'With the release of Creeper World IXE, I figured I''d take the time to play through the series. Creeper World is a series in which you play a commander and you have to fend off the creep from flooding the world and destroying Odin city (Your base.) Unlike standard Tower Defense in which waves come down a lane/path, Creeper World''s Creep is essentially water. That means it drips from higher elevations to low, it pools up and has depth, and has the potential to travel backwards by attacking the sou', 'Too time dependent for me. \n\nYou have to claim this part of the map and save these survivors by x amount of time. Like I can see why these creeper games have great reviews, it''s a great concept but I just despise time limits and can''t enjoy games which function around that. \n\nAnd really with the nature of the creep as creative as that idea was, it''s difficult to make this game anything more. It''s just liquid, no variation so either have the player grind and slowly come to a stalemate with the cr', 'Overwhelmingly Positive', 97.29, 18.60, 2.08);
INSERT INTO reviews VALUES (5682, 422920, 323, 'A nice take on Creeper World with a completely different game mechanic. You still shoot the Creeper, but in a 2D side-scroller style underground. There are some really challenging missions.', 'The missions were awesome until the last couple. After a while trial and error of loading and saving gets incredibly tiresome. I''ve spent the last hour trying to build a single building, and honestly I have absolutely no idea how to do anything at this point.', 'Very Positive', 90.71, 14.90, 27.32);
INSERT INTO reviews VALUES (5683, 422970, 5475, 'Don''t let my playtime fool you, I''ve only seen the first 8 minutes of this game.', 'Overwhelmingly positive reviews? I don''t get it. This is a simple arena shooter that is extremely dark/hard to see anything and overly difficult to the point where getting further than a few minutes into a run is a feat. Maybe it''s one of those games that once you put in 100+ hours and become advanced/expert it gets a lot more fun? I''m an expert gamer and Devil Daggers is still extremely difficult for me. I got it on sale for 99 cents and recommend that you wait for a sale as well... only buy th', 'Overwhelmingly Positive', 96.27, 197.93, 0.43);
INSERT INTO reviews VALUES (5685, 423120, 222, 'Loved the settings, plot, characters are well fleshed out. High replayability for sure. I enjoyed the story though being CP makes action choices a big gamble. Personally, would have failed all the tests if it weren''t for answers online bc i''m not that concerned with studying & would rather get to spend time w the characters but i must say learning Crook''s secret made me T_T!! bc i was so enamoured by him from the get-go hahahaha why couldn''t his secret be literally anything else sigh also love t', 'I didn''t like the writing.', 'Very Positive', 84.68, 5.82, 19.65);
INSERT INTO reviews VALUES (5688, 423230, 6190, 'Scope creep is a problem for many prospective indie developers. Including too many wayward ideas in a game can doom it to never release in a finished state, so many games wisely choose humility and simplicity, and the industry is better for it. Furi, however, is not one of those games. It tries as hard as it can, despite its tiny studio, despite its essentially nonexistent budget, to be the coolest thing you have ever seen. In some areas, it genuinely succeeds at this. It is a beautiful, gratify', 'I don''t like the combat. I don''t like being forced to play a certain way when the boss is immune to damage for half the fight. Imagine if you were fighting Eye of Cthulhu but it''s invulnerable when it charges at you and you had to press A and T on your keyboard just to not get hit. The shooting mechanic also isn''t very fun, it''s not engaging and bosses dodge the charged attack every single time anyway. The soundtrack bangs, but the gameplay just isn''t fun for me.', 'Very Positive', 92.44, 11.62, 0.98);
INSERT INTO reviews VALUES (5692, 423490, 267, 'Great game works really well with Logitech Extreme 3D pro Flightstick', 'Not working on wide screeen. FPS less then 30 with 3080Ti. Poor graphic.\nWhat a joke.\n', 'Very Positive', 81.65, 73.62, 2.98);
INSERT INTO reviews VALUES (5694, 423580, 2136, 'It is a must for the one who remember Sim Tower from back in the day when "Sim Anything" was the trend.\r\n\r\nA nice and relaxing game.', 'Fun, until it isn''t. \r\nThe game has a bit of a steep learning curve as everything is interconnected. The issue is, the tenants have NO patience with you at all, and something as simple as replacing an electrical panel can destroy your entire tower in seconds. If the tenants did not move out at the drop of a hat, and if you did not have to pay to replace them, then perhaps the game would be enjoyable. As it stands, the game will brutally punish you for any tiny reason. Happiest tenants you ever h', 'Very Positive', 85.11, 48.43, 4.65);
INSERT INTO reviews VALUES (5695, 423590, 252, 'I feel like the ending for the game was a little rushed, but the art style was very charming and overall it was a fun time. Would recommend!', 'Sorry, it''s a no from me. Lacking polish. This resembles an old flash game where the point and clicks pixels don''t line up and the answers aren''t particularly fun or funny.', 'Very Positive', 82.14, 5.00, 0.95);
INSERT INTO reviews VALUES (5700, 423710, 103, 'In its current state, the game has a lot of potential. I''m egar to see how the developers do with it, only because I loved the little bit that''s out. I can not wait for updates, I can not wait to see just how far this game goes. It has great RPG elements, combined with a sort of survival element. Not the game I wanted to buy today, but I''m extremely happy that I did!', 'Do you recommend this game?\n Yes\n \n No\n', 'Mostly Negative', 39.81, 4.17, 4.53);
INSERT INTO reviews VALUES (5715, 423950, 257, 'https://steamcommunity.com/sharedfiles/filedetails/?id=2754622734\nhttps://steamcommunity.com/sharedfiles/filedetails/?id=1722993004\nhttps://steamcommunity.com/sharedfiles/filedetails/?id=892484574', 'I was really enjoying this game and then I went to bed, when I started it up again my entire 2 hours of gameplay was completely lost and I had to start from the very beginning - many other reviews state the exact same thing\n\nHow is this still an issue almost a decade after release? It''s a shame because the game is really fun and maybe I''ll pick it back up when I''m not annoyed and just smash it out in a day but this is actually so disappointing', 'Mixed', 63.42, 4.20, 2.33);
INSERT INTO reviews VALUES (5718, 424030, 9728, 'Joined a game choose union side. first skirmish i was beaten to death while being called a N****R lover by 20 charging confederates. 10/10', 'I have just a little over 2 thousand hours in this game and I have been playing it since early 2023.\nThe game originally was incredibly fun, however, the updates are incredibly slow and the updates that have been released are pathetically small and low quality, with every update I feel the game has gotten worse and as a result the community is in slow and steady decline. The melee has been utterly slaughtered, the amount of times I have accidentally stabbed a friendly who was to my side or even ', 'Very Positive', 89.01, 39.70, 2370.30);
INSERT INTO reviews VALUES (5725, 424250, 411, 'If you''re a fan of the Avernum trilogy, you''ll probably enjoy this title. Less dialogue and only control a single character (plus a pet if you choose) Haven''t encountered any of the game breaking bugs people have mentioned, yet. ', 'This game is pretty much everything it says on the tin, and I was loving it. However, I cannot recommend purchasing it or playing it for one very unfortunate reason. It has a game breaking bug that is likely to happen and end your save. NPC''s will sometime disappear from the game world and never return, including ones vital to progression. For me, it happened with the NPC "Leonard" after 9 hours, too late to refund. Searching for a solution I discovered that this has been an issue for many years', 'Mostly Positive', 77.13, 41.20, 9.82);
INSERT INTO reviews VALUES (5727, 424280, 102, 'When will I be able to open cases?? I need skins for my pigs.', 'in this game the wolves always bully me, i report them... this is cyber bullying, this game be trash. :''(', 'Overwhelmingly Positive', 97.06, 2.57, 8.70);
INSERT INTO reviews VALUES (5729, 424370, 27637, 'It was great until chapter 4', '"It is with a heavy heart that we announce a significant change: Starting September 3, 2024, Wolcen will no longer support multiplayer functionality. Additionally, we will cease further development and support for the game. This decision allows us to focus on new projects, carrying forward the lessons learned from Wolcen. We are committed to excellence and driven to create new experiences and adventures that we hope you will be eager to join."\n\nI have been waiting for years for them to finish th', 'Mixed', 56.74, 13.12, 45.28);
INSERT INTO reviews VALUES (5730, 424590, 130, 'I have a few hours into the game now and can honestly say there are no major issues at all. The physics for driving on the roads are not perfect, so just drive carefully but the rest of the stuff in this game makes up for that. All the crop and fruit planting are far more realistic than FS 15. It will really pay you to do All the tutorials. As for the wingers out there FS 15 has still got bugs example: turn on your lights and game freezes.. I think it''s great what these Devs have done with this ', 'Missed opportunity , had so much promised, but was a hurried release. Developers did not fix the flaws which were apparant in the alpha videos/ pictures ( eg bouncing tractors, tractors floating, blurry graphics etc etc ). Has all the ingredients ( which the Farm Simulator series doesn''t have ) , to be a success , but needs to be polished ( patched !! )  a lot. In its current state, i can not recommend this game.', 'Mixed', 43.08, 50.82, 0.42);
INSERT INTO reviews VALUES (5737, 424840, 17846, 'This is fun little 3D platformer and is challenging to some extent as well. It does have a bit of dark side to it which makes it a little more exciting. I''m really enjoying this game so I give it a thumbs up!', 'Like Limbo, but perhaps less tricky puzzle solving.  I just find it boring, repetitive.  \n\nGame consists of manipulating objects and finding+platforming your way out of each room.  It''s just slow and ponderous, like Limbo, it''s relying on ''ooh, look at this'' to sell itself.  \n\nI get it works for some people, it''s just not for me.', 'Very Positive', 94.47, 9.97, 0.60);
INSERT INTO reviews VALUES (5745, 425210, 554, 'Turns out, it''s way harder not to kill anyone than to just kill everyone.', 'Shadwen feels more like a college kid''s project that barely passed as a video game than it does as an actual game. It feels more experimental than it does an actual finished product, even from an indie studio. Too much of the studio''s previous work can be seen here and it''s obvious that they didn''t want to step too far out of their comfort zone. Full Review Below.\n\nhttps://www.youtube.com/watch?v=JCVNwrLlHd4', 'Mostly Positive', 79.24, 8.23, 6.20);
INSERT INTO reviews VALUES (5746, 425220, 868, 'Where is One Piece Burning Blood 2 ODA?', 'Literally one of the worst games I''ve ever played\r\nActively frustrating and not fun or rewarding to play\r\nJust imagine your fan fights yourself and save the money\r\nModded BT3 is literally free and might actually provide some enjoyment', 'Mostly Positive', 79.38, 13.48, 3.02);
INSERT INTO reviews VALUES (5758, 425580, 9511, 'Thrilling and futuristic. This game is a fun and atmospheric puzzle-solving game with occult symbols etched all over it. It takes around 5 to 6 hours to complete. You cannot miss any achievements since all of them are level based. A solid 7 out of 10. It is not a perfect puzzle solving game since some of the riddles are relatively easy and simple. Would recommend it to any puzzle-lover any day.', 'interesting puzzles,but in the final part it becomes ever more spiritistic,not for me!!\r\nso if you want to avoid the evil spirits,save your money.', 'Overwhelmingly Positive', 97.52, 5.42, 6.27);
INSERT INTO reviews VALUES (5760, 425650, 138, 'The gamer''s rage is intense with this one, lmao. As much of a pain in the neck it was to start all the way at the beginning when you died, I had a hella fun time playing!', 'Not a fan of this game. Zero updates in several years. The controls are hard to use. If they would update the game and controls it would be a really fun game. Do NOT waste your money.', 'Very Positive', 92.75, 23.17, 0.12);
INSERT INTO reviews VALUES (5761, 425670, 262, 'It''s pretty fun', 'Took me years to finally finish it, not because it''s long or hard... it''s because it''s meh at best. The progression system sucks, it has rarities ranging from common to legendary, but when I finished the game I barely was able to unlock a few rares. It is meant to be grinded hard, but it''s not remotely interesting to do so. Why would you ever wanna grind this is beyond me.\nUltimately is a big NO from me, I''m glad I can finally remove it from my installed games list.', 'Very Positive', 80.53, 7.80, 9.35);
INSERT INTO reviews VALUES (5763, 425770, 106, 'I was not sure if my computer was powerful enough to run this, but it runs like a dream. Great game.', 'I''m sorry, but I don''t understand the universal appraise. This game isn''t good. It''s less complex than an Atari 2600 game and has bad grammer. It''s not worth even the 99 cents it''s asking.', 'Overwhelmingly Positive', 99.06, 0.08, 0.12);
INSERT INTO reviews VALUES (5769, 426000, 4047, 'I did not know steam showed my friends what games I play.', 'Game kinda fucking sucks. Once I finally started understanding how to play efficiently I got to day 21 only to find out thats where it ends, there''s not even any damn H scenes. Zero replay value and honestly no play value to begin with, what a disappointing experience.', 'Very Positive', 88.78, 2.48, 3.33);
INSERT INTO reviews VALUES (5777, 426310, 217, 'Awesome gameplay idea. The visuals of this game are really something special. As a person uniquely concerned with games that put you in the shoes of another person, especially when hat person is differently abled than you, this game is a piece of living art.', 'I want to love this game but after playing the first couple chapters and putting it down I''m sad to say it wasn''t for me. I love the main mechanic of navigating a space via echolocation, turning the main character''s disability into a novel and enthralling gameplay experience. The voice acting is phenomenal and the story almost hooked me.\n\nUnfortunately it falls down quite a bit in execution. The first bit of the game feels entirely too easy and gives you too much warning for when you''re in dange', 'Mostly Positive', 71.43, 2.60, 1.45);
INSERT INTO reviews VALUES (5778, 426330, 136, 'fun!', 'I like these choose-your-own-adventure stories in general, but they have been very hit or miss for me depending on how much the writing disconnects from the choices I make. I don''t want to give anything away about the story so I will start with an analogy, *not* an actual example. Imagine you are asked by a story to choose your favorite beverage - water, cola, or liquor. You answer water, only to be told you would have preferred liquor and now you are sad because you wanted to get buzzed. I am? ', 'Very Positive', 91.18, 8.82, 2.95);
INSERT INTO reviews VALUES (5781, 426630, 293, 'Bubsy on Steam.\r\n\r\nWhat could possibly go wrong?', 'Bubsy dies whenever the fuck he feels like it.', 'Mostly Positive', 73.04, 10.47, 0.72);
INSERT INTO reviews VALUES (5782, 426690, 122, 'Actually, I am not qualified to evaluate this game''s overall level. Facing my own life, I am just a newbie without enough experience and wisdom. After finishing the game, I really admire the pure and great friendship between Himeko and Yuka, which has been beyond the normal standard of simply helping each other or providing emotional value and becoming the resonance of their souls. If GOD could hear the voice from the bottom of my heart, I wish in the next life, they would still meet each other ', 'Obvious grammatical errors are just unacceptable. Story remains tedious and without plot up until at least Chapter 3, marred further by a paltry translation job. Free version of Narcissu 1 & 2 on Steam remain objectively superior -- offering a coherent translation at the very least, and other options.', 'Overwhelmingly Positive', 95.08, 10.98, 1.27);
INSERT INTO reviews VALUES (5783, 426790, 1219, 'I grew up', 'I don''t have the necessary patience for this kind of game. It looks sweet and the mechanics seem fine, but climbing becomes repetitive quickly.', 'Very Positive', 92.45, 2.33, 0.68);
INSERT INTO reviews VALUES (5786, 427030, 166, 'Playing the game while enjoying the storyline, great 👍 ，边玩边看剧情很棒', 'The reason for closing the Sky Gate is very far-fetched. In fact, there could be a better solution to find the daughter of the Emperor of Heaven. The game exaggerates the danger of this choice but does not explain in detail why the Emperor of Heaven is described as a madman who disregards any other consequences in order to find his daughter, and why the small team of players cannot carry out this action secretly. It is just forcibly creating a tragedy where there is no need for sacrifice. The ga', 'Very Positive', 83.73, 50.60, 146.13);
INSERT INTO reviews VALUES (5788, 427100, 1339, 'I purchased this game when it first came out and the frustration level experienced just trying to get the steering to work drove me to abandon all hope at that time.  I revisited the game a few times over the following years and just couldn''t get to a point where I found the game enjoyable for all its flaws.  I recently tried again to see if the developers had finally gotten things ironed out and man was I amazed.  What a difference only eight short years of development can make.  Fernbus Simula', 'I loved how the game looks, and the graphics are really nice, but the optimization sucks. Even with an RTX 3060ti, I had to lock the frames at 60 and lower the quality to medium, but the game still has major frame drops, especially in cities. This makes the game frustrating and hard to enjoy at times.\nI won''t recommend it to anybody unless you have 4080 then maybe you can tell if it runs smoothly. ;P', 'Mixed', 65.94, 276.67, 129.92);
INSERT INTO reviews VALUES (5789, 427190, 3848, 'If you had to pick a version of Dead Rising 1 to purchase on Steam, which one would you get: The $50 virgin "Deluxe Remaster" that has had its heart and soul ripped out, is heavily censored, and has voice acting that is a noticeable step back, or the $10 Chad OG version that is overall superior despite its age?\n\nI think you know which version of Dead Rising 1 to get.\n\nUpdate as of 11/12/2024: Edited for better formatting and to say how shocked I am at how much attention this review got from the ', 'otis exists >:(', 'Very Positive', 91.14, 21.63, 12.72);
INSERT INTO reviews VALUES (5790, 427240, 334, 'Fun for a couple hours, but overall light on content. I recommend getting it when it goes on sale.', 'Great, except for lack of win conditions, gamemodes, and overall content. There is a very tiny tech tree for the enemies, and a slightly larger one for you. Gameplay itself is great, just wish it had more substance, but this game is basically abandonware. Thankfully far, far better than most, but still....', 'Very Positive', 88.02, 3.83, 3.63);
INSERT INTO reviews VALUES (5791, 427250, 1162, '11/10 best RTS out there', 'Dont waste your money', 'Very Positive', 80.64, 494.15, 32.23);
INSERT INTO reviews VALUES (5792, 427290, 8079, 'Love this game and would have loved to have seen a sequel but sadly it seems im one of the few.\r\ndid no one else enjoy this story as much? yes the combat is janky and the world small but it so rich that a sequel would have polished to perfection given the chance.\r\n\r\nplease make another one, petition=1 any takers?', 'The setting, visuals and voice acting are all superb - and make the game worth playing, but it''s deeply flawed. Even leaving aside the issues with corrupted saves and crashes, the ending sucks, the game removes choice at the moments when choice is most meaningful, and the core combat is disappointing. it''s kind of incomprehensible to me why Dontnot would put so much care and effort into creating something with so much potential, and then burden it with tedious third tier souls-like action elemen', 'Mostly Positive', 76.32, 58.12, 58.47);
INSERT INTO reviews VALUES (5793, 427410, 15705, 'This is one of the best games I''ve played in the last five years, I have only one thing to say to the developers of this wonderful game. Buff the pizza, I beg of you, on my life. Just please make the pizza better. We spent 28 hours on a fresh save, to get pizza, and it was so mid, that I''m have a religious crisis. Please buff the pizza, or I might not be able to find my way to heaven, thank you', 'Wanted to share an honest review. Again just my perspective of what''s missing. Me and a couple gaming buddies grabbed this over the weekend. I ended up playing it the most out of the group. Overall this is a great game with IMO just a couple short comings. We bought it based on the reviews which I expect will continue to be positive. None of us had issues with bugs, game ran well for all of us all. We all liked the "bones" of the game and I commonly heard "I don''t have a strong opinion good or b', 'Overwhelmingly Positive', 97.13, 137.22, 16.25);
INSERT INTO reviews VALUES (5794, 427470, 285, 'Democracy 3 Africa is, as the description states, a "standalone" version of Democracy 3. It opens via a separate launcher and, of course, does not feature any of the nations in the base game. That all being said, this version of the game is cross compatible in terms of your expansions and mods, meaning that a mod or expansion installed for Democracy 3 will work in this game. That''s pretty neat, and it lends itself to why I think this version of the game is actually better than the base game in t', 'Used to be a fun game but now can''t run without a long ass troubleshooting session. Just buy the new game, or if  your bored of that, get modding for it.', 'Mostly Positive', 74.04, 6.53, 17.33);
INSERT INTO reviews VALUES (5795, 427490, 561, 'I played Shadowhand Solitaire first, not realizing this was the original game! While the story is the same for both games, I actually preferred this as an RPG and the game mechanics of this game to Shadowhand Solitaire. And it took me playing this version for me to realize Lady Cornelia is Lady Fleetwood from Regency Solitaire. So I love that this is a fun backstory for her!', 'Play the version without the combat. The solitaire and powers are really cool but the combat is half baked and insanely frustrating to get 3 stars on. It never feels like it''s in your control, all that matters is getting lucky and not giving the AI a combo (which, again, completely out of your control).', 'Very Positive', 83.60, 16.32, 5.97);
INSERT INTO reviews VALUES (5796, 427520, 106205, 'I''m genuinely scared to play this game because while i am bad i have had actual relationships end over this game. I''m sorry Catherine but the factory must grow', 'Imagine seeing DLC priced at the same inflated niche tax price as the base game, then going to the forums to find out whats going on, only to see a pinned thread explaining the people responsible refuse the entire concept of a discount because its unfair or something, though ironically I bet I could buy a resold key from some random Russian for half the price, but I guess its one of those modern values that only applies to things they want it applied to and not others.\n\nTo top it off, anyone que', 'Overwhelmingly Positive', 98.25, 49.28, 208.92);
INSERT INTO reviews VALUES (5798, 427570, 123, 'Promising game! Very nice to look at. Runs smoothly. Looks like we can expect a lot of depth. Would be good see a more clear resource gathering options, mining stations etc.. Battles look good but need more ship designs!! Alien races look fantastic and there are plenty of diplomatic options although at this stage in the early access i think they are bugged. Overall this certainly is a promising game, reminded me of Sins of a Solar Empire, which can only be a good thing.', 'unfinished, bugged, and generally bad design', 'Mixed', 47.97, 4.20, 16.52);
INSERT INTO reviews VALUES (5800, 427660, 127, 'The unofficial Clock Tower game with legally distinct villain the Scissorwalker. Solid premise and interesting but you can see the budget was stretched thin and the game was also promised to be ported to the Vita of all things so don''t expect it to look even AA in scope.\nStill even with all that we get the original voice actor for Barry Burton from Resident Evil 1 playing the main villain so that alone was worth the buy just to hear those dulcet tones deliver stilted dialogue.\nWorth picking up o', 'Bad fleeing mechanics, character runs out of stamina way too fast and just sits there like a sitting duck if you''re too fatigued, trips and falls too much, scissor walker catches up to you in an instant, barely any hiding spots, goofy ahh story, lame ahh characters, boring and shallow second chapter. It feels more like a chore to play this one, in oppose to the unease and terror the originals made you feel. This one will just frustrate you with its unbalanced flee mode and hot mess of a story.\n\n', 'Mixed', 66.93, 2.65, 19.82);
INSERT INTO reviews VALUES (5802, 427700, 139, 'if you love Ys and other RPGs like that- this is a true hidden treat I''m so glad the West got and  found! One of my biggest surprises yet on Steam!', 'this game is overprice, many talk in this game. boring game.', 'Very Positive', 94.24, 25.92, 6.02);
INSERT INTO reviews VALUES (5803, 427730, 16314, 'Having 5 kids myself... this game is a toned down version of real life.  \nWEAR A CONDOM for the love of god.  Don''t do this to yourself.', 'It''s one of those games you thought were fun when you first saw it 7 years ago in YouTube videos, but playing it yourself you then realise how janky and unfun it is. I hate the new artstyle, the more I tried to play the more I was thinking how only a kid would laugh its ass off. So then I decided to play the classic version I was familiar with, which I''m glad it''s there as an option on the menu. To my shock the classic is buggy and broken. I don''t know man, I played with a friend and we just wer', 'Very Positive', 82.14, 0.60, 0.57);
INSERT INTO reviews VALUES (5804, 427760, 514, 'The game is really short and has some buggy moments where things dont trigger until you randomly stumble over the solution, but other than that its pretty nice.\r\nStory is okay, VA / sounds are well done, atmosphere is good unless you have no clue what to do, and the flow is interrupted, then it gets annoying.\r\n\r\nGenerally I recommend the game, though maybe wait for it to be on sale.', 'probably fine on old devices but broken now, no settings and bad roomscaling', 'Very Positive', 83.27, 3.48, 0.47);
INSERT INTO reviews VALUES (5807, 427810, 189, '.', 'I kinda liked the idea, but got locked by (well known, and yet never fixed) "eyes room" bug.', 'Mixed', 67.72, 1.80, 1.25);
INSERT INTO reviews VALUES (5808, 427820, 912, 'At first glance, this game might seem similar to the Hitman series, but it is actually a turn-based puzzle game. This brilliant reimagining effectively captures the essence of the Hitman theme.\n\n\n히트맨 퍼즐.', 'Don''t get me wrong, the game itself is quite fun. Some of the concepts that are so fundamental to the HITMAN series (especially the WOA-trilogy) translate surprisingly well to a top-down board-like gamemode, and gradually introducing and combining them makes for an engaging game that does not quickly get stale. However, I can not in good conscience recommend a game that forces you to jump through hoops to unlock some of its milestone achievements (reinstalling the game multiple times, deleting l', 'Very Positive', 86.29, 3.83, 23.87);
INSERT INTO reviews VALUES (5811, 427880, 658, 'This is an under appreciated game.   It deserves far more praise and player base than it got.', 'Amazing concept, gripping story and... dead.\nThe dev never finished building the world, there is no end, and no explanation.\n\nI really enjoyed the world of the game, and was sucked into it, but man, I wish the dev was still around.\nTheir site died over a year ago... Hope the devs are still around.', 'Mixed', 58.51, 68.98, 17.68);
INSERT INTO reviews VALUES (5813, 427910, 143, 'Poor Man''s Eye of the Beholder.  Online is dead (it was for high scores, so no big loss).  The game is buggy, but serviceable.', 'I played this a bit when I first got it.  It was OK.  I ''cleaned'' my library today, 12-28-2024, and gave it a try again.   Online play says database not available, offline mode crashes after a couple minutes.  Looks like the game is no longer supported and should probably be removed from the Steam Store.  Don''t waste time or money on it, it appears abandoned.', 'Mixed', 62.94, 82.72, 4.12);
INSERT INTO reviews VALUES (5815, 427940, 787, 'This game doesn''t deserve the dismally low rating it currently has. They went with a gameplay concept combining RTS, city and factory builder, and they did a good job. It also looks amazing. It works and there''s no serious bugs and as low as the bar is these days, it is worthy of a 1.0 version number. The only real problem is in the late game where it can get a bit boring without any objective besides wipe the map clean, and the "campaign" replay mechanic doesn''t provide anything interesting eno', 'This game had so much potential. They screwed themselves over in their EA stage. Such a shame it''s abandoned. \n\nIf you''re willing to play this, just get it in heavy discount. This will never get any new updates anymore, so it seems.', 'Mixed', 59.72, 179.97, 12.08);
INSERT INTO reviews VALUES (5816, 427950, 224, '⣿⣿⡻⠿⣳⠸⢿⡇⢇⣿⡧⢹⠿⣿⣿⣿⣿⣾⣿⡇⣿⣿⣿⣿⡿⡐⣯⠁ ⠄⠄\n⠟⣛⣽⡳⠼⠄⠈⣷⡾⣥⣱⠃⠣⣿⣿⣿⣯⣭⠽⡇⣿⣿⣿⣿⣟⢢⠏⠄ ⠄\n⢠⡿⠶⣮⣝⣿⠄⠄⠈⡥⢭⣥⠅⢌⣽⣿⣻⢶⣭⡿⠿⠜⢿⣿⣿⡿⠁⠄⠄\n⠄⣼⣧⠤⢌⣭⡇⠄⠄⠄⠭⠭⠭⠯⠴⣚⣉⣛⡢⠭⠵⢶⣾⣦⡍⠁⠄⠄⠄⠄\n⠄⣿⣷⣯⣭⡷⠄⠄⢀⣀⠩⠍⢉⣛⣛⠫⢏⣈⣭⣥⣶⣶⣦⣭⣛⠄⠄⠄⠄⠄\n⢀⣿⣿⣿⡿⠃⢀⣴⣿⣿⣿⣎⢩⠌⣡⣶⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣆⠄⠄⠄\n⢸⡿⢟⣽⠎⣰⣿⣿⣿⣿⣿⣿⢀⣾⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣦⠄⠄\n⣰⠯⣾⢅⣼⣿⣿⣿⣿⣿⣿⡇⣾⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⡄⠄\n⢰⣄⡉⣼⣿⣿⣿⣿⣿⣿⣿⢸⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣧⠄\n⢯⣌⢹⣿⣿⣿⣿⣿⣿⣿⣿⢸⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⠄\n⢸⣇⣽⣿⣿⣿⣿⣿⣿⣿⣿⠸⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⠄\n⢸⣟⣧⡻⣿⣿⣿⣿⣿⣿⣿⣧⡻⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⠄\n⠈⢹⡧⣿⣸⠿⢿⣿⣿⣿⣿⡿⠗⣈⠻⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⡇⠄\n⠄⠘⢷⡳⣾⣷⣶⣶⣶⣶⣶⣾⣿⣿⢀⣶⣶⣶⣾⣿⣿⣿⣿⣿⣿⣿⣿⣿⠇⠄\n⠄⠄⠈⣵⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⢸⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⠄⠄\n⠄⠄⠄⠸⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⠘⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⠇⠄⠄', 'Promises were made, promises were broken, the game was rushed out of early access half-baked and then abandoned.', 'Mixed', 48.66, 3.12, 1.02);
INSERT INTO reviews VALUES (5818, 427980, 152, 'Aozora Meikyuu\n\nHas a total of 5 trading cards.', 'The graphics are nice, but that''s pretty much all. In my opinion, it''s not well-crafted and well-thought-out. Some plot points seemed forced and I didn''t see any romance in the story.\n    Initially, I felt sorry for the main character, but it soon faded away.  The main character appeared to be a horrible person. His inner thoughts would cause people to run as quickly as they could if they could hear them.', 'Mostly Positive', 78.29, 0.53, 3.22);
INSERT INTO reviews VALUES (5822, 428080, 371, 'Its fun and a good workout!\nJust make sure you got enough space for them swings :-)\n\nIts the same developer as Underdogs which is a very well made vr game and has a big roadmap for future content.\nAnd they still found time to maintain this game with their latest update a few days ago.\n\nRecommended!', 'Started to lag like crazy after blocking it with the built-in windows firewall. Looking at the log reveals ~3500 connection attempts per second. How do you even do that?', 'Overwhelmingly Positive', 96.50, 0.17, 9.15);
INSERT INTO reviews VALUES (5838, 428340, 139, 'I make all the art for my game with this software. I really like it.', 'Linux when?', 'Very Positive', 90.65, 184.10, 2.57);
INSERT INTO reviews VALUES (5840, 428370, 690, 'Weeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeee', 'Broken. :(', 'Mostly Positive', 77.54, 130.23, 2.05);
INSERT INTO reviews VALUES (5848, 428550, 3971, 'Gorgeous little metroidvania with the mood that is just delicious, can''t recommend it enough.\n\nThe ending (and I mean true one) is quite a bit anticlimactic and lazy tho. Would it kill you to create a pictire or two to show us the fruits of our labor a little?', 'Momodora: Reverie Under the Moonlight is the fourth in a series of short Metroidvania platforming action games. The art is neat and the controls are fine. I''m downvoting this game because I am somewhat bad at the gameplay and the main character keeps dying. For a bunch of games, the difficulty and game loop might encourage progress. Unfortunately, the recurring scream of the young female protagonist when she takes fatal damage is a sound bite I personally do not want to deal with. I have played ', 'Very Positive', 93.02, 11.22, 0.35);
INSERT INTO reviews VALUES (5852, 428660, 3134, 'Firstly I thought it was a simple puzzle game in which you solve and try to reach to the final level. But after starting, I have to say, it was beyond my expectations.\nIt is like a short TV show and you always want to know what you are going to learn about the story\n\nChill and deep game at the same time\n\nalready bought the sequel game', 'Way too many bugs. You have to restart chapters over in some cases to get through them.\r\n\r\nThis game is old enough to where these bugs should''ve been addressed.', 'Very Positive', 86.22, 5.47, 3.82);
INSERT INTO reviews VALUES (5853, 428690, 7002, 'GAME IS SO FUN!! my mom shot me in the head because i got an F on my test!!! i then had a threesome with my roomates!! best game!!!', 'There is no sex in the game', 'Mostly Positive', 76.85, 5.10, 3.78);
INSERT INTO reviews VALUES (5855, 428750, 402, 'This is such a great and addicting game. It has got me through some tough times. It has all the classic elements from legendary game era in 90''s, good music, nice graphics with a lot of details, great controls and it''s offering a real challenge. \r\n\r\nThe action in this game gets really hectic, after overseer 5-6. I like that!\r\n\r\nI suggest everyone playing this, use a controller!', 'Good mechanics, but a successful run just takes too long and is too repetitive.', 'Very Positive', 94.28, 109.47, 4.38);
INSERT INTO reviews VALUES (5858, 428860, 138, 'One of the weirdest games ive ever played.', 'I wanted to like this game, I wanted to 100 percent this game. But there are just so many unfair and unfun mechanics in this game. First off almost all monsters insta kill you, you are giving a item to undue the death. This is a finite resource that DOES NOT RESET FOR OTHER RUNS, you have to either find more or just take the death. I sometimes would use the item and get booted to the start screen. It would still waste a use. Saves cannot be used if you''ve been caught or get an ending. Sometimes ', 'Very Positive', 81.88, 6.27, 6.42);
INSERT INTO reviews VALUES (5860, 428880, 378, 'A fun RPG worth checking out imo. It has a lot to offer and is charming in many ways, although it certainly doesn''t hold your hand. I''ve always found the early game to be fairly difficult and even a little tedious, but once you have a proper build and equipment it''s enjoyable.\n\nI really want the card mini-game to be its own separate app; I''ve spent quite a while just playing that because it''s so entertaining!', 'classic retro grid based first person dungeon crawler but pretty boring compared to others. Searching containers can be deadly if you are carrying a ranged weapon. If you are not facing in a specific direction you will instead shoot your weapon and possibly hit a civilian, causing you to pay a 500gp fine AND perma lose weapon skill doing less damage. Many quests require you to run backwards and forwards and you are not guaranteed to succeed the quest. You go cash it in and it might fail anyway d', 'Very Positive', 87.57, 35.72, 3.15);
INSERT INTO reviews VALUES (5861, 428900, 342, 'This is meant to be a rage game, but there is no feeling more joyfull and stasifying then uninstalling it after I 100% the game!\r\n\r\nFr tho, good game, simple but you need to be skillful... and a tad lucky... but mainly skill', 'A wildly inconsistent rage bait simulator', 'Very Positive', 80.99, 3.55, 2.88);
INSERT INTO reviews VALUES (5870, 429050, 11176, 'Fun but cant start after download. looks like dev abandoned this game.\r\nIf you are a new user, simply type the following in properties to start it up: \r\ncmd /c set OPENSSL_ia32cap=:~0x20000000 && %command%', 'Abandoned by the devs. Still has critical game breaking bugs that will never be fixed, including many people unable to open the game.', 'Very Positive', 80.32, 8.97, 43.18);
INSERT INTO reviews VALUES (5880, 429330, 103, 'Hurl the sphere! This game makes me feel like dodge ball has got to be one of the only sports that is actually "missing" from the Olympics. \n\nIts great on the Steam Deck with the 360 degree joystick movement and aim.  \n\nIt''s awesome on split screen and controllers with your homie.', 'I will be unbelievably upset if they don''t add an online option, this game could be huge if they added like a ranked, online section where you could team up with other friends. I can just imagine my friends calling shit out and making huge teamplays. As of now, I regret buying...', 'Very Positive', 91.26, 2.52, 1.63);
INSERT INTO reviews VALUES (5886, 429470, 442, 'First in a series of short sci-fi adventure games. Very similar to a point-and-click adventure with an inventory and item combining except it works differently than the usual. Not a RPG with stats, levelling up and combat. I liked that almost everything you see had some kind of comment or interaction, which is not always a given in this genre. I liked the writing which was to the point and witty. Also liked the personalities of the characters. The graphics were standard RPG Maker fare, so they w', 'hot trash', 'Very Positive', 93.67, 4.88, 1.12);
INSERT INTO reviews VALUES (5888, 429490, 100, 'its not c0-op', 'Premise is cool and the graphics are very very nice.  I''ve definitely seen this kind of game done worse but this really feels like someone''s first videogame.  It''s very very basic.  AI is terrible and there''s only one environment.  Mindless fun for a few minutes but that''s it.', 'Mixed', 57.00, 0.15, 2.13);
INSERT INTO reviews VALUES (5890, 429530, 145, 'Don''t check my playtime for this one because I have only purchased this to play the community mod "Falcon BMS" which is absolutely worth it. One of the best simulator on the PC, I would even argue that it rivals DCS in terms of simulation.', 'Can not get CH Pro Throttle USB to work with the CH Fighter Stick USB. Only can get the Fighter stick to work in the game.\nVery disappointed in this problem which I cannot solve.\nI do not recommend this game for that reason. Do not know which controllers work with this game. Am running Windows 11. Could this be the problem??', 'Very Positive', 87.59, 0.20, 0.75);
INSERT INTO reviews VALUES (5892, 429570, 2201, 'Not a fan of this series. Story was alright. Also, Michonne was the badass', 'The story and characters are boring as hell (compared to the other games at least) but I bought it for the sake of funding telltale to make sure The wolf among us season 2 is still in development and release eventually 😭🙏\n\nSide note: I can’t even take the game seriously with michonne looking like a female version of dreamybull', 'Mostly Positive', 76.24, 4.77, 3.93);
INSERT INTO reviews VALUES (5895, 429610, 141, 'One of the better stories in the HOG series I have played from Artifex Mundi. Probably because of another developer, Gogii Games, the story is very interesting and keeps you going. A lot of new or different puzzles, and I played like 10 of these kind of games. I bought it on sale, but it is worth the money.', 'I don''t recommend The Emerald Maiden: Symphony of Dreams. It is a functional Hidden Object Mystery, but the puzzles are very easy and several of the story''s twists turn out to simply be the main antagonist putting on a puppet show for the benefit of the protagonist. The aesthetics are generally good, with some nice underwater resort set pieces in the general vibe of Bioshock. There''s a cool technician on staff who is half sea creature. I just... don''t feel that the plot holds together very well.', 'Very Positive', 85.11, 7.75, 3.55);
INSERT INTO reviews VALUES (5896, 429620, 252, 'Dungeon Rushers\n\nHas a total of 10 trading cards.', 'Dead game.', 'Mixed', 54.76, 2.40, 16.82);
INSERT INTO reviews VALUES (5897, 429660, 6147, 'Even though it says unsupported it runs perfectly fine on my steam deck oled 10/10 very satisfied with this game', 'A rotten company with racial discrimination', 'Very Positive', 92.11, 38.12, 1.05);
INSERT INTO reviews VALUES (5900, 429700, 121, 'My Grandfather smoked his whole life. I was about 10 years old when my mother said to him, ''If you ever want to see your grandchildren graduate, you have to stop immediately.''. Tears welled up in his eyes when he realized what exactly was at stake. He gave it up immediately. Three years later he died of lung cancer. It was really sad and destroyed me. My mother said to me- ''Don''t ever smoke. Please don''t put your family through what your Grandfather put us through." I agreed. At 28, I have never', 'Concept good, but touchy difficulty ruins experience. Platform edges and timing issues make gameplay frustrating', 'Mixed', 60.33, 485.27, 1.18);
INSERT INTO reviews VALUES (5901, 429720, 1746, 'Was streaming on discord to my friend group. Scared me so bad I accidentally hit a shortcut combo that opened NSFW on stream.\n\n10/10 worst fears realised\n\nThe labyrinth section was slightly annoying', 'this shi scared the pee and poop out of me bruh dont install if your not ready', 'Very Positive', 94.56, 2.52, 4.12);
INSERT INTO reviews VALUES (5902, 429780, 278, 'add workshop content', 'so basically I am this users friend and i dont know if he will ever notice this shit but this game was actually alright if you like bhop i rec', 'Mostly Positive', 71.22, 7.32, 7.60);
INSERT INTO reviews VALUES (5904, 429830, 137, 'I love this game, it really shows the immersive power of VR, and particularly ''redirected walking'' - I truly felt that I was exploring a large complex, and not just crawling around my living room, and it made me feel very immersed in the world. I hope more developers explore and incorporate the redirected walking concept, because it could be a great alternative to the commonly used teleportation mechanic. I will say that the game is very very very short, but well worth it for $3- I will be showi', 'only reason why I rathed this negative is...\nIf you dont have a 3x4meter room, then you cant play this game.\nSo for people with smaller space will not be able to play this game.\nYou would need a room with ATLEAST 4x5meters, due to so you DONT hit your face or controllers into the walls.\nIf and when they will make it roomscale suport, this game remains as a not recomended game', 'Very Positive', 90.51, 1.88, 0.17);
INSERT INTO reviews VALUES (5907, 430020, 126, 'Dance of Death\n\nHas a total of 8 trading cards.', 'Hidden objects with dark atmosphere, repetitive puzzles, frustrating mechanics and unsatisfying ending', 'Mixed', 56.35, 1.00, 2.98);
INSERT INTO reviews VALUES (5908, 430070, 194, 'i really love this game. the story is devastating but interesting, it made me feel sth 1st time in a while ^ ^ \r\ni adore music, art style, gameplay(even though the mirrors was a real nightmare), even after death scenes, i''ve never seen sth like that, thats cool. i wish the game was longer =( but still its absolutely 10/10 \r\nif u into horrors please try this one!! its gorgeous', 'game sucks im with the first boss hes all in fire idk what to do with the switch boxes i gave up not worth my time', 'Mixed', 67.01, 5.42, 0.75);
INSERT INTO reviews VALUES (5913, 430210, 1414, 'guess who finally got his powers haha', 'the vr will not work at all ts pmo idgaf sybau', 'Mostly Positive', 72.28, 3.98, 0.12);
INSERT INTO reviews VALUES (5921, 430960, 1381, 'Homies caught me crying over the Discord Call while playing this game ... Twice. 10/10 Highly recommend to anyone seeking to become an emotional wreck over adorable android waifu.', 'The story does not make me happy. It makes me angry. If you want a relaxing VN this is not it. The game is supposed to be a tragedy and I was supposed to feel sadness for  the death of Lucy at the hands of the protagonist''s abusive father   at the end according to the story, but it absolutely fails at that. I feel nothing but agitation and anger.\nThe slice-of-life sections fail too for being too generic.\nThe father should have rotten in jail for his horrible abuse done to the protagonist.\nIt is ', 'Very Positive', 93.85, 18.27, 6.83);
INSERT INTO reviews VALUES (5923, 431120, 151, 'Beautiful VR strategy game!  If you loved God games of yore like Black & White, Populous, Cultures, or some of the early Settlers games, you will feel at home. The controls are quite simple. (On HTC Vive) You use grips to move the world around and triggers/ thumbpad to "tether" your Norn-like peeps to resources and buildings.  The weather plays an important part in controlling production, access, defense, and healing.\n\nIn order to complete each world, you need to gather Spirit Essence to wake th', 'I hate games with broken achievements', 'Very Positive', 82.12, 7.37, 52.97);
INSERT INTO reviews VALUES (5925, 431180, 1156, 'woof woof bark howel woof bark bark growel', 'bad traumatic experiences with my ex: classic edition', 'Very Positive', 91.96, 74.18, 12.88);
INSERT INTO reviews VALUES (5929, 431240, 33657, 'Horrible game. Absolutely horrendous. Despicable. Never have I played a game that drains my soul from me as much as this. I don''t think I''ve ever ended a game of Golf with Friends wherein I did not feel sad, useless and all around miserable.\r\n\r\nVery good game, would recommend with friends!', 'apparently this became a DLC infested mess since I played it. Wonderful...\n\nBase game is good, but it has way too much DLC for me to recommend anything beyond that. They''re charging too much for what used to be free updates.', 'Very Positive', 89.57, 57.40, 39.23);
INSERT INTO reviews VALUES (5930, 431250, 152, 'I loved playing this game on the ps3, and it''s still fun on pc. Still liked how it''s pretty challenging on the hardest difficulties, but still doing my best to get those 3 stars!', 'Says it supports both remote play and local multiplayer and it does neither. Devs too focused on cash grab of Mushroom wars 2 to fix servers or to make multiplayer work at all. very disappointing.', 'Mostly Positive', 79.61, 10.73, 0.33);
INSERT INTO reviews VALUES (5931, 431260, 248, 'Hah, this is a puzzle game that makes you feel like you are speed-running it already on the first try. Pure sugar for the brain. You mash throught problems like you''re the doomguy.\n\nLoved it. It''s short and you''ll feel like a puzzle-god. It''s a fun palate-cleanser where you''ll never be stuck for longer than 15 seconds. You''ll get the obvious items when you need them and while some of the puzzles are  moonlogic, you''ll understand them.\n\nI also have a special place in my brain for the photoshop-ma', 'Not sure if this was good upon release. Now it''s severely outdated. The main problem with this game is that the image is kinda zoomed in on modern screens. You might not notice that until it starts interfering with puzzles. You simply don''t see everything there is which makes some puzzles much harder than they should be. Even the in-game map of locations cannot be fully seen. You can''t change resolution here and switching to windowed mode doesn''t help.\n\nBeside that, the graphics are very old, an', 'Mostly Positive', 72.98, 2.95, 2.68);
INSERT INTO reviews VALUES (5939, 431450, 204, 'fun game but its short and simple', 'What''s there is fun to mess around with for a bit, but in the end it''s an unfinished game. Don''t bother wasting your money since it''s been abandoned.', 'Mixed', 67.65, 9.28, 1.60);
INSERT INTO reviews VALUES (5947, 431590, 438, 'This was a SUPER NECESSARY tool for every IT class back then', 'The main game: fun.\r\n\r\nThe 50 extra missions that no one asked for: not fun.', 'Very Positive', 92.47, 31.02, 12.57);
INSERT INTO reviews VALUES (5948, 431600, 613, 'Played with a Moza R3 wheel and SRP Lite pedals, played a lot of AMS2 before getting this and zero regrets. Amazing FFB, Physics and some of the highest quality mods available in sim racing. CART extreme or anything made by IDT are top of the top quality mods.\r\nThe customisation including changing what side of the car you sit on are some really nice features I remember from rF1, also changing the strength of the power steering assist and other small details some series offer are really nice to f', 'No proper controller support for this game and TOTALLY SHITTY CAR HANDLING for all cars. Like.....the worst game e-v-e-r.....:(', 'Very Positive', 85.97, 33.40, 4.25);
INSERT INTO reviews VALUES (5952, 431650, 316, 'The game plays a little like an easy Subnautica; you collect elements from the environment, "craft" updates and move up in the story; it''s never too difficult. Unlike Subnautica, there are other characters that speak to you, so it doesn''t feel as lonely. The graphics for your character could use a bit more refinement (the robot looks a bit awkward, like a beta version).\r\nWhere the game excels is in ambience. The environments are beautiful, and the music is some of the best I''ve listened to recen', 'Level design locks you from finishing the game', 'Mixed', 65.51, 16.03, 0.45);
INSERT INTO reviews VALUES (5954, 431700, 118, 'Age of Fear 3: The Legend is a turn-based tactical combat game that focuses more on gameplay than graphics. The developers admit the visuals aren’t flashy, but the deep combat system more than makes up for it. You control two campaigns: one with a dryad and a spider-like drider teaming up, and another about a drunken dwarf lord on a rampage. Both stories are fun and full of humor.\n\nThe game is made up of missions where you face new enemies and challenges. Sometimes, losing a mission can even unl', 'I feel bad not recommending this game. It''s not careless or disrespectful of the audience. There''s a lot of value with 2 branching campaigns. Unit variety is nice, upgrade options for units (who stay with you mission to mission) is varied and interesting. The story itself is not well written but it is original as are the characters.\n\nIt''s an indie game with basic production value, no animation and fairly bad art. But that''s not why I''m not recommending it, I''ve played long enough to not care, es', 'Overwhelmingly Positive', 95.76, 6.48, 18.67);
INSERT INTO reviews VALUES (5955, 431730, 9838, 'Weird game. You spend most of your time drawing things out of little dots. I haven''t found any weapons or items yet. Maybe if I keep drawing, something will happen.\r\n\r\n11/10', 'what the hell, this isnt a game?????????????????', 'Overwhelmingly Positive', 99.20, 25.35, 4542.40);
INSERT INTO reviews VALUES (5957, 431750, 132, 'Engaging and fun with simple design - yet very challenging.', 'A port of a tower defense game that is VERY basic, at least it is a very easy 100%.', 'Mostly Positive', 78.79, 312.12, 8.37);
INSERT INTO reviews VALUES (5958, 431770, 192, 'it''s fun but would''ve been better with more crazy maps like the sparta one', 'Something that you should find for free on some random website.', 'Very Positive', 91.15, 2.87, 0.77);
INSERT INTO reviews VALUES (5964, 431930, 102, 'Game is very good amazing soundtrack and really fast paced.... but the big fault is... there are no players... this game even tho amazing is completly under the rug and nobody knows it exists... has every potencial to be an amazing game if it gets a stable player base... if not it dies before it starts.\n\nI hope the game picks up cause the game is really really good! Bit expensive but totally worth!\n\nIf you like Pinball, Rocket League and making people Rage over losing points this is the game for', 'I''d be remiss if I didn''t give substantial credit to the passion and talent behind this game, and in my opinion, the vast majority of positive reviews for Kabounce are well-warranted. However, while it''s unique concept and style are enough to charm those looking for the next big entry into the "extreme sports hybrid" genre, I cannot recommend it - especially at the $15 mark...\n\nThe game does pit you against a team of fairly-formidable bots in the absence of real players, but Kabounce''s player ba', 'Very Positive', 90.20, 1.97, 5.47);
INSERT INTO reviews VALUES (5965, 431940, 241, 'The concept is nice. My only issue is the lack of skill points. You need to redo the game 3 times to get all the skill points allowing you to complete the skill trees. It''s a linear game with no replayability, so there is no reason to do it again 3 times.', 'Out of 9 Hours i probably had only 30 minutes of actual enjoyment. Mechanically it just is not that interesting, it is an incredibly boring game that tries it''s best to make stealth fun but ends up becoming tedious, samey and agonising later on when patrols take upwards of 40 seconds to do something. AVOID', 'Very Positive', 86.72, 16.92, 9.92);
INSERT INTO reviews VALUES (5967, 431960, 206729, 'I really love wallpaper engine, it''s my favorite app of all time.\r\non September 12, 2022 I hit a person with my car and did not stop, they were never found.\r\nwallpaper engine has so many cool animated wallpapers and I really enjoy using it!', 'this game is bland, no enemies, no leveling, no bosses, no protagonist, unpettable dogs', 'Overwhelmingly Positive', 98.19, 39.77, 11.70);
INSERT INTO reviews VALUES (5968, 432010, 645, 'Up until the lockball mini game, this was actually fun. I have trouble with my hands and have come across a frustrating pattern with simulation games. Generally, the mini games require a stupid amount of dexterity. This makes game completion almost impossible for players like me that deal with hand pain on the daily. I loved the game overall until I hit this mini game in my first summer. \n', 'the controls in this game are just a pain in the ass. I still haven''t found out where i could look up my current quest. Pretty sure it''s not possible to do so. Because i was having so much trouble just trying to navigate the game i tried using a controller... which didn''t help at all. At this point I just uninstalled it for now. Might try it again later when my patience has reached to Ghandi -level', 'Very Positive', 80.00, 23.90, 2.52);
INSERT INTO reviews VALUES (5970, 432100, 413, 'A decent game, Good story and quite a few different endings.', 'This was an idea to try this game as my first visual novel game.\n\nConcept good. Genre doesn''t click for me. Sorry!', 'Very Positive', 83.54, 4.32, 0.75);
INSERT INTO reviews VALUES (5983, 432350, 2628, 'One of the golden remnants of the flash game era of the internet, I still remember when EBF 3 came out in 2010 and it was phenomenal for what it was. This is no different and is even better than it''s predecessors. \n\nlets just say getting pwned in 2024 brings a tear to my eye :,)', 'ebf4 is better.', 'Overwhelmingly Positive', 99.01, 115.40, 23.78);
INSERT INTO reviews VALUES (5984, 432370, 101, 'Such a shame there''s no neutral rating instead of a like or a dislike. The concept of studying the language and philosopthy of an alien civilisation is phenomenal; unfortunately this is not a puzzle game — it''s a walking simulator. The notebook guides the player question by question, sign by sing throughout the game, and asking almost any diffrent question will result in the computer responding ''I don''t understand''. I feel like the game would have benefited from more side content and slower prog', 'The concept of this game is *really* cool. I love language translation games, and the idea of talking with a computer in a custom language is really engaging to me.\r\nHowever, the execution falls flat. The "knowledge base" of the computer has very limited information, and so if you try to ask it questions you came up with yourself, you''ll usually just be left with a generic confused response, even if your question made perfect sense grammatically or contextually.\r\nWhile I enjoyed the first little', 'Mixed', 65.35, 2.37, 1.58);
INSERT INTO reviews VALUES (6005, 432980, 129, 'This is one of the best, yet simplest couch multiplayers I have played.   I cannot reccomend this enough!', 'way too simple, there''s barely any game to be had.', 'Very Positive', 90.70, 7.12, 0.23);
INSERT INTO reviews VALUES (6007, 433000, 261, 'Love this series of games.  They have a lot of playing hours, stories are good and puzzles/quests are well thought out.  Highly recommend.', 'As much as I love this series this one is especially hard. If you don''t click on the exact spot you will miss it. You are forced to do things in a specific order more than usual. And the puzzles are just as bad. I used more hints in this one than the rest.', 'Very Positive', 92.72, 83.87, 23.45);
INSERT INTO reviews VALUES (6008, 433100, 792, 'Story driven walking sim where you get to explore cool long abandoned insane asylum. Story itself is probably the saddest i''ve ever come across in any game.', 'The game shows the sad reality of mental institutions taking place in the 40''s when it was pretty bad. The story isn''t bad its fairly good. My main issue with this game is the snails pace you progress at. It makes the game boring. If you could walk faster I think that would eliminate my concerns with this game. Its a similar feeling to people walking slowly infront of you with no way around them. If that doesn''t bother you then I would recommend it.', 'Mostly Positive', 72.10, 3.27, 4.62);
INSERT INTO reviews VALUES (6012, 433170, 592, 'I hold a lot of nostalgia for this game since I first played it back in 2020, when I had much more time to analyze and think harder on games (since I really couldn''t do much else). I really quite like the game but I can understand the negative reviews. The graphics are a bit poor at times, specifically some of the texturing on ceilings and small details, but that doesn''t really matter to me since the world feels alive. It''s fairly small and contained when compared to other, bigger-budget open wo', 'Die Young has a mediocre story and unappealing world with lots of pop-in. The combat is super clunky, stealth is boring and enemies are spongy. Just not fun, at all. Not recommended', 'Mostly Positive', 77.36, 14.63, 6.15);
INSERT INTO reviews VALUES (6016, 433280, 491, 'How is there not a modern remake of this game.', 'The worst of the three Warlords Battlecry games, and the only one available on steam. I still love it, but it doesn''t hold a candle to 2, and even the first instalment was better. The patch that added spellcasting cooldown and timed life to summoned units was possibly one of the worst things I''ve ever seen, would recommend getting WB2 on GoG instead of buying this', 'Mostly Positive', 79.63, 6.67, 14.33);
INSERT INTO reviews VALUES (6017, 433300, 382, 'IF THIS GAME IS EVER PURCHASABLE. BUY IT', 'Controller mapping is not correct and when I try to use a custom map, the controller flat out will not work. I went to YouTube and there seems to be some work arounds but that shouldnt be necessary for a game on Steam! Says I have played for 4 hours and I''m unsure how as I have not done anything in game due to the lack of actual controller support. If they patch this, I will gladly change my review.', 'Mixed', 58.64, 8.05, 5.92);
INSERT INTO reviews VALUES (6018, 433320, 264, 'fuck disney', 'The controls are messed up and can''t be remapped, but I imagine there are more technical problems with this on a deeper level, because they decided to unlist it instead of fixing it.', 'Mixed', 46.97, 22.82, 6.95);
INSERT INTO reviews VALUES (6027, 433530, 1860, 'yes, it''s abandoned and dead, but god its so fun to play alone in a multiplayer server. super addicting gameplay loop', 'Abandoned and buggy.\n\nNo idea why people still rate this up.', 'Mostly Positive', 74.89, 12.93, 98.78);
INSERT INTO reviews VALUES (6028, 433550, 1668, 'This game features creative puzzles, creepy horror elements, and a unique art style. It''s everything I love in one package.', 'There are some unique and fun uses of perspective that permeate the level design of this puzzle game. But it rings hollow in the lack of any substantial story or atmosphere built in the game. Just some TIm Burtonesque setting and hint of dreamscapes and then you do the puzzles. I wouldn''t recommend unless you just want a decent puzzle game fix.', 'Very Positive', 94.24, 6.00, 2.07);
INSERT INTO reviews VALUES (6032, 433600, 154, 'Not what I was expecting, but very good. The game makes me feel like the world is a toy set and I''m some kind of dungeon god.\n\nEdit:\n\nThis game is now even better, I love the new scale, well done to the developer. Keep up the good work.', 'There are good things and bad things about A Legend of Luca.  You can tell that the developer listens to his audience.  Originally the game was designed as being "a room-scale vr game" and after feedback, they have changed the game to teleportation controls.  I originally purchased this as I was intrigued by the thought of actually having to move around the room to play a game.  This wasn''t ideal however when put into actual play, as the floor was set to be at waist level and you kind of felt li', 'Mostly Positive', 79.87, 1.25, 2.02);
INSERT INTO reviews VALUES (6042, 433850, 37728, 'trying to get more people to play this in 2024. this game was the perfect arcade battle royale. lets unite gamers worldwide and revive this game PLEASE', 'This is an example of taking arguably one of the best games in the last decade and completely breaking it out of greed. Developers need to avoid unnecessary changes to game mechanics. The massive population boom wasn''t for the good graphics, it was for the intense, basic, game play. Don''t break what isn''t broken. RIP H1Z1', 'Mixed', 51.16, 76.18, 507.00);
INSERT INTO reviews VALUES (6045, 433910, 841, 'Spend your life savings on this amazing neon car game. Heck, even if you only have enough money to eat just starve to death while you at least have this in your hands', 'I would love this game IF the perspective was semi-top down so u could see more fully what''s coming ahead, and IF there were no memory testing aspects the the stages, or , at least, an alternative set of stages that were memory testing- free.\nShame, coz the general vibe of the game is great.', 'Very Positive', 84.07, 28.98, 0.48);
INSERT INTO reviews VALUES (6048, 433950, 3030, 'A cheap, simple and enjoyable arcade game.', '\r\nIf so just play Super Bit Blaster XL which is an improvement to this game.\r\n', 'Overwhelmingly Positive', 97.06, 0.53, 4.78);
INSERT INTO reviews VALUES (6050, 434000, 394, 'i cried', 'Yes, I played this before the playing the Shelter games, this is true. However, it wasn''t a terrible game, it was sad and brought slight tears to my eyes. The story had nothing to do with my thumbs down review. My only issue with this game is the price. It was not worth $20. Maybe buy it on sale for $5? It''s just way too short of a game for it to be worth the amount I payed.', 'Very Positive', 91.37, 1.30, 1.67);
INSERT INTO reviews VALUES (6051, 434020, 230, 'Very fun game with the right amount of leveling up. I played for 24 hours total.', 'A mobile game that is the typical tedious, boring, grind-fest. Bought it dirt cheap and played it when bored.', 'Very Positive', 81.30, 24.00, 78.28);
INSERT INTO reviews VALUES (6052, 434030, 1171, 'its a lekker game if u want a starter fs sim', 'outdated unrealistic physics js terrible get xplane, or msfs but physics are shit in alot of areas', 'Mostly Positive', 79.68, 41.80, 6.40);
INSERT INTO reviews VALUES (6053, 434050, 2818, 'For 2$ its an ok version. There are issues with bad sound quality, censorship issues which include a removed female sprite, CTRL F1-F9 insults are missing their audio.... Volume level issues for dukes voice... Few bits of art changed for various legal reasons. Not exactly faithful to the orig copy of the game.\n\nRuns well on Win 10.', 'The 20th Anniversary version is the best looking Duke Nukem remaster in my opinion, with true 3D rendering, you notice it when you look up and down. However, the actual feel to the game has been ruined. The game''s mouse look has a deadzone where fine adjustment is close to impossible. Everything you do seems to have an input delay, this is very noticeable in the game''s movement, where running, stopping, or changing directions make you feel like you''re walking on ice. Queueing weapon swaps are re', 'Very Positive', 80.38, 8.30, 8.25);
INSERT INTO reviews VALUES (6060, 434170, 4033, 'quiplash is RIGGED!!!! you just need to be RACIST! and you get 60% of the VOTES!!!', 'Nobody wants to play any Jackbox games. Every time I try to ask people to play, they either don''t want to, or don''t know what Jackbox even is. Fucking hate this.', 'Overwhelmingly Positive', 97.22, 24.52, 2.13);
INSERT INTO reviews VALUES (6062, 434210, 186, '^ↀᴥↀ^\n\nSpring, Summer, Fall, Winter ... and Spring.', 'although im not the intended audience as a 30yr old female, i found this "game" rather odd. theres no real game play other than continually clicking on 3 trees, some clouds and the ground, and when you''ve seen all 4 seasons, the game loops back to the start without any real ending. also i wasnt too keen on the graphics/ art style, the sound effects were often louder than the audible dialogue and if you over-clicked, the dialogue would often move onto the next sentence before it had even finished', 'Very Positive', 91.94, 2.25, 4.83);
INSERT INTO reviews VALUES (6066, 434250, 354, 'good 2', '\r\nMultiplayer only game, not playable. Essentially a bad version of Counter Strike pretty much.\r\n', 'Mostly Positive', 78.25, 1.30, 3.57);
INSERT INTO reviews VALUES (6067, 434260, 1536, 'Absolutely life changing experience it fixed my marriage', 'ketchup is better', 'Very Positive', 84.18, 2.38, 3.77);
INSERT INTO reviews VALUES (6070, 434290, 112, 'bravo', 'boring.', 'Mostly Positive', 71.43, 4.57, 0.18);
INSERT INTO reviews VALUES (6075, 434370, 146, 'i enjoyed the game <3', 'Great if you like reading reading and then some reading! Myself i like to play games. Would i reccomend this? No id rather watch my close family been mauled to death by a pair of bengal tigers whilst listening to tom jones greatest hits. Hope that helps :(', 'Overwhelmingly Positive', 95.21, 4.13, 0.08);
INSERT INTO reviews VALUES (6077, 434420, 484, 'The most generic jrpg on the planet featuring Tenebrous Deathbringer and a bunch of girls in bikinis. It probably wasn''t playtested so I''m grinding on a boss that''s not supposed to be repeatable so I don''t have to actually play the rest of the game. Normally I don''t like RPGMaker games that aren''t just walking simulators but I deeply appreciate this one not being ATB at least.\n\nit was 50 cents and I''m only reviewing it to blast anime titties at my friends'' recommended pages.\n\nAddendum: Having a ', 'RPG Maker game with weak story, flat characters, and decent animations, but ultimately forgettable experience.\n', 'Mixed', 65.50, 5.03, 1.70);
INSERT INTO reviews VALUES (6079, 434460, 992, 'Best game of all times, But first you gonna do is to be a programmer to open a game', 'Its broken, it don''t work.', 'Very Positive', 89.11, 0.22, 0.25);
INSERT INTO reviews VALUES (6088, 434570, 12741, 'This game is a masterpiece, a true masterpiece. It has realistic gun play, realistic graphics. Billions must try this realistic game', 'I gooned day and night thanks to this game<3', 'Overwhelmingly Positive', 96.16, 1.35, 4.32);
INSERT INTO reviews VALUES (6092, 434620, 117, 'nice logic game', '2/5\nThe game is primitive and lacks self-identity. I''ve passed the game for achievements by simply clicking all the numbers until the guess is correct.\nNot saying that it should''ve had a small story and characters but something wholesome would make the dev more profits. People only buy these types of games for steam trading cards, badges and achievements, sometimes there is some soul can be found but most of the times this type of slop is what you get.', 'Mostly Positive', 70.94, 6.85, 1.97);
INSERT INTO reviews VALUES (6093, 434650, 1375, 'My wife and I had an absolute blast playing this. Excellent replayability.', '''Failed to install Epic Online Services''\nYeah, instant requested a refund.', 'Mostly Positive', 79.56, 252.92, 0.45);
INSERT INTO reviews VALUES (6097, 434730, 1134, 'This game is very challenging. I would definitely play this half dead game first before half dead 2 and half dead 3 to know what it''s all about. This is based off of all the cube movies I have watched so I know what to expect. It''s all about survival and survive to get to the exit from start to finish.', 'This game is quite frankly just not very fun. Unfortunately, there is zero point to the game and in my opinion, watching paint dry would be more entertaining. Sorry guys, but its a no from me. ;)', 'Mostly Positive', 76.63, 5.42, 0.33);
INSERT INTO reviews VALUES (6120, 435100, 111, 'Extremely under appreciated video game, i think this deserves more attention for what it dose right. Its not perfect and at times comes off as edgelord p0rn, but i do think the games style and mechanics are uniqe and compelling enough to warent taking a look at it. Other than that i love killing child predators.', 'always onine DRM. I wouldnothave bought it if I had known at purchase.', 'Mixed', 69.37, 9.42, 0.98);
INSERT INTO reviews VALUES (6121, 435120, 1845, 'Really good addition to the series.  Quite short and the puzzles are pretty easy. I wish there was an option to restart days in case you miss secret ingredients from other days rather than having to restart the entire save.  Brilliant puzzle game though!', 'Rusty Lake PLEASE DO SOMETHING ABOUT YOUR GRAPHICS. They are so ugly and amateurish. That was fine when you were doing silly little flash games but not when you''re asking money for something that looks as horrid as this. I know that you''re most likely just a two person team but I also know you make FUCKTON of money from these games. Or at the very least enough for you to hire a proffesional artist that can draw better than this middle school level stuff. And don''t you dare try to say that "it''s ', 'Very Positive', 93.71, 2.87, 1.30);
INSERT INTO reviews VALUES (6123, 435150, 78306, 'I came to this game from Baldur''s Gate 3 cause I wanted to try another game from Larian Studios. I didn''t expect much since it''s an older game, but, I''ve been pleasantly surprised. It''s very immersive! There''s so many items to find everywhere, the music is great, and I''m enjoying the voice acting. There''s so much attention to detail and the tutorial really helps to ease players into the game. I''m 69 years old and have never played turn based games like BG3 or DoS2  but I"m happy to say you''re ne', 'The cover art is disgusting. That big male head just stinks, looks greasy, and filthy. It assaults my eyes every time I scroll through the library. The gameplay is fine, but the game is crawling with men. Even the origin characters are only 2 female and 4 male.', 'Overwhelmingly Positive', 95.41, 30.72, 26.22);
INSERT INTO reviews VALUES (6127, 435300, 857, '"It''s like... I didn''t realize how much my body was, bothering me, all the time, before? And when they''re peeled off it finally feels like I don''t have to think about them so much. Like normal."', 'I''m just lost on this one and I fit the target demographic. The BGM and foley really confused the tone for me throughout the first playthrough. The narrative was both banal and pompous with no discernable plot. Then it just ended. \n\nI might try the other endings for achievements and to see if anything at all becomes more clear but then again I might just be done with this one. \n\nI read a good review of it somewhere and I guess to each their own.\n\nEdit: finished the other endings. Still not for m', 'Overwhelmingly Positive', 95.33, 3.32, 1.43);
INSERT INTO reviews VALUES (6130, 435400, 3076, 'This game is great, I think that it''s the first hidden object that I don''t go clicking on all the cats/dogs/bees but instead I read the thingy/person description and try to find it in the context of the image. \r\nSound effects are 12/10.\r\nIf you enjoyed any 100 cats type of game do buy this one, you will not regret.', 'If you suffer of migraines or are photo sensitive or get triggered by mouth sounds I wouldn''t recommend this game. \nI really wanted to like it, I tried to get through multiple levels, but the brightness and contrast hurt my eyes and felt more annoying than relaxing, and the mouth sounds didn''t help. I expected relaxing music, but theres no music, just someone making mouth sounds on your ears. Sadly I can''t stand any of that. But I can acknowledge at least that it''s a cute funny well made game.\nE', 'Overwhelmingly Positive', 96.62, 8.17, 0.40);
INSERT INTO reviews VALUES (6132, 435490, 214, 'I dropped like $5 worth of coins into the claw machine and didn''t win a damn thing.  Just like real life.\n\n10/10', 'As other have said, the controls are awful. Purchased 2 copies so my friend and I could play together. Could not interact with the multiplayer button at all. The developer needs to overhaul the controls for this game. Until then, It''s a no from me.', 'Very Positive', 87.38, 1.68, 0.53);
INSERT INTO reviews VALUES (6133, 435530, 2113, 'This is a hidden gem on steam. The story is very intriguing and I can''t say much how it unfolds in the end. It''s simple and short but overall worth for it''s price. The DLC is worth playing too.', 'Whose idea it was to have missable dialogue on the train in a story-heavy game? I guess it doesn''t matter anyways because the translation sucks, I assume this was written originally in Russian, but even in the credits it doesn''t show you a writer. Overall it''s a game that fails at its fundamentals. \n2/5', 'Mostly Positive', 79.18, 6.42, 4.25);
INSERT INTO reviews VALUES (6140, 435840, 101, 'Pro:\n+ Preposterous\n+ Awesome\n\nCon:\n- Is not actually about everything', 'While I can see the appeal, this game wasn''t for me. I guess that''s the point of experimental games though, huh? To be weird and out of people''s comfort zones.', 'Overwhelmingly Positive', 97.03, 2.02, 0.68);
INSERT INTO reviews VALUES (6153, 436290, 253, 'This is a story about a girl seeking freedom. It does not delve into the nature of the Zodiarc weaponry. The battle mechanics is innovative and I delight in having a new concept to consider. There are pretty strong boundaries to the kind of sandboxing I usually like, though. Having the choice to listen to the story as you progress is really nice, though.', 'Only positive is the gameplay.\nYou just get thrown in a couple of fights as a bunch of annoying kids without any explanation why\n', 'Mixed', 67.59, 36.65, 1.25);
INSERT INTO reviews VALUES (6154, 436320, 1667, 'Works perfectly for me using Quest 3 and cable link.Problem is this is premium VR from 5-7 years ago. Let it die. Steam link is just streaming cable link. There''s your problem. Streaming. You can''t. Neither can anyone else, really.\n\nRecommended. Still premium.', 'Leading Global VR Gaming Studio, Award Winning Immersive VR Games.\nEvery their game is abandoned and barely functional, don''t ever buy anything from them, even for free it''s not worth it.\n', 'Very Positive', 81.04, 2.27, 0.12);
INSERT INTO reviews VALUES (6157, 436390, 182, 'C = jump\nX = shoot\n\nall u need to know\n', 'Too much difference between level difficulty.\nLast levels are many rooms without save with pixel and millisecond moving/jumping.\nGame seems not tested.', 'Very Positive', 91.21, 4.57, 7.60);
INSERT INTO reviews VALUES (6161, 436490, 141, 'An absolutely magical experience for anyone who enjoys theatre. I picked this up for £2 and its worth a fiver of anybodys money, especially the replayability.', 'I''m so sorry but I wouldn''t recommend anyone to buy this product. Even if I found it as a breathtaking experience, it''s really not worth it for 10€. It takes 15 minutes to be completed and is not "replayable" (unless you want to see the same thing again), and of this 15 minutes, only 4 or 5 are GREAT, the rest is just ok. I can see the potential in the developers of this game, so I really hope that they bring something more playable, or at least a bit longer.\n\nCome on! Give as 1 hour of experien', 'Mostly Positive', 75.89, 0.33, 0.68);
INSERT INTO reviews VALUES (6162, 436500, 514, 'They Might Be Giants once asked the question "Should you worry when the skull head is in front of you, or is it worse because it''s always waiting where your eyes don''t go?" While Diaries of a Spaceport Janitor sidesteps the question, it does definitively state that the skull head in front of you isn''t nearly as frightening as being stuck in a dead end job in capitalist hellscape.', 'I am sure that if you are the target audience, you will love this game. There is supposed to be a good message in here, but the gameplay loop was SO BORING that I couldn''t stick it out long enough to get much into it. Perhaps I am just misunderstanding the gameplay loop (burn as much trash as possible except stuff NPCs consistently find helpful and stuff you can offer at shrines?), but the game as I understood it was a boring, monotonous grind. I agree with some other reviews that a better tutor', 'Mostly Positive', 79.38, 8.65, 2.02);
INSERT INTO reviews VALUES (6164, 436520, 1178, 'This. This game. This game right here. Everyone says "f2p CoD!" "Pay 2 win!" I for one say:\n\nTotally a f2p CoD. No denying it, Doesn''t mean it''s a bad game. Snipers are often 1 hit kills, so expect a MASSIVE amount of snipers playing. Rifles are good too. BUT, it''s like 100k to perma buy any gun, and you get like 300 gold for a 30 kill deathmatch game. Might just be me but it''s slightly hard to get some guns. But you can just temp buy it. This doesn''t make the game pay 2 win, BUTTTTTT the Traini', 'It should be a free-to-play game.  In game you can rent guns for about 60,000 in game points.  You earn about 150-200 in game points per game.  There are little daily bonuses, but you''re looking about 3-5 days of solid play time in order to rent a new gun for 7 days.  To purchase a gun permanently you need to pay about 400,000 in game points.  Or of course, just spend your real money to get a gun quicker, which is what the system seems designed to do.\n\nThis is an old, worn out model I''ve seen in', 'Mixed', 53.23, 9.95, 6.28);
INSERT INTO reviews VALUES (6166, 436560, 532, 'You people need to learn patience and stop buying early access games looking for instant gratification.\nThe more you jump the gun and give it a negative review for no reason other then your own lack of common sense means that other people will less likely buy it and the development will cease.\n\nI would like to see this game grow into something more and realize that development can take years.', 'Abandonware. Do not buy.\n\nThe website for this game is currently throwing a 503 error while the studio''s website seems to be fine. As is the website for their terrible looking Battle Royale game.\n\nIndustry Games is abandoning this incomplete project because they''re looking to make a quick buck off the Battle Royale craze. They are NOT looking to make quality games. They are looking to take advantage of Steam''s complete abrogation of responsibiltity to curate the platform by churning out incomple', 'Mixed', 51.69, 1.55, 20.72);
INSERT INTO reviews VALUES (6167, 436670, 1400, 'Totally worth it just for Renne’s backstory alone. Hits even harder once you’ve played the rest of the franchise—pure Trails magic.', 'The gameplay of this entry in the series is much more balanced, and the strategy continues to be more fleshed out in a satisfying way. However, that is where my praise ends for this game.\r\nThe devs clearly had been given less time and money to make this game, compared to the first and second chapters. Despite their obvious attempts to make ends meet in spite of their challenges, the game severely suffers due to the lack of time and effort allocated. There are no new settings in this game, beside', 'Very Positive', 94.79, 39.40, 89.27);
INSERT INTO reviews VALUES (6177, 437000, 214, '"I guess you guys aren''t ready for that yet. But your kids are gonna love it."\n-Guilty Gear 2: Overture reception through the years summarized', 'blows dookie shrek', 'Mostly Positive', 78.50, 7.60, 6.42);
INSERT INTO reviews VALUES (6185, 437160, 203, 'what a beautiful game. i just finished it and i loved it so much', 'It''s a visual novel with really annoying interface standing in the way of the storytelling and decisions. The pixel art is cool, the writing was...fine, I guess? It didn''t grab me and before long I just didn''t care enough to carry on. At the end of the first chapter, I was given a list of the "decisions" I had made and what % of others did the same, ala Telltale games. But I never really felt like I knew when I was making a decision, what the context of the decisions was, nor the probable conseq', 'Very Positive', 94.09, 7.18, 6.97);
INSERT INTO reviews VALUES (6187, 437220, 8095, 'I am still waiting for this game to make a return. It was simple, but still complex enough to find joy. They just had to do small tweaks and let the Game run itself. I cant still fathom how they threw this perfectly working game out of the window for a quick shitty looking china ass cash grab and died instantly.  Every few months I am still writing them an email to re-release the normal game and have people play it. AND I WILL NEVER STOP', 'great game ruined by a shit dev', 'Mixed', 57.64, 28.33, 43.30);
INSERT INTO reviews VALUES (6188, 437250, 339, 'If you like Sunless Sea or Sunless Skies you will like this game. Its a dark -literally dark- fantasy game where you explore a parallel dimension and its strange cities in your centipede-like vehicle. Interesting characters abd sites, and lots of good writing. Lots to read! - I have experienced a couple of crashes while playing it, but still good value 8 out of 10.', 'Sunless Sea was interesting, so I decided to try this game, but I don''t like it. Perhaps I should give it more time, but the first impression was negative.', 'Very Positive', 83.48, 26.37, 3.58);
INSERT INTO reviews VALUES (6192, 437420, 132, 'Decent puzzles, no feeling impossible or tedious (like the sort the 3 rings of beads ones), and decent graphics. Not a long game but a decent value.', 'Thing you should know about me. If I''m skipping every other puzzle in the game it doesn''t mean the puzzles are hard. It means they are poorly designed and confusing. And also I hate the game and I want it to be over.\r\n\r\nThe first game had great puzzles, they were challenging, but were fair and made sense. But this game has the most randomly designed puzzles that directions make no sense. Like for instance you are suppose to turn pipe keys in a certain way in one puzzle, but here''s the thing...th', 'Very Positive', 86.36, 4.53, 8.83);
INSERT INTO reviews VALUES (6197, 437570, 461, 'Super cool platformer. I love the style and it is in the smaller pool of Rogue-likes that i don''t get frustrated by.', 'Not even kidding, the DLC is so bad it ruins the whole game - I want to like this game but it''s just not even fun with the DLC. I played this on switch years ago before the DLC and it was good. \n\nTrash , refund immediately or suffer', 'Very Positive', 83.73, 2.03, 2.95);
INSERT INTO reviews VALUES (6199, 437630, 534, 'If you told me that Elon Musk developed this game, I would believe it. This game seems to give a glimpse into our future. This is a sci-fi game, but a lot about it is sci-fact and will happen, even faster than most people realize. \r\n\r\nAlthough I am very much against all this transhumanism, robots and A.I. stuff, this game is very well put together. The story line, the visuals, the overal experience. It also makes you think deeper about the consequences the rapid developing of technology such as ', 'doesn''t hook me as much as i would like, also walk speed feels a little too slow and feels kind of clunky', 'Mostly Positive', 76.03, 19.72, 1.63);
INSERT INTO reviews VALUES (6208, 437920, 2262, 'The singleplayer is fun but gets stale quick. Multiplayer is where the game shines but playerbase is mostly dead so unless you can get a friend to play with you, you won''t be able to enjoy the most fun part of the game. So I only recommend to get the game if you have someone to play with', 'Great concept and well made game but this game is toxic for your mental health.\n\nI have faced my subconsciousness and inner me more than I have ever done in meditation. I''ve had more stress over playing this for an hour than having to study 5 final exams that I''ve only attended few days. This game creates more rage and anger than any other games I''ve played. My heart rate is higher than when I played Doom in hardcore mode. I''ve wasted 2.6 hours of Christmas just because of this. This game is not', 'Very Positive', 89.43, 17.78, 4.62);
INSERT INTO reviews VALUES (6212, 438030, 117, '1. buy game for 16 cents\n2. sell cards for 18 cents\n3. ???\n\nI know, I''m a true entrepreneur\n10/10 would profit again\n', 'Platform shooter with local multiplayer. Retro early 90s inspired graphics that are nonetheless mediocre, no story and gameplay is bland and quickly becomes repetitive and boring. \n\nDoes not help the music is irritating and does not fit the retro artwork.\n\nStill manages to be too expensive for what it offers. Get it on a sale. 3/10', 'Mostly Negative', 35.90, 4.53, 1.42);
INSERT INTO reviews VALUES (6213, 438080, 142, 'My brain sometimes stucked looking at the waves.    7/10\n\n\n                                                                                 -S0YxSauCe', 'This game would be a good one if it speed up then slow down then repeat that process by the time you reach level 2 you end up moving so fast. This game would be great if the speed stopped accelerating then decelerating. And had max cap of 75% of original speed that gradually increases to it but this game says f u c k that lets just start at score 1k speed...\r\n\r\nSuspected the game had speed tied to physics but does not seem like it tried 58 fps cap no real difference... I would highly recommend n', 'Mostly Positive', 78.87, 10.23, 19.98);
INSERT INTO reviews VALUES (6215, 438100, 110, 'why be with your waifu when you can BE YOUR WAIFU ????', 'developers ban normal users for having fun, while their friends get to virtually molest and curse at you while being on a whitelist that prevents you from blocking them...\n\nsteer clear of this, alternatives like altspacevr exist and are much better', 'Very Positive', 83.64, 40.38, 0.52);
INSERT INTO reviews VALUES (6218, 438130, 172, 'My favourite visual novel of all time, I had to buy it again on steam. \n\nI love that instead of making decisions, you rank the characters by how important you view them, which then changes how your character acts.\n\nThe story is amazing, all the characters are really interesting to learn about, and in the endings you either learn more info about the story, or get more depth of the characters, so all the endings are worth getting. \n\nits pretty long, probably at least 60 +hours', 'Root A is very nice. It''s a story about the rescue team doing their best to save the victims of a fire in a situation with a lot of mysteries. Everything goes downhill in Root B onwards though. So much filler, annoying middle schooler protags being brats and their reckless actions being portrayed as being justified, and the actual good guys who brought the crimes of the real criminals LABO''s crimes to light being punished for it anyways in the true ending. It''s a big boring waste of time. The st', 'Very Positive', 90.12, 0.27, 45.93);
INSERT INTO reviews VALUES (6219, 438140, 124, 'The UI looks like it was created for Windows XP (or for mobile app), the AI speed runs every single play even on the slowest setting, the logs to figure out wtf just happened to you is god awful and yet.... Why am I so addicted to playing this insanely fun (stupid) game?! \r\n10/10 and now I''m going to buy the game cards IRL....', 'Let me start by saying that I love the physical Star Realms game. Yet, I cannot remember the last time that I played a PC game that left such a terrible impression within the first hour or two. It''s a usability nightmare. The interface seems almost intentionally designed to frustrate and be an obsticle to your ability to play the game. The fact that the difference between viewing a card and losing it forever (if it has a scraping ability) is single and double clicks means it''s not a matter of if', 'Very Positive', 85.48, 11.87, 6.13);
INSERT INTO reviews VALUES (6221, 438180, 126, 'Nobody will read my review so I Will FInd 1 Friend For Every Like this gets.\n', 'Not Recommended', 'Mixed', 65.08, 4.03, 3.17);
INSERT INTO reviews VALUES (6227, 438270, 1321, '\r\nGood game for learning japanese. It plays just like your usual RPG except you take notes of characters and words that you learn. You will encounter hiragana, katakana and kanji along the way. Soundtrack is nice and story might grab your attention. Just take your notebook and learn some japanese!\r\n', 'Eh.. It''s a good idea, but the ui is clunky, and it''s a pretty slow way to learn Hiragana. Mnemonics work much better', 'Very Positive', 91.52, 1.28, 1.82);
INSERT INTO reviews VALUES (6234, 438420, 171, 'For all it''s flaws as a game, this was one of the best pieces of fantasy/comedy I''ve ever read. If you like Terry Pratchett''s work you will like this too. Just be patient with the game part of it.', 'funny writing, decent gameplay.  Really sucks that i got about halfway where youre escaping the acumen, shut off the last barrier console to get the scepter and my guy gets stuck.  no response to any input.  ive reloaded a bunch of times but no luck.  im done, what a shame', 'Mixed', 64.91, 15.48, 12.12);
INSERT INTO reviews VALUES (6235, 438430, 127, 'Valentino Rossi The Game marks a significant leap forward for Milestone s.r.l, it has created an excellent MotoGP experience, managing to capture the career of biking legend. This is a must buy for fans of The Doctor, and anyone that likes bikes!\n\nhttps://steamcommunity.com/sharedfiles/filedetails/?id=3329386985', 'buy it for motogp16 not for rossi\nwhy milestone didnt release motogp16 and made another game for rossi?\nthis game ruined my display column🤮', 'Very Positive', 83.46, 7.27, 5.33);
INSERT INTO reviews VALUES (6239, 438480, 637, 'Fun game! Finished it in almost 4h\nNot a single non-rock fan slid into the concerts / 3💀 in all. 🤘🏼', '\r\nMusic is good but gameplay feels kinda flat to me. Only a few towers to choose from, not too much variety in stages get repetitive rather quickly. For tower defense game it''s mediocre.\r\n', 'Very Positive', 82.26, 5.08, 5.20);
INSERT INTO reviews VALUES (6240, 438490, 1745, 'If you have hundreds of hours of podcasts or audiobooks to catch up to, GE1 and 2 are pretty good games.\r\nBoth are pretty decent monster hunter clones, with simplistic combat, but not to the point it becomes braindead.\r\nStory is incredibly anime and dumb to the point it actually becomes so bad it''s good and it still manages to pull off good emotional moment every now and then.\r\nGrinding is quite insane if you plan to 100% it, you are looking at something like 100 hours per game of killing same m', 'It has Denuvo.', 'Very Positive', 85.50, 110.28, 5.48);
INSERT INTO reviews VALUES (6243, 438640, 2004, 'somehow palpatine returned...', 'They are still selling this game at full price, the servers have been taken down and the game crashes on start up. The fucking Gaul!', 'Mostly Positive', 78.09, 4.62, 1.87);
INSERT INTO reviews VALUES (6255, 439190, 1116, 'The writing and characters in this game are great and funny, but there''s only so many times I can be bothered to play through the game to get alternative endings, especially when dialogue can''t be skipped at any point.\n\nI played through it enough times until I stopped having fun. Maybe that''s the best way to enjoy this game, but it''s sad it has to be that way.\n\nI would still, however, recommend it, even if just for a few runs, because the game is still very fun overall.', 'Take your mandatory remaster patches to a separate entry, thanks. Or better yet, to the garbage bin.', 'Very Positive', 85.93, 4.70, 0.12);
INSERT INTO reviews VALUES (6256, 439250, 152, 'I''d say... Good. This is a P&C / RPGMaker game. The graphics are basic. The music is not a big deal. The story is actually an entertaining one.\n\nNo bugs or crashes.\n\nOverall, fun to play. The third chapter of this little space opera, made with little resources but with heart and imagination. Several easy puzzles. It includes cards and achievements. Very casual and long enough for the price. One of the nice, cheap indies out there. Have a go!', 'awful', 'Very Positive', 93.42, 5.83, 9.10);
INSERT INTO reviews VALUES (6259, 439340, 569, 'this game is so fun the first 2 levels are easy then it gets way harder you need to research more recipes and train your staff', 'earlier versions made much more sense and were easier', 'Mixed', 65.20, 14.12, 8.03);
INSERT INTO reviews VALUES (6263, 439490, 523, 'played Scrandle for the first time and got flashbanged by the fact that it was made by this dev. incredible shmup', 'english gamedev hiring japanese voice actors to talk like babies for their english-language game incurs a life sentence in cringe idiot jail. have some self respect', 'Overwhelmingly Positive', 98.66, 4.75, 0.13);
INSERT INTO reviews VALUES (6267, 439700, 291, 'This is NOT the Full game, this is just the Test Server you receive access to for free when you purchase H1Z1 King of the Kill.\n\nThis Test Server is used to test updates before they go live.   \n\nI think it''s great that we get the chance to check out an update before it goes live to see how much they game may change after the update.', 'I WANT H1Z1 JUST SURVIVE BACK BASTARDS !!!!!!!!!!!!!!!!!!!!!!!!!!', 'Mixed', 65.29, 12.63, 0.55);
INSERT INTO reviews VALUES (6281, 440310, 1536, 'game crashed when i tried to make a 4D hypercube in 3D projection on my 2D screen.\n\n10/10 would fold reality again', 'I bought Project Arrhythmia a long time ago, and playing it after a handful of years, the game still feels extremely clunky and unpolished. It''s immensely unsatisfying to play, and I''m not sure why it''s still at this point.\n\nThe gameplay is fine. It pioneers off of the ideas of JSAB, and it does it fine. I''m sure theres a plethora of good stuff to be found in user-generated content, but the issue lies in how the game feels, and if you wanted a summary; it''s not great at all. It barely feels flui', 'Overwhelmingly Positive', 96.94, 2318.65, 1.60);
INSERT INTO reviews VALUES (6284, 440420, 431, 'Reddit got me interested in this game and they said it was one of the spookiest. \r\nMy take: Yes it''s spooky and not annoying jump scares. The story is super interesting so it''s certainly a gem. \r\nLong story short, the protagonist got news from her sister and then she goes to investigate it and then finds out the harsh past behind her mother''s demise. Also finds out she has another family member. A powerful family is involved in the whole ordeal and supernatural witchcraft from the looks of it. Y', 'When I saw that part 3 came out I remembered that I had played the first one and hadn''t liked it for some reason, even though I normally love these types of games. So I decided to replay it to refresh my memory.\n\nBy the end of Chapter 1, I remembered. My main complaint with this game is its logic. Why do I need a rake to go through a small pile of leaves to get an object? Why can''t I just pick up that clump of hair? Nope, gotta find something to put it in first. It really feels like they did it ', 'Very Positive', 91.88, 13.45, 7.65);
INSERT INTO reviews VALUES (6287, 440520, 256, 'Great. Works with G25 steering wheel. Sometimes it can be fiddly to get it to work. But worth it after a good few hours. I wish the developers would make a steam guide on how to setup this.', 'Purchased the software to use my Thrustmaster T300 remotely with an ancient Steam Link. The software does work and the wheel connects and runs just fine, but any steering input immediately renders any game unplayable through intense lag, despite them running well using a steam or xbox controller.\n\nFrom what I''ve gathered through the steam discussion board and the publishers own forum, this issue is known and has basically no fix other than to use a raspberry pi or similar device instead.\n\nWhy th', 'Mixed', 47.66, 0.70, 0.13);
INSERT INTO reviews VALUES (6288, 440540, 1332, 'Super entertaining RPG. The art style is gorgeous, as it is obvious. I felt that the gameplay was really balanced, even in Expert (The difficulty I played in). The only time I had to grind there was a quest to motivate me, so it didn''t feel boring at all. You would have to grind to get to lvl 50 if you want the achievement, but that''s you torturing yourself. The story is serviceable and a good ground for jokes. The humor is a big part of the experience; there aren''t any outstanding ones, though.', 'I don''t dislike this game, but it''s pretty repetitive and the plot isn''t strong enough to support the tedium of the combat. The graphics, which were charming at first, got uglier the longer I played it, too. I estimate I''m about 2/3 of the way through the game right now, and I''ll still finish it, because it''s not insufferable to play. The one praise I can give it is the way you level up your equipment, which is more akin to Secrets of Mana than most RPGs, so instead of buying new gear with diffe', 'Very Positive', 94.89, 37.28, 19.43);
INSERT INTO reviews VALUES (6289, 440550, 157, 'How does this game not get recognition, music is awesome and precise as hell like Bit Trip + Super Meat Boy', 'A new peak for the category of "annoying as fuck to play". Get ready to ruin the shoulder buttons on whatever controller you''re using. Good luck guessing the intended speed of gameplay ''cause tick rate is tied to refresh rate apparently. I wanna be the guy... who never plays this mess.', 'Very Positive', 87.26, 2.77, 1.62);
INSERT INTO reviews VALUES (6290, 440630, 601, 'I purchased this game back in 2018 when I first got my HTC Vive.  The problem is I wanted so many experiences when first jumping into VR, so I bought a bunch of games, but barely finished any.  Fast forward, and I''m now playing on the Valve Index and finally decided to jump back into playing more VR and giving this game a full go.  \n\nAll I can say is wow!  For a game that''s pushing 8+ years old, it is fantastic.  The arcade gun play stays fun and satisfying the entire time.  I love all the diffe', 'Just another tech demo (like most VR games are) made in the early days of VR. Not worth £15. Not worth your time. But, as I said in one of my previous VR game reviews, this isn''t the developer''s fault. Why would a bunch of developers spend thousands of hours and hundreds of thousands of dollars developing AAA-quality games when the VR customer base is so low? On the other hand, I can''t blame the customer base either. Why would someone buy bulky and expensive VR headsets and end up having to put ', 'Very Positive', 85.69, 4.82, 0.15);
INSERT INTO reviews VALUES (6295, 440730, 424, '⠀', '\r\nJust another achievement grabber but this one takes more time than usual.\r\n', 'Mixed', 57.78, 4.47, 1.70);
INSERT INTO reviews VALUES (6298, 440760, 211, 'Cube Destroyer\n\nHas a total of 5 trading cards.\n', '\nThis got to be the most boring shooter I have ever played!\n', 'Mostly Positive', 79.62, 1.35, 3.68);
INSERT INTO reviews VALUES (6303, 440880, 582, '\r\nIf you like 8-bit horror games feel yourself at home cause Count Lucanor deliver everything that make goosebumps on your skin. It might feel like cartoony look is not scary at all but the game makes up for it with the right setting and atmosphere which surely is unique for such title. Exploring abandoned mansion is interesting and plot surely will engage you for some time. But be aware as there''re monsters lurking in the shadows! Recommended for people who like simple yet interesting and somew', 'If the mother took responsibility and beat the crap out of her damn child (jkjk!) none of that would’ve happened. Honestly, I won’t spend any more time on this. It made me fall into my gaming slump era', 'Very Positive', 92.78, 4.38, 0.97);
INSERT INTO reviews VALUES (6304, 440900, 36244, 'I have very mixed feelings on this game, despite its age its worryingly unstable, while its packed with content the implementation is super rickety and the breadcumbs are nonexistent, if it wasnt for fans picking up their slack the game would be borderline unplayable and sometimes its the little things that are most annoying... Like the intro, which is tedious in the extreme when you are watching it for the 40th time because the skip button doesnt work reliably and if your server has mods EVEN I', 'I bought this the to play it single player offline never care for the online side of it. After not playing for some times, today I just realize the game doesn''t allow a single player offline anymore. It is really important for me to play offline since I don''t always have good internet connection and I like to play on the go with my ROG ally. Still love the game, but there is no use if I can''t even play it.', 'Mostly Positive', 79.49, 62.62, 382.10);
INSERT INTO reviews VALUES (6306, 441010, 238, 'This game is exactly what my grandparents thought video games were.', 'unique game but to finish all the achievement really hard and confusing', 'Very Positive', 91.18, 3.20, 5.63);
INSERT INTO reviews VALUES (6307, 441050, 293, 'This is a stupid game that looks like a mobile port, made using ass instead of hands. \r\nIt''s bloody awful, but it''s entertaining, funny and fun. So, why not?\r\nAnd yes, I will HUE you.', '\nIf you wanna get into space Kerbal Space Program is a better option. Game feels clunky with cartoonish visuals. Progression system is slow so you have to grind your way a lot. Play only if you like games like Learn to Fly and similar genre with progression system allowing you to get further and further but still there isn''t much to offer.\n', 'Very Positive', 92.49, 8.35, 5.77);
INSERT INTO reviews VALUES (6311, 441280, 202, 'Feels like a Team Ladybug metroidvania because it basically is one!  Co-developed by "Ladybug" who I''m assuming is a core part of the team, and their games use the same engine this one does.  If you enjoyed Touhou Luna Nights or Record of Lodoss War- Deedlit in Wonder Labyrinth you will definitely enjoy this.\n\nShort and sweet, lots of secrets to find and cool movement.  A sort of weekend metroidvania.\n\nStage 4: Luxor is outright infuriating though and the owls that give you stone are one of the ', 'Up to Stage 5 it is very enjoyable, but Stage 5 ruined it for me because it''s hard to get a read-ahead and there are ALSO collectibles to find, couldn''t get past it. Think DKC Minecart Hell.\n\nAlso worth noting this game is very old, to the point it''s still in 4:3 format.', 'Very Positive', 90.10, 8.47, 2.97);
INSERT INTO reviews VALUES (6313, 441380, 326, 'This is the most unfairly reviewed game I have seen due to it being a sequel.', 'I, whole-heartedly, do NOT recommend buying this version of the game. It''s unoptimized, lacks any sort of graphical or performance settings, and does not support cloud saves. It''s a fantastic game, but this is not a fantastic way to play it.', 'Mixed', 68.71, 5.38, 0.13);
INSERT INTO reviews VALUES (6314, 441440, 104, 'I think it''s pretty clear to say if you liked ASM you''re going to like this too. The pace is a little slower and less action packed but I think that is well chosen path. The game lets you explore the cities and the characters while also making you think and worry about the planning, schedule and the future in the back of your head. There are some continuity errors here and there but considering the amount of paths that can be chosen as well as the choices that is transferred from ASM to the new ', 'This could''ve been a decent game if it wasn''t taken so seriously. The story was trying to be complex and twisty, there was drama and politics that nobody was asking for. I felt like I was wasting time watching a reality show. Every town was essentially the same, and the conversations between characters weren''t interesting. And the devs of the game kept making appearance, talking about their work and how brave and important it is to be an indie developer and surviving on coffee. This game should''', 'Mostly Positive', 73.08, 16.45, 29.35);
INSERT INTO reviews VALUES (6316, 441550, 819, 'if ever there was a game that actually deserved a remake, reboot, or sequel, this is it', 'was a great game. sadly it crashes a lot and with no auto save, you can lose a lot of progress or the whole match. hopefully they can find a fix', 'Very Positive', 89.13, 311.27, 11.80);
INSERT INTO reviews VALUES (6319, 441670, 125, 'jelly killer 2\n', 'This one looks nice but the gameplay ain''t so fun to me. It''s a pixel-art puzzle platformer based on strict action sequences with a tightly cropped screen area, so the player can''t see much - all the difficulties come from these 2 facts, making you to navigate levels with try & fail method, gradually studying its structure. But after you have once passed an area there is just no intrigue left to return.\n\nBesides the objects themselves being presented on screen up close, their hitboxes are extrem', 'Mostly Positive', 75.20, 2.87, 5.52);
INSERT INTO reviews VALUES (6322, 441790, 563, 'Good', 'Was rubbish, is still rubbish\r\n\r\nWas terrible when it was active, is still rubbish, just abandoned. devs like this should be fined for wasting peoples time.', 'Mostly Negative', 32.33, 0.30, 0.32);
INSERT INTO reviews VALUES (6323, 441830, 1068, 'Unfulfilled potential is probably how I''d describe Setsuna, or a beginners JRPG. It''s got all the components to make a good rpg. Decent story, potentially interesting battle mechanics. It just didn''t quite reach the end there. I''m left wondering is that all there is to this game? Perhaps I''m overthinking it.\n\nSetsuna is a good beginner friendly JRPG', 'started playing this years ago and couldn''t work out why i stopped playing. i remembered why after a particularly annoying death and remembering how far back the save point was (overworld saving is a must before EVERY new area). After i worked out a certain combo skill i proceeded to steamroll my way through the rest of the game, spending most of my money on eithers. i kept expecting a sudden twist or the world to suddenly expand beyond the frozen wastes but then boom ''The End''\r\n\r\nI desperately ', 'Mostly Positive', 70.22, 35.88, 34.23);
INSERT INTO reviews VALUES (6325, 441870, 1468, 'https://steamcommunity.com/sharedfiles/filedetails/?id=3289025257\nhttps://steamcommunity.com/sharedfiles/filedetails/?id=3286938819\nhttps://steamcommunity.com/sharedfiles/filedetails/?id=3288122612', 'I bought it on sale for %30 off and still asked for a refund.\nNo sensitivity settings, feels like it was made to be played with a controller but the controls it tells you X are for PlayStation or something,. Not Xbox you know the controller that worls best for PC games.|\nIts also badly optimized for such a small game. Menus will load but not show up causing you to accidentally double click when your trying to quit, of which your 2nd click brought you back into cause it was over the play button, ', 'Mostly Positive', 72.68, 3.63, 0.32);
INSERT INTO reviews VALUES (6327, 442070, 680, 'yall are giving it too much shit for an 8 year old game, get it while its free', 'Don''t get me wrong- I love Drawful and I think Jackbox games are THE best party games available right now. I can not wait until Jackbox Party Pack 3 and I will be buying every game they release day one for the known future.\n\nDrawful 2 is a great game IF you don''t already own the Jackbox Party Pack 1 and aren''t a streamer. This new game is a ton of fun and I will be playing it with my friends constantly in the future. However, I just don''t think it''s worth the $8 if you already have the original ', 'Very Positive', 91.76, 4.37, 6.23);
INSERT INTO reviews VALUES (6328, 442080, 418, 'Amazing Game I give it 9/10\n\nIts Monster Hunter meets Pokemon. Its not what I expected for a Nexon Game. I thought it was gnna be another Asian Grind game but its not. Its pretty fun to level and there is alot of depth to the game. If your looking for a game to hold you over until Eternal Crusade drops or Crowfall then deffenitly play this u will not be disapointed.', 'This game was fun until a few years back they "Reworked" everything and removed everything from my acc cus i was inactive 10/10 scam, stole my money. Give me my items and Lvls back.', 'Mixed', 69.38, 14.23, 55.12);
INSERT INTO reviews VALUES (6329, 442120, 940, 'This is not the newest in the series - "Pinball FX" is newer than "Pinball FX 3" because the world is insane and nothing makes sense.\n\nBut this one is better than the newer one. Much better performance, not-as-bad menus, and the physics feel better.\n\nSame tables anyway, but you have to purchase them separatedly for each version.', 'I would really appreciate more unlockable content that isn''t hidden behind a paywall and with such prices on top of that.\n\nIf my parents never had this game fully unlocked, I would never knew what the majority of the pinball tables be like', 'Very Positive', 92.98, 5.88, 11.30);
INSERT INTO reviews VALUES (6332, 442210, 117, 'You will never get this kind of crazy chase in GTA. Not even close.', 'It was fun for a couple of hours, but even at $6 on sale, there isn''t much game here.  The per dollar game hour isn''t that great.  It is a great idea, good execution, there just isn''t enough here to justify spending more than a few bucks on it.', 'Very Positive', 89.74, 8.37, 4.45);
INSERT INTO reviews VALUES (6337, 442500, 464, 'Age of Gladiators is a management game featuring gladiators. The learning curve is quite steep. Patience and careful management of financial resources are certainly key. There are three important factors: training and building a high-quality staff, event sponsorship, and recruiting new promising gladiators. You need to start very slowly because the management costs are very high. In the early stages, recovery times are long, so it is wise to rotate 3-4 gladiators. In the intermediate stages, spo', 'Entertaining for 20 minutes, after that it is the most boring repetitive game you could imagine.  Sure now and again your elite gladiator will get wrecked by some noob but by then you will have so much gold it won''t matter.\n', 'Mostly Positive', 75.86, 22.18, 49.23);
INSERT INTO reviews VALUES (6342, 442780, 1311, 'Absolutely top shelf game. Soundtrack SLAPS!! IT SLAPS I SAY! Gameplay and controls are tight and responsive, weaponry is varied and punchy, enemy design *chefs kiss* Level design 15/10, replayability is infinite, if you havent played this game you need to rectify that immediatly and bless the Pixel Titans! I would love to see a Strafe 2 or at least some more level enemy add ons.', 'In 2024, this game is currently broken and will crash one hundred percent of the time immediately on launch. I''d say this is a scam game, but at one time years ago the game did work. It''s a shame this has been abandoned and left in this state. Do not buy.', 'Mostly Positive', 74.52, 315.95, 6.08);
INSERT INTO reviews VALUES (6346, 443000, 200, 'I loved the concept why did you guys abandon it? you could have done so damn good. nevertheless its a very fun game and the art design is top notch.\n\n\nI like Spaghetti and Meatbalsl', 'This game is abandonware. They''ve run off with our money. Don''t waste yours.', 'Mixed', 52.00, 11.90, 3.88);
INSERT INTO reviews VALUES (6369, 443810, 2780, 'It might seem like just another simulation or RPG, but deep down, it feels more like a moral test against corruption.', 'I guess this game isn''t for me. Apparantly certain choices lead to certain death, so why give me the choice if I can''t play it the way I choose to? Very demoralizing, and I wish I would have known before I bought it.', 'Mostly Positive', 73.99, 13.73, 6.87);
INSERT INTO reviews VALUES (6372, 443860, 183, 'Great little Arcade Racing game. It''s easy to learn but hard to master. Unfortunately online play is kinda very dead so you will have to find some friends who play if you want to race agains real people, or just friend me ;)', 'ERROR : Unable to init game.\n\nIt worked fine last time I played, now it doesn''t. Why ? Nobody knows, there is no solution to this.', 'Very Positive', 87.98, 168.18, 0.40);
INSERT INTO reviews VALUES (6374, 443970, 127, 'godot unreal i woudl rather go on them but this dont mean inst good it is', 'game run fine on editor but after you compile you get a weird error in some other language and really poor performance running stand alone game.', 'Mixed', 68.50, 2.53, 1.88);
INSERT INTO reviews VALUES (6376, 444000, 118, 'Great soundtrack and love the retro arcade racing game feel.', 'The game is definitely a trip back to the early days of racing games. its fun, but I have trouble recommending it for a few reasons.\n\n1. The time limit. No matter if you pick course or stage, you have a time limit, and sadly theres no option for an endless mode where you can just race at your own pace to try to beat peoples times.\n2. The Spotlights. The night sections of some maps feature street lights, which completely obscure your vision.\n\nUltimately, its a good game, for a good price at 5.99,', 'Very Positive', 92.37, 2.37, 0.10);
INSERT INTO reviews VALUES (6378, 444090, 3300, 'It crashed to desktop every other 2 seconds, but when it is working its somewhat fun with friends.', 'Game devs have built a forced-50% winrate into the matchmaking. Enjoy playing with 59-IQ "teammates"? Then this is the game for you!', 'Mostly Positive', 77.82, 1066.93, 155.82);
INSERT INTO reviews VALUES (6380, 444140, 303, 'The game is cool if you like photography or are a virgin.', 'i love you sonico its a shame youre stuck in this gooner game i wish i could save u', 'Very Positive', 88.78, 7.52, 4.35);
INSERT INTO reviews VALUES (6385, 444200, 220, 'Good action.... they let you play evenly at first, then they stick you with tanks much more powerful than yours. Mostly, you are never the higher level tank vs. the level below you. Also, many players hide till the near end of battle so they have full power from not being hit, then they pop out and finish off half dead enemy tanks for points. Sad.', 'гра топ', 'Mostly Positive', 70.45, 163.52, 0.53);
INSERT INTO reviews VALUES (6387, 444220, 101, 'Asteroid Bounty Hunter\n\nHas a total of 8 trading cards.', 'The game looked very cool. I played for 12 minutes and couldn''t take it anymore. The spelling mistakes and typos are nonstop. The voice acting is unmentionably bad. You have to hear it to really appreciate how bad it is. The whole game feels like the designers didn''t care one bit what they were doing or how it''d feel to its players, and it shows because they didn''t even bother to proofread anything. Even though it was $2.19 on sale, because they can''t be bothered to read their own menus and subt', 'Mixed', 57.43, 0.87, 0.22);
INSERT INTO reviews VALUES (6389, 444260, 126, 'I''ve never seen an animation of a dog exploding so many times over and over again.\nTurns out I am not a good dog.', 'i bought this when i was at an age too young to know what a good game is, and got exactly one achievement in it. i recently decided i wanted to try dedicating more to 100%ing games i bought as a kid, and so i made the regrettable decision to play this instead of something normal like watching antique roadshow or doing meth. i think the other options would have been the more productive ones', 'Mixed', 50.79, 0.40, 2.28);
INSERT INTO reviews VALUES (6393, 444350, 105, 'I like the color blue', 'if(This game == not good){\nSystem.out.println("It sucks");\n}\n\nIt sucks', 'Mostly Negative', 23.81, 1.20, 0.45);
INSERT INTO reviews VALUES (6400, 444490, 172, 'I lost my eyes\n gg 11/11', 'Abandoned, buggy game with no players, broken offline modes and impractical weapon unlocks', 'Mostly Positive', 73.26, 4.55, 1.55);
INSERT INTO reviews VALUES (6406, 444590, 300, 'Loved it. Watch my detailed review here\r\n\r\nhttps://youtu.be/Qd-Ri5nX5dA', 'Mouse not supported... and ofc cant rebind to it...', 'Very Positive', 80.67, 9.07, 0.32);
INSERT INTO reviews VALUES (6409, 444690, 106, '⣿⣿⡻⠿⣳⠸⢿⡇⢇⣿⡧⢹⠿⣿⣿⣿⣿⣾⣿⡇⣿⣿⣿⣿⡿⡐⣯⠁ ⠄⠄\n⠟⣛⣽⡳⠼⠄⠈⣷⡾⣥⣱⠃⠣⣿⣿⣿⣯⣭⠽⡇⣿⣿⣿⣿⣟⢢⠏⠄ ⠄\n⢠⡿⠶⣮⣝⣿⠄⠄⠈⡥⢭⣥⠅⢌⣽⣿⣻⢶⣭⡿⠿⠜⢿⣿⣿⡿⠁⠄⠄\n⠄⣼⣧⠤⢌⣭⡇⠄⠄⠄⠭⠭⠭⠯⠴⣚⣉⣛⡢⠭⠵⢶⣾⣦⡍⠁⠄⠄⠄⠄\n⠄⣿⣷⣯⣭⡷⠄⠄⢀⣀⠩⠍⢉⣛⣛⠫⢏⣈⣭⣥⣶⣶⣦⣭⣛⠄⠄⠄⠄⠄\n⢀⣿⣿⣿⡿⠃⢀⣴⣿⣿⣿⣎⢩⠌⣡⣶⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣆⠄⠄⠄\n⢸⡿⢟⣽⠎⣰⣿⣿⣿⣿⣿⣿⢀⣾⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣦⠄⠄\n⣰⠯⣾⢅⣼⣿⣿⣿⣿⣿⣿⡇⣾⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⡄⠄\n⢰⣄⡉⣼⣿⣿⣿⣿⣿⣿⣿⢸⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣧⠄\n⢯⣌⢹⣿⣿⣿⣿⣿⣿⣿⣿⢸⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⠄\n⢸⣇⣽⣿⣿⣿⣿⣿⣿⣿⣿⠸⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⠄\n⢸⣟⣧⡻⣿⣿⣿⣿⣿⣿⣿⣧⡻⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⠄\n⠈⢹⡧⣿⣸⠿⢿⣿⣿⣿⣿⡿⠗⣈⠻⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⡇⠄\n⠄⠘⢷⡳⣾⣷⣶⣶⣶⣶⣶⣾⣿⣿⢀⣶⣶⣶⣾⣿⣿⣿⣿⣿⣿⣿⣿⣿⠇⠄\n⠄⠄⠈⣵⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⢸⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⠄⠄\n⠄⠄⠄⠸⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⠘⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⠇⠄⠄', 'this game need an optimization! i have a fking 4060 and my game just keep crashing...', 'Mixed', 50.00, 3.93, 0.08);
INSERT INTO reviews VALUES (6411, 444720, 154, 'Lets really look at it...this s a $3 game. So you aren''t getting big name title quality. There are bug...lots of them. Some work against you, but some work in your favor. So it evens out. \n\nHowever for $3 it is not that bad of an experience. It is not too long of a game but its enjoyable enough that you can do another run through it if you like. However it might be dead with the remake of it....and that one is pretty cheap too. So if you want to toss a few dollars at it, there is a lot of enjoya', '\nJust play the new version Inexistence Rebirth.\n', 'Mixed', 55.84, 2.42, 1.57);
INSERT INTO reviews VALUES (6414, 444800, 169, 'i did it!\n\n\ni beat the first level!!!!!!!!!!', 'Navigating the menu was harder than beating any level in this eyesore. NO THING to see here, folks. 3/10', 'Very Positive', 89.94, 0.60, 2.85);
INSERT INTO reviews VALUES (6417, 444880, 113, 'Actually pretty fun if you have a couple friends around. I would say its worth its low price even if its not the best quality. \n\nThis is the only game where I was able to make one of my friends walk out of the room in anger so thank you.', 'No one is playing Multiplayer Online.\nSo if you can play local, then it''ll be good, But if you''re looking to play with strangers, You wont have any luck.', 'Mostly Positive', 73.45, 1.05, 0.22);
INSERT INTO reviews VALUES (6418, 444940, 262, 'Its not addictive, i can''t stop whenever i want to', 'Game crashes when I get a Brainclap so I cannot recommend this buggy mess.', 'Very Positive', 84.73, 942.80, 5.00);
INSERT INTO reviews VALUES (6421, 445020, 184, 'The game is a bit buggy and would have benefited from more patching (and perhaps a bit more time being worked on before it was released in the first place!), but regular patching ended at the end of 2018 so the state of the game is basically what you''re stuck with. Everyone''s experience is slightly different, but I''ve personally experienced crashing (crash to desktop either when loading a mission for the first time, or when loading a turn''s results) roughly once every 3-4 hours on average - than', 'The audacity of selling this for $25...', 'Mixed', 63.04, 44.00, 0.33);
INSERT INTO reviews VALUES (6425, 445110, 300, 'The game is old. Childhood classic.', 'Oh boy where do i begin with this review? I will start by saying that this game is better the the first one, and while that is a pretty low bar to jump, id say tasty planet 2 jumps it by a couple rungs. Will i ever play this game again? No absolutely not, while it is better then the first game, it is pretty much an exact copy of the first game, its just done better here. So lets get into the positives. Number one the story has way more focus in this then the first game, still a low bar because i', 'Very Positive', 89.67, 3.08, 4.85);
INSERT INTO reviews VALUES (6429, 445190, 1851, 'I very much enjoyed this game, but it is worth noting that it won''t be for everyone.  It isn''t flashy, so if you need fancy graphics or get bored easily then it may not be for you.  If you like RPGs that let you immerse yourself in a story and a setting, and especially if you are a fan of the era and history, then this game is definitely for you.  \n\nFrom a mechanics standpoint, the game is somewhat unforgiving.  There are a few combat abilities that are must haves, and if you don''t figure that o', 'There I was, sailing back to my homeland after pillaging the crooked-teeth Brits. Watching the waters in anticipation, I saw the shores of Skerjn on the horizon . . . and was interrupted abruptly by a message letting me know that I lost. In spite of my 72 hour investment, spent marching from one crushing victory to the next, I took one day too long to win the game.\n\nA needless, nonsensical time limit turned what this 8/10 game into a 4/10. Shame.', 'Very Positive', 82.17, 107.70, 71.97);
INSERT INTO reviews VALUES (6431, 445220, 7538, 'I found 2 warring factions and befriended them, then proceeded to make a fortune selling each side nuclear warheads. I am the US Defense Dept. 10/10.', 'Let me make this clear right from the get-go, I love the game’s concept. I’ve been playing for four years minimum and have 4.3k+ hours on it. Got a small armada of ships on the workshop, have had several survival worlds, etc.\n\nThat said, right now I can’t recommend it. The developers have proven completely oblivious to what the game actually needs. They’ve made a series of updates and changes that nobody has asked for, yet at the same time ignore the things that EVERYONE has asked for. Updates h', 'Very Positive', 89.63, 228.38, 4382.20);
INSERT INTO reviews VALUES (6433, 445310, 554, 'Great game, but pretty much unplayable without the unofficial HoMM 7.5 patch. Doesn''t solve all of the problems unfortunately, but it is a much better experience with it. The game reminds me of the great times playing HoMM 3 and 5. Definitely worth picking up during a sale.', 'Ubisoft launcher... Need to be online to play a single player game... Need I say more?', 'Mixed', 61.91, 131.92, 5.25);
INSERT INTO reviews VALUES (6442, 445800, 121, 'One of the first few visual novel I''ve played and I don''t regret it. I''ve learned alot about Japanese in this game more than Duolingo, Miyuki best girl! (´⊙ω⊙'')！', 'Overall this is a good game, it''s cute and all, there are a lot of typos in this game in both English and Japanese. Now that''s not my point, the thing is that this game is still on beta version and is incomplete, which explains some errors in this game, you just progress through half of the game and the game suddenly ends AND this game is discontinued, there are going to be no more updates to this game so reconsider your decision if you want to buy it, at the very least, wait for a sale', 'Very Positive', 81.82, 9.78, 48.35);
INSERT INTO reviews VALUES (6446, 445980, 7063, 'could you guys make online multiplayer a thing? or at least open some kinda workshop so someone else can do it? i love the couch co-op but i think adding an online option would be awesome. Love the game I''ve played it for hours but please make an online option.', 'The game can be fun for few hours but i can''t get over the fact there is no i-frame and how frustrating and painfully annoying the stuntlock can be when you take damage. \n\nEven though there is a great variety of spell, i felt obligated to min max and stop exploring new builds idea because the game feels so punishing.  I played other hard roguelikes/roguelites before and I know these type of games requires training to get a win, but I felt overwhelmed with the crazy difficulty curve of this one. ', 'Very Positive', 91.34, 38.43, 12.25);
INSERT INTO reviews VALUES (6447, 446000, 167, 'In Conclusion,\n\nStellar Monarch delivers on its promise; a game free of micromanagement. Even the element I managed, the movement of fleets, can be automated. But what does this leave the player? With no action to take, and a database of unnecessary information to absorb, the emperor occupies their time with chess, or a similarly trivial distraction. The only necessary duties include granting audiences, designing fleet compositions, planning wars, signing truces, while overseeing the research, f', 'Although somewhat overpriced for what it does, Stellar Monarch is a nice little take on the space 4x / grand strategy genre that definetely feels different from more conventional games like Endless Space or even Stellaris. The micromanagement is definetely toned down and you feel properly imperial, but the game does not do enough with its audience and storytelling system. Seeing as it doesn''t, playing from the earliest possible start date is too much of a grind. The genre on a whole could learn ', 'Mostly Positive', 76.05, 22.37, 18.73);
INSERT INTO reviews VALUES (6449, 446020, 3841, 'I know that publisher took away the game from devs and killed it, but I still want to leave a review, because devs did a great job. It''s unfortunate it''s not finished, but it''s still playable and addictive.', 'I bought Jalopy to help support the developers, even though I had pirated it back in its early days. I was really looking forward to a fun road trip, but the game turned out to be more of a frustrating mess. In my play, I found myself clipping right through the floor next to a building, getting stuck on a route because one flipped car blocked the way, and jogging into another car made a huge crashing noise, yet nothing happened to the car at all.\n\nThe game has not seen an update since September ', 'Mostly Positive', 76.70, 7.28, 1.50);
INSERT INTO reviews VALUES (6455, 446120, 255, 'Meh. It’s worth a shot on a good sale. Gameplay is mid tiar fun, but story and progression is kinda meh. The visuals are interesting, and I feel like the game has a ton of potential, but I think the devs are done with it.\nRecommend but again only on a good sale.', '5 minutes, that''s a record. \n\nEverything just feels... wrong. The controls are floaty, and the rooms are too small for the doom-like movement speed. The UI''s pixel size seems all over the place, and is most definitely not pixel perfect. Clicking the mouse button to start the game also shoots your gun, before you even see it. There''s this... noisiness to the way it looks, but it also feels barebones.\n\nThe fact that the mainstream gaming media reviewed this game positively is baffling to me. I''m m', 'Mostly Positive', 73.73, 6.07, 0.08);
INSERT INTO reviews VALUES (6458, 446310, 144, 'Play this game, then play Guns and Lords of Infinity. This series should be regarded in the same leagues as the best works of Tolkien and JRR Martin.', 'Don''t let the meme reviews or comparisons to Suzerain fool you into thinking this is something that it''s not. It''s a text-based rpg with fading tolerance for subpar decisions that are chosen as the story progresses. \r\n\r\nUnfortunately, unless you pick well, the reward for failures doesn''t seem to be many insights other than making you feel stink for not selecting an optimal character, or knowing what the decisions will actually entail, should you not actually mind-read where the story is headed.\r', 'Very Positive', 92.36, 30.03, 4.90);
INSERT INTO reviews VALUES (6459, 446330, 110, 'Genuinely entertaining experience enough to be replayed multiple times to get the best outcome!', 'I did not enjoy this one as much as the first game in this series. \r\n\r\nThis is probably because unless you absolutely know what you''re doing and have specced into the right stats, you will run into a dead run like I did and be forced to restart the game and make different choices in order to actually progress. It would have been nice to have known that ahead of time, but I suppose that would have spoiled events and this is somewhat vaguely hinted at throughout the first game.\r\n\r\nAs for this game', 'Overwhelmingly Positive', 95.45, 5.80, 5.23);
INSERT INTO reviews VALUES (6460, 446380, 167, '3.5/5\nIpeooped, youpeooped, we all peooped.', 'forbanna ass', 'Very Positive', 84.43, 2.02, 0.17);
INSERT INTO reviews VALUES (6461, 446390, 363, 'I spent few hours to look at the characters and suddenly realized I hadn''t played at all', 'This is a button-masher that is 8 years old, but it is still being sold for $40. Furthermore, the combat is rather shallow and the game devs spent more time on fan service than on actual gameplay. Finally, the game crashed so many times.\r\n\r\nMaybe it would be okay if you get it on sale at 80% off, or more, but certainly don’t bother at full price.', 'Mostly Positive', 76.58, 6.78, 25.22);
INSERT INTO reviews VALUES (6469, 446540, 101, 'SO EXCITED ABOUT THIS!!! I absolutely LOVE Smash Up. So happy I can play now whenever I want. I can''t wait for them to add more factions! Really solid all around too. Good ui and no problems what so ever. 100% worth the low price tag!', 'While I enjoy the game itself, I find the interface and layout of the game in video game form to be very poor and confusing.  Sometimes it is unclear what the game is wanting you to select or do when a card power activates.  This is a game that is best left to the actual tabletop, not the computer screen.', 'Mixed', 58.42, 19.83, 7.13);
INSERT INTO reviews VALUES (6473, 446620, 190, '', 'I found it generic and boring, every wave starts the same. Besides new weapons(that can''t be unlocked between waves) and more cardboards nothing really changes. No real progression, no story at all, just shooting a lot of cardboards and trowing the same stuff at the beginning of each wave. Not worth the price yet.', 'Very Positive', 92.63, 7.67, 0.67);
INSERT INTO reviews VALUES (6474, 446640, 165, 'Now I have seen the entire saga since I played the reunion (last) game first.  i would recommend this game to anyone who enjoys puzzles.', 'awful', 'Very Positive', 94.55, 10.98, 1.00);
INSERT INTO reviews VALUES (6478, 446800, 4127, 'how to play this game\r\nstep 1: start a free game\r\nstep 2: go bankrupt\r\nstep 3: repeat', 'Transport Fever is like if OpenTTD was 3D and otherwise worse in every way.\n\nThe game is slow, signals are functionally inadequate, elevation and curvature makes everything difficult with train tracks, supply lines are inconsistent, cargo management is a pain, and overall this game just makes me wish I was playing OpenTTD instead.  Don''t get it.', 'Very Positive', 80.69, 163.37, 22.97);
INSERT INTO reviews VALUES (6479, 446810, 402, 'SNES Zelda core with really cool visuals and Pixel art. I got it real cheap', 'genuinely just play Link to the Past, this game has nothing original going for it outside the cute but highly underutilized framing device.', 'Very Positive', 84.33, 2.22, 6.72);
INSERT INTO reviews VALUES (6481, 446840, 171, 'Played this on election night (USA). I was more concerned with getting platinum medals in the time attack mode than about the actual election results, and I don’t think that mindset should be frowned upon.', 'This game is fun casually but that is as far as it gets. If you intend to play this to get 100% achievements I would highly recommend against it. \n\nThe controls can''t be changed unless you use Steam''s input remapping, which is the only reason I still have not dropped this game. The game is buggy and glitchy, the aiming and controls can be inconsistent with input lag that happens often enough to ruin runs. I can''t count the number of times I lost a run due to these inconsistencies, on top of the ', 'Very Positive', 91.81, 2.32, 104.13);
INSERT INTO reviews VALUES (6488, 447020, 6853, 'omfg i love tracktor , trakcotroototr i so nice , tractor is life and i love the tractor , the tractor also loves me ? i love field , field nice , tractor niceeee  very good game i plant 420 blaze it kush on field 42 with hire worker " john" . he is worknig for an slave price which is nice for me as i have over 900K in debt over some tracors that is now laying in the water just rotting away . i will rate this game very FUUUUNNNNy and you will learn alot terrorism playing this game , 2/10', 'You may like this game like I did, then your ten hours in, get the achievement and your game deletes itself and is lost forever.', 'Very Positive', 92.81, 375.42, 35.95);
INSERT INTO reviews VALUES (6490, 447120, 658, 'I like walking\nI like reading \nJob done ✔️  \n\nThis game may not be to everyone''s taste but I find it to be an enjoyable one to kick back and chill with..\nThe characters are engaging and the collective stories Interesting. \nThe player''s choices during the discovery of particular stories can change the theme of the story from humorous to scary etc and the growing of stories due to their retelling means they have a bigger impact upon the disposition of the listener. The walking can indeed be tediou', 'Interesting premise, fantastic music, narration and art style. It ultimately fails to muster an interesting gameplay loop or put together ideas in a cohesive form. Not to even mention the terribly slow pace.', 'Mostly Positive', 75.23, 13.50, 13.53);
INSERT INTO reviews VALUES (6491, 447150, 2191, 'APE OUT is a percussion jazz album hidden inside a video game where the gameplay itself is the composition. The choice of instrument (percussion) drives home the ham-fisted gameplay. This purposeful use of basically exclusively percussion audibly entrances us to what our gorilla friend is doing and is likely feeling. Even the enemy variety and different levels provide different soundscapes as you smash them into the terrain. Visually, the game skips out on photorealistic fidelity for minimalism.', 'Just watch the first trailer and you will have experienced 90% of what the game has to offer.', 'Very Positive', 94.61, 12.17, 5.97);
INSERT INTO reviews VALUES (6493, 447190, 133, 'I like this game a lot so far. I adore Soichiro and I think his path was very fun to play through. I think this game is perfectly paced. The only issue is kinda rough translation in some parts, but it''s overall very good.', 'I really wanted to like this VN, but goodness gracious is the writing hot garbage. TFW you buy a game specifically for the older cast but they all act like teenagers anyway... Also the relationships are so rushed, it''s hard to really give a shit about the romance or characters involved. And since there''s really no plot aside for the romance, it becomes hard to stay engaged...\n\nStay strong ojicons, we will get a decent game eventually :''))', 'Very Positive', 81.20, 14.85, 6.38);
INSERT INTO reviews VALUES (6494, 447200, 104, 'I love them all dearly', 'The game keeps freezing, especially during choices, and the menu is useless during gameplay. My PC meets all the requirements, but this game is virtually unplayable. It''s too bad because the story seemed interesting.', 'Very Positive', 84.62, 13.52, 2.13);
INSERT INTO reviews VALUES (6500, 447530, 11453, 'I replay this game every year around Christmas. Just feels right! The music is incredible, the art is incredible, the story is incredible, and the game mechanism is incredible! I sometimes get really bored with Visual Novels, but having to make drinks and having interactions possibly being affected because of that really helps keep me engaged. Plus, the plot gives a comfy vibe and really sucks me in every time I play. Love this game so much!', 'The artwork is gorgeous and the premise is compelling so I really want to like this game but unfortunately I just don''t think the writing is very good. It''s filled with dated mid-2010s meme humour and uncomfortable rape jokes. Most of the characters feel very underwritten as they''re just a string of quirky, quotable moments loosely strung together.', 'Overwhelmingly Positive', 97.01, 9.48, 1.47);
INSERT INTO reviews VALUES (6505, 447780, 213, 'not lostwinds 3 but its finally free from wiiware', 'Maybe if I had played this game when it was released it would have been better, but by todays standard I found this game to be quite bland and not very exciting.', 'Very Positive', 84.04, 1.43, 1.75);
INSERT INTO reviews VALUES (6507, 447820, 9488, 'This game needs a revive. a #2\n\nVote up if you played during peaks of 2016-17', 'was one of the best casual shooters ever made (insurgency was as well) until NWI sold out to corporate publishers and made the tacky bloated garbage that is insurgency sandstorm and completely abandoned day of infamy', 'Very Positive', 85.46, 749.02, 191.03);
INSERT INTO reviews VALUES (6510, 447890, 210, 'fat mew', 'A frustrating physics puzzler with imprecise mechanics and trial-and-error levels.', 'Mostly Positive', 73.33, 5.22, 2.23);
INSERT INTO reviews VALUES (6523, 448070, 114, 'https://youtube.com/watch?v=Ow4S5jetaDY&pp=ygUSRHJpbGwgd2hhdCB5b3UgYXJl', '\nDANGER. AVOID.\n', 'Mixed', 49.12, 3.02, 4.15);
INSERT INTO reviews VALUES (6524, 448080, 224, 'LIE OR DIE', 'I loved playing Fibbage in the original Jack Box Party Pack with my friends, so I bought this so we could play more of it.  Turns out, it''s mostly the same exact questions/prompts as the version in the Party Pack.  Complete waste of money.', 'Overwhelmingly Positive', 95.54, 78.02, 0.30);
INSERT INTO reviews VALUES (6532, 448240, 307, 'i love this game because you can combine literally anything into one new species, plus you can combine hybrids with hybrids to make monstrosities', 'This game is an overall ok experience. The fusing mechanic is good, but the rest is lame and repetitive.', 'Mixed', 54.07, 16.88, 51.38);
INSERT INTO reviews VALUES (6533, 448280, 2892, 'Horror games are becoming way too scary', 'i got fired', 'Very Positive', 91.39, 1.62, 2.52);
INSERT INTO reviews VALUES (6534, 448290, 271, 'This game is very good and has great writing. \nAlthough some of the levels were a bit bullshit to beat i don''t know I''m just bad at this game or something else.', '\n-Story is not that great. I found it boring. The good ending is not worth the replay.\n-Control is sluggish and grenade jumping is not fun. Joystick is not precise enough for certain areas.\n-Too simple for my taste.\n-Witty humour falls short most of the time. Hero has no depth.\n-It''s alright but overall there are several better games to play.', 'Very Positive', 83.76, 13.40, 14.88);
INSERT INTO reviews VALUES (6537, 448320, 222, 'GIBZ is an action-packed and chaotic 2D shooter that delivers a thrilling and fast-paced experience. With its retro-inspired pixel art style, over-the-top violence, and addictive gameplay, the game offers an adrenaline-fueled adventure for players.', 'Pretty fun but very simple\nAnd is slightly overpriced imo\nIf you have someone to play with, i recommend\nIf you don''t, i don''t think you should look for someone\n', 'Mostly Positive', 77.03, 38.25, 14.23);
INSERT INTO reviews VALUES (6538, 448370, 821, 'Besides Medal of Honor (2010) and Warfighter it''s one of the few games that actually has the balls to feature Muslim terrorists as an enemy faction', 'Stationary machinegun shooter with very repetitive and bland gameplay. Even the sound from the machinegun itself is bland. There''s also only 4 maps! You must complete map #1 to unlock map #2, etc. How do you complete a map? By killing x nr. of terrorists and destroying x nr. of vehicles. The maps are just a endless wave of enemies and you quickly get tired of the whole thing.\n\nThe gameplay cycle is short and simple; Shoot, kill, gain XP to unlock skills, die, retry map. Sounds fun? There''s no re', 'Very Positive', 92.08, 9.98, 3.18);
INSERT INTO reviews VALUES (6541, 448400, 138, 'i do like these games but for some reason i am not allowed to play two of the games in this set, if someone should know what i should do please tell me thank you need to fix the Mexican Holiday it crashes', 'Wanted some cozy game play, but technical glitches and game crashes make it unplayable. I''m getting the feeling this was an old game from prior platforms, and it was not optimized when moved to the Steam platform.', 'Mostly Positive', 76.81, 154.90, 11.83);
INSERT INTO reviews VALUES (6546, 448510, 4444, 'It is fun game, I enjoyed playing with my wife. But probably would be more fun with 4 people, so we had to have two children. Unfortunately they are not very good in the game, and have proven to be quite a lot of effort to raise.', 'Only way to play "True" Multiplayer is through remote play, not able to play with two people owning a copy, in different households. Hardly Shared co-op without great wifi or being in the same building, even then it varies.', 'Very Positive', 92.26, 26.00, 0.52);
INSERT INTO reviews VALUES (6552, 448580, 213, 'Love the supernatural events. Cheesy, but never gets old. Great arcade game play if you need to pass some time.', 'So I got this game for really cheap as it was on sale, and still it wasn''t worth it.\n\nThe horror boiled down to spooky things happening around you while you''re driving with little rhyme or reason or a garbled voice telling you how you will fail. I suppose if you''re an easily scared streamer or youtuber the random horror moments and frustration will make for good content.\n\nThe gameplay is just you driving 30mph (you can drive faster but it will just get you killed) while avoiding random obstacles', 'Very Positive', 85.45, 1.88, 1.28);
INSERT INTO reviews VALUES (6564, 448780, 332, 'Cheap and good VN game.', 'Mediocre story that was translated sloppy which is pseudo-philosophical and lacking in depth. Also, not much love for characters by the writer. The visuals also mediocre. I do not regret playing to the end it but I would not recommend it.', 'Mostly Positive', 75.60, 1.93, 6.07);
INSERT INTO reviews VALUES (6571, 448850, 1310, 'I was in high school when Descent came out.  As amazing as games like Doom were, Descent and Descent 2 were just absolutely mind blowing.  The moment to moment gameplay, the graphics, the sound - it just made for a gaming experience i couldn''t get anywhere else.\r\n\r\nThis game is basically how i remember Descent.  If you look at the graphics of that 1995 game now, it looks blocky and super low resolution.  But of course, i don''t remember it that way!  Overload looks great, sounds great, and plays ', 'Really cool game\nDoes not run anywhere close to well on a 4090 however - and visuals are not that great for such a horrific fps (VR)\nMotion controls are not supported\nBut really thumbs down for perf - I just cant play this on a 4090 so.. (in VR)', 'Very Positive', 94.20, 64.97, 0.13);
INSERT INTO reviews VALUES (6594, 449210, 286, 'A cool fighting game of cops & robbers where half the characters have a throw option, while the others can handcuff opponents to limit their movement and attacks. Doing this right at the end of the match scores an arrest, and it''s fun to go for a complete set in a run through story mode. \n\nI found myself preferring the side of the law, for this handcuff mechanic. As along with the ranged attacks, it adds a little more variety to the move sets. Which are otherwise likely a bit limited for serious', 'terrible', 'Very Positive', 88.81, 5.18, 1.95);
INSERT INTO reviews VALUES (6597, 449250, 218, 'A very cute and sweet twist on the classic story A Little Princess! As someone familiar with the novel, I really enjoyed it. I loved the sapphic elements and how cutely and innocently they were done in a way that perfectly fit the story. I will say that once you''ve explored every character''s storyline, there''s really nothing else you can do in the game, so you''ll reach a point fairly quickly where there''s just no more to play. However, I still think it''s worth it because this really is so wholes', 'I bought this game because I love Long Live the Queen. However this one was a massive disappointment after having played Long Live the Queen. Maybe I didn''t realize that this is like a choose your own adventure book and all you really do is read and press the spacebar. You choose who you want to end up with and then read the story written about how you end up together. I personally need more involvement in the result of a game. I need a chance to fail or for something bad to happen because my st', 'Very Positive', 94.04, 7.45, 6.38);
INSERT INTO reviews VALUES (6598, 449300, 236, '⠀', 'The game has a terrible economic component, movement is very poorly implemented, the game interface is very unintuitive, and on top of that, the sound accompaniment is dull. Playing this was painful for me.', 'Mixed', 55.08, 2.90, 10.83);
INSERT INTO reviews VALUES (6610, 449530, 120, 'Honestly, it surprised me. \nThis game I got on sale a while back started playing it thought it was too difficult (Entirely skill issue there tbh). Its fun its got several different story options, I will say the translation work for someone that isn''t a naive speaker is really impressive. The 6th level early on is difficult even being linked to the "Hawkeye" achievement. It was a fun shorter experience.\nThough the learning curb was steep for me. (I am not very good at video games) it was applicab', 'So. I bought and began playing this game.  At first, the english translation of the text seemed quirky.   When I spent some time with "Grand Pigeon''s Duty" it was readily apparent what I had thought was "quirkyness" was actually a tenuous grasp of the english language.  The poor job translating this game from its original Russian almost made this game not fun to play.  I wouldn''t gripe so much about a game that only costs ninety-eight cents if the aspect of the game that is broken wasn''t so inte', 'Mixed', 66.67, 3.48, 0.35);
INSERT INTO reviews VALUES (6611, 449540, 1865, 'This Game cured my sisters uncle dad step brothers moms grandmas ex husbands step daughters cats moms owner sister of 4 years on cancer. 10/10 will play again', 'my girlfreind hates me because i played 16 inintuerupped hours of this game and neglected my sons and daughters', 'Very Positive', 90.40, 0.52, 0.23);
INSERT INTO reviews VALUES (6612, 449550, 288, 'Played it on my dad''s laptop with 20GB of space before i even learned how to count my fingers', 'nice relaxing game. the only thing i think might be hard about this game is the fact that we you die you have to restart from the first wave I''m referring to chicken Invaders 2 not the second episode.\n\nHowever, There''s a DLC called christmas this is total blasphemy. there''s no God except Allah\n\nthere is no sound basis for Christmas, nor did Jesus (peace be upon him) or his true followers celebrate Christmas or ask anyone to celebrate Christmas, nor was there any record of anyone calling themselv', 'Overwhelmingly Positive', 97.57, 1.10, 1.53);
INSERT INTO reviews VALUES (6614, 449610, 834, 'Delightful! Solid! I can''t say I felt too challenged but it was adorable and varied and it had a lion man.', 'It''s an interesting game with some nice character change mechanics, giving you skills to unlock as you progress. The gameplay is fun and mostly well designed. What drives me crazy, are the random troll placement of some of the enemies and death pits, that just make you want to tear your hair out. Several times, you get to the end of a particularly tough section, fighting your way there, and they''ve hidden an enemy off screen that swings into you killing you just before you get to a save room. I ', 'Very Positive', 87.29, 14.20, 16.27);
INSERT INTO reviews VALUES (6616, 449680, 211, 'great gaming with vodka.', 'I would not recommend this game for now. It has very janky hitboxes and bad coordination especially on the levels w/ dark bg. The color of enemies blends with background and fake (background) enemies making it very easy to slam into a plane right before completing the sector.\r\n\r\nThe achievements are funny, tho', 'Very Positive', 80.57, 6603.37, 0.58);
INSERT INTO reviews VALUES (6619, 449710, 363, 'Can''t believe it got a massive update after 8 years.\nI love playing this game, it''s good stress relief surprisingly.\n\nDefinitely worth buying.', 'I really like this game. I first got it on my cromebook and fell in love with it because of its challenge, artstyle, and how fluid everything felt. I eventually purchased the full package of the game after having it for around a year and although it took a while, I had a blast beating the game. So if thats all true, why am I not recomending it? Well, I accdentially spiderwebbed my chromebooks screen and when I went to get it fixed I was told that a new screen would be about as much as a new comp', 'Very Positive', 80.99, 25.12, 2.27);
INSERT INTO reviews VALUES (6620, 449730, 152, 'Ahnayro: The Dream World\n\nHas a total of 5 trading cards.', 'frustratingly difficult puzzles aside, the game just *ends*. Like, there''s no satisfaction, no real "aha!" moment. It''s just a series of puzzles and then an abrupt stop. Ultimately I feel like I just spent hours giving myself a headache for no reason.\n\nI liked the puzzles, and the delivery, but aside from that, it''s a mildly interesting story very poorly told.', 'Very Positive', 88.82, 1.45, 16.32);
INSERT INTO reviews VALUES (6626, 449960, 3884, 'Surprisingly nice, charming and quite easy to play hack and slay with good controller support and a rewarding and motivating card system. The graphic is unique, might be not everyones cup of tea but i like it a lot and it let me come back again and again. You can choose your own gameplay time, 8 min or 16 min or you want 46 min? A great feature. Overall a relaxing experience with just the right difficulty to keep you going!  \n\nHigh five Thing Trunk for this awesome experience!\n\n Follow our AWG C', 'Maybe I played this game wrong, but I managed to complete the campaign with nothing other than a single hero power. I just hammered one spell over and over for 11 hours and that was it. I guess I''d have to play over and over and over to see what else the game might have to offer, but one play-through felt like enough.', 'Very Positive', 90.24, 7.07, 11.37);
INSERT INTO reviews VALUES (6633, 450140, 111, 'Played it for several hundred hours in 2004. Once you get the hang of it, it''s really good.\n\nIt''s always annoying when enemy spies want to murder your king or morale drops and all the units become renegades.\n\nThe special attacks of the individual units and the specific gods of the respective races are very well implemented.', 'You can''t just have my Normans be speaking French like that.', 'Overwhelmingly Positive', 96.40, 5.33, 0.32);
INSERT INTO reviews VALUES (6641, 450390, 220, 'What a nice, fun way to introduce VR. Works perfectly on my Quest 3, which you can get for about 380 dollars used as I did. You have to check out Half Life Alyx after you play this.', '7/21/2024\r\n\r\nThis looks like it would be a fun game... if I could play it.  It doesn''t work without VR at all, even though there''s instructions saying that the left mouse button can be used for standard interactions.  Tried every level in the game and none of them have activities that can be done without a VR setup.  Guess I''ll have to revisit when I get a VR setup... if I ever do.', 'Very Positive', 92.27, 0.85, 0.27);
INSERT INTO reviews VALUES (6642, 450440, 155, 'Very creepy, much castle, and has Chica from FNAF in it.', 'If you like to walk around giant mazes at a snail''s pace, this is the game for you.', 'Very Positive', 90.97, 6.10, 3.88);
INSERT INTO reviews VALUES (6643, 450500, 320, 'This is a game where you play as sea creatures that shoot lasers and stuff from their very bodies.\r\nYou can also be vehicles too.\r\n\r\nThe game has a big map and has fun music and co op multiplayer.\r\n\r\nThis is not active nowadays though.', 'It is one of the most non-serious attempts at creating a functioning product with sophomoric elements. Progression is slow, with no real objectives but battling enemies and acquiring their DNA, and the environment is without rhyme or rhythm. What players will find themselves having to fight the most is the camera and controls; Ace of Seafood can only be described as a rigid joke that is way past its expiration date.', 'Very Positive', 93.12, 9.87, 4.60);
INSERT INTO reviews VALUES (6644, 450540, 18428, 'Im an AMERICAN that means getting up at 4am in the morning, drinking 5 cups of black rifle coffee and training for 10 hours like Jocko Willink. Im armed to the teeth with pistols, rifles and tacticool gear that my wife thinks is useless but I tell her its what our founding fathers intented and to reread the constitution. On 4th of July its tradition to chug cheap imported beer and launch Chinese made bottle rockets to celebrate FREEDOM.Its called being an AMERICAN if you cant understand GET OUT', 'The game used to be very good and innovative and one of the best experiences in VR that I recommended everyone buy.\r\n\r\nHowever its seems the Dev is so stuck in his political ways (you can guess what type of politics) that he wont add police related stuff, WW2 axis related, the AK-50 or anything that goes even slightly against what he believes. He also has grown to be a very obnoxious and arrogant man towards anyone who disagrees with him even in the slightest or if you were like me or many of th', 'Overwhelmingly Positive', 97.28, 21.17, 93.03);
INSERT INTO reviews VALUES (6649, 450670, 153, 'Great, fun game. Exactly as much fun as its mobile predecessor.\nGreat (slightly outdated) graphics, fun maps, fun cars, fun challenges.\nFun for people who aren''t into cars even.\nToo bad the servers were shutdown, making some achievements and multiplayer impossible...', 'if your planning on getting this to play multiplayer save your money it does not work', 'Mostly Positive', 76.47, 27.02, 0.28);
INSERT INTO reviews VALUES (6650, 450700, 144, 'With a small station the game plays fine but I''m sure certain devices will get performance issues with larger stations. This is pretty fun in a semi-casual package. I haven''t had any raiders yet but so far even visiting the nearby planets has gone okay, so long as I don''t let my people get swarmed.', 'There are numerious game breaking bugs. Such as resources are not collected from planets, characters stay in low "Mind" even though issue with payment was solved. Also music is so annoying and buggy.', 'Mixed', 65.97, 27.42, 4.22);
INSERT INTO reviews VALUES (6654, 450860, 228, 'better than Rust', 'Very generic world and a gamemix of GTA & Minecraft, its nowhere good but its not the worst either.', 'Mixed', 60.09, 6.30, 2.98);
INSERT INTO reviews VALUES (6655, 450950, 139, 'My only issue with the game is the generic-sounding metal music. And i say this as a metalhead.\n\nShmup is fantastic otherwise.', 'The game only works in old computers. The developer never bother to update the shaders for modern PCs', 'Very Positive', 89.21, 1.08, 0.08);
INSERT INTO reviews VALUES (6657, 451010, 150, 'just fun and well balanced difficulty', 'It is nothing more than killing kittens i will be getting a refund it has really upset me to know these type of games are made liked and played', 'Very Positive', 86.00, 21.92, 0.33);
INSERT INTO reviews VALUES (6658, 451020, 2391, 'This game is probably the SLOWEST dungeon crawler I’ve ever played. And I played a lot of them. \nThe artstyle is exceptional from the character design to the world, everyone and his grandma say this in the reviews, we get it, but this is, first and foremost, a videogame.\nThe fact that the devs did not include some basic features of every dungeon crawler since the Famicom, like skip animation, auto-actions or fast moving or… at least running instead of walking, is dreadful. I mean I am not asking', 'I tried to play this game, got to a certain point, couldn''t stand the grinding anymore, quit, forgot why I quit years later, tried again, got to same point, got sick of grinding again, quit. Grinding does not equal content. It''s sad because the game has a lot of great qualities like the voice acting, world, character designs, art, music, but it''s all meaningless if playing feels like a chore. If they scaled the game differently so that you wouldn''t need to grind, it''d be much shorter but SO much', 'Very Positive', 85.86, 4.43, 27.07);
INSERT INTO reviews VALUES (6668, 451340, 6800, 'Honestly, I love the game, even if I rarely play it, but it''s got a major issue in my eyes, it''s strictly singleplayer, this game would be made easily my top game if this were an experience I could enjoy with a couple of buddies, share goals, and have everyone running specific equipment to keep the mine running, it''d just be a 100% more enjoyable experience if it were multiplayer of up to like, 4 or 5 guys', 'Small community games these days all revolve around the biggest youtuber. Its sad to see potential in a game and then watch over the years the community leaders bully and harass the devs to add stuff they want. Its also happening to another game that started 2 years ago and they already have molested and warped what would have a really good digging game. Not every game is the same, if you want to play farming sim go play farming sim. We dont need skins for shovels, we dont and need decoration pa', 'Mixed', 69.06, 17.37, 156.92);
INSERT INTO reviews VALUES (6674, 451570, 117, 'Wow what can I say this was an absolute AMAZING game!! It was a totally classic P&C adventure in every way possible. Lots of locations and characters, a few puzzles and TONS & TONS of hot-spots, all with tongue n cheek commentary, plus there''s definitely a story here. I could name drop.. For example Monkey island including some of the puzzles being a mix of clever and at times frustrating. There extra hidden objects in each location without hot-spots which are cookies which grant you hints. Ther', 'It''s not terrible and I appreciate how it feels like a one-man job.\nSaid that, I really didn''t like (and even despised) the characters and their art style.', 'Mostly Positive', 76.07, 8.68, 5.50);
INSERT INTO reviews VALUES (6676, 451600, 169, 'One of the most underrated SHMUPS I''ve ever played. Highly refined, has co-op, a workshop, cross-platform, tons of levels, weapons, and ships this really this has it all. Totally down for a sequel.', 'Design like all from other games.', 'Very Positive', 94.67, 14.55, 0.47);
INSERT INTO reviews VALUES (6682, 451760, 925, 'women kiss. and are funny and developed characters in general and have great chemistry. buy it', 'I physically cannot complete the game now, seeing them naked when it was wholesome has ruined the game. Yuri wise 5/10\nStory wise 3/10', 'Overwhelmingly Positive', 95.24, 28.65, 3.82);
INSERT INTO reviews VALUES (6685, 451840, 605, 'One of the OG VR games', 'It''s just a tech demo made for the HTC Vive and Oculus Rift in the very early days of modern VR. Not really worth your time these days. But that''s not the developer''s fault. IMO they are talented, hard-working, even released an update back in 2020 and did a phenomenal job overall. if you feel like supporting them financially by buying this game like I did, then do that by all means. They do deserve it. However, a tech demo is exactly what it is: a tech demo, and buyers should be made aware of th', 'Very Positive', 83.31, 4.27, 0.40);
INSERT INTO reviews VALUES (6687, 451880, 130, 'No one ever sees my reviews, just know its good and move along.\n', 'It''s so boring and pointless, why did you create it?', 'Mixed', 69.23, 4.55, 5.18);
INSERT INTO reviews VALUES (6695, 451990, 107, 'Cranks and Goggles is basically Formula One World Championships on the Pre-World War 1 1920s and 1930s ERA of Grand Prix Racing, it is fun, dramatic, competitive and funny moments when your rivals crash into you, you crash into your rivals to get vengence and revenge when you finished in 1st place at the top step on the podium to become World Champions. it is a brilliant world championship games.', 'I love the old school styling and the simple and clear graphics, but the game play is not fun. Basically, it''s too difficult and unfortunately not in a fun way. It''s made difficult by the poorly utilised perspective that constantly changes and leaves you without sufficient visibility to reliably pick a line or avoid obstacles and other cars. \n\nIf your car is heading from the bottom left to the top right, you can see far up the track. However if you are going from the top left to the bottom right', 'Mostly Positive', 79.44, 12.92, 0.70);
INSERT INTO reviews VALUES (6697, 452060, 1515, 'Finally beat the game after 100 hours of play. Hope to see Caveblazers 2.', 'Let me play the game how I want. This game has so many broken RNG mechanics that you can just get royally screwed. I''ve played plenty of these, but none as bad as this one.\n\nThe fact that I get kicked back to main menu for using cheat engine in a SP game is BS.', 'Very Positive', 86.47, 93.70, 27.07);
INSERT INTO reviews VALUES (6705, 452420, 103, 'Koihime enbu is possibly the best game ever developed by human hands, that being if it was not crafted by the hands of god himself. The characters designed by the same god who designed the human eye to be as appealing as possible, the music undoubtedly performed by the greatest imperial chinese musician known to the great Tianzi''s court. \n\nKoihime has changed my life forever and i could never conceive of touching another shitty anime fighter like strive again. Instead, i will dedicate myself to ', 'For what it offers especially in the market right now, it''s simply not worth the $30+ pricetag.', 'Very Positive', 82.52, 3.58, 1.23);
INSERT INTO reviews VALUES (6706, 452440, 230, 'Shy girl goes to missionary school for girls only and becomes a lesbian. This is the best visual novel ever made\nThere are well written characters, interesting plot, good music and beautiful artwork. But only two endings, second route can only be unlocked after completing the first route. So difficult to play without a guide and choices you make often have no effect on anything\n\nIt''s not a masterpiece, but for this price it''s a very good and long novel with voiceovers. I recommend buy even witho', 'so painfully boring, and characters that are insufferable\ntheres much better out there for yuri VNs', 'Very Positive', 90.87, 33.32, 0.82);
INSERT INTO reviews VALUES (6709, 452510, 392, 'literally one of the best fighter games I''ve ever played I love arc system works', 'In birth? More like Un birth! So I was super excited to play blaze blue cross tag battle. Love blaze blue , played persona arena max and watched RWBY. When I saw the under Night Inbirth I was super hype to play it’s game. So what is an inbirth? From my understanding everyone who some how makes it in the 25th hour of the night that happens once in a blue moon. They must hunt down voids so the void don’t kill people . They also go there to collect EXS to become immortal but if they collect to much', 'Very Positive', 91.84, 12.35, 12.32);
INSERT INTO reviews VALUES (6710, 452570, 879, 'Fantastic representation of cooking. Who would''ve thought that match 3 mechanics would give me a feeling of cooking a complex dish? Absolute gem of the genre', 'Just couldn''t get into this game.  All the mechanics seem to make each other more complicated without making the overall experience more fun.  I think this is a pretty standard opinion though, the reviews say Overwhelmingly Positive, but the steam achievements show only 20% of players get the 2nd achievement in the game.  That is a huge drop-off showing the majority of players pick this up for 2 hours and never play it again; be forewarned.', 'Overwhelmingly Positive', 96.93, 13.97, 2.38);
INSERT INTO reviews VALUES (6713, 452860, 140, 'This simple gameplay of rails-shooter is great, though the price is high. Reminds me of a physical arcade experience. The each gameloop is super short, but the randomizing keeps each game fresh. There is an upgrade system that gives a sense of progression. I only wish there was a co-op mode. Played on an Ubuntu desktop with a mouse.', 'At first it''s a very cool game. Very cool gameplay, very cool artstyle, and has that instant fun factor. It''s dirt cheap too which is another plus. It''s cool for an hour tops though. It''s a mobile port rail shooter that actually belongs entirely in the ''clicker'' game category since you click for each bullet. There''s nothing more fatiguing and mentally barbaric than clicker games. I had no idea this was on mobile prior to buying it but immediately I knew it was because of how insanely priced shop', 'Very Positive', 93.57, 6.80, 4.05);
INSERT INTO reviews VALUES (6719, 453090, 4424, 'Built a nice mass grave outside the coaster that caused 8 deaths then ran and AD campaign for the ride to boost it''s sales during the dip. It stayed the most popular ride in the park. 8 graves/10 would dig 2 more again.', 'There is no quick undo button, for that reason it''s immediately put me off. I just needed to replace some ugly path for a new path, delete the run and it deleted all the bins, decoration, lights etc.. rage quit. done. I''ll delete it now. \n\nI''m sure it''s a great game, but a basic UNDO/REDO button (in terms of features, not coding) is ESSENTIAL for a game where a delete mistake can take half your park with it! A game where you need to line up small items etc, a quick bit of Terra-forming can creat', 'Very Positive', 94.42, 29.05, 0.93);
INSERT INTO reviews VALUES (6724, 453290, 279, 'A very simple and yet uninteresting game that lasts less than an hour. The only extra to this game are its cards, but there''s nothing to say about game at all.\n', 'There is pretty much no story. The puzzles are pretty clever and the dev deserves plaudits for them but they''re not enough to recommend playing this.', 'Very Positive', 81.72, 1.27, 3.17);
INSERT INTO reviews VALUES (6725, 453300, 104, 'A Healer Only Lives Twice\n\nHas a total of 5 trading cards.', 'played the game for 5 minutes and it crashed 💀', 'Mostly Positive', 75.96, 1.58, 0.08);
INSERT INTO reviews VALUES (6726, 453310, 186, 'I enjoyed it, but veterans of this genre may find it lacking. The game is visually attractive and the voice acting is very good (and it''s refreshing to hear a British cast.) The mechanics are a bit clunky, though, and the whole experience is rather short.\n\nAnother factor that killed it a bit is that Finn is such a little beast. This is understandable; the game is a tragic portrayal of the very difficult circumstances some children find themselves in, and the consequences. However, since all the ', 'This is only a negative review because there is no option for "Mixed"; had the game been a little bit longer (I finished it in one sitting), a little bit cheaper, or had provided more story resolution in the epilogue, it would be a positive one. \n\nI have the same problem with this game as I do with Doki Doki Literature Club: It''s too short, so it feels like a vertical slice demo or tutorial level for a much longer, much more impressive interactive storytelling experience, rather than a full game', 'Mostly Positive', 79.57, 2.00, 3.07);
INSERT INTO reviews VALUES (6728, 453340, 922, 'I played it on my Steam Deck. It shows as Unsupported for the Deck and if you try to start the game you will get a black screen with only the audio, so go to Properties - Compatibility - Force the use of a specific Steam Play compatibility tool and choose Proton 3.16-9. Make sure to save a lot, as sometimes the game will crash.\n\nIt´s a very cute game, although on the shorter side. The price is very fair, so I def recommend it if you´re looking for a sweet, fun, relaxing VN.', 'I honestly bought the game just to try it out since it was on sale. if you''re into story-driven games and enjoy following the narrative then you might like it. but for me it was super boring. all you do is follow the story, read dialogues, and move on. it just didnt hook me. Still, props to the devs for their effort ig <3', 'Very Positive', 94.47, 16.12, 0.60);
INSERT INTO reviews VALUES (6732, 453480, 180, 'It''s a f2p card game that you can actually play f2p instead of suffering endlessly while trying to get some sort of meta deck. In addition, it has a sizable playerbase and good gameplay balance (despite how often some people may bitch about Daria).  Don''t let the anime artstyle scare you off if you like TCGs/CCGs, Shadowverse is one of the best games in the genre.', 'If you''re coming here from HS to avoid the aggro meta, don''t bother. After the Bahamut expansion it''s an aggro fest here as well.\n\nAvoid until balance tuning has been done, probably in a couple of months.', 'Mostly Positive', 79.44, 585.03, 136.25);
INSERT INTO reviews VALUES (6737, 453690, 337, '  An easy to use interface and quite playable, if rather a simple design. A fun way to kill some time if you need a breather from all those more intense games, that are available.', 'It''s okay I guess. But it''s so basic. Feels like something that should have been made 20 years ago, not 5 years ago.', 'Very Positive', 81.01, 6.82, 0.93);
INSERT INTO reviews VALUES (6740, 453720, 163, 'I had a great time playing this co-op escape room game with 3 friends! The variety of puzzles kept things fresh, and each one challenged different cognitive skills, allowing everyone to shine in their own way. While some puzzles were tricky and required a bit of external help to figure out, the experience was still enjoyable. There were a few bugs, but they didn’t detract too much from the overall fun. The game is priced well, and the achievement hunting adds some replay value. Definitely worth ', 'Can''t even get the game in a playable state.', 'Mostly Positive', 73.62, 36.78, 1.55);
INSERT INTO reviews VALUES (6743, 453750, 367, 'I wish I could give a neutral rating...\n\nI actually really loved this game when it came out. I even bought DLC for it! Unfortunately, it''s no longer being supported by the developers. The game has some start up issues now. Actually, the only way I can play it now is by turning off my WIFI -- it crashes, otherwise. I''ve also seen some people say that it''s completely unplayable for them. I still love this game, though. There''s not many ecosystem simulation games out there quite like Tyto Ecology.\n', 'i buyd the game later the releasd a dlc i din''t not know about that and the only reason buyed the game was i hoped that will add more biomes but the maked it a dlc', 'Mostly Positive', 76.02, 23.80, 15.22);
INSERT INTO reviews VALUES (6746, 453790, 122, 'i love candice debebe''s incredibly trick lifestyle. i''ve followed this games music and twitter for years but never had the means to play it myself until now. honest to god i don''t know if i''ve ever played another game with so much love and passion put into it. the dev is my personal hero and i want to love something as much as they seem to love making games and music and  i am being so serious this isn;t one of them joke reviews. 10/10 i''ll always be a fan xx', 'An absolute horror show, as well as an assault on the ears. \nDialogue is unbearable to listen to, story is non-sensical, visuals are all over the place, music is diabolical. I have no idea what is going on with this game, but it definitely does not belong on Steam.\nHowever,\nIt''s functional. And in this day and age on Steam, a game that actually works without breaking itself is a good start. There are quests you can partake in, combat is very much like a bullet-hell shooter if the bullets were ab', 'Very Positive', 93.44, 5.95, 0.50);
INSERT INTO reviews VALUES (6763, 454060, 685, 'Blueprint Tycoon\n\nHas a total of 15 trading cards.', 'An interesting idea where you create production chains, expand your operations to do research, and to produce more complex goods. The issue I have with it is that it''s just a headache to navigate the interface, and to figure out the logistics of transporting goods from point A to point B to achieve efficiency without constantly twiddling with the number of workers assigned to shifting the materials around. At first I didn''t think this was too  bad but as the complexity grows, so do the headaches', 'Very Positive', 80.58, 0.70, 6.73);
INSERT INTO reviews VALUES (6764, 454070, 140, 'Very good start to a MMO, you pick your own skills want to advance in, magic or combat stuff, its your pick. each level up, you get a point to put into what you like, Stats atm, are raised defaut, but is lots of bonus weapons to aid you in your stats needed. i went as a mage/healer, and its been fun so far. give game a try, you wont be sad. well worth the cost they asking.\n\n', 'Pretty terrible example of an MMORPG. So bad in fact they had to drop the MMO, i''m not sure who wanted this as a single player game but it''s just not working out for me. Hard pass.', 'Mixed', 54.29, 231.92, 3.15);
INSERT INTO reviews VALUES (6766, 454100, 182, 'A fairly competent Super Meat Boy like hardcore platformer. The controls feel tight and responsive. The hitboxes are fine for the most part - although you will occasionally feel a bit ripped off because of them. The levels are decently well designed and offer a solid challenge. At least, these were my thoughts up until level 19 when the game starts to go downhill.\n\nLevels 19 - 25 are full of gimmicks that make the game more challenging out of annoyance rather than clever level design. Level 19 h', 'It''s just very basic and not doing much for me.  It''s cheap, which is fair.  At this point though you might as well just be playing free games on itch.io instead.', 'Mostly Positive', 75.27, 6.70, 0.17);
INSERT INTO reviews VALUES (6767, 454120, 4280, 'Incredible game concept, poor player count.\r\n\r\nLaunch was messy, and the game will not appeal to casual audiences. I recommend Starbase if you''re an exceptionally enthusiastic fan of spaceship building games.', '- - - - -\nWord of warning: This game was abandoned shortly after launch as the developers unfortunately had to go work on another game in order to secure more funding. I''m skipping a lot of information, this situation is complicated and I genuinely wish the best for the devs. RECENTLY, the devs have sorta made a comeback and have announced they are going to begin working on the game again. But as things stand the game is still pretty "dead" in terms of playerbase and updates.\n- - - - -\n\nBought t', 'Mixed', 57.13, 244.85, 91.77);
INSERT INTO reviews VALUES (6769, 454140, 222, 'it kinda like tennis', 'I''m gonna put this under the ''dangerously immersive VR games'' category. Be warned: you ARE GONNA BREAK SOMETHING in your room while playing this. The game has an ''automatic run'' feature so you don''t actually have to run in real life, but even with that you still need a MASSIVE room to move around if you want to properly hit the ball. What makes it worse is that the game is fairly realistic so you easily get very absorbed into the matches. You are swinging left and right, moving back and forth, r', 'Very Positive', 87.39, 10.58, 14.03);
INSERT INTO reviews VALUES (6770, 454160, 104, 'I loved what I played of it and will definitely be doing a full playthrough of it in the future.', 'my eyes!', 'Very Positive', 94.23, 1.05, 0.13);
INSERT INTO reviews VALUES (6778, 454250, 432, 'A little slow to set up a scene, and movement is annoying as it is only point and click and you cannot search every nook and cranny, only what it will let you do. That said it is in the perfect adventure puzzle genre, no hidden objects, just find and solve puzzles in an atmospheric castle. The best type of game there is for me. More elementary than the Myst series and less creepy than the Room, but very enjoyable. Nice soundtrack here and there too.', 'Pretty sad about this one. It starts off promising, but the vast, vast, VAST majority of challenge in this game comes from pixel hunting essential puzzle pieces in dark/muddy looking environments. Once you actually have all the pieces, the solution is (most of the time) obvious. You''ll spend 70-80% of your playtime wracking your brain trying to figure something out, only to realize that you just don''t have a vital part of the solution, and it really galls after a while.\r\n\r\nJust a tip for any pas', 'Very Positive', 80.32, 39.68, 6.88);
INSERT INTO reviews VALUES (6780, 454320, 104, 'Great puzzle game. Orchestrating a few simple movements to create a complex, repeating motion is very satisfying. The "Hint points" system is well balanced, helping players when they feel stuck, without taking away the challenge or being punishing. Like all great puzzle games, you will on occasion find your own solutions that weren''t the intended solution.', 'no way to play in windowed mode or change which monitor to fullscreen to\nno keyboard shorcuts to quickly rotate or switch what i have selected\neven on second level there seemed to be blocks missing (the level in hint looked different)\nthe dev seemed to have abandoned this game', 'Very Positive', 89.42, 104.78, 0.13);
INSERT INTO reviews VALUES (6782, 454350, 701, 'Heavily inspirted by games such as the original Medal of Honor, the original Call of Duty, Day of Defeat and Return to Castle Wolfenstein. Days of War if built in the Unreal Engine 4, which makes the game really user and community friendly. \n\nIts a WWII shooter with oldschool standards: no bull****, you can''t drop bombs with your ipad while taking a dump, can''t ask for killstreaks nor health regen or any of those crutches. THANK YOU.\n\nIts a class based shooter where you fight in a wide variety o', 'This game is maybe worth $5 with the amount of content and playerbase it has. Highly not recommended. It seems that the developers are trying to ruin their own game.', 'Mixed', 45.79, 8.43, 15.38);
INSERT INTO reviews VALUES (6783, 454380, 111, 'Instead of TTS, i want to post my message to Thor here.\r\n\r\nHi Thor,\r\n\r\nI play Champions of Breakfast with my daughter sitting on my lap. She’s in charge of the mouse, shooting enemies, while I am in charge of the keyboard, dodging bullets. She also picks selections of spices from the rack for me to play. Most of the time, she picks all the spices.\r\n\r\nThank you for making this game. I never thought I would play this game with my daughter, and she is loving it. However, I haven’t decided yet wheth', 'All and all not a bad game but I won''t recommend for the following reasons:\nNo description of the power ups:\n      At times you are given a choice or power ups to choose but there is no description of what they actually do in game or between games. Same for the special powers.\nNo controller support:\n      Store states you can use a controller but the default key bindings are janky and there''s no options to change them which makes it unusable.\n1 - 2 hours of play time:\n      3 dollars is probably', 'Overwhelmingly Positive', 96.40, 9.45, 2.02);
INSERT INTO reviews VALUES (6785, 454410, 184, 'I''ve recommended this game, but I want to stress that if you''re probably going to want to get Giga Wrecker Alt. on consoles instead of this version. While it''s a graphical downgrade playing on a console, the port appears to be a superior product overall. Better translation, a second playable character, an additional ending just make Alt. a better choice.\n\nIf you don''t mind some engrish, or you care about the graphics, then this version is fine, but maybe wait until it''s on sale. Otherwise, the g', 'started off pretty cool but got annoying and tedious way too fast\nbut what actually got me was the first boss battle\nhow in the world should one even think of trying to "parry" the first boss attacks?\nyeah, you are given a very in your face hint once you die a few times, absolutely clueless about what to do, but that''s an awful solution and such a disgusting crutch for the bad boss design', 'Mostly Positive', 76.09, 4.07, 2.27);
INSERT INTO reviews VALUES (6789, 454530, 129, 'If Your into Accurate Historical War Games, this is for you, not initially easy to get into, but it bites you hard, and pulls you in, so much, you cannot help but want to learn and play, from the historical fall outs of the high \r\ncommand, and subordinates, about logistics, fuel, transport etc, way of waging the war, to the battlefronts, where the battles take place, if you love reading the reports, as I do, from disciplinary measures, in the HQ staff, to all the things that run a campaign, wher', 'while the system is simplified compared to case blue. the battles are completely unrealistic. losing battle against with encirclement ratios 4:1 is plainly stupid', 'Very Positive', 86.05, 78.92, 45.73);
INSERT INTO reviews VALUES (6797, 454650, 17524, 'In Dragon Ball Xenoverse 2, players embark on an epic quest to assist Goku and Vegeta as they attempt to open a chain of fast-food restaurants across the universe. The game’s storyline revolves around the two Saiyans navigating the complex world of intergalactic commerce while fending off competitors like Frieza, who has shifted from world domination to owning a rival franchise. Players are tasked with helping Goku perfect his cooking skills while training in secret to defeat food critics who se', 'The gameplay itself is decent but the multiplayer missions are difficult to solo with AI and the game is kind of dead\nIf you are a hardcore Dragonball fan you''ll probably enjoy the game.\n\nFor the record Bandai, I know you want to get as much money as possible; but if your fans need to make a "DLC guide" because any of your company''s games have so much DLC, that''s a problem and for that reason I cannot recommend this game to anyone besides major DB fans in its current state, especially since in o', 'Very Positive', 89.40, 20.75, 170.97);
INSERT INTO reviews VALUES (6809, 454890, 116, '"Arcade Hardcore Starbullets"\nProject starship is a nice little retro arcade-bullethell with pixel graphics and lots of flashing objects. The warnings are true. High risk of epilepsy if you see those red-yellow triangles and thousands of flashing dots. Most remarkable for the game is the tiny base picture (480x360) which you can upscale over F to fullscreen (maybe it''s just for the performance) Then everything seems pixelated but still very unique graphics. And the soundtrack loops are brilliant', 'Not Recommended', 'Mostly Positive', 76.72, 7.33, 3.52);
INSERT INTO reviews VALUES (6811, 454950, 231, 'Not Quite What I Expected\r\n\r\nWhile the game has a decent plot with a unique charm reminiscent of "Papers, Please," it wasn''t exactly what I was hoping for. I came in expecting a game rooted in real hacking mechanisms and knowledge, but unfortunately, the hacking aspect feels overly simplified. Most of it boils down to basic commands like "ping" and "use this computer on this IP," which left me wanting more depth and realism. That said, the detective narrative is engaging, and the game''s style do', 'This plays like a really inferior version of hacknet to me. I don''t love the interface, and the command syntax is really awful and unrealistic (can''t launch new connection while on a server, console history resets when you disconnect, using an invalid IP says ''unrecognized command'' instead of an actual connection error, and there are serious logical inconsistencies with how evidence works that make it necessary to follow a walkthrough even when you''ve made a better deduction of the correct evide', 'Mostly Positive', 77.92, 5.83, 4.97);
INSERT INTO reviews VALUES (6818, 455120, 604, 'Stay Close is a very scary game with a dark and frightening ambient. The designs are nice and the sounds are great. If you like horror games, you will be served. I recommend it!!! 🖤', 'I bought this expecting a funny and scary experience but it was unfunny and bad experience', 'Mixed', 57.28, 13.97, 0.67);
INSERT INTO reviews VALUES (6826, 455400, 759, 'One of the very few games I''ve played on mobile and I liked it there and I liked it here but its pacman as an endless runner high score chase and well.. those old arcade genes still get the job done in spurts.', 'A boring grind fest is what this is. Trying to max out all the powerups was not fun and takes too long with how little coins you get. Doesn''t help most of them are the exact same but just better versions of the other making most of them feel pointless to max out like "Laser" when you have "Optics" which is pretty much better and unlocked later on. I only did it for the achievement.\n\n\nPacman Championship Edition is more worth buying', 'Very Positive', 94.47, 15.48, 26.82);
INSERT INTO reviews VALUES (6836, 455820, 661, 'I''ve played 2 games by Spearhead Games. Stories and this, both are absolutely excellent with a fantastic, semi-time loop game mechanic. This is a more mature story, but still fun and utterly enthralling. \r\n\r\nThis is a must-buy for fans of interesting narrative games.', 'Wish I could rate a game postively/negatively without the ''recommend'' feature. It''s enjoyable, but not for everyone.\n\nNot a bad game, but not really... a good one either? While the concept is interesting, I felt the execution was lacking. The combat was middling and the camera angles became frustrating; some exploration and choices would lock you out of storylines. I wish there was a way to be able to choose which omensight to share or to not share it at all. The most interesting part of this ga', 'Very Positive', 89.56, 6.27, 3.90);
INSERT INTO reviews VALUES (6838, 455910, 901, '"Rogue Squadron! Where''s our cover?!" "Rogue Squadron! Where''s our cover?!" "Rogue Squadron! Where''s our cover?!" "Rogue Squadron! Where''s our cover?!" "Rogue Squadron! Where''s our cover?!" "Rogue Squadron! Where''s our cover?!"', 'if this game is 2 dollars, go a buy yourself a coffee instead.\nyou''ll waste your time trying to fix it.', 'Mostly Positive', 70.37, 3.40, 1.53);
INSERT INTO reviews VALUES (6851, 456430, 232, 'Nice little hidden object game. Puzzles were logical and neither too easy or too hard. The background music is festive and the visuals decent. It has easy achievements ( you unlock all of them while progressing in the game ) and everything feels smooth without any bugs. The only bad aspect of the game are the frequent ( minor ) grammar mistakes, nothing too serious though to the extent they could affect how someone enjoys the game.\n\nRecommended, especially while on sale and of course during the ', 'All I can think of while playing this game is that Chinese forks and spoons joke from the Game Grumps play-through.\n\nActually, just watch that instead of playing this! This is basically just a video with interactive elements anyway.', 'Very Positive', 88.79, 2.13, 1.58);
INSERT INTO reviews VALUES (6854, 456540, 147, 'This game offers a nostalgic look at early cinematic gaming. These titles blend live-action footage with graphics for a classic Star Wars experience. While innovative for its time with space combat and on-rails shooting, gameplay and graphics obviously are already outdated. Still, it''s a commendable piece of gaming history, ideal for fans of classic Star Wars and interactive storytelling pioneers. https://steamcommunity.com/sharedfiles/filedetails/?id=3266072069 https://steamcommunity.com/shared', 'Selling 30 years old game for 10$ and not giving it keyboard support...', 'Mixed', 69.39, 9.95, 0.10);
INSERT INTO reviews VALUES (6857, 456670, 2000, ' He will laugh at your bad luck ', 'I didn''t care that the first game had generic writing because there wasn''t much of it. The host quips about fleshing out narratives from the first game but the writing isn''t any better, there''s just a lot more of it and the game draws more attention to it. You have to click through paragraphs of text every time you start a game, campaigns have dialogue trees full of empty and meaningless choices, and victory often requires you pay attention to details buried in the word avalanche. Especially sin', 'Very Positive', 83.80, 27.38, 5.60);
INSERT INTO reviews VALUES (6859, 456750, 5542, 'Very beautiful puzzle game with great graphics and textures, camera animation is nice too, the atmosphere is amazing and the feeling of being there is great and convincing.', 'the controls are terrible. the backtracking and having to run back and forth with slow ass animations is also terrible. first two games were between good and very good. this has been a slog, and i''m dropping it.', 'Overwhelmingly Positive', 95.85, 7.52, 4.12);
INSERT INTO reviews VALUES (6865, 457010, 157, 'Its actually not bad! Needs better walk speed and a (small) tutorial but mostly it runs good and is playable (haven´t gotten very far yet thou will update once I do)\n\nEdit: Played some more and this game realy got some potential! I can´t wait for a multiplayer serverlist, this should be great fun in multiplayer, especially if the thing with the credits works because I can imagine some people will want to trade items and specialize production and maybe even make little shops to sell their product', 'Got this from a friend purley for Coop and coop was removed shortly after. Like seriously? Don''t list a game saying there is coop then remove it after hundreds of coop players bought it. False advertising BS. I refuse to hamachi my games, so don''t bother telling me to use that workaround. When or if they bring coop back maybe ill change the review, but for now, I will not recommend this game because it is just flat out boring alone.', 'Mixed', 69.43, 1.32, 2.33);
INSERT INTO reviews VALUES (6867, 457140, 45099, 'Oxygen Not Included isn’t just a game for me—it’s been so much more than that. During one of the darkest, most painful times in my life, it became my escape, my distraction, and honestly, my reason to keep going.\n\nThere were days when it felt like I couldn’t handle the weight of everything happening around me, but this game gave me something else to focus on. It’s not just about building or surviving; it’s about creating something out of chaos, and that’s exactly what I needed.\n\nI don’t know whe', 'It seems it is impossible to enjoy this game without having a degree in physics, math, and thermodynamics first. Very, very, very steep learning curve, it required watching hours of videos and reading guides on how to make things properly. Failure is mandatory until you know how endgame looks like, what to build in what order, but need to reach endgame first somehow. There are way too numerous problems that can occur to mess up all base, like running out of resources, or not spawning good geyser', 'Overwhelmingly Positive', 96.04, 672.35, 454.97);
INSERT INTO reviews VALUES (6868, 457210, 1123, 'when I bragged about my world record on discord the top ranked player beat it in 20 minutes', 'The leaderboards in this game are a joke. The devs gave really stupid community members the ability to ban people because those are the only people willing to do that job. One of the moderators (guy named Sirius) banned me without attempting to reach out to me at all because I got #2 in the world on some random level and did a 360 in midair during a part of the level where nothing was going on for a few seconds. All of my leaderboard times got banned because this random kid assumed I was cheatin', 'Overwhelmingly Positive', 95.55, 164.65, 44.77);
INSERT INTO reviews VALUES (6872, 457320, 362, 'Way better than Racket:Nx', 'Smashed my Controller into a wall and broke it because the Grid wasn''t displayed correctly even tough the SteamVR Setup was correct.\nRIP VR', 'Very Positive', 89.78, 4.62, 0.52);
INSERT INTO reviews VALUES (6880, 457480, 156, 'It''s an entertaining little domino puzzle game. As others have said, the physics engine can be nondeterministic among a couple other issues.', 'I completed achievements on this game, painfully. So much RNG, the physics is far inconsistent. You can replay the same setup, nothing change, but having far different outcome. Painful especially above level 20.', 'Mostly Positive', 75.00, 3.17, 12.83);
INSERT INTO reviews VALUES (6883, 457530, 112, 'My Lady is a romantic Visual Novel.\n\nThe game is quite short, but it still boasts 5 different endings. The art is modest but alright, the music is pretty good and immersive, but the voice acting is... amateurish. The story is fine, but it lacks quite a lot of depth. Some of the mysteries aren''t really explained which is a shame, but the plot is interesting. For how cheap it is, I did enjoy reading the twenty minutes or so of text and learn about the characters. I gotta say the characters are one', 'My Grandfather smoked his whole life. I was about 10 years old when my mother said to him, ''If you ever want to see your grandchildren graduate, you have to stop immediately.''. Tears welled up in his eyes when he realized what exactly was at stake. He gave it up immediately. Three years later he died of lung cancer. It was really sad and destroyed me. My mother said to me- ''Don''t ever smoke. Please don''t put your family through what your Grandfather put us through." I agreed. At 28, I have never', 'Very Positive', 83.93, 0.43, 0.88);
INSERT INTO reviews VALUES (6885, 457570, 144, 'I absolutely LOVED this game! Despite the playtime registered it took me 6h:45m to complete, but this was spent offline while travelling.\n\nI had just finished Terror at Oakheart and was looking for something similar and this more than fit the bill!\n\nWhere to start? At the beginning I guess. I really liked the premise and concept, it grabbed me from the off and never really let go. The story was strong throughout.\n\nI LOVED the Easter-egg type references to the movies that inspired it, and it is a', 'did not enjoy the insta death', 'Very Positive', 86.81, 0.15, 4.63);
INSERT INTO reviews VALUES (6886, 457580, 135, 'Please note, that I''ve played this on the Oculus Rift DK2, using the Oculus runtime 1.3 and the present beta version of Steam VR. Steam VR only just implemented support for runtime 1.3. It does work, but the scale is totally off. Basically the player character is about three meters large. I assume this is caused by some problem between the very new runtime 1.3 and the newest beta of Steam VR and not a problem of this game. Just keep in mind that, should you choose to play this on a Rift DK2 or C', 'As with all "scary" games and movies etc....it is the SOUND that makes it scary. Sudden loud noises coming off quiet whispers etc... pretty weak overall. I am sure there are a ton of ppl that would easily be scared by it though. I can not recommend it, but I do not regret buying it. I am getting a kick out of trying as many VR experiences as possible!', 'Mostly Positive', 74.81, 0.17, 0.27);
INSERT INTO reviews VALUES (6887, 457600, 113, 'Emerge: Cities of the Apocalypse\n\nHas a total of 9 trading cards.', 'Some nostalgia around this game - I played the demo in 2016 during my younger years. This was the first 4X I got really sucked into, more so than Civilization games (at that time). And I do like its isometric artstyle.\n\nHowever on revisit, I did not enjoy it as much.\nVery likely because I suck and I spread out my research points, but things got repetitive fast while also getting overwhelmed my enemies. Realtime sections were a chord (and AI wasn''t much better either).\nWith another sequel, maybe ', 'Mixed', 65.49, 1.47, 1.62);
INSERT INTO reviews VALUES (6891, 457680, 350, 'OUGH... LITTLE GUY SIMULATOR...\r\n\r\nthe day we found earth has all the fundamentals that team sigono would go on to build on in their future games: the trademark lineless art style with a wonder-filled expression of space, a simple and affective story with lots of environmental detail that sketches out a picture of what''s happened beyond the main characters'' perspective, atmospheric sound design, and a chill gameplay loop. and while you don''t NEED to know the real-world cultural references in the', 'Primary reason for the negative review is that $15 is an insulting price to pay for this game. The game''s fine, the star mechanic is neat and the story''s passable. The post-game missions finally real like they''re challenging and giving you interesting clues, but they''re gone before you know it. Worth getting heavily discounted, but full price is highway robbery.', 'Very Positive', 80.57, 8.48, 3.73);
INSERT INTO reviews VALUES (6893, 457710, 139, 'VERY GOOD GAME\nI LIKE', 'Could have been pretty okay if the game wasn´t broken.', 'Mostly Negative', 24.46, 0.12, 4.57);
INSERT INTO reviews VALUES (6894, 457730, 249, 'Fun, charming, unique. The whole package that makes a great game. Although the difficulty is kinda whack (either too easy or insanely hard).', 'A few autistic campaign levels, where you have to click faster than you can you can process your thoughts. Unlike the first game where strategy was more important than clicking speed. Pity this came up after the refundable gameplay time.\r\nNote: I completeled the first game 100% hardest difficulty without ever looking at a walkthrough. And in this game mission 34 I can''t do it even if I copy a walkthrough. I''ll just lower difficulty on stupid levels like this I guess.', 'Mixed', 58.23, 12.38, 81.18);
INSERT INTO reviews VALUES (6895, 457760, 643, '\nThe Signal From Tolva has a lot of charm. The graphics are easy on the eyes, whether it be the landscapes or the mysterious structures dotted around or the cool robot designs. The background music adds to the eerie atmosphere of the planet. The gameplay is a straight forward and well-balanced capture territory fps. The story is there if you''re paying attention; it''s a mystery that teases you with data files you find throughout the game. Even so, it does leave something to interpretation. More c', 'Does not take long to see how truly empty this game is. Slogging across barren nothingness to get to a random point to do a random thing, then sent to the next meaningless mcguffin object knowing full well it will just result in being sent to the next thing after that. You gotta give the user something to engage with at the beginning of the experience. You can''t just assume that they randomly share your personal vision and will push through the nothing out of blind trust.', 'Mostly Positive', 71.85, 40.45, 0.50);
INSERT INTO reviews VALUES (6900, 457860, 433, 'For space nerds.  It''s a ride-along on the Apollo 11 mission, like the title suggests.  You get to fly the rocket, connect to parts of the rocket in space, and land the lander.  And bounce around on the moon, that''s fun.', 'This sim was great until it stopped working a few years ago.  I''ve noticed several comments regarding the same.  The developer seems to have abandoned the sim.', 'Very Positive', 82.68, 1.58, 4.17);
INSERT INTO reviews VALUES (6903, 457960, 573, 'I''m middle aged and overweight.  I find repetitive exercise mind numbingly boring.  I''ve lost 11 pounds since Christmas playing this game.  It''s addictive.  I love it.  The only reason I am typing up this review is because I''m too tired to stand up and play more.', 'Honestly, as much as Holopoint is a lot of fun and a really solid way to get in shape, I can''t recommend it because the developer does such a bad job supporting it. He seems to patch in two bugs for every bug he fixes, and recently has all but abandoned development for Holopoint (but not before doubling the price).\n\nThe second half of the game is too difficult to reach and has broken aiming, but with total silence from the dev for three months we can probably assume he''s cut and run.', 'Very Positive', 89.18, 29.57, 18.70);
INSERT INTO reviews VALUES (6905, 458000, 343, 'Love it', 'Interesting idea for a game and it was decent until the combat happened. When you are the only survivor it is fine, even the combat is fun. However once you start to get more survivors, the combat becomes more involved and annoying.\nBasically if you have 3 survivors for example then combat is (pause) issue commends, a few seconds later (pause) issue commands, rinse and repeat every few seconds. It gets annoying.\nIt would be so much better if the survivors you control can act act for themselves a', 'Mixed', 69.68, 45.13, 1.42);
INSERT INTO reviews VALUES (6923, 458470, 249, 'A stereotypical Casual Hidden Object Point & Click Adventure game.\n\nNot exactly thought-provoking. Only take a few hours to fully complete.\n\nMostly a bit of leisurely wholesome fun that doesn''t take itself too seriously.', 'I struggled with whether or not I should give this game an up or down, I don''t actively hate the game, and I did enjoy some of the puzzles as well as the sound in the game... But I don''t feel the game has so much charm as the previous ones, and some parts of the game annoyed me a lot.\n\nThe story doesn’t really match the relaxed gameplay at all, and I think it fits an action game or an RPG a bit better. It felt a bit too action packed for a point and click adventure game’s slow exploration and pr', 'Very Positive', 94.38, 6.37, 3.32);
INSERT INTO reviews VALUES (6924, 458480, 124, 'A classic point-click hidden object game from Artifex Mundi.\nThe low difficulty mode is good for casually completing on a bored day.\n\nMost of the puzzles in the game can be completed with a bit of thought and clicking the mouse, but you will feel a sense of accomplishment if you complete them in one go.\nIt''s too expensive to buy at full price, so I recommend buying it on sale.\n', 'I was quite disappointed by this game. although the backgrounds are gorgeous, the character animation and voice acting are quite poor, and the story not that riveting. Basically you travel through different worlds attempting to find your uncle, and at the same time assemble an artifact based on elements (water, air, etc). But you get almost no back story on either you or your uncle, no idea of how and where you found the plans for the original portal you''ve constructed together, no nothing.\nSome', 'Very Positive', 90.32, 8.72, 6.63);
INSERT INTO reviews VALUES (6931, 458580, 304, 'Fantastic game. getting together with friends and playing through the story mode is an amazing experience', 'I understand that this is a high mobility game but DAMN I have strong vr legs at this point and this was a nausea speedrun.\nGameplay wasn''t fun enough to overcome the motion sickness. The idea is interesting but the swinging is narrowed to "bushes" for some reason, like it was in the first game, and that''s too restrictive to be fun.\nThe first boss was interesting but that''s about it.\n\nEdit: holy bananas I just noticed this is 25€ at full price. Big no. I paid a few bucks for it and that''s fine, ', 'Mostly Positive', 79.28, 55.42, 0.47);
INSERT INTO reviews VALUES (6937, 458710, 2276, 'solid td ,nice look and feel ,not to deep good unwind return to game .', 'unplayable', 'Overwhelmingly Positive', 95.08, 50.75, 4.65);
INSERT INTO reviews VALUES (6938, 458730, 413, 'First played this on the 3DS and it was definitely one of my favorite games on the system.', 'The game spends the first several hours constantly interrupting you with tutorial popups informing you of all the systems, but none of that matters due to how easy it is to walk over enemies. The characters hype up bosses that are killed in two hits to their weak points, and there''s no need to engage with the turn delay system or repositioning your squads to take advantage of bonus gauges because fights end sooner if you just deal attack damage. \r\n\r\nYou produce better squads if you have higher r', 'Very Positive', 80.87, 38.10, 8.28);
INSERT INTO reviews VALUES (6939, 458750, 436, 'If you like FireAlpaca already it''s worth it, basically the same program but a bit more polished.\nI basically only bought this for the dark mode because of my light sensitivity and chronic migraines. I''ve been using the free version so long I didn''t mind too much forking up the cash, but I think it''s *really* crappy to put dark mode behind a paywall, especially this much of a paywall, like, wtf?', 'I love Firealpaca don''t get me wrong but not crazy different then the free version. Also having black UI behind a paywall is quite goofy!!', 'Very Positive', 91.97, 134.55, 734.75);
INSERT INTO reviews VALUES (6941, 458770, 286, 'I Killed A Fan And Got A 12 Sec Time Penalty', 'Not really nice to drive with a controller nor a wheel. The car is very sensitive goes all over the place, if you lower the sensitivity it just becomes delayed and numb and if you increse it it goes everywhere...same almost worse on WRC 7. There is huge improvment from WRC 8 and later (9, 10 and generations)...But this one is not enjoyable at all. Graphics are medium and sound too...don''t loose yourt ime or any penny on this. PS.first i write a review, i hope it will be usefull for you. If you w', 'Mixed', 68.53, 9.57, 2.03);
INSERT INTO reviews VALUES (6943, 458830, 160, 'Nice game play and graphics.', '8 ball is better Snooker. don''t believe me, then ask Judd Trump, lol.\n\nI would love to get a refund, but I bought this game in a bundle, and the refund process looks complicated, so I guess I''ll keep it. Also, how is this game still in early access', 'Mixed', 60.00, 9.38, 0.32);
INSERT INTO reviews VALUES (6944, 458920, 164, 'LISTEN TO ME, the climbing wall mini game. HOLY HELL. One of the best VR experiences I have had yet.  Is it worth $20? I don''t want to tell you how to spend your money. Nor do I want to set you up for disappointment, because it is a short mini game. But one second you''re tossing balls at milk bottles and thinking, yeah this alright.  Then you switch to climbing wall.  HOLY CRAP. You''re sweating your balls off climbing around an obstacle course of doom.  Its intense.\n\nOverall, Carnival games is p', 'Game crashes 10-15 minutes into play. No longer playable until fixed, if ever. Was a great game to let people try VR for the first time. Shame really.', 'Mixed', 51.83, 6.13, 2.20);
INSERT INTO reviews VALUES (6948, 459010, 339, 'Starts with a spooky mine cart ride, with light-gun targets like you''d find at any amusement park ride... but it doesn''t take long for things go "off the rails" and get even spookier! It''s a simple straightforward experience, plays well, has a great dark creepy atmosphere and plenty of jump scares, perfect for a quick scare or VR demo. You won''t find hours of content to level up and unlock here. For what it is, and knowing you can find it on sale for less than $5, I give it... Thumbs: UP!', 'The VR sickness in this game is high, if you are remotely susceptible to VR sickness I would move along.  Super neat jump scares and overall nifty gameplay but the hours of VR sickness afterwards is a major deterrent.', 'Very Positive', 86.14, 0.80, 0.62);
INSERT INTO reviews VALUES (6952, 459080, 841, 'as of today the giant 1.5 (IV) update came out, and it is a massive improvement to just about everything that was wrong with the game initially. the main giant improvement is the battle system: battles are now closer to a traditional turn-based system and very fast paced. load times have been cut down completely. the game has still retained its personality while adding huge amounts of new content and mechanics. \n\nif you either didn''t like the game in its original state or were on the fence about', 'this feels like persona 5 mixed with earthbound but if it was 100% worse. i yiiked my yiik to this', 'Mostly Positive', 79.90, 53.50, 1.37);
INSERT INTO reviews VALUES (6953, 459090, 249, 'Short linear simplex great.', 'good art style and it lets you pause in combat. The story started interesting but got stupid and overly melodramatic and anoying. Got to the point that is was just not worth playing any more.', 'Very Positive', 89.16, 10.18, 10.55);
INSERT INTO reviews VALUES (6958, 459220, 5357, 'One of the few RTSes out there that is not only controller compatible but controller optimized. The AI scaling is pretty neat but the Prophet of Regret can eat my entire ass.', 'This comment is only to protest $80 games that are approved by Xbox. It is not about the game itself.\r\n\r\n#No_to_$80_games.', 'Very Positive', 91.94, 8.83, 5.65);
INSERT INTO reviews VALUES (6960, 459310, 100, 'While I enjoyed it, this is definitely NOT for everyone, due to violating one of the main themes of storytelling - "Show, don''t tell".  We''re told (quite often) about the various trials that marginalized hero types face, but rarely see it in practice.  It''s definitely part of the background, but for the most part, you''re simply told that "X circumstance exists, and needs to change" without much in the way of showcasing it.  That said, I honestly found it LESS jarring than an instance in "Heroes ', 'I''ve been a huge fan of all the other games by this author, so I''m a bit disappointed to have to say.. I didn''t like this one. The game doesn''t make me feel like the main character as much as just being an excuse to have to read very preachy thinly veiled propaganda over and over again. The second interlude felt extremely artificial for instance. i''ve racked up a lot of hours in this game simply because I couldn''t do more than a few pages at a time before needing a break from it, and left it run', 'Mixed', 62.00, 5.00, 31.83);
INSERT INTO reviews VALUES (6977, 459820, 428, 'As a lonely gay girl I would die for my 2D polycule, and I will not state how much money I have spent on diamonds to get my favorite Phone Fling characters as full girls.', 'now I know what your going to say "200 hours and a negative review this has to be a joke" it''s not this game is cruel, and I hate it.', 'Very Positive', 89.95, 444.13, 201.97);
INSERT INTO reviews VALUES (6983, 459940, 174, '\r\nI AM THE DEER MAN!\r\n', 'Oh deer.', 'Mixed', 68.97, 0.57, 0.63);
INSERT INTO reviews VALUES (6987, 460160, 157, 'A funny short visual novel, with more of the great humor of the series.\nI loved it.', 'Came for boobs, got no boobs, waste of 2 euros.', 'Very Positive', 90.45, 1.20, 0.12);
INSERT INTO reviews VALUES (6993, 460340, 103, 'This is a fun little strategy roguelike that is clearly set up in mobile game format, but for some reason was released for PC as a one time purchase instead. It''s simple but engaging and can be bought on sale for essentially free. The only downside is that you can''t save your progress mid-game and some runs can take 20-30 minutes. Looking forward to the sequel!', 'very cheap and very bad', 'Mostly Positive', 75.73, 4.88, 0.12);
INSERT INTO reviews VALUES (6994, 460430, 829, 'It can get a little boring. The story spends a lot of time establishing all the characters'' bonds. I wanted Scary Movie, not Friends. But the scary moments are fun. It''s a great horror visual novel if you don''t mind all the build-up.', 'The idea is interesting, but realisation is rather meh. Game looks like generic mobile game #42, sounds even worse, and voice acting made me turn it off in first 15 minutes or so. Oh, and how can we make a game without obliged "white ppl le bad" in this day and age.', 'Very Positive', 88.06, 34.78, 5.80);
INSERT INTO reviews VALUES (7003, 460700, 327, 'One of my favorite games that I''ve ever played. It''s beautifully drawn, has fun exploration and combat, excellent music, and has a great story. Most of the negative reviews are from people with thousands of hours in fps games, who''s brains are so fried from constant stimulation they can''t enjoy a story focused game. Another common complaint is that the controls suck, but that''s just because the game takes place underwater. The controls look and feel great, and are consistent, if you have problem', 'Song of the Deep reminds me more of Aquaria than Pronty or Depths of Sanity in that it plays quite slowly and narrated.  Like Aquaria, it doesn''t manage to keep my interest.', 'Very Positive', 83.79, 28.53, 0.58);
INSERT INTO reviews VALUES (7006, 460790, 9516, 'Slay queen \nHigh-heels + Guns. \nPole dancing to kill Biblically Accurate Angels.\n\nEnjoyed playing and finishing it on Normal mode alot.\nI need Bayonetta 2 on PC', 'Playing as a witch, this game and it''s series is just heretical seek Christ', 'Very Positive', 92.24, 43.57, 0.60);
INSERT INTO reviews VALUES (7007, 460810, 3644, 'Vanquish is an insanely fast-paced, thrilling third-person shooter that delivers pure, nonstop adrenaline. The action is relentless, stylish, and flawlessly executed, offering one of the most exhilarating gameplay experiences in the genre.\n\nSure, the story is cheesy, the dialogue over-the-top, and the characters are straight out of an action movie cliché. The campaign is also on the short side (around 7-8 hours). But none of that takes away from the fact that Vanquish is a complete action packag', 'PC controls are trash.  Been PC gaming since 1988 and this has the worst, non functional keyboard and mouse controls I have ever used.  Really stunned that this was released on PC.  DO NOT BUY.', 'Very Positive', 89.85, 23.63, 0.37);
INSERT INTO reviews VALUES (7011, 460950, 21361, 'My grandma passed away in her sleep last night and it’s been taking a toll on me. I just picked a random steam game I bought in the summer sale to help try to take my mind of things. I’m really enjoying the story and combat, the soundtrack is also supreme. Would definitely recommend.', 'Justin, it''s been 5 years. Where''s the DLC?', 'Overwhelmingly Positive', 97.98, 7.22, 34.95);
INSERT INTO reviews VALUES (7012, 460960, 167, 'The Deed x 3', 'Well-made but repetitive, occasionally confusing and monotonous', 'Very Positive', 90.42, 5.52, 2.12);
INSERT INTO reviews VALUES (7018, 461170, 187, 'Bucket Detective is a jarring game. It’ll make you laugh on occasion also, but the game is worlds better at priming queasiness and discomfort. Compared to the developers previous game (The Static Speaks My Name), Bucket Detective feels like a much more cohesive idea. Not just in length, but in story feeling and overall vibe.', 'There is really nothing much to offer here except pure shock value. the static speaks my name was an O.K. game for what it was, a creepy and mysterious walking simulator with a decent shocking twist in the end. Even though Bucket Detective offers some funny dark humor and interesting premise, its extremely short playtime, predictable ending and simple puzzles really don''t make the game feel like its worth its asking price. Even if this was free I would still consider the static speaks my name to', 'Very Positive', 87.70, 2.42, 1.35);
INSERT INTO reviews VALUES (7033, 461430, 3125, 'Smooth gameplay, large variety of rigs, although I would like to see this expand out of early access.', 'Development is dead, last update was a year ago and the dev isn''t active at all in the community. Do not buy this game, it will never get finished', 'Mixed', 65.92, 39.60, 7.90);
INSERT INTO reviews VALUES (7044, 461620, 575, 'I''ve been interesting in looking into Egyptian history and mythology lately and playing this game was part of riding that wave of interest.  As others have said it''s mostly a puzzle game which follows the history of Pre-Dynastic Egypt.  Historical accuracy seems quote notable, they clearly put a lot of effort into that side of the game which I very much appreciate.\n\nA single playthrough doesn''t take too long (mine was 4-5 hours) but you could replay to try and fare better.  I''m not sure how much', 'This game isn''t hard. It''s blatantly unfair. I''ve played the games from this developer for a long time and given their previous work, I shouldn''t be surprised. They have a track record of games with awful RNG BS. Play it only on the easiest difficulty and you may have some fun.', 'Very Positive', 86.26, 4.72, 197.48);
INSERT INTO reviews VALUES (7045, 461640, 437, 'The story of this game is really interesting - a world that has been cursed that if they commit any of the seven deadly sins they turn into demons.\r\n\r\nThe first act is very much building up the team, establishing the areas of the world, and levelling up. The second act is very heavy on character backstory and flashbacks, but with far more lore building. There is more content than I expected in this game, taking me about 9 hours to finish. One thing I like is after certain points in the main ques', 'Not Recommended', 'Very Positive', 83.98, 9.30, 3.27);
INSERT INTO reviews VALUES (7047, 461700, 303, 'I came here to have a beautiful romance with my succubus and i have had it, i''m a very happy lesbian', 'I''m partway through my first route (James) and was really enjoying the game... until the angels showed up. That in itself wasn''t too bad. Co-opting a little more religious imagery to flesh out the universe isn''t a bad thing, especially since "demons" and "angels" have basically become part of pop culture. Obviously these beings are no more related to Christian angels than the demons are to Christian demons (that is, not at all). That was my thought process, anyway, as I continued to play the sto', 'Very Positive', 94.72, 2.23, 4.47);
INSERT INTO reviews VALUES (7055, 461840, 985, '\r\nGood relaxing puzzle game.\r\n', 'I had wishlisted Zenge expecting an imaginative, challenging puzzle game, but what I got was a tedious, boring, pointless waste of time. I ground through all of the meh levels for the single completion Achievement & TC''s. Once finished, I could not uninstall it fast enough LOL. The irritation factor really surprised me, since I''ve very much enjoyed other games by this same Dev, and the Trailer was deceptively appealing to me. Oh well - Cheers.', 'Very Positive', 93.10, 8.75, 3.73);
INSERT INTO reviews VALUES (7058, 461870, 1760, 'i absolutely love the game but today i got a new laptop and my game wont start', 'DO NOT BUY - IT IS ABANDONED. THE COMPANY CLOSED DOWN - THERE ARE A LOT OF BUGS AND MISSING CONTENT', 'Mixed', 48.69, 61.55, 26.02);
INSERT INTO reviews VALUES (7060, 461890, 128, 'NORTH is a very loud exploration game where you must brave unknown territory as a refugee coming from the south. Far from home, you find yourself in a new land that threatens the little control you already had. In NORTH, you are the outsider wandering through an "outsider" world. Is it good, bad, or neither? It''s hard to tell, but the thought of forced bureaucracy sends a chill down your spine regardless.', 'Feels 15 plus years dated and where is the menu screen? Why does hitting ''Enter'' reset the entire game? Another undeveloped game piled onto Steam. This is the last time I buy a game out of impulse and a geniune want to be pleasantly surprised. Bought this because of the reviews, people please raise the bar for entertainment. This is a turd.', 'Mixed', 67.97, 3.60, 0.20);
INSERT INTO reviews VALUES (7061, 461950, 1124, 'My wife said if this review gets 50 likes and 5 awards, she will buy a case of beer, guys help me out.\n', 'Has a lot of elements which are normally automatic gold stars from me, but I never got hooked. I like the graphics, the nature of the homage to old cop shows, but the humor never landed for me, aspects of the gameplay were tedious (ranging from tediously easy to, out of nowhere, tediously hard), and I started to lose interest fast. Solid effort but I don''t feel the urge to finish it.', 'Mostly Positive', 71.00, 9.08, 3.57);
INSERT INTO reviews VALUES (7066, 462100, 187, 'Great game with great difficulty. \r\nThe scenery gets awesome as you progress.', 'Turned into vaporware, do not invest.', 'Mostly Positive', 71.66, 12.40, 0.40);
INSERT INTO reviews VALUES (7086, 462680, 346, 'Everything in life needs balance.\nThe same applies to this city.\n\n\n삶에는 균형이 필요합니다. 이 도시도 마찬가지고요.', 'TITS\r\n', 'Very Positive', 80.35, 5.18, 9.88);
INSERT INTO reviews VALUES (7089, 462770, 5375, 'I''ve been putting off reviewing this game for far too long.\n\nIn 2017 I was at one of my lowest I had ever been mentally, even games I enjoyed couldn''t keep my attention or fill me with and kind of emotional response, and I felt like my options and reasons to be around were dwindling. At some point my brother mentioned a game he got but hadn''t really tried and for some reason I decided to download it and see if it could do something for me. 9 hours later I was crying and ready for a second play t', 'Fine art and presentation and there''s a semblance of interesting world building and story but... the gameplay itself is just not that interesting or entertaining to engage in.\n\nWhat a shame.', 'Very Positive', 90.23, 41.03, 7.98);
INSERT INTO reviews VALUES (7090, 462780, 3706, 'The game is really fun, but those laser beams puzzles were diabolical, specially navigating the end of the game.\n\nThe dev in charge of those is not seeing heaven´s gates.', 'The devs have indicated it works on the Steam Deck. Independent fact checkers have determined this to be a lie. In all seriousness, it''s super wonky and crashes constantly, which is a bummer.', 'Very Positive', 86.13, 25.90, 0.33);
INSERT INTO reviews VALUES (7094, 462930, 102, 'In Communist Russia, money buys You!', 'Please close your studio...', 'Mixed', 61.76, 16.43, 11.35);
INSERT INTO reviews VALUES (7095, 462940, 150, 'love your game im playng more as an amature novice stratagist fan of the genere hoping your game is impactful to fans and thay like the game and make it beter and continew to grow we are die hard fans for life thank you.', 'It is basically a reskin not gonna lie.', 'Mostly Positive', 79.33, 7.52, 3.97);
INSERT INTO reviews VALUES (7096, 462960, 152, 'Can''t wait for Caveman World: Mountains of Unga Boonga 2!!!', '\r\nPRO TIP: You''re smarter than cavemen\r\n', 'Mostly Positive', 70.39, 1.82, 3.67);
INSERT INTO reviews VALUES (7100, 463030, 205, 'This game should have been called The Walk, The LONG Slooooow Walk. It''s very pretty but soooo tedious mainly because you walk sooooo slow, the only time you walk faster is when you walk into those little colorful lights, I guess there are achievements but tbh I didn''t care to try and search them out because of how sloooooow you walk.  I''m giving it a positive because it was cheap and pretty, kinda like me. ;-)', 'Not recommended.', 'Mixed', 63.41, 0.67, 3.38);
INSERT INTO reviews VALUES (7104, 463110, 129, 'Farnham Fables\n\nHas a total of 5 trading cards.', 'This game contains some very questionable content, including some kinks that are downright disturbing. It involves unclothed lizard-like anthropomorphic-humanoid creatures that seem to resemble a "lesser" civilization, including a male figure, children, and a mother, all of whom are sexualized one way or another.\n\nSome interactions, such as a character being pleased that a child refuses to wear clothes, kissing them on the lips, and doing so in the presence of the mother is difficult to ignore. ', 'Mostly Positive', 72.09, 1.35, 3.18);
INSERT INTO reviews VALUES (7108, 463150, 268, '\nInstead of coffee you have this game. Somehow it keeps you on for a while.\n', 'While I enjoy the aesthetic and style of the game (arcadey/difficult), I found that BARRIER X''s gameplay felt more rushed rather than fast-paced.  The goal seems to be to leave you with a sense of panic, as it doesn''t take the time to teach you the mechanics as some similar games like Race the Sun do.  Even taking a moment to read the tutorial text will certainly end in your death.\n\nTechnically the game ran fine, except there''s no frame limiter or vsync so the game was also rendering at thousand', 'Very Positive', 80.22, 3.70, 3.98);
INSERT INTO reviews VALUES (7110, 463170, 136, 'A fun stealth-based spin-off.\n\nThe game''s store page says it''s a spin-off so I don''t get the complaints about it not being Jagged Alliance 2.\n\nIt has some jank but it''s a fun stealth-based spin-off, I do agree it sucks that the early game is locked to only 2 mercs. (Though you can eventually get 2 more mercs.)', 'This is a straightforward turn-based tactics game with a Jagged Alliance theme.  Various characters are taken from JA2, including the half-dozen playable mercenaries, but there are few similarities beyond that point.  The game features a series of fixed battles, presented as locations on a world map that is mostly linear.\n\nThe combat is generally good, but the enemy behavior is quirky.  Enemy sight cones are shown but don''t always seem to work the same way.  For example, I had two characters nex', 'Mixed', 58.09, 68.52, 2.45);
INSERT INTO reviews VALUES (7112, 463210, 295, 'i miss my school', 'Not Recommended', 'Very Positive', 81.36, 4.53, 3.52);
INSERT INTO reviews VALUES (7113, 463220, 165, 'Dungeon of Zolthan\n\nHas a total of 5 trading cards.', 'they have gun in this game', 'Mostly Positive', 71.52, 0.83, 4.55);
INSERT INTO reviews VALUES (7115, 463270, 781, 'I didn''t like it straight away, but then I was hooked. It''s a great game, with lots of nerdy humor.', 'hideous, appeals to me on no front whatsoever.', 'Very Positive', 87.84, 13.55, 0.27);
INSERT INTO reviews VALUES (7116, 463290, 107, 'I love Kismet but it doesn''t work with my Quest2 like it did with my Rift CV-1! FIX PLEASE! MUCH SADDNESS!', 'excellent concept, terrible value - tarot card readings last about 15 seconds, and the horoscope was only slightly better with like a 1-2 sentence blurb... if you''re not interested in the minigames you''ll be done within 2 minutes. \n\nthe fortunes are so weak since there''s no questions for you to answer or any other way to feel like the experience was customized, and the explanation of the cards and their meanings are virtually nonexistent.\n\nthis was after being frustrated by having to figure out ', 'Very Positive', 93.46, 0.97, 1.52);
INSERT INTO reviews VALUES (7118, 463350, 254, 'It''s a very bare-bones RPG maker game. There is no nudity or adult ccontent. The girls on the cover makes no appearance or relevance to the game.\nBut it''s not a bad deal for a perfect game in about 6 hours.', 'why do i buy these RPG makers?', 'Mostly Positive', 72.05, 6.78, 3.23);
INSERT INTO reviews VALUES (7136, 463850, 261, 'you a real one if you know bout this game', 'hell naw :rofl:', 'Very Positive', 84.29, 1.65, 0.12);
INSERT INTO reviews VALUES (7141, 463930, 222, 'The game may not be a high budget masterpiece, it might look like it came from a 48 hours game jam, but it is a legitimate game. There''s a lot of text-based lore if you''re into that of the "found diary" variety. The first few levels feel like a prototype but after level 5 or so they''re actually decent puzzles.\n\nYep: this reverse horror, monster simulator is in fact a puzzle game. It solves the issue of being an invincible creature by putting the challenge in puzzles. Most games become boring whe', 'Tip: press 6 many times and refund', 'Overwhelmingly Positive', 97.30, 5.42, 14.15);
INSERT INTO reviews VALUES (7143, 463980, 323, 'Just about what I expected, which is good. I like these simple solitaire games with the option to think strategy a bit more, if you want to. The resolutions suck, and it takes exclusive control even when windowed. Other than that, I''ve had no problems.', 'Really wouldn''t recommend. Every fight I''ve done as the default, the runs are all the same. There''s no depth to the gameplay, it''s entirely RNG-based. Sure you can try and find combos, but once you have a few of the same number it''s easy to look for that pattern again.\n\nIt''s kinda neat, but it seems like a tech demo. No meat on the bones of this game. Combat exists, but there''s really no gameplay for you except match numbers, cast spells. Oh and you buy stuff sometimes. No trees, no branching an', 'Mostly Positive', 78.02, 16.97, 1.70);
INSERT INTO reviews VALUES (7148, 464060, 4402, 'Ruiner is one of those rare pieces of media that elevates its mediocre substance with striking style and atmosphere. The core gameplay is something that could''ve been done on a SNES and is nothing to write home about. However the environments, cutscenes, cartoon talking heads, soundtrack, and special effects really come together to create something special. The soundtrack especially stands out for me, combining tribal drums and chanting with dreamy, low-tempo beats for a unique atmosphere that s', 'unable to run it on the deck. it crashes the whole machine. Tried the linux native version and proton version with the same result. Do not buy it if you intend to play on deck.', 'Very Positive', 90.53, 11.80, 0.17);
INSERT INTO reviews VALUES (7151, 464100, 104, 'It took me quite a while to ''get'' it. I started the game a few times but could never get far into the campaign. This time I''m actually getting further into the campaign. Feels like a good mix of Xcom and strategy. Some of the missions do feel very difficult though, and I find myself delaying doing the missions so that I can squeeze out a bit more research first.', 'A recycled mobile game, which makes it a very shitty PC game.', 'Mixed', 60.58, 10.40, 0.83);
INSERT INTO reviews VALUES (7154, 464150, 290, '"Regalia" is the perfect fusion of a - really interesting, and charming! - storyline in visual novel style, and a decent tactical RPG with lots of customization options and things to do. Within the game, you build buildings, upgrade them, get into deeper and deeper friendshio/relationship with a ton (!) of characters, craft or buy items, and upgrade your characters within a kind of board, where you choose the skills you unlock with all those other stuff. The game challenges you with so called ki', 'This game does have many fun things. I enjoy the art and especially the combat and lots of the character interactions are very fun. However, the humour unfortunately relies on stereotypes a lot, which is not only ethically a problem but also boring. What frustrated me the most was when you fail to fulfill the requirements for a chapter, instead of offering you a clean restart it''s just game over and you have to make sure you have a save you want to get back to. And that''s the thing: even if you ', 'Mostly Positive', 75.52, 7.95, 29.82);
INSERT INTO reviews VALUES (7158, 464260, 111, 'Xenocrisis is an action packed twin stick arena shooter heavily inspired by Smash TV and 90''s Sci-Fi movies.  The pixel art is absolutely fantastic.  I love the retro gameplay and fun boss fights.  This game clearly understands what it''s influences are, and why they were great, and mashes them all up into a fun little package.  The problem is that with the low rez pixelated graphics enemy projectiles often blend into the background.  Overall, the difficulty is moderate and fun.  However, it is b', 'you can''t use your mouse to aim... 6 way directional aim to be like snes, but somehow smash tv is infinitely easier than this game. you get 100 bullets max in your default gun which is about 10 seconds of shooting and your melee attack is barely longer than your hitbox. not super enjoyable', 'Mostly Positive', 79.28, 0.53, 0.12);
INSERT INTO reviews VALUES (7159, 464340, 1012, 'Epic third part. Downside is the inability to save the progress by  hand, it''s autosave in this game. Also the conversations with the characters cannot be interrupted.', 'sure wish the controls weren''t like #that', 'Mixed', 45.26, 26.85, 6.07);
INSERT INTO reviews VALUES (7160, 464350, 1164, 'I really like this game, but what I don''t like is the number of people using open source pre-programmed sources. There''s no real way to avoid it, it just sucks.', 'Background: I''ve been a frontend engineer for 10 years, so I''m pretty good at JS\n\nYou''re supposed to have noob protection for a while so you can learn how to play the game. However, my single room was wiped out by a guy who already had 4 rooms and "needed" my room only a couple days into playing the game. The game runs too slow to understand if your code is working as expected. There is a massive difficulty jump when you exit the tutorial and start playing the game. If you don''t know JS already,', 'Very Positive', 87.71, 550.83, 12.73);
INSERT INTO reviews VALUES (7161, 464360, 897, '3030 Deathwar Redux - A Space Odyssey is a jack of all trades title but master of none, except atmosphere. The atmosphere is absolutely phenomenal. For example, as you look through the trade screen within a station, little bugs usually cross the screen, which you can crush with your mouse pointer. Sometimes a lizard crosses the screen too, as if it''s going after its next meal. This has almost no effect on gameplay but are just there to set the scene. Before docking at a station, you need to hail', '7.50 CHF is worth the game but not more the music, better say the songs are annoying s*** cant stand the voices of the singers. Explanation about what you do and why is like you read book with some zero interactivity. Games is mediocre and nothing special, but ONE BIG THUMBS UP is the design and graphic art in the station hahaha is like some one vomited ........', 'Very Positive', 94.54, 16.92, 1.23);
INSERT INTO reviews VALUES (7165, 464450, 397, 'its crazy that the laser wheel section has a free game attached to it', 'I came for the chicks but left with a broken controller.', 'Very Positive', 94.96, 13.02, 4.02);
INSERT INTO reviews VALUES (7171, 464620, 384, 'Siralim 2 is a creature collector dungeon crawler roguelite, like the first game but with a bit more direction. Instead of aimless dungeon diving, you get a boss fight every 5 or so levels with a bit of story, like about as much of a story Borderlands 1 had, but that enough to keep me interest till the need to power griding appears. The UI is improved, Getting monsters no longer need 3 cores, but just one. Every shop/person of interest is on one floor, easy to find. In my 7 hours of playing, I s', 'Another part of the Silarim serie - monster collecting and RPG with rich mechanics and complexity.\r\n\r\nobviously the game was further and further developed each title - coming from Silarim 1 there is lot of upgrades and gods are good Idea. There is even story but very very simplified and writing is quite meh.. so as to previous title I do not recommend play Silarim 2  - no reason grind too much in it over successor titles and story wise it bring very little to the table (though overall it was add', 'Very Positive', 93.49, 7.60, 45.55);
INSERT INTO reviews VALUES (7180, 464850, 250, 'I have played this game for 3 hours almost straight. I have the Xbox One version as well. There were few issues in the xbox version but let me tell with a big smile, most of them are sorted out for the PC release. This is fantastic and the game is fantastic. There are more stats that pop up like RRR, RR how many runs needed to win, projected score now while playing. This was something users demanded and let me tell you on BigAntStudios listens as a developers. Few shots were missing but now thos', 'Just buy cricket 22 for the same price', 'Mixed', 60.80, 34.80, 24.50);
INSERT INTO reviews VALUES (7181, 464880, 571, 'Good, relatively simple 4x, relaxing, fun to play.\r\nForce of "one more turn" is strong with this one.\r\nRecommended.\r\n', 'It''s a stub of a game. Tech demo. Unfinished. Technically a game - yes, actually a fun game - NO. Should be 1$ or free.', 'Mostly Positive', 77.58, 136.33, 390.65);
INSERT INTO reviews VALUES (7183, 464920, 9759, '\r\nFor me this is the best Mars colony building sim. Plenty of structures, everything is well made and engage grey cells. This is kind of strategy that you will hold to for a while and think about how to improve on your last gameplay. Strongly recommended.\r\n', 'There''s a lot to like here, but there are some serious balancing issues with some of the breakthroughs that completely trivialize entire game mechanics.  The "AI" for the bots and colonists is poorly coded, and constantly does nonsensical things.  You''ll spend almost as much time figuring out how to work around the AI quirks as taming the environment.  Terraforming the planet (if you get the DLC) feels really good, but takes so long you start to lose interest.\n\nThe much bigger problem with this ', 'Very Positive', 84.14, 6.58, 268.07);
INSERT INTO reviews VALUES (7189, 465020, 160, 'This game absolutely whips the lama''s ass\n\nupd: gets kinda boring cutting through bunches of enemies at higher levels in the story and has some bad spots in game design, but overall the setting works well and the game is interesting!', 'I had the decision between a donut and epilepsy. I chose epilepsy.\n\nHere is what happened: Started the game, did the first mission - all fine. Second mission: Ship emits a HUGE and fast explosion of light whenever I fire a shot. Cool, damages all enemies on screen. Not cool: Makes the game literally unplayable because of how hard it is on the eyes. Like, even if you are not sensitive to epilepsy, this will make you feel uncomfortable very quickly, and there is no way to turn it off.\n\nPlease don''', 'Very Positive', 94.38, 24.52, 0.37);
INSERT INTO reviews VALUES (7194, 465100, 353, 'I’ve returned here after several years to leave a positive review. I’ve been following the game since its Kickstarter days, eagerly awaiting its release, and was thrilled when it finally launched. This is an outstanding quest that won’t leave anyone indifferent.', 'The puzzles in this game are very easy, and it purposefully makes you move slowly. I tried to get into that, to feel the vibe, but I never could make it. The cut scenes were very long, especially at the end. If you''re a fan of puzzle games, like Myst, I''d skip this one. If you like little cartoons that try to tug at your heart strings and you want an easy challenge, give it a try. It wasn''t for me.', 'Very Positive', 87.54, 3.95, 3.50);
INSERT INTO reviews VALUES (7197, 465170, 110, 'A Hidden Object game with some crime scene investigation mechanics which are, well, hidden object clicking and a logic puzzle in one. The game is very easy and it is a short game on top. Graphics and sound are fine by Publisher standards, but the story lacks the crime feeling as you never feel frightened or cautious. That is mainly due to the investigator lady you play, who always walks straight into any danger without any second thought. Anyway, I had my little fun with the game and thus give a', 'This game is not good but it was fun because of how stupid it was. I was giggling the whole time I was playing and I wasn''t too mad about the mountain of issues because I got this game on a big sale. It is definetly not worth the full price. It is absolutely ridiculous. And not in a good way\n\nTranslation errors, weird plot and a rushed ending. Characters appear just to die so you don''t care about any of them. A guy is named Weekly come on that isn''t normal. The voice acting wasn''t good either bu', 'Mixed', 69.09, 3.20, 5.70);
INSERT INTO reviews VALUES (7200, 465200, 566, 'Bought it because the negative reviews were all "It''s not fair" "It''s too hard" and that''s exactly what I want.\n\nIt delivered.', 'It keeps resetting graphics and all that jazz each time I turn it on. Refunded.', 'Very Positive', 89.22, 6.20, 0.93);
INSERT INTO reviews VALUES (7201, 465240, 810, 'Honestly the best couple of bucks I''ve ever spent, for someone new to VR that just wants an over the top shooting experience without any risk of motion sickness this is very fun!\r\n\r\nOnly real downside is I wish there were a few more maps, and some of the weapons can be gimmicy/difficult to use like the laser sword, but those are exceptions rather than the rule, all of the other weapons are kick ass  and feel amazing to decimate hordes of enemies with them in VR', 'This game is a serious let down, no pun intended.  Just play the VR versions of the original games.', 'Very Positive', 83.70, 4.25, 1.87);
INSERT INTO reviews VALUES (7202, 465280, 153, 'I liked the story, but the gameplay did not play nice with MacOS''s hot corners.', 'This is another game where it''s over designed and the gameplay and actual user experience is terrible. They''ve let designers run amock with this one. Total waste of money. I wouldn''t take it and a dollar', 'Mostly Positive', 75.16, 15.05, 1.25);
INSERT INTO reviews VALUES (7207, 465490, 1082, 'For those who may shy away from this game due to the early access tag, you will be missing one of the best Sci-Fi RPG. This gem shines even without the full release, the game play is solid and always improving, the updates are steady (even with the Dev going through some hell), and the story is actually interesting. I actually wanted to know the motivations of characters, and sometimes found them out. Sometimes, however, I accidentally caught them in a grenade blast and never heard from them aga', 'Bought this a long time ago. Finally got around to giving it a go. Surprised to see it was still in Early Access after 7 years.\n\nTry to get past the tutorial. Can''t proceed past a door because there is some sort of bug. Search online and see that someone complained about the same thing 7 years ago. Still not fixed. \n\nUninstalled the game. If you can''t get your tutorial section of your early access game wired tight, what are you doing?', 'Very Positive', 81.15, 71.20, 4.20);
INSERT INTO reviews VALUES (7216, 465780, 474, 'Despite the frustratingly slow development progress, the pain of setting it up, the inaccuracies pointed out in other reviews, and the game certainly leaves me wanting a bit more... I still find myself coming back to it and haven''t once considered refunding. I feel a lot of the gaming, and especially VR community has become spoiled to expectations... but despite the bugs it''s solid. Playable roms, customizable cabinets, upload your own movies, etc. It''s a long ways from being perfect but until s', 'Just asked for a refund, would be ok if it is free, but there are too many quirks and workarounds you have to do to even make it playable, not acceptable for a product that you pay for.\n\nOn quest 3, controller is not recoginze, you have some weird HTC vive controller que weirder control scheme.\nWhen trying to play the games, connected xbox controller does nothing, trying to configure controller does nothing, literal nothing I click on the button mapping to change > awaits input > I press the des', 'Mostly Positive', 78.27, 5.17, 0.62);
INSERT INTO reviews VALUES (7236, 466110, 432, 'shaw brothers meets Golden Harvest meets grindhouse theater  movies of the  70s . Excellent game.', 'Hate to say it, but I''m as disappointed with this game as I was when I tried Kings of Kung Fu at a friend''s house. This spiritual successor isn''t very much improved from the last game at all. I recommend if you really want to emulate how the different styles of fighting feel, try looking at something like Tekken and figure out how to do something closer to that. I can''t recommend this in its current state, even to someone who really loves Kung Fu movies.', 'Very Positive', 93.98, 6.55, 0.28);
INSERT INTO reviews VALUES (7237, 466130, 454, 'White Day: A Labyrinth Named School is a remake of the renowned 2001 original in which we find ourselves in the shoes of a boy who is trying to deliver the diary and his love that his classmate So-Young Han wants, but in order to achieve this goal he will have to face the horrors that are to be found in his school at night. \n\nThe game is centred on a variety of puzzles that require reading notes and paying attention to how to solve them, as well as keeping an eye on surviving the maniacal careta', 'Another review said it perfectly. "This game isn''t scary, it''s annoying." \n\nThe characters are bad, plot is bad, and you''ll spend more time hiding than doing anything, not because you''re scared, but because you have to wait for enemies to leave so you can go and do any objectives without being harassed and killed. \n\n100% not worth any purchase, let alone the full price tag of $30.', 'Mostly Positive', 77.75, 40.90, 1.78);
INSERT INTO reviews VALUES (7241, 466240, 733, 'Haven''t played in years but still leagues better than whatever the sequel is doing.', 'Not worthy of 100 hours', 'Mixed', 67.94, 31.05, 128.82);
INSERT INTO reviews VALUES (7245, 466300, 2461, 'Disco Elysium is the best game you''ve ever played except maybe planescape: torment\nDisco Elysium is the best game I''ve ever played except maybe planescape: torment\nYou will never stop talking about planescape: torment or disco elysium\nI will never stop talking about planescape: torment or disco elysium', 'Get ready for more text than a Shakespearean play, except instead of poetic prose, you get dragged into conversations longer than your last family reunion.\nEver wanted to feel like you''re slowly poking enemies to death with a toothpick? Well, look no further because the combat in Planescape: Torment will have you questioning if your character forgot to bring their weapon to the fight.\nIf you enjoy being confused, disoriented, and questioning your sanity, then this game''s convoluted storyline wil', 'Very Positive', 94.51, 45.13, 9.82);
INSERT INTO reviews VALUES (7251, 466500, 891, 'A melancholic and reflective walk through pandemic-ravaged Russia. Reminiscent of the S.T.A.L.K.E.R. and Metro series.', 'Kinda Disappointing', 'Mixed', 57.13, 9.40, 7.23);
INSERT INTO reviews VALUES (7253, 466560, 21996, 'amazing game, the only downside, i hate games where i need to buy DLC, i mean a LOT of DLC to be able to experience every part of the game. pay for unlocking clans?... really?', 'Well... Good game, bad pricing policy.\r\n\r\n6 Base clans , 14 DLC Clans, each a Microtransaction for 1/6 of the games whole worth. I would like to get more clans, but this is ridiculous. Any game that thinks this is fine deservers a straightup downvote.', 'Very Positive', 85.36, 57.75, 133.88);
INSERT INTO reviews VALUES (7255, 466630, 2372, 'A puzzle beautifully woven into everyday life, framed by the signposts of a concrete jungle.\n\n\n일상을 배경으로 명징하게 직조해낸 퍼즐.', 'inexcusable to release a game in this age WITHOUT A WAY TO MUTE THE MUSIC. on the minimum volume the music is still too loud and if i mute it i cant hear anything else in the game. atrocious.', 'Overwhelmingly Positive', 96.33, 6.27, 0.35);
INSERT INTO reviews VALUES (7259, 466740, 190, 'What an amazing game and and Intense experience and good story too, 1 very frustrating Level but that was about it', 'The gameplay is so bad it gave me an headache you can''t even run over a fucking chair that just move by itself? I mean wtf why a game that just released in 2016 has a gameplay like this? even a game from a past few years had a lot better I can tell you that. BTW I think a lot of Thai people recommended this game  for what reason I don''t know myself cuz I''m from Thailand too and I had play horror game quit a lot too all I can say is this game is not worth it if you want to try this game wait unti', 'Mostly Positive', 74.74, 5.67, 0.55);
INSERT INTO reviews VALUES (7262, 466800, 156, 'Fun game - gets boring and easy having to unlock all the time frames. Would make way more sense to just let you keep on playing instead of the game over and restarting. I am 5 hours in only just completed the 90 day session now back to the start for the 180 day session, next 360 days then open play. Doubt ill be bothered making it to the open play version.', 'Meh thought it would have some comedic value but was pretty boring.', 'Very Positive', 82.05, 13.98, 5.02);
INSERT INTO reviews VALUES (7265, 466840, 100, ' ᠌᠌ ᠌ ᠌ ᠌ ᠌ ᠌᠌ ᠌ ᠌ ᠌', '\r\nIt''s one of those games that take space in your library.\r\n', 'Mixed', 59.00, 4.75, 3.88);
INSERT INTO reviews VALUES (7267, 466870, 132, 'Skyrim skill interface in 2D, except that instead of increasing health, magicka or stamina you get some nice achievements. Plus, you get to learn a thing or two about the history and features of some of the most prominent constellations of the northern night sky. I like.', 'Found this in my library and was wondering why I only played it a couple of minutes, but playing it again. There really is no challenge or gameplay to this game. You just click dots and the game even tells you which one to click on next. The encyclopedia is rather nice, but doesn''t have a lot of information about the constellation in question. There aren''t any basics regarding astronomy or stargazing either. If you want a game: This is not it. If you want to learn about the night sky: This isn''t', 'Very Positive', 84.85, 0.67, 0.22);
INSERT INTO reviews VALUES (7272, 466940, 199, 'good game just a little small', 'Has had a bug for years that makes the game unplayable on modern systems. Do not buy.', 'Mixed', 53.27, 6.55, 15.23);
INSERT INTO reviews VALUES (7295, 467520, 276, 'cood', 'Charging 50 dollars for this broken ahh game is WILD.', 'Mixed', 46.38, 125.95, 17.60);
INSERT INTO reviews VALUES (7298, 467660, 509, 'I couldn''t play this for the longest time because the game didn''t support the quest 2. I decided to try again, and now am able to enjoy it. It is a very very good horror game. Great for seeing your friends shake as they try to enter rooms. Recommended!', 'i might be fun, it might not. idk. i have the quest 2 and the controls are so bad i cannot get through the main menu/tutorial. idk how anyone could design this game and release it in good faith knowing it doesnt work. i requested a refund. just do not buy this game.', 'Mixed', 69.55, 2.83, 0.20);
INSERT INTO reviews VALUES (7302, 467760, 132, 'trappers delight is my life i have never before played a game unlike trappers delight if jesus had made this game i couldnt be less suprised. this game has changed my life and has gotten me off drugs and has made me a top 10 billionare all over the world. this game is truly something i have never seen before and because of this I have been playing trappers delight for the past 14 years 10 months 3 weeks 5 days 2 hours and every minute of my pathetic life i love this game so much i would sacrific', 'Dead community.  If you want to play, you''re gonna have to have friends to play with.  Unfortunately, being the shut-in that I am, those are in somewhat short supply for me, so I couldn''t really do much in-game.', 'Very Positive', 93.18, 3.58, 0.98);
INSERT INTO reviews VALUES (7306, 467820, 212, '10/10 10/10 10/10 10/10 10/10 Just don''t play for too long or you may vomit but still 10/10', 'The concept is good and the gameplay is decent enought but unfortunately this game is dead right now. You should only consider buying it if you have at least 3 friends to play with you.', 'Very Positive', 89.15, 1.00, 2.48);
INSERT INTO reviews VALUES (7311, 467930, 178, 'I am a simple gamer. I like bouncy boobs, and blowing things up. This game is cheap and has both. I have it on my Androids too, which I was also happy to pay for. So there.', 'super simple and not interesting', 'Mostly Positive', 79.21, 1.30, 1.37);
INSERT INTO reviews VALUES (7314, 467960, 231, 'how to survive from NATO sponsor genocide', 'Neat idea but an absolute chore to play, and very buggy. I was awarded the ''beat the game'' achievement when i first loaded the game, and this bug has existed since 2020 (if not earlier, per the forum here).', 'Mixed', 53.25, 17.60, 0.38);
INSERT INTO reviews VALUES (7315, 468050, 103, 'Point and click game with the illusion of choice. The dialogue changes and some events depending on choice but overall outcome is always the same. I guess it can''t really work any other way though and it is well done for the most part. A short experience.', 'my eyes!', 'Very Positive', 94.17, 1.38, 0.08);
INSERT INTO reviews VALUES (7329, 468490, 125, 'Good Game !', '\nYou can skip on that, trust me.\n', 'Mixed', 65.60, 2.42, 18.17);
INSERT INTO reviews VALUES (7339, 468820, 136, 'Just came back from there... It is full of stars...\n\nI have previous version from Oculus store and hesitated a bit to get this one as the previous version was big too.. Simple... Wait.. I just realized this is the same version.. or not... hm.. whatever, author deserve my Euros.. :-)\n\nThis one? It is a must for every parent that likes his kid to understand the space. (which should be every parent with VR tbh)\n\nI love universe and this is so far the best representation of planets in VR so far. Not', 'This was very impressive when it was first released for the oculus rift devkit. But there has been no real improvement since then AND the controls for the vive are absolutely horrible. \nBack then it was great really great for its time- but now the whole experience is just a mess. \nIt''s very hard for me to press No on this one because I really loved the game on the DK2 but now I''m just disappointed. \n', 'Very Positive', 93.38, 0.63, 0.52);
INSERT INTO reviews VALUES (7343, 469600, 5801, 'I bought this game last week during the steam summer sale and I think it''s pretty good if you like Auto Chess adjacent stuff please help oh god I bought so much other stuff and instead I''m just playing this?', 'Awesome game, I''ve had plenty of hours of fun, However i will never be playing it again due to fairplay banning me for 3 months because i went afk for 2 rounds due to my dog breaking a nail in the middle of a match and needed bandaged up, Awesome thanks guys.', 'Very Positive', 87.61, 34.25, 1014.40);
INSERT INTO reviews VALUES (7344, 469610, 1773, 'It''s the guy from Fortnite', 'When I saw Jacksepticeye play this back in 2017 I always wanted to try it, but now after i finished it in less than 2 hours, it doesn''t seem all that fun anymore. Overpriced as hell with not much replayability.', 'Mostly Positive', 73.77, 4.50, 1.75);
INSERT INTO reviews VALUES (7346, 469720, 368, 'This game is a hidden gem. While the grafics are basic the mechanics work wonderful and are balanced very well. You loot a certain armorpiece or weapon and you can pass a situation elsewhere on the map you been not able to so far. So you improve step by step without ever feel too powerful at a certain point of the game. The challenge always keeps up. \n\nI wish more modern looking games would have such a depht and balance nowadays. This gem didnt fall to greed and is produced with a solid aim. Ple', 'Digital tedium.\r\n\r\nProbably one of the worst dungeon crawlers I''ve played - from a party customization perspective (5 classes with 2 subclass options each), information available to player (if I fight an enemy once, why can''t I learn what abilities are available to it?), and just a pure grind perspective. It''s solely intended for a massive grind - multiple factions reps and items to collect, multiple parties to manage (which are generally pointless, since there''s very few variations on a party y', 'Very Positive', 85.60, 86.15, 6.10);
INSERT INTO reviews VALUES (7347, 469730, 254, 'I Will Eat 1 Tablespoon of Mayonnaise For Every Like this review gets.', 'Not Recommended', 'Very Positive', 89.76, 4.53, 3.52);
INSERT INTO reviews VALUES (7348, 469790, 418, 'Red was friend all along!?', 'A good game that won''t let me complete it. Will update my review if all the softlock bugs are fixed.', 'Overwhelmingly Positive', 96.65, 2.27, 1.42);
INSERT INTO reviews VALUES (7349, 469800, 224, 'Definitely a good way to learn how to play the game. The only downside is the game does occasionally cheat. It''s not super noticeable, but most games one of the AI players will somehow have more cards to play (easy enough to tell on the first round when everyone should have the same combined number for species, body size, and traits and there is a 2-4 point difference).\n\nSo, just be prepared to play at a disadvantage in AI games.', 'The board game is great, and this adaptation does it justice... BUT, the game has some error in the code that causes the AI to randomly not take its turn which effectively freezes the game. I''ve tried verifying the cache and reinstalling it, but this bug keeps popping back up. If the devs can fix this, I''ll change my review to a thumbs up.', 'Very Positive', 84.38, 222.07, 23.23);
INSERT INTO reviews VALUES (7350, 469820, 4689, 'Beautiful story, made me cry. 100/10', 'Why does this exist?', 'Very Positive', 92.07, 2.15, 0.37);
INSERT INTO reviews VALUES (7353, 469920, 648, 'There''s no better time to hop on the game than NOW, the game was overhauled with an all new tutorial update, definetly recommend checking it out now as it''s a way better introduction to the game!\n------------\nAmazing game, although sadly a bit dead MMO aspect, because a lot of people moved to chatting on Discord instead of using in-games public chat. However that doesn''t kill the vibe and just how much interesting exploration this game has. The tutorial at the start of the game is a bit long and', 'Late by one day to keep my users from retiring/being deleted.. \nDoesn''t feel good. Guess I was done playing, anyway.', 'Mostly Positive', 79.94, 14.07, 110.12);
INSERT INTO reviews VALUES (7366, 470220, 25006, 'this game has pulled my family apart. I am currently mid divorce and my kids wont see me.  But I cant stop winning.', 'For something as simple as UNO I have no idea how Ubi have managed to make it so unstable and buggy. Getting rooms setup with friends and invites is a mess that only works 50% of the time. Crashes frequently, avoid this and just play UNO in Tabletop Sim, at least it''ll work..', 'Mostly Positive', 72.08, 21.33, 2.03);
INSERT INTO reviews VALUES (7367, 470260, 1118, 'Event is that type of game where you put on your detective hat, explore, and probe at a janky chatbot. It has a coherent, story, message & general atmosphere. Games like this inspire me!', 'The concept of this idea is neat, but the AI is too dumb to carry it. More often than not the response it gives has nothing to do with your request. And seeing as interaction with the AI is pretty much the game, the frustration mounts quickly.', 'Mostly Positive', 77.46, 4.72, 1.37);
INSERT INTO reviews VALUES (7371, 470310, 3118, 'weird korean game featuring new xcom style battles mixed with every sort of rpg mechanic ever devised by man and guys who worship spoons, muscular women, and the devs have a guy who responds to every single review posted, enduring the endless cavalcade of nonsensical waifu recommendations', 'I am about 15 hours into the game. I really really like the anime xcom, I even lovingly call it Squid Game Tactics when I speak about it. There''s just so many casual quests, farms, repeatable missions you have to go through. It''s the worst part of a Korean grindfest MMO in a single player (mostly) SRPG.\r\n\r\nStarting around the lvl13-15 missions, map sizes, enemy numbers, and naturally, enemy turn timers increase exponentially. It becomes a slog through an enemy swamp. It becomes more annoying whe', 'Very Positive', 93.49, 83.40, 20.75);
INSERT INTO reviews VALUES (7383, 471010, 592, 'Nov/2024 review after every update and the DLC: Solid 8/10 game with absolutely unique feel and impressive production values, but somewhat simplistic combat and imbalanced pacing of powering up.\r\n\r\nIt plays as an isometric AC in some ways, as the map is highly vertical, your character is capable of climbing much more than you''d think at first, there is a disguise system, full stealth, stealth killing, and open combat. The scenario is sort of post-apoc, sort of cyberpunk, sort of steampunk. The v', 'TLDR:  A very frustrating game to play.  The isometric camera is fine until it interacts with the bad level design.  Everything about the game feels shallow and uninspired.  The stealth is shallow, the action is shallow, the crafting is shallow, the ''RPG'' is shallow.  The story is very poorly done and they failed to make me care about any of it.\n\nYou''re a thief who teams up with an AI to find a government agent who disappeared while looking for an Ark that is important to the Emperor.... Okay.  ', 'Mostly Positive', 75.17, 57.77, 8.57);
INSERT INTO reviews VALUES (7388, 471330, 184, ' Detailed and Positive Review of "Versus Squad" \n\n  Developer: DiezelPower\nGenre: Action, Strategy, Online Multiplayer\nPlatforms: PC (Steam)\n\n"Versus Squad" is a game that combines elements of fast-paced action, real-time strategy, and teamwork, creating an engaging and highly competitive multiplayer experience. Developed by DiezelPower, the game stands out for its unique approach to the online battle genre, offering a mix of mechanics that require both individual skill and team coordination.\n\nG', 'Nation Red is one of my all time favorite top down shooters with almost 200 hours played and 100% achieves.\n\nVersus Squad is a case study in how to take one game (Nation Red), strip out all the fun elements of the original, and release it under a different title. Thankfully, this was peddled as a separate product instead of an "update" to Nation Red, so they didn''t ruin the original experience.\n\nVersus Squad is hot garbage in comparison.', 'Mostly Positive', 79.89, 1.63, 5.93);
INSERT INTO reviews VALUES (7391, 471550, 1294, 'perfect game for a chill session with friends (with lots of replayability too!)\r\ncan just throw them a controller and everyone will be able to pick up right away. no learning/teaching needed which is great for when your friends are too stupid to use technology! xD', 'Whoever FORCED this game to have friendly fire, deserves to chew rocks the rest of their life. That''s how it feels when you play a game with such huge abilities. I like the game, but had to return it cause it''s impossible to play if your companion is constantly freezing, stunning, burning etc you all the time. Plus the 300 million jumping, chanrging and -anything you can think that will make you be stunned- enemies attacking you. Ah, and you can heal the enemies lmao. Terrible gameplay, beautifu', 'Mostly Positive', 78.59, 49.88, 2.17);
INSERT INTO reviews VALUES (7395, 471660, 666, '"Before the era of gaming these people did it for real\nNo controllers, riskin’ life and limb to get famous"\n\nTalib Kweli & Rakim - Getting Up Anthem: Part I', 'It''s strange, it needs an update for the version of unity it''s using, it bugged out and abandoned. Too bad...', 'Very Positive', 82.43, 0.97, 0.33);
INSERT INTO reviews VALUES (7401, 471810, 238, 'I lost my friends.', 'TERRIBLE controller support; incredibly buggy. Forum has major thread with many users struggling to coax controllers to work properly. Developer appears to have abandoned the game and its issues. BUYER BEWARE.', 'Very Positive', 88.66, 6.77, 1.25);
INSERT INTO reviews VALUES (7404, 472420, 119, 'I had a lot of fun playing this short little gem! Insanely good artwork made by point''n''click adventure legends, what''s not to like!\nI may be a bit biased though, since my first adventure game was Curse of Monkey Island, so I have a bit of a soft spot for pirate games :)\n\nDuke struck me as an odd choice for the main character, huge and very, very dumb. But, not to spoil too much, he develops more as you play, really growing on you in the end.\nMy favorite scene was the dancing people aboard the "', 'A very bad Monkey Island clone.', 'Very Positive', 85.71, 3.43, 4.17);
INSERT INTO reviews VALUES (7410, 472870, 529, 'Please remember to have the 07th expansion mod installed for the best experience playing.', 'I think Ryukishi writes the first half of Higurashi as some sort of cry for help. The man can clearly write engaging horror mystery and good characters but at this point he purposefully buries it under mountains of unsolicited, unhinged, and unnecessary filler bullshit and calling it anything more than that is an insult to writers who properly use downtime and slow-burns to a full effect.', 'Overwhelmingly Positive', 98.68, 10.73, 31.90);
INSERT INTO reviews VALUES (7422, 473560, 128, '1. buy game for 16 cents\n2. sell cards for 18 cents\n3. ???\n\nI know, I''m a true entrepreneur\n10/10 would profit again\n', 'Not Recommended', 'Mixed', 54.69, 4.53, 3.52);
INSERT INTO reviews VALUES (7425, 473690, 7270, 'Absolver had an unreal amount of potential, whats here is great.\nIts what the devs DIDNT do that upset me, all they had to do was release more pve content, add new zones, expansions, etc.\nThe devs simply stopped making content, its like they didnt understand why the game was liked to begin with.\n\nThe game is a Pvepvp setting, and it worked great\nThey just needed to ramp up the narrative, and continue writing, what a shame. It could have been so much more, the pvp was great too, sad.', 'Its not a bad game or anything, its just that half of the game''s content is reliant on online gameplay and you''ll hardly find anyone still playing. The next level bosses for example require you to level up from pvp, and matches are never found even after 30 minutes. Im sure this was fun when it first came out but i was recommended this game pretty late and now it jus feels like a barren and abandoned game.', 'Mostly Positive', 73.84, 7.97, 10.98);
INSERT INTO reviews VALUES (7428, 473770, 1718, 'Despite its age (6 years from release now), it is still supported by the developpers (public 1.4 version is on its way). You can''t say the same about the competition (I''m looking at you, Pacer ex-Formula Fusion).\nOf course, I''d be hyped by a game with modern visuals, maybe UE5, HD effects ... but that''s not the core of AG racing. BallisticNG is the best Wipeout experience I had since Omega Collection and Fury. \nOn top of that, the community is working hard to keep it alive, they''re developing to', 'A potentially great successor to Wipeout, ruined by poor steering mechanics that are ill equipped to handle the game''s increasing speed.\r\n\r\nI really wanted to like this game, and I did early on in the campaign mode, as the early campaign is no problem to beat. Later on however, the default game speed increases in the campaign so much as to reveal a glaring flaw with the game''s steering mechanics simply not being able to keep up to the point where you''ll be running into walls with nearly every tu', 'Overwhelmingly Positive', 95.52, 20.53, 7.47);
INSERT INTO reviews VALUES (7431, 473910, 143, 'As games with gameplay features go, this has exactly one.\n\nBut it''s a good one. A very, very good one. \n\nHopefully someday, there will be as many as two gameplay features.', 'I truly hope I can recommend this game further down the road. As it is, The Nest is a cool concept that''s fun for about 10 minutes, but like a lot of these VR games, is a one trick pony. The sniping is fun, the zooming in is cool, playing at night is awesome, but you see all of it and do all of it before you can even really get into it. I know the game is Early Access. I hope the devs keep working on it and add new locations and a campaign and everything we could ever want. But a score should no', 'Mixed', 61.54, 0.60, 0.50);
INSERT INTO reviews VALUES (7432, 473920, 126, 'This game has a great story you really gotta play through the first two days and nights to really start enjoying your self  the first day you can''t do to much but as you go through each day and night the more things you can do the more entities you can interact with it really is such a great story.', 'This is...not what I was expecting. I anticipated a point-and-click adventure game, not a smaller, less colourful Stardew-like. I completed the first day and feel absolutely no desire to continue playing. Apparently it''s short, but it doesn''t feel like a game I want to stick with for more than a couple hours.', 'Overwhelmingly Positive', 98.41, 12.27, 3.83);
INSERT INTO reviews VALUES (7433, 473950, 3939, 'hardcore puzzle enthusiasts will call this game "too easy" but since i''m a dumbass i instead opt to call it "extremely well-designed" and "remarkably intuitive." based video game', 'Me dumb. Me turn here, turn there, no work. Makes head hurt and pc burn hot-hot', 'Overwhelmingly Positive', 95.23, 4.82, 2.02);
INSERT INTO reviews VALUES (7436, 474020, 424, 'nice colony sim', 'I love the game, I love the idea of the game, I love the setting of the game, I love a lot of the concepts of the game. If the (solo) dev had worked with a team, or sold the game to a studio, or kept up support, I believe it could''ve been great. The vestiges of greatness are there, but it''s clear the game still needs a lot of love to even become a cult classic. It breaks my heart, but that''s I can''t recommend it.', 'Mixed', 57.31, 24.52, 18.78);
INSERT INTO reviews VALUES (7439, 474210, 593, 'Fun game. Run around, kill humans. Lots of pixel gore\r\nIf you find the game too hard, try following:\r\n1. Pick a gamepad. Aiming with mouse is difficult, cursor lock on helps a lot\r\n2. Improve contrast in the settings\r\n3. Play on first difficulty', 'It''s easy to tell when a game is difficult just because it''s poorly made.\n\nThe people responsible for this game''s final boss deserve to get slapped so hard it makes them cry.', 'Very Positive', 89.71, 3.35, 13.23);
INSERT INTO reviews VALUES (7440, 474220, 232, 'The server password protection feature doesn''t work and someone who is presumably a friend of the developer invaded a private match. When I notified the soldat 2 community discord of this issue I was met with abuse and told this was normal. Great game, but off putting community.', 'According to recent news, officially abandoned by the developer. It won''t even see 1.0 version.\n\nPlay first Soldat, it is better than S2 anyway.', 'Very Positive', 85.78, 6.20, 2.88);
INSERT INTO reviews VALUES (7444, 474750, 2555, 'If you enjoy easy to play games and don''t mind that this game is really short then this seems fine. It was nice playing through a few times. I''m sure its boring if you wanted to try completing this game though.', 'The game feels very repetitive, with RNG heavily influencing the experience. Without a guide, progressing the story requires grinding through the same scenarios repeatedly while trying to guess the correct sequence of actions. Over time, I found myself stuck, encountering the same events over and over again as I struggled to figure out how to advance the story.', 'Very Positive', 85.13, 7.22, 2.25);
INSERT INTO reviews VALUES (7447, 474890, 114, 'While a bit clunky I''ve had a fair share of fun in this game, mainly by making my on vehicles/mechas, and hell even if the game seems to be dead now it wouldn''t be the first time the developer takes a (3) year-long hiatus', 'I really want to like this game, but it has one very short campaign and it''s more about telling a story rather than testing your skills. Each mission takes a long time, usually because you have to search for something small on a large map using slow units with very limited visual range. Despite the variety of parts you can build with it there isn''t much depth to building or strategy to be found here\nI would have loved to see what could have become of this game had it continued to be developed', 'Mixed', 67.54, 38.30, 23.03);
INSERT INTO reviews VALUES (7449, 474960, 6642, 'Why isnt there an I just Like this button? It''s great. Scifi, mystery, action. Good story. Mind bending. Why do I need to type all this. I just want the algorithm to know what I like.', 'I would really like to give the game a good review due to it''s enjoyable story, interesting combination of game rendered and live action sequences, generally great performance & overall attention to detail. However, due to the current implementation of streamed live action content consisting of unacceptable buffering pauses and constant failure popups - I simply cannot recommend the game in it''s current state.\n\nEither a full download or on-demand download option (i.e. download the live action se', 'Very Positive', 83.47, 4.15, 12.73);
INSERT INTO reviews VALUES (7450, 474980, 134, 'This game feels like a school project but it has cats in it so thumbs up for that.', 'I didn''t realize this was a dating sim... One option you can pick is a kitten.. I feel wrong for even buying this. The friend person in game says, "Oh, they can become a human!", yeah, I think I''ll pass.', 'Very Positive', 92.54, 2.72, 0.25);
INSERT INTO reviews VALUES (7455, 475150, 7502, 'Its actually funny: Playing Titan Quest in 2025 feels like playing an early version of Grim Dawn (my, by far, favorite aRPG)\nTitan Quest is a fun game even though it feels a bit more "simple" than Grim Dawn and more whacky at some points', 'The game is great but the current developer (or IP owner) is a huge red flag. Making a patch for a remake of decades old game just to put an ad into a menu of single player game without DLC or microtransactions is just straight up evil. I was interested in TQ2 but after seeing ads being retroactively added to existing titles, I will look at TQ2 through suspicious and skeptical glasses. Definitely no preorders.', 'Very Positive', 90.38, 12.90, 72.90);
INSERT INTO reviews VALUES (7456, 475190, 2098, 'You pay for an experience: getting to paint the level with a LIDAR device on an otherwise black field of view. At what do you value that experience? You get a few hours of moving around a straight forward level-design, with a couple of jumping challenges. That''s okay. It''s stunningly beautiful, but I am glad that I waited for a sale.\n\nThere were a couple of major bugs while using a gamepad controller. I can only recommend playing with a keyboard and mouse. I used Steam''s Proton compatibility sof', 'The game was an interesting concept. Unfortunately there was far too little game play and finished it in under 2 hours. I was hoping there would be more scary instances but most of it was just making sure you scan before a jump puzzle .', 'Very Positive', 91.28, 4.17, 2.13);
INSERT INTO reviews VALUES (7457, 475240, 187, 'Overly simplistic, but highly playable and often fun. The graphics make it look like a mix between NES and Atari, the game being more like a dumbed down Mario-style platformer. What''s fun about this game is figuring out the different ways to bypass the countless enemy types you come across. There are also several bosses and the game keeps introducing new elements as you progress. There are little details like a shield you can pick up from a fallen enemy on the final level, or a sub-zero type orc', '\n1/10 \n', 'Mostly Positive', 79.68, 2.13, 3.37);
INSERT INTO reviews VALUES (7458, 475490, 346, 'The anthropomorphic animals could be human for all I care and it wouldn''t effect the story whatsoever but it does make for variaty in character design XD\nI honestly didn''t know what kind of story I was expecting but it certainly excceded my expectation and was a lot more interesting than I hoped even if it has a lot of plot holes as would any story trying to have a setting as complex and grand as the universe :3\n\nSadly in a technical aspect is has a lot of cons, A LOT OF CONS, or maybe just all ', 'Major/Minor is the first game from Klace. I have played this game all the way through three times. It was not quite a pleasant experience.\n\nThe pace of Major/Minor is sluggish because of the engine it is built on. It''s built in RPG maker and there really isn''t a way to autoscroll text. You have to hit a button to advance the text every time you need to, so you can''t just leave it on auto and read as it comes up. It''s like reading a novel where you have to turn the page for each line. Likewise, t', 'Mostly Positive', 76.88, 25.12, 36.85);
INSERT INTO reviews VALUES (7461, 475550, 2807, 'This is the game that made me create a Steam account. It was my first game on the platform, and the first DLC I ever bought was for it. This game suited me perfectly: it ran smoothly on my laptop, which was more like a calculator than a computer, and it embodied my passion for dystopias with totalitarian regimes.\n\nThe story is a masterpiece. It immerses you in an oppressive atmosphere of constant surveillance. It offers a unique opportunity to dive into other people’s lives and shape their fates', 'This game has a lot of potential, but for how long it''s been around, they should have fixed a lot of very simple aspects that make the game more work than fun. \r\n1. The controls are terrible, whether you use keyboard/mouse or controller. At the very least, you should be able to pause the game with the spacebar, but you can''t.\r\n2. The tutorial leaves out some key aspects of playing the game, like where to click to document evidence.\r\n3. There''s way too much going on simultaneously to make the gam', 'Very Positive', 82.08, 77.02, 3.43);
INSERT INTO reviews VALUES (7468, 476240, 380, 'Most of my playtime was just me falling asleep on my bed while trying to play knights. You can''t blame me; the music makes me sleepy xD. Overall, the game is good for the price. There are a decent number of levels, and the difficulty is manageable.', 'wanna be friends?', 'Overwhelmingly Positive', 95.00, 22.95, 0.17);
INSERT INTO reviews VALUES (7471, 476420, 145, 'i really love this game i have the real card game and its the same just not as many expantions', 'Very fun card game, but unfortunately I cannot recommend it at the moment.\nThe game was designed  for 720p resolution, playing on anything above and the game is just upscaled, resulting in blurry image quality.\n\nThis is rather strange for a 23€ release (33€ with DLC included). Decent resolution art assets should be a must, especially for a card game. Reading blurry card texts is not a pleasant experience.\n\nRefunding for now, but keeping an eye on it, in case there''s an update on it.\nShame really', 'Mostly Positive', 71.03, 327.78, 1.50);
INSERT INTO reviews VALUES (7478, 476530, 609, 'We violating the United Nations Treaty on Principles Governing the Activities of States in the Exploration and Use of Outer Space, including the Moon and Other Celestial Bodies with this one', 'while the game is good, i cannot advise it as the dev abandoned it and never said anything about it four years ago\n\nand the optimization is seriously lacking', 'Very Positive', 89.16, 0.78, 337.33);
INSERT INTO reviews VALUES (7480, 476600, 13025, 'One of the best Call Of Duty games in the franchise. Love the story and the attention to detail put into this game', 'I loved this game. Every mission. Until I had to control the Sherman tank. Whoever coded those controls is absolutely retarded and it was enough for me to uninstall and not play any more of this game.', 'Mixed', 65.14, 20.65, 3.45);
INSERT INTO reviews VALUES (7481, 476620, 2861, 'I can confirm that all 3 gamemodes of this game work on Linux, in Proton. \r\n\r\nTwo Call of Duty games are the only ones to be playing on Linux, Infinite Warfare, and WWII- anything prior to Infinite Warfare is subject to the hackening and you''ll get your PC hacked and infected by playing them online, anything AFTER WWII has a Linux incompatible anti-cheat and you can''t even launch them (first affected game broken by this is MW2019). Hope that helps!', 'Easily one of the best call of duty''s, but almost dead on pc with no cross play to alleviate it unlike the games that came after...', 'Very Positive', 82.21, 5.82, 0.73);
INSERT INTO reviews VALUES (7482, 476650, 526, 'Our lives are finite, we are born and we die. So we ask, ''What is the point? Where is the meaning in our temporary lives?''. But we can''t answer this question. Our reality exists only between our birth and our death, so to ponder on what comes after is futile. Instead of searching in vain for meaning in a meaningless universe, we could better spend our time searching for happiness.\n\nIf you are looking for a deep philosophical work that will make you look at yourself and your life in a new way, th', 'For a "detective game," it makes very little sense. It''s incoherent even for a game with supernatural horror themes. I think I''d only continue playing it if I totally let go of any expectations, and just wanted to see if I could figure out where the writers were trying to go...but I don''t think I''d want to drag myself through any more of that dialogue.', 'Very Positive', 88.21, 70.92, 3.12);
INSERT INTO reviews VALUES (7485, 476700, 327, 'When I found my wife sobbing in the fetal position next to a pool of her own vomit - headset still on - I knew this game was going to be great.\n\nGhosts and zombie nonsense don''t scare me - they''re not real and my brain won''t be fooled.  Bears scare the bejeebus out of me because I know IRL they will eat my liver and crap me out.  If we managed to reanimate dinos, I would be scared of them, too.  Hence, I am inclined to shit my pants when I notice 3 raptors stalking me up on a ridge or get swarme', 'for some reason i cant play it on my quest 2\n', 'Mostly Positive', 74.31, 34.32, 0.63);
INSERT INTO reviews VALUES (7492, 477160, 29251, 'Its really funny especially with friends but when your by urself, its kinda lonely and depressing. I myself have no friends to play with but its still really fun!', 'I just don''t think this game is for me. The puzzles are often a bit too complicated for me (that''s kinda on me though), and I occasionally get motion sick when not grabbing things correctly, and trying to move, instead having grabbed the floor. I get why people enjoy this game, but I just can''t. I do admire the developers'' free updates, that''s top-tier development behavior, it''s just that the game it''s being done for is hard for me to enjoy.', 'Overwhelmingly Positive', 95.27, 6.72, 5.62);
INSERT INTO reviews VALUES (7497, 477270, 532, 'walmart beat saber', 'does not work', 'Mostly Positive', 79.51, 1.28, 7.13);
INSERT INTO reviews VALUES (7501, 477730, 491, 'A truly beautiful game and very fun game for it''s genre. Endless replay. A hidden gem for me finding it in 2024. I hope this title will get another DLC or continue on the series. Best game money I''ve spent all year! It''s got a very unique take on kingdom management, which I love, and the hero stuff is great too!', 'The game opens with a disclaimer in broken English that is it very buggy and prone to crashing and to just get refund the game if you enjoy a more stable gaming experience.\nI''d rather they just fix their damn game, but to each their own.\nI got my refund, and you got your negative review for making me waste time in buying, downloading and installing it BEFORE you tell me to not play it.\n\nhttps://i.imgur.com/shziqf5.jpeg', 'Mostly Positive', 70.67, 151.18, 0.80);
INSERT INTO reviews VALUES (7502, 477740, 3505, 'I have no words on how to describe this game but this game is fantastic enough with a deep lore (you will see it when you play the game). You get to play the first game (999: 9 hours, 9 persons and 9 doors) and second game (Virtue''s Last Reward). Definitely worth the purchase so this game gets a solid 10/10 for me.', 'I was very excited to get this game for my steam deck, as I loved it on my 3DS back in the day. However, in the short time I''ve played it, I have experienced multiple crashes. It''s hard to get invested in a game when I am constantly worried about losing my progress. I got it on such a significant discount that I don''t regret it and will probably try it out on my PC to see if that''s more stable, but if you''re planning on playing this on steam deck, I''m not sure I can recommend it.', 'Very Positive', 94.86, 60.67, 2.05);
INSERT INTO reviews VALUES (7504, 477770, 864, 'A fitting sequel to Ride.  More bikes than the first game and i find it much easier to control using Xbox One Controller', 'This is absolutely shocking, good luck trying to play this game, because it''s completely unplayable - even on hardware well beyond what is required. The game stutters to the degree you can''t have fun or control the bike at all. Turn all graphics to minimum and it will do exact same, because it''s a software issue. The same happens across multiple PC''s. Should be delisted from Steam as it is completely fraudulent.', 'Very Positive', 83.33, 118.72, 1.05);
INSERT INTO reviews VALUES (7507, 477870, 598, 'This game (and its sequels) is an amazing story. I would definitely recommend it to emotionally mature people. Growth and kindness in the face of terror and trauma may seem unrealistic to some people (I think we call those types cynical), but that is the story here. From dealing with shock and self-blame to helping others despite the situation, this is a great tale of choosing kindness and growing while surviving in an unfair scenario.', 'Quick saves don''t save your game, they''re checkpoints. If you don''t go home to save your game and quit the game, you''ll lose all your progress.\nMake sure you keep walking.\nThis game has a bunch of oversights that don''t seem to have been patched in almost 10 years. Hopefully somebody else can have a better time with it.\nIf you like Japanese folklore and monsters, you''ll probably enjoy this.', 'Mostly Positive', 78.43, 8.68, 1.37);
INSERT INTO reviews VALUES (7517, 479010, 289, 'When I first bought Kodon it was in the earlier days of VR. Glad to see a tremendous improvement since then! Works great as a fast and intuitive prototyping tool. Love the radial array tool. That''s a pretty unique tool for sculpting. I was aware of the save issue so I did a "save as" .fbx file and had zero problems. Imported the fbx into Blender. No issues there either. The results after just a few hours are encouraging. Will continue to work with it', 'Abandonware, there are a few bugs that can break the whole experience. i would not want to contribute to developers who abandoned something in the state this is in. if it was for the most part functional before being abandoned i would not have refunded. even at a -70% discount its not worth it', 'Mixed', 66.78, 4.78, 0.52);
INSERT INTO reviews VALUES (7519, 479100, 108, 'I love it even though it''s glitchy & broken', 'Weird to have an account system for a text-based pc game. Honestly isn''t worth the effort.', 'Mixed', 45.37, 172.72, 39.32);
INSERT INTO reviews VALUES (7530, 480430, 258, 'Someone shits pant while playing Goon and Shriek\n\nMe: Knowing what this means 😱', 'This game had so much potential, sadly the devs pretty much stopped working on it after they launched instead of possibly creating new maps, runes and spells and even different game modes. Now that the game is free to play, it''s definitely a good play with your friends every now and then.', 'Very Positive', 81.01, 10.73, 10.43);
INSERT INTO reviews VALUES (7531, 480450, 104, 'Flippy Hero is the single greatest game that has ever been created. I am Donald Trump and I approve this message.', 'the wasd and arrow keys do nothing and i cant move, i dont know why', 'Overwhelmingly Positive', 98.08, 12.83, 3.88);
INSERT INTO reviews VALUES (7533, 480490, 20615, 'Last good Arcane game until they got mutilated and killed off by Bethesda. 9.5/10', 'I really tried to like this game but I just can’t. The first hours are really rough, and the gameplay never really clicks. Backtracking is tedious, enemies respawn constantly and take forever to kill, and the gravity-based exploration is s''ucks. On top of that, the story is mostly told through audio logs and calls, which are easy to miss because they often play during combat.\r\n\r\n5/10', 'Very Positive', 91.42, 34.23, 27.32);
INSERT INTO reviews VALUES (7534, 480640, 417, 'There are a few bugs, but in general it is not a bad adaptation of the original card game. I hated the mechanic of banishing cards from your deck in the original and it is even more stupid in the game where you can pay for cards. But overall the gameplay is captivating.', 'From my understanding, this used to be a microtransactions game, now a pay to play game. That change is good, as I prefer to buy the game once and enjoy it without being gated by energy, watching ads for gems, or having to buy lootboxes for cards.\n\nBut the game itself has not been updated to match this change. The menu is annoying to navigate, the online saving and crossplatform saves transfer isn''t reliable (you can lose your teams and your progress), the deck building is abysmal and tedious.\n\n', 'Mixed', 62.35, 93.97, 6.88);
INSERT INTO reviews VALUES (7539, 481110, 599, 'Difficult game, been stuck for a few hours.\n\nEDIT: 5.8k hours - HTF do I get out of the bunker!?!? it''s starting to get to me...', 'I''d agree with the other negative reviews; the game itself is pretty low key with a poor array of choices and a pretty low quality plot under it all. All this I could forgive though, ultimately it''s a FMV game, there are better ones but you''re not expecting Kubrick''s finest work HOWEVER the button mashing at the end can go **** itself. I don''t enjoy ''replaying'' scenes to fail them for not clicking repeatedly fast enough, it''s a terrible gameplay device and should burn in a fire. Totally soured a', 'Mixed', 67.95, 7398.80, 2.57);
INSERT INTO reviews VALUES (7540, 481180, 207, 'Step one, buy an inconspicuous cyberpunk CG.\nStep two, read the prologue done as a love letter to the legendary Blade Runner''s foreword.\nStep three, browse through many absolutely gorgeous portraits for your main character, listen to the first sounds of the elegant, spot-on cyberpunk soundtrack (the hights thereof would be something an AAA production would have problems achieving), and after that having a cool, little fixer-vs-muscle AV conversation featuring simple, yet well-thought out reactio', 'Not a bad game, but a boring one. I would probably have rated it Yes if it was not so long for no good reasons. You will be literally forced into multiple combats that are all the same, for the sake of making the game last longer. This is usually not a good idea. This game, with a total duration of 5-8 hours would have been fine. Longer is not better: it''s just boring!', 'Very Positive', 82.13, 8.80, 25.28);
INSERT INTO reviews VALUES (7541, 481190, 211, 'quite good but abandoned 9/10', 'I regret to say this, but this game has had zero development in 7 years and it just not worth the hefty price tag of 20 dollars. at most this game has less than 4 hours of play time to it.', 'Mixed', 51.18, 22.62, 1.62);
INSERT INTO reviews VALUES (7543, 481510, 12431, 'Do you wanna be reminded you''re a burnout, that couldn''t escape your small town, and are struggling with the fact that you''re growing apart from all of your closest friends? No? Well too bad.', 'This game is nice but a bit boring (well it''s a walking sim)\nBut that''s not the reason I recommend not paying for this.\n\nThis game was made by Alec Holowka. He is no longer with us. False rape accusations by Zoe Quinn (some of you veterans may know this name) drove him to suicide. After he was bullied off this mortal coil, the game company went to his sister, Eileen Mary Holowka. Who was buddy buddy with Zoe. But it doesn''t end there. Eileen used the plenty of money she got from her brothers gam', 'Very Positive', 94.78, 1.17, 27.15);
INSERT INTO reviews VALUES (7547, 482300, 274, 'This game is the king of Mehs....\r\nNot really bad but not good also... finished the game wrapped up the dlcs and achievements and still i didnt understand what it was about....\r\n\r\nIts okay for the price but dont have your hopes up for a nice ride \r\n\r\n5/10', 'I want to like this game. The map design is pretty good and the atmosphere has a good blend of creepiness and intrigue. The major problem is how janky this game is. The player character will OFTEN get stuck in geometry making climbing and even simply walking through a door frame a major chore. I even randomly teleported off the map and into the ocean one time.\n\nAnother problem this game has is that it doesn''t make it clear when the game is saving. Take the time I teleported into the ocean for ex', 'Mixed', 65.33, 4.60, 1.32);
INSERT INTO reviews VALUES (7550, 482400, 6764, 'Nightdive deserves more recognition for this perfect remake. Thank you for bringing one of the greatest games back to life. System Shocks 1 and 2 are not for people who require yellow paint in their video games. Don''t worry, the Bioshock arrow will always be there to assist you in other games.', 'I can''t finish the game due to a gamebreaking bug. The game crashes every time I try to enter the flight deck. I was able to enter it earlier in the game, but now I can''t. So I can''t complete it. If the devs respond to my ticket with a fix that works, I''ll change this review to positive. But for now, I''d hold off on buying this game until you can be sure you can finish it without waiting around for a patch that may or may not come.\n\nEdit: the devs responded to my support ticket by informing me t', 'Very Positive', 91.16, 25.55, 20.03);
INSERT INTO reviews VALUES (7551, 482450, 408, 'This is what happens after the Back To Normal route in Song of Saya', 'i''m really annoyed with the controls. can you please address the config bug? it''s very frustrating. as a newbie to fighting games, even i can see that the final boss is poorly designed. it''s the most unbalanced fight i''ve encountered. you get stun locked right away, and suddenly most of your hp is gone. the end boss is just terrible; you get stun locked and then you''re dead.', 'Very Positive', 89.71, 2.15, 2.07);
INSERT INTO reviews VALUES (7558, 483770, 158, 'Horrible game\n\n10/10', 'If you are even remotely thinking about buying this game, DO NOT.\n\n(Aerosoft please stop publishing rubbish.)', 'Mixed', 43.04, 2.52, 7.15);
INSERT INTO reviews VALUES (7561, 483950, 132, 'Despite lack of scripting it is pretty nice.  Get the Unity exporter!', 'This software has a LOT of potential to be almost perfect for it''s intended purpose, and I was really excited and looking forward to using it, but sadly I don''t think it''s worth it for the overall cost.\n\nPros:\n- Pretty easy to use\n- You can add your own models and sprites which is nice\n- There''s no additional licensing needed to sell your game if that''s what you want to do\n\nCons:\n- VERY limited customization. Can''t even change the font of your game in the standalone software\n- No scripting in th', 'Very Positive', 84.09, 51.95, 5.98);
INSERT INTO reviews VALUES (7562, 483960, 146, 'It''s no HuniePop but the match 3 aspect is very fun and a lot more challenging. I just wish there was more to it. It took me a few plays to get used to it but I actually like how in the match 3 you can move your pieces anywhere on the board instead of in the adjacent rows. It wouldn''t work for all match 3 but it works for this one with the difficulty. \nI did not use any H patch and I did read through all the text, speed reading a bunch of it. I love VNs but I didn''t expect much from the story, a', 'I was very excited to play this game. I loved HuniePop, so I wanted to play something similar. Although, Purino Party comes out as a product with pretty looks but with an insanely annoying gameplay that ruined my experience. I like matching-3 games, I’m no expert tho, but wow I expected something at least fun and not so frustrating.\n\nAbout the story, it’s nothing brilliant. The goal is to unlock the lewd CGs of the girls, and interact a bit with them. You have two sets of girls, each one with 4 ', 'Mixed', 60.96, 11.45, 8.52);
INSERT INTO reviews VALUES (7564, 483980, 2237, 'Mad father is a fun little puzzle horror game that lasts about 3-5 hours. I would highly recommend getting it on sale if you enjoy other horror games like it. The story isn''t anything crazy, but it is still engaging. It really shines when it comes to the puzzles.  I would give it a 8/10, definitely buy and play on sale.', 'The ending with Maria is glitched so I am unable to actually complete it and the poor writing of female characters even in death illustrates the authors own sexism.', 'Overwhelmingly Positive', 98.03, 3.08, 5.65);
INSERT INTO reviews VALUES (7565, 484350, 142, 'There''s been a ton of negative reviews lately by people who don''t follow the steam forum developments for this game, and got the impression it''d been abandoned because of how long it''s been since the last update\n\n...but as it turns out, the dev was just holding off on small updates to grope them together for one *massive* game-overhauling update in one big burst- instead of a bunch of  smaller, more incremental changes.\n\nThis dev *definitely* is still putting tons of work into this game!', 'i really didnt want to leave a negative review of this game but here we go SO back in 2018 this game was good i played it a lot with my friends fighting endless waves of zombies with random guns that you would get randomly depending on how many zombies you would kill and it was actually fun and i enjoyed it back then. the game was like a arcade zombie game but now from 2021 to now its just a bad story driven game that took away what was fun with the game i dont even know if it has the arcade mod', 'Mostly Positive', 72.54, 4.72, 5.85);
INSERT INTO reviews VALUES (7568, 484870, 393, 'gold', '2 out of 10\n\nPlayerbase is completely dead, this is a multiplayer game with no players so it''s effectively useless. Gamers move on and this is magnified with mp VR games.\n\nMy score must reflect this glaring issue. Easily an 8 if there was anybody ever online. There are some solo scenarios versus AI, but they can''t save this game, they are really terrible and not worth the bother.\n\nShort review as saying much more is irrelevant. Shame, not the devs fault he''s done a really good job in creating a ', 'Very Positive', 88.55, 17.63, 0.85);
INSERT INTO reviews VALUES (7570, 484900, 1153, 'Reading other Steam reviews, I don''t know what''s going on in Windows land but over here in Linux the game is crash-free, solid as a rock! Maybe you should join us? WINK.\r\n\r\nUnlike other city-builders that got bitten by the punish-the-player bug, Aven Colony is light-hearted, relaxing and fun. The simple, attractive graphics and easy build systems combine to weave a hypnotic little spell as you lovingly craft your little sci-fi colony from tender lander-acorn all the way to mighty, orbit-scraping', 'Overall a fun game, but it''s completely unplayable on Windows 11. It won''t stay open for more than about a minute without crashing ever since I updated. Which is really unfortunate, because I do enjoy it.', 'Mostly Positive', 73.98, 30.88, 15.18);
INSERT INTO reviews VALUES (7572, 484950, 155, 'EvilMaze\n\nHas a total of 7 trading cards.', 'A censored, low-effort dungeon crawler with reused assets and repetitive gameplay', 'Mixed', 65.81, 1.85, 20.47);
INSERT INTO reviews VALUES (7574, 485030, 242, 'It''s a relax game that you play when you don''t wanna break your head on your desk because the game is too complicated.', 'full of trial and error puzzles, and boring platforming sections. dont get fooled by the nordic arty fartsy artstyle, this is an empty shell of a game.', 'Mostly Positive', 76.03, 7.98, 7.77);
INSERT INTO reviews VALUES (7575, 485040, 166, 'i love say gex. 10/10.', ' First off this is NOT a game, It is a very crapy writen story book, no animation, the voice is in ????? so you must not only flip thru page by page (Several times before you even get a new picture tolook at) you need to read the subtitles. This is by far the worst money I have ever spent.  For the most part you can kinda of judge a game by the price, a $40.00 game is normally a fairly decent, if not good game. Like I said if you are looking for a "Game" to playlook elsewhere. This thing sucks T', 'Very Positive', 87.35, 25.13, 8.28);
INSERT INTO reviews VALUES (7588, 485350, 106, '💝', 'good art bad story, not worth trying', 'Mostly Positive', 74.53, 2.02, 1.27);
INSERT INTO reviews VALUES (7590, 485370, 122, 'If you ever wanted to go into combat as a marine, a mad marine, this may be the game for you.\n5 guns, 3 maps, 1 incredible experience.', '\nSuprisingly bad.\n', 'Mixed', 68.85, 3.80, 4.07);
INSERT INTO reviews VALUES (7591, 485380, 1548, '\r\nHard to recommend. Game feels a little bit "unfinished" but it have some nice premise. You search for hidden code while browsing different websites on dark web. Some sites are only available at specific hours, etc. You have to be extra careful to not get hacked while doing so and watch your surroundings to avoid real danger. Gameplay might took a few attempts to clear the game and it''s more on difficult site. If you like games where you have to be cautious to survive and constantly paying atte', 'Fuck you adam', 'Very Positive', 82.69, 2.75, 11.67);
INSERT INTO reviews VALUES (7593, 485400, 153, 'Game is HOT FIRE LAVA SAUCE! *Very* cool cyberpunk CRPG, super immersive, tons of great features and old-school yet modern in some ways too. Highly recommended if you enjoy RPGs of the Baldur''s Gate type variety and stuff like that, you may LOVE this game like I do! Great job Hannah & Joe! :) <3', 'The game has incredible aesthetic and has some serious charm in how it presents itself, however the game itself has some fatal flaws. in my short time playing I had to re load my game at least 7 times to re gain the ability to move and interact with objects. On top of that this game is pretty brutal, this is the kind of game that makes guns pretty hard to use and uses chance a lot to decide whether or not you hit. This is very similar to the original Fallout game and is a negative in my eyes. I ', 'Mixed', 49.67, 7.48, 2.53);
INSERT INTO reviews VALUES (7596, 485460, 1231, 'Still a very good game. Original and very artistic. However, the story is so pessimistic. It''s a downer.', 'After playing through the first two games without a problem, this one in particular crashed multiple times - which is a huge problem in a game without manual saves (and autosaves can be over an hour apart).   \n\nThen I reached a spot about 2/3 through with two battles in a row (one a two part wave battle) which crashed on me three times in a row right after beating both battles.\n\nAt that point I gave up and watched the rest on YouTube, an incredibly unfortunate ending after playing through a tril', 'Mostly Positive', 79.77, 165.77, 21.57);
INSERT INTO reviews VALUES (7599, 485510, 8004, 'me: "hell yeah I combo this enemy with so many combos/hits, now for the final strike"\r\nKO''d you in one or two hits\r\nme: "wtfajdbauiwdbiaw"\r\n\r\nbasically what is like playing Nioh\r\n', 'After 20 hours I would gladly recommend game but the longer it goes the worse it gets. Balance is nonexistent. You will start being under leveled to the point you will be short of 100 levels to match recommended level. At this point you either continue and it will feel like playing Elden Ring without upgrading or spend hours farming levels and better gear. Whats worse game already feels very repetitive and boring before that point. Game is no longer skill game, it''s just grinding fest with terri', 'Very Positive', 80.98, 52.13, 67.68);
INSERT INTO reviews VALUES (7603, 485610, 862, 'Nobody will read my review so I Will Eat 1 Tablespoon of ketchup For Every Like this gets.', 'Whole community are elitists, you will never learn to play because bots are to easy and sweats will kick you before you even get to finish a game, 0/10 ruined by the community.', 'Very Positive', 90.14, 0.20, 6.52);
INSERT INTO reviews VALUES (7609, 485670, 135, 'I love this game.', 'It''s pretty much a poor game, for it to be over £7 is staggeringly expensive and a total rip off honestly. However if you can get it on sale for under a £1 then do so. the colourful polygonal map is quite fun in a big lobby, and its worth it for that alone at 90% off price.', 'Mixed', 48.89, 4.30, 17.80);
INSERT INTO reviews VALUES (7611, 485690, 244, 'I first have to say that i never encountered such a bad translation for the HOS were a key is a wrench and a wrench is a key. And this is only one example for it. The game itself was pretty ok, sadly it had a few moments where you needed a tool that you had a bit earlier. Most of the minigames were really easy to handle, there was only one annoying puzzle that i skipped. The story was pretty nice and the overall graphics were really nice and cool. There were very few cutscenes, which was a bit s', 'I can not in good conscience recommend this game, unless they update it with a proper translation. The hidden object games are near impossible to finish without hints or just clicking on everything due to at least one or two objects being mistranslated in every scene. Sure, with time you learn that wrench and key apparently is the same word in whatever this was translated from, but it is annoying and makes the game less fun. Also, the minigames are so easy they are not even fun, and even then, t', 'Mixed', 63.93, 5.57, 2.93);
INSERT INTO reviews VALUES (7621, 485870, 137, 'worth my whole family''s social and economical integrity', '\r\nMore poopy action but this time even worse than ever!\r\n', 'Very Positive', 81.75, 0.53, 7.65);
INSERT INTO reviews VALUES (7623, 485890, 374, 'i go on steam during a steam sale to buy a game on steam thats about a steam sale and buy games in the steam sale game that are apart of the steam sale', '👎', 'Mixed', 49.47, 0.48, 0.80);
INSERT INTO reviews VALUES (7624, 485900, 147, 'The game is interesting but rather shallow. After a little while, you have seen everything it has to offer.\r\n\r\nThe devs missed the boat when it came to make an educational game via game mechanics. There are too few things you can do and learn just a little about computers. Just like Mechanic Simulator and all those other garbage games that are made in a haste.\r\n\r\nIf you see it cheap though, it is a good enough to be added to your library if you like computers. I really liked it, but it becomes r', 'I got it on sale for under $8 USD and its not worth it!!!  My PC is well over the recommended system requirements and it always crashes, I thought it was maybe something with workshop mods causing the problem but after unsubscribing to all items from the workshop verifying game files and double checking in game it had no mods the f*****g game still crashes F this POS!!!!!!! Spend ur money on something else!!', 'Very Positive', 81.63, 36.40, 23.60);
INSERT INTO reviews VALUES (7628, 485980, 1268, 'not very realistic, the Syrian army defends in this game unlike real life', 'Game didn''t prepare me. Lost Syria in 3 days. Assad is gone. Whoops', 'Very Positive', 83.83, 1.40, 0.12);
INSERT INTO reviews VALUES (7639, 486310, 2290, 'Best game to relax <З', 'I''ve spent so much money and time on this game, I''ve collected WHOLE Shelter series, games, books, and music. And for MONTHS now, ALL the SERVERS have been DOWN. It breaks my heart to say this, but the game is NOT PLAYABLE anymore. Its just impossible to play an online multiplayer game when all the severs are always down. I truly loved this game, but the developers have let it die, so rest in peace Meadow.', 'Very Positive', 91.00, 180.78, 64.70);
INSERT INTO reviews VALUES (7644, 486380, 232, 'This is a $30 quality game for the price of $3, buy it.', '\njust disappointing\n it''s so close to brilliant\n beautiful nothing... \n\nThis game is borderline brilliant.  It''s like someone made 85% of a masterpiece, and then stopped.  Thumbs down because of a few major issues that take it from being one of the greatest games I''ve ever seen all the way down to just not being worth $3.99, unfortunately.\n\nFirst of all, the art is great (although you''ll see the same handful of characters over and over), the gameplay idea is good, and the actual gameplay of turn', 'Overwhelmingly Positive', 97.41, 15.55, 3.32);
INSERT INTO reviews VALUES (7652, 486510, 186, 'Very fun little game! reminds me alot of BF3/BF4 tank gameplay, i enjoyed it alot!', 'Too minimalistic menu. You don''t know which buttons are for what in the beginning. I mean come on, every game has settings menu right from the start. This game doesn''t.\nWhen I finally figured out the controls I started playing it.\nOn the lowest graphics settings I became nausious after a few minutes and it is the first time for me. Graphics needs to be optimzed. I have more graphics demanding games which doesn''t lag like this game does.', 'Very Positive', 86.02, 1.07, 0.32);
INSERT INTO reviews VALUES (7657, 486650, 293, 'Amazing game, would stone an infant to death for a shot at playing this for the first time again.', 'this has to be the lamest game ive ever played , it wasnt even fun to walkthrough , a game for content creators to laugh at', 'Very Positive', 81.23, 2.33, 1.93);
INSERT INTO reviews VALUES (7661, 486720, 620, 'It took me a long while to get to writing a review, because all of my thoughts were quite pragmatic: music, gameplay, pacing, bugs, mechanics... while the game itself is about naked men with flopping schlongs. And here is a small story about that: I wanted to get myself a few games. I was in the mood for isometric mature ones, akin to Tyranny, for example, or older BG. Not a whimsical fantasy story about Disney princess saving the unicorn world, but something gritty, bloody, and real. Among many', 'Couldn''t pass the first room Lol. Quite disappointing after spending 15 minutes creating your characted and reading through the prologue. I may be dumb, but not that dumb. That is just poor game design.,', 'Very Positive', 88.71, 46.57, 0.40);
INSERT INTO reviews VALUES (7663, 486780, 532, 'it''s a really good version of fruit ninja, coming from a girl who played the *original* fruit ninja before they started charging for it on the phone. Really neat feature that you can actually knock fruit and bombs around without cutting or exploding them.', 'yeah i got bored very fast.', 'Very Positive', 80.83, 9.67, 0.08);
INSERT INTO reviews VALUES (7666, 486860, 1494, 'Yet again, negative reviews are a bunch of dumb clowns that don''t understand what early access is for.\n\n "Ever since release..."\nThere was no release. The game HAS NOT been released. The game is in early access and if you''re too daft to understand what early access means then you shouldn''t be spending your money on early access titles. AAA companies with 100s of devs take   5 - 10 years to release a busted game and you morons are crying because a game in Early Access isn''t in a finished state. Y', 'At this point the developer just needs to add mod support and let the community finish the game\n\n\n', 'Very Positive', 85.01, 10.25, 16.53);
INSERT INTO reviews VALUES (7670, 487000, 797, 'It is a perfect game to play with your significant other who does not understand complex game mechanics. We played this game more than a year ago and on a random morning, I saw a similar PoV in a different game which made me think of the fun hours my wife and I spent playing this little game. So, I logged in to Steam to pay my respects to the developer. I highly suggest playing with a friend who would scream at scary zombies etc. It makes the game a lot of fun.', 'Simple, chill game, but requires you to purchase DLC packs to get 100% achievements...', 'Very Positive', 80.30, 28.73, 24.38);
INSERT INTO reviews VALUES (7674, 487120, 3039, 'Simple, enjoyable and an excellent combination of building, exploring and combat. Even the music is top notch. Sandbox possibilities, sprinkled with combat, quests, crafting, harvesting, multiplayer, PVE, PVP and no ads or marketing or upgrades or pay to play...this game is 100% great in all respects.', 'I put my heart and soul into this game. I  even won a contest on the studios discord by suggesting a code element and spells that were then added to the game. \n\nI cannot in good conscience recommend this game to anyone. It is abandonware. Whoever the devs are, they are putting it on sale once in a blue for a few extra bucks. Nothing new has been added in years, and nothing is planned. The only communication comes from community manager “Laura” via discord announcements. There’s never any answers', 'Mixed', 64.76, 2063.15, 813.15);
INSERT INTO reviews VALUES (7677, 487220, 170, 'Freebie\n\nHas a total of 7 trading cards.\n', 'ㅤ', 'Mostly Positive', 71.76, 1.08, 3.83);
INSERT INTO reviews VALUES (7680, 487370, 174, 'Fun puzzle game, short and sweet, easy to progress without having to cheat. Seems to work well, no glitches crashes or issues really. Has a timed mode / regular mode which are the same levels.', ' Meh; it''s alright...not my thing.', 'Very Positive', 83.33, 0.50, 1.92);
INSERT INTO reviews VALUES (7682, 487430, 212, 'This is a peaceful and wholesome story where the character is going through life and finding peace in it through a mysterious world that the population knows little about. The characters are really cute and funny which made it worthwhile, and they all have their own personality to give you a reason to like them even more.', 'The visual novel turned out to be rather average in all aspects. The characters are not appealing at all, their designs are monotypical and unoriginal, and the main character looks oddly drawn. If someone is considering a purchase because of 18+ content, I hasten to disappoint - there are only two scenes, and they do not justify expectations. The soundtrack is also unimpressive, failing to create the proper atmosphere. In general, the game does not offer anything outstanding and does not leave b', 'Very Positive', 91.04, 4.25, 4.52);
INSERT INTO reviews VALUES (7689, 487700, 641, 'best porn game ive ever played', 'conan slept with my girlfriend', 'Very Positive', 93.60, 1.73, 0.62);
INSERT INTO reviews VALUES (7690, 487720, 893, 'People are angry saying that the Unrated version has disappeared from their libraries. They are right, mine is missing too. BUT try checking DLC files in the Steam menu. I bought the game a year or two ago (basic+unrated pack). And I can install both versions of the game. I also can see that there is huge sale on both versions right now. So... why not?', 'These fellas are thieves and should be hard banned from the steam store, you sold us all the game with the unrated version to boot, it was tied as a package, you couldn''t get the uncensored without, that''s what we paid for. You STOLE it from our libraries and relisted it as a separate game so you rancid dogs could snatch a few more pesos. I would say "May all your future games fail" but they already have, you guys suck!  \n\nHave fun with your slowly closing studio and more layoffs. Well Deserved.', 'Mixed', 44.12, 2.58, 0.30);
INSERT INTO reviews VALUES (7702, 488280, 108, 'Don''t watch a playthrough.\nDon''t read more reviews.\nPlay it.\n', '\n"it''s a timekiller arcade game" - true that.\n', 'Very Positive', 82.41, 4.13, 4.52);
INSERT INTO reviews VALUES (7703, 488300, 188, 'This game is what I have been waiting for. SNOW got old fast, and Steep... Well steep isn''t a snowboarding game. It''s a game with snowboarding in it. \n\nLet''s see if I can review this game decently. \n\nFor one, the difficulty is pretty damn high to be honest. People on youtube made this game look like a cake walk but it is far from that. Granted the game is pretty unrealistic when it comes to throwing a 3060 sentuple cork off a semi large feature, but that is the glory of a physics based game, I c', 'Definitely fun, controls take a bit of time to get used to. Right now the amount of content isn''t worth the 50$ price.  Right idea, needs a bit of work and added features.', 'Very Positive', 80.32, 219.90, 3.07);
INSERT INTO reviews VALUES (7704, 488310, 2036, 'DO NOT STREAM/LINK THIS GAME TO AN OCULUS HEADSET\n\nAs a Steam fanboy who''s owned this game on Steam for many years, the difference between playing this natively on a Meta headset from the Quest store versus linking it through Steam is literally huge. \nI went from constantly failing serves and struggling to beat silver AI to easily beating it without even noticing when playing through the Quest app instead.\nThere is a 15min demo in the quest store. Try it yourself.\n\nThe game itself is great and t', 'Used to be incredible before the switch to focus on Meta''s side. As a Steam user, your money is not valued by this developer; you are a second-rate customer to them.', 'Overwhelmingly Positive', 95.28, 8.47, 29.17);
INSERT INTO reviews VALUES (7711, 488550, 608, 'this game is GOATED. best game of all time. can''t describe how good this game is.', 'eh', 'Very Positive', 93.42, 8745.87, 5.08);
INSERT INTO reviews VALUES (7714, 488660, 165, 'Just Deserts is a nice simple visual novel with a main game play loop of sim management where you focus on building yourself up, romancing the heroines, and managing limited funds. I was very pleasantly surprised to find that all the girls were fully voice acted which really elevated my opinion of the game. In my opinion the soundtrack was a real bop, especially the menu track. The story itself is kind of basic but it had its moments and I enjoyed all of the endings especially the single ending ', 'I couldn''t get through it. It wasn''t the story or the difficulty that was the problem, but the interface. This has potential to be a good game, but it''s frustrating. \n1. The attack animations are unskippable. At a certain point of playing, I just want to resolve the combat. I don''t need to watch the enemy attack animation every time. \n2. I shouldn''t need to click on the enemies every time. If there''s one enemy, the game should auto-target. It ends up needing way more mouse movement for every act', 'Very Positive', 81.21, 18.00, 3.60);
INSERT INTO reviews VALUES (7716, 488730, 162, 'Had an absolute blast playing this in coop. \nThe graphics could be better, the story is a bit... sparse, and the balancing between the two characters is a bit off, with one being noticably more powerful at the start. And the camera could be better - dashing towards the edge of the screen and getting killed from something almost next to you aht you could just not see is not that fun.\nOn the plus side, it''s a really fast-paced game that felt hard, but not punishing. \nBoth the levels and the boss f', 'No gamepad support, or at least it doesn''t support my DualShock (though it accepts a button press from the title screen before the main menu, so things are definitely hooked up).  Annoying, overwrought ''badass'' voiceover work in service of a zero effort story.  Press and hold the ''R'' key to do a stealth kill (quiet attack, body disappears so as not to arouse suspicion); it''s one thing to briefly move your index finger off ''D'' for a quick action like a use key or some other quick tap, but to hold', 'Mixed', 67.28, 12.12, 0.15);
INSERT INTO reviews VALUES (7717, 488760, 105, 'Rest in peace man.... :( You made an amazing game.', 'Not sure why there are so many good reviews for this game. Feels much to early for early access. Visuals are very poor, game is overly dark for no good reason (even after the first patch). Enemies (zombies) are poorly animated, make almost no sound, glide faster then their walking animation, and just run in a straight line for you.\n\nThere is no indication of your health, and no indication of taking damage, the enemies just kinda slap at you.\n\nThe spell casting seems like it could be fun, but its', 'Very Positive', 84.76, 4.25, 0.18);
INSERT INTO reviews VALUES (7718, 488770, 201, 'A fun little point and click puzzler. Beginning with a premise that just might work IRL, we blast off into space as Captain English to conquer new lands for a post-brexit British Empire.\n\nWhile the story itself borders on the ridiculous, the humour is consistantly on point. The graphics and voice acting are top shelf. I played from beginning to end twice with nary a glitch. Character movement and inventory control took a little experimenting to learn, but after that I was off to the races. The g', 'Fun while it lasts, but very short with an abrupt ending. It appears to have never been truly finished and this may originally not have been intended to be the full game.\n\nCan''t honestly recommend buying this for this price.', 'Mostly Positive', 77.61, 4.70, 3.48);
INSERT INTO reviews VALUES (7723, 488860, 8523, 'Crazy how far this series came, from a mid animation to the front page of newgrounds, to a flash version of this game, and now a fully fledged product, with mod support.\n\nIf you aren''t familiar with any of that, it won''t matter, because the game is good regardless.', 'not enough big oily men, smh', 'Overwhelmingly Positive', 96.90, 213.20, 213.08);
INSERT INTO reviews VALUES (7725, 488920, 284, 'Personally, this game brought back some fond memories of "Punch Out" from back in the 8-bit heydays. Good game and the only boxing game I bought in VR so far BUT...If anyone planning to buy this has a quest 3 or quest 3s, I''d say do not buy the steam version. Go to the Meta store and buy it there because devs aren''t implementing the mixed reality update on steam games where Meta is. Nothing like fighting these characters in your living space and seeing them standing in your living room. Until we', 'fun but only 6 bosses', 'Mostly Positive', 78.52, 4.23, 0.87);
INSERT INTO reviews VALUES (7728, 489020, 105, 'Is a review really necessary here?  \nGrow some digital ganja whilst smoking some real ganja.......\n.\n.\n.\n.........life explained!', 'Bought this game as my first real "garbage game" purchase, thinking, "Haha, what''s the worst that could happen?" The worst that could happen is that you play this game.', 'Mixed', 54.29, 419.60, 1.97);
INSERT INTO reviews VALUES (7735, 489140, 441, 'It was good (even for 2 hours), but the game needs optimization. I''ve been constantly hearing how my controller was connecting and disconnecting at the same time. I don''t know why this is happening, but it is what it is. Also, crashes at the end and some stutters, when enemies pop up.\r\n\r\n10 punches out of 10', 'Act 1 is fun all the way through. But after that the game just keeps alternating between "huh that was neat" and insane levels of annoyance? I feel it mostly comes down to how the game just keeps throwing dozen and dozen and dozen of enemies at you. It gets even worse when it happens in waves and you have to re-do the whole thing because some rando threw one grenade you couldn''t react to in time. I feel this was done to give the combat more of a "umph" because otherwise going 1 to 1 with an enem', 'Very Positive', 88.21, 5.10, 7.70);
INSERT INTO reviews VALUES (7741, 489360, 708, 'Good game.... One small issue tho, I can''t get passed the loading screen. It''s too scary.', 'I was pregnant when I played it and when I got jump scared i had a miscarriage', 'Mixed', 68.93, 1.12, 0.15);
INSERT INTO reviews VALUES (7742, 489370, 119, 'The review:\nSo far, the game seems like a great turn based strategy game with a disease stopping theme. It reminds me of Plague Inc. in the way the disease spreads and you must stop it. It also has the characteristics of other turn based strategy games in that you try to make the best decisions each turn to achieve the goal. You have several functions your team can do to research tech, cure parts and eventually the entirety of the disease, quarantine cities, establish more sources of income, and', 'Not worth it. Plague Inc is way better.', 'Mixed', 62.18, 3.48, 2.63);
INSERT INTO reviews VALUES (7743, 489380, 414, 'Cant stop, wont stop', 'Great game. Sole developer seems to have been hit by a bus and the backend servers have been offline since 2020. Should be removed from sale.', 'Very Positive', 89.61, 8.27, 2.83);
INSERT INTO reviews VALUES (7746, 489520, 644, 'good game :)', 'Used to be good, is quickly turning into just an abandoned cash grab. Cash purchases have become over priced and past purchases have been extremely devalued. Slap in the face to customers, wouldn''t recommend. Feels like the company was bought out and it''s just a cash grab now.', 'Mostly Positive', 78.88, 30.65, 165.40);
INSERT INTO reviews VALUES (7750, 489600, 440, 'O WOW', 'Cant skip the tutorial which takes 10 minutes, so i cant play this anymore.  It use to be cool but im not doing a tutorial every time.\n', 'Mixed', 66.14, 30.15, 66.22);
INSERT INTO reviews VALUES (7751, 489610, 195, 'bro skipped leg day', 'I paid $1.65 dollarydoos (Australian dollars) and at that price, the game did its job - a silly clicker game that has as much depth as a schooner of beer. \nThe story is bad, the graphics are felt like they were sticky taped together with bought assets. Upgrades don''t really feel like much and I never had any of the black market requests. And even if I did, the bounty didn''t make any of it worth it.\nAt full price though, I don''t think it''s worth the money or effort.', 'Very Positive', 85.64, 14.17, 6.17);
INSERT INTO reviews VALUES (7752, 489630, 4788, 'Nothing is balanced and it should be kept that way. Fun game to play with friends. Pick it up on sale but not a full price kind of game.', 'Slitherine wants to slither their slimy little fingers on into our wallets for crap content per DLC. Tired of piecemeal DLC, this game is becoming full of it. I will not recommend it or play it until they are done trying to pry our money from our fingers for overpriced minimal content per DLC.', 'Very Positive', 81.93, 253.80, 63.37);
INSERT INTO reviews VALUES (7760, 489830, 115179, '-Spends more time on nexus mods than ingame\n-Hates nexus and deletes mod files\n-Play for a few hours w/ no mods\n-Watch a cool mod video\n-Repeat\n10/10 would delete mod folder again', 'Creation  Club sucks. Took away key free mods that improved the gameplay. It''s sad because it''s like this for FO4 as well. I don''t care that they added some free mods to the anniversary edition, destroying something the community built is not okay. I kinda hate Bethesda', 'Very Positive', 94.65, 19.90, 37.02);
INSERT INTO reviews VALUES (7762, 489930, 109, 'A much better game than the Episode 1. Now with proper puzzles, an enjoyable story that actually feels like something, and more puns and references.\n\nIt is still not a quite perfect game, dialogues, interactions and animations constantly bug out and while it''s not on the level of being in an unplayable status(at least it was fine for me to progress till the end), it can certainly be distracting enough to drop to a certain crowd.\n\nConsider the first one as a long introduction for the core charact', 'I really enjoyed the first game, but I cannot recommend this one.  It''s filled to the brim with bugs, ranging from animation glitches, dialog loops and I finally hit a point where the game consistently freezes.  Now when I continue my current save it just freezes immediately and the game crashes.  It''s pretty much unplayable at the moment.  This is made all the more frustrating by the fact that this game''s release was even delayed a few months and yet it still seems unfinished.  Perhaps they''ll ', 'Very Positive', 80.73, 6.92, 6.08);
INSERT INTO reviews VALUES (7763, 489940, 8827, 'I would absolutely rip this game now if people were still playing. I really loved playing and had so much fun on faceit ranked matches. Honestly had no complaints about the game at all. I''m very confused why it died... :(', 'When this game originally launched as Battalion 1944 it was amazing. It had the old school Cod 4 Promod feel and mechanics. It had a small but serious player base, and everyone was generally nice. There were tournaments, competitive teams, all that normal jazz.\n\nThen they completely abandoned it. Went silent for years, came back and announced a new game literally called "promod",\nthey let that bs sit in dev hell for like maybe 6 months to a year, and then cancelled it. \n\nThis game is dead, any f', 'Mixed', 60.08, 91.68, 112.95);
INSERT INTO reviews VALUES (7767, 490110, 2489, 'The gameplay is good, and the graphics are beautiful. However, the AI is not very good, and there are a decent number of bugs (though none game-breaking so far). \n\nOverall, it''s a good game that just needs some bug fixes and AI improvements. Hopefully they will also add more content to make for a even better sandbox experience!', 'It''s a good and fun game overall, but it''s missing some basic polish. For example, after zipping up dead bodies, they still just lie there, which really breaks immersion. When an escort unit arrives, they walk the criminal away on foot and leave their car blocking the road. There''s also no option to tow abandoned or illegally parked vehicles, which feels like a big oversight for a game in this genre. Movement is another issue: it''s clunky, and your walking speed doesn''t match your partner''s, whi', 'Very Positive', 88.43, 24.05, 14.08);
INSERT INTO reviews VALUES (7773, 490280, 725, 'one of the reviews said that this game is a rough gem, i completely agree.\r\nthis game has so many interesting features, so many great elements that you can enjoy for hours, but it still needs some polish in order to be a complete gem, if this game continues to get more and more updates, i think it''s safe to say that it will be among the best games ever made, honestly it can even compete with terraria if the updates try to cut some of that rough edges that this game has, i really do look forward ', 'Big grind and pain in the ass, the game still has game breaking bugs, saves can be overwritten and you can lose your progress, the game isnt very original in general, exploration is boring and in total progression is extremely linear. Youd be better off spending your time on Planet Centauri or Alchemage than this.\n\nAfter 7 more hours I can say that the game is growing on me with its pleasant music and more open areas. The devs put plenty of time into how much content there is down the line but t', 'Mostly Positive', 79.31, 7.27, 39.58);
INSERT INTO reviews VALUES (7776, 490370, 299, 'I have owned and played this game since release, still have the physical copy! one of my all time favs.', 'Terrible game balance... Either the AI is an absolute joke, or the AI is stupidly over powered... I should have spent the $3 this cost me on weapon skins, as I''d have gotten better value for money...', 'Very Positive', 86.96, 63.45, 8.93);
INSERT INTO reviews VALUES (7780, 490450, 210, 'Beautiful game with somewhat lackluster combat and stealth.\n\nI actually really enjoyed the switching camera forcing me to develop spatial awareness of all enemies and possible paths.', 'I remember this game being a lot of fun, but the multiplayer does not appear to be working. The server list is completely empty, and Steam friends are unable to see or join my online games. Friends playing through Amazon games are also not able to see or join servers. \n\nDo not buy if you wanted to play this game with friends.', 'Mostly Positive', 70.00, 5.50, 0.17);
INSERT INTO reviews VALUES (7783, 490820, 108, 'Just a clicker game.\r\nYou can earn achievements.\r\nAnd you can get trading cards too.', 'You jump over a clock 1000 times and tell me if that is fun or not.', 'Very Positive', 81.48, 17.63, 0.27);
INSERT INTO reviews VALUES (7789, 490930, 151, 'Rating:6/10\r\nCompletion difficulty:3/10\r\nThis game plays similarly to Papers please, in my opinion. In some ways, it may just be more complex but lacks a time limit (as far as I know). I''m less a fan of the graphics but the story may also be more developed. Music isn''t as great though. The game goes a tad too long for my taste, but it''s still pretty nice for the gameplay. Try it if you enjoyed papers please and aren''t tired of the whole "privacy breached in a dystopian world" setting.', 'It was alright. If just alright is good enough for you, and you enjoy these kind of investigative sim games, I might suggest getting it on sale. It''s nothing to write home about though, and I don''t think I''d encourage a friend to get it. \nI was severely dissatisfied with how railroaded the story was.   When given a chance to help the DoL or anti-government agencies, you''re forced to help both or you lose the game. There are several mechanics that seem pointless to the game itself. There is a dat', 'Mostly Positive', 74.17, 47.50, 19.85);
INSERT INTO reviews VALUES (7793, 491000, 148, 'A one button platformer where the gravity switches on each press. Plenty of levels and difficulty.', '2.5/5\nRelatively common concept, execution is average, in fact bugs like non-working gravity change on button press - make the game harder than dark souls or whatnot. The game will damage your nerves if you want to 100% it.', 'Mostly Positive', 70.95, 1.78, 3.60);
INSERT INTO reviews VALUES (7796, 491040, 556, 'Pretty hard but rewarding arcade experience, this game is basically  Wild Guns  (SNES) with a cyberpunk touch.\n\nThe music is fun to listen and perfectly matches the gameplay, really like the FM synth-bass the tracks use. The VA is funny (albeit a little cheesy/bad at times). Controller-wise it''s perfect, feels just as it should. Visually it''s OK, could had use a little bit more polish in some of the pixel art.\n\nHighly recommended if you''re into challenging arcade-type games!', 'starts off way too hard, way too fast', 'Very Positive', 93.53, 3.48, 0.37);
INSERT INTO reviews VALUES (7799, 491090, 175, 'As a person who has near 200 hours on ant queen i can confidently say that this is where its at. The theory that playing for 24 hours straight will turn you into an ant has been busted by myself. After you touch this insane game you''ll never want to play another game again. Still haven''t beat and probably never will but perhaps in another 200 hours i''ll ascend to the heavens above and finally turn into an ant', 'It costs way too much for a game like this', 'Mixed', 66.86, 195.23, 21.25);
INSERT INTO reviews VALUES (7809, 491280, 249, 'I love this game because there is my dream car Skyline R34 <3', 'What the crap is this? The physics are nonsense, there''s no controller support, the menu looks slapped together with a bunch of broken buttons, the graphics are weird and shimmery, and the car won''t shift most of the time. Nope!', 'Mixed', 46.59, 50.10, 2.48);
INSERT INTO reviews VALUES (7810, 491330, 124, 'Fifth one in a series of clear the road type time management games. It is just more of the same and I enjoyed my time with it.', 'Stuck workers, softlocks, and repetitive mobile copy-paste gameplay make this title boring and overpriced. Avoid for better options.', 'Very Positive', 91.94, 11.65, 3.05);
INSERT INTO reviews VALUES (7820, 491530, 536, 'it was wery good.\r\n', 'Too many bugs. Couldn''t even get past a mission because of the amount of bugs.', 'Mostly Positive', 76.49, 11.00, 0.85);
INSERT INTO reviews VALUES (7821, 491540, 1405, 'EN: The game has some to offer for those who are looking for it, but for most it''s not there yet. The core gameplay elements are present, in that there are a range of routes you can drive in a 1:1 recreation of Berlin in realistic vehicles, but nothing beyond that. Even though the graphics, sound and physics are excellent, the optimisation is just not there; I have an RX 5700 XT and I only manage to hit ~30FPS with high settings, despite its system requirements from which I assume I could get mo', 'The Bus had great potential when it was first announced, but after three years, it remains poorly optimized and plagued by lag issues. Despite the intriguing concept of a realistic bus simulation, the technical shortcomings overshadow the gameplay experience. Frequent stuttering and frame drops make it frustrating to play, detracting from what could have been an immersive journey. It''s disappointing to see such promise go unfulfilled, leaving players hoping for improvements that seem to be takin', 'Mixed', 69.54, 26.50, 8.80);
INSERT INTO reviews VALUES (7834, 491950, 4648, 'Acting as a sort of Big Brother VN version of Deathtrap Dungeon, you are the "villain" behind the screen of a dystopian (?) surveillance project. I add a question mark beside the "dystopian" descriptor, because in a fairly surprising subversion of expectations, the group of people you are watching are every bit as awful, shallow, annoying, and at least in a couple of cases, actually dangerous and crazy as to justify using such a program. \n\nIn any other hands, this game would have the government ', 'doesnt let u actually investigate. more like a mindless click and drag where u dont have to understand anything and just loooking for the already highlited clues.', 'Very Positive', 90.83, 8.93, 0.52);
INSERT INTO reviews VALUES (7838, 492150, 143, 'Mario Maker meets Dark Souls (meets LEGO).\n\nWhat more could you want?', 'DLC in an early access game? I can''t support such a terrible money scheme and my review stays negative until they stop this.\n\nThe game is in early access. That means all content being added should be content for the full game. So why are they locking it behind a paywall, when there isn''t enough content as it is and the game isn''t even out?\n\nEDIT: They have resorted to updating the game as usual, but now releasing the content as "free DLC" to make themselves look good, despite this content being ', 'Mixed', 66.43, 37.17, 2.18);
INSERT INTO reviews VALUES (7844, 492230, 534, 'Brothers, don''t write it does not work on linux, it''s heresy.  Used blessed Proton db page and simply install proper version, brothers. You can mislead other brothers writing such unholy verses, brothers. It runs smoothly (blessed be machine spirit) and xenos can still bite your red (or blue, white or even yellow) buttocks off, brothers. Still not for weak brothers this game shall be, but for brothers who really wants to crack their implants on this, brothers. Emperor protects brothers. But not ', 'WARNING: as of late October 2024 (for Halloween sale), be aware that for a year or two already, this game crashes after loading screens due to having an outdated security layer access coding. This is a problem with the Unreal 4 engine on which this game was built; some devs have gotten around to patching their games with updated SSL coding but this developer hasn''t for this game. The only way around it, aside from running it under older operating systems (assuming Steam even lets you do that any', 'Mixed', 62.55, 4.57, 7.63);
INSERT INTO reviews VALUES (7847, 492290, 136, '⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀', 'combat system felt too simple, maps choices felt shallow, and the combat system revolves around what felt like click spam leading to a boring experience. \n\nThe writing is suppose to be comedic, but the dialog drones on and on with the joke basically being "look how stupid and silly RPG dialog is" but thats the only joke and the long winded dull writing gets old in about 2-3 minutes.\n\n20$ is way over priced and i quickly refunded it. If it were only 5$ i might still have refunded it. Its just was', 'Mostly Positive', 78.68, 158.65, 0.38);
INSERT INTO reviews VALUES (7853, 492500, 174, 'Very basic dungeon crawler that will scratch the dungeon crawler itch for most people. It''s not up to the level of Legends of Grimrock, but not many are, but it''s a good classic dungeon crawler like the Eye of the Beholder style crawlers. A good indie effort.  \n\nIt was good fun and takes anywhere from 4-6 hours per dungeon run. I finished it a couple of times to use all the classes. \n6.5/10', 'sorry, but: NO. The malus for turning away from enemies is such a bad design decision for a game like that, I just can’t get past that. This makes every encounter pretty boring, because yes, I can click on my mouse button every time my attack is ready. Really exciting. It’s a pity, I love games like Beholder, Black Crypt, Grimrock. I adore Dungeon Master. But this one – not too good for me. But – as always – give it a try yourself, you might like it 🥳✌️', 'Mostly Positive', 74.71, 23.92, 4.50);
INSERT INTO reviews VALUES (7861, 492720, 9216, 'Tropicans await elections. And they will continue to wait, until El Presidente is ready, which might take a while.', 'Pretty similar to previous versions of Tropico. In general the game works fine & is entertaining to play. However there is one Massive reason I cannot recommend it & have uninstalled it. The game now punishes you quite badly for not buying DLC. I received a "mission" that required the purchase of DLC; the negatives for not buying the DLC was big enough to ruin my island. This is a horrible sales practice.', 'Very Positive', 86.94, 37.63, 13.35);
INSERT INTO reviews VALUES (7869, 493060, 131, 'It''s combat for the 2600k. \n\nGood solid action for one to four players huddling around your medium sized monitor screen to better recreate those retro times of you playing on a 13 inch tv grappling your atari controllers.', 'Doesn''t work with Steam Link and Controllers. So senseless for ne, sorry.', 'Very Positive', 82.44, 3.27, 0.10);
INSERT INTO reviews VALUES (7870, 493080, 243, 'So far, so good, and better. This game might not make the most spectacular first impression, but it''s made with skill, care and subtle charm, and despite being a card-based sorta-roguelite, it is most decidedly NOT a Slay clone. But given that it came out two years before Slay, perhaps this shouldn''t be surprising :)', 'I love roguelike card games, but I feel like I should have listened to the negative reviews with this one.\n\nThe mechanics are all quite cool, but for me the entire design falls apart on one fatal flaw. I usually play these kind of games to do some quick up to one hour long runs in the evening. However, with this one, two evenings in a row, the runs ended up in a lengthy slog that almost lasted past midnight. And the worst thing was that the gameplay did not even change very much during those 2+ ', 'Very Positive', 85.19, 5.57, 6.57);
INSERT INTO reviews VALUES (7874, 493200, 1426, 'Go in blind. No guides, no achievements, just enjoy the story.', 'Warning! This game has many mental health triggers and gets into heavy emotional topics. This is not just a casual light-hearted puzzle-game. The look of the game is beautiful, and the quality of puzzles makes for a very engaging game. The tone shifts quite dramatically the last third of the game. I should have done more research before buying, but I assumed based on the description it wouldn''t be so dark. I would recommend based on quality of design, but the story line was not for me.', 'Very Positive', 88.64, 7.90, 10.28);
INSERT INTO reviews VALUES (7879, 493340, 30266, 'Having left a negative review for the sequel I feel it''s only fair to leave a positive one for this. It''s a great game, which has provided me with years of entertainment and the Steam workshop allows for plenty of customisation.\r\n\r\nThe only negatives are the poor optimisation and the path system, but overall it''s brilliant.', 'So you think, I want a newer rollercoaster tycoon game.\n\nYou buy this.\n\nYou''re barely able to figure out how to build.  You keep googling things to ensure your not an idiot.  It quickly becomes a chore...you uninstall it and realize how far ahead RCT was and just play that instead.', 'Very Positive', 90.69, 1892.95, 4.03);
INSERT INTO reviews VALUES (7888, 493490, 5914, 'was speeding when i ran a red light and hit some pedestrians crossing the street, but i drove away, got home and booted up the game', 'Horrible! if I get one step wrong in training it forces me to restart the whole thing. When loading open world, game crashes because it can''t load some NPC''s texture even after downloading the old microsoft redistributable. Moreover, game was released in 2016 but looks like it came from 2007. FPS is so slow despite my graphics being medium/low. it feels like playing someone''s college project than an actual game. waste of money!', 'Mostly Positive', 73.93, 39.60, 0.32);
INSERT INTO reviews VALUES (7890, 493540, 423, 'The beginning with a car crash looks like a very cheap trick to catch your attention but the theme of the game is built around this incident and is kept in line. The gameplay is light - primitive fight system, no hair pulling puzzles, no movement challenges and it doesn''t need it though. It''s a comfortable walkthrough with cozy arts, enjoyable songs and without plot twists - everything is going to be fine.\n\nOverall It''s just a nice game to spend an evening.', 'If there was a "Meh" score, I would have picked that.\r\n\r\nThe game is... entertaining enough, the thing is that it´s also tedious and boring at times. I think this game desperately needs a "fast travel" option, I wanted to revisit other places but thinking of going at the slow pace the main character goes, and thinking I had to cross over ALL the place to go back to the first one and returning... yeah I was not going to do that.\r\n\r\nControls are ok, but bumpy. Concepts are really nice but some exe', 'Very Positive', 84.63, 5.68, 8.23);
INSERT INTO reviews VALUES (7891, 493580, 103, 'Some of these are okay. Some are rubbish. Some won''t even launch. It''s a case of you get what you pay for.\n\nI was torn between "yes" and "no" for recommending, but decided to think positive today. Only buy it on sale, and don''t expect too much.', 'Half my games in the bundle wont load/open', 'Mixed', 51.46, 8.93, 26.43);
INSERT INTO reviews VALUES (7897, 493720, 433, 'Given that this game was made by a single person over a span of 20 years, it is very impressive. The game was released in 2016 and I played this in 2025. It is showing its age in terms of graphics, but it''s fine. There are no profiles or multiple save features. I presume if you quit the game it will return you to your last checkpoint, but I played this in one sitting so cannot be sure. Frustratingly, there are no options for autorun or toggling music. Audio queues are helpful in the game and I w', 'I wanted to like this game, but it ended up being a big miss for me. The first half hour or so, when I was still exploring the minimal game world, was enjoyable, but once it came to crunch time and I had to really solve puzzles... I could figure out almost none in this game. Maybe I was just in the wrong headspace when playing, I don''t know, but I ended up rather quickly running out of options and resorting to a walkthrough for puzzle after puzzle. And rather than thinking "Why didn''t I think of', 'Mostly Positive', 78.29, 3.52, 2.45);
INSERT INTO reviews VALUES (7903, 493840, 1326, 'I recommend the game NOW because Maximillan is coming out with MvCI Beyond tomorrow and it is definitely worth it! Only reason I bought this game today is because of his project along with the 40 fans he worked with. Great job and looking forward to it!', 'They forgot to put Wolverine in the game.', 'Mixed', 65.54, 6.48, 0.92);
INSERT INTO reviews VALUES (7904, 493900, 4860, 'Very much in the spirit on Dungeon Keeper, but with more over the top humour.  The voice acting / narrating is especially fun.  Do NOT expect a very serious game.', 'Accessibility is bad here. I can''t pause and check things out. I can''t slow time. The game constantly throws 2-3 things at you in two different levels of your dungeon. The controls for you units are different on the different maps. It''s just a cluster of BS and I just want to build a dungeon. The creative design to make every character complain about the narrative is a choice that''s for sure. It just get super old listening to the same narrator trash talk you for the third time you run a mission', 'Very Positive', 92.47, 39.87, 10.37);
INSERT INTO reviews VALUES (7913, 494150, 3062, 'I''m too fat for this game shit had me sweating like i ran a mile', 'What moron invented that a VR game had to require 20 meters of space, it''s like playing in a gym? I am also annoyed that the player cannot move in the menu via teleport, the body movement is not well executed, I am often out of space and I cannot even come to consider myself. The game itself is good but these flaws spoil the game !!! Better is Pirate Version', 'Overwhelmingly Positive', 95.79, 1.50, 0.55);
INSERT INTO reviews VALUES (7917, 494230, 215, 'It''s a pleasant enough game but will be very easy for seasoned time management game players. It''s nice to have a proper story behind the levels, and the characters were interesting. I just wish it had been more challenging.', 'I liked the game, but I cannot recommend it as long as it requires an always online connection. This is ridiculous, it''s a single player game!', 'Very Positive', 93.49, 8.53, 12.02);
INSERT INTO reviews VALUES (7923, 494360, 116, 'An excellent point & click horror detective game for true puzzle fans. I play it every few years when the puzzles fade from memory, and it''s enjoyable every time. The game does not hold your hand, and the world - with numerous, diverse, and interconnected locations dripping with atmosphere - can be explored openly, collecting clues to various puzzles along the way. Settle in with pen and paper for taking notes (and a phone for taking photos), and understand that you will wander around aimlessly ', 'I bought Barrow Hill out of nostalgia having originally played it in the mid 2000s. However, revisiting it reminded me of all the frustrating things about the game that I''d somehow repressed. First, the game can be incredibly glitchy at times with movement arrows not appearing or having to severely offset the cursor to perform an action. And speaking of movement, it''s very counter-intuitive at times. Other games that require you to click at the screen edges aren''t nearly so finicky. Also, while ', 'Very Positive', 85.34, 7.88, 16.27);
INSERT INTO reviews VALUES (7925, 494430, 1179, 'Praey for the Gods offers a captivating survival experience set in a frostbitten world. You play as a lone hero exploring a desolate land plagued by massive, enigmatic giants. The game excels in creating a hauntingly beautiful atmosphere with its striking landscapes and towering foes. \n\nThe core gameplay revolves around climbing, battling colossal creatures, and managing your survival needs in a harsh environment. The climbing mechanics are engaging, though they can be a bit finicky at times. Th', 'extremely slow and clunky, really wanted to like it but guess ill try that new SotC clone with magic, looks pretty fun', 'Very Positive', 81.93, 5.08, 1.20);
INSERT INTO reviews VALUES (7931, 494670, 180, 'Good time killer', 'Clunky and not optimized. Every action was made so unnecessarily difficult that led to the game being unenjoyable.\n\nThe prospect was cool, the execution is terrible.\n\nYou end up feeling like a cookie clicker game because the gameplay just dwindles to:\n\ngetting the best contract>assigning driver>repeat', 'Mixed', 56.67, 20.20, 0.72);
INSERT INTO reviews VALUES (7933, 494720, 230, 'Very fun little game, You can definitely get really good at this and last VERY long, but I really wish they made it more obvious how you can right-click on tiles to see their current and potential abilities. \nFor the longest time I thought you could ONLY see the abilities while you were choosing new tiles or upgrading, and it was VERY hard to plan, and I had to try and make paper lists of the abilities - later on I discovered you could right-click to remind you what the abilities are.', 'This is a unique and clever puzzle game.  It''s simple to learn and you''ll understand the mechanics and strategies in a matter of minutes.  Your goal is to survive as many turns as possible - with each turn becoming more difficult - before inevitable defeat.  Each game plays out similarly but with enough randomization to keep you thinking. \n\nMorphblade is a nice little game and should really be a "maybe".  I don''t enjoy the "beat your own score" genre and got bored quickly.  However if you enjoy ', 'Very Positive', 94.35, 26.93, 0.57);
INSERT INTO reviews VALUES (7934, 494730, 361, 'The mechanics aren''t as technically complex as Two Point Hospital but the writing''s good for a chuckle, the mission gimmicks are fair and not frustrating and it''s only £25. Plus the devs clearly have the same autism as me so I want them to keep making spiritual successors.', 'I''m a fan of what this company has done, and one of the old Bullfrog fans who is still bitter. Unfortunately, I just can''t recommend this game.\n\nThis game has good artwork, and writing. The humor is great, and they nailed the creative aspects of this game, imo. I especially like playing a game that is actually positive, as it involved actually helping people rather than killing. That''s a good change.\n\nI completed the story and the game got bored after only 27 hours of play time, and I''m not even', 'Very Positive', 88.92, 22.42, 27.57);
INSERT INTO reviews VALUES (7937, 494810, 180, 'Even if the graphics are not as best as they can be, this game for me is what VR is all about. Room scale exploration was invented for these types of games. This is the game I enjoyed most to be honest. I think "quests" and room escapes are much more suitable for VR than timer based, you are in the middle, teleport style FPS games. I really forgot I was not in the room, this was fenomenal. I WANT MORE!', 'Pretty much just a tech demo. Worth it when it''s on sale for a dollar I suppose, but it''s probably not worth your time in 2024.', 'Very Positive', 87.22, 1.05, 8.12);
INSERT INTO reviews VALUES (7940, 494840, 10200, 'This is some serious next level strategy, easy to play (kind of) difficult to master...but when you start getting good what a dopamine rush it is when you sink that first destroyer.\r\n\r\ngood stuff', 'Honestly don''t recommend for new players to the genre. The tutorial is completely broken (as I found has been reported for quite some time by players when I Googled why I was stuck on a tutorial mission.)\n\nIt starts pretty strong, holding your hand in all the right places at the beginning. Then when you get to the torpedo tutorial, where you''re meant to attack a ship, the whole tutorial goes hands off and doesn''t give you ANY information on what to do next.\n\nIt turns out, according to more exper', 'Very Positive', 85.22, 62.20, 14.17);
INSERT INTO reviews VALUES (7948, 495050, 734, '"What am I Fighting FOOOOOOOOR?!"', 'The games are pretty hard, if you suffer from skill issues (like me) you will probably experience pain.\nIt does run on Steam Deck, but it seems some Proton updates/high amounts of storage used slow the game down. Also likes to eat battery.\nNo idea why DRM needs to be put in a collection of 1 SNES game, 1 PS1 game, and 2 Wiiware (I know 9 and 10 were also on Xbox 360 and PS3)\nJust get an emulator/buy on another platform.', 'Very Positive', 82.70, 28.92, 12.27);
INSERT INTO reviews VALUES (7950, 495110, 319, 'A nice conclusion to the series. Even though i liked the parts before more, this part is also very well done.I liked the animations in the second part more but this game is also very well made adnd well made. It was pretty fun and the bonuslevel gave a nice insight of what happend before. Another great artifex mundi game. I can really recommend this game', 'The worst entry in the series by far.\nHidden objects scenes that were a complete mess. No pun intended.\nScreen transitions that take a long time with no apparent reason whatsoever.\nThe story was very weak and a lot of scenes didnt even make sense.\nThey clearly didnt know how to end the saga.\n\nAs pros, the music is ok, very good graphics with a REALLY good scene at te very beging but quality falls completely short after that. I couln''t wait for it to end. Enigmatis 1-2 are way better than this on', 'Very Positive', 92.16, 8.13, 6.58);
INSERT INTO reviews VALUES (7951, 495140, 1806, 'Naruto is better than One Piece', 'There is no story mode in this game, more like flashback missions which show a barebones version of the events happened. And to unlock those missions, you need to do side missions like chasing dogs on trees, and finding Konohamaru, which is tedious and annoying. I bought this game because I couldn''t afford a PS3 back in 2008 and saw this on the shelves, and as a Naruto fan, I always wanted to try it. Had I played it back then, I probably would''ve enjoyed it, and missed out on the glaring flaws t', 'Mostly Positive', 76.63, 23.43, 8.22);
INSERT INTO reviews VALUES (7954, 495280, 936, 'I am a fan of nippon ichi games, but this one is definitely up there. The writing is peak fiction, and everything feels natural to the world, where characters have flaws and convictions, I would watch a full Disgaea 2 theatrical performance if possible, I love how they do the inner monologues with the screen putting the spotlight on the character by dimming the surroundings. The game play is standard Disgaea, but it was very interesting to get appearances from their other franchises, Phantom Bra', 'Great game but I can''t recommend it unless they fix up this PC port', 'Very Positive', 91.77, 56.33, 6.58);
INSERT INTO reviews VALUES (7955, 495290, 280, 'Quite good for an slightly older RC flight simulator.\n\n9.0/10\n\nhttps://store.steampowered.com/app/495290/AccuRC_2', 'abandon-ware and bugged i want a refund!', 'Very Positive', 87.50, 643.00, 6.30);
INSERT INTO reviews VALUES (7960, 495420, 19599, 'Highly recommended, i wish it had more polished co op and more deep story, but beside that its one of the best zombie sims out there.\n', 'Requires sign in to Xbox Live account. Fine. Not showing the requested permissions, but instead the message "The publisher has not provided links to their terms for you to review," is completely unacceptable when data sharing is a requirement to proceed with sign in.', 'Very Positive', 86.85, 104.08, 0.17);
INSERT INTO reviews VALUES (7962, 495480, 200, 'I''ve messed around with it for a little - it''s pretty good.', 'Every. Single. Thing. You have to do in this software is an outright war.\r\n\r\nI am not kidding, you can get any of the big five full fledged commercial game engines and learn to build VN Maker itself in one of them before you will get basic things to work in this. It''s ridiculous how profoundly overcomplicated they made this software. Doing anything in this is a nightmare, the documentation is near-useless, and you will only find solutions to the infinite problems by accident while spending hours', 'Mixed', 56.00, 2023.87, 3.77);
INSERT INTO reviews VALUES (7970, 495720, 127, 'Fun game I liked it!\n\nShort and simple levels for fast in and out gameplay something you can speed run. More of an arcade shooter nothing to really think about just shoot, grab the keys, find some secrets, and get to the exit.\n\nIf you like Retro shooters check it out!', 'Intrude is very similar to Wolfenstein 3D, a game that hasn''t aged well, so I picked this up with the hopes of enjoying a very old experience that''s freshened up a bit. On the surface it''s lovely, but once you die you start that level again. Your health, armor and ammo carry over from the previous level. So far so good? Not for me. Right now I''m in a level with not much ammo to start with and there are lots of robots in the only corridor I can take. I welcome a challenge, but I''m not having fun ', 'Very Positive', 83.46, 3.60, 14.15);
INSERT INTO reviews VALUES (16167, 495890, 4023, 'Montaro is a hardcore PvE High speed game that will destroy you harder than any other game or boss in dark souls & Elden ring combined, faster than any situation in Helldivers, and you will have no one else to blame but yourself, as it slowly misleads you with its graphics, upbeat music, that slowly break your focus, lowers your guard, response time and background elements slowly melt with foreground leading to imminent death. Master all the obstacles, find weaknesses of enemies, chain up combos', 'Aside from meme value, Montaro is just not a good game. This is basically just a poorly designed old flash Newgrounds game.', 'Very Positive', 94.98, 4.62, 2.85);
INSERT INTO reviews VALUES (16183, 496250, 155, 'I own every table tennis game on the vive as of this review and until now, Pong Waves reigned supreme...This blows it and all other TT games out the water! The best physics, adjustable bats, excellent spin control, AI with a body, fun practice and challenge modes and best of all...\n\nWORKING MULTIPLAYER! \n\nSeriously, get this game now. Stop reading. Buy it. Now. NOW!', 'WARNING! Consider this abandoned by the developer. WARNING! \n\nOver 6 months past the promised launch date, read the early access notes before you consider taking a risk. The game content is solid in this current state it''s a good game, but when a developer fails to fully complete the game they promise then I won''t recommend it.\n\nWant a Ping Pong game, get Eleven: Table Tennis VR instead.', 'Very Positive', 85.16, 20.47, 1.67);
INSERT INTO reviews VALUES (16186, 496300, 3959, 'The map is too long. The game could be significantly improved by simply having the recruited run to camp instead of walking.', 'I both hate and love this game. It''s mega addictive and very satisfying if you''re doing well - but as others have pointed out, one mistake can cost you hours of gameplay. If it was possible to cancel building a wall or to control where my archers go/to which walls my catapult/knights go, then maybe I would change my mind but at this point, I can''t recommend this game.', 'Very Positive', 85.27, 8.20, 26.98);
INSERT INTO reviews VALUES (16196, 496450, 125, 'Jack is good for making maps. But steam kept bringing this annoying pop up requiring a fucking review. So here is it. Are you happ Valve Devs?', 'Seems like they completely gave up on improving or expanding the editor, or even fixing known bugs.  Just download the free version.', 'Very Positive', 89.60, 174.48, 0.28);
INSERT INTO reviews VALUES (16197, 496460, 2098, 'It''s an older game. has some lag issues, but still fun to play.', 'Do NOT buy this game. It is severely unfinished abandonware. The devs made a start on it, then just upped and left years ago.  But for some reason its still for sale on here.\n\n', 'Mixed', 62.39, 502.15, 0.42);
INSERT INTO reviews VALUES (16202, 496550, 215, '⣿⣿⡻⠿⣳⠸⢿⡇⢇⣿⡧⢹⠿⣿⣿⣿⣿⣾⣿⡇⣿⣿⣿⣿⡿⡐⣯⠁ ⠄⠄\n⠟⣛⣽⡳⠼⠄⠈⣷⡾⣥⣱⠃⠣⣿⣿⣿⣯⣭⠽⡇⣿⣿⣿⣿⣟⢢⠏⠄ ⠄\n⢠⡿⠶⣮⣝⣿⠄⠄⠈⡥⢭⣥⠅⢌⣽⣿⣻⢶⣭⡿⠿⠜⢿⣿⣿⡿⠁⠄⠄\n⠄⣼⣧⠤⢌⣭⡇⠄⠄⠄⠭⠭⠭⠯⠴⣚⣉⣛⡢⠭⠵⢶⣾⣦⡍⠁⠄⠄⠄⠄\n⠄⣿⣷⣯⣭⡷⠄⠄⢀⣀⠩⠍⢉⣛⣛⠫⢏⣈⣭⣥⣶⣶⣦⣭⣛⠄⠄⠄⠄⠄\n⢀⣿⣿⣿⡿⠃⢀⣴⣿⣿⣿⣎⢩⠌⣡⣶⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣆⠄⠄⠄\n⢸⡿⢟⣽⠎⣰⣿⣿⣿⣿⣿⣿⢀⣾⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣦⠄⠄\n⣰⠯⣾⢅⣼⣿⣿⣿⣿⣿⣿⡇⣾⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⡄⠄\n⢰⣄⡉⣼⣿⣿⣿⣿⣿⣿⣿⢸⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣧⠄\n⢯⣌⢹⣿⣿⣿⣿⣿⣿⣿⣿⢸⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⠄\n⢸⣇⣽⣿⣿⣿⣿⣿⣿⣿⣿⠸⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⠄\n⢸⣟⣧⡻⣿⣿⣿⣿⣿⣿⣿⣧⡻⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⠄\n⠈⢹⡧⣿⣸⠿⢿⣿⣿⣿⣿⡿⠗⣈⠻⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⡇⠄\n⠄⠘⢷⡳⣾⣷⣶⣶⣶⣶⣶⣾⣿⣿⢀⣶⣶⣶⣾⣿⣿⣿⣿⣿⣿⣿⣿⣿⠇⠄\n⠄⠄⠈⣵⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⢸⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⠄⠄\n⠄⠄⠄⠸⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⠘⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⠇⠄⠄', 'No.', 'Mixed', 42.79, 2.48, 24.92);
INSERT INTO reviews VALUES (16206, 496620, 597, 'Cute, straight forward, deck builder. Good unlock progression. No single path to victory and makes you change up your game plan. For the price, an easy choice!', 'Gets boring very quickly. The DLC makes the game worse, and it just doesn''t hold up  to modern entries into the genre.', 'Very Positive', 80.07, 56.02, 95.92);
INSERT INTO reviews VALUES (16212, 496680, 107, 'I am living the dream.\nMy employees are living the nightmare.\n\n10/10', 'Great idea, poor execution.', 'Mostly Negative', 32.71, 2.92, 0.92);
INSERT INTO reviews VALUES (16214, 496730, 204, 'good. just different enough to be  enjoyable.', 'i more or less liked the origional sorcerer king... dont get me wrong, it defintely had its flaws but i thought it was a nice new concept.\n\nNow this game... is basicly the same game with a new spell added... it leaves me verry disappointed. They did not even fix some of the bugs in the origional version.\n\nI am sorry but i cannot reward this kind behavior with a good review.', 'Mixed', 64.71, 23.83, 9.43);
INSERT INTO reviews VALUES (16217, 496760, 139, 'this game is a warm blanket for me from back when i was in high school.  if you get it, you get it', 'Crap. Don''t waste your time with this, does not worth it, Clicked every damn thing and still did not get the phone call. There''s absolutely zero feedback about what''s missing. The story is boring, the writing is sloppy.', 'Very Positive', 89.21, 460.53, 6.25);
INSERT INTO reviews VALUES (16221, 496890, 360, ' Big Brother is watching you. ', 'Another "game" that is a thinly veiled vehicle for the dev''s maudlin, barely-formed political opinions that he got from watching Netflix. He will probably pull this off of Steam once he gets out of high school and realizes how cringe it is', 'Mostly Positive', 78.33, 2.62, 1.05);
INSERT INTO reviews VALUES (16240, 497180, 1891, 'Got beat by some guy by the name of "WhyBeAre" or whatever in his DevilSport with some stupid modding done to it.\r\n15/10 would recommend.', 'Just play this shit. dont read the bad reviews', 'Very Positive', 88.10, 41.05, 2.23);
INSERT INTO reviews VALUES (16249, 497400, 233, '1 Moment Of Time: Silentville\n\nHas a total of 10 trading cards.', '2004 called and they wanted their graphics back. Cumbersome navigation and the map is no help at all. The whole game feels weird. Story line is hard to follow. The hidden object HOs are hard to see. All in all a very bad game. I will play it through, just to see how it ends, but I''m not putting my hope into it.', 'Mostly Positive', 72.53, 1.48, 52.00);
INSERT INTO reviews VALUES (16266, 497730, 146, 'Good game. \nThe Wardrobe - Even Better Edition5/10\nHeisen \n', 'Love the art, Easter eggs (that I was able to see in my hour or so of playing), and sense of humor, but I can''t recommend this because of the puzzles. I enjoyed the hour that I played, but then I looked at a guide to help get the ball rolling (as I couldn''t figure out next steps) and reading the guide really showed how unintuitive the puzzles are. None of the combinations of items or actions taken to move through the game were ANYTHING that I would have thought of doing and I don''t want to play ', 'Mixed', 65.75, 6.63, 1.07);
INSERT INTO reviews VALUES (16267, 497780, 313, 'Go play the free fanmade dlc "The Ice Palace" when you are done with this game.\r\nSome of the best puzzles i have ever played.', 'Well, that was a waste.  I started up "Recursed" and my very first "puzzle" turned out to be "what in the world am I supposed to be doing here and how am I supposed to do it?"  I looked at the controls in the menus (and both the menus and controls are horrible) and found nothing that would help me.  Looked around the Discussions and found nothing.  Ditto for the Guides.  So, back it goes and I''ll see if I can get a refund for the huge $1.99 ( :) ) I paid for it.  Not Recommended.\n\nDevelopers:  a', 'Overwhelmingly Positive', 98.08, 98.93, 0.25);
INSERT INTO reviews VALUES (16269, 497800, 260, 'It''s a good roguelike and well polished by a developer who is obviously a solid student of game design, but regrettably I think it''s just a little bit too short and lacking in depth to be satisfying for me as a "traditional" roguelike, speaking as a longtime fan of the genre. I understand this was no doubt an intentional design choice, but I must say I found myself missing the epic adventure part of rogueliking while playing Golden Krone Hotel even as I was very much enjoying not having my ass k', 'Hard to enjoy having read inflammatory comments against the genre by the developer.', 'Overwhelmingly Positive', 96.15, 17.33, 1.70);
INSERT INTO reviews VALUES (16271, 497850, 258, 'Reminds me of Warcraft, a game from my youth.  Very fun to play.', 'This game is basically a watered down version of Warcraft 3 with pseudo-8-bit graphics. Unfortunately, it''s not as fun as Warcraft III, and the campaign''s premise is really silly, so there''s nothing to be interested in plot-wise either. I know it''s purposefully breaking the fourth wall in a sort of satirical way, but like the rest of the game, it just comes across as bland and uninspired.', 'Very Positive', 80.62, 53.88, 0.72);
INSERT INTO reviews VALUES (16282, 498240, 6906, 'A truly Telltale-esque Batman story. While some technical aspects may be somewhat disappointing, the compelling storytelling and diverse characters create an engaging narrative that is perfect for Telltale fans and enjoyable for Batman fans alike.\n\n\n텔테일이 그려낸 배트맨.', 'WWBD? Turns out it''s not always what you think (or want).\n\nThis one just isn''t on the level of the best Telltale games. It feels more on-rails throughout, most of the choices aren''t compelling, and by the midpoint, the clunky storyline has become thoroughly nonsensical even by comic book standards. By Episode 4, I was just ready for it to be over.\n\nIf you''re looking for a game that lets you roleplay Batman in a satisfying manner, this isn''t it.', 'Very Positive', 85.61, 8.95, 7.68);
INSERT INTO reviews VALUES (16285, 498330, 512, ':3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3 :3', 'One of the most boring platformers I''ve played in ages.\nThe level design feels randomly generated.\nThere are a myriad of free platformers better than this.\n\n2/10\n', 'Very Positive', 92.58, 1.95, 0.32);
INSERT INTO reviews VALUES (16296, 498570, 108, 'it coo', 'The best baddest game ever', 'Very Positive', 87.96, 1.45, 0.22);
INSERT INTO reviews VALUES (16301, 498660, 107, 'amazing adventure.', 'not worth $5 price\n\ndecently worth 50¢ price\n\nmight crash your pc', 'Very Positive', 84.11, 7417.75, 0.68);
INSERT INTO reviews VALUES (16316, 499180, 675, 'If you''ve 100% beaten the original Braid before and were curious about what''s changed for the high res version: Literally nothing. You can beat the game again in exactly the same way pretty quickly and easily, since you''ve already done it once. The stars are still exactly as annoying to get as they were before. The only thing about the main game that''s changed is that the graphics are even better, which you can check for yourself with the press of a button.\n\nThe real value of Anniversary Edition', 'As a player who supported the game''s pre-order, I feel extremely disappointed. The developer drastically cut the price by 75% just one month after the game''s release, which is significantly more than the 50% discount given to veteran players who owned the original version during the pre-order period. This is truly disheartening.', 'Overwhelmingly Positive', 95.56, 20.80, 0.15);
INSERT INTO reviews VALUES (16324, 499440, 1640, 'Someone really put a lot of heart and brain into this game. Very calm, challenging to a certain degree. New mechanics come in very fluently and expand later.', 'Aesthetically pleasant and visually interesting, but ultimately uninspired -- less a puzzle game than the spacial reasoning portion of an IQ test given a graphics upgrade. The difficulty curve of klocki remains far too long at "insultingly easy" and barely passes into "mildly puzzling" at its peak. What challenge it does pose derives less from clever mechanics and intellectually stimulating puzzles and more from sometimes unclear rules and odd ambiguities caused by the game''s own, admittedly nic', 'Overwhelmingly Positive', 97.07, 1.95, 2.07);
INSERT INTO reviews VALUES (16325, 499460, 195, 'Tomato Jones is most likely the most thought-provoking and introspective indie games I''ve ever played in my life, this is the first time I''ve been made to feel such intense emotions and I can not recommend it enough, this is a hidden gem and once in a lifetime experience you WONT find anywhere else, to everyone at team tomato thank you for making this incredible piece of art to be enjoyed by generations to come.\n\nlove, the tonsil stone gamer', 'Idk if this game even legal, even if it''s a parody (Disney gonna kill anyone if they spot someone using logo design similarity from their franchises)', 'Mostly Positive', 78.46, 2.73, 0.60);
INSERT INTO reviews VALUES (16330, 499620, 193, 'If you ate something bad, or swallowed something you shouldn''t have, then I have just the right solution for you. Make sure to have a bucket ready, strap yourself in, and take a ride in the ultimate booster. Violent vomitting guaranteed.\n\nIn all seriousness, please don''t demo this to someone as their first experience. VR sickness is no joke, and it may avert them from ever using VR again.', 'This could be something cool. Unfortunately the games devs don''t care about fixing things like controllers not functioning, so you basically have something that does not work.', 'Mostly Positive', 76.68, 0.10, 1.33);
INSERT INTO reviews VALUES (16331, 499660, 1192, 'A good game for RTS and city building fans. Runs well on low spec pc''s', 'I wanted to like this game but it just isn''t good. The tutorial is probably the best part. Its a pretty decent overview of game mechanics. The graphics are pretty bad. The game play is repetitive. The combat and lack of saved files kill this game. In the tutorial it appears balanced but on the campaign its different.  combat overall is pretty slow. Archers appear to do no damage. At the start of my campaigns, two different ones, I have lost an equal battle by a significant amount. In the one bef', 'Mostly Positive', 77.60, 44.65, 13.58);
INSERT INTO reviews VALUES (16333, 499890, 114, 'You''re gonna wub every beat of it. High-energy rhythm based game-play set to a soundtrack that''s going to have you tapping your feet to it whether you''re a fan of EDM or not. Easy to enjoy and insanely difficult to master.', 'I love rhythm games but this one misses the mark - the combat mechanics ruin all the fun. I tried the demo for the second version and I still don''t like it. Try the demo first before buying to see if you''re into the combat mechanics - OST is top notch though.', 'Very Positive', 87.72, 17.78, 1.52);
INSERT INTO reviews VALUES (16344, 500260, 415, 'Bro Ive been wanting this game for 3 years and I finally have it. \r\n$17.99 for this game is worth it.', 'Don''t waste your money. Watch a 15 min video on Youtube and forget about it. It won''t get better.', 'Very Positive', 83.37, 58.68, 7.50);
INSERT INTO reviews VALUES (16354, 500500, 179, 'Watching VR P0rn is now as easy as the P0rnstars themselves...  Settings can be switched on the fly with a single hand.  Worth it.', 'Not working anymore', 'Mostly Positive', 72.07, 7.55, 7.58);
INSERT INTO reviews VALUES (16360, 500670, 173, 'i got this for free on epic games and then bought it on here, really fun and feels like you''re trying to beat your high score at the arcade. it''s a very simple shooter game tho so I would recommend getting it on discount.', 'It initially triggered nostalgia for 90s twin-stick shooters (previously know as top-down shooters), like Phobia II, Crimonsland, Ultimate Tapan Kaikki, and others. But it quickly outstayed its welcome, since there is not much here to keep me coming back when so many other things are competing for my time.\n\nAnd I get they are going for a style, but jeez the sound design and music are grating. Same can be said for the main character''s screaming.', 'Very Positive', 94.22, 9.52, 0.08);
INSERT INTO reviews VALUES (16363, 500710, 153, 'Love this game. It has such a peaceful vibe to it. Reminds me of UO but without the hassle (I love UO, but sometimes it could be overwhelimng). I tried Wild Terra 2 and it is good either, but still something draws me to the first installment now and again. My only complaint is how recipe learning works. I keep learning high end stuff without having learned its components. This is a bit frustrating, but again I am not about to win this game, I am about to play it.', 'Pay to win', 'Mixed', 50.98, 414.22, 0.32);
INSERT INTO reviews VALUES (16369, 500810, 1087, 'KILL GNOMES BEHEAD GNOMES ROUNDHOUSE KICK A GNOMES INTO THE CONCRETE SLAM DUNK A GNOMES BABY INTO THE TRASH CAN DEFECATE IN A FILTHY GNOMES''S FOOD', 'Currently unplayable on windows 11.  Getting constant crashes, infinite loading times.  Official and unofficial patches do not work anymore.  Something needs to be done or this game wont be playable in the near future.', 'Very Positive', 87.30, 4.92, 17.22);
INSERT INTO reviews VALUES (16378, 501080, 1126, '12 hours in and these are my thoughts. ? A great game but this needs to have rod fishing in too instead of going out to sea placing lines and then having to go back to port to rest or skip-time for 20 so hours then to go out and get the lines again. this is tedious. needs to be a skip time feature whilst on the boat. To go out and spend 20 mins to a couple of hours rod fishing from the back of the boat then go sell your fish would be a great starting feature of this game. Also have been between ', '10 hours of grinding, and i get the "something is obstructing your path" message while fast traveling to port... The AI ran me into a cruise ship and insta killed my boat and fuel bars. Then it spawned me with the starter ship, all my lines where near despawn times, my ship was gone. I literally lost 1.5 million in seconds because of a UI bug. now im back to the starter boat with 40k no line and 4 hours of play time gone... to no fault of my own. I will be getting a refund. F*** this game.', 'Mostly Positive', 78.24, 14.55, 28.15);
INSERT INTO reviews VALUES (16381, 501120, 174, 'Clock Simulator\n\nHas a total of 6 trading cards.', '\r\nJust another bad game with bad resolution support.\r\n', 'Very Positive', 85.06, 1.65, 1.87);
INSERT INTO reviews VALUES (16387, 501300, 15672, 'Amazing game with an amazing story. Short, it took me 3.5 hours to complete at normal pace. If you ever read the book 100 years of Solitude, well this is story is very similar. If you have not read that book, and did enjoy this game, then get that book and read it.', 'Okay, this family was… maybe… not very intelligent? Raising kids in a house where you can''t properly watch them, putting a swing at the edge of a cliff, forgetting your baby in the bath, letting your family work in a dangerous place while hallucinating, making your innocent daughter shoot a deer only for it to kill you instead (deserved), etc, etc, etc. Man, I can''t empathize with any of it. This is just the story of a mad family doing nonsense and creating their own drama.\n\nThe graphics and art', 'Very Positive', 94.24, 3.47, 3.85);
INSERT INTO reviews VALUES (16389, 501320, 501, 'Everything falls on my shoulders; I end up doing everything.\nAll the blame comes my way, while others do nothing but criticize me.\nOh, I just want to take them all down.\n\n\n누가 죄인인가.', 'RNG killed the cat.\r\n\r\nThey could have done with more Cthulhu horrors and less random generated stats for characters and outcomes.', 'Mixed', 67.47, 9.58, 8.83);
INSERT INTO reviews VALUES (16401, 501590, 3173, 'Сontrary to the original marketing strategy, this is still way closer to Call of Duty than to any classic run-and-gun kind of shooter.\n\nBut it is the most ridiculously entertaining Call of Duty campaign ever.\n\nIt''s gorgeous; every setpiece hits an absolute bullseye, every gun is fun to use, and nothing ever overstays its welcome.\n\nOh, and it actually has good writing. I know it''s kind of trendy to use the same "I will kill your diсks" clip and dismiss the whole thing as juvenile nonsense, but "j', 'This game is filled with sexist and homophobic charecters. the main villian says the f slur alot and it ruins the game for me. the interesting mechanics are the only thing that brings me back to this bad game.', 'Very Positive', 85.44, 7.70, 4.30);
INSERT INTO reviews VALUES (16407, 501790, 585, 'A solid 8. Modern and fresh point & click adventure. With a nice art and audio department, especially the english voice over, and storytelling is also great. The game has no exceptionally original aspects but that is neither a problem nor really needed from a point and click adventure. What''s needed is a good story and nice puzzles and this game has both. Definitely recommended.', 'This game starts out really strong. Cool concept, decent voice acting, real-life logic-based puzzles. The horrible jokes by the protagonist are forgivable for awhile but then the the writing takes a dive. The story tries to end itself quickly as you ponder the motivations of many characters. This game is not BAD, but it''s certainly not GREAT.', 'Very Positive', 86.50, 12.27, 10.33);
INSERT INTO reviews VALUES (16414, 501970, 100, 'You''re such a pretty girl, Blob.', 'GREAT GAME! \r\nTakes me back to my teen years. But sadly the game locks up and crashes WAY too often. \r\nThey''re relying too much on DOSbox, which hasnt been updated in years..... and is obsolete. \r\nI can''t even save my game easily..... which super sucks.', 'Very Positive', 82.00, 9.28, 27.72);
INSERT INTO reviews VALUES (16415, 501990, 208, 'just like i remember it. gods i love old sierra games. they were some of the best back then.', 'The game glitched on the final chapter and then wiped my save >:(', 'Very Positive', 87.50, 2.50, 18.15);
INSERT INTO reviews VALUES (16426, 502230, 177, 'I remember playing this back on Armor Games when I was younger and never managed to complete it, and I still don''t think I will! I only play on hardcore which is a big factor in this...\r\n\r\nI''ll see if I get time to give it another shot but generally a very plain standard dungeon crawler', 'Most of the positive reviews seem to be coming from people who remember playing the free browser version of this game years ago when they were kids. You know what, if Monsters'' Den had been available back when I was in school and looking for a way to kill time between classes (or during classes), I probably would have enjoyed it very much, and I would have fond memories of it now.\n\nBut I never played the browser version of this game and I feel no nostalgia for it. I am evaluating it as a standar', 'Very Positive', 93.79, 1.63, 6.13);
INSERT INTO reviews VALUES (16432, 502370, 805, 'another very very fun 40k TBS with some VERY large scale battles. I think the last mission in one of the campaigns had upwards of 40-50 fuckign squads of enemies/player controlled and took almost 2 hours to beat.\r\n\r\nit was amazing', 'This game is one of those bad 40k games. I''m still amazed this has a 2017 release, playing the game it feels and looks like a fan made game from 2005.', 'Very Positive', 85.09, 20.57, 0.10);
INSERT INTO reviews VALUES (16443, 502500, 19328, 'don''t hate me for this but this game is for controller or flight stick sim, not on mouse and keyboard. So if you''re planning to play this make sure you are planning to buy or have a controller at least. I don''t recommend playing this on mouse and keyboard it such a horrible experience, buy Project Wingman instead', 'A good, very fun, visually pleasing game (I''ve played it before on PS4), but you just simply can''t use a HOTAS, the whole reason I got the game again.', 'Very Positive', 88.68, 0.93, 0.83);
INSERT INTO reviews VALUES (16444, 502520, 5244, 'Super cool game.   Scaling for the opponent is busted and needs to be reworked.    Why get punished bc you did a good job managing your troops in the campaign to have the programming negate that with an extra 30k+++ troops.', 'It''s always a crisis, your always out of position, your always the smaller army - even as the Union- game is great but sets you up, unnecessarily, in perilous predicaments.\r\n\r\nYou can have a large army in camp; however, you can only bring half into a battle, and even then it arrives piecemeal.', 'Very Positive', 88.84, 63.98, 54.00);
INSERT INTO reviews VALUES (16448, 502570, 129, 'If you like Dark Souls, Elden Ring etc., the "game" is the best choice. It is a huge jump in difficulty.', 'So I pushed myself to buy it through steam to keep learning houdini.\n\nAt the beginning it''s pretty useful, it contains the basic tools to learn Houdini but as you start to expand your knowledge (plugins, sidelabs, python programming and the dealbreaker for me, BUGS!) I noticed this houdini is weaker than the apprentice version downloaded through SideFx webpage. I never figured out how to downgrade or upgrade my houdini through steam.\n\nDefinetely, I learned a lot through Houdini, but I wouldn''t t', 'Very Positive', 89.92, 466.12, 402.15);
INSERT INTO reviews VALUES (16452, 502710, 145, 'The game you play to spread your baby VR wings', 'Tested on the Meta Quest 3 using link cable on my RTX 3080 on Windows 11. Weird bug that several people with different headsets have reported. Anyways, the opening cinematics do not render to VR headset. However, the main hub area renders to headset and you can even use your motion controls to select menu items. Then when you select the level, it goes back to not rendering to VR headset again. I''ve never seen this bug in any other game. \n\nDo NOT buy. Broken VR game.', 'Mixed', 60.69, 4.68, 0.08);
INSERT INTO reviews VALUES (16453, 502720, 172, 'Better than starfield', 'I don''t even know why I bought this.', 'Very Positive', 84.30, 0.25, 26.28);
INSERT INTO reviews VALUES (16455, 502740, 241, 'My wife said if this review gets 50 likes and 5 awards, she will buy a case of beer, guys help me out.\n', 'When are you going to fix the bugs? I play as Romans, and have NEGATIVE faith! Payed real money for this, but devs can''t bother fixing its bugs!\n\nAlso, why I cannot deploy units before battle?! I want to arrange my soldiers in a more fitting manner.\n\nUntil bugs are fixed, I do NOT recommend you buying this game.', 'Very Positive', 91.29, 1.53, 0.87);
INSERT INTO reviews VALUES (16456, 502750, 323, 'Still one of my favorite game series of all time', 'Great story but (especially QFG2) is buggy. Recommended for nostagic players. If you want something similar with less bugs King''s Quest might be a better choice', 'Overwhelmingly Positive', 95.36, 68.45, 326.35);
INSERT INTO reviews VALUES (16457, 502770, 387, 'Cute game with a simple concept, though it could use a few optimizations. Of course clickers require clicking, but the upgrades fully maxed don''t bring the ease one would expect for collecting things compared to others in the genre. You don''t just need to click, but you need to do it rather quickly. Something that would help would be traps for the dragonflies, snails, frogs, lizards, and snakes. Some sort of stats page would also be nice considering the achievements require specific numbers and ', 'The art style is cute. But even for a clicker game it''s stressful and some of the achievements are rather excessive. Wouldn''t recommend.', 'Mostly Positive', 78.04, 99.87, 36.25);
INSERT INTO reviews VALUES (16459, 502800, 1431, 'To all my homies who saw me playing this game,\nI bought this game around 22:05 in November. I couldn''t choose between cyberpunk, metro exodus, for honor, zenless zone zero, and drawing so instead of sitting and doing nothing I bought this game and I''m playing it, I have absolutely no other purpose.\nThank you all for reading. Have a nice day.', ' Game is 100%''d at time of this review. \n 3/10 \nFinally done with that awful game being 100%''d...  I''d rate it a 1.5/5 only because the story carried it heavily, but I would not advise ever playing this game just for the sheer sake of how terrible the combat is. \nIf the combat wasnt the worst thing in existence it wouldve actually been enjoyable cause the main story had my attention somewhat, talks a lot about loss of loved ones, and learning how to move forward and how it affects people differe', 'Very Positive', 94.48, 4.90, 29.95);
INSERT INTO reviews VALUES (16461, 502820, 1072, 'I know a lot of people complain about the length of the game, and that its more of demo than a game, but I really enjoyed it.  It is quite short, maybe 1-2 hours, but it is fleshed out by the achievements and Riddler side content.\r\n\r\nGraphically it is quite impressive and there is a lot of detail in the content of the game.  There is limited movement but the use of gadgets really help hide this.  The scope of the Batcave is impressive and the sense of scale left me awestruck.\r\n\r\nOne thing to not', 'imagine not being able to fight as batman', 'Mixed', 65.02, 3.95, 0.68);
INSERT INTO reviews VALUES (16465, 502940, 445, 'Trying to calm down while smoking and trying to make sure your phone doesnt touch the nuke button is very calming 10/10 office work experience for communists', 'Funny and entertaining for the first 15 minutes. Then it becomes infuriating when physics and animations glitches kill you over and over in the last two seconds of the remaining levels. Game very rapidly goes from being novel and humorous to a time-wasting chore.', 'Very Positive', 90.56, 2.22, 1.85);
INSERT INTO reviews VALUES (16478, 503180, 147, 'About 2 hours of total content with a 6 hour equivalent grind to get to endgame. A stylistic and slightly clunky side-scrolling shooter lacking in polish or editing. Very much a diamond in the rough that could have used another year in the pressure cooker. Steam achievements are permanently broken, no replay value, and a trivial game-play loop past the first hour of unlocks. It still look great, the setting and soundscape are phenomenal, and the experience (generally) is decently immersive and e', '.', 'Very Positive', 82.99, 6.58, 31.83);
INSERT INTO reviews VALUES (16484, 503350, 809, 'One of the best horror games I''ve played', 'DO NOT PURCHASE THIS GAME. SERVERS ARE DONE AND YOU CAN NOT EVEN START A PRIVATE GAME WITH JUST YOUR FRIENDS. WE ALL GOT REFUNDS WITHIN 30 MINUTES.', 'Mostly Positive', 77.13, 46.90, 0.25);
INSERT INTO reviews VALUES (16485, 503370, 120, 'THIS GAME IS FUCKIN TYCOON GEM and BEST ABOUT HOSPITAL or HEATLHCARE Game since Theme Hospital. Great Developers and gameplay that will kill your social life. Game is RARE gem in today''s times , 1000% cool gameplay with full of attaractions already and constantly and REGULARLY added by the Devs who must be BULLFROG modernized incarnations !', 'Years later, still Early Access, still busted and broken, still not fun or worth the price. Appears to have been abandoned. Go buy Project Hospital instead.', 'Mostly Negative', 38.33, 13.00, 10.53);
INSERT INTO reviews VALUES (16487, 503400, 894, 'Listen. Strange women lying in ponds distributing swords is no basis for a system of government. Supreme executive power derives from a mandate from the masses, not from some farcical aquatic ceremony.', 'Yet another time where I wish there were more possibilities for the recommendation than just "yes" or "no".\n\nThis is truly a beautiful game, visually as well as musically. It''s full of Monty-Python-esque humor.\n\nSadly, I can''t recommend it due to its barely veiled vitriol against Christ. If you are a neo-atheist, you''ll love this game for this, but it crosses the line from humorously irreverent into cynically spiteful. The gripes with God are the typical misleading strawman caricatures that deli', 'Overwhelmingly Positive', 95.41, 1.60, 2.77);
INSERT INTO reviews VALUES (16494, 503560, 5326, 'Good game mainly because of two reasons: \n\n- You can play in Ohio\n\n- You can sadistically deprive people of emergency services and spread chaos', 'I enjoyed this game. So much I backed their board game version, which quickly revealed the dark side of this company and their frankly exploitative business practices. So I do not recommend giving them any money.', 'Very Positive', 87.57, 4.90, 6.45);
INSERT INTO reviews VALUES (16495, 503580, 1234, 'What can I say? I shot some ducks, shot some dogs, my mom isn''t moving. Great game honestly.', '2 hours of just shooting ducks and uninstalled. trailer makes it seem like there''s horror elements or more interesting gameplay but idk how long im expected to keep shooting ducks to get to that point. It gets boring.', 'Very Positive', 85.33, 10.52, 1.65);
INSERT INTO reviews VALUES (16496, 503620, 864, 'I love me a rogue-like indie game. If this had the budget and support of a big label it would have been a blockbuster. As it stands, the magic system that allows you to combine different effects in different intensities was novel and fun. Using that magic system to unleash unholy death and destruction on all that lay before me was more so.', 'Kinda-fun fantasy FTL ripoff. Lacks depth and replayability. Main gimmick is fun but thin to base a whole game on. Game is still pretty buggy and feels unfinished. Feels like it never left early access.', 'Mostly Positive', 79.51, 126.92, 67.48);
INSERT INTO reviews VALUES (16505, 503770, 420, 'This is an unsung hero of VR games. It''s a simple tower defense concept, but executed quite well. The balancing definitely favors multiplayer, so bring friends if you want to really push it, but the upgrades are fun and reasonably easy to obtain.', 'This has the feel of an early VR game that is basically one note.  There are far more versatile VR games out there with archery in them at a similar price point.  It does require a lot of activity and if you like the style, you could have fun but I did not.  I could see this being used to burn decent calories though.', 'Very Positive', 83.57, 8.57, 0.13);
INSERT INTO reviews VALUES (16511, 503940, 3664, 'This is a magnificent resource management game.  Clever historical tasks and settings add depth and context.   Highly recommended, but...\r\n\r\nWarning to new players - especially to those crossing over from Railroad Tycoon who provide so many of the negative comments!  There is a learning curve for switch placement and station platform management.  This time investment is required to play, and, once mastered, these elements are why RE is such a deeply satisfying experience.', 'Not going to lie- the clunky, complicated UI and the poor explanations surrounding what SHOULD be simple tasks/clicks is problem enough.\n\nBeing penalized for daring to want to PAUSE while not knowing what to do is like a cherry on the turd.\n\nThe fact that the "advisors" you can play as all have various jabs to insult you while you''re trying to figure things out had me hitting the refund button faster than a Pinkerton could kill a hardworking kid in coal mine.', 'Very Positive', 80.51, 1076.27, 0.58);
INSERT INTO reviews VALUES (16515, 504000, 102, 'A stereotypical Casual Hidden Object Point & Click Adventure game.\n\nNot exactly thought-provoking.  Only take a few hours to fully complete.\n\nMostly a bit of leisurely wholesome fun that doesn''t take itself too seriously.', 'Great puzzles. Not impossible but challenging. Stupid storyline.', 'Very Positive', 87.25, 4.22, 43.20);
INSERT INTO reviews VALUES (16521, 504130, 516, 'Nice game to kill time, effects are funny enough that I can overlook the fact that it''s highly repetitive.\nWish I could find someone to try out coop with, though.', 'I wanted to play a short, funny game for a change and I liked the idea behind this game, but unfortunately, apart from the sympathetic narration, the execution is extremely poor. I finished it until the end and I can attest the gameplay becomes increasingly boring and you will end the game feeling completely underwhelmed. The "story" can''t even hold itself in it''s own absurdity, because it''s just weak and not really that funny. So, spending money on this is honestly not worth it. The developers ', 'Mostly Positive', 79.84, 1.92, 2.10);
INSERT INTO reviews VALUES (16522, 504210, 2052, 'Literally, WORK AT HOME WITHOUT PAYMENT', 'As a software developer with experience in embedded programming, I''ve just about had it with this game. On the surface the concept is right up my alley, but most of the difficulty comes from ridiculous artificial constraints. Your microcontrollers have two analog signal pins. TWO. Want to drive three outputs? Too bad, add another MCU and figure out how to synchronize them in a dozen lines of assembly. Everything is exceedingly stingy, from memory to pins to the available space on the board. Copp', 'Overwhelmingly Positive', 95.18, 6.43, 26.25);
INSERT INTO reviews VALUES (16523, 504230, 51160, 'no one reads celeste reviews because they know damn well the game is good anyways im gonna confess i have a crush on that one grandma at the start of the game', 'I played the B-Sides for one hour and am now wanted on multiple accounts of Hate Speech, Manslaughter, Third-First-Second Degree Tomfuckgoobery, and Releasing the eternal Shenron from his Mason Jar. I cannot in good faith recommend getting this game, as it will tickle your prostate in such a way that you may never sexually enjoy time with your loved ones again. My anus quakes with anger at this game, and all it stands for as a porn catagory. Thank goodness I didn''t pay for it, else I''d bust Fett', 'Overwhelmingly Positive', 97.48, 76.63, 1.95);
INSERT INTO reviews VALUES (16528, 504370, 9859, 'I still come back to this from time to time, hoping that it miraculously revives with active players someday.', 'Was a good game. Really enjoyed it.\n\nStunlock can''t maintain a game. Don''t invest in any game they plan to run as a service.', 'Very Positive', 88.05, 62.08, 117.65);
INSERT INTO reviews VALUES (16530, 504390, 132, 'This drew me in more and more as it went along. Fantastic art style, very interesting musical compositions. I thought it was fairly mature and a great story. Had me intrigued as to the other endings which I may look up.', 'Very good game - but I cannot recommend it because it has no save feature, or skip feature. So you have to sit through the entire run again and again to pick different answers. And I don''t have the patience for it, or the emotional investment to care about the other options that much to repeat it. I like that your character physically changes based on choices too. But I don''t think it''s worth the price, and I would rather recommend Demon Heart - a much better, polished similar version of this ga', 'Very Positive', 85.61, 2.03, 6.48);
INSERT INTO reviews VALUES (16549, 504770, 445, '4/5', 'Real review here. To be honest, it would be a great prank gift or joke game. However, in Boris'' name, this game is not worth 2$. Extremely limited content, I unlocked all 6 characters in a good 30 minutes and it gets VERY easy once you get old of the mechanics. Needs content, or lower the price to 0.49$.\n\n4/10 Decent music, funny gameplay, lack of content, repetitive.', 'Very Positive', 92.58, 0.85, 0.55);
INSERT INTO reviews VALUES (16558, 505060, 246, 'fun game when i was like 10 in 2020 w game lads', 'I remember playing this when it came out. It was a pretty fun game, but I''m kind of sad that it''s no longer being updated.\n\nI would not recommend buying it because it is unfinished and likely to remain so.', 'Very Positive', 82.52, 21.35, 4.17);
INSERT INTO reviews VALUES (16563, 505170, 1204, 'Great game but you should absolutely get the C:MD Overhaul patch at cwaboard and play with the experimental patch they released, by right click on the game in your Steam library, going to properties, clicking on the Betas tab and entering VmfPZyCgXec4v2R4 into the code box.', 'Game is not playable on some modern hardware.\nSevere graphical glitches occur with some GPUs.\n\nI have not found a patch.\nIt may be playable on older hardware if you want to roll the dice.', 'Mostly Positive', 79.65, 43.33, 0.30);
INSERT INTO reviews VALUES (16565, 505230, 4231, 'Initially started playing this game again as a way to avoid doing my stressful real life responsibilities.  Game stressed me out so much I''ve had to put it down and fulfill my responsibilities as a way to take a break from the game.', 'During pre-release marketing developers promised that it wouldn''t be a completed game until all three characters storylines added, now 6 years passed and they announce the Bachelor path as a standalone paid game that would be released maybe in 2026, which isn''t very trustful considering the company''s background. Since they can''t deliver on their promises and actively deceive their audience I don''t recommend anyone to oblige another cashgrab.', 'Very Positive', 92.70, 114.08, 7.82);
INSERT INTO reviews VALUES (16568, 505330, 124, 'I like games like Samorost, Machinarium etc so I bought this. The art is great and original. The atmosphere is dark and morbidly medieval. The puzzles are mostly easy except a few where I needed a walkthrough. What I didn''t like were the couple of arcade levels where you had to dodge, Levels like those have no business being in a point and click adventure that is meant to be played at a relaxed pace. Most of the hotspots were obvious but a few were pixel hunting.', 'I want to like the game, and I would prefer not to put thumbs down yet, as I have played very little. Nevertheless it was enough to get pissed with it. It seems you have to pick up things in the right order, otherwise the following steps get blocked. It just happened right at the second scene, where the candles and the star scratched on the floor are. I placed the candles on the points of the star too early before I found out I had to grab some gunpowder-like stuff for them; so I cannot grap it ', 'Mixed', 66.94, 6.17, 0.43);
INSERT INTO reviews VALUES (16570, 505460, 25068, '>Spawn\n>Turn on Voice Chat\n>Ask players what to do cause im new \n>Chill dude from Chile spends an hour teching me the basics of logi and gives me 3 commends \n10/10 Friendy towards new players \n', 'I have had lots of fun in this game and really enjoyed my time, but I really love building bases and that feeling you get from a base that u built just holding the line. With every patch I feel like that the devs are for some reason anti builders, again and again a nerf to howies, nerf to garrisons, LARGE SHIPS.  There is just no point of building good bases anymore, theres too many ways for it to die, you can brute force it with arty, you can SC it, you can RSC it, you can kill with 2 - 5 guys ', 'Very Positive', 82.75, 6.22, 6245.80);
INSERT INTO reviews VALUES (16572, 505630, 583, 'Its a fucking sick throwback to the old stand your ground fort games of the Flash era. The Last Stand is the closest comparison, and its soundtrack is even better for how cheap the game is.', 'Eh, not great. Not much balance. A bit too random and grindy. You progress regardless because you restart on the wave where you previously died. 30FPS cap is also a blast from the past, but doesn''t make much of a difference.', 'Very Positive', 85.25, 1.83, 5.42);
INSERT INTO reviews VALUES (16573, 505640, 401, 'The game had potential, and while the singleplayer mode was fun, the online mode is almost dead. The only thing saving it is the correspondence way of playing, which gets tiresome after a bit. Buy at your own risk.', 'Whoever designed the Gashford level is a dumb fucking wannabe. Too stupid or delusional to design a level properly and apparently not even professional enough to playtest it. Halfway through the campaign and the game suddenly switches from easy to impossible. There''s absolutely no amount excuse for how fucking bad this level is.\r\n\r\nI was gonna recommend this to friends but now I''m uninstalling and moving it to the "Don''t bother" collection.', 'Very Positive', 82.54, 26.07, 6.32);
INSERT INTO reviews VALUES (16576, 505730, 231, 'Just fun \r\nCombat a little tricky\r\nGetting money is tricky\r\nBut with some saving up and doing easy missions enough first - it is doable. \r\nAnd overall, just fun.', 'I thought this might be FTL reborn, but not quite.   Gets a little frustrating as all I do is die.', 'Mostly Positive', 70.56, 29.77, 1.05);
INSERT INTO reviews VALUES (16586, 506480, 314, 'Edit: I said before this was a dead game but after learning about what was going on in the background with the devs I learned that their publishing deal fell through and they have spent the last few months trying to get funding and failed. So kudos to the developer in keeping us informed and he has said he will resume development in jan solo.', 'The game had potential while it was under active development until early 2024. Interesting setting, world generation, mechanics, the works. In mid-2024 the dev suddenly went silent and stopped doing regular upgrades after they changed their publisher/ownership structure. They then took some time off, but we''ve had more than 2+ months of silence, which is not okay in this situation.\n\nOn 20 Nov ''24 the dev posted an update about their silence. Apparently they had an investor that kept promising th', 'Mixed', 69.43, 4.68, 2.25);
INSERT INTO reviews VALUES (16587, 506500, 483, 'Nobody will read my review so I Will Eat 1 Tablespoon of ketchup For Every Like this gets.', 'possibly the worst UI i have ever seen in a game.\nreally boring pummel party clone with boring games.\n', 'Mostly Positive', 70.60, 9.85, 0.88);
INSERT INTO reviews VALUES (16588, 506510, 172, ' JRPGs often get bogged down in unnecessary complexity and padding, Shadows of Adam stands out as a beacon of concise and engaging storytelling. This retro-style gem is a testament to the power of focused game design, delivering a narrative that is both emotionally resonant and expertly paced. From the moment you start playing. \r\n\r\nEvery scene, every conversation, and every plot twist serves a purpose, propelling the story forward with a sense of urgency and momentum.\r\n\r\nThe game''s combat system', 'It pains me to give a negative review to a lovingly handcrafted game such as this, but I''m obligated to warn you it''s not fun.\r\n\r\n-It falls victim to the classic JRPG blunder of having way too many tedious, repetitive fights.\r\n-There''s not a single interesting strategic decision. Abilities are unlocked on a fixed schedule with no customization, and party composition never changes.\r\n-The story is generic and doesn''t compel me to keep playing.', 'Very Positive', 88.95, 22.25, 4.50);
INSERT INTO reviews VALUES (16592, 506610, 7138, 'Best lore than all other Five Nights At Freddy''s games.', 'good for let''s-players and nobody else ever, unless you slog through the main section to get to the custom night', 'Very Positive', 91.43, 2.95, 5.38);
INSERT INTO reviews VALUES (16596, 506730, 310, '⠀', '\nYes, it''s bad. Got this only for achievements.\n', 'Mixed', 60.65, 29.78, 2.03);
INSERT INTO reviews VALUES (16601, 506870, 487, 'Kind of hard and good for playing in short bursts. Like a side job, not the main game to play. may be during updates or if something is being installed. Gets frustrating in the long run. Once in 9 hours I got a bug that made me stuck inside a room without any means to get out, was only able to get out because I had a descent scroll which is a bad way to get down floors.', 'Game looks awesome but holy smokes controling your character is like playing air hockey with chopsticks and feels BAD. Hard, hard pass.', 'Very Positive', 88.09, 9.42, 0.13);
INSERT INTO reviews VALUES (16615, 507390, 139, 'While this game is heavy and not for everyone, it provides insight into some difficult topics, and that was comforting to me.', 'A respectable idea at its core bogged down by poor presentation. It''s a couple of minutes of poorly written sentences that fails to make sense of the story - in Segoe Script no less, so good luck reading it. There are also times where the developer punishes you for having installed it on your SSD by showing some text for about two seconds before it disappears.\n\nDidn''t hit me hard in the wallet, but I think buying some bread and feeding it to some local ducks would have been a more fulfilling exp', 'Mixed', 51.80, 0.38, 0.45);
INSERT INTO reviews VALUES (16617, 507490, 1794, 'Ashes of the Singularity carries a familiar essence, particularly for fans of Supreme Commander. The influence is undeniable, and I could feel its spirit seeping through the gameplay. The campaign offers a solid, well-structured experience, while the multiplayer delivers the standard fare you’d expect from an RTS. That, in essence, is the theme of this game—it doesn’t reinvent the wheel, but it delivers a polished and well-executed version of familiar mechanics.\r\n\r\nMy biggest gripe is the unit d', 'I should''ve done my research, and that''s on me, but this game is not Online Co-op.\n\nThere is no coop modes, no dedicated coop systems. The "coop" is just the PvP versus mode against the AI. That isn''t coop, its just bots. I have never seen Anyone describe bots as coop.\n\nETA: Playing the multiplayer "coop" mode and the game constantly breaks and needs to be restarted. Not a great experience at all', 'Mostly Positive', 79.77, 35.13, 15.93);
INSERT INTO reviews VALUES (16620, 508170, 109, 'BlackSmith HIT\n\nHas a total of 7 trading cards.', '\nTwo button mobile game. I keep hitting my fingers *tears*\n', 'Mostly Positive', 76.15, 2.25, 3.87);
INSERT INTO reviews VALUES (16632, 508440, 76228, 'It''s a pretty fun game from what I''ve played. I can''t say much since I haven''t played that much. I think I''ll aim to get a few more hours on this to see how if I should still consider this a good game.', 'Lies, it''s not very accurate coz mammoths are all ded now. Totally Accurate Battle Simulator, more like Totally Accurate Balls Simulator.\r\n\r\nAnyway, this game is great, stop looking at bad reviews and enjoy the insanity.', 'Overwhelmingly Positive', 98.09, 1568.12, 16.07);
INSERT INTO reviews VALUES (16637, 508550, 930, 'really good game.it reminds me of Coryxkenshin', 'you can literally beat the LAST mission on legacy with the silenced pistol.', 'Mostly Positive', 73.55, 9.83, 1.55);
INSERT INTO reviews VALUES (16639, 508600, 255, 'Good for the price. Honestly doesn''t have a ton else going for it.', 'I experienced some game changing bugs that really destroyed my gameplay. About 50% of the planets i could not even explore because my people just ran in to the corner of my "spaceship" and waited there. So if i sacrificed some turrets to take over a planet i could not even loot it. You can not even save the game. You have to play through the whole game in one sitting. Yes i know this is a very cheap game but if these things were fixed i would most definitely give this game a thumbs up.', 'Mostly Positive', 78.43, 17.62, 1.30);
INSERT INTO reviews VALUES (16652, 508790, 114, 'Fun game. Last boss is ass', 'My experience with the game so far has been solely playing solo.  Keep that in mind.\n\nThere''s a difference between challenging and aggravating.  The later levels are stupid difficult.  The ''you need luck to pull it off'' kind of difficult.  When you can beat a level once (with said luck) and would need to try 20+ more times just to beat it again, ideas of proficiency have been thrown out the window.\n\nI''ve never cussed at my television so much.  Hope you don''t have a spouse or room mate...', 'Very Positive', 94.74, 3.67, 6.15);
INSERT INTO reviews VALUES (16654, 508840, 259, 'Nobody will read my review so I Will Eat 1 Tablespoon of ketchup For Every award this gets\n', 'gameplay is shit', 'Very Positive', 83.01, 5.55, 0.48);
INSERT INTO reviews VALUES (16656, 508900, 1292, 'Lovely achievement letters!', 'This isn''t really a good game, more of an unpolished mess with some underutilized ideas in between and a way to get achievement tiles that you can use for some nice aesthetic designs on your Steam profile (this game seems to exist primarily for the latter reason). I probably wouldn''t have played this at all if not for the Steam profile customization options that came with it.', 'Overwhelmingly Positive', 96.05, 0.88, 11.57);
INSERT INTO reviews VALUES (16661, 508980, 428, 'ANOTHER PLACE, ANOTHER TIME, ANOTHER CRASHDAY!!!\r\nTHAT''S WHERE I FI-I-I-I-IND SOMETHING OF MY MI-I-I-I-IND\r\nSOMETHING I CAN HIDE!', 'The handling and general feel of the controls make this game unfun at best, unplayable at worst.\n\nThere are are older vehicular combat games that feel better to play than Crashday, and which have aged better.', 'Very Positive', 86.21, 4.75, 0.75);
INSERT INTO reviews VALUES (16662, 508990, 119, '\r\nIf you know old arcade games like bubble bobble then you might know what to expect from this one. Simple one screen stages where you have to catch foes with your tongue and spit them towards each other. Fun to play in short bursts.\r\n', 'It''s a less fun Super Mario, the one where enemies come from pipes near the top of the screen. Because the controlls aren''t fluid and the levels are designed poorly the optimum strategy is to sit in one place and spam the "x" button. Also, Super Mario was good because you had to voluntarily be in harm''s way in order to hit the enemies, whereas this game allows you to stay completely safe while killing things.', 'Very Positive', 91.60, 3.45, 0.40);
INSERT INTO reviews VALUES (16672, 509220, 691, 'Very historically accurate game to what actually happened in the Bible.', 'Gross!', 'Very Positive', 91.17, 0.10, 0.73);
INSERT INTO reviews VALUES (16674, 509250, 561, 'Good fking game', 'I played this when i was on a Quest 2 and i loved it. But now that im on an index is extremely uncomfortable and the bindings are made for the stupid Vive wands, it should be updated to have bindings and settings for the Index knuckles. not even custom bindings helped', 'Very Positive', 86.81, 0.15, 0.10);
INSERT INTO reviews VALUES (16689, 509570, 187, 'This is one of the best and most creative games I''ve ever played. There are some physics-related bugs here and there and I had to cut short one run in which the amount of blood (caused by stacking of a particular memento) made the performance to drop to sub-frame-a-second levels, but that happens when you''re really going nuts into a NG+4 run or so.', 'QUICK SUMMARY: The most apt review for this game I can give is it''s very clearly the dev''s first project. Made with love but flawed in the fundamental aspects of what makes a game fun. Such as:\n- Worldbuilding and lore are surprisingly deep, with a huge map to boot. But with a temperamental stamina bar slowing you down and a ticking clock of a hunger bar, its absolutely zero fun to navigate. \n- Both the enemy and weapon variety are very impressive, so there''s a lot to uncover. But an extremely c', 'Very Positive', 86.63, 172.75, 277.25);
INSERT INTO reviews VALUES (16690, 509580, 694, 'good strategy with replay value as you create new decks.', 'This is not at all like I expected it to be. It''s similarity to the physical LCG is in name only. If you are a fan of the LCG I cannot in any way recommend this game. The fact that it is more or less abandonware at this point certainly does not help its chances.', 'Mostly Positive', 75.36, 189.18, 3.52);
INSERT INTO reviews VALUES (16707, 509980, 11676, 'This game is usually an extremely fun horror experience with both friends and solo, but there is one problem that I have with the game: Bigfoot''s A.I. The A.I of bigfoot is generally pretty polished and fun, but he might as well be the Eye of Sauron; since, Bigfoot can find you anywhere, anytime, any way. One time, I was crouching in the corner of a house, all lights were off (including flashlight), and all of the windows had curtains over them. Even the door was closed! Regardless, big Monke Ma', 'The game can be fun with friends, don''t get me wrong but I refuse to ever play this game again due to one simple horrendous bug that must be fixed. At random whilst playing, lightning can strike a near by tree and THE LOUDEST SOUND EFFECT KNOWN TO MAN WILL PLAY! It will make your ears ring, it will shake your bowels, it will cause heart issues. And you might be thinking, "Oh just turn down the volume?" It literally does not matter what volume you have the game on, the thunder will always play at', 'Very Positive', 83.95, 17.92, 21.13);
INSERT INTO reviews VALUES (16727, 510420, 2139, 'Another interesting Daniel Mullins game.  Although it stitches many different games together and has a messy story line, the game is still quite fun to play.  The game length is about 5-7 hours in the first run.   Recommended for anyone looking for indie game.\r\n\r\nAchievements in the game is difficult to figure out.  Many hints are in the last section of the game so it will be almost impossible to get the relevant achievements in the first run without a guide.  Chapter select can be used to get a', 'As much as I want to like this game, it’s too difficult for me to get into the flow. It’s a well-written game that satirizes the gaming industry, but the story isn’t interesting or funny enough to me for me to want to keep going, and the worst part is simply the fact that the gameplay is a slog. You play a variety of different games within the game, and they’re all parodies of specific genres, but none of them is actually fun. I want to beat this game to get it over with, but with lacking and st', 'Very Positive', 94.39, 14.65, 2.67);
INSERT INTO reviews VALUES (16729, 510490, 482, 'There is no Part 3. Pathetic.', 'The story is kinda neat despite being kind of generic, some puzzle segments are ok.\n\nOverall though, inferior to the first game, most puzzles are tedious repetition with very minimal logic, and instead just require you to "try everything with everything" to find the solution. Combat is plain bad.\n\nIt''s not BAD bad, but it''s not good either, I wish I could vote for "Mixed".', 'Very Positive', 80.91, 46.50, 5.25);
INSERT INTO reviews VALUES (16730, 510500, 1048, 'This game is one of those gems that has gone mostly unnoticed.\nLooking forward to the big update that is coming! \n(Please keep in mind it''s only one guy working on this game and whats been made thus far is great!)', 'Don''t be fooled by all the reviews, this game is not it yet. I see a future but right now it''s so bare it''s not even funny.', 'Very Positive', 83.59, 5.20, 10.82);
INSERT INTO reviews VALUES (16735, 510620, 138, 'A great little arcade-y game you can pick up for a few minutes at a time. I''m only around half way through, but I''ve enjoyed it enough to go ahead and write and review.\n\nLeft stick moves your dot, right stick fires bullets in the direction aimed, but while firing, your speed is significantly reduced, so you can''t just fire all the time. It becomes a balancing act of firing and then getting away, etc. The enemies behave in some interesting ways, and I find myself saying "Oh, cool idea" very often', 'stupid rule inconsistencies, bad level design, and lots of waiting make for a game that constantly feels bad to play', 'Very Positive', 90.58, 0.48, 1.83);
INSERT INTO reviews VALUES (16737, 510650, 112, 'It''s an okay game, but it was a bit short for the price and it doesn''t seem to have a bonus chapter. A lot of people are cross about the choices and the achievements. Personally, I''m not too bothered about the achievements, and while the choices aren''t all they''re cracked up to be, they''re not a negative either.\nNot the best of Artifex Mundi but not the worst either.', 'I wouldn''t call it that bad, but without hesitation I''d call it lazy. Nothing new compared to the first game, even few steps back. Rather poor choice of puzzles. The game constantly repeats itself. "Shape your story?" - your choices mean nothing. Literally. Not just within the story, but even within specific quests. One scene has missing textures (the one with the lock if I''m not wrong). Special effects (when you make some interactions) are also kinda cheap.\n\nVisuals in general on the other hand', 'Mostly Positive', 77.68, 2.18, 6.32);
INSERT INTO reviews VALUES (16758, 511140, 114, 'its a tad  bit old, but still worth your time to play', 'Dear publisher/developer, please stop asking me in the middle of the game to review your game. Thank you in advance!', 'Very Positive', 92.11, 17.17, 10.82);
INSERT INTO reviews VALUES (16767, 511350, 146, 'yes', 'edit: After every date, there is another scene/date which I cannot enter since it requires a controller. If it was able to play without a controller, I surely would''ve enjoyed it more. It gets annoying when we''re about to reach the end and to get full stars maybe earn ourselves some extra achievements, but being block for an analog controller. come on. that simply ruins the mood to play. To those who wants to collect achievements and thinking of playing without a controller, do not continue purc', 'Overwhelmingly Positive', 97.26, 0.97, 0.88);
INSERT INTO reviews VALUES (16774, 511470, 1695, 'This is a really pleasant relaxing jigsaw game. It looks and it''s really simple, but I love the ambience of the whole game, really chill and also enigmatic. You''re just making puzzles, but it feels like you''re doing much much more for discovery, history and humanity! aha\nThere is a lot to do! and everything is gorgeous.\nGreat, beautiful and cheap coffee game.', ' While being aesthetically pleasing the gameplay is a dealbraker with tiny images and blank pieces you have to rotate and fit while they are bigger than the gap you are supposed to put them into. \nNot to mention this is a ruzzian game and by bying it you''re supporting the war.', 'Overwhelmingly Positive', 96.87, 7.83, 10.08);
INSERT INTO reviews VALUES (16784, 511680, 856, 'Hmph, Fate/Extella—a decent attempt by mongrels to capture the grandeur of the Moon Cell War. The battles, though repetitive, provide fleeting amusement, and the story, while verbose, is passable for mortal standards. The visuals shine like a polished gem, though none can match my radiant glory. Play this if you wish to glimpse at fragments of brilliance—but know it pales before the King of Heroes.\r\n\r\nGilgamesh', 'I found it really hard to take this game seriously.  It is very ridiculous and over the top in the character interactions with them calling you their husband and acting ridiculous pretty much the entire time.  The combat is also very simplistic and you can''t even command the other units to complete task simultaneously.  It has some novel ideas but nothing to really write home about.  Ultimately lacking as a fate game and a mousou game.', 'Very Positive', 91.94, 46.78, 4.00);
INSERT INTO reviews VALUES (16789, 511740, 951, 'counter strike if it was good', 'I bought this game just to listen again the opening of 8 years ago that was on PsVita. \nThere is no opening.\n', 'Very Positive', 89.38, 21.30, 0.70);
INSERT INTO reviews VALUES (16799, 512060, 401, 'this game is racist', 'Not appropriate', 'Very Positive', 94.76, 4.23, 3.92);
INSERT INTO reviews VALUES (16801, 512080, 121, 'For just $10...I can experience extreme skiing off a cliff...I had my wife try it, and she was screaming so loud..I thought neighbor may call the police....for measly $10...I am fully immersed with fan blowing in my face.....great game...\n\nI admit I am still on my Vive honeymoon but this is a great value... I came over from PS4 and console game title averaged over $50...\n\nAfter several tries...I have not been able to finish the course yet....looking forward to more courses in the future', 'This game is pretty exciting and is a lot of fun but unfortunately there isn''t enough content to make it worth $10. This feels like a demo-there is only 1 ski course and you start from the beginning every time, and there are no other features other than going down that 1 hill in this game.\n\nIf more was added ie. tubing, snowboarding, multiple tracks etc then I would recommend this but I just cant at this point.', 'Mostly Positive', 71.90, 1.45, 0.20);
INSERT INTO reviews VALUES (16808, 512180, 438, 'I don''t even like men and I thought this was good. The Chojiro route and hanzo route were a little mid. Great writing overall though. 7/10', 'NO ONE TOLD ME MC WAS SIXTEEN?', 'Very Positive', 94.75, 244.28, 0.25);
INSERT INTO reviews VALUES (16809, 512220, 362, 'I didn''t buy this game for a long time because I was just like "eh it''s another sword wiggle dungeon game, gorn does it better blah blah'' \n\nNO! \n\nDon''t listen to past me. Past me is an idiot. Listen to now me...or future me if you are reading this later. This game is just a ton of fun. Combat is fun and changes a bunch depending on the weapons you use thanks to the powers. Plus this is not one of those beat it in 3 hour VR games. No you get to beat it for hours and hours in this game...and by it', 'you get what you see in the trailer... and nothing more.\n\nArchery is not as good as in "the lab".\n\nAt the moment it is not real game and 10€ is to much for it.', 'Very Positive', 86.74, 12.07, 0.43);
INSERT INTO reviews VALUES (16812, 512250, 2672, 'Your mum... Is... Your mum... and loves... Your mum.\r\n\r\nOOOGH!!!', 'Frustrating RNG achievements. Not worth your time.', 'Very Positive', 91.39, 4.93, 17.18);
INSERT INTO reviews VALUES (16815, 512300, 235, 'DanTDM is the reason i bought this game', '"Unbox: Newbie’s Adventure is pretty damn dreadful, so much so that I gave up on it after a mere two hours of play.  I’m often reticent to compare games to others too heavily, because I like letting them stand on their own merits, but seriously, there are so many high-quality 3D platformers out there that I can’t imagine why you would want to waste your time with this one.  Even without comparing it to other games in the genre, it falls down under scrutiny.  It’s unpleasant to control, tedious a', 'Very Positive', 88.51, 0.43, 2.15);
INSERT INTO reviews VALUES (16821, 512460, 179, 'i wish i could eat my mantis husband :(\notherwise good', 'Write a review for Drunk On Nectar - The Nature Simulator\n', 'Very Positive', 93.85, 11.85, 1.88);
INSERT INTO reviews VALUES (16823, 512490, 537, 'A nice little game. Definitely worth the price. If you played this during the 360 days, then you''ve found the xbox''s Magnum Opus. The greatest xbox arcade game of all time. Definitely game of the year back in when ever this game initially came out. Once you''re done playing this game, you may go and explore other games from 360 arcade, like CastleMiner Z.', 'I don''t understand what all the hype is about. I mean, it''s basic AF. Honestly, it should be free. This is the shittiest game I''ve ever played! Trust me, if you''re looking at the reviews before buying this, then DON''T GET IT! You will regret getting this game, and that regret will follow you for the rest of your short life.', 'Overwhelmingly Positive', 97.02, 23.55, 0.90);
INSERT INTO reviews VALUES (16834, 512790, 2289, 'Extremely similar to Myst in its conceit, this game involves the player wandering around a deserted island unraveling clues and puzzles left by a previous inhabitant.\r\n\r\nQuern contains two main types of puzzles. One type of puzzle is strictly logical, where you encounter a device and have to figure out its rules to get past it. These are almost uniformly well-constructed and satisfyingly difficult without being unfair. (There is one sound-based puzzle that I had trouble with, though that might b', 'I don''t know. I''ve played a lot of games similar to this, but this one is just lukewarm. Everything is so grey. The map is so large, which wouldn''t normally be a complaint, but its the fact that we have to run from one end to the other without actually knowing if what we''re searching for is right. The game lacks clear directions. For a puzzle game, directions aren''t immensely important since the whole point is to solve the puzzle by what you know, but the map is giant and everything is grey. It''', 'Very Positive', 91.35, 20.10, 12.47);
INSERT INTO reviews VALUES (16836, 512890, 262, 'Keep exploring to find truth in medieval time loop', 'Loved the first few hours with a fresh take on Hamlet''s characters. While finding the endings was satisfying, it''s not always clear what you need to do once you have all the necessary hearsay for some of them. Making one mistake in the order of events can muck up the timeline and you have reset the day and go through the motions all over again. Thankfully you can reset and speed up time whenever you want. The hand drawn art style is beautiful but the animations are a bit amateur. Kudos for devel', 'Overwhelmingly Positive', 96.56, 22.68, 7.92);
INSERT INTO reviews VALUES (16837, 512900, 8045, '- Be a cop\n- You need to neutralize a homeless person\n- I try arresting the homeless\n- Accidentally punch the homeless with cops around\n- Homeless person gets shot up from 4 different directions\n\nThank you Streets of Rogue for letting me play as a corrupt cop, a cyanide gassing scientist, a drugged up monkey, etc. One of the funniest games that I''ve ever played', 'Mission timers. The biggest reason why this is getting a negative review. \n\nThe AI is also extremely unfair and broken. They hit you with perfect accuracy and kite you, meaning they are able to hit you perfectly the exact frame you enter into their weapon range which makes fighting in this game unfair and a chore.', 'Overwhelmingly Positive', 96.67, 38.47, 0.47);
INSERT INTO reviews VALUES (16844, 513230, 224, 'The most hardcore walking simulator', 'I''m refunding my 79c. Not because I can''t afford to lose 79c, but in order to make a point.', 'Mostly Negative', 36.61, 3.75, 1.02);
INSERT INTO reviews VALUES (16849, 513290, 386, 'You can kill children', 'for how old this game is your probably reading reviews out of morbid curiosity. if your planning on buying this game just know your buying it because its a dumpster fire compared to its earlier titles for comical relief. it has its moments and I commend the designer for trying to expand on something already existing and playing with the formula. but much like that mid term paper for that project you thought would be your magnum opus, later turns out to be well lets be nice and say, "sub par." th', 'Mixed', 47.41, 13.88, 17.32);
INSERT INTO reviews VALUES (16851, 513320, 125, 'Negative: Many issues on Meta Quest 3. Steam link causes fatal error on launch. Air link cause fatal error if motion controllers are used. The only way it worked was using Air link + gamepad.\n\nPositive: Game is fun to play, nice environment, especially later in the game. Loved the cat.\nGot 5 hours of fun, spending only 80cents or so on sale.', 'Not actually a VR game, its a simulation for keyboard and mouse. nothing on the Oculus quest 2 worked. just a black screen. You can see the screen on Steam Vr Desktop but then even still the controllers on the quest don''t work properly at all.', 'Mostly Negative', 38.40, 5.17, 0.38);
INSERT INTO reviews VALUES (16852, 513330, 128, 'pretty  simple but fun.', 'NO!', 'Mostly Negative', 35.16, 6.38, 4.28);
INSERT INTO reviews VALUES (16853, 513340, 104, '⠀', 'It seems that there are some things that are not displayed properly, perhaps due to a bug.\nEven without that I can''t recommend it.', 'Mostly Positive', 73.08, 3.85, 7.25);
INSERT INTO reviews VALUES (16854, 513360, 116, 'underrated puzzle game, very unique. 10/10', 'The word ‘experimental’ is never a good sign for a video game. What it tends to mean is that the game in question is trying out some new idea, but basically just doesn’t make a full game out of it. Mu Cartographer is, without a doubt, an interesting proof of concept; we’re given a complex, esoteric device with which to survey a large, abstract landscape. Various knobs and dials alter the appearance of the terrain, but nothing is given a meaningful label or description and the way the terrain cha', 'Very Positive', 89.66, 5.07, 0.15);
INSERT INTO reviews VALUES (16857, 513450, 120, 'Seriously, cutest game ever! And more complicated than I''d expected.', 'So fucking frustrating and annoying .   My agro level is over 9000.\n\nPlease put in  check points or saves during a level.', 'Very Positive', 87.50, 0.87, 3.13);
INSERT INTO reviews VALUES (16861, 513510, 1615, 'for the price its asking for and the sheer quality of it, there are countless hours to be had in this game. just not by me.', 'I''m not big into rhythm games and thus not very good at them, but still enjoy playing them from time to time. Intralism was just a miserable experience though. The user created maps are fun but it creates a massive lack in the consistency of the quality of the maps. Some are hard to see due to colour choices or are just plain ugly, others have too much going on with pictures/animations/colours, which I guess just adds to the challenge - but not in a fun way. Most importantly though, its a dead g', 'Very Positive', 87.49, 2.47, 6.52);
INSERT INTO reviews VALUES (16872, 513710, 34933, 'I play single player, so that''s what I''m reviewing. You can modify pretty much every aspect of your server, once you do that it''s a pretty fun game. Performance is pretty good, graphics are good, gun play is satisfying & looting is fun once you crank up the loot %. If this looks like a game you''d be into but don''t want to deal with cheaters, griefers, and toxic people the SP mode is a good time.', 'By Far the best Zombie game out, Just really Wish we could host our own servers. Been in Dev for YEARS and YEARS. Its about time we can host our own servers.\n\nI Really hate when a Dev Corners you to pay for a server when its just 3 or 4 ppl. Then to make it worse u can only rent a 20 SLOT Server. SO you gotta PAY alot just for a few ppl to play. \n\nUNTIL WE GET DEDICATED I CANNOT RECOMMEND GAME | ITS BEEN 6 YEARS | GIVE US DEDICATED SERVER FILES ALREADY !', 'Mostly Positive', 74.90, 3.75, 301.77);
INSERT INTO reviews VALUES (16877, 513780, 218, 'Nobody will read my review so I Will FInd 1 Friend For Every Like this gets.\n', 'It''s cute but that''s the only thing i liked about it. I didn''t like most of the music and don''t care for the gameplay either. Even though it''s only two dollars there are free games that do it better, so i cannot recommend this game and did not find it fun whatsoever.', 'Very Positive', 83.03, 4.03, 2.45);
INSERT INTO reviews VALUES (16884, 513890, 175, 'Very nice experience. I have enjoyed it a lot. Interesting story, not much running around, fun puzzles.', 'Not sure why this game gets such good reviews.\n\nI''ve been playing adventure games since the Apple II days and this game wouldn''t have impressed me 20 years ago (it would have impressed me on the Apple II though).\n\nAs others have said, this is obvioulsy a mobile port. This doesn''t necessarily bother me but for this game it does. The interface is very poor for a PC game - click everywhere until you find a hot spot.\n\nPuzzles aren''t interesting and neither is the story.', 'Very Positive', 92.57, 2.00, 0.90);
INSERT INTO reviews VALUES (16905, 514310, 452, 'After my 100% completion of Burst Renewl on ps5 and Shinovi versus i once again have extended my hand and lached on to the Tender hand of Senran Kagura it is always there for me when my life has turned grey and it will be even when i turn grey Senran Kagura is a game i would give a seat at the table when time turns Christmas.\n\nSenran Kagura is Love\nSenran Kagura is Life \n\nI will turn old and i will still wait for Senran Kagura 7even\n', 'I can''t recommend this game\nPros: Tiddies, \n         cooking, \n         not bad gameplay\nCons: bad port, \n          lock to 60 fps, \n          low res on clothing (you cant even tell that Asuka''s apron have a frog on the middle)\n\nMaybe give it a try on console but on PC is no bueno.', 'Very Positive', 92.26, 2.88, 1.98);
INSERT INTO reviews VALUES (16927, 514700, 113, 'Excellent HOG, the use of FMV really highlights this game and made it a ton of fun. The game plays as a series of mini-quests which I find enjoyable and keeps you from feeling lost in such a huge map! HO scenes are decent and puzzles are a bit more puzzlely than normal but still enjoyable. Characters are awesome, they all have various crazy personalities, Cooter even farts! There was a very cool puzzle where I had to plunge the bar toilet and make some calls to learn the "secret sauce". My only ', 'Gratuituously gross and grimy', 'Very Positive', 84.96, 5.22, 3.02);
INSERT INTO reviews VALUES (16939, 514920, 485, 'If you want to play a game that makes no sense and you need achievements, you''ve come to the right place\n', 'Fun premise, but the game is too short and feels like a cash grab to get lettered achviments.', 'Very Positive', 84.33, 7.75, 3.15);
INSERT INTO reviews VALUES (16946, 515040, 1087, 'Trump 2024 stunning comeback!', 'Was given this as a gag forever ago.  Regardless of my feelings on Trump (they''re negative, FWIW), I did play this game on its own merits.\n\nIt''s... basic.  Just a basic kind of game you''d expect to find on older Flash Game sites.  It isn''t worth literally paying for when you can find the same thing - for free - on Kongregate.\n\nI guess if you''re REALLY into this guy, go for it.  It is your money.  No one can stop you.\n\nBut if you value your time, money, and integrity?   I''d pass, honestly.  Go pl', 'Very Positive', 86.75, 12.43, 2.23);
INSERT INTO reviews VALUES (16948, 515180, 1864, '21 is way worse than this\n\nRecommend', 'Hello,\nI am really disappointed with your service as yesterday (2nd July 2024) I bought your DLC package which cost around 3.89 euros from steam which is not available in game mode . \nCan you please assist me on this matter or i want my Money back.\nI hope for a quick response on this matter.', 'Mostly Positive', 79.61, 28.47, 60.43);
INSERT INTO reviews VALUES (16951, 515260, 144, 'While I don''t really like the amount of DLCs, it''s still a wonderful game that definitely deserves more attention', 'Not recommended for VR! they only give you each single ride in a grey warehouse: no open area, no people in the ride, no funfair sound. The realistic nauseating sensation is there, but it''s only half of the fun, when you try them individually in a closed warehouse with nothing else around, feeling like a technician testing the thing on your own. Visiting the Fair Ground itself (which is possible for flat-screen) to walk around the park, people, day/night cycle, sounds and pick a ride by walking ', 'Mostly Positive', 77.08, 6.97, 0.48);
INSERT INTO reviews VALUES (16953, 515570, 205, 'Well i like the game', '.', 'Very Positive', 91.22, 63.33, 0.38);
INSERT INTO reviews VALUES (16954, 515650, 118, 'One of the hardest games i''ve ever played for like no reason. Incredible game though', 'I spent some time mucking around with controls in the options menu.  \n\nThis game would feel a lot better to play if you could shoot vertically or 360 degrees.  You can only fire left or right.\n\nI was pretty confused but the UI, but I was making progress clearing rooms and defeating waves of enemies.\n\nSome of the attacks by enemies look kinda tacky in contrast with the otherwise somehwat cool pixelart in the backgrounds.\n\nI dunno, this one ain''t landing for me at all.', 'Very Positive', 91.53, 17.80, 0.23);
INSERT INTO reviews VALUES (16960, 515960, 939, 'This game isn''t hard or scary in the traditional sense. The gore isn''t scary. But the entire thing, is still quite disturbing and menacing. From the background soundscape, to the eerie environment set against the beginning of WW2, to our unreliable narrator. \n\nThe game is an easy play if you''re a casual gamer. Puzzles are pretty simple. Not much for jump scares. Just a lot of point and click and walking around. The story though could be quite triggering. Even if you aren''t normally triggered by ', 'It''s so poorly optimised that I wanna cry :( \n\nThe game itself has a potential to be a good game though, and probably plot-wise it deserves all it''s awards. \n\nBut it''s hard to play an IMMERSIVE game when you face constant lags, glitches, pop ups, FPS drops etc. \nIt was kind of frustrating and honestly I hate that I had to write this review, but for me it''s hard to forgive optimisation issues and bugs in such hyper-realistic graphics, cause it ruins the whole point of the art style in my opinion.', 'Mostly Positive', 75.51, 7.90, 1.00);
INSERT INTO reviews VALUES (16966, 516110, 528, 'It''s the original game but with a load of new stuff added to it and 4 player support. I prefer the original a little more, but this is a really solid follow up, and probably a ton of fun with 4 players. Get it on sale. Jammin''!', 'For those who played the original Toe Jam and Earl for the Genesis back in the day, this review is probably for you.\n\nThis game as a whole has not aged well. My biggest gripe by far is the piss slow walk speed. Toe Jam with his high walk speed makes him an instant pick, everyone else is far too slow to escape from enemies that can chase you.\n\nThen you''ve got the infuriating RNG when opening presents. Do you like the idea of getting instant killed from opening a present, or having random Earthlin', 'Very Positive', 90.34, 2.17, 16.98);
INSERT INTO reviews VALUES (16968, 516130, 180, 'A super solid game that I''m surprised I didn''t try out until now, even when I''m a BIT.TRIP fan.\r\n\r\nI have a couple of complaints, mostly belonging to visual touches on characters (specifically the lack thereof), but those are moreso my bias towards Runner 2, which I favour a bit higher over this one.\r\n\r\n9 impossible levels + 1 Commandgirl Video/10, wish she had better outfits.', 'As much as I really want to like Runner3, it feels so far removed from the the first two Runners and it''s got really weird gameplay changes (and why do all the levels feel so much longer? maybe cause they had to fit a hundred gold in each of them for some reason). Of course the effort in the game is evident but it just doesn''t do it for me like the others.', 'Mostly Positive', 74.44, 21.90, 2.50);
INSERT INTO reviews VALUES (16975, 516480, 399, '\r\nRunning around in pink spandex have never been so fun!\r\n', 'I literally cannot play this game. For some reason the developer made the controls the arrow keys instead of WASD? I have no idea what they were thinking but not only did they do this, they didn''t include anyway to remap the controls. My keyboard has no arrow keys, I literally can NOT play this game.', 'Overwhelmingly Positive', 98.75, 3.40, 0.10);
INSERT INTO reviews VALUES (17005, 517130, 390, 'Honesty, one of the best VR fitness games out there. Although it might be old with no more updates, it still works with the quest 3. I love how you don''t have to download any songs or mods. It is integrated with Youtube and you can just create your own songs/rhythm to workout. This is guaranteed to make you sweat and arms sore.', 'skip this nonsense and buy audioshield', 'Very Positive', 86.41, 8.38, 0.08);
INSERT INTO reviews VALUES (17007, 517160, 454, 'This gave my mom a heart attack. Highly recommended.', 'Originally this game was unique and a fun way to introduce players to VR.  More recently the developers have mindlessly ruined the entire experience.  The introduction of a nonsense EULA screen that resets every time the headset is removed, breaks the ability to calibrate a real-world plank and makes the entire game useless.  I guess this is what happens when clueless developers don''t test their own game and are completely out-of-touch with reality.  Being forced to page through an EULA in VR is', 'Very Positive', 80.62, 3.77, 5.50);
INSERT INTO reviews VALUES (17018, 517330, 103, 'Stellar Interface is a fun little rouge-like space-shooter with a bunch of replay value. With its retro graphics and challenging gameplay, it is perfect for those who are fans of the classic arcade games and retro space shooters. With 100+ upgrades/perks, there are countless ways to spec out your ship, leading to a different experience every time you start a new run. The bosses are all fun with unique mechanics and the music is awesome. Overall, if you are looking for an arcade style space shoot', 'The game does not signal clearly enough what is happening. I just played it for a few minutes and would randomly get taken from the level into some sort of screen where I could select an upgrade. Had I beaten a boss? Had I progressed a level? I didn''t see anything while I was playing that would indicate that. \n\nThis seems like fairly basic stuff, but you really can''t play a game where you can''t even tell if you''ve beaten a level or not.', 'Mostly Positive', 75.73, 4.77, 0.10);
INSERT INTO reviews VALUES (17022, 517370, 105, 'A very fun, cheap little game. I finished the storyline in 30 minutes, however I am a very fast reader and I did not pimp my Tavern out as much as I could have, because I didn''t realise that more categories unlock as time goes past. There is a storyline to follow and I think the hourglass on the counter tells you how long you have to complete the storyline. I haven''t tried the management mode yet, but I will soon! It''s a good game, you pick sides, pick a type of customer to focus on, buy loads o', 'I''ve run through it about 5-7 times now, it is not a tavern sim (or I wouldn''t call it that) and I wouldn''t say it has a strategy even. As long as you choose one thing you can get a good ending. It''s more of a interactive storybook with set amount of events (good chuck have no good outcome as well) with a predictable outcome where the ''twist'' comes in.\n\nThe ''multiple'' endings are the same thing but slightly different text but same good-end/bad-end image  (it doesn''t change if you do something di', 'Mostly Positive', 75.24, 0.47, 2.58);
INSERT INTO reviews VALUES (17031, 517630, 10186, 'I can recommend getting JC4 only on sale. I feel like the devs got tired of making the game but felt that they still needed to get compensated for all the work they''ve done so far and decided to put it out as is regardless of what players and fans would say.  The game plays good but there will be one big lag and some awful stutter. After doing some search, you can eliminate the stutter by simply going in the option menu - game play - and Select leaderboard and put it on show none. Crazy right! T', 'As a huge fan of Just Cause 3, I went into Just Cause 4 expecting an even crazier, more explosive sandbox experience. Instead, I got a dull, lifeless game that stripped away everything that made its predecessor fun.\n\nRight from the start, JC4 felt off. The vibrant, chaotic Mediterranean setting of JC3 is replaced with an uninspired world filled with endless, repetitive lush forests that lack personality. The game takes itself way too seriously, completely missing the over-the-top charm that made', 'Mixed', 62.37, 51.97, 2.68);
INSERT INTO reviews VALUES (17035, 517710, 2256, 'now i''m a proper racist', 'I kinda like it but then again I don''t. It''s a homage to wipeout and those kinds of games but it''s just not wipeout this is an entirely different beast. It looks really good the music is great and the overall vibe is groovy. There is fun to be had here but not for everyone. There is  hard but fair and there is just plain hard and this is way too hard to be fun or rewarding enough for me personaly. Too many unfair controller throwing gotcha moments. I can''t play this game for more than 20 min bef', 'Very Positive', 85.37, 3.92, 12.20);
INSERT INTO reviews VALUES (17036, 517720, 255, 'This is really a great game. You will find an occasional bug or two but it is feature rich and a complete game at this point. It has been in development for quite a while and 2020 hit the team hard reducing it to a single developer, but he is very open about his passion and his promises. If you look at it and think, "I might like this", you definately will!', 'Abandoned, stay away, very much unfinished after 7 years (I bought this in 2018, because of the potential)', 'Mixed', 58.04, 8.88, 4.37);
INSERT INTO reviews VALUES (17038, 517780, 205, 'Great game. played on the paper board back in high school during the 80s. Glad to see it back.', 'Single player campaign is very short, game resolution is very tedious.', 'Mixed', 67.80, 18.65, 10.30);
INSERT INTO reviews VALUES (17039, 517790, 1093, 'I''ve played many city builders over the years but this one still holds up as one of the better ones. I mean for the price it''s actually high above your modern city builders. I love the accessibility too. I remember playing it as little as 8yo and not understanding English I still loved every minute of it.', 'I swear to fucking God, every time I play this, I run out of food. I build the needed locations, place them in close proximity to housing and markets, and my citizens'' lazy asses won''t work. Bitch, GET YOUR LAZY ASS TO WORK! GET YOUR LAZY ASS TO WORK! GET YOUR LAZY ASS TO WORK! GET YOUR LAZY ASS TO WORK! GET YOUR LAZY ASS TO WORK! I don''t fucking care that you''re producing as much food as you can with all of the city''s arable land, MAKE MORE! I''M LOSING FUCKING MONEY!', 'Very Positive', 93.87, 7.72, 5.83);
INSERT INTO reviews VALUES (17040, 517810, 410, 'The game that got me into PC gaming. It was more intricate than my child brain could comprehend. Nearly 20 years later here is me completing it.', 'I love this game and wanted to play it again. I just bought it on Steam and it won''t launch, I get an error message.\nI see there are solutions to launch it but I can''t be bothered to fiddle around when I paid the game. It should work directly.', 'Mostly Positive', 77.56, 76.73, 0.18);
INSERT INTO reviews VALUES (17047, 518030, 1200, 'The beauty lies in its simplicity.', 'the OG Aimlabs, we must let it rest now', 'Very Positive', 81.50, 92.47, 0.17);
INSERT INTO reviews VALUES (17049, 518060, 985, 'I mean... chess is a fantastic game, it always has been for generations of humans, and Chess Ultra does it justice with its beautiful graphics. Playing it is very immersive, I love the music tracks, the backgrounds, and the atmosphere is very immersive, relaxing and elegant—something I never thought I''d be saying about a chess video game. The variety of chess sets is a nice touch, especially the beautifully rendered Isle of Lewis pieces (how I have always longed to own a set of those...)\n\nI appr', 'Just go to Chess.com', 'Mostly Positive', 73.10, 3.67, 20.92);
INSERT INTO reviews VALUES (17054, 518150, 3693, 'If you play this online you only face off against solid snake, and get one tapped before you see him. If you play it with friends or those of equal skill? it becomes some of the most fun ever', 'Game is almost dead, average players are below 100 and the small amount that do play are some of the most entitled and cringe people to ever interact with. The only people defending the community are the people who are the problem lmao pretty sad. Also people get reported by these losers and get banned for things like "racism", Crazy how your game is almost dead and you still can''t be bothered to look over the reports, what a joke.', 'Very Positive', 89.71, 5.50, 6.43);
INSERT INTO reviews VALUES (17066, 518730, 155, 'Y', 'I was ready to give this game a good review but the last level is seemingly impossible unless you buy a lot of shop power-ups which would cost an awful lot of money. You don''t get anywhere close to winning otherwise.\r\n\r\nI can''t fault the game in any other way. If it weren''t for the difficulty it would be great.', 'Very Positive', 92.90, 2.92, 13.77);
INSERT INTO reviews VALUES (17068, 518790, 54905, 'I shot an animal 8 times and followed its blood trail long enough to cover a small country... but game pretty and lets me stalk something that''s not my neighbor so I''d say its a good trade off.', 'This game is so realistic, you have to buy nearly every piece of equipment that''s worth using with real money. $230 dollars of dlc is criminal.', 'Very Positive', 90.05, 6.73, 80.95);
INSERT INTO reviews VALUES (17070, 518920, 558, 'MORE MOUSE BITES!!!', 'A shoddy port made for the long-defunct original Vive headset and not updated at all for newer hardware such as Quest or Index. Has no actual movement and requires you to move around in your space which is not great if you have limited room to use.\n\n4/10, the most fun part was giving Bob the Oldboy treatment and bashing his head in with a hammer.', 'Mixed', 62.01, 2.33, 0.63);
INSERT INTO reviews VALUES (17078, 519190, 3095, 'good game just needs love', 'the game looked great on the store page but is not worth the .99 cents i payed for it tbh. if it were updated or debugged then it would be worth well over 20, but its not. at the opening menu it will have a 50% chance to crash at random, when changing any settings it will close the game, after spawning you will crash and lag (even if not on wifi) every few seconds, the game failed to go above 10 fps and stayed at an average of 3. ten crashed and closed itself on the first animal i killed. the ma', 'Mixed', 58.68, 88.02, 1.12);
INSERT INTO reviews VALUES (17088, 520010, 959, 'i am excausted. worth the price. rember to drink', 'I''m used to grip, not trigger.\n\nalso feels like a cash grab.', 'Very Positive', 91.14, 2.03, 0.22);
INSERT INTO reviews VALUES (17104, 520440, 4449, 'they got that beautiful man in the bed i forgot his name', 'if you havent already devoted hundreds of hours into guilty gear games that arent Strive, genuinely do not bother. Everyone still playing this game in the current year is beyond sweaty and hasn''t seen a job application since accent core+ came out. Just stick to Strive if it''s the only one you''ve played. Learning to be good at this game is entirely more trouble than it''s worth. The game is NOT bad, quite good even! But unless you have any plans with this game other than busting it out with friend', 'Overwhelmingly Positive', 95.89, 49.40, 18.05);
INSERT INTO reviews VALUES (17110, 520600, 141, 'Good balance of fun, light-hearted elements and darker, more mysterious storytelling. Characters were generally very likeable and the art was pretty good, especially some of the backgrounds. Really needs a proper skip function though; I ended up using AutoHotkey to mash my space bar to get through repeat playthroughs.', 'I have more hours on this game than the deserves and I still don''t have the last achievement, which is seeing absolutely everything. This would be okay if there was a skip function, but I have instead had to spam the space bar while multitasking to get to the options and hope that I find the missing couple of pages. My first playthrough or two was fine, but its so annoying that the last achievement takes so much time to get. If you don''t care about 100%, its an okay game, the story isn''t great b', 'Very Positive', 80.14, 12.32, 59.90);
INSERT INTO reviews VALUES (17115, 520720, 1260, 'At first glance, it seems like a simple walking simulator where you leisurely travel around an island without any interaction. However, upon closer inspection, it reveals a story with profound meaning about the protagonist, his experiences, his decisions, and their consequences. Through a unique expression of philosophical themes and literary imagination, beautiful graphics, stunning landscapes, and a captivating soundtrack come together to deliver a dramatic and emotional experience.\n\n\n소박한 산책을 ', 'Ah yes, Dear Esther, the critically acclaimed masterpiece where you… walk. Slowly. On an island. While a man with the tone of a melancholy audiobook narrator whispers cryptic nonsense into your ears like a ghost who just discovered poetry and hasn’t had coffee in years. Gameplay? No, no, that''s too interactive. Instead, you get to hold forward on your keyboard and soak in the immersive experience of watching moss grow on rocks. Sometimes you’ll stumble upon a rusty boat or a cave that looks like', 'Mostly Positive', 75.87, 3.35, 0.82);
INSERT INTO reviews VALUES (17123, 520940, 982, 'this game got me through depression multiple times, split your screen with this on the left and a show or movie or even spotify on the right and it will calm you tf down. also buy the 450 monster bike its a dlc but its 100% worth it', 'Lame physics, and lame out of sync engine sounds. Bored after 10 minutes every time i boot this up and try to like it. You should refund it, take the money and go play the O.G. mx vs atv reflex, that game is a pure gem made by actual riders that crafted a god tier motocross game.', 'Very Positive', 81.26, 919.55, 1.95);
INSERT INTO reviews VALUES (17124, 520950, 960, 'the game has is all looks amazing runs really good, sounds are top notch but the driving is cancerous hard to control smoothly and the garage is to tedious and a pain in the backside. wouldn''t recommend. couldnt do more than 20min.', 'Honestly I have been drifting and sim drifting for a long time and never have I felt a game so horrible. The drifting mechanics are slow and heavy, no snappy response, it feels more like an arcade. Not to mention I "Failed clipping zones" Before I even made it out of the zone. I have also never been in a car that is upset and straightens after a "Bumper tap". Watching back on my replays I have never seen harder transitions, some of them are ridiculous. This needs a lot of reworks especially arou', 'Mostly Positive', 72.92, 0.67, 15.58);
INSERT INTO reviews VALUES (17132, 521150, 1157, 'Personally i really enjoy this game, i even bought it for my friend Michael but he said its so bad he would refund it, except he never did. he is a lying italian man', 'After playing 1 or 2 hourse you have essentially played out the full game.  There are no additional hurdles, and even the reasonably robust mod collection does nothing to resolve the underlying issues.  \r\n\r\n', 'Very Positive', 81.16, 4.98, 3.50);
INSERT INTO reviews VALUES (17142, 521350, 376, 'It is very well made!\nPlease add spanish!', 'I mean it''s alright', 'Very Positive', 87.50, 8.15, 1.07);
INSERT INTO reviews VALUES (17156, 521630, 131, 'the game s*cks *ss, but i had an urge for something silly and it delivered\nIs it worth 4USD?... no, in any way shape or form, but if you wanna have a fun moment with your child, THIS 4 USD are no really that off target.', 'Toadled is an incredible simple game, the only redeeming feature of which is the cute art-style.\n\nBriefly, Toadled places the player avatar in the middle of the screen while your mouse cursor takes the role of a cross-hair. Occasionally edible (animals, people, etc.) and inedible objects (bombs) will emerge from the edges of the screen, and you have to "shoot" the edible objects before they impact you, while avoiding shooting the inedible objects. Once you''ve hit enough edibles, your character g', 'Very Positive', 82.44, 0.53, 0.57);
INSERT INTO reviews VALUES (17161, 521890, 6068, 'I broke into my neighbors basement in real life and he did end up touching me but I did not end up respawning back at my house...... 10/10', 'Go play Alpha 1 instead. It''s an actually fun version of the game that is somehow 10x less buggy than the full version. Not worth even a fraction of the $30 that it costs. The puzzles are unfun and tedious, along with them being almost impossible to figure out on your own without a video guide. The platforming is horrendously terrible, and the overall gameplay is just a complete chore to play. One of the worst games I have ever played. (Alpha 1 is great though, I need to reiterate)', 'Very Positive', 80.74, 10.13, 21.88);
INSERT INTO reviews VALUES (17162, 521920, 186, 'Death''s Hangover\n\nHas a total of 6 trading cards.', 'Doesn''t look great, doesn''t play great, grating character dialogue.', 'Very Positive', 86.02, 0.68, 0.28);
INSERT INTO reviews VALUES (17163, 521950, 151, 'not warking bullet srrow \r\n\r\n', 'Game still stutters even with no supersampling on a 980Ti at specific scenes (most notably level 2). Will buy again when this game is more optimized.\n\nAI is pretty dumb and is obviously scripted to go at specific spots. No mechanisms to prevent the player on using exploit (doesn''t prevent you from going inside objects, walls, etc so you can cheese easily your way)', 'Very Positive', 80.79, 21.72, 1.08);
INSERT INTO reviews VALUES (17169, 522040, 281, 'It''s fun it''s cute it''s gay', 'on top of all the problems of the previous game, for some reason they removed the option to play the game in it''s native resolution of *checks notes* 160:140!? literally NOTHING is a multiple of that! the mixels, theyre everywhere!', 'Overwhelmingly Positive', 95.73, 2.43, 65.50);
INSERT INTO reviews VALUES (17175, 522210, 335, '"Sir, I''m afraid he''s jumped into the flower pot."\r\n"Are you sure, deputy?"\r\n"I saw him jump in with my own eyes."\r\n"When was that?"\r\n"Literally a second ago."\r\n"Dammit, he''s as good as gone then. We''ll never catch him now. Might as well go back to patrolling the area. Wait, wasn''t there a dead body here before? I get so confused."', 'I want to like this game because it has a fun concept, but playing this is so frustrating and unenjoyable as it goes on that I can''t recommend it. Between its price and mechanics that set you up to fail, don''t bother unless you''re fine with a game you can''t finish.', 'Very Positive', 83.88, 44.25, 4.90);
INSERT INTO reviews VALUES (17183, 522470, 2448, 'Overall I enjoyed this game - it definitely tickled my love of escape rooms.\r\n\r\nThat being said, the early game was far more fun than the later game. The puzzles didn''t only increase in challenge (which is fine), they increased in obscurity as well. The early puzzles in the first few levels may have taken me some trial and error and serious thinking, but I got them eventually. Some of the later puzzles were so obscure I had to make extensive use of the hint system, and a couple of them I had to ', 'Got this game during the winter sale since I was curious. Tries too hard to be The Room, a much better and much more logical puzzle solving series. The puzzles skip around with no flow, and a solid quarter had me thinking, ''How was I supposed to know to do this without a hint?''. Not a terrible game, but not worth $20. Wait until its on sale if you want to play, or go play The Room 1-4 for a much more enjoyable and worthwhile experience.', 'Very Positive', 82.80, 9.58, 1.07);
INSERT INTO reviews VALUES (17186, 522570, 103, '‎', 'Best described as a nonsensical, buggy conglomeration of generic Unity assets and piss poor English. It is aggressively bad.', 'Mixed', 45.63, 53.02, 3.98);
INSERT INTO reviews VALUES (17201, 523000, 465, 'my daughter became the best prostitute in the whole kingdom and i scored -69 points, god said it was a mistake to let me be a parent. 10/10 game', 'This is such a disappointment. I have read from forums and magazines that Princess Maker 2 was such a classic simulation game only to find out that this game is shockingly boring.\n\nThe game provides no tutorial. You are supposed to raise a daughter and she will grow into whatever character you make her to be. But, for some reason, you as a hero that saved the country, do not have that much disposable income. So, if you are thinking to send your daughter to various classes so that she can master ', 'Very Positive', 93.76, 8.27, 5.18);
INSERT INTO reviews VALUES (17213, 523210, 1296, 'A Normal Lost Phone is a very good little game where you find a girl''s phone. Check her messaging, emails, photos, etc... to find what happened to her. The puzzles are not to difficult, the stoy is good and the grapchics are nice. For his low price, it worth it and I highly recommend it!!! 💗📱💗', 'Indoctrination, the Video Game!\n\nThis had the promise of being an interesting clicker puzzle game, but once the indoctrination started, it went strong!  It was just too on-the-nose.  It was more a supplemental read on coming out in the LGTB community and explanation of associated terms, with a hint of click puzzler.  Just not much "game" to the game.', 'Very Positive', 88.89, 29.98, 1.70);
INSERT INTO reviews VALUES (17219, 523600, 316, 'Software took a little time to get used to and at first glance it looks pretty underwhelming yet there''s still a lot you can do with Card Creator and I would highly recommend it to beginners in design wanting to just get their ideas out of their head. \n\nFor the devs, I would like to recommend an idea. When editing a card, I love that you can add icons and symbols right next to text and would love a little bit more spacing options in order to center the symbols. And even more important, I would l', 'I would not Recommend this or any Software from this Developer to anyone, I will explain why Below.\n\nThe Developer of this Software is deceitful, they dropped support for this software 2 years ago and made a new one called Tabletop Creator. Which is just another Card Creator, set the Price of that one to double the Price. Then Last year they created a new Developer name and Publisher name for it here on Steam, Raised the price of that new Software to $200 and never did a update on that new Softw', 'Mixed', 68.67, 31.22, 2.80);
INSERT INTO reviews VALUES (17222, 523650, 1365, 'https://steamcommunity.com/sharedfiles/filedetails/?id=2271886403\nhttps://steamcommunity.com/sharedfiles/filedetails/?id=2342790443\nhttps://steamcommunity.com/sharedfiles/filedetails/?id=2297875032', 'Well, there was plenty of darkness. And a little bit of lust. I am giving a negative review because I feel like there just wasn''t really much to the game. I played through it in a couple of hours, and wasn''t really impressed.', 'Mixed', 68.72, 4.10, 4.73);
INSERT INTO reviews VALUES (17223, 523660, 2988, 'Game is dead. I can''t believe gamers would let this die.\n\nSo disappointed. Meanwhile, Warzone is bigger than ever. Pathetic.', 'why is their no negative reviews? they delete them lol, game has been and still is trash. lacks content and the unlockables are so much a grind for custom characters that everyone looks like each other cause of the few defaults they have. matchmaking doesn''t exist unless you get friends to play. and single player bot modes are easily trash with no challenge. seeing i have less than 20 hours and only missing one achievement cause its glitched. would never recommend this to anyone. they raised the', 'Very Positive', 91.87, 1.05, 14.95);
INSERT INTO reviews VALUES (17226, 523710, 152, 'pretty good BUT needs work BUT still ok for 10 dollu', 'As it is right now, it''s just WAY to easy to just go in stabbing under the shield to score kills. Currently a deal breaker....that being said, the developer seems VERY open to suggestions and making improvements! I really get the feeling that the necessary improvements will be made and that the game will continue to be expanded upon.\n\nFor that reason, I will not be "returning" the game, as I want to support the developer, because I can see where this could  eventually be a GREAT game.\n\nI look fo', 'Mixed', 65.79, 0.80, 0.77);
INSERT INTO reviews VALUES (17232, 523770, 103, 'This title falls under the "wish there was a neutral button". I played only via Steam Deck, so feed back here for the review is based on my experience playing it this way. First off, the game is labeled as being a verified deck game. This is more or less true, the prologue worked fine with no settings changes. However, getting the actual game to run required forcing it to Proton 5.13-6 compatibility. Some video did not display properly and navigating back to main menu from ends of chapters hung ', 'I was interested in this game based on the music alone as a fan of the music genre the artists for the soundtrack do, but that being said, it seems that the music is literally all this has going for it. The graphics are meh at best, the MC''s voice acting sounds so flat as if she''s uninterested in what she is doing, some of the side actors outshine her in their performance. The timed events are some of the worst I have ever experienced in a timed event game. You barely get enough time to do your ', 'Very Positive', 80.58, 2.92, 2.37);
INSERT INTO reviews VALUES (17233, 523780, 3775, 'Pretty similar to the last game just a bit longer with more things to do. Extra brownie points for making a cool 2000s site to fit the narrative.', '4/10. Poorly written.', 'Very Positive', 94.15, 2.48, 2.75);
INSERT INTO reviews VALUES (17243, 524010, 264, 'This is an awesome TD, I can definitely recommend it. You have a pre-game moment where you define your towers and upgrades, being able to freely respec. You can also choose the difficulty among a big slider to suit the challenge you want.\r\nPowerful towers feel chunky and tough enemies are satisfying to beat.\r\nThe game COULD have some QoL like being able to preview the map before entering and visualizing the map after a victory/loss. Got this on a sale and definitely recommend it.', 'Game is ass, has been ass, will continue to be ass. Don''t waste your money', 'Mixed', 62.12, 10.52, 1.48);
INSERT INTO reviews VALUES (17249, 524220, 45372, 'What I expected: Booty.\nWhat I got: Good story, nice characters, and decent combat. And Booty.', 'Game feels good, but the stupid prologue gimmick where you cannot save during a 30-minute prologue and have to start over when you die is singularly deserving of a downvote and a dumb design call.\n\nHard is fine. Making people redo 20 minutes of easy content to get back to the hard thing is not fine. That''s just petty.', 'Very Positive', 90.04, 71.00, 4.75);
INSERT INTO reviews VALUES (17253, 524380, 114, 'This game looks great!! I know others said they had issues with clarity, but with my GTX 1070 I had no problems. I went into the menu and changed it to Ultra and everything was super crisp. I did notice though that when I went into the main open world, it changed my graphics, so I just went in and reset it and was good to go. \n\nLove the friendly skeleton and chopping wood. The cart gave me some issues at first, but I appreciate that its like real life and if you run into a tree, the wood flies o', 'another cash grab by some devs...dont waste your money or time', 'Mixed', 41.23, 0.92, 1.05);
INSERT INTO reviews VALUES (17254, 524390, 186, 'Its a benchmarking suite, so its useful to compare computers and/or effects of different settings on the same computer. If you dont do these things, you don''t need this!', 'Note that you can purchase this again. Not clear if this is Steam or whoever owns 3dmark, but ugh.\n\nAbsolute GARBAGE. Likely why they''ve dropped the price to nothing... it doesn''t work any more.\nStopped recognizing my system hardware and software, and nothing will fix it. I have re-installed their very clearly WORTHLESS "System information" software countless times without resolution. They manage to have horrible support even in an age of the worst support in all of history. Their site is now ga', 'Mixed', 69.89, 7.55, 7.12);
INSERT INTO reviews VALUES (17260, 524580, 584, 'While this is a remake of the original game, I think it has done a great job on expanding and rewriting the original. I definitely liked this much better than the original Fairy Fencer F.', 'Probably the most mediocre product from Compile Heart. Maybe this will sound a little harsh but this game is a waste of labor. Character design, soundtracks, voice acting are great. Gameplay and game design suck, hence the game sucks. Don''t be deceived by the Steam rating. This game is overrated as heck.\n\nThey should have named this Repetitive Grind Fest instead of Advent Dark Force. They even recycled the story in itself.\n\nMost of the time, I played this with a grumpy cat emote on my face.\n\nP.S', 'Very Positive', 83.39, 14.20, 21.78);
INSERT INTO reviews VALUES (17263, 524640, 156, 'Challenging arcade style action game with a bit of random generated stuff mixed with some RPG levelling mechanics. The audio was well done, the story is old India mythology which is a lot of murder and revenge but also not really intriguing. The game ran well, and offers a fair value under five dollars, but excellent value under two dollars. You can have some fun with this game, but it will not be something that you cherish. I think the equipment and weapons could have been more varied with more', 'Feels like it has potential. The controls & lack of being able to make it full screen were a deal breaker for me though. Can''t play it w/ my taskbar up the entire time.', 'Very Positive', 84.62, 16.25, 0.22);
INSERT INTO reviews VALUES (17267, 524850, 658, 'impeccable vibes. if you want the classic atmospheric rpgmaker feel of ib, wadanohara, yume nikki, etc this def scratches that itch.', 'read a review online that said that this was a "puzzle game" and got it for that reason. I found that most of the puzzles are actually riddles. I dislike riddle games and am very disappointed.', 'Very Positive', 89.67, 32.03, 3.23);
INSERT INTO reviews VALUES (17268, 524910, 880, 'Hidden Through Time is a very good hidden game where you have to find objects, peoples, etc... It''s really funny because you can interact with everything and they do funny sounds, there''s a lots of levels from differents times and landscapes. \nI highly recommend it!!! 💗💗💗', 'I liked the game series before I didn''t.  Incredible CPU hog. Be mindful of data sharing/privacy when playing the game. Read those pesky EULAs and related agreements... This make me wonder if this data harvesting is what causes the CPU spike while in-game.', 'Very Positive', 91.82, 9.37, 9.58);
INSERT INTO reviews VALUES (17270, 525040, 309, 'I grew up with these games and have a soft spot for this old school NES games. This was a no-brainer as a kid who grew up in the 90''s.', 'Ich denke, manche Spiele sollten einfach in guten alten Zeiten nostalgische Erinnerungen bleiben. Was damals schön und gut war, ist heute hässlich und langweilig. Aber Capom hat hier gute Arbeit geleistet. Gut gemachtes Retro-Spiel für Leute, die alte Spiele mögen.\n\nI think some games should just remain nostalgic memories in the good old days. What was beautiful and good back then is ugly and boring today. But Capom did a good job here. Well made retro game for people who like old games.\n\nBazı o', 'Very Positive', 88.35, 8.17, 1.05);
INSERT INTO reviews VALUES (17278, 525240, 116, 'It wants to be Chrono Trigger. It isn''t, but it gets close enough for a recommendation.', 'Full screen mode has a wave aberration that constantly cycles through. There is no borderless window option. The wave does not happen in windowed mode but it locks you in to specific resolutions. Unless your monitor fits one you are either going to be playing in small window or in a window that just off screen. \n\nAnd no I don''t want to go an screw with all my video card settings. If that needs to be done the game is automatically 1 star. Literally every other game runs fine in whatever mode is c', 'Mixed', 52.59, 11.20, 2.97);
INSERT INTO reviews VALUES (17284, 525380, 135, 'As of the writing of this review the game has a mixed rating on steam.  Do not let that rating deter you from giving this game a shot, from my understanding when this game was released there were several bugs, such as maps that didnt work, save points which randomnly teleported you around the map, unfinished textures and other graphical bugs.  If I played the game in that state I probably would have given this game a negative review also, but all of these features have been fixed in the latest v', '==Temporary negative review==\n\nI kinda liked the game, but there are many issues that will have you crashing/restarting the game which kill all the fun.\n\nHopefully I''ll change the review to positive after another patch or two.', 'Mixed', 65.19, 2.88, 0.13);
INSERT INTO reviews VALUES (17288, 525480, 2132, 'Best game for me, the whole series gave me more than SAO, the franchise chosen to be carried on instead of this this one, ever could, Haseo, in G.U case or Kite are deeper characters than Kirito would ever attain to be, at least we have a final version of this amazing Tetralogy, I would love to the original series being remastered as well but I honestly lost hope at this point, but we should enjoy what we get.', 'Bamco removed cloud saves. Do not buy this version.\n\nThis hurts to leave a negative, it is my favorite franchise of all time. These games are great, and they are wonderful ports of the PS2 games with many QOL changes and just overall a great experience. That being said: BAMCO REMOVED CLOUD SAVES FROM THIS GAME.\n\nAgain, Bamco removed cloud saves. If you get a new PC, if you acciedently delete a save, if a save gets corrupted, etc., your progress across four 40-60+ hour games can be wiped out. Ove', 'Very Positive', 87.57, 536.77, 19.20);
INSERT INTO reviews VALUES (17290, 525510, 1000, 'not worth full price but definitely get it on sale, youll get a good few hours of fun out of this game', 'They kinda solved the motion sickening camera from the first game but there isn''t anything really new. Still a very cheap platform shooter, repetitive, dull, dumb AI with funny, unresponsive controls. Much better than the previous game but not good enough. Just boring.\n\nPS: At first, I''ve tried the game playing with a joystick. Actually, it might work MUCH BETTER with keyboard and mouse. Then I thought to myself: If played like that, the experience could be different. But... Nope. Even playing i', 'Overwhelmingly Positive', 95.90, 2.93, 0.40);
INSERT INTO reviews VALUES (17295, 525620, 711, 'octodad''s wife broke up with him: the game', 'This game was very great It was there when suddenly i can''t launch the game no matter how hard i did it still seemed to not working at all, it wasnt very laggy its that it cant start up i tried to reset anything that may be causing the problem but its still there, I hope that The Creators will fix the game', 'Very Positive', 92.12, 7.25, 49.27);
INSERT INTO reviews VALUES (17296, 525640, 411, 'BAM is the perfect balance between the military simulation of Onward and the arcade quick twitch of Pavlov VR.  This is the best VR multiplayer.  The graphics are nice.  The maps are nice.  The guns are absolutely amazing.  Reloading actually makes sense.  There''s usually several attachments for each gun.  There''s several single player type games/challenges available.\n\nGame runs smoothly.  There are a few locomotion options, but I always go for joystick/trackpad movement.  I experience zero naus', 'I can''t find any servers with people in them.', 'Very Positive', 87.59, 3.45, 2.27);
INSERT INTO reviews VALUES (17298, 525700, 527, 'If you''ve played some older online God Games and are intrigued by the evolution of the natural world, you might like this game! I like that there''s a difficulty to the game that''s based on your own knowledge, much like older god games I''ve played. It explains little and you have to figure out for yourself how to get the results you want. When i play this game, I think back on how difficult these older god games used to be and how fun they were, but it''s not for everyone and in today''s gaming mar', 'I''m going to be honest, it''s a good sandbox god game. It''s just hard to progress far if you don''t know what you''re doing and it''s really east to lose your whole world. I lost my farthest world because I accidentally used an item and my last backup save was a too far away. I never had motivation or ability to get back to that point. It is a really good game I just have problems with it.', 'Mixed', 60.72, 35.32, 39.98);
INSERT INTO reviews VALUES (17309, 526140, 321, 'Very well made.\r\nGreat world building and interesting story.\r\nPuzzles are relatively straightforward.\r\nWorked well on my HP Reverb G2.', 'This game is gorgeously rendered and completely immersive. I was enjoying it immensely -- until I literally ran up against a wall. After having played for quite some time and having picked up a battery in the Tower of Cogs, I needed to transport elsewhere. Try as I might, I couldn''t get the door to open to the transport room. I finally gave up and decided to "cheat." When I went to the walkthrough, though, I discovered that I was doing nothing wrong. The door simply should have opened. Oh, well:', 'Very Positive', 83.49, 6.02, 7.40);
INSERT INTO reviews VALUES (17318, 526490, 380, 'Rika best girl', 'imagine playing a game where for most of the duration focus on a character you dont give a fuck about and a character you hate and occasionally throws in a cute girl that was doomed to be the focus for a mid plot line', 'Overwhelmingly Positive', 96.58, 11.40, 14.55);
INSERT INTO reviews VALUES (17325, 526740, 325, 'It is easy to get all the achievements for this game. That being said, I had to re-launch the game a couple times due to bugs that prevented me from progressing forward. The game had really bad english translations which were kind of funny but also were kind of confusing when it came to following the poorly translated instructions. Not that great of a game, but worth picking up on sale if you are achievement hunting', 'Just don''t buy. If you have bought, please don''t play. Waste of money, keyboard and time. I won''t even start about the technical stuff.  The entire game can be completed in 2 hours, and 1 hour and a half is typing random stuff so the game can continue.', 'Mixed', 40.00, 1.62, 4.38);
INSERT INTO reviews VALUES (17330, 526870, 115056, 'The game gives you a beautiful alien planet and basically tells you to build an Amazon warehouse over it.', 'Up until release the game was great, I could play on steam with my buddy using epic.\nAFTER release you can only play together if both are either on the same platform or make both accounts and connect them.\n\nReverse this BS and make it possible to crossplay without requiring all players to have both accounts CONNECTED.\nIt worked fine while the game was in development, so it can''t be that hard to reverse this.', 'Overwhelmingly Positive', 97.53, 315.68, 299.32);
INSERT INTO reviews VALUES (17337, 527100, 1989, 'Any sentient life still reading this forum in 2024?\nThe best game Star Trek fans ever wanted, unfortunately abandoned...', 'BAD first impression. I am irritated I had to create an account and now I’m being asked for an activation code I was never provided. I hate the 21st century. I really really do.', 'Mostly Positive', 75.57, 1.13, 2.28);
INSERT INTO reviews VALUES (17339, 527150, 136, 'Memento mori', 'this game is okay, but quite a few things bring this game down unfortunately. lack of invincibility frames, dodging can feel clunky and how some attacks can outright last wayyy longer than it should such as with totem. I love the design and every boss feels unique and interesting, but poor movement mechanics in a boss rush game is just....awful. its a shame, i really wanted to enjoy and master the game but it just doesn''t feel tested enough.\n\n4/10\n\n', 'Very Positive', 91.91, 14.30, 4.95);
INSERT INTO reviews VALUES (17340, 527160, 137, 'Amazing cinema experience that is beyond belief !!!', 'It was a cool idea. Then the Dev jumped ship to Racket Fury:Table Tennis VR, wherin they continue their tradition of promising and not delivering. The Dev has, according to their post history, last posted in the discussions of this offering back in April.\nLast update was in January.\nAbsolutely DO NOT get this and expect it to be improved, ignore any features ''promised'' either in the description or discussions.\nPlex support uses a hardcoded directory on C:\\, so if you installed it anywhere else, ', 'Mixed', 59.12, 11.85, 7.20);
INSERT INTO reviews VALUES (17341, 527190, 105, '9/10. Greed and hubris.\n\nI enjoyed the characters. I love them. I love them so much. I love that even when they grow up and change over the years, you can still recognize the same person, even if their personality did a 180. The characters are ever-changing in this series. They always reflect on their past self. Always move forward. So much that I would sometimes felt betrayed by how different they have become, but I guess that''s just how parents feel when their kids grow up. Joy, but quite bitt', 'A massive fall from grace from its 2 brilliant predecessors.\n\nAfter yet another 4 year time skip we will spend 3/4th of the game snoozing through Sekai Project''s piss poor attempt at translating the 2008 crash. The rest 1/4th consists of useless characterization scenes, not for the main cast but for side characters that ultimately drop off the face of the earth for the rest of the story. Hope you didn''t want to see any personal development for Lisa, Chris, Eleanor, you get a few sprinkles and in', 'Overwhelmingly Positive', 95.24, 14.68, 14.13);
INSERT INTO reviews VALUES (17343, 527230, 11201, 'I did a single play through of this game several years ago and fell in love with it, but my party disbanded. When FTK2 came out, I played it through to 100% over the course of a year with some friends, and we''ve decided to backtrack into FTK1 now to do the same. I was a bit worried as FTK2 is one of my favorite games of all time given the memories I made with the people I played with. While we miss certain UI upgrades and abilities from the sequel, there''s a serious charm about the art and how t', 'The scaling makes the game feel frustrating, I frequently found myself getting past the start of a run and then it just becomes a slog. Enemies scale quicker than you, and gold inflation just makes you feel poorer and more punished as the game goes on. \n\nPlayed a lot of rougelikes, with this I never felt excited to go back into a run thinking "what could have I done better", can''t recommend.', 'Very Positive', 89.03, 33.70, 16.92);
INSERT INTO reviews VALUES (17347, 527290, 148, 'It was awesome, though for some reason, I had to rely on items for all of my fights', 'The game is workable and if you have ever played an Atelier game before you''ll get more of the same except a few tweaks. Familiar faces are back and the plot is more towards the characters than any big world-ending problem, so don''t expect an epic tale of heroes ala Final Fantasy or Tales of (again, nothing new to the Atelier franchise.). If you haven''t played an Atelier game just know that its a Turn-based JRPG with a big focus on item construction, you live or die based on how well you''ve prep', 'Very Positive', 87.16, 72.45, 158.42);
INSERT INTO reviews VALUES (17351, 527340, 351, 'Very fun! There''s a Discord channel, so maybe more people can gather for some multiplayer games.', 'Edit: Confirmed as of 11/6/16 on a sunday afternoon. Currently 2 servers up with 1 player in each. This game is dead. Don''t buy it.\n\nCute little take on prop hunt from Garry''s Mod. Maybe worth checking out if the concept interests you enough and you have $4 to blow, but it doesn''t really have any staying power. Map design isn''t noteworthy, and the game modes vary from frantic and fun to interminably boring. It can be fun when the mode forces everybody to keep moving but it can also be a total ca', 'Very Positive', 82.62, 8.23, 0.57);
INSERT INTO reviews VALUES (17356, 527430, 9689, 'It''s a more linear Diablo with maps from point A to point B simple as that. Maps are a little bit linear, but it''s still pretty fun.  It takes a while to figure it out the math of the loot, but once you get it is a ton of fun to use the combinations.  There''s no much to say, all the factions of chaos will show up here SLANEESH, TZEENCH, KHORNE, NURGLE, all of them,  since Inquisitors are investigators in Warhammer 40lk.  You gonna have the main campaign plus a bazillion of extra content and extr', 'As you can see, I''ve thoroughly enjoyed many hours purging heretics in the Emperor''s name. But I have to leave a negative review now because I''ve recently experienced not once, but twice, a supposedly extremely rare desync issue between my account''s stash space and the game servers in Hungary, resulting in the complete loss of 100% of the items I had stored there. The first time, Neocore support manually put items back in my inventory via a "general restock of consumables, void shards, and psalm', 'Mostly Positive', 78.11, 71.22, 1478.28);
INSERT INTO reviews VALUES (17357, 527450, 856, 'I would love to be crushed by that girl\nBefore I played Cockroach Simulator i had a small wee wee, no friends, no girlfriend and absolutely no will to live. None of these things have changed, but the game is pretty good.\n', 'Nagadayu kuplyayuchy (cі navat prosta dadaўshy da zhadanaga) vy padtrymlivaece vajnu', 'Mostly Positive', 76.29, 4.77, 9.70);
INSERT INTO reviews VALUES (17363, 527700, 400, 'im 7 years late\n\nbut a janky cheap hidden gem\n\nstill looks and plays good\n\nno openxr or oculus sdk tho', 'Not good\r\n\r\nAnother terrible game, released in a state that should not of been. Devs these days think they can make rubbish get you to buy it on the "promise" it will be improved, but it really doesn''t get any better or they take the money and run.', 'Very Positive', 89.75, 0.18, 0.85);
INSERT INTO reviews VALUES (17364, 527710, 122, 'This game is an unusual blend of adventure, medieval gladiator manager and real estates upgrade. You start with a newly acquired mansion that’s seen better days, few gold in your pocket and a pair of fighting slaves – and with the goal to become leader in the gladiatorial industry and win the royal tournament. Difficulty is more on the casual side, though you will be hard-pressed from the start to earn money in tournaments, as there are fixed costs that you have to pay every week, so you need to', 'Spent 99 cents on this game. I feel like I overpayed! It mostly consists of watching the same attack animation over and over.', 'Very Positive', 83.61, 28.52, 1.02);
INSERT INTO reviews VALUES (17383, 527990, 112, '⠀', '\nIs it really worth loosing your time playing this?\n', 'Mostly Positive', 73.21, 2.62, 2.75);
INSERT INTO reviews VALUES (17390, 528160, 120, 'This game is exactly what is advertised.\n\nI enjoyed The Red Solstice, so I thought I would give this a shot. There is some good humor and this a great game to play when I want a small challenge and just want to blow mutant aliens up. The guns feel great and there is some fun progression for the classes. \n\nThere is some 80''s action movie style campiness to the campaign and some light humor. There is a survival mode and a coop mode alongside the story. If you''re just looking to shoot some aliens o', 'nice array of weapons and decent variety of different monsters to shoot, blow up and set on fire yet a certain "something" is missing as i kill monsters in this game. the cathartic "feedback" feeling of shooting monsters is severely lacking in this game and just made it boring and unsatisfying overall. it would probably be alleviated if it had online coop but that is a moot point since the game did not get enough financial backing for that feature. i rather give the game a middle thumb but i can', 'Mostly Positive', 70.83, 2.77, 0.93);
INSERT INTO reviews VALUES (17393, 528230, 7555, 'Great game. Wished the devs continued working on adding more content rather than make a mediocre sequel.', 'One of my favorite games ever, I never put so much work into learning a game. It''s a ton of fun, it''s very unique, the community (was) amazing, and the game is very deep and rewarding if you buy into the mechanics (dodge, eject/reload, recoil/deviation/heat, many many active items/abilities) and the general premise (roguelike that rewards timely and controlled aggession, and knowledge to make the best of favorable odds).\n\nBut why the negative review? As someone who spent loads of time with the g', 'Overwhelmingly Positive', 95.39, 188.50, 1274.90);
INSERT INTO reviews VALUES (17403, 528550, 780, 'It''s a fun party game. If you''re having friends over it''s worth a play, but if you''re by yourself you''ll probably want to play Underdogs instead.', 'Drunkn Bar Fight is a rather brief, seamed brawler wherein players must incapacitate all men and women (depending on their discrimination abilities) in a level in order to complete the game''s current version. Due to the lack of polishing, even for a game that does not take itself seriously, it is less than satisfying as NPCs can get stuck in areas that force players to restart a level or come up with creative methods to knock out NPCs that have become unreachable. For a $14, 2016 early access ga', 'Mostly Positive', 76.15, 4.47, 1.23);
INSERT INTO reviews VALUES (17405, 528610, 283, 'good lord\n\ni''m guessing a lot of people have this morbidly wishlisted and a bunch probably bite on each sale. I bit on the current 50% so it cost about $3.50. \n\nI won''t spoil the jank fun for those people, but I can say I got about exactly $3.50 out of it.  It delivered: the crazed unbreaking guitar line in the track for Mission 3, a solid hour of gawking generally, 1 funny video, then that was it. I think it was worth it. \n\nThere''s plenty to pick over, but the main thing I''d like to point out i', 'I loved Double Dragon 2 and Double Dragon 3 on my NES so i was excited to play this sequel but tbh the game is trash. The game has lots of bugs, the storyline is not good and the combat system is nowhere near the old double dragon games.\n\n-  Only for double dragon fans and buy it on sale. 4/10', 'Mixed', 68.20, 0.62, 3.80);
INSERT INTO reviews VALUES (17407, 528660, 133, 'ความไวเป็นของปีศาจ เล่นซะเมื่อยนิ้วเลย', 'Only buy if you''re an achievement hunter.\r\n\r\nThe current price tag for this is 15 bucks and in no way is it worth it. The gameplay just consists of colors falling from above and rotating a colored square to get the same colors to collide. That''s all that there is. There''s a few more gamemodes but they mostly consist of minor modifications like the square being a hexagon, colors coming down faster etc. There isn''t any other elements like rhythm which contribute to the gameplay, it''s simply just p', 'Mostly Positive', 72.93, 1.27, 0.83);
INSERT INTO reviews VALUES (17410, 528730, 186, 'i used to play this all the time as a kid to the point my dad would threaten to not let me play it whenever i misbehaved and i would get so mad i would vomit for hours and got taken to er where i was put on suicide watch', 'I''ve played through this game thrice and I''m not even sure the RPG mechanics are real, that''s how little difference it makes to the end result. It''s also criminally easy to just run past the enemies, as they pose no real threat. The bosses can be easily beaten by simply strafing around them.', 'Very Positive', 83.87, 0.77, 7.88);
INSERT INTO reviews VALUES (17426, 529060, 111, 'Buy now and forget about it for a year or two.', 'cant even verb 37 makes no sense how the hell do you switch programs.', 'Mostly Negative', 32.43, 0.67, 15.68);
INSERT INTO reviews VALUES (17433, 529160, 113, 'It''s a cute, simple, collect em all title. \n\nIt''s like a mix of a simplistic turn based tactics game and pokemon. The story is lame but the battles actually aren''t bad. Nice atmosphere. Cute graphics. All innocent mind, it''s not THAT type of game. The battles are short and not all that involved. Completing one takes around 15 minutes maybe, if that.\n\nIs it worth $12? I don''t remember if I got it on sale but I wouldn''t feel ripped off at $12 and I don''t even usually play pokemon types of games. I', 'This thing gets soooo repetitive, if monster girls is the only thing you need to play the game, that''s what it has.', 'Very Positive', 84.07, 8.37, 6.77);
INSERT INTO reviews VALUES (17434, 529180, 4985, 'This is an insanely good game. The devs abandoned it though and that is why the reviews are actually bad. No it is not barely playable, the game plays perfectly fine and is everything you could want from the genre that it is. If the devs would come back to it would be awesome.', 'Valve should remove this game from Steam entirely. The developer, Snail Games, has abandoned Dark and Light in early access, shut down all official servers without warning, and ceased development altogether—actions that violate Steam’s policies and guidelines.\n\nI strongly advise against purchasing this game.', 'Mixed', 51.63, 100.12, 204.65);
INSERT INTO reviews VALUES (17435, 529240, 140, 'The game basically plays itself. My rarest achievements table is dead, but who cares.', 'P2W game. Now following the trend of "banana" with the steam item drops. And the top of the cherry is that cloudsave doesn''t work for a game released in 2017. Lost all my progress back when I did actually played it obtaining half of the 730 achievements.', 'Mixed', 40.00, 1327.00, 11.20);
INSERT INTO reviews VALUES (17438, 529340, 17706, 'Born too late to explore the world. born too early to explore space. Born at the right time to digitally ship opium to china and beat up lesser cultures.\r\n\r\n', 'Paradox asks for 30 Euros for the upcoming DLC "Sphere of Influence".\n\nThat´s 60% of the current asking price of the base game. For a DLC that mostly introduces mechanics the 15 year old predecessor already has.\n\nAbsolutely nuts. Hope this company goes up in flames with it´s aweful DLC practice so it can rebirth itself with a less greedy management. \n\nThis game still doesn´t feel like a finished game almost 2 years after release. Used to be that DLCs would improve the game after it´s release, bu', 'Mixed', 68.41, 249.45, 424.23);
INSERT INTO reviews VALUES (17442, 529440, 330, 'Better than FIFA/Football Club', 'Sorry, but I''m going to be the first negative review here. Unfortunately this game is plagued with bugs that make it just... not fun. Keys/buttons randomly decide to not register (An issue which seems not to have been fixed from the developer''s previous game The Swindle), the game doesn''t display text properly at 1366x768, and it''s other game events don''t seem to trigger when they''re meant to. On top of that, controller support is minimal and only works in game - No menus or dialogue choices wor', 'Very Positive', 88.48, 0.28, 0.57);
INSERT INTO reviews VALUES (17444, 529490, 193, 'I enjoyed Blue Man Group: The Video Game.', 'DO NOT BUY ; GAME IS UNABLE TO BE FINISHED (Not difficulty related, it is soft-lock related) ; At about the 10th or 11th mission, you have to use a giant twin-cannon turret to destroy submarines located in a nearby harbor that is being assaulted. You take the high ground with your allies and commandeer one of the turrets to take out your naval adversaries. Unfortunately, you are UNABLE to aim the turret low enough to hit the two targets that are clearly outlined with red circles. Your crosshair ', 'Mostly Positive', 74.09, 5.53, 4.80);
INSERT INTO reviews VALUES (17446, 529520, 626, 'This is such a fun game and the commentary is hilarious. I would much rather play this than Madden any day! It has good graphic and the game play is fun and addictive. The names of the teams and players are a riot and it just makes you want to keep playing. Hands down one of the best football games out right now IMO. If you like playing football games and want to step out side the norm...check it out!', 'The main quickplay is fun.. \r\n\r\nThe DYNASTY mode is just fucking AWFUL.  I guess their logic is you''re supposed to build the team up over time, but your ENTIRE TEAM starts with 40 rating, so you literally cant do ANYTHING in the games.. you just sit for 30+ minutes getting your ass handed to you.  Its ZERO fun.  You cant run, you cant pass, you cant do anything..  Even the scrub teams just destroy you.  \r\n\r\nHow is this supposed to be entertaining when you cant even get a first down??', 'Very Positive', 93.61, 10.67, 4.57);
INSERT INTO reviews VALUES (17449, 529590, 519, 'Guys, how am i supposed to start the game if i can''t touch anything? 🙁', 'Apparently, this game worked properly a few years ago. However, in its current state, it is completely broken and unplayable.\n\nSome of the issues I''ve encountered include the inability to place posters (which might not sound like a great deal, but it constantly softlocks you), the reset button does not work as intended half of the time (this also softlocks you) and also some bugged animations. And before anyone suggests it''s my PC, I can run Elden Ring at 60 FPS, so I highly doubt that''s the iss', 'Mostly Positive', 75.72, 2.78, 0.20);
INSERT INTO reviews VALUES (17453, 529660, 451, 'Honestly? The game has all the hallmarks of a low production cost indie game, but if you''re willing to deal with a couple glitches/bugs, occasionally frustrating gameplay, and otherwise, you are rewarded with a very compelling and engaging spellcrafting system, fun combat, and a neat little story :3', 'Bought this to tide me over until Echoes of Mystralia because that gameplay demo was brilliant. Loved the concept of spell switching in Echoes and assumed that enjoyment would carry over here, the game looked cute, and it was on sale for $5.\n\nHonestly, while I can see why people enjoy the game, I don''t think it''s worth the money I spent on it. It feels less like I''m fighting enemies and solving puzzles, and more like I''m fighting the game itself to try to progress. The controls feel clunky, I''ve', 'Very Positive', 84.70, 15.75, 2.48);
INSERT INTO reviews VALUES (17466, 529890, 116, 'Honestly, the fact that Maniac Mansion isn''t more popular despite it''s major influence on gaming as a whole is a shame.\r\n\r\nI feel like everyone should play this game at least once.', 'Review originally published at https://www.thecerebralbore.com/2025/02/maniac-mansion-pc1987.html\n\nManiac Mansion is the original comic graphic adventure game from Lucasfilm Games, designed by Ron Gilbert and Gary Winnick.\n\nI’ve never been a fan of Point & Click Adventure games. I like the idea of them, especially the comedy ones that LucasArts were known for, but I just can’t get on with the pace and the puzzles (and to be fair to me, some of them have a reputation for being obtuse …to put it k', 'Very Positive', 81.90, 9.53, 0.32);
INSERT INTO reviews VALUES (17467, 529900, 100, 'This game has already ruined my life, so I''ll just eat a spoonful of cinnamon for every like this review gets\n', 'Broken on Linux, only displays blank screen', 'Very Positive', 85.00, 3.93, 3.65);
INSERT INTO reviews VALUES (17468, 529910, 205, 'I''ve finally entered the long awaited ARK Park and the experience met but didn''t exceed expectations. Quality visuals, though not quite "The Lab" quality but that is expected from the sheer scale of the environments, which look amazing. The dinosaurs are particularly impressive, and sent literal chills down my spine. \n\nAs far as gameplay, so far it is a mix or exploration, material collection to build tools/weapons, scanning new lifeforms.  Also, a couple nice guided rides in trains, jeeps and d', 'THIS GAME DOES NOT WORK! DO NOT BUY!!!\nthe domain shut down a year ago', 'Mostly Negative', 34.63, 0.98, 0.57);
INSERT INTO reviews VALUES (17471, 529950, 122, 'It plays with only one button, so it''s a great little party game if you hook it up to a tv and have your friends sit around the keyboard. I don''t have friends or a TV, so ive only played with my siblings, but I **IMAGINE** that itll be more fun with friends! /hj', 'Local multiplayer only!? Don''t buy.', 'Very Positive', 90.16, 4.18, 0.15);
INSERT INTO reviews VALUES (17476, 530070, 2702, 'so much simpler kind of PC game ... i find charm in its simplicity, knowing i should ignore its PZB ....', 'This game was abandoned by the devs. \n\nJust like every year. \n\nBuyer beware, this Dev is committed to slapping a new number on their product every year a la Fifa', 'Mostly Positive', 72.09, 22.80, 1.77);
INSERT INTO reviews VALUES (17479, 530120, 372, 'me and my wife were about to sign our divorce papers. right before she was about to sign, i remembered i had just bought this game! i told her to give me one more shot and to play this with me as one last hurrah. after playing for 5 minutes, she stabbed me because she was so angry that i couldnt make a stupid burger. she left me fully and i am now spending my days in bed because i can no longer poop because she stabbed my balls. 10/10, love this game!', 'I really like this game. Going to give a thumbs down because the devs have stopped supporting the game and the problems don''t get solved anymore. For example, no achievement unlocks or new patches.', 'Very Positive', 94.89, 5.13, 1.07);
INSERT INTO reviews VALUES (17485, 530320, 1750, 'Everything Everywhere All at Once: The Game, and you play as Waymond.', 'I was totally vibing with this game for first four hours or so. But the gameplay is so bloated! The devs really need someone, who will tell them when they need to stop. When you got that satisfying feeling when a level almost done, all the boring, children level puzzles got solved, but the level is going going going on!!! What''s the point? Even in the end, when we are in the process of saving the world, we need to do overseer''s tune mechanics twice!!!! WHY?\n\nNot to mention lots of bugs and tons ', 'Overwhelmingly Positive', 96.51, 9.57, 10.77);
INSERT INTO reviews VALUES (17490, 530390, 464, 'Brilliant little Puzzle game. Funny in a violent way. Blood and gore plenty. Highly recommend it!', 'Just a mobile game.\n\nI''m surprised that the pop-up ads for Netflix and the game on Apple and Android are even present in a paid game, let alone steam and that the pop-up ads lock you out of your controls, forcing a reset after ever chalter. Ridiculous for a paid game.', 'Overwhelmingly Positive', 95.26, 7.55, 0.38);
INSERT INTO reviews VALUES (17497, 530560, 196, 'This is a review of an early access game. It is rough around the edges; the UI needs work, and a lot of visuals are unpolished. The playable map itself is too small an area. There is no hiding that it feels like it is in late alpha stage, but these things are to be expected.\n\nUnderneath the rough exterior is a real gem of a game. I really enjoy the depth of crafting this game offers, it''s not easy, but it is complex. \n\nThis is a unique treat for any fans of the steampunk genre, because it is jus', 'This game is dead.  It has not been updated in months.  This was clearly just a cash grab and it should be a Crime that steam allows these games to be sold in their marketplace.  Just a quick cash grab for Steam, and the team that published this game.  Their website is even down.', 'Mostly Negative', 26.53, 28.50, 0.42);
INSERT INTO reviews VALUES (17498, 530630, 158, 'i give it an upvote to support the genre, but don''t bother. Just play AoE4 instead.', 'Honestly, this game is a little bit of fun, but the graphics are... odd to say the least, the factions are okay, but there are lots of little things that combine to become a large problem. Units seem to move a bit slowly across the map, its not always clear what each does, and after you tell a Villager to build several things, you have to manually click the X in order to de-select the build menu instead of being able to hit the X like any other RTS game. Also for some reason when you have a Prie', 'Mixed', 58.23, 2.57, 8.28);
INSERT INTO reviews VALUES (17504, 530890, 1879, 'easy to get lost but she thicc tho', 'AWFUL\n\nControls aren''t told to you. There is a section in the start where you have to drop down onto a ledge, no button prompt, no guide/tutorial, nothing. Its not obvious how to get the character to do this, so you end up dropping off a bunch of times. When you die, you have to restart from the begging. Painful waste of time.', 'Very Positive', 84.94, 8.43, 0.28);
INSERT INTO reviews VALUES (17505, 530920, 149, 'Archimedes\n\nHas a total of 5 trading cards.', 'I generally try to be kind to indie games, and particularly stuff that wants to try something new. However, this game just shows a distinct lack of foresight, a lack of interest in following through with the premise, and a lack of overall care for the player.\n\nThe entire game is paced by responding to an NPC sending you messages. However, these messages take far, far longer than they should to arrive, and often just stop without a clear reason for why until you complete relatively arbitrary task', 'Mostly Positive', 78.52, 0.78, 0.90);
INSERT INTO reviews VALUES (17507, 530950, 168, 'With some lovely modern pixel art and plenty of nods to old Amiga run-n-gun games, Tower 57 absolutely looks the part.\n\nHowever, there are some serious game breaking bugs which hamper a wholly positive and fun playing experience.\n\nI recommend this one only if you are willing to put up with restarting from earlier save points due to the unfixed issues in the game.', 'Everything about this should have been a slam dunk. I was expecting an isometric shooter/fighter/beat em up like Ember Knights. And for a hot minute, it was - navigating sewers and underground tunnels and those were fun. But I was losing my patience when it turned into a metroidvania and I had to figure out where I was going. We spent far too much time trying to find the next section getting bogged down in trying to find the next bit of story to get to the action. While the graphics were good an', 'Mixed', 63.69, 1.07, 2.20);
INSERT INTO reviews VALUES (17509, 531050, 120, 'Did you ever beat FTL?\nYoure about as likely to beat this.\n\nThis game is Impossibly hard, even on the easiest difficulty, and thats why i love it.  Battery swapping simulator meets FTL randomness (dont expect to make it your first try...or your tenth).  This game was surprisingly very polished, well thought out, and well executed.  Space mechanic trucking simulator vr experience we have all been waiting for.', 'I would love to be able to recommend this game, but to be honest with you, I cannot. \n\nPros: I love the concept. The tools feel good when you build and repair your probe. \n\nCons: After a brief tutorial on how to refuel your probes, you are thrown to the wolves. Scanning a planet for resources is tedious and takes a different kind of power than the fuel that the scanner probe takes, (which is a different kind of fuel than your ship takes). No explanation on your other probe, which is just as impo', 'Mixed', 63.33, 10.28, 2.87);
INSERT INTO reviews VALUES (17519, 531270, 258, 'Whenever I play a FPS there always seems to be an element to the game that is new, and also elements that I like from other games that are missing. \n\nFor me Art of Fight combines the best bits of all those – especially the option of a non trackpad movement system very similar to armswining which once you get used to is very intuitive. The gameplay is very similar to Onward  – a 4 x 4 ‘milsim’ where you need to communicate clearly with your team mates to plant a virus. There is a lobby when you d', 'I decided to take a risk given the high price and lack of reviews just to see the locomotion method.  I''m not very sensitive to motion sickness, but after a minute or two of disorientation it started to feel very natural.  It''s a bit like cross country skiing, where you use the controllers to push yourself in a direction, and more immersive than teleporting.\n\nThe graphics are very basic and SUPERHOT-like except for the weapons.  Weapons-handling (pickup, drop, and reload) are very awkward and fr', 'Mixed', 69.38, 62.50, 1.12);
INSERT INTO reviews VALUES (17521, 531510, 11552, 'playing this after a ton of other bullet-dodging games, (Undertale, Hollow Knight) was a breath of fresh air :)\n\nalso heard about this game because WE ARE FORSAKEN 🔥🔥🔥', 'no sex scene with barracuda', 'Overwhelmingly Positive', 97.30, 7.72, 30.28);
INSERT INTO reviews VALUES (17526, 531640, 145, 'A UI as good as Hearthstone with cards and a resource system more similar to MTG and a surprisingly competent AI makes going through the long tutorial worth it. As of writing this review game is very generous giving out commons and uncommons for simply completing quests and building up enough f2p coins to draft doesn''t take very long either. I would say Eternal has the most consumer friendly model on the CCG market.', 'The power flooding/screwing, how you mulligan, and how inconsistent your decks play ruins what is a competent online CCG. \n\nMagic the Gathering is already an exercise in frustration with its 60 card decks. Eternal has 75 card decks -- Why?! This just increases the odds of drawing a streak of cards you can''t utilize resulting in many games where you literally lose the game without playing a unit. This, combined with the game''s harsh mulliganing where you can only mulligan once to which you have t', 'Very Positive', 82.07, 79.73, 11.67);
INSERT INTO reviews VALUES (17527, 531660, 170, 'I have played through the EA version twice with several years passing in between and a lot has been improved although content is still around 10 hours worth. Development of new content is rather slow, but when this one is finished it really will be a Piranha Bytes style space western, bugs and all. So if you like Gothic, Risen and Elex, definitely give this one a try!', 'Been in EA since 2016. Don''t want to hate an indi dev but this game is obviously not coming out', 'Mostly Positive', 73.53, 23.67, 1.02);
INSERT INTO reviews VALUES (17528, 531680, 226, 'I got nothing to say except that my 8-bit guns go pew pew', 'This time emulating starcraft but fusing protos and zerg into one race.  \n\nIt''s an improvement over the first game.  Mission objectives are a little more interesting now, though it still feels like it''s lacking something.  A copycat can only go so far if it has few ideas of its own.  \n\nI do like that higher ranks on missions = more unlocks to your loadouts, but the missions themselves still don''t compell me in ways that the 90''s games it emulates did.\n\nI need something more.. This is still a bit', 'Very Positive', 80.53, 6.75, 0.68);
INSERT INTO reviews VALUES (17536, 531930, 364, '9 out of 10 people you pick off the street and ask to play this game will be repulsed, but for a few, it''s manna from Heaven.\n\nDungeon Rats is a game for people who really, really like Age of Decadence''s implementation of combat. It''s a game for the minority of players whose favorite part of AoD was its combat and who don''t care much about narrative. AoD itself is quite a niche game appealing to an audience that enjoys a systems-heavy, RNG-reliant role-playing game that takes that genre title ex', 'was too hardcore for me', 'Mostly Positive', 79.95, 29.47, 7.65);
INSERT INTO reviews VALUES (17543, 532110, 1565, 'The root and seed of the Rusty Lake series.', 'Why cant I play in fullscreen? Needless to say I wont be buying any more of this devs games. Shame on you.', 'Overwhelmingly Positive', 96.36, 3.27, 0.15);
INSERT INTO reviews VALUES (17546, 532190, 688, 'I went into a boxing game and a hockey match broke out.', 'Goals feel unbelievably random, to the point where it kills all motivation to do anything but buttonmash and hope for the best. Everything surrounding the core gameplay sounds fun but there''s not much point if the hockey itself is unplayable.', 'Very Positive', 92.30, 16.15, 0.42);
INSERT INTO reviews VALUES (17548, 532270, 133, 'Really fun game so far but I did feel compelled to write a quick review due to one issue I had.\n\nThere''s a knife throwing stage that forces you to move to the extreme boundaries of your room setup due to a target placed behind a window on the extreme left. If you have what I would consider an average size room setup, for me that''s 2.4 x 2.6 meters, this could be an issue for you. The major problem with it is the very nature of the knife throwing, obviously requiring quite a fast movement with yo', 'By modern VR standards, this is rather outdated and makes its claim of being a "Weapons experience" sadly somewhat laughable.\n\nThe main thing that is noticeably missing is manual reloads, which is something many VR games and even VR mods achieve.\nIn this game, you simply press the grip button/trigger to reload.\n\nFor its price, its not too bad especially if you get it on sale but i cant only really reccomend it but even then, i wouldn''t say it worth it. Experienced VR users will find it limiting ', 'Very Positive', 81.20, 4.92, 0.42);
INSERT INTO reviews VALUES (17550, 532320, 253, 'made me gay. 10/10', 'The Wii U version of De Blob, which was later ported to PC/Switch, is decidedly worse than the original Utrecht version.', 'Very Positive', 88.54, 20.70, 0.23);
INSERT INTO reviews VALUES (17562, 532840, 215, 'It''s like watching your least favourite Aliens movie to get more of the lore of the universe (Stasis games)\n\nBut it''s free and you''re still a fan and it actually wasn''t that bad aside from very obtuse puzzles, being short and having awkward, terrible jokes', 'More of STASIS, same atmopshere and same character styles (everyone is insane).\n\nWhat really made it hard for me to enjoy this game was that the puzzles had no direction to them.  Early on you get a can of protein powder.  The description makes it seem like you''ll be using it to wake someone up, or something to that effect.  What do you use it for?  Using it as an alternative for fingerprint dusting.  Except the last person to use a terminal was a guy in a giant psuedo hazmat suit, and the secon', 'Mostly Positive', 73.49, 2.68, 2.38);
INSERT INTO reviews VALUES (17580, 533300, 2165, 'If you''re a fan of puzzles and achievements, you''ve come to the right place !\n\n*** All ZUP Games have cool Puzzles + Trading Cards + a lot of working achievments ***\n\n+ Successes are letters in different colors that you can ideally use for profile design\n\n--> If you have the option, buy them all in a bundle to save money. You won''t regret it', 'The game''s only meaning is for the achievements for profiles', 'Very Positive', 92.10, 3.78, 0.25);
INSERT INTO reviews VALUES (17585, 533480, 242, 'A difficult game that I''ve played countless times over the years. A remake could really bring out the potential of this one.', 'Clunky UI, lack of tutorial and pretty hard to get into. Char creation is long and in depth, but I hardly knew what my selections even meant for my character. Felt like you have to do a dummy run and just select whatever until you actually learn how to play, and then start over with a char once you actually understand everything. But the game didn''t hold my attention enough to want to do that.', 'Mostly Positive', 70.25, 1.05, 22.15);
INSERT INTO reviews VALUES (17615, 534290, 135, 'Well Designed and fun to play.  A great tribute to classic side scrollers like Ghost n Goblins.', 'not for me', 'Very Positive', 91.85, 52.27, 9.55);
INSERT INTO reviews VALUES (17618, 534370, 301, 'Fun but painfully hard to drive the machinery (skill issue)', 'do not buy the devs does not updated this any more and the tutorial of the game take more then 2 hours and \nthe Ai workers does still not function buy the time you figure that out it is to late to refund the game', 'Mixed', 69.10, 5.95, 6.42);
INSERT INTO reviews VALUES (17619, 534380, 63555, 'Gameplay is easily 10/10, but the writing, oh the writing is so horrible it actually hurts.', 'Ive played this on Xbox.\n\nAs much as hate to say it, this game is a victim of Cancel Culture. Techland dropped Chris Avellone because of allegations against him, not even waiting to see what the outcome of the situation was, and then it turned out Chris was cleared of any wrongdoing. \n\nTechland really shot themselves in the foot in removing Chris from DL2''s development, and it shows. DL2 is worse than the first game by every conceivable measure. The movement feels worse, the fighting feels worse', 'Mostly Positive', 78.45, 48.37, 0.82);
INSERT INTO reviews VALUES (17624, 534550, 1219, 'I can''t say enough how enjoyable this game is.\nThere are many memes and references. Fighting is fun, and platforming is challenging, but not so hard that it makes you stop.\nThe story is simple yet solid. \n', 'The game, is good. it''s very good. I love it. the artstyle is beautiful, the combat feels great, the platforming FELT great- yes, FELT. even if I liked it, i cannot in good will recommend this to any sane man. You will rage at this game to many times, so SO very many times, same thing for the first game both editions, you will like it, and then you will hate it''s playstyle with a passion. if you took out all the needlessly complicated platforming, the the combinations of button combination and a', 'Very Positive', 91.63, 20.95, 30.98);
INSERT INTO reviews VALUES (17651, 535480, 2136, '8/10. Very fun albeit short game. I love the lovcraftian elements! I wasn''t sure how well the medtroivania rouge like combo would work but they do it very well. Takes about 12 hours to beat, but there are 3 endings so its worth a replay or 2. definitely recommend if you have a rouge-like addiction like me! :D', '\nThis is a mostly competent metroidvania with a satisfying Yggdrasil skill tree (which uses gold dropped by enemies), satisfying traversal and movement mechanics (WAY superior to Hollow Knight in this regard), and mostly fluid and satisfying combat.\n\nIt is weakened by its over-reliance on horde mechanics, which introduce difficulty by overwhelming you with on-screen spam. I''m not a fan of this design philosophy, and I especially didn''t appreciate it during some of the boss fights, especially the', 'Very Positive', 82.82, 13.28, 75.57);
INSERT INTO reviews VALUES (17653, 535520, 635, 'It''s enticing to argue that a good deal of the original Nidhogg''s appeal lay in its utter simplicity - the objectives and mechanics were as basic as could be, the art style lent itself well to potato machines. So adding a roster of weapons and revamping the aesthetic to something more cartoon-like seems like it would be breaking that formula, yet Nidhogg 2 manages to retain its identity as a no-frills dueling game. It might seem like some weapons (the two-handed sword) have an obvious advantage ', 'Not Enough Content For Price', 'Mostly Positive', 79.53, 5.52, 4.50);
INSERT INTO reviews VALUES (17665, 535930, 12120, 'It took me 254 played hours to get all achievements and goals completed in this game, and as soon as I finished that last achievement, I wanted to start a fresh new save and do it all over again. This is the only game on Steam I have completed with all achievements, and the only review I have ever written, I absolutely cannot recommend it highly enough. The music is great, the narrators are perfect, the gameplay is chaotic and fun, and it''s so satisfying to wrangle your mess of a fledgling hospi', 'Gets pretty boring pretty fast. The gameplay is: This hospital has X disease, so you build Y diagnostic room and Z treatment room, and patients move from one to the next and then they''re out of the hospital. You also build some necessities (toilets etc.) nearby. Then you wait until queues get bad so you need to build more Y and Z. And you just keep doing that until you get 3 stars and you go to the next hospital and do the same thing but for different sets of X,Y,Z, but the gameplay is essential', 'Very Positive', 93.25, 254.15, 12.80);
INSERT INTO reviews VALUES (17667, 536040, 113, 'Played it a bit, it’s not bad.', 'its ok, but the gameplay was meh, extremely unfair advantage to monsters once there starts to be more than 2 per wave because your cards dont refresh per monster, only between waves\n\nif you get hit at all by monsters your just dead especially if they hit you with status effects such as poison or freeze, the only real way to win is to nuke the monster in under 3 seconds, but then you run out of cards for 2+ monster waves', 'Mixed', 65.49, 3897.35, 0.32);
INSERT INTO reviews VALUES (17670, 536220, 5516, 'This is a story not only about survival but also about how a family falls apart in the midst of the apocalypse. At the center of it are the brothers, Javier and David, whose relationship is put through numerous trials. The game presents a brutal world where even the strongest people can break.\nThe story begins with Javier, the younger brother, trying to protect his loved ones. Soon, he encounters his older brother, David, who has been living in a different camp all this time and has become a tou', 'Worst season imo. The story is lazy and boring, and the choices you make don''t actually have an impact. Most importantly though, who thought reducing Clementine to an unplayable supporting character was a good idea?? 😐\n', 'Mostly Positive', 76.29, 8.57, 9.68);
INSERT INTO reviews VALUES (17672, 536270, 4850, 'Great game. They oughta make a sequel, cause it feels like humankind’s journey is not complete yet', 'Hear me out ok... \r\nThis game is AMAZING; Between the environment and the skill building and everything in-between this game nails it. That being said, there is a massive memory leak issue or some form of corruption that happens at a certain point in the game. It''s like the game cannot handle all the monkeys, the tools, the piles of items, the enemies, the ambient fruit/vegetation, just everything. Numerous playthroughs have ended with hard crashes. immediate FPS drops and system chugs when view', 'Very Positive', 80.41, 77.35, 33.30);
INSERT INTO reviews VALUES (17673, 536280, 149, 'I got it on sale and it was worth what i paid. Interesting concept. You are the pilot of a futuristic hovercraft. You serve as air and tactical support for your squad. You can give them orders and utilize their abilities while you assist them from above. Never really played anything like this but i can only recommend it on sale. Its probably not worth it at full price unless you think you will truly love the concept.', 'terrible experience. very slow, boring and limited gameplay, the hardest difficulty is impossible to maintain sanity through...not because its hard, no the AI repeatedly kill themselves by running out into open fire mindlessly after killing an enemy and getting themselves killed instantly and you''re stuck with a single option of diving in to save them before you fail the mission and cringing at the awful audio file that plays only to have the same thing happen 3 seconds later.\nThe grav cycle is ', 'Mixed', 60.40, 4.30, 4.55);
INSERT INTO reviews VALUES (17686, 536560, 129, 'No netcode, no players, and pretty wack balance. What more could you ask for?', 'dont get thisd game unless you are a incel gooner', 'Very Positive', 89.92, 21.17, 0.55);
INSERT INTO reviews VALUES (17694, 536780, 102, 'Like another one of this series, it''s almost a children''s tale (those games where you have to listen to a story? they''re here).  It''s well done, but trying on the adult patience.  Thankfully hints and skips recharge quickly on casual.  Annoying "do the sequence" puzzles that can''t be skipped.  I''ll give a thumbs up for the quality of the game build overall, but not for much else.  It gets boring fast.  It''s also very short, 2-3 hours, no bonus chapter.', 'The game is generally OK, but no second chapter, awful scraping noise every time you go into a window, and boring alchemy puzzles. It only tool 3 hours on my first play-through and that is simply not long enough.', 'Very Positive', 85.29, 5.02, 3.10);
INSERT INTO reviews VALUES (17696, 536890, 340, 'im not gay but this is a good game. i do love me some resource management fairy themed simulation games but im not gay. not that being gay is bad. im just not gay personally and i need you to know that. i do love fractions as well why do you ask', 'If Glittermitten Grove were any more esoteric and artsy, it would be in an art museum rather than a store page. In other words, it values aesthetics more than functionality and this becomes undeniable when players have to hunt for keys/glyphs in order to progress in the ASCII section of the game. There is no clear equilibrium between entertaining the player and perplexing them, making the mid-to-late game unintentionally laborious irrespective of the developer''s unserious intentions with the gam', 'Very Positive', 82.35, 2.75, 10.57);
INSERT INTO reviews VALUES (17705, 537110, 1095, 'I like my men illiterate 10/10', 'I am going to be honest. The puzzles are too easy. The story is confusing, and it feels wrong overall. I played through it, sure, but that is because I was hoping the story would get better and less convoluted.', 'Overwhelmingly Positive', 95.43, 7.45, 7.20);
INSERT INTO reviews VALUES (17709, 537340, 842, 'Happy Wheels 3d, que mas quieren ?', 'Guts and Glory is not a bad game, but it is not what you think it is when you look at it. It markets itself as essentially 3D Happy Wheels, but this is far from that. Happy Wheels is a game that can relieve stress and can be actually fun. Guts and Glory is a rage game that wants you to make precise movements with the world''s worst movement system.\r\nYou can press A or D for a quarter of a second and somehow your character will turn a full 90 degrees. You can do the same thing a hundred times and ', 'Mostly Positive', 78.74, 10.03, 5.87);
INSERT INTO reviews VALUES (17711, 537430, 142, 'Yes, indeed there is a lot wrong with this game. Narration is pure gibberish, it''s not worth following or trying to understand. Shooting is far from perfect and optymalization should be better. \n\nBut, the atmosphere and level design are spot on in this game. Combined with no tutorials, no uix, it is really unique stuff. That''s kinda adventure game like Scorn and it is quite easy to finish, gameplay while not great it is also not bad. Sometimes you can use some traps in a creative way. So if some', 'This is a situation where I need a "Thumbs in the middle button". \n\nInner Chains left me not really interested to see more after about an hour of play. The main problem is the rhythm of the game which just seems too slow at times and doesn''t keep your attention. Hence why I chose a thumbs down in the end. \n\nTHE BAD: \nThe story feels like it''s not really there. You get told a lot of concepts and see a lot of artisitc cinematics and designs but you don''t know what to do with it. Gameplay has bad p', 'Mixed', 44.37, 6.12, 0.87);
INSERT INTO reviews VALUES (17712, 537450, 504, 'Its a very hard game. the combat i feel is broken because of the auto aim. The enemy AI is smarter than your companion AI. And odd choice like not able to reload, and replenish health. \r\n\r\nThe platforming is fun, but i fell not really the focus of the game. I like the premise of the story, but the story telling is bad.\r\n\r\nThe game have this old school charm though. It tough and unforgiving, but still feels you can beat it. I recommend this game to people who wants a challenging game to play.\r\n\r\n', 'Imagine for a moment that you sit down to a meal in a restaurant. Something like a hearty 3-course meal with all the trimmings... or so you''re told...  but after the first course being a taste of what you''d is to follow you''re suddenly given a stale ham sandwich and a glass of lukewarm water . You don''t stick around for dessert because you''ve already tried to chew through 2-week old bread only to find that it was also turning mouldy. - this meal is ReCore.\n\nWhat starts as a fairly mediocre but p', 'Mixed', 59.72, 61.37, 26.88);
INSERT INTO reviews VALUES (17716, 537630, 143, 'A really fun golf sim! It''s not as pretty as some other golf sims but the feel is excellent. It might be a bit on the easy side especially if you are experienced with other golf games.', 'Probably the best golf VR game I''ve played, completely let down by the fact that there''s no in-game option to reset/recentre  view in VR. Resetting the view via Oculus button does nothing, nor does using Steam''s "reset seated view" option. Neither has any effect on your in-game position/view.\n\nThe default position for the ball is RIGHT AT THE EDGE of your boundary/play area, so for those with smaller play areas, you''re basically screwed if you want to play comfortably - you''re going to be hittin', 'Mostly Positive', 78.32, 50.58, 1.68);
INSERT INTO reviews VALUES (17722, 537800, 6236, 'Really enjoy this game. Despite the cute graphics is very challenging and hectic during those long missions. I end up getting too attached to my crew, and feel awful if one of them doesn''t make it home. War is hell.', 'Amazing idea for a game and a pretty cool set of mechanics.  I would have loved this game if it weren''t for one small and previously implemented feature... push pause! \n\nThe initial tutorials give you a limited idea of how to operate your bomber but after that you''re learning from 5 second real time text prompts mid mission as you''re simultaneously directing navigation, machine gun fire, bomb runs and repairs.  If and when you lose a crew member or even your entire bomber you lose all the progre', 'Very Positive', 88.61, 40.87, 1.02);
INSERT INTO reviews VALUES (17726, 538030, 1538, 'An upgrade to Xenonauts and the original XCOM. If you think beating XCOM is going to prepare you for this game... you''re wrong. Why?\r\nThe stat system in this game means that the only way you get ''OP'' soldiers is through out thinking the AI in the early game and using meat/robot shields to lessen the blow of your inevitable casualties. It''s through utilizing the suppression system, using smoke grenades to rush, and using meat shield privates to scout ahead. There are no class skills; only the wea', 'Its ok but to be honest if i wanted to play a frustrating game with 90''s graphics, sound and loads of micro managing I would just re-install the original X-Com. Its been in early access for a long time and still seems far from finished. \n\nIn its present state and this price point far better turn based combat games are availabe.', 'Very Positive', 81.14, 64.48, 15.53);
INSERT INTO reviews VALUES (17730, 538070, 537, 'A bizarre and grotesque dream world where you can neither die nor wake up.', 'Игра требует от игрока действий, о которых абсолютно невозможно догадаться логически. Сложно понять, какие предметы доступны для взаимодействия.', 'Very Positive', 88.83, 3.32, 0.73);
INSERT INTO reviews VALUES (17731, 538100, 1227, 'imagine a sequel with more npc''s and quests, hats you can actually wear, four biomes for the four seasons, possibility of making two-story houses, more meal options, more skill perks.  So yeah, I love this game, just wish there was more of it.', 'It doesn''t feel finished and feels really empty. Even if that is the point I don''t think its executed well. I like this game but I can''t recommend it.', 'Very Positive', 85.33, 79.48, 27.02);
INSERT INTO reviews VALUES (17743, 538680, 3299, '60% time wasted to talk to NPC and their daily life\r\n20% to set orbment just for removed after field study\r\n10% stuck at boss because wrong equipment\r\n\r\n10/10 would do it again', 'Started with Sky FC last year and Cold Steel 1 made me consider dropping the series. They tried keeping the same structure as previous Trails games, but the 3D traversal makes everything take longer so the game is stretched too thin. I actually felt bored in the last main section of the game, which I never experienced in Trails before. The main character Rean is a stereotypical anime reluctant cool good guy, which I really dislike in this game. The villain is \na bunch of things I don''t like abou', 'Very Positive', 94.63, 81.35, 77.53);
INSERT INTO reviews VALUES (17747, 538810, 302, 'Ok, I''m really enjoying this game and can recomended for fans of simulator games', 'I want more steam engine jobs :(', 'Mixed', 65.56, 3.87, 3.57);
INSERT INTO reviews VALUES (17748, 538840, 136, 'It''s far from perfect. It''s janky, imprecise, and sometimes confusing and infuriating, and yet I keep coming back to it. It''s fun and addictive in such a way that I''m constantly willing to overlook all of my grievances with the game, to the point I''ve nearly 100%ed it.\n\nOverall, I genuinely really enjoyed my time with City Climber.', 'very, very, very shit game', 'Mostly Positive', 75.00, 5.72, 3.45);
INSERT INTO reviews VALUES (17757, 539270, 247, 'Mahjong is a very good classic game not too difficult. The designs are very good and the ambiant is relaxing. I recommend it!!! 🀄❤️', 'Game play is fine but every few months it wipes out all of my scoring record and relocks all of the puzzles I have unlocked. This has happened three times.', 'Very Positive', 84.21, 10.00, 590.48);
INSERT INTO reviews VALUES (17759, 539300, 112, 'Solitaire is a very good classic game with some nice designs and a relaxing ambiant. I recommend it!!! ❤️', 'There is something wrong with the coding of the game. Sometimes it won''t let you pick up cards that are stacked underneath other cards (like a red 10 under a black 9) This fundamentally breaks the gameplay and ruins the entire experience.', 'Mixed', 41.07, 35.95, 1.82);
INSERT INTO reviews VALUES (17761, 539330, 141, 'This JRPG is a nice but short (but there are more episodes to buy to expand on the story). This game will give you a chibi version of Final Fantasy 7 vibes. If you want to play a decent JRPG but, are short on time def this game a shot!', 'I''ve followed this game since it''s failed kickstarter 2 years ago and as much as I''d like to recommend this game, it''s just too lacking at present.  It looks like classic FFVII, but seems to be imploying the FFVII Remake release strategy.  It''s like paying $30 for just the Midgar section.  The combat is extremely barebones with only one magic equipped to each character (the same in fact) and you don''t get any new weapons until the last 30 minutes.  \n\n\nThe world is interesting, the characters cut', 'Very Positive', 84.40, 4.35, 3.33);
INSERT INTO reviews VALUES (17764, 539400, 102, 'I love son of a Witch, I played a lot on switch like 350-400 hours and would recommend it for close friend groups.', 'Very poor experience on steam deck and with the game in general. I couldn''t enjoy my time playing it :(', 'Very Positive', 86.27, 11.17, 0.65);
INSERT INTO reviews VALUES (17768, 539470, 2229, 'I understand and fully support police brutality now.', 'No idea what they tried to achieve here, but the result is simply unplayable as intended (if you try to approach it as a police assault simulator where you actually need to only shoot somebody who aims or shoots at you, and force others to submit). \n\nHere is how it actually goes most of the times. You see somebody standing, they refuse to comply, suddenly pull out a gun, you start shooting your service pistol from about 10-20m away... and miss 2 times in a row. From a distance at which even shot', 'Very Positive', 82.50, 3.60, 1.73);
INSERT INTO reviews VALUES (17773, 539670, 109, 'The Ultimate Knight Training... With Jiggle Physics!\r\nThe story? Something about training to be a knight. The reality? A high-stakes game of "how long can the protagonist survive before getting dropkicked by a tsundere?"\r\n\r\nCome for the action, stay for the... plot. 10/10, would trip and faceplant into fanservice again.', ' Game is 100%''d at time of this review. \n 2.5/10 \nThe game is pretty similar for the Sakura VN''s except for one main difference this time... Theres a guy in it. I thought the whole premise of this entire series was yuri and no men in the worlds, but this game has proved me wrong. For some reason this game has you pick both Japanese and English for achievements, but really it just wants you to momentarily select each language and you get the achievement, doesnt require much actual knowledge of th', 'Very Positive', 83.49, 3.87, 1.55);
INSERT INTO reviews VALUES (17775, 539720, 474, '**Razortron 2000** – it’s like if car races, laser battles, and a reality TV show for aliens all crashed into one wild gameplay! 🌟 You’re not just playing – you’ve become a human disco ball of neon lights, and every corner feels like *Madonna* from the ‘90s suddenly challenged you to a drag race in glitter combat boots! 🎉 Crash? Pfft – just toggle "Instant Comeback Mode" and watch your ship start breakdancing on a trash can lid! 😉 **Pro tip:** Play with headphones – otherwise, the neighbors will', '\nNot worth time.\n', 'Very Positive', 83.12, 19.07, 5.10);
INSERT INTO reviews VALUES (17791, 540510, 233, 'A fun experience. Less of a "game" and more of an interactive art piece. I found it memorable and peaceful. If you like liminal spaces, this game has em.', 'ISLANDS: Non-Places puts the ''pretentious'' in ''pretentious indie games''.\n\nMark my words this was made for mobile, and will probably show up on iOS and other platforms soon (if it isn''t already). It screams touch screen. I thought you could walk around in this. Nope, you just rotate the screen object and literally click on the lights that blink. That is all you do. The color pallettes used are interesting, but that''s about it. The sounds and ''music'' are fine, but nothing special.\n\nWayyy too simpl', 'Very Positive', 82.40, 0.90, 0.20);
INSERT INTO reviews VALUES (17794, 540610, 590, 'Let''s be clear--while the game is tagged with nudity and sexual content, there actually is none! I am not a fan of developers false advertising to sell a game. I feel like they are taking advantage of my loneliness. This kind of deception is sadder than me. I leave a thumbs up simply because I did enjoy the game, despite having bought it for a completely different reason.', 'an strange game with cardboard drawn girls is simply outrageous!', 'Very Positive', 86.10, 6.08, 6.72);
INSERT INTO reviews VALUES (17802, 540840, 1248, 'very nice game!', 'hitman go (one of my favorite puzzlers and puzzle types) but worse. still as lazy a mobile port as it gets, but instead of fun challenges, there are hidden objects to find for useless cosmetics, and not only are there essentially timed levels (killed enemies come back after a few turns, can''t dilly-dally), a bunch of levels employ one of my least favorite puzzle mechanics, moving multiple mirrored characters at the same time.', 'Very Positive', 92.15, 3.87, 16.83);
INSERT INTO reviews VALUES (17804, 540880, 159, 'The art was cute and the music was great, but this was shockingly short for $9 - this was shorter and way less in depth than a number of free vns I''ve played. Also the fact that you can''t skip through transitions really got grating by the end...', 'It''s not my style. I like cozy games but this one seemed low quality story wise and playing mechanics wise. this is not an awful game, just not what I expected.', 'Very Positive', 91.19, 1.93, 0.22);
INSERT INTO reviews VALUES (17809, 541200, 2678, 'This is NOT A BOOMER SHOOTER. Just gonna get this clear, its NOT a boomer shooter. Honestly this NON-BOOMER SHOOTER is pretty fun with the titanfall-like movement and rougelike elements, which means its NOT A BOOMER SHOOTER. This is one of the most fun NON-BOOMER SHOOTERS I''ve played in a while and i fully recommend this NON-BOOMER SHOOTER.\n\nDid i mention this is NOT a boomer shooter?', 'This game feels like a mishmash of the games that the dev likes to play, but without considering what makes certain mechanics work. Buy it if it''s on sale but for 25 CAD it''s just not worth it.', 'Very Positive', 88.87, 9.93, 10.97);
INSERT INTO reviews VALUES (17810, 541210, 3376, 'amzing game but dont buy unless your desprate as sea power (another game made by the same devs) is coming out in november which will have submarines and suface ships and air craft carries and planes', 'After taking advice from friends with this game on how to approach engagements, learning the controls, etc, its fact that youre dropped within 25nm from the enemy at every single engagement means i have no time to ID anything in the water around me, if I do I already have 5 torpedoes in the water after me.\n\nQuite literally just got control over my sub after an approach at 10kn 200ft deep, the moment I open my sensors page to ID the landing ship im supposed to attack I hear "torpedo in the water"', 'Very Positive', 87.38, 10.22, 3.05);
INSERT INTO reviews VALUES (17811, 541230, 200, 'This is one of the better and more interesting TD games. While the graphics aren''t the best, unique level designs and their environment difference in each level look cool and story fitting?\nThe so called story is pretty much just info text boxes that you can interact with through map, although there is few story lines in levels... There are different difficulties for each level Easy - Normal - Hard - Expert. The first three difficulties don''t really offer much, expert difficulty adds more actual', 'I love tower defense games but besides having some performance issues, the refill ammo mechanic is a deal breaker for me.\n\nYes, you must reload your "towers" as they have finite ammo. It takes money to do, which you receive from killing enemies, which means you are limited in towers on the level since you need money to reload existing ones. I feel like I would really love the game otherwise  but this mechanic just fundementally breaks it for me.\n\nThey might as well get rid of the ability to spee', 'Very Positive', 90.00, 54.95, 0.85);
INSERT INTO reviews VALUES (17813, 541300, 1730, 'decent game, wish had a solo player mode, i dont like people -D\n', 'This game was a HUGE let down for zombie survival games. Back in the day when you could greenlight games I did just that with this one because they promised so much and it looked so good. Not only did it take them almost a decade to finally release this game even after going above and beyond there kick starter goal, but it is still so far from being finished it''ll be completely outdated by the time its done. The other thing that has totally deterred me from playing this game is that when you die', 'Mixed', 68.84, 0.68, 22.37);
INSERT INTO reviews VALUES (17814, 541310, 101, 'Nice little game..\nReally reminds me the Jazz Jackrabbit games from the 90''s.', 'I wanted to like this game but it''s just too frustrating at times.\r\nThe game gives a warning in the beginning that it is "difficult". A lot of the game is really easy, so if it tries to be a difficult game, it failed.\r\nThe frustrating parts are where the game just feels clunky, has obstacles with poor timing, or just weird and frustrating design.\r\nI''ve beat god damn getting over it several times, so I can take some frustration. This game I''ve quit. To me it has strong "never been playtested" vib', 'Very Positive', 86.14, 0.13, 8.05);
INSERT INTO reviews VALUES (17822, 541570, 7902, 'I want to be cautious before recommending Sally Face. It has some dark, dark moments.  If you have certain emotional triggers, it might affect you pretty badly.\r\n\r\nBut it''s a great game! Although it can get really dark (and overall is pretty dark) it has a cute, wholesome atmosphere. Almost healing. The story is layered and captivating. At first I didn''t like the turn of events in chapter 4, where things get really dark. And chapter 5 felt like a totally different game. But it''s also quite creat', 'yall only like this game because you relate to the depressive loser mc', 'Overwhelmingly Positive', 97.41, 11.05, 2.60);
INSERT INTO reviews VALUES (17823, 541640, 251, 'If you''re interested in playing disney infinity but don''t care for the figures, get this version, you''ll have access to every character and every play set. There''s so much to do and it''s just overall a hella fun game. It''s always on sale so be on the lookout', 'fuck this game.', 'Very Positive', 86.85, 5.65, 25.13);
INSERT INTO reviews VALUES (17824, 541660, 160, '2.0''s Gold Edition feels the most complete out of the Gold Collection since it''s only missing content are some power discs, compared to 1.0 missing several challenges, the hub, and the hall of heroes, and 3.0 missing several bits of content from 2016, such as 2 playsets and 10 characters that were released on the console version.', 'not very good for modern day, while yes it is nostalgic, it is quite repetitive and is quite boring, as a grown up', 'Very Positive', 91.88, 39.68, 2.30);
INSERT INTO reviews VALUES (17825, 541670, 638, 'you can play as judy hopps', 'claims to come with all the content but is lacking content from 3.0 which came in a later update like the finding nemo playset which is upsetting since it advertises all content but there is no way to get this content so its basically lost media', 'Very Positive', 88.71, 9.95, 0.32);
INSERT INTO reviews VALUES (17831, 541930, 243, 'Okay this game is really neat, gives you big "playing hide and seek as a kid" vibes. Except with fear. And one player''s a big f***off eyeball. \n\nAmazing level design, very artistic.', 'I wanted to put my review out for this game because of the lack of content and over all polish on the game. Over all they have added are two or three maps sence the game has been released in Early Access. The game has a lack of content, maps, and overall replayability. I really like the concept of this game but it fails to optimize the experience and it lacks content and replayability maybe this game will be good after another year or so of development.', 'Overwhelmingly Positive', 96.71, 4.67, 5.92);
INSERT INTO reviews VALUES (17834, 542050, 684, 'A platformer with Studio Ghibli vibes, an interesting world and lots of charming living objects. The controls were a bit wonky, but it didn''t ruin my enjoyment.', 'Forgotton Anne is more of an appearance-over-substance game, in my honest opinion. The game looks great with its nice 2D Studio Ghibli-styled art and well-executed sound design and story. Sadly, the gameplay elements in Forgotton Anne feel lacking. The platforming feels horrid, the puzzles feel oversimplified, and the story, although based on a great concept, is executed in a way so that I sadly didn''t feel like I could become emotionally invested in a sentient mop or lamp post, even if they did', 'Very Positive', 88.89, 7.85, 7.45);
INSERT INTO reviews VALUES (17839, 542200, 102, 'This is one of the funniest visual novels I''ve ever read in my life! It gives a little hint of Fruits Basket but with a protagonist who is Not-Paid-Enough-For-This-But-Is-Doing-It-Anyway. The boys are all wildly different from each other, some more chaotic than others, but the friendships they develop with each other and the protagonist are wonderful to see. I definitely have my favorite (Kyle) but the other routes were really nice to go through as well. I definitely recommend if you are wanting', 'I can''t recommend this game to any religious persons.\n\nAt one point during the story, you have to admit that God doesn''t exist or that God is dead. This is a direct jab at judeo-christian religions.  You must select either one of these negative answers to continue.  This also has NO effect on the story.  It is literally like the developer wanted to be cruel to people with religious preferences, to get them to deny their faith.   I can forgive a lot of things in games (like nudity which didn''t ex', 'Very Positive', 90.20, 24.12, 10.00);
INSERT INTO reviews VALUES (17848, 542350, 125, '.', 'The controls are super bad and the game it is not very well designed. I cannot recommend this game. Thanks for trying.', 'Mostly Positive', 72.80, 1.58, 0.15);
INSERT INTO reviews VALUES (17849, 542400, 125, 'pretty simple 2d tower defence survival', 'Was going to give the game a twirl or two based on the above average pixel art and the positive ratio in the reviews but the game is way too choppy at 23 frames per second to be enjoyable to play with this set of eyes I was given to perceive the world and all the cool games in it so...\n\nDon''t bother unless you love a true ''CINEMATIC EXPERIENCE''. Don''t work so hot when you got to actively interact with the image I find.', 'Mostly Positive', 79.20, 6.62, 4.92);
INSERT INTO reviews VALUES (17865, 542770, 183, 'at 39 years old there isn''t much that makes me feel like a kid, but this game did it.  I positioned the game table at shoulder height and stand right in the middle of the game.  feels like I am a kid playing on the floor preteding to blow thigs up.  my favorite is the tornado.  when I release it I get right up close to it and it makes me smile every time.  I loved tower defense games on the phone, but this is a whole new experience.  All and all one of the best games I have played in VR.  Thanks', 'Does NOT support Windows Mixed Reality. The developers have been asked multiple times for WMR support, but the requests have been denied for almost a year. The game runs... it''s just not playable. If you own a WMR headset, DO NOT BUY THIS.', 'Very Positive', 90.16, 12.57, 0.35);
INSERT INTO reviews VALUES (17876, 543010, 199, 'the game is fun, good to work, but not so realistic as NHL of EA Sports, that just abandoned us, NHL FANS.\n\nWorth to have fun', 'First of all, the lag on the controls is just awfull. I mean awfull. Having played hockey games for decades, this has far the worst lag on passing, shooting etc. \n\nIt''s a fun game no doubt, but really a mess from the start when starting the tutorial. You have to pass all the tasks given to you in order to get the advanced controls but at the same time you are supposed to use use the rookie controls but for my part they didnt work but insted you get the advanced controls with only passing, wrist ', 'Mixed', 68.34, 0.68, 3.02);
INSERT INTO reviews VALUES (17877, 543030, 114, 'its a fun game :) trust me on this one', 'the game crashes a few seconds efter playing the game', 'Mixed', 63.16, 11.30, 0.10);
INSERT INTO reviews VALUES (17889, 543240, 148, 'I quite enjoyed playing Root Letter! It''s a mystery VN combined with some point&click/investigation gameplay. The story is fun and meanwhile some stuff was pretty predictable, I was still interested since the writing is overall entertaining and I was eager to find out the whole truth. I especially liked how unreliable the characters are, as well as how weird some routes were (tbh I preferred the obscure endings over the realistic ones lol, I''d love the alien and curse endings to be longer).\n\nMy ', 'Root Letter is a reasonably compelling and engaging visual novel that delivers a visually striking and atmospheric experience with beautifully drawn backgrounds, expressive character art, and a hauntingly memorable soundtrack that captures the melancholy of rural Japan. Its greatest strengths are in art presentation, emotive soundtrack, and sharp and intriguing dialogue. However, the narrative payoff is sorely lacking, evidenced by weak character development, underwhelming, lackluster, and outla', 'Mostly Positive', 75.00, 12.15, 9.77);
INSERT INTO reviews VALUES (17890, 543260, 775, 'Great adventure platformer from way back, one of the best SEGA master system games. Remastered in a brilliant and respectful way with quick and easy toggle of retro sound and graphics. Still to this day a solid 6-10 hr playthru.', 'As a new player, this game is frustrating. There are zero checkpoints. Depending on the boss location, you can take 5-10 minutes to get to the boss. If you die, you get sent to the beginning. If you get hit once by certain enemies, you just get dragged along their path and end up taking more damage because you can''t get out of their way. There are potions that act as lives, but they are few and far between. Every time you die, you have to wait to stop a roulette for a chance to get another potio', 'Very Positive', 87.61, 13.17, 4.30);
INSERT INTO reviews VALUES (17897, 543390, 136, 'Primitive shooting range where we like Deadpool kill robots with two pistols and katanas. Nothing special, but last levels will make you sweat. \n\nEntertainment for a couple of hours. Buy on sale.\n\nP.s. I believe, impossible on hard difficult', 'this is up there in the top 5 worst vr games i have ever played at least it was better than Concord. do not buy this game at full price or on sale. you are locked to one aria of the map at a time its also super unoptimised  i have a i9 10850k and a 4070 and i got fps as low as 50fps and in vr that is harsh on the eyes. you cant even use the sward 99% of the time because the enemies are too far away oh and the guns also suck and are not fun to use. the movement is also bad and the constant telepo', 'Mixed', 66.18, 1.68, 0.40);
INSERT INTO reviews VALUES (17901, 543460, 1515, '16 hours in and I fail to see why this game gets the hate it gets...\nPlays perfectly, has great graphics that sill hold up in 2024. \n\nI assume it''s because they removed the timer? or because the VA for Frank is different? Maybe because it dumbed down some aspects? \n\nI really don''t know. I''m really enjoying the game so far. I''ve expected garbage and found gold.\n', 'Don''t do it. Hank East will be hiding under your bed and you''ll never get rid of him. He won''t even pay rent or do dishes....', 'Mixed', 61.39, 33.65, 44.93);
INSERT INTO reviews VALUES (17911, 543870, 903, 'THE BEST GAME I HAVE EVER PLAYED AMAZING RECOMEND IT THE HARDEST CHALLENG IS KAKUZU  but you will do it its easy i acidently had caps on  make sure so get the other games', 'Word of caution. The game is not not optimised to play with keyboard and mouse. If you do not own a controller do not buy this game.', 'Very Positive', 89.59, 310.50, 0.48);
INSERT INTO reviews VALUES (17912, 543900, 2213, 'I honestly don''t know why this game got hated on as much as it did, its a little tedious at times but what the game is, is a metal gear themed zombie survival game with an engaging enough story and fun base building mechanics... its a fun experience', '"I forgot to save simulator."\n\nI''d like to start out by saying the game in and of itself isn''t bad. Its a little clunky, but the overall gameplay is decent.\nHowever, the games only save function is when you enter your base camp, while several of the missions have you traversing far from home. Because of this, you can easily lose hours of progress due to various reasons, including failing an objective they forgot to brief you on, death, random server disconnects, and being automatically logged ou', 'Mixed', 64.84, 34.67, 30.98);
INSERT INTO reviews VALUES (17918, 543980, 177, 'I recommend this game if you enjoy other products from Hosted Games, or just enjoy having your choices affect the story. The amount of time you get out of this game is worth every penny. 10/10\nCant wait for more updates in the future.', 'It''s been eight years, this shit is still not done. Save your money.', 'Very Positive', 85.31, 553.32, 28.62);
INSERT INTO reviews VALUES (17925, 544310, 195, 'clustertruck if there were no trucks', 'cant launch :(', 'Overwhelmingly Positive', 95.90, 1.43, 0.65);
INSERT INTO reviews VALUES (17926, 544330, 852, 'I can''t believe they made a platformer that is the batman meme, but about snakes. This game really makes you feel like a snake hahah The controls translate to snake like slithering in a way I almost don''t believe. Super clever and innovative platformer. I''d like to come back and finish this game one day, but for now, I''ve had enough fun with it to move on to other awesome indies.', 'Might be good if the controls and camera weren''t garbage. And they might not be a problem if the snake wasn''t covered in lube. You can wrap yourself around something twice, only to have it fall off by the time you get your camera oriented despite holding "grip". Do these guys even know how snakes work?\n\nIf you''re a casual person that doesn''t feel compelled to collect everything give it a try. If you''re a completionist... hope you have plenty of hair cos you''ll be pulling it out.', 'Very Positive', 86.85, 3.13, 1.58);
INSERT INTO reviews VALUES (17930, 544390, 759, 'It''s 2024 and man this is a good game! Hands down, the CLEANEST hacking sim.\nNot sure on what the devs plans are as far as making more investigative/hacking games but this one is super underrated.\nAnonymous hacker simulator had alot of real world tools but NITE Team 4 is soooo clean.', '"I originally took this game for a spin when it first launched and I had a blast with it. It''s been a few years, and I thought I''d dive back in. I wanted to play through the tutorial to reacquaint myself with the basics of the game. Well, I can''t even progress through the 2nd tutorial mission. I''m told to enter coordinates into an interface. I enter the coordinates, but nothing. I relaunched the game several times. I even re-installed the game. It appears that recent updates have not been kind i', 'Very Positive', 90.12, 357.65, 1.37);
INSERT INTO reviews VALUES (17940, 544550, 4307, 'Such a good time. The beginning wasn''t easy, but once I got going it was very rewarding. From messing with pressures, ratios, temps and logic, to just surviving it has been a lot of fun. I also learned to code and wrote a successful 70 line script to automate my green house temps, gasses, pressures, and lights with zero experience, and it worked. It was a very proud moment for me, lol.', 'It''s charming, quirky, and I''ll likely keep playing it, but I cannot recommend it in its current state to anyone else. \r\n\r\nNothing is explained. Nothing is intuitive or just FUN. I remember several moments in other crafting games where discovery of a mechanic lead to excitement and cheer. Discovery of new mechanics is Stationeers is almost always frustrating, and results in several trips to the wiki or to the in-game encyclopedia, which still leaves you with several questions about how to implem', 'Very Positive', 86.00, 238.27, 13.50);
INSERT INTO reviews VALUES (17944, 544610, 2046, 'This game is gonna make you roll that hard 6.', 'Space combat is very stylish and both sound and visuals are pleasing. That aspect was actually very enjoyable.\nThe campaign is bad, you are blind on big map (no info about strenght of enemy fleets) and moving fleets around takes too long. The story and it''s presentation are just horrible.\n\nThe central combat mechanics probably started as a very good idea, but the game is ruined by the fact that all ships can only be top up and never roll or pitch. This should have been a totally 2d space battle ', 'Very Positive', 88.12, 124.70, 33.30);
INSERT INTO reviews VALUES (17951, 544750, 5402, 'I do not ever review games. But I will here, BUY IT. \n\nI have Tekken, I have DOA, I play them and love them. BUT THIS GAME IS SUPERIOR in all the ways. Movement, combat, ease. \nWhen I want to play arcade fighters with a person who never plays them, I will smash in DOA and Tekken. This game allows for new players to enjoy themselves visually and theatrically. GREAT GAME. Only fighter that deserves my time, BECAUSE the rest of you need to know, YOU NEED THIS GAME. Come play and suck with me <3', 'As someone with over 100 hours on this game, and had made countless custom characters, DO NOT BUY THIS GAME. There is a bug that can happen to you seemingly out of nowhere where your save data will be corrupted, causing you to lose all your game progress, stats, and custom characters. I have lost all of those hours of my life. Hopefully this will keep you from losing hours of your life as well.', 'Very Positive', 83.30, 4.88, 124.90);
INSERT INTO reviews VALUES (17959, 544920, 812, 'Probably the best battle royale experience ive had to this date, so sad it had to die out the fighting the annoucner the maps the crafting it was all so peak :(', 'Fuck that', 'Mostly Positive', 74.26, 49.32, 34.80);
INSERT INTO reviews VALUES (17960, 544970, 366, 'What the heck! Give me back my cow!\n\n\n내 젖소 돌려줘요.', 'This game, while well made, falls on the nonsense side of point-and-click puzzle design. Without a guide, I would never figure out half of the things it wanted me to do, and that''s not fun.', 'Overwhelmingly Positive', 95.08, 1.25, 0.85);
INSERT INTO reviews VALUES (17962, 545040, 297, 'Feather is such a peaceful game where you play as many kind of birds and flying into a huge wonderful world. There''s no objective, this game is made to relaxation and meditation... The designs are nice, I recommend it!!! 💗', 'Feather is a very niche game. It''s essentially a "walking sim" where you are a bird, but there is only about 20 minutes of content, so you will have to be really, really into the flight mechanics for it to make sense as a purchase. I like walking sims, and I especially like peaceful flying games, but this one wasn''t it for me.\n\nRather than doing the procgen landscapes of Superflight, Feather gives you two small islands with a cave system. This is good and bad - the good is you never get a random', 'Very Positive', 87.21, 10.12, 0.50);
INSERT INTO reviews VALUES (17963, 545050, 225, 'I played Badiya for a long evening, and I enjoyed myself. It''s got a very unique feel to it, and I look forward to playing a completed version. However, you should be aware before buying that the game is (as stated) not even close to complete.  I have explored far and wide and  found each of the possible POI that can spawn. I killed a few animals, stole a ton of stuff. General shenanigans. \n\nCurrently, the only reason I can see for anybody buying this game,  is to support the developers in hopes', 'Game was abandoned. Don''t waste your money. Simple as that.', 'Mixed', 52.89, 2.75, 0.75);
INSERT INTO reviews VALUES (17970, 545270, 396, 'GET THis game and let your life change for the better and let all your friendships and rivalries come to an end.\n\n\ns/o 2 maddog  and saber interactive for putting so much effort in this game, talking 2 the community and doing bug fixes and updates this game is gonna be the norm in the future gg', 'This game is shit. fax. Get past 2 tournements okay then the cpu is ridiculous. Shoulda got that refund smh...', 'Mixed', 62.63, 13.22, 4.92);
INSERT INTO reviews VALUES (17974, 545410, 151, 'Nobody will read my review so I will eat 1 Tablespoon of Spicy Ketchup for every like this gets.', 'This is a school homework project. Do not expect anything else.\r\nBad recitation, a photographer that can kill alone an entire army is simply impossible.\r\nAlso you cannot expect that if you caught a soldier other will surrender to you for save him. In 15 hours and different ending and choices made no achievement at all.\r\nIf it-s free you can try it, but not waste your money, it is trash not a game.\r\n', 'Very Positive', 86.75, 4.40, 15.78);
INSERT INTO reviews VALUES (17979, 545540, 430, 'At first I was put off by the lousy ''parser'' system, where there was no real freedom of questioning. The game wanted us to ask ''exact'' questions according to what was programmed. For example, instead of responding to the question "why did I come to your house?" the game would only respond to "why was I there at your house last night?" Since the questioning system is not AI based, its understandable its like this. Ultimately, you will learn that the easiest way to move forward is only by using ke', 'This may not be a popular review given the positive reviews....however I feel the points I make are justified.\r\n\r\nIMODD is a very ambitious game, an FMV where you actually type in the questions. The problem here is you have to type them in the right way, and another thing is it says youve asked a question already, even though the one youre asking is completely different to the one you asked before. Example "do you like the beach?" , was a question I asked, then I asked "do you live near the beac', 'Very Positive', 81.63, 14.48, 7.73);
INSERT INTO reviews VALUES (17984, 545600, 240, 'Great game for the money. Nice story premise, and fun gameplay. I played it through in its entirety, and that''s not something I do with most games I play. Easy to recommend.', 'This game is getting great ratings, which is confusing to me. I was sold on the whole "Fallout meets XCOM" thing, but the gameplay is so rigid and robotic and the story is so trite that I''m having a hard time with it. \n\nYou go out on missions to get intel, but there''s no realistic set up to any of them. Contrary to XCOM, not only are all enemies immediately visable, but they know exactly where you are from the jump. Additionally, their placement is seemingly random, it''s a bit funny. \n\nAnyway, m', 'Very Positive', 81.67, 31.07, 2.17);
INSERT INTO reviews VALUES (17989, 545690, 263, '\r\nGood puzzles. My brain is on fire!\r\n', 'It''s an okay game. For the price it could be worth it if you want to spend a couple of minutes solving puzzles, but don''t expect any real challenge.\n\nIt took me 29 minutes to complete the 66 puzzles included in the game, which means less than 30 seconds per puzzle. The game''s concept is good, but the puzzle design could definitely be improved to make it more difficult. Also, I''m sure there could have been a way to add more progression in the game, like adding different challenges and concepts wi', 'Overwhelmingly Positive', 95.82, 2.37, 0.48);
INSERT INTO reviews VALUES (18005, 545980, 389, 'An OG Xbox classic got the remaster treatment as it deserved!\n\nPROS: Clever gameplay with well-designed levels; Tons of variety in tasks; Collectibles done right; Has a sense of humor; Well-defined atmosphere with fantastic Jazz music; Great game for those who want a 100% completion achievement\n\nCONS: Some camera problems; Occasional performance issues\n\nCONCLUSION: Voodoo Vince: Remastered is the definitive version of the classic original Xbox platformer. It''s still got the same delightful sound', 'I wanted to like this game, i really wanted to, but it always crashes after "dolly playtime" I''ve left comments about this on the discussions page, but no response whatsoever, this is fucking unacceptable. don''t waste time on this game until they fix it, if ever.', 'Very Positive', 91.77, 13.23, 18.58);
INSERT INTO reviews VALUES (18008, 546050, 2134, 'She be puyoing on my tetris', 'Please do not buy puyo games on steam unless it''s either *your* only option or it was your friend(s)'' only option and you want to play with them. The steam versions are ultra dead and kinda cursed. PPT1 Steam especially plays like it was built with Cardboard and Saran wrap for the McDonald''s Happy Meal engine.\n\nOther than that, fun characters, story, gameplay (when the steam version works). I''d highly recommend buying the game for the Nintendo Switch', 'Very Positive', 89.27, 4.88, 35.25);
INSERT INTO reviews VALUES (18010, 546080, 140, 'how a floor breaking sound so LOUD wtf i got scared (my max volume is 20%)\nanyway decent game + cute art', 'Unfortunately, this was a really unpleasant gaming experience for me…\n\nPositives:\n- the way the big sprites were drawn was really beautiful.\n- Lots of save slots which I like.\n\nNegatives:\nThis game feels like an unfinished shell, it’s so bare bones. The story is incredibly flimsy and lacks any details. The premise doesn’t make any sense. It makes sense that you walk into the mansion to shelter from the rain. But why does the character then immediately go into exploring the mansion, looking every', 'Very Positive', 85.00, 5.47, 3.08);
INSERT INTO reviews VALUES (18029, 546430, 1161, 'There is a reason I have more hours than any other reviewer on this game.', 'My main gripe is with the controls, for example, it doesn''t seem that you can control the camera with right click or the middle mouse button like most games of this genre... you instead rely on border scrolling... which is irritating OR using the WASD keys (which is awkward for a fully mouse controllable game). \n\nBesides that, it seems really short and I''m not sure what some things do because they aren''t explained: e.g., there is difficulty sliders that seem to just make it harder with no benefi', 'Mostly Positive', 75.02, 891.90, 1.13);
INSERT INTO reviews VALUES (18035, 546560, 57957, 'The worst part about Half Life: Alyx is now we have to wait 15 more years for valve to make another Half Life game', 'If you plan to use a Radeon GPU be aware you might run into really frequent crashes the dev team doesn''t not know/want to fix. No problem with Nvidia.\nIt''s a pity because the game is great (at least the firsts chapters I was able to play).', 'Overwhelmingly Positive', 98.21, 38.65, 11.77);
INSERT INTO reviews VALUES (18048, 546930, 213, 'Bad Game but good', 'Yuck.', 'Mixed', 47.42, 1.43, 0.53);
INSERT INTO reviews VALUES (18051, 546980, 114, 'this game is horrible but i did spend money on cards for the badge :$', 'Only purchased for the badge... Asides from that, this game is incredibly unfinished with no ending and it is super boring. Not worth the two bucks.', 'Mixed', 42.11, 0.15, 0.35);
INSERT INTO reviews VALUES (18067, 547340, 129, 'I''m interested in playing this because there are a lot of big-breasted girls here', 'ATTENTION!!!\nto ppl who dont know: do NOT buy the steam version!!!\nmake your research about the vn you want to buy! (ask chat gpt)\nMANY, i mean MANY visual novels like these are censored on steam, so NO seggs scenes. There''s still some fan service tho-\n\nThere are also no official patches on the love kami series on steam also.\n\nONLY BUY IF ITS ON DISCOUNT AND IF U DONT REALLY CARE ABOUT THE SEGGS SCENES!!!', 'Very Positive', 86.82, 0.48, 1.10);
INSERT INTO reviews VALUES (18068, 547360, 261, 'It''s a game that combines robot customization with battle racing. Yet, for some reason, I find myself more drawn to customization than to the actual racing.', 'Cool concept, meh execution.', 'Very Positive', 80.46, 9.20, 11.18);
INSERT INTO reviews VALUES (18071, 547410, 221, 'i am just going to make this short and sweet. if you  enjoy cars and enjoy the act  of going sideways and sending it  for as long as you please then this game is for you. many mods. much fun. very smooth when its playing and you dont bump into othe drifters durring and open area drift comp. i have seen people also be able to hook up their logetc race wheel to this game. i have yet to do that but i can assure you it will be even better if your playing that way. for sure reccomend this game.', 'DO NOT BUY THIS GAME!!!\nThey took down the servers which is the only way you can play the game.', 'Mixed', 47.96, 10.55, 7.17);
INSERT INTO reviews VALUES (18073, 547480, 147, 'I love this game''s approach to 2 player VR. It is very easy for a non-gamer to play as the reaper and manipulate the map while I platform on the keyboard/mouse', '1998 called, and wants their control scheme back. WASD to move, up/down/left/right to MOVE THE CAMERA?\r\n\r\nUgh.', 'Very Positive', 89.12, 10.37, 0.28);
INSERT INTO reviews VALUES (18076, 547590, 257, 'This game is great and scratches the itch for Pinball. The tables are designed very well and are really fun and unique to play. The scenery that surrounds the table as your play is very nice and is unique to the table as well. I only have two gripes about this game. The first is the amount of tables you can have out at once. You start the game off in a big living room in a HUGE mansion, but for some reason you can only have three tables out at a time. Even if you own the DLCs you can only have 3', 'Bought any of the tables in any or all other Pinball FX games?\nWell, duck you, here''s your chance to buy them again because none of them transfer over.', 'Very Positive', 85.21, 0.82, 0.85);
INSERT INTO reviews VALUES (18078, 547680, 203, 'Guild Quest is an enjoyable and surprisingly addicting cute little time waster, in the vein of "Clicker" games but not quite one itself, you could call it an Idling game rather. \n\nIt starts off pretty easy in the first few areas, but by the time you get to island 4 or 5 you will start to have those longer wait times for your money to build up. I think it''s great that each island has multiple achievements for building on it meaning that as they add more islands the achievements just keep coming. ', 'Throws allot of money at you at the start from free chests but then feels excessively slow.. Only got to the third island before I realised that.\n\nI know it is an Idle game but atleast make it playable till level 5 or something to grab your attention.\n\nMuch too short of a attention grabber before you realise that pay for chests are ultimately Pay to Win even in an idle game.', 'Mostly Positive', 75.37, 13.87, 1.95);
INSERT INTO reviews VALUES (18088, 547900, 264, 'I''ve played FOF8 multi-player for years and now I''m the commissioner of the FFL. We have a number of leagues and always could use new players. Some of our leagues you can name your team and use your own graphics but if you need help we can do that too. Just buy FOF8 if you haven''t yet and register at                                 \r\nfof-ffl.com/foffflco_forum/ and Welcome.', 'Too add to the list of negatives, this game is basically run by the people who manage the MP leagues, who are in fact horrible. Rude, sarcastic, generally unhelpful old men. There are roughly 5 leagues or so total that have a full 32 members, and it''s basically all the same people in each one. I played this version for about 8 months and never once saw a new league form. All the stuff about how bad the defense/AI are is 100% true. The developer wrote a letter 4-5 months ago stating he was no lon', 'Very Positive', 84.09, 28733.60, 3095.12);
INSERT INTO reviews VALUES (18089, 547910, 396, 'Although it may not be the most original game, it offers a fresh and intriguing horror experience with a great atmosphere, compelling narrative, decent graphics, and excellent sound design. Considering that it''s a short and compact game, I think it''s worth trying.', 'THIS IS CRAZYYYY. I PAID 5 DOLLARS JUST FOR MY GAME TO CRASH AND NOT SAFE ANY OF MY PROGESS, I CANT COMPERHEND WHY YOU WOULD DO SOMETHING LIKE THAT TO A BUY THIS IS CRAZY TO ME.', 'Mostly Positive', 71.21, 2.28, 0.50);
INSERT INTO reviews VALUES (18110, 548340, 253, 'Quick, basic, 30 minute to 45 minute escape room experience. Pretty simple, but enjoyable nevertheless. Puzzles are definitely not brain busters. The confined space of the "Abode" makes it hard not to stumble on all of the parts and pieces needed to succeed. Nothing to write home about, feels more like a proof of concept, or complete level of a game offered as a demo. Ran fine with PSVR2 adapter on a 3090ti.', 'If you can get it for a couple dollars, sure, go for it.  It is indeed just an ''escape room'' like you would play in real life.  Interesting to try, I suppose, but there''s literally no payoff.  It''s a one time deal and $10 is way too much for what is essentially an experimental VR title.  There are free titles with just as much content or more.', 'Very Positive', 92.09, 0.78, 1.77);
INSERT INTO reviews VALUES (18112, 548370, 109, 'Abandonware', 'I bought this on sale for $1.29. It''s got simple game mechanics, and a cool aesthetic. But it''s got one glaring problem:\n\nIt''s not fun. \n\nWhen you''re defeated, you have to send in another teammate to rescue captured heroes. I got my first guy through the dungeon alright. But every other player I sent through died at least twice, no matter what I did. So now my main tank guy is like level 4 just from rescuing all the newbs who can''t even get through the starter dungeon without dying. This is not ', 'Mostly Negative', 39.45, 4.57, 1.40);
INSERT INTO reviews VALUES (18114, 548430, 159848, 'Besides being addictive as all hell, even after unlocking everything that isn''t cosmetic. This game literally gave me multiple online friendships in a single year; not including Bosco\n\nIf one of you guys are reading this. Thank you', 'I love this game to death... or at least I used to...\nI know that a lot of the veteran players will disagree with me BUT in my personal opinion... the game needs more content and the perk system + the abyss bar could use an entire overhaul...\nBut I got the feeling that the DEV team has moved onto other projects (including 2 spin off games which nobody asked for...)\nThey rather spent their resources on a Kickstarter campaign to sell you a 50 € PLASTIC beer mug (not including delivery prices and t', 'Overwhelmingly Positive', 97.95, 1002.48, 598.87);
INSERT INTO reviews VALUES (18119, 548570, 6951, 'The combat is top-notch but the open-world setting is pretty pointless for such a linear game. Story missions which should unlock sequentially have to be unlocked by completing repetitive side quests.\n\nRATING: 6.5/10', 'This isn''t a terrible game.  The story and characters are forgettable.  I didn''t find them that annoying.  The gun play is really good.  I just wish there was an actual sniper rifle.\n\nThe reason I''m not recommending the game is the DLC.  I bought the base game a while back and was thinking of playing it again.  I figured with the sale on I could probably pick up the DLCs for about 400 yen.  However, you can''t buy just the DLCs.  If you want them you have to buy the entire deluxe edition.  That''s', 'Mixed', 64.34, 20.85, 62.65);
INSERT INTO reviews VALUES (18128, 548840, 142, '''A Rose in the Twilight'' truly lives up to its name—it''s like a rose. It is undeniably beautiful, yet it also cuts deeply into the player. Just as one might lament the thorns on a rose but still take joy in the flower itself, this game evokes a similar experience.\n\n\n로제와 골렘.', 'While the idea is neat, there''s something about the pacing that''s deliberately monotonous and tedious, to the point that it felt like a punishment to play.', 'Very Positive', 84.51, 4.32, 2.52);
INSERT INTO reviews VALUES (18133, 549080, 222, 'Experience the joys of telling people what you want them to do, and the horror of watching them try to do it "in their own way".', 'I can''t recommend this game purely due to the barely-functional AI.\nIt either leaves its troops right where they spawned without attempting to move and engage the player, or goes straight to whatever objective it has without concern for tactics. It''s like if you had the older Total War AI but in a system far, far too complicated for just running straight at the enemy. \nBasically, if you spot an enemy tank somewhere, it''s not going to react to you. You can casually drive around the map to show up', 'Very Positive', 81.08, 20.68, 6.38);
INSERT INTO reviews VALUES (18135, 549100, 105, 'got a coupon for it from badges not bad little adhd fun nonsense', 'This game made me cry.', 'Mostly Positive', 73.33, 1.53, 3.28);
INSERT INTO reviews VALUES (18141, 549240, 107, 'Beans: The Coffee Shop Simulator\n\nHas a total of 10 trading cards.', 'the first hour was fun, but game play became repetitive quickly. doesn''t help that the game is pretty buggy and the achievements have been broken for a while, with the game being seemingly abandoned.', 'Mixed', 66.36, 1.55, 5.75);
INSERT INTO reviews VALUES (18154, 549860, 359, 'One Night Stand is a very good visual novel game with a beautiful story. The graphics are nice and the ambiant is relaxing. I recommend it. 💗💗💗', 'Interesting idea, but no deeper than anything you''ll find on Newgrounds. The game lasts for about 10 minutes max, and despite what it says on the page, there is no sexual content or nudity of any kind in this game whatsoever. There are multiple endings, but absolutely nothing in the way of resolution. You''re thrown in the middle of a story, and taken out before the ending of the story. You never learn anything about who your character is, or really learn anything of note about the girl. \n\nIf you', 'Very Positive', 89.14, 19.98, 1.00);
INSERT INTO reviews VALUES (18161, 550010, 1623, 'i dislike the colored people', 'e', 'Very Positive', 90.14, 3.60, 65.43);
INSERT INTO reviews VALUES (18162, 550080, 403, 'Rinka and Ranka are twin sisters (blood related) who consistently make-out, erotically, to power up. Uhh yeah... Anyway,  the game''s pretty fun.', 'game is basically unplayable, crashes constantly and after trying every possible work around I still cant find a way to make it work.', 'Very Positive', 83.62, 21.57, 14.40);
INSERT INTO reviews VALUES (18169, 550310, 132, 'I enjoyed playing this game immensely. Just got stuck a few times. Well done the developer. Whoever it was who left a review calling it rubbish obviously couldn"t do the game .That review should be deleted.', 'I was fine with the game, overlooking its (many) flaws and feeling happy with some of the not-as-cliched puzzles here and there, and the ok-albeit-cliched story right until the point where I had to perform an act of animal cruelty to go on. Having to kill an animal as a "puzzle" is not fun, it''s sick. The game barely goes on after that, and it''s to top it all off with an awful cutscene that made the story that much more cliched and non-sensical. You also (minor spoilers)  don''t even find out wha', 'Very Positive', 80.30, 33.85, 2.42);
INSERT INTO reviews VALUES (18170, 550320, 3455, '10/10, This game is made with passion and love\n\nThis game is one of the rare car racing games that actually gets me excited. Low poly art style, sounds, handling, gameplay and career mode are great. Game doesn''t have dumb internet connectivity requirements or stupid microtransactions, It is filled with a variety of beautiful maps, passion and a lot of fun! The lighting is very beautiful too. Also, when you are passing under trees, a camera effect disables leaves so you don''t have visibility issu', 'It''s not a bad game, but for $25 dollars, the lack of basic options and poor optimization (seems to bog down from light effects in game) makes it a wait  for it to be on sale type of game!', 'Very Positive', 93.98, 40.13, 14.37);
INSERT INTO reviews VALUES (18171, 550340, 230, 'good 👍 i can beat up furudo erika endlessly in training mode', 'I love Umineko, but man this is one of the worst programmed pieces of software I have ever encountered.', 'Very Positive', 88.70, 67.82, 0.45);
INSERT INTO reviews VALUES (18183, 550590, 125, 'A very polished experience - except for one thing which I will mention below. \n\nThe puzzles are pretty good and some took me quite a bit of time to solve. There''s probably not much need for me to state the nature of the puzzles - you probably can get that from the official Steam page screenshots and description and from some of the other reviews. It is not an an extremely novel type of puzzle, although Archaica: The Path of Light does introduce a few new twists that are good.\n\nWhile the game wil', 'I''ve played loads of puzzle games over the last 25 years, but this game made me feel incredibly stupid. Even with knowing where I had to place all pieces, I still couldn''t solve most of the puzzles (or perhaps I did, I have no idea how far I am in the game). Somehow I just don''t see it, and I find it impossible to reverse engineer any puzzle. The puzzles I solved thusfar were shear luck when I accidentally rotated some pieces in the right direction. \n\nI know I shouldn''t downvote a game because o', 'Very Positive', 92.80, 19.05, 1.98);
INSERT INTO reviews VALUES (18186, 550670, 144, 'I showed my friends this and they said it’s better than Fortnite so', 'Bad graphics and mechanic and there is really no sense in this game...\n\nJust a waste of time and money.', 'Mostly Negative', 26.39, 0.12, 2.58);
INSERT INTO reviews VALUES (18191, 550840, 114, 'Picture if you will a game  you stumble across randomly  with only   $1 off it''s $10 asking price and deciding to  take a plunge. Loving it''s overt he top horror theme that  reminds gives you splatterhouse vibes and  liking the idea of a roguelike where your equipments are the body parts of your enemies.  Now imagine that mechanic doing exactly what it says on the tin, with each bits having  a pool of stats it can be, variations  of the same parts from the tougher/miniboss version  of the enemie', 'Extremely janky, buggy, and long since abandoned, so fixes will never come.', 'Mixed', 49.12, 27.95, 0.45);
INSERT INTO reviews VALUES (18199, 551110, 257, 'Challenging puzzle game with tile-flipping mechanics, increasing difficulty and addictive, satisfying gameplay', 'The kind of puzzles I don''t like. I got through the first part and still don''t have any clue on what approach I should have taken in order to solve them. They are either easy and straightforward or too incomprehensible it was easier to keep pressing things randomly until you get what you need rather than actually use your brain to analize the board, plan your moves and execute the solution you''ve made up.\n\nIt is like trying to shoot a target you don''t see. Miss, miss, miss, miss, miss, hit. What', 'Very Positive', 85.21, 1.20, 2.67);
INSERT INTO reviews VALUES (18203, 551170, 166, 'Arshura x Taishakuten', 'good gameplay overshadowed by extreme RNG and pay to win mechanics, very hard for new players to be competitive unless they open their wallet', 'Very Positive', 80.72, 1489.13, 4057.10);
INSERT INTO reviews VALUES (18204, 551190, 113, 'Cool Epic Game. One of those games that everyone has seen at one point, but literally forgot about. Which is a shame because this game is really good lol', 'I really wanted to like this game because demented muppets are probably my worst fear. Unfortunately I can''t recommend it for more than a $5 sale. The environments and character models are not as good as they look in the trailer, the UI is unrefined and sometimes buttons just don''t work. I love the concept and I will give SMS 3 a shot if they make it, unfortunately this version feels unfinished.\n', 'Very Positive', 92.92, 3.68, 0.27);
INSERT INTO reviews VALUES (18211, 551450, 252, 'Very fun roguelike, easy to learn, hard to master.\n10/10\n\nF*ck those mine ships', 'Boring and repetative.', 'Very Positive', 89.68, 1.83, 0.20);
INSERT INTO reviews VALUES (18217, 551620, 427, 'Incredible rougelike. There’s so much content and variety and different skills and ways to play. \n\nIt’s a lot different from the traditional rougelike loop of survive till you find OP items and then win. It’s a lot more about how you explore and interact with the galaxy in an RPG sense.\n\nFor instance, I was playing an ecology/scientist type character. I spent all my time running from fights, landing on planets and studying every animal and plant on them. I thought it was odd that I only got XP f', 'I want to love this game, however, it will not run, in addition it communicates with a server of some kind extracurricular to steams server, with no explanation for such or what its communicating, its not multiplayer.....', 'Overwhelmingly Positive', 95.55, 14.52, 0.27);
INSERT INTO reviews VALUES (18221, 551700, 256, 'Is this game broken! NO! This is one of the best VR games I''ve played. Please come back.', 'Just gone thru the tutorial. Didn''t know need online server to play. Thought you can play offline. The server has shutdown. Refunded. Steam should stop selling the game if it''s not playable.', 'Mostly Positive', 75.00, 30.42, 0.25);
INSERT INTO reviews VALUES (18225, 551770, 1019, 'Fantastic world building, characters, graphics, narrative and art direction. Truly is gem of an experience.\nI just wished the majority of the game wasn''t just Capture The Key and Collect 30 Orbs The Game.\n\nAll combat is frustratingly limited. \nMakes collection 90 orbs in a massive mega super maze not very fun.\n\nIt''s an acquired taste. I overall enjoyed it though.', 'I bought the game because of a recommendation. It has a cool premise: the enemies in this game learn from how you play. For example, if you a run excessively, the will too. If you use your pistol, you should be ready to dodge bullets in the next "cycle". This makes it different from most games where you always want to use all of the tools in your disposal. \n\nFirst of all, out of 5 hours that I spent on the game, about the first 1.5 were spent on pretty much just walking, with occasional bits of ', 'Very Positive', 80.08, 6.88, 8.20);
INSERT INTO reviews VALUES (18228, 551860, 647, 'Wet FTL', 'i''ve tried really hard to like this game, but i don''t. there isn''t really any depth to it', 'Mostly Positive', 72.33, 27.60, 24.18);
INSERT INTO reviews VALUES (18234, 552080, 907, 'I took my friend with a fear of deep sea into the submarine. Flooded the torpedo bay. He almost threw up. Good times all around.', 'Dead game devs aren''t working on it anymore and playerbase is nearly nonexistent. Don''t buy', 'Overwhelmingly Positive', 95.04, 9.83, 6.32);
INSERT INTO reviews VALUES (18235, 552100, 24453, 'absolutely amazing game the amount of possibilities are massive. everytime i''m low i play this game. the enjoyment is just taper. the enjoyment will never fade.', 'Great game to use your creativity, BUT.... if you are on single player. Online is just awful. People ban you for the most weird& unknown reasons. It would be great if there was a way to report those servers/people.Dont look forward to play in online setting.', 'Very Positive', 94.77, 68.07, 148.92);
INSERT INTO reviews VALUES (18240, 552160, 106, 'Yet another amazing puzzle game. Great Job.', 'nice', 'Very Positive', 93.40, 69.13, 0.08);
INSERT INTO reviews VALUES (18257, 552440, 575, 'there is a way to carry over saves from the non-vr version of the game and I''ve been playing from where I left off years ago just around when red sigils start to appear.\n\nI would say the game is a lot more engaging in VR. It pretty much was made for it.\n', 'It feels like there''s zero reason for this to be VR. \nIt''s slow and frustrating. Yeah, that''s the point with puzzle games, but damn irritating in VR.\nOne of the first VR-games I bought way back, and the biggest let down. \n\nIf you already know you like puzzle games in VR - I can''t comment, maybe you''ll like it.', 'Very Positive', 81.57, 3.98, 0.32);
INSERT INTO reviews VALUES (18258, 552450, 465, 'I have now played trough serious Sam for the first time. After trying to  play through it multiple times traditionally. I really enjoyed it.\r\n\r\nThings to know tough.\r\n*You probably need to play around with both controller bindings in StreamVR as well as the VR settings in game to make it control as you want. Since it''s made for Vive wands it has some really weird ideas on how to control the game if you use a more modern controller like the knuckles or any quest controller.\r\n*Quick save is your f', 'This gets a thumbs down for the lack of GOG availability and making me 100% bound to the Steam platform to install this game.', 'Very Positive', 85.59, 14.85, 11.58);
INSERT INTO reviews VALUES (18259, 552460, 144, 'Great game! Used to play it as a kid, and now feels great to play it in vr.', 'This gets a thumbs down for the lack of GOG availability and making me 100% bound to the Steam platform to install this game.', 'Very Positive', 88.19, 3.07, 10.28);
INSERT INTO reviews VALUES (18261, 552500, 41642, '95% off? It''s exactly like a free game.\nI spent a few hours playing it, and it''s a really enjoyable team-coop game with a welcoming community.\nThis game is similar to WWZ / Left4Dead\n\n It''s really satisfying to break every rat''s head with an axe.\n\nStrongly suggested 11/10', 'I want to like this game, it''s got a great design and play style. The problem is that it''s one of those games where it''s been out for more than a month so you might as well not even bother. Everyone who plays has a god tier class and doesn''t have the patience to play with new people, yet they join lower difficulty servers because there''s nobody on the higher ones and act superior. They run off like dicks leaving you to fight by yourself and die as a result because they just want to speed run the', 'Very Positive', 89.86, 141.97, 22.08);
INSERT INTO reviews VALUES (18266, 552590, 1920, 'I am too dumb to wrap up the concept of this game myself, but alas, game essay always come to the rescue, and this game definitely deserves a thumbs up.', 'The premise, art, and music is all great, but the puzzles boil down to walking through long hallways and slowly opening doors over and over while clicking on everything you see. It''s like the worst parts of Resident Evil got their own game.', 'Very Positive', 90.21, 7.13, 3.37);
INSERT INTO reviews VALUES (18268, 552620, 3279, 'This is a really good game in the style of the original wasteland game. \n\npeople reviewbombing the game because of new ukranian localisation are just hateful warmongers.', 'the game is great but theres just one big problem companions die realy easy and thats a problem becose if Fidel dies and you fail one qest your softlocked\n\n\n\ni had a level 8 charecter and now i need to start new game :(\noh and i checked theres no cheat code you can use to save you if that hapens (etleast thats what google sead)', 'Very Positive', 83.53, 26.17, 38.60);
INSERT INTO reviews VALUES (18272, 552700, 1376, 'If you like cutesy Chibi''s, Final Fantasy, and Digimon; this is one big jumble of it all. The game is really fun to play, but if you''re big on story and pay attention to any amount of details, you''ll start to get annoyed with just how braindead the MC''s are. On sale, this game will always be worth it.', 'Don''t get me wrong, the game is good, but the fact that the game barely works due to steam crashing the game when you open the game via the steam library and that it was never fixed is unacceptable.\r\nfor anyone reading this with this issue:\r\nopen the game via the .exe instead of via steam. create a shortcut on your desktop.', 'Mostly Positive', 75.00, 67.62, 11.87);
INSERT INTO reviews VALUES (18278, 552880, 200, 'Stardrop is a very good science fiction investigation game. You work in the salvage of abandoned spaceships. While investigating a ship, you stumble upon a forgotten conspiracy involving forbidden research and abandoned history. The graphics are very colorful for a sci fi game and the voice acting is strong. It has a good unfolding plot and was really enjoyable to play.', 'This game is boring as fuck. Initially needed an environment variable on your PC to apply a fix - that would instant crash the game - and even then the developer dragged out the pacing to a painful degree. No bueno', 'Very Positive', 85.00, 7.92, 0.50);
INSERT INTO reviews VALUES (18283, 552970, 114, 'For a game that cost me less than $1 on sale, this is a really solid, well-made game. The humour is great. Nice graphics and sound. It''s great on the Steam Deck. I''m generally not much of a platformer fan, but I 100% recommend this one.', 'I read a lot of reviews before putting this game on my wishlist. It stayed on my wishlist for a very long time because most of the reviews I remembered said that this game wasn''t worth a whole lot. Finally it dipped below $3 and my bank account seemed to be able to support this quite minor expenditure.\n\nAfter the bit of hype I got from the trailer and from the reviews that I remembered, playing this seemed like it was going to go well. Unfortunately, this game brought me little but disappointmen', 'Mostly Positive', 72.81, 3.78, 0.10);
INSERT INTO reviews VALUES (18284, 552990, 804, 'tremendously fun and addictive, amazing amount of different gameplay styles, upgrades and classes', 'This new Enterprise skin is ridiculous. Why, WHY would a company release dlc that basically NOBODY CAN USE. People have said that it is plainly stated, but it really isn''t. This is essentially a bait and switch. "Look, a new shiny ship you can get" "Oh, JUST KIDDING, thanks for your money". If a class action doesn''t appear in California due to predatory practices, it needs to.', 'Mostly Positive', 77.36, 5737.00, 46.67);
INSERT INTO reviews VALUES (18293, 553260, 396, 'Great game is a watered down version of hoi4 with technology focuses and etc', 'Worst. Random. Number. Generator. Mechanics. EVERRRRRRRR...\nSuffice to say that the RNG is terrible. It basically negates pretty much anything you try to do. 80% chance of doing something? Fail 20x in a row. That breaks any known laws of probabilities I know, so you''re even if you have managed to put all the best projects together, which supposedly boost your chances of success, none of that actually matters due to the RNG being so profoundly broken.', 'Mixed', 58.33, 38.52, 46.27);
INSERT INTO reviews VALUES (18295, 553310, 3916, 'I fucking love smacking my friends'' balls around\n\n\n\n\nThe game is fun too', 'game is fun but dead, every active player is some 2k hour tryhard. you need to wait for 20 min for every match or join the discord server thats populated by weebs and other permenantly online people, wouldnt reccomend it if you dont only plan on playing with friends', 'Overwhelmingly Positive', 97.17, 38.40, 10.97);
INSERT INTO reviews VALUES (18301, 553420, 8714, 'Tunic is the most thought provoking and engaging game I have played in a long time. Initially it presents as a solid (but beautifully stylised) third person adventure with your normal attack/dodge/block core mechanics but slowly reveals itself to be much more.\n\nThe game starts without stifling you with a mandatory hand-holding tutorial segment - instead mechanics and the main quest are explained through interaction with the world and collecting mysterious manual pages for the player to interpret', 'TUNIC could have easily been a 10 out of 10 game for me. Amazing exploration and storytelling. Puzzles are not very complicated, and don''t tickle my brain the way a puzzle in a Zelda title does but they''re okay. But the souls combat is horrific. After awhile it''s just not fun. It feels like a chore. It''s been a trend for developers to mush souls combat into their games and it shows. MOST OF THESE GAMES DON''T NEED SOULS COMBAT, INCREMENTAL DESIGN WILL SHOW YOU WHAT BEST FITS FOR THE GAME. If you ', 'Very Positive', 91.76, 20.10, 14.42);
INSERT INTO reviews VALUES (18306, 553480, 233, 'I have never played a game like this. I don''t think there''s any game that you can really compare it to. The Pirates Fate gets weird as you play it and weirder if you decide to replay it a few more times. The story has a very interesting concept to it and I would be interested in seeing other games similar to this one in the future. A lot of love was put into this and I''m impressed with the quality of the product overall. Would recommend.', 'This game popped up in my queue by chance and wish-list it immediately! Was so excited for the release that I sat awake 2AM in the morning to wait for the upload. When it finally did , I played about 4 hours of the game and already found it a bit lacking. The art work looks gorgeous but felt they could''ve made more expressive characters. In general the characters lacks depth and it doesn''t feel like your building any meaningful relationships in the game. \n\nI absolutely loved the idea for your pr', 'Very Positive', 88.41, 7.70, 14.87);
INSERT INTO reviews VALUES (18309, 553540, 2007, 'This game will never be complete until you can re-watch an entire combat scenario in real time from start to finish. Not just the last 5 seconds. :(', 'One of the kind tactical gameplay.\nBut any strategy progression is actually pointless. Everything is auto leveled to player squad, so there is no possibility of getting ahead the enemy in any capacity. You progress only to catch to enemy in power, not to overpower them.\nNeeds rework. Or atleast mod disabling autolevel mechanics.', 'Mostly Positive', 75.44, 9.42, 10.97);
INSERT INTO reviews VALUES (18314, 553640, 2953, 'Pretty short game, really fun cathartic combat but the story does go all over the place. Apparently a lot of players complain about hitstun which means they didn''t pay attention to the tutorial, you can recover from hitstun instantly by pressing the jump button to recover a la kingdom hearts.', 'I feel like I would have genuinely enjoyed this game if the narrator would actually shut the hell up', 'Very Positive', 80.12, 4.40, 0.98);
INSERT INTO reviews VALUES (18317, 553760, 112, 'Einlanzer\n\nSo far, I am enjoying the game. The story is interesting enough to keep me going. The combat animation is basic, and enemies feel a little flat, but nevertheless it keeps me content. I will say that the more levels you get the more combat opens up for you. Exploring feels like it is rewarding, as far as loot and exp, which is nice because some games don''t do this well. The chemistry of the party is fun. Banter, insults, silliness, and fun. The Mc is dense and a bit annoying atm lol (h', 'Story not great. \nControls terrible.\nGameplay has unpredictable difficulty spikes, which seems to be a trend for rpgmaker titles.\nYou can choose your subclass  - that''s a cool customization but, that''s pretty much where ''build'' ends.\nEvery single rpgmaker dev out there compares their game to classic titles. Don''t buy into these promises.  It''s a reference to the tools, not the experience, ime.\nGet the other one this dev made - it''s an amazing, unforgettable game. \n', 'Very Positive', 91.96, 51.05, 2.40);
INSERT INTO reviews VALUES (18323, 553850, 566023, 'They finally found the corrupt official that was putting war funds into his own pockets , causing all helldiver''s weapons to be weaker and outdated models. \n\nWith patch 1.001.100, helldivers finally have the right firepower to keep super earth safe. This game is finally back on step to being GOTY again. \n', 'I went to report a hacker and the in game reporting system says that I "cannot report someone for this reason". What?', 'Very Positive', 82.68, 132.67, 237.32);
INSERT INTO reviews VALUES (18334, 554310, 1090, 'only got this for the troll face emoticon. best purchase of my life', 'Game does''nt even  open, why bother selling it other then the Emojis\n\n\nif u think Emojis are worth itt go for, remove all files from library and keep it open for about 2 hours, thats how to get the @ hours count to buy stuff', 'Very Positive', 91.65, 2.00, 2.70);
INSERT INTO reviews VALUES (18341, 554600, 323, 'As an RPG, it''s nothing special. But it doesn''t want to be, it wants to help you memorize all them Katakana. And that it does very well.', 'If you''re hoping to run this under proton, don''t bother.  Tried a number of versions but never got beyond a black screen and some joyful music.  As it''s an HTML/javascript based game, Starting from the index.html or even adding a <base> tag didn''t do anything. \nAccording to protondb others don''t seem to have these issues.. but ubuntu 24.04 is a no-go', 'Very Positive', 93.50, 15.48, 0.15);
INSERT INTO reviews VALUES (18343, 554620, 12797, 'Life Is Strange Before The Storm was a fantastic game. The story was great. Graphics looks the same as Life Is Strange. This game is prequel and you play as Chloe Price. Max best friend. Well, she is being mean to anyone sometimes. I like her, tho. She is a great character, but I don''t like she is being mean to anyone sometimes. Kinda shame that, Chloe doesn''t any power. Only use argument with other people. I think it''s her superpower. The writing is heartfelt, and every character feels complex ', 'I want to get hit by a train after playing this.', 'Very Positive', 92.68, 8.60, 10.35);
INSERT INTO reviews VALUES (18351, 554750, 122, 'it''s an okay game x3', 'franchise mode I cannot chose offensive plays fix??', 'Mixed', 59.84, 2.35, 5.97);
INSERT INTO reviews VALUES (18360, 555000, 294, 'Goat 👍', 'Wont even start anymore', 'Very Positive', 89.46, 32.82, 3.67);
INSERT INTO reviews VALUES (18363, 555050, 121, 'This is great if you want a solo table tennis training challenge vs. challenging a.i. robots, or if you just want to be able to play some table tennis at home without any equipment, and without the need to have others ready to play it with you. Half of the 16 computer a.i. opponents available are really hard to beat at first (it''s more reasonable after you get very good at the game). That''s why I call this a "table tennis training challenge." However, if you ignore the crazy difficulty in the Go', 'Use to really enjoy playing this game. However, something has happened and it seems there are NEVER any players to play with online if you''re using SteamVR. My hunch is the developer isn''t doing any work and future development on it and the cross-platform play with other devices must now be broken. I used to regularly find matches in the Quick Match mode, but now no one is ever online.\n\nSpend your money elsewhere until they fix it if you enjoy the social and competition of playing others.\n\n(Stra', 'Mostly Positive', 79.34, 8.73, 46.45);
INSERT INTO reviews VALUES (18368, 555150, 2164, 'ts is peak unless u got ur brain fried by shorts and tiktok (short ahh attention span) because alot of running around but its so gooooddd (cant let gang know i fw this fr)', 'To be honest, I dont understand why people love this game so much. From all the reviews I read, I thought this was gonna be the best and most heartfelt story ever, but it kinda dissapointed me. Sure the story was nice but nothing else. The story with the fox was also really lack luster. I wish they would have done something more with the story of what happened to the fox cubs, or atleast expand more on the wolf that occasionally showed up.\n\nThe gameplay was mid too, the whole running around and ', 'Mostly Positive', 75.23, 1.40, 1.62);
INSERT INTO reviews VALUES (18369, 555160, 30739, 'CS:GO in VR, but instead of Russians yelling "Rush B," it’s furries and social rejects screaming "UwU" while team-killing you. The gunplay is realistic enough to make you feel like a tactical genius—until you drop your magazine mid-fight and get knifed by a 12 year old sweat who lives in the metaverse.', '1. Game was very good\r\n2. Then workshop support was removed in favor of some third-party mod website, many mods (all which I used to play) weren''t ported over\r\n3. Then the game has become insanely unoptimized, I couldn''t smoothly play it on a Ryzen 7 7800X3D + 64 GB DDR5 RAM + RTX 4080 Super\r\n4. Then the game just stopped running at all. I tried troubleshooting but it just kept saying something like "Unreal Engine — SteamVR plugin was not found…" And found a lot of people online who had the same', 'Very Positive', 89.97, 29.97, 10.00);
INSERT INTO reviews VALUES (18372, 555210, 308, 'Honestly, this little VN is good. For a free and simple game, its story is a lot better than other paid games I’ve played before. I didn’t liked much the “true ending”, but the essence of the story was really interesting. I’d play another game by those devs, I hope there’s more to come!\n\n6/10.', 'Personally didn''t care for it. The English translation needs a lot of proofreading as it''s full of errors and clumsy, awkward phrasing. The story is good enough to keep me interested but the mood often abruptly changes unexpectedly. For example, a scene where you''re in a dark forest and fearing for your life and then the main character is suddenly regretting that he''s not popular. The story moves way too quickly for me, it doesn''t give you time to understand the motivations of the characters on ', 'Very Positive', 85.71, 1.73, 1.05);
INSERT INTO reviews VALUES (18373, 555220, 2557, 'A masterpiece!  Gameplay, story, music, art, all of it, just brilliant!', 'Cant really get into this one. If i''m being as honest as possible it''s not really that intriguing or scary at the start and that alone made me not want to continue playing this game. Judging by the reviews most would disagree with me but i just cant see myself putting more time into this.', 'Overwhelmingly Positive', 96.21, 8.73, 0.77);
INSERT INTO reviews VALUES (18377, 555290, 115, 'Super cute, fun puzzles, a neat little rewrite of Sleeping Beauty, and the art is well done! I thought it was totally  worth the money :)', 'very cool art. gameplay kinda kills any joy one could take from the game.', 'Mostly Positive', 78.26, 3.12, 3.03);
INSERT INTO reviews VALUES (18381, 555400, 189, 'Good game, worth it. The updates come as fast as they do for Zomboid. Still worth a play though when you turn on the beta version.\n\nBought this back in 2017 when it released. \n\nOnly 2hours on record but that''s only because at the time my computer couldn''t handle it. Now my playtime is rising.', 'This game have been in very early access from begining and still is. Last update is from 2022...', 'Mostly Positive', 75.13, 2.28, 15.88);
INSERT INTO reviews VALUES (18384, 555510, 335, 'Watched the trailer, looked at the screens, thought what the hell. I bought it, played it - it''s really crazy. I''ll keep playing)', 'Do not purchase this game. It is abandoned by the developers and filled to the brim with bugs that have riddled the game into a state that is nigh unplayable. It is a shame too, because the game had an interesting concept but there was not enough follow through.', 'Mixed', 51.34, 7.45, 2.53);
INSERT INTO reviews VALUES (18386, 555570, 819, 'Infestation: The New Fail of Zombie Open World Walking Simulator. \nTry not to get bullet in your head in ghost town by AWP.\nGo give it a try, is free, no charge.', 'Game is just like it was 7 years ago. Unfinished and fiilled with bugs. Complete waste of time and has a steady stream of decreasing players. That being said I''m part of the people leaving this game.', 'Mixed', 42.74, 85.17, 80.18);
INSERT INTO reviews VALUES (18402, 555880, 1185, 'The single best VR game I''ve ever seen for people who don''t get motion sickness. All those comfort options? Teleport, screen fade, vignette, snap turn? You can turn them ALL off. You can have full locomotion and smooth turning. You can slide, and jump. You can do triple slowmo spinning tumble flips while shooting dual pistols at everything you see.\n\nIf there''s anything that remotely touches the movement possibilities of this game, I''ve never found it.', 'Fine game, but servers are dead, so online tags is a lie', 'Very Positive', 86.16, 14.98, 2.18);
INSERT INTO reviews VALUES (18406, 555950, 2743, 'The story takes place between Danganronpa 1 and 2; however, I recommend playing it only after completing both games. While the gameplay might not live up to expectations, I found the story enjoyable enough to keep playing.', 'i feel like im on some sort of list now after finishin this.', 'Very Positive', 82.72, 20.08, 10.12);
INSERT INTO reviews VALUES (18409, 556050, 243, 'This game never got the love it deserved, the creators never did enough marketing nor expanded the content and it is amazing. Only works with friends and bots. / Nunca recibió la atención que merecía , jamás expandieron el contenido ni le hicieron suficiente publicidad. Solo funciona con amigos y bots.', 'I played a couple of matches and it was really fun -- I like a lot about it. However, matchmaking was dead and I couldn''t find a match. Also, you can''t matchmake against other players with a friend. How about some 2v2? Or even the ability to join a multiplayer matchmade match with a friend? Will pick this up again once (if) they add  this feature and if the player count increases so that I can actually play it online and not VS bots.', 'Very Positive', 93.83, 1.18, 0.38);
INSERT INTO reviews VALUES (18415, 556180, 312, 'Buggy but fun with friends :)', 'Game appears to be broken and unable to launch. Forum is a graveyard of people reporting this issue with no response. Does not appear to be supported, which would be a major issue in a multiplayer game even if it still did launch properly.', 'Mostly Positive', 73.72, 22.47, 7.53);
INSERT INTO reviews VALUES (18419, 556240, 222, 'Disoriented, against my expectations, turned out to be a minor masterpiece. A platformer that plays on a fear of heights (combined with dizziness), that at times requires very careful jumping, and constantly shifts gravity such that pretty much any surface you see will become important at some point. It''s also a tricky puzzler, with elements such as switches that rotate given surfaces to help lead you elsewhere, buttons that change the environment from light to dark to reveal hidden parts and de', 'There is no door.', 'Very Positive', 80.18, 7.10, 0.92);
INSERT INTO reviews VALUES (18425, 556340, 123, 'Go Play F.E.A.R you hoe bag!!!', 'The other negative reviews all say the same thing, and I pretty much agree. The levels aren''t interesting, they don''t feel like a real, cohesive world but like the same 3 models plopped over a small section of a canvas. The scale is accurate, but this doesn''t work in its favor. Picture yourself bending down to pick up an action figure that a kid left on the middle of the living room floor. Now do it 50 times. That''s the first level. I wanted so badly to be able to move, even if it was in big, lu', 'Mostly Positive', 78.86, 0.38, 0.10);
INSERT INTO reviews VALUES (18430, 556640, 212, 'Great slasher VR game, swordplay is well done and collisions are fairly accurate, the concept is great and honestly throw it in endless mode and you can get quite the workout!', 'its fun but 99 percent of the time after i skip or watch the intro, the game just doesnt show on my vr, but it shows on my pc and captures my hand movement', 'Mostly Positive', 77.36, 2.38, 2.58);
INSERT INTO reviews VALUES (18435, 556740, 190, 'I can see The Legend of Dragoon in this game ^_^', 'I wanted this to be good, but so many ways to get lost.. couldnt equip new gear I made.. not very user friendly.. got a refund', 'Mixed', 68.95, 6.27, 2.28);
INSERT INTO reviews VALUES (18439, 556820, 368, 'I think this game is great except for a couple of things that I feel might make other players not even bother. \n\n1. Your units don''t gain honor (xp) in the single player campaign. I don''t really mind playing the multiplayer except that the Arena (which is a second multiplayer mode) doesn''t seem to have anyone playing it and after playing 150 hard-earned coins for access I just sit waiting for a player. This also means that the arena quests are mostly worthless as there doesn''t seem to be anyone ', 'Mobile card game, obscure UI, login every day shenanigans, transactions, also took $$ and went "free".', 'Mixed', 61.41, 65.83, 5.52);
INSERT INTO reviews VALUES (18443, 556860, 157, 'it s a fun game , but it needs achievments.', 'is not like in the photos', 'Mixed', 67.52, 5.47, 4.98);
INSERT INTO reviews VALUES (18457, 557340, 10894, 'This is what games are all about: fun. This game delivers a simple concept well and then some. If you are looking for additional challenges, you can replay the game many times. It holds its value. For me, one walk through was enough but I replayed it three times just to see how my skills have improved and still had fun. Worth your money but I''d get it on sale.', 'Game is promising but waste a big potential, Mechs doesnt evolve or improve and after the 3rd chapter it became a puzzle rather than a bullet time shooter.', 'Overwhelmingly Positive', 95.32, 12.55, 2.68);
INSERT INTO reviews VALUES (18458, 557400, 157, 'Really good idle game. Recommended for everyone!', 'Now you might think that Midas Gold Plus is just another crappy phone game trying to slither its microtransaction garbage onto Steam.  Actually, you would be pretty spot on.  This game contains not one original idea, not even the slightest hint of creativity, offering nothing more than the standard slow grind incremental clicker game with in-app purchases that so many many have done before it.\n\n     I really like the idea of idle/clicker games, and its a shame that they only seem to exist to scr', 'Very Positive', 85.35, 329.73, 21.30);
INSERT INTO reviews VALUES (18459, 557410, 186, 'Dream Quest is the first "true" roguelike/deckbuilder (ie= using cards) that came out, and is closer to a dungeon scroller with cards than later entries in the genre. Conventions were of course, not defined at the time, which makes it interesting to play in retrospect. Also, the card illustrations were made by the child of the creator, which adds to the niche aspect of the game.\n\nPeter Whalen later went on working on the solo modes ("Adventures") of Hearthstone, which touched a much more mainstr', 'I will say this game does get a bit better as you play, but there is so many better options out there. I get that this was the first of its kind, but there is so much wrong that it was hard to even play as much as I have. The art is terrible, but I could look past it if the game wasn''t so unbalanced. It is very easy to get encounters that basically just deem you dead before you even get a chance, like how was I supposed to know the Hydra can be permanently damaged with Earth and Fire cards if yo', 'Very Positive', 86.56, 1.65, 10.25);
INSERT INTO reviews VALUES (18462, 557520, 131, 'I really liked this game. I read some of the other reviews and the main complaints seem to be: too easy, repetitive, and movement is limited. The movement is limited but for most of the game you''re just exploring a single room so you really don''t need to get around very quickly. The puzzles are easy and repetitive but that''s what I liked about this game. I wanted a simple, fun game with a nice environment to basically just chill out with. That''s exactly what I got. If you like games with hard pu', 'I dont know with other controllers but... the touch plus that comes with the quest 3 doesnt work with this game, at least not through virtuald desktop, so you have to emulate the vive or steam controllers to be able to play. Even with that solved, the locomotion and controlls of this game are horrible, i just needed 20 min to get tired of it even though the game seems interesting and the graphics are pretty good.', 'Mixed', 60.31, 9.00, 0.22);
INSERT INTO reviews VALUES (18465, 557600, 4853, 'Beautiful puzzle game. Jacob Geller best explains beauty of this game in his video: https://youtu.be/7mcwCD7KZmY I enjoyed solving puzzles and connecting thoughts.', 'It''s a beautiful game, the style is very creative and nice but the gameplay was a bit dull, and the game is very short. I found it too expensive for what you''re getting.', 'Overwhelmingly Positive', 95.73, 2.78, 1.50);
INSERT INTO reviews VALUES (18466, 557630, 279, 'Every time I think I played everything, I''m so, so absolutely glad to be so wrong.\nI''ll be bundling this review with EP 1 and 2, but obviously not 3!\nHello Charlotte is a confusing, chaotic and honestly an absolute mess of a game, and also one of the most creative, absurd and outright best stories I''ve ever seen.\nHello Charlotte shows a story not made to be easy to understand, it very clearly exists on the basis of an "unreliable narrator", where nothing you see can be truly processed as you see', 'I usually like titles like this where you explore some weird, dreamlike worlds (with or without the sprinkle of horror) and uncover their secrets as you go, but... I dunno, I felt this game wasn''t very approachable? Like the characters'' reactions to things don''t often make much sense, and so it''s hard to relate to them?\n\nI''d played the demo a while ago and already felt like it was dragging on a bit. I can''t really put my finger on it. I want to like this game, but there are a lot of absurd thing', 'Overwhelmingly Positive', 98.92, 17.87, 0.95);
INSERT INTO reviews VALUES (18472, 557750, 109, 'Just wanted to say "A massive thank you" to all the community for helping me get "Giant Citizen" working just \noutstanding !! i downloaded the game and once i had "installed the patch" it was wonderful !! full graphics HOORAY !!.', 'The game is amazing and I think everyone should buy it. But, not from steam. This version never goes into fullscreen mode and opens the command bar every single time you open the game. It is annoying as hell and there is no way to get rid of it.', 'Very Positive', 94.50, 0.10, 0.27);
INSERT INTO reviews VALUES (18490, 558100, 243, 'Really good concept game. Very unique and team based oriented. Would recommend!!\n\nWaiting for this to COME BACK!!!', 'I wish I could give you a review, but the beta ended once the download finished. -.- My thumbs down is NOT saying it''s a bad game, or I wouldn''t reccomend it. I literally didn''t even get to play it yet lol', 'Very Positive', 93.42, 13.08, 2.90);
INSERT INTO reviews VALUES (18491, 558110, 171, 'Very positive. Teaches the player how to use reason to overcome falsehoods and reveal the truth. We need more games like this.', 'This game is more like a reading assignment than a physics puzzle.', 'Mostly Positive', 75.44, 51.40, 23.55);
INSERT INTO reviews VALUES (18492, 558260, 486, 'I really miss arcade rally game like old dirt series, motorstorm, etc. This game can bring back those memories. Damn, really recommend this game. Specially when discount. 10/10', 'The game is just bad. The driving model is not fun, the graphics are blurry and look like one big mess. You have to edit in the configuration files to fix it otherwise even in high resolution impressions like 480p. The drivers in the cutscenes are totally annoying. The soundtrack is absolute crap. No shit, but I''ve never played a more annoying, cheap-looking modern racing game. Its like games added to computer magazines that no one wanted. It''s better to play the old Flatout 2 than waste your ti', 'Mostly Positive', 76.95, 3.78, 0.53);
INSERT INTO reviews VALUES (18495, 558420, 3060, 'Fantastic little game. Probably 2 - 3 hours for a playthrough if you aren''t rushing. \n\nPicked up for a buck and it''s the best dollar I''ve spent in a while.', 'The horror of Command Not Recognized.', 'Very Positive', 86.34, 3.72, 0.82);
INSERT INTO reviews VALUES (18497, 558450, 134, 'Fun game with a cool aesthetic. I didn''t love the platforming, though. And there is a good deal of it. I only mention it to warn others since I don''t see any reviews mentioning it, or even on the game description. Still worth a play, though. But yeah if platforming isn''t your strong suit, I wouldn''t want anyone to be disappointed.', 'The game has some interesting scenes but horror it is Not. It''s a walking simulator and the enemies ... meander at you; the pathing algorithm used for the enemies is terrible or, more likely, they''ll stare at you ... menacingly! They aren''t scary, they''re pitiful. The story also doesn''t help in the horror aspect at all.\n\nThe story (if you were so brave to call it that) is incredibly forgettable, the atmosphere is built off of some cheap Unity assets pack and the sound through barely audible dark', 'Very Positive', 85.07, 16.22, 1.65);
INSERT INTO reviews VALUES (18509, 558990, 2852, 'Grog see game with shiny colored beads and ticky tock wheels. Grog try to string shiny color beads in right shape, but Grog not smart and it make Grog head hurt. Grog solutions take too many cycles and look like Grog ass. Maybe if you smarter than Grog you like this game.', 'You''re given a set of optimization problems, you have to optimize contraptions for space/area, cycles count and obviously cost. Most of the problems can be brute forced as quantities are infinite/unbounded. \n\nThe real game is about how good you''re with optimization but you gotta ask yourself, why spend time on a video game when you could use your optimization skills on industry/corporate jobs? \n\nSatisfying visuals and audio design, freedom of experimentation make this an excellent puzzle game.\n\n', 'Overwhelmingly Positive', 96.98, 21.32, 1.03);
INSERT INTO reviews VALUES (18513, 559100, 1971, 'Getting into this game is just too unclear for me, it TAKES a lot of want to, so many facets that are not clear or understandable.  For example, I still don''t fully understand how training works entirely.  I will continue to try and slog through it for a bit more, but I kind of regret the purchase and will likely abandon - disappointed as I really like the the genre and concept of the game.', 'Worked fine for years, now crashes on open, no mention of this bug in the game news.', 'Mostly Positive', 74.43, 453.57, 152.57);
INSERT INTO reviews VALUES (18518, 559210, 2882, 'you''re telling me you don''t have 8 hours to play this game. close world of warcraft and have fun for once in your life.', 'At first, I thought this was a relaxed adventure game in a fantasy world just like the description. However, every story is a reflection of sadly real-world events.\n\nThe main character, this little boy is a victim of nuclear leak accident. There is a report about radiation problem from National Security Agency in the game.\n\nThe first main quest is a tragic love story between an exchange Korea student and a Japanese girl.\n\nBecause I''m very tired in the real life, so I don''t want to experience any', 'Overwhelmingly Positive', 97.61, 12.18, 9.92);
INSERT INTO reviews VALUES (18520, 559260, 123, 'I played this game originally on mobile after playing Mage Gauntlet by the same company, Rocketcat Games. I fell in love with it then, and it still holds up today. I just finished getting the last achievement for it and wanted to write this review. The difficulty is just right, the story of all 7 Wayward Souls is unique and refreshing, more than enough so to not make it feel tedious when going through the dungeons again. Each character has distinctive playstyles and abilities and have to all be ', 'At first glance, wayward souls is a good looking game.  Solid spritework, fun enemies, interesting characters with different abilities and upgrades for them, and some really cool procedurally generated levels with interesting special rooms which show up from time to time.  Why am I giving this a thumbs down?  Because the difficulty spikes to an impossible level.  Your health can only regenerate from one use healing fountains and the rare healing item available for a few classes.  This is ok, but', 'Mostly Positive', 76.42, 41.07, 9.65);
INSERT INTO reviews VALUES (18523, 559310, 105, 'nice!! ,excellent comunity', 'If anybody had told me that this is basically plays like a p2w Browsergame from 2002, its f2p via the games website and buying it on steam will do nothing but add the purchase value in ingame premium currencey to your gameaccount, i would have taken my money and ran.', 'Mixed', 63.81, 1906.68, 22.43);
INSERT INTO reviews VALUES (18524, 559330, 703, 'When I say the phrase "VR games used to be fun," this is what pops into my head. It works so well in VR, it gives you this unique sense of wonder and awe without being laggy and overly ambitious. Pretty short, I took an hour to beat it but honestly it could''ve probably been done in half that. But damn is it nice to sit in that tiny slice of VR history where games were this dedicated and creative. It''s a pretty standard point and click adventure with a recurring ability to shrink objects or enlar', 'Do you developers plan to keep ignoring Korean buyers?\nYour official description states that the game supports Korean, but when I launch the game, there are no Korean subtitles or audio.\nWe, Korean buyers, have been asking for feedback and improvements since the early days of the game, but your consistent disregard for us is deeply disappointing. I was hopeful when I saw that you finally released an update after such a long time, but upon logging in, I see that Korean subtitles and audio support', 'Very Positive', 92.32, 1.07, 0.17);
INSERT INTO reviews VALUES (18528, 559610, 699, 'wow i dont have word to say, it;s just so beautiful the story and music, i wish it was more longerr i really love this game very much', 'Art is mid, story didn''t pull me in. Apparently its about teenage lesbian incest? If you wan''t a good lesbian VN I''d recommend Highway Blossoms instead. Much better writing.', 'Very Positive', 91.13, 9.87, 0.27);
INSERT INTO reviews VALUES (18529, 559620, 374, 'WHERE ARE YOU MARSHALL?!', 'So I really need to mention something. I am going to put a not recommended for this game right now. I feel that this game really needs a remaster BADLY! I haven''t played it for very long and I liked what I played so far, but the game keeps crashing and messing up constantly. I understand that this is a game from the late 90s, but I tried everything under the sun, so far anyway, to prevent it from not crashing on me. When I save, it crashes or changes to a tiny window mode. I try to set it at a 4', 'Very Positive', 92.78, 0.88, 1.13);
INSERT INTO reviews VALUES (18532, 559650, 3275, 'Fun prop hunt game.\nNot many players.\nBuy at a discount !', 'I''m too old for this (26 years).\n\nToo many items and very large maps. It''s difficult for me. Very hard to find someone who is hiding. The game might be fun for someone, but it''s clearly not for an old guy like me.', 'Very Positive', 92.76, 4.87, 0.30);
INSERT INTO reviews VALUES (18533, 559680, 499, 'One of the greatest RPGs of its time. Little known fact : this game was what spawned the engine for Warcraft III, WoW, SC2 etc.\n\nIt''s old so be ready for some frustrations when it comes to character control, it''s a clicky with screen edge camera movement thing not a wasd with skills thing.\n\nStory is great, characters are fleshed out and the variety of builds is nice. Very DnD like but with a vampire twist.\n\nOldie but goodie.', 'I loved this game back when it first came out - great story I was really looking forward to playing once more. The brightness makes this game unplayable. Cant see a thing right out of the gate. Very unfortunate. I don''t know how to find and install mods so I rolled the dice and lost on this one.', 'Very Positive', 85.97, 38.95, 0.33);
INSERT INTO reviews VALUES (18537, 559910, 227, 'If the devs spent 5% of their time in balancing, this game would be 10/10.\nBut it''s only 5/7.\n', 'Extremely niche response here, but as a winemaker the whole process here is garbage. I know you don''t play all games for its realism, but this is so far from that for me that it''s unplayable and illogical. Sorry, but no good', 'Mostly Positive', 70.48, 20.48, 8.42);
INSERT INTO reviews VALUES (18543, 560000, 177, '3+ hours of a butch lesbian in progressively gaudier and gaudier three piece suits', 'Utterly confused. The game dev didn''t bother giving character names but instead let us decide a nickname. And the game starts with a full box of swear words making it even more confusing.', 'Very Positive', 91.53, 9.88, 19.43);
INSERT INTO reviews VALUES (18546, 560130, 7835, 'The best written story I have seen in any game. \nYou have to make choices, and there is no clear good option. By helping someone and trying to do what is right, you will always hurt someone else.', 'I just can''t do it, I cannot get into this game. The real time battles are not for me and so I try to turn based and it is just awful. You can NEVER have more than one attack per turn, no perks or anything to unlock this. The game is such a slog with this feature and trying to manage all the characters in real time is worse. This only leaves the option of letting the AI use your companions and at that point, I am out, if I cannot control my characters then why bother?', 'Very Positive', 87.85, 109.67, 12.32);
INSERT INTO reviews VALUES (18547, 560170, 508, 'When the expanded universe ruled the earth.', 'It''s not horrible, but if you are playing it with a mouse and keyboard, your mouse AND your keyboard can move Dash forwards and backwards. Pair this with the fact that you can''t actually aim (but if you are in any way used to shooters, you''ll be trying to because Dash is also incapable of aiming up most of the time), and you''ll be falling off ledges, jumping out of cover, or going two steps forward but one step backwards during a boss fight.', 'Mostly Positive', 72.24, 3.20, 1.23);
INSERT INTO reviews VALUES (18552, 560260, 290, 'A well balanced 2 D Jump N Run only a few levels need a little bit mid skilled but even that dont get to hard, there are 2 bosses and 4 boss fights, but even they are still fair (i find a few levels befor boss fight 3,4 trickier. Since its free everyone who likes Jump N Run should test it. Hope you enjoy like me the 21 levels. Thx 4 reading.', 'What can you expect from a free game? Not much... I never like leaving negitive reviews, because I know someone worked hard on said project, but in this case, I feel like they should''ve worked harder. Some of the levals are a breeze, others are a real b*tch. I assume that since this is a free game, and there are only 21 levels, that this is just a passion project created by a team of no more than 3 or 4 people. And so, I assume that they were the ones to test the game. And since they created it,', 'Very Positive', 85.86, 0.58, 0.33);
INSERT INTO reviews VALUES (18556, 560370, 209, 'install the last resort mod and dgvoodoo2 to experience the greatest cqb sim ever created', 'doesn''t work properly. \r\nThe GOG version is better.', 'Mixed', 67.94, 0.17, 5.07);
INSERT INTO reviews VALUES (18557, 560430, 559, 'My PC is terrified of INDIANA JONES AND THE GREAT CIRCLE system requirements so I''m playing INDIANA JONES AND THE EMPEROR''S TOMB for the 100th time instead.', 'This game is annoying the hell out of me.\nMy ex wife was easier to control than this stupid game!\n\nYou can not save the game anywhere, so I am stuck on level 1 because I cant get the idiot to hug a wall to get any further. You have to constantly press the walk key because of the ridiculous speed Indy moves at. \nI give up!!! Infernal machine was 1000x times better!', 'Very Positive', 92.49, 124.37, 3.72);
INSERT INTO reviews VALUES (18563, 560710, 545, 'From a testing standpoint, this game does exactly what it sets out to do—and does it well. It''s lightweight, smooth, and responsive, which is crucial for any game that hinges on timing and reflexes. What impressed me most is its replayability. The variation in weather and the randomized rune effects prevent the core loop from becoming stale. It doesn''t try to be more than it is, and it nails that minimalist arcade niche. And economically? A dream. I made more selling the cards than I paid for th', 'There’s not a ton of content. It’s just jumping and dodging spears over and over. But honestly, for the price (especially during sales), and with the card drops? You get your money back and a bonus badge. So I can’t really hate it.‍', 'Very Positive', 92.48, 4.42, 4.25);
INSERT INTO reviews VALUES (18594, 561600, 427, 'It''s a good time. It runs smoothly and still looks really good in my opinion. Just a solid, fun Motocross experience and the best game in Milestone''s MXGP series.', 'I hate that you cannot change language ingame! It will default to your OS language.\nWho thought this was a good idea???\n\nGame is fun and all but that issue alone is enough to make me reconsider my purchase.', 'Very Positive', 85.95, 19.65, 4.97);
INSERT INTO reviews VALUES (18595, 561610, 197, 'One of the Best Motorcycle Games = MotoGP™17', 'Team Copy&Paste strike again..\n\nBug city.. no shame.', 'Mostly Positive', 79.70, 19.32, 54.48);
INSERT INTO reviews VALUES (18598, 561740, 182, 'Why is this so good?\n\nI''m super confused, nothing is explained well, but the game is actually pretty good', 'what a disappointment, I wish they invested more into this game besides cheesy mechanics.  I wish the story was longer and and provided more.  Feels like a quick cash grab with these type of similar feeling games being frequent enough in 2024.', 'Very Positive', 84.62, 12.65, 19.52);
INSERT INTO reviews VALUES (18599, 561770, 160, 'Hard for me to say on this, I would say a lot of good ideas but executed kinda clumsily. All in all I enjoyed it though, and the remake thats included helps with the problems of the plot.', 'Al principio me gustó mucho, pero después llegué a un punto donde ya no soporté seguir jugándolo. \nSentí muchos clichés pero de esas veces en las que no es chido descubrirlos, si no tedioso.', 'Mixed', 69.38, 3.53, 3.72);
INSERT INTO reviews VALUES (18607, 562220, 1241, 'If you''re a fan of puzzles and achievements, you''ve come to the right place !\n\n*** All ZUP Games have cool Puzzles + Trading Cards + a lot of working achievments ***\n\n+ Successes are letters in different colors that you can ideally use for profile design\n\n--> If you have the option, buy them all in a bundle to save money. You won''t regret it', 'I''ll be brief like my 20min playthrough. Interesting concept, but the puzzles are bland & repetitive. Zup! 2 failed to hold my interest for long as I rapidly click through another level every few seconds hoping for more interesting challenges, only to find you have already completed the game!\n\nEven taking into consideration the low price, Zup! still doesn''t offer great value in the length, challenge or replayability department. Perhaps the most you may get from this game is an easy perfect game ', 'Very Positive', 92.75, 5.23, 2.08);
INSERT INTO reviews VALUES (18608, 562230, 481, 'Honestly it''s a wonderful game; the visuals are great, the premise is simple to understand you''re a villain doing villainy things! The mechanics are simple to understand for that it''s wonderful. However despite all the good I do have my fair share of complaints. Before getting into that the game doesn''t really suffer from any performance issues and I haven''t encountered any bugs or issues with regards to gameplay so that''s always wonderful. So if you''re looking for a smooth experience and a turn', 'Overall the game delivers exactly what it promises.  It''s real good.  Pretty.  Great loop.  However when you begin playing you only have a single commander.  If this commander is injured before you unlock a second one, you are forced to play crippled for the rest of the game.  At this point you are better off restarting the entire campaign.  I found this so discouraging that I can''t give the game a positive review because I value my time.\r\n\r\nI''ve posted about this in the discussion boards.  The ', 'Very Positive', 84.41, 3.33, 9.40);
INSERT INTO reviews VALUES (18611, 562260, 679, 'Step 1: Open game\nStep 2: Wait 2 hours\nStep 3: Close and uninstall game\nStep 4: Buy and equip black background', 'Thanks for the wallpaper and broken achievements', 'Very Positive', 87.78, 2.00, 10.05);
INSERT INTO reviews VALUES (18619, 562350, 237, 'quantity of endings does not mean quality... but i lube all the ladies equally.\n\nthis is definitely a fun one to try out, especially if you enjoy more than 21 endings, although i find the bad endings rather many & disappointing, i enjoyed all the good endings as well as the artsyle has its perks...\n\npersonally, i am acustomed to a more raw and refined artstylem but the story is a keeper. and it inspired me to create my own mansion drama (i won''t be releasing my story though... i like it like tha', 'Boring Anime trash. There is nothing interesting about it but to torture the reader to some backwards way of thinking. I fell asleep reading this garbage, looking at the same boring style Anime faces of bug eyed children. This foreign made trash is proof all those Asian countries suck. I hate you developers and artists of this kind of cheap boring garbage peddled into this country for a quick buck. BAD GAME!', 'Very Positive', 80.59, 33.30, 7.15);
INSERT INTO reviews VALUES (18620, 562360, 554, 'This game has already ruined my life, so I''ll just eat a spoonful of cinnamon for every like this review gets\n', '\nBad game.\n', 'Very Positive', 85.38, 4.13, 5.80);
INSERT INTO reviews VALUES (18621, 562410, 253, 'fighting panties i want to SNIFF THEM ALL!', 'nope', 'Very Positive', 92.89, 32.38, 0.42);
INSERT INTO reviews VALUES (18629, 562500, 943, 'The game impressed me with its variety of strategies and towers. By combining them, you create unique tactics. The vibrant graphics and upgrade system make the game engaging!', 'Game doesn''t work. Launched the program and it gets stuck at "Connecting to servers" on both Windows and Linux.', 'Very Positive', 87.38, 27.43, 0.37);
INSERT INTO reviews VALUES (18635, 562570, 138, 'Thought this would be quick and easy, maybe an hour or so of play time... Wrong. A small handful of puzzles were either so simple and I was over thinking them, or they seemed to make absolutely no sense, even with hints, or the straight up answer, from the community.\nOver all, probs a 6 or 7/10', 'bad puzzles. sets up for cool things but then doesn''t follow it''s own logic and is intentionally misleading. controls are wacky on some levels. good ui + sound design though', 'Mostly Positive', 76.09, 2.90, 1.05);
INSERT INTO reviews VALUES (18636, 562590, 276, 'The game has some balancing issues, but i believe it can be better than Robocraft, cause it has no random generate loot and it has FAR more rewarding match system', 'Its Meh\n\nIll start by saying its not a bad game for being in the early stages. A bit of fine tuning and it will be a great game.\n\nMy issues are, its really unbalanced, no moderation in the chat and the matches arent long enough. \n\nShip building takes me back to Kingdom Hearts in a good way. Keep working and Iron out the bugs and it will be good. But at the moment, I cant recommend.', 'Mixed', 67.39, 3.28, 1.28);
INSERT INTO reviews VALUES (18646, 562860, 4214, 'I cant believe this was made in the build engine, the best game made in this engine since BLOOD. My one complaint is not really a complaint. It has sooo many secrets you would never find without a guide, and i feel like i miss so much.', 'Doesn''t matter how good the game is if the developers are chuds who think that removing an unnecessary joke at the expense of gay people counts as "censorship". The revelation of transphobia and homophobia in the developer''s discord is also extremely disappointing. There are a lot of good shooters out there and you can afford to miss this one.', 'Very Positive', 93.83, 5.18, 1.63);
INSERT INTO reviews VALUES (18653, 563190, 131, 'This game is the cure for depression. Straight serotonin into your brain.\r\n\r\nJust make sure you fix some of the sound issues. You''ll find the files on r/deblob.', 'The second part has the same technical problems as I reviewed for part 1 (https://store.steampowered.com/app/532320/de_Blob/): graphics are washed out, no widescreen support, low resolution. The game plays basically the same way as in the first part, except that there are some more abilities like smashing boxes, touching vehicles to start them drive away, paint the people of the towns, etc. The games could be very funny, but look too old on the graphics side. Too bad, you can''t setup anything on', 'Very Positive', 90.08, 33.42, 1.02);
INSERT INTO reviews VALUES (18654, 563200, 151, 'Slay is a very simple game that can have many challenging parts depending on your play style and the moves you make.\n\nI would highly recommend it to any and all players who enjoy relaxing while playing or trying to get the hang of things!', 'I remember enjoying this game on a PocketPC device when it originally came out but for the PC version, it seems that most of the levels are close to impossible to beat at the highest level simply because you start with nothing.  By the end of the first turn you are cooked.  I''m sure with enough patience you may be able to work out a sequence that will allow you to win but that just isn''t fun.', 'Very Positive', 89.40, 201.82, 164.65);
INSERT INTO reviews VALUES (18661, 563360, 138, 'game has got potential, some of the controls are a bit weird but you get used to it eventually i guess. i kinda miss having a loan option though, because i want to expand some stuff and my money is going up really slowly so i''m just waiting for time to pass to get money to do the changes i want. other than those things the game could be really enjoyable.', 'Sorry, I realize this is early access and will have some bugs. But there are quite a few, and some are very basic, as in objects that won''t rotate when you place them, and workers who get stuck in locations. And right now, only sandbox mode works. I don''t know if the developers are investing in this game anymore.  If they upgrade and improve the game, or even just fix some of the bugginess, I''ll update this review.', 'Mixed', 55.80, 2.78, 3.95);
INSERT INTO reviews VALUES (18682, 563750, 120, 'Love this game BUT it sorely needs an update or new version where some AI can automate a lot of the sparring, training, and fighting. You must micro manage the day to day of every single aspect of everything in this game.', 'Great concept, poorly executed, this game couldve been amazing, unfortunatly it isnt detailed enough in regards to finances, matchmaking and boxing language i.e (the use of rear hook instead of left hook or right hook) using real existing boxers and organisations could''ve taken this game to the next level i understand there may be branding/copyright issues but it would have made a massive improvement, the main gripe i have about this game is the amount of time you have to lose skipping each day ', 'Mixed', 61.67, 54.52, 2.37);
INSERT INTO reviews VALUES (18689, 564050, 362, 'Slaps and Beans 1 is a love letter to classic Bud & Terence films—punchy, funny, and a bit wobbly. It’s like watching them brawl through a video game: messy, but you can’t help but laugh the whole time. 🍿👊🎮\n\nFollow my curator page for more punches, laughs, and chaotic brawls straight out of a Bud & Terence classic:\nhttps://store.steampowered.com/curator/42602807-Osiris-Reviews/', 'The stupidest punch animations I''ve ever seen, they don''t even come close to being punches.', 'Very Positive', 86.19, 6.33, 0.08);
INSERT INTO reviews VALUES (18694, 564150, 211, 'It''s a fun little game, feels like a Mega Man rom hack, in a good way.\n\nMy only gripe is the password system, you wanna dust off your graph paper and pencil like the old days', 'I usually don''t care if a game is a shameless copy of a different game as long as it''s good, but this one went beyond just being a legally distinct Mega Man fangame, it copy pasted many screens, enemies and bosses. It''s not just a reference or homage, most stages are literally a collage of screens from different mega man games, there''s barely anything original here. If you''re a MM veteran the game feels like a Deja Vu marathon, i didn''t enjoy that one bit. What''s the point of playing this game i', 'Mostly Positive', 72.99, 4.67, 8.07);
INSERT INTO reviews VALUES (18697, 564230, 2357, 'Incredibly well done character creator that goes as far as letting you control the ai, not to mention the unlimited customization with mods. In my 400 hours I have literally never actually played as a wrestler, I just make characters and watch them fight. It''s that in depth and fun. I can''t imagine the amount you can get out of it if you add in player input as well. Cannot recomend it enough if it''s even remotely interesting to you.', 'even though it says i have played this game for 39 hours i haven''t it will not even load. don''t waste your money like i did they will not refund it.', 'Very Positive', 91.47, 410.20, 40.92);
INSERT INTO reviews VALUES (18699, 564310, 1587, 'Great shooter but we couldn''t play the mods together.', 'OMG This game sucks ass. Play Doom instead', 'Very Positive', 92.19, 0.52, 13.27);
INSERT INTO reviews VALUES (18706, 564530, 1492, 'A "timeless" classic? A childhood game, with an epic soundtrack...', 'After playing a few hours, the game will only load to a black screen with the music playing in the background. Very sad because I loved this game when I was younger. This does not work on my computer and nothing seems to fix it', 'Very Positive', 91.82, 0.12, 15.40);
INSERT INTO reviews VALUES (18708, 564710, 465, '....Why am I addicted to this game? I shouldn''t be addicted to clicker games.... Why do I keep denying this is a clicker game? Yes, it has other aspects that require more thought in some actions that are much different than other clicker games, but.... it IS essentially a clicker game after a while. Still, why is this one so addicting?!\n\n\n....It''s good. It''s free. Try it.', 'played 1 hour - its just boring', 'Very Positive', 93.55, 1205.18, 1.00);
INSERT INTO reviews VALUES (18722, 565120, 655, 'It''s a fun, tense story game. There are not many puzzles—it''s mostly a walking sim. The story and ending were fine.', ' It''s too short sup 2 hours. The puzzles are OK nothing grand. The voice actions a plus but the biggest issue is well the story is tripe. The game about you going to the station which was sent to an alien race''s planet to watch them. The game sends a lot of misdirection on who''s the alien with directly contradicting information only to gasp  go the predictable path for social commentary at the end. There three sub stories really two about the crew but nothing that keeps you moving.', 'Very Positive', 85.50, 13.68, 2.93);
INSERT INTO reviews VALUES (18724, 565170, 178, 'This game so ass man', 'This is as good of a time as any to remind everyone to separate the artist from the people who pay the artist; as while some of my all time favorite games may have the Nicalis logo on them, they didn''t make them. they simply published them. And nowhere is it abundantly more clear that Nicalis has no idea what makes any of their intellectual properties actually good than in Blade Strangers. This game should''ve been the easiest win ever; a 2D fighting game starring Nicalis''s greatest heroes (plus ', 'Mostly Positive', 79.21, 1.10, 3.17);
INSERT INTO reviews VALUES (18733, 565550, 119, 'I loved that game as a kid! Crazy memories!', 'One of those games that is remembered and fuelled purely by nostalgia. It''s actually complete trash and somehow became a cult classic.', 'Mostly Positive', 73.11, 2.55, 1.55);
INSERT INTO reviews VALUES (18741, 565720, 100, 'It''s good, but Miss World ''96 is still better', 'It''s just a soulless Gals-Panic-like game with clunky controls and poor voice acting. There are a few themes which are ok and girls desing despite cliché, they are ok enough well designed. I don''t recommend to waste your money on this though.', 'Very Positive', 85.00, 4.98, 1.70);
INSERT INTO reviews VALUES (18744, 565860, 270, 'This is the most ENCHANTING game I''ve EVER played in my entire life. The characters are all so vibrant and full of personality and they compliment the story line PERFECTLY!!!! I immediately recommend you get this game if you''re looking for a great time.', 'STUPID STUPID GAME STUPID GAME STUPID STUPID DON''T PLAY THIS STUPID GAME STYUPID GAME STUPID TOMATO I HATE TOMATOES I''M GONNA RAPE ALL TOMATOES FUCK YOU', 'Very Positive', 81.85, 0.52, 0.20);
INSERT INTO reviews VALUES (18747, 566050, 1021, 'Still one of the best city builder games ever made. Wish they would remaster this', 'The Screen froze and admin does not reply to request for assistance', 'Overwhelmingly Positive', 97.16, 133.20, 70.68);
INSERT INTO reviews VALUES (18748, 566090, 459, 'I played the original bards tale on a apple IIE and it was great. This bring me the nostalgia and in a modern platform story telling way. The turn based combat with the two sides having grids for positioning your party has a nice strategy to it. The abilities have been interesting with limited opportunity for your party each turn and the abilities having specific benefits based on the actions or positioning of the enemies. Great game so far that has not gotten repetitive after a few hours of pla', 'Nah.', 'Mixed', 67.76, 10.68, 4.07);
INSERT INTO reviews VALUES (18751, 566160, 662, 'If you''re a fan of puzzles and achievements, you''ve come to the right place !\n\n*** All ZUP Games have cool Puzzles + Trading Cards + a lot of working achievments ***\n\n+ Successes are letters in different colors that you can ideally use for profile design\n\n--> If you have the option, buy them all in a bundle to save money. You won''t regret it', 'Compared to other ZUP! games and the way they play, this one is terrible ( especially that lighting fast micromanaging that requires - if youve played the other games you know what i mean )', 'Very Positive', 92.75, 3.95, 6.15);
INSERT INTO reviews VALUES (18754, 566190, 165, 'Searching for art supplies...', 'Crashes, bugs and no auto-save.\r\nI didn''t like the game at all', 'Mixed', 69.09, 1.90, 9.18);
INSERT INTO reviews VALUES (18764, 566440, 1976, 'No idea what all the crying is about... this is a decent game - it''s fun, fairly unique, and in 25 hours I''ve not yet come across a single one of these supposed ubiquitous and game breaking bugs... \r\n\r\nGameplay loop is pretty simple, you make a gang, you level them though Thug Life related activities, you make them pretty, you do harder shit, etc. I mean okay, it''s not Elden Ring or Mass Effect but it''s a perfectly playable and enjoyable game with a pretty unique setting and innovative ideas. I ', 'Literally could have just made a Necromunda themed X-Com clone, but they made this instead. AI is broken, gets lost easily/walks into walls. Controls feel janky. Matches take HOURS, and most of the time is spent wrestling with the controls. It''s really not great. Tell me if I''m missing something.', 'Mixed', 55.57, 52.12, 5.25);
INSERT INTO reviews VALUES (18766, 566530, 247, 'Excellent concept, with gameplay that was incredibly fun to play with friends.  However, after a few matches there are some obvious imbalance issues that ruin the game onward, in favor of the seeker.  Our seekers quickly adapted to just picking up and dropping as many androids as possible near the control panels, making it nearly impossible to approach them.  Could definitely use some balancing tweaks, but I''m really looking forward to playing more in the future.', 'Doesn''t work on Quest 3. Extremely buggy', 'Mostly Positive', 71.66, 2.28, 1.02);
INSERT INTO reviews VALUES (18767, 566540, 491, 'Bloodier and hornier Etrian Odyssey. Relative to those:\n+ Strong emphasis on story from the get-go.\n+ Team construction is an interesting, well-developed system in its own right.\n- Non-boss fights offer uninteresting turn-to-turn gameplay.\n- Several mechanics are opaque or obscure.\n- Some translation issues.', 'This feels like a side game that was supposed to let you find out the story of a mysterious side character. It''s not, but that''s the only positive thing I can suggest for the story since the normal ending makes you wonder if that''s it and the true ending makes you wonder why you wasted your time. The game is real simple, you can (are supposed to) mash attack through most fights. The harder ones aren''t that much more complicated, just use whatever magic is good against the opponent and have your ', 'Very Positive', 80.24, 224.10, 76.22);
INSERT INTO reviews VALUES (18781, 566860, 1138, 'This is an honest gem of a game. Not many out there in VR that have aged well, this one is perfectly simple... and uniquely in depth. Working with the armor sets is enjoyable. Combat is straight forward and easy to grasp and the weapons are easy to figure out, with ample places to practice with them. If you understand RPGs you will understand this game. Depending on the setup you use.... you can even get a bit of cardio in. I hope to see more some day... sad this didn''t take off.... its worthy.', 'Typical.... Just another waste of money. I am sick and tired of buying indie games that keep getting abandoned. This is the last straw, no more buying indie or early access games anymore. Enough is enough.', 'Mostly Positive', 75.31, 9.33, 1.23);
INSERT INTO reviews VALUES (18791, 567030, 335, 'Under Leaves is a beautiful, yet challenging, hidden object game that features various animals in their natural habitat. It''s very peaceful, but some levels can really test the player''s patience as far as difficulty goes. I realized that I really struggled with the yellow scenes, in particular, so it was interesting to see how a simple change of color could affect the difficulty so much. I did enjoy my overall experience, but I would''ve loved a way to adjust/mute the volume (the audio was just t', 'Wonderful art. Beautiful sound design. Nice feeling of different environments throughout the world. Hidden Object gameplay that is often made hard by hue shifting the things to find so that they closely match the background. Hint system that requires a sliding block puzzle that feels tacked on, and is either way too easy or needlessly time consuming.\n\nIf you love hidden object games and don''t mind difficulty that feels forced, this is a great game. Otherwise, just watch the trailer. You''re not g', 'Overwhelmingly Positive', 97.01, 3.73, 1.48);
INSERT INTO reviews VALUES (18793, 567060, 121, 'Good game but beware the boss fights they are hard as balls.', 'I tried to give this game a shot after a game ruining bug caused me not to be able to finish Putrefaction 1, this was a mistake. Putrefaction 2 is a few steps forward in a few ways but steps back and in the same slog at the same time. The game is just pretty boring, the gunplay isn''t satisfying. There''s no manual saves option, the difficulty spikes are INSANE even on normal difficulty, and just like the first game the boss fights are unbalanced, sometimes glitchy piles of poop juice. The art sty', 'Very Positive', 82.64, 4.65, 7.18);
INSERT INTO reviews VALUES (18794, 567080, 210, 'A really incredible game for a solo dev to accomplish\n\nthe UI is not intuitive, and a lot feels under/un-explained, but if you''re willing to push through that, its a real gem', 'Dead game. No longer developed.', 'Very Positive', 83.81, 12.25, 1.20);
INSERT INTO reviews VALUES (18795, 567130, 136, 'Quite nicely done actually. But it gets boring very quickly in my opinion.', 'Can be launched on meta oculus quest 2.\n\nIn VR I could move, but couldn''t see subtitles and couldn''t trigger anything, so couldn''t get past just walking around the room. In usual desktop mode I took a flashlight and couldn''t trigger anything else before I fell through the floor, and kept endlessly falling quickly so when I tried to open the menu it was flying away immediately.', 'Very Positive', 80.15, 2.17, 1.73);
INSERT INTO reviews VALUES (18802, 567280, 260, 'its retro but its good.', 'WHAT THE HELL THIS GAME IS 25 DOLLARS?? It''s worth about 25 dollars less than that I hope you know. Don''t buy unless your getting that big package deal with all of the games for 10 dollars. It''s not worth it.', 'Very Positive', 81.15, 5939.92, 1.10);
INSERT INTO reviews VALUES (18803, 567290, 274, 'This game is a good thing to develop blind writing and memorize location of buttons, also cool achievments.\nEducational game.', 'Bought this years ago for achievements to decorate steam account for a dollar. Zup is a better game now for achievement collecting.', 'Very Positive', 86.50, 1.60, 2.27);
INSERT INTO reviews VALUES (18807, 567380, 1748, 'This is a good game. Its not finished, its in early access. The dev does not deserve the ongoing reviewbombing.', 'Honestly, I cannot recommend this game right now. I had originally bought this to support the dev as I had followed his streams, and he was working on it fairly consistently, or so it seemed. The only dev update this year for this game was a meme post for April fools. This at the time may have been funny, but now seems pretty out of touch since it was the only 2024 update.\n\nNow, he barely works on it, if at all and appears to have changed professions somewhere along the line to a full time strea', 'Very Positive', 81.81, 2.30, 4.13);
INSERT INTO reviews VALUES (18810, 567580, 128, 'Very good game, better than classic demonstar. Hoping for another levels.', 'Recycled, overpriced, monotonous game with basic gameplay and inflated difficulty', 'Mixed', 68.75, 3.17, 2.10);
INSERT INTO reviews VALUES (18815, 567670, 302, 'One of my favourite VR games', 'It doesn''t tell you where to go and everything looks the same so it''s so confusing that I can''t be bothered', 'Very Positive', 88.08, 16.72, 0.57);
INSERT INTO reviews VALUES (18819, 567750, 164, 'Fun little tycoon game. If you get it cheap, then it''s worth it for a day of fun.', 'The gameplay is decent. One issue I have is that the scaling/growth for streaming is very unrealistic and it feels like the follower count grows way faster than it should. Also had a bug where the very last esports research removed my class skill progress, and I didn''t want to have to rebuild it from scratch so I stopped playing.', 'Mostly Positive', 75.61, 14.77, 4.35);
INSERT INTO reviews VALUES (18825, 567980, 107, 'hell yeah 353 days until christmas', 'Don''t buy this.\n\nConcept is cool, controls are ass. \n\nConsistent problems with just playing the game.', 'Mostly Positive', 79.44, 1.60, 0.15);
INSERT INTO reviews VALUES (18828, 568040, 363, 'I love macbat. The game is great the music is great. This game deserves a sequel. Good job, Siactro. Good job.', 'Much, much, much, much less than what you''d think. The store details oversell it and then you have an army of room temperature IQ individuals in the reviews pretending this is "just like N64 OMG!". \nWell you''d think if the point was to be "like N64", then the game would have the capacity to outdo famous trash games of that era like Bubsy 3D or Quest 64? Not even remotely, because this game is nothing.\nDon''t know if this was done in Unity or Game Maker or what, but it doesn''t matter. The point is', 'Very Positive', 91.18, 203.43, 0.82);
INSERT INTO reviews VALUES (18831, 568090, 3189, 'I remember back in 2016 when I used to watch all of these youtubers play this game. Brings back good memories of the fan games too. I used to want to play this game all the time as a kid but never had a PC. Now that I own one years later I played it. I can ensure it was worth the wait and actually experiencing this horror-ish feeling was enjoyable. I forgot every single bit of it so it made it puzzling which I enjoyed instead of knowing what to do. This game is a good horror game and the fact it', 'my penis hurts. i railed the fat mother furby too hard', 'Very Positive', 94.89, 1.58, 43.30);
INSERT INTO reviews VALUES (18836, 568220, 9965, 'Do not forget the train. Do not forget the train. Do not forget the train. Do not forget the train. Do not forget the train. Do not forget the train. Do not forget the train. Do not forget the train. Do not forget the train. Do not forget the train. Do not forget the train. Do not forget the train. Do not forget the train. Do not forget the train. Do not forget the train. Do not forget the train.', 'The game is fun and all that, but this is probably one of the worst gaming experiences of all time, if you wanna go through hell, then go ahead nobody is stopping you. This game might seem like a pushover at first, but it will SUCK later on. All in all, if you want to play it, please do, this game will teach you a whole lot of discipline, self control, and patience, and the story is really good. ALSO SCREW THE TTTRAAAAIIIIN.', 'Very Positive', 92.62, 95.08, 74.82);
INSERT INTO reviews VALUES (18840, 568320, 945, 'Good Picross/Nonogram game. Comes with workshop support, create yourself and played other user created puzzles.\r\nIf you like these logic puzzles, this is a good choice to pickup and have lots of hours of fun.', 'HOW THE FUCK DO YOU EVEN PLAY THIS DAMN GAME', 'Overwhelmingly Positive', 97.25, 86.20, 4.08);
INSERT INTO reviews VALUES (18849, 568570, 1446, 'Force of Nature\n\nHas a total of 6 trading cards.\n', 'I have a hard time understanding all the positive reviews of this game. The core mechanics in the game are dull and quickly become boring. The grind is tedious, and you are forced to kill millions of goblins with RNG to drop the gold you need to level up and progress in the game. The micromanaging in the game is tedious, and you always feel short on the resources you need. The combat is clunky, and all hostile animals and goblins work together to kill you, and you can''t outrun any of them.', 'Mixed', 67.70, 2.37, 12.62);
INSERT INTO reviews VALUES (18858, 568750, 166, 'My favorite genre: poorly translated', '甜点恋人 / Pastry Lovers is not a game, it''s a Choose-Your-Own-Adventure e-book that''s been dumped on Steam masquerading as a game.  As a visual/interactive novel, this doesn''t feature any notable gameplay, it''s just a lot of clicking through badly written dialogue that would never have been accepted or published in print, which poses the question, "How did something this badly written end up on Steam?".\n\nTo answer that question: When someone hoping to become an author is unable to get published in ', 'Mostly Positive', 75.90, 7.72, 6.57);
INSERT INTO reviews VALUES (18885, 569480, 18475, 'A low-stress city builder with surprisingly decent vibes. Build your kingdom, fend off some vikings, admire the seasons. It’s like Banished but less emotionally damaging. The perfect game for when you want a touch of strategy without sweating over spreadsheets.', 'you know what sucks? This game has genuine potential. The issue is, the devs have more or less abandoned this game. All the features they promised are going to their new game, Nova roma. If this looks good, I''d recommend getting that when it releases. It doesn''t really feel like a finished game. I love it, but damn man, early access for virtually 3 years. Unfortunate', 'Very Positive', 93.70, 27.12, 77.72);
INSERT INTO reviews VALUES (18889, 569530, 292, 'BEST GAME! BRING IT BACK! 2025 IS THE YEAR OF SKYNOOOOOOON! \np.s I BOUGHT 25 COPIES OF THIS FOR PEOPLE TO PLAY WITH ME PLEASE DONT KILL SERVERS ALEX CHRIS CRAIG AND NATHAN! I LOVE YOU! XOXO', 'would not recomend', 'Very Positive', 83.90, 28.17, 7.02);
INSERT INTO reviews VALUES (18892, 569610, 145, '2000s mobile game. But sometimes it''s good', 'For the price I paid (60c ? Not sure) this is OK. But the boss has too many HP, the game is too repetitive and worst of all not engaging at all.\nSorry, but for lower price (or free) I can play more engaging games and have more than 20 seconds of fun. At least I hope the creator recouped the 100$ entry fee.', 'Mostly Positive', 75.86, 18.30, 0.20);
INSERT INTO reviews VALUES (18897, 569800, 256, 'The tree has lost all its leaves. Let''s help find the leaves while traveling through a surreal world full of aesthetic delights. \n🍃\n', 'Leaves: The Journey is a puzzle game where you have to explore and solve puzzles to find all missing leaves from a tree. The game has no words and no story to speak of, you just have puzzles and atmosphere. The art style is very surreal and reminded me of the Samorost games.\n\nThe puzzles range from easy to totally obtuse. Most of the puzzles weren''t too tricky, although there were a few I really had to think about and a couple that I had to get hints for. There were a lot of puzzles that were ba', 'Very Positive', 80.86, 4.62, 7.15);
INSERT INTO reviews VALUES (18898, 569810, 137, 'The tree has lost all its leaves. Let''s help find the leaves while traveling through a surreal world full of aesthetic delights. \n🍃🍃', 'There is a game breaking bug in this game at the Hanoi puzzle that the developer has never addressed, in spite of repeated requests. For this reason alone i will not recommend unfortunately', 'Very Positive', 88.32, 4.20, 14.98);
INSERT INTO reviews VALUES (18899, 569860, 2079, '8/10\n\nThis is, overall, a great Point and Click game!  If you are an oldschool player and don''t like things too easy, definitely avoid Casual Mode, as it is super simplistic and removes the bulk of the puzzles.  In addition, Casual Mode, in most parts of the game, is basically just walking from point A to B, picking things up, and putting them where they go.  There are virtually no challenges in this mode.  Hard mode is easy in many spots, but some of the puzzles are way more challenging and the', 'Although the game was initially entertaining and captured my interest through a murder mystery plotline, my opinion of it tanked after completing it. Without spoiling anything, it make me feel like the time I put into everything, including unlocking every achievement, feel like it was all worthless. If you''re really on the fence about this game and don''t really mind spoilers, I''ll provide details below. If you don''t want to be spoiled on the ending, I''d get this game only if it''s on sale.\n\n**SPO', 'Very Positive', 91.34, 51.05, 24.58);
INSERT INTO reviews VALUES (18904, 569970, 109, 'Chosen 2\n\nHas a total of 5 trading cards.\n', 'This game is total dogwater slop, one of the worst thing uploaded on Steam. The game is only about 2 hours long and it continually crashes, it even crashed after I defeated the final boss and didn''t allow me to save, put a screen up "one week later" then instead of showing me the rest of the story I get a game over screen. Whoever made this game should give up on game dev it''s shameless and completely terrible, this is a scam and not a full game and it''s poorly balanced and agonizing. Game creat', 'Mixed', 59.63, 1.08, 2.55);
INSERT INTO reviews VALUES (18905, 570000, 123, 'its really good', 'mhh... seems like many here like it. So I purchased it.\n\nIt''s just not for me.\n\nDon''t recommend it, if you get motion sick easily.\n\nI couldn''t even write this review first, because the "game" only lasts 3 minutes and steam requires 5 minutes on record before you can write a review.', 'Very Positive', 92.68, 0.68, 0.18);
INSERT INTO reviews VALUES (18913, 570420, 148, 'Great game, fantastic graphics, but can we have the Oculus 2 controllers too, please?', 'Game has not been updated to work with modern steam VR. Unless you SPECIFICALLY use the HTC Vive it won''t work for you. Shame. It looks great but all I can do is look.', 'Mixed', 64.86, 0.43, 0.33);
INSERT INTO reviews VALUES (18915, 570490, 150, 'It''s solitaire with a nice skin, can''t really say a lot more but for that price you can''t really expect a lot more.\r\nalso an easy but grindy (win 100 games) 100%.', 'I''m sorry, but I can''t recommend it. It''s fun for half an hour but it''s far too simple and too easy to keep me playing. I''m leaving negative review because I''m stuck with the achievement for 100 won games when I''m already bored after 5 wins.', 'Overwhelmingly Positive', 98.00, 15.43, 5.10);
INSERT INTO reviews VALUES (18925, 570780, 107, 'Please try the English Translation Mod for Gujian 1: https://steamcommunity.com/app/570780/discussions/0/4415298372649709265/', 'Customer service sucks. Game can no longer play using my Nvidia 4090 display card. Similar like Assassins Creed Chronicles. They do not want to optimize the game further for today''s environment.', 'Very Positive', 80.37, 44.02, 42.32);
INSERT INTO reviews VALUES (18934, 570940, 42015, 'Evil. Evil game. Evil game is evil. Pure evil. Evil evil evil evil game. It will hurt you. Absolutely horrible and evil game. I hate it. Why would someone ever make something this cruel and evil?? Highly recommended. 11/10,', 'Completely plagued by hackers like every Souls game. But here, people join your game and ruin your save data PERMANENTLY, NPCs appear dead and everything in the world is altered. Only good if played fully offline in single player.', 'Very Positive', 91.39, 39.68, 176.50);
INSERT INTO reviews VALUES (18935, 570950, 106, 'SO MUCH GOING ON I CAN''T SEE SHIT...THAT MEANS IT''S AWESOME', 'I really wanted to like this game but the more I played it the further from liking it I got. I have played many "boomer shooters", they are my absolute favorite type of game to play. This one on the other hand is probably the most frustrating one by far. It started off pretty good, and by that I mean the first level, then came the second and it was more or less the same as the first, same with the third, fourth, fifth and so on for the entire game. I have no idea how many levels you have to beat', 'Very Positive', 85.85, 47.13, 11.15);
INSERT INTO reviews VALUES (18946, 571260, 602, 'I''ve had and played this game on PS4 for years. It''s SNK''s first foray into 3D and it''s... Mostly on point. The looks are a bit off in some areas, but where they absolutely nailed it was the feel and character of the game. If you''re not a long standing fan, that''s difficult to explain, but if you play this you''ll feel it. You''ll totally get why this franchise is so loved.\nSo, with 15 out and 13 games before this, with the previous one looking SO good, is it worth getting this now? Yes, in short.', 'If y''all are playing on steamdeck, don''t even try to buy this one, in fact, don''t buy any kof games, \nA common issue among all of the kof game (ive tested every single avalible one, besides for kof 15) is it takes forever to load a single menu, in the matches it''s fine, it plays as expected, the games run at 60 fps on highest settings. But it takes upwards of 5 minutes to load the main menu of kof 14, kof 02, kof 98, and mark of the wolves , and kof 13 doesn''t even load (infinite loading screen ', 'Very Positive', 82.56, 4.70, 5.50);
INSERT INTO reviews VALUES (18947, 571310, 2546, 'A good game by all accounts, but slightly underwhelmed after seeing ''Overwhelmingly Positive'' reviews, not overwhelmed in the slightest, a good time kill though.', 'SteamWorld Dig 2 is... well, it''s okay. It''s a solid game if repetitive. It''s not really my cup of tea but I can see the game is solid and well built. If this looks like it''d interest you, grab it on sale as it goes on sale quite often for quite cheap.\n\nHowever, the sound is inexcusably bugged. If I''m buying a game from the last decade and I have to download a sound program and manually fix the sound so I can actually hear sound effects; we''re off to a horrible start. Fix the sound.', 'Overwhelmingly Positive', 95.25, 13.72, 1.95);
INSERT INTO reviews VALUES (18954, 571530, 294, 'coolest intro, nice main menu design, cool HUD style, improved graphic and no fps cap so far as well, brings comfortable in gaming. The game play mechanic is the same with previous Hyperdimension series. so its thumbs up from me. Difficulties spike is still exists in this game, so you still have to put a little effort in grinding. \n\nalso where is blanc? where is noire? where is vert? where is rom, ram? uni?. almost giving this game thumbs down because blanc my beloved isnt represented in this ga', 'Awful controls, Awful grinding, meh story with crossover characters that only 3 people and their dog will give a fuck about, unneccessary inclusion of the worst Neptunia char (Plutia), final boss is a mindless monster with no personality and Segami is a cardboard in terms of that too.', 'Very Positive', 91.50, 192.50, 36.45);
INSERT INTO reviews VALUES (18959, 571720, 144, 'It''s better than Call of Duty: Ghosts.', 'I bought this game for like $2 from a sale and I still want my money back. The controls are super janky and unintuative that I think I would actually rather play overwatch. I would have played longer to see if it gets any better but my hand was hurting after like 10 minutes of playing. Trust the other negative comments yall', 'Mostly Positive', 70.83, 55.37, 0.22);
INSERT INTO reviews VALUES (18960, 571740, 11388, 'It''s a Souls-like mini golf game that will psychologically expose you for the fragile child you are. My group of friends now refers to Golf With Your Friends as "training wheels golf," and we all have constant misguided meltdowns on Discord, including bursts of masochism like "Kill me with a car," and "My dead dad would be so disappointed in me." \n\nYou''re pathetic. Golf It! knows that and will air it out like dirty laundry to everyone you love. Incredible community maps. Risk-reward scenarios th', 'made me angy :(', 'Very Positive', 89.86, 81.22, 3.27);
INSERT INTO reviews VALUES (18963, 571880, 1124, 'I wish there was an option to play as a dragon.', 'Writing''s not good, people are just way too nice because it''s niche content to an underserved market (dragon autists), same as how survival horror fans have lower standards due to content scarcity.', 'Overwhelmingly Positive', 96.53, 26.92, 43.12);
INSERT INTO reviews VALUES (18964, 571890, 205, 'Wonderful tool, I use it for organic modeling of characters. Would not trust the symmetry to this software alone. I post-process with TopoGun 3D revectorization to make things look neat.', 'When I initially purchased this product, it was called Shapelabs and included a perpetual license that guaranteed all future updates at no extra cost. Now, they’ve rebranded it as Shapelabs 2024 and are marketing the next update as Shapelabs 2025 to justify charging additional fees. I paid nearly 70 euros for what was supposed to be a complete, all-inclusive system, and this feels like a classic bait-and-switch. They’re now trying to sell updates they originally promised would be free.\n\nThe so-c', 'Very Positive', 82.93, 32.77, 33.13);
INSERT INTO reviews VALUES (18974, 572220, 763, 'If you liked Warlocks from Warcraft III, you''ll like this. It is a bit different, but a lot more fair/"competitive" style.', 'Absolutely abysmal controls. I started on kbm. First it has me in mouse movement mode which was insane that they even conceived a version of controls like that. I hit F1 to swap to WASD. I play a bit like that. The mouse doesn''t have a cursor, it only reads your recent direction of mouse movement to move an arrow. Holy crap that''s awful. They suggest you do controller, okay fair enough. I pull on the controller and low and behold it still feels awful. It''s not like a twin stick shooter the direc', 'Very Positive', 94.36, 30.73, 0.17);
INSERT INTO reviews VALUES (18979, 572410, 2589, 'I''m writing a quick review to take to task the blithering drivel currently being spewed by kids that blast a game they know nothing about, after playing it for 20 minutes. \n\nThis is a great game not a good game. Yes the AI will shoot through windows and nail you the moment you enter the range of a tank or AT gun - so what. This game was meant for human competition play and it''s fantastic. \n\nEveryone wants INSTANT gratification of their little game and has no patience for watching well planned ta', 'These devs are trying to hard to make the game inaccessible, hard to control camera, all units need intense micromanagement and need to be told to get out of trucks etc', 'Mostly Positive', 73.81, 84.12, 0.13);
INSERT INTO reviews VALUES (18980, 572430, 555, 'aint no party like the diddy party', 'At first, I didn''t understand why so many people disliked this game. But by the time I was ''finished'' and cleaning up with achievements. I really understood.\n\nThe game feels very unfinished. The story feels all over the place and is really confusing, nothing like the first game which was very clear in it''s story and goals. One major issue is a bug with the workshop menu that only allows you to go back to the main menu and not select anything. This causes three achievements to be completely impos', 'Mixed', 67.75, 18.75, 120.63);
INSERT INTO reviews VALUES (18989, 572700, 171, 'What a game. Probably my fave among the newer Nancy games. I feel like there''s a great balance between puzzles, story, characters and general vibe in this one, which adds to the enjoyment of the game. It''s a lot of sudoku though. Like a lot.', 'The voice acting and script is bad compared to the older Nancy Drew series. I just find everyone so cringe. Also none of the characters are charming enough to be even a bit likable. They all hate Nancy. She says so herself when she calls Ned in the game! Bess and George, and the Hardy Boys don''t make any appearances in the game with any useful hints or polite conversation. Ned pretty much is useless, too. They removed the hint voice over scripts from Nancy''s friends probably because of budgetary', 'Very Positive', 92.40, 13.83, 6.33);
INSERT INTO reviews VALUES (18992, 572730, 137, 'I really enjoyed the story of this one! The puzzles weren''t my favorites, and I also do not understand how there can be a ''wrong cookie'' lol, but I felt that completing them and earning money were adequate and it wasn''t too tedious. I especially loved Zoe and the lore there too! While I probably won''t ever replay this one, I did like being able to learn a little more about the Drews.', 'I have played Nancy Drew games since I was 6 years old, and I love this series a lot. Sadly, I cannot faithfully recommend this or any other of the newer ND games because of how buggy they are. I purchased this game, played a bit, then tried to save and it crashed. I looked up tips online, followed them, and tried again. Still no go. It still cannot save on my computer, and I''m just so tired of trying at this point.\n\nMany people online agree that the newer games have consistent issues similar to', 'Very Positive', 89.78, 6.07, 7.53);
INSERT INTO reviews VALUES (18993, 572740, 168, '"When there''s a phantom horse/Riding round your ranch! Who you gonna call?"\n\nApparently not the police.\n\nGreat installment to the series, but the near-chronic anxiety of attempting to correctly identify ripe vegetables made me borderline manic.', 'This game sucks. I LOVE the Nancy Drew games, but this one is SO tedious. The daily tasks, the constant saddling and unsaddling of the horse, it''s just too many repetitive actions. Not only that, but if you don''t finish in one setting or take more than a day or two in between good luck figuring out where you left off with the puzzles and the clues.', 'Very Positive', 89.29, 6.73, 6.40);
INSERT INTO reviews VALUES (18995, 572890, 3323, 'super fun game,totally the dark souls of the genre trust\r\n', 'STOP LOOKING AT THE NEGATIVE REVIEWS AND JUST BUY THE GAME YOU IDIOT, IM SACRIFICING MY POSITIVE REVIEW FOR THIS, PLEASE, BUY THIS SILLY AND CUTE LITTLE GAME, CMON, GAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAHHHHHHHHHHHHHH', 'Overwhelmingly Positive', 95.88, 22.92, 1.27);
INSERT INTO reviews VALUES (18999, 573060, 164, 'Installed - Unlocked all the achievements - Uninstalled', 'It''s pretty boring for the most part, I''d probably enjoy it more if I liked management simulators.', 'Very Positive', 81.10, 0.25, 40.65);
INSERT INTO reviews VALUES (19002, 573090, 36435, 'Crash boats and planes in the coast guard, go home play stormworks and admire how the crashes are similar, 10/10', 'The game has unmatched potential, but they still havent fixed the games core or engine. Meaning, once you load in boats that are like medium-large sized. You cant even play the game. Instead of fps drops, the game itself just goes slower, you fall, walk, jump in slowmotion. All these "major update" things dont matter because the content people spend hours on making can barely be rendered and used.\n\nIf the creators actually rewrote the core engine and rendering system and such - it would actually', 'Very Positive', 90.14, 86.92, 41.48);
INSERT INTO reviews VALUES (19003, 573100, 5353, 'good game relay fun however modern hard where will crash because of a issue with the engine. the dev fix didnt work but put this in your launch options and till work fine. took me ages to find it so heres it for anyone who wants it\n\n cmd /c "set OPENSSL_ia32cap=:~0x20000000 && %command%" -NoEAC', 'The game crashes just while sitting in the menu, this issue effects specifically newer hardware. A quick search shows that this is a widespread issue, one must research and follow guides in order to get the game to work. \n\nThe "patch" that "fixed" this in September, did in fact not fix this, as can be seen by the comments in the discussions for that patch as of January. \n\nOne should not have to crash multiple times and follow unofficial advice scattered across the internet and add launch command', 'Mostly Positive', 74.72, 24.42, 2.88);
INSERT INTO reviews VALUES (19005, 573120, 514, 'On sale? Definitely get it. Otherwise, no. I can see what other reviewers meant by the dialogue; that and the art often feel amateur at worst and just rough draft version at best. I enjoyed Dead in Bermuda less than this, I''ll give it that, and I enjoyed Banner Saga more; this is essentially a blend of the two. It really needs another pass from an experienced dialogue editor and character artist.', 'The art style is nice. So are the characters. The survivors are a diverse bunch, and seeing them interact and learning their stories is fun. The villains are easy to hate.\n\nBut the gameplay is terrible. Everything is based on chance. Even the traits you get offered as your survivors level up. A few days of bad weather can cripple your run, with no way of you being able to hedge against it. Every day/turn, you distribute your survivors among the available work stations based on skills and conditi', 'Mostly Positive', 78.21, 64.87, 40.43);
INSERT INTO reviews VALUES (19006, 573130, 260, '🌿 A Mystical Journey Worth Taking! 🌿\n\nAporia: Beyond The Valley is a visually stunning and atmospheric adventure that pulls you into a beautifully crafted world filled with mystery. From the moment you step into the valley, the breathtaking environments and hauntingly beautiful soundtrack immerse you in a story told without words—relying solely on environmental storytelling and cryptic pictographs.\n\nThe puzzle mechanics are intuitive yet rewarding, striking a perfect balance between challenge an', 'Nope, to me it is more a walking simulator/demo for graphic cards than a puzzle game. I left this game sleeping for many years and i know why i left it, the walking phase and slow pace bored me.', 'Very Positive', 84.23, 9.12, 5.35);
INSERT INTO reviews VALUES (19007, 573170, 222, 'Really fun little puzzle game.  I wish they hadn''t tied an achievement to like 309 daily wins.  Otherwise I woulda 100 percented this game.', 'I wanted this to be a relaxing puzzle game but the timer/ghost changes that dynamic. I know many players like a little pressure and say it''s not a problem if you get better. For me it''s an immediate turn off and I''m not interested in playing long enough to become ghost-proof. I''d rather have an option to just disable the ghost, so no timer and instant death. Making a mistake and then trying to correct it in a handful of seconds is just not fun for me.\n\nOther than that it''s actually a cute game t', 'Overwhelmingly Positive', 95.05, 4.05, 2.08);
INSERT INTO reviews VALUES (19013, 573320, 561, 'My favorite game of all time. easily. a timeless classic in the eyes of my younger self', 'I really wanted to like this game cause there is a lot of charm in it. I can''t recommend it. The designers bill the game as "having no turns" but that''s not true. There are turns, but instead of the game managing the turns, you do, if you don''t manage the turns correctly, you get punished. This feels really bad when enemies can move but you can''t, especially when the ranged weapon is really awkward to use. It''s an interesting idea, but the stamina bar is nothing more than a turn timer, when it h', 'Very Positive', 91.62, 11.90, 3.92);
INSERT INTO reviews VALUES (19018, 573410, 922, 'Amazing game, but please hire a UI/UX Artist, your UI looks like crap :P', 'I actually really enjoy this game but i have one major issue, why is it so hard to know exactly how much metal you''re spending, and it so stupid and frustrating when all of a sudden nothing will work all because you captured 2 planets back to back and immediately build mines just avoid that problem, what kind of sense does that make!?!?!? Now i have to restart all because there is no way to no how to adjust or destroy any units just so your metal income is positive/negative. oh yeah, the whole t', 'Very Positive', 89.91, 119.40, 57.32);
INSERT INTO reviews VALUES (19020, 573490, 293, 'I absolutely Love this game, However... The game has been abandoned. I understand this is a niche game and it didn''t have enough buy in to keep making it. \nDevs I beg you to please release all the code for this and allow those who love it to try and re-breath fresh life into it. There is something about this game that makes me want to binge playing it for hours every few months until I reach a point where I feel that I have seen the whole game/reach a point where i see the game has no more conte', 'Really neat game. Sadly abandoned mid development.', 'Mixed', 67.58, 187.87, 10.15);
INSERT INTO reviews VALUES (19042, 574030, 105, 'Interesting football Physical game with 7 languages (if you need it), with many interesting levels where you try to get goal as fast as possible to break the highscore.\n\nFor Highscore Hunters/ Speedrunners & Achievement Hunters', 'Puzzle game that consists of scoring a goal by indirectly moving a ball towards the objective by exploding, moving, and/or removing things out of the way.\n\nUnpolished minimalistic flash-like graphics and terrible repetitive soundtrack.\n\nOver five dozen levels, which do offer some variety but are fairly fast to complete, sometimes rely in timing and luck, and offer little replayability.\n\nI certainly do not think this is nowhere near worth its full price, and still am hard pressed to recommend it ', 'Mixed', 64.76, 3.43, 0.30);
INSERT INTO reviews VALUES (19044, 574050, 399, 'Needs more puff-puff', 'The surface game is a fun little JRPG, but the deeper game is way, WAY too involved and complicated. They give you 15 characters for a 4 unit team, then they give your mains different vocations, and everyone has weapons proficiency. Maxing accessories for just your core team is a massive grind of ingredients and additional accessory drops, and all up, if you want to 100%, you''re looking at hundreds of hours hacking away at the same monsters over and over. Not sure if it was deliberate to make yo', 'Mixed', 68.92, 133.37, 372.42);
INSERT INTO reviews VALUES (19046, 574080, 265, 'Fog of War\n\nHas a total of 6 trading cards.\n', 'DO NOT BUY THIS TRASH. It''s complete, utter trash. Absolute, hardcore garbage. I bought it only because I want the wallpapers and emoticons that come with it and Steam won''t allow me to buy them individually from the point shop if I don''t own the game first.', 'Mixed', 47.92, 2.20, 5.93);
INSERT INTO reviews VALUES (19047, 574090, 843, 'I got mixed feelings about this game. \nOn one hand it''s fun and looks and sounds great and it has good/funny writing, \nOn the other, it''s repetitive, cursed with procedural generation, and if RNGeezus hates you you will not have the gun you want.\nSometimes I felt overpowered, sometimes too weak to complete a map, and I felt it wasn''t because of a skill issue, but rather I just got dealt an impossible hand. Some(way-too-many) guns are practically useless.\nBecause of that I did not stay for the po', 'Epic Games malware injector', 'Mostly Positive', 79.12, 13.15, 6.37);
INSERT INTO reviews VALUES (19053, 574180, 384, 'Honestly, the dev is an amazing person. He''s super kind and will answer any questions/issues you have. This game is very similar to Rust, however this game was being built roughly at the same time. Rust came out earlier because they had a larger team compared to this game being a solo dev at the time. Everything about it is pretty good and constantly has updates with new additions. There are some things I like/dislike but thats personal preference. I would love to see a larger player base to mak', 'Damn, I wanted to like this. I always wanted solo offline rust, this ain''t it. The building/harvesting is just dog crap, doing anything is slow and clunky. Almost 40 hours and it''s been a slog. Save your time and money. It has potential, it will fail to meet it.', 'Mostly Positive', 77.08, 172.67, 38.27);
INSERT INTO reviews VALUES (19059, 574310, 182, 'Komi-permian religion looks awesome hope they were right', 'On sale recommendation. The Mooseman is a charming, magnificently researched game that highlights the culture of an often forgotten part of the world. The art direction is especially captivating, while the gameplay amounts to a very casual puzzler. \n\nHowever, I cannot recommend The Mooseman at full price. I paid 8 USD for what ended up being only 2 hours of gameplay. My personal standard is that I expect a game to provide me with at minimum 1 hour of fun for each dollar I spend. The short story ', 'Mostly Positive', 79.67, 0.40, 2.28);
INSERT INTO reviews VALUES (19066, 574560, 1720, 'A mixture of a rage game, a puzzle game, and a meta-narrative game. Dude, Stop is overpriced, but if you get it for a discount you can have fun with it.', 'I feel like this is a bad version of There Is No Game, after a while the narrators voice is annoying and unfunny, a game not worth going back to and the price is bad for a game like this. If someone really wanted this game, get it on sale.', 'Very Positive', 87.44, 5.72, 1.57);
INSERT INTO reviews VALUES (19072, 574720, 960, 'It is an ok factory game, and it is not a bad game, but you will probably get tired of it relatively fast. There are some things that get in the way of it being a really good factory game. If you really try to optimize a factory you will likely get annoyed by the things you cannot control. For example the output storage for a workstation cannot be specified, a workstation can have only one input storage. Storage cannot be managed to permit only certain items. So a task which needs to assemble bi', 'The game would be fun if it had a sandbox mode or more forgiving dynamics, such as the ability to take out loans. This is a simple solution to its problem that would increase its player base and boost sales. But that common sense is nowhere to be found. The bigger issue is that the game was poorly play tested (or play tested with trainers and developer commands that players will not normally have access to). The workers tire too rapidly, work too slowly, and overall the game is just unbalanced. ', 'Very Positive', 82.92, 42.83, 76.02);
INSERT INTO reviews VALUES (19074, 574760, 723, 'Seeing as it is now free to play I can recommend trying it out.\nThere are some bugs, I''ve encountered that the buttons to trade with other ships become increasingly larger as the game goes on, this can be rest by saving the game and then immediately reloading that save directly. Probably a memory bug or something.\n\nDon''t expect too much from it, but it''s certainly a fairly chill experience for me. And at that price (free at the moment of writing this review) the only thing you can lose is some t', 'Abandoned', 'Mixed', 49.52, 90.47, 10.47);
INSERT INTO reviews VALUES (19076, 574820, 250, 'this is the best game ive ever played. amazing concept. amazing art.\r\ni think there are 3 gamemodes. one of them you click on cats. thats it. i still havent solved the other 2.\r\ntruly a masterpiece. still waiting for cat or bread 2, where you click bread this time. gonna be a hell of a twist.\r\nplay this game. it will change your life', 'this game is literalty so hard im crtying right nown dont buy', 'Very Positive', 94.40, 56.18, 4.37);
INSERT INTO reviews VALUES (19081, 574980, 2196, 'good fighting game. developers sadly got screwed out of the chance to finish story mode when they got bought (and then laid off) by the publisher but game itself is still fun.', 'Love the game. Hate the publissher. Maximum Entertainment, may you rot. Mane6 Inc, I wish you the best.', 'Very Positive', 80.78, 81.98, 0.87);
INSERT INTO reviews VALUES (19095, 575330, 279, 'ㅤ', 'Compared to the first game, not much has changed.  \n\nThe characters are now outdated pop culture icons like Gandalf, Harry Potter, and O-Ren Ishii from Kill Bill. Instead of classic insults like "Your mother is your father", you now have to craft phrases like "Your last movie feels like a forced sequel" or "Your therapist got their degree online."  \n\nIt''s rare to come up with truly funny insults, and the Hollywood aesthetic doesn’t appeal to me, so I don’t see much point in playing this. You’re ', 'Very Positive', 86.02, 4.15, 5.48);
INSERT INTO reviews VALUES (19102, 575480, 134, 'Played a cracked version 5-6 years ago. Didn''t have the money to buy it.\nAfter finishing the game I told myself I would buy this amazing game when I had disposable income.\nI had forgotten about it until now but I kept the promise I made to myself.\n\nRecommend this game very much. Gonna play it again for sure.', '35 ชม. เสียไป ไม่แนะนำครับ หลักๆคือ บท กับ เนื้อเรื่อง\r\nนางเอกมีแค่ 4 คน แต่เขียนมาไม่น่าสนใจ Transition จากเพื่อนสู่แฟนก็นำเสนอมาได้น่าเบื่อ แล้ว Bruh  ตอนท้ายแต่ละรูทเหมือนจะดีแต่ไม่สุด มุขขำก็แห้ง พระเอกแม่งไม่มีอะไรเลย ไม่มีเสนห์ ไม่มีเหี้*ไรสักอย่าง โดยรวม 6/10 หลักๆปัญหาไม่ใช่ตัวละคร Story ล้วนๆ  2/35 ชม คือที่ชอบ เช่น ฉากสารภาพหลักคาโอรุกะ ตอนสุดท้ายของ ซากุรากิ กับ ตอนมาฮิโระตกหลุมรักโคกิ มันมีแค่นั้นจริงๆ\r\n35 hours wasted. I don''t recommend it. The main problem is the story not characte', 'Very Positive', 91.79, 35.40, 34.97);
INSERT INTO reviews VALUES (19112, 575640, 1492, '5/5 would crash Steam again for profile customization. \n\nAlso, the  ZUP!  games really aren''t bad and can be quite relaxing to play for 30-60 minutes. Like say, if you''re avoiding your family on Thanksgiving.', 'a very low quality game but its an easy 100%', 'Very Positive', 90.48, 1.28, 0.65);
INSERT INTO reviews VALUES (19113, 575650, 156, 'this game is just doki doki literature clubs older sister', 'Lily''s Day Off isn''t a "bad" game.  I mean, it''s got a paper doll for a main character, blurred stock backgrounds, and the best of Kevin MacLeod, but it''s cheap, not flawed.  Honestly, it''s more weird than anything.  That said, I got a few chuckles out of the premise and wild plot turns, enhanced by some silly dialogue.  It''s iffy, but also kind of funny that the age-ambiguous main character is perving over a middle schooler who looks like an elementary schooler.  The dress-up options push the j', 'Very Positive', 86.54, 0.48, 0.75);
INSERT INTO reviews VALUES (19127, 575820, 110, 'It''s a fun arcade top down run(albeit in opposition to the usual direction) and gun that''s easy to pick up and play with another human being next to you so for a properly low sale price... give it a go why not.', 'Dear our developers\n\nWe are all very grateful to you for releasing such a masterpiece, and even at such a time.\nThank you that there are no blacks and LGBT people in the game.\n\nYou have created a masterpiece and now all you have to do is continue to edit the technical component.\nThank you, take care of yourself and keep giving us new games!', 'Mostly Positive', 72.73, 3.82, 10.67);
INSERT INTO reviews VALUES (19137, 575950, 289, '⠀', 'You can shoot aliens, and you can also shoot spiders, imagine how cool that is! And also jump run and fight bosses, the game has so much fun that you feel like you are in a park with amusement rides. Not a bad choice of weapons with which a few minutes interesting to shoot at monsters, but the games from this developer is very boring and undeveloped ...', 'Mixed', 66.09, 17.88, 4.68);
INSERT INTO reviews VALUES (19142, 576030, 263, 'im gatekeeping (real ones get this joke)', 'unplayable on steam deck\n', 'Very Positive', 86.69, 4.62, 0.15);
INSERT INTO reviews VALUES (19152, 576260, 110, 'Nice Community feel and obvious room for expansion. Maybe also, and online component should be Awesome !', 'I can''t believe I paid 2 dollars for this!!\nFOR THIS!!!\n\nUgh, 2 dollars!!!!!\nWell, at least I took a copy of this game...out of this world, so someone else doesn''t accidentally play it....\nYou''re Welcome World', 'Mixed', 60.91, 42.88, 0.40);
INSERT INTO reviews VALUES (19155, 576310, 142, 'Nice little walking sim. I''m not sure why all the negative reviews, especially those complaining about the pace being too slow. It''s an open world walking simulator, it''s supposed to be. Besides, most people should be able to complete the game in about an hour or two. Never mind my Steam time because I''m always pausing games to go do stuff, then I come back to continue, esp. when there''s no saves, as with this game. Graphics aren''t spectacular, but they''re decent enough, and the narrator has a n', '\r\n---{ Graphics }---\r\n☐ You forget what reality is\r\n☐ Beautiful\r\n☐ Good\r\n☐ Decent\r\n☐ Bad\r\n☑ Don‘t look too long at it\r\n☐ MS-DOS\r\n\r\n---{ Gameplay }---\r\n☐ Very good\r\n☐ Good\r\n☐ It''s just gameplay\r\n☐ Mehh\r\n☐ Watch paint dry instead\r\n☑ Just don''t\r\n\r\n---{ Audio }---\r\n☐ Eargasm\r\n☐ Very good\r\n☐ Good\r\n☑ Not too bad\r\n☐ Bad\r\n☐ I''m now deaf\r\n\r\n---{ Audience }---\r\n☐ Kids\r\n☐ Teens\r\n☑ Adults\r\n☑ Grandma\r\n\r\n---{ PC Requirements }---\r\n☑ Check if you can run paint\r\n☐ Potato\r\n☐ Decent\r\n☐ Fast\r\n☐ Rich boi\r\n☐ Ask NAS', 'Mixed', 54.93, 5.45, 5.28);
INSERT INTO reviews VALUES (19178, 576770, 1067, 'As God is my witness, I thought turkeys could fly', 'This game has been out since 2017. To this day there is no story line, unless you consider "rescue the merchant" or "create two high quality wooden clubs" a story. That''s seven years of basically no significant improvements. There are dozens of skills  which are not implemented in the game and I suspect never will be. This is one of those games that made me swear off early access. I literally got so bored that I started a arena party which was undefeated 50 straight fights until a group of lizar', 'Very Positive', 88.57, 54.83, 139.98);
INSERT INTO reviews VALUES (19190, 577080, 203, '⠀', 'An affront to God, men, and video games. It fails at both horror and comedy. How does someone make a game about being a pair of floating ass cheeks so un funny? Its an incoherent, terribly optimized mess. I bought this for .50 For the shit emojis and hated playing every second of it.', 'Mostly Positive', 70.44, 4.15, 2.03);
INSERT INTO reviews VALUES (19196, 577230, 331, 'Three Kingdoms: The Last Warlord is a must-play for strategy lovers and history buffs.\r\nIt delivers deep, turn-based gameplay with rich historical detail and tons of replayability. Managing cities, armies, and diplomacy feels rewarding without being overwhelming. The art style and music perfectly capture the era, and each campaign offers a fresh challenge. If you''re into the Three Kingdoms period or classic strategy games, this one’s absolutely worth your time.\r\n\r\nRating: 9/10', 'Buyer beware. Being a fan of the older, SNES/PSX era ROTK games, I''ve been hoping for viable spiritual successors for years. The Last Warlord could''ve been it. But I''m greatly disappointed by its makers'' disdain for English-speaking players.\n\nThe English language translation is a shoddy afterthought at best, incomplete and at times woefully incompatible with the game''s own interface. It''s all clearly designed and prioritized for Chinese characters, which means the generic Western font of the mec', 'Mostly Positive', 71.90, 537.92, 0.10);
INSERT INTO reviews VALUES (19207, 577410, 195, 'Basic short run FPS roguelike. Play couple hours a time. Die (a lot), restart. It is not dissimilar to the original The Pit. A lot of negative reviews on this for some reason, I''d say the game is nothing spectacular, but you get enough bang for your buck.', 'This game was the most pathetic cash grab derived from a previously good game you will ever likely find on steam. The game was launched an unfinished and buggy mess, and so it remains. The game hasn''t been updated since 2022, yet they felt comfortable having the gall to charge for DLC for a game that they hadn''t even fixed. This should have never even left early access and the people who dumped this crap onto the shop should feel bad for the lack of pride they have in their work. Sword of the St', 'Mixed', 65.13, 8.95, 3.28);
INSERT INTO reviews VALUES (19209, 577460, 103, '⠀', 'Tricking people to buy this using hundreds of senseless achievements.\nThe game is nothing special, Steam-Overlay doesn''t work and the controls are clingy.\n\nWhen will Valve take measures against this achievement-abuse?\n\nDownvoted!', 'Mixed', 50.49, 2.52, 10.52);
INSERT INTO reviews VALUES (19211, 577480, 412, 'Shion is kinda like the Joker but for women', 'English translation quality dropped severely in this part. For every sentence in Japanese, half the clauses get translated and the other half are abducted by the oni. If you''re reading in English you''re only reading half of the novel.', 'Overwhelmingly Positive', 96.84, 10.42, 136.23);
INSERT INTO reviews VALUES (19213, 577530, 136, 'A very nice experience. Not what I was expecting, but very nice.', 'Stylistically wonderful but unfortunately the gameplay itself is incredibly tedious, with no need to interact with the ‘real world’ outside of occasionally looking up - apart from the novelty factor it may as well not be there. Difficulty spike on the final boss is incredibly frustrating due to perspective issues which turned a mediocre game into a poor one. Very disappointed.', 'Very Positive', 84.56, 0.38, 1.97);
INSERT INTO reviews VALUES (19218, 577670, 425, 'Driving through the city, everything is empty and no one is to be seen. Tearing down the buildings. Finding out that you are working in a ghost town. Creepy stuff.', 'You can''t even skip time. I mean who works on a construction site during the night?\n\nAlso you can only store the save file locally. Since it''s 2025 I thought it was on steam and did my yearly factory reset w/o backing up the save. Thank you for throwing my progress out the window', 'Mostly Positive', 75.76, 1.75, 8.97);
INSERT INTO reviews VALUES (19219, 577690, 2293, 'love the body bag’s lore. Can’t believe such a tragic story was hidden in a YouTube video by a somewhat small YouTuber who ranked all the Specimens.\n\ngame’s also really good too. I love being scared!', 'Absolutely horrifying I can’t even begin to tell you the immense amount of fear this game has instilled into me. I bought this game because my therapist said I need a stressfree hobby and since my last hobby, building Ikea furniture with my ex-wife, almost killed me with a heart attack, I decided to give gaming a shot and this one just looked so cute. It was fine for a little bit, just a nice stroll through a castle. I''ll admit the ghost girl threw me off a bit since I’m deathly afraid of ghosts', 'Overwhelmingly Positive', 95.94, 2.53, 0.37);
INSERT INTO reviews VALUES (19221, 577730, 126, 'learn elements along with solving objectives, the game is beatable if you spend alot of time, well designed game with plenty of features', 'Really weird game, with random unclear objective due to really, REALLY bad English. If you can even call it "English." It''s like some random Chinese person found out about Google translate, and thought it does the job in interpreting their language into English. And nothing at all is clear as to what is going on, or what the objectives are actually supposed to be, and what the purpose of each screen is even for. Just. A random screen thrown together with no real rhyme or reason.', 'Mostly Positive', 71.43, 94.68, 0.30);
INSERT INTO reviews VALUES (19228, 577940, 2123, 'One of the best fighting game revivals and a proper example on how to revitalize a sleeping IP.\r\nEach character is unique, gameplay is buttery smooth, dynamic battle soundtrack, awesome art style, lagless online matches, the complete package is a just a chef''s kiss. \r\nFor anyone out there itchin'' to play something fresh that isnt'' Street Fighter, Tekken, Marvel VS Capcom, this one is a JACKPOT.\r\nI got a full rostered game for just 10 bucks and that.. you cannot beat.\r\n', 'Game shows a clear anti-Christian bias deliberately replacing BC and AD with "BCE" and "CE".', 'Very Positive', 92.13, 12.58, 7.02);
INSERT INTO reviews VALUES (19234, 578080, 277230, 'PUBG: the only place where you can drop out of a plane, get shot through a wall by someone named ''xX_NarutoSniper420_Xx'', and then get ambushed by a guy in a pink anime cat-ears helmet. The devs keep adding anime skins and ‘limited-edition’ outfits, because nothing says ‘gritty survival’ like a neon ninja riding a motorbike through an airstrike.\n\nAt this point, it’s less of a battle royale and more of a cosplay convention with very aggressive laser pointers. The real game isn''t survival — it''s s', 'Its 2025, game is full of cheaters. And when you report somebody who obviously used aimhack or wallhack he gets temporerly banned for one hour. And then he will be back in the game. Really developers? Game is unplayable at this point.', 'Mixed', 63.25, 240.02, 591.60);
INSERT INTO reviews VALUES (19237, 578210, 391, 'Worth the dollar I spent on it so far. If you see this and have bought it recently, the tutorial doesn''t let you move like normal, just get through it and you can move/controls work just fine. Just make sure you have enough space when you do it to physically walk forward a few steps and reach out fully for a part of it. Also if you have problems playing it with a quest, manually add it to your meta pc app library and launch it directly from there like any other quest game. Worked for me.', 'This game wants me to press buttons that are not on the pico 4 controller, this so OLD game.\nЭта игра хочет чтобы я нажимал на кнопки которых нет на контроллере pico 4, эта игра ООЧЕНЬ СТАРАЯ.', 'Mixed', 63.68, 0.75, 0.63);
INSERT INTO reviews VALUES (19238, 578310, 120, 'Not pay-2-win and is all about skill, explosives are OP as they should be in real life, it''s like a real life 2D Pixel FPS.\n\nWorth a shot but not for all people.', 'The game lacks servers in my area. instantly killed when spawned (without any shots being fired) the game lacks in everyway. don''t download.', 'Mostly Positive', 70.83, 51.98, 0.12);
INSERT INTO reviews VALUES (19240, 578330, 3009, 'Despite being 12% of the population, Mega-Bloks commit 56% of violent crimes in Lego City.', 'Personally, this game is frustrating as heck and not at all intuitive for a person who primarily plays on a keyboard and mouse. I bought it to play with my daughter but the same screen coop seems buggy at times, so I just let her play alone. It would ultimately be such a perfect game to play together and I''d imagine if you could buy it on consoles you''d have a much better experience. It feels like whoever did the keyboard and mouse controls has never used a keyboard and mouse to play a PC game.', 'Very Positive', 89.90, 2.37, 53.57);
INSERT INTO reviews VALUES (19248, 578540, 345, 'it''s a shame lesbians aren''t real', 'I do not know what I was expecting going int- wait, yes, I was expecting a cute yuri romance. \r\n\r\nI genuinely did not understand the tone of this. These characters felt to me a lot like they hated each other. Any inclinations that they liked each other were pretty forced by the author, just giving you choices. Seeing someone and determining they are attractive might make your heart flutter at first sight but my goodness. It felt like there were no deeper connections or desire. So, whatever, miss', 'Overwhelmingly Positive', 99.13, 2.47, 1.02);
INSERT INTO reviews VALUES (19251, 578620, 6398, '1.beat 3 men to death with a bat full of spikes\r\n2.buy gorn\r\n3.rip out a guys heart with a fencing sword\r\n4. play gorn', 'annoying pile of hot garbage', 'Very Positive', 94.45, 10.58, 40.15);
INSERT INTO reviews VALUES (19252, 578650, 15693, 'Okay so now imagine all the good parts of FNV, now get rid of the bugs and gambling and make the shooting part slightly more fun. And put it in space. Obsidian dev Is printing money.\nIts a great, kinda short game, would recommend you get it on sale though.\nScrew Starfeild', 'Game was interesting for a short time mostly due to dialogue. After thirty hours you start to see there is actually very little to the game overall and becomes very boring. The quests are all very boring fetch quests and the weapon diversity is poor. By the end I realized I had spent most of my time looting worthless items that are absolutely everywhere and constantly having to empty your inventory.\n\nSUMMARY: Once the humor wears off and you encounter the "awkward" quests in the game, it shows i', 'Very Positive', 83.18, 14.30, 30.70);
INSERT INTO reviews VALUES (19256, 578720, 623, 'This game presents death from a unique perspective—not as something dark, sad, or fearful, nor as a curiosity or an object of fascination, but rather in a calm, realistic, and serious way. A work that directly addresses the subject of death could even be seen as original and innovative.\nHonestly, compared to the themes and objectives the game seeks to explore, its structure is simple, its length is short, its content is limited, and the gameplay experience might feel inadequate to fully capture ', 'As others commented, this is not really a game, but rather an "experience" and as such it is somewhat overpriced (which is ironic given the game''s message).', 'Mostly Positive', 74.16, 1.23, 0.73);
INSERT INTO reviews VALUES (19261, 578850, 264, '10/10 recommended if you have 69 different brains working in parallel, 33 fingers and 11 keyboards\r\notherwise you will stuck at level 1 for 4 hours', 'This game does not work like it was intended. As huge DDR and Pump-it-up fan (on the floor and on keyboard), I had my good share of rhythm / hardcore games. I posted on the forums seeing if the developers can comment....but in the meantime I wanted to warn you with this video\n\nhttps://youtu.be/8YxFrbJnT9A\n\nSomehow the rhythm and the ''bad guys'' don''t move at the same speed after some time. As you can see those ''bad guys'' gradually go faster, while the music doesn''t. They were not positioned in a ', 'Very Positive', 90.91, 34.80, 0.50);
INSERT INTO reviews VALUES (19265, 578900, 448, 'they could never make me hate you, Sir Brash', 'Nice Art and good german localisation and nicely done production wise. The dark fantasy setting is compelling in and of itself.\n\nBut the story makes me shake my head and leaves me with so many questions. \n\nIm just not into romance plots where the romantic interest is just an evil piece of shit but its okay because they simply are just that much into our Mary S... I mean Girlboss heroine.\n\nClearly I am not the target audience.', 'Very Positive', 90.62, 13.53, 16.42);
INSERT INTO reviews VALUES (19267, 578930, 136, 'A pretty decent platformer with multiple gameplay modes to keep your runs fresh. The game features solid gameplay mechanics, allowing you to place checkpoints and slow down time. Additionally, it includes a reworked version of the first LOVE game for free.\n\nI highly recommend this game, especially if you enjoy speedrunning and striving for self-improvement.', 'kuso means poop in japanese, which is precisely what this game is. at least mister wood is self aware that his game is complete and utter bollocks', 'Overwhelmingly Positive', 95.59, 0.82, 2.00);
INSERT INTO reviews VALUES (19269, 579020, 273, 'nice', 'tennants keep diing on me, put them im, the die, put another in, they die too\r\n', 'Mostly Positive', 73.63, 10.67, 5.85);
INSERT INTO reviews VALUES (19273, 579110, 160, 'Very short, but I liked it (I''m a big fan of any space-themed game)', 'Controls were fuckin awful. Completely unplayable hunk of shit that felt like tryin to get a cow made of cats to dance. Maybe you''ll have more luck, so give it a shot and refund if you had the same control issues as me.', 'Very Positive', 83.12, 8.93, 0.13);
INSERT INTO reviews VALUES (19278, 579180, 2091, 'Damn, what a story! I found this game randomly on Steam and decided to give it a chance... Truly an awesome game with a dynamic combat system, great exploration, an amazing story, and compelling side quests. I’m now eager to learn more about the Ys series, this was my first one, and it was breathtaking!', 'Boring as hell. There''s a decent action RPG hidden in here but it''s extremely basic and they keep interrupting you with bland cutscenes instead of building up on the combat while having a decent story.', 'Very Positive', 92.44, 31.70, 4.98);
INSERT INTO reviews VALUES (19287, 579760, 245, 'The Journey Down: Chapter Three concludes the story of The Journey Down, when Bwana and friends reach the mysterious Underland at last and have their final showdown with the Armando Power Company.\n\nBwana, Lina and Kito finally make it to the Underland, although they don''t stay there for long, as the power company''s plan is finally coming to a head. Bwana and Kito return to St. Armando to stop them, with the help of some new friends they meet along the way. We actually get to play as Lina for a s', 'Fix your price!', 'Very Positive', 91.02, 7.75, 0.17);
INSERT INTO reviews VALUES (19289, 579820, 288, 'The controlls are a bit finicky, but once you get past that, it''s a decent game that looks pretty.\n\nA quick tip for Quest users. If you''re using Virtual Desktop of Steamlink, it will likely default to the Vive controls, which makes it almost unplayable on Quest. I used a a Quest 3, and once I played it using Quest Link/Air Link, it recognized my Oculus controls and worked properly.', 'Sadly abandoned, its a pain in the ass to get working well and ultimately not worth it in 2024. Best off just watching a Let''s Play if your interested at all in the world it creates.', 'Mixed', 55.90, 4.47, 0.70);
INSERT INTO reviews VALUES (19290, 579840, 446, 'Really good game, BUT! It shouldn''t advertise itself as one having a Linux native version when it doesn''t. It just downloads the windows version instead.', 'No', 'Very Positive', 84.98, 18.05, 10.67);
INSERT INTO reviews VALUES (19293, 579940, 314, 'Really well-designed version of the board game. I''m impressed with how straightforward and smooth it is. The tooltips on cards make it easier to learn than the physical version too.', 'There''s a lot of praise for this game in physical form so I thought I would give its digital incarnation a try. I found it confusing in terms of how to accomplish things and develop strategies. I played it for 20 minutes before uninstalling it.', 'Very Positive', 91.72, 49.78, 0.20);
INSERT INTO reviews VALUES (19294, 579950, 764, 'I absolutely loved this game, and I plan on playing it again!\n\nalthough this game was taken down, alongside other telltale games in the past, im very thankful to have owned it and played it, the guardians of the galaxy is the only marvel series I liked, anything else I never have had much enjoyment with\n\none thing I do remember about the game was the title screen, & the song "livin thing" it was so catchy and it was amazing!', 'sold a bunch of csgo skins in 2019 for this mid ass game i havent played since', 'Very Positive', 85.21, 11.78, 5.95);
INSERT INTO reviews VALUES (19297, 580040, 503, 'FUN GAME for those who think its bad and it crashes well you have to shut off wifi to play', 'DO NOT BUY \n\nThe game doesn''t run. i cant make it past a min without it crashing, its a shame as this game used to look really good so i gave it a shot. sad to say it did not live up to what i expected (that being able to play the game at all)', 'Mixed', 64.02, 3.52, 0.08);
INSERT INTO reviews VALUES (19299, 580170, 394, 'PRANKING my 50 HOMONCULI INTO THINKING I LOVE THEM (NOT CLICKBAIT) (GONE WRONG)', 'The message for the game is shown at the beginning and the game play loop becomes trivial very fast...the art is nice. \n\nI played for almost 4 hours messing around and collecting each homonculus, finally grew tired and looked up the endings on Youtube. The true ending is kind of wonky, but I get it. I really wish they had just made this a visual novel or something else, felt like it would have been more interesting.\n\nI''d say buy the game at a discount like I did, only bought it because I realize', 'Mostly Positive', 78.93, 13.28, 3.70);
INSERT INTO reviews VALUES (19300, 580200, 1512, 'Well....  It''s so cute.  It''s cozy.  It''s fun.  To a point.  Then it gets a bit over the top in tediousness.  The crafting gets very bogged down in lots of travel and such.  You need an insane amount of stone for instance, so you are always breaking rocks.  I love this kind of thing usually, my favorite game in the universe is Minecraft, but the requirements for making some things just go way beyond what you would expect.  Usually, for instance, you get planks out of logs.  In this game, you hav', 'Loved the vibe of this one but I got seriously motion sick after playing this so much so I psychically couldn''t play this sadly.', 'Very Positive', 81.68, 20.07, 0.52);
INSERT INTO reviews VALUES (19315, 580710, 277, 'TLDR: There is combat but you spend most of your time thinking about logistics, planning the delivery of a few resource types to various units and locations safely. Depend on your preferences that''s either the most boring sounding thing in the world or the game''s main selling point. \n\nCombat: The combat is present and in a sense it is very traditional with various ranged and melee (not literally) units to hit the enemies with percentage based odds of wining or loosing. On the other hand it is ve', 'So this is a fairly decent and fun COIN game--if a bit unrealistic. The developer though, with it''s choices in new titles like the Rhodesian Bush War is really giving off... umm... how do I say this? Basically they are making a game that simulates the white apartheid government of "Rhodesia" (modern day Zimbabwe) and its attempt to preserve apartheid (white minority) rule in Zimbabwe during the "Rhodesian Bush War." \n\nThe memory of "Rhodesia", incidentally, is currently quite popular among many ', 'Mostly Positive', 73.29, 104.27, 108.53);
INSERT INTO reviews VALUES (19316, 580720, 667, 'Trying to achieve 5-stars on every mission is like Dark Souls for Autistic people.', 'Cool concept managing 302193 things at the same time, but if you want to achieve a flawless game, then be prepared to scream at your screen and start over and over and over until you get it absolutely right for those 5 stars. There is no way of slowing the game down, and neither is there a pause function (except for opening the menu). If you want to feel pressure, want to be overwhelmed and frustrated for most of the time, this is for you.', 'Very Positive', 88.01, 14.97, 18.37);
INSERT INTO reviews VALUES (19325, 581030, 134, '⠀', 'Incredibly low quality, generic FPS that is just using Trump in the title as a shallow attempt to garner attention. The only entertainment I got from this was laughing at the description calling the previous game "The Last Hope" a sleeper hit.', 'Mixed', 58.21, 13.03, 4.25);
INSERT INTO reviews VALUES (19335, 581270, 942, 'Perhaps to make life beautiful, not everything needs to be so difficult and complicated.\nIn the end, we might not need as much as we think.\n\n\n지난 날을 되짚으며.', 'The art is beautiful. I did not enjoy the game however. I did not find it intuitive to play and in the end I very much disliked the "old man". I felt sad in the end and frustrated.', 'Very Positive', 86.09, 1.80, 2.15);
INSERT INTO reviews VALUES (19336, 581300, 139, 'Really good game/story.  Great that the story was dark horror but the screen was also too dark so I wished I had control of the candle to see where I was going most of the time.  The controls/camera angles were a bit awkward at times but manageable.  I only checked a walkthrough for the master key positioning but ended up having to figure it myself.  Steam also have Black Mirror 1, 2, and 3 which I have played and also enjoyed.  So I recommend all 4.  Well worth the money.\r\n', 'To anyone who has played the Old Originals: Black Mirror 1-3 DO NOT PLAY THIS. this is not black mirror castle, these are not the gordons, and this is not their story. \nthe Controls are really bad\nanalysing things is just tedious\nthe game is too dark (when you pull up gamma it just gets cloudy?)\nand this is just feeding of a much better point and click series\nnice try with bringing third person controls into a orinially point and click game. Thanks, i hate it, go back please.', 'Mixed', 45.32, 26.68, 0.97);
INSERT INTO reviews VALUES (19338, 581320, 57119, 'First time I played, I was playing the mode where you can''t respawn. I was one of the last members left on my team, camping in a building as I was being surrounded by footsteps, until I hear ''''Yo I know you''re in here, don''t shoot! Let''s have a knife fight.'''' I was skeptical at first, but turned my PTT on and accepted his duel. The following events compiled one of the greatest moments I have had in a multiplayer game ever.\n\nAs I stepped outside, the courtyard was full of terrorists. In front of ', 'This review exists as a form of blackmail. I have played Insurgency for almost 500 hours now, I love this game but recently they have made a change that is ruining a large portion of the fun.\n\nMatches in this game on PC have always supported 14v14 players, but recently they have added cross-play with consoles and are limiting matches to 10v10 because for some reason they don''t trust consoles to handle the extra 8 players. You can disable cross-play, but they have made it the default. So now, onl', 'Very Positive', 86.63, 31.15, 608.43);
INSERT INTO reviews VALUES (19340, 581360, 146, 'For now, there are only 3 chapters available but those are already filled to the brim with gorgeous pixel graphics, beautiful music, and tons of puzzles!\n\nCan''t wait for more! \nPlease support the developers!', 'A game that will fall into development hell just like every other unfinished title and it seriously wasn''t that bad at the time I initially played it.\nAdding that the guy has been very political that it makes it come off more like a Twitter Slacktivist than I don''t know, working on the game?', 'Very Positive', 93.15, 3.40, 3.85);
INSERT INTO reviews VALUES (19347, 581630, 3514, 'I can''t believe the game Is getting an update after all this years.Let''s support this developer because he makes cool games that are fun and they don''t need your whole budget to play this game,so I will highly recommend it! \r\n\r\n', 'game crashes whenver i try to open its not letting me play', 'Very Positive', 86.06, 1.17, 14.35);
INSERT INTO reviews VALUES (19349, 581660, 613, 'before starting this game i had no friends and my wife had recently left me\r\nafter beating it i still have no friends, my wife took the kids and i developed depression but the games still good', 'The original Super Meat Boy was about precision and control. Two things which Forever lacks because it''s an auto-runner.\r\nInstead of dodging hazards as they come, the best course of action is to just throw yourself at every trap until you make it past.\r\nIn the original, you died because you mistimed a jump or didn''t dodge a hazard. Factors which are entirely your fault. Forever doesn''t allow to to dodge hazards effectively because you CAN''T CONTROL YOUR MOVEMENT. In fact, calling them controls i', 'Mixed', 50.90, 26.30, 4.83);
INSERT INTO reviews VALUES (19360, 582010, 109614, 'You are the bad guy, the story makes you out to be a hero, you are not.... 10/10 would kill an innocent creature to make a hat again.', 'I do not recommend this game specifically for coop because they force story quests to be played on single player until all cutscenes have been encountered, and story-based expeditions can only be played solo. The only parts of the game you can reliably play entirely with others are optional side quests. It makes playing through the main game on coop really frustrating, since you have to leave and re-join quests at unknown points because you never know what''s going to trigger a cutscene. It compl', 'Very Positive', 92.29, 230.22, 143.67);
INSERT INTO reviews VALUES (19364, 582160, 32913, 'The game is very good but somehow it is freezing after windows updating to 24H2 version. There is no fix as of now', 'Fun game but DO NOT BUY!!! The game crashes on Windows 11 24H2 update and Ubisoft''s offical statement that this game is a legacy title and there won''t be any update/fix so it will likely never be playable again if you have Windows 11 from 24H2 and onwards.', 'Very Positive', 83.85, 66.82, 6.48);
INSERT INTO reviews VALUES (19369, 582270, 2234, '"When God sings with his creations, will a turtle not be part of the choir?"', ' Interesting concept, but bad as a game. \r\n\r\nThis is a game whose main selling point is how much stuff is in it. There''s more than a thousand things in it, and you can be almost all of them, as the store page says. That is all true.\r\nHowever, in execution... it''s a lot less interesting than it sounds.\r\nThe philosophy this game is based on is that all in the universe is made of the same stuff, and so, everything is everything. But the way this is executed in the game is just disappointing for the', 'Very Positive', 83.97, 1.10, 4.07);
INSERT INTO reviews VALUES (19371, 582330, 385, 'this game is really addicting... i mean, even now when i write this im playing the game. it fun and progress is addicting. really hope this game makes a comeback because it deserves more recognition... \r\nto sum up, 9.4/10 game.', 'maybe im doing something completely wrong but ive got pretty far but every charactersyou fight up to level 8 just dodges everything im not a fan of the comedic side to it maybe its a reference to something its fun for all about 10 mins until you realise\n', 'Very Positive', 89.61, 50.85, 8.43);
INSERT INTO reviews VALUES (19380, 582500, 1065, 'Played the game with the wife. Had a fight because I lost my temper. We eventually beat the game. Might have affected the future of our marriage, but had fun regardless. 10/10 would recommend.', 'Did not enjoy the game, sorry', 'Very Positive', 89.39, 5.23, 1.02);
INSERT INTO reviews VALUES (19382, 582550, 2578, 'If you put in your heart and time, whatever you draw will be valued. Isn''t that cool and cute?\n정성과 시간을 쏟는다면, 무엇을 그리든 가치있게 평가됩니다. 그런 점이 멋지고 귀엽지 않나요?', 'made so many paintings- spent a good 10 minutes on each and nobody, like nobody would but anything', 'Very Positive', 87.35, 26.00, 3.65);
INSERT INTO reviews VALUES (19383, 582560, 250, 'An amazing game that I''m shocked more people don''t know about. The main mechanic of the game is so interesting to play around with and the many perspectives and stories of each character are well played out. I would recommend this game to anyone who loves a good mystery.', 'It seems like a good game based on other reviews, but unfortunately, I was unable to play it due to the voices not working.\n\nIf you do buy the game, I suggest trying to play the first 10 minutes and checking if the NPC voices are working. If they aren''t, do not play the game for more than 2 hours, as you will be less likely to get a refund (I spent 5 hours trying to figure out the audio issues, but was unable to resolve it).\n\nAnd the company Tequila Works is no longer running, so there is no way', 'Very Positive', 92.80, 10.00, 4.52);
INSERT INTO reviews VALUES (19387, 582810, 105, 'Awesome Metal Detecting\n\nHas a total of 5 trading cards.', 'This game is just awful', 'Mixed', 56.19, 2.27, 5.93);
INSERT INTO reviews VALUES (19392, 582890, 142, 'Absolutely Amazing cannot wait for the third one to come out', 'its okay, i dont like it nearly as much as the first, the atmosphere isnt as rich, the gunplay feels worse, the story of this sequel sort of goes to shit and has so few interactions with characters and enemies that it isnt even remotely compelling.', 'Very Positive', 83.80, 1.55, 1.53);
INSERT INTO reviews VALUES (19399, 583040, 105, 'I wouldn''t actually recommend this game to people who are not fans of this series already; this shouldn''t be your first princess maker game. Alot of the negative reviews are centered around pretty unnecessary things like some artwork being censored or the game being badly translated, however those dont affect the core gameplay at all. (also the censorship was nudity of your daughter? thats an extremely weird thing to get upset about) if you''ve played other princess maker games id recommend this ', 'This port to pc is totally broken and tends to crash. Get one from the high seas, those are more stable.', 'Mixed', 65.71, 12.37, 4.68);
INSERT INTO reviews VALUES (19401, 583090, 121, 'The lack of dialogue tags supplements the theme of dreams and memories; vague, half-forgotten and murky things, mingling and entangling with the past, future, and present, unsure of what is what, in an ever-changing kaleidoscopic shape. Don''t worry too much about "who exactly is saying what." If it''s not stated then it''s something that is not necessary.\n\nAnother point, edit: SeaBed is interesting in part because it presents opaquely fluctuating motions that accelerate until reaching an omitted c', 'Nice art and music, but it had the most abysmal story pacing I''ve ever seen. The game genuinely could have been reduced to like 5% of its length and lost nothing because so much of it was mundane filler. Which also makes it hard to be willing to pay attention and connect the dots when something subtly important does get mixed in. I only played this at night because it always managed to put me right to sleep, and I only got to the end because the very long prologue got me stuck in a sunk-cost min', 'Very Positive', 94.21, 66.33, 22.08);
INSERT INTO reviews VALUES (19407, 583270, 308, 'It''s 3am and my depression just got cured by the massive release of dopamine after finally solving Andromeda 14', 'The game is cute and has trains so I wanted to try it.\n\nHowever, I found the puzzles either simple and straightforward or incredibly frustrating. At no point did I feel clever for figuring out a solution; I was just glad that I finally got to the permutation in my brute-forcing that was the answer. There''s a fair chance that I was just in the wrong mindset or whatever, but I could not figure out any way to intuit or plan out each solution besides simply trying it, seeing if it worked and when it', 'Very Positive', 93.83, 25.43, 4.03);
INSERT INTO reviews VALUES (19408, 583470, 1746, 'Extremely underrated. People who say it''s Super Meat Boy but worse deserve to burn in Golgotha', 'I really wanted to like this game, but I can''t help it. It''s simply not for me, and if you''re reading this, chances are it''s probably not for you either. There is plenty of positives about it, chief among them being the amazing soundtrack, but ultimately it''s a game that hates you. The difficulty isn''t about giving you a challenge to overcome, it''s about frustrating and trolling you.\nIf what you''re looking for in a game is an exercise in frustration, then this is the one for you. It certainly wa', 'Very Positive', 92.50, 153.23, 4.93);
INSERT INTO reviews VALUES (19417, 583760, 295, '\nButton mashing rhythm game that is quite good. Music is nice to listen to. It uses the whole keyboard so you can train your typing skills to become master of typing. Recommended if you like rhythm games with some challenge.\n', 'It was a nice and interesting game with music but apparently the price has been hiked and hiked since I bought it years ago and therefore I do not recommend it, way too expensive, it was originally 1 dollar/euro or so and has been steadily hiked up in price.\r\n\r\nI would say maybe with 90% discount or so, consider, but even then...\r\n\r\nYou can check price history on steamdb if you doubt me.\r\n\r\n(This goes for both slash it 1 and 2)', 'Very Positive', 88.14, 6.98, 44.25);
INSERT INTO reviews VALUES (19423, 583930, 253, 'I''d just like to take the opportunity to point out that, when I finally got fed up with the appallingly low drop rate for eggs which made the last two achievements (for completing the bestiary) a tiresome chore to complete, I complained about it on the forum. Rather than the couple of offhand complaints from other players telling me to stop whining that I''d expected, the developer themselves responded within half an hour to agree that I had a point, and within an hour a patch had been issued to ', 'There was an update (2.0.24) and then it stopped working. Great update!!!', 'Very Positive', 87.75, 29.05, 30.97);
INSERT INTO reviews VALUES (19424, 583950, 8088, 'Every night I cry myself to sleep thinking about what might have been', 'So whats the deal with airline food?', 'Mixed', 56.94, 36.70, 149.60);
INSERT INTO reviews VALUES (19433, 584370, 118, 'I played this on mobile years ago and now playing it on pc and its so much better now. although i wish that things would collapse on their own rather than upgrading but im glad there isnt any micro transactions anymore', 'Will legit soft-lock you if you don''t focus on the house perk\r\n\r\nNot a problem in the mobile version though', 'Mixed', 69.49, 7.58, 4.05);
INSERT INTO reviews VALUES (19434, 584400, 13136, 'Mania, also known as manic syndrome, is a psychiatric behavioral syndrome defined as a state of abnormally elevated arousal, affect, and energy level. During a manic episode, an individual will experience rapidly changing emotions and moods, highly influenced by surrounding stimuli.', 'I adore this game. The sprites are wonderful,the music is catchy and stylish to the point you just want to sit and listen,the levels (most of them) are so well thought out and are very very fun. There is just a few problems that make this game a headache despite it possibly being the best 2D sonic game.\r\n\r\nThe bosses are terrible. Mostly all of them. On top of that if you run out of lives at ACT 2 you have to go ALL the way back through ACT 1 and do EVERYTHING again. Its so infuriating. Losing a', 'Very Positive', 93.29, 10.60, 11.85);
INSERT INTO reviews VALUES (19436, 584640, 218, 'i really punched a hole in my wall because of a game called super chicken jumper.', 'Só comprei esse jogo por causa que é um jogo do Gemaplys. Achei que seria algo divertido, mas não é. É um jogo mal-feito. A programação do jogo é toda esquisita. A história e os diálogos, assim como os personagens, nem merecem comentários. O modo desafio tem muita falta de criatividade. Tem certas coisas na arte do jogo que parecem que só foram adicionadas lá na completa ignorância, nem combina com o resto da arte do jogo.\n\nSinceramente, decepcionado. Esperava mais de alguém que eu achava que en', 'Very Positive', 91.28, 1.70, 8.05);
INSERT INTO reviews VALUES (19444, 584930, 201, 'Really entertaining VR game! It''s short, but every moment of it is fun. What I like the most is how it can run on any PC, that''s rare for this type of game. I found the few combat encounters there are  thrilling and kinda scary even. In conclusion, anyone can play and have fun! Unless you don''t like puzzles...', 'This game is an hour long and is worth maybe $5 at most. It is an interesting concept, but that is all it can be with an hour play length and no time to develop into something greater.\n\nThe VR support is weak relying on you using the triggers for everything, no grip buttons; and you have to teleport to move, no smooth locomotion.\n\nThe puzzles range from brain dead to infuriating. Making me want to look up an answer for the vague backwards logic their world was operating under.\n\nI would love to s', 'Very Positive', 94.53, 1.78, 1.42);
INSERT INTO reviews VALUES (19446, 584980, 1668, 'If you ever feel like punching your monitor, this game is perfect for you. There is no skip option so you have to listen to the same lines multiple times for perfect achievement. I am pretty mad right now and i hope you also buy this game and go through the same suffering like me.', 'The story was boring and a lot of the choices are just giving you the illusion of choice when they say choices matter.\nLike for example, when I chose to leave May-Ling and go home the game forces you to go back and help her.', 'Very Positive', 86.51, 8.82, 1.30);
INSERT INTO reviews VALUES (19447, 584990, 165, 'This game is very clever with its plot, but it is undermined somewhat by the english characters speak. Everyone, mostly scientists, talk like teen boys. Although that sounds pretty annoying, it mostly didn''t bother me because the game is really good. \r\n\r\nThe only other complaint was forcing inventory to the "I" key which just seems like a really weird decision. Yeah, the word "inventory" starts with i, but it would have been much less of a pain to play if I could just press space bar, tab, X or ', 'I would love to give this game thumbs up but unfortunately I will not give because thanks to not implementing steam cloud.\n\nI lost my progress on old pc and i refuse to start over.', 'Very Positive', 82.42, 5.35, 1.47);
INSERT INTO reviews VALUES (19450, 585080, 121, 'e', 'I cannot get this game to run for more than 30 seconds. Can''t even get a loadout setup. I''ve reinstalled it. I''ve verified the files. Absolute trash. Waste of $42. I really think steam should refund all of us.', 'Mixed', 52.89, 8.92, 10.15);
INSERT INTO reviews VALUES (19452, 585180, 287, 'I''m a grown ass manly man... and I cried a little. A very pleasant experience. The main storyline can be finished in about 4 hours, takes about twice that much to figure out all story branches. No issues, runs on a potato. Highly recommended for anyone who likes reading.', 'I wanted to like this game, but there is a bug with the save function. Sometimes, you can''t save. Sometimes, you can''t delete saves to make new ones. Sometimes, you can''t go back to gameplay from the save/load menu. Sometimes, hitting delete on a save will instead load it. It''s a real shame because what I played of the game was pretty cool, but a bug this bad can''t be overlooked.\n\nEDIT: Since initially writing this review, the creator says that the saving feature has been fixed, but I refunded t', 'Overwhelmingly Positive', 98.61, 8.38, 7.52);
INSERT INTO reviews VALUES (19453, 585190, 105, 'A better version of Gang Beasts! Less janky with better control.', 'The game is really good but its false advertisement. It says up to 16 players but max i can get is 5 (1 keyboard 4 controllers) with remote play and local play, we even tried a third party software similar to remote play, we tried xinput on, off and automatic nothing works until this is fixed i cant give a good rating', 'Very Positive', 80.95, 4.13, 3.53);
INSERT INTO reviews VALUES (19459, 585420, 16166, 'This game is really fun on its own, it kinda sucks that some stuff like larger plane engines and sails are locked behind a paywall, but this game is still good.', 'I do really like this game but the fact that a substantial amount of content is hidden behind DLCs does become annoying. It would be better if the DLCs were cheaper but I think they are overpriced for what they are as of now.', 'Very Positive', 93.67, 28.95, 94.57);
INSERT INTO reviews VALUES (19461, 585450, 762, 'Underrated. This should have much larger fan base. I always wanted something in between Diablo 4 and such as Achilles: Legends Untold. This is exactly it, with some interesting puzzles and well thought out level designs. It is Souls-like because you have fewer but stronger monsters (compared to Diablo) where you need a bit of combat tactics similar to Achilles. Item drops/looting are much less than Diablo but more than Achilles, I don''t need to stare at inventory whole day but still fun collecti', 'Diablo-like "successor" of Heretic Kingdoms.\nConstant backtracking simulator through already emptied maps.', 'Mostly Positive', 78.74, 30.40, 19.80);
INSERT INTO reviews VALUES (19463, 585550, 684, 'Thank you for making the trans flag banner 🔥🔥🔥', 'One of the worst games i''ve ever played. Such a nothing experience for the sole purpose of owning "the sjws" or whatever. Stay woke instead <3 I am trans and proud', 'Mostly Positive', 78.51, 2.05, 0.45);
INSERT INTO reviews VALUES (19465, 585690, 599, 'this is a pretty good game tbh i had a really good time playing this for 31.4 hours. i really loved the artstyle it was super cool and uh yeah i loved when the box did the thing it like jumped out and shit and it was wild', 'slippery controls and bad input', 'Mixed', 64.77, 31.38, 9.33);
INSERT INTO reviews VALUES (19466, 585710, 644, 'Cool roguelike, but short, many items give debuffs, characters from the community workshop are too strong.', 'I have almost 50 hours in this game and a big fan of this genre but i would not recommend this game. \nOnly if on a huge sale.\nThis game is basically about collecting punishments on your run with absolutely 0 reward.  Keys are absolutely pointless, secret rooms have no good rewards either.  Coins become useless if you have more than 15,  all the machines you can find are useless , hp machine that drops more punishments , coin machine that drops hp...  weapons are not good either, there are maybe ', 'Very Positive', 83.39, 1.75, 53.92);
INSERT INTO reviews VALUES (19472, 585830, 168, 'very good reccomanded', 'Easy achievement spam.', 'Mixed', 67.86, 0.65, 4.23);
INSERT INTO reviews VALUES (19473, 585840, 503, 'https://steamcommunity.com/sharedfiles/filedetails/?id=1337350704\nhttps://steamcommunity.com/sharedfiles/filedetails/?id=1808809861\nhttps://steamcommunity.com/sharedfiles/filedetails/?id=1341301370', 'I didn''t like the game not because it''s too short but because it didn''t provide anything good.\n\nIt''s like an rpg where the first quest is to speak to everyone in the town, then leave to start your journey; except here once you leave, the game ends.', 'Very Positive', 83.30, 1.37, 2.12);
INSERT INTO reviews VALUES (19475, 585890, 340, 'Somehow missed the fact there were no choices from the store page. This, plus the clueless MC and occasionally obvious foreshadowing made me want to punch a large hole in my computer and also rip my skin off.\n\nOther than this, overall art and writing are on point! \n\nWorth playing if you hate yourself or if you like kitty cats :3', 'This game is gross, Once I got to the "twist" I was done and uninstalled and deleted it from my steam library. Frankly I''m surprised it hasn''t been removed by steam. I should have asked for my money back but did not want to deal with the company.', 'Very Positive', 94.12, 3.05, 4.22);
INSERT INTO reviews VALUES (19476, 585900, 731, 'farm game', 'Empty shell of a Harvest Moon game.', 'Mostly Positive', 76.47, 29.33, 2.40);
INSERT INTO reviews VALUES (19477, 585910, 191, 'ME ENCANTOOOO !!! feliciten a los desarrolladores, lo han mejorado muchisimo desde que lo jugue !! los detalles del juego son espectaculares, !!! nuevos personajes armas !! banda sonora 10!!!!', 'Not sure why it''s so expensive for what it is. Basically a Nam-1975 ripoff with a SciFi Western aesthetic. Controls are clunky and I could not get the controller to work. Remapped keys with Steam input worked OK though, It''s fun enough but really hard to recommend at $20+ AUD when you may as well play Nam-1975 on emulator; and it looks and plays better.', 'Very Positive', 86.91, 0.43, 0.77);
INSERT INTO reviews VALUES (19487, 586140, 4315, 'as far as i understand it, blazblue games are about boobs. \n\nthats it.\n\ni love boobs.', 'dead game with the worst balance, with the most annoying system mechanics, with the most hard execution, with the worst player base, with the worst players who''ve been playing the same game for 20 years', 'Overwhelmingly Positive', 95.67, 5.85, 502.88);
INSERT INTO reviews VALUES (19491, 586200, 1175, 'I''m not a young man, but I was when I used to play Street Fighter in the arcades. Firing this up and using a fighting stick while sitting in a gaming chair might not be the same as getting absolutely hosed in an arcade that smelt like armpit, but it''s close enough for me.', '7 frames of delay? Just play Fightcade instead, 1,000 talented players active every day', 'Mixed', 69.11, 10.78, 18.98);
INSERT INTO reviews VALUES (19492, 586210, 430, 'If this software works on your headset and Computer it is Amazing, I love it.\nps I''m using Quest 2', 'Doesn''t work any more. It was fine for the OG Vive back when Beat Saber JUST came out, but I think that might''ve been around the last time it was updated. OVR Toolkit is your friend these days. Wish I could get my money back for this one.', 'Mixed', 65.58, 16.65, 4.03);
INSERT INTO reviews VALUES (19499, 586350, 203, 'At first, I didn’t know what was happening. One blink, and the game was over. But as time passed, I began to transcend my human form, shedding the limits of my speed. As my divine body emerged from the light, my brain stopped processing information. I was dodging this bullet hell purely on instinct.\n\nI blacked out after 100 straight hours of transcending the limits of humanity, yet my body kept playing UBERMOSH:WRAITH on its own.\n\nI have reached a state close to Ultra Instinct. In the coming day', '.', 'Very Positive', 92.61, 945.30, 0.38);
INSERT INTO reviews VALUES (19518, 586750, 357, 'While I would have liked a continuation from Sonny 2 (what happened to the Felicity and Roald!? ;_;) this has a lot of charm. The improved artwork and extra ability trees are nice, and I think it was a cool re-imagining of the story.\r\n\r\nMy main complaint (other than that is retconned the first two games) is probably that it removed attack animations, which was a step back and made combat look kinda silly.\r\n\r\nOtherwise it was pretty fun and I would say definitely worth playing.', 'After 15 years of development they''ve somehow managed to make this worse than the original flash game. Expect crashes.', 'Mixed', 56.58, 63.87, 1.12);
INSERT INTO reviews VALUES (19522, 586880, 165, 'Classic metroidvania goodness, the gameplay is very simple, but very fun as well. Because of my dumbness i may have complicated the game for myself a little bit ( i always destroy those healing robot, didn''t realize they can heal you until very late in the game), A good and short game for anyone looking for some MSX or NES gameplay.', 'As a massive fan of Ghost 1.0 i was excited to jump into an 8bit version of that game, BUT i have to admit i hatebeat this game!  I basically was stubborn and forced myself to finish the game, out of sheer dumbness.  Im an 80s kid, and i still play alot of retro games constantly, and i love Metroidvanias.  However the difficulty of this game was akin to the NES era.  For the price its fair i guess, but the difficulty is not based off combat, its based of the unfairness of the game design.  Blind', 'Very Positive', 92.73, 5.40, 4.70);
INSERT INTO reviews VALUES (19526, 586950, 317, 'More than your standard hack and slack.  One of the few very good VR games.\n\nYou have to learn gestures to cast spell rather than than just press buttons.  Different options for the levels to add replay-ability and the narrator adds humour.  And the level increments offer challenges.', 'I thought that a game called enhanced edition would be more supporting.\n\nCouldn''t get movement to work with Quest 3. Very disappointing.', 'Mostly Positive', 73.82, 3.28, 0.08);
INSERT INTO reviews VALUES (19527, 586960, 158, 'I bought it for 1.01 euros, on sale. For 16 euros it is not worth it. The game is repetitive, some levels are very difficult, the main character seems to have a stroke when he is in the air. But, it''s a pretty quick game to finish for achievements.', '$10.99 for this ♥♥♥♥..?\ndont make me laugh\n', 'Mostly Positive', 79.11, 1.18, 4.55);
INSERT INTO reviews VALUES (19530, 587000, 499, 'With Trump reelected, the message "in 2024 humanity has the power to bomb itself back to the stone age" really resonates with reality.\r\n\r\nSociety is no longer moving forward, it''s living on borrowed time.', 'they locked content with signing up to a news letter. so i get a demo because i don''t wont to sign up for a fucking bullshit news letter  . i was  liking the game untell this. why would i do that for you guys to sell my data and send me emails for what. go fuck yourself.', 'Mostly Positive', 73.55, 33.43, 4.90);
INSERT INTO reviews VALUES (19533, 587100, 398, 'you should play this game if you love old jrpg games\nalso i hope falcom would remaster ys v kelfin', 'why is the ys seven.exe file detected as virus by kaspersky??', 'Very Positive', 90.70, 53.22, 26.03);
INSERT INTO reviews VALUES (19534, 587110, 481, 'Japan''s infamous amnesiac is at it again on yet another adventure. This dude really needs to stop doing drugs and forgetting everything. The story is more or less the same as any other Ys adventure and the combat is exactly what you expect from the series. \n\nMaybe some see the repetitive nature of these games as a bad thing but I like that there are some series you can count on for sticking to what they do best. If you enjoy action RPGs then you will almost certainly love this!', 'not enjoyable previous 3 games are far better this one doesn''t feel like its even the same series was uninterested most of the time playing this skip and save your time', 'Very Positive', 92.93, 37.50, 27.93);
INSERT INTO reviews VALUES (19537, 587220, 1510, 'This game is incredible! So fun! Once you get the feel for how to jet around it''s such a blast.', 'I thought this game would be perfect for someone like me, someone who doesn''t get motion sick easily. I really wanted to give this game a chance but the constant clipping through walls and floors at high speed did it in for me. This is kind of an issue when the game advertises itself as being able to go as fast as you want to. The game''s fun, don''t get me wrong but, it''s hard to look over this major issue.\n\nMaybe I''ll try it again in the future but until this is fixed, I cannot recommend this ga', 'Overwhelmingly Positive', 96.16, 1.63, 0.65);
INSERT INTO reviews VALUES (19538, 587260, 711, 'Imagine Persona + YS merged together and you get this game! very fun and enjoyable game, i recommend it!', 'Like watching a really trash anime.\r\n\r\nLike, super trash anime. The irredeemable kind that just use all the anime tropes unironically, where characters speaks by turning their back on their conversation partners, close their eyes and talk, as if they are super cool or something.\r\n\r\nIt is so cringe. The story is a nothing burger. The characters are walking tropes, and not in a good way.', 'Very Positive', 88.19, 39.67, 60.10);
INSERT INTO reviews VALUES (19544, 587420, 203, 'No micro transactions, dlc''s and permanent online service. Just a funny little game with ridiculous difficulty and humor. What a shame.', '\r\nPush your shopping cart and try to land on designated spot. Physics based gameplay makes it a bit fun and each run will give some random result, but still the game is pretty shallow. Check it out if you like those physics based games. Anyways, Slackers Carts of Glory is your glorious alternative for this one.\r\n', 'Mostly Positive', 71.92, 10.93, 2.97);
INSERT INTO reviews VALUES (19545, 587430, 1629, 'It''s cool, but very short. Aimed at seated VR only, but there''s one spot in the final level where you have to stand up to press buttons. There are a couple of other obtuse puzzle steps, but other than that it''s good.\r\n\r\nI''d recommend it on a sale.', 'I got the "Complete all missions" achievement, but then there''s more missions? What the hell is that? Is anyone in charge of this game? Get it together mr. Schell', 'Overwhelmingly Positive', 95.09, 4.00, 2.78);
INSERT INTO reviews VALUES (19547, 587450, 1032, 'Devs got screwed over by their old manager, now they''re back to work on this amazing game with great potential!', 'I will never, ever forgive the former manager who embezzled 75K and essentially ruined what could have been an amazing game. I *genuinely* hope someone finds their info one day and plasters it all over the internet to ensure they never get another job ever again.', 'Mixed', 60.95, 0.57, 64.98);
INSERT INTO reviews VALUES (19549, 587470, 273, 'Easily one of the coolest VR experiences out there. Not much to do but it''s visually really interesting and cool and it syncs to music. Highly recommend to anyone with a VR who wants a new experience.', 'Game no longer works on Virtual Desktop + SteamVR + Oculus Quest 2; Controllers are stuck in the floor. It was cool when it worked though. Tried changing controller bindings and that didn''t seem to work either.', 'Overwhelmingly Positive', 95.97, 3.00, 0.13);
INSERT INTO reviews VALUES (19552, 587520, 1383, 'Good coop dungeon crawler indeed.\n\nAs some people mentioned: Early zones are a bit old-ish looking.\nThey get progressively better and better and there are alot of zones to go through.\nI was impressed by the graphics later on to the point where they rival modern games in their detail. Not joking, you will understand once you get to the Crystals in the Frozen cave.', 'Their discord has confirmed the game has been abandoned by the Devs, avoid it at this point unless you want to play an unfinished buggy mess.', 'Mostly Positive', 75.20, 22.98, 14.62);
INSERT INTO reviews VALUES (19555, 587580, 213, 'I''m impressed by the large scale of the environment, where you can get almost any viewpoint, and also by the different weather and times of day. If you build/grow a few things just right, it''s an experience where you don''t mind just sitting in one place for a few minutes and enjoying the atmosphere. The ground plant textures being very 2D is the only complaint here, which breaks some of the immersion. Also, the free walking mode needs a speed select option, it''s a little too fast. For a good pri', 'For the time of it''s release it was ok, but for today''s standards it is very dated, both graphically and the whole experience.', 'Very Positive', 83.10, 0.38, 1.97);
INSERT INTO reviews VALUES (19566, 588030, 4964, 'Started watching Squirrels YouTube series about Derail Valley. Next thing i know I''m hours deep into this game. Absolutely addicted! worth every penny! 10/10 would recommend.', 'This is probably the most fun train sim I''ve tried, however...\n\nSome of the sandbox content is locked behind hours of career grind, despite community''s request to make it available out of the box. The developer tries to justify it with unreasonable arguments such as\n "players would get bored quickly" or "it would be overwhelming for new players" \n\nLocking the content of the sandbox experience is exactly the reason I lost motivation and reason to play the game.', 'Overwhelmingly Positive', 96.11, 46.93, 9.03);
INSERT INTO reviews VALUES (19567, 588040, 246, 'The negative reviews are weird. The game has already put out warnings regarding its content but those people buy anyways and proceed to complain about what has been warned? It''s like buying a cheese pizza then complain there is cheese on it. \n\nThat aside, this game is one-of-a-kind and I enjoyed the story-telling very much despite there being some confusion at various sections. Please pay no mind to the negative reviews and give this game a chance.', 'Okay,so, this game is... interesting to say the least. I''m personally liking it ...mostly, but I can''t in good faith recommend it. Do note this comes from someone who has not finished the game though, but most of my complaints are big enough to still need mentioning.\n\nFirst of all, the content warnings gives this game a disservice, to not spoil much, if you can think of an awful thing that can happen, it''s probably in the game  in some way or another, on its most extreme version as well most tim', 'Very Positive', 85.77, 9.57, 6.97);
INSERT INTO reviews VALUES (19570, 588110, 142, 'One Dog Story Review: Heartwarming Adventure\n\n\nOverview\n\nOne Dog Story is a charming adventure game developed by Big Way Games. Released in 2021, this indie gem shines with:\n\n\nGameplay\n\n- Explore vibrant worlds\n- Solve puzzles\n- Interact with adorable creatures\n- Uncover the dog''s story\n\n\nPros\n\n\n- Emotional storytelling\n- Vibrant hand-drawn graphics\n- Immersive soundtrack\n- Challenging puzzles\n\n\nCons\n\n\n- Short gameplay (4-6 hours)\n- Limited character customization\n- Some players report minor bug', 'Video review:\nhttps://www.youtube.com/watch?v=877DDS5K9mw\n\nNot crazy about One Dog Story. Poor story, bad structure, and tons of glitches, some of which made me have to quit to menu to continue. Plus, the publisher has engaged in some shady stuff that I go into more detail about in my video. If you want more info in a different format, then here''s another Steam review by a guy named Dravvad did his own deep dive.\n\nDravvad''s post:\nhttps://steamcommunity.com/id/Dravvad/recommended/588110/', 'Mostly Positive', 71.13, 10.05, 15.83);
INSERT INTO reviews VALUES (19573, 588160, 180, 'Good pizza business management game with cute graphic. Making/adding the ingredients for the pizza can be fun thing to do.', 'A shame such a good franchise was ruined.', 'Mixed', 48.33, 1.47, 9.05);
INSERT INTO reviews VALUES (19575, 588190, 611, 'simple and effective, far better and user friendly than the new game', 'I have followed the FAA guidelines for traffic separation, everything and keep getting hit with penalties.  Kind of getting frustrated as five mile in trail spacing is more than enough.  Not happy, no explanation as to what, were when or why.  Just points lost.  Kind of seems like a bug to me.', 'Mixed', 68.25, 16.55, 149.92);
INSERT INTO reviews VALUES (19591, 588690, 301, 'Pretty nice to play!\r\n(dont go for all of the achievements, i lost my mind doing that)', 'It''s like the Papers, Please of the afterlife. If you''re into that, you''ll find some enjoyment here because it''s well done. That''s not really my thing though. And while it''s cool that it''s filled with nods to tv, movies, pop culture stuff, you''re on a timer. So if you take the time to acknowledge those things, you''re going to be graded poorly at the end of the level.', 'Very Positive', 90.03, 34.67, 2.08);
INSERT INTO reviews VALUES (19594, 588730, 433, 'Absolutely amazing - don''t come in trying to get a 100% Good/Bad run at first, it''s better to do everything first go around and to have a balance between the amazingly happy endings and the amazingly dark bad endings.\n\nWorth the price!\n\n(Tip: Most reviews say there is too many anime questions. You can reduce the likelihood of anime questions in the settings menu!!)', 'Way too much anime & visual novels questions !\n\nI don''t know what instrument random kawai girl one is playing on the first epiode of season 1 of random anime about random things !', 'Very Positive', 94.23, 2.48, 6.30);
INSERT INTO reviews VALUES (19601, 588950, 1095, 'If you''ve ever played shareware stuff like "Castle of the Winds," messed around with old operating systems, or just enjoyed a lo-fi grand fantasy this is a fun and relaxing game to play. At least until you run into enemies that open multiple popups and your aging, weak reflexes can''t carry you through. \n\nThe music is largely made by Landon Podbielski of Duck Game and you should buy both this and Duck Game. Duck Game is life, Duck Game is love.', 'Kingsway is an RPG with a really cool aesthetic. Everything has it''s own pop up window, whether it''s your character screen, your inventory or the enemy you''re fighting. Ultimately you are just trying to get from the left side of the map to the right side, completing quests and dungeons on the way, hoping that you will be strong enough to beat the final boss when you arrive. Each individual run is relatively short at 1-2 hours, but you''re encouraged to play with lots of different classes and achi', 'Very Positive', 91.42, 11.52, 5.48);
INSERT INTO reviews VALUES (19602, 588970, 316, 'profile simulator', ' i cant delete save ;-; ', 'Very Positive', 89.24, 0.87, 2.57);
INSERT INTO reviews VALUES (19614, 589200, 267, 'The game is unplayable because it''s %#@&ing terrifying', 'After being so excited to play this and managing to fix all the issues I had with my PC and VR, I am disappointed. This isn''t what I expected or really wanted. \n\nI was expecting more Amnesia: The Dark Descent type deal, a fully fledged story wasn''t a must, this game has some interesting lore, but the gameplay is just repetitive. There is no real way to "juke" the monsters, if I could use my coins for luring the monsters away instead of just some very light lore. Its just walk around, see monster', 'Very Positive', 94.38, 0.15, 1.60);
INSERT INTO reviews VALUES (19619, 589290, 15818, 'Playing as a French soldier, someone was mic spamming loud African tribal music. People followed him to a fireplace and formed a circle, dancing about to the African drum music. Meanwhile the British took full control of the map, tribal dancing continued unabated. \n\nWith only a couple minutes to go, the micspammer then started playing Native American war dance music and led us all on a charge. The British players , by now all bored and complacent as there was noone to fight, were overwhelmed by ', 'This is a great game, ruined by an insufferable community. People in game chat are painfully unfunny, and spam soundboard bytes over and over and over again. You''re not funny, go back to discord.', 'Very Positive', 90.72, 22.28, 3.92);
INSERT INTO reviews VALUES (19622, 589360, 4137, 'Good game, just feel like I have out grown it.  Like it is for tweens more than anyone else.  I really wanted to like it, but it feels more like I''m forcing myself to finish it, rather than enjoy the experience.  The thing that really bothers me is the whole basis of helping some adolescent kid make a kingdom and unite the world.  To me, it''s unrealistic and would never happen in that world with such vast differences with races.  It''s too "kiddy" for me.  Everything from the art, gameplay, and w', 'This game is not even close to the quality of the first installment. The story is bland, the combat is repetitive, and it is the worst example of artificial difficulty I have ever experienced. I uninstalled it right after getting the platinum - which I did by basically spamming two spells over and over again', 'Very Positive', 82.74, 20.08, 120.47);
INSERT INTO reviews VALUES (19631, 589500, 440, 'A great game, but if it''s intriguing to you at all or seems like the kind of thing you''d like, I recommend just going ahead and buying Treasure Trove. It includes this game in a bundle with 4 other Shovel Knight games, 1 of which isn''t sold separately nor offered in the standalone bundle (Plague of Shadows). It often goes on sale for about $20.\n\nAs for the game itself, Shovel Knight: Shovel of Hope is a platformer with simple and succinct, but also surprisingly heartfelt and humorous, writing, c', 'poopookaka', 'Very Positive', 93.18, 28.65, 8.37);
INSERT INTO reviews VALUES (19632, 589510, 239, 'You can rail grind... 10/10 \r\n\r\nBeing serious tho, this is an amazing game would definitely recommend it (:', 'Not great.', 'Very Positive', 94.14, 11.82, 0.22);
INSERT INTO reviews VALUES (19633, 589530, 547, 'Sometimes you have to indulge yourself and replay that trash otome game from your early teens.', 'I do not recommend buying either this game till it is confirmed that they fix the crashing issue with the game. First time you open the game it is fine no issue but the second time you open it all you get is the black screen then it time''s out. Unfortunatly i did not know about steams refund policy so i can no longer get a refund so unless there is a confirmed fix for this issue i would suggest not getting the game.', 'Very Positive', 91.41, 34.70, 31.50);
INSERT INTO reviews VALUES (19634, 589590, 6533, 'this game has rapists, druggies, alcoholics, murderers, psychopaths, Mrs. JigglyTits - there''s something for every ones taste so why wouldn''t u play :)', 'I hate children', 'Overwhelmingly Positive', 96.98, 4.25, 4.00);
INSERT INTO reviews VALUES (19641, 589760, 403, 'What a very fun game. if you like arcade racing games and enjoy making cars go faster, this game is a must have.', 'I''m not playing a game with arrow keys like it''s 2001. I just want a car lifestyle sim game that works, besides MSC.', 'Very Positive', 83.37, 59.70, 0.08);
INSERT INTO reviews VALUES (19643, 589780, 3051, 'I pirated this game 4 years ago when i had no money to buy it and things weren''t great overall; 4 years later and i can say much has changed, but i still think this is a beautiful and introspective story about people and personal values; and fun gameplay with more outcomes than your typical telltale-type game.\n\n11/10 would buy again', 'This game wasn''t for me. I like the art and setting, but the game is painfully slow. It''s essentially a visual novel except you can only read one sentence at a time. Maybe I''m a fast reader, but this was excruciating to wait for the next dialogue bubble in a game where 90% of the gameplay is dialogue bubbles. The other 10% is half-baked papas pizzeria style minigames (which are kind of charming but a little awkward to play). The game ends with more questions than answers, which is normally a goo', 'Very Positive', 91.45, 3.70, 3.03);
INSERT INTO reviews VALUES (19645, 589860, 118, 'SoulSet is so good, I personally loved the story and the characters. I usually only like maybe one or two characters when I play a romance type game but I loved everyone. I really liked that you could have a friend route and weren''t forced to have a romance ending with the characters, its more flexibility for people who fancy certain types of characters. I thought the story was different and entertaining I like the way the story played out and I was so happy to see it all come together. This is ', 'Transphobic game.\nThe story and characters are interesting, but there''s a trans character treated in very poor taste and sexualised. Her storyline seemed great at the hints we got along before she tells about it, but from the moment she reveals it, EVERY LINE is pathetic and is just about how she likes looking, sounding and being treated as a girl but is actually such manly man.\nI would''ve liked the game and would even try getting all endings if it weren''t for that, but now I simply despise it :', 'Very Positive', 91.53, 11.72, 6.28);
INSERT INTO reviews VALUES (19647, 589940, 224, 'How one single dev managed to create possibly the most VR-ass VR game I''ll never know, but if you have plenty of room to play, you owe it to yourself to try this out. It does a lot of things that bigger budgeted games could only dream of achieving.', 'Developer should of let you move around with your VR stick instead of moving yourself only. Unless you have room of a football field you cant enjoy this game. I waited for 4 years for any update on this issue. Still unplayable for me since I don''t have a giant room to play in. Not sure why the developer is so stubborn on their design decision.', 'Overwhelmingly Positive', 95.09, 0.30, 0.35);
INSERT INTO reviews VALUES (19652, 590380, 11568, 'Back when I didn''t have money, I pirated this game and played the hell out of it, and it was one of my favorites to just boot up and do a turn every now and again in the background while I did other stuff.\r\nNow that I actually do have the cash to spare, I made sure to get it officially to support the devs. But when I booted up the official version for the first time, it remembered all of my achievements and saves from my pirated copy, and gave them to me properly on steam. They really didn''t hav', 'I really want to like this game, and I have liked other games from this publisher and the genre. However, the roguelike elements of this game are more about punishing new players with "gotcha" moments, where your ignorance of the game mechanics is severely punished. Such as certain squad/mission combos are not winnable, though you can still unknowingly select them, but new players wouldn''t know this until they figure it out through trial and error. The learning curve is more about "really?" mome', 'Very Positive', 94.05, 59.45, 4.85);
INSERT INTO reviews VALUES (19659, 590590, 205, 'Great game! Makes me furious every time I play it, but I keep going back. Always makes me want to shave a couple milliseconds off my time! Worth every penny!', 'Ok. So after seeing this game posted incessantly all over r/speedrun, and on the recommendation of a couple of friends, I figured I''d try it out.\n\nThis game isn''t fun to me. The controls are wonky, Kayra likes to eat shit into walls/spikes/death pits if you lose momentum, and why is there a ghost from the very beginning? I don''t want to know how well other people are doing compared to me on my first time playing the game, I want to play and enjoy the game. I figured out you can turn off ghost re', 'Very Positive', 94.15, 170.82, 1.13);
INSERT INTO reviews VALUES (19664, 590690, 469, 'In my opinion, this is the most fun game to sweat in VR. If I had to make a top 10 list of best VR games for real fitness (or to lose weight, if you need it) this would take spot #2, with Les Mills Bodycombat at #1, and Beat Saber and Ragnarock at numbers 3 and 4. Sprint Vector has its problems, it''s definitely not perfect. The online multiplayer is dead, and single player, although really interesting and quite effective to sweat with a VR racing game, doesn''t have a ton of content to keep you b', 'Leading Global VR Gaming Studio, Award Winning Immersive VR Games.\nEvery their game abandoned and barely functional, don''t ever buy anything for them, even for free it isn''t worth it.', 'Very Positive', 84.01, 6.05, 0.17);
INSERT INTO reviews VALUES (19685, 591370, 2090, 'This is a great assembly line/production game. I really wish the developer would add more to it. Don''t get me wrong, there is a lot of a game here, I like it so much that I wish there was more.', 'buggy asf', 'Very Positive', 82.44, 126.78, 2.60);
INSERT INTO reviews VALUES (19686, 591380, 308, 'Hi there,\nIt would be really great if you could add a level generator where we can select the difficulty.\nI am using this game with my kids (6y) and I think it''s great to teach them logic, problem solving and electronics. And they love it.\nHowever it is soon becoming too hard for them (around xor gate) there is not enough for them to practice on the easier levels. Hence why it would be great to have much more levels. Maybe 10 times more level for each chapter. Or best would be to have a generato', 'Great game, but only about a 1 hour playtime. Would be phenominal with a level editor / Steam Workshop, but I feel that''s a missed opportunity.', 'Very Positive', 87.34, 3.52, 1.58);
INSERT INTO reviews VALUES (19688, 591420, 779, 'It took me just shy of an hour to complete all levels and achievements... kind of fun though and really simple to play!', 'Zup! 4 feels like a slight step back compared to the previous entries, particularly in terms of difficulty and challenge. After enjoying the intensity and the need for precision in chapters 2 and 3, I was a bit disappointed with this fourth installment.\n\nThe overall difficulty of the levels is noticeably lower, and more importantly, the timing element is almost completely absent. In the previous chapters, precise timing was crucial to detonate blocks at the right moment so the sphere could reach', 'Very Positive', 90.89, 21.42, 0.53);
INSERT INTO reviews VALUES (19689, 591460, 1866, 'stego lauched a kid named charles into orbit 10/10 experience', 'It is despite the tutorial(s) sometimes very hard to figure out mechanics and some mechanics are bugged. There is a lot of content, but I feel the polish is missing.', 'Very Positive', 93.52, 29.30, 7.32);
INSERT INTO reviews VALUES (19694, 591630, 136, 'A nice little game that teaches us that sometimes our dreams might not be what we actually expect and that maybe our destiny is different from what we thought. That most times what matters is the journey and not the destination...\r\n\r\nWell thought puzzles, interesting mechanics, nice visuals. Plot that leans into a stereotype, which however doesnt take away from it its importance at any time. Duration around 4 hours. Played it on the Steam Deck, game ran flawlessly.\r\n\r\nOverall, a good game and re', 'Bleh, it might have been better, but i really dont want to squint to see where i am going, and to fall and lose even more changes.  Annoying game', 'Very Positive', 88.97, 7.65, 0.20);
INSERT INTO reviews VALUES (19701, 591790, 150, 'Very good game for 99 cents really fun theres some bugs but its playable. Sadly theres no players and the developer abandoned the game', 'Note: The last update made by the developers was over 7 years ago. The information and timeline described by the developers here may no longer be up to date.', 'Mixed', 49.33, 2.62, 4.15);
INSERT INTO reviews VALUES (19709, 592030, 194, 'when i run it i just get a black screen', 'CANT PLAY THE GAME when i load in is just a black screen fik it plsss', 'Mostly Positive', 74.23, 0.95, 0.77);
INSERT INTO reviews VALUES (19717, 592260, 1879, 'The game the almost 100 hours on when i bought it, it looked promising but seems that the dev has abandoned it its done me a great service and i''ve loved it alot. thers some problems here and there but sadly theres problems with exporting and he''s stopped trying. i really hope he''s okay and that nothing bad happened to him. maybe he''s had a rough time but i hope their okay.', 'Shouldn''t be on Steam. It is abandoned software that has many systemic issues the creator clearly couldn''t overcome. The fact that they started working on DP2 before they even finished DP1 should''ve been a clear sign that the program is broken.', 'Very Positive', 82.54, 85.52, 1.83);
INSERT INTO reviews VALUES (19729, 592480, 248, 'I really really liked this game. So much actually that I got the artbook. So when I saw just now that it had mixed reviews I thought I should add mine to the mix. haha.\n\nBack during pandemic I was looking for co-op games to play with my girlfriend while stuck at home. and I was surprised by how well Knights and bikes managed to convey the childlike exploring + imagination. If you''re looking for challenging gameplay then this is probably not for you. The game is pretty straightforward and super f', 'A co-op game (local or online; can also be played as a single-player game) with a linear story (around 10h long), beautifully drawn pastel art, and an imaginative story setting. The trouble is: it is never fun or exciting to play, mostly due to the boring plot and the utterly bland gameplay (exploration, combat, level design etc). Besides, the uncontrollable viewing angle and zoom-in/-out are doing a complete disservice to the background art. I regrettably suggest a hard pass.', 'Very Positive', 91.13, 14.30, 3.92);
INSERT INTO reviews VALUES (19733, 592580, 394, 'Better then FC24', 'AI in higher difficulties is awful...you can stop playing around 65th - 70th minute because it doesn''t matter which team you play against...they all will start playing like barcelona in their best years...just frustrating to this point!', 'Mixed', 59.90, 226.53, 973.50);
INSERT INTO reviews VALUES (19746, 593030, 165, 'This is a great game system, hindered only by the absurdity and historical inaccuracy of its scenarios and campaigns. Naval units are individual vessels and submarines, rather than flotillas & squadrons that would better match the scale of the game. The order of battle for nearly every belligerent is truncated, ahistoric, and poorly researched. Scenarios should be designed at corps level and below, with very few army level units. I built a 1939 campaign based on a historic order of battle and pa', 'As a solitaire experience, it''s fun for a while. But the naval subroutines don''t model the submarine war in the Atlantic at all well, and I would rather have no navies at all with this game.  The naval sub-routine ruins the game for me every single time. I''ve tried to mods; I''ve done research. Because the trade route is static, the Allies can "go trauling for U-boats" with tremendous success.  Spend 4 months trying to sneak out into the Atlantic and your U-boats will be crippled in 2, then you s', 'Very Positive', 89.70, 1269.48, 55.43);
INSERT INTO reviews VALUES (19751, 593150, 846, 'if pokemon and stardew valley had a baby and that baby was a stoner, it''d be this game', 'Although I really enjoy the game, I dislike how the devs talk to the community. Plus they didnt communicate that the game was done (or not done) and the ooblets community is left confused.', 'Very Positive', 91.49, 5.02, 25.12);
INSERT INTO reviews VALUES (19756, 593280, 3243, 'Get this for its simplicity, cuteness overload (save game by taking a cat nap!), addictive hack&slash (mewrder!!) and cat puns galore. Game makes fun of its flaws and RPGs in general, a chuckle here & there guaranteed. :)\n\nPossible turn-offs (or turn-ons for completionist masochists, I don''t judge) : risk of quickly becoming repetitive in terms of enemies, dungeons and fetch quests, a very grindy mid-late game, & high likelihood of not getting 100% achievements completed (extra grindy). A possib', 'i did not care for it', 'Overwhelmingly Positive', 95.25, 14.60, 0.12);
INSERT INTO reviews VALUES (19760, 593490, 111, 'Promising game that feels like the classic Caesar and Pharaoh empire builders.', 'https://youtu.be/n9nFXr76W9Q\n\nDevelopers have been proven to post reviews of their own title. As a result of this I cannot recommend this game and I would advise you do not purchase.\n\n**UPDATE** As is fairly predictable, the Developer has begun deleting discussion threads showcasing the video in an effort to limit the visibility of the issue.', 'Mixed', 69.37, 9.42, 0.60);
INSERT INTO reviews VALUES (19765, 593640, 445, 'A concise and incredibly beautiful game! After finishing it, I watched videos about its art development. It''s wonderful. I''m really looking forward to Pirofauna', 'Beautiful visuals but I found myself frustrated from the opening scene. Gameplay is slow with lots of backtracking. Stopped caring about what I was even supposed to be doing after a few minutes because there''s zero reason to keep going.', 'Very Positive', 92.58, 1.67, 0.48);
INSERT INTO reviews VALUES (19773, 593900, 131, 'In retrospect it''s obvious now why the genre of games that ask you if you fantasize about horse penises never took off, but it took Gaming Pioneers to take that leap and show us why.', 'This game is infuriatingly broken. I don''t know whether these issues are Steam Deck related only but if so then it does not deserve the verified status.\n\nIt''ll load purely black with no visuals unless you manually add Linux terminal launch options, that alone should disqualify verified. Then the game will randomly break when trying to go from a clickable environment to a cutscene, which basically IS the game, therefore this can happen at any time. The worst part is that this game has NO save/loa', 'Very Positive', 86.26, 6.35, 10.38);
INSERT INTO reviews VALUES (19775, 593960, 648, 'make sure you have lots of chocolate, painkillers and antidepressants with you while playing this game.', 'A nice short intuitive quest type expirience. One thing I don''t like this game is the portrayal of male characters: they are either completely spineless or unkillable psychopaths, which kind of plays into the whole feminist propaganda of "men bad" and unquestionable male subserviance to women, which is disgusting and makes a bad impression of men in general. There''s also a stange problem with the performace if you play on higher setting which shouldn''t be in the first place, but the visuals are ', 'Very Positive', 90.12, 6.98, 7.95);
INSERT INTO reviews VALUES (19780, 594040, 181, 'Fun, please update', 'It''s all but abandoned don''t waste your money', 'Mixed', 58.01, 32.52, 17.35);
INSERT INTO reviews VALUES (19781, 594050, 162, 'https://steamcommunity.com/sharedfiles/filedetails/?id=2706638821', 'The player camera only updates its position at 60Hz.\nNo matter how fast you PC is, this game will always feel stuttery.', 'Mostly Positive', 78.40, 7.23, 0.10);
INSERT INTO reviews VALUES (19783, 594130, 458, 'Fantastic, FULLY-voiced (yup, even the optional side-scenes) visual novel with plenty of interesting, morally ambiguous choices to make, and an adorable, furry cast of characters. The performances on show from many of the voice actors were great, with a couple emotional moments being particular standouts that had me on the edge of my seat. The soundtrack does a good job in setting the mood without being so noticeable as to detract from the dialogue happening at the same time, with the super spec', 'Its okay.  Looks good from what i have played of it.  Sounds okay too.\nThe creator is a bit up his own butt, but still, this game, of what I have played of it is okay.\nIf there was a 3rd option rather than thumbs up or thumbs down, a mid rating, I would give it that.\nIf you are going to get this, wait for a sale.', 'Overwhelmingly Positive', 95.85, 21.12, 0.23);
INSERT INTO reviews VALUES (19787, 594220, 160, 'This game is frigging amazing at an incredible price. The story is linear but I put this above Arizona Sunshine 2 although a similar game the levels in The Living Remain are much longer. How do I know? I completed AZ 2 in under 4 hours & took nearly 8 hours to complete this awesome game.', 'No idea why it so praise (very positive) - its abysmal. Graphics are very VERY poor. The physics is basic, the walking speed is so slow and the jankyness of this game mecanics ... someone should talk to the team of devs - Jankyness is not a feature to promote!\n\nBig big pass. Would have been very passable in 2018 but in 2025 this is ajoke. NO IT DO NOT COMPARE to other zombie shooter.', 'Mostly Positive', 78.75, 16.10, 0.15);
INSERT INTO reviews VALUES (19793, 594330, 3820, 'This is the only a game in my life that I feared playing. Incredibly frightening, will keep you on edge all the time. Very immersive, great visuals and environment.', 'Worst controls of my life, jesus christ. Opening doors is a pain, lighting candles and correctly placing them is a pain... if I wanted to suffer more with the controls than with the story, I''d be playing Manual Samuel. I know I might get used to this, but I''ve played for almost two hours and I''m NOT having fun. I can''t even pay attention to the ghosts if I''m worrying about whatever the f*** I have to do, if the place I''m standing is considered darkness, and funky controls. Just place the god dam', 'Very Positive', 86.44, 15.80, 1.67);
INSERT INTO reviews VALUES (19794, 594350, 108, '10/10 would kiss helicopter again', 'good meme. cute anime girls. bad ui. slow transition when meeting new characters. \nonly played for the point shop.', 'Very Positive', 89.81, 5.62, 2.12);
INSERT INTO reviews VALUES (19802, 594570, 50262, 'Only at 80% off. The DLC policy is still a borderline scam, but you can have fun in the game for the price.', 'I bought this on sale so its definitely worth it 75-80% off but I''m reminded of how scummy a company Creative Assembly is the longer I play.\n\nThey don''t sell you complete games, they sell you some of a game then sell you many of the cool features that synergize with your favorite factions separately through DLC... if your favorite faction isn''t a DLC in itself that is. Factions like Wood Elves are locked away behind over priced DLC you can only buy from TWW1 and there''s now 3 TWW games, and many', 'Very Positive', 93.47, 141.68, 196.58);
INSERT INTO reviews VALUES (19803, 594650, 88400, 'The game itself is great, the new engine update makes it look a lot better than before, it has removed all the jaggy outlines on a lot of objects/models and for the most part performance seems to be the same or better with DLSS.\n\nThe UI is absolutely terrible though, they need to fix it, it''s a complete step backwards from a UI that was already a bit awkward to use.\n\nGiving it a positive review, just fix the UI, there''s no point reviewbombing the game because of the poor UI when the gameplay is ', 'Update:They have released a video acknowledging the poor UI, while they did say they will work on it this review will remain negative till the new or fixed UI is implemented to the game\n-----------------------------------------------------------------------------------------------------\n\nNah yall should feel embarrassed about this new UI, like I legit refuse to believe you play tested it. Why is it all so BIG, the buttons make no sense too. Why is it space to pull up my hunter menu and then ente', 'Mostly Positive', 75.97, 280.70, 428.20);
INSERT INTO reviews VALUES (19822, 595140, 1136, 'Fun fast paced arena shooter rogue-like. \nGot a scroll that removed my crosshair and another that changed all the font in the game to hieroglyphs. \n\nI''m glad my gun has two men shaking hands amount of ammo', 'why did i buy this game i hate Roguelikes one of my friends warned me it was a Roguelike but i bought it anyway\n\nand unfortunately it has been sitting in my library for too long so I can''t get a refund\n\ndamn steam with their 50 to 80% discounts I fall for it every single time. damn you steam summer sale damn you \n', 'Very Positive', 90.23, 56.53, 1.93);
INSERT INTO reviews VALUES (19826, 595280, 1779, 'i miss this game', 'The game''s community has died, and I would recommend highly getting a different game.\r\n\r\nUnfortunately the game no longer has a supported playerbase, and games and matches are only sporadically found via it''s Discord Server.\r\n\r\nThe game has not updated in forever, an it''s development has practically died.\r\n\r\nWhile it was an amazing social deduction game (and even better than it''s competitors in terms of balance) when it was active, with better mechanics, and even had unique gimmicks and cosmetic', 'Mostly Positive', 78.25, 97.98, 288.05);
INSERT INTO reviews VALUES (19830, 595420, 114, 'Love the game, finally getting over the old tried but true East Side Hockey. \nLoads of improvements that help ease of life, good step in the right direction.\n\nIt pains me that the sim speed has not been improved at all, as that is many peoples gripe, aswell as my own biggest. Almost to the point of making me not reccomend, but alas, enough other things have changed to make that silly.\n\nGreat game overall, definitly taking steps in the right direction. If the sim speed is improved in patches, it ', 'Not right now. \n\nNot in it''s current form. Way too sloppy, way too many errors. And under polished. \n\nIf you want to support sports management sims, by all means. But OOTP needs to stop pricing this as a finished product and take a deep look at themselves, and decide whether they want this to be a money grab, or actually grow a fan base. \n\nI own FHM 1 through 4.', 'Mixed', 61.40, 8.45, 170.67);
INSERT INTO reviews VALUES (19831, 595430, 280, 'What a cool game. \nEven playing against bots is fun. \nThe dev stated via Discord, that he paused the work on this game due to his family life (he became a father), but will continue the work in the future.', 'This is a good game, but there are a few things you need to be aware of before buying.\r\n\r\nFirst off, it is in early access despite the last update being in 2021. Technically it hasn''t been completely abandoned, but don''t buy it unless you are happy to play in the current state.\r\n\r\nThe biggest issue that I have, is that it requires a persistent online connection to progress. And the connection can be a bit unstable at times. So if the connection drops, you''ll be instantly dropped out of your sess', 'Very Positive', 94.29, 2.68, 1.00);
INSERT INTO reviews VALUES (19832, 595440, 171, '\r\nQuite cool!\r\n', 'Dev raised the price of the game during the sale just so he could get the appearance of a deeper discount. Very shady. Game is actually MORE expensive with the 95% sale than it was just a few months ago at its true price.', 'Very Positive', 84.21, 3.90, 0.22);
INSERT INTO reviews VALUES (19833, 595460, 145, 'Flix and Chill\n\nHas a total of 7 trading cards.\n', 'Overall not worth to play.\n\nThere is some humour in the later levels, but other than that, success is mostly a gamble and trial&error besides "Don''t be a jerk". Replaying for achievements or story changes is tedious.', 'Mostly Positive', 77.93, 1.75, 13.37);
INSERT INTO reviews VALUES (19835, 595500, 1039, 'Story sucks, main villain is awful.\r\nIt''s an improvement over the first game on every other front, and i love this game to bits.\r\nThank you for existing, Freedom Planet.\r\n\r\nCarol is my waifu.', 'I wanted to like this game. I really did. It had solid visuals, decent gameplay, and a promising start but then it slammed a brick wall in front of me disguised as a race against a character named Captain Kalaw. This wasn’t a challenge; it was torture. You need superhuman reflexes, perfect execution, and a ridiculous amount of luck to win. I gave it a fair shot, tried, failed, and realized I wasn''t about to waste hours clawing my way past this nonsense.\n\nSo I uninstalled it, removed it from my l', 'Overwhelmingly Positive', 96.34, 85.68, 1.48);
INSERT INTO reviews VALUES (19837, 595520, 4317, 'Had 100+ hours on my old PS2 in 2009/2010. Then it broke and started playing again on PCSX2 in 2011, and my father started playing too on his save file. The game is so good it helped my father stop smoking for 3 months after smoking 20 years 2 packs a day. It is the last game my father finished from start. Had to play it again. Might be my favorite PS2 game. And dont believe Ondore lies!', 'It says it runs on steam deck, it does not. Game loads up and it freezes on a white screen. This has been an issue for years according to a Google search. That tells me a fix for this is not planned.\n\nThis also tells me that the steam deck verified feature also doesn''t work', 'Very Positive', 90.06, 48.42, 19.92);
INSERT INTO reviews VALUES (19845, 595690, 2801, 'I didn''t expect a game so rudimentary and clunky to be so immersive. My mom clothed me, fed me, named me, and taught me to farm potatoes. I was sad when she died, and struggled for the remainder of my life to give her a proper burial. I died next to her grave, right after my little sister said, "you did good bro."\n\nIt was a good life. \n\nAlso, I thought the tutorial was very good.', 'Bad, people will curse you and stab you for no reason. I told them I''m new then they cursed me, exiled me, and stabbed me to death in the house I was born in', 'Mostly Positive', 79.90, 5.80, 11.97);
INSERT INTO reviews VALUES (19848, 595770, 164, 'this adds a story to airmech. this is worth the money 9/10', 'DO NOT BUY\n\nThe developers have abandoned this game and want to unlink it from the main AirMech servers. The game itself is also not that fun. It can be easily completed in 8 hours, and the story is an absolute snoozefest. A complete waste of £11. Spend your money on the original AirMech or don''t spend it anywhere.\n\nIt''s criminal that they''re keeping this game up imo.', 'Mixed', 67.68, 9.53, 7.67);
INSERT INTO reviews VALUES (19850, 595790, 206, 'its a fun little arcade 2D shooter, you are placed in different arenas and must survive a number of waves, beat all the arenas and 5 bosses and you beat the game, simple enough', 'I didn''t really enjoy this.', 'Very Positive', 91.75, 2.78, 1.65);
INSERT INTO reviews VALUES (19853, 595960, 143, 'It''s May 2025 and Pinball WIcked is back! The new Unreal 5 Engine version looks I-N-S-A-N-E. The game is way better optimized now too and has a ton of new graphics settings. New music. It''s the highest quality digital pinball table available in the world!\n\nFull release is on the way now too. To get access to the Unreal 5 Beta, simply go to your Steam Library, right-click the game, select “Properties”, and navigate to the “Betas” tab.\n\nThey are working on a new pinball table too!', 'Why has a single pinball table been in Early Access since 2017??', 'Very Positive', 86.71, 31.25, 0.22);
INSERT INTO reviews VALUES (19855, 596000, 124, 'Short and very enjoyable. Some acts hit hard, some not really, but following the unwinding story was interesting.\nI wish ending was more twisted tho.', 'Nah.\n\nI got it at 80% off, and for that it''s fine as a time killer experience and achievement hunting game.\n\nAs a psychological artistic story though, it''s rather pretentious, and to call it a mystery is a stretch. I also don''t like when you accidentally progress the story by not knowing which, say, room to explore last, and get locked out of things due to it. The game could really benefit from being able to replay chapters for this reason, rather than having to start a whole new game on a new s', 'Mostly Positive', 76.61, 3.83, 10.50);
INSERT INTO reviews VALUES (19862, 596240, 121, 'Apocryph: an old-school shooter\n\nHas a total of 6 trading cards.', 'First off, this game does feel like the games they put in the description so atleast that''s a positive (and probably the only one), now onto the negative.\n\nWhen launched, we were promised we would have about 30 levels in total, there are only 3 levels total. When asked if there will actually be 30 levels, they ignore the answer. The AI in the game is so janky it''s crazy, it''s like they never even tested them or the levels themselves with the amount of bugs in the game. Half the time the AI just ', 'Mixed', 47.93, 1.43, 13.67);
INSERT INTO reviews VALUES (19878, 596590, 153, 'A simple puzzle game. No fuss.\n\nNot really memorable, but enjoyable.', 'It is ok, but pretty boring. Probably worth the price.', 'Very Positive', 92.81, 2.28, 2.18);
INSERT INTO reviews VALUES (19889, 596950, 109, 'I mean, I really don''t know what to say other than this is the greatest game of all time. Actually, no, I have a lot to say about why this game is so great.\nFirst of all, the UI. I mean, you get dropped into this game and immediately your eyes are blessed with what I can only describe as the greatest, most well made, and most visually appealing menu screen of any game I have ever seen. Like seriously, I think multiple substances of multiple different states of matter were released from every hol', 'very simple. very boring. very bare.', 'Very Positive', 86.24, 4.42, 0.35);
INSERT INTO reviews VALUES (19890, 596970, 2205, 'Sunless Skies is the definitive answer to the question "What game you like but not sure you can recommend?"\n\nImagine reading a VERY interesting book, but every chapter or so you have to throw the book across the room and go pick it up to continue reading it, and sometime you throw it too hard or too far so have to read the book from the start again. But if you can stick to it, the book is worth it.\n\nIf you like reading, game atmosphere and don''t mind A LOT of fetch quests, you can enjoy this gam', 'the core concept of the game, an RPG that spans ''generations'' as your captains die, is kind of interesting. the application is endless fetch quests, pretentious writing, tedious combat, and difficult to track storylines as every character is ''named'' with a descriptor + noun combination ("the incautious driver," for instance). getting the same RNG "skill checks" constantly because someone saw a spooky enemy that you''ve killed thirty times already just makes the entire experience more tiring.', 'Very Positive', 84.22, 34.67, 63.75);
INSERT INTO reviews VALUES (19893, 597030, 123, 'Ok time waster, don''t expect anything more.', 'Good idea, but very bad balancing - mostly ends up tedious and grindy.\nEasy difficulty is not easy, because almost everything is still a bullet/bomb/rocket sink.\n\nAnd when the map introduced just huge constructions (with nothing to them just being even bigger damage sinks)..Nah.', 'Very Positive', 82.11, 20.58, 1.88);
INSERT INTO reviews VALUES (19898, 597150, 252, 'Hyper Knights is an absolute delight that feels like a one man army simulator! From the stunning, but basic, visuals to the engaging gameplay, this game has it all. The combat is fast-paced and satisfying, with a variety of unique abilities that keep battles exciting. I love how every knight has their own backstory, adding depth to the experience and making you really invested in the journey.\r\n\r\nThe quests are well-crafted and often come with unexpected twists that keep you on your toes. Plus, t', 'Very fun, for a very short while. Taking the first territory and recruiting your first knight are the only exciting moments in this game. After that it turns into repetitive hell. "Super Self" is the only combo that matters, which is actually just mindless button mashing. You could beat the game just by dispatching your knights to defend your lands - they are going to raid the neighbouring lands anyway and eventually conquer them; all the manual work you need to do is upgrading villages/castles ', 'Very Positive', 90.08, 8.67, 6.13);
INSERT INTO reviews VALUES (19899, 597170, 15739, 'It''s as good as it has always been, ever since watching it with Blitz or BaronVonGames, or even Captain Sauce, this game still provides the same or even better satisfaction when watching it.', 'Singleplayer is fun but it''s like 90 minutes of play. And now for the important part of the game - multiplayer\n\n2 minutes of waiting for a game, 20 seconds of fighting before getting hit with a random fire arrow. Being put into same games with homosехuals with 8827 (!!!) wins doesn''t make things more fair. It''s not even lack of balance, it''s lack of even an attempt of. Also ping makes it unplayable. Completely throws off any movement predictions. Your clean hit doesn''t reg then you get slashed i', 'Overwhelmingly Positive', 97.33, 98.00, 11.28);
INSERT INTO reviews VALUES (19900, 597180, 2788, 'I am a university professor, game developer, and 4X TBS game fanatic. I played, developed, collaborated on, play tested, analyzed, wrote about, and searched for 4X TBS games most of my life. \r\nI played thousands of games and tens of thousands of hours of TBS games. I make this post after 300 hours of playing Old World. My estimated level of knowing and understanding Old World and its features: 60%.\r\nFar from being perfect, but my perception is that Old World is currently the second best game out', 'I really dislike that you can only settle cities in pre-defined spots.  It takes a lot of fun away from the 4X framework.', 'Very Positive', 84.43, 577.10, 3.13);
INSERT INTO reviews VALUES (19904, 597220, 8232, 'spit\n\n10/10', 'Devs have allegations of misconduct and SA :/', 'Overwhelmingly Positive', 98.12, 11.13, 3.33);
INSERT INTO reviews VALUES (19905, 597230, 414, 'does anyone else relate to this', 'It''s like NES Zelda but with a shotgun instead of a sword.  \n\nIt appears to be a somewhat competent product.  One thing I noticed was that the dungeon map was not tracking my location, making it needlessly confusing to know where I was.\n\nIf you think NES Zelda is fun in 2024, maybe this is worth a shot.  Personally I need something that is closer to Links Awakening, something like Master Key or Blossom Tales to really draw me into the adventure.\n\n', 'Very Positive', 93.00, 17.27, 0.18);
INSERT INTO reviews VALUES (19911, 597700, 175, 'Sometimes, you just need a game to help you relax and escape the world, and OVIVO is exactly that. It’s simple, yet incredibly fascinating, pulling you into a calming, hypnotic experience with its enchanting art and atmospheric music.\r\n\r\nAt first, I thought the gameplay would be too monotonous, but I was completely wrong. There’s much more to discover as the game progresses, and it’s far more engaging than I initially expected. I won’t spoil anything, but trust me—there’s depth here that goes be', 'The aesthetics and cool mechanical idea make you think this is going to be a great game, but do not let them fool you. The controls are janky, and the puzzle design is mostly "figure out where this block outside the screen is, then jump there with pixel perfect accuracy". If you enjoy that kind of thing, go for it. Checkpoints are plentiful, thankfully, but exploring this "metaphorical world" is not actually fun.', 'Very Positive', 88.57, 4.05, 0.60);
INSERT INTO reviews VALUES (19917, 597820, 8121, 'I don''t really get the mixed reviews. This game is really good. Sure the text box dialog requires reading if you ignore your automaton narrator, but the customization is incredible. The open world is amazing. Whoever complains about repetitive fighting, that''s any combat based game. At least in this game you can unlock combos and customize your load-out. Not just your weapons load-out either, but your magic/psionic loadouts. This game is detailed through and through. The mixed reviews are unwarr', 'BIOMUTANT had so much potential, but I found it disappointing and boring.\nThe combat gets repetitive, and the story fails to engage.\nA missed opportunity.', 'Mostly Positive', 70.90, 5.43, 1.18);
INSERT INTO reviews VALUES (19918, 597840, 229, 'its great works really well somtimes....', 'dogshit, update your stupid app. a majority of wallpapers dont even load to show a preview and there are 0 updates to new wallpapers. do NOT waste your MONEY', 'Mostly Positive', 72.49, 841.33, 103.52);
INSERT INTO reviews VALUES (19923, 597970, 169, 'Fun time waster, but I''m glad it''s cheap. The gameplay is quite good but there''s no real difficulty option or curve.', 'This is a really good game... that continually annoys the player with pop-ups after games.  "We''re on Android/Iphone!", "We have another game out!", "Are you enjoying the game?  Leave us a review!".  Well, here''s your review.', 'Very Positive', 83.43, 96.63, 27.35);
INSERT INTO reviews VALUES (19927, 598060, 1538, 'Dark and Darker but single player, hand drawn, and a bit less frustrating.', 'Atrocious balancing, you''ll feel it right after the first level.\nNot enough here to keep me playing for more.', 'Very Positive', 83.16, 19.28, 6.58);
INSERT INTO reviews VALUES (19935, 598330, 2599, 'nice game with beer in hand.  nice potencial but the game is half done. expected more updates, more object, bigger variation. but its worth of meney', 'Honestly one of my favorite simulators ever, but there are a lot of bugs. Heartbreaking, but the devs seem to have abandoned the game (or at best, ghosted their players!), so buyer beware that stuff may never get fixed. We all might be stuck waiting for the next great airport simulator from a different developer.\n\nWho knows, maybe we''ll get lucky and the devs will reappear and complete their promised patches. After more than a year, I''m not optimistic.', 'Very Positive', 81.53, 34.30, 177.53);
INSERT INTO reviews VALUES (19941, 598450, 185, 'Extremely underrated and overhated.', 'This game, is a gem in the way it''s designed. It has got a very nice battle system with some intricacies to it. The parry-cancelling that allows you to bait attacks for example, or combo two attacks. Jumping isn''t broken, which makes it very tense throughout each round, one mess-up can mean everything.\n\nA MAJOR buzzkill for this game is that there isn''t any online for the multiplayer. I was hyped for this game when I saw the mechanic shift from health bars, and was hoping to be able to play agai', 'Mixed', 63.78, 3.72, 1.87);
INSERT INTO reviews VALUES (19943, 598490, 121, 'As someone who enjoys playing as a support/healer class in most games I play, this is a very enjoyable game. It has a lot of meta humor and some 4th wall breaks, which adds to its charm. The music is pleasant and enjoyable while reminding me of Crash Bandicoot. The builds you can make a lot of different builds, however I''d recommend heal, remedy, shield, and meditate with focus mostly mana regen (meditate) and passive resistances (remedy). Graphics are nicely stylized and also pleasant.\n\nI do ha', 'The game is easy to play - a nice casual gaming experience.  Spell skill tree is nice.  However the game is extremely linear, and you progress through one monster encounter with amusing plot text to the next.  When you reach a monster you can''t beat your only real choice is to walk back and forth between previous monster trigger areas, fighting an identical 2 sets of monsters again and again until your party has levelled up enough to be able to take the next set of monsters.  Only you levelling ', 'Very Positive', 83.47, 27.55, 4.48);
INSERT INTO reviews VALUES (19946, 598550, 1719, 'A short but amazing indie title inspired by the likes of Contra and Metal Slug. But I must say, it is definitely better than them in every aspect. It''s overall easier and more modern gamer friendly. The gameplay is pretty solid. The cyberpunk art design is top-notch and overall, it does a brilliant job at giving that retro vibe in every corner. Even the character lines are cheesy in a good way. Level designs are also great.\r\n\r\nThe difficulty curve is too steep in the last area, I must say. But e', 'Pixel art is beautiful, shooting is fun, but... Every stage plays EXACTLY the same... Boring...', 'Very Positive', 94.53, 9.77, 1.02);
INSERT INTO reviews VALUES (19955, 598700, 1608, 'https://steamcommunity.com/sharedfiles/filedetails/?id=1681623469\nhttps://steamcommunity.com/sharedfiles/filedetails/?id=2809625758\nhttps://steamcommunity.com/sharedfiles/filedetails/?id=1924406360', 'I played this all the way to the end, and the final boss is ridiculous. SPOILER ALERT: The Final Boss is at least three boss fights in one, and there are no checkpoints: If you die at the *final* final boss you have to start all over, and I was one-touch killed by her. Thanks, but no thanks. I''ll play something else now.', 'Very Positive', 88.56, 11.48, 10.20);
INSERT INTO reviews VALUES (19957, 598730, 388, 'I don''t regret the three bucks I spent on sale. Finished it in about 12 hours, no replay value, but it was fun while it lasted.\n\nSolid GTA 2 style gameplay. If you liked that, you''ll like this, not much more to add there. \n\nThe humor isn''t going to hit for some people but ''out-of-touch-boomer deals with modern world'' works for me. The arc with the wanna-be-rapper/failson has been done better elsewhere, but it was minor enough it didn''t break anything.\n\nThe property buying mechanics are mostly a ', 'Basically an art portfolio. Like this feels like a project for a digital design class, rather than a game.', 'Very Positive', 88.40, 13.08, 1.37);
INSERT INTO reviews VALUES (19959, 598780, 159, 'Def a fun game to play with some friends. 10/10', 'Overall, the gameplay is incredibly solid, with controls being simple and easy to grasp, and a combat system that is as enjoyable as it is intricate. Despite the (relative) complexity of the combat, it is incredibly easy to learn with a high skill ceiling.\n\nUnfortunately, the game seems to have been abandoned by developers for the time being, and the online servers have more or less died off. It being abandonware is the sole reason for the negative review, and overall I highly recommend the game', 'Mixed', 66.67, 7.15, 25.42);
INSERT INTO reviews VALUES (19960, 598810, 935, 'It''s a great version of Carc.... but for some reason they hate money and stopped adding DLCs of all the expansions. \n\nWHY.', 'I love playing Carcassonne, but don''t bother buying any expansions because they will crash even during local games ):', 'Very Positive', 83.32, 81.58, 228.68);
INSERT INTO reviews VALUES (19966, 598960, 898, 'This game is great. It reminds me of the good old railway simulators I used to play in my childhood. It''s also nice that the developer does not support the Russian terrorism and supports Ukraine. Even though the game is developing slowly, it''s moving in the right direction, and it''s interesting to follow the updates. I don''t mind paying the full price for this game.', 'Nice game, but I don''t like that politics are injected into it.\n\nGood to see Ukraine, which is busy fighting a war against Thanos/Bad Spiderman/Hitler/etc., can spend time and money on getting Steam gamers to add ''Jester'' awards to my review. Keep them coming liberals.', 'Very Positive', 83.85, 3.52, 0.10);
INSERT INTO reviews VALUES (19967, 598980, 4485, 'been playing on and off for 5 years. never uninstalled the game or re downloaded. game is incredibly unique and i keep coming back from time to time. the devs really care and have been keeping up to date for years and still implement large updates to the game. truly a gem.', 'ok i really want to respect the dev(s?) because this game is pretty great. i love life sims so being able to just exist in a world like this is goofy and fun. but jesus christ the audio system is dogshit. your bike, the main method of transportation, isnt tied to any of the audio sliders in-game. i had to turn the entire games audio to 5 percent just for the bike to not drown out everything else. its insane that after 6 years of development (?), the fucking bike isnt even tied to master volume? ', 'Overwhelmingly Positive', 96.21, 29.68, 11.50);
INSERT INTO reviews VALUES (19973, 599080, 1619, 'The Blackout Club was, and still is, one of my favorites. The thing is, however, that it was the most fun at its peak activity--when the interactive, real-time storyline was still running and the developers were updating it accordingly. The Blackout Club was done in part to tell a story that players could be a part of, and that story is now concluded. I would still 100% recommend playing it, but if you''re going to recommend it you HAVE to be honest about the fact that it''s a dead game and there ', 'Dead and abandoned by developers. Other reviewers that know the game is dead but still recommend it are irresponsible. No dead game should be mostly positive, potential buyers need to know that the game is dead and the developers took the money and ran.', 'Mostly Positive', 78.44, 289.65, 2.63);
INSERT INTO reviews VALUES (19974, 599140, 15720, 'It''s like Stardew Valley, but they swapped the romance out for corpse desecration and cannibalism. Excellent and fun game.', 'I want to love this game. I really do. The art style is amazing, the story is interesting, the controls feel very good. \r\n\r\nIt''s the progression system, you get DRIP fed the story, it also overwhelms you with all these tasks, techniques, and just constant things you need to get done, but not enough guidance to get things done. Imagine, every time you''re looking forward to the next day to get a new objective to complete only to find that you are one step away, and you have to wait another 7 days ', 'Very Positive', 84.56, 430.72, 24.72);
INSERT INTO reviews VALUES (19981, 599460, 276, 'Interesting simple game mechanics!\nCrafting, hire many different heroes, sending heroes to travel, equipment,  attached to the equipment skills, heroes attributes leveling, small economy (leveled heroes demand more payment), selling stuff to earn money.\n\nRemark: at the start it is much easier to lose all money by taking wrong decisions. Just click on your pet to get money (or just replay). Later, earning money is much simpler.', 'At it''s core you hire crafters to make equipment for you which you then sell to make a profit and pay off your debts. You then hire adventurers who go out and bring you back new resources to make even better gear. You can then use that better gear to equip your adventurers, allowing them to go to more dangerous places and bring back even better loot. Rinse and repeat. \n\nI really enjoyed the core gameplay loop of Weapon Shop Fantasy as I enjoy micromanaging. E.g. you get a quest to make 5 shadow ', 'Mostly Positive', 77.54, 33.50, 150.52);
INSERT INTO reviews VALUES (19985, 599560, 127, 'I am a bit in between with this one\nThe riddles are fun to play but the story is a bit... \nThe "detective" should really go to jail herself for the stuff she does or at least lose her job...', 'This was a disappointing one. I wanted to like it, really I did. But the story is so flipping ridiculous it just makes me go "UGH." :( There''s really no redeeming qualities either. Nothing makes up for the poor dialogue, very poor storytelling that makes NO sense, nor the poor minigames and HOPs to play. I do appreciate the length of the game - and the bonus story was a good length unlike so many that can be barely 5 minutes of playtime. If I were you, I''d only buy this game if it was.... $2. :(', 'Mostly Positive', 70.08, 2.90, 5.47);
INSERT INTO reviews VALUES (19989, 599610, 349, 'I''m a writer whose grandma is currently on end-of-life care. \nI cried. A lot.\nBut I probably needed this game more than I realised.\nThanks game devs. <3', 'No hate, truly. Even though I am fond of wholesome children''s stories, this one was just a tad too boring to captivate the adult that I am or awaken the child in me. I believe there''s a secret recipe to make children''s work enjoyable for children and adults alike, and this one lacks it.', 'Overwhelmingly Positive', 95.42, 4.22, 8.08);
INSERT INTO reviews VALUES (19992, 599750, 443, 'Killed that bitch yeltsin', 'A great game, one of the better political sims out there, but the UI and information displays are not helpful (perhaps deliberately?). The biggest challenge now, is the lack of updates since 2020 and the game is so riddled with bugs that you cannot effect change in policies, political departments, or the economy as the game design intended. \n\nDo not buy until this game until you see it''s been updated in 2024 and information of bug fixes have been shared by the developer.', 'Mostly Positive', 75.40, 11.93, 34.68);
INSERT INTO reviews VALUES (19998, 599960, 171, 'This is a hidden gem.', 'It''s a sh*tpost. I would''ve recommended it if it wasn''t for some dumb jokes and annoying controls. And some of it felt personal. Honestly, I beat it out of spite. Eh, it''s pretty good in other aspects. \n\nBtw, anime girls just for a checkmark and advertising.', 'Mixed', 68.42, 1.52, 1.87);
INSERT INTO reviews VALUES (20000, 600080, 152, 'This is honestly one of my favorite games I''ve ever played. If ask me to someone were to recommend a game its "Unto the End". I thank all the people who supported, and assisted in the creating of this masterpeice. This got to be the most underrated, and unmentioned games I''ve played too. The combat, espcially when played on controller is amazing, along with the graphics, artwork, and story even when its not told my dialgoue. All this only for 15.00. Once I saw this games trailer I was instantly ', 'First off, I hate to vote this down and i love the concept and the style of the game but every step seems to be one seemingly impossible enemy after another which in my opinion sucks the fun out of it and ends up being a dying simulator. I do understand it isn''t supposed to be easy and yeah i like a challenge but to be 1 hit by some guy who i have to flawlessly hit 5+ times in a row only to continue this process over and over just leaves me frustrated.', 'Mostly Positive', 76.32, 19.62, 6.93);
INSERT INTO reviews VALUES (20001, 600090, 339, 'First time that a women is chasing me 10/10 would recommend', 'This game is incredibly annoying. The maps are designed so you have to constantly backtrack and do half a dozen workarounds to get anywhere, the enemy AI seems designed to camp you (or just spawns literally inside you and hits you before you can react) and the ending sequence must be one of the most frustrating segments ever designed. The story is promising, but the gameplay leaves a hell of a lot to be desired.\n\nHard avoid, even on sale. There are better games you can get for £1.', 'Mostly Positive', 79.35, 3.23, 3.58);
INSERT INTO reviews VALUES (20004, 600130, 752, 'Incredible variety for a game like this. The art is fantastic, killing stuff is fun. Just a solid game.', 'if you dont have a controller, dont bother. keyboard controls are by far the worst i have ever seen. \nGamplay is repetitive and many sections are tedious. if you want to make a hard game, go on, but make it hard, and not tedious to play.\n\ni dont recommend it, but you gotta decide', 'Very Positive', 87.37, 5.88, 1.35);
INSERT INTO reviews VALUES (20020, 600370, 850, 'Great humour\r\nAmazing art\r\nSuperb soundtrack\r\n5/5\r\nAccurately demonstrates life in Eastern Europe.', 'I have more play time than listed.\n\nThis game has excellent graphics and the voice acting is awesome, but the game itself is dull and unfunny. I''ll play just about anything if it has a good story, but I was not entertained.', 'Overwhelmingly Positive', 96.47, 11.17, 0.88);
INSERT INTO reviews VALUES (20024, 600460, 202, 'Just finished the campaign after approx 20 hours. Was an enjoyable deviation from my usual tactical turn based rpgs. Realtime stealth based combat was really well done. UI was somewhat clunky but became much easier after realising that the spacebar (pause) is your friend. Campaign, while hohum, was interesting enough to push you to complete. Rough translation didn''t help though. Able to save anytime is a real plus. The portrait for your main character is just plain ugly but custom portraits fixe', 'don''t waste your time dev''s abandoned and broke the game never buy again from this dev', 'Mostly Positive', 74.26, 32.85, 8.88);
INSERT INTO reviews VALUES (20025, 600480, 2135, 'I used to work extensively with fish of all types for over a decade and this is probably the first aquarium/management sim that has gotten the Vibes right.  I loved opening up a fish info panel and seeing "does not like conspecifics" in the tags- that''s how I knew this was going to be a good time.  I love playing "fish sudoku"- trying to time when fish grow in tanks with their tank mates to make sure they don''t eat them/aren''t eaten themselves along with any additional requirements like if they ', 'Game is nice but the auto-save (every 1min) isn’t working. I lost everything.\n\nAlso, it’s not intuitive when you start a new aquarium from the e-mail notification. If you say yes, you go to a new zone to make a new aquarium, and unlock more stuff. But then you can’t go back to your previous aquarium and if you save, only the current aquarium will be saved. You need a save for every zone… should have just made a map icon where you can see all your aquariums and choose between them.\n\nMy friend and', 'Overwhelmingly Positive', 95.41, 27.35, 2.83);
INSERT INTO reviews VALUES (20033, 600610, 220, 'This is a hidden gem among rogue-lites. \n\nGood progression and challenging but fair difficulty curve.\nLovingly crafted Arthurian aesthetics and writing.\nGreat, rewarding grid-based tactical combat.', 'This game has kind of every chance of being a game worth playing, However it is ridiculously difficult. No game saving, and no room for any kind of wrongful choices. You cannot return or retreat to passed landmarks on your map, and you have no idea for which kind of choices may aid you ahead. The battle scenes are sometimes a mess, where you have absolutely no idea where you should be positioned during combat. I suppose you learn from your mistakes, should you ever start a new run. However, for ', 'Mostly Positive', 73.18, 13.82, 7.98);
INSERT INTO reviews VALUES (20040, 600720, 149, 'im a real lagooner i love lagooning', 'A somewhat poor port of the Lagoon environment into Trackmania 2. Solo campaign is generally low effort, and the magnets on the tracks may fail to hold your car to the surface because the developers increased acceleration on magnetic surface in an update. The way car drives may not be to everyone''s liking either, switching from insane grip on roads and magnets to poor grip on wood and offroad. Also generally not a very active environment. Only buy if you want to complete TM2 collection and unloc', 'Mixed', 68.46, 6.92, 0.17);
INSERT INTO reviews VALUES (20044, 600990, 936, 'Through the long night, we share our stories, promising to keep our bond unchanged.\nWhile everything else fluctuates, one thing remains the same.\n\n\n우리의 추억을 기억해줘.', 'I don''t recommend this game because of it''s lack of everything inside of it. It''s not very interesting to rewind time back and forth and it gets boring after a while. Unfortunately you can''t control characters, they move by themselves.', 'Very Positive', 93.16, 1.30, 0.35);
INSERT INTO reviews VALUES (20047, 601050, 3436, 'Awesome game based on a really cool anime. The controls take a bit of getting used to but after that you''ll be flying through the air slaughtering titans in no time.\n\nThere''s a bunch of different game modes and a lot of ways to upgrade not only your main character but all the characters from the anime as well. Between each game mode it pretty much covers the whole story.\n\nIf you enjoyed the anime you should definitely give the game a try!', 'it wont let us kiss eren jaeger....', 'Very Positive', 93.83, 50.08, 7.27);
INSERT INTO reviews VALUES (20051, 601150, 33800, 'Devil May Cry 5 is a game about Vergil hiring Vergil''s brother and Vergil''s son in order to work with Vergil to kill Vergil so that Vergil can fuse with Vergil to become Vergil. 11/10 motivation would Vergil again.', 'DMC5 feels like every Zoom meeting I join while working from home: the room full of tedious NPCs, a whole lot of pointless conversations, and me in pajamas just staring blankly at the screen — knowing all too well I''d be better off playing Bayonetta instead. \nGreat visuals, though — definitely beats my Excel spreadsheets. (No it doesn''t)', 'Overwhelmingly Positive', 95.55, 462.72, 2.33);
INSERT INTO reviews VALUES (20056, 601220, 1472, 'If you''re a fan of puzzles and achievements, you''ve come to the right place !\n\n*** All ZUP Games have cool Puzzles + Trading Cards + a lot of working achievments ***\n\n+ Successes are letters in different colors that you can ideally use for profile design\n\n--> If you have the option, buy them all in a bundle to save money. You won''t regret it', 'This game is a headache -- but the achievements are gorgeous, for if you''re into steam artwork profiles.', 'Overwhelmingly Positive', 95.92, 1.20, 2.88);
INSERT INTO reviews VALUES (20062, 601430, 5630, 'the protagonist name drops the full title of this video game and then stares into the camera.', 'A spectacular downgrade compared to the first game. The first one wasn''t a great game by any means, but it had its moments and charm, and wasn''t boring to go through.\nTEW 2 is just bad.\nThe story must be one of the dumbest stories ever in a piece of media. The main character is just plain stupid, and he is a police detective hahaha. He also just doesn''t shut up. The game is riddled with neverending long a$$ cringy cinematics.\nThe villains are totally original though. An art student, an evil prie', 'Very Positive', 90.83, 21.95, 22.67);
INSERT INTO reviews VALUES (20067, 601530, 347, 'Darkarta is a very polished HOG with an Indian setting. Some of the puzzles are frustrating to solve but the actual HOG parts are great, with no odd names for items.', 'I forgot why I had stopped playing this one so many years ago, only to reinstall and in barely 20min remembered why...\r\nThe game has serious issues with registering clicks, it constantly sends you out of puzzle and hop screens. Interactable zones are never clear, and the design is horridly obtuse. \r\nOh it has all the features of a HOPA, like fast travel, collectible objects, a hackneyed cliche story of love, of course its the cloyingly sweet kind of save the innocent baby... (honestly this is no', 'Very Positive', 90.49, 2.85, 7.02);
INSERT INTO reviews VALUES (20068, 601540, 340, 'I got this very cheap on sale. Still very early access. Concepts are interesting and there is a lot of potential, hence why its a "Yes" and not a "No." I only played 28 mins and didnt really have fun, but I can see why this game is compared to a mix of Total War and Mount & Blade 1 and 2... But its not in state where it is fun to play. Difficult to learn and do what I want to do. \r\n\r\nIn a battle left click is both select and attack so its very difficult to control. In strategic view difficult to', 'it''s a crime that this is still even on sale.\n\nAvoid like the plague', 'Mixed', 49.71, 0.47, 2.38);
INSERT INTO reviews VALUES (20079, 601810, 875, 'it crashed one time like 4-5 years ago and i still cant open it to this day but its still fun\r\n', 'The game starts out amazing and then devolves into the most infuriating "rage platformer" BS I''ve ever seen in my life. It''s a Sonic-style game that emphasizes speed and forward momentum in every single part of its design, except the level design in the last few areas suddenly throws all that out the window in favor of precise jumps and disappearing platforms. Which would have been fine in a game like Mario whose controls and overall design philosophy support it, but not in a Sonic clone. And do', 'Very Positive', 91.54, 17.92, 4.10);
INSERT INTO reviews VALUES (20080, 601840, 5080, 'Please I am begging you make a sequel.  I have yet to find a suitable equivalent to everything this game does so well.', 'Just badly designed unfair game.  \r\nIntroduction lasts 10 hours and then last boss crush you in 3 moves.\r\nGames forces you to play combats over negotiations all the way down.\r\nI dunno why devs made it, maybe to "shock the play with hardcordness".  Not shocked just disappointed.', 'Very Positive', 93.62, 105.78, 18.12);
INSERT INTO reviews VALUES (20104, 602320, 1078, 'A puzzle game about trains? Autism at its finest, a very fun and entertaining game', 'You''d think it''d be fun to build tracks and produce goods, but you''d be wrong in the case of Train Valley 2. The first game was smooth head scratching from the beginning to the end, but this one starts getting on your nerves after a couple of hours. The maps get complicated which is not the problem, but it''s not fun anymore when you can''t tell where you can build the tracks due to the graphics and the clutter in the maps. The cleverly programmed tunnel and bridge building modes highlighting ever', 'Very Positive', 90.82, 10.97, 9.90);
INSERT INTO reviews VALUES (20106, 602430, 107, 'I''m torn on this game. Of course the game looks cute and I didn''t find it difficult myself, but it''s not totally exciting either. It''s family friendly if the child doesn''t have to play, because the game would be too difficult for that. \nI didn''t finish the game because it didn''t appeal to me completely, but if you like games like this, you should wait for a sale and treat yourself to the game.', 'Might change opinion about the game later, but the first impression is not good. The first level has you navigating narrow bridges, literally from the start, and you die if you fall in water. There are no options to turn on invisible walls or any other accessibility features. For a small child (who I presume is the target demographic of a game about a cute little elephant going on an adventure), who is not yet that precise with the controls, this is insurmountable obstacle. They go forward a bit', 'Very Positive', 81.31, 3.83, 0.20);
INSERT INTO reviews VALUES (20109, 602520, 2218, 'The auto button is very useful when you have your hands busy.', 'no nudity', 'Overwhelmingly Positive', 97.16, 5.47, 1.07);
INSERT INTO reviews VALUES (20117, 602700, 604, 'bought the game here, but played it in rust', 'Not recommended not worth money from that if u wanna rust skin just buy it', 'Very Positive', 91.39, 2.38, 0.53);
INSERT INTO reviews VALUES (20118, 602770, 182, 'Play this game and get a free clatter helmet in Rust!', 'The CPU trash talk is annoying and it doesnt seem to be toggled. Personally, I know what mistakes I make when I make them, because the game is very much like chess. We are not permitted to trash talk in chess. I dont need the computer rubbing my nose in it. Uninstalled.', 'Mostly Positive', 76.37, 1.57, 3.67);
INSERT INTO reviews VALUES (20122, 602890, 113, 'Good game made by developers for developers. Not to recommand for a Twitch stream after all, but really fun if you want a chill game.', 'Tried playing the game, and immediately got stuck. Was told to hack an account... no username was provided, nor mentioned anywhere. The game is unplayable.', 'Mixed', 49.56, 1.62, 0.20);
INSERT INTO reviews VALUES (20127, 602960, 24946, 'i stole fentanyl from the medical cabinet and got shot in the head by the captain, fortunately the doctor could fix my fractured skull and severe braindamage, pretty good game', 'I''m too stupid to understand how this game works', 'Overwhelmingly Positive', 95.24, 26.70, 2.08);
INSERT INTO reviews VALUES (20131, 603020, 203, 'abi fma daki edward var oyunda la', 'Your character is soooo slow in this game.  \n\nI have practically zero motivation to go anywhere or do anything because walking around is such an arduous chore.  Combat is also slow.  Most metroidvanias, even the soulslikes are not this slow.\n\nIt''s a pity, the initial story premise was interesting:  You died and were brought back to life by someone who inhabits your body.  They can dispose of you at any time and take someone elses body if you don''t do their bidding.', 'Mostly Positive', 72.91, 12.97, 0.25);
INSERT INTO reviews VALUES (20146, 603260, 374, 'Thanks to this game, I will no-longer laugh at my cat when he''s hunting birds through the window.\n\nNow I know he only does this for the achievements!!', 'I hate to be that guy, but I don’t think The Cat Games is that great. In fact, I am very disappointed.\n\nI don’t mind minigame collections, but what is on offer here is pretty weak. I found none of the 3 main offerings appealing, I was able to complete everything achievement-wise within less than 50 minutes, and then just ended up leaving the game on to get the Steam cards out of the deal. The indoor racing feels weird to control and the object randomisation feels unfair. The swim challenge just ', 'Very Positive', 90.64, 1.22, 2.18);
INSERT INTO reviews VALUES (20148, 603320, 276, 'It''s hard for me to put into words what I''m feeling. For the first time in my life, I fell in love with a game from the very first level. It is rare for me to experience this. I enjoyed this game even more than I expected, beyond fun, even more fun than I expected.', 'I bought this game 5 years ago (Yes, in 2019) when it first was in early access. I bought it because Warstone, Battlecruisers first game, is one of my favorite games. I installed it a few times over the past years but the game did not seem to make any real indepth progress. So I was surprised to see that it came out of early access. So I installed it for the fifth time.\nConclusion: Age of Defence does not even come close to Warstone.\nIt seems to have been programmed by a completely different tea', 'Very Positive', 80.80, 8.37, 29.13);
INSERT INTO reviews VALUES (20154, 603390, 322, 'It was fun at first, but be aware that it becomes a grind.  One of the items in the game is something that will enable the game to loop levels over and over, so the grind is a planned part of the game.  I think for over half of the 91 hours I "played", the game was just going in a loop in a background window while I did other things or slept.  You need more and more of things to upgrade them, and it increases exponentially.  I''m now at the point where I have 1,028 of one thing, and 5xx-600 of ot', 'Has long since devolved into mobile game slop, unsurprisingly around the same time the dev started getting invested in crypto and "AI" ventures. Constantly badgers you to send "referral codes" to people. Straight up has season passes. No new meaningful content in 4 years.', 'Very Positive', 90.99, 127.95, 815.07);
INSERT INTO reviews VALUES (20159, 603530, 623, 'The first time I played "A Robot Named Fight" was on the Nintendo Switch. Got it on sale for $0.99 and it was well worth it. A Metroidvania with procedural generation of maps each time you die. The rooms themselves are fixed though, so that runs will always be possible. There are many weapons and items to collect to help you fight off the fleshy invaders with items unlocking as you play through the game. Teleporters and Revenant stations are pretty neat too. If you die, you can spawn one time ba', 'SHIT TROON GAME', 'Very Positive', 89.09, 12.23, 7.38);
INSERT INTO reviews VALUES (20166, 603700, 104, 'If you like story rich games this is a must play, a funny story about a spy who doesn''t want to waste her time as an assistant, and wants to cause chaos. You spend 70% of this game listening to dialogue, the VAs casted were phenomenal and added real emotion to their characters. The main female spy is hilarious, the game play was very beginner friendly and the story was easy to follow. 100% recommend if you''re looking for a funny point and click game :)', 'Really disappointed with this game. It started off positive, with a phone call mini game where you have to find information to manipulate the person you''re calling. It then quickly drops off with pointless, boring tasks that don''t feel very intuitive or interesting. \n\nI wish I could get this refunded, but left it too late. Don''t recommend; the premise is great, the execution, poor.', 'Mostly Positive', 75.96, 5.43, 1.23);
INSERT INTO reviews VALUES (20168, 603750, 220, 'bought it just for the black background and then refunded', 'I don''t like. :(\n\n\nIf you''re playing this your most likely only playing it for the easy 100% achievements or the pitch black background.', 'Mixed', 53.18, 2.02, 2.07);
INSERT INTO reviews VALUES (20170, 603800, 107, 'The puzzles are tough, especially towards the end. Oddly, many puzzles give you more cubes than you need, which is confusing for no reason (eg. for the final puzzle my solution left three cubes unused). It feels like the developer designed the puzzles by just randomly placing a few cubes, lasers, and nodes down (making sure all the nodes were activated) without checking that their solution is unique, or even optimal. Contrast this with a game like Baba is You, where it''s exceedingly uncommon to ', 'I''ve played ReThink until level (or room) 20 and probably will never play again.  I hate jumping puzzles and this game unexpectedly has quite a few.  It starts off strong with some very nice laser puzzles.  I really enjoyed them.  Then there''s a series of cube/climbing puzzles which were ok.  Then jumping gets incorporated into the puzzles and that''s when the game started getting less fun for me.  \n\nI find making the jumps to be rather difficult in this game.  I have to hit the jump key way, way', 'Very Positive', 85.98, 3.63, 2.55);
INSERT INTO reviews VALUES (20171, 603810, 116, 'A Girls Fabric Face (weird name) is a short horror game meant to be played in one sitting. It takes place inside a house that opens new areas as you find new tools or the narrative advances. The house is dark but you''re equipped with a camrecorder that has a flashlight, but that''s not the only thing you can do with the camrecorder. You can also record paranormal activities as weird things happen around you. There''s a % counter that fills as you record stuff, and I guess you''ll get an achievement', 'After getting to the first ending I didn''t feel any motivation of achieving the rest because even the first one (read: "straightforwardly linear run to escape without any prior knowledge") was just boring enough. Ok, I mean, the horror ambience, screamers and all were not bad, no, but the overall plot wasn''t engaging and tbh, didn''t present any mystery pleading for itself to solve.\n\nTL;DR: Simulator of multiple walks between two opposite corners of the house with demonstration of disconnected el', 'Very Positive', 82.76, 0.95, 1.27);
INSERT INTO reviews VALUES (20173, 603850, 8673, 'The game is easy to learn and it''s a good replacement if you are tired of games like HOI4 and EU4.', 'I genuinely wonder how people keep playing this game with such a terrible UI. Anyway, I would probably get past that if it weren''t for the fact that the game changed the nation I was playing after I''ve updated the UI scaling settings. WHAT!?\n\nThere''s a chance I''d get past that as well, but after I struggled for 10 minutes to find my new nation on the map and failing to find any centering button, I finally gave up. I''m too old to battle with UI for 1h before I can actually start playing.', 'Very Positive', 86.67, 55.22, 0.92);
INSERT INTO reviews VALUES (20178, 603940, 132, 'Unique concept and well executed. I like it. 7/10', 'It was fun at first, but the gameplay in the late game was not fun. It tries to mix things up by making items become invisible and artificially making enemies strong with no real way for you to fight back. It doesn''t even offer powerful late-game weapons or armor. It''s just mediocre.', 'Mostly Positive', 77.27, 1.60, 32.03);
INSERT INTO reviews VALUES (20179, 603960, 2337, 'If I ever met one of the devs I''d buy them a beer for making a great twin stick bullet hell roguelike. Then after one sip I''d slap it out of their hands. "That''s for the troll rooms."\n\nAlso, the music is amazing. It gets stuck in my head every time I play.', 'Give me your medals', 'Overwhelmingly Positive', 96.53, 31.42, 19.00);
INSERT INTO reviews VALUES (20191, 604240, 7816, 'when you shoot the ground a new corn grows', 'Game is quite well made and is actually pretty fun, when there isnt a hacker in your lobby that is. Which seems to be every single game so its unfortunately become pretty much unplayable.', 'Very Positive', 93.45, 14.25, 19.23);
INSERT INTO reviews VALUES (20193, 604330, 517, 'I so badly wish more people knew and played this game. I tried showing it to all my friends an they all laughed it off as "another furry VN" And it pissed me off. The story is so gorgeous and the art is ughh so heccin cool. Cant wait for chapter 3\r\nOne day ill make a proper vid on the game since doing gameplays feels awkward cuz its a lotta reading haha\r\n9/10 only cuz i need chapter 3 NOW WRAGGHHH', 'No updates since forever.', 'Very Positive', 94.97, 11.07, 10.80);
INSERT INTO reviews VALUES (20195, 604450, 232, 'Story: ★★★★☆\r\nMusic: ★★★★☆\r\nGameplay: ★★☆☆☆\r\nOverall: ★★★☆☆\r\nRough around the edges but interesting narrative - didn’t expect this from the dev of those mobile troll games I’ve played in the past', 'Boring af. Million other games on Steam for the same price are much more entertaining.', 'Very Positive', 86.64, 0.90, 0.52);
INSERT INTO reviews VALUES (20196, 604490, 595, '⠀', 'Running Through RussiaRunning Through Russia is an achievement spam game that fails at even being that, the only reason anyone would buy this would be for the abundance of achievements, only for the game to drip feed you them over the course of 2 hours of actively playing. I regret ever starting garbage like this.\r\n\r\nGameplayVery simple endless runner, poorly made to where you just constantly die and restart, no goals or anything, simply garbage shovelware.\r\n\r\nAchievements (4096/4096)Unlike othe', 'Mostly Positive', 75.80, 2.73, 2.15);
INSERT INTO reviews VALUES (20200, 604540, 2492, 'This game is the reason why Steam needs a third option beyond the thumbs up thumbs down we''re given. Ultimately yes I would recommend the game, but the developers gave up on this way too early in my opinion. The concept is great and had a lot of potential that is lost. The ability to develop and manage a mafia empire was a huge draw for me. The combination of RTS and turn based strategy is equally well done in my opinion with the design of the game. Other pros that make the game worth while are ', 'Broken, rugpull game. Tons of bugs that will ruin the game for you and stop a campaign in its tracks. Expansion 2 was sold but never delivered. I actually liked the game, thought it could be a little slow at times, but thought it had potential. Sadly now it is abandoned.', 'Mixed', 50.92, 103.90, 34.00);
INSERT INTO reviews VALUES (20203, 604740, 129, 'If you were a fan of Burnout''s crash mode then you will love this game!\n\nEdit:\n\nIt runs great on an Intel HD4600 - with all settings on max @1920x1080 I get between 30 and 60FPS. My specs: i7-4900MQ @ 2.8GHz, GTX 780M (not using for this game however), 16GB RAM, SSD, Win 7 SP1', 'Very bad damage model, boring gameplay, no music, slow and annoying game!\r\n', 'Mixed', 65.12, 3.88, 0.33);
INSERT INTO reviews VALUES (20205, 604780, 273, 'A simple maze game that doesn''t pose much of a challenge.', 'Uninspired puzzle game. If you are a heavy puzzle game nerd and you dont find anything else anymore you havent played, sure, I guess.\r\n\r\nIm on a quest of at least trying every game in my library, of which I got plenty from all kinds of bundles, not all though. If you are interested in my journey, check out my other reviews :)', 'Very Positive', 81.68, 0.88, 7.72);
INSERT INTO reviews VALUES (20221, 605230, 954, 'I wrote a python script to convert a specific video(!) to text files then copied the contents of the text files into the game, then used the game''s scripting language and coded a program that could play the video from those text files into the terminal(with full colors), compiled it all into a single file program and uploaded it as a hack tool just to Rick Roll whoever decides to download and run it. 10/10', 'not very friendly to new players, toxic player base run off new players before they even get a chance to start doing missions, they also give no advise or help', 'Very Positive', 89.52, 64.10, 57.60);
INSERT INTO reviews VALUES (20225, 605450, 698, 'Always stays in my top 3 vr games', 'Was great for its time, however the steam version has been abandoned in favour of the Quest.\nWorth $10 on sale, but tough to recommend at full price.', 'Very Positive', 82.95, 31.62, 6.85);
INSERT INTO reviews VALUES (20228, 605740, 9144, 'The game is fun, but has a lot of downsides. Lacks content, extremly glitchy so far and uses a ton of resources for mediocre graphics. I wouldn''t take it at full price but when on sale it''s worth it.', 'This game could be good but it''s too buggy. NPC''s will get stuck. I couldn''t figure out how to tow a car away during the police mission. The medic missions were okay. The firefighter missions were probably my least favorite. There was a fire on top of the building I couldn''t reach so I thought maybe a ladder could reach it. The ladder mechanics is glitched and the water from the truck doesn''t reach the building. Then I had to help a woman from a car accident which seem like the medic missions at', 'Very Positive', 84.09, 16.22, 1.12);
INSERT INTO reviews VALUES (20231, 605830, 230, 'the only silent hill game on steam is Homecoming and this is better than that.', 'I only played it for a few minutes, but the game is just too outdated in 2024. Maybe that was ok in 2017, but I cannot play this in 2024.', 'Very Positive', 89.57, 0.87, 0.12);
INSERT INTO reviews VALUES (20245, 606230, 1174, 'I prefer Thea 1 and have only played 2 for 40+ hours BUT I like it for its ease and overall update in game play compared with Thea 1. combat is much easier as is crafting and gathering. There is more of a build up in challenges and each island gives you a higher level of difficulty.', 'Every single thing in Thea 1 is better, then in Thea 2. \n\nThis is absolute trash, ignore it and get the first game instead.\n\nIf you''re set on buying it, you can pick it up on other platforms for less then 3 bux.', 'Mostly Positive', 78.71, 156.32, 2.17);
INSERT INTO reviews VALUES (20246, 606280, 4085, 'I''m never listening to reviews again. Look, if you think a game will interest you and be awesome, THEN TRY IT OUT. DO NOT LISTEN TO YOUTUBERS OR REVIEWS. This game is F***ing amazing.', 'I really tried to love this game because I''m a huge fan of the franchise but it has nothing left of what made its predecessors great. I tried to put down my bias that I hate Dark Souls and Souls-Like Games and even cheated just to achieve some form of powerfantasy, which made Darksiders I + II memorable games. But after realising that it doesn''t matter how high your level, how low the difficulty or how upgraded your armor is, how many healing items you have (healing items have cooldown) or how m', 'Mostly Positive', 76.92, 78.33, 6.57);
INSERT INTO reviews VALUES (20251, 606370, 103, 'This game should be mentioned with Chrono Trigger and FF6 as the SNES rpg kings. Masterpiece. If you don''t like it then I blame you for being weak, not the game.', 'The game itself seems fun enough, sadly the port is an atrocity that makes the game very hard to play. \n\nYou have no options at all, need steam input to get your controller to work and if you tab out it sometimes forgets that your controller exists forever (until you restart the game that is).', 'Mostly Positive', 78.64, 45.57, 0.23);
INSERT INTO reviews VALUES (20254, 606500, 1155, 'Unique game style, but overpriced. According to other reviews, development was slow and I assume the devs lost motivation. This could''ve been a truly amazing game well worth the price, but it lands a fair deal short of that.\nTo be fair, I enjoyed my time playing, would definitely recommend it and if you''re not hurting on money then $20 isn''t outrageous. I''d price it more in the $10-$15 range though, personally.', 'Game was never finished but the dev says it''s "full release"', 'Mixed', 66.67, 25.08, 6.30);
INSERT INTO reviews VALUES (20258, 606680, 247, 'Shame on you Steam. Its full of bugs, incomplete (rain dungeon not available, glass palace unavailable, special attacks not available) and this is just after 4 hours of game play. I finished the game back in ''99 but now it just feels like Steam robbed me of one of the best games from my childhood. \nGame is awesome, but not this version that Steam sells.', 'FF is Gold - this is not Silver...its not even bronze...', 'Very Positive', 92.31, 5.13, 0.10);
INSERT INTO reviews VALUES (20260, 606710, 432, 'One of my favorite games growing up', 'Sphynx has a reputation for being a hidden gem of an action adventure game, and it is quite the looker for its age, but I found the puzzles to be tedious, and I found the game world to be repetitive and bland.', 'Very Positive', 93.98, 29.80, 14.22);
INSERT INTO reviews VALUES (20262, 606730, 181, 'Having played this back on the 360 I can say this is an excellent, beautiful, and very unique shmup. A lot of people will claim the main time mechanic works against you, in response to that I say beneath layers of sweat and tears, "git good". It''s genuinely one of the most difficult shmups I''ve played but it''s worth every second. I hate to say "Dark-Souls-like" but it really does beg you to come back for more after it shoves your face into the dirt for the 20th time. The set pieces alone make yo', 'What a shame. The core gameplay in this game is pretty fun. They did a great job with the graphics and the in-game presentation... but it''s all ruined by some horrible game design decisions. First, they decided to make it so that if you get hit once you lose ALL of your firepower powerups and have to frantically chase them around the screen to regain them. You will get hit... it''s borderline inevitable. Absolutely ridiculous. I could see maybe losing 1 powerup when you get hit once, but ALL fire', 'Mixed', 58.56, 2.82, 1.52);
INSERT INTO reviews VALUES (20264, 606800, 2833, ' If you’re into micromanaging and have an unhealthy obsession with virtual numbers, this might scratch that itch.', 'Definitely not for the faint of heart, I wasn''t expecting the amount of micro manage it forces on you..', 'Very Positive', 80.69, 9.73, 1.25);
INSERT INTO reviews VALUES (20267, 606860, 252, 'This game is like my ordinary dream. Easy to get all achievements', 'I have no idea why is this crap is in my library this is unplayable\nSlow walking speed, at least give player power to sprint would be better.\nPuzzle is fine, just terrible at where it located.\n\nNot recommended for who don''t have patient', 'Mixed', 63.10, 0.73, 0.20);
INSERT INTO reviews VALUES (20269, 606880, 10049, 'This is a strange game to me, cause I''ve plaued it twice and sunk over 100 hours into it, yet I just really don''t have an opinion. Since I finished it both time I think I lean more positibe than negative which is why I recommend it, but otherwise I just really don''t find this game memorable at all.', 'It''s a walking and talking simulator. Walk, walk, walk...talk, talk, talk. You look like a musketeer...a walking musketeer. You walk up hills, down hills, through forests...cause every movie you ever watched that gave you these vibes had the hero...walking. I was so tired of walking at one point...in despair, I right-clicked on my companion to see if he would carry me. He wouldn''t. So, I rage quit.', 'Mostly Positive', 76.62, 102.23, 16.33);
INSERT INTO reviews VALUES (20270, 606890, 130, 'For the price it is sold a fun little game for inbetween. Nothing really bad to say about it, nothing really groundbreaking either. Got it on sale for less than 2 USD, it was ok for that.', 'I bought this game for 1 dollar and asked for a refund after 10 minutes, which I didn''t think I would ever have to do lol, but the game assets are glitching and disappearing constantly, its entirely unplayable for me unfortunately... Got very good PC btw.', 'Mostly Positive', 71.54, 7.18, 0.13);
INSERT INTO reviews VALUES (20274, 606960, 136, 'CRIMSON METAL Classic 1999\n\nHas a total of 9 trading cards.', 'If you expect anything reasonable than just keep your hands off that one so as there is no fun but anger to expect. First lacking of any settings, it is way too dark like there is an energy discipline, the basics comes (what else to expect) from Doom & Co but you cant call it old school shooter coz the old school was better. Music is like Quake but nothing new nor anything better. Loadtimes - take a p or s, come back and you can play! The character moves clumsy and tends to become glued to the g', 'Mixed', 47.79, 1.07, 0.80);
INSERT INTO reviews VALUES (20279, 607050, 2328, 'As a single player game it felt very lacking, especially compared to "Advance Wars", but as a co-op game it is tons of fun. Be sure to also get the mod that allows you to play the campaign mode in co-op, as the official co-op campaign is quite short. What I prefer in "Wargroove" over "Advance Wars" is how you can check the exact stats of each unit.', 'I want to love this game, but I can''t.  The core problem is the difficulty curve.  On a one-on-one fight of even numbers/income/holdings the AI cannot win against even a barely competent player.  Thus, the only way to make it a challenge is to constantly pit the player against overwhelming odds.  Kudos for the devs for making many plot-contrived reasons why we are always on the defensive, but it''s tiresome to barely get $400 a turn to spend either healing or recruiting, when the enemy gets over ', 'Very Positive', 83.20, 58.32, 16.38);
INSERT INTO reviews VALUES (20280, 607080, 7694, 'This game is high budget cinema on the same level as Dreamworks, Pixar and any other studios who made groundbreaking animation in the last six years. This game has the craziest art, music, scenario, game design choices for the entire genre of platformer games. This game has a unique perspective on mental health issues with recognizable humor from Double Fine studio (thank you, Tim Schaefer). \n\nAbsolute love and respect for devs, original backers of crowdfunding campaign and also publishers (Star', 'Psychonauts 2 is very controversial game. After finishing it i found that it is very difficult to recommend it.\r\nIt is a very good platformer with interesting plot, good music, specific character design - a good sequel to original game. The variety of regular enemies was increased and every type requires different approach. Player still can roam through areas, collect cards, scavenger, find himself in different situations. \r\nNew character skills, possibilities were added to improve story progres', 'Overwhelmingly Positive', 96.59, 33.02, 24.70);
INSERT INTO reviews VALUES (20305, 607880, 304, 'I love kuroyukihime \n', 'As many others I came from SAO and AW and I hoped that i find a unique experience and a non traditional rpg with the characters and story I saw in the anime.\r\nWhile the characters are there, this game is not only not a really good RPG it''s not really a good game either.\r\nThe controls are ported from consoles to PC as an afterthought and it shows.\r\nThe graphics are leaning towards the bad side but I would say ok. (It''s ageing slowly like fine milk.) \r\n It had some hicups during gameplay (cuz it''s', 'Mostly Positive', 73.36, 21.40, 1.58);
INSERT INTO reviews VALUES (20306, 607890, 1424, 'Came for Asuna, then came for Asuna.  \nOn a real note, I really enjoyed this game. First time playing this style and I will definitely look into the others!', 'Bro i originally didnt want to write this but today this stroke really bad.\r\n\r\nFirst of all, do NOT buy this game if you''re playing it on pc with a keyboard, the designs are so poorly made a very frequently key you have to use is X, yea but you can change the keys bla bla bla No you cannot, theres like 200 other things you need and theres 0 space available.\r\n\r\nAnd the main reason i stopped, was because of the stupid damn gui. The New game button is litteraly above the fucking continue, so when y', 'Mostly Positive', 73.10, 100.00, 22.52);
INSERT INTO reviews VALUES (20309, 608120, 245, 'Score attack shooter from the developer of "TOP DOG", similar gameplay to Top Dog but much simpler.', 'If I can describe this game with a single sentence, it''d be "Bruh, what the hell is this balancing?!" \r\n\r\nIt''s not like the game doesn''t try to balance itself, it just does so in completely contradicting directions of what the game feels like it''s trying to be. For example, there is a cool down mechanic on your weapon of choice. Now let me say, it is really really cute that the game has this, like it''s not about to swarm you with more enemies that most horde shooters. It is utterly ridiculous th', 'Very Positive', 88.57, 22.30, 2.73);
INSERT INTO reviews VALUES (20315, 608530, 107, 'The Ship needs to upgrade from DOS to WinXP! I like the idea but could of been done with more in-depth hacking like trying to find code or something. \nA bigger budget version of this game would be incredible...imagine Alien Isolation mixed with Zork. You have to be aware of surroundings while you hack a complex state of the art space station...unlocking the truth.\n\nThe last Puzzle sort of ruined this for me...It wasn''t hard..it just lead to confusion. Also the protagonist is a pain to listen to ', 'Game is crashing after the 30 secs after the launching, no matter if I''m in the actual game or in the main menu. I have RTX4080, 32RAM, i7-14700. Can''t even find a solution online to fix this', 'Mixed', 40.19, 14.25, 0.20);
INSERT INTO reviews VALUES (20322, 608800, 466, 'This is the best dead game.', '849 trash achievements on Steam killed this game.', 'Very Positive', 80.69, 205.20, 14.63);
INSERT INTO reviews VALUES (20325, 608990, 214, 'good but need more people u should add full people in demo can play with full gamers if thay join there demo lobbie\n', 'Best game ever, you go in and you get the whole server to yourself. Its like meditating as a dinosaur.', 'Mixed', 53.27, 2.53, 0.82);
INSERT INTO reviews VALUES (20328, 609110, 453, 'Incredible bosses, npc and gameplay in this run and gun game . It is one of the few good run and gun games I''ve played lately in coop over remoteplay with my friend. I had asked for recommendations of run and gun games when Contra Operation Galuga came out and this was one of the games recommended to me, rightly so i''d say.\n\ncon - the save and progression system is a pain in the keester, ruining an otherwise mindblowing game.', 'This is not Contra, this absolute unbalanced garbage where you are just bombarded with everything on screen.  Contra was fair and had things spaced out nicely..  There is no place on the screen to go where you will not be hit. Hardly any defense or power ups ever drop. When they do you usually die immediately after grabbing it.  The power ups just seem to make the game more difficult anyway.  Feels like there is major input lag with some of them.. Oddly placed enemies where they are below your b', 'Very Positive', 89.40, 5.75, 4.42);
INSERT INTO reviews VALUES (20329, 609150, 909, 'Other than the characters in the cutscenes belonging in a wax museum... this is a solid offering.', 'The original was good, all remakes by Square Enix are bad without exception.\nTerrible company for years already.', 'Mostly Positive', 70.08, 3.00, 0.20);
INSERT INTO reviews VALUES (20336, 609490, 995, 'Minit is charming as most indie titles are. Its world is kinda whacky and kooky and being part of it for a little bit does feel special. Being a short game is actually a really good thing since spending any more time than I did would have definitely started to weigh on my patience a bit too much. I always appreciate when games try new things valiantly and so the gimmick of doing one run that lasts one minute (hehe Minit, I just got it now) is very refreshing. It does start to get very draggy aft', 'i like this game a lot, but the fact that the start up crash on this game was never addressed means most people coming back to this game cant use it anymore.', 'Very Positive', 90.55, 2.02, 1.85);
INSERT INTO reviews VALUES (20340, 609920, 618, 'Well, I bought this game imagining that would be a simple game to play for 1 or 2 hours.\n\nBut it have a very good mechanic and a lot of hard achievements that prolongs the game play.\n\nThe Expert level is hard and you will not be boring playing against them. And you will need to adapt your manage style dependent on the car that you choose.', 'I may have 11 hours in the game, but I cannot recommend it. The rubber banding is so strong that you could get out of your car, walk 99% of the race, and make sure to sprint just before the finish, and you''d still win. That also means there''s 0% chance of ever having a lead over the second place, even on normal difficulty it''s gonna keep up no matter how fast you drive. I beat all championships on Normal difficulty without even boosting, because the rubber band works pretty aggressively both way', 'Mostly Positive', 74.92, 9.18, 11.03);
INSERT INTO reviews VALUES (20347, 610180, 1874, 'My wife''s boyfriend and his friends love playing this! I recommend whole heartedly :)', 'made me realize im extremely  unfunny.', 'Overwhelmingly Positive', 95.14, 51.73, 5.50);
INSERT INTO reviews VALUES (20348, 610190, 233, 'Lu Bu is teleported to a FurFest convention. Along the way, he meets a talking, jingoistic cat, an Irish weeb with the ability to have English voice-acting in a game exclusively voiced by Japanese VAs, easily forgettable characters from Japanese-exclusive games and female, scantily clad girls with questionably young ages. He and his newfound friends have to commit mass genocide against furries in order to save the world from complete darkness and destruction.\r\n\r\nIf you think I''m making this up, ', 'Holy Furry Field Day!\nThe Hell even happened in this game?\n\nI usually take 40 - 60 hours on Musou games but I "beat" this on in under 10.\n\nBizarre combat system they used too. Wasn''t a fan', 'Mostly Positive', 75.97, 4.53, 9.75);
INSERT INTO reviews VALUES (20355, 610360, 592, 'If you''re a fan of puzzles and achievements, you''ve come to the right place !\n\n*** All ZUP Games have cool Puzzles + Trading Cards + a lot of working achievments ***\n\n+ Successes are letters in different colors that you can ideally use for profile design\n\n--> If you have the option, buy them all in a bundle to save money. You won''t regret it', 'This game is fun and all but its the same pattern again and again, Its boring so waste of money, Wouldn''t recommend buying it', 'Very Positive', 92.74, 5.82, 2.73);
INSERT INTO reviews VALUES (20356, 610370, 3863, 'Probably the best stealth action top-down game you will ever play. Good story, great gameplay, impressive level design and world building.\n\nRIP Mimimi.', 'boring repetitive gameplay. got bored in just few hours. i''ve played this game additional 100 hours and still find it boring + repetitive + steam re-review request shity. i paid for this product!', 'Overwhelmingly Positive', 95.99, 52.57, 1139.43);
INSERT INTO reviews VALUES (20357, 610380, 183, 'Really fun and underrated. I wish more people would play this because it''s hard to find someone to play with.', 'Tried for longer than 30 minutes to play with a friend but every time we couldnt see each other moving  or one of us couldnt see the other person etc. Multiplayer sure needs to be fixed. The game has a good concept, but the multiplayer is very bad and laggy.  I am sure that there aren''t people that are playing this game vs the bot because it would get very boring, so the only solution would be multiplayer.\nIf it gets fixed i recommend it but for 15 € it''s definitely not worth buying it. I have g', 'Mixed', 57.38, 2.70, 0.48);
INSERT INTO reviews VALUES (20361, 610500, 102, 'Another straightforward RPG/Adventure hybrid that I''ve enjoyed my time with. Differently, this at times can be difficult and you need have your tactics prepared before the battles.', 'Whilst I initially liked the game and found it quite good, the combat leaves a LOT to be disired. There is no strategy involved. Having placed my characters behind a huge rock, the enemy could cast spells straight through the rock and damage my characted. Not area of effect spells, but individual spells ie. magic misile.  My intent was to force the ranged enemy to come closer by having to navigate the obstacle, but no, they did not need to do that. They just got within the required range and bla', 'Mixed', 66.67, 14.65, 16.82);
INSERT INTO reviews VALUES (20373, 610750, 100, 'This is a pretty good game. Each chapter took me about 1.5 hours so it is a relatively short game but it is worth it. The story is generally good and the visuals are not bad. Overall I would rate this a 7/10. It is not a perfect game, but it is definitely not the worst that I have ever played. Also, no spoilers but I did NOT see the insane plot twist that happens in chapter 5 but the true ending definitely makes up for it.', 'Short visual novel with nothing all that redeeming aside a quick chuckle or two. Plus only fiove chances to make a decision, most of which were mundane ones. Honestly not pleased with the price point (on sale at the time I wrote this for $1.79), but at least got two achievements and another completion out of it.', 'Mostly Positive', 76.00, 10.08, 0.63);
INSERT INTO reviews VALUES (20375, 610810, 270, 'I let Hana decide which map i should play on ready or not and the ones she picks are all peak\n\n10/10 you should buy this game', 'utter slop', 'Mixed', 66.30, 7.15, 2.75);
INSERT INTO reviews VALUES (20377, 610860, 123, 'Funniest thing by far is that all the Japanese characters are drawn in anime style except one American guy named "Hank Johnson", who is just a normal person.', 'I loved this game as a kid but after buying a steam copy tonight it''s crashed 5 times in 39 minutes and it''s made all text in steam and my internet browser look extremely chunky and pixellated to the point that it''s difficult to read.  It''s bad enough for a game to not work, but if it''s going to break things beyond the game it shouldn''t even be in the store.  Definitely avoid.', 'Mostly Positive', 73.17, 5.73, 0.65);
INSERT INTO reviews VALUES (20378, 610900, 120, 'Fantastic point and click! Not as tough as the old Lucas Arts games but has a great story and is tons of fun.\r\nI really like everything I''ve played from Cloak and Dagger Games.\r\nHere''s hoping there''s many more adventures to come from them!\r\nThanks for a great game!\r\n(PS ignore my playtime, may have left it running in the background!)', 'Yandi tells a competent, short survival story in the somewhat informative setting of logging-ravaged Indonesia. It''s an OK play experience - the visuals, story, sound, objectives and music - it''s all OK (though the end feels a bit abrupt). It feels a bit like reading a news magazine article - adding the context of characters and visuals brought to life some realities of expansive jungle clearing, and there are a few frames that felt like unique visuals of life in Indonesia. However, like a news ', 'Overwhelmingly Positive', 96.67, 50.90, 2.92);
INSERT INTO reviews VALUES (20383, 611040, 308, 'love this game #tubing\nedit: after playing another 300 hours i can tell you its mid.', 'Man this game drags!!\nThis game is a whole lot of grinding the exact thing over and over again... Very repetitive and just not even automated, eventually it feels more like work than a game. Do not buy it unless there is a sale.', 'Mostly Positive', 74.35, 8.10, 12.22);
INSERT INTO reviews VALUES (20390, 611150, 374, 'Psychological Horror is the most appropriate tag for this game.', '', 'Overwhelmingly Positive', 100.00, 9.10, 0.00);
INSERT INTO reviews VALUES (20391, 611160, 892, 'This game plays a lot like a DnD campaign (I think). A deep dungeon dive, lore to be found various places, ambushes and traps all over, several encounters with npcs who give you missions, branching paths, big boss battles etc. I really like this and the general gameplay.\r\n\r\nThings it doesn''t do well: hitbox for melee weapons and the mining pickaxe is particular about where you strike and sometimes doesn''t register. The comfort options for movement are hidden in an "advanced options" section of t', 'Solo is too slow and boring, maybe with friends. Last content update was 2020.', 'Very Positive', 83.86, 18.20, 0.98);
INSERT INTO reviews VALUES (20392, 611180, 128, 'I just like to roam around in an open world and enjoy the destruction.', 'Non-licensed cars, but licensed parts.\nWhores dancing around in your garage the whole time.\nStupid AI.\nBoring races.\nGrinding achievements.\n\nAvoid like the black death.', 'Mixed', 45.31, 7.35, 7.28);
INSERT INTO reviews VALUES (20397, 611300, 285, 'If you love Socom you will love this. Great old school feel. Love how straight forward the developers are in their chats with the community. Cannot wait to see what is to come in the future and will be along for the ride. Worth it for me!!!!', 'Still not sure if this game is real or a scam', 'Mostly Positive', 72.28, 61.05, 3.83);
INSERT INTO reviews VALUES (20398, 611350, 163, '“If you believe it’ll work out, you’ll see opportunities. If you don’t believe it’ll work out, you’ll see obstacles.”', 'too evil', 'Mixed', 68.71, 7.28, 1.28);
INSERT INTO reviews VALUES (20400, 611500, 3775, 'I was happily surprised this game still has a community playing it. Quake just never gets old to me. Years later I start playing again and it feels like I never stopped. It''s just a lot of fun once you learn the movement mechanics and where all the ammo and hp/ap spawns are. I highly recommend this game to anyone who wants a fast paced arena shooter', 'The only reason why I don''t play QC anymore is because it just takes way too long to get into a game. Even if there are enough players to play. If I want to play an arena shooter that already has very short rounds, then I want to start the game, click on a server and then I''m immediately in the game. And when the round is over, the next one starts immediately. Just like in Quake live.\n\nYou don''t need graphically elaborate main menus. Arena shooters are fast food and should not have loading times', 'Mostly Positive', 74.46, 541.70, 189.52);
INSERT INTO reviews VALUES (20405, 611660, 4272, 'Mods are necessary. With that said, it''s super easy to mod this game. So please don''t let that stop you from trying this out if you''re interested. There''s tons of lists of recommended mods that make this such an incredible experience. I recently got a Quest 3 and am going to try out this nonsense with it', 'This is the laziest VR port I''ve every seen. you have absolutely 0# extra interaction with the world around you, you cant manually reload your weapons, and you cant even aim a rifle with both hands which makes using long guns accurately extremely difficult. They basically made a VR game that doesn''t have any of the the things that make a VR game fun. then on top of that they have the audacity to charge 60 dollars for something that should of been a free addition. they abandon this game shortly a', 'Mixed', 61.03, 20.42, 0.67);
INSERT INTO reviews VALUES (20406, 611670, 6919, 'The VR version of this is quite poor. ...... However modding it with the Mad God Overhaul it becomes one of the best things I have ever played or experienced. So with with I would be giving it 2/5 for standalone, 5/5 with MGO mod', 'I bootd up the game and the wagon started flying all over the place. Then it crushed the horse and I got softlocked. I rebooted several times and could not get past the gate.', 'Mostly Positive', 74.65, 90.02, 0.20);
INSERT INTO reviews VALUES (20411, 611750, 142, 'I played for a while and after these updates I can really tell it is worth it...unless you want some child kind of gameplay with bears and stuffed animals on cameras...\nThis is real horror...Im glad to still be alive cause my heart has been tested on this one.\nIf you want to fall from your chair and be scared to death then...welcome to Hanwell!\n\nTotally recommend it ♥', 'Do yourself a favor and just get  Beyond Hanwell Its better than This game.\nThis game is really really rough around the edges. I Do hope that Steel Arts, Remakes This game with BH''s Game Mechanics. I will say it was a real smart idea to make this into a Free to play game.\n\nI''m still holding on hope for a reamke tho.', 'Mixed', 47.18, 17.53, 11.63);
INSERT INTO reviews VALUES (20412, 611760, 1278, 'I played both the trilogies; Don''t Escape and Deep Sleep, and also Primal Sands. I played these multiple times so I am quite familiarized with the story, and let me tell you its very well put together. This game however ties it all in such a sublime way. The Night Folks are mentioned in some notes and can appear during the gameplay. Also the blue crystals are mentioned on other notes that explain how they interact with the story background. And considering both these objects were introduced year', 'Puzzles are unimaginative, music gets annoying. "Overwhermingly positive" is odd, there are tons of better games in this very old genre.', 'Overwhelmingly Positive', 99.06, 24.97, 17.67);
INSERT INTO reviews VALUES (20414, 611790, 6113, 'a lot of NSFW games tend to front load the nsfw and treat gameplay as secondary. this one really puts the game before the NSFW content. even if you follow a guide to get to the *cough* desired ending of the game *cough*, (pardon my throat!) you will have played out an entire sexual comedy film plot straight out of the 90s. \r\n\r\n a lot of games like put you in the role of some guy who is supposed to be like a general looser or something. but here you can choose a gender, which comes with its own l', 'This game is kind of fun, but way too particular about your choices. Half the missions require you to break into the booze stash, and then Frank fucking obliterates you and it''s game over. I can''t even count how many times I had to start over, just to get a little further and knocked out again.\r\n\r\nAlso, not nearly enough romance options for straight women. Like.. cool, there''s boobs. How about some actual men I can try to hook up with besides lame ass Derek and drunk ass Patrick?\r\n\r\nI understand', 'Very Positive', 88.03, 9.02, 6.10);
INSERT INTO reviews VALUES (20415, 611800, 179, 'You know early access indie racing games are good if the developers didn''t bribe TheSLAPTrain to play it.', 'In later updates i can see this game be great\nbut for now this game have a fame rate that says 3.\nit have been forever sinds last update...\n\ni do not recommend to buy this game right now', 'Mixed', 55.31, 14.82, 6.92);
INSERT INTO reviews VALUES (20423, 611980, 225, 'kind of a boring game,\nbut those achievements are still cool,anyway.', 'Let''s be honest, the only reason one will get this is for the achievements.', 'Very Positive', 90.67, 6.27, 10.52);
INSERT INTO reviews VALUES (20430, 612100, 128, 'A really small fun game, with different path to different ending. Content not explicit enough where you wish more and more explicit actions, heh.', 'The game is ridiculously short, the pacing is entirely too fast, and not a single one of the characters in this game is likeable.\n\nIt''s like somebody took The Mummy (1999) and removed all entertaining parts.', 'Very Positive', 89.06, 5.78, 1.23);
INSERT INTO reviews VALUES (20431, 612110, 151, 'A cute, funny story about a Dryad and her quest to seduce her witchy employer. There''s a decent number of CGs, most of which are pretty tame by some standards, but they were still very nice.  I wish there was a way to  be with the mermaid instead of rude Amethyst, and to relocate her to the lake so that she was less stinky, because the mermaid was very sweet. Maybe there will be a sequel or something!  Overall, it was definitely worth the time and money.', 'This is a rude and dirty story without any love. It''s not worth your time or money.', 'Mostly Positive', 75.50, 4.18, 1.35);
INSERT INTO reviews VALUES (20443, 612300, 126, 'I remember buying this game when I was a kid and playing it for hours. I was excited to rediscover it on Steam. I love this game and would highly recommend it to anyone who enjoys historical RTS games.', 'Unless you''re living on an extreme budget here on Steam or you''re an old hand just out to experience a little nostalgia, I wouldn''t recommend buying this game. In view of the changes and development in the RTS genre over the past years, Sudden Strike is pretty much like an ageing hag who saw her best days long ago.\r\n\r\nThis game may have stood out with its innovative gameplay mechanics back in the early 2000s and was certainly unrivalled in the attention to detail regarding the representation of ', 'Very Positive', 88.10, 6.95, 10.45);
INSERT INTO reviews VALUES (20445, 612370, 256, 'Underrated masterpiece, the gameplay is addictive, the soundtrack is so good and fits with the game. You should try it if you can.', 'Seemed like a fun casual game so I bought it. It turned out to be a fun casual game. Only problem is, it''s broken. Using a good portion of weapons will cause horrible stuttering (no matter the machine you''re running it on). Bug was reported almost a month ago but wasn''t fixed or even acknowledged by the devs, so no, I don''t recommend this one to anyone in the current state.', 'Very Positive', 94.92, 6.57, 1.73);
INSERT INTO reviews VALUES (20447, 612390, 351, 'The game is a little fetch-questy in the late game when it comes to fulfiling the conditions for the true ending, but other than that this is a beautiful and fun game. The art and music are gorgeous and the mechanics and lore are inspired. I started and finished this right after the 2024 election so playing a game where you fight as the literal avatar of creative freedom against an oppressive regime really hit for me and cemented that freedom and art and expression are something that''s always wo', 'this got to be one of the most unentertaining games I''ve ever played. felt literally nothing playing it. feels like devs just made a check-box list game (it has this and it has that and everything else) but forgot that games need to be entertaining and this game is just not. \n\n   battles suck (also enemies design is awkward, why am I fighting some furries with medieval weapons lmao), \n   platforming nonexistent (you can pretty much just spam jump 99% of the time and be just fine), \n   metroidvan', 'Very Positive', 82.91, 11.27, 1.55);
INSERT INTO reviews VALUES (20450, 612470, 889, 'Somehow this game left a huge impression on me after just 3 hours. I''m no doctor, but the "Life" mode really makes me feel like one. A small-time doctor with limited influence. Allow me to explain:\n1) To diagnose something, prescribe treatment or convince your patient to eat healthily, you need bio points. So you need to decide which one of those is more important. \n2) Diseases have a "hierarchy". Someone can''t have a heart attack if they don''t have arrhythmia. And they can''t have arrhythmia if ', 'This game is fun, HOWEVER, even if you have 5 systems collapsed and are about to kill the patient, if the doctor heals just enough you lose. Its really annoying and honestly makes the game unplayable for me. If youre fine with being close to winning and the person is practically dead, then you lose because sudden hair loss was treated, this is your game.', 'Very Positive', 87.06, 15.62, 8.18);
INSERT INTO reviews VALUES (20454, 612570, 411, ' 🏆 Overall rating: 8.5/10 \nThis is truly one of those great games that not many people know about.\nWith 3 races, 4 character classes, each class has a different way of building a skill tree, combined with positive/negative characteristics, making the game much more diverse and interesting. The interaction between the environment and the game''s skills is a point that I appreciate. Collecting items, skills and resources on the map will help your army become stronger.\nWith 3 levels, it is enough to', 'This game focuses on all of the least fun aspects of tactical turn based combat games.  Combat is heavily based on your ability to push enemies into rocks... or rocks into enemies.  Really?  When you were designing the game, you were like "We could either have really cool abilities... or we can have people push rocks around."  And you chose the rocks!?!  \n\nYou do have some weak regular attacks that don''t involve throwing rocks... but those are heavily penalized by percentage based cover mechanic', 'Mostly Positive', 76.64, 38.98, 0.82);
INSERT INTO reviews VALUES (20462, 612720, 752, 'The fact that this developer keeps chipping away and has stuck with this project and not abandoned it like so many other developers is an absolute win. Well done good sir', 'Yeah .... I found it really boring. Tried to like it, but with games like Manor Lords and BellWright out there, it feels extremely dated. Combat is shockingly poor.', 'Very Positive', 85.90, 1.23, 14.20);
INSERT INTO reviews VALUES (20469, 612880, 15812, 'My grandpa from Argentina loved watching me play this game! Especially when you got to meet the Führer. 9/10, the only thing I didn’t like is that my grandfather was extremely upset whenever I killed the Nazis.', 'Wolfenstein 2 is still a one of the best, if not the best Wolfenstein game in 2025, expecially when you want to kick some nazi ass. Great Story, great Weapons, still incredible looking graphics.\r\nBut why do i give it a negative review? Well, there are multiple, well documented, unfixiable crashes in the game that bethesda JUST WONT F**** FIX.\r\nIf you, like me, want to 100% this game and collect everything, SAVE AFTER EVERY PICKUP! This Game WILL CRASH and it WONT SAVE YOUR COLLECTED ITEMS!', 'Mostly Positive', 77.84, 22.77, 13.72);
INSERT INTO reviews VALUES (20471, 612930, 359, 'Thank you Caddicarus for introducing me to a niche fighting game indie dev who ended up making a FAR better game (Fight of Steel) - but my friends still like this one best.', 'It''s alright, but it''s definitely not what I expected. There are four different attacks. light, medium, heavy, and grab. from the characters I played it seems like every character just has the same four inputs. It makes it easy to learn the characters I guess, but I think it would be cool if the inputs actually did something different depending on if you use a lighter or heavier attack, but instead it just makes the move go a slight bit further. I think the way they did it with Jesus'' down forwa', 'Very Positive', 83.29, 0.95, 0.48);
INSERT INTO reviews VALUES (20478, 613190, 448, 'The first game I played on my Steam Deck and what a great experience. As a big fan of Hollow Knight, this scratched a similar itch, with a much more restrained scope and scale. Bosses were challenging, but fair. They each required careful planning and I enjoyed determining their patterns. My main complaint is that there a few areas that had multiple hyper aggressive enemies on a single screen, which was a pain in the butt to proceed past. Otherwise I absolutely loved the game!', 'Poorly made game. No soul and boring.  The game fights itself and begs not to be played. Hard enemies? No annoying traversal and stupid elevator mechanics. Many other better 2d souls likes absolutely an abomination', 'Very Positive', 80.13, 13.48, 4.02);
INSERT INTO reviews VALUES (20483, 613270, 112, 'best', 'this game is everything i would expect from a bad game. Bad meshes, bad coding, full of glitches, bad grahpics and the list goes on. Although it does have it''s charm.', 'Mixed', 58.04, 3.25, 0.45);
INSERT INTO reviews VALUES (20487, 613390, 157, 'Beats most AAA titles in terms of depth and playability. Definitely recommended.', 'Not really a fan of the whole  indie games pretending to be CRPGs when they are clearly ARPGs at best. Four virtually set in stone stats, plus Diablo''s gimped equally fixed dumb down *health* and *mana* system being proof this is an ARPG LARPing as a proper *Pool of Radiance* or *Baldurs Gate* style RPG sorry.', 'Very Positive', 87.90, 1.97, 8.97);
INSERT INTO reviews VALUES (20491, 613450, 120, 'i played it the way i live my depression at first: stay in bed, watch vids without capturing info, binge eat, take a shower to temporarily feel okay again only to fall back, coming late to work a few times in a week.... and yeah the narrator did not hold back. some of his sentences hit close. the better route is smth i know i need to do...... bu im so busy beating myself down.', 'This game is like peering into the mind of the kind of guy you’d swipe left on so hard it might break your phone. He’s basically a walking red flag factory, and the game unintentionally showcases exactly why you’d want to steer clear of him. Let’s dig into the traits that make him undateable and why this perspective is such a dumpster fire of relationship dynamics.\r\n\r\nWhy You’d Never Date This Guy\r\n\t1.\tHe’s an Emotional Black Hole:\r\n\t•\tHis entire emotional world revolves around what others can d', 'Very Positive', 92.50, 4.50, 3.53);
INSERT INTO reviews VALUES (20492, 613470, 172, 'This is a point-and-click adventure with a unique world and captivating story. This sequel takes things up a notch, boasting even more cuteness, an expanded storyline, the signature humor fans adore, and engaging puzzles.', 'Enjoyed the first game and was happy to play this sequel. Liked the artwork and although it wasn''t as charming as the first one, I was enjoying the ride. But ... the game is broken. Maybe it''s because I''m playing on Linux. As soon as Chapter 1 ends, the game just crashes. So.. just got 1 chapter out of this. Sad.', 'Very Positive', 87.21, 2.83, 23.55);
INSERT INTO reviews VALUES (20499, 613730, 189, 'I like this because drinking', 'Very realistic ;)', 'Mostly Positive', 73.02, 0.72, 0.08);
INSERT INTO reviews VALUES (20501, 613830, 5829, ' For years a heard people say that Chrono Trigger is one of the best game ever made and i aways thought its was just the nostalgia talking, but now i''ve played the game and i can say my own opinion:\nTHIS IS ONE OF THE BEST GAMES EVER MADE!!\n\nThank you for the art, Akira Toriyama.\n', 'While the game itself is kind of incredible... I found the port to be buggy?\n\nI mean, it plays flawlessly when it''s actually running, but I''ve only put a few hours into it and already I''ve found a few consistent normal gameplay actions that will crash the game guaranteed. Which isn''t surprising, if this is indeed a PC port of the mobile game port of the DS remake... I note that all 3 of the previous links in the chain *also* had a lot of complaints about crashes.\n\nI lost about half an hour of pr', 'Very Positive', 88.18, 24.23, 0.98);
INSERT INTO reviews VALUES (20504, 613880, 730, 'get planet zoo for complexity, get this game for simplicity, if you want a more simple zoo tycoon game you wanna get this, also cool to see all the animal interactions', 'Very little customization, kinda sucks. Also I can''t delete the walls of the enclosure and unleash my lions onto unsuspecting visitors, so 0/10', 'Mixed', 57.26, 18.17, 1.60);
INSERT INTO reviews VALUES (20524, 614570, 4456, 'The playing time is relatively short, the areas are structured more like a sandbox and you have around 5 levels with tasks, as well as the option of how to complete the mission (example: bring a target person to person A or B, your choice), which brings a bit of variety.\n\nDue to the lack of a long-winded story, it suddenly plays like a quick Hitman level, i.e. spawn, kill the target person and disappear again, either stealth or full action. You can like it.', 'Very short, boring powers and overal very easy. This should have been 5$ DLC for Dishonored 2, not standalone game.', 'Very Positive', 85.73, 5.85, 10.08);
INSERT INTO reviews VALUES (20525, 614630, 301, 'Old old old game but, it has the chill factor of 1000! Going to different train stations across the world, Customizing your train sets as well, it''s pretty awesome!', 'The devs abandoned this game, do not buy it.\nIt''s free on mobile and with easily twice the content', 'Mostly Positive', 75.75, 6.67, 2.95);
INSERT INTO reviews VALUES (20537, 614910, 198, '#monstercakes\n\nHas a total of 5 trading cards.', 'Fun game and nice for the item drops but is absurdly heavy on the CPU for what it is so hard to recommend compared to others.', 'Very Positive', 84.34, 30.47, 6.53);
INSERT INTO reviews VALUES (20538, 614950, 112, '"Money can''t grow on trees"\n\nMFER... you have not seen what I''ve seen', 'Ambiguous mechanics, wonky hitboxes.  Movement feels file, weapons feel good, but enemy encounters and puzzles are unpleasant.', 'Very Positive', 81.25, 3.92, 0.90);
INSERT INTO reviews VALUES (20541, 615010, 108, 'A hack-and-slash indie game with a twist\n\nWhile it has its shortcomings of a VERY indie production, the overall experience is highly enjoyable. Grab your axe and dive into this dwarven adventure, you won''t be disappointed!\n\nNote: it is coded by the guy behind Death Trash', 'This is somewhat enjoyable, but the gameplay is too clunky.  Your attacks continue on for at least one attack after you try to stop them.  Why you are attacking this difficult to control if more than one optic.  The graphics are the blockiest I have seen in an isometric RPG.', 'Very Positive', 87.04, 0.80, 11.40);
INSERT INTO reviews VALUES (20545, 615120, 1807, 'This is fantastic one of the best VR games.\r\nEvery aspect of the game is pure class. \r\nWhat really makes this stand out from numerous other VR shooters is the lack of any jank. If you die in the game it is because YOU did something wrong.\r\nThere is a real challenge here if you play this on any setting above easy and that is what has kept me playing for 22+ hours.\r\n', 'The graphics look very fine. That''s where the positives end.\nThe negatives are: very boring gameplay, really boring interactions with guns (nothing to fiddle with, just point and pull the trigger), very uninspired basic guns, very uninspired basic maps, very uninspired basic enemies. The rogue-lite part is that when you die, the run is over. The description claims that the dev is looking for feedback, but the game''s development cycle is pretty much over. The game is so basic that it basically be', 'Overwhelmingly Positive', 97.45, 31.42, 1.93);
INSERT INTO reviews VALUES (20553, 615350, 106, 'A stereotypical Casual Hidden Object Point & Click Adventure game.\n\nNot exactly thought-provoking. Only takes a few hours to fully complete.\n\nMostly a bit of leisurely wholesome fun that doesn''t take itself too seriously.', 'This game is pretty but dear gods the ending is problematic. Surprised more people haven''t mentioned it', 'Very Positive', 89.62, 2.58, 2.83);
INSERT INTO reviews VALUES (20558, 615530, 217, 'An alright Visual Novel. It very often drags on, and some paths are noticeably WAY better than others (I would honestly recommend you to skip Kagome''s entire route, seriously screw that woman) but there are some good moments and the Ellie and Himitsu routes are pretty great.', 'As a lover of Everlasting Summer i can not recommend this game. The main character is an asshole with depression problems that leads you to make only stupid choices that out of the 3 two of them are pretty much the same. Worst part is no matter what you do you cant seem to get the main character to do any real changing development. The only thing i can say positive about the game are:\n- The girls are cute( and great personalities )\n- Music gets an A+\n- Thumbs up for the Art style\nand honestly ma', 'Mostly Positive', 76.50, 95.95, 16.42);
INSERT INTO reviews VALUES (20561, 615610, 1480, 'Very simple gameplay (only thing you do is press the RMB at the times and for as long as you think it''s right), yet kinda addictive in a "one more try!" way. Reminds me of gaming in the 80s/90s. I like it!', '\r\nOne button game where you orbit around the wormhole while avoiding falling planets, asteroids and other rubbish. Again, I expect something much better on PC than that.\r\n', 'Overwhelmingly Positive', 97.09, 1.38, 1.20);
INSERT INTO reviews VALUES (20568, 615730, 136, 'Nancy Drew: The Final Scene is a captivating and thrilling game that has left a lasting impression on me. I have fond memories of playing this game with my father during my childhood, and it remains one of the best gaming experiences I’ve ever had.\n\nThe game is set in an old theater, where Nancy’s friend Maya goes missing. The storyline is engaging, filled with twists and turns that keep you on the edge of your seat. The puzzles are challenging yet fair, making you feel accomplished when you sol', 'I couldn''t wait for it to be over. Super boring, anti-climatic. Very small set-up for game play and very small amount of inventory that you pick up. Not exactly aesthetically pleasing either and didn''t love any of the characters.', 'Very Positive', 80.15, 4.23, 3.28);
INSERT INTO reviews VALUES (20569, 615770, 219, 'Not my favorite from the ND games I''ve played since it felt fairly short and the dialogue and voice acting felt a bit limited, but also not ashamed to admit that it was immersive enough to scare me more than I thought it would! It was also a fun way to learn about San Francisco history and draw Chinese characters, learn the zodiac order, etc. Some of the puzzles and conversations were confusing and easy to get lost in, especially with the journal being locked in her suitcase and not having the u', 'Out of all the Nancy games I have played, this one is my least favorite. I love the concept but half of the notes are basically inelliglble and there is no clear guide of what to do next, i swear that is the most times I have ever called George and Bess', 'Very Positive', 84.47, 4.20, 12.72);
INSERT INTO reviews VALUES (20570, 615780, 201, 'My first and all time favorite ND game. I first played this on a giant, clunky Dell desktop right after it came out. It was the day after Christmas, late at night, and it was snowing. The ambiance was perfect. This is an excellent introduction to the series if you''re just starting out.', 'I had the same issue with older Nancy Drew game as well, but it''s quite tedious and not smooth/rewarding that you have to redo the puzzles that you''ve already solved just because those puzzles are in the way...', 'Very Positive', 84.08, 3.75, 5.93);
INSERT INTO reviews VALUES (20576, 616110, 1931, 'You can''t lose, but it scratches a specific itch for upgrading things efficiently. The aesthetic is cool, and I gotta say the music is right up my alley. Won''t last you long, but nice while you''re playing.  Picked it up for $1 on a steam sale and was a good decision.', 'I cant honestly recommend this. The story is brilliantly wacks, the soundtrack is magnificent, the visuals are really cool - but the problem with all of it (at least for me, ymmv) is that it''s wrapped in an incremental/clicker game that just... isnt incremental. You very quickly get to a point where you cant really unlock anything new, your upgrades barely matter (x2 earnings from one thing, as a "lategame" upgrade in a game like this? come on...), and you''re just left with tedium to see what''s ', 'Very Positive', 90.26, 3.52, 7.17);
INSERT INTO reviews VALUES (20579, 616250, 1100, 'I had enough fun with Crystalline to give this an recommendation if you can get it on discount.\nPixelfade has its own take take on well known  tropes.\nThis VN is worth your time, the less you know the better experience.\nPixelFade: Please  make Crystalline 2.', 'I know I haven''t played long enough to form a complete opinion, but I quickly  understood why some people say, "The story is average and the characters aren''t memorable," and still recommend the novel. Despite a story that hasn''t done anything exciting yet, some of the dialogue choices are hilarious and I found myself smiling throughout the entirety of my play. But once I stopped I found nothing to pull me back to it, and whether I''d recommend it or not ultimately comes down to one thing:\r\n\r\nIt''', 'Very Positive', 94.27, 20.47, 0.35);
INSERT INTO reviews VALUES (20585, 616560, 5214, 'A good game to download, play for a few hours, and then uninstall for three years.', 'There is an inherit problem with games with no limitations. People who are given unlimited answers will always struggle more than those who are only given three. UEBS ultimately gives you the power to simulate large battles, but what for? For what reason? The resounding result is battles resulting in tens of thousands of soldiers, but, between the frames, what are you watching? There''s not much intrigue to watching pre-programmed AI fight a meaningless battle in the modern day.\n\nUltimately, this', 'Mostly Positive', 76.75, 10.83, 4.47);
INSERT INTO reviews VALUES (20595, 616720, 193, 'Recommend for people in to anime and live2d stuff. I can see my lovely waifu everyday on my pc and smartphone there are available to download in the same name on ios and Android.\n\n', 'I bought this for the free Shondo L2D Wallpaper she posted earlier and the software is just bad.\nUI is extremely cluttered and badly explained. Also the "Wallpaper"-Mode is not a Wallpaper mode, it''s just a flying layer with permanently clickable buttons. Maybe those are possible to turn off but that the software just can''t manage a wallpaper with a wallpaper mode is just lame.\n\nAlso it is a ressource hog. Only used one 8MB Wallpaper of Shondo and the App wanted up to 2GB of my RAM, ate almost 1', 'Very Positive', 89.64, 19.53, 0.15);
INSERT INTO reviews VALUES (20605, 616920, 134, 'its one of the best ones, I like it when I first time entered start of 2000 and its still nice^^', '"this game features in-game purchases that directly increase the power of your character, as well the rate at which they gain experience and gold". This sound like pay-to-win to me.', 'Very Positive', 84.33, 18.80, 2.52);
INSERT INTO reviews VALUES (20607, 617030, 152, 'The game has huge growth potential, and can’t wait to see what they add.  The biggest thing for me is the developers with the game.  I’m sure you read the negative reviews just like I always do and some of it is true.  There are a lot of things that need work but you can look at the discussions on how they respond.  I have got a response every time I have had an issue.  These Devs are committed to make this game awesome.  That alone would make me support them.  The content gets better every day.', 'This game should be free in its current state.', 'Mixed', 48.03, 144.47, 0.73);
INSERT INTO reviews VALUES (20609, 617160, 522, 'By far one of the coolest horror games I''ve ever played!! I don''t think I''ve ever experienced a game that scared me quite like this one has. The atmosphere and the story had me so focused on what I was doing that specific times in the game really jolted me and gave some very solid scares. \n\nI suppose my only complaint would be that the hide and seek mechanic was a bit over done and almost made certain parts of the game not really enjoyable to me. This is, however, a personal preference of mine b', 'This Game just ruins the fun by having too many scripted moments and having the school girl ghost thingy be so slow at walking ad also having the most sensitive  ears known to ghostkind. The game also relies on its notes too often to serve at its story.', 'Very Positive', 81.23, 6.77, 2.63);
INSERT INTO reviews VALUES (20611, 617290, 23326, 'Diablo, Dark Souls, The Division and Hellgate London, mix them in a bowl and you get Remnant from the Ashes. In the game, Earth has been rendered uninhabitable by an invasion of demonic beings from multiple dimensions, and humanity is on the brink of extinction. As a member of the Remnant, the last surviving group of humans, we set out to find the place where the evil beings came from and put an end to it. The gameplay is a shooter with a mix of action, RPG, and spiritual genres. Throughout our ', 'Developers: "Hey, we''ve made some pretty cool bosses here. Now, let''s fuck everything up by adding random, annoying enemies to LITERALLY every single one of them."', 'Very Positive', 86.83, 34.50, 26.42);
INSERT INTO reviews VALUES (20618, 617480, 1284, 'This game is a hidden gem in the RPG genre – it definitely deserves more attention. You can see that it was developed passionately by people who love their work. The mysterious and captivating story takes you to a tower buried upside down in the ground to unveil its hidden secrets. The combat system is quite original, as the battlefield occurs in a more detailed location than the standard map. The real-time/pause mechanics enable players to carefully plan their actions against approaching enemie', 'I didn''t manage to stick to the end. I just failed to connect emotionally with the characters, and the combat and exploration became a bit of a chore.', 'Very Positive', 84.42, 4.78, 19.43);
INSERT INTO reviews VALUES (20631, 617670, 2708, 'It has achievements with letters and other symbols that you can use to decorate your steam profile. But it isn''t a dummy game just for that, Zup! S is actually a fun and short puzzle. That''s a good combo!', 'A very pointless game. Everyone buys this game only for its achievements and nothing else.', 'Overwhelmingly Positive', 96.90, 0.48, 1.03);
INSERT INTO reviews VALUES (20634, 617700, 529, 'As a fellow stoner, I can say that I really appreciate this game. It runs great, and is a ton of fun to play. The Weed Shop 2 is a shop simulator game where you own and run your own marijuana store, leveling from the ground up. Besides selling weed, you can also explore the beach and the boardwalk and find some interesting treasures. Not only that, but some customers do yoga on the beach where you can hear them fart. No cap, on GOD. Once I max out this game, I''ll try out Weed Shop 3!', 'This game has gliches with clipping through the floor and ceiling.  Workers wander to other areas of the shop and you can''t get them to perform their duties until you quit the game and start the game again.  This is getting old and I may stop playing all together because of these issues if not fixed.  I could have made a much better purchase.', 'Very Positive', 84.12, 6.67, 48.30);
INSERT INTO reviews VALUES (20638, 617830, 5577, 'Great, I''d however recommend downloading an older verion for the full experience. to do this, press windows+R and type steam://open/console. When in the console, type "download_depot 617830 617831 6114012175981140194" and replace the game files with these.', 'I used to say this was the best game for VR, but I can no longer recommend you buy the game from Steam, as the Steam version has had vital content cut and no longer recommend you purchase it here. I would recommend you find and play a version from prior to 2021, although Steam is not currently selling it on this storefront.', 'Very Positive', 80.89, 7.83, 8.47);
INSERT INTO reviews VALUES (20639, 617850, 154, 'This has improved a lot but still needs time to cure and iron out the issues here and their. Get it on sell and for the price its really not that bad. Just give it time. Will recommend.', 'The best example of a game which turns up running on your sound device instead of your GPU, that''s why it has same low performance/stutter no matter your spec high end or low, no matter your graphic settings ultra or low, because it uses not your GPU and not even your CPU to render, it blandly using your Sound Card to render. It took me headache pills and 21 hours to understand :D\n\nI strongly believe if production company release this game and code with free licence, modders and community would ', 'Mixed', 57.79, 8.43, 21.45);
INSERT INTO reviews VALUES (20648, 618100, 116, 'They have the best game ideas in the world ,but seldom have the ability to find the right guys to realize them,and worse yet,they don''t have any talent in running a company and dealing with it''s capital-related issues .Ladies and gentlemen, I give you: the Russian developers.', 'dead men tell no tales and dead games get no praise.\nRIP\n2/10', 'Mixed', 52.59, 3.33, 0.25);
INSERT INTO reviews VALUES (20649, 618140, 634, 'it has cars, they go vroom.', 'Barro is a series of eight copy/pasted, generic racing games. The car controls fairly poorly, and there''s no drifting so turning is clunky. There are no powerups or any interesting extra features. It''s the absolute bare minimum for a racing game - just go around in circles on a track. The tracks, while shaped differently, all use the same assets. The only difference between any of these games is different cars and tracks - they all use the same sound effects, menus, game modes etc. They really o', 'Very Positive', 81.23, 0.15, 3.53);
INSERT INTO reviews VALUES (20664, 618510, 165, 'Battle Bruise is a hilarious ride! The wild characters and outrageous moves had me in stitches. Every match feels like a cartoon brawl, and the chaos is just pure fun. Perfect for some laughs and epic battles!', 'Do you like unbalanced gameplay? Do you like paying actual money for a game that could have been found for free on CrazyMonkeyGames in 2006? Do you like the inability to adjust sound levels in the options? If you answered yes to any of these questions, than what the hell is wrong with you? Also this game might be for you.', 'Very Positive', 94.55, 69.37, 0.17);
INSERT INTO reviews VALUES (20670, 618610, 102, 'Endless Horde\n\nHas a total of 7 trading cards.', 'pretty "meh" , get it for card drops i guess', 'Mixed', 60.78, 0.60, 0.92);
INSERT INTO reviews VALUES (20677, 618720, 510, '1bitHeart\n\nHas a total of 9 trading cards.\n', 'Grinding the friendship system is super tedious and all the blatent TWEWY copies are cheap as heck. Inspiring yourself is fine, but don''t just copy that one math-obsessed gimmick to your own OCs...', 'Very Positive', 92.75, 1.57, 7.72);
INSERT INTO reviews VALUES (20678, 618740, 755, 'Man my music taste so obscure I''m getting high scores on "Unidentified song". Great game btw.', 'It was a''ight. To me it seemed like songs all played and looked the same. I could barely tell it was moving to the song. \nI miss Audiosurf from back in the day... that game actually felt like I was riding the song itself. This seems to be ... loosely tied to the song a little?? Strictly on whether it was an okay experience, I would say yes. But because it was so disappointing from the perspective of a game "POWERED BY  MUSIC", I would not recommend it.', 'Very Positive', 90.86, 7.90, 0.43);
INSERT INTO reviews VALUES (20682, 618850, 296, 'i love this game to bits.', 'Don''t buy it, it''s really bad. Jank. Movement is stupid, and most of all, doesn''t start off right to help you understand what to do very well. I don''t even know what to do!', 'Very Positive', 80.41, 701.60, 0.28);
INSERT INTO reviews VALUES (20683, 618920, 151, 'A simple but fascinating roguelike game for VR. Budget graphics, but there is a dynamic gameplay. Short sessions, little content.', 'I could not open the drawers normally. At some point I thougt that they are decor so I got stack.', 'Very Positive', 80.79, 9.85, 0.63);
INSERT INTO reviews VALUES (20684, 618950, 151, 'Anti-vegan propaganda', 'It''s a cute game, I adore the graphics. But...it''s not really enjoyable to play. There''s entirely too much dialogue that just isn''t necessary and it makes the game drag.', 'Very Positive', 92.05, 5.87, 0.58);
INSERT INTO reviews VALUES (20685, 618970, 318, 'No "re-imagining", "tailoring it to the current audience" or "adding a few new artistic ideas" bs. \nJust an already perfect game updated with better graphics.\n\nNow if someone could redo Gothic II and VtM Bloodlines the same way, my life will be complete.', 'Steam needs a yes but no review option. I paid $2 for this, so yes, it is playable, but it is ridiculously dialogue heavy, and full of vague quests. You have to do some things in the right order, or options are not available, meaning you just run around in circles. Hopefully the sequel is a lot better,t he potential is there.', 'Mostly Positive', 79.25, 10.05, 13.78);
INSERT INTO reviews VALUES (20688, 619080, 1049, 'Get into my first game. Find a flare with a friend. Proceed to set off the flare. We get the supply drop off of a roof. Find some sort of bomb. Surrounded by other players asking for free loot. My friend punches the bomb and we die. 10/10', 'rip off', 'Mostly Negative', 26.02, 5.23, 18.92);
INSERT INTO reviews VALUES (20691, 619150, 2995, 'This is an educational game wrapped in a puzzle game that teaches high level concepts of machine level concepts.  If you''ve been wanting to test the waters of ML, this might help you visualize the jargon that you may have heard.   I highly recommend reading all of the supplemental information that the various missions give you as well.   I''m enjoying this very much.', 'I am a software engineer, and I worked on machine learning frame works.\n\nThis game is very bad at explaining what it wants you to do, which makes the puzzle confusing instead of challenging.', 'Very Positive', 88.51, 19.65, 1.18);
INSERT INTO reviews VALUES (20692, 619210, 196, 'Not really worth the $15, but the creator definitely should get some compensation for actually doing the math', 'Its a cool idea, but you''re paying $15 for something you get bored with in an hour. I wish there were more features, or maybe a custom builder just to raise engagement', 'Very Positive', 87.24, 3.77, 0.65);
INSERT INTO reviews VALUES (20697, 619280, 289, 'This game is a simple and straightforward roguelike, perfect for casual play. While it may not have deep elements to explore or extensive content to keep you hooked for hours, its rough charm makes it ideal for light and enjoyable gaming sessions.', 'Dead Cells-like game but:\n\n- much slower\n- no persistent growth\n- extremely limited weapon types\n- extremely repetitive due to limited enemy types and environments\n- The entire game loop revolves around memorizing enemy move sets instead of making any kind of build, having cool abilities or fluid combat\n- speaking of, combat is really rudimentary\n- difficulty is poorly balanced and the game very clearly artificially pads its content by punishing you with it, and no it''s not "git gud", I enjoy ch', 'Very Positive', 83.39, 3.13, 0.52);
INSERT INTO reviews VALUES (20704, 619390, 242, 'The issue is i feel devs wanted someting fresh and new in 2021 game (you cannot blame them for that). If you are new to this product it is w/e (overall okish) but if u played in 97/98 orginal products then during gameplay u will feel this emotion like you missing something (like a piece of puzzle).\r\n\r\nThe best solution is just to accept the fact this product is something else even if it looks similar. Just adapt to it and split old with new.\r\n\r\nOverall game is cool i would recommend', 'You had one job.\n\nGive us a competent remake of Exoddus alas New and Tasty. Instead you cooked up this unsightly abomination that bastardised the story, feel and setting of the original game.  I couldn''t even suffer 30 minutes of the tutorial before shutting the game off. If you are looking for a good successor to New and Tasty, this isn''t it chief.', 'Mixed', 61.57, 70.83, 0.57);
INSERT INTO reviews VALUES (20710, 619500, 862, 'Had this game wish listed for a long time and saw how much time the dev was continuing to put into it. Finally bought and played it and...wow... can''t believe I waited this long!\r\n\r\nThis game really takes advantage of the change in experience that VR provides. Making your first furnace takes a while, with carefully placing many blocks in the right spot. But by the end you feel like you deserve to start smelting that iron!\r\n\r\nI''m having a great time so far and already look forward to jumping back', 'It just need a lot more of everything. It''s beautiful but there isn''t enough to do. Only one way to die - falling. No enemies. It''s just exploration/LEGO right now.', 'Very Positive', 91.76, 3.67, 5.83);
INSERT INTO reviews VALUES (20712, 619540, 179, 'I bought this game because my mate Hades said i should get it and we can play it together. A week later and i''m still waiting for him. \nI give the game a good rating but i give Hades a 0 out of 5.', 'Released too early.\n\nShould had been a little more optimized before release. Every player character seems to phase through walls and lag everywhere. Cant see who is who because there are no player names. Combat is a** and there is really no Directive. This game should be free in it''s current state.\n\nI won''t refund because i think it''s a good concept for a title. I trust the dev to fix the game a bit.', 'Very Positive', 84.36, 1.68, 0.33);
INSERT INTO reviews VALUES (20721, 619780, 693, 'The Swords of Ditto: Mormo''s Curse is a gem of an action-RPG, offering a rich and varied adventure with every new attempt. Each legendary hero you embody brings a unique touch to the fight against the sinister Mormo, guaranteeing infinite replayability. With its captivating mix of dynamic combat and engaging quests, this game captivates from the very first moment. Immerse yourself in a vibrant world, where every decision counts and charming humor adds a special touch to this spellbinding epic.', ' Last week, my mother lost consciousness, vomited on the bed. 911 came and took her to the big hospital. Naturally I had to take care of her in the hospital, until last Sunday. Apparently she was suffering from Gallstone and that was causing severe inflammation which caused loss of consciousness, vomiting, and pain she said she was having. During this hospitalization, She was so weakened that I had to take her urine for her, find out the amount, clean the tools, record the amount, numerous times', 'Mixed', 66.09, 26.93, 2.45);
INSERT INTO reviews VALUES (20723, 619820, 3148, 'This game is awesome. I can''t wait for some dumb billionaire to hire me to play it for him so he can claim to be good at it. It''s been years since a solid grind has been so fun and rewarding.', 'The game seems pretty good and I''ll love to give it another chance someday, but for now I''m having to give it a "no" for an accessibility issue.\r\n\r\nThe text is very painful to read for me, and I''m the type of player that enjoys reading everything and comparing options for items and heroes and such, so the game became "literally unplayable" for me very quickly as it really strained my eyes.\r\n\r\nA lot of games with similar aesthetics tend to have options to swap the typeface for a more readable one', 'Very Positive', 85.71, 139.15, 0.33);
INSERT INTO reviews VALUES (20725, 619880, 541, 'it was peak and now its peak but with 0 players', 'No players online ever.', 'Mostly Positive', 76.16, 1.40, 0.12);
INSERT INTO reviews VALUES (20736, 620190, 684, 'Steam should remove and refund games thats not recieved any news or patches as Early access within a year and refund the license holders money from the devs pocket, not Steam''s pocket.\n\n\nBut the game is ok not gonna lie, but...I''d like the money back if Kenn just refuses to finish the product and we all know, Kenn always asks for refunds for products he buys that doesnt work or never gets finished.', 'Extremely slow update schedule, mediocre content and gameplay, and the studios last action was to toss the game to a developer who looked at a factory management sim and said "This looks like a paradox strategy game", got roasted, and then went radio silent ever since. This does not speak to a game that''s in good hands.\n\nI cannot recommend the game in its current state or with its likely future path.', 'Mostly Positive', 75.29, 73.83, 12.03);
INSERT INTO reviews VALUES (20737, 620210, 288, 'This yuri visual novel has a great premise that is very well executed. 12 people who died at the same time are forced into a battle of wits by the goddess of fate, and whoever wins gets to live - but only one can be left standing. \n\nThis leads to a story with a lot of tension and a very interesting and large cast of characters.\n\nThe game has some of the best character designs I''ve ever seen in a VN and also has wonderful music. Although it does feature surprisingly few CGs for such an epic game.', 'Death game plot: mid\nYuri: great', 'Very Positive', 93.06, 19.95, 6.15);
INSERT INTO reviews VALUES (20738, 620220, 248, 'Such a fun game. Nothing terribly difficult, but such an amazing experience. Also, really enjoyed the story... all the "enemies" end up being totally relatable by end game. Although it shows only 4 hours of gameplay, I do have an additional 8 hours of gameplay via Steam Deck that somehow did not get logged (possibly because I was traveling and in "OFFLINE" mode). I''m nearing what feels like the end of the game and feels like I have less than 3 hours of pure gameplay left... making this an extrem', 'An exercise in frustration, every death requires you reload the game from the previous (and sparsely placed) checkpoint, necessitating so much tedius backtracking (on top of the standard metroidvania backtracking). So many screen transitions place you right on the edge of a platform, causing you to fall right back down to the previous screen, and every pitfall returns you to the exact pixel before you fell, almost guaranteeing you will fall again. On top of that, sometimes between screens your f', 'Very Positive', 84.68, 9.37, 1.73);
INSERT INTO reviews VALUES (20748, 620590, 2079, 'If Atilla Total War and Company of Heroes 2 had a child, this would be their offspring.\n', 'Crusader gameplay was a huge letdown. The story for the crusaders is just "crusader evil." I wanted to play some awesome christian soldiers killing heretics and whatever. Instead I got "crusaders are evil you should feel bad." Don''t get this game if you wanted to play as them.', 'Mostly Positive', 76.91, 4.62, 4.78);
INSERT INTO reviews VALUES (20762, 620980, 52256, 'Beat Saber is a lot of fun, but the stock levels and DLCs leave a bit to be desired. If you buy this, download BSManager, install some mods, then head on over to Beat Saver and download some high-rated playlists off there. Anything with a rating of 85% or more is guaranteed to be a good playlist. There''s loads of good levels on there which should keep you going for a long time. Plus, it''s good exercise - you can get fit playing video games. What a time to be alive.', 'stop looking at bad reviews and buy it allready', 'Overwhelmingly Positive', 95.96, 163.40, 106.35);
INSERT INTO reviews VALUES (20766, 621060, 19361, 'this game is really fun but my dad thinks im not normal bc im building a pc in a pc 10/10 would recommend', 'Since the devs are sold out to Epic, PCBS is no longer receiving updates anymore. Accidentally soft-locking yourself and buggy achievements are still happening as of this writing this review. Parts list are frozen in time and they are focusing on PCBS2 which is a permanent exclusive on EGS. \n\nGod forbid something goes wrong with your game progress because they''re now refusing to support PCBS. Shame', 'Very Positive', 94.48, 10.45, 167.35);
INSERT INTO reviews VALUES (20767, 621070, 601, '11/10 IDEA!!!! \n- First-Person/Third-Person/Action-Combat/RTS/City Management/Empire Simulator\n8/10 EXECUTION!!\n- Definitely fun and totally worth the price! This developer understands how to make a well-rounded game with all the unique mechanics we all enjoy from various other games. I hope they continue to succeed in delivering games like this one and that other developers take heed to the level of variety in mechanics we all deserve! \n- More in-depth than Dynasty Warriors 9 Empires, and with ', 'Sometimes you back a game, and it turns out like No Man''s Sky. Other times it turns out like this. Abandoned.', 'Mixed', 56.57, 7.88, 8.47);
INSERT INTO reviews VALUES (20773, 621220, 538, 'Fun game. \r\n\r\nHas decent character growth. Felt bad when I would lose some of these guys I had built up and took to see their families and had trained them from cabin boys to capable crew.', 'The final boss battle against Mobydick ruined the experience for me. making an boss invincible is fine but allowing him to become invincible again makes it feel cheap and completely based on rng.', 'Mostly Positive', 76.21, 17.30, 23.02);
INSERT INTO reviews VALUES (20777, 621810, 154, 'If you like Rimworld''s RTS combat, you''ll love this game. \n\nMicromanaging your pawns, equiping them to fit their specializations, and even supporting them via airship''s abilities. It''s all so satisfying! And the final levels were pretty tense for me as I had grown so attached to my crew I got worried so many times I might lose one of them right until the end! Definitely one of my favorite combat systems and with the world building being as good as it was, it made the game''s ending pretty fulfill', 'The interface is super annoying. I tried a couple times, but it''s just so janky I couldn''t get past it.', 'Very Positive', 87.66, 27.18, 0.23);
INSERT INTO reviews VALUES (20778, 621830, 1254, 'One of the best rally games to play on the Steam Deck, with graphics that look great, featuring very detailed terrain and cars.\n\nThe handling is a bit arcadey but fun and engaging, especially on a controller. Compared to Dirt 2.0, where you can barely keep the car straight sometimes.\n\n95% of the time, the car physics are good, but in the remaining 5%, you will lose control of the car due to hitting a tiny rock when cutting a corner at a slightly wrong angle.\n\nOverall, it''s a great semi-arcade ra', 'I had fun with this game for a while, but after grabbing WRC 10 on sale I can''t help but feel like I have wasted my time. Runs choppy at 1440p with a 5600X and RTX 3060. Kind of disappointing considering it''s a 2017 release. My computer should be able to handle it. I noticed that the longer stages like 10km were especially choppy. I have 32 GB RAM, ought to be enough.\n\nGrabbed WRC 10 on sale and it runs flawlessly at 1440p at 100 FPS. I haven''t changed anything about my system setup.', 'Mostly Positive', 74.40, 28.58, 41.12);
INSERT INTO reviews VALUES (20781, 621930, 210, 'Its kind of sold on being a "Reverse X-Com" but the only part of the game that is like that is the moment to moment turn-based gameplay of each level. There is no base, or squads, or loadouts. You gain points to spend on upgrades between missions and there''s a linear sequence of tactical puzzles for you to solve with jokes during and between. Thats it.\n\nThe writing can be pretty funny, the visuals make it look a bit like a cheap Xbox 360 game and the campaign isn''t very long. The UI is a bit lac', 'I had fun with this, but the movement math is screwed up and once I realized that it was tough to keep playing', 'Very Positive', 84.76, 3.80, 5.78);
INSERT INTO reviews VALUES (20786, 622040, 208, 'smash', 'this game is dead', 'Mixed', 65.38, 5.92, 0.48);
INSERT INTO reviews VALUES (20791, 622220, 1439, 'I''m a simple person.\n\nI see Astolfo \n\nI buy', 'I wanna like it, but the mandatory internet is required to launch the game every time is a huge deal breaker. Yes, EVERY TIME. Sure, you can launch the game then turn off wifi but good luck doing that when you''re outdoors with no internet or in the middle of a car ride. This is not a "just launch it once every few days and you''re good."', 'Very Positive', 93.88, 30.42, 0.27);
INSERT INTO reviews VALUES (20799, 622420, 100, 'Honestly really great game. Beside the glitchy visuals, the game is inching closer and closer to the perfect singleplayer zombie survival game. The in-depth customisation of everything really helps build immersion and literally every playthrough you have will be different. Plus, the dev is very active and very interactive with the playerbase, you can check the discussion board and see how he responds to tonnes of people''s suggestions.\n\nI went from being a "Rick" like leader from the walking dead', 'abandoned by dev to start new projects to fund this game... or that was the excuse... The sad part is this had something special... I wouldn''t support this developer at all if he continues this way...', 'Mostly Negative', 38.00, 553.13, 141.10);
INSERT INTO reviews VALUES (20800, 622460, 164, 'Fun. The challenges were harder than the boss', 'I really wanted to like this game. After all, it is a steampunk setting. But sadly it is very-very boring :(', 'Mostly Positive', 70.73, 12.58, 25.78);
INSERT INTO reviews VALUES (20809, 622650, 9965, 'It might be kinda old. It might be arguably past its prime. And I may just be autistic and this game might be one of my special interests. But this game slaps.\r\nThis game is a classic for me. One of the prime games of growing up on the weird fandom side of the internet. I love the simplicities AND the complexities of it. It''s pattern recognition yet it keeps you guessing. The depth of the storyline had me in a chokehold from the first time I cared to pay attention to it. The character designs ar', 'The game was fun, creepy and unique... until chapter 4. This chapter felt repetitive and uninspired. But i wouldn''t mind so much if it wasn''t the Boris Boss fight. The controls became VERY sloppy during the fight having to click things 3-4 times in order to respond, hitting Boris had no effect on him 9 out of 10 times and 4 times out of the 6 i played the fight, the game froze while i was respawning.\r\nEven if it is an Indie game, i would not recommend because of the frustrating unresponsiveness ', 'Very Positive', 88.40, 60.95, 4.57);
INSERT INTO reviews VALUES (20813, 622720, 850, 'This is.... okay. The gameplay loop is kind of boring and the controls are obviously meant for tablets or a Switch type controller. Get it on sale. If the product being grown were tomatoes far less people would buy this.', 'Boring mobile game with tiresome grinds to keep you clicking buttons. I am shocked I wasn''t asked to buy coins or something while playing. If you enjoy games you could play post lobotomy this is right up your alley.', 'Mostly Positive', 77.18, 17.97, 6.03);
INSERT INTO reviews VALUES (20814, 622770, 136, 'yes', 'We could''t play local co-op due to issue with connection to external server.', 'Mixed', 56.62, 15.13, 5.98);
INSERT INTO reviews VALUES (20817, 622870, 150, 'I love this game. A long time ago, I was a big fan of Tenchu: the Wrath of Heaven - and I''ve been looking forever for a game that feels like that one. This honestly comes close for me. It has very precise controls, a fast pace, a hardcore/permadeath mode, bosses, and high difficulty. A YouTube review I saw on the game complained that some of the the controls acted imprecisely with wall runs, but he was wrong - skill issue. Also, a reviewer here on Steam complained about getting spotted by archer', 'Quick review: 3\n\n### Metric ###\n1- Garbage. :(\n2- Did not fulfill the purpose.\n3 - Ok, fulfilled the purpose.\n4 - A good game!\n5 - Just play and be happy. :)', 'Very Positive', 83.33, 31.27, 0.50);
INSERT INTO reviews VALUES (20828, 623080, 338, 'thank you yumemi for showing me the stars', 'To me it kinda felt boring and repetitive, same with the drawings, nothing much was happening. I''ve played free vns for 30 mins with more content in it', 'Overwhelmingly Positive', 97.04, 3.82, 1.95);
INSERT INTO reviews VALUES (20829, 623090, 214, 'Easily one of the best offroad racing games of all time, no question.', 'This game is horrible. The cheating and rubberbanding is worse than Mario Kart. AI opponents seem to be able to take turns at full speed as if they''re on a rail.  Upgrading your car is a waste of time and credits as it doesn''t change anything; in fact, it seems to make your performance against the AI worse. The physics are awful on top of all that. The number of vehicles is heavily inflated by variants, which cost different amounts to purchase despite supposedly being identical according to the ', 'Very Positive', 83.64, 65.98, 2.95);
INSERT INTO reviews VALUES (20834, 623340, 729, 'The game had potential but has now been left to die. \r\n\r\nDO NOT BUY THIS GAME!! The Devs gave up on it.', 'The presentation on the store page is a total lie, I was presented a space survival shooter i got a unity asset flip with some of the worse primitive survival i have ever seen. \n\nNo updates in over a year so it appears to be dead as well \n\nJust pass on it, this feels like a project some people started that had no business starting in the first place.', 'Mixed', 64.33, 5.80, 5.53);
INSERT INTO reviews VALUES (20847, 623700, 194, ':steamthumbsup:\r\n', 'Yet another mostly functional, but definitely not completed, EA game abandoned by the indie developer.  They lost interest in developing the game, but not in making money from it, so it will stay in EA for eternity.', 'Mostly Positive', 77.84, 7.63, 52.73);
INSERT INTO reviews VALUES (20853, 623880, 169, 'No player base, just wait for it to be free to play, because it has cars for real money, still fun though, i was in the closed beta so i know about the game. Basicly a good game, for free, only for free.', 'feels like a game on my phone', 'Mixed', 65.68, 0.43, 0.35);
INSERT INTO reviews VALUES (20857, 623940, 2632, 'Hiveswap: Act 1 is a delight! The vast majority of the Steam reviews appear to be from fans of the related webcomic - and I''m glad they''re having fun with this - but actually this is a wonderful adventure game even for people like me who had never even heard of the source material. Its target audience appears to be people who were kids in the 90s, and this short episode is filled with nods to pop culture of the era. Somehow, though, it avoids coming across as pandering or gimmicky. The trick is ', 'every single somewhat positive trait is offset perfectly by an overwhelmingly negative one', 'Very Positive', 94.22, 2.32, 3.17);
INSERT INTO reviews VALUES (20863, 624270, 2431, 'I absoloutly loved this game - MAKE YOUR OWN NOTES AS THEY ADVISE - i felt like a real detective trying to link all the pieces of the puzzle together, figure out who was linked to who - every step of the way you were figuring something else about someone, you were lead in different directions and had you doubting yourself - played all day couldnt stop until i solved it!', 'It''s really good for about 2/3rds of the game, but the third act flops pretty hard.\n\nNarratively, it just starts telling you exactly what happened, making all those notes you took rather pointless. Gameplay-wise, it becomes a matter of running to a location, opening a door to get a key, running to the opposite end of town to open another door to get another key, then running back to the first location to use it. You already know most of what happened at this point so it feels more like a series ', 'Very Positive', 89.26, 8.92, 7.22);
INSERT INTO reviews VALUES (20882, 624970, 633, 'Game of my childhood, remastered! Perfection. Wish there were more RTS''s like this one.', 'it''s an old game that got a graphic update, it''s confusing to play, commanding your units (because this is an RTS or whatever, basically it''s like age of empires) is frustrating because of the like number 1 thing that makes this game rather hard.... everything is in first person pretty much don''t know what the creators of this game were on when they made this but but a game that involves commanding units to do battle in first person was such a dumb idea', 'Very Positive', 90.05, 105.55, 4.48);
INSERT INTO reviews VALUES (20896, 625340, 726, 'gg', 'nahh safe your money for something better then this', 'Mixed', 64.19, 28.22, 15.92);
INSERT INTO reviews VALUES (20906, 625680, 107, 'It is really good, it is no fun to watch someone else play, so a lets play video is not a good reference. If you like to parry, this is your game.', 'I am a huge fan of the 2D beatem up genre. I really enjoy games like Double Dragon Trilogy, Streets of Rage 4, Teenage Mutant Ninja Turtles IV: Turtles in Time, and Final Vendetta. I rather hate Way of the Passive Fist and would argue it has poor game design.\n\nWay of the Passive Fist is not an original concept. There have already been 2D beatem ups with parry mechanics such as Super Double Dragon originally released in 1992 for the Super Nintendo. In Way of the Passive Fist your only option is t', 'Very Positive', 82.24, 5.23, 0.33);
INSERT INTO reviews VALUES (20921, 625960, 9832, 'This game can be very unforgiving at times.  However, I feel that it occupies a perfect spot in-between classic and modern RPGs.  Difficult, with a focus on trial-and-error + hints embedded in lore.  But also flushed out, with good visuals and mechanics.  \n\nI waited for over a year for the Rags to Riches update to come out, and so far it''s been amazing.  It fixes a lot of my complaints with the game, and I would wholeheartedly recommend this game now.', 'Amazing game. Super hard, challenging, steeeeeeeeeeep learning curve, so far so great. But the save mechanic is unfathomably anti-player. If you want to play some hardcore-mode as a checkbox at the start of the game, I understand you''d like such a mechanic, but normal players don''t have time for that sh*t. The game disrespects the players time by making them travel and redo content over and over again if they die, because they can only save in taverns (or bedrolls if you are further into the gam', 'Mostly Positive', 73.91, 97.83, 5.18);
INSERT INTO reviews VALUES (20922, 625980, 180, 'This is truly one of the best games I''ve ever played. The art is gorgeous, the story is rich, and the mood is perfect. Everything down to the most minute detail is well polished and after completing the whole trilogy I will look back at this game fondly in particular. It held onto that spark the first game had but expanded on it thrice-fold in story, character, and world-building/expansion. With references and special appearances from the first game, it stood out from the other two games. Don''t ', 'This is a conflicting game for me. On one hand, I like the atmosphere and the monsters in this game. On the other hand, it''s extremely repetitive and the gameplay is super simple. There''s nothing to this game. I have no idea how it''s sitting at 93% positive reviews. Some of the "bosses" are extremely annoying, you essentially walk around a giant map while monsters spawn at random, and that''s it. Sometimes you get to tighter locations, and those are pretty fun, but those are the best part of the ', 'Very Positive', 91.67, 62.30, 8.17);
INSERT INTO reviews VALUES (20933, 626600, 166, 'A very unique hidden gem RPG,\nuses turn based TACTICS and unit positioning as a combat system instead of the ol "MASH A" system. So battles actually require thought and strategy.\nIt also has a very interesting story. Yeah the usual, the BBEG is destroying the world. BUT out of the 11 heroes (thats enough for a soccer team!) ONE is a traitor.', 'Looks like the last working driver for this game is AMD Radeon Software 24.5.1, newer than that this game won''t work or black screen. Definitely not recommended if you plan to play new games, you will always need to be stuck to older AMD drivers.', 'Mostly Positive', 74.10, 0.55, 0.10);
INSERT INTO reviews VALUES (20934, 626610, 448, 'After 600 hours, I can confidently say that I love it. The key to success is achieving smoothness, which comes from deeply ingrained track knowledge acquired through many hours of play. Understanding the subtle nuances of the bumps, bends, and cambers, as well as approaching the correct gear and speed, is essential. Knowing your markers is crucial, yet even then, you may still crash! The thought of doing this for real is unfathomable for any sane person.', 'No!\n\nIf realism is what you are looking for, it''s not here! AI riders on rails while you are Ice Road Trucking. If you don''t know the tracks, then don''t go looking for help with the virtual racing line. It will tell you to slow or brake where the AI continue full or almost full throttle. Collisions cause you to do weird acrobatics, collisions with the AI do nothing to the AI. If the AI collide with you, you end up off your bike. Low speed connections with anything other than the tarmac cause you', 'Mostly Positive', 72.32, 763.10, 12.60);
INSERT INTO reviews VALUES (20937, 626660, 124, 'An absolute gem of a game that blends stunning visuals with unique gameplay mechanics! \n\nThe art style is absolutely beautiful and gives the game a distinct, quirky charm. And the voice acting is top-notch! \n\nThe gameplay itself is a fascinating twist on platforming, where you alternate between the real world and the world of the dead. You have the ability to possess people in the real world. Each character you possess has their own unique skill, which keeps the gameplay fresh and creative as yo', 'Weird hate on for Masculinity. Some parts were clunky and unintuitive. Story was decent, art style was amazing, characters were ok. Could have had a more perilous feeling by adding some risk. It doesn''t seem like you can actually die in this game and gathering the basic souls seems like a chore and not fun.', 'Very Positive', 86.29, 7.62, 8.87);
INSERT INTO reviews VALUES (20939, 626690, 5014, 'good if it discount\r\nnot worth the money if no discount\r\n', 'Ring 0 DRM Denuvo and EAC. Won''t be playing again until these are removed. With this game''s age and the fact there''s already a cracked version out there, no point in keeping Denuvo. I am willing to lose all online functionality if it means not having to launch EAC as well.', 'Very Positive', 83.15, 1011.43, 156.13);
INSERT INTO reviews VALUES (20946, 627270, 6201, 'First time I have personally experienced a story mode in a fighting game that was worth the effort. I’m late to the party but this is a great game. Beautifully made.', 'At first your gonna get into this game hyped to grind out each character and collect new gear, etc. Your gonna put a few hours into it and then your gonna realise that it will take tens of hours to level each character up to level 30. The multiplayer is dead so your only going to fight against ai, which is awful and honesty boring. At a certain point it all becomes very repetitive. Even if you learn every new combo it just gets boring. My biggest issue with this game is the clashes and stage tra', 'Very Positive', 85.87, 2.08, 41.45);
INSERT INTO reviews VALUES (20960, 627910, 144, 'Game''s mid but Bubsy can fucking get it.', 'This game will not run properly. I''ve tried changing the settings to try to fix my issues and it still will not work properly after entering a level. Do not buy.\n\n(PS. Play Sonic Lost World instead.)', 'Mixed', 60.42, 4.62, 0.28);
INSERT INTO reviews VALUES (20962, 628070, 236, 'English version please. bought this a while still hadn''t get to play it yet, even if i try to follow steps to patch english version i can''t.', 'Please give us official english translation...', 'Very Positive', 87.29, 0.18, 0.95);
INSERT INTO reviews VALUES (20965, 628200, 300, 'Line go up = good if long\r\nLine go down = good if short\r\n\r\nAs long as money go up, who care where line goes?', 'I expected a trading simulator where you earn/lose money and buy things.\n\nUnfortunately, this game is about countless quest dialogues that you end up skipping quickly without reading,\nbecause the clock is ticking, every second matters, and you have to focus on making money.\n\nAlso, there''s a ''competition'' among co-workers, and you get fired (Game Over) if you don’t earn more than someone else regardless of you are still making good money.', 'Very Positive', 80.33, 9.02, 2.62);
INSERT INTO reviews VALUES (20966, 628290, 133, 'very interesting gameplay and world, especially after living in berlin for 5 years now! the only thing that bothered me was that you could barely see what was happening on the last health state. all that static made it really hard to see enemies or even the environment', 'It''s poor animation turn-based game. Just two scene and feeling like mobile games are much better.', 'Mixed', 69.17, 5.52, 7.15);
INSERT INTO reviews VALUES (20979, 628670, 1546, 'this is a great game it is a little janky but honestly the jank added to the experience also if you want free items at the start of the game go to the console outside of the start room (it will have a small pile of bones at it''s base) and enter the code 100408 and after that enter the code 642017 this will give you great starting gear with relatively low stat requirements I definitely think you should play with a friend.', 'Dark souls 2 but sci-fi. I actually like dark souls 2 though. There are plenty of reviews reciting the same complaints about level design, jankiness, combat issues. \r\n\r\nI was enjoying the game until I made it to the arisen congregaters. Horrible change of pace for the beginning of the game. Gank fight, one shot attacks, spells go through walls, relentless. I have beaten every fromsoft game and this left me in shambles lol  (Probably half my play time spent)\r\n\r\nI can tell that the devs put passio', 'Very Positive', 80.27, 73.07, 5.10);
INSERT INTO reviews VALUES (20983, 628740, 318, 'Genuinely uplifting and life affirming. A beautiful story full of quirkiness and excellent humour. Truly touching and heart breaking also, as someone who has suffered severe depression for many years this actually managed to break through my emotional barrier and make me feel something for the characters and feel hopeful. I cannot recommend this enough for its beautiful art and music, its wonderful story and emotional weight. An actual masterpiece. It''s also very silly in all the right ways!', 'So while the pixel art and music of the game is absolutely gorgeous, I didn''t really like any of the characters. There is a child character who''s written like any other stereotypical child character, the side characters weren''t very interesting and I quickly grew tired of the rampant fatphobia. Seriously this game absolutely hates fat people. Now, the ending was very nice and I did find it impactful, but the rest of this game didn''t really warrant such a beautiful ending, and it wasn''t enough fo', 'Overwhelmingly Positive', 98.43, 2.23, 2.88);
INSERT INTO reviews VALUES (20984, 628750, 269, 'More of the same fun mazes as the previous title, this time we have various shapes and styles of mazes.\r\n\r\nRelaxing, chill game for when you need a break, now featuring an extended array of achievements, and more beautiful astronomy art.', 'IT''S GARBAGE DAY! /Silent Night, Deadly Night Part 2 (1987)', 'Very Positive', 85.13, 4.57, 1.03);
INSERT INTO reviews VALUES (20986, 628770, 626, 'Solid roguelike that''s *actually* a roguelike. There''s good variety, and lots of potential for building your character in different ways - you can switch classes and mix + match your class abilities to an extent.\r\n\r\nIt''s also kinda buggy, but that''s my only gripe.', 'Not good, embarrassing amount of glitches, like, imagine all your pokemon being deleted by a glitch and the response is just "yeah, that happens sometimes, still trying to work that out" 6 years after release???? absolute shit support, good idea for a game but terribly executed. I truly can''t believe they would start a sequel before sorting the shit out on this one, crass cash-grab and dogshit studio (besides the artists, they are cool, the coders and managers are ruining it)', 'Very Positive', 87.06, 325.97, 28.40);
INSERT INTO reviews VALUES (20987, 628800, 124, '\nGood shoot''em up made in the vein of Gradius. You unlock new weapons for completing missions so your arsenal gets bigger with each stage. There is no weapon swap so make sure to pick right guns before starting the mission. Graphics is ok but nothing mouth dropping. Music and sound is again ok. Gameplay is rather good and controls are tight. Don''t expect it to be easy so I recommend to start on rookie difficulty first. There is plenty of different stages and at some points you are able to choose', 'Some wild hyperbole in the reviews, especially the pro quotes. This schmup is so slow that the music tracks end before the levels do. That''s just jank. Moving the fighter is like dragging folders across a Win95 desktop. Laborious and dull.', 'Very Positive', 88.71, 15.82, 1.32);
INSERT INTO reviews VALUES (20991, 628900, 147, 'Complicated game and takes a long time to gain a decent level of competence. I’m still working out if I think it’s a worthwhile exercise! For learning to play without annoying real opponents I think this app is pretty good: the AIs are easily good enough to be challenging. It’s a bit buggy though (it has frozen completely on me a few times - mainly when I used ''undo'' actions) and I would like a bit more guidance (e.g. hover over things to see some explanation tooltips). I haven''t explored the ''r', 'Terra Mystica is one of my favourite board games, but the poor interface and lack of developer support really make this adaptation disappointing.\n\nOn some of the menus (cult track, for instance), it is very hard to figure out what magical point on the screen you have to click and how many times in order to take the action you want to.  After being stuck on a screen for 10 minutes I had to look up in the forums how to take the action (it turns out that when you press on a certain part of the scre', 'Mixed', 59.86, 56.85, 9.50);
INSERT INTO reviews VALUES (20992, 628920, 146, 'Based game. Love me some tomboys', '5/10', 'Very Positive', 87.67, 2.53, 7.40);
INSERT INTO reviews VALUES (20994, 628950, 172, '\nA little bit of exploration with some fantasy. Pace is rather slow but also it doesn''t take much time to complete. Gameplay wise might feel somewhat unfinished. Overall not bad option for round of walking sim with some unusual story.\n', 'Sorry but I had to be honest with this. I''ve been looking for the last mushroom more than 1 hour. Why didn''t you also put a HUD for the mushrooms? Map is so big that instead of relaxing, it was stressing. Not recommended at all. Don''t waste your money.', 'Mixed', 65.12, 0.30, 2.48);
INSERT INTO reviews VALUES (20996, 629000, 222, 'The game itself is cool; it''s an easy, well-designed point-and-click game. Not recommended for anyone with depression or going through a rough time. It''s true that it can be a bit unnerving at times, especially when you see what''s really happening through the lens of a little girl. But in the end, I felt like something was missing, I don''t know what. \n\nGive it a try when its on sale.', 'I can definitely see the appeal for this game, but it just personally wasn''t for me. I found the game to be too slow, the animation felt too wonky for me, and the plot was lackluster. However, that doesn''t mean it won''t suit you. However, if you''re into eerie, slower, storytelling games, then I would say give it a try.', 'Very Positive', 91.89, 0.98, 0.27);
INSERT INTO reviews VALUES (21000, 629090, 264, 'Really underappreciated hidden gem of a game, even if the presentation can look jarring at first.\nVery fun game with emotional story.', 'Unfortunately, the amount reliance on infinite lives and constantly retrying to get something right just once is really not fun. Can not recommend to anyone except a platforming enthusiast.', 'Very Positive', 85.23, 14.58, 19.07);
INSERT INTO reviews VALUES (21004, 629220, 304, 'Psychological horror focused on exploration, with a few jumpscares, a few very simple puzzles, good graphics, creepy vibe and interesting albeit cliche story. Reminds me of Layers of Fear but with less interactions, puzzles and achievements. It''s also much shorter. I think the price is decent for the amount of content and quality. Overall a good game in the genre.\n\nSome people reported some issues in discussions like bugs and glitches, but there doesn''t seem to be any major problems. I personall', 'Visually stunning & creepy walking simulator with minimal gameplay interaction. Story is average. Probably would be worth a shot to see how immersive it is in VR. But, I cannot recommend. A game should be interactive.', 'Mostly Positive', 76.32, 3.12, 3.18);
INSERT INTO reviews VALUES (21017, 629520, 26282, 'very immersive story.\nengaging gameplay.\ninteresting worldbuilding & characters.\ngreat graphics & optimization.\n\nwhat more could you ask for?  10/10', 'the games kinda boring you just upload sound and stuff. Add a comp mode to make it more interesting :/', 'Overwhelmingly Positive', 95.82, 1698.08, 2293.08);
INSERT INTO reviews VALUES (21021, 629650, 111, 'It is my favorite visual novel. But I''ve played it somewhat 15 years ago, and I can tell it didn''t age well. Don''t get me wrong, I still love it for the vibe and romance. And I also like all 3 girls very much, especially Torta. No one deserves happiness more than her. But playing it now, when I''m almost 40, I can see just how flawed it is. For the music lover and past musical student like me it holds the very special place in my heart, and that will probably never change, but I wish they''ve upda', 'the original is much better. this translation is garbage and slow retardation. the og art is also much cuter. PLUS now its almost impawsible to find the old game version, BECAUSE OF THIS TRASHHHHHHHHH. fail!', 'Very Positive', 88.29, 3.87, 10.90);
INSERT INTO reviews VALUES (21022, 629690, 550, 'I bought this game because I was looking for another experience like the two Legend of Grimrock games (my first experiences with a grid based dungeon crawler).  While this game doesn''t reach the excellence of those games, it did scratch the itch.  It has only a single character that you play as, which I honestly found easier because you don''t have to balance all of the party members at the same time.  It has a cool steampunk setting, and the story is decent, although the voice acting isn''t great', 'Random update after 6 years of inactivity and it''s to add Epic Online Services to an exclusively singleplayer game? Never going to recommend this game to anybody ever again.', 'Very Positive', 85.09, 28.27, 6.90);
INSERT INTO reviews VALUES (21024, 629730, 46263, 'I loved when the shopkeeper said "you''ll do good out there, you truly are a Blade & Sorcery VR Fantasy Sword Fighting"', 'Great game, but plagued with performance issues. Even on recommended hardware (High-End computer, USB-C 3.0 connection), its nigh on impossible to make it through one of the newly introduced Outpost levels without the game freezing, glitching, or tweaking out. I feel like I need to reiterate before I continue, what I am experiencing is NOT a hardware issue. I can consistently run other, much more demanding VR titles, such as Half-Life Alyx, and EXTREMELY demanding desktop titles, such as Teardow', 'Overwhelmingly Positive', 96.98, 57.38, 77.32);
INSERT INTO reviews VALUES (21025, 629760, 58829, 'Very hard game for newbies to learn. At 400h i do not die all the time anymore. And the playerbase is how to say kindly.. very unique. Team balancing is nonexistent because game is all about skill. If you see a shirtless small person charging you with a frying pan most likely you dont stand a chance.', 'There is a ZERO chances for any new player to have fun in this game, the 200+ level players filling the few servers really need to get lifes and get out more, and Devs should consider a solution for that issue if they really care, but seems they dont and its just for these veterans players that can kill you a thousand time with you never able to deal any damage to them.\n\nIf you value your mental health stay away go play Chivalry II its way better.', 'Very Positive', 81.59, 400.55, 10.95);
INSERT INTO reviews VALUES (21026, 629770, 231, 'A point-n-click with charm, that doesn''t overstay its welcome. Great visuals, great soundtrack.\n\nIf you want to fall asleep in a boring way, play a Visual Novel. If you''d prefer to drift off in a more pleasant manner, play this.', 'Cute game\nAwesome sounds\nVery Easy\nVery very Short', 'Very Positive', 91.34, 1.77, 2.25);
INSERT INTO reviews VALUES (21029, 629820, 5900, 'It was a really fun and interesting game and I loved the experience. The whole game was fun and although the missions got repetitive, the game didn''t get boring for me.\r\n\r\nScore: 7.7/10\r\n\r\n', 'Bought this game after I discovered one of the developers was pro Trump and was outspoken about it. Days later the dev team forced him out for wrong think. I was unable to get a refund. F Tripwire and Ty Steam for giving me a list of games to never buy. It''s one thing to disagree with someones opinions, it''s another thing entirely to go after their employment.', 'Very Positive', 90.98, 20.72, 5.07);
INSERT INTO reviews VALUES (21030, 629840, 470, '⠀', 'It’s a very short walking simulator that makes no sense story-wise. The visuals are gorgeous and surreal and interesting to look at, but the walking speed drove me crazy and the dialogue makes very little sense to me. I picked this up very early in my gaming interests and never tried it until now, but by now I know that this is not the sort of game I’d ever pick up.', 'Mixed', 65.96, 4.20, 1.27);
INSERT INTO reviews VALUES (21035, 630030, 144, 'It''s cool. I bought it cuz at first glance it reminded me of the Transformer Movie games. It doesn''t play anything like them but I think its an alright game. If you like Mecha games you''ll probably like this game.', 'The endgame is too grindy. Replaying missions or challenges doesn''t feel worth as the rewards are minuscule.', 'Mostly Positive', 72.22, 2.38, 21.92);
INSERT INTO reviews VALUES (21048, 630310, 378, 'Imagine a GBA/DS Castlevania game, but instead of playing as a vampire hunter armed with a wip and holy water, you play as a soldier with a shotgun and a flamethrower.\r\n\r\nThat should be enough info for you to decide to give this game a chance or not.', 'Played about hour till first boss and lost interest to continue.  enemies respawn everytime and too boring enemies. reminds me old average 8bit games..', 'Mostly Positive', 79.10, 11.03, 1.08);
INSERT INTO reviews VALUES (21056, 630550, 109, 'shoutout to cocohen', 'I played best elf prior and really like that game. This one I was needing more voice acting in the main game, the game play got boring.', 'Mostly Positive', 77.98, 1.18, 9.65);
INSERT INTO reviews VALUES (21057, 630610, 383, 'I was going to write a review for this game, but a strange strong wind blew it away. Now my review is scattered all over the place. Could you go and find it?', 'Game runs extremely poorly. Lots of stuttering and lag. The first cutscene with Mickey finished the dialogue earlier than the animation and I had to sit there for quite literally a minute in silence before I could move on. Couldn''t even properly move after that and just gave up on being able to play.', 'Very Positive', 90.34, 21.82, 0.08);
INSERT INTO reviews VALUES (21062, 630720, 240, 'The most mid game ever created', 'Does not work with either a controller or a keyboard.', 'Mostly Positive', 76.25, 1.33, 4.68);
INSERT INTO reviews VALUES (21065, 630900, 377, 'I''ve been using this program for years to make battle maps and floorplans for D&D games. It''s an amazing tool that really deserves so much love. The dev has been continually updating and fixing bugs, and showing care and attention. \n\nWhile it is quite simple, and you won''t find Photoshop level tools here, it''s perfect for what it sets out to do, and the only real issue I''ve ever had with it -- long load times when starting a project/loading one in -- is primarily my own fault for having 1k+ asse', 'Allows you to make basic maps quickly, but isn''t good for much other than that. Can''t make round or curved tiles, can''t use overlays or layers to put a transparent texture (like rain) over an existing tile, there''s an option to make tiles straight or jagged but you have to make extra copies of the tiles and have to relaunch if you do so don''t expect to hit a button and have it work. The more custom icons you have the slower it loads, my guess is this has something to do with the program putting ', 'Very Positive', 93.37, 87.28, 69.72);
INSERT INTO reviews VALUES (21075, 631510, 6085, 'The first game''s difficulty is already hard, but Trish''s appearance is making it harder for me to play.', 'WARNING: includes DMC2', 'Very Positive', 93.39, 34.95, 1.42);
INSERT INTO reviews VALUES (21077, 631570, 918, 'You know a game is Good™ when you finish it and get overwhelmed with feelings of anger, sadness, emptiness and frustration that there is no more game to play. But than you remember that you can play it again and make different choices and all is well in the world. 5/5 Blue Vials.', 'There''s a ton to like and that I did like here. It presents itself as a more modern take on the genre with associated QoL features and design sensibilities, but it''s all skin deep. Underneath it still does all the same old BS the golden age games did lol. The atmosphere is moody and cool, voice acting is largely solid and the script is good. It has a really strong start gameflow-wise, but then the "exploration" and "puzzles" start and that "old school point and click" stuff rears its ugly head a', 'Very Positive', 94.23, 32.50, 4.38);
INSERT INTO reviews VALUES (21082, 631830, 100, 'I played this with my dad. He not my dad anymore.', 'ᅠ', 'Mostly Positive', 72.00, 3.25, 6.55);
INSERT INTO reviews VALUES (21089, 631980, 125, 'unique vibe, nice mechanics.', 'While this game had interesting gameplay and FAR more interesting lore, the game''s developers intentionally lied about a "good ending" to the game that has never existed.\n\nI can''t support people who would trick players into sinking more hours into a game to give a false sense of more popularity -- and purely because players were honestly curious about such a unique and interesting narrative that they clearly never had the time or resources to finish.\n\nThe game has its other flaws, as well -- all', 'Very Positive', 81.60, 10.65, 10.67);
INSERT INTO reviews VALUES (21091, 632000, 516, 'Fun little puzzle game with varying mechanics that aren''t too hard or too easy to understand. Most of the game is on the easier side, but it''s not too easy to where it''s boring. \r\n\r\n7/10', 'Unlike the other cells games, this requires some trail and error. There is no quality of life to support that, it''s incredibly frustrating to try out solutions and back track. It''s a fun puzzle concept, but the game itself is inadequate.', 'Very Positive', 84.50, 0.80, 1.75);
INSERT INTO reviews VALUES (21095, 632070, 533, 'https://steamcommunity.com/sharedfiles/filedetails/?id=937281194\nhttps://steamcommunity.com/sharedfiles/filedetails/?id=1577610548\nhttps://steamcommunity.com/sharedfiles/filedetails/?id=937846323', 'this game crased again and again', 'Mostly Positive', 78.24, 3.52, 0.17);
INSERT INTO reviews VALUES (21101, 632200, 436, 'This game is a very lovely experience my friend. Graphics are cute, yes, very cute. Controls are simple like morning chai. But after playing 20 minutes, I found that it is repeating too much. The enemies, they come again and again like uncle’s same story. Where is the spice, bhai? We need more variety in attacks, more surprise, more boss challenge! But I do like the badge system, very cool for showing off. My advice for developer-ji: maybe make small story for character? Like why is Kuro fightin', 'The game has a great foundation, but the balance is way off. Some weapons feel useless, while others make fights too easy. The difficulty is inconsistent—sometimes enemies barely react, and other times they swarm you instantly. I also noticed that some crafting materials are too rare, making progression slower than it needs to be. Right now, it feels like the game is punishing in a frustrating way rather than a rewarding way. I hope future updates bring better balancing, because there’s a good g', 'Very Positive', 89.91, 4.05, 4.03);
INSERT INTO reviews VALUES (21105, 632300, 2125, '800+ hours played - time to take a break.', 'If you love rage inducing mini-games and restarting the game after two in game days multiple times, this game is for you. I''ve heard good things from players who stayed past that, but I simply can''t. I understand the game is meant to represent the constant struggle of homelessness and it does that well. But as a game to enjoy and play for fun? No. Do you enjoy those carnival games where you press a button to stop a light at a very specific place? Well, you have the opportunity to do that at leas', 'Very Positive', 80.05, 809.00, 2.20);
INSERT INTO reviews VALUES (21106, 632350, 1160, 'I want to sniff Blanc''s intoxicating and brunette locks of of hair.', 'Giving negative rating because dont get me wrong tho, this game is really nice, it has improved graphic, an actual action fantasy RPG-like HUD style and much more that i dont know how to mention it one by one. But this one, sadly i couldnt enjoy it very much. Lets mention the bugs and errors ive encountered, the controller is really buggy, struggling to move the camera, settings that kept changing everytime i launch the game, fps limit, blue screened sometimes and the last one is no game directi', 'Very Positive', 84.57, 38.00, 237.87);
INSERT INTO reviews VALUES (21107, 632360, 145560, 'Spend 3-4 hours building character for epic 1 shot boss fight\nEnter Boss fight\nGame crashes from too many on hit effects and cannot compute damage numbers\n10 / 10 would recommend', 'One of my absolute favorite games completely ruined by Gearbox and Take Two Interactive with a horrendous DLC that botched the base game, and a recent EULA that wants to scrape all my personal data, prevent me from using mods, or even talk about glitches, bugs or cheats. It explicitly even states against using VPN to bypass this bullshit.\n\nUntil, at the very least, this current EULA is rolled back, I can''t in good faith recommend anyone to purchase this game. A real shame that a modern classic i', 'Very Positive', 94.78, 146.75, 189.12);
INSERT INTO reviews VALUES (21109, 632470, 50334, 'Great game, sail the seas. The people who actually made this game got pushed out. This game was stolen from the creators, don''t buy it and help fund their theft. Find different ways to experience it', 'It''s the best game I''ve ever played. I love it. Everything is amazing there from OST to the story...\nBUT!\nDo not sponsor ZA/UM corporates. Do not buy the game, do not buy ZA/UM''s merch, clothes in their atelier, anything! Not a single euro cent should go to their greedy hands. \nYou can easily find the information about the atrocious situation how one crook stole ZA/UM from original creators. Compus must pay dearly for what he did to Kurvitz, Rostov, Hindpere and others. The art must prevail here', 'Very Positive', 92.86, 5.53, 88.08);
INSERT INTO reviews VALUES (21116, 632800, 106, 'hm, i certainly enjoyed the game''s aesthetic dimensions. the background illustrations were particularly divine. i was also impressed by the simple yet effective scoring. albeit, a touch bit repetitive at times. with a game like this, i reckon they could have gone a bit harder with the sensual audio effects. some did not mirror the realism i was hoping for (e.g. mouth action). additionally, i could have done without the interactive story mode. i get it, but it did little to bolster the overall ex', 'Well this game seems to be sensored. You can''t see any of the sexy scenes. I was not expecting this so I requested my money back. 30 bucks for this BS? No way!!!!', 'Very Positive', 89.62, 10.07, 0.57);
INSERT INTO reviews VALUES (21123, 633060, 1012, 'In my view this is a step down from the first game. I think that the concepts they implemented were interesting, but ultimately overcomplicated things to a point where you, as the player, become overly confused as to what to do. As well, it seems like the order of operations you need to accomplish certain things by certain times is extremely difficult to figure out in a first playthrough, requiring multiples playthroughs to really get a full sense of the game''s content and alternate endings.\n\nFo', 'The main game might be better. This one is either rushed or plainly poorly written: your manager (spy executive) orders a suspect to be executed by special forces under surveilance cameras. The nation you serve is literally called The Nation. Your main antagonist is a blogger in a wheelchair with a grudge against the government and writes 3 paragraph articles in capslock. However, the stakes are somehow high in bringing him down.\r\n\r\nSeem like this story wasn''t important to the developer either.', 'Mostly Positive', 75.79, 10.42, 3.05);
INSERT INTO reviews VALUES (21124, 633110, 274, 'This game fucking sucks', 'Ultimately, it''s just a dull and frustrating grind.', 'Mixed', 66.79, 26.58, 6.33);
INSERT INTO reviews VALUES (21126, 633230, 17334, 'Wake up to reality. Nothing ever goes as planned in this accursed world. The longer you live, the more you realize that the only things that truly exist in this reality are merely pain, suffering and futility. Listen, everywhere you look in this world, wherever there is light, there will always be shadows to be found as well. As long as there is a concept of victors, the vanquished will also exist. The selfish intent of wanting to preserve peace, initiates war and hatred is born in order to prot', 'I like the game and I enjoy playing it, but recently there are too many people with the game hacked and they activate unlimited ninjutsu. So, not funny to play with player with unlimited ninjutsu and unlimited secret technique activation.', 'Very Positive', 85.94, 2.80, 1392.72);
INSERT INTO reviews VALUES (21129, 633360, 621, '👍', 'Ever wanted to run around a creepy mansion with a old naked guy chasing you? This is the one.', 'Mixed', 69.73, 4.65, 15.57);
INSERT INTO reviews VALUES (21132, 633460, 3545, 'A simple WW1 game in the eastern front. It has some awesome elements of the trench warfare, especially the thing that enemies are killed by one shot most of the time. The battles are mostly tactical, mixed Players and NPCies, which is great as the playerbase isn''t big. \n\nThe biggest amount of players i played with was around 60, but majority of them are really good seasoned players who have mastered all the maps, have their favorite camping spots and thrive to have the most kills in the game. Th', 'A good game, but it should just be rolled into Verdun at this point. Never understood why this had to be its own game when it seems to be the exact same thing as Verdun under the hood. It just ended up dividing players and leaving Tannenberg with a tiny playerbase. Even back when it launched you''d be hard-pressed to find a full match.', 'Very Positive', 86.74, 15.92, 8.22);
INSERT INTO reviews VALUES (21145, 634160, 2088, 'A+ game, especially if you were one of the Warrior Cats kids that made their own Clans and OCs and wrote stories about them or ran around the playground pretending to be a fighting cat (hi, me)', 'i cant find a catfish', 'Overwhelmingly Positive', 96.12, 3.90, 69.52);
INSERT INTO reviews VALUES (21149, 634410, 203, 'This game was so interesting to see what it is like to be an NPC in an RPG. I thought it was neat how you get to play out the "mc''s" whole life time. Since you are an npc don''t expect any fighting or anything. This is sort of more like a walking and fetching type game with lots of dialog and story. The story was really bittersweet and made me tear up at times. Over all I really enjoyed this game.', 'As lovely as the game is, visually and story-wise, I just refunded it.  In less than 50 minutes I had two lock-ups during dialogue that forced me to shut it down using the windows button on keyboard.  Then I had to replay everything from last save, which gets old quick when the game is almost all cut-scenes so you can''t cut corners.  (with replaying chunks I estimate it was actually twenty minutes actual game time).  The lock-ups didn''t occur second run so not sure what the problem is but it mak', 'Overwhelmingly Positive', 97.04, 11.82, 0.82);
INSERT INTO reviews VALUES (21156, 635200, 426, 'Alot of the people complaining about this game are experiencing nothing more than a skill issue. i saw credits roll on this game in around 2.5 hours on a casual explore everything play through. If they have 40 minutes in this game and complain it''s too hard they never really left the tutorial. If you''ve played Don''t Starve, The Long Dark or Dark Souls you''ll realise where the complaints are coming from. If you want a game to hold your hand this isn''t it, If you want a good, short unique game wit', 'Apparently the bug where a friend goes through the next level door successfully and you fall behind breaking the run is a pretty common one. This massive oversight makes playing a roguelike unreliable. Imagine playing a long run to only have it ruined because of a common bug.', 'Mixed', 61.74, 8.83, 1.98);
INSERT INTO reviews VALUES (21159, 635260, 37691, 'The game is fun and highly configurable. The community is toxic and highly hateful.', 'I cannot even play the game it is so garbage. Car is constantly drifting and there is white steam under wheels like when you hold break and gas at the same time, don''t know how to fix it. Nothing in the settings...', 'Overwhelmingly Positive', 95.43, 19.45, 0.38);
INSERT INTO reviews VALUES (21161, 635310, 106, 'Better and funnier than whole the Sniper Elite franchise', 'Designed to be unwinnable unless you hack the game and force all objectives to be complete.\r\nWhoever made this game has never heard of a fucking bipod in their life.', 'Very Positive', 83.96, 0.48, 3.55);
INSERT INTO reviews VALUES (21162, 635320, 801, 'Last Day of June is a beautiful story about a couple who''s living their happiest life together and suddenly having a terrific accident. Rewind the story and replay throught differents characters linked to the story to try to stop the accident. The designs are bright, colorful and the soundtrack is peaceful. I highly recommend this game!!! 💗', 'I am extremely dissapointed. Do not waste your money on a game that may or may not work. There is a common issue of the game launching only once, then never again unless you keep deleting the save file, which makes no sense. It´s been around for years and has not been addressed by the developers. 20 euros for 2-3 hour game is already a bit high, but for one that doesn´t even work, that´s insane.\n\nThe graphics are pretty, the music is good. Sadly, can´t say more because I didn´t get to do more. A', 'Very Positive', 83.52, 38.03, 1.33);
INSERT INTO reviews VALUES (21177, 635940, 473, 'Tip for newcomers!\nUse Magpie with Anime4K upscaler to get clearer image (720p to 1440p for example).', 'this game killed my grandma', 'Overwhelmingly Positive', 98.10, 129.15, 3.48);
INSERT INTO reviews VALUES (21184, 636100, 452, 'This is probably one of the most insane ideas for a game i have ever seen. It does seem kinda wierd or even stupid you may say but it has been executed so well i have to say that''s its  opposite of stupid and it does fit very well into a top down shooter. The shooting is good maybe it lacks weight here and there but its really really good, and the weapon roster is amazing. The way the whole thing progresses reminds me a lot of Nation Red, the mission mode to be precise. You try to survive hordes', 'I got lured in by the names of two of my favorite historic figures.\n\nI understand that it''s supposed to be a musing, but I didn''t find the portrayal of theirs entertaining all the same. Heck, I din''t find this game entertaining altogether, since this seems to be a severly dumbed-down version of Crimsonland / Evil Magic. \n\nIn all honesty, it might be good for a little while, if you got some time to kill, and you don''t mind having no experience / perks transfering from one map to another (you star', 'Very Positive', 91.59, 56.75, 0.22);
INSERT INTO reviews VALUES (21185, 636150, 379, ' Space Cops Will Get Ya ! \n\n Pretty nice space arcade game inspired by Asteroids from Atari. You play as a rogue space blue-haired gal in a rogue space car(?) travelling through vast endless space filled with asteroids and cop ships of different sorts. The game starts slow with fewer enemies but gets chaotic pretty quickly with swarms of enemies flying through the screen. Every 5 levels there is a boss battle (big tank ship) and every 5 levels there will be +1 tank ship (up to 5 total from level', '\nVery basic game. For that price you can still get something better...\n', 'Very Positive', 82.32, 22.97, 23.73);
INSERT INTO reviews VALUES (21186, 636170, 108, 'https://youtube.com/watch?v=1o5OaRM4YWw&pp=ygUKaW5zZW5zYXRleg%3D%3D', 'Cant turn down volume, cant turn off narrator', 'Mostly Positive', 75.00, 0.23, 0.85);
INSERT INTO reviews VALUES (21192, 636320, 140, 'The game has tactical shooting combat with procedural map generation.\n\nThe submarine itself does not feature in the combat, but can get healed or damaged via the random nodes on the map.\n\nI think the setting spoke to me which led me to purchase it, but the story is a weak point.\n\nI like roguelike and roguelite games, if you do this is a nice one to pad out your library.  It is competently made.', 'https://www.youtube.com/watch?v=PCAI_S8X2Bw\n\nThese developers revoked the Steam Key (beta from itch.io) of a user for posting a negative critique of the game. They have issued a new key and apologized, but this still paints the picture of a developer to be VERY wary of.\n\nIn regards to the game, if this were 1/2 the $20 asking price, I woul dbe singing it''s praises. As it is $20 it comes in at a price point where there are additional levels of expectation that simply are not being met. Coupole th', 'Mostly Positive', 73.57, 1.88, 0.57);
INSERT INTO reviews VALUES (21199, 636450, 801, 'I must not fear. Fear is the mind-killer. Fear is the little-death that brings total obliteration. I will face my fear. I will permit it to pass over me and through me. And when it has gone past I will turn the inner eye to see its path. Where the fear has gone there will be nothing. Only I will remain.', 'They didn''t try very hard at all with the VR implementation, it feels more like a low-effort flatscreen mod with barely any visual depth and a strange warping to the UI. Not to mention it''s a complete headache to play for even short amounts of time. Do not acquire this game if the VR mode is what brought you here.\n\nRez, as a remaster, isn’t pleasant either. Despite being a key feature, the music seldom builds into anything memorable, the levels’ short loops quickly get repetitive, and the consta', 'Very Positive', 91.76, 38.72, 1.72);
INSERT INTO reviews VALUES (21201, 636480, 42655, 'I have played this game for a little bit I still have more content to play with the amout of mods you can use just buy it already', 'the developer isn''t a bad person, but he''s undeniably dishonest and naive; promising far too much and never delivering an ounce of it. the game has looked the same for 7 years. various updates come out with frivolous bulls**t that doesn''t address the core flaws with the game. the added content is pure fluff, and even then its all half baked and abandoned for another manic change a few months later. rinse and repeat. hardly any decent core content and so poorly optimised, especially with mods. iv', 'Overwhelmingly Positive', 97.48, 1241.95, 19.35);
INSERT INTO reviews VALUES (21216, 636970, 798, 'This is basically Mount and Blade VR. Definetly some jank, but the combat itself and the really long and in depth campaign make it worth it.', 'My preferred strategy of "stab them in the face until they stop moving" doesn''t seem to work in this game.', 'Very Positive', 80.58, 16.48, 0.60);
INSERT INTO reviews VALUES (21221, 637090, 17283, 'The base game is good for the story - for a more genuine tabletop feel go modded.  I can recommend BEX (Battletech Commanders Extended 3025) and BTAU (Battletech Advanced Universe).  NexusMods for BEX and bta3062 dot com for BTAU. RogueTech is another mod that is worth exploring, with the caveats that it requires a more robust computer and the gameplay can be quite a bit more harsh until you learn the systems it introduces.', 'I really wanted to love this game. I love the tabletop version but I just can''t recommend this. I was hoping for like a Mount and Blade in Battletech with battles similar to tabletop, what I got was a grueling meta-game balanced time that removes a any real semblance of choice, fun, and any chance at roleplaying.\n\nThe average battle begins with your lance (four mechs) fighting an enemy''s lance. However after a turn, another enemy lance will pop in and pepper you with missiles and stagger and dam', 'Very Positive', 85.32, 7670.77, 34.50);
INSERT INTO reviews VALUES (21222, 637100, 3646, 'People acting like forces is the Anti Christ when there''s worse games out there.\nThere''s even worse sonic games than this and I''m not even talking about 06. \nYes this game is very stupid. \nBut it plays fine. \nI wouldn''t say its worth 40 dollars, but its not unplayable. \n\nI know five year old me would have been very happy about the custom sonic friend creator.', 'There is always going to be that small percentage of people who say this game is overhated or doesn''t deserve the flak it gets. They sure as hell will never explain WHY they think it''s good though, they''ll probably just bring up the music or something like that. \n\nIt is your civil duty to put them in their place every time they speak out of line. Unless you''re really young and don''t know any better, I don''t know how you could possibly extract any joy out of this experience. It''s utterly devoid o', 'Mixed', 56.06, 62.80, 17.73);
INSERT INTO reviews VALUES (21230, 637650, 16521, 'now i can never listen to "stand by me" without violently sobbing. 10/10 would roadtrip with the boys again.', 'As much as I like Final Fantasy 15, Denuvo ruined it completly for me. Not only do stutters occur, it crashes on some scenarios of the game. I would like to enjoy the game in its full glory, without any prevention which eats my FPS away. If it would be possible, could you remove Denuvo for better performance from this game?', 'Very Positive', 82.60, 127.75, 76.47);
INSERT INTO reviews VALUES (21231, 637670, 1342, 'It was worth a one time playthrough since we are big fans but next time we will play the classic SNES version again which is simply a greater experience in every aspect, even the 16 bit graphics.', 'I hate to not recommend this, but only because of my own nostalgia. Secret of Mana was an awesome SNES game because it was an SNES game, making it one of the beginnings of action RPGs. The combat itself was okay for the time, being on an old console game, but it won''t translate to someone who isn''t looking through rose colored glasses.\r\n\r\nFor definite negatives, the magic was absolutely amazing back then, up there with any RPG, but they kind of fumbled that in this one. There are levels for each', 'Mostly Positive', 71.31, 32.67, 53.35);
INSERT INTO reviews VALUES (21241, 638000, 225, '　　　　　　🏔️ \n　　　　⛷️　　　🚠\n🚑　🏁　　　　　　　🚠', 'super repetetive. I thought Id really like this but it wasnt for me.', 'Very Positive', 88.00, 17.65, 0.82);
INSERT INTO reviews VALUES (21244, 638070, 161, 'Brings back good memories of AC Brotherhood multiplayer, only without everyone running on roofs like idiots.  Also this has dedicated servers so it''s at no risk of a multiplayer shutdown like the AC games.  There are a few mechanics to encourage stealthy game play and penalise running around like mad.\n\nMy one complaint is that guards are a little bit silly.  Guards work by policing an area and preventing hostile actions.  They can become temporarily distracted, during which time hostile actions ', 'horrible crap horrible awful game not fun and just crap and horrible and so not fun dont get this game unless you want to kill yourself this game is so so so bad that its awful', 'Mixed', 63.98, 10.07, 0.95);
INSERT INTO reviews VALUES (21247, 638160, 151, 'This is one of the most aggressively Japanese games I have ever played.', 'i''m a big fan of neptunia franchise and enjoyed all of the games but omfg this game is a big NO i played for around 9h but can''t force myself to continue anymore just no never', 'Mixed', 68.21, 0.45, 8.17);
INSERT INTO reviews VALUES (21248, 638200, 225, 'Why does steam not have Capitalism Lab? \nLoved this game growing up. One of the better business games made.', 'recently restarted on crappy pc. game imploded randomly after playing for 2 days with no problems. can''t load save, start new game, nothing. re-installed, still nothing. tried windows 98 as admin, nothing. get open set error. tried launching the save file get resource error copied that file into save folder, gives same error. No clue how it''s unusable after a 4 hour break of playing it perfectly fine. I''ve seen some wacky stuff with pc''s and games but this might top the cake. also when it was wo', 'Very Positive', 86.22, 55.87, 140.80);
INSERT INTO reviews VALUES (21249, 638230, 11281, ' I Thought I was going to be alone.... I was wrong\n\nI decided to play journey, I had already played the first 5 minutes months ago and decided I was going to sit down from the start and finish the game. I had no idea that there was other players with me until I ran into them, Even though we could only communicate through a little music note it felt nice to have another stranger, a random connection to another person. It was truly unexpected, I loved it it. Thank you random people who i played wi', 'This is an experience, a beautiful one.  However, it is a bit too short/simplistic and skew too much on the "artsy" side.  It didn''t quite click for me, but for some people this probably resonates much more than it did for me.', 'Very Positive', 92.56, 1.83, 1.95);
INSERT INTO reviews VALUES (21260, 638510, 1673, 'Game is great but freezes constantly on the "work" screen. Looked up the issue and its been happening for 10+months. No fixes yet seems wild and cant find a workaround. Happens constantly even after reloading and losing the day. Really irritating as the game is fun. Hope they figure this out eventually but seeing as its been happening since launch I wont get my hopes up.\n\nEdit: My issue was not fixed yet as I just posted this, but the fact that the Dev reached out almost immediately asking for d', 'Played a game on easy for three days just so I could see the end game, after failing the endgame on a harder setting. Beat every single challenge until the final winter. Had a heat challenge upcoming, had four buildings producing heat, had a 95% chance of success. Lost it... killed every... single... villager. From dominating the game to game over in one second. Forget it.', 'Overwhelmingly Positive', 95.22, 39.48, 68.47);
INSERT INTO reviews VALUES (21262, 638650, 691, 'This is basically a 200-hour-long dating simulator with combat mechanics.', 'Not Worth It Unless You''re a Hardcore Fan\n\nI had high hopes for this game, but unfortunately, it fell short in almost every way. The graphics and models feel outdated and rough around the edges, like something out of a decade-old game. As for the gameplay, it’s just not engaging—there’s little to no replay value, and the mechanics feel clunky and uninspired.\n\nHonestly, it feels like the developers were banking on nostalgia rather than delivering a solid gaming experience. If you’re not a die-har', 'Very Positive', 82.05, 282.38, 0.73);
INSERT INTO reviews VALUES (21266, 638850, 607, 'This has a lot of potential, very nice graphics, game play is good, you need this game!', 'Although this game is listed as a "Full Release", the Dev said this to be able to abandon the game. This is indeed an incomplete game, missing features, incomplete world, incomplete story, and more. Objects are broken and so is the environment. Do not buy this game, it has been LONG abandoned by the dev (at the time of posting it has been 4 years since the last word from the dev). Do not buy, you have been warned, this is NOT a working game.', 'Mostly Positive', 70.35, 74.85, 11.20);
INSERT INTO reviews VALUES (21271, 638970, 35923, 'this game kinda misleading, it says yakuza 0 but there are a lot of yakuza all around you', 'cant have majima sex', 'Overwhelmingly Positive', 96.96, 200.98, 14.92);
INSERT INTO reviews VALUES (21272, 638990, 335, 'Yet another zombie killing ,leveling, crafting, exploring game. A little harsh with the passing of time in-game but a good play(I installed a mod that let me stop the time so I can actually enjoy what was happening because it''s a game after all not IRL)', 'This game has so much promise and does not deliver.\n\nI feel this is common for Chinese games. The art style is great. The premise is intriguing. The first 2 hours of gameplay has this on full display, and this it just grinds to a halt. \n\nIf this was early access I could excuse the poor translation. I could excuse the grind due to mechanics that are not balanced, but the game is pretty much abandoned now.\n\nGet it. Play the first 2 hours, and then use the steam refund. It''s not worth it past that.', 'Mostly Positive', 78.21, 45.98, 2.63);
INSERT INTO reviews VALUES (21273, 639130, 310, 'Pilot Wings: Airplane Edition :)', 'Stuck on press any button screen, Tried on two computers (index and psvr2). Tested after 14 days so no refund. Dont waste money on a broken pos.', 'Very Positive', 89.35, 4.05, 2.28);
INSERT INTO reviews VALUES (21274, 639170, 603, 'bring back mc story mode and bring me a season three!', 'This game is a great way to test your patience, or maybe even strengthen it.', 'Very Positive', 90.55, 8.55, 5.38);
INSERT INTO reviews VALUES (21280, 639270, 199, '~ a novel approach to rail shooters. interesting and i found it to be entertaining when played in spurts. I don''t feel it was worth the 20$ I put out for it though.', 'I like the concept - arcade machine, side-scrolling fun, infinite ammo, just you and lots of enemies. The best part are the immersion sections where you can hop into specific set pieces of the map to throw knives, snipe distant enemies (sniping always being troublesome in VR), dual-wild bazookas, or drive various vehicles (which is honestly more trouble than its worth most of the time). It''s a cool and fun concept that helps shake up each level, and they''re completely optional (minus the challen', 'Very Positive', 94.97, 0.50, 1.12);
INSERT INTO reviews VALUES (21288, 639490, 849, 'i wish erika furudo was real so she could intellectually rape me with Facts and Logic', 'I''ve never seen a writer shoot themselves in the foot this hard. There''s dropping the ball, and then there''s Twilight Of The Golden Witch. Save yourself 120 hours and read literally anything else. Listen to the Japanese fanbase when they tell you Ep8 is unreadable garbage that ruins the entire series.', 'Overwhelmingly Positive', 96.23, 93.73, 59.27);
INSERT INTO reviews VALUES (21302, 640120, 133, 'Something truly magical here... I honestly don''t even know how to describe it. Visuals are something else, for me it looks like a Nintendo''s Splatoon + Valve''s "something", and it''s so beautiful to look at. The amount of polish is absolutely insane, sound design is marvelous and physics are top notch. So far, the puzzles were more on the easy side, but I only played for like ~3 hours. Playing this exclusively on a Steam Deck. Runs flawlessly.', 'I never get motion sick.  Even in VR with no comfort settings I''ve flown planes in Ace Combat 7 with no issue.  But man this game quickly gave me a headache and motion sickness.  This is probably the first and only video game to accomplish getting me sick.  Even fiddling with camera tracking settings didn''t seem to help.', 'Very Positive', 93.98, 3.72, 0.38);
INSERT INTO reviews VALUES (21311, 640380, 247, 'Nobody will read my review so I will eat 1 Tablespoon of Spicy Ketchup for every like this gets.\n', '.', 'Very Positive', 94.33, 4.30, 0.38);
INSERT INTO reviews VALUES (21312, 640590, 585, 'Long before time had a name, the First Spinjitzu Master created Ninjago using four elemental weapons. But when he passed, a dark presence sought out to collect them all: Lord Garmadon. So I, Sensei Wu, his brother, sought out to find four ninja to collect them first.', 'why this game always crashing', 'Very Positive', 87.69, 24.53, 3.83);
INSERT INTO reviews VALUES (21320, 640820, 16996, 'I have spent far, far, far too long with this game.\nI adore it. I love it.\nThere is no twist to this statement, I genuinely just adore Pathfinder Kingmaker, it''s character, the world and the plot.\n\nBest 5 dollars I ever spent, and I wish I had played it sooner.', 'New company has purchased the license and is requiring all original owners to agree to their own new data policies that allow for micro transactions.\n\nI would no longer recommend buying this game.', 'Mostly Positive', 76.57, 388.78, 182.02);
INSERT INTO reviews VALUES (21326, 640990, 232, 'i geniunely wish i could put into words what i just went thru while playing this game but i cant. JAHDJADHJADHADJHA ITS SO AWFUL ITS LIKE A BAD WATTPAD FANFIC THAT I COULDNT STOP PLAYING. THE HUMOR IS SO BAD BUT IVE NEVER LAUGHED SO HARD AT A VISUAL NOVEL IN MY LIFE. DO I REGRET BUYING THIS? WELL. NO. WAS IT MY BEST INVESTMENT? ABSOLUTELY NOT. I DIDNT KNOW WHAT I WAS GETTING INTO WHEN I BOUGHT IT????? BUT ITS NOT THE WORST??? LMFOADHADJHADH I DONT KNOWWJJADA I DONT KNOWWW!!!!', 'I haven''t been able to play this game as a popup comes up entirely in Japanese with the only English word being unicode. It seems to be some kind of common error, but every search I made there were no solutions posted.\n\nI tried to get this refunded but couldn''t, because even though its unplayable and doesn''t start, it still runs in the background and shows me as high playtime. Feels like a scam to be honest, I''ve posted in the bugs section, so if it''s solved I''ll amend my review.', 'Very Positive', 82.33, 7.98, 13.33);
INSERT INTO reviews VALUES (21328, 641080, 1439, 'Trials Rising is a masterpiece of a game in and already excellent series. Another perfect combination of platformer and physics, loaded with content and fun ways to compete with friends without having to play at the same time as them (while still having the option to do so). Super high skill ceiling makes the game very challenging but rewarding.\n\nI think the Steam version had a hiccup where it wasn''t playable for a while but it''s fine now. When I booted it up it crashed, then I booted it again a', 'Cannot believe they are still able to sell this game, it doesn''t function. A huge amount of people cannot get this game to start whatsoever due to Ubisoft''s insistence that you install their bloatware. This is a phenomenal game, Trials deserves better than Ubisoft.\n\nI highly recommend looking into how many people are complaining on forums and in tickets before purchasing this game.', 'Mixed', 64.07, 53.93, 24.13);
INSERT INTO reviews VALUES (21329, 641320, 8166, 'i am a chef in real life\n\nthis game caused me genuine stress and i found catharsis in frying a what was supposed to be baked fish in an open flame, slapping it onto a plate with incorrect sides and sending it with rage to a customer who arrived 5 minutes before closing.\n\ni have come to the realization i genuinely hate my life', 'Despite the warning the devs have now added to the store screen, i genuinely believe that if i am capable of running CyberPunk2077 on high settings at 120 FPS  i should at least be able to get 60 FPS in this game on low.\n\nThis game takes place in a single room, with most assets rendered at all times. I really do not understand how this game manages to run so poorly.', 'Very Positive', 85.71, 2.97, 35.35);
INSERT INTO reviews VALUES (21331, 641780, 1926, 'i have only tried a few other sims, however this sim is great for learning\r\nthe swich into acro(intermedite) is realy confusing as there is no explanation, but it has realy helped me learn how to fly', 'I''m new to FPV drones and decided to get this for sim practice before getting a drone. While I liked the tutorial/onboarding and the general map design, I am simply shocked by how atrocious every other aspect of this game is. \n\nIt is super slow just to use. Want to restart? Wait 5 seconds. Want to reset a checkpoint? Wait 5 seconds. Finished a race? Wait an entire 15 seconds before you can jump back in to either a new map or even just restarting. Why? Who knows, the UI just loads so slowly. My b', 'Very Positive', 92.06, 22.30, 8.28);
INSERT INTO reviews VALUES (21337, 641960, 946, 'to be honest this is a great workout app. U have to maybe learn the proper way to punch and stand, but after that I clocked between 1 and 1 and half hours and actually lost weight and it made me sweat as well as muscle elasticisity being improved. Recommend\r\n.', 'Game got abandoned 4 years ago, CEO Sam Cole doesn''t give a damn about the issues that were there in 2020 already. Just went full money hungry on his subscription based FitXR. \r\n\r\nWorkout in the game is good and fun, if it works and the game doesn''t put your ingame position into a wall with no way to reset it except for going into the cfg file itself. Has variation in music and patterns, tho you wont know what you get until you are already in the workout.\r\nPlayed the DLC using an "alternative" m', 'Mostly Positive', 77.70, 84.55, 5.05);
INSERT INTO reviews VALUES (21339, 641990, 10764, 'Hella funny game. I highly recommend with friends. \r\nI was playing a little bit ago with 3 of my friends on a map and we couldn''t get out so one of my friends decided that digging out under the electric fence was a good idea. We spent 3 hours on that map dying over and over, my friend who was digging the tunnel started to go crazy cause we weren''t out yet, like when we needed just 1 more lumber than we had anticipated he started to laugh hysterically, he laughed even more hysterically when we fi', 'This game can be fun at times, especially with friends. However, their idea of a difficulty curve is removing more and more sandbox elements to the point where it feels like escaping is just solving a puzzle or trying to figure out what the game ''wants'' you to do. To me, this is a HUGE setback for the franchise.', 'Very Positive', 91.06, 17.20, 18.88);
INSERT INTO reviews VALUES (21343, 642090, 765, 'Dang, this game is THE GAME - I was gooning for HOURS! :D - You wouldn''t last 5 mins playing this game! PLEASE CLICK HERE!!!', 'the humour in this game is a boner killer', 'Overwhelmingly Positive', 95.42, 12.72, 3.72);
INSERT INTO reviews VALUES (21348, 642560, 275, 'Fascinating and mesmerizing puzzle game that just keeps getting better', 'Most of the levels are too easy. Many levels are thought through faster than you have to wait for the animation to end the level. Also waiting for the menu display and camera intro to go away before the next level annoys me.\nAt level 60 and above the difficulty gets good, what took you so long game? All the levels before seem to be only the tutorial.\nThere are 75 levels, so for me only about 15 of 75 levels are good, which is a really bad ratio of 20%. Not enough for me to give this a positive r', 'Very Positive', 93.09, 3.60, 2.12);
INSERT INTO reviews VALUES (21352, 642610, 132, 'Shape of the World is a nice adventure game with some original colored graphics and a cozy ambiant. I recommend it!!! 💗💗💗', 'Just walking simulator, you can watch full game with no commentary on youtube and save your money.. and no, I am not a person who just "didn''t get it" - I loved Proteus and saw art in there.. this one was just pseudoart..', 'Mostly Positive', 75.76, 26.97, 1.15);
INSERT INTO reviews VALUES (21354, 642650, 129, 'Pepper''s Puzzles is a great puzzle game! It''s fun and challenging!', 'This is a nice looking nonogram game but lacks some QoL features and commits the cardinal sin of having puzzles that are *not* sized to multiples of 5.', 'Overwhelmingly Positive', 95.35, 16.42, 3.65);
INSERT INTO reviews VALUES (21361, 642770, 116, 'Holy crap, this is the real deal. I had everything from cheap belt driven Kam turntables right up to technics 1210 mk3''s back in the day and this feels so good its unreal.\n\nI was able to go right in and mix tracks together at a pretty accurate level with only about 5 minutes of playing around and getting used to it. The fact you can output the master track seperate to what you are listening to with the cue mix is fantastic.\n\nCan''t wait to see what the developer does next.\n\nNB: I''m on oculus and ', 'Some off my issues have been fixed, but there''s still no new content.  I can only recommend this for serious DJs, but then serious DJs will have their own equipment like I do, and tbh, trying to do all this in VR is a little awkward.  It''s also awkward to reset your position.\n\nUpdate: the Cue system seems to be working fine for me now, maybe I need practise, but this all feel awkward for me still.  I get a track set up and I can''t get the damn thing to play quick enough like with real decks.', 'Very Positive', 92.24, 20.02, 2.13);
INSERT INTO reviews VALUES (21366, 643200, 163, 'this game feels like speedrunning therapy', 'This game doesn''t really have a reason to be a game, since there''s just no gameplay. It would work better as an illustrated book or something, although the visuals aren''t that good. I assume it''s supposed to look like a child''s drawing, but it doesn''t really work either. You can make something minimalist and yet more evocative or appealing. The texts are the only interesting part, but there''s not much to find there either. As a free experiment on Itch I would understand. Actually, if it''s really', 'Mostly Positive', 74.23, 0.30, 0.30);
INSERT INTO reviews VALUES (21373, 643620, 131, 'Night Trap go hard. \nIts the first game in the Five Nights at Freddie''s franchise and is harder than Dark Souls. \nSo obscene it got a T rating.\nPlay it.', 'games kinda crap. very trail and error. catchy song though', 'Very Positive', 84.73, 2.95, 1.27);
INSERT INTO reviews VALUES (21374, 643810, 383, 'Bird up', 'Controls are BEYOND clunky, motion sickness inducing (and I don''t generally get motion sickness), blood spatter when you hit something which doesn''t vibe with the... vibe. I spent a whole five minutes on this and I''m already running for the refund button. I love pixely aesthetics, too, so it''s not that I''m one of THOSE people. Obviously, if I were, I wouldn''t have bought it. I love Superflight. I was hoping this would scratch the same itch, but controlling your little guy is so hard and counter-', 'Very Positive', 86.16, 0.75, 0.10);
INSERT INTO reviews VALUES (21375, 643820, 112, '👍👍👍', 'This could be a good game If It wasn''t for the constant crashing (sometimes with a bit of freezing too) and there''s no way to fix this. \nI''m glad the game let''s you skip chapters to get the achievements. \nThe graphics are okay and the story is there, I guess. I don''t remember how long It took me to complete this but some of my playtime was just idling to get the cards.', 'Mixed', 61.61, 5.40, 7.38);
INSERT INTO reviews VALUES (21378, 643880, 353, 'Fun and charming game. Definitely worth the price on sale (80% off as of writing this review).\n\nHowever, the default difficulty (Normal) is ruthless and brutal when you''re playing solo. The reach of your character to hit the ball is very limited, and with the countless attacks of enemies (ranged, physical and debuffs), you''ll quickly find yourself struggling immensely just to find where your ball is at - let alone hit it with your slow movement speed and limited range. Unless you have lightning ', 'I don''t know... I liked the concept alot, otherwise I wouldn''t have wishlisted it for the longest time and finally bought it.\nBut in practice it''s only made me annoyingly realize how bad I apparently am on a simple brick-breaking game made fantasy story & stuff. I''m aware it''s likely more a me-problem and nothing against the game, but it''s not worked for me.\nI think it''ll just take patience, but I couldn''t afford applying it over here at this time. \n''Could''ve had a demo.\n\nRather than prolong my ', 'Very Positive', 91.78, 2.18, 0.45);
INSERT INTO reviews VALUES (21379, 643900, 115, '👍', 'This game is kind of mediocre, mostly just that it doesn''t control very well and it''s sort of low quality.  I think a lot of people sort of give this a pass because it''s a solo dev and he tried - but I kind of regret that I bought this because now it''s in my library and I probably won''t ever play it.  If you actually want to buy this, I would suggest to actually try it and refund if you don''t like it instead of letting it sit the whole time.', 'Very Positive', 93.04, 22.02, 0.57);
INSERT INTO reviews VALUES (21383, 643960, 291, 'An amazing game, and easily best tower defense EVER MADE. All of the tower defense games are all the same, but this one has an original concept and unique gameplay. It should be 1000x more popular than it is.', 'I can''t even begin to tell you how frustrated I am with this game.\nThere are achievements for not letting the enemies touch a single one of your gems for the levels.\nI don''t even know how often (but VERY often) I have failed to complete this task on some levels because sometimes put of nowhere from one second to the next the keyboard shortcuts don''t work anymore. And of course, it''s always when the enemies arrive for which the towers aren''t strong enough.', 'Mostly Positive', 79.73, 10.75, 28.38);
INSERT INTO reviews VALUES (21398, 644390, 1230, 'very accurate reproduction of the board game.  For me the medium AI is challenging.  Purchased the base game and two DLC for less than $ 15, before tax', 'This is an ok adaptation of the board game''s rules and a nice single-player adaptation.\n\nHowever, there are a lot of design flaws that make it feel cheap and underdeveloped.\n\nMultiplayer is barely passable, and pray you don''t have any exceptions during play because sessions aren''t saved and there''s no way to return as the game autoforfeits for you.\n\nLook into other methods of playing Lords of Waterdeep.', 'Very Positive', 94.07, 66.18, 1.85);
INSERT INTO reviews VALUES (21401, 644480, 157, 'If you''re into the horror kind, RE/SH-like, with lots of reference about mostly anything, this is for you !!\r\n\r\nReally fun to explore and discover, probably better with someone tho as it''s highly "co-op" oriented', 'Pathetic!\nIt makes Banned Memories look like Silent Hill', 'Mixed', 68.15, 9.05, 0.85);
INSERT INTO reviews VALUES (21407, 644640, 126, '⣿⣿⡻⠿⣳⠸⢿⡇⢇⣿⡧⢹⠿⣿⣿⣿⣿⣾⣿⡇⣿⣿⣿⣿⡿⡐⣯⠁ ⠄⠄\n⠟⣛⣽⡳⠼⠄⠈⣷⡾⣥⣱⠃⠣⣿⣿⣿⣯⣭⠽⡇⣿⣿⣿⣿⣟⢢⠏⠄ ⠄\n⢠⡿⠶⣮⣝⣿⠄⠄⠈⡥⢭⣥⠅⢌⣽⣿⣻⢶⣭⡿⠿⠜⢿⣿⣿⡿⠁⠄⠄\n⠄⣼⣧⠤⢌⣭⡇⠄⠄⠄⠭⠭⠭⠯⠴⣚⣉⣛⡢⠭⠵⢶⣾⣦⡍⠁⠄⠄⠄⠄\n⠄⣿⣷⣯⣭⡷⠄⠄⢀⣀⠩⠍⢉⣛⣛⠫⢏⣈⣭⣥⣶⣶⣦⣭⣛⠄⠄⠄⠄⠄\n⢀⣿⣿⣿⡿⠃⢀⣴⣿⣿⣿⣎⢩⠌⣡⣶⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣆⠄⠄⠄\n⢸⡿⢟⣽⠎⣰⣿⣿⣿⣿⣿⣿⢀⣾⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣦⠄⠄\n⣰⠯⣾⢅⣼⣿⣿⣿⣿⣿⣿⡇⣾⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⡄⠄\n⢰⣄⡉⣼⣿⣿⣿⣿⣿⣿⣿⢸⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣧⠄\n⢯⣌⢹⣿⣿⣿⣿⣿⣿⣿⣿⢸⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⠄\n⢸⣇⣽⣿⣿⣿⣿⣿⣿⣿⣿⠸⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⠄\n⢸⣟⣧⡻⣿⣿⣿⣿⣿⣿⣿⣧⡻⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⠄\n⠈⢹⡧⣿⣸⠿⢿⣿⣿⣿⣿⡿⠗⣈⠻⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⡇⠄\n⠄⠘⢷⡳⣾⣷⣶⣶⣶⣶⣶⣾⣿⣿⢀⣶⣶⣶⣾⣿⣿⣿⣿⣿⣿⣿⣿⣿⠇⠄\n⠄⠄⠈⣵⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⢸⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⠄⠄\n⠄⠄⠄⠸⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⠘⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⠇⠄⠄', 'don''t get this game ever because the only reason that i ever got it was for the coop and that has been removed', 'Mostly Negative', 37.30, 2.05, 1.70);
INSERT INTO reviews VALUES (21409, 644670, 108, 'WE WILL TAKE JERUSALEM\nDEUS VULT DEUS VULT DEUS VULT DEUS VULT DEUS VULT DEUS VULT DEUS VULT DEUS VULT DEUS VULT DEUS VULT DEUS VULT DEUS VULT DEUS VULT DEUS VULT DEUS VULT DEUS VULT DEUS VULT DEUS VULT DEUS VULT DEUS VULT DEUS VULT DEUS VULT DEUS VULT DEUS VULT DEUS VULT DEUS VULT DEUS VULT DEUS VULT DEUS VULT DEUS VULT DEUS VULT DEUS VULT DEUS VULT DEUS VULT DEUS VULT DEUS VULT DEUS VULT DEUS VULT DEUS VULT DEUS VULT DEUS VULT DEUS VULT DEUS VULT DEUS VULT DEUS VULT DEUS VULT DEUS VULT DEUS VU', 'So, the developers have outdone other lazy VR-developers and deprived players of the ability to use the joystick not only to turn, but even to move.\nBravo, I''ve never seen such a mockery of players before.\nRefund, of course.', 'Mixed', 59.26, 3.25, 0.10);
INSERT INTO reviews VALUES (21415, 644830, 2905, 'Surge 2 is a good game, no doubt about it, just not so good as the first one. I like new parry system, weapon and enemy variety, world building and how city changes through the story. I don''t like story at all, some basic garbage about saving a girl and you play as a big nobody who don''t have any personality. NPCs are awfully stupid, just talking puppets, the only one interesting character is Warren from first game. First half of the game was too boring, level design and city layout are very con', 'I at first thought when i got this my PC was old and couldn''t run it, fast forward some years and my new PC is a small nuclear reactor.\r\n\r\nThis game runs like it''s missing legs. Like, all of them.', 'Very Positive', 81.41, 50.12, 4.25);
INSERT INTO reviews VALUES (21419, 644930, 18145, 'spent 5 hours building a big base and killed most of the zombies, and then a single zombie somehow got in the base and infected the houses and overwhelmed all the defences, i lost all the progress. \n\n10 out of 10 would recommend  \n\n', 'Dev abandoned the game years ago, right after making a few unpopular changes that no one liked (hello mutants who can hear a fart from 100km away).\n\nOh yeah, they''re also vehemently anti-modding despite producing no new content, and went to the trouble of hardening their game against modders.\n\nTAB is a decently challenging time waster, but it lacks the depth players want from a strategy / wave / zombie survival game. This game IS NOT worth $30. Don''t buy this for more than $15, unless money real', 'Very Positive', 80.17, 140.13, 205.70);
INSERT INTO reviews VALUES (21420, 645090, 715, 'If you''re a fan of puzzles and achievements, you''ve come to the right place !\n\n*** All ZUP Games have cool Puzzles + Trading Cards + a lot of working achievments ***\n\n+ Successes are letters in different colors that you can ideally use for profile design\n\n--> If you have the option, buy them all in a bundle to save money. You won''t regret it', 'Yet another entry of the "pay for steam achievements and not an actual game" series. People who are recommending it are not playing the game itself, and the game itself is simple and bland. Don''t waste your time, money, or pride.', 'Very Positive', 92.31, 3.62, 0.83);
INSERT INTO reviews VALUES (21444, 645630, 21316, 'Just spent 30 minutes disassembling an entire engine, only to figure out the problem was the Radiator fan housing. Then spend another 30 minutes re-assembling the engine 10/10 would recommend XD Autism brains will be happy, also OCD ones.', 'Game did not start (on MacBook Air M2).', 'Very Positive', 90.34, 45.25, 0.18);
INSERT INTO reviews VALUES (21448, 645730, 491, 'I was going to write an essay but really nobody will ever read this so suffice to say I''m giving this a thumbs up but 95% of the population of Earth will hate this game but it does have several interesting things to it and it''s not a bad game, it''s just incredibly niche even by JRPG standards.', 'Has no autosaves and the only place you can save is at your base. So if you end up in a fight you can''t win on a another level your only option is to potentially lose hours of progress by reverting to your last homebase save. Also mired by a lack of PC features, inexplicable frame drops, telling you "not turn your console off when saving", etc, etc. Utter excrement tier PC port and "Remaster".', 'Very Positive', 80.45, 48.08, 2.63);
INSERT INTO reviews VALUES (21451, 645790, 925, 'The Alamo', 'its a good concept, but it needs some serious work, especially with the AI, i enjoy it, but i dont recommend you buy it\nits fun, when its not frustratingly in need of work', 'Mostly Positive', 79.46, 10.10, 29.33);
INSERT INTO reviews VALUES (21464, 646200, 842, 'Still fun, if very VERY dated.\n\n', 'Another cheap mobile game', 'Very Positive', 81.95, 5.60, 0.38);
INSERT INTO reviews VALUES (21467, 646270, 982, ' i got murdered by a talking soviet dog, 10/10 would recommend', 'Disappointing. I bought the bundle, should''ve known this kind of thing is always worse.\nThere was this confusing thing where I had to grab specific items at the start before I was allowed to run around and grab whatever I wanted, and the panic part at the end of the timer lasted too long.\nThe UI and experience in the actual gameplay were very confusing. There''s like 3 different ways to ration food. Speaking of, the essential supplies in the original were more obvious. You need food, you need wat', 'Very Positive', 90.02, 12.67, 0.23);
INSERT INTO reviews VALUES (21478, 646500, 371, 'As someone who has studied Ancient Egyptian history and linguistics, I really enjoy this game. Not only the gameplay, music, and graphics are great, but there it shows that a lot of research was put into this game to make it very educational too.', 'yet another similiar game with always the same mechanism\nthe pyramid construction event is totally st.\nmore and better i built, worse situation i would face later.\nsk the tomb upkeep, this mechanism is absolutely the teacher of modern time american housing.\ni paid all i have to buy and build a house, and then i have to pay unreasonable high tax for holding it through out my life.. this is just insane.', 'Very Positive', 84.64, 3.65, 8.18);
INSERT INTO reviews VALUES (21480, 646570, 65914, 'This is the best game on Steam, especially if you''re an adult. You can stop playing at literally any moment, you don''t even need to pause; you don''t need internet connection, so you can play on a plane; it''s incredibly deep, brilliant, fun, and as immersive as you can afford to be immersed without punishing you for not being able to commit. \r\nIt''s fun to learn, and once you have knowledge of the game, it''s not about maintaining a skill (like FPSs) or constantly keeping up with the Dev''s changes ', 'Overwhelmingly positive? What am I missing here? This is boring! I love deck builders but this one is generic and repetitive. The rewards don''t seem that interesting, the enemies are generic, turns are basically some element of strike or block, where''s this "intense amount of fun" that everyone talks about? I''m already bored and can''t be arsed to keep rinse repeating this.', 'Overwhelmingly Positive', 97.79, 868.78, 0.62);
INSERT INTO reviews VALUES (21486, 646910, 25277, 'I have a feeling that this game was designed by people who had never actually driven or sat in a car, and everything they knew about driving was through bing searches and 80''s action movies.\nStill worth the price tho, beautiful graphics and racists', 'I can''t express how deeply unsatisfying the non-physics-based driving feels; it''s worse than a cheap arcade motorcycle game. Furthermore, online required (see what happened to The Crew 1), terrible, LONG, extremely frequent cut-scenes, very poor UI decisions (I couldn''t even figure out how to exit the game!), FPS and resolution limited, a mandatory anti-cheat driver, and mediocre graphics means that there are far better games out there. The only reason I can see to purchase this game is for its ', 'Mostly Positive', 77.18, 3.38, 0.53);
INSERT INTO reviews VALUES (21497, 647570, 227, 'An incredibly interesting walking sim. Honestly a huge fan of it''s story and vibe. But here I am trying to replay it in 2024 and the Uplay/Ubisoft log-in literally refuses to work. I literally can''t log-in to a game I OWN. I literally can''t PLAY A GAME I OWN. Cool cool cool. Fuck me I guess. I really wanted to replay a fascinating game experience I loved a few years ago and wanted to re-experience today, but fuck me Ubisoft, fuck me.', 'Anyone wanting to play this game be warned: it installs the outdated Uplay. You''ll need to manually install Ubisoft Connect, log in, and only then can you play via Steam. It''s unacceptable that they''re still shipping this with outdated software. This alone justifies a negative review. Story wise, it''s like Soma. The setting is nice. Expect some jumpscares!', 'Mixed', 66.96, 1.75, 2.08);
INSERT INTO reviews VALUES (21502, 647740, 271, 'Great game, it has been abandoned so there are no more updates so you get what you get, and don''t expect to play with random pepole because the average online ammount of pepole is 0, still great fun even solo, especially fun with freinds would recomend', 'needs way more work to be worth the money', 'Mostly Positive', 77.49, 13.92, 71.27);
INSERT INTO reviews VALUES (21505, 647830, 2607, 'I accidentally left my pc on for a week whilst this game was running.', 'In short, the game IS good, but there are some things to consider... Firstly, I don''t like calling it a sequel of the first LMSH. It just doesn’t deserve to be called like that if we compare the qualities of both games in terms of technical features and story itself. Secondly, mentioning ''tech features'' again, there are A LOT OF bugs. Like… seriously? For 60+ hours I played this game I have been stuck in textures more than 10 times. Besides that, I personally didn’t like the fighting system in t', 'Very Positive', 84.31, 199.65, 62.02);
INSERT INTO reviews VALUES (21514, 647960, 2445, 'this game is fun and all until you are playing against 屁股歼灭者 and 专业花盆吃者 and they destroy your base in less than a minute', 'im racist now', 'Overwhelmingly Positive', 97.10, 9.55, 74.00);
INSERT INTO reviews VALUES (21518, 648050, 109, 'It''s blisteringly fast, with a pleasing aesthetic and a soundtrack that ranges from decent to certified bops. \r\n\r\nDriving has just the right amount of complexity, easy to learn but hard to master, with a good variety of machines. The sense of speed is great. The earlier tracks are simple to allow for new players to find their footing, and the later ones are extremely challenging, but in a fair way (in my opinion). I haven''t tried the track editor for myself, but I''ve played some custom tracks fr', 'A very neat tech demo, they''re high if they think this is worth 12 bucks tho.\n\nThe handling is fine, but the enviroments and tracks are boring as hell.  Track editor is very basic as well.\n\nRefunded for now, but will wishlist, and revisit when it gets updates.\n\nJust don''t wanna get burned by another EA lol, its not you devs :/', 'Very Positive', 90.83, 14.20, 0.17);
INSERT INTO reviews VALUES (21521, 648100, 678, 'For the first 15 or so hours (The first two full loops) this was the most fun I think I have ever had with any game in a long time, and then somehow, halfway through the third loop, the game had a massive dip in quality, still decently enjoyable, just not as spectacular as the first two loops, only to be followed with the WORST ending in the history of any medium of storytelling ever. Raging Loop will go down in my mind as one of the greatest, and THE WORST video game of all time. The title is v', 'Starts great but the story gets increasingly ridiculous as the game goes on.', 'Very Positive', 90.86, 26.52, 13.07);
INSERT INTO reviews VALUES (21527, 648350, 22867, 'Jurassic world evolution is a nice lesson which teaches you that your beloved pet dilophosaurus named "Spit on that thang" will eventually die of old age.', 'Openly greedy company. They had a complete full game product ready for their launch date, yet CHOSE to partition their complete product to hide behind superfluous paywalls. $40 game with day-one $10 DLC. That is a 25% mark up fee to buy a couple extra dinos that should have already been provided within the core game. Unacceptable.\n\nOther than the couple titles I already own, this overly greedy business model makes it easy for me to never buy another title from Frontier Developments. This bar of ', 'Very Positive', 86.47, 47.62, 0.25);
INSERT INTO reviews VALUES (21530, 648410, 2560, 'There are a lot of retro CRPGs on Steam that try to evoke the feeling of classic 90''s RPGs like Fallout.  Few manage it.  Most are trying to hard to emulate those older games that they feel more like rehashes then something fresh.\n\nColony Ship is different.  You can see the influences, but it''s not afraid to forge it''s own path.  The end result feels manages the tricky balance of feeling like part of the lineage but also being it''s own thing.  Stylish and original world building, challenging and', 'Tried my best to enjoy the game but there are too many things that make the game less fun. The game needs a real map so you can find areas you have not been to yet. The "map" that you currently have is great for fast travel and fetch quests but it is not a real map. So many fights feel pointless to even attempt either because the enemy has so much more AP then you or they can pull you and you don''t get to even try to dodge. Even if you win the loot and exp don''t feel worth it. I have played othe', 'Very Positive', 87.38, 227.00, 21.72);
INSERT INTO reviews VALUES (21537, 648580, 600, 'All the fun of B-movie thriller, with healthy doses of humor and wit scattered between cheesy emotional scenes. That, on its own, wouldn''t sell this experience, but what makes this phenomenal is how it tells a somewhat non-linear highly intertwined story that wouldn''t really be plausible in any other medium. Combined with the absolutely jaw-dropping plot twists at every turn, this game is sure to keep you entertained throughout, whether it''s hysterical edge-of-your-seat screeching or hearty laug', 'While I''ve heard many good things about the game, and have no doubt they are true, this port has no text speed options and the glacial pace at which it scrolls makes me want to eat a chocolate gun.', 'Very Positive', 94.17, 39.50, 2.35);
INSERT INTO reviews VALUES (21544, 648780, 125, 'HOW IS THIS GAME NOT MORE POPULAR ????', 'i lost', 'Mostly Positive', 79.20, 15.82, 0.85);
INSERT INTO reviews VALUES (21545, 648800, 121210, 'Me and by buddy George went out into the ocean on this little do hicky and we ran out of food, sadly only one of us are here today to tell the tale  (I ate him)', 'Raft is a fun game with a unique and creative playstyle that kept me hooked at first. However, after around 15 hours of gameplay, it started to feel repetitive, leaving me questioning what else there was to explore or achieve. The grindy mechanics also stood out, as tools wore out quickly, batteries drained too fast, and the constant need for food and water became more of a chore than a challenge. While the initial experience is enjoyable, the gameplay loop could use more variety and balance to ', 'Very Positive', 93.87, 26.52, 17.18);
INSERT INTO reviews VALUES (21549, 648890, 182, 'Pretty sure I saw God at one point.', 'Not bad effects, nice randoms, but... Its to flat for me... its ok in 2d but not in Oculus... the figures has no volume... like flats paper cards... Also its not to easy to focuse...\n\n', 'Very Positive', 93.96, 0.97, 0.30);
INSERT INTO reviews VALUES (21565, 649600, 266, 'Best game ever made', 'Every single little aspect of this game is nothing in comparison to the original (free btw) S&S 2. The previous UI is miles better, the gameplay is better, it''s way more straightforward in the original version and it''s just more fun. There is no point at all in wasting your hard earned 8 euros on this stupid stupid dumb game. I hate this game.', 'Mixed', 68.80, 7.85, 1.12);
INSERT INTO reviews VALUES (21568, 649640, 465, 'This is the best cricket game with realistic gameplay thata I recommend everyone to play,\r\nthis game will have less features than cricket 22,24 but it has better gameplay and very realistic physics,\r\nif u are searching for realistic gameplay I would recommend this game.', 'The devs clearly have no interest in this game.', 'Very Positive', 82.37, 70.58, 73.63);
INSERT INTO reviews VALUES (21574, 649790, 105, 'I had originally given this game a ''thumbs down'' and noted that the mouse controls weren''t working. I spent more time clicking, trying to do the most basic functions (open doors, water plants, feed animals, etc.) than playing the actual game.\nFortunately, the developer, Stromsky, replied to my post on the discussion page in record time. \nTurns out I needed to change the setting from mouse and keyboard to keyboard only. The next update should fix the mouse control problem, but in the meantime, I''', 'If you are looking for a Harvest Moon or Stardew Valley type game, this is not it.  Many of the claims by the developers are false at best.  The mini-games are not only boring, but still quite buggy (logs failing to get cut, bobber for fishing disappearing, etc.).  The people are mostly stale and boring.  The "quests" seem to give nothing for completing them.  There seems to be little way to sell goods other than just keeping a wide variety and hoping that the villagers come looking for the righ', 'Mixed', 42.86, 16.05, 1.45);
INSERT INTO reviews VALUES (21580, 649950, 1549, 'Underrated souls-like game, with a wonderful world, lovely music and voice acting, as well as enjoyable combat.\n\nI''ll preface this with I purchased this on Epic first, and have at least triple the play time there. I honestly love this game, and would recommend it to anyone who enjoys a souls-like game, it''s not quite as challenging, or as deep with lore, but it makes up for that with charm, IMO.\n\nThe only real complaint I have about this game is the matchmaking for co-op, whomever your partner i', 'While this game has one of the most stunning art styles I''ve seen in a long time, the gameplay is very poor. I''ve gotten to the 4th area and beaten the second boss, and this game just continually frustrates me. The difficulty is almost entirely sourced from ambushes or ganking. Many attacks are strangely telegraphed, with a really long wind up, then very quick, blocky attacks coming out, with other attacks that will just have a quick windup and huge distance closer. The village progress system i', 'Mixed', 67.85, 41.37, 3.97);
INSERT INTO reviews VALUES (21584, 650000, 1692, 'It''s not as bad as people make it seem, if it''s on sale, buy it. I spent 3-4 hours playing it casually but also aiming for every achievement.\r\n\r\nHow to make game good:\r\nMax graphics\r\nUse VR headset with vr controllers (eg. no xbox controllers)\r\nHave enough space for you to turn around to look (I used Oculus Air Link)\r\nDon''t play all at once, do like 30-45 mins a day it''ll be fun.', 'This game is unplayable on the quest 3 because the controls dont fully map. Avoid.', 'Mixed', 55.32, 4.05, 2.82);
INSERT INTO reviews VALUES (21590, 650220, 416, 'Very fun silly game to play with friends \n\nThermonuclear bombs teched, woe be upon ye', 'The Enhanced Edition is not balanced against AI.  At the Easy level, AI destroyed 2 of my cities in 20 turns, while I was only trying to build up my cities, and haven''t even got one shot off.  Tried against only 1 AI opponent, as well as a full field of AI opponents.  All set to Easy.\n\nAlso, with the graphics set to Max or Minimum, Vsync on or off, etc. (tested everything) you get this really bad graphics artefact that look like TV static across the middle of the solar system.  This is on a top ', 'Very Positive', 85.82, 7.57, 2.98);
INSERT INTO reviews VALUES (21594, 650350, 150, 'do people not get what early accses means people are writting all bad reviews but it is earlly accses what do you expect yes they are bugs that are game braking but its a really good game overall', 'Could have been cool but its totally abandonware', 'Mixed', 50.67, 19.78, 4.42);
INSERT INTO reviews VALUES (21595, 650440, 298, 'Very good tactical game. Story becomes great near the end. Choices affect the end also. It will be hard for those not used to tactical turn based combat like Fantasy General even on easiest. A must play for fantasy story and turn based fans.', 'The hit chances are way too low for this game to be fun.  Nobody plays strategy games because they like to watch their guys miss a lot even on common enemies.', 'Mostly Positive', 70.13, 22.35, 11.27);
INSERT INTO reviews VALUES (21598, 650510, 562, 'Shift to VECTOR CANNON mode.\nAll energy lines connected.\nLanding gear and climbing irons locked.\nInner chamber pressure rising normally.\nLife-ring has started revolving.\n\nReady to fire.', 'Twenty-one minutes was all it took to want a refund. The first minute I opened the game, the sound was messed up -- static, crackling, right from the opening. (There are fixes, apparently, but they don''t work with my Bluetooth speakers.) There''s also no explanation of the keyboard controls. If you''re not playing with a controller, forget it.\n\nDisappointingly lazy. An awful port of a game that deserved better.', 'Mostly Positive', 72.95, 1.55, 0.35);
INSERT INTO reviews VALUES (21602, 650670, 490, 'I gotta be honest, this one is rough. The interface is clunky (especially when it comes to forging), the balance was all over the place, and some of the graphics and audio choices were just mind-boggling. \nBut honestly? I still had a great time. Steam needs more weird games like this. Here''s hoping that the game gets another pass of polishing like a V4 or something. Or at the very least custom character portraits.', 'Played for an hour. This game is steaming garbage. I was promised an "oldschool" "hardcore" experience. What I got was "brain dead UI" and "tedious is the same as difficult, right?" \nWhat do I know about this game?  It has an obtuse interface, no explanation for how anything works or even what things are (Characters have a stat labeled FEL - what the hell is it? FEeLings?), but I sure know the author''s feelings on gender-based biological essentialism, because the only concrete information on the', 'Mixed', 68.78, 30.05, 1.05);
INSERT INTO reviews VALUES (21610, 650760, 160, 'Great game, very pretty, interesting story and characters, just hard enough to be fun rather then irritating. I love it', 'Hit a soft-lock during the tutorial fight, I moved my last surviving character and then my turn should have ended, but didn''t. The English translation was also much rougher than I expected. Refunded.', 'Very Positive', 80.00, 6.40, 0.25);
INSERT INTO reviews VALUES (21617, 650940, 285, 'Great turn based dungeon crawler, graphics are pretty nice compared to many in the ''''traditional rougelikes'''' genre, with a decent number of races, I would prefer more classes (I come from ADOM). There is an infinite dungeon mode that each level enemies get a buff for each level depth it''s quite nice. Campaign maps. Each game played gives an amount of currency which you can spend on perma-buffs for future characters generated.', 'As someone who has already beaten both Dungeon Crawl: Stone Soup and ToME4 that this game takes its mechanics from, I can testify that this is just an inferior game to those that inspired it. Nearly every semi-original idea that this game has over the others does not fit in very well and seems poorly designed. Potions that temporarily raise a certain stat? Why? Have we not grown out of this already? To top it off, I have already encountered a numerous amount of bugs during my 2 hours short gamep', 'Very Positive', 82.81, 65.67, 1.77);
INSERT INTO reviews VALUES (21633, 651490, 155, 'Beautifully crafted game that explores themes of transition, friendship, and the bittersweet nature of moving on. The heartfelt dialogue and relatable characters resonate deeply with anyone who has faced significant life changes.\n\nThe game''s vibrant visuals create a warm atmosphere, while the soothing soundtrack enhances the emotional experience. However, the character movement can feel a bit unpolished, as they sometimes continue walking when obstructed by game objects, disrupting the flow of e', 'This Game just wasn''t for me.\nI''m someone that plays a lot of Visual Novels, but this one just couldn''t catch me. After the first half of the Game I didn''t even care anymore because the dialoug was as flat as the screen I played it on. I think the problem is, I don''t care for either Bo or Ao since all we see is that one evening befor they move out. There maybe people who can relate to them regardless but I wasn''t one of them.\nStill the game isn''t bad and just because I couldn''t enjoy it doesn''t ', 'Mixed', 63.87, 1.25, 2.22);
INSERT INTO reviews VALUES (21634, 651500, 121, 'An incredibly touching story of... being human. Set in WWII, in Poland, it tells a story of two kids under Nazi rule, just after the invasion. It is beautifully camouflaged as something else, but with a clear intention of telling a story in a way that reminded me of "La vita è bella" from 1997 (an amazing Italian film that everyone should see in their life!).\n\n10/10', 'the game is cute, mainly with puzzle elements not too hard.\nobviously means for kid.\n\ni don''t recommend this though, because the story telling about a kid stealing stuff!\nif u making a product targeting at kid, use good and inspired element in the story, stealing is not!\n', 'Very Positive', 90.91, 9.78, 1.28);
INSERT INTO reviews VALUES (21642, 651660, 463, 'Lighthearted parody of mostly Star Trek, which is fun. I bounced off of it getting a bit grindy, but if you like grinding JRPG style battles, with a lightweight base building component, this is a fun, silly one for you. This is apparently the less grindy updated version of the game. The original is under "Classic Edition" and I give it thumbs down.', 'The idea of Halcyon 6 is strong: XCOM in a Star Trek-like universe! But the execution is lacking. XCOM makes you feel like every decision matters, as you face a terrifying new challenge with every new type of alien you encounter. Halcyon 6 offers tons of choices that are utterly inconsequential, and many game elements feel largely irrelevant. Diplomacy, for instance, feels like it should matter but doesn''t. You get some rewards, sure, but you already have plenty of everything, so why does it mat', 'Mostly Positive', 79.70, 33.18, 33.75);
INSERT INTO reviews VALUES (21643, 651670, 1521, 'The fact that I keep coming back to trying another, harder run every few months is a testament how much I like how Star Renegades plays, looks and sounds. Finishing a run is insanely fulfilling. It''s just really hard to justify investing time because the formula barely changes but runs take 4–6 hours and could end after the second bad decision.\n\nDialog is astonishingly cringe sadly. I hope no developer ever believes that it''s a good idea to put this marvel-ass-shit in a game again.', 'I gave it a few tries, but it''s really not for me. Pardon my rudeness but the writing is just very bad, and it prevents me from enjoying an otherwise perfectly okay game. The battle system is novel and interesting, the art is good (and sometimes great even), the music is fine, but the dialog is fan fiction levels of bad. I''m talking "aaaannd he''s right behind me, isn''t he? / Erm, so that''s a thing now I guess!" levels of bad. Maybe their next game will be a bit better. If you can look past the b', 'Very Positive', 81.66, 47.02, 2.20);
INSERT INTO reviews VALUES (21664, 652190, 184, 'This game is a massive improvement from the original game. There are more evil dolls and each level is different from the last. It is also a lot scarier than the original, so definitely give this one a try.', 'This is shit lol', 'Very Positive', 85.87, 6.43, 1.08);
INSERT INTO reviews VALUES (21675, 652410, 419, 'Kings Field: New Vegas', 'Constant crashing\nCan''t launch through Steam\nTexture glitching\n\nedit; Dev decided to mock me when these personal issues are everywhere in forums for months, useless.', 'Overwhelmingly Positive', 96.18, 15.70, 2.75);
INSERT INTO reviews VALUES (21703, 652950, 100, 'A wonderful and charming experience that will end up teaching you the importance of eating your veggies :'')', 'I had nothing but problems trying to play this game so I gave up on it. I''ve played many point&click games but it''s been a while since I found one this annoying in terms of technical issues. Once you start a new game, I could not find any way to access the menu again to quit (nor save progress). Since there''s no game menu available, I was forced to quit by killing the process/task - but this game does not like to be minimized so this always resulted in crashing my machine temporarily along with ', 'Overwhelmingly Positive', 97.00, 2.92, 0.18);
INSERT INTO reviews VALUES (21715, 653530, 16051, 'I’ve significantly increased my consumption of questionable substances in the hope of inducing severe memory loss. This would let me experience the game again as if it were completely new.', 'DO NOT PLAY THIS GAME IF YOU ARE DEAF, HARD-OF-HEARING, OR HAVE TROUBLE DIFFERENTIATING ACCENTS.\n\nPortions of the game require you to distinguish speakers using their accents. These accents are not marked or noted in the subtitles in any way.', 'Overwhelmingly Positive', 96.61, 17.20, 7.13);
INSERT INTO reviews VALUES (21724, 653930, 991, 'the game is good sad it was abandond', 'TLDR: A game I love is now abandonware.\n\n I love this game with all my heart and soul. BUT Lumbernauts (the devs of the game) left it to die and for no appatrnt reason so its just the moders left and so it feels like there is no community. I would give it a 10/10 but Lumbernauts just fucked off so I cant fairly rate it. \n\nI hope one day Lumbernauts get back to the game and update it. The game was last update well in a from of DLC BACK IN 2019! Its 2024 as of writing this.\n\nLumbernauts please! we', 'Very Positive', 92.43, 113.43, 130.10);
INSERT INTO reviews VALUES (21725, 653940, 107, 'Time I got around to reviewing this game. It''s a mostly text based procedural generation survival sim with horror elements. Sort of. It''s also got a very ''meh'' relationship system which just isn''t all that interesting and I don''t recommend getting the game if you''re looking for that. The best parts about the game are it''s management, survival, and horror elements. That and the ability to add custom content which is fairly robust.\n\nAs you can see in the screenshots and whatnot, the game has sever', 'Just utterly unoptimized, whole computer locks up while it tries to figure out how to launch', 'Mostly Positive', 71.96, 36.72, 0.13);
INSERT INTO reviews VALUES (21739, 654220, 108, 'This is a very good representation of the board game experience. My only gripe is that I wish there was a true top-down view, but that''s forgivable as the experience here is great!', 'why the FUCK does it zoom when you right click to move the camera??? legit infuriating when im trying to play. Other than that its a really good digitization of the board game, with added maps. Just fix the fucking right click zooming in problem its unplayable with that.', 'Mostly Positive', 79.63, 63.05, 0.08);
INSERT INTO reviews VALUES (21748, 654440, 104, 'It''s one of those puzzle games where you navigate to the exit while stepping on each square the correct number of times to unlock it. Similar mechanics can be found in RPG mini-puzzles and other puzzle games.\r\n\r\nWith 50 levels, the 2€ price tag seems fair. The difficulty starts off manageable, though it might ramp up later. Just a heads-up—there’s no keyboard support, so you''ll be clicking your way through the game.', 'Perhaps this is because Ive been playing the likes of the absolutely fantastic Hade, but I cant really recommend this. \nWith the exception of a couple of the last levels the design is trivial to solve, there isnt much in the way of mechanics, the music is... quite bad. (Though in its plinky plonky way it did make me chuckle sometimes.) the controls are just odd for a desktop computer, I completed it in under an hour while putting very little thought or attention in. It reminded me of the game pr', 'Very Positive', 80.77, 2.93, 0.97);
INSERT INTO reviews VALUES (21753, 654550, 199, 'It''s like Ron Gilbert and David Lynch had a son with a lot of love and enthusiasm, but now they are going through a marital crisis, and the kid is entering adolescence, little by little losing his way.\nA lot of teenage angst, surrealism colliding with hyperrealism and an atmospheric night like no other, a soundtrack like cherry on top, so memorable that I played it in 2021 in the middle of the pandemic and I still remember it perfectly, good and consistent pixel art for the story it aims to tell', 'This was creepy with no payoff and not very interesting to play.', 'Very Positive', 90.45, 2.15, 1.35);
INSERT INTO reviews VALUES (21772, 654850, 171, 'Do you like zombies?\nDo you like shooting zombies?\nDo you like shooting zombies with your friends?\nIf you said yes to all of the above, you may find this game slightly more enjoyable than a stale biscuit.', 'i feel like i''ve wasted several years of my life for playing this game \nbuy  m&m with that 1 dollar', 'Mostly Positive', 73.10, 1.77, 0.52);
INSERT INTO reviews VALUES (21774, 654880, 4546, 'your wife died and you moved to a new town what would u do the first thing? find all the gays in town (like all of them are) and fuck them one by one. 10/10 would do it again', 'The artwork is decent, but the writing is terrible. The dialogue feels unnatural, and the characters are bland and uninteresting.', 'Very Positive', 92.04, 7.03, 0.92);
INSERT INTO reviews VALUES (21775, 654890, 1828, 'I recommend this game along with its DLC Whiskey & Lemons. Lets talk about the positives. This game has a massive map spanning from Texas to Maine just about which for some could be a positive or negative as it could be overwhelming. This is a large game and by that standard yes the whole game could be for players who are newer to Grand Strategy games. You have ultimate control over EVERYTHING. From building up your navy to naming the individual regiments within the game. For any total war playe', 'Garbage dev team.  Release game in semi-finished state to avoid accusations of rug pulling, then utterly abandon the game.  Brilliant!', 'Mostly Positive', 75.98, 1085.80, 221.18);
INSERT INTO reviews VALUES (21776, 654900, 333, 'Great game, various minimalistic puzzles that are not that hard to solve, the difficulty increases with the levels passed, but still managable to win it. Many achievements as well for you to add to your achievement count. I recommend this game, 10/10!', 'I can only recommend this for children. Every level can be solved by backtracking from the finishline, and 70% you can just try. No real logic required.\n\nThe music is 3 seconds long, and its looping. The dev called it "Pleasant".\n\n3/10', 'Very Positive', 89.19, 2.43, 0.35);
INSERT INTO reviews VALUES (21783, 654990, 722, 'Dude Simulator\n\nHas a total of 5 trading cards.', 'Asset Flip Simulator', 'Mixed', 57.20, 0.52, 2.72);
INSERT INTO reviews VALUES (21789, 655100, 239, 'Yes for achievements hunters!', 'In itself a fun simple puzzler for the most part, with a few moments of frustrating wonky physics.\r\nThere''s a technical issue; Upon launching the game thousands of Achievements activate simultaneously\r\nwhich completely crashed Steam. There''s simply no need to have that many Achievements spawn on launch in that way.', 'Very Positive', 80.33, 6.95, 7.45);
INSERT INTO reviews VALUES (21799, 655290, 433, 'Excellent advanced survival game with great progression and a large mix of items and builds.  It''s a true survival game, decisions about exploration and resources planning are key.  You can''t just expect to move through predetermined tiers (or levels) and just survive without thinking and planning.  The mechanics are not too hard to understand, but they do take patients and some ingenuity (just like a real survival situation).  It originally had some glitches with rafts flying around, but most o', 'Utter Garbage and typical EA lack of development.  I bought it years ago because I wanted to support the developer but 6 years later its still a hot mess.  I waited all this time to leave a review to see where it goes and if you want to build a house, a small raft, and never leave your starting cluster great.  The bugs you encounter are only frustrating.  If  you want to leave  your cluster get ready for a bug filled rage quit.  \n\nIt''s amazing to me with all the bug fixes posted by the dev it ha', 'Mixed', 69.75, 122.98, 154.83);
INSERT INTO reviews VALUES (21808, 655480, 237, 'Ask yourself, what if Terraforming Mars was simple, relaxing and entertaining? Don''t worry about it, Solar Settlers answered the question for you. Synergistic abilities, clever resource management, calculable risk, with the random card draw and starting planet adding the chef''s kiss of randomness for you. You should play the game, support small devs making good things.', 'esperaba más fondo. Es el mismo tablero una y otra vez, con pequeñas diferencias en cartas. Una raza distinta es solo una única habilidad distinta, me suena muy repetitivo y en número de horas esperaba más replayabilidad.', 'Overwhelmingly Positive', 96.20, 16.75, 16.85);
INSERT INTO reviews VALUES (21810, 655500, 19346, 'You''ll hate it at first,  and then youll hate it some more,  then you can ride slowly around the track and then hate it some more when you try to get some air.  Youll hate it some more when trying to rail berms, and then youll hate it some more when you cant learn any of this stuff in one day.  10/10 would bang\n\nupdate after 69 hours.  still wood bang.', 'Could''ve done with some kind of tutorial, guide, in-game help, literally anything at all, instead got zero answers and a fourm site that seems to have been recently taken over by dating bots. Shame, too, ''cause the game seems really cool. Also, why can''t I lean forward/backward on controller without having to re-bind something?', 'Very Positive', 94.59, 98.22, 0.67);
INSERT INTO reviews VALUES (21825, 655730, 265, 'Quite a fun, creative and diverse action-adventure game, definitely worth a try. Hugs for The Tavern Limbo Gang. ', 'I''m sure this was some kind of cathartic experience for the dev(s) but boy does this game think it has it all figured out and sniffs its own farts. The gameplay (when you actually get to it) is tight and VERY satisfying, but half the game is trying to be deep with shallow ignorant thought that masquerades as complex wisdom. It even tries to judge you at the end which is ironic. Btw, it is not even close to accurate. Gameplay wise, it is fun but not worth the slog of the rest. The last chunk drag', 'Very Positive', 83.40, 2.63, 2.25);
INSERT INTO reviews VALUES (21829, 655770, 316, 'I thought I could fix her.\n\nShe thought she could fix me.\n\nIn the end, we fixed each other.', 'I think this game had so much potential, but fatal writing flaws turn it into a cliche yandere VN. \n\nThe premise of playing as someone suffering from mental issues and dealing with a stalker could become something really interesting, but it falls flat. The plot about the medication drags it down and is overall extremely unnecessary. A story about two people who feed off of each other''s instability and desperation would be so nuanced and interesting but the author barely scratches the surface. In', 'Overwhelmingly Positive', 97.15, 5.58, 1.25);
INSERT INTO reviews VALUES (21830, 655780, 257, 'Fabulous visuals, odd storyline. Interesting way to chain together resource gathering centres.', 'Sightseer was an attempt by Tasharen Entertainment at expanding on the formula that made Windward great, with a greater focus on exploration and base building. Sadly, the final product fell far short and was abandoned by the developer after its sales failed to reach expectations. At least its free for users now.\n\nI was a long-time fan of Tasharen Entertainment, paying to be a backer of Windward Horizon and putting in hundreds of hours of feedback and playtesting. Unfortunately I can no longer su', 'Mixed', 64.59, 676.47, 41.97);
INSERT INTO reviews VALUES (21831, 655790, 255, 'this game changed my entire outlook on life and is a masterpiece everyone should play it made me cry, laugh and everything in between buy this NOW!!11!11', 'Fly Simulator – A Swarm of Disappointment 🦟💥\n\nFly Simulator had me excited at first, thinking it would be a quirky and fun twist on simulation games. Instead, it feels like a chaotic mess with no real purpose or direction. The premise of fighting off flies as a waiter might sound interesting, but it quickly becomes tedious. You’re stuck swatting away the same relentless bugs over and over, with no real strategy or variety to keep things fresh. 🪰\n\nThe controls are clunky, the gameplay lacks depth', 'Mixed', 67.84, 0.63, 0.25);
INSERT INTO reviews VALUES (21847, 656200, 138, 'yes the game is abandoned and super chinese, but if you''re looking for an esports GM game this is the best option and it''s not close.', 'Set my jungler to gank early and he sets up a campfire in the jungle, then toasts marshmallows the whole game.', 'Mixed', 58.70, 55.83, 0.17);
INSERT INTO reviews VALUES (21850, 656240, 1634, 'Great Game would be great if devs would fix some of the problems or offer this to someone who could bring it back to life single play works good its the co-op with a server that has the problems here is hoping they will fix or sell to someone who can bring it back.', 'This is the game that made me start looking at Dev before I buy. This is the second one of their games they have stopped working on... Too bad cause this has a lot of potential.', 'Mixed', 48.16, 37.68, 1.48);
INSERT INTO reviews VALUES (21857, 656350, 4137, 'Not a fan of roguelikes, and never have been. Something about spending hours getting to a point, only for it to all be lost. But this game man, I love this game. I don''t know what about it makes it so appealing but it IS appealing. It was one of the first games I got on my computer, then I bought it again on steam. For four years, I''ve had this game, and it still hasn''t gotten old. Recently 100% it, not because I was close, but because it was just fun enough to keep going. Can''t recommend this e', 'Undermine has a mechanic that ruins all potential fun for me: Pilfers. Every time gold drops, little creatures immediately show up and steal it, so the player has to frantically compete for loot. No way to turn it off.\n\nThe easiest way to make me hate your game is showing me a reward and then taking it away.', 'Very Positive', 90.86, 311.92, 0.93);
INSERT INTO reviews VALUES (21874, 656600, 156, 'modern day piano practice', 'If I could, I’d give this a mixed review, but since that’s not an option, I have to rate it negatively. The game has some fun and interesting mechanics, but the frustration and poor design choices outweigh the positives.\r\n\r\nFirst, for a rhythm game, the notes are neither synced to the music nor consistent in their timing across songs. In some modes, like numbers, alphabet, and words, this isn''t a big issue. However, in modes that rely on precise timing—such as space, mouse, and arrow key mode—it', 'Mixed', 61.54, 3.80, 3.03);
INSERT INTO reviews VALUES (21875, 656610, 163, 'Nobody will read my review so I will eat 1 Tablespoon of Spicy Ketchup for every like this gets.\n', 'Everything is the same as in other games from the developer, only here with animals, everything is also extremely bad.', 'Mixed', 55.83, 4.30, 4.50);
INSERT INTO reviews VALUES (21882, 656700, 266, 'hot anal rico action', 'Servers Offline !!! \nNot working to play: Daily Missions, 2 Player Missions and Co-op\n!!! 100% on Achievements not possible !!!', 'Mixed', 63.16, 8.85, 0.52);
INSERT INTO reviews VALUES (21894, 656970, 162, 'A wonderful puzzle platformer with unique mechanics in every level. Easy to control, but WAY tougher than it looks. If you want a cute challenge I highly recommend this!', 'Follow my Curator page, Fruit N Doggie Reviews, so you can be updated whenever I post a new review.\nOverall Rating - Mediocre ★★★☆☆\n\nFirst Impressions\nFor those who know me, I can be a sucker for cute things, so it''s not that shocking to find MagiCat (MC) in my library. At first, I was put off by some of the choices with how this game is designed. However, as I explored later worlds, unlocking more of the content, I started understanding important factors that weren''t well explained earlier. I b', 'Very Positive', 92.59, 15.25, 4.97);
INSERT INTO reviews VALUES (21895, 657000, 122, 'fun and very unique take of rouge-like genre blend with metroidvania, you should try it', 'I don''t have anything constructive to say. \nI didn''t find the talents/perks to be interesting and the combat was unintuitive.', 'Very Positive', 90.98, 1.52, 1.70);
INSERT INTO reviews VALUES (21908, 657200, 9935, 'the controls in this game tempt me to use my real hand to shoot the real me with a real bullet', 'It''s fun for about 30 minutes at a time with friends so yk maybe that''s what ur lookin for <3', 'Very Positive', 83.55, 10.22, 1.92);
INSERT INTO reviews VALUES (21911, 657240, 966, 'this game is so frickin old school and i loooooooovvvvvvvvvveeeeeeeeee it', 'promised the workshop in 2017', 'Very Positive', 93.89, 9.23, 6.93);
INSERT INTO reviews VALUES (21914, 657280, 179, 'As someone with absolutely no other experience with music making, this software was really nice and approachable. I first used Rytmik Ultimate on the Nintendo 3DS of all things, so transitioning to Studio on PC was a nice upgrade. Definitely recommend.', 'User interface doesn''t make any sense. Its a pain in the ass to wrap your head around just to figure out how everything works. Plus, it''s been in early access for years and it looks like the developers have abandoned it. There''s an endless number of other programs out there that are free, easier to use, and still being updated.', 'Very Positive', 86.03, 265.75, 0.28);
INSERT INTO reviews VALUES (21929, 657630, 297, 'This game fixed my broken marriage.', 'one of the fidget spinners is a swastika\ni will be refunding this game now.', 'Very Positive', 83.84, 11.20, 0.08);
INSERT INTO reviews VALUES (21931, 657690, 421, 'The Caribbean Sail is a charming, retro styled sailing adventure that I’ve grown fond of. It’s simple but hits the right spot when I’m in the mood for something lighthearted and Silly. There’s a surprising amount of humor and dark twists thrown in. The random events at sea keep me wondering what''s next? and I like that I can sail with or against the wind, never quite knowing what’ll happen next. The unpredictability of my voyages keeps me coming back. It’s a small game, but it nails the feeling ', 'oregon trail was way less tedious than this, this game is unfun sadly... its not even low on content, its just an awful mount of grind to get the content which is planly boring and addin little to no mechanics to it. Unbalanced and grind. it is overpriced imho.', 'Very Positive', 94.77, 70.93, 6.68);
INSERT INTO reviews VALUES (21935, 657990, 113, 'I 100% reccomend this to other people, i know that its a 5 dollar game but its possibly the BEST 5 dollar game ive ever played! From my expieriences i could not get into multiplayer BUT it does have a really epic single player experience that i would reccomend to everyone. it only takes about maybe an hour or two depending on your skill level to master the game and know how to fully or mostly play the game. onto the content. its a zombie shooter game thats like minecraft and DayZ or dont bite me', 'yeah game is abandoned... no servers cant get loot in singleplayer, i want my money back', 'Mixed', 54.87, 4.93, 0.15);
INSERT INTO reviews VALUES (21941, 658150, 123, 'I got a booner throughout this game\n10/10', 'TERRIBLE GAME never play this astounding garbage that makes a unbeatable final boss look like a painful train wreck with a bonefied mushroom sticked up their stounding butts', 'Overwhelmingly Positive', 95.93, 6.25, 29.35);
INSERT INTO reviews VALUES (21942, 658160, 167, 'I have tried and still play many clicker/idle/incremental games, but there are a limited few that will grab your attention and have come back to play day after day like ClickRaid does.\n  \nThe dev is constantly working on new material, balancing old material and fixing bugs.\nEvery month has an optional new season that only last a few weeks, that contains different mechanics than the non-season.  Every earned in the season then gets transferred to the non-season much like Blizzards Diablo 3 season', 'Look at the amount of time/energy I have invested in this game...\n\nCommunity is almost dead.  The original developer has moved on to developing ClickRaid2.  New developer has taken over and has decided that instead of fixing issues with the game that is best to totally change the gameplay mechanics.  The newly proposed gameplay mechanics... Everyones progress will be reset monthly.  That months progress will be added to a cumlative leaderboard that adds no benefit to your current run (therefore,', 'Very Positive', 80.24, 3019.73, 3479.63);
INSERT INTO reviews VALUES (21962, 658550, 296, 'If you''re a fan of puzzles and achievements, you''ve come to the right place !\n\n*** All ZUP Games have cool Puzzles + Trading Cards + a lot of working achievments ***\n\n+ Successes are letters in different colors that you can ideally use for profile design\n\n--> If you have the option, buy them all in a bundle to save money. You won''t regret it', 'Don''t play this game, I don''t recommend it', 'Very Positive', 93.92, 5.62, 12.47);
INSERT INTO reviews VALUES (21963, 658560, 525, 'I like to play chronologically, so this is the 7th of the series that I''ve played and so far the one I like the most. Or maybe I''m just getting used to it. I found the others sometimes too tedious but this time I really had fun. As always it has lots of short levels, sometimes straightforward and easy, sometimes you need to experiment a bit. \n\nI''m not fond of the achievement spamming after each level (one would have been enough for me, the pop-ups annoyed me quite a bit) but otherwise this is a ', 'ᅠ', 'Very Positive', 94.10, 1.57, 5.10);
INSERT INTO reviews VALUES (21964, 658570, 506, 'FIVE BLOODY STARS!\n\nI downloaded this and thought it was only for keyboard - WHOA! This is one of the best drift games ever... but there is no one online to play so you only get to drive with ghosts.... the DLCs become essential for the fun to continue. \n\nI HIGHLY recommend this game, it was a sleeper but once I configured my Logitech g920, this game sang into my heart. And listen to what a $60,000 exhaust sounds like as opposed to a $30,000 one. It''s fascinating, watch your money from the start', 'Shit cash-grab that died like its brothers that were re uploaded with different names. Don''t buy any of this guys games anymore.', 'Mostly Positive', 77.08, 6.30, 26.40);
INSERT INTO reviews VALUES (21965, 658590, 167, 'She and the Light Bearer is a beautiful adventure game with his cutes designs and his relaxing ambiant. I recommend it!!! ❤️', 'The art in 𝑺𝒉𝒆 𝒂𝒏𝒅 𝒕𝒉𝒆 𝑳𝒊𝒈𝒉𝒕 𝑩𝒆𝒂𝒓𝒆𝒓 is absolutely gorgeous – it’s like stepping into a beautifully illustrated storybook. Sadly, that’s where the magic ends.\n\nThe gameplay is 𝗽𝗮𝗶𝗻𝗳𝘂𝗹𝗹𝘆 𝘀𝗹𝗼𝘄, especially the movement animations, which take forever and make the whole experience feel like a drag. It’s not that the game is too easy, it’s just... boring. Everything feels vague and unengaging, and I honestly couldn’t connect with it at all. ˙◠˙\n\nOh, and the voices? I had to mute it after five seconds b', 'Very Positive', 82.63, 34.00, 2.30);
INSERT INTO reviews VALUES (21966, 658600, 229, '52 HOURS OF COMPLETE EDGE', 'game''s broken. lawnmower won''t move.', 'Very Positive', 87.34, 292.73, 0.53);
INSERT INTO reviews VALUES (21968, 658620, 896, 'short yuri vn :3\nnot sure why it''s so expensive when it''s only about an hour long, but otherwise it''s pretty fun with a great art style!', 'hey man, that scene where the girl get''s is fvćked like an animal by the janitors rabid dog was necessary for the plot!\noh oh! and the chapter that consist entirely of rápé and other sexual assault scenes, because apparently, I, as a reader, am too stupid to understand something that is explained to me in words, so instead, the author has to show me it 10 times back to back, as if I was rétárded and didn''t know what sexual assault or physical abuse is.\noh oh! and don''t forget to read the entiret', 'Very Positive', 90.96, 1.05, 48.05);
INSERT INTO reviews VALUES (21972, 658700, 169, 'i almost refunded this game 3 times, first my controller wouldnt work, found had to map them manually in game setting, then my car was sliding around like a lunatic, found i had to buy a better car and switch the car settings for the right ground surface, then the graphics looked awful foggy and washed out, found shader reshade fixed that. 3 hours in i ended up loving it, great career mode, great course selection and tracks, is like a rally version of GRID.', 'I bought this because it says it supports X-Box Controller. It doesn''t! \nOf course, with Steam there is no way to get a refund.', 'Mostly Positive', 73.37, 7.60, 0.28);
INSERT INTO reviews VALUES (21976, 658780, 105, 'Super fun little platformer! There are definitely parts that feel too cramped and frustrating to be enjoyed given that dying can sometimes send you back really far. Fun though.', 'I like Nitrome and the game looks charming. However, I feel like Bomb Chicken can''t decide if it wants to be a slow puzzle platformer or a precision platfromer like Meat Boy or Celeste. This results in a game which is somewhat of a frustrating mess. It feels like how the original Rayman was frustrating because the developers played the levels so many times it felt too easy for them so they went overboard with artificial difficulty. \n', 'Very Positive', 84.76, 3.75, 2.85);
INSERT INTO reviews VALUES (21981, 658850, 2041, 'Underrated, fun game where you figure out what people you''re watching are doing and decide what to do with said information. \r\n\r\nThe only truly bad mechanic is missing people while you''re out. You can go days without getting a package just because you weren''t in the apartment at the right time. And when you do stay in the apartment to wait for the package, there''s a huge time gap of when the mailman can come, messing up your schedule and potentially ruining your run for the day.\r\n\r\nIf you can ge', 'The first few games were great, but when you start getting the same stories over and over, and since you can only get a few variations in some of them, it gets repetitive really easy. I will say that the humor is good and that the resource management between not starving and stalking random people was fun. The main problem is the fact that missing events is quite common and just watching the cams expecting for important things to happen can be quite boring.', 'Very Positive', 91.82, 12.10, 11.77);
INSERT INTO reviews VALUES (21984, 658890, 400, 'this game is really good and not gay', 'Seems like the type of game I wanted to play. That''s why I bought it. Too bad every time I try to play it, I keep getting errors and a black screen. Please fix this game!! It''s so disappointing when you see talented developers make a good game, but forget to quality check. I can''t even refund it because I took to long to try it out after buying.', 'Very Positive', 91.25, 43.02, 0.50);
INSERT INTO reviews VALUES (21986, 658980, 363, 'I have to apologize to the developers, I first started this game at the end of a bad week after losing my close cousin and my pop. I reviewed the game unfairly and said some mean things I didn''t mean.  So I want to humbly apologize first off. Secondly I want to give an honest review of the game.  Sure Valnir Rok has its bugs and random crashes but beyond that what is trying to be achieved here is something quite epic. As updates roll out the game targets in on what mmorpgs used to stand for... t', 'GAMES BEEN DEAD SINCE 2017 maybe 18 like why is it still up? why did steam not take this game down? its a cash grab they are not even working on it. in fact since its early access you should give us all are money back. Since they never planned on finishing this game.', 'Mixed', 46.01, 60.35, 48.15);
INSERT INTO reviews VALUES (21999, 659190, 159, 'I really wish there was a "maybe" option for recommending this game. \n\nBasically, I played all the puzzles, and really liked them. So if you enjoy those types of logic puzzles, where you get a grid with some numbers and then you have to click on a bunch of squares depending on those numbers? Great, you''ll have fun. I think the difficulty curve is pretty good too. \n\nBut the reason I land on "maybe" is because I read a few of the logs and completely tapped out on the story because I just wanted to', 'It''s really bad. I mean.. really.  \n\nYou just keep clicking random buttons in repetitive, sudoku-like mini games. Of course the solutions are not actually random, but the easiest way to solve them is by just starting somewhere and then see where it takes you - or just restart if necessary.\n\nYou''re "rewarded" with countless bits of chat logs, consisting of terrible dialogue (or more like monologue) in terrible English, which must have been written by terribly horny teenagers in summer camp. Horny', 'Mostly Positive', 72.96, 7.78, 2.03);
INSERT INTO reviews VALUES (22006, 659480, 138, 'Very nice puzzle game, many different interesting puzzles and all of them not too easy, Nice that game don''t advice you too much. This type of games need to play without guides because with guide you are ruining your joy and game is not worth money. Without guides length is nice. \nGame is described "Horror" but i don''t feel horror 98% of the time so don''t wait scary game or any spooky things.\nI Got this discounted so i give 7/10. If you like brain/puzzle/escape room style of games worth a try.', 'I dont like it I found it boring.', 'Mostly Positive', 78.26, 5.23, 1.80);
INSERT INTO reviews VALUES (22010, 659540, 1669, 'This is Caves of Qud if you''re too dumb to play Caves of Qud (I''m too dumb to play Caves of Qud)\n\nAn ASCII game that doesn''t require a degree in theoretical physics to play /10', 'The information I saw on this game lead me to believe it was going to be a complex simulator that would generate interesting worlds to explore and conquer.\nIt''s not exactly what I was expecting. It''s a pretty simple game with some funny writing, but it''s not the immersive world and politics simulator I was looking for.', 'Overwhelmingly Positive', 96.11, 9.88, 0.87);
INSERT INTO reviews VALUES (22032, 660160, 502, 'This game may feel clunky at first, but it is a better portrayal of ancient tactical combat than any other game I''ve encountered. Formations matter. Classic strategies such as controlled withdrawal on one oblique while pushing heavily on the opposite flank works well. The quality of troops matters tremendously. The impact of ground quality on combat (especially phalanxes) was gratifying. The degree to which you lose control of your army as it engages is also realistic. I haven''t seen any game qu', 'I want to like this game so much because I am a big fan of historical strategy games but I can''t because I don''t understand why on earth range units (archers/javelins/slingers) cannot fire at enemy units that are in melee, I would understand if it''s only from the front but it prevents you to fire at enemies even from their rear, making all range units useless or not worth to bring, while historically they were able to (and they did) fire at enemies engaged in melee', 'Very Positive', 87.25, 160.48, 5.15);
INSERT INTO reviews VALUES (22055, 660920, 174, 'Actually I would recommend the game but ONLY at a high discount and with a friend by your side \nYes, it''s abandoned but I think there''s fun to be had here, sadly only for a little while', 'imagine getting a refund for a game thats $1.50', 'Mixed', 54.60, 36.88, 0.13);
INSERT INTO reviews VALUES (22079, 661290, 364, 'Wild stunts, crazy speed, and pure chaos!\r\nFun core, but it’s like a Lambo with square wheels - just needs a revamp and this could be gold.', 'I can''t describe how bad this game is.. 🤢 💩', 'Mostly Positive', 79.95, 12.63, 0.28);
INSERT INTO reviews VALUES (22087, 661430, 220, 'Haven''t finished yet but so far really solid. The game is very well made and the general concept is pretty solid as well. If you like puzzle games I would recommend. 7/10', 'Way too easy to complete. All 80 levels done in just as many minutes...\nSome additional annoyances:\n- The music, while pleasingly ambient at first, does get tiresome on its repeat rather quickly. I turned it off about halfway in.\n- Every level has an impatient starting square that starts pinging incessantly while you examine the puzzle to see what path to take. Beyond distracting it''s downright aggravating; the only real way around it is to click and hold the starting position to make the sound ', 'Very Positive', 87.27, 1.35, 1.33);
INSERT INTO reviews VALUES (22108, 661790, 1195, 'Playing this gem again around Halloween 3 years later, it''s still a nice little horror game. Not recommended for zoomers with ADHD, this is a slow-paced game.', 'The worst thing about this game is that you''re forced to play from the perspective of a 3ft tall midget', 'Very Positive', 89.29, 4.82, 2.83);
INSERT INTO reviews VALUES (22112, 661920, 142, 'If this game is not working on your computer it is likely due to having an Intel 11th Gen CPU installed. You can fix this by including a command in the launch options of the game when you right click it and press properties in your library. The command is - cmd /c "set OPENSSL_ia32cap=:~0x20000000 && %command%"', 'This game will no longer open for me, and many others. It was interesting while it worked, so it''s disappointing to see it not maintained anymore.', 'Mixed', 64.08, 5.70, 2.97);
INSERT INTO reviews VALUES (22113, 661940, 162, 'You''d think a bunch of different people controlling the same robot basketball player would be a clusterfuck, but it somehow works. Very funny game, especially for its price, though you will need friends to play with (up to 10 players local/online)', 'wtf is this game', 'Very Positive', 93.83, 2.40, 0.25);
INSERT INTO reviews VALUES (22117, 661990, 154, 'This is a better DBZ game than any actual DBZ-branded game!\n\nBuy it now, and if you already have it, buy for someone else!', 'i''m sure there''s probably a good fighter hiding behind this loli hentai but i''m not taking any chances\n\nbtw i did my research and every single character is under 18', 'Very Positive', 86.36, 0.57, 4.07);
INSERT INTO reviews VALUES (22123, 662210, 216, 'Has some funny, crass humor that i found refreshing in a JRPG. for a couple dollars, if you want something different, enjoy metal and some dumb humor and don''t expect a masterpiece JRPG, you''ll probably like this game.', 'So here''s the deal; if you like weed, dick jokes, and metal references this game is probably a fine way to kill some time. It''s not expensive and the graphics are decent.\n\nHOWEVER, I picked this game up thinking it would be something of substance, given the "very positive" reviews on Steam and the six hour playtime. Not so. For me, that playtime works against the central conceit of the game being a goofy collection of funny lines. If it was only an hour or two long I could see myself playing thr', 'Overwhelmingly Positive', 96.30, 4.25, 0.60);
INSERT INTO reviews VALUES (22137, 662540, 107, 'I''ve played this a lot from itch.io. I originally got the game with a big bundle. Reviewing here because it''s awesome! If you like traditional roguelikes, this is a very fun and compact little game. The starting species/class combos allow for a lot of variation on somewhat simple gameplay. It''s just plain satisfying, though, with nice little sfx and small animations. It doesn''t have a ton of tracks but the music is pretty good. There''s enough strategy in using your tools that you do have to thin', 'This is a great game. Let me repeat that, this is a great game. Very cool nostalgic art style, great soundtrack, decent, although nonintuitive, mechanics. But I just feel that the amount of content it includes is not worth the current sticker price. I took my first run of the game all the way to the end and the ''special'' ending. It took about 3.5 hours. I''d definitely like more content with this game, I could see it becoming something very special. But in the end, I don''t feel like it was worth ', 'Very Positive', 81.31, 13.90, 3.80);
INSERT INTO reviews VALUES (22156, 662960, 270, 'The above game is an exceptional case because it is a perfect example of how it was possible to kill and completely destroy the potential of a good game that could have become a really good title. Meanwhile, it is something like a "beta version" but even despite this and its numerous errors, you can still feel this unused potential in this game. I really liked the game itself and it hurts me a lot what the creators did with it, or rather what they didn''t do with it, i.e. they didn''t provide it w', 'Game can be fun but the amount of bugs and lags is just so frustrating and kills the experience.\r\n\r\nThe amount of times I needed to restart the game because it simply hangs is such a pain.\r\n\r\nAlso some achievements seem to be locked even tho I have already fulfilled the objective, for example hitting a combo of 100+ or 500+. I am not sure why some people have managed to get this achievement, maybe it wasn''t broken in earlier versions, but I have seen a forum post of more people complaining about', 'Mixed', 64.81, 9.75, 16.28);
INSERT INTO reviews VALUES (22173, 663240, 108, 'o jogo diz que tem tudo que eu possa comer mas não tem a mãe do ravs >:(', 'I was able to completely 100% this game in under an hour. I really don''t have a lot to say about it. For a game that can be beat in 3 minutes I sure had a weird time trying to unlock the achievements. There''s a few funny lines here and there but this BARELY constitutes even being a game. The default setting for "page turning" visuals is a terrible idea and thank God the dev had the sense to toggle to turn that off. This feels like it should have been a webcomic rather than a game, there''s very l', 'Very Positive', 86.11, 1.60, 0.70);
INSERT INTO reviews VALUES (22179, 663390, 335, 'Great game, but the style and interface is like it''s an 80''s game haha', 'REVISED (12/28/2024): Screw this game.  It is a pile of garbage. I have tried adjusting settings and lowering the configuration to make it work better.  It only works better for a few minutes.  And then it gets worse again. \n I am convinced that the game developers must be recording every single mouse click.  It just.... keeps... getting... slower... the... more... that... I... play... the... game... and.... there... is... no... obvious... reason... why.... this... should... be... happening... u', 'Mostly Positive', 79.10, 7.35, 58.70);
INSERT INTO reviews VALUES (22195, 664000, 231, 'For a boot leg colony sim, I was quite pleased with several features from this one. I wish I could take a pawn from rimworld and play it in first person like this game.', 'look i love a good sandbox game or a good dungeon crawler game or a good town builder game. This a blatent cash grab. it is dissapointing and does the minimum with all of those game designs. i love when a game does anything new even its combing two types of games that were well done. but like i said they did the minimum effort.', 'Mostly Positive', 78.35, 10.00, 2.23);
INSERT INTO reviews VALUES (22202, 664090, 153, 'This game really surprised me.  I did not think i would enjoy it.  Another wave shooter and a no locomotion wave shooter at that.  And the first few waves seemed to confirm my misgivings.  But oh my, how the difficulty ramped up and how the variety of enemies increased.  It seems the gates of hell have opened and every manner of demon has descended upon you.  You''re getting attacks from all angles and you''re dodging, blocking, melee-ing, and shooting seemingly one after the other, non-stop actio', 'Melee combat is unsatisfying - therefore all the battles and gameplay as a whole don''t have much point.', 'Mostly Positive', 75.16, 1.47, 0.78);
INSERT INTO reviews VALUES (22208, 664180, 100, 'pro level puzzler gaming', 'This is one of those games that is dependent on the steam workshop to make up for its limited amount of content. While player generated content is an avenue to keep a game alive and interesting, it completely backfires when those players stop making content or they dont make quality enough content for the remaining players to enjoy.', 'Overwhelmingly Positive', 96.00, 1.47, 0.75);
INSERT INTO reviews VALUES (22235, 664750, 315, 'Great game, well thought out and quite deep. Neverhood meets a third person Minecraft. Needs more people repping it.', 'Don''t go in the water', 'Very Positive', 94.60, 12.78, 4.80);
INSERT INTO reviews VALUES (22238, 664830, 841, 'This game is from my childhood when I used to play it on flash game websites such as Friv and Yepi i recomend this game mostly to people who tried the flash versions first because there are like 3 zombotron games in flash format on google: \nZombotron 1 Zombotron 2 and Zombotron the time machine there is also a mobile version but i didnt like the controls. Very nice game!', 'TL;DR: The game is too short for it''s price.\n\nAs a fan of the old Zombotron this game was a blast to play through with great visuals and level design... but there is a major issue. 15$ for only 6-7 hours of total gameplay???? Also, I really don''t get why the developer didnt add a level select menu. Once you finish the game, you cannot go back to get the collectibles you missed, making it not worth the time to go through the entire game again just to get them. HUGE missed opportunity.', 'Very Positive', 88.47, 7.75, 7.03);
INSERT INTO reviews VALUES (22245, 665090, 179, 'Pretty fun little hacky-slashy game from what little I played :]\nI wish there was any kind of way to lock onto enemies like in any other action game\nNot a big fan of how the game throws you into button-mashy enemies immediately, but the combat is solid enough\nI give it a uhhhh 7.5/10\nDefinitely fairly priced at £7, and I''ve barely scratched the surface', 'They stole marie rose.', 'Mixed', 67.04, 0.62, 0.25);
INSERT INTO reviews VALUES (22254, 665300, 1164, 'It''s fun, but lots of people don''t like to see a representation of themselves on the screen while they are lurking.  Be sure to set it to only display avatars for people who are actively chatting.', 'I currently can not recommend this at this time.\nThey plan to add KICK integration. \nA site ran by and the host of many people that have neo-nazi world views.\nRight now the test is in BETA and if it is not implement my review will revert.\n\nEdit:\nCorrection: KICK integration is now apart of the official package of Stream Avatars. So as it stands I will not be changing my review. It is with a heavy heart that I will have to let this software go. I have no ill feelings toward it''s creator. I wish t', 'Overwhelmingly Positive', 95.27, 432.77, 637.87);
INSERT INTO reviews VALUES (22256, 665330, 310, 'People don''t realize the magic of McD''s games. Who am I to explain. I just want the thumbs up.', 'Might be passable for mobile, but this is absolutely unplayable on PC compared to every game in the series before it.  Framerate capped and controls dumbed down to suit mobile.  Should have left the game there and not bothered with a PC port for this version.', 'Very Positive', 87.10, 8.07, 5.35);
INSERT INTO reviews VALUES (22259, 665360, 4904, 'If you are looking to get called the N word 500 times a second this is the game for you. Very fun only been told to kill myself 20 times a day.', 'just a bunch of kids thinking saying the N-word or slurs is funny', 'Mostly Positive', 73.31, 4.12, 0.27);
INSERT INTO reviews VALUES (22260, 665370, 1187, 'Thank goodness this game is still playable.\nMessage to the developer, you made me not do any school work during the flash era, go fuck yourself... with love <3.\n\nWould recommend with love.', 'its trash whenever you grab a item like a knife it spins around if you move your cursor while holding it making impossible to stab where u want to people play ground lets u hold a and d to make stay in place where you want it', 'Very Positive', 94.27, 0.62, 0.17);
INSERT INTO reviews VALUES (22289, 666020, 587, 'Shark titties, enough said.', 'dev abandoned the game after promising new content and cashing out on the indiegogo 4 years ago', 'Very Positive', 87.73, 2.45, 0.85);
INSERT INTO reviews VALUES (22295, 666100, 118, 'So much fun.  Shooting giant advancing fruit with automatic rifles while scanning stuff at the checkout.  What more could you want?', 'Amazingly fun VR game, played on my HTC vive pro and worked great, however cant get it to run on my Pimax. seems to be a issue with the game as FPS is choppy no matter the settings', 'Very Positive', 88.98, 7.43, 5.68);
INSERT INTO reviews VALUES (22298, 666140, 11781, 'Basically, "The Sims" had a baby with "Animal Crossing".\n\nEnough said.\n\n\n9/10 - In the game, your dad leaves you but you inherit his workshop. In reality, my dad just left. No workshop, no nothing...', 'This game was abandoned and the devs did not even bother to finish this and made a second game. Now, they are making a third game and will most likely abandon both. Do not waste your money on these series.', 'Very Positive', 92.05, 236.03, 119.18);
INSERT INTO reviews VALUES (22299, 666150, 2246, 'Best recommended if you want something like JWE2 but actually good.\nOr Planet Zoo but with more game alongside the sandbox.\nPlus Dinos R cool.', 'It''s disappointing that a game in development for so many years doesn''t have any kind of object avoidance. I decided to finally buy it because I heard babies are finally coming this year and I was immediately turned off when I saw my people walking straight through the decor I had placed. Even ZT2 had object avoidance. Regardless I still wanted to see the super realistic dinos/animals the game has and was again disappointed when I saw how the smilodon walked. It looks good otherwise but the back', 'Very Positive', 87.71, 19.32, 0.67);
INSERT INTO reviews VALUES (22309, 666330, 346, 'Inertia is a physics-based platformer that offers a thrilling challenge for fans of fast-paced, precision gameplay. The core mechanics revolve around manipulating gravity, allowing you to pull off exhilarating jumps, glides, and wall slides through a series of increasingly difficult levels. The minimalist design works well, keeping the focus on the tight, responsive controls and the obstacles ahead.\n\nWhile the difficulty ramps up quickly, it never feels unfair—every failure is a learning experie', 'This game is very very bad. The worst part is the movement. It is broken, laggy, and just not well done. The lvl desighn also lacks a lot, and the music is strange. Dont reccomend to buy', 'Very Positive', 81.79, 9.02, 0.87);
INSERT INTO reviews VALUES (22312, 666570, 557, 'Imagine being the sole survivor of a zombie outbreak at the mall only to have God drop a landmine on your head', 'I picked up this game out of nostalgia for the original games. This is not nearly as fun as the older games, and is frankly frustrating. Zombie upgrades are tied to the amount of "zombies" you have, which means summoning zombies takes away from upgrades. Upgrading in general is super slow. The game jumps between being too easy and impossible. Don''t know what the developer was thinking, but almost every mechanic introduced in this game takes away from the fun. Games are meant to be fun.', 'Mostly Positive', 78.10, 14.43, 2.77);
INSERT INTO reviews VALUES (22315, 666610, 285, 'when i can''t sleep, this game helps me to relax and get drowsy, eventually slipping off into slumberland, while wide-body passenger jets are left to fend for themselves.', 'u will never be able to have independent parallel approaches, no realism at all', 'Overwhelmingly Positive', 97.54, 9.40, 4.90);
INSERT INTO reviews VALUES (22320, 666730, 149, 'This game is very good. Has a good amount of playtime and is very fun.', 'Bug ridden and not balanced', 'Mostly Positive', 73.15, 44.50, 4.02);
INSERT INTO reviews VALUES (22325, 666820, 204, 'A really neat and simple game that really captures the spirit of its flash game predecessor.\r\nAre you going to get 100th''s of hours of playtime out of this? Probably not, but on sale its pretty cheap and its a good time waster to play a couple of rounds every so often.', 'losing is not fun, this game makes you play and grind 500 hours before they even give you any useful rewards if any, achievemnts require wave 200 plus but will auto spawn game ending waves by 150, dont let the game fool you its a losing is fun BS', 'Very Positive', 92.16, 1.32, 494.10);
INSERT INTO reviews VALUES (22364, 667600, 1014, 'Really great top down shoot em up with nice modern graphics. The pacing is mild and I love that. So that you can chill and enjoy it and still get a kick out of it. The enemies look dope and the shooting action is really fulfilling. The boss fights are a fair challenge. Might not be the greatest challenge for seasoned shoot em up players. But for an average player like me this game is fantastic ⭐⭐⭐⭐⭐', 'Played game on mobile for years. Started on PC. Got a phone call, can''t pause game. Game doesn''t let you pause until you hit a certain milestone. If you don''t respect my time as a player, I don''t respect your game.', 'Very Positive', 92.50, 1.57, 6.63);
INSERT INTO reviews VALUES (22365, 667610, 936, 'I was hesitant about buying this game because of the mixed reviews but after i saw recently a youtube video about the last updates i decided to buy it and i can say it is a very good game despite being in works. I like the graphics, better than Dawn of man which is also an ancient city builder, the game is balanced, everything works pretty good. I didn´t see any bugs or glitches. What i don´t like is the storage system because you can store only 1 resource in a storage building. But i am sure th', 'Another game than promised alot and delivered very little, Where is all the civilisations promised? Launched without 90% of content. Very disappointing and it would take a decade at the current rate to see any real substance. Another over-promised  under-delivered city builder just like some others...\n\nEDIT: After 6 months of updates I can say that it looks worse and performance is worse, another useless and terrible upgrade to UE5? Some new content but nowhere close to the missing 90% of what w', 'Mixed', 64.00, 64.40, 8.48);
INSERT INTO reviews VALUES (22371, 667720, 1914, 'Aw man, this is probably one of the best games from the 7th console generation. This is THE example of gameplay over narrative.\r\n\r\nWould it be better with a good story? Sure, maybe... But does a game with destruction mechanics that are still highly intricate and advanced 15+ years later really need to have a deep story? Mindlessly smash and explode your problems away until you bring down the entire political system of Mars.\r\n\r\nYou''re the good guy in this, trust me :3', 'I loved this game when i first played it back on the 360 in 2009, and I loved the remaster when i bought it for the Xbox One, but this PC version of the remaster is broken. The second i meet with Mason''s brother Dan after the tutorial mission, the game crashes, and i can''t find a single solution that can fix the issue.\n\nDeep Silver, do better here.', 'Very Positive', 80.83, 33.65, 0.52);
INSERT INTO reviews VALUES (22386, 667970, 15212, 'Gets into game with some basic air combat knowledge; instantly shot down by high-pitched screaming kid lobbing AMRAAMs at anything with a radar return. 10/10', 'Stop going through the negative reviews already, go and buy the damn game!', 'Overwhelmingly Positive', 98.23, 62.18, 118.48);
INSERT INTO reviews VALUES (22394, 668210, 1141, 'certified hood classic', 'No keybinds', 'Very Positive', 92.64, 10.47, 2.88);
INSERT INTO reviews VALUES (22400, 668320, 233, 'Civvie made me do it', 'Floaty and slow movement. Barely any enemy variety. For a quake inspired game it didn''t really feel like quake at all. It''s more like those early 2000''s clunky shooters.', 'Mostly Positive', 72.10, 2.70, 2.55);
INSERT INTO reviews VALUES (22401, 668350, 426, '"THE ALIENS CAN''T KEEP GETTING AWAY WITH THIS!!!" I scream, while dousing an elementary school in gasoline.', 'That was really, really boring chapter. It barely had anything to do with Onikakushi. The last tip is the only thing worth reading in this game.', 'Overwhelmingly Positive', 99.77, 26.92, 25.12);
INSERT INTO reviews VALUES (22404, 668430, 169, 'if you''re a biker and a gamer there''s so much fun to be had on track one i haven''t even looked at the rest yet. highly recommend this game', 'I tried to play this game after having it in my library for ages. Switched to Xbox controller in the menu and couldn''t progress at all after that. No ability to navigate through menus, let alone play the game. \n\nVery disappointed, not recommended at all.', 'Very Positive', 88.76, 33.67, 0.42);
INSERT INTO reviews VALUES (22409, 668550, 223, 'Previously did not recommend, but have changed my mind. I did not find the world or story particularly engaging, but there is enough there to integrate into the gameplay, which kept me interested and playing. Input handling is dubious (when spamming the attack button, it''s impossible to turn around) but overall manageable. I was getting tired of the game toward the end of its main story, but i came back around to it in postgame. I didn''t originally put enough effort into getting used to fighting', 'I like the atmosphere and drawings, they''re quite simple yet unique in their own way, but I just couldn''t really enjoy the game. It''s just not that fun nor satisfying and the map is super dispersive', 'Very Positive', 83.86, 24.58, 4.53);
INSERT INTO reviews VALUES (22412, 668580, 10759, 'Awesome graphics, not elden ring difficult, neither solitaire easy, enjoyable story. My life''s better after playing it.', 'There is one thing really holding this game back: you cannot use all the DLC weapons and skills in the main game and vice versa. Please change that as it will give much more incentive to purchase the DLCs.', 'Mostly Positive', 79.64, 50.58, 65.12);
INSERT INTO reviews VALUES (22413, 668590, 186, 'This isn''t the best interactive fiction game I''ve played, but for what it is, it works well. The RPG stats and inventory system are simple but functional. The choices you make have some impact on the story, but none of them can change the direction of it. For the most part, the story is on rails aside from some small details in each chapter.\r\n\r\nHowever, the writers of this game are obviously big fans of H. P. Lovecraft, and if you are too, you''ll dig this game. This game has a strong atmosphere ', 'I had fun with the initial parts of the game, where the choices I made felt like they had consequences, and where the story was quite polished.  After the first few hours, however, the writing takes a tremendous hit.  I don''t mind a couple of typos or grammatical errors here and there in such a text-heavy game, but later in the game the errors were so numerous that it impacted my ability to fully understand what I was being told and consequently reduced my enjoyment by quite a bit.', 'Very Positive', 86.02, 3.98, 8.03);
INSERT INTO reviews VALUES (22417, 668630, 810, '(｡･ω･｡)ﾉ  Very nice game. But the problem is that I don''t know much Chinese.', 'Boring story. Just a lonely dude and tragedy life. Depressed story with stupid peoples that even doesn''t know how to live a life.', 'Mostly Positive', 77.28, 3.77, 3.97);
INSERT INTO reviews VALUES (22435, 668980, 161, 'A fun 6DOF shooter from the good ol’ days of the PS1 generation, remastered and polished up by Nightdive for modern computers to work flawlessly. I don’t know if you’ve ever had the misfortune in recent times to purchase a game on Steam designed for Windows 95/98 and try to get it to run on a modern system with Windows 10/11, but usually the games won’t even launch at all without installing some kind of fan-made patch or mod. Honestly, Steam shouldn’t sell those old games without a huge warning ', 'No, deathmatch with bots and unlockable drivers like the original. sad!', 'Very Positive', 86.96, 2.68, 0.22);
INSERT INTO reviews VALUES (22438, 669050, 126, 'I don''t even like visual novels that much, and this game is some weird furry nonsense that I''m just not into at all, but I bought it anyway plus all the DLC to support this developer and protest Valve''s enforced censorship and inconsistent policies regarding adult content.', ' There''s content here for you, but the game remains, unfinished... the developers have disappeared and that has effected my review, like the anime MM! I don''t believe you''ll ever see a completion, it''s like edging, but it''s a visual novel. \n\nOverall Review: 3 futanari out of 10', 'Very Positive', 86.51, 9.52, 5.08);
INSERT INTO reviews VALUES (22440, 669290, 310, 'Forget bad reviews. Game is good. Some jank here and there but still an amazing experience.', 'This game has so much potential, it sucks that it doesn''t live up to it.\nThe most glaring issue is the AI, they are not threatening at all. They take forever to spot you (even at the highest difficulty) and are not very accurate, giving you plenty of time to kill them before they alert anyone else.\nAs a stealth game it gives you no incentive to actually be stealthy, I just killed an elite trooper, took his gun and started running around like a maniac shooting everything in sight and not caring a', 'Mixed', 52.26, 2.58, 1.65);
INSERT INTO reviews VALUES (22443, 669330, 7795, 'If you still looking for that competitive feeling but you are getting too old to compete with the zoomers, this might just be the game you are looking for. There is no slide canceling, 360 no-scope or high APM microing and all that BS. All you do is place your units, upgrade them and enjoy the view. And maybe spend your night wondering what went wrong.', 'This "indie" game has in-app purchases yet that is not disclosed in their steam page. Meh, I''m refunding the game.', 'Very Positive', 86.95, 132.18, 0.22);
INSERT INTO reviews VALUES (22452, 669500, 161, 'This game has given me a lot of good vibes from playing it so far. It''s not quite as deep in character building as, say, Final Fantasy Tactics, but it sits in a nice middle point between the character customization of FFT and something more linear character building wise like Ogre Battle.', 'Poor implementation, never updated with anything worthwhile, and left in a broken state. Do not Buy. It''\ns like purchasing a single developer''s dream demo that never made it further.', 'Mostly Positive', 73.29, 7.48, 41.68);
INSERT INTO reviews VALUES (22472, 669950, 500, 'Not a bad shooter, there are some funny jokes.\nShort game - completed in 2.5 hours.', 'Lets you fight nazi ponies armed with miniguns, yet still manages to be boring.', 'Very Positive', 86.40, 10.00, 4.42);
INSERT INTO reviews VALUES (22482, 670160, 339, 'очень добрая играя и милая, а главное со смыслом и полностью переданной что значит дружба! (когда у тебя в кармане клинок)', 'The premise is good but this dev knows nothing about game design. It''s just garbage', 'Very Positive', 94.99, 15.58, 4.32);
INSERT INTO reviews VALUES (22488, 670260, 689, 'THIS IS A GREAT GAME GIVE IT A TRY\n', 'Its been out for 2 years with almost zero improvement.', 'Mostly Positive', 76.05, 124.43, 1.08);
INSERT INTO reviews VALUES (22512, 670750, 220, 'thom yorke would love this', 'Linux is not supported. The Linux version is extremely broken, with transparent textures rendering as black, looking movement being limited, causing you not being able to rotate indefinitely, and clicking on one of the doors makes the game crash.\n\nConsidering that this is an exploration game, with art being the entire focus, the broken textures are actually game-breaking in this context. I don''t feel comfortable recommending a broken game, even if the Windows version under Proton works just fine', 'Very Positive', 89.09, 1.05, 1.78);
INSERT INTO reviews VALUES (22542, 671390, 143, 'Played on Steam Deck.\n\n\nI recommend this game, especially if you enjoy match 3 games. The story was decent. Multiple endings. Got all, but one. I had to YouTube the last one. I have a problem with the endings, but can’t go into detail without spoiling anything. Needless to say, my problem with the ending’s doesn''t ruin the game for me. It’s somewhat challenging, but not too much and the story kept me going for the duration of this short, but worthy experience.', 'Frustratingly difficult and no way to "train" your character\n\nThe game has no way to train / get more perks. You simply have to keep losing at the same level with the same powers over and over until you get lucky enough to get past it.  Choosing some locations closes off the entire storyline for others. \n\nI played through the demo and then I bought the game but it wouldn''t let me continue my progress from the demo so I started over a couple times.  Got to the fight with the dogs and they attack ', 'Mostly Positive', 75.52, 3.05, 0.75);
INSERT INTO reviews VALUES (22543, 671440, 1838, 'I like this game in small doses. I probably play it for a few hours every now and again. Its good but not exceptional. If you can get it on sale then great, try it.', 'this game is buggy, vary unoptimized also to managing the trains in mid to late game is horrible due to the lack of granularity on how to manage items for the logistics of the game', 'Mostly Positive', 73.67, 21.77, 59.55);
INSERT INTO reviews VALUES (22548, 671510, 2235, 'Smoking enough weed to get the whales out of the sky', 'So at first glance, the game seems interesting, story is okay, game isn''t buggy and graphics are fine. \n\nBut the gameplay is just so inexcusably horrible. Game literally punishes you for playing it, with how frustrating every single thing in the game is. Weapons have durability like they were made of cardboard, they literally break apart from 100% durability to 0 after killing just 2-4 enemies so keeping them in a working state is a constant chore. Infections, fractures or other similar debuffs ', 'Mixed', 66.89, 72.80, 13.18);
INSERT INTO reviews VALUES (22554, 671620, 682, 'its fun', 'i actually like this game a lot\n', 'Very Positive', 85.63, 950.42, 12.23);
INSERT INTO reviews VALUES (22569, 671860, 76642, 'The game is good, but the dev refuses to release their super big update they''ve been working on for like a year, so the game caps out at 2k players max. 32v32 and 64v64 game modes might as well not exist after certain times of the day. which really sucks, because the game is super fun! the player base has dropped off a cliff though. hopefully when they release the super mega update in 2026, all 12 remaining players will have a real good time with it :)', 'People really enjoyed Battlebit initially and I guess the devs really took offence to people enjoying their product because they systematically did everything they could to change everything people liked about it.', 'Very Positive', 84.66, 124.38, 17.88);
INSERT INTO reviews VALUES (22573, 671970, 860, 'This could be one of the best games for renovating, cleaning and painting random items and cars if it gets more love and the controls were improved.\n\nI spend most of time renovating items and cars. Clicking to remove each car part is almost on par with Car Mechanic Simulator. Then cleaning and painting is pretty fun, but could be improved. It would be much better to reduce motion sickness if done like in Gas Station Simulator Junkyard DLC. Using the grinder there looks more realistic and you don', 'Hard to Control, without the basic ability to rebind keys. I sit between my mouse and keyboard with ,y keyboard being on my left side controlled naturally with my left hand and mouse on the right controlled by ,y right hand. Therefore I always rebind “wasd” to the arrow keys, The game does thankfully allow me to do that, but for some weird reason they chose to HARD bind a few keys, for example "e" to operate just about everything, this makes the game very difficult to play! That is just one basi', 'Mixed', 61.98, 15.13, 12.18);
INSERT INTO reviews VALUES (22585, 672150, 105, 'This is a forever game. You will be playing it for the rest of your life. It''s a chill, relaxed experience. No twitching, no action, just a sort of very low key vibe for when you want to deliver some aluminum to Istanbul to make bicycles.', 'What I thought it was: A game of logistics puzzles with supply chains and route/economy management.\r\n\r\nWhat it is: "This endpoint needs 2 tons of clay, so drag and drop the clay from the production point to the consumer point and wait until the truck arrives. Great, now do this 1 billion more times."\r\n\r\nTo clarify, you have to do every delivery by hand and it''s just the same thing over and over with different goods. I don''t know what exactly the puzzles were supposed to be.', 'Very Positive', 88.57, 1073.57, 1.55);
INSERT INTO reviews VALUES (22605, 672630, 1471, 'Are you saying that managing a school is exactly the same with prison??\n\nYES', 'Game has been abandoned since Paradox bought it, which sucks because when I bought it at the time it seemed to have a lot of potential.', 'Very Positive', 86.81, 19.28, 12.47);
INSERT INTO reviews VALUES (22626, 673000, 783, 'sludge life with guns', 'You can make a game look stylish and cool, absurd and humorous, even have a bomb-ass soundtrack for flavor. But that doesn''t mask the fact this game is kinda boring to play through. All flash, no substance.\r\n\r\nIt''s like someone was enamored by games like Superhot and Hotline Miami and wanted to make something like that, but it falls flat.\r\n\r\nYou''d be better off getting the DOSEONE soundtrack and not even bother getting the game. \r\n\r\nGreat for speedrunners or high score chasers, at least.', 'Very Positive', 84.55, 4.05, 1.03);
INSERT INTO reviews VALUES (22633, 673130, 5150, 'Alright game, play fun.\r\n\r\n...With one huge caveat though: your computer must be strong enough to run modern AAA at "high", since this game is also quite demanding on the hardware — don''t look at its "boomer shooter" artistic style, it''s a proper high-end Unreal Engine 4 title. On its low settings, the game becomes barely playable: even if the combination of low resolution with bad aliasing won''t literally make your eyes bleed, then the very next minute you''ll discover enemies attacking you from', 'Very boring weapons, only the magic staff is effective and it is boring to shoot from it, boring confusing maps, many melee weapons in the shooter, shots are only in the form of magic.', 'Very Positive', 94.39, 13.88, 0.25);
INSERT INTO reviews VALUES (22636, 673210, 592, 'This is a pretty good game if you like "take stuff from point A to point B" type games. It''s not polished - I wouldn''t recommend the full price. It feels like a couple people tried making a game and had a pretty good result for their portfolios', 'Online Requirement for a Single-player offline game \n\nthere are ways to make drm less agressive', 'Mixed', 68.92, 42.23, 39.75);
INSERT INTO reviews VALUES (22641, 673260, 367, 'ogs remember 2017-2018 starblast', 'worse game i ever played full of teamers there is no way you can play survival without 10 big machines shoorting on u same time', 'Mostly Positive', 79.02, 1321.68, 551.27);
INSERT INTO reviews VALUES (22649, 673450, 309, 'Works fine on Oculus / Meta Quest 2. However has a launcher window starting on Play instead of the game itself, so you need to click there first - switching via menu button to steamvr and then desktop will help.\n\nTurned out not as bad as I thought. I underestimated the puzzle part so had to check a walkthrough video to start - the game was not broken, it just really expected me to figure things out on my own. Mostly it''s seek & point & click.\n\nThe full price is ridiculous, I bought it for some c', 'doesn''t have built in turning, shows vive wands no matter what, doesn''t even have a good tutorial. confusing in the bad way', 'Mostly Positive', 74.11, 1.07, 0.32);
INSERT INTO reviews VALUES (22658, 673600, 204, 'I really like this game its just really fun to play but i wish there was a sandbox mode were you can get every item in the game for free and make anything', 'Wont let me into the next prison even tho i beat the first one', 'Very Positive', 86.27, 3.15, 2.77);
INSERT INTO reviews VALUES (22659, 673610, 4391, 'I do love this game, it''s a really good airport sim in my opinion, although it still has bugs and some things that aren''t fully polished yet, the devs were good at the start but now we haven''t even had a patch since late 2023 (November time) I hope that the devs to see this and or more reviews like this and hope they can fix some things. I''ll give an example: I have made a baggage area where my dudes can collect it via luggage haulers and take it to the intended aircraft. Problem is my ramp agen', 'please listen to everyone complaining about optimization/ game play, after a certain point game becomes quite literally unplayable. don''t get me wrong, i love this game and how detailed it is but if you have a short temper or are easily irritated just skip entirely', 'Very Positive', 83.22, 80.80, 68.95);
INSERT INTO reviews VALUES (22666, 673750, 1208, 'Good way to practice English. My friend knew literally no English. After playing this, at least he could say ''fuck'', ''stupid'' and ''idiot''.', 'A fun(ny) game ruined by shitty netcode. Game desyncs all the time online making it impossible to progress with a friend.', 'Very Positive', 88.91, 4.62, 20.53);
INSERT INTO reviews VALUES (22667, 673800, 358, ' STILL BETTER THAN BLIZZARD GAMES ', 'This game should have been offered as a mod, not as a regular series. It''s tiring cuz you have to place objects yourself, and it''s really hard to play with a Steam Deck. I don''t recommend it.\n\nEven if you place the blocks correctly, if you make a momentary control mistake and have to restart, you will have to place all the blocks exactly the same again. Why did you make the game so frustrating? If you play this game with a controller, it is not a game, it is a disaster. I hope we won''t see this ', 'Very Positive', 81.28, 2.65, 5.08);
INSERT INTO reviews VALUES (22672, 673850, 204, 'Rough around the edges.\r\nVery heavy handed.\r\nOverloaded with pop culture references.\r\n\r\nDespite that, it''s charming, unyielding and unapologetically intentional in its delivery. If you can look past the flaws, you may be surprised with what it has to offer.\r\n\r\nMy biggest real criticism is the visual inconsistency and interface. I think for a story this tightly directed a different format might''ve worked better.', 'i couldn''t get past 20 minutes of this game, the dialogue just is absolutely terrible, the first situation is so badly written so illogical, so stupid, so childish, reminded me of those games made in the 2000s by kids using flash, its that level of writing and story. I really wanted to like this game. and no, i wont give it more than 20 minutes as that already felt like a waste, and if the writing is that bad even if it magically improves tenfold it would still be terrible. Sometimes I feel like', 'Very Positive', 86.76, 8.18, 0.82);
INSERT INTO reviews VALUES (22674, 673880, 7439, 'From the moment I understood the weakness of my flesh, it disgusted me. I craved the strength and certainty of steel. I aspired to the purity of the blessed machine. your kind cling to your flesh as if it will not decay and fail you. one day, the crude bio-mass you call a temple will wither, and you will beg my kind to save you. But i am already saved, for the machine is immortal. Even in death I serve the Omnissiah', 'Literally every map event lied to me about what it did', 'Very Positive', 92.86, 63.18, 2.87);
INSERT INTO reviews VALUES (22680, 673950, 4619, 'Don''t play this game unless you plan on dumping countless hours into. I didn''t really learn anything about real farming but I was ADDICTED! This game will suck you in for no good reason at all\n\nWould do it all again!', 'Eh. I''ve played for nearly 11 hours and I''m still not sure what I''m doing. I''ve earned coins, but buildings cost diamonds to build? Do I earned XP or earn and spend it? What''s up with the badges? \n\nYou can build buildings (like a vegetable or fruit stand), which increases storage, but what happens when your storage is full? How long does it take to deplete your storage? Is one vegetable the same as any other vegetable? Does it matter if I plant lettuce vs corn?\n\nThe quests always seem to ask for', 'Very Positive', 93.14, 142.95, 10.80);
INSERT INTO reviews VALUES (22684, 674020, 14424, 'No wonder the game is dying. the game is good. all your reviews mean nothing to me saying it''s garbage, it runs fine, its smooth way better than other shooter games. but the attitude you guys bring to a shooter game is garbage. I suppress fire and my team mate kills me says my aim is garbage. You want to push up but instead you kill me and say my aim is garbage. you guys need to play something else or be a little more sports man like.', 'needs coop and bots bad cuz there is literally noone playing. lots of wasted potential. coop, console release, bots, and crossplay would literally save this game', 'Mixed', 60.04, 68.30, 23.03);
INSERT INTO reviews VALUES (22685, 674090, 624, 'I bought this game some time ago in EA, was pretty satisfied then as updates were planned and just because i loved these airplane/airport management games. I forgot about this game for 1 or 2 years, and played this again in 2024 only to see that reviews were abysmal and updates and any leaks have essentially stopped since 2023. Honestly the game is pretty overpriced considering the current state of the game. However, the devs had said that they will(?) continue work on sky haven, so I''m hoping t', 'Abandoned, don''t waste your money. Devs can eat a fat one.', 'Mixed', 62.02, 68.75, 22.70);
INSERT INTO reviews VALUES (22688, 674140, 5496, 'Only playing for 11 hours, All assets are made by hand, the engine they use is open source, minimal bugs on day one and never crashed, they continue to provide fixes for the game years after its release. \r\nTHAT shows dedication to a game/project. \r\n\r\nAnother actual W dev team and Game.\r\n(I get to pet Bunger in VR now that they added a VRMode, which the engine they use has none. So for their devs to FULLY MAKE A VR MODE FROM SCRATCH, is a MASSIVE W for this team. I would love to show more apprece', 'do NOT let your children play this game, beffica is fine as heck and my son is obsessed. constant fapping the second i hear this game boot up in his room. im removing his door and im suing. expect to hear from my lawyers soon. unless you make beffica body pillows to sustain his addiction. please please please make them.', 'Overwhelmingly Positive', 97.71, 11.68, 1356.37);
INSERT INTO reviews VALUES (22711, 674500, 2966, 'This game is really fun for ten minutes and then get kinda boring.Overall it''s pretty fun', 'Very fun and unique but abandoned by useless devs', 'Very Positive', 81.79, 325.58, 20.38);
INSERT INTO reviews VALUES (22712, 674520, 1063, 'A better time investment than actually pursuing meaningful goals.', 'way too difficult, it feels like there barley anything you can do and there tons of unused buttons, no reliable defensive abilities or ways to avoid damage, easy mode has to be unlocked, training mode which is the real tutorial has to be unlocked. \n\nHitting enemies feels good, the game looks good, the extra game play modes like score and versus are cool, but the difficulty lack of defensive actions and the SUPER button mashy game play makes it a not recommend from me.', 'Very Positive', 92.47, 6.10, 5.33);
INSERT INTO reviews VALUES (22719, 674750, 525, 'I say... It''s OK. This is a shooter / Tower Defense game. The graphics are fine. The music is repetitive. No story here, just an anecdote if any. \n\nNo bugs or crashes.\n\nOverall, is entertaining for a few hours. It''s the same game as before with slightly better graphics. Almost nothing is different. There''s no story or any missions, just survive till you get overrun by a horde of zombies and start all over again. It includes cards and achievements. It''s a simple game. It''s a cheap game. It''s hope', 'A very boring game, gets boring in a couple of minutes.', 'Very Positive', 83.24, 3.95, 0.12);
INSERT INTO reviews VALUES (22723, 674850, 135, 'An absolutely fantastic recreatation of playing as a QB with completely unforgiving and very realistic throwing mechanics and playmaking. \n This has some seriously SMART AI (this actually shocked me), a playmaking board in a lockeroom as a homebase to make some plays which is very intuitive.  Pplay some 2 min drills with the plays you created in rounds of increasing difficulty.  Im about 4 hours in and ive made it to the 5th round with about 200 points.  I just cant stop playing.  This is a game', 'This game would totally be worth the price for the experience if it were not for the actual football throwing motions that do not feel just right. Unlike VRQB, which feels a lot more natural, the ball tends to dive most of the time when throwing naturally, although you could compensate for the angle of the ball-throw necessary to get it where you want it to go but then it does not feel natural. I had more success throwing the ball with an underhand toss, even for long distance shots to score a t', 'Very Positive', 91.85, 19.97, 0.18);
INSERT INTO reviews VALUES (22727, 674930, 1454, 'boyfreind. dungeonndsn. boyfriend in da dingeons,,,,s,a,,, i love oyfriwend,,,,,', 'Boyfriend Dungeon is a game I picked up because I thought it looked cool. A dating simulator where the people you date turn into weapons and then you build relationships by taking them into the dungeon? That sounds pretty neat!! Except the execution left much to be desired. In the initial version of the game, there were two dungeons. That''s it. Two whole dungeons in a game about dungeon crawling. The combat in the dungeons can feel shallow, with your moveset changing between your various partner', 'Very Positive', 91.40, 8.10, 12.77);
INSERT INTO reviews VALUES (22728, 674940, 51694, 'this game is so ass, you get to touch little stick figures which can lead to some highly sexual scenes, do not let your child play this game. This message is to all of the mothers out there. This game is full of druges and alcohol and violence and scarey. I dont recommend buy instead go to gta 5 its a more wholesome expiriace with real people which you can talk to and have fun, no violence. Only car', 'Game is no longer maintained and has lots of issues. Don''t buy it.', 'Very Positive', 94.28, 26.22, 79.07);
INSERT INTO reviews VALUES (22731, 675010, 9965, 'imagine playing for 10 hours, crashing it 2 mph and losing all your cargo and having to drive to the wood place for another 5 hours to get wood and reset all your progress', 'under rated gem, an essential if you like trucks\n\nEDIT: Saber Interactive is a predatory publisher and removed the original Spintires (2014) game developed by Oovee from Steam, with some claim that they themselves started the Spintires franchise. I don''t know how truthful this is but the original game is not for sale. Because of this I have left a negative review and do not recommend you buy their product', 'Very Positive', 90.71, 62.62, 11.67);
INSERT INTO reviews VALUES (22739, 675170, 183, 'The controls are easy with mouse & keyboard. For throttle you need to map a 2nd key inverted to throttle down. left/right & up/down just use your mouse just like Warthunder.', 'Fundamentally unplayable.  Horrible interface, no ability to exit from detail menus.  A total waste of time and money, purging from the drive now.', 'Mixed', 56.28, 42.28, 1.70);
INSERT INTO reviews VALUES (22743, 675240, 212, 'Shining Song Starnova is, overall, a really well put game. It has a great Visual Novel experience, nice art and the stories of the girls are amazing! A FAVOURITE for sure!\n', 'No gameplay no sunrider what the fuck is even the point. I dont give a damn about idols irl this was supposed to be management game you dont get to do anything. Stopped """"playing"""" after like an hour.', 'Very Positive', 94.81, 49.30, 7.72);
INSERT INTO reviews VALUES (22744, 675260, 3727, 'Telltale did an outstanding job with this game. My choices fully mattered in shaping the story, and I have to give huge credit to the team for improving on the previous installment. They took everything that worked and made it even better. It’s a shame that a third season is a long way off (if it ever happens), but if you have the chance, experience this masterfully crafted Batman story as soon as possible—it’s made with an incredible amount of passion and effort.\r\n\r\nI really enjoyed the side ch', 'Usual Telltale nonsense.\n\n\n\n\n*Telltale will remember that.', 'Very Positive', 94.28, 10.98, 11.52);
INSERT INTO reviews VALUES (22792, 676420, 280, 'Short and fun, with a handful of levels requiring a good amount of thinking. Getting all of the achievements is very doable.', '➖➖A minimalistic puzzle game where we have hooks at our disposal and we have to use them to throw balls into holes.\r\n\r\n➖After an hour I got totally bored. After 27 levels I gave up.\r\n\r\n➖In my opinion the game should have more mechanisms than just 10.', 'Very Positive', 92.14, 1.60, 1.10);
INSERT INTO reviews VALUES (22793, 676430, 323, 'Straight up amazing how many levels he could come up with based on such a simple concept.', 'This is just horrible. No fun at all. It feels like this game is designed to make you feel frustrated. Unless you are okay with starting stuff all over again because you pushed something out of order.', 'Very Positive', 81.73, 2.07, 1.58);
INSERT INTO reviews VALUES (22798, 676500, 338, 'it''s OK.', 'The game feels too unpolished and barren for the 17€ price tag. Would maybe consider it OK at a 85%+ sale though.\n\nResearch effects are very uninspired and the scaling on them feels awful. You will quickly reach a point in the game where there are no new things to unlock, and all you do each reset is stuff like increasing weapon damage multiplier from 102x to 103x for sub-percent DPS increases in a game with exponential scaling.\n\nThe FPS element, while rare in idle games, is, as you can likely s', 'Very Positive', 83.14, 3777.38, 253.60);
INSERT INTO reviews VALUES (22807, 676630, 155, 'I really like the game with it''s FMV and in the way that you interview people from the time to understand the story more, but progression feels strange. I got stuck and the only choice is to replay the interviews.', 'It is very informative but it annoyed me to no end that I could not skip minigames that I have already completed. When I ran out of coins I had to skip the ending scene a looot of times. It was extremly tedious to complete it to 100% and get all the information. It is nice to hear them tell their own story but I could do that via YouTube or other media sources and hear much more. Sadly I can not recommend this game.', 'Very Positive', 91.61, 1.42, 2.05);
INSERT INTO reviews VALUES (22817, 676820, 1333, 'It''s a fantastic narrative game where you play as a robot detective solving a mystery in a futuristic subway system. As someone who loves futuristic games, this one really hit the mark. The whole game revolves around talking to other robots and piecing together clues from their conversations. The writing is sharp, and the world-building is surprisingly deep for such a short game. It touches on cool topics like AI, free will, and what it means to be “alive” in a way that’s both fresh and thought-', 'I don''t know why, but my own butt hurts just watching this. He just doesn''t stand up once the whole game. I like the plot-twist at the end, but that''s it. I wish there was more to do, instead of just sitting and talking until the end. Narrative-based games are fine, I love those genres. But please don''t make it limited. Its like I got nothing to do. Sit. Talk. Sit. Talk. Die.', 'Overwhelmingly Positive', 95.12, 1.83, 3.75);
INSERT INTO reviews VALUES (22819, 676840, 460, 'Decent enough vr game for 4 euros that i paid for it on sale. I would not pay the full price for it because of very annoying bugs.\nOn vacancy day 2 for example the guy carrying the stuff turned around and started walking back where we came from and got killed by zombie horde. Did not feel like playing from last checkpoint again.\n', 'Like don''t get me wrong the game is okay but there are some problems with the game that should be addressed before even buying it period.\n\nCONS: 1) Had trouble hearing the game, 2) Zombies are poorly made, 3) Movement could be better, 4) Interactions didn''t always work, and 5) Takes too many hits to kill the zombies.\n\nPROS: 1) Guns shoot well, 2) Story is good, 3) The tutorial was good.\n\nThe cons outweigh the pros making the game not worth buying. REFUNDED', 'Mixed', 65.22, 6.23, 0.80);
INSERT INTO reviews VALUES (22826, 677020, 103, 'I need an eventide 4 where Mary sends John to hell.', 'Was enjoying this enough. a bit cheesy, not too hard. But then I hit a bug towards the end. The hint button stopped working. Had to check a walkthrough and realised there was an object that I didn''t pick up that I needed but was no longer able to pick up. It broke the game and I can''t complete it', 'Very Positive', 84.47, 3.65, 3.35);
INSERT INTO reviews VALUES (22831, 677120, 4500, 'You play character to make game easier to make game harder to make character better to make game easier to make game harder to make character better to make game easier to make game harder', 'Maybe it''s because I''m playing solo, but the game hella grindy. The combat is nowhere near fun enough for me to want to keep playing. I would request a refund it if I didn''t only pay a few bucks for this game.', 'Very Positive', 88.56, 518.60, 1.65);
INSERT INTO reviews VALUES (22832, 677160, 3284, 'dont buy this game if your friend begs you and promises to play with you. Trust me he wont and it will have been a waste of money. Im talking to you Gio.', 'The game itself is great with the right friend (one who actually uses his brain). The puzzles are tough and genuinely challenging, which makes solving them really satisfying.\n\nHowever, I can’t recommend this game because of the broken checkpoint/save system. If you leave the game, you’ll have to redo all the puzzles from the beginning—no progress is saved.\n\nIf you’ve got the time to finish it in one sitting (you need 300 iq for this), then sure, give it a shot. Otherwise, it''s not worth it.', 'Mostly Positive', 79.26, 3.70, 1.62);
INSERT INTO reviews VALUES (22844, 677340, 654, 'If I was to say I was obsessed with this game.. It wouldn''t describe it. I am craving more and more content. I can''t get enough! It''s amazing that I can play multiplayer with my husband too. If you like building your ''colony/city'' games, this is the game for you. The developers are also super helpful and interactive. 10/10 would recommend.', 'Played it on the switch and iked it very much.\n\nWanted to play on the steamdeck, but unfortunately the menus are not useable.\nI wish you would use the same radial menu like on the switch. That was a great way of playing!', 'Very Positive', 85.47, 457.93, 0.10);
INSERT INTO reviews VALUES (22847, 677480, 389, 'lot of good potential. fun to build. but only a few places to set your base on because of limited resources.', 'Stinky bad game', 'Mixed', 50.64, 74.73, 5.12);
INSERT INTO reviews VALUES (22851, 677620, 159, 'This is as if halo and portal had a baby. Set in an unreal tournament fighting arena. Super fun even though its all PVP and you cant do offline and fight bots but still fun none the less.', 'The game has incredibly inconsistent relaod bugs. Not even related to reloads specifically, sometimes youll be ocmpletely unable to fire your gun. The game feels like halo + portal sure. But dying consistently several times a game because your gun literally seems to misfire? Yea no. \nThe audio in the game is completely fucked too. Gun shots as well as footsteps seem to just be randomly placed and not actually give any form of direction, at least not a correct direction. \n\nWould be a fun game if ', 'Very Positive', 93.71, 10.37, 4.82);
INSERT INTO reviews VALUES (22878, 678310, 109, 'awesome game, fun and tons of tables, tickets  to collect to change table skins and open up challenges, worth the money!!! its addicttttttttiivveeeeeeee!!!! must have in youuuuuuuuuuuur collection!!!', 'Developer last seen? The cell phone game seems to be the most important thing in development. You get frustrated quickly to this game. Has nothing to do with proper physics.', 'Overwhelmingly Positive', 98.17, 277.02, 477.15);
INSERT INTO reviews VALUES (22889, 678520, 241, 'If you want an arcade-like Gal*Gun experience with proper VR controls, get this on sale. Otherwise, get Gal*Gun 2 and be ready to tweak it for a working smooth experience that contains story and much more interactions. \n\nShould mention that this version has pretty long loading times and Oculus native compatability if using an Oculus link (wired or wireless). If you don''t want to play through Meta compatibilty - resort to using LibOVRRT from github.', 'Bought this game a year or so back and it didnt work with my Oculus Rift S. The game would crash within the first minute of playing no matter what I do. Fast forward to today, Ive got a Meta Quest 3 and a newer computer, but the game still crashes after a minute of playtime. This game release in 2017 and the devs still havent fixed it. It would be a good idea to avoid all games these clowns make since they simply dont care.', 'Very Positive', 81.74, 2.23, 0.42);
INSERT INTO reviews VALUES (22905, 678900, 1032, 'At first I had to get used to the different RPG elements, but after playing it for a bit I really took a liking to the whole concept. \r\nIt''s a welcome change of pace after all the farm simming. Also, developers have been updating the game constantly and it has only gotten better.', 'Do not buy!\r\nThe tutorial pads out the first 2.5 hrs with the same tasks on repeat.\r\nOnce you get to main game its a buggy unplayable mess\r\n\r\n', 'Mostly Positive', 70.64, 103.73, 3.90);
INSERT INTO reviews VALUES (22910, 678950, 24852, 'Great game, if you like dbfz and you like fighting games pick it up. this game can run on even the most trash pc. into 2024 there''s still a pretty active community online. Wish they would bring back raids. \n\nthe single player experience isn''t too bad.', 'Could have been a great game but half the roster is behind a paywall. Fighting games need to quit doing that or people like me aren''t going to play them anymore.', 'Very Positive', 91.29, 2063.47, 31.57);
INSERT INTO reviews VALUES (22911, 678960, 17788, '>dodge that doesn''t work\n>terrible gank fights\n>boring level design\n>downright terrible bossfights\nwelcome back dark souls 2', 'Code Vein is a game with many genuine strengths. Unfortunately, it doesn''t seem to know what those are, so it stumbles and fumbles at actually letting you enjoy them, instead of bogging you down in frustrating boss designs, an incoherent and uninteresting story, and a cast of shallow template characters who the game insists have become your best and most trusted friends. Code Vein is a game that relies on you making use of NPC companions and equips them with interesting abilities, but doesn''t ef', 'Very Positive', 87.38, 14.05, 41.02);
INSERT INTO reviews VALUES (22912, 678970, 122, 'I wouldn''t be able to improve on all the wonderful reviews  already posted.', 'It''s ok, but not for full price! Way too short (2h) and easy, no new puzzles. Videoscenes lag.', 'Very Positive', 92.62, 25.50, 2.50);
INSERT INTO reviews VALUES (22919, 679110, 448, 'Just finished the game, its not as bad as some people claim it to be. Fun old style mindless hack and slash Game with a Werewolf kick. It has few somewhat cool boss fights and graphic it pretty good too. Its for people like me, looking to play a simple game with not too much thinking, Transforming into werewolf and killing everything around felt great.', 'too hard :(', 'Mixed', 68.08, 23.12, 2.30);
INSERT INTO reviews VALUES (22950, 679750, 257, 'Quite immersive and fairly easy to learn. Not to mention way cheaper than buying a fishing license every year. I''m glad a friend gifted this to me.', 'too much fish would not recommend don''t waste your money', 'Very Positive', 89.11, 6.08, 11.57);
INSERT INTO reviews VALUES (22956, 679900, 2409, 'I find the game fun and enjoyable. I like how you can either try to get the best combo possible or the bare minimum. It also gives you a fun story line and overall a fun game', 'Instantly Refunded. The store page indicates FULL CONTROLLER support, but there is ZERO controller support. May be a good game, but that blatant of a misrepresentation is an immediate no for me.', 'Very Positive', 92.61, 182.50, 0.10);
INSERT INTO reviews VALUES (22972, 680360, 1206, 'It''s fun\n\nLot of ppl complaining about tough enemies and throwing being OP. Game is clearly not well balanced, just get better gear. You''ll deal 1M dmg per melee crit if you spend some time doing quests.\n\nThe only thing that actually sucks is that idle game in the tavern. Why is it there? Litteral waste of time that thing', 'Softlocked in Tutorial after loading back into it after noticing the price for the physician was cheaper there, broke the save \n\napples somtimes roll to the other side of the map\n\nlimited resources per map (e.g. Wood, which you can no longer collect after your storage is full, and it vanishes if you revisit the region)\n\nalso no downside to spamming the E key, if you really want to hide things don''t make the best way to find things spamming E', 'Very Positive', 85.07, 17.20, 2.02);
INSERT INTO reviews VALUES (22973, 680380, 210, 'Nice character development on the citizen fare of nighttime Paris. Well-written dialogue without any discernible mistakes. Art is fantastic, great style. Enjoyable game. Got a really good feel for the primary character.', 'It''s an excellent game, except for the lab cat passenger. If you pick up the girl looking for a cat just remember her face and exit the game, Do yourself that favor, and don''t pick her up again. It''s a game, and you don''t need that story in your head.', 'Mostly Positive', 77.14, 57.00, 13.32);
INSERT INTO reviews VALUES (22976, 680420, 30273, 'I played this in 2024 on a PC, so now idea how it launched, somehow it flew under my radar, i had a blast with it, especially with the monster hunts and bounties, the story is good enough, the characters are likable, hope there is a sequel in the oven for this game.', 'Played with a group from level 1-15 (out of 30) . One member of our group spontaneously lost their character. Has to restart. We''re told there is no way to save characters(''it''s on a server, not local, can''t be backed up), and that this bug has been there since the game''s release. \n\nThat''s unconscionable for a game to not provide local saves and have bugs that wipe characters. Can''t ever recommend a game like that.', 'Mixed', 68.75, 11.53, 146.67);
INSERT INTO reviews VALUES (22979, 680480, 175, 'ICY is a choose your own adventure with light survival elements. You lead your ragtag band of survivors through a frozen post apocalyptic wasteland in order to rescue your friends and maybe even find a home.\r\n The story is decent but not outstanding there are a few branching paths which culminate in a small number of endings. The combat is simple but surprisingly tense as you and your opponents race to kill or be killed.\r\nDefinitely worth a play if you like these sorts of visual novel type adven', 'Coming into this game I was excited to see the story it offered as well the amount of strategy that would be involved in the decisions you made. However after playing it for a few hours, sadly I was dissapointed by the mechanics in this game. The writing and story seems okay from what I can tell nothing amazing but it isn''t terrible either. Where the game really takes a dive for me is in its mechanics. For example hunting and resting work completely differently then they do when you initially ju', 'Very Positive', 88.00, 8.75, 3.67);
INSERT INTO reviews VALUES (22983, 680590, 110, 'One of the greatest game on my top games. I really like Ollie, no, love her the most. Thank you Markiplier for introduce the game to me.', 'Sorry, not playable. screen is always stuck at small size, so if you''re not using a 12" screen then  you''ll miss out. those of you who love this game must be playing on a cell phone which I wont play. I need glasses to read my phone, not for this. Sucks because its been out for a while and not fixed. Wasted money, again on you loser programmers. You guys really suck. PONG ass holes! I have played and programmed games Since PONG. Get it together you greedy ass holes! Make me work for what I paid ', 'Overwhelmingly Positive', 96.36, 35.47, 0.55);
INSERT INTO reviews VALUES (23000, 680980, 416, 'I really like games like Headliner. You have to spin the news by selecting from the available articles to produce the slant you want. Are you going to be pro-genetic modification or anti? Are you going to be sympathetic to refugees or hostile? When you leave the office at the end of the day and walk home through the city, you see the effects of your decisions on your city. It''s a fun little political sim.', 'A very interesting concept, but it spends too much of this very short game''s time on having personal discussions with family. My decision making and impacting the world was about 10 seconds at a time, followed by a few minutes of reading how my family felt about my decisions.\n\nThe choices are too black and white, your''e either pro-issue or anti-issue. Your decisions on which article to publish literally affects the public in whatever direction you chose, no nuances.\n\nThe graphics during the fami', 'Mostly Positive', 76.92, 0.77, 0.90);
INSERT INTO reviews VALUES (23013, 681240, 218, 'How have I not reviewed this gem? Go in blind. Read the text and try to understand it for what it is. This game is a top 10nner.', 'Well, that was different. Really not sure what to think about it.  Pretty experimental and artsy. I don''t think I liked it, but I don''t think I''m supposed to. The game description just says "apolitical" yet it feels political with all the women dressed in niqabs including your character, in an occupied Islamic country. It has big tonal shifts. Tries to be humorous sometimes, but I didn''t find it funny. Tries to be deep and philosophical sometimes, but it''s hit and miss. Control on the overland m', 'Very Positive', 89.91, 5.43, 2.60);
INSERT INTO reviews VALUES (23015, 681280, 8987, 'A long time ago, before I became disabled for unrelated reasons, I rode BMX. I was not all that good at it, but I tried. I failed a lot, but I tried. It''s something I would still be doing to this day, at 42 years old as of writing this, but I can no longer ride a bike because of health reasons. I do have a recumbent trike, but it''s not the same; I also don''t get to ride it all that much. I used to do, or try to do, some of what''s in this game. It''s hard to play the game and not think about my pa', 'I would rather pay and play a Ubisoft game for 1 hour and have them steal it back.', 'Overwhelmingly Positive', 95.50, 284.92, 0.37);
INSERT INTO reviews VALUES (23017, 681330, 176, 'Peaceful, addictive.', 'When utilizing any of the shipyards in the game to build a ship, the shipyard will sometimes require materials to begin construction on whatever ship is in queue - which is fine.  What''s not fine is when the shipyard requests materials but doesn''t have the money to pay for them - and there''s no option to trade them for free.  What you end up with is a deadlocked game where all the shipyards have your ship in the build queue but can''t begin construction, no matter what you do.\n\nI looked for and f', 'Mostly Positive', 76.70, 9.70, 54.37);
INSERT INTO reviews VALUES (23022, 681390, 436, 'It''s essentially a chinese version of Killing Floor 2 in VR. I love it. The game runs perfectly on an Oculus Rift(the hands are awkwardly aligned, but the guns and melee weapons are perfectly fine as-is). If you run the game in Windows 7 compatibility mode, you can avoid the spawning in the ground glitch that occurs on Oculus.\n\nOverall though, for $5, get this fucking game. It''s simply too much value to pass up at this price. To be honest, I''ve had more fun with this game than Killing Floor: Inc', 'No any discount on sales.', 'Very Positive', 86.01, 11.73, 0.15);
INSERT INTO reviews VALUES (23037, 681660, 4562, 'Game is good.  Bumpy Launch, but overall it gives me Aion flashbacks.  The game isnt the next big thing, but it isn''t trying to be.  If you want a fun game to play with friends and pvp.  Bless is a good choice.', 'worst mmorpg ive ever played and a scam pay to play game that turned f2p', 'Mostly Negative', 36.72, 283.78, 12.70);
INSERT INTO reviews VALUES (23041, 681730, 481, 'underrated. i keep coming back to it!  it''s got more of an emphasis on the tactics and survival than some of these other deck-builders that get really huge, and as a result is somewhat more challenging, but it''s got good art and a real mood to the world that i like.  i think tactics people don''t like cards as an interface, and card people don''t like slow methodical strategy encounters and hard fail states. but if  combining those things w/ the classic ftl-style overworld map progression sounds c', 'The difficulty curve on this game is just whack.  I''ve beaten slay the spire at ascension 20 (hardest possible difficulty) half a dozen times and I find this game intensely frustrating at the easiest difficulty.\r\n\r\nLike yes I see that there are ways that I *could* have averted problems with the right combination of cards but the synergies are way too easy to disrupt.  So if I luck into the right draws the fights are easy while if I luck into the wrong cards at the wrong time I''m screwed.  You ha', 'Mostly Positive', 79.21, 20.07, 66.40);
INSERT INTO reviews VALUES (23060, 682130, 1096, 'Discord Bot Maker is so amazing!\r\n\r\nIt is one of the best programs for making discord bots, HOWEVER...\r\n\r\nIt is unfortunately outdated, but it still runs good bots, and there is a good community making modded commands and events for the program, so otherwise, it still is good, but if you''re looking for a more updated discord bot maker, I recommend, (Bot Maker For DIscord) BM4D.\r\n\r\nThank you.', 'Useful -- But far out of date. Can''t do anything to do with commands in dms in the modern day </3 See: "Bot Maker For Discord" for more modern features.', 'Very Positive', 82.94, 390.07, 601.23);
INSERT INTO reviews VALUES (23061, 682140, 304, 'fun, but now is abandon for sequal', '$18 is too much for a dead game that feels severely outdated now, save ur money', 'Mostly Positive', 78.62, 1.88, 0.22);
INSERT INTO reviews VALUES (23074, 682450, 173, 'This is the Gundam Breaker 4 you want to play.', 'Camera and controls are straight jank, targeting barely works, and it''s generally not smooth at all.', 'Very Positive', 83.24, 3.60, 0.67);
INSERT INTO reviews VALUES (23080, 682530, 443, 'Very good tower defense. Unfortunately it''s too short and too expensive for launch for the content.\n\nTwo achievements are really dumb. One is to get all the others... and the other is to complete all levels on normal difficulty. I''ve played all the levels on hardest and didn''t get this... so now I have to play them all again on easier difficulty?', 'Nah, I just cant get into it. It is way too restrictive to have any real fun.', 'Mostly Positive', 76.52, 8.43, 2.42);
INSERT INTO reviews VALUES (23082, 682570, 200, 'Yes, it''s repetitive.  Yes, it''s a silly game about killing zombies as schoolgirls.  On the other hand, does wonders for social anxiety.\n\nListening to the schoolgirls talk of hobbies, anime, coffee beans, and skin lotion you just kinda feel a sense of "Aw, that''s nice!"  Even if the usual sort is rolling their eyes at the prattle...\n\nStill, nice mix of shojo bits and zombie killings.  I just came for the killing of zombies, didn''t expect to feel comfort in party chats.', 'Doesn''t support 2k resolution, no hitmarker feedback or sounds when hitting, game feels like free trash on Unity.', 'Mixed', 69.50, 41.83, 0.15);
INSERT INTO reviews VALUES (23097, 682990, 9106, 'This game is good until a certain point where its just running around 24/7 and avoiding police, it gets old pretty quick', 'Worst performance I''ve ever seen in the recent free visual update. This game has somehow demanded more from my PC than any game before or after it.\r\n\r\nPacking drugs has the most insane UI ever. Trying to fulfill the stupidest requests for 33g of drugs is agony. and having to pack 1g bags back into storage 1 at a time is insane.\r\n\r\nBuyers demand the exact amount of product. A demand for 29g can''t be fulfilled with 30g for example. You''re telling me they would decline free extra drugs??\r\n\r\nAll in ', 'Very Positive', 86.60, 91.35, 10.33);
INSERT INTO reviews VALUES (23113, 683320, 23439, 'Undoubtedly, it is one of the most beautiful games \r\nThis game showed us that even in the darkest and worst moments of our lives, there is always a light to guide and save us\r\nTo find the lights of life, you have to try and never give up \r\nThe game music was very relaxing Overall I enjoyed it :)))\r\n', 'A Chore from Start to Finish\n\nGris has a sublime art style and sound design; however, it is utterly ruined by shallow, meaningless puzzles and poor level design. As a video game, I wouldn’t recommend it at all.', 'Overwhelmingly Positive', 95.40, 3.10, 3.53);
INSERT INTO reviews VALUES (23138, 683900, 1600, 'I originally got this game as a prize from a cereal box like 18 years ago. Still holds up.', 'Opened, saw new UI, closed the game.\n\nI tried coming back a few months later to "give it a chance" but the game lacks basic quality of life options and doesn''t remain faithful to the original vision of the game.\n\nJust get OpenRCT2.', 'Very Positive', 90.12, 19.42, 3.73);
INSERT INTO reviews VALUES (23140, 683940, 176, 'Fantastic game, started playing the android version about 5 years ago. The mechanics, whilst not like reality, really get you into the game. My only criticism is that the steam version seems to make interviews twice as expensive, which does make games less interesting and can make higher difficulties feel slightly futile.', '\r\n---{ Graphics }---\r\n☐ You forget what reality is\r\n☐ Beautiful\r\n☐ Good\r\n☐ Decent\r\n☐ Bad\r\n☐ Don‘t look too long at it\r\n☑ MS-DOS\r\n\r\n---{ Gameplay }---\r\n☐ Very good\r\n☐ Good\r\n☐ It''s just gameplay\r\n☑ Mehh\r\n☐ Watch paint dry instead\r\n☐ Just don''t\r\n\r\n---{ Audio }---\r\n☐ Eargasm\r\n☐ Very good\r\n☐ Good\r\n☑ Not too bad\r\n☐ Bad\r\n☐ I''m now deaf\r\n\r\n---{ Audience }---\r\n☑ Kids\r\n☑ Teens\r\n☑ Adults\r\n☑ Grandma\r\n\r\n---{ PC Requirements }---\r\n☑ Check if you can run paint\r\n☐ Potato\r\n☐ Decent\r\n☐ Fast\r\n☐ Rich boi\r\n☐ Ask NAS', 'Mostly Positive', 79.55, 31.67, 2.02);
INSERT INTO reviews VALUES (23142, 684000, 159, 'She murda on my wood till I ocean', 'Its with a heavy heart that I give this game a thumbs down. \nWith the recent rise in Early Access titles being in development for years without releasing comes a weird exception in the name of Wooden Ocean that I personally feel should still be in early access. The amount of bugs ive encountered in my run were unaccountable. Complete systems that aren''t fully fleshed out. Areas of the map that just exist and do nothing or crash your game. Dear Leif, If you are going to add something new to the g', 'Overwhelmingly Positive', 97.48, 0.98, 27.15);
INSERT INTO reviews VALUES (23144, 684050, 227, 'good lore', 'Wilx100% (Feb 8, 2022) - Honestly not even game, just clicker that lags the shit out of your PC because of the amount of achievements you get per click. I got it because I like seeing my achievement number go up like a neanderthal, Number up me happy. But I also feel kind of guilty like these achievements were not satisfying, if there is a way to get rid of them I would in a heartbeat. There are also 2 of them in total, so I''ll be posting the same review on all of them. I would rate this disgust', 'Very Positive', 80.18, 14.83, 7.47);
INSERT INTO reviews VALUES (23153, 684270, 198, '', 'This game will often times present you with modules that don''t work as described.  It apparently does this as a sort of "gotcha".  Which doesn''t work well in this style of game I feel.', 'Very Positive', 88.89, 0.00, 2.40);
INSERT INTO reviews VALUES (23160, 684410, 2272, 'I am now 100% sure that whoever builds the bridges in my country has never played this game before.', 'This game can be fun if you like the bridge constructor games. If you are a portal fan and want to play this because you see it''s portal branded, don''t. It''s not even close to the portal gameplay style. It only appeals to a certain amount of people. It is also too difficult for a normal player discovering this game. It gets too frustrating. I somewhat enjoyed this game but overall it''s not very good in my opinion.', 'Very Positive', 90.54, 1.68, 5.78);
INSERT INTO reviews VALUES (23163, 684450, 1747, 'I''ve started using this simulator again to prepare myself for 2028.', 'Broken, do not buy.\n\nSurviving the Aftermath is a great game let down by it being completely broken. I lost every save so far since it just will not load.\nAnd on top of that, the main quest bugged out for me. I have to build things in the desert biome... and I do not have such a biome on my map.\n\nSadly, I am quitting this one. Do not repeat my mistake and pour in 8+ hours into a game that can''t even load its saves.', 'Mostly Positive', 72.58, 289.67, 8.05);
INSERT INTO reviews VALUES (23171, 684580, 765, 'Haven''t played the previous game, but this one seems to be fairly simple in nature. You buy/craft items, mark up the price, and sell it. Combat is just as simple where you swing or shoot and probably get hit; if there is any sort of special ability then I haven''t progressed far enough to unlock it, but I don''t see anything of that nature given the skill tree. I also haven''t tried ranged combat yet. There are multiple skill trees and you can progress in each of them independently, meaning if you ', 'I was just like many of you out there. Looking at the game and its reviews wondering to my self "it can''t be that bad right?" well, I can tell you all out there that this game is exactly what the reviews say it is. Its an unfinished abandoned game that lacks the proper polish it needs to even be worth two dollars alone. Tried to play with my friend, but in the end we simply could not connect/couldn''t even find a multiplayer option. If you and your buddies are looking for a game to play, this isn', 'Mixed', 57.65, 15.13, 0.62);
INSERT INTO reviews VALUES (23175, 684680, 110, '‎', 'Hey guys, if you have issues with spinning imagery(get nauseous easily) or even a minor issue of flashing lights. Don''t play this. BIG ON THE THE FLASHING LIGHTS WARNING. (no you can''t turn off the background)\n\nOtherwise, its a short game (recommend to get it on sale) with 5(+bonus) levels.', 'Very Positive', 87.27, 167.03, 1.00);
INSERT INTO reviews VALUES (23196, 685240, 443, 'i diddled alright.', 'Ok, so hopefully my review will help someone else avoid making the same mistakes I''ve made. I first purchased Paradiddle from the Viveport store for my Vive XR Elite. I found it interesting but I wanted to be able to have a kick pedal and hi-hat pedal to make it more like playing a real drum set. While looking into doing this I discovered a YouTube video using a Roland kit and Paradiddle with MR. I decided to buy a Roland kit as I always wanted one anyway and I really wanted to try Paradiddle wi', 'Very Positive', 92.33, 9.30, 0.60);
INSERT INTO reviews VALUES (23203, 685400, 200, 'I am begrudingly changing my review to Recommend after playing a bit more and realizing how addictive the RNG aspect is. However, my criticism as follows still remains relevant:\nSee, the mechanics are cool, the aesthetic is crunchy and all but when I die over and over for no fault of my own but because the game just cannot accept aim input properly, there is just no reason to play it.  I cannot care about any progress or finding new upgrades and such when I know it just won''t matter because I am', 'The game''s art is super cool, I love the aesthetic but the gameplay loop is a little stale after the first few rounds through. I got very frustrated with the projectile that fires from your soul gun, it always manages to weave its way past literally every enemy even if you have a whole swarm chasing after you. This issue also plagues the axe as well, seeming big enough to hit a few enemies but always falling short, not letting you hit that enemy you think you killed, only to be damaged by that s', 'Very Positive', 94.50, 2.63, 1.30);
INSERT INTO reviews VALUES (23209, 685670, 149, 'its probably good but its not the bachelor route so i don''t care', 'I bought this game to support Ice Pick Lodge alone, and on that basis I would recommend it if you want to support their efforts in game design. (Which are badass and impossible to find elsewhere.)\n\nThat said, I can''t really recommend this game as an outsider. Personally, it felt like the dynamic between the friends and Asya bordered on toxic and cringey. I had to stop because I didn''t understand why grown adults couldn''t have a conversation without a vague flirtation or a slight undercut embedde', 'Overwhelmingly Positive', 96.64, 0.68, 3.42);
INSERT INTO reviews VALUES (23210, 685680, 145, 'The same cringy tropes, with the same boring, "tell me you''re not a lesbian without telling me you''re not a lesbian" sex, ergo writing that never aspires to go beyond merely adequate, but unlike most other Winged Cloud titles, the characters here manage to offer at least more than an oil stain''s worth of depth, and when combined with an unexpected dose of much-welcome meta commentary that, while deeply ironic (this studio hasn''t really learned anything after peaking in 2016), makes for a rare Sa', ' Game is 100%''d at time of this review. \n 2/10 \nA bit longer than the last one I played, and actually had options for the story which made you have different possible routes and stories with additional playthroughs. Still was very quick as only 2 routes were needed for 100%. Yet again I didn''t bother with actually listening to or reading the story, just skipped through and saved at decision points. This game actually has trading cards though as well, so thats nice. The theme with Sakura Games th', 'Very Positive', 86.90, 2.73, 0.85);
INSERT INTO reviews VALUES (23211, 685690, 213, 'I bought my VR headset 2 months ago and I''ve been looking for a good singleplayer shooters. This is the best VR shooting game so far. Definitely worth the price', 'I dig the colorful graphics and the lightheartedness of this game.  It has some personality and charm.\n\nYet as a game, it becomes very tedious.  I''ve played through the first three levels and every single one of them overstayed their welcome.  It''s incredibly repetitive and goes on too long.  My fingers were sore from constantly having to pull the trigger.  Even with automatic weapons, my arms were sore from holding them up.  Some games are great b/c you get a work out from them, this is just an', 'Very Positive', 86.38, 1.37, 1.00);
INSERT INTO reviews VALUES (23233, 686200, 1942, 'I shot the sheriff, and the terrorists, but I did not shoot the hostages.\r\n\r\nReally though its tactical Broforce, this game is awesome!\r\nPlays fantastic on the steamdeck also!', 'This game will be fun for a time and then it will become a challenge of how much annoying bullshit it can try and hit you with before you just go, "I know how to get three stars on this, but it won''t be fun, so fuck this, I''m done"', 'Very Positive', 93.87, 11.45, 7.52);
INSERT INTO reviews VALUES (23235, 686260, 461, 'This is a game I was longing for a long time! Oh, boy, where do I start. They just don''t make this kind of games anymore. I have just finished 5th mission (where you kill carter). I spent like 4 hours figuring out how to take 3(THREE!!!) opponents with this b*tch-ass super tank until I have annihilated them all in 15 minutes. This warm feeling, this adrenaline rush.... I can''t say it''s better than s*x, but it gave me the good old thrill I used to have playing Dune as a Harkonen =) You just oblit', 'Buy C&C Red Alert 3 instead :)', 'Mixed', 58.57, 19.12, 1.13);
INSERT INTO reviews VALUES (23242, 686440, 215, 'One of the best childhood game', 'Not enough gay rape, 0/10', 'Very Positive', 91.63, 1.68, 7.35);
INSERT INTO reviews VALUES (23256, 686680, 557, 'made a pc and went bankrupted 11/10', '"Computer Tycoon" is a game with a great concept where you run a tech company, design computers, and navigate the tech industry. This idea is exciting and has a lot of potential.\n\nHowever, the game''s user experience (UX) and user interface (UI) are big problems. The game is hard to navigate, and it’s not clear what to do next. There’s little feedback on your actions, making it confusing and frustrating. The menus are cluttered, and important information is hard to find.\n\nDespite these issues, "C', 'Very Positive', 85.10, 24.30, 1.28);
INSERT INTO reviews VALUES (23259, 686770, 130, 'I love this game. It is one of a handful for which I have all the achievements. I kept coming back to it for a few years. Everything is simple and smooth in design while producing complex and interesting gameplay, which is the perfect combination. The animation and sound design are absolutely fantastic. There are multiple difficulty levels and many different leaders with different layouts and styles, so you can make it as hard or easy as you like. The developers are responsive on Discord.', 'You play 30 min,  a small mistake and you lose 60 min of game, because everything is so expensive than it would make your match. However, all is full of silly things to do, so you don''t see much important things anywhere... maybe just boring', 'Very Positive', 93.08, 140.35, 17.22);
INSERT INTO reviews VALUES (23260, 686810, 57541, 'I met this guy from Mississippi, we had a good conversation while pushing up to the enemy for about 15 minutes. He and I alone snuck through their trenches and took them out without being detected. He told me about his kids, his wife, and the stuff he got his kids for Christmas. As we finally got to the frontline I watched him be blown up by an artillery shell. 10/10', 'The game was great, i was enjoying it so much. Great community, friendly people who would help you if you re new to the game and would sometimes even show you the mechanics and the basics of Hell Let Loose. But then suddenly on 2 of january Hell Let Loose had gone free on Epic Games. Now i need to wait and 15mins to just join the fricking  queue. And what is even worse is that half of the lobbies are players who claimed it on epic. Which is not bad but more than an half of them are stupid, dumb ', 'Very Positive', 84.54, 52.30, 52.13);
INSERT INTO reviews VALUES (23262, 686900, 138, 'Ooga booga', 'Stupid fucking shit. Deserves no awards. No fucking point either. Dumbass game that should have never been made.', 'Mostly Positive', 75.36, 2.32, 0.97);
INSERT INTO reviews VALUES (23266, 687260, 564, 'In my opinion this is a game that''s only worth to buy during sale. Overall it''s an interesting experience and I don''t have any complaints about the story or gameplay, plus I really love the music, art and atmosphere. I genuinely enjoyed playing this, I think it''s beautifully done but wish that the game was a bit longer, since due to lack of gameplay/puzzles I believe that at least the story could''ve been more extensive.\n\nHowever, as MANY people have already mentioned, this game unfortunately suf', 'I really wanted to like this game, but even after seeing all the endings, nothing stuck with me. The S.P.I.N. system is really underutilized; it felt like only two of the attributes had any effect on the gameplay. The characters do not feel fleshed out and there''s just not enough here that satisfied me. I also wish that at minimum you could use the Space bar to advance text but no, your only action is clicking the mouse.', 'Very Positive', 86.17, 11.58, 9.73);
INSERT INTO reviews VALUES (23280, 687540, 176, 'Was entertaining watching the tasty games on youtube when I was a kid and now I only bought them for nostalgia and for the achievements.', 'This game is fun on a normal playthrough. However, don''t play this game if you''re an achievement hunter. Many of the hardest achievement require beating every level in the game by a steep time goal, so steep that some medals can only be earned by spawn RNG.\r\n\r\nStandard Game Play (7/10)\r\nCompletion (3/10)', 'Very Positive', 84.09, 21.57, 33.28);
INSERT INTO reviews VALUES (23290, 687750, 150, 'Are you still waiting for the release of Yandere Simulator?', 'Why did I buy this.', 'Mixed', 63.33, 3.00, 0.12);
INSERT INTO reviews VALUES (23292, 687800, 511, 'It starts SLOW. VERY SLOW. \r\n\r\nYou''ll die in Cambrai so, so, so many times. but then you start finishing that part, and racking up substantial gains each run and uncovering new paths and gear and etc. that''s when it gets good. \r\n\r\nUNFORTUNATELY, that never speeds up the early game. yes, you can kill guys faster and spend less time thinking about your choices, but unlike something like say... Rogue Legacy or even Nethack or something, there''s never any skipping the beginning of the game. So you''r', 'I have played 100 hours, am at Level 1000 and am following guides. But I still have 0% chance to hit Ruffin, Even after I successfully stunned Ruffin with a shield bash: 0% chance to hit. That is just wrong and unfair.\n\nThere''s a difference between challenging and frustrating. This one here is frustrating.\n\nAnd there''s another really stupid "feature": When you get a choice, the question is not displayed with the choices. So when you skip the dialogues you often have to answer choices without kno', 'Very Positive', 84.93, 210.20, 122.52);
INSERT INTO reviews VALUES (23299, 687920, 203, 'Tropical Liquor is a good visual novel game with a minigame and a beautiful story. The graphics are nice and the soundtrack is Chill and relaxing... I recommend it!!! 🍹💗', 'Everything in this game is so incredibly slow.\nThe transitions are actually painful to sit through, the text is slow without an option to speed it up, the dialogue is boring and bland... not worth the price. Maybe if it''s ever on sale and you have more patience than the average person.', 'Mostly Positive', 70.44, 8.08, 1.00);
INSERT INTO reviews VALUES (23305, 688060, 724, 'I dont recommend this if you like simple colony sims. This game is ridiculously complex to learn and navigate, nearly dwarf fortress tier. Personally its ruined it for me and i cant bare it. But, i do see theres alot of quality here.', 'the game needs a proper tutorial and introduction, otherwise you don''t know where to start from or how to operate anything, maybe also the issue is in UI itself, but given a starter guide can solve this problem.', 'Very Positive', 84.67, 1.85, 0.15);
INSERT INTO reviews VALUES (23308, 688130, 3782, 'i like to jerk off with sandpaper\r\n', 'I have beaten Getting over it with Bennett Foddy 50 times in 11 hours total. I have 22 hours in this and have only gotten halfway through the first level. It''s not fun, it''s not addicting like getting over it, and I don''t enjoy anything about this.', 'Very Positive', 85.56, 60.85, 137.73);
INSERT INTO reviews VALUES (23309, 688140, 128, 'Great game, Captures the feeling of the original, just beautiful work.  Didn''t know they sold spinners, will look into getting one if they add support.  If its not in there would also dig an ''old school'' mode to be able to go to pure vector look now and again, but as it is now it satisfies just like the original.', 'Controls and Music ruin it. Lack of mouse controls is not great. But on top of that the joystick controls seem to have an annoying inertia to it in order to kinda poorly emulate fighting against a trackball''s inertia. But you never get the precision of a trackball or mouse, so clearly that doesn''t work out. The visuals are generally pretty great and the gameplay is pretty timeless. It doesn''t stray too far from the original formula, doesn''t offer multiple modes of various modernity like some ret', 'Mixed', 67.97, 2.10, 0.52);
INSERT INTO reviews VALUES (23320, 688420, 4807, 'after playing this game I went to our coastal area with cliffs and tried to make the viking fog horn noise with my voice, I also tried to make the flute noise. People get scared and think I am crazy, which of course I am.', 'The game really lacks content.\nThe idea is cool, and the mechanics are solid,\nbut compared to other indie titles, it falls short in terms of content.\nIt''s like:\nFaster Than Light but with only 3 gun options — only 3 unit types\nSlay the Spire but with just 8 relics — only 8 possible equips\nHades with only 13 boons - only 13 traits (most of them is minor buff to speed or smth like that)', 'Very Positive', 93.95, 24.20, 1.48);
INSERT INTO reviews VALUES (23333, 688740, 136, 'Fractured Minds isn''t a game that''s made to make you feel comfortable or make you enjoy it. I think that as a piece of art, I can understand the intent and emotion behind it, however, with all the games out there about mental illness, depression, and anxiety, I don''t feel like this game does the best job at capturing what that feels like while also having something to say. 3/10', 'Game is completely unplayable. As soon as you gain control, the camera spins to the right endlessly. Controller or keyboard, there is no stopping it. No solutions in discussions either, and I''m not the only one who has this issue. If I didn''t get this as a bundle I would refund it immediately.', 'Very Positive', 87.50, 0.50, 0.15);
INSERT INTO reviews VALUES (23380, 689790, 136, 'Just bought it to look cool... lol', 'tried using it 7 times, it crashed 5 of those, for something of this price tag, this is simply a waste, asking for a refund', 'Mixed', 63.24, 36.22, 1.55);
INSERT INTO reviews VALUES (23384, 689900, 211, 'Selected CAT mode first time... Imagine my look on my face... ♥\n\nOther than that it''s pretty OK, the only annoying thing is that when you click on the hotspot you got ALL 3 options available to you interact/examine/TalkTo and that does not mean you can do either of them that''s a confusing bummer for the game.\n\nAnd main actor''s voice is meh (for English), jokes are fine but voice cannot express it in a fun way.', 'I really wanted to like this game and I did complete it, but overall it was a frustrating and lacklustre experience for me.\n\nSome of the game play is extremely frustrating. The character interactions are often unhelpful and there are lots of missed opportunities to have them help push the story forward or give useful information. I didn''t find the puzzle logic consistent. Perhaps I am used to more complex games, but I was assuming I had to, let''s say, create something by doing multiple tasks or ', 'Very Positive', 89.57, 4.33, 8.27);
INSERT INTO reviews VALUES (23385, 689910, 335, 'Another Lost Phone is a very good little game where you find Laura''s phone. Check her messaging, emails, photos, etc... to find what happened to her. The puzzles are not to difficult, the stoy is good and the grapchics are nice. For his low price, it worth it and I highly recommend it!!! 💗📱💗', 'Easy achievements, it''s more or less the same as the first one.', 'Very Positive', 91.34, 28.08, 0.80);
INSERT INTO reviews VALUES (23386, 689980, 172, 'If you ever sold cars for a living it is fairly close. Love the game it is a great way to pass the time.', 'abandoned', 'Mostly Positive', 72.67, 27.07, 16.80);
INSERT INTO reviews VALUES (23388, 690040, 5275, 'It''s like the first SUPERHOT, but more challenging and with some power-ups to change up the gameplay. Would''ve been a 10 if it was just that. It was still really fun but the levels were very repetitive after the first few hours. Not only that, but the ending required the game to be on for 2.5 real-time hours (used to be 8 hours) just to unlock a very anticlimatic resolution. Still a solid game with fun gameplay nonetheless, 7/10.', '"more, more, more more" we get it, you added more. too bad half of the more you added has zero purpose or is obsolete by other "more." this rougelike approach they took for the sequel is an endurance test on how long you can play the same 15 levels over and over and over again with random upgrades sometimes thrown that MIGHT help you. if I have to complete 15 levels in a row with two hearts, why would i EVER pick a goomba stomp over a heal. its like this game encourages you to play safe instead ', 'Very Positive', 84.66, 9.42, 9.38);
INSERT INTO reviews VALUES (23395, 690140, 167, 'O jogo é bem simples, baixo orçamento, porém te entrega algumas horas de estratégia. Não compre esperando um grande desafio mas algumas horas de diversão descompromissada.\r\n\r\nThe game is very simple, low cost, whatever you gain some hours of strategic play. Don´t buy thinking in a great challenge but in some hours of uncompromissed hapiness.', 'This is the really good start of a game that needs to be longer, more complex, and more compelling. There are a lot of tactical RPGs out there, you''re better off with almost any of them.', 'Mixed', 65.87, 12.55, 1.98);
INSERT INTO reviews VALUES (23405, 690370, 105, 'I was Post Number 25105 that requested you add the tagline "Make the game your own: Mods = Gods".', 'Devs promised to make Skirmish AI and never delivered.\nYou essentially have 9 missions (and quite boring ones) and that''s it.', 'Mixed', 62.86, 0.15, 4.77);
INSERT INTO reviews VALUES (23408, 690420, 170, 'They gift me this game for my bday \n\nbest gift \nVery dank \nApproved\n10/10', 'theres no shrek', 'Overwhelmingly Positive', 97.06, 0.42, 0.60);
INSERT INTO reviews VALUES (23412, 690530, 197, 'Alright, I recommend this game, but not in early access.\nit''s quite like Dead by daylight. But it got some new idea. Is good but not good enough. Terrible match system,  terrible optimise, terrible Anti-Cheat and most important stiff action.\n\nFor the people who NOT LIVE IN CHINA MAINLAND: if you want to play this, must change your download zone to China. \nSteam-Setting-Download-Download Zone\n\nOthervise you need wait for thousands years to play 1 round.', 'Selling DLC while the game is still in a bad state in early access. Just a huge red NO for that alone.', 'Mixed', 58.38, 33.33, 0.40);
INSERT INTO reviews VALUES (23414, 690560, 103, 'It is now 2025 and the creator of the game mentioned that he was working on a save progress in 2018 and I''m wondering if the creator died or just has ADHD and moved on to another project.', 'Unbalance and hard to see if items actually work', 'Very Positive', 85.44, 15.22, 33.93);
INSERT INTO reviews VALUES (23420, 690640, 2769, 'The graphics are great, the walking forward never ends while playing...\n\n10/10', 'You guys reeeeeally gave up at the end. Also, fix your checkpoints - not a single person enjoys being stomped by a battle, only to have to go back and do a janky-ass physics puzzle again. I give this two thumbs down, and may god have mercy on your souls.', 'Very Positive', 93.36, 15.60, 14.48);
INSERT INTO reviews VALUES (23425, 690790, 17105, 'Driving the Audi quattro group B is like trying to wrestle a gorilla juiced on viagra and cocaine', 'what a joke. Finally finished the first rally competition and while in a loading screen right before i get my rewards i get a message telling me my "team rally season has been reset due to server synch". I got no rewards, no money, and the 5 hours of racing has all been reset, so no progression allowed. Why the hell does it need to constantly connect to their servers? Im racing against the games ai.', 'Very Positive', 89.01, 57.97, 5.85);
INSERT INTO reviews VALUES (23427, 690810, 440, 'Although control of quest 3 controller is a bit hard at first. After learning I completed the game. It''s a great game and onsale it''s unbeatable. I really enjoy all the modes it offer.', 'Awful game. \nFirst, the game doesn''t save your progress(!), you need to beat in a single playthrough. Are you out of your mind?\nSecond, I can''t even finish the game, it gets stuck after the third mission (a lot of people with the same issue)\nThird, the game itself is complete garbage, you just shoot teleporting zombies in small arenas to open a door to another arena\nDon''t waste your money on this thrash\n', 'Mixed', 50.45, 8.95, 0.48);
INSERT INTO reviews VALUES (23429, 690830, 9374, 'Don''t know what to write for a review. But I just can not stop playing this game. Been a gamer since i was 7 which started with a Commodore 16.\nWent on to play The Settlers, Civilization and Sim City on my Commodore Amiga 500. I like the tinkering, building, tweaking, buying and selling. \nExcept for Sim City I never liked the military part of these games and that is why i cannot STOP PLAYING FOUNDATION.\nI do not think this review helps anyone.', 'Amending this review to say that I think a great deal of my issues have been due to bugs. I have had to abandon two cities because of them. The first city seemed to place an arbitrary cap on wheat production. No matter how many farms I had, I was only able to produce 100 wheat. Bizarre. Apparently there is also an issue w/ game speed impacting production quantities. Astoundingly terrible bug if true. My second city I just sort of gave up on after the armory resource drop down stopped working ent', 'Very Positive', 85.31, 187.30, 82.07);
INSERT INTO reviews VALUES (23440, 691160, 339, 'This game is one of the best VR Music games out there\n I guarantee this purchase do it', 'Leading Global VR Gaming Studio, Award Winning Immersive VR Games.\nEvery their game is abandoned and barely functional, don''t ever buy anything from them, even for free it''s not worth it.', 'Very Positive', 91.15, 14.90, 0.18);
INSERT INTO reviews VALUES (23446, 691280, 235, 'It feels like a short version of the Dark Souls series. However, its original systems and fresh experiences make it an enjoyable game that transcends being merely labeled a mini Dark Souls.', 'I really wish I could like this game. I managed to beat all 8 bosses, except the final one. It''s just too punishing. I like challenges, but this is actually masochistic. I like to have fun when playing a game. Challenges should have solutions that aren''t just based on pure skill and perfect timing for all inputs. I get that final bosses should be hard, I have played all Dark Souls games and Elden Ring. I love those games. This is not that kind of game. The challenge is so steep that I''m willing ', 'Mixed', 61.70, 4.00, 4.47);
INSERT INTO reviews VALUES (23447, 691320, 408, 'I ain''t american, so this is the closest I can get to a gun range sim (It''s kinda arcadey but fun). Get it on sale.', 'this is actually fucking awful, its not even funny. the inaccuracies on most of the weapons are completely unacceptable and cant be excused as you call yourself "the ultimate virtual weapon simulator."', 'Mostly Positive', 75.00, 4.87, 0.73);
INSERT INTO reviews VALUES (23451, 691450, 1263, 'spoilers, fun game with fun mechanics and fun deaths, love the balancing of insane looney toons comedy & actual serious topics handled with respect. however replaying it as an adult i’ve realized i’m not too fond of the steven universe redemption of a pedophile because he got bullied as a kid', 'i liked base game and truth route fucking ruined everything and im not even gonna put spoiler marks for it but why in the FUCK does the rapist get a "redemption" and the redemption in question being that he was just an incel so its okay that he SA''s and murders girls mhm yea he really earned that hug \n\nyea he did not deserve the bullying\nhe deserved worse\n\nthe remaster shouldve cut that part completly and then it wouldve been salvagable but nope, developer doubles down on that, what a shame', 'Overwhelmingly Positive', 95.80, 3.27, 4.15);
INSERT INTO reviews VALUES (23462, 691690, 1073, 'What a HUGE improvement. The major update has turned this into such a good tactical combat game. I went from 5 hours played with multiple restarts and frustration to nearly 15 hours played nonstop. It was hard to stop playing long enough to type this review. Really nice job devs.', 'Look, I got this a while ago and bounced right off of it.  When I saw that it was majorly updated, I checked it out again.  The update is a huge improvement to the actual combat and gameplay.  I''ve had fun playing through the fights.  The art and animations are great.\r\n\r\nHOWEVER, I''m 50 years old.  I have been a gamer for a very long time.  This has to be the most poorly written game I have played.  Sometimes it makes sense.  Most often it does not.  Interacting with NPCs is completely bewilderi', 'Mixed', 66.92, 46.18, 14.72);
INSERT INTO reviews VALUES (23467, 691770, 160, 'DAD! I want to play sengoku rance!\nwe have sengoku rance at home ;V\nSengoku rance at home:\nWell... for me this game better than sengoku rance\n', 'The combat varies between being too easy until it eventually reaches an insane difficulty spike.\nDialogue is extremely lame, story is boring, characters have nice designs but are mostly the same and lifeless.\nIt''s decently fun as a strategy game until it reaches the point where it''s unplayable.', 'Very Positive', 86.88, 87.90, 15.15);
INSERT INTO reviews VALUES (23469, 691830, 180, 'Having played the Avernum games on and off for almost 20yrs I always find myself enthralled by the world development and progression from each game to the next. I may go a year or two between playthroughs but it always draws be back. fun little games to sit back and enjoy. Avernum 3: RW was, has been, and is a pleasure to play and just freely roam the world, excellent for those who love to role-play their game characters. Can''t wait to see the remake of Avernum 4: Greed and Glory when it gt''s re', '\n\nI would skip this if you enjoyed Spiderweb Games of old. I played the Exile series many years ago after stumbling upon it on AOL Shareware file sharing. Bought the game disks. Played them all. I even played Nethergate and enjoyed that. Maybe I''ve just gotten old but this was, as the game describes itself towards the end, "a cynical rewrite." As a programmer, I constantly found the lack of feedback irritating. I had to guess if I was on the right path and then redo, redo, redo onerous puzzles. ', 'Very Positive', 86.67, 472.18, 79.08);
INSERT INTO reviews VALUES (23479, 692100, 358, 'infliction is a short horror game where you investigate what happened in an eerie house . i gotta say the atmosphere of this game is crazy good and game doesnt uses cheap jumpscares like horror games these days . its really amazing to experience such a different type of horror game where u constantly feel u are always seen . it is a must play experience.\r\n\r\n9/10', 'I''m honestly too exhausted with this game to give it separate short and long review so I''m just gonna be straight with you on this one, it''s boring. At first I was intrigued, there were a few moments where I was able in that good suspension of disbelief mode, and it felt like a good start. Somewhere along the way it felt goofy and got frustrating. The game''s mechanics like hiding, polaroid camera photos showing hidden clues, and the mirror world feel really sparse and under-utilized. I think I h', 'Mostly Positive', 78.77, 4.43, 1.72);
INSERT INTO reviews VALUES (23498, 692840, 451, 'This game is great as long as you\nGet it on sale\nHave low expectations\nEnjoy janky games\nLookup the file to get the kickstarter items\n\nIf you fit all of these criteria you can have a good time with it.', 'Don''t waste your money. Some would have you believe that patches applied to this game have made it playable since launch, and it certainly seemed so for the first few levels, I was having fun. Then the problems started in the Underswamp. The game for some reason no longer recognised my character possessing the Abyssal Key I acquired in the Keep, meaning I could not claim my reward from the mediator, and the next objective wouldn''t trigger. I was able to use this transient "key" to get to the low', 'Mixed', 41.69, 13.63, 12.35);
INSERT INTO reviews VALUES (23499, 692850, 10583, 'It took a little while for the developers to get there, but they made it. This game is worthy of the prestige of Castlevania. It has beautiful art, fun gameplay, and a story that you can sink your teeth into. Add Shantae-esque transformations, and side characters that you actually care about, and this game is absolutely worth your money.', 'This is not a review about the game itself, I actually really enjoyed playing this game. But I felt I had to leave a negative review to show that I''m quite pissed after recently finding out that my previous 100% achievements for this game was removed from me, all because the developers decided to not only add more to the game, but to also lock those behind paid DLC that is apparently a) not like the rest of the game, and b) not very well-made.\n\nYou can call me petty all you want, but it''s not of', 'Very Positive', 93.36, 17.17, 37.38);
INSERT INTO reviews VALUES (23500, 692890, 12208, 'Map design and exploration is where this game sets a bar above most others. I''m tired of procedural generated roguelikes. Hand crafted, quality levels like these are what devs should aim for. A solid 15-20 hour game is much better than a dull 100 hours.\n\n\nPlus big numbers feel good.', 'tbh this game is *really* close to being amazing, but there''s just too many places it falls short. Base combat system is fantastic, but frankly that''s it. Remarkably predictable for a roguelike, as the stages don''t actually change, just *some* of the enemy layouts. A lot of the weapons are just terrible no matter what build you''re running. The player characters have way too much in common, with the exception of one which is admittedly a breath of fresh air but comes at the cost of the most obnox', 'Overwhelmingly Positive', 96.03, 21.60, 53.13);
INSERT INTO reviews VALUES (23526, 693580, 212, 'Bring glory to your gobo tribe within this colony sim game!', 'yet another unfinished game on here.... im fed up being a beta tester for all these companies\r\nI miss the days when people would work on their OWN GAMES then put them on the market \r\nnow a days we the consumer are also the beta testers and game designers IM DONE WITH IT', 'Mostly Positive', 71.70, 19.68, 1.55);
INSERT INTO reviews VALUES (23529, 693700, 138, 'This is definitely a programming zachlike. But it differs from a lot of other programming games by not being completely low level (you get integers instead of binary signals) but also not high level (only very simple tools, e.g. you only have an increment tool and not an adder), so you''re solving low-level problems, but different ones than you might be used to.\r\n\r\nIt has a good ramp up on difficulty--reasonably challenging but in the end doable (took me ~40 hours to 100%). For the final puzzle I', 'Fiddly and un-fun. Not Zach-like at all.', 'Very Positive', 86.96, 49.83, 3.33);
INSERT INTO reviews VALUES (23552, 694280, 2407, 'It''s fun and incredibly easy to pick up and get into.\r\nYet, there''s one MAJOR issue that somewhat does drag the game down a bit, it really lacks weapons. There''s like 10 weapons if you don''t have any DLCs and none of them feel nearly as good to play as the weapons from the pretty damn expensive DLCs.\r\nI''ve resorted to buying them because at it''s core the game''s really good for wasting a bunch of time in but 5 bucks for a single gun is just brutal.', 'Imagine a shooter where you don''t unlock new weapons. You start with 3 options and you have to buy the rest with real cash. GTFO with that micro-transaction Bull.\n\nGame is $50 dollars, but most of the weapons in the game are locked and require you to spend more money to unlock them. Cash grab game. Thumbs definitely down.\n', 'Very Positive', 86.12, 75.67, 4.62);
INSERT INTO reviews VALUES (23561, 694500, 707, 'Awesome classic RTS game! Has a decent campaign mode as well as skirmish and multiplayer. The graphics are a little chonky but there''s a mod to allow for some modern feature support. Plays a lot like the old Age of Empire games.', 'Loved this game growing up it was a lot of fun. I sadly wouldn''t recommend getting it anymore as it no longer works for some such as me. I recently got a new laptop and now the game won''t even open or function anymore', 'Very Positive', 88.40, 17.05, 2.80);
INSERT INTO reviews VALUES (23571, 694770, 436, 'Yay a fire emblem game where you don''t marry your sibling', 'Crash crash crash crash crash crash crash \r\n\r\nwould be a great game if i could play more than 30 minutes without a crash', 'Very Positive', 85.55, 7.30, 17.82);
INSERT INTO reviews VALUES (23578, 695050, 159, 'It''s a great game BUT it''s short and there are chapters missing many years after release so the story is a big unknown gap. Such a shame really but understandable and I don''t hold a grudge against the developers. They did a really good job with the little budget they had.\nI still recommend it though but you won''t get a complete story.', 'Just finished it and realized this game came out in 2019.... It''s 2024 and there''s no news of Chapter 2 and Chapter 3 ever releasing. If you''re down to just playing through the first chapter and letting your imagination play out the rest of the story in a "What if" scenario then by all means grab this game during a sale and enjoy it. It''s fun, the puzzles get boring after some time but overall, I would rate it an 8/10 experience', 'Mostly Positive', 74.84, 3.95, 5.10);
INSERT INTO reviews VALUES (23579, 695100, 108, 'this reminds me of don''t starve but not as much of a focus on survival mechanics. im actually a fan of the art style as it grew on me after a while of thinking early that it was rather boring and bland. everything ranges from decent to good, not really ever getting "bad" in any part of the game, but also not feeling "great" in any way either. some things are a little too simplistic and they could''ve benefited from being a little more fleshed out & complex, namely the combat jumps to mind as a go', 'The concept for this game is great, as is the art. The story gets you hooked, the characters are intriguing, and it has a very creative and interesting world to explore.\n\nBeyond that however, everything quickly goes down hill. Who ever decided that the characters should be something like 2d sprites on a 3d background, should have been shut down instantly. You never quite know where exactly you are standing and facing and swinging in regards to your foes, and the same goes for when you are trying', 'Very Positive', 81.48, 14.03, 1.22);
INSERT INTO reviews VALUES (23582, 695330, 742, 'As a person deeply interested in the topic of the archive, the base premise already resonates with me. I think the way a society preserves its history, memories and legacy is very indicative of how that society is structured and which values it upholds. History is not a given, it’s a process of writing and re-writing, at least loosely informed by the archives that hold traces of the past. But those traces aren’t a given either. Whose history does a society decide is worth recording and safeguard', 'I really like the concept of this game, but I cannot recommend it sadly.\r\n\r\nThe first level ran ok, but after getting the bike and going to the next area the lag became constant.\r\nI can''t progress past the hilly forest portion where you meet the first character because I get motion sick.\r\n\r\nI tried to fix it on and off which didn''t work, and was too late on refunding and got rejected.', 'Very Positive', 94.88, 11.42, 4.10);
INSERT INTO reviews VALUES (23594, 695600, 188, 'really great game that involves time and money. lots of different career paths including starting your own business, investing your hard earned money in the market, clothes, possessions, or even the housing market. you even have to pay taxes, just like real life. 9/10 foot hairs, recommend to all friends', 'its just rather dull and not at all fun. No notable random pop up events, just the same boring click through the same 10 or so buttons non stop', 'Mostly Positive', 75.00, 52.22, 1.22);
INSERT INTO reviews VALUES (23604, 695920, 575, 'I used the pickup lines provided and now I''m in jail', 'Im still single', 'Very Positive', 82.96, 2.45, 17.32);
INSERT INTO reviews VALUES (23618, 696140, 121, 'Odeio a Prefeitura de São Paulo', 'https://youtu.be/bPiZ7cnXp_o\n\nPossibly a lot more with four players but without that the single player experience is not much to write home about.', 'Very Positive', 85.95, 727.70, 0.22);
INSERT INTO reviews VALUES (23621, 696170, 1211, 'unironically very fun. imagine splatoon with tits. yeah thats this game', 'you can NOT play in VR. there is a "doll dress up" thing for VR bur you can´t play in VR.\n\nthe game is fun but falsly advertised as VR.', 'Very Positive', 85.30, 5.55, 0.35);
INSERT INTO reviews VALUES (23622, 696180, 332, 'Who asked for this to be ported to PC?\nI''m very glad it''s here but who was this madman?', 'Bullet Witch is a third person action shooter with a dark fantasy setting and a mix of gunplay and magic.\nThe magic abilities are creative, and the characters are well designed and stylish.\nHowever, the PC port is poor, performance feels outdated, and the combat quickly becomes repetitive.\nOverall, I’d only recommend it to nostalgic fans.\n4/10\n', 'Mostly Positive', 70.78, 13.55, 6.50);
INSERT INTO reviews VALUES (23624, 696220, 785, 'Although the Developer is inactive."for understandable reasons" this game is freaking awesome i love the concept and cant wait for more cryptids/updates.', 'it had potential if the devs didn''t cut and run leaving you with an unfinished game.  Expect 2 missions about 30 minutes each and that''s it.', 'Mostly Positive', 75.29, 33.25, 7.70);
INSERT INTO reviews VALUES (23629, 696370, 626, 'You know, I hear the servers are dead, but I didn''t really want to play it online anyways. I got this game heavily discounted, and it was absolutely worth it just to play offline. It''s got a lot of really interesting detail and effort, and I find it to be a really fun little playground. I might even try my hand at making a map, who knows.', 'ENGLISH:\nHonestly, the game has been basically dead for years now, and if you are searching for an action RPG fake life sim kind of game like this, there''s plenty of other options that are way better, with much more content and also free. I mean, my God, even when there was an "active" community it was full of toxic players that did no RP at all and more than one official admin who abused their power just because they had it (you can read other older reviews and see that for yourself), and that''', 'Mostly Positive', 77.48, 28.02, 40.07);
INSERT INTO reviews VALUES (23634, 696480, 490, 'nothing short of a masterpiece. incredible atmosphere and music, funny gameplay, and an eerie narrative that goes to some very conceptual/metaphorical yet surprisingly real places. very often like a dream, and sometimes like a nightmare, equal parts comedy and horror but never going full force into either, the result is its own unique and uncanny thing. as someone who adores esoteric videogames and has something of a musical background, this game means a lot to me. there is so much detail and ar', 'I''m not sure what I just played but I should stop buying steam badge coupon games.', 'Overwhelmingly Positive', 96.33, 4.80, 2.28);
INSERT INTO reviews VALUES (23638, 696530, 167, 'It''s good looking and has some fun puzzles, the story is unfortunately quite poor in its structure and execution, but if you like atmospheric environments it''s good for that', 'Follow "First Person Exploration and Puzzle Games" for more games like this!\n\nI''ve been trying to play through this game for years.  Every time I pick it up, I get bored or frustrated and put it down again for a few months.  It''s now been 3 years since I last played, so I''ve given up and am writing this review.\n\nFrom what I can remember, the environments are beautiful.  The puzzles are not as terrible as everyone is making them out to be, but there was a lot of backtracking and wandering to figu', 'Mixed', 66.47, 8.20, 1.88);
INSERT INTO reviews VALUES (23640, 696560, 116, 'Crazy? I Was Crazy Once. They Locked Me In A Room. A Rubber Room. A Rubber Room With Ducks. And Ducks Make Me Crazy. Crazy? I Was Crazy Once. They Locked Me In A Room. A Rubber Room. A Rubber Room With Ducks. And Ducks Make Me Crazy. Crazy? I Was Crazy Once. They Locked Me In A Room. A Rubber Room. A Rubber Room With Ducks. And Ducks Make Me Crazy. Crazy? I Was Crazy Once. They Locked Me In A Room. A Rubber Room. A Rubber Room With Ducks. And Ducks Make Me Crazy. Crazy? I Was Crazy Once. They Lo', '.', 'Very Positive', 89.66, 1.08, 6.78);
INSERT INTO reviews VALUES (23669, 697550, 933, 'Its like Diablo, meets Terraria...I like it.', 'since this went 1.0 without anymore remaining meaningful changes or updates I won''t be recommending this game. Had a lot of potential, evidently it was abandoned before that full potential could be achieved. Get on a sale if you like older school Diablo, beyond that though I can''t say I will be supporting this dev moving forward. Highly disappointing.', 'Very Positive', 83.17, 10.30, 55.10);
INSERT INTO reviews VALUES (23673, 697650, 243, 'Greatest Yaoi ever written. Congratulation Suda51, even Kojima could only dream of making something so gay.', 'Has some nice aesthetic touches but is a tedious and boring point and click', 'Very Positive', 92.59, 19.50, 0.10);
INSERT INTO reviews VALUES (23681, 697860, 128, 'fiddly, janky, and the best $25 i ever spent\r\n\r\nI wish the documentation was more thorough, but learning and experimenting has been soooo much fun.\r\ndefinitely has it''s quirks and limitations, but honestly the synth alone is worth it.\r\n', 'another steam program that looks awesome with no documentation..\nim not going to waste countless hours desperately trying to learn it and scour the internet for forums im just gonna refund it.\neverything i got out of it was very cool, very nice graphics but i cant manage to make  it do the one thing i want, saving myself the headache', 'Very Positive', 88.28, 401.33, 0.85);
INSERT INTO reviews VALUES (23698, 698260, 347, '-The concept is neat, but the execution left something to be desired. It has potential, but it didn''t quite hook me.', 'I keep trying to like this game. I just cant. Every time I go out from the hab. Something hits the hab. I then dont have enough materials to repair it. I run of oxy then die. Then when I do get enough to repair it. I dont have any materials to build the quest tutorial plant box. While Im getting the material. The hab gets hit again. Then I dont have enough materials to fix it. Then I die becuase i couldnt eat any food.\r\nRinse, repeat.', 'Mostly Positive', 78.67, 0.47, 4.32);
INSERT INTO reviews VALUES (23708, 698540, 502, 'Excellence in the tower defense genre. Grind xp, increase global skills, increase and decrease trap masteries to suit the task. Push, pull, flamer, spinning blade pillar.', 'Sweet in the beginning, but sour later on. I checked the game activities and it seems there is almost no balancing passes at all. The game''s foundation is actually fun, but it hit a point pretty early where you feel powerless against the enemies.', 'Very Positive', 92.23, 15.00, 19.85);
INSERT INTO reviews VALUES (23713, 698640, 1051, 'Sure.\n', 'Every now and then I think to myself, why don''t I give this game another try? \r\nLevel 1 - 4: This game is fun! Why do I always quit after a while? \r\nLevel 5 - beyond: Oh... That''s why...\r\n\r\nThis is just a remind to my future self: There''s no balance after level 5, stop wasting time.', 'Mostly Positive', 72.98, 2.43, 23.73);
INSERT INTO reviews VALUES (23716, 698670, 5666, 'This game is like snorting a bunch of ibuprofen and caffein pills while high and having a fever. Then trying to solve a rubix cube', 'Okay, first things first, the art and setting in this game are incredible. I''m a huge fan of Zdzisław Beksiński and Hans Ruedi Giger (who I highly recommend checking out if you''re interested in this game), and I felt like I was in a real-time art gallery of their combined works. Unfortunately, that''s the only thing that caught my attention.\n\nThere''s some gore and body horror, but no real horror or tension of any kind. The puzzles are okay; some of them genuinely gave me a headache, and others I ', 'Mostly Positive', 75.79, 2.27, 4.53);
INSERT INTO reviews VALUES (23717, 698700, 344, 'Rise of the Third Power is a very impressive SNES-era style JRPG to be made by such a small team. The character portraits look amateur, but the rest of the game is very much not. Excellent pixel work, excellent music, a surprisingly good story, solid side quests, rewarding skill advancement, and very solid game mechanics. Each of the eight playable characters has a unique skillset and none of them have a generic fight command, so you have to think through a variety of actions. There''s also a min', 'Not a bad gameplay experience but the story teeters on fan fiction (but is serviceable) until the end. Felt like a pathetic attempt at both a miserable ending and a cliffhanger. Only thing missing was the words "The End...?" Which I guess was similar to Ara Fell. Not going to pretend endings are easy, but if you can''t make a good one just do a generic happy ending. This has massive levels of oh so nothing we did mattered ever and everyone is worse off, cool glad I bothered. Only positive thing I', 'Very Positive', 90.41, 30.88, 41.65);
INSERT INTO reviews VALUES (23720, 698780, 202, 'It''s OK i guess.', 'boring piece of shit game for beta males who are too scared to talk to 3d women.', 'Overwhelmingly Positive', 98.51, 420.47, 2.57);
INSERT INTO reviews VALUES (23734, 699130, 5839, 'I initially loved playing World War Z. The co-op gameplay and the thrill of facing massive hordes of zombies with friends were exhilarating. The visuals and sound effects added to the immersive experience, making every moment intense and engaging.\nHowever, over time, my enthusiasm waned. The missions began to feel repetitive, and without significant updates or new content, the game started to lose its appeal. Playing solo also highlighted the game''s shortcomings, as the design clearly favors co-', 'It took the heart of L4D2, added pointless, grindy gamification, and basically nothing else. OK to pick up on a sale if you have a friend who will only play this game. Otherwise, avoid and play something better.', 'Very Positive', 85.25, 862.43, 21.33);
INSERT INTO reviews VALUES (23737, 699170, 3259, 'Was fun enough for me to 100% it. That means it''s good. Although rng can induce rage from time to time when you miss several 90+% hits in a row on a guy that proceeds to murder one of your own next. Comes with the genre I guess.', 'It looked like a more modern Final Fantasy Tactics but it fell far short. The dialog was pretty bad. Navigating the menus, and just the controls in general, are pretty bad. I don''t have a controller so maybe that would help. Character portraits look pretty cheesy and AI generated as well. I had to return it.', 'Very Positive', 89.44, 75.75, 0.70);
INSERT INTO reviews VALUES (23738, 699180, 357, 'Pretty short and sweet idler; it has some comedic moments thanks to the on-board computer companion. Also, has no MTX and doesn''t overstay its welcome, a good way to waste an hour or so.', 'Less than 30 minutes of actual game play, and all of it is repetitive.  You can finish it in 20-30 minutes pretty easily, an hour at most.', 'Very Positive', 93.56, 1.23, 1.37);
INSERT INTO reviews VALUES (23741, 699330, 587, 'The game is clearly inspired by Battle Brothers and other mercenary company games, and it does a pretty good job of accomplishing that. They have a decent number of classes for all of your companions and for the first half of the game I felt like that was enough. By the second half of the game, you quickly get to the point of having two of most classes and while they can have different skills between them they felt very samey. I was wishing there were more types of equipment to distinguish the c', 'So close to an awesome game.  I saw a dev say they had plans for 21 classes but felt the skills were to "samey".  But that is my major gripe with the game.  You have so few playable classes that they all feel samey due to that exact fact.  The player having the choice of options is always better than having too few options to choose from.\n\nThe game felt like it was so close to putting out a quality game but fell a few dev cycles short.  All the bones are there for a battle brothers esque game bu', 'Mostly Positive', 76.66, 59.27, 10.52);
INSERT INTO reviews VALUES (23752, 699600, 127, 'This reminded me of the things I find at cracker barrel\n', 'Dishonest Trailer:\n\nNarrator:\nFrom the creator of KNIGHTS, comes PEG—a puzzle game that’ll make you think you’re a genius... until it doesn’t.\n\n\n\nNarrator:\nNo tutorial? Absolutely. A UI that makes you question your life choices? You bet. But who needs clarity when you can spend hours figuring out the most tedious, repetitive puzzle of your life?\n\n\n\nNarrator:\nSure, you’ve got nearly 130 levels to conquer, but don’t get too comfy. Before you know it, you’re drowning in complex boards and your pati', 'Very Positive', 94.49, 0.25, 1.03);
INSERT INTO reviews VALUES (23753, 699670, 247, 'i actually loved this game and couldnt put it down till i beat it... be warned tho there is ton of wonk and a buncha jank. but i can see some thing special in this game... if they make another game kinda like this its gonna be great.... fingers crossed', '5 years ago I watched a trailer of this game and got hooked by the art style but unfortunately, I''m in that era in my life that I don''t wanna waste my time on worthless entertainment. the game does not have anything new to offer. it became really repetitive after 4-5 hours. basic level design, no story or storytelling, basic gameplay, and ... . other than the beautiful art style there isn''t any good or special thing about "FEUDAL ALLOY". Waste of money and time in my opinion', 'Mixed', 64.37, 51.92, 2.68);
INSERT INTO reviews VALUES (23758, 699740, 101, 'Over all I enjoy this game, its like warcraft 3 but with a game of thrones inspiration, the story is in my opinion interesting and the voice acting is alright, some moments its good other moments im laughing, i dont care for graphics so so my say on that doesnt matter, units are okay the base building is classical, just sad that they lost multiplayer support, so dont get it to play with friends but do occasionally binge of single player experience for a bit', 'in my case the game does not start.', 'Mixed', 54.46, 1.55, 0.08);
INSERT INTO reviews VALUES (23760, 699770, 108, 'It is very realistic and feels so real', 'keeps crashing after one minute of gameplay', 'Mixed', 50.93, 15.00, 9.30);
INSERT INTO reviews VALUES (23767, 699920, 320, 'This game truly changed my life, to live my fantasy as a despotistic AI in a dystopian future was amazing, I also got a dog in game', 'Mechanics are simplistic, scaling energy cost of passive production scales in an unsatisfing way. \nIt expects you to enjoy it like a rogue-lite game and to not mind that you are restarting over and over, but it lack in the most expected aspect of this game loop - in one playthrough unlocking something for the next one. You can probably bear with it for more time and to find some enjoyment, for me it just felt shallow.\nShallow like an undercooked game jam product - maybe because it is basically w', 'Mostly Positive', 72.81, 31.57, 0.83);
INSERT INTO reviews VALUES (23773, 700030, 1518, 'Fun slow burn crafting medieval survival sandbox. Know what you''re getting into. This CAN be the game we all thought it would be in 2015', 'Purchased this game, they shut servers done. Now they brought them back and i have to subscribe to play the game i purchased. Literal scam', 'Mostly Negative', 37.35, 35.72, 27.12);
INSERT INTO reviews VALUES (23778, 700160, 153, 'Its a nice puzzle platformer that sells itself with its deformable environment. As a platformer, the deformable platforms are indeed a unique mechanism in my opinion and it feels satisfying to move in the game. As a puzzle game, I don''t think that this features made this game stand out.\n\nThe puzzles themselves aren''t too hard but they aren''t trivial either, I bought this for a day-long train trip and it was a decent way to spend some time. For that, it''s perfect, otherwise I don''t think that I w', 'I don''t know why other reviewers say the puzzles are difficult, they are somewhat easy, also controllers are responsive no issues there as others mention. The problem with this game is that it gets boring real fast and it stays like that, at least it was super cheap during sale.', 'Very Positive', 86.27, 7.72, 1.90);
INSERT INTO reviews VALUES (23800, 700600, 7222, 'I''m giving the game a thumbs up only because I can''t go neutral. It''s fun for the most part but I can''t exactly recommended it either. It has good base building that''s easier than similar games, but that isn''t necessarily a bad thing. It''s also cheesy but in a fun way. The reasons I can''t recommend it are there are a lot of bugs, the descriptions don''t tell you nearly enough (lots of things aren''t explained at all), and the difficulty is entirely an illusion because one core system doesn''t work ', 'A soul-less copy of the first part.\nWorld-Domination-Screen just sucks. Base building is clumsy. The cool trap combination stuff: gone. Some nice new ideas (i.e. submarines) cannot safe the game...', 'Mixed', 67.88, 125.68, 10.77);
INSERT INTO reviews VALUES (23809, 700820, 153, 'Rough around the edges, but apparently it''s a small dev team (or is it a single person?) so that''s to be expected. Unique mechanics, and those aforementioned rough edges can make some parts of the game frustrating, but it''s nothing a veteran gamer can''t handle. Losing is Fun comes into play here, but the game in it''s current state (a several hours long tutorial map) is winnable, and potentially teaches you the fundamental differences between this and the million Rimworld/Dward Fortress clones al', 'Gets regular patches that change the game completely. it was nice once and currently it''s a hot mess with a lot of bugs. Don''t buy it right now.', 'Mixed', 66.01, 34.13, 54.02);
INSERT INTO reviews VALUES (23820, 701160, 8658, 'This game is brilliant, simple and quite addictive, harsh with you when learning how to play it but you ease into it after some time. The videos show what the game has to offer, so look into them when you are not sure if this game is for you, and also, dont doubt to get the DLCs that offer different play styles, they have their own different ways to handle themselves.\n\nThere is one thing that I still find a problem after playing all challenges and different play modes is: when are the devs going', 'You can destroy a game by accidentally building a wall too far out - without the ability to cancel, your builders will go kill themselves every day trying to build that wall until you run out of resources / cannot keep up with the increasing enemy difficulty. Same goes if you''re overextended and need to withdraw from a position.\n\nDev is against adding the option, because f***ing up a save over what should be a minor, common sense, reversible accident is the hallmark of great gameplay..', 'Very Positive', 90.04, 102.75, 62.13);
INSERT INTO reviews VALUES (23831, 701470, 136, 'The vinelands are back, and this time dissociatives are really starting to kick in.. Time to open that third eye wide open!\nTrip to Vinelands 2 is more of the same mazerunning extravaganza with a slightly more otherworldly protagonist and a slightly smoother gameplay. As with most of Walter''s games it is small tweaks that overall gives you a familiar yet new experience that you can slowly master over time..\nhttps://steamcommunity.com/sharedfiles/filedetails/?id=3429336470 \nIf you enjoyed bashing', 'While playing this game, I sweated 3 times, almost broke my monitor, and was close to schizophrenia', 'Very Positive', 86.03, 2.88, 4.60);
INSERT INTO reviews VALUES (23846, 701870, 219, 'I love this game. I''ve played it on and off for years. More strategy is needed than you might think. I''m so glad achievements were added :'')', 'very hard', 'Very Positive', 92.24, 36.55, 25.73);
INSERT INTO reviews VALUES (23858, 702050, 1914, 'A very family friendly Visual Novel that''s great for the kids. I would reccomend to play it with the whole family at christmas eve for a cozy experience. Same thing goes for Euphoria :)', 'This is a censored version of the game which does harm to the plot. PLEASE find a patch or an uncensored version for your better experience.\n\n寻思着趁打折来补票，结果部分CG和谐了，不是哥们儿，我都来这儿玩了还给我和谐CG？\n\nEdited: ...和谐了以后不是说单纯的游戏画面少福利的问题而是很影响剧情啊，咔了那些CG语音和脚本以后对于Saya对Fuminori的重要性的刻画轻淡了很多，负面影响玩家对Fuminori心境和选择的理解。', 'Very Positive', 88.61, 4.83, 4.85);
INSERT INTO reviews VALUES (23861, 702110, 133, 'No soccer player playable character.', 'lame... add fatalities', 'Very Positive', 92.48, 1.00, 6.10);
INSERT INTO reviews VALUES (23862, 702120, 162, 'i mean...it''s KOF...it''s better than Street Fighter ;)', 'I know this is a quick cashgrab in order to capitalize on China''s obsession with ''97 in particular, but even as such it''s still a very poor effort, especially compared with the other Code Mystics works. No training mode at this day and age is a complete dealbreaker. Even the Orochi Saga Collection on the PlayStation/Wii gives you a superior experience aside from the loading times.', 'Very Positive', 85.19, 5.43, 0.98);
INSERT INTO reviews VALUES (23881, 702670, 5997, 'In Donut County, you play as a hole consuming everything. It''s oddly relaxing and hilariously absurd.', 'It''s fun for about 15 minutes, and then it just  gets boring. Graphics are great, story is average, but moving around a hole sucking things into it endlessly gets very dull. Beat the game way to quickly for $13. At best this game is worth $3. I don''t recommend buying this game unless its on sale....', 'Very Positive', 90.70, 7.15, 1.92);
INSERT INTO reviews VALUES (23882, 702680, 323, 'If Keita Takahashi has zero fans that means I am dead', 'I would recommend this game... If you''re under the age of 12. or if you just really like something that holds your hand the entire way through. I was hoping for something a bit more "Open world" like noby noby boy or something funny like katamari, but no. It''s cute but it''s just not that great.', 'Very Positive', 84.52, 3.48, 1.60);
INSERT INTO reviews VALUES (23883, 702700, 159, 'If you have IRL friends, you''re gonna have a good time. Otherwise, sorry. Even with good online play, it''ll never be the same.', 'Not a very good game.  Insane price.  Emulate it.', 'Mixed', 52.20, 6.43, 0.50);
INSERT INTO reviews VALUES (23887, 702890, 2133, 'Maybe the real blazblue was the crosstag we made along the battle...', 'why can i play as a tank but not kokonoe', 'Very Positive', 83.03, 22.78, 0.28);
INSERT INTO reviews VALUES (23895, 703080, 38817, 'I am a 75 year old senior who is basically a technical idiot so I have found it a little daunting to follow the training as I am not overly familiar with all the terms and guides, however I plug away with a little progress each time I play with trial and error in sandbox mode and I try to follow some of the internet samples.  I will try one of the more advanced modes when I feel ready but for now I am finding it a great way to learn some of the game''s quirks and enjoy the game at the same time.', 'I really wished I had taken more stock in the reviews. This is more than a ''steep learning curve''- I exceeded the playing time for refund thresholds just trying to figure out how to build a pathway in a zoo. The  building mechanics are so unintuitive and difficult to use that I found myself looking up walkthrough videos FOR THE TUTORIALS. There''s no way to even construct the pathways and zoo layouts already in place by the game. I''m a grown adult with an advanced degree- this was not fun and I b', 'Very Positive', 91.27, 823.73, 5.05);
INSERT INTO reviews VALUES (23908, 703320, 364, 'I will hunt down every single person who writes negative comment about this game', 'Dont get unless you have played it before, i tried for 10 minutes to figure out the controls and gave up.', 'Overwhelmingly Positive', 95.33, 4.78, 0.10);
INSERT INTO reviews VALUES (23915, 703510, 324, 'The game is a masterpiece that has been forgotten. However, now that Wooden Battles Spec Ops seems to be completed, hopefully the development team will return to the original and make an update.', 'Its a fun game for the first 2 hours then you play conquest which is impossible you can have 1000 soldiers on a fort and one little green guy can mystically take the fort.', 'Mostly Positive', 77.78, 57.83, 14.35);
INSERT INTO reviews VALUES (23927, 703840, 265, 'a super squad of amazing animals, its just like im sonic', 'Game is fun for an hour or 2. I bought this because of PewDiePie. PewDiePie is washed now. Game sucks. waste of money. I''m an idiot for buying this', 'Very Positive', 82.26, 0.63, 6.83);
INSERT INTO reviews VALUES (23935, 704000, 110, 'HOLY GUACAMOLE IS THAT JEREMY ELBERTSON', 'GunHead is actually a good game, if u played the game for the duration of all achievements, it does actually became a good game, you get the same vibes from Cryptark at certain point...but its unfinished, LORD, the game is unfinished and unbalanced...repeated weapon with different names easly breakable economy, awkward physics, dumb AI, difficulty only based on numbers, etc etc...I could go on on how Cryptark is a superior game in comparison, that it was a visually simpler game with it had a nic', 'Mixed', 69.09, 3.32, 15.55);
INSERT INTO reviews VALUES (23938, 704030, 248, 'Such a shame this game is not being developed. It has the foundations to make it an excellent farm sim.\n\nIf you can get it on sale, it’s well worth playing.', 'The game is only half-finished, and development has stopped years ago.\nSave yourself the frustration and buy a finished game instead.', 'Mixed', 60.48, 11.32, 188.80);
INSERT INTO reviews VALUES (23946, 704270, 17505, 'Good graphics, nice bicycle riding and cool robot concept but a bit repetitive, bad inventory management and nothing that grips you to the story, you get bored easily ... It''s fun only for a bit.', 'So I tired to give this game a chance.  I bought it around the time it first came out.  Played about 8 hours, and lost interest.  It was so empty and the modes of fast travel are...  Lacking.  Come back a few years later...  No real difference.  They added "Events" but it''s just robots that get marked on the map.  Bunkers are completely wasted opportunities for story elements and other stories to converge to or start from.  Every town is empty, lifeless.  No one else fighting back...  It''s such ', 'Mostly Positive', 76.88, 8.32, 16.37);
INSERT INTO reviews VALUES (23947, 704300, 137, 'i think i made meth instead of a Moscow Mule, pelase help', 'idk if others had this problem but it was unplayable wouldn''t load and only crashed', 'Mixed', 59.85, 0.17, 0.48);
INSERT INTO reviews VALUES (23950, 704360, 183, 'The graphics and audio of this game (on HTC VIVE) are on the level of watching CGI movie. Literally, this is level of immersion that made me get into VR to begin with!  Game is basically moving tower defense using VR Archery vs. steady spawn wave of attackers from many different angles. And different hits to opponents do matter in the game. \n\n2 major annoyances soon begin to wear on you and will eventually make you switch off to another game after a while. 1) Cut scenes are neat...the 1st 10 or ', 'way to short. finished in under 2h!\nget it when it''s on sale....like a real sale.\nnot worth the 20 bucks.\nsorry devs, you have a nice game here, with nice mechanics and ideas....but that''s a demo at best!', 'Very Positive', 83.06, 4.78, 2.23);
INSERT INTO reviews VALUES (23953, 704450, 4845, 'So, I''d be remiss if i didn''t leave a review after 10k hours on steam... yeah i said on steam... I''ve been playing this game since it was out on CD ROM Meaning i''ve played for about 20 years or so. This game is really something else. The singleplayer story is one of my favorites all time hands down. Then you''ve got Solid DLCs that came later, Shadows of the Undrentide and hoards of the underdark both absolutely amazing storytelling. So much to find and see hidden away and multiple endings some e', 'Perhaps, I would''ve played the shit out of this game in 2007 when I was 12, but now I couldn''t force myself to complete even the first act. Of course, as with any old-school game, it has its charm, but the gameplay is too repetitive and dull: loot empty crates (with no loot system whatsoever) and fight waves of worthless enemies as a filler in between.\n\nThe story and quests were just as boring and poorly written. In the first act, while searching for 4 beasts and for the first time arriving at t', 'Very Positive', 91.02, 12045.55, 10.45);
INSERT INTO reviews VALUES (23956, 704510, 195, 'Similar style play to Rimworld and Stranded Alien Dawn but down scaled. Mercury Fallen has some bugs and I found that loading my most recent save would resolve the issue. The game also lacks the Rimworld drama and it would''ve appealed more to me if they had some enemies to attack or defend the base. Buy the game on sale, wouldn''t recommend otherwise at full price.', 'Worth it on a $5 sale, otherwise no.    Boring and really basic.   Little strategy, just resource attrition and tedium', 'Very Positive', 81.03, 22.35, 39.95);
INSERT INTO reviews VALUES (23958, 704640, 241, 'Great', 'There might be a good game in here somewhere but if there is it is buried beneath a UI straight out of 1993. I bought this game based on the excellent reviews it was getting but I definitely regret it. The resolution is terrible, the tooltips are inconsistent, and the overall aesthetic really, really, draws away from whatever gameplay there might be. I''m sorry, but I just cannot get past it. $18.99 for a game I can hardly stand to look at for more than 20 minutes is very steep. I would absolutel', 'Very Positive', 86.72, 127.62, 0.62);
INSERT INTO reviews VALUES (23966, 704860, 142, 'This is one of those games that gets extremely overlooked. The story is so beautiful and the story telling is perfect. The puzzles are tricky, but if you are there for the story, there is an option where you can skip past the puzzles. I have played a lot of point and click games, but this is one that has stuck with me for years because of how nice the story is. If you love classic point and click games, please give this one a try. :3', 'I''m not sure which was worse, the navigation mechanic, or the puzzles (or perhaps the game-breaking bug that forced me to thrice-restart after hours of play each time), but I do know that calling them ''puzzles'' is an insult to actual puzzles. Most are nothing more than guessing games, and the rest failed to be interesting.\r\n\r\nAlso, the voice acting is grating, and the story isn''t good enough to overcome the game''s many weaknesses, so do what I wish I had done and find something better to play.', 'Mostly Positive', 78.87, 13.97, 18.12);
INSERT INTO reviews VALUES (23982, 705120, 466, 'Your goal is to cause “accidents” and collect souls while avoiding angels. Simple yet addictive gameplay with fun and creative levels.', 'Game would be fun if it didn''t interrupt you literally every 10 seconds.  You spend more time clicking through Death talking to you than causing death in the game.', 'Very Positive', 84.76, 5.38, 0.52);
INSERT INTO reviews VALUES (23992, 705280, 211, 'Bouncy.', 'Personally for me, the game got super repetitive quickly. The reason for this is the combat.\n\nTo me, the the fact that there''s really only a single button for attacking and nothing more made me get tired of the game super quickly.\n\nWhile there is more nuance with timing, the combat itself just feels boring to me. \n\nI usually enjoy super simple combat that have a low bar of entry but an insanely high skill ceiling that push the mechanics to the limits (celeste, osu, crypt of the necrodancer, etc)', 'Very Positive', 83.89, 10.70, 2.50);
INSERT INTO reviews VALUES (23993, 705290, 157, 'Looks cool but a bit short.\r\nReccommend waiting for a discount.', 'I don''t get it.', 'Very Positive', 84.08, 1.13, 0.32);
INSERT INTO reviews VALUES (24026, 706020, 505, '9 / 10\r\nGreat, but there are lots of flawed decision making. Eg. finite resources, Permadeath, and a slilly sequence full of jank where you have to risk everything on jumping from ledge to ledge right at the end of the game!', 'Would have been interesting without all the demon crap. Theme is just too dark', 'Mixed', 63.56, 29.98, 0.72);
INSERT INTO reviews VALUES (24047, 706560, 440, ' jimmy and the pulsating mass is beautiful beyond belief. criminally underrated among its quirkyindieearthboundinspired-rpg contemporaries, it delivers fantastically in storytelling/writing and gameplay. I find myself drawn to its realistic depiction of family dynamics, of which I can say little without spoilers. humor is pointed and inexplicably fresh. jatpm squeezed laughter and tears out of me several times, sometimes within moments of each other. combat isn''t over-complicated and provides am', 'Dev won''t add cheevs cause they think it doesn''t need them. But he''s adding them to the Xbox and Playstation version. Lazy dev.', 'Very Positive', 94.09, 164.87, 1.80);
INSERT INTO reviews VALUES (24060, 707010, 674, 'Game should be called will to Grind. good game all in all.\r\nwould recommend for people that like to suffer.\r\n', 'game is ass, do not play it. AI is broken as hell and progression is long and tedious', 'Mixed', 69.88, 1401.57, 58.75);
INSERT INTO reviews VALUES (24061, 707030, 6186, 'One of the first things I did when I started playing this game was turn on the radio to a talk show. The very first caller was a furry po rn artist selling commissions. I''ve never felt so represented in a game.', 'Used to be a lovely thread "This game just isn''t that good" that over the years gathered a great deal of information *why* this game is trash.\nDev felt like deleting that discussion, so I guess we are not interested in constructive criticism therefore you wont find any in this review.', 'Mostly Positive', 72.65, 107.92, 10.48);
INSERT INTO reviews VALUES (24069, 707300, 226, 'If you give me Miku, i will give you a positive review.', 'I like Miku, but this game ain''t it imo\nThere''s several things that caught my attention, mainly some wacky translations and inconsistencies in the tutorials, e.g: the notes in the tutorial are spheres, while in-game they''re just circles\nGameplay is kinda lacking, especially considering there''s less than 30 songs in the game, including the DLC, and there''s only 2 difficulties for each song, Easy, and Hard, which ironically don''t even have a way to measure how easy / hard it is (think of star rati', 'Mixed', 60.18, 1.35, 0.52);
INSERT INTO reviews VALUES (24077, 707580, 128, 'This walkthrough game gets played EVERY time I use my headset - Now I''m on the PCL and graphically it just can''t get any better - the only problem is they have 2 other games that they wont release!! This is a VR crime in my book. Anyhow, you do have the Oculus version that''s a bit different so check that out as well.', 'Shame I had to refund this game but it literally would not work, every time the game opened it just would refuse to open in the Meta Quest interface so I would try and use mouse and keyboard to snap to full screen, it just would not go into full screen and wouldn''t even detect the motion from the hand controllers either.\n\nI imagine this game is good and that''s most of the reason I bought it because I heard it was one of the scarier VR games to play but couldn''t even get it to open so can''t recom', 'Mostly Positive', 76.56, 12.57, 0.15);
INSERT INTO reviews VALUES (24110, 708580, 208, '"...if in order to destroy Dust we also have to destroy the Oblation Board, the College of Bishops, every single agency by which the Holy Holy Church does the work of the Authority — then so be it ... better a world with no church and no Dust than a world where every day we have to struggle under the hideous burden of sin.\n\nfor dust thou art, and unto dust shalt thou return', 'demon went up my ass now i am traumatised', 'Mostly Positive', 72.12, 0.75, 3.53);
INSERT INTO reviews VALUES (24145, 709410, 109, 'I guess they had to package this into something that resembled a game.\r\n\r\nNeat to get cards from it after getting this in a bundle of some kind, but you''re just getting this for the achievements', 'Achievement Spam Galore\n\nI wouldn''t particularly consider playing a game that features a room where you have to open chests to unlock all 4000 odd achievements, it takes away any need to play the actual game.\n\nThere''s no reason to get this game other than the virtually free +1 to your perfect games list.', 'Mixed', 62.39, 57.58, 0.22);
INSERT INTO reviews VALUES (24169, 709920, 957, 'My dear devs, I''m begging you - we need more!\nI haven''t been able to find any other simple grid puzzle games with a comparable level of difficulty on Steam. Addictive and fairly challenging, without being impossible.\n\nAnd if anyone has a recommendation of any other games that scratch a similar itch, please comment!', 'this game is dead silent so that you can hear your own blood boiling', 'Overwhelmingly Positive', 97.91, 578.10, 0.75);
INSERT INTO reviews VALUES (24182, 710230, 142, 'I will preface this review by stating this is done as of february 3rd, 2025 as it is in early access, so take this with a grain of salt as this is not the final product.\r\n\r\nThe game is very similar to a game known as dead state, a zombie survival base management game.  however, where that game fell flat on many notes this game learned from and is improving upon.  The combat is challenging without being insanely repetitive (unless you want that, more later), the loot system is fairly managable an', 'I wish I could give this a neutral rating.\n\nUnfortunately, I was expecting more of a sandbox game that was like Jagged Alliance or XCOM, where you could manage squads, take over territory and have random missions/encounters on a strategic layer. But from what I''ve played so far, it doesn''t seem to offer that. Combat is great but it doesn''t carry the game. Design is semi-linear, more like a CRPG - where you run around, loot, do quests and ultimately progress a storyline. \n\nIf you like a linear rp', 'Mostly Positive', 74.65, 192.28, 1.92);
INSERT INTO reviews VALUES (24188, 710470, 352, 'If you are a fan of Little Witch Academia (like I am), then this game is certainly for you', 'Game has no mouse input; must use keyboard or controller (took me far too long to figure out why I couldn''t click the options button on the main menu)', 'Mostly Positive', 76.14, 2.33, 6.65);
INSERT INTO reviews VALUES (24193, 710610, 123, 'Interesting gameplay for a 2D sidescroller, I''d give it a go.', 'Unfinished and abandoned', 'Mostly Positive', 78.05, 11.30, 1.25);
INSERT INTO reviews VALUES (24201, 710710, 285, 'you, too, can experience a lobotomy', 'I''m ashamed to own this game.', 'Overwhelmingly Positive', 98.60, 3.15, 8.27);
INSERT INTO reviews VALUES (24208, 710920, 3213, 'This Diablo like version of Darksiders is even more fun than the last 10 years diablo Games!\r\nBlizzard should be embarrassed', 'Buggy garbage, who the hell codes a game like this. Nothing works, got soft locked multiple times losing hours of progress. Clearly there was no QA testing done on this game. Steer clear of this mess.', 'Very Positive', 85.31, 25.90, 24.85);
INSERT INTO reviews VALUES (24232, 711440, 124, 'An absolutely underpriced game. I would buy this game at 10 maybe even 20 dollars! The game is great against random players and even better with friends. Me and my friends did a team battle which was one of the most fun things to do. I definitely recommend this to anyone with a VR headset especcially at the price of $0.99.', 'Using Rift S, and cannot get past the main menu.', 'Mixed', 59.68, 0.72, 0.13);
INSERT INTO reviews VALUES (24238, 711540, 1403, 'Started as a peaceful ride through nature, ended up as a high-speed physics experiment. Hit a tree, bounced off a rock, did an accidental 360 into a river. 10/10 mountain said no. 🚴‍♂️🌲💥\r\n\r\nFollow my curator page for more nature-induced wipeouts, downhill disasters, and games where gravity always wins! 💸🎮✨\r\nhttps://store.steampowered.com/curator/42602807-Osiris-Reviews/', 'The game looks like a chill downhill adventure. It is not.\r\nRunning down a treacherous slope with a camera facing backwards is not fun. You will wreck a lot, and not because of the lack of your skill, but because of a game design decision, that awards memory over dexterity. \r\nLove the aesthetics and the vibe, but the camera just turns this ''outdoor experience'' into a ragefest.', 'Very Positive', 90.02, 9.02, 7.57);
INSERT INTO reviews VALUES (24245, 711660, 1268, 'It''s a pity that the cattle from russia spoil the statistics of great games by Amanita Design with their negative reviews because their paradigm has broken, for the Czechs have chosen an adequate position.\n\nThis is a great studio, and I love their creations, they are very atmospheric and fascinating, it''s literally a part of my childhood.\n\nGo cry, you offended children.', 'Chuchel is a very cute and charming game visually, but in my opinion, it’s more suited for kids. The puzzles are extremely easy, especially compared to Machinarium, which I enjoyed a lot more due to its challenge and depth.\r\n\r\nSometimes I felt a bit bored, since many parts feel more like a cartoon show for children — something like Discovery Kids. The gameplay is very basic point-and-click, with no real exploration or depth.\r\n\r\nIn summary, Chuchel might be great for younger audiences or those lo', 'Very Positive', 84.31, 3.53, 3.27);
INSERT INTO reviews VALUES (24250, 711750, 428, 'Monster Energy Supercross is a good title that can grant to all the supercross fans hours of fun. There are some technical problems, and the career isn''t brilliant, but the gameplay is truly solid.\n\nhttps://steamcommunity.com/sharedfiles/filedetails/?id=3303055320', 'EVERYTIME I START THE GAME, IT PUTS ME IN THE RED MILESTONE SCREEN FOR ONE SECOND, THEN IT JUST CRASHES. TRIED EVERYTHING IVE SEEN ON YOUTUBE AND GOOGLE AND NONE SEEM TO WORK, FIX YOUR GAME MILESTONE.....', 'Very Positive', 81.07, 6.68, 17.53);
INSERT INTO reviews VALUES (24261, 711980, 696, 'At the moment this is a pure creative spaceship builder with testing grounds. Just be aware of that. \nThat said, it might be the best creative spaceship builder there is, it''s truly amazing; just browse the workshop and you see what this small developer had managed to create, gives me high hopes for the future survival/game content. Well of course, it will take time. So if you want creative building, just buy it, if you also want purpose, you should wishlist.', 'The question was "would I recommend this game"  My answer is NO but I need to explain why\r\n\r\nNearly clocked up 100 hours on this so it''s fair to say I have tested this out..... As it''s present stage it is not a game it is a concept of Proof and it is very impressive really good building mechanics, you can step into your ship fly into space go to another planet land there and get out without even one loading screen...... But at the present stage of development there is no survival game (developme', 'Very Positive', 84.05, 25.18, 109.97);
INSERT INTO reviews VALUES (24268, 712100, 6823, 'Fantastic game. If you like the period, Vkings, Last Kingdom etc you should buy, don''t listen to the haters.', 'Just woeful of a game. While you cant produce more then 10 troops without start to starve your nation and running out of money, rival factions that own just 1 town can produce 2 20 man strong armies at full strength while while you have to wait days for your armies to become to full strength and by then your town rebel against you and start losing land', 'Mixed', 68.91, 125.87, 12.45);
INSERT INTO reviews VALUES (24272, 712190, 828, 'Its pretty fun, although it does start to get a little repetitive after 100 hours.\r\n\r\nthe combat is fun, and building your ship and crew is also exciting.\r\n\r\nim not sure how to describe it, but the game has a 80% done kind of feeling.\r\n\r\nBuy on sale.', 'Genesis Alpha One is a game that could have been excellent. If you look at the curated promotional material, you see a title that''s steeped in aliens-esque grit, with excellent vibes. A potential for excellent environments and cool story beats, dripping with atmosphere. The game itself, however, is staggeringly shallow. It reeks of a development cycle that was cut short a year early. You will spend most of your time in proc-gen arenas on bland rocks, holding down your mouse button to shoot an an', 'Mostly Positive', 70.53, 119.70, 8.05);
INSERT INTO reviews VALUES (24285, 712730, 2205, 'cool concept, decent story, boring gameplay', 'I felt like this game wasn''t that impressive.\r\n\r\nThe story was uninteresting, the acting was horrible, and there were multiple grammar errors that made the texts really painful to read through. Plus, for a fast reader like me, the game went way too slow, and I felt like half the time I was just waiting for the game to finish loading whatever dialogue was supposed to come next. This game isn''t worth your time.', 'Very Positive', 93.74, 11.90, 5.28);
INSERT INTO reviews VALUES (24318, 713460, 199, 'This game was the BEST thing to play on the Xbox 360, sad to see it isn''t developed anymore but it still holds a special place in my heart as an integral part of my childhood. Absolutely love the game even if its abandoned', 'I bought Train Frontier Classic because I love trains (especiallly model trains).   I was all excited to play and I went to play and the first thing I noticed is there is no tutorial.  There is no button layout in the Game Settings to show what buttons to push with your keyboard, mouse, or controller.  You pretty much have to second guess what to do in the game on your own.\n\nTrain Frontier Classic needs a tutorial of some kind and it needs a Game Setting layout of a button map in Game Settings t', 'Very Positive', 88.94, 8.98, 1.15);
INSERT INTO reviews VALUES (24320, 713530, 158, 'Simple side scrolling shooter game starring Doom Kitteh. Each stage consists of completing a challenge based around slaughtering hordes of Doom inspired monsters to a bad ass Doom inspired soundtrack. There''s a bunch of weapons, armors, and upgrades to unlock and despite it''s simplicity it''s a lot of fun!', 'Do not buy this game, worst game I''ve ever played. It doesn''t even work and instantly crashes on launch, and once you fix that its still constant crashing, also the whole game is the same thing over and over again. avoid', 'Mostly Positive', 77.85, 7.98, 57.67);
INSERT INTO reviews VALUES (24342, 714080, 329, 'Before I played this, I had a small penis, no girlfriend and no will to live. None of these things have changed, but the game is pretty good.\nAs a fan I think this game is fairly nice.\nIt introduces a different story from the anime and introduces a simple and fun combat system.\nThe game has both a story mode and multiplayer, both fun.\nIf you are a fan of the anime and games similar to Dragon Ball Xenoverse / Naruto to Boruto: Shinobi Striker I fully recommend this game.\n\nin the end i can say  AA', 'worst 6 m of my life, will refund this', 'Mostly Positive', 78.72, 6.23, 0.10);
INSERT INTO reviews VALUES (24344, 714120, 4845, 'I started throwing glitter every time I came across a problem, It didn''t help fix it but it sure as hell looks pretty and sparkly (i''m a little delusional <3).', 'NOT A KIDS GAME! This little "cute" character drops F bombs. Now my 2 little girls are running around saying F this and F that.', 'Very Positive', 90.30, 3.18, 2.45);
INSERT INTO reviews VALUES (24355, 714370, 301, 'metal gear wannabe but its ok', 'Released, had one update that didn''t fix anything then was abandoned. Lots of bugs, gameplay is horrible, and will most likely crash.', 'Mostly Negative', 28.90, 0.42, 7.57);
INSERT INTO reviews VALUES (24368, 714800, 190, 'Came For The Trains.  Came  For The Trains ᗜ‿ᗜ', '3 stars out of 5. I bought it because I like trains and cute things, I mean in totally non-sexual ways like cats. The idea of raillords is really cute and I really like it, because I have written my own story before hearing about this game (not influenced by Moe anthropomorphism) about a sentient stream locomotive that became a human girl when the locomotive was to be scrapped. I want to behave like Hachiroku''s mom and do anything for her. The story is well written and captivating so I couldn''t ', 'Very Positive', 93.68, 51.18, 19.52);
INSERT INTO reviews VALUES (24374, 715010, 291, 'This game is a great way to unwind on Linux, without feeling like you''re sacrificing too much time. You''ll find yourself engrossed in trying to collect as many light circles as possible while avoiding obstacles on a familiar six-lane grid.\r\n\r\nThe gameplay is straightforward: control different rectangles with unique handling and speed settings, each adding its own twist to the experience. It''s surprisingly fun!\r\n\r\nWhat I enjoy most about this game is that the map remains consistent throughout, wh', 'i didn''t like it to be honest (or it really i don''t think it was even my style of game)\ncompared to other games made by the dev, the gameplay is just plain annoying with almost no margin or ability to correct an error, you just wait until your inevitable death if you dont do some insane predictions in such a short time margin before an enemy obliterates your forehead\n\nI DID NOT ENJOY COLLECTING 400 POINTS BECAUSE OF THAT. THIS THING MADE ME SEETHE SO HARD ITS SO UNREAL\n\nanyway putting that aside', 'Overwhelmingly Positive', 95.53, 14.72, 8.38);
INSERT INTO reviews VALUES (24376, 715050, 173, 'The developers need to come back to this and simply re-write the blurb to say this is an idle game and the idle crowd would love it. \n\nIt''s a fairly short one, granted. But I think that is reflected well in the price.\nIt''s perfect for people like me that want to tinker with something simple and easy while drinking their morning coffee.', 'This game is, well, it''s nothing special. Unless you''re going for 100% completion you can finish this game in 1-2 hours. While it is only a $3 game, it does nothing new with the formula. I found myself more bored and doing spreadsheet math for most of my playtime. It plays like an old facebook game if they took most of the time gating away, and doesn''t have really any payoff for it.', 'Mixed', 67.63, 12.78, 7.23);
INSERT INTO reviews VALUES (24390, 715380, 265, 'A horror game about darkness, both figurative and literal, where the player needs to use light to stay safe. There are armed ghouls in the shadows that will kill you if you get to close, so most of the time you need to stay away and find ways to make them disappear. Sometimes it''s not exactly perceivable where you can step in or not, and you might die a couple of times because you didn''t get the distance right.\nStory is good, tragic of course, but horror needs tragedies.', 'The graphics aren''t up to par, the game play is exhausting and tedious, and the story is barely there. I gave it an honest try, but this game is terrible.', 'Mostly Positive', 70.19, 9.73, 4.30);
INSERT INTO reviews VALUES (24391, 715400, 910, 'The game is not abandoned like others say, they''ve been posted dev blogs and in fact it''s an amazing game, the combat is satisfying, progression seems at a good pace so overall very well worth it''s money considering the prices to today''s game and their quality by those standards this game is AMAZING.\n\nBoss mechanics are fairly simple, but I''m excited to see more either way, the combat and variety of weapons compensated for this so far.\n\nNow to address the other reviews: This game started with 5 ', 'had great hopes for this game it was ok at the beginning and had great potential to get better but it was abandoned so don''t waste your time or money', 'Mostly Positive', 70.55, 15.58, 25.65);
INSERT INTO reviews VALUES (24400, 715560, 3314, 'It wasn''t for me, but I could definitely see the appeal. Beautifully designed, interesting characters, but walking sims, even the great ones, are a love-it-or-hate-it relationship. Still, you should give it a try, it''s not expensive and it IS a cool game.', 'I never reviewed this?   Well, isn''t that a shame.  I lost a perfect opportunity to shame it while it was still popular. \r\n\r\nThis game was a severe disappointment, and I think a lot of that was how poorly it presented itself.  \r\nAt a surface glance it appears to be a pretty game,  though it was more concerned with presenting itself as a peaceful, non-violent game about pictures or whatever.    I was told it was a good game for exploration, and that is why I tried it... \r\nAnd then I ran into the ', 'Very Positive', 89.89, 7.87, 13.43);
INSERT INTO reviews VALUES (24431, 716340, 194, 'So, I get an achievement for falling in a river but not for being eaten out? Make it make sense.', 'Recommending this game is impossible for me. All the lovely writing in the world cannot overcome the tedious "breasted boobily" nature of the art, nor the sexualization of children present within the story. There are ways to present young women/teenagers coming into sexuality/adulthood, none of them involve leering upskirt shots or romantic kisses between a 19 year old and a 12 year old.\n\nAnd what hurts more is that the writing is sincerely quite good. It''s refreshing to see a story set in the V', 'Overwhelmingly Positive', 96.39, 6.93, 24.32);
INSERT INTO reviews VALUES (24432, 716350, 239, 'Very mechanically detailed and atmospheric game in medieval setting similar to m&b. I want to go to the bar after the battle to drink ale from the innkeeper!', 'I believe most of the other reviews of this game are fake. They have a 15 level tutorial area and the content (monsters etc.) is just copy and pasted from the tutorial to the "mainland". This is just a device to keep people on the game long enough for the steam 2 hour max play policy to expire so players can''t refund when they learn the game has little to offer. TBH probably one of the worst games I''ve ever played. Do not buy.', 'Mixed', 61.09, 4.07, 11.47);
INSERT INTO reviews VALUES (24438, 716490, 1070, 'Zachtronics developed a lot of these ''assembly code'' games, and I think this one was the best execution of the concept. While I enjoyed the others a lot, TIS was very bare-bones and Shenzhen was too complex and varied in its objectives. I think this game struck a great balance in challenge, visual feedback, and I liked the story as well', 'As a fan of the programming puzzle genre, I was excited to dive into the game. The aesthetic, the concept, and the idea of hacking with a pseudo-assembly language seemed right up my alley.\n\nHowever, with the bugs, my experience was frustrating from the start. It completely blocked my progress. The game asked me to input some text from the receipt, but I cannot type anything there. No matter what I tried, I couldn''t get past this step, which meant I was stuck before even getting to the actual gam', 'Overwhelmingly Positive', 96.36, 64.82, 0.35);
INSERT INTO reviews VALUES (24439, 716500, 730, 'I don''t think I can play this now that it''s basically become a reality', 'You know it’s kinda bad when SOLITAIRE is better at capturing your attention than the main story. Maybe I’m just jaded from having been through multiple IRL therapy sessions, but I didn’t find much of this story particularly compelling or full of insight on the philosophy/ethics of mental health treatment. The AI nature of the treatment wasn’t nearly as much of a conflict generator as it could have been, and having to follow the script for almost all therapy sessions without even the opportunity', 'Very Positive', 93.15, 6.28, 9.28);
INSERT INTO reviews VALUES (24442, 716630, 104, 'Good little game with some flaws.  \r\n\r\nBalance of upgrades needs some tweaking and unlocks are sort of lackluster - they all sound great, but all the new tech has to be researched in-game and I don''t see a reason to research new weapons when it takes half the game to research them and doing so forces you to neglect basic research (like economy boosts, hull boost, and shield boost). Why research gatling guns when cannons get the job done and you can fully upgrade them for only a bit more than the', 'As a big fan or Harbinger I was really suprrised how unfinished this game is. It cleary need some playtest iterations to be ready to be released.\nIt is repetitive and therefore quite boring. Art is worse than its predocessor, choices are meaningless, UI is horrible and the whole game flow is flawed.\nI got into a loop of attack-: defend-attack-defend so I did not do any progess in the game. Progression is obviously broken.\nGame is around alpha level, far from beta.\n', 'Mixed', 60.58, 6.03, 49.88);
INSERT INTO reviews VALUES (24443, 716640, 350, 'what the sigma', 'The game does not prepare you for the mechanics or at least gives you a win at the beginning to figure out what to do right. This isn''t fun; I literally can''t find the fun. This game sucks.', 'Mostly Positive', 73.71, 12.70, 4.02);
INSERT INTO reviews VALUES (24444, 716650, 153, 'I''ve played this game front to back twice now. However, I haven''t played this game in months, maybe a year. The reason I''m on the store page is because I think about this game a lot. Even now I''m thinking I''ll play it again soon. I think this may be the most underrated, under-played, under-known game on this platform. \n\nThis game has a lot of character and a lot of identity. The writing is charming and hilarious. The voice acting is perfect. This game''s only issue is that it''s over long before y', 'I know it''s a small gripe.. I mean, the game is fine, I guess. Fun enough and cutely made in an attempted old 80s style. But the bobbing. THE BOBBING!! Why do all the characters bob up and down ALL THE TIME all AT THE SAME TIME. \n\nFor me personally it makes the game unplayable as it distracts me too much and drives me completely bonkers. Big no for me even though I payed for it. Sigh.', 'Overwhelmingly Positive', 97.39, 3.53, 0.55);
INSERT INTO reviews VALUES (24446, 716710, 378, 'i couldn''t afford dragon ball sparking zero so i went for the next best thing.\n\nalso this is a very fun fighting game in general, it feels quite unique with the "flying" gimmick and the duo system. you need a bit of modding to get a proper online network going and need to find a chat room (like discord) where people are playing the game, so if you can''t do that for some reason then maybe just give the offline modes a whirl and be done with it.\n\nalso it has koishi komeiji. instant 5.14/5 stars.', 'Another neat concept, hindered by god-awful difficulty spikes and poorly handled JP development.\nThe boss of the second to last story chapter is impossible to beat, even on Easy.\nAvoid, unless you enjoy neat concepts ruined by frustration and mediocrity.', 'Overwhelmingly Positive', 97.35, 4.33, 7.75);
INSERT INTO reviews VALUES (24471, 717310, 256, 'Great game. Horrific gamepad implementation. Would''ve rated it a negative if it wasn''t for the fun gameplay.', 'The game has zero respect for your time. Long walks between save points and boss fights, losing experience on death, and a complete lack of any sort of useful map completely ruin the game. Some hitboxes feel really off. The down stab attack only chooses to work around half the time, causing tons of unfair damage.\r\n\r\nIf you are looking for a retro style metroidvania, consider Alwa''s Awakening or Cathedral instead.', 'Mostly Positive', 75.00, 4.47, 4.30);
INSERT INTO reviews VALUES (24478, 717560, 444, 'A fun experience but extremely short and lacking complexity. Very good as a proof of concept but as a game in and of itself needs more fleshing out (content, variables to solve, consequences for poor reasoning, etc.). As the game sets up a clear sequel, I hope the developers come back to it with more focus on the mystery solving aspect and the overall complexity of the culprits'' schemes as opposed to the aesthetic and the timeline mechanic (which are undeniably cool, but not enough to make for a', 'The issues with this game are that it is too short, and too easy- all three cases are fairly short, with at max three suspects and limited physical evidence. It feels like a demo for an actual game rather than a full product.', 'Mostly Positive', 73.20, 2.57, 1.87);
INSERT INTO reviews VALUES (24479, 717610, 222, 'A relatively quick detective game with enjoyable background music, good art style, and fun gameplay. My favorite parts were the taxi rides between each location which gave you the opportunity to have conversations with the driver.\n\nOverall, I recommend this game if you enjoy puzzle solving and just want to relax :)', '"A Case of Distrust" looked promising with its noir aesthetics and intriguing premise, but unfortunately, it''s unplayable in its current state. The mouse movement slows to a crawl, making it nearly impossible to click on the dialogue advancement arrow or scroll around the screen to search for clues. This technical issue severely hampers the gameplay experience, rendering the game unplayable. If the developers ever upload a patch to fix this, I would be willing to give it another try. Until then,', 'Very Positive', 84.68, 3.22, 0.18);
INSERT INTO reviews VALUES (24480, 717640, 328, 'Really fun spin on a Reigns game. The priest is a cant and you can romance characters that talk like they are sims voice actors. Recommend', 'Hamfisted last second commentaries about real life are not appreciated', 'Very Positive', 81.40, 3.95, 3.27);
INSERT INTO reviews VALUES (24486, 717790, 365, 'The devs abandoned this game ages ago. So why is it still for sale. It’s basically unplayable and will never be updated.', 'ABANDONWARE ::::STAY AWAY!!', 'Mostly Positive', 72.05, 162.57, 12.00);
INSERT INTO reviews VALUES (24491, 717850, 120, '8/10 It is overall pretty good.  The MC can be annoying at times but it is not to the point that is drags down the rest of the cast.', 'I liked "Tomboys need Love" and "Catch Canvas" so I gave this v.n. a try. There is no doubt that the author is good at dialog and creating a setting. I try to judge entertainment from the view of the intended audience. You cannot fairly compare "Peter Pan" with "Gone with the Wind."  My problem with this v.n. is I have a certainty that I am too old for it yet the morality and sexual references of one or more of the routes makes it inappropriate for pre-teens. The self censured (or fear of Steam ', 'Overwhelmingly Positive', 96.67, 36.22, 93.18);
INSERT INTO reviews VALUES (24510, 718200, 139, 'It''s RPG Maker. It''s got the usual RPG Maker graphics, music, janky staircases, etc.\n\nBut there''s a surprisingly powerful story behind that, and even the gameplay feels fresh - the bosses have a lot of interesting gimmicks.', 'nicely priced but stuffed with way too much tedious narrative before you actually get to any gameplay', 'Very Positive', 92.09, 214.53, 0.28);
INSERT INTO reviews VALUES (24525, 718560, 2109, 'My Dad plays this game all the time, i probably have like 30 minutes on this game, please play with him.', 'The board game itself is great, but this iteration of it has some real problems. One would think that an app could make things more clear than a board game, but it does not. And the online lobby is one of the most irritating implementations I''ve ever seen. From the moment you step in, anybody can invite you to a game. So when I go in to check to see if the game I''m playing with friends is ready, I have to first cancel half a dozen game requests. And people don''t stop. They''ll just keep hitting t', 'Very Positive', 90.61, 1587.25, 2.73);
INSERT INTO reviews VALUES (24526, 718590, 638, 'Dark Devotion is an unconventional souls game that’s somewhat hamstrung by some questionable rogue-like mechanics. But it’s definitely well made and interesting enough to appeal to a certain style of souls player.\nSome reviewers claim that this is a roguelike which is a genre a lot of people are sick of in the indie space. But this is not really true in that the levels are not procedurally generated. The game does have a roguelike structure in that you need to do more runs in order to unlock bet', 'I play lots of games like this, but never with *these* default controls. This game does not let me change them in game so I will not be playing it.\n\nrefund / 10', 'Mostly Positive', 75.71, 26.98, 0.08);
INSERT INTO reviews VALUES (24527, 718650, 715, 'Its a fun game for like ~20 hours (also the time to finish 1 out of 3 race campaigns). But for me after that, even while that is switching to a different race with different buildings, units, and few magic spell, it felt like you are doing the same 10 actions every time, So for me after that it lost its appeal, still fun for the price I bought it at', 'Boring.\nIt tries to be a Majesty, but it doesn''t have a soul. \nNo humor, no story. You need tonns of workers who barely could feed themselves. Economy is really bad.\nHas a very heavy "mobile" feel to it. \nI pushed myself to the 3rd scenario, but could force myself to finish it. \nThere are better game to play.', 'Mostly Positive', 71.89, 35.92, 20.52);
INSERT INTO reviews VALUES (24529, 718670, 4832, 'it''s woefully easy to become a cannibalistic homicidal maniac on a diet purely of cops, the spiral is real', 'I wish I''d like this game. I just love the setting. I don''t mind the cryptic nature and absence of hand holding. I actually enjoy it.\r\n\r\nBut in the end, it''s a micromanaging grind fest that can end abruptly to bad RNG.\r\nEverything is decaying on a timer, your are constantly trying to keep up with them.\r\nIt''s just unsatisfying how much attention is needed to achieve so little.\r\n', 'Mostly Positive', 79.43, 36.95, 22.10);
INSERT INTO reviews VALUES (24539, 718850, 2681, 'I should have written this reivew a long time ago. Age of Wonders: Planetfall is a great game. A interesting twist on Age of Wonders with is new Science Fiction setting (with some more fantastical elements like Psionics.) \n\nIt is a game that still looks great in my book. One of the best looking 4x games still in 2025. Has a lot of interesting faction. And if you want Age of Wonders, but a bit more directed. A bit more constrained then Age of Wonder 4, then this is a good option. The two games pl', 'Same as the third game. Throws a login section first thing when you hit start. I have a steam account, i have the game on steam and that''s all i need to start the game and play it. I don''t need to be stopped by the third party account police and asked for my id so they can steal my data.', 'Mostly Positive', 79.90, 450.88, 1.27);
INSERT INTO reviews VALUES (24548, 719040, 10564, '20ish hours into the game and I''m loving it so far (i restart a lot), the story is good, the quests are fun, I found myself laughing out loud a couple of times because of funny dialogue, your choices kinda matter and they have an impact on the world, the classes and customisation are fun and diverse, and finally the combat is a blast\n\nHighly recommend for any rpg fan\n\nedit: I just finished the game and loved every minute of it', 'While game itself is great and reminds me of classic Fallouts (music, characters, dialogues, easter eggs, etc), I can''t recommend buying it on Steam because of the way DLC activation is implemented, it''s simply horrible.\n\nIf your Internet connection is interrupted during gameplay - DLC quests will just silently disappear, costing you hours of progress and it breaks your save, not carrying over your DLC desicions to the main game, and questlines get restarted without the ability to actually compl', 'Very Positive', 85.12, 62.93, 54.20);
INSERT INTO reviews VALUES (24558, 719200, 147, 'is gas petal mang.', 'Okay. I bought this game a few days ago, i was extremely optimistic after reading reviews. I decided the £3 spent on the game may be worth it. I downloaded the game and loaded into a massive box which prompted me to join the discord, so i accepted. I quickly gathered that this game was a desolate wasteland and was dying by the day, with people explaining in the discord why the game was so bad and quickly being banned. I played the game for a few hours, i was having a blast. If you have a full te', 'Mostly Positive', 74.83, 0.13, 7.58);
INSERT INTO reviews VALUES (24576, 719590, 342, 'a fine game.', 'This game was a scam, uncompleted product. The fact its still on steam is a farce, Do NOT buy this, the money just goes to the lead devs pocket after he ran away with the money.', 'Very Negative', 17.25, 26.98, 8.80);
INSERT INTO reviews VALUES (24583, 719750, 392, 'PUSS! is an eccentric game with lots of funny and colored levels in a retro ambiant. I recommend it!!! 💗💗💗', 'There bullet hell RNG, a then there’s this game. There are people that will scream "git gud" and “skill issue” and then there’s this game. there are so many levels where the odds are more than stacked against you. every time you time I’m smashing my click button trying to regain control over my character only for it to immediately die every time in boss areas. The infinity frames are useless if an object collides with your character. When you respawn, you will most likely spawn on top of a proje', 'Very Positive', 91.58, 25.97, 32.95);
INSERT INTO reviews VALUES (24587, 719890, 4545, 'The game itself is fun, the playerbase. Full of bullies, The lil guy has no chance in this game', 'I have 4200 hrs in this game and I have come to terms that while I''m stupidly addicted and keep coming back, my tolerance for the bullshit has worn out. I used to be one of those die hard sit and grow for hours and hours and hours and hours afk trying to get some semblance of accomplishment. It''s just not feasible. \n\nThere''s a select handful of people (simps?) who have sunk SO much time into this game to get giant dinosaurs that are 10.0 who get to enjoy the game because they''re OP giants who ca', 'Mixed', 68.45, 16.08, 4245.12);
INSERT INTO reviews VALUES (24592, 720030, 193, 'One of the most unusual game experiences. The game pretends to show you than its deeper, that seems from the first sight. Totally proved, that simplicity can bring more sence and joy than overcomplicated and meaningless game mechanics.', 'Don''t get me wrong, this is a really interesting and unique game, but the price is absurdly high, at about 6$ per hour of gameplay. Again its a really unique and interesting concept, but it doesn''t have enough content to justify that high price tag.\n\nThere are also a lot of 2d abstract games out there, so this game has a lot of competition to be priced so high. \n\n\nIn this games critic reviews, Kotaku (gaming news site) says "it only took a few seconds for me to completely fall in love with it", ', 'Very Positive', 84.97, 3.53, 0.42);
INSERT INTO reviews VALUES (24598, 720250, 1754, 'lights cut off=alt f4', 'Dev threw a fit over a free mod', 'Very Positive', 81.70, 0.37, 1.50);
INSERT INTO reviews VALUES (24600, 720280, 496, 'Zero was better. Still, for a AUD $3 kinetic novel, better then what I''ve read at the $15 range. MC is a giga-simp. OST is amazing.', 'Cute game, but the resolution doesn''t get any better even when using the smallest window. It hurts my eyes to look at it for too long.\nThe English writing is very shaky. It can be very annoying and hard to understand.', 'Very Positive', 82.86, 3.20, 1.13);
INSERT INTO reviews VALUES (24605, 720350, 809, 'Mundaun is an amazing experience. The art style is gorgeous. It''s based off a real village in Switzerland which makes the story more intruiging. I was hooked for every hour over the course of the game. It takes about 7 hours to beat, but the gameplay reinvents itself every hour. It doesn''t get boring. I highly recommend it if you like the art, dark fantasies or the Swiss Alps.', 'When you solve a puzzle correctly, it should immediately progress. In Mundaun, I solved a puzzle correctly kind of by purely common sense and logic, only to be  given feedback that I was wrong. Only to find out that I was right and had to find a photo on the wall to confirm. \n\nIm sorry, but if the player flukes a puzzle by using common sense or just luck, the game should still progress and reward the player so. \n\nCool art style, atmosphere and vibe, I just don''t have the patience to do puzzles t', 'Very Positive', 93.57, 7.90, 0.78);
INSERT INTO reviews VALUES (24611, 720560, 1250, 'This game is not talked about enough, it is Bloodborne meets Castlevania. The combat is fun, the platforming can be iffy but I attribute that to me pc being sub potato. I relish the day I get to play this with max settings and I have yet to encounter a soundtrack or area I didn''t like.', 'This game is phenomenal until you try to use the map. I can''t even begin to recommend a metroidvania game in which the map feature does not work at all. It is a blank black screen with the names of the locations randomly placed throughout the entire abyss of what should be the map. The devs have known about this for years and it has still not been fixed. \n\nIf you want to play an extremely large metroidvania game without having a map, this may be the game for you. I personally cannot give this ga', 'Very Positive', 86.80, 18.93, 30.55);
INSERT INTO reviews VALUES (24613, 720620, 3009, 'I love this editor. You can make amazing scenes or even import some via the Tallspire Bazaar website, and the community is amazing. The free content with updates is also awesome, and I like that there isn''t a subscription. That being said, the downside is the $15 per player seat system. I think with the purchase of the game, you should be given at least 1 seat. That way, you can use a TV or something as a second monitor and have the player view it for small groups. \nI''m not mad about buying seat', 'There''s no way I can recommend this to use as a DnD virtual tabletop. It''s so close to being great, you just need to spend a lot of money for it. \nSo, you can buy the game on sale for about 19$ and that''s worth it for the full fledged editor and map making, then they introduced "seats" to the game. Great, now players don''t also have to blow about 20 bucks, except the DM has to pay for the seats. \nImagine the turn off players have in person when you paywall the chair they can sit on to play, so t', 'Very Positive', 90.86, 8.00, 0.13);
INSERT INTO reviews VALUES (24624, 721180, 233, 'the game is aesthetically repulsive and an insult to the entire project of world-civilization, playing it for only three hours I developed a terrible headache within the first; however; the US Govt provided the developers with a grant of 250k to combat misinformation, and I support the Free West', 'Game advertised itself as a character action game with an unsubtle progressive commentary on politics. I don''t know any character action game where you don''t start fighting until you go through an hour of unskipable iterative cut scenes as your thrown into a middle of a story where you don''t know any of the characters but the game makes sure you know each of their pronouns. Like I got this game to stream and laugh with my audience about the games politics and pandering... and I did... but I didn', 'Mostly Positive', 74.25, 2.67, 16.88);
INSERT INTO reviews VALUES (24639, 721700, 119, 'I loved every moment of this game, however I am beginning to suspect the developer may have wrapped up creating new content. I dont personally have an issue with this as I love what I''ve been given but i know what matters to some given its still listed as EA', 'Bought this game expecting more updates considering the news and stance in the early access description. Very buggy, can''t recommend as I don''t see the devs finishing anything.', 'Very Positive', 80.67, 27.45, 4.68);
INSERT INTO reviews VALUES (24653, 722060, 1621, 'Dominions somehow merges the horror and brutality of large-scale warfare between primordial entities with the mundane drudgery of managing a huge excel spreadsheet. \n\n', 'Don''t buy this game. Wonder why there''s Dominions 1, 2, 3, 4, 5, all released close to each other? The developer releases one update calls in Dominions 6 and charges $40 for it.', 'Very Positive', 94.02, 65.98, 24.82);
INSERT INTO reviews VALUES (24655, 722180, 1203, 'All the zombies are taller then me, even the kid zombies. Made me very sad.\nBut I was able to shoot the kid zombies. Made me very happy', 'I originally bought this game because I thought it was going to be a co-op looting type game where you make your way through the objectives with scavenged items. \n\nThis is more of a disappointment because you start of in a safe-room full of weapons and you just pick whatever weapon you want to go do the objectives around the map. Pretty lame and takes the whole point out of looting other than to find collectables. \n\nIf you''re looking for a co-op looter shooter type experience you''re in the wrong', 'Very Positive', 82.54, 12.13, 2.65);
INSERT INTO reviews VALUES (24665, 722560, 415, 'Pros: mutations are fun, world design is fantastic with fun lore drops, it was fun to explore and discover things in this world, and combat was fun. All in all, very fun to play, for a while. \n\nCons: I know this isn’t really a story based game, but the world and lore was interesting enough I started getting interested in the story development with each successful run. However, it ended up being a very lackluster story in the end. That was a bummer. The worst part was the RNG, though. It was anno', 'This is an absolutely terrible port of this game. Everything feels "off" from the xbox one version I spent 100+ hours with... Colors, hit detection, clarity, control, everything feels bad. Excellent game, a lot of fun, but feels awful to play this version of it.', 'Mostly Positive', 75.90, 84.37, 1.10);
INSERT INTO reviews VALUES (24674, 722730, 1222, 'This excellent NERD game unexpectedly does not support Linux systems! But I will still leave my thumbs up.\r\n这个优秀的黑客游戏竟然意外地不支持Linux系统！但我还是给个好评。', 'So, I actually have more than the listed hours. I''ve put more than 500 hours into this in total, going back to beta 7. I want to like Cogmind. I really want to like Cogmind. It''s full of interesting-sounding ideas.  So what''s the problem? Accessibility. The game has been developed around the top tier of players for years, resulting in swathes of content that almost nobody will ever get to see due to the high difficulty. Worse, the difficulty slowly increases as the new content causes trickle eff', 'Overwhelmingly Positive', 95.74, 73.45, 353.50);
INSERT INTO reviews VALUES (24682, 722960, 382, 'It''s outstanding game in my opinion, But it was only fun for a few years, or months the player base died down, now you won''t really get into matches on your own, you either bring Friends play with or you wait for eternity for a few russian guys to join so you can some how play.\r\n\r\ndon''t count on bringing friends cause they wouldn''t buy this game for the reasons you would give them\r\n', 'Just kinda sucks ngl.', 'Mostly Positive', 76.44, 103.05, 34.05);
INSERT INTO reviews VALUES (24694, 723270, 468, 'This game made me want to get a Roomba and put googly eyes on it. Sadly, my house is unfit for a Roomba at this moment, but once I move elsewhere, Rumu is coming.\n\nFun game, great story. Less enthusiastic about the OST, but that''s fine because by the end, you''ll love Rumu, I''m sure.', 'I love the idea of Rumu, unfortunately the game crashed shortly after I got started and every time I tried to launch it after that it was just a black screen with pleasant music. I tried uninstalling/reinstalling the game, restarting my computer, deleting all files from my computer, etc. but nothing worked. It looks like this has been a problem since at least 2021.', 'Very Positive', 89.53, 3.60, 0.22);
INSERT INTO reviews VALUES (24700, 723390, 2365, 'It''s not good. Why do I recommend it? Simple, if you''re interested in game design/theory/production- this game is a perfect example of things NOT working well.\nDoing a good job means being aware of why things don''t work and what that looks like.\n\n10/10 don''t be this game.', 'Hunt down the refund\nEdit: I failed to hunt down the refund', 'Mixed', 54.21, 1.88, 5.62);
INSERT INTO reviews VALUES (24735, 724250, 111, 'I wish the review system on Steam were more nuanced because I would only just barely recommend this game to fans of the series. For one, a playthrough is much longer than other entries in the series, which discourages replayability, which is bizarre given that''s what the series is known for. Add in a poor translation/localization and you have this release of princess maker 5. While it does have its merits (cute characters, interesting story, the option to be a mother and not a father, friendship', 'go play pm2 refine. this game is fun but way too long. i havent finished my first playthrough and i have 84 hours on the game. princess maker is made to be replayable but this one feels like it just drags on', 'Mixed', 67.57, 38.22, 85.37);
INSERT INTO reviews VALUES (24738, 724300, 261, 'i like smash bros, i like roof, i like this game\nbuy it', 'uf u put put a gun to my head and told me to play this game or die... i would said pull the trigger. bcuz i would rather  die than play this game.', 'Very Positive', 89.27, 6.68, 0.22);
INSERT INTO reviews VALUES (24746, 724470, 124, 'lazy', 'Really shitty game. There are many idlers out there. Don''t waste your time and money with this.', 'Mostly Positive', 75.81, 25.87, 2.52);
INSERT INTO reviews VALUES (24759, 724740, 325, '✔️', 'Played on Steam Deck.\n\nNo colorblind mode, visual artifacting on steam deck, only 100 levels, just an achievement spam game.', 'Mostly Positive', 72.31, 1.38, 0.08);
INSERT INTO reviews VALUES (24770, 724970, 102, 'A Chinese Drama RPG, that delivers gorgeous visuals, romantic moments and some fun battles, but also a lot of jank and bad pacing.\r\n\r\nThe game''s biggest flaw is its extremely slow start. It is a bore to play the first 2-3 hours, when you only play as the extremely naive/dumb kid. Things greatly improve once you recruit Wangshu. From there, you the plot, romance and combat mechanics shift into gear, and you''ll have a fun time until the last few hours, when it starts to rush things out and gets a ', 'I really wish I could recommend this, but I simply can''t. I''ve enjoyed many of the Chinese games that have been coming to Steam in recent years, and I was excited to try this thanks to the English fan translation... but it''s just not a good game. It''s got a lot of potentially good elements, but none of them really come together. Worse, it feels janky and borderline broken throughout. The combat system, in particular, seems downright unfinished. Nothing about it feels like it works quite like it ', 'Mostly Positive', 74.51, 32.78, 37.63);
INSERT INTO reviews VALUES (24783, 725270, 643, 'For some reason I thought this had a more game-play element than a visual novel. Nonetheless I''m really curious where this is going and enjoying the story so far.  It''s also a great way to wind down in the evening.', 'More of a walking simulator than I expected, which is not an inherent problem but I didn''t connect with the characters either. The devs did a great job, but this one just ain''t for me.', 'Very Positive', 88.65, 23.97, 0.27);
INSERT INTO reviews VALUES (24786, 725330, 229, 'A very fun short game, some of the fights can be a little frustrating if you react slowly like myself but the music is atmospheric and the characters are a lot of fun.', 'First half of the game was great. It was creepy, fun, and had a good story. Second half dragged. It was mainly walking with a few fights. By the end I was wondering "Is it done yet?".  \\Why did the friend live? Why is the dragon fuzzy?\nI think if the game ended after the 1st person pov I would''ve 100% recommended it. It just feels like it lost all its charms in the second half.', 'Overwhelmingly Positive', 95.63, 2.80, 2.45);
INSERT INTO reviews VALUES (24791, 725480, 2209, 'Slap my balls', 'I commend the developer''s effort for trying, and the graphics are nice, but it''s just not like the competition.', 'Overwhelmingly Positive', 95.70, 49.07, 0.40);
INSERT INTO reviews VALUES (24799, 725780, 117, '*"Play With Me" is a thrilling escape room horror game that will put your brain to the test. With its eerie atmosphere, clever puzzles, and unsettling surprises, it keeps you on edge while challenging your problem-solving skills. Perfect for fans of psychological horror and mind-bending riddles, this game delivers an immersive experience that will keep you hooked until the very end!', 'The game seems alright but it has some game breaking bugs that haven''t been addressed anymore for a couple of years. One of them being a game breaking bug that doesn''t let you continue with the game, in a bugged keypad for a door in one of the rooms ("Crosswords" room). Some people have reported some issues with the menus and other parts too. So In it''s current abandoned state I wont recommend buying it.', 'Mixed', 55.56, 5.12, 3.20);
INSERT INTO reviews VALUES (24815, 726110, 1035, 'Very fun game, but still very buggy. People getting stuck on tracks, reputation plummeting because a train that should be in the station never arrived and holds the station hostage, the type of bugs that feel like they should have been discovered in beta if I''m seeing them. Tutorial could also use some love, a lot of necessary info is not explained. I had to consult guides to understand key things that could not be done, that are not obvious. Sign of a tutorial that needs an overhaul. If these t', 'I usually like building/sim games but this gave me a headache. Having to procure every item and tool takes a long time because bonds are gained by accomplishing achievements. Hiring staff is extremely expensive and making money is slow as well. The tutorial was not very good and basic. Building on multiple floors is also challenging to do especially when money is hard to come by. If you like a grind, go for it.', 'Very Positive', 85.60, 82.92, 3.88);
INSERT INTO reviews VALUES (24817, 726200, 142, 'It''s a really short and sweet puzzle game. it took me around 30 minutes to finish it. if you want to buy it get it with a big discount.', '45 min to complete casually, feels short\r\nEasy puzzles because not a lot of options\r\nLack of animations\r\nNice music and atmosphere\r\nNo speech\r\nStory?', 'Very Positive', 84.51, 0.57, 0.90);
INSERT INTO reviews VALUES (24819, 726250, 189, 'it is a fun short game', 'abandonware', 'Mostly Positive', 71.43, 4.93, 2.20);
INSERT INTO reviews VALUES (24825, 726360, 658, 'i think this is the worst game iv ever played', 'no wounder russia invaded ukraine when they come up with crap like this', 'Mixed', 59.12, 0.57, 0.43);
INSERT INTO reviews VALUES (24838, 726590, 443, 'Online play is gone, but its just a simply addictive time-waster.  Easy mechanics to learn, tough to master.  Fast paced and local play is smooth.  Worth a couple bucks on sale.  Grin out a season and 3-point contest to unlock cards pretty quickly.', 'Do not support games like this one who want to charge you micro-transactions for single player content. Refund requested immediately upon finding out.', 'Very Positive', 80.36, 6.95, 0.50);
INSERT INTO reviews VALUES (24849, 726830, 684, 'for a game that prides itself on being an accurate simulation of , there''s a surprisingly high number of  to do here. its still pretty good regardless, with 200% more movement compared to its stationary predecessor.\n\n00110001 00110000/00110001 00110000 Stars, would  again', 'SUPER HARD DO NOT RECOMEND\r\n', 'Very Positive', 92.40, 7.20, 106.70);
INSERT INTO reviews VALUES (24850, 726840, 621, 'man i love this game, after previously downloaded and played the pirated version for days, i decided to bought it on steam to support the dev, \n\nthank you for the dev and mod creator', 'I really never leave reviews, but this game is identical to Game Dev Tycoon. The gameplay is the exact same, the graphics are similar, there''s literally nothing separating the two games. I''m going to refund it, it''s basically an exact copy that adds nothing of value. Disappointing', 'Very Positive', 90.18, 94.57, 228.98);
INSERT INTO reviews VALUES (24864, 727130, 1110, 'I have been trying really hard to get into this game, because it''s the one that gets the closest to Fractured Space''s combat. While it falls short of FS''s capital ship combat, the story and events on this game are really amazing. I got into the sidequests, and I gotta say, congratulations to whoever wrote the Cursed Ship, I really enjoyed that. Most of the other sidequests are amazing too, I am enjoying them more than the main story, but that is not a bad thing.', 'Many random situations, but barely any smart choice. Cursed ship ? No option to deactivate systems and loot, really ?! \nTutorial lacking in term of weapon overloads, shields regen (when 0 they stop completely).\nMost choices come back to the same, so more like a what happen before situation resolves.\nFind a creature on your ship and miss your roll, then no conclusion to the situation.\nThe "adventures" are really unpolished and needed a major overhaul to have some sense and bring some fun and clos', 'Mostly Positive', 76.58, 16.73, 3.73);
INSERT INTO reviews VALUES (24887, 727570, 153, 'Very fun game.  After I finished it i just wished there was more.  Hit my rimworld itch hard.', 'Won''t run on an excellent computer. The story mode seems completely busted. It slows until it crashes for no reason. Nothing else does such a thing.', 'Mostly Positive', 79.08, 205.42, 7.37);
INSERT INTO reviews VALUES (24900, 727850, 1354, 'Dark Souls meets Diablo meets Doom. Slash and hack your way through the land of the dead facing monsters through the fire and brimstone. Everything a dungeon crawler should feel like without any unduly complex extras.\n\nHere''s the thing, a game (as an adult) should be 1) Good and 2) Short. These games that claim over 50+ hours worth of content require you to sit there for over 2 days'' worth of time. I can''t do that anymore. I need something that knows what it''s doing and does it for less than 10 ', 'When I read it being a "metal af slasher with brutal melee combat" I expected a bit more, something fast paced and more fluid combat but this felt pretty stiff and slow throughout the game, The only thing that felt metal was the soundtrack I guess, which was decent. However it did pick up a bit in the end but not enough to make up for the whole game unfortunately. \n\nEnemy variety was also lacking and so was the combat. The enemies had a minimal set of attacks they were repeating and same goes fo', 'Very Positive', 88.11, 6.60, 3.88);
INSERT INTO reviews VALUES (24903, 727910, 198, 'i luv how u can get on life boat n expierence the sinkin bit crazy stayin on titanic n sinking that way', 'This game needs some work. You are unable to explore much of the ship, only the outside decks, and some interior rooms. I''m sure the simulation is great, but I mostly bought this game for the exploration aspect, and if I cannot explore the ship, this game is not something I would recommend.', 'Mixed', 60.10, 0.35, 0.18);
INSERT INTO reviews VALUES (24916, 728240, 340, ''''' I wish I could see the Tree House one last time...\r\nBut That''s ok.\r\nJust promise to plant me there. ''''', 'If you''ve got kids who need a few hours to kill and you''ve been wanting to introduce them to a basic turn-based-RPG style game, this would be good for that.\n\nOtherwise, it''s pretty boring. 40% of the game is slowly and awkwardly bouncing from one point on the map to the other side of the map in a slow moving boat. The other 40% is slowly walking around big set pieces just to smack things for dosh. The interrogations were kinda fun at least, and the fights were easy to understand get through. Sad', 'Very Positive', 87.35, 13.35, 8.10);
INSERT INTO reviews VALUES (24918, 728530, 1933, 'It''s pretty fun, though it has a lot of menus so you should be aware of what you''re getting into. SD Gundam games don''t tend to be especailly *fast* games, so if you can''t handle hour long missions you won''t enjoy this.', 'I love the game, just not the constant crashing, from patch 1.6 onwards. \nIf Namco bandai fixes all the crashes or give us the ability to roll back  to an earlier patch 1.5 version, it will be a thumbs up.', 'Very Positive', 89.55, 961.82, 259.13);
INSERT INTO reviews VALUES (24925, 728740, 1176, 'very straight forward and FUN', 'This game needs a proper remaster. This is the biggest cash grab I''ve ever seen. Sniper elite v2 is the best of them all and yet when they resell their game at an extreme price with no difference what so ever, I get offended. I play this game on the hardest difficulty and I still see hundreds of bugs and issues that needs to be fixed. \n\nI recommend the game, but do not buy it at this ridiculous price. They don''t deserve a fucking penny', 'Mostly Positive', 75.51, 11.17, 4.78);
INSERT INTO reviews VALUES (24929, 728880, 12951, 'The pacing is too fast, the food takes too long to make, the customers are rude, the environment, tools, and even your very own friends and family you play with are against you.\n\nIt''s pure chaos\n\nWorth every penny', 'This COULD be a fun game. However, I always get frustrated, because the levels get too crazy too fast. I wish they would slowly get harder as you went and instead have DLC with the crazier levels. The first level is pretty chill, but once you get to the second and third level, it''s too much.', 'Very Positive', 93.74, 6.93, 107.63);
INSERT INTO reviews VALUES (24933, 729000, 2413, 'What fun this little game is.  keep grabbing inventory is what I have learned.  And find your safe places! such fun.  perfect starter game for an older person who watched their kids game for 27 years! lol finally its moms turn!  recommended by my gaming savvy kids', 'I hate to leave a "negative" review because the game is polished and the stories are interesting and appeal to my desire for something fantastical and slightly dark, but I will never be able to finish this game. The constant new requests that require you to return halfway across the world to where you just were just at the moment you think you''re going to actually achieve something are so discouraging. I wish there was a way to maybe buy ingredients at certain points or earn them from completing', 'Very Positive', 93.87, 101.90, 5.03);
INSERT INTO reviews VALUES (24935, 729040, 11298, 'Borderlands 1 is shockingly great. Having played up to 3 I really wasn''t expecting much at all going into 1 but it is really fun. I was blown away by how little jank there was, sure it''s missing a fair bit of qol compared to the sequels, but there really was little to no awkwardness to be found at all.\r\n\r\nApart from that there were 2 things that really stood out to me. The first was how good the gunplay felt, don''t get me wrong it''s not as good as BL3 gunplay, but it''s still really satisfying an', 'I understand that they can force us to comply by making it so that you are agreeing to their terms if you play the games from this point on but if a developer/publisher changes the EULA after sale, the customer should be entitled to a refund if they don’t agree (or are allowed to use what they originally agreed to) Adding DRM after purchase is not okay.', 'Mostly Positive', 79.31, 28.38, 1.33);
INSERT INTO reviews VALUES (24973, 730050, 317, 'Came back to this game after a long time and finally noticed what a hidden gem it was. In a time where the farming/cozy genre is getting saturated, this game truly was and still is a breath of fresh air. It introduces a seemingly similar gameplay of grinding, farming, gifting, unlocking bundles, but done with a vastly unique style from Stardew Valley and most farming games. The setting leans toward sci-fi colony building, and the fact you can combine seeds to make them grow faster or yield more ', 'It feels like an early access. \nIts kinda ugly for my taste and a bit boring.\nResources are easy to find and respawn at the next day I think.\nIt has an energy bar that depletes way too fast when mining/cuting trees, but it moves next to nothing when doing other activities. \n\nHell I didnt even make an hour and I got every fish.', 'Mostly Positive', 78.55, 47.12, 0.77);
INSERT INTO reviews VALUES (24986, 730310, 1103, 'Game got way over hated imo, it was the first time (& now only time) KT did a open world like this for DW & what they did with what they had is good, all i can say is play it for yourself & think yourself bc i didn''t get DW9 for years bc of what others said & i regret it.', 'An unplayable piece of garbage. Can''t figure out how to beat the first bosses. What a piece of worthless trash.', 'Mixed', 57.48, 155.40, 0.98);
INSERT INTO reviews VALUES (24987, 730410, 146, '⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⢀⣠⠤⠤⣄⠀⠀⠀⠀\n⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⣠⠞⠉⢀⣀⣀⣿⣧⠀⠀⠀\n⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⡀⠀⠀⠀⠀⠀⠀⠀⠀⢰⣾⠁⣠⠖⠉⢀⣀⣧⣈⣧⠀⠀\n⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⢀⣀⣀⣀⣷⣄⠀⠀⠀⠀⠀⠀⣠⢾⠛⣿⡁⣠⠞⠉⢀⣯⣀⣈⣇⠀\n⠀⠀⠀⠀⠀⢀⣼⣿⣆⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⡠⠞⠉⠀⣀⣘⣏⠛⣷⢤⣀⣀⡤⠞⠁⣸⠟⠀⡷⠃⣠⣶⣟⣏⣀⣀⣘⣆\n⠀⠀⠀⠀⠀⣾⡿⠛⢻⡆⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⢠⠞⠀⣠⠖⠉⠉⠉⣏⠙⡿⢾⣄⣀⣀⣠⣼⣽⣠⠞⠀⡰⠃⢨⠟⠋⠀⠀⠀⠉\n⠀⠀⠀⠀⢰⣿⠀⠀⢸⡇⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⢀⡏⢠⠞⠁⣠⣴⣾⣿⠏⠉⠓⢾⣦⣀⡀⢻⡿⠟⠁⢀⠞⠁⡴⠃⠀⠀⠀⠀⠀⠀\n⠀⠀⠀⠀⠸⡇⠀⢀⣾⠇⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⢸⣆⠀⡸⢀⠏⢠⠞⠁⣨⠟⠋⠉⠉⠉⢻⡧⢤⣈⣁⣀⣠⠖', 'It is not a bad game, but after about eight hours of play there wasn''t enough variation in the game play to keep me engaged.', 'Mostly Negative', 37.67, 1.92, 8.63);
INSERT INTO reviews VALUES (24989, 730430, 174, 'WOW! A President Donald Trump simulator! Guess I''ll just play it one day at a time over the next four years, I''ll crush this game.', 'great promise but it has a very political slant. The game intro needs to be re-written. Its "okay" that the main character has a crazy back story, but dropping it as exposition midway thru the game is a little lame. Hard to get into character. It goes from serious to funny to satire and you are never really sure what the right tone is. \r\n\r\nChoices are random, the results are counter intuitive. So you are just guessing.\r\n\r\nGreat concept, would love to see part 2 with a much better back story and ', 'Mixed', 67.24, 0.40, 19.95);
INSERT INTO reviews VALUES (25001, 730820, 1495, 'The Year is 1997 and you wake up as a child and play this game in the morning on Saturday after watching cartoons.\n\nThe year is 2025 and you wake up as an adult and play this game in the morning on Saturday after watching Anime.', 'There is a cool artstyle and concept, but the game has this pressing need to constantly remind you that it''s a cartoon. The humor is flat and the third wall is non-existent. The answers to puzzles are too fanciful for me to figure out on my own.', 'Overwhelmingly Positive', 97.12, 8.20, 16.53);
INSERT INTO reviews VALUES (25002, 730830, 360, 'Good game.  Very enjoyable, and difficult.  Took exactly 52 hours, 9 minutes, and 37 seconds to finish.', 'It''s one of my favourite games but this version doesn''t work at all on here.', 'Mixed', 56.39, 52.27, 1.57);
INSERT INTO reviews VALUES (25003, 730840, 250, 'Did more work than Donald Trump. 10/10', '', 'Overwhelmingly Positive', 100.00, 21.90, 0.00);
INSERT INTO reviews VALUES (25005, 730870, 270, 'PLS ADD ACHIEVMENTS FOR EXTREME RATING IN EXTREME MODE SO MY AUTISTIC SELF CAN BE SATISFIED WITH BEING IN THE 0.01% OF PLAYERS WHO MADE IT\n\n\nGame is awesome just as it used to be 15 years ago.', 'i''ll okay is there is so many work station to place ur stuff not just only fucking one \nis this game made for super human to play on later level? fucking god damn it \nso overwhelming with complicate thing annoying sauce mechanic when everyone order the same thing that need time to made like stupid only 1 waffle or bread machine cant even play with RNG speed super power up ./.', 'Overwhelmingly Positive', 98.15, 41.72, 23.95);
INSERT INTO reviews VALUES (25008, 731040, 2415, 'Overall a great experience, but sadly the game also has some problems like graphic flickering and fps drops ... also I feel like the voices could be way louder in some parts, but I still recommend the game, especially if you liked Firewatch.', 'The game is beautiful, and the acting is very good.\r\n\r\nThough basically you press W and sometimes click on things for 6 hours. The story is a okay, but the problem with a mystery like this is that through the course of the game you invent your own story, your own expected outcomes that are much more interesting than the game can actually offer.\r\n\r\nIf you can call it a game. It''s a so-so story, well made, that you ''walk'' through. Fine to kill some hours, but the conclusion was a great anti-climax', 'Very Positive', 87.08, 6.50, 6.92);
INSERT INTO reviews VALUES (25021, 731490, 6035, 'at first you''d be like "oh nice, a game for kids with funny animals", but then you realize it''s about pain and suffering', 'Okay so short review, here''s the thing. This game is a perfectly passable update to the original games, which are as fun as they ever were. That said, as someone who really appreciates and relies on subtitles, I''m shocked and kinda pissed they didn''t take the time to add them to this. It''s a basic accessibility need in this day and age, and to re-release three games without this basic improvement is mind-boggling to me. So ya, fun games but apparently the devs didn''t really care about improving ', 'Very Positive', 91.96, 13.30, 19.32);
INSERT INTO reviews VALUES (25042, 731920, 137, 'A bit basic on many levels, but .... it just gets you and before you know it you have gone through several years of simulation.  Just plain fun.  Can''t wait for #2!', 'This game is left wing propaganda. It should be called "Increase Taxes Simulator". The game logic is very primitive.', 'Mixed', 46.72, 63.45, 23.30);
INSERT INTO reviews VALUES (25049, 732050, 802, 'feels like openttd with some aspects from games like factorio. \r\n\r\nas of now, progressing in the base game is a lot slower than openttd, however i feel as though the game incentivises you to use more of the vehicles/resources available to you as it is much harder to progress in this game unlike openttd.\r\n\r\ni do feel as though a lot of essential features are still missing, such as level crossings and multiplayer, and with how slow development is currently it is very hard to justify the high price', 'No, I will not recommend this game. It looked fun at the start, but after 4 years it is just lacking updates, features, and communication.', 'Mostly Positive', 76.31, 4.48, 6.10);
INSERT INTO reviews VALUES (25055, 732240, 517, 'This game is really awesome. It is absolutely nowhere near a AAA title but its huge and feels very alive. If you have ever played Freelancer, this feels like a modern version of that and its so fun. \n\nIf this dev(s) were given a AAA budget we''d have the best space sim ever made, I do not doubt that. Give this game a try and then go play the sequel.', 'TL:DR The only good thing about SpaceBourne is the combat. Everything else is garbage with no sense of progression.\n\nAs another reviewer pointed out SpaceBourne basically has no sense of progression at all. Even after 20 hours of play the game flow feels the same even after getting a variety of different skills, ships, weapons, etc. A lot could be forgiven if the game had a decent story or exploration both of which SpaceBourne completely lacks. In the end the only competent aspect of the game is', 'Mostly Positive', 73.89, 5.30, 20.52);
INSERT INTO reviews VALUES (25059, 732370, 288, 'its a really fun co op action game, great couch game to play with your girlfriend/wife who doesnt play games noramlly', 'Top-down shooters are one of my favorite genres - I adore them, even the not-so-good ones. This one, though, I couldn''t enjoy.\n\nIt is GORGEOUS - it is also painfully slow, controls terribly, the combat is boring and the difficulty is non-existant - you will only die out of being too eager to kill the bosses, who have boring invincibility mechanics and take forever to kill.\n\nGreat work by the artists absolutely ruined by awful gameplay. Stay clear.', 'Very Positive', 84.72, 9.45, 0.45);
INSERT INTO reviews VALUES (25062, 732430, 7690, 'I play this game when the group is arguing about what to play. I play this game when I''m waiting for something else to download. I play this game when I''m stressed and need to take a few minutes to collect myself.\n\nThis game is on my all time favorites list.', 'No first person view.', 'Overwhelmingly Positive', 96.94, 6.62, 0.17);
INSERT INTO reviews VALUES (25069, 732690, 7252, 'very scary ahhhh! Made me shoot a white substance in my pants thats how scared I was!!111', 'Not worth the price at all, bought it when it came out and almost finished it the same day.', 'Overwhelmingly Positive', 96.07, 17.98, 2.40);
INSERT INTO reviews VALUES (25074, 732810, 663, 'Slipstream is a very good driving in a retro ambiant with lots of levels, few cars, very good soundtracks and great pixels graphics. I really enjoyed this game and played for hours!!! I highly recommend it!!! 💜💜💜', 'I want to preface by saying I love this game, and it''s great to play on the nintendo switch. HOWEVER...\n\nI bought it here on steam with the sole intention of playing it on PC with a friend who does not own a switch. Turns out, it is not possible to play multiplayer online. For multiplayer, it expects you to connect additional controller input to your computer, which was impossible for me and my friend since we live in different states. $10 down the drain, VERY DISAPPOINTING!\nAdditionally, it see', 'Very Positive', 91.25, 31.95, 0.12);
INSERT INTO reviews VALUES (25086, 733050, 196, '3 hours + game play, very fun and challenging! Worth it for the price!', 'Was enjoying it until I lost all my progress about a quarter of the way through. Meh, not too far into it but I don''t wanna risk that again.', 'Very Positive', 89.29, 3.40, 4.00);
INSERT INTO reviews VALUES (25088, 733070, 463, 'Sudoku Universe is the classic japanese game. There''s lots of  levels with easy, normal and hard difficult choices. The designs are nice and the soundtrack is relaxing... I recommend it!!! 💗', 'This game requested "keystrokes from any application". Keylogger? No thanks. Uninstalled as malware.', 'Very Positive', 89.42, 27.00, 0.25);
INSERT INTO reviews VALUES (25090, 733110, 228, 'Don''t let the name trick you, this game has a great story and great systems that harken back to old ones. It''s packed with solid characters and solid content, and none too easy! Definitely give this one a try, a hidden gem.', 'good visuals but a lot of hand holding and filler dialogue, hard to stay engaged outside of cutscenes with big vfx. i want to like it, but its just OK. generic modern names breaks fantasy immersion for me. charlie is kind of a brat and other characters seem low depth. will maybe play  again but shelving it for now.\n', 'Overwhelmingly Positive', 95.18, 38.93, 3.23);
INSERT INTO reviews VALUES (25092, 733210, 499, 'Bought this on sale but it was worth more then full price. \nFrom the beginning you given a mystery that needs to be solved, and as I interacted with the game I found myself getting emotionally invested. Everything from the atmosphere to the characters to the writing, oh my goodness the writing was superb! It had elements of self-awareness that had me lmao-ing, which helped to lighten the darker themes explored through the story. The game isn''t long(only took me a few hours to finish the main sto', 'So I absolutely loved Pinstripe. The art, the music, the story, it was wonderful. Of course I was excited to play Neversong! Unfortunately, it just didn''t hit the mark for me.\r\n\r\nThe story is lackluster and simple, the puzzles are more annoying than fun, the ending isn''t satisfying, and the boss combats are soooooooooo boring. I''m not happy I spent the money on this. It''s more of a $5-$8 experience than $15. Buy it when it''s on sale, but not at full price.', 'Very Positive', 87.78, 12.52, 5.10);
INSERT INTO reviews VALUES (25095, 733300, 208, 'A little bugy but very delusional,dialogues are fun to read.\r\nrpgmaker game with sorta meta game?Awesome!', 'While the art and music are good, and it does deliver one very cool scare, the story dropped off a cliff early on and never recovered. The vibes and tone just didn''t work for me, or (in my opinion) with each other, and the whole package feels like it got 70% of the way there and just stopped. There''s odd oversights in the gameplay (notifications that pop up when inactive) and the sarcastic dialogue never lets the dread live and breath. Gameplay-wise it''s also fairly basic, just collecting whatev', 'Very Positive', 92.79, 6.00, 2.25);
INSERT INTO reviews VALUES (25096, 733340, 245, 'i want to romance hot japanese men: the sequel', 'Experiencing random crashes and the game is not saving my save data', 'Very Positive', 93.88, 77.92, 0.13);
INSERT INTO reviews VALUES (25100, 733460, 219, 'Accessible and relaxing. Worked to a playable on my slightly-better-than-potato laptop. For me, it was indeed a little laggy towards the end game, but I was OK with that. It was fun. I beat the game at just over 35 hours of gameplay. That''s how long it took me to do one class! To be fair my potato can only play at the lowest speed and I was learning as I went.\r\n\r\nTech support is great, too.', 'Game feels unpolished and unintuitive compared to other more popular games with similar style of controls. I usually like this kind of games and wanted to give it a shot but after 5ish hours I just couldn''t play it anymore.\n\nI don''t want this to sound like it''s a completely bad game, but definetly not what I expected and not for me.\n\nI see some people are comparing it to Factorio, I don''t see how is this similar... in terms of rating compared to Factorio I played Factorio over 1000 hours and thi', 'Mostly Positive', 72.15, 71.50, 5.80);
INSERT INTO reviews VALUES (25118, 733790, 1285, 'This game is ok. It definitely has taken inspiration from papers please, and tried to place it in a more contemporary setting. The design of the graphics, sound and music is very good. The design of the game and it''s UI is less good. Many parts of it are a bit difficult to figure out, which is maybe kind of the point, but it still feels awkward. And some parts are just plain nonsensical, like the save slot management system.', 'It has it''s charm yes. However I found this game more enjoyable to watch than actually play. It becomes frustratingly repetitive and on the whole boring for the amount of irritation it brings. The BIGGEST issue is the inconsistent UI. The date format is different in THREE separate places on the screen at the SAME time and in a game where checking dates is paramount it makes it unfun.', 'Very Positive', 87.78, 11.23, 0.62);
INSERT INTO reviews VALUES (25119, 733800, 104, 'I''m having difficulties with Frosty Nights no matter when i played the snowman tutorial I crashed or bugged', 'I mean what can I expect from a game with that title by a small developer? \nBut what I expected was, that this game is VR supported when it says so in its description. The VR port is absolutely awful and an insult.', 'Mixed', 64.42, 1.93, 0.25);
INSERT INTO reviews VALUES (25126, 733990, 1229, 'Let''s go gambling!! EERRRR Aw dang it, EERRRR Aw dang it, EERRRR Aw dang it, EERRRR Aw dang it, EERRRR Aw dang it, EERRRR Aw dang it, EERRRR Aw dang it, EERRRR Aw dang it, EERRRR Aw dang it, EERRRR Aw dang it, EERRRR Aw dang it, EERRRR Aw dang it, EERRRR Aw dang it, EERRRR Aw dang it, EERRRR Aw dang it, EERRRR Aw dang it, EERRRR Aw dang it, EERRRR Aw dang it, EERRRR Aw dang it, EERRRR Aw dang it', 'Behold my time, take it not as a testament, but a warning. Beware the ignorance I once held, and take shelter unto better games.\n\nIf this game did not ask for your over a week, your precious time, hogging the resources on your computer to get all the achievements I would recommend it. It’s a stupid simple clicker time waster poking fun at the game industries reliance on gambling to make money. Your progress is purely at the feet of RNG, who expects you to sacrifice your time in the name of ‘coll', 'Very Positive', 91.62, 0.22, 196.68);
INSERT INTO reviews VALUES (25130, 734120, 113, 'Short, but interesting horror game. It has unique concept that will definitely intrigue you. It is quite short, but will provide you with amazing experience.', 'Nope. Pretty much as weak-sauce as it looks. I don''t want to be mean, but the controls are bad. In a way which feels neither intentional nor part of the Unreal Engine out of the box. MOVING is broken. I was constantly struggling to just DO things. I started getting a headache before long because it felt like I was trying to pick up my keys with my feet... while wearing my shoes.\n\nBonbon gets good for half-a-second when you feed cake to a giant rat, but then you literally sit in a bed for three m', 'Mostly Positive', 75.22, 0.93, 0.50);
INSERT INTO reviews VALUES (25152, 734920, 151, 'Meanders is a pretty relaxing game about jumping from platform to platform and hitting things with a projectile.\nIt''s a decent time waster, not amazing, but not bad either.\nI recommend if you have nothing better to do with your life.\n8/10', 'This game feels almost like an asset flip, quantity over quality at every step. The movement is janky, the visuals are simultaneously minimalist and overbaked, all of the individual elements are mediocre in their implementation and don''t build anything past the sum of their parts. The level design is asinine, with "puzzles" more about figuring out where the objectives actually are than about any kind of creative problem-solving, and the obstacle course nature of the levels is more frustrating th', 'Very Positive', 92.72, 1.62, 1.03);
INSERT INTO reviews VALUES (25159, 735280, 466, 'Emergency 20 is less complex than Emergency 4, which remains the king of the series, but I''ll say it, I think this game got too much flak.\n\nMany people don''t remember vanilla Emergency 4 because of how much time they spent playing modded versions of the game. The vanilla Emergency 4 was itself quite bare bones compared to the huge mod projects which added so much to the games experience.\nThis highlights the problem I think this game has. The modding scene never really took off. I don''t know exac', 'I know the games from my childhood. But holy they dumbed it down a looooot', 'Very Positive', 80.04, 104.17, 0.40);
INSERT INTO reviews VALUES (25160, 735290, 606, 'In terms of mechanics, Genesis Noir is an atypical point-and-click adventure game in which the puzzles have a loose, experimental feel. Instead of classic puzzles, the player immerses himself in surreal spaces, manipulating time and sound in a way that is more intuitive than logical.\r\n\r\nThe pace of the game is slow and contemplative, building an atmosphere of melancholy and reflection. This is not a title for fans of dynamic action - it''s all about the emotional experience, creating a cosmic mel', 'I really, really wanted to love this game, unfortunately, I''m just not sure that I could recommend it to anyone - at least not without a few warnings/caveats. In brief, if you are buying the game on sale, then I think it is probably very ''worth it'' for you. Genesis Noir is ambitious in its art direction and less-than straightforward storytelling. It''s an interesting game if you are willing to give it some patience, you don''t have light sensitive epilepsy (or sound sensitivities), and you don''t m', 'Mostly Positive', 77.39, 4.52, 4.68);
INSERT INTO reviews VALUES (25162, 735350, 128, '“Bottle Pilgrim” belongs to the walking simulators genre, telling a sorrowful story about the demon alcohol and family tragedy. As you walk the path across verdant mountain jungle, through caves and alongside the seacoast, you listen to the main protagonist’s narrative (read in pleasant male voice), collect hidden drawings and uncover a secret or two. As it’s become the norm with this franchise, gameplay is strictly linear and episodic, with several intermezzos of past reminiscences where you ne', 'I could write multiple paragraphs critiquing various aspects of why I don''t like it but I will just simply say it''s not for me.', 'Mostly Positive', 74.22, 1.73, 0.88);
INSERT INTO reviews VALUES (25173, 735580, 259, 'This is an all-round beautiful and artistically sophisticated game in the setting of World War I. 11-11: Memories Retold consists of a variety of well-composed, deeply emotional scenes, underpinned by gorgeous painterly graphics. The art style is the star of the show here. Just looking at a random screenshot taken from the game feels like entering a different world through a piece of art. You can stop at any given moment in the game and I guarantee that wherever you are, the scene will look like', 'I don''t know what the point of this game is. It doesn''t teach you about WWI because its presentation of that conflict is plainly unrealistic to the point of going "over the top" in a battle and feeling all the danger of the produce section at the grocery store. It''s not to convey some kind of point about morality or loss because it doesn''t covey any such thing beyond "it''s bad when someone you care about dies, and also killing is bad." And the point is certainly not to tell a good story, because', 'Very Positive', 91.89, 5.90, 5.63);
INSERT INTO reviews VALUES (25182, 736190, 1510, 'I tried so hard and got so far\nBut in the end it doesnt even matter', 'Disappointing parents IRL is enough', 'Very Positive', 92.52, 5.93, 3.20);
INSERT INTO reviews VALUES (25184, 736220, 11421, 'This game has come a long way since Offworld took over. If you are thinking about buying this, do it! We need more players!', 'It has unique mechanics, more content in terms of maps and vehicles than Hell Let Loose. But besides that it still has all the problems of Hell Let Loose, but with worse graphics, worse performance, more game-breaking bugs that cause hard crashes, 1/10th of the playerbase, etc. Needs more time to be polished.', 'Very Positive', 80.28, 64.67, 7.52);
INSERT INTO reviews VALUES (25188, 736260, 11171, 'Do you want to stare at a screen, touching nothing, brow furrowed, for hour after hour? This is the game for you. It''s like dark souls, except the boss is some stupid little collection of stupid words that are stupid. And mean. And lame. I don''t need words anyway!\r\n\r\n10/10 highly recommended.', 'Having an amazing introductory part that feels like a sandbox, it quickly shows its hardcore puzzle teeth once you must find one — and only one — particular solution to a level, in a long and complex set of moves that you might not have any idea about (until you apply several hours of brute force, or just look up the solution on YouTube).\r\n\r\nIt''s really fun for the first couple of hours, but trust me, it gets unbelievably hardcore very quickly, and not in a good way (so here''s my thumb down). Ev', 'Overwhelmingly Positive', 97.93, 14.35, 3.08);
INSERT INTO reviews VALUES (25200, 736570, 629, 'The negative reviews of this game seems to be pi**ed off they didn''t get a 8 year old Senuas Sacrifice for £3. The game is a classic in the genre and deserves respect on that term. The story is above average for an indie game of its'' time and the developer is definitely a big Silent Hill 2 fan. If you''ve never played monkey Island or Skipper and Skeeto you might struggle with some of the puzzles but honestly i completed it in less than 4 hours without a guide and i enjoyed it so much i played th', 'Great story but the final battle is almost impossible to actually beat because the boss''s movement speed is too fast. You have to have a literally perfect reaction speed to hit him without getting hit yourself. For a game that''s supposed to be a narrative puzzle solver, this is really annoying to have to deal with. Most people would be better off just watching an old letsplay of the game than playing it themselves unless the dev suddenly decided to come back and rework the game a bit', 'Very Positive', 93.48, 8.00, 7.53);
INSERT INTO reviews VALUES (25207, 736810, 136, 'The amount of detail poured into this story is absolutely mind boggling! The voice acting is amazing and there are thousands of lines of dialog. The characters are very interesting. The game has 5 chapters and it''s a very long game. Sadly the in game puzzles are sometimes very tedious on par with Monkey Island. I know that''s a beloved franchise, but so many times we quit that game in frustration because the item combo puzzles were drawn out, far fetched and didn''t always make sense, or even wors', 'Beware.\n\nMost of the game is ok''isch, nothing exciting but quite nice. Sadly it also introduces deathloop as a game mechanic later on. Thats a particulary nasty game mechanic: literally guess what the developer thinks now fast enough or die. Over and over again. Sadly the solution is not obvious (nor clearly visible) so this sucks quite a bit of fun from the game.\n\nThis mechanic is introduced a little into the Game, there is no indication that this will happen, so when it happens, the timelimit ', 'Very Positive', 80.88, 15.32, 7.28);
INSERT INTO reviews VALUES (25208, 736820, 1914, 'It''s a great mix of Europa Universalis lite with some Total War-like combat mechanics and vibes. If you''ve ever played a TW game and thought, "it''s great, but gee, I wish it was a bit more like Europa Universalis or Crusader Kings", or played a Paradox game and thought "it''s so good, but I wish it was also a little bit like Total War", then, brother... this is the game for you!', 'Good single player. but devs wont fix multiplayer and instead give advice for changing network adapter settings. So i cant play with friends without doing some insane work around.', 'Mostly Positive', 76.12, 25.22, 20.95);
INSERT INTO reviews VALUES (25211, 736850, 848, 'I have absolutely no idea what is happening but I recognize that''s a me problem.', 'Not the worst gameplay in the world, which is a start for a game about being a revolutionary tribune. I dislike the game moreso for its inability to properly engage with history on a macro or a micro scale. On the micro side, the game doesn''t capture the feeling of the French Revolution in any specific sense, opting rather for the sort of trite generic video game revolt you can find in so many other games depicting similar events. There is no sense of allying with factions in the Convention, or ', 'Mostly Positive', 70.28, 1.57, 14.08);
INSERT INTO reviews VALUES (25229, 737520, 163, 'This review would definitely be subjective, but I can say without a shadow of doubt that this has been the most enjoyable game combat experience I''ve ever had. To start things off, I struggle with ranged weapons, so us being given melee weapons  was already such a win for me. As if the sword wasn''t good enough, I was ENTHRALLED when we obtained the swift-attacking Battle Gloves. Weapons with high attack speed fit me best because they allow me to retreat from bashing opponents at the last possibl', 'It''s not a terrible game, it''s not a broken game, but it is a mid one.  \n\nIf you don''t mind an unexceptional filler, this might suffice, but most will probably be better off trying something else on the market, like Yooka-Laylee and the Impossible Lair.', 'Very Positive', 81.60, 14.97, 0.47);
INSERT INTO reviews VALUES (25244, 737890, 144, 'GOOD', 'I returned the game because the audio does not work if you use it through family sharing. However, there were many other reasons that this game fell short, many of which others have touched on in their reviews. One thing that I found disappointing is you do not get to see the ship you are attacking which seems like a huge oversight when the basic premise of the game loop is take down the other ship before it takes you down. If you can''t see the product (other ship being fired on and visually tak', 'Mixed', 65.97, 5.25, 0.25);
INSERT INTO reviews VALUES (25268, 738520, 5126, 'Why did I waste my time building that cool base and car when I get forced into a weird fetch quest with a stupid space ship far from either of those things. what a dull and poorly made way to finish a pretty good game', 'I REALLY want to like this game. I got it when it was during early access. And I adore the developers sense of humour. In fact the humour and story is all that kept me going for this long. I adore survival games. I love subnautica. But this? It just isn''t fun. There''s nothing fun about having to backtrack to find rubber, or alluminum, to obtain the one item you need to progress. There''s nothing fun about slowly moving forward in a straight line with nothing to do but hold the shift key occasiona', 'Mostly Positive', 73.06, 15.88, 21.05);
INSERT INTO reviews VALUES (25269, 738530, 803, 'Fun game! did not expect the "dating sim" part but still fun, great for planning paintjobs!', 'cant be that bad right? i had to try for myself, its so bad. Building? AMAZING. Combat? ABYSMAL. id rather have a colony dropped on me', 'Mixed', 54.05, 43.18, 2.33);
INSERT INTO reviews VALUES (25270, 738540, 1648, 'Tales of Vesperia is one of the peak Tales of flagship titles, but it can''t be denied that its age shows.\n\nI consider it one of the stronger entries storywise, with its semi-environmentalist message and well-developed main and side characters. That said, anyone who has played the newer Tales of games before trying this one will have to get used to a significantly less fluid combat system and a much clunkier game overall. \n\nI''d recommend this game to everyone who is already a fan of the series. A', 'The sound does not work in Remote Play.', 'Very Positive', 84.77, 89.85, 0.30);
INSERT INTO reviews VALUES (25271, 738550, 120, 'Has to be one of the most unintuitive controls ever\nBut once you figured it out its satisfyingly good\n\nA lot of bugs tho\nIf only it had EA money', 'Have PC that runs maxed-out cyberpunk only to chrash this game after 30 seconds of booting it up.\nSeems fun tho.', 'Mixed', 50.00, 0.98, 0.15);
INSERT INTO reviews VALUES (25276, 738610, 116, '....', 'You cant lose and you dont have todo anything while youre playing the game, the game just is playing itself, just relax and watch you howre money is growing, i dont see any "simulation" here just a relaxing game where you can build youre "dream" train station.\nAs iam wanting a more chalanging and rewarding game its nothing i could recommend. Walls are not importent, the bus station are just show, people came either way if you offer a ticket maschine...the rest is just for youre decoration and bo', 'Mixed', 58.62, 8.52, 0.32);
INSERT INTO reviews VALUES (25295, 739080, 179, '100% achievements in 11.7 hours.', 'I DON''T LIKE IT (NOT USER FRIENDLY)', 'Very Positive', 84.36, 11.70, 0.28);
INSERT INTO reviews VALUES (25297, 739130, 110, '\nThe game I have been waiting for 2 years. participated in tests, and waited, waited, waited. A lot of things changed in it, it got better harder and I can’t believe that today it has already loaded and you can play it in its entirety. It is filled with difficult moral choices, difficult characters and opportunities to ask yourself questions that in real life will be scary to ask.\nI look forward to a complete immersion in a dark, scary, mysterious world. buy play, and join discussions', 'XML tags in tutorial dialogues, untranslated russian text in English version...\nThat would be acceptable in early access, but it''s a full release. They really should hire some QAs. If they didn''t bother to even proofread the  tutorial , it doesn''t leave a good first impression.\nI may change the review if it gets fixed', 'Mixed', 49.09, 4.18, 4.87);
INSERT INTO reviews VALUES (25300, 739190, 134, 'A short, about 40-60 minutes long, funny game about an ant who dreams of visiting Paris. The design reminded me of the Samorost series overall, but here the main character''s facial expressions stand out very much, kinda rough but kinda hilarious too. The puzzles are not hard but the logic was mostly lost on me and hints don''t really help, mostly what I''d like to see here is a way to highlight interactable stuff, map is sorta the same way as in you really need to poke at everything to find your w', 'I really want to like the game, but I just can''t keep playing. I appreciate the art style and the little jokes, but for me the gameplay is too vague and random. It''s very difficult to see what''s clickable and the solutions to the little puzzles do not make sense for me. I find myself keep asking for hints and that''s just not enjoyable.', 'Mostly Positive', 74.63, 2.12, 1.65);
INSERT INTO reviews VALUES (25308, 739540, 429, 'Half Thomas Was Alone, one-third There Is No Game, and a little Undertale thrown in... but ALL awesome, with a great (albeit unoriginal) soundtrack, interesting characters (Satan was my favorite), lots of groovy firearms and McGuffins to collect, and some super-fun thought-provoking existential dread!  Short and silly in places, but definitely underrated and...\n\nWhat''s that?  You say you don''t find existential dread particularly thought-provoking or fun?  Oh well... sorry, Kevin, I tried...\n', 'Simply put.. it''s a bad game and a waste of time and money. You''ll have more fun staring at a wall.', 'Mixed', 68.30, 8.98, 1.43);
INSERT INTO reviews VALUES (25309, 739630, 328638, 'Phasmophobia is the perfect game if you’ve ever wanted to scream like a toddler. The graphics and scares are great, and your friends will absolutely abandon you in your moment of need (and you’ll do the same to them, it’s fine) It’s like playing Ghostbusters but with less science and more running for your life. Highly recommend if you enjoy panic attacks, dark hallways, and a complete lack of teamwork.', 'This game used to be such a fun playing with friends but after the progression update it has become over complicated and grindy to a point it''s no longer fun. The shopping UI is messy and too much stuff is locked behind too steep leveling system. Much more simple game play was previously perfect for casual playing with your friends but the current one is too much of a bother.', 'Overwhelmingly Positive', 96.24, 642.33, 103.85);
INSERT INTO reviews VALUES (25310, 739650, 567, 'I feel sad that I didn''t gave this game a try back when it got released.\nThe game is absolutely  fantastic and cute .Love the Drakes they are so adorable . This game is definitely  for those who wants a basic and not too stressing gaming experience. Exploring the map and locations are quite fun as it doesn''t  feels any grindy. It''s a game for all age groups even though mild violence is there .Story so far is going great and I believe  it''s going to get even better later.\n\nThe visuals and graphic', 'they just abandoned the game'' and it''s way too grindy', 'Mostly Positive', 76.72, 1.03, 1.43);
INSERT INTO reviews VALUES (25314, 739720, 127, 'This gem of a game deserves far more praise and recognition than it gets! While it is light on the hand holding (which I prefer) it also doesn''t feel particularly grindy (which I appreciate).', 'Early access aside, this game was launched in 2018 and it still hasn''t been updated further?!?! And you get money from people so when do you play on updating it more?', 'Very Positive', 88.19, 16.85, 18.62);
INSERT INTO reviews VALUES (25326, 739980, 117, 'Let''s not stay friends is a short otome (girl x boy) visual novel by the Russian developer group Violet Feature. You play as a young woman called Inske, who happens to be a student enrolled at a Magic Academy. Soon there''s an outdoor exam that all students must go through, and depending on your choices, one of Inske''s friends will accompany her and something more will happen between them. \n\nYou have three romance options: Frenz (the childhood friend), Taf (the school playboy), and Burain (the sm', 'Art is beautiful, UI and design is great, but the story is boring and bland. Dialogues are uninteresting, and nothing ever really happens. The romantic scenes aren''t even interesting enough to make up for it. Only remotely interesting character was Burain, and even his story wasn''t super interesting. Don''t recommend.', 'Mostly Positive', 76.92, 2.45, 3.25);
INSERT INTO reviews VALUES (25331, 740080, 213, 'Im a simple man. If I play a game saying "only 10 more minutes" for an hour, I recommend it then', 'Overall good ideas in mechanics and overall good execution but severely hindered by a small few critically bad design decisions. The most egregious problem is that most of the effort that has gone into balancing the rest of the game goes to waste because of the surprising prevalence of powerful explosions with little warning which can easily wipe an entire team of survivors in an instant. After learning how to get past the early game, this has been the cause of every single one of my failed runs', 'Very Positive', 81.69, 2.42, 7.82);
INSERT INTO reviews VALUES (25333, 740130, 10569, 'You pull a sword out of a really hot girls tiddies then use it to kill some guy named Ball Sack. The hot girl realizes you are the only one capable of using the tiddie sword so she asks you to go on a journey with her and use the power of the Tiddie sword to slay a bunch of lords. If you''re waiting on FF7 Rebirth to come to pc and looking for something to scratch that final fantasy itch in the meantime, this game will do. The graphics and art style are gorgeous and are definitely the games stron', 'The game had an interesting start as it introduced you to its world but it kinda fell flat in the final arc, I honestly mentally checked out by then and just wanted to get it over with, hoping that the ending would rekindle the love I had for the game during the first few chapters but boy was I wrong.\n\nOverall the game was decent and memorable enough but I just wish they wrote the antagonists a bit better. They were all bordering cringe with no redeeming quality. The pacing was also all over the', 'Very Positive', 88.47, 119.68, 45.62);
INSERT INTO reviews VALUES (25344, 740290, 177, 'Scary as heck and you can die', 'Overall Rating: 4/10. Being honest it''s been a while since I played the game. I remember it being fun for a Holiday themed horror game, and it had some decent jumpscares. But overall the puzzles felt simple, most of the scares and the "antagonist" if you could call it that, felt cheap and the story line just wasn''t there. There are better holiday horror options.', 'Very Positive', 86.44, 1.67, 1.58);
INSERT INTO reviews VALUES (25373, 741140, 325, 'Holy Mecha Kino, the combat is addicting and immersive. Once you master dodging incoming attacks and pulling off devastating combos of aerial attacks, you truly feel like the best vanguard simulacrum pilot in the world that you are supposed to be—the untouchable hot dogger. *Restoration 〜Reticent Sky〜 starts playing* "Fight me... If you win, I''ll give you my virginity. If you lose, I''ll take yours! You''re not gonna run away are you... Kou?!" Best girl.', 'The Steam version doesn''t work. Even pirating the game and playing it on your hard drive doesn''t work. Something in Windows 11 won''t allow it to play. There is only one workaround I have found. \nBuy on GOG. It works there for me. It even still had my save files that I could load. \nAnd we all know Microsoft won''t fix anything for just a single visual novel. \n\n', 'Very Positive', 92.62, 144.28, 4.18);
INSERT INTO reviews VALUES (25375, 741250, 169, 'the sexual tension between me and lullaby', 'snoozefest', 'Very Positive', 93.49, 6.45, 18.85);
INSERT INTO reviews VALUES (25382, 741430, 193, 'im gonna be very very real here THIS GAME is actualy awsome as A. this game practically is a 4 in one game theres great story good writeing amazeing plot and 2 tours you can take. The 5 hour segment that showed the sinking was amazeing it can cover 2 hrs in  5 minutes somewhat you hop onto a lifeboat and watch evrything unfold. i was actualy crying during one part of it  they did a great job with this game with omost perfect voice acting and its realy realistic for a game like this as most other', 'index controller not supported', 'Very Positive', 82.90, 12.47, 0.12);
INSERT INTO reviews VALUES (25386, 741510, 807, 'Hotline Hong Kong', 'Just play Hotline Miami.\n\nIf you''ve already played Hotline Miami...play it again.', 'Mostly Positive', 73.98, 0.12, 0.67);
INSERT INTO reviews VALUES (25392, 741670, 489, 'When I first opened it, I thought It would be an Awful Game, but now I see this game has EVERYTHING!, Guns, Units, Attachments, and much more, It''s perfect for those who do not have much money or a good PC, But want good WWII experience, one good thing is that you can customize entirely your loadout, You don''t like the sniper scope? Remove it! You don''t like the charger? Take it off! You don''t like the gun itself? Throw it away!', 'I haven''t played easy red 2 but I pretty much wouldn''t recommend the first one.\r\n\r\nSandbox Omaha sounds cool in theory and is interesting for a few rounds,  but in practise it gets boring fast.\r\n\r\nIt''s not a badly made game at all, it''s just not that fun.', 'Very Positive', 80.78, 8.67, 1.98);
INSERT INTO reviews VALUES (25395, 741820, 402, 'Classic Hide N Seek mode :)', 'I wanted to try this in VR, but boy it was a disappointment.\n\nThe control scheme is ONLY teleport with physical turn in your playspace.\n\nI mean no snap turn, no smooth turn. No turning from controllers. Teleport only is also VERY outdated way to move in VR. And there is no way to customize period. This alone was disappointment enough to not even try to progress from the starting room. Game looks good and runs good. But VR is a no-go.', 'Mostly Negative', 30.85, 0.47, 0.22);
INSERT INTO reviews VALUES (25400, 742120, 4676, 'One of the greatest RPG''s ever made\r\nRIP Akira Toriyama', 'Fuck Square Enix for releasing a definitive edition with nothing new except worse graphics than the base game and a 2d mode they expect players to pay $40 for the game a second time to access\n\nReally stupid choice just a complete middle finger to the consumer, I''ll never buy another SE title within 3 years of launch especially not a standalone title like this', 'Very Positive', 84.05, 234.12, 103.93);
INSERT INTO reviews VALUES (25405, 742250, 203, 'May you reach the stars, and shine upon us.\nTo the cosmos.\n\n\n빛이 우리를 감싸고, 모두가 은하에 닿을 수 있기를.', 'It is definitely more of a comic book than a game. Furthermore, it has the typical Chinese game design where it tells you what to do at every single step (a big flashing finger tells you where to click). There is no freedom for the player, which I guess I understand why now that I type this out.', 'Very Positive', 91.63, 5.57, 0.37);
INSERT INTO reviews VALUES (25406, 742300, 1656, 'A near ideal sequel showing Capcom actually does have the power to make good MM games, but deliberately choose not to for some reason.\r\n\r\nThis is the best spite-game I have ever played. 9/10, it was made with hate.', 'This game is literally unplayable, and since I got it during a sale, it''s also literally un-refundable. I was really looking forward to trying this game out, but it straight up will not load past the start screen, and not only is this a common issue that has been there since day one, apparently, neither Steam nor Capcom have even *tried* to fix it. I just want to play the damn game, please... stop with this whack ass Denuvo crap, ffs...', 'Very Positive', 88.35, 10.82, 0.52);
INSERT INTO reviews VALUES (25410, 742420, 2403, 'Honestly the game''s good. It''s fun, the characters aren''t annoying to me, it''s got plenty of things to do, and the fashion options for the boss are great. I guess the launch was kinda rough but at this point it''s solid.', ' Saints Row: Gat''s Broke! \nTo start, it''s not as bad as people say, but still, this is the worst Saints Row ever released. Volition should be ashamed for butchering their franchise this badly. The boring storyline, annoying characters, and frustrating combat with zero to no comedy make this game an insult to fans of the series. I was tired of shooting an entire magazine to kill a random bum with armor or imagine a situation where you have to shoot a guy (with no hat armor) six times in the head.', 'Mixed', 61.34, 47.02, 47.32);
INSERT INTO reviews VALUES (25411, 742460, 213, 'Pretty nice; I play it once in a while. I enjoy it because it feels like Marble Blast Ultra, however it is a little less polished', 'This game is kind of a mess despite it feeling kinda good. Also, Marble Blast is probably the game you are looking for, and I''m pretty sure Marble it Up is the games fallow up. This, I''m not sure what this is. Maybe don''t get it.', 'Very Positive', 81.22, 2.37, 1.20);
INSERT INTO reviews VALUES (25416, 742520, 367, 'About 10 hours with a smile on my face. Brilliant little project! Play Your cards right and get coitus post consultatio ;)', 'If Shakespeare (who features in this!) was a video game; a bit snobby, "highbrow", artsy-fartsy blah, an interesting interactive museum exhibit maybe, but not much of a game. Clearly made with love but unless you have a keen interest in a very specific period of history maybe it''s not for you, as it wasn''t for me.', 'Very Positive', 94.55, 10.12, 3.88);
INSERT INTO reviews VALUES (25419, 742700, 118, 'I''ve been playing this game since the 1980s.  It''s a great game and more people should play it.', 'Having played the Empire series since the late 80''s, I put off buying this game because I was afraid that I was going to be disappointed.  I was afraid that it was going to be not much more than the same game with a new UI and I my fears were not far from the mark.  It feels like to me that the game has been dumbed down as happens with so many games these days.   Things like the Command Queue and the Processing Queue were two things that I found very useful in the earlier iterations of the game ', 'Overwhelmingly Positive', 95.76, 2298.38, 271.72);
INSERT INTO reviews VALUES (25428, 743130, 565, 'A good game, but a little on the thin side. The tutorial isn''t really much different from the regular game except for starting with a few more resources and being extremely limited on which achievements you can unlock there for some asinine reason. I picked this one up in early access and came back to it about a year after it went gold, and honestly the difference between the beta and the finished game was a lot less than I was expecting. Even with the addition of all the technology trees that a', 'The game is very shallow: you go out of your base while you have oxygen, play fetch for a few more rocks or an alien artefact that you exchange with tech points. Rince and repeat, and slowly grind to the rocket to (finally) get out of here. But the devs drew a cat face on your character and made a cat pun, so that''s that. It''s not terrible, but even on sales there are much better options for your time.', 'Very Positive', 92.57, 59.43, 6.42);
INSERT INTO reviews VALUES (25439, 743390, 577, 'Amazing Writing! Prepare to be surprised by how deep the story of this game. I never thought I could learn more about depression and hope from a random indie game like this one. I highly recommend this series', 'I like both Distraint games. More so the first one since the second is a bit too meta for my taste and some of the dialogues feel off. But holy shit, the ending, and I mean by that the final scene just before credits roll, it just sours *the whole experience* for me. Never before a game end scene made me feel that way and if those seconds were cut, I wouldn''t have to think twice about recommending Distraint 2. I truly hate that cliche in any story it appears in', 'Overwhelmingly Positive', 96.01, 7.92, 3.05);
INSERT INTO reviews VALUES (25441, 743450, 8791, 'accidentally got the ending where one of the love interests gets assassinated and everyone goes to her funeral in the credits\n\n\n10/10', 'This is unfortunately a miss for me.\n\nThe character design and the art are cute but it''s pretty much the only parts of the game I really enjoy. The writing is never cute or wholesome, it''s always going for jokes, in every single scene. Some of them land but it''s not a majority, it''s mostly random wacky stuff that''s almost always disconnected from the previous scenes. The boardgame type gameplay is a neat idea but beyond a list of stats, everything is hidden from you and just leaves you guessing ', 'Overwhelmingly Positive', 95.55, 18.40, 2.10);
INSERT INTO reviews VALUES (25448, 743640, 1369, 'Lots of achievements.', 'Achievement Clicker feels pointless, offering nothing but mindless clicking for fake achievements. It’s a hollow experience with no real gameplay.\n\nRating: ★☆☆☆☆ (1/5)', 'Very Positive', 81.59, 122.95, 1.67);
INSERT INTO reviews VALUES (25455, 743860, 138, 'Dispite what everyone else thinks, i believe this game has potential to become something great. While it is true that the gameplay in some areas is a bit rough... I believe it is or will be well worth it in the end.', '$30.00 for a Pay2Win Alpha game that is being advertised as a full release. This game should be free. Game launched 3 days ago and there are lvl 58 characters running around that will one shot you. Four different events that you can get gear from...you will have less than a 1% chance of getting the airdrop, or relic item, but will enjoy watching level 50s walk all over you and get it repeatidly. It is virtually impossible to progress around level 20, having no real way to obtain any items. This ', 'Mostly Negative', 31.88, 18.92, 16.55);
INSERT INTO reviews VALUES (25456, 743890, 1477, 'It''s a solid collection of great platformers, X1 to X3 are the SNES trilogy and are each bangers. \n\nI don''t love X4 (the PSX-era FMV cutscenes are painful with terrible voice acting and some of the levels are pretty basic) but it grew on me. Having to think of completely different strategies for playing X or Zero is pretty cool. \n\nThis is definitely the better half of the Mega Man X games, though.', 'Literally the worst possible way to play these games. How do you screw up the frame rates of a Super Nintendo game? Still not fixed 6 years later? Playing these games on the SNES mini is the way to do this. No gallery or achievements, but at least the friggin'' games work.', 'Mostly Positive', 76.37, 28.08, 6.47);
INSERT INTO reviews VALUES (25457, 743900, 622, 'recommended for those that truly hate playing video games for fun', 'While I''m happy to see the latter half of the Megaman X series preserved, I personally can''t recommend anyone actually play them. X5-X8 don''t quite hit the same as the X1-X4. X5 feels like watered down X4, X6 is watered down X5, and X7 is so watered down, it only barely has any remnant of what it originally was. X8 almost hits the mark, but it almost felt like too little too late.\r\nOnly buy this collection if you either;\r\nA: You want to be really thorough with going through the Megaman series (W', 'Mostly Positive', 73.47, 32.67, 43.05);
INSERT INTO reviews VALUES (25466, 744050, 133, 'This is not (quite) Space Invaders. It''s based on it, but there''s a lot going on, including power ups and the need to keep track of the colors and types of enemies. The soundtrack is a great 70s style one too. But be warned, there''s a ton of flashing during gameplay', 'It’s a real shame that such a great game requires to be online to play it. It looked like a perfect match for the Steam Deck but this nonsense requirement makes it a lot less compelling.', 'Very Positive', 87.22, 1.60, 0.13);
INSERT INTO reviews VALUES (25467, 744060, 557, 'I wish they''d port wai wai party over or update this. It''s like they don''t want our money. The Switch version is by far the better choice but this is a backup if you have no other options or care about achievements. Still a great game but a bit barebones compared the to switch version.', 'Game is nothing like wai wai party. zero vocaloid songs. feels unpolished and unfinished. just get wai wai party on switch or go to an arcade with custom servers\n\nEDIT: literally abandoned. get the switch version on sale or custom servers at an arcade (since arcade was also abandoned as well)', 'Mixed', 67.68, 7.65, 0.30);
INSERT INTO reviews VALUES (25470, 744190, 1064, 'Paradise would not exist without great sacrifice.', 'Rusty Lake PLEASE DO SOMETHING ABOUT YOUR GRAPHICS. They are so ugly and amateurish. That was fine when you were doing silly little flash games but not when you''re asking money for something that looks as horrid as this. I know that you''re most likely just a two person team but I also know you make FUCKTON of money from these games. Or at the very least enough for you to hire a proffesional artist that can draw better than this middle school level stuff. And don''t you dare try to say that "it''s ', 'Very Positive', 93.61, 4.02, 3.10);
INSERT INTO reviews VALUES (25474, 744270, 122, 'this game is a cool game its sad to see that this game has much more potential to be even better but i can see by how long its been stuck in early access that the developer has abandoned it which is sad these developers pay more attention to the dumb games that have millions of bugs instead of the cool games like this one', 'Much like Innuendobot 5000, I jumped the gun and bought this game because Josh on Let''s Game it Out made it look really fun. I wanted to have my own adventures like Johnny Hotbody. But now seeing that the game has indeed been abandoned, I prettymuch want a refund. I thought I was paying for a finished product. Not cool, Devs...', 'Mostly Negative', 36.07, 56.03, 5.28);
INSERT INTO reviews VALUES (25495, 744670, 120, '**NOTE - The Jan 2020 update destroyed this game and I will have to retract my review - the planes dont fly the same - and suffer from a terminal G force that cant be pulled out of, sadly the helicopter also suffers the same fate. This WAS a game I really enjoyed and championed, unique in VR, but since the update, its been basically unplayble. This game is absolutely what VR is made for. Jaw Dropping. You cannot get this experience anywhere else, and I''m shocked this game isnt more widely known ', 'It was okay but arcade experience at best, still buggy but playable. I''d wait', 'Mixed', 68.33, 11.77, 0.23);
INSERT INTO reviews VALUES (25510, 745000, 100, 'Played the free version on mobile for a while and even that was great to pass the time, but I''m so glad I bought the full version. It''s a super cheap and fun deck building game! I like that it was super easy to learn, no unnecessary additions or tutorials! Overall 10/10 recommended!', 'About 12 months ago the Daily challenge broke. You''d think a year would be enough time to fix a small but crucial bug, but since the developer can''t be bothered to do their job I can''t be bothered to leave a positive review.', 'Mostly Positive', 72.00, 4.60, 24.88);
INSERT INTO reviews VALUES (25511, 745010, 128, 'There''s a big worm', 'Goodbye John', 'Mixed', 49.22, 123.62, 24.12);
INSERT INTO reviews VALUES (25521, 745330, 117, 'This game is litteraly my childhood. I perfected it in 20h. This 20 hours were really fun, and I can say I enjoyed it. Apart from nostalgia this game is really good. Of course it isn''t perfect (You really need to have great reflexes to click one frame to jump), but I really think that if you have some free time or you have nostalgia to the series, i recomend to buy it.', 'some jumps just have to be pixel perfect', 'Very Positive', 82.05, 20.38, 12.68);
INSERT INTO reviews VALUES (25552, 745880, 992, 'Cant beat this shit on Normal', 'I''d rather have a red hot poker inserted into my urethra than play this game/\r\n-10/10', 'Overwhelmingly Positive', 98.59, 80.65, 48.10);
INSERT INTO reviews VALUES (25555, 745920, 17840, 'This game isn''t really that bad, but man is it like IMPOSSIBLE to buy clothes. Let me be a pretty princess, Jesus.', 'This game was fun before they introduced the battle pass. I recommended it better than Pokémon until they introduced the battle pass, which ruined the game for me.', 'Very Positive', 82.96, 74.92, 679.80);
INSERT INTO reviews VALUES (25559, 745960, 291, 'A Sky Full of Stars 仰望夜空的星辰\n\nHas a total of 8 trading cards.', 'It starts off very boring and does absolutely nothing to draw you into the story.', 'Very Positive', 94.85, 1.47, 0.52);
INSERT INTO reviews VALUES (25569, 746140, 152, 'You don''t need legs to be able to headshot zombies', 'A very boring game, gets boring within 10 minutes.', 'Mostly Positive', 77.63, 6.73, 0.20);
INSERT INTO reviews VALUES (25580, 746400, 418, 'i did not rob a bank and you cannot prove otherwise', 'A short game with characters that are interesting, both in terms of their design as well as personality (except for Drea, the androgynous tentacle-haired person, who is both an eyesore and not all that special) The rest of the cast however, were very likeable and had touching conclusions to their stories. A good mix of dark, cute, funny, and sad themes, and I''m glad that I experienced it. \n\nSadly, I''m going to have mark this game as ''not recommended'' simply due to the price. Having completed the', 'Overwhelmingly Positive', 97.61, 2.52, 1.23);
INSERT INTO reviews VALUES (25585, 746510, 648, 'its a fun and scary horror game and i would smash his mom', 'graphics not bad but can''t really do much stuff so it''s kinda boring tbh', 'Very Positive', 94.60, 15.53, 5.57);
INSERT INTO reviews VALUES (25591, 746580, 502, 'This game has great presentation and some really good mecha designs. I''ve never thought I''d have fun with SD mecha but this proved me wrong. The story isn''t anything new but it''s a fun-enough romp, and the levels are very well designed. The only thing that hampered the experience for me was the controls; using a gamepad is not a great experience because of how movement and aiming work. It''s not unplayable, just definitely a point of friction.\r\n\r\nAlso, I''d recommend against getting any of the DLC', 'Amazing game, cool enough story, gameplay is perfect at my opinion. Don''t buy.\nWhy? Because the Devs abandoned this game. While the Singleplayer is great, 10/10 even, the multiplayer services are dead.\nGuess what all the DLCs are for. You can''t even play against Bots, as that requires connection to their dead servers. It''s a shame.', 'Very Positive', 90.44, 16.82, 34.28);
INSERT INTO reviews VALUES (25597, 746710, 365, 'Crack open your notebook and enjoy thinking at a blank wall for a solid hour. Each cypher is worth sitting down to and the light history makes you feel like you are learning while screaming at your scream.', 'This game made me feel very dumb. Pretty sure I also had a stroke.', 'Very Positive', 89.32, 7.48, 1.02);
INSERT INTO reviews VALUES (25607, 746940, 138, 'Really great game, hilarious, its like mario kart but running', 'Nippon Marathon is a game like Takeshi’s Castle but on a weird sugar high, with characters so eccentric they make anime characters look restrained. I laughed – a lot – at the bizarre events, nonsensical obstacles, and characters that looked like they escaped from a B-movie.\n\nBut I also felt mildly nervous about this game. Why? Because it wasn’t made in Japan. And maybe this wouldn’t be a big deal, but for someone like me (hi, yes, I’m autistic) reading intent in parody can be a rollercoaster. Is', 'Very Positive', 94.20, 3.20, 1.00);
INSERT INTO reviews VALUES (25614, 747200, 1143, 'Pleasant little game, as another reviewer said its like Terraria with graphics that look a lot like Rimworld, much more Terraria-like gameplay though. Actually I suppose its got some SNES Legend of Zelda similarities in the gameplay too, in the way you fight and explore in a top-down view world.\n\nOverall, i''d say its worth a tenner or so... I played for 90hrs at time of this review, which is like £11.39 / 90hrs = roughly a cost of 12p of entertainment per hour. My sandwich yesterday cost £2 and ', 'My reviews are never seen. Just know that this game is negative from me and move along', 'Very Positive', 85.30, 90.20, 8.23);
INSERT INTO reviews VALUES (25624, 747340, 522, 'I came for folklore in a dark forest, and Unforgiving delivered.  Short but memorable.\n\nThe first and last parts are linear and underwhelming, but the middle is open-ended and captivating.', 'Pros:\n- Atmosphere\n- Music\n- Harp gameplay mechanic was unique\n- 2nd portion of the game in the caves was legit scary\n- Swedish voice acting seemed fine\n\nCons:\n- TOO F***ING DARK\n- You don''t get matches until much too far into the game. Turning up gamma only helps so much...\n- 1st portion of the game was a little too open and in combination with the darkness it led to much confusion even with the map given.\n- Some backtracking was frustrating because you''d have to walk quite a ways to go back an', 'Very Positive', 83.33, 3.35, 3.90);
INSERT INTO reviews VALUES (25625, 747350, 761, 'Playing in VR made me really FEEL like a schizophrenic celtic warrior.', 'This is unplayable for me with a Meta Quest 3S. Controllers don''t work. Have to use the keyboard, and the mouse doesn''t work to look around.', 'Very Positive', 84.76, 9.40, 0.52);
INSERT INTO reviews VALUES (25634, 747660, 35350, 'My name is Edwin, I made the Mimic\nIt was difficult to put the pieces together\nBut unfortunatеly, something went so wrong\nAnd now I can''t do anything but sing this stupid song\nMy name is Edwin', 'Imagine if someone gave you one billion bucks to build a space rocket but you are not an engineer, how would the result look like?\nI thought about this question a lot while playing this game. It was such a bad decision to give this big IP to a studio that has a weak knowledge about 3D games.\nAlthough Security Breach has very good level designs, themes etc. , the gameplay itself is extremely rough:\nThe hide and seek mechanic from the animatronics has no depth during the open areas, the flashlight', 'Very Positive', 85.48, 12.77, 10.98);
INSERT INTO reviews VALUES (25644, 747910, 235, 'Disesemble my balls', 'Not worth 40 dollars, maybe worth 22 for everything but idk', 'Very Positive', 84.26, 15.32, 23.28);
INSERT INTO reviews VALUES (25652, 748040, 134, 'this was my favorite game as a kid', 'only State of War is working the other game state of war warmonger do not work very annoying', 'Very Positive', 91.79, 183.73, 33.75);
INSERT INTO reviews VALUES (25660, 748300, 393, 'It was relaxing to go around and dig up items that could be expensive artifacts, but I wish my computer didn''t start roaring as soon as the game opened, it''s good other than optimisation perhaps', 'keeps crashing every minute. No matter if im in game or menu. Rtx 3070 and intel i9', 'Mixed', 62.60, 6.95, 0.75);
INSERT INTO reviews VALUES (25664, 748360, 788, 'I see Todoroki and I feel visceral hatred. Not because I hate him, but because he''s gay. 10/10', 'i bought it for 3 bucks and i still feel like i got robbed. this is horrible.', 'Mostly Positive', 79.06, 4.02, 0.13);
INSERT INTO reviews VALUES (25665, 748370, 807, 'They did finally update and fix everything i know of a bit ago. Holes in the ground, glitches in the castle, etc. There are real players. \n\nA good time to find more real players is around 5 to 8pm eastern usa time. \n\nI enjoy this game a lot. Everything works well. Its a simple shooter, slow hunt that is forced to be fast. With wonderful game mechanics to push battle with the shrinking damage barrier. It doesnt try to be too much. \n\nThough, i wish they would make the helicopter always spawn in th', 'seems they just half build games chuck them out for sale pretending they have future updates but 4 years has passed iv lost trust in the company this game and gang v is still half built but abandond', 'Mostly Positive', 71.75, 260.25, 0.77);
INSERT INTO reviews VALUES (25670, 748490, 1712, 'This video game was an impressive journey of emotions, I can say that it is the first video game that has made me cry for the death of a character, the plot twists and surprises have made it one of the best Trials so far, definitely this saga has become the best and my favorite so far. <3', 'has rean schwarzer', 'Very Positive', 94.45, 73.55, 29.40);
INSERT INTO reviews VALUES (25675, 748610, 123, 'Honestly despite it being a bit expensive for a game like this, I''d say it''s worth it. Anyone who loves aviation should get this. I can play for a few hours and not get bored despite it being repetitive. Wish it had some more features though and was higher quality but it''s still amazing.', 'I''ve been a long time supporter of this developer and this is his first release I''m rather upset with.  Like all his previous releases, he promised new airports released as part of the purchase which has traditionally been about one a month.  Instead of getting free new airports as advertised, he goes straight into Version 2, the quest for more money!\n\nOkay, I have enjoyed his releases so I went ahead an purchased this release.  It''s not a stand alone, it doesn''t introduce anything new that AM3D', 'Very Positive', 88.62, 17.85, 76.35);
INSERT INTO reviews VALUES (25687, 748890, 123, 'Initially, it was pretty overwhelming not gonna lie, tons of names and unique stuff about the game world adjectives and status + the big hard winter chapter.. but then after some fails i managed to get the hang of it and it was actually pretty fun! And wow the world building is something amazing, very detailed and you also have an usefull codex that you can read at any time with a detailed description of each name meaning and things, it''s a pretty unique experience compared to other games from C', 'Give sequel.', 'Very Positive', 91.06, 15.75, 10.88);
INSERT INTO reviews VALUES (25691, 748970, 200, 'Great game if you drunk.', 'You know how i know you know i suck at chess?\r\n\r\nSo if i, a complete noob, can see multiple solutions on several levels and the game doesn''t accept any of the solutions except a single one, you know this game was poorly tested and not double checked.', 'Very Positive', 87.00, 6613.18, 1.47);
INSERT INTO reviews VALUES (25706, 749250, 171, 'My wife said if this review gets 50 likes and 5 awards, she will buy a case of beer, guys help me out.', 'The puzzles are ridiculously punishing, for some the only way to get through them is by repeatedly dying to learn their sequence', 'Mixed', 67.25, 4.62, 2.03);
INSERT INTO reviews VALUES (25727, 749800, 187, 'Not as good as the first one, but the first one was a tall order to beat anyway.', 'Doesn''t hold a candle to the original. I wish they hadn''t, y''know, completely changed the style of the game. I completed the first PixelJunk Monsters game in co-op with 4 different people, that''s how good it was. Didn''t make it anywhere with this.', 'Mixed', 62.03, 55.85, 1.88);
INSERT INTO reviews VALUES (25730, 749840, 137, 'Finally revisited this series after 3 years, and this was the strongest entry so far.\r\n\r\nAn awesome setting and great puzzles and scares. Made me genuinely care about the characters and their fates. It was great to see familiar faces and the world of the strange men anthology continue.\r\n\r\nEnding made me ugly cry. 10/10, can''t wait to play the final entry.', 'It''s not a bad game, more like a "meh" game, but the reason why I''m giving it a negative review is that you NEED a guide to get the good ending. You can''t logically make out the choices you need to make to get the good ending. Heck, just playing the game normally, I felt like I needed a guide. After The Cooked Man and The Sandman, this is definitely the weakest so far. Also, the main protagonist isn''t likeable whatsoever. I get that''s the point, and he does make up for it in the end, but I was r', 'Very Positive', 81.02, 6.50, 5.95);
INSERT INTO reviews VALUES (25735, 749890, 106, 'I played the entirety of Uri''s "Strange Man" series but will only post a review here as all criticism and comments can be applied to all games in this series.\r\n\r\nUri''s biggest strength is writing a good and touching story, with the best stories being in "The Crooked Man" and in "The Sandman". I always like Uri''s characters and their design and I find their games to be very atmospheric. The Hanged Man in particular was very atmospheric with it''s setting and it being set in the season winter. The ', 'The Strange Man series was super fun, especially Crooked Man and the Sandman. However, it started to go downhill with the Boogie Man, and completely flatlined in this game. The voice acting wasn''t good (I had to mute the game in order to progress, because of how much I disliked it), the game felt super uninspired (so many rooms were exactly the same, and it seemed like it was just to fill space), and the plotline is...kinda lame. The Boogie Man, Crooked Man and the Sandman all had important role', 'Very Positive', 89.62, 8.80, 8.22);
INSERT INTO reviews VALUES (25738, 749960, 240, 'One of the games that you are afraid that you will have completed it soon. I really wish there were more strategy / resource management games in VR. I would buy a Townsmen VR 2 immediately.\nIt''s extremely relaxing to just watch your people being busy and carrying around resources.\nI can really recommend this game to everyone who owns a VR headset. It''s not as complicated as many other strategy games, everything is explained very well.', 'no oculus sdk despite meta store rift version.....', 'Very Positive', 81.67, 18.10, 6.87);
INSERT INTO reviews VALUES (25746, 750130, 1694, 'I don''t care what people say about the mechanics. Yeah, it''s annoying sometimes, but it''s actually a really good game worth checking out if you like Lovecraftian horror.', 'The game had good atmosphere and a good premise, but was bogged down by serious bloat. The game could have been much more satisfying if it was significantly shorter, with less running around doing fetch-quests in the same 4 houses. The city should also have been much smaller, as its size made it more apparent that it was made by a small team. The city is full of repeating set-pieces, signs, house interiors and exteriors. All-in-all, the developer tried to make the game way bigger than it needed ', 'Mostly Positive', 73.26, 22.62, 23.77);
INSERT INTO reviews VALUES (25747, 750170, 212, 'That''s how you make a game. The core first, then improve visuals. Features lots of stuff DTG are failing to deliver. And thankfully it''s not UnrealEngine :)', 'All trains have the same instruments in the interior, just positioned differently. This means that trains with no gears do have a gear selector which breaks immersion. Overall, this is a very unpolished game.', 'Very Positive', 94.81, 12.63, 0.20);
INSERT INTO reviews VALUES (25748, 750200, 185, 'Completed the game in 3 hours. It was fun! but not much left to do after that. The game is really fun imho.', 'The game is incredibly buggy and seems to be poorly optimized. With a 13700k and 4080 I had to play on medium at 5120x1440p or the game would literally stutter to 2 frame a second. I had multiple fight instances where I died just because I would click something like dodge and it wouldn''t dodge, but then when I would respawn the character would dodge randomly. or I''d try to dodge and it wouldn''t and I''d get attacked, but when I would jump it would dodge as soon as it hit the ground. I was hopeful', 'Mixed', 57.84, 5.73, 1.43);
INSERT INTO reviews VALUES (25752, 750290, 242, 'I recommend this game even though it has one of my most loathed P&C mechanics.  The good:  great art work, atmosphere, and music.  The world is immersive and enjoyable.  The inventory is quick to use and travel between scenes isn''t tedious.  For all these reasons, I really enjoyed this game...most of the time.  What I really disliked was that sometimes you get stuck because a travel direction is obscured - a door isn''t obviously a door, a travel direction doesn''t look like it is feasible, a scal', 'Extremely mid.\n\nThe gameplay is clearly aping Amanita Designs (Samorost & Machinarium). Start with their games first, and if you''re still looking for more puzzle games, come back to this. There is nothing really awful about this, but it just wanes in comparison to other titles in this space.\n\nI do like the art style in general. Some characters and scenes reminded me of Mercer Mayer books. I just wish there was more going on than looking nice.', 'Very Positive', 93.39, 13.02, 5.53);
INSERT INTO reviews VALUES (25760, 750470, 317, 'very fun has started to die of, rip war brokers thanks for all the great years', 'This game keeps banning me and not letting me play because someone complains about my gamer name. And it also bans me for no reason I have been told. My gamer names are never vulgar or rude in any way. Just because someone finds my gamer name offensive for some reason should not allow a person who complains to get me kicked off the game. This is the 3rd time for me. People on this game platform are too sensitive in my opinion. Just play the game and quit complaining about stupid things that don''', 'Very Positive', 93.69, 176.83, 972.33);
INSERT INTO reviews VALUES (25763, 750520, 293, 'the game is pretty fun its worth buying and playing', 'I bought this game quite a while ago and somehow managed to play it for 18.4 hrs. It''s a grind but wasn''t unpleasant. I got bored today and decided to give it a replay. Wtf. This used to be an entirely point-and-click game, like most Tycoon games. Optional hot keys are fine, but you''re forcing me to use both hot keys and the mouse, switching back and forth to get through the menus? \n\nI''m sorry, but this is the most annoying interface redesign I''ve ever seen. It went from being a game that I migh', 'Mostly Positive', 79.18, 3.38, 18.78);
INSERT INTO reviews VALUES (25778, 750920, 21192, '9/10.\n\nIt''s a fun game, the exploration and combat mechanics are the best from the 3. The levels are pretty cool and the puzzles and tombs are very well done.\n\nLara is an awful protagonist, though. She is selfish, whiny and obtuse and she has actually regressed from the previous games. She has no relevant character arc and her making knee-jerk decisions is the cuase of like 90% of the problems she has to solve. Even Jonah lost his cool with her on this one.\n\nThe internal logic of the game is als', 'What was once a fresh formula with the first two games now feels a bit dated. The platforming is boring, the story is quite dull, and the locations are few and uninteresting.', 'Very Positive', 84.98, 50.27, 15.77);
INSERT INTO reviews VALUES (25798, 751440, 741, 'Where is the sex or am I missing something', 'Played in the family living room during thanksgiving, just to feel alive.', 'Mostly Positive', 72.20, 0.50, 1.22);
INSERT INTO reviews VALUES (25799, 751450, 116, 'Pretty cool game from the creator of 9-nine- and Liminal Border. It might appear light-hearted at first glance, but it actually has pretty much everything possible, because Kazuki Fumi writes thrilling mystery, funny comedy, and touching drama. It''s not perfect, and I''d wish for better side routes (go straight for Kotori during your first playthrough and think about the rest later) and better foreshadowing for the culprit, but overall it''s still a strong emotional story', 'Don''t give the player the illusion of ''choice'' or ''multiple routes'', when there''s really only one route, with some minor variations. Don''t make the central heroine the most irritating character in the game either. I''d like real routes focused around the other characters, but the creators of this game decided to prioritize their garbage waifu over everybody else instead.', 'Very Positive', 94.83, 14.32, 3.13);
INSERT INTO reviews VALUES (25803, 751500, 145, 'I’m really enjoying this game on my Steam Deck, but level 14 keeps crashing and won’t run. I only get the wheel turning in the lower right corner and then everything freezes up. Tried uninstalling and then reinstalling it and playing through it all over again. Would like some help if it’s possible.', 'Fun game if you played Advance Wars as a kid, but M09 won''t unlock for me even though I''ve beaten M08 and MX03. Since I can only play 11 of 50 story missions and can''t progress I''m not happy.', 'Mixed', 66.21, 49.52, 7.57);
INSERT INTO reviews VALUES (25809, 751630, 1447, 'Amazing game! The gameplay is very satisfying and the guns feel good.\r\n\r\nMy only complaint is that there''s not many players at the time of writing this.\r\nIf you want to play this game at night, you might not even find anyone to play with.\r\n\r\nExpect to play singleplayer if you buy this, Unless you have friends, but what kind of nerd has friends in 2024?', 'The game is fun, however there is a game breaking bug that has been an issue for over 2 years and the Devs still haven''t fixed it. \nEvery time there is a gunner that spawns any time during gameplay, the players guns stop working after the gunner is dead. This means you can''t proceed and have to lose any in game bonuses. Considering the Gunner spawns more than half the time now, even in the first mission it makes the game UNPLAYABLE! But Devs have not acknowledged or fixed in years!!!!', 'Mostly Positive', 76.92, 21.78, 0.85);
INSERT INTO reviews VALUES (25816, 751780, 12825, 'Buy at a discount but not at full price kind of game. It''s a lot (like, a LOT) of fun and kept me well entertained for a solid 50 hours, but considering how the game was dropped by the dev a while ago now with missing, promised features, (such as multiplayer) it''s hard to recommend at its full price. Certain qol settings or functions are hidden either in the secret settings for the game or need to be added through mods, which is a bit questionable. Still heavily recommend to give it a shot if it', 'Cool game, too bad it''s not finished.\n\n4years with no updates and the end game is non-existant.\n\nYou can get about 20hours out of the game, but it then hits a brick wall of disappointment.', 'Very Positive', 88.49, 52.92, 20.07);
INSERT INTO reviews VALUES (25818, 751820, 204, 'Game looks good, music is awesome. \n\nLevel design wise is a bit confusing and the mechanics are a tad weird sometimes, but fun nonetheless.', 'I wanted to like this game. I really did.\nBut when the first two games I play ended with my character falling through the floor just seconds after defeating a boss, forcing me to restart the run, I felt cheated. And then I looked through the discussion and it hit me with the truth: this game''s worst bugs, the ones that unfairly glitch a run through no fault of your own, have not been patched. For years.', 'Mostly Positive', 71.08, 3.83, 0.23);
INSERT INTO reviews VALUES (25841, 752470, 203, 'CINERIS SOMNIA is a gorgeous exploration game with elements of horror and mystery. I absolutely loved every minute of playing this, and am so happy I discovered it! It places you in lonely, desolate settings with surreal undertones as you guide each character through discovery and acceptance. I really like that the character you play as is not necessarily the *main* character, but merely a tool used to tell each girls'' story as you progress. Each chapter has a moving story that gradually expands', '50% walking 40% getting lost and only 10% admiring the beauty and storyline. Best way to approach this game: go on YouTube and watch walkthrough videos with 2x speed-_-b', 'Very Positive', 84.24, 9.27, 6.27);
INSERT INTO reviews VALUES (25842, 752480, 409, 'I can see why people don''t like the game, but I''d say it''s great if you want a fun sniping vr game.', 'While game can be fun aiming, shooting, reloading basically all essential actions are clunky AF. You also move extremely slowly. IRL you use rifle stock against your shoulder to stabilize the gun, VR games compensate shaking of your hands since you are not holding anything and your hands wobble quite a bit. Not this game. Also not being able to adjust where you want to grip the gun is annoying and you will find yourself fighting your scope more than enemies.\r\n\r\nAlso to unlock levels you have to ', 'Mixed', 54.03, 7.35, 10.62);
INSERT INTO reviews VALUES (25850, 752590, 19764, 'An interesting game with a fascinating story. But there are downsides - these are blind NPCs who don''t care what''s going on around them, you can at least dance in front of them and then just as easily hide under the bushes (like yo buddy, you can go through, I didn''t see anything lol). The game is quite boring and monotonous in places, I literally played for 30 minutes a day, for me this is an alarming sign. The rats in this game are quite stupid, not aggressive, they mainly serve as an obstacle', 'I actually liked this game a lot and for a long time thought I would rate it 10/10. Until I reached the last four or so hours of the game. Now it''s perhaps a 5/10 for me, only propped up by the earlier good parts.\n\nWithout going into spoilers: Towards the end the game suddenly completely changes its mechanics. It turns into some kind of  dexterity soulslike. Until then it was a suspensful and story-heavy but mechanically rather relaxed horror stealth game. Then it morphs into a skill-based actio', 'Very Positive', 93.02, 9.95, 13.00);
INSERT INTO reviews VALUES (25863, 752900, 318, 'Yes it has a lot of work yet to be done but honestly its the best dino hunting game on the market outside of carnivores 2. The devs actually listen to their players and updates appear to be frequent and substantial. Keep up the good work guys!', 'Wish there was a yes and no option I honestly love this game lots of love and passion went into it I can tell. However after 7 hours all I have unlocked is the "hunting rifle" and the "revolver" I get it its supposed to be a grind but when animals take 5 shots with a hunting rifle in the lung and still refuse to go down that is where I have an issue. Lets start with 1 \nupon death you lose a certain amount of ammo and have to reclaim those items for herbivores its kinda easy if its a carnivore mi', 'Very Positive', 85.22, 97.18, 9.87);
INSERT INTO reviews VALUES (25864, 752910, 186, 'BETS GAME', 'No one has played this since 2017 so dont expect to play public servers, good concept though', 'Very Positive', 81.18, 5.30, 6.47);
INSERT INTO reviews VALUES (25872, 753220, 150, 'Mhakna Gramura is a very unique VN. None of what it presents is usually typical of VNs with its art style giving off a water color painting impression providing a very unique feeling similar to what you mind find in a fairy tale book. To add on to this fairytale motif, the story presents itself similar to what you would find in a fairytale like Peter Pan or Alice in wonderland as well with a mysterious and magical land filled with a lot of nonsensical things occurring. In the case of this partic', 'So pretty.. too bad it is barely memorable. Also more scary than I would have hoped for.', 'Overwhelmingly Positive', 98.67, 1.15, 3.93);
INSERT INTO reviews VALUES (25881, 753420, 2398, 'honetsly kinda mid dident play that much but enjoyed it', 'The concept of the game is good, but i just cant stand the lack of information. I rly don''t get it. Like, items with info "but deals less damage".  why? why just not let people know how much less damage? \n\nBunch of items have this kind of mysterious description, and i just cant get why devs do stuff like this.\n\nUPDATE: After playing more, which was kind of a drag, i noticed i keep getting the same item drops over and over. I unlocked 95% percent of the game, but  the item pool is just mega stupi', 'Very Positive', 93.20, 507.77, 187.23);
INSERT INTO reviews VALUES (25887, 753590, 516, 'Totally 90s FPS, I love it. You don''t have to revisit areas (with respawned enemies, yuck) like in today''s games, and you don''t have to look at your inventory in every 5 minutes like in modern games because there is no inventory at all. Also, there are no tremendous action keys you need to remap at first start, because there are no tremendous action keys in this game. And finally, you don''t have to worry about your weapons being low level, because there is no character and weapon leveling in thi', 'the game is good but it''s too short way too short for the price 7 levels and 1 boss fight?? \nneeds to be way cheaper for the lack of content which is waste because the gameplay is good.', 'Mixed', 68.80, 2.92, 2.68);
INSERT INTO reviews VALUES (25890, 753640, 43330, 'The best game I''ve ever played. \nDon''t spoil yourself. No matter what.\nStop reading reviews and play the game.\n\nVenture forward into the cosmic unknown.', 'Like me, you probably fell for the "Go in blind, it''s SUCH a good game" propaganda. While the game engine is well-made, the gameplay loop consists of: 1) Go to planet. 2) Read lore. 3) Run out of time and restart. That''s basically it; the entire game is just based on reading hours and hours of lore with very little payoff. Some people might find that fun, but personally, I just couldn''t find a reason to keep playing.', 'Overwhelmingly Positive', 95.15, 15.37, 9.12);
INSERT INTO reviews VALUES (25891, 753650, 5305, 'Please just make it free. Like no one is playing your game anyway. You already have cosmetics in the game just use that as profit or something bro idk figure it out please this game needs players again. Such massive potential if it goes free just pull the trigger. Idk if you devs have ur hands tied or something but someones window needs a visit from the brick. This game is genuinely so good, like hands down the best 5v5 fps ive ever played. A truly ENDLESS gameplay loop. VIVA LA DUE PROCESS', 'This game is really awesome, but this review is done out of moral standing:\r\n\r\nThe current developers for this title are not being paid, they are working on a volunteer basis. Normally, I''d be okay with this, but it strikes me as predatory for this reason:\r\n\r\nGiant Enemy Crab (The studio releasing this title) is currently hiring software developers at a senior level. These people ARE being paid, but the devs responsible for this game are not.\r\n\r\nDevelopers deserve a wage if they''re working on a ', 'Very Positive', 84.45, 127.22, 53.37);
INSERT INTO reviews VALUES (25895, 753930, 520, 'This indie horror game is a standout, offering a refreshingly experimental approach. It seamlessly blends a compelling narrative with a haunting atmosphere, making it feel almost like a thoughtful walking simulator. I appreciate how it stands out from the typical low-budget horror games that often rely heavily on monster chases and excessive jump scares. I''m eagerly anticipating the next installment.', 'I agree with the other reviewer who said it''s not so much walking simulator as it is a  waiting  simulator. So much time wasted looking around cluelessly, waiting for doors to unlock. If the devs were trying to create a virtual purgatory, I''d say they succeeded. If they wanted to stretch a minimal amount of gameplay over several hours by forcing players to click around and stare at various objects for ages, they might have succeeded, though I''m not sure how many gamers have the patience to not r', 'Mixed', 67.88, 2.03, 3.30);
INSERT INTO reviews VALUES (25904, 754040, 239, 'Quite possibly the best single player experience I''ve ever had. The highs of this game are immaculate and the lows are rare if never to be found. The platforming is second to none, other platformers such as jump knight wishes it could have such unique and fluid movement. The art-style and sprites are truly flawless designs that accompany the elegant game-play. The final level of this game had me on the edge of tears, the true beauty of the story was moving and the difficulty proved a challenge a', 'piggy poggy poo', 'Very Positive', 86.19, 0.20, 0.70);
INSERT INTO reviews VALUES (25907, 754120, 142, 'ACHIEVEMENTS', 'Achievement Spam.', 'Mostly Positive', 78.87, 0.23, 5.27);
INSERT INTO reviews VALUES (25908, 754150, 1831, 'Rolling Line isn''t just a train simulator or a game. It''s a sandbox engine that literally lets you make anything you want. Thanks to its building system, the level of creative freedom here is only rivaled by titans of gaming like Minecraft. You will never run out of things to do in this game, because it allows players to make their own content as they wish. I''ve spent hundreds of hours recreating real life train stations, for example. A thriving modding community and regular updates will probabl', 'pc controls are fucked, snapping is terrible, you need to walk at a snails pace to and from the drawers, whole point of the game is to build but it is so annoying to do anything', 'Overwhelmingly Positive', 96.34, 476.83, 0.47);
INSERT INTO reviews VALUES (25925, 754530, 688, 'An absolutely fantastic WW1/WW2 flight sim!\n\nLooks great, plays great and the sounds are superb.  And all for under £10!\n\nIf VR arrives it will be complete!', 'Bought this because I read a dev post from mid 2022 that they were introducing VR in an upcoming patch.  Unfortunately as of September 2024 there is still no VR compatibility, although they do say they plan on introducing it but the last communication was 6 months ago.', 'Mixed', 66.72, 4.90, 0.33);
INSERT INTO reviews VALUES (25936, 754890, 640, 'What a game! What. A. Game.\r\nBeen a fan of Cyan games for many, many years since playing Myst way back in the early 90''s. They have always produced beautiful, story-rich games, and this is no exception, this game is absolutely stunning!\r\nThe visuals are absolutely astounding, as one would expect from any Cyan game. Beautifully rendered into a fully realised world that feels real and believable along with a deep and intriguing story with one heck of a twist right at the end... and talking about t', 'Visually quite stunning in parts, but I found it a bit tedious to play. The puzzles weren''t very challenging, and it got quite repetitious - there was a lot of running back and forth between places with nothing to do except watch the same views over and over again. I also found the control interface (the so-called Adjunct) irritating and the key mappings (which you can''t change) uncomfortable to use. It spoiled the game play.\r\nThe biggest problems for me, however, were the bugs - the game contin', 'Mixed', 69.38, 10.07, 17.68);
INSERT INTO reviews VALUES (25951, 755410, 223, 'Other than an over zealous riddle and so annoying "wait around till the boss does a thing otherwise they''re invincible" (which is a bit awkward when you and a big boss just sit there staring at each other) this is a pretty fun little indie adventure. The graphics and story are as simple as it gets, but the gameplay mechanics and over all game design are really good having been made by a pair of brothers on one of their first games. There''s only a handful of enemy types (and their variants) and o', 'The game is fun. Don''t get me wrong.\nBut its been out almost 6 months at the time of this review and still only the first chapter is available. How many years until the game is actually finished? That''s anyones guess. My guess is never. Small early access titles like this have a habit of turning into abandonware when the dev realizes that making more content doesn''t bring in more customers, because everyone who was interested already purchased the game.\nSo if you want a quirky fun little title t', 'Very Positive', 93.72, 12.38, 3.75);
INSERT INTO reviews VALUES (25954, 755470, 171, 'It was amazing. Unique combat system that I didn''t see in similar games which revolves around match 3 altougth I expected there will be more types of attacks than just black hole, fire ball or slash. It has pretty challenging enemies that each of them needs different approach. There are very adorable and cool characters with nice designs which implement unusual set of colors and the story and the lore is very good and I wish there was like continuation except from the end credits. \n\nReally enjoy', 'this game need a save file, i dont wanna spend more 5 hours to get full achievement bruhh', 'Very Positive', 80.12, 2.92, 7.37);
INSERT INTO reviews VALUES (25956, 755500, 1999, 'combat is ass, story is slow, missions are EVERYWHERE but namis honkers are big', 'havent played the game because i refused the agreement at the start where it says I dont actually own the game after PURCHASING THE GAME.\n\ndoesnt let you proceed if you dont agree that the game is in fact purchased and not leased like a 1 bedroom flat or an escort like the bandai excs indulge in because who would even look at a tub of congealed lard and say mmm, yes please\n\nsuck it bandai namco, another type of garbage that even my trash bin wont accept because even it has standards', 'Mostly Positive', 79.74, 6.57, 1.12);
INSERT INTO reviews VALUES (25977, 755980, 205, 'It''s a pretty good game, but sometimes it gets boring, which makes you want to get through and out faster.', '\nYour unusual MOBA game. Gameplay is not bad however there''s no people playing it now so you''re left playing with your friends or just pass on this one.\n', 'Very Positive', 82.93, 2.33, 0.20);
INSERT INTO reviews VALUES (26002, 756530, 473, 'bad', 'Whether you love anime games or are just a fan of Tokyo Ghoul, you''ll probably be disappointed with this game. It''s reminiscent of a PS2-era game when it comes to the gameplay mechanics and animations, but actually much worse.\n\nConsider the price tag: $59.99. For that price, you don''t even get full voice acting! The characters in 95% of the game just mumble a few Japanese words, which is ridiculous. The campaign lasts at most 2 hours. Despite the huge amount of content that could have been inclu', 'Mixed', 60.89, 0.13, 3.17);
INSERT INTO reviews VALUES (26013, 756800, 8784, 'I had a guy arrive at the border in a van saying that he was carrying medicine to cure children with stage 4 cancer. Unfortunately, his passport was expired by 1 day so i slashed all of his tires, sent him to the labour camp for the rest of his life and blew up the remaining contents of the van with a grenade.\n\n10/10 game would recommend.', 'Very quickly repeating and tedious, clunky, gameplay wise not interesting, massive overhyped for some weird reason(streamer crap I guess)', 'Overwhelmingly Positive', 95.70, 1193.88, 1.52);
INSERT INTO reviews VALUES (26017, 756880, 105, 'amazing spectacle for all special dwellers of steam!', 'Pretty Much Copy and Paste\n\nNVL pretty much feels exactly like another game I played recently, Azura featuring the same room full of chests to grant you 1000s of achievements when opened. I may as well copy and paste my review from that game with how similar it feels. I didn''t even bother doing anything else because, like with the aforementioned Azura, having a room that just gives you all the achievements sucks all the fun out of playing.', 'Mixed', 60.95, 7.95, 0.13);
INSERT INTO reviews VALUES (26030, 757210, 574, 'To my knowledge this was my first PC game. I had the CD version. Later bought the Steam version. Great game and even better it allows modifications that elevate the base game. This has always been enjoyable and easy to jump into. No complaints and it still runs smooth.', 'I don''t think they cared when making this expansion.', 'Very Positive', 93.73, 3.62, 49.32);
INSERT INTO reviews VALUES (26034, 757300, 473, 'Nice relaxed charming humorous point and click adventure with good story, items to look for and put in the right place (press the spacebar to show interactable items/spots marked with a red x). The animations are funny and are a piece Art. The surroundings (chambers, environmemt) are a piece of Art as well! Sometimes, you have to trade items with a non-player-character. Have fun!', 'The game is beautiful however it is really slow (slow dialogue, almost impossible to skip things, puzzles take forever) and with a dry storyline and delivery (the voice acting was sometimes quite painful to listen to). I completed it but it wasn''t really worth it in the end. I feel like the development team were more focused on their vision and making sure that the player notices all the hard work that went into it, rather than considering what would make this fun for the player.', 'Mostly Positive', 73.78, 113.00, 6.90);
INSERT INTO reviews VALUES (26035, 757310, 3519, '\nWonderful game with an enchanting atmosphere. It captures that childhood sense of exploration perfectly -- with flying, mysterious masks and endless curiosity. I rarely say this, but I wish I could play it again for the 1st time to experience that pure joy and awe. 100 chum eggs out of 100.', 'It’s devastating for me to leave a negative review here. But I can’t help myself after the experience this game offers.\n\nThe pros are definitely here. With a beautiful and unique art style leading the list off. Additionally, the music and atmosphere is beyond relaxing. Lastly, some of the art direction with characters and buildings were enjoyable to be around.\n\nBut the game is just nonstop fetch quests. The lore didn’t keep my interest enough to continue on. After the initial exploration and art', 'Very Positive', 86.62, 27.92, 7.50);
INSERT INTO reviews VALUES (26036, 757320, 2340, 'I really love this game. Scratches several itches. Still feel like I have lots to do too. I only play on Deck. Just a few stutters.', 'This game lies in the 9th circle of Bullet HELL where access to meta-progression is gated behind random encounters and measured in .001 increments.', 'Very Positive', 93.42, 85.33, 11.50);
INSERT INTO reviews VALUES (26037, 757330, 163, 'qop2 is a logical puzzle game that uses the keyboard arrow keys to move a cube to the final destination point. Its cheap and I highly recommend it. It could be challenging but its easy to achieve all achievements for it as well using a guide you can find in the guides section.', 'Not Recommended', 'Very Positive', 90.80, 2.15, 0.95);
INSERT INTO reviews VALUES (26045, 757480, 1486, 'It''s a real shame this game didn''t get more traction, because I find that it''s a very unique experience and one worth having. Beneath its admittedly enticing vaporwave visage lies a creature with curious puzzles, playful characters, goofy writing, and a full, fleshed out story. It is an experience that, from beginning to end, is thoroughly enjoyable. There''s not much else to say on it.', 'Just add a mouse sensitivity slider into the game.', 'Very Positive', 92.19, 27.33, 0.10);
INSERT INTO reviews VALUES (26080, 758190, 1037, 'Bought the game just to let everyone know its free on Mobil if you wanna try it out.', 'It''s not bad, but it commits a cardinal sin: It''s a singleplayer game that has cheat engine (and most importantly speedhack) detection. It cannot be disabled. I''m going to say it plain: You don''t get to decide what I do or do not do on my own machine. Sadly, I cannot refund it anymore as I left the game running while I left - but I cannot recommend anyone else buys it.', 'Very Positive', 85.63, 0.13, 7.78);
INSERT INTO reviews VALUES (26086, 758320, 102, 'I''m a simple person, I see a romanceable naga, I buy it.', 'I can''t say I hate this game. In fact, I even like some of the parts. Like Enok, Sylrissa or Vaeril (just for looks). But that''s it. Plot is painfully generic, dialogue is boring, choices are unimportant, characters are flat, combat system feels like an afterthought, music is offensively mediocre and the price is RIDICULOUS. \r\nSo, no I can''t say I hate this game - because it fails to evoke any strong emotion at all. It is just so aggressively mid.', 'Mostly Positive', 70.59, 1.27, 29.85);
INSERT INTO reviews VALUES (26087, 758330, 1173, 'For the best experience, make sure you''ve never played anything more advanced than this and then have children and lose your hair before playing the third one.\r\n\r\nIt''s clunky, but it''s still the best kung fu movie I''ve ever played.', 'Have wanted to try this for years. Got it on sale, figured it was worth a shot.\n\nAaaaaannnnddd... nope, it wasn''t. This is a "you had to be there" game.', 'Very Positive', 89.60, 36.65, 5.13);
INSERT INTO reviews VALUES (26089, 758410, 130, 'Yes, I would like to recommend AO International Tennis for everyone.', 'Just expected more from a Tennis game', 'Mostly Positive', 76.92, 0.55, 3.17);
INSERT INTO reviews VALUES (26091, 758480, 495, 'This game has forever changed my view on not only Ukraine, but galaxy gas. When I was 5 years old ago, I had a dream about this exact game, and seeing it being in fruition and real, and these incredible graphics and story of this ball just wanting gas, is the true movement we need. Made me realize how important life is, especially grass, and that castle I found along the way. I don''t think I''m gonna ever be the same without this and gas.', 'would be a good purchase but steam wont stop reccomending me porn games no matter what i do', 'Very Positive', 94.75, 0.35, 0.37);
INSERT INTO reviews VALUES (26092, 758500, 380, 'Making the entire industry collapse for a MacGuffin(literally) sounds right for a game named "loot box quest".\n\nUpgrading highly unethical business practices and literal crimes against humanity makes you laugh first, then cry because some of it actually happen in real life, then ponder about what you can do and what you should do.\n\nAnyway, 7/10 game.', '', 'Very Positive', 93.95, 3.40, 5.33);
INSERT INTO reviews VALUES (26095, 758570, 101, 'This game is masterpiece. it shows very well how depression works and this is just incredable. i never seen a better psychological and philosophical game before. i think its actually the best game that represent depression and i played games with these themes a lot. the message it carries makes me love it even more. please play this game if u or your loved ones suffer from depression, then you will more understanding. this game fits perectly for words "art is meant to comfort the disturbed and d', 'Too clunky to serve as a game, too shallow to serve as a serious message.', 'Very Positive', 81.19, 3.78, 0.50);
INSERT INTO reviews VALUES (26106, 758690, 1026, 'This game is a really fun game. Its not a easy game to at all but i don''t thing its overly hard. you just need to learn a lot from your mistakes and such. Though its really rewarding when you learn how to do things and start to understand everything and how it works. Exploring is a big thing in the game so don''t be scared to go out and explore. My only issue the moment feels a bit weird is all. so anyone complain that the game does not hold your hand. sorry but games should never hold your hand ', 'I have been on the fence about whether to get this game for at least a year. Now, I decided to give it a try. Interface is clunky and awkward. Frame rate and controls are janky, no matter what resolution I choose. The biggest problem is that there are long periods where you simply can''t do anything. Why should you have to stand around for 5 minutes slowly recharging your suit? this is something that should take like 5 seconds, tops. What can you even do in the pod when its too cold outside? slee', 'Mostly Positive', 70.57, 16.45, 1.53);
INSERT INTO reviews VALUES (26107, 758730, 132, 'Excellent first video game for a four-year-old! Think Super Mario, but without the frustration of being able to die. Recommended!', 'I didn''t like this game. It''s boring, And it''s the same thing over and over again. It was a mistake to buy this. I tried to get a refund, But it didn''t work. So I had to permanently remove it.', 'Very Positive', 84.85, 24.10, 3.15);
INSERT INTO reviews VALUES (26111, 758870, 2276, 'Kynseed is a beautifully done generational rpg game, It can be painfully pun-y at times, and maybe a little cheesy, but: \n-the story is great \n-the fishing isn''t a massive pain.\n-there''s lots of different stuff to spend your time doing\n-the characters are diverse and constantly changing (albeit they can be a *bit* weird at times) \n- after adulthood you don''t *have* to sleep and there isn''t an energy bar so you can just do stuff as much or as little as you want.\nIf you enjoy fairy-tales and sligh', 'I''ve tried to play this game a few times and I just get so overwhelmed. There''s a lot to do and it throws new things at you at a very fast pace. The days go by too quickly to let you do anything. If you try to keep up with the tutorial tasks you''ll not get through them and still have a ton of other things in your task log to potentially do that you just don''t get to do. I wanted to love it but I get hours in and feel like I''m drowning in tasks and not getting to explore, learn, or have fun.', 'Very Positive', 81.85, 178.97, 8.73);
INSERT INTO reviews VALUES (26116, 758990, 1981, 'I love this game. I play this game so much. Its so simple and fun, its basically creating battles of ur own but with all of the different technology they used in history. Its fun to make battles and make ur own units. 1000 hours on it so yeah definitly play this game.', 'this game looks fun at first but its only fun for like 20 minutes and then its boring asf im curently refunding the game, the price is to high for such game, TABS is 100% better and way more fun and easier to download complex mods', 'Overwhelmingly Positive', 95.86, 1020.50, 0.43);
INSERT INTO reviews VALUES (26125, 759440, 213, 'This game is fantastic for getting started with your Kanji basics. I do suggest creating mnemonics for the kunyomi and onyomi readings. Also learning 1 word for each reading will help you better recall it. \r\n\r\nI wish there was a continuation to the game with even more Kanji, oh please creator Gods hear my prayer! :D', 'в первую очередь это не игра. это средство изучения кандзи, но разработчики решили усложнить эту задачу. и вместо того чтобы изучать кандзи - ты повторяешь одни и те же бои. потому что боты делают по 2-3 удара сразу и сносят все хп. я не совершаю ошибок в кандзи и вопросов ко мне быть не может. просто игра, как игра, получилась полной ерундой. играю на харде. в описании сказано, что разница между хард и нормал в наличии ромадзи.', 'Very Positive', 82.63, 69.78, 33.13);
INSERT INTO reviews VALUES (26131, 759740, 1177, 'RIDE 3 is a dream come true for me because it features my ultimate baby: the BMW R 1200 GS (2016). Unlocking that masterpiece through the dedicated DLC, which also comes with an extra volume and five bonus events, is such a treat. The game itself is a blast, but honestly, just seeing and owning my dream bike in-game makes the experience so much better. Highly recommended for any bike enthusiast.', 'Crashing on Windows 11.', 'Mostly Positive', 79.44, 7.62, 14.00);
INSERT INTO reviews VALUES (26147, 760060, 6266, 'The stealth mechanic is a refreshing take on tactic games. The levels feel more like a puzzle to solve than a tactical strategy to win. Great theme that walks a line between gritty and silly. Really fun and highly recommended.', 'Bad combat mechanics ruin this otherwise great game. The story, voice acting, visuals, characters, etc are all superb, but having to plug each enemy with round after round just makes it tiresome. I get that you can sneak around a lot of situations, but most of the battles 8 hours in have been dissatisfying. It would just take tweaking a few combat-related properties to make this game much better.', 'Very Positive', 89.24, 26.48, 9.47);
INSERT INTO reviews VALUES (26155, 760330, 243, 'Addictive. Charming. Tiny, yet I feel like this is as much of an experience as more mainstream games. Also, I feel like there''s a few things that this game does that other games could easily, and perhaps should obviously pick up on. If you play it you''ll see what I''m talking about.\n\nHello Arnold.', 'ByteWrath - really infuriating.', 'Very Positive', 91.77, 22.97, 0.55);
INSERT INTO reviews VALUES (26159, 760410, 294, 'Good Horrorgame', 'I wanted to give this game a good review since it was so inexpensive but I can''t recommend it. The graphics, story and performance are pretty good but the gameplay is the issue. Multiple times I had issues with getting the indicator to show that you can interact with something. It was also jank when it did. Like trying to grab something in a drawer but it keeps closing the drawer instead of grabbing the item. Secondly, the chases are just tedious. You die instantly when caught so you will die ov', 'Very Positive', 82.31, 1.95, 7.92);
INSERT INTO reviews VALUES (26168, 760630, 100, 'Just an outstanding game. If the idea of tennis management game sounds good to you, then it is hard to imagine how this could be better. Maybe a graphics or presentation update, but that feels like nitpicking as it gets all the important things right.\r\n\r\nThe gameplay is so smooth. The players play like their real life counterparts. The training and tactics feel meaningful and rewarding. Strong recommend for people who like sports management games.', 'The career mode is fun to begin with, but as you get to the top of the rankings it becomes a chore trying to keep your stats at a high level and competitive with top players.', 'Very Positive', 92.00, 469.95, 29.97);
INSERT INTO reviews VALUES (26169, 760640, 298, 'An outstanding tennis game with the must-have XKT mod. \n\nI''m an OG Super/Virtua/TopSpin player from the distant past, and thought I could scratch the old tennis itch with TopSpin 2K25. TopSpin looks great, and I don''t hate it, but after 50+ hours of uninspiring gameplay that never felt like proper tennis, I decided to give TE4 a shot. I went from doubtful to completely addicted in a matter of hours. The gameplay feels like real, exciting, dynamic, no nonsense tennis. The AI players have their ow', 'I currently do not recommend this game. If it weren''t for the scarcity of tennis games and the positive reviews, I wouldn''t want to play it any more. Here are my points:\n\nPros:\n\n1.Good feel in rallies, satisfying exchange experience, but note it''s only rallies!!\n\n2.Characters show growth.\n\n3.Expandable with thoughtful mods (can add real players and tournaments, improving \nconnectivity).\n\nCons(mainly concerning AI opponents):\n\n1.Unrealistic AI at the net, low error rate on computer volleys (can b', 'Overwhelmingly Positive', 95.64, 85.62, 35.43);
INSERT INTO reviews VALUES (26170, 760650, 996, 'Definitely worth $2.50, already played 4hr in the first night. \n\nKind of like Oxygen Not Included, with maybe a little more forgiveness.\n\nEDIT: I did just want to pop back and say, after exploring a LOT more, and discovering the rest of the biomes, the game is definitely visibly struggling to keep up with the size of the map at 3x speed. Thats coupled with the fact I only have 12 dwarfs of my possible 41, and I''m playing on the smallest mountain map. \n\nGot a feeling a mega colony on a large map ', 'DON''T BUY IT, devs abandonned the game.', 'Mixed', 54.22, 14.23, 4.03);
INSERT INTO reviews VALUES (26178, 760890, 864, 'The perfect epilogue, the perfect prologue. The end of the childhood of someone who finally got to have her own. The beginning of someone''s free existence in a world unlike her original. Two girls who realized the horrid truth of their own existences, and the sorrow and apathy they felt. One man, one life, the father who loves them all. And then there''s you.', 'Edgy pseudo intellectual cringe story about kawai psycho crrazy anime girl who is so kawaii coo coo kill knife #deep #philosophical #depression\nI can''t believe it wasn''t written by kill for senpai 14 years old girl \n#deadinside #horror #it''s not just a phase mom #mom don''t embarrass me in front of my friends\n\nI am big lover of this genre but this is not something that a normal human being ( older than 12 ) can consume with a straight face  \n\n#edgy #freddyfazzber #crazy #8th grade #meinkampf', 'Overwhelmingly Positive', 98.61, 22.72, 1.07);
INSERT INTO reviews VALUES (26190, 761030, 223, 'Fairly straightforward turn based RPG. Not too complex. I enjoyed the first 37 hours then reached level 20 and it felt like a bit of a slog towards the last few hours I played. It would be nice if the lower level monsters would flee from the party like other games I have played. It just makes for tedious and unnecessary battles since there is really no reason to grind after level 20. The attribute perks felt a bit underwhelming as increasing any stat didn''t seem to have any affect on combat. I h', 'It''s ok for a while, but it falls apart in the second half. There isn''t much depth and even though its a shorter RPG (20ish hours) the lack of content drags it down, and what content there is gets repetitive quickly. Main quest is influenced from 90s and early 2000s RPGs but all the twists and turns have been done many times over, while side quests are mostly just collectathons. There''s this rather tiresome side quest near the end of the game that is locked behind doing a bunch of resource gathe', 'Mostly Positive', 79.82, 39.57, 32.75);
INSERT INTO reviews VALUES (26208, 761350, 129, 'Interesting lore and story, good Papers Please-esque gameplay, different choices. Watch out what choices you make, you might need to replay several levels if you make the "wrong" ones and get stuck\n\nSolid game', 'The Good: There were care and effort put in the game. The pixel graphics are pleasant to the eye and perfectly reflect the environments and scenes presented in the game. The music at times can be calm and soothing, almost making you forget the "reality" of what is happening in the story. Mechanically, the game works as intended and I did not encounter any bugs throughout my play. As other reviewers have pointed out, the game is inspired by Papers, Please and at times the influence is less than s', 'Very Positive', 86.82, 16.02, 7.13);
INSERT INTO reviews VALUES (26211, 761460, 540, 'I''ve actually beaten "Lamplight City" before, off GOG, so I thought I''d write a quick review before I continued replaying it in preparation for its upcoming spiritual successor "Rosewater". It''s a point and click adventure game of the old school—in the sense that there are no dead ends and the puzzles are mostly logical. Well, sort of: It''s also a detective game, so it''s structured to let you give up on solving a case, which affects the ending. It also means that you can close off avenues in you', 'Some cases you may lose because you do things in the wrong order that you have no way knowing about, just pure luck.\nOther than that, the game is good, but this one is a dealbreaker for me.', 'Very Positive', 88.33, 4.50, 5.82);
INSERT INTO reviews VALUES (26214, 761600, 1175, 'No matter much time passes, no matter how many pretenders to the throne there may be, Onimusha will always be the king. This is the peak of samurai games.\nCapcom please port the rest of this series', 'I love this game BUT Capcom added silently a shitty DRM (Enigma Protector) to it with the newest patch. It''s not even reflected on the store page.\n\nThe only purpose of this is to make modding the game more difficult. That''s shady business and I would refund the game if I could.\n\n', 'Very Positive', 94.64, 3.83, 153.33);
INSERT INTO reviews VALUES (26215, 761620, 941, 'Having not played the first game I had no idea what to expect but I must say I was thoroughly impressed! Oddly enough, the closest game to this I would say is Kindergarten, where you have a certain number of actions in a day before you have to go to bed. It makes every day feel tense as the consequences of your poor actions keep piling up. Nevertheless, with enough trial and error, it was truly satisfying to get to the top of the corporate ladder! Just don''t play this game if you want to have a ', 'I really appreciate the style and premise of this game. But, I don''t think it''s terribly fun to play. The gist is that you''re a low-level  bureaucrat working in a DMV-like office for an autocratic state (think North Korea). Part of the game is performing a Papers, Please like game of manning a booth to issue paperwork to folks. But, it isn''t as interesting or clever and often feels arbitrary. Which is a big critique of the overall game. When not in the booth, you''re trying to uncover details of ', 'Very Positive', 83.21, 12.40, 3.83);
INSERT INTO reviews VALUES (26226, 761830, 1712, 'This game is ideal for those of us who don''t really have a life, but want to survive anyway. You know who you are.', 'I think there might be a good game in here, but if there is, it''s buried under suuuuuuper tedious and time consuming make-work you have to do every single goddamn day over and over and over again. By the time I got a few days into the game, I was surprised I didn''t have to cut down trees and manufacture toilet paper so I could manually wipe my ass every morning.', 'Very Positive', 83.18, 52.72, 1.32);
INSERT INTO reviews VALUES (26228, 761890, 889, 'I''d love to play this game more and progress further but the risk of dying and losing gear is just not worth my time. I can see why people love this game and it''s system. I personally would definitely play this a lot more had there been a way to preserve at least my equipment on death.', 'To be honest, the game isn''t actually that bad, at least if you only want to play up to the midgame in terms of equipment and so on. But as soon as you enter the early lategame (equipment level 6+ in my eyes) and then you think you have to collect the resources for your equipment yourself, the nausea sets in. There are simply far too many players (I would love to write a litany of insults and curses for these players here, but I don''t want the review deleted, so I won''t) who have made it their b', 'Mostly Positive', 70.19, 36.60, 322.23);
INSERT INTO reviews VALUES (26229, 761910, 321, 'absolutely amazing game, just sucks that nobody owns it.', 'overall neat game, but unfortunately no one owns it and it''s hard to find a good group to play with. playing with friends is really fun for a bit, but the consistent community is pretty toxic. not worth your money imo.', 'Very Positive', 86.60, 43.45, 59.53);
INSERT INTO reviews VALUES (26243, 762220, 584, 'You got to fight for your right to party!\n', 'I wanted a fun lighthearted game drinking with the devil in hell. Instead I am stuck with the two most boring stuck up dorks in gaming history and have to listen to their unskipable cringeworthy banter. Only thing worse is the demon that is supposed to torment them and fails miserably. I hope when I finish this I get to see them burn. Only reason to continue playing honestly. I want the worst for them.', 'Mostly Positive', 70.72, 10.07, 5.38);
INSERT INTO reviews VALUES (26257, 762610, 150, 'One of the best!  A first-rate modern arcade game with inexplicable theming that adds depth on depth with each new level of the campaign mode -- and an endless, proper arcade mode that will keep you gamin'' well after bedtime.  It feels really tough when you pick it up, so hang in there, squint those eyes, and seriously engage with the game''s special ballistics.  Because it''s worth it.\n\nCampaign is a whopping 36 stages in which you collect bones -- used to unlock later levels -- by completing inc', 'It''s a silly simple game that feels like it was designed in the 80''s before people really had a chance to see good video game design. \nLiterally bark at people and get the food they drop... really? And you have to grind each level for a few boring minutes until you get a crumb of a new mechanic like another dog that competes with you?!\nIf it was cheap and you''re into a time-waster then I would recommend it, but the price makes it atrocious.', 'Overwhelmingly Positive', 97.33, 23.20, 0.10);
INSERT INTO reviews VALUES (26259, 762650, 588, 'This is a criminally underrated game. It''s one of the better Banish clones. It''s essentially Banish in the wild west but with some unique mechanics. Like cemeteries are for burying the dead not just to make people happy. And if you don''t bury the dead, they rot in the street and spread disease. You have to build outhouses or people will poop in the streets and spread disease; I love this little logistical consideration that I don''t think the other games consider. A lot of reviews say it''s boring', 'Clunky, unfinished. Little more than the content of a cell phone game, but decent entertainment for $3 once you get the hang of it.', 'Mixed', 60.88, 80.98, 34.75);
INSERT INTO reviews VALUES (26263, 762830, 640, 'Okay so, the game did leave me a bit confused on what exactly was happening fully, but I got the gist of it. I think it''s worth playing when you''re bored with time and patience to watch videos. You can eat or snack while playing lol. It''s definitely left me not wanting to play it again because I don''t think there is any replay value. Getting it for cheap, like a few bucks isn''t bad.', 'If you claim to enjoy fast forwarding through minutes of people nodding to unheard conversations, then YOU''RE the one Telling Lies!', 'Mixed', 62.03, 6.00, 5.93);
INSERT INTO reviews VALUES (26264, 762840, 356, 'I thought this would be a nice lighthearted puzzle game.  A couple hours later, it''s tugging at my heartstrings, and making me melancholy over my life''s choices.  Still a fun puzzle game, though.', 'The puzzles were full of personality, and their concepts and presentation were excellent. However, the overall design, controls, and narrative felt somewhat lacking. The game had the potential to be amazing, but compared to the creativity of the puzzles, the other aspects felt too ordinary, which was rather disappointing.\n', 'Mixed', 64.89, 5.28, 4.33);
INSERT INTO reviews VALUES (26270, 762940, 208, 'After finishing the main story, this game is absolutely precious and wholesome. However, there are a BUNCH of glitches, one of which was nearly game breaking for me (don''t ever change your resolution). Others required me to start entire days over (don''t get caught on the snowy mountain 3 times, don''t click through the fishing booth dialogue to fast). Then there were others that effected absolutely nothing, but were still present (that one bush that doesn''t adjust with the seasons, outfit changin', 'This game is so cute and so fun and you can''t enjoy it at all. Played it on the steam deck because I was warned it doesn''t work on the switch. This game you literally wake up with a long loading screen, walk out your front door long loading screen, walk to the store long loading screen, walk to bus stop long loading screen, I can play another game during the loading time my play time is 75% loading screen what is wrong with this game', 'Very Positive', 81.25, 34.88, 25.23);
INSERT INTO reviews VALUES (26275, 763030, 122, 'ABK should voice everything in my life. Also a great adventure game.', 'How many times do I have to ask for this?  If  you put a QTE minigame in a point and click or hidden object game PUT A F***ING SKIP BUTTON FOR THE BENEFIT OF THOSE WHO SUCK AT QTEs games\n\nThis is just another game that I had to unistall and ask that be deleted from my library because the developer never thought about his customers, only his ego\n\nIf I never see another game from tis developer it will be too soon', 'Very Positive', 92.62, 8.52, 3.08);
INSERT INTO reviews VALUES (26279, 763100, 128, 'hi', 'keep playing this game and save my progress only to come back to a new game', 'Mixed', 64.06, 24.28, 6.30);
INSERT INTO reviews VALUES (26285, 763250, 153, 'Very good puzzle game. I was recommended to me by ChatGPT when I asked for games like Portal or Talos. I was not disappointed. Good puzzles and moving story. Only thing that I would add is more puzzles. Definitely recommended if you like puzzle games.', 'Started off in a cold hotel with no real direction, then after finding a random table and entering 1 code, it switched to a weird color puzzle game, that just got more and more difficult. Identity crisis. Horrible.', 'Mostly Positive', 75.16, 11.18, 0.52);
INSERT INTO reviews VALUES (26314, 763890, 11247, 'If you need a multiplayer game for your friends, this is it. Our friends and I used accents for each of our characters and read all of our lines. It was incredible. We will return.', 'Breaks my heart not to recommend this game because it checks off so many boxes. However, After almost 45 hours I just simply could not handle the writing anymore. It reminds me of something a moody freshman in an introduction to poetry class would write. It''s cringy at it''s best and a grammatical mess at its worse. \n\nThis is the issue with small indie studios, they''re usually great at some things and not great at others. In this instance, the writing was a hard miss. If you like to skip dialogue', 'Overwhelmingly Positive', 95.36, 105.47, 44.90);
INSERT INTO reviews VALUES (26318, 763970, 111, '10/10 would recommend.  Pirated the game back in the 90''s and bought it here to pay Al back.  I talked to Al and found out that he won''t see a penny from the sales on Steam so I sent him a donation on his site. He''s a legend!  So if you''re trying to make good for stealing it back in the day, go to Al''s website instead.', 'Larry is actually so stupid it hurts me that i cannot see his perverted and depraved growth as a character due to its unplayable state', 'Very Positive', 85.59, 2.10, 0.25);
INSERT INTO reviews VALUES (26322, 764050, 543, 'I have zero complaints about this game. It''s great. It''s free. The biggest ''issue'' with it is more players don''t play it. but it''s a great game.', 'Matches full of bots. Steamcharts says under 20 players online. But hard battle pass, shops, P2W and so on. Just let it die.', 'Very Positive', 80.29, 27.02, 20.47);
INSERT INTO reviews VALUES (26327, 764230, 117, '0% drugs\n0% alcohol\n0% violence\n0% nudity\n100% cute anime girls (kissing is optional)', 'the only reason i have any hours on this game is because i played it as a dumb 11-12 year old ignorant to the obviously pedophilic undertones and the only reason i''m writing this is cause i think any game where looking at children''s underwear is a feature deserves more bad reviews . if youre grown and playing this please take a shower and go outside to touch some grass (preferably very far away from any school)', 'Very Positive', 92.31, 54.70, 18.18);
INSERT INTO reviews VALUES (26330, 764300, 369, 'How to run the game at 60 FPS on a high refresh rate monitor:\nGo to: C:\\Users\\YourUsername\\AppData\\Roaming\\WayForward\\ShantaeHeroUltimate, change vsync=false to vsync=true. Then, go to NVIDIA Control Panel, navigate to Manage 3D Settings and limit its FPS to 60.', 'As much as I love this game, this is such a bad port', 'Very Positive', 90.79, 8.65, 6.03);
INSERT INTO reviews VALUES (26352, 764790, 4325, 'It is indeed very good, but it has a bit of a tension that prevents it from being a true classic. For the first 30% of the game, it is an extremely linear retro platformer, then it opens up into a modestly scaled Metroidvania. The tension is in the timing of this switch though, as the retro action platformer portion is so long that it can mislead players. For players looking for action platformer, enough of a gameplay loop is established that when the Metroidvania structure is finally revealed a', 'The first half of the game is a very good Action/Platformer. The second half, for some reason, is a VERY bad Metroidvania, full of fluff to artificially extend your playtime.', 'Very Positive', 92.67, 41.62, 14.32);
INSERT INTO reviews VALUES (26357, 764920, 302, 'So, Purchased this game some years ago now as a youtuber i watch was playing it at the time, Please dont get me wrong is the game worth what there currently charging for it... yeah, big open world, plenty to do. however you will hit a dead end pretty quick if you are familiar to zombie survival games. Now my primary concern is that they ARE still charging for a game that has  had no updates that i can see in a hand full of years, which in my option is such a shame because Dang could this be of t', 'Another game by Snail Games that was just abandoned after releasing into "Early Access" \nit looks like they removed it from the game description. I wont buy another game from this publisher/developer. \ntruly disgusting behavior', 'Mixed', 50.00, 85.25, 9.25);
INSERT INTO reviews VALUES (26383, 765410, 5897, 'as of now 9/10 game... but whenever the Sex update comes out it will be a 10/10', 'Apperently this game has become a trojan horse twice? According to the reddit the game has been hacked into and turned into a trojan horse which means my computer may no longer be safe. Why is this the case? Why is beanbattles not just a game that lets you have all the files in your pc? This would allow self-hosted multiplayer and local play as well as custom maps easily being modded in without having to rely on a server. \r\n\r\nAfter 21 hours of amazing gameplay, I have to start worrying about the', 'Very Positive', 94.83, 36.52, 51.80);
INSERT INTO reviews VALUES (26407, 765810, 1422, 'I''m elon musk', 'The developer of this game openly admits that they don''t fix even the most basic bugs in their games. They are unable to even fix the simplest sound bug that appears always and at any time, every time. Why? "Because it''s not worth it." Just that. \n\n Don''t buy such games. This creator is pathetic', 'Very Positive', 82.63, 3.75, 37.47);
INSERT INTO reviews VALUES (26411, 765870, 645, 'I initially despised this game. I found Larry''s voice acting to be grating, the jokes to be ill-timed & ill-intended, and the premise to be profoundly puerile. But my love for mad-cap point-and-click adventures along with some well-designed inventory puzzles eventually won me back. \r\n\r\nI also must admit that the game isn''t as misogynistic as it initially appears. All the characters are flawed, and many of the women, while objectified by Larry, are written with more depth, albeit typecast depth, ', 'Starts well/funny, Larry''s voice weak acting, art is superb but for me personally falls down to toilet level jokes too fast and too soon and it kills otherwise good start and then it follows at that pace. Cant compare to old games, never played them. A tad too much running around different places and collecting way too many items before you can make use of them. And dialog a must to get something out of characters all the time petty much, some times you have to talk a lot before you get to a lin', 'Very Positive', 82.95, 12.22, 4.85);
INSERT INTO reviews VALUES (26412, 765880, 127, 'Such an amazing game. I''ve never played anything like it. I''ve played it through once and now enjoying many replays of chapters. There''s so much to do and explore. Totally worth it.', 'I played a level for one hour, then a game breaking bug took me to a black screen that I couldn''t leave, unless I quit the game. When I returned, the progress hadn''t saved. No way I was playing through all that again for one hour. The game looks nice, but it simply doesn''t work.', 'Mixed', 69.29, 95.88, 2.77);
INSERT INTO reviews VALUES (26414, 765900, 249, 'This is the Elden Ring killer', 'cant play the game. does not work\n', 'Mostly Positive', 75.50, 9.95, 44.95);
INSERT INTO reviews VALUES (26428, 766280, 206, 'To be honest initially I expected the plot to be quite different (the Steam page made it appear to me like some apocalyptic suspense action lol), I was surprised that it ended up so close to reality. Although I definitely enjoyed it regardless and it actually evoked that "reality-check"-like sense of emptiness within me.\nFirstly, I really adore the art and music, they perfectly capture the setting''s ambience and story''s emotions. The plot itself is almost absurdly simple yet manages to create so', 'I get that the two major characters having inaccurate views of the opposite side is intentional, but goddamn is the MC an unlikable asshole.', 'Very Positive', 87.86, 6.65, 2.78);
INSERT INTO reviews VALUES (26430, 766320, 124, 'meta quest 3 users may experience crashes during loading, but the developer page provides an easy solution.\n\nVR game featuring immersive mage combat and plenty of puzzles. The price is reasonable for a VR game.', 'Wasn''t able to get game to start. Game crashes immediately with Unreal error screen. Tried everything what was available in the interwebs, but no luck. Had to refund the game.', 'Mixed', 66.13, 10.83, 0.32);
INSERT INTO reviews VALUES (26469, 767390, 277, 'I can say without a doubt , this game is a winner. We can sit here and nit-pick all day long like some other reviews which say the co-driver is screaming, it doesn''t support VR blah blah blah... but show me another game that costs $2,99 (on sale) with 2 out of 3 DLC that is free and gives you this kind of cool driving experience in unique conditions with a variety of vehicles and the ability to be PvP as well. Not many games like this out there at this price! Pick it up, you can thank me later.', 'The premise of open world navigation coupled with motorsports was intriguing enough to have a look. Sadly, the game lost me during the first few minutes of the tutorial - there''s a muddy patch that you''ll have to traverse, and despite the offroady nature of a game bearing the name DAKAR, the sensation of "driving through mud" just was''nt there. If you played Mudrunners before, you''ll likely be in the same boat. \n\nSame goes for driving on sand, which you''ll be doing alot - there just isn''t any fi', 'Mixed', 66.79, 2.50, 0.33);
INSERT INTO reviews VALUES (26488, 767930, 462, 'Devil May Spy', 'For being made by a single person, this game is decent. It has many flaws, redundant combat, button mashy game play, lack luster character designs and development. It is not that strong as a game. The fact that I flew through it in less than 2 hours says a lot about the single play content of it. From what I saw, I think having two characters but letting them go through the same exact levels is again, redundant. And the game could have very well benefited from extra run time, more unique ideas, ', 'Very Positive', 92.42, 1.23, 1.82);
INSERT INTO reviews VALUES (26499, 768200, 3783, 'Finished the game from start to finish. Oh man what a game! Everything about it is captivating, you can play for hours without getting bored. Though I have no friends, this game was just as fun to play solo. I highly encourage anyone looking for a new building survival game, to download this asap!', 'Disappointed in the multiplayer experience. My wife and I thought we''d be able to build together like other co-op games like Valheim and Enshrouded. Nope. Had to build on separate trees. Then, at a time when I was logged on alone, I accidentally claimed her tree. When she logged back on to play, her house and items were gone. This game was clearly not designed with multi-player at the start. It was an afterthought so can''t recommend if you''re going in with that in mind.', 'Very Positive', 82.50, 72.18, 19.55);
INSERT INTO reviews VALUES (26504, 768450, 484, 'Really not what I expected at all - for some reason I thought this was going to be a zany psych-horror-comedy about a researcher being driven mad by squirrels, and instead it''s actually a rather serious environmentalist thriller. Basically a much better Firewatch in some ways. The puzzle elements are rather unique, as you have to place video cameras during the day and study the footage at night, essentially making this a very unconventional detective game. I can understand why some might conside', 'The game is very pretty, in a sense, but the high contrast does sometimes make navigation and tracking difficult. The storyline itself could have been more intriguing, and the gameplay falls a little flat. On sale (as it is now) for $3 it''s a wonderful purchase. Priced at the full $20 I would definitely skip.', 'Very Positive', 86.78, 4.47, 2.78);
INSERT INTO reviews VALUES (26507, 768520, 1133, 'A good PvE game. Extremely niche shooter with lots of fun once you understand a few thi-\r\nNetwork error: Pending connection failed\r\nNetwork error: Pending connection failed\r\nNetwork error: Pending connection failed\r\nNetwork error: Pending connection failed\r\nNetwork error: Pending connection failed\r\nNetwork error: Pending connection failed', 'I''ve come back to this game several times hoping that things would be better, but no.  The tutorial is essentially "let''s throw all the infos at you at once via dialogs and clicking continue and we hope you remember it all".  Even the initial mission, which is essentially somewhat of a tutorial gets it wrong.  One of the first choices is RTS or WASD controls.  I''ve tried both, but upon choosing WASD the tutorial proceeds to show RTS info - which is all wrong for WASD mode.\n\nAnd then there''s all ', 'Mostly Positive', 78.46, 122.77, 11.10);
INSERT INTO reviews VALUES (26515, 768750, 115, 'Best marketing ever.', 'This is less about puzzling and more about a big terrible maze. I got to this one part where the puzzle was just an invisible platforming challenge, and it was then that I noticed the game had a timer.. I spent a half hour in there and the timer ran out and sent me back to the beginning.\n\nYou get a map that draws itself out when you go through the maze but it has no pointer to tell you where on it that you are.\n\nIt''s no fun,, I would compete for the prize if it was at least a little enjoyable bu', 'Mixed', 43.48, 1.95, 1.52);
INSERT INTO reviews VALUES (26553, 769670, 128, 'It''s an improvement from my old one which kept crashing every few minutes.', 'The screen recording feature stopped working for some reason. Kinda bad if you consider that its the main feature of a screen recording software which also costs money. After 1000 hours of use i can say that i do not recommend it. It used to do its job but there were lots of minor downsides like crashes when trying to record certain programs, random lags and freezes while using the built-in edit feature and game recording feature just straight up not seeing some games. There are better paid alte', 'Mixed', 66.41, 102.52, 1012.17);
INSERT INTO reviews VALUES (26562, 769950, 233, 'Fun turn based game a little baffling at first but soon worked it out. I liked the style and graphics also the combat outcome is slightly different each time but not outrageous. so reloading does not always help. The game benefits aggressive but thoughtful play and care and attention should be given to preserving core units throughout the campaign. Overall I enjoyed the game and am looking to purchase more titles from the developers.', 'I, too, am a big fan of Slitherine.  I''ve tried to like this game; really tried.  After some 30+ years of PC turn-based war games, I''m crushed at the failure this is.  I''ve put in 23 hours, so a refund is not possible.  Nor should it be.  But this is awful.  \n\nThe "strategy" is ludicrous.  Poland...ok.  France...ok.  Norway...ok, sort of.  Dunkirk...  That''s as far as I got.  I tried the battle three times.  My Luftwaffe, well, never mind.  You cannot attack in the face of AA--the game mechanics', 'Mixed', 58.80, 239.12, 42.12);
INSERT INTO reviews VALUES (26563, 769970, 310, 'It features a different style from the previous work, and while there are some disappointing elements, it’s not bad overall.', 'Genuinely do not understand why this and its predecessor get so many glowing reviews. The puzzles are fine but the writing is awful. Broken English seen in every line, and crummy dialogue that doesn''t really mean much. Haven''t given a proper review in a while but this one made me annoyed enough to do so.', 'Very Positive', 80.97, 2.50, 1.18);
INSERT INTO reviews VALUES (26569, 770070, 124, 'This isn''t league of legends', 'Too buggy to play.', 'Mixed', 61.29, 7.32, 0.85);
INSERT INTO reviews VALUES (26572, 770100, 587, 'So ADDICTIVE!  I am loving it.  The progression system is awesome.  I did solo the first few hours and now I am playing 2 characters.  I have played the tabletop game, but I am really digging this PC version.  I haven''t tried any of the DLC yet but I am sure I will... I am having that much fun.', 'As a game developer and passionate gamer, I am deeply disappointed and saddened by the decision to feature only female characters in this game. In 2024, when the effort to include male characters could be as simple as adding an additional image per character, this choice feels particularly exclusionary.\n\nWhile I support female representation in games, this decision seems to miss the mark by excluding male characters entirely. It''s disheartening because it appears to support feminism, yet no woma', 'Mostly Positive', 78.88, 118.40, 2.55);
INSERT INTO reviews VALUES (26573, 770110, 106, 'Cute little game, could had been so much, sadly to short.', 'While the production quality of the game is relatively high, it''s very short and badly paced. Just after you finish being introduced to the world and it''s characters, it''s over. This is obviously intended as an opening chapter to a series of games, and it really should be advertised as such, i.e. "Twilight Path: Episode 1".\n\nActual playing time was about 1.5-2 hours. The "puzzles" are more about figuring out the game controls and mechanics. Nothing was any real challenge to solve. If you''ve play', 'Mostly Positive', 77.36, 1.68, 3.43);
INSERT INTO reviews VALUES (26578, 770240, 704, 'One of the greatest. Close control here makes EA Sports devs cry cause their game is The Sims.', 'Game is not for those who like to play OFFLINE, because you can''t anyway without an internet connection. Overall i have no problem with the graphics etc. What i hate what Konami have done is, the constant internet connection required in order to just launch the stupid game. You can''t launch the game without internet connection. Thats the biggest mistake Konami made. All their previous games did NOT require a constant internet connection. I have played PES games since the very first one. I see th', 'Mixed', 50.99, 1663.20, 138.27);
INSERT INTO reviews VALUES (26585, 770390, 927, 'The one RTG I missed out on. Finally finished in 2024. Game is a scenic tourism of a village in Norway. Lovely characters on the journey though I feel the mystery is a tad underbaked. Worth a play especially after finishing a long ass rpg.', 'I do not recommend playing this game. First off, this is a pure walking simulator (there is no challenge or difficulty in this game), so that is already bringing the marks down somewhat, but walking simulators can be interesting, they just have to excel in the story department or the way they integrate the story into the gameplay. This game does neither.\r\n\r\nThe gameplay basically never interacts with the story and it''s all just ''walk here and press the button to read''. And the story has the gall', 'Mostly Positive', 74.33, 6.22, 5.75);
INSERT INTO reviews VALUES (26589, 770490, 116, 'Death in the Water is a simple yet fun underwater survival game. The goal is to kill as many Great Whites as you can in one life while they tear you to shreds. The more sharks you kill the more that will spawn at one time which is scary, exciting, and challenging. The game is intentionally difficult and only the bravest of divers will survive for long. The sharks can swarm you from all sides which keeps you on the edge of your seat and your heart pumping. I have frantically yelped a few times wh', 'There''s nothing wrong with the game, but I wouldn''t spend money on it. You''re swimming in a bleak ocean fighting off increasingly larger waves of sharks with your infinite harpoon gun. It''s just kinda boring.\n\nI see that there''s a second game, and maybe that one''s a little more engaging.', 'Mostly Positive', 72.41, 0.42, 0.47);
INSERT INTO reviews VALUES (26599, 770810, 1917, 'Amazing game but if you think it''s a chill game you''re totally wrong, the customers asks u pizzas in such a complicated way sometimes u need to ask what 3 times, not to mention that when they ask for every single ingredient in their pizzas just to say "u could have done it a lil better" like no shi, i cant even see the topping i put in the beggining and sometimes this game make me rage quit. Other than that, nice game', 'This is a direct port of a free mobile game, complete with micro transactions, but they are asking for an up front cost on steam as well. Do not waste your money on the steam version when you could get the exact same game for free on mobile. It’s\nvery deceptive to call this a “complete” version of the mobile game knowing there are crazy amounts of micro transactions in this port.', 'Very Positive', 86.85, 28.43, 0.23);
INSERT INTO reviews VALUES (26623, 771350, 359, 'I love when steam crash from the achievements :D', 'It''s clear to everyone what this game is for.\nIt''s clear to everyone that this game is trash.\nIt''s clear to everyone that I am one of the people who knowingly gave money for this trash and why.\nIt''s clear to everyone that I need help.', 'Mostly Positive', 79.39, 0.18, 0.52);
INSERT INTO reviews VALUES (26628, 771420, 155, 'Feels like a really good SNES platformer lost to time.  \n\nVery short though (2.5 hours).\n\nSound & visuals were great.\n\nThe game has multiple New Game+ that apparently increases things like the amount of enemies, but I have not tried this yet.', 'Being Primal Light a game so deeply rooted in the past, it’s baffling to see gameplay mechanics elegantly nailed 30 years ago being convolutedly (unnecessarily so too) implemented in it: dashing, slipping down ladders, hanging from hooks, all need additional d-pad inputs here--never required in their original forms (e.g. Mega Man X, Aero the Acrobat, Darkwing Duck respectively); even sliding can get you stuck middle-action--despite its original flawless implementation in 1990’s Mega Man III sett', 'Very Positive', 83.87, 2.72, 3.93);
INSERT INTO reviews VALUES (26643, 771810, 215, 'A big surprise for James Bond fans. So many references and humor, I basically can''t stop the giggles. Would definitely play again, my solute to devs.\n\nGameplay is linear and simple, apart from a giant robot most enemies are one-hit kill, the fun part is to look at the familiar setting, items and characters. Calling M as Mother is funny enough, but that snow mission where Bond uses his partner as a ski sled cracks me up. It''s not a long game but full of memes, besides each level has 3 hidden targ', 'I actually played this game for a few hours some years back, and really enjoyed it, but in its current state I just cant recommend it. Something was changed in the way aiming works, now anytime you aim near an enemy your mouse sensitivity drops like 70% (think like scoping in does in some games)... I guess the developer thought this would help with aiming far away enemies, which I guess it does ?!?. But.... anytime theres an enemy close its also working, so youre stuck with about 30% of your mou', 'Very Positive', 81.86, 5.48, 4.27);
INSERT INTO reviews VALUES (26647, 771920, 152, 'i want her nude', 'It was fun, but it''s not worth the 14.99\nIt''s labeled hentai, so I assumed there was like actual action, there wasn''t any nudity or even anything that romantic\nit''s a mini-game collection with subpar jiggle physics. I played the whole thing in less than an hour. I feel a little bad for refunding, but it''s not what I was looking for.\n*EDIT\nI thought I should mention I didn''t watch anything because of spoilers and I didn''t try the DLC', 'Mixed', 61.84, 1.60, 0.98);
INSERT INTO reviews VALUES (26657, 772180, 114, 'drgfg', 'Honestly Terrible, They mixed up controllers from left to right the bat is never aligned with controller/ real life bat. The height is so off, im 183 cm but in game the stumps come up to my shoulders with no way to adjust the height,  re-orienteering the game is a night mare to align with the room you play in, even the center marking for the stumps is off and sometimes isnt even inline with any of the stumps. honestly i wouldnt even get this if it was free, it a horrible game and terribly design', 'Very Positive', 90.35, 29.60, 29.53);
INSERT INTO reviews VALUES (26665, 772290, 173, 'Rainswept is a good narrative game where you play as a detective to solve a murder. The designs are great and the ambiant is cozy. I recommend it!!! 💗💗💗', 'I''ve only been playing for an hour and a half but I''m giving up. First of all, it''s more of a visual novel than a proper point & click game, so there''s not much game to play. Still, that''s not the worst. The worst is that you spend most of your time walking from one place to the next at an extremely slow pace. There''s a map but there are no shortcuts. It''s really infuriating. Plus on Mac there isn''t even a "run" option so it literally takes forever. The story is interesting and I''d really like t', 'Very Positive', 84.97, 10.02, 1.48);
INSERT INTO reviews VALUES (26672, 772430, 499, 'This game is amazing.\r\nFrom the gameplay to the lore, this game is for casual and hardcore gamers alike. The lore is extremely rich and deep and it will keep you invested. I recommend this to anyone.', 'Hero of the Kingdom I: 10/10\nHero of the Kingdom II: 10/10\nHero of the Kingdom III: grind/grind\n\nDo not ruin your expectations if you enjoyed two previous games.', 'Mostly Positive', 76.75, 9.75, 7.98);
INSERT INTO reviews VALUES (26679, 772540, 225, 'Best PUBG trainer I''ve come across. Lightweight, fast loading, three scenario (urban, countryside, wooded areas) trainer with AI opponents who range from not too dumb (keep moving around) to idiotic. None of them are smart enough to move to the shrinking circle so you can sometimes win by default (though the circle will just focus on the area with the most characters alive. Few hide when health is low which could be because none of them can pick up health and revitalise. But some will have unerr', 'Battle Refund Trainer.', 'Mixed', 68.89, 148.65, 1.97);
INSERT INTO reviews VALUES (26706, 773370, 2913, 'Ball go fast i like🤗 but astronaut picture scare me😥', 'This game is weird. Yes, it is somewhat nice-looking and has its charm, but it''s basically a screensaver that you have to control for some reason. Every world is a bit too long and/or lacking new mechanics to stay fun, and controls are not always playing in your favor.\nAnd one of the main drawbacks is the game''s "plot". I assume it has one, but listening to scary and distorted voices talking something about Jupiter while you''re a glowing ball gliding through completely unnatural landscape... it''', 'Very Positive', 91.04, 4.20, 1.15);
INSERT INTO reviews VALUES (26719, 773580, 292, 'Nice micro management and steady new possible opportunities and challenges as time advances within the game. \n\n10 out of 10, would create a more greedy company then EA again.', 'Dev has long since abandoned this game. (last update was in 2020 iirc) Was really hope he would return to fix some major game braking issues and some extra content updates. \nThe dev listed the lack of sales as the main issue with not continuing to develop this game, I understand that, gotta support what puts food on your plate but I''ve not seen any effort to market this game since. Even through free marketing like advertising it in his newer games.\n\nI would even buy DLC for the game but none has', 'Very Positive', 87.33, 13.38, 275.28);
INSERT INTO reviews VALUES (26727, 773670, 762, 'An exceptionally good puzzle game. My only criticism is that it is nowhere near long enough.', 'Not worth it', 'Overwhelmingly Positive', 96.19, 2.30, 1.27);
INSERT INTO reviews VALUES (26731, 773790, 2579, 'I discovered this game I dont know how long ago, but my family comes from a Russo-Germanic village that sits in the basin of the Volga River, it was, before the Bolshevik Led German Cleansing of Russia, called Dietel, however, today its called Aleshiniki, it was settled around the same time this game takes place, As someone deeply attached to my families history, it helps me visualize it and appreciate it heavily.', 'Its been in an early state for years, part of why i no longer support solo dev projects', 'Very Positive', 92.79, 19.03, 5.02);
INSERT INTO reviews VALUES (26734, 773840, 238, 'Finally the racing game DRAG was meant to be!  Easier handling, full vehicle collision physics and a new campaign vs AI.   And it still runs perfect with vulkan native on Linux!\n\n*Updating this review to say that while all the above is true and makes for a great singleplayer game the multiplayer was a huge letdown.  \n\nIt''s currently matchmaking only.  It has no private games or choosing regions and from the one match I was able to join it appeared to be nothing but short time runs without any pl', 'ExoCross is quite fun. The vehicle physics feels great, with amazing suspension physics and great handling. The environments look very interesting as well. There is a solid game here, despite some AI having some pathing issues. However, it just doesn''t have enough to justify a $40 USD price tag currently. I recommend waiting for it to go on sale.', 'Mostly Positive', 71.01, 53.12, 2.30);
INSERT INTO reviews VALUES (26739, 773951, 5173, 'I bought this game during it''s initial release about 6 years ago. At some point, the original devs hired new people who screwed up their vision, and made the game just not enjoyable. They rolled it back to a stable release that was more in line with their goals, and hunkered down to work on it. For the first time in a year and a half in march, 2024, they released a progress update. I don''t know if it''s real, or it was just an update to try to get more purchases. The game itself is fun, it''s basi', 'When it first released it was a jank FPS shooter mount and blade. Which at the time was decent for what it was. Still luls were had. Nearly 7 years later, its the same thing. Don''t spend your money here. Deader then the relationship with your ex', 'Mixed', 62.15, 91.80, 95.48);
INSERT INTO reviews VALUES (26741, 774091, 255, 'Got it for the steam profile background. Was worth it', 'If there was a mixed review button i would of picked it but i have to give a thumbs down, yes i do like this game and yes i  am obsessed with the cold war, east germany, the berlin wall however the game is not polished well at all, yes i know all games from nostalgames or kremlin games are not well polished however china mao legacy was not hard to master and info about what everything is and does was easy to figure out. i do think the game is good and i do like it but info about what everything ', 'Very Positive', 90.59, 2.50, 16.43);
INSERT INTO reviews VALUES (26747, 774171, 28162, 'as a game this is certainly a good time         however there is are significant odds that you are metaphorically flashbanged by a loading screen of an adolescent in promiscuous attire and make you feel really sad. (or maybe it makes you happy but in that case we can''t be friends i don''t like you)', 'Bro, why do I have to pay for the majority of the songs? I already dropped $3 on the game, WHY aren’t all the songs unlocked? Just raise the price and include all the songs instead of shoving a DLC that is almost 12 times the price of the game. Yall can make DLCs for collabs or something idk, but this is BS.', 'Very Positive', 94.82, 16.18, 7.77);
INSERT INTO reviews VALUES (26748, 774181, 6109, 'This is a true rhythm game. Once you learn the sound cues, you could play levels with your eyes closed. It''s really a good rhythm game', 'its a well made game, but if you like rhythm games im not sure if you would enjoy this one.\n\nit started out good, but in the second stage the rhythm part of the game gets messed up. the game introduces new mechanics that literally change the rhythm itself, and it throws you out of sync, all while being VERY visually overwhelming. you go from pressing the button every X beats, to sometimes every 4 beats, sometimes every 2 beats, and sometimes you need to completly ignore the beat for some reason.', 'Overwhelmingly Positive', 98.79, 55.92, 1.10);
INSERT INTO reviews VALUES (26750, 774201, 1499, 'Initially I was wondering why this game doesn''t get more hype despite all the praise, and then I quickly realised that all the other reviews are correct: the travel mechanics of this game is frustrating. Hand sailing makes sense in new unknown waters, but on known and fully mapped out paths? I don''t think anyone would be interested in the exact minute details of Indiana Jones'' 8+ hours flight to the country of his exciting new dig location. Please just give us the exciting new dig location direc', 'Intriguing story, great music, unique graphics. That being said, this is the most frustrating game I''ve probably ever played, and to be fair, a lot of that is because I want to finish and keep trying to keep at it. There are no cloud saves, there are no branching saves, it''s super easy to fat finger the opposite of what you intended to do, going to a certain place will end the game with no warning (no, not the one you might assume, a different one). The only way to make this halfway playable is ', 'Very Positive', 86.79, 11.95, 59.28);
INSERT INTO reviews VALUES (26753, 774241, 1545, 'This game and Vermintide makes me sad when i play them, because i get reminded that we never get any Rpg´s in the rich Warhammer fantasy universe. This game and Warhammer Quest is the closest we got and i cheerish every moment i play this game', 'Shallya’s Mercy, this is Nurgle''s Rot!\r\nThe game is just a tasteless diablo 3 rip-off with more bugs than Greater Unclean One’s poopy pot. Not sure what is good here… The Warhammer vibe is somewhat present… but also in the most basic and repetitive manner.\r\n\r\nBut not all is lost. Gather you lads, set easy and crack open a Bugmans… you gonna need it… If not that, you''re gonna meet with Morr in no time, while napping on your keyboard.', 'Mixed', 60.97, 23.58, 3.53);
INSERT INTO reviews VALUES (26759, 774351, 672, 'Fun game, missing some elements of city building. Enjoying the Democracy style gov options. Republic of Banana has fallen', 'I am on mac and the game keeps shutting down every 5 seconds I cant even play', 'Mostly Positive', 74.70, 1.95, 6.72);
INSERT INTO reviews VALUES (26760, 774361, 15122, 'In just 5 hours I had 3 suicide attempts irl because of this game, The Game Kitchen really outdid themselves this time\n\n10/10 cant wait till I open the game and it ruins my day again', 'The art style, music, setting etc. are great and the game has kind of a cool vibe. However, I didn''t find the movement or combat that satisfying. There''s something quite slow about the Penitent One, and the game doesn''t give you tonnes of options in combat. Also, the platforming sucks, ladders are inconsistent to grab, and spikes insta-kill you, so I wouldn''t recommend it based on that alone.', 'Very Positive', 90.45, 4.97, 32.40);
INSERT INTO reviews VALUES (26766, 774461, 1945, 'good game but i dont have friends', 'Mad Verse City is the only reason to get this pack. YDKJ Full Stream is ok too I guess. Other packs have better games and better variety. You don''t want to show up to a party with Zeeple Dome.', 'Very Positive', 94.04, 0.33, 41.07);
INSERT INTO reviews VALUES (26769, 774511, 251, 'Nepgear''s my sunshine.. My only sunshine.. She makes me happy when skies are grey.. She will never know how much I love her.. please don''t take my sunshine away.. The other night, Gear.. As I lay sleeping.. I dreamed I held her in my arms.. When I awoke, Gear.. I was mistaken.. so I hung my head and cried.', 'its the same like Megadimension Neptunia VII that ive finished long time ago. I was expecting so high if this was different game but its just improved HUD/UI style, Simplified version of Megadimension Neptunia gameplay (lets just say, you dont have to meet multiple endings when playing with this one), performance issue is still persist, bugged fullscreen mode, and such. I would really love if the dev actually made a totally different games instead recycling the same assets from the previous Mega', 'Mixed', 62.95, 26.98, 142.17);
INSERT INTO reviews VALUES (26771, 774541, 785, 'The creator had made a mention about his mental health awhile ago. I would not expect this to receive attention anymore, but for a few bucks it''s already paid for itself. Don''t treat it as an outright sim, but more like an idle thing to futz with when you''re bored. I don''t feel ripped off, more disappointed this gem won''t be cut to perfection. Hopefully the dev gets some peace.', 'Game isn''t being worked on anymore, buy only if your okay with it''s current state.', 'Mostly Positive', 74.01, 32.40, 48.62);
INSERT INTO reviews VALUES (26774, 774651, 117, 'Although the game can be grindy at times, it is a perfectly enjoyable Mega Man spiritual successor.\r\nI wish the Elemental system was better well thought. I seriously dislike how the appearance of the shots have nothing to do with their elemental damage, and I dislike that I have to play some stages twice to get all items, but even with all that, I had fun.', 'I did not like the gimmick of having to be close to enemies to defeat them, it just kind of betrays the idea of, you know, designing levels.', 'Very Positive', 85.47, 7.27, 0.25);
INSERT INTO reviews VALUES (26777, 774791, 666, 'is was butthoe', 'This game was sold to a company that removed half its reason for existence, the multiplayer, and is now still advertising it as multiplayer. DON''T GET THIS GAME!', 'Mixed', 47.75, 0.87, 4.33);
INSERT INTO reviews VALUES (26778, 774801, 19946, 'You get to play as a crab with guns and Warframe level movement. You may not like it, but this is what peak gameplay looks like.', 'About 100 hours in this game, have been having a blast with it ... Until the "final patch" was released containing a ton of nerfs and making the game overall a whole lot worse.\nIf anything; the earlier waves should be made a bit more easy, and some essential upgrades should be made available to get without depending 100% on RNG. But they went the opposite direction catering for a small elite group of hardcore players.\nSo they basically ruined the thing that made it fun for the casual player to e', 'Overwhelmingly Positive', 98.06, 38.50, 252.58);
INSERT INTO reviews VALUES (26779, 774811, 589, 'I could never figure out whether Yume Nikki is the name of the girl or not. I googled it. Yume means dream. So by that logic, the game''s title is "Nikki''s dreams". Fitting title, right? WRONG! Because as I soon found out, "Nikki" means diary and "Yume" means dream. Does Nikki keep a diary? Well then, what about the title? Does it mean "Yume''s Diary" (Yume is the surname, Nikki is the name i presume) or "Nikki''s dreams"? I looked everywhere. Everyone told me it was "Dream Diary", but i already kn', 'The more you try to explain a dream, the less magic it holds. Analyze it too much, and it''s no longer a dream diary but a dream manual.', 'Mixed', 67.06, 9.82, 4.35);
INSERT INTO reviews VALUES (26788, 775500, 5056, 'Finally finish the game with 1st protagonist. Story line 10/10.  Game play and fighting mechanic 10/10. Beautiful environment and characters. It may take time to get used to the overall game mechanic but it really worth it. Post game really worth it... many unlockables and new game + so many things to explore. Recommended game. 10/10 star game.', 'The game is bad. The combat isn''t great with a dodge being the only way to really avoid damage, which doesn''t have i-frames but perfect dodges let you counter attack. You maybe can take 3-4 shots from bosses which most have fairly static move sets. It took less than 4 hours to get over the style of combat.\r\n\r\nWhile the combat is bad the story is somehow worse. The twists make no real sense and are set up poorly. The character development is bland. Dialogue is mix between boring and cringe. I hit', 'Very Positive', 86.37, 123.32, 5.23);
INSERT INTO reviews VALUES (26804, 775900, 224, 'This epic title works great with the UEVR injection tool to play in virtual reality! It also happens to be compatible with Yaw VR Pro Motion Simulators! Mostly plug and play using the Yaw VR Game Engine software. A great play for VR racing enthusiasts.\n\nYaw Motion Simulator settings:\nPitch Forward: 10\nPitch Backward: 17\nRoll: 26\nPower: 73', 'my motogp  18 games keeps stopping', 'Mostly Positive', 78.12, 0.08, 0.13);
INSERT INTO reviews VALUES (26807, 775940, 1262, 'very fun, game is abandoned use discretion to avoid wasting money', 'WARNING!!!!!!!!!!\n\nDONT GET THE GAME. THIS GAMES DOESN''T UPDATE. THIS IS PRETTY MUCH RISING FRONT: THE BETA VERSION', 'Very Positive', 85.10, 5.83, 4.30);
INSERT INTO reviews VALUES (26827, 776340, 270, 'This game made me realize. Its not so bad seeing how many times you can sit your butt on a bottle and moan. Also ARREST THAT STRAIGHT PERSON NOW!!! DO NOT LET THEM ESCAPE AND SPREAD HETEROSEXUALITY!!!\n\n10/10 made me fall in love with my bros', '0/10 thought gaypolice meant arresting gays', 'Very Positive', 83.70, 2.95, 0.13);
INSERT INTO reviews VALUES (26834, 776490, 499, 'I got brain damage', 'I used to really like this game back then but as time passed on it really started to rub on me how much unpolished overall it actually is. Trying to play this on Lunatic is like torture with how janky the enemies, the projectiles, your movement, and the hitboxes are. This game has a lot of soul and passion in it, I''ve beaten it once so I''m sure of it, but the polish is just not there man, this game deserves better...', 'Very Positive', 84.37, 11.72, 27.50);
INSERT INTO reviews VALUES (26854, 776960, 275, 'Buying for achievements', 'Literally Me (I''m The Scared Little Mouse)', 'Very Positive', 81.09, 2.10, 0.73);
INSERT INTO reviews VALUES (26863, 777150, 107, 'I don''t think the playerbase seems to have discovered the real potential. \n\nThis is an old school MMO like "The Realm" except that everybody is playing a stable of interactible characters.\n\nThe programming might be the dorkiest route to this end but it enables so many dimensions of interaction.', 'This game is essentially abandoned by the only developer, who seems to only check in every few weeks to make sure the servers are still up. Bugs are rampant and generally not fixed unless they start to become abused by more than a few players, item/skill balance is non-existent; and the paladin character was a work in progress when I started which is two years a this point. The entire economy is dictated by a group of ~2-3 players and due to the way item upgrades work you will likely never get y', 'Very Positive', 85.05, 5.12, 8067.55);
INSERT INTO reviews VALUES (26879, 777390, 1430, 'noe one will see this but it is a great game but takes a bit to get used to, also I will eat 1 cloth rag for every like\r\n', 'Sort of baffling that there is no undo feature. Like genuinely strange. There is clearly a LOT of love that went/goes into this project. But to not implement an undo button in a pretty technical 3D workspace is certainly an interesting decision. I''ll change this review to positive when it hopefully gets added.\nIn their discord they say \n>Undo Button (This is being worked on)\nas of april 12th 2024', 'Very Positive', 85.10, 254.92, 9.83);
INSERT INTO reviews VALUES (26884, 777470, 174, 'Nice space exploration & fighting game with a nice player community and a very active developer, who is present in the game talking to the community.\nIf you like lots of ships to choose from and slapping lots of different guns, shields, drones onto them, this is a very nice game to pick up.\nMay seem grindy, but become member of a corporation and you will receive a lot of help from your mates!\nI play on Steam and on my phone, works perfectly.', 'This game is very near and dear to my heart. I love it, I''ve spent over a thousand hours on it. It''s a great space based mmo that revolves around guilds called corps and involves "guild based" combat, but unlike other large mmos, the developer has artificially allowed a certain favored corp to monopolize power and terrorize players and other corps alike. The dev also overlooks their rampant toxicity that literally drives people to quit the game. It''s been like this for far too long and I fear if', 'Very Positive', 87.93, 61.15, 1744.23);
INSERT INTO reviews VALUES (26896, 777770, 207, 'i like This game, the only thing i extremely dislike is that i cannot play it offline, is that fixable??\n', 'Not the latest obviously - Warcraft 3 copy (with a mix of Paraworld) that offers little after 30min play on skirmish against AI. The maps are so tiny, it does not matter if you have ''unlimited'' resources/Unit expansion, because you will barely get to it. This is a game limited to one type of gameplay (1vs1, 2vs2, 3vs3) with the all-so-common ''Too easy or too hard'' issue. There is no such thing as best-comes-out-of-top skirmish as limited to 6 players and 4 teams unless you only want to play for ', 'Mixed', 66.67, 4.62, 1.07);
INSERT INTO reviews VALUES (26919, 778330, 138, 'This charming platformer is pretty good. Also, very difficult. Best time spent.', 'The dialogue is weak. The music is gratingly simple and loud until the lategame. The level design is buggy (I found two softlocks by just walking into them accidentally) and there''s a rookie mistake with the keypress events which makes it so that you have to let go and re-press the directional keys just about every time you die or change rooms.\n\nThose would all be forgivable if the game felt good to play. It doesn''t. The physics are slippery and raw and vary wildly with minute changes in keypres', 'Overwhelmingly Positive', 96.38, 23.43, 3.02);
INSERT INTO reviews VALUES (26923, 778390, 259, 'The stories are pretty good, but they might have been better off sticking purely to the visual novel format. The "gameplay" is just annoying. Seeing the more minor characters get some spotlight is pretty cool, and like in the first game there''s lots of gorey bad ends! It''s worth your time.', 'I''m sure the game would be great if it worked but quick saving breaks the game beyond repair, you can''t even start a new game anymore if you get hit by the glitch', 'Very Positive', 84.94, 23.22, 1.57);
INSERT INTO reviews VALUES (26924, 778400, 118, 'This is a silly game at it''s core, mostly just for fun! The stories range wildly from really really bad, to very superb! Total mixed bag. Overall though, it''s kinda nice to see the characters in different scenarios. I''d say if you''re already a Corpse Party fan, it''s worth reading!', 'While I do enjoy the corpse party series for what it''s worth this game has a LOT of uncomfortable scenes including minors (even moreso than the main series games) and one scene of a previous character being canonised as a pedophile, this is played for jokes. Stick to the horror based games I''d say unless you REALLY want to know every single aspect of this series and even then I''d recommend just watching a youtube video for the important parts.', 'Very Positive', 85.59, 19.83, 19.12);
INSERT INTO reviews VALUES (26936, 778610, 192, 'Really short and easy, I only needed a guide because I talked to the old woman first and she doesn''t say her hint twice (from my experience, I don''t know if that''s 100% right) but other wise it''s just a very relaxed hour an a half at most. \n\nThe only thing that I would like in this game is some sort of map... and more illustrations, the girls are FANTASTIC and there is just a single pic for each.', 'The idea for this game is really good but the gameplay is no fun at all. You move at snails pace through sheer endless mazes all the time. Just for some mid-quality hentai images. Nah thanks I''m good', 'Very Positive', 93.23, 1.78, 3.33);
INSERT INTO reviews VALUES (26959, 779090, 135, 'Played this after Miside and was impressed with story even tho it was short. Main menu was awesome too i honestly play it in the backround just to listen to it. Starting wire lips and eco hole next. Also love the umfend doll in miside.', 'can''t save the game, so many small bugs which force restart on the entire game (falling to the void), the guy you play as is a slow walker, ugly gf; no wonder why the game is listed as horror', 'Very Positive', 87.41, 7.62, 1.48);
INSERT INTO reviews VALUES (26963, 779130, 115, 'I wasn''t expecting much going into this game, but holy shit.  They have refined the VR fighter to a science.  I have never had more fun punching people in the face in VR than in this game.', 'Stars received: 3.7/10 _ Note: v.7  = IMHO\r\n\r\n Controls & Training & Help\r\n Menu & Settings\r\n Sound & Music\r\n Graphics\r\n Game Design\r\n Game Story\r\n Game Content\r\n Completion time (level/game)?\r\n is it Enjoyable & Fun?\r\n Could it hold a spot in Favorites? (& if the Game can be repeatedly played again)\r\n BONUS point: Multi-Player related\r\n BONUS point: Review for VR\r\n - if Registration is required with providing PII\r\n - is it acceptable to Play the Game in 2023+ ?\r\n - is it acceptable to Play the ', 'Mixed', 68.70, 0.85, 1.22);
INSERT INTO reviews VALUES (26974, 779330, 162, 'I KEEP GETTING RAIDED AND THESE F U C K I N G ORCS KEEP STEALING MY WOOD AND GOLD', 'Why TF is this in my Steam library? It''s awful!', 'Mixed', 64.81, 6.93, 2.53);
INSERT INTO reviews VALUES (26975, 779340, 16369, 'Folks, let me tell you, I am Sun Jian, the man who founded the Eastern Wu kingdom. And let me tell you, that Liu Bei guy, he''s no good. He''s weak, he''s spineless, and he doesn''t know how to make deals.\r\n\r\nI''ll tell you what, back when we were all part of the same group, the Red Cliffs Alliance, Liu Bei was always trying to take advantage of us. He''d say things like, "Oh, Sun Jian, we need to work together against Cao Cao." But then as soon as we''d win a battle, he''d turn around and side with Cao', 'Seems to crash a lot. Used to play on a lower spec laptop which ran it fine, now I''m playing on a better desktop though it seems to not want to work. Really annoying as it tends to happen a few turns in when I''m just getting used to it. Makes it unplayable so needs to be a thumbs down.', 'Very Positive', 84.43, 50.20, 68.18);
INSERT INTO reviews VALUES (26979, 779430, 158, 'Better gameplay than Topspin 2k25 by far!', 'It seems like recent updates to this game have ruined it in my opinion. Volleying seems impossible now with the AI hitting much faster and unrealistic shots as soon as you approach the net. Movement for both the player and the AI is extremely clunky. The game also seems to randomly decide whether or not your ball will be out. You can hit the most perfect shot and sometimes it''ll go in, but, seemingly at random, sometimes it''ll completely miss. If this game is on sale maybe buy it, but for the mo', 'Very Positive', 85.44, 38.85, 285.90);
INSERT INTO reviews VALUES (26986, 779590, 495, 'I suffered catastrophic radiation poisoning, got sucked into the vacuum of space, and asphyxiated before I even knew what I was doing. 9.5/10 my only complaint is that you can''t dive headfirst into the planet and have the hostile atmosphere tear your flimsy body to shreds or cook yourself with the spaceship''s thrusters.', 'Horror and Rougelite do not mix, you will just leave before anything scary happens. I bought it for the scares, refunded for the radiation timer. I do not know why the game has a timer, but it actively hurts the horror experience. And even when you extract with your loot, you''re greeted with a high score and some text detailing how your character lived out the rest of their life. It''s underwhelming all around.\n\nGo play Voices of the Void, it''s free, more confident in its design, scarier, and far', 'Very Positive', 91.31, 3.25, 1.82);
INSERT INTO reviews VALUES (27013, 780210, 1476, 'A simple game that has ruined my life and all productivity. Easy to play, hard to master. That, or I''m a moron.', 'There is no way to edit roads after they have been placed, other than undoing the most recent one. That is extremely frustrating when almost finished with something and realizing the first road I placed is the problem. I expected more at this price.', 'Very Positive', 88.28, 22.62, 0.72);
INSERT INTO reviews VALUES (27016, 780280, 106, 'Another must have game if you''re new or not too long in VR! Or if you simply like the mini games.\nAs for the achievements tho, they don''t count for me at all.', 'I have had my fun playing this game for what it is. There is, however, one major problem that must be addressed. The game is unplayable offline. I reached out to the developers about the problem, and they never wrote back... So I have to assume that it is a form of DRM... \n\nTherefore I can not recommend buying the game. I am an advocate against using DRM games. The main reason why obviously is because at some point the developers will no longer support the game.... Which means you will no longer', 'Very Positive', 84.91, 8.05, 5.92);
INSERT INTO reviews VALUES (27017, 780290, 9652, 'It''s like the board game Gloomhaven except it doesn''t take 65 hours to set up the board and you don''t have to calculate/debate enemy actions.', 'Gloomhaven itself is an amazing game (with some balance issues that are mostly addressed in Frosthaven). That is not what this negative review is about; my review to Cephalofair is "9.5/10, amazing game, be proud".\r\nThe Gloomhaven game which was released by Flaming Fowl Studios is a decent game; very good graphics for a game of this type, interfaces are a bit clunky, a few things needed tweaking, but overall a 7/10. This negative review is not for them although the game still needed polishing at', 'Very Positive', 82.98, 164.33, 184.20);
INSERT INTO reviews VALUES (27019, 780350, 158, 'At loading screen it freez in steam deck,\nThen ge proton 9-25 work.\nDon''t expect to work on steam deck out of box.\nChange compatibility to ge-proton9-25', 'Game is sadly crippled by the save system. There are extremely long sequences that you need to replay all the way through if you die along the way. A game being hard is fine, but a game being tedious is not fine. We played for a while but eventually bailed because of that.', 'Mostly Positive', 72.78, 1.77, 5.85);
INSERT INTO reviews VALUES (27024, 780500, 172, 'Suzy Cube is a funny platform game with some cutes designs and a cool ambiant. For his low price, I recommend it!!!', 'id call it "baby''s first platformer" but im worried that if this was a kid''s introduction to gaming theyd think all games are this dull and tedious', 'Very Positive', 85.47, 35.97, 6.87);
INSERT INTO reviews VALUES (27034, 780750, 131, '⠀', 'my man couldn''t even make a simple good snake game, so he added 4884 achievements.', 'Mixed', 65.65, 5.13, 6.72);
INSERT INTO reviews VALUES (27047, 781130, 146, 'The only game game I have found that lets me discover and edit specific genes, as well as evolve. 20/10', 'Very cute game, however it clearly has a long way to go before it''s fully playable.  I was unable to complete the tutorial because multiple times it would ask me to click on something and what I needed to click on wasn''t indicated clearly enough.  For instance, it asked me to apply a mutagen to a seed, but didn''t highlight or otherwise indicate the seed so I didn''t know what I was looking for.  Later it asked me to click a button to register a new species, but there was no such button anywhere o', 'Mixed', 68.49, 15.88, 0.70);
INSERT INTO reviews VALUES (27060, 781480, 422, 'Lunch Time ', 'the base gameplay loop is very dull, and the  fact that if you miss a single thing you''re stuck in a nothing playthrough  (with no hint thats happening other than radio silence from any of the plot-progressers) until the end is definitely a choice...', 'Mostly Positive', 78.20, 5.03, 8.48);
INSERT INTO reviews VALUES (27094, 782140, 124, 'The game is perfectible, but honestly, I had a blast.\n\nIt reminded me by spirit, games like sacrifice or populous, but at a little scale.\nPlaying the "Prophet" in a dystopic world, sending zealots to a certain death they are eager to go for you is ... particular.\nThe questions regarding religions are interesting.\nBut this game is not that long. i regret this point.\n', 'The game brings up a brilliant idea and the theme is great. But that''s all. Converting civils into soldiers may sound interesting. But the gameplay fails to create an immersion for the player. You would feel more satisfied if you would convert an hostile unit in -say-, Age of Empires, although conversion is the basis of this game. When you upgrade a female basic soldier, she turns into a male and such things are real immersion-killers. The game could be fun if it had multiplayer and a skirmish. ', 'Mixed', 63.71, 12.02, 0.48);
INSERT INTO reviews VALUES (27098, 782250, 1203, 'I''m really sad that the game had to end. The connections you build with the girls were really nice and I felt sad to let go once the game ended, even though I don''t feel like ever letting go. I''m really sad. But yeah, great game. Did I mention I''m sad?', 'I don’t want to hear about your penis, Eli.', 'Very Positive', 93.93, 22.13, 2.58);
INSERT INTO reviews VALUES (27102, 782330, 115662, 'my grandma (god rest her soul) was a very heavy catholic. i, on the other hand, am not. however, i loved my grandma very much, and if she saw me slaughtering demons she would be very proud of me.', 'Doom Eternal is a good game, probably my favorite FPS campaign ever. It''s fast, violent, has a variety of interesting weapons, and good movement mechanics.\r\n\r\nSo, why don''t I recommend it? Because id Software didn''t pay Mick Gordon for over half of the music used in game, took partial credit for some of his music, announced the OST well before signing a contract with Mick for said OST or even talking to him about it, and attempted to shift all of the blame to Mick. Marty Stratton acted like a ch', 'Very Positive', 91.26, 137.30, 56.93);
INSERT INTO reviews VALUES (27125, 783170, 288, 'My wife said if this review gets 100 likes and 50 awards, she will let me play all week without seeing the sun or touching the grass.', 'Dont bother with this game, another example of half arsed development, you get so far and then everything goes to shit or the game just stops working correctly as in the character doesnt move. Levelling up is a joke, inventory is a joke, combat is even worse, the enemies are all crack marksmen while your shots will miss 4/5 times. The art work and story setting etc are great, but this is where the positives end. It takes for ever to earn one XP point, you cannot upgrade weapons and armour, and f', 'Mixed', 56.25, 12.77, 25.97);
INSERT INTO reviews VALUES (27128, 783210, 155, 'Great 4X strategy game. The amount of complexity is just right. The hotkeys and QoL features are awesome. It plays really well.', 'this game sucks. it may have great potential but the game mechanics are disastrous. also commanding and selecting units cuases headaches. the economy is non-existent, the player becomes just an observer of random  and wilful production. there are no indicators how much of which resource you produce and why. and there are very few ways to affect it and if at all.', 'Mostly Positive', 77.42, 11.85, 32.00);
INSERT INTO reviews VALUES (27147, 783590, 188, 'Quiet Complex compared to earlier version.\r\nSometimes the battles won''t make any sense. The underlying factor supposedly would be the storyline overwriting the game plan. \r\nSo, just ''Ouchy'' everywhere...meant for the fighters...', 'Avoid this half baked game', 'Mixed', 65.43, 52.32, 4.80);
INSERT INTO reviews VALUES (27153, 783840, 362, 'game weird, game hard, so am i', 'Unique and a seriously demented title. Would be a big thumbs up, but the developer abandoned the game, leaving with a lot of bugs, non-working or half-baked features, and lacking in simple QOL features like skippable cutscenes. If the dev gave the game the final polish it needs, then I''d recommend the game to anyone who can stomach the ultra dark content.', 'Mostly Positive', 76.24, 7.70, 12.83);
INSERT INTO reviews VALUES (27163, 784080, 8739, 'this is the single greatest game in all of creation\r\n\r\nI have been experiencing a single, continuous orgasm since I first booted it up\r\n\r\nplease send help', 'The mod community made this game and for that its amazing. However limited Vanilla and the ongoing dlc practices thats decades regressive in design, showing how dedicated the publishers are to it is disgusting. \r\n\r\nIts incredibly hard to recommend with how much work each and every user has to put into it on their time to make it worth playing. From simply affording the dlc to seeing how fragmented the game is in even the most basic QOL features.', 'Very Positive', 84.98, 224.07, 29.62);
INSERT INTO reviews VALUES (27167, 784150, 7063, 'This game showed me exactly why planned economies in socialist countries failed.\n\nBecause there was an idiot like me doing the planning.\n\nPeople were waiting in a line in front of the grocery store because I couldnt manage my food supply chain \n\n10/10 for realism', 'The developers have made an absolutely enthralling game here; it''s challenging, deep, thoughtful, and has a unique point of view and historical setting.\n\nWhich is why it really pains me to have to return it, after trying my hardest to puzzle my way through -- my colorblindness is of the exact type that makes the shades of red and green used in the game _completely_ indistinguishable.', 'Very Positive', 90.56, 426.40, 3.30);
INSERT INTO reviews VALUES (27179, 785260, 1471, 'Sonic does not view Israel as a legitimate state', 'Not great.  Definitely not as memorable as Transformed and is a step back in many ways.  \n\nFortunately, it appears the devs agree as the latest, CrossWorlds, appears to be heavily inspired by Transformed.  Maybe wait for that one.  If you can''t, look up Transformed and play that one instead.', 'Mostly Positive', 70.84, 11.20, 4.78);
INSERT INTO reviews VALUES (27182, 785480, 349, '11 year old me is so happy because I finally won the game! It only took me 26 years and marrying a video game developer to conquer this dream', 'Crashes way too often', 'Very Positive', 86.53, 19.72, 5.63);
INSERT INTO reviews VALUES (27187, 785740, 1298, 'A cold, gray morality, harsher than any blizzard.', 'Could not be compared to This is the police. The plot becomes horrible at some point and there is a tactical mission that made me basically just fully follow someone playing a playthrough to complete, because its too hard and too specific.\nI thought I would love this game, and there are things that I love about it, but boy the negatives are huge.\n\nSpoilers: the game literally just kills off some characters for no reason. I dont know, I expected better.', 'Mixed', 64.02, 19.15, 44.73);
INSERT INTO reviews VALUES (27190, 785770, 394, 'The game has way too many bugs, and it sometimes seems like the developers don''t test the different missions before updating. Aside from that: Playing the game when it works is extremely fun. With support for steering wheels, it makes it extra enjoyable. Recommended, just a heads up on the bugs!', 'I can no longer in good faith recommend this game to anyone. I have played this game since it was first released to say it has been a buggy non-optimized mess has been an understatement. The last few patches have really sealed this games fate. I have run into more game breaking glitches and bugs in the last several updates that make the game unplayable and can no longer enjoy it. So today is the last day I will have played this game unsuccessfully. It has now been filed under retired and broken ', 'Mixed', 66.50, 57.33, 232.22);
INSERT INTO reviews VALUES (27192, 785790, 1935, 'WHAT THE GOLF? is a nice puzzle game with lots of funny levels, some nice graphics and a cool ambiant. I recommend it!!! 💚💚💚', 'If you don''t care about achievements, this game is awesome and you should buy it. But as an achievement enthusiast, this game is a pain in the ass. They have a habit of adding achievements years later, but then the achievements have issues. It''s already annoying enough to come back to finish the game again when the new achievements are added, but for those achievements to be unobtainable without ridiculous workarounds? I have to give this game a negative review out of principle.\n\nThe first time ', 'Very Positive', 92.76, 34.18, 19.18);
INSERT INTO reviews VALUES (27195, 785850, 117, 'The game is quite good, it''s just that when I play it, sometimes there are bugs in the missions that require me to restart the game or complete the practice mission first to continue the mission that has the bug in it, which I think is a bit annoying. Otherwise, I think this game is quite fun and worth playing.', 'Really tried to like this one... seriously. Explored a bit and grinded in the repetitive level... with the same design... again.. and the same encounters and decor... again. You''ll see.', 'Mixed', 53.85, 20.67, 6.00);
INSERT INTO reviews VALUES (27198, 785880, 155, 'i beat the game :D', 'Fun game with an interesting concept but I got too frustrated with two incredibly unfair aspects\r\n\r\n1 - Limited camera.  The camera won''t scroll until you''re very close to the edge of the screen but the enemies will still be there, out of sight but full able to blindside you.  It reminds me of those old SNES-era shovelware platformers that had the camera so far zoomed in that you couldn''t reasonably react to dangers when moving\r\n\r\n2 - Teleporting bosses, in some cases teleporting right into you,', 'Very Positive', 83.87, 0.75, 4.08);
INSERT INTO reviews VALUES (27199, 785890, 371, '~6 hours of great puzzles. If you''re buying this game that''s like 95% what you should care about. If I had to make 1 criticism it''s that the settings are mobile phone level, but like... It''s a puzzle game dude and the puzzles are good.', 'It''s aight; no real tutorial though--which isn''t a problem for game mechanics, but is for all the features and controls that are available to support you success. Compare with a game like Tametsi that has a list of tips and features explicitly on the main menu for you!', 'Overwhelmingly Positive', 95.69, 6.22, 0.73);
INSERT INTO reviews VALUES (27233, 786520, 229, 'This is perfect Simplisity', 'Espectacular interfaz. Es como estar en el juego. Lástima que quedó anticuada esta aplicación y el navegador integrado ya no soporta los sitios de ahora. Además, otras opciones como la del correo (en el caso de Gmail) ya no son compatibles porque cambiaron la seguridad y no se pueden usar más los datos para sincronizarlo. Lo decepcionante es el servicio de mensajería que usa sólo el de QQ, de Tencent (el que usan en China). El widget del clima tampoco funciona. Lo que te deja sólo la interfaz pa', 'Very Positive', 85.59, 458.35, 7.33);
INSERT INTO reviews VALUES (27236, 786580, 235, 'This game is different and at first seems very boring or like its not very complex or fun. But if you stick it out and keep playing it becomes very fun and it starts opening up into a very great game that is hard to walk away from. My only problem with it is that perk menu crash. It really sucks and makes leveling  up a bad thing for me.', 'Believe me, I tried so hard to like this game, but the game is painfully boring and unfulfilling. While the concept sounded promising—a farming game with creepy secrets and mysteries—the presentation is dreadful. I had high hopes and bought it merely because of its intriguing premise. However, this doesn''t mean that the developers can let everything else fall by the wayside.\n\nYes, the story of this game includes rape, sexual cheating, paedophilia, blackmail, various forms of violence, and suicid', 'Mixed', 69.36, 117.52, 9.33);
INSERT INTO reviews VALUES (27256, 787070, 452, '\r\nTwin stick shooter with simple yet reliable gameplay. It will not surprise you much but main focus is put on story and gameplay. Aside standard guns you have your special attack and ability to absorb various bullet types. Game resembles pretty much State of Anarchy with doodles and stuff. It have some redeeming qualities like unusual art style (feels like bootleg...) and music that is ok. Overall gameplay is working but you will not experience anything outstanding. Play for the story, otherwis', 'Super Ledgehop: Double Laser is yet another of literally hundreds of lazy amateur 2D retro top-down shooter/brawlers infesting Steam and lowering the average quality of all video games everywhere.  This one has a key difference, apart from the lower than average quality (and I must say the average quality of games on Steam, the 90,000+ indie shovelware games that nobody plays, is already quite low).  It''s got a rhythm/qte hybrid thing going on where you need to shoot in time with the really crap', 'Overwhelmingly Positive', 97.79, 8.17, 5.92);
INSERT INTO reviews VALUES (27271, 787480, 8589, 'The unskippable cutscene of Edgeworth and Phoenix making out in the courtroom was a bit unnecessary (feelings) but it''s a great game and i love it very much, kiss it on the forehead even.\r\n\r\nPutting this one in my law school résumé btw', 'Ah it hurts to give this a negative review. But ultimately the gameplay was just too frustrating to recommend it. The cast and the style and the concept are all fantastic. A stylized and action packed legal drama? Hell yeah! \r\n\r\nSo what''s the problem? I will tell you. The game just can''t live up to its own ambitious premise. You want to feel like a clever lawyer with your investigation and making the right choices. But ultimately this game is very linear. It railroads the player along a very nar', 'Overwhelmingly Positive', 97.80, 108.50, 14.02);
INSERT INTO reviews VALUES (27272, 787510, 121, 'The fact that I cant put the game into fullscreen without third party applictions and the UI being a downgrade to the original trilogy is a big deal breaker for me. However i still do recommend this game regardless because the games story more than makes up for it. this game delves into a lot of lore and expands our understanding of the muvluv universe. I personally enjoyed the overarching geopolitical focus of this instalment. The cast is great with a very emotional coming of age story which we', 'The actual gameplay is a disaster. Sure, the animation effects are quite good, but that doesn''t mean much when it''s moving around so fast you can''t tell what''s going on. The UI is somehow downgraded from Alternative, and the sound keeps cutting in and out. No matter how good the story may be, the sound issue alone destroys the immersion. I only tried it as long as I did because it''s Muv Luv, but no matter how much I love the series I can''t keep playing when the sound issues detract from the dram', 'Very Positive', 91.74, 40.53, 0.95);
INSERT INTO reviews VALUES (27283, 787740, 167, 'It''s an old game, but its very good. The graphics are actually pretty good in my opinion, controls are easy to learn, game progresses pretty well. Overall a great game to buy.', 'Wow i didnt set my bar to high but this is a joke and have asked for a refund.\nCamera controls are laughable at best you go to dig a hole and your camera ends up in a house with no way to move it.\nThe controls are very clunky same with the camera to move around\nAs i said buy if you will but will wait till they relese a new Constuction Sim that is for PC not a port', 'Mostly Positive', 73.65, 8.63, 0.60);
INSERT INTO reviews VALUES (27288, 787810, 1405, 'The game is 90% off right now and after playing the demo I bought it immediately.  Right now the reviews only say mostly positive which I don''t understand, so I read through the negative reviews.  Many of them said the game crashes but I never experienced that.  I think anyone that liked Link''s Awakening will immediately like this game.  I like being able to take portals to go directly back to dungeons to earn gems that allow me to upgrade the character more like a RPG than what zelda games allo', 'purchased specifically for use on steam deck. It worked great for a while than stopped being supported and can no longer play. disappointed because i was having fun with it', 'Very Positive', 80.43, 1.85, 12.83);
INSERT INTO reviews VALUES (27291, 787860, 23688, 'Joined friends game, bankrupted them with vehicles, used forklift to stack everything unusable. Would do again', 'I personally could not recommend this game, I was following the directions, doing everything you were meant to do, and following directions, but it wouldn''t work.\n\nI''d start the seeding process, turn everything on, and it wouldn''t plant/start, I''d try to start the tilling process, and it wouldn''t till, following the directions of the tutorial, but the second I followed the last step which was to hire someone, it would go back every time and work as it was meant to, so I thought it was just a wei', 'Very Positive', 93.69, 39.33, 1.88);
INSERT INTO reviews VALUES (27293, 787930, 133, 'Love this game it has so much potential & possibilitie the in depth hands on with the locomotives really bring the game to life . I truly hope the developer''s return and compleate what they have started . They really don''t know the jewl they have', 'This game has been abandoned by the developers in favor of their sequel platform. It is not under development, has no forthcoming updates or upgrades, and yet it is still here, for sale. AVOID THIS GAME AT ALL COSTS!', 'Mixed', 48.12, 29.58, 6.77);
INSERT INTO reviews VALUES (27305, 788100, 3237, 'Iv''e loved this title since it dropped. anyone complaining must not understand the point of the game is to actually have fun playing a game versus learning a broken system that actively hates the player.', 'The ways you can be killed on this game is unfair and ruins the experience for me. Arcade machines blow up on you when you buy them and you die, you activate your invincibility item to open a spiked chest and you die, you accidentally shoot a crystal door while breaking boxes... you guessed it, it turns spiked and there''s no way to get through without dying. If a game has to rely on cheap tactics to make a game more difficult, that is not a game I''m going to be interested in. So unfortunately, I', 'Very Positive', 86.65, 258.18, 3.77);
INSERT INTO reviews VALUES (27313, 788270, 462, 'I have finished the game like 20 times on mobile,cleared all quest,explored every inch of the game and i pretty much memorized everything.Time to beat it another 10 times on pc lol,cheers!\n\njokes aside this is a hidden gem,probably the best mobile rpg and a contender for top pc rpgs,i haven sunk over 500 hours in this game and i have no regrets at all,enjoyed every second\na tip for new players:dont stress over your build,just have fun and explore the posssibilites because if u ever have trouble ', 'as much as i like old style games like this and Eschalon. I find game needlessly difficult. Warrior gameplay can be ok with skills on cooldown, but mage that needs to run back to the inn and sleep every 3-4 spells because you cant regenerate mana, seems like a forced grind to drag out game. having both mana and health regenerate without needing to go back to town would go long way to make game fun.', 'Very Positive', 86.15, 2.92, 18.10);
INSERT INTO reviews VALUES (27329, 788630, 164, 'its like Starsector but you can play in one ship sandbox...\r\n\r\nStory is good and gameplay is good', 'This game has a disjointed story that''s difficult to make sense of.  It''s also difficult to know what to do next or where to go.  Maybe I''m just dumb, but it''s tedious and I lost interest pretty quickly.', 'Mostly Positive', 74.39, 37.92, 1.02);
INSERT INTO reviews VALUES (27332, 788690, 415, 'She Rhombus on my Ruin till I Psychonauts', 'Steam really needs to add a meh or middling option for their review system. Rhombus of Ruin is a sweet mini intetmission for the true sequel gme and it showcases a lot of the innovations and improvements of graphics for the first new Psychonauts game in over 12 years with smoother models, great animation oozing with personality, and beautiful environmental setpieces retaining the whimsical and odd style. The writing hasn''t skipped a beat either but the gameplay is a major downgrade. You''re extre', 'Very Positive', 86.51, 2.50, 2.62);
INSERT INTO reviews VALUES (27333, 788700, 119, 'Okayish everything; very, very so-so execution of every idea. I would say a mixed verdict of 6/10 and not truly a recommended game...', 'Hit a bug after 5 hours and cannot get past that. Too long for a refund. Do not buy.', 'Mixed', 67.23, 0.87, 5.25);
INSERT INTO reviews VALUES (27374, 789660, 773, 'Randomly addictive. When I''m too tired to think and just want some wanton, low-graphics destruction to give my brain some serotonin, this is the game I keep coming back to. I like to pretend this is how the bugs in Helldivers feel.', 'Straightforward auto-battler. Build up your swarm (which doesn''t fully listen to you)\n\nDefinitely not worth 20 bucks though; lacks visual and mechanical polish in many places. Upgrade tree is pretty boring. Feels a bit like a student game.\n\nWorth it if you see it for 5 or lower.', 'Very Positive', 87.06, 51.87, 5.00);
INSERT INTO reviews VALUES (27383, 789760, 355, 'Metro 2033 + japanese nonsense + metroidvania = Dead or School\nThe animations are cheap, characters looks like they''re made of cardboard but the gameplay works and it''s challenging enough to push you into grinding & training to get better gear and skill up yourself along with the protagonist.\nAnyway for the overall quality of the game and the lenght if you like metroidvania and anime this will be a good purchase.', 'It''s fun, but its controller support is bad. At the start, your RT and LT buttons do nothing despite being designated in the menu. You have to re-designate them, and then they suddenly work. But that''s fine, the big issue is LT and RT cannot work at the same time, no matter the methods and schemes tried. The game''s skill tree depends on using LT for aiming or activating and RT to use. Half the game''s fun is closed off to you because controller support is poorly optimized.\n\nI''m sure it''s fine on ', 'Very Positive', 86.76, 25.70, 0.83);
INSERT INTO reviews VALUES (27399, 790060, 1104, 'The next time you see this review, the content of this game may have doubled in size.', 'Unfortunately not challenging enough, even on the hardest difficulty. Ships in general feel really boring to control. I like the panic attack mechanic and all of the bonuses for breaking things, but the upgrades you get for doing so feel inane and often useless. The main attack of each ship gives no variety, the only interesting thing is the charge shot which is saying something. The writing is also not a strong point, lots of very annoying characters.\nOnly grab if you''re the kind of person who ', 'Overwhelmingly Positive', 99.37, 55.33, 12.90);
INSERT INTO reviews VALUES (27416, 790410, 202, 'Best game ever George droyd and adolf rizzler played it too cant wait for part 2', 'You can 100% this game and refund it without even knowing what to do. Game is way too short and the scenes aren''t worth it. Spend your money elsewhere.', 'Mixed', 56.93, 0.10, 2.10);
INSERT INTO reviews VALUES (27419, 790540, 257, 'The game turned out better than I expected after all the reviews so far. Yes, the fighting mechanics weren’t very smooth, but the idea behind the project is very original. The studio had tight deadlines and a limited budget, so they did the best they could. I''m not a very judgmental person, and I always try to evaluate all aspects. So yeah, I enjoyed the game no matter what!', 'well you could say this game left me speechless ahahah\r\nbtw i hated every second of it, you should buy it', 'Mostly Negative', 32.68, 2.97, 4.02);
INSERT INTO reviews VALUES (27428, 790740, 3317, 'cool game. do not play it with an autistic person. they will cry. very good game though.', 'Game claims that I wasted my time playing it and afterwards in the credits doesnt thank me for playing. Additionally it took a friend and me less than 90 minutes to play through (struggled at one point a bit) and even though I bought the game in sale (50%) I dont think that it was worth the time. \nThere were some cool ideas and the artstyle is very neat. It just feels like there are like 90% of the game missing and this is just a demo(for 5 Euros(10€, if you actually want to play it, as you need', 'Very Positive', 90.80, 2.57, 1.95);
INSERT INTO reviews VALUES (27434, 790820, 2444, 'SEGA ill suck you off for a valkyria 5 i swear im good for it \n\nthis game rocked btw can you also make pc and console remakes for 2 and 3 \nthis is honestly one of the best and unique ip''s you have just go for itttttttttttttt mannnnnnnnnnnnnn', 'This is not a tactics-based game. This is a LINEAR PUZZLE GAME disguised as a tactics game.\n\nHalf of the optimal strategies for maps involve dashing from spawn to the victory flag. The score system is centered around ''speedrunning,'' in which ideal scores involve plays that finish up a level in the fewest turns possible. Enemy AI is likewise predictable.\n\nYou''re not devising a dynamic, adapted response in combat scenarios. You''re trying to emulate the speediest plays that have been predetermined ', 'Very Positive', 88.95, 64.85, 47.08);
INSERT INTO reviews VALUES (27436, 790850, 580, 'A fun game for players who like to summon hordes of minions to fight at their side.  Minions from giants to chickens - Yes!  Chickens!  Imagine filling up your maximum number of minions with only undead chickens and taking over a village.  Very entertaining - lol  Plus, you have your own spells to choose from as you continue thru the game, so you are not left completely defenseless.  The graphics could have been better, but while playing, they seem to fit this type of game.  Now, what are you wa', 'I DONT WANT TO KILL 10101010101010101010100101 HOUSES LLA THE TDAU MNNO NO NO NONONONONONOONNOONONONONONONONONONOONONONNOONONNONONOO O I DONT LIKE LIKE HOUSE NONONNONNONOO ALL I DO IS KILL DUMB HOUSE FOR 1000 GOUR', 'Very Positive', 86.90, 15.02, 0.13);
INSERT INTO reviews VALUES (27451, 791180, 169, 'Clever game. Love the concept and the execution. Really awesome pixel graphics and just fun to play. It''s short if you play it through just the one way but each character not only has a normal and hard mode, they each have their own unique spin on the level. As well you can play to beat your time forever if you want. Highly recommend, especially at this price. Looking forward to seeing more from this developer.', 'Interesting concept, lack luster execution. The games animations and effects (such as the ripples when you fall into lava) are nice little touches, but in a game where the pixels matter the slipperiness of each character results in a frustrating experience. If I where picking any word  to describe this game and its game play I would have to say it is mid.', 'Very Positive', 86.98, 4.60, 0.40);
INSERT INTO reviews VALUES (27459, 791330, 315, 'making positive reviews for hentai games recommends them to your friends which ruins their steam store page with hentai games.\n', 'im currently having issues with the game none of the H-scenes are being shown at all iv gone to the recollection thing and it just shows a black screen and a text appears saying who ever spent some time with any of the characters for that scene how do i fix this', 'Very Positive', 87.62, 30.32, 1.08);
INSERT INTO reviews VALUES (27478, 791770, 129, 'Theres a huge muscular man in my bedroom staring at me like hes about to fuck me', 'scary af', 'Very Positive', 91.47, 9.02, 6.88);
INSERT INTO reviews VALUES (27488, 792040, 270, 'Fun, though occasionally obtuse puzzles. Liked the characters and narrative though.\n\nMy only confusion is... why is the game so big (2.5 GB) on disk? There is no voice acting or video... It could easily be 50 MB.\n\nAnyway... still enjoyed it.', 'It''s got a great atmosphere and a decent enough story but at the end of the day, the puzzles were just not fun.  They were either too easy or set up in a way that my brain just outright rejected trying to solve it.  The most frustrating thing for me though was examining an object and then needing to click on it again to find out that now you can interact with it.  That lack of feedback left me cold far more often than I liked.\n\nAnd really, for a detective game, I didn''t really feel like I had mu', 'Very Positive', 92.22, 5.58, 17.00);
INSERT INTO reviews VALUES (27492, 792100, 769, 'Well, this game is great. I''ve been a software developer for more than 20 years, and it was really challenging for me to beat it, especially with all the additional speed and size challenges.\n\nOn the downside, the UI could definitely be better. There are no breakpoints, no keyboard controls, broken step-by-step execution, and no ability to copy/paste specific code fragments. These aren''t critical issues, but improvements here would greatly enhance the experience.\n\nI definitely recommend this gam', 'I almost really like this game, but programming with Goto statements? Someone needs to be slapped.', 'Very Positive', 93.37, 167.37, 0.08);
INSERT INTO reviews VALUES (27493, 792120, 1103, 'Pirated this game at first, saw how much of a gem it was and bought the game as soon as I could.\nThis game is super underrated and deserves a lot more attention.', 'I don''t understand why this game has such good reviews when it has such glaring issues. First off, the save system is extremely archaic and it kills the flow of gameplay instantly. The fact that you have to manually walk back to the start of the game each time you want to save is just bad game design. You might the just say,"then don''t save that often", but the enemy encounters are so frequent that you will waste all your potions and be forced to anyways to regenerate your health. On top of the ', 'Very Positive', 92.38, 16.60, 0.97);
INSERT INTO reviews VALUES (27500, 792300, 2225, 'What an Awesome game,\ni find the beast inside one of those story games that i can''t forget i had an incredible time playing it.\nthe storytelling is Amazing the idea of connecting the past and the present is truly impressive and well done, The ending actually shocked me, the voice acting is great, and the cutscenes are decent, though some of the cutscenes were unintentionally funny for me not gonna lie. but it’s an indie game, so I’m not complaining.\n\nand oh man, the world building is just phenom', 'Dude spends matches to light candles, but can''t take at least one candle with him', 'Mostly Positive', 77.17, 13.58, 0.50);
INSERT INTO reviews VALUES (27514, 792660, 122, 'an excellent game, still stands as a solid, thoughtful game', 'Terrrible buggy mess.', 'Mostly Positive', 76.23, 519.08, 4.72);
INSERT INTO reviews VALUES (27517, 792710, 627, 'mmmm yes platformer with level editor mmmmm yes happy', 'An underrated gem! I was a bit conflicted whether I would like it, but I’m glad I was proven wrong. The controls are tight, and the course elements are detailed and have depth in their customization. The only real critiques I have is that it slightly lags when you die and return to a checkpoint, and that there are only 4 level themes to choose from.\n\nEdit: After uploading my level and not getting a single play after 4 days, I''ve began pondering on something that may be a flaw in the core of this', 'Overwhelmingly Positive', 96.81, 3.93, 18.12);
INSERT INTO reviews VALUES (27535, 792990, 286, 'Attention devs, just a query, the gun range update hasnt been added in yet for a couple of years, if you could give me a time frame for that release that would be swell.', 'there is no game, i cant believe steam still has this up for sale.', 'Very Negative', 16.08, 6.27, 0.35);
INSERT INTO reviews VALUES (27556, 793350, 910, 'There''s a certain intrinsic beauty in the chaotic - a method to all forms of madness\r\nOne might not be able to intellectualize exactly what they''re doing at a given moment in SWARMLAKE, an endless score-chaser first-person-shooter/platformer hybrid that tasks one with jumping deftly in and around massive swarms of enemies - some clusters of spheres that follow you around, others incomprehensibly tall walls of pointed death - collecting satisfyingly-explosive orbs to stave off the horde for as lo', 'good particles and effects\nbut kinda boring and monotonous', 'Very Positive', 93.30, 21.45, 0.70);
INSERT INTO reviews VALUES (27557, 793370, 745, 'I like KIDS', 'A surrealist game I did not feel was effective. especially not at getting any kind of message across. I liked the minimalistic visuals, but that was about it. It was okay at best.', 'Very Positive', 83.49, 2.57, 0.52);
INSERT INTO reviews VALUES (27562, 793460, 2011, 'Fun little game for a few hours. You get to decide, how to act in certain situations and get through them a bit differently each time. However, it does get repetitive after a while - the phone calls aren''t new, so when you pick all of the options, you essentialy play it over and over again. There are different maps, but still - I would like to hear new voices, maybe by using AI. \n\nGood entertainment for like 2-3 days.', 'I can speak English very well but this game deserves Turkish language support. If that day ever comes, I''ll update the comment as "recommended". Other than that, it''s a good game.', 'Very Positive', 89.91, 14.35, 8.72);
INSERT INTO reviews VALUES (27574, 793690, 307, 'This game is soooo addictive! I love it! Just good fast paced fun! Highly recommend.', 'Just a heads up to any future buyers. The server that the devs used for multiplayer is no longer running. Therefore if you''re looking to play random matches or even with friends, you will be unable to. Due to this game being heavily pushed for multiplayer I can''t recommend it. Otherwise the game was great when multiplayer was live.', 'Very Positive', 91.21, 61.83, 6.58);
INSERT INTO reviews VALUES (27593, 794260, 14453, 'I''ve had a love hate relationship with this game. \n\nI walked into it expected a modern RPG and got my ass handed to me, lost all my gear, lost the starter house got tilted and uninstalled and didn''t touch for years.\n\nEventually i came back with a lot more patience and understanding for what the game was going to throw at me. Accept my loses, adequately preparing for adventures and even making sure I have backup equipment back at home in case i lose everything out in the field. With a lot of prep', 'I considered this game a "hateplay" like i would consider watching a movie i bought but hated within the first hour. I definitely got hooked not because I enjoyed it but because I wanted to justify the money i paid for it after i hit the 2 hour mark on steams return policy. I did not to want to feel like my money was wasted so I went all in to get as much done in this game. As you can tell from my achievements in game, I have done one playthrough and finished the main campaign of the dlc (beatin', 'Mostly Positive', 73.46, 137.43, 154.12);
INSERT INTO reviews VALUES (27599, 794490, 384, 'A BIG THANK YOU TO DEVELOPER\nI want to say thank you to DEVELOPER ADRIAND. I hand a problem on my end and Adriand helped and stayed with me for 3 day''s until he figured it out. I''m talking up to 4 AM in the morning. The thing is is it wasn''t the game it was on my PC and he still stayed with me until he fixed it.Again A Big thank you to Developer Adriand', 'Game abandoned and unfinished.', 'Mixed', 57.81, 19.42, 10.32);
INSERT INTO reviews VALUES (27601, 794540, 857, 'https://steamcommunity.com/sharedfiles/filedetails/?id=2619094574\nhttps://steamcommunity.com/sharedfiles/filedetails/?id=2618410668\nhttps://steamcommunity.com/sharedfiles/filedetails/?id=2619094552', 'Game teases you with inaccessible dialogue options irrespective of your prior choices.\n\na: Say something reasonable\nb: Lay a massive fart\nc: Say something friendly\n\n(Unfortunately you have lost control of your anus and the farts are on their way. To progress the game please choose option b.)', 'Very Positive', 83.08, 4.05, 0.75);
INSERT INTO reviews VALUES (27602, 794550, 105, 'There are a lot of grappling hook based platformers, but this is the first one I''ve seen where the hook is truly multi-purpose.  You use it for movement AND combat AND puzzle-solving, since it interacts with enemies and objects as well as the environment.  It''s a great game!', 'i assume this game is fun but my controller doesen''t work', 'Very Positive', 94.29, 6.32, 1.37);
INSERT INTO reviews VALUES (27604, 794580, 245, 'Simplified gameplay is literally in the description, but people still buy the game then proceed to complain about it. Go figure.\nThen you have the usual freaks complaining about fanservice. Sad!', 'This game does not have actual native xbox controller support. Don''t be fooled by the Full Controller Support section. It''s lying. LT/RT/LB/RB are not set up and the game has not option to change controls..... IN A FIGHTING GAME -_-', 'Mostly Positive', 72.24, 11.47, 0.13);
INSERT INTO reviews VALUES (27614, 794800, 1966, 'Very good game, too bad I don''t have opponents, they are very easy. Mostly one called Xannel.', 'The game is really fun, but when playing with friends on the same screen, the screen keeps freezing…the app works great, but the freezing screen ruins the whole game..you can’t see what’s happening in the game:(( hope this bug get’s fixed.', 'Very Positive', 87.84, 63.77, 12.53);
INSERT INTO reviews VALUES (27619, 794860, 447, 'eSail + eSail Pro: ~$47\nBoat insurance deductable: $3500\n\nThe choice is yours.', 'You have to provide and confirm your email to play this online.', 'Very Positive', 94.63, 80.68, 7.97);
INSERT INTO reviews VALUES (27623, 794960, 104, 'One of the better first person puzzle games that I played.\n\nWhat strikes me most about this game is that all the levels are small. There are only a few puzzle elements per level. Yet, most of the levels succeed in being challenging. Some of the levels are real head-scratchers.\n\nEverything about this game feels good. The game has the right level of difficulty. The environments look nice. The effects and the changing environment in between the puzzles make the trip worthwhile. The sojourn tries to', 'The K-mart Talos Principle', 'Mixed', 68.27, 16.20, 15.02);
INSERT INTO reviews VALUES (27634, 795420, 797, 'I always expected The Darkside Detective to be funny, but this sequel still surprised me with its spooky antics and laugh-out-loud moments.', 'Pretty disappointing versus the first game. I needed a walkthrough with the first 3 case files whereas the first game I didn''t need any and it''s all due to very moon logic item use. The puzzles were great. The humor was still on point. But point and clicks are made and broken by their logic.', 'Overwhelmingly Positive', 95.86, 11.57, 2.93);
INSERT INTO reviews VALUES (27691, 796860, 278, 'They need to work on this again.', 'this game sucks it KEEPS CRASHING OVER AND OVER AGAIN DON''T BUY THIS GAME SAVE YOUR MONEY!', 'Mostly Negative', 32.01, 4.43, 0.95);
INSERT INTO reviews VALUES (27695, 796940, 100, 'Playtime for all routes and achievements is around 4 hours. I really enjoyed the stories, the (good and bad) endings and interestingly, the sound effects. There is no voice acting but the sound effects and the music create a lovely atmosphere. The art is lovely and the different routes are quite different. Due to the short playtime I would recommend getting it on sale.', 'I couldn''t get into it. The choices were nice, but the writing style wasn''t for me. I didn''t feel any immersion, and the flow of the story seemed pushed towards endgame too fast.\n\nIt felt... amateurish. Granted, I''ve also been playing Vampire the Masquerade and it''s sibling games for better part of 20 years, so I guess this felt too cut and dry for me.\n\n---\n\nCurator - Toby''s Gaming Nook', 'Very Positive', 90.00, 4.17, 1.30);
INSERT INTO reviews VALUES (27732, 798290, 311, 'My wife said if this review gets 10 likes and 5 awards, she will buy a case of beer, guys help me out.', 'Handling is good, graphics and sound are bad (even with HDR disabled in ini file).', 'Mostly Positive', 77.81, 15.23, 1.68);
INSERT INTO reviews VALUES (27737, 798460, 2201, 'Please note that I played this game to about 98 percent completion on the switch, but got it on steam to play again. \n\nNi No Kuni Wrath of the White Witch is an absolutely fantastic game about love, loss, and friendship. It''s such a comfort game for me. From the animated cutscenes by Studio Ghibli to the cute, wacky characters- it''s just so fantastic and comforting. From the gameplay perspective, it''s great. The combat system is unique and very, very fun. The boss battles are all different. The ', 'In all honesty, you are much better off watching a full playthrough which allows you to skip the grinding this game has, instead of playing it yourself. This game offers maybe max. 10 hours of unique content, and the rest is filled with grinding or fetch quest. The gameplay has no real strategic depths as you will have a very limited selection of monster since leveling up those is already so much grind that you wont dare take any other monsters with you. \r\nThe world, music, story, characters are', 'Very Positive', 84.60, 8.77, 41.22);
INSERT INTO reviews VALUES (27740, 798490, 2299, 'Othercide is a roguelite turn-based strategy game developed by Lightbulb Crew, where players create and manage "daughters," units that engage in combat to fend off the twisted, otherworldly enemies threatening the world. The game’s standout features include its timeline-based combat mechanics and the ability to customize said daughters. Set in a black/white gothic Victorian-inspired world, the game offers a visually striking experience, with beautiful art, fluid animations, and a compelling soun', 'If you''re checking this game out, it''s because of the super-stylized visuals. In that respect, the game nails it. Fantastic visual style, environments and music. It''s really unique and does it very well.\r\n\r\nGameplay-wise, though, the game gets super tedious. My biggest gripe is there are only 3 classes, each with ~3-6 skills (depending on your level) and the skills honestly don''t really differentiate or even synergize. Lots of them break down to "do a lot of damage in 1 hit" vs "do smaller damag', 'Very Positive', 83.95, 47.68, 12.65);
INSERT INTO reviews VALUES (27741, 798510, 700, 'As a Dragon Ball fan very cool and fun game, just a shame there''s no achivements', 'Honestly, the Japanese locale files are still in the game, and they''ve left Japanese as an option during the terms'' agreement at the start of the game. It''s totally nonsensical to have deliberately removed the Japanese text option from the in-game menu!\n\nIs this some particular kind of mockery I am not aware of?\nWhat reason/gain is there, to make the original Japanese text unavailable?!\n\nHaving played the previous titles in their Japanese versions, the current game is complete gibberish to me...', 'Very Positive', 83.71, 10.75, 0.30);
INSERT INTO reviews VALUES (27753, 798810, 484, 'controller motion still works as of aug 7th 2024, that reason being why i got it, being able to swing your arms at your sides to run in Skyrim VR is awesome, and adds a good layer of immersion and beats spending $1000 on a treadmill for VR, hopefully future updates don''t break the controller motion tracking! app is abandoned by creator / hasn''t received updates in a long time.', 'The tracker I am using (Slime & Pico) is not supported. Please consider updating the software to support various types of trackers.', 'Very Positive', 83.47, 20.35, 0.75);
INSERT INTO reviews VALUES (27755, 798840, 192, 'better than world of tanks gyat damn', 'Game is so bad. The enemy AI is so overpowered and will kill you in one hit with MUCH weaker tanks. You will never one shot an enemy AI in this game unless your tank is at least 10 tiers above the enemies tank. The enemy don''t miss, having pin point perfect accuracy, and track you through walls so get used to dying the second you come around a wall cause they were aiming at you the entire time. Your shots will bounce off enemy tanks CONSTANTLY and the game doesn''t give you any information on wha', 'Very Positive', 85.42, 4.60, 8.32);
INSERT INTO reviews VALUES (27761, 799070, 841, 'Lets be honest we all here for the Red Clouds background xd', 'no sex', 'Very Positive', 94.17, 9.10, 4.90);
INSERT INTO reviews VALUES (27778, 799510, 260, 'Just a really cute little platformer. The whole inking gimmick is neat and it leads to some cool puzzle bits later on and an actual pretty sick boss battle (both in the same library level actually) and there is the obvious adorable charm present throughout the entire thing. There''s not much more I could say about it but I don''t think the game set out to be much more than a solid gameboy era platformer and what it does it does well especially at the price. Also I played this to break up my Dusk p', 'The game is beautiful and cute af.\nBUT I will rate this as negative. Because it has a few flaws that are way too big.\n-> No saving (what were the devs thinking)\n-> You cant change the resolution, how to play this game in my monitor ?? It''s nauseating, needs windowed mode.\n-> The camera shouldn''t follow pixel for pixel the hero. Even more nauseating combined with the previous flaw.\n\nIf these 3 things were fixed, I would change my review.', 'Overwhelmingly Positive', 95.00, 0.48, 0.33);
INSERT INTO reviews VALUES (27784, 799600, 6690, 'My friends built fighter jets, missile carriers, battleships.\r\n\r\nI built ships of industry, mining, and refining. For I know that the most dangerous thing of all- Is capitalism.', 'I want to like this game. I played the original free-to-play version of this game and loved it, and I can appreciate how much hard work has clearly gone into improving it, especially in regards to campaign. I mean, really, what a glow-up.\n\nHowever... this game is wrong. It feels wrong. It embodies everything I hate in a game like this. The game has been made in such a way to encourage certain design principles--that--if you want to play optimally--you cannot stray from. This is incredibly frustr', 'Overwhelmingly Positive', 95.11, 17.93, 19.35);
INSERT INTO reviews VALUES (27787, 799640, 889, 'Has the boss gameplay of Terrarias Calamity mod, has combat of Starbound, has literal SCP based creatures in it, and the humor is of really good memes. What more is there to love!', 'The game is poorly built with enemies that are too difficult for the power that you are given. In the final fight, there is a bug where if you have failed the first time, the damage is already done when restarting, leading to an infinite loop of failure. This isn''t a "git gud" issue, this is a literal bug where you can not physically move your character to an area fast enough to defend it.', 'Very Positive', 94.38, 12.63, 9.67);
INSERT INTO reviews VALUES (27811, 800270, 3217, 'Outstanding adaptation. Takes away a lot of the pain from the tabletop version, especially my clumsy fingers knocking over all my little cubes. Basically all card options and mechanics work correctly, expansions slot in and out seamlessly, and your scores and options are calculated for you in ways that assist play.\n\nMy single major gripe is that I''m always being torn away from looking at my cards whenever another player performs an action, which immediately closes whatever view you have open and', 'The board game is amazing. But the developers for the digital game constantly break the game with horrific bugs. They introduce a new DLC expansion, but apparently never test it once to see that they have broken half the cards in the game. All of a sudden discount cards no longer provide discounts, the UI just randomly disappears, alerts and messages pop up multiple times. It really is a joke.', 'Mostly Positive', 70.69, 73.90, 1918.15);
INSERT INTO reviews VALUES (27827, 800600, 301, 'I enjoyed the game and am already on book three! This is concerning given that I started playing only four days ago. I am already thinking about what to do in another playthrough, and ahhhh yes, a big can of brainworms has been opened with this one. Anyways, I warmly recommend this game.', 'I felt like I was playing Charlie''s Angels meets Twilight, with a feeble attempt at a detective story. Because while you play as a detective, all the clues are revealed right away and you then have the option to either meta-game it and have your character figure everything out easily or play the fool and make the wrong choices willingly. The "professional" stats are there as an afterthought, not really changing how you go about guessing clues and how you fight. You have 4 teammates in Charlie''s ', 'Very Positive', 94.02, 19.38, 10.18);
INSERT INTO reviews VALUES (27828, 800620, 356, 'This game is so good, by far being the best series made for hosted games. The depth of the characters, the customization options, the way it handles gender identity and depression, all while being set into a cool alt history super hero cyberpunk setting make it one of my favourite works of fiction out there. \n\nThe story is told in first person and the players past is pretty established. The player decides how the protagonist reacts to develops and what motivates a former telepathic super hero to', 'Would not recommend. The prose doesn''t have good flow and why you should care at all about the story isn''t established well: the MC''s motivation isn''t adequately explained.', 'Overwhelmingly Positive', 96.35, 5.33, 1.95);
INSERT INTO reviews VALUES (27857, 801290, 145, 'It''s quite nice to play games like Diabolic, because they are quite simple and bring positive emotions, which should be characteristic of great games. A pleasant soundtrack creates a special atmosphere. I advise everyone.', 'Unbalanced, cheap enemy spawns, endless grindfest after level 7, boring.', 'Very Positive', 84.83, 2.68, 1.93);
INSERT INTO reviews VALUES (27867, 801480, 1702, 'This point-and-click puzzle game was an enjoyable experience from start to finish. The graphics were visually appealing, and although the spy-themed story was somewhat predictable, it still kept me entertained throughout. The controls were intuitive and easy to grasp.\n\nThe puzzles were cleverly designed, offering a satisfying balance between logic and challenge. While some puzzles could be tricky if you didn’t pay close attention, they always felt fair and rewarding to solve with a bit of patien', 'I can''t in good concision recommend the game, part of that was probably my own expectations fault. I bought the game thinking it was a puzzle game (partially because of the tag line, which does seem a bit deceptive). In reality the game is a kind of hidden object game, there are no "puzzles" for you to actively solve, it''s all just finding keys/codes and then inputting them in the appropriate designated spot. And you spend a LOT of time going back and forth between scenes, like 90% of game time ', 'Overwhelmingly Positive', 95.06, 7.17, 3.85);
INSERT INTO reviews VALUES (27870, 801550, 1485, 'Great game but what is the point of making the game free if you are going to make people pay to play the actual game', 'Everything is fine with the game itself, it plays nicely, the movements are pleasant. But. The game is full of kids, and the last straw was when I met a bunch of kids who emulate controls using a mouse or gamepad. The hands were locked at the wrist, the same for 3 players, and these players played the best of all.\nI wanted to send a report, but there are NO REPORTS in this game', 'Very Positive', 80.00, 4.67, 5.75);
INSERT INTO reviews VALUES (27873, 801630, 2093, 'she under on my night until i in-birth and later', 'Outdated version of UNI, but still plenty fun if you don''t have the extra few bucks for the new one.\nEdit: Nm, guess it''s not available for steam deck anymore, zero reason to lock it away to windows lol', 'Very Positive', 94.65, 8.17, 4.22);
INSERT INTO reviews VALUES (27880, 801800, 1651, 'Finally, a game set in the fictional land of England. They made S.T.A.L.K.E.R. scarier by adding more British people.\n', 'A single player game that requires an internet connection to play, which isn''t listed in the store page.', 'Mostly Positive', 78.68, 1.20, 10.13);
INSERT INTO reviews VALUES (27923, 802730, 190, 'I''m getting an abortion', 'i just cant bring myself to love you... sorry my little thing', 'Very Positive', 85.79, 0.95, 0.35);
INSERT INTO reviews VALUES (27927, 802870, 331, 'It''s not long enough.', 'Somehow it''s a pretty bad game. Despite enjoying many similar games, the writing feels lazy, the characters are somehow unattractive, and it constantly throws in your face that characters want to have sex. This is also done in a really bland offputting way, I''ve gone back to the game a couple times to see if anything changed but it''s probably the worst fanservice VN I''ve ever read still. You might enjoy it if you want characters constantly talking about sex, really sexualized distasteful charact', 'Overwhelmingly Positive', 95.47, 18089.65, 2.32);
INSERT INTO reviews VALUES (27928, 802880, 572, 'This is like the "Better Call Saul" of visual novels. It starts off on a really odd note and just makes no sense and seems a bit mundane. In time though it pays off and things start coming together and the story gets more interesting. Highly recommended!', 'Archetypal Idiot protagonist whose personality is that of a generic anime loser.\n\nNeed I say more? Because I really do not understand why this low effort archetype is even tolerable to anyone, and I am quite disgruntled at the user who convinced me to give this a shot under the impression "it gets better" since it does not in any way that matters.\n\nIf the main character is bad, that colors the impression of the rest of the story in a way that can not be recovered from.', 'Very Positive', 92.13, 11.95, 10.50);
INSERT INTO reviews VALUES (27929, 802890, 856, 'Better than Black Myth: Wukong', 'Whiny indecisive MC. I thought there''s no one as bad as Shinji from Evangelion. This guy tops it. Shinji didnt have the same luxury to loop like MC, and also younger. That alone gives him the benefit of the doubt when being compared. You think MC would''ve gotten better, as time passes? A bit less melodramatic maybe, but ultimately the same. Cant say how many times ive skipped his monologues cause it''s unbearable. How tf anyone can put up with MC''s attitude haha.\n\nPersonally i came for the closur', 'Very Positive', 94.98, 32.25, 46.87);
INSERT INTO reviews VALUES (27934, 803050, 2387, 'Do you have ADHD but are not autistic enough for Factorio/Satisfactory?\nHere you go!\n\nLet''s terraform Venus next', 'I want very badly to like this game. It''s a fascinating terraforming journey, with challenging logistical issues, long-term planning, complex interplay of mechanics, and the pleasure of watching Mars turn from a frozen airless wasteland into a verdant world. It''s also a coming-of-age story of a cybernetic intelligence doing the best she can, despite her mission and existence becoming political almost as soon as she booted up.\n\nUnfortunately, these experiences are ruined by a pair of game-breakin', 'Mostly Positive', 77.08, 100.78, 195.25);
INSERT INTO reviews VALUES (27947, 803330, 6249, 'Destroy all humans is as beautiful as the day I first played it. It''s a love letter to campy sci fi movies of the 50''s and 60''s. Besides that there''s just something cathartic about the level of destruction you go on. It''s not particularly deep but it doesn''t really need to be. This fuels that niche that ''Rampage'' games used to fuel.', 'Great idea ruined by absolutely the worst difficulty balancing since the C64. Missions and exploring are ruined by about a million soldiers spawning and absolutely never losing sight of you, even from across the map. By the time you''ve done two missions you''ll find that all you can do is walk around refreshing the Holoblob, as literally anything else breaks your disguise - followed by about a million soldiers spawning etc etc.\r\nDon''t bother, spend your money on something else.', 'Very Positive', 93.95, 9.08, 31.98);
INSERT INTO reviews VALUES (27954, 803600, 1616, 'I dunno, I''m only 271 hours in; it might be too early to make a decision on this.', 'It pains me so much to give this game a negative review because the game deserves nothing but praise. It''s my first Disgaea and I''ve never had so much fun with a tactical RPG before, as hectic as this game is.\r\n\r\nHowever, the game freezes at random after Windows updated to ver. 24H2 and I get it, it''s not NIS'' fault but I believe they might notice negative reviews on Steam before Microsoft does anything and I know this is nothing but wishful thinking. Well, neither companies will do anything at ', 'Very Positive', 89.60, 314.35, 115.82);
INSERT INTO reviews VALUES (27961, 803830, 223, 'I just picked this game up in Feb 2025, searching for games that feel better and might be more difficult, but more satisfying in the end. Think Skate 3 vs. Tony Hawks Pro Skater, This is more of a Skate 3 game. Im definitey satisfied with it, and love playing it for a change of pace, but right now Shredders definitely keeps my attention and is my go to snowboarding game. Steep and the other Ubisoft Extreme sports game are alright, but i know its unrealistic like Tony Hawks Pro Skater, where you ', 'Seems like this game stopped working completely', 'Very Positive', 81.61, 46.65, 2.92);
INSERT INTO reviews VALUES (27970, 803980, 848, 'Played for 8.6 hours so far and i must say the game is really detailed and player friendly, though unscrewing all the parts tends to get annoying after awhile (Edit while i did get bored after awhile it was fun for a little bit', 'So much potential. Unfortunately the devs abandoned the game years ago before the game was ever finished.', 'Mixed', 54.01, 8.62, 1.50);
INSERT INTO reviews VALUES (27972, 804010, 1028, 'Not the most creative or deep deckbuilder out there but still a fun, heartfelt (and quite silly) take on the wacky SteamWorld universe. \r\nPerfect for the Steam Deck, you can pick it up and put it down without missing a beat. You don''t even need to use headphones, dialogue is not voiced (well, it kinda is but all you hear is mechanical gibberish), and music/sound effects add little to the experience.\r\n\r\nThere were a few mechanics I didn''t care for (like your inactive party members falling behind ', 'Meh. By the numbers, boring and grindy. I kept waiting for it to evolve into something better up until the very end, and it really didn''t.', 'Very Positive', 85.89, 22.27, 26.53);
INSERT INTO reviews VALUES (27985, 804490, 1039, 'I tried to play this game but then I accidentally uppercutted my dog.\n\n10/10', 'Are you kidding me??? I bought the game at a discount and it won''t start at all, it says some kind of Unreal Engine 4 crash report, what the hell are you doing that you can''t get the game to work normally??? this is for a refund!\n', 'Mostly Positive', 73.92, 1.83, 1.35);
INSERT INTO reviews VALUES (27993, 804700, 319, 'im crying because of the onions!!', 'I like the depth this game gave to some characters and most importantly to Jacopo and Morganas story but honestly I couldn''t focus too much on it since their age difference makes me so uncomfortable. The way where some conversations and topics were going, were just too much for me. Worst part is how everyone else completely encouraged his behaviour, even leading it to sexual topics.\nCompletely ignoring this, the story between them really is amazing and heartfelt but adding a few years to her age', 'Very Positive', 94.67, 70.13, 14.47);
INSERT INTO reviews VALUES (27996, 804850, 258, 'At last, I finally get a pretty decent game that allows me to explore planets and systems. I like the three added DLCs as it really gives the game a lot more depth. The AI looks to be doing the basic things correct. And the graphics look pretty decent. But I will need to play more to see if the AI knows how to expand off-planet. I must say, this is not a complete game engineering dud after all... I would rate it 6 out of 10. But seriously, I would love more content please!', 'Civ clone in space.', 'Mixed', 53.49, 2.37, 7.12);
INSERT INTO reviews VALUES (27998, 804870, 115, '\nCapture reactors, build your own defenses and wander around eliminating enemy robots. \nI guess it''s ok. Music get sometimes weird. You can choose which towers you want to build and where with cursor. I wouldn''t recommend playing with controller as the building interface is not very accessible. Graphics look good but depends on where you looking at because terrain sometimes might look waverly and uneven like made out of clay. I feel like game is missing a few things. You''re able to place turrets', 'this game sucks, the movement is so stiff. the price is too expensive. i have regrets after i buy this game', 'Mixed', 63.48, 7.83, 2.00);
INSERT INTO reviews VALUES (28028, 805550, 12006, 'do not buy i spent $20 on the game and now i''m spending thousands on a new wheel, cockpit, monitors and haptics', 'This is a great game and I do enjoy the gameplay.\n\nHowever - the servers have been quite unreliable and they can be down for hours on end. It is disappointing that a game based on competitive racing is unreliable when it comes to multiplayer.\n\nThis game has been out for 6 years, there''s no reason why servers should be so flaky.', 'Very Positive', 92.43, 64.75, 10.35);
INSERT INTO reviews VALUES (28029, 805590, 673, 'LOVE the game but replayability isn''t great because sometimes if you want to restart from previous checkpoint the game will take you to a checkpoint from another run. Developer personally responded to this a couple days after I posted the review with a hotfix. I think I that speaks for itself.', 'Wave survival games just aren''t really my thing, and for 5 bucks, I''d want something with more to do. Nothing was really wrong or bad, it just wasn''t worth the price tag, imho.', 'Overwhelmingly Positive', 98.51, 8.20, 2.47);
INSERT INTO reviews VALUES (28039, 805820, 141, 'This game cured my cancer!', 'That title isn''t doing you any favours, open it then close it seconds later and be on your merry way.', 'Very Positive', 90.78, 0.13, 0.10);
INSERT INTO reviews VALUES (28047, 805940, 960, 'Nobody will read my review so I will eat 1 Tablespoon of Spicy Ketchup for every like this gets.\n', 'Nagadayu kuplyayuchy (cі navat prosta dadaўshy da zhadanaga) vy padtrymlivaece vajnu', 'Very Positive', 81.25, 4.07, 16.20);
INSERT INTO reviews VALUES (28053, 806140, 466, 'Nobody will read my review so I Will Eat 1 Chili pepper without milk For Every Like this gets.\n', 'Rating: 2/10\n\nAchievement Printer is a bizarre and ultimately pointless "game" that offers little more than an artificial dopamine rush. The concept is simple: you do nothing, and the game rewards you with achievements for, well, nothing. This creates an illusion of progress and accomplishment, but it’s hollow and lacks any real substance.\n\nThe gameplay is non-existent—there’s no challenge, no mechanics to engage with, and no real interaction other than clicking a button to unlock achievements. ', 'Very Positive', 87.98, 2.85, 4.55);
INSERT INTO reviews VALUES (28089, 806950, 374, 'I eventually fell in love with this game. Truly epic in what they delivered. Its grand strategy, logistics, tactical battle and the tactical visuals are great i.e. dive bombers actually dive bombing. Loved every part of it in the end. A little hard to learn the campaign at the start so I suggest playing a few in custom battles first. When you come to the end of first first campaign you will see carrier battles of 10 vs 10 and its just awesome. Addictive!!!', 'overall seems kinda fun, been wanting a game that has the entire pacific campaign. so i started playing. it''s not super in depth, but overall it''s fun, until you''ve sunk your 10th japanese carrier, and there''s still somehow two fleets with 4 carriers, 2 battleships, 3 cruisers and 18 destroyers, one at midway and one at makin atoll. playing on normal difficutly, and apparently the japanese invented the 3d printer in 1942 and can shit out carriers left and right because they have seemingly infini', 'Mixed', 62.03, 143.32, 12.57);
INSERT INTO reviews VALUES (28112, 808080, 287, '', '', 'Very Positive', 87.11, 73.32, 1.35);
INSERT INTO reviews VALUES (28114, 808100, 399, 'this is a game for paradox fans who hate paradox games', 'Bust a fat one.', 'Very Positive', 91.98, 34.45, 20.43);
INSERT INTO reviews VALUES (28133, 808910, 1303, 'Amazing how this game is still fun to play nowadays\nIt''s been decades and the game play still feels smooth.\nHowever I really wish we could someday see a full remake of this game, I''d love to see those pods, racers and tracks with fully up to date graphics, light and textures and game mechanics like improved ways to update your pod''s parts and etc. and why not more and new tracks to interact.\nProbably just wishful thinking XD\nanyway, this one is definitely still worth playing', 'without a doubt one of the best star wars games, and one of the best racing games. this port is garbage. you have to wade your way through an ocean of glitches and imprecise controls in order to play this game. get it on a different platform.', 'Very Positive', 85.26, 26.93, 3.73);
INSERT INTO reviews VALUES (28139, 809020, 1321, 'don''t play this game unless you''re truly ready to experience the abject suffering of attempting to break free from the cycle of samsara', '\r\n  failing the end deletes your save. i dont care if its thematic. i want my time back. this has happened twice  ', 'Overwhelmingly Positive', 95.91, 17.72, 11.92);
INSERT INTO reviews VALUES (28142, 809060, 324, 'It felt like reality and fantasy were blended together, as if I were constantly drifting in and out of a dream. While the playtime may seem a bit short, it offers a variety of elements, including intriguing puzzles, tense moments, and unexpected storylines. It''s truly like a circus!\n\n\n환상 속에 그대가 있다.', 'Unfortunately all I got from my 70 minutes playing is shallow jump-scares and an endless horror-dream scenario with 0 explanations or logic. I did not feel encouraged by what I had seen so far to keep going with the hope there''s more to it than this.', 'Very Positive', 88.58, 7.68, 1.17);
INSERT INTO reviews VALUES (28146, 809140, 1657, 'Nice little aesthetically pleasing futuristic city game from a dedicated dev that kept updating it throughout the years, great bang for your buck!', 'Absolute rubbish. No manual. Nothing to tell you how to go about setting up a functioning city. The tutorial just tells you to build stuff with no explanation anywhere as to why you are building it, what it influences and how it links to other elements of the game. From a concept which is highly original and visually appealing, this is one of the most empty, awful gaming experiences I have ever had. \r\n\r\nIf the Developers even have a clue how to educate new players (which we all start off as) the', 'Very Positive', 84.79, 72.52, 5.70);
INSERT INTO reviews VALUES (28155, 809280, 104, '\tGrimmwood is a cooperative survival game where players are tasked to manage their 17th century village in an increasingly hostile haunted forest, under the growing pressure of dwindling resources. Player characters are given random traits and starting equipment. Death is permanent and comes swiftly with the first mistake, forcing cooperation for long-term survival. There is no player-versus-player, and the uncooperative may find themselves banished beyond the walls, at the mercy of the wild.\n\n\t', 'Started the game. Went outside the village, got some fish and meat. Ran out of stamina. Went back. In the next 24 hours I spent my stamina on building and crafting. That is it. 1,5 hours of gameplay. \n\nIt is a nice idea but the game is unrewarding. You are encouraged to do basically nothing and can\\will be punished for taking actions. Interesting but not fun. Because at the start I had 270 stamina and spent it in 10 mins. But your stamina regenerates for like 10 in a hour. So you need to do noth', 'Mixed', 55.77, 6.38, 1.42);
INSERT INTO reviews VALUES (28156, 809310, 256, 'This game is criminally underrated.\r\n\r\nThe graphics and music give off the same overall vibe, despite being entirely different art media. Each breed of sipho (creature) is masterfully crafted, and every zooid (part) feels satisfying to use. The ingame SFX is amazing, too, with clinks, crinkles, and crushes all working in tandem to create a truly awe-inspiring soundscape.\r\n\r\nI can''t understate how much I love this game. The community is welcoming and more than happy to disclose strategies, tips, ', 'Played 5min, looted a Santa hat, Alt F4, Uninstalled, asked for a refund. This ain''t it. Get the game "Thrive". That''s what we were looking for folks. Cheaper and better.', 'Very Positive', 84.77, 13.98, 0.08);
INSERT INTO reviews VALUES (28164, 809440, 292, 'Awesome little strategy game with a feeling of overwhelming odds. It was fantastic.', 'Eh, it''s ok. Controls kinda suck.', 'Very Positive', 86.30, 39.12, 5.53);
INSERT INTO reviews VALUES (28171, 809540, 322, 'I''m not going to lie, this game has its problems- it''s buggy, the balance is questionable at best, the script can best be described as one big typo, there''s one late optional mission that is virtually impossible due to a bug (except that it automatically cleared itself after I failed it enough times, somehow)... but ultimately, the core gameplay is so much fun the aforementioned problems hardly mattered to me.\n\nRecommended, but know what you''re getting into.', 'The game is very boring, with excessive grinding required at lower levels to progress, which makes advancing to higher levels nearly impossible. This poor game design has led to significant regret over my purchase. My OCD compels me to complete this tedious game 100%, even though I find it unenjoyable.\n\nBut you played for 200 hours?!?!\n\nNo, I left the game running and occasionally ground through it just to achieve 100% completion, leaving this disappointing title as a blemish in my library.\n\nReg', 'Very Positive', 82.61, 26.25, 254.92);
INSERT INTO reviews VALUES (28179, 809720, 332, 'Nice game,  its quite good with coast guard dlc and im addicted to the game', 'After playing it for a good while I got a message from my antivirus that one of the game files in a temp folder contains a trojan:\nC:\\Users\\[]\\AppData\\Local\\Temp\\stillalive studios GmbH\\RHQ\\Player\\FSX\\0e5c2511c9404d16a4135edc9a04e7ab.dll\nTrojan:Win32/Wacatac.B!ml\n\nCool.', 'Mostly Positive', 78.01, 6.52, 37.92);
INSERT INTO reviews VALUES (28180, 809730, 282, 'As an avid aquascaper, fishkeeper and goldfish breeder, this game has an excellent design. I think this can be a super helpful way for those keeping to trial different aesthetics or aquascapes before build-out IRL. \n\nIn terms of the game, I think a really interesting mechanic to add would be varied color morphs. IE: As a ranchu breeder, you could have several base colors in shop such as red, white, black and breed them to create blue, bronze, lavender and tricolor offspring. This would add some ', 'HOW IN THE HELL DO YOU GET TO THE PLUMING VIEW PLEASE HELPPPPPPPP', 'Very Positive', 85.82, 4.67, 30.68);
INSERT INTO reviews VALUES (28188, 809870, 113, 'guys you''re not gonna believe this but i actually saw a carrot in this game (rare)', 'Rabbit go boing boing', 'Overwhelmingly Positive', 96.46, 15.13, 1.02);
INSERT INTO reviews VALUES (28189, 809880, 341, 'Nobody will read this so I will do 10 push-ups for every like this gets.', 'At first, this game seemed like a hidden gem. The concept is solid, and the mechanics feel fun—for a while. But then you realize you''re just doing the same thing over and over, and it quickly turns into a mindless grind.\n\nThe novelty wears off fast, and instead of feeling rewarding, the gameplay just becomes repetitive and stale. There’s barely any effort to shake things up or keep players engaged past the first few hours. It feels like the developers had a great idea but got lazy when it came t', 'Very Positive', 84.75, 1.30, 1.77);
INSERT INTO reviews VALUES (28190, 809890, 367, 'Produced by the same studio that gave us the Wild ARMs franchise, this JRPG may not be revolutionary, but it is still fun, light-hearted and has a great battle system. The OST is well done and (perhaps aside from the protagonist), the cast is well-written, engaging and interesting enough.', 'TL:DR: Game is at best a 3/10 do not play it, or buy it unless you have a morbid curiosity or are masochistic. Interesting music, but game play, story, and characters are mediocre to bad at best. Do yourself a favor and play Tales of/Trails of if you want a better experience.\n\nI streamed this entire play through, and I will say it just doesn''t feel good in the slightest, it''s always one bit away from being good 7-8/10. The idea of music being powerful, is cool, but what they don''t explain is tha', 'Mostly Positive', 71.12, 56.87, 53.95);
INSERT INTO reviews VALUES (28197, 810040, 680, 'I played the free demo before getting this game. My husband and I liked it. We felt that it had a lot of potential and we hoped that we could see this game become more. When we got the full version we had no idea just how much was already in the game.\r\n\r\nIn the demo you are kept to a small island. In the full version you are able to go to another island nearby. AND THEN THERE IS THE MAIN LAND. It was like a tutorial part two. We didn''t really feel like we knew the game until we got past the seco', 'First I love this game, It be a fun game... BUT...\r\n\r\nThe camera is awful when using magic, you aim right at your head unless you charge a spell.\r\n\r\nI wish there was a way to edit the 3rd person camera on the Y and X axis in the settings.', 'Very Positive', 92.06, 69.73, 13.73);
INSERT INTO reviews VALUES (28213, 810500, 304, 'This is a great workout game. Make a playlist for 30 minutes, play through each song and you will feel the workout.', 'I have to run it twice as the first launch is always stuttering and make me super dizzy. Super wrong with its memory management. Get better developers!!!', 'Very Positive', 85.53, 35.72, 35.33);
INSERT INTO reviews VALUES (28221, 810660, 154, 'This game is awesome! I have been waiting forever to play a good point and click game and I finally found a great one. If you are into these type of games (and even if you are not) you will love "The Office Quest". The drawings are beautiful with lots of humor, the puzzles are great and the overall game-play is rich and interesting', 'The story is fun, but, sadly, the annoying puzzles ruins the game! In particular, the platform puzzle sections in chapter 3 ruins the fun of the game. They''re simply annoying, and breaks the flow of the game. I managed to get through it, but the humor of the game was marred by the frustrating and meaningless minigames.', 'Very Positive', 90.26, 2.52, 5.60);
INSERT INTO reviews VALUES (28222, 810670, 188, 'Recommending this solely for fun.\r\n\r\nThat being said, while many people will tell you that you just open a bunch of chests and then you''re done... Well, that''s true if you''re just after achievements. But the game does go beyond that. It has an interesting feature I haven''t seen in many RPGs: while HP and MP recovery outside of battle isn''t new, this game slowly increases your amount of gold as you walk around.\r\n\r\nIn theory, you could probably cheese this system to the max, though that might get ', 'ᅠ', 'Mostly Positive', 73.40, 3.38, 5.07);
INSERT INTO reviews VALUES (28259, 811870, 278, 'Is this game beatable in an hour on your first run (Probably not) well worth the sale price of 2.99. I got 3.5 hours out of it ans still haven''t done the challenge mode or beat the game. I''m Currently stuck on level 97/100 and will probably spend 30min to an hour trying to get to level 98. After level 80 the game becomes a real challenge. This game is a can be replayed especially if you want to try to get all trophies per level.', 'Level design is very poor, looks like a B game. Movement is very floaty', 'Very Positive', 91.37, 3.47, 0.12);
INSERT INTO reviews VALUES (28260, 811880, 259, 'It took some considerable time to adjust to but it has really grown on me. The 3D battle map is great and adds a new dimension which has never been a factor previously. My favorite part in this new addition to the Close Combat series though has been the unit history. Keeping track of your division from day 1 is very satisfying and has been missed thus far. Keep going with this, make a sequel and double down on what you have started here and I think fans will come around.', 'It just really, really stinks. It has less functionality and worse AI than the original series did 30 years ago. These "new" CC games are all a cash grab from a company that inherited the rights.', 'Mixed', 52.51, 81.22, 3.12);
INSERT INTO reviews VALUES (28261, 811890, 307, 'A cool quest for a few hours with a fvсking fun setting, good animations and a nice soundtrack. The only downside is that the game is short. I recommend it from the bottom of my heart.', 'It is very fun, novel and hilarious, but extremely short for its price.', 'Very Positive', 91.53, 3.82, 6.20);
INSERT INTO reviews VALUES (28267, 812040, 907, 'Feel like Star Trek Deep Voyager', 'Suddenly stopped receiving updates 3 years ago while still in a state of buggy and clunky gameplay. Not worth it in the slightest; stick to FTL.', 'Mostly Positive', 74.31, 18.23, 30.77);
INSERT INTO reviews VALUES (28273, 812140, 54355, 'Malaka this malaka that, couldnt you find any other greek words to spice it up ? + There is japanese dubbing but no greek ? JAPANESE DUBBING??? FOR THIS GAME ? AND NO GREEK ? Malaka ubisoft for sure. \n\n', 'Played the game for almost 100 hours, had fun with it. Until I lost all my progress. The game has cloud saves on Ubisoft connect. Same ubisoft connect that somehow corrupted all my save files making me lose all progress. \nI won''t ever replay it again because Ubisoft can''t have a working launcher.', 'Very Positive', 89.56, 7.35, 100.82);
INSERT INTO reviews VALUES (28280, 812410, 116, 'It''s simple - I''m a big fan of monster girls and ready to consume a lot of content. But even so this game is my favorite girls with monster girls. I like girls and their personalities and I like that this game is pretty short. It''s a shame that there is only 3 girls here.', 'Who comes up with the idea to sexualize a flipping plant??\nFricking vegans.', 'Very Positive', 88.79, 7.57, 0.25);
INSERT INTO reviews VALUES (28284, 812550, 152, 'Tony Hawk''s Pro Whimsical Forest Adventure.\n\nYou can get really fast and it''s a wonder to play, like you can almost feel the wind in your hair as you fly through the beautiful levels.', 'I just don''t get it. Couldn''t get past the tutorial where the dude with wings stops you.\nI guess this game is too "artistic" for a smoothbrain like me.', 'Mostly Positive', 71.05, 1.65, 0.17);
INSERT INTO reviews VALUES (28294, 812840, 161, 'If I could give a neutral rating I would, it''s not bad enough for a not recommend, but it''s also doesn''t really do anything to set itself apart from other VN''s. \n\nAlso for some reason it was tagged as having sexual content and nudity for awhile, it doesn''t.', 'Black Miku is a guy: Confirmed.\n\nEdit: Dev done perma-banned me on 3 infractions of hate speech and harassment, too bad you can''t delete reviews 🤣🤣', 'Overwhelmingly Positive', 95.65, 3.60, 7.85);
INSERT INTO reviews VALUES (28297, 812870, 155, 'Well balanced and interesting combat. Lots of character customization (both in your own hero and customizing the allied heroes).\n\nIt doesn''t have Freedom Force''s focus on environments and destructible terrain, but it has basically everything else that made that a great game.', 'I liked it in 2020 but I was waiting for more content beyond the first two chapters.  Here I am in 2025 checking back to see what has been added and found nothing!  Completely abandoned since 2021.  If this comes up in your queue and you think "Hey I love X-Com and Superheroes!"  Forget it.  Even on a 90% sale it isn''t worth it.  It''s too bad.', 'Mixed', 67.10, 5.45, 7.55);
INSERT INTO reviews VALUES (28312, 813230, 11455, 'when i first saw gameplay of this game i thought it looked a bit like rain world, but after playing it a bit its much closer to halo 2 mixed with halo 3.', 'Tried to beat the game in ernest without any walkthrough. Did not enjoy travelling the map hundreds of times scraping for clues to get the "real ending" . At some point all the charm it started with slowly lost all it''s bubbles.', 'Overwhelmingly Positive', 95.49, 6.32, 42.45);
INSERT INTO reviews VALUES (28325, 813540, 192, 'fun little witty visual novel. can be completed in 2 hours, but fun none the less', 'The trailer looked really good, but the actual gameplay was really disappointing. The setting was interesting, the voice acting was good and the characters were consistent, but the story was lacking, the dialogue was a constant swearword rant and the game was over in a couple of hours. Can''t recommend.', 'Very Positive', 82.81, 2.35, 4.42);
INSERT INTO reviews VALUES (28327, 813630, 4503, 'I rarely sit down and beat a game in basically one go, but Supraland hit my ADHD at just the right angle. Only negative thing I can say about this game: I 100%ed it and they added more achievements. BLARGH!!', 'The devs should be held personally responsible for the Donald Trump assassination attempt because of their "Well Deserved" achievement. See how you libcucks like it.', 'Overwhelmingly Positive', 96.05, 23.22, 26.97);
INSERT INTO reviews VALUES (28329, 813700, 155, 'gay asff', 'Not one of the best I''ve seen, but if you''re one into Yuri, i guarante you''ll be grinning for hours- \nOr y''know, "other things". e_e;;\n\nBut god they talk and talk for so long reeee-', 'Very Positive', 87.10, 6.62, 2.37);
INSERT INTO reviews VALUES (28331, 813780, 55249, 'I enjoy the Definitive Edition, but I hesitate to call it the same game as Age of Empires II. Like the Ship of Theseus, nearly every part has been replaced, usually for the better but sometimes replaced with inferior versions. The voice acting especially, stood out as a major letdown compared to the original. There''s mods to bring back some of it, but it makes me sad that most people won''t be installing them and thus won''t grow to appreciate the original artistry as I did.\n\nLike imagine someone ', 'I have owned this game for 5 years now and out of nowhere there''s now a new EULA to sign or you can''t play the game. I don''t care what is on the EULA. What care about is agreement was added to the game after I purchased it and already had my agreements beforehand. I''m getting sick and tired of companies thinking they can just add new end user agreements to their software and did not use service if you don''t sign them now in their initial end user agreement there''s probably some stupid stipulatio', 'Very Positive', 94.95, 8.33, 101.65);
INSERT INTO reviews VALUES (28336, 814000, 1287, 'I recommend watching at least to episode 600 before playing so you know most stuff and things don''t get spoiled. But for game play its super fun to play and you could do lots of fun stuff I cant describe it to much but I will say 1 thing you should explore the whole map before doing somethings.', 'I''ll open up with the positives: The visuals and effects are pleasing to the eye. The menu and UI are easy to navigate and easy on the eyes. The character interactions are great, especially if you''re a fan. If you like One Piece''s overused gags, you''ll love seeing them here(gotta love em). Many good ideas in this game, such as smaller battles happening amidst a bigger brawl. The idea of a One Piece RPG is fantastic and they shouldn''t give up on it. I love the idea I first mentioned in particular', 'Very Positive', 82.05, 14.85, 94.40);
INSERT INTO reviews VALUES (28348, 814370, 4540, 'Its such a pity because I know I would of absolutely loved playing this as a kid.\n\nThe premise is so simple yet unique, tame monsters, use them to battle other monsters. collect them when you win and train them to get stronger, gotta catch em all , why didn''t anyone think of this before ?\n\nFortunately I''m still a child trapped in a 40ish year old body so its not really an issue enjoying this much more then I probably should.', 'The game was very fun at first and seemed like it would have huge potential.  But the longer I played, the more bored I got.  Play sessions started to feel grindy and I stopped having fun.  Eventually I just stopped playing altogether.', 'Very Positive', 92.97, 43.00, 41.13);
INSERT INTO reviews VALUES (28349, 814380, 79123, 'its like im playing Edlen ring the ring i played it like dark souls 2. the ring ring souls, shing shing can we get Bloodborne on PC please sony you gatekeeping fucks', 'For a game so focused on one-on-one combat, they sure love throwing 6 enemies at you at a time', 'Very Positive', 93.81, 50.25, 6.27);
INSERT INTO reviews VALUES (28352, 814480, 127, 'si', 'Chinese ahh Minecraft', 'Mostly Positive', 72.44, 22.55, 105.17);
INSERT INTO reviews VALUES (28354, 814530, 289, 'I generally don''t like RTS games. I''m not good at them, I don''t understand them, my brain just doesn''t work in that way. Death Crown overcomes that by stripping everything back to the purest distillation of the genre. No tech trees or elaborate build orders, just three types of building - money building, troops building, defence building. Your troops march out at a steady rate without needing your input, kind of like in a MOBA - all you need to do is build the relevant buildings and set a path f', 'An RTS boiled down to its most base components: 3 structures. One attacks, one defends, one collects resources. Visually great and cleanly designed but very shallow feeling.', 'Very Positive', 88.24, 2.50, 0.27);
INSERT INTO reviews VALUES (28355, 814540, 7632, 'Made me a furry, gay, and everyone is hot, also i was hard while playing through the whole game. would recommend, my fav game.', 'I played it two years ago. The puzzles are interesting, but the game itself looks pretty unpleasant. Sure, the characters are kind of original, but it still doesn’t feel nice, even weird, plus, the main character looks like a kid, and this is VERY weird..', 'Very Positive', 85.39, 7.62, 10.17);
INSERT INTO reviews VALUES (28368, 814680, 556, 'Thoroughly enjoyed this game!  It''s a mix of the puzzles of Abe''s Odyssey, the fast hard platforming of Celeste, the quick time events of Ori / Rayman and the metroidvania skills of Hollow Knight.  Put them all together and you get this underrated gem of a game that I''d never heard of and never comes up in Metroidvania lists.  \n\nConsidering I bagged it for under a fiver and I''ll get about 10 hours of playtime, I think it''s thoroughly worth it!', '7.5/10 overall for the game. It''s polished and well put together, and some very fun level design mechanics that are well utilised. The art is a bit budget but has its charm and is good enough for what it is. Music is nice, perhaps a bit repetitive after a while. The story was fairly intriguing but was more like a childs book. \nWhy can''t I recommend this? The difficulty spikes.... I was often having fun but then hit moments where it required micro micro millisecond input to get around a puzzle, t', 'Very Positive', 84.53, 8.77, 1.92);
INSERT INTO reviews VALUES (28372, 814740, 448, 'This was a really cool idea but they gave up on it. \n\nIf on sale it''s worth playing at maybe 5-7$, that is probably fair. \n\nIt''s not worth 20 and never expect them to finish it. \n\nIt''s sad when good ideas are left to rot.', 'ABANDONWARE! \r\n\r\nDO NOT PURCHASE, THE DEVS ARE ROTTEN', 'Mostly Negative', 27.01, 20.25, 18.58);
INSERT INTO reviews VALUES (28392, 815150, 118, 'JRPG GOTY 1993 right here boyos.\r\n\r\nBut in all seriousness, there''s a remarkable amount of depth and easily swappable ''build'' decisions for all the characters, and while it''s not totally freeform, the amount of variety in skills and equipment means you end up devising team-wide openers for combat depending on enemy group makeup and needs. \r\n\r\nIt''s a lot more sophisticated and nuanced than the simple presentation suggests, and while the writing isn''t winning any awards, it''s charming and perfect ', 'My game is broken! When ever my character level up It said I got a new skill a double strike but when go back to stat and check the skill the skill werent there Im stuck with the same old skill the game is glitch I dont receieve any new skill when I leveled up even it said so Please FIX this and i reconsidered rerating', 'Very Positive', 94.92, 24.98, 11.52);
INSERT INTO reviews VALUES (28403, 815450, 148, 'A quite good visual novel, with an interesting story and a good choice system. It''s not the best on the market, and considering  the sheer number of VNs out there it''s probably not your first pick, but if you''re looking for something decent, short and out there, you''ll want to try this one out.', 'I wanted to love this game so much, so it''s frustrating to write this. I wasn''t sure if I was even going to, but I''ve only seen one other review that matched my concerns, so I decided to just do it. To preface, I''ve been following Rinmaru and her awesome work for a long time; I loved the Ascension games when they came out and played them a ton. I really admire and respect her goal of creating powerful stories focused on strong female characters, they''re definitely needed right now. Cardinal Cros', 'Very Positive', 94.59, 9.83, 2.70);
INSERT INTO reviews VALUES (28415, 815780, 1790, 'My friend who i play CS:GO with said if i post a review on this game and it gets 200 likes and 200 awards that he will buy me a RTX 3060 and 2 kilos of canned ham. So i''m just gonna leave this here. Help a brotha\r\n', 'I hate this game with all my heart. The controls are straight up dogshit. It looks like a garbage can and the fucking achievements are impossible and no fun at all. please dont buy this and if you do make sure you find a way out because it will bring depression', 'Very Positive', 88.99, 102.85, 18.77);
INSERT INTO reviews VALUES (28428, 816090, 5503, 'honestly the best first person 40k game out there it looks great, plays great, has a lot of replayablity and is just all around fun and the levels look amazing, if youre a fan of 40k you will like it\r\n', 'Game is boring, monotonous and awfully balanced. Difficulty is mostly made by absurd inaccuracy when you have to empy half the mag of assault cannon to hit someone more than 20 meter away form you. Holding you weapon at the height of your balls also makes it near impossible to shoot standing next to a meter-high fence. Recoil while zooming fells like shooting a gun taken from the titan, but damage feels like shooting .22lr (takes 3-5 hits to pasify common enemy). I understand that shooting and c', 'Mostly Positive', 73.94, 54.00, 4.38);
INSERT INTO reviews VALUES (28440, 816340, 1508, 'Kingdom Rush Origins is the third installment in the Kingdom Rush series and the chronological prequel to the first Kingdom Rush game. Taking place on the southern continent 30 years before the original game, the enemy factions and towers are entirely new as we play as the Sylvan elves instead of the Linerean Army like the first game.\nThe game follows a typical tower defense formula with plenty of other systems that improve the experience. The main gameplay consists of building towers in strateg', 'This tower defense game really likes to do that thing where you build a decent tower setup and then the enemy just happens to open a new path around your defenses.', 'Very Positive', 94.56, 45.00, 3.85);
INSERT INTO reviews VALUES (28445, 816430, 129, 'A lot of fun for the money. And a lot of bugs, mostly in boat and chopper part, so please be aware. But nothing I cannot handle for €2.43.', 'good game for free but way to buggy and cheap for money (after the car levels the game is just shit)', 'Mixed', 66.67, 6.50, 12.92);
INSERT INTO reviews VALUES (28446, 816490, 387, 'It''s a cute game despite the very simple graphics. You''re looking for cats and yarns in a quiet and rather empty winter world. Sometimes it''s really tricky, but you can get (vague) hints when you''re stuck. \n\nI have mixed feelings about this game. The music is nice but very repetitive, the cats are cute but the empty islands feel a bit creepy, the controls let you move very freely but also give me motion sickness, so I can always just play for a short time. \n\nOverall I think the game is well made', 'A hidden object game where you embark on a quest to find cats and colorful balls of yarn across 20 snowy islands. Hidden Paws, with its cold winter night atmosphere, is visually appealing and creates a cozy ambiance. The game offers over two hours of gameplay, which, while not extensive, is perfect for a casual gaming session.\n\nAt first glance, the graphics are fair; they do the job but don’t particularly stand out in the crowded genre of hidden object games. One major highlight is the soothing ', 'Very Positive', 84.50, 3.47, 2.80);
INSERT INTO reviews VALUES (28473, 817230, 130, 'THIS GAME IS WAY BETTER THAN IT SHOULD BE FOR A DOLLAR', 'no controller support for a game like this is a crime, hard pass.', 'Very Positive', 90.77, 1.10, 0.12);
INSERT INTO reviews VALUES (28482, 817510, 379, 'Golfing Over It with Alva Majo is the same as Getting Over It in essence, although I prefer the latter. This game is still great don''t get me wrong, I just hate controlling a ball. This game made me rage and I definitely injured my scalp, maybe this game did its job too well. In all seriousness, I really loved the challenge and though I was mad, it just made me hungrier to clear the game and finish the speedrun and hit limit challenge. A simple yet gruesome game. Recommended but not for the weak', 'pain in the ass\r\n', 'Mixed', 68.87, 8.02, 5.33);
INSERT INTO reviews VALUES (28484, 817540, 822, 'Fantastic game, interesting mix of RTS and RPG mechanics. I wish there was more games like this.', '"Welcome! Thank you for playing SpellForce 3 ! For the best experience, please sign into your THQ Nordic Online account, or create a new one for free if you aren''t registered yet."\n\nThis is a thing you will see when starting up the game. If you hit play offline it will try to guilt trip you to make an account for fear of losing out on some bullshit level or whatever.\n\nYou will see this in the other SpellForce 3 games: Fallen God and Reforced.\n\nHow about no! I am done with this series. The first ', 'Very Positive', 83.09, 30.65, 0.10);
INSERT INTO reviews VALUES (28495, 817840, 1265, 'It''s not like other XXX-rated games, and that''s exactly why I like it. A bigger and better sequel would be hella awesome, with the same format, just with more to do!', 'The art and characters and humor are great, but, there''s just not a lot of content here -- definitely not enough to warrant $20. The gameplay loop is shallower than similar games you could find on Newgrounds for free 20 years ago.\n\nAlso, I beat this game, grinded relationship to max for at least one executive and didn''t see one single tiddy?? Even with the nude patch and everything, I expected there to be something other than unlockable concept art that''s in a completely different style. Imagine', 'Very Positive', 93.28, 38.95, 6.45);
INSERT INTO reviews VALUES (28510, 818210, 198, 'Cool and very entertaining game!', 'game didnt even bother working when i tried to play it', 'Very Positive', 80.81, 11.93, 0.13);
INSERT INTO reviews VALUES (28525, 818520, 111, 'Built pyramids, angered gods, and accidentally turned Memphis into a trade hub for Beer. 🍺💰 Balanced temples, armies, and royal tantrums—who knew Pharaoh life was this chaotic? The Prologue was also fun. 🏺✨\n\nFollow my curator page for more ancient chaos, divine drama, and Nile-side shenanigans:\nhttps://store.steampowered.com/curator/42602807-Osiris-Reviews/', 'Mechanics are earie similiar to the Pharaoh, while 3D graphics not looking good, and being poorly optimized. Especially striking is the details distance which is laughably short. Usually how the game looks is second to me in case of managment games, but in this case you would have extremely similiar (if not better) experience with Pharaoh, which 2d graphics looks better than this.', 'Mixed', 42.34, 1.50, 0.48);
INSERT INTO reviews VALUES (28550, 819020, 336, 'Came back to this after leaving it 5 years ago due to certain... events that unfold within the game.\n\nComing back to it, forgetting much of the extraneous stuff, I found myself remembering the core story and gameplay, it had made an impression I suppose,  but I often found the gameplay while fun, was held back by the story at times and likewise when I wanted to just focus on the story the game would get in the way because I had to get better gear or make more food etc. Thankfully if your like me', 'I couldn''t bring myself to finish it. The combat is clunky, the micromanagement is not fun, and I''m not invested in most of the characters. \n\nI finished an LP online to check out the rest of the plot and I''m glad I didn''t continue with the game - the plot writing also left me feeling very disappointed. \n\nHard pass.', 'Mostly Positive', 76.49, 76.25, 19.93);
INSERT INTO reviews VALUES (28551, 819030, 400, 'Man microwaves his friend''s banana and invents time travel. 10/10', 'Play the original', 'Very Positive', 88.50, 8.48, 12.63);
INSERT INTO reviews VALUES (28557, 819190, 121, 'Had previously posted what was likely a rage induced critical review of this title. I was quite let down by a game that showed much promise. \n\nWithout going into great detail, Dark Curry didn''t abandon their project, bringing it more in line with the pre-launch hype it had garnered. Combat feels much better, as does the performance. \n\nMay add more if/after I play through the campaign again.', 'Pros: \nIt''s a good time, I find it less floppy than blade and sorcery, kind of similar style, but takes itself less seriously. The voice acting is fun. \nCons: The pick up and store system is way too precise, I go into a fight and suddenly realize at some point I''ve dropped my sword instead of storing it, or thrown my bow over my back instead of storing it. Picking up arrows drove me to madness, you have to be so precise you have to spend ages just trying to grab them. Climbing similar. Also ther', 'Mostly Positive', 70.25, 14.63, 0.73);
INSERT INTO reviews VALUES (28573, 819630, 136, 'The game is pretty cool but it needs more ability to work inside of the paint without the player going straight into a dunk. I''d also like the ability to change how many games are played in a season. The game is pretty repetitive and I d think it needs 15 games in the regular season. 12 at most.', 'I wanted to like this game, but in the end, a game like Baseball Stars or even NES Hoops beats this out. I appreciate all of the references (recognized them all, very very cool) BUT THE GAMEPLAY IS NOT FUN.\n\nGet Super Blood Hockey instead.', 'Very Positive', 94.12, 28.63, 1.43);
INSERT INTO reviews VALUES (28588, 820020, 113, 'Great concepts, great art, not perfectly executed. I love the many combat mechanics at play here. I like how there are many stats and ways to customize your characters, including voice, though the stats seem a bit unnecessarily bloated (for example, the 10 stamina = 1 bar, and 5=1/2 bar). The UI could use some polishing - sadly that probably won''t happen now. I understand its supposed to be difficult, some of the challenge just seems like arbitrary limitation. For example, why start on the hunte', '(Posting this review at 3 hours played mark) \nCame in expecting a Darkest Dungeon meets XCom type of game, but I''m sad to say I found an unfinished, buggy mess that wasn''t sure what it wanted to be.\nInteresting premise and great atmosphere, however the gameplay is rather stagnant as you face the same rather uninteresting types of enemies over and over again. The mechanics are unclear as well, the game doesn''t do well to explain what exactly activates enemies - they will either wander pointlessly', 'Mixed', 61.95, 8.82, 5.85);
INSERT INTO reviews VALUES (28606, 820520, 3612, 'Its kind of crazy that devs still didnt turn this game f2p, but keep pumping out battle passes and cosmetics for 50 ppls that are still playing it.\nIts a good game, but its dead af. Make it f2p, dont be dumb.', 'This is an excellent game that has, sadly, gone overlooked by a broad audience fascinated by marginally different online shooters. Deceive is a really fresh take on action and espionage but rolled into the format of a shooter. It''s really fun to pretend to be an NPC, it turns out. Slipping around people in plain sight was a thrill and hilarious all at once. Lots of good things to say about the gameplay. \n\nUnfortunately, because this game failed to garner a decent audience, the entire community i', 'Very Positive', 85.44, 96.28, 48.15);
INSERT INTO reviews VALUES (28613, 820630, 509, 'a game so violently american it makes me wanna invade a foreign country to liberate them from communism', 'This game is not bad, only problem is that it always crash when i do second mission. I read comment''s  where people have the same issue due to AMD graphics. I''m among them. I''m waiting to fixing the issue', 'Very Positive', 84.87, 25.33, 0.57);
INSERT INTO reviews VALUES (28620, 820730, 167, '‎', 'In Adventure of a Lifetime, you play as Hiroki Mizuno, a teenager returning to the Ogasawara Islands to help his grandmother with her restaurant. On the way to the islands, he meets the half-Japanese, half-American Emily who is traveling to the islands to look for a lost sunken treasure. He also meets up with his childhood friend Chisa who is a skilled swimmer. Hiroki and Chisa take an interest in Emily''s goal of finding this treasure and work to retrieve it all while Hiroki gets closer to these', 'Overwhelmingly Positive', 96.41, 54.35, 7.40);
INSERT INTO reviews VALUES (28627, 820900, 106, 'I am not into LGB type of stories because to me a lot of them seem really forced, but not this one. \n\nThis has wonderful art and environment design, relaxing music, fun to solve puzzles, and a lovely short yet engaging story. When I played it I didn''t know it was an LGB story but the art was to pretty to push it away so I gave it a try and omg did it pull the strings in my heart. \n\nThis gets a ♥ Lovely (´,,• ω•,,)ﾉﾞ♡ rating from me!', 'RPG Maker strikes again!\n\n"Ceress and Orea" is one of hundreds of low effort retro-pixel RPG Maker asset/construction kit flips spamming the Steam catalog, made with the RPG Maker video game construction kit... in their own words, "Our easy to use tools are simple enough for a child."  Like all RPG Maker "games", this is essentially a bunch of low quality/canned assets from RPG Maker coupled with a cringeworthy high school anime club fan fiction.  In this case it does appear some of the assets a', 'Very Positive', 88.68, 2.12, 3.58);
INSERT INTO reviews VALUES (28637, 821250, 1113, 'A word of caution is also why I like Flotsam:  It''s in development, so it''s changing.  Things work, then change, and sometimes break before they work again.  It''s like playing a new game every few months.  The play is casual, which I like.  But interesting enough to keep me playing one more game day.  They''ve added "architect" which allows fixing city layout.  Floating things can be rearranged.  So unlike other city games, when something doesn''t work, you don''t have to destroy, crash your popula', 'There are reports going back to 2020 of people being unable to save their game.  I just ran into this same issue.  That''s kind of a dealbreaker for me, so I don''t recommend Flotsam in its current state.', 'Very Positive', 82.21, 1115.78, 7.65);
INSERT INTO reviews VALUES (28639, 821320, 105, 'This game changed my life and fixed my balls and bought me a ps5 and jerked me off and kill me \r\n', 'literally has no replayability', 'Very Positive', 92.38, 1.13, 1.48);
INSERT INTO reviews VALUES (28670, 821880, 1295, 'This game is about two of my favorite things: anime women and ruthless capitalism', 'It''s a solid game. Got a few decent runs in a couple years ago on release. I honestly forgot I even had this game until i randomly had the urge to play it again this week. Be aware, this game is unfortunately in pretty busted state nowadays with some serious game breaking bugs. Lost saves and broken time advancement are pretty common and it seems these bugs are never going to be fixed. The developer has completely abandoned the game and dropped off the face of the internet.\n\nIf you were hoping f', 'Very Positive', 90.89, 48.72, 25.62);
INSERT INTO reviews VALUES (28701, 822760, 162, 'Fureraba is a rather decent moege, most of the game is comedy but there are some surprisingly emotional & heartwarming moments.\r\nEven though this is an old game, CGs are very well-drawn and still up-to-date with today’s standards, H-scenes aren’t lengthy which is a huge plus in my opinion. \r\nThe main problem I have with Fureraba is its protagonist, out of every Smee games I’ve read (Fureraba, Making Lovers, Sugar Style, HaremKingdom), Kyousuke is the most hyperenergetic, he’s quite calm in some ', 'I can''t find a reason to recommend this VN, it has nothing different or memorable, the joking tone is excessive, common route is nice but the romance routes are very similar and tedious to read, with all 4 girls losing most of their initial personality and becoming some overly-attached housewives. I felt that the 30 to 50 hours lenght worked against this VN for it being too repetitive.', 'Overwhelmingly Positive', 98.15, 57.20, 63.88);
INSERT INTO reviews VALUES (28704, 822830, 114, 'I appreciate the game keeping convenience in mind when it could have foregone such consideration for a lazy tedium. It keeps the game''s pacing pretty tenable.\n\nThe patch scenes are not exactly something to drool over, but I personally find this quirk about the game quite tickling. \n\nIt''s been a good time. Endearingly amatureish, with an engaging casual story of many bemusing novelties and turns into the unexpected, not to forget fun characters.', 'Play Chrono Trigger or some other game which doesn''t waste your time.', 'Overwhelmingly Positive', 95.61, 13.50, 1.23);
INSERT INTO reviews VALUES (28710, 822930, 647, 'cute sexy wolf girls, heartwarming wholesome story, and an 18+ patch to boot? 10/10. chat can we get these wonderful ladies some headpats and forehead kisses?', 'Catgirls >> Wolfgirls. Change my mind.\r\n\r\nWolf Tails is a visual novel developed by Razzart Visual, the same devs behind Love Ribbon, which I reviewed a while back. This is a far shorter VN (since it was developed using Ren''Py, you can see the progress by pressing F2), and, while I think the writing is a bit better than Love Ribbon, there are still issues that I need to address.  But first, let''s see the positives. The art direction, while generic, is fairly detailed, and character design is sol', 'Overwhelmingly Positive', 95.98, 2.93, 5.90);
INSERT INTO reviews VALUES (28713, 822990, 237, 'Normally I wouldn''t recommend, but I think if you can get it for a few dollars on sale it''s worthwhile.  Overall, a very interesting game concept that is technically well-implemented, but lacks a bit in the actual fun of the core gameplay loops.  There are tons of options for manipulating governments, researching cyberpunk technology, controlling the media, etc., but a lot of what you are doing on each game turn is looking at marketing angles and deciding what products to launch in each country.', 'I cannot get through the tutorial. Tried in September 2023 and again today. These morons have flashing rings around things where you need to click. Anyone with ADHD or epilepsy, stay away from this game! These idiots only needed to put a still, yellow halo to highlight what you need to find. Instead, they bludgeon you with flashing lights. Over a year later, still the fucking flashing lights.\r\n\r\nThe usual losers will find this funny. Those who consider themselves soooo tolerant, but find the mis', 'Mostly Positive', 77.64, 16.65, 0.43);
INSERT INTO reviews VALUES (28716, 823130, 10831, 'Stopped playing after discontinuation was announced to find another BR with lively player base, eventually came back to see devs were subject to a DDOS attack, reworked some stuff to counter the attack, and then released community server tools. Also they begrudgingly released a battlepass for $6. Devs are overwhelmingly based, please support these people.', 'only cheaters left );', 'Very Positive', 90.77, 45.52, 17.57);
INSERT INTO reviews VALUES (28732, 823500, 29040, 'In this physics-based puzzle game, you play as a scientist with a crowbar who travels through a large complex infested with zombies and crab-like creatures which attack by jumping onto people''s heads.\r\n\r\n10/10', 'I''ve given this game couple of chances. I watched numerous reviews. Many talked about how deep the game is etc. But it’s extremely boring. After 12 hours it’s all the same. Just go from one point to another and shoot. The story seems like an afterthought to a tech demo. It all felt like there was always severe input lag and stutter, other VR games in my collection don’t have this problem (e.g. Half Lie Alyx). Despite having more than enough setup for this game. I browsed through forums and suppo', 'Very Positive', 92.63, 53.82, 12.20);
INSERT INTO reviews VALUES (28738, 823610, 139, 'Solid Dungeon Crawler that definitely was able to still my hunger for this kind of old school game genre. Graphics and tile set variety are fine as is the sound and there are enough riddles and traps involved to keep you going. Fights and movements are old school, party can be personalized a bit, all good. On the negative side you can buy all (!) gear in the shop before finding it in the dungeon as you always have more than enough money to spend. Also you can easily max out your characters so th', 'This is a poorly made Grimrock copy full of bugs, nonsensical puzzles, confusing English translation with bad grammar and typos. If you''re looking for a Grimrock-like to sate your hunger, trust me, this won''t cut it.', 'Mixed', 69.78, 26.50, 2.87);
INSERT INTO reviews VALUES (28751, 823940, 313, 'I will admit the game is abandoned, Servers are completely dead, AI will kill themselves in the storm and leader boards are probably not accurate. The only reason I play this still is that the gun play to me is still fun. Even with AI its still kinda fun to just kill everyone for I guess practice or something. I wouldn''t say buy the game unless its like 5-10 dollars. This game dropped when I think population one dropped (another VR royale game) and it didn''t stand a chance against it.', 'No one discount on sales.', 'Mixed', 65.81, 13.42, 0.18);
INSERT INTO reviews VALUES (28752, 823950, 955, 'Ive had it on my wishlist for a while and just havent gotten it until now because of the negative reviews, but its a lot of fun. yeah its a little grindy but thats actually part of the fun. it feels like something i would have played on gamecube, definitely give it a shot if you like the farming sims. it does feel a little unfocused, like they just kept having ideas and adding them in, but i find that pretty enjoyable.', 'Abandoned.\n\nAfter a two year silence, they dropped an update that they''d be continuing development and work on multiplayer, etc... that update was on January 2024. It''s almost been another entire year of silence since then. Game is buggy and unfinished in its current state, and I''ve run out of copium for an update.', 'Mixed', 56.13, 13.47, 16.17);
INSERT INTO reviews VALUES (28753, 824000, 1068, 'It’s a shame that this game got so much hate when it was first released. Here in 2024, the devs fixed a lot of bugs and the game received awesome updates. Get it if you like Animal Crossing or relaxing decorate games in general. The game really opened up for me after I built the first house. It is only $3.99 when it is on sale.\n\nThis game could be a hit if they could polish the character models and keep updating it with new areas and content. Personally, the models could be better but doesn''t bo', 'First of. 19,99 is redicolous. You don''t get anything worth the money. \nPut some horror music in the backround and make the game a bit darker and you have a wonderful kids horror game, becausee the characters just look scary and are lifeless.. \nthe "quests" are just: Here, grab this, talk to this freaky animal, then go back. Over and over and OVER!!!\nWhat else can I say... spent your money on something else...', 'Mixed', 68.54, 5.53, 0.52);
INSERT INTO reviews VALUES (28754, 824070, 478, 'This is a very particular but very fun game. It plays more like one of those old submarine simulators than your standard space sim. But now it''s you going in freedom instead of following orders. There''s tons of things to do.\nThe graphics are really retro, one of the first PCs might even capable of displaying the graphics. But for me, that''s a big plus. These graphics ignite your imagination, the same way a book does. There should be more games with graphics like this.\n\nLike modern sub sims, it w', 'PS: If you want something similar that has a future, search for Ostranauts in steam.\n\nLook...its a good game. I followed this game years before it launched back in 2018. I was very hyped.\nBUT its sad that the devs abandoned really quickly and left bugs and no ending.\nWith this you can get minimal 20h of gameplay easy and fun. But remember its not finished and the later you go more bugs.', 'Mixed', 50.42, 57.20, 19.98);
INSERT INTO reviews VALUES (28758, 824190, 329, 'The whole purpose of this "game" is to earn 5000 achievements in under 5 min with an autoclicker.', 'It''s clear to everyone what this game is for.\nIt''s clear to everyone that this game is trash.\nIt''s clear to everyone that I am one of the people who knowingly gave money for this trash and why.\nIt''s clear to everyone that I need help.', 'Very Positive', 85.11, 19.85, 0.10);
INSERT INTO reviews VALUES (28763, 824280, 245, 'My 3 year old loves Monster Jam. I love Monster Jam. You love Monster Jam. Watch Monster Jam = Good. Play Monster Jam = Great. 3 year old becomes Monster Jam driver = Win!', 'Close to being great but absolutely BONKERS Freestyle physics ultimately gives this game an L\r\n\r\nOddly the more grounded MJ game, probably The most grounded MJ game, which further disappoints me since the game plays like butt.   \r\n\r\nTrucks feel floaty and weigthless.  But at least they don''t feel as terrible as Monster Truck Championship.  They hardly bounce from big jumps.  In air control is greatly exaggerated; you can do backflips off of jumps that would be otherwise impossible to.  \r\n\r\nOvera', 'Mixed', 68.16, 3.03, 4.77);
INSERT INTO reviews VALUES (28774, 824550, 961, 'It''s a hack n slash game.  No surprise.\r\nDon''t know what all the fuss is about that people were complaining.\r\nSo many gundams and units from across the eras and ages.\r\n7/10 and that''s a good rating.', 'Pretty hard to play when theres SO MUCH action on screen and they expect you to read subtitles to know whats going on. darting my eyes back and forth especially when playing on the big screen sucks. Just tired of the lazy ports. Not going to bother buying anymore modern games that arent dubbed in english.', 'Mostly Positive', 79.19, 12.72, 11.25);
INSERT INTO reviews VALUES (28777, 824600, 3261, 'This is the kind of game that big studios have forgotten how to make.  Incredibly atmospheric and filled with tons of hidden secrets and Easter eggs.  Solid boomer shooter gunplay with creatively designed levels.  The custom engine presents you with some very unique visuals and great performance.  The setting is super cool as well, I''m a big fan of the Stalker games and old Soviet architecture so it was a joy to explore the environments.  You can really tell this game was made by a gamer FOR gam', 'A friend returning from several months in the Czech Republic liked to do an impression of a dour Czech, delivering an accented, expressionless, "it is okay" when questioned about something''s value. That''s this shooter. It is okay. It''s not that fun and it''s not that clever. The theme is fine. Everything is brown. None of the weapons feel good to use. The enemies are sort of funny but mostly kind of dumb. The level design is a so-so retread of actually good shooters from the 90s. I get that it''s ', 'Overwhelmingly Positive', 96.99, 6.63, 9.47);
INSERT INTO reviews VALUES (28783, 824830, 171, 'The corpses partied again 🗣', 'I can''t really recommend it unless you''re a die hard fan that absolutely must drink up all Corpse Party content. The silly 3d models take away a lot of the atmosphere first and foremost. The game is full of chases that don''t really serve any narrative purpose. You have to avoid hazards around the school that deplete your health, but you''re healed as soon as you save so it''s mostly just there to be a nuisance. They pack in so many new characters, nobody has time to breathe. While it''s called the ', 'Mostly Positive', 71.35, 28.20, 22.05);
INSERT INTO reviews VALUES (28785, 824850, 135, 'pleasant 3-hour post-apocalyptic walking sim, exploring an abandoned place and examining items to figure out what happened to the inhabitants and the world itself 300 years ago. no puzzles or anything, so won''t be for everybody. really slow movement speed as well, made worse by having to walk back and forth and the final section. a lot of unnecessary ellipses too. there''s a handy map and a hotspot indicator at least. and a knight rider and dune reference, don''t see those often enough.\n\nannoying ', 'sucked\n\nits been long enough i dont really remember my gripe with it, i just know it sucked', 'Very Positive', 93.33, 3.13, 1.53);
INSERT INTO reviews VALUES (28796, 825300, 123, 'This was a solidly good quality story. The writing is good for the most part, and the voice acting is professional.\r\n\r\nThe incubi weren''t quite what I imagined they''d be - they''re aliens rather than demons, and place an unexpectedly high value on their idea of marriage. I imagined they''d be more treacherous than they ended up being, but thats ok. I didn''t expect this story to feature dealing with trauma to be one of its main themes, but again nothing wrong with that.\r\n\r\nEach incubus has their ow', 'So many things to say about this game...where do I start? I read a lot of reviews on this, both on Steam and outside before deciding to buy this (at a discount). It took me some time to finally give in as I was honestly very torn. There were a ton of positive reviews and everyone was raving about this game, so I thought "what the heck! I''ll get it." I even tried the demo, which is not long enough to give a good idea about the game.\n\nAfter almost 2 hours of play I am now saying "what the heck? Wh', 'Very Positive', 85.37, 11.98, 1.67);
INSERT INTO reviews VALUES (28797, 825310, 529, 'Dude Simulator 2\n\nHas a total of 5 trading cards.', 'Idk when or why I brought this game\nbut I do know that you shouldn''t.', 'Mixed', 51.80, 0.82, 0.83);
INSERT INTO reviews VALUES (28809, 825630, 1349, 'Man falls in love with ChatGPT. 10/10', 'Usually I''d do a longer better thought out review but this game a lot of what I find wrong with it can''t really be explained too well. I just get a feeling when I play it that its just a bit off and underdone. Can''t really say much more then that. Only 2 endings were really enjoyable and the rest just felt rushed or unsatisfying.', 'Very Positive', 94.74, 39.72, 58.02);
INSERT INTO reviews VALUES (28810, 825730, 172, 'Lovely! Works on Windows11, but the aspect ratio is off.\n\nThe best fix for Windows11 in 2025 I found..\n\n ..is from GOG forums, Tzar 1.10 GOG Windows11 Patch + CD Audio Tracks + Anthology Expansions Translated to English post. Make sure to edit the ddraw ini file, and edit line 39 (Bicubic works best for me). Make sure to also enable CD audio in game for the truly original OST blasting during gameplay.\n\n', 'Did not display correctly. Running Windows 11. Could not configure after about an hour of trying. Do not buy on Windows 11', 'Very Positive', 90.70, 17.48, 0.12);
INSERT INTO reviews VALUES (28835, 826540, 209, 'This game is basically Synth Riders 2.0 - heavily inspired by it, but on a higher level of graphics, more famous songs, better polish and UI. That''s saying a lot, because Synth Riders is already great.', 'I tried the cardio mode: Contrary to what some review says, it''s not particularly cardio intensive. Which is what I was looking for\nI tried campaign mode, it was really boring.\n\nI''ll refund, I have more fun with beat saber, and the fitbeat songs hare more of a workout than this', 'Very Positive', 89.47, 1.20, 0.33);
INSERT INTO reviews VALUES (28838, 826600, 169, 'I bought this for a dollar or two, and it was worth it at that price.  The single player turn-based mechanics were given an interesting twist in that you plan an action, then a move for each of your characters (instead of move/act) and then you and the opponents play out the action at once.   No real RNG element as weapons do a fixed damage and always hit, but there is a varied choice of weapons with different features.  That made it different enough to be interesting, and new mechanics/challeng', 'First off, I gotta say, I have no clue how this has a mostly positive rating. I''ve played 100''s of turn based tactic games, this is the first one that I can recall, where you HAVE TO attack (or use an action) before you move. I can''t even begin to tell you how awful that is, especially when you have characters who can only melee within a short distance. Enemies move out of position or they''ll attack and kill you before you can get your attack in. This also means you are left with only playing ra', 'Mixed', 69.82, 85.38, 1.32);
INSERT INTO reviews VALUES (28840, 826630, 5725, 'The game is good. Unfortunately, it was left in this state, no updates or patches for it, getting dead as I write this. The story was good but it ended very fast, in game achievements should be worked out to work the same as the ones on the steam, nothing records without a VPN set up. Overall I am giving it a 6.5/10. I had fun', 'servers abandoned without so much as an announcement and no ability for peer to peer hosted matches.  I hope King Art and Prime Matter don''t seriously expect us to buy from them again when they only supported this premium game for 4 years. plus this game being largely defunct and on sale without so much as a notice its sketchy as fuck. im not asking you to revive the servers, but either give us dedicated server software or let us play peer to peer, especially if you are still going to try and se', 'Mostly Positive', 75.37, 159.28, 40.10);
INSERT INTO reviews VALUES (28855, 827290, 397, 'Secret Little Haven is a very good game where you''re chatting and playing littles games with some friends on an old 1999 Windows interface... it''s kinda like an Emily is away game with a touch of eccentricity... It''s funny and with his low price, I highly recommend it!!! 💗💗💗', 'It could''ve been great.\n\nThe main problem with this game is the jank. Sometimes you have to click buttons several times before they do anything; the draggable area is inconsistent across windows; you can''t drag icons on the desktop or rename saved documents; the terminal emulator has no tab autocompletion and no cd or dir commands, so navigating the filesystem for puzzles is a painful experience; the reminders application can''t be closed after it is opened; characters will sometimes send the sam', 'Overwhelmingly Positive', 98.49, 19.98, 5.42);
INSERT INTO reviews VALUES (28866, 827640, 116, 'Great story. Best on steam.', 'Trash Story - Horrible "gameplay" because it''s basically a visual novel.\r\n\r\nStory is bland and predictable, but at least it gives 5000 achievements.', 'Mostly Positive', 79.31, 0.25, 0.25);
INSERT INTO reviews VALUES (28878, 828070, 301, 'I lost gallons to this!!', '2 years in and a coding decision which does not allow this game to be installed on anything other than the root drive has not been fixed or changed. Don''t buy this game.', 'Very Positive', 85.05, 31.35, 0.37);
INSERT INTO reviews VALUES (28909, 828740, 341, 'Good world-building, cute cats, rich color palette, and beautiful music = a pleasurable experience. Some of the puzzle solving was a tad complicated but overall quite do-able. I''d say it scores a solid 7/10 or so on the trusty Adventurino-scaly''O.', 'Fun in some ways - starts well and the opening screen music is rather lovely. I liked the apartment and being a cat. Then........the bit in the red light district with a load of women being leered and cheered at - YUCK! Also the puzzles are very, very, very easy - or very, very, hard. I''ll finish it but I won''t be sad to see it go.', 'Very Positive', 83.58, 8.72, 12.37);
INSERT INTO reviews VALUES (28915, 828900, 572, 'Just to preface this isn’t a story with a happy ending, but it doesn’t need one frankly. You are old, you are alone, your only knowledge of the world outside your farm are the letters from your family, the conversations with the trader, and the slow changes occurring in your environment. All of them signal that things are changing, and they’re changing for the worst. But no one has answers as to what’s happening and all you can do is slowly go about your days as you always have, until you can’t.', 'I have to admitt, it took me a few tries to get into this game. My main problem was, that the character was moving so slow. At first I was confused as to why they made the character *this* slow but you will only understand later. This *isn''t* a farming game. This game is about an old lady who has had a long life. This is essentially her last summer. Some days go by faster, some go by slower. The point of this game is, that it is pointless. As absurd it sounds, it actually makes sense within the ', 'Mostly Positive', 75.00, 4.37, 5.65);
INSERT INTO reviews VALUES (28925, 829280, 646, 'Loved every bit of it! I''m so glad some people are still making games like would be found on the SNES!', 'Allow me to cut to the chase this time. Things like graphics, music, collectibles, content etc are what you can expect when compared to other games in the genre. They’re done with care and they’re great. However, I believe that the game’s Steam page is misleading when it’s describing the gameplay and challenge. There is one mention of ‘but challenging platformer’. This is VERY underselling how challenging it is and whether it’s really a traditional platformer. It feels more like an auto-runner. ', 'Very Positive', 92.11, 6.02, 16.88);
INSERT INTO reviews VALUES (28935, 829660, 755, 'I used to have friends.. now I have enemies.', 'Its an interesting life simulation with an amusing art aesthetic, but it doesn''t really work as a board game.  There is zero interaction between the players.  It is just a race of who understands the game mechanics best, with nothing anybody does having any impact on any other player.  And the game doesn''t give enough information to make good decisions.  If you want to make a purchase, there is a little happy face symbol, and a price, but no indication of how much happiness you''re getting for yo', 'Very Positive', 92.45, 35.43, 4.08);
INSERT INTO reviews VALUES (28943, 830370, 517, 'I don''t want to compare 2 completely different beasts here, but despite the amount of polish that Temtem has, I''ve greatly enjoyed Monster Crown 10x more. It has its problems, with a little bit of bugs, but I can''t help but notice that a lot of heart and soul has been added into this game despite the problems this game is facing. The dev is crazy for even attempting to make his own Monster Crown TCG. I will be buying the sequel when it releases. Please give this game a chance. 10/10.', 'i wish i could leave a positive review, i really like the game-play but after several new game files and every one of them ending in a different save corrupting bug i just cant recommend someone spend money on it, i hope the devs focus on fixing the issues present and i can update this review someday', 'Mixed', 69.05, 8.58, 16.23);
INSERT INTO reviews VALUES (28955, 830640, 122, 'love hate relationship', 'this is the most confusing thing i have ever done no instructions or tutorial at all this is cock and ball torture', 'Very Positive', 87.70, 3170.95, 1.08);
INSERT INTO reviews VALUES (28959, 830820, 637, 'Great soundtrack, explosive gameplay, nice variety of weapons & options. \nLevel-wise = little short, but still fun.\nAchievement-wise = doable, but be prepared for hardcore mode, playing same levels to difficulty 10 (10x same missions over and over) and mortal kombat + tetris baby.', 'For twice the price of its predecessor in the series, players are given less customization, levels, and attention to detail and instead provided a slight update in graphics and item transactions such as full refunds. There is no real feeling of progression as cutscenes, as motionless yet charming as they were in the first game, have completely been omitted therefore reinforcing how arcade-like the sequel is with its short-lived levels and early difficulty spike which sets the precedent for later', 'Very Positive', 90.58, 30.93, 2.13);
INSERT INTO reviews VALUES (28962, 830980, 251, 'This is my favorite game in the world. for every new friend me and my bestie get, we make them play this game with us. its the highlight of our lives. thank you.', 'i married an asian pear and divorced the rock of my life', 'Mostly Positive', 72.11, 14.53, 5.30);
INSERT INTO reviews VALUES (28980, 831560, 871, 'Yes, I''ve played 246 hours. Yeah, that''s a lot of time for a work-every-day adult. Yups, it''s been worth it every single second. The variety of gameplay and characters is HUGE, there''s a LOT of game to be played. Plots are cheesy, fun and goody-be-good KOEI style, and that''s great when you are tired of the "I-AM-THE-DARKNESS" kind of mood. Would I recommend? HELL YEAH! But there''s not a real need to go into details. Just get it full price if you can, on sale if you can''t, but get it, play, have ', 'I know what i was  getting in, i enjoy some musous, but this one was so boring, this game relies to much on the magic system at a point that is tedius, incredible boring, you just spam magic bc is the most effective atack in game, it doesnt even matter that much what character are you using, it gets so old  in a short time, even for a musou', 'Very Positive', 87.14, 278.15, 13.57);
INSERT INTO reviews VALUES (28999, 832360, 253, 'Allright yet another game needing the ''meh'' option. At this time this game is not really worth it. It is laggy, the AI is poor and there really is not enough management options to have an actual challenge. Positive review cause this came -could- be good after a couple years of development.', 'RUN！！！！！！DO NOT BUY !!!!!!!!!!!!!!!!!!!!!! WORST GAME EVER!!!\nEvery saved game crashes within 5 hours and then becomes impossible to reopen. And just two hours after the refund window closes, it starts lagging like crazy. i even question my self if i was building too fast after each crash that caused the lag and crashes. I kept giving it chances, sunk 20 hours into this, created 4 game saves, and now none of them can be opened.', 'Mixed', 63.24, 7.18, 22.23);
INSERT INTO reviews VALUES (29006, 832500, 122, 'I’m laughing my ass off after just a few minutes! This game really brings back those old Monkey Island vibes. I already love Betty! The music is great, and the art? It’s amazing. It really stands out from the usual pixel art.\r\n\r\nThe best way to describe it is that it feels new but still familiar. The puzzles are fun and make sense, you don’t have to guess what the developers were thinking. I’m still trying to figure out the story, but it’s interesting enough to keep me hooked. I’m excited to see', 'Skip. The writers aren''t afraid to waste your time and use every chance to do so.\n\nIt drags on and on, the dialogues go on forever without going anywhere, there are too many subplots that lead nowhere, the puzzles are decent until they go all moon-logic, the ending is abrupt and unsatisfying. There are choices to make, apparently, but it''s hard to decypher what the choices are and what effect they have. To top if off, the characters are very unlikeable, to the point that the playable characters ', 'Very Positive', 84.43, 12.47, 24.45);
INSERT INTO reviews VALUES (29022, 833040, 1071, 'this game sucks ignore my profile', 'Not good Homestuck content, and not even a good visual novel. I''m a total nerd for this world and i''ve never been more uninterested in what its trying to say. save your money and just watch the chatlogs on youtube, i promise you''re not missing anything.\nThanks Hussie :/', 'Very Positive', 93.74, 0.13, 2.20);
INSERT INTO reviews VALUES (29025, 833090, 585, 'Please finish your game :(  Bought this 5 years ago by this point and all ive got is a dead abandoned game', 'Dead game. No updates in years. Still early access.', 'Mostly Positive', 79.49, 0.52, 1.77);
INSERT INTO reviews VALUES (29027, 833140, 134, 'I first played Supaplex in the early 1990s on an old Atari computer I believe, might be wrong, it was 30 years ago. Anyway myself and my housemates played it always late into the evening and early hours in the morning, especially when we got stuck on a level and had to repeat the whole thing. This version has a save and load function, so you can start back where you failed, which is a bonus for an old player. Enjoy, some games just stick in your head, this is definitely one of those, for me.', 'It was a pleasure to see one of my absolute childhood favourites on Steam. I remember when I played Supaplex as a child, and I have many great moments with this game, which are both entertaining and in many cases extremely difficult.\nBut I can''t recommend this remake edition. It simply don''t seem to have the love for the original game, and I will even call this remake for lazy, and for several reasons:\n- Many of the animations from the original game are missing\n- The pleasant music and soundeffe', 'Very Positive', 94.03, 219.88, 0.98);
INSERT INTO reviews VALUES (29036, 833360, 1801, 'fantastic game.  Keeps me wanting more.  Very simple, but can be as in depth as you want it to be.  Only problem is it seems like development is done for now.  There is still plenty of content for what is available right now.', 'Fun for combat and ship design, that''s it.\nIf that is your jam, pick up this game cheap, imo, b/c it''s not worth $25.\n\nMy main gripe after ~115 hrs, there is not enough story content. All that there really is for the player to do is grind for mats to experience ship design or combat.', 'Very Positive', 90.06, 120.23, 117.23);
INSERT INTO reviews VALUES (29077, 834280, 421, 'Go fishing IRL. 0 fish. Come home and play this game. 1 fish. 10/10', 'DO NOT SIGN UP FOR THIS THIRD PARTY WEBSITE. Dovetail Games sells your information, its in their terms of service. I''ve gotten so many fishing related advertisements online since downloading this game. I''m getting emails about signing up for services I haven''t. Please stay away, this is basically spyware.', 'Very Positive', 80.52, 58.33, 0.40);
INSERT INTO reviews VALUES (29088, 834740, 1233, 'If into the likes of Warcraft and Starcraft - then Circle Empire is a fast paced and fun alternative. This one''s cutely cartoonish fresher take on RTS with a non-existent learning curve. Probably also inspires those usually aren''t into real time strategies. Games don''t often take much time either; the game fits to be whooshed away during lunch breaks at work. \n\nNative Linux support is a plus from these wonderful fellow Estonians. One thing lacking though; Circle Empires doesn''t have cloud saves!', 'There is very little variety and they sell variety that should be in the standard game with dlc.\n\nLack of much variety and no different game modes will make you get bored of this game quickly. They also sell the Multiplayer mode, which is the only different and possibly fun mode, as a different game (Circle Empires Rivals).\n\nInstead, I thought of completing all the achievements. out of 82 achievements, 2 achievements got bugged and didn''t give me the achievement even though I did what I was supp', 'Very Positive', 88.73, 3.67, 37.17);
INSERT INTO reviews VALUES (29090, 834760, 126, 'Great retro game .  All the fun without some of the needless frills.  I can''t see 3d games without a headache so when I find a FUN game with lots of challenges and levels I jump on it.', 'The new game (Robot Wants Justice) features incredibly brilliant design, such as invisible enemies that insta-kill you if you touch them, also you get to experience being the wimpiest robot in space, each one of your attacks having the approximate effectiveness of a fly farting in the wind.', 'Very Positive', 86.51, 54.07, 7.75);
INSERT INTO reviews VALUES (29094, 834910, 19769, 'Abandoned or not this game has so much to offer. It beats Sea of Thieves in the fact that i get to make my own ship, have my own port and city. Plus you can have creatures that help you in combat or transit. This game beats Skull & Bones in the fact that its an actual pirate game where you can walk on land and hold a sword, you know....everything a pirate wants to do. \r\n\r\nThis game could use 10 lbs of polish and it would stand out as one of the best pirate games there is, unfortunately our Snail', 'when a DEV abandons an EA game steam should force the DEVS to issue full refunds to every person that spent any type of money on the game, these EA games are getting out of control with being abandoned', 'Mixed', 47.16, 26.98, 212.42);
INSERT INTO reviews VALUES (29100, 835430, 432, 'The second game is a 10/10 badass, admittedly headache-inducing game that I beat without using a guide;\n\nWhich is not something I think fucking ANYONE can say about the first bloody game.', 'La Mulana 2 is not better than La mulana 1. The first half of La Mulana 2 is better than the first game, but the second half is so much worst. The easiest example is   that the final dungeon of this game is the optional troll dungeon of the first game . That part alone is responsible for nearly 20% of people who killed all the guardians and reach the final challenge to then quit the game. It''s absurd that such a huge percent of people who made it 35 hours+ into game will all quit all because of ', 'Very Positive', 87.50, 64.62, 37.82);
INSERT INTO reviews VALUES (29108, 835570, 268, 'เกมส์เหี้ยนี้มันนนน ต้องใช้เวลาเล่นชิบหายถ้าจะทำทุกตัว \nแต่ถ้ามีเงิน เรื่องนี้จะเป็นส่วนท้ายที่คุณจะมีปัญหาด้วย', 'The game is currently unbalanced and not suitable for new players. Even returning players struggle because the grind is too excessive for the overpowered units, which have very few viable counters. This makes the gameplay frustrating and discouraging rather than enjoyable.', 'Mostly Positive', 70.90, 522.37, 212.82);
INSERT INTO reviews VALUES (29124, 835960, 7635, 'The Talos Principle 2 is to The Talos Principle 1 what Portal 2 is to Portal 1', 'The level design is magnificent, the puzzles are good (but never quite reach TTP1 levels of challenge) but the narrative is tedious, the non-puzzle gameplay is tedious, and the philosophy is eyerollingly sophomoric.\n\nTTP2 asks the question "can we be trusted with progress, technology, and knowledge?" and largely supports a single thesis that "progress is unilaterally good". Many characters and in-game text support this thesis, with variations on the sentiment that humility, or acting humbly, or ', 'Overwhelmingly Positive', 95.14, 44.62, 18.17);
INSERT INTO reviews VALUES (29139, 836450, 552, 'I have genuinely never encountered anything else that so well translates the experience of being a terrified transbian living in the soon-to-be-fascist united states. cannot recommend enough to anyone who loves women and hates the government', 'I don''t typically leave reviews, much less negative ones, but I just had to sleep off a throbbing headache, so I feel the need to warn potential buyers that this game is heavy on the eye-and-ear strain. The music ranges from ambient and pleasant to downright hell on the ears. One of the protagonists has this super red filter over her UI, which serves no real purpose other than to make the game harder to look at. HWBM also lacks a lot of basic features I expect out of visual novels, such as skipp', 'Very Positive', 92.93, 9.12, 5.80);
INSERT INTO reviews VALUES (29174, 837350, 110, 'snapback might be the most fun i''ve ever had playing a non-smash platform fighter', 'I would''ve liked this game if it weren''t for the final boss of arcade mode, I genuinely hope whoever came up with that fight gets their dick stuck in an active blender', 'Overwhelmingly Positive', 98.18, 6.37, 0.48);
INSERT INTO reviews VALUES (29176, 837400, 128, 'Edit 7/30/19 I had made a post in the discussions requesting hotseat gameplay, and it has finally come to fruition, these are devs that truly listen to the players and adapt the game as they want and as the players want. Bravo Fated Kingdom!\n\nThere is public matchmaking now so disregard those people that have not updated there reviews, having said that, I have not seen anyone on the public lobby so I have yet to play the game.', 'can''t use unless you know other people that own it, there is no player matching you have to manually join other games or \nhave others manually join yours. However there is also no list of servers anywhere i can find.', 'Mostly Positive', 78.91, 0.20, 0.15);
INSERT INTO reviews VALUES (29179, 837460, 122, 'ayo? a good game', 'Game went from enjoyably challenging, (even with turning on the "easy mode" features) to outrageously difficult and frustrating... So, very poor challenge balancing...', 'Very Positive', 81.15, 0.22, 22.20);
INSERT INTO reviews VALUES (29180, 837470, 9062, 'It''s kinda like low level terrorist simulator but with more replay value.', 'Clunky controls, and the puzzles feel more like chores than something fun. Not my type of game.', 'Overwhelmingly Positive', 96.17, 5.85, 0.70);
INSERT INTO reviews VALUES (29182, 837510, 208, 'Highly recommended.\r\nThis engine will take a couple of weeks for you to learn, and then you can do basically whatever you want with it in 2d gaming.\r\nI have massive projects in this engine, and have experienced no real issues. A few crashes in  the years it''s been out, and nothing else.\r\nI''m posting this review after reading a lot of negative reviews from people who haven''t spent but 20 hours with it.\r\nIt''s a game engine...20 hours makes you a tourist.\r\nI highly recommend this if you want to mak', 'It doesn''t work. It won''t start a project; it just never loads and crashes every time.', 'Mixed', 62.02, 2841.83, 0.22);
INSERT INTO reviews VALUES (29185, 837590, 167, 'A short and fun game, that remind the first Call of Duty and Medal of Honor games. The story is weak, but the oldschool gameplay is still enjoyable. I''d still advise you to pick it up when it''s on the $1 discount, as it''s still a very short game.', 'This game is from 2011, according to Steam, but it feels like it should have come out in 2001. Operation Thunderstorm is a horribly janky WW2 shooter that seems like a one-man developed game. It''s supposedly very short; I was determined to beat it, but I had to give up after the second mission. The shooting and destructible environments feel surprisingly good, but everything else is awful: movement, locations, weapon variety, enemies, story, and voice acting are bottom of the barrel. It wasn''t e', 'Very Positive', 80.24, 1.63, 1.17);
INSERT INTO reviews VALUES (29193, 837880, 216, 'I paid 2$ for this game and played it for 33 hours.\r\n\r\nThere''s a campaign and there''s multiplayer and that''s about it, but the simplicity of the game is what makes it so much. It is definitely not worth the full 20$ it costs in my opinion, but I would be happy paying 10$ for it.\r\n\r\nDefinitely play only if you have friends to play it with, as Online mode is pretty dead (and takes a looong time to connect). And if you do have the friends, hey! Don''t be cheap! Buy copies for all of them, it can be ', 'Great game, unfortunately there’s no more players. So it’s sadly a dead game.', 'Very Positive', 89.81, 33.67, 2.35);
INSERT INTO reviews VALUES (29212, 838310, 1881, 'Pretty fun classic Castlevania type game, but much less punishing than the NES Castlevania games. I usually prefer the Symphony of the Night and onward style of Castlevania but I still enjoyed this one more than I thought I would! Played through it several times.', 'Not sure what to think about it, art and music are pretty cool-ish, gameplay is mid at best.\nBut, really, it''s pretty hard to defend an hour long game. I know it is pretty replayable, but honestly, I don''t wanna to.\nBosses are good and that''s pretty much it, not my type\nThe game is way too easy, honestly if a neutral option existed that will be my review.\n\n\nTL DR: meh, not bad, not good, 1 hour game', 'Very Positive', 92.24, 6.00, 1.40);
INSERT INTO reviews VALUES (29213, 838330, 129, 'This game literally need an advertisement to populate.\nGame is decent and fun, not the best mmo but if you like grinding then this game is for you.', 'game is sold on Australian Steam market... no oceanic server and game has a delay from lag connecting to US servers.. refunding and uninstalling.', 'Mixed', 62.79, 254.42, 0.23);
INSERT INTO reviews VALUES (29215, 838350, 686, 'It''s a great game, one of the best cultivation games. The downside is that this game has not had the English Language (yet, idk if the dev intend to do it). It has the Eng Translation mod from the discord server tho but there are lots of limitation of it.\r\nThe game is good if you can handle the rough translation. For me, I would wait for another 5 years when the game has properly translated lol.', '6 years in early access\nstill no official english translation\nblocks cheat engine\nwhy did I even bother with this game :D', 'Mostly Positive', 75.95, 567.37, 3.08);
INSERT INTO reviews VALUES (29217, 838380, 1581, 'Not enough DLC''s. Maybe another 400 will suffice.', 'Yeah, I''m done with KOEI TECMO, their greed ruined a once great Beat ''em up series. Not even the Deluxe Edition comes with all characters.', 'Mostly Positive', 72.80, 35.70, 0.57);
INSERT INTO reviews VALUES (29225, 838630, 759, 'Not a bad game, but it''s pretty much just crabs all the way through. You’re mainly grinding to make more money, but at least you can AFK and let your crew handle most of the tasks.', 'Do Not pay attention to positive reviews, they are just simps.  This game is horrible and abandoned.  I Started playing this when it was supported years ago and have only managed to stomach 20 hours because I really wanted a game like this to work and be good.  there is no progression its a buggy mess that will never get fixed (it truly is abandoded with the last update being years ago its even been through mulitple devs).  I am more upset with the simps that score this positive than the devs at', 'Mixed', 50.46, 11.90, 20.27);
INSERT INTO reviews VALUES (29254, 839310, 796, 'voices of the void', 'Signal Simulator had its moment several years ago, but its moment is long gone. The game stopped getting updates, and as it is now, it''s just kinda frustrating to get into.\r\n\r\nIf you want a game that''s like this but still supported, you''ll want to look at Voices of the Void, a game that took heavy inspiration from this game, and implemented in a much nicer way.\r\n\r\nThat''s not to discredit this game, though. This game is fun and creepy, but there isn''t too much to it.\r\n\r\nSignal Simulator walked so', 'Mostly Positive', 79.65, 9.88, 3.57);
INSERT INTO reviews VALUES (29262, 839450, 194, 'This game should serve as a standard of otome games. There are 7 separate routes with just enough meaningful choices, awesome visuals and soundscape. Naturally, the story is all we want and it''s there - layered mystery, romance, fun. The only concern is crashing for an unknown reason, so i recommend to run it windowed and save every time there''s a choice branching. Other than that, 7''sCarlet is an absolute must have for otome lovers', '我全成就了但是总的来说我觉得这个游戏不值他的价钱。有几个原因\r\n1. 最影响游戏体验的是他总是卡退，我是win11系统，不得不玩五分钟就村一存档，很麻烦。\r\n2. 恋爱写的不够心动。刚开始日野线会觉得竹马很美好。然后伊空线竟然是天降竹马，可能还会有点惊喜。但是到后面，所有男主都是小时候就认识女主，会让人觉得复制粘贴，很无聊。\r\n3. 馆主的人物塑造对我来说比较难以接受。我明白可能馆主想写成傲娇，但是他已经不是傲娇而是非常不尊重女主了。“在这里我所说的一切都是绝对的，接受不了的话就滚”类似的话。还有馆主父亲“你已经驯服这个女人了吗”这种话，让我感到很不适。\r\n4. 女主的塑造我个人也很不喜欢，太弱太自卑了。每次遇到危险都是无法自救，然后最后选择闭上眼睛放弃抵抗，每次都是这样，等男主来救。就感觉太弱了，甚至有点蠢了。而且经常会说 ”像我这种人，怎么能够“ 这类话，让人觉得无法带入。\r\n\r\n总的来说我觉得是可以拿来消磨时间的游戏，但是绝对称不上是什么佳作。而且如果不是视觉小说节购入的话，我可能真的会考虑退款。', 'Mostly Positive', 76.29, 32.57, 21.12);
INSERT INTO reviews VALUES (29270, 839630, 235, 'Very fun and very challenging to figure out game play, Little current youtube info but enough to get started and 242 hrs and i''m just now building structures,  A bit frustrating but then i''m 71 so takes me a bit to remember not to poke bears with wood spears. Best survival game I ever played.', 'Screw this game. I tried to build a ship, which requires so much work, running all over the island hundreds of times. Then, one axe hit on the damn ship yard destroyed it all! Over 50 hours gathering, crafting nails, planks, plates, etc., gone! Play WURM instead!', 'Mixed', 55.74, 315.55, 122.87);
INSERT INTO reviews VALUES (29276, 839770, 2673, 'In many ways, Phoenix Point is inferior to XCOM-2. There is questionable gameplay balance, worse character customization, and just generally less of the magic that makes XCOM-2 so great.\n\nBut I find myself returning to Phoenix Point far more often than XCOM-2 for a few reasons: the factions, the flexibility, and the larger scale. There are so many great moments of decision making that make you feel like you are actually strategizing a war against an enemy. Do you build bases near your allies to ', 'This game is so close to being good, but instead, it just winds up being frustrating. There''s SO SO MANY good ideas here, but the game falls apart in the balancing and structure of engagements. Every encounter has the same enemies with a substitute here and there, but after a certain point in the game, it always has this one enemy that you HAVE to kill as soon as possible because it calls in reinforcements every turn for a fourth of its action economy, it also reanimates fallen allies in an aoe ', 'Mostly Positive', 71.31, 227.85, 69.52);
INSERT INTO reviews VALUES (29279, 839870, 377, 'Sort, sort, sort.  I love to arbitrarily sort.  However, I am extraordinarily slow and bad at games when there''s a timer element because my brain stops working as soon as time pressure is applied.  So I don''t play this one because it stresses me out - I never seem to have enough time to sort and arrange the new items before the customer window opens, and things get messier and messier, and it''s harder and harder to keep up, and pretty soon it''s not a game anymore but it''s my life.  Because for m', 'Not engaging enough minute to minute to get me invested into the warehouse management.  I can see why people would like it, but slow movement and some weird controls have just a little too much friction for me.  Being judged on time for a relaxing game is also not my favorite.', 'Overwhelmingly Positive', 96.29, 2.62, 0.17);
INSERT INTO reviews VALUES (29282, 839930, 124, 'Here in my car\nI feel safest of all\nI can lock all my doors\nIt''s the only way to live in cars.\n', 'game for gringos only... not very sigma\r\n:<', 'Mixed', 65.32, 0.38, 1.38);
INSERT INTO reviews VALUES (29286, 840010, 1585, 'I have more hours in this than Baldurs Gate 3', 'Cute and fun to play with others, but also Very buggy and a generally poor multiplayer experience. Preferably don''t buy for full price, it''s definitely not worth $20 with how it controls, but it''d still be pretty fun if you got it at a discount. Try to not think about the mouse movements too hard. If you''re looking to decorate your house, godspeed.', 'Very Positive', 90.54, 831.10, 8.48);
INSERT INTO reviews VALUES (29294, 840140, 164, 'Can anyone help me how to get on character creation? Its all in chinese and I can´t even log in the game. Very frustrated.', 'Scam', 'Mostly Negative', 34.15, 1.93, 6.45);
INSERT INTO reviews VALUES (29298, 840210, 346, 'Let''s make one thing clear. Arkham Horror: Mother''s Embrace is not the digital version of the famous board game, nor was it much beloved card game.\r\n\r\nArkham Horror: Mother''s Embrace is more in spirit with JRPG than TTRPG. Was the game good? No, it is not as good as it should have been, but it could be way worst than what we got.\r\n\r\nWhat you love/hate about Arkham Horror is here. The colorful character roster, the Sanity check, the Mythos penalties and so on. The graphic is decent, the soundtrac', 'The game play is reminescent of the old Sierra games. Limited text bases choices requiring you to do what the devs thought was the right answer. I find it clunky. In the late 1980''s, it would have been acceptable tech. Not now. The Developer Lucky Hammers closed in 2019.', 'Mixed', 60.12, 4.20, 3.30);
INSERT INTO reviews VALUES (29305, 840390, 227, 'While it doesn''t have the charm of the original, it is still a decent game.  I did find it more enjoyable after I turned off the voice for VAL.', 'This game is broken and a blatant injustice to it''s predecessor.\r\nThe AI pathfinder for your combat units and even the alien visitors is busted.\r\nThe audio driver is broken and has to be manually restarted by pulling up the Steam overlay or the audio menu.\r\n', 'Mixed', 49.78, 7.93, 20.70);
INSERT INTO reviews VALUES (29319, 840720, 521, 'This game is awful. Legitimately terrible game. That being said, I love it. For some reason I can''t put it down and it''s one of my favorites. I played it originally on PS4 and it was the first game I ever tried to Platinum. I beat it and honestly didn''t want to stop playing so I did new game plus as well. Hoping to do the same on PC as well haha.', 'I DO NOT WANT TO PLAY AS STUPID KIRTO!!!!!!!!!!', 'Mostly Positive', 78.69, 41.83, 1.60);
INSERT INTO reviews VALUES (29322, 840800, 2932, 'Sell it to a Dev that will finish the damn game, this game is special and don''t need to be thrown away!', 'More early access alpha theft. Game hasn''t updated since 2020... Steam really needs to implement some type of system that tracks all "alpha" release games and if they haven''t been updated in a certain amount of time either remove them from the sales list or make the game $1 until it updates.', 'Mixed', 59.00, 28.15, 107.50);
INSERT INTO reviews VALUES (29332, 840930, 145, 'Bing Bong XL is cool, i liked it.\n\nThe game makes fun and the music is nice!\n\nFor some people it may be difficult, you will need some tries to get into the game.', 'This is the worst game in the XL collection. It really doesn''t have much to do with skill because the only control is slowing the player icon in a vertical lane to avoid object impacts. Another lane to jump horizontally or lives would make this a much less frustrating experience. It''s basically just 60 sec runs over and over until you get lucky with the object pattern and good power ups. Sometimes the objects will be reasonably spaced and other times you''ll have blue and orange rectangles stacke', 'Very Positive', 87.59, 1.62, 4.30);
INSERT INTO reviews VALUES (29355, 841770, 767, 'It''s like Pokemon but with fantasy creatures. Lots of customization, nice QoL aspects and I just designed a monster to hit like 20 times by casting 1 spell, that''s pretty dope.', 'Went into this really hoping to like it. But the dialogue is awful. It reads like edgy teen fan-fiction and I just couldn''t get past that. Refunded.', 'Very Positive', 94.39, 23.98, 0.25);
INSERT INTO reviews VALUES (29366, 842100, 1210, 'https://steamcommunity.com/sharedfiles/filedetails/?id=2598186018\nhttps://steamcommunity.com/sharedfiles/filedetails/?id=2571154216\nhttps://steamcommunity.com/sharedfiles/filedetails/?id=2557787406', '\nDaymare: 1998 is a third person survival horror game.\nIt feels very much like early Resident Evil, but the gameplay is clunky, buggy, and despite that, it has a good vibe and atmosphere.\nCombat gets repetitive quickly since there are only 2–3 enemy types, and the story feels unnecessarily dragged out.\nIf you''re a Resident Evil fan, it might be worth a try, you could enjoy parts of it (I personally didn’t).\n4.5/10', 'Mixed', 67.69, 15.78, 7.77);
INSERT INTO reviews VALUES (29393, 842780, 672, 'As a veteran of Battleshipcraft and Warshipcraft I have had a long period of where I wanted a more indepth game like this. Well when I had seen this I was hesitant at first but then I spent a naval deployment getting the initial hang of things and soon after than I learned Carrier were coming to the game and I got even more into it. Since then I want to think I got really good at it and have made several ships on the workshop. In all I appreciate what the devs have done for the genre when games ', 'Played this for the first time in a couple of years and I still regret paying for it. The game now has a tutorial (who knows how long that took to get added) but it simply stops working halfway through the second chapter. \n\nWhile I respect the dev''s choice to add lots of shiny cool-looking new features (probably to placate the deranged obsessives who seem to flock to games like this), what the game really needs in my view is improved/streamlined hull design. The current system is excruciating to', 'Very Positive', 91.22, 162.97, 11.65);
INSERT INTO reviews VALUES (29397, 842910, 614, 'bruh this game is too goddamn relatable it gets even more viseceral when my deadnames initials are also "J.J."\r\n\r\non a more serious note its a relatively short but easy play even if ur horrible at platformers like me there typically checkpoints close enough and I only ever needed a guide for collectibles and 2 puzzles', 'This game suffers from laughably poor voice acting that sounds like they asked the actors to read their scripts out loud right after handing it to them for the first time. To make matters worse, the actual dialogue reads like a conversation someone who''s never actually talked to real people before had in their own head, with the text message dialogue being peak ''hello fellow kids''. The gameplay is not much better, either, with the difficulty ranging from easy to the point of boring, to brutally ', 'Very Positive', 89.90, 8.82, 7.20);
INSERT INTO reviews VALUES (29410, 843200, 1013, 'Behemoth''s weakest title to date (at least from the Castle Crasher days onwards). The game feels like it lacks a coherent difficulty curve and felt incredibly repetitive even for its short length. It does maintain the signature Behemoth charm and humour, yet falls flat on its face in the gameplay. Compared to previous titles it felt like a ''safe'' ''filler'' game.', 'The gameplay has taken such a downgrade compared to the first game. All missions are repetitive and the enemy encounter design is just bland AoE spam that doesn''t feel fun or rewarding. The UI is cluttered with information and consistently blocks your view with bright pop-ups and flashy indicators that are just unnecessary. It''s a shame that the game didn''t come close to my expectations, I was really excited to play this game.', 'Very Positive', 87.56, 8.60, 1.30);
INSERT INTO reviews VALUES (29413, 843260, 911, '10 year old me watched my Dad play The Bard''s Tale in the late 80s, I didn''t understand the appeal at the time. 44 year old me understands it big time and is loving every minute of it. My Dad passed away in 2015, I''m hoping to finish this trilogy for the both of us.', 'This game was probably way more fun with friends around a PC/console to make characters with but having no party members and no banter and nothing to break up the grinding and finding makes the game a slog.', 'Overwhelmingly Positive', 96.05, 16.60, 1.68);
INSERT INTO reviews VALUES (29419, 843380, 3101, 'after 900+ hours in, I can safely say that its an alright game yeah. go play it. its fun!', 'idk why i have this game i have no memory of playgin it', 'Overwhelmingly Positive', 95.94, 924.48, 11.10);
INSERT INTO reviews VALUES (29420, 843390, 2013, 'Up there with half-life alyx, a bit less production value, and a bit more humor, buy it, support the dev, enjoy..', 'Played for 10mins. Realised it''s another woke infested DEI game. Your character is a black female with no option to change sex or race. Totally ruins any immersion in the game.\n\nApart from that in the intro sequence I could barely understand the voice actors, one sounded like kermit the frog.', 'Overwhelmingly Positive', 96.08, 26.12, 0.12);
INSERT INTO reviews VALUES (29423, 843430, 102, 'Pivot XL is a fantastic game with addictive gameplay, vibrant graphics, and challenging levels that keep me entertained for hours.', 'I uh, I really didn''t like this one unfortunately. The player can change size dynamically, and is often too big compared to the other shapes which means there would be times where I thought I''d be fine but then just be too big. It doesn''t help that the hitbox being perfect and the player being a sphere, means that the hitbox seems smaller than it really is. It really doesn''t help that the trail is smaller than the hitbox as well. The transitions in the menus are slow, and points are slow to get.', 'Very Positive', 93.14, 4.50, 1.10);
INSERT INTO reviews VALUES (29424, 843440, 111, 'Fun, polished little arcade game well worth the $0.49 on sale.', 'After a few minutes, the game feels more annoying than fun. Object spawns escalate too quickly and support items are too few/far in between. The screen arena feels too small.', 'Very Positive', 92.79, 1.08, 3.20);
INSERT INTO reviews VALUES (29456, 844040, 132, 'Very impressed with this one!\nEnough options to tailer it to your liking and make it run well, flying feels good and overall its just a solid package!\nHard to believe its made by the same developers as Gun Club VR since that one was missing even basic stuff like Antialiasing.\n\nRecommended - specialy on sale a good purchase!', 'The lady that keeps talking when I am trying to change modes can just STFU, I know what free flight is, dont need to talk for 2 minutes about it and showing me what boost is when it forces you into a tutorial at the start explaining it, why does it need to tell you twice.\r\n\r\nPhysics are apparently non existent, as you can fly straight up and keep going, taking a very long time to slow down, and when you stall its not even a proper stall you can keep aiming straight up and it does not force you d', 'Very Positive', 81.06, 0.25, 0.25);
INSERT INTO reviews VALUES (29466, 844260, 357, '  There is nothing really new here, but I had a lot of fun finishing this game.  the old school gameplay, the humor, and the art style are all positives.  if you liked the old gta1+2 games you will like this.  "Grand theft Horse" is a perfect description.  8/10\n', 'I adore the game, its great. I have one HUGE problem though, when you go to close the game you get an In Game POPUP ADVERTISEMENT. Listen.. I purchased your game, not your advertisements. I already have most of your games, I do not need to be reminded that "Hey you could own these others titles from us, just click here!!". This is a boundary crossed that honestly, shows that you as a dev/publisher or both you are clearly Willing to cross lines to make money. This is the last dollar you''ll see fr', 'Very Positive', 80.39, 28.75, 8.40);
INSERT INTO reviews VALUES (29467, 844330, 234, 'this game is everything ive ever asked for. it has goats...it has men...the only downside? a cliffhanger. thats right, a cliffhanger. When i first saw this ending i was stoked to see another goat and maybe another man however it is extremely hard to say this but the game...has been most likely abandoned...we will never see another incarnation of goatman again...all my goats take a bow in silence for our goat..man', 'No updates for many years, this is one of these early access games where the studio just want quick money and then drop it. Stay away', 'Mixed', 68.38, 1.18, 2.78);
INSERT INTO reviews VALUES (29471, 844420, 107, 'It''s a port from smartphons.\nUsually, I don''t really like turn-based games, but some of them are fun enough like this one.\nAlthough really NOT polished in various ways (e.g., weird text mistypes, multiple bugs but not game-breaking , etc.), this game is very enjoyable.\n\nHowever, IMO it is overpriced for what you get so I''d wait for a sale of 50% or higher!\n\nIt has A LOT of potential, I wish it could have been like HoMM, in terms of story and length as well.', 'boring as hell.\nquality is like school project.', 'Mostly Positive', 78.50, 22.85, 0.10);
INSERT INTO reviews VALUES (29478, 844590, 3814, 'Hypnospace Outlaw could have so easily been a cheap trick. It could''ve secretly been a horror game the whole time. It could have blindsided us with a view of the internet so desolate, so cynical that its genuine hope is for us to log off forever. It did not do these things. Instead, shockingly and beautifully, it represents a love letter to the internet, as it once was, and as it can be, given the right people. The internet is not an organism malicious in nature. It is an invention that boldly a', 'Great concept, great art direction, TERRIBLE execution in gameplay.\n\nThis is not a game, it''s a visual novel masquerading as a game.\n\nYou do nothing in this game besides point and click at things the game specifically instructs you to point and click at. The puzzles are glorified fetch quests. "Click here and maybe there''s a thing on this other page you can click on. Do this and type that code in." \n\nPASS!', 'Overwhelmingly Positive', 96.88, 10.07, 4.80);
INSERT INTO reviews VALUES (29481, 844660, 577, 'trans girl? yuri? trans girl yuri?! peak', 'I wanted to like this so much but I just couldn''t. It felt really flat and superficial and a lot of times cringe. The art and music was pretty at least.', 'Overwhelmingly Positive', 97.05, 7.90, 2.72);
INSERT INTO reviews VALUES (29487, 844850, 276, 'Dead cells with anime girls', 'Erza''s Trial is a ok game but very unpolished. you can stun lock most enemies just by attacking them and this makes most early levels feels easy so to make it harder later levels stack enemies. this makes enemies with ranged or knockdown moves deadly because they are often behind others so you need to get near these enemies and take them out first but when theres more than 1 of these you''ll often take damage. when you hit the fire stage it''s full of enemies that you can not stop their attacks bu', 'Mixed', 60.51, 0.97, 4.85);
INSERT INTO reviews VALUES (29494, 844930, 691, 'Fox Hime Zero is a heartfelt visual novel that tells a touching story filled with romance, mysticism, and beautiful art. The character designs are stunning, and the backgrounds are vibrant, creating an immersive world that’s a joy to explore. The music complements the mood perfectly, enhancing the emotional beats of the story.\n\nOn the downside, the gameplay is limited to making a few choices, which may not appeal to players looking for more interactivity. Additionally, the pacing can feel slow a', 'Yet another bad English translation. Fox Hime also had an awful translation.', 'Very Positive', 94.50, 4.63, 0.82);
INSERT INTO reviews VALUES (29499, 844980, 196, 'I got the ending where you become a dictator and stay in office after your second term, but you kill yourself 50 days later anyways.\r\n\r\nGreat game 9/10', 'This game is a joke. I thought it was a presidential simulator, but it is a bad comedic story telling game.\nThe average event in the game is like:\n"President, the Prime Minister of Canada said you aren''t cool. How do we respond?"\nOption 1: Nuke Canada and burn Ottawa\nOption 2: Cry under my desk\n\nThere is no moderates in this game, there is no politics or strategy.', 'Mixed', 63.27, 10.88, 3.57);
INSERT INTO reviews VALUES (29541, 845880, 231, 'Stupid little oni goblin brat. Correction needed.', 'This is bollocks, like straight up bollocks. It just fuckign sucks\nJust don''t bother, even on sale, it''s not worth it. It''s crap', 'Very Positive', 91.77, 12.75, 1.32);
INSERT INTO reviews VALUES (29542, 845890, 1071, 'This is an incredibly good example of why you should MARKET YOUR FUCKING GAME! when playing this you can FEEL the love and  care put into this masterpiece. From the charming characters you get to paint yourself, to the pages of lore and audio dramas, to the intuitive way the game controls. Everything within the game indicates a level of care most games don''t get these days, especially from larger developers. Unfortunately none of that means anything when no one even realizes the game exists, and', 'WARNING: You may be tempted to spend hours painting your characters, looking forward to playing them, but it will all be a waste of time and money. You can''t use them in single player mode, and you will probably rarely find anyone to play multi-player. I tried to get a refund but I spent too much time painting the pieces and didn''t qualify for my money back. I will gladly change my review to a positive if the devs fix this problem (what were they thinking?!?) but I''m not holding my breath as it ', 'Very Positive', 86.18, 41.97, 7.80);
INSERT INTO reviews VALUES (29551, 846030, 2051, 'If you''re like me you have a million games and don''t know what to play because it either takes too much time or its not as in-depth as you wish it were. You''re constantly stuck looking for a game that is in-depth enough but not so much you need to learn something and can take up as much or as little time as you decide. This is a game that fits that bill. and its CHEAP. So no need to pirate it.\n\nTry it for 20 minutes. If i just described you you''ll have 40 hours in this game in 3 weeks.', 'A good and very promising game about asteroid mining, it has all the required basics: A beautiful and immersive interface that really makes you feel like you are operating a huge mining ship; A quite wide arsenal of different tools and modules for your ship; Quirky but absolutely realistic ship controls. It really feels like a nice, thoroughly made simulator, and if you enjoy the meditative and monotonous process of excavating precious metals from icy asteroids, you will have some good time. \n\nB', 'Very Positive', 94.34, 44.78, 14.15);
INSERT INTO reviews VALUES (29555, 846110, 472, 'Great game. Lets you do a little bit of everything and play an everyday life with convos with other characters and even the possibility to date others. Overall good experience, have played it through 3 times now and still enjoying it.', 'The cooperative mode is not well thought out and poorly configured, it is practically unplayable and exists simply for show.', 'Very Positive', 88.77, 145.17, 0.82);
INSERT INTO reviews VALUES (29566, 846470, 1704, 'More developers need to approach VR this way. Classic platformer gameplay re-imagined from an enhanced and immersive perspective, instead of derivative low-effort first-person VR slop.', 'The game is beautiful. But the is way too much fighting with bugs of monsters. It would be wonderful if there was a version with not fighting, with only the puzzles.', 'Very Positive', 94.84, 6.98, 23.37);
INSERT INTO reviews VALUES (29575, 846770, 4556, 'There are so many things I like about Dysmantle that it''s hard to put into words what exactly it is that makes me get lost in it for hours at a time. I''ll try anyway:\r\n\r\nThe hook is pretty much instant. Upgrades keep the carrot dangling nicely. The destruction is satisfying. It''s calming. The moments of intensity can mostly be planned well ahead. Moments of frustration are few and far between. It''s huge to the point of being almost a little overwhelming because there is so much to do. I keep get', 'Game isn''t bad if purchased on sale. Haven''t had issues with bugs and the like, except for when you are holding down the camera rotate key while moving your attacks will only go downward which can put you in a tight spot. However, it utilizes popups to push the dlc and doesn''t prevent you from crafting dlc items when you don''t have the dlc. And if you do happen to craft a dlc item, your save game is now inaccessible unless you buy the dlc required for that item. I happened to make a food that is', 'Very Positive', 90.91, 96.07, 10.27);
INSERT INTO reviews VALUES (29577, 846800, 492, 'good game played for 250 hours, you get to bet up homeless men', 'Bought the game from misleading descriptions of being able to hire staffs, can only play with A.I. through singleplayer. It''s basically a knockoff version of Overcooked and unless you have all 4 friends, it''s not going to be fun.', 'Very Positive', 90.65, 249.72, 0.55);
INSERT INTO reviews VALUES (29581, 846870, 515, 'Yooka-Laylee and the Impossible Lair follows on from its first game in different formats and dimensions where we must once again defeat the fearsome Captain B. At this point we have the option of saving the 48 bees lost in the 20 chapters plus the open world outside them to serve as a shield during this long and arduous battle or going it alone with the determination that despite there being no save points or tonics to save you, you will persist until the end. More challenging than its predecess', 'I''m trying to like this game, but so far I''m not feeling it. It just doesn''t grab me. Plays nicely on the Steam Deck however. It just feels bland for me and I''m not enjoying the dialogue or level design. I probably should have refunded this, but it''s too late now. I''m going to try and power my way through it. This isn''t a bad game, it is just not for me.', 'Very Positive', 84.27, 98.72, 4.77);
INSERT INTO reviews VALUES (29582, 846880, 163, 'Mejor que el primer juego. Tiene muy pocas batallas, pero es bastante más gracioso y divertido. Me he reido más de una vez.', 'If 2$ is worth a game you will play once, then this is your game. Completed in several hours. No grinding for levels. Linear gameplay. Some potintial, I guess.', 'Very Positive', 94.48, 1.52, 3.03);
INSERT INTO reviews VALUES (29590, 847370, 6358, 'Runs fantastic on the Steam Deck. Don''t let Valve''s unsupported badge fool you.', 'Great game, but it has serious problems with saves. You won’t be able to progress. Avoid!', 'Very Positive', 89.68, 2.50, 1.85);
INSERT INTO reviews VALUES (29618, 848030, 321, 'When pinball meets roguelike rpg\n\n\n핀볼이 로그라이크 RPG를 만났을 때', 'It''s a fun concept on paper, but it doesn''t really work well. I really wanted to like this game, because it has some cool art and concepts and it looks well developed. But the chore mechanic is broken. You are supposed to hit the enemies, but then you get punished when you do that. Having a health bar for this type of games is just disastrous. It really takes the joy out of the game.', 'Mostly Positive', 79.75, 30.77, 4.77);
INSERT INTO reviews VALUES (29619, 848050, 234, 'One hell of a game, since u only get 1 bike and 3 tracks make sure u watch a video on how to mod the game because this game is fun only if u have mods', 'Great physics, but it''s so ugly I almost puke all over my monitor every time I start it. And that''s with mods. I would also say that the flat lighting and lack of details makes it hard to judge distances and to memorize the tracks.\n\nAlso it cannot be used without mods whatsoever, but that''s mentioned in the description and I knew it before I bought, so no complaints about that here.', 'Very Positive', 93.59, 42.73, 9.42);
INSERT INTO reviews VALUES (29635, 848350, 3548, 'Life changingly good. Why did I only just discover how amazing this is NOW, 20 years later??? Regardless, we''re gonna make it. Everything will be okay. I''ve seen the light, and it''s Katamari. I must spread the word far and wide.', 'Keyboard control simply does not work.  At all.  Refunded.', 'Very Positive', 93.63, 5.07, 0.18);
INSERT INTO reviews VALUES (29639, 848450, 50711, 'Although it has its own issues, its a perfectly functional game which would have been amazing as a standalone, but suffers from having to be a sequel to an excellent game.', 'This game is just a disappointment to me after Subnautica; the immersion isn''t there - the fact that the character you play actually "talks" is just off putting and just brought me out of the whole "I am alone and on the hunt" arch. \n\nThis game feels like it''s designed to be easier than Subnautica because some people had complaints about the first one being difficult and scary. I am a scaredy cat like crazy but LOVE LOVE the oceans in any way shape of form so it felt like a good deal - Below  Ze', 'Very Positive', 90.10, 16.02, 21.92);
INSERT INTO reviews VALUES (29642, 848480, 3565, 'The creator of this game should hit up the casino, cause this MFer can''t lose. \n\nAnother brilliant game from a superb dev. Not everything is ultra polished, but this game''s got a lot of character and it''s awesome to play. I''ve played almost all the games this guy has put out, love em all.\n\nI mean seriously, why are there no copy cats of this great idea? Fighting a fluid, it''s awesome. Knuckle cracker has unashamedly created the same game 4 times, adding features and depth here and there technica', 'It is a good game, just not for me, and depending on the why, maybe not for you.\n\nThe game stages can be quite long and tedious. The most fun part of any map is the start, it really goes down hill from there. It really is more like a puzzle disguised as a tower defence game. Once you are "on the path" to winning, you can''t lose. My key problem is that the time from when you''ve clearly won, to when you do win, is quite lengthy and full of tedium.\n\nIt''s just uninteresting to inch cannons and tower', 'Overwhelmingly Positive', 95.23, 23.70, 2.85);
INSERT INTO reviews VALUES (29667, 849100, 1064, 'I love this game! \n\nThese are the type of game mechanics that I wished were in American Truck Simulator and its European counterpart. \n\nThe almost survival mechanics are so cool and having to take care of your truck and maintain it and being able to move around instead of being attached to the truck is so awesome I look forward to seeing more for this game. \n\nThat all being said I have one issue…. The optimization for this game… holy shit it needs to be better optimized because it runs very poor', 'The game is abandoned. The developers are releasing DLCs and are already planning a NEW project without finishing this one. Issues from 2023 remain unresolved. The game’s performance is poor, but the worst part is the bugs within the game itself. I expected the project to be completed, but it was simply released and left as is. I regret the time spent and the trust placed in the developers.', 'Mixed', 66.07, 22.45, 31.00);
INSERT INTO reviews VALUES (29705, 849740, 510, 'Excellent writing and surprisingly fun mini-games and premise. No real adult content, if that''s what you''re looking for, but as for a well written dating sim, it''s fantastic.', 'The game itself isn''t bad, it crearly took a lot of work have all this content, and I wouldn''t have played as much if I was bored. But as an H-game, it just sucks. It''s super grindy, the rewards are minimal, and if you chose the wrong option, you''ll be locked out of endings. I feel like the affection requirements should be halved, and it should have twice as much H-scenes as it does to at least consider it an H-game worth playing.', 'Very Positive', 94.12, 24.42, 19.28);
INSERT INTO reviews VALUES (29714, 850000, 197, 'I was going through a bunch of older looking rpgmaker games and putting them on my wishlist since I wanted to go back and experience those games. While looking through them during the winter sale, I looked at a review for this game that said it was "one of the best games I''ve played in the decade". With a review like that, how could I not buy it to see what it was all about?\n\nThey were right.', 'Guilty Pleasure for sure. Just why, oh why is this conflict stretching for an unnecessary amount of time...? This could have been 4 episodes max.', 'Very Positive', 94.42, 27.95, 34.55);
INSERT INTO reviews VALUES (29717, 850050, 194, 'fun game, graphics are good, achievements work, would recommend the game', 'so many achievements but at what cost.... this will literally break your computer until you get it uninstalled.', 'Very Positive', 82.47, 2.63, 0.18);
INSERT INTO reviews VALUES (29721, 850190, 3932, 'this game really opened my eyes to the situation regarding prostitution and human trafficking in albania and serbia, such tragedy.', 'My kid likes it, and it is a fun game but...... The rainbow flags gotta go, and my child and I as goats went to wreck a wedding of 2 men being married. It''s a shame that Steam won''t refund me. Thank GOD this country will go somewhat normal January 6th and I say this as a straight Cuban male.', 'Overwhelmingly Positive', 97.76, 3.85, 4.15);
INSERT INTO reviews VALUES (29726, 850320, 398, 'This game made me realize id rather kms than be stuck together with my Bf. 10/10 would recommend', 'Very annoying bugs when you get hooked and your teammate sees you doing nothing, or you stretch the entire length of the map and fly off the map, causing you to have to restart the level, and it seems to make things worse, you want to enjoy the game, not be angry that everything you do just breaks the game and makes it impassable, and the thing that seems like it should solve the problem (restarting) doesn''t work', 'Very Positive', 89.95, 16.15, 10.15);
INSERT INTO reviews VALUES (29728, 850450, 178, 'The puzzles did not feel linear. Honestly, it was this game that almost made me refund the other 2 for Escape First games. I''m glad I didn''t but this game is definitely not for the faint of heart. It''s frustrating, takes time and a lot of patience. The lighting in it was fine though and I liked the concepts. Still fun.', 'Sadly the VR support is horrible.\nThere seems to be only snap turning and every time you turn creates a weird sound effect.\nIn Desktop mode it is playable.', 'Mixed', 58.99, 2.20, 2.65);
INSERT INTO reviews VALUES (29745, 850980, 323, 'I still fucking hate that time traveling british bastard', '99% of GG: The Missing Link players quit before they land the instakill on justice.', 'Mostly Positive', 79.57, 2.93, 5.57);
INSERT INTO reviews VALUES (29748, 851100, 4475, 'thousand knives thousand knives thousand knives thousand knives thousand knives thousand knives thousand knives thousand knives thousand knives thousand knives thousand knives thousand knives thousand knives thousand knives thousand knives thousand knives thousand knives thousand knives thousand knives thousand knives thousand knives thousand knives thousand knives thousand knives thousand knives thousand knives thousand knives thousand knives thousand knives thousand knives thousand knives thou', 'Games can be challenging and rewarding (Im huge fan of all souls games and most big soulslike) or challenging and annoying.\nThis one is in the second camp.\n\nI played Touhou after brilliant (and very easy) Afterimage. And in comparison it is small, mediocre and way to annoying.\n\nOverall ok, but not for me and I would not recommend it.', 'Overwhelmingly Positive', 97.94, 11.23, 6.57);
INSERT INTO reviews VALUES (29757, 851280, 133, 'I played mainly on Switch and I can tell it''s a great game, kind of a hidden gem. It''s a pure metroidvania taking all the best from classics, offering tight controls, crisp pixel art, nicely designed bosses and very immersive world with nice story. You can see it''s all done with passion.', 'The entire game is... A mess. There''s a lot of mixels cases, the controls are rather awkward, the combat is too slow, bosses and enemies have too much HP and deals too much damage, the healing is worse than Dark Souls, the map is a pain to navigate, there''s too many rooms between save points and launch pads, and the part that made me throw this game in the bad games list is that there is Mimir, followed by Maximum Mimir that takes FOREVER and keeps its weakpoint off reach for 70% of the fight, F', 'Mixed', 68.42, 2.62, 8.55);
INSERT INTO reviews VALUES (29769, 851670, 429, 'I feel like this game is very popular with autistic people', 'Tetris Effect is one of my favourite games of all time. Figured I''d also love Lumines. I hate Lumines.', 'Overwhelmingly Positive', 95.34, 7.93, 3.77);
INSERT INTO reviews VALUES (29778, 851850, 16933, 'Play this if you do not want to re-watch the entire DBZ series. The gameplay gets repetitive, lacks dynamic mechanics but overall is worthwhile for the steam achievements and a story recap. Buy when on sale. Kind Regards', 'It is a great nostalgia trip but quickly gets boring. i forced myself to proceed at many points of the game but ultimately dropped it as it was simply too much of a chore. The open world felt bland, the side-quests grindy and the combat system is basically "smash one button and use super attacks when you have charged up ki"\r\n\r\nIf this game was not a dragonball IP, i can imagine refunding it within half an hour of playtesting', 'Very Positive', 92.41, 78.50, 21.87);
INSERT INTO reviews VALUES (29780, 851890, 614, 'Let''s all be honest, we did not play this game to kill demons.', 'Game will crash after 60 seconds every time, tried fixes and done all the standard checks, no dice, refund requested.', 'Very Positive', 85.83, 2.85, 0.08);
INSERT INTO reviews VALUES (29782, 851930, 228, 'not a bad tycoon game', 'game crashes about 5 minutes into loading or starting a park entirely randomly', 'Mixed', 68.42, 13.57, 4.17);
INSERT INTO reviews VALUES (29787, 852090, 402, 'This is exactly the type of silly game that hooks me. I love this one so much, a new favorite for sure. The visuals, the gameplay, the pacing of the unlocking of new mechanics, THE AMBIENT SOUNDS. It''s so so perfect and satisfying for my brain. The replayability is amazing and I''m definitely 100%ing this.', 'Did I play it for 6 hours? Yes. Did I enjoy it? Also, yes. Can I recommend it? I... don''t know. This is a middle ground for me. It is very much pokemon snap, only the art and style did not feel in any way charming. Instead, it felt disjointed and discordant. Some of the puzzles were finnicky, and stuff happened certain ways just because that''s how it was in Pokemon Snap.', 'Overwhelmingly Positive', 99.25, 10.03, 6.07);
INSERT INTO reviews VALUES (29788, 852110, 683, 'You''re not here for the maze puzzle. You are here for the achievements. And we all know.\n\nStill decent presentation with good music. But actually boring mazes.', 'Misderable and boring, And Im being spammed with 200 acheivements', 'Overwhelmingly Positive', 95.02, 0.42, 0.43);
INSERT INTO reviews VALUES (29792, 852220, 465, 'This game is very educational and usefull its a nice way of showing people how to act in car accidents 10/10', 'It''s not that its bad, its just not really worth what you pay. The amount of content is really low, you could probably finish in 2-3 hours. Also the quality of the levels deteriorates over time, not in the environment art per se, but in the level of storytelling and interesting scenarios. It starts off really strong but devolves into very generic scenarios. The lack of Steam integration is really unfortunate, too. No achievements or trading cards. Very linear and nearly impossible to lose at any', 'Mostly Positive', 70.75, 7.75, 5.33);
INSERT INTO reviews VALUES (29794, 852300, 202, 'I 100% the game in about 4 hours or so, and I have to say I had a wonderful time. If you need a game that you can just beat and be done with I cant recommend this enough.', 'Fun until the Synchronus Field boss. 50% of my playtime has been stuck on this 100% bullshit RNG boss. Won''t finish. Do not buy.', 'Mostly Positive', 79.21, 4.15, 2.65);
INSERT INTO reviews VALUES (29802, 852480, 913, 'Yeah, i''m a pervert on main. So what? At least i''m not a republican!\n\n...but yeah the game is cool, has a good art style, great voice acting and it''s quite fun.', 'I thought there would be animation and scenes, but it turned out to be an ordinary comic book, it’s not worth the money, for that kind of money you can buy a comic book game like this one with scenes and more.', 'Very Positive', 93.32, 3.10, 1.18);
INSERT INTO reviews VALUES (29828, 853200, 106, 'GOOD base line good level and just really fun.', 'mid game, better to spend a few more bucks for decenders or riders republic', 'Very Positive', 88.68, 38.68, 8.83);
INSERT INTO reviews VALUES (29831, 853240, 107, 'I love postapocalyptic worlds with scary alien machines so I enjoyed playing it.\r\n\r\n The only thing that I find a little disapointing is that the only ending feels like a bad ending.', 'I diont like it I found it boring.', 'Mixed', 59.81, 3.65, 0.27);
INSERT INTO reviews VALUES (29840, 853450, 750, 'Asked the dev in Discord if there was a button to loot chests/curios on the keyboard. 2 Hours later, a patch came out with the keybind implemented.\n\n10/10 Great Game, Great Dev.', 'Do you want to play "Melee" at all? Well tough. Your naked caster friend will absolutely destroy you in damage until at LEAST level 50. Oh, and this is assuming you have grinded your fourth character to actually have every perfect Legendary weapon you could even hope for to STILL be losing to your naked caster friend facerolling his keyboard. Literally every class that has access to spells is just better when only using those and ignoring anything that scales with weapon damage for half your lev', 'Very Positive', 89.73, 96.62, 119.78);
INSERT INTO reviews VALUES (29843, 853500, 392, 'It’s a tight, thought-provoking sci-fi game where you play as part of a team communicating with an alien in a tense, isolated setting. The game focuses on dialogue and decisions, making you think about ethics, communication, and what it really means to understand something completely alien. It’s a little on the short side, but the writing is top-notch, making it a solid pick for anyone who loves story-driven games. Definitely worth checking out if you’re into deep, reflective narratives.', 'I wish I could recommend this game but I cannot. After my second playthrough, it immediately become clear that this game has too many poor points despite an otherwise okay initial visual novel experience.\n\n* The UI is stylish but has very poor feedback. On my first playthrough I missed several moments to ask questions because topics to talk about that you unlock are kept separate from actual dialogue options and are only usable in certain moments, indicated by them lighting up slightly. Furtherm', 'Very Positive', 88.27, 1.55, 3.95);
INSERT INTO reviews VALUES (29844, 853550, 2056, 'equilinox is so satisfying until you hit endgame and entire biomes still feel empty. this game feels incomplete but it''s never getting updated, so i can only half-heartedly recommend it. \nwhere''re the pandas?? who''s gonna eat all this bamboo???', 'Eh.  \r\nIt COULD be a fun game.  It doesn''t really start you off well, during the tutorial phase.  The graphics are small, the controls kind of hard to find, and after I''d done a few tasks, I didn''t really feel the need to do more.  I''ll try reading through the documentation and see if I''m more invested at that point, but they can definitely do more to make the game a fun start.', 'Very Positive', 93.53, 49.15, 1.98);
INSERT INTO reviews VALUES (29851, 853770, 2739, 'This is like ultrakill for people without autism', 'In retrospective 4 years later, splitting with new blood was probably the worst decision possible for this game. For "creative differences" you are left with a product that still feels inferior to when new blood developers were involved. Genuinely would have been better off canceling the project in its entirety than let it linger on in early access and get worse with each update. Its crazy to me that the gameplay felt more intriguing 4 years ago than it does today. Oh maximum action, what could ', 'Very Positive', 89.63, 4.32, 39.15);
INSERT INTO reviews VALUES (29859, 855860, 953, 'i played the original game when i was 5 years old', 'Cant connect to friends because of my router using CGNAT, which cant be removed, poor game been out 7 years and no proper multiplayer nothing.', 'Very Positive', 88.46, 28.45, 42.58);
INSERT INTO reviews VALUES (29863, 856890, 117, 'Somehow it was fun being a sneaky psychopathic rumba killing everyone\nGame pretty short too\nBut good game and funny ridiculous story.\n8/10', 'Genuinely unfun gameplay. I quit at the third level with a grimace when I realized that the gameplay, after brutalizing the enemies (extremely trivial, you spam click on anything you see in the same room as you and they die), you have to carry four people to an exit one-by-one without dashing. I thought this game was a creative stealth game, but it''s more just brutality simulator. Also, they REALLY like to play the sound of a guy moaning deeply in your ear??? Why???', 'Very Positive', 94.02, 7.65, 0.55);
INSERT INTO reviews VALUES (29865, 860020, 152, 'Just a quick review of EXFIL which I will add to later.\nThe game has ambitious goals. A game which can be played like the owner wants. With many options to mix and match to tailor it into how you want to play.  I personally am not into PvP. This started off as PvPvP tactical game with a somewhat unique take on a tactical Milsim. 3 teams competing against one another. Well, they just released their first take on AI enemies which is what I was waiting for. The game with AI is insanely fun and I am', 'Check SteamDB before buying this game.  It peaked at 100 players launch day, and dropped to 65 players next day.  It takes 32 players for a full match.  The game is DOA, aside from the developers and a few close friends.  A complete ghost game on launch, WILD!\n\nI have nothing for or against this company; I saw this game releasing and thought it looked cool.  Refunded after spending 5 minutes on the only server with players and realizing they all knew each other already (probably devs)', 'Mostly Positive', 71.71, 89.78, 0.10);
INSERT INTO reviews VALUES (29866, 860650, 108, 'Nica and relaxing walking simulator with nice views and interesting animal (and weirdo) encounters.', 'I don''t know what it is that made me so mad when playing this but I have decided I am never buying an asset flip walking sim again (no matter how easy the achievements).\n\nThe dialogue was so painfully annoying I muted it a short way in and it works better when just left with your own thoughts.', 'Mostly Positive', 74.07, 0.92, 0.88);
INSERT INTO reviews VALUES (29872, 865090, 379, 'AHEGAL\n\nHas a total of 5 trading cards.', 'AHEGAL is a a somewhat  a dating game but you have to move around to Avoid lot of things Shooting at ya as you do well you can undress them to see more it was a ok game but stop playing it sadly', 'Very Positive', 90.50, 1.53, 0.28);
INSERT INTO reviews VALUES (29877, 867210, 5137, 'As someone who''s played HOMM2 & 3 (and yes, even 4), and would rather perform a full frontal lobotomy on myself than play whatever the hell Ubisoft eventually made out of the franchise, this ... sort of scratches the itch. The campaigns are fun, but more puzzle-ish than tactical, particularly the ones where you can''t lose your primary hero. I find the magic system needlessly overburdened with complexity, to the point where I don''t bother building a hero up to take advantage of spells. \r\n\r\nI find', 'I really enjoy this game. A beautiful clone of HoMM but with it''s own qol upgrades and gorgeous art.\n\nHOWEVER. The game starts with 4 very sparse factions, and now, after paying 40 dollars for the whole game, we have to pay 15 for an additional faction? I feel ripped off. They should be releasing factions for free as the game was released without enough variety. I will not pay for the dlc.', 'Very Positive', 85.50, 23.47, 10.00);
INSERT INTO reviews VALUES (29881, 870200, 1821, 'This game is darn near perfect. Do you fancy spaceflight? Like building things? You''ve got it all here. If you''ve already been accustomed to other spaceflight games with the little green men, its like that, but prettier looking. The building is smooth. Once you get familiar with hotkeys and the fine details, this becomes a very satisfying way to construct any vehicle you desire. With a fun career mode, being able to start with hobby size rockets, to working your way up to heavy launch vehicles. ', 'Sure you can build anything, and go anywhere.. but what''s the point? Other than discovering locations there''s no point to going places. There''s nothing to collect, nothing to study, nothing to learn. Everything is unlocked by just travelling and setting new records for height, distance and speed. I wish there was more to it, such as taking samples of the ground, space, resources etc.\n\nIt''s fun if you like building rockets I guess', 'Very Positive', 89.79, 1006.97, 33.72);
INSERT INTO reviews VALUES (29883, 871540, 1924, 'Don''t be scared off by the negative reviews. This game is RAD.  I haven''t fully explored the main map yet, but the mod scene is killing it with community built maps that take like 5min to add to the game. Main game has unlockables (parts, riders, etc.) which keeps me coming back.  This is not an easy game to just pick up and play. Controls take a bit to get the hang of, but I knew that beforehand.  This motivated me to get back on the bike IRL this weekend to try and get my hop whips back.  Do y', 'Instead of slowly updating and tweaking the game you sold (Like what was happening), homie decided to make a free demo to yet again completely rebuild the game. \n\nHyped it up so much to do the same thing as last game. Sell you a game that homie doesn''t "Finish" or "Quite like" Then starts making / tweaking sht in a completely different game. \n\nHow did PIPE feel better than Streets and how tf are you building physics into a different game / Free Demo. ', 'Mostly Positive', 74.79, 32.98, 28.68);
INSERT INTO reviews VALUES (29897, 872410, 628, 'I kinda like this better than ROTK XI. The biggest difference that is fun for me is the buff stacking concept. For example you use officer that can create a Ring formation and has "Defense" trait. Then bring another officer with "Steel General" to accompany him and make a camp. That single officer can reach 2000-2600 defense and will only take 1 damage per tick making him unbeatable even with low counter damage.\r\n\r\nROTK XI is more a strong individual unit with 3 officers skill combined, while in', 'Bought it, launched it, and went to play it to give a honest shot. Discovered you can''t play as an individual character and start without a force. \n\nDefeats the game if you ask me, part of the charm was playing as your own character and building yourself up and inserting yourself into History. Really missed the mark on that called.', 'Mixed', 62.74, 812.15, 0.25);
INSERT INTO reviews VALUES (29903, 872750, 153, 'Pretty entertaining point & click adventure in the style of the old LucasArts games, but way easier. Definitely liked the medieval part of the game more than the futuristic setting, but luckily that part doesn''t overstay its welcome. I did have a few annoyances tho, like how some paths aren''t visible immediately until you move to the edge of the screen and an arrow appears.\r\nOverall it''s definitely worth a playthrough for anyone who enjoys old school adventures.', 'This is only worth it if you''re really desperate for point-n-click adventures. The graphics and animations are good, and the puzzles work out alright. But the characters are dull, the writing never reaches quite reaches clever, the story is boring, and the many pastiches and references are merely there but uninteresting.\r\n\r\nIt''s kind of trying to re-create those Simon the Sorceror/Legend of Kyrandia days. But I''m sorry, the writing just doesn''t pop. \r\n\r\nAs an adventure game, there''s far too much', 'Very Positive', 88.24, 4.93, 3.20);
INSERT INTO reviews VALUES (29904, 872790, 2548, 'FM is addicted to me... Joke', 'I think this was the one which fucked the series up slowly.', 'Very Positive', 87.17, 2702.22, 431.05);
INSERT INTO reviews VALUES (29917, 873200, 119, 'What can I say, It''s a nice game.', 'It''s not a nice game.', 'Overwhelmingly Positive', 96.64, 13.75, 3.35);
INSERT INTO reviews VALUES (29922, 873270, 271, 'feels great to control it''s probably in my top 5 favorite games to speed run and when you want to cheese the levels it lets you cheese it. But no Monkey 9/10', 'Rolled Out has been inactive in its development for years, despite showing the most promise for a modern day, classic-style Super Monkey Ball experience. I bought the game when it came out, and it''s had like 3 major updates in that time. It''s fun as hell to play unique levels, but that only goes so far when the game is basically still in an alpha state with next to no information on what''s coming, if anything at all.\n\nIf you want a complete SMB experience, try Ballygon here https://store.steampo', 'Very Positive', 86.35, 33.52, 18.93);
INSERT INTO reviews VALUES (29943, 873840, 484, 'A soft recommend. It''s a good game but nowhere near to the level of ETS or ATS. One advantage Truck & Logistics has over those games is smaller cargo transport is built in, other than that it loses everywhere else.', 'I apologize for being so critical but this game is unacceptable. There are no consequences for driving under water... I rest my case and refund. Also Mobile Games look better than this game.', 'Mixed', 65.91, 1.53, 0.23);
INSERT INTO reviews VALUES (29946, 873890, 206, 'Legends of Amberland is a short sweet lite version of might and magic without the puzzles.  Is suitable to be an entry point for younger audiences / players getting into dungeon crawling adventure. This also is a good way to distress and fight monsters without racking your brains on difficult puzzle solving and also this game is not a very long game. There is one thing that needs improvement is when you scroll over the items in the shop, there is no window to compare the equipment currently equi', 'I hate to dunk on a game that clearly has a lot of passion and care for a niche that I love, but I can''t pretend this is the successor to might and magic I''ve been waiting for. The artstyle isn''t bad, the music is wonderful and you have a good amount of options and freedom for your builds and party, from what little I''d know of it anyways. On the other hand, the sound effects, few as they are, sound dinky and unsatisfying and the game doesn''t absorb me at all, it just feels like numbers for the ', 'Overwhelmingly Positive', 97.09, 23.43, 0.90);
INSERT INTO reviews VALUES (29949, 873940, 1831, 'The gameplay is unique, a tricky real-time strategy puzzle that feels easy, up until it forces you to adapt. But I rarely felt like there was no chance, like I was completely outmatched.\nThat said, sometimes your opponent won''t have a chance to win, but they will take a long-ass time to die, and they might be annoying the whole time. \nI didn''t find the story all that impressive, but that was largely mitigated by the stellar art. \nTry the game out, if it''s not for you, it''s not for you. I don''t r', 'Has a lot of things going for it: art-style, rogue-like concept, an attempt at sci-fi narrative. But unfortunately the strategy in the space battles is just too shallow to justify $25. Also really did not enjoy the fact you have to start a new run each chapter (you make it through a big section and your reward to is start your gear from scratch again). I felt that was part of a bigger design problem that your success on a given run didn''t really translate to any advantages on subsequent runs. My', 'Very Positive', 84.71, 5.73, 5.53);
INSERT INTO reviews VALUES (29965, 874260, 6396, 'This game lets me live out my ultimate fantasy of going back in time to the roman empire with a glock.', 'It is an ancient Roman version of Groundhog Day you are a man from the 21st century who is brought back in time after dying. However it completely falls apart with its blatant agenda pushing. The text prompts are filled with woke libtard propaganda and heresies such as religious indifferentism. One of the worst parts is during a quest which is necessary to complete the "canon" ending you are forced to blackmail a Christian guard into accepting a side character’s homosexuality, threatening him if', 'Overwhelmingly Positive', 96.40, 9.47, 10.25);
INSERT INTO reviews VALUES (29988, 875210, 162, 'Korean Please', 'Never knew this game can be so bad. \nIt''s a game about  90% of waiting for everything else. \nFor example,  like recruiting and managing your buildings while there''s only 10 % of battling in this game. The older series of this IP is like totally the opposite situation~with 90% of looking for battles and looting , together with only 10% of doing everything else.\nI don''t like the ROTK''s concept where you have to wait for 5 minutes to know the results of your scouting for officers and this game actu', 'Mixed', 59.26, 38.35, 65.60);
INSERT INTO reviews VALUES (29993, 875310, 191, ' One of the best short games ever. Highly recommend!', 'The base idea of the game and its visual style ain´t too bad: a comic-style adventure with some story parts (mainly reading) and some gameplay parts (though the game is 3D, it is only making use of 2D, which isn´t necessarily a downside). \r\nI did enjoy the film noir visual style of it, and the story, but unfortunately the gameplay is really repetitive and doesn´t make you use all avaiable options (e.g. sneaking, ambushing, fighting) but enables you to just gun down everything in the game. The gi', 'Mostly Positive', 70.16, 19.48, 7.62);
INSERT INTO reviews VALUES (30013, 875760, 141, 'Short lived journey but man is this game super fun! Makes you feel like a pirate like no other game!', 'it was a bit fun at first to sail and have pirate combat. However this is a negative review because the music is very lack luster and it has performance issues. Even after re-configuring my resolution and the other typical VR fixes it continued to lag after 10mins of gameplay. Music in a pirate game is very important and it sucks that all you hear is unity "epic game trailer" shit that makes my head hurt -- the sea shanties playlist could not help this game', 'Mostly Positive', 70.21, 15.23, 0.57);
INSERT INTO reviews VALUES (30016, 875800, 183, 'After playing the original its a great nostalgia experience and also a way to experience the birth of a genre.', 'A graphical upgrade for sure, but replicates the jank of the original, while adding issues not originally present. Wasteland Original Classic is at least faithful, warts and all, to the 1988 release, this game''s bugs (including freezing up when trying to run in combat or use items, requiring a quickload or restart (which loses you progress and doesn''t guarantee it will work next time you need to "use" or run)) add an extra layer of frustration on top of the aged-like-milk gameplay of the origina', 'Mixed', 69.95, 41.42, 1.58);
INSERT INTO reviews VALUES (30049, 876650, 1074, 'This game is fucking amazing.\nNo sexual content\nNo Blood\nNo Drugs\nStraight Fire and Brain Food. Give us more 2d aground updates', 'There are minor spoilers in this review - primarily gameplay-related, but it might impact the story experience if you are perceptive.\r\n\r\nI don''t think the game was intentionally misleading, but the experience of playing the demo was nothing like the real experience. I expected the story to engage more with individual characters, or at least have them be more permanently mentionable people, but after the first few nights their dialogue becomes stiff gameplay tutorial cycles. I expected gameplay t', 'Very Positive', 93.39, 185.50, 19.27);
INSERT INTO reviews VALUES (30059, 877010, 505, 'Much improved since release. The beginning can be a bit tough, but nothing a player paying attention and checking tooltips could not handle. \nOxygen consumption can be handled easily with the Rebreather, while food can be cooked with the stove (even the plant one, it doubles the stamina regained). So focus on spending Research on Rebreather then Stove, and you are good.', 'Interesting story lines, I really give it that. I love a good sci fi survival game. Unfortunately, I feel too much time is absorbed in basic needs (food, oxygen, etc) that it becomes a menial and repetitive chore. After two hours of this gameplay loop, it was time to turn in.\n\nTo play the other characters available, you need to redeem in-game currency that I''ve never seen a drop of in my playtime. Being forced to play the one character that I was growing tired of really killed my interest.', 'Mostly Positive', 70.89, 7.22, 1.90);
INSERT INTO reviews VALUES (30066, 877200, 2908, 'yeah, no this is the SH*T', 'this game was so much better before it was crossplay. all the graphics were amazing. but now all models and textures are scuffed as hell because quest needed to ruin it and join', 'Mostly Positive', 78.37, 11.85, 93.15);
INSERT INTO reviews VALUES (30074, 877360, 155, '^_^"', 'It''s just an achievement game, you get the achievements but it doesn''t count as a perfect game + you don''t get the achievements on your account/profile. So unfortunately an L success game.', 'Mostly Positive', 70.97, 3.73, 47.32);
INSERT INTO reviews VALUES (30093, 877810, 581, 'First game I finished in 2025… and man I can’t think of it getting any better than that. \n\nYou don’t have to play the first Anodyne to jump into this masterpiece, I didn’t. But I definitely want to play Anodyne 1 so I can then replay Anodyne 2. \n\nThis is a very story driven game and I feel like you need to follow the story as best you can with your own interpretations in order to really appreciate what this game is. \n\nGreat OST is always a plus too!  100/10 -- oh and go buy a Nova Plush when you', 'okay let''s start with the things I like the music is pretty cool and the 2D sections are sometimes interesting the main reason I don''t recommend this game because the story is Ass I''m not really sure what to say but you have to experience it for yourself cuz it''s like you know the characters that you helped out suddenly all they realize what they did wrong blah blah like this one f****** rock guy this goes on and on about like talking to these f****** imaginary things it''s like he know they can''', 'Overwhelmingly Positive', 95.01, 22.93, 10.85);
INSERT INTO reviews VALUES (30094, 877850, 146, 'TribeXR is a great program, and I have enjoyed being an early purchaser on SteamVR and Beta Tester on Quest.  I recently sold my controller, and I cannot replace it anytime soon.  I plan to get back into TribeXR in the meantime, and I will update this review if anything stands out as something to highlight or mention that others may not have shared.  \r\n\r\nThe DEV''s are DJ''s themselves and TribeXR is a passion project as much if not more than anything else.  I''m not a fan of subscribtion models, b', 'I have the lifetime sub because I bought this software a long time ago, if you have that, its pretty great saves me some time if I just wanna spin something real quick with minimal set up, if not. Well. Get yourself some real intro decks if you wanna learn to DJ.\n\nThis sub model ain''t it devs.', 'Very Positive', 84.25, 27.63, 47.68);
INSERT INTO reviews VALUES (30130, 878580, 128, 'Its a Mix of Hotline Miami and Silent Hill.\nAlot of awesome Boss Battles and weapons.\nI love how some enemies react to damage, I cut an enemies head off and it wandered aimlessly. The trippy Grind house feel is awesome with the grainy VHS look. Love this game and its super fun.\n\nThe controls are a little clunky and it could use improvement in that area but it takes a little getting used to. But with the lack of ammunition you have to make your shots count so take your time aiming. But this is aw', 'I liked the visuals and the music, but everything else was bad.\nBiggest problem, the game doesn''t appear to have been playtested: enemy damage insane (certain soldiers will one-shot you from offscreen even on easy), enemy spawn behind/right next to you quite often, max ammo is far too low, there are ammo drops right before the end of the level that give you 2x the amount of ammo you can actually carry, most secret walls aren''t hinted at in any way and can only be found by chance or by wallhumpin', 'Mostly Positive', 71.09, 7.93, 5.07);
INSERT INTO reviews VALUES (30136, 878670, 427, 'I think it''s pretty rad that the devs took to heart all of the criticism of the first two games being slow and clunky and made the game even slower and clunkier.', 'I tried. I tried and tried again and it''s just so painful.\r\nI never make it past the first village, I''ve tried over and over with an open mind..\r\nI had to uninstall again, I''ll try again in 2028.', 'Mostly Positive', 74.71, 28.50, 34.33);
INSERT INTO reviews VALUES (30140, 878750, 2736, 'Nodoby will read my review so I''ll eat a banana for every like! Humpf!', 'no artwork and screenshot showcases really steam? kinda defeats the purpose of buying this game', 'Very Positive', 92.62, 17.68, 0.70);
INSERT INTO reviews VALUES (30152, 879000, 175, 'Nice helicopter action game, you don''t see those too often anymore. \nIt has a campaign and single missions that are pretty nice. There is 2 main gameplay styles, the helicopter combat and drone. You have a drone that you can deploy at any time, in pretty much every mission you infiltrate a building with it. Its variety, imo the drone segments can be a bit long sometimes.\nDoesn''t take itself too seriously, there is a lot of voiced dialogue with lots of banter in every mission.\nThe game doesn''t ha', 'it''s Comanche 4 in disguise of new graphics and clunky control somehow, straight-up garbage.', 'Mixed', 56.00, 3.22, 2.98);
INSERT INTO reviews VALUES (30161, 879160, 1467, 'supervive people come here plz', 'abandoned by both devs and players. Was never particularly good to begin with. vs AI is all that''s left. Seriously, don''t bother.', 'Mixed', 67.14, 44.55, 6.83);
INSERT INTO reviews VALUES (30170, 879420, 1352, 'A very faithful recreation of Ohio', 'searching for steam cards led me to places i wouldn''t even go to with a gun\r\n', 'Mixed', 64.13, 9.72, 4.10);
INSERT INTO reviews VALUES (30198, 880380, 112, 'the most addicting hockey game ive played since nhl 94\n\nlove it....', 'I have put around 500 hours into the FHM seriers on FHM 3 and FHM 4, i have lead teams on these games to NHL season with 70 + wins for 5 straight years so id like to think i know how to play. Let me start by saying like everyone else on here i do think that the UI has improved a lot this year, but the reason im giving this game a negative review is because of what they have taken out. You can now only assign one role to a player on your team, in old games when your players where 5v5 you would as', 'Mixed', 55.36, 653.50, 72.38);
INSERT INTO reviews VALUES (30200, 880510, 380, 'the steam achievement sound is now ringing in my head', 'a couple achievements are bugged but a simple drag and drop puzzle solution. or hit f for 1552 achievements. Also makes me question if some of the tracks here are premade music it also is present in alot of other 1$ games', 'Very Positive', 86.58, 0.82, 0.15);
INSERT INTO reviews VALUES (30203, 880580, 238, 'It was a very Good Game in the first 2 hours, but it became a bit boring afterwards.', 'Quickly hits a point where there''s nothing else you can do. There''s a hard limit on how many buildings you can place, so once you hit that limit, you basically just.... stop.\n\nVery cool game idea. Unfortunate they artificially capped it this way.', 'Very Positive', 85.71, 5.98, 2.82);
INSERT INTO reviews VALUES (30208, 880730, 176, 'rocket league 2.0', 'Avoid this game if you value your sanity... if you''re a masochist, go for it.', 'Overwhelmingly Positive', 95.45, 7.13, 6.70);
INSERT INTO reviews VALUES (30219, 880940, 13598, 'Basically it is your Mario Party, but with PC flavor including some blood and 8 players mode. \nProbably the best game of the genre that you can get on Steam.', 'Played pummel party for the first time, expecting a merry and jolly time. Came out with ruined friendships (specifically with Spacecool27) and a victory royale. Will not be touching this game again.', 'Very Positive', 88.02, 11.70, 1.22);
INSERT INTO reviews VALUES (30223, 881020, 10312, 'This reaffirms to me that gacha games can be great but actively choose to lessen themselves in the name of greed.', 'Great game, then the develops completely abandoned this project. Throw in a few DLCs for money but don''t support any version of crossplay or online services. Amazing game to play for literally the main story by yourself.\n\nGet it on sale, don''t support this at full price. Absolutely tarnished a beautiful project.', 'Very Positive', 92.30, 14.78, 34.07);
INSERT INTO reviews VALUES (30228, 881100, 42697, 'Playing Noita hurts. It''s like a good hurt, though. It doesn''t hurt like getting stabbed or beat up, though. It''s like paying a woman $20 to kick you in the testicles. I have done both of these things and I have to say, I prefer Noita.', 'every pixel being simulated is cool but when i cant walk on the ground for 2 secs without getting stuck in something it does not feel fun having a run ended to the ice that formed into my *** or a feisty pebble getting too deep while there are enemies around should be less of a problem. the game itself is fun but needs more quality of life in some spots.', 'Overwhelmingly Positive', 95.65, 154.40, 65.10);
INSERT INTO reviews VALUES (30239, 881320, 397, 'I got to play this game after Lego Movie 1 (probably)\r\nWhen I played the game I had a lot of fun but the downside of this game is that it is very short', 'I''ve given this a couple tries now, and i just don''t like it. Hubs/maps are my least favorite thing in Lego games, and this seems to just be one giant hub. There might be a good game hidden in here, but I''m not willing to look any harder for it.', 'Mixed', 60.45, 5.25, 1.65);
INSERT INTO reviews VALUES (30242, 881420, 387, 'This game is a mix of a tribe simulator and a visual novel. The art is beautiful and prominent and gives life to the mythical ages of Glorantha, the events are varied and have many different outcomes, and the game itself is easy to pick up but hard to win. I had a blast with it even though it took me a while to figure out and I failed often.\n\nOne thing to note is that the game really does not hold your hand at all. It does not tell you how to win, and it is possible to completely doom yourself l', 'I have to warn everyone considering to buy this game that in the end, despite the game offering many choices, there is only one storyline that will result in a victory scenario after a wedding, no matter how well you play, and I think that despite this game showing a really interesting world, the endings just ruin it for me, especially since many game overs are scripted endings to storylines, and you can have a flourishing clan, but the game just gives you an event that people have migrated into', 'Mostly Positive', 79.59, 21.87, 75.53);
INSERT INTO reviews VALUES (30249, 881560, 335, 'OH MY GOD', 'Review note: I didn''t get that deep into the game. I stayed inside the refund window.\n\nThe only thing that made me slightly want this game was the Psychological Horror tag. However, I didn''t get far enough in to get to that point and it was already feeling like a slog because all the characters were so cookie cutter and fake even for a VN. Some of their dialogue felt so forced and made me go "of course you would say that. Classic <insert generic anime personality> energy right their".\nI''m pretty', 'Very Positive', 80.90, 156.83, 1.62);
INSERT INTO reviews VALUES (30254, 881690, 352, 'A pretty good first person Hitman-esc game, where you play as Budget Bruce Willis.\nPlayed for quite a few hours, and had fun for the most part.\nWould recommend.', 'If you ever wanted to experience the gameplay of Hitman in fps with indie stlye - and with significantly worse execution - then I would recommend The Slater to you. Otherwise, it''s best avoided.', 'Mostly Positive', 74.72, 6.90, 1.23);
INSERT INTO reviews VALUES (30263, 881920, 170, 'Felt like playing League of Legends over and over again.', 'Awful/buggy game that isn''t worth it for 2 euros.', 'Mixed', 67.06, 1.02, 0.52);
INSERT INTO reviews VALUES (30267, 882020, 356, 'Good game, better than the newer ones, I recommend this one over 3 because the Compund and the Playground, which are some sort of free roam maps, have proper Motocross style tracks, so you don''t really need to bother with buying the MXGP games if you get tired of stadium tracks or aren''t a huge fan of dirt bikes.', 'Game doesn''t work anymore. crashes upon startup, f*ck you Milestone, fix your games. Used to play this all the time. Now, it don''t work.', 'Very Positive', 82.58, 244.45, 44.95);
INSERT INTO reviews VALUES (30271, 882100, 12552, 'A cheap and cheerful version of XCOM. Everthing is smaller and simpler. Fights are per-room, rather than on a large map. Chimera Squad is not as good as the earlier games, but it is still enjoyable and worth playing.', 'This game broke my heart. Not in the "my soldier missed a 95% shot and got melted by a Sectopod" kind of way—that''s the good heartbreak. That’s the stuff XCOM fans live for. No, Chimera Squad hurt me because it took everything I loved about XCOM and put it in a blender with rainbow sprinkles, buddy cop dialogue, and a weird obsession with breach animations. This isn’t XCOM. This is XCOM with training wheels and a laugh track. Gone is the tension. Gone is the dread. Gone is the permadeath that ma', 'Mostly Positive', 74.44, 42.17, 3.00);
INSERT INTO reviews VALUES (30274, 882140, 622, 'Simply outrageous.  It''s not as hard as you think.  Learn in order, Mercury > Gemini > Apollo and the gradual increase of complexity will be easier to understand, especially when the basics of Mercury are under your belt.\n\nFrom the gorgeously crafted faithful interiors of some of the greatest technological achievements in human history, you can step aboard the launch capsules and relive, in real time, every flick of the switch, every concerned breath, every panicked voice of the faithfully synce', 'The simulation is relatively decent, but there''s enough discrepancies for historic missions to be kinda useless. The game is also quite poorly optimized.\r\n\r\nI think there''s a lot of potential in this game, and in its current form can be a great learning tool, but I don''t feel the experience is fleshed out enough to be enjoyable.', 'Overwhelmingly Positive', 97.27, 112.85, 6.95);
INSERT INTO reviews VALUES (30298, 882710, 367, 'It has smug Reimu in it', 'Controls don''t work properly for me (slowdown doesn''t work). Can''t rebind them either.', 'Overwhelmingly Positive', 95.37, 27.78, 0.15);
INSERT INTO reviews VALUES (30301, 882790, 260, 'The English translation still not out yet but I likes the gameplay and the animation', 'junk', 'Very Positive', 91.92, 61.53, 0.22);
INSERT INTO reviews VALUES (30314, 883070, 129, 'An excellent little horror game! Once you figure out what you''re doing, this game can be beaten in roughly an hour. That said, it took me at least 3-4 hours figuring out what I was doing. The puzzles are on the tricky side, and had me going for a loop, but I really enjoyed the story and the reveal at the end. And once I got the bad ending, I was immediately motivated to go back and try and get the good ending. Highly recommend!', 'I didn''t play this for long because I don''t have the patience to spend a long time solving puzzles. The game barely gives you any hints, you have to walk all over the place to find something. Usually games like these are room to room or house to house, but in Viviette it''s a very big area. Feels like a waste of time to be running around in circles. Not my kind of game. After 40 minutes or so I only got to the second item and it didn''t tell me at all what to use it for, tried interacting with it,', 'Very Positive', 85.27, 7.57, 0.60);
INSERT INTO reviews VALUES (30315, 883080, 167, 'I love making friends and then cutting them off and blocking them after one game', 'Scripted game, show me the game code!', 'Very Positive', 82.04, 9.53, 2.13);
INSERT INTO reviews VALUES (30316, 883100, 254, 'Actually good', 'Needs public servers', 'Very Positive', 89.76, 3.80, 1.07);
INSERT INTO reviews VALUES (30317, 883130, 197, 'This game is too addictive. I had to uninstall it in order to not lose my job.', 'The game itself is great fun. If it''s on big sale, you can buy it. \nBut what''s the point if it keeps crashing? (BtD) \nSupport from the developers in the discussions is also very limited when it comes to crashes... \nSo all that remains is a thumbs down...', 'Very Positive', 87.82, 205.78, 9.55);
INSERT INTO reviews VALUES (30320, 883220, 161, 'Enjoy alongside 3-4 dry grams', 'slow in a bad way. i like slow games, i loved naissance, i loved death stranding, i loved layers of fear... etc etc. but this just didnt hit.', 'Mixed', 67.70, 0.77, 0.70);
INSERT INTO reviews VALUES (30352, 884260, 1358, 'kill bill x hotline miami .. totally worth more than the 1$ i spent on it', 'If this game let me move while I was shooting and didn''t have a stamina bar it''d be an easy recommendation. It''s so close to being good but ends up being infuriating in a way where the mechanics of the game and the type of the game it is are at odds with each other.', 'Very Positive', 94.70, 3.35, 0.83);
INSERT INTO reviews VALUES (30355, 884320, 201, 'I had a good time.', 'Ok so it starts off with you walking in her room mind you it’s not free roaming either. She dances for you 2 times only wearing a different outfit each dance. She asks questions and there is no dialogue choices it’s like a bubble with a green something then I guess you automatically answer when you press the only bubble. Also she kinds of like freezes for a sec when she decides to dance for you it happens again when she dances the second time it’s not even like a lap dance and you can only grip ', 'Mixed', 56.72, 3.67, 0.52);
INSERT INTO reviews VALUES (30383, 885000, 976, 'Personally, I think the only thing Beat Saber does better than Synth Riders is the songs it comes with. Synth Riders outperforms Beat Saber in all other aspects by a thousand miles.\nThink of Beat Saber as playing DJMAX game in VR, and Synth Riders as playing Just Dance in VR with superior movement detection.\nI guess it just comes down to what you are looking for in a rhythm game. Are you looking for a game where you play an instrument along with music (the instrument being the sabers), or are yo', 'This game is perfectly fine, but there''s basically no reason to pick it up over Beat Saber unless you''re having wrist issues or have trouble swinging a stick precisely.', 'Very Positive', 93.24, 7.18, 0.75);
INSERT INTO reviews VALUES (30387, 885150, 373, 'Get a piggy bank and put a quarter every time you use continues . \nYou''ll either get much better or you''ll be able to put a down payment on a house. \nEither way you win .', 'This game doesn''t let you to play with a joystick and a keyboard (player 1 and 2) at the same time. I recommend anyone to find another way to play these games if you don''t have 2 controllers.', 'Very Positive', 86.60, 7.17, 2.02);
INSERT INTO reviews VALUES (30408, 885810, 848, 'Yo shoutout to my dad for shooting a blind legless girl best dad of the year', '"A horror house pixel game - Another one Edition"\n\nNo offense to the original developer, but this honestly isn''t anything I haven''t already seen a dozen times already, it doesn''t do anything new or particularly interesting, and there''s no story. Or rather, no narrative of any sort. I''ve seen this sort of thing done better, but I suppose that makes sense considering this is a remake of an older game. Still, I have to judge a re-make on modern merits (because why would you remake it if you thought', 'Very Positive', 94.81, 3.55, 2.08);
INSERT INTO reviews VALUES (30411, 885910, 106, 'I''m new to shmups. Coming in with no expectations and only looking forward to the 3D mecha + anime art style, I was surprised how engaging this game turned out to be. The game focuses on the story mode which has 10 missions total. Each mission has a very unique flavor and associated gimmick to it, which kept me coming back to see what would happen next. Sometimes bullet patterns can be hard to distinguish from the background, and it can be hard to tell where your ship is, but you can get used to', 'Noisy anime characters won''t shutup during the missions.  \n\nI like the level select screen and ship customization, but the game itself is too busy.\n  \nArtstyle doesn''t look great either (at least in my opinion).  It''s very difficult to tell what is an obstacle and discern what is in foreground versus the background.  In the 3D sections it is also difficult to determine where objects are in relation to you, making it difficult to avoid them.\n\n', 'Very Positive', 84.91, 12.12, 0.13);
INSERT INTO reviews VALUES (30414, 885970, 7307, 'What can I say after several hours? Overall, the remaster turned out well. A huge bonus was that buying the remaster also added the original 2004 Rome: Total War to my library. Overjoyed at having the original, I jumped right in, but the outdated textures convinced me to give the remaster a shot.\r\n\r\nAs for the downsides, the map is a bit too garish, and the UI isn’t the most user-friendly. The AI, from what I remember, is pretty much on the same level as before—which, for me, is a plus, as it br', 'UI is abysmal the 20 year old game is superior in almost every way, forcing you to buy this to get the original is something definitely thought of by someone who wears a tiny hat', 'Mostly Positive', 77.13, 4.35, 0.43);
INSERT INTO reviews VALUES (30417, 886040, 104, 'very boring game lol xD\r\n', 'Bad artworks and horrible gameplay, didn''t turn me on 0/10', 'Mostly Positive', 75.00, 0.45, 0.18);
INSERT INTO reviews VALUES (30459, 886900, 740, 'Hard game for low IQ people like me.', 'Even the short time I played wasn''t very fun or satisfying. There''s just so much that''s clunky, confusing or doesn''t make sense. \n\nFor instance, when building your menu, you have meters on the right-hand side to indicate the different groups that might come to the restaurant and how the menu would appeal to them. Great! I know "Cheapskates" are my first demographic to target so I build a menu that gets a 100% rating with them. I start my first day, reviews start to roll in aaaaaand... the cheaps', 'Mostly Positive', 73.78, 13.73, 0.75);
INSERT INTO reviews VALUES (30461, 886960, 138, 'For a port of a korean mobile Vanillaware beat ''em up knockoff, this is really not bad. The problem is, this is a port of a korean mobile Vanillaware beat ''em up knockoff. Low-res textures, incorrectly cropped sprites on some of the enemies, endless grinding, repetitive combat. If the dev/publisher cared a little bit more and polished their game further, this could''ve been a great beat ''em up RPG on Steam, because the combat animations are really well made and satisfying, the equipment/customiza', 'What you are paying for is a mobile game port which means the game was designed as a mobile game first hand. \nAnd surprise its extremely monotonous. Every single stage is the same and hell even the skills barely a character has barely vary. You end up doing the exact same thing over and over. Also this game is literally google translated.\n\nThe portraits are nice and the ingame graphics aren''t bad but nothing extraordinary.\nThis game just isn''t worth 10 or more bucks.', 'Mostly Positive', 79.71, 19.82, 2.90);
INSERT INTO reviews VALUES (30464, 887060, 187, 'Remastered game that is a sequel of a game, based on funny French comic book.', 'Combat didnt change much from the old one. The few changes that I did notice disappointed me. Unlike the XXL remaster it doesnt have a button to change into the "old" style. Also very bad performance for some reason whenever I got the combo goin? Only get it for nostalgia reasons unless you have a way to get the original XXL2.', 'Mostly Positive', 74.33, 0.65, 25.67);
INSERT INTO reviews VALUES (30472, 887370, 135, 'The game is simplistic in its linear story line. However I found myself liking the tactical battles. Being a turned based it wasnt too hard in the begining, but later gets much harder with alot more enemies and your crew of only 3 per battle.\r\n\r\nI did like how in some missions you get several other characters as rewards (besides upgraded weapons) for certain missions. These characters can be a boon later in the game. \r\n\r\nIts not greatly in depth as XCOM or Jagged Alliance tactical styles but I f', 'I can''t recommend this game. Whilst there''s clearly a lot of work gone into it I find the battles too buggy to continue with it any further. Strange behaviour when an event happens and a character seems to slide into a completely different part of the map. I don''t have the time to continually restart missions when this happens, there''s no save on turn. All in all, I''m just not getting along with it. I may return to it at some point as I love this type of game, The story, characters and narrative', 'Mixed', 61.48, 22.72, 11.90);
INSERT INTO reviews VALUES (30475, 887450, 180, 'After Spending 41 Hrs playing and fulling completing this game i would say that this is worth the buy, \r\nThe game has its flaws it isn''t the most re-playable game in the world, unlike other Rougelikes in it''s genre like Hades, nuclear throne and the likes. But there is enough to properly sink your teeth in and actually enjoy whilst playing.\r\n\r\nFully achievement completion wise it was a slog, getting all of the lore books is really tedious and boring, its rng based so playing with friends and goi', 'Not a great beat em up. Especially in co op. They lock you in a very small area and you fight waves of samey enemies. Then you fight a hard boss. The worst part is it''s hard to revive your friends so they end up sitting and watching mostly.', 'Mostly Positive', 70.56, 41.80, 0.43);
INSERT INTO reviews VALUES (30476, 887490, 339, 'I haven''t given the game much playtime yet, but so far, I love the mix of "choose your own adventure" and tactical combat.\nIt really feels like Band of Brothers: the tactical game so far, with its nagging drill sergent.\nThe tutorial was a bit awkward, though, with a mix of excessive hand holding at times and hazardous decisions to take at other times.\nI like how you typically have to choose to favour your soldiers(by playing it safe) or the HQ (by zipping as quickly as possible through the missi', 'I hate to not recommend this. I had it on my wish list for years and it randomly came out today, but wow is it underwhelming! The tutorial is pretty much over 2 hours if you sit and read everything and watch the little videos that pop up every 3 minutes of game play. Some images look authentic but a lot of them look AI generated. They try to play it off like this is some revolutionary game, which in fairness the concept is a great idea the execution is just not there. I also don''t like how they ', 'Very Positive', 81.42, 6.97, 1.97);
INSERT INTO reviews VALUES (30479, 887530, 108, 'Warning if you are sensitive to NTR content, this is not a game for you, on the other hand, I recommend this game, if you like NTR, a little non-consensual sx, watching guys take advantage of protagonist, or just watch H scenes if that''s the case. Also, if you are one of those who likes to enjoy both the story and the H content, some scenes may be a bit repetitive, but from there you can enjoy it because of the type of outfits in which you see the protagonist with different positions. If you lik', 'I didn''t like this one. I only have 0.3 hours on record before uninstalling it, so somethings obviously wrong with it.', 'Very Positive', 82.41, 13.47, 0.28);
INSERT INTO reviews VALUES (30481, 887570, 2877, '50 hours to learn, 3000 hours and an estradiol prescription to master. 10/10, would play again', 'It''s a great game if you are here for multiplayer, which I am not. After over 2.5 years there is still no improvement in SP content while this was promised at release. It has now been delayed even further.\n\nI have a feeling (could be wrong) that the dev listens to the vocal and active multiplayer community thinking these are the only people interested in this game. I believe, however, that the majority of people, like me, are simply silently waiting for some sp content to be released. \n\nOh well,', 'Very Positive', 82.83, 769.18, 29.27);
INSERT INTO reviews VALUES (30487, 887720, 182, 'short and mix with devil may cry and prototype games\n6/10', 'the combat system was OK (not good but not bad either)\na lot of bug and in I wanted to say a review in one sentence I can say:\nThis game could be better but it is a failure right now', 'Mixed', 51.65, 7.28, 8.53);
INSERT INTO reviews VALUES (30491, 887800, 382, 'Great game and realistic. Shame you cant create yourself but still worth the buy.', 'It''s crap. Applying english affects cue ball path incorrectly (source: snooker player IRL) making it unplayable. There''s no deflection at all (some call it squirt, don''t google that) and when the cue ball has side spin on it, it strongly changes the *cue ball''s* angle coming off the object ball. That''s not at all how it works IRL. Default FOV when looking down the cue is far too high with no way to change it, nonsensical commentary, apart from some basic graphics settings there''s zero options an', 'Mostly Positive', 70.68, 235.08, 0.83);
INSERT INTO reviews VALUES (30507, 888040, 212, 'One of the best strategy game. I hope we will get 4k remake or part 2 <3', 'Please Insert Metal Fatigue disc #1???', 'Very Positive', 92.45, 45.92, 0.10);
INSERT INTO reviews VALUES (30521, 888530, 164, 'Playing through Yaga was an enjoyable experience overall, but for me it was primarily so because of how the game brings to life some fascinating and, at times, very niche characters and creatures from Slavic mythology. Being able to play through the game and show my Russian wife every new creature and ask her if she''s heard of it was an integral part of my enjoyment as she either immediately knew what it was and happily told me everything she knew about it or had to look it up online only to rea', 'no', 'Very Positive', 84.76, 7.63, 0.28);
INSERT INTO reviews VALUES (30535, 888790, 593, 'Very compelling story with nice characters. The character design is a bit plain compared to other Yuzusoft games, but the plot for Nene''s route especially makes up for it. I highly recommend Riddle Joker or Amairo Islenauts for more cohesive character design.\n\nSome people might experience giant GPU usage when running this game however, and it is because of the game engine uncapping the framerate and requesting the GPU to run the game at 2000 to 3000 FPS. Just click the Help button on the tool ba', '纯cjb无聊的一笔', 'Overwhelmingly Positive', 95.78, 39.12, 7.82);
INSERT INTO reviews VALUES (30544, 889080, 279, 'At first glance, you might think to play this as a civilization game - build your cities to destroy your opponents. Forget that. Dragons. Research spells to summon dragons. Clear dungeons to level dragons. Build your cities to make tons of money and mana. Why? Dragons are expensive. Hire heroes and level them up to train your dragons. Defeat the other empires so they can''t shoot down your dragons.\r\n\r\nThat''s probably the most fun I''ve had in this game. Don''t try to play this game as it seems inte', 'I fuckin tried to get into it but god this game can get soooooo tedious. If I automate 3 workers I shouldn''t be getting up to 50k gold with barely any improvements built anywhere. As much as the city building is fun I cbf placing 2 million lumber yards/farms/fish nets/etc. Need some major QoL improvements for the price you pay.', 'Very Positive', 87.10, 379.05, 56.45);
INSERT INTO reviews VALUES (30561, 889480, 535, 'Absolutely delightful. Perfect fit for a chaotic goblin like me.', 'This is a great game, but i cannot recommend it if you are a Quest 3 owner. The controls are mapped to a HTC controller, and as it has touch controls, it doesnt work well with the joystick. You also have to remap the rest of the buttons to have a good experience. Great game anyways, as ive played it with a friend.', 'Very Positive', 91.78, 3.02, 0.28);
INSERT INTO reviews VALUES (30563, 889510, 880, 'based and redpilled franchise that died to censorship so that woke slop could flop.', 'i don''t recommenced this game here why upon my research i can say i regret buying Serena kagura because i found out actual age of character am ashamed that i purchase this game i know i have down voted game for less but this time take my word for it they sexual minors in this game how did this game get M rating this is soft core pedophile porn i fucking hate it i hope to god people don''t purchase the game i wish i can remove it from my library i down-voted game i don''t know why it has very posit', 'Very Positive', 94.20, 8.52, 2.18);
INSERT INTO reviews VALUES (30566, 889600, 232, 'This game will stay in my heart forever', 'ass', 'Mostly Positive', 73.71, 125.78, 8.27);
INSERT INTO reviews VALUES (30570, 889710, 113, 'Muv-Luv Altered Fable is Muv-Luv Extra with a stronger punch.\r\nDefinitely worth it.', 'I assume most people will buy the game to get the canon follow-up to the story of Muv-Luv Alternative, and its way more unsatisfying than the ending we got in that game. It''s pretty soulcrushing to see Takeru lobotomized to be even dumber and more irresponsible than he was at the start of Muv-Luv Extra. The plot conspires to make it a full harem even at the very end, so you can''t even get an actual ending to the romance. At least find an uncensored version of Altered Fable rather than getting th', 'Very Positive', 83.19, 65.93, 18.27);
INSERT INTO reviews VALUES (30576, 889910, 571, 'It''s like a deranged 3D Mario game, but the platforming and camera controls are better in Hell Pie than they are in Mario. Fun skill tree to expand your abilities & enjoyable trying to explore the levels for secrets. I did fall through the wall in the pipe restaurant several times, but other than that I''ve not noticed any other bugs or glitches.', 'The platforming is basic and a little boring\nThe humor is juvenile put me off of continuing', 'Very Positive', 90.89, 14.60, 1.28);
INSERT INTO reviews VALUES (30596, 890550, 2623, '99% of the negative reviews are complaints that the controls in this game are too difficult. Don''t be detered. Anyone with an attention span and resilience to frustration will blow through this game with EASE. Most issues with controls come from impatiently throwing your hands around, without paying attention to wrist rotation, There''s a large discord community that are ready to help you. \nOnly one problem with this game. The active player base is small, so finding a live match outside of US Eas', 'The game is truly great. However, the incredible small player count makes it very hard to play unless you’re carried by the more experienced players. You’ll mostly be put in matches with very experienced players after waiting up to 30 min for a match. The community is very welcoming but always feeling like the worst player just isn’t fun and not being able to fight against similarly skilled players is Unmotivating. I sincerely hope the player base rises and the game succeeds because its one of t', 'Very Positive', 88.30, 88.63, 1.62);
INSERT INTO reviews VALUES (30597, 890570, 145, 'For what it is, its neat. This game is unfortunately most likely lost in development hell. Dev seems like a solid dude though - pick it up if you want a few hours of shoot em'' up hardcore goodness.', 'This game is pretty cool, but the dev abandoned all social media in 2021 and he''s from France. France isn''t exactly a safe or stable place these days, so the possibilities for what happened to him are endless. No idea if he abandoned the game or visited Paris on the wrong day, but based on the themes expressed within, he could just as easily be a political prisoner jailed for promoting subversive ideologies.', 'Mixed', 68.97, 3.72, 1.38);
INSERT INTO reviews VALUES (30606, 890720, 1324, 'A beautiful meditation on the wonder of the world around us and the importance of keeping it alive.\n\nWhile this game, with its text-heavy exploration, abstract art style and not particularly exciting moment to moment gameplay might not be for everyone, If you are looking for a serene contemplative experience that lets your mind''s eye wander, it might very much be for you.\n\nThe way I unearthed the layers of this alien ecosystem, specie by specie, description by description, each one more evocativ', 'it''s essentially a text based adventure within a claustrophobic environment and with unwieldy controls.\nThis is not for me, I get that some people might like it.', 'Very Positive', 89.58, 12.88, 0.20);
INSERT INTO reviews VALUES (30618, 890970, 311, 'An excellent, bleak, Outlast-esque indie horror with several charming nods to Jurassic Park. Short, sweet, and worth the price tag if you enjoy dinosaurs, violent content, and shitting your pants.', 'Had a few good scares, but overall was a bit disappointing. No master volume slider so no matter what I adjusted, the game was super loud. Had to repeatedly mess with graphics settings because it was very unoptimized; for a game from 2018, I should be able to run it easy, but I had to fight it.\nSome jumpscares used suuuuper old noises(old slenderman game noise, etc.). \nHonestly felt like a game two friends slapped together while learning Unity and using premade assets.', 'Very Positive', 84.89, 1.53, 1.32);
INSERT INTO reviews VALUES (30637, 891370, 140, 'Long long journey on the same maps with the same cards and the same (some) characters, \n and with the same sound effects. Avarage, playable card game. it is good for a sleeping pill too.', 'A Rogue-lite deck building game, which unfortunately works against its own mechanics. Combat is simplistic, each card has an energy cost and an effect. But the more cards you unlock, the worse the experience gets, because many cards in the same tear have the very energy cost and effect as well as rarity, but are just slightly worse than cards already unlocked. I.e. a card that does POWER + X damage, and another one that does POWER + X + 2 Damage for the same energy cost. This needles redundancy ', 'Very Positive', 80.00, 10.42, 23.12);
INSERT INTO reviews VALUES (30645, 891510, 106, 'The game is very simple since it just have two endings. If you want a good, short visual novel without complicated route-finding, this is it.', 'An extra addon for adult content and they only kissed? A kiss ? Rly ???', 'Very Positive', 87.74, 7.17, 2.93);
INSERT INTO reviews VALUES (30680, 892860, 181, 'A cautious recommendation.\r\nThe idea is good and the execution doesn''t lack much but there''s a key issue in that the most engaging this game was is after already beating it.\r\nHaving ranged non lethal options really takes advantage of the strongest part of the game, the middle ground of aggression with restraint. A lot of levels felt like that simply wasn''t a realistic option when all you had was a hand taser, with the ranged options it becomes possible and at least in my opinion, a lot more fun ', ' you can''t shoot, punch, flash or zap enemy or MISSION FAILED all you can do is walk behind enemy as they keep running away shouting SURRENDER as if one day they will', 'Very Positive', 83.43, 14.18, 2.48);
INSERT INTO reviews VALUES (30686, 892970, 243782, 'Crafted the best armor, then got one-shot by a falling tree. 10/10', 'Very good game until the Mistlands and the Ashlands.  Mistlands  is a navigational nightmare that is tedious to the point of quitting.  Ashlands is a non-stop monster slog that is likely to get you soft-locked in a death loop.', 'Very Positive', 94.96, 421.25, 394.93);
INSERT INTO reviews VALUES (30691, 893030, 867, 'cool', 'I like this game, I really do but I really wish they make an update where they fix the Youtube plugin. I really wanna play my favorite songs and drive to the beat of them. But everytime I try to play a different song, I sit here and wait almost an hour or more to just see it sit there and say "Converting to audio". Can there please be an update for that??? I''m only able to play one or two songs. PLEASE UPDATE AND FIX THE YOUTUBE PLUGIN', 'Very Positive', 80.51, 1.02, 37.75);
INSERT INTO reviews VALUES (30692, 893050, 458, 'Game is bugged, I can never win online, not even once. please fix. :(', '"Play Online" is false. Most (if all) games are done by bots.\r\nAnd for further proof, game continued when I cut the Internet.', 'Mostly Positive', 78.82, 5.40, 12.17);
INSERT INTO reviews VALUES (30699, 893180, 3850, 'Baiting players with promises of nudity and sexual content to lock them up in hell and force to solve 3D puzzles under time pressure. \r\nGood job devs. 10|10, highly recommending.', 'What an incredible abortion of a video game. Have you ever wanted to role play as a cowardly piece of work that has a certain amount of time each day to try and stitch together some semblance of an adult human knowing that he will make everything worse when you''re not directly affecting his life? No, that''s insane? That''s what I thought But someone at Atlus convinced Very Serious Business People of the concept, and then hundreds of people made a video game about it.\r\n\r\nI have never seen a video ', 'Very Positive', 91.22, 16.22, 22.35);
INSERT INTO reviews VALUES (30720, 893680, 2412, 'I''m a big fan of this game. I feel this is the kind of game I want to create. There are probably better boomer shooters out there, but this one made me think a lot in 2018.', 'ending levels made doom tnt reviloution seem easy, truly this game is the tianamen square of doom games, solid until the final levels crush you under their tire tracks', 'Very Positive', 88.02, 11.55, 3.08);
INSERT INTO reviews VALUES (30723, 893720, 187, 'Had a mental breakdown figuring out the puzzle and accidentally solved it while laughing hysterically\n\n10/10 - would breakdown again', 'It''s good but it doesn''t have a certain vocal range. I''m trying to sing along with it but the detector it just keep going up and down wrong like I sing high it goes low and I sing low it goes high.', 'Very Positive', 88.77, 5.23, 3.65);
INSERT INTO reviews VALUES (30724, 893790, 256, 'Go gay boy!', 'idk good game but i think u should change the cover', 'Very Positive', 93.75, 7.45, 3.38);
INSERT INTO reviews VALUES (30727, 893850, 3530, 'The Longing for me wasn''t a game; it’s an existential partner that sat quietly with me as I worked, procrastinated, and questioned what it all meant\r\n\r\nThe shade became my silent coworker, a pixelated companion who never judged my productivity or the number of times I alt-tabbed to check emails or minimize it on a meeting call. Like a Tamagotchi for introverts, it needed just enough attention to remind me it was there but never demanded more than I could give. we explored caves, read books, and ', 'Not for me, sadly. \nRight off the bat, I think I read too much hype about the game being this one-of-a-kind "experience" and went in with expectations to have my mind blown. The concept of The Longing is very unique, problem is I''m someone who cares a lot about efficiency and detailed planning (neurodivergency ftw!!). So, naturally, I hyperfixated on grinding the Shade''s home decoration until time was suddenly going 15x normal speed. I panicked that everything was going too fast and I was doing ', 'Very Positive', 92.58, 1313.62, 40.70);
INSERT INTO reviews VALUES (30736, 894020, 9530, 'Runtime to 100%: 11h40m\r\n\r\nExcellence all around. The pacing is great and the entire experience feels inspired.  A challenge when it needs to be but seems to actively avoid trying to irritate the player. I would imagine if you liked Ori youd like this. Highly anticipating the next game the devs work on. 9/10', 'A great 2D Zelda-like marred by being too souls-like.\n\nI know some people really enjoy souls-like games, I do not, and Death’s Door is the perfect reason why.  Everything else about it, makes it a game I should love, a very 2D Zelda like game. The problem with Death’s Door is even when you take the time to go on the side quests to improve you character to hopefully give you an edge in later battles it never really makes a difference,  You never really feel like your character has gotten more pow', 'Very Positive', 94.01, 16.08, 16.60);
INSERT INTO reviews VALUES (30755, 894630, 301, 'Had a lot of fun with this one.  Each faction fleet seems to have a gimmick that makes it very strong if played to advantage.  For instance I only lost a handful of ships in my first grand master win using the Imperial fleet, and my Royal fleet games usually went without a ship loss until late game regardless of difficulty level.\n\nIt plays more like a board game since you only have one move a turn to base your strategy around.  The other factions like you also get one move a turn, and the Empire', 'I wanted to like this game, and may still enjoy it on occasions after work, but it is a space tactical combat game pared down to its actual barebones and not built up from there much at all. The direction of attack doesn''t matter, movement barely matters, targeting aspects of a ship isn''t a thing. Just a couple of minor tweaks could have made this a nice, basic strategy game, but it just isn''t there. Clearly, this won''t be seeing any changes going forward. I don''t regret giving the game a shot, ', 'Very Positive', 81.06, 1305.33, 28.53);
INSERT INTO reviews VALUES (30764, 894940, 5019, 'This game was advertised to me as something to scratch my Stardew itch, and because of that, I grew disappointed and bored. This game is not like SDV. It’s not even a farm sim. If you want a Stardew clone, look elsewhere. But once I realized what Littlewood actually is, I enjoyed it enough to put in 70 hours and get all 60 achievements. This game is a cozy, repetitive, low-stakes grindfest, with cute pixel art and enough lore (if you talk to the characters and read the item descriptions and othe', 'game has been abandoned by devs, controls get stuck and is full of bugs', 'Very Positive', 93.48, 70.70, 0.23);
INSERT INTO reviews VALUES (30772, 895200, 161, 'I think the game has a lot of potential. A few times I felt like I was playing Dark Souls in VR. The swordplay feels nice, but could be a bit more refined. Adding different environments might change things up a bit. Only thing i found to be disappointing was that voice chat never seemed to work in multiplayer so far. Would be nice to hear my teammates.\n\nOverall, I enjoy the game and will continue to play and recommend as well.', 'Is this a joke? Giving a promise for an epic campaign and leaving us with wave clearing on 2 maps?', 'Mixed', 47.20, 1.47, 0.83);
INSERT INTO reviews VALUES (30776, 895400, 15599, 'Day Z for people like me who doesnt want to run around without a gun for 20 hours\r\n\r\nRust for people like me who doesnt want to hit trees with rocks for 20 hours and grind my life away\r\n\r\nFun PVP , good game. Weird its not more popular tbh!', 'Only purchase if you plan to play PVE servers only. On pvp servers players teleport into your base and take whatever they want, they teleport next to you and kill you, and they can change there names to avoid detection even if you do happen to get a video/screenshot to send to the devs. On top of all that the worst part is that legit players risk getting banned anytime they kill a player if that player happens to be a streamer / a friend of a streamer / or an admin on an official server. I can p', 'Mostly Positive', 77.05, 34.43, 197.92);
INSERT INTO reviews VALUES (30777, 895420, 104, 'Loved it. Highly recommend. Would love if there would be a sequel.', 'The entire game is unplayable for the MacOS Sequoia. After entering the first room of hidden objects, the whole screen is frozen, the click is not working, and the cursor gets stuck. Pitty :(', 'Very Positive', 93.27, 6.95, 0.68);
INSERT INTO reviews VALUES (30780, 895480, 118, 'It''s a very good indie game with a unique gamepaly idea', 'Was trying to ignore the bad pixel graphics i tend to want more art in my pixel games. Wasn''t really for me too blocky. And feel too locked into the story line. I wanted a more open world free from shackles experience so im refunding.', 'Very Positive', 89.83, 13.18, 0.23);
INSERT INTO reviews VALUES (30787, 895620, 1279, 'I really enjoyed this game and finished it once.  Just beware there are a decent amount of bugs still in this game.  Some of the card text contains strange code tokens in brackets.  What made me stop playing was game breaking pathing bugs where a teacher couldn''t figure out how to get to his classroom.  It would have been nice to be able to load a previous save, but this is a rougelike so you can''t do that.  I would still recommend, but watch out for these bugs!', 'i love the game but there are so many frustrating and bad designs in the game that makes me wonder if the developers even plays it.\nthere are no way to delet/demolish placed rooms, and there are no ways to delet an established house that might be identical or even worse than one already excisting, and there are no way to recolour their emblem.\nevents when looked at early can not be closed so if you are 1 or 2 points behind on haveing a favourable out come on the event you are just shit out of lu', 'Very Positive', 81.00, 29.58, 43.48);
INSERT INTO reviews VALUES (30797, 895870, 10607, 'shoutout to unrealistic modern military games with anti war themes\n\ngotta be one of my favorite genders\n\nedit: someone gotta get crimson 1 therapy holy shit', 'The 2.0 update completely breaks VR. The new clouds are abysmal and tank FPS like crazy', 'Overwhelmingly Positive', 95.14, 21.65, 14.83);
INSERT INTO reviews VALUES (30809, 896160, 852, 'When are they making Part 2?? I have an alt account with family sharing, I have more hours than it appears. This is an amazing concept of even a modern game. Back when it was new, it was a pretty cool game. It has a lot of what I want to play, it just needs an updated Part 2.. Please remake this.. It''s very satisfying taking over the world as a bank. I already figured out how to win the game 100% of the time though. Literally just start up like any company would, prioritizing loan capabilities. ', 'Though it scratched the itch of "number go up" for a bit, this game is simply a mess of barely connected systems that are barely explained at all. The biggest issue is the lack of information. This is a banking game and you cant even see your income per turn...', 'Mostly Positive', 75.59, 25.47, 5.75);
INSERT INTO reviews VALUES (30822, 896440, 224, 'I am eternally edging', 'So, I like the game, I do. HOWEVER when you have the bug of getting a white screen at boot-up...it never goes away. No uninstall and reinstall fixes this, backed up my save data and deleted the it from the folder, nope. I have some decent progress, and this is excessively annoying. I can get over the jerky aiming with the gun, I can get over the bonuses from the equipment not functioning outside of self-debuffing, and I can get over the the massive empty space of the various regions. What I can''', 'Mixed', 67.86, 0.35, 5.70);
INSERT INTO reviews VALUES (30823, 896460, 338, 'Given the current climate, honestly something to play and take to heart.', 'I can accept a game having an abstruse user interface, or vague or dreary exposition, or a soundtrack that could be a chimpanzee playing with an oscillator, even come to love them for it, but a game whose visual style is migraine-inducing, makes the game world a chore to navigate and combat hard to read has pushed the bounds of what I''ll tolerate. There''s probably a decent game in here, but if so it''s hidden inside an aesthetic that I for one cannot digest.', 'Very Positive', 93.79, 62.40, 1.42);
INSERT INTO reviews VALUES (30825, 896520, 754, 'this game depicts the average experience of living in Oklahoma.', 'I liked the gas station section far more than the infuriating and unfair hide-and-seek styled, over-complicated house puzzles sequence which encompass the majority of the game. It feels like the game is much scarier and more atmospheric with the gas station. Sure, the house part is tense, but that feeling of tension quickly dries up and turns into a mess of inundated design choices.', 'Very Positive', 93.50, 0.72, 1.23);
INSERT INTO reviews VALUES (30830, 896750, 154, 'Koral is a beautiful adventure game with some colored levels and a relaxing ambiant. I recommend it!!! 💗💗💗', 'Really wish there was a neutral option on Steam. This a beautiful looking game, and I very much appreciate the intention, and the environmental message. I was also finding it very relaxing/chilled until 2 things happened: \n1, the introduction of timed puzzles in chapter 6, which were a bit annoying and broke the mood\n2. a game breaking bug in chapter 7 that meant I got permanently stuck behind a rock and couldn''t continue\n\nA real shame.', 'Mostly Positive', 78.57, 33.00, 1.92);
INSERT INTO reviews VALUES (30836, 896890, 691, 'It''ll save you money \r\n', 'Very unstable. On Quest 3 runs, but with frequent crashes.', 'Very Positive', 86.83, 65.33, 0.83);
INSERT INTO reviews VALUES (30846, 897030, 1013, 'it''s hard to explain why, but this is one of my favourite games ever. it''s not particularly exciting mechanically or easy to understand. but there''s something about its atmosphere, its deeply harrowing electronic reverbs, its distant lights, its distorted visuals, its constant cuts and jarring sound design, that appeals to me a lot.\r\n\r\nthis feels like driving down a highway and taking a stop in the middle of nowhere, in a small gas station in the middle of the night. nobody is here, but you feel', 'The atmosphere is cool but it''s too boring and short even for $3, also the jump cuts were a dumb idea and the whole thing is paced badly. Just skip', 'Mostly Positive', 79.96, 2.90, 0.77);
INSERT INTO reviews VALUES (30852, 897220, 622, 'Good game, but i reccomend downloading the Reflection Blue version of the game which can be found on DLSite, it has a fan translation (which is very good) and adds a bunch of new story to the game (new routes for the girls, better ending, more history of the island, more ost)', 'bros are out of ideas for their visual novels, I guess', 'Overwhelmingly Positive', 96.30, 2.17, 6.40);
INSERT INTO reviews VALUES (30859, 897410, 321, 'NA finally won a moba WORLDS!', 'It''s more interesting to kick a bucket than to play in this game where the only thing you have to do are 4 clicks.', 'Mixed', 61.37, 1.65, 1.83);
INSERT INTO reviews VALUES (30862, 897450, 2753, 'I love playing this game with my son, it connects us and it''s fun. It''s nice considering he''s 13 now, but this is one of the ways we hang out :) forever thankful!', 'The game was abandoned several years ago. They took down their road map, leaving lots of content out of the game', 'Mostly Positive', 76.93, 8.18, 9.40);
INSERT INTO reviews VALUES (30872, 897730, 1445, 'I understand people saying it''s not finished and being upset that it''s abandoned, but its rainy outside and I wanted a chill pretty game to unwind without characters and their problems or high stakes QTEs. I play on hard mode so the simple things I can do are still satisfying. I''m happy with a little cabin I can decorate and a pet fox. \n\nI may not lose myself in this game for hours and weeks at a time, but sometimes all you need is a little bite of an experience here and there when you''re in-bet', 'Beautiful game that has loads of potential and was abandoned by the developer years ago.', 'Mixed', 66.23, 11.52, 8.75);
INSERT INTO reviews VALUES (30877, 897820, 256, 'Better than season 8.', 'I wasted 12 hours trying to 100% the game and I just reseted on ending, It''s such a slop of a game, most of the time you brainlesly go through cards for a small chance of getting an event you actually want or need, the outcomes are wild and totally unpredictable most of the times, endings don''t make sense, characters don''t make sense (just check endings if you want to see why) I regret buying this game so much, huge time sink and waste of time', 'Mostly Positive', 71.88, 833.57, 30.92);
INSERT INTO reviews VALUES (30883, 897930, 182, 'Sir Brash is the best overly manly tsundere. Other than my absolute love for that man the game play is really fun so fun that I can see myself finishing this game pretty quick and that''s bad because my sweet a$$hole Sir Brashy baby isn''t in the third game :''(', 'I adored the first Demonheart game. Loved it to the point that I bought this without a second thought. I enjoyed this one... enough. The plot was good, but it took ages to get through the meh maps. I made it through one run before I set the game down. The first game is one of the few games I''ve 100%ed. Would I buy it at full price? No. Would I have bought it if I hadn''t been so invested in the characters after the first game? Also no.', 'Very Positive', 84.07, 72.18, 12.32);
INSERT INTO reviews VALUES (30908, 898450, 143, '8 из 10\nРекомендую', '.', 'Very Positive', 93.71, 4.70, 0.38);
INSERT INTO reviews VALUES (30913, 898580, 342, 'When life''s got you feeling down because a man has just micturated on your rug that really held the room together, Premium Bowling is a good place to be. Just remember to not step over the line, this isn''t Vietnam, there are rules.', 'having the first major update in months turn out to be a dumbass DLC is reserved for AAA games only', 'Very Positive', 93.57, 3.85, 16.98);
INSERT INTO reviews VALUES (30914, 898650, 385, 'to be fair, quite good. 8/10 plot was decent, acting a bit cheesy but overall fun play.', 'Not bad, but an ultimately mediocre FMV. I am giving it a thumbs down due to some unnecessary padding (~3 seconds transition after every interaction, gets really annoying over time) and no checkpoint / replay chapter option, so you have to replay the whole game to see different endings.', 'Very Positive', 82.60, 5.33, 4.28);
INSERT INTO reviews VALUES (30918, 898720, 335, 'Ive been enjoying this one.  Some people are calling this game abandoned when it''s actually just complete.  Not sure why everyone expects patches until the end of time for a game.  Also you do not start over for each island in the campaign. You have a boat that gets loaded up with most of your important stuff that was acquired during the last mission. You also get optional islands that allow you to gear up and leave any time you want (I always treated my colony to a nice vacation during those. l', 'this game has been abandoned,\n\nlast update is August 2022.', 'Mostly Positive', 78.51, 12.50, 6.37);
INSERT INTO reviews VALUES (30919, 898750, 1458, 'This game has given me the biggest, goofiest grin I have had in a long time. I feel like a kid getting all the action figures out and just smashing them together in some wild storyline I make up as I go along. Only drawback is now it''s adding to the endless backlog of series I want to watch!', 'A rotten company with racial discrimination', 'Very Positive', 94.86, 131.03, 33.92);
INSERT INTO reviews VALUES (30922, 898800, 163, 'I played the first version of this game back in the 1990s and it was one of my favorite games. 20 years later one can realize that a well-designed game is timeless. This game is as fun to play today as it was back in the 1990s in spite of all the alternatives that exist today with better graphics. They should do a reboot of this game and give it a Godfather theme. It would be amazing.', 'Im coming from playing Mob Rule/Street Wars from my Childhood \nIve never played constructor so i decided to give this one a try.\nI think it will please anybody who has played constructor before, but it wont if you only have played Mob Rule/Street Wars.\nYou see, while the same soul, humor and systems are present, the motivation and goal is completely different. In fact, there are most systems (like the undesirables) that make more sense as a mobster than just a corrupt builder. So that got lost. ', 'Very Positive', 87.73, 2.88, 2.73);
INSERT INTO reviews VALUES (30925, 898890, 1198, 'Endling: Extinction is Forever is a visually beautiful game with a heart touching journey and a unique perspective. The simple controls allow you to take in the world and manage the stress of the situations without it being overly complex. The story is depressing and at the same time full of hope. The developers have done a beautiful job creating situations that make you feel attached to your fox and her cubs. Endling is a charming survival game carrying an ecological message; bringing awareness', 'The world is bleak and propagandistic.\nThe story is masochistic. I''ve seen a lot of actual animal suffering in my life, and I have no desire to live through it in an immersive game.\nThe (4 hours of) gameplay loop is okay, but relies too much on built-in save-scumming to deal with hard-to-avoid deaths, rather than letting the player outsmart a clearly perceived world.\nSome annoying achievements basically require guides to finish. I put in 3 additional hours to 100% it, and the 2nd playthrough was', 'Very Positive', 94.66, 5.00, 7.53);
INSERT INTO reviews VALUES (30927, 898920, 3966, 'Over 1000 hours into this should tell you something. Great game. Only thing i wish it had, would be better AI. They use pretty much the same strategy each game. I understand the game is meant for online play and the solo is more for learning the game, but some of us don''t like people. HAHA  Like i said, this is the best A&A game out there on PC', 'Have you ever played a game that makes you sooooo mad that you want to break your controller? Well, this is one of those games. This game is SO rigged that you will quickly feel like the game hates you, the developers hate you, your mom hates you, and even your dog hates you now. This game is one of the most frustrating games I have ever played in my life. I would not recommend this game to anyone with behavioral disabilities, there is a good chance something will get broke. I remember playing t', 'Mostly Positive', 78.42, 1269.12, 351.65);
INSERT INTO reviews VALUES (30943, 899310, 261, 'The mechanic for this game was fresh and interesting.  The game itself felt short - I was disappointed at what felt like the narrative cutting off in the middle in a way seemed set up to sell DLC.  I enjoyed the game, however, and would play more if it were available!  There were some bugs - especially with being able to pick up interactable objects.', 'no graphics options \r\nfull screen blur like you can''t see anything at all', 'Mostly Positive', 77.01, 33.92, 0.33);
INSERT INTO reviews VALUES (30945, 899390, 220, 'I like everything about this game, except for having to start in a hoop-dee that can''t drift.', 'nah,,,,   looks bad plays bad nothing interesting Im sure I could find better free racing games then this dont buy', 'Mixed', 66.36, 19.48, 0.52);
INSERT INTO reviews VALUES (30946, 899440, 2979, 'I never played the game.\n\ni only got it to play dress up as a woman \n\nIn the game menu \n\n10 / 10', 'Purchased and downloaded the game a while back and just fired it up for the first time today with great surprise. This game is somewhat racist. Upon creating a character, I found out that you can make your character as pale/white as a cloud but the darkest you can be is RED. As a gamer of rich colored skin, I was offended to see the disdain in having a dark brown/black skin tone selection. Bandai can do better.', 'Very Positive', 86.91, 2.25, 0.58);
INSERT INTO reviews VALUES (30957, 899770, 55478, 'Within minutes of playing a Void Knight Sentinel, I realized something important, I had been gaslit by game design for years. This game respects my time, and build choices. Each ability has its own specialization tree, meaning you’re not just choosing skills—you’re shaping them. My Void Knight doesn’t just deal damage; he travels through time to delete problems before they happen. Sometimes I don’t even know what I killed. It just stopped existing. \r\n\r\nFeels like a power fantasy where the devs a', 'As a fan of ARPGs, I was excited to try this based on the reviews and recommendations. The build customization is awesome and I like the emphasis on crafting. However, I just couldn''t get into the game as it never felt like there was any threat of dying or being skill-checked with my build. I just felt too overpowered and was bored with the gameplay and story. The game failed to hook me at six and half hours, which should be ample time to get into most games. I''m fine with the loss of $30 becaus', 'Very Positive', 85.18, 451.67, 11.18);
INSERT INTO reviews VALUES (30961, 899970, 883, 'I mean its like fortnite', 'It''s Nekopara but the main girls are little kids. Unless you''re like me and unironically played these games for the stories and 100%s with zero interest in the sexual stuff then I''m worried most players of this game belong on a watch list', 'Overwhelmingly Positive', 95.47, 2.10, 1.00);
INSERT INTO reviews VALUES (30963, 900010, 452, 'I like the relaxed nature of the game, along with the ending. Truly incredible.', 'Purchased on kickstarter, abandoned by devs. Overall regrettable experience.', 'Mixed', 60.18, 62.27, 10.55);
INSERT INTO reviews VALUES (30964, 900040, 1340, 'After playing Elex1 I found the start of Elex2 Strange and a bit clumsy. After playing thru the whole game I found that the game is technically a "classic" Skyrim and Fallout4 are my all time favourites. However playing them takes a long time. The 2 Elex games are much shorter... and offer a wonderful challenge as well as thought provoking story line. I will be 80 in 6 months so do not have the dexterity to play them at high difficulty levels. But it forces you to devise battle strategies if you', 'Not as good as the first game, which was not as good as Risen, which was not as good as Gothic.', 'Mostly Positive', 71.72, 4.18, 13.60);
INSERT INTO reviews VALUES (30967, 900270, 2289, 'interesting adventure game where your goal is to die and find new paths and different endings. i was impatient so i used a video walkthrough guide, but if you plan on exploring everything yourself you can easily get double my amount of playtime (if not more) out of it.', 'The devs have scammed their community by not finishing the board game that they kickstarted and they are refusing to refund anyone for it. Genuinely great game, but fuck them.', 'Very Positive', 92.92, 8.60, 4.20);
INSERT INTO reviews VALUES (30974, 900400, 365, 'These days, it is difficult to find a good visual novel game that isn''t porn.\n\nSacred Fire gives you an excellent story where choices really matter. Only downside is that they made me wait for the release for ages.', 'Really beautifully done game, with intriguing mechanics, and a very well-done and elegant story line.\n\nThe only problem is that the game is incomplete; I played to the end of Act 2, reaching an intriguing climax, and then was told "wait for the final conclusion coming soon." Most of the story had yet to unfold (intriguing strangers, and a late introduction of a royal family.)\n\nOnce they actually complete the game, I think it will be terrific. But I would say wait.', 'Very Positive', 94.79, 12.22, 5.97);
INSERT INTO reviews VALUES (30977, 900883, 30889, 'Im just here reading comments, hoping you young guys got the inside scoop on the remake. i''m 38 years old and it kinda feels like this game and ES6 may be the last games i enjoy. Not sure yet if that''s from me aging or the quality of games with good story telling has gone down the crapper. Prolly both.. Sure hope they put this out soon!', 'Poorly optimized game with a boring setting, uninteresting plot, and a broken level scaling system that makes the game unplayable long term', 'Overwhelmingly Positive', 95.58, 34.23, 259.30);
INSERT INTO reviews VALUES (30980, 901147, 106, 'COW LAUNCHED!', 'Way too expensive for what''s offered. These are the dos versions of the games, not the snes and n64, running on dosbox meaning there''s no direct controller support. Also, games 2 and 3 aren''t that great. If you really want to play these games I''d suggest you avoid this release and find other means to play them', 'Mixed', 41.51, 1.13, 0.20);
INSERT INTO reviews VALUES (30981, 903040, 150, 'Love this game.  It is super fun.  It''s pretty well done and is a good representation of the board game.  The only con I really have about it is the seed they used to create the random dice roll generator.   It''s just plain horrible.  As a general rule I get doubles at least four to five times in a row every time I play.  And in this games, doubles are rarely good. Otherwise, they did a good job and if you enjoy the tabletop version of the game, you will like this one too.  And if you are findin', 'Fix the bugs :(', 'Very Positive', 83.33, 73.77, 3.13);
INSERT INTO reviews VALUES (31008, 903950, 10933, 'A wonderful and exciting new concept that was poorly executed. A fresh start with a new dev team would bring back the player base, I know there is a large pool of people that love/ would love this game and its emerging genre.\n\nDon''t let the flame die out!', 'Note: The last update made by the developers was over 2 years ago. The information and timeline described by the developers here may no longer be up to date.\n\nThank you Valve for doing this at this point the game still costing money is a scam.', 'Mostly Positive', 70.17, 107.05, 54.55);
INSERT INTO reviews VALUES (31018, 904360, 202, 'Family man is a weird goofy game that makes you want to play more and more to see ever possible result of your actions. Fantastic game totally worth adding to anyone''s library', 'This would have been an interesting little game if it wasn''t for the TIME LIMIT. \r\nSeriously dev why would you put TIME LIMIT on a game where most of the missions involved figuring things out for the players themselves?\r\nYou also have to watch the stats of your family household which consumes time and money while finding money to pay for your debt in a very small time frame. Such a waste of a game.\r\n', 'Mostly Positive', 76.24, 12.88, 1.92);
INSERT INTO reviews VALUES (31019, 904380, 201, 'i played while not having experienced darkest dungeons.\n\ni read there were lot of issues when the game first launched, but as i played this on august 2024,  no particular balance or RNG issues (game was a bit on the easy side, i played on normal).  \n\ni had fun playing this, really liked that the devs put extra arts to go with the different costumes (the columbo and sailor moon were funny).\n\n', 'I like the idea of Darkest Dungeon, but with more story focused and beautiful art. What I dont like is no real roguelike mechanics or RPG mechanics - meaning that there is no possible way to get better, apart from buying new equipment. For example, I went through the whole dungeon to confront first boss, and it wiped my whole party, alright then. I thought I will get better things and try again, well, all the money I had was used just to buy health items to make it to the boss again and it wiped', 'Mixed', 67.66, 11.17, 14.83);
INSERT INTO reviews VALUES (31027, 904520, 225, 'incredible story, one of my favorite visual novels.... it''s not that hopeless like people paint it to be. i would say it''s very romantic. let''s slay the spirit of gravity together', 'Eh... if I wanted to be in an emotionally abusive relationship, I''d stop playing dating sims and download tinder.\n\nI honestly think this needed to be edgier. Instead, it was just a bunch of abrupt and terrible endings.', 'Very Positive', 82.67, 66.82, 13.12);
INSERT INTO reviews VALUES (31029, 904540, 228, 'Feels kinda weird to say it, but this was among my most memorable gaming experiences of 2024. I love the hell out of this game, absolutely adore it. It''s clunky, and it''s slow, and it''s often obtuse in the fashion of classic point-n-click games (I needed a walkthrough for most of the game), but... somehow, that all washed off me while playing. Instead, I felt transported by the adventure, constantly surprised by its scale - it took me 30 hours to beat. The opening chapters exploring ancient Baby', 'The controls make this unplayable. Indy moves so slow and I keep getting stuck on nothing and I have to look up a walk through because I get stuck every 5 seconds. I''ve played this game for 30 minutes and I keep dying over and over. Even when I look up what to do it''s still hard. I love the old graphics and voice acting and music but the game is so unplayable I can''t recommend it', 'Mostly Positive', 79.82, 29.63, 0.50);
INSERT INTO reviews VALUES (31030, 904570, 110, 'Cool game with nice music and easy trophies. Cheers', 'I don’t recommend this game — it feels more like an interactive piece of art than an actual video game, and not a particularly good one. Some levels do look nice, both at the start and once completed, and the background music is decent, but that’s about it.\n\nThe real issue is the complete lack of challenge: going through all 90 levels felt dull and repetitive, more like a chore than an engaging experience.\n\nEverything in the game seems designed to slow you down: tiles rotate slowly, you can’t cl', 'Very Positive', 89.09, 0.83, 1.12);
INSERT INTO reviews VALUES (31037, 904750, 206, 'This game not only allows you to see dinosaurs, interact with dinosaurs, and collect many facts about dinosaurs, it also allows you to be a dinosaur.', 'The game is cute but the story and characters aren''t interesting enough and the world feels very small. I was quite disappointed when I realized the game was ending by the time I made it out of the underground part because I was itching to explore the rest of the surface.\n\nThe story is too tame and uncompelling. I know it''s supposed to be family friendly but I didn''t ever feel like there was any real danger in the story conflict. There was not much buildup or intrigue; all I knew was I was tryin', 'Overwhelmingly Positive', 99.51, 11.82, 12.55);
INSERT INTO reviews VALUES (31049, 904960, 264, 'It is such a difficult software to use and lots of stuffs are missing. They should have put up a trial version to try and see if this is what they are looking for. Expecting a refund asap. Please don’t not buy if you are looking for a easy Cine lighting setup solution', 'This Sim has potential to be a great sim. At its current state and current price I would highly reccomend you wait until it is no longer an early access.', 'Mostly Positive', 70.45, 2.08, 0.60);
INSERT INTO reviews VALUES (31066, 905340, 1008, 'dont play with ur daughter or she will kill u', 'No online co-op. Why, just WHY??\n\nSteam Remote play isn´t working either.\nSuch a funny game ruined by no online play support\n', 'Very Positive', 92.66, 5.87, 0.18);
INSERT INTO reviews VALUES (31075, 905490, 160, 'It''s an interesting idea. The graphics are cute and fun. After you unlock a few cards there ends up being some good variety. The hidden combo system is an interesting innovation and pretty fun.\n\nHowever, the upgrade system needs an overhaul. It encourages you to stall every single fight, which leads to a huge boring grind early as you stall and stall to focus on leveling up your cards. Hitting into shields to upgrade your attacks, overdefending to level up your defense cards. Stalling to level u', 'unfinished, abandoned garbage', 'Mixed', 58.75, 11.05, 1.95);
INSERT INTO reviews VALUES (31095, 905970, 386, 'I hit my hand on my desk when turning the gun elevation', 'bought this game twice, first time i played it was when i first got vr, game lobbies were completely empty and void of any life, so i ended up refunding the game. about a year later i bought the game again, lobbies are still non existent, so i refunded it once again. it seems like a pretty cool game just the lack of players is really the only issue.', 'Very Positive', 85.75, 1.43, 0.37);
INSERT INTO reviews VALUES (31099, 906050, 123, 'blow my shit smoove off', 'Overall, the main feature of this game, being the images, aren''t in a high quality resolution. Other than that, its your typical case opening game with anime chicks. Wouldn''t waste a dollar on it if I were you, but if you do intend to purchase the game, just be mindful that your dollar won''t give you a whole lot of content.', 'Mostly Positive', 72.36, 0.60, 45.18);
INSERT INTO reviews VALUES (31100, 906100, 2335, 'We live on a placid island of ignorance in the midst of black seas of infinity, and it was not meant that we should voyage far. \n\n― H.P. Lovecraft, The Call of Cthulhu \n\n\n끝없는 암흑의 바다 한복판에서.', 'This game is essentially impossible to play. It only saves at checkpoints, and the checkpoints are so far apart in gameplay time that almost all my playtime so far has been spent re-doing things I did in the previous session. I just loaded up the game to find that my last two hours of exploration and progress have been lost, and I just don''t have the energy to retread my steps.', 'Mostly Positive', 78.89, 4.88, 39.28);
INSERT INTO reviews VALUES (31102, 906120, 216, 'this is what ur nan thinks video games are', 'Unplayable on Oculus CV1; no controls work and no fixes available. Tried to connect a controller but it did nothing. Unfortunate; the splash screen looked really cool.', 'Very Positive', 94.44, 0.65, 0.20);
INSERT INTO reviews VALUES (31135, 906930, 147, 'Very fun, It just needs to get more popular as this game is sitting on a goldmine. MORE ADVERTISING', 'played this game for awhile but these are also the people who made the survival wizard game that was left to die once the player count dropped a little im surprised anyone even touches this game anymore', 'Mixed', 61.22, 0.62, 50.15);
INSERT INTO reviews VALUES (31149, 907270, 101, 'Pretty good little sim that captures quite well how MOBAS work. \nThe EN translation is not always perfect, but gets the job done. Also, the writing has some nice humor to it.\nOh, and the whole game is strongly based on the eSports scene of LoL, so if that is your thing, you will like it even more because of the parallels and references.\n\nOverall, I was honestly quite impressed and really don''t understand why some people seem to dislike the game. Sure, it is no factorio/paradox game in complexity', 'This game is pretty mediocre.  1) if you don''t play and follow League of Legends E-sports, most of the references and most of the "quiz" items that show up every evening will be impossible.  The obvious champion list and pro-player names line up 1:1 with League, as does the map.  2) the translation is awful, and worse, many of the text areas are truncated.  Sentences (even important ones for some of the quiz items) are cut off and you can''t finish reading them, although trying to read them is pa', 'Very Positive', 82.18, 35.20, 9.97);
INSERT INTO reviews VALUES (31157, 907470, 333, 'nice atmosphere and artwork, decent puzzle mechanics.\r\nrelaxing without being boring.', ' The overall style is very nice, great to look at. Most of the puzzles were too easy and too many were like having to figure out a rubiks cube, which wasn''t enjoyable. Also the character moves way too slow.', 'Very Positive', 84.98, 4.88, 3.82);
INSERT INTO reviews VALUES (31164, 907650, 1815, 'For any Stronghold fan that isn’t sure if he wants to buy the game or not, since all the bad reviews of some people. First of all I played every Stronghold since Stronghold 1 to Crusader 2 and now SH: Warlords, so I guess what I’m talking about. The game is not bad as some people say, they played it for what 30 minutes to max 1.9h (so they can refund) and didn’t give the game a real try and just said its not Crusader or SH2 so their opinion that the game is “bad”, “terrible” can’t be counted, if', 'I feel dirty giving Firefly money for this, even on sale.  \n\nStronghold died long ago, please stop reskinning it and flogging the corpse. \n\nIn terms of a real review: The mechanics are almost completely unchanged from previous iterations, the maps are tiny and claustrophobic. Units, UI and buildings all lack crisp visual clarity, the voices range from insulting to a poor joke and for a 2021 release it feels like it walked straight out of the mid 00''s.  Avoid like the plague.', 'Mixed', 63.75, 106.22, 2.33);
INSERT INTO reviews VALUES (31165, 907670, 104, 'Underrated beat''em up. This is a funny and very well crafted game with a superb art style. It even offers the chance of replaying each stage to improve your scores if you are into it.', 'a 3 hour 2d bayonetta with one-dimensional combat', 'Overwhelmingly Positive', 98.08, 3.82, 3.32);
INSERT INTO reviews VALUES (31186, 908070, 293, 'This is a neutral recommendation. A bit tricky to pick up at first and pretty fun when you get it down (especially with all the expansion sets and new mechanics), but there''s not a lot of variety in win conditions. Generally speaking, stacking growth asap is the only path I''ve noticed that consistently wins games. The game is also not up-to-date on Steam as there are several expansions that have been added to the physical game and not updated here. Fun for someone that likes board games or card ', 'As an avid deckbuilder and card game fan, while the game itself is fun, the constant cheating by AI (playing illegal cards, taking cards they can''t afford, or just outright cancelling your actions) ruins the actual gameplay experience. That this becomes utmost apparant the second a human player is in the lead by as little as one point, is ridiculous.\r\n\r\nThis occurs mostly because the AI, even on it''s highest difficulty, is as useful as a box of hammers, making illogical, inconsistent actions tha', 'Very Positive', 89.42, 11.60, 15.87);
INSERT INTO reviews VALUES (31201, 908360, 364, 'This is it.\r\nUltima Underworld, Arx Fatalis, Thief and Dark Messiah of Might and Magic stand behind this amazing one-man project and nod respectfully in it''s general direction. Finally a worthy successor to the ''solo dungeon crawler with dark atmosphere'' genre.', 'In these kinds of games I typically play a mage, and if anyone else is the same, then this is not the game for you. The magic system is clearly an afterthought in this game. It''s obtuse, annoying, and difficult to grasp how to properly prep and cast spells. And dear god do you have a tiny mana pool, and it drains FAST. I was at intelligence 12 at the start, put some points in cognition, but I was still running out of magic at a pathetic rate. The tutorial is very bare bones and glosses over it, ', 'Very Positive', 91.76, 20.18, 1.40);
INSERT INTO reviews VALUES (31208, 908520, 1608, 'It works but just with SteamVR games. If you have an Oculus (Meta) device, you can open the debug tool, then on the HUDs section "Visible HUD" dropdown choose "Performance". Then you will get an FPS and headroom counter while u play.\nIt''s not developer fault, but I do not recommend it for meta users.', 'Where is my free fps in vr bro?', 'Overwhelmingly Positive', 97.76, 3.77, 122.03);
INSERT INTO reviews VALUES (31216, 908740, 139, 'The game idea es awesome, but is not beta, is kinda pre-alpha. Empty world, no servers at all, nothing, no pvp, only host ur coop game. The problem is this: has been 4 years and this is it? sad.\nbut with the special, is a good deal, to duel with friends and pass the time, but I want badly a survival full pvp base building extended crafting mode', 'Still beta testing? Come on man, it''s been 4 years.', 'Mixed', 59.71, 0.80, 0.12);
INSERT INTO reviews VALUES (31230, 909080, 284, 'Cube Escape is a true classic of flash games and each game expands on the story. One of my favorite franchises.', 'The amount of backtracking needed in the forest is just too annoying for me personally. The rest of the puzzles feels solid and a good concept put together with the Paradox short film. Good experience except for the backtracking as is an apparent personal issue I have with a lot of their games.', 'Overwhelmingly Positive', 97.89, 3.83, 3.25);
INSERT INTO reviews VALUES (31238, 909320, 986, 'While enjoyable and largely ''finished'', it''s a shame the game has been left in this state - it has so much potential for story telling (Rimworld style) but most of that capacity is unrealized even after all this time. Still, it''s a fun romp if you are psychopathic-minded and would enjoy ruining the lives of innocent villagers. Getting to 100% achievements was quite a slog (and then they added even more!).', '"We know it has been a while since our last update. After the 1.1 update, our intention was to keep pushing out updates to address the issues raised by our players. Unfortunately the truth is that the sales of the game were impacted by our poor V1 launch, and we had to make a hard decision to secure funding and focus on our next game to keep the company afloat. I’m sure a lot of you are aware of the layoffs and company closures happening in the industry right now, and we’re trying our best not t', 'Mixed', 62.78, 33.53, 26.30);
INSERT INTO reviews VALUES (31250, 909660, 1041, 'I am a South Korean who is not good at English.  Nevertheless, I wanted to play this game, so I bought it along with the DLC.  I tried to play using an automatic translator, but I couldn''t do it because of the errors that kept coming up.  \nSo I earnestly ask you to do so.  It doesn''t matter whether you use Google, Papago, or any other translator, please support Korean within the game itself.\n\n저는 영어를 잘 못하는 남한인입니다.  그럼에도 저는 이 게임을 하고 싶어서 DLC와 같이 구입했습니다.  자동번역기를 사용하여 플레이하려 했지만 계속해서 나오는 오류 때문에 도저히 할 ', 'The grind is too real here, might as well be a second job. There is too much monotony. You are basically forced into being a boring caravan merchant, attempting to play the game as a mercenary or explorer is pointless as a starting role. Unless you like save scuming you will have a run of bad rolls and have to restart. Your companions are very weak early and anything you do will piss off someone to the point one will eventually leave. Leaving you with a more grind to get to the point you can go ', 'Very Positive', 84.05, 74.12, 12.15);
INSERT INTO reviews VALUES (31254, 909820, 228, '7/10\n+ story\n- bird ass cheeks.....why would you animate those???\n+ music\n+ light platforming puzzles\n- no map\n- every button prompt is the same color, shape, and size', 'Story is charming and character designs are cute. But environment art and design is too simplistic and tileset-ty. Sounds like a family-friendly game and yet, I feel the game might too hard for kids to play even though you cannot fail in this game.\n\nFor a rhythm game, lacks quality of life that many rhythm game has. No callibration, can''t rebind keys, and bad visual clarities that can''t be editted.\n\nThere are many songs in the game and the songs are fine. Uniquely, the song are designed to be si', 'Very Positive', 88.16, 7.68, 8.23);
INSERT INTO reviews VALUES (31257, 909970, 134, 'good game', 'Sad Abandonware Would have been a cool game.', 'Mostly Negative', 26.12, 3.25, 1.02);
INSERT INTO reviews VALUES (31277, 910450, 143, 'I recommend it, but only if you have a good tolerance for grind and unnecessary unbalanced shenanigans. Still, it can be a fun little run.', 'They really need to cap ambush spawns. i had 3 people who would hit 1 out of every 4th attacks then during a big fight i get ambushed twice. i think they came 3 turns from each other. how am i expected to fight 8+ enemies as 3-5 more spawn every 3 turns with characters that have x-com like accuracy. ya, sorry i''m not dealing with this crap. if RNjesus decides it, you''re parties dead.\n\nplay 1 but skip this. there are other issues but this is the one that did it for me.', 'Mixed', 50.35, 4.20, 1.43);
INSERT INTO reviews VALUES (31280, 910490, 1242, 'Game is good solo. A little hard at the end.', 'Meh.\n\nNo multiplayer.\n\nRefound requested.', 'Mostly Positive', 74.32, 12.12, 2.22);
INSERT INTO reviews VALUES (31285, 910630, 387, 'Oh man, I found this game via an interview by DarkTeaTime''s interview with Stefan Gagne about games that offer features and options for Asexual gamers and honestly don''t tend to do a ton of graphic novel like games, but decided on a whim to give this one a try and it was exactly what I needed. \nDespite not playing many text/choice based games like this, the ones that I have tried in the past often felt a bit isolating because I couldn''t relate to the narration whatsoever, so I constantly would h', 'ᅠ', 'Overwhelmingly Positive', 95.87, 14.68, 5.97);
INSERT INTO reviews VALUES (31293, 910830, 640, 'This is my favorite Space Sim.  It''s built on nostalgia for Privateer, a game I used to play every few years.  Now, when I want something like Privateer, I load up Rebel Galaxy Outlaw.  If you want to hop in the cockpit of a space ship, transfer some goods between stations, dogfight some pirates, and in general have a good time, this is the game for you.  Whether you are a Space Trucker or a Dog Fighter this is a great game.  You will probably see some bad opinions about this game.  Sadly, the d', 'Awkward controls, boring dialogue, basically Elite Dangerous had a baby with Firefly and they both drank heavily throughout the pregnancy.', 'Mixed', 65.31, 63.47, 3.18);
INSERT INTO reviews VALUES (31296, 910880, 205, 'A simple little time waster that looks kind of pretty too. Reminds me of Sim tower from my younger days (yes I''m old)', 'Why does a developer go to such lengths to make a good game only to ignore the need for some kind of manual or effective tutorial to play the game.   Your given all kinds of stats and info with no instruction on how best to utilize the info.  This is just plain lazy in my opinion.  I would have given this game a big thumbs up if I wasn''t forced to guess as to what the info given to me meant.  Such a bummer.', 'Mostly Positive', 78.05, 24.25, 19.42);
INSERT INTO reviews VALUES (31309, 911220, 123, 'This is a fun short game. The characters are fun and the hub is well designed. While the game does leave a bit to be desired, I can see it has lots of untapped potential.', 'I failed to relate myself to Ximending nor its fantasized counterpart before completing the main story. I don''t need to interact with any landmarks at the map for 95+% of time in Ximending, and I''m not motivated to revisit any part of the virtual Ximending at all. You can''t fill in your city with just street food and monsters, it needs more stories.\n', 'Very Positive', 82.93, 11.12, 7.30);
INSERT INTO reviews VALUES (31319, 911400, 4203, 'I received this game as part of AC Odyssey Gold Edition. I can''t review the game as I haven''t played yet. This is just to let people know that the game runs without an activation code. I ran into the same issue as another reviewer, but after launching Odyssey first, you will then be able to launch AC III Remastered and Liberation successfully.', 'gave this 15 hours because nostalgia, liked it while ignoring all the bugs and glitches, thought the graphics had to be much better then the original. until today, when i downloaded the original again. i was denying the truth. the original runs so much better, way smoother, and isnt broken. many people need to be fired for releasing this. a single modder could do a better job then an entire ubisoft team. f ubisoft for being greedy. i say pirate these games if you really need to play them.', 'Mixed', 65.79, 0.18, 16.00);
INSERT INTO reviews VALUES (31321, 911430, 726, 'This game seems hard until you get to the point where you can have machines make your parts and you initially think "Oh it''s going to be so much easier now." NOPE! All that does is add another layer of complexity and logistics into the mix. It''s a lot of fun though.', 'Abandoned game with a ton of frustrating bugs. There is a reason most of the achievements are at .01. Avoid if you ever plan to 100% this game. Tedious and broken are a couple of words that come to mind to describe my experience.\n\nBug example, in rocket science challenge - zone buffs don''t work, workers gain skill points but can''t assign anything without success points; which are stated to be unlimited in this challenge. Without these buffs it is near impossible to generate enough science to win', 'Mostly Positive', 71.49, 75.27, 158.90);
INSERT INTO reviews VALUES (31327, 911550, 146, 'This game is awesome, with the amounts of mutations you can get almost feels like a rogue lite game. Its a pretty addictive action rpg with cool elements not seen on the standard ARPG games.', 'I''m honestly not sure about this game. Like a lot of Soldak''s games there''s a lot of really cool ideas marred by spotty execution, but this one in particular is plagued with technical issues that keep me from truely enjoying it. I hope that whenever they finally go back to make another top-down ARPG they start over with a more modern like Godot or something, because I really want to see some of these idea come to fruition.', 'Mostly Positive', 78.77, 561.43, 22.65);
INSERT INTO reviews VALUES (31361, 912570, 238, 'In this isometric adventure (which to me feels like a walking simulator) you''ll traverse post-apocalyptic Africa, encountering bizarre creatures, solving intricate puzzles, and making decisions that shape the fate of the world. It''s like a scenic hike with a side of existential crisis - perfect for those who prefer their exploration with a hefty dose of narrative depth. https://steamcommunity.com/sharedfiles/filedetails/?id=3286774544 https://steamcommunity.com/sharedfiles/filedetails/?id=328276', 'This game is beautiful to look at and the designs are incredibly creative, but the plot like something from Garage Bad Dream Adventure and not at all what I was expecting. I guess because it''s "the Future" nothing has to make sense. It''s like a pulp science fiction book you read where the plot is stupid and you know it''s stupid but you keep reading anyway because the writing is decent and there''s the occasional interesting idea.', 'Mostly Positive', 77.73, 77.95, 2.72);
INSERT INTO reviews VALUES (31381, 913060, 636, 'It is like an evolution to Luftrausers game, well made. The weapon customisation is good to keep things fresh and we can customise the gameplay according to our style. Missions are short and fun, we can keep playing in short sessions which is nice', 'Game was fun at the start, but it gets to a point where the screen flashes bright every few seconds with enemies dying and missiles exploding, and i can''t keep track of anything. Makes every mission really frustrating to me and just ruins my experience as a whole.\r\n\r\nGame really isn''t for me', 'Very Positive', 94.03, 13.25, 12.67);
INSERT INTO reviews VALUES (31414, 913740, 5818, 'Alright first steam review, you bastards forced my hand. Let me explain, this game was made by one person, whom shot themselves in the foot by over-promising much within a much too small of a time frame. This is another tragic early access mishap (early access is a garbage system). And I felt the need to do my part in skewing the reviews more towards positive.\n\nDid they take too long to make this game? Maybe. Did they screw up by giving the trailer these amazing black/white animations, making pe', 'Dev abandoned the game with zero communication. It''s not a bad game but is missing so much that it feels a hollow, imo. Dev not very professional, so buyer beware.', 'Very Positive', 93.38, 14.17, 18.73);
INSERT INTO reviews VALUES (31423, 914010, 867, 'I bought it for 3 euros with the DLC included. Didn''t expect to be such a great game. Similar to other games like this, but at the same time u feel like it''s something different', 'The gameplay is good, however the lack of a fov higher than 70 is motion sickness inducing for me.', 'Very Positive', 84.20, 26.13, 1.55);
INSERT INTO reviews VALUES (31424, 914020, 1004, 'Cathulhu.', 'As a veteran of point&click games i gotta give it a thumbs down. Although the artstyle is pretty and the characters are well animated the gameplay is just too plain. The puzzles are too easy and items are practically thrown at you to know which one to use where (it''s not Deponia, I tell you that). So it''s more like a story driven clicking with a bit of thinking.\r\nThe story starts strong but later it seems the potential of quirky characters wasn''t used much (possibilities of puzzle solving with k', 'Very Positive', 87.85, 6.43, 24.22);
INSERT INTO reviews VALUES (31431, 914170, 239, 'i swear i used to be like #1 on this game when i was like 8', 'If you are looking for a duck life game dont choose this one, its not much more and the online is dead, so its just a little more ducklife if you realllllly want that', 'Mostly Positive', 78.66, 5.08, 6.15);
INSERT INTO reviews VALUES (31437, 914260, 729, 'Great game, but my stinky winky friend returned it cause he loves men......smh', 'TL;DR Can be fun for a bit, but it''s repetitive and the challenge isn''t really an engaging challenge for me. Just running through trap rooms, gambling on RNG when you''re out of shoes to throw, and searching for an exit. Simple, enjoyable for a bit, but not deep. If you''re drunk gaming with friends maybe it''s a lot more entertaining.\n\nIt''s fun at first, but I wouldn''t really recommend the game. It gets repetitive quick, and its complexity comes down to whether you''re able to get through some insa', 'Very Positive', 83.68, 2.35, 2.93);
INSERT INTO reviews VALUES (31439, 914290, 142, 'A pretty good game with a lot of fun to be had, especially if playing with friends.\nThe main game loop is hunt down the prince, kill him, and temporarily remove taxes...\nit''s more fun than it sounds.\nIf that interests you definitely give this a shot.', 'No in-game saving facility so when you get killed,which is often,you have to restart back at the village and fight your way past all the drones/soldiers/prototypes etc again to get back to your last position.Frustrating and not enjoyable.', 'Very Positive', 80.28, 56.87, 2.00);
INSERT INTO reviews VALUES (31451, 914620, 6934, 'Just a small suggestion to the hard-working developer: why not open a modding support for the game?\n\nFrom what I gathered from all the reviews and discussions, this game has a huge fan-base including myself, who can''t wait for more and quicker updates, I''m sure there are quite a lot modders among us. If the developer open a modding support plenty of awaiting stuff can be modded into existing version, or at least some simple models so players can continue have more fun and the developer can have ', 'Been playing this since day one! has/has soooooo much potential but unfortunately the Dev seems to care more about the multiplayer aspect of the game rather than actually fixing anything in the game. truly wish he would''ve just stuck to the single player version and make this game actually playable first before introducing multiplayer. Dont waste your money', 'Mostly Positive', 76.69, 62.92, 224.27);
INSERT INTO reviews VALUES (31454, 914690, 270, 'gerçekten harika bir oyun. Bana atalarımı hatırlattı.', 'Going to tell my kids this was the original Doom', 'Mostly Positive', 77.41, 0.42, 3.63);
INSERT INTO reviews VALUES (31455, 914710, 1778, 'Just as with the original "Cat Quest", I''m definitely recommending "Cat Quest II".  If you played the 1st game (and you should), you pretty much know what to expect here.  So, I won''t rehash that.\n\nThere are a couple of changes to the game mechanics, though.  First, this game has a second character that either follows you and fights for you as a bot (in solo mode) or can be used by another player in co-op mode (local co-op in the game or via Steam''s Remote Play Together).  On one hand, that''s re', 'Just felt too repetitive and the combat is basic and boring. I read it''s the same throughout so can''t be bothered to carry on.\n\nLove the art style, love what the devs are trying to do but just not feeling the combat  and how repetitive things seem.', 'Overwhelmingly Positive', 95.11, 26.80, 1.08);
INSERT INTO reviews VALUES (31456, 914750, 296, 'укуси меня пчела', 'If you suffer from any type of motion sickness do NOT get this game. It is such a shame but the game is just not playable. Make me throw up after 5 minutes of flying around.', 'Mostly Positive', 77.03, 0.92, 0.22);
INSERT INTO reviews VALUES (31457, 914800, 4288, 'This game honestly brings it all together.\nRelaxing gameplay, good music, and a great story.\nIt helped me relax through some pretty rough patches of life.\nI''ll gladly recommend this game to anyone reading, one of the most memorable games I''ve played :)', 'Bland and pointless, also filled with therapy-talk which makes the writing borderline unbearable.', 'Very Positive', 94.75, 11.80, 1.47);
INSERT INTO reviews VALUES (31475, 915310, 3548, 'I don''t get the absurd amount of complaints this game gets.... Its cheap, has a simple mechanic (Snake with combat).\nGames are not forever, this game is complete and fun for the price point. Development has stopped and that is ok, devs are not beholden to eternal updates.\n\nGrab the game, have 5+ hours of fun gameplay, go eat something and that is it.', 'The game is cool, the units are diverse and synergies are interesting.\n\nThen you reach NG+ and realise none of that matters anymore. There''s a limited set of viable units and even then sometimes the elite will just run straight into you deleting half your units and your counterplay was to just play a different game. Beyond NG+2 you are paper and the enemy is fire, there is no playing around it unless you always build warriors which makes you wonder why the other synergies exist beyond the near m', 'Very Positive', 94.64, 5.23, 10.38);
INSERT INTO reviews VALUES (31483, 915460, 856, 'Best Game ever', 'Bought this YEARS ago as a joke for some friends and I. Recently have become a completionist and decided to re download it to get all achievements. I was immediately notified by windows defending that a trojan horse had been injected onto my computer but was successfully quarantined. The trojan horse was DEFINITELY from this download. WOULD NOT RECOMMEND', 'Very Positive', 93.11, 5.90, 8.43);
INSERT INTO reviews VALUES (31485, 915490, 102, 'it''s a fun game but there is a serious bug where I cannot switch weapons when using the mouse, despite using the correct button, can you please fix this bug developers?', 'Cant really recommend it', 'Mixed', 63.73, 1.50, 1.90);
INSERT INTO reviews VALUES (31489, 915600, 484, 'This game definitely understood the assignment. If you''re a survival horror fan you should definitely check it out. However, it IS an indie game, so it''s pretty rough around the edges and you''ll probably need to use a walkthrough to avoid walking in circles endlessly.\n\nThe level design in particular is more of a nuisance than anything else. I get what they were trying to do, but it just doesn''t work. In a survival horror or metroidvania style game the map feels rewarding and it makes sense. But ', 'In a game with so scarce saving opportunities, an unstable game that can crash at any time is the last thing you want. \nThis worst case scenario has happened to me enough times to leave it as is.\n\nWill come back to the game in a year or two.', 'Mostly Positive', 77.69, 11.67, 5.83);
INSERT INTO reviews VALUES (31492, 915670, 235, 'The negative outweighed the positive. \n\nBut If you have 1 dollar to spare and time to waste and enjoy playing as a mildly attractive protagonist with awkward movements animation then sure. Why not\n\nOnly thumbs this up because it''s a dollar on sale', 'Very clunky and rough around the edges action shooter.\nEasy on the eyes protagonist, low quality voice acting.\nVisually nothing great, poor animation, boring combat.\nBad vehicle controls, stupid AI, empty environments.', 'Mixed', 52.77, 0.80, 5.15);
INSERT INTO reviews VALUES (31498, 915810, 3237, 'It used to be one of my favorite games back in the day. It would be super fun, but it’s unenjoyable with just 10-20 peak players per day now. To the devs: Why don’t you make it free? This game has huge potential, but it’s completely DEAD. You’d probably make much more money from selling in-game cosmetics and weapon skins to tryhards and paste-eating idiots, as we see in the modern gaming industry.', 'incredible game but nobody really plays it, if it had a larger community or better AI it''d be a better experience but playing with the AI is TOO easy', 'Very Positive', 81.74, 98.12, 25.58);
INSERT INTO reviews VALUES (31527, 916440, 9434, 'the game itself is fun and i honestly like it a lot\nHOWEVER\nif it were published under any other publisher it would be 10000000000 times better\nevery single time i attempt to launch the game i have to spend so much time trying to troubleshoot the ubisoft connect launcher because it is complete and utter garbage\ni dont understand how they have managed to botch what used to be uplay even further but jesus christ just attempting to get into the game is genuinely the worst experiences i have ever ha', 'It takes longer to load ubisoft connect than to get to the main menu of the actual game that you purchased. Don''t get me wrong, I enjoyed the game (says it on my game time of review), but having to log in to another server just to play a game on steam is just silly.\n\nAlso, I mostly play single player, so if I ever travel and don''t have internet, I can''t even load the game.\n\nSo only get this if its in a heavy discount, don''t pay full price.', 'Mostly Positive', 78.80, 14.70, 92.68);
INSERT INTO reviews VALUES (31535, 916730, 1964, 'It''s kind of Metroid, kind of Blaster Master and kind of simple. It was never unfairly hard, or boringly easy and it was just about as long as it needed to be.', 'You can tell that the devs made it with love but I hate to say it is mediocre at best. Art is excellent, gameplay and exploration is decent and story is just poor. There are also some annoying things like weird controls and unskippable dialogues everytime you fight a boss and keep dying. Bosses were good but I don''t get the experience devs were trying to achieve. Some bosses exteremly easy and some extremely difficult (more than the final boss). Maybe more dev time and it would''ve been phenomena', 'Very Positive', 94.60, 6.17, 4.40);
INSERT INTO reviews VALUES (31538, 916840, 5528, 'good game, started out insulting walkers and then stabbing a old man in the head with a screwdriver and ended with me drowning a kid for supplies. 10/10 game would edge to walkers again.', 'game softs lock you as soon as you start or atleast in my experience with a quest 3 playing through steam link. asks me to reset the hmd with a button that isnt even on the quest. i tried to troubleshoot but then the game just randomly crashes on startup so i just gave up after like 4 tries', 'Very Positive', 87.84, 12.93, 0.08);
INSERT INTO reviews VALUES (31541, 916900, 122, 'Super chill point and click game with very lovely art style and music. Can be finished in 2 hours if you want all achievements. Story is about a lil wombat''s journey and you just can''t ignore the cuteness of it. <3 \n', 'Prrrbbbbt.... As succinctly as possible. I DO recommend this if you are a parent of a very young child AND you buy this on sale. Otherwise, give it a pass. \n\nPaperbark is an 18-30 minute playable storybook about a slow-moving wombat exploring the Australian bush. It''s unique as an interactive storybook, plus the animations and art style are incredibly charming... and that''s about all this has going for it. \n\nIn Paperbark, you click to explore a foggy landscape and slowly reveal terrain and anima', 'Very Positive', 87.70, 2.15, 0.50);
INSERT INTO reviews VALUES (31543, 916930, 177, 'I didnt want to believe but yes... This game is dead. I had to buy it just so i can recall some memories and because i had little hope that I''ll bump into some players there, but there is noone. If someone wants to play, contact me please, i would like to spend some time enjoing this without server kicking me out after 3 minutes xD', 'Red Crucible 2 was a better name\nShould be a free to play game again', 'Mixed', 46.89, 28.08, 0.17);
INSERT INTO reviews VALUES (31552, 917150, 702, 'This is a fun little sim game. You essentially just guide your people and develop your religon. You can boost certain attributes of your followers, however the actual fighting is up to them. The customization is good and the various types of religons you can choose open the game up to a varying amount of runs. I reccomend if you like sim games and autochess type combat.', 'I think this game is strategically designed to be interesting for exactly 2 hours', 'Mostly Positive', 73.36, 12.63, 2.88);
INSERT INTO reviews VALUES (31557, 917290, 175, 'Yes! A cute little Soulslike gem game!', 'Couldn''t shake the feeling that multiple sounds were overlapping each other and I might have left another program open. Turns out that''s how the game is.\n\nDuck Souls is very...okay. Not the first Pico-8 inspired platformer and sure won''t be the last.\nWasn''t fond of how your spawn point in each level was all over the place with nothing to draw attention to your character, in a game that encourages you to move immediately. \n\nTBH the game might have been better if it had the zoomed in camera from t', 'Overwhelmingly Positive', 97.14, 1.98, 0.82);
INSERT INTO reviews VALUES (31565, 917720, 390, 'Light recommend. It''s a really solid idea and the heavy Polish elements on slang is a nice touch but the story line is choppy. The ideas are good but the way they''re presented can sometimes be rough. For example when you arrive to a murder scene there is like one dialogue pop up "Oh, X has been murdered" and then you can just start talking to any rando about it before ever getting the full details by actually looking at the body/talking to cops on scene.\r\n\r\nThis creates a bumpy narrative I equat', 'I am left flabbergasted at how linear and shoehorned the storytelling is.\nYou can off three guys in once scene, and apparently it is fine, but when you are in a bar and a person is fumbling with a control device to kill all logged players you just stand there like a moron and let her kill them.', 'Mostly Positive', 74.10, 13.05, 6.72);
INSERT INTO reviews VALUES (31573, 917840, 341, 'Mass Hysteria causes an entire school to fight gladiator style to not be exterminated; the DND club somehow sweeps. 10/10.', 'Woke Tactics Club', 'Very Positive', 92.08, 15.65, 0.22);
INSERT INTO reviews VALUES (31581, 917950, 756, 'Thought there wasn''t a lot of depth at first, but as I unlocked more ink colours it became apparent there are a ton of potential builds and play styles. Each ink colour feels pretty unique, and even the ones I thought would be underwhelming ended up being fun in their own way. Great game, great mechanics. Has the potential to evolve in a top tier roguelike.', 'Can''t say I recommend this one.  One of the main methods the game uses to increase the difficulty is just to decrease the contrast you get on the screen, making it more difficult to identify hazards from other parts of the stages.  I don''t really like it when a game uses accessibility downgrades as a crutch to spike difficulty.', 'Very Positive', 90.74, 10.53, 3.18);
INSERT INTO reviews VALUES (31597, 918380, 137, 'This game is well written and so much fun. There are loads of choices that really seem to affect your story.', 'Something was missing from this one. Namely, there seemed to be too many dead ends and abrupt changes in direction. I found myself asking "Really?" several times when it seemed giant swings in the story happened instantly and without my ability to avert them in any reasonable way. You might think this isn''t a big deal, but when you''re hours into a story and a severe shift in the story occurs and ''ruins'' the direction it feels like you just wasted your time. Which is quite infuriating. \n\nMy story', 'Very Positive', 91.97, 28.98, 3.12);
INSERT INTO reviews VALUES (31604, 918530, 105, 'Excellent good fun and it’s always entertaining to get yelled at by budget Sephiroth \n\nAccidentally activated hard mode twice A+ will play again', 'DO NOT BUY - STUDIO IN CHARGE ABANDONED THE GAME!\nLEAVING CREATOR IN THE DUST', 'Very Positive', 90.48, 0.40, 3.02);
INSERT INTO reviews VALUES (31606, 918570, 748, 'the only thing i want out of this game is a open world with other players and ai stuff, just to vibe and cruise around, other than that i really enjoy this game.', '1.) was a fun game at launch after that it has went down the shitter\n2.) game for whales at this point\n3.) buying reviews\n4.) game is dead', 'Mostly Positive', 79.68, 14.35, 12.13);
INSERT INTO reviews VALUES (31617, 918820, 481, 'Used this in my Social Studies classes to examine concepts such as media bias and digital literacy.  Served as a great introduction to the importance of document analysis', 'Centrist crap', 'Very Positive', 91.48, 27.62, 4.17);
INSERT INTO reviews VALUES (31633, 919260, 272, 'I got about 5 hours in before I hit the factorio style infinite treadmill of upgrades and factory expansions. The game plays nicely and feels good to develop your own prototypes. Unfortunately I''m just not in the mood to scale infinitely right now, lmfao. From my experience playing it, I would judge the game to be worth 5$, 10$ if you''re into the factory and space colony genre.', 'Picture this: you’re handed a galaxy to conquer, a fleet to build, and endless possibilities. But then the controls step in and say, “Hold my beer.” Navigating this game feels less like building a space empire and more like assembling IKEA furniture—without the instructions, and with a missing Allen key.\n\nThe concept? Awesome. The execution? Well, let’s just say it’s a bit... quirky. Every menu feels like it’s daring you to figure it out, like an elaborate puzzle designed by space engineers who ', 'Mostly Positive', 77.21, 5.13, 6.63);
INSERT INTO reviews VALUES (31634, 919280, 385, 'I bought this on sale for a good price and I''ve been satisfied with it. It''s easy to use, good for begineers like me. I recommend it.', 'What a f*cking disaster.  The only reason I''ve used this app for so many hours is because how user unfriendly it is.\r\n\r\nThe tutorial is for macs and its not the same for PC, so its useless.  \r\n\r\nDon''t buy.', 'Mixed', 55.32, 2.47, 66.37);
INSERT INTO reviews VALUES (31638, 919370, 303, 'From the guys what saw Pokemon and Ark and made Palworld, comes the game they made when they saw Slay the Spire and Clash Royale.', 'feels really soulless', 'Mostly Positive', 78.88, 119.68, 0.55);
INSERT INTO reviews VALUES (31643, 919640, 4133, 'First of all, I want to say how absolutely blown away I am by this game. This is the best tactical ww2 rts on the market. Call to arms, company of heros, man of war, all of them need to make way for this masterpiece. For starters, the scale is on a much bigger level. In other games similar to this, it is comparable I''d say to managing a company of men, however, in the skirmish game mode, you are basically commanding at the regimental level, which is commanding a couple of thousand men. (Typicall', 'Greedy, greedy, greedy devs that seem to only grow more and more money hungry the longer the game is out.  Bought the so called ''ultimate edition'' on sale for 24 AUD and it didn''t even include all the DLC (which mind you, all the DLC will cost over 100+ AUD ON SALE for a game that was released in 2018!!).  Most of these DLC''s only include 2 division for a price of anywhere between 7-12 AUD on SALE.  Without the DLC it feels like you''re missing 90% of the game.  Not at all worth your money or tim', 'Mostly Positive', 79.63, 116.67, 0.55);
INSERT INTO reviews VALUES (31649, 920210, 25249, 'fun game, my only anoyance with it is that every time the game starts up rey asks where her place is in all this when it is blindingly clear she belongs in the trash', 'The game offers an almost overwhelming variety of skins, planets, vehicles, and mini-challenges. While this is impressive at first glance, it ultimately feels somewhat shallow. The gameplay becomes repetitive quickly, making it seem like you''re just swapping textures rather than discovering anything truly new. The story and cutscenes are, as always, excellent, but feel far too short and rushed. In the end, it feels like the game tries to do everything but doesn’t really excel at anything.', 'Very Positive', 90.20, 12.85, 9.63);
INSERT INTO reviews VALUES (31651, 920320, 401, 'Purge the heretics', 'This looked like something I''d love (I love RPGs and I love sci-fantasy! And it used to come bundled with OneShot, and OneShot is absolutely delightful!), but it''s... disappointing. Less than the sum of its parts for sure.\nI completed the Cardinal+Starcrossed route a few years back, but didn''t like it. Recently, I came back after the recent update to see if anything''s changed, or maybe if I was just too jaded to see the magic back then. I completed the Capricorn and Taurus chapters, and... yeah,', 'Very Positive', 93.77, 0.35, 22.98);
INSERT INTO reviews VALUES (31654, 920490, 133, 'Good for driver updates, but got to watch for driver versions, from time to time it wants to install wrong drivers', 'the news update just make this program unusable always fail updating the driver because just stuck in 1% thank you regret getting pro. if im wrong comment here pls so i can resolve the issue', 'Very Positive', 87.97, 16.35, 575.33);
INSERT INTO reviews VALUES (31661, 920680, 394, 'Fate Hunters is probably one of the lightest Roguelikes I have ever played. You can spend days on it to unlock everything, or you can play two runs in about two hours and defeat the Tower''s Master. The difficulty doesn''t spike very high. If you optimize, you can go into this game blind and win. The push-your-luck decision to tie class/item card purchases to escaping with gold bothered me for about the first three hours I played, but I ended up happy with the execution. The art style is grim-dark', 'Shallow.', 'Mostly Positive', 78.93, 41.77, 65.35);
INSERT INTO reviews VALUES (31678, 921570, 4438, 'Pro:\r\nGreat looking gaming.\r\nVery nice, fun take on turn based combat.\r\n\r\nCon:\r\nThe 8 stories are completly seperate and not very deep/interesting.', 'My cons from the completionist''s perspective:\n\n- Galdera''s boss fight is very hard and for some reason there is no save station in the last dungeon. So in order to retry him, you have to beat another 8 hard bosses first to open the passage. Very time consuming and very disappointing when you fail on the last boss (each try takes ~2 hours). In addition to this, you have to use all 8 characters in that fight, so you have to go and grind AGAIN to make them all somewhat ready. Grind is not fun.\n\n- S', 'Very Positive', 86.68, 88.18, 135.48);
INSERT INTO reviews VALUES (31679, 921590, 447, 'Lmao, at the time of me writing this review this game has Final Fantasy 11 players in the game. Even still, I play this game as much as I can because I really like it.\r\n\r\nIf you wanna get in on the niche game that is Dissidia NT, check the community tab for the Discords so you can actually find people that play the game. You can even get the DLCs for free. Don''t feel bad about getting them, I blame SE/Koei Tecmo for abaddoning the game. You hear that you bitches?! You screwed Squall with his rew', 'Square Enix, please do dissidia 012 HD remaster!', 'Mixed', 57.05, 243.68, 27.55);
INSERT INTO reviews VALUES (31684, 921710, 241, 'This game is a bit rough around the edges but the galaxy conquest mode it has is worth checking out.  XCOM-like gameplay but with a ship to manage instead of a base (and less complicated), but in the galaxy conquest mode you are redirecting fleets around the map in a 4x-lite strategy layer on a randomly generated map.  I wish more games would do this!', 'Exit EA before the game is complete and abandoned. Disappointed.', 'Mostly Positive', 75.10, 11.58, 1.15);
INSERT INTO reviews VALUES (31690, 921780, 324, 'After they fixed the bugs this game by far is one of my top horror games now 9.5 /10', 'afther last update game crash all the time', 'Mixed', 66.05, 27.12, 4.78);
INSERT INTO reviews VALUES (31692, 921800, 1938, 'Encased is a brilliant isometric game that didn''t get enough love when it landed on STEAM.  I played over 100 hours on my first play-through as a mentally challenged Silver (the elite, administrator class).\n\nIf you want a unique roleplaying experience, on your FIRST play-through be sure to run an intellectually challenged Silver and enjoy the ensuing hijinks. The dialogue with the NPCs is GENIUS as confused questgivers try to figure out how to explain complex situations to your mentally limited ', 'I like a lot of things about this game, but the simple truth is it''s not really a finished game. The first half feels complete, the second half is just entirely cobbled together in a rush. They clearly don''t intend to correct that. There are also some very real problems with certain aspects of the game, particularly in the second half that make it clear they didn''t spend enough time play testing it. There are even typos in the final lines of dialogue, the VERY limited final lines, come on man. \n', 'Mostly Positive', 74.46, 126.35, 28.02);
INSERT INTO reviews VALUES (31702, 922050, 143, 'It was fun enough.  Would HIGHLY recommend playing with a mouse and keyboard.  Had fun for ten hours then before going to the final boss there was a macguffin fetch quest for six things.  This combined with the limited fast travel system killed my desire to finish the game but it was fun while it lasted.  Also each boss was very uniquely designed and interesting to fight but most of them had a mechanic that was...annoying for lack of a better word.  It took a little away from the experience.  An', 'This game starts strong, but is just rough around the edges in a lot of different aspects.\r\n\r\nThe twin stick shooter style of movement is interesting and starts quite fun, but especially the last 50% of the enemies are just kamakaze enemies, which are quite boring.  Just general movement is -extremely- floaty and slow, leading to lots of tedium and frustration when navigating the map and going to previous areas.\r\n\r\nExploration is quite tedious, as you tend to get small amounts of progression in ', 'Very Positive', 82.52, 10.60, 14.55);
INSERT INTO reviews VALUES (31705, 922100, 236, 'This game went beyond my expectations! \n\nI failed plenty of times, but when I understood how to navigate the nauticrawler. I thought that was the game, navigate through the radar, avoid being blasted to bits and manage fuel consumption. But then the moment came...I realized I just finished the tutorial. Cinema! \n\nThis game is part escape room, and part exploration. Can definitely recommend and hope more people play it.', 'Cool idea, but after having to compare a guide to simply start up the engine after it wouldn''t start up again on repeat playthroughs after death (activating other switches than the mainframe one before startup seemed to be the issue along with other problems), I''ve come to the conclusion that the game is bugged, and just can''t be sure that if I get stuck later on in the game that I just can''t figure out a solution due to me being stupid, or if some glitch is making progress impossible.', 'Very Positive', 93.22, 6.32, 0.67);
INSERT INTO reviews VALUES (31713, 922400, 267, 'I missed DX Ball. Then I wondered if it was on Steam. It was. Huzzah.', 'Stutters & mini-lags from time to time make this hardly playable. Good game otherwise, used to play it around 2005 (worked alright) -nice comprehensive physics & bonuses..', 'Overwhelmingly Positive', 95.88, 10.03, 2.25);
INSERT INTO reviews VALUES (31732, 922710, 115, ' Coupon Game \n\nThis is honestly such a good hidden indie gem I didnt think much of it when I got the coupon for this game but after watching the trailer I figured i spend like the $2 on it and I would have the $6 for it because even though theres only 4 dungeons each dungeon is completely unique with different enemies, mechanics, puzzles, and End dungeon bosses.  I absolutely love the pixel art and that retro style soundtrack definitely worth it!\n\n Big Mac Price Certified! ', 'one of the worst games ive ever played\n', 'Very Positive', 86.09, 1.83, 3.87);
INSERT INTO reviews VALUES (31751, 923260, 408, 'There are a list of qualities that make a good puzzle game but simply put what you are looking for is a simple concept that gradually adds complexity at a pace that is understandable and enjoyable. Golf Peaks does a perfect job of doing this.', 'Golf Peaks is a game where you solve minigolf courses using a preset hand of movement cards. Each card has a "hop" component (which allows it to go over ledges and avoid environmental effects) and a "roll" component (which bounces off of ledgers and does not avoid environmental effects), or a combination of both (with the hop always coming first). At the beginning of the game there are only grass titles, eventually adding sloped tiles, ice tiles (which cause the golf ball to slide until collidin', 'Overwhelmingly Positive', 96.08, 7.20, 3.40);
INSERT INTO reviews VALUES (31761, 923470, 196, 'My little brother killed himself because of Momo, this game really brought back those positive memories. Recommend.', 'Better stay away from this one.', 'Very Positive', 82.65, 0.28, 0.80);
INSERT INTO reviews VALUES (31768, 923570, 154, 'A wonderful game, part action RPG, part visual novel, that was almost ruined by one of the worst final boss fights I''ve ever had the misfortune to experience. Almost, but not quite.\r\n\r\nEternal Radiance is the story of Celeste, squire of The Ashen Order, and her companions Ruby the mage and Valana the mercenary archer. The story is told in visual novel style sequences, and the actual gameplay consists of action combat sequences in large open ''dungeons''.\r\n\r\nThe artwork is mostly very nice (some of', 'The game becomes unbearably hard and unfair not because the bosses have difficult paterns, but because:\n1. Your AI partners are very stupid. They can''t dodge or deal damage as fast as you can. They have no positioning at all.\n2. You take damage even if you are stunned. And yes, you can''t roll to the other side to dodge a projectile - you''ll get it, don''t worry about it\n3. Bosses in chapters 4-6 have the wildest amount of XP compared to the first three chapters\n\nI''ve completed the game, but it''s ', 'Very Positive', 89.61, 34.05, 5.22);
INSERT INTO reviews VALUES (31781, 923810, 143, 'fuckkkk the censorshipssssssss', 'Once again Moenovel has butchered the routes beyond belief, not that I expected much of 4kids 2.0 anyway.  Hopefully a fan re-translation will come along and fix it.', 'Very Positive', 93.71, 43.95, 4.98);
INSERT INTO reviews VALUES (31790, 924070, 414, 'I love this game. If you don''t have a gremlin riding your neurological pathways this should be a tasty treat.\n\nThe content generation is wondrously intermixed and you always find mods to augment yourself, I say this having already played for 83 hours. I''m still unlocking new mods to progress further and the ability to create your own archetype is currently standing on its own.\n\nAnother good point is the hidden lore in the game aided by the upfront lore.\n\nEasy purchase for the price and even easi', 'The core of this game is a pretty solid soulslike with a neat aesthetic.\r\nEverything else about the game ruins that.\r\n\r\nThe writing is atrocious, you get to listen to bad jamaican accents doing a bad reimagining of norse mythology.\r\nThe art is ugly as hell- the aesthetic is cool but its bargain bin PS2 game graphics ruin that. \r\nThe gameplay is ruined by the metaprogression heavy roguelite structure. The enemies are not exciting enough to be interesting to fight in a second run, and it drags bad', 'Mostly Positive', 78.74, 118.65, 12.78);
INSERT INTO reviews VALUES (31795, 924140, 2854, 'Game allowed me to touch myself inappropriately and eat mushrooms, would recommend.', 'weird ass controls too difficult and boring asf this just ain''t for me', 'Very Positive', 86.86, 2.52, 0.22);
INSERT INTO reviews VALUES (31812, 924750, 513, 'Loved, loved, loved this game.  One autosave that saves frequently.  Minimal puzzles and lots of dialogue, cut scenes, and exploration.\n\nThis game is a beautiful piece of art, with beautiful music and voice acting and storytelling. The story made me laugh at times and a bit weepy at times.  I was completely invested and enjoyed it immensely.  What I got from my 15 hours of play time trying to speak to everyone and explore everything in each act was well worth the price of admission into this won', 'Don''t be fooled. This is NOT a videogame. There are no choices to be made, there is no gameplay besides walking left and right. Everything is pre-determined and you are basically train on a track who cannot do anything else than "go to the next station". \n\nBut the story is beautiful. \n\nGet this on a sale.', 'Very Positive', 82.85, 15.37, 15.88);
INSERT INTO reviews VALUES (31821, 924970, 24103, 'I won''t compare this to left 4 dead, if I did It would sound worse than it actually is just due to how good Left 4 Dead was.\n\nBack 4 Blood had a (right deserved) rough start, the game launched in an abysmal state. Glitches and bugs that ended your run, AI that was atrocious and got you killed repeatedly, insane difficulty spikes that made the game go from too easy to impossible in a snap, god awful progression/card systems that stalled gameplay, and more.\n\nAlmost every one of these issues has be', 'They made the game''s name a direct reference to Left 4 Dead... yet they left out all the fun of Left 4 Dead, condemned modding the game, and abandoned the game. \n\nMaybe 90% off is an okay price, but I got it for full price and it was a complete ripoff. This game sucks.', 'Mostly Positive', 71.77, 16.27, 45.73);
INSERT INTO reviews VALUES (31822, 924980, 2117, 'I have adhd and I lose interest super quickly. Played this 30 h so far, and still going. So yeah, it''s pretty fun :D', 'I never played the original so no rose-colored glasses here. I didn''t hate it, but it''s pretty MEH.  I could see how back in the SNES era it may have been more impressive. The combat is the best part even though it''s nothing special. \n\nOn normal difficulty it''s stupid easy and there''s at least one or two NPCs whose voices make my ears bleed.  The story was whatever-who-cares and I didn''t really like any of the characters.  It''s certainly not a bad game and it does have some redeeming qualities b', 'Very Positive', 92.16, 30.40, 9.57);
INSERT INTO reviews VALUES (31829, 925100, 234, 'Good game keeps up to lore but doesn''t have support on the rog ally because it''s missing the middle button even tho it has buttons on the back.', 'Good review is blocked in your region.', 'Mostly Positive', 79.49, 0.00, 0.00);
INSERT INTO reviews VALUES (31840, 925440, 136, 'A poorly translated doomed yuri Reimari RPG Maker game this game was specifically designed for me. I was crying the whole time.', 'This game features a saddening tale about Reimu and Marisa, while I did like it, I can''t fully recommend it due to its shortcomings.\n\nThe tone the game takes is confusing, the fanservice does not mesh well with the more emotional moments the game has, I managed to get a couple of tears in my eyes at these emotional moments but they didn''t hit as hard as they probably intended to due to these tonal shifts.\n\nThe choice of game engine and its limitations make the game feel a bit wonky and a bit ann', 'Very Positive', 92.65, 1.65, 1.47);
INSERT INTO reviews VALUES (31841, 925460, 153, 'Yes.', 'Pretty slow and repetitive for a single player game. If you are looking for groovy graphics and relaxing gameplay then this is probably the game for you.  \n\nI bet it would be a lot of fun with friends, but there isn''t enough game here for me.', 'Overwhelmingly Positive', 96.73, 2.02, 0.62);
INSERT INTO reviews VALUES (31849, 925570, 287, 'https://steamcommunity.com/sharedfiles/filedetails/?id=3008619556\nhttps://steamcommunity.com/sharedfiles/filedetails/?id=3007157867\nhttps://steamcommunity.com/sharedfiles/filedetails/?id=3008619524', 'The game is ok if you don''t mind playing a broken game with more bugs than a rain forest.  If you don''t like playing broken games, I''d say stay away (even at the $1 price I paid on sale). It is playable and the story is decent, but it was a headache to complete. The only reason I put up with it was because the first game was better and had an interesting concept that I wanted to see play out. Unfortunately, it ended with another cliffhanger and the Devs will not be making the 3rd game because th', 'Mixed', 60.28, 7.18, 15.67);
INSERT INTO reviews VALUES (31859, 925930, 302, 'I can has VR-compatible remake of this one, too? 👉👈🥺', 'The original MYST was ground-breaking for its time, and Riven was great; everything else from Cyan since that time has been either meh or terrible, with timed events and/or events requiring timed mouse precision.\n\nNope.', 'Very Positive', 93.71, 4.27, 13.75);
INSERT INTO reviews VALUES (31860, 925940, 168, 'This is a great game even if some of the puzzles were really a bit unfair and weird. \n\nTo me, Myst 1-4 will always be the one epic canon to the series and part 4 is the final chapter for me. Myst 5 and URU never really appealed to me and you must be a diehard fan to enjoy these ''spinoffs''. I truly loved Revelation, especially because of the actors. The story was amazing and I hope that eventually there will be a remaster of Exile and Revelation. The outdated graphics would look so stunning if th', 'Most puzzles are nonsensical with inadequate clues to resolve without resorting to walk-through cheats; too many obscure riddles that are simply frustrating and tedious make the game boring.\r\nLots of unnecessary trial and error challenges with excessive backtracking required in order to make progress.\r\nBut the Myst worlds are intriguing to explore, always providing an immersive and entertaining experience.', 'Mixed', 68.45, 9.00, 54.38);
INSERT INTO reviews VALUES (31861, 925950, 823, 'I love being nonbinary :D', 'I suppose a cute and cozy indie platformer nowadays just can''t go without some woke deep dark  fantasies  backstory. The developers don''t seem to hide the nature of the game much, but it''s still not entirely obvious at first glance. Wanted a cute and simple Paper Mario-like platformer, recieved a furry boy-kisser runaway "tragedy" in a form of one. Definitely not what i was looking for. Technically it''s okay, i guess.', 'Very Positive', 92.95, 18.15, 1.00);
INSERT INTO reviews VALUES (31869, 926140, 1343, 'Making this review because (ironically) the developers have fallen on hard times and may not be able to continue development after possibly closing their doors in the near future. Please give this game a shot, it''s well worth the price and deserves more attention!', 'How was this game ever nominated for an award and why does it have such good reviews?  Do people just feel bad giving a game about homeless people a bad review?  Half of the perks dont actually work or do what they say, the game is very redundant containing no fun at all.  Also how does studying at the library decrease your hygiene more than digging through trash cans? The logic in this game makes no sense and I dont understand why people like this low quality game.', 'Very Positive', 92.93, 31.92, 2.25);
INSERT INTO reviews VALUES (31889, 926520, 117, 'I won''t lie, I first discovered this game back when I was like, 10, on Roblox, when someone recreated the game there. I didn''t know it was an actual game until I saw the box for it at mt local B&N. It then became one of my absolute favorite games, and THEN (maybe a year or two ago) I learned that it was on Steam??? I was so excited I think I bought it same day.\n\nUnrelated, my friends and I have created nicknames for the cards, as well as our own personal feelings for them as well. We all hate th', 'PUT IT BACK ON BOARD GAME ARENA\nthe web version was 1000x better', 'Very Positive', 93.16, 18.63, 0.53);
INSERT INTO reviews VALUES (31890, 926540, 226, 'game is dead but i hope more people play its a very fun and not so serious game but im sure with ppl act playing it could be serious if u got the right guys all around a fun game more people need to get it', 'Tbh, only purchased it ''cus a YouTuber purchased it, played it for 6 hours, haven''t played it since. It appears most of this game''s community got it for the same reason, as it''s multiplayer is dead. Don''t get this game as the last update/piece of news was two years ago.', 'Mostly Positive', 72.12, 3.12, 6.22);
INSERT INTO reviews VALUES (31891, 926580, 339, 'Love XCOM and was looking for a similar game. Hasn''t quite got the polish of XCOM, and is a little less tactical, but really enjoyed the game and the story. Overall very fun, just lacked a little depth to the combat. 8/10', 'Not worth $24.99.\n\nI got it on sale, and for the price, it could have been okay. Until the next to last chapter where I find that the story flags you as having done things you hadn''t. The story and choices were part of the appeal, but if the game doesn''t even track them properly?\n\nPass or wait for a sale and be prepared for incongruity in the narrative in some instances.', 'Mostly Positive', 76.40, 8.10, 7.30);
INSERT INTO reviews VALUES (31897, 926860, 196, 'It''s pretty mid. It''s fun in a way that only top-down rally games could be, but I''m not a huge fan of the Running Man schtick. If it was just a pure rally sim I''d probably play it more.', 'Was primed to write a positive review because the game is great, it really is. I have been having a great time with it. But then randomly far into my hardcore campaign there was some kind of save file corruption that entirely eliminated my playthrough. I don''t know the cause. Maybe it was my computer but I highly doubt that. It just seems a game as simple as this shouldn''t have any issues with something as menial as save files. And I couldn''t find any way to retrieve or save the prior file. It w', 'Very Positive', 91.33, 0.60, 29.17);
INSERT INTO reviews VALUES (31899, 926990, 7908, 'I''m Autistic and my special interest is wolves. I''ve played this game for 4 hours, my first litter of pups were born, and they were so cute that I literally cried in real life, then shut the game off and didn''t play it for months because I was worried something bad would happen to my pups.\r\n\r\n11/10', 'Claiming territory is redundant, repetitive and not fun. Then you have to keep redoing it because it fades constantly. You have to stand there and pee twice and then howl like 5x in a row for each hexagon. You need 15 hexagons of territory to get started, and other wolf packs are trying to fight you for the same territory. Then, when you finally have pups, they will get killed constantly in ridiculous ways even on easy.\n\nFor example, my pup got killed by an invading wolf pack despite me having d', 'Overwhelmingly Positive', 98.07, 4.85, 9.25);
INSERT INTO reviews VALUES (31905, 927250, 491, 'Really enjoying it, good fun!', 'Bladed Fury made me feel the "fury" part when playing, as the controls for the game are so clunky that if you were to make a Digimon out of the game, it’d be called Clunkmon. The only saving grace for this game is that it’s short, but even then, I’d not recommend wasting any expense on it and instead moving to something more worthwhile.', 'Very Positive', 88.39, 5.12, 3.53);
INSERT INTO reviews VALUES (31906, 927270, 799, 'aconuing puls\r\n', 'Excellent game when it came out, but support afterwards is a joke, people all over the world can''t get past the first part of the game bootup choosing the stance, developers are not reacting and not fixing this, it''s been 4 years.', 'Mostly Positive', 73.34, 3.37, 2.38);
INSERT INTO reviews VALUES (31909, 927380, 7737, 'guys you do not have to spend 12 hours playing mahjong for that 1 side quest you can find a peerless tile from komeki do not spend 12 hours playing mahjong its pretty much impossible without the tile. You will thank me later', 'Boring af, also anti-aliasing sucks big booboo', 'Overwhelmingly Positive', 96.42, 48.77, 8.70);
INSERT INTO reviews VALUES (31918, 927890, 853, 'Hentai Girl Linda is a good puzzle game with many levels kinda easy. With his low price, it worth it. I recommend it! 💗', 'Bought the game for a profile background, and got my asexual ass traumatized for being curious and bored.', 'Very Positive', 92.15, 8.50, 2.08);
INSERT INTO reviews VALUES (31933, 928390, 134, 'buy when its cheap. it has r-type inluding r-type 2 which i wasnt expecting. 2 games for one price.', 'Sad to say its a -negative for me, Super Nintendo Super R-Type remains supreme for me So sad steam does not offer that version the progression build is perfect. These R-Type I & II are coin base and it shows. The levels are short, shallow and difficulty based on how many coins you put in the machine = Cheap death and not skill based.', 'Very Positive', 86.57, 0.08, 2.92);
INSERT INTO reviews VALUES (31938, 928520, 151, 'Great art and outfits and sexy scenes with sounds and the they got a second one now too I plan on getting that one also so yes I recommend well worth the price.', 'They put one CG behind an easy af boss. The thing is, you have to be defeated by this boss to get the CG. The dev themselves probably never played their own game.', 'Mostly Positive', 75.50, 1.62, 1.47);
INSERT INTO reviews VALUES (31950, 928960, 652, 'Honest review, Game is fantastic, cinematic are great, story line is there, that being said i didn''t get this game for the story, combat is amazing! take-downs feel smooth, weapons feel powerful, high skill level required, there are still some bugs, especially playing with multiplayer during tower mainly, most of the game really happens in the endgame content so best not to listen to any player review under 20 hours of game time because they don''t know what their talking about, the game in my op', 'First off, my hours are low as this is not the account I put hundreds of hours in on. I played this for a long time with my friends on PS5 and we loved the grind. The mechanics in the game feel seamless, the weapons "felt" powerful, and the game-play loop as a whole wasn''t too bad. However, what killed the game for me was when they introduced the "revamped" ailment system that changed the entire landscape of the game. Put simply, there were cool builds and synergies that the old ailment system h', 'Mixed', 69.02, 97.03, 2.60);
INSERT INTO reviews VALUES (31952, 928990, 135, 'I was initially concerned about this game because of the RPS review suggesting it was awkward to control. I have not had this experience at all; I found the game''s controls to be intuitive and well-designed. The environments are beautiful, the combat is great fun, and the story only seems to increase in intrigue as the game progresses.', 'The game has many mechanics and systems that seem like they would be fun to explore, but instead the game beats you senseless with them. The biggest frustration with the game is the combat. Enemies are constantly throwing range attacks at you, AND they never stop running away from you, AND they also have huge health bars, AND they can heal themselves, AND they take very little damage, AND enemies deal increased damage, AND your items can break, AND your heals can get stolen, AND you have stamina', 'Mixed', 67.41, 1.18, 2.75);
INSERT INTO reviews VALUES (31953, 929010, 955, 'Can go from upgrading your town to slaying monsters to participating in fashion shows.\n\nCan''t say I''ve ever played a game that let you do that before.\n\nThen again, before Graveyard Keeper I had never played a game that let you manage and run a cemetery.  These developers sure know how to inject uniqueness into their games.\n\nTo be fair, the gameplay loop can get a little repetitive and at times feel too "slow" from a progression standpoint.  But since I''m such a loot goblin that part didn''t reall', 'after playing 14 hours of this game I can say this. I HATE THIS GAME! I felt the urge to punch something everytime i played it. But I had to finish the story because I made a deal to myself that I would finish games I bought. So GOODBYE SWAG & SORCERY stay in my library and never be touched again!', 'Mixed', 47.02, 33.48, 14.40);
INSERT INTO reviews VALUES (31956, 929060, 204, 'How can i start this review .... i own most survival/crafting games and ive left them for one reason or another .... either they were not very good or there were cheaters who spoiled the games and the devs do nothing about it.this game is different i have 311 hours logged as i write this review although it is single or multiplayer i have only tried single and it ticks all my boxes .... the crafting and base-building is very good and the enemies are great.ok it is early access but the Devs are ve', 'Developer moved on to a new game , no updates in 2 years (march 2022 shows).  Don;t buy this or their other games', 'Mixed', 63.73, 1508.73, 21.75);
INSERT INTO reviews VALUES (31965, 929270, 123, 'Solid tracking solution for sims, once you''re used to it its second nature.', 'SCAM DO NOT BUY. Stops working shortly after paying and "runs on background" accruing fake playing hours.', 'Mostly Positive', 73.98, 362.30, 13.73);
INSERT INTO reviews VALUES (32012, 930620, 148, 'Nice', 'You can''t honestly expect me to build a combo by pressing the fire button in a specific rhythm while bombarding me with enemies left and right in a tiny warzone of an arena.\r\n\r\nThese things don''t mix!', 'Mixed', 59.46, 13.40, 2.02);
INSERT INTO reviews VALUES (32019, 930780, 250, 'I like it so much. For anyone who like Slay the Spire, I think this game has a very high potential to be on the same level. \r\n\r\nThey have a unique feature and play style, some combos are very broken tho. I enjoy it :))', 'too easy to break: you just need a few cards to make an OTK combo on turn 1, sorry if i forgot their names, and use it in this order:\r\n1: +1 mana\r\n2: the innate card (that always starts in your hand) that you grab any card from your deck for 1 mana\r\n3: the "duplicate all cards" that cost 2 mana\r\n4: that normal card that costs 1 mana and duplicates a card from deck\r\n5: the normal card that gives 2 mana\r\nrinse and repeat steps 4 and 5 of this combo for infinite cards + mana', 'Very Positive', 81.20, 69.62, 3.90);
INSERT INTO reviews VALUES (32024, 930910, 266, 'Man becomes a furry and develops schizophrenia. 10/10', 'Linear Bounded Phenogram is a waste of a cool idea. The game consists of a couple of short stories, narrated by different characters from the main cast and all take place in different worldlines. You can split these routes into two general categories. The first one includes serious stories that are related to the events in the original Steins;Gate and try to give some additional insight into the characters. The second group is where the wacky, bizarre and silly routes go.\r\n\r\nThe serious stories ', 'Overwhelmingly Positive', 97.74, 24.77, 16.68);
INSERT INTO reviews VALUES (32038, 931270, 315, 'Still in EA and seems not abandoned. In depth supply chain, hexagon, pixel art. It is so good that I actually think the retail price is too cheap, while I just bought it from summer sale.\n\nEdit: 2024-07-23\nGame become slower when reaches 2K pop, while it does not fully utilize the CPU (3900X), GPU (3060 Ti) and RAM(64GB). Disabled weather effect do improved 25% FPS (20 -> 25, though).', 'the game is still in EA but we haven''t seen an update since almost a year\ntake this for what you will', 'Very Positive', 93.97, 50.00, 0.82);
INSERT INTO reviews VALUES (32039, 931280, 478, 'Good. Fun. Fine. Chill. Relax.', 'Boring and buggy game. Constantly spending 15 minutes on a level and then losing because the game doesn''t scroll to another part of the map. What a waste of money', 'Mostly Positive', 77.62, 6.38, 2.65);
INSERT INTO reviews VALUES (32040, 931310, 188, 'Someone please tell me what 26 Down is in the crossword', 'so bad\r\n', 'Mixed', 69.68, 3.82, 5.67);
INSERT INTO reviews VALUES (32046, 931500, 201, 'I have never been so happy to complete a tutorial before.', 'Genuinely the most boring ass shit I''ve ever played. How is it even possible to make a game with 2hu girls boring?\n\nThe only emotion I get out of this game is the earth-rending annoyance that consumes my entire being every time Futo opens her whore mouth to make the already way too long dialogue sections 3x longer for literally no reason. Nothing else about the entire game is noteworthy. Gameplay is there, and boring. The story exists, and is boring. Characters are there, and never shut the fuck', 'Very Positive', 93.53, 7.32, 8.30);
INSERT INTO reviews VALUES (32068, 931950, 111, 'The game is highly strategic and brilliant; a masterpiece like Twilight Struggle.\n... but as an European I''m already sick and tired up the ass from hearing or seeing pictures or messages of islamistic extremism e.g. in the ambience background sound clips or on the cards... If I have to see one more Schleiatauntn or Binibort or Muuslfreysn, and the only governmental acts that are done about them are fictional ones in a game, I''ll become blind from rolling my eyes too hard.\n\nSorry, it''s a good gam', 'Look, i like online boardgames, but could you just put in at least some kind of tutorial so i know what the bleep i should be doing?', 'Mostly Positive', 75.68, 1.75, 0.18);
INSERT INTO reviews VALUES (32100, 932850, 801, 'good but confusing game\r\nthe discord was no help with getting certain things to work, but hey this game is pretty dead anyways so what can you really do, still was able to get by though', 'not respecting God\n there is shouldn''t be any game represting the player as god \nI bought the game and I didn''t think it had this thing . sorry but I do not allow disrespect to the Lord.', 'Very Positive', 83.77, 33.95, 0.12);
INSERT INTO reviews VALUES (32107, 932980, 126, 'it''s an okay game x3', 'This game has many problems and many good things the gameplay is decent the team editor is great same with franchise mode but the passing is horrible it''s almost impossible to complete a single pass decent game just not for me', 'Mixed', 62.70, 4.98, 0.12);
INSERT INTO reviews VALUES (32112, 933110, 12780, 'Age of Empires III in my heart forever <3 My dad showed me this game years and years ago, and it was still open on his laptop when he passed away. He never stopped playing. I''ve loved every version of AOE III.', 'Developers have abandoned it, and betrayed the player base. The DLC that was just cancelled is simply the latest in a long list of ways this title has been left to rot. I may change my review to the positive that this game deserves at some point in the future if it''s ever handed over to someone who will actually give it the attention it deserves, but I doubt that will ever happen.', 'Very Positive', 83.65, 77.83, 198.92);
INSERT INTO reviews VALUES (32132, 933820, 3209, 'I love this game! It''s one of the more unique builder games I''ve played, and what I love most about it is that it pushed me to learn a different approach. Where many builders reward (or at least don''t punish) early rapid expansion and over-production, Endzone demands a careful awareness of balancing what you have against what you absolutely need. If you over extend right out of the gate, you will rapidly find yourself unable to support even the most basic needs of your colony, and the dreaded de', 'Only writing a review because of the sequel, because this game never felt finished and I wanted to give the studio a chance to finish their product before bashing it.\n\nIt''s bland. There are plenty of equal/better city builders. I got bored quickly.', 'Mostly Positive', 76.29, 254.13, 6.45);
INSERT INTO reviews VALUES (32135, 933860, 274, 'Discolored is a very good puzzle game, not too difficult with a cozy ambiant and some nice graphics. I recommend it!!! 🖤🩶🤍', 'Uninteresting, unimaginative, boring.\n\nThe game is basically 30 minutes long (if you take your time). Should be the demo for the sequel but instead you pay for it.', 'Mostly Positive', 76.28, 13.97, 1.28);
INSERT INTO reviews VALUES (32161, 934700, 4756, 'Lots of fun. Great game-play and lots to do. \nI got this game to play with my son and he is learning teamwork and perseverance.\nNah, just kidding. Mostly he and his stinky friend just keep on finding ways to blow me up, electrocute me, or set me on fire. Use birth control, people.', 'This message is for people wanting to buy this game on sale. DON''T buy it. 1. There is epic online service that is needed to play the game. 2. The ending is pointlessly abrupt and the game ends just when the story get interesting. The majority of the game was a chore and the story was lukewarm. And then when the story does get good it just end abruptly. And you would think DLCs might pick up the story? well no. sorry to break that news to you guys. It doesn''t. they are just irrelevant stories th', 'Mostly Positive', 77.33, 60.77, 79.82);
INSERT INTO reviews VALUES (32163, 934780, 652, '      If you were a fan of GTA, particularly GTA 2 during the late ''90s, and enjoyed the charming text dialogues along with the top-down 2D graphics, then you’re in for a treat here. This game may not be a high-budget blockbuster, and it might lack a plethora of options or an extensive arsenal of weapons. Some might argue that it doesn’t deliver enough intensity or that the dialogue is sparse, and while those points are valid, they don’t tell the whole story.\n\n      For those who appreciate indi', 'At first, I was having a fair amount of fun with this game. I think I found it by searching Stealth. I quit right when I reached the 2nd city when the cops were set off by impossible sight lines. I am also getting Win10 blue screens with only this game; 4 in these 9 hours of play time. It''s not a terrible game, but I don''t have time for an alright game that''s kinda unstable.', 'Mostly Positive', 76.07, 23.93, 9.32);
INSERT INTO reviews VALUES (32172, 934930, 256, 'was expecting a simulation, instead the game felt like forza, ok ffb, more towards the feel of an arcade game, cars are ripped off, clutch wasnt doing what its supposed to be doing, but a fun game for casuals.\n\n\nbuy assetto corsa', 'игра ебаное говно при запуске котоорого выходит надпись failed load shaders и в игре все кроме машины просто черное\r\n', 'Very Positive', 80.08, 2.55, 0.57);
INSERT INTO reviews VALUES (32189, 935400, 322, 'hi', 'should not have been released as a finished game', 'Mixed', 67.39, 1.55, 3.92);
INSERT INTO reviews VALUES (32194, 935580, 322, ' True Fear is MY NEW FEAR  \nI don''t review the HOG games i play in a critical manner but this one is truly one of a kind and worth a mention. This is a continuation from part 1 of the Trilogy, did it explain most of the stuff in part 1 in the second installment yes it did. So I played the 1st time off the expert mode and man it was tough as hell. Brace yourselves for these puzzles  There were minor bugs where the magnifying glass would not work and that had me run in circles. I liked the fact th', 'Terrible.  Just terrible.  I''m honestly baffled at how badly designed this game is.  How in the world did anyone think this was a good idea?  Was it play tested at all?  Did every play tester not tell them how fundamentally broken the whole design of the game is?  The basic problem here is that at any given time there are WAY too many areas open, WAY too many items in your inventory, NO JOURNAL telling you your objectives, WAY too many obscure pixel hunts in various scenes with critical things t', 'Very Positive', 92.55, 20.37, 7.85);
INSERT INTO reviews VALUES (32206, 935880, 965, 'A beautiful puzzle game with a stained-glass aesthetic.\nThe fantastical art captivates with its stunning visuals and unique charm.', 'Was looking for a chill puzzle game like the sequel but instead I got a pile of nightmare fuel. I’m sure some people will like that edge, but it’s not what I wanted.', 'Very Positive', 92.33, 9.27, 0.70);
INSERT INTO reviews VALUES (32209, 935930, 212, 'A diamond in the rough. It has great potential, but is limited currently.\r\nVery fun and enjoyable, just need some refinements and balance.', 'meh', 'Very Positive', 89.15, 19.05, 2.78);
INSERT INTO reviews VALUES (32220, 936140, 124, 'Yes, accurate game.', 'Shi*e movement around the peloton, AI only goes after you, completely ignoring other AI attacking.', 'Mixed', 67.74, 107.18, 94.90);
INSERT INTO reviews VALUES (32226, 936490, 242, 'The game has great concept and I enjoyed playing it for most of the time, but after a while it become repetitive and same missions get repeated over and over, specially after you manged to max all upgradable resources game get boring, so it will be a fun for around 10 hours so pick it up only for a good sales discount.\n\nPs: the some photages and pics of the game and trailer in early stages look even better in steam page more than the accutial game in the current stage, feels the game got downgra', 'The game has an amazing concept, and it does have its charm. However, the game is also very buggy and cannot speed up. Additionally the game will frequently get stuck and not progress. All and all, Great concept, but poor development.', 'Mostly Negative', 39.67, 14.17, 0.80);
INSERT INTO reviews VALUES (32227, 936500, 411, 'Great little game, not sure I would pay full price but £2.78 in the sale then its worth it. Not sure how people are finding this game confusing, especially the ones who claim to be avid lovers of transport sims etc. This is very straight forward, and the added features as you progress only help in the matter, so yeah I wouldn''t say this game is confusing at all, and if you just play the tuts and actually pay attention/read the wiki the game provides, then its pretty easy to get the hang off.', 'It is a cheap game and I got it on sale for next to nothing. But tbh it lacks any sort of depth and I mildly regret the £2 I spent on it. I was actually looking at buying another game by the same developer and publisher but I assume it is the same ''meh'' quality shovelware so I''m put off.\n\nEach city/town will have 1-4 possible other cities/towns you can create a route to which is a huge missed opportunity for progression since it would make sense to use trains for longer distance routes, and plan', 'Mixed', 67.64, 27.65, 12.38);
INSERT INTO reviews VALUES (32237, 936720, 1193, 'I removed every part and forgot how to put it back on 10/10', 'At this time I would not recommend purchasing this game in it''s current state. There are two different games. The game they are showing in their first preview video here on steam, is the beta version which has no objective attached to it. The BETA is where are all the cool tool variations are and the hatchback. But you cannot race a vehicle after building it and there are no jobs to complete like the production version.\n\nThe production game is no where near as detailed lacking any tool/vehicle v', 'Very Positive', 89.35, 3.92, 28.62);
INSERT INTO reviews VALUES (32241, 936790, 6800, 'Life is strange It proved to us how beautiful a game can be sometimes and how close to life it can be \r\nLife is strange Prove to us that sometimes things happen that we may not want but we have to fight against them \r\nLife is strange It proved to us that we are all like an actor and we have to play our role well \r\nLife is strange  proved to us to always smile even when the situation is not the way we want it to be <3\r\nIt was beautiful Game <3', 'Unfortunately it''s just not worth the price tag of 60 bucks. As a LiS fan I hate so say it, but True Colors felt like such a sellout. I''m still not sure how they got away with it, but this game really doesn''t justify the increased price.\n\n There are a few touching moments and you can tell they tried to recreate the LiS formula, but somehow it fails to deliver a convincing story. The narrative feels forced at times and characters are acting illogically - it just doesn''t flow. \n\nI don''t think I''ll', 'Very Positive', 91.00, 10.35, 17.27);
INSERT INTO reviews VALUES (32250, 936960, 178, 'alot of depth and surprises', 'This game is clearly abandonned, loads of bugs to be encountered no matter how you deside to play this.\n\nThe followup is same kind, fast easy money, and never going to finish the development nor fixing any bugs.', 'Mixed', 62.36, 16.75, 24.87);
INSERT INTO reviews VALUES (32262, 937170, 309, 'Otaku''s Adventure is an endearing little gem. It made me laugh. It made me cry. It made me want to yeet my mouse at the wall in unbridled fury. It made me cringe so hard that it caused me physical pain. A true roller coaster of emotions and experiences. As little as the game takes itself seriously, the story is surprisingly heartwarming, and at times heartbreaking.\n\nOtaku''s Adventure is essentially a multi-route visual novel with mini games and point-and-click elements sprinkled in (and some lig', 'I do not recommend this game.\n\nGOOD:\n- Art Style, comic-like story telling\n- Some jokes are funny (Only applicable if you play the game in it''s native language and can understand Cantonese)\n\nBAD:\n- Terrible mini games with crazy timing (I am talking about you, boxing)\n- Lots of re-loading your save files if you want to 100% it, and the other 2 problems stated below are pain in the arse related to this constant loading:\n- Unskippable Cut Scenes\n- Saves files do not lead you to the precise save po', 'Very Positive', 92.23, 16.97, 8.97);
INSERT INTO reviews VALUES (32267, 937310, 353, 'One of the best TD games I''ve played, and its free which is bonkers... One game that can hook you if you let it...', 'Windows Defender marks one of the game files as infected with a trojan. The game cannot run because of the quarantine for the file, and while this could be a false positive, I''m not going to risk and make an exception. Seems like the devs do not care much about the situation, there is no official response regarding the issue. So that qualifies as negative for me.\nI would also like to add that I''m one of those who paid for that game, so I don''t really care if it is now available for free. I expec', 'Very Positive', 87.54, 1633.27, 421.15);
INSERT INTO reviews VALUES (32279, 937580, 366, 'junko x reisen gex update when', 'Touhou 15 is very good but the experience of playing it was so nightmarish (only for me to accidentally delete my twelve hour save file on the final attack of the main campaign) that I cannot in good faith recommend anyone else enter this hell, unless they''re prepared to Pavlov themself into feeling physically nauseous when they think about this thing\n\nI''m writing this review to convince myself I''m finished with the game and get closure', 'Overwhelmingly Positive', 98.91, 18.88, 12.57);
INSERT INTO reviews VALUES (32287, 937850, 147, 'Meow', 'HIdden Paws Mystery is an hidden object game.\n\nIt is the second game in a series of 3 games where you have to find cats and yarn hidden in various 3D levels. This game was my least favorite of the bunch, the controls felt even worst than the first game, the game stuttered many times and some of the yarn and cats were hidden in cheap ways (black cats hidden in shadows, cats hidden in fog, grey yarn hidden in snow...) The graphics are nice, the levels are super varied (although some levels are jus', 'Very Positive', 93.20, 7.37, 2.03);
INSERT INTO reviews VALUES (32306, 938220, 197, 'Not a bad companion piece to DJMAX Respect if you find this game on sale. Especially if you''re clamoring to play DJMAX Ray songs again since this game has them\r\n\r\nAlso I''m a huge sucker of the morphing lanes mechanic', 'Game no longer starts, shows "Missing authentication information" and forces you to close it.\nSome stupid DRM system preventing playing legitimately purchased game.\nNO.', 'Very Positive', 90.36, 3.33, 1.35);
INSERT INTO reviews VALUES (32319, 938380, 234, 'A very christian game', 'The tutorial is so slow - it won''t unlock the necessary buildings for at least 2/3 minutes after telling you what you need to build! Dialogue is just as slow and painful.  You can fast forward the game day but not pause at all. I''ve had this for a while and I tried it again today and still don''t like it.', 'Mixed', 69.66, 23.75, 2.38);
INSERT INTO reviews VALUES (32324, 938560, 1574, 'Boys will literally make a work of art about suffering instead of going to therapy\n', 'The gameplay is incredibly clunky, even though this game should not be about the gameplay I''ve had to many moments where my character didn''t do what I wanted it to do. You move too slow for a game where you have to track back to previous locations to continue where you sometimes spent 5 minutes slowly going over the whole map trying to find where you have to go. The slowness took most of my enjoyment away.\nBut then the game should be about the story, but it''s hard to follow with these weird meta', 'Very Positive', 87.23, 3.53, 3.92);
INSERT INTO reviews VALUES (32330, 941460, 2531, 'This game could be really, really great. It is a shame that because the team is so small, the amount of work is just too staggering to complete in a reasonable amount of time before people inevitably begin to move on. And for that to happen to a game like this, a game with THIS much potential....really sucks.', 'I really want to give this game a positive review, but the devs haven''t put out an update in a year, and there hasn''t been a single update from them since they missed the past THREE milestones on their own roadmap, the lack of communication and progress is absolutely ridiculous, and its a shame because the game looks like it could have been great. I hope the devs sort their problems out because I''d be really excited to play whatever this game was supposed to be, but for now its just a half finis', 'Very Positive', 93.68, 3.60, 8.22);
INSERT INTO reviews VALUES (32332, 943370, 227, 'Co-op Dead Cells with simplified mechanics but excellent random level generation. Really fun if you get a good build/run going, and surprisingly deep customization once you get everything figured out.', 'i understand why the reviews are so bad\nit may not be a bad game but the maps are always the same there is no random generation and the monsters also seem to have fixed spawns each run\nmeaning the only difference in ur runs are the items u find, its not a roguelike just a beat em up with unlocks\nits also very short, not worth full price', 'Very Positive', 83.26, 4.88, 1.35);
INSERT INTO reviews VALUES (32333, 943410, 152, 'Playing simulation games since 1959. Istanbul is a remarkable game. I''ve taught it to dozens of rookies and Grognards. Been to "The Great Bazaar" and back. Can''t wait until I get my digital Mocha & Letters! \nTom Spirito', 'Dislike:I have 4 Inactive games in my queue.  How can I get them removed?  I am neither able to Abandon nor Continue these games.', 'Very Positive', 94.08, 106.02, 912.95);
INSERT INTO reviews VALUES (32334, 944330, 480, 'Great game. Just wish there was a c u m button during the f*ck positions. Maybe add that please', 'Complete and utter waste of money.\n\nI bought this game a long time ago because i really liked the concept but that was a very bad call. This project is way too much for the current studio to handle and to this day they only keep adding fluff to the game, its main gameplay loop remains pretty much identical as when it came out even though its been years. And what is in isnt good either. The maps are gigantic but are completely empty and you end up having to walk for an hour to just get to another', 'Very Positive', 82.08, 69.08, 37.65);
INSERT INTO reviews VALUES (32335, 945360, 361277, 'you’ll find some of the most braindead fuckers on the planet playing this game. it’s both frustrating and hilarious at the same time. someone will just randomly say your color and without hesitation, the entire lobby starts voting for you. people will come up with the dumbest reason for why YOU’RE the imposter, and since these kids don’t understand the concept of logic, they’ll just roll with it. fun game 10/10', '(THIS DOES NOT APPLY TO ALL PLAYERS!) \n\nUnless you can time travel back to Covid, its not worth it guys, im sorry.\nWith quickchat came bugs that are still left unfixed to this day. Glad i was there for the OG version of this game. All it is now is a buggy game were its impossible to find a good lobby. But when you do, its just (mostly* not everyone*) filled with braindead idiot players who are probably 4 year olds, people not trying, or racists and trollers or hackers.\n\nJust being honest, But he', 'Very Positive', 92.23, 73.80, 28.15);
INSERT INTO reviews VALUES (32336, 945770, 392, 'After 100+ hours in BG3, I began searching for a replacement. And while Dark Envoy isn''t on the same level, it certainly has the heart and brings a lot of fun.\n\nThe music is spot on, the setting and story are great. The character creation is deeply customization without being too complex (e.g. Pathfinder); with each class getting multiple sub classes the ability to further customize with enchanting. I think I spent as much time making character builds as i did playing the game.\n\nThe biggest issu', 'For about a year now the game has had a fatal bug where the game freezes up for no reason making the game unplayable. \nThe game is decent but for this bug that pops up during combat.', 'Mixed', 69.64, 27.33, 8.88);
INSERT INTO reviews VALUES (32337, 946610, 116, 'Love dungeon? buy this game\r\nGood at grinding? buy this game\r\nWant to play with friends on Beta-foreverTM server with a lot of bugs? buy this game\r\nCan it crossplay with player on Smartphone? idk I never try but buy this game!!\r\nThis game is on sale and you are in doubt? buy this game\r\nDoes dev still active and try to improve this game(26/2/2025)? Yes so pls buy this game:D', 'My Progress got deleted for some reason. Support wont even respond.', 'Very Positive', 81.90, 154.72, 35.80);
INSERT INTO reviews VALUES (32339, 947300, 715, 'Much, much harder than it looks.\r\nYou need to plan out your settlement before you start.\r\nI would recommend if:\r\n1. You need motivation to quit gaming.\r\n2. You have a messed up personal life.\r\n3. You find it amusing to see hours of work go up in flames because one stupid healer couldn''t do their job.', 'Nice intro.\n"Here''s the game, time is passing, good luck."\n\nYeah fuck you too.', 'Very Positive', 88.25, 10.53, 0.25);
INSERT INTO reviews VALUES (32340, 948740, 4003, 'Great game that gets dragged down by its god awful anime humour. Every 5 minutes they feel the need to add some terrible porn joke that it almost feels Pavlovian. The action scenes could be completely removed from the game and be swapped with a black screen that says "And then I beat everyone" that it would be better than whatever the game comes up with.\n\nBut when they actually decide to take things seriously, it''s quite a captivating story, made even better by its excellent soundtrack. The Engl', 'The dirty jokes is too much in this game!! Jokes about porn, boobs and pedophilia every 5 minutes!! even when there''s a murder case they still talk about boobs!! this game doesn''t make any sense!! you can''t take anything seriously!!', 'Very Positive', 91.93, 36.45, 2.37);
INSERT INTO reviews VALUES (32341, 949230, 28155, 'Colossal Order please re watch your own promotion video from 5 years ago by Justin Roczniak/donoteat01 and listen to what he says. That''s what a good city simulation needs to be able to do, on top of being a good looking city painter.   \n\nIts a start but still has some odd design. I think the worst part is somehow its more sterile and overly clean felling than the first game. Shame on Paradox for pushing this out the door long before it was ready. Making hardware requirements this high end was a', 'CS2 has been out for over a year what we learned:\n\nIt''s in an incomplete state.\nthe switch from steam workshop to Paradox mods has caused a crypto wallet stealing virus to be widely spread.\nThey are sort of listening to fans but are ignoring a ton of community concerns and requests\nThe other reviews cover the rest of the pros and cons of this game.', 'Mixed', 54.03, 93.77, 159.23);
INSERT INTO reviews VALUES (32342, 949480, 371, 'I was a tester on the previous game by Fabrice Breton, which was a pure point-and-click adventure game, but I was hesitant to buy this one because of the "Beat ''em up" tag.\n\nWell, I can tell that I was totally wrong in my suspicions: "BROK the InvestiGator" is a great adventure game, indeed! The "action" part is actually quite fun and not difficult at all, so I ended up not skipping any of the battles. The game is even much better than "Demetrios": the setting is quite unique,  the story is inte', 'I played a little over 3 hours and fell asleep toward the end. I did like this game, but it got to be just too much clicking and story filler. There was a sequence where it felt like 10-15 mins of just talking and talking and clicking and clicking. I felt I never got anywhere. The game is designed well, the fighting is ok. It just didn''t feel like I went anywhere with this.', 'Overwhelmingly Positive', 97.57, 8.22, 3.53);
INSERT INTO reviews VALUES (32345, 950740, 246, 'You can destroy israel', 'The only way you can enjoy this game is either if 1) you''re just along for the ride to learn about Chinese history or 2) a terminally online 14 year old Marxist-Leninist LARPer. \n\nThe game is barely more interactive than a choose your own adventure book, which could be fine, but the UI is abysmal, almost a parody of bad strategy game UIs. Very few actions are intuitive and or explained. There also is no creative flare or narrative. It breathes railroading where there are so few options that the ', 'Very Positive', 86.99, 50.35, 0.83);
INSERT INTO reviews VALUES (32346, 951440, 4696, 'Very fun game but it took me and my friend 12ish hours to beat it so keep that in mind. I saw a lot of people saying that the game is too hard but they are probably just dumb, if you use the tools available to you, it really isnt that hard.', 'The game is good and I know I put a bad review but really the only issue I and many other people have with this game is the "repairing simulator" part mid-late game when they CONSTANTLY attack your base. You have to keep coming back to make sure or check every module and it gets annoying and demotivating to push further into the game, so until they finally add some sort of repair module/bot after a suggestion with 80 upvotes from 5 years ago I am not going to keep playing this game', 'Very Positive', 85.26, 12.53, 24.53);
INSERT INTO reviews VALUES (32348, 953580, 575, 'I like it best among all the Bus Sims. Has a large challenging map and the best bus company management system. \n\nWord of warning though. Do not paint any of your busses in the game. It causes a variety of bugs after a bus is painted. Future purchased busses may not appear at the dock, routes gets swapped out with random lines. etc...   It seems to corrupt the save after a bus is painted. Hopefully the next update fixes this issue. So note the date of my review and if it has been patched since\n\nO', 'i really loved the idea of this game but TML are just terrible at making games that run well, poor graphics poor physics and terrible optimisation, for starters, they seem to get games out there and abandon them', 'Mixed', 62.96, 105.73, 12.65);
INSERT INTO reviews VALUES (32349, 954650, 938, 'I''ve been having a great time with this game, and I''m glad to say it totally works on the Steam Deck.', 'It is more a puzzle game than a tactical combat RPG. Very nicely done and polished, but not my type of games.', 'Very Positive', 82.84, 24.97, 1.73);
INSERT INTO reviews VALUES (32350, 955320, 136, 'Great Timer killer, though it isn''t too relaxing due to the time limit they put on each puzzle difficulty.', 'Pretty pictures but they''re often very muddy and monotone but you can keep solving puzzles by letting the game automatically grab the piece once you try it close enough to the right spot. The game doesn''t allow for you to combine pieces outside the field and the field has a dim version of the picture you''re assembling that you can''t disable. The game pretty much strips the enjoyable aspects of puzzle solving and just reduces it to dragging and dropping.\n\nYou''d think that it''s pretty hard to fuck', 'Very Positive', 93.38, 0.17, 12.58);
INSERT INTO reviews VALUES (32351, 955870, 223, 'If you have ever played REDCON, you will like this.', 'This is basically a mobile game, all the gameplay is two ships sitting a distance away from each other sending troops at each other ala "Age of War" (the flash game). I did get tricked by the store page into thinking that it would be a more tactically involved or deep game, but that''s really all there is to it.', 'Very Positive', 87.44, 10.73, 0.87);
INSERT INTO reviews VALUES (32352, 957070, 117, ':)', 'horrible game, crashes every 30 second. nothing wrong with specs just randomly crashes. would like a refund for such a poorly optimised experience for pcvr users', 'Very Positive', 94.02, 561.92, 74.13);
INSERT INTO reviews VALUES (32357, 960090, 207433, 'The cinematic and storytelling masterpiece of this game can only be compared to the story of Jesus Christ and the Bible.', 'I''m not liking the direction this game is taking. First, there was the double cash boost DLC, then a DLC that outright lets you skip part of the game, and now a rushed rogue-like DLC that mostly recycles assets from the base game. Modders have added better content for free. I can''t recommend it right now unless NK stops with the EA-style microtransactions.', 'Overwhelmingly Positive', 97.38, 115.67, 801.63);
INSERT INTO reviews VALUES (32359, 960910, 4322, '(-)Control: Controlling the character in this game feels like teaching a toddler how to moonwalk.\n(-)Story: Overall, the story was good, but it has too many plot holes.\n(-)Chapter 3: I remember playing the demo a couple of years ago, and now I understand why it started at Chapter 4… Chapter 3 (Father and Son) was written so badly.\n(-)Voice Acting: Some performances are great, while others sound like the actors were given the script five minutes before recording.', '5/10\r\n\r\nContrived high-school writing, cheesy action sequences, numerous plot holes. Ironically, worse than Fahrenheit in almost everything.', 'Very Positive', 80.75, 22.27, 22.03);
INSERT INTO reviews VALUES (32360, 960990, 5550, 'Whatever anyone says, but it turned out to be another exciting adventure from David Cage, the creator of such games as Fahrenheit and Heavy Rain. His games have the appearance of the gaming industry. "Fahrenheit" was a breakthrough in the genre of interactive cinema in its time. It had high-quality implementation of both variability and an exciting plot. Heavy rain finally won my heart, that I did not calm down until I walked it along and across to see all the possible endings. Only it impressed', 'I do not usually write reviews, but this game pisses me off so much I had to.\nThe most annoying part about Beyond: Two Souls is that motion cap tech, graphics, and acting are amazing and you want to experience it but everything else about the game make it unplayable, not just unplayable, torturous.\nThe writing literally boils my blood. This game has the most cliche, predictable, and overly dramatic tropes one can find in any content medium.\nCamera in the game makes me feel like they held a compe', 'Very Positive', 84.67, 79.30, 22.25);
INSERT INTO reviews VALUES (32361, 961200, 6395, 'I suck at League so I came here. Now I suck at two MOBAs. 10/10.', 'i played paragon. loved it. played this game. loved it...AT FIRST, then they came out with timed rank?!?!? no joust. brawls ok but i cant believe the amount of people who ruin the game in a 5v5 just cuase they died once. or didnt get a gank. the community sucks and the amount of people who just throw is insane. im done with this game. dont download unless you wanna get angry each match. they dont ban players, they let people run wild.', 'Mostly Positive', 78.00, 87.25, 712.93);
INSERT INTO reviews VALUES (32363, 961660, 183, 'Developer "Slow", The sequel Chromahertz... When?? I like your game a lot, Hope your next task going well. The day will come when your game will be recognized by more people.', 'Impossible to play properly with Keyboard controls, and would not accept my DirectInput gamepad. Might be playable on a 360 controller but not everyone owns one and I don''t fancy getting arthritis trying to constantly press four buttons with my left hand. In the gameplay department: invincibility period after being hit is not long enough, no hit stop, tiny jump height that falls way too quickly, and is visually confusing as to when your shots are connecting (to say nothing of the visual clutter ', 'Overwhelmingly Positive', 98.36, 14.13, 0.63);
INSERT INTO reviews VALUES (32364, 964800, 3925, 'Doom Eternal when the devs aren''t preoccupied with demanding that you mash the dash button every second or hotswap to the "correct" weapon for every enemy or placing you in slowdown goop or forcing you to Super Mario through hoops to get to the next "Doom" part of the game.', 'The game has a phenomal artstyle, great sound design and good feeling weapons.\r\nSadly, the gameplay loop feels very bad. It is overall hard to describe, but it''s one of those games where i only played it for 6 hours yet it feels like I spend years on this thing just trying to get through.\r\n\r\nI ended up not having enough fun to actually finish it.', 'Very Positive', 92.89, 0.37, 6.60);
INSERT INTO reviews VALUES (32367, 965580, 2613, 'The board game is great and this digital implementation is great too. The only thing missing is the option to play with 5-6 players.', 'This is a fantastic game that I cannot recommend due to a game-breaking bug whereby online multiplayer games get disconnected and there is no way to get around it.', 'Very Positive', 92.81, 81.30, 8.90);
INSERT INTO reviews VALUES (32371, 966330, 1754, 'Grass flickering and bugging as the game rise, with a gentle framerate.\nNo music to be heard and a soundtrack on the mobile.\nHer hands on the Steam Deck, my head on her shoulders.\nStill laughing from her complaints about the control and gameplay\nIn this simple ass, gay ass, artistic ass game.\nTis was a great night. Indeed it was.', 'Enjoyed it very much on PS3.\nI bought it on PC years ago : was glitchy, mute, didn''t work.\n2025 - still the case.\nThe devs just don''t care.', 'Mostly Positive', 79.02, 1.90, 0.18);
INSERT INTO reviews VALUES (32372, 966430, 272, 'The game is officially abandoned and will never be finished. BUT it features pretty fun souls-like combat with rogue-lite progression, a few characters to play with, and decent optimization. Not a bad deal at 80% off if you''re curious.', 'Man, I had high hopes, but the game being abandoned made me.... not want to play it.', 'Mixed', 64.34, 1.13, 1.78);
INSERT INTO reviews VALUES (32378, 971690, 152, 'Really fun game. I bought it to my 7 and 9 yr kids and they loved it. Recommended to dads looking for something pretty funny yet not too violent. Only downside is that after playing usually they demand deserts :P', 'Cake Bash multiplayer has been off for weeks. No response in discord or discussions 👎. I hope others will speak up as I''ve been seeing a few. Truly sad to see this game left alone. I''d suggest not buying until this game gets some love.', 'Very Positive', 88.16, 6.13, 0.58);
INSERT INTO reviews VALUES (32384, 977630, 226, 'Let''s make one thing clear, this isn''t a Shelter game. It fits the franchise, but the previous two Shelter games involved you being a mother and caring for your children. In this one, you have a child yes, you kinda have to take care of it, but I feel no attachment to it. The game doesn''t even change if your child dies. Having said that, the game is fairly decent. It''s fun, albeit frustrating, to play. There''s different paths giving it a small amount of replay-ability, and the story is fairly in', 'i really likedx the part where they made walls just high enough for me to see over to my destination but i have to walk all the way around them because the map wasnt big or interesting enough without it . baby elephant cute', 'Mixed', 47.79, 2.60, 1.08);
INSERT INTO reviews VALUES (32386, 978300, 1684, 'They took the original + smeared it with graphics (not bad (character redesign is controversial)) + we added a million bugs over and above those that were there = the remaster is ready. If you want to complete Saints Row 3, play the original', 'I can say I''m not big on this remaster. Overhaul it runs great and looks fine, my biggest complaint is the minutiae detail to censorship. Unless you''ve played this game when it came out unlikely you would even notice it, but those who have will. \r\n\r\nSome of the dialogue was changed, I noticed a few times. There is s couple clothing items and customization that was also changed. I''m not sure why they felt the need to change these things, especially for what this entire game series has been known ', 'Mixed', 68.11, 0.18, 4.95);
INSERT INTO reviews VALUES (32387, 978780, 3066, 'You are 10, sitting on the living room''s floor, holding a ps1 controller and looking at Popuri through your tiny tv, thinking "wow she''s so cute..."\r\n\r\nGirl, you are gay.', 'I love the game of what it is. I have played the GBA and DS versions religiously as a kid. There are quality of life features like not having to carry your chickens or push your livestock individually so they may enjoy the sunny day, walk through crops, and owning more trees. Multiple types of cows and livestock are a plus including the rabbits and pets you can purchase from Van. I don''t recommend this game, but it does keep me occupied to kill time when on the plane.\n\nWhat disappointed me the m', 'Very Positive', 94.19, 29.32, 14.18);
INSERT INTO reviews VALUES (32388, 979640, 1637, 'The game is fun. It feels like playing Prototype as an RTS, and you''re on the side of the squishy humans. \n\nAlso, the people complaining about the "DLC" are crazy. It''s literally an art book, a novella, a comic, and some two dollar skin packs that are explicitly for people who want to offer more money to support development. None of that is taking resources away from development to get money.', 'Am I going to keep playing this, yes. Does that mean I recommend it, no. Making a video game is hard, but the game shouldn''t be this unpolished, broken, and overall just rage inducing. The game is fun, if you can overlook your units not going where they should (updated navmesh huh), ugly ass vehicle movement (floating vic?), every update breaking something else. Honestly this game may be good some day if instead of trying to add new content, the dev team spent the next year fixing what they have', 'Very Positive', 81.86, 51.00, 40.80);
INSERT INTO reviews VALUES (32389, 981430, 1758, 'excellent deck builder game, great strategies with soo many different build options, very fun for the genre. huge replayability between the choice of characters with an added option of 1 of 3 different decks to choose from to even make them more of a niche'' build. good branching storyline. can see many many hours of my life sunk into this. def recommend.', 'In short you find a combo an repeat it infinitely, there is no reason to swap heroes and each hero progression is boring. After certain time new cards are worse then what you already have.\n\nJudging by the achievement stats 70% of players never made it past the ACT 1. They left all these positive reviews and stopped playing?', 'Very Positive', 88.28, 52.15, 42.70);
INSERT INTO reviews VALUES (32391, 981890, 173, 'Great game until my friend gets a 118M throw in hammer throw. This guy needs to do a drugs test.', 'Hi. Game isn''t playable. Not sure how a company can try to sell this garbage for such a price. Unreal.', 'Mixed', 62.43, 8.67, 3.98);
INSERT INTO reviews VALUES (32393, 983870, 1440, 'Satisfactory meets Minecraft.\nIf you like either of those games? You''ll probably like this one. My gaming group and I play all of the survival builder, factory builder, automation, style games and this is right there with Satisfactory and Minecraft in my top 3.', 'The game is fine, but it will install a third party Paradox game launcher to your system without telling you. That''s unacceptable to me.\r\n \r\nThis game doesn''t launch natively through Steam without a workaround.', 'Mostly Positive', 79.44, 311.92, 9.45);
INSERT INTO reviews VALUES (32394, 983970, 2173, 'Finally they added ability to play it as two women.\nGame has decent (a bit naive and romanticized) story and standart-ish gameplay with some unique twists (stylized exploration and jRPG battles).\n\nBest to play it with your couple on one screen (or via Remote Play Together), as it is focusing on romantic relationship and your actions can change some outcomes and events (thought, not much). Technically you can play it alone with an AI controlling your second half, but it is not as fun this way.\n\nP', 'I had read multiple times that this was a good co-op game for a couple to play. It''s barely co-op. Player 2 has minimal to no real agency. They just kind of follow around whomever is leading the way. Which makes it really awkward to move around at times, almost like you are being pulled or pushed. I guess if it''s something you want to play alone, go for it and it''s probably fine. \r\n\r\nBut I''m saying No to recommend here because it often comes up on co-op recommendations and it''s not a great co-op', 'Very Positive', 90.93, 180.50, 1.32);
INSERT INTO reviews VALUES (32395, 984680, 570, 'OK I am one of these old farts that have been playing computer games since PCs came out.  Master of Orion and MOO 2 were great back in the day, but games have evolved and there are lots of 4X games out there. We still need that beer and pretzel 4X space game.  Some are overly complicated like Stellaris and some overly simplified like the new version of MOO.  I just re-tried Interstellar Space Genesis (lame title) looking to scratch that 4X itch, and I think it is a worthy successor to MOO.  You ', 'To be fair, it''s not necessarily a bad game. I just found it to be tedious. There are a lot of turns spent just clicking next, next, next, while waiting for things to be built. The process to improve a planet is tedious. The research needed to improve a planet takes too long. The amount of planetary building that you can actually build is too few. The game is just, well, boring. Master of Orion, to me, is a better game.', 'Very Positive', 84.21, 93.58, 41.37);
INSERT INTO reviews VALUES (32398, 985830, 1675, 'my parents saw me playing this game, now they dont talk to me anymore.', 'game is 112 GB which is insane for what the game is.  Combat is clunky, game is buggy, Cutscenes are designed to stall the starting process to cause users to run out of the 2 hour limit to get their money back.', 'Mostly Positive', 79.10, 5.02, 0.47);
INSERT INTO reviews VALUES (32399, 985900, 193, 'It is a fun game with interesting graphics over a plot that evolves as you advance through the game learning about the main characters and seeing their growth over their ways.\nThere is a really accomplished combat system that rewards skill plays and it is very satisfying to pull off in the hardest difficulty.\nThe main issues I had were the balance of the game and how quickly it wraped up in the end. For the first point, i feel there is a heavy balance change between the first part of the game an', 'The developers have abandoned this game. There''s a nasty bug really early on in the game that was reported 3 years ago by several players and it still hasn''t been fixed. I played maybe 10% of this game and now I can''t progress because I''m stuck at a black loading screen. I can''t even refund this game since I bought it and didn''t play it until this week. Do yourself a favor and avoid this game.', 'Very Positive', 82.38, 23.17, 3.48);
INSERT INTO reviews VALUES (32402, 990080, 127204, 'I enjoyed it for what it was, a mid-tier game. For a bigger HP fan I could see it being much more entertaining. Definitely get it on sale though, as there''s no more development for the game going on and $60 is a bit steep.', 'Bought the game late last year, made a character, but only this past week got around to playing.\n\nAfter a recent update, you are now forced to agree to the game selling personal information. There is a visible "Do not sell or share my personal information" button; however, clicking it redirects to a website unavailable in the country I am currently in.\n\nI won''t be playing unless this is resolved in-game (and I''m not counting the manual opt-out form that has been posted on the forums which also d', 'Very Positive', 91.73, 46.32, 0.47);
INSERT INTO reviews VALUES (32406, 992300, 2077, 'The game has an item that transforms your male protagonist into a smoking hot babe with big rack.\nDoing so also gives you a stat boost!', 'Half of it is not translated. The other half is translated poorly. I don''t even know what half of the stuff does. Especially the weapon effects. The game isn''t bad, especially for the price. Consider this a neutral view.', 'Very Positive', 86.04, 1.23, 3.98);
INSERT INTO reviews VALUES (32407, 993090, 10378, 'i genuinely think bro is an actual tech-einstein while also being drunk enough to sell a nobleprize-worthy software at the cost of a starbucks coffee. Here take my upvote and upmost respect.\n\nnb: nvidia and all those greedy corporate scumbags can go to hell honestly', 'only buy this if have decent gpu with atleast 4gb-6gb of vram , not idle for low tier gpus with 2gb vrams', 'Very Positive', 93.33, 99.60, 0.23);
INSERT INTO reviews VALUES (32413, 996580, 8152, 'Steam deck compatibility needs to be dropped to Playable instead of Verified. When running at 60 fps (the games default setting) it will occasionally soft lock by not letting doors open or challenges complete. Reducing framerate in the performance menu does fix it, but you shouldn’t have to do that in a Verified game.', 'Jump height is bound to fps.\nI was wondering for the 5 hours I played with 120 fps why the game is so ridiculously hard, like had to make pixel perfect jumps to a point where I couldn''t do a ramp jump, not matter how hard I tried. So after a lil google search, I found out, Spyro jumps lower if you have high fps. At first, I thought "no way, they must be joking", capped fps to 30 and damn the game became much easier...\nThe fact the devs never patched this is a shame and negative review worthy.', 'Very Positive', 92.60, 18.33, 9.43);
INSERT INTO reviews VALUES (32414, 997010, 8994, 'i recommend the game BUT this message is to the developer mainly..  \n\nSTOP Releasing content - and start fixing the game.. the game has too many bugs that are easily fixed.  i will continue to not buy DLC from you lot until the game is fixed..', 'A line has been crossed\n\nI supported this game in the beginning of Early Access when nobody believed in this game. I thought it would be great fun but the developers really don''t care about delivering a great product with nice gameplay but to release unlimited amount of DLC for high prices. It''s not even at affordable levels. \n\nThat''s not how it works pals. Very sad developer.', 'Mostly Positive', 78.39, 29.27, 7.57);
INSERT INTO reviews VALUES (32416, 998400, 303, 'this game is like playing as heavy weapons guy from tf2 in the stalker world while persueing career in illeagle activitys whilst also being a train operator of the 1980s the games fantastic', 'If you were watching the gameplay ad, you might think this was a silly, quirky goat simulator like goofy game.  Run the train, drink the vodka, fistfight a bear!\n\nThe reality is, that is is actually quite serious, and very complex.  \n\nStarting the train requires about 25 steps -- turning on compressors, transferring throttle control to the correct station, releasing a series of brakes, managing voltage, changing compression modes, connecting power systems, and so on.  \n\nIf you want a silly game,', 'Very Positive', 90.76, 2.57, 0.47);
INSERT INTO reviews VALUES (32418, 1000410, 1345, 'Out of all the ''boomer shooter'' types, this one is perhaps the most faithful game of the era rather. The trailer on Steam doesn''t really do the game justice either. It shows off a fast paced action game with loud guitar riff music, WRATH couldn''t be further from that. While it IS a fast paced action game, the overall ambient of the game has this serene, ethereal and otherworldly feel to it. Even during boss fights which you''d think would be tense just has a soft and moody ambient playing in the ', 'frustrating', 'Mostly Positive', 77.25, 16.88, 8.70);
INSERT INTO reviews VALUES (32419, 1001270, 1266, 'Great game but not being able to save manually sucks. All the work I did rearranging my place and buying new stuff is gone. Please for the love of god, add this simple mechanic that has been around for decades', 'Thanks for nothing after adding new achievments for a stupid christmas event.\nStill no content after the 2024 roadmap was not reached at all.', 'Very Positive', 82.54, 15.27, 60.92);
INSERT INTO reviews VALUES (32422, 1003360, 138, 'feel so peaceful every time open this game. thank you so much', 'russian-made garbage about romanticizing the bleak parody of existence they live in', 'Mostly Positive', 76.09, 2.17, 0.55);
INSERT INTO reviews VALUES (32424, 1003590, 5008, 'Fact: This was Tetsuya Mizuguchi''s dream game when the PSP came out. He couldn''t really do it at the time because of licensing issues so the Lumines series was created. And now here we are.', 'This doesn''t support the play station 5 controller, but the games exactly the same as the one on the ps5 or any other console', 'Very Positive', 94.69, 50.48, 0.28);
INSERT INTO reviews VALUES (32425, 1004610, 181, 'this game lets you live out your wild fantasy of being john wick but as a roomba (robot vacuum) lol! you can also unlock all achievements in under an hour, making it the perfect quick fun gaming session 💀💀', 'confused this game with rumu. kinda disappointed but its my fault. Its pretty repetitive.  Feels like a proof of concept demo.', 'Very Positive', 88.40, 1.87, 0.55);
INSERT INTO reviews VALUES (32426, 1004770, 480, 'Both singleplayer and multiplayer modes are fun. I never expected a bullet-hell fighting game to be this enjoyable.', 'Every enemy has undodgable bullets. You also can''t control the aim, so your aim is always lagging behind where the enemy is.', 'Overwhelmingly Positive', 98.54, 24.53, 1.97);
INSERT INTO reviews VALUES (32428, 1005300, 1967, 'just love all of the games, murder trivia is so fun. wish it was less american though', 'ppoo', 'Overwhelmingly Positive', 95.68, 27.05, 5.75);
INSERT INTO reviews VALUES (32433, 1008020, 822, 'Stop making the male characters so hung that it looks like a bee stung an elephants dick and had an allergic reaction.....', 'It''s not good. Their previous game, Treasure of Nadia, was good. But Lust Epidemic has way too much annoying gameplay, and the sex scenes are just slideshows, not real animations like in Treasure of Nadia. You will be disappointed, don''t purchase this.', 'Very Positive', 86.01, 31.00, 0.98);
INSERT INTO reviews VALUES (32436, 1008710, 649, 'Im not ashamed of having this game in my library.', 'still better than overwatch', 'Mostly Positive', 77.20, 4.08, 0.38);
INSERT INTO reviews VALUES (32443, 1012030, 211, 'what if naoto from persona 4 was a slut? this game boldly asks that.', 'It''s not a bad game, however, everything about it feels generic from the combat to the H-scenes; of which nearly every combat encounter is more or less identical and the H-scenes are more or less 4 or so of the same scenes but with slight changes. I got more entertainment out of grinding levels and looking for scrap to upgrade my equipment and in a H-game that''s a bad sign.', 'Very Positive', 90.52, 4.28, 9.15);
INSERT INTO reviews VALUES (32444, 1012110, 754, '>join server\n>join VCs\n>build a loadout that''s just a bunch of fifth-hand WW2 weapons\n>my teammate is screaming GO HOME GI in voice chat\n>spawn in\n>get instantly killed from across the map by someone dressed as Pvt. Joker from Full Metal Jacket', 'I thought there would be a single player campaign. There is not. Probably never will be at this point.\nIf you like multiplayer FPS then this is probably a great game for you.\nIf you''re like me and you only do single player, you''ve wasted your money.', 'Very Positive', 90.58, 9.73, 0.25);
INSERT INTO reviews VALUES (32446, 1012880, 4644, 'People in this game are very friendly, for example, when I opened the door to strangers, they sent away all the trash in our bunker, although in their understanding trash is water, food, our son, and so on', 'this game is bad', 'Overwhelmingly Positive', 95.26, 4.02, 5.32);
INSERT INTO reviews VALUES (32447, 1013540, 176, 'This is one of the best factory game I have had the privilege to play . I play it the way I want and have fun experimenting with different builds.', 'In it''s current state, I''d say it''s not worth it yet. That said, the game has a massive potential. It''s an automation game, like Factorio or Fortresscraft, but it has yet to really solve the "run around and gather all the resources by hand" part of it in a realistic way. I''ve put enough time in to it I should be looking to extend supply lines and create sub bases in any other automation game (and if you check my history, I''ve played a lot of them) but instead I''m still busy micromanaging basic r', 'Very Positive', 84.66, 478.93, 413.02);
INSERT INTO reviews VALUES (32450, 1015890, 155, 'TASOMACHI: Behind the Twilight\nYukumo is a girl on a journey, flying an airship and soaring through the clouds when a mysterious shockwave damages her engine and she’s forced to crash-land on an Island covered by fog. Kogara, a stranded member of the Nezu cat tribe, finds her and asks for help in a mutually beneficial relationship. By restoring the Sacred trees, the fog will leave the city and its citizens will gradually return, and by collecting the tree’s lantern fruits – a fuel source – Yukum', 'So I decided to finally review this game after buying it years ago and putting only a few hours into it. my summed up words?\n make sure to get this game on sale!\nIn my opinion, Its not worth the 20 bucks ONLY BECAUSE IT FEELS UNFINISHED . It really does feel this way and I know I''m not the only one with this observation. The graphics and colors are obviously good and stunning, the levels are neat to jump around in and explore, however after a few hours it doesn''t seem like there is alot to explo', 'Very Positive', 80.65, 9.43, 5.52);
INSERT INTO reviews VALUES (32451, 1016600, 421, 'I really wish I had played this sooner than I had, especially now that I see there''s a sequel planned.  (And I hope said sequel is "more of this, but more polished".)\r\n\r\nAt first glance, it LOOKS like a bare-bones indie rogue-like, but once you start doing runs, there''s a LOT of content to unlock.  Characters, weapons, items, areas, and just gameplay additions and tweaks are earned both by progressing and thru a Dead Cells-like "purchase with currency earned by killing enemies" method, and it''s ', 'Game with great potential hindered by clunkyness and nonsensical difficulty; difficulty isn''t supposed to be instant attacks sometimes from across the screen while breaking your guard and homing like a sidewinder. And of course, your character is super sluggish, has to wait 10 billions years before doing an action after another, and dodge only works when the game feels like it, that''s not mentioning the general clunkyness of hithoxes and collisions.\nTo quote Gordon Ramsay : You''ve got no respect', 'Very Positive', 92.16, 48.30, 10.50);
INSERT INTO reviews VALUES (32452, 1016930, 147, 'An interesting story and the core gameplay mechanic promise a lot of entertainment. Unfortunately, the game falls short in many areas. I still recommend it. If you want to know what axes I have to grind with The Great Perhaps, watch my review, where I go into more detail:\n\nhttps://steamcommunity.com/sharedfiles/filedetails/?id=3434480163', 'I actually liked the overall chill & pondering of life vibe of the game. Had some major issues with keyboard functions, I use a wireless one & it normally does fine. But for the apartment scene, I had to get up & use my laptop keyboard to only get a marginally result, it was really frustrating. But the biggest reason I''m giving this game a thumbs down is the ending. You don''t find out the cause of the disaster, you find out the reason why you can travel to the past, but not why the world ended. ', 'Mixed', 64.63, 3.08, 6.70);
INSERT INTO reviews VALUES (32453, 1016950, 2212, 'It''s Blood Bowl. Rules are up to date. Can be a hair spotty at times with respect to bugs but they are actively working to repair those. Not hyper thrilled about the current and to date release schedule of new teams but overall it''s been a blast to play, just hope the cadence of team release speeds up a little. The latest "season" with two teams in it was great... Hoping they do more of that.', 'They locked all teams content behind a premium currency and a battle pass, and they are releasing the teams in seasons, despite having the ability to just have had all the teams out at launch. Along with this, the only way to do league play is against other players. So there is no way to practice team progression without playing in comp. Your time and money would be better spent on buying Blood Bowl 2 LE. While the rules for this game ARE updated to the current tabletop rules, if that matters to', 'Mixed', 47.11, 254.95, 6.15);
INSERT INTO reviews VALUES (32454, 1017180, 22503, 'Found beer, drank it all and filled my bladder, pissed it back into the beer bottle for 77% alcohol and 23% water. Continued recycling my piss beer while chain smoking and before I could do anything about it I died. \n\nFantastic Game.', 'They broke the multiplayer mode 2+ years ago and have no intention to fix it. I went into the discord a little bit after the last update and was practically told to f**k off by fans because multiplayer was no longer part of the vision of the game or whatever, now it has not been updated whatsoever in almost 2 years. \nCrazy. \n', 'Very Positive', 91.87, 6.98, 17.87);
INSERT INTO reviews VALUES (32455, 1018000, 114, 'All the negative comments I see are mostly related to control issues.\nI use a gamepad and it works flawlessly.\n\nIt''s a great little niche jump down memory lane of the golden age of gaming.', 'cant control with mouse.', 'Mixed', 54.39, 0.30, 0.28);
INSERT INTO reviews VALUES (32457, 1020800, 161, 'very good game but we need multiplayer is gonna be a lot of fun', 'Spent more time trying to work around bugs rather than actually doing anything in it, considering it''s this buggy after 4 years and the last update was in February I really don''t expect much. They got my money I suppose. Going to play My Garage instead.', 'Mostly Positive', 77.64, 243.97, 4.50);
INSERT INTO reviews VALUES (32458, 1021210, 1041, 'Has the heart of Xcom and the skin of Cyberpunk. If you''ve ever played Xcom and wanted more plot, or played Cyberpunk and wanted it to be more tactical, this game will scratch both those itches for you.', 'Fun concept but a lot of the design is pretty hostile. The game comes at you fast and hard and never lets up to the point where it''ll pretty quickly feel like you''re drowning. You never have enough people to do all the jobs and legwork that comes your way and even just skipping them leads to you being punished. Despite claims that combat is a viable approach any attempt to launch a proper assault is suicidal. Enemy security response will come continuously, too fast for you to handle, with enemie', 'Very Positive', 93.95, 133.17, 26.13);
INSERT INTO reviews VALUES (32459, 1021770, 244, 'getting over it fighting game', 'game is fun but i dont want to pay for dlc charcters', 'Overwhelmingly Positive', 95.90, 11.28, 1.27);
INSERT INTO reviews VALUES (32460, 1022980, 1600, 'This game was made by an insane person. The correct way to play isn''t taught to you, and you will doom several characters before understanding what happened. The flight interface is purposefully weird and impossible. Some of the mechanics and missions you rely on are noob-traps or actual outright traps. There''s an entire colony-simulator style mechanic that you likely will never reach. Exactly what I was looking for, exactly what I paid for.', 'I don''t mind the fact that I literally couldn''t figure out how to open a door in the first 20 minutes and I ended up repairing a fridge for days on end. What did bother me was the fact that the spritework is horrible. I cannot tell anything apart. I have played hundreds of hours of SS13 and other pixelized games that are probably even smaller than this game especially with the way Byond engine works (tiny ass window) and I still understand intuitively what I''m generally looking at. This game nee', 'Mostly Positive', 79.00, 17.35, 0.22);
INSERT INTO reviews VALUES (32462, 1024650, 557, 'Looking at my play time, I think you could say I enjoy this game. The ship battles are turn based which I love. And all the other aspects are very enjoyable to me. You have a nice map to work with. You do have to complete the initial campaign chapter to open all options. Each chapter is challenging but not impossible. Each faction has nicely interesting perks. The Fame tree is interesting and probably 80% the same for everyone. Just that last 20% is the faction perks. Playing "Free Games" allows', 'It wasn’t at all what I expected when I got this game. It is very trade heavy with minimal combat or events. \r\nThe gameplay is very Zen and hectic at the same time. It’s a mix of town-building and trading sim but is lacking slightly in both, and there’s way too many things to consider if you want to actively play it, I mean, this thing has about 10 tutorials for its mechanics. Overall if you like Zen games this is a good one otherwise skip it or buy on sale, I already don’t think I’ll be playing', 'Mixed', 58.35, 864.08, 7.67);
INSERT INTO reviews VALUES (32463, 1025410, 224, 'I like unique games that presents itself to stand alone as something special thinking outside the box. This game was just that for me. Enjoyed the game play. Games are made to tell a different story that takes you from the everyday life of routine. Immerse yourself as a bug to escape.', 'No pun intended, but game breaking bug in Lawyer''s Desk prevents progress. After reconnecting the cable for the certificate printer, the red dial to power up the pressure gauge just endlessly clicks and resets regardless of how fast or slow you turn the dial. Attempted multiple restarts to no effect.\n\nVery disappointing because I was actually enjoying the atmosphere and gameplay. Until fixed, do not recommend.', 'Very Positive', 80.80, 9.55, 1.48);
INSERT INTO reviews VALUES (32464, 1025960, 154, 'It''s been a long time since I''ve played a game that was this up my alley.\r\nA character-focused mystery that deals with the messed-up reality of social media and the entertainment industry? Yes, please.\r\nStill, before I start with the praise, there is one major caveat that buyers should be aware of: The English translation for this game is not very good, to the point of making things difficult to understand at points. If, like me, you know enough Japanese or Korean to get by via the voiced dialog', 'This game has a lot of potential but it doesn''t really explore it well. the different routes and endings are all very similar. The roles of each character are always the same, and having just finished it I already cannot remember the difference between the routes. it''s definitely a game with heart in it but it does not know how to foreshadow without being blatently obvious and the "gameplay" is probably the most pointless and obviously filler gameplay I have ever seen a visual novel include.\n\nIt', 'Mostly Positive', 79.87, 42.33, 14.60);
INSERT INTO reviews VALUES (32465, 1026680, 2311, 'Spent 15 hours drawing. Remembered I was doing it wrong. Drawing Meltdown for 15 more hours.\n\nSquall’s still emo, Seifer’s still a tool, and Triple Triad is still the true endgame.\n\n10/10 would awkwardly flirt with a sorceress at a ballroom dance again.', 'I like this game.\r\nBut the "remastered" is a rip off. Buy the 2013-Version (without "Remastered") and get the tsunamods - they even made a mod-manager.\r\nYou pay extra for a cheat menu. No graphic improvements. So again you need to get mods (what people made for free in their spare time) to realy remaster the game - and there are more mods for the 2013-Version.', 'Mostly Positive', 72.31, 23.42, 92.25);
INSERT INTO reviews VALUES (32468, 1028570, 417, 'The lofi most stressing you can find', '10 LIRAMI GER ISTIYORUM\n A\n', 'Very Positive', 84.41, 0.75, 1.02);
INSERT INTO reviews VALUES (32470, 1029210, 1614, 'If you ever wondered "what would Mega Man X be like as a roguelike?"  this answers that question and the answer is "awesome."  The soundtrack is solid.  Boses are interesting.  The plot you can uncover is a very nice touch and the controls are tight well refined.  This is clearly a labor of love on the part of the developers and it shows.  I can fully recommend this game.', '30XX feels like a step down from 20XX. Some may prefer the sprite work to the flash-style art of the original, but I think it pops out more. The background and foreground blend together in 30XX and it makes things unnecessarily difficult. I also have issue with the wording of how some Powers and Cores work; it''s very unclear. I also feel the progression isn''t anywhere near as solid as 20XX, and the gameplay loop doesn''t feel as satisfying. After only 3 stages I get tired and want to quit, wherea', 'Very Positive', 91.39, 112.13, 24.20);
INSERT INTO reviews VALUES (32471, 1029690, 8256, 'The best part of the game is when a wounded Hitler was stammering and pleading for his life only to say "Mein Gott, Karl really is the Sniper Elite 5!"', 'Loved all the sniper elite series from the start but what are the devs/publishers playing at with the overpriced DLCs now? £10 for one mission, £30 for two missions. it''s become an awful business model. Base game is great after the patches. DLC prices stupidly high.', 'Very Positive', 83.22, 22.07, 73.00);
INSERT INTO reviews VALUES (32472, 1029780, 7525, ' I have 1000 hours in Rimworld  \nI got this game since it scratches that same itch, but I have to say it does more than that. At first I thought this was just a  Medieval Rimworld clone  but it really stands on its own as a game. I''m having a good time and the devs pump out content. \nIf there are any early Rimworld players out there, they know it took time for it to be the massive game we know it for today. So give this game a chance and  let the devs cook ', '{More neutral than an actual negative review} A colony sim that plays like a 3D Rimworld or Dwarf Fortress, with plenty of customization, great build options, weapons and systems to play around with. Some persistent AI issues have never been addressed (pathing, job priorities (settlers will often harvest some crops --> cut a tree halfway across the map without picking any wood up --> move to another part of map to mine one block --> move back to crops, by which time they need to sleep)), optimiz', 'Very Positive', 89.95, 87.03, 161.37);
INSERT INTO reviews VALUES (32475, 1030830, 6885, 'Mafia II but it looks better and doesn''t crach a lot \r\nAnd this is how remasters should be just up the grapichs and chance nothing else capcom could learn from 2k it seems', 'What 2K and Hangar 13 has accomplished here is nothing short of revolutionary! They''ve somehow managed to transform an 8 GB classic into a massive 44 GB masterpiece, all while preserving every single detail exactly as it was. The sheer dedication to achieving a perfectly indistinguishable visual experience compared to the original is truly admirable! This ''Definitive Edition'' is an essential purchase, if only because the original, tragically, just won’t cooperate with Windows 11. A truly stunnin', 'Mostly Positive', 74.15, 44.83, 15.70);
INSERT INTO reviews VALUES (32476, 1030840, 24462, 'It''s short but the story is great! Really great to drive around the city, but the cops are merciless! Be careful! :D\n\nBut after finishing it, I don''t fell like coming to it again. Took me around 14 hours to finish and I am not a fast player.\n\nIt''s a good game, but for me it is not worth the full price.', 'Amazing game but such a pain in the ass to start up. It crashes my whole computer cause the game launch is so handicaped. You gotta change the format for the screen in the settings but the game launches so you can''t get into settings and then it freezes your computer.\n\nEdit: Still can''t get the damn game to launch. Tried everything even reddit, god this is annoying someone got a fix?', 'Very Positive', 86.69, 14.50, 17.80);
INSERT INTO reviews VALUES (32481, 1032430, 5073, 'i killed two crackheads with blunt force trauma to the skull, and shot another 4 times. then i went home and did the exact same thing in blood trail. great game.', 'Do not buy this. The clips you''ve seen on YouTube that probably led you here is only on Experimental. It''s been almost 6 years and this game has barely evolved from being a tech demo. The long-awaited (and grossly unfinished) gore update is still only on experimental test branch where melee NPCs have been broken for months. All you can do is shoot unarmed bots or terrible AI with pistols. It''s worth probably 5 bucks, and for whatever reason this game''s community are turbo copers and questioning ', 'Very Positive', 82.02, 8.97, 15.33);
INSERT INTO reviews VALUES (32485, 1035050, 130, 'Alt-Frequencies is a good short game with an original story, some nice graphics and a relaxing ambiant. I recommend it!!! 💗💗💗', 'I preferred A Normal Lost Phone and Another Lost Phone, but this was still a decent game. I just did not get into it as much. It had an underwhelming plot. I just wanted to finish it to finish it. I''d recommend it on sale only.', 'Very Positive', 86.15, 32.98, 3.22);
INSERT INTO reviews VALUES (32488, 1036240, 1202, 'It does take a while to get into it. The tutorial is great at first but then kinda just throws you to the wolves. I did have to restart bc I was prioritizing the criminal lesson challenges but then was broke AF. Once you get the hand of it though you''re locked in', 'Poor combat \ngame breaking bugs\nunpolished\nnot optimised\n3/10', 'Mostly Positive', 72.71, 58.73, 6.83);
INSERT INTO reviews VALUES (32491, 1040200, 9572, 'A low income janitor that, because of the crappy healthcare system in America, can''t afford his daughters hospital bills and has to take a side gig as a crime scene cleaner for a mob boss. The setting might seem intense but it''s a chill game. There''s no time limit, no enemies, just you and your cleaning supplies. It''s a game where you can relax, put on some music while cleaning the crime scenes spotless, all while you IRL room gets messier and messier because no one likes to clean their room.\r\n\r', 'I loved this game but wish I had been made aware that the devs chose to use AI generated pictures in the game. I found out too late to get a refund.\r\nOverall the game is well made, and I don''t think you can justify using AI when you can buy stock photos for the same result. Generative AI is not only stealing assets from artists, it also heavily contributes to pollution by its sheer use of power, both things that i''m not in favour of supporting monetarily.', 'Overwhelmingly Positive', 98.10, 16.52, 22.15);
INSERT INTO reviews VALUES (32492, 1040230, 539, 'Shouldn''t the second one of these be called the Bi-Curious Expedition?\n\n(Oh, also fun game.)', 'Sorry, but even for me, a Bi-Sexual furry, that game is not enjoyable for me because of the "overkill wokeness". Characters can have any gender, which is fine nowadays, but not in that time and age. It is romanticizing the era with "oh look how we accept anyone". I don''t mind representation. I mind overrepresentation. Make one or two characters queer, I don''t mind, would be good inside the "statistical" chance. But since anyone can be anything, I don''t like it. Also as others stated most if not ', 'Very Positive', 84.23, 25.55, 0.47);
INSERT INTO reviews VALUES (32497, 1043340, 1379, 'They lied in the game description you can actually travel to times before 1 A.D. several thousand years too. They over delivered by quite a large margin with this one. Highly recommend.', 'EDIT: Game developer was swift to respond and took the neccesary steps as to not mislead anyone. Big plus in my book, definitely pick it up for the singleplayer story which is very detailed and quite interesting, maybe it could be incorporated into a multiplayer aspect when the story nears completion. Developer could have a gem on his hands. if your buying it for multiplayer, give it some more time (let it cook basically) but if you loved BTTF you''ll apreciate this custom rendition of what could', 'Overwhelmingly Positive', 97.75, 45.92, 5.47);
INSERT INTO reviews VALUES (32499, 1044620, 791, 'good sport simulator. your job is to train them', 'Some of the character quirks are annoying. The relationships develop too suddenly. The fictional sport is pretty boring. The writing gets laughably bad during intimate scenes. The protagonists "trauma" feels like a weak excuse. The Misaki route is better than the others. The characters don''t have enough depth to make them interesting.', 'Overwhelmingly Positive', 97.35, 16.98, 27.23);
INSERT INTO reviews VALUES (32500, 1044720, 8254, 'Pretty great colony sim. Has come a long way. Does it do much different? Not really, but its not super complex and I like that about it. Its very much play at your own pace with great game design compared to the over cluttered other colony sims. Relaxing game to play.', 'Just another banished, nothing new to a saturated genre.    Hate that walls can''t be built at angles or rounded....your settlement is always built in squares and rectangles, doesn''t flow or look natural.     Immersion breaking for me.\n\nDefinitely wait for a sale, I would recommend this game but not at $30, there are other survival city builders that are just as good and cheaper.', 'Very Positive', 87.24, 28.65, 51.55);
INSERT INTO reviews VALUES (32501, 1046480, 158, 'Idol master and lovelive which one better? Different person will have different answer.', 'TL;DR If you''re looking for Idolm@ster eye candy, this is the game you''re looking for. If you''re looking for a fun simulation type of game where you manage idols, look elsewhere cause the gameplay is torture.\n\nSo I will preface by saying that this is my first idolm@ster game, so I don''t have any comparison to the past titles.\n\nThe good: It''s a bandai namco game with a strong IP, of course the only thing they aren''t gonna screw up is the visuals. The characters look great, the songs are great, cu', 'Overwhelmingly Positive', 95.57, 16.22, 31.05);
INSERT INTO reviews VALUES (32506, 1054490, 5688, 'A beautifully illustrated digital version of a board game I fell in love with instantly. I''m a big fan of engine builders and this is the game that taught me how much I like that style of game. I''ve been playing online with my friends a lot!', 'Game is fine but it will constantly barrage you with ads to buy their DLCs and "news" (telling about another dlc). You can''t turn this off.', 'Overwhelmingly Positive', 95.09, 32.98, 1.67);
INSERT INTO reviews VALUES (32507, 1054510, 1366, 'I rarely review games on Steam, despite so much of my life being taken up by them, but I recently had a positive interaction with the developer, and I feel the need to tell you all that this game is worth a purchase. I love the game in its current state, which is still under development, and I love it even more with between 40 and 50 mods enabled at any given time. What makes this even better is that I had a game-breaking error that was caused by a mod, but I had no way of knowing this without s', 'Rule 10 on the developer''s discord:\n\n"10. Racism, sexism, homophobic, transphobic, or other offensive language, will not be allowed in this server. Offensive content will also not be allowed in this server. Memes that use offensive language, or depict potentially offensive events, will be discussed by the staff if it is tolerable or not. If you are warned about the memes you post, then be mindful of the memes you continue to post. Refusing to do so with result in being muted for a set amount of ', 'Very Positive', 88.21, 321.68, 82.23);
INSERT INTO reviews VALUES (32508, 1056180, 205, 'One of the best metroidvanias I''ve ever played (and I''ve played pretty much all of them lol). Unlike what all of the other reviews will tell you, it''s not actually that hard if you''re experienced with the genre. It is definitely not beginner friendly though. I thought it was a great difficulty level pretty much the whole time. I would highly recommend exploring and getting all of the upgrades for a smooth and fun experience.', 'In most metroidvanias if you run into a boss or area that is too tough you back track and find power ups. In this one you back track and find a power up that gives a +1% chance to negate damage from a hit and gold you can''t spend on anything because you already bought all the power ups in the store that are shockingly unhelpful.', 'Mostly Positive', 72.68, 16.33, 13.23);
INSERT INTO reviews VALUES (32509, 1056610, 144, 'A really good, short, depressing point and click puzzle game about an elderly man losing his memory and missing his deceased wife. \n\nNice visuals and trippy, ambient soundscapes.', 'The game is literally 30 minutes long and contains very simple to solve puzzles. There is a speed run achievement for beating the game in 22 minutes (Very difficult due to poor puzzle mechanics). A ridiculously buggy ball puzzle where you hold down buttons to charge the shot for each of the 4 directions. You must get them exactly right each time. Its like in those mini golf games where you judge your swing power but it goes up entirely too fast to control reliably let go at the number you want. ', 'Very Positive', 84.72, 1.72, 3.77);
INSERT INTO reviews VALUES (32510, 1057540, 224, '"It was the Yuletide, that men call Christmas though they know in their hearts it is older than Bethlehem and Babylon, older than Memphis and mankind". H.P. Lovecraft - The Festival\n\nH.P. Lovecraft liked Christmas. I don''t like it that much so I''m glad to have found a game that put me in the perfect mood for Christmas. The story, the setting, the soundtrack, the funny dialog, everything fits the Christmas season. The spirit of Christmas has been reawakened in me. Thanks for that. Fhtagn!', 'There''s nothing really wrong with Cthulhu saves Christmas, but there''s nothing spectacular either. The characters are fun, there''s a good blend of humor and action, but it''s a very short game with very repetitive battles. The battle system seems interesting at a glance, but it''s just fluff you''re most likely never going to need.\r\nIn the end, my dealbreaker for not recommending it is the pricing: game is not priced appropriately for what it offers.', 'Very Positive', 89.29, 5.47, 8.65);
INSERT INTO reviews VALUES (32512, 1058450, 1556, 'I have 19 minutes played at time of review.\n\nI opened the game > Went to adjust volume > The voice volume has samples of characters talking\n\nThey recorded around 20 minutes of characters just talking about adjusting the volume. This is peak game design. I have not played ANY of this game yet.', 'doesnt work on PC via steam hit start and it just stops waste of money big scam', 'Very Positive', 88.56, 3.35, 0.12);
INSERT INTO reviews VALUES (32517, 1059880, 135, 'i played this game from app store a lot about 10 years ago.i suddenly remembered it but forgot the name, took me some time to find it. still love it!', 'Buggy pc port of a mobile roguelite platformer. Buy devious dungeon 2 for a slightly better experience.', 'Very Positive', 82.22, 1.05, 5.77);
INSERT INTO reviews VALUES (32518, 1059980, 735, 'Great little game for the price.  Has some rough spots, but the mechanics are solid.  Works perfectly on deck.\n\nIf you loved Brotato and are considering this, please don''t hesitate.', 'I wanted to make a pet army team, come to find out this game forces you into not playing that way, or rather any way you want.', 'Very Positive', 89.80, 13.23, 0.15);
INSERT INTO reviews VALUES (32520, 1061090, 4811, 'After getting the last achievement, I sat there looking at my screen. I broke down and shed manly tears, not because the journey was finally over, but because I know I will no longer be the same person after completing this game. This game taught me that if I put my mind into what I do, I will be able to accomplish it. But I don''t think I can recover from the mental damage inflicted when going for this completion. \n\n10/10 would recommend', 'don''t buy it I already broke 3 monitors and 5 mice', 'Very Positive', 91.44, 215.65, 1.48);
INSERT INTO reviews VALUES (32521, 1061180, 563, 'Fast physicky platformer with a punchy grapple that''s good for reaching high velocity and recovering from mistakes. Great soundtrack, short game, generous checkpoints, movement is smooth as glass. Level 1 your struggling to aim your grappling parabola over a small gap, by level 25 your Spiderman on adderall doing quadratic equations while travelling at the speed of light. Looking forward to Crumble 2: The Way Of The Blob.', 'Great when the game stops holding your hand and lets you go fast. Unfortunately, it likes to stop you from going fast with hard geometry rather often.\n\nI''ve seen speedruns bypass this, of course (and most of the levels in turn), but picking up speedrun tech requires you love the game first, and I''m finding it hard to love the game.', 'Very Positive', 90.05, 2.70, 0.55);
INSERT INTO reviews VALUES (32523, 1061730, 246, 'Super Monkey Ball: Banana Blitz HD by Sega is a non-stop action thrill ride that just keeps entertaining, A well polished game, great theming, and lots replayability make this one a keeper for me.  It scratches a certain itch I need once in while for game.  I don''t play as much as I probably should, but it always brings a smile to my face when I do.', 'FUCK THIS GAME SO FUCKING MUCH, MY FUCKING GOD, THE BOSSES IN THIS TRAVESTY MADE ME WANT TO RIP THE HAIR OUT OF MY SCALP AND SCREAM LIKE I''M IN A PADDED CELL IN AN ASYLUM. ONE OF THE WORST GAMES I HAVE PLAYED FROM BEGINNING TO END', 'Mixed', 57.72, 0.35, 8.95);
INSERT INTO reviews VALUES (32526, 1062520, 13952, 'Animal Crossing had a child but doesnt know if the father is Stardew Valley or Minecraft. This is the product.', 'Selling thousands of copies of a game to people only to turn around and require us to literally sell our identity in order to play it is beyond unethical. I had a lot of fun playing Dinkum in early access, and was highly anticipating the full release. However, this new EULA by Krafton is unacceptable in every aspect. There is no reason I should have to sign away my identity and my rights to my personal information to this degree just to play a non-competitive single player game. If this was an M', 'Very Positive', 94.29, 162.07, 131.58);
INSERT INTO reviews VALUES (32528, 1063420, 4218, 'When playing solo this game is good. \nWhen playing with decent randoms its very good.\nWhen playing with friends this game is incredible.\n\nOnly problem: Despite the game having a good amount of content that does not go stale fast, I want more. Of everything. Higher difficulties, more ships and ship layouts, more skills, more components, more enemies, more bosses. In short: more Voidcrew!', 'You''ll first be dazzled by its gilded halls, yet after just a few hours, see nothing but shallow pools with untapped potential. \r\n\r\nI really want to like this game, but unfortunately I cannot give it a thumbs up. I played this game almost a year ago and it hasnt changed much since, yet it is out of early access and in 1.0. There is so so much that is just.... half-assed isnt the word, and yet it fits nonetheless. In my opinion, the devs wasted far too much time on inconsequential or semifrivolou', 'Very Positive', 89.19, 85.92, 32.20);
INSERT INTO reviews VALUES (32537, 1068460, 103, 'This game is a hidden gem.  Absolutely must play for puzzle platformer fans.  Really, really good.', '', 'Overwhelmingly Positive', 100.00, 6.97, 0.00);
INSERT INTO reviews VALUES (32548, 1068640, 238, 'best sex game ever\r\n', 'gotta give them credit, stole my money and didnt provide much else in this game, W game. 10/10', 'Mostly Positive', 71.01, 3.27, 1.07);
INSERT INTO reviews VALUES (32553, 1068820, 2401, 'I pretty much use this to have windows media controls on my wrist while doing anything in VR.  And after 3700 hours, I can say it''s good at that.', 'I''ve had more issues trying to work with this then it helps, if anything i''d recommend this to people who enjoy having everything just crash abruptly because you dared to think about trying to use any of the "features'' Oh you don''t like the countless floating bars that aren''t attached to anything? Hover your cursor near the close window button to just, you guessed it crash. And yes i''ve sat down with several other users to attempt to assist me to make this program even function properly, and nop', 'Very Positive', 88.59, 4238.48, 132.98);
INSERT INTO reviews VALUES (32562, 1069030, 350, 'Fun Game, does glorify mister Elon a bit to much tho, hopes the second game tones down on the glorification of a fascist', 'Extremely laggy in the late game... on a fairly beefy computer. Got to the point where the best thing to do was to stop expanding, because the lag hurt more than the additional resources helped.\r\n\r\nThe cardinal sin of a building game.', 'Very Positive', 92.00, 3.97, 8.75);
INSERT INTO reviews VALUES (32570, 1069160, 2448, 'Excellent distillation of modern CRPG design into a DOS-colored dream.  Cosmic horror themes, Lovecraftian almost explicitly.  Deeply respectful of your time while also telling an excellent story, this is an extremely ECONOMICAL game.  Sometimes this economy works to its detriment--I would have liked a little more crunch in the combat and character building, but this is nitpicking, and I am a sicko.', 'I was so excited to play this game. A retro RPG with turn-based combat, pixelated graphics, and Lovecraftian horror theme! Count me in!\n\nIt started wonderfully. I restarted a few times to try different characters (hence my 15 hours), then settled on one and started playing. The game was very fun, engaging, and like a breath of fresh air among all other modern "RPG" games.\n\nThen why the negative vote? Simple: It has bugs so severe that you are locked out of progressing in the game. Here be spoile', 'Very Positive', 93.95, 37.63, 15.48);
INSERT INTO reviews VALUES (32572, 1069190, 330, 'An hour of this game is a trillion times more fun than Elite: Dangerous''s cargo contracts.\n\nIt truly feels like you are flying a shuttle, the engines are powerful enough to fly to stations and back and the fuel capacity is forgiving, you just need to have the skill to fly and the knowledge of orbital mechanics.\nIt''s calming in a way that even Truck simulators can''t match.', 'I really liked this game when I played it the first time. Well done so far. However, it is lacking a lot of content and the devs haven''t put anything new into it for ages. Actually, the last update was 6 months ago in Oct. 2024 by now, and during all 2024 the progress was already rather slow anyways. For 2025 I can see no plan to release any big new content, there is only talks about closed betas for minor updates in the forums. For me, this smells like abandonware kept buyable by small fixups e', 'Very Positive', 94.85, 26.98, 23.90);
INSERT INTO reviews VALUES (32587, 1069530, 554, 'Since I don''t want to give a NEGATIVE rating, I want to start with what I DIDN''T like for readers to know this is not a high-praising review. Steam does this positive/negative rating which I always found extremely misleading and inaccurate.\nThis is a game for people that loves a story and appreciate art, not someone that enjoys complex mechanics and character evolution. The game mechanics are extremely simplistic, I certainly didn''t enjoy much either the combat or the platforming. There''s also Z', 'I just can''t with this game. I don''t know how people like it. Boring combat loop. Easy boss fights. Crappy level design where you can''t tell if its a background or a platform you''re suppose to interact with. And tons of empty rooms. And the real reason I''m writing such a negative review. No F*ing Map. How simple would it be to make one? It''s like the devs are just trying to pad hour game play hours with needless backtracking. "Hey, remember that room? No? Good." F*ing stupid. Even before I had m', 'Mostly Positive', 78.88, 4.52, 4.08);
INSERT INTO reviews VALUES (32590, 1069640, 2542, 'So after reading through some of the negative comments, people are saying this game is full of bugs.  I''ve cleared the entire map and nearly 100 hours worth of gaming, I''ve not once experience any bugs.  The game ran smoothly on my PC.  Perhaps get a better PC?  This is a good game and an amazing atmospheric experience.  Yes, I would recommend this game.', 'Abandoned game, do not buy!', 'Mixed', 68.37, 97.33, 7.10);
INSERT INTO reviews VALUES (32591, 1069650, 1173, 'Ultimate Admiral: Age of Sail has a lot to offer. While it doesn''t offer a historical re-enactment, this game sets the standard for realism in Age of Sail sea battles against which future games will be compared. The combined land and sea battles (as well as the land-only and sea-only engagements) are very enjoyable and the harder missions offer a satisfying challenge.\n\nBeing able to customise ships and land units is a fantastic feature. The game offers many different classes of ship - for exampl', 'In terms of historical accuracy, this game is nothing short of a complete disaster. Not only are the ships modelled too few to adequately represent the variety of ships of the period, the ships actually modelled are also incorrect. HMS Victory for instance is represented in the game with 112 cannon (compared to the 104 carried at Trafalgar) and the layout of said guns is also incorrect (compared to the ship actually in Portsmouth). The Barfleur-class, the only second rates represented in the gam', 'Mostly Positive', 77.41, 330.35, 66.53);
INSERT INTO reviews VALUES (32592, 1069660, 3903, 'This is my favourite game, but as you can see from some of the other reviews this is that special kind of game where people can play it for thousands of hours and not recommend it. \n\nHow is that?\n\nI think it is because this game makes you care. Games are all about the consequences of your decisions and I have never played a game that gives you consequences like this one. The loop of designing ships, using them in combat and then learning the lessons from that for what you need to do going forwar', 'They made sure to destroy the modding scene right before ending development and support and then going out of business.\n\nPerfect fatality, no notes.  \n\n(don''t buy it, they left it in a terrible state)', 'Mixed', 64.08, 2183.75, 115.48);
INSERT INTO reviews VALUES (32594, 1069690, 577, 'While it is a good game, it feels a bit unfinished. There are a few bugs to stomp, some visual, some not, and there are some things that I doubt the author intended, like how once you clear a scenario, you can''t go back to a lower difficulty, which can get you absolutely stuck in pretty unwinnable places.\r\n\r\nThe voice acting is nice, and I do love myself some flavor when you are talking about different classes. How the defeats are canonically explaining by the Devil cheating and turning back the', 'Just feels unfinished and abandoned. Language still has weird bits of French all over the place. A disappointing end to a really cool concept. Stick to Darkest Dungeon', 'Mostly Positive', 72.96, 50.07, 12.60);
INSERT INTO reviews VALUES (32597, 1069740, 3424, '\r\nDon''t be fooled by simplicity. Great platformer with interesting story. Collect bits of hope and avoid negativeness. It reallu makes you sit til the end.\r\n', 'Looks good and has lots of potential but is effectively abandonware - last update was in July 2021, and the one before that November 2020. Developer is working on Seen 2, while this is still in Early Access.', 'Very Positive', 91.33, 3.68, 4.27);
INSERT INTO reviews VALUES (32599, 1069760, 371, 'I will admit, reading through the third entry from PixelFade was kind of underwhelming at first. The visual novel itself presents you with a pretty humdrum story and plenty of visual novel tropes and cliches along the way, most of which get pushed away to the side to focus less on the narrative and more on the moments with their characters... It''s kind of PixelFade''s signature at this point: slap together a hamfisted, barebones story and reason for characters to be together, but then surprise us', 'Maybe its good but when I was forced to make some stupid ass decision to make any progress in the story I quit.', 'Very Positive', 93.53, 38.32, 0.20);
INSERT INTO reviews VALUES (32625, 1070330, 1546, 'this game changed changed my life, only complaint is you cant have sex with putin', 'A good meme game has good memes and good gameplay, this has mid memes and subpar gameplay. The upgrades, costumes, and locations are all essentially the exact same, they don''t do anything unique. There is no ascension feature that a lot of clicker games have.\n\nThe majority of clicker games take time to complete even if you''re using an auto-clicker - this took 10 minutes to 100%. It contains ads for other games that you can''t dismiss off the screen. You also can''t play in windowed mode, there are', 'Very Positive', 90.36, 0.37, 9.83);
INSERT INTO reviews VALUES (32638, 1070550, 405, ' Hello, I''m your friend Bill. please make sure that I pass away calmly. ', 'overrated on steam250 hidden gems\nplease downvote', 'Overwhelmingly Positive', 99.51, 2.10, 0.88);
INSERT INTO reviews VALUES (32639, 1070580, 1696, 'car !!\nThis is how I drive to your mom''s house\nand my wife leave my ass for drive this car''s wtf is going on here', 'Its trash, actually no.... some trash can be recycled... this... just no, NO!', 'Very Positive', 91.16, 4.57, 0.20);
INSERT INTO reviews VALUES (32642, 1070710, 6008, 'I''ve played many games, but none have touched my heart the way Kind Words has. This game came into my life when I was at my lowest, struggling with feelings I couldn''t explain, and desperately seeking a safe space. This game became that space for me—a place where I could pour my thoughts into letters, knowing that on the other side, someone, somewhere, was willing to listen without any judgement.\n\nThis game offers a lifeline of connection in a world that can feel isolating. It’s more than just w', 'I''ve spent a good amount of time on this "game" (If you can even call it that) On paper i think it''s a great concept and I''ve gotten through some rough shit during the pandemic because of the comfort this game can give. However the state of the community in 2024 is.. less to be desired. I would not recommend this game to someone with severe mental health issues as of now. Replies to letters are often dismissive/insensitive at best, and harmful at worst. I''ve gotten replies that were straight up ', 'Overwhelmingly Positive', 98.20, 31.20, 13.27);
INSERT INTO reviews VALUES (32645, 1070790, 244, 'Freshly Frosted is a very good puzzle game with a lots of levels. It''s a chill  and funny game and the puzzles are not too difficult. I highly recommend it!!! 💗🍩💗', 'This is a time I have to flip my thumb. It hurts me to do so, but let me explain why. \n\nI left my previous review when I did recommend it below, but I have discovered a serious design flaw in the game that is just unacceptable. Granted i still love the game, but this flaw makes it something i won''t recommend playing for puzzle lovers:\n\nYou can be punished for being too efficient.\n\nThere will be a point where you will have donuts looping back around and conveyor belts connecting. However too many', 'Overwhelmingly Positive', 98.36, 32.98, 14.70);
INSERT INTO reviews VALUES (32647, 1070840, 106, 'This game is super freaking awesome, Would 100% Recommend it''s fun to play solo but i hear it''s even funner to play with a group hints "Together". But with that said even as solo the game has a lot to offer a really deep User Interface which is awesome, A lot of unique quests which are completely solo-able. Definitely worth trying if you need help or want to join me on my Journey i''ve also posted multiple videos onto my YouTube channel in regards to the game. Here''s a good one to start you off! ', 'has became a turn based combat.... in VR.... WHY?\r\nwe play on VR for realistic movement combat. come back at the previously method', 'Mixed', 60.38, 2.38, 4.17);
INSERT INTO reviews VALUES (32649, 1070860, 362, 'Absolutely love this game. It was so much fun to play. Capture unique creatures. Use magic to fight, explore etc. Definitely worth your time!', 'Npcs will walk right into you , making you unable to move until they move since theyre impassable.\n\nI just had my first death after i got attacked while in a dialogue. You lose a lot from death and to have my first death happen to me completely out of my own control is pretty sad and leaves a shitty taste especially since this is basically first impressions. Feel like i just wasted an hour and half.', 'Mostly Positive', 72.38, 117.97, 1.22);
INSERT INTO reviews VALUES (32651, 1070940, 145, 'A well made if short asteroids clone with high quality pixel H scenes on defeat. What''s not to like? I wish there were a lot more games of this type.', 'It''s like trying to play asteroid while someone is constantly trying to yank the arcade stick from you.', 'Mixed', 65.52, 1.82, 0.10);
INSERT INTO reviews VALUES (32659, 1071100, 297, 'This is a program that everyone should have on their computer, especially if you don''t use a sound card. It really enhances the sound quality and adds more depth, not just for gaming, but also for watching movies and listening to music. I think it works exceptionally well.', 'TRASH\r\n', 'Very Positive', 84.18, 1017.72, 5.13);
INSERT INTO reviews VALUES (32661, 1071130, 655, 'Otro magnífico título digno de su predecesor con una magistral muestra artística de humor negro y blasfemia.', 'its pretty boring in all honesty, i bought this game a couple years ago and really didn''t like it then, but i thought now that time has passed maybe i was too harsh on this game. i find that the gameplay lacks a little bit, its a point and click (i think?) but instructions are not too clear and there aren''t enough interesting things to discover to keep the player engaged that some other point and clicks do. the art is beautiful and that is what originally got me to play the game, as i understand', 'Overwhelmingly Positive', 96.79, 4.05, 25.43);
INSERT INTO reviews VALUES (32662, 1071140, 243, 'This game is so good!. \r\nThe first four hours I had no idea what was going on...\r\nlater to find out this is exactly the kind of games I love to play!!!\r\n\r\nGood strategy and a lot of fun!\r\n:)\r\n', 'Was fun, but recent changes increased difficulty by just tanking performance. The new player experience is worse than it''s ever been. They added a lot to the game with little actual clarity as to what you are doing and why things are happening. The maps are easy, until they are not, by just spawning thousands of enemies every few seconds. There is no real curve for you to understand how the game is flowing, I can''t tell if it''s bugged or they decided to do away with losing a campaign still impro', 'Mostly Positive', 71.60, 17.83, 11.72);
INSERT INTO reviews VALUES (32670, 1071290, 301, 'wacky!', 'To be quite honest, this game is only fun in concept. The game-play itself is dreadfully boring. You only really walk places and can only fast travel to specific locations. The graphics are pretty mid, the gunplay isn''t very satisfying. The lore and world building is kind of interesting, but that really isn''t enough. There is hardly any variety in enemy types. Small Scorpion, slightly bigger scorpion, and giant scorpion. Bandit, wizard bandit, and then small elemental and giant elemental. that''s', 'Mostly Positive', 72.09, 0.57, 42.22);
INSERT INTO reviews VALUES (32693, 1071870, 1406, ' Accidentally  boop your partner off the edge and apologize by holding hands!!\nSuper simple but cute~', 'If you want to play co-op. one person plays with a mouse and the other person plays with a controller. And you can''t play with two xbox 360 controllers because one person was controling two characters of the game.', 'Very Positive', 90.75, 2.78, 0.32);
INSERT INTO reviews VALUES (32703, 1072040, 1673, 'Just a fun, stress free strategy game, a lot like checkers...  Does not take up a lot of time and not all consuming.   I use it as a stress reliever.', 'The game is alright. Compared to the original game, it has it''s pros and cons. But is the game worth a hundred dollars? Absolutely not. And buying the base game does not give you enough. They purposely chunked out different campaigns to charge more. It is absolutely overpriced.', 'Very Positive', 83.62, 4505.35, 596.47);
INSERT INTO reviews VALUES (32707, 1072100, 105, 'easily worth the 4 dollars on sale if you are a wrestling fan', 'This game is total trash, super repetative and some of the worst tutorials as they dont work,', 'Mostly Positive', 76.19, 1.63, 0.80);
INSERT INTO reviews VALUES (32709, 1072120, 240, 'Supports 1 handed controls.', 'A series of degenerate, low-effort sliding puzzles games. The developer has dozens of these on Steam that are essentially all the exact same.', 'Very Positive', 86.25, 1.40, 1.60);
INSERT INTO reviews VALUES (32711, 1072150, 1325, 'This is top-tier boomer shooter action with some light puzzling and sprawling level exploration. The backtracking did get a bit annoying at times when I couldn''t find what to do, but it takes nothing away from this awesome game. Crystal-punk is a fantasy subgenre I''d never seen before and it''s a real fun time, I liked the inversion of orcs as the good guys and elves being terrible villains.\r\n\r\nThe hot orc pixel babes are definitely a bonus.', 'like passing futa kidney stones', 'Overwhelmingly Positive', 95.09, 11.92, 8.40);
INSERT INTO reviews VALUES (32714, 1072190, 353, 'I only recommend this game if you are interested in the campaign and only while it is on sale!\r\n\r\nI don''t really get this game at all. The production quality is top notch but sadly it seems to be abandoned now. There are quite a few bugs left that will probably never be fixed. Multiplayer didn''t seem active but I didn''t really try. I bought it entirely for the campaign and it was well worth the 4 bucks. The campaign is quite good but way too short. I mean, it''s 15 missions for all three factions', '!!! DO NOT BUY !!!\n\nThe game no longer works: The game speed is overwritten by something like factor 30 regardless of mode or settings and the campaign cannot even open!', 'Mixed', 65.72, 8.42, 0.38);
INSERT INTO reviews VALUES (32726, 1072420, 1634, 'We''ll probably never get a sequel or proper spiritual successor, so please know that the closest game to Dragon Quest Builders 2 is Necesse if that''s something you''re looking for.\n\n9.5/10', 'So, I finally forced myself to finish this game and for a lack of a better description, this game''s biggest flaw is that it takes the control away from you, the player, too many times. I really wanted to like it and the game shines through when they let you build and give you objectives, heck most of the dialogue is good. BUT... there''s too much unskippable cutscene like stuff to truly make it an enjoyable experience. Some examples:\n\n1) When the mysterious voice is speaking, you can''t skip the d', 'Very Positive', 89.66, 143.72, 78.93);
INSERT INTO reviews VALUES (32728, 1072480, 339, 'great game, just wish he developers didnt abandon and forget about it.we need more lakes and lures\r\n', 'game is dead, very few people playing, competitions cancelled regularly due to lack of players. Game is not maintained, no updates', 'Mixed', 62.24, 2039.07, 1496.63);
INSERT INTO reviews VALUES (32729, 1072500, 356, 'Best Tennis game out here so far. I''ve tried Tennis World Tour on console but this one really scratches the itch for me.', 'This game require you to be online ALL THE TIME to play, that include career mode.', 'Mixed', 67.98, 43.93, 21.30);
INSERT INTO reviews VALUES (32736, 1072640, 245, 'Splendid', 'There''s a lot of good ideas here, but this game suffers from far too much grind in a roguelike.  It''s hard to even get to level 2, and when you do, there''s not enough damage to really keep up with the enemies.  Even after dying 20-30 times, the progression system does not level fast enough, and most of the runs feel completely wasted.\n\nYou will never get the amount of notes that these attract videos show, not without putting many many hours grinding the progression system.  And since most of the', 'Very Positive', 87.76, 50.72, 3.13);
INSERT INTO reviews VALUES (32763, 1073320, 284, 'I can''t believe how overlooked this game is! The art is absolutely fantastic and the game loop is clean and addictive. Not the deepest or most elegant designs, but very fun.', 'it was fun for like 2 hours. It feels like it lacks the depth of a deckbuilding game thus gets repetitive and boring kinda fast', 'Very Positive', 94.01, 18.38, 2.55);
INSERT INTO reviews VALUES (32783, 1073820, 251, 'Overall a unique unexpected story. Could have been a little lust cluttered with repetitive notes but I enjoyed the experience', 'This game has some cool concepts, and i''m glad someone tried to explore it. But the overall game just isnt good.', 'Very Positive', 92.03, 2.02, 1.82);
INSERT INTO reviews VALUES (32788, 1073900, 105, 'Brukel is a passion project that offers a window into the life of someone from a diminishing generation. The game is full of real anecdotes from the subject herself about the experiences she went through. This is all, of course, in her native tongue, but thankfully there are a variety of caption options available for those who wouldn''t understand it based on the audio alone. You could view this game is somewhat of an interactive interview with accompanying visuals. It isn''t meant to be a true "s', 'While initially a very interesting concept, the use of horror and supernatural elements to tell a story about people feels very out of place in a game which such a grounded base for a story to tell.', 'Very Positive', 94.29, 1.52, 1.22);
INSERT INTO reviews VALUES (32789, 1073910, 680, 'Before We Leave is overall an okay city builder, but suffers from a couple of significant issues. \n1: The game appears to be horribly unoptimized and requires a significantly better computer than it should need to run. It straight up did not run on my old computer and causes excessive heating on my current one, which is a gaming laptop. \n2: The game is very repetitive, forcing you to build up the exact same infrastructure on every planet you visit with no variation besides the different biomes. ', 'Had a lot of fun on this game till I did not, it starts out good and nothing wrong with it I just lost total interest in the game and that''s not common for me.\n\nthe difficulty does not scale but the amount of work you have to put in for the same result, you don''t really get anything worth more for more work and its not really fun work.', 'Mostly Positive', 75.59, 17.48, 14.02);
INSERT INTO reviews VALUES (32793, 1074030, 135, '▪ 다양한 동물들이 모여 사는 마을과 그곳에서 벌어지는 이야기\n\n    개인적으로 동물들과 나누는 소소한 대화들이 게임을 몰입하는 데 즐거움을 주었습니다. 개성 넘치고 공격적이기도 한 동물 친구들과 여정을 함께 하며 약속 장소를 찾아 친구와 만나기 위해 모험을 떠납니다. 멜론을 컨셉으로 한 전체적인 연두색 풍의 그래픽이 아주 인상적이며, 마을 곳곳에 준비되어 있는 다양한 음악과 준수한 스토리가 게임을 끝까지 플레이 하며 만족스러웠습니다.\n\n▪ The town where various animals lives and story that various happens\n\n    Personally, small conversations I had with the animals made game enjoyable to immerse myself in. I went on a journey with my unique and aggressive animal friends and went on an ', 'For a game that emphasizes its story and exploration, I feel disappointed. The story is rather short with insufficient build-up, where I don''t feel emotional connection to the characters. The game consists of 3 acts, but only Act III piqued my interest. While I missed some sidequests (since I only unlocked 12/20 achievement), I doubt completing those would make me feel invested towards the story. The exploration is nothing special, just like your usual RPGMaker/GameBoy-esque games.\n\nHowever, the', 'Overwhelmingly Positive', 95.56, 6.48, 3.58);
INSERT INTO reviews VALUES (32796, 1074070, 227, 'As a massive fan of the carvaneer series and easily a few hundred hours in the 2nd one alone i might be a bit biased in loving this which has clearly taken inspiration from it.\n\nI will say for super old folk like me who have played caravaneer 2 this one differs in that it is a simplified version, while you still have industries you can invest into and build up to setup trade routes in the economy, the combat is a lot more basic and essentially risk free, there is not yet any sort of livestock el', 'Dust to the End has nice hand-drawn graphics in a post-apocalyptic setting which is what drew me to the game. It''s just too slooow and boooring for me. I really wanted to like it. I even tried it again, but it''s a dud. Not recommended', 'Mostly Positive', 78.85, 37.88, 8.95);
INSERT INTO reviews VALUES (32797, 1074080, 308, 'Came for the fanservice but left with a surprisingly enjoyable pinball game.', 'I went into Peach Ball looking for a decent sexy pinball game and what I got was an awkward visual novel with TERRIBLE pinball. There are only two very simplistic tables here that are barely different. While it plays okay you can see absolutely everything there is to see gameplay wise in a half hour. There''s no variety to the story missions and every game plays out exactly the same. It''s also so absurdly easy that even someone who has never played pinball before will have no issue S-ranking ever', 'Very Positive', 87.99, 19.57, 2.00);
INSERT INTO reviews VALUES (32820, 1074620, 207, 'This is great, very unique approach to monster collecting and summoning, with real time combat for once. Taking care of summoning the right creatures and the sinergies between them is plenty fun. But it''s not without flaws, it can be repetitive and horribly grindy, the constant ingredient and material farming is annoying at best, and the creature skills are used automatically when you summon them, so you either reserve some or stop caring and just summon them as normal, which I did. I wish the d', 'Support for this game seems dead. Last update was December 2023....\n\nWas hoping for more tweaks on the game. Concept wise, I was drawn in and bought it. Once I got to playing it though, it got repetitive fast. Not much going on. Some other comments mention it was initially a rougelite which makes a lot of sense on why it feels repetitive. Just don''t feel like they did enough to go full RPG because the game would likely be better as a roguelite. Having something fast paced and increasingly challe', 'Very Positive', 82.61, 37.73, 0.95);
INSERT INTO reviews VALUES (32821, 1074630, 151, 'Thank you for whoever recommended me this game, it saved me from killi myself. \njavascript:void(0)', 'A fairly bad asset flip that shouldn''t be purchased.', 'Mostly Positive', 76.82, 0.97, 0.77);
INSERT INTO reviews VALUES (32839, 1075080, 134, 'This game is and was very fun to play. It is VR compatible though I played it without a headset. The games design is both realistic and cartoon like. The blend gives it a unique feel and touch. The controls are easy to use and the mechanics for the most part are fun and not complicated. The game is relatively short only really lasting about 10 hours so in that aspect if you''re looking for a game to play over the course of multiple days this game isn''t very suited for that. It''s more of a fun sho', 'I reeeaally want to like this game. The Bird is cute. Thats what i''m here for, cute vr birb. The thing is the vr is broken. your pouch dosn''t stay seated on your body, it just floats around. The locomotion is weird and sickening if you use twinsticks. The writing is absolutely dreadful, and the world feels empty. It feels like its early access but it''s out and ''done''. If it gets some major updates i''ll nab it again.', 'Mostly Positive', 76.87, 8.32, 1.18);
INSERT INTO reviews VALUES (32842, 1075190, 991, 'Plays just like board game. Same game, without the counting/token etc issues.', 'Sadly, the game is unplayable online, we tried many times and 99% of started games just hangs in a random moment. Nobody cannot do anything. Waste of time.', 'Mixed', 69.83, 30.82, 22.10);
INSERT INTO reviews VALUES (32847, 1075400, 169, 'Some rough edges, and you''ll probably have to remap some controls to be able to move, but overall a really fun 3-hour Doctor Who VR experience. The Weeping Angels chapter is genuinely terrifying and worth the asking price all on its own!', 'Only took 20 minutes to see this game is a load of tripe! It''s sad to see just how far the Dr. Who franchise has fallen. This "game" is the prime example of a studio and developer resting on ones laurels. I feel embarrassed for Jodi Whittaker who is horrible playing the doctor), the developer, and the BBC.', 'Mixed', 58.58, 2.75, 0.33);
INSERT INTO reviews VALUES (32853, 1075740, 1208, 'Great game.  My favorite deckbuilder.  Good atmosphere, its not just a digital card game, but it all works together to create an experience.', 'I was enjoying this game and had a pretty decent strat. Until the game decided "Fuck you, I''m gonna banish the first of every card you play throughout every round because of some ability one of your enemies have, there by locking you in to drawing nothing but injury cards or cards you can''t use due to stamina until you die or quit."\nDon''t bother playing this game unless you like getting angry and seeing every strat you employ go down the drain because the game never cuts you a break. It''s unfair', 'Mostly Positive', 79.30, 37.62, 11.05);
INSERT INTO reviews VALUES (32863, 1075980, 127, 'NinNinDays is a simple and short feel good visual novel about your everyday insert mc running into a country bumpkin ninja girl, and starting a life together. The story itself is fairly basic and simple, but that was obviously put on the back burner by focusing the attention on Sumire''s character. She definitely feels like the average clueless waifu to be trope, but that is forgiven because Sumire is cute as a button. The real defining factor for NinNinDays is the fantastic art style which is ju', '5/10. Boring, even.', 'Very Positive', 93.70, 2.30, 5.50);
INSERT INTO reviews VALUES (32874, 1076160, 829, 'I am concerned that the NSA is being pinged every time I fire this game up.  I can feel the NSA agents connecting anonymously to my Steam account and recording my game.  I''m pretty sure that Tom Clancy''s estate has direct access also to my PC whenever I start up this game.\n\nAfter I played this game against Syria and took down their forces and saved Assad''s regime, I soon started seeing blacked out  SUVs following me.  Not only that, but I swear drones are constantly following my every move in Ne', 'Missile burn profile is unrealistic, with enforced top speed limit. PAC-3 mse in the original database suffer from no CEC and abysmal engagement ceiling, and SM-3s lack the CEC capability as well. While guiding via aegis-borne radars in the game is impractical due to the heavily underestimated ranges against ballistic targets, the interceptors can be guided via datalink, but datalink channels count is limited to SPY-1D''s 16 instead of making it with cec for which there is no limit, like what is ', 'Very Positive', 84.92, 8.28, 366.12);
INSERT INTO reviews VALUES (32875, 1076200, 1678, 'Its good but its WAY TOO SLOW.\nInstead of just choosing what to do, you have to walk the map and go back and forth to progress, even to check the shop.\nThe combat animations are locked to 1X speed, card draw animation is slow, starting the run, everything is slow. You EASILY waste an close HOUR per run (my average is 1.5 hours) just walking and waiting for stuff to resolve.\nI dont want to give a negative review because its a good game but after 10 hours I dont wanna play anymore because of this.', 'Roguebook is my 1# favourite game - still, I recommend not to buy it anymore. Developers do not seem to do anything anymore - not even the most simple bug fixing. Often you get stuck when trying to leave the cave level and your run get deleted due to corrupted data. Recently you cannot even play the daily challange as the data doesn''t even load (often wait for up to thirty minutes in the main menue for the count down to load ... but it simply won''t (restating the game does not help).', 'Very Positive', 85.34, 13.08, 803.03);
INSERT INTO reviews VALUES (32886, 1076550, 242, 'For some reason they didn''t put this version of SS5 on the ''complete'' collection so if you are a SS aficionado completion can only be achieved with this one on tow... or just emulate it... you do you :)', 'Level 1 difficulty & AI is reading all inputs , instantly reacting to them with no delay & spamming moves...', 'Very Positive', 91.74, 0.28, 0.63);
INSERT INTO reviews VALUES (32893, 1076750, 237, 'Automation game with active fighting and strategy for defending in a simplistic TD style.\n+ Flying away makes a soft reset which solves the stiffness of long-running automation bases\n+ Varying gameplay, you can move around fighting by yourself or build solid defenses or focus on resources to get a heads-up in technology\n+ Since v1.00 finally balanced 🙂\n- Slightly stretched end-game, but still fun ''cause of all the various resources and choices you can make\n- Small performance issues, slowing dow', 'Extremely buggy, I wish I could say more about the gameplay but it is actually unplayable with all of it''s bugs right now.', 'Mostly Positive', 77.64, 212.82, 0.80);
INSERT INTO reviews VALUES (32897, 1076880, 336, 'I saw Captain Sauce play it so I bought the game.', 'its fucking impossible to buckle your seatbelt, therefore permanently locking half the endings. other than that a funny game.', 'Overwhelmingly Positive', 96.13, 0.18, 0.85);
INSERT INTO reviews VALUES (32898, 1076920, 161, '⣿⣿⡻⠿⣳⠸⢿⡇⢇⣿⡧⢹⠿⣿⣿⣿⣿⣾⣿⡇⣿⣿⣿⣿⡿⡐⣯⠁ ⠄⠄\n⠟⣛⣽⡳⠼⠄⠈⣷⡾⣥⣱⠃⠣⣿⣿⣿⣯⣭⠽⡇⣿⣿⣿⣿⣟⢢⠏⠄ ⠄\n⢠⡿⠶⣮⣝⣿⠄⠄⠈⡥⢭⣥⠅⢌⣽⣿⣻⢶⣭⡿⠿⠜⢿⣿⣿⡿⠁⠄⠄\n⠄⣼⣧⠤⢌⣭⡇⠄⠄⠄⠭⠭⠭⠯⠴⣚⣉⣛⡢⠭⠵⢶⣾⣦⡍⠁⠄⠄⠄⠄\n⠄⣿⣷⣯⣭⡷⠄⠄⢀⣀⠩⠍⢉⣛⣛⠫⢏⣈⣭⣥⣶⣶⣦⣭⣛⠄⠄⠄⠄⠄\n⢀⣿⣿⣿⡿⠃⢀⣴⣿⣿⣿⣎⢩⠌⣡⣶⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣆⠄⠄⠄\n⢸⡿⢟⣽⠎⣰⣿⣿⣿⣿⣿⣿⢀⣾⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣦⠄⠄\n⣰⠯⣾⢅⣼⣿⣿⣿⣿⣿⣿⡇⣾⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⡄⠄\n⢰⣄⡉⣼⣿⣿⣿⣿⣿⣿⣿⢸⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣧⠄\n⢯⣌⢹⣿⣿⣿⣿⣿⣿⣿⣿⢸⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⠄\n⢸⣇⣽⣿⣿⣿⣿⣿⣿⣿⣿⠸⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⠄\n⢸⣟⣧⡻⣿⣿⣿⣿⣿⣿⣿⣧⡻⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⠄\n⠈⢹⡧⣿⣸⠿⢿⣿⣿⣿⣿⡿⠗⣈⠻⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⡇⠄\n⠄⠘⢷⡳⣾⣷⣶⣶⣶⣶⣶⣾⣿⣿⢀⣶⣶⣶⣾⣿⣿⣿⣿⣿⣿⣿⣿⣿⠇⠄\n⠄⠄⠈⣵⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⢸⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⠄⠄\n⠄⠄⠄⠸⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⠘⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿⠇⠄⠄', 'I got this game because Alex the rambler made videos on this game, I was intrigued. I saw that the game had achievements, that I think could be easy to complete.\nHowever... there''s a problem, you cannot actually achieve them. On top of that the game is incredibly boring and way too easy. There''s no way to increase the difficulty either unless you play naturally difficult countries. But not even that is hard if you consistently improve relations with countries you''re not ready to go to war with a', 'Mixed', 54.66, 3.68, 22.22);
INSERT INTO reviews VALUES (32914, 1077290, 475, 'the game is so messy with even 1 friend its really good and its worth the money if u have friends because of how goofy it is and its a very sigma game', 'No one plays it its cool but no one plays it. Crap', 'Very Positive', 93.26, 5.48, 7.77);
INSERT INTO reviews VALUES (32919, 1077410, 106, 'EZ to get all achievements 100%\nJust press  on each level', 'Hentai Sweet Girls is a very poorly made puzzle game with adult content.\n\nThe game has forgettable music and if it''s anything like ''Mi Mi Mi'' from the same game company, except to have tiles of the same colors not matching for a certain reason. The game has 40 levels as well, but just like that other game I mentioned before, it''s not 40 different pieces of art, it''s only 10 different pieces of art with varying state of undress. To put the final nail in the coffin, the art is anatomically wrong, ', 'Mostly Positive', 77.36, 2.20, 2.35);
INSERT INTO reviews VALUES (32921, 1077430, 148, 'pretty nice little indie game', 'Very good game pls add more maps', 'Very Positive', 81.76, 3.25, 2.67);
INSERT INTO reviews VALUES (32922, 1077450, 166, 'Fun, charming little nuclear throne esqe rougelike. A little small in scope compared to some of it''s competitors, but lot''s of charm.', 'fun so far but my biggest problem is the unability to change any keybinds AT ALL\nI find the initial scheme quite uncomfortable and can''t see myself playing for a really long while with the keybinds like how they are', 'Very Positive', 93.98, 2.62, 0.72);
INSERT INTO reviews VALUES (32926, 1077520, 262, 'Very short game but well done. Surely the graphics and the setting are what fascinate the most. At the beginning it is a bit boring but then it takes a good pace. Price adequate to the duration. My rating 7/10', 'Shit Game.Inconvevenient mouse Control, unoptimized  Crap, expensive, reset saves after restart\n\nPLEASE do not BUY RUSSIANS GAMES. They Should be banned At the Un international', 'Very Positive', 83.59, 4.40, 0.92);
INSERT INTO reviews VALUES (32927, 1077530, 125, 'I enjoy this game alot, it''s good for world building. I use it to help visualise my DnD maps.\n\nI  do however wish there was more content to the game, new items and building materiel would be nice.', 'This game showed and gave a ton of promises when I first came across it, but it''s been years since the last update, and there hasn''t been any word of new content.\r\nI''ve been to the discord page, and there doesn''t seem to be a lot of progress being made on the new content, and even if there is new stuff in the works, letting steam users know how busy you are is how you keep your fanbase loyal.\r\n\r\nThe lesson to be learned here is that Communication is Key!\r\nTell your players what''s going on across', 'Mostly Positive', 76.00, 48.65, 30.73);
INSERT INTO reviews VALUES (32948, 1078200, 322, 'I really hope there''s a spirits abyss 2. game is absolutely a must play if you like roguelikes. Caiys always puttin out good stuff.', 'Stupidly hard for no f*cking reason with horrible, horrible controls. Trying to hit something in this game is a chore. Worst controls and handling I have seen in a rogue like ever. Not sure what people find with this.\n\nEdit because of the funny R-tards:\n\nYour boos mean nothing, I have seen what makes you cheer.', 'Overwhelmingly Positive', 96.27, 6.87, 0.68);
INSERT INTO reviews VALUES (32952, 1078280, 116, 'no seggs with Vise 0/10', 'The greatest mistake I made when buying this game is that I didn''t consider the controls.\r\nThis game requires that you use a mouse if you are on computer.\r\nNow if you consider that this is a game for wanking off, and then consider that you have one hand on the mouse and one hand on the keyboard, which hand is doing the wanky wanky? \r\nThis game is a logistics problem of the wankthed dimension.\r\nNOT RECOMMENDED.', 'Very Positive', 93.10, 22.58, 1.50);
INSERT INTO reviews VALUES (32956, 1078350, 182, 'I''d say this one is as good as Magical Girl Celesphonia and that''s high praise.\nIt strikes that perfect balance between actual gameplay and H-content where you can move between both seamlessly. There''s this thing with Adult RPG-maker style games where either the adult scenes are a complete pain to unlock or they''re overly aggressive with them. This game and Magical Girl are those rare exceptions where you can actually choose where and when you want to unlock them which makes the game so much bet', 'At first I liked this game, but I couldn''t finish it. And I''m not stupid so I''m usually able to finish a game, but this one just seemed to end on it''s own, before I could finish it myself, and I just roamed the map trying to figure out what the next mission or goal was and I never discovered it and the games kinda sucked and became a disappointment.', 'Very Positive', 90.66, 25.53, 11.23);
INSERT INTO reviews VALUES (32961, 1078420, 809, 'I love it when I possess the body of my ex-friend who just killed me, and get godly powers from a spirit to become the lead singer of Death Grips.', 'honestly as much as this tries to be Weird it just ends up being boring. every Weird thing critters for sale throws at you feels tepid and overly referential rather than original - there''s a lot of "look, it''s thing you know!" for the overly online generation that just does not compel in any way, especially for a game that overall is close to plotless outside of its Weirdness. that plotlessness (and just generally uncompelling writing) really works against the game because it is at its core a fa', 'Overwhelmingly Positive', 95.80, 4.57, 0.63);
INSERT INTO reviews VALUES (32966, 1078510, 121, 'cute little game, doesn''t receive updates but if it is on sale its a good deal. You can play for a decent number of hours, some of the achievements are pretty annoying to get but overall a fun game to explore all the paths you can take.', 'A very relaxing game but it has some major issues. You can repeat certain events or scenarios in each area over and over again for experience and rewards when obviously you''ve already completed it and it SHOULD NOT be repeatable. There are no heavy consequences for being evil or good, but honestly being good just has more benefits than being evil. There''s really no reason to play the game again after you''ve beaten it since everything is pretty much the same. The game isn''t really worth $10. I wo', 'Very Positive', 89.26, 10.32, 2.97);
INSERT INTO reviews VALUES (32975, 1078760, 652, 'great game to kill a few hours with and i feel like i have definitely learnt a thing or two about motorbikes certified motorbike mechanic right here, don''t mind me i am just gonna go update my cv', 'As a Motorcycle mechanic!!!. This does not have a lot of stuff from my work in it.. No carb adjusting. No valve timing. No wiring diagram and wire soldering. Just not enough diagnose play.  Not enough Motorcycles. Too much pay to get stuff. Could have added torque wrench system and snapped bolts. And stuff to extract bolts. game is  1/10 really not recommended.', 'Mostly Positive', 72.85, 8.22, 8.90);
INSERT INTO reviews VALUES (32981, 1078920, 727, 'The game in many ways is more enjoyable than Trailmakers.\nFor whatever reason, the other game took off and this one is seemingly abandoned.\nThere are still a lot of bugs in the game, and crashes\n\nHopefully they come back to this project eventually', 'need a network connection just to play alone got halfway through an unsaved build just to be kicked out by laggy wifi', 'Very Positive', 86.11, 2.93, 6.28);
INSERT INTO reviews VALUES (32985, 1079000, 159, 'A game that can make you laugh with such few words.', 'boring.', 'Very Positive', 91.19, 2.23, 1.32);
INSERT INTO reviews VALUES (32988, 1079160, 229, 'This game does the impossible, it shows Youmu not being a complete bottom', 'This game fucking sucks.  He took all the worst mechanics from the previous entries and packed them into the same game.  I can no-continue the majority of the games on hard and this game wrecked me on normal, and almost every time i didn''t even know what killed me.  There is so much visual vomit on the screen you''ll be more focused on not having a seizure than dodging.   The cringe UFOs are back (who the fuck asked?) except now when you activate them you get a giant beam of light that makes it a', 'Overwhelmingly Positive', 97.38, 2.47, 0.23);
INSERT INTO reviews VALUES (32990, 1079210, 520, 'It could be a bit janky at times, but ultimately I had a lot of fun with it. Boss fights slightly reminded me of Sekiro with the parry system being the best way to fight them as it increases your damage the more you successfully do it, letting you melt them once you reach the maximum. Soundtrack is also pretty good, especially the boss themes. Level design was unique and a lot of the visuals reminded me of Sonic Adventure 2, namely the space stages reminding me of the Ark stages in that game. De', 'Spark had a rough transition into 3d.', 'Very Positive', 89.81, 7.35, 21.55);
INSERT INTO reviews VALUES (32991, 1079230, 142, 'the bloom be pretty af', 'Abandonware. Stay clear. Dev is pursuing his new, more successful game of a completely different genre. A shame.', 'Very Positive', 81.69, 31.07, 2.07);
INSERT INTO reviews VALUES (32992, 1079260, 2532, ' The best fun you can have with your clothes on \n\n The only downside I could find is that you can''t save your work. You could sink hours in creating a fireworks show, trying to time everything perfectly but you have to do it in one session.  (Or you can just blow up a fireworks store or a gas station) Even with the quick and dirty way it''s a lot of fun. The world may look cartoony but the fireworks themselves look neat. Sounds great too. Added mod support is brilliant and adds a lot of extra val', 'you can burn down a church not cool man', 'Overwhelmingly Positive', 97.59, 3.58, 1.83);
INSERT INTO reviews VALUES (32995, 1079310, 103, 'Best clic H then f12 game 1000/10\ngood art :)', 'Generic, low effort sliding puzzle game featuring typos and UI that runs off the screen at 4K. Press ''H'' to solve a puzzle instantly and get the achievements in a few minutes.', 'Very Positive', 82.52, 0.67, 5.10);
INSERT INTO reviews VALUES (33005, 1079510, 195, '62 hours in, Sumerians remains my city builder of choice. Here are a few reasons why. \n\nI get to focus on buildings, because, Sumerians is not a roadway engineer simulator. Residents path find their way to jobs automatically, allowing a type of urban design I wish games with a more contemporary setting allowed for. \n\nPlaning economic development and trade to expand state capacity. Unlike other city builders economic nodes are not simply abstracted into dollars, and government isn''t relegated int', 'In a world loaded with city builders I don''t really recommend this one so much. I really love certain aspects of the game and the time in history is extremely interesting to me. But for me to get immersed in a builder I need ambience and that feels missing most of the time. When a game like this feels like it''s missing anything at all and they they start releasing DLC, I usually throw in the towel. Even if it''s only $2 I feel like it should be free based on the game feeling like a work in progre', 'Very Positive', 86.15, 70.03, 35.67);
INSERT INTO reviews VALUES (33011, 1079620, 468, 'After painful experiences of Star Citizen''s new Master Mode, I''ve finally been saved.', 'Would recommend, BUT buyer beware I really don''t foresee this niche multiplayer game gaining a playerbase beyond the occasional organised little community game. As much as I don''t want to say it, the aim of fostering community growth and retention seems mostly ignored. A good game is being made that unfortunately seems like it won''t be played.\n\nWill update when checking back on progress. Please leave comment with news if you know it before me.', 'Very Positive', 80.77, 8.18, 15.15);
INSERT INTO reviews VALUES (33018, 1079800, 2801, 'Leg day simulator.', 'Recent changes/updates have made it far less accurate to the beat, so you''re punished for doing well and have to actively work against the beat which is the opposite of the game''s intent. Hopefully fixed in the future, but generally just bad to play outside of a few levels or without custom settings.', 'Very Positive', 93.93, 0.58, 18.75);
INSERT INTO reviews VALUES (33020, 1079830, 151, 'I haven''t finished this game yet but so far so good. I don''t really get why this game has mixed reviews? But I personally like it. The artstyle is bright and beautiful, the story is pretty decent, and the turn-base combat has a cool twist to it like you can parry, crit hit, and bend time to your advantage so it keep you engage most of the time unlike traditional turn-base games. So yeah, I''m really having fun with this game so far.', 'This game isn''t actually all that bad, but it just felt slow and often times annoying. Not being able to walk faster was definitively one of the main factors in that.', 'Mixed', 68.21, 10.15, 17.78);
INSERT INTO reviews VALUES (33027, 1080010, 105, 'My wife and I are completely obsessed with co-op cooking challenge games (Overcooked-esque), and this one is our absolute favorite! Great variety of levels and mechanics, and VERY well balanced for 2 players - getting 3 gems on every stage is possible but challenging.', 'My wife and I love playing these types of games together. It began with Overcooked, and Witchtastic is our newest endeavor in the genre. The concept of the game isn''t too difficult. Gather ingredients, mix them into potions and dispense them accordingly. All of this works pretty well. \n\nThe problem with the game, however, is that the further you go, the more issues begin to arise. I realize that games like this should have a growing challenge. As I''ve said, my wife and I played the Overcooked ga', 'Very Positive', 92.38, 101.82, 17.95);
INSERT INTO reviews VALUES (33028, 1080020, 842, 'not accurate at all everyone on the job sites are too polite i expect to be berrated and have horrible words thrown my direction as an electrician', 'Bought this game while learning about electrical work. The game is alright, but the tutorials are not crap. Spend half an hour trying to figure out how to hook up wires when the game offers little explanation about how the game mechanics work. Find myself having to go on youtube to figure out how to pass the tutorial missions: doesn''t that defeat the whole purpose of tutorial missions?', 'Mostly Positive', 73.52, 11.08, 8.28);
INSERT INTO reviews VALUES (33050, 1080750, 632, 'I don''t think the summary quite does this game the justice it deserves - there''s so much more depth to the characters than simply "small-town drama." You''ll explore loss, personal philosophies/anxieties, relationship conflict - romantic, platonic, and familial, and the general growth and rebuilding of a community that''s been outcasted and torn about by so much trauma.\n\nMind you ALL of this is tucked into a neat little package of a point & click type of walking simulator. Time passes in a very cl', 'A game for those who love to read.\n\nCons: In my opinion, the gameplay is sometimes irritating. The attempt to include farm elements in a story-driven game didn''t succeed. The graphic design is also not for everyone, resembling "paint by numbers"...\n\nPros: I liked the music and sound design. I appreciated that the game is slow-paced and quite meditative. \n\nIt''s worth playing once, but overall, after the enthusiastic reviews, I was rather disappointed.', 'Overwhelmingly Positive', 96.52, 8.83, 10.68);
INSERT INTO reviews VALUES (33083, 1081510, 438, 'Basically, a 30 minute movie with choices along the way.  Compelling and enjoyable.  Recommendation: Set audio to original Russian with English subtitles.', 'They call this an interactive movie, but in terms of length, it''s more like an interactive TV episode. One playthrough will take 25 to 40 minutes so pretty short. You will get distracting screen tearing, even with v-sync, unless you set your monitor at 25hz, which I couldn''t. It''s a Russian game dubbed in English. It''s not terrible but it does break the immersion a bit too. There are not that many choices to make, maybe a dozen. They said "every choice matters" at the start, but most of the time', 'Mostly Positive', 76.26, 2.52, 1.57);
INSERT INTO reviews VALUES (33090, 1081650, 107, 'best fps parkour runner, nothing comes close\n\ndevs take note of ledge mantle and air crouching!!!', 'For the price, not really doing it for me. That said!\n\n-Cool music\n-Cool designs\n-Feels okay\n\nAll-in-all: Feels under-baked, no controller support, and feels like a basic flash game\nShows promise for a fun, Mirror''s Edge style platforming experience and would be worth it for a few bucks; definitely not 8, as it stands.', 'Very Positive', 87.85, 22.88, 0.12);
INSERT INTO reviews VALUES (33112, 1082180, 397, 'i love edging', 'trash game\r\n', 'Very Positive', 82.62, 0.43, 29.78);
INSERT INTO reviews VALUES (33113, 1082190, 149, 'Old school in the best possible way, great story, not too hard and a whole lot of fun. Loved it through and through', 'This looks nice, having a classic feel without pressing the retro graphic button that is so overused. Dialogue doesn''t overdo the goofiness do keep some heart. \nBut, unfortunately, like with Harold Halibut, they forgot to put a game in. You pick up your 1-2 items per location, click on them when it''s obvious to use them. Then you get the next three dialogues to click through, rinse and repeat. That''s not a game. That''s a tortured way to read a simple short story.', 'Overwhelmingly Positive', 95.97, 12.35, 2.22);
INSERT INTO reviews VALUES (33118, 1082430, 11743, 'One of the greatest experiencies that I''ve had on entire life. I''m very thankful to be born in a time where I could play this.', 'I really tried loving this game, tried it both on here as well as on mobile. For me the interface where you have to blink sounds cool on paper but I found my focus was constantly on my eyes instead of the game. It didn''t feel natural for me and I couldn''t really relax while playing the game. Cool concept but for me personally it didn''t work.', 'Overwhelmingly Positive', 98.24, 1.90, 0.60);
INSERT INTO reviews VALUES (33120, 1082450, 157, 'game worked fine untill the unreal engine 5 forced version dropped now it looks like junk and runs at 10 fps after the first 3 error,s it worked and then crashed off. but still the only co op gold mining game out there as far as i know too..', 'DO NOT!!!!!!!!!!!!! DO NOT!!!!!!!!    Buy this game 2 years devs have not fixed 1 thing they have locked the forums  ....SCAMMERS .STEAM SHOULD REMOVE THIS GAME....EVERYONE THAT HAS WASTED MONEY ON THIS GAME SHOULD REPORT THESE GUYS GET THIS TOTAL GARBAGE REMOVED FROM SALE....... \n UPDATE ....\nSTILL THE SAME SHITTY MESS 11.01.25\n today they ban me from discord for questioning the scam game these guys made so goes to show what kind of people they are,,,, \n\nUPDATED REVIEW ......\nWOW  WHAT CAN I SA', 'Mixed', 40.13, 33.95, 13.65);
INSERT INTO reviews VALUES (33129, 1082680, 670, 'Over hated game, story was mid but the game play and weapons were fun. Playing as the show characters was so cool and exciting for me', 'I think the decision to make walkers take multiple head shots to take down is a decision so detrimental that it completely ruined the game.', 'Mixed', 43.88, 11.53, 1.00);
INSERT INTO reviews VALUES (33132, 1082710, 4115, 'If you like the Paper Mario series, then you''re gonna love this game! Bug Fables does everything what a Paper Mario game does but BETTER and more engaging. If you needed to scratch that Paper Mario itch. This is the game for you! \n\nSide note: Vi is the best character. Don''t @me', 'Too many bugs', 'Overwhelmingly Positive', 97.45, 18.38, 2.42);
INSERT INTO reviews VALUES (33142, 1082930, 149, 'the story is great. the game unique - highly, highly recommended! it may not be for everyone, but holy, I loved it!', 'The game concept is very good, first hours of game too. The second half is the problem. The endings are pure meme with developers showing total disrespect with players. What could be something amazing, full of meaning and character development turns out to be pure trolling. final thoughs: SAVE YOURSELF HOURS OF OF DISAPOINTMENT, GO SEE THE ENDINGS ON YT.', 'Very Positive', 80.54, 8.57, 7.65);
INSERT INTO reviews VALUES (33144, 1082970, 242, 'Splattercat brought me here, and I am incredibly excited to see where this one goes. There is something special about creating a party to adventure with, especially when the diversity of options when creating said party is as high as this one. The exploration to combat loop is very engaging, and with some more polish it will be a great game.', 'Good game but come on man old school mode with nearly no resources for you to even progress through the starting dungeon without failing every attempt at looting. Start just forces you into these brutal fights where you gonna miss everything and have no healing outside of combat cause there is NO FOOD at all other then two spots I found. Fix start for all the other difficulties or just simply add more stuff to your map....\nThe miss chance isnt as bad as Battle Brothers and I can handle that but ', 'Very Positive', 83.88, 6.08, 7.30);
INSERT INTO reviews VALUES (33148, 1083190, 161, 'Disc Creatures is very charming and fun game.\r\nThe world of Disc Creatures feels very creative in its approach and the lore makes a captivating setting with its monsters and cute retro art style.\r\n\r\nThe style of jrpg combat feels familiar yet distinct in its own personality with interesting creature specific skills that help define each of the 200 creatures. There are also unique status conditions that gives battles strategy and promote using non-damaging moves. \r\n\r\nThe story is serviceable and ', 'Its not all bad, the Mon''s are okay, and there''s a lot of quality of life stuff like the cafe that lets you pay to level up your mon''s - with each tier unlocking as you get further into the game. So its not like you have to completely start from scratch if you want to mix up your team, but the game is still very grind-heavy. Sometimes, it feels like anything less than 5 memory sticks and you won''t get a capture, so you have to build up a cash reserve to keep buying items, but most of your money ', 'Very Positive', 83.85, 39.87, 9.65);
INSERT INTO reviews VALUES (33149, 1083210, 102, 'Pretty mediocre. The gameplay is sort of fun, it''s original at least and was engaging enough for me to finish the game. It has a story but it''s not that amazing. The scenes are lackluster too, imo. The art is alright but not the greatest. The music is repetitive. The store point emotes are kind of ugly unlike those from other games in the bundle. Won''t recommend getting this standalone, but as part of bundle it''s okay.', 'Achievement locked behind DLC.', 'Mostly Positive', 71.57, 4.92, 1.02);
INSERT INTO reviews VALUES (33156, 1083310, 104, 'The game is completely underrated. It''s a fantastic metroid-like game! And all this with splendid graphics from an indie team.', 'the game seemed like it would be great but what tied me up was the controls. its like too many inputs overwhelm the game and its a real damn shame because it made something that could of been amazing into a poor experience. i might revisit it to see if i can work around it but i wouldnt count on it.', 'Mixed', 66.35, 0.95, 1.75);
INSERT INTO reviews VALUES (33173, 1083790, 309, 'This game is criminally, offensively, underrated. I bought this on a whim because I liked the style and visuals. Jesus H. Christ, that was the best whim I''ve ever had. All the music is incredible, the combat style is unique, and the visuals are more stylish than anything I''ve ever seen. If you have twenty dollars to spend on an rpg, you''d be hard pressed to find a better use for that money than this game.', 'My game save got deleted', 'Overwhelmingly Positive', 98.71, 26.00, 2.87);
INSERT INTO reviews VALUES (33178, 1083870, 124, 'This game is a delightful mix of strategy, humour, and lighthearted fun that keeps me coming back. The concept of playing as a country ball is unique and entertaining, and the design is simple yet charming. The game is bright, colourful, and has personality. The animations are smooth. All and all a good game and worth buying despite there being a lack of updates. A solid 7.2/10', 'its dead and a cash grab, do not even buy it, not even on sale.', 'Mostly Positive', 75.81, 12.92, 1.30);
INSERT INTO reviews VALUES (33179, 1083880, 1800, 'game''s good but there''s a bug in the prequel game "real life" where when you talk to any of the girl NPCs they don''t immediately want to have sex with you, can you fix this please? thanks', 'Cool, I need a patreon subscription to get access to all content in this game. I actually very liked this game until I found out the patreon.... now I wish I pirated the game. Don''t buy this on steam', 'Very Positive', 85.94, 13.40, 29.02);
INSERT INTO reviews VALUES (33182, 1084020, 969, 'very good city builder, a cheaper alternative to city skylines 2.', 'This is a mobile game ported to PC and it shows. Ingame prompts to make an account with them for an online service nobody wants, limitations on the player from how many region slots they can make hidden behind a gold coin cost. You can earn the coins for free or you could pay them with real money. It has a really bad UI that was designed around phones and touch screens and mechanics that are very skin deep.\n\nIt takes literally 4 clicks to get to roads, pipes, powerlines or most buildings. When y', 'Very Positive', 91.54, 40.57, 0.25);
INSERT INTO reviews VALUES (33187, 1084160, 4733, 'Played JA1 and JA2 when they first came out many years ago. It was one of my favorite tactical RPGs in that era along with XCOM. I highly recommend this game if you''re into that genre. 10 bullets out of 10.', 'I like x-com type games and i never played JA before so i thought i should fix my error and tried JA3.\n\nAt first i thought its great. Later i thought its kinda like baldurs gate with guns, not exactly xcom. Later got frustrated few times due to sudden difficulty spikes without proper warning and annoying resource management. Then i thought that i do not like African setting, rpg elements, humour and this feeling im fighting with junk, chase clock, run out of money etc. \n\nIn the end i asked mysel', 'Very Positive', 88.32, 80.07, 50.58);
INSERT INTO reviews VALUES (33199, 1084640, 618, 'these chickens gay good for them', 'This game could be good if it worked right but it doesn''t and the immediate save system it has compounds this BS.  I need to interrogate a guy to move on with the story but the bubble didn''t become available, or if it did, I did something else first so it disappeared so I can''t interrogate him. The map isn''t available to move anywhere else and maybe comeback to do the thing I missed because the game wants you to do everything in a certain order, so I must stay where I am and do the thing which i', 'Overwhelmingly Positive', 96.12, 33.92, 7.67);
INSERT INTO reviews VALUES (33220, 1085160, 160, '분위기는 좋고 중간중간 놀래키는것도 나쁘지는 않았고, 퍼즐도 너무 어렵지않아서 \n간단하게 즐기기 좋다~ 라고 중간까지는 생각했는데, 마지막에 갑자기 \n텍스트로 구구절절 설명을 하는게 너무 김이 팍 빠져버림 .. \n한글이 안되서 문제인게 아니라, 한글번역 되었다해도 마지막에 설명때려붓는건 지루했을듯', 'Nice idea.... bad execution. It just didn''t cultivate my fear.  I don''t mind cheap jump scares but.. when that is all there is.... It''s... just very lack luster. I was only nervous in the first .... 30-40 minutes? Very simple but... just not great. 3/10 stars', 'Very Positive', 86.25, 1.97, 3.55);
INSERT INTO reviews VALUES (33221, 1085180, 263, 'Whether you''re going for all the achievements or playing casually, this is probably the shortest and most streamlined of the Gunvolt games to beat. Consequently, I''ll admit it''s stuck with me less than the other games in the series.\n\nThat all said however, it''s a massive amount of fun! Copen''s “the floor is lava” gameplay from GV2 is back and as fun as ever. The levels being shorter makes them a blast to replay. The boss designs are overall pretty good, and beating them unlocks some of my favori', 'The problem with this game is that it has no problem on being bad. It''s Bad like wow they thought this is a game. It''s a shame really. The game developers have no idea how Mega Man Zero balanced hard but fair. It has too many moments of it being too easy and then suddenly being stupid hard. The people who made this game really are having a problem of easy and hard being separated on difficulty choose. I went fearless because normal felt too easy. So I tried it and it still felt easy until I face', 'Very Positive', 90.49, 6.87, 3.02);
INSERT INTO reviews VALUES (33224, 1085220, 262, 'to be honest i didn''t think that i will like this game but when i played it i totally had good time.\nreally enjoying feels very different from the other games.\nit contains the Arabic language which is a beautiful thing.\nreally good game (:', 'The game is nice and funny for a single player. \nMy problem is with the Co-op because the second player can''t really do anything, not part of the boss fights, can''t do any puzzle so playing it with my wife is pointless. Mostly player two is just sitting there doing nothing it is like the developers did something to check that we have a co-op mode without any real effort which is a shame because othereise we really like the game.', 'Very Positive', 94.27, 6.80, 1.82);
INSERT INTO reviews VALUES (33233, 1085510, 7219, 'I never thought a kart racing game could change my life, but Garfield Kart: Furious Racing did just that. This game became more than just a way to pass the time; it became an anchor in my life when I was at my lowest. As I faced personal battles with addiction and struggled with dark thoughts, something about the game’s simplicity, humor, and lighthearted charm pulled me out of that void. Racing alongside Garfield, Odie, and Jon became a reminder to not take life too seriously, to laugh, and to ', 'garfield kart rip off', 'Very Positive', 89.83, 0.25, 5.95);
INSERT INTO reviews VALUES (33242, 1085660, 74247, 'Terrible game, terrible mechancs, terrible maps. Zealots Reward. -5 handling, terrible maps. Terrible pvp matchmaking.\n\nWould def recommend 5/5', 'This is the best game that I can''t recommend. The shooting, the art, the sound—everything about it is the industry''s best, held back by draconian progression systems and temporary-by-design story content. I imagine this game is comparable to something like heroin: it feels so good... until it doesn''t. And then you''re stuck chasing the dragon. No other developer exhibits such frustrating inconsistency of quality and consideration for its players. The future of this live service game is uncertain,', 'Very Positive', 80.96, 4962.88, 5902.30);
INSERT INTO reviews VALUES (33245, 1085750, 892, 'Still better than Overwatch', 'Such titillating graphics muddled by constant reading. I came here for Stalin backshots! Not to learn about the history of communism. I did enjoy Stalin''s voice.', 'Very Positive', 81.50, 2.05, 1.35);
INSERT INTO reviews VALUES (33258, 1086010, 372, '198X is a cute little narrative game with impeccable 80s vibes conveyed through the synth sound design and the outstanding pixel art.\n\nThe game features a collection of mini games that you would expect to find in an Arcade during the period this game takes place in. Those mini games come from a variety of different genres - there''s a dungeon crawler, a beat ''em up, a racing game and more. I definitely enjoyed the diversity of genres and each game had something in store for me. Depending on your ', 'Was expecting to play as a dude but the girls voice you play as is beyond annoying. The story sucks and is just a Tron rip off. Great idea but poorly executed and playing as a lesbian makes it worse.', 'Very Positive', 84.68, 1.82, 0.32);
INSERT INTO reviews VALUES (33271, 1086410, 533, 'super fun, amazing with friends and loads of possibility''s with the custom game options, way better than golf it.\n\nand even Markiplier said this is better than golf with your friends.', 'In the LT version press the C key to unlock the camera so you can use w,a,s,d to look around and it works... In the full version this dose not work so you can not look around and see where the whole is..\r\nThe full version is literally unplayable', 'Very Positive', 94.75, 20.63, 0.90);
INSERT INTO reviews VALUES (33278, 1086640, 632, '⠀', 'im pretty sure this just mines bitcoin', 'Mixed', 66.61, 4.72, 0.27);
INSERT INTO reviews VALUES (33286, 1086850, 469, 'That was absolutely amazing!!! I wish there were more islands/content hihi\r\nI am super addicted to farm/crafting games and I was so happy when I found this in VR!!\r\nI completed the story but I didn''t rush it, just enjoyed my time decorating the island.\r\nSuper cozy game, if they release a DLC or a similar game, I will definitely buy it!', 'I must be really stupid, or there are mechanics from some other particular game that is an unspoken prerequisite to this game, because I managed to give the creature the beets it wanted and get a block of "water" that I somehow managed to put into my inventory... and that''s it.  Isn''t the tutorial supposed to show you how to play the game?', 'Very Positive', 93.18, 14.77, 0.83);
INSERT INTO reviews VALUES (33290, 1086940, 407236, 'Turns out i like turn-based RPGs. Turns out I like DnD based games. When I first saw this game, I didn''t have a single bit of interest. I gave it shot, and now I''m completely enthralled. This review is for the skeptical people who wouldn''t normally play these types of games. It''s a bit overwhelming at first, especially if you''re unfamiliar with DnD! It''s worth the learning curve!', 'With the heaps of praise this game has received, a negative review is likely to stand out as being "wrong", but one should keep in mind that games (and a person''s enjoyment of them) are, at the end of the day, a fairly subjective experience.\r\n\r\nI couldn''t keep my hands off this game for the first 15-20 hours. I picked up every single item, read every book, and talked to every NPC I came across. I felt wholly immersed in this world and I was having a blast. But, alas, around the 20-25 hour mark, ', 'Overwhelmingly Positive', 96.89, 80.40, 91.98);
INSERT INTO reviews VALUES (33303, 1087270, 250, 'OOTP continues to add more features to the FHM franchise making it still one of the best manager sims for hockey out there (EHM probably still edges it out at this point).\n\nMy biggest complain with this series is probably the fact that there is no 2D representation of the games going on for simming. Text is fine and all that but having a 2D representation at least would let me know which players are actually doing their job well. \n\nAnother big one will probably be scouting\\when the draft happens', 'I see you still haven''t fixed the issue where, upon a player receiving a penalty with no time left in the period, the game completely shits itself and the only way to finish and exit the game is to Sim End.\n\nDid we pay full game price for a roster pack and an unnecessary rivalry feature, or were any good and helpful fixes actually made?', 'Mostly Positive', 76.80, 252.48, 3570.73);
INSERT INTO reviews VALUES (33308, 1087460, 474, 'its like Stick RPG\n', 'It can be fun bu ts mostly a grindfest', 'Very Positive', 91.14, 5.73, 4.58);
INSERT INTO reviews VALUES (33319, 1087760, 919, 'Very sweet and relaxing adventure/puzzle game for a few evenings. Cleaner simulator with a vacuum cleaner. The grind for plants and materials is just so satisfying.\n\nAt the same time — beautiful landscapes, great character voice acting, an interesting and heartwarming story. Pleasant sounds in the menu and the game itself. The process of cleaning up the world brings some strange satisfaction. Perfectionists will appreciate it.\n\nRuns great on Steam Deck with high settings. Took a lot of cool scre', 'The Gunk is definitely a mixed a bag, I enjoyed it as much as I found it infuriating at times, as an artist myself I appreciate the work that went into the world, props, character design but not so much in the gameplay department, level designs were too simple at times and hence it gets repetitive later on, don''t get me wrong I did enjoy my short time with it but wouldn''t recommend it outside of the really pretty world building (bonus points for a pretty good UI design), I got it at a discount s', 'Very Positive', 85.53, 12.00, 7.37);
INSERT INTO reviews VALUES (33336, 1088090, 4076, 'I have some mixed feelings of this game. I started playing when it was in legacy, early access. with 2 base dragons and 1 DLC. it was a fine game concept for something that was a work in progress, and having the DLC be the one dragon in the roster that can''t fly made sense to me. However, with the newer updates and dragons that are being added, more and more of them are DLC exclusive. Hell, there''s a dragon that only people who were there for the kick-starter can use. they''ve since made an NPC t', 'paying per dragon really sucks\r\nwill be interesting to see how this functions when the game is complete.\r\n\r\nwould like to pay for the game and have dragons to play\r\nnot pay for the game AND pay for the dragons.', 'Mixed', 69.70, 410.57, 22.00);
INSERT INTO reviews VALUES (33348, 1088710, 4528, '95% of the game is like having your own wholesome family, like happy, home, inner peace....and then BOOOM. Last 5% of the game you are cutting onions, trying to hide your tears, but you cant...because the endgame broke me!\n\nA yakuza game is always a good choice. You dont consume Yakuza games, once u started, yakuza games consume you.', 'this game stares at me from my steam library when im trying to sleep. it makes me dream of unsatisfying combat and poorly tracked substories. of never earning enough exp or money from street fights to ever justify doing them. of a bad level up system. of terrible boss ai. and of being gay. im not sure if that last part has anything to do with the game tho\r\n\r\nyakuza 4 is great', 'Very Positive', 84.85, 148.98, 32.47);
INSERT INTO reviews VALUES (33351, 1088770, 203, 'The game has a lot of promise. it has the right idea but was executed kinda poorly. the biggest turn off for me is the bugs. the game itself is fine. the controls are a bit wonky as well. but as i previously stated, the game isn''t horrible. if you don''t mind a few minor bugs, and slightly weird controls, go for it.', 'Poorly adapted VR title.\nControls are super confusing at first, even once you get to know them you realize they''re kind of jank.\nForce-grabs don''t work. \nMenus open when you don''t mean to open them and block you from making progress\nThat tablet needs to be able to be hidden as it gets in the way\nSandbox mode you have to bid on cars, and can''t just... do sandbox/creative mode stuff (like summon cars, motors, etc)\nWould not recommend as it''s purely frustrating and enjoyable. It''s also super unreal', 'Mixed', 60.10, 5.25, 1.98);
INSERT INTO reviews VALUES (33352, 1088790, 2256, 'Huh, wha... Who, me? Airstrikes? Uhhh, no... umm... no no. Uhhh... it was that guy, yeah, him. He called for them, not me.\n\n\nAirstrikes successfully denied.', 'Very stupid and random game, that lacks the ability to give you a fair and hard challenge, so instead compensates by randomly spawning isurgents and their camps in already stabilized zones, with max level police and a garrison nearby just because you''re doing too well. Clearly camps dont just spawn in areas with most opposition over some time, but also spawn instantly if you destroyed the last insurgent group somewhere else, just to keep you playing! Captured zones cause you reputation bleed, an', 'Very Positive', 83.24, 3.57, 65.00);
INSERT INTO reviews VALUES (33355, 1088850, 16742, 'One of the most misunderstood game premise''s of all time if the reactions to the trailers of this game are anything to go by. Marvel''s Guardians of the Galaxy is a action team leadership simulator and it is surprisingly fun in how it plays. All of the Guardians have four abilities by the end with each functioning uniquely both from a member to member basis as well as for the individual members. Drax is the brute so he can bulldoze through enemies, Gamora''s abilities do high damage to individual ', 'I purchased because it stated it was Steam Deck Verified...I spent around 30 minutes running different settings and even messed with the BIOS settings on the deck and could not even successfully get to the in game menu screen. THIS SHOULD NOT BE VERIFIED ON STEAM DECK', 'Very Positive', 93.75, 25.62, 0.17);
INSERT INTO reviews VALUES (33367, 1089090, 4437, 'Fun button masher with Luffy in it but why God why are the Vinsmokes taking up four separate character slots that easily could''ve gone to Enel, Kuma, Perona, Moria, Caesar, Magellan, Goku, literally fucking ANYONE but the Vinsmokes? I would''ve genuinely taken Vander Decken IX over Yonji''s bitch-ass.', '     This is one of my favorite games and i truly put it up there with my top 3 of all time, however this review belongs to the pc port exclusively. This game is unplayable with the amount of lag and unexpected game crashes. no amount of fixes or setting changes has fixed this game. I can run new games this year at the highest settings no issue, but this piss poor excuse of a port has disgraced an amazing game. \r\n\r\n  To the developer, \r\n           You really should try to fix bugs and issues mor', 'Very Positive', 93.80, 111.35, 8.55);
INSERT INTO reviews VALUES (33389, 1089780, 175, 'In 2024, the game seems to be abandoned from what I''ve seen from others in this community. Nonetheless, if you have the necessary hardware to run the game, you should be fine. \n\nThe game does have it''s jankiness at times, but I''ve found that most VR games have it so it doesn''t negatively impact my review. If you''re not picky about that you should be able to enjoy the game.\n\nDespite the mixed reviews on the game page, I have been able to have fun. The game is challenging, and has enough content t', 'This game still needs a lot of work. my biggest problem is when you try to grab your magazine you end up grabbing the med kit and you can only drop it at that point. Start a round with all your magazines at your feet because the grabbing system is glitchiy. Has a lot of potential but not there yet.', 'Mixed', 67.43, 9.47, 6.67);
INSERT INTO reviews VALUES (33390, 1089790, 104, 'its very good only one minor thing it crashes a lot! but still very fun i love learning all about chairlifts and setting them up in this game.', 'Buy the sequel. This one is abandonware', 'Mostly Positive', 72.12, 96.68, 30.88);
INSERT INTO reviews VALUES (33394, 1089830, 655, 'The best Supercross game we''ve had in a while, having said that. Yearly iterations of this game with updated tracks and barely any other changes needs to stop.', 'I had never heard of supercross before, but the game looked interesting so I decided to pick it up for cheap during the summer sale. I''m kinda confused how well this game is rated considering how bad the tutorial is. As a new comer it really doesn''t explain basic things, like how to turn properly without crashing or how to maintain momentum for jumps. It also doesn''t explain the purpose of sweeps or sweeping, whatever they are called, all they seem to do is make you fall over. Even when I starte', 'Very Positive', 86.56, 20.00, 0.80);
INSERT INTO reviews VALUES (33395, 1089840, 172, 'It plays more like Graviteam Tactics were you issue orders prior to the start of a battle. Decent amount of content to play around with. Campaigns aren''t that in depth but still a lot of fun to be had if you want a more modern era of war game.\n\nPretty easy to learn as well. Would recommend some you-tube vids to familiarize yourself with the functions.', 'First person, action scenes provided in advertising show first person scenes. There are no first person playing or animations in this game. So why show something that isnt in the game?>Tactical map game. Not first person, real world game and misleading.', 'Very Positive', 86.63, 19.85, 0.22);
INSERT INTO reviews VALUES (33401, 1089980, 35387, 'Incredible heart breaking interactive story line with Dark Souls level difficulty. Only buy if you have a strong heart and iron will.', '0/10 No way to save charles.\nBut''s it''s a good game play it.', 'Overwhelmingly Positive', 98.82, 2.52, 43.27);
INSERT INTO reviews VALUES (33409, 1090250, 444, 'Such a fun game. The fact that there are updates coming out of the pipeline again gives me hope, this game has incredible potential. The rogue-like mode is my go to with friends.', 'Completely abandoned. Shame.', 'Mixed', 51.35, 13.55, 2.85);
INSERT INTO reviews VALUES (33420, 1090800, 112, 'i am enjoying the game, but i got it after hearing there was an online co-op mode. its ok if you guys arent doing it anymore, but i bought two copies for myself and my boyfriend, and would like to know if you still plan on releasing a co-op mode in future.', 'Do not support this developer...This game is v0.15 its been out for almost 4 years now and the devs are now talking about another game already as this one will eventually be abandoned....too manny times i have seen this exact behavior with indie devs and being a dev myself its unethical behavior period and just gives indie devs a bad name\n\nAnother dev that scams people 15$ and charges to support them but in the end they will never deliver which is just bad for the Steam EA program as a whole and', 'Mostly Positive', 74.11, 4.78, 0.77);
INSERT INTO reviews VALUES (33422, 1091500, 333898, 'I can''t stop jacking. I''m serious. I see a port and i just have to jack it. Any opportunity to jack it, i do. I love when the story makes me jack it. honestly, i''m addicted to jacking it.', 'The game is awesome but I cannot help but be frustrated with the steam deck version.\n\nBeing marked as "verified" is misleading as I have not had any game cause me more issues on my steam deck than Cyberpunk 2077 ; audio issues, performance issues, crashes, problems with the launcher...\n\nA little tweaking around could probably lift up a fair amount of annoyances but that is not what a "verified" experience is about in my opinion. \n\nIts a hard game to run and crazy that it is possible to do so on ', 'Very Positive', 87.63, 64.87, 13.92);
INSERT INTO reviews VALUES (33424, 1093290, 286, 'I''ve just finished the game and it''s 2.30 am so would say it''s quite addicting. The story is captivating and the characters are absolutely adorable. Would recommend to anyone who is looking for a fun game that is not too complicated but still insanely entertaining.', 'It''s a cute, colorful, safe and enjoyable game for younger players. However, it is not the reasons I purchased it, as I was looking for a more complex adventure experience.\n\nAfter spending 1.5 hours in the game, I found myself mostly doing repetitive tasks, like collecting seeds, using a dryer on haystacks, directing minions to carry wood... I pushed myself to keep playing and when I encountered fire minions, the gameplay remain mostly the same instead of they get certain things on fire. I can a', 'Overwhelmingly Positive', 95.45, 30.02, 1.50);
INSERT INTO reviews VALUES (33425, 1094000, 348, 'This game is good, i really like it. I first play the mobile version, then switch to steam version, but i notice a bunch of different thing that far behind from the mobile version. So please update more the steam version, or at least make the feature that are available on mobile version is on the steam version too.', 'Goofy Off-brand Raft I Bought On Accident', 'Mixed', 60.34, 3.48, 0.63);
INSERT INTO reviews VALUES (33428, 1094780, 510, 'This game far exceeds most other fishing games Ive played. Left RF4 for this game and will most likely never return to that money scam game.  Lucky for me it is free Norway week and Im really enjoying their version of sea fishing. Free boats, cheap map transfers and the starter gear is pretty cheap. So refreshing to play a game designed to have fun and not a money grab like RF4.', 'Unfortunately it''s nearly impossable to fish the ever highest level venues if you got a job. Takes thousands of hours to reach the level for the last level.\n\nBesides that the game is pretty nice. But to pay for a game and never be able to really see the latest content just kills the game for me.\nAlso it''s a game you buy but dont get all the content you could get if you paid even more. Has a complete f2p monetisation model.', 'Very Positive', 81.96, 631.87, 339.15);
INSERT INTO reviews VALUES (33431, 1096410, 1246, 'Vampire: The Masquerade - Coteries of New York is a narrative-driven visual novel set in the Vampire: The Masquerade universe. It offers rich storytelling, atmospheric visuals, and tough moral choices.\nThe art in this Game is atmospheric and dark, perfectly capturing the mood of the game''s gothic, vampiric world. \nThe three main characters each have distinct backgrounds and personal stories, reflecting their unique vampire clans. Their narratives explore different aspects of the vampiric world, ', 'Starts of promising. \nYou explore a bit, get to know characters.\n\nAnd then it simply ends.', 'Mostly Positive', 70.14, 5.73, 6.55);
INSERT INTO reviews VALUES (33432, 1096530, 12595, '"I want to play Baldur''s Gate 3 but the gameplay loop is just going between dungeons to dungeons like crypt at the beginning and also I can have a full party of custom characters instead of Origin Characters" \n\nThis is the game for you (me)', 'I saw that they were making Solasta 2 so I thought I''d leave a warning here. I bought this game at early access, you would think that they would include everything in the early access build until it''s fully released. But no, they started selling character classes as DLC. What''s the logic in that except for greed? How can you sell one of the most basic things in the game as DLC before it''s a full build? Very scummy. Think again before you buy Solasta 2.', 'Very Positive', 88.10, 4.47, 6.10);
INSERT INTO reviews VALUES (33433, 1097150, 149291, 'I found the best way to enjoy this game is to take repeated shots of liquor and multiple bong rips to the dome', 'I spent like 20 bucks for a bullshit RNG fest of a game just for it to go free to play and be removed from steam.\nAwesome.', 'Very Positive', 83.82, 92.73, 8.70);
INSERT INTO reviews VALUES (33434, 1097620, 581, 'love men', 'after like the 6th level the game is insaley hard and literly imposible to complete it.\r\n\r\n\r\nlove my spelling', 'Very Positive', 82.27, 5.22, 19.52);
INSERT INTO reviews VALUES (33438, 1099410, 1595, 'love myths, love mythological creatures, can''t wipe russia here but this is a good game!', 'Dissapointed with how small the base game is. Only 4 factions playable, constantly being reminded to buy dlc to get the full game.', 'Mixed', 69.97, 43.63, 31.92);
INSERT INTO reviews VALUES (33445, 1101120, 1384, 'They actually listened to me and added the ''magazine variant'' function to the latest Thompson M1928! I''m so glad that the developer added that to Thompson, my most favorite gun from WW2 era.\r\nW dev.', 'Hilariously poor realism. Parts improperly named, parts straight up missing, the game forces you to disassemble guns in mechanically impossible ways. For example, the AR in the first few missions has a mid length government profile barrel and a rifle length gas system meaning the rifle wouldn''t even cycle, period. 0/10 since the devs don''t even seem capable of making any effort to do basic research on what they''re making a game about. Calling a magazine follower a "magazine top part" has to be r', 'Very Positive', 85.77, 64.17, 0.72);
INSERT INTO reviews VALUES (33447, 1102190, 11863, 'This is one of those games where you''ll either play 20 hours of it and never think about it again or you''ll play hundreds of hours and it will never leave your recently played queue.\n\nIt is endlessly replayable. Every time you load up a game it feels different and you will have to adapt your deck building strategy on the fly. It is a text book example of not judging a book by it''s cover because there is a depth of gameplay hiding behind its simple facade that is breathtaking. \n', 'fun at first but as you start getting into the higher difficulties, it really shows that only certain strategies are valid.', 'Overwhelmingly Positive', 96.84, 1028.08, 24.68);
INSERT INTO reviews VALUES (33450, 1103490, 187, 'Is this game hot? Yes, very. Is this game good? It''s... fine, but it''s somewhat rife with some very annoying issues.\n\n Positives \nOne of the game''s strong points is definitely the storytelling and presentation. So many games with succubus nowadays have been watered down to no more than cosplay sex stories. This game really emphasises on the actual horror and menace of succubi as a demonic race. It definitely added some thrill to the gameplay, and made it... scarousing. It also has a nice pacing ', 'Beautifully drawn artwork, however lacked basic functionality of a standard VN game (gallery mode, auto, fast foward, log, game settings, etc) and is still plague with issues not yet fixed with this update.', 'Mostly Positive', 74.87, 5.35, 2.68);
INSERT INTO reviews VALUES (33451, 1103860, 254, 'Really good if you have someone to play with but absolutely nobody was on and player base is pretty much non existent.', 'Playing on my Quest 3 through steam link. The virtual hands were at a 45 degree offset from my real hands. It made range combat difficult, melee combat impossible, and menu navigation a hassle.', 'Mostly Positive', 74.80, 0.75, 1.03);
INSERT INTO reviews VALUES (33452, 1104280, 2780, 'The game is by no means perfect, but it has kept me entertained for far longer than any other ARPGs like Diablo or Last Epoch.', 'This game''s a grind for the sake of being a grind, the entire game is filler. I was hoping the 1.0 launch would improve the gameplay loop a bit but unfortunately it''s just too stale for me. The campaign is pointless pee pee poo poo humor that doesn''t contain any meaningful story, the actual gameplay boils down to 3 buttons (primary skill, secondary skill, specialist skill) and 4 "ancestral" keys you''ll rarely use because the effects are mid. Every map is "open breach, kill enemies (sometimes WAV', 'Very Positive', 88.06, 547.60, 117.88);
INSERT INTO reviews VALUES (33454, 1107320, 1630, 'Made a friend in a chase. Really cool guy.\r\n\r\nThen he got sucked up by a tornado and I never saw him again.\r\n\r\n10/10', 'Why is there a minimum player count of 8 people to play a private party? Realistically, most people in a group of friends aren''t gonna have 8 people who are willing to fork out £30 for a niche early access game like this. The game looked it would be good fun to play with a couple of mates, but I can''t I guess! We''ve all refunded now, maybe we''ll return when this limitation is removed.\n', 'Mostly Positive', 78.40, 35.83, 0.27);
INSERT INTO reviews VALUES (33461, 1111940, 134, 'My parents think im gay my name is luke grommit, I live in 308 negra aroal layne albaqwerky new mexico', 'Quiplash, but with french people. Should be cheaper. Just buy party pack 3 if you only speak english.', 'Very Positive', 91.04, 5.15, 1.57);
INSERT INTO reviews VALUES (33466, 1114150, 5765, 'After reading all the reviews and spending some actual play time with the game i''ve come to realize that the majority of people are wrong. I was in the same boat as you were the physics didn''t "FEEL RIGHT" and the cars were floaty and had lots of under-steer, but it all come down to the tuning! This not CARX Drift Racing where you can drift anything from balloon tire cars to slammed to the ground cambered out mess of a car. the tuning actually matters PLEASE spend some time with the game before ', 'Welcome to the game that makes you pay twice for the main vehicle shown on the cover of the game, and breaks its promises (as well as steam TOS) of including a DLC for deluxe pass owners. These are not serious devs', 'Mixed', 69.49, 64.50, 94.75);
INSERT INTO reviews VALUES (33468, 1115450, 129, 'Chill or challenge?  It is up to the gamer to set the difficulty.  Either way this is a fun game and seems to be a labor of love for the author.  I recommend this game to anyone that likes survival and city build without zombies (Ha, ha, ha).  It''s still is colonial to medieval and much like how we got to where we are today.  EZ to learn controls and weather system as well as speed-up or freeze time.  More features abound, give it a try today!', 'built a sawmill which produced planks for a while but then stopped producing planks later on in the game so you cannot build structures requiring planed wood.', 'Mostly Positive', 77.52, 12.20, 55.38);
INSERT INTO reviews VALUES (33471, 1116170, 110, 'Really fun so far. A great combo of Synthetik, Roboquest, and Ruiner. A lot of fun, high paced action, and a work in progress (so be nice to the dev team). If you follow the patch notes, you will see that the releases are frequent and pack a punch.', 'Text and audio reads and sounds like it''s either AI generated or from a source that was never checked for grammar, spelling or realism. Bugs and general gameplay issues I can totally understand and forgive from an EA title, but being lazy when it comes to what the characters say, and leaving in blatant spelling and grammar issues? Come on already. Spend less time advertising on Twitter and more time working on the quality of your game.', 'Mostly Positive', 74.55, 7.75, 0.18);
INSERT INTO reviews VALUES (33473, 1117090, 457, 'Real ones remember when this was ''Purble Place''', 'The game is a ripoff, The original game is free and always will be free.\nIts not by the same original creator, You can always download the real copy legally off of the web at zero cost instead of buying an illegitimate mess on steam. \n\nPlease spread the word about this copy being a ripoff and if you''ve already made the mistake of buying this crap just give it a negative review.', 'Mostly Positive', 78.56, 0.97, 2.33);
INSERT INTO reviews VALUES (33474, 1117310, 133, 'Having successfully worked hundreds of traditional Sudoku puzzles, I was ready for a change. I ran across "Cracking the Cryptic," and decided to try Sandwich Sudoku. I really enjoy the math clues to help solve the puzzles. It took a fair amount of time to figure out what the numbers on the puzzle menu meant, but finally realized you just start each puzzle by double clicking on any one ( I am old school, so I started with number 1 and worked them in sequence!) i am getting a bit faster with each ', 'Now I want to emphasize that this isn''t a bad game by any means. This is actually pretty good sudoku with a nice twist and quality of life features, but that''s the problem... it''s JUST some good sudoku... with a twist... and some quality of life features. I just don''t see the point in buying this when there are plenty of free versions of sudoku that are close to if not as good as what''s provided here. Like, there''s not even background music so you''re gonna have to provide your own when playing u', 'Overwhelmingly Positive', 96.99, 89.68, 3.38);
INSERT INTO reviews VALUES (33478, 1118240, 2125, 'Ok, the game is relaxing and if u wanna get away from everyday life''s stress it is very good for it. But i guess the story should''ve been much more rich. İt took me  seversl hours to finish the game. The choice of the dialog is nice. \n\nEndings are nice too. Only objection is game is super short.', 'I would really love to write a positive review about this game because it is graphically pleasing and a very relaxing game, but that''s about it. It is way too expensive for what it is and there is really no way to justify the price. Sure, if you''re looking for a stress-free and boring game, you can play this, but there really isn''t any real "decision-making" or it doesn''t feel like it. I tried to push through, but I can''t see the game becoming more entertaining and I feel like I could make bette', 'Very Positive', 87.25, 8.78, 2.47);
INSERT INTO reviews VALUES (33480, 1119800, 106, 'so i purchased white lavendar a little while back from these guys and liked it. it''s a very short souls game with simple mechanics and a unique artsyle and environment to go off of and play through. the games are simple, for some reason i found this game more calming and you can run through it a couple times pretty quickly if you want to get all achievements, especially when you remember where to go and what not. the combat is very traditional and simple, and it works throughout the entire game.', 'When I started, I really wanted to be able recommend this game or at least say I was neutral on it, but on... I actually hate this game. The graphics are amazing and actual foundation of the combat is solid, but it fails at just about everything else. There is little to no story, the game fails to tell you, about several mechanics, your stamina is way too low to be useful, enemies do to much damage, you get locked into the bad ending to easily, the game world is too small to have enough enemy va', 'Mostly Positive', 79.25, 1.20, 1.97);
INSERT INTO reviews VALUES (33481, 1120480, 491, 'While not my type of game, I really appreciate modding support and developers looking beyond GaS.', 'Chet, this game is an embarrassment. How do you go from being a well-regarded and respected game developer -- having contributed in the conception of such titles like Left 4 Dead, Half-Life, Portal, etc. -- to now being someone who seems to have completely unlearned everything and created a game I would fully expect a beginner or junior-level game developer to make. I, and so many others, gave you and your team''s game the benefit of the doubt. It was in its infancy, you and your team were experi', 'Mostly Positive', 71.69, 1.65, 6.25);
INSERT INTO reviews VALUES (33482, 1121560, 1908, 'Wow. I actually ended up loving that a lot more than I thought I would. Gust knows how to push my buttons with the "Everyone moving on" trope that always gets me...\n\n\n\nP.S., Koei I''d love to play more of the series if you ever dropped your years old games below $20...', 'Loved the game! Journeyed over the months and finally finished the story just couple weeks ago, then playing for post-story achievements.\n\nWhat made me stop now: Recent update (Sep 2024) changed my entire settings incl combat keyboard mapping! Tried using the new mapping but could not activate fatal drive. Tried changing the keys to no avail. was frustrating to go up against post-story bosses while trying to re-discover the keyboard, only to find out i cant use the fatal drive.\n\nI really wish th', 'Very Positive', 88.52, 39.87, 122.08);
INSERT INTO reviews VALUES (33487, 1124180, 933, 'As a railway maestro in Rail Route, I''ve found myself lost in the intricate dance of steel and steam. The game masterfully blends the simplicity of a city builder with the complexity of a logistics puzzle. Each city map is a new canvas, and I''m the artist, painting lines of track that pulse with the lifeblood of commerce and industry. The automation system is pure genius, allowing me to sit back and watch as my network operates like a well-oiled machine. Yet, the challenge is ever-present, keepi', 'I want to love this game so much.  I played many many hours of Train Dispatcher 15+ years ago, and was excited for this title.\r\n\r\nBut I just find it frustrating.  I think the problem lies in the UI.  Too many inconsistencies - right click vs. escape to exit menus, etc.  A game like this that depends on speed of reconfiguring routes, it''s too difficult to clearly lay out routes, quickly switch from building to routing, etc.  Really needs a revamp.  Going to uninstall, but monitor future developme', 'Very Positive', 87.25, 126.60, 10.38);
INSERT INTO reviews VALUES (33488, 1124300, 11731, 'I love this game. That Civ 7 is copying a lot of the mechanics that made this game different should tell you everything you need to know.', 'I still want to like this game. It''s not that it could have been so much more, it''s not that the 4x and combat elements are still too disconnected. It''s quite simply that the actual gameplay is not fun. \r\nThe case study that prompted me to write this review:\r\nI''m playing a greedy game where I''m the only civ on my relatively large continent. I pick England and build Strongholds in various strategic locations. I own the whole continent and have lots of tech and buildings but a fairly small army - ', 'Mixed', 68.46, 155.00, 74.18);
INSERT INTO reviews VALUES (33490, 1124660, 343, 'I came from the outer space.', 'Like the vast majority of meme games this is low effort trash that just exists to try to capitalize on a trend. You''ll get bored of it after about 5 minutes. If you removed all the ''haha meme funny'' positive reviews this would most likely be sitting at overwhelming negative.\n\nBad physics that don''t allow you to strafe while running and kills your momentum when you jump. A running speed that is just barely faster than a decrepit grandmother walking. No options menu. Bad lightning effects. No audi', 'Mostly Positive', 79.88, 9886.68, 3.65);
INSERT INTO reviews VALUES (33494, 1125510, 429, 'This is the perfect little cozy game.  Although, seeing as I''ve played it for 99.9 hours now, I guess "little" might be the wrong word!  It''s got a cute story, tons of things to do, hilarious quest lines (and item descriptions) and is such a great balance of relaxing and attention-grabbing.  Oh and also, the devs are AWESOME - congrats on 1.0 guys!!', 'With how much the reviews hyped up this game, along with the 25$ price tag, I expected way more. I understand that the game is in early release, but it is painful to play. I put 18 hours into trying so hard to love this game.\nEverything about the crafting mechanics are terrible. For example, if I need 10 stone paths for a quest, and I already have 9, I can''t just craft the 10th one. If you already own an item, the option to craft it disappears. So you need to place all 9 of your items, craft the', 'Overwhelmingly Positive', 97.90, 100.42, 23.82);
INSERT INTO reviews VALUES (33495, 1126750, 103, 'yeah i like it. druaga and the "indiana jones" style minigames are a bit tough, but i like how the different rules make you think about the game in different ways - it''s fun to think up different strategies. I''m not that good at mr driller (I can get to 1000m with standard rules if i''m very lucky), and it didn''t take that long to unlock the 2000m stages, which are more than enough for me to handle.\r\n\r\npeople mention the great music and it really is very pleasant, especially when playing the game', 'DO NOT BUY IF YOU''RE COLOURBLIND.\n\nI know this probably comes across as obvious, but I''ve played plenty of versions of Mr Driller and have managed to get by with only minimal problems. I don''t know how they''ve managed to do it, but in this one they have chosen just the WORST shades of green and red for the tiles, to the point that it''s completely unplayable for me. The fact that there''s nothing in the options to try to alleviate this mess is pretty damn unforgivable for after 2020, even if this ', 'Very Positive', 90.29, 7.55, 0.18);
INSERT INTO reviews VALUES (33496, 1127400, 8430, 'A pretty fun, more arcade and simplified factorio-like free and open source game.\n\nGet it for free from the official website. And if you end up liking it, buy to support the developer.', 'My husband quit his job to go pro', 'Overwhelmingly Positive', 95.23, 8.55, 14.03);
INSERT INTO reviews VALUES (33502, 1128810, 105, 'Risk’s digital incarnation elevates the classic with elegant pacing, seamless mechanics, and refined strategy—an undeniably superior experience. 6,5/10', 'im forced to COMPLETE THE ENTIRE USELESS FUCKING TUTORIAL\nGARBAGE FREEMIUM WHATEVER\nTHE BLITZ ROLLS ARE CALCULATED IN SOME WAY THAT JUST DOES NOT MAKE SENSE\n\nI AM UPSET', 'Very Positive', 81.90, 144.40, 1.42);
INSERT INTO reviews VALUES (33503, 1128920, 6518, 'Top tier game, absolute class-act studio. Only studio I''ve seen in over 3 decades of gaming that voluntarily lowered the price on upcoming content to help their community in the face of international economic uncertainty. \n\nTo any Rockfish devs that see this; y''all are fucking legends. I hope each and every one of you the absolute best of success and just know that, at least one random dude out there, is going to buy the expansion just to support y''all on this decision alone. Keep on doing good ', 'Game would be fantastic if the f.cking enemies didn''t scale.  I don''t mind if the AI plays smart but ships gradually become bullet sponges and you''re spending credits by the millions just to try to upgrade faster than they do.', 'Very Positive', 88.16, 28.88, 43.40);
INSERT INTO reviews VALUES (33506, 1130620, 530, 'Samurai Slice', '9+ crashes later. No save mechanic whatsoever (i have had to restart EVERY single time). These two aspects are among the chief reasons I have not enjoyed playing this game very much.\r\n\r\nAnother thing, however, to mention, something which I could have maybe looked past if not for the complete lack of a save system coupled with the constant crashes, is the extremely unfair and repetitive enemy AI who teleports to your exact location non-stop, ''roaming'' back and forth constantly in your exact area ', 'Very Positive', 87.17, 2.03, 4.63);
INSERT INTO reviews VALUES (33509, 1133120, 418, 'This is not a typical video game, think of it more like a science experiment.\n\nLike other Artificial Life games Ecosystem requires immense patience and is intended to be left in the background.\n\nSmall changes can have drastic effects so focus primarily on observing and/or terraform your area FIRST and watch how life evolves in what you setup.\n\nAlways save before you make a change so you can revert to when you made that change, that way you can even "fork'' your save into multiple different outcom', 'I was really excited about this game and I am sad that I don''t like it. \n\nFirst off, the concept is right on the money. It is, in theory, everything you want in an ecosystem game but it has issue that ruin the fun of watching the creatures evolve. Let me say that the terrain and plant simulation is pretty awesome, that part is sweet. But the fish, they all flop around in ways that don''t make sense. I don''t mean a few weird random species. I mean EVERY fish flops around all weird. Even when you m', 'Mostly Positive', 78.95, 41.65, 2.30);
INSERT INTO reviews VALUES (33511, 1133500, 111, 'I don''t understand people who get an early access game and then complain when they see that the game isn''t finished.\n\nThe point of selling an early access build of a game is to allow the developers to have a little extra income while developing the game. Anyways this might be the most polished early access I''ve ever played. The movement feels about as good as Mario Odyssey and The Big Catch. There isnt a lot of decorative buildings yet but the ones we have are basically essentials.\n\nI''m loving t', 'I got to be quite honest and it comes from a good place cause the ideas are great and all, but even for early access this is way under cooked, there is nothing more than there was in the beta and the game has come with many bugs which they are hot fixing quickly which I appreciate. That said I am enjoying my time just making my town and stuff, but I really think they should have waited to release it with their first planned major update which would of really helped it. If you buy this game now a', 'Mostly Positive', 77.48, 47.08, 3.37);
INSERT INTO reviews VALUES (33513, 1133870, 1347, 'Seems solid, runs 1000x better than KSP2 lol.\n\nThere are gonna be SO many negative reviews from people that ABSOLUTELY REFUSE to read what they are buying.\n\nIt is clearly stated that this is a small part of the skeleton of the game, and we are getting usable bits over the next few months. Don''t effing buy this is you can''t entertain yourself with building stuff, seriously. It''s so embarrassing to be the same species as some of these other "reviewers"', 'The game is nothing more than SE1 with a new splash of paint.  They claim they want feedback to help improve it, but when you do, you are slammed with hostile and ignorant responses that make you not want to participate at all.', 'Mostly Positive', 78.40, 1.73, 1.68);
INSERT INTO reviews VALUES (33514, 1134100, 1524, 'So this is similar to Northgard, it feels more immersive and customizable.\nHowever, this game feels incomplete. There is definitely promise with a little more refining. For $6 it''s 100% worth it. I wouldn''t pay more than $10.', 'If you subscribe to the Broodwar school of "great gameplay is clicking 200 times to move a few units up a ramp" then this is the game for you. It''s at the same time a boring city builder and an infuriating RTS. Enjoy!', 'Mixed', 66.54, 7.40, 7.22);
INSERT INTO reviews VALUES (33515, 1134710, 1103, 'It is literally the autism simulator and thats why I love it.', 'the 1.14 & 1.15 updates have added some more detail, but have been an enormous step backwards in playbility. it has become incredibly challenging to change train schedules & edit stations compared to the previous system, and has put me off playing, when i previously enjoyed the game a lot. also terrain height isn''t a thing which is disappointing', 'Very Positive', 88.76, 234.68, 481.88);
INSERT INTO reviews VALUES (33516, 1135260, 226, 'Also try Bulwark.  The game is optimized for controllers and doesn''t work well with keyboard and mouse, but controls are relatively simple any easy to get a hang of even if you don''t use controllers often. \n\nBulwark and Falconeer have some of the most interesting and creative world building from any game/series I have ever seen. 10/10', 'Can''t recommend. It looks pretty. There''s some good bit of foundational lore writing. But the game itself is very boring. The missions are repetitive. The combat is frustrating. The navigation is dull. And the story fails to make you care about anything going on.', 'Very Positive', 84.07, 5.42, 3.48);
INSERT INTO reviews VALUES (33517, 1136380, 542, 'seems realistic to me, good thing there isn''t a game warden', 'This is bad, games nowhere near ready to play. I only payed $1.99 and i''m still gonna get a refund.', 'Mixed', 65.31, 33.43, 0.20);
INSERT INTO reviews VALUES (33522, 1139980, 6618, 'I had to refund, not because I don''t like, but because of lack of accessibility. I cant ''tap'' over and over. There should be an accessibility to toggle an action to complete (like chopping wood, mining, etc). Hit me back when this option becomes a thing.', 'This game entered early access in 2020, and to this day the experience still feels thread-bare. Every corner you turn there''s something that looks like it might lead to a quest, a new zone, or something you could unlock, but you just can''t. The game has a lot of issues besides content that you might usually be inclined to hand-wave as typical early-access issues, like a poorly tuned resource economy, and an ineffectual skill-point system, but when it''s been in early access for nearly five years,', 'Very Positive', 89.88, 17.60, 19.88);
INSERT INTO reviews VALUES (33527, 1142220, 152, 'Maybe the trailer and graphics looks very cheap like a unity demo or something, but the algorithm behind the AI Generated maps with a yt video is simply amazing, love it. Nice aim trainer. 10/10', 'why why why is there not an option to have strong hit (not fire) sounds, this is literally the sole reason I refunded\n-addendum: why can I not set my own and have above be a moot point\nwhere is the hitmarker on crosshair\nwhy download yt dlp without letting me put a path to an already existing copy\n', 'Very Positive', 92.11, 4.82, 0.32);
INSERT INTO reviews VALUES (33529, 1142500, 3784, 'The best game I''ve ever played, hands down. I''ve cried multiple times because of how incredible this game is. Elden Ring who? Baldurs Gate who? Every GOTY should be awarded to Fun with Ragdolls: The Game. No other piece of media will ever top this. Even the tutorial is an absolute masterpiece, singlehandedly unmatched by anything else out there.', 'Was good, when i got it in like 2021, or 2022, but they just completely abandoned this game, then got bored of it and stopped playing.\n\nSure this game is fun, for about an hour or two but it just is sad that they stopped updating it, if you want to, go ahead and buy it, but beware of no upcoming content\n\n\nUpdate: 23/01/25\nOfc im not saying to Not buy or buy it, but i highly don''t recommend buying it, if it at all goes on sale, then maybe, as im 90% sure there will not be another update again', 'Very Positive', 90.64, 23.92, 37.08);
INSERT INTO reviews VALUES (33530, 1142710, 49764, 'The third installment of the Total War: Warhammer Series, and by far my favorite. Now there have been some major ups and downs for this game, especially given just how great Warhammer II was, but the developers have been doing a lot to fix/improve on their mistakes. In it''s current state, minus some outdated factions that are currently being worked on in future updates, this game is amazing. The scale is insane, and if you''re a Warhammer nerd, especially a Warhammer Fantasy nerd, this game is an', 'The game itself is great! I love to play it! But the DLC policy is a money making scheme at its finest. Consider the base game as a demo version, where you can only play a very limited selection of factions and also have limited access to troop types. In order to play a specific faction you''d have to buy a DLC. But hey, there are free factions, right? No. They''re free, if you own the previous games and their DLCs. If I hadn''t bought the game in a sale, I''d have refunded it. This is some EA level', 'Mostly Positive', 75.12, 95.28, 189.22);
INSERT INTO reviews VALUES (33532, 1142830, 120, 'This route surprisingly entertained me a lot. Sora route was still better though. I can''t wait for the next episode. ✍️🔥✍️🔥✍️🔥 This shit is bussin fr fr. However, I don''t want it to end. I don''t want to complete it yet T-T', 'I''m sad to say I am not finishing this series. Episode 1 was a really strong start, 2 mostly kept up momentum, but this one drops the ball completely. It''s not that it''s an episode with no merit; Like previous episodes, there''s some cool moments with interesting reveals and progression. But there''s so little of the good stuff compared to the bad stuff. The vast majority of the runtime in this episode is boring and/or immensely stupid. The conversations feel very phoned in and padded out - it fee', 'Overwhelmingly Positive', 98.33, 16.25, 8.72);
INSERT INTO reviews VALUES (33533, 1143810, 1169, 'The game gets a bit homogeneous clearing the islands, but makes up for it with a good feeling of gradual progress and an interesting narrative. I liked exploring the islands and learning about the world. \r\n\r\nI do wish airship combat had a greater role in the game. With exception to a few encounters; it serves mostly as a vehicle to grounded combat. Though there is still enough there to chew on, and fits into the game well.', 'They changed the game greatly after Early Access, I played it in EA, it was fun and really good, they dumbed down nearly all of the systems and took out the fun parts, they nearly full overhauled everything... now it is a unchallenging husk of its former glory. And there is no chance to get back the EA version!', 'Very Positive', 81.52, 23.03, 22.78);
INSERT INTO reviews VALUES (33535, 1144200, 102836, '1. bring non-lethal ''beanbag'' shotgun to mission\r\n2. cause brain damage to suspect completely rendering them a hollow shell of thoughtlessness for the rest of their life \r\n3. tell the therapist it was fun\r\n4. get promoted \r\n5. LES GOOO', 'new update just completely ruined performance, game was just fine and now it''s laggy as hell', 'Very Positive', 90.13, 69.05, 28.22);
INSERT INTO reviews VALUES (33536, 1144400, 770, 'Shinzo abe gave up fixing the declining birth rate of japan and dropped this peak to tank the birth rate of everywhere else.', 'Some dialogue voices got switched to incorrect places when devs were making change to the "adult scenes". So you have no choice but to use the "back to adult version" patch, even if you don''t care about nude girls.\nThis is probably the most hilarious thing I''ve ever met.', 'Overwhelmingly Positive', 96.49, 60.63, 22.95);
INSERT INTO reviews VALUES (33537, 1145350, 34660, 'At the start i thought it was worse than the first, now i think its twice as good. How do you make a game twice as good as a 10/10 game ? It''s not even finished...', 'This game was not for me. The grinding for materials that was present in the first installment of the game has been cranked up to eleven. The characters I have encountered so far are not as likeable as they were in Hades. I dont really know why but I have no real interest in "getting to know" the gods like I did in the first game. If that is because of my lack of engagement in the game, or simply the fact that I''m not resonating with any of them. \nMaybe if I give it some more time the characters', 'Overwhelmingly Positive', 96.98, 391.37, 2.85);
INSERT INTO reviews VALUES (33538, 1145360, 130489, 'The best roguelike ever made, hands-down. Hades adds an entirely unique spin on the genre by having every single run enhance and progress everything around you. They enhance the characters, improve relationships, add depth to the history of the world, progress the story, gives you the ability to change and improve the abilities of your character, and modify the aesthetic of your House. The story is great, giving interesting interpretations of the entire Greek Pantheon and many connected mytholog', 'I literally only bought this game because it''s greek mythology, and greek mythology is filled with incest, and they just straight up removed the incest. Super lame.', 'Overwhelmingly Positive', 98.56, 356.70, 6.97);
INSERT INTO reviews VALUES (33541, 1145630, 112, 'It''s easy to grab Beast at full price, see that the UI is a little clunky here and there, be put off by the slightly off wording and voice acting, and refund it quickly...BUT....this is likely why it has so many early poor reviews. Underneath a poor first impression is a solid turn based strategy game with pretty decent graphics and cut-scenes and a story that is, likewise, decent. It honestly does not deserve the level of poor reception it has had and it is an absolute steal at its sale price. ', 'Don''t buy this game. There has been no updates since November 2023. I reached out in the discussion board to see if this was a dead title, since they are everywhere now.\nThe developer responded saying they are working on a second title (Never a good idea when a game isn''t finished) and they were planning on using that funding to finish this title. So they want to use the funding that is supposed to go to the second title, to finish the first title, which will also put the second title a bit behi', 'Mixed', 67.86, 32.92, 24.07);
INSERT INTO reviews VALUES (33544, 1147860, 5531, 'I want shorter games with worse graphics made by people who were paid more to work less and im not joking.', 'just like the classic NES titles they mimic, UFO 50''s games sport level of difficulty that makes an old casual like me want to break down in tears.  i''ve grown soft over the years, and i wasn''t ready.  for real though the games are tough (but fair), so if you aren''t interested in a serious challenge, or willing to bang your head against the wall for hours on end to get anywhere in these games, then this game (collection of games?) might not be for you.', 'Overwhelmingly Positive', 95.75, 29.98, 1.85);
INSERT INTO reviews VALUES (33545, 1147940, 279, 'Best ''new'' way to play old NES games...  Some games you can rotate the screen look at an angle for a true 3D feel like Punchout. \r\n\r\nAll I can say is just get it!', 'Wasnt bad but doesnt support widescreen (Only 4:3) and has about 50-60 games that it works with. If this supported 16:9 and at least a couple hundred games, then it would be worth it. It doesnt even work with SMB2? Its capable with 1 and 3, but not 2.', 'Very Positive', 91.76, 11.17, 0.40);
INSERT INTO reviews VALUES (33550, 1148760, 3287, 'It''s been about a year since I finished my first ending and which also marks a year that I''ve spent searching for games *like* IWATEX to fill that hole that it left and have sadly come up short. I''m in love with... almost everything about this game, from the art, to the setting, to the characters, to the story, just about everything. The part I love most is getting to grow up and watching the other kids grow up and become their own people and navigate the colony alongside me. Awh it''s just genui', 'Refunded before I even got out of character creation.  My dollars don''t support this nonsense.', 'Overwhelmingly Positive', 96.68, 132.27, 0.33);
INSERT INTO reviews VALUES (33551, 1149460, 22601, 'This game is a lot of fun. I am a Gen X mom who plays with my teenager. I love catching the creatures and taming them and then riding them all over. The collaborative game play is really fun because you have to help each other to succeed.\r\n', 'I think everyone should be aware that the developer would rather push out new pricey DLC than fix the bugs in the base game. The bugs that have been there since launch and has been reported over and over.\n\nIt''s a scummy and greedy business model.', 'Mostly Positive', 75.56, 138.53, 27.92);
INSERT INTO reviews VALUES (33552, 1149620, 9666, 'This game is very relaxing and fun for the first 10 hours but then it starts fading. But how the f did i end up with 63 hours you may ask, well i got tricked to do all achievements and. Yea, thinking about selling my pc now. 7/10 great game :)', 'This game is made by a money hungry developer who refuses to fix the constant bugs in their game. The game has major stuttering problems and fps drops which makes it unplayable. Edit: ignore the fake reviews and the bot responses from the dev and their bot army. They''re still money hungry and wont fix the game lmao.', 'Very Positive', 87.83, 63.60, 42.80);
INSERT INTO reviews VALUES (33554, 1150080, 1140, 'I don''t really have too many complaints about crosswave, I just think there''s a lot of wasted potential. They could''ve done some really cool stuff but decided a visual novel was the best way to make it more self-contained. \n\nCall me back when we''re fighting against siren kaijus with the monsters that accompany ironblood characters. \nLiterally some of the coolest design ideas i''ve ever seen and nobody wants to do anything with them. \n\nYostar is sitting on an IP that could have killed hoyo and nex', 'bought this game ages ago, sadly its still trash. graphics are very poor i love my shipgirls and they deserve better', 'Mostly Positive', 75.18, 9.32, 26.60);
INSERT INTO reviews VALUES (33556, 1151340, 38721, 'As a Fallout fan the game is automatically a good start, but I was vastly concerned over the MMO part but turns out I was able to play solo and not interact with others in any way. Almost 800 hours in and only been trolled once.', 'Do not buy this game, as of Nov 13 2024 Zenimax has Updated their terms and service to "You do not own your account or any associated content (e.g., digital assets, user names). ZeniMax reserves the right to restrict or terminate your account for any reason​(ZenimaxTermsOfService)". Among other Terrible terms such as "Any UGC you submit grants ZeniMax a perpetual, worldwide, royalty-free license to use, modify, and distribute your content. This includes a waiver of moral rights, meaning you forf', 'Mostly Positive', 76.94, 911.47, 1540.48);
INSERT INTO reviews VALUES (33561, 1153410, 878, 'Just in the little time that I''ve played I must say that I''m very impressed.   It gives initial D, MF Ghost, and Fast and Furious type vibes.  The music stations are fire. The manga element is amazing. At this time I don''t even care that it doesn''t have multiplayer yet. I''ve been waiting for a game like this for a long time.  You guys delivered!!  I do think you guys should add FSR 3 for us AMD users though! Great work devs!!', 'Yet another example of Unreal Engine taking a massive dump on what could have been a very good game. \nThe driving physics are pretty good, the fact that there are licensed cars is pretty impressive, I love the radio and especially the setting.  \nThe performance however... Is not that good. Running the game at Native is not viable, upscaling and frame generation were enabled by default (at least for me), which to me seems like an attempt to cover up the poor performance. There is no adjustable sh', 'Mostly Positive', 73.92, 3.40, 1.08);
INSERT INTO reviews VALUES (33562, 1153430, 275, '**Love wish** is basically the reason my dignity packed its bags and left. The devs knew exactly what they were doing with this one, bro. I’m clicking through, pretending I care about the "story," but let’s be real, I’m just here for the fanservice. Gameplay? HA, what gameplay? This is straight-up horny jail material disguised as a game, and I’m not even ashamed anymore. Every scene is a one-way ticket to questioning my life choices, but somehow... I CAN’T STOP. Absolute masterpiece of trash, 10', 'Creepy degeneracy. Mash ''T'' repeatedly to complete levels quickly and get the achievements in about 10 minutes.', 'Very Positive', 82.18, 196.72, 5.33);
INSERT INTO reviews VALUES (33572, 1157220, 701, 'It''s a good game, especially if you liked Zeus and Pharaoh. \n\nWhat I like: the cities look good, the ambivalent music is also very decent considering that you''ll be listening to it for dozens of hours, that''s extremely important and they''ve done very well. It also improves on aspects of the old city-builders by allowing you set up custom routes for your peddlers to travel, adding or removing additional sellers. You really hate to return to old games and having to set up roadblocks or else your s', 'Okay game overall, and if you like the genre, this one might give you some chill time for some time. However, not recommended for the ones not familiar with the genre. \r\n\r\nI got stuck in 4th tutorial (hence the low playtime). In this game first 5 missions of the campaign are considered as (are also designed as) tutorial. Problem with 4th tutorial is that some of the game mechanics are locked (that will be introduced in 5th tutorial , probably), results with impossible funding management of the c', 'Mostly Positive', 78.74, 3.42, 5.77);
INSERT INTO reviews VALUES (33574, 1157700, 378, 'I booked Horace Hogan against The Shockmaster in a bras and panties match for the WCW World Heavyweight Championship.', 'Too easy\nMulti man matches = extra star', 'Overwhelmingly Positive', 97.35, 630.25, 2.37);
INSERT INTO reviews VALUES (33575, 1157740, 263, 'The Contra formula is really showing it''s age, and Iron Meat doesn''t attempt to innovate at all - it''s a straight up clone doing nothing these games didn''t over 30 years ago. In fact, it does less - no perspective switches, vehicle sections or any of that. Just walking forward, shooting, and dying  because you didn''t learn the pattern yet. You can''t slide or climb on walls, and aiming is strictly 8-way digital.\n\nBut at least it is fun for a single playthrough, because of the quality pixel art, i', 'Game is far to focus''d on killing the player via random enemy spawning or worse, untested unpolished boss patterns that leave you with 1 second to shoot the boss, and 30 seconds of dodging.  You''ll be battling against your patience more then the boss for 2/3 the fight.', 'Overwhelmingly Positive', 97.34, 1.65, 1.20);
INSERT INTO reviews VALUES (33576, 1158160, 11425, 'I really enjoyed the game up to year two! It''s very relaxing and the addition of a sea level is very cool compared to other games of this genre. However I did the mistake and I adopted a fox as a pet and it keeps making a constant annoying call that  you can''t mute and you can''t un-adopt it. When I say constant, I mean every 3 seconds. I had to uninstall after a few days having her since my relaxing experience became TORTURE. \nJust don''t get Luna guys. Its painful and you can''t do anything about', 'Whilst this game is fun to play I do not recommend it currently as although it was release November 2023 it is now late June 2024 and the game isn''t finished (it isn''t possible to actually complete all the quests, some areas are still not accessible)\nI would consider this a good game if it was still early access, but to release it with out the ability to finish the main game feels bad.', 'Very Positive', 88.84, 114.85, 1189.15);
INSERT INTO reviews VALUES (33577, 1158310, 43679, 'Put bannerlord and total war into this game and I''ll never even need another game.', 'Stop charging so much for DLCs. I want to play this game with my buddies but they see the price tag and they get spooked', 'Very Positive', 91.22, 1318.63, 1024.50);
INSERT INTO reviews VALUES (33579, 1158890, 368, 'It''s okay. The story is a little weird, there''s really no depth or real connection to the character. The last chapter is just confusing Who as the other bird with wings that had the ticket A38?. Graphics, aesthetics, mood of the game all well done. Mechanics are pretty good although little things like some boxes are pull only (you can''t push them), more character control when dropping would be good and a run button!\n\nIt''s not worth £17 that is it on sale for now. I think if you can get this in a', '"White Shadows is a cinematic puzzle-platformer where you play as a little Ravengirl trying to escape a brutal dystopia founded on oppression and violence that puts her at the bottom of its hierarchical social ladder."\n\nThis is it, nothing else happens. No story, no great gameplay piece... just a cinematic puzzle platformer with a backdrop of a dystopia which gets no story arc. It has the depth of a 5 year old''s drawn story. 4 hrs long if you take your time.', 'Very Positive', 81.52, 2.68, 4.05);
INSERT INTO reviews VALUES (33580, 1158940, 1037, 'Nobody will read my review so I Will Eat 1 Tablespoon of ketchup For Every Like this gets.', 'This game is very good, but the developers are not monitoring it. They have ruined the game this way—cheats have become widespread, and it''s impossible to play properly. The gameplay could be great, but as I said, since there''s no supervision, no one wants to play anymore and is quitting the game.', 'Very Positive', 83.99, 12.63, 23.15);
INSERT INTO reviews VALUES (33581, 1159690, 2964, 'You ride a train on a flying track in a dreamworld with flying sharks and deformed goombas fighting off nazi soldiers stealing mushrooms to feed little bald cats to make them work and slave on your train. \r\n\r\nI don''t know what these developpers used as a drug but I need it.', 'Void Train - Like the void, in abstance of content.\n\nStarts out great, then you get so much tedious micromanagement. For example your "crew" consisting of lizards, that experience explosive diarrhea every few minutes: You need to clean up that mess to not lower the morale that bad that they just refuse to work and the guy shooting mines goes on a break and half of you train needs repairs.\n\nDevs should try to focus on some parts of the game and refine them, but not in all directions and effective', 'Mostly Positive', 75.57, 5.88, 9.88);
INSERT INTO reviews VALUES (33582, 1160330, 201, 'This game is very fun because of the mechanics and is very fun with friends. This game is PEAK FICTION though, I need an anime or movie with my boy Muscle beluga kicking ass and the rest of the cast fighting. Should be at every EVO. 100/10', 'Bruh, Idek if this game is good or not, I just got my ass handed to me and am malding rn.', 'Overwhelmingly Positive', 97.01, 7.05, 3.45);
INSERT INTO reviews VALUES (33583, 1160360, 176, 'very bad', '... Who makes a platformer where pressing down/up on the left analog stick completely stops the character? Then thinks it''s a good idea...', 'Mixed', 56.82, 44.68, 0.33);
INSERT INTO reviews VALUES (33584, 1161830, 119, 'So i have currently played about 50 hours of this game, so is this game fun?\r\nWell yes it is and if you liked Blackthorn arena you will probably like this game. \r\nIs the game buggy as of me writing this post, yes it most certanly is, but if you played alot of BtA you are probably pretty used to all the bugs and wonk from this dev. Would i recomend buying this game? \r\nWell that depends on how frustrated you get of buggy games, i personaly have 3 characters that i cant continue playing with since ', 'This is my last edit to this review as I promised I would review the game even though it changed direction into something I wouldn''t like.  This is not a paid review like so many of the rest, and the end is this game is complete trash.  The developers can be seen contradicting themselves over and over just check the different older threads where they claimed to have fixed bugs that are still 100% present in the current version.  Go look at their other products and how they used the same material', 'Mostly Positive', 73.95, 115.12, 131.35);
INSERT INTO reviews VALUES (33587, 1162520, 239, '外挂 作弊的太多了，都成团伙了， 就不能修正吗', 'a  waste of time  terrible game memory and do not buy it\nI can not figure out why this game so unfair and destory my patience', 'Mixed', 58.58, 3553.97, 2.10);
INSERT INTO reviews VALUES (33589, 1162750, 4222, 'The "unlimited demo" is actually just the full game version or two behind the current live build.\nTry away!', 'Very sad to be posting my review for this game as negative. I bought this game, needing an alternative to Rimworld and my problems with it and something more to my preference. I binged it for like 12 hours immediately. I thought I found the holy grail here. Colony sim/city-builder on a scale that felt like it could actually reflect the difference between and formation of vilalge, towns, kingdoms, and empires; in a lot of ways Songs of Syx really is that. I felt like I was tripping because after ', 'Overwhelmingly Positive', 96.07, 99.07, 11.97);
INSERT INTO reviews VALUES (33590, 1162960, 481, 'I wanted to write a detailed review but unfortunately it''s 5:40 right now and I need to watch the kids AT 5:40.', 'Does not have the swear death screens on the first game.', 'Overwhelmingly Positive', 95.63, 0.50, 0.87);
INSERT INTO reviews VALUES (33593, 1166860, 2949, 'I bought this game after playing the mobile version. I enjoy the PC version much more, since there are no micro-transactions or subscriptions. I love the racing, the breeding, the training, and the goal/leveling system. I do wish that there was a way to connect with friends in the game, but that''s my only gripe.', 'please start bringing the new updates to PC as well, having to wait months just to see some change is unfair. we understand mobile brings in revenue but PC needs to be kept up-to-date as well because it has become boring, and i feel like if it was updated as frequently there would be more buyers interested.', 'Very Positive', 94.24, 67.77, 24.70);
INSERT INTO reviews VALUES (33594, 1167450, 2169, 'It ain''t Armored Core 6, but it''s Armored Core less than 6. I had fun.', 'Slapping robots silly with broadswords the size of buses should be a guaranteed good time, but having to stomach a plot and dialogue that makes bad anime look like slightly less bad anime leaves DXM hard to recommend at best.', 'Very Positive', 82.90, 14.42, 31.27);
INSERT INTO reviews VALUES (33595, 1167630, 64907, 'I feel the realism in this game. When a fire breaks out in the game, my Steam Deck also starts burning in my hands. 10/10', 'Purchased the game, was an amazing game for the first year, then was hit with an EULA terms of service after a couple of DLC''s arrived. The EULA essentially states that the game I purchased with my hard-earned money is somehow now NOT mine, and Tuxedo Labs can terminate my access to this single-player game at their whim. How is this not theft?', 'Overwhelmingly Positive', 95.44, 29.42, 70.20);
INSERT INTO reviews VALUES (33604, 1172380, 76798, 'The game is good, but there''s quite a few things that prevent it from being great. If you like constant backtracking and puzzles that make no sense, while also having a super simple solution, this game is for you. The problem is that tons of area''s are locked on different planets, and you have to play several hours of the game in order to get a skill to go back and unlock the areas.... without a fast travel system.. So you end up going through the same areas like 10 times, and its straight up bo', 'The EA App is the worst thing I have every had the displeasure of touching. This horrendous creation makes launching the game a nightmare as it doesn''t work half the time. Additionally, do you like how your in-game notifications are set up in Steam? Well TOO BAD, this app COMPLETELY IGNORES THEM and doesn''t have half as many options! Don''t want achievement popups in the middle of playing a game? Screw you, you can''t turn them off! Wanna disable in EA overlay? NOPE! Not allowed unless you launche', 'Very Positive', 89.05, 23.98, 17.00);
INSERT INTO reviews VALUES (33605, 1172470, 1017, 'less lesbians plz', 'Game is actually broken now in season 22. This is the absolute worst one that has ever dropped and I seriously might have to uninstall now after playing sense season 0. Download this game right now if you want depression/uncontrollable bursts of anger', 'Mostly Positive', 79.94, 9.43, 1013.22);
INSERT INTO reviews VALUES (33606, 1172710, 10068, 'Very immersive game. you can cook a well-done steak on your GPU while you play and the hot blasts of air from your PC fans truly make you feel like you are in the desert. keep a bag of sand by your desk and periodically toss handfuls of it into the air to really complete the experience :)', 'Not really for me.  I get survival crafters require a bit of time investment to really get going, but 2 hours in as an adult with a full time job, I still hadn''t done a single "fun" activity. This wasn''t true for other similar games likes Valheim or Palworld. I''m sure this game will be amazing for at least some people, but for me it took too long to take off for it to be worth it. There are other games that are more fun sooner for me to play since I only have so much time.', 'Very Positive', 89.95, 2.07, 2.25);
INSERT INTO reviews VALUES (33615, 1176470, 4383, 'This is a game with a built-in goldfish filter. Do not attempt to play unless you really like trains, have an adderall prescription, or have trouble speaking with women. Great game tho 10/10', 'I love this game, but it feels like it becomes less engaging, less accessible, and less fair with every patch. Too much of the game''s strategic depth has been removed by the repeated nerfs to successful strategies.\n\nAn appeal to Pavonis: difficulty is not inherently good. The challenge is part of why I''m playing your game, but when you continually remove player agency and don''t replace it with anything interesting, the game doesn''t become better by virtue of being harder. It just becomes less in', 'Very Positive', 81.77, 102.17, 1011.78);
INSERT INTO reviews VALUES (33618, 1178790, 199, 'Almost didn''t buy because of ppl complaining about item loss on death. It does suck, but this game is so good its worth dealing with.\n\nWhen you get past the first 3 towers it allows for item tagging that you can restore items on loss. The game punishes you for failing but if you stick past the first 3 towers it eases up and gives you "insurance" to get your items back. Also if you just play it safe with the right revive items you get from the point shop that you can easily afford every run, you ', 'No. I''m going to be the dissenting voice here.\n\nThis is not a good game. It would have been good in 1994 but not for a game released in 2010. \n\nWhy did this series not bother with any quality of life updates whatsoever? Navigating every menu, using any item, equipping anything, managing your items, learning what your items do, or comparing equipment - it''s all trash. You''re going to be putting items in jars, breaking jars, storing items, and swapping items, and often times you''ll have no idea wh', 'Mostly Positive', 79.90, 49.32, 8.43);
INSERT INTO reviews VALUES (33620, 1179890, 100, 'Very bizarre and awesome game, highly recommend watching the documentary about the creator for more context.', '', 'Overwhelmingly Positive', 100.00, 4.32, 0.00);
INSERT INTO reviews VALUES (33621, 1180250, 121, 'Divination is a focused experience that gives you one story with a few twists and turns and a clever fortune-telling mechanic. \n\nThe first time you play through you may think the game is very short, but it''s just getting started. The structure used here is clever, and the divination plays into that very well.\n\nOn the downside, I think that the game doesn''t do much to guide you towards the ending it wants. Right answers get a little feedback, but it''s not clear what it means, and wrong answers si', 'This game is pro AI slop', 'Very Positive', 89.26, 0.97, 0.52);
INSERT INTO reviews VALUES (33631, 1184250, 107, 'First thing you experience is a long winded boring ass speech from some random boomer officer that takes too long. Too accurate of a simulator, 60/10 would rather be a conscript again.', 'Viimeisin päivitys hyvin suureksi osaksi pelkkää copy pastea. Joissain tapauksissa jopa Suhakka huutaa tuvassa huomio, vaikka ei olekkaan enää koko tuvassa. Pyörällä jos osut seinään niin se uppoaa maanrakoon yhtäkkiä. Vielä niin keskeneräinen peli etten ainakaan tässä vaiheessa voi suositella.', 'Mostly Positive', 79.44, 1.53, 73.65);
INSERT INTO reviews VALUES (33632, 1184370, 16473, 'Played BG1-3, NWN1/2, and other rpgs and this was by far the most bloated in terms of complexity without improvement. Just too many options, feats, classes, modifiers, way too many gd buffs to keep track of and cast. Asking a lot of the player to manage a 6 character party in such a mess of a system. Realized I''m not a fan of pathfinder 1E after playing this.\nDespite all that, I did have fun and enjoy the story until getting burned out of the buff mania late campaign. Got my money''s worth so tha', 'This is a tough one to assign a recommendation for or against to because it comes so heavily down to person choice. For what it is, the game is well made with heaps of content and customization options for the min-maxers out there. The game''s difficulty settings are extremely detailed and provide the opportunity to tailor the experience to your own skill level and interest in engaging with the game''s systems.\r\n\r\nWhere the game falls flat, for me, is more connected to it being based on Pathfinder', 'Very Positive', 82.21, 252.02, 77.35);
INSERT INTO reviews VALUES (33633, 1184560, 124, 'I’m a simple man, I see Kurisu Makise I buy this game.\r\n', 'This is the first fighting game with buffer where buffering an input makes it NOT come out.', 'Mostly Positive', 72.58, 1.18, 1.03);
INSERT INTO reviews VALUES (33634, 1184990, 108, 'cool game, fun combat, pretty unique. 100% recommended', 'No depth and clunky, unresponsive combat.\n\nAfter my 20 time getting surrounded and stun locked, I give up. This isn''t fun.', 'Very Positive', 87.96, 3.72, 1.15);
INSERT INTO reviews VALUES (33638, 1188250, 122, 'I saw this game on a youtuber''s "100 for $1" list - this was only one of three games recommended, so despite not liking first person horror, I thought I''d give it a shot.  It''s not bad - certainly better than the price tag implies.  If you are looking at it and deciding if this is worth a candy bar, the answer is yes.', '2/10 the game was crashing every time i was going to play', 'Very Positive', 88.52, 0.38, 0.43);
INSERT INTO reviews VALUES (33639, 1188930, 2260, 'For those who wonder what is the recent drama of this game:\nThe recent game updates have broken a large amount of mods. One of the devs argued with mod creators in Chinese community, continued ignoring their opinions, and finally muted the mod creators (one of them is also the founder of the Workshop support of this game, as acknowledged in the contribution list of the game). As a result, a few mod creators left the community and deleted their mods. You can see the devs'' apology message in the m', 'Dev''s update killed the mod that i need to enjoy this game(tho someone did reupload the mod), some said that the devs don''t get along well with the mod creators.\n \nDunno what were the devs thinking, you literally got free content from those 3rd party developers, and now you make them stop updating their contents and left.\n\nWell done devs.', 'Very Positive', 94.16, 1535.60, 50.63);
INSERT INTO reviews VALUES (33640, 1189100, 100, 'Bought this one as a guilty purchase, because I had a craving for warlord era China content. I have an unhealthy fascination with that time period and I thought that a game about it could do me no harm.\n\nBoy, was I wrong.\n\nA 100 hours later in and now not only is my obsession growing, I can''t get enough. The game is so much better than it seems that it''s uncanny. It dragged me in for weeks and now I must have more. It''s grip on my mind is worrying. I am now as loyal as Feng Yuxiang, as noble as ', 'While I can see why others like it, I have tried to like it and it isn''t really my cup of tea. I only kept trying to play as I was over the 2 hr mark for a refund when I landed on that decision.', 'Very Positive', 92.00, 147.68, 10.65);
INSERT INTO reviews VALUES (33641, 1189230, 200, 'Cool its very grounded gives me "could i survive a zombie outbreak" plus horrors beyond human minds.\r\nstay away from vampires. and don''t trust dogs they don''t love you.', 'i dont think the dev realises that, he can have his short and intense, die at the end, without being lazy and not implementing a save system. truthfully, i would not have refunded this if it was at all able to be saved. load in, die, thats fun.\nload in, get good progress, bunker up and start to think of a plan to escape this awful place, have to go for irl stuff, cant save, and my pc is a potato, which is why i play ascii games, but i cant save, minimizing will just slow down my computer.\n\ndo be', 'Mostly Positive', 76.50, 5.27, 0.38);
INSERT INTO reviews VALUES (33642, 1190000, 13829, 'I went from zero knowledge of cars to a knowledge that would impress someone with zero knowledge of cars.', 'i thought this game was actually a realistic game. being that it had simulator in the name but its not don''t get me wrong its close but very far at the same time there''s a lot that goes into fixing a car and this is not it. in the game there was a certain job that i did and it involve removing a timing belt it didn''t even require timing the engine too make the car run properly we basically just slapped the parts in and called it a day. what if a person decided to use this game as a reference to ', 'Overwhelmingly Positive', 95.88, 74.72, 2.30);
INSERT INTO reviews VALUES (33643, 1190970, 6669, 'I cannot recommend this game enough. Had a hard day? House Flipper 2. Want to have something to do while listening to an audio book? House Flipper 2. Depressed about how you''re a millennial that won''t be able to own a house in their lifetime because we''re in the end stages of capitalism and can''t even afford groceries or basic necessities, much less a HOUSE payment? House Flipper 2. It''s my favorite game and I could not be more serious. Endless jobs and houses with the community made content too', 'LOVED house flipper. But house flipper 2? HATED it. With only 14 hours, and 2ish days to really play, I beat the story mode, which was incredibly disappointing. You don''t install things anymore, which was actually enjoyable for me. You just place everything. THE PAINTING SYSTEM SUCKS SO HARD!!!!!!!! I hate it soooo much. Basically anything I really liked from the first game is gone. And the things I hate the most about this game are constant or in every single mission. I also waited a hot minute', 'Very Positive', 83.69, 1206.60, 13.98);
INSERT INTO reviews VALUES (33646, 1191580, 892, 'Nexomon, what is basically Pokemon. It was pretty fun not gonna lie. The Nexomon''s are kinda forgetable, but a few are not (Looking at you Carnagrius). The gameplay well, it''s what the older Pokemon games are like top-down view, you fight and catch Nexomon, you fight trainers and bad peeps, as you progress through the game, pretty simplistic. And as most people who played these type of games, I did not use any "Power-up" moves that would raise your ATK or DEF or whatever. 99% of the time you jus', 'Vollyball killed this game for me. here''s a overly quick timing mini game that blocks progression in a turn based game, possibly the stupidest choice I''ve ever seen in a game ever.', 'Very Positive', 88.23, 32.35, 25.23);
INSERT INTO reviews VALUES (33647, 1191630, 748, 'the game has tumblr-esque dialogue, gooner character designs, 1000 healing items that make you immortal, and weird voice acting\nso basically its just the average shantae game. 8/10 i didn''t like the card system + no ammo baron (the worst part of the game honestly)', 'If I could give this a thumbs sideways, I would. Played every game in the Shantae series and while this is probably the second best, it''s leagues behind Pirate''s Curse, still. It''s cute, but the gameplay itself is just so pedestrian and obnoxious, with dumb level design and ability decisions smoothed over with Skyrim-esque levels of consumable items shoved in your pockets. Drilled through this game in two days while listening to podcast episodes, and I wouldn''t have finished it without them. Bar', 'Very Positive', 90.78, 10.37, 17.10);
INSERT INTO reviews VALUES (33648, 1191660, 145, 'Good metroidvania, with an unfortunate soulslike feature of losing shit when you die and it becomes EXTREMELY frustrating.  It just doesn''t make sense at all in this application.  Wish devs would stop forcing that in metroidvanias.\n\nSteam, please let there be a neutral review option.  I feel bad giving a negative review to someone that poured their heart and soul into something like this.', 'Dev ruined what would have been otherwise a great metroidvania. I actually started to really enjoy the exploration and gameplay. But losing cores which is your max health on death is just really stupid for no reason. And then after you reach minimum cores you start to lose half your money each time. Like did people that design metroidvanias not play Super Metroid. The only penalty was you had to restart at your last save which is penalty enough. Losing time (which is our most valuable resource w', 'Mostly Positive', 73.79, 1.70, 3.12);
INSERT INTO reviews VALUES (33651, 1192380, 140, 'Baseball Been Berry Berry Good to Me', 'Pitching and fielding in this game is fun, it is very satisfying to catch a ball after it''s been hit in the outfield. However, batting in this game is terrible. It is almost impossible to get a run, even on the easier difficulties and with high assistance. It''s either caught out or immediately thrown to first base. The devs should make it harder to catch the ball, like adding a chance to drop the ball', 'Very Positive', 87.14, 1.68, 6.33);
INSERT INTO reviews VALUES (33652, 1192440, 187, 'Finally! I can create and breed plus design my ex wife and her mother. Thank You Developers, now im truly a Wizard.', 'I really wanted to enjoy Monster Breeder, but it just doesn’t deliver — especially not at its current price point.\n\nThe graphics are unsatisfactory, and the monster designs come off more as randomized messes than anything genuinely creative or appealing. Instead of being excited to see what new creature I could breed, I found myself actively disappointed — nothing looked cool, just grotesque in a way that wasn’t interesting or fun.\n\nCombat is barebones, and while the breeding mechanics are detai', 'Very Positive', 94.65, 0.35, 16.95);
INSERT INTO reviews VALUES (33653, 1192900, 491, 'Good vr game.  Feels like Hawken.  Aiming with your arm feels good.   Controls are easy, I just wish there were more complicated/cool things we could do in the cockpit.', 'The game had an "overwhelmingly positive" score when I bought it, but it turns out that was mostly just people hoping the game sticks around and gets more stuff added to it. I''m hoping that in the future I can come back and edit my review to positive, but as of now I really can''t recommend this game (and I''m kind of upset that the other reviews misled me into buying it).\n\nThe videos I saw led me to believe that I was getting something akin to vtol vr but with mechs. Unfortunately for this game, ', 'Very Positive', 85.13, 6.33, 0.83);
INSERT INTO reviews VALUES (33655, 1193340, 426, 'its a good game, was review bombed due to being abandoned, turns out things went to shit at hq or what not. They are slowly rebuilding the game and gonna release a update soon it seems.\r\n\r\nIts a really good game, and i could only imagine what this game will turn it to. Its been rocky for sure. The game is fun for awhile good time sink for 15-25 hours, and if you enjoy it a bunch easily 50 or so hours of gameplay here. Thanks for ready uhh huh yeah bye ig', 'DON''T BUY! The game is still "early access" however the developers haven''t released an update for years and clearly don''t have the intention to continue working on this game. Steam should remove this from the store, selling a game as "early access" when you''re not planning to ever finish it is a scam in my opinion.', 'Mixed', 62.68, 13.72, 0.30);
INSERT INTO reviews VALUES (33658, 1195560, 232, 'Would you like to play a base building survival game with third person and a top view. Then this is for you. The game is still in early access and has a ways to go. But the potential here is excellent. buy a copy and help our developer friend continue their quest. I will not say wait until later, that is not how we help games develop. Join in and provide feed back in the forums help this game grow. To developer: Excellent work so far keep going. Custom building pieces and decorations are needed ', 'Concept: I actually really like the whole concept of the game. There''s 3 different modes: Adventure, Survival, and War. The first 2 are pretty similar. Adventure you start in a town and you wander off, Survival you start with nothing. War is a quick objective based game. First to beat up a camp wins. Its a pretty cool idea. You can build your own villages and buy lands to trade and defend. You can train defense guards and what not. I love the idea. \r\n\r\nTutorial: This is where it starts getting w', 'Mostly Positive', 74.14, 847.32, 22.15);
INSERT INTO reviews VALUES (33659, 1196310, 521, 'I''ve had countless hours on this game \r\nPreparing my campaign, having fun with my friends, adding new content or new rules to my current pathfinder campaign I really love this, it''s less stuffy to play my game when going to my friend or even staying at home :)\r\nI recommend it :)', 'for full functionality, buy a subscription... buy an upgrade to an improved license... buy this, and this and that', 'Very Positive', 80.04, 12013.70, 0.30);
INSERT INTO reviews VALUES (33666, 1198730, 319, 'paras peli ikinä. pelään joka päivä tätä peliä.', 'ᅠ', 'Very Positive', 80.25, 2.50, 7.23);
INSERT INTO reviews VALUES (33667, 1198740, 130, 'Good fun for the price played and time it took to get 100%. And once you get the main missions finished on hard everything you build turns to gold?! heck yeah :)', 'Cons:\n- Enemy units don''t follow the route. Instead, some of them fly directly to your base and attack it.\n- Enemy seems to easily destroy towers blocking the shortest route.\n- Difficult to define a route for the enemy to take.\n- A lot of micromanagement is required.\n- The difficulty and number of available units/upgrades ramp up too quickly. It''s not possible to purchase everything with the money allocated, and it''s unclear which ones to choose.\n - Selection and deselection of units are not int', 'Very Positive', 90.77, 26.22, 2.88);
INSERT INTO reviews VALUES (33677, 1199030, 3974, 'The only card game i had was hand of fate which i enjoyed.I saw this on sale thought I would try it.Glad that I did old saying could not put it down.Have looked at some other card games they do not come up to this.\nI am 76 yrs old so their are others out there that could write a better review.but lets say I am hooked on this and can wait for the second part.\n', 'In most roguelikes, some bonuses and unlocked paths will stay between runs, but all in-run quests generally reset, allowing you to do them over choosing differently.  Not so with Tainted Grail.  There are npcs who if you chose the wrong diialog the first time you meet them, will be permanently hostile on all future runs, locking you permanently out of questlines or services for all runs (unless you give all your progress entirely by starting a new save).  Basically forcing the player to look up ', 'Very Positive', 89.76, 4.03, 158.58);
INSERT INTO reviews VALUES (33726, 1200330, 147, 'Great Game!', 'I can''t in sound mind recommend this game.\nI really wanted to, and I''ve played it a reasonable amount, but the voice acting is so, so terrible. You have some very, very American sounding people very enthusiastically reading corny German dialogue. Every unit has an equally ridicious action and selection voice which is equally jarring.\n\nThen the first line of the store page is;\n"The game is created with great care and attention to historical details by a team that is passionate about WW2 history. ', 'Very Positive', 81.63, 8.15, 98.47);
INSERT INTO reviews VALUES (33741, 1200710, 102, 'Servers are as dead as disco. I played on the most populated one that had seven players. Fortunately a friend bought it at the same time so it was a bit more fun.\n\nAt the moment the game is basically just waiting to earn enough money from passive income to buy a money printer, you then print more money to buy more money printers until you have enough to buy high end money printers which will print enough money to buy more money printers and eventually guns and cars. \n\nAfter we made enough money ', 'garbage abandoned trash', 'Mixed', 69.61, 2.35, 0.38);
INSERT INTO reviews VALUES (33742, 1200730, 181, 'One of my favorite NSFW games on steam. Super solid kart racer, great cast of characters, plenty to unlock. I have no complaints!!', 'some achievements are locked behind cosmetics only available in seasonal events', 'Very Positive', 87.29, 23.15, 86.10);
INSERT INTO reviews VALUES (33758, 1201230, 795, 'Oh gosh, this game is SUPER fun! I have been loving it so far, and there''s still so much to do after 150 hours of playing, haha. I love how unique and quirky the characters are, the aesthetics, the banquet/cooking mechanics, and unlocking everything. \n\nOne great thing about this game that sets it apart is it removes the tedium from similar games in the genre. The  watering/planting mechanics are fun instead of boring, the storage system is satisfying instead of frustrating, and I can mass sell i', 'No. They scrapped the marriage system after claiming they would do it during early access for a lame roommate system.  If i didn''t feel like i got burned for buying it during early access i''d probably recommend it to someone who doesn''t care about romance', 'Very Positive', 91.07, 172.93, 14.07);
INSERT INTO reviews VALUES (33762, 1201270, 3685, 'Already at "time to play single-player game rather than the competitive one" phase. 10/10', 'It might have a good story. But it has a very bad gameplay loop.\r\nIt''s in essence "fetch quests" the game. Now also featuring lots of backktracking!\r\n\r\nWhen I got the umpteenth go to A > go to B > go to A > go to B loop in chapter three I just couldn''t anymore.', 'Overwhelmingly Positive', 98.72, 14.70, 3.12);
INSERT INTO reviews VALUES (33776, 1201540, 1391, 'This game is just awesome, even better with friends!\r\nThe art style is fun and clean. The game play is interesting and each play through you can try new ways to win!', 'I really love the idea, but the content for a singleplayer gameplay is too low, will try again when I can convince some nerds to play with me\n\nFun but the requirements to enjoy the game as it''s worth is too high.\n\n- the main selling point is its a party coop game, beside that the game offers low replayability with around 1:20 hours minimum per session, which is really long\n- online matchmaking is dead, meaning we need exactly a party of 3 for a balanced gameplay\n- even when on sale, the price is', 'Very Positive', 89.50, 67.68, 0.75);
INSERT INTO reviews VALUES (33777, 1201550, 185, 'I played this game with friends. The puzzles are fair, not too challenging. 😎 But it''s a bit short, with 3 chapters only. The game can be finished within 2 hours. I used a bit time to complete all the achievements. (Speedrun for chapter 3 is quite challenging) Recommend to buy it when it''s on sale, as the gameplay is short.', 'The puzzles make no logical sense, and the "story" is nonsensical unrelated rooms barely tied together with bizarre voice acting. I feel like I''ve lost braincells for having played this. This hardly counts as a puzzle game, much less an ''escape'' room one. \n', 'Mostly Positive', 70.27, 2.48, 2.03);
INSERT INTO reviews VALUES (33779, 1201630, 193, 'This game put me through a lot. At first I really wanted to put a bad review, but I realized, its not about that, you have to look at the good. This is a game that tests your anger and how far you can go. I was gonna rage quit, but I GOT TO LEVEL 2, AFTER WORKING HARD. Maybe i didnt beat the rest 90% of the game, but i got to level 2. W''s IN THE CHAT!', 'I''ve seen hell and this game was there.', 'Mostly Positive', 79.27, 0.28, 0.98);
INSERT INTO reviews VALUES (33789, 1201830, 345, 'You know, after waffling on this game for years due to all of the negative reviews, I picked it up on sale.  I''d been following it for a long time, because it hits a lot of spots for me in terms of gameplay and science fiction setting, but I''d been worried about wasting my time and money.  I don''t know if I was right back then, but I my experience has been mostly positive since I began playing a few days ago.\r\n\r\nThere''s been a few bugs, most notably the one where I ended up getting stuck due to ', '"You found a bunch of worthless junk!" - my game freezes. This proceeds to happen 9 times out of 10. Which generally requires a restart OR sometimes if I''m lucky, I can return to the main menu and load a continue.  FTW has been out for years and still has ridiculous bugs in it. Buy on discount or not at all. Massive Galaxy Studios, FIX YOUR DAMN GAME!', 'Mostly Positive', 73.04, 16.83, 2.15);
INSERT INTO reviews VALUES (33790, 1201840, 136, 'I don''t think most people will get the reference, but as soon as I heard the main menu music, I had to laugh. It''s literally the Amazon Flex training video music. Bless Kojimbo for his brilliance in this little Easter egg. A fun game with an unexpected, hilarious touch for those who catch the reference!', 'Not a Hideo Kojima Game', 'Very Positive', 86.76, 3.35, 3.73);
INSERT INTO reviews VALUES (33804, 1202130, 5255, 'The game''s main campaign mode is up there next to Company of Heroes 1 & StarCraft II campaign for me in terms of how much fun it is. There aren''t many RTS games with good campaign and Starship Troopers is a breath of fresh air after so many years.', 'The game itself has potential but where it falls down is how outdated the game design feels and the AI control over your units. It harkens back to an era of micromanagement of unit abilities which we really should have moved beyond. I don''t find it personally enjoyable to have to babysit my infantry units telling them when to use their grenades or other such basic combat abilities. Realistically that sort of micromanagement should be toggleable or in cases where it''s not limited by resource but ', 'Very Positive', 88.30, 11.77, 4.10);
INSERT INTO reviews VALUES (33809, 1202200, 1417, 'A casual, simple, adorable little farming sim with dinosaurs. I like dinosaurs. Highly recommend to anybody who just wants a feel-good game without a lot of brainpower or focus needed to really enjoy it and have a great time. Did I mention the dinosaurs are the most adorable things I''ve ever seen? No? The dinosaurs are the most adorable things I''ve ever seen. :)', 'wouldn''t really recommend the game to anyone at the moment, you''d be so much better off going to play minecraft modded or solo ark or something. the devs are pretty obsessed with making merch (mid) that barely get any sales, they seem to be putting effort into everything outside of the game to make money. recently decided they needed VIP roles for discord where you get a mystery item (they don''t tell you what it is or anything else and it''s just ONE item) and a special discord role like?? just f', 'Very Positive', 86.73, 49.12, 60.38);
INSERT INTO reviews VALUES (33815, 1202310, 265, 'The first in a franchise that lit the hearts of millions of fans across the nation. So many things to love. The characters, the plot, the porn, the sex, the artwork of the sex, the sexy naked women, the sex again, the art style when they are having sex. 18+ patch required. PORN IS LIFE!', 'worst one in the series', 'Very Positive', 83.02, 20.72, 331.78);
INSERT INTO reviews VALUES (33827, 1202540, 443, 'Superb art combined with stellar performances combined with "what on earth did I just read" make this visual novel a fun read.', 'Animation and voice acting is top notch. But the story man. Its just ridiculous. Good luck finding an accurate description of the entire storyline because your brain will melt from stupidity.', 'Very Positive', 94.36, 8.33, 2.92);
INSERT INTO reviews VALUES (33837, 1202690, 1363, 'No one is Going to read this review so i want to confess that i am gay .\n', 'May god protect us all\n', 'Mostly Positive', 74.61, 0.35, 1.50);
INSERT INTO reviews VALUES (33849, 1202900, 4030, 'Very short, very endearing puzzle game of light-medium difficulty (depending on your familiarity with the objects I suppose) about repairing broken objects and broken parts of relationships. \n\nI like that it encourages taking a look  inward  to make amends with people in your life rather than focusing on how other people are behaving or what you perceived  them  to do to  you . It''s that whole locus of control thing. \n\nThe manipulation of the objects can be a little fiddly and I would guess keyb', 'This game is pretty mediocre. The graphics are nice, but the game play is not great.\nMy most pressing issue is that the game is too focused on the story. I''d say the advertising for the game is misleading in this sense. I''m pretty sure I spent more time listening to dialogue than doing repairs. It''s not very well written and the story is pretty shallow. \nUnfortunately, the repair part of the game is also underwhelming. There is not much variation when it comes to mechanics, leading to the game p', 'Very Positive', 90.74, 1.77, 1.55);
INSERT INTO reviews VALUES (33856, 1203180, 532, 'Its a really interesting game, the water physics are fun and interesting to play around with. However I have no idea what this game is doing to my GPU.\r\n\r\nThe GPU load is about 40-50 (Which is fair), but the temp skyrockets above 60 degrees in less than 20 minutes, not to mention the GPU load goes to 100% sometimes when the game is on the pause screen.\r\n\r\nThis isnt anything dangerous, just odd, since a lot of other games dont give my RTX 3080 any issues like this. But again, its not anything dan', 'Literally downloaded and tried this game for myself since I really loved the water dynamics, the perceived battle mechanics, and crafting. Realized very quickly that all of the comments about GPU and fan speeds being destroyed are SPOT ON. There is no optimization for this game. The combat is horrible, the mouse feels like a rubber band. The water is great but the fluidity is waaaay too overbearing at times. The crafting is actually so short and rough to get around that I felt like I didn''t have', 'Mixed', 69.36, 12.70, 1.35);
INSERT INTO reviews VALUES (33857, 1203220, 12854, '- Stunning Character Design & Fashion (One of the best)\n- Character Control Depth and Skill Ceiling is VERY HIGH\n- Single Player PVE Mode is Great. I stop playing Nioh to Play this Showdown Mode instead\n', 'This game used to be great, but now it feels overrun with hackers—about 90% of the player base seems to be using cheats. As a top 500 player, I can confirm that this battle royale game has significant issues with internet connectivity, hacking, and numerous other problems that have remained unresolved for over three years.\r\n\r\nLike many companies, the focus seems to be on profit, but it''s difficult to see how they expect to make money when they aren’t addressing core issues. Another major problem', 'Very Positive', 81.87, 408.20, 1339.87);
INSERT INTO reviews VALUES (33863, 1203360, 249, 'Idk where 14 hours came from but this is fun and addicting, great to play while watching a YT documentary.', 'Barely worth the name "tower defense" and quite expensive for what it offers as wel. It can provide some simple casual fun I guess but there are many more better games.', 'Mostly Positive', 76.71, 15.98, 1.37);
INSERT INTO reviews VALUES (33867, 1203420, 472, 'For every like I get, I''ll put a banana in my ass.', 'RNG is absolutely abysmal on these', 'Very Positive', 89.41, 18.32, 0.73);
INSERT INTO reviews VALUES (33878, 1203620, 36798, 'Overall is a fun game to play.\nHowever, there is no pause function in single player. Developer should consider add in this feature as some of us are parents and need to attend our kids', 'Honestly, the game is pretty, and its pretty enjoyable at first. but for me personally it felt like combat wasn''t satisfactory enough for me and eventually killed my interest. I''m saying this after re-downloading it 5 times trying to give it more chances.', 'Very Positive', 87.77, 19.55, 10.83);
INSERT INTO reviews VALUES (33879, 1203630, 2797, 'This is not like Symphony of the Night. It looks similar and has similar base mechanics but you will not have a nice relaxing time with this one.\r\nIf you have fast reflexes and enjoy platformers, then this is for you. The main gameplay mechanic is switching between elements on the fly and getting hit will severely reduce your attack power - until you build it up again by hitting enemies with the opposite element.\r\nOnce again - THIS IS NOT LIKE SYMPHONY OF THE NIGHT.\r\nIt''s a good game that a lot ', 'Very generic SNES style action platformer. I would not describe this as a metroidvania. There''s not much exploration and the path you''re expected to take is plainly laid out for you. Fighting was clunky, although the wind/fire ability you could swap between adds a unique element.\r\n\r\nI also had no idea what was going on with the story the entire time. Perhaps it would have made more sense had I watched the show, but I had not.', 'Very Positive', 93.89, 5.33, 10.10);
INSERT INTO reviews VALUES (33883, 1203710, 765, 'It''s like playing a lost version of a Metal Gear game from the Sega CD era, if that was a thing back then. Great fun.', 'A very unfunny game that thinks it''s such a riot you need to sit through 10 minute joke laden exposition every 20 seconds, with bosses that are borderline impossible and gameplay that is otherwise essentially braindead. A very, VERY poor spoof of Metal Gear.', 'Very Positive', 91.50, 16.47, 0.95);
INSERT INTO reviews VALUES (33895, 1203930, 550, 'game lasted 9 minutes, already found bugs, and terrible mechanics. \nFor the love of god avoid with game', 'it was fun in the beginning but has been abandoned. do not purchase.', 'Mixed', 60.36, 0.15, 773.90);
INSERT INTO reviews VALUES (33934, 1204720, 118, 'I thought this game was funny. I am not sure who Yang is bet it was a cool eye opener. I might check him out now.', 'Cringe fest shitty "fighting game" that gets outclassed by Street Fighter 1. Still more of a Fighting game than smash', 'Very Positive', 88.98, 3.50, 0.25);
INSERT INTO reviews VALUES (33955, 1205040, 599, 'this game only requires 3 controls. The mouse,the keyboard and alt + f4', 'I''d give this game a "mixed" if I could, however this game has grown on me significantly. It is a decent sequel to the first game, however the map really isn''t made for 2 enemies. Areas like the kitchen offer no escape if they''re coming from both sides, and even then, areas like the bathroom are a complete death trap, since the only form of escape in that room is a shower that doesn''t work against Granny.\n\nEdit: yeah no lol this map is terrible. The map can barely fit 1 enemy, let alone 2.', 'Overwhelmingly Positive', 95.33, 25.75, 5.27);
INSERT INTO reviews VALUES (33961, 1205170, 103, 'I got this game recommended by steam, I tried the demo and loved it. Then I bought the full game, and loved it as well. \nI was already quite satisfied with the initial magnet mechanics, which feel very rewarding when you manage to remember which polarity you need to use at each obstacle. The best part is that when you use the wrong one, you get flung in the opposite direction as if the game was personally telling you that you messed up. With vibrant art and soundtrack that keeps you wanting to t', 'In this game you have 2 actions: attract and repel. But instead of i dunno having one button to attract and one to repel, which you know would MAKE SENSE. there is a button that attracts red and repels blue and one that attracts blue and repels red. that might not sound that bad. But when you are mid air it''s just an extra headache to think of what is now the right button for the right action. It feels like the controls change all the time for no reason.', 'Very Positive', 92.23, 10.98, 0.10);
INSERT INTO reviews VALUES (33962, 1205240, 130, 'Best 47 minutes of my life that ive ever invested in something', 'Why does this game have RPG, Strategy and Adventure in the tags, when it''s simply just another puzzle game?', 'Very Positive', 90.00, 0.78, 0.08);
INSERT INTO reviews VALUES (33969, 1205430, 255, 'Main story: 8,5/10\nside quests: 8/10\nzone: 9/10', 'There is one thing that I really don''t like about this "Expansion" it is the fact that they make you pay to finish the expansion that you already paid for... Markath is the conclusion of it and they released it as a DLC, it is unacceptable and should not be tolerated by the fans it is an insult to us. They do this just to make more money or make us pay for eso+ wich is a double standard for their "Free To Play" model, it is a really greedy move by Zenimax.\n\nI love the game but there are ALOT of ', 'Mixed', 55.69, 0.00, 0.00);
INSERT INTO reviews VALUES (33970, 1205450, 6509, 'I love committing Tax evasion. as a turnip! i too hate taxes, and can only dream of committing tax evasion. as a Turnip.', 'Idk about this guys... I was lured in by the reviews, the catchy title and the hefty discount, but I still feel like I haven''t got a game worth 3€. the puzzles and boss fights are not challenging, the humour feels like a washed out Undertale, the controls are just bad, the side quests are just bringing stuff over and over to the same areas... I haven''t finished the game, but after almost 2 hours I just feel like it''s not worth my time. Sadly it''s a no from me.', 'Overwhelmingly Positive', 95.24, 4.30, 1.73);
INSERT INTO reviews VALUES (33971, 1205480, 237, 'The game is very fun for my son, who''s 4 years old.  He loves playground mode, but we''re also working together to unlock all the cars.  Highly recommend if you have a younger kid that LOVES monster trucks!', 'Pretty decent arena/stadium monster truck game, really terrible open world/circuit racer. The thing that irks me the most is how bad the physics model is. For a 20 ton truck it sure feels weightless and stoppable. Destroyable-looking objects can crash you and send you to a full stop or flying. The littlest things can tip you over, as if you had the world''s stiffest suspension; the moment one side of the truck goes up, you''re guaranteed to fall over unless you kill all momentum and come to a full', 'Mostly Positive', 78.48, 64.68, 25.38);
INSERT INTO reviews VALUES (33972, 1205520, 4402, '"Be a medieval artist," they said. "See the funny margin doodles," they said. I was NOT PREPARED for the emotional and intellectual sucker punch this game inflicted on me. It had deep conversations on art, life, loss, self-fulfilment, religion, language, culture, society, and more - but they were all weaved beautifully through the game, and never felt preachy or cumbersome. I truly felt that I was making meaningful choices in the game, while also coming to meaningful decisions in my own views on', 'Err, this is an awesome illustrated book. The amount of detail in the Renaissance (and Middle Ages) is incredible. I learned probably thousands of interesting facts about the village and monastery life, about professions, about religion and more. The storytelling is also very good. There are interesting characters, secrets, twists and turns and complex stories are woven with novel presentation, like the nun (Illuminata) walking you through a book.\n\nSo why the negative recommendation? There is no', 'Very Positive', 94.89, 18.47, 11.15);
INSERT INTO reviews VALUES (33984, 1205900, 266, 'Great game and a step up from the first Alwa game. It feels more forgiving than the first game, even though precision is still needed sometimes. Optional comfort options give everyone the challenge they desire. The world is all about exploring with a lot of freedom and the metroidvania temporary dead-ends that you need to find the right items to overcome them. Game speed is rather slow but graphics and sound are awesome for Pixel Art and Music which never minded me backtracking. Warps can be act', 'Very polished metroidvania with nice visuals and animation, fantastic dungeon and map design, and interesting and funny characters.\r\n\r\nWhere it falls short is in the game play progression: the map not tracking blue orbs, the constant need to downgrade and swap abilities to advance in specific areas, blue green switch with character colour mechanics not explained, and needing to traverse every single map room again and again to find specific character for advancement without any hints or indicati', 'Very Positive', 87.22, 28.95, 8.83);
INSERT INTO reviews VALUES (33985, 1205960, 425, 'Our planet needs more leaders like this.', 'subtle nazi themes', 'Very Positive', 89.88, 6.22, 1.68);
INSERT INTO reviews VALUES (33986, 1205970, 1895, 'Most W game if you ride ditbikes but its expensive if you want other tracks so if your a little kid like me don''t get this because you will be spending a lot and working a lot', 'probably the biggest waste of money to be honest I love mx and atv series, but the vehicles are all reskins of each other and I payed for the deluxe for a bunch of the same motorcycle in different paint schemes and some random shaped pipes with no new stats or anything, prob the worst feeling MX vs ATV I''ll just get my playstation 2 out and play the older ones.\n\nDon''t get me wrong I love the MX and ATV series but like this just is a game that has a half baked feel and is feeding on nostalgia of ', 'Mostly Positive', 77.04, 44.88, 0.42);
INSERT INTO reviews VALUES (33992, 1206060, 1026, 'Kids, don''t do drugs', 'Beautiful and gloomy point&click, I especially like the levels in a rounded place, like in a hollow planet. However, I don''t understand half of the riddles, I never know where to click.\nSo, the game is not bad, but not for everybody.', 'Very Positive', 88.79, 1.78, 0.77);
INSERT INTO reviews VALUES (34007, 1206410, 136, 'Highly recommend for anyone familiar with Dark Souls. Very fun and challenging when it needs to be. Also recommend playing the demo first to make sure your PC can handle it.', 'This is VERY unfinished. Marketing made it look more complete, but at this point I cant even progress due to unworkable stuttering and constant loading. Ill wait for them to finish it... I guess.\n\nEdit: to the developer: Ive worked in tech for over 35 years, and Ive worked for a few devs. I understand how all of this works, but Ive also watched as the idea of CROWDFUNDING has morphed into what people think is regular game sales. Many devs now release unfinished games and depend on the community ', 'Very Positive', 83.82, 29.97, 6.47);
INSERT INTO reviews VALUES (34008, 1206430, 921, 'This game has a beautiful and interesting storyline with gameplay to match. There really is nothing like it. Unfortunately, - and I realize this is a me thing - I found myself developing motion sickness on the first level. The high contrast Black&White plus quick looking around while throwing ink blots started to make me feel nauseous pretty quickly, and unfortunately I had to return this game. (for a reference, I get motion sickness when playing MineCraft without a shader, so I imagine I must b', 'Rating: ★★☆☆☆ (2/5)\nThe Unfinished clicking simulator.\n\nThe game is filled with interesting gameplay ideas, but these are neither fun on their own nor work well together. Special mention to the plant sections, where the player has to continuously shoot water to make them grow hundreds of meters to turn large sections climbable. Despite fitting the game mechanics, I also didn''t find the story interesting.', 'Very Positive', 81.43, 0.20, 1.58);
INSERT INTO reviews VALUES (34010, 1206480, 454, 'multiplayer when? also great for sparing', 'Had potential, but the devs are lazy losers who just made a game for the money. updates are a joke to them, no bug fixes and barely any content, u will get 2-3 days worth of content no replay ability cause the AI are a joke. dont waste ur money on this garbage thrown together google playstore game.\n\n', 'Mixed', 68.06, 17.82, 17.40);
INSERT INTO reviews VALUES (34016, 1206600, 256, 'I loved this game, had a LOT of fun and I LOVE how game idea was presented in game - IT was fun to play and that is all what should player want from game. Potential here was on EPIC level in my opinion (I am fan of gods and magic like game called Sacrifice released in year 2000) and was hoping this game will be something I can remember as mentioned game :)\n\nReal shame that this great game vision and idea ended up abandoned.', 'Abandoned', 'Mixed', 63.67, 40.62, 0.38);
INSERT INTO reviews VALUES (34017, 1206610, 876, 'The game is fun, very happy and chaotic.', 'online server trash', 'Very Positive', 88.58, 2.52, 0.10);
INSERT INTO reviews VALUES (34020, 1206670, 152, 'Fun low poly survival. Lot of stuff to do!', 'Review as of end of august 2024: No new patch since Nov 2022 => it appears abandoned', 'Mixed', 61.84, 0.62, 68.23);
INSERT INTO reviews VALUES (34053, 1207650, 6027, '10/10 Successfully established a police state, threatened the life of the only opposition who i hadn''t arrested in the middle of the presidential debate, dropped out of the race in order to endorse Adolf Hitler as the next president, and retired as a football manager.', 'I was highly engrossed in my first play-through... I couldn''t put it down for 10 hours... However, it started to lose its luster when i realized this game punishes you way too severely for not playing "the right way" and does so without warning for spending any governmental funds, especially in a command economy run, while also being anti-communist.  Also it is practically impossible to get anything done without going into huge debt. I was under the impression that I would automatically receive ', 'Very Positive', 93.60, 108.18, 39.30);
INSERT INTO reviews VALUES (34057, 1207780, 629, 'Nice gameplay and beautiful anime characters, I can''t evaluate the plot because I skipped it.', 'The game is okay, but your save files will randomly disappear that not even Steam Cloud can save it. All of my progress gone and steam cloud only have one 0% save, 100% would not recommend', 'Very Positive', 86.33, 8.65, 10.75);
INSERT INTO reviews VALUES (34075, 1208260, 1478, 'I was lonely. sad. depressed. wife left and took the kids. I used drinks to dissolve the pain. I figured it was time to end it all… that was until i was told about game Hentai Vs Furries. Immediately it took me in a spiral of emotions. Life grew back into my body. Everything taken away suddenly fell right back into my arms. I have everything i ever wanted. All because I decided to fight furries as a big titty milf. 😭😭😭', 'Bad game. There isnt the opion of playing with friends. Which did make us all sad. One of my friend cried because of it. So please add Multiplayer. It will curse cancer and help all the kids in the friend. People will united because of multiplayer. All nation will play this and make world peace. Maybe Putin and Trump will play this game. And they will then kiss each ohter because how beatiful this game is. So please add multiplayer.', 'Very Positive', 90.80, 0.97, 0.65);
INSERT INTO reviews VALUES (34094, 1208600, 504, '♡ ∩_∩ \n  („• ֊ •„)♡\n|￣U U￣￣￣￣￣￣￣￣￣|\n|              100/10               |', 'This game plays like a mobile game and there''s nothing to do other than click to gather coin, remove debris, and pet bunnies to raise "cozy" level (which takes ages to get to max). You can also decorate your plot, of course, but the seasonal items are locked behind IRL seasons, which makes little sense in a game as small as this. The progression to unlock all the bunnies are also non-existent, so you''re most of the time just sitting there while collecting coin and removing debris and hope that t', 'Very Positive', 90.28, 9.77, 4.48);
INSERT INTO reviews VALUES (34099, 1208770, 142, 'At first this game was rather bad, lacking content with horrible controls. But despite that the dev never gave up and kept working on this game. I can only applaud him for that and if he continues like that this game will be a jewel. Keep the work up man!', 'holding the sword feels nice, everything else not so much\nthere is not a much content and enemies', 'Mixed', 64.79, 1.73, 0.52);
INSERT INTO reviews VALUES (34121, 1209410, 259, 'When I first got the game I struggled with the tutorial a bit and almost regretted my purchase, but once you get past that the real fun begins - I''ve done two playthroughs now so feel qualified to say that it genuinely is a fun game BUT it''s more of a skill based one and so while it could be easier, earning the skills and making sharp turns with sails almost feels MORE rewarding as you start getting the hang of it. \n\nCombat is the not easiest at the beginning when you lack a decent sized ship an', 'It has nice graphics. And the flag is interacting correctly with the wind. But it''s bland. And somewhat broken or unfinished. If you''re okay with that it''s a thumbs up. But would I recommend? No. \r\n\r\n(I''ll go play that pirate game from the late 80''s that had a pretty good remake in the early 2000''s now. Less voodoo, but more digging, dancing and dividing plunder. Apparently Baron Raymundo has information regarding your lost sister.)', 'Mixed', 58.69, 76.35, 24.38);
INSERT INTO reviews VALUES (34125, 1209490, 1434, 'I liked it when they exited the Gungeon and they said it was Gungeoning time and they Gungeoned all over the place\r\n\r\nupsides is funny combo''s and stuff and random gun mode is now a starting thing.\r\n\r\ndownsides feels like i am limited on power unlike in Binding of issac and the game is now a 2D platformer \r\nNo buttplug support.', 'This is like if you cheated on your 10/10 wife that sucked your dick every day (enter the gungeon) with some broad-shouldered el ogro de las americas from work that complemented your hair (exit the gungeon), all because you just wanted to "try something new" and "maybe it wouldnt be that bad"', 'Mostly Positive', 78.10, 0.45, 11.93);
INSERT INTO reviews VALUES (34148, 1210110, 322, 'Can''t get laid even in a game about getting molested. Very realistic', 'Without the DLC, the game is very short. Too bad.\nOf course I was raped too. I wish there was the possibility of having an ending that ends well. As well as a longer duration of the story in general.', 'Mostly Positive', 73.29, 1.03, 2.55);
INSERT INTO reviews VALUES (34150, 1210230, 153, 'There is no Russian localization, but the music is memorable', 'Suits Absolute Power is 2 steps forward and 2 steps back for the series. The artstyle is better than ever, the writing is just as cynical, and the world is just as populated by wacky side stories and characters. However, unfortunately, its not all positive changes here. The world is much bigger than before, and with the monotone pallet and lack of notable landmarks at times, its very easy to get lost, or forget where you''re going, and just end up wandering around confused and bored for awhile. A', 'Overwhelmingly Positive', 95.42, 7.82, 15.62);
INSERT INTO reviews VALUES (34163, 1210610, 224, 'An action game with style and an engaging gameplay loop which is influenced by Tron, Ninja Gaiden and some retro beat''em ups. It appears to be the first game of the developer so it is even more stunning to see how well the game unfolds and does not overstay its welcome which is greatly appreciated nowadays.\r\n\r\nThere is one small negative aspect (at least for me), some sections can be a bit frustrating (I am looking at you helicopter...) but fortunately the rest of the game is more enjoyable. In ', 'Didn''t like this that much. The game is too simple and short for starters. A very basic beat-em-up, twin stick shooter with a dash a metal gear thrown in. The checkpoints suck and the last stage is a bitch. Hate the helicopter part and the final boss. The ending is sudden and very meaningless, just not satisfying at all. If I had to say something positive was the game was sort of fun. If only all the stages were like stage 5 then we would be cooking.\n\nIn my opinion it needed to be more wacky. Le', 'Very Positive', 91.07, 2.20, 3.98);
INSERT INTO reviews VALUES (34174, 1210800, 238, 'A full diablo-like for dirt cheap. Playing this is like finding a classic ARPG you didn''t know existed. Fun builds, hand made levels, story that knows that you don''t give a fuck. Has endgame, but don''t expect POE endgame.', 'For the price of a hamburger you got a couple of hours of decent old school diablo fun. There are some odd choices here and there but the core of the game is good. My biggest gripe are the ship battles that slow the game down. These are absolutely horrible and have no place in any ARPG. Think of the knight missions in 40k martyr but much MUCH worse. Every couple of maps you get these garbage ship missions that kill all joy of playing this game. Make these optional or better yet throw it out of t', 'Very Positive', 93.28, 27.03, 11.72);
INSERT INTO reviews VALUES (34183, 1211020, 13563, 'my son has loved this more than Roblox.\r\n\r\nhe has found ways to explore, create (i don''t have a clue what he is doing but he enjoys it!), and he enjoys exploring the online world that has been created.  (tonight was the themepark + water park).  \r\n\r\ngreat job developers, he is 8 years old and a "pro gamer" in his own words.', 'Big yikes. My six year old loves it, I might buy it for him for his Xbox but I bought it for us to play split screen — I’m not picky when it comes to playing things with him, because the options are generally pretty limited.\n\nThis ain’t it though. The physics make most jobs extremely frustrating, and the controls are already janky af. This would be awesome to play with a few simple changes — an interaction to load patients into the rescue helicopter instead of having to fight the physics to load', 'Overwhelmingly Positive', 97.05, 19.15, 1.50);
INSERT INTO reviews VALUES (34187, 1211110, 173, 'I''m so lucky to have come across this game on Steam!  As a fan of Bejeweled and other fun connect 3 puzzle games, this is one is right up there!  Unique idea, well executed and very fun to play with a variety of modes and multiplayer!  Plus, this soundtrack is banging!  It says not playable on Steam Deck, but I have had no issues running the game, plays flawlessly!  I really like the control options in gives you, too!  Can play using keyboard, touchscreen or controller.  I got it on sale but I w', 'I like retro. I like good pixel art.\nI understand when low resolution art is used to significantly reduce amount of work for an artist. \nBut this is not the case. A gameboy resolution in the puzzle game with few primitive sprites is a crime.', 'Overwhelmingly Positive', 96.53, 4.87, 0.33);
INSERT INTO reviews VALUES (34199, 1211360, 117, '《角色建模》超棒！老婆们都非常可爱！这个塔防游戏虽然玩法简单，但是二次元美少女真是治愈！每个角色都有自己的技能，而且换装系统太赞了！虽然敌人只有8种，但打起来还算有点挑战。老婆们打起Neomorph的样子真的太好看了，必须一键三连！\n\n**总结**：二次元+塔防+美少女，满足了我的所有期待，角色设计满分！二次元真是太好了！', 'There is no H.E.N.T.A.I (╯ ͠° ͟ʖ ͡°)╯┻━┻', 'Mostly Positive', 76.92, 97.42, 0.68);
INSERT INTO reviews VALUES (34205, 1211600, 651, 'Autism is considered as negative trait. 10/10', 'It''s hard to recommend the game for one main reason.\r\nEnemy spawning.\r\nEnemies will randomly spawn in places you''ve already cleared without any notice at anytime. But most importantly, if you make noise or set off a car alarm suddenly 5+ enemies spawn all around you which is fatal if one manages to catch you which is very difficult to avoid in most areas.', 'Very Positive', 82.33, 1.28, 8.52);
INSERT INTO reviews VALUES (34207, 1211630, 3568, 'In the box, straight up jacking it, and by it, lets just say my party pack 7', 'I''m unable to play with my russian friend, thx Ukraine', 'Overwhelmingly Positive', 96.97, 15.35, 0.42);
INSERT INTO reviews VALUES (34218, 1211930, 105, 'This is a reluctant endorsement. The game, the visuals and the narration are actually quite good. You are a woman exploring a remote island. There is a ghost speaking to you. As you explore, you uncover the mysteries of the island and its inhabitants. It''s really quite good. \nUntil the ending. The ending is shockingly stupid. So painfully stupid that it really undermines the decent game that led up to it. Too bad. I''ll remember this game, but not for good reasons.', 'Man, not a fan. While I do like walking sims, I feel they actually have to do something. Ghost on the Shore presents a story but that''s really it - just the bare minimum for the genre.\n\nYou slowly walk down a lone path in a somewhat generic locale. There''s a lifeless building. Go inside and there are a few sparkly pages and items. You click the sparking thing and sit as the exposition tells you the story. Get back on the path. Slowly walk to the next similar building in the next similar location', 'Very Positive', 84.76, 3.37, 1.75);
INSERT INTO reviews VALUES (34224, 1212020, 341, 'Void’s Calling starts promising, as it has RPG elements like battles, gearing, money system and so on with the visual novel gameplay, which is a good addition. Once you figure out this part of the game, it’s actually enjoyable for those who are into it. The animations and pictures for the themes are also alright. The story also starts interesting, but to be fair it gets some inspiration from Witcher, which is not a big of a deal though.\n\nHowever this game is surprisingly difficult, because it do', 'Hints are too difficult to find. No clear instructions on mission details either. Which is fine in general but there is no option to enable/disable it. Have been stuck for hours to progress next to the story quest. A visual novel does not need to be this difficult to navigate through', 'Mostly Positive', 78.01, 11.30, 2.15);
INSERT INTO reviews VALUES (34227, 1212100, 119, 'was fish. got big. noice.', 'The octopus at the end really stressed me out. They immediately remove everything you''ve done and it doesn''t seem very fair. The game itself is cute and satisfying, but I hated how hard it got, especially to get all the achievements (the vegetarian one especially).\n\nFor more honest reviews check out my youtube channel CozyAriGames <3', 'Very Positive', 89.92, 3.70, 6.72);
INSERT INTO reviews VALUES (34240, 1212400, 100, 'Very cute, charming and funny. Pure delight through and through.\nShockingly good merge of character and game mechanics (a thief with a heart of gold that actually cant steal in game gold) that surpass major studio rpgs.\nSimple but well thought out combat system with 0 grinding which is absolutely not the norm for an rpg maker game.\n', 'I tried. I just can''t. Between the riveting oh no one has skills so we will all smash attack all day battle to get back a spellbook, to resting costs about 12.5% of my G and I can''t grind anything, to the only healing spell heals 1 HP and characters got 500 - 700 HP., to a warrior freezing up all the time and being utterly useless in battle...I just couldn''t. I do like a good parody game but it has to be fun to play too, and this was not it.\n\nIf the game at least allowed grinding for money or ma', 'Very Positive', 86.00, 23.97, 1.25);
INSERT INTO reviews VALUES (34241, 1212410, 127, 'A decent first-person puzzle adventure with unique copy mechanic. If Talos Principle had a small brother then this game would be it. Hourglass is a more bare bones approach to puzzle platforming with borrowed mechanics from Talos Principle and its Egyptian theme art-style. You can expect new puzzle mechanics and interactions throughout the game plus a gradually increasing difficulty towards the end. I got this game on sale and was worth the sale price. Overall, if you enjoy puzzle games then you', 'Precise timing puzzles are extremely frustrating, I dont have the time or desire to waste time figuring out the precise jump distance. Just to fall and have to spend a couple minutes getting back to the start to try again only to fall a second later. Makes for a painful gameplay loop.', 'Very Positive', 80.31, 6.70, 4.53);
INSERT INTO reviews VALUES (34264, 1212830, 191, 'i hated this game until i installed the patch dlc, its a great game and one of the best games i have ever played, elden ring doesnt come close to the level of greatness this game hase\n\npraise the chest', 'this one not good. not hawt enuf.', 'Very Positive', 81.15, 0.25, 4.47);
INSERT INTO reviews VALUES (34270, 1212940, 252, 'Awesome experience that is about as close as you can get without taking mad amounts of shrooms. Each persons experience is different when breaking through but this artist captured their experience and its awesome to be able to share it with others. It makes a great intro to VR for newbies as they don''t have to get to grip with controls and most of my friends are into this kind of subject.', 'Pretty cool experience while fried, but wayyy overpriced for being so short', 'Very Positive', 82.54, 4.80, 0.60);
INSERT INTO reviews VALUES (34282, 1213210, 16791, 'This remaster is a winner. It’s a stellar package, and hopefully a template for what is to come. The minor shortcomings are all due to the age of this title – but this is an old game. You have to take it for what it is – a glorious little piece of history. In presenting that, this is a practically flawless release – but the old-fashioned, less friendly design in places will mean this one isn’t quite for everyone.\n\nhttps://steamcommunity.com/sharedfiles/filedetails/?id=3424281244', 'Delist EA. Forcing third-party accounts and banning for inactivity with no appeal is predatory.', 'Very Positive', 91.91, 22.70, 3.55);
INSERT INTO reviews VALUES (34284, 1213230, 242, 'Got the demo, then the game, played a bit of it, uninstalled, waited a couple years, then beat it.\r\n10/10 Would rain on parades again.', 'game physics like car movement and sliding speed are tied to your fps (game doesnt have an fps limiter btw) pay to lose', 'Overwhelmingly Positive', 95.45, 21.48, 8.08);
INSERT INTO reviews VALUES (34302, 1213740, 3569, 'Broken, abandoned, outdated, wonky, bugged and fun. Steam why are u still selling broken merch? It should be offered free or at least with a disclaimer at a nominal fee. Get it for the lowest price u can and modders and mod authors have at it. This one is worth saving.', 'abandoned, stay away.', 'Very Positive', 82.99, 34.93, 33.27);
INSERT INTO reviews VALUES (34303, 1213750, 565, 'Trump got shot / the day I got this game', 'DO NOT BUY. \n\nON ATTEMPT TO QUIT GAME, BRICKED COMPUTER. HAD TO REBOOT AND UNINSTALL.\n\nThe controls are absolute garbage. Following tutorial, the crab did something completely different as soon as i went into an actual game. It''s like you''re controlling a RAG doll. No consistency to movement. Total crapshoot. Button-mashing is literally the only way to do anything worthwhile. Would not even walk in the direction I pressed!', 'Overwhelmingly Positive', 95.40, 4.92, 0.57);
INSERT INTO reviews VALUES (34321, 1214470, 955, 'okay so, i''ve spent the past few days playing this game and here are my thoughts.\r\n\r\nthe game is fun, i enjoy the range of options you have, i really like that the rooms have their own unique layouts and size (especially depending on the floors of the hotel you''re on), i think it''s aesthetically pleasing to look at and relatively fun albeit repetitive but that''s what you get with a simulator game.\r\n\r\nnow despite all of those things, this game has some major issues and some minor ones. for one, t', 'Game has been abandoned. No updates this year. DO NOT BUY', 'Mostly Positive', 76.96, 187.92, 6.40);
INSERT INTO reviews VALUES (34324, 1216060, 2500, 'The main unfortunate thing about this game is that today''s gamers have different expectations from new fighting game releases. They want frequent patches, and low turnaround time on new content after release.\n\nThis game has had infrequent patches, and didn''t launch any new content for the game for about one year after release. \n\nI say all the above simply to explain why the concurrent player count is low. Between that and the lack of support of the competitive scene, those are why this game neve', 'honestly was pretty fun but you REALLY have to find discords/friends to actually boot up as the game was abandoned as fast as it came. Hopefully the eighting devs learned their lessons with the game and apply them to the hunter hunter game when that comes. only buy with cheap codes or whenever a sale comes up, this being $50 is insane given the game averages less than 30 players daily.', 'Mostly Positive', 70.92, 102.28, 1.47);
INSERT INTO reviews VALUES (34327, 1217060, 34908, 'Can''t recommend this game enough, super fun. I play mostly solo and have over 4,000 hours at this point, it''s super addictive and mastering all the classes makes it almost endlessly replayable. Amazing value for the price!', 'how is there no new map variety in four years lol. this game is fun but the whole 4 biome only shtick is devastating. could they really not pump a few more levels into things? four... years...?', 'Overwhelmingly Positive', 96.31, 4872.13, 25.03);
INSERT INTO reviews VALUES (34341, 1222670, 44650, 'This is a great game to DOWNLOAD and play. With so many character options you can create any type of Sim, even a FIT GIRL! You can also REPACK your belongings and move a new lot anytime. This game is a TORRENT of nonstop fun that i would recommend INSTEAD of similar titles!', 'A downgrade from the previous games; a downgrade from a life simulator to a dollhouse. DLC after DLC to milk the audience to the bone by your ever loving EA.', 'Very Positive', 88.27, 0.10, 282.25);
INSERT INTO reviews VALUES (34342, 1222680, 44676, 'This is a simple NFS.\nAnd that''s great.\nJust a regular arcade driving game where you win races, buy new cars or new parts and becomes faster.\nIt feels like a Underground2 / Most Wanted gameplay dynamic.', 'Does not work with Steam Deck anymore. It did when I bought but stopped after EA borked it with their policies on supporting Linux / SteamOS. Save your money. Plenty of other racing games that work beautifully on the Steam Deck.', 'Very Positive', 84.78, 32.87, 8.98);
INSERT INTO reviews VALUES (34343, 1222690, 9985, 'Great game, people are idiots. EA launcher is installed when you boot up the game for the first time. You can easily toggle it to not run when the system starts and turn off background processes making it close completely after you finish playing. So hard! ZOMG!! Just play the game an quit whining. Can''t wait for Veilguard.\n\nInstructions:\nOpen EA app > Settings > Application > Untick ''Open EA on startup'' && ''Enable background services'' > Restart PC - Done.\n\nSide note: if the game won''t launch th', 'The game is unplayable due to classic EA launcher BS.  This game itself is AMAZING but you cannot play it because of the garbage EA launcher. Avoid at all costs until EA figures their shit out.', 'Mostly Positive', 75.56, 9.60, 86.88);
INSERT INTO reviews VALUES (34344, 1222700, 20585, 'More and more people need to have the experience of playing this game. Once you finish it the only thing you''ll want is to forget the story and play it again.', 'good game but ea''s servers are so shit that i cant even play the game anymore cuz i cant connect to ea servers because of their shit ass fucking app that they force u to use and makes u want to throw ur entire pc out the window... ive legit tried every solution ive seen online to make the ea app work but its impossible. good game, fucking steaming dogshit of a company and app. fuck you and your stupid ass app ea. this would be a positive review if i could use steams multiplayer features... but n', 'Very Positive', 88.17, 7.55, 1.97);
INSERT INTO reviews VALUES (34347, 1224600, 673, 'An art piece disguised as a Half-Life 2 mod.', 'I have no idea what I just played. The levels are extremely chaotic, hard to follow, puzzles are even worse. The game can have you stuck for hours trying to figure out a simple solution to "get to the next room."\n\n I barely understood the plot, and by the end I had no idea what happened during the game. It kinda felt like it just kept going on, and on, and on, and on, and by the ending I was like "when is this going to end?". While I did overall enjoy the game, I would not recommend  it.', 'Very Positive', 85.14, 14.73, 14.88);
INSERT INTO reviews VALUES (34348, 1225560, 1488, '\r\nOne of my favorite games of all time! Nice mix between puzzles and platforming. Story is really interesting and drive the whole adventure. Level design is really good and will gradually gets harder as you progress through. Soundtrack again superb. Really awesome game if you''re looking for something cool you will not be disappointed.\r\n', 'Fun game, but I can''t play it without logging into the EA service, so I won''t be playing it any more.', 'Very Positive', 87.16, 1.68, 2.85);
INSERT INTO reviews VALUES (34349, 1225570, 2251, 'This game ruined my marriage but it is a really well designed game beautfiul scenery mechanics and music that is sad because this game will ruin your marriage. Whoever made this game i would like to marry one of the developers cause im divorced now. thank you\r\n', 'EA decides to implement their 3rd party DRM well after I''ve purchased the game. Now I''m forced to create and log in to a EA account before playing the game. EA doesn''t seem to understand it''s moves like this that will ultimately destroy the company imo. I can personally attest to the fact that I will NEVER purchase an EA game again. We as the consumers have the power, we really need to take a stand and send a message to these companies, or they will continue with this flagrant disregard of their', 'Mostly Positive', 76.54, 10.85, 3.42);
INSERT INTO reviews VALUES (34350, 1225580, 240, 'It was a very good game! This is the first game i''ve ever completed without help, BUT it was very brain racking, i spent 37 hours on a single playthrough. It''s good to just play without thinking. Thanks for reading even though it''s small.', 'Never buy EA games. I cant even play the game because of its EA launcher.', 'Very Positive', 80.00, 43.17, 0.10);
INSERT INTO reviews VALUES (34351, 1225590, 579, 'very good, very sad, but also very happy game? \r\n\r\nfun game if you have family issues', 'A Bit Embarrassing\n\nIt''s a well made game that plays smoothly and intuitively with wonderful character and environmental design. \nBut the dialogue feels like the director literally handed their college therapy journal to the development team, who I imagine asking "Oh, so you want us to rewrite this to fit your monster aesthetic?" "No, don''t rewrite a thing. Just copy and paste all the dialogue." \nIt''s like an English major who hasn''t fully grasped the concept of metaphor. ''Re-skinning'' the drama', 'Very Positive', 80.31, 2.98, 3.35);
INSERT INTO reviews VALUES (34353, 1226670, 210, 'Fantastic game so far, with an exhilarating spirit of adventure! I''m really enjoying the different companions and their range of skills and personalities. It adds a very nice dimension to puzzle-solving. Lovely art, easy-to-use UI, outstanding voice acting. \r\n\r\nI''m always so excited to see what can be done by solo devs and small teams. This is a top-notch entry into the adventure game genre, and expands my ideas of what''s possible, in so many ways. Huge congrats to Grundislav Games for working s', 'This is not a gritty real world western. It is a gentle romp with stuffed pink pillows - after four hours I find myself looking for anything mature or gritty. While it is kinda fun, it''s not the western I was hoping for - but I imagine it is great for teenagers who like a gentle adventure. And after 4 hours I really only found one spot where my choice mattered. So choices that matter are not frequent so far. \n\nI want to continue but I am skeptical. I will update this review if things change. Thi', 'Overwhelmingly Positive', 96.19, 22.15, 3.98);
INSERT INTO reviews VALUES (34357, 1228520, 1661, 'A short but enjoyable retro-style Japanese horror game that transforms the mundane experience of being in a simple store or walk from home to work into an unfamiliar and unsafe environment.\n\nIt didn''t terrify me (which is already difficult at this point, let''s be honest), but I did notice the tension building up with each shift. So for less than the price of a movie, this brief horror experience gave me a good time, and I''m happy with that.\n\nWait, now that I think about it, it does have one terr', 'Not one thing is convenient about this store, Not unless you think being raped is convenient. i opened this game and began to play. 15 mins in a furry runs at me. I dont want to talk about the rest, it makes me sick. This game is sick.', 'Very Positive', 84.59, 2.17, 4.65);
INSERT INTO reviews VALUES (34358, 1229020, 180, 'If you really liked the first and need to know what happens, go for it.  Personally I didn''t enjoy it as much as the first.  It was missing part of the charm of puttering around a small town.\n\nThat said, they up the ante on the horror with an initial "you are in quebec" jumpscare and later sticking you in a house with 4-5 quebecers that you must interact with entirely in french.  A horror many Canadians can relate to.', 'Tired of running into situations where the obviously right thing to do is prevented by the game developer for "reasons".\r\n\r\nSpecifically, found and retrieved a battery that takes two hands to hold, but cannot carry it through double door with giant-ass buttons on it.  ALSO cannot set battery down to open apparently wildly complex door with giant-ass buttons.\r\n\r\nHave these developers never been to any commercial building, ever, while carrying something?  Back on planet Earth, your hip will kick o', 'Mostly Positive', 78.89, 14.85, 4.97);
INSERT INTO reviews VALUES (34359, 1229460, 447, 'Reminds me of good time playing board games with friends. It was fun for the first few hours but it got repetitive very soon despite all the different game modes. Nonetheless, a good game to relax on.', 'an interesting concept that feels rather boring to play sadly', 'Mixed', 69.80, 23.30, 1.32);
INSERT INTO reviews VALUES (34364, 1232580, 1169, 'Some parts of this game really rub me the wrong way. I don''t mind borrowing a lot of the combat structure, buffs, debuffs etc. from Slay the Spire, but making carbon copies of cards felt like it was done in incredibly bad taste. I felt a similar way about Lies of P (despite loving the game) and other souls-likes. Borrowing concepts and making a game in a similar genre is fine and a certain degree of mimicry is to be expected. The issue is when aspects on the periphery are stolen too. So when I s', 'This game seems like it could be good, except for one issue: the illusion of choice. Roguelike games are usually rife with different avenues that can lead to victory. Not this one. To actually beat the game, you have to do very specific things on the map to be equipped for defeating the final boss. That''s not fun. At first, you''re treating it like a true "StS" type deckbuilder, just discovering and having fun. Then, it becomes very "grindy" and boring. Every run you learn something new about the', 'Very Positive', 82.98, 29.13, 10.28);
INSERT INTO reviews VALUES (34365, 1233070, 576, 'Very interesting concept of a game but there is one big issue I had. It''s pretty hard to tell whether a puzzle is solvable or not at your current point and it can lead to a lot of frustration when you waste a lot of time on something impossible. It''s not a game like The Witness where every puzzle is solvable at any time, some are physically impossible until you get a powerup. The puzzles individually are great and it has a good difficulty curve as you progress. You definitely have to go into the', 'Ugh... I''m torn on this review. I don''t think I''ve ever given a thumbs down to a game I enjoyed so thoroughly.\n\nBut this game is left incomplete in the worst possible way. Several meta puzzles were cut, but their signposts were left in the game, sending players on a wild goose chase. Not cool. Throughout the playthrough I spent lots of hours coming back to puzzles that it turns out were never there.\n\nEven something as simple as a completion % on the save file after beating the game would have pr', 'Very Positive', 94.44, 9.03, 28.60);
INSERT INTO reviews VALUES (34367, 1233570, 5812, 'Please do not listen to the reviews about the server being shutdown. This game is literally still playable. You just have to close the server shutdown messages when you load the game and all is good! Sometimes they may popup but never during gameplay.\n\nThis game still saves properly and does everything that it used to do for except maybe leaderboards? You can finish the whole campaign and still enjoy it to it''s fullest.\n\nI love the game, the graphics were ahead of its time and it''s super relaxin', 'Game tries to ping winter15.gosredirector.ea.com on startup and will crash if it cant reach it. \nThis server has been permanently shutdown, so this game is literally unplayable/unbootable.\n\nThe fix would be simple to implement, but why bother when you can put a literally unusable game on sale, right EA?\n\nIf you wanna play this game, and you are fine with a tiny bit of tinkering, add winter15.gosredirector.ea.com to your "hosts" file as 127.0.0.1\nThis will make the game think that your own comput', 'Mostly Positive', 78.77, 6.85, 13.60);
INSERT INTO reviews VALUES (34370, 1235110, 454, 'Rising Lawnmower 2', 'WARNING:\nThis game uses invasive kernel level anti-cheat (Easy Anti-Cheat).\nThis information is not posted to the store page.\nThis is a single-player game.\nThe only reason the developer adds this is to sell the cheats DLC.\n\nDo not buy this game.', 'Very Positive', 94.27, 5.37, 22.22);
INSERT INTO reviews VALUES (34371, 1236720, 882, 'Imagine if the very best, most engaging, creative,  interesting decision-making in a 4x game like Civ was every single turn of every game. Imagine if we''re in our 30''s and don''t necessarily have 3 hours to spend on a given day. In 30min-1 hr, you will experience here some of the greatest game design I have ever come across. Multiple systems interlock in original, meaningful ways that allow both thematic immersion (you''re an elemental spirit fighting colonial invaders? Crack open a pedialyte, son', 'I love Spirit Island, the board game. And I get that this is a heavy game with a lot of moving parts to program. But I''ve only played two digital games so far, and the number of times that the game didn''t allow legal moves, forgot aspects of event cards, and bugged out when trying to undo moves, was pretty bad. However, the second game we didn''t even get to finish, as our save game somehow became stuck on "another player is choosing a growth option". No matter how many things we tried, saving, u', 'Very Positive', 91.27, 62.83, 37.95);
INSERT INTO reviews VALUES (34373, 1237950, 36791, 'i dont know why the game died. i''ma be honest because its such a good game and has pretty good graphics too. so everyone shuld go and try and riveive it', 'The cheating situation is insane, it''s impossible to play the game due to anti spawn cheating. All gamemodes effectively unplayable', 'Very Positive', 86.70, 8.78, 21.72);
INSERT INTO reviews VALUES (34374, 1237970, 85481, 'this game has forever changed my life. back when i used to live in a small rental house in the hood and my parents were split up my mom would struggle for money and so did my aunt, so she moved in with us along with my three cousins. the oldest of my cousins had the brand new Xbox 1 s and along with it he bought tf2, so i was watching him play one day and it was the coolest game to me as a 8 year old. fast forward a couple months and my cousins had moved out it was my birthday, and i got the xbo', 'This game is great, BUT since the latest steam sale, EA Origin backdoors itself onto your desktop and begins spamming you with advertising.\n\nWARNING. DANGER. Fantastic game with a shit publisher.', 'Overwhelmingly Positive', 95.41, 7.65, 23.55);
INSERT INTO reviews VALUES (34375, 1237980, 2332, 'I remember the old days in 2015 when this game first came out. I was but a young boy, a young boy infatuated with star wars. When this game came out it was simply a dream come true. Even though I sucked ass at it I still loved it and I do to this very day.', 'The game is fun but there are no active players in servers, so around the time of this review, I only have played the offline activities (Survival missions, death matches with AI, skirmish etc.).\r\n\r\nThis is a negative review so that it will be easier to find for players interested in this game. It isn''t saying it''s a bad game, but just that it isn''t active and wouldn''t be the experience you are promised. If you still want to play a Star Wars game similar to this, I recommend Star Wars Battlefron', 'Very Positive', 80.40, 12.45, 6.13);
INSERT INTO reviews VALUES (34376, 1238000, 8859, 'Well... I have to admit, the crowd mentality got to me on this game. I didn''t buy it until today during an 80% off sale. What a mistake ! This game is really good and all the bad stuff that was said about was probably when it launched. It runs great, looks spectacular, and the combat is just plain awesome ! The thing is, I''m not that kind of person. If everyone goes right, I turn left. (always) But each time this game came up, everything I saw or read was bad. It''s just not true !\n\nAbout the onl', 'I''m not buying another EA game until you remove the requirement for the EA launcher. I do not want your trash on my computer. It literally stops the game from launching. it does the opposite of what a GAME LAUNCHER is supposed to do. So stupid. I hope this stupid company goes bankrupt so all the games they made aren''t held back by their shitty business practices.', 'Mostly Positive', 73.73, 1.18, 38.53);
INSERT INTO reviews VALUES (34377, 1238020, 1275, '12 years later and the multiplayer still has people playing. While the legendary edition is worth it for the upgraded graphics and gameplay, I still recommend the classic for the multiplayer. It''s a simple game loop focusing on the combat but allows you to play as a variety of the races from the trilogy. Salarian STG? Yep. Krogan with a huge hammer? Yep. A freed collector with insane biotic powers? It''s here. The enemies are various enough to keep the gameplay engaging. If you''ve never played it', 'Game immediately freezes when I try to load the multiplayer, which is the only reason I bought this. Everyone at EA deserves eternity in hell for ruining every game franchise they''ve ever touched, I truly wish the worst for every single EA employee and CEO hope there''s a special layer of hell waiting for you worthless cretins.', 'Mostly Positive', 72.24, 28.17, 0.17);
INSERT INTO reviews VALUES (34378, 1238040, 3607, 'This game is hated because it changed things from DA:O a bit even though it kept the tone. Veilguard is loved despite javing nearly nothing in common with other Dragon Age titles. Make it make sense.\n\nThis game is the second best in the series and I will die on that hill.', 'You cannot play the game without going through the EA app which is notorious for not working. I can''t even play the game.', 'Very Positive', 80.87, 38.93, 0.53);
INSERT INTO reviews VALUES (34379, 1238060, 4360, 'Game is enjoyable I would recommended the coop partner you play with is what makes or breaks the gameplay. \n\nCurrently playing with my friend ken, watching him play makes me question how hes made it this far in life. \n\n', 'Delist EA. Forcing third-party accounts and banning for inactivity with no appeal is predatory.', 'Mostly Positive', 70.14, 8.08, 3.40);
INSERT INTO reviews VALUES (34380, 1238080, 3539, 'Hell Yeah Simulator\n\nThe game is buggy,but just install Bo98''s core bug fixes and you''re good to go.', 'Good game, terrible PC port.\r\nRequires the atrocious EA app for starters, and it''s also infested with Denuvo DRM.\r\nDo not buy this version of Burnout Paradise. Instead, go to a site like G2A and find a Steam key for the original PC port of Burnout Paradise Ultimate Box, which still runs great on modern systems, doesn''t require the EA app and is not infested with Denuvo DRM.', 'Mixed', 60.67, 15.92, 1.02);
INSERT INTO reviews VALUES (34381, 1238810, 31946, 'My review of Battlefield 2042: The game is now affected by a strange bug that automatically enables "share player usage data" without notifying the player. This means data is collected without consent. Don''t jeopardize your privacy with EA. They should be under investigation by the FTC for these questionable practices.', 'check my review on battlefield 2042 but this game is now plagued with a weird bug that will turn on "share player usage data" without notifying you, meaning that it forcibly collects data without player consent. Don''t risk your data to EA. They should be investigated by the FTC for such shady practices.', 'Mostly Positive', 70.83, 11.63, 1.07);
INSERT INTO reviews VALUES (34382, 1238820, 4115, 'I don''t want rockstar launcher.\nI don''t want ea launcher.\nI don''t want ubisoft launcher. \nPlease, at the very least just let me play your games.', 'I bought this for the nostalgia, remembering playing it back when I was a kid. Fighting enemies on a train, that classic death animation with the hand, flying jets in the campaign, it all hit me hard. The campaign is still awesome, realistic, tough, and well-paced. It brings back memories and delivers that gritty, immersive feel I remembered.\n\nBut man, actually playing it today is a nightmare. First off, I just want to play the campaign, solo, offline. Why the hell do I need to launch the EA App', 'Mixed', 67.29, 1.45, 8.97);
INSERT INTO reviews VALUES (34383, 1238840, 38239, '>Play on German servers because it has most pops\n>On Operations\n>Every normal game ends with "gg" & "wp"\n>Play on Ottoman side and win the operation\n>chat fills with "TÜRKIYE #1!!!!!!!!!!!!!!!!!! MUSTAFA KEMAL IS MY KAISER!!!!!!"\n10/10 game man', 'Your launcher is horrible, EA. Your anti-cheat doesn''t prevent cheaters from cheating, but it does prevent me from playing on Linux. I''m never again buying another EA game in my life. I''d leverage short your stocks, but you''re probably being propped up by your ESG investor overlords.', 'Very Positive', 86.56, 36.00, 4.57);
INSERT INTO reviews VALUES (34384, 1238860, 26045, 'The last good Battlefield game they made. If you want to play class-based online FPS with vehicles and up to 64 players on the same map, this is the game to get. Forget everything they made after it and come join us. The game is still alive and you''ll find at least one conquest server with good ping and other players to play with, 24 hours a day.', 'Delist EA. Forcing third-party accounts and banning for inactivity with no appeal is predatory.', 'Very Positive', 84.53, 122.73, 6.22);
INSERT INTO reviews VALUES (34385, 1238880, 1040, 'Love the story how the importance of each character and their story is narrated. Wanted to play game like this in a long time. This is one of the very few games which has almost perfect in every thing.', 'Delist EA. Forcing third-party accounts and banning for inactivity with no appeal is predatory.', 'Mixed', 66.35, 26.28, 3.20);
INSERT INTO reviews VALUES (34387, 1240440, 27129, 'If you turn your brain off to the story a quarter of the way in, Infinite is actually a blast. The multiplayer is pretty fun as well when Microsoft isn''t trying to nickel and dime you for fucking armor colors.\n\nSolid 6.5 out of 10.', 'This is a decent Halo multiplayer shooter that is being kept above water by the community alone. The only thing the official devs put out are overpriced cosmetics or a single new weapon and developer tooled map in a year. To top it all off and what really makes me not be able to recommend this game is that the development studio doesn''t view user content as "real" content. Yet it''s that content that is keeping the game from being dead, it''s that content that the devs ask for in every single upda', 'Mixed', 68.20, 207.57, 377.38);
INSERT INTO reviews VALUES (34388, 1240630, 359, 'Such an amazing game, very well put together.  All I found myself wanting was more of it. The Campaigns and Scenarios are nothing short of amazing and crazy fun.  Counters are beautiful.  Where game also truly shines much more than Matrix or Slitherine games is the amazing Mullti-player support which is absolutely top tier.  I know the author has put so much work into this title I feel bad for being a greedy human but I hope the author of this amazing titles drops a DLC that has a Global Map lik', 'Can''t recommend this, had higher hopes. Given the scale, the units don''t stack, which is ridiculous, so it negates any manpower advantage you might be able to bring to bear. Also, the designer spent time making sure the pictures of the units line up historically with the  types and countries, which is great, but it ends there. There is no difference in quality between countries. The 1937 Chinese are WAY too strong, AA units are ridiculous. If you want to win the game, just build tons of mechaniz', 'Overwhelmingly Positive', 96.38, 160.05, 339.18);
INSERT INTO reviews VALUES (34391, 1243830, 1223, 'Good game to get if you don''t already own 1 or 2. Includes both and the game looks great! Fun game if you love screaming at your friends and family when their brain starts malfunctioning.\n\nThere is a bit of a connection issue but ONLY IF one of your party members has crossplay enabled. This makes the game connects to the T17 servers which are absolute crap. With that on, we would occasionally disconnect after a level and the load times were not fantastic. Once we turned it off, not only did we n', 'Imagine buying this game four times, once for yourself and three friends. Now imagine your surprise when you spend two hours trying to figure out how to not disconnect over and over again before you get even outside of the tutorial while playing with your three other friends. Now imagine scowering the internet looking for a way to fix it, including but not limited to disabling crossplay, verifying files, undownloading and redownloading, changing hosts, among every other way to "fix" it. There is', 'Mostly Positive', 71.95, 3.50, 6.52);
INSERT INTO reviews VALUES (34392, 1244090, 5594, 'it''s such a crime that this game isn''t rated overwhelmingly positive, this game was worth every cent, can''t wait for the DLC to release', 'This game is a love letter to great games of the past, and it does that all very well. The problem is that feels less like you''re playing a game and more like you''re just walking through a private museum of classic games. It''s lovingly made, but the storytelling is boring, disjointed and contrived, and ultimately nothing about the game is especially compelling or original. The couch co-op is nice. I''m enjoying playing it with my kid. if it weren''t for that, this would be a drag.', 'Very Positive', 89.86, 51.73, 40.38);
INSERT INTO reviews VALUES (34393, 1244460, 16145, 'it’s a fun game and then when you get bored you just start letting all the dino’s loose like the movies', 'If you want to play this game as a sandbox and just play with the dinos, go buy it. But if you are here because you want to play through the campaign, it''s not worth it. While both games have mediocre stories, at least the campaign in the first game was still fun. On the other case, the campaign in this game is so boring and frustrating that I ended up closing it and just went to do the dishes. So yeah, keep your money safe and don''t be like me, who just spent 70 euro for the premium edition', 'Very Positive', 90.34, 23.52, 39.43);
INSERT INTO reviews VALUES (34394, 1244630, 784, 'The game got stuck at 89% on the loading screen, so I emailed the developer. They responded quickly and fixed the issue! I really appreciate such an active and helpful support team.', 'initially a great game, however the lack of free houses and inability to keep playing unless you purchase expansion packs is a stupid concept. Wont keep long term lovers of the game this way, once you complete all the free houses theres nothing to do.', 'Mostly Positive', 76.66, 0.78, 31.08);
INSERT INTO reviews VALUES (34395, 1244800, 1582, 'This is less a city-builder or base-builder and closer to a single player board game in video game form. My experience has been that it feels a lot like a well-built, single player version of Terraforming Mars (the tabletop game), both in the theme and the turn to turn play. If that sounds appealing this game is an easy recommend; the game has a very addicting core loop that''s challenging without feeling unfair (at least up to moderate difficulties). If you''re after a Mars themed city or base bu', 'I can''t recommend it. Your mileage may vary, but I don''t think this genre blend of "rogue-like" and "colony builder" offers much. There is very little variation between runs, regardless of the ''campaign goal'' you''ve picked, which means they are very samey. The core game-play is also overly shallow. Meta progression is done via unlocking a new random building, but it offers the same resource generation as the rest and therefore isn''t particularly exciting or enhances your run experience much. I''d', 'Very Positive', 89.57, 25.52, 1.80);
INSERT INTO reviews VALUES (34396, 1245250, 127, 'Not for me.\n\nI thought this was going to be more like Age of Empires.....It is not. It is a make your people happy game and I dread this type of gameplay. However, It looks like a pretty in depth game and very well put together. So if you like these types of games I am sure you will love it.', 'The game keeps breaking. It goes from my Inventory not going up, the story stops working, military units stop moving, Caravans getting stuck in towns, materials showing on the map that''s not even visible to gather. Enemy siege units being immune to dmg from all spear units unless hit with a different unit. not being able to train more soldiers, and have to rely on milita contracts. It''s happened twice, where if I leave the game I lose the save. I''m loving the game, but I can''t keep losing progre', 'Mostly Positive', 76.38, 0.40, 24.02);
INSERT INTO reviews VALUES (34397, 1245430, 1417, 'not just beating my meat, but eating it, shooting it, breathing it, sitting on it, becoming it, talking to it, having romantical feelings for it, throwing it, hacking with it, slashing with it, attacking it, breaking it, dying upon it, killing upon it, dying with it, killing with it, and also probably having sex with it.', 'Nice artstyle and cool vibes wasted on a sweaty-ass, unfun, unfair and repetitive rouge-like, terrible controls and some artsy-fartsy nonsensical ravings for a narrative. Looks much cooler in trailers than it is really.', 'Very Positive', 92.03, 23.53, 3.75);
INSERT INTO reviews VALUES (34398, 1245480, 590, 'The game is really good, way better than I expected but it needs an online co-op sortie mode so we can play with friends.', 'Dev had cheaters that made massive amounts of money. If you happened to kill a cheater and take their Magus you got an insane amount of money but you had no way of knowing this beforehand. As of the patch today, the devs gave all the INNOCENT people -99 MILLION CREDITS. I am sitting at -29 Million credits and can''t even play the game I paid for. \n\nDO NOT BUY.\n\nEdit: It has now been over 3 weeks with my support ticket open. The support is F tier. They have no answers and no contact with the devs.', 'Mixed', 50.17, 41.78, 110.07);
INSERT INTO reviews VALUES (34400, 1245950, 127, 'Very fun, really satisfying, good replayability. Each fight feels different, and I love how much personality each opponent you fight has. Despite the enemies being NPCs, they really do feel human. \n\nHuge recommendation to those who have VR, only issue on my end was a slight controller issue. \nI wish more people played this game so PvP could be an actual thing you could do, I''d play it all day', 'I''m just not having very much fun. The only people I ever enjoyed playing against were players with the 2 handed sword or crusaders, probably cause I''m bad but whenever I played against people with fast weapons they were able to just do quick repetitive movements and no matter how much i try I can never get my weapon either in place fast enough or recharged fast enough to properly block, especially when someone walks up so close to me I''d probably be able to feel their breath if we were in perso', 'Mostly Positive', 77.95, 3.60, 1.75);
INSERT INTO reviews VALUES (34401, 1247290, 131, 'I''m not a game designer and have never used any other tools to create 3D games, but GameGuru Max made it incredibly easy for me to build my first game level. The interface is user-friendly, and I didn''t need to rely on many tutorials. I might finally be able to make an FPS game!', 'In 2025 GGM still can''t deliver a rudimentary, working fps. All new features seem to come from the community. No apparent roadmap on sight. Updates are sparse. Tons of expensive DLCs do come out frequently instead. Can''t recommend this software in its current state.', 'Mixed', 67.18, 45.48, 298.48);
INSERT INTO reviews VALUES (34402, 1249970, 2271, 'A good foundation with potential, missing a lot of what made TDU unique though. Where are the driving schools, housing etc. we also need more people per server as it feels quiet.', 'Positive recomendation will be available after introduction of offline mode, good luck', 'Mostly Negative', 36.86, 18.05, 32.07);
INSERT INTO reviews VALUES (34408, 1252300, 190, 'RetroMania Wrestling is a wrestling game from \nRetrosoft Studios that pays homage to WWF Wrestlefest and WWF Superstars. \nI picked this up recently and it instantly became one of our favorite games in my household.\nIt is definitely worth playing. \nR.I.P. Roadwarriors', 'It only took a few minutes for me to realize that this game just isn''t for me. While I''m a big fan of wrestling games, especially classics like WWF Royal Rumble on the SNES - this one didn''t quite hit the mark. The timing-based grapple system didn’t feel satisfying to me, and overall, it didn’t capture the fun I was hoping for. Unfortunately, I don’t see myself coming back to it.', 'Very Positive', 81.58, 80.17, 0.12);
INSERT INTO reviews VALUES (34410, 1252680, 532, 'Frankly, I find any review of this game centered on its difficulty to be a bit insulting. The game is challenging and that makes it feel even more rewarding to do well, to learn the small details of the maps that I know these devs have poured their hearts into. Don''t bash a game because it is too difficulty for YOU, especially as this topic has seemed to affect their design decisions going forward in allowing Difficulty adjustments to be made. Will you all change your reviews to positive once yo', 'Sentry almost reaches greatness with its solid gameplay but falls short due to the outside systems surrounding it.\n\nThe layout of the ship and multiple attack vectors incentives the player to neglect the outer sectors and focus on the two choke points leading to the core, leading to the same levels being played back to back for an entire run. This leads to a repetitive routine of defending the same two sectors and the core back to back, which is exacerbated by the lack of tools available to a ne', 'Very Positive', 86.65, 5.03, 12.33);
INSERT INTO reviews VALUES (34416, 1253920, 7420, 'its the one in better  , devs listen community after the first ands imprement thing people request .\n', 'The original game was a hack and slash roguelite. This one is a f*cking bullet hell platformer. You spend more time jumping around like a f*cking rabbit than actually fighting. Also, making the enemies stupidly powerful so that you''re forced to grind endlessly just to get enough health to survive a level is not my idea of fun gameplay. Fucking stupid.', 'Very Positive', 91.20, 42.07, 52.32);
INSERT INTO reviews VALUES (34423, 1257280, 108, 'Enjoyed this game a lot, just needs some quality of life improvements and minor bug fixes to be a great simulator game', 'The 3rd site from the end is very finicky to start, the last mission at machu pichu has a statue that will NOT come clean at the spray step. It stays stuck at 98% and even setting up an auto click mouse and slowly moving over every pixel of the surface from as many angles as possible for over an hour doesn''t get it to move. Very frustrating being so close to finishing the job and not being able to. These 2 bugs are unacceptable. Don''t waste your money!', 'Mixed', 68.52, 6.27, 12.87);
INSERT INTO reviews VALUES (34426, 1259420, 32933, 'There''s got to be a special place in hell for the morons at playstation who approved Concord but didn''t want to move forward with Days Gone 2.', 'The game''s world and atmosphere are impressive. The motorcycle mechanics and upgrades are also well-designed. The story progression is slow, but overall, I enjoyed the narrative.\n\nHowever, the excessively repetitive nature of the tasks in the game made finishing it feel tedious for me. This aspect negatively affected my enjoyment and led to a dull experience when I was hoping for more variety in the missions.', 'Very Positive', 92.13, 246.22, 76.55);
INSERT INTO reviews VALUES (34427, 1259510, 208, 'It''s literally crazy that this game is $2. It''s legitimately better than Poppy, Bendy, FNAF SB, Ruin, and basically every other first person mascot horror game. The fact that it was made by a single person makes it all the more impressive. If you like those types of games, you would be crazy not to play this.', 'As someone who played the original release and this brand new update, I''m frankly baffled by how much undeserving praise this title is getting. The map design is still incredibly confusing, with little indication on where you''re meant to be going and what you''re meant to be doing. Visuals aren''t good, with environments that feel cheap, empty and right out of a Roblox game. I was so frustrated with this new build in particular that I didn''t even finish it; I couldn''t figure out what I was meant t', 'Very Positive', 91.35, 9.20, 4.57);
INSERT INTO reviews VALUES (34428, 1260320, 15470, 'I immediately deleted this game because it has no local offline play. This would have been a great game to play with friends and family,m but, as is, just not suited to my poor wifi countryside home.', 'My current problems: \nIn the latest update, they added gambling in the way of a rigged claw machine. \nYou have to PAY to get all daily gifts. \nThey are purposely  avoiding to add offline mode in PC version of the game.\n\nThey are trying to implement F2P microtransactions in a paid game.', 'Very Positive', 89.64, 1.57, 31.43);
INSERT INTO reviews VALUES (34429, 1262240, 3107, 'To be honest, I don''t entirely see what the hate toward this game is about. I personally prefer this more lively artstyle to the prior GW games more gritty and dark tones. The hub world is pretty good, although I can''t deny that jumping behind enemy "vines" of GW2 deserves plenty of merit. The characters here in BFN are much more charming, and the game itself is easier and simpler without the character variants of the prior games (although, again, they had their pros). Sure, it would be cool to ', 'Anti-cheat purposely not supported on Linux (and, therefore, on the Steam Deck) since the transition to EA''s own anti-cheat ("WINE is not supported"). And guess what? The number of cheaters and exploiters have not changed at all. Previously they were using Easy Anti-Cheat and it was working perfectly fine for Linux users.', 'Mostly Positive', 76.63, 712.00, 6.38);
INSERT INTO reviews VALUES (34430, 1262460, 737, 'its a good game but the zombies look a bit off in comparison to the rest of the game and PLEASE add multiplayer \n', 'Only played for 48 minutes and had to google how to do things 4 times because the game doesn''t tell you, Like how to sleep. A few basic tweaks like having a tutorial would make the game a lot better. Good idea though and it definitely has potential. Refunding it for now but might revisit in a year or 2.', 'Very Positive', 83.99, 21.52, 0.80);
INSERT INTO reviews VALUES (34431, 1262540, 6391, 'The fucking EA app sucks, but when the game works its fun, EA app 0/10, game 10/10', 'My biggest complaint and the main reason I would not recommend this game is that ur forced to play online even if you’re not using any of the online features. I bought this game so I can play it on my steam deck when I travel, only to find out the game is unplayable without an internet connection. Highly recommend playing any other racing game.', 'Mixed', 65.47, 12.38, 1.45);
INSERT INTO reviews VALUES (34432, 1262560, 7001, 'Would be great if it wasn''t titled "Most Wanted", that said it is a B L A S T with mods.\r\n\r\nMultiplayer is pretty dead, btw \r\n\r\nPeace :)\r\n\r\n(as I write this South Korea has declared martial law)', 'I saw this game and though "Oh wow, Need for Speed Most Wanted! I loved playing this game as a kid on my PS2!"\n\nI bought the game, installed the game, realised the graphics looked a bit different. Thinking, "hmm... perhaps they also remastered it a bit as they ported it to PC...". \n\nI go through the tutorial, get to free roam, drive directly onto a road that suddenly has a big border of red X''es across. I drive into it, and it prompts me to buy a DLC to drive into this area. \n\nI alt + f4 and req', 'Mostly Positive', 74.53, 9.38, 0.17);
INSERT INTO reviews VALUES (34433, 1262580, 6699, 'Do yourself a favor, and play it with the Unite 1.2 mod. It makes the handling much better, the drifting more engaging, and the cops more ruthless. It also removes the random speed cards and allows you to buy the ones you want directly from the store, just like you''d buy parts in any other game. As soon as that speed card system is out, the game becomes much more enjoyable. Definitely worth it when on sale.', 'DO.NOT.BUY.THIS.GAME.ON.STEAM!!!! I enjoy playing it but since the hellspawn that is EA loves that STUPID app and CLOUD SAVES so damn much, I have to restart steam over and over and OVER AND OVER AND OVER just to hope that this damn game will launch without giving me a damn CLOUD SAVE ERROR on that piece of S**T app. I have been trying to launch the game for 20 minutes! Go find a "launcher free" version from a scruffy seafarer, I know I will.', 'Very Positive', 85.28, 31.48, 28.78);
INSERT INTO reviews VALUES (34434, 1262600, 2972, 'very good game.. way ahead of its time.. insane graphics and the option to play as a cop is just too good.\nruns at 30fps but can be fixed. just paste the following command at the launch options by right clicking on the game, properties, general, and launch option -  (steam fix!) (dont know about origin)\n\n-GameTime.MaxSimFps 60 -GameTime.ForceSimRate 60', 'WARNING:\n\nI played this game for almost 7 hours in my first sit down because its actually an incredible game, BUT out of nowhere, it disconnects me from the server (i didnt lose internet, it was just their server) - and when i loaded up the next game, ALL of my progress was set to zero. No stats, level zero, no money, all my cars are gone, everything was a complete wipe for no reason at all.\n\nI looked it up, and it turns out, this is a semi-common problem that has no solution so just beware, but', 'Mostly Positive', 75.50, 12.60, 7.83);
INSERT INTO reviews VALUES (34438, 1264250, 1397, 'I took Rudy Smith, fresh out of Lockerport School for Students with Special Needs, and somehow made him the North Atlantic''s top crane and dredge operator. The fishing is so mind-numbingly slow that I started having deep conversations about life with my NPC crew members. Now we''re all emotionally entangled, and I think I have found a virtual best friend in this guy. Rudy can even manage two dredge cranes at once during scallop operations—an impressive feat for a lad who once struggled to operate', 'Here are the notes I posted with my refund request:\n\nThe basics of an excellent game are here which makes it frustrating and confusing as to why the game is not polished (i.e. finished). It has crashes, the controls are clunky and as mentioned it generally needs polish. Fix the crashes, revamp the controls (I use controller) and generally polish the game including improving the game play loop and there is a great game here. Based on discussions on the forum it sounds like the game is abandoned s', 'Mostly Positive', 77.38, 37.83, 2.25);
INSERT INTO reviews VALUES (34439, 1264520, 523, 'I played it on Roblox when it came out, and I will say. This game is very faithful to the original idea and I just love this game. Mainly because of my nostalgia for playing it in Roblox in 2017/2018. A wonderful work and a wonderful game.', 'one bobux', 'Overwhelmingly Positive', 97.90, 3.03, 11.80);
INSERT INTO reviews VALUES (34444, 1265800, 452, 'I have mixed feeling about this one.\nIf this was a flat game then it would be a 4/10 at best. I guess because of the lack of these types of games in VR it just lunges over the 5/10 line for me.\nThe graphics are great. But everything else is mid.', 'Yes, it looks amazing. But that''s mostly it. \nThe gun-play is very basic, the crafting mechanics feel like an unnecessary gimmick.\nSwimming straight sucks and climbing feels fake.\nIts like a bad Half Life Alyx wannabe but with a space scifi generic feel to it. \nNot even the most basic part of just shooting feels fun. \nVisuals over everything else.', 'Mostly Positive', 73.45, 10.27, 0.83);
INSERT INTO reviews VALUES (34445, 1265920, 2938, 'This is the best game I have ever played, It changed my life for better (even though I cry every single time I play it) The soundtrack is perfect, the characters have a lot of development during the game not just the main ones.\nif I had Max''s power I would go back in time and tell my younger self when I open the game for the first time that "This action will have consequences..." but the best consequences you could have asked for, it''s a pleasure being able to live in a world where I met this ma', 'Pros to this game: It''s Life is Strange! It''s one of my favorite games of all time and the story is absolutely amazing. I couldn''t ask for a better game. It was really nice to be able to play it again.\r\n\r\nCons: Please, just buy the original. It''s cheaper and honestly I didn''t notice any major improvements in the graphics or anything. It''s exactly like the original, except somehow, even though this was remastered I experienced so many bugs. Both visual and technical. There were several times the ', 'Very Positive', 88.97, 58.97, 18.17);
INSERT INTO reviews VALUES (34449, 1266540, 1141, 'AAAAhh yes salmon farm for a week, come home from work, play game with salmon farm.\r\n now i can salmon farm all the time and fish', 'In the latest update you guys added some tier 3 ships, including a tier 3 service boat. However, map spawned missions such as towing/firefighting/repairing are not working. You guys stated that map spawned missions would be available after refactoring process was finished, and now that it is, map spawned missions are still broken. This game is nowhere the state you can charge $30 for it. Nonetheless, I will change my review once the things I mentioned are working properly. I simply cannot recomm', 'Mixed', 64.15, 61.03, 48.42);
INSERT INTO reviews VALUES (34450, 1266690, 1333, 'fun game BUT, the devs should add bots or make more promotion to this game because it takes so long to find one match nowadays. still, i would recommend this game because its fun (and painful) and its very cheap when its on sale.', 'The devs don''t do shit to this game and leave it dying. This game''s terrible, not worth buying.', 'Very Positive', 81.02, 14.92, 290.27);
INSERT INTO reviews VALUES (34454, 1268750, 19968, 'I do not care If helldivers 2 is objectively better in every aspect I''m still sticking to getting my citizenship dammit', 'Game full of bugs (and not the good kind) and problems and if you point that out and look for assistance on Discord you get attacked by the moderator''s friends and banned from the Discord channel (and steam) by the moderator Centuron.\n\nWaste of money with the same old creed "ADD MORE STUFF BUT NEVER FIX".', 'Very Positive', 82.92, 54.33, 424.42);
INSERT INTO reviews VALUES (34455, 1269020, 374, 'Absolutely loving this as an introduction to the genre - I''d tried DoorKickers 2 and found it a bit overwhelming, this seems to be easing me in far better as a noob. It''s taken a bit of effort to get the hang of the controls and UI, even with the devs provided layout takes a little time to get comfortable on the Steam Deck, but after 5-6h I''d now say I''m just fighting the bad guys, not my understanding of how to do things. \nI love the gameloop of loadouts, planning then watching helplessly as yo', 'I really want to like this game... but the true enemy of this game is the mission planning UI. It takes so much extra work to get things the way you want to and in a game where little details make a big difference it just feels like a chore. \n\nStill suggest trying it if you like the style of game, but its not for me. :/', 'Very Positive', 88.24, 9.52, 2.10);
INSERT INTO reviews VALUES (34456, 1269710, 428, 'This game is fantastic. Until it sucks. It''s a wild ride with such highs and lows. I''d give it a solid B- at this point. A neutral rating if I could. It would be a straight up A game, amazing in so many ways, if it weren''t for the absolute awful UI implementation for an otherwise very polished game. It''s so frustrating at times. You''ll lose a ridiculous amount of runs simply due to the UI. It''s so mind bogglingly bad at times that I wonder how the developer even plays the game without noticing. ', 'I was hoping that in the two years since I played this that some basic quality of life features might have been implemented, but alas, it is not much worse. Manually selecting and controlling individual units is such an immense chore. Units often ignore orders and will suicide into enemy villages for no reason. Weather events will randomly kill >90% of your population with no counter. I guess the dev reached the sales he wanted in alpha and gave up finishing the game.', 'Very Positive', 80.37, 140.63, 43.43);
INSERT INTO reviews VALUES (34460, 1272080, 29358, 'Game has gotten a lot better over the past few months, however more still needs to be done to make it a worthy successor to Payday 2. While the launch was unforgivable, the game has started to turn itself around and is actually fun and starting to get content on the regular. \n\nI think it''s in a decent enough place where I can recommend it.', '5 months (2/29/24) and 4 DLCs for $20 before we even got an unready button and graphics sliders. Here we are *another* 4 months later and "offline mode" is finally "coming" but it''s actually just an empty online lobby, which is exactly what you''ve been able to get for the last 6 months by queueing since fewer than 1k people have been playing this rotting corpse of a game in all of 2024.', 'Mixed', 42.90, 168.22, 25.08);
INSERT INTO reviews VALUES (34461, 1273080, 103, 'It''s one of the cringiest ABC Afterschool  Special that never existed. While it''s not quite up there with Dinky Hocker Shoots Smack, It''s still a lot of fun and a lot less cringe than Jared Leto''s career during and after My So-Called Life.', 'The game had so much potential with an interesting concept and vibrant art style, but the execution missed the mark for me. The dialogue choices all leaned heavily into awkward or cringey interactions. While a little cringe can be funny, it felt overwhelming when every option was cringey, leaving no room for more genuine or diverse responses.\n\nPlaying with friends made it fun for a while, but without that, I probably wouldn''t have stuck with it as long. There also seemed to be some strange respo', 'Overwhelmingly Positive', 96.12, 7.28, 1.68);
INSERT INTO reviews VALUES (34462, 1273100, 185, 'I give this a conditional thumbs up. Its a fun city builder with good bones but is rough, defintly a pre release game. If you are looking for a refined finished product Id wish list and keep an eye on it. If you love the period and just want to build Greek cities and can deal with issues then Id give it a go.', 'Watch out for this developer. They shoved out Viking Frontiers in a bad state, and they did the same with this game. There are too many bugs to name. Buyer beware.', 'Mixed', 63.78, 3.25, 5.98);
INSERT INTO reviews VALUES (34463, 1273440, 586, 'Ill start with the negatives. There isn''t much to do besides drift around, you cant really turn much without drifting, and you have less customization of your cars compared to carx, you arent changing the parts on the car, just the color of stuff and the sounds, and it has a very low player base, you will be playing with the same 10-20 people. But for an arcade drifting game, its the most smooth feeling one I have played, there is a good amount of cars to choose from, and you can tune them how y', 'permanently online, the first car you get is pure shit and there''s no tutorial', 'Very Positive', 80.20, 56.78, 0.10);
INSERT INTO reviews VALUES (34466, 1274600, 1290, 'You wanted Bloodborne on PC? Here it is, just in 2D. Great visuals, nice OST, good combat and exploration. The story is another fever dream in FROM SOFTWAR style (which I got tired of to be honest), but overall great game. If you love metroidvanias, totally worth to pick up.', 'I''m not sure how to rate this game. It''s competent and generally succeeds at what it does, being a dark fantasy slash gothic horror soulslike metroidvania.\r\n\r\nBut... it''s like Last Faith doesn''t have a single idea of its own. Bloodborne is a great game. Blasphemous is a very decent game. Last Faith is a non-entity if you remove everything it copied from them. So if you love the genre, you''ll probably enjoy it, but nothing in the world would change if it didn''t exist. (Also status effects are bug', 'Very Positive', 82.02, 24.75, 38.13);
INSERT INTO reviews VALUES (34474, 1277930, 469, 'UOOOOOOOOOOOOOOOOOHHHHHHHHHHH NANAMIIIIIIIIIIIIIIII 😭😭😭😭😭😭😭😭😭😭😭😭😭😭😭😭😭😭😭😭😭😭😭😭😭😭😭😭', 'I''ve come to realize that unfortunately that this type of visual novel just isn''t for me. It''s not bad, for sure: the voice acting, English translation, and art are all excellent. However, there''s not really that much to do within this game: choices don''t make a big impact on gameplay, as it''s extremely easy to backtrack to unlock different routes. The story is perfectly acceptable, but nothing awe-inspiring either. If you''re looking for a relaxing dating sim, this is perfect, but otherwise this', 'Overwhelmingly Positive', 97.44, 83.32, 20.47);
INSERT INTO reviews VALUES (34476, 1278540, 890, 'Game launches in Mandarin.  If you are an English speaker like I am; you will need to click the option second from the bottom on the title scene, and then the third option on the second screen.', 'I''m pretty surprised at all the positive reviews. Firstly, the english translation is quite poor and caused me to have difficulty understanding what was being communicated. Secondly, there is AI art everywhere between character models and team logos. Lastly, and most importantly, the game piles dozens of systems on you with no explanation for what they do mechanically in the game. Eventually, you are thrown into a match with all of the units buzzing around everywhere, the screen completely full ', 'Overwhelmingly Positive', 95.39, 105.42, 0.45);
INSERT INTO reviews VALUES (34491, 1282200, 5347, 'I would like the option to save the feedback and the closing thoughts locally, even in a .txt file.\nI''ve been writing it down but it takes a lot of time, and I''m worried I may end us losing my notes.\nYour secret word is: Trust', 'I played the first one through just fine however, one of the sex questions you couldn''t escape without sin so I used my free will and closed the game with the X in the corner.', 'Overwhelmingly Positive', 97.70, 1.00, 0.50);
INSERT INTO reviews VALUES (34493, 1282690, 1432, '\r\nMaximum armor but you already know that!\r\n', 'EA IS UTTER OCELOT TRIPE AND YOUR RANCID LAUNCHER', 'Very Positive', 82.40, 1.43, 15.97);
INSERT INTO reviews VALUES (34494, 1283970, 1279, 'The mouse in Last Epoch is a dot on my screen, so this was a game changer!', 'Gameplay sucks, the story''s okay.', 'Very Positive', 93.04, 20.47, 4067.32);
INSERT INTO reviews VALUES (34496, 1284190, 28326, 'If you''re looking for a tech-savvy, realistic terraforming Mars type of experience, look elsewhere.\nOn the other hand, if you''re looking for a game that is absorbing, but that you can just pause for a while to just look around in, then this is it.\nIn short, it''s just beautiful. In fact it''s the most beautiful game I''ve ever played. The designs for the plants, the animals, and the forests and plains that grow from them are wonderful.\nRelaxing? Yes. Busy? Yes. Do you feel like you''ve really achiev', 'There is no way this is a overwhelmingly positive game. It doesn''t really do anything wrong, but it''s for hardcore genre-enthusiasts, everyone else will be bored from repetitiveness pretty quickly imo.\n', 'Overwhelmingly Positive', 95.94, 163.37, 13.70);
INSERT INTO reviews VALUES (34499, 1284820, 571, 'She keeps walking to my fifth monitor that sit close to my crotch\n(⁄ ⁄>⁄ω⁄<⁄ ⁄)\n\n\n10/10', 'She started saying my IP address so I got scared and deleted it\n\n\nalso this might be a bit coin miner it uses almost 30% GPU doing basically nothing or its just really poorly optimized or\nI made a Chinese person very happy.', 'Very Positive', 88.27, 4.20, 0.10);
INSERT INTO reviews VALUES (34503, 1286220, 2299, 'This is truly a dream come true... only 51 minutes in, however I''ve been able to visit my 2 at-sea commands whilst in the US Navy in the early to mid 90s.... The USS Harry E. Yarnell (CG-17} and the USS Yorktown (CG-48). Both ships are lovingly modeled and a joy to watch.\n\nThank you Triassic and Microprose. You''ve made an old salt''s day :)', 'This is a tricky one. In my mind, this game is great when you are commanding a small task group of 1-3 surface assets for example in well designed, low to medium intensity scenarios and terrible when commanding fleets in high intensity situations. \n\nWhat do I mean by this? Well, if the player wishes to be efficient they have to micro almost everything from firing individual missiles at individual incoming threats, clicking on individual aircraft in a flight to make sure they all drop their ordna', 'Very Positive', 89.69, 1.42, 94.65);
INSERT INTO reviews VALUES (34504, 1286350, 5934, 'BPM is a very simple game, and that''s what makes it great. There''s no plot. No cutscenes. No backstory, no dialogue, nothing. Zero fluff. It starts at level 1 and the game says, Here''s a gun, now get on with it.\n\nhttps://steamcommunity.com/sharedfiles/filedetails/?id=3302255692', 'I love rhythm games, I love metal, I have every reason to love this game\n\nWhat''s putting me off is the all red visual. I struggle so hard to find enemies sometimes, and worse to find the power up stations. I can go in a room 3 or 4 times without ever noticing a station. What''d be great is if there was something on the map to at least show there''s something else in the room. It also feels counter intuitive to not have i-frames on dodge, and for the enemies to not be timed with music. So often I''v', 'Very Positive', 91.52, 4.18, 3.55);
INSERT INTO reviews VALUES (34505, 1286580, 1906, 'Great game EXCEPT for the dev''s obsession with eggs. THE EGG MECHANIC IS TERRIBLE!!! And they just released a dlc for it. WHY?! We want ghost ships and gold coins and lost civilizations, instead you keep making egg gear and egg artifacts and egg dlc. ARE YOU FRANK FROM ALWAYS SUNNY?! It makes me want to NOT unlock new items because it''s all egg gear and will ruin my gear pool. Stop with the eggs already, It''s ruining the game. GAAAAAH', 'Do not buy if you expect to use two controllers in local coop. It doesn''t works, and the devs are aware and won''t fix it.', 'Very Positive', 87.25, 89.23, 0.38);
INSERT INTO reviews VALUES (34506, 1286680, 10467, '2K and Gearbox have updated their EULA to be one of the worst and most invasive Terms of Service that has ever been drafted in the industry. You can and will be banned / locked out of your game if you do anything 2K and Gearbox deems as inappropriate or cheating, including modding single player games, and they demand kernel-level access to scan, record, and gather your PC''s data to sell to their partners. \n\n2K and Gearbox have betrayed the trust and privacy of their customers, do not support the', 'Uninstalled since the new EULA give''s uncontrolled access to my computer. Love the Borderlands games, but will no longer be playing the games or giving money to these criminals.', 'Mostly Positive', 71.66, 5.35, 360.22);
INSERT INTO reviews VALUES (34507, 1286830, 340, 'I been playing this game since beta,  with 1 break of 1 year a bit after Rise of the Hutt Cartel.  I remember with the many, many servers the day it was launched, and it looked very promising, unfortunaly  back then, there where extremely many bugs and  when hitting level 50 (back then the  maximimum), as usual the game was released  not really finished. The poor handling of the  feedback caused many players to quit the game  really fast. Always felt that the introduction of the Cartel market mo', 'I have fun, but I have years of experience to help me navigate this toxic community and avoid the pitfalls that would be devastating to the mental health of newcomers who aren''t ready for them. I also have accumulated decorations and shit over the years that make engaging with side content like Strongholds worthwhile. For many that verymuch will not be the case without sacrificing their life, sanity, or wallet. None of this would be worthwhile even if the game weren''t likely to die within the ne', 'Very Positive', 88.24, 10940.47, 1142.75);
INSERT INTO reviews VALUES (34508, 1289310, 160, '100%''d this for my waifu', 'The only way to buy the free game is to buy the soundtrack.', 'Overwhelmingly Positive', 99.38, 6.50, 3.10);
INSERT INTO reviews VALUES (34510, 1289810, 1415, 'I feel like this game is two design choices away from taking the autistic nerds world by storm. It''s fun for those that really like stupid builds, bit it''s also way too grindy.', 'The same boring gameplay forever.\n\nGOOD NEWS!  It''s NOT the same boring gameplay forever!  \n\nSometimes the glorious dev will RESET your progress from your pc and cloud by making mistakes in his releases so you can enjoy the whole game MULTIPLE TIMES. \n\nFeel free to pop onto their discord server so you can witness the glorious Zach''s sycophants blowing so much hot air up his butt it''s a wonder he''s not a hot air balloon.', 'Very Positive', 93.85, 112.63, 103.17);
INSERT INTO reviews VALUES (34512, 1290330, 1363, 'I''ve played a lot of Survivor-likes, and this doesn''t reach the same level as Vampire Survivors, Brotato and Soulstone Survivors, but the sci-fi theme help elevates it past the stinkers. \n\nObjectively speaking, it''s a solid 6/10. The game is incredibly repetitive and kind of short on content. You''ll be playing the exact same map with the exact same spawn patterns until you''ve collected enough cubes to fully upgrade your character, and then you''ll unlock unique, character-specific challenges that', 'Developer claims they have always been transparent about AI-generated content in this game, but a simple look at the Wayback Machine makes it clear that''s absolutely untrue. There was no mention of AI on the store when I bought this and the developer has made it clear they support and will continue to use AI slop.', 'Very Positive', 87.60, 35.15, 0.15);
INSERT INTO reviews VALUES (34518, 1292020, 441, 'Life before death.\nStrength before weakness.\nGameplay before graphics.', 'I can''t help but feel that the percentage shown on the screen are not the real percentages. If the numbers are real then there must be some form of mechanic that is obtuse or hidden to the player. I can''t say I didn''t enjoy the game, but it was really frustating.\n\nI''m no stranger to bad luck but damn does all the bad luck piles up. It is like playing with a GM who purposely fudge the numbers to bring you down a peg.  Guns breaking down four days in a row in the first battle of the day. Constantl', 'Overwhelmingly Positive', 98.41, 5.12, 19.82);
INSERT INTO reviews VALUES (34522, 1292690, 1392, 'It''s a good game... but I didn''t know my friends on discord could see what I was playing.', 'The obsession of the creators to bring futa and gay into literally almost every scene is disturbing at this point. It used to be a good mix and there was something for everyone but in the past year every update has included a swath of futas and maybe it''s the creators kink, but it''s not my kink.', 'Very Positive', 91.45, 40.78, 136.13);
INSERT INTO reviews VALUES (34523, 1293160, 3603, 'The first thirty minutes got me crying so hard because i would like to have a chance to say a final goodbye to my father as well and make him rest easy to make me feel better.\nAnd she said it, people will do anything to have her power, well it''s a video game.\nWhat i didn''t expect, this outcome was made by the developer i despised so much, i think i gotta trust Bloober Team a little for Silent Hill 2 Remake.\n10/10 for the first 30 minutes that i''ve just experienced.\nGood luck with Silent Hill 2 R', 'Incredibly boring. The only thing this game has going for it is the atmosphere which is why I didn''t refund it within 2 hours, beyond that it''s just a walking simulator.', 'Very Positive', 88.90, 8.57, 2.72);
INSERT INTO reviews VALUES (34524, 1293820, 1668, 'If you''re actually going to buy this, buy it through Jast. The 18+ patch is pay walled anyways and is pretty much required to make sense of a decent amount of it.  \n\nGo in blind and avoid using a walkthrough as much as you can. It''s a truly unique experience that couldn''t be done in any other medium.', 'DO NOT PURCHASE THIS GAME ON STEAM. This is a censored version that cuts a significant amount of content. Buy the full version straight from JAST USA.', 'Overwhelmingly Positive', 96.04, 20.55, 5.28);
INSERT INTO reviews VALUES (34527, 1294760, 4140, 'so i MAY have refunded this (cant remember why) but this game is excellent. from the optional gore, to the gun skins, player skins, graphics, and enviornments, this game is great. cant wait to see whats to come (once i get the game again lmao)', 'Used to be really good, and now since the last couple updates the game became unplayable due to the horrible game optimization since the last couple updates. It just lags and lags and lags and it never did that before. I have a pretty beefy computer and it’s the ONLY game I’ve ever had that problem with. Instead of fixing their game they just say we have bad pcs or try to do this or that they just say it’s a you problem when when the actual problem is THE GAME. Really sad to see a good game bein', 'Very Positive', 86.45, 6.78, 9.12);
INSERT INTO reviews VALUES (34528, 1294810, 1613, 'The game made me realize how influenced we are by the opinions of others, we never give ourselves the opportunity to explore things for ourselves, we prefer someone to tell us what is good and what is bad. The truth is that little by little we have become toxic.', 'thanks for the refund 2 years later guys, very cool', 'Mixed', 41.04, 15.42, 26.35);
INSERT INTO reviews VALUES (34530, 1295500, 2736, 'Simplified  version of a 40k Warhammer Table Top Game. If this sentence appeals to you, you will like this game.  Community helps give this game life with Narrative campaigns. Devs continue to add factions post launch.', 'It''s a good game, but the fact that you have to pay for each update is absurd.\nCannot recommend', 'Very Positive', 88.19, 220.02, 21.45);
INSERT INTO reviews VALUES (34531, 1295660, 21913, 'It''s good. The pros of this game outweigh the cons. The UI is abysmal and seems to be designed by grey aliens or some other soulless being. I''m assuming they''re gonna change it at some point its that bad. They also locked Napoleon behind making a 2K account so they can harvest and sell your data. All that said, the game itself is extremely fun and the new features are for the better fun-wise comparatively speaking.\n\nEdit: Guys days later this game fucks so hard. Its so fun.', 'This game literally just ends in the 1940''s. No option to keep playing, no real feeling of satisfaction other than a screen saying "Victory". Its like they got halfway through it and just decided "lets save the rest for DLC" and shipped it.\r\n\r\nTo be clear, this game feels extremely incomplete, especially considering the size of it''s predecessors and the huge price tag.\r\n\r\nCoupled with a ton of visual bugs, units models showing where they''re not actually located, a HORRIBLE UI in a lot of the gam', 'Mixed', 50.71, 18.90, 18.55);
INSERT INTO reviews VALUES (34534, 1296450, 170, 'Amazing top down shooter. Art style reminds me of Borderlands. Not too difficult and really fun.\r\n\r\nRecommended 10/10', 'Dust & neon: mixed review from the outset, dust and neon is a casual style twin sticks action roguelike that incorporates permanent xp progression to unlocking boss encounters. The issue with the xp gating is that it becomes heavily padded towards progress/light on content, such as not allowing xp to carry over on rank up. The reload animation is merely a gimmick as you will be watching the reload circle instead. Even 75% sale is overpriced for what you get 5/10.\n\nAverage completion time: 15+ ho', 'Mostly Positive', 72.35, 11.85, 14.97);
INSERT INTO reviews VALUES (34535, 1296610, 9237, 'Fun game but a bad rougelike. Has plenty of fun orb combos and interactions with items. I highly recommend to people who are fans of Peg games. 7/10\r\n\r\nMy beef with the game:\r\nThe start of each run is by far the most boring, makes a disheartened me not want to continue. The uncertainty of navigation is a funny gimmick but is heavily outweighed with annoyance, a punishment is fine but that punishment of throwing my run isn''t (especially with some of the boards). Certain encounters are just over i', 'Look, this game is a fine roguelike\r\n\r\nUnfortunately, I''m starting to see a trend of roguelikes promising this exciting new gameplay, but instead it''s the same gameplay (right down to the map traversal and shop layout), with a minigame pasted over the combat\r\n\r\nTL;DR: If you haven''t played many roguelikes and like peggle, this is a fine option. But if you''ve played any number of other ones and are starting to see a pattern emerge, then maybe skip it', 'Very Positive', 88.22, 59.00, 1.58);
INSERT INTO reviews VALUES (34537, 1296830, 1236, 'hades but fun', 'The game is in serious need to making the starting progression less frustrated. It''s hard I get it but there are roguelites also very hard but offer more generous rewards on a failed run. I had 0 unlocks on a few starting runs and started the game all the same. The runs are not linear but also not too much different, as of now. I got the same weapons every run with a tad different stats, same actives, and upgrades are also super repetitive... May give a few more tries but the slow progression al', 'Very Positive', 94.66, 81.87, 1.87);
INSERT INTO reviews VALUES (34544, 1299170, 349, 'So I have been playing it for 3 days straight before writing this review. This game has not only scratched an itch that has been left unsatisfied since Rune Factory 5, but even integrates awesome features that feed my Pokemon addiction as well. Initially I was off put by the blobs, thinking they were too simple and just slimes, but I have found the breeding system to crossbreed and make more cosmetically awesome blobs a good way to continue the gameplay loop. In addition I joined the Dev''s disco', 'I''ve been enjoying the game so far but have 1 issue that''s been aggravating me. While fishing I got jumped by mobs and they wiped out my team. For some reason my character blacked out and it automatically moved to the next day while I lost all energy. This has happened to me twice. It''s not any fun losing all energy and moving to next day. Why is it a thing when my character could just run away when my team loses? I''m trying to maximize my tasks for the day and it gets ruined after losing. Worst', 'Very Positive', 93.41, 68.92, 25.38);
INSERT INTO reviews VALUES (34547, 1299400, 311, 'i dont understand', 'If you ever want to feel stupid, try this game. I do not want to give it a negative review, but I could not even make it past chapter three (out of what seems like ten chapters), and I could only fully complete chapter one. I may look up the solutions later, but that will ruin the fun (if there is any fun left after hours of mindless bruteforcing, because I can no longer see any logic or patterns in many levels past chapter one).', 'Very Positive', 91.00, 13.70, 5.12);
INSERT INTO reviews VALUES (34549, 1300600, 115, 'More people need to play this game, it''s so good! Incredible audio design, simple concept with so many creative twists, including a pretty wild story.', 'Well this was disappointing. A game that is stripped down to bare essentials - no graphics, and pure reactive gameplay using just your ears and one analog stick - has to have pretty amazing rest of the package. Blind Drive, however, doesn''t deliver.\n\nThe story is ridiculous, but not funny. What starts as a badly written (and narrated) B thriller quickly turns into a Carmageddon-esque craze followed by a Cartoon-Network style finale.\n\nThe gameplay gets repetitive really quickly. Hint to the dev: ', 'Very Positive', 93.04, 1.63, 1.20);
INSERT INTO reviews VALUES (34557, 1304400, 152, 'Don''t listen to the morons giving this negative reviews after 20 minutes. This is a wonderful game just like the dev''s previous title, Worlds. The dev is clearly very devoted to an open-ended design that completely refuses to hold the player''s hand and expects them to use their brain. Give it a chance!', 'Usually these types of first-person action adventure games are right up my alley.  Sadly, this one was not.  Game was obviously designed to have multiple playthroughs for different achievements, but there isn''t enough here to make it worth it.  When I wasn''t fully bored, annoying enemy design made the game far less enjoyable.  I couldn''t even complete a single playthrough without being bored to tears.  A shame as it doesn''t seem all bad, but I can''t recommend it.', 'Very Positive', 87.50, 6.48, 1.15);
INSERT INTO reviews VALUES (34558, 1304430, 107, 'I really enjoy this more than Medieval Dynasty, the Atmosphere is great and you can see that Viking Frontier is actually geared for Singleplayer.\n\nThe Performance is kinda an issue, especially for what''s listed on the Steam Page Hardware requirements.\n\nHaven''t experienced any bugs so far and the gameflow is nice.', 'Built a hut. Froze to death. Raided a village. Starved to death. Crafted a fire. Died of sadness. This Viking life hits hard—but so does the framerate. Game’s not bad, not good… just not done. Should be Early Access but has potential. 5/10, would cry into mead again. 🪓❄️\n\nFollow my curator page for more sagas of survival, tragic taverns, and unfinished adventures! 🏕️📜✨\nhttps://store.steampowered.com/curator/42602807-Osiris-Reviews/', 'Mixed', 60.75, 4.23, 0.63);
INSERT INTO reviews VALUES (34560, 1304610, 183, 'I have not quite finished this game thus far, however I can say that this is a fantastic indie puzzle game. It is incredibly simple however the puzzles have oh so satisfying solutions, enough new gameplay concepts get introduced to keep it fresh and a really nice artstyle and story. I have found other indie puzzle games to be lacklustre however this is not. it has some nice references and neat humour and the voice acting is great. \r\n\r\nI am super glad that steam has a really good algorithm and ma', 'The puzzles are ok, not great, not bad either. But the story/humor are so bad that they are unbelievably annoying after a few moments. It tries to somehow mimic the humor of Portal, which I love, but fails.', 'Overwhelmingly Positive', 97.27, 9.70, 2.58);
INSERT INTO reviews VALUES (34562, 1304930, 26169, 'I was playing with a black character and my friend was playing with a white character and the cop decided to keep chasing me. Very realistic 10/10', 'Removing parts of the game and regurgitating them as random weekly trials doesn''t make me come back weekly, it makes me quit playing.', 'Very Positive', 94.47, 233.03, 96.57);
INSERT INTO reviews VALUES (34565, 1305080, 412, 'I''ve always been looking for a game where you can create vehicles from scratch, this game goes above and beyond, not only can you build vehicles, you can build whole engines down from the pistons to the firing order, to the output shaft it lets you build transmissions gear by gear, fantastic game. It took me 12 hours to build a simple rear wheel drive car with a steering rack and suspension. This game is definitely worth the 15$, Absolutely fantastic work from the developer.', 'why the fuck am i not just a camera being a person serves no purpose other than making the controls fucking janky go look at besiege and fix this shit make it so you can spawn bodies you can control if you must but this is goomber as fuck to control', 'Very Positive', 88.59, 27.17, 1.88);
INSERT INTO reviews VALUES (34574, 1305300, 107, 'Girl chases you and calls you BAKA\n\n10/10', 'I would not recommend this game. While the story and concept are very interesting, the actual gameplay has some major faults. The map randomly generates every game, and on top of that the map is outrageously huge. Normally, I would enjoy such a large map, but in a game where you''re constantly being chased around and needing to search for items a large map quickly becomes disorienting and confusing. On top of that, the actual directions for how to gather complete other endings is very confusing. ', 'Overwhelmingly Positive', 95.33, 9.18, 5.67);
INSERT INTO reviews VALUES (34575, 1305310, 212, 'It''s an interesting game but I feel like once you''ve beaten a couple sectors you''ve kinda seen it all. Was really hoping for some cosmic horrors mixed in with all the starships and dogfighting but I haven''t encountered anything scarier than a touhou-like bullet hell of missiles and energy projectiles.', 'I did enjoy this title for a time, it gave me the mindless ARPG kick and with a nice little twist that was actually meaningful. However, as I play longer I find neither the ARPG part nor the twist, i.e. the simulated world that gives meaning and character to the gameplay environment compared to the usual hand-crafted ARPG environments, offered the creative playfulness and depth required keep the flame going. I believe the title would be much better if all the simulated environment would naturall', 'Very Positive', 90.57, 88.32, 9.05);
INSERT INTO reviews VALUES (34581, 1305420, 414, 'MAKE THIS GAME 1 DOLLAR AND I WILL SINGLE HANDEDLY REVIVE YOUR ENTIRE PLAYER BASE', 'no player only me in game', 'Very Positive', 81.16, 44.78, 0.23);
INSERT INTO reviews VALUES (34619, 1306620, 299, 'I would give this a negative review, however I like chilla''s art and their games, and I like the core idea of this game overall, but would not really recommend it because its so short, and the player is so uninvolved in the story that it is left as uninteresting and forgettable. i really have no idea what the story even really was about, the little snippets you get of the lives of the kids youre investigating isn''t enough to give a clear sense of what''s actually going on, but the exposition of t', 'Feels more like a walking sim without any scary moments, the puzzles are just "find item x for y" and all the characters always have the weirdest items with them for some reason just to give them to you. In addition, all the dialogues seem... strange anyway, whether that''s because of the translation or I just didn''t understand some surreal metaphor here... no idea\n\nThe characters are so strange and "accommodating" that I constantly thought it was all just a manifestation of our guilt, blah blah ', 'Very Positive', 85.28, 1.15, 1.38);
INSERT INTO reviews VALUES (34620, 1306630, 1046, 'The game is kinda hard BUT IM HARDER !', 'At first I loved this game, as I''m a fan of 2D souls-likes... that said, after a while it feels like a lot of cheap & unfair game play keeps coming up. Very disappointing, this is no Blasphemous or Momodoro. You die too often to situations where skill and reflex mean nothing. For example, you might do some tricky platforming only to be killed by a fireball from off screen while the devs clearly planned for you to be in a position where you can''t avoid it, all after you just spent several minutes', 'Very Positive', 86.04, 23.23, 2.62);
INSERT INTO reviews VALUES (34621, 1306720, 189, 'Хороший битемап, хотя и несколько медленный. Необычный интересный сеттинг, есть история и даже реиграбельность (хотя и всего на один раз, открыть альтернативный маршрут). Рисовка а-ля SOR4 очень подходит современным битемапам и, похоже, становится стандартом, что круто, т.к. она сохраняет и брутальность и некоторую ребячливость. В общем, рекомендую и сам жду вторую часть.', 'This game pissed me off and I don''t know why', 'Very Positive', 87.83, 2.68, 0.75);
INSERT INTO reviews VALUES (34637, 1307090, 227, '+ relaxed racing minigame \n\n+ all achievments work\n\n+  Singleplayer or Multiplayer possible', 'Unpolished Unity graphics. Gameplay is somewhat customizable, but there is nothing to do except press the acceleration button non stop, and opponents are invariably too easy.\n\nOffers achievements based on level wins, and cards. Expect 100% in less than an hour, after which there is little to no replayability.\n\nFor the content offered, definitely not worth the full price, but might be worth a shot if you can snag it at a deeply discounted price. 4/10', 'Very Positive', 80.18, 7.03, 0.52);
INSERT INTO reviews VALUES (34657, 1307550, 7183, 'Palworld without Pals, but with much more different mechanics, game-systems and MUCH more bugs and unfinished pieces.\n\nAlso, because Palworld is out (from same developers) - this one will be in early access forever now.', 'Don''t buy this game until full release. There''s no sign of the game being near to completion and instead finding people to finish this game first, they made Palworld. Might as well treat this title as abandonware until proven otherwise.', 'Very Positive', 81.14, 511.57, 4.33);
INSERT INTO reviews VALUES (34659, 1307580, 2279, 'TOEM is suitable for all audiences. Everything from its friendly nature, to the ease of control, to the cute characters and catchy tunes, TOEM hits the mark in many ways. Though I wish it were longer, a part of me thinks the short length adds to the simplicity and relaxation aspect of the experience. It was just so inviting, especially during days where you want to do something easy and not necessarily feel too challenged, making me wish there was more content and areas to explore. TOEM 2, perha', 'The game came off as super charming and i loved it up until it decided to glitch out and not give me a quest item after showing a character the correct picture. Now i can''t show them the picture again and their dialogue loops. Locking me out of 100% the game without replaying up to that point again.', 'Overwhelmingly Positive', 99.30, 6.58, 1.55);
INSERT INTO reviews VALUES (34662, 1307660, 477, 'Great game. Better Viking game than Ac Valhalla', 'Don’t waste your money on this game , developers abandoned this project.', 'Mixed', 55.56, 7.02, 0.68);
INSERT INTO reviews VALUES (34664, 1307690, 193, 'As a professional bear lover, i approve this game. Game was good, but bear was great.', 'Nice graphics. There is not enough detailed map, useless portals, only making things even more confusing. Almost half of the ability improvements are hidden or not available until the end of the game, you need to look for them after completing the storyline, but why are they needed then?......', 'Mostly Positive', 76.17, 13.10, 8.42);
INSERT INTO reviews VALUES (34665, 1307710, 1120, 'A great arcade racing game. If you are expecting a sim, don''t bother. The story is great and compelling, but it is obvious the writers aren''t very interested in cars or racing. The story never changes track whether you finish 8th or 1st, very irritating that on the hardest difficulty I can win every race and still have my team tell me I suck and "need to prove myself". \n\nAI are very competitive and hold their own without rubber banding or cheating. Physics are a nice blend between realistic and ', 'THE WORSE AI\r\n\r\nSeriously, this game has the worse ai of any racing game i have played. It is a game that i want to love so bad, but the ai makes it unbearable to play. Everytime i hop on, it leave mad, because they simply do not know how to drive. This is a shame, because this is a game that had a lot of potential and has been ruined by a single element', 'Mostly Positive', 75.00, 2.23, 56.53);
INSERT INTO reviews VALUES (34673, 1307870, 180, 'Short but very interesting game. Cool soundtracks. A lot of secrets. Final section is also cool. Overall it''s a good game.\r\n\r\nI really like the idea of  giving the player a game development museum as a reward for solving the tree puzzle ', 'I thought there was a story because it seemed someone wanted to build a human-like robot or something that can sense touch, taste, sight, smell and hearing. However, it was nothing. (At least that''s what I think.) In every section has some lore-like stuffs that tried to tell you some back story but nah. It was just a part of puzzle.\n\nNow, puzzle itself has middle difficulty. You need to think a little harder for final and secret one.\nThe WORST one that the main reason I don''t recommend is "every', 'Very Positive', 93.33, 10.47, 2.53);
INSERT INTO reviews VALUES (34675, 1307890, 4211, 'This game has some weaknesses - the card system still feels a bit lackluster, possibly because (at least as of the time I write this review), you always seem to end up with more cards than you need, making the whole system kind of pointless. The military also feels like it needs a huge rework, because right now it''s just annoying enough that you feel some obligation to interact with it, while still being pointless enough that it doesn''t really matter.\r\nThat being said, if you just play this game', 'It''s OK. I don''t understand the crazy praise for it in the reviews. It doesn''t really do anything new from similar games in this field.\n\nThe cards to build buildings feature might feel new, but it is actually just a roundabout way of having a build menu. How? Well because you get random cards that allow you to build buildings, right? But you also get wild cards that allow you to build anything you want, and you get them pretty much nonstop. So you can just build anything you want with the cards,', 'Very Positive', 90.10, 53.50, 2.07);
INSERT INTO reviews VALUES (34705, 1308700, 114, 'You have to like these old games, it must be your thing or you will not like this one. It''s classic, and it''s niche and it''s unforgiving.', 'I don''t know, I can imagine giving this game a thumbs up but the UI/sound settings and graphics are incredibly crude. If you really, really love this type of games, it''s good. It''s pretty playable. But it feels like a shareware game from 2007.', 'Very Positive', 80.70, 51.57, 3.92);
INSERT INTO reviews VALUES (34739, 1309610, 748, 'I like the game very much! Gameplay is easy to learn - hard to master. After few games it becomes easy to defeat the hardest AI. But the problem is that the game has very low online. And few players who always online are unwinable for simple mortals like me. I still manage to find games and even win in peak hours. I really wait for new updates and hope there will be more new players in the future!', 'This is a negative review, only because the controls of the game. I must say I LOVE the concept of this game, however, it just feels wrong to not be able to select units. There is times where you only want to move a couple units and you cant.\r\n\r\nAlso for the 4x element of this game, playing tall is impossible. Not a big deal, but it would be nice to have more than 1 winning strategy, which is currently expand fast. You can''t turtle down and build up. Remember the good ol days of Red Alert 1, cho', 'Very Positive', 80.88, 42.78, 1.55);
INSERT INTO reviews VALUES (34740, 1309620, 284, 'High on Life but with actually snappy gameplay and not written for Redditoids.\r\n\r\nAlso probably the closest thing we''ll get to a non-cringe Borderlands 4.', 'It''s impressive how much a small team was able to accomplish.  The scope of what they tried to do is huge, but the level of polish on the final product is low.\r\n\r\nThe game can be boiled down to two things: FPS arena fights, and secrets that mostly take the form of little comedy skits.  Some of the comedy lands, and some of it doesn''t.  It''s a toothless brand of comedy that aims to be wacky without poking fun at anyone or anything in particular.  There''s joy to be had in exploring a level and dis', 'Very Positive', 94.01, 14.35, 15.25);
INSERT INTO reviews VALUES (34748, 1309820, 189, 'While most of it was done in 12 hours here it''s a pretty solid game for early access.   No major bugs worth commenting about.   The commuinty it supports is very positive and the developres also willing to answer questions in a freindly realiable manner.   So yes well worth the price, as all that espcially the community it has so far and dev behaviour towards questions.   A rare thing to see these days.', 'nothing is changing in tyhe content you can finish the story in 1 hour', 'Mostly Positive', 78.31, 12.10, 24.43);
INSERT INTO reviews VALUES (34755, 1309950, 1064, 'such a strong personality on this game. really melds a bunch of different artistic sensibilities into an anarchic hodgepodge that makes for an intense audiovisual experience that i can''t help but smile when i observe it. the gameplay is rather simple in premise, but in execution, is a satisfying sequence of executions that you feel like a true marksman for being able to finesse. i shan''t divulge any more, please go in as blind as you can and just experience it for what it is, but damn this is a ', 'Cool. You play as an alt-girl who really love murdering zealots. Visually and sonically this game is great, the gameplay is essentially a puzzle/top-the-leaderboard type of game (its fun).\n\nHowever positives aside this gets a very simple reason for a not recommended. The game totals around 2 hours. You are introduced to new mechanics that never really feel fully capitalised on due to the lack of levels. The game needed at least twice the number of levels and also a community level editor of some', 'Very Positive', 93.05, 2.63, 2.28);
INSERT INTO reviews VALUES (34757, 1309990, 123, 'A simple but fun game. Honestly, if I have a complaint its that the game has a neat idea, but it doesn''t quite do enough with it. I feel like a lot more could have come from it. 7/10', 'Game breaking bugs killed my fun.\nRestarted a new game and bug happened again.\nIts has not been updated for almost a year\n\nAvoid purchasing this game', 'Mixed', 55.28, 3.85, 31.70);
INSERT INTO reviews VALUES (34765, 1310330, 993, 'It''s melancholic, a bit gay and definitely woke but so am I so I find it kind of nice. Totally not GOAT, for in the end it does not have branching storylines, the dialogue choices won''t have a significant effect and even if you would like to go rather offensive with the stressed dialogue option it just flattens out by actual dialogue which is played by your choice. So yeah - even if I said I am woke, I still wouldn''t mind that the game had a bit of spice in it. I do act like a jerk sometimes whe', 'I can''t really recommend this game to anyone. As with any game, you have the good and the not so good. This title had too much going on in the story to cover in 8 or 9 chapters. The story isn''t long enough for the price of the game. I never really got a chance to know the characters and stay in a conflict long enough to see them grow.\r\n\r\nThe music is very good and the characters would be interesting if I had more time to know them. It was a good idea, but it didn''t have any direction.', 'Very Positive', 88.82, 7.25, 8.03);
INSERT INTO reviews VALUES (34768, 1310410, 1094, 'It''s a pretty good game.  I am enjoying it immensely.  The only thing I wish is that they had a separate map button instead of putting everything under I.  It takes a toll on older machines but is still playable with 4G of dedicated graphics RAM.  But honestly, I am enjoying it immensely!!!', 'i''m stuck in oil pump location glitching i can''t move farther even if i restart the checkpoint still i can''t go farther! fix this stupid game!', 'Mostly Positive', 79.52, 23.02, 5.83);
INSERT INTO reviews VALUES (34772, 1310510, 457, 'lethal company 0.1', 'even just seeing the main menu made me not want to play, once i got in game it was not any better. the voice chat was just so muffled and quiet (also once you die you can''t even chat with dead people?), i had no idea what i was doing and the map generation was boring. I only played one game so maybe i just had bad RNG with the map generation, but the voice chat alone puts me off.', 'Very Positive', 91.25, 0.72, 0.35);
INSERT INTO reviews VALUES (34783, 1310910, 746, 'I did not know Steam showed my friends what games I play.\n', 'I really have no idea why did i bought this game. Not much of fun except finding a empty void in myself. LOL', 'Mostly Positive', 74.53, 5.02, 2.35);
INSERT INTO reviews VALUES (34787, 1311070, 339, 'A very good metroidvania with some puzzle aspects. Eventually you get to control all three characters at once. The story is interesting. The hand drawn graphics are very pleasing and the music is also great. The game is a good medium length. Nothing was too challenging. \r\nThe only downsides would be that the map isn''t detailed so you can''t see exactly where you are in each area. Plus you get the third character pretty late. \r\nOverall I enjoyed this game and recommend it for fans of the genre loo', 'This is a really fun game killed by the fact that the two characters don''t stay in sync when moving around.  I can''t tell you how many times I''ve been killed because one caught a ledge, made a jump, or hit a bouncer and the other didn''t.  I otherwise enjoyed this game, but I couldn''t take the sync issues, despite extremely liberal use of the right trigger to pull them together.\nIt''s also annoying that the map is nearly useless.  I''d explore everything for quest 1 only to have to go back over it ', 'Mostly Positive', 79.94, 17.98, 4.63);
INSERT INTO reviews VALUES (34806, 1311570, 139, 'It''s Descent but it looks like it was made in 2001 and is a sort of roguelike.\nPew pew is fun, moving around while pew pewing is silky smooth.\n\nIf any of that made sense to you then you probably already decided if you want to get this.\nCongrats devs on the full release.', 'No way to keep progress.\r\n\r\nIf you die too many times it wipes everything and you have to start all over. That''s not fun.', 'Overwhelmingly Positive', 97.12, 14.82, 0.52);
INSERT INTO reviews VALUES (34852, 1312960, 193, 'Very Very good game. Bought it on sale for 1.99.\n\nYou can fry rats in this game and eat them. Yum yum yummy I want ratties in my tummy.', 'It is a cute game with a ton of potential but the movement speed/speed of time passing ruin the game. Especially the movement speed. I am going to give it another go with a youtube video in the background but can''t recommend at this time.', 'Mostly Positive', 77.72, 2.93, 15.40);
INSERT INTO reviews VALUES (34858, 1313140, 50300, 'The love I have for this game, despite not playing much recently, is vast and hard to put into words. Rest in peace Narayana Johnson/River Boy. You were one of my favorite artists, and thank you and everyone else for making this game so beautiful.', 'Aside from the cute art, the game is very underwhelming.\n\nThe rougelike aspect is grindy and boring. To get to each boss for the area, you have to get to the boss room 4 times. You get barely any upgrades throughout your run so there is very little progression, you start and end each run playing the exact same way. There are only 6 weapons with very basic moveset consisting of just light and heavy attack. Apart from the blunderbuss that you get much later in the game, the other 5 weapons feel wa', 'Overwhelmingly Positive', 96.20, 74.73, 11.05);
INSERT INTO reviews VALUES (34880, 1313860, 12841, 'yes', 'not working', 'Mostly Positive', 75.68, 1749.47, 0.87);
INSERT INTO reviews VALUES (34886, 1314000, 599, 'Finished the entire game, every cave, fight, main quest, side quest the game had, ONCE. It took me 20 hours.\r\nOnly 2 bugs I found: 1, I got stuck in between some terrain rocks after rolling too much (game has an unstuck button clearly for these so easily solved) and 2 the "cart wheel side mission" got bugged on my end because I found the item before the quest giver gave me the mission and some flags seem to not be correctly setup. A very minor side quest, but the only one I "didn''t finish".\r\n\r\nO', 'I don''t like souls like games and I really should have paid better attention to the tags. This game has everything I hate in a soul like game in it. It took me only 11 minutes to know I wanted a refund.\n\nI really thought I was buying an ARPG not an Action RPG. Joke''s on me I guess. Also, to people who like souls like games, how can you stand the clunky controlls? I''ve played my fair share of games with a controller and soul like games are just bad, no matter what I do. And I don''t mean hard, I m', 'Mostly Positive', 79.47, 20.05, 0.18);
INSERT INTO reviews VALUES (34890, 1314140, 238, 'Get it on a big sale, otherwise it''s way too overpriced, also it has a fair share of bugs, but other than that, a great simulator that has no match on the market... for now at least.', 'The basis is great, Vienna has never been built more accurately.\n\nHowever, this game received zero optimisation, zero extension, zero support after release.\n\nI do not write reviews often, but this deserves to be seen. A game with great potential left to die a painful death.', 'Mostly Positive', 71.85, 22.38, 36.03);
INSERT INTO reviews VALUES (34910, 1314820, 186, 'It will help you learn to fly but its expensive for what you get', 'flys well, its insane how expensive even this feature gutted version is tho. if i had to do it again i would have just stuck to the "high seas" if you catch my drift. the new update added some cool planes, maps and multiplayer support but the ui is so god awful. ive seen better design on roblox.', 'Very Positive', 81.72, 7.88, 40.60);
INSERT INTO reviews VALUES (34925, 1315200, 253, 'It''s buggy, hard as hell, and the pathing is still not working properly (sometimes to your benefit). But I am powering through it via sheer nostalgia. I will finally beat this series.', 'The game is an amazing game. However, the game keeps crashing for some reason, I can''t figure out why...', 'Mostly Positive', 76.68, 56.08, 8.13);
INSERT INTO reviews VALUES (34935, 1315610, 458, 'The game is a mix of both good and bad, with elements that seem to clash. Instead of calling it simply bizarre or alien, I think terms like ''chaotic'' or ''confusing'' better describe its nature. It feels like a glimpse into true, indescribable madness that resists easy explanation. I believe it could have been much better with just a bit more refinement and focus.\n\n\n어쩌면 이런 것이 형언할 수 없는 광기인걸까.', 'Its better to have a finite amount of purposeful art and interactions than an infinite amount of baffling graphics and enemies that just simply are not interesting', 'Mostly Positive', 76.86, 40.52, 1.50);
INSERT INTO reviews VALUES (34952, 1315980, 653, 'requires a learning curve but is very enjoyable to learn each system and troubleshoot in stressful situations\r\n\r\nunfortunately feels a lot like work for me...', 'The concept seemed interesting, but in practice was a complete waste of time. Don''t bother unless thumbing through tech manuals, and memorizing what errors and symptoms indicate, before you even try a scenario sound like fun to you. It wasn''t for me.', 'Very Positive', 83.31, 14.82, 0.62);
INSERT INTO reviews VALUES (34962, 1316230, 605, 'It is a good game. I get all my games on sale and $7.99 was a steal.\n\nIt is cheaper than a McDonald''s burger here in California and won''t give you a heart attack :D', 'I did have fun and for $15 it''s a price point. However The game is too grind heavy. I like to grind things but the amount of things to grind and progress mixed with sitting around laterally watching my screen waiting for something to craft just killed it for me. If it didn''t have the waiting and so much grinding it would be good but can''t recommend because its just draining.', 'Mostly Positive', 73.39, 118.52, 16.33);
INSERT INTO reviews VALUES (34968, 1316390, 125, 'This is a very pleasant collection of sudoku with a great little twist.', 'Now I want to emphasize that this isn''t a bad game by any means. This is actually pretty good sudoku with a nice twist and quality of life features, but that''s the problem... it''s JUST some good sudoku... with a twist... and some quality of life features. I just don''t see the point in buying this when there are plenty of free versions of sudoku that are close to if not as good as what''s provided here. Like, there''s not even background music so you''re gonna have to provide your own when playing u', 'Overwhelmingly Positive', 96.00, 64.08, 6.88);
INSERT INTO reviews VALUES (34976, 1316680, 1609, 'It''s basically Russian Half-Life & The Last of Us but for $10 lol.', 'I don''t understand like half of the positive reviews. Sure, on a technical level the game functions well, which already deserves some praise these days, the graphics ain''t bad either, but when it comes to the gameplay - I don''t get it. \nPeople keep comparing it to games like HL, Doom, Painkiller etc... It tries to imitate those games on a surface, but deep down it''s a shallow shooter with hoards of enemies running in lines, with the AI acting more "A" than "I". \nAnd FFS, whoever did the voice li', 'Very Positive', 88.56, 10.53, 1.45);
INSERT INTO reviews VALUES (34982, 1316800, 116, 'Fun, easy, yet lots of depth.\n', 'Simple arena survival game with a small variety of weapons and abilities. I''ve got a little over 3 hours in this game and roughly 3 million points. I''m reaching a point where it''s losing its replayability; there''s a single map and the only real variable element is the limited perk selection. There is no unlockable element between runs, just the cumulative points total going up. It doesn''t feel like any real progression is being made. The max achievement is for 100 million points, which based on ', 'Very Positive', 91.38, 3.45, 3.78);
INSERT INTO reviews VALUES (34985, 1316910, 1083, 'This game is evil incarnate.\n\nThe perfect xmas gift for your Roblox / Fortnite addicted little cousins.\n\nps: Kazuma Kiryu is in this, IKUZOOOO! And the modding community did some godlike stuff on PC, go check it out if you get hooked.', 'I originally had this as a recommend. cos it''s a fun little physics platformer, with some rough edges that i chalked up to it being a 20 year old game......\n\nwell i played the original on an emulator recently. the original has 0 of the jank of this "remake." the physics are wrong, the control is wrong, the camera is wrong, the format is wrong, the banana placement is wrong.... "why does every level force me to backtrack for exactly 3 bananas?" because whoever designed this remake is a talentless', 'Very Positive', 83.84, 4.65, 1.28);
INSERT INTO reviews VALUES (34988, 1317020, 471, 'better than Elden Ring', 'I didn''t put a lot of time into this because it was too retarded. If you like kaka peepee poopoo humor then this might be for you but It ain''t for me.', 'Very Positive', 91.72, 1.02, 0.27);
INSERT INTO reviews VALUES (35003, 1318090, 990, 'it’s a fine vr game to get if you’ve just finished half life alyx and need to scratch that itch a lil further. story is minimal which i thought was kinda lame until i started vertigo 2 and realized what a blessing that was, and there’s some fun weapons here! pretty much every weapon doesn’t require both hands, including the minigun, which i found benefitted from single handing. this is also the only vr game ive played which includes a grenade launcher and that by itself is fun to use even if its', 'I love what this game was attempting to do. The overall concept and vibe was good.\r\n\r\nBut there were just too many poor game design and level design choices. About half the time I was not enjoying myself, but rather just getting through it. I lost count of the times I thought, "oh... okay... this again?" or some other uninspired feeling. The boss battles should have been cool but they were just tedious. Especially the giant fat alien one towards the end. Just a chore to get through. Games aren''t', 'Very Positive', 93.43, 4.30, 7.68);
INSERT INTO reviews VALUES (35023, 1318690, 7564, 'Essentially a lightweight, abstract version of Factorio. shapez ditches various "superfluous" elements of Factorio, like resource management. defense, and vehicles, to focus on the core gameplay of building the factory. The idea to use shapes as resources is pretty clever as it allows for loads of combinations that are intuitive to create (not needing a recipe tree or anything). Definitely worth the price. Also check out shapez 2!', 'Shapez is a factory game that doesn''t feel rewarding when you build factories.', 'Overwhelmingly Positive', 96.63, 21.22, 1.38);
INSERT INTO reviews VALUES (35026, 1318740, 254, 'Sad to see such good game be abandoned by dev, it has a lot of potential.', 'Tense and hectic early games that quickly devolve into end-turn-button mashing despite the timer, the feeling of any planning or strategy undercut by reliance on far too much RNG, weird balancing and tedious resource costs. I loved the first three missions, but after that the game was tedious even when using Cheat Engine - mostly for, as other reviewers have pointed out, circuits.', 'Very Positive', 92.91, 14.72, 8.85);
INSERT INTO reviews VALUES (35034, 1318970, 118, 'It is like Cthulhu Saves the Christmas, but you are Magical Girl who is saving Shakespear from Cthulhu.\nAnd I am sure it makes sense, at least it must make sense - thought, I haven''t found it yet, only insanity so far.', 'FYI : still has a gamebreaking bug. Saving in the backstage area will permanently brick your save, sending you back to the first post-tutorial area. This will be unsalvageable, and you''ll have to delete and start over no matter how far into the game you were. After two restarts because of this, I''m regrettably giving up on the game. Maintain multiple saves.', 'Very Positive', 89.83, 80.03, 12.82);
INSERT INTO reviews VALUES (35047, 1319420, 340, 'Great aesthetics, convoluting story which leaves a lot for interpretation, but quite enjoyable. The game drops you in an open world with little to no hand holding. You have to pay attention to ''visions'' and dialogues to get your objectives. I don''t like the comparison to Silent Hill, this game is its own thing. The game is around 4-5 hours in length and doesn''t overstay its welcome.\n\nAll in all a good game to pick up this sale if you''re into creepy narrative games.\n\nSide note: I hate the name of', 'It could have been a good game with a little bit more gameplay. But walking simulation isn''t enough for having me captivated. No fights, no riddles. Just exploring with an annoying backtracking.\n\nIt is not a horror. Mostly like a thriller. A weak thriller.\n\nAs a verdict, I can''t name this game as a bad game. But moreover, I can''t name it as a good one.\n', 'Very Positive', 89.41, 4.88, 5.65);
INSERT INTO reviews VALUES (35049, 1319460, 557, '0/10 - Not Gay Enough', 'Fun concept, great style, but by the final 1/3 of the game, the enemy encounters become unbearable slogs. So much of the combat encounter design sets you up to take gobs of unavoidable damage, then "apologizes" afterwards with health drops to build you back up.\n\nHaving to switch weapons to deal with different enemy types is a potentially interesting idea, but in practice, it literally ruins the game by the end. Being swarmed by different enemy types in a tiny space (like a rooftop) creates situa', 'Very Positive', 91.74, 0.70, 3.27);
INSERT INTO reviews VALUES (35052, 1319550, 183, 'I love this game and can''t get enough of it! I just love to vibe with it and get in the zone. The creamy color palette is just beautiful, and fitting with the pixel art. As if the aesthetic wasn''t enough, the mechanics feel so good too. I''m playing with a controller on pc, and it feels great with twin stick control. There''s a little bit of drift when stopping, little details like that. Feels like an elevated addition to the bullet hell genre. I''ll think I''ve had enough but I keep coming back aft', 'A lot of dead space. High travel times. You''ll spend most of your time flying through empty space with nothing to do but hope the next destination has a purpose.', 'Very Positive', 82.51, 58.53, 0.55);
INSERT INTO reviews VALUES (35064, 1320100, 402, 'i can fit like 20 raccoons up my ass. \ntrust.', 'Interesting concept, poor execution. This isn''t a $15 game. Its barely a $5 game.\n\nThe art assets are mostly purchased, none of them make sense. Why are people walking around in sleeveless shirts in the snow?\n\nThings don''t reset properly after you respawn. Eg, a guard will enter a room, capture you, you respawn and the guard is already in the room with you when you respawn. \n\nThis has the potential to be a fun game, but the developer needs to put a lot of time into it.', 'Mostly Positive', 75.12, 4.40, 0.40);
INSERT INTO reviews VALUES (35066, 1320140, 1428, 'Small Saga really went "to live one''s life seeking revenge is to live one''s life as a ghost" and "to cling to old ways and religious traditions blindly is to offer oneself up for slaughter" and "to resist fascism through violence is never equivalent to fascist violence" and "Disability is a struggle that can and will drain and sap you of all energy but friends and support are vital for perseverance" and "even if there are but few of you it is always your duty to organize and protest" and "those ', '8-9 hours to beat the game, which is okay but not great. The combat was also very, very easy, with me dying once throughout the 8-9 hours. The story was maybe a 6/10, and is quite heavy on the woke messaging.', 'Very Positive', 94.96, 6.27, 8.28);
INSERT INTO reviews VALUES (35085, 1320950, 175, 'A half-hour walking sim game with mild horror elements and a confusing story. Like the store page shows, the primary horror comes from pig people. There are no jump scares.\n\nThe gameplay is all around exploring different areas of a house. Each day the player is given access to specific rooms to restore memory, receive a tarot card and encounter pig people, then it''s the end of each day. It would be better if the collectibles can be highlighted, I almost gave up on the fourth day because I didn’t', 'This one was alright. Personally, I wouldn’t recommend it, mainly because there are better options available in the same price range. However, if you feel like you’ve played most games at this level and you''re just looking for a quick change of pace, this could still be a decent pick.\n', 'Very Positive', 82.29, 0.57, 1.22);
INSERT INTO reviews VALUES (35090, 1321070, 265, 'Not the most interactive FMV game, and yes it is basically linear, but it was an enjoyable way to spend a couple of hours on a lazy afternoon. Ran perfectly on steam deck, but I would probably only pick it up on sale as it is relatively short.', 'Did the line "from genius creator of the Danganronpa series" also entice you to give this game a go expecting interesting story twists and a story that would keep you glued down for hours?\n\nI''m sorry to say that this sadly will not give you a Danganronpa experience. The story is very linear and you''re basically just clicking through a very short story. After less than 3 hours I had found all secrets, unlocked all achievements, and the entertainment value was not THAT high. You may still enjoy it', 'Very Positive', 81.13, 3.92, 2.92);
INSERT INTO reviews VALUES (35096, 1321230, 106, 'Very short but good enough to tell us about the past of Eddie. He was such a sweet little boy who lost his way due to his family...\n\nI think the ending could have had a bit more drama to it. Felt like that part was too quick and not as touchy as I''d like it to be, but oh well.\n\nRecommend to pass the time and for those who would like to know more about this character. Things make a little bit more sense now! Wish we could have more of this for the remaining floor owners :3', ' A very disappointing spinoff game \n\nI''m sorry, but that wasn''t very good. This review will be full of spoilers, by the way. I can''t believe this is from the same developer that made Angels of Death. This feels like a fangame made by people who were allowed to use the license. It''s not good. The story is mainly about kids being beat up and animals getting hurt and killed. That''s it, and it''s not even done in an interesting way. The main character, Eddie, constantly gets beat up by his older brot', 'Very Positive', 93.40, 1.85, 1.77);
INSERT INTO reviews VALUES (35097, 1321270, 244, 'pretty goated game', 'Every single thing in this game feels like it was specifically placed there to piss me off.', 'Very Positive', 90.98, 41.55, 17.02);
INSERT INTO reviews VALUES (35100, 1321440, 5360, 'I liked the game, my only problem is that I can''t play it due to the flashing parts. But I def would recommend to friends, just wish I could toggle off the flashing bits.', 'TL:DR: What starts as an innovative and exciting experience unfortunately ends up devolving into a mundane and messy one.\r\n\r\nI appreciate the innovation when it comes to the platformer and traversal aspects, however the camera angle and movement made several encounters very janky, repetitive, and a chore. As for the battle mechanics - the forms and walls are a welcome addition. While I appreciate the wider variety of types and advantages, this turns into a spreadsheet headache if you care about ', 'Overwhelmingly Positive', 96.32, 3.95, 30.15);
INSERT INTO reviews VALUES (35101, 1321450, 438, 'i love stealing from people\r\n', 'It''s not a game, it''s a piece of fucking shit! Cars and pedestrians materialize out of thin air, the game itself freezes at launch, textures lag, and there is no optimization. NPCs communicate with gestures without words (voice acting just disappears). How could such a thing be released and sold for money? This game is trash! She belongs in a landfill. The developer''s attitude towards gamers is just piggy. It''s just an unfinished piece of fucking code. I regret the money I spent.', 'Mostly Positive', 76.94, 20.97, 18.63);
INSERT INTO reviews VALUES (35106, 1321680, 1075, 'I really don''t get all the hate I''ve seen this game get. I thought it was a fun story to play through and has been a fun game to come back to every few months and burn through again. \n', 'Honestly pretty good, but this is probably the most "broken promise" of a game of all time. They really needed to deliver and they just DIDN''T.\n\nThey ARENT finishing the game, they LIED during development, and the games story is barely even there anyways', 'Mostly Positive', 75.91, 6.78, 29.85);
INSERT INTO reviews VALUES (35114, 1322100, 138, 'This game is so creative and fun to play with friends. I wish more people played it. I love it', 'Fun but way too unbalanced ruins it. not grinding more to just be able to win', 'Very Positive', 89.86, 13.52, 16.02);
INSERT INTO reviews VALUES (35115, 1322170, 152, 'It is not dear ester but I still liked it. For me it was the best one of the couple of games I played by this author. Space speeds you up btw ;)', 'You know this could be a really good escapist immersive walking sim but it''s half assed. If this and Chionophile which I am yet to try are Bodur''s highest rated games, how bad can the others be? A scary thought. To some extent it has to be an issue of working with UE4, but some decisions seem asinine, like aggressive clip brushes, god forbid I want to have a look around in my have a look around game! Why does picking the "flower key" create an obnoxious filter around me so I can''t enjoy the some', 'Very Positive', 90.79, 0.53, 0.68);
INSERT INTO reviews VALUES (35130, 1322650, 229, 'Precision platforming at its finest.', 'if possible I would have left this review as mixed\nthis game had a lot of potential as the music is cool and the design is pretty nice even though a bit repetitive, \nbut sadly the physics of the game are just way too sensitive for a precision platformer and end up making the whole game feel clunky and jank. It gets even worse when you get into the bonus level and your biggest nemesis is the physics and control because everything requires specific jumps.\n\nif you plan on playing the game I highly ', 'Very Positive', 84.72, 0.32, 5.67);
INSERT INTO reviews VALUES (35134, 1323000, 143, 'Absolutely lovely! The alien races you need to balance are memorable and likeable, some of the best I''ve seen in a game. The plot is interesting, and the price is right!', 'Even for its price - 50% off, the game was too short and the jokes were not funny. I played through it multiple times and while the endings are ultimately different, the gameplay is almost identical. Maybe its just my sense of humor, but it was not fun to play or funny.', 'Overwhelmingly Positive', 97.90, 1.98, 1.23);
INSERT INTO reviews VALUES (35144, 1323420, 482, 'best thing before WW3 starts.', 'Pretty unrealistic - half-naked women would never run towards me so eagerly.', 'Very Positive', 89.00, 7158.72, 0.38);
INSERT INTO reviews VALUES (35145, 1323470, 327, 'I don''t know what to say about this game', 'Requires Internet Connection to play single player! \n\nDon''t buy this until they fix that BS.', 'Very Positive', 81.04, 2.52, 1.05);
INSERT INTO reviews VALUES (35150, 1323620, 183, 'best in class simulator for VR and non-VR, but the depth of content is lacking and it has not been updated in 2 years\n\ndevs seem to be responding to recent reviews on steam but no official news of any updates as far as i can tell since June 2023 ("updates coming soon™")\n\ndespite being pseudo-abandoned, it is still probably the best adult simulator game out there and I hold out hope that the devs will continue to support this', 'I wanted to give this a shot, but it''s not worth it. I''m very forgiving since nothing can be perfect for everybody, but there''s not really a lot you can do in this game.\nSure, you can simulate having sex with the models, but switching poses takes them away and brings them back after a couple of seconds (too many seconds) in another pose, instead of just switching poses.\nThe models are giants. I''m 185 cm tall, and a model that''s only supposed to be 150 cm tall shouldn''t be towering over me.\nYou c', 'Mostly Positive', 75.96, 5.65, 1.03);
INSERT INTO reviews VALUES (35158, 1323900, 200, 'I completed the game in approximately 8 hours with a friend, and overall, it was a great co-op experience. The game features survival, crafting, and some combat mechanics. While enjoyable, it does have some areas that could be improved.\r\n\r\nThe map can be a bit confusing, and there are minor bugs, but nothing that significantly affects gameplay. Towards the end, the game becomes a little repetitive, but for just $2, it''s a great deal.\r\n\r\nIf you''re looking for a budget-friendly co-op game to play ', 'A game where a destination is displayed on the map, go there, find something, bring it back, build something at your base, wait a day, and repeat.', 'Mixed', 67.50, 7.95, 25.93);
INSERT INTO reviews VALUES (35166, 1324130, 4990, 'It''s a good (but not great) game. The positive aspects are the crafting (very well balanced), the music, and the interfaces. I like that there are a lot of mods in the steam workshop to tweak the game.\r\n\r\nWhat I''m disappointed with is that the resource management aspect is quite easy, especially once you get through the early stages of a mission. Most things are quite plentiful and easy to grow yourself once you have observed them.\r\n\r\nThe main difficulty modifiers seem to be the weather (makes i', 'WARNING! This game behaves like a trojan horse and there is nothing you can do about it! Upon opening the game, you are greeted with a screen which says, to quote, "We may from time to time during your Use of the Game collect information about your device (...) This information may include your (...) IP address, MAC address (...) other device use information" - which to me reads that they will obtain your personal data (MAC address is unique for each network card produced), and potentially can t', 'Very Positive', 83.95, 215.78, 0.57);
INSERT INTO reviews VALUES (35168, 1324270, 125, 'Bruh, started it up...... and listened 2.9 hours to the titel screen music. Because its that good !', 'They abandoned the project and failed to even START the 2024 roadmap they promised with no communication and have started working on a different game.', 'Mixed', 55.20, 3.13, 5.62);
INSERT INTO reviews VALUES (35170, 1324340, 861, 'This game seems pretty cute so far, I''ll probably buy it for my niece since she''s about the same age.', 'Got copyright struck for playing this game, appealed it but alas the people behind this game are a corporation that decided to  keep the claim on. I mean why not at the end of the day, it''s not like I can do much more then leave a negative review and scream about it into the void. They know I can''t take them to court and force them to abide by fair use, It''s scummy and no matter how much I like this game I am leaving a bad review on principal. I would love to refund the game but they took their ', 'Mostly Positive', 77.24, 64.93, 2.07);
INSERT INTO reviews VALUES (35171, 1324350, 451, 'if youre tired of rocket league and have autism come on down to the minor leagues where you can become SSL in golf instead of soccer', 'This is an incredibly fun game. The thrill of zooming across the map and slamming into your ball and gliding through boosts is just *chefs kiss*.\nIt''s such a great shame then that the only two server options are west europe or central us. I am in Australasia. I get bad connection issues on every game that I enter. It blinks me around the map, in front of my ball, behind my ball. It doesn''t register me hitting the ball so the ball blinks behind me. Or mid reset of the car behind the ball and it b', 'Very Positive', 88.91, 16.87, 0.55);
INSERT INTO reviews VALUES (35178, 1324530, 1264, 'Dis ain''t fer da weak! It''s all ''bout bein'' an Ork, smashin'', bashin'', and gettin'' stuck in da biggest, baddest fight ya ever seen! With loads o'' teef to earn and custom gear to smash in, dis game''s like a Gorkamorka dream come true! And when ya get tired o'' stompin'' solo, team up with yer mates and show ''em who''s da biggest, baddest Ork around! So, if ya wanna feel da WAAAGH coursing through yer veins, get yerself dis game. It''s da greenest, meanest, Orkiest rampage ya ever gonna have! WAAAGH! ', 'The aesthetic is awesome and the game play is fun. But man the crashes when playing with friends makes this game unplayable. No patches since 2022 and no word from the  dev team on how to fix the issues. Do not buy this game if you intend on playing with friends!!', 'Very Positive', 88.21, 54.97, 1.83);
INSERT INTO reviews VALUES (35186, 1324780, 3796, 'Everytime I go to launch the game, there''s an update...\n\nand each time I am more and more impressed with the effort from Corvo\nKeep making this game great!', 'Unfortunately this game isn''t anywhere near as good as i wanted it to be, in fact quite the opposite. I will preface this with saying i only played in Co-op. Ai appears to be brain dead being my biggest criticism, after reading how hard the game could be and how the Ai was decent i went in expecting it to be challenging if not brutal, which is what i was hoping for. It couldn''t be future from the case, all the missions i played consisted of the same objectives, capture and hold or defend an obje', 'Very Positive', 90.73, 26.88, 2.85);
INSERT INTO reviews VALUES (35194, 1325040, 119, 'First initial impressions are great, music slaps, doesn''t support ultrawide yet, but would be nice if it had some art or something on the pillarboxed sides not a deal breaker tho ^^, looks like there''s full remapping available for kb and controller, and loads of colour options for the interface so you can make the ui more comfy for yer eyes.\n\nThe combat takes abit to get used to and can be quite punishing if you can''t get the timings for blocking/pallying right, but once you nail it, it can be h', 'Look I went into this game knowing more or less what to expect. I loved Virgo Vs The Zodiac and I knew it would be a similarly punishing timing based combat system... but even after the demo feedback its still overtuned. You really need to memorize the timing of your opponents attacks... and the timing is pretty strict and the flash that indicates when you''re supposed to press the button is not generous at all meaning you''re almost never going to counter an attack on the first try... or even the', 'Very Positive', 90.76, 1.45, 13.92);
INSERT INTO reviews VALUES (35196, 1325200, 9521, 'This game has a lot of potential to be great and i really shouldve stuck with it. HOWEVER fare warning this game is hard as hell and im just not goated enough to get gud.', 'I love a decent fair challenge like the Dark Souls trilogy, but this one is just mindlessly unfair. You must be a masochist to like this game. Get used to dying cheap deaths and repeating each level several times. I did not enjoy this.', 'Very Positive', 91.43, 2.30, 44.03);
INSERT INTO reviews VALUES (35199, 1325260, 710, 'it''s actually better to constantly get hit in this game because if you finish a level in fox form it does an adorable little sneeze', 'Nearly bereft of original ideas this is a Super Mario Bros. 3 romhack also featuring elements from Super Mario World. In the time I spent with it, I was repeatedly taken aback by the developer''s willingness to lift elements from SMB3 and World completely unchanged down to highly recognisable enemy logic.', 'Overwhelmingly Positive', 97.04, 7.93, 1.25);
INSERT INTO reviews VALUES (35205, 1325400, 134, 'A beautiful game full of amazing stories and characters. After the previous games where Sony abandoned Vegas I was concerned if he''d find the courage to keep up going but he has managed to defeat several evils. I won''t spoil the ending, but I was in tears for hours. Can''t wait to see how the story continues in Vegas Pro 19.', 'cant render a simple fucking video without the render freezing 1/3rd of the way through', 'Mixed', 56.72, 150.20, 187.92);
INSERT INTO reviews VALUES (35212, 1325800, 157, 'Ui isnt great but a good game when you figure it out', 'It takes weeks to get enough people for online play. You can play against the AI, but it''s playing against AI but it feels poorly executed. I would not recommend the online version.', 'Mixed', 67.52, 16.08, 19.97);
INSERT INTO reviews VALUES (35215, 1325890, 266, 'Great art style with wonderful creature and environment design, contributing to a very atmospheric game.\r\n\r\nTook me 3 hours to finish, but you might be able to do it in 2 hours if you were really going for it. Despite the short play time I think the game is still worth the asking price for the points mentioned above.', 'Boring and frustrating game. The gameplay loop and puzzles are bad. The game throws a new mechanic at you, plays with it a bit and then does a "bossfight" which after defeating, you get into 5 minutes of unskippable cutscenes of an uninteresting story and this is done 4 TIMES, THE SAME THING barely anything changes in the after boss sequences. I would love if this game leaned in more into the exploration of new creatures and enviroments, because the artstyle and atmosphere is really good.', 'Mostly Positive', 77.44, 2.97, 2.18);
INSERT INTO reviews VALUES (35216, 1325900, 369, 'If you love Mario 64, this is the game for you! It''s rough around the edges but it has a heart of gold.', 'If you can get it on sale buy it and play through the first two worlds and you''ll have a blast. Once you clear the first half of world three the levels start to troll you. You see the crazy thing about this game is they extend your move set after each boss fight. in 90% of games that would be great but in this one they make the use of that ability compulsory from then on, and they''re all more likely to get you killed. You have the hookshot ability that will make you overshoot or undershoot where', 'Very Positive', 85.91, 19.85, 22.08);
INSERT INTO reviews VALUES (35220, 1326000, 104, 'seg', 'Would be nice if there was a middle option to choose between yes and no so I guess I''ll go with ''''it''s up to you if you want to buy it''''. For those who want some good lewds, this is a an okay novel for that, but for other things...well...:\nThere''s more grammatical errors in lewd scenes, which suggests the writer was scripting while gazing at the lewds and not giving a crap about fixing mistakes xD, in regular scenes it wasn''t so bad. Other than grammar stuff, surprisingly this series is progress', 'Overwhelmingly Positive', 96.15, 0.10, 10.55);
INSERT INTO reviews VALUES (35225, 1326270, 114, 'Simple and fun', 'Could be great without the bugs, I really liked it, but the buggs are too frustrating. Meds and security guards can''t function properly. Pls fix', 'Mostly Positive', 74.56, 5.80, 1.53);
INSERT INTO reviews VALUES (35228, 1326470, 100345, '- Cut Tree\r\n- Make House\r\n- Cannibal Visits\r\n- Cannibal Dies\r\n- Cook Cannibal\r\n- Eat Cannibal infront of Cannibal\r\n10/10', 'This game is decent in a lot of ways. The graphics and AI capabilities are off the chart. A lot of animations are cool and immersive. It''s a beautiful looking game. But there''s so much left to be desired. The map is way too large and empty. building a defense base is pointless, and there''s no guidance on how to progress the story. The GPS doesn''t help when all of the POIs and caves are blankly listed out all at once.  How are you supposed to know to upgrade the Ancient Armor with Solafite to ope', 'Very Positive', 87.99, 51.22, 135.43);
INSERT INTO reviews VALUES (35239, 1327080, 425, 'Two games in one. \nSome bosses are definitely not doable one handed.', 'While I do like this game, I can however not recommend this game in good faith.\nThis is because I was experiencing issues with this game that I was even able to determine what the problem was but the devs continue to ignore me (please refer to the discussions page regarding screen flickering bug and the pinned bug reports discussions).\nThe only way i was able to run this game without the seizure inducing screen flickering was to run the game from the directory it was installed in all the while h', 'Very Positive', 89.41, 10.27, 9.30);
INSERT INTO reviews VALUES (35261, 1328350, 4089, 'your body is made up of roughly 70% water. In this game, your body is 70% chainsaws, and that''s pretty cool.', 'I liked it up til the last act, which felt like it overstayed its welcome, and just became too much of a movement puzzle with annoying arena slaughters. Also, it changed antagonists then, and that sucked because I liked the story up till that point too. After that, it became more of a chore to just finish what I''d invested in already.\r\n\r\nYour weapons never really get stronger either, and your chainsaw is the preferrable method of killing things quick. Which gets both boring and frustrating when ', 'Overwhelmingly Positive', 95.74, 29.13, 17.10);
INSERT INTO reviews VALUES (35270, 1328530, 213, 'Story is very simple, game is pretty hard but can be played in easier modes, probably beat the story in 8 hours. Loved the art and the gameplay. Really solid deckbuilder, highly recommend!', 'This game certainly has good aspects to it. The cards and gameplay offer a ton of new creative ideas I haven''t seen in any cardgame before. The visual style of the characters, menus and cards is very appealing. But Quantum Protocl ultimately failed for me because of two great issues. \r\nFirst, this game isn''t beginner friendly at all. There are SO MANY things a players has to learn, apart from the own deck. Quantum Protocol is so mechanically deep, something I usually like. Yet, the learning curv', 'Very Positive', 91.08, 13.02, 17.98);
INSERT INTO reviews VALUES (35276, 1328660, 4527, 'I''m not sure who EA hired to be the voice that reads you the description for each car, but they did such a good job, it is auditory heroin. You gotta listen to her fully explain the backstory of the car before you can drive it every single time, sorry I don''t make the rules.', 'It doesn''t matter what the game plays like. EA forces its own launcher onto the pc and sets itself to run at startup. I can think of about 3000 more fun ways to get digital herpes, and none of them require me to put scumware on my PC.', 'Mostly Positive', 79.59, 18.33, 3.53);
INSERT INTO reviews VALUES (35277, 1328670, 35559, 'Too bad you have to struggle with the EA launcher which still can''t consistently do the one thing it is supposed to do... launch the damn game. So when you get to play it, it is a great game.', 'Can''t play the game in offline mode.\nI wish Valve banned any external DRM and launchers.', 'Very Positive', 91.33, 18.38, 2.90);
INSERT INTO reviews VALUES (35285, 1328840, 1426, 'Very easy, which made it a pretty good choice for introducing my girlfriend to adventure games.  Absolutely charming story, great art.', 'I believe people deserve to know this is an Israeli product', 'Overwhelmingly Positive', 97.27, 6.37, 0.08);
INSERT INTO reviews VALUES (35288, 1328890, 254, 'Absolute BANGER of a game. Definitely worth every cent. If you like well animated pixel 🌽 and using fantastical powers to dominate monstergirls, this is it. It''s the gold standard of what h-games should strive to be 🙏', '(I played with the uncensored patch)\r\n\r\nThe gameplay is fine, but the sex action is too small. There really should have been time invested into larger scale animation and images that display somewhere on screen during sexual encounters. As it is, the action is so small and pixelated that it''s not erotic at all.\r\n\r\nI can get off to most porn games, but this one can''t even give me a hard on.\r\n\r\nIf you''re here for a cute game with decent gameplay you might enjoy this. But if you''re looking for some', 'Overwhelmingly Positive', 96.06, 4.50, 1.22);
INSERT INTO reviews VALUES (35293, 1328990, 468, 'I cannot explain the sense of nostalgia this games brings to me, something that Stormgate is trying SO HARD to make me feel that, actually do the opposite\n\n If Stormgate tries to sell you Starcraft, Godsworn is the Warcraft 3 feel you are searching for, I think this is the only sentence I can use that truly explains the feeling of this game.\n On the other hand, the game is still really fresh, but the multiplayer (thing that I did a lot during the demo period that is not reflected on this review ', 'This game is lacking in way too many features to be asking $30.00. The big one of course is NO SAVE FUNCTION. That''s right. You can''t save your progress during the campaign or even in a custom game. It also does not save automatically when quitting the game. After checking through the Steam discussions, it seems that the developer is refusing to add a save function because that would be way too difficult to implement such an insane request. There is also no option to speed or slow the gameplay, ', 'Very Positive', 92.95, 3.93, 0.98);
INSERT INTO reviews VALUES (35318, 1329500, 2337, 'This is one of the best games I ever played. It''s unique but still classical and it''s hard to get bored of. It gets updated all the time and has daily challenges', 'It can be a great game if you are playing on the same console/pc, but when you play online (which i do) the delay from when you press a button to it doing something in the game is just unplayable and it ruins the whole expirience. But again, if you are playing from the same console/pc, this shouldn''t be a problem', 'Very Positive', 94.27, 35.25, 8.37);
INSERT INTO reviews VALUES (35319, 1329510, 550, 'It''s a cute little farming game. Enjoyable to play. Some things are annoying like having little micro currencies at different stores. Sell cooked dishes to get "gourmet" coins to buy recipes and ingredients. Sell fish for fish coins for recipes and ingredients. You get the idea. It''s also annoying when you''re in a menu, it exits outs when you complete an action. So say your at the mill and need to make shreds to make animal feed and then make fertilizer for your tree, you have to open the menu s', 'It''s more of a mobile farm game than a farm game at all. "Click here to upgrade", "Click here to repair", nonsense.\nThere''s also micro-transactions in it, couldn''t not-recommend this enough, and it''s looks rough as well.... dissapointed.', 'Mostly Positive', 76.91, 37.52, 0.13);
INSERT INTO reviews VALUES (35321, 1329540, 221, 'DOOM ITS THAT U', 'Too difficult, you die in one hit.', 'Mostly Positive', 75.11, 1.73, 0.15);
INSERT INTO reviews VALUES (35322, 1329600, 194, 'This unironically is game of the year.', 'shit', 'Very Positive', 87.11, 7.12, 0.10);
INSERT INTO reviews VALUES (35329, 1329880, 797, 'The 1.0 release is a much better product than the original. The original Wild West Dynasty was an extremely janky, buggy mess. The graphics have been improved since then. Character movement is still a bit janky but I am impressed by the quests, polished texts, and ability to ride mounts (horses). This game is not Medieval Dynasty; it has even more emphasis on character survival. \n\nHave not reviewed all of what the game has to offer yet so update to review will be forthcoming. So far happy with t', 'This game has a TON of potential. I love survival games and I''m fascinated with anything to do with the Old West. I played it when it first released. Very buggy, as I knew it would be. So I took about a year hiatus to let the devs cook, then came back. After a year you can tell they have made some progress, but not nearly what I had hoped for. There are still a TON of issues, both visually and mechanically. Like some other reviews, it should not have left early access. I really enjoy the concept', 'Mixed', 43.91, 12.40, 38.98);
INSERT INTO reviews VALUES (35331, 1330000, 2090, 'Fun game, but glitchy like a mofo. Freezing up at random bosses in campaign, a persistent bug that hasn''t been fixed in roguelite, I''m not sure if either of these are even being fixed.', 'Developers are abandoning the game to make another game. Don''t buy. It''s not finished in it''s current state, but it COULD HAVE BEEN one of the very best games ever made if the developers had kept producing it.', 'Very Positive', 86.12, 284.23, 177.77);
INSERT INTO reviews VALUES (35340, 1330190, 230, 'My honest thought I love the characters an choice the story is weird but the mostly chill I understand what the creator an the crew is going through stuff you know life I will play the game till new updates or the new game come out on steam that one look very good cheers on the full 1.0 release keep up the work don''t let life keep you down', 'All but abandoned by the dev to move on to a more popular, lucrative project on Patreon.  The dev has gutted the game, stating themselves "I''ve reworked the main story and cut out about 45 chapters from act 3 and condensed the story elements into 15 chapters to complete the story.  Gonna be honest, it''s not the cleanest or the most free flowing change but I''ve decided to do this to minimize the amount of art assets and work left needed to turn this game from an ALPHA into a FULL version." (Sourc', 'Mixed', 69.57, 23.10, 13.03);
INSERT INTO reviews VALUES (35351, 1330460, 2474, 'Honestly, a really cool game, but the developers for one reason or another, have stopped updating the game despite many bugs still being prevalent and content that was previously teased not being released.  I don''t know for certain, but I think this has to do with the Ukraine war since the developers were based there.  I hope they are doing well and get around to working on this fun little game again.', 'Bought this long ago and really enjoyed the gameplay, the graphics, the progression etc. But at the time i felt unpolished and crashed too often. I waited for it to be updated and fixed but it''s been so long (more than a year) there hasn''t been any updates so I can''t really recommend this game. Would love to see it more developed though', 'Very Positive', 84.11, 7.17, 2.87);
INSERT INTO reviews VALUES (35352, 1330470, 642, 'Originally played through this game on Epic (free game giveaway) and enjoyed it so much that I had to buy it on Steam to support the devs. FIST has to be one of the most overlooked and slept on metroidvanias out there. If you''re a fan of metroidvanias this one is a must-play.', 'An absolutely great game initially. Outstanding graphics and enough challenge to keep things interesting. I cannot recommend this game though based solely on the fact that there is a massive difficulty jump on the final two bosses. To top it off, you have to go through multiple sections with no breaks, meaning that death means starting the whole battle over from scratch. Really wanted to finish the game, but the huge difficulty spike and flat out overpowered bosses ruined it for me.', 'Very Positive', 88.01, 17.53, 20.00);
INSERT INTO reviews VALUES (35355, 1330560, 244, 'Good game, previously had crashing issues but the dev team made a lot of effort over a couple weeks to try and fix this for me, great support from GameFormatic', 'I had really high hopes for this game, I''ve been wanting to play a hairdresser game for such a long time and thought this would be perfect.\n\nHowever, it was very buggy. It took ages to load. And now I found out they''re releasing long hair, but as a DLC!!? What? That should just be a base game feature. Craziness.', 'Mixed', 41.80, 28.83, 1.43);
INSERT INTO reviews VALUES (35359, 1330660, 425, 'It''s a fun game once you understand it. I would strongly suggest reading the guides on Steam for it. Some of the design choices are questionable like the signal color not being like real life or train coming towards you on the right side but I believe there a setting to make them appear only on the left side tho. Should be called train life a train game not a simulator since very little is simulated but regardless if you looking for an arcady train game that let you run a train all over Europe w', 'Unfortunately the publisher abandoned the game before it could reach it''s full potential.', 'Mixed', 53.88, 177.20, 4.43);
INSERT INTO reviews VALUES (35371, 1330890, 233, 'For a few cosy evenings I was back to being a child. Sitting in front of a bulky monitor in a warm blanket with tea and cookies my mom made, completely safe and full of hope for the future. Can''t believe something could take me back to that wonderful feeling, even if just for a few hours. Those nostalgic memories are priceless. \n\nThe game itself even after all this time is fun. The levels have quite the variety and you don''t feel repeating the same "run, shoot, jump" over and over again. Most of', 'ITS A GOOD REMAKE OR WHATEVER IT WORKS WELL BUT ITS A FUCKING PLATFORMER. NOBODY SHOULD PLAY PLATFORMERS', 'Overwhelmingly Positive', 97.85, 12.57, 0.40);
INSERT INTO reviews VALUES (35386, 1331210, 395, 'A bumpy but extremely enjoyable ride. \r\nMore of a visual novel with proper gameplay than anything else, but there is so much to like about Wolfstride. \r\nThe No More Heroes like structure moves along the plot, going from grinding minigames and sidejobs to upgrade your mech and get new attacks for these fun clashes against other mechas. Initially the premise is super entertaining, but sadly, you eventually will encounter loopholes within the combat system, and its very easy for the daily tasks to ', 'A mecha visual novel with some turn-based combat. Wolfstride is a passion project by a small team with many technical achievements.\n\n-Loads of unique 2D art\n-Good music\n-Full voice acting\n\nSo if you''re confident that you will like the story, it''s probably worth playing for you. For me, I did not enjoy the story. It''s very much a quirky so random humor game. And the plot plays with a lot of familiar tropes while being an absolute slow burn. That''s my subjective takeaway.', 'Very Positive', 88.10, 20.18, 2.35);
INSERT INTO reviews VALUES (35400, 1331510, 722, 'I enjoy this game, thus I am giving it a good review, this is how reviewing works, stop giving your favorite games bad reviews because "you want to change the mind of people looking through negative reviews" People looking through negative reviews are genuinely looking for flaws and not just random stuff in the slog of positive reviews', 'This game has cool weapons and items, but hitting most enemies feels like hitting a rubber doll.  Deflecting, parrying, and charge attacks are difficult to impossible to pull off on any enemy that isn''t a grunt which is annoying, because killing most bosses depends on deflecting their strong attacks. Some abilities straight up don''t work. Movement in the game is too slow, you''ll always be backing into your invisible boundaries. I fought a boss who''s attacks I couldn''t parry/deflect, none of my w', 'Mostly Positive', 74.24, 6.20, 2.12);
INSERT INTO reviews VALUES (35403, 1331550, 4421, 'I enjoyed the game, but after about day 60, I realized that I was just repeatedly sleeping to earn enough money to start a new business, and then repeating the process. It quickly became boring, but the first 10 hours were really enjoyable.', 'Fun for a few hours when the concept is still fresh, but after that the gameplay loop becomes tedious and repetitive. Every storetype is only superficially different. \nI dont really understand why there even is a playable character. The only thing you can really do is drive around and sleep. There is no social life and you cant interact with people or personnel. \nI really like the concept of this game it really reminds me of tycoon city New York, but its just too barebones for me at this moment ', 'Very Positive', 92.92, 18.15, 12.38);
INSERT INTO reviews VALUES (35418, 1332010, 72415, 'I''ve been going through a tough time recently and lost interest in the things I used to enjoy, like video games.\n\nDuring the last Steam sale, I remembered this game. It had been on my wishlist for a while, so I decided to buy it, even though I didn’t really feel like playing. I gave it a try and played for a few minutes—until I noticed a calendar on the wall with my birthday on it (October 11th).\n\nFor some reason, that small detail motivated me to keep playing. Over time, I found myself playing ', 'First off, if you enjoy the game for the cat thing and just like the whole vibe and visuals, I totally agree with you. I''m happy that you enjoy the game. \r\n\r\nAn in-depth look, however, reveals some shortcomings. While "Stray" is visually stunning, it ultimately plays like a walking simulator. Even as a cat, there''s no real platforming to be found, and the puzzles are basic at best. The world-building falls flat within the first 15 minutes. I would have been more intrigued if the story was told t', 'Overwhelmingly Positive', 97.40, 22.30, 5.35);
INSERT INTO reviews VALUES (35451, 1332720, 1973, 'If you''re wondering whether to buy this game because it''s similar to the first one, don''t hesitate, just buy it. The mechanics are quite similar, which is a plus, but the difficulty level is significantly higher. Additionally, there are many easter eggs and collectibles, smarter AI, and more possibilities, all of which make the gameplay much better and more engaging. It''s a very addictive game, and besides, if you can''t find a girlfriend in real life, you might succeed in finding one in prison. ', 'I absolutely loved Thief Sim 1 and have almost 100 hours on that game. I tried to enjoy Thief Sim 2, I really did, but it''s impossible. Don''t get me wrong, it''s got it great aspects. I loved the idea of drones, but they were a little too useful and I believe should''ve been some sort of late game mechanic instead of having you rob a toaster using a thousand dollar drone. Also, loved the new driving mechanic. The idea of having the pawn shops within the neighborhoods was great too. The idea of hav', 'Very Positive', 88.04, 30.08, 18.62);
INSERT INTO reviews VALUES (35453, 1332760, 183, 'It''s exactly what it''s billed as - an indie spaceship ARPG (like Path of Exile, Diablo, Grim Dawn, etc.). The English translation is pretty mediocre, but the story is pretty much irrelevant, as you are here to kill things, level up, and gear up. Price to value proposition is pretty fair! Compared to Drox Operative 2, which is its closest contemporary I''m aware of, I think this game is better, though Drox Operative/Drox Operative 2 might also be up/be even more up your alley if you are interested', 'I have mixed feelings on this game. I enjoy ARPGs/looters and 2D space games, and this game somehow scratches neither itch. Most of the game is relegated to navigating tight corridors in what are essentially dungeons, which makes playing the larger ships much more difficult and ends up being more of a detriment unlike most space games where the goal is usually to get larger, more powerful ships. This would be okay if the "dungeons" had at least some space to move around for larger ships, but thi', 'Very Positive', 87.43, 56.98, 27.38);
INSERT INTO reviews VALUES (35465, 1332990, 132, 'I strongly reccomend this visual novel.\r\n\r\nWriting is strong, comedy never misses, majority of content is voice acted and minimal animations do enough to not make the scenery too static.', 'Although the art and Ader''s voice actor are really great, this is much more of a narrative than a game.  With limited choices to affect anything and lots and lots of references without a glossary, it''s really an exercise in watching someone telling a story without explaining themselves.  Wouldn''t recommend it.', 'Overwhelmingly Positive', 96.21, 22.87, 4.05);
INSERT INTO reviews VALUES (35477, 1333200, 963, 'This is an absolute beautiful game to experience and play.  The colors and music just draw you in.  The relationship with Willump and Nunu is adorable.  I recommend this game to anyone young and/or old.  I am a 70 year old woman who has been playing video games for close to 50 years and this game rates among the very top.  I was sad that it ended.  It was almost like when you finish watching a great series and you are almost part of the movie or equate this to a good novel that you wish would ne', 'I really wanted to like this game, but I simply found it too boring, I feel no inclination to open it again. I do love the artstyle though.', 'Very Positive', 94.39, 56.68, 1.02);
INSERT INTO reviews VALUES (35489, 1333470, 229, 'The title is misleading. Alex Kidd is not a kid. Do not let him touch your crotch area.', 'Goodness, these controls are miserable.', 'Mostly Positive', 77.73, 0.08, 0.30);
INSERT INTO reviews VALUES (35491, 1333490, 112, 'Dead Game.\n(Literally)', 'I was hoping for some more creature growth and monster evolutions but yeah no this is just you doing nothing for hours to level up, thats it that is the game at the moment. I tried the different types of creatures and it was okay but with reason to exist there is sadly no point in playing and the penalty for dying is pretty brutal. Not only do you lose experience but you also lose everything in the inventory with no way to recover it. This game has pvp but so far i have seen maybe two people in ', 'Mostly Positive', 79.46, 4.63, 5.30);
INSERT INTO reviews VALUES (35495, 1333560, 103, 'Enjoyed this game when I played it a few years ago after it was first finished.  With some polish and additional content, I enjoyed it even more.\nSome of the hottest MILFs you will ever see.  Though the lewd scenes would greatly benefit from erotic sound effects, they are still quite good.  The animations are very good.\nTranslation is a bit rough sometimes, but I''ve seen much worse.\nPacing is a quite uneven and I would have really liked more with Nika, but the story is still a bit of fun.\nHas so', 'Short and incomplete.', 'Mostly Positive', 77.67, 9.95, 2.87);
INSERT INTO reviews VALUES (35508, 1333910, 658, 'It''s a fun and chill puzzle game that really draws you in with its cute low-poly dioramas and unique resizing mechanics.\nYou can shrink or grow objects to find hidden secrets, making it a fresh and enjoyable experience.\nThe levels are short and well-designed. It''s a great way to unwind while keeping your mind engaged.\nDefinitely worth checking out if you like casual and exploration games!', 'I''m a big fan of puzzles and a big fan of relaxing games. Even though everyone in the reviews repeatedly calls this game relaxing, I found Sizeable annoying. The gameplay is frustrating because eventually you end up just clicking and scrolling on absolutely everything in the scene- and at that point each level lost its fun for me. \n\nCertain portions of puzzles aren''t intuitive, and because some of them don''t make logical sense the game becomes less of a cute puzzle and more of "get lucky clickin', 'Overwhelmingly Positive', 97.57, 8.25, 1.48);
INSERT INTO reviews VALUES (35515, 1334000, 407, 'It is good but i would never spent 20$ on it, only buy this in sale then its definitely worth it.', 'This is not a $20 game. Got it on sale for $0.99 and I still feel like that''s too much. I''ve played far better word games that were free. I haven''t checked whether this game or THE Wordle came out first - nevertheless, this game is certainly taking advantage of the shared name. At no point did incorrect guesses "give clues about letter placement." There was no limit on how many times you can make guesses, and thus no penalty for just stringing letters together at random until a word caught my at', 'Very Positive', 83.54, 2.58, 2.77);
INSERT INTO reviews VALUES (35516, 1334010, 258, 'Since cards have already been added, it would be nice to add achievements) It will immediately increase interest in the game\n', 'Nah man, this whole game can be beaten in 58 minutes without even trying. Puzzles are so simple and not much variation. You are basically put into a open air box and when finishing a level you have to select another from the main menu. Level design is so bad, it feels like they just threw assets together and didn''t try to fit them. The first level or so is OK but then the yank beings.\nGames got spelling mistakes, missing textures and weird music that doesn''t fit the game. All interactables are h', 'Mixed', 67.44, 7.18, 0.97);
INSERT INTO reviews VALUES (35548, 1334700, 304, 'Etherane games are like  interactive short stories that''s sort of like if a morality prose poem and a buzzfeed quiz had a baby and they all fucking hated you\n', 'Isn''t worth it. Even though it''s short, puzzles are not intuitive enough to enjoy solving them, only make you angry or disappoint', 'Overwhelmingly Positive', 96.05, 2.55, 1.33);
INSERT INTO reviews VALUES (35549, 1334730, 626, 'Well done Retro-FPS, good to pass the time, as for its story I would say that it seemed interesting, but the way of telling it seemed boring to me and I ended up ignoring it completely and just focusing on moving forward ღ', 'Peak writing is when the there''s ''''some kind of...'''' or ''''we''ll meet again, '''' after you''ve damaged boss for some amount of health and not even kill him. The movement is garbage and this game punishes you if you play the game the way it was intended. You want enemies to not damage you? Just kill them one by one from around this corner! +That''s so goddamn stupid when there''s another enemy on your way, you try to shoot him but there''s a corpse laying between you and the enemy, but your shot goes r', 'Very Positive', 84.35, 2086.87, 0.83);
INSERT INTO reviews VALUES (35561, 1335230, 314, 'Sumire is a beautiful Japanese walking sim with some light puzzle elements. It has a gorgeous hand drawn art style, and a lovely narrative. The music and sounds are incredible. You can get different endings based on the choices you make throughout the game. I loved everything about Sumire, it was perfect to me. At just three hours long, it was like playing through a film, and it made me cry at the end! 11/10.', 'this game is harder than elden ring dlc', 'Overwhelmingly Positive', 96.82, 3.03, 1.25);
INSERT INTO reviews VALUES (35577, 1335530, 781, 'Probably the only PSX inspired game that actually feels like a lost title from Playstations catalogue. I don''t think there''s one indie game out there that has accomplished anything close to the PSX feeling Alisa achieves. That alone makes it worth recommending but the game itself is fantastic.', 'Contains a sliding puzzle.', 'Very Positive', 89.63, 3.92, 0.85);
INSERT INTO reviews VALUES (35578, 1335560, 301, 'A girl''s surreal adventure in Unreal Life, with a talking traffic light.\nYou''re going to love tomorrow''s story.\n\n\n195', 'The street light character makes a really annoying sound whenever it talks.  Undertale was a mistake.', 'Overwhelmingly Positive', 98.01, 16.13, 0.30);
INSERT INTO reviews VALUES (35586, 1335790, 2035, 'Excellently made asymmetrical coop game. Important note: only one player needs to have purchased the game.\n\nI can''t say too much without spoiling things but if you enjoy games like "Keep talking and nobody explodes" or the "we were here" series, you will adore it. It is rather short but what is there is near perfect.', 'schmutz spiel, nur bugs seit 3 jahren anscheind. spiel hat super Rezensionen aber ist buggy wie sau. haben die eine hacking mission mit dem dective scheiß gespielt und die IP und Pass Codes nie hingehauen. also mein beileid das man dass seit 2020 nicht hinbekommen hat, das zu fixen..', 'Very Positive', 91.84, 5.78, 3.17);
INSERT INTO reviews VALUES (35589, 1335830, 2208, 'This was a pretty close no, but I''m feeling nice today, so it''s a yes instead. I would ONLY buy this on sale. One guy - yes, just one singular human - made this game from scratch. For a pet project, it''s quite a nice little gem, but take it for what it is - if it weren''t for the combat, this would be a cozy game. The combat itself can be quite challenging only given the number of enemies that can sometimes swarm you.\r\nI don''t have anything great to say about this, but I don''t have anything awful', 'I’ve never been so mad at a game in my entire life. I just rage quit for the first time ever playing a game.\n\nSo much potential. I love the concept of this game... HOWEVER, The controls are so incredibly bad it feels like they were designed by an energy vampire that gets off on my absolute rage trying to simply retrieve some food that is stuck in a chest and cannot be retrieved while I starve at an exceedingly fast rate.\n\n“Full Controller Support” is an absolute lie.\n\nupdate: I saw the recent up', 'Very Positive', 86.01, 5.15, 5.00);
INSERT INTO reviews VALUES (35597, 1336060, 131, 'Kaguya and his  14  bad ends gave me trauma  more so than gretel and his cage ', 'Gretel''s route was the worst thing I''ve ever experienced in my life and  I''m so angry at all the positive reviews on this episode that led me to think that his route is somehow not just completely incest. It''s incest!!!!!!!! The other episodes are more fun but this one almost stopped me from even bothering to play them at all. Kaguya''s route is also not great and handles self harm and suicide in a really poor way so. Watch out for that also.', 'Very Positive', 92.37, 8.97, 6.53);
INSERT INTO reviews VALUES (35605, 1336180, 427, 'First of all it must be understood that this game is "not for everyone" and this IS A HARD GAME to grasp and understand. In other games you put stuff down and your done mostly...Well in this one were you put stuff matter''s. Example: There is the "workplace"..."the house those workers live in"..."and the distance between" AND this is only that problem. IF you put the workers house next to their workplace they work more but then they may not be close enough to recreation as recreation has a area a', 'This is probably one of the most boring games in ""colony simulator" genre. Many convenient things other games have are simply absent here, the interaction between clans is also simply terribly implemented, it is easier to settle them on different islands than to influence their relationships. The game complains that a resident has a long way to go from home to work, but they do not give you the opportunity to do anything about it, you cannot manually relocate it. In "surviving the aftermath" an', 'Mixed', 55.27, 57.70, 18.38);
INSERT INTO reviews VALUES (35617, 1336490, 16286, 'As a casual player, my issue with traditional building games is that I often don''t have time to reach the middle/end game. I sometimes return to a game after months, finding myself to simply start a new map because I don''t like the old save game any more.\r\n\r\nAgainst the Storm seems to be made exactly for me. Playing one settlement lasts a couple of hours, then I have the feeling of having something accomplished. And after returning after some weeks, I simply start a new settlement and be finishe', 'Overall, I really like the concepts that Eremite has shown off here, but I think the implementation and balancing of those concepts still needs some refinement to make an awesome game.\r\n\r\nThe big issue for me is that all my towns felt the same, so the game became repetitive.  Every town that I played was won by earning reputation points from the same 3 sources - completing objectives, keeping villagers happy, and opening crates.  I don''t think I would have been successful if I only focused on on', 'Overwhelmingly Positive', 95.47, 37.83, 63.35);
INSERT INTO reviews VALUES (35618, 1336560, 564, 'This game is fun, but it''s physics are janky, the levels are few and quick to beat (17 levels in the career), and the online mode simply doesn''t work on PC. Please developers, if you read this, improve the online compability and rework the physics engine. This game has potential, but it really needs work. And stop the microtransaction h*ll, this game is fostered within. So many things to buy, so few to work for whilst having fun ...', 'dead game', 'Mostly Positive', 71.63, 4.82, 1.13);
INSERT INTO reviews VALUES (35621, 1336600, 377, 'Cabin Fever is a great example of what makes visual novels so good. The music is functional. The art is amateurish... except, oddly enough, the backgrounds, which are the epitome of comfy. The interface is the absolute basic of the basics. But this low cost of entry allows in a wonderful story from a creator who might otherwise not be heard from.\n\nI actually like the main character. For once, he''s actually relatable. So many VN protagonists are either jerks, barely functional, or sometimes both.', 'This game has a notorious habit of creating bad endings where Mallory or Protagonist dies no matter what you do (The misery of never happily married or friends only DEATH SENTENCE for 1 or both).', 'Overwhelmingly Positive', 95.49, 2.23, 7.93);
INSERT INTO reviews VALUES (35637, 1337010, 2657, '关于环保和动保的小游戏，女宝和岛民一起拯救小岛的故事，多元化做得不错。体量不大胜在治愈，对成就党也很友好。\n结局阿尔巴和好朋友牵手的地方看得人心暖暖的ww\nps.才发现和纪念碑谷是同制作组，真好啊ustwo', 'I rarely write reviews and even more rarely I write negative ones, maybe it''s the first one? I would rather give this game a neutral estimation if I could, yet I bought it on sale and even then I regret it, it''s not worth the full price for sure. This game is for little and very very naive children, so parents - beware, it doesn''t develop the critical thinking. Also it is short and pretty boring. I played it till the end only because I was expecting it to become interesting at some point, and I ', 'Overwhelmingly Positive', 97.93, 3.32, 8.55);
INSERT INTO reviews VALUES (35652, 1337520, 16259, 'As someone that played the original Risk of Rain for over 100 hours and got all the achievements, I can say that the remake''s better in every way I can think of. The original game''s bug where level collision broke and you just fell through the ground in certain areas is no longer, characters other than Huntress can finally move a little bit while they shoot, MINER IS BACK, and the game''s got all sorts of new mechanics and item parity with the sequel.\nThe pixel art''s been redone beautifully, Chan', 'amazing game but Take Two''s new eula spyware is unacceptable I will never buy another take two game. Changing the TOS after several years and you have all your primary game sails is trash if i could refund this game and every other Take Two game I own I would. This kind of shady business is going to kill gaming because no one is going to trust you now and when you and Gearbox go under you will have no one to blame but yourself.', 'Very Positive', 94.86, 22.15, 48.87);
INSERT INTO reviews VALUES (35653, 1337530, 167, 'Very good. Some puzzles, some drawing and crafting, nice narrative - and you get a neat game! Not super, but quite a solid VR experience. Recommend, I played it with interest to the end.', 'I really enjoyed A Fisherman''s Tale so I jumped into this hoping for something similar.  Unfortunately it''s not very much of a game, and more of a walking experience with a TON of talking and exposition.  The voice overs are well done, but they''re nearly endless.  In fact, they run on so long, I''d often end one while walking and trigger another audio queue.  \n\nToo much exposition, not enough game.', 'Very Positive', 92.81, 4.53, 3.57);
INSERT INTO reviews VALUES (35662, 1337760, 2224, 'Fairly small and short game. The characters don''t interest me much (I think the most interesting characters I find were Dan/Dev). It lacks dialogue variation for the NPCs and character customization. There''s barely any challenge in the game (both in combat and treating patients) so it can get pretty boring/repetitive. If you''re a completionist you may end up spending most of your time post-game collecting resources (trees, rocks, plants, enemies).\n\nIt was ok :) Maybe buy it on sale', 'In theory, I like this game. It has a beautiful art style, a charming concept and I love its sound design. \n\nIn practice, it is the most boring game I''ve ever played. Usually the repetitiveness of tasks in games is relaxing for me. Here? It is just painfully monotonous and unrewarding. The NPCs are so flat it makes me not want to interact with them in the slightest. The diagnosis + potion making gets old very quickly. This is a game that looks fun but after a while its emptiness is undeniable. T', 'Mostly Positive', 79.54, 43.65, 11.47);
INSERT INTO reviews VALUES (35669, 1337890, 211, 'A simple choose-a-path type game that is fun and quite short (2.5 hours to 100% achievements). This is not a true historical medieval game, but rather a fantasy game largely inspired by the Middle Ages. Nevertheless, it was a delightful romp in its simplicity despite errors of the period and no research done at all (errors too numerous to name)--I particularly enjoyed playing through several paths and discovering titles and achievements. The path that looks "correct" may not actually be best. Re', 'I saw one of the parts of these games on Twitch and decided to buy the first one for review, but here the story lasts only 20 minutes and then endless repetitions, I don’t recommend it', 'Very Positive', 81.52, 2.52, 2.78);
INSERT INTO reviews VALUES (35671, 1337920, 143, 'Bought it the day it released to play with my best friend. Best friend passed away less than two weeks after. Two years and a month after I finished it for us buddy. Wish you could have seen how well I did.', 'too much flashing screen and no option to turn it off. unplayable for me', 'Mostly Positive', 75.52, 95.38, 0.13);
INSERT INTO reviews VALUES (35686, 1338330, 1238, 'Fun game for a bit. I couldn''t figure out a way to make more than $120 in a day no matter how many upgrades I got. So don''t plan on seeing a significant increase in profits even as you add upgrades. The cosmetic upgrades for your room are not worth the time considering you only see the bedrooms screen for a few seconds before you start your day. They should not be worth as much money as they are. \r\n\r\nUltimately, I finished seeing what I felt there was to see in about 14 hours.', 'I was really excited about this game. I had it on my wishlist so I could price track it and grabbed it during a Steam sale. I don''t like posting negative reviews, but I wish I''d read more of them before buying it. I am leaving this one only because I feel that the marketing was off-target for me. It''s supposed to be cozy and relaxing, but it felt like I was actually back working in a bar on game night again. Stressful and anxiety-inducing would be nearer the mark, at least for me.\n\nI love the co', 'Very Positive', 87.72, 16.15, 3.10);
INSERT INTO reviews VALUES (35697, 1338580, 371, 'This game is stupid. The humor is juvenile and absurd. The gameplay highlights a common issue with point-and-click adventure games of the past: every solution has to be brute forced, because the logic either just isn''t there or it doesn''t meet with player expectations. It shares a lineage with the flash games of yore. The pixel art gives off the impression that anyone or their 4-year-old nephew could make a game like this. All in all the game is crafted with love, without an express permission f', 'I got bored after 20 minutes.', 'Overwhelmingly Positive', 97.57, 5.70, 0.18);
INSERT INTO reviews VALUES (35699, 1338640, 144, 'big love for russia', 'There''s too much positive reviews to not call it an organized campaign. The game has been made in Unity and I bet most of the models have been lifted from the unity asset store. Game can be completed in less than 15 minutes. It has enemies that are blind and won''t hit you unless you choose to not kill them and just run past them. I was hit twice in my 2 minutes long pacifist sprint to the end boss. This game has only one level and it''s extremely short, it has intersection of two streets in the m', 'Overwhelmingly Positive', 95.14, 0.72, 0.40);
INSERT INTO reviews VALUES (35702, 1338770, 3792, 'Sniper Ghost Warrior is a really long-going staircase of sniper-themed games, and, finally, that last title is something I can fairly recommend to play. Yeah, the storyline still ain''t any better than before, it''s a cliché parade about ''good guys'' killing the ''bad guys'' in the name of ''status quo''. It''s really dreary nowadays, but we can''t avoid the prop issue, we can only learn to ignore it.\n\nThe gameplay itself, though, is honed better than ever. Previous Ghost Warrior titles, SGW 3 and the fi', 'No manual save. You''d think it would autosave after wiping an area of enemies but it doesn''t even do that. Not going to waste my time with a game that doesn''t respect its players'' time.', 'Very Positive', 85.31, 41.05, 0.58);
INSERT INTO reviews VALUES (35706, 1338840, 923, 'Spear gun shark survival while collecting treasure. Graphics are beautiful and game play is smooth. I found myself very immersed in the environment because of how beautiful the game is. Alot of people are hating on it because of ai or something but in my opinion this games better than %90 of games that have come out in the past couple years. Grab it and give it a try before you listen to these weirdos crying about ai. Try the game out its $7 on sale. If you dont like it you can easily refund it.', 'nothing good except the campaign and even the campaign is mediocre at best, the narrator and art is ai. do not buy unless its on sale and you have money to waste.', 'Very Positive', 86.78, 61.42, 7.02);
INSERT INTO reviews VALUES (35713, 1339000, 617, 'Love being able to create and design aquariums fulla fish without the commitment of taking care of a real aquarium fulla fish.', 'This game had a huge chance to be amazing, the graphics are actually really nice. However, the game play itself is awful, and that''s if you even get the game to load in the first place.\r\n\r\nStarting up the game takes so long and usually crashes from the loading screen, then if you do manage to load in, the game is laggy and controls don''t work on certain things and eventually the game will close itself.\r\n\r\nThe spelling in this game is terrible and shows such a lack of effort from the devs, the in', 'Very Positive', 87.20, 1.33, 5.20);
INSERT INTO reviews VALUES (35757, 1340120, 102, 'Super', 'IxSHE Tell is a romantic comedy about a popular student council president who''s chased not only by the five main heroines, but by all the girls in the school. As you can probably tell from the ridiculous premise, this VN primarily focuses on its absurd over-the-top comedy. While I enjoyed this VN personally, it has too many issues, so I have reservations about recommending it to others.\n\nOne thing I quickly noticed, is that this VN suffers from quality-of-life issues. The text is borderline unre', 'Very Positive', 94.12, 30.22, 38.87);
INSERT INTO reviews VALUES (35758, 1340130, 166, 'Mashiro is the greatest girl ever. This eclipses the main game to me solely for how amazing she and her arc are. Must read', 'Honestly, I like this Fandisc much more than the original in some ways; even the translation feels better here.\r\nNo cartoonish, cringy antagonists—just pure romance fluff. If you''ve ever played any linear kinetic romance visual novels, it''s basically that. While kind of generic, at least it’s not a plot full of bad anime clichés like the original. Here, you get the same high production value, the same likable characters from the first game, and even some new music. And if you liked Mashiro in th', 'Overwhelmingly Positive', 96.39, 5.80, 10.30);
INSERT INTO reviews VALUES (35774, 1340480, 2281, 'A beautifully strange and poetic story about the nature of fate and power, which doesn''t lean heavily on genie tropes or monkey paw curls -- it doesn''t condemn you for wanting to change the status quo or punish you karmically for actually using your supernatural powers, which is quite nice. \r\n\r\nCaveats? I wasn''t really that into the massive political storyline that dominates the last act of the game, but it''s not badly made, just not my cup of Witch Tea. But the thing that didn''t sit well with m', 'The game is really wonderful but it is ruined by a constant hate speech against men... only "women and non-binary people" can become witches, because "men are too priviliged"... too bad.', 'Very Positive', 94.56, 7.43, 13.45);
INSERT INTO reviews VALUES (35782, 1340640, 175, 'Breaking your legs simulator.\n\nSuperb. Doesn''t overstay its welcome. I thought the few physics based puzzles scattered around were neat if simplistic, story is straightforward, controls responsive, maps lovely and somewhat varied. More intruiging than scary. Even though I didn''t utilized it I thought it was a super nice addition to be able to remove enemies via the menu if anyone struggles with those and just wanna experience the story. Also that one can unlock the camera via menu and play throu', 'while the game looks good its very bland and frustrating, the environments are really nice, but its the same puzzle for each chapter and the challenge comes from being chased by a goofy animation in a very enclosed room with very limited stamina', 'Very Positive', 81.14, 6.57, 1.68);
INSERT INTO reviews VALUES (35799, 1341050, 308, 'In 10 years, they''ll call this a must play retro classic.', 'Legitimately one of the worst games I''ve ever played. Controls poorly, story is bad, the designs for the outfits are questionable, just a really poorly made game.', 'Mixed', 58.12, 7.70, 14.27);
INSERT INTO reviews VALUES (35805, 1341160, 346, 'by far the  best paintball game out rn. gives old greg hastings vibes.\r\nthe gun and gear selection is big considering how small the studio is. very impressed', 'Oh, you absolute show-offs. You button-mashing, skill-spamming, sweat-drenched champions of destruction. Do you ever get tired of ruining everyone else’s fun? Or is it your life’s mission to make the rest of us feel like clueless amateurs while you play like the game was built just for you?\n\nYou move like the rules don’t apply to you, dodging, scoring, and pulling off ridiculous plays like you’ve got cheat codes wired into your brain. And then you have the nerve to act surprised. “Oh, that was j', 'Very Positive', 86.13, 12.70, 0.08);
INSERT INTO reviews VALUES (35808, 1341200, 433, 'The cheapest to get it is just buy the base game and then do the season pass... you save about 10 bucks.', 'I''ll keep it simple for the lazy readers. Game Is eye candy nice, but very very boring compared to previous Dynasty Warriors.', 'Mixed', 54.97, 30.05, 16.22);
INSERT INTO reviews VALUES (35809, 1341210, 245, 'I''ll be honest, I had high hopes for this one. And I''m hoping that perhaps the Dev''s will polish this one someday!!! If this is polished I would definitely play it again!!! So without further ado:\r\n\r\nFirst the mechanics are clunky. Needs fluid motion that games from even 2014 have. Needs a mini map on a bottom corner somewhere so you do not need to open map all of the time. You need to be able to mark destinations and have directions lined up for you. Items locations for crafting need to be mark', 'This game had so much potential, but it sadly appears to have been abandoned.', 'Mixed', 60.00, 2.28, 6.02);
INSERT INTO reviews VALUES (35815, 1341290, 5297, 'This game, and series of games have some pretty big pros and cons. The pros are that the puzzles are different each time and feel new and fresh with each iteration of the We Were Here series. The con is that you need a friend to play these and as an adult aligning free time is like aligning planets.', 'THIS GAME IS SO ANNOYING ITS SO HARD WITH NO CLEAR INSTRUCTIONS !! MOST OF THE TIME WE WERE LOST AND HAVE NO IDEA WHAT IS  THE MAIN THING TO DO . \r\n I DON''T RECOMMEND IT.', 'Very Positive', 93.60, 11.42, 10.03);
INSERT INTO reviews VALUES (35826, 1341490, 337, 'I like the way it does the gun shoot stabby time magic thing. Wish multiplayer had the endless mode, and also wish more difficulties were unlocked from the start since the game can be a bit easy.', 'trying to be too much\nends up being too little\nthe mob kills aren''t satisfying. the weapons aren''t satisfying. the progression isn''t satisfying. the boss fight wasn''t satisfying\ninventory system is buggy. movement system is buggy (both likely due to overall bloat)', 'Very Positive', 83.38, 49.83, 1.35);
INSERT INTO reviews VALUES (35840, 1341820, 1049, 'As a huge fan of choice-based games, I was absolutely immersed in the story of As Dusk Falls. The narrative pulled me in from the start, and I found myself hooked until the very end. The storytelling is beautifully done, with every decision feeling weighty and impactful. Honestly, I was so engrossed that I was surprised I didn’t leave a review sooner after finishing the game.\n\nThe emotional depth and tension in the story make it an unforgettable experience, and now, with a little luck and a RAM ', 'Where is Book 3??? How can you release an unfinished game and then make absolutely no effort whatsoever to even let us know if another chapter is coming? It’s been YEARS with no word. Wtf? Can’t recommend an unfinished game', 'Very Positive', 88.94, 5.78, 9.57);
INSERT INTO reviews VALUES (35863, 1342260, 594, 'add crossplay and relaunch the game', 'Recent update has given me a "Failed to connect" error when I launch. Can''t even play my fave fighting game on Steam when the whole reason I bought it was for the Rollback inplemented', 'Very Positive', 81.99, 1.32, 6.82);
INSERT INTO reviews VALUES (35866, 1342330, 1972, 'Running Nintendo''s business model better than they have, before they can, and then buying them out cured my depression.', 'It''s really tedious and unimaginative.\r\nWay too formulaic, you can''t have any creative direction because the games will need to use the perfect slider settings to make a hit and even then, you barely will sell.\r\nNo focus on abilities since you can just brute force it with more employees instead (which makes no sense really).\r\nPretty bad :(', 'Very Positive', 93.26, 403.38, 32.02);
INSERT INTO reviews VALUES (35879, 1342620, 543, 'As far as virtual CYOAs go, this stands out above most of the others.  \n\nAsk yourself this - if you were at a used book sale and you found something for $1.50 that told a good story which incorporated an awesome location (Białowieża - Europe''s largest surviving primordial forest), crazy werewolf lore, a journey of self-discovery, and modern political struggles all at once, but also had fantastically good illustrations, and on top of that played an absolute banger from a Belarusian fantasy-folk b', 'Half the dialogue makes little sense, you pick an option expecting one result and the exact polar opposite happens.\r\n\r\nI expected a fun fantasy experience, not some leftist political drama.', 'Very Positive', 84.53, 10.90, 4.93);
INSERT INTO reviews VALUES (35888, 1342790, 224, 'the game is fun a little buggy but i like it id like to see some nude mods for the game', 'Everything by Raptor Lab so far as been...ok.  Playable, but needs work. Work which is never completed with any real attention to detail or quality.  Promises half met, this is the way Raptor Lab''s MO.\n', 'Mixed', 67.41, 10.43, 0.47);
INSERT INTO reviews VALUES (35891, 1342890, 515, 'The game itself is fine. Making a level 5000 achievement should be a war crime.', 'One year ago when I first played, I would have easily recommended this game. However, the latest update introduced new achievements that serve little purpose other than to drastically increase play time and repetition. Getting to level 5000 seems to take approx. 100 hours of playtime just repeating the same things over and over and over again (the base game is only 4 hours of gameplay and gets you somewhere around level 225).\n\nAlso, the DLC was not updated with the latest game update, so the DLC', 'Very Positive', 89.13, 91.78, 6.93);
INSERT INTO reviews VALUES (35906, 1343240, 3146, 'Decent game, not for everyone, you wont find a deep story, friendly characters or comfy gameplay, this is just you, your reflexes and the enemies. The parry system is what made me finish this game, you just have to be patient, learn the patterns of the enemies and then, CLONK! CLONK! CLONK! pure satisfaction, my best advice to have fun here is to become the parry king.\n\nNot a spectacular game in any aspect but a thumbs down would be unfair, have fun friendos.\n\n', 'Honestly wish I could be more positive about this game but having played games which inspired it (Sekiro and Bloodborne) i have to say this is a hard pass for me.\n\nIt incorporates the worst aspects of any souls-like title. Bosses slide across terrain to ensure that every single attack swing can land. And their tracking is just as bad. There is no point in trying to dodge or circle around or distance yourself from bosses as that is not a relevant strategy. So you must parry. Except the parry wind', 'Very Positive', 83.38, 12.13, 1.85);
INSERT INTO reviews VALUES (35924, 1343670, 267, 'I dont know rick, it looks fake.', 'The gameplay loop is fine, but it drags out a lot, once you get some sort of wealth going there is no danger of ever declining from that point, and then there is just several hours of repeating the same sales tactics to gradually get richer and richer', 'Very Positive', 81.65, 5.33, 10.58);
INSERT INTO reviews VALUES (35930, 1343810, 318, 'I''m so normal about this series. So, so normal. I''m not obsessed at all. It''s not like every time I finish a playthrough I start gushing about the variables, the secrets, the characters, the end states, the romances and general replayability value of this book to everyone I know who is also into interactive fiction - even if they haven''t read it yet and aren''t likely to, because superpowers and heroes are just not their thing. It''s not like I''m sad that I have no one to properly discuss the book', 'I don’t personally know the creator of this series, but by playing this second installment I get the impression that they received lots of different types of feedback from the excellent first game and then in the sequel tried to cater to a wider audience to the detriment of their vision. Forget all of the exciting mind games of Rebirth, because in Retribution you will be playing a seemingly never ending dating simulator where it seems that none of your choices matter while most of the exciting s', 'Overwhelmingly Positive', 97.17, 23.98, 12.62);
INSERT INTO reviews VALUES (35950, 1344530, 138, 'Works on Reverb G2.\n\nIt is a woodworking sandbox with the most immersive building mechanics in VR. I had no interest in carpentry, but had fun playing the campaign mode.\n\nGameplay is very satisfying, despite some inevitable physics item interaction jank. vrkshop takes realism and immersion seriously: there are no ugly flatscreen GUI elements, everything is done with diegetic tools and paper forms. Sawing, hammering and measuring is responsive and intuitive. I wish I was any good at it, though :)', 'I couldn''t even draw a straight line to cut a board. Bought this so i could test run a project before going out and buying the materials. Not worth it.', 'Very Positive', 85.51, 6.90, 0.33);
INSERT INTO reviews VALUES (35957, 1344740, 389, 'This literally taught me more about fighting games than any other fighting game. Fantastic for learning. Fantastic to play with the people who complain you won because of your combos', 'If you arent born with fast enough reactions good luck getting past whiff punisher. Also being negative on break just seems wrong.\n\nIt doesnt whiff punish it will frame perfectly short you if you try to approach and if you are too slow to react to its moves it will always hit you.', 'Overwhelmingly Positive', 95.63, 0.93, 1.10);
INSERT INTO reviews VALUES (36001, 1345890, 1100, 'Due to the many negative reviews, I nearly did not buy this game. However, I enjoyed ''Deliver Us The Moon'' so much and was engaged with the story that I went ahead and bought it anyway. I love it! The story was very interesting and engaging, much like the Moon part, and it has left me hooked, waiting for the next chapter.\n\nA very large portion of the games I buy end up disappointing me, often not even bothering to play them to their conclusion. I am very picky about the types of games that suit ', 'Absolutely not worth the price tag, awkward character animations, glitches, and the writing. OMG the writing REEKS of pompous LA Millenial. Almost none of the characters are likeable and they are all ugly due to the terrible character models. I got it for $15 and still regret it.', 'Mostly Positive', 73.45, 41.27, 7.57);
INSERT INTO reviews VALUES (36003, 1346020, 223, 'It’s Wargroove 1 but with a roguelike mode and more units. It’s good. It won’t be liked by everyone, but the balance is good now and the bugs are fixed. Worth getting on sale for sure. Square-grid tactics games are hard to make, and I commend the developers for not only making it fun, but also adding full support for custom campaigns and events. 9/10', 'Imagine plot writers so stupid that they propose to unite two nations in blood by marrying two princes together.  Just wow.  Wokeness truly robs people of all sense.  Shame too cause I liked the first game and this one isn''t bad otherwise but the story is woke garbage.', 'Mixed', 67.71, 4.53, 12.60);
INSERT INTO reviews VALUES (36008, 1348390, 254, 'Please add the Pilot Story as well to the game', 'I''m really happy that ATC4 was finally available to the EN community, but I was pretty disappointed that we couldn''t get IRL airline liveries like the ones in the JP versions of this game. It wouldn''t make sense to deny the EN community the same option that the JP community has for this game, it also wouldn''t make sense on them being unable to supply us the real liveries due to a copyright lawsuit...cause well...if you think about it, what''s stopping multi-million dollar airlines from submitting', 'Mostly Positive', 77.95, 38.02, 66.15);
INSERT INTO reviews VALUES (36011, 1350840, 451, 'Overall it''s a game that I would recommend to others but it definitely has some aspects that aren''t super ideal. \n\npros: it''s cute, the skill system is fun, it has great characters, the questing mechanics are fun, the inner world mechanic is AMAZING, and much more.\n\ncons: it''s very grindy. for starters, i''m on year 2 and still can''t date any characters (let alone marry them) because of how much effort it is to raise these friendship values. you can give them their favorite gifts and get the best', 'Unless you are a diehard farm sim fan, this game has an excessive amount of bugs and a lot of them are game ending. The characters are likeable except for most of the males. No gay marriage because china discriminates and the devs have no intention on providing an option.\n\nWhile I found it incredibly enjoyable, I know that the vast majority of players will not have a pleasant experience in the end. I have little faith in the developers to proceed responsibly or fix their product out of an alpha-', 'Mostly Positive', 78.27, 53.47, 128.53);
INSERT INTO reviews VALUES (36012, 1351240, 1001, 'as a girly with autism who loves driving simulators this is the perfect simulation game. i’ve had this game since release on xbox then decided to get it on my PC and a lot has come into to it since the start. the realism in this game is really good and i can play hours! Only dislike and bad side is the NPCS walking in the road at random moments )): it can be quite annoying. Also for your employees it can sometimes interfere with your money making depending on the cons of the driver and i’ve had ', 'TERRIBLE AI CARS AROUND YOU, PEDESTRIANS PROGRAMMING ALSO TERRIBLE (Goes back and forth in the pedestrian lane, like literally while being infront of your taxi), TRAFFIC JAMS Seriously dont move (and there''s no way to reset traffic just in case this happens) GPS SYSTEM IN GAME IS FAR FROM BEING GOOD, SIMULATOR + CLUTCH MODE IS FAR FROM BEING AN ACCURATE DRIVING EXPERIENCE, Gas Pedal and Clutch sensitivity system is still trash no matter how I adjust it. (and Im using Logitech Steering Wheel with', 'Mixed', 63.94, 14.58, 101.13);
INSERT INTO reviews VALUES (36015, 1353300, 323, 'relatable', 'it''s amazing how they managed to take the worst part of the game (bonus stages) and made them even worse (aot crossover stages)', 'Mostly Positive', 71.52, 223.27, 1141.65);
INSERT INTO reviews VALUES (36022, 1357210, 1243, 'While interesting, the galaxy being split into multiple sectors separated by a single paths doesn''t enhance the game play that much. It seems to slow things down.\n\nThe most annoying thing about the game is the bright galaxy background, it sometimes makes it hard to see objects in the foreground.\n\nIt would be nice to be able to build a generic starbase like in galactic civ 3 and then choose what type afterwards. Requiring a mineable object to be in the initial starbase area of effect to create a ', 'New free update changes how custom species work and kills your ability to add your own portraits to make your species look how you want.\nNOW you gotta pay for the DLC to actually do this again. So content has been stripped out and packaged for money. This annoys me.', 'Mostly Positive', 73.53, 342.43, 174.07);
INSERT INTO reviews VALUES (36024, 1357860, 616, 'Short and simple but fun, also very cute. Although, there is just something hilarious about loading children into a death canon as a game mechanic.', 'Using children''s souls as cannon ammo...\nNo. Just no.', 'Overwhelmingly Positive', 95.62, 26.55, 0.47);
INSERT INTO reviews VALUES (36027, 1359980, 4302, '10/10 Best Postal game\nFun Fact: You can cancel any weapon animation by hitting the piss button for a sec, AKA: Piss Cancelling\n\ndoom eternal but you can smoke crack in a walmart\n', 'Ill-conceived open locations, I stuck on an island in the air with no way to get out, often unclear where to go and what to do, completely ill-conceived shooter not linear, more like another part of the Postal with an open world in which you have to entertain yourself.', 'Overwhelmingly Positive', 95.61, 3.03, 0.43);
INSERT INTO reviews VALUES (36029, 1361210, 64283, 'The problems of this game are outside of the actual gameplay, which is immaculate, and is definitely worth playing now that skill trees, itemization, and built in cosmetic unlocks have been fixed/improved.', 'I can no longer in good faith wait for the game to be improved.\nCrafting update delayed for 1.5 years and counting.\nPromised Solo mode update never.\nNew classes each quarter was a lie.\nWhere are new maps for a live service game?\nCosmetic cash shop updated regularly though.\nIncredible disappointment from an incredibly promising game.', 'Mostly Positive', 73.43, 1261.88, 169.93);
INSERT INTO reviews VALUES (36032, 1361510, 5561, ' story is whatever but the mechanics and the gameplay (especially in the shard/survival mode) keep me coming back to play more even after over 500 hours. highly recommend playing if you consider yourself a Ninja Turtles fan. cowabunga dudes', 'The pixelation looks horrible on my 4k monitor. I mean, the game looks great in the videos, but I just can''t get past the blocks. However, I bet it would be fine on a small screen like a Nintendo Switch.', 'Overwhelmingly Positive', 96.21, 972.75, 0.17);
INSERT INTO reviews VALUES (36036, 1363080, 31968, 'as of 24/12/2024, i have seen some adverts from a game called "king of Avalon," on youtube using footage of this game. however i cannot report it and i suspect that the footage is being used without consent. i do not know how to contact the devs about this.', 'Interesting concept. I enjoyed the first 20 hours, but there is very little to do. I would love better castles, more manors, town guards, watching other AI build their towns and trying to keep up, etc...\r\n\r\nWait for more content before purchasing.', 'Very Positive', 89.27, 2.12, 77.47);
INSERT INTO reviews VALUES (36039, 1363850, 126, 'Monument Valley with GLaDOS.', 'WAS NOT IMPOSSIBLE', 'Very Positive', 84.92, 0.42, 0.85);
INSERT INTO reviews VALUES (36042, 1364100, 609, 'How refreshing: Lacuna is a somewhat unique investigative adventure because it actually allows players to fail without resulting in a death- or game over-screen. You play as an investigator trying to crack a case by looking for clues and interviewing suspects and then putting it all together. While it never gets too opaque, you will need to stretch those deduction muscles a bit. You can (and will) f*** up if you don''t pay attention. But the game is robust enough to allow for blaming the innocent', 'If you''re sensitive to motion sickness be aware that this is probably not the game for you. I couldn''t get through more than a few minutes of the beginning of the game with the camera movements before I felt like I was going to throw up. I tried to turn off the camera shake in settings, but it didn''t change anything as far as I could tell.', 'Very Positive', 92.12, 17.88, 0.37);
INSERT INTO reviews VALUES (36043, 1364290, 1738, '" bad community" dont play this game" "so many bugs" blah blah blah they are all wrong, first the so called bad community i have not met a mean player in the time i have played this game and when i just join as i hippo there was 2 crocs one left being a croc to be a hippo with me shout out to LingLingheeya1 for doing that for me. and the dont play this game though it can be boring at times when you meet the right players and go to the right place im just gunna say its lots of fun and if your bor', 'They are charging 15$ USD to play as a bunny. \nWhat kind of Mickey Mouse BS is this????\n\nAlso to everyone thinking about buying this, there is only 1 active multiplayer server that averages around 55 people.', 'Mixed', 63.46, 11.65, 26.97);
INSERT INTO reviews VALUES (36044, 1364780, 16987, 'Dissapointing-\nThe game is fine, runs just fine and is a great evolution in the series BUUUUTTT... Charging a full $60 for the game, and then offering a "yearly character pass" for 4 DLC characters for $30 is just GREEDY BS.... so if you want to play the game, and get 8 more characters over 2 YEARS, you pay $120 for it... Can we just pay a little more and have the whole game? why are fighting games doing this now? making you pay for the base game, but you pay double if you want the "real game" -', 'No upgrade path for the people who bought the base game before is disappointing', 'Very Positive', 87.04, 59.30, 765.77);
INSERT INTO reviews VALUES (36050, 1366800, 16726, 'The gameplay and story is insane, can''t stop playing it', 'fatass giving me an ad for his other shitty piece of useless software every time i boot it up', 'Very Positive', 94.18, 220.35, 8190.90);
INSERT INTO reviews VALUES (36055, 1368030, 1710, 'This game is a little gem which if it got more polishing it could really shine, unfortunately the combat system and the rpg components really need some reworks to make it more enjoyable. Still I recommend it, I really enjoyed the graphic and the charas, so if you can deal with the flaws you won''t regret it, though avoid the collector''s edition (you can read here https://steamcommunity.com/id/ChronoMkIV/recommended/1909960?snr=1_5_9__402)', 'I really wanted to like this game. The game design itself is interesting and fun. Lots of cool UI choices, and the overall art direction is solid. The first cut-scene feels like something out of blade runner, evangelion, and arcane all at once. Very cool vibes. The graphics are really compelling, vibrant, and just feel good. However, the game-play itself feels like very stock player movement. The animations try to save it by looking weighty, but the actual movement feels like any generic input t', 'Very Positive', 89.82, 24.45, 1.12);
INSERT INTO reviews VALUES (36057, 1368850, 158, 'I love the original, but this version is indisputably better. I just beat the first one, and I''m playing this back to back. The quality of life improvements are great. If you like traditional tower defense games, this one is one of the best. Worth it at full price, but I got it on on sale - all the better! Glad I can finally support the creator of this game.', 'This is a COMPLETE ripoff!  This game is IDENTICAL to Cursed Treasure 2, except the interface has be SLIGHTLY altered to be a mobile game.\n\nThey took Cursed Treasure 2, ported it to mobile, made the controls huge so you could use your finger instead of a mouse, removed obvious PC interface things like the use of ESCAPE key (SERIOUSLY???), changed the static load screen to have these two ladies, and that is it.  Original PC game made worse, ripping off fans of the original, selling them the exact', 'Mostly Positive', 70.25, 35.00, 0.73);
INSERT INTO reviews VALUES (36059, 1369670, 3763, 'gta sa mp – only about cars\ni started working as a taxi driver. two people got in my car and wanted a comfortable ride. in the middle of the road, a street racer pulled up and decided to race me. i couldn''t just let it slide, so i accepted the challenge. in the end, i won because he crashed on a turn, but my passengers weren’t very happy. they kept hitting their heads against the car and ended up paying me less\nthe game is cool! there are many different jobs with various cars. once you earn enou', 'Was in love with it until i realised after upgrading my way to the best trucks that the economy is built to punish you for progressing. Who on earth thought it was a good idea to make the same cargo at the same weight, have different sell values depending on the truck used? This means that the beginner 40k flatbed truck + small trailer can bring in far more $$ per hour than the 300k truck with a 100k flatbed can. Just WHY????\n\nThis backwards feature applies to all professions and only incentives', 'Very Positive', 93.54, 6.12, 13.70);
INSERT INTO reviews VALUES (36061, 1371580, 3098, 'Great game, I''ve played on many servers and made many friends, everyone is friendly, except for some Asian players, they are keen on attacking and looting, although I have defeated them many times, but they are too crazy! So now I enjoy playing on my own server, so I can collect all kinds of warriors and all different colors of horses. The developers seem to have started to listen to the opinions from the community recently, which is great, just like they did at the beginning, once the new DLC, ', 'If you aren''t Chinese don''t bother buying this game, all servers including the North American servers are 90% populated by Chinese players who not only hack, but relentlessly harass and destroy any player who isn''t also Chinese. They quite literally make it impossible for you to play whether alone or with friends. I used google lens to translate some of the things they say in the server chat and it''s always along the lines of "foreigners have no ability" "foreigner located at (location name)" et', 'Mostly Positive', 73.66, 4885.12, 162.70);
INSERT INTO reviews VALUES (36062, 1371980, 16204, 'I’ve played this game since its initial release, on the Steamdeck. Even then, in its very unoptimized state I couldn’t put it down.\n\nWith the crucible, and now Breach update the game has gotten even better! Once you play the game you’ll see why it’s taking so long. The amount of artistry being put into this game is just incredible.\n\nLet Moon Studios cook. When this game launches into 1.0 it’s going to be something special.\n\nI hope this helps. I hate writing reviews.', 'Just tried the breach patch. The devs are trying to make a souls like with the camera pulled way back. Fine aspiration, but this game is dead set on wasting your time and making you replay content. Waiting for town upgrades. Only able to teleport between the main city and the last portal you visited. Grinding wood, ore, food... etc. I swear I''ve chopped more trees than enemies in this game. \n\nMore importantly, the combat is not well designed. Attacks in a souls game need to have a certain level ', 'Very Positive', 85.66, 228.97, 10.38);
INSERT INTO reviews VALUES (36066, 1373090, 311, 'Tried to be a benevolent king, ended up broke, betrayed, and emotionally attached to a bear. Yes, Your Grace: Snowfall is peak medieval micromanagement with Slavic spice. 9/10, would ignore advisors and trust gut instincts again. 🕊️👑❄️\r\n\r\nFollow my curator page for more snowy thrones and royal regrets!\r\nhttps://store.steampowered.com/curator/42602807-Osiris-Reviews/', 'DO NOT BUY AND HOPE YOU WILL BE ABLE TO PLAY IT. The game in its current state if FULL of Bugs. If you take a look through Steam Forums you will notice that every 2-3nd topic is about a GAME BREAKING BUG, preventing someone from continung to play it. I myself got hit in Chapter 3 with multiple of those and can no longer progress the Game, you will not get what you pay for, this is misleading its not a finished game at all.\n\nUpdate: The Developers are fixing some Bugs already, however the overall', 'Mostly Positive', 73.63, 0.72, 18.70);
INSERT INTO reviews VALUES (36067, 1374290, 276, 'Thank you for these EPIC games!! Keep going!', 'One of the lesser good games from this dev. Relatively short game, repetitive, tedious puzzles mixed with oversimplified ones, a boring story and a very cringe narrator. \n\nNot this time, sorry.', 'Mostly Positive', 78.99, 3.67, 7.13);
INSERT INTO reviews VALUES (36068, 1374490, 15254, 'Things I want from this game as a solo player:\r\n- Pause in solo play.\r\n- Build from storage.\r\n- Better optimization on encounters. Feels like every 30 seconds I''m getting rained on by the dragon, hunted, or raided. I just want to chop some wood, sod off for ten minutes!\r\n\r\nOverall, having fun. Solid start for the game.', 'unable to turn off post processing effects like TAA, motion blur and bloom makes the game very uncomfortable to play and makes everything look like it''s been smeared in vasaline', 'Very Positive', 83.91, 18.00, 0.57);
INSERT INTO reviews VALUES (36078, 1380070, 625, 'This is a fantastic game. I have not seen anything else like it. I am male and prefer female slaves so that is my point of view for this review.  It is easy to earn money to buy slaves. Once you own them you can enjoy them in your dungeon at anytime during the game. There is some first person shooting (bow and arrow) which I enjoy. Great care has been taken to make sure that male parts fit perfectly into whichever female part you chose to enjoy. You can talk to, punish or enjoy your slaves. You ', 'This is a difficult down vote for me. The art is good. I bought the game because I wanted a BDSM game with high quality characters, and I got that. \r\n\r\nEssentially I think it boils down to not vibing with the training mechanics. To unlock new positions with any real viability is by ''punishing'' the slaves. There is a love bar, and you can get some skill points in other ways, but it really is just whip and beat. Because of this it feels a lot more like an abuse simulator than a trainer, which seem', 'Mostly Positive', 76.48, 80.57, 5.13);
INSERT INTO reviews VALUES (36083, 1383150, 186, 'I just beat the game. and, honestly, the game was pretty good. took me around 80 hours to so. my main... MAIN issue with the game was creating a transport station for resources. they seriously need to revamp that entire system. by the end of it i had around 20 iron transport ships, 20 silica transport ships, and like 30 bau transport ships. and each one of them needs a specific load and unload point and unique name. it was REALLY annoying to deal with. especially when one of the astroids would r', 'This game values complexity over depth.\nEarly-ish game features like planetary research bots require a lot of sub-combines and resources from different asteroid mines to produce. That in itself is fine.\nThe problem is that the criss-crossing spaghetti that would be required to connect all these factory snippets is not allowed in the game. Any form of mass-transit (other than slow and bulky mass drivers) must go straight horizontal or vertical.\nI was looking forward to researching cargo bots beca', 'Very Positive', 83.87, 202.92, 10.60);
INSERT INTO reviews VALUES (36085, 1384630, 376, 'I''ll be brutally honest here. The gameplay is so bad that it feels like something created by a beginner using a 3D game creator. It''s very clunky, and most of the content doesn''t really make any sense. BUT, there''s one thing that should interest fellow perverts: the adult content. There are dozens of high-quality sex scenes, and exploring them all makes this game worth the price. The ideas for the scenes are so interesting and executed to a high standard. This stuff alone is worth the money, so ', 'Yeah, no. So, I like the concept, but... BUTT! Yes, I love the butts... but... One, there''s no map. You have to figure out the coordinate system which it doesn''t explain at all. Middle number is elevation BTW if you''re wondering. Why on Earth is there no map? Anyways, you can get used to the coordinate system, but unfortunately you can''t even get to the quests. The game doesn''t even say it''s in early access, but this is basically an alpha testing build. No real skill system. Invisible walls EVER', 'Mostly Positive', 71.81, 1.30, 0.63);
INSERT INTO reviews VALUES (36087, 1384700, 179, 'Great I like men🔥☝️🗣️💯', 'It’s like Fire Emblem i̶f̶ ̶i̶t̶ ̶w̶a̶s̶ ̶g̶a̶y̶', 'Very Positive', 90.50, 0.43, 0.38);
INSERT INTO reviews VALUES (36093, 1386890, 109, 'Its the best game evr (ignore the 10 hours thing i play hyper dash mostly on my meta quest instead of steam vr)', 'I see what they are going for but with the huge amount of kids screaming and main tactic is "Hold both guns in front of your face and spam pew pew" its not the game for me.\nMaybe i''m just getting old, but i would spend my money elsewhere.', 'Very Positive', 87.16, 10.10, 0.28);
INSERT INTO reviews VALUES (36094, 1386900, 1040, 'You guys want to know something crazy? I first watched Blade Runner in 2019 (the year the film took place, and the year both Roy Batty and his actor Rutger Hauer ironically passed away) and I fell in love with the film. It became my favorite film. Then I play this cyberpunk game starring Hauer, and it takes place in the very city where my family overseas lives; Krakow, Poland. A beautiful city I love visiting. I just thought I''d share all the irony.\r\nThis is a beautiful game where Hauer takes De', '<<<<<<Motion Sickness>>>>>>>\n\nGlad i found the story on yt because i can''t play this game anymore. I can say the story is great but gameplay is so boring and trips... made me vomit. \n\nIt''s my fault i didn''t see Psychological Horror tag but a game shouldn''t make you feel sick.', 'Very Positive', 85.19, 5.52, 5.73);
INSERT INTO reviews VALUES (36098, 1388880, 9267, 'This game changed my life and simultaneously made me want to kill myself out of nostalgia. I will never be 10 again and it haunts me to this day. 10/10', 'this game ruined my life', 'Overwhelmingly Positive', 97.03, 15.82, 8.78);
INSERT INTO reviews VALUES (36100, 1389990, 716, 'w aim so good now all the val egirls want me 10/10', '"Help find your perfect sensitivity" this "system" does not learn on your player its like it randomly throws out numbers and the worst part is its either a low sensitivity of 30 dpi or its obsurdly high like 9900 dpi not in between. I do NOT recommend this at all.', 'Very Positive', 82.54, 12.08, 0.47);
INSERT INTO reviews VALUES (36101, 1390190, 1044, 'APICO is a very good simulation game where you take care of the hives and bees. With some cutes pixels graphics and a chill ambiant, I recommend it!!! 💗🐝💗', 'Sexual mutilation pronouns propaganda.', 'Very Positive', 93.01, 69.97, 1.85);
INSERT INTO reviews VALUES (36103, 1390350, 6731, 'As a amateur lover of the insectoid and arachnoid world, I can''t recommend this sacred chest highly enough to arachnophobes, because you can turn this fear from the fearful into the pleasant by recognizing that cruel nature also has the grace to glimpse us with its senile humour and its way of carrying out the cycle of life it has been given. \n\n I therefore recommend Webbed to all nature lovers and those who fear it, as it was lovingly made to teach and get to know in an alternate comical cute w', 'sadly I did not enjoy this game and I feel like the description of the game is missing an important tag. This is definitely a PUZZLE platformer. You''ll do way more web connecting & dragging things around the first couple of hours compared to jumping and swinging with webs and I just couldn''t power through it to see if the rest of the game had more platforming. Its not bad I don''t think but its really not my genre and better tags for the game would have helped me avoid this game. If you like puzz', 'Overwhelmingly Positive', 97.31, 61.77, 2.63);
INSERT INTO reviews VALUES (36110, 1394960, 129, 'I love the potential this game has. It is a bit frustrating with the insane concept because as a survivalist I would LOVE to live like this and it wouldn''t affect me as easy as the mechanics currently do in game. I would love to see the food last a bit longer considering you live in a freezer. I would also love the ability to construct your own nails, as it is quite possible even in the real world.  I am currently in Survival mode only as I hate questing. I love building and surviving. Devs have', ' I use to say... oh its just early access it will get better... no no it wont, and you will just give your money to another subpar game.  I will be surprised in 6 yrs from now if it gets better.  If it even gets to there', 'Mixed', 59.69, 210.77, 1.03);
INSERT INTO reviews VALUES (36111, 1395030, 506, '8/10 After playing through the Nancy Drew games I need more female detective games and Kathy Rain delivered. A bit crass, a bit angsty, Kathy Rain takes on the case to solve multiple mysteries all wrapped up in one story. This game has great art, good voice acting and some solid puzzle solving making it worth checking out.', 'While the game looks and sounds great, riddles are engaging and fun, the story is unfortunately mediocre and characters are flat.', 'Very Positive', 93.68, 8.97, 6.53);
INSERT INTO reviews VALUES (36118, 1401590, 13339, 'Honestly, I didn’t expect to get hooked like this. It’s the perfect mix between a cozy life sim and the Disney universe we all grew up with. At first, I thought I’d play it here and there, but now I find myself logging in every day. Time flies when you’re in it, in the best possible way. It’s a bit like Animal Crossing, but with a more lively and magical vibe. Every character has their own personality, unique quests, and fun little interactions. You really start to get attached to them, and it f', 'The game was supposed to become free to play at some point but devs changed their mind and it will permanently remain buy to play.\n\nMy ick here is that they are going to be keeping the free to play monetization model they added/started way before deciding of not going free to play anymore. When the game was planning to be free to play, I could get behind the idea and system since they would need the funds to continue developing the game overtime, but now that it will remain a fully priced game I', 'Very Positive', 90.92, 1959.82, 252.05);
INSERT INTO reviews VALUES (36119, 1401730, 479, 'It''s basically Crashlands 1, but better in every single way. Love it.', 'Unfortunately suffer from the woke virus. Plus no way to resize window as they had promised in the first one.', 'Very Positive', 93.53, 111.55, 1.38);
INSERT INTO reviews VALUES (36124, 1403310, 174, 'Played on steamdeck. No issues works well. \n\nI loved this game it’s very cozy and there is always something to do. \n\nLots of upgrades and unlockable items to work towards. I wish there was more controls on planting, I often had issues getting plants lined up exactly and it bothered me. \n\nFor the price definitely worth a try.', 'not a terrible game but definitely not worth 15 dollars, its just the one yard and you barely have to do anything to clean it up, there''s not a lot of decorations to unlock either', 'Very Positive', 82.76, 4.30, 2.45);
INSERT INTO reviews VALUES (36127, 1404090, 185, 'Def a good trivia game, love the workshop support. Only thing is I wish that it had some sort of web connect mode in the vein of what the dub or jackbox so that I could play it easier at parties by just hooking my steam deck up to a screen and everyone using their phones. Other than that good game.', 'It''s not very good. \r\n\r\nIt''s functional, and it''s neat that there are user made question packs but it''s very basic and barebones. There is nothing to make the game feel any more engaging that just doing trivial questions on some random website. There are games like You Don''t Know Jack that really add some extra flare to make trivia feel fun, and then there is this game on the opposite side of the spectrum.', 'Very Positive', 92.97, 3.82, 7.58);
INSERT INTO reviews VALUES (36128, 1404210, 29188, 'The fun comes with friends. The actual content you can play is not thaaaaaat longtime fun, but with friends...it is always. So grab some friends and join the wild wild west!', 'Rockstar has created a lovely piece of Abandonware. It''s filled to the brim with hackers, much like GTA online, the difference here being, they''ve entirely abandoned Red Dead. I quite literally CANNOT play the game, without being teleported into the middle of the ocean, having seven thousand boats spawned in the sky above, explosions which chase the player infinitely, and eventually just remain on their person, preventing gameplay entirely. And they have about 50 ways to prevent you from reporti', 'Very Positive', 81.75, 150.38, 240.58);
INSERT INTO reviews VALUES (36131, 1406780, 420, 'Bought the game since EA, love it then and love it even more now. High speed movement, intense gun fight battles. \nEven quite gory at times, what is there not to love for any FPS fans. \nEven though you have limited ammo capacity and most the time you regain HP and Armor back by gibbing and meleeing enemies. It''s done way better than modern Doom like Doom Eternal....because the momentum is always there and never slowing down to a cutscene... \nGame is punishing, it''s hard and challenging. But not ', 'woman escape from kitchen', 'Very Positive', 90.71, 23.05, 0.95);
INSERT INTO reviews VALUES (36132, 1406810, 148, 'To me, playing this game right now with the state of the world and the USA was a healing experience.  I''m so grateful to the developers and creators across the board - this is a masterpiece.', 'I would say this is more like a mixed review... \n\nWhile I like the storytelling and the visual of this game.... it is just doesn''t feel compelling enough to play it to completion... maybe I''ll give it another go in the future..', 'Very Positive', 81.76, 24.75, 4.48);
INSERT INTO reviews VALUES (36133, 1406850, 286, 'Really fun game.\nThe combat in levels become a bit repetitive at the very end, but still fun and the boss battles make up for it as they are really creative.', 'The art style is very good, as is the combat system. The game suffers from too much linearity and repetitiveness.\r\nThere are some good ideas here and there, but they are all almost half-cooked.\r\n6/10', 'Very Positive', 94.06, 7.07, 7.23);
INSERT INTO reviews VALUES (36136, 1407200, 172, 'Very fun game. Alot of DLCs to have get. Sadly World of Tanks on steam wont let you use your account you created through WG. Which I think is stupid. Not worth getting if you put hours into the game and just got steam version.', 'Absolutely disgusting and predatory Gambling Crates within Gambling Crates withing Gambling Crates, ultra late pity system and full on Pay 2 Win rewards that are atrociously overpowered and thus highly desirable.', 'Very Positive', 81.40, 0.88, 20.05);
INSERT INTO reviews VALUES (36137, 1407450, 105, 'This game is awesome.  If you like martial arts or wuxia then give it a try.  Stands up with recent releases of Wuxia JRPG.  Don''t know why it has such mixed reviews.  Full release is already out in beta testing and open release is around the corner.', 'The game has potential for sure. But if you have played Wandering Sword you wouldn''t want to play this after as it''ll just make you miss that game. If you haven''t played Wandering Sword then I''d recommend playing that game instead because it''s far more polished, smooth and doesn''t leave you wondering where you''re supposed to go because the quest journal says you have done everything, including the thing you''re supposed to be doing next so you''re left checking every location once or twice before ', 'Very Positive', 87.62, 64.05, 50.13);
INSERT INTO reviews VALUES (36139, 1408230, 2546, 'Buy this. Holy crap, buy this. Not only is the mini-golf gameplay itself super fun and feels good/responsive, but all of the courses are clearly labors of love. They''re fantastical, stylized, awe-inspiring, creative, and just wonders to play through. This game is an absolute blast, especially with friends. The devs are pumping out DLC courses on the regular and they''re super affordable and just as wonderful as any that came before them. I cannot recommend this game enough.', 'If you love mini golf and multiplayer sure go for it I guess, I''m sure it''s the finest multiplayer VR mini golf game out there.\n\nBut if you''re like me, don''t fall for the hype, mini golf is even more boring than it sounds and everything is a 4€ DLC (114.22€ total as of the time of this writing).', 'Overwhelmingly Positive', 97.80, 50.38, 6.62);
INSERT INTO reviews VALUES (36147, 1411020, 326, 'controls are super crisp, the art and animation are beautiful and the soundtrack is stellar, but already expected that after trying the demo.\nwhat i was not expecting was the amount of cool npcs, little sidequests and lore that i''m finding. will update after i''m finished and try the co op. but it''s looking like a banger.', 'When the developers started their working day in the office, they thought for a long time how to make the most disgusting control in the game. and they came up with it! and made it better, you can''t change it! (you can''t make the mouse tracking? or just hit the joystick button)\nand to this they made a boss with chess, which moves absolutely randomly. show me at least one player who has passed this boss. i really look forward to feedback from him.\nThe music is amazing. the drawing and the story a', 'Overwhelmingly Positive', 97.24, 13.85, 10.32);
INSERT INTO reviews VALUES (36150, 1411910, 4633, '🕵 Wise Guy Eh? 🤌\n\nOh you got somin'' else t'' play? Fuggedaboutit!\nCan''t ya'' see I''m talkin'' ''ere? No fugazi, play Fallen Aces or I''ll make you Sleep with the fishes...', 'As of now, I can''t recommend this game. There is one massive issue; It''s too easy.\n\nYou can sneak past most encounters, you can kill or nonlethally take down every enemy (As of now there doesn''t appear to be any consequences for killing everyone), and it''s all equally shallow. The only difference is how much you want to left click the mouse. There is no challenge on Normal, Hard, or with tweaking the difficulty outside of making enemies one shot you and you give no damage. Most players will be a', 'Overwhelmingly Positive', 98.40, 2.25, 3.07);
INSERT INTO reviews VALUES (36157, 1416050, 508, 'I don''t get the negative reviews, sure you may dislike roguelikes, but whats the point in buying a roguelike and making a bad review stating "I dislike roguelikes"? Borderline dumb.', 'it''s... fine. my biggest problem with this being a shovel knight spin off is that it makes me want to play pocket dungeon. yes i know they''re 2 COMPLETELY different genres, but pocket dungeon knocks it out of the park while this one kind of limps to the finish line?\n\nthe gameplay loop is fine, it handles alright, it''s just missing a little spark for me to truly enjoy it, an i''m not quite sure what it is. characters design are on point, the knight''s moveset is good, i just... wish i liked it more', 'Mostly Positive', 72.64, 3.95, 2.33);
INSERT INTO reviews VALUES (36161, 1417420, 100, 'Recommend for small children', 'Painfully easy, you could use easy mode as a wallpaper and never die, same with very hard mode which is difficult for maybe one second before it goes back to being mind-numbing', 'Very Positive', 92.00, 14.20, 0.32);
INSERT INTO reviews VALUES (36167, 1419850, 984, 'This game is super fun! I drank some salt water then died, and then stole a bunch of tablets in the tutorial and sold them in my shop. Now I kill all the filthy dirty customers who leave trash in my shop. 10/10 would recommend', 'This game looks and feels very cheap. It looks like a bunch of Unity templates and assets mashed together. The worst part of experience is UI. It''s awful. I bet it''s the only part of the game really made by devs themselves. It shows. Everything else is just borrowed assets and mechanics.', 'Very Positive', 88.62, 237.23, 4.17);
INSERT INTO reviews VALUES (36170, 1420350, 861, 'game is good but please stop working on other characters and focus on playable peppino', 'This game is NOT worth 19.99. Sure, the game has beautiful pixel art and mechanics, but it''s pretty much bare bones. It''s crazy how hyped this game was when the trailer came out, which led to a big disappointment. 3 years have gone by since release; the game is in the same exact state, with only two new characters and 4 assists being added. Hopefully, this game will get some massive comeback, but come on now.', 'Mostly Positive', 78.51, 16.55, 0.62);
INSERT INTO reviews VALUES (36171, 1420540, 194, 'Very basic and quick game I played on my Steam Deck. Definitely can''t recommend it, while at the same time I wont tell you not to get it and play it. Its a basic puzzle game at the core. So if you want to give yourself a little brain workout, then give it a go. Bout as much as I can say..', 'I was really looking forward to playing "Catch the Stars," but it turned out to be a frustrating experience. The game lacks any tutorial or instructions to teach you the rules of the puzzles. As a result, I spent more time trying to figure out what to do rather than actually enjoying the game. A basic guide or some hints would have made a huge difference. Until the developers add some form of instruction, I can''t recommend this game.', 'Overwhelmingly Positive', 97.42, 1.00, 0.17);
INSERT INTO reviews VALUES (36172, 1420740, 174, 'A fun little game that has many grim endings for this poor T-Gotchi gal.\r\n\r\n\r\nMaybe you can fix her.\r\n\r\nI could not.', 'took me an hour and a half to play through :) its cute, the visual design is really top notch but it overall kind of feels like wasted potential. the format of a cute tamagotchi being used to subvert expectations and induce certain emotions is really unique and interesting in concept, but in execution here it doesn''t really work for me because of the lack of player agency. I understand that this is the "point", but it really doesn''t work for me.\n\nyour amazing t-gotchi doesn''t feel like playing a', 'Very Positive', 82.76, 1.38, 1.52);
INSERT INTO reviews VALUES (36173, 1421290, 585, 'Great for people who enjoy playing Doomfist in Overwatch but wanna play an actually good game for a change :3\n', 'I''m hoping for a refund because I found out that they worked with Sweet Baby Inc.', 'Very Positive', 85.30, 58.45, 2.85);
INSERT INTO reviews VALUES (36175, 1422130, 792, 'Disclaimer: I''m a real life train driver, so my opinion might be different from that of a casual gamer.\nI for one, love this simulator. Rest assured, this is not a game, but a simulator. There are no "adventure" missions, no shooting, no score - you just drive a train. What sets this simulator apart from others, is that this is not all about eye candy.\nIt''s very good to look at, mind you, but where this sim shines, is in physics and systems managing. Driving a train here isn''t just about moving ', 'BEFORE YOU BUY PLEASE READ \n\nI wont talk about the singleplayer and other features blablabla whats good and etc, I bought this thinking its a promising game by a polish studio, where with the current rail system in Poland they have a lot of room to maneuver, but they ignored it. Limited scenarios including no other train traffic in offline game mode is a minus. MULTIPLAYER Frequent server restarts, server lagging (trains passing by like powerpoint show in windows) for almost the existence of the', 'Very Positive', 80.05, 200.85, 137.83);
INSERT INTO reviews VALUES (36176, 1422440, 1934, 'save scumming is a lore integrated gameplay mechanic\n\n10/10', 'Not a bad game, but nowhere near worth $30. I''d pay $10 at most. It seems like a really cool RTS/Tower Defense game, but there is ZERO depth. The progression is incredibly linear and there is no real strategy to utilize here. Each time you play it''s just "build tall base and stick archers on top then wait".  There is the occasional upgrade to use but they are very, very few and far between and linear themselves.', 'Very Positive', 90.64, 17.15, 12.02);
INSERT INTO reviews VALUES (36180, 1424330, 9791, 'One of my proudest achievements is sitting down with a real physical notebook and taking notes on the genetics of my winged dogs to figure out how to breed for them. After that I did enough experimenting and note-taking to determine the genetics of each wing type. I made a whole chart about it. It was the most fun I''ve ever had doing science and I felt so smart once my hypotheses were proven correct. The genetics are so complex and interesting, but everything is coated in a layer of silly fun th', 'i cried when my dog freakbob died', 'Overwhelmingly Positive', 98.50, 49.10, 10.55);
INSERT INTO reviews VALUES (36181, 1425000, 104, 'OK wow. I played the beta for this game back in October of 2023 when I found it during a search for new games to play. Boy oh boy I was not prepared for what this game had to offer. Since then I have been watching the development of this game and waiting for release, and seeing major improvements during the public playtest. The final release is smooth and bug free so far, and I think $10.00 is a bit much for the current state the game is in, however once some of the bugs are hammered out I think', 'The developer couldn''t bother writing a single sentence without spelling mistakes, massive grammatical mistakes and missing interpunction. If the developer can''t bother, why should I? \n\nOne of the characters advertised on the store page isn''t even in the game.', 'Very Positive', 89.42, 18.27, 0.32);
INSERT INTO reviews VALUES (36184, 1426010, 1247, 'An interesting game with a great asthetic, three playable characters and an engaging story.\r\nThe asthetic, especially in the later levels, reminds me of something HR Giger would dream up.\r\n\r\nI played this game for the story and the characters and as such used the guide basically all the time. Playing this way was great for me, without the manual I would have gotten very frustrated at some points. I can only recommend being at least aware of the Manual, which contains all the information you''ll e', 'Wonderful point and click that twitsts into new shapes the familliar bones and guts of Alien, Dead Space, the thing, event horizon. \n\nThe game is well written, each character are strong and likable.\n\nThis would be a strong recommendation, unfortunately, the presence of a LOT of AI-generated Art gets in the way. Every now and then, the game will have "lore element" scattered, little items that you can look at, and your eyes will glaze over them, because they were quite clearly  computer generated', 'Very Positive', 93.42, 7.93, 16.12);
INSERT INTO reviews VALUES (36185, 1426450, 4938, 'Took me about 280 hours to work up to ''Horrific'' difficulty. I''ve enjoyed this game a lot, having previously played ''They Are Billions!'' I wasn''t sure how I''d find the fantasy setting, but it works well.\r\nIf you''re looking for a game to come back to every now and then to burn some time, this is a good one.\r\n\r\nMy advice: PAUSE often, see what you can build, where you can expand to, and where resources might be at the edge of the fog of war. \r\nPlenty of my early runs ended in a wave because I spen', 'Game design has much potential and IMO superior to they are billions, but whoever did the technical side and Unit AI/pathing should never find work again. Your units will literally attack a stationary section of wall while being hit in melee by other units. Unit pathing was better in 90s games such as SC1 and C&C1 (and they had flaws). And every time the game loads, I wonder if my computer will crash.', 'Mostly Positive', 78.19, 390.02, 22.10);
INSERT INTO reviews VALUES (36186, 1427860, 391, 'Good story, nice nerdy and geeky references, LOTS of s3x scenes, easy to get into without online aids and the story flows very well with the girls as you learn who they are, what are their culture and kinks. girls of all sorts love u.. sort of.. and mini games can be skipped. art is great, i can''t help but ss a lot of them.. need more memories in the main menu. Easy to get back into if u have goldfish memory like me as they have a quest chart. I''m still not done meeting all the girls and i can''t', 'I just didn''t have the time to invest into playing this game.\nLook at some of the reviewers, with 50+ hours of playtime on this game.\nThe progression seemed way too slow for me. I wasn''t interested in playing 3 hours of content just to see a single sex scene.\nI gave up playing after 2.8 hours and uninstalled it.\nThe boredom literally made me tap out.', 'Very Positive', 92.33, 50.57, 3.73);
INSERT INTO reviews VALUES (36188, 1428310, 4912, 'My secret word is Fair. PS I''m crying. \nI highly recommend the Test Series. It''s interesting, it''s interactive, and the next test game seems to just get better and better in different ways. I am looking forward to what the secret words hold in the next game.', 'Well, I saw the reviews, and they overwhelmingly positive, and everybody were saying that this test is super legit and makes sense, and that their test result really speaks to them. \n\nWhat can I say about this test? It''s just a generic one, that you can find on the internet, a bunch of questions, like would you rather have this or that, what emotion do you feel or describe this picture. I anticipated a lot out of this game, based on reviews the test was suppose to tell me what kind of person I a', 'Overwhelmingly Positive', 98.07, 1.22, 2.13);
INSERT INTO reviews VALUES (36189, 1428420, 521, '9/10 - Bring back multiplayer one day so I can play with my work friends\n\nI discovered this game when Twitch streamer Tomato was playing it. The guy is brain rot funny. Anyways, I work in the nuclear field and this game gives me the opportunity to be an Operator for fun. Super detailed game with A LOT of potential. I want to surprise my co-workers with it the next time they visit. Enjoying my time so far learning and expanding my little nuke plant. Great job so far! Keep up the hard work!', 'Bought 2 copies for co-op with a buddy. That week the co-op mode was removed because it was "too unstable", and now it''s marketed as a single player only game.\n\nI understand that multiplayer is difficult, but I''m disappointed by how it was handled.', 'Mostly Positive', 78.89, 5.67, 8.95);
INSERT INTO reviews VALUES (36190, 1429880, 233, 'I have been looking forward to this game for forever now! I can finally live my best girly pop life in little London and put my fake British accent to use. \nI Love that the game has steam deck support and look forward to see what updates will come in the future!', 'I wish there was a "meh" button for steam... It''s not fun but it''s not boring. Just meh. I think I might''ve expected a lot more to it? The world doesn''t feel alive (nobody reacts that my character has been wearing her undies out in the city because her clothes are in the washer, no reaction to her being stinky, can''t talk to the NPCs walking around, etc etc...) and honestly the characters that are introduced are so unlikable... It also takes WAYY too long to do things. Why does drinking water ta', 'Very Positive', 80.26, 14.53, 3.40);
INSERT INTO reviews VALUES (36196, 1431850, 166, 'I rarely say this and repeat this but, I know you probably played a game where you said: "Man, I wish I could lost my memory so I can play it for the first time.". This is one of those games.\n\nMy best friend were staying with me for a week and we decided to play this. An hour or two later and we had papers laying around, brainstorming, taking turns of each puzzle when other was stuck. What an experience that was. Honestly this is no horror game, just your good old bloody spooky escape room. I ca', 'Unfortunately, I can''t recommend this.\n\nThe premise of the game is okay, but after less than 20 minutes, I got frustrated with the visuals.  There are options to disable them, but they don''t actually seem to work.  Even with the "wobble" disabled, there are still objects in the environment that wobble and even with the texture warping disabled, there are still objects that have warping textures.  There''s also an antialiasing options that would presumably disable the pixel filter, but it doesn''t ', 'Overwhelmingly Positive', 95.18, 5.10, 1.00);
INSERT INTO reviews VALUES (36197, 1432850, 331, 'I rarely write reviews for games. In many ways I feel unqualified to talk about a game experience, especially when there are so many professional game reviewers who critique the media for a living. That said, I couldn''t help but feel compelled to write some things about Farewell North. \r\n\r\nBefore release, I saw a preview for Farewell North and thought that sounds right up my alley. My partner and my beloved border collie passed away earlier in the year so playing one to experience the joy of her', 'Extremely slow cut scenes, way too many cut scenes, huge open spaces with nothing to find or do, no difficulty for the uh... "puzzles" that a toddler could solve.', 'Overwhelmingly Positive', 96.68, 9.70, 5.23);
INSERT INTO reviews VALUES (36198, 1433140, 10317, 'Very fun and entertaining game, there''s lots of things to do in a match and it''s not that repetitive. The graphics are really beautiful.\n\nThe only issue with this game is the balancing, the devs have a really hard time hearing the community on what''s best. Sometimes they take bad notes from one side and that''s really what kills the game. Also, the matchmaking is always taking really long.', 'an absolute joke of a company. killed a game from one of the most popular horror movie franchises in just 2 years and now they think "The Texas Chain Saw Massacre has reached its full potential" never buying another game from this embarrassment of a company who clearly doesn''t care for their players.', 'Mixed', 68.01, 376.15, 62.45);
INSERT INTO reviews VALUES (36202, 1435790, 8198, 'Really enjoyed playing through the game with a buddy.  A fun change of pace, and some really good puzzles.\n\nHowever ...\n\nTo play additional map packs such as those in the DLCs requires both my friend and I to buy them. That''s basically the same price as the core game just for an extra level, regardless of how long that takes (hint an hour).  If they''d done the EA thing where one person buys and can host for mates, then I''d have no qualms.', 'It used to work well with Linux, now I cannot play anymore. \nI bought this game because of its availability on Linux. It doesn''t make sense stopping service in the middle while you have user.', 'Overwhelmingly Positive', 95.62, 20.78, 2.97);
INSERT INTO reviews VALUES (36204, 1436700, 686, 'I would say, part 5 is the best Trine game so far. Besides the beautiful graphics and lots of content, it offers you a great balance between fun and difficulty (Life/Fight/Riddles - difficulty can be increased or decreased during campaign). This time the chars have even more mechanics, that allow you to solve the one or other riddle in several ways. But it could also overwhelm you at some point. Some of the mechanic combos between the chars are not explained, so you have to experiment to find th', 'I always loved Trine series, there is nothing like them and Trine 5 took a while to complete which is good. However, I am very dissapointed with the number of bugs in this one (not gameplay but with achievements). It is a coop game and for such a well established studio these issues weren''t properly tested. Tidbits, letters, hats disappear after each session because i was not the host. I had to return to old sessions and complete my achievements like that. Only "Collect all experience" achieveme', 'Very Positive', 91.55, 32.83, 29.02);
INSERT INTO reviews VALUES (36207, 1440670, 1253, 'Watched dapper, kan, and kosmonaut play this game for a while on youtube... hoped it would come to ps5... built a 5k gaming PC just for zeepkist and I don''t regret it one bit.', 'I loved this game for so long, but the update with the guilders is not vibing with me. The controls for flight are not very intuitive at all and now I am being forced to play it on every other map.', 'Overwhelmingly Positive', 97.85, 7.47, 105.20);
INSERT INTO reviews VALUES (36211, 1442430, 1152, 'Great game. The only complaint I''ve read people have is that you can''t lose money on these auctions, but I have news for you, unless it''s a televised auction, it is extremely difficult to lose money on something like this because real people are only looking for bargains. Everyone knows what is in the storage unit in advance. If you keep bidding, you''ll win pretty quickly. The unrealistic part is that you can''t know the approximate resale value of the items before you start bidding, but since th', 'I love simulation games but it seems like there is this new trend on steam where developers release a product with very little optimization and just copy paste features from other simulation games with some "new" features and try to sell it as a brand new and never before seen idea. The game is decent but I just can''t recommend these "asset flip" products that have no real optimization', 'Very Positive', 83.33, 21.02, 1.95);
INSERT INTO reviews VALUES (36213, 1442820, 277, 'I own this game on three different platforms lol so ive spent some money trying to support this game and this franchise because i love it so much. This is a very difficult game as all R-Type games are so if you are some one who doesnt like to loose then your going to have a very bad day. As this is a trial of tribulation and fire. Unlike many other side scrolling shooters that move fast. You will be playing a game that is more based on being patient, slower more methodical  and very precise move', 'I owned this game since it came out and haven''t played it for a while and saw the expansions on sale so I thought I''d buy them and fire it back up.  One major problem though.  This game is no longer playable offline, I just get  black screen when I start it.  I play offline 99% of the time which made my purchase worthless.  There is no indication anywhere that this is required.  I''ll change my review if this is fixed.', 'Mostly Positive', 76.90, 44.80, 0.83);
INSERT INTO reviews VALUES (36216, 1444480, 2253, 'Not being a big brain guy myself, rather drag my knuckles in counter-strike than ever try to use some other logical structure. This game requires big brain, but it sometimes makes you feel like it doesn''t, and gives you good use of small brain to muscle train your brain to be bigger, essentially building your small brain to evolve into big brain. Like bicep, but brain. Sometimes small brain gets very confused. But it is okay. Because I know just because small brain confused, it is training. This', 'I love this game. People with the same type of brain I was born with will love this game.\n\nHowever, there are two egregious issues that keep me from recommending this:\n\nThe first is that a lot of the instructions for levels are pretty difficult to understand exactly what it is the game wants you to do.\n\nThe second, and far more frustrating problem, is that there is no easy way to debug anything in your circuit as far as ticks are concerned. In the campaign, the only way to advance ticks is to ma', 'Overwhelmingly Positive', 95.21, 10.97, 4.22);
INSERT INTO reviews VALUES (36219, 1446850, 144, 'EZ to get all achievements 100%\nJust press  on each level', 'spam h for a couple minutes, uninstall, then rethink your life choices', 'Very Positive', 81.25, 2.77, 0.10);
INSERT INTO reviews VALUES (36224, 1448750, 190, 'Booty enjoyer? Always wanted to SLAP SLAP SLAP one?\n\nThen get this! A dirt cheap game with nice achievements!', 'I came', 'Very Positive', 92.11, 2.85, 2.97);
INSERT INTO reviews VALUES (36228, 1449200, 1666, 'I almost didn''t buy this game because of reviews saying that it has nothing to do with the first game...\r\nIt is a direct continuation from the first game, I recommended for anyone that enjoyed it', 'I really wanted this to be good but the story got a little.... wonky at the end. The first game was so good, how did they drop the ball on this one? Not even the mind break kind of wonky but just you sitting there in disbelief going "What just happened". In a bad way.', 'Very Positive', 87.03, 29.73, 39.75);
INSERT INTO reviews VALUES (36229, 1449630, 169, 'The screenshots do not do this game justice. They make it looks like a child''s plaything. This game has a fantastic mix of depth of mechanics and ease of controls. Really worth trying out if you are on the fence. Don''t let the arcade looking screenshots scare you.', 'Tedious. Combat situation are repetitive, just different locations in the Pacific during the war patrols. Once you learn to fire your torpedoes at long range and run there''s no challenge.', 'Very Positive', 94.08, 15.70, 405.57);
INSERT INTO reviews VALUES (36234, 1450900, 777, 'This game is absolutely amazing. While not for everyone, I think you need some positive experience from more advanced games like Factorio, Satisfactory, Techtonica before going onto Desynced. Even if it looks complicated and different at first glance, it is not (except instead of belts, you got bots and drones). I have about 80 hours in this early access and still learning, while having fun.\r\n\r\nDont worry, bot programming is not needed at all. And programming in this game is more like programmin', 'The thing that attracted me to this game is the programming aspect of it, which I discovered is kinda pointless, sadly.\nThe units have built-in functionality that already allows them to do everything that is needed from them if they have the correct modules, so there''s no ''need'' to program their behaviour. But, if you did choose to program them anyway (because programming is awesome and I should be able to improve unit efficiency), then there is no way to disable their default behaviour so that ', 'Very Positive', 84.94, 154.85, 25.32);
INSERT INTO reviews VALUES (36235, 1451120, 133, 'This experience was worth every penny.', 'Couldn''t bear myself to complete it. Would have been worked 10 times better as an audiobook, since the gameplay is so slow and repetitive, it''s just- it just NO. Watch it on youtube, I bet it works wonders as ASMR.', 'Very Positive', 82.71, 0.63, 0.43);
INSERT INTO reviews VALUES (36236, 1451190, 12281, 'add Training Games, Give us the opportunity to change weight classes, Press conferences Would be a plus We need instant replay and new venues. It would be nice to have the ability to spend our cash on personal items such as Mansions Cars Clothes,  Give a Centralized GYM Where multiple champions you create train or Allow us to have trainer mode Where WE can act as a trainer for multiple fighters at different weight classes at the same time. Juggling fights schedules from that perspective would be', 'Expecting people who supported the game throughout early access to pay extra for content that was advertised in the beginning is genuinely scummy and greedy behaviour. Game had potential, but it is miles away from feeling like a polished game. The career mode was exceptionally low effort, not worth the wait', 'Mixed', 62.18, 370.75, 139.75);
INSERT INTO reviews VALUES (36241, 1452250, 203, 'To the devs: Do not give up on this game. I''ve seen it too many times where devs allow the critics to get in their head and discourage them. That trend needs to end. This game has a good concept and I support it. I''ve played games this year with more of a budget and it doesn''t even come close to this game. Now on the other side, this game has bugs that need to be fixed ASAP. I think once when the bugs are fixed, character customization is added, racing, maybe mods, and a bigger map... I think th', 'If you don''t know much about cars, you will maybe enjoy this game.\n\nThe game is wildly unrealistic for a Garage / Mechanic game. The issues however are hard baked into the game and won''t be fixed or patched. \nMuscle cars / all cars are all wheel drive. \nJapanese cars (R34 Skyline) have V8''s. \nThe driving dynamics are VERY bad.', 'Mostly Positive', 73.89, 5.52, 1.58);
INSERT INTO reviews VALUES (36245, 1455840, 14669, 'If you''re like me and think rotating and placing hexagons is peak gameplay, then this game is for you', 'Stressful for a "relaxing" game; you have to reach all sorts of achievements to gain more tiles and such, and that was just not what I want from a game that advertised its relaxing aspects to me.\nCan''t use more cortisol in my life.', 'Overwhelmingly Positive', 96.57, 11.47, 3.03);
INSERT INTO reviews VALUES (36248, 1456760, 784, 'This game is an absolute gem, combining rythm based shooting to a style based frame work akin to Ultrakill.\nAnd with the addition to add your OWN music makes this almost infinitely replayable (if different music is enough to keep you coming back). \nWhile I do have some gripes with how not all weapons have as many options as some others to style with (heck the Revolver gets a unique 360 multiplier that makes it even better for getting points) I would still recommend this game in a heartbeat', 'Has huge potential but just like Metal Hellsiger, this game suffers from most of the game not being rythmic, aside from shooting you don''t have to care about rythm (enemies are not rythmic as well), jumping dashing  etc you don''t have to care about these actions being rythmic since they aren''t really beneficial and there is no rythm for parrying or reloading which makes the game feel like any other shoot em up.\n\nOne major issue is that feedback in general really sucks, being on the rythm with yo', 'Very Positive', 94.90, 24.13, 0.65);
INSERT INTO reviews VALUES (36250, 1458140, 11394, 'Amazing game!!! Also, here’s a tip: The game autosaves when you enter a new zone, so you don’t have to finish the whole run in one go. You can leave when you get to a new zone and then resume from where you left off.', 'If this game had a "save anytime" system I''d still be playing it instead of deleting it. Why do developers think gamers want to repeat the same exact thing over-and-over again? You can''t just leisurely play this game for 20 minutes. You MUST dedicate your time, maybe 2 hours, to completing a mission once you start it or be severely punished for quitting. Without this horrific save game system I''d recommend it. With the current save game system it feels like a punishment. I just wish I didn''t was', 'Very Positive', 83.24, 28.47, 19.30);
INSERT INTO reviews VALUES (36251, 1459010, 181, 'Thoroughly okay\n\nSo, this is a game in the vein of Megaman and some elements from Kirby. The controls are a bit floaty, the enemies are a bit spongy, but it''s all in the acceptable range. After each mission, you''ll receive a quest item and there''s somewhere an NPC on the map you have to tediously find and give it to them for a small actual reward.\nSpeaking of NPCs, clearly most of the love went into designing NPCs. Enemies are mostly a handful of types with colorswaps, but NPCs with nice Pixel A', 'They put "pronouns" in the game, then tried to start a brigade on reddit about 2 negative reviews that mentioned it. Watch out putting these kinds of people''s software on your PC.\n\nhttps://www.reddit.com/r/Games/comments/1eyp53g/pronouns_can_devastate_small_indie_games_in/', 'Very Positive', 90.61, 25.05, 0.25);
INSERT INTO reviews VALUES (36258, 1461030, 131, 'Eh... I''m a bit on the fence for this one. I always say that games must be judged for what they are compared to what was their original aim, and... as a dinosaur hunting game, this is undoubtedly lackluster. I can understand the negative reviews. The main problem here is the lack of content considering the asking price. Few dinosaurs, few maps, and few weapons. But the worst thing is, the base game does not bring justice to its own name, since there are just 2 carnivores over a total of 6 specie', 'I loved the original Carnivores game back in the 90''s, but this game is not it...\nThe developer removed almost all of the weapons from the original game.\nIf i remember, there is like 4 maybe 5 weapons now. No crossbow, no pistol. Getting to the point of unlocking the T-Rex to see how that hunt has changed is super tedious. In order for you to claim your "trophy", you have to approach the dead dino to mark it for transport. This was not the case in the original.\n\nThis game is the embodiment of wh', 'Mixed', 58.02, 17.18, 0.92);
INSERT INTO reviews VALUES (36259, 1461910, 255, 'What a wonderful little RTS! I''d imagine if someone wanted to make Slay The Spire an RTS game, this would probably be the closest realization to that. Minus the aesthetics are very different of course. Let''s get into how the "Rogue-Like" plays out.\n\nYou play a 10 round "Run" of random battles with randomized perks and unit pulls with three starting units in your initial unit pool. Your build unit, a resource gatherer, and a specialized unit that will shore up the backbone of your unit pulls. The', 'The game isn''t hard, but it is unfair. Imagine playing an RTS match, but you''re at the beginning of the match building everything up, but your opponent already has an established army, economy, and base. The ai is quite dumb, but that doesn''t make it feel any less unfair', 'Very Positive', 92.55, 18.40, 4.08);
INSERT INTO reviews VALUES (36261, 1462570, 2303, 'A criminally underrated platformer, a very unique and interesting story combine with some fun gameplay elements to create something magical. Definitely check this one out, especially with the announcement of the sequel.', 'The game is nice for the price, even if the pacing is very slow and the combat sections do get repetitive after a while, but the story and beautiful characters compensate it. \n\nThe main issue with this game is actually the EA app which is absolute cancer. It works half the times and installs a bunch of useless garbage on your PC, it even lost my saves after the update from EA Orgin.\n\nI just want the game, not your proprietary, useless, telemetry collecting, garbage app EA.\nDouble launchers shoul', 'Very Positive', 89.75, 13.77, 1.27);
INSERT INTO reviews VALUES (36262, 1462810, 590, 'One of my favorite rally games ever, what a banger. I know rallying is supposed to be intense and difficult - and this game sometimes offers that - but I play on the lowest difficulty possible so my only opponent is myself (the hardest to beat honestly), and it''s really soothing that way. 10/10\r\n\r\nonly complaint is that one stage in Kenya where the co-driver says water splash but it doesn''t happen for another like, 7 pace notes, and when it does happen there isn''t a pace note about it. LITERALLY', 'I''ve been playing racing games and racing sims for decades and I was a huge fan of the WRC series.  This edition of WRC is ok if you''re someone who wants to manage the entire racing team.  That''s not me.  I want to race.  A part of this game is like a racing team manager sim where you have to manage the team to make sure everyone feels good, has plenty of rest and gets along.  And it''s not optional.  It''s a requirement.  There are racing team manager sims out there and if that''s want I wanted to', 'Mostly Positive', 75.25, 61.27, 0.42);
INSERT INTO reviews VALUES (36265, 1465360, 14976, 'Playing SnowRunner is a lot like making love. You''ve got to take things slow and realize that the shortest route isn''t always the best route... Unfortunately, I always take the shortest route and end up dumping my load within the first three minutes.', 'Game not bad, but DLC''s for vehicles should be free or at least they should be included into season DLC''s.\nCurrently game with all DLC''s is 205 euros, feels like supporting money sucking scammers', 'Very Positive', 88.96, 88.52, 304.08);
INSERT INTO reviews VALUES (36266, 1465460, 5348, 'Perfect training. Now i know there is a bunch of government buildings in my hometown that contain guns where i thought was just a normal house or buisness.. oops maybe i wasn''t supposed to know this information.', 'Game is good in the beggining but in the long run it becomes completely unplayable, im playing on normal, it took me like 2 hours real time to build those high tier walls which get shattered into pieces by 2 hordes of zombies in couple seconds, when I station my men in a building in my colony they run out of ammo in couple seconds while not even defeating a single horde, guard towers and gates seem to do practically nothing all I could see them do is hold longer than the wall which is quite funn', 'Very Positive', 84.33, 59.40, 18.58);
INSERT INTO reviews VALUES (36267, 1465470, 1201, 'I got to tell you, I am 71 and playing on steam for over 20 years. Have played Satisfactory {which I like} but am very impressed playing this new game. My hat off with the Dev''s quick responses and constant updates and fixes sometimes 3 times a day. This is how you open a new game. When NMS started it had many problems in 2016 but came back hard and fast to make it right to its players {unlike Star Citizen which is constantly disrespecting its player and still not ready after 12 years}. Congradu', 'I think this has a lot of promise, but there''s simply too many incredibly frustrating problems with the programming. The whole basis for the game is resource management and automation, but the game consistently fails to recognize priorities, and items on the ground. Conveyor belts don''t function properly in that if you upgrade one, but split with two lesser belts, it doesn''t split the difference but slows everything down. Power management is nonsensical so you have constant power failure notific', 'Mostly Positive', 73.44, 374.98, 17.85);
INSERT INTO reviews VALUES (36269, 1466060, 8246, 'This game is proof that we DO NOT need photo realistic graphics. We need better art styles. The artists of this game should be some of the highest paid in the industry and I know they''re not.', ' I''v never written a game review before now, but I just had to for this game.. Because it seem''s to me, judging by other knee jerk reaction reviews I see which have only 3-15 hours of playtime, that many people suspect that the rest of the game is just as great after those first dozen or so hours. Spoilers, you''re wrong. ACT 1, whether it was intended to be or not, is a bait and switch. \n\n The quality falls of a hill once you head into ACT 2, and while ACT 2 does by in large maintain a good port', 'Very Positive', 87.65, 76.58, 61.12);
INSERT INTO reviews VALUES (36272, 1466390, 293, 'I never lost hope. The pixel art is way better, the music — once again composed by Daniel Kobylarz — is still absolutely wonderful. There’s a ton of reading, a lot of clicking, and a huge cast of characters and locations to explore. It’s a sequel that every fan of the original Kathy Rain should definitely try!\n\nI’m having an amazing time so far — Kathy Rain is back, baby!', 'finished the game in about 7h.\n\nPlus: pixel graphics, gameplay, decent puzzles maybe too easy sometimes, voice acting for main characters.\n\nMinus: same problem as the first one: the story after passing 70% becomes absolute rubbish, re-furbished things from the first game with this second one. And the ending speech is an absolute diarrhea of pretentious useless words. Not a spoiler but the ending is 100% same as the first one. Why??', 'Overwhelmingly Positive', 96.93, 12.27, 7.55);
INSERT INTO reviews VALUES (36282, 1471410, 1728, 'Ignore all the negative reviews saying that the game is abandonware. The devs posted a beta build of their latest update like, a week ago.\r\nSo far I''m having a lot of fun. I''ve had plenty of experience with the first game, and I can safely say that I''m enjoying it just as much.', 'Communicating exclusively through Discord when you haven''t put out an update in over a year kinda sucks, my man.', 'Very Positive', 83.16, 56.13, 5.03);
INSERT INTO reviews VALUES (36285, 1473060, 310, 'This game has a fun gameplay loop if you’re into roguelites/ARPG’s/top down games/loot! I clocked 47 hours on the demo on my PC. I’ve been playing the release on steam deck so far and the only feedback I have right now is it would be nice to have GUI scaling in order to see text better. It’s readable, but it would be more comfortable with scaled up text. However, it is still very playable on the deck.', 'Nothing says fun like being forced to reset your progress multiple times in order to access the next tier of empowerment. There''s an overabundance of half-baked game systems and the central mechanic itself is nowhere near as deep as advertised: rewriting doesn''t meaningfully alter your playstyle, the weapons, or build strategy. On my sixth go-around I finally decided that, no, I don''t want to replay the threadbare campaign yet again just to eke out another incremental power bump. \n\nThere are far', 'Very Positive', 86.13, 46.60, 31.67);
INSERT INTO reviews VALUES (36290, 1475810, 4732, 'It''s a fun enough game. Worth it at a discount.\nThe map is fun to explore and there''s a ton to see.\nThe combat is fun albeit repetitive after a while.\nThe colect-a-thon of items, graffitis, etc. gets stale a bit too fast imo but it''s totally skippable.', 'Before the DLC I 100% this game and loved it. After DLC it has become a complete mess that cant be played on even high end pc''s. Im sad I dont get to keep my 100% because I cant go back and play it due to the changes. I cant even pause the game anymore. ( I got it to work once) and I checked the graphic settings and it was set to low all across the board and it was still dropping from 60fps to 30fps in or out of combat. mainly if I move it drops. this never happened when I played it before the d', 'Very Positive', 84.19, 66.17, 45.13);
INSERT INTO reviews VALUES (36295, 1477590, 394, 'doesn''t have side track notes', 'was enjoying the game a lot.... until servers just went down. why can i not play a single player game without internet? awful just awful', 'Very Positive', 87.31, 43.12, 3.87);
INSERT INTO reviews VALUES (36297, 1479140, 480, 'this is just america if axolotls were native to it instead of mexico.', 'From the people who''ve played enter the gungeon, and nuclear throne: comes the most underwhelming twin-stick roguelite with enough of a competent look to seem like it''s worth your time.\n\nVery repetitive, and generally lacking. The run-to-run gameplay is incredibly same-y, the memes are a weird and forced addition, and the whole "cute and cuddly seeming thing is actually violent/evil/suuuper badass'' shtick is tired.\n\nSkip this.', 'Mostly Positive', 73.12, 15.23, 1.80);
INSERT INTO reviews VALUES (36298, 1479730, 331, 'It''s Commandos, except it''s 2025. If you don''t understand why that''s exciting, you missed out then, don''t miss out now.', 'feels cheap. too many bugs. way behind MImimi in terms of function, features and graphics.  Way overpriced for what its worth.', 'Mostly Positive', 74.62, 5.52, 58.35);
INSERT INTO reviews VALUES (36301, 1480560, 1547, 'Started playing this game in my first couple weeks of university and something incredible happened. My grades went through the roof and all my wishes came true. This game is magical!', 'This game is abandoned for a long time already. No new maps, machines or update for over 2 years already. Don''t waste your money on this game as it is abandoned.', 'Mostly Positive', 75.11, 4.87, 170.77);
INSERT INTO reviews VALUES (36302, 1481170, 812, 'Really good 4x game with a huge focus in combat. If you played Gladius, it''s basically the same system with original factions that, dare I say, are cooler than the 40k ones, including leaders that are oozing with originality and personality. To those old enough, it almst reminds me of Sid Meyer''s Alpha Centauri leaders.\n\nAs cons, I''d prefer a bit more space to breath (this is like Gladius in that too, no turn will pass without combat) and unique units for each leader would be really cool. But ev', 'It definitely feels like Gladius, but unfortunately there''s extra baggage that doesn''t quite work well. There are several other new resources like Algae and Chips for example, both of which are used primarily as upkeep resources for Voice and Cyber units, respectively. These new resources are not faction dependent and anyone is able to acquire these resources, unlike Gladius where several factions had unique play styles based on specific resources or a lack thereof, leading to variety and replay', 'Very Positive', 87.32, 44.17, 19.07);
INSERT INTO reviews VALUES (36304, 1481440, 184, 'You can create your own Missions in the Editor. People who downrate this game probably never even bothered to try that. If youre creative, this game offers endless replayability.\nI put over 1000h into this game, be careful not to get obsessed. :D Devs are super responsive, Community is great, updates feel refreshing and the editor is a great way to feed your OCD. You should also join the official Discord! \n\nThank you guys for creating such a beautiful game!', 'Can no longer recommend, as the devs intend to add a cash shop with the next update. Too bad, it was a good game until they pulled that.', 'Very Positive', 82.61, 2.25, 10.83);
INSERT INTO reviews VALUES (36305, 1481780, 238, 'Karate chop!! This game makes me want to karate chop my children in the neck. Truly a life changing game.', 'theres not enough to the game to make it worth $30 if it was worth $10 this game would be alot easier to enjoy there isnt $30  worth of content in this game', 'Overwhelmingly Positive', 96.22, 4.77, 0.77);
INSERT INTO reviews VALUES (36309, 1482700, 107, 'Big veiny Dihh', 'There are only sprints in the pc version. On the mobile one there is a lot more versatility on the pc version. I paid £2 for this rubbish expecting it to be as good as the mobile one. Heck you can play a better version for free on poki. Don''t buy this!', 'Mostly Positive', 78.50, 12.00, 1.25);
INSERT INTO reviews VALUES (36311, 1483870, 311, 'I totally crashed a game of Chinese players (there were no English lobbies!) and they were nice enough to wait until the game was over before they kicked me. How sweet!', 'Wouldn''t recommend it. Unfortunately, from what I''ve found anyway, absolutely no one plays this game. There are zero public lobbies. Which mean''s, unless you have friends to play with, you can''t do anything with it.', 'Mostly Positive', 75.56, 1.50, 0.10);
INSERT INTO reviews VALUES (36314, 1484280, 1064, 'Fun D&D Turn based 3D board game style good on VR and PC without VR. Some salty players want you to play their way.  You get lots of you "should have done this" "should have done that" small brain opinions from the PuG''s. ...but a good strategic mind reads the game and makes moves that set you up for the win. They''re playing checkers while the smart guys carrying them are playing chess! Mute is fantastic!', 'Update is absolute trash, roll it back ASAP. Game went from one of the best out to bugs that make the game absolutely irritating. Lost turns for no reason, bosses performing more actions than they have action points for, dice bugging into the walls and changing rolls, and heroes not placing in the square you have highlighted just to name a few of the really annoying ones. The "improvements" are nowhere to be seen, literally everything that was supposedly fixed or improved is in a worse state. Up', 'Very Positive', 88.44, 46.33, 53.87);
INSERT INTO reviews VALUES (36316, 1485590, 2019, 'Careful listening to the bad reviews here. A lot of them are due to the fact they wanted this to be a sequel to Dungeon of the Endless and it is not. It is its own game and it does it very solid. It leans a little farther into action game than tower defense, but I felt the progression and gameplay was great.', 'They ditched all of its graphical grit, and critical thinking charm with depth for the same Fortnite graphics every company since Fortnite has tried to replicate, and turned a cool in depth strategic game into essentially Gears or War 2 Horde mode, or a somehow less engaging Naz* Zombies from CoD. Everything is so bright and glittery, reminds me of Diablo1/2 vs 3\n\nThis game took what the first game was good for, ripped out the vital organs and slapped a generic WASD top down shooter. Dungeon of ', 'Mixed', 64.19, 47.55, 10.57);
INSERT INTO reviews VALUES (36321, 1486920, 3302, 'So far I can say this is what I wanted for a long time. Good campaign/skirmish game. It does feel like "old" new Red alert game from Westwood. Thank you for making this.', 'Read the eula linked on the steam store page, especially section 13.5, and notice the additional eula at 13.6.\n\nI didn''t and played for a bit. the game itself seems fun, but now I''m worried and might refund.\nThey talk about transmitting RAM dumps while the game is running, as well as a bunch of user and system information, for "For the purpose of detection system improvement and elimination of malfunctions and errors in the Game, as well as detecting the use of third-party software resources tha', 'Very Positive', 89.61, 9.52, 1.72);
INSERT INTO reviews VALUES (36323, 1488560, 713, 'Just plain ass, normal, every day, no question about it, no NFL, no year. Not named after a player. not named after a coach, not named after the referees pet gold fish. No quarterback, steinback, dime back, nickleback. Simple ordinary, unembelished, unmistakable, crystal clear, as frank as Frankenstien, as blunt as a atom BOMB. One compound word; It''s mother fuckin goddaamn'' sonsabitchin'' fuck fuck FUCKIN'' FOOTBALL!!!!!', 'I''ve never seen a good game suddenly nosedive so fast. A big part of the reason why I bought this game was the physics and hard hitting tackles, and the game had that when I bought it. In the latest updates, somehow the physics feels LOW impact and very glidy, tackles aren''t crisp or hard hitting anymore. We finally had a new Backbreaker-level high impact football game... and then they wrecked it and ruined the tackle system.', 'Mostly Positive', 79.38, 2.42, 55.47);
INSERT INTO reviews VALUES (36324, 1489630, 2324, 'The devs are sitting on a gold mine of a game but seem to have turned a blind eye to it. I don''t know if the game said something to hurt someones feeling but they really need to put whatever they have behind them and actually develop and update the game cause its one of a kind and actually an amazing concept that seems to have been dropped from the face of the earth.', 'Good concept, way to expensive for the content it has. Curretnly only good for PVP with friend has the AI is very dumb but blessed by unlimited everything and x2 speed on everything. forcing you to cheese the AI with strategy that you have to find online to win.', 'Very Positive', 81.02, 30.97, 49.60);
INSERT INTO reviews VALUES (36329, 1491000, 343, 'This game is awesome! Lots of fun with the mech parts and weapons, feels like what hawken could have been! 10/10', 'Don''t buy this.  No one is playing and you''re forced to fight bots.  As such, the bots power level quickly exceeds your ability to gain enough resources to upgrade your hangar and devolves into a very frustrating experience.', 'Mostly Positive', 77.84, 177.38, 5.35);
INSERT INTO reviews VALUES (36330, 1491410, 675, 'If you''re an old BioWare fan, this is what you''ve been looking for. \r\n\r\nA charming, brightly colored RPG that combines my favorites from BioWare (storytelling, companion/NPC growth, romance) with a Shadow of Colossus style combat with some magic weaving thrown in. Add some really interesting world-dynamics (temperature, day/night, etc) and I think this is legitimately a fantastic game. I''ll be recommending it to everyone I know, and really hope that this title helps solidify the studio''s future.', 'Got about 20 minutes into the game and it started with the weird gender pronoun nonsense with one of the main characters referring to himself as they/themselves.  No interest in modern day silliness.. refunded', 'Very Positive', 88.59, 44.20, 0.78);
INSERT INTO reviews VALUES (36333, 1492070, 3794, 'Want to play COD Zombies but tired of the same old things over and over? THIS GAME IS FOR YOU. Enemy movement is closer to the like of Killing Floor 2 but in a good way. Well balanced maps, weapons, enemies, bosses too! Objectives to achieve during round based zombies game play. Buy back options for teammates you couldn''t get to before they bleed out. Smooth game play without lag, stutters, or glitching. Easily better play ability than any COD Zombies to date. Weapon upgrades (pack-a-punch), per', 'A very tentative no: \r\nPicked it up for some zombies with the boys knowing itd be backed by a good group of devs and with a solid future road map. Unfortunately multiplayer consistently kicked us out of the 5 games we tried, between that and a bug that blocks blocks from walking through purchased doors, we found the experience lacking. \r\n\r\nMy biggest ask would be multiplayer stability, I wont refund at this point, Ill check back in a few months and hope this is addressed by the dev team.', 'Very Positive', 85.32, 7.25, 12.95);
INSERT INTO reviews VALUES (36338, 1494560, 237, 'Easily one of the most unique games I''ve played in years. I think calling it a "deckbuilder" isn''t quite right, as I think that implies a random hand draw and the general strategy of managing deck size. The flexibility the game provides is so refreshing and satisfying, and the design allows for some beautifully broken combinations. \n\nI think the puzzle can, at times, become unwieldy.  There have been runs where one of my characters had such a complicated setup that I had to completely rewire it,', 'I really should love this game, but it''s just too frustrating. Even on beginner it seems impossible to get a useful chain going before characters start getting knocked out. I suspect that if I slog through a few more runs to unlock a few more things then it might be possible to get to the "fun", but that''s not a good design.', 'Overwhelmingly Positive', 96.62, 6.30, 2.67);
INSERT INTO reviews VALUES (36339, 1494810, 2984, 'Game of all time, play it if you like waving big sword. There''s other classes, but I don''t know about the other classes because I was busy  swinging my big sword to pay attention. This game and I are soulmates', 'cool game. i love combat system. it has depth, but lacking a little variety how you use certain classes. but i hate instakill water, abyss, whatever that thing is. it''s a bad design decision. it''s not cool to die just because you did little mistake in movement. i don''t mind this on special platforming levels, but on regular, instakill is a bad thing and it is not fun at all', 'Overwhelmingly Positive', 96.11, 19.53, 14.35);
INSERT INTO reviews VALUES (36340, 1494840, 735, 'ts so frickin tuff like its so frickin tuff play it ficken tuff boii', 'ragebait temu version of skate 3', 'Very Positive', 90.07, 5.02, 0.52);
INSERT INTO reviews VALUES (36341, 1496250, 117, 'I recommend playing Nightmares first if you don''t put much weight on the story and MS2 first if you value story a lot. MS2 has some random gameplay changes that are in some cases worse than Nightmares.\n\nMost of the crashing has been fixed, barring a couple fringe cases. \nIf you want the purge minigame, add an empty minigame.dat file to the game directory.\nThe Nightmares remake is included and unlocked at the completion of Mary Skelter 2, or there''s a way to unlock it early.\n\nSidenote: Some of th', 'I like the game, I really do, even though I''m no longer a man of culture, I can enjoy a good dungeon romp, but no matter how good a game is, the amount of crashes, including a freakin bsod, in a game like this  where you can lose hours if your forget to save? \nI cant be positive about a game in such a state and even more so for the price, given how dated the game looks. \nI dont have as much time to play vidya as I used to and losing 2 hours of progress is a game killer for me.\n\nSucks, I bought t', 'Mostly Positive', 76.07, 152.77, 4.70);
INSERT INTO reviews VALUES (36348, 1498130, 165, 'This game is being made by only 4 Devs and being self published by them as the one who was publishing it before dropped the game. The devs said hold my beer and have released it, this are very open in their discord about everything. \n\nIs it buggy - Yes\nIs it Fun - Hell yes\nAre the devs actively working to improve the gameplay and fix the issues - Yes\n\nBut hating on the game instead of giving feedback/telling devs about issues and bugs isn''t the way to go. Go join their discord, they''re very open', 'I had looked forward to this. I didn''t like the Demo, but hoped It would get better, sadly it didn''t\nIt is not the Steel Fury Kharkov sucessor that I hoped. It is arcady, even in simulator mode. But still clunky with unintuitive controls. (Like why cant I change the ammo type as a commander?)\nAlso there is no tutorial. Just a shooting range and the Campaign. No explanation on how to spawn more than one Tank, no introduction on the infantery.\nThe viewing ports of the Tiger don''t work, (they freez', 'Mostly Positive', 75.76, 9.07, 0.62);
INSERT INTO reviews VALUES (36352, 1500180, 108, 'Looks and sounds gorgeous, and plays super smooth. Just coming up with different combos for the enemies is already lots of fun, but then the level design is also really tight!\nIt''s made with love and that shows. Definitely recommend.', 'First off i would like to say that there is a lot of polishing this game needs. the lack of sound effect from the menus, character, enemies, and environments can make this game feel empty at times. the music, while i understand what its trying to go for, doesn''t end up being very appealing either. some of the art aspects are fine, but other times i can clearly see when it cuts corners. Combat and movement doesn''t end up feeling very good either. the game tries to go for a platform fighter aspect', 'Overwhelmingly Positive', 95.37, 1.45, 1.57);
INSERT INTO reviews VALUES (36356, 1501610, 1021, 'I have never posted a review of a game before, even for those I loved or hated, but for this game it seemed absolutely necessary. \nThis game is ridiculously fun and I am completely blown away by the wonderful QOL choices the developer has made. I''m a huge fan of resource management and automation type games. I loved Forager and Don''t Starve and I get vibes of both in this game. But a lot of games in these genres have mechanics that can feel grindy or cumbersome, and Nova Lands seems to have a re', 'Great game, it''s like forager but the developers aren''t a group of uncredited volunteers and then published under the name of 1 person and sold as a solo developer game, it''s more focused on automation, Good playtime so far, I''m still not quite done with all of the content 15 hours in, I have mostly enjoyed my time.... Or at least that''s what I wrote before finding out this game has data mining enabled by default and you have to go to a sketchy website to opt out (Which is potentially against EU', 'Very Positive', 90.50, 44.62, 15.03);
INSERT INTO reviews VALUES (36357, 1501750, 16594, 'Amazing how the people behind this game listen to the community!\n\nI already enjoyed the game when it launched, even though it was obviously flawed in some regards. Over the last 2 years the game received numerous updates, and today I got recommended a video about update 2.0 launching, and it literally fixed EVERY SINGLE FLAW the game had. And even though I already own the game I really respect the game being on a 67% discount for 2 weeks right after the update drops, instead of making people pay', 'Seamless co-op doesn''t work on a fundamental level. \nConstant lag when in session, the world states doesn''t get sync and overall systems just flat out doesn''t works. \n\nMight work at a later date, but if you wanna buy the game for seamless co-op, just don''t.', 'Mostly Positive', 73.04, 28.40, 30.27);
INSERT INTO reviews VALUES (36368, 1506830, 33497, 'Fifa 22 is better than FC24 and FC25', 'Amazing. Four years in and the servers are already dead. EA’s been busy squeezing wallets dry with card packs, and now they’ve unplugged the whole thing like it’s a broken toaster. Bravo. I just wanted to play this mess once every few months, not ask for a miracle. FIFA’s been sliding downhill faster than a Sunday league defender, but pulling the servers this quick? That’s next-level clownery. Time to find a game that doesn''t treat its players like walking ATMs :V', 'Very Positive', 80.83, 82.07, 39.83);
INSERT INTO reviews VALUES (36369, 1507580, 183, 'I would absolutely love if it was possible to mismatch the voice and text language. I really want to play it listening to the original portuguese dub.', 'Refund this crap game because i pressed the begin button and it made me do a musical puzzle in the main menu that bored me.\nNext time if you want people to play your game don''t be jerks who pretend they are making art.\nMAKE A GAME, stop being pretentious little wannabe artists.\nImagine a developer wasting your time in the main menu with a musical puzzle and not leting you start the game, making you belive it''s loading or bugged\nRefunded and Reported, when someone comes home from a long day at wo', 'Very Positive', 92.35, 52.40, 0.13);
INSERT INTO reviews VALUES (36373, 1508680, 212, 'I though it''s simple NSFW game, but now I need at the end of the game more my RTS skills, than F with girls, now I f my enemies, not waifus. Awesome chinese type rts, like you need prepare your troops to big battles. Prepare full your brain at 8 level !', '。', 'Very Positive', 91.04, 7.58, 4.40);
INSERT INTO reviews VALUES (36379, 1510580, 105, 'A pretty nice game. It gets sadly a bit tedious, especially when you consider that the achievement counter resets after avery achievement from the category. The variety of toys could be greater and the actions mor specific. still pretty nice. I would recommend it buying on sale. I can still recommend it.', 'I do not play alot of builder sims, but this one is the least engaging of the ones I tried.  There looks like a lot of content is eventually available, but the grind to get there was just more than I was willing to invest.  3/10', 'Mixed', 56.19, 26.25, 3.70);
INSERT INTO reviews VALUES (36380, 1511630, 565, 'Game has lots of potential, doesn''t feel too polished though. pretty good overall. i refunded to afford another geek bar.', 'very clunky gameplay, the physics feels like a boat. think of mxgp. super slow and clunky. the getting off the bike when you crash thing is super annoying because it takes WAY too long for you to start walking. and the animation is so silly. why do i have to wait until my rider stands perfectly still to go after my bike? and the first person mode for the standing is awful. why does the camera depend on my movement with the left stick? who thought that was a good idea? and then when you get back ', 'Very Positive', 84.25, 3.80, 23.25);
INSERT INTO reviews VALUES (36384, 1515640, 174, 'I don''t know how this game has gone unnoticed, but it is genuinely fun, and definitely worth buying.', 'It was a game with potential however the developer abandoned it years back and hasn''t come out with anything new. Now they''re making it F2P without offering any bonus or compensation to everyone who bought the gaming thinking it won''t be abandoned. \n\nit''s probably okay to play as f2p for awhile but you will quickly get bored by the 4 available biomes and lack of variety in procedural generation.', 'Mostly Positive', 77.01, 4.33, 47.93);
INSERT INTO reviews VALUES (36387, 1517290, 97298, 'This is my chillax game. No big punishments for dying (but revives and team play are encouraged). Guns are nice. Progression is not great, but it is there (most of good cosmetics are hidden behind MTX, which is poop). Game''s performance is good.\n\nThe only big bug that I have encountered is bad UI resolution scaling (it is in 2K while my display is 4K)\n\nGet it on sale and remember to have fun. THIS GAME HAS NO TRADITIONAL SINGLE-PLAYER, ONLY SOLO/COOP MODES!', 'For anybody looking to purchase this game in 2024, keep in mind that this game will no longer receive any more major content updates as the devs have started to focus on the next battlefield game.  The playerbase is also still very active unless you''re trying to play one of the "dead" gamemodes.  That being said, it''s still a pretty good game (much better than what it launched as), but I do not think that this game is worth it at full price.', 'Mixed', 47.06, 22.58, 268.43);
INSERT INTO reviews VALUES (36389, 1517970, 838, 'If you thought path of pain in Hollow Knight and the B/C sides in Celeste was fun rather than frustrating then you''ll probably like this game. If not, skip out on this one', 'There are two main reasons I cannot recommend Aeterna Noctis:\r\n\r\nFirstly this game should not have been structured like a metroidvania. Even on the easy mode the platforming is crazy punishing (fun), but it''s very difficult to design crazy punishing platforming sections that can be traversed both directions, and because this is supposed to be a metroidvania that means backtracking through those platforming sections over and over again (not fun).\r\n\r\nSecondly, the visuals of this game are all aest', 'Very Positive', 80.55, 60.20, 33.27);
INSERT INTO reviews VALUES (36394, 1519710, 103, 'I wish Netherlands was real', 'The one and only difference between a mixed review in the store or probably VERY POSITIVE or maybe even OVERWHELMINGLY POSITIVE is the price of the game. It''s by far the most overpriced game I have come across. Its great to play, fun little story, funny things, very well made.. Yes it has got it all to be that indie game which goes OVERWHELMINGLY POSITIVE. But it seems the developers have been caught by greed and money unfortunately. \n\nIf they would price this game at a $4.99 (that''s what is wor', 'Mostly Positive', 76.70, 4.83, 3.02);
INSERT INTO reviews VALUES (36397, 1520380, 240, 'HyperCube, yo', 'Somehow a downgrade to the previous games in gameplay. Falling through the floor. Having to remake lobbies constantly.', 'Mostly Positive', 75.83, 4.72, 1.05);
INSERT INTO reviews VALUES (36403, 1524630, 312, 'Some people here don''t seem to understand what this game is about, expecting something like ARK Survival or similar. There are complaints in the reviews about the graphics and gameplay, which I don''t get. The graphics are solid, focusing on base building and survival. The performance isn''t perfect, but with FSR, I can reach up to 110/120 FPS on Ultra settings. It uses Unreal Engine 5 "Next Generation," so it''s understandable that it won''t run optimally on weaker PCs.\n\nIt''s an indie game develope', 'This game is VERY clunky.  The controls are awkward and trying to craft just one of something is near impossible.  Also be aware that this game EATS memory.  My video card is above the minimum requirements and it still gives me trouble.', 'Mixed', 66.67, 3.87, 0.28);
INSERT INTO reviews VALUES (36407, 1526900, 612, 'I was performing cunnilingus on a pokemon when another creature snuck up behind me and started doing the macarena. I had to stop jacking off cause I laughed too hard, solid game.', 'Such a great game with potential, sadly there are a few things that they should of done beforehand.. First its a great pass time game and getting the right angles to get S+ shots are fun and challenging.  The con to this is that  a lot of the the animations are not as smooth as they should be. Lots of art during animation is off.  Second the clothes on player are off and choppy. The Jump function is way to short hand have to be just right for it to work. The trow stone well useless or a bug. Las', 'Overwhelmingly Positive', 95.42, 1.80, 3.98);
INSERT INTO reviews VALUES (36409, 1527950, 11421, 'Great game, the only downside being no proper endgame - you don''t get to see any kind of credit roll, and some simple slideshow showing you what you achieved. Sooner or later, as you have achieved everything you wanted, all that is left is to leave the game without any closure.\r\n\r\n', 'sigh, come back to see if the game has been updated since its boring lack of content launch, and yes it has. its just locked behind 60 dollars of paywall in the form of dlcs. this game isn''t worth 60 dollars. Content you failed to add in at launch or during an alpha / beta release should not be on the consumer''s end to pay for.  Make a complete game next time.', 'Very Positive', 87.96, 124.18, 48.13);
INSERT INTO reviews VALUES (36415, 1530160, 930, 'Enjoyable Digimon game with a very frustrating grind and unfair difficulty.\r\n\r\nYou pretty much have to abuse the defense order or you will get ragdolled by bosses that spam their ultimate move back to back practically one shotting any digimon that isn''t defending (Defense order should have been unlocked from the start with how necessary it is to beat the game). Post game pretty much requires never making mistakes raising your digimon and having near max stats and a huge supply of full heal items', 'It''s fun, and I want to upvote it to support Digimon as a whole, but it just seems bandai doesn''t want to make games that are for Digimon that have mechanics and game features that would bring Digimon games up to snuff. What I mean is, no matter how good the cinematics are or how many Digimon they put into the game, it won''t make up for the fact we''re either playing a sort of baby-sitter simulator where you clean up dung and feed them constantly or you''re playing a Virtual Novel.... I mean.... t', 'Very Positive', 81.72, 73.13, 4.75);
INSERT INTO reviews VALUES (36416, 1530450, 130, 'My first thought on seeing this game was, "why hasn''t anyone made this game before?" It''s such a great idea! I love simultaneous turns for this kind of thing; the comparison that always pops into my mind is BSG: Deadlock (and Star Hammer before it), but having to worry about things like gravity, blackouts and detailed systems damage adds a lot to the experience.\n\nAfter playing it, I can appreciate why we don''t have a million games like this, and it''s because they had to solve some pretty tricky ', 'Basically a demo at this stage - massively overpriced at £25. The few pre- made missions are mostly garbage (Friendly Fire in particular). No scenery. No weather. Only 4 planes, of which only the spitfire is flyable, except for 1 or 2 pre-made missions, and even in these, the 109 would not go over 150mph.\n\nThe wing commander missions all seem to start off with all the planes stacked in a small column - basically an instant dog fight with no chance to jockey for advantage before the battle starts', 'Very Positive', 91.54, 2.75, 27.22);
INSERT INTO reviews VALUES (36417, 1531540, 1957, 'The most realistic space faring 4X game out there. I love how the private economy basically manages itself and you have the option of automating the entire game, essentially making it an auto4X game if you want. But you can turn all that off and micromanage every aspect of the game as you see fit (outside of the private economy). You can, however, greatly influence the private economy through how you setup your form of government at the start of the game and through various tech paths (which the', 'I have rarely encountered a game in more dire need of spending a solid year on nothing but quality-of-life fixes. I know making content is the fun part of game design, but that''s not what Distant Worlds 2 needs. It needs a middle ground for its automation settings, somewhere between ''constantly fighting the player at every turn'' and ''off.'' Fleets need a ''retire fleet'' option instead of having to hunt down all their ships to select and retire them directly (especially for when you end up gifted w', 'Mostly Positive', 70.57, 779.67, 32.72);
INSERT INTO reviews VALUES (36418, 1533390, 34123, 'Its a fun and cool game but alot of racist kids and toxic kids', 'I just got an 8 Week ban for doing literally nothing I was literally listening to music while playing the game and I got banned for cheating?!?! The only mod that I had on was a camera mod for recording videos? like what the heck gorilla tag I wasn''t doing anything against the code of conduct?!?!', 'Very Positive', 93.68, 41.68, 36.63);
INSERT INTO reviews VALUES (36421, 1534840, 2454, 'It''s definitely still in its earliest stages, but the core gameplay loop is satisfying and pretty unique for a roguelike. The exploration is very Breath of the Wild inspired, with a more enjoyable combat loop based around movement - weaving in and out of attacks and primarily relying on knowing when to charge attack or wear down enemies - all while providing rewards for exploration through upgrades and new weapons. \n\nSome of the critiques are on point - the performance is a bit choppy at times, ', 'Incredibly punishing at the start and some weird balancing decisions have me scratching my head. \n\nWhy are basic attacks so incredibly weak compared to cooldowns? Why is there a detailed parry system when fights are usually against fast swarms of enemies where there''s no time to exploit an opening? Why do I have no innate way to heal myself when I have to kill thousands of enemies and I die in ~4 hits from anything? Why do I drop all progression currencies when I die, when losing everything I ha', 'Mixed', 67.11, 1.45, 2.32);
INSERT INTO reviews VALUES (36422, 1534980, 1207, 'I love zombie games, I love survival horror games, i love roguelites, and Terminus scratches my itches without being too in depth. Unlike the dwarves of Moria, I can delve just deep enough into the crafting mechanics to succeed without going insane. Everything is pretty simple, from three hit locations, simple stats to track, tooltips are easy to read and understand, and the menus are easy to navigate. \nThis isn''t your standard survival game, like 7days, Zomboid, or CDDA. Your playthrough has an', 'The fact that you starve to death in 20 hours wouldn''t be so bad if it didn''t take an hour to walk across the living room, or three hours walk over to your neighbor''s house.  The whole pacing and time system makes no freaking sense.  \n\nYou have all these stat bars that are constantly degrading at breakneck speed - it feels a lot like playing the Sims in that regard - only you have no agency over what items are in the game, so you''re pretty much guaranteed to drop to zero in something and die unl', 'Very Positive', 92.63, 205.83, 0.60);
INSERT INTO reviews VALUES (36423, 1536090, 1631, 'As a diehard Stardew fan, I can say this game is the only real successor to that crown.   Instead of trying to copy it, the devs came up with their own new take on the genre, which is what made Stardew so fantastic.  It was an original in a world of first-person shooters.   Plum Grove is an entirely new take on the cozy concept.   And its customizability really does help you play exactly the level of challenge you enjoy.\r\n\r\nI''ve got almost twelve thousand hours in Stardew, and about a thousand h', 'I loved a lot of this game, it''s really cute, and the mechanics are fun, if a little challenging at times. But there is one massive problem I have with it, that has honestly ultimately put me off of it. My daughter grew up, and that was great, but then out of the blue I got a notification in the mail that she was engaged. To her uncle, her other parent''s brother. And there was nothing I could do about it, there was no possible way to stop it, or turn it off.', 'Very Positive', 90.44, 1373.82, 35.38);
INSERT INTO reviews VALUES (36425, 1536620, 224, 'This absolute GEM of a game now fully works on Steam Deck, devs have been amazing at communicating throughout the fix! Credit to them and all who helped. I’m not the most tech savvy guy so loved the passion they showed to help. \n\nOh and this game is super fun and slick! One of the few games I’ve been hooked on and keep coming back for more! You know a games good when you look forward to smashing it when you get home!🤣. \n\nThanks again and keep at it!🙌', 'I was excited for this game after seeing Splattercat play and trying the demo for myself, but honestly this game is boring. I thought shooting boulders and enemies at stuff would be enough of a fresh change to the bullet hell genre to make this fun for me, but it really isn''t. There''s very little here to make me care and game play feels monotonous.', 'Overwhelmingly Positive', 95.98, 6.13, 2.63);
INSERT INTO reviews VALUES (36428, 1537830, 587, 'I have 150 hours in the games so far and i still come back every week to get my dose. Finaly a Kart game that compete against the Mario Kart series. 10/10 \n\nAlmost on my 3rd level 50 racer, capping one from each movie is my goal !', 'This could be a really good game if they stripped out the free to play and charged $30-50 for it.  I messed up and bought access before it came out thinking it would be a pay kart racer game. Its not worth booting up with how much they try to nickel and dime you in it.', 'Mixed', 62.18, 188.17, 5.83);
INSERT INTO reviews VALUES (36430, 1538570, 1527, 'Husband and I are having fun playing it side by side at our computers at the same time. We both did custom settings for our play styles. The gameplay is comparable to other similar to it. Nothing wow, but fun trying to manage. It will keep us busy for the weekend. I do not believe the game is being worked on anymore since they have a new game currently in EA, but we did not run into any bugs or issues. If you like these types of games it is worth picking up on sale. That is what we did. Good tim', 'I''ve got 74 / 85 achievements after 20 hours of playing time. The remaining achievements are for doing poorly (citizens leaving, dying of hypothermia, revolting, etc.), so I am not really compelled to get them, nor am I compelled to replay the game. Most of my actual playtime was spent staring at the research screen because you cannot queue multiple research projects, and at a certain point you are just waiting ages for immigrants to arrive and research to complete. There is a great, rich resour', 'Mostly Positive', 74.98, 34.85, 20.65);
INSERT INTO reviews VALUES (36431, 1539140, 782, 'sold my apartment to short sell 100''s of shares in Gemustop and lost everything. \n', 'Not recommending because the core game element (stock trading) is so shallow it''s basically just lottery. I know real stock market is prone to surprises, but here it''s *all* there is to it.\n\nThere is essentially no useful data that you can analyze. The data is either irrelevant (past profits, market cap), so direct that no analysis is needed ("investors are excited about construction companies"), or so vague no analysis is possible ("strange events at X change its stock price" - that''s it, you c', 'Overwhelmingly Positive', 97.44, 1.17, 4.47);
INSERT INTO reviews VALUES (36439, 1544360, 2209, 'LEGO Builder''s Journey is a pretty good puzzle game with a nice story. There is not a lot of content, so I would wait for a lower price.\n\nPros: The game has really good graphics and lighting, the gameplay is relaxing, and I wasn''t expecting a heartwarming story.\n\nCons: The controls feel weird, it can be awkward when moving the characters or placing bricks. Some of the puzzles are not designed well. I know the developers want the player to think outside of the box, but I still don''t like the solu', 'Cool cool but the default controls are painfull. Plenty UI have drag and drop but here you are forced to work other way. One click = pick up. Click while holding = rotate. Click and hold = drop. \nThis is so counter intuitive and there are no options to configure any controls!! :(', 'Very Positive', 81.62, 3.67, 1.20);
INSERT INTO reviews VALUES (36442, 1545560, 1566, 'It''s difficult writing about this game after the closure of the studio. I enjoyed their other games, and I enjoyed this one. In some ways, it was the triumph of their production.', 'I was really excited to get into this game. Desperado''s 3 was incredible! This feels like a far cry from that. The characters aren''t particularly interesting, the story is bland, the missions feel repetitive and for some reason the path finding and controls seems to have regressed from the previous title. I really wanted to enjoy this game, but after 8 hours. Its unfortunately a no from me.', 'Very Positive', 91.57, 29.87, 7.92);
INSERT INTO reviews VALUES (36445, 1546400, 1031, 'A great game overall, really capturing the spirit and quality of Godzilla Destroy all Monsters. And it literally has Godzilla now. My only major complaint is if you''re not playing multiplayer the game can be pretty bland pretty fast.\n\nMaybe something more in depth for a story mode, or a campaign mode like War of the Monsters did ages ago.\n\n\n', 'I cant sex the godzilla', 'Very Positive', 94.96, 5.43, 4.38);
INSERT INTO reviews VALUES (36454, 1548750, 159, 'My mum came to visit me over Christmas and she was always a fan of watching my brother and I play adventure games when we were younger, so I purchased this to occupy our evenings.\n\nWe both got bang into the storyline and the somewhat haphazard detective techniques of the main hero Mr Conway. \n\nOverall it was an enjoyable game. Puzzles not difficult so would have preferred more of a challenge here. Ending was a little rushed IMO too but otherwise we got our moneys worth and were able to immerse o', 'i only have 3 hours playtime because i had to restart twice due to game breaking bugs that forced restarts, both early in the game, one with the piano puzzle getting stuck and another soon after with a door prompt not showing up.\r\n\r\ndevs keep slowly pushing updates they say fix things, while replying on the forum they are unaware of any game breaking bugs so maybe this will finally get their attention.\r\n\r\nnot worth the cost even on current sale.', 'Very Positive', 88.05, 12.92, 8.08);
INSERT INTO reviews VALUES (36455, 1548850, 8529, 'This game is very realistic, so sad how our soldiers had to deal with 30 FPS on the battlefield', 'You. cannot. close. a. door. In a CQB sim. Unbelievable.\n\nPicture this, Im still on the tutorial part of the game. I walk in the main room of a building, braindead AI squad members see the main door leading outside, they (the AI) decide its a good idea to try and kick it open for some reason. Now the shooter on the opposite rooftop has a clear LoS to all of us and we get shot at every time we have to walk through that main room to clear the rest of the building, all this because programming clos', 'Very Positive', 85.39, 0.83, 1.68);
INSERT INTO reviews VALUES (36458, 1550010, 421, 'I love witchy games and this is one of my all time favorites! This game has my two favorite things: wandering around a pretty world and collecting things. So if that''s what you enjoy, I definitely recommend this game! That being said, there are some things that could use improvement in the game. It is very hard to know where you are supposed to go and what to do, though they are at least adding in quest area highlights in a new update. Still, it is frustrating to get a quest and spend hours upon', 'So much wasted potential... The game has some really nice idea, it could be one of my favorite cosy farming game. But in the end, they butchered it. One problem is the technical difficulties. The game crashes so many times, it''s getting annoying. Especially when I''m ready to end the day and save after grinding my soul out, and I need to start over the whole day... But what''s more problematic is the gameplay itself. It supposed to be a cosy game, with farming, exploring, collecting stuff, etc. Bu', 'Mixed', 67.93, 60.53, 148.07);
INSERT INTO reviews VALUES (36463, 1551360, 78915, 'installed the game\ngrinded the "storyline"\ngot a few cars\nshot at 430 km/h over a mountain\ncrashed into a rock\nlost drift series of 1.8 million points\n10/10 game', 'Gotta change my thumbs up to a thumbs down. Bought the digital deluxe ultra premium special edition, which includes the car pass, but now I''m repeatedly being asked to pay $3 per car in the new car packs? Massive L.', 'Very Positive', 88.55, 85.70, 86.18);
INSERT INTO reviews VALUES (36465, 1552350, 987, 'If the Wheel from Wheel of Enormous Proportions is reading this, I hate you with every inch of my body. I answered all of your stupid trivia questions correctly, got all of the slices AND the power slice, even set my username to "ILoveWheel" on jackbox.tv, and then you had the AUDACITY to let my dumbass, 0 IQ, 2 inches long friend win the game despite doing literally nothing. \nAnd his question? If he should waste his money on One Piece cards. You know what won''t be in One Piece? Your Babybel-loo', 'Bro, this pack is just AWFUL. Not a single game worth coming back to on here and the Wheel of Enormous Proportions was the worst time playing a game that me and my family ever had. Such a shame. Every other pack is better than this one.', 'Very Positive', 90.68, 32.83, 2.62);
INSERT INTO reviews VALUES (36469, 1555910, 121, '10/10 Came for the nut, stayed for the story.\r\n\r\ndownloaded the demo, got enthralled, bought the game to keep going. I lost 4 hours of my morning to this, I completely lost track of time I was so engrossed in this, only stopped cause I seen the sun come up. Wanted to drop this first. I''m going to bed now.', 'I really wanted to like this because the zombie girl looked interesting. it popped out as something more unique....The dialogue sequences are not well written, and can run on without a point. It reminds me of AI writing. I was going to brute force through it in hopes of it picking up, but the MC is insufferable. Think like gross wannabe edgy discord mod writes themselves as a loner writer who has guns and thinks killing is "cool." Dropped it after MC made a comment about waiting for a girl to be', 'Very Positive', 85.12, 11.65, 1.75);
INSERT INTO reviews VALUES (36472, 1556100, 2760, 'fun for a week but then gets bland and repetitive fast. just bring back f13', 'People can just leave as you are killing them and prevent you from getting a win or cocooning them. Insane that this was overlooked. Cocoon 6/7 survivors, all 6 leave and we get a loss because "1/1 humans" escaped. Game breaking...', 'Mostly Positive', 75.18, 5.02, 8.02);
INSERT INTO reviews VALUES (36474, 1556200, 2366, 'Great game but would be better with the Dr DisRespect DLC', 'The game used to be a lot of fun, but they nerfed the fireteam so much that there is no point in playing the game as anything but the predator. They also keep releasing new predators and predator weapons but haven''t dropped a single new fireteam member or human weapon since I started playing. The Dev''s have clearly given up on this title and are just phoning things in to cater to the 50 people who just want to meta build a predator and spawn kill the fireteam who no longer pose any threat. At th', 'Mostly Positive', 79.33, 5.45, 146.38);
INSERT INTO reviews VALUES (36476, 1559390, 166, '剧情有趣，探案谜题有逻辑，还融入熟悉的电视剧人物，是非常好的游戏作品！', 'The mission is too complicated', 'Very Positive', 87.95, 88.10, 51.43);
INSERT INTO reviews VALUES (36477, 1559600, 1124, 'I think this is hands-down the best horse game there is on the market. Possibly the end of the really long horse-game-curse and so many scams and horse game drama. It´s Different from other horse games, despite being about the same thing as most of them. Yes, a lot of games focus on training/caring for your horse - entering competitions - upgrading your ranch - breeding better horses - repeat. But it is so much more than that as well. It´s cozy, it´s stylized, and it´s especially perfect if you´', 'This game''s rave reviews show how badly abused enjoyers of this genre are. Other horse games are so incredibly abysmal that as soon as a solidly mid contender gets released everyone weeps with joy. So let me give a sober review of this: it''s okay. The art is pretty, the animals are cute and there''s a good amount of content. On the flip side, the controls are insultingly bad, the camera is janky as hell, there is still a large amount of bugs even though it is now fully released and the story is..', 'Very Positive', 93.59, 57.57, 27.60);
INSERT INTO reviews VALUES (36480, 1560250, 2450, 'It''s not bad but far from being a viable product.\nHas a lot of gamebreaking bugs, general polish issues, a lack of emphasis on unit differences, a lack of unit variety, a lack of tanks, a lack of planes as units. There is NO AI in the game. The movement of enemy units in matches is ENTIRELY prerecorded using the scenario creator.', 'The game itself is very good. However, the AI is terrible. It camps always around one spot, which means one good artillery bombardement can kill entire garrisons. ALso, AI doesn''t seem to be able to use machine gunes properly. Then the spawnpoints. Thge spawnpoints are awful. If the enemy manages to storm your positions, you get killed immediatly after spawning, which makes it impossible for you to continue playing. And the death screen is just awful, it stays for way too long, even after respaw', 'Very Positive', 89.92, 42.23, 5.15);
INSERT INTO reviews VALUES (36481, 1561340, 226, 'It''s fine enough. It feels really good to move. It aped Copen''s thing from Gunvolt pretty hard and I don''t begrudge that one bit. Fighting stuff rules. But the level design is getting me down. Rather than surveying obstacles in front of me and deciding how I want to utilize my kit as one does in Mega Man, I''m switching weapons every three seconds to utilize some bespoke interaction that requires a specific weapon. This platform only moves with the fire ability, this wire is only grabbable with t', 'Having to collect metals should be an extra fun activity for the player not required to see the ending of the game. There is no reason other than to collect them, no rewards, no extra unlockables just required to beat it. Fun game but the levels get extremely repetitive and I have no interest in replaying them to find obscurely hidden secrets with no map or radar. If the game would have just ended I probably would have left a positive review, but man what a lame way to arbitrarily double the pla', 'Very Positive', 88.94, 3.12, 3.80);
INSERT INTO reviews VALUES (36488, 1564560, 238, 'Really cute and easy puzzle game.\nI''m finishing it with my 6 year old son who is passionate about it^^\nPrice in line with the content. \nRecommended to pass the time, not recommended for those looking for a challenge. 7/10 my rating', 'This sadly isn''t much of a game or a puzzle. The objective is to rebuild an island based on a template. You can always switch to and back from the template, which eliminates all challenge. The gameplay is rather slow and, even if you would like to play it as a memory-type game, later levels are very big which forces constant switching to the template. Overall you can kill some time with it, but I would not recommend it. I also randomly lost progression about halfway through, but luckily there is', 'Very Positive', 94.54, 9.25, 2.02);
INSERT INTO reviews VALUES (36492, 1566200, 2364, 'I would easily rate this game 10/10, but without online multiplayer it''s just 9,9/10. Make it happen so I dont have to invite my friends over. My sofa always smells like butt afterwards.', 'It''s honestly mind-blowing to me that we can still get sports games like this in the 2020s, cheap and frustrating AI, half baked mechanics, and limited replay value.\nFirst, the AI is way too unbalanced. You will dominate the game in shots on goal, time on attack, pass interceptions, and hits, and still somehow lose the game 2-1 or 3-0. The opponent goalie is way too strong, how many cross crease one-timers do I have to shoot in one possession, just for the AI to score on a lazy floater from the ', 'Very Positive', 92.47, 330.88, 32.12);
INSERT INTO reviews VALUES (36496, 1569580, 6704, 'This game is for a very particular type of person - someone who enjoys both puzzles AND rogue-likes. It''s an unusual combination, and I think many of the negative reviews are from either puzzle fans who either don''t like or aren''t familiar with the way one progresses through a rogue-like game, or from rogue-like fans who find the switch to progressing through puzzles vs combat to be obtuse and frustrating. But if you''re someone who actually likes both kinds of games, then you''ll REALLY enjoy thi', 'This is a good game with really clever puzzles, but it is held back by a number of really irritating oversights that can be summed up in one phrase: it does not respect player''s time. I will explain what I mean by this. If developers could consider improving on these, that would be great.\nFirstly, there is a lot of unskippable, unnecessarry long transitions during pretty common actions. Things like: camera flight at the start of new run, stats counters at the end of every run, digging dig spots ', 'Very Positive', 86.75, 50.38, 22.68);
INSERT INTO reviews VALUES (36503, 1571100, 391, 'Before I played Passpartout 2, I hated France, sucked at art, and was absolutely hopeless.\nNothing changed, but the game was pretty good.', 'If it was 5 dollars it would be good. But the game is just all over the place. It starts off fun but there is really not much to do and unlike the first game there is really not guide in the story you just go around trying to figure it out yourself. Very overpiced and lacks what the first one did so well', 'Very Positive', 94.88, 4.05, 9.40);
INSERT INTO reviews VALUES (36515, 1574900, 984, 'Salt 2: Shores of Gold is a chilled game of exploration. Your ship is your home. In a procedurally generated world you can sail and explore to your heart''s content. There is danger on the islands, sometimes unexpectedly. There are caves to explore but you never know what will be waiting for you in them. Tons of crafting to do, resources to harvest, and skills to level up. \n\nI recommend you enter the world of adventure and purchase this game :)\n\nArr!', 'Could have been great. Instead, the game switched to a multiplayer focus. Multiple updates and posts made by dev to appease a mob of people requesting multiplayer. Thing is, those same people will be done playing the game two weeks after release. While the single player fans will be left with "what could have been". Cast out to sea, in favor of multiplayer slop.', 'Very Positive', 86.79, 14.70, 36.93);
INSERT INTO reviews VALUES (36522, 1577120, 6371, 'i put on the 80''s outfits and the 80''s filter so all the times the game doesnt let me make a choice or the characters make a choice that is so unbelievably stupid i can trick my brain into thinking its a horrible 80s horror movie', 'I would have said yes to recommending this game if they didnt have the absolute WORST save/re-play system. Loved the game and wanted to try and get different endings once I completed the original run through, but I accidentally chose the wrong chapter. Come to find out you cannot choose another chapter, you have to FINISH THE PLAYTHROUGH to choose another??? I''ve already completed the game, why do I have to complete it AGAIN to be able to choose a chapter to jump to. Such a fun game but that rea', 'Very Positive', 83.02, 9.43, 8.82);
INSERT INTO reviews VALUES (36526, 1578390, 1417, 'Build car, crash car, repair car, get mad because you don´t know how to repair it, sell car, buy new car, build car, repeat.', 'crashes way too often absolute mess of a game', 'Very Positive', 90.90, 160.58, 0.15);
INSERT INTO reviews VALUES (36530, 1579340, 132, 'Survive the Fall has a Mutant Year Zero vibe, with very similar exploring system and setting, but with real-time combat instead of the turn-based MYZ. However, it takes us to a next level with the base management. It''s a very cool game.', 'Feels like a mobile game. not much for an open world survival you start a project wait 15 minutes clear some debris start project clear more debris i can down load this on an app store for next to nothing and get the same thing', 'Mixed', 68.94, 6.78, 0.70);
INSERT INTO reviews VALUES (36533, 1581770, 1033, 'Great game. Not exactly your standard 4x, more like Thea mixed with Age of Wonders - text-quest-roguelite-4xlite-tbs. Sounds like some crazy cocktail, and it probably is, but it''s good. \r\nYou play as some upstart mage striving to get into the Circle and you have 4 craft mastery types (classes) and 7 spell schools to choose from. Crafting process itself is pretty similar for different classes, but results vary greatly and each class feels very powerful and unique in it''s own way.\r\nGraphics and so', 'I really love the foundational idea of this game, however, the game constantly scales up with you so that once you get past the initial "okay, this is easy enough that I can win and can get my characters to level up" fights, every one of the main antagonists stays tougher than you and if you become their enemy, they just hammer you over and over. And if you lose any of your soldiers that you''ve been levelling, it will take you a couple hours to get the new guys up in level, but your enemies just', 'Very Positive', 81.41, 541.00, 157.22);
INSERT INTO reviews VALUES (36536, 1583320, 3469, 'Ngl this shii better then Fifa. 5 stars.\r\n\r\n\r\n\r\nI love oiled black men', 'good idea and can only get better, put some freaking effort in it brylos and start actually trying to make this game a real game instead of just a limited 4 moves game, its been early access for way too long and its been literally the same game for a couple of years now, jesus bro why are you so lazy!', 'Very Positive', 87.35, 58.25, 895.95);
INSERT INTO reviews VALUES (36543, 1585180, 3915, 'Metaphor: ReFantazio, Final Fantasy VII Rebirth, and Dragon Age: The Veilguard are gonna be fighting for best RPG of 2024, and sadly the actual best RPG released this year likely won''t even be nominated.', 'I see what this game is going for. But it doesn''t do a particularly good job on the details.\r\nCombat: \r\nIs just bad. Just. Really bad. Enemies ALL move faster than you. Human enemies can, and do, sprint in combat. You cannot. Your dodges, power attacks, and special abilities are limited via resources. Theirs are not. Non-human enemies are not quite as bad, but they tend to have at least one move that is basically a half-screen dash attack, making it difficult to keep pressure on.\r\nSecond. The wr', 'Very Positive', 94.18, 31.68, 35.50);
INSERT INTO reviews VALUES (36546, 1586750, 127, 'I had the great opportunity to speak to the developer at gamescom and so far i love the vibe of the game.\n\nHopefully there will be online play added in the future.\n\nIf you like fighting games and enjoy old samurai movies, be sure to check this one out.', 'The game is awesome but only provides like 30 minutes of play time. It''s something you revisit every few months. I love the art style and the characters. The concept is amazing too but for only 30 minutes of play time and almost nonexistent player base it''s not worth the 10 dollars. If it was around 4 dollars then I would recommend.', 'Very Positive', 91.34, 0.57, 0.50);
INSERT INTO reviews VALUES (36547, 1586800, 3531, 'Such an all round wholesome game!\n\nIt''s like being a kid again and spending a Summer day going on adventure and making new friends. You know...that time when a rock was not just a rock and a stick was not just a stick... :)', 'It feels weird to not recommend a game that I actually really liked, but for the price it just falls flat in too many areas. The game is extremely one-note; pretty much every friend quest is either breaking a few targets, sometimes timed, or just finding some characters and clicking through some cute dialogue. The environments follow suit, where the only locales are Forest, Mountain, and Slightly Dry Forest. Most items you get are reskins of the default equipment, with some fun exceptions but no', 'Overwhelmingly Positive', 99.09, 5.08, 3.08);
INSERT INTO reviews VALUES (36551, 1588530, 1548, 'I  love this product. I have already used it for three of my maps for D&D however, I really wish there were more abandoned or ruined structure options. I also wish there were sci-fi or cyberpunk options because finding good maps for Traveler of Cyberpunk red can be tricky sometimes, and I would rather make them where possible. That being said this is perhaps the easiest map making tool I have ever used, and it has tons more potential than I have seen in any similar program in years. A huge leap ', 'It is pretty rigid and limited.   I don''t think its worth the price.\n\nFor example - create a forest map.  Then go to "Paint Terrain".  There is no sand texture.  There is no way to import textures.  There is only like 5 textures.  *BUT* if I go to create a badlands map type, the sand texture is there.   Why are all the textures not available?  \n\nRidiculously limiting.', 'Very Positive', 94.12, 22.60, 5.57);
INSERT INTO reviews VALUES (36554, 1589570, 109, 'Amazing roguelike. It has everything I want, action, magic, monkeys, bananas!\nIt''s filled with charming surprises and challenging gameplay. One of the standout features of Dunjungle is its art style. The graphics are colorful and engaging. Each level is beautifully designed, offering a rich atmosphere that immerses you in the experience.\n\nBut what I like the most are the monkey sounds (there''s a dedicated button for that)! UHHH UHHH AHHH AHHH\nFrom a monkey to another monkey', 'I found Dunjungle to be a fairly mid-tier game, not terrible, but not impressive either. While it clearly draws inspiration from Dead Cells, it doesn’t offer enough unique elements to stand out. When deciding whether to recommend it or not, I’d lean towards not.  \n\n- Although it''s a roguelite, the procedurally generated levels felt too similar from one run to the next, making each attempt feel repetitive.\n  \n- The variety of weapons and abilities is limited, and many options felt almost identica', 'Overwhelmingly Positive', 99.08, 200.22, 1.68);
INSERT INTO reviews VALUES (36558, 1592190, 12695, 'As I did refund the game. I don''t have much "bad" to say about it other then a couple I guess.\n\nIts a spin off of Bone Works, just more directed towards the sandbox style rather then a story line. Bone Works is much cheaper, and has a bigger story line, one that leaves you hooked. The Storyline is just way to short on Bone Lab for me to justify spending almost 40 bucks on it when I can just boot up Bone Works an enjoy an amazing story line.\n\nIf the game ever gets a REALLY good sell I will re pur', 'Overpromised, underdelivered, abandoned.\n\nBONELAB is a game that owes its entire monetary success to an initial wave of unearned hype. Let me make this clear: I LOVED Boneworks. It''s one of the best VR titles available - even now, years after its release. But this game, despite all the bold claims of having "full modding support!" and being "like Boneworks but bigger and better!", BONELAB is nothing but a hollow shell with a pretty painted exterior - a glorified tech demo for a promising concept', 'Mostly Positive', 78.12, 0.73, 16.07);
INSERT INTO reviews VALUES (36559, 1592280, 3478, 'Doom engine in 2024 more fun then Unreal 5.4\nIf you dig this check out the Ashes 2063/Afterglow/Hard reset', 'A game I really want to like. The graphics and art style are great and the shooting feels good. But there isn''t enough of it. I wish the game was more like some of its possible inspiration like FEAR. But maybe that is me.\n\nThe map is simply too large or confusing to navigate. I got lost way too often and found myself getting bored looking around the same environments. All enemies you kill in at most a minute or two. The rest is just wandering around for switches and keycards. The maze-like convo', 'Very Positive', 93.76, 28.15, 4.53);
INSERT INTO reviews VALUES (36560, 1592290, 426, 'If someone gets stuck at the orphanage during the part where you need to place objects on each grave, try removing them and placing them again. The issue occurs if an item is placed too early. We struggled with this for a while before figuring out that resetting the placements solves the problem.\n"Adam, Timmy, Emma, and Judy are still picky even in the afterlife"\n', 'i highly do not recommend this game the killer camps to much around your team mate the difficultly needs fixing like easy mode is the same as hard mode and impossible to even understand what you are meant to be doing in the game as every little sound that you make your dead before you know it', 'Very Positive', 88.26, 3.82, 2.63);
INSERT INTO reviews VALUES (36567, 1593780, 101, 'very enjoyable the kids love it', 'aint it', 'Very Positive', 85.15, 13.42, 0.92);
INSERT INTO reviews VALUES (36575, 1594060, 298, 'NEEDS MORE GOTH!\n\nVictory Heat Rally is like those 90''s racing games. Simple but with a difficulty spike towards the last few races. Having more goth girls would have made the game better. Hooters would not be going out of business if they had goth girls. An all goth Hooters is a multi million dollar idea. Would probably work for racing too.', 'This games has some nice style and feels like a racing game from the late 90s/Early 2000s aesthetic.   I love the music and design style of the entire world this takes place in.   In short bursts of playing it can be quite fun.\nThat being said however the game does not feel like it took eight years to develop.   There''s some noticeable bugs and glitches abound.   The art design on the vehicles look cute like a choro-Q car, but they have very few frames of animation.  And a lot of the vehicle spr', 'Very Positive', 93.96, 23.37, 6.88);
INSERT INTO reviews VALUES (36580, 1594130, 104, 'The game is very good and cool. i like games that allow u to roam freely destroy the city and fight kaiju. i wish we could go back to the old version though but it is what it is', 'Excidio is barely a game, more of a tech demo. It has fun destruction, monsters feel weighty, there is a great foundation for a great kaiju game but there is a lot of work still need to be done at the time of this review. The biggest thing its missing is a desired goal, just sandbox destruction. Dont take the "Do not recommend" as a "do not buy" I just cant recommend it because its such a minimalist bit of content that I only got an hour and a half of enjoyment out of it before the charm began t', 'Overwhelmingly Positive', 97.12, 20.32, 1.98);
INSERT INTO reviews VALUES (36588, 1594320, 3544, 'I now understand why big companies destroy the planet(pro tip dump trash in the ocean to increase your land)\n-Very good game', 'I''m sorry, but I have to. New UI is downgrade and deal breaker. I love the game, but cant play it now without being irritated by unintuitive UI, hard to read font for numbers, ununified system of closing dialogs and screens, annoying notification system. It all stand between me and my island, between me and joy playing the game. \nI will be happy to change my review in future, now with heavy hearth thunb down :(', 'Very Positive', 94.13, 112.67, 262.57);
INSERT INTO reviews VALUES (36614, 1594880, 176, 'It''s hard for me to say absolutely. Yes if you are really hurting for a semi-realistic age of sail action RPG, otherwise no. \n\nI played a game nearly identical to this called Age of Pirates: Caribbean Tales about 19 years ago. This is like a prettier version of that, with a more engaging quest system.  So it''s basically an incremental step up in that case, but brings it back down with jank. I have crashed to desktop as many times as I have quit the game normally, the camera is jerky at times, th', 'How the developer can release a game in this state is beyond me. To me it comes down to complete laziness the fact that either the devs haven''t played the game to find out the multitude of bugs or they are aware and haven''t bothered to sort them out. I bought this game on the expectation it would be similar to the Pirates of the Caribbean 2003 game and I was aware that it was early access. Perhaps the dev should look at POTC 2003 to see how a game, which was released over 20 years prior to the r', 'Mostly Positive', 72.73, 3.07, 2.92);
INSERT INTO reviews VALUES (36617, 1594940, 2981, 'great game <3x1000 ...but pretty concerning that there hasn''t been any mention of a full release yet even though the early access was released over 2 years ago now.', 'I loved this game when I first played it in 2022. It seemed like a perfect cozy, casual gaming experience, I enjoyed everything about it and was looking forward to playing the complete game.\nBut the fact that almost 3 years later the game is still in early access and the developer works on things like customization/cosmetics instead of finishing the story first, makes me lose my faith that it''s ever going to happen.\nOn top of that, when I installed one of the updates some time ago, my whole prog', 'Very Positive', 91.48, 250.03, 12.22);
INSERT INTO reviews VALUES (36626, 1595030, 307, 'List of characters:\n\nSweet and sexy redhead\nThe others\n', 'i purchased this game because it said FULL ENGLISH AUDIO in the description. WRONG! It has NO voice acting at all.I''m no game expert, but I can''t see how adding voices is such a big deal. I think it adds so much to the game', 'Very Positive', 84.04, 6.87, 13.30);
INSERT INTO reviews VALUES (36639, 1595290, 242, 'Bought it for all the wrong reasons when it was on sale.\nTurns out it is a pretty relaxing puzzle game.\nIt''s not the best puzzle game but there was something calming about the music, game play, and naked women who look similar to but are legally distinct (the best kind of distinction) from famous copyrighted characters.\n\nI''m not joking about the relaxing game play. \nThis is like taking a digital muscle relaxer.', 'I know exactly why you are looking at this game ;) (it was the same for me).\r\n\r\nDespite the pretty girls, I really cannot recommend this game. Soooooo boring. Honestly', 'Very Positive', 80.99, 1.60, 4.18);
INSERT INTO reviews VALUES (36658, 1595640, 152, 'There are many horrors in the world, and you are a rat with a bat.\n\nIt''s a lot of fun! Takes a little practice to make good use of controls (don''t forget that you can dash!), but don''t you worry - it doesn''t take long before you can get some mobility options, and then more weapons, and other things as well.\n\nI do quite like how the game''s achievements (and different ways to beat the game) form a trail of breadcrumbs leading you to doing a speedrun.\n\nAlso... the game''s really smooth? Doesn''t seem', 'Picked this up as it was praised by The Metroidvania Review, and I can''t tell you why.  I did not enjoy my time with this, but I don''t feel like I was swindled or anything.  Just not for me.', 'Overwhelmingly Positive', 96.71, 19.17, 0.90);
INSERT INTO reviews VALUES (36687, 1596310, 749, 'My electricity provider likes this game.', 'I built an incredible mining farm in this game, but none of my earnings are withdrawable. It''s a complete scam! Despite having multiple bitcoins, the game wouldn''t let me withdraw anything. What a joke. I can''t believe they make scam games like this. I advise anyone to just buy Bitcoin directly instead of wasting time mining it here.', 'Mixed', 64.35, 0.63, 5.20);
INSERT INTO reviews VALUES (36694, 1596440, 103, 'Really fun short boomer shooter. You are Arkos, the founding member of Nickelback, betrayed by Chad "Wizard" Kroeger you need to exact your revenge and start the best band in the universe (Creed). Now that you know the story (which is breathtaking), let''s talk about the graphics: they''re nice. Movement is good, but I wish it was faster. Also the music is fantastic. The gameplay is repetitive, but as the game is short (4-6 hours max) you won''t notice it. I recommend it ''cause it''s cheap and fun. ', 'I can appreciate wanting to create a mashup of Wolf3D and Heretic but this game does so much wrong I couldn''t stomach more than 3 Episodes. \r\n\r\nFor starters, visually, this game is vomit inducing, it''s incredibly hard to tell where you are in relation to the rest of the level, everything looks the same on top of the overuse of voxels and samey textures leads to disorientation and it''s quite frankly terrible. Also, as you progress, just getting through the levels requires a lot of wall humping an', 'Very Positive', 80.58, 5.78, 1.30);
INSERT INTO reviews VALUES (36727, 1597310, 358, 'After the logistics update, I''ve been binging this game, love it. Its still rather difficult to keep the whole business machine running, or from running into hiccups. But its been a good opportunity to practice algebra and Excel. Its very fulfilling when things just work eventually. And its the Sailing/Trading/Warship simulator I had always wanted, and I''m not sure if it was on purpose, but it taking place on "airships" with no geography up there, it makes it so much more relaxing.\r\nLooking forw', 'This game is frustratingly opaque. I can''t even read quest materials lists like Henry''s Shopping List and Javier''s List of Building Materials while I''m out looking for the items to complete them. The game has broken bits and elements that make no sense, and nobody seems to be answering any questions on the forum.\n\nThis game had potential once, but I can''t recommend buying it now as it appears unfinished and abandoned.', 'Mostly Positive', 75.42, 157.62, 82.33);
INSERT INTO reviews VALUES (36745, 1597720, 177, 'Feed All Monsters is a nice puzzle game not too difficult with some good graphics. For his low price, I recommend it!!! 💗💗💗', '', 'Overwhelmingly Positive', 100.00, 33.02, 0.00);
INSERT INTO reviews VALUES (36746, 1597730, 579, 'I severely overestimated my intelligence when I purchased this game.', 'Not casual', 'Overwhelmingly Positive', 98.79, 2.33, 0.13);
INSERT INTO reviews VALUES (36765, 1598160, 840, 'Bloodwash is a short but fun little horror title that I really enjoyed. Nails the 80''s movie aesthetic and feels like you''re playing through a fun 80''s B movie horror. It''s very Puppet Combo like (Which makes sense when Torture Star Video''s is owned by Puppet Combo. Don''t think think Bloodwash is actually made by them though, just published) but holds less of the jarring noises present in puppet combo games\n\nWhile not really scary, it is a little disturbing with the lore of the villain and has a', 'This game is absolutely awful. Do not buy it.', 'Very Positive', 92.02, 1.40, 118.43);
INSERT INTO reviews VALUES (36801, 1599250, 177, 'A bear with extra chromosomes? Take my money and footjob.', 'Not my bag', 'Very Positive', 87.57, 0.15, 0.15);
INSERT INTO reviews VALUES (36804, 1599330, 876, 'An exceptional game. There''s a great balance between farming, action and discovery. Farming is quite unique - you can plant anywhere, as long as you can provide water. Start with one tiny water source and create rivers by the end of the game. You don''t need to grow much to provide for yourself, so you can do very little or knock yourself out creating beautiful landscapes. And, most importantly, you can hug frogs! How wholesome is that?', 'I love a lot of things about the game but ultimately the lack of guidance as to what you''re actually supposed to do to progress made it unplayable after a point. It''s unclear how to complete the quests, not in a "puzzle" sense but in a "this was designed badly" sense. Ultimately I was spending more time searching online how to do things that should be either intuitive or well-explained to the player that it wasn''t fun anymore. Disappointing because I do really like the mechanics and story.', 'Very Positive', 89.61, 103.13, 32.93);
INSERT INTO reviews VALUES (36809, 1599470, 238, '0/10 no coco and brownie yuri scenes /j', 'https://youtu.be/eX-E_7U5hqg\n\nHorror twee to the Nth degree if the characters don''t click immediately spending hours with them is unlikely to change that opinion.', 'Overwhelmingly Positive', 99.16, 1.72, 0.23);
INSERT INTO reviews VALUES (36815, 1599560, 529, 'Probably the best VR game after Half Life Alyx, the graphics quality and detail can be improved but the story, the puzzles, the unique gameplay and immersive locations are really well crafted and enjoyable, really hard to put down the headset and stop playing. I could finish it without a walkthrough and that was very rewarding. I can''t wait for the sequel, will surely buy it. Super recommended!', 'RACIST SUBLIMINALS WARNING. ''Star Beamers'' puzzle contains a harmful subliminal. You have put a lense on the end of a torch, so it shines a constellation. The torch is like your ''eye''. Notice the puzzle sequence is ''Libra'', ''Gemini'' and ''Cancer''. So what are you putting ''in'' your ''Gemin-eye?'' The ''crab''.\n\nThis harmful subliminal is activated by another game item, ''Super Sapphire'' - the gem - which shows this is specifically aimed at racially harming blue eyed persons.\n\nInstance 2. On the shelf, ', 'Very Positive', 84.50, 15.77, 2.85);
INSERT INTO reviews VALUES (36816, 1599600, 10896, 'I normally play those games for relaxing but this game is F**KING STRESSFUL. Every time when I fail, I feel like Gordon Ramsay watching me with the disappointment in his eyes', 'We really want to like this game, but the let down when you spent 30 minutes and get to day 14/15 and lose is too great.   I''d be OK if you got more garage items or other permanent unlocks that make the game easier for future runs, but we got a single item after getting to day 14.   It feels insulting to get as far as you ever have before and then get virtually nothing for the effort.   Practicing the harder recipes or learning about the advanced machines takes forever.  I want to play a level t', 'Overwhelmingly Positive', 96.51, 30.82, 23.63);
INSERT INTO reviews VALUES (36829, 1599880, 557, 'This is a game designed perfectly for people who love cats and puzzle games. It has an amazing range of difficulty and ease, whilst still giving you that feeling of euphoria once you complete an interesting puzzle. With that being said, I rate this game an 8/10 since sometimes it does feel like you are just dragging a block across a screen (I''m looking at you level 1)', 'Yeah I''m not feeling this. The puzzles aren''t really puzzles so much as dragging your mouse across a straight line. I HESITATE to even call them activities. When I open the taskbar on my desktop and click on my browser, did I just complete an activity? Can you call this an accomplishment? Maybe if I was three years old. Maybe if I was a quadriplegic or a double amputee. The only puzzle is how the heck this game has an "overwhelmingly positive" score on steam. I can''t wait for these reviewers to ', 'Overwhelmingly Positive', 96.59, 5.70, 1.42);
INSERT INTO reviews VALUES (36855, 1600370, 234, 'This game has so much love put into it that it actually almost made me tear up at the credits. This game was a absolute joy to play and fed into my type of humor. Though, the game is a little short for the price tag but 10/10 would definitely recommend.', 'Such a confused mess. The authors wanted to send a political message, but didn''t know _what_ message they wanted to send. Choices don''t matter, you either make the choice the game pushes, or you get punished.\r\nIt''s also not obvious when the game saves. You''d think that after you finished a night, and are on the map screen that it would''ve saved. Naw, have fun redoing the night.\r\n\r\nI''m disappointed and upset by this sequel', 'Mostly Positive', 77.35, 6.52, 8.90);
INSERT INTO reviews VALUES (36876, 1600780, 273, 'Sunny hangs out with her friends while Sprout stirs up the population to reignite a race war 10/10 peak fiction', 'Bad game friendship with benefits is better', 'Mostly Positive', 79.12, 2.05, 2.37);
INSERT INTO reviews VALUES (36901, 1601280, 163, 'This unassuming little indie game with a peculiar title and simple yet captivating graphics turned out to be the best first-person dungeon crawler I''ve played in many years. It''s got clever and intricate dungeon design, engaging and satisfying turn-based combat, and decent character and team-building options that allow for interesting experimentation. There''s also atmospheric music and a story with an ecological message—your goal is to find potato seeds that can grow in polluted soil in a post-a', 'Just a boring, poorly implemented game. Kind of reminds me of a student project made by middle school kids or something. If you like laughing at janky half-baked shovelware you might like this. Otherwise, give this one a wide berth.', 'Overwhelmingly Positive', 96.32, 30.95, 1.27);
INSERT INTO reviews VALUES (36903, 1601330, 136, 'Just some initial impressions: Nothing woke in the character creator. Simple, not that hard people ! The bones are here so far to be a great game. Original world. Playful Graphics. And a sense of humor. I accidentally got an achievement for kicking someone. Good laugh. \n\nThe only negatives is I am not seeing a pause option for the massive audience of single players ( I have been told it does have it I just haven not noticed yet). And some of the quest language seems geared for multiplayer. Its a', 'The game looks great, the idea is really cool, and I actually really enjoyed the first 5-6 hours. However, that''s where you really  hit a snag if you try to play solo. The game doesn''t scale well at all. As the game progresses, so do the costs of upkeep (fuel, repair, materials for new buildings), and with a zombie attack every other night you just don''t have enough time to do it all. Any exploration that you do becomes a frenzied rush to find a blueprint as fast as possible so you can get back ', 'Mostly Positive', 76.47, 0.42, 7.63);
INSERT INTO reviews VALUES (36911, 1601580, 7837, 'A notification popped up telling me one hundred of my citizens had died due to the cold. I thought to myself "Well, I''ll have to get some shelter built soon." And then I thought about that. In Frostpunk 1, a single death was a tragedy; a hundred would have been a nearly unthinkable disaster. In Frostpunk 2, a hundred deaths was a shrug and a reminder to get more housing built. The game dehumanizes your citizens, and I think that was a deliberate move to make you think about what happens when you', 'I hate to give this a bad review, because I loved the first game, but I just didn''t enjoy the sequel as much. It introduces new factions and systems that only add unnecessary complexity without enhancing the experience. The joy of researching and building new technologies, which was one of the highlights of the first game, is significantly diminished because you’re constantly caught up in managing endless crises. The faction system, while mildly interesting, becomes an exercise in frustration as', 'Mostly Positive', 79.23, 34.35, 80.77);
INSERT INTO reviews VALUES (36916, 1601680, 530, 'Bard', 'cant remember my secret word, cant be bothered to do it again\nshould tell u what u need 2 know', 'Overwhelmingly Positive', 97.17, 1.03, 0.95);
INSERT INTO reviews VALUES (36918, 1601740, 110, 'it''s like if Mortal Kombat and Dark Souls had a child nobody asked for', 'I feel like this game is *almost* a really good game. its biggest problem is that that combat is just kinda eh. If you have a fast swinging character like the assassin (which you start with) you kinda just win by spamming attack and that''s that. And you''re kinda encouraged to just spam attack due to the way the combo damage multiplier keeps stacking even if you miss, so you just keep ramping more and more damage as the enemy constantly blocks, up till you finally get them to stagger. I went to a', 'Very Positive', 86.36, 3.30, 0.58);
INSERT INTO reviews VALUES (36936, 1601970, 702, 'I traded a recipe to treat erectile dysfunction for a can of tuna, and 60 rubbles. 10/10\r\nFair warning: it is a really janky game.', 'A isometric version of stalker Chernobyl. It just had a little too much busy work for me to enjoy this.\n\nI note that the dev reached out to me.\n\nTo expand on my point. I don''t like farming and grinding for ingredients or crafting material. As I have gotten older my tolerance for that game loop as diminished quite considerably. \nIf that sort of thing doesn''t bother you then this game will be your jam and you should play it.\nIts just not for me.', 'Very Positive', 91.60, 32.50, 3.68);
INSERT INTO reviews VALUES (36938, 1602000, 125, 'Watching ConflictNerd playing the game, decided to buy the game. Looked like a game I would love to play like theme hospital when i was younger. So far so good. Still enjoying it.', ' It may be a good game. But I don''t like these forced hand holding starts.\n\nI would probably like the game if I could just start in sandbox and learn to play using my own brain, then the developers hand holding. (which has issues)\n\nGood luck with the game, but it''s not for someone who like to learn and master a game by playing.', 'Very Positive', 93.60, 15.43, 0.32);
INSERT INTO reviews VALUES (36939, 1602010, 2335, 'i lose every matchup against Elizabeth because anytime I glance at her armpits my mouth starts to drool pouring water on my controller bricking it until I lose', 'Ngl this game kinda ass, dropped it after 10 hours.', 'Very Positive', 86.21, 28.30, 1197.95);
INSERT INTO reviews VALUES (36941, 1602080, 698, 'This game was exactly what I was looking for, a FUN, engaging story with good game-play. I hope this game sold well as I would like a sequel, the world is cool and I love the characters. I hope others want a sequel too.', 'It''s actually really good at the start, it''s a very high quality action game with great environments, lots of skills, enemies with clear tells and different roles to make group fights interesting, and good boss fights that don''t drag on too long, basically everything you''d want out of it.\nThen it introduces mines.\n\nThe game has a mechanic where you activate a field around you in order to damage objects and certain enemies that you can''t hit without having that field active. This works well until', 'Very Positive', 80.80, 24.62, 9.37);
INSERT INTO reviews VALUES (36970, 1602560, 290, 'That''s an acid trip with a senior university project in arts.\n10 out of 10 stars', 'The animations are cool but the cut scenes take a VERY long time. Every time you die you have watch a rewind animation then the cut scene again before you can retry the puzzle. Some of the puzzles happen quick so you will die multiple times. This gets very tiresome very quickly.\nAdditionally, I managed to soft lock myself and had to restart an entire level. This only happened once but I thought it worth noting.', 'Very Positive', 81.38, 2.43, 2.18);
INSERT INTO reviews VALUES (36985, 1602930, 101, 'Pedro''s Adventures in Spanish is an adventure game for learning Spanish. In this game, you play as Pedro, an adventurer, who has to go on a quest to rescue a princess from an evil wizard, using the story and puzzles to hone your Spanish skills.\n\nThis game is designed for high beginner/ low intermediate Spanish learners, at the stage where you want to start incorporating some Spanish-only materials into your learning but still find materials for native speakers too difficult and/or intimidating. ', 'Was looking for language learning games, this one seems to be targeted just for that, and I''m at A1 (when click-through dialogues work better than live speech), but problem is the story''s writing looks subpar, and I feel like playing a generic point-and-click. And it lacks double captioning in 2 languages, which works exactly in cases when my vocabulary is lacking.\n\nAlso it''s not well made. It lacks a feature of saving words in personal dictionary. And travelling from one place to another - ther', 'Very Positive', 94.06, 6.85, 0.97);
INSERT INTO reviews VALUES (36990, 1603180, 959, 'I love a good Diggy Down game. Ever since Motherload way back in the Flash days. I''ve played a good couple of these and this is certainly the best after Motherload. The game play loop is simple but fun. The variety of excavator mechs is interesting. The upgrading process is a little flat but seeing the benefits is always appealing.\r\n\r\nLooking forward to the next one and I''ve got a bit more gameplay to squeeze out of this one till then.', 'I wish the dev best of luck on their next iteration of the game. This game is fun for the first couple hours but then the afk mine brings in more money than mining for ore. Basically it becomes afk in game for $$$, upgrade hella expensive mechs that dont transfer upgrades over, mine a little bit until you run out of bombs, deposit stuff very slowly, restock on bombs, fall for 1 minute, repeat. Motherload was fun because of risk, fuel economy, fall damage, lore, cool upgrades, cool graphics... th', 'Very Positive', 91.03, 35.43, 8.80);
INSERT INTO reviews VALUES (36998, 1603410, 145, 'A very cute, but short game.\n\n3 hours of gameplay + an hour or so to mop up the last achievements.\n\nVery cute and cozy, about learning to take a break while exploring an alien planet and gathering materials. \nI wish some of the post-game-content had more relevant during exploration phase. \nWhat''s the point of giving me pets and outfits NOW?', 'The only reason I am not recommending this game is because of 1 achievement - "Met Them."  This is supposed to be a chill exploration and quest game and for the most part it is.  I was enjoying it immensely and didn''t even really mind the grind to get enough money to get the expensive item achievement, but when it came to getting  the last achievement it was a totally random 1% chance that you would see this NPC when you walked into a certain area.  I had to use a guide to even find out where th', 'Overwhelmingly Positive', 95.17, 5.40, 7.85);
INSERT INTO reviews VALUES (36999, 1603420, 125, 'What started as a cheap game to try out with friends turned into an obsession. The combat is fun, the characters are compelling, and the jokes and story are endearing and comedic. I''m 75 hours into what I thought would be a 3 or 4 hour game, and I honestly don''t regret a second of it. Cannot recommend this enough.', 'really unfun and repetitive gameplay, absolutely despise it. not fun to play by yourself, or in a group. good art, but that''s all i really liked about it', 'Very Positive', 87.20, 79.63, 1.32);
INSERT INTO reviews VALUES (37010, 1603640, 510, 'Didn''t know solving puzzles would be this phenomenal! Shoutout to the devs for making this fun little game! Indie game studios have been releasing based games lately. Worth giving this series a play tbh.', 'It is a decent continuation of the franchise, with a few issues preventing me from giving it a honest thumbs up. The most glaring issue is the technical side- the game has no frame limiter or even at least a vsync option, so you''re stuck with your GPU going full tilt for no reason, spinning its fans, eating extra energy and heating up the room. Yes you can limit FPS through your GPU control panel, but that makes the game sorta choppy. It will report that it outputs 60 FPS, but will drop some fra', 'Very Positive', 88.43, 10.13, 10.50);
INSERT INTO reviews VALUES (37027, 1604000, 6902, 'I''ve never felt more seen by a game than when playing the Milk series, specifically this second game. The first is fine but it''s pretty short and was more of a proof of concept (though chances are if you''re looking to buy this you know that). \n\nI''ve seen people say that it''s just vacuous fluff and not what mental illness is like but after playing it and seeing most of the endings I''m fairly convinced those are healthy people speaking for mentally ill people because they somehow understand better', 'اللعبة ماتدعم اللغة العربية', 'Overwhelmingly Positive', 97.62, 2.78, 2.78);
INSERT INTO reviews VALUES (37029, 1604030, 50038, 'I lost my best friend before we even finished playing this game together. I can''t bring myself to launch the game to see our castle right now, but in the hopefully near future, I will. Just to remember him and all the fun we had gathering resources, and (sometimes) cheesing the harder bosses so we could get better loot out of it.\n\nI''ll remember to feed your horse too.\n\nI miss you man. Hope you''re casting your fave blood spells somewhere in the Beyond.', '25 December 2024\n--------------------------\ni would have said yes, but they completely removed the ability to change all the settings of the game, now i have to do some hacker stuff and open weird files in the bowels of the games files and manually change them with weird names and figures, its like they specifically said "hey, how can we make this game less user friendly?" what is the point in removing these settings from inside the game? why did you remove easy buttons and sliders to have me go', 'Very Positive', 89.92, 73.00, 365.93);
INSERT INTO reviews VALUES (37037, 1604240, 158, 'I uninstalled Baldurs Gate 3 to make room for 93,846 copies of this game.', 'good game but too old 1990s', 'Overwhelmingly Positive', 99.37, 10.62, 17.17);
INSERT INTO reviews VALUES (37067, 1605010, 182, 'Adorable Witch\n\nHas a total of 10 trading cards.', 'Not to sound like a perv, but when a game is tagged with "nudity" and "sexual content", it should probably have some... just sayin''.', 'Very Positive', 90.11, 6.78, 9.83);
INSERT INTO reviews VALUES (37076, 1605220, 6779, 'I stayed away from this for awhile based on the mediocre reviews, but within the first 20 minutes it was pretty obvious what the problem was...and it has nothing to do with the game.  It was really mis-marketed, because well, there''s really no way to market this game.  They''re selling it as an RTS, and people are expecting SC2 on Arrakis, but it is most definitely not that.  It''s best described as a very complex pausable real-time board game...and it was marketed wrong because it''s difficult to ', 'The whole "assassination is an instant win but we''re not going to explain how it works before every faction tries to assassinate you" bullshit is really fucking annoying. As long as it takes to play these types of games, these developers sure do love wasting players'' time by not telling us anything about how the most important and complicated mechanics work.\r\n\r\nAnd that'' where this game fails. It fails to respect players'' time when you can lose an entire campaign by not knowing the very awkward ', 'Mostly Positive', 79.44, 40.78, 84.47);
INSERT INTO reviews VALUES (37111, 1606180, 111, 'ENGLISH PLEASE', '先不提我短短几个小时遇到了十几二十多个BUG。游戏本身就过于无聊了，完全没有任何代入感。\n不明所以的任务系统，恶心复杂的UI，制作者完全不懂得什么叫减法，什么都要缝合进来。网游设计导致没有任何交互，就是个人形马桶刷，十分难受，甚至哪怕你刷完对话能变一下也做不到。', 'Mostly Positive', 72.97, 15.30, 7.23);
INSERT INTO reviews VALUES (37114, 1606280, 274, 'good aim trainer', 'Hentai Aim Trainer is an FPS game with adult content.\n\nBy adult content I mean, the girl cutouts used for target practice have breasts on them and they moan when you shoot them, a true classic. As far as the shooter experience go, the game isn''t that smooth and shooting (especially the sniper rifle) feels somewhat clunky. As a game intended to practice aiming, let''s say that''s not exactly adequate! Furthermore, the levels are pretty much all the default texture-less tiles/blocks. The game looks ', 'Very Positive', 91.61, 2.93, 0.08);
INSERT INTO reviews VALUES (37116, 1606340, 864, 'total warhammer 3 nintendo version but better lowkey\n\nYOU GUYS NEED TO SPONSOR REGGIE HE PUT ME AND TONS OF OTHER PEOPLE ON', 'Unfinished game. Has no tutorial.\n\nEven Age Of Empires came with a tutorial. Game too complex to figure out. Not everyone learns from reading a stephen-king sized book or watching someone else play it.', 'Very Positive', 89.58, 61.68, 0.10);
INSERT INTO reviews VALUES (37147, 1607130, 1034, 'Buy it bro its not sexual, its a boxing game if u play it right all the girls knock u out', 'Game was great. Narrator ruined it. Give option to turn off pls.', 'Very Positive', 81.72, 7.20, 14.07);
INSERT INTO reviews VALUES (37152, 1607200, 131, 'A heart shattering masterpiece of it''s own kind. \nA story that you won''t easily forget. \n\nThat is the story that awaits you.', 'I''m not sure if I read the same VN as the other readers.\n\nCase 1-3 is barely readable.\n\nThe main plot is all over the place, they keep on contradicting themselves. And put a tape to salvage the plot hoping readers wont notice it. Maybe chatgpt can generate a better story for aojashin\n\nPlot Rant:\n\n The  Im satisfied with my life disease  , it just doesn''t makes sense? Ok lets say its because of messing up with your genes but how will your genes know you are satisfied? And why does no one did rese', 'Overwhelmingly Positive', 96.18, 74.78, 53.35);
INSERT INTO reviews VALUES (37175, 1607670, 116, 'A really faithful recreation of the original from Apogee, I was so happy to see this get remade.  I hope the other Apogee games can get HD remakes like this!', 'I bought this game because I played it over 30 years ago and I liked the initiative of a remaster. However, the game is far too difficult to be enjoyable, So I cannot recommend this game.', 'Overwhelmingly Positive', 98.28, 26.02, 0.47);
INSERT INTO reviews VALUES (37176, 1607680, 1849, 'WARNING: THIS GAME MAY CAUSE INTENSE RAGE, RUINED RELATIONSHIPS, DESTROYED FRIENDSHIPS, RUIN YOUR SOCIAL LIFE, BURN YOUR BRAIN.\nCONTAINS: ADORABLE PENGUINS CLIMBING A MOUNTAIN SAID CLIMBING A MOUNTAIN IS VERY HARD. \nWE RECOMMEND STEALING BALLS FROM YOUNG CHILDREN TO CAUSE EXTREME SADNESS.\nPLAY IT. ITS FUN. PLAY AT YOUR OWN RISK', 'This game fucking sucks. I do not recomend this game to anyone because of its intense difficulty and my brother keeps punching me in the face AND TRYING TO HANG ME FROM THE CEILING NOW AND i DONt think our relationship is ever going to be the same ever again he wont stop punchoing me [please help me im bleeding out i dont know hwat to do please can someone call the police myaddres', 'Very Positive', 82.42, 5.37, 4.38);
INSERT INTO reviews VALUES (37193, 1608070, 3054, 'Beautiful remaster and an epic prequel. I loved this game from start to finish. The visuals are great and the story is plenty of fun. Some of the missions were kinda silly and tedious but otherwise it''s a really great game. I really enjoyed the combat system despite the randomness of the slot machine deal. Worth it for any Final Fantasy fan!', 'If you never played the original, without the nostalgia factor, this game is not worth your time even for free. Just watch the story playthrough on youtube for the lore, or play the original. \n\nIf you did play the original, the game is fine, it runs well, the graphics are a good upgrade, but use voice mods probably. I recommend this game purely on nostalgic value, otherwise do not waste your time on it, it does not stand on it''s own legs by any modern standards whatsoever.', 'Very Positive', 90.05, 86.02, 33.22);
INSERT INTO reviews VALUES (37201, 1608230, 2275, 'We liked it and played to the end in several sessions in sort of a couch-coop mode. The art was amazing. It can get a little bit nerve racking at times. If there''s one thing we could change about it, it''s that the run is a bit slow (and looks too casual sometimes). Mui is SO cute. Best character in the entire game. We recommend it, it was a very fun playthrough and we hope you enjoy!  (written by a 10 year old and a 50 year old father daughter team)', 'The game is absolutely beautiful and the sound design/music is very well done, however that''s about all I enjoyed about it. The platforming and puzzles are both pretty boring IMO. There is little to no challenge anywhere to be found in the first hour of playing. All puzzles are pretty much "direct your cute companion to stand here and/or perform this action so you can move to the next spot."\n\nI would say it''s a good game for someone not looking for a challenge and just wants to enjoy the world, ', 'Very Positive', 93.19, 7.20, 0.98);
INSERT INTO reviews VALUES (37204, 1608290, 579, 'an insanely good game that''s worth every cent. the $25 price makes me feel like i''m robbing the devs. the casual inclusion of nonbinary characters is one of the smallest yet most heartwarming parts to me; and in this space murder hellscape, i need the warmth i can get.\n\ni cannot recommend this game enough.', 'Gnosia just simply isn''t for me, while it started fairly strong, the gameplay loop became old for me pretty fast. It does however have a unique soundtrack, I don''t personally recommend the game but it''s music is a really fun listen.\n\nIf the prospect of single player among us really entices you however, go ahead and give the game a chance. It may not have been for me, but it has it''s audience.', 'Very Positive', 93.61, 58.53, 1.32);
INSERT INTO reviews VALUES (37208, 1608400, 506, 'I still end up with paint on my hands.\n', 'this game is for people that can paint. i forgot i cant paint :(. enthralling.', 'Overwhelmingly Positive', 96.05, 1.72, 0.23);
INSERT INTO reviews VALUES (37210, 1608450, 245, 'An absolute underappreciated gem that was very, very welcome when it was pointed out to me. Like many games these days I went in fully prepared for disappointment only to be completely struck by surprise. Hellslave is a strongly focused single player, single character RPG where the moment to moment gameplay is contriving multiple synergistic abilities for overwhelming combat advantages. This seeming imbalance is absolutely and utterly necessary however as your character will be fighting through ', 'I liked the Game until a virus was detected in the last update. That´s not acceptable for me. The developer don´t want to remove the update .He says there is no virus and the update is save. But why there is no new update without this problem???', 'Very Positive', 88.16, 13.25, 29.37);
INSERT INTO reviews VALUES (37212, 1608470, 142, 'WISH MORE PEOPLE PLAYED THIS GAME IS GUN', 'It''s not a bad game, but it''s very boring. Repetitive levels and a limited arsenal force players to rely on slow-motion mechanics to achieve the highest difficulty rating. The jumping and rolling mechanics feel clunky and unsatisfying.\nI''d rather Neon White.', 'Very Positive', 91.55, 9.03, 4.27);
INSERT INTO reviews VALUES (37220, 1608700, 504, 'Really fun game that incorporates rythm mechanic but kinda falls short because it becomes repetitive and adds little mechanics later on the game. Left it halfway through the story but I do believe it is a really nice game that attemps a fresh look to the bullet hell genre.', 'TL;DR: The game is promising, but there''s just nothing there, songs are forgettable, combat is repetitive and bland, the characters and looter aspect offer very shallow customization, and the level design goes against the very scoring system of the game. 3/10, don''t buy.\n\nThis game suffers from being an amazing concept with terrible execution, surface level stuff is pretty bad, characters, story, the world and most designs are very bland and boring, but the gameplay is just downright bad. A majo', 'Mostly Positive', 79.96, 8.77, 5.70);
INSERT INTO reviews VALUES (37239, 1609080, 1626, 'A brief yet thrilling horror game brimming with high-quality scares.', 'The game is just walking around and reading notes in a very restricted area, the process of unlocking new areas isn''t organic, sometimes you just walk back and forth in the same room, a few jump scares, not very interesting. I would not recommend this game under any circumstance. I don''t even know how this game is so heavy, it''s just 3 rooms and some notes.', 'Very Positive', 89.11, 1.92, 2.07);
INSERT INTO reviews VALUES (37245, 1609230, 2420, 'I used to smoke meth and this game is the more difficult of the two to put down. It is possibly the best game I have ever played. It replaced my psychiatric medication and I have formed a legitimate parasocial relationship with a cartoon. I''m not exactly sure what sort of blood magick rituals black tabby are doing, but I hope they never stop. Seriously, this game is incredible. This is my first steam review. I thought this game was going to be extremely whack but I snagged it after feeling as th', 'This game hasn''t had a new episode for 2 years, wtaf', 'Overwhelmingly Positive', 98.35, 34.30, 8.43);
INSERT INTO reviews VALUES (37264, 1609730, 410, 'its like cod zombies but better and ultrakill movement', 'i personally dont like this game because it was given up on so no new updates and also you can get trapped on gravestones easily sometimes and killed by low level ghosts even though you have good weapons\r\n', 'Very Positive', 90.98, 13.33, 8.10);
INSERT INTO reviews VALUES (37293, 1610440, 544, 'The game’s design and story structure are exceptional. I did notice a few typos, but given that the original language isn''t English, the translation is impressive. The tutorial, which lasts just over an hour, is thorough in covering both the controls and the lore, keeping the mystery alive and engaging. Overall, I’d rate this game a perfect 10/10. Well done BearBoneStudio <3', 'While I do think this is a good game, the endings were so bad and the mysteries not being answered left a sour taste in my mouth. Idk what happened but some story lines felt unfinished or that they didn''t finished which really angers me. I also despise what happens to the Jason in our head at the end of the game, like why did you do that, there was no reason or a point to do that, all you did was make me even more angry. Like I said this was a good game, if you are interested in this type of gam', 'Overwhelmingly Positive', 95.77, 8.32, 27.20);
INSERT INTO reviews VALUES (37295, 1610460, 312, 'penis', 'This is by far the worst Supercross game ever created by milestone. Supercross 6 gets a lot of hate but I can say with absolute certainty that 6 is infinitely better than this garbage. I always play these games on the advanced physics against realistic AI and not only are the physics and cornering some of the worst of any moto game period, but the AI are so insanely annoying as well. They get speed boosted when near the player and will always effortlessly ram you straight out of the way then pro', 'Mixed', 67.31, 74.02, 9.17);
INSERT INTO reviews VALUES (37296, 1610470, 381, 'Truly the dark souls of racing games. Do not play this to "relax" cause you will not be in a relaxed state during or after playing. It''s fun also challenging and difficult. It''s just one of those games where you have to spend some time learning the flow, how to control your bike and THEN you can have your fun.', 'Terrible physics, terrible graphics, zero fun.  There are dozens of better racing games available.', 'Mostly Positive', 78.22, 7.63, 0.53);
INSERT INTO reviews VALUES (37298, 1610520, 112, 'I completed the story as far as i can with minor inconvenience. I only have one problem with fog if a setting could be added to lower the thickness i think it would run alil better for me \nBesides that good game \n', 'Personally as a buyer from Day 1 and a content creator making the videos on the series i was hopeful. But last "major" update was in September and as of writing this it''s been 3 months with no news or anything. suggested big changes to improve game in their discord but still radio silence. We get ignored with no mod response, no updates to their supposed roadmap, and the last "major" update felt so half assed i gave up recording videos on it because it didn''t feel fun enough for me to do it. Gre', 'Mixed', 47.32, 12.12, 34.30);
INSERT INTO reviews VALUES (37334, 1611430, 144, 'Asian games can be different, the same as Asian horrors. This one is curious, but absolutely not scary. Irritating in pursue-moments, a bit vague in the story and unexpected in the ending. \r\nFew words about everything. \r\nThe game is not about fear or tension, or suspension. It is about how fast you can hide and how well do you now the game. Because sometimes you will need to die 5-10 times, to understand where you path will lead. Monsters hearing is too good, they are faster than you and if you ', 'All the stealth segments are garbage and the placement of the ghost is so awful in the exorcist part, get stuck in a loop of progress 1%, get spotted, forced to hide, get spotted, forced to hide, repeat, all in the same fucking area.\n\nsad that asian horror is so good yet this game is just painfully tedious, i cant be bothered to finish it after 5 hours of this back and forth pov switching game with horrid stealth segments that are just glorified trial and error with 0 thought, I hope the second ', 'Very Positive', 92.36, 8.15, 5.48);
INSERT INTO reviews VALUES (37338, 1611580, 221, '10/10 Amazing!\nRecently i had an unfortunate event happend irl that made it impossible for me to have aquariums right now \nwith this game i can aquascape and still kind of pursue my hobby thanks to this game :) the things you can do with this game are endless\nkeep updating the game you wil have me as a loyal player for sure!\nreally is the best aquarium simulator game :)\nkeep up the good work dev''s your really helping me with this game :)', 'Do not buy, game has been abandoned by the developer who sees no profit in continuing development.', 'Overwhelmingly Positive', 95.02, 16.03, 37.63);
INSERT INTO reviews VALUES (37340, 1611600, 6963, 'me watching the ai charge into my pre-positioned abrams + bradleys for the 5 billionth time (proof that eugen ai department is a single overworked 50 y/o who hasnt seen his family since european escalation)', 'You can zoom in on any spot on the map and hear enemy units even if you can''t see them. This means in multiplayer you can snipe any unit even if it''s idle (including infantry!). You will lose any sense of surprise because anybody can hear a helicopter or tank rush coming before you can even see it. \n\nIt is the same in Steel Division 2 so I assume it''s a game engine problem that they won''t fix. Some of the online community is pretty toxic about it calling it a feature and that you should just "ge', 'Very Positive', 82.91, 105.17, 567.53);
INSERT INTO reviews VALUES (37356, 1611910, 6730, 'I enjoyed this game very much. I usually buy a lot of games and get bored too quickly to finish it, but this one I sat through the whole campaign and love every moment. Best turn based game I played in years. Lots of replayability and customization. My first warhammer game and also first X-COM type turn based game. It has a steep learning curve, but once you learn how it works, you''ll feel proud to die for the emperor.', 'This game is incredibly frustrating.  Even on normal difficulty there is a mechanic that will spawn troops or give you some debuf every few turns.  If a world gets too infected reinforcement come almost every other turn.  It makes it incredibly monotonous  to progress through a map when you have to back track to kill some lone sniper that is out of range of your normal team.  If you do it perfectly, one round to back track, one round to stop the reinforcements, and one round to return to where y', 'Mostly Positive', 79.27, 140.70, 52.58);
INSERT INTO reviews VALUES (37376, 1612620, 328, 'I love this game, it sucks that the devs gave up on it, it has a ton of potential still. Its just another dungeon crawler but it has a really nice and unique skill tree that makes it worth playing, along with some end game you can grind for.', 'Abandoned.', 'Mostly Positive', 73.48, 48.85, 8.27);
INSERT INTO reviews VALUES (37379, 1613670, 140, 'Great game, however, the Pac-Man level is way too difficult. Like, hair pullingly difficult. And, on top of that, in reverse mode, the light should still shine foreword. Hopefully the developers will add these quality of life improvements at some point in the future.', 'I did enjoy the games artistic direction, the simple yet fun combat and the absurd dialogues and situations, but there''s just not enough content.\n\nThe trial and error nature of the game makes you die a lot of times, which would not be a problem if the checkpoints were well placed, but they''re terrible, forcing you to replay big chuncks over and over again, not to mention having to stop every single time to read pointless dialogues before starting your run.\n\nThe souless repetition takes away the ', 'Mostly Positive', 79.29, 11.08, 1.30);
INSERT INTO reviews VALUES (37386, 1618380, 474, 'After about 4hrs of beating my head against the wall, trying to learn how to play the game and actually getting past the first boss i basically turned the game into a point & click adventure with the enemies being Bags of Mana waiting to get in me and realizing at lv 6+ i prob could go infinite.\n\n\nSo yeah Great game, highly recommend', 'This game REQUIRES acceptance to a 20+ page Privacy Policy that primarily tells you why they are going to collect information from your computer, and why you can''t opt out. There was language about contacting the author (if you were in certain countries, such as the EU) but you either had to agree to data collection, or couldn''t play the game. There was a similarly-sized EULA as well - I didn''t count how many pages that was, but it seemed about the same length.\n\nI understand developers'' desire t', 'Very Positive', 93.04, 6.65, 0.08);
INSERT INTO reviews VALUES (37388, 1619230, 107, '★★★★☆\nFull Gameplay Walkthrough : https://youtu.be/QHky8Zc0RPc\nGameplay : 7.5/10\nArt/Graphics : 7.5/10\nMusic/Soundtrack : 7.5/10\nStory : 7.5/10\nGame Time : 1 - 2 Hours', 'I bought this game because I loved the feel about it, the design and the story. I also bought the game because most of the player feedback said that the puzzles are not that hard. So I (female 59 years) and my husband (73 years) sat there for long periods of time, tried to click whatever we could, and had no clue how to solve the puzzles. If you have very little to no experience with this kind of games (I usually play survival, simulator and city builder games) those puzzles are HARD. Also, I''m ', 'Very Positive', 94.39, 2.37, 1.67);
INSERT INTO reviews VALUES (37392, 1619540, 114, 'Awesome game! Or should I say: wholesome? The game leaves you with a warm, loving feeling. Also lots of humor. Often cheesy and dad jokes but still funny. About the adult content: this is a game you play for the story. The adult stuff is still great, imo, But not the selling point. Animations are few and short. Graphics are great, not superb. There are some 15-20 adult scenes. But only 7 or so go all the way till 4th base; it is not *that* sort of game where the story is just to get you from one', 'The graphics are poor, characters seem boring and cliché, and the story has such, for lack of a better term, rapey vibes. It''s an AVN, ok, but it feels disgusting whenever it''s not boring. ANd yeah, 19 minutes was all it took to never touch it again.', 'Mostly Positive', 78.95, 15.25, 0.32);
INSERT INTO reviews VALUES (37395, 1619570, 464, 'This is a sort of deckbuilder turn-based strategy game, where you are in a deadly race fighting opponents as you go towards the finish, swapping out parts of your car for new ones along the way. So a new engine replaces your old engine, which basically swaps out a subset of cards for new ones. Same with tires, weapons, and gadgets. So you are trying to build a decent deck to take on opponents as you race down a highway to a final boss encounter. You also collect scrap along the way that you can ', 'Bought on a sale and still cannot recommend this game.\r\n|its a fun concept RogueLike with a little replayability \r\nbut most choices are painfully bad so you end up with a similar build everytime\r\nAlso lots of Game Ruining bugs that are never going to be fixed\r\nin my 5 hours I''ve had 3 runs end in  a bug that forced me to restart\r\nDeveloper himself has said that there is no plans to work on the game anymore (look its in the discussion) \r\nso I doubt they will be fixed', 'Very Positive', 81.68, 51.23, 10.52);
INSERT INTO reviews VALUES (37402, 1619790, 127, 'This game is amazing, its clearly missing one HUGE thing. Multiplayer. If this game had multiplayer it would be an amazing game. Its crazy fun to play.', 'Woah, a review for this game in 2024? \nThe last update was in 2022, with radio silence from the dev since. It''s a fun couple of hours, but certainly not worth 20 USD. Take your money to a different early access fly-em-up. If you do buy Aggressor, know that it''s quite incomplete, and really only as fun as you can make it. Stay safe.', 'Mixed', 63.78, 11.78, 8.77);
INSERT INTO reviews VALUES (37426, 1620290, 187, 'good game for what it is, devs seems to have given up but fun over all.', 'Thera Bytes and Aerosoft seemed to have moved onto another project, leaving this game is a permanent state of EA.\n\nThere is a half finished game here, which I did enjoy for a short period of time. But there is still a lot of work that needs to be done to move this from current EA state to 1.0 release.\n\nBut due to a complete lack of communication and the upcoming release of another game, I have very little faith that this game will be completed.', 'Mixed', 68.45, 198.53, 30.73);
INSERT INTO reviews VALUES (37429, 1620340, 2226, 'who would win a fight a AAA developer with a 9 trillion dollar budget that cant make a game that doesnt suck or some jackass named dickie that makes ps2 games in 2024 i think i know the answer after playing this game', 'I genuinely used to love this game, my hours in it should prove that, but holy shit the last update for this game straight up ruined it. Dude added a court system for some reason that seems to be largely just RNG, you can lose titles and all of your money to court cases that you should never lose. It''s really disappointing when developers fuck up a game with poor additions, especially in this case since it was to drive up hype for his other game.', 'Overwhelmingly Positive', 95.42, 36.68, 102.82);
INSERT INTO reviews VALUES (37436, 1620520, 131, '0/10 i didn''t get to kiss corsic', 'I really tried to like this game, too love it and all... But over my playthrought, I saw over the nice art and music and found nothing worth liking. The best I can describe it is a character based story, without a story, like as if the whole plot was just an afterthought. A world you put bunch of models in, without a purpose and nothing noteworthy to tell. At the end of the game in epilouge, bunch of characters started to argue about the themes of the story, narrator just saying that it''s up to ', 'Very Positive', 94.66, 8.30, 7.78);
INSERT INTO reviews VALUES (37437, 1620540, 247, 'It''s kind of a pixel-art arcade-y FIFA.  It''s outrageously fun, and the production value is so much better than it needs to be.  Love the playful references to clubs and players.  Cannot recommend enough for a fun, casual soccer game.  And party tournaments FTW!!!', 'showed promise but not it.\nplay on easy, dont lose a game all season. \nplay on normal, dont win a game all season', 'Mostly Positive', 76.52, 5.50, 12.43);
INSERT INTO reviews VALUES (37443, 1620720, 152, 'Honestly, I didn’t have high expectations since I just stumbled upon this game while looking for something with a jazz theme because I love jazz. This game is a puzzle-based adventure! I think it’s a simple yet heartwarming game that gives players courage.', 'We all react differently to loss.\nIt was an interesting narrative, but ruined by uninteresting gameplay.\nNot enough narrative, the gameplay itself feels too much like padding for what would be an extremely short game otherwise. The narrative, and ultimately, music wasn’t inspiring enough to recommend a play through, even at the sale price.', 'Very Positive', 93.42, 1.40, 3.20);
INSERT INTO reviews VALUES (37455, 1621070, 3598, 'Started playing before the massive rework and found it to be enjoyable for a few hours. Balancing wasn''t the best along with loot being super abundant definitely ruined the survival aspect but I was having fun so who cares. Pretty obvious this was a asset flip but seeing how the dev is trying to make his/her own unique game for a cheap price I''m willing to look past it. I haven''t really touched it since the rework update as I want more time for the game to cook and give it a fair review then jum', 'Okay so I purchased this when it first came out and played a few hours, it felt extremely empty and just no substance at that time, however I really enjoy the premise and idea of the game. Cool vibe, so I thought id let it cook for awhile. That was in 2022, fast forward 2 years later and it says it gets consistent updates but I just don''t see it. There needs to be some sort of guidance for this initial quest, the map is pretty large and wandering aimlessly picking up my 23764th mask or pumpkin f', 'Mostly Positive', 78.93, 9.42, 6.28);
INSERT INTO reviews VALUES (37458, 1621140, 344, 'It is a cute, short game I enjoy. There is just something compelling about returning these fish to the flood waters; I guess that same thing as other fishing games.\n\nThat said, I accidentally hit "Q" on my 29th fish and was completely restarted. No idea why a restart quick key was included, but at least warn me before I accidentally hit it! So you be careful, dear reader, because no matter how short it does not feel nice to have wasted time.', 'Game is WAYYYYY too short. I understand I should have expected the game to be short given the price and the completion time being listed as "under 1 hour" but I was able to 100% the game in less than half a hour. I like the concept of the game, but overall felt the game was too short, even for it''s small price of $2.99.', 'Very Positive', 94.19, 0.98, 0.47);
INSERT INTO reviews VALUES (37464, 1621310, 345, 'If you plan to play this on the deck, you might want to reconsider it, the game seems to have a nasty habit of permafreezing on loading screens, potentially causing you to lose progress, about 50/50 chance usually, with some areas its even more likely\n\n\n\nAnyway, with that out of the way, it''s a pretty good game, though the ingame info could use some polish, as it has a tendency to send you to the wrong places for certain materials, like saying a certain boss drops silver crystals, when it doesn''', 'Sophie 1 is SO much better IMO. Really preferential to that battle system.', 'Very Positive', 91.59, 58.92, 58.30);
INSERT INTO reviews VALUES (37477, 1621690, 20182, 'I actually like this better than Minecraft for reasons I don''t fully understand yet. It seems perhaps more streamlined or less confusing. I''m playing this with my two kids, aged 7 and 9 and it is complex enough to keep me, a 40ish year old man entertained, but easy enough for small children to grasp. \r\n\r\nUnfortunately there is no split screen type co-op, but that is understandable imo because otherwise you''d be tied to the same area or the screen would be too small. The upside is this motivated ', 'I enjoyed the first 3-4 hours and beating the first 3 bosses however, the game quickly becomes repetitive and boring after that. \r\nThe gameplay loop doesn''t change or evolve, what I experienced in the first 3 hours was what I was doing for the rest of the game. You gather resources and mine ore to craft gear and progress through the various milestones, pretty standard survival mechanics. Some people like this grind, I personally find it boring. \r\n\r\nCombat is simplistic and quickly gets boring. T', 'Very Positive', 94.95, 14.35, 18.25);
INSERT INTO reviews VALUES (37479, 1621760, 341, 'This game is the spiritual successor of Decision 3 (better, in many aspects). If you want to re-live Decision 2 (as in, liberating half of the game alone with overwhelming firepower, infinite ammo and quickly evolvable guns), this is not the game for you, you will need a good squad to not suffer with overwhelming amount of zombies. \nI like the game especially if I measure it against Decision 3 though it is really a fusion between the two games, just as much relying on base-building as free-roami', 'It pains me to say this, ''cause I loved the original series of Decision, Every new game was a huge improvement on the older one, but this? this game is just a mess, the gameplay is slow and repetetive, the survivor and camp management is barebone on many aspect, and confusing in other, the combact is primitive, the graphic is meh,the class system is bad, most classes are useless, it was handled better in the The decision 3 installment. also you can''t choose your character name, It would have mad', 'Mostly Positive', 74.49, 42.78, 50.18);
INSERT INTO reviews VALUES (37490, 1621990, 134, 'A bit rough around the edges but all in all worth the money, especially because its constantly on sale.', 'Gues i didnt see the Souls-like tag. Get it on sale. Not very good combat and hard to remember where you went.', 'Mostly Positive', 74.63, 44.90, 5.67);
INSERT INTO reviews VALUES (37527, 1622770, 652, 'Relaxing and clever puzzle game that consists of 60 bite-sized escape room like scenarios with each having a different theme and gimmick. Most levels seemed easy & casual (5-15min solve time), with a few exceptions of the more difficult puzzles you face. Each level contains two gems and one scroll to collect with most being in plane sight. The game can be completed between 6 to 10hr and has a level selection menu in-case you need to go back to find some of your missing collectibles. Doors: Parad', 'This is a very pretty game with a fun idea, but the "puzzles" are not very good. They either consist of clicking on everything you can see to find the thing you need or are pretty easy. There are a few good puzzles, and the animations are fun, but it just isn''t good enough to recommend as a puzzle game.', 'Very Positive', 91.41, 7.27, 4.60);
INSERT INTO reviews VALUES (37528, 1622800, 294, 'Fun little game for level editor lovers such as myself.\nThink Super Mario Maker except for the dungeon crawler genre.\nAlthough, if you''re more of a player than a maker, I don''t believe it''s worth it- but, if you''re into building, give it a go!', 'This game had potential. Unfortunately, it was abandoned without any notice and is severely lacking in content. Play Quest Master instead, it has regular updates and the demo alone has more content than this game.', 'Very Positive', 83.67, 15.13, 8.57);
INSERT INTO reviews VALUES (37533, 1622900, 2231, 'This is a great mod off the Stellaris game. Better than the original, in my opinion. It''s a tragic shame that they aren''t still developing more of it.', 'This is EXACTLY the reason Steam changed its Publishing Policy, and THANK GOD!! This game is nothing more than a cash grab against its loyal fanbase and they should be suable! How many people purchased the title SOLELY on the reputation of Paradox (raises hand) and feel the burn (raises hand). I would have played this game non-stop, growing up as an Original Star Trek/Star Wars Fan, and they just ripped my heart out with nothing more than a "Thanks for your money sucker". I hope they go bankrupt', 'Mostly Negative', 39.89, 426.87, 1.72);
INSERT INTO reviews VALUES (37534, 1622910, 4035, 'The only unrealistic part is that your flathead screwdriver doesn''t slip out of screws. Otherwise 10/10', 'Still Wakes the Deep was quite a disappointment for me. It features on-the-rail, strictly linear gameplay, not too dissimilar from the "Houses of Horrors" in Theme Parks - you are being carried forward in a little car while being subjected to jumpscares - because that''s all there is to it. The monsters are straight-up rip-offs from the old movie "The Thing". On the surface, it looks Lovecraftian, but there is no mystery, no real exploration, no discovery, no interesting characters, and a paper-t', 'Very Positive', 90.36, 11.18, 6.57);
INSERT INTO reviews VALUES (37541, 1623070, 684, 'Good remake. Unfortunately the developers abandoned it completely. There are many obvious bugs and issues that seem simple to fix.\r\n\r\nStill, quite fun and looks good.', ' This is a single player game and the AI is atrocious. The only thing it can do effectively is send out settlers. It''s worse than the AI in the original. A 30 year old game. \n\n  Spellcasting is broken. The AI only actually uses a few spells. The rest are not even implemented. Diplomacy is broken. If one AI cancels a treaty, all of the other AI''s act as if the player broke it. Once you have an army of 5 or 6 units, you can take over every AI city. Even late game, they will be defended by 1 or 2 s', 'Mostly Positive', 70.91, 690.93, 23.10);
INSERT INTO reviews VALUES (37546, 1623210, 450, 'Game is fun, with very in-depth character creator and beautiful pixel graphics. Looking forward to the sequel being fully out with the straight marriage mechanics. Keep up the good work dev!', 'Mediocre game from a homophobic developer. Don''t waste your time or money.', 'Mixed', 69.56, 5.68, 1.42);
INSERT INTO reviews VALUES (37570, 1623730, 136695, 'Nintendo is jealous they can''t produce a solid 60fps experience with little to no bugs and frame rate drops with a team 100x larger than palwords dev team. And no its not a Switch hardware issue since TOTK runs very well with little framerate drops and bugs for such a massive open world game on their own console LOL\n\nSupport Palworld and support competitive titles that will push Game Freak to not release trash!', 'I''ve played hundreds of hours of Palworld and genuinely enjoyed this game, but with the newest update and EULA, I cannot recommend it. The Monitoring section of the new EULA states: "We may actively monitor use of the Services, both on our own servers and on your computer or device, for a wide variety of different purposes, including preventing cheating and hacking, reducing toxic user behavior, and improving the Services. We may monitor and collect data regarding the use of the Services in acco', 'Overwhelmingly Positive', 95.34, 14.65, 591.82);
INSERT INTO reviews VALUES (37578, 1623940, 2607, 'I booted this up expecting a cute little forest romp. Five minutes later, I’m emotionally attached to a child and being hunted by something that looks like a troll crossed with my sleep paralysis demon.\n\nVisually? Gorgeous. Like a Studio Ghibli film fell into a vat of Scandinavian trauma.\nSoundtrack? Haunting. Like lullabies sung by a ghost who regrets their life choices.\nGameplay? Mostly me running, hiding, and whispering “no no no nope nope nope” out loud.\n\nThe story is surprisingly touching. ', 'i''m putting not recommended but it''s sort of mixed. \r\n\r\nthe actual story and mythology were interesting and the graphics are good, my issue is with the actual gameplay. throughout the game the controls are either too sensitive or not sensitive enough, and a lot of the deaths i had were due to the character not being lined up by like millimeters. it was super frustrating. also the fact that some of the game is supposed to be hinted with sounds, so for people who don''t have headphones or have hear', 'Very Positive', 94.71, 28.47, 6.27);
INSERT INTO reviews VALUES (37602, 1624540, 3433, 'It''s a good game but it would be way better if there was a sandbox mode where you could use any scenes and characters you wanted.', 'A very clever game with thoughtful and fun puzzles, but let down by being too short. I had completed the core game and was playing updated content after only about an hour of playtime. There is no replay value and the content provided is too little.', 'Very Positive', 85.90, 3.45, 2.08);
INSERT INTO reviews VALUES (37700, 1626350, 101, 'Pekoe is a cute and cozy game, they made it quite immersive as far as tea brewing goes and I like how many combinations you can try, and you have a lot of freedom to make what you want while still fulfilling the special requests the customers give you. I just wish there was more to do sometimes; I find myself tabbing out frequently just waiting for customers to appear, or not really finding much to do to interact with the villagers despite having a friendship system. You just talk to them for a ', 'I got this game because I wanted a cozy making cats tea game and it was ok to start with, but it''s getting really frustrating and not worth the 17$ I paid for it. It''s ok making tea at the beginning although a little simple, but when it starts to get more "complex" it also gets confusing. You will have cats asking you for seasonal tea (they don''t teach you about that before hand) so I made a tea with typically spring ingredients, WRONG. At a later time at one of their shops they asked me to make', 'Very Positive', 89.11, 9.72, 9.98);
INSERT INTO reviews VALUES (37716, 1626640, 355, 'Gamer Girls : eSports SEX is definitely my favorite game of all time. The story is very in-depth and emotional, and it really made me cry. Recommended for sure if you are into romantic drama.\n\nNo, I didn''t receive this for free and I''ve purchased this game with welfare money.\n', 'This game is full of bugs.The design is bad and inconsistent.You cannot even lose in it,the game will just act like you won and go to the next "level".\nTo get the last achievement you have to use a patch.\nThe OST is epic,though.', 'Mixed', 65.92, 2.07, 1.62);
INSERT INTO reviews VALUES (37743, 1627350, 752, 'Absolutely stunning. You basically play as a data-entry employee, which means being a fast typist is extremely useful, but put through the lens of a horror game with meta elements. I don''t want to give too much away but there''s a ton of mindfuckery involved and so far I''ve only got one ending out of some number the game doesn''t tell you, but I''ll be going for all of them. It''s not a super long experience but with all of the paths you can take, it''s the perfect length for multiple playthroughs. I', 'Just finished the game. What actually happened? $15 dollars for this? And it has overwhelmingly positive reviews? Now that is spooky.\n\nThis game is a psychological horror where NOTHING actually happens! Your screen cracks a bit, and goes static-y at times. There are scary ambient sounds, that''s it. This game is a HARD pass if you are on the fence. \n\nThere are tons of better horror games for cheaper.', 'Overwhelmingly Positive', 96.41, 10.13, 2.67);
INSERT INTO reviews VALUES (37757, 1627570, 824, 'It’s such a cool concept, but it’s a chore to play. The amount of text and constant gamplay interruptions is really messing with me. I really want to like it, but I might need to put it down for some time and get back at a later point. Cause right now, I’m just not having a good time with it. \n\nI’m recommending it, cause I know there’s an audience for it and the art style, specifically when you’re in the book is incredible. We need and should support more weird and interesting games like this, i', 'Great concept and beautiful artwork. But this game doesn''t let you do anything on your own. It''s 3 steps - dialog - 3 steps - dialog - 3 steps - dialog. The game does very seldom let you explore and find out what to do next, it just plainly shows you where to go, and then doesn''t let your do anything until you''ve done it. You are taken on a tour of a beautiful world that you''ll never get to enjoy.\n\nI can''t recommend this game, sorry.', 'Very Positive', 82.28, 2.78, 6.67);
INSERT INTO reviews VALUES (37762, 1627680, 110, 'Came for the boobs, stayed for the troops', '玩不了一进去就卡着', 'Very Positive', 85.45, 30.02, 0.42);
INSERT INTO reviews VALUES (37764, 1627720, 19564, 'Dark souls 3 but instead of Ashen one it''s an ex k pop idol and instead of monsters we fight sex dolls and furies. Awesome game 10/10.', 'The clunkiest souls-like I have ever played.  World building seems cool, weapons system seems like it has potential, but man it is just sooooooooooooooo slow and clunky that mechanically I''m just beyond bored, especially after playing something like First Berserker Khazan. Things just feel super unresponsive and everything you do has a billion frames of recovery.  Every enemy attack animation is a spring-loaded wind up requiring internal timing rather than visual reaction, with tons of awful tra', 'Very Positive', 93.52, 23.90, 54.58);
INSERT INTO reviews VALUES (37771, 1627850, 374, 'please update new map', 'dogshit', 'Very Positive', 87.17, 8.85, 0.70);
INSERT INTO reviews VALUES (37773, 1627870, 205, 'I''ve already made 4 songs and i''m in love. I''ve always enjoyed musical "toys" like elektroplankton on the ds etc\nI can see myself playing this for many months to come!', 'It''s cute, but at no point did I make anything worth listening to.', 'Overwhelmingly Positive', 96.59, 2.55, 0.22);
INSERT INTO reviews VALUES (37774, 1627890, 168, 'One of my recent favorite roguelite for sure! Combat is super nice, stacking items works well and there is nice amount of metaprogression (not grindy at all).\n\nHighly recommended. My other favorites from the genre are Enter the gungeon, Caveblazers and Noita.', 'Not terrible, not great.\n\nPlays like an average action rogue-lite, but it doesn''t do anything new or interesting. The options for Melee and ranged Weapons are neat, but throwing away your current weapon is way to prominent. It''s hard to tell if you got hit and your health bar is pretty small. \n\nThe moment-to-moment gameplay doesn''t make me feel smart for planing a good attack or powerful for beating lots of enemies. The level generations works, but doesn''t look like anything. It''s all just... me', 'Very Positive', 92.86, 22.62, 1.83);
INSERT INTO reviews VALUES (37780, 1628130, 281, 'Personally i felt more relaxed playing this game rather than Ten Dates or Five Dates even though comparing them is like comparing apples to peaches. Here you have to conduct an investigation among your family members  during an online family meet with timer running out and find out who poisoned your Uncle. I failed on my first attempt. Will try to replay. It is a difficult game where you have to investigate with or without arousing suspicion.\n\nadd - the game is oodles of fun, it involves choosin', 'I''m really sorry, I wanted to like this game so much. But I just can''t. I decided to buy and try it because I already tried a lot of FMV games and in the describtion it was said ''it''s one of the best realsed fmv game sin the year''.\n\nBut... It wasn''t a detective game AT ALL. In fact, if you just picked totaaaal random answers everywhere and then the next round you chose the opposite one, you can quickly gather every evidence. And there is no logic between the answers! It''s not like you choose to ', 'Mixed', 69.75, 7.67, 2.28);
INSERT INTO reviews VALUES (37816, 1629200, 177, 'Well its a Diablo 2 clone, and I''ll say that its deeper than expected. So if you get it on sale, then it''ll be worth it.\r\n\r\nIf you want something more modern like PoE/D4, then you won''t enjoy it.', 'I played Anima for long on my phone at this point and I don''t get why would you release older version for the PC. So many things were fixed in later versions for the phone.', 'Mixed', 64.41, 24.52, 11.20);
INSERT INTO reviews VALUES (37828, 1629520, 7734, 'this game is relaxing but I personally wish death on whoever decided the box level at the end of chapter 3 was a fun and relaxing puzzle. I hope you never see the light of heaven. I hate you.', 'The artstyle is lovely and the gameplay is somewhat smooth, though overall it was more tedious than relaxing at times. Items have to be locked into place for it to register as solved and some solutions to puzzles are confusing. The cat grabbing the items was just annoying. Concepts of puzzles are repeated often and - after replaying this game in one sitting - there isn''t that much content.\nIf you are an achievement hunter, be aware that you need both paid DLCs and need to play the game a certain', 'Very Positive', 92.41, 3.78, 8.53);
INSERT INTO reviews VALUES (37829, 1629530, 1428, 'id give this game a 10/10 but he didn''t put the credits actually controllable in the game despite making a car segment, a flying segment, mech boss, in depth momentum mechanics, functional wall running, around 40 minutes of cutscenes and very impressive levels that actively kept me engaged. \n\n9.9/10', 'no its not as good as a good sonic game. the main issues r it likes the sonic werehig mechanics, and jumping just feels off, also alot of tewrrain like roofs and slight slants r bugged physics wise they slow u to a crawl and u just drop down often to ur death. also alot of bugs in the maps, not enough debugging. boss fights hgave not felt good at all....werehog fights felt better than this. the other issue is homing ansd ground pound...pound doesnt dmg enemies it feels bad....homing like changes', 'Overwhelmingly Positive', 96.85, 5.65, 0.97);
INSERT INTO reviews VALUES (37843, 1629830, 149, 'If Stardew Valley and Pokémon Legends: Arceus combined to make a cute farming game with tones of new creatures to befriend and research along the way! This early access game has lots to do and explore already, so I can''t wait to see the final product!', 'While it starts out super fun and I honestly had a blast. I might try more slowly; I guess to play the game. It''s So much WORK! In Spring, it''s not so bad. In Summer it starts to ramp up but if you can manage to get some sprinklers and an upgraded watering can, you can manage; just don''t expect to work on fishing, mining and friendships much too. But in Autumn; it''s a NIGHTMARE! Imagine the game tells you nothing of Acidic soil! In order to get it; you need a crystal, found only in the mines. Li', 'Very Positive', 93.96, 55.93, 49.43);
INSERT INTO reviews VALUES (37851, 1630110, 274, 'It''s exactly like the others described, a PS2 game in somewhat modern graphics. Once you stop caring about the type of game its not, you will definitely enjoy the game. But I cannot recommend the game at full price. Get it on 80% sale and it''s well worth for that price.', 'Boring brain dead garbage, but with enough flashy lighting to appeal to the usual morons.', 'Mostly Positive', 79.56, 7.55, 0.45);
INSERT INTO reviews VALUES (37871, 1630590, 234, 'I spent 145 hours. Yup. 145 Hours. Process that real quick. Along with that, I PAID for this game.', 'Uses 90% of the GPU to crypto mine or something there is no way that the game itself needs that much.', 'Very Positive', 90.17, 145.92, 1.03);
INSERT INTO reviews VALUES (37885, 1630920, 107, 'https://steamcommunity.com/sharedfiles/filedetails/?id=2833348306\nhttps://steamcommunity.com/sharedfiles/filedetails/?id=2833457511\nhttps://steamcommunity.com/sharedfiles/filedetails/?id=2613193604', 'I love this game but sadly i cant recommend it since it has a game breaking bug half way that wont let you proceed the game.\nI really hope this will be fixed.\n\nTranslated in russian i the hope the game developer sees this.\n\nУважаемый разработчик геймеров, пожалуйста, исправьте ошибку, приводящую к поломке игры с помощью ключа от гаража. Заранее спасибо.', 'Very Positive', 90.65, 2.78, 2.02);
INSERT INTO reviews VALUES (37913, 1631470, 974, 'I got the game, played for 20 minutes, got insulted by a very rude villager when I introduced myself, and I suddenly felt 11 and playing Animal Crossing for the first time again. 10/10!', 'I will not be supporting a game that thinks adding pronouns to their game is a good idea.', 'Overwhelmingly Positive', 96.10, 5.10, 0.10);
INSERT INTO reviews VALUES (37962, 1632490, 398, 'Great learning game! But definitely need more content.\r\n\r\nAlso, I would like a feature where you can increase your movement speed. Because moving around gets tedious pretty quickly because the movement speed is not that fast.', 'I think whats sad about this is how good this could be. Its a vocab builder more than anything that will teach you individual words if you''re willing to repeat the same actions over and over. I am sure people would buy DLC if more content was added, or it could be expanded into the subway or the different stores. I would certainly pay more for it. Its a good looking game with a lot of charm but it will not improve your Japanese, at its core, its playable flash cards. That being said, I still lik', 'Very Positive', 92.21, 7.22, 1.12);
INSERT INTO reviews VALUES (38005, 1633370, 273, 'Bomber crew, but you''re in a PT boat during the Guadalcanal campaign, and surprise! it''s also basically a bullet hell - you better be good at dodging 127mm if you want to succeed!\n\nDespite the name, it''s not that fussy about crew management. Crew have traits and skills, but they''re not restricted to one skill and can level multiple different skills at the same time. They can also do some tasks automatically; Loaders grab ammo and feed guns, repairmen grab parts and fix damage, etc, all without n', 'The game seems to be headed in the wrong direction for me. Early on, it was a fun PT boat captain experience. It has now reached a point in which you are required to do nothing but defend bases, as the AI outnumbers your allies and is overly aggressive. Your campaign will end in a week or two if you attempt to behave as a PT boat captain, rather than defender of the isles. In my most recent attempt, I was on patrol killing subs in early game (which is what the devs have suggested we do), and wat', 'Very Positive', 87.18, 76.70, 58.87);
INSERT INTO reviews VALUES (38029, 1634150, 1586, 'Let''s paint the finest scenery. Shall we, Amber?\n\nThis game has a story so good that even though I got it for free on epic games, I had to go buy it on steam to show my support.\n\nAlso, it''s a nice touch that it''s free there on January 23rd, it''s very fitting. If you are seeing this review before January 30th, 2025 go get it for free now!', 'The game has a nice story, nice graphics and nice music. The cat was lovely.\nBut while I wished my complains stopped at the price being a bit high for a game so short and repetitive, something has to be said :\n\nTHE BUG HAS TO BE FIXED\nIf you played the game you know which one.\nNot only it ruins the relaxing atmosphere of the game, but having the devs refusing to fix it and actually blaming either the gamers'' systems or their ''inability to just sit and enjoy'' (???) was a big no no', 'Very Positive', 93.76, 0.08, 1.68);
INSERT INTO reviews VALUES (38046, 1635450, 1712, 'This game is a real treat for people who love animal crossing and survival games c:\nI plan on buying copies for my family.\n\nReading the comments you only see downvotes about PvP play and servers, but there''s PvE servers, and you can host your own. There are hostile NPCs to kill if you do not want to participate in pvp. The game is still unforgiving and if you die in PvE someone can loot your stuff.', 'this game was FUN until it just wasnt . what cause it ? it was the many different ways that people were cheating . during offline raids it was thought that people would simply stay online all night putting in work taking over bases but that was wrong . people someway somehow were having offline bots running for them raiding and destroying bases for pettiness . offline bots that looked like real players even though they were NOT real people . To make things worse we had developers going into your', 'Mixed', 65.01, 16.97, 847.40);
INSERT INTO reviews VALUES (38051, 1637320, 8803, 'When I originally bought it I played it for a bit, unlocked all the domes, all the gadgets, nearly unlocked all the pets (?), saw nearly all the random world spawns and it was all over. All within <15 hours. It was a good game but I didn''t go out of my way to write a positive review. However one day a open beta popped up. Massive content update for a grand total of free. I love you guys, keep it up. Hope you add multiplayer you were prototyping at some point!', 'It checks a lot of boxes, and it can be good, but it''s not. It''s a roguelike where the first half of every run is a boring slog.\n\nImagine if in Minecraft your game would restart every 30 minutes or so, and each time it did, you moved at a snail''s pace, your inventory was only 3 slots, you didn''t have a pickaxe, and the workbench + combat portion of the game were always at your base, so you have to slowly backtrack with your 3 blocks multiple times to work towards marginally upgrading 1 specific ', 'Very Positive', 93.10, 23.20, 5.58);
INSERT INTO reviews VALUES (38054, 1640300, 528, 'Amazing game, fun gun play, cool weapons and magic to combine and use, i absolutley loved the first Project Warlock, im pleased to see that levels are bigger and allow you to explore a more open space in project warlock 2, if you love games like DOOM, Quake or Blood i highly recommend Project Warlock 2 and the first game as well, im also happy to see the game has been getting more updates along with the new chapters as well, the only thing that has annoyed me in the past was randomly losing save', 'secret hunting in this is miserable compared to the first game\n\nputting metaprogession things behind secrets means they aren''t secrets anymore but puzzles', 'Mostly Positive', 75.57, 11.73, 1.03);
INSERT INTO reviews VALUES (38060, 1641960, 3850, 'There is 1 massive difference between this game and other surival games that make it so awesome, the whole game is designed around the airship, your own massive flying mobile base, this means you always take all your storage and all your crafting benches with you at all times, making this whole genre around a billion times more fun.\n\nThis mobile base makes me wish all survival games would have something similar, the biggest downside of Valheim if you ask me is having to constantly travel back to', 'Has a fan of survival craft games, i trully wanted to give this game a positive review, but even with bugs aside, i just cant\n\nthe idea of having a mobile base that you fly around and transform as you progress is really appealing, and they hit it right on the mark on that front. The problem with this game is its progression. You need to jump from outpost to outpost, collecting resources, upgrades and blueprints. And there are a few different types of outposts, like a communications outpost, wind', 'Very Positive', 81.84, 12.18, 16.73);
INSERT INTO reviews VALUES (38061, 1642220, 291, 'A one-page hidden object game.', 'It''s a nice game, but too short.', 'Very Positive', 94.85, 0.27, 0.42);
INSERT INTO reviews VALUES (38064, 1643310, 1023, 'Feels like playing modern Dungeon Keeper and it''s pretty nice.\nI don''t really mind that it''s goofy, might be a downside for other people and it''s fair.\nUnits and spells feel good, campaign eases you into new tech at a comfortable pace.\n\nMy only complaint so far is that the Attack command on enemy units appear the same as a movement command, so even tho  I give an attack command and it''s successful, because in other games it appears differently (like a red circle around attacked units) it often m', 'Get Dungeons 3, I really want to like this game but between annoying level design, less punchy humour and reworked mechanics which detract from previous titles, if you want to play a game from the dungeon series, play 3.', 'Very Positive', 86.71, 6.25, 23.18);
INSERT INTO reviews VALUES (38065, 1643320, 36593, 'My favorite part is this really considerate feature where if the game feels like you could use a break, it will just crash directly to desktop for you, like a bartender cutting you off.', 'This game is good, aside from one MASSIVE issue. And 1 smaller one. First the smaller one, weapon customization/ modding. In the first game there was a large branching tree of upgrades for each gun that would take awhile to max out. I maxed out my ak74s tiny upgrade tree in the first 2 hours in this game.  Also would have liked to see an expansive attachment system, but it''s pretty bare bones. \n\nBut the real issue is unacceptable. A life 2.0 is a fat fucking lie. There is no life to this game. T', 'Mostly Positive', 78.17, 7.80, 31.07);
INSERT INTO reviews VALUES (38066, 1644320, 875, 'Everything I hoped for.\r\nStarted playing at 11pm, next time I noticed the clock was 2am.\r\nNext time I noticed the clock was 3:30 am. The next time after was 5:30. I stopped at 6:30.', '5 hours and I never got the game to actually allow a reasonable build that I wanted.  Manual signals mode is broken.  Trains pretend the signals arent there and wait anyways.  Trains move against one way signals and then teleport back to the station.  Trains wait forever at a station even with a dozen spacer signals between them and the train in front of them.  Should be ashamed you released this game in this state.  Last $ you will ever get from me Kalypso.', 'Mostly Positive', 74.86, 13.25, 5.38);
INSERT INTO reviews VALUES (38068, 1644840, 112, 'This deceptively simple tile-swapping puzzler can get really fiendish in its later stages. Thankfully it''s also lenient on how many times you move the tiles around. With an adorable, slightly animated, cat-themed overlay, it''s a fun way to simultaneously relax and give those brain muscles a thorough workout. My only complaint would be that there''s just one looping music track for the whole game, but you can easily mute it.', 'I found this game tedious and slogged through it. I enjoy difficult puzzle games, but not when the difficulty merely comes from overly big or complex levels. Not to mention that this game is closer to a jigsaw than any kind of interesting logic puzzle, so it''s not like you get any deep insights from solving one of the puzzles. You just finish the outer pieces, then search the inner tiles for whatever specific tile you need.', 'Overwhelmingly Positive', 96.43, 5.60, 2.33);
INSERT INTO reviews VALUES (38069, 1644940, 2062, 'As a fisheries biologist currently attaining a master''s in the field, these types of games really mean a lot to me. It can be extremely difficult getting people to care about the environment through science alone. The current and general apathy towards our natural systems seems to be weirdly rising and is disheartening. This game is super cute and fun with a simple and direct message - protect and respect nature. I''d recommend this game at any price. Always remember that what we currently have i', 'its just a walking sim but instead of walking u swim. 90% of the game is spent going back and forth. and its even more annoying when u make garbage and goop respawn. i already have to swim forever now i need to waste more time cleaning areas ive already cleaned. add some mobility and it will be kinda maybe alright', 'Overwhelmingly Positive', 98.55, 7.97, 2.45);
INSERT INTO reviews VALUES (38074, 1646850, 2736, 'Please note : This is an Early Access game, not the final product, and it doesn’t feel like one. There’s still work to be done, but I’m reviewing what’s been accomplished so far.\n\nI played the highly anticipated AAA game called Starfield by Bethesda, created by a 500-person team tasked with delivering a space game that was supposed to give us everything we wanted and more from a rpg set in space... and when I compare it to SpaceBourne 2...an indie game made by one guy (with some help here and th', 'Videos look great, but game is overcomplicated, poorly tutorialized, and extremely difficult to control.\nUI & interaction leave very much to be desired.\nMission design, from what little I''ve seen, is nice, and this game could be fun, but I don''t see myself ever getting past the UI & controls unless the whole thing is rebuilt.\n', 'Mostly Positive', 78.29, 63.35, 2.62);
INSERT INTO reviews VALUES (38076, 1647550, 554, 'Those Gucci pins were fake I''m getting my ass beat by frogs', 'This really is rather dreadful, and I don''t think I can continue. Characters are unbearably cringe. Main story is barely moving. Quests revolve around mundane stuff like asking people what they think about curry. Combat is incredibly repetitive and grindy. Just a few enemy types you fight over and over and success is tied to level and not skill. Combat itself is just mashing a few buttons, waiting for a cooldown and mashing them some more. Half the gameplay outside of combat is running in circle', 'Very Positive', 92.06, 45.82, 12.18);
INSERT INTO reviews VALUES (38077, 1648390, 1229, '*While i am a gay little mantis shrimp, I did still enjoy this game to the highest degree, my soft little mantis claws were able to use the controls seamlessly, and i do believe that i ranked higher than the straight mantis shrimp of similar builds. Overall, I would give this game a 6 out of 8 stars on the  basis of inclusivity and accessibility to our clawed kind', 'for a game called scooterflow you would expect some fluidity and flow during gameplay, this is not the case.... super hard to get transition and link tricks in a line. game is a waist of money tbh.', 'Very Positive', 94.71, 131.70, 29.40);
INSERT INTO reviews VALUES (38080, 1649240, 3776, 'After 40 hours and finally making it to the 5th biome, I''ve decided this is my favorite game Sony has published since Bloodbourne.  Unique take on the Rogue-like genre due to blending strong production values with a gameplay loop you''d normally find from the Indie scene.  I took me awhile to learn to be aggressive taking risks in terms of pickups but once I did, the game clicked.  Movement and gun-play feel good.  There''s a nice variance in weapons.  \r\n\r\nReturnal tells an interesting story while', 'Didn''t authorise nor was informed that the game would automatically install Epic Games Spyware on my PC when I bought the game.', 'Very Positive', 81.81, 42.45, 0.20);
INSERT INTO reviews VALUES (38082, 1649740, 143, 'Hunt the Night is a diamond. Not only is this game gorgeous, but for it''s art style and combat, it feels refreshing. The world breaths character. No two places feel the same and the horde of secret places hidden around the game is really exciting when you stumble upon them. I''d love to forget that I played this game, just to experience it again.\n\nHowever, even diamonds can have their imperfections, and for a game that I hold in such a high regard, it has a few hard-to-overlook flaws. Despite the', 'I finished the introductory dungeons and bosses, and the combat''s been pretty fun. Now I have no idea where to go. Characters in the game say to me "If you''re lost, go to the Court of the Insomnus," "the Court of the Insomnus will guide you." "check out the Court of the Insomnus."  Well GUESS WHAT?  I DON''T KNOW WHERE OR WHAT THAT IS. I''ve been wandering for a couple hours, killing random monsters and talking to everyone I see. Nothing is highlighted and there is no map. I''m going to stop playin', 'Very Positive', 82.52, 22.85, 3.17);
INSERT INTO reviews VALUES (38083, 1649950, 1656, 'i disappointed the mayor, the mafia beat me up, i was sued 3 times and i had 9 protesters blocking my entrance... but by golly, we got the scoop boys. we got the scoop.', 'It''s a great structure for the game and I look forward to see what the final release will be, but I can''t recommend people pay $20 or $15 for it right now\n\nMy big problem is that your newspaper feels like it has no impact at all. The game really needs more consequences, like the mafia debt needs to actually come into play. I want to send biweekly payments to the mafia boss "OR ELSE". If I piss off the mayor either by not reporting his lies or if I report dirt on him, I want him to have the cops ', 'Overwhelmingly Positive', 96.98, 8.15, 24.97);
INSERT INTO reviews VALUES (38085, 1651490, 238, 'Fun little game. It reminds me a lot of a certain original maxis game and it does scratch that itch. I''m looking forward to seeing this little beauty grow.', 'I hate to give this game a thumbs down because I still hope it can be made into something good, but even for $10 there just isn''t enough here. Like not even a few hours worth of fun. I tried it when it first came out and it was very boring, but heck, it was brand new and just needed to bake more. Tried it again 16 months later and... still missing a ton of features. Not a lot of jobs, skills, activities, etc. As far as I can tell you can only make money from the  jobs and not craft skills. I get', 'Very Positive', 89.92, 3.85, 2.12);
INSERT INTO reviews VALUES (38087, 1652250, 802, 'Love Auto-battlers but hate the stress of making timed decisions? \nWant a fantasy game with some light role-play elements to keep you hooked? \nIf you said yes to these, this game is definitely for you! \nTales & Tactics has a wide range of items, combinations and strategies that will keep you grinding away unlocking all the content there is to offer, and then keep you playing beyond that! \nHighly recommended.', 'I was initially unsure about purchasing this game, but I decided to give it a shot. My interest is mostly about PVE, rathen than PVP. Unfortunately, the gameplay feels overly self-centered. Most of the time, you''re simply focused on choosing the passive ability you want and buying the corresponding units. Enemy units, buffs, and items rarely feel relevant.\n\nThe roguelike elements are rather shallow as well. While the game offers unique units, their individuality is overshadowed by the overwhelmi', 'Very Positive', 88.15, 17.03, 5.75);
INSERT INTO reviews VALUES (38099, 1657630, 17624, 'Co-op,I speak for Every single person who bought this game and plays/played it from kids to students to adults to couples, WE WANT MULTIPLAYER!', 'Seems like the devs dont have a clear idea on what makes this game work. After two full years of early access, on a game thats slightly more than a slime rancher 1 dlc, adding an annoying grind mechanic ridiculously far away from your ranch while theres still no way to automate slime care at all seems a little out of touch. Not to mention than half of the grinding leads you to... ranch decorations. Buy and enjoy slime rancher 1, sr2 is not worth playing in its current state, much less for its pr', 'Very Positive', 94.43, 27.22, 57.18);
INSERT INTO reviews VALUES (38103, 1660080, 1305, 'Very enjoyable to play. Multiplay works wonderfully. Two of us grandmothers playing together! Time just flew! Had to gift the game to my sister (also a grandmother) and her husband and my niece. Can''t wait until we all multiplay together! Flying with the glider was very difficult at first (I died), but it is getting better. I love the concept, the story. Combat became easy once I got a sword and remembered to aid my health before battle with food and drink. And I have only played 12 hours - most', 'The game is beautiful, but 8 minutes in I have to ask for a refund :(\nThe FOV is giving me extreme motion sickness no matter how much I play with the settings. The fish eye view end the screen bobbing up and down when you walk are really not friendly towards people who are easily motion sick. \n\nI really wanted to enjoy this game, but sadly I cannot. If you''re not affected by motion sickness you''l probably have a great time!\n\nEdit: A game designer from astrolabe politely reached out to me to sugg', 'Very Positive', 85.36, 34.43, 0.13);
INSERT INTO reviews VALUES (38112, 1663640, 277, '     Have you ever played a game so bad that its good? This isn''t quite that. It has all the vibes of a so bad its good B movie, but everything considered its actually pretty okay. It may not be as fine tuned as some of its more popular competitors, but I have laughed harder at this game, and the jank that it is, than I have with any other souls like.\n     Also something incredibly interesting is that your decisions do actually matter. I played this with a coop partner and we are swapping betwee', 'Ah yes, I always wanted a soulslike where you play as a reddit mod.\n\nAlso, the map design was horrible. I spent more time wandering around lost than actually progressing.', 'Mixed', 69.68, 16.90, 11.48);
INSERT INTO reviews VALUES (38113, 1664200, 678, 'The situation with this game sucks so much. To clarify its amazing, its probably the best competitive fighting game I''ve ever played just the skill floor/skill ceiling are so ridiculously high that its player retention is next to nothing. As of writing this the game averages only about 10 players online world wide. If you have any hopes of playing this game you need to go to the discord, the community is small, extremely small, but they are incredibly welcoming and kind. \n\nTLDR If you play games', 'After half a day of "playtime" I barely got over 10 matches online played, most of matches were with insane pings or straight up disconnects. I am writing this review right now after waiting in the unrated queue for 40 minutes. I wish I could give this a positive review, the gameplay seems like a decent redesign of One Step From Eden foundation for PvP, but the player base is so miniscule it is literally unplayable in a nonironic way – unless you are willing to join d**cord I suppose, since it i', 'Overwhelmingly Positive', 96.76, 7.33, 13.55);
INSERT INTO reviews VALUES (38115, 1665130, 318, 'Pac-Man Arrangement (arcade) is so good. Also OG Championship Edition > DX', 'Namco museum 1 was like a fully 3d first person museum which even had dipswitches for games. Pac-Man Museum+ in 2022 gives you a tiny 3d arcade to plop down 5 copies of pac and pal to access arcade emulators which dont even have basic control remapping .\n', 'Very Positive', 88.99, 7.82, 2.55);
INSERT INTO reviews VALUES (38116, 1665460, 368, 'WOW', 'This is the worst game I have ever played. It feels like a student project.', 'Mostly Negative', 32.07, 331.68, 1.08);
INSERT INTO reviews VALUES (38117, 1665500, 494, 'A vibrant retro-ish PS2 aesthetic vibe out type of game.. \n\nthis does not have a lot of action mostly just platforming/exploring dream worlds or talking with NPCs. Theres even some horror themed levels which is surprising for this kind of game.. \nIf you are someone that enjoys this sort of niche stuff then this is good otherwise just skip it.....', 'I    purchased this product  based upon a revue by the curator  \nTrippy Games.  I usually  purchase  games  that are recommended by  \nTrippy Games . For something to relax to  when I am  drunk stoned or  sleep deprived  some surreal   visual experience to relax to and to   help me  drift off  into dreamland .  This game was none of those things, It was  a rather annoying plat former  that seems to become progressively  changeling and harder  with each level .  I played it stoned and drunk got no', 'Overwhelmingly Positive', 96.36, 9.22, 4.80);
INSERT INTO reviews VALUES (38118, 1668540, 726, 'A great conclusion to three previous arcs. The story doesn''t drag like CS III & IV - the main story is around 50 hours. There''s a huge optional dungeon you can explore after you finish the story with tons of great rewards. Almost all of the characters from previous entries are playable. A lot of side stuff like mini games if that''s your thing. \r\n\r\nSo yeah, if you''re a fan of the series - you''re in for a treat!', 'If you want a story where, everyone lives to the end and goes off walking hand to hand together (even those hah... few hah... who "die" within the story), with massive lists of useless characters half of whom are bland carbon copy "Yes (wo)men" of each other. This is your game.\n\nIf you want an adult story where there are actual stakes, where favourite characters could possibly die, where not everyone ends up agreeing and becoming a complete goody two shoes. Look elsewhere. This series is not for', 'Overwhelmingly Positive', 95.04, 71.57, 52.73);
INSERT INTO reviews VALUES (38122, 1669980, 2455, 'My daughter is a lesbian polyamorous swordmaster that saved the world and i could not be more proud of her', 'Looks good, but the translation needs to be rewritten by a professional. It hurts to read.', 'Overwhelmingly Positive', 95.97, 23.93, 0.78);
INSERT INTO reviews VALUES (38125, 1671210, 22707, 'DELTARUNE tomorrow was yesterday. This game has given me DETERMINATION to live longer and fulfill my HOPES & DREAMS. Anyone who wants to live a good adventure with characters better developed than most games and some F*ing good music should play this game.\n\nRoxas out.', 'The main reason for this being negative is the insane amount of required backtracking compared to chapters 1 and 2. For comparisons sake, imagine if to unlock Jevils fight you had to get a key in ralsei''s empty castle town he locks you out of within the first 5 seconds. If you don''t do the first 5 seconds perfectly, the next 1 hour may well be wasted and you have no way of knowing until you''ve spent all that time doing it to get a "Rank" for that section.\n\nHalf the chapters a boring NES/Gameboy ', 'Overwhelmingly Positive', 98.81, 8.90, 14.42);
INSERT INTO reviews VALUES (38127, 1671360, 116, 'After Aragami 2 abandoned the "Path of Shadows" basic gameplay loop, I thought we would not see another iteration of the concept. Ereban puts a nice spin on it, but doesn''t let go of what made Aragami great in the first place.\n\nSad I missed this game at launch, but since proper stealth games are rare, I hope more people eventually end up finding it like I did.', 'This is tough. The game isnt all that bad... its just kinda fine. But your time is better spent on other games (clear something from your backlog instead)\nGameplay - its basic as hell, nothing special about it. It is a full stealth game so no combat just stealth kills (not a bad thing) Its really hard to say anything here, because there is nothing all that good or bad about it\n\nStory - I dont know if there was 5 different writers all trying to force in there own story, or if they just didnt have', 'Very Positive', 81.03, 7.70, 8.80);
INSERT INTO reviews VALUES (38128, 1671410, 732, 'I love Somerville, legitimately might be one of my favorite depictions of an alien invasion ever. Extremely nice looking scenarios, superb environmental audio and memorable moments, with a good mix of slow and frenetic phases. The puzzles are cool too, with nice variety and never giving up on the cinematography nor the satisfaction of the solutions.\nI absolutely recommend this game to anyone looking for a "cinematic" adventure, a really good addition to the other games we all already know.\n\nEsp:', 'I really tried my best to play this game but I found the controls to be terrible and it totally broke me out from the experience multiple times. 3D environment also were very misleading on what I should be doing and it seems that the 2.5D was rather enforced rather than carefully integrated to the gameplay. I adore Limbo and Inside but this unfortunately didn''t click with me.', 'Mixed', 69.81, 3.10, 1.62);
INSERT INTO reviews VALUES (38130, 1672500, 1516, 'Sorry, Nintendo\r\n\r\nNintendo lost out. I''ve been waiting over twenty years for a proper sequel to custom robo, and I''ve finally found it. The customization is insane, even a few hours in. There are not safeguards to prevent you from making something that does not function if you choose. I built a robo that couldn''t jump, and did not have a walking animation. \r\nNow, obviously, you can build great things, but the true trade off on that is allowing people to build non functioning garbage heaps. I''ve', 'The online sync issues from the beta test are still here. I can''t say this enough but Bandai really needs competition with these anime IPs', 'Very Positive', 87.60, 52.40, 46.43);
INSERT INTO reviews VALUES (38134, 1674170, 6728, 'Sir, the new infantry support tank has tracks a meter wide and a gun that could only possibly be the tank equivalent of a micro-penis. However, it moves at a speed of 7kph, a new record!', 'Had tonnes of fun playing earlier versions of the game that didn''t require hours of blender, but the game could really do with a tutorial.  Coming back and I can''t do anything with free from because I can''t understand what each thing.  Maybe I''m just not smart enough for a game like this, but a tutorial aside from other people half mumbling into their microphones for poorly edited YouTube videos would do wonders for this game, particularly in learning the free form mechanics.', 'Very Positive', 94.83, 16.50, 14.43);
INSERT INTO reviews VALUES (38164, 1675830, 3247, 'As a local Hong Konger who witnessed and somewhat overcame my fear of potentially being brutally beaten to death and imprisoned for years by actually joining the protests in 2019, I have never been able, and I believe I still am unable, to watch any documentaries capturing what happened in the second half of that year. I was essentially traumatized in the aftermath, a fate I think also befell most who joined or experienced the protests in one way or another. Imagine how "peaceful" Hong Kong once', 'Literary fiction in visual novel form - tries to say something about a lot of things (generational trauma, religion, being an immigrant, authoritarianism, pandemics, mental illness) but ends up not saying much. Flowery language in a weak sci-fi setting doesn''t do the ideas it''s trying to explore justice. This is art, but not a piece that captured me.', 'Overwhelmingly Positive', 97.07, 10.22, 7.35);
INSERT INTO reviews VALUES (38174, 1676130, 1904, 'Unironically this game made my nuts quiver every time i booted it up', 'Extremely repetitive.\r\nBarely a story.\r\nAll around forgettable.\r\nShooting and action is fine.\r\nNot much in the way of destructables or differing enemy deaths dependent on weapon.', 'Very Positive', 91.65, 19.90, 17.45);
INSERT INTO reviews VALUES (38185, 1676380, 258, 'Its barely more than barebones, needs improvement, but what is there is fun. Some say this is an asset flip, but them using *some* assets is a non-issue. Especially for an indie game, who does not have the capital to hire specialists for everything. They use frameworks and build up and adjust from there. Thats what assets are for and why they are sold.', 'It''s a lazy asset flip that hasn''t received an update in 7 months by a developer that only produces garbage.', 'Mostly Positive', 75.19, 3.40, 0.35);
INSERT INTO reviews VALUES (38207, 1676840, 4447, 'Was pretty unpolished on release but it''s essentially just more of the first game which I really enjoyed multiplayer with friends. The grid based battle system makes things slightly more dynamic but wasn''t a massive change. Most of the early issues with crashes and bugs have been fixed and we got about 40 odd hours out of the main campaign & that''s enough for a thumbs up imo. Looking forward to a new campaign or dlc.', 'game is really fun, its an improvement from ftk1, and I would recommend this game to anyone who liked the first game, if not for the game breaking bugs that are still in the game\nplayed with a friend till chapter 4, and couldn''t enter a dungeon due to the game freezing at the loading screen every time we try to enter it. huge bummer since it was a near perfect run, and its just sad to see all the effort go down the drain due all because of a bug', 'Mostly Positive', 78.26, 48.60, 42.85);
INSERT INTO reviews VALUES (38222, 1677110, 1454, 'The ONLY reason this is not already my favorite game is that the days feel punishingly short, you have only a few minutes to get absolutely everything done in a game that otherwise feels perfectly cozy and go at your own pace. Please, I''m begging the devs to make the days longer, that''s all this game needs to be just about perfect<3\n\n*Edit a game update later and having played through most of it at least, still think it needs more time, but more so something like pause while in menus and/or read', 'I loved this game before the update. The hand designed map with clear step by step progress, along with a companion that provided dialogue throughout your time playing so you didn''t feel so alone. The early on interactions with NPCs plus Pip-3r made the game feel wholesome and like a small community. Now, after the update, it doesn''t feel the same. The map feels more tossed together with resources intermingled so there isn''t a clear sense of direction. Pip-3r is practically gone, and because I w', 'Very Positive', 85.69, 56.87, 46.80);
INSERT INTO reviews VALUES (38231, 1677280, 11199, 'Here is my actual review. COH3 has the best QoL in the franchise. SO much so I stopped playing COH1 and 2. Both are favorites to me. But COH3 just feels better. Balance is in a much better state as well as the game. The game is taking longer to reach where it needs to be now with a smaller team, but it is a team that cares. This game received too much hate on launch because people compared to an almost 20 year old coh1, and a 10+ year old COH2. But base game to base game COH3 had so much more co', 'They listed my GPU as supported and then quietly patched out support back in the first year, well after the refund window had passed. Absolutely heinous rug pull from a heinous company. This hot garbage is just stuck in my steam library but just crashes and they intend to do nothing about it. Money genuinely stolen.', 'Mixed', 62.73, 1112.02, 257.90);
INSERT INTO reviews VALUES (38233, 1677310, 5115, 'i love traumatized queer people stuck in time loops while slowly going insane\ngotta be my favorite genre', 'Made me sob very violently. 0/10. (Also could not sex odile. No good. Fix this insertdisc5 pls) \n\nFr tho get out of negative reviews and go play. This game is the reason I wake up in the morning. Tehe!', 'Overwhelmingly Positive', 97.85, 42.12, 64.17);
INSERT INTO reviews VALUES (38234, 1677350, 1601, 'Mostly enjoyable. Not as good as the old school Tiger Woods games but as close to them as we''ve had for years. \n\nHowever, whichever monster decided career mode needed to be constantly Online deserves to burn in the fires of hell. What a terrible call. Absolutely no need for career mode to require a connection to the EA servers.', 'EA has completely abandoned this game. There is no technical support, they do not respond to their own forums and now they have a problem with leader boards and tournament scores not even being logged - no response...\nI''ve had issues playing online with friends with constant "disconnected" issues and can''t even have a private match with a friend one day and fine the next but someone else crashes the game. They fired the creators long ago and simply don''t care about this game. There are maybe 175', 'Mixed', 55.09, 5.80, 1643.58);
INSERT INTO reviews VALUES (38257, 1677740, 308, 'love this game playing since 2 years and scopely is adding good updates every month so you shoul play this game', 'Ever since the game became owned by Scopely it has gone down the drain. It has never been what it used to be.', 'Very Positive', 87.01, 1502.58, 1246.67);
INSERT INTO reviews VALUES (38258, 1677770, 5580, 'Yes, I Recommend this Game.', 'Leaving a negative review just to let people know that the recently released "Redux" UI is unconscionably bad.\nIt feels like a UI sized for a mobile phone and it''s looks cartoonish on my desktop monitor.\n\nThe move away from a pixel font to a vector font is great, but the replacement of the constantly visible word bar and single "thinking" page with a bunch of different tabs is terrible.\n\nIf you still want to play this game, I highly recommend using the original UI. \nSkip the "Redux" version!', 'Overwhelmingly Positive', 98.49, 22.10, 13.10);
INSERT INTO reviews VALUES (38266, 1677970, 150, 'It is similar to Railroad Corporation 1 (don''t know is it good or bad) but few things I have noticed so far:\n\n- railroad construction now is much, much better\n- we have signals!!!\n- finally trains have a proirity like in good old Railroad Tyccon 2!\n\nI didn''t try a multiplayer yet. I''ll update my review once I test it.', 'Exactly the same game but in a snow setting.\n\nI really expected this game to be an improvement from the original, was hoping for a little more ease of use when it comes to cargo and some more freedom with the track building, but i was highly disappointed. Nothing really stood out to me as new and better, the views are still bad, no ride along modes, everything seems very scaled down and toyish. This really should hev been just a basic DLC, im kinda sick of companies giving a fresh coat of paint ', 'Mostly Positive', 79.33, 100.37, 0.35);
INSERT INTO reviews VALUES (38267, 1677980, 134, 'It''s easy to learn, it plays fast.\nIt''s fine for what it is.', 'I''m not sure what I was expecting, but the gameplay, combat animations, voice clips, and sound effects all felt lackluster.', 'Mostly Positive', 76.87, 10.33, 0.93);
INSERT INTO reviews VALUES (38276, 1678140, 200, '+++ easy, fast & cheap 100 % Steam Achievements\n\n+++ 5 Trading Cards Set = Perfect\n\nGood for Achievements Hunters, Card & Games Collectors + Indie Genre Fans\n\nhttps://store.steampowered.com/app/1678140/Shades_of_Sakura/', 'Unbearable visual glitches. Game should come with an epilepsy warning.', 'Mostly Positive', 79.00, 1.32, 4.50);
INSERT INTO reviews VALUES (38285, 1678420, 281, 'The state of this enhanced version is a joke. It looks like someone accidentally smeared butter on every sprite and background, and to make matters worse, it’s plagued with numerous game-breaking bugs. It doesn’t seem like Nightdive is making any effort to address these issues.\n\nFortunately, the package includes the classic version of the game, along with a variant that has some cut content restored. Just play that one.\n\nThe game itself remains a true gem. It’s definitely worth playing for fans ', 'Enhanced my ass.. Basically a crappy re-release.', 'Mostly Positive', 71.89, 6.00, 1.35);
INSERT INTO reviews VALUES (38286, 1678430, 455, 'Powerslave (Always, Exhumed to me). This is, the definitive version. I think I first came across this project on an obscure website a long time ago and quietly hoped it would come to fruition. I have thoroughly enjoyed this game and nostalgic reliving of, one of my favourite Sega Saturn titles. I still have a Sega Saturn with Exhumed and, I 100% approve of this version. I sincerely thank the Team behind this. \nThank You, guys. \n\nOne Team Doll left. I missed it :( haha', 'FPS platforming while dodging constantly shooting slow projectile traps in awful, bland, samey levels with sh♥t music, underwhelming weapons and lots of tiny enemies. Miss me with that.\n\nF♥ck you devs for that last sequence in Amun Mines, putting an enemy after a frustrating platforming & dodging sequence right behind a door where I have to blow myself up to get past the door and then switch to another weapon before said enemy tears me to shreds. I had to do that sh♥t like 20 times. F♥ck you.', 'Very Positive', 90.33, 42.37, 1.55);
INSERT INTO reviews VALUES (38325, 1679210, 406, 'What a masterpiece of a game! I loved the music soooo much and also the village''s nighttime charm. For all the people who always only talk about the graphics, it should be said that''s what makes this game so charming. I would have liked to help more, just to be able to continue playing. Maybe one day I''ll return to this village, for the music, for the charm, for the story and for the mouse of course.', 'Might be different with a controller, but there''s no way to adjust how slow/quickly the mouse runs about with the keyboard controls. The default speed is too fast so the game makes me feel ill. Game is unplayable for me because of this. I hope this can be changed in future updates.\n\nDon''t purchase if you struggle with fast motion.', 'Overwhelmingly Positive', 98.52, 6.50, 0.33);
INSERT INTO reviews VALUES (38326, 1679220, 111, 'Real good game with letsa replay ability', 'i was jumping, pressing right and letting go so i would land on a platform but my character kept going right even with the button released, resulting in me falling off the edge. I had to spam left/right while mid-air.\ni literally lost on the very first 1-1 screen, it was so bad i wanted to punch my screen', 'Very Positive', 90.99, 61.20, 0.80);
INSERT INTO reviews VALUES (38329, 1679290, 183, 'Shelling underage conscripts with 8 lbs artillery guns', 'I like the game a lot and I love the period but the bugs that these game has need to be fixed, which would make me buy it again. I think it has a lot of potential, it just needs improvement and a one or two historical errors I could point out but they might be just bugs. I love the art work also. I would only not advise to buy it at this price.', 'Mostly Positive', 72.68, 35.37, 1.72);
INSERT INTO reviews VALUES (38330, 1679320, 425, 'Nice game\nEZ to get all achievements 100%', '100 hidden cringe 2', 'Very Positive', 93.65, 1.35, 4.55);
INSERT INTO reviews VALUES (38338, 1679510, 193, 'Fun game, has cool boss fights.\n\nMake sure you read the system requirements, very hard to run and had to buy bigger hard drive.', '(JUST to be clear; I''ve played till a little after the first boss and have experienced all(most) of the demo)\n\nThe game''s clearly not for me, I was disappointed due to the lack of polish. poor and messy environments, and very easy bosses/enemies. The game has a lot of good ideas such as the unique boss patterns, humor, characters, and story. The opening to the moon made quick a chuckle and the character''s vibe also provided a couple laughs but aside from that in terms of the gameplay I didn''t fe', 'Overwhelmingly Positive', 96.37, 5.25, 0.37);
INSERT INTO reviews VALUES (38362, 1680000, 160, 'Rewrite was so good that me and my friend hated on it for 5 years but then revisited it and realised it was the greatest piece of fiction written by man', 'True route is an actual waste of time', 'Very Positive', 90.00, 66.27, 49.67);
INSERT INTO reviews VALUES (38402, 1680880, 3000, 'I watched some popular streamers shitting on this game while playing it. They were very entertaining, but I saw some interesting things about the game.\r\nI pulled it up on STEAM and it was 70% off. I thought for $20 it seemed like a deal. It was. The game is worth $70, but I would not pay that because I am 71 and cheap.\r\nThe game has a learning curve, but once mastered, the game is fantastic.\r\nFor $20 this is one hell of a bargain.', 'It''s a 20€ game sold for 80€.', 'Mixed', 68.70, 167.67, 3.93);
INSERT INTO reviews VALUES (38413, 1681060, 363, 'TL;DR: you should absolutely play this if you''ve ever watched a non-Universe episode of Stargate, ever played Evil Genius, or enjoy lighthearted science fiction and low-stress management games. If none of that applies: how does Theme Hospital meets Strange New Worlds sound?\n\nExogate Initiative is a delightful management/4X/base building game that absolutely nails the semi-whimsical, sometimes-serious, but never self-serious tone of its source material. I cannot imagine a more fitting Stargate ga', 'Ran into 3 or 4 separate bugs with the AI within an hour. They kept getting stuck not sleeping or eating or being eternally stuck in the medbay unless I manually removed them from it. The tutorial is also terrible and poorly paced. \n\nI figured out how to solve most of the issues by browsing through the steam discussions where people had reported these problems over a year ago. But since it just wasn''t grabbing me and I was getting sick of the bugs in what is supposed to be a fully released game ', 'Mostly Positive', 73.55, 32.97, 1.58);
INSERT INTO reviews VALUES (38427, 1681430, 9819, 'Come for the fun ultra violence and ragdolls, stay for the thrill of mundane police work and charming interactions with the good citizens of Detroit.\n\nWhat the trailers don''t show is that a good portion of the game involves you walking around immaculately rendered 80s-scum cityscapes yapping it up with the locals and doing cop-stuff (ticketing cars, resolving disputes, building public trust), and honestly it some of the best parts of the game.', 'Good effort but really not interesting enough to keep playing.\n1st section is all gunfight, which is nice. I mean, it feels like Robocop, the bullets pack a punch and the killing is satisfying, but that''s where it ends for me. You do get the feeling of being a robot tank able to take bullets and not care while headshoting everything that moves, but the enemy AI is piss poor, just running at you without care of being blasted into pieces, the stages are corridors with open doors to fake rooms that', 'Very Positive', 88.13, 2.75, 1.30);
INSERT INTO reviews VALUES (38436, 1681600, 233, 'Okay this is a hard one. Like If you like farming games for the FARMING in them, this is an OKAY game. But honestly- whyyyy so many types of EVERYTHING. I don''t get it. Okay? you want to confuse the hell out of players? Okay got that. Want to waste all the inventory space with garbage? GOT IT! It just makes no freaking sense to me. I like the soil mechanics but really. Like 50 different types of rocks? Okay.... \r\n  I do really like the START CUTSCENE buttons tho- it actually gives you a pop up t', 'There looks to be undisclosed use of AI-generated text for some of the characters. An example that looked fishy to me:\n\n “Welcome! The Water is calling your name. Ready to embark on a thrilling adventure? These caves are brimming with surprises and enigmas, set to kindle the spark of discovery within you. Have you heard about the majestic Squid that resides in the depths? It’s an imposing sight, but nothing you can’t handle, I’m sure! Given your grit and resolve, I have no doubt you’ll conquer t', 'Very Positive', 90.99, 7.65, 25.92);
INSERT INTO reviews VALUES (38443, 1681840, 308, 'Excellent game with loads to unlock.  I can see myself playing this for many, many hours.  The dev is extremely active on the forum and answers questions extremely quickly.  Very very impressed with both the game itself and the dev.  10 out of 10.', 'Wow. This game is no where worth the sale price I got it at ($14.99). How is it priced at $29.99?? Game was buggy from the get go. Feels and plays like a mobile game. Refund requested.', 'Overwhelmingly Positive', 95.45, 31.37, 0.10);
INSERT INTO reviews VALUES (38445, 1681880, 156, 'amazing game but people need to stop writing bad reviews because they don''t know how to learn the controls', 'This is at best a mobile game...', 'Mostly Negative', 38.46, 7.92, 10.58);
INSERT INTO reviews VALUES (38448, 1681970, 129, 'I enjoyed this game a lot. The story is thrilling, the actors are talented. Looking forward to the next part.', '本篇看着有5回其实也就是故事序章。每一回故事确实很短。前5回基本没有什么故事只是系统熟悉和故事背景。不喜欢等和不喜欢多次购买DLC收费的人注意了、至于看到的后面DLC到17回，写评时还没出，不确定水准。\n不过好的是这个是"全动"画演出不像某些大部分是幻灯片。', 'Overwhelmingly Positive', 95.35, 9.40, 2.20);
INSERT INTO reviews VALUES (38454, 1682050, 397, 'That aint me', 'Seems like a good game if you have a lot of friends. Servers are dead and so is the player base.', 'Very Positive', 85.64, 1.85, 0.68);
INSERT INTO reviews VALUES (38455, 1682060, 126, 'I''m a big fan of Warriors of the Nile 1 and part 2 does everything that made the first one great and more. There''s more heroes, more diverse levels, more tablets, and more strategic fun. \n\nIf you don''t know, this is a strategic turn-based rogue-lite with meta progression. As you play, you get further and further in and earn new characters and abilities. The game is just like chess in that every move carries significant weight and consequence. There is an element of RNG, but you can''t get anywher', 'There is too little strategy for strategy game.', 'Overwhelmingly Positive', 96.83, 157.88, 2.62);
INSERT INTO reviews VALUES (38503, 1683100, 115, 'A small but well-made production where you can really have fun, of course it''s not a huge game but long hours but that''s why this game is so good because it doesn''t tire you out with its formula. I think it''s really worth playing.\n\n10 / 10', 'It''s a cheap knockoff of nier automata with the same bad nonsense combat, empty characters and bland visuals.', 'Mostly Positive', 75.65, 6.28, 4.03);
INSERT INTO reviews VALUES (38505, 1683150, 2234, 'Fun game....does not hold your hand whatsoever (i still have no idea how to do jobs apart from passengers) ....switching can be annoying.....but its still a great game\n(Edit: Literally the day after writing this review they updated the tutorial and it is 1000000000000000% better THANK YOU DEVS!)', 'my wife said it was me or railroader. i miss my wife.', 'Overwhelmingly Positive', 97.67, 22.32, 661.95);
INSERT INTO reviews VALUES (38513, 1683320, 155, 'Definitely a great game for someone who thinks running a Country is easy. This game allows you to think outside the box, strategise and push harder than ever - economically and militarily - to achieve your own goals.', 'Of every game I have ever bought. This game is the absolute worst. I now avoid all Eversim games. Complete waste of money. Horrible game and worse company.', 'Mixed', 53.55, 103.05, 3.75);
INSERT INTO reviews VALUES (38514, 1683340, 614, 'Fantastic game, very realistic physics feeling and beautiful visuals. Unfortunately I have had to refund as I just can''t play it without it making me feel sick. If you get motion sickness be prepared to take pills before each session haha! Stunning game though!', 'White water has been part of the development roadmap for awhile and now its finally being released.. under paid DLC.', 'Very Positive', 82.90, 0.55, 6.45);
INSERT INTO reviews VALUES (38525, 1683560, 494, 'Alongside Parasite Black, this is my favourite game in my library.\nI absolutely love the storytelling, intrigue and consequences of this game. It genuinely has so much replay-value despite being a fairly lengthy game in its own right. The character designs are amazing and the art is gorgeous. \nI only yearn for more content, but this is a devteam that follows a stable release cadence which is very refreshing. Very excited to see what else they have planned in the future!', 'This game is a scam. If you''ve played the demo DO NOT waste your money buying the actual game. The demo lets you play 99% of the available content for free. There''s literally nothing of consequence after the demo ends, except 10-15 minutes of minor exposition. Will there be new content in the future? I don''t know, but they just announced their new game, so I''m going to say it''s not very likely.', 'Very Positive', 94.74, 24.03, 14.88);
INSERT INTO reviews VALUES (38561, 1684170, 582, 'As a bi male I really enjoyed being able to hook up with heterosexual females, trans and the twinky guy (really liked that last surprise the most). Fun story, sexy times. Please continue to add in all the different kinks and fetishes and orientations and let us choose while we go about the fun silly story. Thanks!', 'Was an awesome game, but having to invest money for week 1, then buy the game for week 2, and then buy it again for week 3  was a little cheeky by the dev.\n\nThen, to hide the endings in another paid for DLC turned this game into a joke, worse than EA. Best way to stop this is to not support the dev and boycott his games until he changes being a greedy little EA wannabe', 'Very Positive', 84.19, 4.33, 104.17);
INSERT INTO reviews VALUES (38572, 1684350, 1187, 'Seriously. IDK how this is not turning a profit yet. But this is BY FAR one of the best single player games I have played in a while. And by that I mean I played it ALL THE WAY THROUGH even though I have the attentionspan of a fortnight-player after 25 cans of monster at 4 a.m.\n\nInvestigation is good but no moon-logic. Fights are very much old PS1 era style in type. And the sense of humour is just this wonderful dark kind of humour that can only be pulled off in an eastern european setting.\n\nI a', 'It has a cool setting and some neat ideas but I was disappointed with the gameplay. Detective work is automated, combat is too easy and scavenging hunt sidequests are tedious. The story lacks focus and I didn''t connect with any of the characters.', 'Very Positive', 82.98, 38.88, 33.40);
INSERT INTO reviews VALUES (38575, 1684410, 605, 'This is my favorite game. Seals are my favorite animal. If they are also your favorite animal you will enjoy this game. This game was fulfilling and made me smile a lot. I loved the ending. This game captures perfectly the simple joy of life. For a seal at least.', 'This game would have been a hearty thumbs up, but in the third world, as you approach the refund time limit, the platforming becomes dramatically more complex and unforgiving and resetting after failures takes increasingly longer. It certainly is attainable, but it''s not enjoyable, and runs again the vibe of the first 2 worlds.\n\nETA: The platforming may ruin the enjoyment in the end, but I unironically nominated this game for Outstanding Story Rich Game in the Steam Awards. That''s the only reaso', 'Overwhelmingly Positive', 99.50, 2.78, 1.87);
INSERT INTO reviews VALUES (38588, 1684670, 161, 'Would like to hear the tines dragging on a concrete floor.', 'unable to refuel forklift engine stuck on 1%', 'Mostly Positive', 75.16, 0.63, 22.48);
INSERT INTO reviews VALUES (38590, 1684720, 226, 'sad hitler isnt alive to play this masterpiece', 'Lacks features. Movement is janky. Upgrades are either OP or awful.', 'Very Positive', 93.36, 0.17, 0.93);
INSERT INTO reviews VALUES (38601, 1684930, 4993, 'This is the best feeling boomer shooter ive ever played. Hits the perfect sweet spot of being a bit slower paced compared to something like Dusk, while still feeling snappy. If you enjoy games like Ultrakill this may be a little slow for your liking, but it''s perfect for me.', 'Why go through the trouble of making the sound design retro, if you''re gonna make the music not fit at all with the rest of the game? kinda just ruins it for me.', 'Overwhelmingly Positive', 98.38, 22.90, 0.12);
INSERT INTO reviews VALUES (38690, 1686940, 12829, 'One of the most fun couch/online party games I''ve played. Combining different physics-based abilities into unique ways to kill each other never gets old and allows you to be really creative. And you might find yourselves playing ''just one more round'' for about 73 rounds.', 'I broke my mouse, my keyboard, and my love life. I get migraines while playing this game, but can''t stop. My friends want me to make myself kill myself in this game. I need help.', 'Overwhelmingly Positive', 97.47, 50.60, 368.98);
INSERT INTO reviews VALUES (38695, 1687000, 213, '55 hours and i don''t think i''ve seen even a quarter of everything in this game. and i haven''t been bored a single time. it''s genuinely THAT GOOD. the combat is a bit lacking for options, but once you unlock the second character that''s alleviated pretty well.', 'The game can be fun but it''s equally frustrating with the lack of a manual as you only get three trips a day. Buying a car only unlocks the countryside but doesn''t give you even one extra trip but it''s questionable if access to the countryside is even necessary. Another problem is that this game has awful controls and GUI for PC. I should be able to simply press buttons and cycle through menus to see my status and inventory yet to pull a gun out you must hold c and press z. Then to shoot hold z ', 'Very Positive', 90.14, 59.17, 2.37);
INSERT INTO reviews VALUES (38712, 1687250, 203, 'This game is sooo much better than expected. I thought it looked good, but some reviews made me hesitant. I''m really glad I decided to go with my gut and buy this. The gameplay is well done and surprisingly varied. The visuals and h scenes are great as well. I''m still early in the game, but already see a lot of collectibles and rewards to be earned (magazines, outfits).\n\nI do hope it gets controller support soon, but other than that, I have no problem recommending this game!', 'Finally finished the game. You must complete all the main quests to unlock the nude status for all the female characters. It takes about 3.5 to 4.5 hours to complete the game. I only finished it once and don''t want to play it again. I hope people who haven''t bought the game will be cautious. The protagonist you control doesn''t have breasts as big as those two supporting characters, so people who like big breasts should not buy it (personal advice)', 'Mostly Positive', 70.44, 3.88, 5.80);
INSERT INTO reviews VALUES (38725, 1687550, 165, 'This game was made with so much heart :)\r\nIt''s a little reminiscent of Undertale, but there''s no combat which means it''s a much cozier and relaxed game. It was also surprisingly much longer than I anticipated! (Important to note that about half of my play time was idling, however.)\r\nIf you''ve been sleeping on this game, I''d highly recommend trying it out <3', 'There is the only way to go the Heaven, Jesus said "I am the Way and the Truth and the Life nobody enters the Heaven except through me. So, unless people repent on this earth, there is no room for you in Heaven.', 'Overwhelmingly Positive', 96.36, 6.17, 2.92);
INSERT INTO reviews VALUES (38737, 1687950, 26560, 'i think my game is bugged they didn''t let me pursue a romantic relationship with goro akechi', 'Get out of the negative review section and actually play the game. It’s solid.', 'Overwhelmingly Positive', 96.87, 93.00, 348.30);
INSERT INTO reviews VALUES (38743, 1688100, 194, 'From the title and the media available on the Steam page, I was just expecting cute cats. A few minutes in, I thought the developers had taken a nice trip, and I was about to join them on the journey. By the halfway point, the story had started to make sense. By the end, I was devastated, then happy.\n\nThis game is fairly easy and forgiving; the puzzles are simple and fun, the characters are well thought out, and the visuals and designs are amazing.\n\nThe only downside is that some parts are reall', 'Enter a surreal world populated by the bizarre and the grotesque. There''s also a lot of cats. Unfortunately, the story is too pretentious and emotionally manipulative. Moreover, there are 2 achievements which require you to beat a 20-second timer. Too slow? Well, tough luck. You''ll have to abandon your game and restart from the very beginning!', 'Very Positive', 94.33, 2.02, 4.60);
INSERT INTO reviews VALUES (38767, 1688580, 504, 'As a trans woman, this game hurts. As a human, it hurts even more. But the pain is really good, while showing the struggles living life from a queer perspective, it also has very heartwarming moments, Games like this give me hope for humanity.', 'It seems to be a kinetic story. It''s not bad but not too interesting either.', 'Overwhelmingly Positive', 99.60, 2.72, 1.02);
INSERT INTO reviews VALUES (38776, 1688750, 109, 'Great software to get into making animated videos, both music and anime! Easy to use interface similar to general video editing tool with a timeline to control animations, camera, and so on.', 'Deadass can''t even upload my vrm. Waited over 4hrs to try and upload, wouldn''t work. Now I can''t even get a refund.\nThis is bullshit. A waste of my money.', 'Very Positive', 88.07, 1.38, 4.95);
INSERT INTO reviews VALUES (38788, 1689080, 103, 'Fantastic game and a great spiritual successor to Tales of the Neon sea by the same devs. \nTranslation quality is fine this time (unlike the pre-revised version of ToTnS), so unless you''re an english teacher you won''t have problems enjoying the plot. \nLess puzzles this time, and they''re a bit easier, which is fine. \n\n\nOne hint: if you''re going for a 100% explore everything before entering a door/passage/ area you''re supposed to go to, because stuff will get locked out and you''ll have to load a s', 'Over sexualized furries is not my thing.', 'Overwhelmingly Positive', 99.03, 12.18, 0.18);
INSERT INTO reviews VALUES (38803, 1689350, 261, 'THIS GAME IS ADDICTING. Its almost 6 am and i should of been in bed by now. but i cant stop!!!!!\n\nplease make some DLC i would happily pay 4x the price of the game for it!!!!!!!', 'Idle game that needs you to not be idle :)))', 'Very Positive', 86.97, 4.93, 2.35);
INSERT INTO reviews VALUES (38810, 1689500, 1769, 'Nice challenge, good tutorial. Feels nice and balanced. No one will read this so i will snort a line of wasabi for each like this gets.', 'Great implementation of this game digitally.\n\nThe reason I don''t recommend this version is simply that they don''t have couch co-op and refuse to add it. I spoke with staff at PAX and they said it''s not happening, which is incredibly disappointing. I''m not sure if I would have bought this knowing that.\n\nThis is common among digital adaptations and the only reason I can see this not being done is to force you to purchase two or more digital copies.', 'Overwhelmingly Positive', 95.42, 6.17, 2.32);
INSERT INTO reviews VALUES (38818, 1689620, 2240, 'Game runs smooth until Yamamoto drops his Bankai and melts your GPU.', 'The game crashes a lot. It''s not a good PC port and pretty much unplayable. Avoid it for now. As a long time Bleach fan, I''m very disappointed.', 'Mostly Positive', 70.80, 36.50, 0.77);
INSERT INTO reviews VALUES (38820, 1689640, 205, 'I mean, there is just no audio here. No music, weapons sounds are really quiet too\n\nGameplay seems ok, artstyle nice but honestly good Music/ Audio is 100% needed imo. Instead there is just some weird ambient sound constantly makes the game not really have much atmosphere imo \n\nI wont thumb it down cos assuming solo dev/ small team but I need good Audio to enjoy these types of games personally', 'A Roguelike game with 2 bosses?!?!? WTF is this BS, the fact that this game is not marked as early access is criminal, after the second boss the game completely falls apart, they keep reusing the same bosses over and over and over again first as normal enemies, then the 3rd boss fight is just fighting the same 2 bosses again, then the 4th boss fight is just the same 2 bosses again with an annoying ghost mechanic and then the final boss is just a wall that moves from left to right that it''s impos', 'Mostly Positive', 73.17, 0.30, 5.15);
INSERT INTO reviews VALUES (38827, 1689870, 156, 'This is the last of a four part series that really gets to the meat of the matter as you discover the source of the mystery on an Alaskan island.  It was the hardest in terms of puzzles but finish the story just perfectly!  Each game is very modest in price, and more than well worth the 19 hours I spent on all four games!  I enjoyed it much more than Facility 47, which I played years ago.  This is right up my alley wandering alone, and taking my time on a large variety of interesting and sometim', 'Up until the very end I would have said is was a passable game.  Literally a matter of a few steps from the end I could no longer play the game and could not finish it.  I have essential tremor and doing prestidigital gymnasttics is not something I can do.  It is precisely why I play puzzle games and avoid Super Mario Brothers type platform games.  I''m so pissed off that I played all of the parts, including the prologue and am left unable to finish the game because of this BS.  If you have any s', 'Overwhelmingly Positive', 99.36, 8.62, 19.33);
INSERT INTO reviews VALUES (38830, 1689910, 250, 'My Gf left me because im a loser but atleast i can date a hot nurse', 'The censored version is badly broken, many scenes are just black screens or white screens as they couldn’t be bothered enough to make a valid censored version. Most routes are just oh I’ve never been with anyone but let’s do it NOW! Or I am going to get over him by screwing your brains out. Because of this most routes felt shallow and like they were only there to try to slam in porn scenes in the AO version. \n\nAnd yes even though I played the censored version I could read between the lines enoug', 'Very Positive', 93.60, 10.25, 6.43);
INSERT INTO reviews VALUES (38887, 1691190, 388, 'Wonderful, wonderful game.  The devs took the best ideas from Slay the Spire and Darkest Dungeon, mixed them with smart new mechanisms, like the shoving in combat, and created a top tier roguelite taking place in a mystical age of pirates where you can tame sea monsters.  Every aspect of the game, from base management to ship combat to tactics battles to exploration, feels equally fresh and well thought out.  Most of all, this game has an undo button. \n AN UNDO BUTTON IN A TACTICS GAME. I''m cryi', 'This game would normally be right up my alley, but unfortunately I find it frustrating. The crew combat is okay. There''s a decent amount of decision making there that you would expect from turn based combat. However, its prefaced by the ship combat which is an RNG hellscape. Most of the cannons have insane damage ranges that remove a ton of the player agency you have over the coming crew combat. High roll your cannons? The fight will be a cakewalk that ends before it starts. Low roll your cannon', 'Very Positive', 85.05, 8.95, 3.85);
INSERT INTO reviews VALUES (38895, 1691320, 355, 'At the game''s core, it''s a round based zombies game that resembles Call of Duty''s well known survival mode. If we dig deeper than that, this game becomes something much more. Unlike Zombies in COD, the show is run by a single developer, and it is a passionate one at that. I have played the game when it was much more bare-bones at the beginning, and I have to applaud the maker of this game for improving on the mechanics, power ups and overall aesthetic of everything I have enjoyed about it thus f', 'Killing Floor from Tesco.', 'Mostly Positive', 78.87, 10.35, 1.13);
INSERT INTO reviews VALUES (38899, 1691420, 405, 'tried to get the ending where you are least suspicious as possible. got the ending where you''re as suspicious as possible. true siffrin experience', 'Only leaving this here because I seem to be the odd one out with this opinion, but I''m not super convinced this is worth playing if you''ve already played In Stars and Time. And if you haven''t played In Stars and Time, you should just go play that instead, because it is a fantastic game and also improves on this one in every way. I wasn''t expecting this to be much different from ISAT, just looking for a little bit of extra lore or maybe an earlier version of some scenes, but quite a lot of the sc', 'Overwhelmingly Positive', 96.54, 14.48, 4.02);
INSERT INTO reviews VALUES (38938, 1692240, 425, 'a game so controversial the dev got arrested', 'In case anybody is thinking of buying the game I would wait until the developer gets out of prison....3 years from now. To the people that bought the game I would highly suggest a refund', 'Very Positive', 92.24, 0.93, 4.20);
INSERT INTO reviews VALUES (38939, 1692250, 9474, 'my gearbox fails every race , pretty annoying kinda wanna shoot a school  up idk fr', '100% sure EA did something to screw the handling so this game has become unplayable. ive been using the same setups since game launched and now i get random understeer and randon  oversteer mid corner, its fucking horrendous, yet another game ruined by EA', 'Mixed', 65.38, 53.53, 569.20);
INSERT INTO reviews VALUES (38960, 1692700, 150, 'The game is great, my motion sickness isn''t.', 'Just not great, only a small box of non blurry textures and also there is no search function for online planes', 'Very Positive', 86.00, 0.73, 0.27);
INSERT INTO reviews VALUES (38971, 1693040, 130, 'Synthwave Burnout with a very juicy retro-wave style that is injected into every piece of this game. The cars have a good responsiveness in control, which gives a lot of fun from each race. There are no difficult tasks - just drive and have fun in the game', 'Absolute broken scam of a game, do not buy and do not waste your time playing.', 'Mostly Positive', 76.92, 3.68, 0.08);
INSERT INTO reviews VALUES (39028, 1693980, 24721, 'The perfect remake/remaster! This is how they should be made!\r\n\r\nKeeps the fundamentals of the game the same, maintaining atmosphere and depth just as much as the original! No bugs, no performance issues just a great game!\r\n\r\n', 'beautiful remake - insane that it has to be connected to the internet. What''s the point of buying this game for the steam deck if I can''t play it on a plane or the toilet or under the covers? Disgusting.', 'Very Positive', 90.57, 38.45, 10.87);
INSERT INTO reviews VALUES (39051, 1694420, 639, 'This is quite possibly the best survival game I have ever played. And all you do is move cards. (Goes to show graphics is nothing, gameplay is everything.) \r\n\r\nThe depth of the experience, the need to survive day by day, by patiently, gradually building everything you need to make it... the different tropical environments, different animals, skills you need to level up - it''s just all so satisfying. There is a lot of grind in this game, but it''s grind that doesn''t feel pointless. \r\n\r\nAlso, a not', 'While I do find the game interesting, the portraits in the game were created utilizing MidJourney. This was not made apparent on the store page (although I''m glad it''s at least disclosed on the main menu of the game). As someone who''d rather not support something that utilizes AI personally, I wish this was more apparent on the store page as I would have likely not purchased it in the first place.\n\nEdit: In the time since this review was posted, Steam started having notes at the bottom of store ', 'Very Positive', 94.84, 212.28, 1.03);
INSERT INTO reviews VALUES (39056, 1694510, 282, 'This is a really good game and almost has every feature I was looking for. I really wish this was an online CO-OP. I just want to run a cafe with my friends.', 'Currently waiting on a refund for this game. Game feels very janky. Making the coffee wasn''t fun, the cleaning wasn''t satisfying (honestly it made me just miss House Flipper 2 cleaning so I switched to that). Game isn''t cozy enough to have good vibes, and not weird enough like Internet Cafe Simulator 2 to have a laugh. Last update seemed to be awhile ago, so I don''t have any hope of it being improved in the future.', 'Mostly Positive', 75.89, 0.28, 0.32);
INSERT INTO reviews VALUES (39060, 1694600, 1045, 'I see most of the bad reviews are from people who didn''t play the original game. I don''t know what''s the fuzz about. \nWhat you all expected? Skill tree? PvP? 100 hours of gameplay? Loot boxes? Paywall?\nIT''S AN ARCADE GAME FROM THE 90''S! It''s a short and simple game!', 'It´s a shame. I want to play it the second time, but it didnt start. I start the game than i came in to the loading screen, see the publisher and than nothing happend. I see that the developer & publisher are unfortunately not interested in the reviews at all. It''s a shame when developers are not interested in their game. Especially when bad reviews come in, you should ask and try to fix the problem, but no, you have already received the money for the game & whether the player can play the game ', 'Mostly Positive', 71.67, 4.00, 1.88);
INSERT INTO reviews VALUES (39079, 1694960, 524, 'im going to shoot myself', 'THEIR FEET ARE COVERED. 0/10 WOULD NOT RECOMMEND.', 'Very Positive', 87.21, 44.90, 1.07);
INSERT INTO reviews VALUES (39103, 1695670, 188, 'I think someone screwed up. It''s third person, go figure.', 'When I bought this game, it was quirky and fun.  It had  charming, cartoon type art style.  Then the devs did a complete overhaul, changed it to a "realistic" style.  They removed all the fun elements and then abandoned the game.  I loved the game I bought, but this ain''t it.  Do not waste your money, or your time.', 'Mixed', 67.02, 0.50, 11.65);
INSERT INTO reviews VALUES (39106, 1695791, 121, 'The dark souls of the halo series... no hand-holding, no map guide, very little info to go off from (obscure at that...). You are left to fend for yourself as you get lost in a hostile virtual environment with only pure grit and knowledge to carry you through the challenges which lie ahead. Your efforts will feel as though all for naught, but with enough trial and error, you may somehow find a way to overcome your demons. Be prepared, and remember, don''t you dare go halo...', 'only an alien can use this shit', 'Overwhelmingly Positive', 95.04, 215.27, 5.00);
INSERT INTO reviews VALUES (39112, 1695830, 723, 'This game is just about nostalgia, i was playing it every week-ends on Play Station 2, days and nights long with my friend when we were young.\nWhat a great surprise to see it coming on computer, i finished it again, alone and with my girlfriend and that was great fun.\nMy only regret to be honest is that 20 years later, it is not a remaster, an enhanced or whatever improved version you would call, it is just... a port...\nAt a 30 euros price tag, to me it feels like a deception, and only fans of t', 'Lazy port of a great game. :(\n\nWe''ve got fuzzy and blurry graphics!  60fps hardlock! Delayed control response.  Bit-crushed audio.\n\nNothing here was enhanced, improved or modernized.  There''s next to no video options.  Price does not make any sense for this one.', 'Very Positive', 82.16, 15.67, 0.27);
INSERT INTO reviews VALUES (39113, 1695840, 1068, 'why did i lowkey start fapping my boner to this game', 'I wish the nun in it would give me a footjob :(', 'Mixed', 69.38, 0.53, 3.95);
INSERT INTO reviews VALUES (39122, 1696080, 154, 'I enjoyed this game - I did buy it on sale, so that always skews your view on things but overall I''m glad I did.\n\nYou basically start with a saloon that you have to improve by researching food and drink items which you then sell to the patrons.  You can buy decor to improve your saloon ambience as well.\n\nAs your saloon grows, the town grows with it and new businesses move in which you can buy things from to help you survive in the saloon business (e.g. Different types of drink, a horse to lower ', 'Gave it a fair chance, uh, it sucks. All of it. It''s so easy its almost an idle game. 20$ is ridiculous, considering how trivial it is to basically win, because you genuinely have to try to lose past a certain point. Maybe 5$ for this, considering the overwhelming slog.\n\nKey maps don''t save whenever you boot the game up too, whoever was the leading team behind this game needs to close itself down.', 'Mixed', 62.99, 25.23, 10.53);
INSERT INTO reviews VALUES (39128, 1696220, 261, 'Yo splice me up but drop the pronouns either Vix is a female or a male no in between! if you can force yourself to look past the pronoun stupidity you got yourself a pretty good game, now i just have to find a way apply a stamp over the mouth of a very annoying talkative lunchbox.', 'I really wish I could give this game a neutral review!\nLike others said, the story was really the only thing that kept me going and even then it began to fall a flat towards the end and I had to press myself to keep playing.\nI feel like it could''ve been a few hours shorter and it would''ve been a better experience, the puzzles themselves were fairly fun for the first few hours then it got so repetitive, for right now I would say it might be worth picking it up during a sale, but be warned it gets', 'Very Positive', 86.59, 5.78, 11.05);
INSERT INTO reviews VALUES (39139, 1696440, 1169, 'Crazy person game. Everyone and everything is a superpowered martial artist, including horses and giant frogs. NPCs are mentally unstable and the mechanics are strange. Combat is unusual to say the least, but mastering it is genuinely enjoyable. There is some kind of bizarre rap battle debate system which can result in repaired friendships or literal death by argument. Perfection.', 'It''s weird because I like this game. I enjoy it. But it should NOT have left early access. It''s not ready, not by a long shot.\nIt''s janky, badly translated, and unfinished. There are placeholder skills that still say "To be released" and more.  Yes, it gives me Kenshi feels and has some neat elements, but the release to "1.0" was a bad idea.\n\nAs such, I am reviewing this as if it is indeed a complete game. A full release and not early access, as they have so claimed. In that regard, I must mark ', 'Very Positive', 88.45, 42.97, 73.50);
INSERT INTO reviews VALUES (39146, 1696720, 170, 'This thing is dripping in style, and I wholeheartedly adore it. But unfortunately, PsiloSybil was made for a very specific audience: hardcore Crash Bandicoot fans, speedrunners, and other sorts of gaming elite league. As a casual, I''m not getting anything out of it. I''ll still recommend it because clearly there is a lot of passion and love fuelled into this project.', 'For a game that tries so hard to copy Crash Bandicoot, it sure misses out on what makes Crash fun. The sound effects are weak, the precision required borders on the masochistic, and there appears to be no Aku Aku equivalent. Let''s throw in stupidly precise platforming using the psuedo-3D in a way Crash never did in a level so dark that the drop shadow is worthless, with no brightness settings! Oh, and let''s make it the third level. No thanks. Really wanted to like this one, but it''s not happenin', 'Very Positive', 87.65, 0.47, 0.65);
INSERT INTO reviews VALUES (39151, 1696810, 4085, 'Year after year, these developers have molded this one into a gem of a train game. Set into the 1800''s, we perform a mix of route planning and delivery skill to earn the ability to purchase a generation of locomotives. The variety of cargo and the needs to access them provide a long playing game that is likely to plateau when access to the final cargo has been achieved. The online game-play is a key to its extended longevity as helping others to achieve their goals is enjoyable too. The growth o', 'Game was poorly managed from the start, had poor development and quality control, and as soon as 1.0 hits they release 2 DLCs. Not only that, but they flag my comment on one of the update forums for being against community guidelines. The comment did infact not, and I had only stated I''m disappointed they are the way they are taking this game.', 'Mostly Positive', 78.16, 487.72, 138.75);
INSERT INTO reviews VALUES (39159, 1696960, 360, 'Like a needle in a haystack, this game is a gem among the plethora of 90s recreated survival horror games that have come out in recent times. A short yet gripping story with familiar tank controls and puzzles reminiscent of classic horror games, this game hits -- and it hits hard. The fact that this is a prequel with the main game in development pleases me greatly considering how gripping this short masterpiece was. However, I hope to hear something soon since steam achievements were promised al', 'It tries to be Silent Hill; it feels almost like it, but not really. I wish the keys were used automatically. I like the aesthetic, but everything else feels too confusing to even begin to theorize.', 'Overwhelmingly Positive', 97.22, 2.08, 1.15);
INSERT INTO reviews VALUES (39189, 1697700, 1405, 'RIP David Lynch. I doubt he knew about this game but I''m curious what he''d think about it. It emulates his style near perfectly in a way no other "Lynchian" horror really does. Perfect game utilizing the medium of a game to the fullest extent, unlike most media which usually fails to utilize the strengths of their medium.\n\nTo say anymore would be filled with spoilers. Play it yourself. Don''t look stuff up unless you''re genuinely, actually stuck. Finish all the things you think you can in the gam', 'the store page and description of this game is misleading. It''s described as being a mystery game with a heavy emphasis on interacting with npcs and controlling your facial expressions. And that part of the game was very cool and fun. The problem is that the game leans heavily away from that after the first hour or two and instead starts shifting into an incredibly convoluted and confusing story with way too much meta-focus. To be blunt, this isn''t a game so much as it is a confusing ARG, where ', 'Overwhelmingly Positive', 95.87, 7.78, 4.12);
INSERT INTO reviews VALUES (39190, 1697720, 242, 'Not your run-of-the-mill horror game. Not a walking simulator, which is nice. The best way I can define this game is a first person POV Little Nightmares game, minus the platforming. Each area is a puzzle in itself and the game doesn''t punish you for getting caught (and you don''t die). In fact, getting caught is part of the experience.', 'whys this shit so godamn loud? no matter what i put the volume to shit do not get quieter and oh my god every time i die i gotta talk to this old man about his birthday soup. I know all this already just tell me what you want in the soup this time so i can try again.', 'Overwhelmingly Positive', 97.93, 6.43, 1.02);
INSERT INTO reviews VALUES (39200, 1697880, 827, '-got car stuck trying to make a shortcut. \n-have only $10.01 so i Can''t tow home.\n-proceed to walk home to get chainsaw to cut trees for tow money.\n-washer falls from sky think hmm what if..\n-spent 3 hours destroying my car with it until it was unstuck. 10/10.', 'Alright, I would give this game a positive review if it weren''t for the tires popping at least every day (on stock rims) and if it wasn''t for the fact that a TURBO''ED TRUCK IN 4X4 CANNOT MAKE IT UP A HILL WITH 6 EMPTY PROPANE TANKS AND 2 EMPTY BUCKETS. It also doesn''t help that as well as tires popping that the parts durability (Head Gasket, Pistons, Belts, ETC) are like the Health of a 80 year old man with stage 4 cancer. It makes the game so much worse when it comes down to it, you''re supposed', 'Mostly Positive', 78.96, 22.25, 61.07);
INSERT INTO reviews VALUES (39214, 1698220, 165, 'way less puzzle and way more fast platforming action. It was a nice experience with less problems than teslagrad 1 but I missed the physics puzzle :)', 'I wouldn’t recommend this game on Steam Deck. Although it’s marked as "verified," I encountered a couple of freezes and a significant bug where the map wouldn’t display when pressing the designated button. This issue even caused the game to crash a few times. I tried reinstalling the game, but the errors persisted.\n\nFrom the limited time I was able to play, the game feels a bit rougher than its predecessor and somewhat clunky in terms of gameplay. That said, I wish I could play it further to see', 'Mostly Positive', 78.18, 2.10, 0.53);
INSERT INTO reviews VALUES (39223, 1698520, 194, 'Simple Fish Adventure is one of the most enticing ragdoll video game I have ever played. I played alongside my wonderful wife. We had one of the most romantic evenings playing as floppy fish, and losing our minds as people. 10/10, would not play again, worth the .99 cents.\n\nYour seagull complaints are just a skill issue. (My lovely and wonderful wife carried me)', '', 'Very Positive', 87.63, 1.77, 0.60);
INSERT INTO reviews VALUES (39267, 1699480, 791, 'You thought you loved someone until they leave you on a random floor in the heart of the gigastructure so you hunt them until their brain turns to ash and their eyes become stone this is the truth of the universe never ever trust those you love they will always betray you the traitors nothing about this game is anything but getting stabbed in the back by the ones you love this is the heart of all things never ever ever ever ever ever will be the first to see the dreams only waking in the nightma', 'My main gripe with this game is the revive system. In a group of 6, having it revive the person who died last is a pretty bad system. If player A dies, then the group finally gets enough bottles to revive a teammate (too many bottles to revive someone tbh) and then player B dies before revive goes off, then player B will be revived and player A is still waiting. In a smaller group it''s not that bad, but in larger groups it''s not ideal. Make it a little cheaper to revive someone or change it to r', 'Very Positive', 91.28, 8.22, 3.68);
INSERT INTO reviews VALUES (39282, 1699860, 106, 'its pretty fun to play with friends sucks it costs money now\n', 'This is one of those games that had the potential to be great but the lack of updates from the dev who basically abandoned the game after it got released makes it unplayable. For $8, you better pray someone will be online which 99% there''s no one. There''s no server browser, only random search hoping to connect you with someone in your region. Even switching regions, nobody is online. $8 basically down the drain. It sucks you have to beg on Discord for someone to play against you as the game itse', 'Very Positive', 86.79, 1.98, 10.93);
INSERT INTO reviews VALUES (39303, 1700270, 332, 'The positive: This game has crisp graphics like old school flash games. It''s got a bizarre sense of humor (I love it), seems easy at first gets harder with a bit of mystery. \r\n\r\nYou will die, a lot. Sometimes you''ll have no idea what you are trying to do. But pay attention there''s clues, if not try again. It''s cool\r\n\r\nUnclear if there will be meta progression outside of the runs. \r\n\r\nThe negative: 0.1.1 and I''m already coming back to play more. One of those games I''ll wear out before it''s out of', 'I want to love this as much as I loved the previous (Flash) games, but the length of each tower coupled with the atrociously awkward control scheme makes for an extremely frustrating experience. Please separate Pick Up and Drop, and please make Use only Use, not also Pick Up, and please stop the hands from automatically switching, ever, or Drop actually Drop and not swap with another item. The sheer amount of times I''ve ended a run because I accidentally picked up/used something I shouldn''t have', 'Very Positive', 94.88, 23.88, 9.08);
INSERT INTO reviews VALUES (39322, 1700870, 1656, 'As you can see by my 800+ hours, I love this game. Do not be fooled by the Rimworld-esque aesthetic design; this is no clone. Living my best cozy life in Medieval Scotland, guiding my clan through famine, storms, and inter-faction rivalry, watching the firelight through the windows and the children playing their instruments while the family hound sleeps by the hearth... instant relaxation and joy. \r\n\r\nThe developer updates regularly, communicates well, and has a Discord set up for beta testing. ', 'In the forums, the dev posted the main difference this game and Rimworld is that Clanfolk is more focused on fighting nature whereas Rimworld is combat. In it''s current state, that amounts to little in-game. Can you build a room with a fire? Can you gather enough mushrooms in the fall? Perfect, you survived winter and the only challenge in the game.\r\n\r\nAfter 10 hours of playing, I questioned why not just play Rimworld where I could accomplish the same challenge and a whole lot more. There''s a lo', 'Very Positive', 92.93, 1076.28, 9.95);
INSERT INTO reviews VALUES (39335, 1701190, 188, 'Too short (the time at review is me 100%ing the game) but otherwise a fun collection of puzzles. Buy if you think two hours of entertainment is worth the price it''s selling for.\n\nA steam workshop and level editor would extend the longevity of this game tenfold.', 'Unique chess puzzle game that is pretty easy, even for a person that couldn''t get past the first 5 worlds in Baba is You. Only get it if it''s on sale because I somehow managed to complete the game in refund time without a mouse. There are sadly no easy keyboard shortcuts for moving the pieces. The game is admittedly too simple and isn''t used in many creative or subversive ways which makes it too easy\n\nAlso, the music and sound buttons are really weird since you need to hold them to make it go up', 'Overwhelmingly Positive', 99.47, 1.75, 1.00);
INSERT INTO reviews VALUES (39342, 1701380, 1673, 'very bad shots they should learn from real cricket 24 mobile game', 'Unplayable on PC as requires a controller which was not made clear at time of purchase. Game takes ages to load and then even longer to use. Gave up after 2 hours. Don''t buy if you intend to play on PC.', 'Very Positive', 81.71, 27.03, 2.90);
INSERT INTO reviews VALUES (39348, 1701520, 1045, 'Chinese Hollow Knight. Very beautiful.\n\nIt’s just a pleasure to be in this game. The graphics are lovely, the music is wonderful, and the gameplay is great. I really like the game, and I''m glad I''ve played it.', 'I''ve been playing my way through a lot of Metroidvanias in the last few months. Afterimage doesn''t come off very favorably in comparison with the others. There''s nothing technically wrong with Afterimage, the problem is it''s just not very compelling. The combat is weightless and boring with almost no depth. The storytelling is rote and perfunctory (especially if you''ve played other Chinese-made games the style is cliche). The art is pretty but very generic Chinese animation. The map is huge but ', 'Very Positive', 86.89, 59.07, 3.35);
INSERT INTO reviews VALUES (39359, 1701800, 1265, 'A hidden gem. Well made relaxing 3D platformer, a combination of jumps, climbing, sliding and running but never frustrating, and you can do triple jumps, even 4 jumps when you unlock the birdie character. The devs know how to create levels with challenging yet not too much, all the monsters are one-hit kills, but your character got 3 lives and the checkpoint are not far, so basically this is a mistake-tolerant game.\n\nI especially enjoy the cake-candy and crystal world, tbh each world is unique a', 'I don''t want to be mean to this game, because it''s clearly had a lot of time and love put into it. But man the core design of the thing just isn''t very good. \r\nIt''s essentially structured like a fully open Crash Bandicoot game, "linear" levels that are very open and require thorough exploration to 100% complete. Unfortunately, because Hana feels so weightless to control- bolting from 0 to 100 the second you touch the stick and having very simple animations- exploration isn''t very satisfying at t', 'Overwhelmingly Positive', 95.89, 2.65, 1.27);
INSERT INTO reviews VALUES (39372, 1702010, 2084, 'Played enough to have an opinion now. TLDR: Overall game is OK, get it on a sale, a big sale, or wait til they actually ''finish'' the game. \n\nI like the community style setup, BUT Medieval Dynasty did it better. People matter in MD, they are just bodies in SD, one person is not better or worse than another, they all produce exactly the same and do not get better, MD they did and I loved that each person had their own skills. The AI in both games is meh at best but its utterly borked in SD. Enemie', 'At first this seems like a fun little crafting/empire building game but after a while it becomes apparent that it relies on an insane amount of grind to fill its content. \n\nWant to build a single house for some people to live in? Better build 3 or 4 hammers because those will keep breaking as you go. Need more logs to build those hammers (and also the house)? Better build 3 or 4 axes for that. \n\nThis coupled with an annoying progression system that is locked based on what regions you have yet to', 'Mostly Positive', 76.68, 24.65, 19.55);
INSERT INTO reviews VALUES (39386, 1702330, 988, 'Rune Factory 5 is like a part-time job where you grind endlessly—but hey, at least there are cute villagers and a cozy farm.', 'Rune Factory 4 is a better game in every way the only thing this has going for it is that it''s 3D', 'Mostly Positive', 77.94, 46.83, 39.88);
INSERT INTO reviews VALUES (39391, 1702390, 193, 'one of the only positive things i can recall from the Netherlands', 'Don’t be lured by the positive reviews of this game, as it is right now it’s not worth the price you are paying. The combat system it’s clunky and unbalanced. During a siege battle the pathing of different units is really bad and sometimes you have your units blocked inside the castle or on the wall. The campaign mode is really unbalanced, the fact that certain factions don’t have access to certain important structures or unites, as stone castles, make them really weak. Furthermore, the linear w', 'Very Positive', 88.08, 34.32, 3.78);
INSERT INTO reviews VALUES (39438, 1703340, 21461, 'I was told to quit the game and leave a good review then to turn the game back on.', 'I feel terribly sorry to give the game a thumb down. This game might be the most meaningful game in the past years, but I do feel that the game is teaching me not to do as the narrator said. In the new content, the producer showed his concern in negative reviews and gave a lot of comment on it to make me give this game a positive review? but I''ll give it a negative review instead as a part of the game. \nIn conclusion, you can''t miss the game. It''s a masterpiece.', 'Very Positive', 94.29, 6.62, 30.73);
INSERT INTO reviews VALUES (39451, 1703610, 151, 'it''s a good horror game (i''m afraid of women)', 'Preface: I''m aroace myself, but naturally I can only speak for myself in regards to how this game made me feel. There are going to be other people who feel differently.\nI was really excited when I saw the title for this game! There are plenty of dating sim/visual novels that have general friendship endings, but I''ve never seen one before that made pursuing a friendship with a specific person a goal, certainly not as opposed to a romantic one. But... I don''t know what I expected, but it wasn''t th', 'Overwhelmingly Positive', 95.36, 2.50, 1.07);
INSERT INTO reviews VALUES (39461, 1704080, 158, 'got this game on a wicked sale, im astonished by how much stuff is packed into this game, 10/10 will be climbing more bean stalks in the future', 'This game has an interesting concept, but it does not execute it well enough for it to be enjoyable. The whole task of climbing a beanstalk, shooting monsters, looting and escaping is good. However, you are 10000 feet up, and they don''t even give you a parachute, and making the escape rope spawn in near the escape horn would also make the a game more fun. Instead of starting with the glitchy climbing hooks, the game might be more fun starting with or solely using the grappling hook. This game ha', 'Very Positive', 85.44, 1.27, 1.30);
INSERT INTO reviews VALUES (39497, 1705140, 385, 'I wasn''t pulled in by the game''s appearance, but since it had a demo I figured I would try it and immediately lost the rest of my day. It almost scratches the same itch that an incremental clicker game does, even though it''s not that kind of game, because you start out in every shop having to manually monitor and place items and gradually discover ways to automate and exponentially increase your profits.\r\n\r\nAlso, the writing has caused me to laugh out loud on many occasions. It''s not going to bl', 'I got this game cause I was told it''s similar to Recettear and if you''re getting it for that reason, don''t. They''re both games about running a shop but the similarities end there. Recettear offers a lot more freedom in how you run the shop (since you pick your merchandise and there''s an actual in game economy system). Final profit is much more linear/railroaded in that regard.\r\n\r\nThat said outside of the shop there''s a lot of fun decisions that can affect your profit margins/story, I honestly wi', 'Overwhelmingly Positive', 95.84, 44.63, 50.47);
INSERT INTO reviews VALUES (39499, 1705180, 3746, 'A great tank simulation game, no repairing your parts or anything. Good if you want to escape from a certain snail but still want to play tank games', 'The game has promise - but the biggest issue isn’t bugs or balance, it’s the moderation.\n\nThe forums are run like a private club, not a feedback hub. Criticism gets shut down, threads are locked without reason, and valid concerns, or even compliments are treated like attacks. It’s hard to take "we want feedback" seriously when the mods act like gatekeepers instead of facilitators.\n\nEarly access relies on trust - between devs and players. Right now, that trust is being undermined by a hostile mod', 'Very Positive', 92.12, 6.13, 0.45);
INSERT INTO reviews VALUES (39511, 1705520, 121, 'This is a honest review, so I am being honest about this game. I bought this game because of the meme potential and also because I might been a little horny. I was absolutely flummoxed when I started playing this game. This game is a lot more\nthan just a anthropomorphic porn game. This game is short of a masterpiece. I have never before this game felt the same way that this game made me feel. I have experienced many feelings like anger, sadness and happiness while playing video games, but this i', 'THIS GAME HAS NO HOT WOLF 2D TITTIES OR PUSSY I HAD TO USE AN AUTO CLICKER TO GET TO THE SEX SCENE AND IT WAS ALL BLACK IM KILLING MYSELF. +', 'Mostly Positive', 75.21, 221.13, 0.90);
INSERT INTO reviews VALUES (39529, 1705930, 178, 'When I first came across the game, I wasn''t sure what to expect. I added it on my list and forgot about it for a bit. During a Steam Sale I bought it and am really happy that I did! \n\nIt''s a great game, gave me the best scares I had since a long time. Even if I did replay the game, I still got scared and the jumpscares did get me quite well. \n\nThe story is interesting and I enjoyed the twist in between and the choice in the end, you have to make. Since I am really easily scared, I am glad that t', 'SEEREM BAANGGETTTTTTT 😨😨😂😂😂', 'Very Positive', 92.13, 3.53, 1.97);
INSERT INTO reviews VALUES (39532, 1706090, 129, 'thanks patty', 'This _is_ a good puzzle game, I feel bad for giving it a bad review, I just can''t recommend it. It''s so unbelievably hard and each puzzle seems impossible until you figure it out. I will continue to play this game but with content being locked behind progress, I''m just stuck on island two with no way forward.\n', 'Overwhelmingly Positive', 99.22, 4.58, 7.00);
INSERT INTO reviews VALUES (39547, 1706360, 212, 'So this is a fake RTS . It''s a really good fake RTS and I love it for that. TLDR this is essentially a basebuilder/idler game . You base build and the units ram into one another until you or the enemy die. \n\nIt''s also very incomplete outside of the gameplay loop. Units aren''t done, Art feels rushed and prototypy. \n\nBut the gameplay loop is incredible. 17 hours in and I definitely got my value worth.', 'Could end up being a pretty good game but it is definitely not worth $30 atm.', 'Very Positive', 91.98, 23.97, 5.58);
INSERT INTO reviews VALUES (39601, 1707550, 436, 'Best game gimme granny 4 Dvloper idk how much time just give me granny 4', 'Balls', 'Very Positive', 92.89, 14.43, 0.15);
INSERT INTO reviews VALUES (39611, 1707650, 666, 'This game blindsided me completely with its existence since i had no idea Swords and Sandals was still even going, i had thought it was just something that would forever just be in my childhood but man, this... this improved and cleaned up a lot of the issues of the first few and generally just, expends on everything. Now there is some jank here and there but with such a small dev team I understand it what with how much cool stuff there is to do in this game, I do think it is very much worth you', '(A turn based game that focuses on rng more than outwitting your opponent) \n\nThe game is pretty decent, it adds way more content than the previous S&S games, but it still has many problems. For example, if you level up your stamina, it''s pretty much a waste, considering your skills increase in stamina every level for no reason, even though you''re not getting a better version of the skill or anything. Another huge problem is that you can be 15 levels up on a boss on very easy difficulty, yet you''', 'Very Positive', 85.14, 29.22, 168.73);
INSERT INTO reviews VALUES (39627, 1707870, 195, 'If you like MST3K and Rifftrax, you''ll enjoy this game. If you don''t like either of them then LEAVE THE BRONX!!!!', 'not as good as other party games.\nAlso there tends to be a VERY obvious house answer, and if you have a player that wants to min max, they can always vote house answer to deny other players points.\n\nPretty much ruins the game right there', 'Very Positive', 93.85, 30.93, 1.12);
INSERT INTO reviews VALUES (39631, 1707990, 497, 'Worst possible way to communicate with your audience and release a game. Almost feels like a shadow drop since nobody really knew if this was gonna be released today or not.\nGame looks and feels good too. 9/10', 'After being spoiled by the responsiveness of actual physics-based combat VR games like Blade and Sorcery, the core combat in this just feels sloppy and unsatisfying. Feels reminiscent of very early VR melee combat.', 'Mostly Positive', 75.45, 8.00, 1.23);
INSERT INTO reviews VALUES (39632, 1708010, 1161, 'If you haven''t watched the show I feel like this really wouldn''t be worth it because there is very backstory or exposition.\n\nOn the other hand, if you are a fan of the show, it is really fun to get back into the Expanse universe. Voice acting is great, especially Drummer, the fully 360 movement is unique & nicely done. It was over too quick but if you want to spend an evening listening to some beautiful lang belta pick up when on sale beratna.', 'There is no way to save the game manually. This makes it unplayable if you can only play in short spurts of around 20 minutes. Game companies need to respect there players time.', 'Mostly Positive', 76.23, 6.90, 0.35);
INSERT INTO reviews VALUES (39636, 1708110, 304, 'would heartily recommend to anyone who was super devoutly catholic at a young age because of all the "mortification of the flesh" and "hallucinatory mysticism" stuff and then grew up gay and full of seething petty rage', 'a great experience the first or so hour, i thought the dialog was (at first) engaging, the music beautiful, the characterisation interesting, the setting intriguing (i love nuns too), and the main character is all of the above. what eventually led me to be really turned off, despite the disclaimer this story takes place in the 1400s and the dialog reflect ideas from that time, is the total anachronism of the other nuns speech (the MC is perfectly fine); they talk like 21st century characters who', 'Overwhelmingly Positive', 99.01, 34.98, 1.37);
INSERT INTO reviews VALUES (39637, 1708150, 249, 'Juice is everything. There is nothing in the Fog. There is no greater honour than to serve the Juice Queen, and the sky is definitely not made of plywood.', 'it tooked my left testicile. do NOT reccomend', 'Overwhelmingly Positive', 98.39, 2.05, 0.42);
INSERT INTO reviews VALUES (39639, 1708190, 177, 'Easy 100 hidden rams (sheep, actually) achievements, BUT the game only requires about 10 minutes with no replayability.', 'Installing this game triggers a warning from anti virus software and won''t  allow the game to be installed or ran. Virus notification says it puts computer security at risk by potentially allowing people to remotely view your activity on your computer. Super disappointing, especially since I''ve played every other game in this series. The developer claims this is a false positive but I''ve had similar issues before on an update for another game that couldn''t be installed due to the same reasons. R', 'Overwhelmingly Positive', 98.31, 0.17, 0.10);
INSERT INTO reviews VALUES (39650, 1708460, 598, 'Can''t wait to see what this game will become, I can feel the potential in it. \n\nGlad you''re doing well again Kyle!', 'Got this when it first came out back in 2021, enjoyed it a lot. Came back to it in 2024, the tutorial bugs out during the second step, you cant create lobbies. The game is unplayable, do not purchase. \n\nI hate leaving negative reviews, especially for indie devs but when it cant be played and there has been no dev communication or fixes.. its best to warn people away from wasting money', 'Mixed', 65.72, 4.83, 9.37);
INSERT INTO reviews VALUES (39669, 1708850, 2409, 'Stabbed multiple people, used crowbar to kill 4 guys...i even blew up a car with c4 and yet they arrest and beat up my friend ''cause his character is black. 100% realistic simulator would play again', 'First game was superior in just about every way. This is a game that should''ve been early access at least, but probably should''ve just taken another year or two to work on it.', 'Mixed', 69.53, 12.57, 7.02);
INSERT INTO reviews VALUES (39677, 1709050, 249, 'Don’t make this your first deckbuilder game, but if you’ve played Slay the Spire and enjoyed it and enjoyed it and want a new experience, this is a great grab. Adding movement to the game adds an extra layer of strategy to the genre, and becomes even more challenging the further in you get. Playing as the character with guns was an intriguing experience, albeit a tougher one to get the hang of (although, the same may be said about the game as a whole). Fun and colorful graphics, great 80’s synth', 'Developer has not patched the game since 2022 and has not even acknowledged any reported bugs since April 2024.\nI ran into two major bugs in my one hour of playtime, so I cannot recommend it at this time.', 'Very Positive', 90.76, 45.93, 0.77);
INSERT INTO reviews VALUES (39683, 1709170, 324, 'I will bask in an array of pastels as they wash over every contour of my body. I am not important, and none of this was for the sake of others, it was all for my own. That''s why it matters. The sound of this game was simply enveloping, and I hope to come back to it later on down the road. I''ve enjoyed my time with this simple marsh a lot.', '+ The game is beautiful, the color changes according to the time are gorgeous. The biomes are unique and atmospheric.\n+ The sound design is great, I really liked finding critters by the sounds they emit\n+ An easter egg with a phone number really helps to understand the author''s idea better\n- The game becomes repetitive and a bit tedious towards the end with that ''catch them all'' vibe. There are a lot of interactive things just for the fun of it and I wish catching all the  critters was also up t', 'Overwhelmingly Positive', 95.68, 2.82, 3.72);
INSERT INTO reviews VALUES (39711, 1709730, 147, 'I originally played this on GOG, but had to buy it again on Steam so I could up vote it (and probably replay it to get all the achievements).  It''s that good!\n\nOwlsgard is up there with other classic point-and-click adventure games like Monkey Island and Sam & Max.  It''s kind of insane that every character has something unique to say about every item.  Not just repeating "I don''t want that" like you normally see.  And on top of that, everything is voice acted.\n\nI did run into three annoying "cli', 'asshole', 'Overwhelmingly Positive', 97.28, 0.10, 0.68);
INSERT INTO reviews VALUES (39717, 1709900, 776, 'The game can feel slow in the beginning, but it''s too good to ignore. It wraps a Tower Defense into the Slay the Spire formula exceptionally thoughtfully. If you enjoy deckbuilding and TD games, you''ll enjoy figuring out all the unique synergies and builds the game has to offer.\n\nIf you''re not feeling it with the starter decks, try at least sticking out until you unlock Everchanging (I think Level 10?). It''s a deck that begins with random cards every playthrough. It will allow you to start exper', 'If you''re looking for something like tower defense with *a few* roguelike factors and deck building, I should recommend Emberward. Don''t buy this if it isn''t in a deal.\nWhile this IS a roguelike, gameplay is (as of now, 15/july) dull. Played a game, found it interesting. Played another one and "oh, thats similar", then followed to play another half an hour doing just the same. You know, part of a roguelike deckbuilding experience *is* being able to play with different playstyles, unlock gameplay', 'Very Positive', 89.82, 17.42, 14.78);
INSERT INTO reviews VALUES (39727, 1710170, 671, 'This game came out over 20 years ago, there was never a game like it before and there has never been a game like it since. The best way I can describe the depth and satisfaction of the gameplay is to suggest it is like learning a musical instrument.', 'Only superficially similar to Souls games, the claim that it "pioneered the soulsborne genre" is a gross misrepresentation. This game suffers numerous technical issues if you try to run it on modern hardware, including crashes, animation bugs, subtitle timing problems, cutscene issues, and more. The controls have not aged well, even with the crude attempt at improvements in the settings.', 'Very Positive', 89.72, 196.73, 0.62);
INSERT INTO reviews VALUES (39745, 1710540, 258, 'While I''m recommending this game I will say it''s with the caveat that it''s... not actually a very good game. Do not get me wrong, it''s charming, and I loved it, it''s just very flawed. With a somewhat disappointing ending, dialogue trees that occasionally negate each other, a world that doesn''t really reward you for exploring, and extremely buggy minigames, I highly suggest this game if its on sale. I really hope the dev''s fix some of these issues someday ! It would be a stellar game!', 'This game was gearing up to be really enjoyable but ended at the climax of the story. I was just starting to get really invested in the characters when the game just...stops. There were plot points that didn''t get tied up, potential character growth that didn''t happen, and moving around the large map felt like a chore.', 'Mostly Positive', 71.32, 10.88, 19.43);
INSERT INTO reviews VALUES (39748, 1710580, 578, '1. you buy this for less than $5 on sale\n2. you go to overtake gg and you download the mod for the 2025 season\n', 'Forcing users to use an Xbox controller for a motorcycle game (this is definitely not a sim) is ludicrous. I''m glad I got this game on sale because it was a waste of money. If I could use it with a joystick (without having to use other software) then it would be better. If you are looking for a realistic motorcycle sim, this is not it. I''ve used about every racing sim ever made going back a long ways.', 'Mostly Positive', 79.07, 5.50, 1.12);
INSERT INTO reviews VALUES (39752, 1710670, 103, 'I’m not completely sure what to make of the game.  The graphics and combat are good. The tutorial was good at the beginning but then completely drops off. It said you need a relic and catalyst to activate the relic. I found the first relic and catalyst and see it in my inventory, but have no idea how to activate it. The inventory only shows the item, you cannot select it and do anything with it.  Not sure if that is by design?  I have not yet figured out a way to get the dog statue to move and p', 'They lock you in the second room without explaining what to do, index controllers have no tracking, the game looks like its made with free assets and it runs and controls like shit. Don''t buy this thinly veiled quest game garbage', 'Mostly Positive', 79.61, 8.18, 0.30);
INSERT INTO reviews VALUES (39798, 1711610, 203, 'This game is a janky, messy machination of unfinished goodness that will probably never get another update.\n\nHowever, if you hate yourself you''ll love this game. If you suck at auto-battlers you will find this game difficult. If you''re good at auto-battlers you will find this game difficult.\n\nIn this game your biggest enemy is your past selves decisions. You make a broken build, you will have to fight it later.\n\nThere is no winning, only suffering, can be very repetitive, can be rng heavy. I lik', 'Game isn''t finished and doesn''t seem like it ever will be. Stay away!', 'Mostly Positive', 73.89, 26.90, 40.97);
INSERT INTO reviews VALUES (39810, 1711950, 487, 'It''s like Gwent, only for people who don''t play nicely with others. I like Gwent, but unlike humans, the computer doesn''t seem to rage quit (yet).', 'Pros:\n    Gwent\n\nCons:\n    everything else\n', 'Mixed', 59.55, 122.08, 7.22);
INSERT INTO reviews VALUES (39849, 1712840, 280, 'If you''re a die hard fan of the borderlands series, you have to buy this! Yes it is a repackage of a borderlands 2 dlc, but they did a really nice job on it! There''s two playthroughs, normal and TVHM, and the scaling is done very well; for every level up you gain 2 skill points, allowing you to have really cool builds even at level 20 or 30! There''s two imported quests from BL2, but they''re reskinned in a very cool way, they''re not just exactly the same as BL2. ALSO. They added a new shield type', 'Spyware collecting all my information outside the game and not owning the game I paid for are you serious. Until these terms of service get reversed uninstalling all take two games and never purchasing one again.', 'Mixed', 66.79, 12.90, 9.85);
INSERT INTO reviews VALUES (39871, 1713350, 751, 'Great graphics and many things to think about as you try to survive...it''s like ''spinning plates''...if you can''t multi-task....you won''t last long.  Intriguing and dangerous....very additive. Loving it and I''m a 72 year old pensioner!!! lol', 'I really liked this game when I watched my favorite youtuber play it. It looked really good. It reminded me of stranded deep, but when i started playing it was buggy as all hell. I''m not really picky when it comes to this kind of stuff, but when its game breaking bugs. I gave it chance after chance. so waited a few months to see if they can fix some of the bugs out. I started playing again a few days ago, its just not fun. there''s no survivability, all you have to do is farm coconuts and your go', 'Mostly Positive', 70.84, 231.87, 19.93);
INSERT INTO reviews VALUES (39891, 1713810, 506, 'I honestly see the potenzial of this game, but lack of coop (only split-screen).\n\nFrom my point of view this game it feel like incompleted and i dont think the developer will made a big upgrade, if they do pls put also a modern coop it will make the game more great on the preparation and even funnier when the insect raid you.\n\nmy idea on a new mode is an another infinite raid but you dont need to protect the base but only yourself, and on coop we can make the game more hard and put it a revive o', 'There are other games to do the mine, defend loop better. Having to go into my inventory to switch between my drill and gun is annoying. The reviews say its a very slow burn and takes a long time to get the unlocks to build out base and that its about 80% drilling and 20% tower defense and that something you feel pretty quickly. I personally need a bit more action or at least other things to do for that other 80% of the game. I can see the appeal but it''s not for me', 'Mostly Positive', 76.68, 8.85, 0.38);
INSERT INTO reviews VALUES (39911, 1714250, 124, 'The game is fun but repetitive, basically doing the same thing over and over again, so the game gets boring easily when you have reached over 50 days in the game. The playtime spent with each animal, especially the rabbits, is very time-consuming and the way how the mini game works really hurts your eyes after several rounds. Also, whoever came up with bathing the dog in less than 45 seconds is unrealistic and needs a life. Overall, the game is ok. 7.5/10.', 'I want to love this game but the bugs keep me from being able to do so. i hope that one day the devs update their games instead of just releasing a new game every month and then not updating their new ones ever again.', 'Very Positive', 83.06, 19.67, 88.30);
INSERT INTO reviews VALUES (39923, 1714420, 532, 'Zionists are noticing this game and trying to get it banned.\n\nIf Steam ban this game for "depicting terrorism" they better ban CS2, All CODs and BFs as they have the same premise with the addition of history revisionism, but since in their games the enemies are brown and from the global south it is ok.\n\n10/10 would recommend, GOTD!\n\nPalestina livre 🔻🔻🔻', 'just a hamas propaganda', 'Overwhelmingly Positive', 96.24, 1.02, 3.05);
INSERT INTO reviews VALUES (39932, 1714580, 180, 'This is a very unique time to be playing this game where there''s an ordained Hero running around with a giant bladed weapon making everything worse for everyone and all the townsfolk are just letting it happen.', 'To be honest, I don''t recommend playing this game but I DO like it. \nIt has a really cool and ahead-of-its-time concept, but unfortunately the gameplay is extremely tedious, and sometimes VERY cryptic. And I didn''t find any of it to be fun. Interesting, sure, but not fun. It might just be a problem with going back to old games after playing games with modern conveniences, but being forced to wait real time if you want to get to a certain point, the slowness of a lot of transition cutscenes, and ', 'Overwhelmingly Positive', 96.11, 14.88, 22.50);
INSERT INTO reviews VALUES (39933, 1714590, 545, 'Saw an option to toggle Pride Flag Billboards, I decided I wanted them enabled so I toggled them.\nTurns out that toggle makes the Billboards exclusively Pride Flags and there was never a way to disable them if I wanted to.\nThat got a good laugh out of me.\n\nOh yeah also game''s good.', 'This is a great game on paper that is executed flawlessly.... and that what makes this hard for me. I enjoy racing games like the next guy and i would play the hell out of most wanted back in the day. The thing for this game though is its pilfered by political messaging, I noticed that some of the billboards just had the Gender flag plastered with no rhyme or reason and of course you would get a "ACAB" comic splat if you hit the cop cars some times. now let me tell you why political placement ma', 'Very Positive', 92.84, 5.22, 0.55);
INSERT INTO reviews VALUES (39955, 1715130, 2839, 'Crysis Remastered is a great game. If you ever played the original Crysis before, then you are in for a treat. The graphics and overall game mechanics have been modernized. The audio to the game seems to be largely untouched but is nonetheless very apropos to the overall game.\n\nHighly recommended!', 'Honestly, it''s impressive how bad this "remaster" is. I mean, Crysis has always been a benchmark title but while the OG tested your hardware, this version tests your patience more than anything. After you apply all the necessary mods and change all the parameters, you can finally play... sorry pray - that it doesn’t randomly crash whenever you shoot an enemy, AI doesn’t get bugged or the particle effect doesn’t show as a 2D sprite. And the best joke? Even maxed out it looks AND runs worse than t', 'Mostly Positive', 70.24, 10.72, 6.13);
INSERT INTO reviews VALUES (39961, 1715280, 622, 'Went to Keflavík\nStole a bunch of ground vehicles\ndrove them all around the airport causing mass delays and chaos\nnever got punished\nwent home and played airport sim\n\n10/10 game for having my countries (basically) Only international airport (Akureyri and reykjavik are too but not used often)', 'As a former ground handler who somewhat misses the job I wanted to like this game so so much.\r\n\r\nEach update I come back and play for a bit, but the bugs remain.  It''s basically impossible to complete a single scenario as things ***will*** bug out.  Multiplayer is ok, but the discord is already almost dead.  The game had so much potential and the interactions of the game are really good, but the bugs just kill it.', 'Mostly Positive', 70.90, 9.92, 15.62);
INSERT INTO reviews VALUES (39977, 1715590, 391, 'Come for the nostalgic shooter vibes, stay for the charming pixel art, vibrant atmosphere, and super fun, user-friendly level editor. Word is, you can easily sink hundreds of hours into it.', 'I really wanted to like Wizordum. It has a lot of charm to it, with a good retro artstyle and decent magic combat.\n\nBut it''s bland, oh so bland. It''s slower paced than a snail caught in a glue trap. The levels are massive and labyrinthine with enemy counts in the hundreds, but most of the time you''ll only be fighting 2-3 enemies per room. You''ll likely spend more time exploring, breaking barrels and opening chests than actually fighting.\n\nMost of the enemies are not very engaging to fight. You g', 'Very Positive', 92.84, 842.32, 6.20);
INSERT INTO reviews VALUES (39983, 1715730, 1525, 'UPDATE YOUURRR GAME, its a fun game but comon dont let it die devs', 'Its a great game with some great ideas but sadly there''s not been an update since April 2024 when before that there were regular updates. Also heard that dev been working on another game idea. so for that reason i would avoid.\nThis is an unfinished game.\n\nWill happily change review if dev ever finishes the game. but i wont hold my breath.', 'Very Positive', 90.10, 45.47, 21.02);
INSERT INTO reviews VALUES (40033, 1716740, 81088, 'I love Starfield, BUT you are not listening to your community at all. There is a reason I have a 1000hrs on Skyrim, and there is a reason why I haven''t played Starfield in 6 months. You know how you could make Starfield the best game out there, I don''t know why you aren''t doing it. Please make Starfield the game you promised us it would be.', 'I want this game to be good, so badly. It just isn''t and I don''t think it ever will be. It''s one of the worst full-price games I''ve ever bought and it is criminal they are charging $70 for it.', 'Mixed', 57.96, 466.30, 62.83);
INSERT INTO reviews VALUES (40045, 1716940, 186, 'I''m enjoying this game very much so far! The gameplay is fun and challenging without being overly complex, so it''s great for jumping into when I have a little spare time or I''m listening to podcasts. What makes it stand out from other card battlers is the theme of mythology and its art-style, which I personally find wonderful and very relevant to my interests.', 'Update: I actually really loved this game; but support for it has been cut off in favor of a cruddy mobile version of the game.\nIn good faith, I can only tell people that, if they wish to buy the game, it will be as is. There will be no new gods, balance patches, or any of the sort. ... R.I.P. draw card buffs... (It bugs out and acts like level 1 again...)\n\nThis game is still fun. There are lots of toys to experiment with, though meta builds certainly exist because that''s just a nature of this g', 'Mixed', 59.68, 1.97, 40.08);
INSERT INTO reviews VALUES (40051, 1717090, 424, 'it''s a strange pleasure to have to tone down your build to keep the game from crashing', 'It''s fun for a few hours until you realize the gameplay loop is extremely monotonous. You have to grind for hours to advance well past the amount of time you''re even being challenged by the level you''re at.', 'Very Positive', 87.03, 93.95, 8.35);
INSERT INTO reviews VALUES (40057, 1717250, 252, 'dont buy yet but is has some EXTREME potential if the devs keep up the updates', 'It wants to be Men Of War, but it isn''t. It does nothing well, and everything it does, it does poorly. \n\nA cover based game with no cover?\n\nWhat?\n\nNot even busty rat girl can overcome this poor attempt at... whatever they''re going for.', 'Mixed', 57.14, 1.25, 0.25);
INSERT INTO reviews VALUES (40068, 1717510, 157, 'Hop to it! \r\nThis is a cute little game that you should definitely not frog-et about. It''s toad-ally worth playing this cozy little game about helping frogs on their island. There''s no real stakes as you can''t really croak but it''s still a pond-stomping good time. \r\nGameplay consists of some very mild platforming and exploration around Frog Island, as you help the denizens with their various requests, all the while trying to get your shipwreck back in shipshape so you can ship out to new adventu', 'I''m sorry but nothing about this game other than the art direction and maybe controls were well designed. The tasks are made very vague and the world is far too big with no form of map that I could find to make navigation easier. There''s no sort of tutorial to familiarize yourself with the ideas of the game either, it pretty much just expects you to learn without communicating anything. Some quests are straightforward, but most aren''t, and due to the large world you''ll most likely get lost in no', 'Mostly Positive', 71.97, 5.08, 0.55);
INSERT INTO reviews VALUES (40072, 1717640, 211, 'This not just another Slay the Spire clone.\r\nAnd that is good.\r\n\r\nIf anything, it''s a super "lite" version of Mage Knight, with an L5R skin.\r\nAnd that is great.', 'As others have said, beautiful game until it crashes with a corrupted save, leaving you unable to ever finish the game. This occurs over two accounts& computers in our household alone, in different levels. The issue has been reported multiple times for over a year now without any response or action taken by the developer. Inconceivable that this is still being sold.', 'Mostly Positive', 77.73, 6.83, 45.78);
INSERT INTO reviews VALUES (40076, 1717770, 1914, 'Insane, absolutely absurd amounts of personality crammed into this game.\r\nvery good very fun, wish it lasted longer so i can play more with it and see what else zeekers could come up with.\r\n10/10 would simp for shrimp again', 'If you find "intentionally annoying" funny, you''ll like the game-design. If not, this is just a rage game with a slapped on "emotional climax" it pushes in, which is completely unrelated to anything that happens in the game and has almost 0 build up except some text boxes at the end of the game. \nIn fact the narrative of this game has almost no relation to the game itself. It''s just someone telling you a story between each level.\nYou would have a better experience just reading the story rather t', 'Overwhelmingly Positive', 99.27, 10.00, 8.27);
INSERT INTO reviews VALUES (40091, 1718130, 1368, 'https://steamcommunity.com/sharedfiles/filedetails/?id=2885421579\nhttps://steamcommunity.com/sharedfiles/filedetails/?id=2884840361\nhttps://steamcommunity.com/sharedfiles/filedetails/?id=2885421615', 'Meh.\nIf you''re NOT an SCP fan then this game is... alright, I guess. Bland, but not atrocious. The graphics (and visuals in general) are fine overall, although the intro had given me high expectations that weren''t met by the rest of the game. But there is little to no gameplay, it''s essentially just a bunch of stories loosely based on SCPs.\nIf you''re an SCP fan then this game will feel like a big letdown. The universe is clumsily depicted and the stories are kinda mediocre.\nShame.', 'Very Positive', 86.11, 7.97, 4.78);
INSERT INTO reviews VALUES (40092, 1718160, 205, 'The occipital lobe of the human brain takes approximately 18% of the total space and is dedicated largely to visual processing. \nThis game is fully aware of and exploits that fact. Take that as you will.', 'Unplayable, unmitigable input lag. The game deserves better.', 'Overwhelmingly Positive', 97.56, 12.62, 8.92);
INSERT INTO reviews VALUES (40102, 1718570, 2840, 'This game is honestly a masterpiece. KEIZO''s 15 years of work really paid off, he made something truly special here. It''s been awhile since I couldn''t put down a singleplayer game, and since I played something where the pure passion of the developer was tangible while playing. Story is excellent (though I''m a sucker for time travel and the butterfly effect, and we ignore how cringe chapter 4 was) but more than that I just love the compelling sense of adventure it provides, and just how ridiculou', 'I enjoyed the game a lot until it became way too horned up, then I tolerated it. (seriously, what is with those goofy wubbly-jubbly animations?)\r\n\r\nI tolerated the game until it told me to go fuck myself with a multi-form boss fight that when you die during the second phase and have to start over, the game sends you back to the start of the first phase without any of the items you used during the previous attempt.\r\n\r\nI am now putting this down and not coming back to it because it''s wasted enough', 'Overwhelmingly Positive', 95.18, 122.72, 54.53);
INSERT INTO reviews VALUES (40110, 1718870, 3804, 'Installed the game.\r\nRefunded the game.\r\nInstantly regretted refunding the game.\r\nBuilt a rocket.\r\nFlew it straight into the sun.\r\nDid it over and over again.\r\n10/10.', 'Cant sex the rocket :(', 'Overwhelmingly Positive', 96.53, 10.75, 112.73);
INSERT INTO reviews VALUES (40112, 1718910, 217, 'Fantastic game!\nCryptograms and classic books are a great combination. Very entertaining and relaxing.\nIt''s also great that part of the money goes to Project Gutenberg.', 'Kind of a plain puzzle game. It''s just a simple find-which-letter-goes-where type of things, with nothing more to it.\nI''m not sure why I expected more out of it - more mechanics, a story, progression. It''s just quotes out of books.\n\nWithout any hints it''s too difficult, and the next difficulty gives you 3 common letters so it''s not very hard. \nAll in all I think you should be getting more for the price.', 'Overwhelmingly Positive', 99.54, 19.60, 0.63);
INSERT INTO reviews VALUES (40122, 1719180, 131, 'This was one of the first games from Randumb Studios since The Test series where the answers felt fresher, new, and more engaging. 4/10\n\nScore: 431 \nSecret Word: Positivity', 'Ok , so I answer a ton of questions for 30 or so minutes and then what? Thats it ?now what? I read the description and well damn I don''t get this .. But for $1.59 it was better than watching a rerun of "Alf" in Spanish ..', 'Overwhelmingly Positive', 98.47, 0.77, 0.62);
INSERT INTO reviews VALUES (40129, 1719310, 262, 'Got banned from Valorant for third-party software while this masterpiece played in the background. Worth it. 10/10', 'too much reading to the point where its not even a sexual content game anymore.\nit starts really slow and alot of none sense added to the game. \nhow did they manage to make a porn game boring?\n\neven with imagination i Have. this literally is not as fun as part 1', 'Overwhelmingly Positive', 99.24, 8.50, 4.72);
INSERT INTO reviews VALUES (40197, 1720850, 183, 'Do you like esoteric programming languages?\nAnd recursion?\nIf so, get some help\n', 'I''m sure that this is a great game, but I was too young to play it properly and cheated all of the answers. Don''t make my mistake, either play it now or wait until you can.', 'Very Positive', 91.80, 2.40, 1.93);
INSERT INTO reviews VALUES (40207, 1721060, 715, 'This game is fun and I do reccomend it, but pc players should be aware that there is no ultrawide support, and based on the discord comments there will never be.  They are saying that it''s a design choice.  Still a good game, but this is something you should definitely know.', 'I don''t know if this was on purpose, but when I first installed and launched the game, I didn''t encounter the shady EULA that many are discussing. It wasn''t until the second time I launched the game that I was presented with the option to opt out (and obviously you can''t start the game if you don''t accept), but by that point, I was already outside of Steam''s refund window. Additionally, Windows has only now detected the suspicious, virus-like executable. I''m not saying *it is* a virus, but this ', 'Mostly Positive', 72.31, 31.78, 6.12);
INSERT INTO reviews VALUES (40213, 1721170, 192, 'Overall the game as pretty fun to play. It had a quirky style and the story for the most part helped the games overall feel.\n\nI did have some issues with the ending though. It so unsatisfying. We spend the whole story hinting and stuff and telling a story shrouded in doubt and mystery. And when it come to the end where the pieces should fit together, it just doesn''t feel like it fell into place the right way. There was so much that could have been done with it that didn''t happen, and that left m', 'Puzzles are rather boring and easy. Had some annoying bugs throughout my gameplay as well.', 'Very Positive', 91.67, 12.73, 9.18);
INSERT INTO reviews VALUES (40225, 1721470, 16005, 'i loved it, i honestly loved the gameplay and story. it was  little buggy but the devs fixed that really quiclkly. altho justice for piano saurus', 'Paid like $20 for the base game just for it to become free and for them to charge me for chapter 2 DLC.', 'Very Positive', 80.41, 7.07, 11.90);
INSERT INTO reviews VALUES (40230, 1721530, 152, 'Fun adventure - strongly reminiscent of Lucas Games.', 'I expected a Trek like game with the long winded speeches and complex moral quandaries, instead you get... I don''t know, you''re just some guy on an automated ship with some really smartass (not in a good way) AI companions, it''s trying to be witty, but not the high brow late 90s/early 2000s BBC witty, more like current BBC ''witty.''\n\nOne of the first tasks in the game is a rescue operation, it''s a guy that''s been in stasis for a loong time and all his friends are dead, his message says he doesn''t', 'Very Positive', 90.13, 83.13, 0.72);
INSERT INTO reviews VALUES (40243, 1721870, 304, 'this is the best roughlite game ive played in a while 10/10 you should play\r\nive had this game for 3hr but i have 8 hr of playtime', 'The game is an awful grindy mess that feels much the same to play at 10 hours as it did at 1. I''ve played as all the non-blackmarket ships and the difference in play style is virtually nonexistent since you''re likely going to be making the same choices in build over and over in order to get anywhere.\n\nAfter gaining access to the Black Market, everything in it is overly expensive and not worth buying to begin with. \n\nAlso, for whatever reason, the game requires you to be online to buy any of the ', 'Very Positive', 87.83, 12.53, 10.73);
INSERT INTO reviews VALUES (40269, 1722520, 230, 'good  hidden game with color filling and features', 'Find all 4  and the first game are fun, but 2 & 3 are brutal, and it stems from what I would call poor drawing of the items you''re looking for.  Can''t say I recommend this one.', 'Overwhelmingly Positive', 96.09, 18.65, 0.43);
INSERT INTO reviews VALUES (40274, 1722620, 713, 'When you play lava levels Toree wears a little Indiana Jones hat. This is what gaming is all about.', 'smile over sundance', 'Overwhelmingly Positive', 97.48, 0.53, 0.23);
INSERT INTO reviews VALUES (40281, 1722760, 115, 'My Singing FENTANYL Playground', 'This game is just too expensive, it is probably worth $10-$15.', 'Very Positive', 81.74, 1.78, 3.70);
INSERT INTO reviews VALUES (40288, 1722840, 324, 'Already have the board game, and was sometimes playing the single-player version. Saw it recently on steam, but decided against buying it, because why buy the same game twice?\n\nWell, for one, this is way more convenient. Don''t have to count the points yourself. And I also love how many game modes you have. Got it on sale, didn''t regret it. Currently playing through the single-player content. Might wander into multiplayer once that''s done, but we''ll see about that. Currently, having a blast playi', 'I have been playing months, spent so many hours and I have ti say, that there are some things that really need to be fixed. The whole experience gets ruined. There should be a control of who sits at your game and there should be a shorter timer. People join and either take 4 minutes to play or they leave if they don''t like their hand. We should be able to choose who should we accept in a game we create. And fix the timer...', 'Very Positive', 89.51, 23.77, 1104.25);
INSERT INTO reviews VALUES (40289, 1722860, 619, 'It''s munchkin, but brought to PC! Great board game, and I wouldn''t have refunded it if Couch Co-op was an option.\n\nNewsflash: Couch Co-op is NOT an option. walk away if you want couch co-op.', 'Requires 3rd party account to play online; no Steam integration. (This is the big killer, the rest is just annoying)\r\nUI is quite bad. Buttons to do things are hard to find and often not present. The timer for actions is inconsistent. Parts of the turn have no timer and can be unclear who you''re waiting to act, while combat timers are too fast for the current player and too long for enemies. The timing system seems to change after asking someone for help in combat, and it was difficult to find t', 'Mostly Positive', 73.67, 0.52, 2.70);
INSERT INTO reviews VALUES (40290, 1722870, 275, 'If you like board games but have no friends like me, this is perfect. Plays like the original board game and when playing the AI acts like a bunch of jerks, like the friends we don''t have and will take the good cards out of spite. The animations are fine and I am looking forward to Direwolf hopefully putting out more boards/expansion sets.\r\nGod I''m lonely', 'The game is fantastic, super fun to play in a couch setting on a big TV with friends and family, however...\n\nYou know what''s not fun? Game breaking bugs not touched on for months, paired with developers that do not communicate at all, leads me to believe this game is as dead as it will ever be. Do not waste your money, ESPECIALLY if you think they might add the other maps in the future, they won''t. The game is literally unplayable because of a bug that hides your cards when the turn changes, so ', 'Very Positive', 92.00, 143.45, 107.15);
INSERT INTO reviews VALUES (40321, 1723780, 668, '4.5/5 Realistic Finnish cottage experience. \nOnly unrealistic part is that you can''t drown.\n\n7 out of 10 Finnish people drown every summer.', 'Let’s start with the good part first. The game is very detailed, and it really captures the authentic Finnish vibe. Sometimes you just sit on the porch in the morning, smoking a cigarette, drinking coffee, and soaking in the atmosphere the game serves up — and you simply enjoy it.\n\nHowever, I still can’t wholeheartedly recommend it, because the developers haven’t made any meaningful updates to the game in months. I played it with a friend and we had an incredible time, but this long wait for upd', 'Very Positive', 94.16, 17.48, 8.58);
INSERT INTO reviews VALUES (40331, 1724050, 424, 'me and my best buddy jerked off to this together! a pain in the ass to unlock the sex scenes in comparison to the first one, but I''d say it''s worth it~', 'too many nudity :(', 'Very Positive', 94.81, 2.82, 6.62);
INSERT INTO reviews VALUES (40338, 1724140, 232, 'If you love fun, wishlist Craftomation 101 now. Entirely unique gameplay with programmable units. The groundbreaking UX logic built by this team will trickle into the ENTIRE next generation of RTS/Strategy games. In 5 years, failure to enable the functionality seen in this lil'' indy game will SINK triple-A titles. This is what genius looks like. This is what the future looks like. BRILLIANT!', 'I like it but it became a game of burning fuel to farm items to burn fuel. i had 20+ bots just collecting and burning fuel while 2 were actually used to play the game\n\nfuel consumption should be cut in half', 'Very Positive', 81.47, 5.82, 7.33);
INSERT INTO reviews VALUES (40350, 1724390, 134, 'Great game from it''s genre with attitude and heavy metal and demons.', 'DONT BUY\r\n\r\nlike I know this is harsh but there are a lot of games that are just so much better. This game does nothing good and is RNG heavy af with no real sense of progression. \r\n\r\nJust play Slay the Spire or Monster Train', 'Mixed', 68.66, 19.57, 11.12);
INSERT INTO reviews VALUES (40354, 1724440, 207, 'it is amazing and i would reccomend it to any UEBS players', 'I purchased this game and their 2 other games. It was pretty good for a few hours/days but then it got boring. If their was more troops/mods like uebs I''d enjoying it much more. Also the game gets updated very few times.', 'Very Positive', 87.44, 19.13, 6.90);
INSERT INTO reviews VALUES (40396, 1725640, 862, 'This game really feels like the developer made it just to show off their cats.\n\n/ᐠ｡‸｡ᐟ\\', 'I loved the cat drawings and I love sudoku, but I can''t recommend this game :/ .\nThis game lacks so many QOL to make this actually enjoyable. The early levels are nice, but when I was in the extra levels I was super annoyed of how bare bones this game is.\nThe lack of rewind button and a fast way to note each cell is the worst parts. Also the visual of the background/cells keep changing when I leave a puzzle.', 'Overwhelmingly Positive', 98.38, 2.83, 8.25);
INSERT INTO reviews VALUES (40413, 1726130, 155, 'I’m hooked on this game! It’s super addictive and enjoyable, striking the perfect balance between being slightly challenging and highly engaging. I love the freedom to build my own structures and craft a variety of clothing items and weapons, which adds so much depth to the gameplay. I do wish there was more guidance on unlocking certain crafts, though – after 140 hours, I still haven’t figured out how to mine copper and am working with stone tools. But even with that minor frustration, it’s a c', 'Like others have complained it''s clunky with controls, I couldn''t be bothered to finish the tutorial. I was hoping from the reviews from almost a year ago it''d be different by now, but it''s not. maybe I''ll try it again if the devs start updating the game again. They did downsize in july 2024 though they seemed to stop updating at the end of november 2024, as it is currrently march 2024 without any word on steam from the devs.\n\nSo if you INSIST on buying the game don''t wait and hope they''ll fix t', 'Very Positive', 87.10, 148.58, 0.17);
INSERT INTO reviews VALUES (40416, 1726190, 887, 'This game is really cool! took about 12 hours for a slower playthrough, redoing some bosses for higher scores. Stylistically, musically, and artistically, this game is just straight up really sweet. It can be a little corny, but it works so well for what they''re going for. I had a dumbass grin on my face the entire time.\n\nWhere the game is lacking though is in moment-to-moment gameplay polish. Every boss has some attacks that work really well for the kind of game they''ve made: They sync up well ', 'I really wanted to like this game, but I just didn''t. The gameplay did not feel good, the characters didn''t control well and the music integration just didn''t feel right. I like the actual soundtrack and visuals, but the cutscenes and story were painful, and the gameplay was painful. I''ve never felt so sad about not liking something. ~PR0XIDIAN', 'Very Positive', 92.56, 12.05, 0.78);
INSERT INTO reviews VALUES (40425, 1726400, 1440, 'The puzzles were tough for me but still, | had fun playing this :) https://youtu.be/5ggucKzrc7k', 'Game puzzle như lồn', 'Very Positive', 92.01, 4.38, 3.08);
INSERT INTO reviews VALUES (40438, 1726730, 148, 'Good game and an interesting sequel to Summer of 58 I guess. At least I''d say that it''s taking place in the same universe if not being a direct sequel. Either way, it''s another great game from Emika. I really enjoy these.', 'You Must is a short horror game in which you have to play a game to find an item in an abandoned location. Apart from just one creature that lurks around and can easily be evaded, the game just throws unnecessary scares at you, thinking that the weak plot will bring some benefit. Another point is the crashes in places where if you''re not careful you''ll have to return to the last save. You Must Not Buy This!\r\n', 'Mixed', 68.24, 4.03, 4.03);
INSERT INTO reviews VALUES (40439, 1726750, 121, 'A nice game, trying to find the cats and people.  Only bad thing is on the main picture, I couldn''t move the picture unlike the other pictures, I had to go mental with the mouse moving just to get it to move.\n\nUpdate: I reinstalled my PC and game, and the game works as normal.', 'I have all games in this series so far (this is the 6th), and it pains me to say I cannot recommend this one.\n\nMany/most of the elves have angry facial expressions, which is somewhat of a let down considering the theme of the game.\n\nPlenty of content for the price; the final bonus level (Snowball fight) also requires finding characters, many of which are not really distinctive from each other, and the thumbnails are so small they''re almost useless... so it turned into a clickfest hoping to get l', 'Overwhelmingly Positive', 97.52, 3.30, 3.62);
INSERT INTO reviews VALUES (40440, 1726760, 215, 'I am god awful at platformers, and seldom play them. \n\nI put 80 hours into this game and nearly 100%''d it. \n\nThat should tell you enough.', 'This is the most mixed I''ve felt on a game in like ever. For each thing the game does amazingly, there''s some other problem attached. fun movement but there''s screen crunch so its hard to use it properly, a ton of content but most of the content is secret hidden stuff, the sprites look great but the low detail makes it hard to see stuff sometimes, etc. etc. the only thing that doesn''t have an issue is the soundtrack. difficulty has also been very inconsistent due to very little access to healing', 'Overwhelmingly Positive', 96.74, 72.42, 7.47);
INSERT INTO reviews VALUES (40458, 1727210, 100, 'A close friend of mine, vtZda, took her own life in autumn 2023, and this was her favourite game before she made her final choice. She kept talking about it, and she was part of this game''s fan creation community. It looked like she had much fun, and the people within that community seemed to offer her much mental support, even if they probably didn''t know about it. She once said if she died, she''d appreciate the full version of this game burned for her. So I made a mental note to check on it fo', 'Great concept\r\nGreat music and atmosphere\r\nJapanese=cool\r\n\r\nIt will never be finished. I might be panicking and the next episode is coming out tomorrow, but it''s been ~2 years since the last one. I''ve played Ghostopia and it''s the same there.\r\nThe devs might also be confusing people with the game version being 1.1.3, even tho it''s early access.\r\nThe third and the fourth bosses have completely meaningless dialogues, so there is basically only 1h of good gameplay/narrative.', 'Overwhelmingly Positive', 96.00, 2.30, 4.28);
INSERT INTO reviews VALUES (40467, 1727420, 130, '10/10\r\nMusic Nerds Only. \r\nNerds with a DAW OK.\r\nEverybody else go away.\r\n10/10\r\n', 'Hey, dev, if you''re reading this, add default sounds to the program, like guitar and piano. Maybe a workshop for others to add more sounds, but i don''t think the program is completly good if you need another to run it correctly.\n\nI like this program, but it feels incomplete', 'Overwhelmingly Positive', 96.92, 8.02, 1.33);
INSERT INTO reviews VALUES (40523, 1728660, 130, 'Probably one of the best arcade rally games out there. While it may seem like it''s an alternative to art of rally, the only thing in common is rallying in top-down view. Apart from that the car handling is more on the arcade side, as in pure "smash the throttle and drift" style, has a different, more grounded stylistic approach and features a co-driver - something that art of rally never bothered implementing and it''s a shame, because this changes a lot, even if it''s a top down driving game.\n\nOv', 'Those guys don''t know geography, they think Palestine is a country, while leisurly leaving out >150 official world state flags. Also spectators double as springboards here.', 'Very Positive', 92.31, 32.28, 4.90);
INSERT INTO reviews VALUES (40531, 1728840, 148, '♫ Diggy diggy hole ♫', 'The game is basically dead, no updates since march iirc. Feels clunky in its current state, wait for final release.', 'Mixed', 64.86, 485.73, 0.35);
INSERT INTO reviews VALUES (40552, 1729300, 119, 'i wish there was combat and multiplayer', 'IT FUCKING WONT RUN ANYMORE IT RAN GOOD THE FIRST TIME BUT NOW IT''S FUCKING BROKEN WHAT?!?!?!?!?! (also add controller support. and multi player)', 'Very Positive', 89.08, 8.03, 8.42);
INSERT INTO reviews VALUES (40576, 1729940, 116, 'Don''t starve tribals meets frostpunk/gorn. Some fun mechanics but not as wild or in depth as either game. You have no direct control over your tribals and have to rely on extremely slow explore towers or placing lumberjacks everywhere to extend vision.\n\nThe tree regrowth isn''t explained anywhere and is extremely important since you need trees to keep the fire going. Fear even during the day sucks snd no real way to grt people out of it.\n\nThere should be more mechanics to get people level headed ', 'A game that had amazing potential turned into another lesson about buying games in EA. It’s a gamble. Sometimes you buy into devs like from project zomboid, other times you buy into devs like here…. Scammers and fraudsters in my opinion. \n\nThis game is now complete abandonware and the dev sneakily took it out of EA even though basic bugs and lack of content are apparent. DO NOT BUY THIS GAME. \n\nI REPEAT. DO NOT BUY THIS.', 'Mixed', 61.21, 1.62, 6.05);
INSERT INTO reviews VALUES (40600, 1730360, 580, 'The occasional naked men turn me on', 'I mean it''s just a find the difference puzzle but sometimes a guy with a suit is mean to you. You already know if you want this without my review so I don''t know why you''re reading this but in case this actually sways your opinion I''d like to just recommend basically any other game. And for the record if horror is what you are looking for this game is ANTI-scary. It also clearly features AI design/art.', 'Overwhelmingly Positive', 97.59, 4.07, 7.40);
INSERT INTO reviews VALUES (40616, 1730650, 309, 'instructions unclear. Just duct taped my grandma to the ceiling', 'so buggy that i cant even get past tutorial and devs abandoned game only a month after it released. just a blatant cashgrab.', 'Mixed', 65.05, 1.67, 0.23);
INSERT INTO reviews VALUES (40618, 1730680, 1195, 'Never has a series of scrimblo bimblo mascot platformers hit me with such emotional gut punches through unexpectedly amazing stories while still retaining simple yet extremely tight gameplay. You are doing yourself a disservice by not playing this. WAHOO/10.', 'I bought this to support Klonoa, and I''d do it again, but I can''t in good conscience call this version of Door to Phantomile a good representation of the game. I can''t even call it Door to Phantomile (DtP).\n\nGood: 1.) Original sounds are great to have, and 2.) Updated graphics are fun to behold for longtime fans.\nBad: Gameplay. This is supposed to be one of (if not THE) best platforming games to come out of the original Playstation''s lifecycle, and I agree with that sentiment as someone that has', 'Overwhelmingly Positive', 95.31, 47.73, 5.42);
INSERT INTO reviews VALUES (40620, 1730700, 1332, 'this game is good for your mental health-gets me through anxious days better than a xanny bar ever could', 'The King of All Cosmos tells me over and over again that I''m not good enough. Screw you. Roll your own damn katamari.', 'Overwhelmingly Positive', 95.87, 249.65, 2.03);
INSERT INTO reviews VALUES (40639, 1731070, 962, 'This is a lovely and charming indie game. It takes some minor inspiration from the souls genre, as such there''s no map and a very bare bones journal (it can be off-putting if one isn''t used to it). The combat is responsive and flows well, though It''s rather easy if you''ve ever played a souls game before, even on the hardest difficulty, but it was nonetheless quite enjoyable. The DLC is mostly fine too, thought there''s one platforming boss that''s just as bad as Bed of Chaos. Greek mythology has s', 'Don''t be fooled by the cute red head like I was.', 'Mostly Positive', 79.00, 81.65, 52.67);
INSERT INTO reviews VALUES (40657, 1731460, 298, 'ABSOLUTE PEAK\nEdit: The BRAWLS Support team are the truest MVP''s ever !!!', 'I Was expecting a decent LEGO-themed platform fighter, and GOD was I disappointed. Long story short, do not buy this game under any circumstance unless you have a kid who loves LEGO and want to introduce them to platform fighters, and even then, I bet they would get bored quickly.\n\nthis game has absolutely 0 depth, and I don''t just mean it''s easy or super casual, it is literally nothing but a button mashing frenzy, there is only ONE ATTACK BUTTON and a dash that kinda acts like an attack but not', 'Mostly Positive', 77.52, 5.43, 0.58);
INSERT INTO reviews VALUES (40666, 1731720, 154, 'where the shemales at???', 'many of the puzzles are impossible from the start and the animations for the scenes are animated poorly.', 'Mostly Positive', 71.43, 2.07, 0.50);
INSERT INTO reviews VALUES (40676, 1732050, 260, 'Okay!, This game is fantastic, Filled with more sex and great Graphics than most games I have played. This is a must have if you like playing sex games. the new season is better than the last. Together they are fracking Fantastic. Keep up the great work MX Games, make more seasons. You have my vote, which really doesn''t meant a thing.\n\nThis game has more sex than Rabbits have at a mating Festival.  o.O', 'Season 1 was great. Season 2 was fair. The last update (ending) was crap. \r\nSeemed like the dev just wanted through with it and didn''t even try to make decent.\r\nUnless, he fixes it, I don''t recommend it.', 'Very Positive', 82.69, 14.33, 93.15);
INSERT INTO reviews VALUES (40684, 1732190, 1200, 'BRO I HAVE A LESBIAN PANIC EVERY MINUTE IN THIS FORSAKEN GAME IF YOURE A LESBIN DO NOT GET IT!!!!!!!!!', 'do not play this game on keyboard it was genuinely the worst thing ever', 'Very Positive', 85.75, 21.35, 0.83);
INSERT INTO reviews VALUES (40696, 1732430, 500, 'Realistic game, this is exactly what I do to my neighbor''s house in real life', 'Neighbor: Suburban Warfare had the potential to be a standout indie title, but sloppy netcode, poor balance, and a rushed early access release doomed it. The core gameplay loop is genuinely fun, but constant lag and a tiny player base ruin the experience. Most matches are now filled with hyper-competitive players, not just because the game attracts them, but because they’re the only ones left. Look, you can’t fault competitive players for playing, but when they’re the only ones in the queue, it ', 'Mixed', 67.60, 0.20, 3.65);
INSERT INTO reviews VALUES (40717, 1733060, 516, 'Played and perfected with family sharing.\nPurchased after it because a developer, who not adding stupid amount of achievements (100+) to his/her/whatever  short game deserve money.\nThat''s all folks.', 'I didn''t think I''d find myself recommending against a finding cat game but here we are. The art style is not much to look at, some cats just barely resembled an animal and there are so few levels. I only finished it for the achievements in which I had to replay the same monotonous levels.', 'Overwhelmingly Positive', 99.81, 0.85, 1.10);
INSERT INTO reviews VALUES (40720, 1733110, 115, 'This game is familiar, and yet does so many things differently for a colony sim. \n\nExample: I see a spring coming out of the side of the mountain and follow it down, then I see fish spawning up stream and keep following down to a lake.\n\nThe depth of the animal and environmental detail and life cycle is blowing me away. If you love deep detailed simulation without a ton of micromanaging, this is a great game for you.', 'I know the devs truly did their best with this game but, as a mediocre connoisseur of this game genre I just didn''t enjoy it, personally. The first couple hours were a challenge going through the tutorial and matching the small icons for the structures that needed to be built. Just before the tutorial/main quests were completed, it turned into a boring formula of "Build all the unlocked buildings, increase speed x300 until completed, continue until new stage unlocked, rinse, repeat.\r\nIt''s too bo', 'Very Positive', 84.35, 1.68, 6.67);
INSERT INTO reviews VALUES (40722, 1733170, 178, 'For a remaster, it''s not bad at all.  I have noticed a few bugs- one game breaking one in particular, if you''ve managed to pick up the RSVP and die on your way back to the mansion, the RSVP disappears from your inventory, and doesn''t re-appear where you''re meant to find it in the Hunter''s Cabin.\nOtherwise no issues- but I''d wait till it came on special- Almost $30AUD for a remaster of what is basically a Doom clone is a bit much.', 'Beware this game is published by Nightdive Studios, whose CEO Stephen Kick has made it perfectly clear he is comfortable with violence against Trump supporters. To quote him directly “Anyone who supports this monster deserves to go down with him.” If you press the credits option in the main menu, he is the first name. \n\nhttps://nichegamer.com/nightdive-studios-boss-boycotts-company/\n\nThe game itself is fine. Too scary maybe.', 'Very Positive', 93.82, 6.35, 0.12);
INSERT INTO reviews VALUES (40725, 1733240, 404, 'I dont think Phantom Fury is a BAD boomer shooter. Is it better than Ion fury? Fuck no. Not even close. Ion Fury was a labor of love on a outdated engine that even in the 90''s was a pain in the ass to make games on. Phantom Fury on paper is the perfect Boomer Shooter, and it has the "vibes" to fool most into thinking its the best in the genre. Pointless interactive objects? CHECK! Pixelated visuals? CHECK! Wise cracking protagonist yelling one liners? CHECK! The "vibes" are indeed here, so why t', 'Contender for the worst nonsensical plot in 2024. Has missing sound effects, like there''s no sound effects when you walk on water surfaces (yes, really). Has large amount of segments where music just doesn''t play.. for some reason? The shooting the thing that you''ll do most in the game feels awful and doesn''t really have satisfying feedback. The AI literally stops working and stands still sometimes.\n\nI can go on but you probably get the idea. It ain''t the worst game ever made, but if I really ha', 'Mixed', 59.65, 8.87, 11.55);
INSERT INTO reviews VALUES (40726, 1733250, 230, 'pls just make the fucking movie, I''ve waited like 10 years, 10 longgggggggg fuckin years, an entire decade, you know what that does to a person??? Anyway the game is really fun', 'Crouch is mapped to a button instead of just pressing down like every other 2D platformer on the planet.  I''m too old and impatient to train myself to do that when there are so many good alternatives out there.', 'Very Positive', 93.91, 5.52, 0.38);
INSERT INTO reviews VALUES (40748, 1733880, 188, 'From what I understand; the mixed reviews focus too much on comparing this game to the last few ones and what the game does wrong like changing Copen''s playstyle, having the story feel like an excuse for this game''s existence, locking the true ending behind hard mode, etc. The story and characters are pretty mid but the gameplay, stages, soundtracks and bosses (not including the dlc bosses) were enough for me to enjoy and play through the game. The change of Copen''s playstyle wasn''t necessary bu', 'This is easily a downgrade from the first game without a doubt.\n\nIn order to appease people who found the first game too hard, they incorporated an "Instant Full Heal" ability that you can use at ALL TIMES an INFINITE number of times. The only penalty being it will impact your end score, which doesn''t matter because there''s no real incentive to go for high scores. This means ANYONE can beat this game if you can press Y > Heal.\n\nI''m extra insulted by this, because you''d think hard mode would fix ', 'Mixed', 68.09, 34.90, 42.43);
INSERT INTO reviews VALUES (40754, 1734070, 158, 'Finished the game in 10 minutes.\n\nThe game has a solid foundation and the art is gorgeous.\n\nI hope that when it comes out of early access, the game has much more to do.\nAlso I hope that they add a harder difficulty.', 'i *really* wish i could give a nuetral review because i could see this game being very fun but as it stands right now, it''s WAY too easy. like, i beat it first try in 10 minutes. i havent even really played the mainline danmaku games, for reference... i just play a good amount of enter the gungeon... anyways. i think making enemies and bosses have WAY more health would be very good to start with but crazier enemies in the later levels + more rooms + room shape variety (like putting pillars or ob', 'Mixed', 67.09, 1.17, 0.20);
INSERT INTO reviews VALUES (40763, 1734320, 1420, 'If I had a nickel for every awesome game with enemy designs based on the artworks of Hieronymus Bosch, I''d have two nickels. Which isn''t a lot, but it''s weird that it happened twice.', 'I have played so many roguelites and turn based battle games over the years. I have a good grasp on what works and doesn’t.\n\nAll signs in this game point to an experience leaning too far towards dependence on chance. Chance that has dramatic, run ending outcomes outside of your control. You might have starts that offer you 30 gold and no outlet for it before a difficult fight. You might have starts that drop you a free item that trivialises the first 15 minutes. You might have a 50/50 directiona', 'Overwhelmingly Positive', 97.82, 39.67, 1.25);
INSERT INTO reviews VALUES (40767, 1734390, 140, 'I love it but the disasters, even on easy are rediculous. i wold still be repairing my base, only to be hit with another earthquake, critical damaging everything. My drill hit a gas pocket even though its storage was full and not even active.\r\n\r\nI''m gonna give it a few weeks and come back.', 'The game was entertaining for awhile, but it appears the devs have stopped updating. Nothing since a little patch in May 2024.', 'Mixed', 61.43, 22.93, 9.58);
INSERT INTO reviews VALUES (40781, 1734680, 476, 'I had much fun with this game, still better than DOOM Eternal.', 'Playing through the first episode was all right, then slowly got better and better, with the gameplay flow and music slowly building up through each level. The atmosphere is both chilling and electrifying, finding the exact balance between horror and power fantasy that put it on par with Dusk.\n\n...Until about level 4, where the first boss fight happens. Or a level where buildup + a boss fight happens, and if you die while fighting the boss, you WILL have to restart the level from scratch and re-', 'Very Positive', 90.76, 5.90, 0.88);
INSERT INTO reviews VALUES (40818, 1735420, 219, 'As a person who has lots of sex all the time, I can say that this game is 100% accurate to having sex with sexy women. like I do. everyday. this game did not make me horny, however. I am not gay. I just have too much sex with real women to spend more than 15 minutes in this game. on the other hand, I would recommend this game to people who do not have sex (unlike me because i have lots of sex with women lot) as there is a naked woman in it and she is naked. she kinda looks like one of my many gi', 'Fake Hostel is a pipe connecting puzzle game with adult content.\n\nTo preface things, the main character is just as lovely as many of these types of game: An asshole, women-hitting, pervert, racist Mario clone. 100% of adult content scenes includes a dirty toilet brush at some point... why are you still reading this? Alright, let''s keep going then! There''s around 40 levels maybe, lots of dumb and funny dialogues and lots of bugs. You have to repeat the same levels multiple times in a row for no r', 'Mixed', 65.75, 2.08, 2.42);
INSERT INTO reviews VALUES (40829, 1735700, 760, 'I adore this game, it''s crazy how much it''s flying under the radar. Basically it''s a life sim/choices matter kind of deal. Live in prison, go through the daily routine, work on raising your stats and skills and do one of a crazy number of different paths to escape.\nHonestly, I can''t emphasise enough how much effort they put into these different routes. There was a SECRET, hidden escape path I found that included like six entirely new characters you''d never even see otherwise with full animations', 'I really wanted to like this game. In theory, everything about this game was supposed to be exactly what I like. But no. After 21 hours I have to say I regret putting 21 hours into it. It punishes you for not knowing the rules which it has not presented to you. The only way to "win" this game is to play the story for multiple times or use all the guides and help from internet. Awful a lot of time goes into checking what all the inmates sell or what presents do they actually like. You absolutely ', 'Overwhelmingly Positive', 95.79, 47.12, 21.27);
INSERT INTO reviews VALUES (40850, 1736360, 100, 'All my liquid came out', 'Bad price, artwork, story, and game play.  This is a game where you draw a line on the screen with your mouse and get a ball to roll into another ball.  I found it frustrating and boring.', 'Very Positive', 81.00, 25.72, 0.50);
INSERT INTO reviews VALUES (40860, 1736550, 175, 'While Deflector has some very innovative ideas, I felt it does not provide longevity as well as other roguelike titles I have played. While I did enjoy the game, I think it''s missing an element that compels the player to continue playing after beating the game. For a more in-depth review check out my video below!\n\nhttps://youtu.be/TQbOqQUKwX4', 'It''s a decent game and I would say it''s fun for about 3 hours or so. Fast paced simple combat, pleasant aesthetics and the music is actually pretty good. But in all honesty, I do think it lacks the addicting hook when it comes to replayability many other Roguelites have. Sure, there''s mutations and additional characters to unlock, but I got so bored of my mind of it after 8''ish hours, I just felt like deleting it. You could argue I got the value out of it, if it wasn''t for the fact that the publ', 'Very Positive', 88.57, 5.58, 8.07);
INSERT INTO reviews VALUES (40893, 1737340, 226, 'For what its worth, the game is pretty solid. It takes less than 24 hours to achieve 100%. There are a few issues, too bad the devs seems to already wash their hands off this game. But there are no game broken bugs/glitches that made me want to uninstall the game. Would I recommend this? Yes, I would.', 'Feels loose and sloppy. There are other better options out there', 'Very Positive', 88.05, 21.53, 0.20);
INSERT INTO reviews VALUES (40916, 1737870, 1407, 'I do not make game reviews. I do not play this style of game. I am not the target audience. I bought this game for an ex-girlfriend who I thought would enjoy it, and never played it. \n\nI love this game. It is beautiful, whimsical, and a legitimate relaxing joy to play.\n\nPlease, PLEASE keep working on this project. I cannot express how excited I am to play through the finished version and recommend it to everyone I know.', 'This game has so much promise but with out an actual release date in sight, there isn''t enough content in this game to justify the $20 price tag, I''d wait until there are at least 3 more updates that are full in game content before buying.  Just my opinion though.', 'Very Positive', 84.72, 5.07, 6.35);
INSERT INTO reviews VALUES (40935, 1738610, 290, 'nice game with a friend. it does have some tedious parts but the rest is ok', 'Please regard this review as relative to the other games in the series (Escape memoirs). It is a good game, but as other people have said, this one is rather tedious compared to the others. In the other games, I love the feeling of "Aaah, that is the solution!", whereas in this game, you need to read a bunch of stuff and think of like 2-5 different possibilities, of which hopefully one is the solution. In other words, the solution for a puzzle, in the end, is perhaps not super clear. Yes you may', 'Mostly Positive', 71.03, 10.32, 7.57);
INSERT INTO reviews VALUES (40947, 1739000, 155, 'I have no idea what I am doing and I have made so many players mad on the VGK team by because of poor management. Very realistic', 'game keeps failing', 'Very Positive', 80.00, 5.93, 773.78);
INSERT INTO reviews VALUES (40950, 1739070, 204, 'A really cute game about killing your customers and harvesting their souls for fun and profit. If you''re looking for a spooky version of Overcooked to play for October, give Bone''s Cafe a try!', 'This would get a neutral from me but since steam only allows binary choices I''m leaning not recommend.\n\nThe main story is fun and good. It''s missing a hands-on tutorial on how to use minions/programming. Default controls are very bad (JLKI), zero mouse support on a PC platform..\n\nMy biggest gripes are with endgame, test kitchen and challenges. Discovering and recreating recipes is a pain because it only shows the ingredients and tools, not the order. This means that if you have 6 ingredients in ', 'Overwhelmingly Positive', 99.02, 4.77, 21.28);
INSERT INTO reviews VALUES (40959, 1739300, 353, 'I only use the character creation tool. It is fast, easy, and does what I need it to do for my own personal projects.', 'I got this Game/Software after Seeing it On Youtube Shorts. Thought it would be nice To have this to play around. \r\nBut it Lacks Basic Features Like Being able to Change Canvas Size To a Higher Resolution, You are limited to 256x256 Pixels.\r\nSo I can''t Recommend it.', 'Very Positive', 88.10, 13.25, 6.48);
INSERT INTO reviews VALUES (40983, 1739880, 130, 'This game is okay, nothing to special, it is janky a little bit but it is okay if a part of a bundle or on sale, solid 3+hours of playtime to get the achievements if you have friends to play with even more just don''t aim down the sight you are way more accurate hip firing', 'It is "Yet another zombie defense" turned into 3D asset flip. Nothing works properly, guns suck, turrets don''t work half of the time, zombies have no animations. I got this game from a bundle that was cheaper than the game I wanted from that bundle, so I actually saved money by getting this game - and I still think I didn''t get enough to play or recommend this game.', 'Mixed', 54.62, 2.93, 2.33);
INSERT INTO reviews VALUES (40984, 1739900, 344, 'Richardson is a certified, Gilliam-esque maniac in the finest possible sense. Death of the Reprobate is the anguished God cry of a Rennaisance Art PhD, forced to endure the impossible mundanity of 21st century wage-slave life. True to the last frame.', 'Like previous two games, style and animations are very nice, and together with music they create a good ambiance. But the weakest part of the games is what author (and some fans) most probably thinks to be the strongest: "edgy, nihilistic" writing. Satiric paintings and surreal medieval themes give a very strong and tasteful base, but author just drown it all in his over-the-top wannabe acidic, but disappointingly bland sauce, mostly consisting of ground-level and very tired generalisations, lik', 'Overwhelmingly Positive', 95.64, 3.37, 2.72);
INSERT INTO reviews VALUES (40992, 1740070, 119, 'Sokpop''s Bread & Butter right here. They find a good concept, make a short enjoyable game and sell it for a cheap price.\nAlthough this game sort of goes a little over the classic sokpop groove by having a little extra content you can grind for and it is a little more pricey but it was still fun for the almost 2 hours I played it.', 'Don''t trust the Sun, She told me she is always hungry so i pick up all available materials (about 400 carbons, oxygen and ice each) in the asteroid field and feed it to her just after the first planet. All she reward me is infinite matches (granted, infinite matches are pretty neat). The matches need oxygen to burn, and i already gave her all available oxygen and there is no more and i need to restart.\n \nFirst into this "comfy" game and immediately teach player to be selfish is bad look, not goi', 'Very Positive', 89.92, 1.77, 4.08);
INSERT INTO reviews VALUES (41002, 1740240, 240, 'Wow. Just wow. I know it''s considered cliche to say that a video game changed your life, but anyone willing to say that clearly hasn''t played 100 Hidden Cups. Within my 24 minutes of playing this game, my entire worldview has shifted, I feel like I have achieved some kind of enlightenment; my mind feels clearer, I feel that I finally understand my purpose in life. After many years of being unsure of who I am, what my goals are, what my purpose is, everything suddenly seems so simple. Every quest', 'I''m playing Steam games in alphabetical order and you can watch my review here: https://youtu.be/5l-fer6s-7Q\n\nPrefer to read?\nThis is a 100 hidden object style game, but the object you are seeking is hidden in incredibly evil and unfair ways that will leave you questioning reality. What even is a cup?\nNot what we''re finding here, as these are all mugs, which coincidentally is what I feel like for buying this game.\nThis dev has made much better games like this.\nThis is an E tier game for this gen', 'Mixed', 40.00, 0.40, 0.37);
INSERT INTO reviews VALUES (41005, 1740300, 1416, 'I had this game for a long time in my library and recently got around to it and regret not playing it sooner. The game is a relaxing and cutesy puzzle-platformer with an adorable aesthetic and a great cast of characters. The mood and music is very mellow and the addition of the mycology encyclopedia is a great idea for learning about mushrooms. I would 100% recommend this game for anyone interested in a relaxing and laid back game with great music, a compelling cast of characters, great writing,', 'A cute looking game pulled down by a bad camera, endless jumping puzzles, a color palette that makes you get lost really easily unless you go along the default paths, and item fetching. If you find an item that you have to carry, and don''t know what to do with it, and leave it somewhere, it will despawn if you go into another area. For example, one item looks like a hand that goes to a stone statue. Maybe because it''s the same color as the statue and looks exactly like a hand....but it''s not. \n\n', 'Overwhelmingly Positive', 99.22, 5.93, 1.52);
INSERT INTO reviews VALUES (41024, 1740680, 251, 'A very satisfying game to play ... great voice acting ... beautiful music .... loved the art work ... and a very rich story from beginning to the end ... was not able to stop playing until I finished it ... for a point and click game its a 9/10 recommend', 'Not fun enough to recommend and the story is nothing special.\r\nThere are better detective games and better point n click games out there.', 'Very Positive', 94.82, 6.43, 5.80);
INSERT INTO reviews VALUES (41026, 1740720, 4014, 'Full of items to discover ,Challenging and has a funny story line. Enjoyable by all.', 'I bought this because I really like the artwork, and I was hoping for something more like the Ori games. The overall issue I have is that getting through levels is pretty easy, but the boss fights at the end are disproportionately difficult. The result is having to start over and slog through a fairly boring level over and over again just to receive another beatdown at the end.', 'Very Positive', 87.87, 331.13, 4.22);
INSERT INTO reviews VALUES (41034, 1740930, 721, 'i want to eat the car', 'Physics are too messy for the challenges to be fun. 50% luck is not fun for something that takes a lot of trial and error. You''ll probably like it but I don''t', 'Overwhelmingly Positive', 97.78, 10.17, 3.68);
INSERT INTO reviews VALUES (41038, 1741040, 104, 'Femboy Elf Queen was 100% worth it', 'Much more game than porn.\nThe gameplay is fun but kind of repetitive with how much it wants you to grind.\nThe porn isn''t that great most of the are just cg''s that they switch between to give a sort of animation but sometimes they just switch to ones where they''ve cummed and stuff which seems weird.\nThe last cg''s are fully animated though they''re all pregnant. Really odd they did it for those and none of the others they bothered with having an animation loop for.\nIf you are wanting to 100% be war', 'Mostly Positive', 76.92, 3.40, 43.48);
INSERT INTO reviews VALUES (41063, 1741640, 824, 'Imagine a game that''s really three games happening at the same time, and you''re only playing one of them. 80% of the AI is playing Crusader Kings II, the other 20% is playing Call of Cthulhu, and you? You''re Cthulhu.', 'Very unique 4X, but the much-anticipated UI overhaul appears to not be coming, as nowhere can I find a lick of dev activity for most of the past year.\n\nIf the concept interests you enough, get it on sale, and good luck deciphering its interfaces. There are some great mods that bring interesting new god concepts that you''d hardly see anywhere else, but nothing that really "fixes" the game - only the dev had the power to do that.', 'Very Positive', 92.35, 16.40, 18.67);
INSERT INTO reviews VALUES (41105, 1742610, 246, 'Bought on sale for $5, no (one) complaints. Nice maze building. Generous checkpointing that''s not common to TDs.\n\nMy only complaint is there is one achievement that requires you to grind through the entire game on hardest difficulty with all difficulty modifiers active simultaneously, but you don''t even unlock highest difficulty modifier until xp level 50 (which took me 35 hours). So not only do you have to play all the levels a second time (another 35+ hours probably) but the modifiers all toge', 'A solid TD with some interesting mechanics but unfortunately poor to no optimization at the moment. During my last run the game provided 7-9 FPS on the last stages and then crashed after consuming 26GBs of RAM. \n\nI''d recommend to wait for some patches before buying.', 'Very Positive', 93.50, 34.00, 2.77);
INSERT INTO reviews VALUES (41122, 1742930, 874, ' Though it initially seems like a point-and-click horror game, the game is weirdly comforting. \nIt is short, not that scary, quite eventful, and simple, but conveys the story well. \nWith overflowing deadlines, our protagonist, HER, was racing against time (that''s why the monster in the game has a clock for a face). Burden with responsibility, she doesn''t have the mental capacity to study or work any further,... When HIM is HER''s, let''s say, ideal self. HIM was buried in books, calendars full off', 'It has a nice art style but the game itself is not good, it is a short but not deep experience, it does not reach what other similar games can achieve, it seems to want to reflect life problems in a very "basic" way.', 'Very Positive', 92.45, 3.65, 3.23);
INSERT INTO reviews VALUES (41164, 1743830, 279, 'Good competent base management game. It''s plays basically like a reverse evil genius. Your nation has been invaded by a comic villain and you have to take it back. Build your base, upgrade your minions and send them on missions. Nothing revolutionary but solid, good stuff.', 'Starts off fun but quickly becomes not so much fun. Building the base is a blast, it reminds me of Evil Genius 2, building your stronghold feels good and is satisfying, unlocking each tier of new specialist and training was cool and had me excited for what was to come, but unfortunately with no actual combat or strategy anywhere to be found. Its lacking a massive piece, what should in my opinion be the other half of the game. Its only fun until you realize that the missions you send your soldier', 'Mostly Positive', 76.70, 12.15, 14.58);
INSERT INTO reviews VALUES (41165, 1743850, 2334, 'HYPER DEMON is the only perfect game I have ever played. If the developer asked me for one piece of feedback- an addition, removal, or otherwise- I would have nothing to say. There is nothing about this game I do not like, and there is nothing I think would make it better. It reminds me of Tetris in that every mechanic has great impact on the rest of the game, so there''s no real definition of a "correct" move. In other words, every decision you make in a run will occlude other possible decisions', 'Only a person with no self-respect (or a severe humiliation kink (or both)) will spend more than 50 hours on this game', 'Very Positive', 94.43, 17.18, 75.08);
INSERT INTO reviews VALUES (41184, 1744330, 413, 'Not quite as strong as the first one, but didn''t have as many tediously designed segments as 2, overall it''s a lovely sendoff to the series if you also played Travis Strikes Again . If you''ve played the others you''re getting more of the same here.', 'Weakest NMH by far, and a disappointing sendoff. Combat''s been simplified and stiffened significantly from 2''s, there are no pre-ranking match stages or unlockable beam katanas. Repetitive overworld objectives, boring lock-on mech segments, greasy aesthetics and characters written flat as a board. The disjointed Takashi Miike glazing cutscenes overstayed their welcome quickly, but are forgiven for being skippable.', 'Very Positive', 81.36, 18.90, 10.58);
INSERT INTO reviews VALUES (41210, 1744910, 214, 'The game is simple and very like all other Chillas Art games. I can recommend it since the story is nice and the game is simple yet have some good horror elements.\nMy point is, the charm of Chillas simple games, I don''t think every game need to be a totally new experience that will fill you brain with dopamine. I think that simple games that you can have some fun once in a while is also good and the price asked for it is also fair.', 'After what feels like 5 weak to mediocre releases in a row, I''m slowly just accepting the fact that Convenience Store/Inunaki Tunnel was their creative peak and I''m just giving up on Chilla''s Art.\n\nEvery time the exact same weak atmosphere, busy work, mostly generic ghost story and the same 25 assets - you can literally see how the pressure of regular releases and Patreon is causing the creative death of an actually cool team. I guess this is still fine for horror newcomers, but someone who revi', 'Mostly Positive', 76.64, 2.58, 1.78);
INSERT INTO reviews VALUES (41220, 1745170, 158, 'This game is a damn Masterpiece. Sadly there is no multi-player. But this game is seriously underrated. Keep it up dev', 'overpriced, maximum i would spend is less than 5 euros.', 'Very Positive', 94.94, 118.70, 0.33);
INSERT INTO reviews VALUES (41262, 1746030, 701, 'As a lover of Chinese history and murder mysteries, this gorgeous detective game set in the late Qing dynasty could not be better fit to my tastes! I enjoyed every moment of this game, from its lovely artwork to its charming characters to its intriguing and mind-wracking murder mysteries. There is so much attention to detail. I loved the setting and getting to explore this important time period in China while also following a brain-twisting story. The English translation is very smooth and accur', 'I''ve finished solving 3 cases, and so far the game mechanics is okay, and I also enjoyed very much reading the detailed historically accurate lore. However I must also criticize about the way the plots are planned because I think this is the biggest flaw, not just to this game, but also to the detective genre. In general, I think there are plots in the game when the protagonist arrives at a conclusion, it lacks a logical thinking to back up his decision, but rather the plot exists for the sake o', 'Overwhelmingly Positive', 97.29, 13.53, 6.32);
INSERT INTO reviews VALUES (41300, 1746930, 635, 'All the negative reviews are valid since the game isn’t well-programmed and still lacks polish. To be completely honest, it should be marked as "Early Access."\n\nThe developers are actively working on the game and seem really lovely, so I still recommend it for many reasons. As long as you can accept the "work in progress" status, this game promises to be unique and fun.\n\nIt feels like a Persona game meets a farming sim, and I love everything about that. The characters seem interesting. I haven''t', 'Alright so first the game! This is a really cool idea, as a fan of farming / life sims I love the modern spin on the farming genre. I feel way WAY too many of these games just redo the harvest moon formula that''s been around for 30 years. I''d really like to see more fresh takes on it like this game provides. It has a lot of cool stuff that makes for an interesting and new experience. Definitely buy it if it''s on sale and if you are a fan of the farming sim genre you''ll enjoy it! \n\n That''s the go', 'Mostly Positive', 70.39, 5.80, 2.05);
INSERT INTO reviews VALUES (41304, 1747050, 304, 'if sam and max kissed sloppy style in this game i wouldve liked it better', 'Do not support companies that censor art.', 'Overwhelmingly Positive', 99.01, 37.38, 17.02);
INSERT INTO reviews VALUES (41335, 1747760, 1057, 'Actually, I preferred the previous part in this series. But this one is also good. Beautiful pixel art and pleasant music. It was also very fun to play, especially to complete the hardcore challenge.', 'Well, it''s not a bad game... But it feels empty, idk. Like some things were thrown in without much thought - like fishing, or all your currency that you amass for no reason at all. Locations are not memorable. Difficulty is random. You can breeze some places, but some enemies kill you in two hits. \r\nAs i said - for a small game - it''s ok. \r\nBut the most complaint I have is:\r\nPuting tag "Metroidvania" here is like puting tag "RPG" on Doom 2016 just because you have some sort of skill-points there', 'Very Positive', 93.95, 26.25, 10.50);
INSERT INTO reviews VALUES (41344, 1747890, 134, 'Very short but sweet platforming. This feels WAY better than the base game (less floaty, tighter controls, faster pace) but I''d still recommend playing the original Demon Turf in addition to this one.', 'The gameplay is good, the color schemes are bad, I took frequent breaks playing neon splash. Whenever I come back I can not help but feel dread looking at this game as my eyes strain. Please give players a toggle mode to change the color schemes to look just like the original Demon Turf game.', 'Overwhelmingly Positive', 96.27, 2.22, 0.23);
INSERT INTO reviews VALUES (41368, 1748390, 162, 'Good but I wish that they would bring back ranked squads', 'this game is very bad i didn''t like it and TRUST ME i did a through investigation', 'Very Positive', 89.51, 39.08, 2744.27);
INSERT INTO reviews VALUES (41373, 1748610, 206, 'Dogy : )', 'I should preface this, I neither watch nor truly enjoy V-Tubing.\nI had barely any expectations of this game, yet still i was disappointed.\nThe idea in itself is pretty interesting but thats where it stops.  I wouldnt even say its a walking simulator because you cant walk. You just press the LMB and the screen slowly moves to the left.\nIt couldve been okay too if the screen didnt zoom in any time something was out of the norm and just let the player focus on it himself instead of being warned by ', 'Very Positive', 93.20, 0.43, 0.58);
INSERT INTO reviews VALUES (41374, 1748620, 2210, 'Despite the premise, this game is disappointingly heterosexual. That said, still very fun & cute. Wishing the best to all the eggs this game ends up cracking btw.', 'This game let''s you swap genders with a button, but only has M+W and W+W pairings, which is extremely disappointing. Also for some god forsaken reason you turn into a smurf during the H-Scenes - seriously, every man turns blue. Why they decided to give you Dr. Manhattan''s penis is beyond me.\r\n\r\nThe gameplay itself is fine I guess. It''s a passable metroidvania with pretty good art, but you can find better. That being said, the music has absolutely no right being as good as it is, it''s groovy as h', 'Very Positive', 94.84, 14.50, 8.95);
INSERT INTO reviews VALUES (41407, 1749350, 151, 'For a long time I''ve dealt with depression. A less than stellar home life and lack of social interation at an early age all contributed. This game single handedly made all of that a thing of the past. I now have a penthouse suite with 12 lambo''s all across the world to use when I travel, and a beautiful family I take with me. The jokes in this game saved me.\n\nThank you, Gobby McGobblenutz. The Art of the Dad Joke: Chapter 1 is the best game I have played.', 'Well this one was okay-ish. Got kinda stale, though. It''s also somewhat unreadable for ESLs.\n\nWord is Ludicrous.', 'Very Positive', 92.05, 0.25, 7.17);
INSERT INTO reviews VALUES (41426, 1749750, 236, 'Similar to other disgaea games. Cutscenes a bit long and plot was silly but still fun.', 'This sh*** is not Disgaea... Just a quasi-mobile auto battler', 'Mixed', 58.47, 29.45, 7.00);
INSERT INTO reviews VALUES (41431, 1749860, 320, 'I don''t think there''s anything on the market that comes even close to it, the game is beautiful and the atmosphere without the stories is very reminiscent of Firewatch to me.', 'I really wanted to like this, but feel like it''s not designed for people who actually enjoy photography IRL.\n\nFirst, no option to disable motion blur, leaves the world looking like a mess unless you stand still.\n\nBokeh/blur seems to be implemented with every object deciding whether it is IN or OUT of focus. If it''s IN focus, it is rendered sharp. If it''s OUT of focus, it''s rendered blurry. It doesn''t feel like objects shift gradually between these two states, instead snapping to one or the other', 'Very Positive', 91.56, 8.88, 0.17);
INSERT INTO reviews VALUES (41437, 1750030, 175, 'After so many years waiting for someone to make my dream game of playing an old overweight man running around a Japanese train station, I was about to give up hope when this game came out of nowhere.  And its actually much much more then that.  I thought this would be a fun throwback to PS1 era survival horror games, with its obvious nods to legacy resident evil and silent hill.  What I didn''t expect was how good this game turned out to be.  I came for budget silent hill and instead got a cold s', 'I was very hyped for this game as they marketed it as an homage to classic old-school survival-horror titles, but unfortunately it kinda just borrows tropes from Silent Hill and I believe some inspiration from Obscure, but without coherence or consistency between anything.\n\nUltimately though it is an indie game and as far as indie horror games go it''s pretty clear that there was actual effort put into this one and for what I assume is a first attempt it''s not that bad, but after finishing it I s', 'Mostly Positive', 78.29, 1.87, 5.32);
INSERT INTO reviews VALUES (41461, 1750570, 700, 'cute little horror game that scared the crap out of me and then made me go awwwwwww…. and then scared the crap or of me and then made me go awwww and then…….', 'I wish I liked this game, the big problem is that it feels so slow and boring. The artstyle is really good tho', 'Very Positive', 83.14, 5.40, 0.48);
INSERT INTO reviews VALUES (41469, 1750770, 2615, 'You''ve played Stellaris, right? Fun, isn''t it? But isn''t the best part of the game always exploring a new galaxy? Sending out your exploration ships and seeing all the weird things you find, and maybe even getting caught up in some bigger plots here and there? And of course, sometimes running into things that want you extremely dead.\n\nHave you ever thought "I''m kinda bored with all that empire building stuff. Wouldn''t it be better if I could just play as the exploration ship instead"?\n\nIf so, th', 'If you''re going to have an idle game mechanic where it takes 20 real time minutes just to cross open space, don''t have the player mysterious die without prompting and have to reload from last manual save. No one has time for that.', 'Very Positive', 92.81, 26.55, 25.02);
INSERT INTO reviews VALUES (41491, 1751350, 253, 'I''ve tried playing this game several times and there is always bugs that prevent me from completing quests, which is extremely frustrating.  I do think this game has the guts to be good, but calling this a 1.0+ build of the game should just not be true.  Please fix game breaking bugs so I can enjoy this game.  I will uninstall for the 3rd time now and try again in a few months.', 'They just released that they will be increasing the price to around $20 which is a laugh to me because this game feels so uncomplete. The conversations are redundant and dont update if you already have done certain things for an npc. The camera has no rotation or opacity for you moving behind things. The quests are sometimes non-descriptive and have no map markers. The graphics have no settings except resolution and v-sync. There seems to be not much more to do after about 2-3 hours of play exce', 'Mostly Positive', 70.36, 50.60, 5.28);
INSERT INTO reviews VALUES (41590, 1754000, 153, 'Main story: 8/10\nside quests: 8/10\nzone: 7,5/10', 'Store page description is misleading, it shouldn''t list past chapters as features if they''re only available in the CE. wasted money on this because I just wanted the Blackwood chapter and thought this was better value than buying crowns, assuming this was a "Buy one get all" purchase as other MMO''s in the market like WoW and FFXIV have.\nThe tiered upgrade options almost feel like a trap to confuse people into paying more than they intended', 'Mixed', 60.13, 0.00, 0.00);
INSERT INTO reviews VALUES (41620, 1754840, 711, 'Tried leaving a negative review but command prompt popped up... 10/10', 'This game is WAYYYYYYYYYYYYYYYYYYYYYYYYYYYYYYYYYYYYYYYYY too complicated. would not recommend, you need at least 0578239458672349 braincells to play this but i only have 2 pls help :(', 'Mostly Positive', 74.68, 13.27, 0.23);
INSERT INTO reviews VALUES (41621, 1754860, 328, 'This was fun, also way to short. Roll credits when you think the story is just starting to really kick off. Wouldn''t buy again for more then $5.', 'Boring and misogynistic', 'Mixed', 67.99, 1.20, 11.57);
INSERT INTO reviews VALUES (41622, 1754870, 383, 'Okay, I''ve finally finished this edition of Lust Theory and I enjoyed the journey, mostly.  The reason I used "mostly" is, had it not been for Amy, Sophie, and Ellie, I would have lost interest.  My major issue is that my character is an adolescent nitwit that would have been beat up everyday by the girls.  The BDSM scenes where not believable.  It takes more than ass smacks and hard thrust.  Hopefully Season 3 version is better.  The spellchecker should be fired.  Put some lube on the asshole a', 'I don''t recommend this game as it is. However, it occurred to me after a while into it, that I probably would have a completely different opinion if the developers hadn''t chosen to make it a sandbox. This is not really a sandbox game, it''s structured as one, but there''s no real freedom in how the story plays out. Even when a choice is given, there is the right choice that advances the story, and a bad choice that forces you to try again.\r\nIt ends up being tedious. If the game was just a typical ', 'Mostly Positive', 75.98, 80.90, 19.80);
INSERT INTO reviews VALUES (41627, 1754960, 197, 'Honestly I''ve seen so many people leave bad reviews on this game and I think people are treating this as a finished and published game. This game isn''t finished and was released really early. So yes there will be issues and not a lot to do right now. This game already looks so nice and has so much potential. I can''t wait to see this game when it is finished!', 'Mmm, I''ve been following this game for a little while and I''m kind of disappointed by how bare bones it still is. It has potential but right now, I wouldn''t recommend it. It rarely goes on sale so I would not bother buying it full price (like I did). Updates still happen, it isn''t abandoned, but it''s very slow going.', 'Mixed', 58.88, 0.45, 0.22);
INSERT INTO reviews VALUES (41628, 1755030, 176, 'Mothmen, pulp fiction, and DOS text game throwback. What''s not to love?', 'Short. Several loose ends. Shallow. Frustrating puzzle controls. Grating audio. Pure aesthetic. How this rated so highly is beyond me.', 'Very Positive', 90.91, 1.60, 3.73);
INSERT INTO reviews VALUES (41635, 1755180, 256, 'Kicked out of college, grandpa dies, and leaves the brewery to you.  \r\n\r\nMake brew and sell it.\r\n\r\nGG.', 'bought this at least a year ago, saw that it was unpolished so i set it aside to wait for updates, but those updates never came', 'Mixed', 55.08, 18.77, 6.53);
INSERT INTO reviews VALUES (41643, 1755350, 355, 'Convinced my friends to buy this on sale for $1.79. It was a semi-hard sell but they thoroughly enjoyed peeing on one another. The amount of seasoning that all meats require is RIDICULOUS. It''s 100000% more likely for me to pee on my friends at a BBQ than for me to add 20 seasonings and sauces to my hot dog. There''s an insane number of modes that all require over seasoning meats but it''s well worth $2.', 'I''m going to be honest I bought this for £1.60 and let me tell you the amount of content was really under 2 hours if I was being honest and me n my friends only managed to 2 hours as we messed with the physics in the game. xD \n\nI cannot recommend this game it can be fun but they need more variation and not have it all  revolved around cooking even just spraying the sauce at each other and losing health would of been funny or throwing meat at each other and we take damage. Or whacking each other ', 'Very Positive', 83.94, 1.20, 2.23);
INSERT INTO reviews VALUES (41651, 1755580, 136, 'Straight up jackin my box rn', 'connection sucks fuck you', 'Very Positive', 92.65, 3.07, 1.97);
INSERT INTO reviews VALUES (41665, 1755830, 988, 'I am completely sick of games that just copy Slay the Spire -- Monster Train and Griftlands being too examples I have not enjoyed at all -- so why then is Astrea: Six Sided Oracles perhaps my favourite deckbuilding game of all time, even surpassing Slay the Spire itself?\n\nAstrea definitely takes a lot from Slay the Spire, from broad deckbuilding mechanics  and the branching map even down to individual fights and character abilities. The hidden fourth boss in particular felt a bit too derivative ', 'This game is absolutely beautiful. I love the art style and it''s probably the best thing about the game. \n\nThe game has a lot of cool and nifty mechanics with how the health, corruption, and dice work. Having a fixed 7 max health is definitely a step in a unique direction, and forced some new strategies I haven''t found in other games. \n\nBut to be honest, I don''t really like any of the characters or decks. Those nifty mechanics seem to have boxed the game into coming up with lots of novel mechani', 'Very Positive', 94.13, 192.10, 10.77);
INSERT INTO reviews VALUES (41684, 1756160, 159, 'At some point a heard some screaming and I thought it was the screaming vehicle thingy that follows you, turns out it was my friend... and a giant spider behind him. Fun game fun moments would recommend.', 'Got this a few years ago as a pretty cool EA sci-fi horror game. Come back to it now to find it''s just a Lethal company clone. Disappointing.', 'Mixed', 66.04, 2.18, 1.18);
INSERT INTO reviews VALUES (41685, 1756180, 131, 'An engaging shooter with great graphics and humor! Fast-paced and thrilling gameplay', 'I don''t know how I got this or who recommended it but fuck you', 'Very Positive', 86.26, 2.87, 0.10);
INSERT INTO reviews VALUES (41744, 1757490, 510, 'i was horny', 'Game is fairly hard if you don''t have good reaction time. And i''m not as young as i use to be.', 'Very Positive', 86.86, 0.33, 0.63);
INSERT INTO reviews VALUES (41811, 1759350, 421, 'I almost never write reviews, but I grabbed this well back in its early access and had loads of fun with it. The developer has added so many QoL improvements that only enhance my enjoyment. Some people have said that they are getting low FPS recently with great computers. I haven''t had any issue whatsoever, for what its worth, and my computer isn''t exactly top of the line.\n\nThere''s a very relaxing flow to the game of building up resources and setting up your rig, and always something new to reac', 'Was not planning on reviewing this game until the developer commented on a thread I made in the games forum. I had made a thread about one of the most important items in the game being too rare and immediately got jumped on by another player. 1 or 2 other players basically commented about how they agreed after that then the dev came in and basically said that we were playing the game wrong (there have been several other threads on the topic and several of the negative reviews talk about this as ', 'Very Positive', 86.94, 226.07, 7.27);
INSERT INTO reviews VALUES (41812, 1759380, 560, 'This is Graveyard Keeper (it even has the same developers) but more wholesome. If you want a light story, an immense amount of brain off activity while you navigate a skill tree and knitting being made into the most awesome magical skill ever, this game is for you. Not everyone is going to enjoy the grind, but if you enjoy slamming down task lists this is the game for you. I don''t really care about LoL but the lore and story were fun even isolated from knowing anything about LoL. It''s a shame Ri', 'As a cozy gamer, I was really excited to hop into this one. I loved Arcane and experiencing Heimerdinger in another medium was something I greatly enjoyed. The story and the graphics pulled me right in. But, that said, I feel like this game was mismarketed as a cozy game. It''s actually quite complicated, and I found myself confused and having to pause to google how to move forward often since the mechanics felt that they weren''t made for cozy gamers the way the aesthetics were. By the end of thi', 'Mostly Positive', 76.61, 6.10, 36.10);
INSERT INTO reviews VALUES (41848, 1760250, 4582, 'The game is pretty accurate. Easy to change settings etc.... Overall, it is a decent game.', 'my food fell when i was playing', 'Mixed', 54.30, 147.10, 132.85);
INSERT INTO reviews VALUES (41881, 1761380, 138, 'This game is truly amazing! I''ve been playing for years and it always manages to surprise me.\r\nThe level designs, the Bosses, the Character designs, the Skins, the Devs... I 100% recommend! \r\nSpecially because of the Devs, they''re really kind, polite and they update the game frequently.\r\nYou will never feel like you are playing a "dead game".', 'Game is charming enough, but it keeps wiping my progress on certain updates. I can''t regrind my progress a fourth or fifth time, no matter how fun it is :ebfslime:', 'Mostly Positive', 77.54, 739.05, 414.43);
INSERT INTO reviews VALUES (41882, 1761390, 8222, 'The game is really fun and the modding community is amazing\nDenuvo sucks and shouldn''t be allowed in a rhythm game', 'Please remove Denuvo Anti-Tamper! I keep getting locked out for 24 hours simply for being on Steam Deck and changing Proton versions! Extremely annoying! It''s a fun game though when Denuvo decides to let me play it! AGH', 'Overwhelmingly Positive', 95.21, 667.78, 192.55);
INSERT INTO reviews VALUES (41891, 1761620, 279, 'PLEASE ADD LOCAL/OFFLINE/SPLITSCREEN MODE.\n\nloving this hidden gem, I don''t want another indie multiplayer game to have their servers shut down and becoming forever unplayable.', 'to developers:\nYOU HAVE FAILED. \nits now dead with 30 daily players on steam\nyou could made it free to play and sell skins and battlepass and I''m afraid its too late to do it.\n', 'Mostly Positive', 70.61, 2.02, 8.28);
INSERT INTO reviews VALUES (41907, 1761900, 190, '- Improve movement if its puzzle and obstacle courses.\n- Game isn''t well optimised high range PC would experience severe frame lag during some hordes.\n- Include more interact-able content in between platform hordes so it doesn''t feel slow.\n- Expand map size but include means off transport because dying to hordes and spending more time travelling isn''t enjoyable.\n- Scenery and audio is immersive.\n\nThe game has good potential but feels like a cluster of different ideas that don''t share a middle gr', '#1 complaint the ending gives you blue balls. Builds you up for this epic boss fight then just rolls credits. smaller complaints are: No threat outside of the platform waves, respawn takes WAY too long, and its way too expensive for the amount of gameplay (5Hrs).', 'Very Positive', 81.05, 4.73, 4.98);
INSERT INTO reviews VALUES (41911, 1762010, 666, 'what if Dune and Cruelty Squad had an autistic baby?\n\namazing art direction, fun gimmicks, great worldbuilding and level design in general\nthis game deserves more love really\n8/10', 'Wasted potential. Too many bugs, dev abandoned a game that was truly unique. After you beat the worm boss it''s all downhill. Quests don''t properly complete, locked out of some freezers even though it claims they were unlocked by the assigned npc. Game crashes at random, my biggest complaint was the total failure of the enemy respawn mechanics. Enemies will respawn if you reload your game, so if you save in a area you just cleared out and reload your file, the enemies are all back. You leave a zo', 'Mostly Positive', 75.08, 6.97, 5.95);
INSERT INTO reviews VALUES (41920, 1762270, 520, 'We''re so Barack.', 'ends on a cliffhanger :( :D', 'Overwhelmingly Positive', 95.96, 0.60, 1.00);
INSERT INTO reviews VALUES (41932, 1762570, 199, 'I play on a Super Ultrawide 5120x1440p which i know isn''t a common resolution, the menu buttons were very zoomed in and i couldn''t navigate properly through them unless i lowered my resolution through windows. i filed a bug report through their discord, got a prompt reply from Adam one of the devs and the issue was fixed the next patch. Thanks again Adam!', 'I foolishly thought the game would restart the map if I lost a mission, so I intentionally attacked an enemy station that was more powerful than me to see the epic battle.  I figured I would die, but I didn''t realize the game would auto-save after losing my fleet.\n\nSince I spent all my money on this fleet, I did not have enough money to repurchase ships, so it is quite literally a "Game Over" situation with no manual save or load features.', 'Very Positive', 80.90, 6.75, 4.62);
INSERT INTO reviews VALUES (41942, 1762930, 332, 'Still as fun as it used to be. Definitely the definitive way to play on PC with the quality of life improvements brought by the remaster, for example the ability to swap out mutators mid game, something the original PC release lacked.\nThe price tag is a bit high for a remaster of a ten dollar game from a decade ago though.', 'You''re not supposed to joke about making a "low effort cash-grab" and then actually release it like that for full price. Textures don''t even load in properly either. I''m extremely disappointed, which is not how goats are supposed to feel! Probably the first bad thing coffee stain has done relating to goats.\nI''d buy the original three times over buying this.', 'Very Positive', 83.13, 5.73, 0.20);
INSERT INTO reviews VALUES (41944, 1763030, 134, 'After I played this game, I learned how to mod Unity games and built a randomizer for it. I think that speaks for itself.', '"we have Tunic at home"', 'Very Positive', 89.55, 35.67, 3.58);
INSERT INTO reviews VALUES (41946, 1763050, 1309, 'The game is somewhat broken for me. I can''t progress after being picked up by Jason; the LMB to talk doesn''t function during that part. \r\n\r\nNonetheless, I love the atmosphere of this episode and being in a situation where you are stranded during the night adds to the suspense of the game. \r\n\r\n', 'Even though I think this game has great potential , My greatest issue with this game is the lack of settings or anything for that matter , My entire playthrough was painful, sensitivity is super high with no way to change it and alot of bugs that made me reset to the point I have gotten bored of even trying to play it to the end.', 'Very Positive', 87.24, 5.03, 1.10);
INSERT INTO reviews VALUES (41959, 1763250, 1479, 'It''s absolutely a Hades knock-off. Does that stop it from being fun as hell? Not at all. Great game.', 'I reluctantly have to tell people to wait on this game.  It''s a fantastic Hades-clone with co-op.  In fact its almost everything you''d probably want in Hades co-op.  Already having 4 classes, each with 4 unique weapons and skills is a great start to an early access game.\r\n\r\nThat being said the game is plagued with a save wiping corruption issue.  If your game crashes at any point there is a good chance its going to corrupt the save, to which the game thinks restarting from a brand new clean slat', 'Very Positive', 87.63, 7.62, 14.15);
INSERT INTO reviews VALUES (41992, 1764390, 2972, 'Very cute, fun, and wholesome game. Only complaint would be that it''s 10 dollars for just about 3 hours of game play, but I''ve spent more than that to shoot an airsoft gun at targets for about 30 seconds in a mall, so pick and choose your battles.', 'one of the worst, most corniest power of friendship ass games ive ever had the misfortune to play', 'Overwhelmingly Positive', 97.85, 3.15, 1.22);
INSERT INTO reviews VALUES (41998, 1764530, 1418, 'ADDICTIVE! The sailing experience in this game is better than ATLAS, NAVAL ACTION, SKULL & BONES, PIRATES OF THE BURNING SEA, UNCHARTERED WATERS...I''ve played all these games.  Sailwind makes you really sail your ship.  You not only control your rigging, wheel, and rudder but you can also modify it in the shipyard to your liking.  Change your masts, sails, mizzen, bowsprit,  forestay...etc.  Also, this game requires navigation skills and duly gives you access to all the navigation tools necessar', 'It''s a great game, but unfortunately development has slowed almost to a complete stop. When I bought the game a few years ago, the dev had put up a roadmap with all these awesome things on it like VR, multiplayer, making the sailing even more realistic, more big ships, etc. It''s basically the same game it was when I bought it in 2021. So far this year, there was an update in June with better mooring lines. I''m so sick of being sold a promise and then the game being stuck in EA forever.', 'Very Positive', 90.97, 302.47, 161.32);
INSERT INTO reviews VALUES (42058, 1765780, 669, 'Being a hardcore HL2 fan, this game really hit home. Everything from the ominous environments and glowing soldier eyes, to the gravity gun-like object manipulation made this game truly a spectacular experience. I havent adventured much into the Zone Patrol mode extensively but from what I did experience it was a wild open-world action movie that 64-bit Gordon Freeman would be proud to call home. Pendrake, you knocked this one out of the park. 100/10', 'Could have been great, gunplay seems fine, level design isnt great but i must ask why non binary? What does that contribute to the game over all? Others say it''s missing a complete story, I won''t stick around to find out.', 'Very Positive', 91.33, 23.25, 0.72);
INSERT INTO reviews VALUES (42069, 1766010, 418, 'I always wanted to like ultrakill but I could never get into it. Now there''s a cute robot girl. I like girls.', 'Force Reboot seems to take elements from its inspirations and water them down. Movement just feels "nerfed" and its options don''t work together quite well like in Ultrakill.\nYou''re told to make use of your dashes, slides and jumps with kills to build up speed, but these options feel too short/stubby, and half of the rooms (which tend to repeat too often with same enemy placement) are too small to stay mobile in with enemies charging at you. Enemy weak points are hard to read with these graphics ', 'Overwhelmingly Positive', 95.69, 1.77, 1.37);
INSERT INTO reviews VALUES (42071, 1766100, 687, 'All the negative comments about gameplay or difficulty are just people who are really bad. Good game, don''t listen to clowns, they probably couldn''t even beat ds2, this game def got that ds2 charm, and isn''t nearly as broken.', 'I want to love this game but the mechanics and game feel drag this game from an 8 to a 4 imo. The art style is great and story seemed alright from what I could manage. People love souls-likes because the gameplay is difficult to learn but rewarding to master. The difficulty in The Last Hero of Nostalgaia isn''t due to the game but the unpolished mechanics, the enemies can attack seemingly as fast as they want while you have a 2-3 second delay between yours. That alongside how hard even the weakes', 'Very Positive', 80.35, 3.52, 2.43);
INSERT INTO reviews VALUES (42087, 1766390, 425, 'I bought this game because I liked the developers second game, Pyrene. This game is very similar, and its mechanics are clearly the building blocks of Pyrene. I do like this art style a lot more though, darker and pixelated. I also like the music. Forward: Escape the Fold is a very simple game with very short runs, but it''s fun to play and is well made. I bought it on sale, and it''s definitely worth the ~4 euros I spent on it.', 'Fun game but missing core QoL options like animation speed and keyboard support. Becomes a slog because of that.', 'Very Positive', 83.76, 4.72, 9.82);
INSERT INTO reviews VALUES (42097, 1766720, 194, 'A really fun and engaging game, but for the base price I expected to get more hours out of it without having to continuously dish out $$$ for new DLC.', 'Relatively simple city builder puzzle game. As you go through the campaign, more buildings and mechanics open up.\r\nReason I cannot recommend is that the game throws challenges at you without providing good ways of solving them. A specific example is the use of decrees to tell the villagers what to focus on. This can be work harder, or make/don''t make babies. But then it throws challenges at you like keeping population capped. Seems simple enough to tell villagers simply not make babies when popu', 'Very Positive', 94.33, 212.38, 4.13);
INSERT INTO reviews VALUES (42098, 1766740, 10473, 'Personally, I feel we need more games like this, small in scope but confident in what unique aspect it''s going for and not padding out extra game time with busywork. Choo-choo Charles is very upfront about what you''re getting: a survival game where you''re being hunted down by a demonic train, with some extra side quests and objectives should you want to do them. And for me this was great: take a small idea and turn it into a short, fun experience.', 'Almost $20 USD is simply not worth it. A very basic bare bones game worth less than $10 USD. I finished it in just under 2 hours, there is no real replay value.  The memes and the funny/horrifying train Choo Choo Charles'' design/art are good, but the game simply isn''t. ONLY BUY ON SALE, if you really want to play this.', 'Very Positive', 92.36, 6.98, 1.88);
INSERT INTO reviews VALUES (42102, 1766790, 242, 'Nice game\nEZ to get all achievements 100%', '100 Hidden Birds 2 is a very simple hidden object puzzle.  Find 100 hidden objects in a large 2D line drawing of a slightly urban area with some fields and apartment buildings.  The whole thing might as well be done in a web browser. \n\nOnce more the Russian art is ok, but again being wasted on a shallow, Adobe Flash tier point and click experience.\n\nThere''s just not enough gameplay or enjoyment in this to recommend anyone should pay for something this simple, short, and unengaging.  Steam is for', 'Overwhelmingly Positive', 96.69, 1.97, 4.13);
INSERT INTO reviews VALUES (42112, 1767170, 103, 'A fun blend between gacha and roguelite gameplay. The story is about a group of girls debugging different games representing different stages. The characters from the games are bullets, functioning like cards that can then be differentiate with cartridges that grants different benefits. Battles function like a JRPG battle where the enemies have turn indication that tells the player how much action they can take before the enemy acts. Each bullets then have costs which then brings the enemy turns', 'Unbalanced to the point the only way to finish and win the game is by avoiding fights until you reach the boss.', 'Mostly Positive', 76.70, 14.25, 2.02);
INSERT INTO reviews VALUES (42126, 1767560, 108, 'very entertaining, loads of options for playing', 'While the 2022 version is the most refined so far, it''s pretty much the same as the last 5(?) years. If you have any of the previous versions, I would not buy this one.\n\nLoading times are super slow as always, TT''s are notoriously boring with all the wait time (Where is the skip button?), progression system needs a major overhaul, and the worst part is the peloton system which is just awkward to use.  \n\nThere are so many things that could easily be implemented that would elevate this game to ano', 'Mostly Positive', 78.70, 80.15, 29.98);
INSERT INTO reviews VALUES (42161, 1768280, 753, 'Fun game, rules are simple enough to easily grasp but allows for emergent gameplay. Encompasses Civ''s feeling of "just.. one more turn" quite well, and the games are relatively pretty quick.\r\n\r\nHowever, the game UI could use some polish. One gripe I have is that after winning I''m not able to see which missions I''ve completed (wonders built) to get the winning crowns. Even after saving and reloading a turn before, that section is wiped - don''t know it it''s intentional, but I would like to be able', 'Every game you play in Ozymandias plays exactly the same.', 'Very Positive', 88.71, 22.75, 11.57);
INSERT INTO reviews VALUES (42173, 1768640, 1663, 'Came to smile.\r\nCried.\r\nBeautiful storytelling.\r\nBroke my heart and fixed it all over again, bully.', 'with the rating "Overwhelmingly Positive" i came in with a bit of expectations, but was sorely disappointed. DISAPOINTMENT - is a single theme running throughout this whole thing.\nanimations and renders are weak to say the least, especially first half of the story - pretty terrible.\nstory itself is super stretched out. a lot of dialogs that are just watering down the story - more is not always better.\ni feel like author tried touching on serious subject an i should give him credit it was done fa', 'Overwhelmingly Positive', 96.27, 37.95, 27.10);
INSERT INTO reviews VALUES (42177, 1768780, 147, 'I was having fun optimizing my character till one day I was staring at my level up screen and I realized I had built into a stealth archer... AGAIN.\r\nI haven''t played the game since out of shame.', 'This game starts with the feeling it will be fun but it goes downhill from there. Every time you level up, the monsters you fight seem to level 10 times. By the time you get halfway through, you will be going up against things that will one hit kill you while you can''t make a dent in their hit points, that while they have other enemies with them who are stronger than you.\n\nSpells/skills you get early on are the same ones you will be using all the game. Don''t be hoping for something powerful when', 'Mostly Positive', 78.91, 11.07, 29.38);
INSERT INTO reviews VALUES (42184, 1768920, 141, 'This is what I imagine is happening inside of my body each time I take my Hrt meds.', 'It''s a solid gimmick shooter, but gets repetitive fast', 'Overwhelmingly Positive', 96.45, 0.82, 7.18);
INSERT INTO reviews VALUES (42197, 1769170, 631, 'The golden standard for turn-based dungeon crawlers. Probably one of my top games of all time, which might seem off if you look at my Steam hours only. This game is free on the Google Play store (there aren''t even any ads or a garbage energy system or anything, it is literally just the full game for free but on your phone) and it is probably the only game I first found on mobile that I will ever sing praise over. I''ve definitely got well over a thousand hours total on this game over all its past', 'consume random nearby substances to find the strength to use new equipment and hope they don''t kill you', 'Very Positive', 92.87, 146.72, 0.95);
INSERT INTO reviews VALUES (42201, 1769270, 132, 'Love this game very simple very easy! As a casual gamer may I ask that in the club mode, can you add a cheat mode? Where money doesn''t matter, as well as in exhibition mode can you have the option to play the whole team or specific players? Great game love it thank you!', 'The game was nice before. But now its difficulty levels are beyond human capabilities. The only playable game difficulty is  "Easy" but it''s too easy while "Normal" is already very difficult. I don''t want to mention other levels, they are impossible to play.', 'Very Positive', 91.67, 231.68, 23.48);
INSERT INTO reviews VALUES (42209, 1769420, 938, 'Really great game. I like the verticality and the customization. I can built up 16 levels and I can build down 16 levels. Tunnels and Towers. There are few Rim or DF-like colony builders that allow that. I really like Colony sims where I have the individuals with story and levels and the overworld with travel and combat and conquest. This game does all of that. The customization is really good as well. Cannibals, Vegetarians, what... or who.... to wear. Really good. I also personally really enjo', 'Why am I giving this a bad review? In one word: poo.\r\nThe poo mechanic in the game is ridiculously unbalanced and my villagers seem to spend all of their time pooing and then cleaning up the poo.\r\nIt might make sense if the poo was useful for anything, like collecting it for fertilizer as some other survival games do, or if you could build an outhouse or something to keep the poo confined to a limited space. But no, it''s just poo everywhere, like a flock of ******* pigeons.\r\nIt seriously has rui', 'Very Positive', 83.26, 45.58, 63.12);
INSERT INTO reviews VALUES (42224, 1769830, 125, 'Dude it''s the most incredible deckbuilder roguelike since slay the spire, every run origin ("class") is so different and the draw and energy mechanics have fun particularaities to them. The town turns feel meaningful and make preparing and choosing your fights more fun, I''m having a blast.', 'There was potential here, but the current state of the game is just baffling. The dev made the mindboggling decision to scrap the original system of 20 gradual difficulty levels in favor of a few massive, jarring jumps in difficulty. The result? The very next difficulty after your first run throws enemies at you with one-shot attacks that can delete your units or your tower outright. It’s not challenging—it’s cheap and frustrating. It takes away any sense of progression and replaces it with tria', 'Very Positive', 92.80, 45.40, 3.38);
INSERT INTO reviews VALUES (42230, 1770050, 112, 'The same as all the others of simular nature. It is not easy . It took awhile to learn the basics all again after playing open world games.', 'Game doesn''t feel like a strategy game when the game registers over 500 misses in one battle of a campaign!! Come on!!  The game had no tutorial either so you are thrown into the game not knowing what to do.  So you have to read EVERYTHING to learn how to play this game.  Game designer''s evidently to lazy to put in a tutorial to jump right in.  Think it took like 2-3 battles just to learn how things worked.  I thought if at least this was a casual strategy war game like Panzer General I could en', 'Mostly Positive', 74.11, 82.47, 19.28);
INSERT INTO reviews VALUES (42232, 1770080, 564, 'Cheeky and fun game! looking forward to the full release. very promising story', 'SCAM - it was abandoned - no updates in over a year - DO NOT BUY.', 'Mixed', 42.91, 6.15, 4.18);
INSERT INTO reviews VALUES (42240, 1770210, 134, 'Price of Power is one of the better AVNs I''ve played. It is part of a growing group of games that I define as erotica, focusing on quality storytelling and character development with sexual relations as a natural and accepted part of those characters'' lives.\n\nKudos and thanks to the developers and writers of Price of Power and similar games for giving players like me a welcome and satisfying alternative to the too often trite material offered by so many AVNs.\n\nFemale characters are gorgeous, com', 'It had a good start...attractive characters, interesting story, better than average lewd scenes. It has gone down the tubes shortly after that. The story has become stale and boring, lewd scenes are almost non existent and the entity -whatever it is- is now plain annoying. Interesting enough, I had a few exchanges with the developer through discussion boards who anknowledged the issues and welcomed my feedback , promised improvement in the next chapters but nada. It is as if he is really fond of', 'Mostly Positive', 79.10, 43.02, 3.62);
INSERT INTO reviews VALUES (42276, 1771070, 128, 'A short but spooky point-n-click. I appreciate the retro style and animations.', 'I like the 80s feel overall. But the game is way to short. Feel really ripped off. This is so short it should be a freebie game. I will definitely be wary of these type of games in future.', 'Overwhelmingly Positive', 96.09, 0.80, 1.52);
INSERT INTO reviews VALUES (42281, 1771180, 162, 'This game is better than FIFA and PES.', 'No players online really, only bots you can play with... and still get trashed on by some Easy level bots bro like-', 'Very Positive', 91.36, 4.98, 1.10);
INSERT INTO reviews VALUES (42287, 1771300, 39847, 'Imagine an AAA game with stable performance and little to no bugs on release.', 'Really wish I could be playing it, was looking great… but had to refund as the motion sickness was brutal from walking around. Cutscenes and combat was fine, so I guess it was the head bob but no options to turn it off. Hopefully they’ll add an option in the future or some mod will take care of it cause I’d really like to play it, but right now it makes me want to throw up after a few minutes walking/running :(', 'Very Positive', 93.19, 131.85, 0.90);
INSERT INTO reviews VALUES (42290, 1771360, 171, 'An exciting and dramatic entry in the underrated Choices Matter genre. A good blend of Disco Elysium and classic Telltale gameplay makes for a can''t miss narrative experience. Every choice feels impactful and there is quite a lot of branching paths your journey can take. Gerda is a great protagonist and I was glad to have her be my companion through a little piece of World War 2 history. Good game!', 'I really, really want to love this game. But unfortunately, I can''t.\nFirst, the art style is really creepy! All the faces are blurred. It seems to be a kind of bug, but I think it is just how the art style is.\nThen most of the dialogue is written. Despite the game having spoken narration, most of the interaction is via text you have to read. And not only that. You only get one sentence at the time, and you have to click every time you want a new sentence. That makes the game tedious, and the gam', 'Overwhelmingly Positive', 95.91, 8.27, 0.28);
INSERT INTO reviews VALUES (42303, 1771700, 288, 'I played with one hand.', 'amazing visuals, basically an anime, interesting multiple choices but the game is just WAY too short, I would recommend but never at it''s current state, the game has only 1 chapter which is just way too short and not that much content in it of itself, maybe after another 2 or 3 chapters release then perhaps I would recommend it', 'Mostly Positive', 77.08, 1.67, 0.83);
INSERT INTO reviews VALUES (42344, 1772830, 722, 'The devs added a 7-8+ hour content update with hundreds of rooms and new shit for FREE. Buy this game, the devs absolutely deserve it.', 'Hard to recommend when the combat is so un-fun. It''s not that the combat at its core isn''t fun, but that health pools are so large for even regular enemies that it ends up feeling like a chore to fight anything. The movement is very fun, if a bit finicky at times. If this title was more focused on the platforming and less worried about tacking on combat and having arena fight after arena fight, this would be a must-play. The story is meh. Nothing wrong with it, but not extremely compelling. Musi', 'Overwhelmingly Positive', 95.15, 19.05, 15.28);
INSERT INTO reviews VALUES (42356, 1773180, 235, 'was really fun when I bought it, should of been free to play imo with paid cosmetics or something and needed specific things to be fixed ASAP, there was a game breaking issue I eventually realized where you can easily tell the difference between bots and players because of stutter frame lag the players had and from what i remembered it was either never fixed or fixed way too late for me RIP\n\n', 'Pretty much no lobbies to play on', 'Mostly Positive', 74.89, 13.37, 0.17);
INSERT INTO reviews VALUES (42382, 1773890, 288, 'The 100 hidden dogs game has nice music, and an interesting map layout. It''s a scrollable screen with some animated art in it too, like the moving aliens!\n\nIt was quite challenging as you see many other animes like birds, snails, and cats mixed in with the dogs. These furry companions also blend in so well in some of their environment, like trees, building corners, and ladders for example. I definitely needed to use a guide for finding the last few!\n\nIt''d be nice if the game provided a hints opt', '100 hidden dog shit', 'Very Positive', 93.40, 0.47, 3.60);
INSERT INTO reviews VALUES (42404, 1774580, 41852, 'refunded the game when it first came out cos of optimization issues. i bought it again during autumn sale 2024. the game runs great now on PC and also on steam deck. so yay for sale 🌸 \n\nnow waiting for ubisoft’s star wars outlaws 90 percent discount 🫣', 'I really wanted to enjoy Jedi: Survivor, but the PC optimization is absolutely terrible. Even with the latest hardware, the game constantly crashes. No matter what settings I tweak, it just refuses to run smoothly.\n\nThe worst part? I’m completely stuck on the Jedha map because the game always crashes right before a cutscene. I’ve tried everything, drivers updated, settings adjusted, even reinstalling—but nothing fixes it. At this point, it’s unplayable.\n\nFor a AAA title, this level of performanc', 'Mixed', 67.80, 30.20, 9.85);
INSERT INTO reviews VALUES (42435, 1775490, 1615, 'I don''t know why I purchased this game considering I am not really a turned based kind of gamer, nor am I big on deck building. I''ve tried slay the spire, baulders gate, hades.. you name it , the idea of these style games never appealed to me. So for 9 dollars I figured this might be worth a shot. This could easily be one of the best games offered on steam, if I have to give a disclaimer and say the best game for 9 dollars, sure. The strategy of the game is extremely fluid throughout the rounds ', 'I hate to leave a negative review for this because I actually liked the game for the dozen hours I played it, but the lack of content is definitely too severe to get a pass. I expected more and more enemies, bosses and items; in reality, there''s very few, and the entire gimmick is to unlock bizarre game-modes with strange rules and modifiers, which I have zero interest in. All I wanted is a true endless mode that extended for much longer, instead, the so-called endless mode just loops the same r', 'Overwhelmingly Positive', 96.41, 2.23, 13.77);
INSERT INTO reviews VALUES (42439, 1775530, 535, 'Lately, I have developed a thing for great AVNs. I have amassed quite the collection. I wasn''t sure about this one when it started. I almost noped out on the character''s whiny ass. I am soooo glad I didn''t.\n\nTo say that this is one of the greats doesn''t do it justice. I would say this is easily top 5, if not top 3. The story in Book 1 is told so well, that I have feelings for all the characters. Lots of laughing, and even a couple tears. The visuals aren''t great at the beginning, but that is exp', 'pornography is bad for your health, go start a family I use too play games like these then I met my spouse and now have no reason to play i''m only writing this review so other humans can realize there is more to life than porn.', 'Very Positive', 93.83, 12.55, 15.17);
INSERT INTO reviews VALUES (42440, 1775550, 131, 'Strategy Gaming Dojo has a quick start tutorial on youtube; it''s almost 5 hours long.\r\nThis is THE game if you have autism and likes WW2 eastern front.\r\n', 'Atrocious UI, severe performance issues and crashes frequently.', 'Very Positive', 93.13, 742.38, 0.22);
INSERT INTO reviews VALUES (42509, 1777390, 156, 'If you haven''t played the first game, you should go play it. If you''re tight on your budget, and I mean really tight on your budget, this is a good one to go with. Both games are fantastic. They have a lot of characters, and clearly Barance was looking towards creating a game that is just such a massive improvement over the first game. Higher intensity animations, more impactful storytelling that builds off of the first game, and additional forms of gameplay, character and world building, and te', 'In mu opinion Ui is kinda stale, the the objective is not clearly lead your way and you don''t know what to do next and I just keep work research and rest click on the event and repeat, it literally not my type it not suit me', 'Very Positive', 91.03, 14.52, 1.02);
INSERT INTO reviews VALUES (42516, 1777620, 1057, 'This game is the "anti-Atlus" game. Female protagonist, non-silent protagonist, adult cast. Just from that alone, I already recommend this game. Unfortunately, that is literally its best aspect. The characters are good, the story is good, but sadly the gameplay is pretty subpar. The combat feels slow and tedious for half of the game, enemies give little experience once you outlevel them, and it''s not until you have piled up enough upgrades at the end of the game that fights go swiftly. The dunge', 'Says its playable on steam deck. I try, it isn''t , i try different protons and different launch commands , still doesnt work. Can''t try anymore cause Denuvo kicked in.\n\nFuck you Denuvo.', 'Mostly Positive', 75.69, 44.95, 1.07);
INSERT INTO reviews VALUES (42546, 1778210, 151, 'I got this to play with my 2.5 year old and he really likes it. I get him to tell me which way we need to go to find things. He can get "left" and "right" correct almost 50% of the time now!\n\nOnly problem is the balloons. Whenever we come across some, we''re stuck there for 15 minutes of him launching them into the air,', 'I''m not really sure if King Boo is an asset flip.  Some elements of this game certainly make it seem like the developer put some effort into assembling some kind of original here.  On the other hand, a lot of the game assets don''t seem like they were created by the developer, but they haven''t credited any asset creators for supplying assets, which might be a case of plagiarism.  There''s no evidence, so we need to give the benefit of the doubt... regardless, asset flip or not, the quality here is', 'Overwhelmingly Positive', 98.01, 3.58, 4.02);
INSERT INTO reviews VALUES (42567, 1778820, 21943, 'My headless limbless tumor brother can play this game! Very nice and Accessible! Also, the graphics are so good for a 2D game!', 'I do not recommend Tekken 8 season 2 for these reasons.\n\n-The developers do not understand the characters they design. They see that the character has strengths and weaknesses and continue to not let them have this weakness. Instead, they homogenize the character to be like the others making them overtuned. This was a big issue in Season 1 that made 70% of the roster oppressive. And the game is suppose to favor the aggressor, but it favored the aggressor too much to the point where it will look ', 'Mixed', 56.99, 558.37, 1583.62);
INSERT INTO reviews VALUES (42569, 1778840, 167, 'I’m not usually a fan of open worlds but this one is something special. Decades ago I spent weeks if not months looking for the 17th Colossus in SotC and never sense had a game made me feel that since of wonder and exploration until this one. The music, the lore, the gameplay itself are all made by people who very obviously love what they put into this game. It’s a must try, a must buy, and I honestly can not recommend it highly enough . Already one of my go to games', 'I very much wanted to like this game, but I can''t get a good framerate out of it. Less than 60 FPS just isn''t acceptable when my computer runs other, more graphically intensive games just fine.', 'Very Positive', 81.44, 98.53, 0.30);
INSERT INTO reviews VALUES (42587, 1779180, 162, 'this is the most fun ''jumping puzzle'' platformer i''ve played, and i''m a big fan of this genre.\n\ni was initially a bit reserved in my judgement. the falling blades at the beginning give the impression of a brutal, trolling game meant to vex streamers. i was worried this was ''rage bait''. but it''s not like that at all !! it''s quite fair and learnable. sections may seem tough at first, but i assure you, despite some tricky jumps here and there, it''s all quite achievable. you CAN beat this game with ', 'this game whack asf hope you like vegetables.', 'Overwhelmingly Positive', 95.06, 45.57, 8.12);
INSERT INTO reviews VALUES (42589, 1779200, 882, 'It has promise, but there''s not much to the game past the 2 hour mark. Once you hit multicell stage everything is unbalanced and a mess. Trying to advance past that stage is nearly impossible due to the imbalance of chemicals and the huge amount of competitions. \r\n\r\nOverall, the game is a bit too complex for my liking. I was hoping for something more simplistic like Spore, but this is more heavily science driven to the point that it make certain things far more difficult to understand. After 3 h', 'I like the premise, but the controls are abysmal and the menus are too convoluted.', 'Very Positive', 91.27, 3.83, 0.13);
INSERT INTO reviews VALUES (42597, 1779460, 121, 'Damn bro, you made me cry! 🧡', 'I liked the first game, really liked the second game, and came to loathe this game. The creator tries to get too deep with the story about a silly mayo jar and makes you spend upwards of 30 minutes holding shift and w to run through an extremely boring forest while surface level thoughts float across the screen. It was a horrible way to end the series.', 'Overwhelmingly Positive', 95.87, 1.60, 1.08);
INSERT INTO reviews VALUES (42602, 1779560, 158, 'A fantastically fun and danged tough NEW-OLD arcade experience starring a potbellied little baker with jug ears.  The Donkey Kong parallels are obvious -- but you actually have mid-air and falling control if you jump straight up, or even close to straight up (you can hop into and hook back from the nearest ''nut in Dodo''s Lair before you fall on the spikes, for example).  Sure, it lacks the cruel, lead-a$$ed trajectory of Mario''s first outing . . . but in this game you''ll have to contend with a b', 'You jump lower than Mario and there are zero, ZERO ways to stop enemies. Easy-Medium Mode is already punishing, so be prepared for what comes next. Not for casual play!', 'Overwhelmingly Positive', 98.10, 6.70, 0.98);
INSERT INTO reviews VALUES (42647, 1780370, 150, 'I understood nothing', 'The art is very engaging and I enjoy it a lot. However, there are less interactive elements than I was anticipating. At many points it feels less as if I''m actually making any decisions and more like I''m being dragged along for a story that I don''t have any control over. There are a few times where the text is clunky and hard to understand. I recognize that this is more of a personal gripe, but throughout most of the story I do find the protagonist to be annoying. The story feels as if it''s cons', 'Overwhelmingly Positive', 98.67, 4.58, 1.55);
INSERT INTO reviews VALUES (42676, 1781030, 120, 'you can sell me on a game if it has fishing in it', 'grindy and boring fishing minigame, which is insane considering that''s the entire game. even the fishing component in stardew, animal crossing, and survival crafts games are better, where it''s basically an afterthought. it would be fine if the story was good, but it might actually be worse than the gameplay', 'Very Positive', 90.00, 38.08, 3.92);
INSERT INTO reviews VALUES (42725, 1782150, 207, 'Roses are red, violets are blue\nI want to hug Clementine too!', 'I''ll add more as time goes on, but simply put: this game is a disappointment for both regular gamers and fans of the franchise, and downright insulting for completionist.\n\nI''m back, and after writing a lot here then having it all get deleted from steam''s shitty design choices, I''m just gonna keep this short: Unpolished gameplay and game design, thin ass story, contradicting level design to what we actually know about the Great Tomb of Nazarick. But thing that takes the cake for insult to injury ', 'Mostly Positive', 72.46, 265.50, 24.02);
INSERT INTO reviews VALUES (42733, 1782330, 774, 'The only reason this game gets hate is because of no co-op which i think is weird. Just because it has been abandoned by devs doesn''t mean it is bad. At the same time i do kinda understand the hate because there hasn''t been a update in awhile which is bad.', 'Bought this in anticipation of the promised co-op that''d be implemented. The devs were gonna keep us updated, they said. The update we now have is that co-op will be releasing on December 16th for Quest and PSVR only. The PCVR version has been shamelessly abandoned.', 'Mixed', 56.85, 20.77, 0.18);
INSERT INTO reviews VALUES (42742, 1782570, 413, 'It''s seems like a nice game,  just started to play and nothing but problems. After completing and validating the contract.  The computer in the game wont let me exit out of it by hitting ESC key. Only way out is Alt F4 and exiting the game completely', 'Buggy from the start. I read the reviews saying it was buggy, but went for it anyways. Poor decision on my part. Tons of initial issues clipping with the hand cart. Then I couldnt exit the PC screen after turning in my first contract. Had to alt-f4 out of the game. Id pass.', 'Mixed', 44.79, 3.20, 0.98);
INSERT INTO reviews VALUES (42749, 1782670, 281, 'This is litterally just Bronx life rp from Roblox with a graphics over haul like litterally same layout and everything', 'FAKE WANNABE DEVELOPER, this game is a fraud, no missions, no story, straight bugs and problems. This guy who is behind this is a FAKE BUSINESSMAN who knows nothing about technology and game creation. POOR EXAMPLE of a game, this should be banned from STEAM.', 'Mixed', 51.96, 10.58, 0.83);
INSERT INTO reviews VALUES (42777, 1783110, 741, 'This is my second AVN after Leap Of Faith (which is totally awesome). Ignoring the ''adult'' content (which is fine) what i like about this is the characterisation and the dialogue. Many times I laugh out loud and many more times i smile. This is good writing and well worth the price of entry. If Leap Of Faith is 9/10, this is 8.5', 'Enjoyable, however, it would be nice for those people that have paid for the game to receive regular development updates on steam, and now have to go and pay x amount of US dollars a month for development updates. The game has already been paid for, and I feel it is unfair to expect people now to fork out a monthly cost to receive those updates. I have many games that I have paid for where updates are not charged for and regular communication is provided. Your last communication was on Patreon 3', 'Very Positive', 93.52, 16.10, 31.00);
INSERT INTO reviews VALUES (42782, 1783360, 223, 'Undertale and Monsters Inc. had a beautiful love baby... And now she''s looking for her mom.\n\nUnderrated little gem. Clearly a labor of love, short game that''s bound to leave any story-driven rpg fan emotional.', 'Boring, didn''t move me at all', 'Overwhelmingly Positive', 95.52, 8.45, 4.23);
INSERT INTO reviews VALUES (42792, 1783680, 116, 'Another gem from Sarepta Studio, it manages to balance slow but enjoyable pacing with excellent investigation puzzles and more. I won''t spoil it for you - so grab it yourself and check it out. \n\nAbsolutely recommended! :)', 'Thalassa: Edge of the Abyss is a satisfactory combination of walking sim and detective game, despite a few notable problems. With a clunky start and some believability concerns, it takes a while before the game settles into an agreeable state. While most of the mysteries are easy to clear, there are prominent issues with some clues and deductions. Traipsing back and forth through the shipwreck is more irksome than interesting, despite a few good holographic memories to witness. And with the game', 'Very Positive', 91.38, 1.63, 8.72);
INSERT INTO reviews VALUES (42798, 1783800, 200, 'Better than Linux', 'Pony Island it may look like, but Pony Island it is not. It''s a Sokoban game with an odd aesthetic, and nothing more. Not gonna rip on it too badly, as 2 hours entertainment for the price point isn''t *bad*, I was just expecting something more than pushing boxes around.', 'Overwhelmingly Positive', 99.00, 1.40, 1.78);
INSERT INTO reviews VALUES (42803, 1783960, 115, 'I love Fetishists!', 'Everyone looks at me weirdly when I tell them I afk''d this game for 30 hours for fun, it''s funny though.', 'Mixed', 63.48, 47.88, 36.17);
INSERT INTO reviews VALUES (42825, 1784780, 295, 'This is the shortest game in whole hero of the kingdom series. It feels like this is the first demo game of this series. It is too short  , i have completed game within 4 hours with %100 achievements with really really slow pace.\r\nDo i suggest this game ? Yes it is 100x better than the 3rd game of this series. But try to buy it when it is in discount otherwise just watch it on some streaming services.', 'Terrible game compared to the others in the series.  Non-stop backtracking one fight at a time to buy specific potions.', 'Very Positive', 87.80, 4.25, 4.90);
INSERT INTO reviews VALUES (42839, 1785150, 6588, 'Really addicting game, good community. This game is underrated and needs more attention, but unfortunately the generic game title works against it in terms of YouTube algorithms and SEO.', 'I enjoy the game WITH MY FRIENDS because we are around the same level and skill but when i decide to play\r\nmatchmaking the game gives me players that are at crazy high level if not MAX. the game fun WITH FRIENDS.\r\nwould not recommend matchmaking', 'Very Positive', 85.28, 148.15, 76.23);
INSERT INTO reviews VALUES (42847, 1785300, 141, 'Fun, mildly spooky VN about the perpetuation of generational trauma in several young women from a strict religious sect. It will likely resonate with anyone who went through even much milder indoctrination, and has the added bonus of some of that gnarly old-time religious ''why are they praising this highly messed-up thing?'' If you''ve ever been taught to venerate women who starved, scourged, or mutilated themselves out of love for God, you know exactly what I''m talking about.  \n\nI didn''t personal', 'This game is so boring and the voice actors are quite bad, especially Holy''s voice, she sounds so fake. To me, it''s 3/10. I bought it because The letter is so good but this game is totally a bummer. Luckily, it''s cheap.', 'Very Positive', 86.52, 3.98, 8.37);
INSERT INTO reviews VALUES (42873, 1785940, 128, 'This game is being slept on feels unique for a fps game, I hate Quake likes but loved this, great music, fun actual magic feeling weapons,fun game mechanics like bullet time, corpse/testicle eating etc.', 'So much potential but a failed execution. When you think of Boomer Shooterers you think of the following, shooting, movement, powerful guns, and a overall power fantasy. This game gives you cool guns and magic but after giving you all this cool stuff its immediately turns into some sort of survival horror bull crap where it starts rationing ammo likes its Russia in 1945. For example it gives you this super shotgun weapon thats so much fun to use but your rarely ever have  more than six shells at', 'Overwhelmingly Positive', 95.31, 6.22, 2.82);
INSERT INTO reviews VALUES (42885, 1786200, 241, 'Can full auto the bolt action rifle.', 'Dead game, devs has left the village looooooooooooooong time ago.\n\nSo if you wanna buy it, consider this fact.', 'Mixed', 53.53, 7.90, 4.60);
INSERT INTO reviews VALUES (42920, 1786790, 254, 'You need a free patch from kaguragames website to get the full game.\r\n\r\nIt was so easy to find that I legit forgot how I did after downloading it. I think the brainrot is getting to me.', 'Got unfinished buggy game. The game menu disappeared after go to Oasis and changing to bath so, can''t load/save. I figure out that the game version on Steam is not the latest version (1.07.1) which released around 2022 and, none care to release the update on steam. This is not the first game with issue from this publisher so, don''t buy this in steam and maybe other game from this publisher.', 'Very Positive', 93.31, 24.67, 4.00);
INSERT INTO reviews VALUES (42937, 1787090, 533, 'Turned my Razer Blade into a frying pan, now I could make steak and eggs and eat it on a cutting board with honey and avocados with my bros while half naked 100/10 would recommend for bromance.', 'Awful and unstable. Steals your data. Very scammy.\nI had this program opened for 5 minutes or less and it took 1 minute to open. Looking at the task manager, there were 2 apps linked under mydockfinder.exe tilted "數據分析器" and "加密轉儲工具" which translates to "datamining.exe" and "cryptodumping.exe"\nIf you don''t know what that means, it means that it is literally stealing data, using your computer hardware to mine crypto and dumping crypto that you have on your computer. Luckily I don''t own any crypto', 'Very Positive', 84.43, 0.85, 0.08);
INSERT INTO reviews VALUES (43062, 1789470, 234, 'Incredibly short, and basically what you see is what you get : some basic dungeon crawling reminiscent of the old day of dungeon master, some short sexy scene, and a bit of humor.\n\nThe execution is very good though; the visual style really works well, the movement is nice, the difficulty is fairly balanced… it is a shame that there is little meat on this bone, though. Still, for that price, it''s a nice little romp.\n\nI''d be curious to see more of that.', 'repetitive sex scenes', 'Overwhelmingly Positive', 96.58, 0.40, 0.45);
INSERT INTO reviews VALUES (43063, 1789480, 10572, 'I love this so much so cool. way more awesome than I thought it would be buying it tonight. Really awesome !', 'I would never buy this game in its current state. Its an entirely PVP focused game with a diminishing player count. I think that it is necessary that this game has some sort of a PVE or campaign option its the only way this game can be seen as a viable purchase. \n\nI really enjoy the gameplay, style, "story", and mechanics and would love to play it in another form rather then just PVP.', 'Mostly Positive', 73.58, 1.72, 62.62);
INSERT INTO reviews VALUES (43064, 1789490, 370, 'An adorable little dating sim; I loved all of the possibilities, however I''m sure theres a lot more to be developed; Took me less than 3 hours to finish the game and with only 12 characters, its over pretty fast. Would love to see if the developers expand on this; some new characters would be cool to add, or even a quirk system for your ghost so you can customise your playthrough even more :)', 'Super short game with minimal activities.  Maybe a good time waster if it were one sale, but definitely not worth $20', 'Overwhelmingly Positive', 97.57, 2.67, 3.90);
INSERT INTO reviews VALUES (43082, 1790370, 188, 'Very fun, casual resource management game. Some of the minigames have more depth than others, but the variety and speed of progress keeps runs fresh all the way through.', 'I liked this game before they changed the system for hacking buildings. With the old fear system, where the fear for each hack was based on who was around each item, the hacking minigame was more skill based and required more planning. But I can''t wrap my head around the new system, which seems to just randomly give you fear points for the hell of it. It''s not as fun and doesn''t reward skill. I just ignore the overhead lights now- they used to be a huge part of the strategy, but now they''re usel', 'Very Positive', 80.32, 45.98, 66.52);
INSERT INTO reviews VALUES (43088, 1790490, 102, 'This game is SO good! ❤️ Please Bring the next game soon!', 'Eventho I love puzzle games, this game didint get my love. It''s alright game, some puzzles were super easy and some puzzles, eh difficult. Sometimes I had to use guide because I had no clue what to do because of lack of hints. There is "hint" section, but it only show one hint and that hint doesnt help at all. If it could give more hints , it would made better game experience. \n\nIf you like puzzles and  are not capable/doesnt like to overthink, then this game is not for you.', 'Very Positive', 87.25, 0.37, 2.35);
INSERT INTO reviews VALUES (43092, 1790600, 26780, 'I know they said they weren''t going to worry about balance with respect to the power levels of different characters, but I really have to question the decisions of the developers that led to them including Mr. Satan in this game. I picked him once against a friend as a funny joke and he had to power up Gogeta all the way to SSGSS just to stand a chance against the Dragon Ball Delibird.', 'the game been out pretty much a whole month, and they still haven''t fixed the communication error. I get kick out of pretty much every online match.', 'Very Positive', 88.86, 84.57, 102.52);
INSERT INTO reviews VALUES (43140, 1791790, 131, 'i just wanna thank this game for existing', 'I was gonna recommend this game as a fun little game\nhowever the game ends with you being captured by the nazis\nI think you even get executed at the end', 'Very Positive', 83.97, 2.43, 1.98);
INSERT INTO reviews VALUES (43161, 1792250, 1403, 'Somehow, a fan-made side-story to Serious Sam 4 is formally adopted by Croteam and turned into something that exceeds Serious Sam 4 in almost every way. Better designed areas, better looking areas, new weapons and enemies, but still that excellent core gameplay of destroying hordes of enemies, backed by another amazing soundtrack.', 'As the game already has enough positive reviews, I''m ok with giving it a negative one.\r\nI have played all the Serious Sam main game saga, I''ve been here for it since SS(1) and maybe because I did i just can''t let this one go, the game play has, even by what I''ve read, changed a lot, it does not feel or play the same, its more punishing in petty unfair ways, I always feel forced to do things like using the biggest gun instead of outsmarting or outmaneuvering the onslaught, enemies are weird and c', 'Very Positive', 91.30, 3.90, 11.50);
INSERT INTO reviews VALUES (43194, 1793030, 117, 'the only reason i haven''t bought Revenge of the Seven yet is because i haven''t been able to stop  playing this one.', 'The leveling up structure ruins this absolutely charming game. The artwork is unique; the attacks are diverse; the strategies abound. Unfortunately, as another reviewer has recognized, the ''leveling up'' structure is such that the enemies parallel your advancements step for step. Meaning as you grow stronger so does each enemy--and they generally start off ahead of you from the jump. Sad :(', 'Very Positive', 90.60, 75.48, 14.45);
INSERT INTO reviews VALUES (43202, 1793170, 117, 'Loving this game. There''s deck building, real time strategy, and even some rhythm elements. The game gives you just enough information, and then lets you learn the rest on your own. Definitely gives some vague slay the spire vibes, but I love the mechanic of building up your skills every time you play a card. My efficiency-minded brain loves it.', '\r\n3/10, cannot recommend. Had an amazing run up until the end. The boss sets up a wall that couldn''t be broken because I had a more defensive build, despite me having crazy amounts of Speed, Crit, and Reflect. But the boss also wouldn''t kill me because I had crazy amounts of Evade, Armor, and Shield. Which means the only thing to do was to remain AFK and let the game play itself out. Came back hours later, nothing had moved. Never played a roguelike deckbuilder that punished you for doing well. ', 'Mostly Positive', 71.79, 12.12, 21.57);
INSERT INTO reviews VALUES (43208, 1793260, 110, 'As an ex-Uber Eat delivery partner with 97% positive stats, I really enjoy this game. I can''t wait to see more DLC on this. There is this sense "accomplishment" buy delivering something or someone in time. \n\nGj on this game ^^\n\nps: Special request to add the "Bat Mobile" as a "cosplay" luxury car, a TRON motorocycle, a Akira Motorcycle and of course the famous "Bumble Bee" car. \n\nThanks.', 'Ultimately this game lacks much content and is highly repetitive. If you like sending things from place to place, with a few considerations to keep in mind like what combinations of passengers and luggage can go in each vehicle, this is worth getting on sale (like I did). Otherwise, after about three hours of playtime I felt like I''d already done everything here.', 'Mostly Positive', 75.45, 17.85, 7.57);
INSERT INTO reviews VALUES (43229, 1794470, 523, 'A little boring, but decent for this price', 'story line is pretty boring, has some bug or something that makes it reset to the start screen when loading a new scene  so make sure you save often.  got repetitive really fast and was just not interesting', 'Very Positive', 80.50, 11.38, 23.55);
INSERT INTO reviews VALUES (43232, 1794680, 120911, 'so its a 10/10 game, i love it, but i can literally never play it again because after i played a 3 hour session ALL I SEE WHEN I CLOSE MY EYES IS BLUE AND GREEN GEMS AND ITS NOT GOING AWAY ITS BEEN HOURS IM NEVER PLAYING THIS GAME AGAIN\r\n\r\nhighly recommend', 'I picked up this game very early in its development. While it still remains dirt cheap to buy, I think it''s lost track of what made it fun and is outmatched by all of its successors in the genre it created.\n\nHere''s what I mean by that. At some point, I went through the trouble of resetting my savefile, and sure enough, the game is pretty fun when you struggle to scrape by, slowly getting unlock and little permanent upgrades. But inevitably came a point that I had nuked my save to avoid : with th', 'Overwhelmingly Positive', 98.60, 9.10, 140.62);
INSERT INTO reviews VALUES (43238, 1796470, 4335, 'At 3 PM local time, in a random discord server I was in, I showed them the videogame "HASTE" with the comment: "I hope this game comes out".\nI wishlisted the game then, though I''d known about it ever since the initial mechanical demo.\n\n2 hours later, 5 PM local time, I get an e-mail from steam: "HASTE: Broken Worlds is now available on Steam!"\n\nYeah. That''s pretty fucking hasty, alright.', 'It''s a good thing the core moment-to-moment running gameplay is so exhilaratingly perfect, because the rest of the game they built around it kind of sucks. I ordinarily like roguelikes, but this game is a textbook example of using the roguelike structure purely as a cynical, or maybe just desperate attempt to pad out their five minutes of genuinely good gameplay into a full-length experience.\n\nIt''s hard to give this a thumbs down when it''s still, at it''s core, really damn fun. But when the game''', 'Very Positive', 92.25, 5.15, 3.70);
INSERT INTO reviews VALUES (43239, 1796580, 1025, 'Silent Hill meets Killer 7 through a super gay bubblegum pop lens with PS1-era graphics and insane boss music.\r\n\r\nDivine.', 'Art style is gorgeous. Writing wise it sucks. How the characters express themselves or how they talk just is not believable at all. It''s corny and sometimes cringe. They talk expressing their archetypes out loud, like saying "IM THE SWEET GUY" and "IM THE BAD GUY" and they are too obvious with what they mean.\nAlso sometimes paths are blocked by the most ridiculous excuses or things.\nThe art is gorgeous but inconsistent in the sense that some npcs has portraits while others don''t have portraits d', 'Overwhelmingly Positive', 98.44, 1.48, 0.43);
INSERT INTO reviews VALUES (43240, 1796790, 1222, 'I work in a kitchen to come home and work in a kitchen! \r\n\r\nGreat game. \r\n\r\nGot my GF to play it, she spent eight hours trying to make it pretty. It doesn''t get pretty.', 'One of the worst things that can happen in a game is to get soft locked in a game. This one does that in abundance. Basically every story quest that involves your eatery has hidden requirements that are also needed in order to open. If you accept the quest, it will not let you open your eatery until you have the hidden requirements (shown after you have already accepted the quest and no longer have the option to go back). This happens for every major quest, no exception. This tells me the dev ma', 'Very Positive', 89.36, 116.50, 36.95);
INSERT INTO reviews VALUES (43251, 1801110, 3872, 'I played this game almost an year ago with my girlfriend! It was the best game ever to play with eachother, even tho we didn''t quite undertsand the ropes of being in a relationship, a game wich made us laugh and cry but most importantly brought us together and strengthened our relationship trough the amazing experience it offered... we wanna play it again with switched roles for the 1 year aniversary since we finished it!', 'they removed the friend pass :(', 'Overwhelmingly Positive', 95.40, 10.55, 5.98);
INSERT INTO reviews VALUES (43260, 1801850, 161, 'Joeseppi sent me here, you too probably. 10/10', 'The game is only 99 cents, so of course I wasn''t expecting a AAA title, but I was expecting a game. Overall this is about 15 minutes of game play  and there is no orientation to what the controls are or the purpose of the game. I usually try and keep my reviews of games positive, but there just isn''t anything positive to share here. At first I thought it might be someone''s small, first time indie project, but there are far too many games under this developer for this to be a first try. It appear', 'Very Positive', 90.68, 0.37, 0.27);
INSERT INTO reviews VALUES (43302, 1802880, 156, 'This game is an amazing experience. Action platforming, parry heavy soulslike combat, fun and rewarding battle mechanics, huge skill tree... The list goes on. I was obsessed with this game during Early Access and now I''ve fallen back in love all over again. Well crafted and just SO much fun to play!', 'The game is good and the story is great. However, before you get to see the ending you have to go do a very strenuous task: go through every single map, all over again, space by space, and look for some new monsters that they secretly added without telling you--and they don''t even mark this monster for you on the map either! You have to kill these monsters to open the way to the ending. It felt like a job except you pay them. So I quit as soon as I realized this to save myself the frustration an', 'Very Positive', 89.74, 37.32, 5.40);
INSERT INTO reviews VALUES (43326, 1803390, 317, 'I''m a truck driver who enjoys casual driving and racing games on my G27 wheel. I am not a "sweaty" when it comes to driving games because my entire IRL day is spent swearing under my breath because I''m stuck behind a chowderhead doing 32 in a 45 and/or literally sweating because the state police are trollin. I honestly bought this thinking "How much fun could DRAG racing possibly be in videogame format...?"\n\nWell whoever made this game made it fun as hell - awesome job!! If you are the least bit', 'YOU HAVE TO BUY DIFFERENT CARS FOR REAL MONEY AND THERE IS ALMOST ZERO NOISES FROM THE CARS I NEED A REFUND', 'Very Positive', 86.12, 5.43, 0.47);
INSERT INTO reviews VALUES (43327, 1803400, 519, 'This game deserves WAY more recognition! It is an absolute blast to play because of the music, the atmosphere, and most especially the wonderful mechanics I don''t think I''ve seen in other deckbuilders. The fact that some cards grant you bonuses if they are auto-discarded instead of being played is such an interesting way to approach how a round is played. Aside from Fights in Tight Spaces, I think this game also exemplifies a new standard other deckbuilders should live up to in regards to having', 'Gameplay is okay but the difficulty is far too high. I have reached level 31 after about 11 games and only won once. Destroys any sense of mastery when that one win felt so random.', 'Very Positive', 81.31, 32.47, 26.07);
INSERT INTO reviews VALUES (43328, 1803410, 144, 'My friend and i are pretty much the only players on this game most days, but it''s always a damn good game to end the night on.\r\nI''m better at chess and he''s better at fighting games, there''s a lot of fun in bridging that gap\r\nI B-line for his king and he wipes my pieces one by one but i''ll be damned if it isn''t a hell of a lot of fun!\r\nthe score is 21-14 in his favor, but i''m getting there\r\n\r\nonly downside i would say is that a lot of the moves are almost somewhat hidden ? i could swear we''ve bo', '"We designed Checkmate Showdown with an ''easy to learn, hard to master'' philosophy"\n\nReally? There is no tutorial. There is no difficalty selection. There is no fight vs CPU...', 'Very Positive', 80.56, 31.40, 0.23);
INSERT INTO reviews VALUES (43362, 1804010, 808, 'Pro: it''s a faithful recreation of PS1-era game design\n\nCon: it''s a faithful recreation of PS1-era game design', 'I was genuinely looking forward to enjoy this game. The art style is hauntingly beautiful, and the horror atmosphere is top-notch. Visually, it nails the creepy, crispy retro PS1 aesthetic in all the right ways.\n\nBut the combat? It''s a nightmare – and not in the way the game intended. The system is clunky, slow, and frustratingly imprecise. Nothing about it feels responsive or rewarding. Every fight feels like a chore rather than a fun challenge. \nThe level design isn''t that great either. While ', 'Very Positive', 94.06, 7.28, 1.58);
INSERT INTO reviews VALUES (43414, 1805130, 207, 'Michael Kovach my beloved,,', 'I wanted to like this, truly I did. Unfortunately the most seasoned actors in the world cannot carry a game on their own. Objectively, yes, they are good actors, though at times they are given poor direction. I really think they should''ve wasted less money on such big actors and budgeted more towards their art or even some of their writing.\n\nMost of the character designs are palatable, but there''s no variety in the candidates. 5 wolves and 1 bunny is kind of a small selection so far as species g', 'Very Positive', 93.24, 22.32, 14.37);
INSERT INTO reviews VALUES (43432, 1805480, 2288, 'I love this game and everything RGG Studio puts out,but wow,the grind in ishin is next level.I usually go all-in and try to 100% their games, but this one made me rethink that I found myself wanting to stop because I didn''t want to go crazy and lose my love for the series. It''s a fun game, Not fun for 100% enjoyer since you can actually lose your braincell.If you reading this and actually 100% in this game,you get my respect.', 'This is more of an updated port than a full remake or even a proper remaster. The worst parts of the game are still prevalent and the game wants you play it in a very specific way to get the most of it. This isnt exactly fun when large chunks of the mechanics are tied to doing things like *give x item 8 times to this person* or material collection/ crafting item requirements tied to item drops which both require you to grind the same dungeons + RNG and absurd money on top. SO in effect, you''re g', 'Very Positive', 87.76, 88.08, 125.17);
INSERT INTO reviews VALUES (43503, 1807080, 993, 'A very good recreation of phasmophobia. Graphics are cool, ghost events are scary, atmosphere is a fire and it is much more scarier than phasmophobia or other ghost hunting games.', 'Tutorial cannot be completed since the required items do not spawn or are not available.', 'Very Positive', 86.61, 8.87, 0.85);
INSERT INTO reviews VALUES (43504, 1807090, 182, 'I don''t wanna discourage others. Game just throws serious inescapable and unpredictable scenario on your way. That alone is so discouraging for me  after long grind. I see no incentive to start the game again and play, knowing the unpredictable random  destruction bosses inflict.\n\nMy recommendation is for those with significant pain tolerance. Cheers', ' An unbalanced, dull and unintuitive game. \n\n  Don''t let the skill tree fool you - there is virtually no development choice here, and skill crafting boils down to creating one or two combat skills, one healing skill, one jerk and a couple skills of your choice. \n  \n  There is a plot, a couple lines every two hours. The whole RPG element boils down to +15% poison damage or -4% to the cost of a skil. Enemies are always plentiful and their abilities are simple and extremely nasty - a couple arena s', 'Very Positive', 87.36, 7.98, 9.95);
INSERT INTO reviews VALUES (43509, 1807200, 101, 'This is close to whether I''d recommend or not. Silent hill + amnesia + original half life mixed is what this game felt like. Story is cool and I did find it spooky. There were a few sections of the game that just didn''t feel fun to play, that felt badly conceived. But plenty of health and generous auto saves balanced it out. Overall, a really impressive effort by a small team, but there is room for improvement.', 'one of the indie games of all time', 'Mostly Positive', 76.24, 7.45, 5.87);
INSERT INTO reviews VALUES (43544, 1807810, 210, 'good', 'For being advertised as a heavy metal game it really felt nothing like that at all, the music was pretty tame even in combat, so much so I wouldn''t even call it metal let alone heavy metal. Most enemies seem to just run in a straight line and don''t feel very alive. I feel like the game has potential but really isn''t very heavy metal or horror at all, I think if it had leaned more into those aspects it could have been a lot more interesting. Also the graphics and performance was pretty bad, my PC', 'Very Positive', 83.33, 29.13, 0.37);
INSERT INTO reviews VALUES (43546, 1807930, 108, 'The puzzles are good.  It gets decidedly less fun once you have to make ridiculously elaborate back-and-forth journeys across the whole islands multiple times, the mental strain of keeping the switches for the tracks in mind when designing get quite burdensome.  On top of that, the music is quite poor, a very short melancholy clip on loop that feels neither relaxing or engaging.\n\nIt also resets camera location and re-rolls the goods in each station on each retry for some bizarre reason.\n\nI''m sur', 'The game has it''s flaws, overall I would give it about 6/10.  There are a couple of annoying things about it.  The train tracks with the numbers need to have some explanation behind it.  Also why are some of them green and some are red?  Again, an explanation or a tutorial would be nice.  The other thing that could be improved is the ability to choose levels.  There are 50 puzzles (or "levels") in the game.  Currently I''m stuck on a really hard puzzle and it would be nice to skip past this one a', 'Very Positive', 94.44, 3.38, 25.42);
INSERT INTO reviews VALUES (43555, 1808130, 192, 'my rod was flying and spin around me longer than i was fishing', 'i loved the game but the ending was a huge let down', 'Very Positive', 94.79, 10.08, 2.18);
INSERT INTO reviews VALUES (43583, 1808680, 1398, 'You can continuously drop Little My in the well while she screams in agony 10/10 would do again', 'This game was really pretty and cute but the story felt really boring and short, I felt like there wasn''t much character development and I wish there was more to the story. Also the game play compared to the price is insane, I could see this being like $10 or at most $15 but $20 is actually insane', 'Overwhelmingly Positive', 96.85, 3.73, 3.75);
INSERT INTO reviews VALUES (43621, 1809540, 13699, 'Stop waiting for Hollow Knight Silksong and play this!', 'I really wanted to like this game. I really did. I tried so hard to like it. There''s so much it does well but god I really just don''t think the combat system works well for bossfights. I found it so... boring. The parry mechanic limits how much movement and dodging is a part of the combat skill. I feel like I spent a lot of time just standing waiting for the boss to do a parryable attack. The options in combat are really limited as well. Every fight felt so formulaic. The bosses do different thi', 'Overwhelmingly Positive', 95.93, 37.95, 29.33);
INSERT INTO reviews VALUES (43626, 1809700, 2705, 'game sometimes black screens my entire PC in tartarus but I get to play as a girl so its okay', 'Don''t play this game. Period. Go play RELOAD, if you want FeMC route so bad, go watch a youtube video. Please, I wasted so much precious time on this, I don''t even wanna make a formal review on this. You would enjoy more on playing Call of Duty warzone than beating this poorly optimized PC ported video game.', 'Mostly Positive', 79.19, 22.38, 634.40);
INSERT INTO reviews VALUES (43668, 1810580, 216, 'Still waiting for  the next story until now.', 'Was fun at first BUT game is abandoned.', 'Very Positive', 82.87, 127.13, 4.65);
INSERT INTO reviews VALUES (43682, 1810820, 170, 'I''m the map. I''m the map. I''m the map. I''m the map. I''m the map. I''m the map. I''m the map. I''m the map. I''M THE MAP!', 'I love the etrian odyssey series to death but there is no universe in which i''ll ever pay forty dollars for this singular game. It''s not that the quality isn''t there, but the games themselves simply don''t have wide enough appeal and the quality of production simply doesn''t match the price. Call me when they give these the persona 5 treatment in terms of polish and i''ll consider forty bucks. Otherwise buy this on a sale. It is genuinely one of the best dungeon blobbers you can get though and a fa', 'Very Positive', 91.18, 8.67, 23.88);
INSERT INTO reviews VALUES (43687, 1810960, 394, 'good, minus the fact that chapter 2 will never come out', 'It''s been a pretty long time since anything has come out even teasing an update. Pretty sure it''s abandoned, which is unfortunate', 'Very Positive', 87.82, 1.37, 1.65);
INSERT INTO reviews VALUES (43690, 1811040, 267, 'South of the Circle is an enjoyable narrative experience for a lovely afternoon of gaming.\r\nIt is so nice to finish a game.', 'Not much of a game. You click 1 button to respond and that’s it. You don’t actually have control of your character. Unless you call walking forward control. \n\nSave yourself 18 bucks and watch it on YouTube for the story.', 'Very Positive', 80.52, 3.48, 1.10);
INSERT INTO reviews VALUES (43695, 1811260, 35710, 'Game is fun but match objectives are the dumbest thing they could have added. Either remove them or give the player an option to turn them off. \r\n\r\n"Oh you had a hat trick? Thats cool but did you have 25 short passes and a 60% cross conversion rate? No? Guess youre riding the bench for the next several matches."', 'I would go to a hotel, sit on the cuck chair, and watch my wife of 47 years get two-man railed by Johnny Sins and Lil Pump while Thick of it by KSI plays on loop for 45 consecutive minutes, instead of play one single UT Champs qualifier match. This game is pay 2 win, pay 2 play, and also costs your sanity. If you want to lose sanity this badly, I''d recommend go play Phasmo.', 'Mixed', 60.71, 13.62, 244.92);
INSERT INTO reviews VALUES (43709, 1811500, 124, 'Ryukishi07\nVisualArts/Key\nProtagonist with Voice Acting\nDual Language\n\nDo I need to say more?', ' Well it is, at the very least, a short decent visual novel and I kind of like it...\nHowever the lack of "Visual" in this visual novel really makes it hard for me to recommend this game.\nMy own imagination and the game''s voice acting, which is superb btw, does most of the heavy lifting in terms of the storytelling. It does get better in the later parts, albeit slightly.\nLove the art style though since I''m familiar with Mochizuki Kei''s artstyle.\nBut like come on, atleast add some portraits for Ku', 'Very Positive', 86.29, 13.92, 7.05);
INSERT INTO reviews VALUES (43718, 1811740, 183, 'Very, very short so I''d say get it cheap or in a bundle. It''s good while it lasts, creating a good atmosphere and has a decent story. The ending is kind of meh and it could have used some extra chapters, but it''s a good bite-sized adventure game.', 'I''m not gonna lie, I didn''t even want to get this game. I only got it because it was part of a sale where if you got this game with The Longing (a really great game) the price would be cheaper than if you just got The Longing. I don''t know what the Steam sale managers were cooking when they made that up but hey, 5 dollars and a free game is 5 dollars and a free game. And even though this game was apparently (according to Steam) so bad it jacked down the price, I really liked it. It had art that ', 'Very Positive', 86.89, 1.88, 2.87);
INSERT INTO reviews VALUES (43727, 1811950, 171, 'If you have made it this far with Trails there really isn''t really anything else to say at this point. It''s great.', 'Yes it''s a great game and a refresh story line for the series, interesting new characters and lovely old faces. Better battle system but lack of variety of enemies / monsters. Story almost perfect unfortunately down by last chapter where the final scenes is kind of anti-climax and obviously feels too familiar liked trails of cold steel (Big bad boss trauma).\n\nAs for the PC port it really should have been better, Cloud leopard should add more quality of life (e.g. better anti-aliasing and 120 FPS', 'Overwhelmingly Positive', 97.66, 78.10, 108.52);
INSERT INTO reviews VALUES (43728, 1811990, 4999, 'wildfrost is very punishing for the first 50 or so hours because the guardrails you''re used to in other deckbuilders aren''t there. you are always 1 mistake away from death since if your leader dies you lose the run, and your leader can get one shot. \r\n\r\nonce you push through the initial learning curve, get used to the enemies and their spawn patterns, and build good habits to cover your mistakes, wildfrost is one of the most enjoyable deckbuilders i''ve ever played. you can think your way out of ', 'There are a lot of really good things about this game, like attaching trinkets to cards and different builds you can make, but the bad parts really cancel out anything good. There''s so much randomness (like you getting past heroes from your last run that don''t fit into your build, but actually hurt it) and events you unlock that make the game harder instead of easier like most roguelikes. Then there''s the fact that if you win with a really good build, you have to fight that build for the final b', 'Very Positive', 91.52, 732.68, 19.87);
INSERT INTO reviews VALUES (43729, 1812070, 156, '                        \n\n\n\n                                                                        ඞ', 'ex made me buy it as a joke now i cant get rid of it', 'Mixed', 60.26, 0.15, 0.63);
INSERT INTO reviews VALUES (43730, 1812090, 591, 'Prisoner: I’m sorry I tried to escape.\nGuard: I’m not mad, just ... disappointed.\n\nRemember, kids, never let your guard down.\n', 'I''m a fan of The Room, House of DaVinci, Myst, and other more "serious" escape games.  \n\nThis one is more like a kids'' cartoon. The graphics are waaaay too cartoony for me. There are also goofy characters that take away from the experience. The music is annoying and breaks my concentration. When I got to the third level and saw a chunky cartoon dude with a yellow jacket introduce me to the level, I had to stop playing.  The timer aspect is also a huge no-no in these games. I''m under enough time ', 'Very Positive', 86.63, 14.62, 1.00);
INSERT INTO reviews VALUES (43743, 1812300, 480, 'Not sure why everyone is so negative about this where the only real issue is that the game is just too short once you''ve got everything done this really isnt anything else to do it kinda just runs stale.   Would be nice for some addons and perhaps adventures but otherwise its a great little game.', 'Every negative review basically explains this game. The logic behind is not there. The idea that the citizens are worried about luxuries rather than survival. The missions on the subs are not interesting. And the over all mission for the Atlas is kinda a snooze. Feels like the devs really were trying to copy Frostpunk but wanted to make look completely like it''s there own idea. Game needs a huge over-hall especially for a story, resource gathering, resource creation, focus more on technology dev', 'Mostly Positive', 71.04, 19.20, 49.65);
INSERT INTO reviews VALUES (43745, 1812370, 1169, 'Takes some time to get going, but its pretty compelling after the first two hours.\n\nI can appreciate the faithfulness to emulate old 90''s anime during some of the cut scenes, even flips to a 4:3 aspect ratio and reminds me a lot of rose of Versailles and rosenmaiden with it''s visuals.\n\nIf the idea of playing through a German fairytale through the lens of a lite social / life sim appeal''s to you, you will love this game.\n\nBUT PLEASE FOR THE LOVE OF GOD ASTRALSHIFT, STOP PUTTING CHASE SEGMENTS IN ', 'The art style is what captivated me to purchase this game because it was just so visually pleasing. I am not even that big a fan of dating sims, let alone horror games but this one held my attention with its unique story, fun mini games and cast of characters. So why do I not recommend this game to other players then if I had such a positive experience with this game? Well, this game has a lot of flashing lights the further you get into this game and I''ve found myself dying a lot and encounterin', 'Overwhelmingly Positive', 95.38, 5.87, 5.47);
INSERT INTO reviews VALUES (43748, 1812410, 123, 'It just works.', 'Whoever decided to make the key to draw your sword the same key to talk to NPCs in a game where if you have your sword out in front of NPCs you get arrested needs to be themselves arrested. \n\nThis might be the worst game I have ever played.\n\nThey tried to force this game out before OOT and it shows', 'Mixed', 64.23, 0.08, 0.28);
INSERT INTO reviews VALUES (43752, 1812450, 5824, 'The game is awesome . What i would really like is a Road Map or an update on the progress, Please vote up!\n\nROAD MAP ROAD MAP ROAD MAP ROAD MAP ROAD MAP ROAD MAP ROAD MAP ROAD MAP ROAD MAP ROAD MAP ROAD MAP ROAD MAP ROAD MAP ROAD MAP ROAD MAP ROAD MAP ROAD MAP ROAD MAP ROAD MAP ROAD MAP ROAD MAP', 'These are the same devs that made and abandoned last oasis\n\nNPC Voices are using a cheap AI voice gen.\n\ncombat is somehow weaker then last oasis combat\n\ni do not trust these people in making a complete game.', 'Very Positive', 80.91, 97.10, 1.95);
INSERT INTO reviews VALUES (43756, 1812620, 2099, 'This program is the best choice if you actively use gamepads on PC. It helped to reveal the functionality of the basic DualSense better than Sony did on its PS5, even in DualSense Edge.', 'I bought this software to use my DualSense Edge with my PC, and the latest update now requires me to buy additional "DLC" that costs 60% of the price of the original software to continue using that feature. Note to the devs-- utility software doesn''t have "DLC." You''re just being greedy and trying to sell me what I already paid for.', 'Mixed', 64.60, 130.97, 77.42);
INSERT INTO reviews VALUES (43766, 1812910, 247, 'Got the game on sale.\nIt was very fun while it lasted, but this is a one and done game.\nAfter one play through, you will have seen enough and know all the tricks such that everything will become tedious the second time around. \nWould have liked options to extend the game longer as opposed to being herded by set game events. \n', 'I can see what they are going for here, but my experience with the game was pretty mediocre, sadly. My gameplay was constantly interrupted by people proposing the same trade deals to me over and over again, and since I cannot promise to trade away my entire food production more than once, I had to to reject them, tanking my relations with all of my neighbours. This got really annoying, since the game slows to a crawl. Similarly, despite an overall good tutorial, it was also really difficult to f', 'Mixed', 63.56, 54.67, 1.27);
INSERT INTO reviews VALUES (43777, 1813130, 144, 'I do love this game, but you run out of content that leaves you wishing there was more to the game. The biggest issue for me is I wish that there wasn''t a limited amount of world tiles, the game abruptly ends because you cant expand your world anymore. This limits how many resources you can get from things like Cows thus making milk recipes useless as i only get a couple milk every single day. The devs need to allow much larger expanding of the world, and buying of specific tiles such as more co', 'The game is cozy and cute; you run a little restaurant but I didn''t enjoy the story line. You can cook, forage, farm, and care for some animals later in the game but it feels like either a beta or early release game, there are a lot of bugs that makes the game frustrating to play and sometimes the goal of the quests was not clear. \n', 'Mixed', 68.75, 20.50, 39.47);
INSERT INTO reviews VALUES (43780, 1813170, 311, 'Honestly, wasn''t as bad as the reviews said. The only issue was an audio bug where if you separate from your group all the audio attempts to catch up and you hear everything that was said when your group was separated. The atmosphere was nice and creepy, the monsters were all unique and scary. My biggest gripe with the game is the map, not being able to see where you are is frustrating running around in circles in the dark fog only to loop back to the same map after being lost for 10 minutes. Th', 'My Grandfather smoked his whole life. I was about 10 years old when my mother said to him, "If you ever want to see your grandchildren graduate, you have to stop immediately". Tears welled up in his eyes when he realized what exactly was at stake. He gave it up immediately. Three years later he died of lung cancer. It was really sad and destroyed me.\n\nMy mother said to me- "Don''t ever smoke. Please don''t put your family through what your Grandfather put us through" I agreed. At 20, I have never ', 'Mixed', 44.05, 2.20, 0.82);
INSERT INTO reviews VALUES (43787, 1813270, 157, 'Gotta bring back more of the og islands shark tooth, superhero, train mystery, diary of a wimpy kid', 'I love Poptropica with my whole heart, but this is ridiculous. Most of the old islands are gone, there is no option for full screen, and it does not keep you logged in. Until these things are taken care of and the old islands are returned, I won''t play it. Not worth $20 at all.', 'Mixed', 68.15, 8.45, 4.62);
INSERT INTO reviews VALUES (43798, 1813430, 1391, 'I''m tired of pretending that I don''t like furries. They''re hot as f*** and this game is a masterpiece.\nI wish there were more games like this. It''s an untapped gold mine.', 'no gay sex', 'Very Positive', 93.89, 1.75, 0.13);
INSERT INTO reviews VALUES (43816, 1813860, 124, 'Easily one of the best games of recent years and destined to be a new classic of the indie scene. It''s an unforgettable experience full of little nuances to discover in every game session. It''s amazing that it''s all done by one person. 10/10', 'Look, this game is absolutely beautiful. The music is relaxing, the vibe is chill, and the visuals are straight out of your favorite childhood storybook.\n\nBut given the fact my playtime is at 90 minutes and I feel like I''ve been playing for 4 hours and that I''m only apparently 1/4 of the way through the game, I cannot in good conscience recommend this at full price. It is absolutely a chore to play and with every successive episode, the chore list gets longer and longer. I wish I actually liked ', 'Overwhelmingly Positive', 96.77, 1.13, 0.97);
INSERT INTO reviews VALUES (43821, 1814010, 692, 'Downloaded this because it seemed interesting, and I don''t mind an idle game. However, it quickly became one of the best games I have ever played. The sheer idea of this game is phenomenal! I''ve always loved the concept of time loop movies, and this game embodies that idea perfectly.\n\nI found myself just staring at my loops as I tried to optimize and explore new areas. If I could say one thing to the developers, it would be: please, please, please make another game with the same concept!\n\n5 star', 'Look how they massacred my boy (Loop Hero).', 'Very Positive', 84.83, 273.00, 0.22);
INSERT INTO reviews VALUES (43831, 1814170, 549, 'Lingo has quickly moved into the conversation for the best puzzle game I''ve every played. It''s got the imaginative puzzles and charm of games like Baba is You and the Witness, head-scratching challenges, breath-taking solutions, and deep unprecedented secrets hidden at every corner. It''s everything you want from a puzzle game and there''s enough content in it for you to sink your teeth into for hours, if not days. \n\nDo not overlook this absolute hidden gem of a game. (bring your own music though,', 'i like this game but i cant recommend it because whilst the puzzles are fun the map itself is awful to navigate and you''d often spend more time trying to get to the next puzzle than actually doing it. there are a few resources in the discord to help with map navigation but if i have to use an outside website to help me play the game, there is something wrong.', 'Very Positive', 94.72, 67.87, 32.20);
INSERT INTO reviews VALUES (43863, 1814770, 100, 'As a Tall Poppy Speedrunner I recommend!', 'what the mid', 'Very Positive', 90.00, 2.17, 0.22);
INSERT INTO reviews VALUES (43889, 1815230, 210, 'This runs well on the steam deck and i recommend changing steam input to use d pad as joystick and set right trackpad to be a single button bound to dpad down.\n\nThis roguelite feels like an improved and fleshed out rogue legacy. it isnt very enjoyable at first but as you get stronger it becomes more fun in an almost exponential way. good stuff.\n', 'Meh. For the first 6 hours or so you''re intrigued by the high difficulty and interesting worlds. I also found the dialogue clever. There is nothing glaringly wrong with how your character controls and combat can be fun.\n\nProblem is it''s pretty repetitive -- not enough variation in worlds or enemies. Biggest problem is that there are way too many types of currency and the meaningful upgrades (ie, a new weapon) cost way too much. You end up grinding way too much, experiencing the same content over', 'Very Positive', 90.95, 40.38, 12.68);
INSERT INTO reviews VALUES (43902, 1815530, 205, 'Amazing new take on the dungeon defenders series. The original and 2 were amazing and I didn''t think it was possible to get any better than that. But then after Awakened which was just a worse repeat of the original came Going Rogue. I highly recommend this game it is incredible!!!', 'No updates in almost 2 years, no news of any kind, yet suddenly no longer early access?', 'Mostly Negative', 39.51, 8.55, 6.62);
INSERT INTO reviews VALUES (43905, 1815570, 531, 'When I first tried this game, I bounced off of it hard. I came back to it after a month or two and had a much more enjoyable time. The key difference is that the first time around I was expecting an RPG that incorporated poker into the rules; what you get is an RPG that incorporates a poker *deck* and poker *terms* but has little to do with the game poker itself. In particular, the asymmetry between defensive and offensive hands will really mess with you if you''re coming at it from a poker persp', 'Love the concept, art, story, voice acting and animations. The only thing that bothers me, which is a deal breaker for me, is the fact that despite the game advertises as poker hands with ability cards, it forces you to play the same amount of cards as a defense as the AI used to attack you with. What that means is that you can never beat a single card with anything other than a high card. Not with a pair, 3 of a kind, 4 of a kind, or any straight or flush, even if you have those in your hands.', 'Very Positive', 89.64, 153.72, 3.15);
INSERT INTO reviews VALUES (43932, 1816300, 1253, 'It''s okay, but it feels like the game had a "farming team" and an "adventuring team," and they barely talked. While adventuring gets you mats for crafting, farming is really just a way to make money and temporary buffs...and even then, adventuring for minerals nets you more money. It feels like an adventure game with a farming sim tacked on. If you''re looking for a farming sim, try any of the Rune Factory titles, Sakuna, or even No Place Like Home.\n\n6/10', 'I thought long and hard about if I would or would not recommend the game and finally leaned towards No. I think I would sum Harvestella up as being a solid Okay/10: all the different aspects of the game are shallow, so you can get tired of it quickly. I got it on sale and it''s been keeping me busy, but there''s nothing to write home about here. There are no crop levels, fishing levels, and the combat skilltrees don''t feel particularly meaningful. There''s no real way to mitigate damage, so you''re ', 'Mostly Positive', 77.81, 58.38, 21.80);
INSERT INTO reviews VALUES (43958, 1817000, 566, 'Zodiacats is a puzzle with the function of assembling the different signs of the zodiac in the shape of cats with a single cosmic and relaxing song when assembling each one. For lovers of cats and astrology, it''s a cute, cozy and meditative way to pass the time.', 'Hard mode is broken, thus it disables receiving the final achievement. Simple bug but no fix.', 'Overwhelmingly Positive', 98.06, 5.72, 2.50);
INSERT INTO reviews VALUES (43962, 1817070, 46547, 'I''m rarely a fan of Marvel''s movies, shows, or video games, but Spider-Man Remastered is a rare exception—entirely on the strength of its gameplay. The experience was undeniably exhilarating, with mechanics reminiscent of the Batman Arkham series but refined and expanded to an even greater degree, making it compelling enough to see through to the end. Unfortunately, the narrative fell short, its mediocrity exacerbated by an excess of teenage dialogue that I found particularly irritating. That sa', 'sneak missions  are actual psychological torture. great game tho.\n\nedit: even more sneak missions. painful.\n\nedit: holy fucking fuck, what the fuck is wrong with you insomniac? do you hate the people that buy your game so fucking much that you force us to do these intolerable sneak missions? i''d rather pull my own teeth out. what the fuck is wrong with you psychopaths', 'Overwhelmingly Positive', 96.58, 19.33, 26.98);
INSERT INTO reviews VALUES (43968, 1817230, 15443, 'This game made me realise how depressed I was, it ignited a spark in me and I seriously can''t recommend this game enough it''s almost perfect and worth every penny I spent from the characters to combat to ost its all just top notch this has become one of my favourite games of all time and I look forward to continue playing it\n9.5/10\nFuck microsoft for shutting down the studio', 'F🖕C K Microsoft!\nR.I.P. Tango Gameworks, thanks for the great game.', 'Overwhelmingly Positive', 97.84, 14.13, 28.17);
INSERT INTO reviews VALUES (43988, 1817800, 794, 'This game feels like Picmin and factorio had a cute little wood shaped kid and gave it alot of personality', 'Sadly woke soup. A while into the game I was bombarded with things like nonbinary/trans/etc. flag pattern things (like clothing, and they''re literally outright named that). I''m not interested in your politics, dev.', 'Very Positive', 86.15, 37.33, 12.20);
INSERT INTO reviews VALUES (44002, 1818180, 118, 'works and looks great, even in potato mode.', 'i thought it was a game maker.\nits not.', 'Overwhelmingly Positive', 95.76, 202.68, 0.15);
INSERT INTO reviews VALUES (44029, 1818750, 5319, 'It''s a damn shame what happened with this game.  The move to completely redo the game after the beta ended was probably one of the biggest mistakes they made.  Even at the end of this game''s life, when the game is in the best state it''s ever been after its full release, I still think the game was at its absolute best during the beta.  \r\n\r\nI could go on about the individual things I liked and didn''t like, but that doesn''t really matter since the game''s only got a few months left.  I finished up t', 'In the future, after this game is completely dead, people are going to pretend that it was garbage. But when this came out, and it was new and fresh, every person i knew was hopping on this. An engaging, interesting fighter that was fun, easy to pick up, and a really cool roster that was supposed to get even better as time went on. I was having fun with this game a lot, my buddies were, it was cool. and then it went offline. Why? WB claimed it was to make it better. it did no such thing. in fact', 'Mostly Positive', 71.20, 340.18, 103.03);
INSERT INTO reviews VALUES (44052, 1819230, 191, 'Eeeh? Easy mode?\nHow lame ! Only kids play in easy mode !!', 'nah udonge in interspecies cave is better highkey', 'Very Positive', 90.58, 7.30, 0.70);
INSERT INTO reviews VALUES (44062, 1819460, 286, 'Mika and the Witch''s Mountain is a wonderfully charming game.  I bought it on a whim for my 5 year old daughter and we just finished it tonight.  Now she''s flying around the island introducing Edgar the bird to all of the friends she met along the way.  She spent hours flying around the island exploring while I did the reading (including my best impression of a Scotsman for O''Vel) and helped with some of the more fragile deliveries.  \n\nWe played it on my Steam Deck hooked up to the TV and never ', 'The story/characters/writing aren''t particularly interesting or memorable. The need to backtrack is abundant and can get quite tedious. There''s little to unlock besides cosmetics, and the few gameplay-impacting upgrades you do get are underwhelming.\n\nAll of this would be forgivable if just flying around was fun, but this core mechanic is where the game missed the mark the most for me. Flying feels slow and clunky, and the nearly non-existent vertical mobility makes the experience more akin to dr', 'Very Positive', 85.66, 19.30, 2.68);
INSERT INTO reviews VALUES (44163, 1821680, 171, 'For 8 bucks, this is a great little hidden gem with a low player count and a smooth little MMO system. Fun in a bun.', 'Game has a very fun early experience and feels very relaxing to play for the first few hours. Then the mid/late game comes and takes all of the fun away. Grinding is one of the worst things in the game and you need lots of it, like 80% of your hours played will be killing the same enemy camp over and over to increase level because level requirements are insanely high. Gear takes even more time to get as in order to craft it you need to invest even more hours. Could easily take a player a 100 hou', 'Mixed', 67.25, 8.78, 48.13);
INSERT INTO reviews VALUES (44184, 1822060, 447, 'This is a sublime gem of a turn-based squad game from a solo developer who ought to be supported - nay, nourished and cherished - by all fans of turn-based squad games. The game has a gripping plot, and the turn-based combat - the core of all games of this stripe - is intuitive and yet complex. As an inveterate min-maxing, power-gaming freak, I found myself re-starting the entire game three times already to try out different characters and class combinations. And boy, is there an endless variety', 'Initially I quite enjoyed the gameplay and its story. This game has much potential, however, what holds it back is the various bugs and/or errors that lead to the game crashing upon loading a save or even upon startup. As of right now, the game is unfortunately unplayable.', 'Very Positive', 91.28, 113.15, 62.13);
INSERT INTO reviews VALUES (44197, 1822450, 274, 'If you like games like The Long Drive and My Summer Car then this is the game for you. It has a lot of the aspects of both games but including a lot of the assets from The long drive but minus the annoying stuff. Unlike The Long Drive, this game has missions and stores you can go to to buy food, water and resources. Unlike My Summer Car, you can''t die from stress and it''s not anywhere near as complicated to maintain your vehicle. Aside from that, it''s similar to both of those games because you s', 'Cool idea, I guess, if it was actually playable. The game essentially has no optimisation to speak of, none whatsoever. I have well above the system requirements listed on the store page and even if I turn down all the settings and decimate the draw distance, I still cannot play with freezing, lagging and terrible frame rate.\n\nI really hate throwing around the term ''eruojank'' for games like these but the amount of effort that clearly hasn''t gone into making the game playable is embarrassing. \n\nM', 'Very Positive', 85.40, 42.62, 0.48);
INSERT INTO reviews VALUES (44205, 1822550, 728, 'i just wanna say, this game does HUD clarity really well. thank you, devs, for not overwhelming me with 8 different tabs, and 10 subtabs each.', 'It''s not impossible to lose, you can lose a lot of time (and potentially a save file) getting soft-locked by sudden difficulty spikes. What the game''s description doesn''t tell you is that you still need to make linear progress; you can''t end a run early like in other idle clicker games, and the goal is to ascend after beating specific crises tied to the last era you unlocked. Since the game grades your runs and awards you upgrade points based on your various scores, you can easily accumulate eno', 'Very Positive', 82.42, 49.92, 8.63);
INSERT INTO reviews VALUES (44213, 1822710, 135, 'Best Game', 'It''s fun and the game is organized well.\nHowever, I don''t feel like playing this game again. There''s nothing to unlock, nothing to upgrade.\nIf I die, I just die, but I don''t want to try again.\n\nPlease put something to upgrade. plz', 'Very Positive', 92.59, 6.92, 5.75);
INSERT INTO reviews VALUES (44219, 1822910, 910, 'CAP-Y-BARAAAAAAA~ CAPYBARA CAPYBARA CAPYBARA CAPYBARA~ CAP-Y-BARA!!! KAKIBARA KAKIBARA KAKIBARA KAKIBARA.', 'I adore capybaras as an animal, but this game is just tedious. The gameplay is lackluster, and there is no real customization options except for where you place stuff. After expanding my spa, I dont really feel any ownership to it. The gameplay consists of dragging capybaras into bathtubs, dragging fruit, soap or towels to the bathing capybaras, and then dragging the capybaras back out.\n\nThe gameplay is just dragging stuff around your screen, and it gets boring after two minutes. Save up money a', 'Overwhelmingly Positive', 95.82, 20.33, 5.43);
INSERT INTO reviews VALUES (44241, 1823380, 279, 'It has nice content , \nbut the freeroam is very tedious, and you can only skip time in MC''s room', 'SuperButtHurtAlex won''t update this game on Steam because of negative reviews that he brought on himself?  What a narcissistic loser.  To the customer supporting his Patreon: You are regarded....', 'Mixed', 52.33, 0.08, 50.23);
INSERT INTO reviews VALUES (44242, 1823390, 105, 'Use a scroll of identification to identify a scroll of identification', 'It''s 2025 and another clueless dev team releases a game without gamepad support. Unplayable on ROG Ally, uninstalled and refunded, thanks for wasting my time. Next time spend less on advertisement and more on basic features...', 'Overwhelmingly Positive', 95.24, 1.00, 0.95);
INSERT INTO reviews VALUES (44249, 1823600, 220, 'It’s a solid geo-political sim overall, super fun to jump into wars, but tbh, that’s not the main vibe. For me, the real deal is managing the economy and teaming up with other countries!', 'I dearly hope that someone eventually makes a good, modern geopolitical sim, someday.\n\nThis is not that game, nor are any of the (insert year here) versions of it. The interface is genuinely one of the worst possible, the combat is dull, the array of mechanics seems broad, but is really shallow, badly implemented and really, really awkward to use. Then there''s the business practice of re-releasing what is essentially the same game with minor tweaks multiple times.', 'Mixed', 53.64, 48.55, 8.18);
INSERT INTO reviews VALUES (44267, 1823930, 549, 'Wavetale\nSigrid is a young girl raised by her grandmother on a small, quiet island with a lighthouse. Forbidden from going near the water, her life is simple, boring, and peaceful until one normal day a terrifying dark fog surges in like a tidal wave and monsters invade from the ocean. The lighthouse flickers and dies, and the dark fog seems like it would swallow Sigrid whole until something strange happens; There is a solid shadow in the water, a true reflection mirroring every step she takes u', 'I felt that the game was too linear and basically equated to a railroaded walking simulator with a surfboard. The platforming is fun and the movement will give the player a thrill until they realize there''s nowhere to go and momentum doesn''t build. The speed threshold is really low so you can''t push through an area in a satisfying chain of movement and jumps. The next obstacle or slide often is spaced just out of reach so you always have to break your momentum. Not a great choice.', 'Very Positive', 87.61, 8.87, 3.35);
INSERT INTO reviews VALUES (44269, 1823950, 449, 'this game introduces you to its mechanics very well. you manage space and supply chains while feasting on the visuals. moving buildings is free and i think that''s good and part of the cycle as more buildings, resources, and more challenges are introduced over the course of a scenario. i also like how resources do not have travel time but longer distances induce higher pop costs. i''m on the second scenario and the only thing that has annoyed me is that the warehouses, which carry resources over d', 'Oh I was so excited to play this game and I''ve been left disappointed. :( Visually it really is stunning, but it''s just not a city builder. You get a set of maps that are all pretty similar, with the same specific rules on what buildings can go where, and after playing for 2 hours it''s just... bland. I kind of feel like if the devs took the city builder tag off the game it''d be better, and people like me wouldn''t have made the mistake of expecting it to be something it''s not. \n\nThat being said, ', 'Very Positive', 82.18, 22.08, 2.02);
INSERT INTO reviews VALUES (44285, 1824220, 18749, 'this game is very fun it did have its final update a few months ago tho\r\ntorn banner perma banned a youtuber by the name of soter dave he was very dedicated to helping the devs\r\nfix problems mainly the cheater problem witch the devs ignored, soter dave uploaded a april fools video on pretty much how easy it is to cheat soter dave was perma banned because of that and because soter dave sadly took his own life on april 15 2024, a good video explaining what happened is made by liniyka titled abusiv', 'The game is very fun, extremely fun. Rarely does one find gems like this one in today''s boring, generic, and forgettable world of FPS/PvP games. Challenging combat but feels very rewarding and fun as you start understanding the mechanics. \r\n\r\nHowever, the developers might be some of the most pathetic, shameless, and downright evil people. Even for today''s standards of developers. From mediocre balancing, to non-existant updates and extra content, overpriced DLC cosmetics, to not listening to the', 'Very Positive', 81.52, 84.53, 11.97);
INSERT INTO reviews VALUES (44301, 1824580, 291, 'Ignore reviews that say "you can''t do much on one turn", "You can''t move around much", "Wasting a turn is often optimal" or similar. They DID NOT play the game for long or figure out the mechanics, you complete several floors in a row in one turn, kill bosses in one turn, draw your whole deck, etc. Or even just get a bit more AP to play more cards, use cards to move around the field, etc. This game has progression, you know, a staple of videogames, so it''s only natural you''ll start a little weak', 'town is the worst thing. you get lost and overwhelmed and little guidance', 'Very Positive', 80.41, 97.45, 1.55);
INSERT INTO reviews VALUES (44312, 1824960, 317, '100% worth. Exactly what you would want in a zombie game. Loved everything! Only downside is the length. I wanted more! Propagation was amazing. Paradise Hotel was amazing. Can''t wait to see what they come up with next! Great job!', 'The game is really good but the ending sucks.\nIt''s so abrupt that i was just standing there being like "Are they for real?"\nI would''ve given this game a good review but with this terrible ending it''s a no for me...', 'Very Positive', 86.75, 8.47, 3.85);
INSERT INTO reviews VALUES (44387, 1826570, 148, 'Nice 1-st person escape room puzzle in style of The Room and House of Da Vinci series. Interesting puzzles, not too hard, but not too weak either. There was a couple of times when I was close to turning to a guide, but in the end I managed to complete the game on my own with all achievements unlocked. So I''d say that the balance is very good here, and in the end the solutions were elegant and logical, you just need to be patient and don''t miss the fact that some books that you read can several p', 'As the previous one, I found this one quite tedious. At least it got a few improves in comparison to the first game. I could find myself enjoying some puzzles when it didn''t rely on reading a lot of notes and books. Don''t take me wrong, I love reading, but some notes and books are full of information that I believe I never used, just filling my mind with unnecessary information \r\n\r\nPS: looking for the collectibles were quite fun and the new mechanism to let us know how many in each area is perfe', 'Very Positive', 80.41, 8.93, 3.55);
INSERT INTO reviews VALUES (44399, 1826860, 129, 'rat', 'This game is definitely interesting. So far it doesn''t seem like there is any storyline or real plot and that it is only a maze game where you continue to explore, talking to rats, experiencing the different music, and playing weird little mini games(?) while you look for cheese and fruit (I have not found a purpose for the fruit, but I think cheese takes you back to the beginning as a restart). I think it''s enjoyable if you want to play a game where you pretty much aimlessly run around with no ', 'Overwhelmingly Positive', 98.45, 0.52, 0.28);
INSERT INTO reviews VALUES (44477, 1828650, 108, 'if you, like me, are the sort of person who gets a rush of dopamine at the mere thought of the phrases "RPG", "dark fantasy" and "otome" being used in the same sentence, you should play this game', '', 'Overwhelmingly Positive', 100.00, 6.78, 0.00);
INSERT INTO reviews VALUES (44479, 1828690, 191, 'Genuinely a really fun and eerie horror game with an intriguing story. I didn''t expect such a cheap game to be so interesting and enjoyable to play, highly recommend!', 'Warning: Framerate capped to the unplayable value of 60.\n\n', 'Very Positive', 92.15, 2.20, 0.10);
INSERT INTO reviews VALUES (44516, 1829470, 177, 'Okay I deleted my old review since I tried the game out on keyboard and it works much better, let me put it this way;\nDo not play this game on gamepad\nfor some reason the hit detection is MUCH harsher on gamepad, if not outright impossible, I don''t know if this is a bug at the time of writing this but when i tried playing on gamepad, I would see the "fail" lines right in the circles/squares, which would clearly denote that I''d have hit the note right? wrong. I would fail constantly and then, for', 'I loved the first Melody Escape, it was a simple but did a great job at what it was. I was excited when I found out it had a sequel, but didn''t live up to my expectations. To be fair, the game is in early access and has a lot of potential. Below is a list of the things I like and don''t like. \n\nLike:\n- I do enjoy the visuals, mostly, however I do agree with other reviews that say that placement of the blocks causes you to put most of your attention to the road. Colors are bight and vibrant and th', 'Overwhelmingly Positive', 96.61, 0.72, 20.87);
INSERT INTO reviews VALUES (44539, 1829980, 315, 'Yuzusoft never disappoints. Plot is great with several funny dialogues. H scenes may not be animated (as usual), but the voice acting more than makes up for it.\n\nOne thing that really stood out is Natsume''s voice (by Kanako). I''ve never heard a voice as angelic as hers in the many VNs I''ve already played. I found myself playing back many of her lines more than a few times.\n\n@Yuzusoft, please give Kanako more roles in the future.', 'Maybe it''s a Japanese thing, but personally I don''t find it funny when a protagonist is unceasingly being shamed for "being a creep" in situations where he is actually trying to have serious discussion and be helpful and considerate. Makes me furious when I imagine myself in that situation. The story seems to start as interesting, but it''s not fun to actually experience it.', 'Overwhelmingly Positive', 95.87, 60.85, 5.40);
INSERT INTO reviews VALUES (44566, 1830620, 116, 'i got this, and try to start the game.\nbut the game just stops responding right away.\n', 'For the Fap Rating: ⭐☆☆☆☆\nBottom Line Up Front: Interesting concept but too much work for the fap.', 'Mostly Positive', 75.86, 6.87, 0.43);
INSERT INTO reviews VALUES (44570, 1830720, 223, 'You haven''t experienced true horror until you''ve tried to pick apples while colourblind.', 'I figured out quickly what was really going on.  I''d categorize the game as "creepy, weird?".  I really didn''t care for it much.  For the true ending expect to put in 4 to 6 hours?   There is a robust ending and it''s worth it to check it out but I just don''t have the time nor the patience for it so I just caught up on YouTube.', 'Very Positive', 92.38, 3.57, 1.47);
INSERT INTO reviews VALUES (44583, 1830970, 1093, 'Game was good.\r\n\r\nNot every game needs to be the next lifestyle game. Many roguelites can feel like that. I suspect that many players may play this game hoping for that. This wasn''t. And I think it was better for it. I gave it my 50 hours, saw all that the game has to offer, and I was happy with it. I''m "done" with it, and I''m glad I can say that.', 'The developers are trying really hard to make this game have a unique point of view, but the game design prevents interesting plays like pivoting to new heroes and changing builds. Basically I feel that whatever i pick at the beginning is going to be my build and I force it. Even forcing a particular build, I usually win on the hardest difficulty. I would like to see a change to the character leveling system (making it "team levels" to promote swapping of characters to fit certain battles). That', 'Very Positive', 91.86, 39.92, 11.42);
INSERT INTO reviews VALUES (44641, 1832040, 438, 'the gameplay loop is just good fun. the combat and movement keeps things interesting. imo they shouldnt have market as a souls-like (or "souls-lite"). sure theres souls elements which is all too common in current year, but its just more like GoW in basically every way and thats a good thing. i just finished Shadow of the Erdtree, dying over and over is the last thing i want. Thankfully, thats not what this game is. Its a solid linear action game thats a blast to play. Story and characters are fi', 'Not worth it at full price. Game is "OK", but not good. Combat is loose and never feels precise. Traversal is equally loose feeling like you''re never sure if you''re going to miss your jumps. Story is uninteresting, but who plays for that anyway. Voice acting is ok, but the audio is produced poorly, so your characters voice is loud while many NPC voices are super quiet. Performance is ok on my system, but overall the game is kinda bland and boring. Mostly trash enemies with unpolished combat. Its', 'Mostly Positive', 76.71, 25.17, 14.57);
INSERT INTO reviews VALUES (44642, 1832050, 109, 'Aesthetics, ui, pacing, all right there with ya. Continually entices you into thinking just a little bit harder about what you''re seeing, continually rewards you for finding new ways to think about it.\r\n\r\n"A hidden gem" applies here, so very well.', 'Cute little game if it wasn''t so buggy.\r\n\r\nIt''s cheap and an easy way to support a smaller creator (who was also in some stressful legal trouble through no fault of their own) which makes it an easy decision to buy.\r\n\r\nUnfortunately, half the time either the HUD doesn''t show up (so you don''t know which components come up or when, and can''t use the exchange button to swap components), and other times the neighbourhoods don''t spawn. I had to start the tutorial three times before I got to play it a', 'Very Positive', 94.50, 7.67, 10.03);
INSERT INTO reviews VALUES (44667, 1832640, 2453, 'To be honest, many people have their aims on this game but as I haven''t played mirror 1 before, I did''t care about any 18+ content. The scenario is good on some characters so I would still consider this game as a fine one.', 'Imagine going bankrupt because you didn''t add porn to the game.', 'Mixed', 47.29, 5.23, 0.98);
INSERT INTO reviews VALUES (44698, 1833490, 269, 'Higaeri4000, we are with you! I heard your story in the web. I wish you the utmost patience and fortitude in this difficult time. I bought the game to support you. A review will be written as soon as I play the game. From Russia with love!', '“Goodbye World” is a game that leaves many players underwhelmed despite its intriguing premise about the struggles of indie game development.\nWhile it has attractive pixel art and an emotional story, its execution falters. Critics and players alike often criticize the gameplay for being shallow and tedious, particularly the repetitive “Blocks” minigame, which disrupts the pacing of the narrative rather than complementing it.\n\nThe game’s attempt to explore serious themes like creative burnout and', 'Very Positive', 91.82, 1.03, 0.23);
INSERT INTO reviews VALUES (44763, 1834820, 109, 'this game slays... literally. it has everything you could want; a dominant girlboss, a himbo w fat t!ts, and a real kinky enby.', 'having to somehow repeatedly, on the spot, prove you deserve to live', 'Very Positive', 86.24, 2.60, 1.60);
INSERT INTO reviews VALUES (44765, 1834920, 445, 'i love balls thats it really', 'Why does the AI heal even with full health?? Lost so many battles because 80% of my troops dont attack', 'Overwhelmingly Positive', 97.30, 54.63, 15.53);
INSERT INTO reviews VALUES (44785, 1835240, 1169, '', 'I want to be clear, this is not a bad game, and you will probably enjoy it! Its does everything it does very competently, and there are some interesting variants. But the problem is, this game exists in a crowded market. Despite being true 2d, it still competes with Hades and Sworn at the moment. Not to mention Astral Ascent which is essentially the same game, but with far more content and variations. If this game existed a few years ago, it would be amazing. But the action roguelite genre is so', 'Overwhelmingly Positive', 96.15, 0.00, 3.92);
INSERT INTO reviews VALUES (44811, 1835810, 230, 'Short and cute Yuri love horror story.\r\nLiked the story, art and music was soothing ♥ \r\nBackground art style was little mood killer since it looked really ai generated and bland\r\nbut other ways this visual novel was great and cute.', 'I really should''ve read reviews before buying. While I agree with others that the visual part is quite pretty, the "novel" part is simply dissapointing. The plot is indeed shallow deep, full of holes and characters written without much thought put into them. The story relies on common tropes and cheap tricks(e.g. jumpscares and other shock elements) to keep you engaged, but the effect it has is completely opposite, leaving you unsatisfied and bored. "Horror" and romance are almost nonexistent an', 'Overwhelmingly Positive', 95.22, 2.75, 1.47);
INSERT INTO reviews VALUES (44822, 1836120, 257, 'Intensely thrilling arcade shooter featuring incredibly rewarding mechanics. Every time you take down an enemy or get hit, the impact is truly palpable. Simple to grasp, yet challenging to perfect.', 'ᅠ', 'Very Positive', 91.05, 13.62, 5.13);
INSERT INTO reviews VALUES (44824, 1836160, 107, 'Communism Simulator\n\nYou work day and night in the freezing streets while the bourgeoisie are in the comfort of their homes, your salary is terrible, you have no freedom at all, everything around you is very the same and similar. And the main objective of the game is the difficult task of saving money to escape the country.\n\n', 'It''s just like my life in Quebec, Canada, in winter. And I hate my life.', 'Mostly Positive', 79.44, 2.52, 0.63);
INSERT INTO reviews VALUES (44856, 1836730, 4611, 'I want shorter games with worse graphics made by people who are paid more to work less and I''m not kidding.', 'overpriced for what it is.\r\n', 'Overwhelmingly Positive', 97.77, 10.10, 18.00);
INSERT INTO reviews VALUES (44862, 1836860, 311, 'Honestly a really solid hack n slash, I wish less of the reviews were only posted to complain about the lack of fanservice. NxS is rated T by the ESRB and lacks the partial nudity tag mainline M-rated Senran has, so it''s to be expected (and would''ve been shown in the gameplay trailer if present)\n\nBut anyways, I really like the game so far, even if the story is comedically weak. The combat takes a bit to get used to since there''s plenty of anim locks, but as long as you remember to take advantage', 'As others have said, this is not a Senran Kagura game. \n\nI still kinda like it, the graphics are nice, you can uncap your fps so it feels really smooth. The combat is genuinely pretty nice feeling. But for my fellow men of culture, this ain''t no SK. Don''t expect booba or booty, you will feel blue balled as I have. \n\nGonna go play Shinovi versus now. I miss my fanservice man.', 'Mostly Positive', 77.17, 11.30, 3.55);
INSERT INTO reviews VALUES (44881, 1837220, 357, 'Short game, very good jumpscares, good audio design. I''d give it a 10/10.', '99% boring, very slow walking sim.\r\n\r\n', 'Very Positive', 87.11, 0.55, 0.77);
INSERT INTO reviews VALUES (44884, 1837330, 295, 'I love this game. I love being a gibbon. this is so wonderful. It''s so beautiful. I love the story of the gibbons. I love to swing in the tree as a gibbon. It''s so so so beautiful. I love the forest and animals and the magnificent gibbons I love gibbons. Its so fun to be a gibbon and swing in trees and different places as a gibbon. I felt so much emotion in this game . I felt so gibbon. Very beautiful gibbon game 10/10 would recommend plus it gives you gibbon fun facts which is even better. This', 'Seems beautiful, but the gameplay was way too hard for me. Couldn''t even get past the tutorial.', 'Very Positive', 91.86, 36.43, 0.23);
INSERT INTO reviews VALUES (44889, 1837480, 438, 'A criminally insane Indonesian man put this heart and soul into this between his 14 hour factory shifts and by God you''re going to enjoy it', 'I''m leaving a negative review but not because this game is bad. Just super janky. The amount of content in this game is incredible, its just held back by the fact that it only works half the time. In my hour of playing, I kept going "wow! I can do this!?" Only for that thing to just not work as intended later.\n\nMaybe after some more time is put into it, I will buy it again and give it another go. There is something special here and I would hate to see it die.', 'Very Positive', 84.25, 1.57, 7.68);
INSERT INTO reviews VALUES (44900, 1837650, 164, 'Super cute game! Very fun and easy to play! The chicken and other animals are so cute! ❤️🐥🐔🐓🐸🦉🐿️🐦‍⬛❤️ 10/10!', 'Once you pick up the third weight in the temple, stop, consider the game completed, uninstall, and never play again. The ensuing level with numerous jumps that require pixel-perfect precision less you go all the way back to your last save is frustration and annoyance personified, and lets down what had been, until then, a fine game.', 'Overwhelmingly Positive', 97.56, 9.28, 2.67);
INSERT INTO reviews VALUES (44958, 1838970, 193, 'Anybody else just buying all the flash games on Steam now? Feels good to actually give the dev money for the games I enjoyed so much for free growing up.', 'If your looking for the old sandbox mode where you could build levels its not here', 'Very Positive', 86.01, 9.42, 3.98);
INSERT INTO reviews VALUES (44979, 1839430, 385, 'Deserves so much more recognition for doing a combo of armored core, dark souls, and nier....really loving it so far', 'Really enjoying the theme but this game needs LOTS of polish\n-crashes often\n-audio is irregular\n-combat feels clunky and kinda slow \n\nFor now it''s a No for me BUT gonna hope the devs improve the game in time\n', 'Very Positive', 88.57, 3.05, 6.65);
INSERT INTO reviews VALUES (44996, 1839810, 179, 'Disco Elysium meets Hylics in a card battling format', 'Great game! Love the vibes.\n\nDidn''t realise till 16hr that it makes use of AI generated art.\n\nAI has no place in art.', 'Very Positive', 91.06, 11.12, 16.75);
INSERT INTO reviews VALUES (44997, 1839820, 161, 'Good game and great devs. I asked them to add fishing as a joke and they replied as: \r\n\r\n"''ll secretly add fishing-related mechanics and things, lay clues in the the lore that the ultimate goal is to get a fish, allude about it in the environment,  without actually implement the fishing system, like some other game."\r\n\r\nAbsolute best', 'Gameplay is nice and fast but I really dislike the fatigue system, This mechanic should be removed and it would be agreat game. The reseach tech tree is a bit boring and lacking fun nodes that ramps up your play style.', 'Very Positive', 84.47, 9.13, 1.58);
INSERT INTO reviews VALUES (45002, 1839880, 1062, 'Married a fish, pissed off church, they sent the Inquisition, declared my fish husband heresy, got burnt at stake\r\n\r\n10/10 will sleep with Glub again.', 'this game ruined all my friendships made me homeless and killed my parents', 'Very Positive', 91.71, 26.80, 10.80);
INSERT INTO reviews VALUES (45005, 1839940, 502, 'I love this game, but First and foremost, this game is broken. It ranges from slightly broken to very broken, depending on what you''re trying to do, but it can be worked around.\r\n\r\nIf you can work around the bugs, it is so totally worth it, because there is no other game that can offer the experience that this game has. I think to fully enjoy this game, you have to be a bit of a nerd for obscure motorsports, buty even the arcade modes are a blast. You have to play through a lot of the more arcad', 'Game is awesome until it crashes. It crashes a lot.', 'Mixed', 52.99, 180.80, 3.23);
INSERT INTO reviews VALUES (45006, 1839950, 1488, 'Outstanding game, but needs an infinite campaign where you take the army you have from the main campaign and simple roam around Texas hitting Legion bases, attacking and defending strategic locations, helping Movement and Founders which then join the Resistance because you struggle the whole time trying to get veterans and top grade gear to then have it end.\n\nSo yeah great game, just wish there was more to the "fight back"', 'Pathfinding is really bad. I really wanted to enjoy the campaign but it was way too hard way too unforgiving in not a fun way. Lots of save scumming required even on normal difficulty. I''m no stranger to rts been playing them for almost 20 years and this one is so close to being a good one. Too bad', 'Very Positive', 80.44, 102.37, 18.27);
INSERT INTO reviews VALUES (45011, 1840080, 2975, 'Campaign is D to C tier.\nThe game play concept of its StarCraft 2 but in 3 denominational space is amazing. \nwould recommend but not for $60... $30 would be more reasonable', 'We just got told that the game will no longer be supported.  I spent almost $100 on the collectors edition and the season pass was included.   The game is enjoyable in my opinion and if you turn off parts of your brain and appreciate the many impressive visual qualities it can be good.  While I said I didn''t recommend this game, if you get it on discount I recommend it.  I don''t recommend it at full price.', 'Mixed', 41.71, 35.85, 16.62);
INSERT INTO reviews VALUES (45030, 1840490, 514, 'In the Spirit of Christmas and the fact that I''m a bit of a Grinch I''ll strongly recommend getting Christmas Massacre.\n\nIn this third person Playstation 1 stylized game you will step into the shoes of Larry a depraved serial killer who gets ordered by his chatty Christmas tree to kill, kill, kill.\n\nA highly recommendable, dark and rather comedic Christmas game made like an old slasher movie and you are the bad guy.\n\n9/10 - probably the best Christmas game ever,', 'You''re going to burn for this.\r\nI am a big fan of Puppet Combo and their Torture Star label, which is why it is so disheartening to leave a negative review. But this game plays like a demo or a prototype for something that may or may not ever exist. \r\n\r\nYou play as Larry, a serial killer that goes around killing men, women, and children as they scream for mercy. Even putting aside the hollowness of the game''s story and the pettiness of the violence on offer, the violence just isn''t very good. Th', 'Very Positive', 91.83, 4.10, 0.33);
INSERT INTO reviews VALUES (45046, 1840800, 230, 'XCOM for dads and history nerds. \r\n\r\nDisregard the reviews regarding "getting hit by things you can''t see". Welcome to more realistic warfare: take out the spotters and you won''t need to worry about the artillery anymore. Check your corners and clear out anywhere a scout might be hiding. It''s not that hard if you''re willing to think tactically beyond full-on attack to the objective. I highly recommend turning on the LoS indicators and FoW to help make it more clear what you can and cannot see.', 'I purchased this game based on the reviews and expecting it to be a nice challenge perhaps in the vein of XCOM. After playing it for a bit I must say I am disappointed.  The difficulty of the game seems extremely easy and not at all dynamic like with X as an example where the enemy is trying to reposition.  It is a shame because I feel like the nuts and bolts are there but it just needs more balance Polish and perhaps some improvements to the AI.  The UI is pretty meh and I don''t like the hotkey', 'Mostly Positive', 76.09, 12.85, 16.45);
INSERT INTO reviews VALUES (45071, 1841240, 176, 'Best indie gem I have played in some time. Really enjoyed this one. The only negative review at time of posting is from someone with 0.3 hours on record that wrote an entire review about how this is not hyper light drifter. Not sure that is relevant. I didn''t care for hyper light drifter but loved this game. The only design choice that I really didn''t care for was the limited slots that you had to split between passive upgrades and traversal upgrades. It was annoying having to go into the main m', 'I really want to recommend this game. There''s a lot of positive aspects to it, such as the graphics, music and exploration/secrets. I really enjoyed exploring the world and seeing what new areas and equipment I could find. The fatal flaw for me, however, was late game. I think there''s a level of getting good with souls like games. Late game takes it to another level where I''ve had over 100 attempts on certain bosses. I''ve scoured the discussion pages and even watched a play through to see if I w', 'Very Positive', 90.91, 24.97, 14.48);
INSERT INTO reviews VALUES (45080, 1841390, 244, 'Nice game\nEZ to get all achievements 100%', 'Way too loud with no way to turn volume down.', 'Very Positive', 94.26, 1.77, 0.13);
INSERT INTO reviews VALUES (45155, 1843090, 1667, 'Great game, needs an endless mode where you serve coffees tho. Honestly very cozy if you ignore the stalker.', 'Only thing I found scary was the animation quality.  Characters clip through the doors too.  It''s laughably bad.  I didn''t watch a YouTube video of this game prior to purchase.  If I had, I would not have purchased.  I understand it''s an indie game but the quality is just too poor for me.', 'Very Positive', 90.58, 2.92, 0.80);
INSERT INTO reviews VALUES (45162, 1843310, 392, 'For some reason the game decided that when I do one part of an achievement, it means i''ve completed it all.\n\nIt''s okay so far but there are quite a few bugs. Just got soft locked in the Scott Pilgrim world (couldn''t do anything but walk around and shoot.) Other than that there is a lot of potential. If all the bugs get fixed soon then it''ll be peak.', 'this is the most cash grab horrifying consumerist slop I have ever played in my life. the game has made me lose all faith that AAA games could ever be good and its exactly whats wrong with the game industry.', 'Mixed', 69.64, 2.13, 1.03);
INSERT INTO reviews VALUES (45167, 1843470, 151, 'Dungeon crawling? Grinding for xp? Romancing characters around town? Yes please!', 'It''s a fun little RPGMaker style game with easy, chill game-play and a story interesting enough for the type of game it is. It kills itself, however, like many small indie devs do to their poor games - it has quicktime events. This is a turn-based game that suddenly has you speed-racing a goblin on level 35 in order to keep going, and it''s pass or fail. That''s it. I *hate* it when these flash/quicktime style "mini games" ruin something. This could have been a fun little story but the unnecessary', 'Very Positive', 90.73, 59.78, 34.63);
INSERT INTO reviews VALUES (45168, 1843540, 270, 'A dollar store Ratchet and Clank, and left in it''s shadow.\r\n\r\nGiven it''s fairly cheap it''s easy enough to recommend despite it''s flaws. I might be biased here cause third-person platformers with shooting is such a rare thing to see novadays there ain''t much to choose from.\r\nGameplay itself is "fine" but when it comes to stuff like weapon variety, characters, some of the design decisions overall leave a lot to be desired feeling that stuff wasn''t quite tuned right. Performance vice the game works', 'There''s a lot of reviews comparing this game to Ratchet&Clank, which in my opinion is far too generous: this is a strictly linear action platformer with 8 weapons TOTAL (and only 4 of them will see regular use), levels that are almost perfect corridors besides the short "secret" side paths (sometimes indistinguishable from the main path) with a collectible at the end, minimal progression mechanics, way too many reskins of what are fundamentally the same enemies, uninteresting story...\nIn R&C you', 'Very Positive', 84.44, 10.95, 11.07);
INSERT INTO reviews VALUES (45173, 1843730, 162, 'Amazing game with a great gameplay and a good loop, Worth the 11$ especially on sale.\nSean is a great dev with alot of talent, I''m glad to see him keep working on his game after release, Hopeful for more updates in the future but i feel like i got my 11$ worth with the content in the game already.\na good 9/10\n(Please for the love of god do not take on another project for this to be left aside. Like magicite and rougelands were)', 'Why does the AI kill you so fast even when your geared and it takes u so long to kill them. AI with 9mm doing so much damage this needs fixing. Just found something new the ai can see and shoot through walls now', 'Very Positive', 82.72, 33.62, 28.67);
INSERT INTO reviews VALUES (45175, 1843760, 4140, 'So silly to post negative reviews "abandoned game". It''s a "finished game" you dumdums. And a pretty good one for the price. I got wayyyy addicted to it until I beat the game on non-completely-ridiculous difficulty.', 'Abandonware.  Even worse, the creator was asked to implement QOL changes such as gamespeed updates, deck option updates.  Treated customers with contempt and refused, and abandoned the game.  Also not on the workshop so unable to get mods to do the work he was too aloof to do.', 'Very Positive', 80.22, 24.75, 141.17);
INSERT INTO reviews VALUES (45186, 1843940, 572, 'This is a really good and faithful sequel. I watched my monsters make a name for themselves and grow into legends. It got me invested and sucked me in just like Legend of Forsena did when I was young. I had my doubts going in that they, we, could capture that feeling again. I''m happy to say the more I played the more I felt like I had jumped into a time machine. Thank you for bringing the magic back for me one more time.', 'This game is absolute trash. There is close to no tactics, the battles last for hours for no good reasons, the UI is  a tragedy and the story is the most generic fantasy bullshit on earth. I know you''re hungry for a good turn based strategy, and lemme tell you: This is not your game. \r\n30 bucks thrown in the bin.', 'Very Positive', 90.91, 23.72, 4.18);
INSERT INTO reviews VALUES (45207, 1844380, 1095, 'I bought it on sale mostly for the army painter, to come up with paint schemes for minis.\r\nNo regrets.', 'game overall, decent try, no cigar. Far from what we really needed for a warhammer rts, like DOW2 or god forbid, DOW3, but so much worse.\r\n\r\nStory mode? Rough, a tower/convoy stopping mission as mission 3? With slow units and an enemy that just spawn and spawns his army unending? Lazy. If i wanted tower defence I''d waste my time on some free old school flash game or Gratuitous Tank Battles. (A decent TD game with wonderful features. Which I admit I never got good at due to its features being qui', 'Mixed', 56.44, 4.42, 3.00);
INSERT INTO reviews VALUES (45254, 1845670, 197, 'I did not come close to completing this game, but I had a good time. I have no nostalgia for the era of gaming that Islands of the Caliph is harkening back to, and this is my first time playing a game of this style. The experience was enjoyable in its novelty, but I certainly miss the quality of life features included in modern rpgs. I started taking physical notes on paper to remember which islands sold which products and which towns had which merchants and skill trainers. There''s certainly a c', 'developer thinks they''re genius for making the game keyboard only.  I spent 9 minutes hitting every key on my keyboard multiple times trying to close the help screen and no key closes it.', 'Very Positive', 92.39, 5.03, 0.22);
INSERT INTO reviews VALUES (45268, 1845910, 26856, 'Seems fine so far, combat is much more intensive.\r\n\r\nthe writing is painful, actually painful.', 'I beat the game. It took about 62 hours to do so and my biggest takeaway from this game is that this isn''t a BioWare game. \r\n\r\nBioWare made it''s name on "your choices matter", then boiled down 200 hours of content down to three questions and destroyed every former region in what feels like a scorched earth attempt to say "We''re done here, stop asking about things from Origins/2/Inquisition because they''re dead and now there''s no going back" and that nothing that we did in those three previous ga', 'Mixed', 68.95, 53.03, 65.65);
INSERT INTO reviews VALUES (45279, 1846170, 6339, '100 % in 1,5 hours, didn''t refund because this developer deserves every penny. The graphics make the atmosphere of the game phenomenal. Only negative is that I cannot relive this the first time ever again.', 'It''s a novel and reasonably well-constructed horror experience, but frankly, 7.99 for a 45-minute game with zero reply value is egregious. I haven''t refunded it out of respect for the creator, but there''s a reason that 2-hour limit exists, to discurage creators charging money for experiences that can be completed in a lunch break. Because this game should be free, it''s just not long enough to justify a price tag, 0.99 would be reasonable, 2.99 would be justifiable, but 7.99 is simply not worth i', 'Very Positive', 92.46, 2.03, 1.42);
INSERT INTO reviews VALUES (45289, 1846380, 17268, 'Very *ok*. The handling is awkward, the story is lackluster and the soundtrack is hit or miss in a way that the good songs are sort of okay and the bad ones make you want to cut your ears off. And I still enjoyed it more than Heat. The artstyle is genuinely the best thing about this game. Buy it when it inevitably goes on sale for like 5 bucks lol.', 'The worst handling model ever. Car randomly goes into drift mode and can''t drive straight.', 'Mixed', 63.77, 35.87, 10.43);
INSERT INTO reviews VALUES (45292, 1846460, 499, 'The closer we get to death, the clearer life becomes.', 'This game is quite the faulter to the standard of Harvester Games.', 'Very Positive', 94.99, 15.63, 3.48);
INSERT INTO reviews VALUES (45303, 1846720, 115, 'This version of the game definitely has some issues that need to be addressed. However, I think overall it is a very promising game that (besides the clunky controls and small bugs) I am having a lot of fun playing. \r\n\r\ntho the developers: Please knock this back into early access and continue to pour you hearts into this game to make it perfect! take the users feedback as motivation to polish up the game and make a strong comeback. In the mean time im gonna continue to play and enjoy the updates', 'Bugs that were reported in the Demo from 5-6months ago are still present & were not addressed. Visual glitches and sizing issues, Clunky controls when you interact with certain things at certain times only work a certain way but sometimes they will work the normal way all the time. I would say its just a launch issue & it might be patched in a day or two but these are the same bugs from months ago. \r\n\r\nSo I would wait a few months & check back to see if it as improved', 'Mostly Negative', 33.04, 36.78, 0.37);
INSERT INTO reviews VALUES (45311, 1846920, 704, 'Adult version Harry Potter.  Overall a good story, although the pace could be slow at the start especially if you are rushing for adult contents.  \n\nThe story mode is a novel with very few choices.  The sand box mode has more freedom and a little bit of resource management.  It’s better to play story mode first and sand box later.\n\nAchievements are not difficult but some are only acquirable in the sand mode.  First run of the story mode takes about 10 hours to complete if don’t skip texts.', 'The game is pretty decent as a AVN. The story so far is kinda mid but servicable, the renders are okay to decent. I actually like some of the characters (the Hermione stand-in is a cutie pie) and the lewd scenes can be pretty good. However...\n\nMy biggest gripe is with the gods-darned grammar! It''s so terrible it''s constantly breaking my suspention of disbelieve and destroys my ability to enjoy the story. Now, I understand that English isn''t everybody''s first language. Heck, it isn''t my first lan', 'Mostly Positive', 79.55, 13.35, 14.25);
INSERT INTO reviews VALUES (45331, 1847240, 233, 'very first kairosoft game that I''ve played when it came out on app store. Nostalgic. Still doing a good job i guess but it doesn''t feel right to play with my computer. There are much better tycoon computer games with so much depth. With this graphic and this depth, i dare say it''s an audacity of them to pull it out as a computer game. Perhaps the nostalgia is the selling point.\n<번역>\n앱스토어에 나와 처음 플레이 했던 나의 카이로소프트 게임. 추억돋고, 괜찮게 뽑혔지만 컴퓨터로 하기엔 뭔가 기분이 이상하다. 타이쿤 게임으로는 휠씬 낫고 깊이가 있는 컴퓨터 게임이 있기 때문. 이 그래픽과', 'I genuinely love Kairosoft games, unfortunately this one is just boring. There is no design element, you just sit in the same room continuously (you can upgrade the room to add more employees, but that''s it) picking game combos you hope work. Once in a while your games are judged for awards, or you pay to attend a convention to gain customers, but there is nothing engaging or whimsical like other games I have played.\n\nEDIT: Going back to get all the achievements is an absolute, colossal grind. D', 'Very Positive', 93.13, 2.88, 98.50);
INSERT INTO reviews VALUES (45344, 1847510, 181, 'I wish i had my own boba bar ~  o u o ♥', 'i love this game. i really do. however, it hasn''t gotten an update since 2023. \nif you want to play it, go for it! it is fun with what is already there! the price is perfectly fine (3.99€) but i doubt it''ll ever be finished. \n\ni''m only not recommending getting it due to the lack of updates. \n\nif you buy it you need to know that you are buying an unfinished game.', 'Very Positive', 88.95, 5.87, 7.80);
INSERT INTO reviews VALUES (45373, 1848270, 125, 'This is not SCP.\nSecure, Contain, Protect.\nThis is SCR.\nSecure, Contain, Reproduce.', 'Seriously don''t bother with this one. It compelled me enough to write a s hitty review, exposing myself, just to report how embarrassingly bad and mediocre it is.', 'Mostly Positive', 74.40, 5.42, 0.10);
INSERT INTO reviews VALUES (45384, 1848450, 2607, 'I finished the story twice, it gave a very good vibe like RESIDENT EVIL.\nSimple and interesting puzzles also with different guns.\nThe old quality made the game much scarier I definitely recommend it.\nClassic Classic\n7/10', 'I could not get into this game, I feel obligated to leave a review because the Overwhelmingly Positive reception led to to believe the game was something that its not. I was excited to try based on the idea that it was a low-budget, first person, abridged Resident Evil homage.\n\nPlaying the game, it immediately just felt cheap and bad. Its not just the lack of orginality (we really stretch the term "homage" for copying wholesale one of the world''s most popular survival horror games), but it just ', 'Overwhelmingly Positive', 96.09, 5.00, 0.45);
INSERT INTO reviews VALUES (45388, 1848520, 161, 'You don''t technically have to buy this. There''s a lot of free online copies out in the web, or a lot of places where you can just go and play this in games within games.\n\nHowever, I bought this for the controller support, and for the sale price of $1.39, that''s certainly worth the convenience to me.\n\n', 'I played this game when I first got it, it worked good. then when I logged off the game I could never get the game to play properly. It says its running but it isnt. very frustrating. So I gave up after trying multiple times .\nthe time I was able to play it,it was fun, relaxing.game.\n\n', 'Overwhelmingly Positive', 95.03, 3.97, 16.77);
INSERT INTO reviews VALUES (45413, 1848960, 231, 'I really enjoyed this one! All of Randumb''s games are good, but I enjoyed the Heavy Metal music and the Medieval theme in this one! \n\nChance of survival - 75.9%\nSecret Word - COURAGE.', '83.7% and my secret word was INHERIT and all i can say is.... what the FUCK is this hot garbage you call a "game"? this is a fucking quiz that does nothing to entertain.... i was frustrated halfway through the 2nd round of questions and just wanted to PLAY THE GAME.... to find out THERE IS NO GAME, JUST QUESTIONS!!!!!!!!!!!!!!!!!!!!!!!!!!!! in the About This Game, you have the nerve to write "What is Medieval Fantasy Survival Simulator? Well, in essence, it''s just what it sounds like!".... no it', 'Overwhelmingly Positive', 96.54, 1.12, 0.70);
INSERT INTO reviews VALUES (45416, 1849000, 1486, 'Hmmmm. Not quite sure what I think of the game yet. I will update when I have played the game a bit more.\n\nUpdate 4.5k: it’s pretty okay. I like the part when sex', 'This game is extremely historically inaccurate. Hitler only had one testicle but this game depicts him as having two smdh.', 'Very Positive', 83.65, 4629.30, 2.87);
INSERT INTO reviews VALUES (45426, 1849250, 5017, ' 1998-2025 \n RIP Rally by Codemasters \nPersonally I''d been here since 2007, enjoying their off-road racing games. Sure, many games were far from perfection, but it was fun while it lasted. The WRC licence marked their peak and their tombstone.\n\n *Listening Biffy Clyro - Mountains ', 'Kernel-Level AntiCheat for a Rally-Game? Are u fu*ing serious?\nI made an exception with buying an EA-Game after boycotting them for years,\nbecause this game was developed by Codemasters.\n\nNo EA-exceptions anymore.', 'Mixed', 59.42, 89.95, 7.53);
INSERT INTO reviews VALUES (45447, 1849790, 629, 'The game is lovely. But PLEASE add a training/practice mode for the later modules. Getting to reactors only to die part way through your first one, sending you back to 4 days of tutorial tier fixes has me eyeballing that "No" button. Or at least add some sort of upgrade that lets you toggle which modules can show up starting day 1.', 'Starts off alright and fresh; the new tasks are challenging when they are still something you learn, but everything quickly becomes boring and you start to skip things to get to the bosses/side quests.\n\nYour unlocks are not very meaningful and it feels like you should use Cheat Engine to get over the weird hump of the first few rent days to get to the actual part you want to play. This is because there are parts of the game that are always the same no matter what, so it becomes like an unskippab', 'Very Positive', 87.60, 40.02, 43.52);
INSERT INTO reviews VALUES (45456, 1849900, 1823, 'you can murder 6 year olds in this game.  10/10', 'Game can no longer be played without your consent to have voice recordings of your living room saved, stored and shared with a third party. This is not acceptable and shady behaviour by the devs.', 'Mostly Positive', 75.53, 4.25, 22.48);
INSERT INTO reviews VALUES (45463, 1850050, 601, 'Outside of a few performance issues that I eventually ironed out, this game was a great VR experience.  Don''t sleep on this title if you''re an Alien fan.  The Atmosphere, sound design, and the aliens themselves don''t disappoint. You''ll be panicking every time your motion sensor blips. Pro Tip: if you use Quest 3 you must use Airlink with Openxr to get the best possible performance/experience.  Virtual Desktop is a stuttery mess with this title.', 'I feel quite deceived by the devs and publisher that its now Part 1 on launch day, which was never mentioned anywhere before. Thats why I would give it a pass for anyone on the fence as 39 EUR is way too much. I have preordered it in august for 29 and there is no mention of being part 1 of who knows how many parts.\n\nIts a very sad state in which PCVR is right now and HL:A is still the best we got….five years ago! Everyone focuses on the Quest platform and thats such a shame. \n\nAlso: Alien Isolat', 'Mixed', 67.22, 12.87, 1.75);
INSERT INTO reviews VALUES (45468, 1850160, 1129, 'This game is super fun and is exactly like real-life physics! I really recommend this game,  and this is coming from an 10 year old', 'I know it sounds strange for a Poly Bridge game, but I really think this one jumped the shark. I started with Poly Bridge 2, and honestly loved it, it was super interesting and engaging to try to find complex solutions and using real physics and engineering principles to do so. Poly Bridge 3 has almost none of that. instead of interesting bridges that force you to think about structural stability or complex movements, it''s all just boring ramp levels and janky floating bridges, both of which hav', 'Overwhelmingly Positive', 96.28, 64.00, 5.95);
INSERT INTO reviews VALUES (45481, 1850510, 1200, 'Triangle Strategy is a bit of a generic name for a beautiful tactics RPG from Square Enix that delivers a focused combat experience inside an interactive political intrigue.\r\nFor fans of the genre, the comparison to Final Fantasy tactics or Tactics Ogre are warranted, but when I say that this tactics game is focused, I mean that the designers have condensed the essence of squad-based tactics combat into meaningful encounters. You will not find generic party members that you have to level-up to u', 'It could have been marketed better as Triangle Story or Occasional Strategy, but definitely not Triangle Strategy. Each battle is enveloped in countless JRPG-style story segments, one or two "exploration" segments, where you wander around a map talking to NPCs and collecting semi-hidden items, and a voting segment, where you use things you found in the exploration segments to coerce your companions to voting your way in an accurate, but not so fun democracy simulation. I have done 10 story battl', 'Mostly Positive', 79.08, 194.70, 20.22);
INSERT INTO reviews VALUES (45484, 1850550, 591, 'If you like observing and being on duty this is the game for you. I very much like observing and being on duty so it is the game for me. Go take your vitamins.', 'Hey uh dont use AI gen thanks\n', 'Overwhelmingly Positive', 96.95, 117.35, 7.77);
INSERT INTO reviews VALUES (45485, 1850570, 11724, 'Its more than a walking simulator. Sometimes its a running simulator, a swimming simulator, and a getting-dragged-away simulator. 9.5/10', '"Playing" this game feels like work. It''s weird at the best of times and frustrating at the worst of times, but I could never find a time where I would call this game fun. Taught me a valuable lesson about buying games just because of the hype around who made it.', 'Very Positive', 91.94, 80.93, 7.93);
INSERT INTO reviews VALUES (45491, 1850740, 2901, 'imagine a russian guy listened to all the requested features of phasmophobia and made them all in 10 minutes', 'It would be a good ghost game if there was a tutorial so you know what your doing with every item and how to use it, Throwing new player in a game with no tutorial. Tried playing it twice, Wouldn''t recommend to other from my personal \nexperience of the game.', 'Very Positive', 82.76, 3.15, 3.75);
INSERT INTO reviews VALUES (45498, 1850960, 476, 'That monkey from Nonsensory is so cool... can''t stop staring at him with my jaw on the floor...', '0/10 on Fibbage 4, the question was "Artist Prince midnight created a toilet shaped like ____". My friend put the answer "Lars Ulrich" whereas the answer was "Metallica''s drummer Lars Ulrich" and it got through. He then ended up winning by the points he got from it, as I wasn''t sure which one to pick! Very upset over this minor thing as he is rubbing it in my face and being very not humble, our friendship is lesser now :(', 'Very Positive', 83.40, 10.08, 9.12);
INSERT INTO reviews VALUES (45509, 1851280, 384, 'Yamato-no-Orochi gives eight heads at once.', 'I cannot recommend a game that neither ACTUALLY lets you reconfigure the controls (there are multiple menu options to change what the activate button is and what the buttons do, but the game ignores all of it) or retains those settings on death when you go back to the hub.\n\nDon''t get me wrong, the overall design and concept of the game is fantastic and I like it, but if you can''t let me put the jump button in a logical and comfortable place that humans use, that''s a no-debate refund', 'Very Positive', 89.32, 23.83, 0.45);
INSERT INTO reviews VALUES (45588, 1853200, 1834, 'As a black man in a America this game is the most accurate depiction of my day to day life that I have ever seen portrayed in any sort of media to date.', 'After using cheat game broke my whole windows. Not recommend', 'Overwhelmingly Positive', 95.04, 55.20, 0.93);
INSERT INTO reviews VALUES (45595, 1853410, 134, 'The Shape of Things is so cute, it’s super fun, and the smooth gameplay and the puzzles are well-considered. Minus the couple of things I had issues with, The Shape of Things was nearly perfect. I love it so much.\n\nIn addition, the game is cute, fun, relaxing, and worth picking up if you love these kinds of adorable little puzzle games.', 'Play the gachapon to unlock a new world. Every new world has ten levels. At each level, you need to rotate and assemble the broken object as precisely as you can to look like a new one. \n\nI wish I would like this game but the amount of precision required to assemble the object is frustrating. Maybe I''m lacking patience or playing on a console wasn''t ideal. The controls are difficult to rotate to achieve the required accuracy to fix the object to its perfection. It would be helpful if there was a', 'Very Positive', 88.81, 5.60, 11.37);
INSERT INTO reviews VALUES (45604, 1853760, 395, 'Overwhelmingly underrated game for the vast amount of content this game offers for its low price, especially considering it''s a solo dev. The bosses are varied and all have unique and fun mechanics, and there''s also so much to love for those willing to explore and find the games quirky little secrets. The humour and art style is also one of the game''s many strengths. Overall such a surprisingly well crafted experience.\n\nComing from a Fromsoft fan the games difficulty is also nothing to laugh at,', 'This game made me realise the importance of sound design in video games. Because the dev made all the sound effects with his mouth and they all suck. So the audial feedback of the game is a incomprehensible mess. (I still have no fkn clue what the various pitches of kissing noises meant during boss fights.)', 'Overwhelmingly Positive', 97.47, 20.00, 1.40);
INSERT INTO reviews VALUES (45608, 1853830, 131, 'Good game but I big downside is that half the time they just show the body and not the face', 'This game is nothing more than an abandoned Steam project. The developer has gone radio silent and that''s usually an indication that the game is DOA. Its been my experience that most developers (with abandoned projects) use Patreon for making money. They then release an EA game on Steam with promise of grandiose updates / future content usually to milk some extra money. And then nothing happens. Sadly as with many of these abandoned Steam projects, you get invested in the story and then...poof "', 'Very Positive', 80.15, 21.33, 9.13);
INSERT INTO reviews VALUES (45710, 1856030, 1109, 'This game is a whole adventure about cleaning trash! The game is fun overall and for casual players I do recommend this game. \r\n\r\nCOMPLETIONISTS: This game isn''t easy or fun to 100%, and I would have not recommneded this if that was my only criteria. The Africa level has been glitched for several years, the criteria for petting all the animals only occurs in specific circumstances. Fun for casual play but I had to go into the game files to finally get a 100%', 'On the last map my bots weren''t coming out of my inventory, so I dropped a save and quit the game to reset it and see if it would fix the issue. Booted it up to see my save was gone. 7 hours down the drain, now I have to play through and 100% every map AGAIN just to get to where I was.', 'Very Positive', 87.92, 35.22, 9.35);
INSERT INTO reviews VALUES (45753, 1857020, 129, 'The game is worth attention, I finally finished training my right hand, now I''m moving on to the left', 'Really bad game. The only thing you can do is click and cycle through possitions forever more to gain money and XP. It is an enormous grind. With the XP and money you can unlock locations, toys, and clothing. That is all this game is: click, click, click, click... It is sooooo boring, there are no words for it. The graphics and animations are bad, there are a lot of graphical glitches. The game looks cheap and made in a very short time. Total waste of your time and money.', 'Mostly Positive', 76.74, 5.02, 1.97);
INSERT INTO reviews VALUES (45757, 1857080, 468, 'Great fun - no wonder Scotty always had a way to increase efficiency on the Enterprise', 'I had high hopes for this game, but honestly, there are a ton better "Starship" games out there.  The one glaring thing for me; no bridge/cockpit/command center whatever you wanna call it!  Your ship is more like a floating factory with guns and thrusters lifeless pawns walk up to activate and the ship magically navigates.  On and those lifeless pawns are just that, lifeless!  No sleeping quarters, no mess hall, no habitation whatsoever.  They just bring stuff from point A to B then just stand a', 'Very Positive', 80.98, 29.77, 1.23);
INSERT INTO reviews VALUES (45758, 1857090, 2123, 'Priest fell in love with my wife and tried to go on a date with her.  I killed the priest a few days later an inquisition burns down down my entire village & kills me.\n\nWould do it all over again to protect my honor.', 'Just imagine that you cannot directly attack a settlement even if you are enemies with its leader. You have to send a messenger who will inform your enemy that you plan to rob it. From there, you must wait for his response. While he is thinking, he summons all allies. And having united with them he already says that he is ready for war and only then the option of attacking the settlement is opened. It''s the dumbest restriction I''ve ever seen, and it made me lose all desire to play. When will gam', 'Very Positive', 83.28, 21.75, 6.98);
INSERT INTO reviews VALUES (45784, 1857740, 205, 'I mean- it''s good enough or whatever. It''s nothing incredible but it''s a solid port. Fun enough combat, really shines in the selection of suits though and +10 points for being able to switch packs for the Strike Gundam mid mission. That''s really sick.\n\nJust wish Bandai cared more about the Gundam franchise. After what FromSoftware did with Armored Core we should be swimming in amazing Gundam games and not breathlessly clutching our pearls in hopes of a good port of a mobile, arcade or PlayStatio', 'they just cant make a good gundam game for PC can they?', 'Very Positive', 85.85, 12.00, 0.12);
INSERT INTO reviews VALUES (45808, 1858500, 253, 'Perverteer delivers quality every time. I loved SL so much. There''s even a Bella poster in one scene!! Currently Season 2 is in development and it''s on Chapter 20 of season two. Meaning at Chapter 24 it should be completed if he''s sticking to a 12 chapter format. Absolutely awesome story and if you wanna play up to the current Chapter, sub to the Patreon. It''s totally worth the price or if you have the patience, just wait it out, shouldn''t be much longer. We love you Pervy!! Make a Sisterly Lust', 'Well let''s see you go out of you way to find your sister and when you do she seems to not care that you have been trying to find her. Also when you get the option to romance her it from what I have seen doesn''t work out and she doesn''t want to have anything to do with you. All Eva cares about after you rescue her is to lead army again a war that you are forced to take par tin and that everyone on the she sides with the MC sister Eva against you hear. So in the long run the game is terrible.', 'Very Positive', 88.14, 18.62, 7.65);
INSERT INTO reviews VALUES (45813, 1858630, 715, 'Wait for a Sale, the only thing you do in the game is grind character levels on the same missions to get cosmetics. All characters have 3 preset skills/attacks, there is no customization except for clothes and weapon skins.', 'Don''t get me wrong, the game itself is great.  They took the best parts of the older games and put it all together.  But the problem is the need for always online connection.  I was in the middle of a cutscene in story mode and I get thrown into the title screen suddenly because bandai''s servers fail to communicate through no fault of my own.  Thats a big problem there.', 'Mostly Positive', 73.01, 44.55, 15.38);
INSERT INTO reviews VALUES (45814, 1858650, 344, 'Great game, my wife can''t describe a square though, would recommend the game. Would not recommend the wife.', 'Played the first two levels with my friend and refunded. There are better co-op escape room games out there, to spend your money on. This game was pretty boring. \n- The puzzles are very repetitive and uninspired. Most of the puzzles are just numbers and symbols, and some sort of lock for inputting them. There was one puzzle the game straight up made us solve twice, while just changing our roles.\n- There''s no context for the puzzles, they don''t naturally feel part of the world\n- Nothing else goin', 'Very Positive', 93.31, 5.63, 2.02);
INSERT INTO reviews VALUES (45848, 1859280, 723, 'Only three hours in and it''s been so much fun. As a linguistic enthusiast this game scratches my brain in a very good way. If you love solving puzzles, deciphering messages, and making abstract connections paired with a mysterious story, I would highly recommend the game!\n\nI''ll make an update when I get nearing to "finishing" the game.\nUpdate: Roughly 12 hours into the game, and have discovered most of the words meanings. I have to say the biggest source of enjoyment is when you start to begin t', 'I do like this game and the unique type of game play it offers. That said, I am very frustrated by the difficulty in the latter half of the game. Some words are near impossible to guess by context. Let me explain:\r\n\r\nConversational words like "meet, so, then, all" were very difficult to decode, as you could only guess them by the context of the sentences they were in, rather than being taught via environment or chores. This wouldn''t be so hard, if it weren''t for the fact that most of the sentenc', 'Very Positive', 86.45, 14.28, 7.12);
INSERT INTO reviews VALUES (45849, 1859290, 132, 'I bought for 30k Bitcoin back in 2010. Still living on it. Game is accurate, sort of.', 'Too much micro-management, what to do with the millions if you can''t spend it on a Lambo like a true cryptominer would do. Not accurate enough.', 'Mostly Positive', 78.79, 12.20, 2.03);
INSERT INTO reviews VALUES (45850, 1859360, 155, 'I like this game, but it can be frustrating at times. A few of my characters are stuck in the grass and I have no idea how to move them. Other than that, it''s your everyday garden variety tiny pixel city builder. It''s a pretty fun game for little money.', 'This game is a mobile game port. Is it a bad thing? Not really. The real problem is that it is a BAD mobile game port and that the game itself is VERY dated at this point.\n\n     Horrible controls. I tried playing the game on PC - and it was a nightmare as there are no controls for PC whatsoever. On deck it was better as it basically turned back into a mobile game.\n     Horrible user interface. Giant buttons, even the simplest actions require several clicks, you get barely any info what any of th', 'Very Positive', 85.16, 29.53, 12.68);
INSERT INTO reviews VALUES (45854, 1859470, 760, 'Please remake Pac Man world 2, it was amazing and needs to be brought back.', 'The only better things about this is the music and the easier platforming in comparison to the PS1 version.\n-No voice acting.\n-Slide move is gone.\n-Changed cinematics that have less charm, less personality, less emotion, worse directing and worse animation.\n-The charactar redesigns are awful. Ms Pacman in particular.\n-Overal worse presentation that feels a little soulless. The sound design in particular is dull and flat.\nOn its own its probably an ok-ish platformer, but i would stick to the PS1 ', 'Very Positive', 92.11, 0.52, 0.22);
INSERT INTO reviews VALUES (45860, 1859580, 152, 'Fantastic old school platformer, but less punitive and cryptic (I have Flashback or Heart of Darkness in mind). Still, the stiff controls and die/retry loops may not be for everybody. Narrative design, even without text, is also top-notch, and I found the art more impressive than most souless realistics AAAs.', 'I had no idea about the inspiration and messaging behind this game when I bought it. Felt a bit duped when the end screen popped up. Given that the story isn''t fully fleshed out, the end re-contextualized the entire game into a weird anti-covid lockdown message that just conjured up memories of boomers coughing in people''s faces because of masking. Lockdowns weren''t fun, but they saved lives. But, no, let''s sacrifice Peepaw so that Brayden can have a birthday party. If you thought the pandemic w', 'Very Positive', 87.50, 2.97, 2.28);
INSERT INTO reviews VALUES (45876, 1859910, 411, '明明很好玩啊 \n\n跟主角趙活一樣，被世間人誤解的游戲', '根本没做完。。。9个女主只做完了2个半。。。灾难级别的战斗系统+养成和属性不挂钩，武功增进到一代大师打杂摔死你敢信， 正派侠士满心态突然发疯給家人做黑暗料理纯恶心人。。。\n\n说句公道话，主线剧情是很感人。但是整个世界剧情只做了30%就正式版了，不标Early Access就是欺诈。。。什么时候改完什么时候改。\n\nUpdate: almost zero story update an entire year after launch.... RIP.', 'Very Positive', 90.51, 44.00, 59.05);
INSERT INTO reviews VALUES (45904, 1860510, 1676, 'Like Mount and Blade, but with modern military units and you can control anyone or zoom out Total War style. Needs more work, but this is already one of the most interesting shooters with the most potential I''ve seen in years. With the right handling ,this could be the better single player ARMA everyone could ever want.', 'I''ve put a decent amount of time into this game, and it''s been a great time for the most part. Are there issues? Yeah sure. But it''s a very ambitious early access title. \n\nMy main issue with this game, that can be applied to many early access games, is the release of paid DLC when the game is unfinished. This practice is garbage. You''re not releasing DLC. You''re charging us for content that should be in a finished game. You''re charging us for a development update. That is an absolutely ridiculou', 'Mostly Positive', 72.26, 15.17, 80.32);
INSERT INTO reviews VALUES (45934, 1861290, 319, 'A Kingsfield style roguelike. It''s fun and it embraces the fact you can upgrade your spells and stats to absurd levels. As a bonus, you can always drop by the Devil Spire Discord where the dev is very social and giving access to pre-alpha versions of the sequel.', 'It isn''t often that you find a game that would be outright ruined by a basic tutorial, but this is it. It starts out super strong. You meet a lot of strange npcs, the strange items and crafting system create a lot of mystery, and the game is very challenging. phenomenal first impression all around. \n\nYou learn pretty quick that the npcs dont matter and the story is practically nonexistent, so the gameplay is going to do a lot of heavy lifting, but it fails to hold up. This is why the game doesnt', 'Very Positive', 91.54, 25.40, 11.62);
INSERT INTO reviews VALUES (45948, 1861610, 966, 'So I can''t speak for everyone else but this game is a buggy mess right now. It''s only $4 which is good. It shows some promise but It looks like the developers game and mine are completely different. The menus don''t work. I''ll come back once more fixes are done. For now the game plays like dogshit. Promising game tho I like the idea for sure.', 'for those coming from social media like tiktok or insta after seeing someone play it... do not even consider buying this game. it is miles from finished and is extremely clunky. The dev is paying people to post clips of the game to bait people in buying it. You will literally touch this game for 10 mins and get bored. The only reason youll come back to play it is because the dev always titles his updates as "biggest update yet" or "best update ever" as bait when the only thing that is changed is', 'Mixed', 54.76, 0.37, 0.40);
INSERT INTO reviews VALUES (45956, 1861880, 110, 'PLANES, STRESS, ANXIETY, AUTISM.\r\n\r\nI love it.', 'complicated and not simple', 'Overwhelmingly Positive', 95.45, 11.93, 0.68);
INSERT INTO reviews VALUES (45958, 1861970, 226, 'Friends and family looking at my account and seeing this game here.\nI swear it was just a joke that I got this game!\nnothing else.\njust for shits and giggles ya know!\ntrust\nHAHA', 'It''s very bad compared to Mister Furry Hot Muscles. The concept of doing random mini-games for some random furry pictures is so bizarre to me. At least Mister Furry Hot Muscles made some sense, as nonsensical as that was. I just don''t know how to feel about this. I must say that I''m very disappointed, and I had elevated expectations because of Mister Furry Hot Muscles. My bad, I guess.', 'Very Positive', 91.15, 1.68, 0.50);
INSERT INTO reviews VALUES (45976, 1863430, 225, 'Theres someone in the reviews thats 7 hours in the game and doesnt know how to teleport in the city. that should tell you enough to not trust the reviews lmao', 'Game feels more like an Alpha 1 than an "Early Access" they say it will be fully ready in 7-10 months which feels a little ambitious but I wish them the best of luck.', 'Mixed', 64.44, 18.38, 0.30);
INSERT INTO reviews VALUES (45981, 1864880, 241, 'Very promising, one gripe - "dont place houses near quarries as the sound is annoying"\nYes, the sound is extremely annoying, so why are you making me listen to it constantly? Please, unless you are zoomed in fairly close to a quarry, please turn that fcking noise off :)\n\nOk so fuller review, built a big city, now the game is just waiting for each wave of blobs to crash into my walls. Love the idea of the game, and very impressive for one dev, but its missing something. I dont feel there is anyth', 'its alright. i dont know why every indie developer feels the need to coerce me into joining their discord server though', 'Very Positive', 92.95, 34.68, 0.43);
INSERT INTO reviews VALUES (45986, 1866430, 117, 'I remember playing this game as a 6 year old and having a hard time finished it.\n\nNow as a 30 year old mom I finally able to save my prince!', 'Gave this game a chance but it''s really not for me. Musical bits are hard to sit through, the game is piss easy even on hard mode, and its sense of humor just falls flat most of the time. Kinda glad though. I was going to try out the sequels but people keep saying they''re a bit of a downgrade to this one.\r\n\r\nSo, uh, thanks for helping me save money I guess.', 'Very Positive', 91.45, 9.52, 3.52);
INSERT INTO reviews VALUES (45987, 1866630, 243, 'This game surprised me, in a good way. It quickly became a favorite "session" game that I jump into at various times throughout the day. It provides a good balance of variety: enough to make every run unique, with new and fun ways to "break the game," but not so much that learning the possibility space is a chore. It just feels good to play, man, and it has good "bones" (sorry). Definitely give it a shot.', 'I would recommend waiting on this one, very fun for 4 hours or so, but I''ve done 90% of available builds in the first 5 hrs.', 'Very Positive', 90.12, 13.65, 9.03);
INSERT INTO reviews VALUES (45990, 1866880, 234, 'Awesome game, highly recommend this game. \r\nIf you like vampire survivors and webtoons about martial arts cultivation you will love this game.', 'I think the game isn''t very fun. Also not even sure why my right joystick makes me move a sword around it doesn''t seem to do anything and the game explains everything really poorly so I am still lost. I also don''t like the sudden massive increase in difficulty after defeating the first boss. Surrounded by tons of enemies while tons of bullets fill the screen, like I''ve played many shmups but even then that was insane to me, cuz there aren''t any proper patterns to weave through cuz the enemies ar', 'Overwhelmingly Positive', 96.15, 208.12, 0.87);
INSERT INTO reviews VALUES (46003, 1867190, 128, 'A useful game for learning a language and memorizing the spelling of words; learning words in a game is much easier and more fun than in books and textbooks)\n', 'DO NOT BUY THIS GAME. Tons of words are misspelled completely. Words are repeated even in the VERY NEXT PUZZLE at times. A lot of the categories words are proper names which anyone whos played Scrabble knows they SHOULD NOT BE. Also ive no clue what the achievements are tied to, I did random categories and got all the achieves by the time I had done 65% of the puzzles. Would be completely unplayable without a guide. I only completed it because im a completionist soooo... >_> but just dont bother', 'Mixed', 66.41, 2.60, 1.58);
INSERT INTO reviews VALUES (46014, 1867510, 386, 'Step into tights, suplex a cactus, and take life advice from a pixelated Randy Savage. It’s part RPG, part fever dream, and 100% committed to the bit. I admired the pixels, flexed through the grind… and somehow still felt like I lost the belt. 🤼‍♂️✨🎮\r\n\r\nFollow my curator page for more pixelated chaos, genre mashups, and games that drop the elbow and the emotional arc! 💾🎭💥\r\nhttps://store.steampowered.com/curator/42602807-Osiris-Reviews/', 'All the fun parts light the wresting chalenges are few and far between.  Once you get to know a character they switch you to someone you do not care about and play for 1-2 hours. horibble game play. backtracking is insane and you have no idea what to do at times. oh and THERE IS NO FUCKING MAP. which would be insanely helpful in 90% of the game.', 'Very Positive', 82.12, 4.30, 69.45);
INSERT INTO reviews VALUES (46016, 1867530, 900, 'This isn''t Heart Machine''s previous game, Hyper Light Drifter. This isn''t even an action game, really: it''s a 3d exploration-platformer where you roller-skate through gorgeous, colorful yet dilapidated worlds inside a black hole. Drifter, gameplay-wise, was about snappy, controlled movement and brutal assassination. Solar Ash, instead, is about floaty, freeflowing constant movement, sliding and jumping and rail-grinding and grapple-hooking, whether through relaxed wandering or occasional brief t', 'Solar Ash is a movement-based platformer game with some great world building, voice acting, and accompanying sound design. The world consists of various levels that seem to be made in their signature neon-colored cyberpunk art style, which lends a great look to the world and feels like a lot of fun to look at and explore. However, as all the levels/worlds sit in these foggy blue clouds, some parts of the world can feel a bit empty and boring. But one can mostly just ignore these side areas to en', 'Very Positive', 90.33, 11.12, 9.17);
INSERT INTO reviews VALUES (46038, 1868000, 103, 'The game''s reliance on RNG and the effort required to deal with difficulty spikes at the endgame just doesn''t match up with the quality of the story and the lewds. This gives the impression that the endgame either hasn''t been properly playtested or the developers are just being sadistic.\n\nDespite this, the story has a good premise, and the characters are well-drawn. However, it''s all bogged down hard by the translation, which, while not machine translated, is still amateurish at best. The transl', 'AI art', 'Mostly Positive', 70.87, 12.80, 16.92);
INSERT INTO reviews VALUES (46047, 1868140, 42842, 'Nikke collab event sent me here, and wow this game''s actually pretty cool.\n\nWhen are we getting the Nikke content pack? :)\n\nIf you missed the event post, you can call the operator and redeem the code ''AEGISTHEDIVER'' for a unique boat skin featuring the aforementioned Aegis squad. It''s not exactly playable Helm, but it''ll do.', 'Time limited DLC.\n\nI planned on getting it when it came out but when I found out it was only available to buy for 6 months after release, I avoided it. Game preservation is important, and it''s already bad enough in game as a service titles. We don''t need this in single player games.', 'Overwhelmingly Positive', 96.94, 6.82, 14.23);
INSERT INTO reviews VALUES (46049, 1868180, 298, 'get quest - Enter dungeon- walk and get into battles- hp gets low- walk back to town- gets jumped by FOE- wipes whole party- Game over - lose hours of progress - fun game', 'Great game, Denuvo sucks.', 'Very Positive', 91.28, 26.30, 42.23);
INSERT INTO reviews VALUES (46095, 1869270, 309, 'The greatest thing since the last thing to put anime girls and tanks together.\n\n11/10', 'when you die you lose all progress', 'Overwhelmingly Positive', 97.09, 21.07, 3.62);
INSERT INTO reviews VALUES (46155, 1870700, 106, 'Makes me feel like I''m back in the 90s and I''ve found some banned black market gameboy game.', 'The game could be fun, but the battles are way too difficult at the beginning. I battled a moose that was 1 level below me, had to use every piece of food that I had, and it still killed me.', 'Very Positive', 91.51, 0.33, 0.75);
INSERT INTO reviews VALUES (46180, 1871310, 374, 'Just as good as Hook 1. Truly a relaxed puzzle where you push forward by dismantling the puzzle piece by piece. Can''t really get stuck but fail too many times and a restart it is. Late game puzzles really stresses your ability to look at things in 3D but still one doesn''t really get stuck.  Excellent game and one of my favorite genuine ''relaxed'' puzzle series. \n\nJust the stuff you need when you got 15 minutes spare time.', 'It''s a decent game, but there''s just a couple issues that are just too frustrating for me to be able to recommend it.\n\nThe first one is the alignment connections. In some puzzles, all the hooks are laid out in 2D, and the alignment to connect it happens to be such that you don''t get to see at all what you''re moving, and when it tells you that some things collide, you don''t get to see them as the whole puzzle falls on a line to be able to align visually the connections, not to mention that it kin', 'Overwhelmingly Positive', 97.33, 2.23, 2.10);
INSERT INTO reviews VALUES (46190, 1871480, 104, 'fun card game and futa? makes a mf wanna say ''hell yeah''', 'The game is fun and all, but it honestly needs a difficulty choice. the dev/creators refuse to do anything like that claiming "it has to be this way" but, the game really only needs a slight adjustment. if you want a completely unbalanced challenge, then the game is for you, but if you''d like a challenge that''s actually fair? then this isn''t it', 'Mostly Positive', 76.92, 12.98, 36.53);
INSERT INTO reviews VALUES (46193, 1871510, 101, 'Very interesting to explore the aftermath of Epstein''s island.', 'This game is and will be the worst horror indie game i''ve ever played. the amount of time walking and nothing happening to the very underwhelming ending and no so scary jump scares. DO NOT BUY!!!! SAVE YOUR 2.49 cents and go to the gas station. you be better off', 'Very Positive', 82.18, 1.18, 1.07);
INSERT INTO reviews VALUES (46242, 1872680, 276, 'It took me about 2 months of playing off and on (around 11 hours) to 100% the game. Do I recommend it? Yes. Was it what was I expecting? Not really. Bullet hell metroidvania sounds incredibly promising, and while the game is good it tends towards frustration. I would perhaps blame that on mana for cards getting funneled into powerful weapon cards and there not being a lot of unlockable metroidvania features. Some people with a better brain than me might make interesting decks, I made one that al', 'I love most things about the game, but halfway through there are levels that are just not fun at all, and then they add enemies that auto-hit you every X seconds unless you''re spamming the dodge button, all while trying to dodge everything else. Too many times dying without even seeing what hit me. Not fun. Waste of time.', 'Mostly Positive', 71.01, 11.35, 7.50);
INSERT INTO reviews VALUES (46248, 1872790, 166, 'A fun tower defense, dice game hybrid. Super easy to pick up, moderately complex gameplay.\r\n\r\nI beat it in under 10 hrs. I wish it was longer and harder.', 'What it is not:\n- a decent tower defense\n- a decent citybuilder\n\nWhat it is:\n- a novel one-session-game attempt', 'Very Positive', 80.72, 13.87, 3.62);
INSERT INTO reviews VALUES (46251, 1872860, 692, 'TLDR: Conrad Stevenson''s is a slow-paced game with no major threats or "puzzles," but is a narrative piece of art that makes you feel like you''re actually learning about the ghosts that you''re investigating. It''s a really, really good game, but play it when you feel like lazing about- the game is not fast paced or action filled. That game''s not about Monsters of Dead, they''re about People who were once alive, and currently suffering.\r\n\r\nI''m amazed Steam only has 16 hours on record, I''ve owned th', 'There is a good game in here somewhere but I just don''t think it lives up to the early potential. Going through the first couple of houses sets you up with a few good ghosts to deal with and all looks promising. The third location you unlock just ruins what was set up. The map goes from a small house to a small town which does nothing more than spread the encounters out with an incredibly slow walk speed. Ghosts start getting very shy despite the notes you have being correct, standing around for', 'Very Positive', 93.93, 16.95, 16.93);
INSERT INTO reviews VALUES (46293, 1874000, 3422, 'As a die-hard Chloe stan, ignore the haters and play this. Yes you''ll miss her, and yes it''s a little slow starting off (I think it rests on its laurels slightly in the beginning, assuming that just having Max will get and keep our interest rather than working to gain it anew), but it''s also worth persevering as episodes 2, 3 and 4 in particular are pure gold. Lovable characters, the plot had me HOOKED (what started as ''cool I''ll finish episode 1'' turned into an all-nighter to finish it because ', 'Nostalgia sacrificed for "good" graphics & money knowing many LiS lovers who gave up after LiS2 would give this a chance. I''ve played all of the LiS games, loved them even loved True Colours but this one just was a very big let down, zero depth to Max''s powers and zero depths to any characters. The best thing about LiS has always been the emotional attachment you gain towards the characters and how much you can bond with them but this game lacked that, even the love interests were pointless. The', 'Mixed', 66.57, 10.20, 10.47);
INSERT INTO reviews VALUES (46298, 1874170, 2319, 'One of the best snowboarding games I''ve played. The game has solid mechanics and feels more realistic than Steep & Riders Republic.', 'STEAM DECK PERSPECTIVE---\n\nI don''t think this game currently deserves the Verified tag for Steam Deck. It''s seemingly quite a fun experience, esecially if you really know your stuff when it comes to snowboarding. However despite spending an hour tweaking the graphics, resolution and such, I still encountered significant drops in frame rate, down to as low as 10fps at times, and this was before trying out the multiplayer or many of the Missions.\n\nI personally had a hard time following the beginni', 'Overwhelmingly Positive', 95.47, 21.12, 1.12);
INSERT INTO reviews VALUES (46310, 1874490, 4759, 'The newest update to Potionomics absolutely changed the game for me (literally and figuratively).\nI played this game a fair bit around the time it first came out but fell off of it because I felt some of the elements were a little too punishing and I got bored. After watching a review video a few months back, I decided to give the game another chance, this time on Steamdeck, but found it unplayable. Since having a baby, I can really only get game time in on my Steamdeck, so if it''s not Steamdeck', 'This looks like it could be a really cute game - the minimal time I got in it of gameplay was enjoyable. However, I''m playing only on Steam Deck which states this is verified - sadly it''s a buggy, crashing mess. I''ve restarted the game 4 times in the just over an hour of gameplay and each time lost massive chunks of progress. Do not buy this if on Steam Deck thinking it will work properly. Hopefully future updates fix this as it''s such a shame.', 'Very Positive', 90.21, 7.02, 1.07);
INSERT INTO reviews VALUES (46321, 1874720, 146, 'Get water in a cup and get nude elves in return... can''t believe I just wrote that sentence. The art is nice though.', 'Pretty much just a gallery game.\n\nYou can complete the entire game by just clicking skip so there''s no need to play sadly.', 'Very Positive', 82.19, 0.47, 0.10);
INSERT INTO reviews VALUES (46325, 1874880, 18726, 'In 40 hours of gameplay the most important thing ive learned is if you get in a vehicle with teammates there is a 75% chance you will die in a violent car crash way before you get to the enemy base. \n\n10/10 would be ejected thru the windshield at 60mph again', 'If you check steamdb, you will see that the developers increased the price right before both holiday sales, so holiday pricing was actually just what the game was usually sold for. Dishonest practice.', 'Mostly Positive', 75.93, 105.60, 1.85);
INSERT INTO reviews VALUES (46330, 1875060, 1250, 'Reus 2 is a better sequel to Reus than most sequels are to anything. Lots of games, especially nostalgic properties, just get sequels for the sake of making sequels. Reus 2, however, exists to be the Reus that the original Reus was not.\n\nI considered the original Reus to be an excellent puzzle game. Upon hearing about Reus 2, I was a little afraid that the changes the developers would make to the core gameplay would be too fundamental and detract from the original vision of Reus 1. I couldn''t be', 'I hate that they removed ''greed'' mechanic from Reus 1. It used to be an amazing RTS with pause, but now the game feels more like a solitaire, a turn-based puzzle game. \n\nThere''s no more danger, no more time-management, no more balancing on the knife''s edge between growth and collapse. You just place things until you run out of things to place and see what you unlocked.\n\nMaybe the game is less stressful this way and for some it''s a good thing? But I didn''t get a chill vibe first hour playing. Pla', 'Overwhelmingly Positive', 96.00, 39.17, 1.28);
INSERT INTO reviews VALUES (46364, 1875830, 3042, '', 'A fun game that runs great on steam. Regrettably, they waited days after release to put out a new EULA that says you don''t own the game. I can''t refund it, as I''ve already played too long or I would have. Game companies that think that $60 dollars to  rent a game until they don''t feel like you playing it is absurd and should not be supported. I won''t be buying any game published by Sega for at least a month after launch now.', 'Overwhelmingly Positive', 96.15, 0.00, 38.52);
INSERT INTO reviews VALUES (46368, 1875950, 132, 'this game omg...... the grip it had on me when i just started playing it, every evening was filled with playing the routes. at this point i''ve finished all passionate endings, and i just want to say that this visual novel is so special to me and i 10000% recommend it. the worldbuilding is insane. all routes are unique in their own way. it really pays off to play them all because you learn something new about the universe the story takes place in every time. the writing is amazing. all the romanc', 'I have to be honest, I have been playing for 17 hours and I haven''t even completed a single romance. There is *so* much reading. Like.... so.... much.... reading. I have dyslexia, so it takes me a while to get through it. I feel like a lot of it is unnecessary and doesn''t add context or information that actually matters. I don''t know if that is a translation thing or what, because the wordings of things is very odd as well. Anyway, it is hard to say if any of the characters are captivating enoug', 'Overwhelmingly Positive', 96.21, 75.85, 44.42);
INSERT INTO reviews VALUES (46395, 1876590, 3064, 'I expected the extremely fun and frantic gameplay when I bought this, but the shockingly compelling homoerotic story and great VA work was a bonus.', 'Screen shaking is VIOLENT with any melee. There are two settings to adjust ''head bobbing'' and ''arm bobbing'' but any melee, whether it connects or not, violently shakes the screen to the point of making me nauseous. Until accessibility is addressed, I cannot recommend this game despite really wanting to play it.', 'Overwhelmingly Positive', 98.43, 3.20, 0.17);
INSERT INTO reviews VALUES (46414, 1877020, 1879, 'needs some oiling up ngl. severely disappointed in the lack of oil', 'Nah i''d refund.', 'Mixed', 58.59, 1.20, 8.25);
INSERT INTO reviews VALUES (46460, 1878070, 120, 'Reminds my of the very first computer strategy game I ever played in the early 90''s called ''Centurion: Defender of Rome''.  It was a super simple Proto-RTS with an even simpler strategic layer.  It was fun and easy to play without a huge time investment, just like this game.  For $6 you don''t even have to wait for it to go on sale to get your money''s worth.', 'I get to the starting menu and frames drop. I have a more than good enough pc t run this. Just sad really.', 'Very Positive', 85.00, 1.20, 1.25);
INSERT INTO reviews VALUES (46489, 1878740, 454, 'peakest of peak. if you want to live through the peakest peak of peak life, play this peak peak. its peak', 'ver scarey i go so scare i poo meself an  run 4 loop around me hous an the i threw up on the carpit after crying from scare', 'Overwhelmingly Positive', 96.26, 0.37, 0.37);
INSERT INTO reviews VALUES (46513, 1879330, 433, 'i have played  Orochi 2  when i was still a child and it made my childhood, and now i''m going back to this amazing series with  Orochi 3  to enjoy how good at was, lot of people say that orochi 4 is better so i''ll keep that in mind to play it after this one, i don''t think people will enjoy Orochi if they didn''t try samurai warriors or dynasty warriors, they won''t understand how goofy to put Japanese warriors with a Chinese warriors at the same time so yeah they won''t understand the fun with it.', 'Boring. Grindy. No interesting concepts. No English dub. It''s one of those games that gives you the illusion of customisation of the battlefield.', 'Very Positive', 91.45, 97.98, 7.18);
INSERT INTO reviews VALUES (46564, 1880470, 100, 'Reminds me of original Witcher game: rough around the edges, but a really interesting world, lore, and dark atmosphere. It''s also based on the books of a Polish author, like the Witcher. \n\nIf graphics, facial animations, and modern gameplay is really important to you, then you probably won''t like this game. BUT, if your priority is story and the atmosphere of an original and intriguing dark world - then I would definitely recommend this! \n\nI really hope ''the Inquisitor'' gets a sequel! It would b', 'I was willing to risk blasphemy in the hopes of a great fantasy story that would make me appreciate how God loves us in reality. Unfortunately, I got what felt like an underwhelming PS2 game.', 'Mostly Positive', 71.00, 4.48, 0.33);
INSERT INTO reviews VALUES (46566, 1880610, 113, 'Good game but it''s free on Epic now, sry :3', 'no way its free on Ep1c', 'Very Positive', 82.30, 1.17, 0.10);
INSERT INTO reviews VALUES (46586, 1881120, 216, 'It''s a little like Firewatch in space. There are not a lot of games like that. Firewatch is one of my favorite games so I enjoyed this very much. The ending was a little flat tho.  (Also has a little Soma in there)', 'It was promising at the beginning, but after those dull cyber cube puzzles, the game became very boring and tedious. \nToo generic and monotonous.', 'Very Positive', 89.35, 3.70, 1.98);
INSERT INTO reviews VALUES (46587, 1881140, 107, 'bought it while drunk and yeah 7/10', 'i don''t like this game.', 'Mixed', 68.22, 0.45, 2.63);
INSERT INTO reviews VALUES (46590, 1881200, 1004, 'I just bought myself an Avata 2 and the FPV 3 controller so wanted to check out the sim scene for practice, TRYP has been so much fun to both learn, and to just play as a game. I love flying around the mountains and buildings making up lines and familiarising myself with the FPV experience, it''s actually incredible how it goes from wtf I''ll never get this, to omg it actually works a few hours later.\r\nI''ve practiced with all the styles and think I''m a mode 3 boy, right stick throttle feels intuat', 'Throttle works great!  Straight up or straight down.  Let go of throttle....Straight up!  That''s it, nothing else works.  Xbox one controller, tried all different stick modes, calibrating, still nothing but throttle.  Uninstall.  Refund.', 'Very Positive', 85.56, 12.42, 0.35);
INSERT INTO reviews VALUES (46604, 1881420, 711, 'I sold my house to buy this game', 'I have been playing Cardfight Vanguard since the OG limit break era. I still remember my first deck being a Dimensional Robo deck built around Great Daiyusha. I played the irl game all the way up until V era ended. After Bushi rebooted its game not once but 3 times, I saw a pattern. I went ahead and bought this against my better judgement thinking it might be fun. It was...and then I realized this was another Bushi cash grab. The DLC is significantly overpriced compared to other games and offers', 'Mostly Positive', 79.18, 70.18, 49.08);
INSERT INTO reviews VALUES (46636, 1882240, 158, 'Love these games.', 'I hate that I''m ending up giving this a negative review, I mean I got it for almost free on sale. But there''s just too much holding it back to enjoy.\n\nSo I''m not old enough to have ever played the originals or know anyone that did, but I''ve done plenty of DnD. Unfortunately, I''ve only really dealt with 3, 3.5, and 5. So much of that knowledge is utterly useless here. But that''s ultimately not even the real issue.\n\nI don''t mind having to learn an even older version of DnD, but I''m not doing that ', 'Very Positive', 90.51, 169.58, 0.77);
INSERT INTO reviews VALUES (46638, 1882280, 196, 'I had this AD&D game, Unlimited Adventures when i was a kid, all through my young years playing it in my very ordinaryish 1940''s style basement in Binghamton New York, crafting and making up my own creative adventures, quests, campaigns, and storylines. Forgotten Realms is my sacred thing of the AD&D entertainment world, i do recommend Forgotten Realms Unlimited Adventures for AD&D fans, creative and interesting geeks, and amused RPG goers and hardcore fans for lots of positive immersion, sereni', 'This bundle does NOT have cloud saves. The publisher is advertising that falsely. The publisher does not respond to emails.', 'Very Positive', 89.80, 30.87, 83.62);
INSERT INTO reviews VALUES (46648, 1882500, 1072, 'The game has good replay value, the characters are flushed out, the gameplay is good, and overall it is just amazing. However, it feels like the devs have abandoned the game after pushing a couple updates and calling it good, which also happened with the first game. They are still active and responsive in the community, but CWW has SO much potential. The community pulls through though with mods that enhance the game with more characters, furniture, maps, and more. Highly recommend, just wish tha', 'One storyline that can be completed in less than an hour. Very little content, not worth the price to be honest. The dev team promised all these things that just fell flat in game because there is a genuine lack of content. It feels like the dev team didn''t even want to make the game to be honest.', 'Overwhelmingly Positive', 98.04, 199.02, 37.35);
INSERT INTO reviews VALUES (46675, 1883090, 182, 'I hate that its so short because the voice acting and art is so good! There is a second game and I PLAN on playing it! Story and music is amazing too! Also this game the NSFW it is cut off, It cuts it out and don''t see the bottom part of this game. If you are like that then this game is for you! If you do like that NSFW, like me, there is a DLC they give away for free on here! Just make sure that the game IS CLOSED when downloading it so you can see it, if open and you download it you will not s', 'Its... fine? The actual story has zero stakes. They keep introducing things that make me go "Oh that''s interesting, that must be the outside conflict" only for it to never be brought up again or immediately resolved. \n\nThe art is beautiful and the voices are great. The VAs did a really solid job of sounding believable and charming. I wish their dialogue wasn''t so stiff. They talk like they just walked out of therapy directly into a sex ed video. It''s very strange. I can appreciate the focus on t', 'Overwhelmingly Positive', 96.15, 5.90, 2.30);
INSERT INTO reviews VALUES (46682, 1883260, 421, 'This feels like a Nintendo WIi game in all the best ways possible. A fun short roguelike if you''re looking for something quirky.', 'This is a essentially a mobile game for PC.  It''s not worth $14.99 and there isn''t much depth.  There are better things to spend your money on.', 'Overwhelmingly Positive', 95.01, 7.98, 0.23);
INSERT INTO reviews VALUES (46688, 1883370, 257, 'I remember 10 years ago, playing Undertale for the first time. When I beat it, I remember thinking "Man, what a special game. I wonder how long it will be until I play something else that hits like this."\n\n10 years. 10 years is how long. \n\nDelta Rune aside, this is the closest I''ve gotten to that "Holy shit I''m experiencing a modern classic" feeling since I played Undertale a full decade ago. \n\nI haven''t beaten it yet, so maybe my opinion will change and I''ll have to update this review, but for ', 'I wasn''t aware going in that this is a troll game that will screw you over if you don''t already know to expect, or don''t plan to play it multiple times. The game says you only get to try things once but that isn''t exactly true. You can retry plenty of things an arbitrary amount of times, which doesn''t feel good at all when you almost complete the task on attempt #3 or #4 but suddenly you don''t get a #4 or #5. It tries too hard to be memey and it turn just feels disrespectful to my time  and effo', 'Overwhelmingly Positive', 95.72, 4.60, 7.45);
INSERT INTO reviews VALUES (46697, 1883580, 151, 'Aunt you can''t stop me in playing videogames.', '🌵', 'Very Positive', 87.42, 6514.27, 101.53);
INSERT INTO reviews VALUES (46702, 1883800, 268, 'I bought this unsure whether I''d like it or not based off other people''s reviews, and now I have played it at least a little almost every night since then. That being said, this game definitely isn''t for everyone. I would say the biggest gameplay focuses are the workshop/automation mechanics (setting up your brewing stations, figuring out storage, etc.) and then gathering resources. And boy howdy are you gonna need resources. I don''t even typically take to automation games, but this one lured me', 'It''s cute and functional, but overall just not a lot of fun. Everything turns into a bit too much of a grind and even progressing feels like you''ve made more work for yourself. Most of the game is just running around and grinding components. The rest is micromanaging inventory space and moving things between boxes. Oh, and unclogging broken equipment is a lot of fun when you''ve got one wrong component stuck somewhere. Had a few bugs here and there, like not being able to interact with customers ', 'Very Positive', 82.84, 54.63, 39.52);
INSERT INTO reviews VALUES (46752, 1885110, 1428, 'The game is completely ruined, they didn''t accept refrigerator as an answer to "what can run but can not walk" Luckily it still accepted nose as a response. I just refused to answer a river', 'The word scramble + dungeon crawler concept is great on paper, but the novelty wears off quickly—and once it does, the combat system’s lack of depth starts to show. I guess it’s the kind of game that works quite well for streaming.', 'Overwhelmingly Positive', 95.24, 10.12, 0.90);
INSERT INTO reviews VALUES (46773, 1885690, 206, 'Cool little game about simulating digital logic circuits.\r\n\r\nYou gotta be a special breed of autistic to enjoy this, and I''m one of them.', 'Hahahahah very sad to see the poor on-boarding for new players, the game seems perfect, if not for throwing you into a total abyss of information on your own, I expected to be able to jump in an begin ''playing'', but it isn''t really a game, as it''s more like a tool set to explore circuit ideas... but it''s not really even user friendly.\r\nthe information you''re given as a new player is very, very, wordy and without a audio explanation it isn''t a breeze in the park to try and digest all the informat', 'Very Positive', 93.69, 66.87, 0.62);
INSERT INTO reviews VALUES (46777, 1885750, 405, 'as usual with Cosmo D, came for the music and art and stayed for the pizza mechanics.', 'I bought this because I enjoyed all the other games in the series. This is totally different. this is essentially a digital board game, which is fine if you''re in to that. I am definitely not. I preferred the laid back "puzzle" and dialogue based romps through a cool setting, not this dice filled whatever. I hope no future releases follow this formula.', 'Overwhelmingly Positive', 97.04, 7.23, 0.13);
INSERT INTO reviews VALUES (46790, 1886070, 673, 'This game is absolutely stellar. It''s like the anti-clickbait. No matter what you think you''re getting, you''re getting that and more. I''d give this two thumbs up if I could.', 'The game doesnt explain jack shit, make 3 mistakes at panels, start the entire room over again. It took me and a friend almost 3 hours just to get around 4 rooms in, no monsters, just 2 rooms with turrets, thats it. THREE HOURS and we basically got NOTHING out of this game. And then all that while constantly maintaining power, health, etc. We eventually died to turrets, just to do that ENTIRE SEQUENCE AGAIN. DO NOT PLAY THIS GAME UNLESS YOU KNOW HOW IT WORKS.', 'Very Positive', 93.02, 10.05, 2.65);
INSERT INTO reviews VALUES (46823, 1887020, 128, 'Great game for only 2 people making this game', 'Instead of building the game since the EA release they continue to concept and overhaul it into different things. I feel like it isn''t the game I bought originally. Combat is SO clunky. When half the things you''re doing is fighting it should be smoother. Oh well. Loss on this one.', 'Mixed', 66.41, 14.90, 3.13);
INSERT INTO reviews VALUES (46841, 1887400, 2408, 'I would really like to play more of this game but there seems to be a bug where every time I open it I explode violently and my house is reduced to a smouldering pile of ash. Unfortunate!', 'It''s like Pizza Tower if it sucked donkey penis', 'Overwhelmingly Positive', 95.97, 24.42, 0.38);
INSERT INTO reviews VALUES (46853, 1887840, 8270, 'This game is phenomenal, and is the first action-adventure game I''ve been able to play in years without stressing myself out. For context, I''m disabled. My reaction time is significantly slower than these types of games expect you to have. Like I physically can''t move my hands fast enough in any accurate manner. \r\n\r\nSo imagine how I felt when I heard that Aggro Crab was making this game. I know from playing Going Under that their accessibility options are second to none. I downloaded the demo, a', 'I really kept trying to enjoy this game but I couldn''t. The character and vibe of the game is great, all the design and art.. my issue is with the gameplay. I can best summarize it as finicky. The parkour is finicky, the combat is finicky, the balance is very weird. I don''t think it''s a horrible game, but I really just wasn''t having fun.', 'Overwhelmingly Positive', 95.49, 59.48, 16.28);
INSERT INTO reviews VALUES (46864, 1888070, 117, 'I think i downloaded the wrong Luigi''s Mansion', 'I didn''t like it..', 'Very Positive', 86.32, 9.72, 0.33);
INSERT INTO reviews VALUES (46869, 1888160, 37337, 'I am bad at this game. It lets me dual wield shotguns and go fast. I die a lot. I didn''t hear no bell.', 'I have neither the patience nor the inclination to wage a steeply uphill battle against increasingly difficult bosses just to get a dopamine rush upon clearing said fights. I respect that others enjoy oppressive challenges, or have the time to develop the skills required, but I do not and there are no difficulty settings. It''s a shame too, the story looked fascinating.', 'Very Positive', 93.52, 13.68, 1.07);
INSERT INTO reviews VALUES (46913, 1889620, 340, 'add sex', 'I do not recommend this game, because it is not a one time purchase. Much like all of these AI story generators they are subscription based, so for the $10 price tag of the game you get access to the free model.\n\nTo get better image generation, story generation and even proper sounds you have to subscribe to their sapphire or silver model, which are monthly based subscriptions and it''s just like make the game free at that point.\n\nI would rather pay $60 for this game upfront to have a lifetime su', 'Very Positive', 80.59, 39.37, 0.48);
INSERT INTO reviews VALUES (46922, 1892030, 1440, 'Great Game But I hope They add a Actual Peace deal system because Ai never peace out with you and its super annoying having to pay millions to a country im winning against just to declare war on me again I think hoi4 peace deal system would work great in this game. I Also think alliances should be reworked into factions.', 'This game used to be fun, the last update killed it.  the game has become hard to read, hidden troop reserves, a national standing system that makes no sense. suddenly everyone is friends and you cant invade anyone.  your money constantly disappearing while you go get your university degree to work out where it went.  This game used to be simple, and fast. Now it is slow and makes little logical sense (like all of europe is at war with russia. you invade russia, now all of europe hates you becau', 'Very Positive', 86.46, 19.77, 56.65);
INSERT INTO reviews VALUES (46925, 1894430, 1263, 'People who say "jUST pLaY FAcToriO" haven''t actually played the game. Developer gives frequent updates through EA, more than can be said for 90% of EA games. Game has good content, killer soundtrack, and relaxed gameplay. Better still, the game price is scaling, meaning you don''t pay full price for a game still in development. Developer has also posted a public Trello where you can check in on the progress of updates and make suggestions. Insanely recommended.', 'I was holding off on giving this one a review because I figured they would eventually fix some of the big issues with this game. Issues including terraforming having literally no effect on your population/cities whatsoever, and not even being able to fully terraform the planet. However it has been more than a year and no visible improvements so at this point I kind of doubt anything is going to happen to improve these aspects.\n\nMy main issue with the game is that terraforming has literally no ef', 'Very Positive', 92.16, 85.45, 110.40);
INSERT INTO reviews VALUES (46930, 1895880, 5821, 'Insomniac doesn''t miss.  The Ratchet and Clank series is one of the best made and most fun video game series ever.  Highly recommend you play this and HIGHLY recommend Insomniac give us a massive Ratchet and Clank collection optimized for PC at some point.', 'As a long time fan of R&C - the magic is not here. Writing is extremely bland, combat lacks weight and the weapons are mediocre in terms of feel compared to R&C 2 or 3. Humour is basically non existent, all characters are perfect paragons with 0 charisma or edge. Can''t recommend, look great and plays ok but this game is EXTREMELY demanding on high settings with large jumps in FPS.', 'Very Positive', 89.88, 17.72, 8.63);
INSERT INTO reviews VALUES (46934, 1898290, 555, 'Enjoyed playing it with my toddler. He told me what to do, and I tried to comply.', 'it somehow manages to remove the creativity from a very creative hobby. you HAVE to do some puzzles in a certain way instead of your own and you''re zoomed in like shit!!! only get if free or under £2!!! better yet buy an expensive lego set irl, you''ll have WAY more enjoyment than this poorly executed game which had a good potential to be great.', 'Very Positive', 83.60, 17.37, 7.07);
INSERT INTO reviews VALUES (46935, 1898610, 209, 'Bought this because a) saw the sequel was coming out, and 2) it was only $5. This has been one of the BEST expenditures I have made! It''s worth triple the price- I haven''t had this much fun in an "old skool retro boomer shooter" for some time! Well worth the money- I wish I could pay MORE for it!', 'The levels are giant mazes. When I get to actually shoot something I like this game. Sadly that''s about 30% of play time at best. The rest is runnign around looking for the place you are supposed to go.', 'Very Positive', 87.56, 5.88, 1.78);
INSERT INTO reviews VALUES (46938, 1901370, 1341, 'I would recognise you in total darkness, were you mute and I deaf.  I would recognize you in another lifetime entirely, in different bodies, different times.  And I would love you in all of this, until the very last star in the sky burnt out into oblivion.', 'Very short, simple, boring. I think 12-16yo people will enjoy this game, who are easy to impress with a simple story.', 'Overwhelmingly Positive', 98.88, 2.87, 2.68);
INSERT INTO reviews VALUES (46941, 1902650, 122, 'Fun with friends', 'Need inverted mouse. Otherwise it is what it is.', 'Overwhelmingly Positive', 98.36, 0.28, 0.12);
INSERT INTO reviews VALUES (46942, 1902690, 1137, 'It''s good. It would have been better with a fully animated mana transfer scene with Saber, Musashi, and Iori but it was still good', 'I should''ve paid more attention to the reviews. I went in expecting a full musou game like Fate/Extella, especially since it''s from the king of musou games. Instead I got a visual novel with occasional single room musou-style fights.\r\n\r\nI''m about 10 hours in right now and it still feels like I''m in a tutorial. I find myself having a hard time giving this game my attention instead of just playing something else.', 'Very Positive', 91.64, 47.18, 9.83);
INSERT INTO reviews VALUES (46943, 1902960, 1983, 'This game is what you’d get if Yellowjackets, I Saw the TV Glow, Paper Girls, It, Stranger Things and Life is Strange had a baby.', 'This game''s opening is comparable to Skyrim in how slow it is, except Skyrim''s opening only lasted 20ish minutes.\n\nI''m 48 minutes in, and I just barely talked to someone other than the cat. This game is just...\n\nBoring.', 'Very Positive', 88.55, 29.58, 1.97);
INSERT INTO reviews VALUES (46944, 1903340, 45732, 'When 30 (!) French devs escape from Ubisoft to build their own game, they proved that the real issue with big studios isn’t lack of talent or heart, but horrendous corporate leadership.', 'I''m leaving a negative review purely so the devs can address accessibility problems with the game. I am mostly blind and lack of distinct prompts for dodging make the QTE events largely impossible for me to complete without a huge amount of dumb luck on my side. We''re meant to rely on sound effects and animations, but this window doesn''t feel consistent or well telegraphed to someone with a visual impairment. I can''t see the enemy animations well enough to determine what their pattern or timing ', 'Overwhelmingly Positive', 97.60, 91.83, 12.28);
INSERT INTO reviews VALUES (46945, 1903560, 260, 'So far it feels a bit uninspired and bland. Crab Champions far outpaces this game for gunplay and build crafting and its half the price. I''m hopeful they will add more but currently there is only like 10 perks you can even get in a run so it all feels pretty repetitive. It has good bones, if they can expand on it they will have a good game but currently it needs quite a bit of work before release. the bugs are manageable, its early access game afterall. But its not bringing a whole lot to the ta', 'With a first major update none of the core issues have been fixed. Solo is still borderline unplayable, most of the powerups you get either do nothing meaningful or not enough. You can only progress game with extremely specific build of best powerups, there is no room for improvisation, trying something new or just getting unlucky choices.\nFun concept, terrible roguelike part implemention.\n\nAs of April 8th: the game still runs like absolute crap - you may have 100fps, but it doesn''t matter becau', 'Mixed', 69.62, 7.57, 7.93);
INSERT INTO reviews VALUES (46948, 1904790, 245, 'Very fun game, loved it a lot. Only con, you can''t pet the cats :(', 'Practically all the changes with respect to the novel are for the worse, BY A LOT. The ending is downright baffling. It''s hilarious to me, the ABC murders was practically the perfect videogame adaptation, it barely changed anything and every change felt necessary. So why then has this saga never managed to just copy that formula?! YOU HAD IT. YOU HAD IT AND YOU KEEP MAKING IT WORSE! Hell, this is even worse than the other 2 too. At least those had better reasoning behind them. The changes to the', 'Very Positive', 85.31, 11.83, 11.40);
INSERT INTO reviews VALUES (46953, 1906020, 192, 'BEST GAME! We need Bon Jovi - It''s My Life!', 'I play drums, this aint it. \n\nYou can''t play past easy to medium songs because the hit detection, audio latency and even optimization ruins the experience. Spent an hour messing with the audio latency to try to get it workable but just never felt right. Gave up and just went to play the songs on a real drum set. It is impossible to get the visuals to sync with the audio.  I also experienced lag when a lot of notes were spawned in a row and im on a 4090... so that was pretty shocking and the litt', 'Very Positive', 89.58, 41.47, 1.03);
INSERT INTO reviews VALUES (46968, 1910860, 587, 'Start up game. Fight boss. Gets knocked away. Loses weapon and dies. Fight boss again with dagger i made. Gets thrown away lose dagger. Finds main weapon from last fight behind boss walking towards me. Runs dodges big attacks. Grab weapon  and continue to fight. Finally stagger boss. Kill boss.\n\nAbsolute cinema.', 'PS: This game is still being worked on i understand i think its amazing what they currently have i just wanted to share my opinion with the devs. Nothing against the devs.\n\nI was SUPER hyped for this game when it was in beta watching people playing it so when i heard it was fully coming out i was ready to buy it. It came out on sale so i bought it immediately. A little into playing the game i did not like the combat i feel like it was just stupid. Not the physics or damage the way it gets knocke', 'Very Positive', 80.24, 8.48, 1.63);
INSERT INTO reviews VALUES (46970, 1911610, 4084, 'Forget all the gameplay -even though it is one of the most satisfying gameplay ever- only for the music and sound design of the game deserves 10/10. Would make and sell another child again', 'This game is just okay. At the time of this review, there is not that much content or much replay value to be had. In only 25 hours I managed to unlock every item, weapon, and powerup, as well as clear the highest difficulty. Build variety is very limited as of now, especially if you want to play on the highest difficulty. Currently, I would say it is not that much worth it for the $25 asking price as you do not get much right now. Come back in 6 months or about a year to consider it when more c', 'Very Positive', 93.95, 23.43, 29.52);
INSERT INTO reviews VALUES (46972, 1911860, 123, 'Fun real-time-pause RTS/Roguelike with mech + ww2 aesthetics. Interesting meta-progression mechanics that revolve around loot drops, which can be fused to get better items if you are unlucky. You only control 3 mechs + your command vehicle, but it gets hectic enough managing that once all the enemy mechanics get layered in as you constantly have to watch your positioning, as various abilities will force you out of cover or advantageous positions. Nothing feels unfair. Pretty polished and tightly', 'To be honest, the game is just kind of boring. I really wish other reviews would stop comparing it to Into the Breach, about the only similarity is they both use robots in a small area. Gameplay and strategy is completely different, it''s not even turn based (although it probably would have been more fun if it was). It''s just real time drag your mech here, drag your mech there with some roguelite tree map flavoring. Not really feeling the gravity of when your mechs do or take damage, there''s no r', 'Mostly Positive', 78.86, 4.15, 0.32);
INSERT INTO reviews VALUES (46978, 1915380, 382, 'I love this game and it''s very easy to lose time playing.\n\nBut, that being said, it is extremely annoying to have a plant cap. Barely 10% of my garden is covered and I can''t plant anymore because the game tells me there isn''t anymore room. Especially when I have the whole Greenhouse a good 80% of the initial garden and across the bridge empty. And that''s in the story and creative. \n\nI understand needing to have somewhat of a cap on plants, but barely being able to cover the garden because there ', 'The only reason I don''t recommend this game is the flower quantity limit (I have so much open space left to fill but can''t due to the limit on plants I can have). Once they fix that and perhaps add some more interesting quests/expansion areas I''ll pick it up again.', 'Very Positive', 81.68, 22.78, 15.77);
INSERT INTO reviews VALUES (46980, 1915510, 127, 'First of all PLEASE check the dates on the top negative reviews, they are from a long-ass time ago in early access and seem incredibly unfair to the games current state.\n\nIt''s a fantastic little deckbuilder akin to slay the spire, this one has a beautiful art that''s a mix of stylized and traditional chinese, and the characters decks are far far more interesting than those in most other similar games, I''m really really enjoying the mechanics of the individual characters, they''re far more unique a', 'As much as I enjoy the art as well as some character/enemy designs in the game that look very cool and unique, I cannot recommend a game that blatantly copy other game this much and this obvious it looks just like a premium reskin version of Slay the Spire with some small additions\n\nI acknowledge that there are attempts to add something new like active skills and some character passive, still most of the game from UI layout, lots of core mechanics, systems etc. are the exact replica from Slay th', 'Very Positive', 91.34, 23.35, 1.88);
INSERT INTO reviews VALUES (46981, 1915550, 376, 'Its ok but not greatfull. You can not play solo with multiple characters which would balance the game to the intended difficulty and multiplayer with randoms are also not possible because there is no server to join. \nYou can not play with Nemesis 1 or Aftermath characters, with different species from Nemesis 1, his addons or Nemesis: Lockdown addons. You also can not play with the second board side. \n\nThis game is more developed as Nemesis: Distress but still bareboned compared to the boardgames', 'Not possible to play solo with multiple characters. This should be basic thing for the board games.', 'Mixed', 67.02, 9.90, 2.35);
INSERT INTO reviews VALUES (46997, 1920480, 566, 'Absolute cinema. More games with "slightly above indie" backing should strive to be like this.\n\nBrilliant presentation, art and music, solid movement foundation and combat, mesmerising combo system, pretty cool use of metroidvania world that doesn''t overstay its welcome. The only noticeable negative is probably the lack of proper netcode, you will feel the latency in its entirety when playing online co-op.\n\nWould absolutely recommend you play both games, they were hands down the best recommendat', 'WayForward announced Double Dragon DLC 2 years after the game was released, to be released in the summer of 2024. then they said it''d be 11/12/2024. that day came, and the DLC came out, but only on consoles. here we are a week later and still no Double Dragon DLC on pc. WayForward can suck my ass.', 'Very Positive', 86.04, 67.93, 40.83);
INSERT INTO reviews VALUES (47003, 1921900, 606, 'My secret word is Goblet.\r\n\r\nI truly enjoyed the gameplay loop of this game and that it put a different spin on their usual choice based games.', 'Secret word: shepherd.\r\n\r\nThe aforementioned witch never appears, we never encounter anything that''s mentioned to be a few feet ahead of us, we never see other wanderers or animals they chose to become besides the popular butterflies (that doesn''t mean they''re all butterflies), and the game keeps insisting its "secrets" require "exploration" when the rooms are tiny and you''d have to be blind to miss them.', 'Overwhelmingly Positive', 97.03, 11.72, 2.08);
INSERT INTO reviews VALUES (47004, 1922010, 941, 'VR R6, except no cheaters or broken abilities', 'AUS PLAYERS BEWARE this is another vr shooter with not enough players in aus and ping too awful to matchmake in us for it to be worth the purchase \nif your in us this is a good purchase tho this is a great game and i wish i could play it against real people and not bots', 'Very Positive', 84.48, 9.17, 3.08);
INSERT INTO reviews VALUES (47007, 1922560, 14722, 'in the backyard. straight up "planting it". and by "it", haha, well. let''s justr say. my peashooter', 'Loved This game but like everything EA does they find a way to ruin something you love and when you think they are done ruining it. EA just comes back and spits in your face.\n\nI Hate EA and I hope they sell off their IPs to other gaming company so I can buy a game knowing im not gonna get screwed', 'Very Positive', 91.84, 402.80, 0.27);
INSERT INTO reviews VALUES (47009, 1924400, 206, 'this game has such an immense amount of personality and charm. you can tell that the dev put a lot of effort and love into making it. are there glitches, some of which more game-breaking than others? yes, there''s no getting around that. at this point it''s up in the air whether any of those will get fixed, but i''d say it''s still worth playing this game anyway. even if you get a glitch that prevents you from progressing far, even the first one and a half dungeons still made me chuckle. and if we c', 'Overall, I do like this game. If you''ve ever seen that old D&D indie film "The Gamers" from 2002 it gave me similar vibes. Cool aesthetic, great music. However, I cannot recommend this in its current state as it has game-breaking bugs that will require you to restart entirely to ''fix''. For how long this game has been out, and for how long it has been since there has been any update from the dev, having bugs that bad still around is a bummer. I hope they can get them patched at which point I woul', 'Very Positive', 89.81, 4.68, 4.77);
INSERT INTO reviews VALUES (47014, 1927920, 148, 'Pretty solid simulator. Graphics are nice, and you can customize characters really well—make whoever you want. Movements look realistic, though there are some occasional bugs. Overall, if you''re into this kind of game, it''s worth checking out.', 'I honestly feel the studio should give up on simulators. Escort 1 dumpster fire. Escort 2 another dumpster fire, Real Feel is more like Feel this Migraine.\n\nThe quality sub par. The stuttering is off the charts. Moving the camera is like looking through a big blurry mess. I have RTX 3080TI and I run better games than this.\n\nThey have like this AI advertising of the models but the game is no where near that. It''s a big disappointment. I wanted to give them a try but after the other games that I m', 'Very Positive', 80.41, 3.37, 0.15);
INSERT INTO reviews VALUES (47017, 1928090, 222, 'fun game, nice art, nice voice acting. most of the negative reviews are from "hardcore" csd fans being dissapointed that this game that shares a name with csd is not the same as it. cook serve forever is not a sequel of csd and the gameplay is different. i have a combined ~150hrs in all of csd and still enjoyed the game even though its not as hard as them. if you want a difficult fast paced game. this isn''t for you', 'Too woke.', 'Mixed', 68.47, 47.73, 1.15);
INSERT INTO reviews VALUES (47024, 1931180, 1345, 'Man... This game is a tear-jerk when and one I hold personally close to my heart of all the 200+ games I have on steam. I remember back in 2017 I was working at a car wash, 21 years old, patiently waiting to play World Adrift as soon as I finished my $10/hr job. I was playing non-stop. I just loved Worlds Adrift. When it was announced that the game would be shutting down due to financial reasons with the world-hosting I was heart-broken. Desperate to play the game again. \n\nIn that time span, I h', 'So far, the game is just not playable, we''re doing a 3 man co-op, everything ship related is a mess, things get destroyed, glitch and all around don''t work, which is a major bummer when it''s the whole selling point.\nThe hook system is great though, minor tweaks and it would be fantastic!\nSo it''s probably a "let it cook" kind of deal.', 'Mostly Positive', 73.38, 33.40, 6.58);
INSERT INTO reviews VALUES (47033, 1934570, 1962, 'I miss the 2005-2015  games where they use to be linear with a little story trying to be unique in its own way, some magic tricks and a distinct vibe. This game takes me back to those times.', 'Not really that fun unfortunately. I do appreciate the art of the game. I do like that.', 'Overwhelmingly Positive', 95.06, 22.18, 4.62);
INSERT INTO reviews VALUES (47034, 1934680, 7879, 'This game should be considered as a golden standard for what remasters should be. Not only the graphics have been completely overhauled but the gameplay mechanics have been tweaked to allow gameplay that wasnt possible on older hardware. Population cap is now much higher and you can use powers nore frequently which allows for some crazy battles. The AI pathing is better, the game is well optimized so it runs smooth even at the highest settings on older rigs. I could not recommend this more.', 'Game is good, but the recent introduction of constantly online bs needs to go and is the main reason for my negative review. Failing single-player missions because your internet connection was unstable for 1 second is simply put moronic. If what I''m playing is done locally on my machine, then why the hell do I have to constantly be connected to a server?', 'Very Positive', 90.02, 61.08, 124.25);
INSERT INTO reviews VALUES (47036, 1936360, 109, 'Love this game.  My kids can rip me apart as big apes, much like they do in real life already!', 'This game could be fun, but it''s... really really bad.\n\nThe VR controls are unintuitive. Everything feels super clunky. If you''re experienced with playing VR games, get ready to unlearn everything you''re used to, because nothing makes sense in this. Maybe if you spent a few hours practicing the controls first, it might be fun, but you absolutely cannot just turn this game on with some friends who haven''t played it before and expect them to have a good time.\n\nMovement is horrible. To run forward ', 'Overwhelmingly Positive', 99.08, 7.65, 2.02);
INSERT INTO reviews VALUES (47039, 1937500, 1625, 'this game is so addicting. i love force-feeding my students mooncake n making them morbidly obese', 'The game repeatedly rearranges classes that are set in the class plans and screws everything up. it practically makes the game unplayable because every ingame year i have to take 1-2 real life hours just to fix what the game decided to screw up. I haven''t found a fix for this so i honestly might unfortunately just stop playing altogether.', 'Overwhelmingly Positive', 96.12, 88.72, 136.52);
INSERT INTO reviews VALUES (47041, 1938010, 3791, 'Alright...I''m going to be bias but I don''t care. I played this game when it officially release 2 years ago on Xbox Series X, and loved the game so much that I got 100% achievements TWICE!? on console and recently on PC. I really wish Koei Tecmo didn''t use EA as a publisher, this game was the perfect spin off Monster Hunter game like Saints Rows. If EA didn''t get their hands of this I.P, this game would''ve definitely pan out differently and got the proper support it deserve. This game died way to', 'I can''t in good conscience recommend this game to anyone at all.\nNot only was it abandoned after 6 months and never got the patches it needed to fix the technical issues, but now it''s getting a Switch 2 exclusive re-release that fixes the problems with the game and adds better multiplayer features while this version of the game that''s still FULL PRICE rots abandoned and unfinished.', 'Mixed', 56.50, 115.32, 65.25);
INSERT INTO reviews VALUES (47043, 1938090, 221511, 'if you want to spend 2 days deleting and reinstalling drivers, games, formatting drives and reinstalling windows. Then spend £70 to play the beta. ps COD HQ is the worst decision they have made.', 'Why do you combine everything into one launcher that breaks everytime you release a new game. Why can I not just launch MW2? Why can I not just launch MW3? I have never seen a game restart so many times before you can even play it. You guys are terrible. I''m done, i''m over it. I''ve played COD since COD 2. Congrats on destroying your franchise. Never again', 'Mixed', 57.94, 207.28, 524.40);
INSERT INTO reviews VALUES (47047, 1940200, 131, 'Thank you so much. I play this when I feel very upset and it immediately helps me. I really enjoy your game.', 'I bought the game to support the devs as I really enjoyed Chill Corner. This game isn''t bad for the price but this is a very EA game. The optimization is bad and there isn''t really a lot to do yet. A few bugs here and there but so far nothing game breaking. Buy this if you want to support the devs otherwise give it a year or two of development to improve on the areas it is lacking in. I look forward to future updates and will revisit this game and update my review in the future.', 'Mostly Positive', 70.99, 17.27, 12.62);
INSERT INTO reviews VALUES (47048, 1940340, 10018, 'Dear Developer,\n\nPlease rename the game to Darkest Road, and the Steam rating will go up. The game is fun, but it''s just very different from its predecessor.\n\nWarmest regards 🤍', 'I do have a bunch of issue with this game but this negative review I''m leaving has nothing to do with the game at all. For context, just read the Eula this game has...\n\n"...We also reserve the right, in our sole discretion, to terminate your access to all or part of the game..." - section 5. general access\n"...When you are using the game, the game may monitor your computer''s random access memory (RAM) for unauthorized third -party program..." - section 14\n"...we may terminate this agreement and ', 'Mostly Positive', 77.16, 18.08, 5.63);
INSERT INTO reviews VALUES (47065, 1942110, 583, 'I can use a pistol to do the following:\nShoot food\nShoot open coconuts\nShoot a campfire to light it\nShoot a torch to light it\nWho knows what else. That''s all I''ve been doing is figuring out what I can set on fire with a flintlock pistol. I''m sure I''ll enjoy the game when I actually start playing it.', 'I actually enjoyed this game a bit, but I’m going to leave a negative review. The game is fun, but the days are insanely short. It feels like the day barely starts, and you''re already hunting for rocks to start a fire. You can''t truly enjoy the game or explore if, just moments after the day begins, you''re scrambling to find two rocks. Please consider extending the day duration or allowing players to customize it. I can’t recommend this game until that’s fixed. There’s no time to relax and enjoy ', 'Very Positive', 84.22, 26.53, 3.32);
INSERT INTO reviews VALUES (47067, 1942280, 25340, 'Worst. Game. Ever.\n\nYou end up playing it for way too long. Every class sucks you in so you feel obligated to try and beat the game with it. Hate it. DO NOT BUY. You''ll end up regretting the hundreds of hours you''re likely to spend playing this game.', 'Very boring game with primitive flash games graphics, where you just have to run around a very small map and choose items and improvements at the end of the round. There are games with similar gameplay much more interesting and yet free. Also this game breaks the hdr on my monitor and I have to restart it through windows and monitor settings.', 'Overwhelmingly Positive', 96.74, 891.68, 0.17);
INSERT INTO reviews VALUES (47069, 1943950, 29526, 'Really good. Buy it. Spend all of your money on this game. Buy it for your friends, your parents, your grandparents, and even your dog. Make more steam accounts and buy it on all of those. This is an S tier game full of fun levels and (sometimes) horrifying scares. This will give you and some friends at least 14 hours of awesome gameplay.', 'Lying dev. Game is completely abandoned\n\nSpeaks for itself / Note: The last update made by the developers was over 15 months ago. The information and timeline described by the developers here may no longer be up to date.\n\nApproximately how long will this game be in Early Access?\n“I''m estimating around 3-6 months.”', 'Very Positive', 90.30, 48.65, 11.70);
INSERT INTO reviews VALUES (47073, 1946700, 505, 'Too many layers, not enough fear.', 'Lots of design choices that are at odds with each other. Like there are plot decisions you make by choosing which direction to walk in and it''s not always obvious when you''re making these decisions. That would be fine, except there are collectibles, which motivate trying to explore the entire level rather than being deliberate about the direction in which you are heading. You can''t reload old saves, so you can''t undo decisions made by accident.\n\nThe thing that finally made me rage-quit was the t', 'Mostly Positive', 78.02, 1.12, 6.97);
INSERT INTO reviews VALUES (47077, 1948800, 390, 'Important tips for the new:\n\nThe user agreement only applies to people in China. It doesn''t appear at all unless you started the game in Chinese.\n\nThere''s a way to insert cards, which is explained in a loading screen tip, but I''ll repeat it here. To insert a card, hover it over the slot you want it in, and wait for the other cards to shake, then drag it slightly left or right to indicate which way to push the other cards, before releasing.\n\nThere''s a lot of guides you can read, and many of them ', 'game suck', 'Very Positive', 91.03, 2067.15, 206.40);
INSERT INTO reviews VALUES (47090, 1954160, 429, 'Hello all,\nThis is my first and only review......I have read many of the others and I just want to say that this a a great game with a sing;e developer who is addressing all the bugs faster than most. I do not know why they chose full release versus early access but either way, they do not deserve negative reviews while working diligently everyday to addressing all known issues in the game. This game is a one of a kind in its genre and with a little patience, the potential and the ability to rep', 'Cannot recommend the game as is. I bought this under the assumption that it was a fully finished game, as it isn''t marked as an early access game. As of right now, the game is unfinished and buggy, and has issues with basic things in the game, like the tutorial quest and basic game functions. Please save your money for something else. I''d be more forgiving of the game, but seeing as it was marketed as a fully finished game and not as an Early Access game, I can''t help but feel that I was ripped ', 'Mostly Positive', 74.59, 30.70, 8.77);
INSERT INTO reviews VALUES (47092, 1955340, 115, 'Buffs need to be more impactful, I felt just as helpless as I was from the beginning till the final boss. Only a few actually have any worth, the rest just make you go: "Better than nothing I guess."\n\nDon''t know if it''s intentional, but the color choice as well as the color of the environment really makes it hard for me to actually see the enemies on screen. The highlight features in the option barely help.\n\nSo far, I would give a Get it on sale recommendation. Should be fun for a few hours.', 'It is going to be great if only I don''t have to switch between shooting and constructing.\nAnd the difficulty is rising way too fast than it should be(or maybe it only happens in multiplayer).\n', 'Very Positive', 88.70, 6.48, 4.55);
INSERT INTO reviews VALUES (47096, 1957760, 108, 'Game is not done yet (hopefully). Missing a lot of polish and some significant bugs. One of my main gripes is I can''t have more than one train. This makes no sense to me in a game called islands (I can definitely build multiple islands) and trains (but I get only one?). Should be called "Islands & Train". Hopefully that will be fixed. Another complaint is certain pieces can''t be mirrored, like switches. Therefore, you have to plan track layouts carefully because you only have one orientation of ', 'I was really excited to get Islands&Trains since my son and I enjoy playing Tiny Glade and Train Valley, and this game seemed perfect for him. Unfortunately, the controls and building mode are quite awkward and complex. For instance, you can''t simply swap train tracks with certain elements; instead, you have to switch modes, remove the existing tracks, and then place a different type of track that serves the same purpose but looks slightly different. I also expected some automation for the train', 'Very Positive', 85.19, 4.70, 3.98);
INSERT INTO reviews VALUES (47097, 1957780, 6776, 'my very first raid:\n\nI load in with an m4 and a makarov, with a friend. Friend does not have any guns.\nFriend proceeds to grab makarov out my holster and shoot me in the head, then turn the gun on himself.\n\n\nVery good game im addicted to it', 'The fact that this developer would rather make more DLCs to milk more funds from people rather than fixing the issues presented by multiple players is pretty crazy', 'Mostly Positive', 74.26, 25.43, 69.78);
INSERT INTO reviews VALUES (47098, 1958340, 474, 'This game might be just a little stupid, if not full of complete bullshit.\nSome of the builds i''ve made in the past are insane and broken completely and would normally be nerfed. (but the dev is based as hell)\nOne of my runs the enemy leader just like died of a heart attack after one of my cubes dealt/took damage. I cant even explain it correctly thats how weird it was.\n10/10 would cube again', 'overly complicated, I like tug of war battles and the idea of making nerdy trigger type combos, but it''s too much. feels like it would actually be better if it were a bit simpler.', 'Overwhelmingly Positive', 95.99, 50.87, 18.75);
INSERT INTO reviews VALUES (47101, 1960480, 253, 'Now it''s time to spend all of my time on this game...\n\nafter 17 hours: the game is great and I don''t want to do everything in early access. bcs of that, I uninstall it, till getting release version', 'Good game. I like the base building, tech tree, working out how to make my base more efficient. Only thing that sucks is 1 save point per game. Just had an invasion come in where i have no defenses. Alien kills me in 2 shots. Trashing my base, So i goto exit.... save and exit. i guess i could alt f4 out and try to reload at an earlier pt, Multiple save points per game would be nice, else every game is iron man. 6 hrs of game down the toilet.', 'Very Positive', 89.33, 17.13, 58.85);
INSERT INTO reviews VALUES (47102, 1960900, 214, 'Beautiful unusual art style and plenty of loveable characters. Short run time that takes good advantage of the the medium and length. Wishing the devs the best with their future work!', 'Where did the BABY GO?!? Bad coding, now I have to start the whole game over. Not sure I want to.', 'Overwhelmingly Positive', 98.60, 5.08, 1.70);
INSERT INTO reviews VALUES (47103, 1961600, 224, 'Played through the first two missions of the campaign (so far), but I gotta say I''m enjoying it quite a bit. It really scratches that Warcraft itch.', 'It''s like a rudimentary version of Warcraft 3 mod that focuses on hero/RTS mashup - except the hero talents are narrow in scope and boring, and the RTS/basebuilding elements are poorly implemented and boring. You tech up in a very narrow, uninteresting way, and building up large armies is annoying because of poorly executed mechanics (lag, terrible pathfinding, poor QoL for clicking and commanding units, etc). It''s a lot of eye-rolling and unevenly paced missions that''ll put you to sleep.\r\n\r\nSom', 'Very Positive', 80.36, 3.22, 21.23);
INSERT INTO reviews VALUES (47108, 1962660, 3640, 'Dispite all the bad reviews, I disagree with every one of them. For starters, Infinity Ward finally tried the mil-sim style and it worked. The slowed movement essentially got rid of every single sweat. No slide canceling, no YY movement TikTok wannabe. It makes the game so much more fun for the casual community. The gun play is fantastic as well. I''m sure there will be endless whining from the community over the hefty recoil, but I like it. It aids to the mil-sim type of game play Infinity Ward ', 'Go F yourself activision, your franchise got so boring that people out of your development team was making a mod that the community was enjoying and you guys shut it down AGAIN (they shut down an other project called SM2) you guys will do ANYTHING but make your community happy, instead, you guys will add more stupid ass bundles and events ingame to try to make people forget about the problems that you created', 'Mostly Negative', 20.96, 0.00, 0.00);
INSERT INTO reviews VALUES (47109, 1962663, 4661, '400 gigabytes download just for some little kids calling me racial slurs. \n', 'Engagement Optimized Matchmaking, AI Generated content that varies from PURCHASABLE BUNDLES to maps, calling cards, and voice actors. This game is a breach of Steams Terms of Service.', 'Mostly Negative', 25.83, 0.00, 0.00);
INSERT INTO reviews VALUES (47111, 1963040, 184, 'It''s a good game to play if you want to chill and feeling burnout after playing an intense game. This game combine elements of some other games like vampire survivor, tower defense and city management. The Micro management can be quite heavy and detailed but not really punishing (unless you played on purgatory difficulty). And the only downside of this game is as the other reviewer said, game is not fully translated and can be quite confusing at times but not on the state of unplayable. Dev also', 'TLDR: If you hope to be able to play the game in English, do not buy.\n\nI hesitate to write negative reviews based on opinions. But The Lost Village is unplayable for an English speaker due to the inconsistent and poor translation. It is not just minor grammar issues - entire concepts change meaning. They said a large patch would be fixing the English early this year, but I can''t imagine it was worse than it is now even if it simply had no translation. This is around nine months post full-launch,', 'Mixed', 64.13, 90.00, 3.00);
INSERT INTO reviews VALUES (47112, 1963210, 427, 'I understand the disappointment of the fans of Valkyrie series. \r\nEven if it''s not close to its true origins, Valkyrie Elysium is still a fun game.', 'weak\nthis game has sacrificed everything that made the games that came before it good in exchange for a mediocre action combat system where the most difficult enemies are the lock on control and the camera \nif you''re a fan of Valkyrie Profile avoid this like the plague', 'Mixed', 63.93, 27.42, 11.65);
INSERT INTO reviews VALUES (47113, 1963370, 2155, 'Almost to 600 hrs in. Great Game. I don''t understand all the bad reviews from people who''ve hardly played. Give it a chance before you bash it. There''s a lot to do and a lot of content. Updated often. Plenty of game play options. If I want to chill, I''ll work around the base and build stuff. If I want to get my ass kicked, I''ll go find a bunker. Bandit camps are fun. Also a great price for a game this loaded with content.', 'Haven''t played in quite a while and kinda forgot I even had this game but after reading about the recent update wiping saves and paid DLC for a unfinished game, I can not recommend this game. I will not recommend any EA games that release paid DLC for unfinished games.', 'Mixed', 66.96, 696.92, 28.43);
INSERT INTO reviews VALUES (47114, 1964200, 134, 'cute and addicted a little but the fact that the game has a time limited skins are disappointing.', 'It''s... better than the first one? Which admittedly is a low bar. But it also is the most positive thing I have to say about it.\n\nOverall there are many better deckbuilders available. That''s it really. This one does nothing great.', 'Overwhelmingly Positive', 95.52, 8.85, 0.82);
INSERT INTO reviews VALUES (47117, 1966720, 266222, 'tbh i play this alone since i actually have no friends, but its still fun. yes its harder and sometimes impossible but that doesnt make the fun go away. i enjoy every bit of the game and the updates are worth it', 'Dev abandoned the game after making millions. Still listed as early access despite no major content updates in over 6 months with patches being changing a few values in code. Game is still buggy and incomplete. Fun with friends but there is only so much fun you can have until your experienced everything it has to offer.\nIf the game receives the care it deserves from the dev maybe my thoughts will change but until then I can''t recommend supporting this developer.', 'Overwhelmingly Positive', 97.53, 10.77, 89.47);
INSERT INTO reviews VALUES (47118, 1967430, 1686, 'Just bought this for the small chance for Takumi making a new game, this game is my life\n\nJust an unpretentious silly game made by a guy who wanted to make a game for his beloved dog\n\nRest in piece real Missile, you will never be forgotten', 'Removed DRM and then re-added a different DRM for some reason.', 'Overwhelmingly Positive', 97.92, 35.55, 2.77);
INSERT INTO reviews VALUES (47120, 1967630, 1512, 'This is a game where you can leave your real life house and go and live on an island, hunt for food and travel the seas all in your own time. Living on an island for 206 days, built a complete wooden fenced compound with all the carpentry, tanning, drying, building benches. There is more than enough food to find on the island of hope, you learn quickly enough that you can overstock very quickly. Spend my time collecting different seeds, flowers, stones, twigs, long sticks etc on different days b', 'Interesting concept but it feels unfinished. Though the biggest problem for me is the whole ''skip time'' thing. ''Oh you want a stick from this tree, you''ll have to just skip an hour of the day while it magically appears in your inventory.  I tried to play last year and was hoping they would change that system, but nope. You want wood? Go up to a tree and tell it how much wood you want. the more wood, the more time it just skips. Want to craft a bow and some arrows? just skip a few hours..... No a', 'Very Positive', 84.66, 603.18, 6.43);
INSERT INTO reviews VALUES (47123, 1968340, 603, 'Very satisfying. My ONLY complaint is that there are far too many pointless zombie missions and not enough actual scenario missions. Zombies should be a minority of the content.', 'Controls are weird, game is too confusing (no directions on what to do and the enemy almost never shows up), and the game keeps crashing. Angel of Death (Demo) is much better and easier to play than this. Will wait for substantial improvement before re-buying this.', 'Mostly Positive', 79.10, 78.65, 0.37);
INSERT INTO reviews VALUES (47135, 1975280, 261, 'Dude this guy''s girlfriend a total loser! She doesn''t cook, Doesn''t bake, looks pretty crappy, doesn''t clean, doesn''t clean the dishes...even not her own. The only thing she has going for her is that she has the biggest boobs of the girls in his circle. The guy (main character) could totally do better than this!', 'I''ve uninstalled this game, mostly because I have no disk space and I''ve finished it as well. However, the game does not seem to want to stay uninstalled. It keeps saving one folder that has a persistent.file in it. How can I permanently remove the BTW files without them rewriting the files back into the steam folders?\n\nEDIT: I have since removed it by removing the permissions from the folder. Even if you uninstall the game, BTW gives Full Control to its game folder preventing a complete uninsta', 'Very Positive', 86.21, 86.73, 24.73);
INSERT INTO reviews VALUES (47136, 1975580, 362, 'I tried the demo of this game a few years ago, shortly after looking for something similar to Unrailed. My wife and I joined the creators'' Discord and followed every game update, rooting for its release.\n\nThe game is very fun and easy to play, besides being super cute. For anyone who enjoys couch co-op, it’s fantastic.', 'As much as I loved this game and I really did enjoy the 2 hours I almost played I can not recommend this game in the current state there is just so little content as of now I defeated both bosses that there is in the game and it was sad to see that was all it had to offer and yes I know it is early access but this feels more like an alpha compared to early access some opinions might differ will defs pick it up again when it had some more updates really fun game but like I said it does not offer ', 'Very Positive', 82.32, 3.17, 1.88);
INSERT INTO reviews VALUES (47137, 1975670, 161, 'its like if dark souls was good', 'Got hardlocked in plant pot village and I can''t progress. Other than that the game is really good, what a shame.', 'Very Positive', 92.55, 2.20, 3.12);
INSERT INTO reviews VALUES (47144, 1978720, 225, 'VERY fun and good\r\nstilll dont know how to connect with freinds though...\r\nstill 10/10 game highly reccomended', 'i hate this game im going to refund\n', 'Very Positive', 84.89, 4.50, 9.82);
INSERT INTO reviews VALUES (47149, 1982340, 407, 'Doomed yuri for furries', 'extremely laggy, wack camera, also installs random software without telling you.\nunfortunate, because the idea is extremely cute and the art looked adorable! it feels like it needs more work :(', 'Mostly Positive', 74.94, 1.18, 0.40);
INSERT INTO reviews VALUES (47152, 1984020, 1506, 'After 10 minutes and 34.57s, this game has given me\r\n- Temporary confusion\r\n- A staring spell\r\n- Stiff muscles\r\n- Uncontrollable jerking movements of the arms and legs\r\n- Loss of consciousness\r\n- Psychological symptoms such as fear, anxiety and deja vu', 'Not a bad game, rather disappointing considering how good first game was. Game is too repetetive with fighting the same enemies and beating them the exact same way, wave of enemies sections are probably the worst. Gameplay is still good but basically everything was done better in previous game.', 'Mostly Positive', 73.51, 7.07, 10.23);
INSERT INTO reviews VALUES (47156, 1985050, 177, '   This game, while being actively tweaked by the devs continuously, is sheer genius.  While it looks simplistic at first glance, there is a LOT going on under the hood. If you like games with a lot of complexity and requiring some deep thought and contemplation, then you want to pick this one up even at full price. If you have played its predecessor, Field of Glory: Empires, you will notice a lot of new changes that will increase your interest in the game. Trade, Prestige, Dynasties, have all b', 'A wise man once said that an idiot admires complexity while a genius admires simplicity and I''m inclined to agree and so, I feel, does the creator of Field of Glory: Kingdoms - a game which, at first, appears to be as basic as they come, but with time reveals its depth through systems that have been carefully crafted to intertwine delicately, forming a synthesis that culminates in an addictive and interesting grand strategy game. There are very few levers with which you are able to manipulate th', 'Mostly Positive', 79.66, 313.73, 32.98);
INSERT INTO reviews VALUES (47159, 1985930, 289, 'Grim, sinister and sombre atmosphere. Overall, disgusting feeling to be involved in what''s happening in the storyline. It leaves a sour aftertaste in your mouth upon completion. \n\nThis game has barely any connection to The Backrooms concept, other than the title and the idea of no-clipping into a different place, which in this case is a purgatory, that protagonist is going through for what he did.', 'Pretty antithetical to the Backrooms to have a story and things within them; also extremely jumpscare-heavy which is again not the point of liminal horror.  In those jumpscares, most are just annoying and cover your whole screen.  There are a handful of subtle ones which were surprisingly decent, but the rest are Youtuber bait un-apologetically.  There could be something here with the paint system to be honest, having other player''s write messages or draw icons to direct people towards points of', 'Very Positive', 82.01, 1.92, 0.75);
INSERT INTO reviews VALUES (47165, 1988540, 612, 'Some very, very good solitaire games, with the exclusive Fortune''s Foundation being my favourite.', 'I really want to like this game, But when I play a puzzle game I want to "Solve the Puzzle!", and there not being a ''Restart'' or ''Retry'' option is painful. The game has been out a while so I''m sure it''s part of the developers philosophy rather than a feature they haven''t thought about, but it still makes me feel like junk.\n\nGreat game, but don''t get it if you were a kid who hated failing a test.', 'Overwhelmingly Positive', 98.86, 134.93, 2.75);
INSERT INTO reviews VALUES (47167, 1989070, 265, 'Nice artwork and design, mellow music to build to.\n\nSerious negative is all the other audio - there is very little of it. No sounds from people working, buildings, creatures, wind etc it''s a very empty audio space. Hopefully a QOL update somewhere along the way fills out this aspect.', 'Last major patch was a step in the wrong direction. Having pinnacle research buildings that exchange resources for nothing that has any real impact on moment to moment game play is not fun or engaging, its a major grind. \r\nThe charm of this game comes from molding, changing, and working with the environment around you to help you survive in a harsh environment. Constructing a library that uses a tier 3 resource to make the culture bar go up is something you would expect to see in a game like fac', 'Very Positive', 83.77, 2.15, 59.15);
INSERT INTO reviews VALUES (47169, 1989270, 17553, 'Take a sniff of The Stanley Parable, a hint of Doki Doki Literature Club, and stir it in a Lovecraft pot.\n\nBeautifully horrific, doing things with the visual novel engine that I have never seen before, and a really good story.', 'I don''t really get this one. Some paths are interesting, and whenever you actually get pertinent information can feel cool, but it fails to stick the landing and loses a LOT of its luster on the third go around and beyond. Whether or not the mystery is fun to unravel, once it is unraveled (in a long exposition dump) it becomes clear that the game doesn''t actually have much to say that hasn''t been said before in a thousand different ways. It''s a basic game stretched to its very limits and made my', 'Overwhelmingly Positive', 97.43, 8.12, 3.72);
INSERT INTO reviews VALUES (47174, 1990110, 807, 'Fun game! It''s Slay the Spire but easier. Fun, relaxing, has enough depth to keep you coming back for another round', 'For me, the core gameplay loop is just kinda slow and boring. The deckbuilding feels really constrained, the meta map is bland and rolling dice and hoping for getting the numbers that you want is pretty meh.', 'Very Positive', 89.34, 70.13, 7.25);
INSERT INTO reviews VALUES (47179, 1990740, 143, 'Aku Pemburu Untuk Achievement!\r\n\r\n7/10', 'Barro is a series of eight copy/pasted, generic racing games. The car controls fairly poorly, and there''s no drifting so turning is clunky. There are no powerups or any interesting extra features. It''s the absolute bare minimum for a racing game - just go around in circles on a track. The tracks, while shaped differently, all use the same assets. The only difference between any of these games is different cars and tracks - they all use the same sound effects, menus, game modes etc. They really o', 'Very Positive', 82.52, 2.75, 3.27);
INSERT INTO reviews VALUES (47185, 1995520, 2729, 'Fun but no way would I pay a subscription in it''s current state the game is no where near complex enough.\nAlso there are many bugs and server issues, I wouldn''t buy into the game just yet wait for full release unless you''re happy to pay to be a tester for a game that may or may not be great.', 'There is nothing on the store page saying that when they release the full game you have to purchase it again and pay monthly. (you have to go to other website to find out) hell no, i want my money back! Lot of money to drop on a game and DLC for an early access and you don''t even get to keep it. Another money grubbing company ruining games.', 'Mixed', 58.48, 190.00, 17.30);
INSERT INTO reviews VALUES (47186, 1996010, 4061, 'Not to be overly reductive in my description, but this is a good baby''s first Silent Hill, minus the "deep" plot. The puzzles make sense, there''s a generous hint system and the item drops seem to be dynamic, meaning you''re always finding the ammo that you''re lacking. It''s also not that hard to dodge the enemies altogether. The controls are also a nice departure from the regular survival horrors - you _can_ use tank controls, but there''s also a modern control scheme with relative movement and rot', 'Not a bad game but I think it is a bit overrated. Won''t recommend it at full price but if you can get it for 10-15€ then yeah.\n\nWhy? Because the gameplay feels average and the length is on the short side. The puzzles, combat and story felt ok, passing grade, but I''ve seen a lot better. Tormented Souls for instance has the best puzzles I''ve seen in a survival horror game and it is the same price. The only thing this game does exceptionally well is its aesthetics, and it should be applauded, but p', 'Overwhelmingly Positive', 98.35, 5.58, 8.97);
INSERT INTO reviews VALUES (47190, 1996770, 337, 'It easier to explain my love of Turok 3 by reflecting on the first two games and the tedious problems each of them had that Turok 3 does not. Turok 1 mostly only suffers from two issues it''s clunky platforming and terrible secret locations to hunt down. Lots of the secret locations are behind fake walls you can pass through, some with no way of knowing you were supposed to check said wall. Others so insane there are secret walls within the secret walls! Sometimes even lava pools you must dive in', 'My main problems don''t lie with it being a bad remaster, Night Dive hit it out of the park. My problems with this game are; it feels very rushed compared to the other Turok games, a lot of janky animations with characters during cutscene, and the combat doesn''t feel as rewarding as the other titles. The game is focused on a much more linear approach to level design which can be good in many cases, but its way too linear in most of the time.', 'Very Positive', 86.65, 9.58, 4.43);
INSERT INTO reviews VALUES (47199, 1998530, 236, 'A very cute game and very funny!!\nI want to kill myself.\n\n⑨/10', 'Art is cute but the grazing tutorial doesn''t work???', 'Overwhelmingly Positive', 99.58, 2.62, 0.25);
INSERT INTO reviews VALUES (47216, 1999170, 256, 'Fun "vampire survivors" type game without the roguelike element. \r\n\r\nGood game to just chill and shoot some bugs. You can scale your ship insanely high so if you like some grinding this would be a good one.', 'It does not run on steam deck and should not be verified. It use to run years ago on release but has been broken for some time. The devs do not respond. If you want it on PC it''s ok, but I got it for the deck. It broke and they never fixed it or acknowledged it. Stay away', 'Very Positive', 87.89, 27.35, 7.27);
INSERT INTO reviews VALUES (47218, 1999520, 252, 'A super fun 2D puzzle platformer built around the buttered cat paradox meme. \n\nIt’s pretty common to see games built around a fun meme or image, but it’s rare to see one executed so well. Some of the puzzles in this game are really impressive. Plus the cat is cute and will meow if you press R. \n\nTotal gem. I need co-op mode.', 'most puzzles don''t make sense or are way too easy', 'Overwhelmingly Positive', 99.21, 6.83, 14.27);
INSERT INTO reviews VALUES (47222, 2000890, 3651, 'What a beautiful game.  I''ve read a lot of complaints about writing and acting....  These complainants have never read the "Blood of Kerensky" trilogy, for if they had, they would understand how close this game is to the lore expressed there.  This is the story of warriors bred for war, not looks.  Making the models ugly and gritty added to the flavour that these characters had fought since being "birthed" from their "Iron Wombs".  Yes some of the character animation was janky.  Mostly when the ', 'I really wanted to like this game but I''ve gotten frustrated more times then i can count playing it. \n\nI can get past the uncanny valley that is the face animations in all of the cut scenes. The story is good enough. There is a noticeable lack of options when customizing mechs which is frustrating and doesn''t make sense imo. Its been in so many other games why not this one? The new mechs are alright i guess. Some of them just look like walking boxes. \n\nBut the biggest issue i have with this game', 'Mostly Positive', 74.69, 35.87, 38.55);
INSERT INTO reviews VALUES (47223, 2001070, 700, 'I try to stay impartial and just factually describe a game in a review, but I REALLY enjoy this game. I''ve owned it for 60 hours and I''ve got 43 hours of play time. So uh... Yeesh. Honestly that by itself is the best recommendation I can give it. There was just a moment when I was hacked into entering a forever war with cultists and slumlords while aliens carpetbombed the region and my units were ambushed by the remnants of all those genetically engineered super velociraptors that we accidentall', 'I was eagerly awaiting this game for months based on the promo text. It sounds right up my alley. However the early game is thematically all wrong. The player is supposed to be laying low and gradually building up power under the noses of the humans until it’s too late to stop the new AI overlord. And yet, the game opens with gunfights against humans right away and you build a giant evil villain tower for all the world to see? When you agro hostile humans, the shoot at you for a like a day but t', 'Very Positive', 93.57, 95.98, 4.78);
INSERT INTO reviews VALUES (47225, 2001340, 188, '1st game: "You are below 50%hp. Would you like to commit a war crime to win instead (Y)/(N)?"\n2nd game: "You are below 50%hp.   Automatically loading child into soul cannon.  Initiating countdown sequence to fire in 20... 19... 18... ', 'The game is just too alike the first game to be fun for me. I don''t expect a lot of differences in a sequel, just enough to keep it fresh. But even the progression systems and leveling systems were the same. It really just felt like I had reset my save of the first game and started over.', 'Overwhelmingly Positive', 97.87, 102.70, 5.42);
INSERT INTO reviews VALUES (47229, 2002570, 199, 'An OK time-passer global shipping simulation. This a logistics game, no actual ship navigation or controls are involved. Buying ships and acquiring contracts to move cargo from Port A to Port B is pretty much all there is to it, and most of the game occurs on a simple map of the world. Every contract has a value and a "deliver by" date. Multiple contracts can be combined into one journey, the ship''s speed can be changed (at the cost of fuel efficiency and eco-rating) to meet contract deadlines, ', 'This game is okay for $10, not whatever the non-on-sale price is.  The UI is bad. There is a map UI and multiple menu UIs, when you use one it effects the others... The game has features that mean nothing. You can buy a ship and customize the colors but you never ever again see the ships and whatever colors you chose dont reflect on the map. But if I had to say what the worst part of this game is, it is undoubtedly auctions. They built in an auction system where you can buy used boats for way le', 'Mixed', 59.30, 63.42, 31.00);
INSERT INTO reviews VALUES (47242, 2008100, 562, 'the aluminum superstructure refits of 1940s heavy cruisers will continue until shipyard capacity improves', 'Spreadsheet simulator.\r\n\r\nIf you like spreadsheet simulators, this game is for you, but I couldn''t really get into it.', 'Very Positive', 89.68, 54.80, 0.48);
INSERT INTO reviews VALUES (47244, 2008920, 1547, 'It''s like if David Lynch made a puzzle game that is structured like Resident Evil, but without the zombies.\nThe puzzles are really well designed. Pen and paper is basically required and is one of the reasons it''s so good.\n\n', 'Seriously, where the hell is the back button? Ruins an otherwise very enjoyable game, navigating the menus is just an absolute nightmare.', 'Very Positive', 94.38, 35.00, 8.45);
INSERT INTO reviews VALUES (47248, 2010030, 347, 'I have been playing the game for quite some time and genuinely enjoy it. While the progress can feel slow at times, it gradually improves over time. Even though the day-to-day tasks may feel repetitive while working toward a goal, the experience remains engaging and enjoyable. However, by the end, it feels like there’s something missing. That said, I view this as an opportunity for future updates, such as adding features like a stock market, additional entertainment centers, or new job options. ', 'I had this game refunded, it had been on my wishlist since even before it came out, but honestly? I am extremely disappointed and I am quite surprised at the amount of loved reviews for this game.  The graphics are okay, and all.  But: you can''t zoom on the map, you can''t set up in any way to have a form of direction to know where you need to go for a mission, even after placing all the furniture in the first mission it doesn''t register that you''ve placed the furniture.  I hope it might get bett', 'Mostly Positive', 79.25, 456.75, 0.18);
INSERT INTO reviews VALUES (47254, 2011780, 968, 'Despite this game''s overtly silly appearance, It''s actually an extremely well made collect-a-thon with some rather complicated & tech-based movement. Highly recommended if you want a N64-style collect-a-thon that doesn''t have a serious bone in its body.', 'While it may be partly my own fault, I can''t help but view Yellow Taxi Goes Vroom as anything other than an unfulfilled promise. See, I really like 3D platformers, especially collect-a-thons, but have not found myself with a burning desire to play many of the newer releases in this particular sub-genre due to the fact that they, for the most part, tend to lack enough novel ideas to really differentiate themselves from one another. So when I first saw Yellow Taxi, with it''s main gimmick of having', 'Overwhelmingly Positive', 98.14, 15.48, 5.50);
INSERT INTO reviews VALUES (47255, 2012190, 252, 'Bought it as soon as I noticed it was released - this was the game that I''ve been waiting for, the culmination of my Grand Strategy, City Building, number go up, Interbellum starved gaming brain.\n\nI didn''t regret it, and I do recommend buying this game, but only just. With the tutorial and an early game city under my belt I can safely say that this is a fun game for fans of the genres, and it has a lot of innovative gameplay elements that definitely sets it apart from other games. Information ab', 'I really wanted to like this title. I think that the setting is very cool. They might be able to fix performance issues and make the UI more user friendly. However, the game core mechanics are deeply flawed. \nI don’t think there is enough strategizing here to make the game fun. Your job as a player is to set up every single production chain and that’s about it. Optimising these chains is not really necessary or rewarding. Trading mechanics feel tacked on. The global war feels very sluggish. Fina', 'Mostly Positive', 74.21, 3.47, 22.18);
INSERT INTO reviews VALUES (47258, 2012510, 1047, 'Having an absolute blast playing.  So far favorite thing is how user friendly the macro is in comparison to other RTS like starcraft.  I am a casual at RTS so being able to micro my army while building units at the same time without individually clicking buildings or spam camera swapping is amazing.  Auto control groups sends units as soon as they are produced to groups 1 (all units), 2 (ground units) and 3 (air units).  Things like the building tab to select any structure without having to find', 'I can tolerate the nightmare inducing faces that represent a human''s, a rehashed Warcraft III campaign (but instead of Arthas getting a cursed sword Amara gets a fidget spinner), and Celestials dominating the ladder. The straw that broke the camel''s back: I a-moved my scout (Vanguard dog unit) to kill an Imp (Infernal worker) and instead of attacking, it just floated while trying to bite a fleeing unit. That and you literally have an ad for "GearUp Booster" in the game''s description (as of writi', 'Mixed', 66.57, 153.52, 11.73);
INSERT INTO reviews VALUES (47262, 2014380, 300, 'Unlike most JRPGs, which have very long linear stories, this game has several shorter stories that you can play in whatever order you want, which is unique. Perfect if you want to play a JRPG but don''t have a ton of time. I also love this game''s depiction of hatred. It is so accurate, it''s almost biblical: no matter where you are in history, hate will always be there, and it''s a never ending battle, yet you can''t give up nor allow it to consume you. If you''re a JRPG fan and you''re looking for a ', 'Live A Live has a similar format to the Octopath Traveller games with it''s separate, distinct chapters each following different characters which I already wasn''t a big fan of in those games but i still wanted to give this game a try. Overall i felt it was just an average JRPG experience. The stories range from mildly interesting to outright forgettable, and some chapters are so short or underdeveloped that it''s hard to care about the characters or their worlds.\n\nCombat is basic, and while each c', 'Very Positive', 89.67, 32.18, 11.55);
INSERT INTO reviews VALUES (47264, 2015240, 1807, 'Farming/Grinding/Timewaste the game.\nWhen I bought the game I was under the impression that it was a kind of roguelite, where you''d make a build every time you left the hub/"started a run". It''s not.\nYou make a build early on and stick to it for as long as you can be bothered to keep on farming. Every time you win a map, your reward is a bunch of currency and equipment to further enhance your build. The next run will be exactly like the first one, but with higher numbers.\nIt''s pretty decent for ', 'Game is fine; lots of holding right mouse button and kiting. \n\nLeaving a negative review to let the devs know it''s ridiculous to have to join a discord for patch notes.', 'Very Positive', 82.46, 62.88, 35.80);
INSERT INTO reviews VALUES (47265, 2015270, 1969, 'People are complaining of price increase. I find this absurd. Klei is doing what I''ve heard of most Early Access games. Please, do not review bomb a good game, because price is increased. I do not know how game development economy works. Game is an entertainment to me and Klei is very good at their job. But, this I can tell. Most early access games have their price increased as they continue to develop. They add more contents, more mechanics and more everything. So, the price is also increased f', 'Something would need to drastically change before 1.0 for me to be interested in picking this up again. The art is top notch. The combat itself serves itself really well. It almost feels like a 2d pre-World Monster Hunter. But that''s where it falls short for me. If it actually _were_ a 2d monster hunting type game I would be hooked. However every run in the same biome ends in the same boss fight which got boring extremely quickly. \n\nIn my opinion, the way to fix the game would be to have a mappi', 'Very Positive', 92.38, 0.52, 8.70);
INSERT INTO reviews VALUES (47279, 2019300, 131, 'Seeing how the game gets on release-day 5-10 patches, addressing each issue people have in the forums, is probably the most heartwarming thing i have ever seen. Keep the good work up!\n\nthe game is fire too~', 'If you like old school pokemon you''ll love this game, that being said there are some downsides that you should know about before getting the game. The first and most important thing in my opinion is that the leveling and stats system is way too complicated with no explanation to it anywhere, at least not that I could find. From what I could find it SEEMS like each level up gives you a stat point that you can put into a stat, but it doesn''t seem like putting them into a stat changes anything? als', 'Very Positive', 82.44, 3.28, 6.03);
INSERT INTO reviews VALUES (47283, 2021880, 998, 'Stable, no crashes, beautiful graphics, non intrusive sounds.\r\n\r\nVery deep game, with lots of way to get where you''re going.\r\nLess CIV then CIV, more production chains.\r\n\r\nBest thing about it, is economy centered, not military centered, very good.', '- performance is quite poor, but might be fixed overtime\n- requiring xboxlive for multiplayer should be part of the sys requirements instead of stealth installing it\n- the game itself looks like having potential but i''d wait a year or two before revisiting it\n- this is no civilisation, there is way more necessary micro management... so much that i don''t see this game playable in multiplayer at all, as the game takes too long for that', 'Mostly Positive', 70.44, 93.52, 1.17);
INSERT INTO reviews VALUES (47291, 2027330, 5834, 'Interesting, GTA is always victim of accusations of being the reason why school shootings happen and stuff, meanwhile, this game, this game is kinda ignored by that kind of people.\r\n\r\n\r\nbtw pls add sex to the game', 'It''s ass, they''ve ruined the game, can''t mess around with friends without being warned about spam and when the owner touches your stuff its theirs all the sudden and you can''t move it, i don''t recommend this game for people who''s wanting to mess around with friends', 'Very Positive', 92.25, 35.67, 37.00);
INSERT INTO reviews VALUES (47298, 2050650, 48302, ' Thanks, Capcom. \nI haven''t enjoyed playing games this much in a long time, but RE4 brought back long forgotten feelings and emotions. Definitely the best Resident Evil remake of all three so far.', 'It lacks a lot of the original heart and soul.\r\nIt takes some much of the original concepts that made it timeless in service of a more "realistic" game. The giant robots, giant boulders, cocky leon, dumb dialogue. All in service of a "modern" game that is overall more boring. Its all gray like its dialogue.', 'Overwhelmingly Positive', 97.05, 89.13, 43.37);
INSERT INTO reviews VALUES (47299, 2050680, 183, 'good {like pls. want steam points]\n', 'This game sucks. Jester award incoming. I''m pretty sure it''s the devs giving the jester award to every negative review. If so, it''s really funny how they have the time to go through every negative review to leave a clown emoji like a 12 year old rather than work on their shitty game.', 'Mostly Positive', 79.78, 12.72, 4.68);
INSERT INTO reviews VALUES (47304, 2051620, 151, 'Solid FPS with a unique take to the genre where you control a squad of soldiers not just one. Also with the tank and plane models of war thunder gives the game a easy to play hard to master vibe that can be daunting to tackle but once overcome can be an absolute time sink. Don''t let my steam hours fool you I''ve wasted far too much time to this game lol. \n\nEnlisted has definitely scratched the old Battlefield itch that i have been craving that has not been delivered in a very long time. if you en', 'This was the second worst Steam Release I have ever seen after The Day Before.\nAnd I am amazed on how silent the studio went regarding the release.', 'Mixed', 66.23, 306.03, 12.00);
INSERT INTO reviews VALUES (47315, 2054970, 41470, '"It would be funny if itsunos''s last game before quitting was a giant ''F**k you'' to Capcom that nobody picked up on"\n\n- cameron, punkduck''s friend\n\nNow i understand why half of the game feels exactly the same to the first game, what an astonishing meta story by Hideaki Itsuno he is always 2 step ahead of all of us BRAVO and thank you to punkduck for enlightened me', 'save file corrupted after 90 hours, lost all progress. seems to be a common issue. dont limit players to one save file if save files can be bricked at any time', 'Mixed', 67.25, 150.50, 121.58);
INSERT INTO reviews VALUES (47316, 2055050, 307, 'I have actually played this game outside of steam. At first, the UI lacked the more styled look, and the story mode didn''t have anything in it. \r\n\r\nI mistakenly thought the game was just some shovelware + anime girls because the first impressions was so poor. If the devs are reading this review, I need to tell you guys to. IMPROVE YOUR FIRST IMPRESSIONS. \r\n\r\nIt is until you actually played about 2 - 3 hours into the game where the stuff unlocks, the complexity shows that is where the game finall', 'Doing the same thing over and over again is not fun.', 'Overwhelmingly Positive', 97.72, 2.40, 0.43);
INSERT INTO reviews VALUES (47319, 2056210, 698, 'I found this game via Esty8Nine''s stream and absolutely love it. Today, I finished the climb with the first ship to defeat the highest difficulty currently in the game (I think). After doing so, I was reminded that everything wasn''t in the game since its not 1.0 yet, which I completely forgot that this was technically early access as of right now. Which is truly a testament to the quality that currently exists in the game.\n\nI love everything about the game with 1 small exception. The game NEEDS ', 'It''s an interesting game, but feels a bit random and short. By the time you randomly receive the right units to make a decent combo, the missions are over and you reset everything and have to start over', 'Very Positive', 90.69, 49.27, 22.88);
INSERT INTO reviews VALUES (47322, 2058570, 461, 'Did not like the first one, the potion economy could not let me enjoy the game.... well he fixed almost every problem I had with the core of this game and it is now a brilliant work of art. \nAn amazing experience.', 'For the moment, I''m actually going to not-recommend this game - While I like where certain things have gone with Rift Wizard 2, in comparison to RF1, there''s also just a staggering amount of additional annoying book-keeping involved now. I''ll keep playing it in short bouts, but I feel frustated after pretty much every run.\n\nYou are to be expected to read up on every single monster, their resistances and abilities, before choosing which room to go to next - Unfortunately the U.I. and presentation', 'Very Positive', 91.76, 111.67, 16.42);
INSERT INTO reviews VALUES (47323, 2058730, 134, 'I like because detective like mechanics\nI like presentation, style, ect.\nI like bringing justice to Nazis.\n\nAlso it gave me some feels', 'I really, deeply want to recommend this game because the content that *is* there is very well done. That being said, I just can''t get behind the fact that there are only 2 cases. I understand the game is only $20, but that''s a low amount of gameplay even at that price. Plus the ending feels incredibly rushed. You get through the two cases, then get smacked with an epilogue that hits you with a deeply uncomfortable revelation that you then do absolutely nothing with because sorry, game''s over! Ev', 'Very Positive', 92.54, 7.97, 12.27);
INSERT INTO reviews VALUES (47327, 2059310, 170, 'very enjoyable. voice overs make these types of games so much better and this game has a considerable amount of voice over. i see that as a big W. Mango should make more games that run on mac... its kinda sad how scarce good adult games are . Personally i pref this game over kaiju princess 1 so yeah give it a try and see if its also to your liking', 'The Game''s alright, nothing special. A decent gameplay loop, not a lot of variety but I dont mind that because even though there''s only one character she''s an absolute banger! What kills this game for me is the performance issues. The artwork is beautiful but the animations are terribly optimized, leading my actually pretty good machine to lag to the point of near unplayability. I wish I could enjoy this but I just cant when the framerate makes me feel like I''m watching a freaking slideshow the ', 'Very Positive', 90.59, 8.48, 0.82);
INSERT INTO reviews VALUES (47328, 2059530, 1017, 'Tried it because of the Greek theme...\n\nEnjoying it because I like open world crafting games...\n\nStill playing it because let''s be honest, who doesn''t want to be a flying hoplite putting mythical creatures and other evil creations in their place?\n\nPlus, I need my Greek fantasy fix while I wait for Titan Quest II to come out.', 'A game that starts off somewhat promising but ultimately descends into an exercise in frustration the longer it goes on. \r\n\r\n The hook of the ancient Greek theme isn''t really expanded on. Rather it''s a hollow facade - exactly the same as any other early access survival builder just with Spartan armour and a hoplite sword. The traversal is incredibly boring. It lets you fly, but the world is so sparsely populated with anything of interest that you end up spending 60% of your playtime hitting ctrl', 'Mostly Positive', 79.06, 6.60, 25.15);
INSERT INTO reviews VALUES (47329, 2060160, 1267, '\nwhile True:\n    if (get_entity_type(SteamGames.FarmerWasReplaced) and num_reviews(SteamGames.FarmerWasReplaced) < ∞ ):\n        click_thumbs_up_button()\n        print("This is only time I was happy to pay someone else to write code for them.")\n', 'I read from the reviews that programmers have fun with this game.\nBut for a noob this is way to fast in the beginning, could not get past the starting block and make a loop.\n', 'Overwhelmingly Positive', 97.00, 14.57, 0.55);
INSERT INTO reviews VALUES (47331, 2060790, 197, 'This game is awesome! The art style is amazing and I love the story. I really struggle with the idea of death and the fact that I will die one day. I love that this game gives me a cute, new way to think about the afterlife. I will say, this game is definitely challenging at times, but I enjoy that! I do wish it was easier to move around to the different locations. I''m someone who likes to double check that I haven''t missed anything and it''s time consuming to retrace my steps if I want to go bac', 'I wanted to love this game so badly. The visuals and music are nothing less than astonishing. \n\nBut I never had any fun, even after two full hours. The gameplay has no sauce: neither abilities nor rewards are compelling. \n\nReading the positive reviews here, I guess I didn''t realize this is supposed to be a cozy game. If you are not into cozy games, I have to warn you away from Hauntii despite its enchanting art design.', 'Very Positive', 94.42, 6.02, 2.13);
INSERT INTO reviews VALUES (47337, 2064810, 236, 'Please do some update, maybe SUV cars and maps', 'I''ve played CityDriver for 1 hour, and I must say, the experience has been underwhelming. For a game released in 2023, the graphics are incredibly poor. The game is riddled with bugs, making it frustrating to play.\n\nThe vehicles are poorly designed, and the vehicle sounds are equally disappointing. The steering is atrocious, making the cars feel like they are gliding on butter rather than driving on roads. Moreover, the selection of vehicles is very limited, leaving much to be desired.\n\nConsider', 'Mixed', 42.80, 14.82, 0.97);
INSERT INTO reviews VALUES (47338, 2064870, 462, 'Super fun game with lots of annoying hill billies that kill the entire lobby because they''re mad and jealous of people that don''t have parents who are related', 'I bought it and then they made it free.\nI''d like my money back, World Makers.', 'Mixed', 64.94, 15.40, 15.87);
INSERT INTO reviews VALUES (47339, 2065000, 109, 'Okay.  I have to say that I am surprised at how good this game actually IS.  I looked at the video and said, "oh, that''''s a clever gimmick.  And it''s on sale."  So i bought it and I''m glad I did.  (I do not say that often.)  The clever gimmick works well all the way through.  As I said, I was surprised.  Pleasantly.  It''s not the sort of game with a long play through.  But to complete a run you may need a few hours since it has an "endless mode" after you beat a certain number of levels.  12 tac', 'Don''t feel enough "chess" theme. Yes, some moves are chessy, but it doesn''t add strategy imho\nTurn-based bullet hell is a hard combo to make it fun, and this one I can''t call successful.\nI think animation between turns is too long, so the game is not as dynamic as I would like to see. And surely not as strategic coz there are too many enemies and you just trying to maximize splash/explode damage without targeting or caring about your position', 'Very Positive', 90.83, 48.63, 0.37);
INSERT INTO reviews VALUES (47377, 2067050, 2122, 'last couple months were rough. gf broke up with me, parents disowned me, friends turned their backs, lost my job... didnt have much hope or motivation to move forward. barely even made out of bed today, but im glad I did. because if i didnt keep pushing, i never wouldve experienced this PEEK. Squirrel With A Gun, youve given me a reason.', 'Don''t get me wrong, this is a fun game.  There''s not much to it, but the assassinations are hilarious and the entire concept is absurd.\r\n\r\nBut glitching under the map, getting stuck in a tutorial scene, or just a plain ol'' force-close ... it gets old quickly.  When I can only play for 40 minutes at a time before the game messes up in some way, forcing me to close it out and reload the last save who-knows-how-long-ago and then go through each mission and cutscene again, I can only do so much.', 'Very Positive', 87.37, 7.25, 4.82);
INSERT INTO reviews VALUES (47410, 2067780, 1455, 'goated game goated game goated game goated game goated game dare i say better than danganronpa play it NOW', 'Your Turn to Die started as a promising horror and mystery game, but unfortunately, its journey in Early Access has become a true test of patience for fans. The game has been on Steam for two years without completion, and the creator, Nankidai, remains completely silent regarding updates, deadlines, or any relevant communication.\nThe lack of commitment to release dates is one of the biggest issues. There is no transparency about development, leaving players in the dark, unsure if the game will e', 'Overwhelmingly Positive', 98.90, 34.40, 13.33);
INSERT INTO reviews VALUES (47411, 2067790, 457, 'I can fix her', 'very bad optimisation, fix it, lots of stutters and frame drops', 'Very Positive', 94.31, 2.65, 0.42);
INSERT INTO reviews VALUES (47437, 2068280, 1790, 'A fully recommended action-roguelike with many interesting skills & characters to unlock.', 'It used to be good, but now devs thought it''s a good idea to reset meta progress and lock achievemnets in paid DLC to keep the game "fresh".', 'Very Positive', 89.39, 1215.85, 75.00);
INSERT INTO reviews VALUES (47469, 2069040, 998, 'Totally worth the $6. Puzzles are just challenging enough to really piss you off. A couple of times we came close to using a hint but were always able to grind it out. 100% recommend', 'Great game but way too short! The puzzles have a good difficulty level (we never needed any hints) but usually had a similar pattern. Fun but not worth the $12 since you need to buy it on two devices to play.', 'Very Positive', 91.68, 3.53, 2.55);
INSERT INTO reviews VALUES (47480, 2069310, 471, 'I was EXTREMELY letdown. I read all of these good reviews and so I bought the simulator. Once I got into it, my graphics were worse than games I''ve paid 20 dollars for. There were no options to increase them or even set my resolution. I bought this to enhance my flight skills, and the instructor mode is no more than videos. Those were already free on YouTube. I literally got nothing for my money. It''s simply a game.', 'This game is okay, but not 100 dollars okay. The full version is a bland waste of money. If you need to learn how to fly RC vehicles, I would recommend Phoenix for free or at most the trainer version of this game. Even better if you can play it for under 2 hours and then get a refund. The graphics of this game do not match the pictures. Even at maximum they run easily on my laptop (which doesn''t have dedicated graphics) and look like they are from a 2010''s budget game. Seriously, most of the map', 'Very Positive', 85.56, 1.50, 7.77);
INSERT INTO reviews VALUES (47531, 2070550, 2108, 'Steam 2010.\nHey, look at this awesome games platform where you can play games like Half Life and Team Fortress and Fallout 3.\n\nSteam 2024 Year in review.\nYou spent 200 hours playing 25 different games about finding hidden cats.', 'I can not recommend A Castle Full of Cats.  It''s a cute enough hidden object game, but I just did not find it fun or engaging.  People seem to love it, it has an overwhelmingly positive review score.  Unfortunately I just was not one of them.  The game ran fine, there were no bugs or glitches, it did everything it said it would in the description.  I just had no desire to finish the game after giving it a try for a bit.', 'Overwhelmingly Positive', 99.34, 1.78, 0.57);
INSERT INTO reviews VALUES (47559, 2071280, 6041, 'Absolutely goated game. \nOnly complaint is that honestly content feels relatively small still even with this release. Roguelikes live and die based on how long you can repetitively play them. \nAnd unlike Hades, you aren''t really building up a HUB world or anything so progression never really feels all that  fulfilling. The game is still an overall fun time, but it''s definitely on the lower end tier of rogue likes in terms of overall quality and things to do aside from runs. \nIt was the same prob', 'Game was fine until they decided to nerf the entire cast of heroes and the rerolls, basically making the highest difficulty a casino machine.', 'Very Positive', 86.48, 15.58, 75.60);
INSERT INTO reviews VALUES (47568, 2071430, 215, 'This is my second favorite roguelike city builder after Against the Storm, but that one has beavers in raincoats so it''s a pretty unfair contest.  Still, I very much enjoy the Norse theme and the aesthetic that blends a rustic feel with touch of future-tech.  The core mechanic of playing cards, placing buildings, and trying to generate resources effectively is very addicting, as is the meta progression.  You can make some terribly fun combos with the right mix of artifacts and cards.\n\nThe game i', 'This game looked really good, but it was just... boring.\nI found the game play repetitive and I didn''t find the story engaging at all.\nIt''s still early access, so might improve.  I''m not really sure where you would take it from here though.\nSorry devs.  I feel bad that I''m being down on your hard work :(', 'Very Positive', 89.77, 27.47, 3.07);
INSERT INTO reviews VALUES (47573, 2071520, 136, 'Great renders, nice characters and good plot.', 'I liked this game. I wanted to love this game. It''s so close. But the reason I can''t support it and the reason I did not buy the additional seasons is because this game contains hard stop game over points based on "really bad", as the game calls it, decisions. If you''re going to put a super kinky decision in your XXX game, I''m going to choose it to see the scene. Making it an auto game over just pisses me off. Let me know if you can confirm they got rid of those in seasons > 1 but, as of now, th', 'Mostly Positive', 76.47, 57.43, 5.65);
INSERT INTO reviews VALUES (47612, 2072450, 6339, 'This animal crossing game is pretty neat! Not too sure about the weird yakuza story attached to it though!', 'The game is 9/10, one of the best RPG in years. \n\nBut I cannot in good conscience give it a thumbs up when they gate NG+ as a paid dlc. What they''re doing is beyond greed, it feels like one of the shady villains in the game holding it the full game hostage. \n\nThe game IS worth playing and is good, but if you can skip it, do so. The only thing they can hear is you voting with your wallet.', 'Very Positive', 92.30, 109.45, 118.77);
INSERT INTO reviews VALUES (47624, 2072660, 227, 'Good but a bit flawed, if you like similar games and roguelikes youll probably enjoy it.', 'Making a somehow slow-paced FPS have bosses that are basically just DPS machines that you need to cheese to even beat does not equal a fun game', 'Very Positive', 88.99, 17.50, 8.43);
INSERT INTO reviews VALUES (47630, 2072840, 289, 'Overall the game is neat.\nThe problem is without copy and paste you are spending a LOT of time re implmenting factory paths for letters you''ve used many many times.\n\nThe ability to pick a previous word or letter and have the solution show up would speed up input.\nAs it is now I really can only do a puzzle or two till I get bored as I have to once again build an ''O'' generator to make another letter.', 'optimization couldn''t be done more wrong. the game seems to courage competition (with histograms), but it does not have save slot for each "farm factory" design. moving factories around & connect wire is super weird. the cycle count is wtf too since it counts cycles between output, ignoring the "overhead warm up time" of the whole factory farm. i''d say the game prefers form over function: make it bouncy and beauty, but not prioritize the fun from solving puzzle :(\n\nwithout the optimization in mi', 'Very Positive', 85.12, 1.68, 0.38);
INSERT INTO reviews VALUES (47652, 2073470, 1640, 'Even tho the devs abandoned this game half-completed, the server is still full of online players cus the the game itself is that good.', 'How is this game sitting at +80% positive reviews? There is no gameplay at all, it is shocking that for a RACING game there is NO RACING at all! You can just drive in circle while listening to some 15sec music loop that gets super repetitive very very quickly.\n', 'Very Positive', 81.40, 4.75, 0.08);
INSERT INTO reviews VALUES (47674, 2073910, 431, 'So much fun! Very unique mechanics, and the spider is adorable. The levels have lots of secrets to find, and the puzzles are enjoyable.\n\nAlthough it''s single player, I would recommend if you like games like Trine or It Takes Two. Also World of Goo', 'just a 3D ripoff of webbed', 'Overwhelmingly Positive', 99.77, 6.00, 0.30);
INSERT INTO reviews VALUES (47693, 2074330, 106, 'I produced 0.8L to this', 'no sticky footy, would not replay ever', 'Very Positive', 83.96, 0.20, 0.72);
INSERT INTO reviews VALUES (47725, 2074890, 180, 'If you''re reading this... Just buy the game.  You know you want it.', 'Its pinball. Fantastic Art. And why not some hentai?\n\nBut after an hour.. you''ve finished. And the elves have finished too who knows how many times.', 'Very Positive', 93.33, 12.75, 1.48);
INSERT INTO reviews VALUES (47735, 2075070, 7692, 'This game is AMAZING, you will definitely have a great time!!! Also, they need to add the sex update, other than that that its pretty good', 'this game was really fun and i enjoyed it however it caused a glitch and now my entire desktop has been wiped and i have to put everything back manually', 'Very Positive', 93.45, 4.13, 1.95);
INSERT INTO reviews VALUES (47737, 2075100, 139, 'Overall much smoother experience after the huge patch. Keep up the great work devs.', 'This game is really weird to me. The first game was really cool and I really enjoyed it. It was a awesome blend of Sci-fi, horror, mystery, exploration and atmosphere. It had RPG elements and base building elements but those werent really the focus. \n\nChernobylite 2 however... it''s like they removed everything that made the first game so cool and doubled down on all the stuff that wasn''t. This feels like a wonky fantasy fallout game or something. The environments look cool, but the gameplay itse', 'Mixed', 58.99, 8.07, 6.62);
INSERT INTO reviews VALUES (47765, 2075720, 1138, 'Game is good so far hovewer there is a lot of bugs and I had to replay the first 30 minutes of the game because I killed Muda.\nBut the game is good feels like elex 2 with the graphics and story\n\nEdit : So Day 9 and I cant finish the game because I am a bit too underleved yes its my fault but I couldnt finish like 5 quests because of how buggy the game is.\n\nIs it still a good game despite the bugs? Yes\nWould I recommend this to anyone? Not in its current state.', 'Let him cook. This game needs a couple more years in the oven. It''ll be amazing after that. I am sure.', 'Mixed', 68.54, 23.95, 0.50);
INSERT INTO reviews VALUES (47776, 2076010, 1330, 'The best actual fighter currently on steam/console. If you want a game with actual schmix and no hand holding like Strive or SF6/Tekken 8 then this is the game for you.\r\n\r\nHard to master, Easy to pick up and it''s not yet a discord fighter as there''s quite alot of people online though they only play ranked.\r\n\r\nI got this game when it came out new to the series, got cooked online but now I''m sitting near the top of the Carmine leaderboard. It''s worth it lads', 'Under Night In-Birth II Sys:Celes..  \r\nIf you love Undernight, this is just more Undernight, and I mean exactly more Undernight.\r\nHowever, for an Undernight..  this is unfortunately Overpriced. Arcsys messed up with this big time.\r\n\r\nIf you''re looking for a great modern French Bread fighting game and your budget is limited, grab Melty Blood Type Lumina instead.', 'Very Positive', 87.89, 121.35, 4.50);
INSERT INTO reviews VALUES (47781, 2076140, 799, 'I would like to start off by saying this. I don''t play casual games, visual novels and the like. Quite the opposite in fact, I play more action oriented games where you have SIGNIFICANTLY more input into what goes on.\r\n\r\nThis game however managed to capture my attention. It truly is something special from the perspective of someone who doesn''t normally enjoy these games, I can''t exactly pin it to one specific attribute, but if you are one of these kinds of people that think they don''t like it, I', 'The art is gorgeous and the character design is 11/10! However, the game doesn''t allow you to make mistakes or be very creative at all. The drink making is fun at first, but gets boring after the same character asks for the same drink for the 7th time in a row, and you don''t even get to choose what to make (the Innkeeper tells you when you''ve chosen the wrong drink, even if it meets the customers expectations). The most fun I have playing is deciding which drinks to make for quests, but that doe', 'Very Positive', 92.12, 6.38, 7.92);
INSERT INTO reviews VALUES (47787, 2076260, 109, 'Thank you for the fun times I had playing Pinkamena on mobile app, especially when multiplayer was introduced : )', 'i do really like this game, i had a lot of fun on mobile and it''s really complex and in-depth, but i can''t recommend it on here\nit crashes like all the time, making it unplayable\ni hope this issue will be fixed, but in the meantime i wouldn''t recommend purchasing\nreally sad :(', 'Overwhelmingly Positive', 97.25, 7.05, 0.13);
INSERT INTO reviews VALUES (47803, 2076580, 630, ' Another Banger From Devolver Digital \nThis game continued to surprise me the more I played it. It''s beautiful, unique, funny, and very creative in it''s world building. The gameplay mechanics call back heavily to the sand world from Ori and the Will of the Wisps, which is a blessing in disguise.', 'It''s a neat concept, but it just makes me want to play Celeste and appreciate it didn''t try to make you do area-style boss fights.\n\nControls aren''t as tight as they could be, interesting gimmicks aren''t used to their fullest, terrible gimmicks are used way to much. The water mechanics are just not fun (and they make them even less fun in the frozen level). I''m just not interested in playing further cause the cracks only get bigger the deeper you go into the game.\n\nIn terms of world building it''s', 'Very Positive', 86.35, 5.75, 9.67);
INSERT INTO reviews VALUES (47811, 2076740, 247, 'Better than Payday 3.', 'i got scammed out of my femboy sex game the game is made of 4-5 pngs and my penits was not wet, shitty femboy that looks like a homonculus i hate you femboy stepbro\r\nnot enought femboy penits and femboy starfish', 'Very Positive', 82.19, 0.33, 0.23);
INSERT INTO reviews VALUES (47846, 2077380, 270, 'Beautiful puzzle/platform game. Every level is made with a different art technique and hand made by the dev.\nReally fun to play. The only thing is that the whole game feels like a long tutorial. The puzzles are simple and maybe is the purpose of the game, making something more contemplative, but the mechanics are too good to not make something bigger and more complex with them\nI totally recommend this game', 'Has all the style charm and the platforming is even fun, but gets bogged down with thinking it needs boss fights. Shame, the first one (an escape sequence, basically), was really good. Downhill from there. It''s not that they''re impossible or anything, they just weren''t fun--sorry Micah.', 'Overwhelmingly Positive', 96.67, 3.95, 2.15);
INSERT INTO reviews VALUES (47877, 2078230, 485, 'this game is made with love, its a rogue lite mad max inspired open world. buy it, play it, supports a small indie dev team that listens to the community.  10/10 worth every penny', 'The block/component building doesn''t do it for me, I would''ve much rather a system where you change out sections of the vehicles and customise ''hardpoints''. The driving is passable, but quickly becomes a circling clusterfuck where you just wait to hit your abilities on cooldowns. They realised much of the game drags, and so are generous with speeding up and skipping cutscenes etc. But there is still much of it present, EVERY weapon ability makes you watch a slow-mo few seconds for example. Not i', 'Very Positive', 86.80, 25.85, 1.72);
INSERT INTO reviews VALUES (47880, 2078350, 301, 'Keeps my daughter entertained however, this game is not worth the full price and should only consider getting if your child enjoys the show "Bluey" (obviously Everyone loves Bluey)\r\nThe game can be a bit buggy at times and has very limited depth, as in could easily be completed within a couple hours by a child.', 'I had high hopes for this to be my son''s intro to video games. The whole family loves Bluey. Sadly this game is nowhere near the quality I expected from such a quality show. The models were super pixely, the audio just seemed off, and I could barely get past the character selection without bugs. Total bummer, had to return it. I bought it on sale and still think $30 is way too much money for the game.', 'Mixed', 69.44, 51.28, 1.10);
INSERT INTO reviews VALUES (47885, 2078450, 115, 'Never would''ve touched this if it stayed F2P, but for $16 in the Combat Racing Bundle? Absolutely. It''s some damn good car combat in a genre that doesn''t have enough options nowadays.', 'Despite advertising pear to pear multiplayer format and single player with bots, this game still isn''t playable offline. Seems fun, If it ever becomes playable offline I''ll pick it up again', 'Very Positive', 83.48, 1.83, 0.12);
INSERT INTO reviews VALUES (47890, 2078510, 317, 'i forgot to say this game is cool', 'Whoever designed some of the levels in this game needs to be locked up in a mental ward.', 'Overwhelmingly Positive', 98.74, 50.00, 18.17);
INSERT INTO reviews VALUES (47917, 2079180, 153, 'CONS: too many references for the setting to feel particularly believable\r\nPROS: you can be incredibly annoying about how you get all of the references in a way that''s really funny\r\n\r\nnot a particularly strong pastiche piece in how pervasively it feels "2003 written in the 2020s" but its less about the space itself and more focused on navigating awkward teenage relationships within it, and i found those really compelling. i knew ppl like most of these when i was a teen; its nice to be able to go', 'A fun throwback to the ICQ/MSN and MySpace/Xanga days. The story is told through a pixel art-styled social media platform... kudos to the developer for this creative approach to a visual novel.\n\nThat said, the story is both cheesy and heartfelt (if you’re lawful good, it’s probably your jam). My biggest issue is the pacing—it’s a very slow game.\n\nThe story itself could’ve been wrapped up in 2 hours tops, but instead, it stretches to 5-6 hours because you’re stuck waiting for characters to “type”', 'Overwhelmingly Positive', 96.08, 5.18, 6.05);
INSERT INTO reviews VALUES (47982, 2080690, 8093, 'To be totally fair. I love the genre. I bought Raft and both of "The Forest" titles when in early access, when the story wasn''t even really fleshed out. I was patient with both titles and those dev teams. They are not triple A studios. What set them apart for me was listening to player feedback. Both titles had a story in mind and worked towards that as the goal of releasing it farther than "early access". Right now i LOVE the "Waterworld" feel of the game. I love the amount of decorations. Even', 'Has potential but the latest update is a step back for solo players. Enemy respawn timer is unforgiving. In the middle of taking over an island the number of enemies left grew rather than shrank. Wait until it''s no longer in EA and hope for the best.', 'Very Positive', 85.49, 133.22, 27.47);
INSERT INTO reviews VALUES (47998, 2081080, 296, 'Gameplay wise reminds me of XCOM: Chimera squad. Levels play out more like puzzles where you use powers to manage the level as opposed to a more dedicated "grind and play" RPG. \r\n\r\nSetting is fine, story is fine, characters are fine. If you like super hero games and turn-based tactical games there''s a lot to like.\r\n\r\nI was on the fence due to mixed reviews but if you read the reviews a lot of them are clearly review bombs. Some 4chan "anti-woke" influencer got upset because the game isn''t entire', 'I feel bad for buying this. I bought it early on because I was so desperate for a Superhero X-COM but I can''t stand it. I kept hoping it would get better, but the story and characters are just not engaging,', 'Mixed', 69.93, 24.67, 1.17);
INSERT INTO reviews VALUES (48014, 2081470, 330, 'I am 53 years old and absolutely love Red Matter 2, very , very immersive. Not to difficult and strong story line. \nFive stars from me. \n', 'Looks fantastic but the gameplay is boring af', 'Very Positive', 91.21, 12.68, 1.08);
INSERT INTO reviews VALUES (48022, 2081630, 169, 'Short and simple answer is that in my humble opinion, this AVN is a solid 7.5/10 and a great addition for anyone who likes a lil more story, intrigue, and politics with there spicy stories.\r\n\r\nWhile not breathtaking visually the graphics are still overall good. It''s a fun period piece for the genre and I wish there was more of them. For the most part it has a really good story, decent pacing, good political intrigue. Though far from perfect it keeps getting better and better with each new update', 'I really expected more... if I knew I was going to be a General, yet not spend one minute outside the city during the entire AVN; if I knew that my only task in the entire simulation was to stop childish, catty backstabbing between 12-15 females, none of which have any impressive body worth buying; if I knew all the photos were still photos; if I knew that there would be only 15-16 "choices" to be made in the game (only one of which is an answer-all); if I knew that I would be expected to do ana', 'Very Positive', 90.53, 27.27, 9.58);
INSERT INTO reviews VALUES (48050, 2082350, 283, 'banned me from there discord after i sent a poop emoji, game good tho', 'Very slow development. Game is missing a lot of features that are in the trailer. \nWait for updates before purchasing.', 'Very Positive', 80.57, 47.30, 0.13);
INSERT INTO reviews VALUES (48052, 2082410, 166, 'I would give this game 4.5 stars of 5 if you put the time and effort into mastering the combat it''s very rewarding.\r\n\r\nThe only issue I have is the characters in-game, they can be rather flat which is disappointing because each character has a solid backstory and personality, the problem lies in the fact that the cast rarely interacts with each other and even then it''s mostly about the objective. The characters show most of their personality in their fist scene and the backstories are in the equ', 'This game DEMANDS that you rush and have enough damage in order to complete it. The entire game itself is pretty much Darkest Dungeon''s Farmstead from the Color of madness dlc where you will fight wave after wave of enemies with the map having some way to mess with your party but it has an ending. You do not have to complete the entire run in one sitting, you can save and come back later. In between these fights you will get events which are kinda a break away from combat, but can also be anothe', 'Very Positive', 91.57, 91.12, 53.95);
INSERT INTO reviews VALUES (48088, 2083210, 446, 'We have Gran Turismo at home.', 'This hurts to review because the gameplay is great and what they are going for is wonderful. It''s hard to find a game with that traditional Gran Turismo style progression. Unfortunately the dev misses on of the most important parts of what makes Gran Turismo/classic Forza''s progression addicting. Always getting a new car to try and making progress with new events. \n\nThis games progression has a good concept but sucks in practice. Events payout a pitiful amount of credits and cars sell for a redu', 'Very Positive', 84.75, 25.97, 3.90);
INSERT INTO reviews VALUES (48121, 2083840, 144, 'Her Name Was Fire is an alright game, and at its price point it is a really good game. There is not much in the way of content to be fair, but it plays really well and every weapon/upgrade is well balanced. The first however many hours of game play are super fun, and it is super exciting trying out different builds and weapons, however, those few hours are also enough to get used to everything and try out each of the weapons and upgrade paths. I definitely think this game is well worth buying an', 'Cool premise but thats really it\n\nEvery run you need speed buffs as a crutch just to survive. Speed and a card called ''fasting'' (Which increases dmg every lvl up skipped) is really all you need to completely destroy the game.\n\nAlso the Thunder blade is completely broken. Idk if its suppose to be a hard weapon to use but the early game is cursed, just restarting everytime until you get claymore then the late game is all fucked with you flicking your mouse around, squeezing all the bonus dmg possi', 'Mostly Positive', 70.14, 5.07, 3.07);
INSERT INTO reviews VALUES (48125, 2083900, 300, 'Dirt cheap game if you''re looking for something pretty easygoing, blending minor rougelite and tower defense elements together in a neat little package.\n\nBuy defense/support towers that can attack and assist in a variety of ways, while also comboing types of units together for better attributes (like stronger burns, longer tower ranges, wider AoEs, etc.), to make a tower line that can help you survive a constant assault from colorful little blob things. A game is only really slated to last 20 mi', 'Love the game... but holy shit this needs an epilepsy warning.', 'Very Positive', 85.00, 4.13, 7.15);
INSERT INTO reviews VALUES (48132, 2084000, 2607, 'It''s as if Fights in Tight Spaces and Katana Zero had a child. Positioning is key, mistakes are severely punished, the gameplay is rhythmic and elegant. Move, turn, wait, queue your cooldown-based skills in a fast-paced tactical frenzy. The graphics, while plain, convey the setting and possess the oomph. A well-timed twitch and a swoosh effect coupled with a little bit of screenshake make a mace to the face feel as it should. The UI is really helpful by showing you enemy intents so you could str', 'Definitely a fun experience for a few hours, but gets repetitive much too fast to shine as a roguelike.\n', 'Overwhelmingly Positive', 97.24, 24.72, 25.43);
INSERT INTO reviews VALUES (48169, 2084930, 190, 'Played and perfected with family sharing.\nPurchased after it because a developer, who not adding stupid amount of achievements (100+) to his/her/whatever  short game deserve money.\nThat''s all folks.', 'THREE GAMES LATER NOTHING HAS CHANGED\n\nI don''t like giving games a thumbs-down vote because I feel bad for the developers who must feel a sense of pride after creating a game. But on the other hand, I feel it can help developers by encouraging them to be more creative.\n \nI have played every hidden cat game I can find; some are simplistic clicking games, some require you to actually find hidden cats, and others have elaborate interactions. Two of my favorite hidden cat games are\nhttps://store.ste', 'Overwhelmingly Positive', 98.95, 0.73, 1.83);
INSERT INTO reviews VALUES (48190, 2085360, 267, 'Do it. Buy it. I feel seen. \nInsomnia is a cute, amazingly illustrated game about exactly what it is like to have insomnia. It may be a short experience but is perfectly paced and reflects well, it''s subject matter. 10/10', 'i am kinda neutral about this one; it was a good time killer, and i related to the character a little, but.. if i had to choose, i wouldn''t recommend adding this game to your backlog', 'Overwhelmingly Positive', 96.25, 2.28, 1.37);
INSERT INTO reviews VALUES (48211, 2085920, 141, 'So realistic i can''t hardly breathe!!', 'BEING BLACK IN VR IS HARD\n\nPLAY ON A KEYBOARD OKAY.......', 'Very Positive', 94.33, 1.60, 1.30);
INSERT INTO reviews VALUES (48220, 2086140, 216, 'don''t believe what the other reviews say, the game is extremely good if it runs in your system', 'Can''t give a positive review on good faith.\r\nI''ve been very anti AI since the beggining of this craze, I couldnt believe my eyes when I beat a run and saw the developer thanking ChatGPT in the credits... I don''t know what parts of the game were made using it, but I''m against it and always will be. The worst thing is that it''s actually a really fun game!!! I will probably keep playing it for a while more, but like I said, I can''t support a game that was made using genAI, sorry.', 'Mostly Positive', 75.00, 43.10, 5.03);
INSERT INTO reviews VALUES (48221, 2086150, 104, 'Really short game.', 'This game is not worth it, as much as the sex scenes are not too bad. The quest system is totally broken, NPC don''t spawn, pieces of them left behind. It is total crap in the open world.', 'Mostly Positive', 72.12, 1.47, 4.20);
INSERT INTO reviews VALUES (48230, 2086430, 879, 'neat game, although devs tout the number of weapon combinations imo the variation is lacking since a number of those modules are just upgraded versions of previous modules. the ~800,000+ weapon combinations number, although technically true, doesn''t really feel so when you''re picking one of ~5 different base upgrades over and over again. i''d like to see the visuals more refined (although this is situational, i''ve been overwhelmed by the amount of explosions on screen with the RPG during lategame', 'At this point in development, the game is too unbalanced. Progression is an absolute slog. Meta game enhancements are extremely high priced, with the resources you need to buy them exceedingly scarce. There is no reliable way to create a build, or to further develop the weapons you make; the first assault rifle I ever made is still higher rated than the 14th, despite having unlocked a lot more attachments and having a better understanding of what they do. The RNG hates on you hard; there are som', 'Very Positive', 87.71, 26.20, 43.10);
INSERT INTO reviews VALUES (48241, 2086680, 129, 'If this game implemented Co-op and Mod support, it would go so hard.', 'Neat so far but disappointed by lack of AI disclosure and use of AI voices in the game. UI is also very limiting with only being able to have 4 building tiles on your hotbar at a time, which you then have to back all the way out of the build mode to then change them to different tiles. Moving around your troops is also very un-intuitive and getting them to go anywhere you want is very difficult. There is a food resource that says + or - but seems to update at its whim and doesnt give you anyway ', 'Very Positive', 87.60, 11.28, 0.70);
INSERT INTO reviews VALUES (48256, 2086970, 108, 'it a fun and good game for in terms of sex games 10/10', '"You don''t have to do this." "Amazing," "Wonderful." "I usually don''t do this." they are said so many times it''s just annoying. The game is highly repetitive. Some scenes can''t be skipped and take forever to complete. The idea is nice and different from the average adult game, but the conversation couldn''t be duller. The words mentioned above are said tons of times. The conversations are boring. The girls look like mannequins; the sex scenes are pretty bad. There are no details in a females geni', 'Mostly Positive', 75.93, 3.20, 2.52);
INSERT INTO reviews VALUES (48279, 2087610, 105, 'I started playing this and thought "Oh man, the Super Puzzle Platformer guy is going to be PISSED" and then I looked at the Dev.  Great job, Andrew.  Super fun.', 'tetris minus the part that makes it addicting in any way; impossible to get into personally', 'Overwhelmingly Positive', 98.10, 6.33, 1.37);
INSERT INTO reviews VALUES (48306, 2088280, 142, 'its pretty good at about 4 hours for the cost, decent atmosphere and story. Enjoyed this one. Strong recommend', 'Just played this game, and honestly, it’s ridiculous. If the developers insist on calling it a horror game, they’re setting themselves up for failure because it’s not scary—just painfully boring. It feels like one endless chore. Nothing goes smoothly.\n\nYou solve a puzzle to get a key—great, progress! But wait, the room you just unlocked is pitch dark because the lightbulb is missing. Fine, you go to get a lightbulb. Oh, but the hatch to the ladder where the lightbulb is? Rusted shut. So you need', 'Very Positive', 85.21, 4.98, 4.80);
INSERT INTO reviews VALUES (48310, 2088340, 285, 'Recommend this for all the girlies! 🌸𓂃 ࣪˖ ִֶָ𐀔', 'I recommend it if you''re new to Bratz or are looking for some nostalgia.\nI wouldn''t recommend it if you''re looking to relive the old Bratz games, as Rock Angelz and the like were an entirely more engaging experience than this one.\n\nIt disappointed me...', 'Mostly Positive', 75.09, 4.75, 1.70);
INSERT INTO reviews VALUES (48324, 2088570, 6974, 'It''s a great rogue-lite but honestly, the barrier to me playing it more often is the fact that there''s no mid-run pausing. The runs can be LONG, and I''m an adult with responsibilities. I need the ability to stop and start a run again later, especially when they''re almost always over half an hour.', 'This game does not include any kind of "save + quit" option, which demands the player spend hours in a single run hoping that no emergencies or game crashes happen. If you do have to stop for any reason, all of that progress is lost and wasted. This does not respect my time as a player and the dev has totally abandoned the Steam forums (via a pinned message) and, quite frankly, he/she seems to have an ego problem. I do not like that and I won''t support someone who says they won''t implement neces', 'Overwhelmingly Positive', 97.02, 12.22, 1.28);
INSERT INTO reviews VALUES (48338, 2088840, 2546, 'PEAKayune dreams is the ultimate and final game. it is the culmination of humanity''s achievements. it represents both carnal pleasure and the eternal ennui that we all face.', 'I''ve played most of the bullet hell/heaven and Vampire Survivor clones out there. This simply is not a very good one. It feels swampy and unresponsive, the enemies are dull, the graphics are kind of interesting, but also there''s way too much clutter. The upgrade system is lackluster, the weapons are typical and boring. It''s odd, and either it''s merely that oddness that is leading people to give such high and omni-directional praise for this game, or it''s some gimmicky marketing campaign. Probabl', 'Overwhelmingly Positive', 98.78, 133.07, 1.40);
INSERT INTO reviews VALUES (48360, 2089350, 593, 'i have no clue how to play picross but this has hatsune miku in it and thats all that matters', 'there is no way to disable the assist mode, it''s always on and you *will* be told the answer. you can''t mark a single square without the game shoving you aside to tell you if its wrong which completely destroys the point of a picross game. you''re better off playing a color by the number game compared to this. if you want a good picross game just play khimera puzzle island instead. i''m devastated bc i thought this would be another solid picross w miku :(', 'Very Positive', 93.76, 2.33, 0.17);
INSERT INTO reviews VALUES (48368, 2089600, 353, 'very good game \ni can finally sit in my room and pretend to have friends and a job i highly recommend this!!', 'Uuuugh..... hate giving a negative review, especially to a project that I feel is really promising. There''s a ton of evident, great stuff here - design, music, puzzle solving. However, I feel the English translation is not so strong. It''s not *unreadable* levels of bad, but it''s clunky - lines aren''t connecting naturally, odd words are chosen, stuff like that. It''s enough to take me out of the scene and lessen the mood the game''s going for, and I''m not seeing other people highlight that. And I''m', 'Very Positive', 90.65, 0.42, 5.77);
INSERT INTO reviews VALUES (48384, 2089980, 185, 'This game is great. Is it some triple-A blockbuster? No. Is it an experience with thousands of hours of game play? No. Is it a perfect game with no bugs? No. But do you want to know what it does have? Passion. In an industry rapidly filling with soulless cash grabs by greedy companies that don''t care about your experience, EPC is a breath of fresh air. It looks beautiful, has a simple and effective progression system, and most importantly of all, it''s just fun to play(solo or with friends). If y', 'Does not work with 8bitdo controllers and steam deck', 'Very Positive', 82.70, 14.55, 1.08);
INSERT INTO reviews VALUES (48438, 2091500, 227, 'First day playing it... and this game is pretty cool development tree and simple enough to figure out with some trial and error. What you put in your deck will determine how long you can survive. Overall it is a good balance game. \n\nThe only cons I see is this game eventually overruns you with the orcs.... It feels like every time I play a new game, I am already expect to die in the end. Maybe they should give it milestones like 10min, then at the 15min mark, then at 20min mark and so on each 5 ', 'I enjoy the game a bunch, however it seems the Devs are busy making new games before finishing this game, Most the game is great Until you get to the endless version, which is apparently set up to be a super grind-fest? The scaling happens way too quickly, as well as the game mode changes for some reason? If its endless it should allow for endless card unlocks to help mitigate and adjust but instead they are locked behind the defeat of each wave instead of multiple unlocks a wave. The Town hall ', 'Very Positive', 83.70, 54.12, 91.30);
INSERT INTO reviews VALUES (48470, 2091960, 180, 'don''t play if you have Megalophobia', 'I am really really sorry but whatever I was supposed to feel, I did not at the slightest. It feels like someone''s first steps into 3D, including sculpting and scanning. I think I get what was the intent but the implementation is just very, very low effort.\n\nThe big reveal at the end felt like a joke and not a clever one to be honest.\n\nThe music was alright.', 'Very Positive', 86.11, 1.33, 1.05);
INSERT INTO reviews VALUES (48504, 2093000, 104, 'Cool game. It focuses on story more than the other games like it. All levels are predesigned which i personally prefer to the randomly generated alternative. Decent playtime for it''s cost from what i''ve seen. Can be quite challenging but that''s what i came for. Well worth imo.', 'It''s not a survival game, or a city sim, or any real combination, despite its surface appearance.  It''s really a glorified, linear, puzzle game.  There are so many scripted events, and so many little things to juggle, there''s basically only one way through, with little to no wiggle room for actually playing it like any kind of sim game.  It''s like playing a ''choose you own path'' adventure where 50% of the paths lead to death with no real way to tell beforehand.  And there''s so many cascading dea', 'Mixed', 63.46, 4.40, 10.33);
INSERT INTO reviews VALUES (48505, 2093010, 299, 'It''s a $10 game. Solo developer. People need to cut him some slack. I enjoyed my playthrough of this & felt I got my money''s worth. The ghost Susan Crawler is actually very unsettling. The way she stalks you from around the corner and runs at you is VERY creepy and gave me chills each time. Totally recommend it!', 'I am entirely convinced this was written by AI. As others have pointed out, the story makes absolutely no sense, nothing adds up. \n\n(I''m going to mention some "spoilers" here) First "Susan" is said to be an 80 something year old, by the end of the game it''s saying she was pregnant with a family and implies the Sherif was in love with her. I mean, even her ghost is clearly an elderly woman. Various instances throughout the game seem to have no correlation or add any meaning to the story. The game', 'Mixed', 63.21, 1.35, 3.08);
INSERT INTO reviews VALUES (48539, 2093900, 109, 'Island Cities is a cute and relaxing puzzle game. You get a look at the finished city and then need to rearrange all the scrambled tiles. You can always check back at what the finished city needs to look like and there is no time limit or some other restriction, which I think is perfect for a relaxing game. Since the price is a real steal, I''d 100% recommend Island Cities.', 'I thought there would be more to it, but it really is just a jigsaw puzzle. I wouldn''t complain if it was just that, except that several configurations that make sense as a city are not accepted as solutions, you need to place the blocks in an arbitrary specific way, leaving little room to creativity or play. On top of that blocks are fixed when they fall into their place, which can block the way for other blocks and prevent you from completing the level, which is annoying.', 'Overwhelmingly Positive', 97.25, 3.23, 0.15);
INSERT INTO reviews VALUES (48540, 2093910, 164, 'The translation quite possibly could have been done by ChatGPT. Yet, I still managed to have fun!', 'FPS capped at 60.\n\nNo FPS options.\n\nNo Vsync.', 'Very Positive', 85.98, 7.02, 1.18);
INSERT INTO reviews VALUES (48541, 2093920, 332, 'First thing first, the game is quite atmospheric. And by that I mean, the game''s setting and atmosphere can be VERY immersive and scary at times. The potential is there and that''s the problem...you can tentatively feel there''s a great game inside, different than the slow, methodical Project Zomboid. Things can get super duper hairy in a cinematic way (which feels awesome at times) some scripted some not but when things come together it''s out of this world. NPCs from soldiers to future-victims ac', 'Tried to play the game despite the main UI and overall game looking bland and unfinished, GUI is also clunky. Gameplay is repetitive, I literally held shift and ran to each waypoint over and over again which I then noticed I was still in the tutorial.\n\nEverything looks like a last minute effort to make the game look decent but it shows that the devs didn''t even check their own game.\n\nI would wait until the developers actually polish the game and make it worth to play.\n\n(P.S whoever told me this ', 'Mixed', 66.27, 12.85, 1.30);
INSERT INTO reviews VALUES (48548, 2094070, 248, 'This game is basically the Zelda Maker that N* never released. If you love 2D Zelda games, this is truly an endless experience, just like Mario Maker. The Steam Workshop even allows you to turn your main character into Link himself using community-made mods.\r\n\r\nA huge portion of the dungeons created by players are inspired by Zelda, filled with references, or even full recreations of the original dungeons. If you''re a fan of 2D Zelda games, this is an absolute must-play!\r\n\r\nThe developers'' passi', 'great minish-cap inspired art, good controls on the builder, but the central issue is that playing individual zelda dungeons isn''t very compelling. an excellent game built around a very flawed concept', 'Overwhelmingly Positive', 97.98, 4.22, 0.27);
INSERT INTO reviews VALUES (48564, 2094320, 451, 'i''ve never written a review in my entire time on steam, but this game was too good to NOT say anything about it.\ni''m a sucker for games like this and even my fiance enjoyed playing this with me. i''d rate this game a 10/10, right next to escape simulator and the we were here series. i got this on sale for 3 euros but better believe me i would''ve paid 15 euros for a game like this, 100%. very very good!\n\ni really don''t get the people saying the game crashed in coop, because it didn''t crash once fo', 'Don''t get me wrong, I had fun, but the game plays poorly in co-op, items missing, 5 crashes, then we both had to play the game through again in single player because we couldn''t both reveal the illusions so neither of us could get our achievement.\r\n\r\nI like the atmosphere of the game and the narrator is very funny but at full price for only 3 hours of gameplay with half of that being rebooting after crashes or when one of our items fell through the floor and then replaying to get all the achieve', 'Very Positive', 83.37, 1.97, 3.48);
INSERT INTO reviews VALUES (48596, 2094910, 305, 'The grammar mistakes and typos are kinda jarring. PLEASE make it better. Things like:\n"choises" instead of choices.\n"Let''s" when you mean "Lets". "Lets you skip a turn" not "Let us you skip a turn". Let''s = Let us.\n"It''s" when you mean "its". "Satisfies the need of Nature in its range" not "it''s range". It''s = it is. "it is range" is wrong.\n"Adventages" instead of "Advantages".\n\nPlease for the love of god, get an editor or someone who speaks English to go over the base text before you fully rele', 'I really don''t recommend the game right now, because it''s fairly broken. I know it''s an early access game, but some of thebugs I am encountering are frustrating and shouldn''t be there upon release:\n- I can''t get key rewards no matter what I do - Complete Rectland below 75 meters? I''ve done that on Regular Game Mode at least 4 times by now and I can''t get the reward for that objective.\n- Land fails and I attempt a new game? Land is still at it''s failed status, even though I just started a new gam', 'Mostly Positive', 77.05, 2.27, 21.20);
INSERT INTO reviews VALUES (48615, 2095190, 127, 'sami bag pula in el ca nu ma lasa sa il scot\r\n', 'its just really bad, i only have these hours cause i left it on and forgot to turn it off', 'Mixed', 69.29, 67.45, 643.28);
INSERT INTO reviews VALUES (48621, 2095300, 246, 'studying hard math keeps principal yang away', 'I was really enjoying the game until, at the half way mark, it just ended and told me I had to buy DLC to see the rest of it. No resolution at, just an abrupt cut and a link to the Steam store.\n\nAbsolutely inexcusably scummy practises. Avoid at all costs.', 'Very Positive', 87.40, 8.08, 2.72);
INSERT INTO reviews VALUES (48623, 2095340, 752, 'I don''t know why this game gets the hate it does. The first bit of it is a little... bad, but everything else about this game was great. Obviously not as good as Road 96 but it is still very good. Not enough Stan and Mitch though. But if you are seeing all the reviews saying it sucks, only the start does, its pretty good. Get the game please.', 'If you''re a fan of Road 96, this game will most likely be disappointing to you. Not only is it significantly shorter than the original game, but it also plays differently.\nThe developers for some reason thought it would be a good idea to incorporate rhythm-based mini games into the story, and it honestly doesn''t feel like a necessary addition. I personally would''ve preferred to play it without those elements. \nAs far as I''m concerned, the only reason to play this game is for its backstory into Z', 'Mixed', 66.62, 4.47, 4.03);
INSERT INTO reviews VALUES (48627, 2095450, 351, 'Nothing groundbreaking. Solid TD for those that like TDs. Wait for a sale.', 'Uh i think i''ll go with not recommend. The core mechanics are good, the art style is... fine. But there isn''t enough variety for how long the game is.\r\n\r\nFrom what I experienced it boils down to getting an aoe unit and putting all the upgrades on it. Every single level.', 'Very Positive', 82.05, 8.40, 22.05);
INSERT INTO reviews VALUES (48656, 2096030, 114, 'I plow for a living in New England, and honestly this is how it all started the way you start with this game, shovel and go. Truck handles as it should in conditions on realistic. Save Game should be more noticeable (it''s on the office wall to the left of the map board). The game is slow paced, but relaxing. Can''t wait to see what else gets added. Also wish there was Co-Op it would be interesting.', 'Shoveled snow for 3 hours. Little repetitive but, that''s fine and to be expected. Finally saw my first NPC in game he tells me to check on a swing in his backyard. I fell in a hole and can''t get out of it. Had to quit the game. No auto save, lost 3 hours of progress after falling into hole. Rage quit game, uninstalled game, waited 2 months before leaving review due to still being angry and not even wanting to even think about this game again. Would give it more thumbs down if i could.', 'Mostly Positive', 73.68, 3.63, 3.13);
INSERT INTO reviews VALUES (48680, 2096510, 308, 'If you like Chess you will definitely like this. Some of the names of the extra pieces in this are made up for this game, like war wagon, but many of these piece types exist in official chess variants that I have played. The War Wagon is a promoted Shogi rook for example. But many of these are completely unique to this game. I got a little bit addicted to this game because I play chess every day already and this is my style.', 'im disappointed i was looking foward to play this game for a while, finally bought it and in less than 2 hours i''ve beaten the game nad almost in 4 tried almost every piece and upgrade... im disappointed because there is a really great potential but it''s not fullfilled, i would understand if this game was new, but for a game that is 2 years the only this i can say is that im disappointed', 'Very Positive', 85.39, 3.43, 3.90);
INSERT INTO reviews VALUES (48685, 2096600, 1508, 'Crysis 2 Remastered is a great game with an awesome story. Fighting some human enemies and aliens. Buildings collapse, everything was collapse was awesome. It making me intense too. The combat system is the same as Crysis 1. Like throwing enemies far away. The suit does have a cloak, armor, and more. Same as the first game. Remastered, well it looks a little bit odd, but I do enjoy it. Great graphics and smooth gameplay', 'No steam clouds\n12 languages, no Brazilian Portuguese.\n\nCrytek really hates Brazilians, we haven''t forgotten what they did in Ryse: Son of Rome (PC) which to this day has not received the PT-BR language that is available on Xbox.', 'Very Positive', 86.34, 14.70, 6.57);
INSERT INTO reviews VALUES (48686, 2096610, 1132, 'One of the best games of its generation, and a masterpiece singleplayer game of a kind they simply don''t make anymore. Back when it was new, you needed a beast machine, plus it was only available on origin and gimped consoles, which is the chief reason it prompted really bad headlines in gaming magazines, with the memetic ''EA IS IN FINANCIAL CRYSIS!'' being the one people are most likely to have seen, as, unfortunately, the game greatly underperformed.\n\nWell, that was then, and this is now. For a', 'I prefer playing games on the easiest difficulty so I can focus on enjoying the story and defeating enemies effortlessly, feeling powerful and unstoppable. For me, that''s what makes gaming enjoyable—not being repeatedly defeated in boss fights, running out of ammo, or struggling to find decent weapons. Unfortunately, Crysis 3 Remastered lacks this experience, making gameplay frustrating and more challenging than I''d like. It feels irritating rather than fun, and ultimately, it didn’t deliver the', 'Very Positive', 88.34, 4.05, 17.80);
INSERT INTO reviews VALUES (48718, 2097230, 1360, 'Can’t wait for “Turnip Boy commits arson”, “Turnip Boy jaywalks”, and “Turnip Boy violates the Geneva Convention” for more wacky fun times!', 'A lot worse than the enjoyable previous part.\n- Full of LGBTQ-propaganda\n- Exploring is only possible with a time limit\n- The characters are a lot less deep\n- The whole story is shallow and seems like it was thrown together just to milk the previous part\nHands off this "game", all it does is leave a bitter taste behind for the first game...', 'Overwhelmingly Positive', 95.96, 4.12, 5.72);
INSERT INTO reviews VALUES (48728, 2097570, 1198, 'the game has a hidden feature where you launch it and its suddenly 5 hours later', 'Gets unpleasantly difficult in act 2 and 3. And you have too low hp, only 5 doom points. And you get boned if special units channels doom in the backrow.\n\nCant recommend this game.', 'Overwhelmingly Positive', 99.25, 52.23, 6.85);
INSERT INTO reviews VALUES (48732, 2097720, 171, 'this game made me sexually attracted to bullets', 'The overall design of this game is VERY poor in my eyes, your main shot is unbalanced due to how narrow and weak it seems (especially in comparison to how fast and/or durable most of the enemies get sometimes), certain bullet patterns I encountered felt unavoidable due to their absurd speed (I also feel like their hitboxes might be janky, but that could just be me), and the music is average in my opinion, which I find strange since shmups (especially Touhou games) have absolute banger soundtrack', 'Very Positive', 91.81, 5.58, 0.37);
INSERT INTO reviews VALUES (48804, 2099080, 250, 'This is a really cute search game. You need to find all the cats within a black and white picture. Once you find a cat and click on it, it gets a bit of colour.\r\n\r\nVisually the game is really beautiful with the art style and the scenery and later on the colours. \r\n\r\nThe sound effects and music is really nice where you can hear the cats every time you find them and when you search in a different area, then the sounds differ.\r\n\r\nOverall a super fun game with easy achievements.', 'Was good at first, but saved up 17 hints and could an only use the first one.  Waited 5 minutes and still could not use the other 16!  WTH?\n\nRead other reviews about achievement problems.\n\nFix the problems please!', 'Overwhelmingly Positive', 98.40, 1.02, 1.88);
INSERT INTO reviews VALUES (48806, 2099110, 1073, 'its great fun but would be amazing with even 2 player coop or the goty with 4 player coop or game of all time with 16 player coop', 'This new update includes a lot of AI slop, more bugs, and the new level is nearly impossible. Skipping any future updates for this.', 'Very Positive', 91.15, 1.95, 5.75);
INSERT INTO reviews VALUES (48812, 2099220, 183, 'Vampire survivor style game that''s actually really good, plays well, tons of diff char, and packed full of things you can buy ingame with currency earned through playing. Has an auto chess mode and coop, what more do you want at a steal price?', 'It''s a paid version of holocure that isn''t as good as holocure.', 'Very Positive', 85.25, 72.88, 11.53);
INSERT INTO reviews VALUES (48857, 2100150, 118, 'Finished a run with assasin girl, and man that was satifying. Game got me hooked and I want to play with other characters too. Not a copy of another game, characters feel unique, you can get various playstyles. camera angle felt weird at the beginning, but I got used to it now.\n\noverall I strongly recommend!', 'gets boring and repetitive very quickly after the first few runs, the difficulty is laughable for a roguelike, so laughable that even a toddler can beat the game on his first run, and there aren''t that many fun synergies to experiment with, not recommended.', 'Very Positive', 87.29, 9.85, 6.37);
INSERT INTO reviews VALUES (48858, 2100160, 283, 'I guess the Bikes handle very realistic, the AI sucks and this Game is not made to play vs. AI. \r\nI am just very shitty in this game C:\r\n\r\nGraphics are pretty tho c:', 'not recomended if you play motogp for fun because the ai is impossible the wet wheater feel like flood you cant even brake without crashing idk if its was a skill issue but i say that this game is pretty bad', 'Mostly Positive', 78.45, 10.47, 392.55);
INSERT INTO reviews VALUES (48907, 2101250, 131, '3 FPS Simulator (in the good way)', 'It worths it''s discounted price, but lacks content overall  and it is very, very, very grindy.', 'Very Positive', 87.79, 8.33, 14.30);
INSERT INTO reviews VALUES (48964, 2102450, 659, 'I highly recommend this game... just not right now. I have been following the development of this game closely for roughly 2 years now, and it was my most anticipated game of 2024. It delivered a bloodborne x sekiro combat system that I absolutely love, along with a good story, interesting lore, and a gorgeous world that I want to explore more of. However, with my bias now being addressed, this game isn''t worth the $50 price tag. This is the devs first game, and that unfortunately really shows. ', 'I knew something was wrong which is why i refunded.\n\nYou release a roadmap with core features needing to be polished after release. Why not release as early access at a discount? Why not just wait until March of 2025? I do appreciate you continuing work on the game but you should of delayed or early accessed this game. \n\nI wasnt even going to make a review but I just refuse to accept this type of behavior in gaming any longer.', 'Mixed', 64.49, 32.87, 0.60);
INSERT INTO reviews VALUES (48969, 2102520, 1041, 'Game seems to be dead but in actuality is still very much alive. The devs are rebuilding the game from the ground up in Unreal engine after the Unity scandal. So while i recommend the game i also recommend just keeping an eye on it and wait till they re-release the game.', 'DO NOT BUY, Developers have all but given up on game yet keep telling people to buy into it then after steam does the update to let us know this game is basically abandoned the dev gives a bogus update reiterating their bs of UE5 version is being worked on. Now they''re saying it financially is becoming a burden so they need more money from us because this game was started when they were 14 they didn''t expect it to be this big when they released it at 18....just sounds like these people were a sc', 'Very Positive', 86.94, 11.48, 1.35);
INSERT INTO reviews VALUES (49015, 2103470, 153, 'I agree with other reviewers, if you''re really into Anno, this is probably not the game for you. I personally find Anno to be a bit much, especially after a long day of responsibilities, and this game scratches the itch while still being casual enough (it also costs way less). It reminds me a lot of Sid Meier''s Pirates, with less complex battles and city building. I will say, if you like a challenge, this game isn''t going to provide much. But if you like pirates, city building without too much r', 'Play the demo it''s all there is to this game. It''s the first map restricted before you unlock clothing. There is no more. Don''t be tempted you will be disappointed. Not even if it''s on sale, don''t do it. There is no campaign though the menu option is campaign or free play. No story line. Unless you think The Big Red Ball is a story book. It a series of different maps you have no access to until you pass some arbitrary line. It''s random when stages unlock. You can wait hours after building what t', 'Mostly Positive', 73.86, 35.98, 11.53);
INSERT INTO reviews VALUES (49023, 2103640, 250, 'axis football 2023 his a good game overall. outside of the gameplay witch honelsty sucks, and the anouncers that just werent prograhmed well the rest of the game is great, i love how you can customize teams and outside of playing franchise mode is really fun. i would give this game a 3.5 stars but if you want to try the gameplay go ahead', 'Franchise management is great, but the actual gameplay leaves more than a lot to be desired.', 'Mostly Positive', 79.60, 7.02, 4.67);
INSERT INTO reviews VALUES (49026, 2103680, 105, 'This game doesn''t have nearly enough reviews for how good it is.\n\nIt''s incredibly confident in its presentation, with some of the most uniquely stylish artwork I''ve seen in a game that does a fantastic job of presenting the setting as a lurid, neon-soaked hellscape that is nonetheless sensually tempting, tying in with the constant Catholic imagery and themes of Catholic guilt. The story is very much about a specific moment in time (post-Covid) for a specific group of people (wealthy Italian twin', 'There aren''t meaningful choices, there aren''t intelligible events, there aren''t interesting characters... Somebody ought to be writing a very-small-audience literary novel but thought they''d "write" a game instead. Onanistic.', 'Overwhelmingly Positive', 97.14, 6.73, 0.27);
INSERT INTO reviews VALUES (49064, 2104880, 100, 'Starcraft Silver League player here, this game is surprisingly challenging, subtle, and complex for a first time player. Definitely a bit more challenging than something like fallout shelter. The fact you have to earn the information on how to what features even are instead of a fully fleshed out tutorial + lack of more than 2 save slots + restarting new game every time you die, the procedural generation of levels being truly chaotic and encouraging re-rolling etc  may put off some other players', 'TLDR: Don''t Buy. This isn''t a full game worthy of your time.\r\n\r\nI want this game to work. I really do. The premise is amazing. It looks good... the problem is this game just DOESNT F***ing Work. Tutorial is not a real tutorial, its a story set up that teaches you BARE MINIMUM. Move to the campaign and its just... Atrocious. Workers "Stamina" is a joke as simply walking from top of a building to street level will burn half of it. So your rooms will be at stand-still more than actually producing b', 'Mostly Negative', 32.00, 108.72, 5.07);
INSERT INTO reviews VALUES (49065, 2104890, 3973, 'Ok, so I''ve seen a lot of confusion in the reviews - it is not Snowrunner, it is not Expeditions. This game doesn''t focus so much on simulating the big trucks and offroad experience. This is it''s own thing focusing rather on the aspect of completing objectives and removing the effects of natural disasters. The fuel consumption and most of the damage model that you''ve probably known in Snowrunner doesn''t exist here. There''s no vehicle customization as well.\n\nAs much as it seemed strange for me at', 'the game just feels so soulless, also has same issues as snowrunner did when it first came out, tail lights don''t work, engine sound is just a loop also not snowrunner related but the game has no day/night cycle or really any weather system unless scripted by a certain mission. its just always day and no real challenge. its hard to even get stuck anywhere and the physics honestly feel worse and your vehicles just feel like weightless toys. and cherry on top cause this is saber interactive cant w', 'Mostly Positive', 74.00, 3.52, 1.28);
INSERT INTO reviews VALUES (49101, 2105660, 217, 'I live in a similar hole.', 'The concept was interesting, but the narrative was pretty mediocre and so simple i was caught of guard while playing it, like "That''s it?".\nBut what made me refund it was the AI ART, i didn''t notice at it first, but it is pretty obvious, and makes me suspect the narrative was made with ai too, because it was very empty and not really fun to read. Like, you''re playing as the monster, it should be more expressive than that. \nI wouldn''t recommend it.', 'Very Positive', 85.25, 0.95, 1.15);
INSERT INTO reviews VALUES (49115, 2105910, 265, 'Truly excellent. I find the trailer doesn''t quite sell how brilliant, varied and creative the game is all the way. Levels are 4-5 minutes long but there are dozens of them and pretty much every single one brings a new mechanic. The game keeps reinventing itself through classic platformer inspiration (most obviously mario world) but shines with really clever level designs. Tons of secrets to find and the game has it''s own "language" on type of secrets so once you get the general design philosophy', 'Firstly, I think most people are finding this through the video of the dev acting butthurt about people not liking his game, which is fine and all, but it''s framed in a way that''s beyond narcissistic. There are hundreds of games that are good, and yet haven''t even a fraction of the traffic this has.\nYou have 251 reviews at the time of me writing this, bro: calling your game the "most underrated game on steam" is completely inaccurate. When I think of an underrated game I think of something like ', 'Overwhelmingly Positive', 98.87, 10.57, 1.00);
INSERT INTO reviews VALUES (49126, 2107030, 125, 'My childhood but better and now on PC', 'The game was not supposed to be like this. I bought it only because Block Fortress 1 represents my childhood and was one of my favorite games. Well, I can''t say the same for this one. Extremely unbalanced game, you don''t earn enough to be able to repair your base from a previous attack. I struggle to get past the second level at round 20 (2 Bosses in one round) when it should be a fun game, focused more on defense and building. Instead you will recive a game where you have to work hard and get a', 'Very Positive', 88.00, 41.73, 18.63);
INSERT INTO reviews VALUES (49127, 2107090, 468, 'Very nice (considering the fall of the KSP franchise due to Take 2''s incredible negligence) (don''t worry this game''s developer is not apart of Take 2 anymore)', 'This game is bare bones and should be labeled as early access. It wouldn''t have the positive reviews if not for the association to KSP1.', 'Very Positive', 86.32, 4.75, 1.15);
INSERT INTO reviews VALUES (49131, 2109270, 287, '\nEnglish + Deutsch \n\nWhat a cute, cozy, relaxing and addicting game. You create biomes by the cards you have, place the correct animals in them and gain points this way. There are currently 3 biomes (continental, Savannah, sea) and in the beginning, you start with the continental. Every time you reach the required points in the bottom left corner, you can a new piece of land which increases your biomes little by little. In the continental one, you must let it rain to turn the tiles green so that', 'wish it there was an endless mode like in dorfromantik. this game could have been amazing but because its "one solution to reach one of the scores" is not creating replay value, which is so sorely needed in a game like this, i would love to feel the magic that i can just keep going but knowing that there is a limit and a perfect solution with a ceiling just evaporates that magic feeling and leaves a sour tasting thought in my mind, knowing this is just that, a puzzle with an end.', 'Overwhelmingly Positive', 96.52, 10.05, 1.27);
INSERT INTO reviews VALUES (49137, 2111090, 221, 'Has a lovely artstyle and animations, but I''m about two hours in and I feel like I''ve seen 75% of the content already. I would recommend this as a fun thing to play with for a bit, but not as a game to seep several hours into.', 'it''s great looking but i think it''s really overpriced -- would guess that''s a big reason it didn''t take off more', 'Overwhelmingly Positive', 96.83, 1.98, 6.88);
INSERT INTO reviews VALUES (49138, 2111190, 4009, 'mullet madjack is a bright and exciting game that instantly grabs your attention with its unique style and charismatic main character. in the game, you control a daring hero who embarks on crazy adventures filled with action and humor. the dynamic gameplay, combining platforming and arcade elements, keeps you on edge every minute. the graphics delight with vibrant colors and detailed levels, while the music perfectly enhances the atmosphere of cheerful chaos. the hero''s unique abilities add dept', 'It takes 3 hours to beat and you''ll be bored by the end of it, because the gameplay is shallow and repetitive. The weapons and upgrades don''t do enough to change up the gameplay, and there''s a serious lack of variety in the enemies and levels. It''s really mindless and doesn''t feel rewarding in the same way as similarly fast-paced games like Hotline Miami.\n\nI loved the aesthetic and had fun for the first hour or two, but unfortunately the game never really develops beyond that. It''s all style and', 'Overwhelmingly Positive', 97.51, 4.00, 3.65);
INSERT INTO reviews VALUES (49139, 2111630, 175, '電車でＧＯ! 電車でＧＯ! 電車でＧＯ ＧＯ ＧＯ!!!', 'Good game, racist DLC pricing (if you''ve lived in Japan like me and seen their pricing you''ll know)', 'Mostly Positive', 73.14, 105.23, 16.63);
INSERT INTO reviews VALUES (49140, 2111870, 276, 'Im actually happier with the Single Player focused changes but i understand that people bought this for the co-op.\n\nWhat i don''t understand are the people review bombing the game for this change in direction. They''ve made it clear already co-op will still be there just that they will focus on refining the SP gameplay.', 'just buy The Ascent and play that instead. early access or not, i dont see a way for this game to change enough to be fun without them changing everything about except the genre and art style.\n\nhonestly, it has the makings of a perfect game but it fails. something is off.. its just not satisfying or fun really. run ahead a little, flip a switch, get trappded in a tight space you cant leave but enemies cn run right in the door thats blocked for you, so you just repeatedly empty the clip rolling a', 'Mostly Positive', 72.46, 2.12, 1.02);
INSERT INTO reviews VALUES (49144, 2113040, 177, 'you dont broke game = you lose\n', 'This is basically an idle game.  Refunding.', 'Very Positive', 84.75, 1.03, 0.08);
INSERT INTO reviews VALUES (49145, 2113850, 6407, 'This game has legitimately helped me start taking better care of myself. I''m pleasantly surprised.', 'I loved it until I found out their music provider uses AI art.\n\nSupport real artists, god damn.', 'Overwhelmingly Positive', 98.22, 873.45, 22.15);
INSERT INTO reviews VALUES (49146, 2113900, 499, 'Definitely scratches the Initial D itch. Physics take a little while to get a hold of, but the skill cap is extremely high, you definitely can/need to put in many hours to get good.\n\nPlenty of fun to be had in the lobbies too. \n\nLooking forward to see how this game develops, but as it is, already quite a fun experience.', 'Very poorly optimized game, despite its average graphics.\nEven with the lowest graphics settings, it remains unplayable for those without a high-end PC.\n', 'Very Positive', 86.17, 11.67, 0.23);
INSERT INTO reviews VALUES (49150, 2115390, 273, 'Honestly a $10 horror game coop that is refreshing every run. it doesnt feel scripted the ghost interactions are smooth and feel randomized enough to keep you on your toes. comparing to phasmo obviously phasmo is a well polished game but give this one time too cook and i wouldnt be surpised if it comes close. i love the game first 3 hours i played with just 1 other guy and we had a blast. TALL LADY TAKE ME AWAY', 'Its like if Phasmophobia was less fun, had less variety, and more artificial/scripted difficulty.', 'Very Positive', 87.55, 9.23, 2.28);
INSERT INTO reviews VALUES (49152, 2116120, 3308, 'I was a patreon supporter & a play tester back from when the game was in earlier development under a different title, I helped spread the awareness to people on social medias to let them know there was an Extraction shooter mainly focused on Solo & Co-Op. I''ve tested the game out on two different gaming PCs. The game did run very smoothly at one point, but the developer added in animations for all of the surrounding foliage in-game & that has heavily tanked the performance more than it should be', 'a wonderful idea once again spoiled by unreal engine 5''s unsuitability. this is everything i want, but i simply cannot play it due to unreal being horribly un-optimised mess for any older rigs.', 'Mostly Positive', 74.55, 23.42, 0.63);
INSERT INTO reviews VALUES (49153, 2116510, 229, 'So here''s the thing: this game is good. "Oh cute, they made a match 3 game with interesting mechanics and quirky humor!"yeah anyone can do that and they did. "Oh look at the meta jokes about game development!" Yeah yeah, breaking the fourth wall has been done before and they did it here.\n\nBut: for almost two straight hours, I was having fun. I was enjoying my time on Earth in a way that helped me forget about my woes and troubles and just slid those shapes around the board with not a care in the', 'everytime i play a videogame about videogames i die a little more\n\n', 'Overwhelmingly Positive', 97.38, 2.95, 0.67);
INSERT INTO reviews VALUES (49158, 2118810, 661, 'I don''t understand the negative reviews. To me, this game is exactly what I was hoping for so far: The overall atmosphere of FTL, combat that feels like Slay the Spire, and crew mechanics similar to Into the Breach. If people are looking for something else, I''m not sure what they expected because so far Breachway delivers on what it set out to.', 'Graphics and game concept are good. After the update the game feels like you could play any ship and have a chance; however.... \nIt is 100% against you. You could have a phenomenal build , but lo and behold an enemy ship (especially in the second system) is the near perfect counter to your build, and then after surviving that conflict  (to which you''ll most likely suffer severe damage) RNGeezus just so happens to make every node to the next space station a conflict zone...notwithstanding your re', 'Very Positive', 80.48, 2.07, 79.47);
INSERT INTO reviews VALUES (49159, 2119590, 137, 'game nya seru tapi sya dapat dosa karena fitnah teman saya', 'A game with potential, its can be extremely fun with the right people, but as off this posts date, its dead and only players on speak Portuguese, devs haven''t updated it since January..... their DC is just as empty as the game atm.', 'Very Positive', 85.40, 8.07, 15.30);
INSERT INTO reviews VALUES (49163, 2121100, 105, 'Great story so far. Definitely enjoyed the sexy girls, options, and overall atmosphere. Keep up the great work!', 'Two years on since its release and it’s still not finished.\n\nThe graphics and storyline are good, but given it remains unfinished after two years is unforgivable.\n\nDo not buy this game, not at least until it has been finished.', 'Very Positive', 82.86, 6.13, 19.42);
INSERT INTO reviews VALUES (49164, 2122090, 112, 'Finally x-com based turn based action game from WW2, fresh air into all the other generic games recently.\r\nI recommend to try also for pure hardcore gamers. Its pretty challenging, logic and strategy thinking is required all the time, like in good old games.', 'For 2003 this might have been a banger but wow is this bad. UI is awful, gameplay is slow and unintuitive. Like XCOM but worse in literally every way. Graphics look like this was made in 2007 (not kidding), all of the cut scenes take entirely too long, voice acting is clearly ripped from Google Translate, and written by people who clearly do not speak english. There are ZERO ui intricacies that I like, and compared to games like XCOM this just isn''t even close. Please just do yourself a favor an', 'Mostly Positive', 77.68, 6.98, 0.42);
INSERT INTO reviews VALUES (49167, 2124120, 2299, 'Another reason as to why indie gaming is constantly coming out on top at the moment.\n\nGreat gunplay, great loot variety, fantastic artstyle, sound and music alongside interesting characters.', 'Really not much to the game in its current state and it''s pretty boring. It has the skeleton for a great game it just needs some meat on its bones. \r\n\r\nWould recommend waiting for some updates before jumping in.', 'Very Positive', 89.47, 26.65, 4.62);
INSERT INTO reviews VALUES (49172, 2125420, 271, 'After playing Civ 7 I was delighted to play a game where obvious attention and care went towards the interface.\nPleasant traditional roguelike with really nice interface+controls and a lot of DnD-esque flavor. Reminds me a bit of DCSS and Incursion.', 'Use of AI generated assets in supplementary material makes me suspicious', 'Very Positive', 91.14, 1.35, 0.18);
INSERT INTO reviews VALUES (49173, 2125540, 342, 'A lot of the reviews seem to stem from poor communication from the dev. Just like a lot of the other reviewers, I was kinda bummed about the rush to 1.0. The dev/publisher posted a statement about how the scope of the game was being cut waaay back, and would only get one more major update. It felt kinda outta nowhere after large periods of inactivity and didn''t seem to do enough to justify a full release, to the point I almost left a negative review too. I thought they wanted to push the game ou', 'As the developers decided to abandon this, I really can''t recommend it at all. This could''ve been a really fun little game if they had gone further with it, as it is ''1.0'' is still just a glorified Early Access and nothing else. Avoid it, spend your money on games where the developers actually give a damn. Avoid any Dino Rocket games in the future\n\n12/05/2025 EDIT: So there has been rapid fire updates adding more monsters, types and so on. This is good, I am glad they are trying to get more out ', 'Mostly Positive', 70.76, 50.62, 48.80);
INSERT INTO reviews VALUES (49192, 2132560, 115, 'It''s only been 10 minutes and I already wanna bang diana', 'I really want to like this game. I''ve been following it since the announcement trailer. But now that it''s here, I''m not sure how to feel about it.\nStory wise it''s fine, I suppose. But there doesn''t seem to be a whole lot to do on the life sim side of things. The movement speed is a little slow, too. Sprinting feels more like a visual effect than actually making you move faster.\nThere have been a few bugs that blocked my progress until I restarted the game, which is quite annoying. Large portions', 'Very Positive', 89.57, 1.13, 15.65);
INSERT INTO reviews VALUES (49193, 2132690, 162, 'I''d recommend this game, but I''d suggest coming into it with an open-mind as it is a little buggy. While I don''t really know much about Bratislava or Slovakia in general, the game seems genuine with the setting it portrays and the troubled period following independence. Even though I''m really unfamiliar with Slovakia''s history I do find their sincere show of a time and place without hitting you over the head with it quite nice.', 'lots of sympathy for east european game development. big fan of soviet republic, witcher 3, et al. preordered kingdom come deliverance 2 blabla... love the idea of the game, but sadly the fps on my moderate system is soooooo bad (i have newest drivers, tried all settings, even lowest, max fps was about 40! so it''s not my hardware i guess) - it looked like a mix of the original Doom and Minecraft. so - much love for the project (born in GDR 1978), really, but the quality of production is waayy to', 'Mixed', 66.67, 30.67, 2.38);
INSERT INTO reviews VALUES (49201, 2134320, 516, 'very freaking funking fun like hot feraking fracking dang. fun little hiz to do its great', '', 'Overwhelmingly Positive', 100.00, 11.33, 0.00);
INSERT INTO reviews VALUES (49204, 2135150, 2369, 'I headpatted another adventurer to build more affinity, which caused them to lay an egg. Proceeded to fry said egg and gift it to them. They loved the gift and promptly ate their own fried egg.', 'I really wanted to like this game, but it''s just not for me. Too much basebuilding and management, not enough dungeoning. I approached it more as a roguelike but it''s definitely a hybrid survival game with roguelike elements mixed in. Fans of Elona/Elona+ will definitely be at home.', 'Overwhelmingly Positive', 95.91, 111.85, 3.70);
INSERT INTO reviews VALUES (49209, 2137760, 308, 'Experience the most different Survivor game for each career!\r\n\r\nWish you could play Butcher, Thief, Painter, Nanny, Policeman, Doctor!', 'I want to start with one thing.  This game has some awesome potential.\n\nThat being said, while I was playing, something felt off.  I couldn''t place my finger on it, so I kept going, enjoying the characters you can play and their unique individual playstyles.  I then realized that I was unable to dodge certain attacks, and was taking more damage than I do in other similar games.  Upon further investigation, I found that the direction I was pushing would randomly "stick" and I would not be able to', 'Very Positive', 84.09, 7.80, 7.60);
INSERT INTO reviews VALUES (49212, 2138710, 6127, 'The only bad part of Sifu, is it will ruin how melee combat feels in almost every other game that has it.', 'I want to like the game, but I just can''t. I no longer have the reaction time, and the parry/avoids window is exceptionally tiny. Also, the camera so often sucks. \n\nI played Dark Souls and Elden Ring and had no difficulty with them. Sifu is on a whole other level. Even Sekiro has a more generous time window than this.\n\nThe game will be fun if you have good reaction time and are willing to learn the mechanics, but it''s more frustrating for me', 'Very Positive', 92.51, 48.00, 2.53);
INSERT INTO reviews VALUES (49216, 2140020, 2664, 'So much nostalgia. Stronghold and Stronghold Crusader were the gaming cornerstones of my childhood! Anyone who likes strategy games but hasn''t played it yet I highly recommend it, these games charm is unmatched, played it in 2000s and I was spending hours just making most unpenetrable castles for absolutely no reason but fun, never got into other Stronghold games but this and the Crusader are my absolute favorite to this day. \nLooking forward to Stronghold Crusader: Definitive Edition.', 'No AI players in multiplayer\n\n1. Communicated as much as possible - sure, its not even mentioned on store page, so much to communicated as possible. Most people propably wont watch all your teasers and dev diaries on "remastering" when they want to get a bit of nostalgia, only to find out, we cant even go play coop...\n2. Refitting/creating a few dump-as-rocks bots is beyond scope. Slapping 15$ price tag on abandonware tier of game is not. Sure.\n3. Slapping copy-pasta "Sorry but not actually sorr', 'Very Positive', 82.73, 39.80, 13.55);
INSERT INTO reviews VALUES (49217, 2140100, 395, 'It''s a pretty fun Shoot ''em up Roguelite, very easy to grasp and with a good amount of variety. It has a really nice art style with the characters and a straight forward progress to unlock things.\nRight now it has few weapons and ships, and the maps, even though they look different, are not that interesting, but most of the upgrades are good and some changes the way to play. Also the movement is simple but responsive and with BARREL ROLLS included.\nIt''s addictive and entertaining to play runs an', 'Version 1.0 feels like it is half baked and we are sitting at version 0.5 with the amount of content available. 4 gun types, 3 missile types, 3 ships, 3 pilots, and no variability in perk selection. Not even any elemental upgrades to add slow, damage over time, etc. The game is so reliant on your primary weapon that it is completely up to RNG if you get those upgrades early to make a successful run. The game play itself is fun but the amount of content had me bounce hard off this one. I beat the', 'Very Positive', 82.28, 5.33, 2.80);
INSERT INTO reviews VALUES (49218, 2140330, 7038, 'im only playing this because NCAA 25 isnt on pc and not spending extra on another shit game', 'DO NOT BUY. THIS GAME DOES NOT WORK ON PC. \n\nWhenever I have attempted to launch this game, it simply does not launch. The EA App doesn''t properly load up and there''s no way to actually get into the game. \n\nDO NOT BE FOOLED INTO BUYING THIS GAME. IT DOES NOT WORK AND IF YOU RESPECT YOURSELF, YOU WONT GIVE EA A DIME FOR PRODUCING SUCH AN ASS-TIER PRODUCT', 'Mixed', 47.24, 9.83, 632.18);
INSERT INTO reviews VALUES (49220, 2140510, 3540, 'There are issues with the people that play this game, Throwers, cheaters, etc.  But the game is solid.', 'laid off modders that were improving the game for a sketchy publishing company + overmonetization', 'Mostly Positive', 78.08, 929.60, 384.28);
INSERT INTO reviews VALUES (49228, 2141730, 7640, 'I see lots of people complaining about a solo developer not being able to uphold his deadline, because of a technical glitch that is out of his control. These people forget that this game costs less than a combo meal at a fast food joint. $6, boys - and you get a UE5 horror game that can be played with up to six friends. Even if he wasn''t actively updating the game, if you can''t justify spending $6 for at least three hours of enjoyment, then I don''t know what to tell you. You either need therapy', 'was meant to get new levels end of 2024 and didn''t. most of the levels is just mindless runnning around until you find the door', 'Very Positive', 89.32, 14.85, 3.73);
INSERT INTO reviews VALUES (49229, 2141770, 255, 'I love this game. I''m battling some depression and anxiety, and I have a similar numbers-only game on my phone. I saw this and bought it on a whim. The learning curve was simple due to the other game I''ve played, and I love the "simplistic" modeling and shaders. It''s very relaxing and pleasing, and the ambient music is right up my alley. Definitely recommend!', 'The game is tagged as a city-builder, and has images with a lively city aesthetic reminiscent of games like Islanders. However, the game itself is a flavored-up version of 2048, where one must place 3 similar buildings next to each other to create one building with a higher level. There is no distinction between the buildings whatsoever, they don''t play any role and don''t interact with each other except for being merged. I''m thus a bit puzzled how this game qualifies as a city-builder, since the', 'Very Positive', 92.55, 9.00, 0.13);
INSERT INTO reviews VALUES (49234, 2142790, 15018, 'Well done. 10/10 \nJust one minor caveat, I would love to have the option to join in on the D&D, or the card games on Fridays at the Inn. Perhaps something to consider later down the line? ^^', 'I really really want to love this game, and I waited until I''ve played almost a full year (in-game) to write this review, but there is a glaring issue with it that prevents me from recommending it. If you are like me, you play this style of game to relax and play how you want. The glaring problem with this game is that the days are WAY too short. There is no slider option to make them longer, and the devs don''t have a discord or monitor the forums. Check my reviews ... I almost never leave a neg', 'Overwhelmingly Positive', 98.14, 38.37, 29.63);
INSERT INTO reviews VALUES (49242, 2144640, 195, 'I really don''t understand many of the negative reviews. Just like every other EA title, Endzone 2 is incomplete. This means features are missing and some things don''t work. What you should expect from a sequel in EA is there. Improved graphics and new systems or else why bother with a sequel and not just DLC for the original right? Yes the game is bare bones but it is also playable for the most part. If you liked the first one, it stands to reason you will likely enjoy this one once it is finish', 'As a fan of the first Endzone, this version is a huge disappointment. All the game-play that was fun from the first game was removed and we got a bland dumbed down version in Endzone 2. Basically, a mobile game version of Endzone 1. You''re better off just playing the first Endzone. \n\nYou might as well just be managing a spreadsheet, green arrows = good and red arrows = bad. Just plop down a building (all buildings look the same so its difficult to tell them apart) and green arrow goes up. That''s', 'Mixed', 67.18, 7.22, 0.95);
INSERT INTO reviews VALUES (49254, 2151290, 1133, 'this is the first game ive pirated (sorry) that i actually went on to buy on steam, bro made me hop back on my steam account which i haven''t used in over 2 years just to buy this', 'So let me get this straight, I''m a school that makes it to the college football playoff every fucking year and when i send $10m+ to a recruit bitchass ohio state makes the comeback of the century to steal the recruit and ruin my day', 'Overwhelmingly Positive', 95.94, 131.80, 40.82);
INSERT INTO reviews VALUES (49261, 2154330, 280, 'great story i know alot of people always say out its a sex game i dont care about that the storys matter in these novels least thats why i play them fantastic job', 'This game has NO sounds during love making or character interaction, just blasting OVERLY loud dry boring music. Some of the scenes are actually enjoyable to watch, if u know what i mean ;) , but that doesn''t mean i want to hear no character dialog or "sounds" while the scenes are playing. If u add actual people, environment/background, interaction sounds then I am MORE than happy to buy further games and support your studios work. Games like Genesis Order, Project Passion, are REALLY good Adult', 'Very Positive', 83.57, 15.15, 1.65);
INSERT INTO reviews VALUES (49264, 2155180, 998, 'The game is good, mechanics are well worked out but currently it''s lacking a real game goal. After playing for an hour I get a feeling "why am I playing this?". After some time the game just lacks it''s appeal and starts feeling pointless. Hope a proper campaign or more challenging maps would give this a better spin.', 'I enjoyed this game, it''s early access but there''s still a lot there.  The graphics are nice, the atmosphere is fairly immersive, and the music really kinda brings that home. It''s got a cozy feel to it. There''s quite a few QOL features that have yet to be added that would make the game less frustrating. The tutorials are OK, they really give you just enough to cause trouble and leave out a lot of specifics that you figure out on your own or from other guides online. After much trial an error for', 'Mostly Positive', 77.15, 47.58, 25.18);
INSERT INTO reviews VALUES (49266, 2155770, 219, 'I bought this game for $7.49 during the Winter Sale and it was worth it. Fun game, good concept, interesting story. However, there are a few negatives:\r\n1. Some of the puzzles are not intuitive at all. I spent at least 30 minutes trying to solve one puzzle and I eventually just brute forced it because there were no reasonable clues given\r\n2. There are only autosaves. There was one point where it had been 20-30 minutes since my last save and the game crashed. That sucked. (It was at the color puz', 'its not a bad game but\r\n\r\nPros: the graphics and worlds are decent and keep you involved. The story line is not bad and the voice acting was good.\r\n\r\nCons: The puzzles dragged on way too long. Trying to figure them out took me too long. And he boss fight was well not memorable', 'Mostly Positive', 73.06, 10.97, 6.30);
INSERT INTO reviews VALUES (49268, 2157560, 3141, 'come from the easy to grasp gameplay\r\nstay for the absolutely cursed questbooks', 'My god, another "Deluxe Edition" INCOMPLETE. You buy it and you don''t have all the characters. We are sik of this practices. The fact that is''t called "Deluxe Character Pass 2" it doesn''t mean you will have it in the Deluxe Edition. This DLC is not included.', 'Very Positive', 88.92, 106.62, 0.27);
INSERT INTO reviews VALUES (49274, 2158670, 120, 'Coming to this as an experienced RPG Maker dev, I can say Architect really is a dream come true for me. It might take a bit more work to get a basic game up and running than it does with RPG Maker, but that''s simply because Architect is a much more open and versatile piece of software. \r\n\r\nSupport on Discord has been great. Updates are constant, bug fixes are lightning fast. Great community and I''ve really enjoyed seeing the vastly different projects people are working on - from traditional 2d r', 'This product is not beginner friendly, and if you''re first starting out, stick with RPG Maker MZ. I get the program gets a lot of flack, but you don''t have to spend almost an hour just to find out how to make a new map. Also the resources provided in the game are not clear in terms of dimensions. I have to keep starting/restarting my project just to select ''32'', and even then there seems to be no character models that work. Also the tilesets are weird in 3D. I put down a simple mountain, go to p', 'Very Positive', 93.33, 765.38, 0.63);
INSERT INTO reviews VALUES (49275, 2158730, 717, 'Got railed in the ass by my homeboy for 17 minutes. Then I installed Hand Simulator: Rendezvous. This game is a masterpiece. It offers more of a complex challenge than Elden Ring. Theirs hours of content to be explored and beautiful maps. This game is truly the best cinematic achievement of the modern age. This game is so good. I could go on and on for hours about the complexity of this game and the challenge it produces to the players with satisfying achievements to show your friends that you''r', '1. Homie and I played Hand Simulator\n2. Homie says to buy this\n3. After finally grabbing **** me and bro stroke it\n4. Game finally Installs but we didnt end up playing', 'Very Positive', 86.61, 1.28, 0.27);
INSERT INTO reviews VALUES (49285, 2162800, 6597, 'The most important thing first: The game starts with 70% music volume and an overall volume of 50%. Why can''t all games do this? \n\nGameplay is nice. Game runs smoothly. No crashes.', 'More puzzle than factory management. \n\nThis doesn''t really offer anything interesting over shapes 1 other than being in 3D. The game-play loop is as follows. Get task to make a shape, build factory to make said shape, delete factory once shape is not needed. For me this loop is tiring, I never get the "factory must grow" feeling or the feeling like I am working towards something.', 'Overwhelmingly Positive', 98.26, 45.12, 0.62);
INSERT INTO reviews VALUES (49289, 2163590, 140, 'For some reason my mom got me this for my Birthday - 11/10 story and gameplay!!!', 'There is barely any game play, it''s just a click click click style game with some extremely boring mini games that pop up to avoid it from being just click click click. There''s no saving feature like most visual novels and not even a roll back feature for what little choices there is. I had to stop playing cause I got so bored by the story a few minutes in. I don''t remember when I purchased this or the 2nd game so I doubt Steam will refund it but at the very least I know not to buy from this dev', 'Mixed', 53.57, 16.63, 0.13);
INSERT INTO reviews VALUES (49295, 2166060, 3717, 'With there being a LOT of indie horror games using the "innocent children content" as the fear factor, this one still feels unique and fun to play. Amanda the adventurer feels like an escape room of sorts with most if not all objects being used at some point to get to the end of the game. The concept of having Dora The Explorer type interaction to have an effect on the progression and attitude of a character like Amanda is something I am surprised hasn''t been done earlier. Playing this with AKMo', 'requires guide to play wastes your time and just gets annoying after awhile. Just watch someone else play and save your money.', 'Overwhelmingly Positive', 95.48, 1.92, 0.98);
INSERT INTO reviews VALUES (49343, 2167220, 671, 'I saw that Atheists were trying to report this game to get it taken down. The Devil works hard, but God works harder. \nChrist is Lord y''all.\n\n-Rastaban', 'Knock-Off of Ultrakill, and doesn''t have the Bible Fanfic, Dante''s Inferno DLC', 'Very Positive', 87.03, 0.10, 0.37);
INSERT INTO reviews VALUES (49383, 2168260, 139, 'After 77 hours this is my take on Forgotten Seas: I don''t recommend or unrecommend early access games. But being an old retired fart I have a soft spot for these efforts, even if some of them are just easy money grabs. Forgotten Seas has an interesting approach, but a long way to go, and I hope they keep going. Today I decided to take a break until next upgrade, because I started to get stressed and vexed. If I wanted to be stressed I will go out of retirement and back to work. Too much repetiti', 'I''m all for janky amateur projects, but if you''re charging someone over $20 for a game about being a pirate, at the very least I expect you to have put some basic effort into the sailing physics. Instead, we get boats that just feel like a default character controller slapped onto a boat model: zero momentum, zero weight, and overall unsatisfying.', 'Mostly Positive', 79.86, 77.07, 0.45);
INSERT INTO reviews VALUES (49387, 2168450, 237, 'every copy of dreamwild is personalised', 'great aesthetic, good soundtrack, but unfortunately i don''t think it works as an arena shooter. alone the fact that your only source of health/currency flies and bounces around the map until you can collect it manually instead of it being added directly to your inventory is pretty frustrating. the game is meant to be fast-paced and you can''t really slow down to collect them without dying. in the end i just found myself killing enemies as i went and then hoping i would stumble across their drops ', 'Very Positive', 89.03, 3.65, 1.40);
INSERT INTO reviews VALUES (49396, 2168680, 3199, 'Simulator disguised as an arcade game slowly tricking you into learning things. On the surface is just seems like a fun colorful sandbox aircraft game, there''s big explosions, cool planes, and extremely simple controls that are very intuitive. However, underneath are realistic aircraft flight models that even rival expensive simulators, weapon systems that function like real weapon systems, sensors that work like real sensors and the best aircraft damage models that exist anywhere, bar none. Thi', 'I really really like playing this game.  I really really can''t support it anymore and am requesting a refund due to a singular community member.  Their behavior ruined multiplayer for me.  Their attitude about said behavior was abusive. The member being a moderator is apparently immune from the rules about harassment.  Other staff is working hard to silence any critics of said community members behavior, including removing reddit posts, banning discord users, and deleting steam posts.\n\n\nEdit aft', 'Very Positive', 94.22, 241.28, 158.18);
INSERT INTO reviews VALUES (49410, 2169120, 172, 'This series has been a lot of fun so much so that I am devastated by the time frame I will have to wait for a sequel.', 'I really want to recommend this game/series but the lack of any sound, art, and anything to make it not just a book, i can''t. The series''s story is really good but it feels like the game wants to make you go to sleep.', 'Overwhelmingly Positive', 95.35, 16.27, 7.62);
INSERT INTO reviews VALUES (49414, 2169200, 1405, 'They should have called this Sniper Elite 5 part 2 because it feels more like an expansion for SE5 rather than a new game -- but the main thing is that it''s fun, especially for people who can''t keep up with faster paced games like CoD. I do think it''s time for a fresh take on Sniper Elite, maybe set in Vietnam or outside of WW2.', 'Sniper Elite 5 DLC, but more expensive.\n\nIf you''ve played SE 3-5 you''ve played this one already. If you''re new to SE go get SE 3 through 5 on sale. \n\nIt''s OK. It''s not SE 6 and it''s not named SE 6. It''s just more SE 5. I''m a fan and knew what this game is so it''s OK for me. If you''re expecting something new you''ll be disappointed.\n\nBut the price is just too high for the general public. When all the content is released and goes on sale I think it will be worth it. It should have been a DLC, but I', 'Mostly Positive', 71.74, 22.45, 22.28);
INSERT INTO reviews VALUES (49443, 2169950, 109, 'Very fun. I love the art and character designs. Especially Taketora.\n\nUpdate. I will say that it would  be nice if there were some more updates and added layouts in the games levels. Because for now it is very rinse and repeat with little variety to enemies, bosses layouts and scenery with each stage and even resting points. But I still recommend Yasha. It is fun and has allot of potential to keep growing like many action rouge games we''ve all come to love. \nPlus the art is just wonderful. I rec', 'It has potential, the fight is fun and smooth, but only last 1.5 hours.\nIt is bugged after first round, cannot proceed at the result screen.\nNow I was locked at the death circuit, enter game, fight the last boss, result screen came out, then cannot proceed.\nAfter all I spend 26 USD to play 1.5 hours and bugged.\n', 'Overwhelmingly Positive', 95.41, 3.47, 8.28);
INSERT INTO reviews VALUES (49496, 2171440, 6066, 'sat in a confessional, confessed to murdering someone, told them it made me horny, get called a terrible person, killed the man i confessed to, went home and played fear and hunger', 'hate this game cant sell the child for free claymore', 'Overwhelmingly Positive', 97.49, 69.13, 21.97);
INSERT INTO reviews VALUES (49506, 2171630, 101, 'First and foremost I want to say to the devs that although many of the reviewers dismiss the English translation as laughable and funny I think that it''s probably the biggest problem with the game in its current state because a lot of potential players will likely be immediately turned off by how confusing it can be early on even before the automation quest starts. \r\n\r\nThe game so far reminds me of Core Keeper and Keplerth with a bit more focus on automation. There are some hefty pacing issues w', 'I don''t currently recommend the game for english speakers. The translation is 90% nonsense at the moment, like they just ran the whole chinese script through Google translate and pasted it straight in, which makes quest logs and instructions almost useless. \r\n\r\nThere is also a huge amount of automation and grinding needed at the 2nd layers and beyond, which really slows things down too much.', 'Mixed', 68.32, 11.62, 14.25);
INSERT INTO reviews VALUES (49516, 2171840, 110, 'There is a lot of depth to this game. I spent almost 8 hours on it. The match 3 is on point. The art is decent.', 'Generic match three that overstays its welcome. Very little variety, no story, and the art is generic.\r\n\r\nEven at discount, there are better takes on this game genre. Only buy it if you''re running out of cheap games to play. \r\n\r\nI''m only pushing through the rest of the levels out of spite. Don''t make my mistake, get out while you can.', 'Mostly Positive', 71.82, 7.90, 5.35);
INSERT INTO reviews VALUES (49524, 2172010, 1299, 'Started playing upon release at midnight and kept playing until dawn—10/10 highly engrossing!', 'Doesn''t even let you go to the main menu without PSN.\n\nExtra accounts for Singleplayer games shouldn''t be normalized.\n\nPS: You can play the game without PSN via opening the "Bates-Win64-Shipping.exe" located in the game''s directory. You''re Welcome', 'Mostly Positive', 79.83, 14.10, 0.17);
INSERT INTO reviews VALUES (49533, 2172260, 867, 'I took some shrooms and played through this game and... wow. This game is absolutely beautiful. Every inch of liminal space was just perfect. It scratches your brain in such a nice way. What I love about this game is that there really aren''t any entities (other backrooms games get kind of cringe with it), so this was truly refreshing. The scariest aspect of this game is the ambience. The dead silence. The design. The radio music. The liminal spaces themselves. Everything was just so insanely put', 'I am hoping more gets added to this game. Whats there is pretty good, but it costs money. The Complex: Found Footage is free, longer, and you experience far more. Expedition is the paid version and as of right now, it feels like I paid for a massively watered down version of the free "demo". \n\nI will not refund it, though. The developer is clearly talented, if a bit inexperienced.\n\nAs of right now, however I cannot recommend this game.', 'Very Positive', 91.93, 3.25, 1.92);
INSERT INTO reviews VALUES (49558, 2172860, 161, 'I really wanted to play this for the lovecraftian horror aspect of it and it was pretty good. dull at times where it felt like it dragged on. but i mean given its inspiration i get it. No the only thing that really bothers me is some of the boss fights were obnoxious and boring. sat here for 45 minutes fighting one of em and just watched a show on my other screen because it was pretty simple to keep from dying but the health pool was massive so it was just a long boring slog to get through. This', 'Gotta be one of the most boring dlc''s, horrendous dialogue for a chapter, bugged quests (lmao), and the class is still having the same issues it had on release, would not have bought if it wasnt for the class', 'Mostly Positive', 71.43, 0.00, 0.00);
INSERT INTO reviews VALUES (49560, 2172900, 102, 'This one is for the doggos! Super cute little game about raising and walking your dogs around some nice trails. There are a bunch of mini games, some great scenery, and a bunch of different dogs to collect. \r\n\r\nEach dog has stats to level up so they can perform better in construction projects as well as the different mini games. This would likely be a great game to entertain your kiddos since it''s very easy and relaxing to play through.', 'IVE PLAYED FOU 2 HT', 'Overwhelmingly Positive', 99.02, 14.93, 20.60);
INSERT INTO reviews VALUES (49597, 2173760, 139, 'Easy to learn, difficult to master \n\nPerfect easy going retro golf game and runs perfectly on the deck. \n\nSoundtrack is probably well worth the extra £1.50 too', 'I first thought it is a good game, just a simple golf to kill some time. Then I realized that all greens are the same shape with the hole in the middle, with only some slight elevation differences. No par 5 holes at all also. The game gets boring and repetitive quite fast due to reason mentioned above. Sadly I can''t recommend it at this point.', 'Overwhelmingly Positive', 95.68, 5.72, 3.25);
INSERT INTO reviews VALUES (49599, 2173800, 1343, 'Probably the worst "adult" game I''ve ever played. How can you expect me to be horny when I''m truly involved in the plot and the characters while also laughing my ass off? \n\n10/10, Funny, Sexy, Silly, Well written. \n', 'A bit mixed to be honest. Sex scenes were... subpar but that''s okay since the story was quite awesome. Cyberpunk/scifi setting really gets me going and the Star Trek thematics of different species integrated into the societies, FTL travel and dystopian concrete hells all combined was a great treat. Also the game has some really good humour going on - I really enjoyed all the jokes, puns and situational comedy presented in the game.\n\nWhy did I downvote? It is not a complete story. These uncomplet', 'Very Positive', 93.37, 12.58, 8.23);
INSERT INTO reviews VALUES (49603, 2173900, 144, 'honestly this game is way better than regular sex with hitler i speedrunned it and beat it and came at the same time 100/10', 'adolf could be packing more ngl', 'Very Positive', 86.81, 0.15, 117.18);
INSERT INTO reviews VALUES (49627, 2174500, 168, 'This is a very good game, as the big blue box indicates it is an early access title and is not yet finished development. The writing is overall very good, the game and world is very interesting, and the characters are overall pretty likable. I first played this game a while ago, and it has gone through some major changes since then.\n\nI will say I only have one complaint at this time for the game, and I don''t think it will be a permanent problem. The H scenes do not look like the regular characte', 'Not worth full price right now, plus already announced dlc with scene unlocks and manual. Game is gimmicky  with progress route and paying for manual for game i already paid is incredible greed.', 'Very Positive', 89.88, 8.65, 8.88);
INSERT INTO reviews VALUES (49666, 2175390, 128, 'If you are new to VN and new to P0rn VN, dont buy that, its worthless lol.. directly go to ''''Being a DIK'''' or ''''Acting Lesson'''' or ''''Leap of Faith'''' if you are not new to VN, this is okay, its a regular VN with okay story, okay graphic, okay everything. \nThis game is unremarkable, yet, and its important : It okay to buy it, play it, (enjoy it) then delete it.\nIts more story driven than p0rn driven and lol choice DO REALLY MATTER! I''ve actually got the bad ending playing with ''''guts feeling'''' .. ', 'Entertaining enough. The main character is unlikable, dumb via bad writing, ugly as sin. \n\nthe writing is pretty bad. There’s a lot of strange (presumably translation) word choices like saying “she stops caressing your organ.” Or calling dudes in a modern bar “bandits” repeatedly. \n\nScenes between characters suddenly happen with no chemistry or build up. The animations are extremely brief and the MC basically doesn’t react after the deed is done. Both of the characters continue on as if they did', 'Mostly Positive', 79.69, 7.28, 2.60);
INSERT INTO reviews VALUES (49675, 2175540, 292, 'This game rules. I logged 90 hours on switch and I''m excited to get all achievements on steam. Same game but it runs better because PC. Late-game areas may still be unoptimized idk. (My review will be edited if there''s major issues with the PC port).\n\nAnother DQ Monsters banger. You scout monsters, level them up, breed them to make better monsters. The game provides a story mode progression and a CPU-control-only arena progression reminiscent of the original DQ Monsters. The story is decently lo', 'As of writing I have finished all content in the game, with the exception of 100%''ing the monsterpedia. My playtime is around 50 hours.\n\nI really can''t recommend this unless you adore dragon quest or the dqm series. The games performance and graphical fidelity are poor, and the paper-thin story and lifeless way it''s presented only highlight this fact. The battle and creature collecting gameplay is fun, but the difficulty spikes a bit artificially towards the late game unless you grind, especiall', 'Very Positive', 84.93, 56.80, 52.72);
INSERT INTO reviews VALUES (49728, 2176790, 271, 'Better than R6', 'The "furry" stuff is NOT integrated with the gameplay - it''s only videos within a menu.\nThere is NO single player.\nThere is NO players for multiplayer.\n\nThis is only an Unity asset flip and a bad one at that.', 'Mostly Positive', 70.48, 0.08, 10.32);
INSERT INTO reviews VALUES (49784, 2178070, 830, 'With over 10 hours played, with all settings on EPIC, ZERO crashes, and very few bugs, I can say with 100% certainty that this game is incredible! Absolutely stunning! Cannot stop playing it! Forget all those bs reviews of childish people throwing a fit that an early access game isn''t "polished and flawless", wake up to reality, your instant gratification seeking will get you NOWHERE in life. \n\nThis game has restored my faith in game devs. The world is stunning, the gameplay is smooth, the comba', 'My friend and I bought this game hoping to play together. We knew the multiplayer mode was still in early access (like the rest of the game), but we thought it would be fine as long as at least one of us could progress through the quests.\r\n\r\nHowever, the quests are actually **BLOCKED**. Story and quest progression can only be done in single-player mode. We managed to reach the Sky God, and all he said to me was, "Thanks for bringing a visitor."\r\n\r\nThe game is visually stunning, and the creature ', 'Mostly Positive', 76.27, 18.37, 23.75);
INSERT INTO reviews VALUES (49798, 2178330, 395, 'Artist''s name : namako8982', 'I''m not a huge fan of having to protect an object instead of enemies just coming at me. \n\nI don''t feel like it serves the genre very well.', 'Very Positive', 88.61, 14.77, 1.12);
INSERT INTO reviews VALUES (49815, 2178590, 320, 'Game is trash, but the devs are kinda based', 'Terrible game, don''t waste your money', 'Mostly Positive', 78.75, 0.22, 0.13);
INSERT INTO reviews VALUES (49841, 2179170, 1086, 'I spent 4 hours looking for cats, barely blinking, tears rolling down my face while my eyes twitched... but it was worth it', 'For the love of God, when you click a cat you found, IT SHOULD MEOW!\n\nRight now, it just chimes. Why... why would a cat NOT meow... in a cat game. Please fix this.', 'Overwhelmingly Positive', 99.54, 3.78, 2.30);
INSERT INTO reviews VALUES (49853, 2179380, 360, 'It was a good game, but I wanted to refund to save money. I totally recommend it though!!!', 'Its alright but there are WAY better options. The powder toy is free on steam and has much more content. Get the powder toy dont waste your money on this.', 'Very Positive', 94.17, 0.28, 1.58);
INSERT INTO reviews VALUES (49855, 2179440, 138, 'Request to add Moonboard 2016 in a garage map + ability to edit climber''s height and some hangboards ofc (not kidding) 😁 Fire game tho 🔥🔥🔥🔥', 'The idea is great, and I get the concept is a hard one to build, but its just frustrating. The biggest issue is the lack of correlation between textures and holds. At crevecoeur castle the appear to be cracks and holes i can fit my head in, so you go there and find no holds... fall... repeat...\r\n\r\nIt makes this like the escape rooms where you have to put your mouse on the right pixel to get out.... just move the mouse till you find green...so you will rage quit a lot (which requires alt-f4 becau', 'Overwhelmingly Positive', 96.38, 4.20, 14.75);
INSERT INTO reviews VALUES (49873, 2179850, 2801, 'It has it. It''s got that spark. It''s got that magic in it. It has that itch you love to keep scratching. It''s got characters you love to see. Deck building roguelite shenanigans that you love to partake. It''s not too hard, it''s not too easy. And you can change that if you want. And after going at it run after run, just having a good time doing it, piecing everything together, you are finished extremely satisfied. It''s not too over the top, it''s not making promises it can''t keep. It''s a wonderful', 'Prefacing this with Cobalt Core is not specifically a bad game, but I can''t recommend it when you compare it to other games in the rogue-like genre or deck builders. I will say the aesthetic and humour is good, UI is done well.\n\nThe game is very well balanced to the point of it being an issue. Builds never feel like they pop-off like in say Slay the Spire or FTL. Choices feel less impactful than other games in the genre. It feels like game play needs to be more...RNG? Spiky? Higher highs, lower ', 'Overwhelmingly Positive', 97.04, 67.63, 12.53);
INSERT INTO reviews VALUES (49941, 2181610, 1700, 'It is incredibly alright. Perfectly decent. Quite playable. The mechanics are engaging while you''re learning them, and feel pretty alright to exploit when you''ve mastered them. The art is definitely average or better.\r\n\r\nBut, like, you see the problem? Nothing about the game is truly spectacular. There''s no moment where it really CLICKS and you love it. You get to the end of a run, and you''re eager to push through Endless, except you''re already pretty much maxed out in upgrading your defenses al', 'It suffers from a fundamental flaw mechanically that unlocking more content reduces ones ability to beat the difficultly curve that you are trying to stay ahead of by playing cards in the first place. The only way I could consider combating this is by allowing the player to create/pick deck sets that dictate the theme of the cards in play.\n\nOtherwise it is a good game to have on the side as you do other things and it has a unique story telling style that you can engage with as the player via the', 'Very Positive', 87.24, 10.65, 25.62);
INSERT INTO reviews VALUES (49947, 2181720, 615, 'Many thanks to the developers:-)  I''m having a lot of fun :)). I can recommend it to anyone who likes this kind of game.', 'This game is a horribly balanced grind fest. Some of the characters are basically useless while others are overpowered. Try it and you''ll see what i mean. This game is only good if you want to zone out and kill time.', 'Mostly Positive', 79.19, 33.25, 63.72);
INSERT INTO reviews VALUES (49958, 2181930, 1608, 'years worth of brain damage in just a few minutes', '\nFeels more like a spoof than actual game with reliable gameplay. Way too chaotic with no actual goal you just rush and spam your bullets with dr. Livesey and his crew. Game appears to be roguelike pretty much with some random booty you collect along the way to buy new stuff. There''s no map so good luck with finding your way through this maze. I would say go watch cartoons it''s much better experience unless you''re looking for some serious psychedelic experience or just easy achievements...\nDon''t', 'Very Positive', 91.67, 0.35, 4.30);
INSERT INTO reviews VALUES (49960, 2181950, 114, 'I enjoyed it. I''d recommend it with one caveat: It''s *mind-numbingly* easy. This might be the easiest Deckbuilder since Mahokenshi. \n\nThere''s a lot of degenerate combos and a lot of just incredibly powerful abilities, and the Failsafe system makes those degenerate combos consistent between runs. This game needs a *lot* of balance changes. Even on Max difficulty with all the modifiers turned on, it''s easy to build your operators and your deck so that every combat ends on turn 1 before the enemies', 'Clicking &/or dragging cards doesn''t work ~60% of the time. Which is bad because that''s the point of these games.\n\nCards look cool\nNice setting\nMusic is great\n\nBut gameplay is just broken', 'Very Positive', 89.47, 13.55, 0.62);
INSERT INTO reviews VALUES (49990, 2182630, 232, 'Fun and simple, zero replayability as far as I can tell besides being optimal with island choices. Hopefully future updates will change this but currently this is a mobile tower defense game with some grinding.', 'Feels unpolished and unfinished. Hasn''t received an update in 5 months so I doubt this will get better anytime soon? Would be really happy to be wrong though love the concept!', 'Mostly Positive', 73.71, 19.30, 18.48);
INSERT INTO reviews VALUES (50058, 2183900, 74073, 'Finally, a solid game, with solid gameplay, various modes, and an a variety of customization options, without all the crappy microtransactions. This is my first Warhammer 40k game, I have no idea what''s going on lore wise lol (for now) but i''m happy to be a part of this community!', '9/10 but can NOT recommend.\nThis trend of corporatocracy needs to stop. I shouldnt need 3 accounts (steam, epic, saber) with 6 EULAs (steam account, epic account, saber account, in-game EULA, steam purchase EULA, epic service EULA, and maybe more that I forgot) just to have my consumer rights degraded. Forced arbitration, not actually owning the media you buy, and having to run what surmounts to spyware even for single player, battlepasses and predatory monetization everywhere. None of this shou', 'Very Positive', 86.15, 45.98, 11.13);
INSERT INTO reviews VALUES (50074, 2184150, 193, 'It''s a great game. with beautiful graphics. It has huge potential, but requires a lot of work from the creators. If the creators gave their 100% attention, this game has a chance to become one of the best zombie games.', 'I was 17 when this game first caught my attention.\r\nI am 25 now, with a wife, child, a paid off car, and a mortgage...\r\n\r\nWhere''s the fuggin'' game guys?', 'Mostly Negative', 30.57, 26.38, 1.13);
INSERT INTO reviews VALUES (50079, 2184230, 157, 'Climbing the corporate ladder brings you closer to Lucifer. F%cking hilarious. And very true.', 'I suck at the ending platforming level.  I hate it.', 'Very Positive', 87.90, 1.68, 1.33);
INSERT INTO reviews VALUES (50086, 2184350, 107, 'A very promising turn-based RPG that is heavily influenced by Divinity Original Sin 2''s mechanics. Honestly, if you are going to emulate another CRPG combat system, DOS 2 is an excellent choice. Normally, I''m turned off by pixel art, but the use of modern rendering techniques for lighting and VFX does wonders for the pixel art style.\r\n\r\nI have a couple of gripes I''m hoping the devs will address:\r\n1) Combat pacing in the early game - I''ve been playing CRPGs since the early 80''s. I expect early co', 'Don''t trick me into wasting my starting healing items on a forced loss battle 5 minutes into the game.', 'Overwhelmingly Positive', 96.26, 4.45, 0.27);
INSERT INTO reviews VALUES (50121, 2185060, 2385, 'Worth the $40 if your into 2point games. This is an improvement on Hospital and runs great. It''s shocking to have a completed game that runs well on release day in 2025.', 'Fun game up until the Thieves are unlocked.  The thievery mechanic needs to be completely overhauled, because it ends up pulling focus away from all other game aspects. Unless you like having hours of your real time literally stolen by this poorly-designed "feature"...', 'Overwhelmingly Positive', 95.47, 96.05, 16.47);
INSERT INTO reviews VALUES (50142, 2185780, 118, 'Very Nice :D', 'Dieses Programm will ständig Zugriff auf meinen Standort haben.\nNever trust china spy software -.-', 'Mostly Positive', 77.12, 101.55, 0.32);
INSERT INTO reviews VALUES (50166, 2186320, 3573, 'game is very cool but i wished it had geopolitical roleplay and events. if it was more in-depth and realistic into roleplaying, it would be my favourite game on steam. ignore the grammar... i''m holding pizza at the same time typing this.', 'A fun concept, with the depth of a puddle. Maybe this game will be worth it when it''s out of early access.', 'Overwhelmingly Positive', 96.84, 4.18, 0.70);
INSERT INTO reviews VALUES (50186, 2186680, 12856, 'A great classic RPG. All the tropes I wished for. I''m a massive 40K fan and played the Pen&Paper RPG this is based on for years.\r\nTotal victory on the flavour, setting and atmosphere side.\r\nRogue Trader reminds me much more of Baldur''s Gate 2 than BG3 does, which is a win in my books.\r\nBut I am bitter and old, so make of that what you want.', 'Quite enjoyed this game at first, but the devs have decided several patches in a row that major nerfs to player skills were the correct approach. While players could certainly make "overpowered" builds before, I don''t feel nerfing a single player game months after launch is a good approach, and will always thumbs-down it.\n\nIf you want to make things harder, add specific fixes/changes/enemy counter-skills on the higher difficulties. Don''t take away power fantasy on normal (or easier), it''s just r', 'Very Positive', 83.67, 66.55, 240.43);
INSERT INTO reviews VALUES (50187, 2186700, 253, 'First let me tell you something. For this price, while it''s cheap, buy it! I wanted to give credit to the developers. I say this because nowadays it''s hard to find these right mindset developers. Let me explain, they failed hard at launch, but they are trying to make it work. They released tons of patches and added many requests to the game. Yes, manly like you i did not buy the game at release after seeing all those videos about it. And thought they would abandon the game after that. Also, seem', 'The developer team of this game has announced that the game development has been delayed, and they said the next update will be releasing in summer 2025. The current version of the game is buggy and bad optimization. If your PC is not good enough, don''t try the game.\n\n', 'Mixed', 57.71, 1.35, 4.30);
INSERT INTO reviews VALUES (50207, 2187220, 716, 'This series is so good. I wish lawyers were real.', 'the logic in this game does not connect like it does with the rest of the series', 'Overwhelmingly Positive', 97.21, 84.42, 34.22);
INSERT INTO reviews VALUES (50209, 2187290, 3211, 'Great game, so easy to lose track of time while playing. Loved everything about it. I wish there was more content so I could put even more hours into it.', 'Wall World is by no means a terrible game, but its very core mechanic is flawed.\n\nMining for ores and for artifacts is fun, yes. Using them to unlock better gear also. But this is only a part of the game. \n\nThe other part is fighting against waves of enemies. And this is very repetitive. When you have a new profile they will attack you after only 90 seconds. You can extend this by finding and upgrading an artifact, but these waves keep coming and coming. Everytime, you have to rush out of the mi', 'Very Positive', 89.94, 92.33, 40.77);
INSERT INTO reviews VALUES (50293, 2189640, 178, 'AI of the enemy is pretty good.\r\nBut game is too short, should have maded more keys or something that would make gameplay longer.\r\nOther than that very good game.', 'Controls are kinda annoying but it''s even worse when the cannibal spots you.\n\nBeing chased is rather boring and backtracking to a hiding spot feels like a waste of time.\n\nIt''s a short game but it was a rather boring and annoying experience. Just watch it on youtube.\n\nNot worth the money nor the time.', 'Overwhelmingly Positive', 95.51, 1.17, 1.13);
INSERT INTO reviews VALUES (50321, 2190220, 350, 'this is proof that undyne will appear in touhou 20', 'I been play for 2 hours and decide to write a review about this game \nEven I''m a huge touhou fan but I''m having hard time to enjoy this game \nthe story is wack . gameplay is base , also have some unnecessary mechanical like skill card , I mean too much reading for a rhythm game , not only that , difficulty setting is not user friendly too , easy and normal is 4k rhythm game and hard and lunatic not only became 6k rhythm game , at the same time have a HUGE difficult gap that is hard to learn as a', 'Very Positive', 87.43, 2.67, 3.70);
INSERT INTO reviews VALUES (50368, 2191190, 266, 'Previously, I played only the first one in this series. So, I decided to "cheat" a little bit and jump to episode number 4. Why? I wanted a relaxing experience so I looked up the achievements. In previous instalments some were tied to completion time and there were even different difficulty settings available. Here all ''cheevos are tied to finding various items and completing the levels and puzzles. And that''s it!\n\nWhat this HOG does differently compared to most is that you have to find a lot of', 'I wish you could zoom in and out, it was overall rlly hard to enjoy for me! (but I love the artstyle)', 'Overwhelmingly Positive', 99.62, 1.85, 1.60);
INSERT INTO reviews VALUES (50427, 2192620, 100, 'These Girls are Gay.\nGood for them. \nGood for them.\nYoru and Sayoko Best Dynamic', 'Ghostpia\r\n 7/10 \r\n It certainly has the passions, but is a hard sell\r\nLenght: Around 9 hours\r\n\r\nGhostpia is a story about a group of four friends—quite literally. Despite the game''s interesting setting and atmosphere, for the most part side characters are not really interested and lack some connection to the main group. They''re merely passing characters who don’t return for the most part.\r\n\r\nProbably a big factor to enjoy the game is if you are really enthusiastic about subtle Yuri stories, beca', 'Overwhelmingly Positive', 96.00, 7.93, 10.05);
INSERT INTO reviews VALUES (50437, 2192790, 307, 'What happened Rick I thought you weren''t a beta anymore, ain''t that what you said? Even right here right now you''re not gonna rizz me for it? I''m better looksmaxxer than you, Rick. \n\nI''m better for Lori than you, man. ''Cause I''m a better sigma than you, Rick. ''Cause I can mew and I can jelqmax. But you come back here and you just destroy my edging streak! \n\nYou got negative canthal tilt...  You got prey eyes... You ain''t got the first clue on how to lock in.', 'WOW, This game is horrid. Would rather be tied up and tortured for hours on end. Love the Walking dead, But what is this shit. Even if it was free it wouldn''t be worth the computer space. Anyone who has played this game should be financially compensated for giving any amount of time to this game. \n\n10/10 Would never even look at this game again!', 'Mixed', 43.32, 11.98, 1.63);
INSERT INTO reviews VALUES (50449, 2193070, 166, 'this game best story but exited for jennifer in here but i hope have inside jennifer chapter 2 or season 2 pleaseeeee', 'Copy paste the same girls from another game from Inceton games. Makes the story boring. The story is nearly where I wanted it to bee but got boring after a while. Not worth it. I see the same in alot of games from Inceton, they use the same chars in many of the games, they dont come up with much new stuff.', 'Very Positive', 82.53, 11.70, 15.25);
INSERT INTO reviews VALUES (50467, 2193490, 1051, 'If this game adds multiplayer... not even matchmaking or anything, just the ability to make a direct connection lobby with a friend or friends, this game could blow up', 'the ai is either celtics shaq or prime jordan, no in-between', 'Very Positive', 88.77, 3.48, 2.42);
INSERT INTO reviews VALUES (50471, 2193540, 703, 'Someone needs to clear the air here because these reviews are extremely disapointing and biased...\n\nNO! This game DID NOT copy Hades; Hades is a great game, but does not own the genre. This game is more like the original Wizard of Legend (which btw, is older than Hades) than it is like Hades. Agree, the new art style is similar, but that''s all that I see and I don''t think it''s a bad thing. I''m hoping the overall reviews on this will go up but that''s only going to happen if people stop unjustifia', 'Not recommended, not the same devs, it''s some ue5 slop that lacks all the impact and weight from the original, just a cashgrab from humble games to cash in some sales off people that really liked the first one.\n\nGo follow the old devs on their new projects, avoid this cashgrab at all costs.', 'Mostly Positive', 70.55, 14.37, 0.40);
INSERT INTO reviews VALUES (50482, 2193720, 168, 'why is the archives music such a banger', 'A lot of the mechanics don''t cross over well into 2D. You can be looking at the gold watchers and they''ll still move. Agatha constantly telefrags you with the portals during her boss, and in general through the zones of her chapter. The murder monkeys constantly bug and stick to a wall and don''t move, which usually results in blocking a shard and having to sacrifice an S rank because you couldnt pick it up. Ridiculous.', 'Very Positive', 84.52, 2.83, 0.87);
INSERT INTO reviews VALUES (50521, 2194730, 149, 'I quite enjoy playing this moderately technical repair simulator game.  \nIts tasks are varied enough to provide me with a satisfying level of challenge.  \nNotably provides a warning before job completion if I forgot something.  (!)  \n\nThe developers are still adding new features, and participate in Steam forums.  \nI wrote a Guide to help less technically inclined players get started.', 'I will put this on my cv but its very boring', 'Mixed', 59.73, 48.88, 0.38);
INSERT INTO reviews VALUES (50524, 2194790, 166, 'In short, it was well worth the wait. A damn good fixed-camera horror game, much more in line with Silent Hill than Resident Evil. Some lack of polish is noticeable but the dev has been quick to patch more serious issues; I can forgive a lot for a dev team of 1. I urge you to give it a try.', 'grammar errors a few minutes into the story. pacing is pretty dodgy and the writing leaves a lot to be desired. the audio also isn''t balanced properly and the "2d controls" just don''t work.\nit''s under baked, i got a refund.', 'Very Positive', 94.58, 11.68, 0.22);
INSERT INTO reviews VALUES (50526, 2194810, 173, 'Good game lots of sex Unfortunately not accurate with Hitler''s balls should''ve removed one so technically its sex with some unknown man', 'Not enough content', 'Very Positive', 89.60, 3.42, 6763.63);
INSERT INTO reviews VALUES (50542, 2195120, 776, 'An alien with tentacles is running the seafood shop. I ride around on a bug. A witch runs the book store. Life is good.', 'I can''t recommend this game because it is not ready yet. It is very early access. It doesn''t feel completely balanced yet. The tutorial seems to abruptly end leaving me to figure out a lot on my own. For some reason there is not a character creator at the beginning of the game. A random character is generated. You can change this but the game never tells you, you''ll have to discover how yourself.  There also is not a lot of content yet. At 7 hours, I can tell I''m nearly done. Not a big deal for ', 'Overwhelmingly Positive', 96.39, 29.85, 9.42);
INSERT INTO reviews VALUES (50551, 2195250, 31743, '6.5/10 As someone who has played football in professional clubs and who has been playing computer games since 1995 and the first FIFA until today, I can say that FC is making poor progress. Every year, the mechanics remain the same, nothing special changes. The goalkeeper is too big compared to the goal of 7.32 meters. It is impossible to score a goal from more than 20 m, which is a paradox. The goals being scored have been seen countless times. The goalkeeper does not go out for crosses. There ', 'Game''s Performance is worse than my grandmas healthcare.', 'Mixed', 57.40, 58.55, 0.68);
INSERT INTO reviews VALUES (50557, 2195410, 611, 'I don''t usually buy Early Access games, but this one made me interested because of the Ukrainian localization, and I''m really liking it so far. Art style is gorgeous.', 'The only positive thing I can say about this game is that the art was top notch.\r\n\r\nRest of the game just wasn''t that fun. Played through the whole campaign and the card system, base setup and two factions really didn''t make for a fun experience. I can''t even remember what the name for both races were or what anybodys name was and I''m only after finishing the game. Just an unforgettable story with frustrating game mechanics that I did not enjoy.\r\n\r\n2/10 wouldn''t hymn again :(', 'Very Positive', 81.01, 2.03, 28.30);
INSERT INTO reviews VALUES (50608, 2196420, 147, 'For sure you can spend you time in better ways', 'Not just the worst adult game i''ve ever played, it''s basically the worst game i''ve ever played. The adult content narrows down to a couple of pictures and a couple of gifs which repeat with different clothing. So instead of 46 scenes you get basically a dozen. One of the gifs is bugged and repeats with the same clothing. Game sometimes bugs and shows 9999999 likes/comments on a post. The minigames are an affront to humanity. The idle aspect of the game is just terrible and doesn''t make any sense', 'Mostly Positive', 70.07, 6.82, 2.63);
INSERT INTO reviews VALUES (50611, 2196490, 261, '90 mins in, so far so good. interesting option to let you choose the gender of characters to suit. i like it.', 'It''s not a terrible game. There are worse AVN''s out there. However there are better AVN''s out there too. Play games like Come Home, Projekt Passion, Being a DIK, or Between Two Worlds. The MC seems somewhat like a douche bag and the main female lead is somewhat annoying too. Haven''t been any updates or news about the next chapter in a while. Lot''s of talk of it being abandoned. Look elsewhere for a good AVN.', 'Very Positive', 86.21, 8.28, 6.57);
INSERT INTO reviews VALUES (50637, 2196980, 302, 'i got to kiss the guy who kills my parents #TOXICYAOI #BASED', 'I''ve played some great interactive fiction games, but Arcadie didn''t really click for me. The conceit of a political intrigue adventure, and some of the interpersonal dynamics I did find quite interesting. Unfortunately weak writing (especially the descriptions) would pull me out of it, and the choices were often not super interesting. I didn''t feel like I was often making interesting tradeoffs in the decisions, which often either had obvious correct and incorrect choices, amounted to just choos', 'Very Positive', 93.71, 3.53, 6.15);
INSERT INTO reviews VALUES (50676, 2197760, 106, 'Not going to lie, it''s such a wonderful interactive game with an awesome background story. I absolutely adore everything about it! Highly recommended! 10/10', 'Disappointing Game with needles Undertones\nNot really a game as there is no gampelay here, just click the mouse, move and read.\nThat''s about it.\nWhile the background music is good almost all sound effects are complety off and break the emersion. \nAlso I did not enjoy the homosexual subtone and is just off putting and completely needles.\nIn the end, I was rooting for the Theo and Aiden.', 'Very Positive', 81.13, 1.62, 2.02);
INSERT INTO reviews VALUES (50683, 2197890, 307, 'The game is fun and interactive. The only real complaint i have is that when you progress more the ghost seems to hunt more frequently for longer periods of time. Too many hunts for too long. I cant get any work done.', 'This game was amazing, It had reasonable chores, it had many different levels, and it had 3 locations. It only had one ghost, which was a little boring but still. But then, the update came. And while everything runs a lot more smoothly now, everything else has changed. Instead of being able to choose how many chores you can do at a location, it defaults giving you every single chore. And added a ghost hand print clean up, which wasn''t there before, but also burn haunted toys.\r\n\r\nInstead of havin', 'Very Positive', 80.78, 4.63, 40.27);
INSERT INTO reviews VALUES (50693, 2198070, 378, 'A city builder that isn''t built around grinding for more resources and waiting as your city grows. It''s really amazing - I''m not even 2 hours in and I really like the games idea. All of your city is based on random cards which gets drawn from the deck, you have to make the best use of what''s available and try to survive as long as you can. The idea that your city won''t live forever is great, I personally get too attached to my builds and don''t want to re-do a lot of the things. Cardboard town ta', 'The game can be fun, but usually ends in frustration. I''ve played a lot of roguelike games and deck builders. The idea of combining one with city building is a great idea. The unfortunate reality is that you don''t have enough control over your deck and to really make this fun. Instead you end up being forced to play cards that will immediately end your game and your hand full of trash with no way to discard.', 'Mostly Positive', 72.49, 5.45, 7.05);
INSERT INTO reviews VALUES (50697, 2198150, 11126, 'I only wish there were chickens in this game. What''s the point of putting up fencing if there aren''t any chickens? What kind of glade doesn''t have chickens? I feel like I''m missing out on ambient clucking as well.\r\n\r\nLooking forward to DLC (DownLoadable Chickens) to fill the egg-shaped hole in my heart.', 'I''m a bit disappointed if Im going to be brutally honest, I was counting down the days to this game and bought it right at launch, however its so... hollow? dont get me wrong its cute but youll get bored after a few hours, i was under the impression the game upon launch would have a larger amount of content but its literally just the demo with slightly more space, and a few other seasons to play around with. You literally get one new type of actual window and sure a bunch of new colours for your', 'Overwhelmingly Positive', 97.59, 48.87, 2.70);
INSERT INTO reviews VALUES (50711, 2198510, 1094, 'No updates since July. They need to make it clear if this game has been abandoned or not.\n\nEdit: Switched to positive thanks to reply from devs below. Just to clarify there is no rush for updates it is s solid game, we just need the occasional communication to reassure that it is still in development. I''ve bought a few early access games recently that just got dropped entirely.', 'What a mess ... Playable but pointless and broken at it''s core.  beachdreamer1013 summed it up perfectly in their review.', 'Very Positive', 84.92, 3.83, 49.78);
INSERT INTO reviews VALUES (50724, 2198800, 370, 'im pretty sure I have the most playtime on this sim out of everyone. truthfully, I opened the game, played for 5 minutes and then my wife went into labor and I left the game open and running on my pc for a month straight. 10/10', 'I''ve expected much more from this simulator, the 3D aspect is fun and shit but it does not really cooperate with my electronics passion. I found that tinkercad or something as simple as falstad simulator gives me much more options to work with. Add customizable transistors, mosfets, maybe something kind of redudant but most known elements, maybe a relay? maybe accept higher voltages than 12V DC, maybe AC voltage? that would be cool. Maybe optocouplers maybe voltage rated capacitors maybe Linux s', 'Very Positive', 80.81, 932.55, 0.47);
INSERT INTO reviews VALUES (50778, 2200190, 266, 'whoever made that karaoke master achievement is going straight to ####', '3/10\nI love Chilla''s work and the look of their games. The positives for this game are the multiple endings. While I didn''t complete the game I did look into other''s gameplays to see if I wanted to continue playing, but I did not find this one worth the money. \n\nThe controls for the bike riding scene were difficult around sharp corners, but other than that it was smooth. There was a little bit of looping with the background weather sounds that I noticed, and the dog barking. \n\nThe main part I ha', 'Very Positive', 81.20, 6.95, 0.97);
INSERT INTO reviews VALUES (50808, 2200780, 2282, 'Hello, while the game is good and cozy, I believe this game lacks the attention of the right people. Example the workshop. its an idea where other users can create their own things like tables, laptops, windows, etc. And share them so other people can use them. But The workshop is mostly filled with wall papers or anything of the following.\n\nSelfies, Highly sexual art, kids shirtless (boys), and other things. \n\nI went through all 180 pages as of now, and most of them were mass spam of those prev', 'This game is really fun, don''t get me wrong. But after spending at least 1 hour(s)+ all my doors and windows get removed. That''s not the worse either, all my stuff, my bed, gaming setup, plants and everything else is all gone. Only some accessories were left, but they were clumped in the middle of my room. I do enjoy this game, there''s just too many bugs. I wouldn''t be paying six dollars for a game with bugs. If the developers could fix it I would give a higher rating. But overall the game is go', 'Very Positive', 88.17, 18.83, 5.88);
INSERT INTO reviews VALUES (50849, 2201710, 141, 'Three Kingdoms Zhao Yun is... honestly I don''t blame the reviews for being Mixed (66%) when I write this, because I have somewhat mixed feelings about it as well. On one hand, it''s a fun Three Kingdoms-based ARPG with a solid plotline (of course! it''s based on the Three Kingdoms XD) and some interesting twists on the normal combat of the genre such that you can knock enemies out of attacks and be knocked out of your own attacks in turn, and you can dodge and parry enemy attacks both. On the othe', 'The story doesn''t check how zhao yun supposed to be. The translation is bothering me, too much wolf like do you have any problem with wolf ? it''s like whenever i go, or a place becomes abandoned, the default enemy would be wolf. Wtf ? No matter how cool Zhuge liang strategy, it doesn''t kill cao cao''s general, like wtf ? The movement bug, ruining conversation.', 'Mostly Positive', 77.30, 24.22, 16.83);
INSERT INTO reviews VALUES (50858, 2201940, 1501, 'Since last update, game crashes within 5 mins.\nImpossible to play as is.\n\nEdit (March 22): Patch seems to have resolved most of the issues.', 'since the floating cities update the game has not been playable. either you get 30 minutes then fatal error and loss of all progress. or on loading a save the game crashes straight away when exiting the house. \r\n\r\nsince the patch for stability i have tried a brand new game and the crashing is still occurring. initially i thought this may be pc related, so i have built a new pc running i9-14900k, 64gb ddr5 ram, RTX 4070 Super, running windows 11. Graphic drivers and operating system fully updated', 'Mostly Positive', 77.95, 197.57, 293.10);
INSERT INTO reviews VALUES (50877, 2202470, 219, 'No Sun To Worship in the absence of light.\n...or Rogue-like Splinter Cell.\nIf you are a big fan of stealth action games, such as Splinter Cell or Metal Gear Solid, and looking for something similar - this game is for you. Even though, I partially agree with some negative reviews: it is short-term game, it lacks some useful features and looks like a concept, rather than a standalone game. After all, it is a good game and I hope developer would continue making stealth-action games.', 'I made it to the fourth level, the prison.  I might pick it back up later.  Dunno.\n\nThe strongest element this game has going for it is its PS1 Syphon Filter-esque aesthetic, with a bit of dramatic dynamic lighting reminiscent of the original Splinter Cell layered over the top.  A lot of the rest so far is less impressive.  Very little in the way of settings menus to configure the game before you start.  The opening cinematic doesn''t seem to respect the volume setting ingame, which is a pain and', 'Very Positive', 86.30, 7.07, 0.87);
INSERT INTO reviews VALUES (50882, 2202590, 182, 'Its like nova drift in 3d. i love nova drift. except this has better movement. like gungeon. and i love gungeon. but im all outta bubblegum so im gonna chew ass\r\n', 'Weaker version of Nova Drift, not nearly as fun in every way. My first gripe is having talents that are ONLY beneficial in multiplayer mode. There are three or four, and they offer ZERO benefit in Single player. How difficult would it really be to attach a singleplayer ability to that skill as well? Instead you have complete deadspace in the skill tree if you are not playing with somebody else. Incredibly lazy.\n\nLets talk about the skills themselves. There is nothing interesting there at all, it', 'Very Positive', 91.76, 53.92, 22.38);
INSERT INTO reviews VALUES (50942, 2204130, 395, 'They dont make games like this anymore, because the population is not capable of playing them.', 'warning!! as of february 26th alien crossfire is not working with windows 11, would refund but it was past the 14 days.', 'Very Positive', 91.39, 0.17, 0.48);
INSERT INTO reviews VALUES (50944, 2204170, 170, 'Splodey is an amazing platformer that has no jump button at all. Your base speed is very slow and you have to use potions to splode yourself in directions and it''s all about that fluid beatiful momentum you have build up while sploding yourself. It''s difficult as hell at first, but once you master it, it feels rewarding. Easily this is the most satisfying platformer I played in a long time. Going for that 100% completion was a challenge. Highly recommended to all platformer fans ! Also whoever c', 'This will be a counter-intuitive start, because if I were allowed to, I would give this game a 5 or a 6 out of 10. Because it''s not *bad*. The way to maneuver around the levels is clever and with proper technique you can go incredibly fast and I can see this being a darling of speedrunners. The levels are also clever and designed with intent and for the asking price, you get a lot back. \n\nAnd yet I can''t recommend this game, because while the method of mobility is clever, it''s also counterintuit', 'Very Positive', 92.94, 45.03, 1.47);
INSERT INTO reviews VALUES (50950, 2204350, 212, 'I Don''t Understand. Where is the player base for this good game?\nThis game is great. We played for like 8 hours and the only bug we encountered was a friend out of the country desync-ing and even then the netcode was robust enough that it fixed itself without him having to leave and come back. There''s so little jank compared to games like Phasmo and Demono. Everything just works. The game is super engaging. In other ghost games you''re wandering around waiting for things to happen...not here. In ', 'I really did actually try to give this one time to cook and grow. Posted feedback and even had dev replies but its mostly just  balance and gameplay issues that make me tell you to pass on this one.\n\nMore than half of my hours on record are me waiting for hunts to finish since the entities seem to need only about thirty seconds between hunts that tend to last upwards of one minute and thirty regardless of difficultly. its lame. more time hiding than exploring or enjoying the content. \n\nI left de', 'Very Positive', 91.98, 94.42, 11.27);
INSERT INTO reviews VALUES (51029, 2205850, 346, 'They added Turkish... Just neutralising the other guys review.', 'Meh. After five hours, I think I''m done with it. There are some compelling systems at play here (which the game really doesn''t help you understand, e.g. advanced classes), but the game doesn''t seem to care whether or not they''re any fun. You spend most of your time in the menu on incremental and almost insignificantly small improvements, and you never really feel like there''s a cohesive "build" with your army. There are surprisingly few synergies you can find; even the item set bonuses are negli', 'Very Positive', 82.95, 0.87, 7.00);
INSERT INTO reviews VALUES (51039, 2206140, 206, 'makes rocks look very edible', 'Initially, I liked geodepth. You get into your drill, you get some resources, everything is rather chill and feels like one of those “dad games”. The problem with it becomes obvious when you try to progress further - instead of something else you are given the same exact set of activities, only slightly redesigned: the cave with another upgrade looks a bit different, the ore you mine is of a different colour, the stats of your drill are increased but feel the same because everything around you h', 'Very Positive', 87.86, 4.82, 7.07);
INSERT INTO reviews VALUES (51042, 2206210, 311, 'A story of isolation and pain, and a story of regret and guilt, that anyone could experience, has experienced, or is experiencing.', 'good game but why i need collect to get true ending bro so sad \r\ni come form True world to save Emliy and u die or Emliy or go do Something like 2 h to get true ending and u can watch it in YouTube ????????????? \r\nGOOD GAME BAD ENDING bc ending 5/10', 'Overwhelmingly Positive', 97.11, 7.07, 6.17);
INSERT INTO reviews VALUES (51048, 2206320, 112, 'At this time the developers have fixed 96% of bugs, so the game now is very good. I recommend it', 'Good', 'Mostly Positive', 72.32, 12.18, 2.13);
INSERT INTO reviews VALUES (51050, 2206340, 158, 'An excellent conclusion to Misaki''s story.\r\nI don''t know if sprite is working on an EXTRA3 or 4, but I really hope they are. I need more Aokana in my life.', '', 'Overwhelmingly Positive', 100.00, 8.62, 0.00);
INSERT INTO reviews VALUES (51061, 2206560, 195, 'has very nice achievements, i recommend it', 'As a game, this is extremely weak. The puzzles are incredibly easy and boring. You simply click on exploding boxes to shepherd a ball to the end goal. Some of the later levels get more interesting but also introduce more bugs with the physics resulting in having to do the same level 10+ times to move on. \n\nAs a way to get achievements, trading cards and point shop items, all the Zup! games focus on appealing to people into collecting such things to decorate their profile with. These people will ', 'Overwhelmingly Positive', 96.41, 2.20, 4.57);
INSERT INTO reviews VALUES (51104, 2207440, 164, 'This is an INCREDIBLE puzzle game. It''s so unique and challenging. It does a fantastic job of teaching you each mechanic and building off that. Sometimes the puzzles are incredibly challenging, but I never felt stupid for not figuring it out sooner. I always left this game with a feeling of "OH so that''s how that works! That''s so cool!". Absolutely recommend this game. It''s going on top of my list for sure.', 'Just couldn''t get into the game.', 'Overwhelmingly Positive', 98.78, 4.52, 1.23);
INSERT INTO reviews VALUES (51108, 2207490, 564, 'This game is fun, brilliant very addictive', 'I found it to be a bit too chaotic.  So much resource and production balancing but no tools to help wit hit and something new every 2 minutes with no notable explanations.\nGlad others are enjoying it,. just not for me.', 'Very Positive', 93.26, 542.40, 1.78);
INSERT INTO reviews VALUES (51134, 2207970, 412, 'How strange it is to be anything at all.', 'I enjoyed sodaraptor''s Hypnogogia titles because they were beautiful nonreal worlds to explore, while this is liminal space stuff with dull locations. I like looking at liminal stuff, but actually playing this is not for me.', 'Overwhelmingly Positive', 96.84, 8.47, 0.73);
INSERT INTO reviews VALUES (51158, 2208570, 849, 'Had the blind monster on a run. Hid under a desk when my friend showed up under the desk to talk strategy with me. Shoved him out from under the desk and started yelling and the monster murdered him. 10/10', 'currently very buggy. Had to restart mission several times due to players getting trapped in rooms and items not spawning in the correct locations.\n\nThere is no FOV slider (really no excuse for this in 2025). The game has forced random camera movements from the player''s breathing that cannot be turned off (this isn''t covered by the "camera shake" setting).\n\nMy partner posted about this issue on their forum. One of the devs responded "too bad" and closed the thread. Clearly accessibility is not a', 'Very Positive', 86.57, 27.23, 1.00);
INSERT INTO reviews VALUES (51171, 2208920, 11028, 'Ubisoft added achievements so I am happy to provide a positive review. Please add achievements to your other older games and I will buy them as well. Hell I''ll buy them now to provide the cash to pay the Ubisoft employee that will add the achievements.\r\n\r\nThe game is great, if you enjoyed AC Odyssey, AC Origins or open world games with a good story you will like this.', 'Ubisofts trash launcher stole 1 hour of my life when it wouldn''t let me log in and connect with steam.\n\nThis trash launcher then stole me another hour of my life when i was trying to figure out why the game crashes after launching.\n\nI did the grave mistake not having the game installed on the same drive as Ubisoft Connect and Steam. How dare I !', 'Mixed', 68.72, 186.65, 40.87);
INSERT INTO reviews VALUES (51212, 2209680, 425, 'Really neat & kind of addicting little game. Plays very well on Steam Deck. The gameplay revolves around defending against a World War II Normandy style invasion that comes in waves, and it becomes particularly intense once you hit wave 30 or so. \n\nYou get a light mix of artillery & machine guns + duplicates to shoot down a variety of troops, tanks, trucks, gun boats, planes, etc. Sometimes the weather changes. \n\nGraphics are alright, not super impressive. Would be cool if there were more Steam ', 'The game is... Good? The game play is fun and engaging for 15 minutes then its just the same cycle. Half the weapons become useless after 5 waves, why would i use bullets against tanks and ships? The planes shouldn''t be every round. They are annoying and one plane kill is about 16 added to the counter. Had potential, will be asking for a refund.', 'Very Positive', 83.53, 10.40, 0.88);
INSERT INTO reviews VALUES (51269, 2211090, 181, 'Its not a bad game, can do without the grinding need to keep the story going though. It''s funny and silly entertainment. You get a glimpse of who is really in control... Some of the most ruthless, nasty women you will ever meet will stick in your brain like a tumor. Not much on sex scenes, but its still entertaining. Good game!\n\nUpon completion of this long game I had to further add my 2 cents worth. It ended kind of abruptly with a predictable outcome. I was disappointed in Incredible Woman on ', 'I''d say the game is good, but it''s not finished and, from what I''m seeing, nothing has been done on the game in a while. So, my recommendation is to wait until the game is done and then buy it if you are interested. The game itself is not bad and has some extra mechanics beyond just clicking the next button and seeing a slide show. I do hope it''s finished, but with the lack of updates and the way things go with early access games, I''m not optimistic.', 'Very Positive', 82.32, 8.33, 37.30);
INSERT INTO reviews VALUES (51275, 2211170, 507, 'Great game to play with your spouse on the couch after getting railed.', 'Good concept, but terrible execution with the zoom level\n\nI was excited to play Unrailed! 2 after enjoying the first game, but the zoom level is so far out that it ruins the experience. It feels like you''re watching the action from a drone miles away, and you lose all the charm and connection with the characters and the train. Worse, there''s no option to adjust it in the settings.\n\nThis might not bother everyone, but for me, it made the game feel impersonal and hard to enjoy. Games like this thr', 'Very Positive', 93.49, 4.90, 7.72);
INSERT INTO reviews VALUES (51283, 2211390, 138, '|^^^^^^^^^^^^^^^^ \\||___\r\n| The Truck of Approval  |||""''|""\\__,_\r\n| _______________ |||__|__|__|)\r\n|(@)@)"""""""""""""""**|(@)(@)**|(@)', 'A lot of good and bad mixed in with this one.   While the overall was fun to start, \r\nthe items needed for upgrades are very tedious to get and the amounts required are beyond reason.  you can earn maybe up to 10 iron on a run? maybe at max 4 or 5 time crystals, and 1 heart.  \r\nthen you''ll get items to level up and it costs like 5 hearts.  which for most levels is a one time\r\nshot after playing for 18 minutes in a level.  basically just overly hard for hard sake.  just drawing out run time.\r\n\r\nS', 'Mostly Positive', 71.01, 28.43, 10.87);
INSERT INTO reviews VALUES (51297, 2211730, 347, 'great game. gets your heartrate up nice. reminiscent of devil daggers and i love that. the movement also feels amazing. the only gripe i have is there not being replays. glad some australians finally made a slice of life game too', 'I thought there will be like campaign with levels, but it''s 1 arena level and 1 weapon. Visuals are nice, movement/parkour is polished and the shooting mechanic is fine, but there is like extreme lack of content for me. A lot of indie shooter demos have more content and more things to show, so I would only recommend that if you are the type of person who enjoy the same experience, when you do the same thing for 10 hours increasing your skill.', 'Overwhelmingly Positive', 97.69, 9.23, 0.12);
INSERT INTO reviews VALUES (51321, 2212330, 22132, 'I have now installed over 2gb of mods for a 300 mb game and now it crashes on a regular basis\r\n10/10 would recommend', 'If you''re going to get into this game, know that this is a fundamentally communal experience. If you don''t already have a group of friends who are into the game, the new player experience is going to be actively hostile; no Singleplayer (the "Singleplayer" option in the lab menu has no AI and would be better called a sandbox/training mode), no tutorial explaining the (very large) moveset of the various characters, nothing. The five characters are apparently really complex and nuanced; I''m going ', 'Overwhelmingly Positive', 96.64, 14.33, 0.50);
INSERT INTO reviews VALUES (51358, 2213120, 582, 'I love the graphics of this game, and it is the perfect proof that you don''t need realistic graphics where you can count the main character''s boogers or every single eyelash, in order to convey, experience and reflect emotions and feelings. A good story, good characters and good gameplay are the heart of a good game. Well, this is a good game, and it was made with a lot of love.', 'I absolutely love games like this, but unfortunately While We Wait Here fails to achieve what many similar games before it have. There is an over-amount of cutscenes/nonplayable sections of the game where it feels unnecessary, then due to the amount of cutscenes there are constant loading screens that completely ruin any immersion. The majority of the voice acting is good, but there are times you can tell a voice actor read directly from the script with no emotions and awkward reading that is ju', 'Very Positive', 89.35, 3.92, 9.35);
INSERT INTO reviews VALUES (51360, 2213190, 1166, 'The only game where "L, the worlds greatest detective" could be a really stupid 8 year old with the deductive skills of a brain damaged walrus. 10/10 highly recommend.', 'Refunded. The demos and concept are fun, but I literally couldn''t play through a single game with real people. Left rooms because voice chat was so vulgar (slurs and just horrible shaming when someone got anything wrong), or got automatically kicked for being a woman. I am not self-hating enough to put myself through any more to find my crowd. Without any kind of safeguards or development of the text chat, this game is unfortunately not for the half of the remaining Death Note fanbase of goths, ', 'Very Positive', 88.42, 30.15, 2.18);
INSERT INTO reviews VALUES (51364, 2213300, 147, 'I''d beaten this one on Nintendo DS thrice, but only got to a PC version years after its release. If I had to guess, I was probably admitted to a mental institution at the time. Always a safe bet, am I right? Here I am, even more years later, playing it for the fifth time. Match my freak. I suppose it won''t hurt to (re)write a quick recommendation for, I hope, a truly definitive version that won''t go away like the previous one published by everyone''s favourite Ubisoft who screwed things up for ev', 'Just a worse looking version of the last game they''ve tossed out after deliberately borking the previous version so it won''t even work.\n\nNot even slightly worth the price.', 'Mostly Positive', 74.15, 7.23, 58.67);
INSERT INTO reviews VALUES (51414, 2214220, 125, 'Be warned this is VERY early access, the game feels more like a demo at this point. I would only recommend buying this if, like me, you were excited by the trailer and want to support the development. The potential is definitely there though, the atmosphere and art style are great and the shooting feels satisfying but there is a long way to go until this is a proper game.', 'Trench Tales has an intriguing WWI-inspired horror setting and some creative supernatural combat mechanics, but it currently feels rough and unpolished. The visuals are atmospheric, yet gameplay lacks refinement and clarity, leaving the experience feeling more concept than execution.  Need time,  because now it''s terrible . \n4.5/10\nVideo Gameplay - https://youtu.be/J4CjB-8Tai0', 'Mostly Positive', 70.40, 1.50, 0.48);
INSERT INTO reviews VALUES (51437, 2214880, 298, 'I''ve only had the chance to play the very start of the game but can already tell this game was made for me. The game looks lovely and plays flawlessly. The movement is just so free, you can jump, float, glide and slide around an absolutely gorgeous world. I hope the devs are proud of the game they have made because based on only 20 odd minutes of play, they should be', 'I think overall its a glorified walking sim with not much to offer in 3D platforming. \n\nI''ll be fair and start with the positives. The Music and Graphics are fantastic. I do find it pretty interesting you are on one of Jupiter''s moons if it was terraformed. The atmosphere is great and there was a lot of cool spectacle moments. The movement is decent. Being able to fly around with a reasonable fuel system feels pretty decent and there isnt much limitation with where you can go with it. \n\nNow for ', 'Very Positive', 86.58, 0.73, 3.40);
INSERT INTO reviews VALUES (51451, 2215260, 1453, 'I want Kim Pine to step on me and Stephen Stills to choke me', 'I love Scott Pilgrim.\r\nI hate Ubisoft.', 'Mostly Positive', 70.20, 18.33, 1.45);
INSERT INTO reviews VALUES (51460, 2215430, 27339, 'The best Assassin''s creed game since Black Flag, and I say that lovingly.', 'This is one of my all time favorite games. The music, story, combat and design are all incredible. Could some things be better? yes. Are there a few bugs? sure. But this game is a complete package and well worth the money. And I''ve bought it twice.\n\nSo why not recommend this game? PlayStation and it''s handling of forcing everyone on to PSN for no real reason. And the debacle of how they handled Helldivers II is not something I''ll just forget or forgive.\n\nSucker Punch Productions deserves all the', 'Very Positive', 94.06, 75.73, 42.37);
INSERT INTO reviews VALUES (51482, 2216120, 106, 'Magicube is a puzzle game with a deceptively high difficulty. The graphics, controls and mechanics are simple yet the puzzle solutions are anything but. A must play for enjoyers of especially challenging puzzle games.', 'I CANNOT RECOMMEND THIS GAME.\n\nEach level introduces several (too many) new ideas at once, none of them explained before, and all mixed instead of one after the other. This makes the puzzles too hard in a very artificial way, and even harder when several of the new ideas are weird and not intuitive at all unless you are the game developer who already knows those tricks... This is indeed bad puzzle design because the pacing is too fast, making the puzzles annoyingly hard and in a bad way. A well-', 'Overwhelmingly Positive', 98.11, 21.53, 4.78);
INSERT INTO reviews VALUES (51507, 2216660, 188, 'At first the game does not feel as a big improvement over the first Mortal Glory, some things are actually made worse (buy/sell interface for instance). There are still huge difficulty spikes. Art style is inconsistent. Most playable characters after getting some levels offer pretty little variety and there are very few effective archetypes. This reduces replayability greatly. Reign of Tyrants DLC is a game changer. Boss mode is much better than standard campaign mode. Playable bosses are all un', 'worth like $5\n\ncomplaints in rest of comments nail it. map is boring (should be more like slay the spire), early game is slow and boring or broken/rng reliant, there are a billion skills but few synergize well enough to justify the action cost, many dont work how you think they will work (apparently ''summon hostile creatures'' means they are only hostile to me?''), and maybe half are outright useless.\n\nit seems like a lot of work went into this, but it honestly seems like a pet project game. there', 'Very Positive', 89.89, 136.42, 0.75);
INSERT INTO reviews VALUES (51514, 2216770, 195, 'Reminds me of my Python programming experience during my degree\n\n"I like the way this sucks!"\n\nJust be aware that this game is more towards someone who has some experience in coding than someone who wants to start coding. The game immediately expects you to do stuff after some basic tutorials, and the in-game tutorials is just not enough for that. You''d definitely need to seek external sources like W3Schools if you''re someone who isn''t familiar with coding. Hell I''d even recommend you to code us', 'I really wanted to like this game because it combines two of my favorite things - video games and programming; however, the game''s current state is too buggy to be enjoyable. Throughout the tutorial and first level, buttons would stop working until I restarted the game, game would be choppy or slow for too long after starting each level (my specs are well above recommended, r5 5600 and rx6750), and in-game code running after it was removed (tried restarting the level, resetting the code, and com', 'Mostly Positive', 78.97, 11.80, 1.70);
INSERT INTO reviews VALUES (51515, 2216830, 401, 'Most of this pack borders on okay. Fixytext is an okay game that can be funny, but isn''t that much more involved than opening a Google document. Hypnotorius has a fun concept, but is ludicrously unbalanced. Timejinx is a fun year-guessing trivia game, who''s scoring system means that it''s fairly fun even if you suck at trivia (like me.)\n\nTee K.O. 2 is a really good side-grade to the original, offering a usually less funny bracket-style tournament structure, as jokes can get stale when you''ve seen', 'Jackbox Party Pack 10 sits right between Party Pack 1 and Party Pack 2 in my library \n\n***This wounds me***\n\n', 'Mixed', 61.35, 11.88, 2.48);
INSERT INTO reviews VALUES (51520, 2216960, 173, 'she psycho on my baseball till i super', 'Its fun but it''s totally abandoned. No updates in almost two years... It''s a shame tbh', 'Very Positive', 91.91, 13.47, 0.28);
INSERT INTO reviews VALUES (51523, 2217000, 4450, 'It''s a fun platform fighter, however it lacks a proper tutorial as of right now. When I refer to "proper tutorial" i''m referring to an interactive space that tells you how to play the game, not video guides, so if you''re not an experienced rivals 1 or melee player, it''s generally going to be a hard time for you.', 'If you''re new to Rivals of Aether/Melee save your money. The game is not bad, but you are not the target audience. LET ME REPEAT, THE GAME IS NOT INHERENTLY BAD. The game just only caters to people who played the original or played Melee and gives nothing to new players. No tutorials, no in game explanations, and a barely functional training mode. The only bit of help you get is a wordy steam post that gives vague explanations. You are essentially required to forego playing the actual game to le', 'Mostly Positive', 79.69, 3.93, 5.38);
INSERT INTO reviews VALUES (51540, 2217580, 568, 'Sim features like pit stops, tyre wear and fuel management along with team management and a rival system in a career mode spanning 5 decades of F1 packaged in an accessible fun little retro arcade racer. What a gem.', 'Game does not support my racing wheel. To make it worse, you can''t change the bindings on your controller. After I accidentally switched camera views for the 11 thousandth time in 10 minutes of ''racing'' I gave up.  Refund requested.\n\nDEVELOPERS:  For goodness sake , if you''re going to promote a game based on grand prix, please support a racing wheel!  It doesn''t matter if the game is arcade or not, it''s still car racing!', 'Very Positive', 93.49, 12.42, 0.37);
INSERT INTO reviews VALUES (51573, 2218400, 365, 'Only for genre addicts. Absolutely zero new ideas but the enemy models are cool and the balance/progression is pretty good. Worth the sale price to waste some time when brain fried after work.', '6.5/10\n\nGame is not bad in any way, but severely lacks content so hard to recommend it over other games in genre. Every run feels very samey because there aren''t many options and no mission variety.\n\nTook me about 25 hours to 100% game in it''s current state and none of them were hard achievements, last one i got was just to finish 60 missions.', 'Very Positive', 86.85, 70.92, 30.67);
INSERT INTO reviews VALUES (51589, 2218750, 19515, 'This game is simply amazing. The diabloish design paired with Vampire Survivor''s gameplay is a really good match, it''s fun, it''s nervous, it''s hard.\n\nOne of the must fun meta progression I ever seen on this kind of game, not rellying on farming ressources but rather by achieving some quests (and some of them are really hard to do). And as the final quests are complex, the game remains a challenge even after 65h+ of play. \n\nThe number of possible combinations (spells/equipment/potions/characters,', 'The game is pretty fun but unfortunately it just plays so slow. If the moment to moment gameplay mattered it  would be fine but once you get a couple levels the game borderline plays itself for 20-30 mins until it might get hard at the end of the run. Vampire survivors knew this was a problem and instead of insisting on wasting everyones time they added a "turbo mode" that made it so the runs were a lot tighter and more fun.\r\n\r\nUnfortunately halls of torment wants that slowness as part of it''s a', 'Overwhelmingly Positive', 96.39, 77.70, 16.95);
INSERT INTO reviews VALUES (51601, 2218930, 103, 'Great story and beautiful renders.\nGreat scenes.\nGreat buy for sure.', 'Have to say the price isn''t worth it since there are game mechanics intentionally left out or withheld.  Such as; a very simple "change relationship" mechanic.  There was a vague patch mentioned through the grapevine that if download could change relationships but no links and if I get the hint correctly, it would be outside of steam.  Really want to do that?\n\nAnyways, I paid a medium price for what?  No I''m not a patron other than a simple out right purchase.  I''m not going to go for the game m', 'Mostly Positive', 76.70, 4.60, 1.10);
INSERT INTO reviews VALUES (51603, 2218970, 205, 'Great game, Kenshi meets Conan. Absolute hidden gem. Tons of depth. 8/10. It is mysteriously addictive. It is rough around the edges but the greatness is there.', 'Lots of promise, lots of potential. From a fan of Kenshi and survival games, the premise and promise is here. But the game simply DOESN''T work as advertised. From desync problems, to absolute jank issues where inventories glitch out and you can''t access stashes, NPC''s getting stuck in questlines, not being able to create multiple characters without resetting progress, there''s a just a looooot of work to be done here. For the price asked for it now + it''s numerous issues, I simply can''t recommend', 'Very Positive', 82.44, 40.23, 2.05);
INSERT INTO reviews VALUES (51709, 2221490, 10822, 'If you value fun in games, avoid any type of PvP in this game.\n\nliterally pretend it doesnt exist.\n\naside for that 8/10', 'Bought the ultimate edition\nSays new dlc battle for Brooklyn is a part of ultimate edition....... never got dlc\n\nEdit- i found out it''s only part of the "new" ultimate edition which is still a damn scam and i will not be changing my thumbs down review for this scummy dodging practice', 'Mostly Positive', 77.51, 330.63, 2.57);
INSERT INTO reviews VALUES (51710, 2221500, 165, 'Game wont tell you to do basic things but everything you need is spreaded around the kitchen so if you look around you will quickly understand game''s mechanics', 'It would be nice to include a small tutorial on how to navigate and prepare toast in the beginning.', 'Very Positive', 84.24, 4.60, 0.75);
INSERT INTO reviews VALUES (51725, 2221840, 103, 'Better than warthunder', 'A bit too many scenes, takes way too long to complete', 'Very Positive', 91.26, 1.30, 1.67);
INSERT INTO reviews VALUES (51729, 2221920, 1725, 'Unfortunately Ubisoft never excels at games and this title is no exception.\nGraphics and animations are very nice, but whoever wrote the dialogues for this game should change their job. Banal and without any kind of depth, I just want to skip every little scene where the characters talk.\nGame ported to Steam and without Achievements and this is another flaw, especially for those who like to collect trophies.\nDisappointing in many respects, however, the landscape and gameplay earn it a 6/10 ratin', 'I adore the game - I consider it like an Assassin''s Creed Odyssey but with a different aesthetic and with a good amount of humour. You can tell a lot of thought and care went into making this game.\r\n\r\nSo why the bad rating? UConnect is installed by default and sadly you will not be able to play this mostly single-player game should the servers ever go down for the UPlay service. It is a terrible tragedy that the game be tied to this invasive sort of DRM when it is already being sold on Steam - a', 'Mostly Positive', 71.36, 7.20, 11.07);
INSERT INTO reviews VALUES (51755, 2222540, 284, 'playing this game with checkpoints off will truly put the fear of god into a man', 'It''s a fine game, but I don''t enjoy it nearly as much as I enjoy Runner2. Rerunner lacks the charm of Runner2. It has boring, list-style menus, no story or voices, no cannon mini-game at the end of levels, the difficulty is much higher, the levels are boring to look at, it''s harder to see and plan moves.\nAfter I played through Zone 1 and some bonus levels, I launched Runner2 so I could compare them back-to-back, and Runner2 was like a breath of fresh air.\n\nOverall, I''d rate Rerunner 3/5. I picke', 'Overwhelmingly Positive', 97.54, 3.45, 1.42);
INSERT INTO reviews VALUES (51803, 2223590, 161, 'Got this on mobile yesterday and its good fun, and is still good fun on PC. \n\nWell worth the price!\n\nP.s I do wish I could get my progression shared across mobile and PC, but not the end of the world', 'this game is extremely light on content.  it feels like 1/3 of a kingdom rush game.', 'Very Positive', 82.61, 11.58, 20.60);
INSERT INTO reviews VALUES (51808, 2223700, 722, 'fun game but still a while away from perfection with there being a decent amount of bugs, 1 being that if you play on uncapped fps the steering is uncontrollable and you spin out non stop. so for anyone buying this game make sure to cap the fps so its playable.', 'Very fun game, absolutely ruined by the fact that due to the way it was made/programmed/whatever, if your game stutters for half a second you''ll bug out and immediately catch on the floor and die. Falling through the floor for no apparent reason is also fairly frequent. At best, this is immersion-breaking and kills the chill flow-state vibes the game is going for. At worst, it makes it damn near impossible to get the 50k combo required for the 2nd map.\nI struggled to get a 20k combo on the first', 'Overwhelmingly Positive', 95.57, 33.22, 6.87);
INSERT INTO reviews VALUES (51814, 2223840, 2302, 'Most memorable part of the game is the game not releasing with the ".EXE" file only a 250 KB file and was unplayable for 30 minutes during release. Now to start playing the game', 'It''s starting to feel like dead by daylight was just dumb luck. \n\nFirst of all, the game released as an empty folder (some intern surely got fired over this).\nSecondly, the story is so boring and the characters have barely any depth as of 2 hours in.\nNot even mentioning the poor framerate that hasn''t changed since the demo even on high end computers.', 'Mixed', 65.25, 23.85, 1.90);
INSERT INTO reviews VALUES (51846, 2224640, 419, 'Barely.  Its more of a puzzle tower defence that requires a lot of restarting to see what works.  Boring after an hour or so', 'Like many other negative reviews said, the game is extremely restricting with its strategy and towers etc. It feels like there''s one solution for every map, and no deviation allowed. The mechanics are also strange. Enemies that don''t give gold? No AOE tower in the early game? Lots of air units that render your maze useless? Just not fun.', 'Mostly Positive', 72.08, 2.88, 1.43);
INSERT INTO reviews VALUES (51888, 2225530, 127, 'i kind of recommend it. its a fun game, but i dont like the fact you cant play it with people that arent your friends, would be nice to be able to play with strangers \ntoo.', 'Sorry to take down the mood, but the game really sucks. It''s beyond me why anyone would purchase this when there are countless free alternatives that actually have a more fun setup. This game asks everyone in your group to write down what they want to draw and then they draw it. That''s it. AMAZING CONCEPT. SO UNIQUE. And then there''s nothing. No challenge or activity or goal that you work towards. You just goof about how dumb your picture looks when you''re just drawing with a mouse like it''s ms ', 'Very Positive', 89.76, 1.50, 1.60);
INSERT INTO reviews VALUES (51915, 2226160, 171, 'you can cancel your turnaround with a dash', 'listen, I wanna love this game and to an extent I do. It''s got great music, amazing visuals, tight controls and clearly was made out of passion. It''s a loving tribute to Celeste and the genre of platform fighters. But it''s just too faithful in the worst way: it''s too technical. The execution barrier feels too high for me personally to enjoy. I was playing just the intro for about 40 minutes trying to get a feel for the controls and I couldn''t even get past a C on level 1. This is obviously a gam', 'Very Positive', 93.57, 20.53, 0.80);
INSERT INTO reviews VALUES (51922, 2226430, 195, 'Moth people are cute, Owlcats are cute and my tiara made of trash is cute. Ain''t nothing you can do about it.', 'This game isn''t quite there yet. I loved the demo, and was excited to play this, but the amount of crashes and glitches I''ve had have made it unplayable to me. Feels much more like an Early Access than a full launch. \n\nHopefully in a few months the game will get to where it should be and the kinks will be worked out of it.', 'Very Positive', 82.05, 1.02, 2.35);
INSERT INTO reviews VALUES (51960, 2227130, 303, 'When the time comes, at the end of the year, to give games awards on STEAM, Caves of Lore will be the first I''ll vote for. The dev has my thanks, not only for having crafted a real good old RPG on par with the classics, but also for all the work and pain he must have taken to iron details, and implement mechanics that works perfectly every way. Everything is good in this one, even the writing, even the story, and the rich pixel graphics too!\nᓚᘏᗢ I''m particularly fond of "small-dev-team indie gam', 'Hmmm.  \n\nSadly I am marking this as a not recommend, and I lurve most CRPGs.  It has its charms - nice pixel graphics, humorous writing, exploration, amusing details like the dog carrying a torch if it is a ''leader'' or dog specific NPC chats...  But it is plagued by a zillion trivial combats, each taking a minute or two to win.  They are no threat, not interesting and kinda dull ...  and that boring time adds up!  I feel it wastes my time.  Yet skipping them by running or sneaking is itself a mi', 'Very Positive', 94.39, 31.72, 8.30);
INSERT INTO reviews VALUES (52008, 2228280, 962, 'Nice game, but it’s not a traditional city simulator as one might expect. The design limits are restrictive, especially when it comes to roads and layouts, which are more for visual effect rather than functioning as real infrastructure.\n\nThis feels more like a city governor simulator where you manage a map, similar to a 3D version of Microcivilization. The 3D aspect isn’t even necessary, it could have been a 2000s style browser game (which isn’t necessarily a bad thing).\n\nIt can be enjoyable, bu', 'Memoriapolis has great potential but after just 10-15 hours becomes boring. Only 2 in-game metrics really matter and all of the resources can be bought/sold on market, which negates the need to make your city self-sustainable. Starting character and in-game choices ("Are you going to support X or Y?") make no measurable impact on gameplay. Also, based on recent announcements, developers seemed to be focused on UI instead of introducing more content beyond new buildings with each age.\nOverall, in', 'Mostly Positive', 77.03, 1.98, 21.73);
INSERT INTO reviews VALUES (52058, 2229560, 320, 'Zet Zillions is fantastic. The artstyle is amazing and the gameplay fun. Yes, this is Slay the Spire with FTL map. Price is great, game is challenging but fair (so far)\nBUY IT! So the devs can do more with it.\n\nCons: The actual shop and currency is under utilized. Cards don''t seem to change much. Card Fusion can be somewhat confusing\n\nMore content than I was expecting for less than $10, big update coming on 7/11/2024', 'I leave a negative review with a heavy heart. I absolutely L O V E the art style of this game, the music is pretty decent too. However, in my last two games I encountered bugs with the core mechanic of the game, when sometimes cards just simply refused to fuse or stack into each other, basically ruining hour long run.\r\nAlso, there aren''t enough opportunities presented to plan on building for a playstyle. Maybe I just haven''t ''grinded'' enough to unlock every content. My enthusiasm didn''t last lon', 'Very Positive', 90.94, 63.05, 5.75);
INSERT INTO reviews VALUES (52069, 2229830, 176, 'To play singleplayer all you need is cnc-ddraw &\nWINEDLLOVERRIDES="ddraw=n,b" %command%\n\nHowever, if you want online then you need:\nhttps://cncnet.org/command-and-conquer\npatch for existing installation', 'Game does not work on windows 11 unfortunately', 'Mostly Positive', 78.41, 0.13, 0.10);
INSERT INTO reviews VALUES (52070, 2229840, 161, 'Such a nostalgic game, and I personally still find it really fun and challenging to play! Very enjoyable nearly 30 years later!', 'Sadly it don''t work on my computer just black screen and crashes :(', 'Very Positive', 83.85, 116.82, 0.53);
INSERT INTO reviews VALUES (52071, 2229850, 3091, 'Don''t listen to the smoothbrains telling you this doesn''t work. 5 seconds on google... CnCNet is the place to go, download yourself the client and enjoy it in 4k widescreen, perfect sound, full online play, with the factions fully balanced.\n\nCan''t say much cause my POV is clouded by nostalgia. But like me, if youre bad at AOE or Starcraft, give this a shot. Its wacky, and has a no nonsense, micro/macro-free experience that is fast paced and doesn''t drag out for an afternoon. Highly recommend!!', 'You can''t buy this game separately ,Like this post so that others don''t make the same mistake, thank you', 'Very Positive', 94.89, 30.33, 0.80);
INSERT INTO reviews VALUES (52073, 2229870, 778, 'One of the very best strategy games of all times. The gameplay still holds up to this day and the singleplayer missions are still epic and creative. \r\nYou may play as one of 3 factions (Global Liberation Army, Chinese or USA) and every team is very distinct in their playstyle. Furthermore the factions are displayed in an over the top somewhat racist stereotype which is hilarious. \r\nMusic is absolute banger.', 'Do NOT purchase C&C ULTIMATE COLLECTION unless you only want to play the older of the titles. EA has made literaly no effort to ensure these programs are operational on modern PCs. Red Alert 2 and earlier is fine, but Generals wont boot without a custom options.ini file. In 3 Tiberium Wars only the skirmish crashes with no error codes. I have not tired Red Alert 3 because I''m not having fun at this point. No one purchased this for C&C4 so idc if its working. Maybe I''ll revisit this and try to tr', 'Very Positive', 86.89, 17.15, 0.17);
INSERT INTO reviews VALUES (52074, 2229880, 588, 'Rest in peace James Earl Jones, you were amazing in everything you did as an actor and/or voice actor. \nEven though you are gone, you will never be forgotten!', 'If, like me, you were unaware that the early Command & Conquer games are available as freeware now, do yourself a favour and get them at over at CnCNet. Unfortunately my experience with this version of Tiberian Sun has been marred by crashes but I waited too long before testing to get a refund. The aforementioned CncNet version works flawlessly and is a great way to sate your nostalgic urges.', 'Very Positive', 89.80, 2.08, 0.92);
INSERT INTO reviews VALUES (52075, 2229890, 411, 'At 12 years old this is how I got my username. An underrated classic. Now with EA publishing the source code, this game may yet have a renaissance', 'i know its old and i have played this when it came out but never ran in to game breaking bugs till now always getting stuck in objects and not being able to get out. out side that i love the game but cant give a good review when having to restart missions due to getting stuck', 'Very Positive', 84.67, 9.43, 1.63);
INSERT INTO reviews VALUES (52079, 2229940, 202, 'Ok I am having fun with this, so I will recommend, but I really need to warn people because I DID NOT KNOW THIS GOING IN that this is a game about RUSHING. You CANNOT take your time, you are on the clock and even if you do EVERYTHING perfectly and take 0 damage the entire run, you can still lose because Liz the Lunch Lady got in the pod 0.7 seconds faster than you.\r\n\r\nIt does not make this a mechanic until you''ve played for like an hour btw. It comes completely out of left field and completely c', 'First game ever that gets worse the more you play.\nFor those comparing this game to Hades, its easy to understand - Imagine if Hades AUTOMATICALLY increased your heat level the more you play and unlock things, EVEN THOUGH you didn''t clear the game a single time.\nYou never feel like you''re getting more powerful, because the enemies get stronger and enemies from later stages appear sooner. And you have zero choice on difficulty, or to even keep playing on the same initial difficulty.\nIf you compou', 'Very Positive', 86.14, 2.98, 7.83);
INSERT INTO reviews VALUES (52082, 2229990, 258, 'made me piss out of my butthole, 10/10', 'honestly: shit', 'Very Positive', 93.02, 0.15, 0.43);
INSERT INTO reviews VALUES (52091, 2230110, 1614, 'This is the video game version of those mass produced frosted sugar cookies you buy at the grocery store. It''s not good, but it hits if you''re in the mood for it.', 'This game is really cute graphically, but the gameplay feels... lacking. The characters don''t really have much personality or do  anything other than stand in their shops. There''s nothing that sets this game apart from all the other farming sims coming out right now. Generally feels like there was more of a focus on making it look cute than the actual gameplay :(', 'Mostly Positive', 78.07, 63.18, 3.52);
INSERT INTO reviews VALUES (52101, 2230280, 190, 'civ but tiny like my bf', '"This is a historical simulation game that..."\n\nNo, this is a match 3 with a "civilization" theme.', 'Very Positive', 94.74, 5.05, 1.00);
INSERT INTO reviews VALUES (52119, 2230650, 694, '10/10', 'It has better art, comparable music, a much more ambitious and complex story, full voice acting, and on paper is an upgrade over the developer''s previous title Rabi Ribi. \n\nThat said, I flat out had more fun with Rabi Ribi and was disappointed that this game didn''t captivate me the same way RR did. In RR, the controls were simpler, the story was stupid and self aware, the music was catchier, and the game didn''t take itself too seriously. \n\nThis team, despite putting significant effort into world', 'Very Positive', 94.67, 15.85, 119.38);
INSERT INTO reviews VALUES (52133, 2230980, 706, 'This game looks like it came out in 1999. It plays as if it came out in 1999 and is janky as any game from that era. Still, it''s better than Skull and Bones will ever be. 10/10', '7/10\n\nI bought this game a week or so after release. Game is fun overall but sometimes a struggle to "enjoy" mainly due to the charmingly nostalgic yet outdated systems and UI. Task/mission comprehension seems to be a consistent issue for the community, with many, if not most, missions requiring an external guide. Music, sound design, and visuals are decent (what you''d expect from a remaster) but all that is made better with various lightweight mods from the workshop. The overall story of the ma', 'Mostly Positive', 74.22, 0.22, 134.98);
INSERT INTO reviews VALUES (52136, 2231010, 348, 'the day i made a steam alt account was a start down a dark and horny path, enjoyable but i do question my life choices', 'Greedy devs ruined their reputation with this one. This was the most expensive part of the game as it is, but was unfinished and even then, they sold the unifinished ending as a DLC priced at ~ 30% of the game price itself. Absolute joke.', 'Mixed', 63.79, 54.72, 3.20);
INSERT INTO reviews VALUES (52146, 2231190, 103, 'My husband said if this review gets 100 likes, I can name our new kitty Flora.', 'I got this game cause I love crafting/cooking games and from the videos it seems just that but it''s mainly a platformer complete with disappearing/crumbling and moving platforms. Don''t let the cooking preview fool you. You need ingredients? Go platform to find ingredients or buy them from shops(which you have to platform to btw). It doesn''t help that the map is essentially a maze so for a good chunk of the start of the game you''re fumbling around trying to figure out which way is the right way a', 'Very Positive', 86.41, 17.17, 2.42);
INSERT INTO reviews VALUES (52153, 2231380, 14515, 'game crashed at the same time as the helicopter crash in the start scene realistic 10/10', 'If you are considering purchasing this game, do so with the full knowledge that support for this game ended in 2022. This game is only alive while the servers are going. Once they shut the servers down, this game will no longer be playable. You do not own this game, you are purchasing a lease on it until they shut the servers down. Consider this when making your purchase with your hard earned money.', 'Mostly Positive', 72.44, 79.95, 507.08);
INSERT INTO reviews VALUES (52154, 2231450, 42676, 'i love this game. i love the goofy art style, i love the fast gameplay and i love the amazing soundtrack. i had gotten this game from my aunt after i asked her to buy it for me as a gift but my account was hacked and the person who did it refunded the game and bought a dota 2 mask for 19 euros. i hope they commit sudoku. highly recommend to people who love games with fast gameplay.\n\nedit: i bought the game again, hopefully it doesnt happen again.', 'what are you doing looking for bad things about PEAKzatower \r\nTHIS GAME IS NOT FOR THE WEAK!!!\r\nand you aren''t weak\r\nso buy pizza tower', 'Overwhelmingly Positive', 98.50, 4.23, 128.22);
INSERT INTO reviews VALUES (52175, 2231890, 105, 'Gifted Word: Planning\n\nI cannot say how much this extremely short amount of time that I spent in this at this very moment has made me realize so much peace and understanding in such seemingly simple questions that really helped me realize questions about myself. In this short "test" I was able to ponder upon myself and was able to conjure so much development that I didnt realize I could produce nor needed, but this game did it gave that to me in the short 40 minutes that played it. I cannot reco', 'This one is a little weak compared to the others so far, which I''m currently playing in order of release. A lot of the questions are repeated from past games, and the final message I got was a pretty basic "Everything happens for a reason!" message, which is... kinda trite considering the suffering some people go through. If I was still as deep in my trauma as I was a few years ago, I could have taken that message very badly. Overall, not my favorite.\n\nMy secret word was "planning."', 'Overwhelmingly Positive', 99.05, 0.58, 0.25);
INSERT INTO reviews VALUES (52199, 2232600, 257, 'Fantastic Game.\r\nVery very few Anomalies which i didn''t like, only one i actually kinda hated, all of them where on the first map.\r\nThe Second map is just beautiful, great Anomalies, Nice Map Design, for my taste just a little too dark BUT you need the Darkness on the map for some Anomalies to work properly.\r\nAlso makes a lot of fun to play with Friends, even after you finished the game and play with them together to see which Anomalies they don''t spot.', 'Terribly designed game, when you mark things that are very obviously anomalies it still tells you you''re wrong and resets you.  This is probably one of the worst games in this genre, if you''re looking for something enjoyable try False Dream, False Mall or Floor 9.', 'Very Positive', 93.77, 3.88, 0.83);
INSERT INTO reviews VALUES (52222, 2233120, 979, 'For fans its very great product. For gamers who never heard of ''A Quiet Place'' this game might appear too slow and boring or you might like it . Gameplay a bit reminding of Outlast but in this title all revolves around SOUND and BE QUIET AS HELL . I played with mic detection stuff and its incredible . I hardly advise this game for all of u .', 'Don´t buy the game yet. Wait for some bug fixes and patches. It runs very poorly even on lowest settings. Very sad it´s not working :/', 'Mostly Positive', 76.20, 14.93, 0.33);
INSERT INTO reviews VALUES (52246, 2233600, 125, 'I have never had an interaction with a real woman', 'This game has ok graphics and game play. It is not really repayable. The actual NSFW content is small for 10 dollars its not worth it.', 'Mixed', 66.40, 0.47, 1.52);
INSERT INTO reviews VALUES (52319, 2235020, 323, 'I''ve been a Contra fan since I got the NES version as a kid, it brings back so much fond memories of staying up late playing with my brother. Operation Galuga has so many quality of life aspects that have made this game a blast, such as a health bar that you can increase, no more cheap 1 hit deaths. Plus now I can play with my brother online and relive the old days. This game has potential for a bunch of DLC, I''d love to get to play as the Cyborg Wolfman, Brad Fang once again, and in levels insp', 'As a classic Contra fan, I found the levels to be too difficult, too frustrating, and a little too long. The cool unlockables need quite a lot of points, too.', 'Very Positive', 89.16, 15.38, 2.48);
INSERT INTO reviews VALUES (52355, 2236070, 2546, 'Incredible game. its not a regular rage game, it lets you get better climb after climb and presents you a hard but doable challenge. You get the feeling its not a level made for you to get mad, but to get better. Also hi spiff thanks for the recomendation, plink', 'Wish I could love this game but it gives me really bad motion sickness', 'Overwhelmingly Positive', 97.88, 67.40, 0.75);
INSERT INTO reviews VALUES (52364, 2236300, 348, 'Grand Emprise is a wonderfully thought out and engineered game. What surprises is that it is one person''s brain child. That being said, of course there are certain things that may seem a little lack luster about the graphics and interactions. But what this game does make up for is the conceptual and philosophic context. More over, the game explores scientific theories towards the end.\r\n\r\nAll that to say, I really enjoyed the game. A big ''thank you'' to the creator. If this is what you can create ', 'They made really promising start that was fun and epic. But they then just abandoned the game and announced a second game. Seem like money grab.', 'Mixed', 67.82, 24.45, 9.88);
INSERT INTO reviews VALUES (52375, 2236860, 120, 'A quirky little indie that takes a cheeky swipe at the world of TTRPG gaming by presenting a plausible experience of your average social dynamic during a session of D&D. And they direct some thinly-veiled, smirk-inducing sarcasm towards Wizards of the Coast.\nAnyway, the premise doesn''t sound like much, but the writing is great and they pull off some good humour because they don''t try too hard. It''s a different experience and worth the money. And a sequel.', 'i do not recommend this - barely any playtime at all and the game ends . . . i felt scammed out of $4.49 nzd. if you buy this you basically just paid to sit there and waste half an hour reading fictional people argue with a fictional dm and suddenly they say welp games over!', 'Very Positive', 90.83, 11.23, 0.67);
INSERT INTO reviews VALUES (52422, 2237970, 1429, 'You know how after school or work or just an overall tiring day you''re looking for a game to help you really unwind and relax. but you can''t find one?\r\n\r\nTHIS is your game.', 'First island was fun. You actually progress not to fast, not to slow. But after that... thats it. Everything becomes extremly slow and so many things need a ot of time to craft, because exacly the resources you need for them are less. After a while all i seem to do is walk around and wait for the credits, which are also very slow to gain. After all, this was not a fun experience anymore and it just feels like a waste of time.\n\nThe good things i can say is, that the game has beatyfull graphics, g', 'Very Positive', 94.68, 45.38, 9.75);
INSERT INTO reviews VALUES (52426, 2238040, 863, 'its is a very silly, low stakes game that I crave. It reminds me a lot of a Short Hike or Button City. You just go around doing whatever you feel like, no crazy challenges, just little mini games, things to explore and junk to be found. The dialog is also very funny. To me this is what a cozy game is. No tasks or clock counting down (looking at you stardew) just do whatever you feel like when you feel like it.\n\nLife is hard. I''ve played EVERY From Software souls-like. I am tired and I just want ', 'I didn''t really like this game enough to recommend it.\n\nIt overall felt unfinished.\n\nI encountered a log of bugs, some weird performance issues (for a game that looks this visually simple, it runs like hot garbage). The story is barely present.\n\nOn a more positive note, I liked the fact that it was short (especially because of the lackluster story). I also somewhat liked the humor and the visual style.', 'Overwhelmingly Positive', 96.52, 2.98, 3.88);
INSERT INTO reviews VALUES (52451, 2238630, 131, 'This game is a gem developed by a solo dev.\nIt has great replay value because it''s a roguelite, and the fact that it''s a tactical roguelite makes everything feel even more special.\n\nI recommend it to everyone who likes tactical games, classic RPG settings and has that itch for roguelites.\n\nExcited to follow the game''s evolution and support :)', 'Alright I''m not going to lie the game does seem very fun but the balancing barely works half the time, for the following reasons\n1) Your characters can have random negative traits, which you have no way to reroll or control without just starting a run and instantly abandoning it. This wouldn''t be a problem if the traits varied by class or had any kind of balance to them. As it stands, a lot of your characters will have -1 action which pretty much neuters them earlygame, or your literal magic cha', 'Very Positive', 81.68, 1.70, 4.92);
INSERT INTO reviews VALUES (52462, 2238900, 1698, 'I can finally enjoy the game my friend''s dad would only let us watch him play on Playstation. This is how they should have remastered Final Fantasy VII', 'I never really got into the Star Ocean games - I had Till the End of Time when I was younger but I never got very far in it, and I played a bit of First Departure R on the Switch.  \n\nI was intrigued by the visuals in this game, but I''ve found most other aspects of the game to be pretty disappointing.  The combat felt very bland, the dialogue often dragged on longer than it needed to, and the story in the first 8 hrs at least wasn''t particularly engaging.  I did like some aspects of the skill sys', 'Overwhelmingly Positive', 96.35, 9.75, 8.38);
INSERT INTO reviews VALUES (52473, 2239150, 9613, 'Game is REALLY good. Simple but there''s still plenty of room for fun creative builds.\n\nTo the developer, someone is stealing your assets/IP from your game in a mobile app called Kingshot. The ads have the sound bits from your game. Hate to see your game being stolen since it''s so good.', 'i thought i was going to love this but i didn''t. it''s frustrating as you can''t place towers where you want, and you get easily overwhelmed and die if you don''t figure out how to do it the way the game wants you to. i don''t know what''s supposed to be strategic about this game besides choosing perks that seem to have good effects, but are basically useless. \n\nthis game could be so fun but it''s just not.', 'Overwhelmingly Positive', 96.40, 13.18, 1.80);
INSERT INTO reviews VALUES (52488, 2239550, 3906, 'It''s not a horrible game, just a massive step back from the previous two. Especially the first one. The city looks great, the gameplay is fine, but repetitive, and the story is just awful. Maybe if it didn''t lack a protagonist, it would be better. The concept of recruiting different characters with different skills doesn''t actually matter, as you can complete the whole game with one or two characters. I played the entire game with Aiden and Wrench. It''s such a "meh" experience. \n\nMaybe a 5.5 or ', 'Forced to use the Ubisoft Launcher, which screwed me out of my copy because it linked it to a random account instead of mine and their support is useless.', 'Mixed', 59.11, 70.73, 8.98);
INSERT INTO reviews VALUES (52492, 2239710, 1350, 'Solid game so far. Its pretty challenging, I do not like the weapon durability system though. You stealth kill 3 zombies and a combat knife breaks.', 'I enjoyed the demo enough to buy the game, but I can''t really recommend a purchase right now unless you have gobs of free time and a high tolerance for repetitiveness. The game does a great job of building suspense and actually makes you think hard about the logistics of your group, the weapons you use, and risk vs reward for each outing, but it''s just too punishing - enemies are all markedly stronger than the PCs and dogpile at the drop of a hat, weapons are few and far between and they break a', 'Very Positive', 91.70, 4.02, 36.32);
INSERT INTO reviews VALUES (52507, 2240080, 1737, 'got to listen to my autistic friend crash out about ocean creatures being in a river. 10/10 would recommend. very cosy. (don''t get her started about the whales)', 'Considering the length of the demo, I expected the game to be about 2-3x as long. the full game feels like a demo itself.\n\nthe ending comes out of nowhere and there is practically no buildup to it. the bottles are very finicky to hold on to.\n\nthe rest of the game looks good and is a bit fun but lacks any depth. few of the mechanics tie into each other in a satisfying way', 'Overwhelmingly Positive', 95.05, 1.05, 0.77);
INSERT INTO reviews VALUES (52511, 2240150, 347, 'I downloaded this game from "some" sources, after going to chapter 4 I came to clear conclusions, the game is worth its price or even higher, so I bought it on Steam, it tells an unusual story, people who looking for only erotic scenes will be disappointed, while people who want to know the story full of pain, fear, despair, loneliness but also love will be delighted with this production. \n\nFor me Huge YES', 'No sex whatseover in this game. There were a few romantic/spicy scenes, but not one of them was worth the money I paid for this. I read from other reviews that the story made it worth it, it didn''t. There are to be other seasons added to this one, hopefully they''ll start having sex.', 'Very Positive', 94.52, 10.28, 10.68);
INSERT INTO reviews VALUES (52534, 2240790, 870, 'in the bedroom straight completing it, and by it well.. i mean my rituals', 'aAaaaaH, a bit conflicted on this. I did not enjoy this, or at least not as much as I thought I would.\n\nOn one hand the gameplay is "better" (and every other aspect of the presentation), on the other there is more things to do (bad) and less eldritch dating (mega bad) in my eldritch dating game.\n\nSo yeah, if you prefered ACT1 & 2 of the first game, this brings more of the ACT3 to all the game. If you enjoyed the jump in interactivity in ACT3 then buy now because it improves it.', 'Very Positive', 94.71, 4.00, 2.38);
INSERT INTO reviews VALUES (52538, 2240920, 225, 'This game has given me hours of entertainment. I dont try to solve the case so much as I just try to frustrate and confuse the  bizarre characters I interact with. Pretty impressive AI, especially with updates. If you are looking for a good laugh then this game is for you.', 'Seemed fun, turned frustrating. npcs are confused - they''d give me information, and when i asked about it, they suddenly don''t know about it. If I tell them they just told me they did, they just say ''oh i forgot'' like a hallucinating ai lol. I also find it strange that the notepad doesn''t appear in every scene as an intractable button, so i had to keep jumping back to the map to look at my list of random names the ai peppered me with.\n\nOne hilariously frustrating moment was being told i should t', 'Mixed', 53.33, 131.22, 0.62);
INSERT INTO reviews VALUES (52542, 2241020, 101, 'Fun game just wish they would update it and add some new trucks and garbage cans.', 'I waited until this game went on sale for half off, and I will say it''s maybe worth the $6 I paid but I am still requesting a refund. Some trash items don''t even fit in the truck without significant struggle, and there is no objective or complexity to the game. You just drive in a straight line, pick up trash, smash the trash, repeat, until you run out of time. No story line, no career mode, and no other objectives or tasks. I played the game for about an hour and knew once I closed it I would n', 'Very Positive', 80.20, 38.40, 0.83);
INSERT INTO reviews VALUES (52563, 2241560, 139, 'From trailers I thought it would be like Axiom Verge, but it''s not. \r\nIt''s tight, short and to the point. \r\nMinimum amount of backtracking (unless you''re trying to save), no hand holding...\r\nCharacters are... peculiar, but no extra lore.\r\nThere are some... gripes (like ladders or lack of air control) but they''re not infuriating.\r\nThis game isn''t a full meal, but a quick snack. And it''s not bad at all.', 'Was drawn to this game by the pixel art and aesthetic which was done well throughout the game, but it suffers from pretty rough controls which take away from the gameplay.\r\n\r\nSome suggestions would be display options, a setting to review and edit controls, and full controller support (which i think has been mentioned)', 'Mostly Positive', 72.66, 4.15, 3.53);
INSERT INTO reviews VALUES (52589, 2242100, 353, 'The systems are in place. This has the potential to be a low-poly Stalker for those who crave more A-Life action, if the dev adds more POIs (lots of running between action now) and focuses on AI and spawns. I''d like to see him ditch the zombies in the future and add interesting mutant types and introduce anomalies in the overworld. No need for story or le hecking weapons as a priority, polish what you have and keep populating the map!', 'An interesting game, but at one point your base simply disappears completely, with all the things, boxes and buildings.', 'Mostly Positive', 71.10, 3.42, 19.57);
INSERT INTO reviews VALUES (52619, 2242760, 637, 'As far as the "co-op haunted house" genre goes, this game felt a lot better than others. Less replayability since the levels aren''t as randomized, but the puzzles are great and the atmosphere has much better tension. Absolutely worth the 4 dollars it cost.', 'Not scary only made my balls itchy', 'Mostly Positive', 77.71, 3.00, 0.73);
INSERT INTO reviews VALUES (52635, 2243110, 340, 'This is such a great survival horror action roguelite. I just wish I were a bit better at it (“Nightmare” difficulty is kicking my patootie, hard). Fans of top-down action and/or survival horror might really enjoy this. The aesthetic and sound design are top-shelf, and the controls feel really tight. It runs really well on steam deck. My only suggestion would be to new players-take a look at the options menu. I personally play with most of the visual aesthetic options set to “clean”. I understan', 'I get that this sort of horror is supposed to be a kind of miserable experience, but I think this goes a bit far. It''s pretty easy up until the boat level, most of the enemies can be downed in a few hits and have limited range. There are randomised difficulty spikes which involve tankier miniboss enemies or hordes of smaller enemies, but after a while there are regular groups of tanky enemies which take several full magazines to down a single one, let alone three. There''s no significant differen', 'Very Positive', 92.65, 37.45, 5.98);
INSERT INTO reviews VALUES (52640, 2243250, 105, 'Don’t judge it by the demo. The finished game made small but noticeable improvements to both level design and dialogue, and the rest of the game is in line with that.', 'The aesthetic is great, but I''m really not enjoying the moment to moment gameplay with this one, which sucks considering how much everyone else loves it. I guess it could improve, I did get unreasonably stuck on a very obtuse early game puzzle, but since I''m not really having fun here, I''ll drop it now and refund. \n\nAnd here''s one thing about creating, but cumbersome fast travel systems. Very cool for the first ocuple of times, but after that it just becomes a cumbersome fast travel system. Not ', 'Overwhelmingly Positive', 99.05, 5.42, 1.88);
INSERT INTO reviews VALUES (52660, 2243710, 240, 'raven best girl', 'If you''ve played Rune Factory 4 before, you will be disappointed by RF3. Lots of quality of life features are missing, can''t play as a girl, game is too easy. The only feature standing out is playing as a wooly but that serves nearly no purpose except storywise a few times. Overall undercooked and the weakest installment of the series.', 'Very Positive', 93.33, 4.47, 30.52);
INSERT INTO reviews VALUES (52678, 2244130, 796, 'So much fun! Well paced. I didn''t like Oxygen not Included, but this city builder/survival game has just the right amount of complexity. \r\n', 'It looks extremely cute and all the mechanics are there for it to be a great base building game, but it feels like I''m constantly fighting against the user interface and the lack of in-game information and proper management windows.\n\nThe weird console-style controls where you can''t just use your mouse to hover over icons when navigating menus like the research tree or report windows is a constant pain.\n\nYou''d think a game about rats would have better mouse support.', 'Very Positive', 88.32, 1250.55, 3.10);
INSERT INTO reviews VALUES (52697, 2244470, 135, 'Surprised at the mixed reviews.  This is by far the best in the series so far.  The new switches update makes this one of my favorite train games.  Scratches the itch of some of the more complex railway economic games, while in a package that I can easily finish within an available play window.  Comfortably fits in the space between casual and railway economic simulator without becoming too much of either.  Great game!', 'I really wanted to like this game but there are just some really annoying things:\n1. Trains don''t take a new route even if you laid tracks in front of it, it wills take a whole cycle to recalculate which is just stupid\n2. Signal Mode makes no sense. The in-game ''tutorial'' says "explains" it in 1 sentence with very little detail so no idea how it should work; my trains are either all stopped or they all crashing. It''s stupid -- can''t believe they put that feature in with zero explanation. Their ''', 'Mixed', 67.41, 42.57, 4.12);
INSERT INTO reviews VALUES (52780, 2246110, 123, 'After 42 hours I have finally beat the first level. I will update once I beat the second level.', 'I like the idea and the puzzles, but the inaccurate controls and imprecise hitboxes killed the fun very quickly.', 'Very Positive', 81.30, 60.50, 0.52);
INSERT INTO reviews VALUES (52791, 2246340, 63349, 'Guys, I like the gameplay and all, but could you add more menus to the game? I feel like there are not enough menus in the game. I would like at least 2x more menus for each interaction. Also, I think 2-3 types of party aren''t enough to play with a friend. We need at least 5-6 types. Maybe with 2-3 menus each.\nAlso, could you add 2-3 submenus in the main-menu?', 'Cool game, awful performance and worse optimisation. Capcom, if you do end up fixing the game and you''d like me to edit this review into a positive one it will cost you £3.49 for a "Review edit voucher".', 'Mostly Positive', 73.72, 49.23, 5.73);
INSERT INTO reviews VALUES (52823, 2246880, 1632, '8/10\r\n\r\nThis game is pretty good, though its unfinished, i can see it being worth the price!\r\nIts basically if People Playground and Garry''s mod had a threesome with Gorebox.', 'this game is pretty boring, the camera was weird and janky, i dont like the expressions when i kill stanley because it makes me feel bad, i want an option to turn off faces', 'Very Positive', 93.81, 13.07, 0.68);
INSERT INTO reviews VALUES (52844, 2247570, 109, 'it is a good game and i think the people here are really being unfair to it. although the economy in this game does need a rework it still is a fun and addicting to play. there not too much story though there really is no need for one, the takeover system is fun and the game itself is cute. I just hope they fix the economy issue but i would recommend this game', 'Just want to chime in and put emphasis on the fact that the cash mechanics have been very bad and not changed by the devs for a long time. Great idea but execution so bad that you should not buy. Changing the mechanic should not take too much time, which makes me believe that this game has been abandoned by the devs.', 'Mostly Positive', 74.31, 7.60, 16.85);
INSERT INTO reviews VALUES (52860, 2247820, 142, '5% halo (has a feature like skulls to make the game easier or harder)\r\n55% FTL (combat and general in space, has ship and crew you upgrade for story)\r\n40% Rimworld (a lot more customization of your ship being able to build pretty much whatever you want; crews have job priorities and more skills than FTL)\r\nI’m sure there is more I forgot to add here but it is a fun game, does not take much to get to where you can steam roll the game but there are options to make it more difficult, and while it do', 'A bit too simple and ''idly'' in some aspects yet too repeatable in other aspects. Would make a good time killer on a phone, but  there is are better options on PC.', 'Mostly Positive', 76.76, 41.70, 0.52);
INSERT INTO reviews VALUES (52884, 2248330, 120, 'Rest of backroom games: Escape the backrooms\r\nThis Game: Destroy the backrooms', 'Great concept, but can do better.', 'Mostly Positive', 72.50, 7.48, 0.88);
INSERT INTO reviews VALUES (52893, 2248430, 681, 'Biggest nitpick: Where''s the bangin'' level up music???\nEdit: Developer added level up music a week after I posted this, legend', 'awful. cant get past the first dungeon without game overing .tried 7 times. leveling vit does NOTHING. a game where rng means more than strategy is pointless. if this is the shit persona fans want to go back to, then theyre a bunch of crazy masochist! at least real touhou has good music and skill mastery even when insane. the story is likewise non existant. this game has ZERO good points! i want my 8 hours back', 'Overwhelmingly Positive', 98.38, 10.43, 7.85);
INSERT INTO reviews VALUES (52903, 2248760, 4145, 'I really enjoyed the game before 1.0 Had tons of fun i would recommend to everyone.\nBut since 1.0 my camera is just living its own life...\nIf i turn slightly to quickly, it freezes for a split second and i would have done a 3quarter spin, or full spin, it gets very irritating very fast.\nI hope this can be fixed cause i was really excited to check out the new map and everything it had to offer. But right now its just unplayable for me sadly. Don''t know if others had this aswell but..', 'I gave this game a legitimate shot. Here''s what happened:\r\n- Mouse bug made it nearly impossible to view anything. Messed with my DPI settings, mouse sensitivity settings (in-game), and turned down the graphics. This took the game from being entirely un-playable to mostly un-playable, at best. For a studio that claims to have a respectable office now, I cannot fathom how they are proud of this. \r\n- There is no map which makes navigation to *timed events* virtually impossible unless you have spen', 'Mostly Positive', 77.93, 34.00, 1.87);
INSERT INTO reviews VALUES (52911, 2248890, 127, 'Oh, what a sweet little piece! \nIt is practically perfect even from a Sherlockian perspective: pleasant, authentic, and remarkably peaceful. \n1920 may sound a strange choice for a year, as we know so little about Holmes and Watson after 1914, - but everything still appears quite plausible. The story is small but interesting, the puzzles are great, the characters are nice.\nThe only drawback is that is very short - it took me just a bit over 2 hours to complete the game with all the achievements. ', 'I hate to be the person who gives this a negative reviews and I so wish Steam had a neutral option. I just think this game is probably not for me (or players like me) but it seems to be plenty of people''s bag so to speak.\n\nThat being said, my personal opinion is that nothing happens and it''s boring. I don''t care about the main characters relationship and love so why would I care about their picnic? (Disclaimer: those who know more about Sherlock lore I guess may feel this was baked in, it wasn''t', 'Overwhelmingly Positive', 98.43, 2.28, 4.22);
INSERT INTO reviews VALUES (52912, 2248900, 126, 'At least in the game I can become a grandmaster.', 'Not so much a chess management simulator as it is a means to play chess against AI. The UI is a mess. Quitting the game in the middle of a chess puzzle results in losing all progress in the chess puzzle, and not being able to get it back. Essentially, you lose XP for quitting the game in the middle of a key gameplay moment. Considering the only way to get this XP is to play these puzzles, and these puzzles only happen once a month, this does not seem fair.', 'Very Positive', 86.51, 2.80, 3.73);
INSERT INTO reviews VALUES (52924, 2249160, 518, 'go to the bathroom before you play this. \n\n\nthat''s all I''m saying.', 'Mostly jump scares with little to no story really. I didn''t mind that it was short but it was overall just boring.', 'Very Positive', 86.10, 1.22, 0.90);
INSERT INTO reviews VALUES (52980, 2250550, 203, 'This loser named Bill keeps on insisting that I have "stolen his designs" and that I am a "damn thief". Well, I can assure you good people that these were unrealized ideas. I have corporate sponsors backing me while Billy boy is busy playing weather man for the local station. Stick around Bill, ''cause your days of sniffin'' the dirt are over.', 'the game is overall unrealistic and the videos of the game on the steam page are so fake the tornades just look like dust and you can see right through them the wind fields and almost everything about the tornado is just bad and unrealistic.', 'Very Positive', 82.76, 0.38, 1.98);
INSERT INTO reviews VALUES (52983, 2250600, 527, 'Much better than 6 as others have noted. 5 is likely the best mechanically, but I do enjoy the level design and verticality in 7. \n\nI do not, however, enjoy the move to chibi models that''s continuing here from 6. I can tell it''s cheaper to make.\n\nPixel is best.', 'this game has its issues, and follows the trend of nippon ichi shoving way too many annoying as fuck gimmicks into every game they create. did you like quests? No? well now there''s 10000x more of them. did you find it silly that all of disgaea 5 was dominated by the FMA land decimator spammers? well now you get robots that can kill literally everything in the entire map without even moving, in 1 turn usually. And anything you can''t kill in one turn, you can jumboify and make them teleport anywhe', 'Very Positive', 85.39, 15.52, 32.33);
INSERT INTO reviews VALUES (53023, 2251580, 145, 'The best interactive novel I have ever read. Gets a little bit heavy with all the self inflicting injury type stuff for my taste, but otherwise the narrative, the MC, all the other characters, as well as the choices and consequences are wonderful. It''s a grim, dark, medieval, brutal, and rather epic story, and I would recommend it to anyone who''s interested in any of those topics.', 'This game has excellent writing, and it''s nice to see some PTSD representation even if it didn''t sit right with me. \n\nThe lore was interesting but so many times I felt like being the player character felt like it was written for someone who has a hero-saviour complex. I didn''t feel the PTSD representation was very accurate and seemed to be written for people who want to imagine what it''s like but extremely dramatized to almost a funny degree. I could imagine the player character being someone wh', 'Very Positive', 92.41, 24.67, 2.42);
INSERT INTO reviews VALUES (53024, 2251620, 149, 'Enjoyed the game throughly\nsola best girl', 'SPOILER ALERT!\nThis is a game where I REALLY wish there was a middle option. The music and the visuals are a definite step up, with some reused tracks from old games along with new ones. The change in combat from a hex based grid, to a momentum based one, takes a second to get used to, but it''s an improvement once you do. It allows a bit more freedom instead of always just rushing or hunkering down. The team get''s stronger with more clear upgrade paths, and new options open up when the affection', 'Very Positive', 85.91, 77.00, 27.62);
INSERT INTO reviews VALUES (53058, 2252570, 5631, 'The first football game I played was FIFA 2003 on my brother''s original Xbox. Today, after the disaster that is EA and their games, I finally snapped. The winter sale enticed me even more. I had been contemplating on making the switch over to Football Manager for the longest of time, but was always scared of how complex it was/is. After forcing myself to play for 7.3 hours, I finally started to understand the hype and get a taste of what is to come.\n\nI''ve gone from dealing with EA''s mess to scou', 'Warning to you that considering buying the game:\nSI are not extending the licensing and force a patch 4th december to remove the licensing. \nThey already sold the software to most customers based on these licensed to be included and are now removing content we payed for.\n\nNew buyers please be adviced you will no longer get a complete game of you buy,', 'Very Positive', 91.90, 37.22, 1988.63);
INSERT INTO reviews VALUES (53059, 2252680, 131, 'I''ve been diving into the early access version of this game for almost an hour now, and I''m playing version 0.017, the very first release. In this time, I haven''t encountered any game-breaking bugs, though it''s clear that some fine-tuning is still needed. Despite that, the game shows great potential for a future hit.\n\nGraphically, it''s a delightful homage to pixel art games, with gameplay mechanics reminiscent of Stardew Valley and Animal Crossing. You can really see these influences in the musi', 'This game has less to do than a demo. None of the NPCs have any type of function apart from the sales ones. Yes, you can visit other planets, but only to cut down trees, bushes, mine rocks, catch bugs and fish.\n\nYou can upgrade your ship but nothing else. This is a shell, not even worth being in EA.\n\nAll the positive reviews come from fan boys of this twitch streamer dev.\n\nBe warned. Give this game time before buying.', 'Mostly Positive', 79.39, 1.37, 7.88);
INSERT INTO reviews VALUES (53136, 2254740, 629, 'any game with ryuji sakamoto is a good game to me', 'I got this game on sale, played through both the story and dlc, and it just isnt worth it. The more time that passes the more this feels very... amateurish? its a new direction for the persona series and I can see how it happened, but it''s also still a $60 game. can''t recommend in good faith, even if I bought it to hang out with Akechi for a few more hours', 'Very Positive', 81.24, 44.15, 36.63);
INSERT INTO reviews VALUES (53143, 2254890, 1351, 'Got the game because horny, but stayed for the gameplay and story!', 'Ok. the game is pretty enjoyable up until the stealth portion of the game. I don''t know why the dev thought it would be fun for the AI to instantly become bloodhounds knowing actually where you are even if you ran away to hide and infinitely spawning was a great game-play mechanic. Its super unfun and unforgiving. I like the game but seriously that one part of the game really kills any enjoyment I had for the game.', 'Overwhelmingly Positive', 95.78, 36.87, 71.40);
INSERT INTO reviews VALUES (53145, 2254910, 180, 'Nice game\nEZ to get all achievements 100%', 'Honestly pretty disappointed in this game. All the only "100 hidden" games are pretty straightforward and 2D, and while I applaud this dev for branching out into 3D, it really just makes the game run slowly trying to load the assets. The gameplay is also frustrating, in that I didn''t realize until probably 20 minutes in that I could rotate to find more frogs. I wish there were setting options, such as changing scroll speed, muting sounds/music, etc. Overall it wasn''t too difficult of a game in t', 'Very Positive', 80.56, 0.93, 0.97);
INSERT INTO reviews VALUES (53209, 2256450, 251, 'The game keeps interrupting my fishing for mandatory robot violence\n\nUPDATE: The game no longer interrupts my fishing for mandatory robot violence', 'game is CONVINCED you want to read every line of it''s snarky dialogue, it thinks it''s charming when it isn''t, it''s a shame too, was excited after the nextfest demo', 'Overwhelmingly Positive', 99.20, 14.82, 0.97);
INSERT INTO reviews VALUES (53232, 2257010, 593, 'Feels like a mix of creeper world 2 and 3. So far so good.\nAlso modding support for the base mechanics similarly to creeper world 4 but even more possible(modifiable it seems) extensive particle interactions like the game Noita or ye old falling sand game(FSG)/powder game(dan-ball) without the complicated pressure and wind physics at least.', 'For me mostly a downgrade to the previous installments. This is much more of a puzzle than an actual strategy game.\r\n\r\nIn previous games, you could be proactive and creative with your approach, you were constantly pushing in multiple directions, trying to keep approaches covered and figuring out how to best deal with the creeper.\r\n\r\nIn this, what units you have is fixed per map, and the ressources you have access to are frequently limited. So there is really only 1 solution the game wants you to', 'Mixed', 69.98, 74.80, 3.42);
INSERT INTO reviews VALUES (53255, 2257460, 116, 'great game play, good scares, casual experience. I really enjoyed playing. Thanks', 'Boring walking simulator. First of all, the premise is god awful, I''m in a crime solving simulator? Really? Second, the game gives like 0 chance for any tension to form, but tries to be jump scare city from the get-go and it blends with the premise to just being boring. Thirdly, it''s one of those walking simulators that have very specific checkpoints for the next "thing" to happen, which leads to you walking around an area several times zooming in on random stuff and pressing E on the (far too m', 'Very Positive', 85.34, 2.75, 0.47);
INSERT INTO reviews VALUES (53297, 2258290, 116, 'The game seems fun! However, Aimee with those chicken legs of hers (doing squats she looked pathetic) could never have done 100kg squats even in Smith machine. As for the bench press .. come on .. about 100 benchpress (even though it is still Smith)? A girl? With that result she would have been a pro powerlifter. At least I had my fun laughing at it :) \n\nSeriously, I am enjoying the game so far. The game looks quite unique in comparison with the other ones in this genre.\n\nI have just finished my', 'I am Going to say it has a Nice Story to it!!!  But i am not Going to Recommend, Because You Have to Buy Each Episode F**K That Sh*T that is a waste of money!!! That''s like i buy a Movie only to get to watch the first 30 mins to hit a pay wall have to hand over more money to keep watching this!! What a joke, People are to freaking Money Hungry These days it''s Sad!!!', 'Very Positive', 85.34, 8.90, 1.83);
INSERT INTO reviews VALUES (53307, 2258500, 161, 'Crymachina is a love letter…\r\nNot to the community, not to the genre, but for you. A game that completely flew under people’s radar, yet it’s one of those rare gems that I would recommend everyone to try out. \r\nThat alone is worth a gold star. \r\n', 'I really liked story but everything else was average at best. It would be fine but this game is noticeably short (my playtime includes finished game with a bit of grinding although with 100%). Devs expect you to pay for that full AAA game price and Imo. this game is not worth.\r\n\r\nIn short: buy only with heavy discount.\r\n', 'Very Positive', 86.34, 73.87, 13.42);
INSERT INTO reviews VALUES (53316, 2258770, 104, 'Very good story but on god please download the uncensored patch. This steam version softlock you in 2/3 of the playtrough and has a lot of cut content. I would put a negative review but it''s the censored version that''s the problem and not the game itself that is bad. Outside of that, it''s worth every penny.', 'It''s extremely annoying that you''re softlocked into a bad ending in this release unless you go download the adult patch on an external website, which then subjects you to adult scenes even if you didn''t want to pursue that route. The story of Kara no Shojo is great and I''m playing this as a reread because the last time I touched this was years ago but I spent over an hour driving myself insane with game guides trying to advance the story when I couldn''t. I don''t care if the steam release is cens', 'Very Positive', 91.35, 23.05, 10.17);
INSERT INTO reviews VALUES (53323, 2258940, 273, 'Sorry to lead with this, but Mage Kanade is probably... not worth $25.\n\n   Generally, short and simple lewd games and H-games on Steam give you what they advertise right: some basic gameplay and some hentai animations and that''s that.  There are a lot of hidden gems H-games that are decent shmups, decent zelda-clones, or even decent castlevania-clones (Midnight Castle Succubus for example).  An important aspect of most of these games is that they have some semblance of challenge, and that they t', 'i cant justify paying almost 30 dollars after tax for this. and even after the patch, im still seeing some of the scenes pixeled out which is so lame. way too short, way too simple. please take my advice and just bust it now and get the clarity, or get a good game like Scarlet Maiden or Sex Hex. Unfortunately Futa games are rare and most of them are borderline torture in terms of game play, but please dont stop trying because eventually we will have a great one. if this was 5 dollars id keep it.', 'Very Positive', 83.52, 2.83, 0.90);
INSERT INTO reviews VALUES (53335, 2259210, 201, 'I have defeated Megacorp on Normal difficulty using Engineer. I found the game very difficult at the start but once I found an operator that I liked and managed to understand how all weapons and enemies worked, I found it very fun and satisfying. I recommend the game to players who like trying out many different playstyles in their top down shooters. \n\nTo the developer: As a fellow game developer, I recognize how much time and effort have been spent on making this game. Well done and keep up the', 'Ridiculously hard even on casual. 45 min cannot even get past first level. Seriously, this is impossible to enjoy unless you some mega dark souls fan. Casual means fun and enjoyable not die in 2 hits as  you''re stunned all day. What are the devs thinking? Refund!', 'Very Positive', 80.10, 2.47, 0.73);
INSERT INTO reviews VALUES (53339, 2259260, 527, 'It''s as if Dead Cells and Dark Souls had a lovechild, with very charming PS1 graphics and textures!\n\nSuper Mega Recommended (SMR)', 'Unfortunately lacks too much variety or difficulty for a longtime souls player to find much enjoyment. Almost every enemy was quickly exploitable by circle strafing, it''s very easy to trigger aggro ranges and pull one enemy off at a time, and parrying is too risky to even consider with the punishing window to land it, especially when simply holding your shield up 100% of the time is incredibly rewarding, but also sadly boring.\n\nThis game does a lot of things well, but lacks anything really uniqu', 'Very Positive', 85.39, 3.80, 0.65);
INSERT INTO reviews VALUES (53342, 2259310, 411, 'It is really like real life. I work to provide for my cat. Nothing else matters. Cat is love cat is life. I would die for cat. I will endure for cat. 10/10 :3', 'Spoiler alert!!\n\nSo  i finished the game, it looked funny and it was! The new areas are nice but sadly its always the same creature with a different  skin. After  some time its just the same, over and over again. If the other areas would have a  other creature type, so that you have to learn new tactics it would be surely a thumbs up but yea... the ending was also not satisfying. I guess maybe you can find more lore about it all? Why there is a warehouse with creatures and why you are locked in?', 'Very Positive', 91.24, 5.03, 2.98);
INSERT INTO reviews VALUES (53382, 2260530, 173, 'If you''ve played any of the other "Hidden Cats" games by this developer, then you know exactly what you''re in for, for better or for worse.\r\n\r\nSome cute cats and brain/eye-straining hidden object game-play, accompanied by repetitive and ultimately annoying music.  Obviously some maps are harder than others, and the limited hints can be frustrating in the bonus levels, but take your time and zoom in on the screens as far as you can go and you should eventually find all the wee felines.\r\n\r\nRecomme', 'Out of all the Hidden Cats I have played so far, I do not recommend his one because it is a buggy mess.', 'Overwhelmingly Positive', 97.11, 1.55, 3.82);
INSERT INTO reviews VALUES (53405, 2261050, 224, 'A week ago I was diagnosed with a terminal illness and the doctors have given me a year at best. I''m so glad I was able to play this before I go. I don''t know how many people will see this; but I recommend to you to play this game if you do see it. Gameplay, atmosphere, graphics. everything is masterfully crafted. If you read it, thank you and good bye.', 'There is a genuinely nice game somewhere in here. The little auto-chess battler feels fun! It''s so poorly balanced that you will either have runs where you absolutely stomp or runs where you never stood a chance with nothing in between.\n\nThe adult scenes and features, by comparison, are terrible. Poor translation, low-effort characters, poor scenes (click dialogue, mash one area, click dialogue). It''s the first game like this that I have played where I would have patched it to remove the adult s', 'Very Positive', 85.27, 2.33, 1.92);
INSERT INTO reviews VALUES (53422, 2261350, 172, 'Genuinely super impressed with this game especially considering it''s a solo dev and in early access. Super cute and cozy, and has an addicting gameplay loop.\n\nVery excited to see how this game progresses in the future.\n\nAlso for those curious, the game runs well on Steam Deck too. I haven''t fiddled too much with the settings but dropping everything to medium and locking the framerate to 45 has provided a great experience', 'I would have to say wait for a bit before buying this game. I do like a lot this game has to offer, but it could use A LOT of quality of life improvements, such as not being limited as to where you place storage units, storage units not linked to crafting benches <a lot of games of this genre do this>, auto pick up would help a lot, grow times for crops is weird, you can plant crops that take a long time to grow, but if you plant trees to chop down, they are grown a lot faster, stack limits in s', 'Very Positive', 90.70, 5.50, 13.15);
INSERT INTO reviews VALUES (53457, 2262080, 147, 'Feels like Craftopia had a baby with Palworld and Valheim.\nIt''s cute, it''s interesting, kinda similar, but also different.\n\nThe game has potential to be something pretty awesome.\nDevs, don''t let me down, I believe in you!', 'It''s literally just a barebones Valheim with a worse version of Scratch. However to force you to use the basic programming, they''ve made the crafting system of Valheim tedious, meaning among other things only being able to craft 1 item per workstation and some of these crafting options taking longer than they need to. I''m gonna be honest it didn''t feel like a game, it felt like a basic course on coding with added gamification elements.', 'Mostly Positive', 77.55, 5.53, 1.17);
INSERT INTO reviews VALUES (53485, 2262610, 1098, 'just like the simulations except i''m writing my ma thesis, tiger-chan is replaced by astarion, and skye and hana are gay men kissing', 'This is, by far, the most boring game I have ever bought. The music is complete garbage and the phone screen wastes your time massively because it is made to open pixel by pixel and to slow down to a crawl in a way that it takes close to a minute to show up. You have to open that window repeatedly and wait every damn time. Do *not* bother with this game.', 'Overwhelmingly Positive', 99.00, 3.92, 1.08);
INSERT INTO reviews VALUES (53494, 2262770, 2329, 'Garten of Banban 2…. Where do i even begin….\nThis game is beautifully crafted by the Euphoric Brothers and to say that it offers a once in a lifetime experience would truly be an understatement.\n\nEverything in this game is charming. The visuals are stunning with everything from the characters veiny bodies to the highly aesthetic rooms highlighting how much care went into how this game looks. The music is great at building suspense, especially in the chase scene approaching the end of the game. I', 'I bought this game because my seven year old son would not stop talking about it. Clearly watching YouTube has warped his young mind and I have failed him as a father. Only playing the first and second installments - I feel confident in my assessment that this game is absolute garbage-trash-cash-grab-low-effort-nonsense.', 'Mixed', 68.78, 1.72, 1.83);
INSERT INTO reviews VALUES (53501, 2262930, 265, 'This game is not about solving puzzles, but about teaching your own robot exactly how to solve the puzzles automatically for you. As a player you are required to construct your own set of theorems to solve minesweeper. It is very unique and fun. The game is quite hard but is comfortably so.\r\n\r\nOn the other hand, its UI is... well... let''s be honest it''s far from ideal. It is as if figuring out which enigmatic symbols or numbers on the screen mean what, and figuring out how you can interact with ', 'Fun game on the surface, but eventually the rules just get repetitive. I found myself copy-pasting the same rule way too many times, when they could all be fused into one. The game''s autosolver also doesn''t treat rules which apply to 1+ to also apply to 2, 3, 1/2, etc, despite ALL of them being a narrowing conversion - they are a subset of 1+, so the rule will always apply transitively. If you don''t believe me, let me state it again in a different way to prove it.\n\nImagine any region with a labe', 'Overwhelmingly Positive', 96.60, 346.42, 9.07);
INSERT INTO reviews VALUES (53533, 2263510, 108, 'Great little Deckbuilder. It has a good amount of leader selection for the delve mode, which is similar to the rogue/exploration modes of other titles. It also has several other modes, which include constructed, arena style, and a multiplayer section. I personally spend most of my time on Delve, as that is what I enjoy. Each card is unique, as far as I can tell, being generated from a series of rules based on the cards faction or colour. This provides a lot of replay value, as you can collect a ', 'I love roguelite card deck builders. So the idea of procedurally generated cards sounded really interesting. Sadly I can''t recommend this game. I can get past the poorly designed UI that looks like a flash game from the late 2000s and can live with different font sizes everywhere. I''ve played hours of Monster Train, I''ll ignore the graphics if the game is engaging. \n\nThere is little to no tutorial at all. I''m expected to guess which stat is attack and which is defence/health (as the attack kinda', 'Very Positive', 90.74, 47.67, 0.60);
INSERT INTO reviews VALUES (53547, 2263920, 212, 'hole in 86', 'honestly the most tilting game I''ve ever played, its barely fun when its going well and it never does. That being said if you''re feeling guilt stricken due to a religious upbringing that you''ve now distanced yourself from...this is probably the closest you''ll ever get to hell', 'Very Positive', 91.04, 1.30, 1.62);
INSERT INTO reviews VALUES (53568, 2264340, 167, 'I own and played most of the tennis games like all the Top spin , all the Virtua tennis, Grand slam tennis, ao tennis, tennis world tour, tennis elbow, mario tennis... This is the first time in over 30 years playing tennis video games that we are blessed with such a big roster from both the atp and wta. So many tournaments to choose, the quality of the graphics and player faces and animations....All I can say, thank you Big ant studios. I have played all your tennis games and see that you have b', 'Look it''s a good game, I get the developer''s effort in the player''s models and moves etc, I get that it''s improving and I do see the potential in this game, but they physics is just not right. I play tennis in real life and other tennis games, but there are things that are just off. If u play under the Legendary difficulty in the career mode, like slams, you will see what I mean. First of all, apparently ur opponent has much more stamina than you, even you are Alcaraz, Second of all, they always', 'Mostly Positive', 71.26, 31.42, 13.60);
INSERT INTO reviews VALUES (53594, 2264880, 309, 'A game with different game mechanics in which you can do different things there, even present music in the game', 'The models are attractive, and the system for generating funds/points is interesting enough, but there isn''t really very much of a story at all.  This plays like you''re min/maxing a finance app. and if you do well enough you get to see events with women you do not care about or are interested in at all (because there isn''t much of a story).  I love H games, but this one felt like somebody sandwiched two ideas together without making the playthrough interesting.  This isn''t a sex game with intere', 'Mostly Positive', 73.79, 4.73, 1.87);
INSERT INTO reviews VALUES (53616, 2265310, 148, 'As an entomologist, this is an adorable and fun game for introducing people to the fun of collecting and studying insects. Definitely recommend this for anyone who enjoys bugs or anyone who has played Animal Crossing and enjoys building museums.', 'A game about collecting bugs sounded interesting. I love creature collectors and bugs are cool. So I was really excited to play it. But the actual gameplay is... well, isn''t. There''s not much of a game here. You just walk around hitting stuff until a bug appears, then you press a button to catch it. That''s it. Over and over. Ad nauseum. I got through half an hour of this before it became too boring to bear.\n\nThe shop dynamics don''t help, either, and the quests very nearly complete themselves. Yo', 'Overwhelmingly Positive', 97.30, 7.20, 0.50);
INSERT INTO reviews VALUES (53756, 2268470, 352, 'i wish russian women were real', 'not schizopilled enough cant cut my wrists at the end 0/10 literally unplayable', 'Overwhelmingly Positive', 97.73, 2.83, 0.38);
INSERT INTO reviews VALUES (53760, 2268560, 117, 'pretty neat game for the price tag, im a fan of survival sandbox games so this checks alot of boxes. minor bugs but nothing major so far. looking forward to seeing how it grows', 'It’s a good game but the only issue is I can’t use the guns when equipped the seem to disappear in hand and shoot but hit noting so it’s not really worth me playing', 'Mixed', 65.81, 14.65, 90.43);
INSERT INTO reviews VALUES (53855, 2270600, 157, 'Truly a very strong political message on the strenght of diversity and against the exploitation of workers in a society that should value them as living beings with emotions and not as just workforce', 'Mediocre, poorly translated, all of which would have been fine if they hadn''t also pushed an update that erased all of my save data.', 'Very Positive', 84.08, 2.82, 2.02);
INSERT INTO reviews VALUES (53903, 2271750, 177, 'If you love star trek and boobs this game is for you. \n\nOverall it was solid game. would recommend. \n\nHopefully some day we''ll get 3002: The MILF Generations', 'Great game but!!!!!!! The other chapters of the game will not be released on steam. Dev messed up W/characters A.K.A used actual characters that he had no right to use. Instead of fixing this Dev abandoned steam customers. So if you decide to buy the game realize there will be no more content for this game on steam.', 'Mostly Positive', 75.71, 2.23, 12.62);
INSERT INTO reviews VALUES (53910, 2271930, 460, 'I wont recommend the game in its current state. 2 Reasons. 1. Manual saves don''t always work.  2. The game had an update today that changed the settings I had for a casual experience. So what happened with the changes from the update? well I got killed by the dead at my base, and they also destroyed everything I spent tons of hours working on. And the kicker was I lost all the loot I had on me as well. So I am walking away from this game for a while. \n\nAfter I posted the bad review of my experie', 'Buyer beware, Epic Game account required to play multiplayer.  Can''t recommend this game until this has been resolved.', 'Very Positive', 84.13, 92.37, 5.05);
INSERT INTO reviews VALUES (53925, 2272250, 563, 'They took a great first game and made it even better. Great art style, even more defined and polished then the original. Also better maps and enemy placement and encounters. It still has some boomer shooter aspects but plays more like a fast pace FPS and not just one large room after another with a bunch of monsters in each one. Level design is also greatly improved. Overall I love this game and can''t wait for 1.0 next month.', 'Fantastic Game that improves on everything the original did and is a fantastic shooter overall!\r\n\r\nShame that it is now hidden behind an adware launcher that is being recognised as a virus by some Anti Virus suits, I''m sure nothing dodgy is going on there.\r\n\r\nI''m sure this was forced onto the dev by the publisher, if this gets removed the review will turn into a strong recommendation as the game is fantastic! \r\nKeep up the great work!', 'Very Positive', 85.61, 13.20, 4.27);
INSERT INTO reviews VALUES (53929, 2272400, 534, 'Warning: THIS IS NOT A TRAIN GAME.\r\n\r\nOkay, so - it''s a puzzle game first and foremost, that happens to have a train theme. But I felt compelled to warn that upfront because trains are my father''s brand of autism and I know how particular y''all train people can be.\r\n\r\nThis kind of caught me off-guard, since I had seen a teaser for the game in some Not-E3-Anymore showcase in recent years and just thought it looked like a cozy train game with a nice voxel artstyle. What I didn''t expect was how add', 'If you''re looking for a cozy train game, this is not it. It went from fun to stupid hard very quickly. If you like to bash your head against brain-straining puzzles then you will enjoy this game. If you want some relaxing wind-down time, this is not the game for you.', 'Very Positive', 88.20, 13.18, 2.08);
INSERT INTO reviews VALUES (53950, 2272900, 1082, 'Do not let the hours next to my name fool you; I''ve put just over 80 hours into the playtests over the last two months.  Getting a decent blend of RPG and Open World Survival Craft, can be really tricky, not to mention quite a bit of work.  A TWO PERSON DEV TEAM managed to pull it off--- but oh yeah, it is also a pretty cool farming sim with a deep NPC relationship component.  The fighting is a little simple, but I still find it quite fun (and this is coming from someone who plays Valheim, Enshr', 'Let me start off by saying I love this game, I think it has so much potential.  But it is way too expensive in its current state. do not call this a version 1.0 when it should still be in early access.  there is so much that is locked/unavailable/blocked off that it makes it so frustrating.  whats more frustrating is I will complete the game and then the game will be updated and I will have no desire to replay the game because I already completed all the quests.  WAIT TO PUT OUT THE GAME UNTIL I', 'Mostly Positive', 74.31, 0.30, 22.55);
INSERT INTO reviews VALUES (53966, 2273430, 3553, '!Spoilers to the story of BlazBlue CentralFiction!\nLet me get 1 thing clear: this is a good game. It is a good rogue-lite and is overall fun to play. It has nice artstyle and music. Combos are super fun. If you want to play a good rogue-lite and don''t know anything about BlazBlue, play this game. I, however, have 2 major issues with this game:\n1. Game is too easy. I am constantly playing on Hard with maximum of debuffs I can get, and the game is still very, VERY easy. Except maybe on the last bo', 'if you bought it on a steam sale and still dont feel like you got your money''s worth then maybe dont recommend it. ive spent easily over 60 hours on hades but less than 15 hours in this game already makes me feel bored. they should have had fewer number of characters and more time cooking the level designs. also the visual clutter can be unbearable sometimes.', 'Very Positive', 94.82, 30.47, 18.22);
INSERT INTO reviews VALUES (53988, 2273980, 1806, 'Alright let''s start off with what this game is NOT. It is NOT Orcs Must Die 4. This game plays like the devs had a villain origin story where they heard someone say "Orcs Must Die is so easy that I just leave it running over night" one too many times and just snapped and poured in pure pain and malice. It is STILL A FUN GAME but do not go into this expecting a game for casuals or a typical Orcs Must Die game lmao. This game is brutal and often frustrating but the discord is active and the devs a', 'Missing an early access label, a massive step down from previous titles and absolutely not worth the price right now.', 'Mostly Positive', 75.58, 247.02, 0.58);
INSERT INTO reviews VALUES (53994, 2274110, 528, 'I grew up with a lot of jmbt02''s flash games, so having all of my favorites + some new ones that I hadn''t experienced in one big collection is awesome. Also having flash games preserved beyond flash''s death is always good so thank you for taking the time to make this collection as well!', 'severly unoptimized and seemingly abandoned, with no updates in sight, which is an absolute shame considering how good these games are\n\ni am looking forward to being proven wrong, but until then i suggest you play the games from this collection through flashpoint', 'Overwhelmingly Positive', 96.21, 2.73, 3.85);
INSERT INTO reviews VALUES (53999, 2274200, 211, 'I have no idea what is going on, but its beautiful, extremely interesting, high sci-fi and with good physics combat.\n\nLike seriously, but I mean this in a good way, I have not the faintest clue what is going on.', 'this is the actual worst quality vr game i have ever played it has some of the worst combat i have ever seen, the sfx make this game sound like a quest 1 game, the custom sword painting is terrible and the enemies have the worst of the worst attacking animations. actual quest game save your money this "game" over priced as shit.', 'Very Positive', 90.05, 2.28, 0.48);
INSERT INTO reviews VALUES (54013, 2274480, 141, 'Full disclosure, I don''t think I actually put 30 hours into the game, and not in a "the time was flying by!" kind of way but a "that number is 100% bugged" kind of way.\n\nThat said, it''s an extremely good game. In a world where most economic games have simplified economies and are "buy sugar at a low price here and sell it at a high cost there", this game goes out of its way to tell you nothing. Where is a good place to buy sugar, where is a good place to sell sugar, what even is a good price for', 'I was happy to see this game going on sale.\nHowever, my joy didn’t last very long.\nEither, I mastered the game very fast or I was incredibly lucky, but I got fairly rich very fast.\nAfter 30 minutes, I started to get bored and since nothing changed, I decided to refund the game.\nI didn’t feel challenged, nor I had the feeling there was much strategy involved.\nAt times I got frustrated when I tried to trade large sums of money, either the money I owned or that of the customer. The result was alway', 'Overwhelmingly Positive', 95.74, 29.77, 2.32);
INSERT INTO reviews VALUES (54015, 2274510, 232, 'Fun game, especially for the money. I hope the devs continue working on it so that the multiplayer can actually have real people. The bots are kinda cracked sometimes for no reason. But ultimately a funny idea and decent game play loop and mechanics. As a white guy from the suburbs, it felt great to finally experience what growing up in da hood is all about.', 'Made me create an account to play, annoying but okay, then my password/username was immediately incorrect? \n\nWeird okay, maybe my username is my email even though it just made me create a custom username? okay weird, but It worked. \n\nLog in to my first game, this is pretty cool. Got my first kill, realize that ITS DISPLAYING MY ****ING FULL EMAIL ADDRESS AS MY USERNAME.', 'Mostly Positive', 75.86, 3.00, 0.08);
INSERT INTO reviews VALUES (54038, 2275020, 375, 'Best backrooms game I''ve played. Dev updates and improves game regularly too.', 'I just refunded the game, I fell for the positive reviews. The game to me is quite bad, another very generic take on this backrooms genre. It''s poorly optimized and looks horrible with all those VHS and film grain/noise effects. IT''s like you are watching a messed up VHS tape, who wants that? You can''t even turn the effects off in graphics settings to get a clean image. Hard pass.\n\nPS: I have POOLS and Liminalcore here, they run smoothly and look 100000x better than this, which runs like crap', 'Mostly Positive', 74.13, 5.13, 0.20);
INSERT INTO reviews VALUES (54045, 2275150, 608, 'I used to hate smoking. But then I started working...', 'Definitely a bit of a sophomore slump since this game feels more like DLC than a standalone sequel. It takes the original map of SLUDGE LIFE and makes it less dense, less interesting, less challenging, less funny, and overall less engaging. Giving the player more items is nice in theory, sure, but they take away all the challenge of the first game ( although the sprint was much needed and double jump was helpful at times). After getting  the JJ''s  right off the bat, there were never any tags or ', 'Overwhelmingly Positive', 97.20, 6.43, 2.35);
INSERT INTO reviews VALUES (54059, 2275560, 155, 'An awesome story with great replayibility. You really get a feel for the personality of the characters, and perhaps most shockingly, it passes the Bechdel test.', 'More than 2 years of development, its 1.5 years seems to be on steam and yet we never got frequent updates, always wait and wait and get a dissapinting update in terms of lengthwise and as steam users, we get them days after its patreon release it seems.\n\nIts the end of season 1 the dev says on its latest update yet we still have zero content for nearly half of the romance options.\n\nGame is marvellous on art and story side but the lack of content and lazy development schedule is so annoying, so ', 'Mostly Positive', 77.42, 10.17, 2.25);
INSERT INTO reviews VALUES (54075, 2275940, 101, 'It’s not just a strategy game with some deckbuilding elements!\r\n\r\nAs a Slay the Spire fan, I was introduced to roguelike deckbuilders through it and have been hooked ever since. At first, I was skeptical about mixing deckbuilding with strategy elements like resource management and eras. I expected strategy to dominate and deckbuilding to feel secondary—a "decide your strategy, then tweak your deck" type of gameplay.\r\n\r\nHowever, I was pleasantly surprised! Your deck choices have a huge impact, an', 'Wish i saw the AI declaration before playing. Game is a valid take on the civ game style, though it is not a complete game and more of a proof of concept, and I say this beyond the scope of the "early access" info provided. Would love to see this turned into a real product (and with real art)', 'Very Positive', 92.08, 121.82, 18.68);
INSERT INTO reviews VALUES (54113, 2276830, 231, 'An RPG where the depth just kept revealing itself, with a job system that enticed me and then unleashed my unhinged devotion. Battles can go from "okay how do I handle these guys?" to "feel my meticulously crafted wrath" in just a couple hours of play. Once I also realized how it all ties with navigation, it was over for me. I was hooked and in.', 'If you LOVED Horizon''s Gate, and its sense of vastness, optimism, and possibility; its beautiful graphics and its witty, accessible dialog... You will probably not like this game. Horizon''s Gate was an open-world exploration game with interspersed tactical combat. Kingsvein is a tactical combat game with a weakly-presented frame narrative and a few constrained elements of exploration. It opens with a sequence which fails to establish a status quo, a motivation for the protagonist, or any other m', 'Very Positive', 90.91, 32.45, 5.97);
INSERT INTO reviews VALUES (54115, 2276850, 182, 'good game very scary faecal matter had entered my underwear at least twice', 'Hope you like jump scares, because that''s all you''re getting in this game.\r\nConstant jumpscares. Loud noises to scare you. Things suddenly appearing in front of you screaming., then nothing but calm and your suit squeaking for a while, and then back at it to make you regret purchasing this game.\r\n\r\nScanner Sombre (the tech demo for the lidar bit) was imo way spookier than the game that came out of it.', 'Mostly Positive', 79.67, 2.05, 2.55);
INSERT INTO reviews VALUES (54119, 2276930, 4462, 'I''ve worked at several aquariums and this just really scratches the itch for me. I like the scaling between the different packs, there is a nice chill capitalism game mechanic that takes over your brain when you play this because having new shiny fish is important. Now im at the stage where I can recreate georgia aquarium sections to my hearts content. This game also fulfills the niche of watching fish swim to calm your mind and your heart rate. And you get to learn some new species. it rocks.', 'way too grindy. if it was more automatised it would have been fine but even then, I can''t even imagine the amount of hours you''d have to put into this to get all the achievements.', 'Very Positive', 94.35, 77.03, 105.40);
INSERT INTO reviews VALUES (54121, 2276980, 532, 'I don''t care about clicker games, but the style of this one had me interested. Banger soundtrack too.\nTook me 2.4 hours to reach the end, which I think is a good length for it not to get old. Pretty fair for the price, I think. There''s also an endless mode that''s unlocked when you reach the end, though I don''t know if that offers anything extra.\n\nOverall, I had a good time with it.\n\nAlso, make sure you enable the experimental audio player in the settings so that you get Winamp instead of Windows', 'Finished the hard mode (which is literally just artificially lengthened) in 2.6 hrs with a few periods of afk.\n\nThis is a basic incremental game with one system that you will manage for the entire game, there is no real development. The only progression mechanic is buying upgrades of the Auto face identifier. Everything else around that is just buying upgrades to not lose the game, i.e. enough CPU, RAM, cooling and some others.\n\nStory is dull and cliché with nothing new or interesting.\n\nHard pas', 'Very Positive', 91.73, 2.43, 2.55);
INSERT INTO reviews VALUES (54127, 2277090, 112, 'Absolutely delightful little game. I was looking for something to scratch the Obra Dinn/Golden Idol itch and this was the PERFECT scratch. I felt like that most of the deductions were achievable, but not spoon fed (some specific details were... pretty much impossible for me to get, but i was able to complete the segment with what info i did have). Some of the daemon descriptions made me laugh out loud, and it''s obvious that a lot of thought and care were put into writing ALL of the investigation', 'I put this game to my wishlist when it''s first announced and thought that it will turn out a game like Golden Idle with unique design, story and smart puzzles. It is not bad though but didn''t worth the wait. Nothing is extraordinary and every piece of this game is okayish which is sad. Ad package is good but the actual game is not that much', 'Overwhelmingly Positive', 98.21, 5.47, 0.27);
INSERT INTO reviews VALUES (54135, 2277320, 418, 'Incredible game, hyrbid God Game with some Strategy & Roguelite elements. Wish there was more games like this, was definitely worth the price.\n\nYes, could do with some QOL improvements (like dragging on the minimap to smoothly move, or having icons for enemy spawners/bases, and for showing which unit you have selected on the minimap), and the AI for defending is sometimes great and sometimes stupidly rudimentary - simple battle strategies like spreading out to avoid AoE abilities, etc, there''s n', 'no Save & Quit, only Give Up, wtf???', 'Mostly Positive', 78.23, 42.42, 7.62);
INSERT INTO reviews VALUES (54167, 2278010, 125, 'As all the games they have made since King of Dragon Pass, this is an amazing story trapped inside a tribe sim, which makes it all the better, as the stories are directly intertwined and depend on your decisions and actions - an important character died? story will continue without him - Did half of your population get eaten by a maggot-looking demon? your economy is pretty much destroyed, but the story will continue. The difference with the previous title is that instead of fighting for a bette', 'I spent most of time looking for food and not engaging with the wider world. I get the story they are trying to tell but the game play is so narrow I couldn''t have fun with the game. A lot of the negative reviews say the same so I know I am not just bad. This game I guess sold a  lot less the  previous games. It doesn''t have many guides or walkthroughs for it. It also has weaker production values. Events repeat and characters children get the same events just with a name tweak. What is worse is ', 'Overwhelmingly Positive', 96.80, 18.75, 17.95);
INSERT INTO reviews VALUES (54195, 2278790, 124, 'calling it now its gonna hit overwhelmingly positive within 2 weeks. \n\nAn improvement over the original in every way, the movement feels faster and fluid, level design is bigger and more open with plenty of missable secrets, better boss fights and more of them, and there is a 2nd dog now. Luna has a different abilities from Pablo so it will take a bit of adjusting as you swap between the two. Luna with her air dash and firing her gun. In a addition with added unique abilities you find in levels ', 'I think I need to play Grapple Dogs 1. I had a lot of fun then the levels started to get really long and grindy with finding the gems to unlock more levels and finding 20 keys to open a door. Definitely worth trying but the grind started leaving me conflicted. \n\nI love Pablo''s gameplay (this game has a 50/50 split playtime for each character) a lot more that''s why I''m saying I should try the first game.', 'Overwhelmingly Positive', 98.39, 16.77, 4.37);
INSERT INTO reviews VALUES (54198, 2278830, 178, 'Sure the game isn''t finished yet but it''s still very playable, and quite fun. Especially for 3 bucks. And claims of it being abandoned are totally unfounded if you actually care to look at the discussion board. The dev explains that he has a lot of demanding things in his life that take priority over the game but he still plans to finish it. He has a couple of updates about this actually. So i wouldn''t call this abandoned at the moment, but development is definitely paused for the foreseeable fu', 'abandoned', 'Very Positive', 87.64, 4.97, 3.55);
INSERT INTO reviews VALUES (54216, 2279330, 192, 'love it!\nreminds me of my childhood, getting on the bus and listening to starfish sledgehammer and co. with my friend on our way to school <3', 'I got the original Savant for a dollar a decade ago, and got this for free for being an owner. This remake is fine with that consideration, but for a 10 dollar game as of now, I can''t recommend it.\r\nThere are still awkward control elements. You can''t shoot when you are jumping. Start button on Xbox controller while paused will unpause and repause a frame later, too bad there''s no need for frame perfect buffers. There is no Back button support in the menus, so you have to navigate extra steps to ', 'Very Positive', 89.58, 2.05, 7.48);
INSERT INTO reviews VALUES (54233, 2279600, 316, 'Really fun gameplay, but I think needing to spend currency to play a level is annoying game design. Once you learn the general design of each level, they become pretty easy to clear- so having to go back and constantly replay the cheap levels every time you have a bad run is tedious and not fun. I feel like levels should be free to play, but you lose a percentage of your money every time you die. Makes failure similarly punishing, while also making it possible to progress through the game withou', 'It''s a game I REALLY wanted to love but every mechanic felt underbaked. The stealth generally didn''t feel worthwhile enough to really engage with. The tools while occasionally useful weren''t enough for me to even consider using and the fact that escaping doesn''t allow you to bring any tools back is pretty crazy considering how all the equipment seems to be just minor stat buffs. The combat feels nice most of the time but the lack of combos besides the launcher was disappointing and left me wanti', 'Very Positive', 89.87, 6.22, 2.20);
INSERT INTO reviews VALUES (54259, 2280350, 271, 'Ignore the people saying the handling is garbage, they''re probably holding w the entire time. It''s not that bad if you''re driving like your life is on the line, which it is. \n\nIf you die in the game you die in real life. Be careful.', 'They banked way too hard on the driving mechanics (which arent good) and now this feels nothing like turbo dismount at all. driving is way too forced upon to player, and too stiff to control. if there was a healthy ratio of driving levels to dismount levels, it might be ok, but a majority of the levels in this game force or expect the player to manually drive the car. (even some levels labeled as dismount do this.) not to mention poor optimization. I really cant rate this game positively in it''s', 'Overwhelmingly Positive', 98.52, 2.82, 1.77);
INSERT INTO reviews VALUES (54271, 2280520, 248, 'new ending\nwe need more voices in the game\nwe need an increase in the quality \nwe need sex \n\ni love my wife', 'No seggs or nudity', 'Overwhelmingly Positive', 95.97, 13.33, 3.17);
INSERT INTO reviews VALUES (54314, 2281480, 100, 'It''s perfectly fine, not that much there but what is there is fun and well worth the price.  A couple of things could stand to be more clearly explained, but you usually figure it out.  Cheap game, got well more than my money''s worth of fun out of it.', 'It looks interesting on paper, but just feels... anemic? There''s absolutely no "OOMPH!" to any of your mechs'' (!!!) weapons. Moreso, both your units and enemies feel extremely floaty, which makes just playing the game so underwhelming. Also because of this, while there''s theoretically a lot of weapons and mechs, they all just feel the same and boring.', 'Very Positive', 87.00, 10.43, 0.92);
INSERT INTO reviews VALUES (54322, 2281650, 283, 'Game is really good, it has great mechanics, but the studio is dying and it''s heartbreaking to see people calling it an "Early access scam" . They know dev made a break because they have no money left and people still leave negative reviews because there''s no more updates, knowing negative reviews will confirm the downfall of the game.\nIt''s harsh to see an unfair cycle of doom like that...\n\nGreat game nonetheless, I hope the best for the devs in their future projects. <3', 'Game had much potential, but it''s abandoned. Last early access update is 7 months ago.', 'Mixed', 65.37, 21.28, 4.42);
INSERT INTO reviews VALUES (54329, 2281820, 113, 'That game really took me by surprise. It''s genuinely good. Hard as heck, sure, well it''s a roguelike after all so it can come down to luck every once in a while (I''ve seen a couple comment about the third boss, yeah, it''s difficult, abusing sleep/freeze/sticky can help but it''s doable with incremental damage/abusing bond) but damn satisfying. \nAnyways, it''s  great, figuring out the fusions is most of what I find fun, there''s a sense of wonder in trying (or not) to mash up beasties together and g', 'I want to enjoy the game, but there are flashing effects and there doesn''t seem to be any way to turn them off (I tried a few things in settings, including changing the filter, with no luck).', 'Very Positive', 84.96, 39.20, 0.33);
INSERT INTO reviews VALUES (54336, 2281940, 183, 'Beat it in 15.7 hours, but only to like 75% completion. Fun little Metroidvania game. Don''t listen to the reviews complaining about backtracking and taking forever, there are a lot of fast travel points with the last update and there are a lot of QoL features that make traveling and exploration not such a slog.\r\n\r\nIt''s a little bit simple, and pretty short, but I had plenty of fun with it for the price tag. But now I just want to go back and play Shadow Complex for the 10th time.', 'This is a game that seems like it has so much potential at first, but after playing for (only) 1.5 hours, it feels like it''s just repeating itself. The graphics are cool to look at, but after 1.5 hours of the same backgrounds, the same enemies, the very generic music and the not very engaging level design I decided it wasn''t worth it.', 'Very Positive', 83.61, 15.73, 1.05);
INSERT INTO reviews VALUES (54403, 2283460, 119, 'A perfect game that foreshadows the future events of 2069, where Mr. Führer comes back to life and takes your hoes...', ' The Dissapointment \nI purchased this game with high  hopes , however i was largely dissapointed with what I saw. I expected a game of constant non-stop sex with the former fuhrer, Instead I was met with shitty gunplay that isn''t good and poor craftmanship. There was a very minimal amount of cunnilingus and that made me cringe in horror and defeat. This is a  MAJOR  dissapointment and I hope in the future  Adolf Games  can learn from their mistakes and create an engaging experience for gamers an', 'Mostly Positive', 79.83, 1.82, 0.13);
INSERT INTO reviews VALUES (54419, 2283780, 243, 'This is hands down my favorite VN game. Story, Characters, location, interaction. there is also daily games, puzzles, picture hunts and interactions with the women. I could go on and on. This has some of the best comedy written through this game as well. I have played through a few times and still continue to play different routes and choices im at 150+ hr''s played. Wildman_Dev is a single person, one guy made this game and is still going strong not to mention the 2nd part of this story, which I', 'I cant recommend this game.  9 hours into it and not enough action.  That''s 9 hours of skipping long drawn out conversations hoping to open the flood gates.  It will let you skip at any time so that''s a plus but the action up till now is minimal.  The renders are good though.  I cant comment on the story except i was reading it all till I got bored and started skipping.  I just played "s3% Robot" and it was great compared to this.', 'Very Positive', 83.95, 168.27, 11.83);
INSERT INTO reviews VALUES (54499, 2285550, 136, 'its peak im afraid\r\nits one of those games that dont do anything particularly innovative but what it does do, it does well. \r\nit also has little QoL tweaks such as being able to save mid-day, to move chests that aren''t empty, to fastforward instead of skipping cutscenes entirely.\r\nthink graveyard keeper without the slog, and without needing to read the dev''s mind', 'The game does seem relaxing and cozy. However, the pixelation was too much for me - sprites ran together and I had a hard time discerning where items and interactive spots were. Placing and targeting felt a bit clunky at times.', 'Overwhelmingly Positive', 98.53, 10.85, 0.33);
INSERT INTO reviews VALUES (54503, 2285630, 309, 'A fun survivors like, worth a play :)', 'I play every game like that . This one is not very enjoyable. Clunky and very very unbalanced. \nI think 3-5 hours at its best - that it. If you dont expect more its maybe okay.', 'Mostly Positive', 78.32, 1.57, 5.58);
INSERT INTO reviews VALUES (54508, 2285820, 232, 'This Game is perfect for anyone who likes gears that spin and turn other gears that turn other gears until the end of time. NOT SUITABLE FOR ANYONE WITH A LIFE', 'Devs clearly didn''t actually understand torque, angular velocity, gear ratios, or practically any other mechanical principle related to gears. Several of these terms feature in the game but are just shoehorned in to pander to the aesthetic. This is just your average idle-game shovelware, like you''d find on a mobile app store, with a gear-based paint job trying to mask the gamedev sins. Stick with a decent incremental game like adventure capitalist or cookie clicker; at least their gameplay-loops', 'Mostly Positive', 70.69, 38.63, 64.92);
INSERT INTO reviews VALUES (54534, 2286390, 534, '"Oh I have a degree in Network Administration, this seems like a neat game about networking computers, let''s see what I can figure out about it"\r\n*8 HOURS LATER*\r\n\r\nYeah this thing sucked me in deep lmao', 'Tunnet is a niche game for a very specific kind of person. If you are not the kind of person who enjoys computer networking, or has a real interest in tinkering with computer networking, then you will probably not enjoy this game. I thought I might have been that person, but I was wrong. Also losing several thousand dollars to the first jump scare really sucked.', 'Overwhelmingly Positive', 95.32, 19.13, 1.83);
INSERT INTO reviews VALUES (54576, 2287220, 935, 'Monaco in game is more interesting as in real life.', 'dear lord, just sell the ip to a different dev', 'Mostly Positive', 77.22, 141.78, 15.88);
INSERT INTO reviews VALUES (54578, 2287330, 372, 'As an ant game lover, I really can''t give this game a thumbs down... but I''m still disappointed that it''s not the same RTS style as "Empire of the Ants" from 2000 or "Empires of the Undergrowth" or even "SimAnt", where you actually take part in building a colony: gathering food, nursing brood, engaging in combat, etc. In this game, you play more like a scout and commander, with everything taking place above ground, which kind of loses that true ant colony vibe. There''s no attacking the enemy que', 'This is a hard review to write because I absolutely appreciate the devs for giving this concept life. However where the game falls short for me is the complete lack of colony management and having conversational dialogue between Ants to move the "story" forward which is extremely immersion breaking when set against realistic graphics.\n\nFor some odd reason in the back of my mind I had hoped it would have been a modern version of Sim Ant from SNES. A game where you could start a colony from scratc', 'Mostly Positive', 73.92, 76.07, 0.58);
INSERT INTO reviews VALUES (54587, 2287520, 3548, 'Had a fun time with it! Flat mode released today so I thought I''d finally go through another FNAF game. VR is of course always the preferred experience but it actually worked out pretty well in non-vr.\r\n\r\nProbably the biggest thing I really have to say about this game is; thank you Steel Wool for not including Night 4 of Sister Location', 'I really wanted to like this game, but it''s vastly inferior to the first. I expected a campaign mode where I could play all of Sister Location and FFPS but it''s unfortunate we''re still getting generic shooting-gallery games in 2024.\n\nI wasn''t expecting anything groundbreaking or genre-defining, I had pretty lax expectations but this game is nothing more than a sleazy attempt at combining Wii Sports and Job Simulator. It feels much more disjointed and uninspired than the first, I played almost 2 ', 'Very Positive', 94.87, 11.37, 0.92);
INSERT INTO reviews VALUES (54592, 2287710, 107, 'Having read a decent amount of vns, this one isn''t bad at all.  The story is very simple and the game doesn''t take itself too serious.  Most of the characters in the game are enjoyable especially Monica lol.  Overall its not bad at all.  My main dislike about the game is the way it ended suddenly for season 1 and it could use an upgrade on animations but other than that I had a good time reading it.  Would recommend and looking foward to season 2.', 'now near after 6 month still no updates DON''T BUY WAIT SEASON 3', 'Overwhelmingly Positive', 95.33, 7.72, 49.65);
INSERT INTO reviews VALUES (54606, 2288070, 179, 'This game is fantastic! As a fan of the Super NES version, playing this reminded me just how well certain game genres can still hold up today when done right. If you''re a fan of beat ''em ups, this is an absolute must-play!', 'A reimagining of a classic from the SNES era. Keeps what made the classic great, while adding two new characters, and mechanics. Not that the story was a big draw, but it would have been nice if they added a couple of cutscenes.  The deal breaker for me which turned it from recommend is the fact that in order to beat the game and unlock the new characters you have to beat it all in one sitting. There is no way to save your run and come back to it latter.', 'Very Positive', 94.41, 12.28, 4.27);
INSERT INTO reviews VALUES (54611, 2288150, 302, 'It''s a polished up rebuild of a PS2 era game.  A lot of the bad reviews are people that were expecting some kind of hot new content, and wanted all the extra layers of BS from newer entries.  A remake of 8, in a series that is in the teens now.  WTF were you expecting?', 'Good game, absolutely braindead terrible AI. The AI in this game stands for artificial idiocy. In fact the original game had better AI, go figure.\r\n\r\nWill keep this thumbs down unless AI is upgraded to an acceptable level.\r\n\r\nVery little game options too, Koei is getting very lazy.', 'Mixed', 68.54, 23.05, 142.18);
INSERT INTO reviews VALUES (54626, 2288630, 275, '50€ game\n70$ drum\n1 broken window (it was the neighbours)\n-2 arms (it was the rhythm)\nfree serotonine (it was the festival)', 'It''s definitely fun, but the combination of micro-transactions and the always-online battle-pass monthly subscription with "pre-order" songs (whatever that means) feels incredibly predatory. Wait for a sale,', 'Very Positive', 92.00, 98.90, 3.27);
INSERT INTO reviews VALUES (54650, 2289390, 150, 'I don''t like most management games, but this is an exception. I love my silly lil crabs. My only suggestion would be that they could use some silly lil hats.', 'The first 5 hours were fun, however it doesnt currently feel complete or like a rougelike. Nothing changes on the second run, so if you won the first there feels like no reason to continue. Really hope that work continues on this but it feels like early access to me.', 'Very Positive', 88.67, 4.35, 5.60);
INSERT INTO reviews VALUES (54663, 2289650, 361, 'The core gameplay is addictive, and the programming-like waypoints are a nice innovation over older aircraft control games. It''s kinda underhanded that the developer named the game this given that it''s ripping off the fame of Mini Metro and Mini Motorways, both rather more polished games than this one.', 'If you are buying this because you loved Mini Motorways: don''t.\n\nWhat I loved about Mini Motorways was the satisfaction you got by seeing everything going smoothly. You needed to strategically position everything, and it payed off.\n\nIn Mini Airways, you are constantly giving directions to the planes, while the upgrades kinda help you automate it. But still requires a lot of interaction.', 'Very Positive', 91.97, 25.08, 0.35);
INSERT INTO reviews VALUES (54680, 2290180, 4895, 'Recommending zen mode in this game because it helped me glide through a very difficult week I had. \n\nI was assigned to a really stressful project at work. It was the first time I experience height of anxiety and depression. I used to come back from office and open this game with Zen mode and for next hour I just used to snowboard or cycle through mountains. As I do like all the stuff IRL as well It provided me a short escape from all the anxiety. I highly recommend this game zen mode if you are ', 'Says its the complete edition, then i go to the longboard area and it asks for 20 dollars before i can access it. then year 4 pass is another 20 dollars. This isn''t the "complete edition" when i would have to toss another 40 dollars at it in order to have all the content...', 'Very Positive', 81.82, 14.23, 0.52);
INSERT INTO reviews VALUES (54719, 2291020, 197, 'The culmination of the entire Science Adventure Series. Unlike other entries you''re thrown right into the thick of it, making it very well-paced. \r\n\r\n If you''re coming from steins;gate (anime or VN), DO NOT PLAY this until you finish the other mainline games (Chaos;Head Noah, Robotics;Notes, Occultic;Nine anime). This game takes key elements from those stories and uses them in new ways, so having previous knowledge will greatly improve your enjoyment.\r\n\r\nThe ending of this game and the themes it', 'Big SciADV implications, good visuals, voice acting, and a decent soundtrack. But the story... the world building... the characters...  They''re falling behind. Big time. Honestly, such dry characters are undeserving of having such big implications for sciADV world. I''d rather it be Okabe, Takumi, Kaito... Anyone who had any bit of character and development.\nFor this price (with disount), you could get Chaos;Head, Robotics;Notes and Steins;Gate. Think about that.', 'Very Positive', 85.79, 21.60, 32.25);
INSERT INTO reviews VALUES (54720, 2291060, 3667, 'This is not the first time this year that a B movie-inspired Steam game about shooting bugs added a third-party account requirement that wasn''t previously necessary. In this case, it also happened to be an Epic account. Not Epic Games Store, mind you, but that was never going to go over well with Steam users. The requirement also wasn''t disclosed until release day.\r\n\r\nIf you came here wondering why reviews are "Mixed," there''s your answer. On the bright side, it''s less intrusive than you''d expec', 'Requires a third party account with Epic Games to play online with friends, even if you only play with people who are solely on the Steam platform. There is no indication anywhere on the Steam page that this was the case before purchasing and is definitely a shady, potentially illegal business practice.\n\nConsidering that NONE of the previous titles ever required this, it boggles my mind as to why they thought this would fly, especially on a competitor platform.\n\nEdit: As of around 0600 (UTC -6),', 'Mostly Positive', 75.84, 64.47, 0.13);
INSERT INTO reviews VALUES (54730, 2291340, 519, 'This was a fairly realistic babysitting simulator, though they hardly touched on the cosmic horror of real babysitting.', 'I will simply NEVER forgive the the developers for the loss of NEWT. I hope you all have a bad Christmas. In fact, I hope on the next possible morning that all of you stub your toe on the edge of your bed. NEWT shall never be forgotten, a lost angel. RIP. Forever in our hearts. I cannot recommend this to anyone simply on the basis that I would subjecting them to the loss of a loved one. That, I simply cannot and WILL not do.', 'Overwhelmingly Positive', 96.15, 1.43, 2.72);
INSERT INTO reviews VALUES (54741, 2291760, 8213, 'This game has changed my life forever, It may be only 56 hours I have played this game, but I have left my family behind to be permanently be working at Papa''s Freezeria. There is no turning back now.', 'Lame ahh game waste of time i do NOT recommend go play apex legends or smth else 0/10 overrated as heck', 'Overwhelmingly Positive', 99.23, 56.30, 271.50);
INSERT INTO reviews VALUES (54744, 2291850, 1235, 'I have made it a mission to slowly go through all rusty lake games in order of release. This was the last game on my "to complete" list as it is the most recent. I have spent the past year getting through all of them and being continuously impressed by each one. This game is absolutely no exception and is a perfect example of a developer becoming a master at what they''re doing. This is an improvement over all prior entries in every regard. The story is phenomenal, the puzzles are great, the chap', 'Rusty Lake PLEASE DO SOMETHING ABOUT YOUR GRAPHICS. They are so ugly and amateurish. That was fine when you were doing silly little flash games but not when you''re asking money for something that looks as horrid as this. I know that you''re most likely just a two person team but I also know you make FUCKTON of money from these games. Or at the very least enough for you to hire a proffesional artist that can draw better than this middle school level stuff. And don''t you dare try to say that "it''s ', 'Overwhelmingly Positive', 97.41, 2.85, 3.73);
INSERT INTO reviews VALUES (54754, 2292060, 446, 'The core experience is somewhat similar to something like Noita or Path of Exile where you cast spells that activate other spells that activate other spells etc. etc. While reviews say that the game is relatively simple mechanically, I disagree. Often, your spell cast loops will depend on you either by attacking with your weapon light combo, heavy combo, dodging, or by casting your main spell. Your weapon combo''s length and weapon damage depends on the given weapon, which can alter how your buil', 'Rough around the edges. I''m amazed the game is so well reviewed.\n\nThis game features spells and trigger that charge mana for spells (and auto-cast them). It''s a nice baseline for an action roguelike, however the game is closer to a survivor''s game in gameplay, as movement is slightly too slow, attacks are effectively spammed and spells are pretty much automatic. The entire gameplay is moving out of the way while fighting enemies and then moving to the next arena to do the same.', 'Very Positive', 93.05, 9.42, 0.50);
INSERT INTO reviews VALUES (54764, 2292260, 818, 'When I was a kid I was too scared of the monsters in the sewer to progress beyond the third level, but now, thanks to Nightdive and the passage of time, I am a big boy who can finally finish the game.', 'Having played the original when it first came out in 95...and also playing The Force Engine version...which is free to download and fixes all the bugs the original had...my conclusion as Dark Forces Remaster is exactly that...1995 Dark Forces with a new paint job and optimized for modern computers...yet still has all the bugs that the original did...Personally I recommend buying the classic version...and download The Force Engine...while it may not be as ''pretty'' as the remastered...it is the su', 'Very Positive', 91.69, 5.78, 0.40);
INSERT INTO reviews VALUES (54782, 2292650, 483, 'Recommended, it is a very nice escape room game. Good puzzles, nice graphics, but very short. I completed it in just over 3 hours, so I would also recommend to wait for a sale, it is not worth the price per hour otherwise. \nLuckily you can spend some more time on the bonus level and on getting 100% achievements.', 'Game seems really good so far but I have to downvote because of no freaking manual saves between checkpoints. I really don''t like my life schedule depending on a game. Especially an escape-game, you don''t know if your run is going to last 30 minutes, one hours, maybe way more if you don''t get stuck. I want to be able to do a quick session before going to bed and resume it at my convenience, not the game''s convenience.', 'Very Positive', 92.96, 4.72, 3.90);
INSERT INTO reviews VALUES (54792, 2292800, 484, 'Fantastic economy management game, played it from the demo and have waited for it since. Really chilled out game you can either take part in or sit back and watch it all happen. I highly recommend this.', 'Not worth it. Shallow gameplay. Too few development options. No complexity and no interesting choices. Brainrot.', 'Very Positive', 86.16, 3.52, 0.40);
INSERT INTO reviews VALUES (54840, 2293680, 345, 'I played this game for a little during the Beta and from my experience, this game has absolutely LOADS of potential. I have high hopes for this game and believe that upon release (minus typical day 1 release quirks) this game will scratch the Medieval Survival itch you are craving! The graphics are beautiful and the performance was great on an old/borderline outdated PC. One of the biggest compliments I can give to this game/studio/devs is how involved with the community the team is. The Creator', 'There is an Admin to this game that basically accuses everyone of cheating. He destroyed part of our base claiming he was looking for evidence, when he didn''t find any he did not replace anything he broke. Repeatedly kicking players back to the main menu. Going invisable and deleting chests that are placed. This guy is straight out admin abusing the players on the PvP server. He goes by the name Prince Major. I suggest  anyone with even a little raiding/pvp skills to avoid this game like the pla', 'Mixed', 65.80, 166.07, 27.30);
INSERT INTO reviews VALUES (54849, 2293850, 151, 'This game has taught me some valuable life lessons like: Deforestation gets you hot furry women (and futas) to gobble on your drain pipe, It doesn''t matter whats in your pants, you CAN and WILL get pregnant, mining is awesome and children should be sent back to the mines as a form of discipline, Fertility and pregnancy is like gambling you can win small or win big, I somehow got cami pregnant 1 million + times just from 5 minutes in a mating press (atleast theres no child support). Overall this ', 'was okay, very what you see is what you get tho', 'Overwhelmingly Positive', 98.68, 18.13, 0.28);
INSERT INTO reviews VALUES (54862, 2294130, 1474, 'I’d totally recommend this game! Sure, the devs might''ve bounced, but it’s still a ton of fun for the price!', 'The art style is cute and popping enemies feels very satisfying, but the game doesn''t really do anything that hasn''t been done before. I think it''s also held back by boring and repetitive music, the game''s art style and vibe would be the reason to pick this over its competitors but the music kind of ruins it.\n\nJust grab Brotato or Vampire Survivors or one of its many clones instead.\n\nEdit: The game still needs work but it appears to be abandoned by the devs, it is unlikely that it will ever get ', 'Very Positive', 90.91, 20.77, 4.08);
INSERT INTO reviews VALUES (54884, 2294660, 1363, 'The Quinfall had a rough launch with many server stability problems. That being said, bugs are to be expected with most MMO launches. I have not played many $20 games that engaged me as fast as The Quinfall has however. When the servers are working this game sucks you into a vast and beautiful fantasy world! I''ve reached lvl 30 as of this moment, and (outside the few bugs/server performance issues) it has been a wonderful experience! I''m excited to keep playing and see how this game develops! Th', 'refunded due to shady developer, the selling of Unity Asset Store items  as Cosmetics which is against the Unity ToS and just being a temu Black Desert Online. \n\nThe combat is also straight from the unity store.\n', 'Mixed', 52.02, 34.83, 0.63);
INSERT INTO reviews VALUES (54888, 2294730, 183, 'Bought it, and the kids love it.', 'About 75% of the content this season are flashbacks to season 1...', 'Very Positive', 83.61, 2.72, 13.25);
INSERT INTO reviews VALUES (54923, 2295610, 130, 'This game was returned, BUT dont let that be a cause for you not to buy it. This is one of those situations where it should have a more nuanced review system on steam.\n\nThe game is fantastic, old school, arcadey feel. The controls and options are very limited but that actually works for the old school charm and the need to know exactly how close you need to be for an attack to connect both in dealing and taking damage. The ONLY reason that I returned the game is that this game is the type that r', 'Only for annoying "challenges" instead cool slasher i cant recommend this. I dont know why modern devs think that "challenges" is needed for any new retro game. Just made cool slasher/beatemup and thats enough.', 'Very Positive', 90.00, 1.92, 2.70);
INSERT INTO reviews VALUES (54934, 2295970, 186, 'Got this game thru Steam''s digital store when it was on sale just late April of this year. I grew up watching Super Robot animes during the late 1970''s thru early 1980''s. Being from Philippines, I became a fan of "Mazinger Z" & "Voltes V(five)" when I was just 4 or 5 years old. Before coming to the States, my parents & I moved to the Middle East (Saudi Arabia) during the early 80''s thru early 90''s. This was when I first heard of "Grendizer" watching its episodes. Even though I didn''t understand ', 'I wanted to like this game but it has too many flaws. Even if you’re a fan of the series, the game is extremely repetitive. The graphics other than the robots are pretty bad. The performance is also bad and the game is unoptimized. You can upgrade Grendizer to the max only after you have finished the game which is pointless. The music is pretty good as it’s mostly from the anime.', 'Very Positive', 83.87, 32.05, 17.50);
INSERT INTO reviews VALUES (54944, 2296380, 416, 'Another banger game in this banger franchise. Ive seen a lot of people say this is the weakest game out of the trillogy but i honestly prefer it over the first one, if your hesitating buying it due to the reviews just buy it its really fun', 'as someone who has purchased all 3 games in the series, cog in the machine feels incredibly stale especially in comparison to the first and spy and the liar\nthe story is bleh, the villain doesn''t hold her own (especially not in comparison to John Juniper. can''t even remember her name) and the puzzles, while fun, are missing something, relying more on spectacle than interesting ideas. and the little things too- the opening credits sequence isnt nearly as entertaining or good sounding as the first', 'Very Positive', 93.75, 6.67, 10.97);
INSERT INTO reviews VALUES (54951, 2296550, 391, 'Best tower defense game since Defense Grid 2 for me. I like the aesthetic, the high number of viable tower types, and the ability to alter paths.', 'This game seemed novel at first, but quickly became frustrating and tedious which is saying something for a tower defense game. I''m used to TDs, I''ve played plenty of them. This game however seems to be either bugged or just poorly planned out. Some of the permanent perks you buy seem to not always apply or activate or they interfere with one another when you start new runs, the rate at which you gain resources is too slow to be able to gain much headway and adequately bolster your defenses in t', 'Very Positive', 89.51, 16.62, 26.05);
INSERT INTO reviews VALUES (54965, 2296990, 990, 'Fun game but beware if you suffer from motion sickness.\n\nThe last puzzle was incredibly nausea inducing and reminiscent of migraine aura. \n\nI wish there was a way to turn off that screen effect because the last puzzle was quite fun but we had to throw in the towel because of the screen effects.', 'Ill give it to you that the game is fun, but the bugs especially in the Sirens curse puzzle has to be the most frustrating thing ever. For that reason I cannot say I would recommend it because I have now closed the game ten times due to frustration.', 'Very Positive', 86.57, 5.60, 4.47);
INSERT INTO reviews VALUES (54992, 2297650, 186, 'Very adorable game with little challenging gameplay when It comes to platforming. The graphics, characters and the story, everything was amazing over that It took like an hour to finish.', 'Jank controls, even when using an Xbox controller as recommended.', 'Overwhelmingly Positive', 96.24, 1.47, 0.15);
INSERT INTO reviews VALUES (55010, 2298300, 224, 'I love the tower defense genre, and this game stands out from others with its interesting action, as if you were watching a movie and playing on a VHS cassette', 'There''s definitely something fishy about the many positive reviews for this game. Carnage Offering isn''t very good, especially compared to the popular TD games on PC. \n\nThe gameplay is very basic: there are only 7 different towers without unique perks or different upgrade paths. In combination with the very limited spots where you can build a tower, you''ll end up using the same towers over and over again. Except for the last few levels, the game offers no challenge at all because you''ll rarely b', 'Overwhelmingly Positive', 95.09, 3.10, 9.43);
INSERT INTO reviews VALUES (55020, 2298590, 114, ' very good changed my perspective on German culture in the 1940s', 'Not enough content', 'Very Positive', 83.33, 0.27, 5458.25);
INSERT INTO reviews VALUES (55038, 2299130, 111, 'Tutorial on how to get to the OnlyFans industry.\n\nRe edit: This is my first adult game that I purchased here on steam, my experience playing this game was great, I completed all the achievements, 100% recommended.', 'There really isn''t much to do here but click your profits and upgrade things. Sure, it''s an idle game, but it really tries to pretend it isn''t.\n\nAlso, most importantly, everything you need to click is on a menu that completely covers the girl. So, why play a lewd clicker over cookie clicker if you can''t even see the girl?', 'Mostly Positive', 76.58, 3.98, 3.15);
INSERT INTO reviews VALUES (55071, 2299900, 2657, 'Great Game, gorgeous art, would recommend. What I cannot recommend is playing Dungeons and Dragons with the creator Jozef Pavelka, because he killed my character with friendly fire.', 'If thee can readeth this without t sev''rely annoying thee, then mayhap thee shall enjoyeth this video game. unfortunately f''r me, this typeth of oration is grinding on mine own senses and I cant spendeth anoth''r minutia reading this shit. Oth''r than yond, generic-ish rpg with valorous graphics 6/10', 'Overwhelmingly Positive', 98.76, 8.73, 4.53);
INSERT INTO reviews VALUES (55083, 2300160, 198, 'Slava Ukraini!', 'instead of focusing on graphics and realism, the authors focused on propaganda.\nthere are other drone games free of political references\n\nP.S. yellow and blue smoke trail behind the drone - what is that for?\n\n', 'Very Positive', 91.92, 0.37, 0.23);
INSERT INTO reviews VALUES (55089, 2300300, 112, 'Not bad if on sale for under $5.  Took roughly five plays to unlock all milestone-based content, after which it''s a pleasant enough "reverse minesweeper": think of it as using mines to reveal tiles, and therefore needing to reveal more mines than you spend so that you can keep going.\n\nWould be nice if the order you find certain animals changes (to shake up the puzzle), and the game gets noticably easier once you unlock additional "points of interest" for each map (these not only reveal multiple ', 'It takes less than 2 hours to understand that this game terribly lacks interest. Don''t get me wrong, the game is cute, the idea interesting and refreshing (no combat as usual), but it is just an RNG, nothing more. No strategy, nothing to think about, no replayability. Nothing. Nada. Once you finished your first area, you pretty much finished the game because there is nothing more. And to finish the first area, you will need some luck as long as you understand the very basic concepts of the game.', 'Very Positive', 91.96, 8.63, 2.98);
INSERT INTO reviews VALUES (55091, 2300320, 8698, 'Finally, I no longer have to deal with my single-neuron-sharing workers. Or at least, that''s what I hope... (I hoped in vain)', 'Been playing since 2009. All the graphics and ground deformation stuff is cool but there''s even less content compared to FS22 and it''s disappointing... Half stuff is put from FS22 season passes and that makes even less equipment then in previous game.. I''m guessing they put less content just to sell more packs and season passes in the future. Everything else is fine', 'Very Positive', 81.72, 33.50, 44.67);
INSERT INTO reviews VALUES (55093, 2300340, 148, 'I just completed the first dungeon (Oracle''s Cave). So far the game is beyond cute, very fun to play and brings back vibes of Zelda, Animal Crossing and other games I hold dear to my heart. Can''t wait to play more and see what the Dev adds!', 'It''s a short game, for the money. Also camera angles and hard to turn cameras are a pain. I am slow at games\r\nand mess up on jumps... a lot. I''m a Grandma and play like one too took me 10 hours but I''m guessin someone younger would spend close to half that time. The whole game is done and I finished all I could find to do, talking to everyone ect. Story was okish but not great and again hard to line up jumps or gliding with the camera angles. My Grandma rating at best is 5 out of 10 and that is ', 'Overwhelmingly Positive', 97.30, 1.58, 10.10);
INSERT INTO reviews VALUES (55177, 2302140, 366, 'Maybe the real journey is the shrimp we made along the way', 'The game has cute art, and good music, and interesting looking world\n\nThat being said, the story felt... incomplete, there''s too many character but the game is short so the characters are not fleshed out enough, and I also don''t understand all the imagery in the game, maybe I missed something but there are very vague to no explanations for all the things that exist in the game. I feel like the game has potential to be even better but alas.\n\nIf you like cute stuff I think you may enjoy it, but th', 'Overwhelmingly Positive', 95.36, 2.12, 2.08);
INSERT INTO reviews VALUES (55178, 2302150, 170, 'this game is great. glad you are able to realize your dream. \n10/10 gonna buy it again. this gonna be my go to gift game from now on.\n\nthanks Thor for bundling this Gem of a game.', 'It''s abandonware, unfortunately.', 'Very Positive', 87.65, 9.87, 0.10);
INSERT INTO reviews VALUES (55198, 2302660, 2306, '"I don''t like Mr. Crawling at all" I say, then I suddenly tripped and fell to the ground, as multiple pictures of Mr. Crawling fall out of my bag. "Wait!" I madly cried out. "These aren''t mine!!"', 'you cant fuck them', 'Overwhelmingly Positive', 98.96, 7.67, 9.12);
INSERT INTO reviews VALUES (55220, 2303350, 3838, 'So I love this game and it''s extremely fun to make silly little sticker scenes but there are some things that would make it so much cozier.\n\n-custom text (although its omission is definitely understandable)\n-copy/paste sticker elements (I''ve had to drag out the same element repeatedly to complete a sticker on account of I want more of something or other, and having to color, scale, and rotate each identical element is pain)\n-edit already-created sticker, or print sticker on a different type of p', 'The Devs keep adding achievements locked behind paid DLC.\nThe gameplay itself is repetitive and bland. I found myself spam making stickers by the end of my time with the game. No longer finding any joy in creating endless pages of the same stickers to just finish the game.', 'Overwhelmingly Positive', 96.77, 33.78, 19.62);
INSERT INTO reviews VALUES (55269, 2304440, 131, 'Maybe it''s just me, but I don''t really want to fight or kill things. At least I don''t anymore. The world is just too full of violence. I am so happy to have found this game. Welcome to a world where you get to explore, learn, and pet creatures. You are here to save them but in the end I think you really learn to save yourself. Fixing the problems and learning from the people and creatures of the planet feels so much better than just blasting zombies or pwning newbies at respawn points. If you ar', 'The game´s creatures are pretty cute, and i like that you can pet them, and that they have skills you can use for exploration, but sadly it´s mechanically pretty boring.\nI expected something more along the line of, say a 3d monster sanctuary, but it all stays surface level. Nothing much is done with the creature´s skills and there is basically no challenge to the game.\nAdditionally, quite a few things in this game are badly thought out. You can lock yourself out of content by completing objectiv', 'Very Positive', 86.26, 36.12, 12.17);
INSERT INTO reviews VALUES (55280, 2304620, 270, 'This game should honestly be more famous than it is. It now has a cool feature where you go into random backrooms and try to figure out what entities, radiation level, and pasts of signs explorers are. This game is actually pretty entertaining and hard for some of the levels. I highly recommend this game and playing it in groups is the best. Been recommending this game to all my friends.', 'GPU Had to be shipped to the PC Doctor.', 'Very Positive', 80.37, 82.82, 2.00);
INSERT INTO reviews VALUES (55281, 2304640, 137, 'OK, we are talking about a low price game here that is of the "hidden objects" genre.   Not the kind of game I normally play (For Managed  Democracy!) but it was a cute fun diversion I picked up for the wife where we could burn a bit of time together in mindless low grade fun exploring the main game maps, and those created by other users.  The music was nice, the animations were nice, the maps were nice.  If you are a "Hello Kitty" fan like my wife is, or you are married and want to spend a bit ', 'So this would be a yes recommendation if it was not for the bugged Master Detective Achievement which the appears to have been an on going bug since the game came out almost a year ago and still has not been fixed.\n\nThe actual game play is fine. The art and levels are solid. The Worded  play hint system is interesting. \n\n\nHowever seeing how instead of fixing the bugged achievement they released DLC does not sit right with me. If and when they get the bugged achievement fixed I will probably swit', 'Very Positive', 82.48, 7.33, 7.30);
INSERT INTO reviews VALUES (55283, 2304660, 238, 'this game is amazing and it is in early access bare in mind.\n\nas a new player it can be punishing, but also at the same time rewarding, the more you level up the better characters you get.\n\nIt doesn''t explain a lot, but at the same time it has one of the friendliest and most helpful team working communities in any other game i have ever played, i have met some real decent people on the the twisted discord channel, they will help you learn everything you need to know and you will become very good', 'The problem with this game and new players is the partnered streamers. They make up half of the player base, have had access to the game for like a year, still have access to the dev server, so they get to see where all the new poi''s and loot are before everyone else. You may as well be playing against the game developers. Every time you see who killed you (its usually the same few people killing you) you turn to twitch and there they are with "A Twisted path to Renown Partner" listed proudly on', 'Mixed', 52.10, 548.33, 65.52);
INSERT INTO reviews VALUES (55319, 2305500, 258, 'A short and cozy roguelike deckbuilder set in the Fairy Tail universe. There are five characters you can play being Natsu, Lucy, Gray, Erza, and Wendy. There isn’t much of a story, but the pixel art animations are adorable. I’ve had no issues playing on the Steam Deck and the overall experience has been pretty cozy, albeit somewhat lacking.\n\nAlthough each character has a unique kit, it is frankly rare to make full use of them due to how short each playthrough is. There are 3 labyrinths, but only', 'umm too little content, should have half the price. Also the game offer replay value aka repetitiveness.\nI just cant repeat 1 dungeon for hours and expect players like to enjoy it. big NO.\n\nI dont like the random event just to remove unwanted card, farm certain card which are RNG and the random upgrade options makes the RNG even worse.\n\ni like control over my character.\n', 'Very Positive', 94.57, 16.45, 15.32);
INSERT INTO reviews VALUES (55333, 2305840, 933, 'finished in under 5 hours, didn''t even realise I was doing the main story for most of that. Not that many dungeons. I feel like there was more water exploration in Cat Quest 2. Only changed weapon about 3 times. Started with base sword, got a really good one quite quickly, upgraded it to level 100, then found an even better sword and then the game was over. As far as I know there were three guns in the game. As soon as I got a magic wand I switched to that, also leveled it up to 100. Did all the', 'I''ve been excited for this title a while now. Played it the minute it came out. There were positives, the feel of combat, the fluidity and the graphics are all better than the previous tittles but there was a much larger issue. I was expecting it to be a decent sized game but it fell FAR short of my expectations. Cat quest 2 had a map roughly four times the size of this one and lasted 3-4 times longer as far as content and game play as well. I didn''t clear every single side quest but I did 85-90', 'Very Positive', 94.96, 5.97, 10.33);
INSERT INTO reviews VALUES (55336, 2305900, 101, 'I wanted to take a moment to write about this game, even though I didn''t get as far as I''d like to before writing a review. There''s another game just like this called Gunlock. This is a rogue-lite shoot''em up. Like Gunlock, you pick your ship and find a handful of weapons in the level that you upgrade on your run. There are also utility items that are upgraded that support your play through such as regenerative health, shields, speed ups and damage ups. This game has branching paths and all the ', 'yea no. dont buy this. im going to guess its a phone. its a shooter right? yea you dont shoot. game does that for you. just like a cheap, free, phone game. you control the ship. 100s of better shmups', 'Overwhelmingly Positive', 97.03, 7.53, 0.12);
INSERT INTO reviews VALUES (55361, 2306590, 2946, 'This game has changed my life. Ever since i was a young boy, i have been living in poverty, feasting on rats and living under a bridge. I thought i would never make it out of the slums, at least, that''s what i believed before i was blessed with this game. When i first launched this game, it changed my perspective on how to live, guided me out of the darkness that was my life and onto a brighter path. I now own and operate the largest oceanic drug and human trafficking ring. Thank you and God Ble', 'Not enough sex', 'Very Positive', 94.50, 0.33, 2.55);
INSERT INTO reviews VALUES (55395, 2307350, 2243, 'I like the part were the explorer says "I''m going into the Radius." and the Co-op explorer is introduced coming out of the fog and says\n"You can''t possibly believe you''re going into the radius alone, right? I''m going into the Radius too."', 'let it get some updates under it''s belt first.', 'Mostly Positive', 79.14, 5.20, 0.97);
INSERT INTO reviews VALUES (55436, 2308360, 127, 'Its got good bones, I just wish they''d kept building on it. There''s balancing and quality of life changes that could be made to vastly improve the experience. Most comments say the game is abandoned and I can''t really dispute that.\nTry it out, keep an open mind, and settle in for the grind as long as you are ok with it. \n\nI''d give it a thumbs to the middle if I could.', 'The game doesn''t work and the devs have abandoned it. complaining about this gets you banned from the discord.', 'Mixed', 52.76, 6.88, 8.05);
INSERT INTO reviews VALUES (55447, 2308630, 275, 'I legit got an ad for this game on Tumblr and decided to check it out lmao. So to whoever it was that had to explain destiel to their boss, congrats! It''s a pretty fun game!\n\nEdit: I do however have to acknowledge that it was an improper use of the Tumblr Emergency Broadcasting System, and that the authorities should be speaking with you soon. Cheers!', 'An ok game with no mouse support at all.  I think that''s important to note, especially with all of the glowing reviews.\n\nDev says it didn''t work well when he tried it.  That makes little sense.  You don''t need to use it for every single mini game.  The overworld definitely needs mouse support, especially as the city expands.\n\n2/5 - It''s 2025.  No mouse support, no recommendation.', 'Overwhelmingly Positive', 96.36, 1.12, 0.35);
INSERT INTO reviews VALUES (55477, 2309400, 223, 'A game created by two developers - definitely impressive. It''s early access, and during the game we encountered one bug, which was corrected after being reported - the developers care about their work :) \nThe gameplay is smooth, the graphics are very nice and atmospheric. If you can get into the atmosphere, the story will absolutely absorb you. There are puzzle pieces, you have to think, there are jumpscares and a bit of running away. Various equipment to help you during the game. We will encoun', 'I really liked this game. First time horror game which really makes me scare. But then devs decided to make Panicore and this games feel abandoned. Even chapter 2 is late and devs havent shared any news for 6 months, only focused on Panicore which is yet again another looping short-term game. This game had potential but dev abandoned it, sadly. I will change my review if i see some progress happening but for now, i dont want to recommend this.', 'Very Positive', 80.27, 12.92, 4.72);
INSERT INTO reviews VALUES (55517, 2310300, 105, 'I am a 55 year old biker and trucker father, and probably one of the oldest people playing this game. I am a single father to my Son, who is 15 now. My son got this game for from his uncle, so we installed it on his computer and he started playing. By the end of the week he had 12 hours on this game. This was horrible for me, as it was already hard for me to find ways to spend time with my son, as he is always out with his friends or just watching YouTube. So i decided to make a Steam account an', 'My Achievement! It''s Disappeared!', 'Mostly Positive', 72.38, 2.23, 0.73);
INSERT INTO reviews VALUES (55557, 2311190, 1518, 'Ever since I beat Garten of Banban 3, it was where I starting playing every Garten of Banban Chapter on the day it released when it got to Chapter 4. This game is just amazing, so I can reassure you; the only reason people hate this game is because they''re just jealous of how good it really is. Never listen to a hater, always understand that they''re jealous. The only thing that I agree with the haters is that the first 2 chapters were shit, but people hating on the next 5 chapters are completely', 'Rather play a game made in scratch then complete this game', 'Mostly Positive', 74.04, 5.63, 1.32);
INSERT INTO reviews VALUES (55578, 2311680, 309, 'I can''t tell what got me so addicted to this game but apparently it got me addicted.\nIt''s simple, no music, barely any story. But just the look of how you''re progressing further and further into the game just makes me happy. And hecc- I was relieved once I finished the last boss.\nIn magic research all you do is building up your little text-based production while exploring text-based dungeons. Key feature is to "retire" once you hit an unbeatable point and -restart- the game with additional skill', 'As much as I dislike having to give this game a negative review it has a major flaw that has yet to be fixed. Had about 43 hours of progress and was enjoying the game for the most part until I tried opening the game and found my save to be gone without a trace. My PC didn''t crash the last time I played and I just closed it as normally would. I have no clue how this would happen and why this hasn''t been fixed yet. With just a quick google I found multiple people reporting the exact same problem a', 'Very Positive', 90.61, 145.40, 42.95);
INSERT INTO reviews VALUES (55589, 2311990, 373, 'Rack and Slay is a light, low challenge Rogue-Like. It runs smoothly with no glitches. You see everything the game has to offer in a relatively short time frame, but at this price there is nothing to complain about.\n\nSome reviewers complain about unreachable targets, but I only experienced this if I didn''t plan ahead a shot or two. If you have the skill (there is a slight learning curve) then even the highest levels are beatable. The challenge is moderate at most.', 'I am very split down the middle on this game. I like this game alot, I am a huge fan of pool and roguelites, however I am still not recommending it because of how unpolished and frustrating the game can feel. Ive noticed several spelling errors and encountered moments that didnt feel very good to play. There are some items that arent clear on what they do, your power meter is hard to read and often will over shoot something and fly into a spike and at times it feels impossible not to sink your c', 'Very Positive', 92.49, 453.25, 2.63);
INSERT INTO reviews VALUES (55611, 2312520, 174, 'DEVS, PLEASE UPDATE THE DEMO!!\n\nI played the demo and was originally going to pass on this game because of how empty everything felt. I understand that a demo is just a taste of the content but it''s also a showcase of the best features of your game. I''m glad I took a gamble and bought the full version, anything I didn''t like in the demo was either different or finished, but I can definitely see the demo turning people off of the actual release.\n\nAll in all, this is a wonderful little game so far', 'The good: The aesthetics and art style of this game are absolutely perfect, I love the look of it. \r\nThe not-so-good: I''ve now played a good bit and am finding the game to be pretty seriously lacking. Unlike other farm management games, there''s no additional tasks past tending to your farm, crafting, fishing, mining, and socializing. No leveling system, no collecting, no character customization, nada. The game is marketed with this idea of looking for a lost sister, but you go weeks and weeks as', 'Mostly Positive', 77.01, 2.37, 7.15);
INSERT INTO reviews VALUES (55632, 2313020, 165, 'Pretty fun but theres no way this should be 45 dollars. Like surely they''d make more money if it was easier to convince ppl to buy in at like $15-20\n\ncygames plz', 'Even as a fan, I cannot recommend this game with it''s current price tag. And with only 4 mini-games and no further activities, it wears out it''s welcome quickly. Granted the girls talking and the story livens things up, but that will wear any fan out fast. Also Cygames charging $20 for three DLC''s (others won''t be out until near the EOTY) it feels VERY predatory. For the rather paltry offering, it''s not worth $44. I''m refunding it and waiting for a sale. Do better Cygames!', 'Mixed', 69.70, 1.95, 0.60);
INSERT INTO reviews VALUES (55644, 2313240, 752, ' 𝕃𝕠𝕠𝕜 𝕗𝕠𝕣 𝕒𝕟𝕕 𝕗𝕚𝕟𝕕 𝕥𝕙𝕖 𝕔𝕦𝕥𝕖 𝕜𝕚𝕥𝕥𝕚𝕖𝕤 𝕤𝕔𝕒𝕥𝕥𝕖𝕣𝕖𝕕 𝕒𝕣𝕠𝕦𝕟𝕕 Italy \n\nSomething to do in between shifts I guess.', 'A step down from Paris – secret mechanic done worse\n\nCats Hidden in Italy tries to follow the same formula as Cats Hidden in Paris, including a hidden mechanic—but this time it felt even more obscure and unrewarding. Unless you’re mindlessly clicking around, you’d probably never find it.\n\nCompared to Bali or even Paris, this felt like a weaker entry. Still has the usual charm, but the attempt at adding depth just didn’t land.\n\nNot free, and not their best. 6/10.', 'Overwhelmingly Positive', 96.81, 2.42, 0.27);
INSERT INTO reviews VALUES (55645, 2313250, 180, 'French: Ce jeu est un chef d''oeuvre\r\nCat: Mrrp meow meow nyaa purrr meow meow mrrp', 'After completing and thoroughly enjoying Cats Hidden Around the World, I decided to go back and try out the earlier chapters of the series, which focus on individual cities or specific countries.\n\nOverall, while these games offer much shorter experiences — each chapter usually consisting of just one or two maps — I found it particularly enjoyable how interactive the environments were.\nIn these episodes, it’s fun to click on various background elements and see them react with sounds, animations, ', 'Overwhelmingly Positive', 97.22, 1.60, 0.15);
INSERT INTO reviews VALUES (55648, 2313330, 1010, 'The reason this game has mixed reviews is because the playerbase of TerraTech wanted an updated version of the first game with the exact same mechanics. This is in the same genre, but is a very, very different game, and that''s a good thing. It learns a lot from other vehicle building games like Trailmakers, but adds some really interesting base building mechanics and an updated crafting system while keeping the original TerraTech charm. I played the demo, and while it has dramatically improved s', 'This is a good game, but look at my play time and know that I have exhausted all the content in the game. It is not ready yet, needs more time in the oven.', 'Mixed', 67.82, 53.42, 5.85);
INSERT INTO reviews VALUES (55663, 2313720, 356, 'It''s kind of addictive, I just want to keep seeing the new areas and unlock all the words. I''m on a 3 year streak on Duolingo and I feel like vocabulary is my weakest point. I''m about 6 hours in and I''ve learned a lot of vocabulary that I haven''t learned in DL in 3 years.', 'I know this game is in early access and that''s part of the reason I do not recommend it. \nIt''s riddled with game breaking bugs that make it a horrible, clunky, experience. (this review was made after experiencing a bug where the wrong words were showing up and expected to be the answer to every question asked)\n\n I''ve learned quite a bit of Spanish from doing Duolingo for over a year and I was excited to try this game and it have a bit of a story that I could try to follow along with. The game do', 'Very Positive', 89.61, 11.73, 1.62);
INSERT INTO reviews VALUES (55689, 2314160, 1839, 'while playing this co-op with my friend i saw him peak a corner and get his skull turned into fragments\n\nall i could do is hide behind a corner covering my mouth hoping my breathing wouldnt alert the guards as i saw his lifeless body get stepped on by an npc\n\nhorrifying game would play again', 'This game was pretty fun and I liked it for a while but it now seems like the Devs are on a downward spiral making questionable game design choices and cannibalizing the PCVR version of the game to work on the Quest to the point of removing the entire Sandbox map and mode and just replacing it with yet another room randomizer map that we already had and did nothing but take away from the experience, not to mention the various technical bugs with the game that I would ignore if it weren''t for the', 'Very Positive', 89.61, 4.65, 27.30);
INSERT INTO reviews VALUES (55710, 2314720, 664, 'i got stalked and all i got out of it was a bunch of youtube commentators making slop off of my trauma', '"Babe it''s time for another mediocre job simulator with stalking, please consume my product"\n\n"yes chilla''s art"\n\nI''m starting to think the fanbase of these games is under some influence, or simply doesn''t play horror games outside of these nonsense quantity>quality titles. My other theory is that the bait is to include stalking and violence against women as "social commentary" in every weak asset flip horror game with 2 months (!!!) of development time, which perhaps for some reason still happe', 'Overwhelmingly Positive', 95.33, 1.63, 2.15);
INSERT INTO reviews VALUES (55724, 2315020, 138, 'I am FROG', 'Felt like near the end you just gotta run for 1-2 mins and its impossible to get exp.', 'Overwhelmingly Positive', 97.83, 6.73, 1.33);
INSERT INTO reviews VALUES (55733, 2315400, 333, 'If you''ve played Fights in Tight Spaces, this is essentially a visually enhanced FITS with weapons, whose fighting systems have been honed to perfection.  So, digital crack.  If you have not played FITS (yet), boy are on in for a treat.', 'This game is a downgrade from Fights in Tight Spaces (FITS) in almost every way. The enemies will avoid positions where they can be knocked out of the arena above all other concerns as long as they are able, which makes the mechanic virtually unusable. This is especially irritating when your bonus objectives frequently involve knocking enemies out of bounds. The UI makes you look at different areas of the screen for necessary fight information which should all be together in one panel or at leas', 'Mostly Positive', 74.17, 25.28, 3.30);
INSERT INTO reviews VALUES (55734, 2315430, 398, 'The game is good but... the game ends in 2021... it should be continuous... so you are forced to reset everything again, like I wish it was more immersive with your company and movies, idk, I found it kind of vague\r\n', 'How is it that so many years after Game Dev Tycoon, a game clearly trying to replicate it fails to deliver the animation, gameplay, or charm, and still costs more?  \n\nI''m really disappointed by this.', 'Very Positive', 81.91, 7.20, 1.47);
INSERT INTO reviews VALUES (55746, 2315690, 3826, 'Really fun game I recommend it but if you plan on getting this game just pre order 2K25 as they give u 2K24 For Free!', 'The game is fun at a fundamental level. The modes are better than they were in 2K23 and the roster is leagues above it as well. However, nuking community creations that use unlocked content from the abhorrent sewage drain that is myfaction, a mode NOBODY wants to play, by marking them all as damaged content as well as actively attempting to kill the modding scene for the game is inexcusable. News flash morons, half the people playing the game want to mod it. Maybe don''t treat half of your player', 'Mostly Positive', 73.18, 44.25, 37.15);
INSERT INTO reviews VALUES (55770, 2316410, 145, 'this game was decently done, scenes were ok and the story actually had a minor cliffhanger at the end making me want the second game. the last scene was the best imo just saying. get these games on sale.', 'Really less than 20 minutes to finish and you can only watch videos?  No choices and no scene control.', 'Mixed', 62.07, 0.33, 0.45);
INSERT INTO reviews VALUES (55774, 2316580, 536, 'This game has a lot of flaws, but I still recommend it overall. \nHappy to see an African mythos game, and hope to see more. \nAlso the SBI "controversy" is a nontroversy and just typical racism veiled with coded "antiwoke" language, unsurprisingly.\nAlso keep the clown rewards coming, it''s just a running tally of racists for me and it gives me points 🤷🏾‍♀️', 'played 3 hours into this very easy and basic game, beat first boss and got soft locked after a bunch of game breaking bugs. Not I cant switch stance back to light form to open a door.', 'Very Positive', 85.63, 8.93, 13.80);
INSERT INTO reviews VALUES (55825, 2317640, 275, 'I was clearing Demon Barrow out with an Onion Bro.  We cleared the entire level and almost beat the boss. But at the very end I choked and fell, all the enemies had respawned. I had no chance of seeing my Onion bro again.\nOnion Bro if this finds you, I''m sorry I let you down.', 'A fundamentally improved and expanded Jump King, but I wholeheartedly can NOT recommend it in its current state. The initial network test proved that the game is flawed into oblivion, mainly related to the netcode/the multiplayer. Despawning mobs, unregistered hits, characters flying all over the place, jumps not registering, being randomly teleported 2 screens up or down, bosses despawning mid fight, wandering special bosses despawning, the hotdogs not working but still counting as being consum', 'Very Positive', 84.73, 16.40, 11.97);
INSERT INTO reviews VALUES (55840, 2318070, 295, 'One of my favorite childhood games, beautifully remade and sensibly modernized.\nReally hoping for a remake of the second game as well!', 'The game is a buggy mess, poor enemy path-finding, sound effect glitches, the magic ball is horrible, Twinsen has been frozen or stuck multiple times. In all good consciousness I can''t recommend this to be even the most loyal fans (me being one of them). I think this game will get good reviews as fans are so desperate for this to work out me included but I think they''re kidding themselves.\n\nThe game looks good and the music is good. Apart from that its bad the original plays better and its 30 ye', 'Very Positive', 85.08, 6.18, 25.95);
INSERT INTO reviews VALUES (55851, 2318310, 3569, '"Does he have a major fetish?" "No, his major fetish is a minor fetish." "So what''s the fetish?" "I told you, a minor fetish." "I know it''s a minor fetish, what''s the fetish for?" "Minors." "Like guys that dig coal?" "Not those minors." "So shitty baseball players?" "What? No!" "Then what''s the fetish?" "Um,,, He''s into girls under the age of 18." "Oh that''s not good... Why are we getting him pizza?"', 'This is the Developer actively bullying a 14 year old autistic child btw\nhttps://x.com/MagicMushMM/status/1839017063534252466?t=ZPPCh9Cvia3TN1ocZ99Y5g&s=19\n', 'Overwhelmingly Positive', 97.79, 10.48, 30.07);
INSERT INTO reviews VALUES (55857, 2318480, 1197, 'I love the tremors idea, and I like the details. Super dead though without friends...', 'GREAT GAME BUT you have to have friends ON OTHER PCs to play, and unforchantly I cant recommend this game because of that BUT it makes sense and I am also not saying dont buy the game, just keep that in mind when you do. I would like to see ai or something to help compensate for that but that is a very hard task and that is not a fair ask and I dont expect it but I just thought I would state that', 'Overwhelmingly Positive', 96.41, 0.85, 0.65);
INSERT INTO reviews VALUES (55901, 2319390, 133, 'It''s a slavic version of FEAR. Not quite as good as FEAR, but man is it still good!', 'I wish I could recomend this game. But this is a boring, repetitive snoozefest. The levels are samey, the enemies are not very varied, the combat mechanics are worse than Forgive Me Father. The first boss was incredibly boring. The visuals are alright, but nothing special, the music is alright. Buy it on sale if you really, really want a Sovietcore Boomershooter and you already played HROT.', 'Very Positive', 85.71, 16.95, 5.98);
INSERT INTO reviews VALUES (55913, 2319640, 441, 'Fun little game with 5-10 hours of content.\n\nSome updates to add more content and maybe a bigger city would be beneficial.\n\nProps to the developer who is very vocal and active in listening to suggestions!', 'Boring game , with meaningless mechanics . No challenge or worthy progression', 'Very Positive', 87.30, 13.70, 11.28);
INSERT INTO reviews VALUES (55970, 2321210, 295, 'This is by far one of my favorite games of all time...and it''s never going to be completed. Which hurts. I suggest people to still play it though, it''s a good game. Lovely music, amazing aesthetics, combat is solid, cute character designs.', 'game is abandoned dont buy it\r\nit had potential but was abandoned by the publisher, dont give them any more money\r\nplaytime was from when the game was actually still being updated, came back to review so to warn people from buying', 'Mixed', 60.68, 10.55, 78.43);
INSERT INTO reviews VALUES (55999, 2322010, 10258, '"Not enough available memory" crash with a 24GB GPU and 64GB of RAM… guess Kratos needs even more godly hardware!', 'Creating a PSN account was something I knew was necessary in advance and I was prepared to do so, until I was met with the reality of it. \n\nFor UK residents at least, it requires submitting a mobile phone number to verify your age just to start with, and if that fails (which it did, no texts were ever received) your only recourse is to submit a photograph of your face or a government-issued ID to a third party website.\n\nIf you''re happy with that, go right ahead.', 'Very Positive', 87.85, 31.30, 0.33);
INSERT INTO reviews VALUES (56010, 2322180, 203, 'Tiny Sticker Tale is a very good game with an original gameplay. We have to solve some tiny puzzles with stickers to move thru the story. The music is good and the athmosphere is so relaxing. I highly recommend it!!! 💗', 'Awful achievement design! \r\nThis is a simple, yet fun game! Though, I guarantee you will frustrate yourself, as I did, if you wish to 100% the game. It will force you to play it all over again until the end. I could have had a wholesome experience of having it all done perfectly, with effort, attention an care and be rewarded with a satisfying 100% achievement. Instead I was punished to have the finish the entire game again due to poor achievement design that has a permanent choice achievement t', 'Overwhelmingly Positive', 97.04, 10.28, 4.50);
INSERT INTO reviews VALUES (56019, 2322380, 116, 'Fun. Runs great on steam deck. Open world patrick game. Goat sim but patrick.', 'Honestly very disappointed with this game. I''ve played all the Spongebob games and I was very excited for this one but $40 for a bunch of mini games is a bit egregious. Overall, the games are fun but I think half the price would be much more reasonable.', 'Very Positive', 85.34, 4.67, 1.00);
INSERT INTO reviews VALUES (56022, 2322440, 358, 'This game made me feel miserable for so many years, and when it finally shut down I thought I was finally free...', 'Excessive grinding is a huge problem, making some stages feel like hard walls like 8-1, Elite 5-1, and the 2-3rd missions of Another Story due to the unfair deployment speed enemies have. Grinding for parts is ludicrously tedious due to no Raid system from Metal Slug Attack, which is understandable due to the removal of Sortie points, but it would go a long way if you could buy low rarity parts at the very least. I''m hoping these issues get sorted out later because it''s very hard to progress cur', 'Mostly Positive', 73.46, 17.12, 161.82);
INSERT INTO reviews VALUES (56030, 2322560, 1457, 'If anyone on my friend list notices I reviewed this game, I''m launching myself off a building.', 'I might stop playing after only 3 chapters. \n\nI thought this game was going to actually give you "free will" to determine who you''ll end up with. Reality is, there is a set amount of TOTAL affection you must reach to open the next chapter. Meaning, if you''re like me and playing it for the first time, you''re bound to gain affections equally from each love interest. Which is good until you didn''t reach the total affection quota. You''ll have to go back and change most of your choices to gain MORE a', 'Very Positive', 93.48, 9.12, 2.23);
INSERT INTO reviews VALUES (56283, 2328310, 175, 'Yeah the gameplay is a combo of armored core and edf from like.. 15 years ago.. \r\n\r\nbut the mech building is 11/10\r\n\r\nno idea whats even happening in the story, don''t even care\r\n\r\nmust.. find.. more.. partsssss', 'This game does not worth the $49.99 price tag, the painful progression are similar to EDF if you want to unlock parts that are just not junk.', 'Mixed', 52.00, 14.93, 0.58);
INSERT INTO reviews VALUES (56298, 2328650, 227, 'I’ve been in a highly anxious state for the past six months. I’m about to get married, work has been very stressful, and I’ve been mentally drained every day. I feel like I’m just muddling through life. I even stayed in the hospital for a while at the end of February. I can’t even bring myself to enjoy games like I used to.\n\nThis game’s gameplay and style are so similar to Animal Crossing — collecting trash, assembling my own train, playing with little animals. After work, I lie on the couch and', 'It''s fun for like 2 hours then the gameplay loop kind of gets boring. Passengers don''t really feel "alive", they don''t really ask for snacks or react to train decorations, afaik they don''t care if you keep the dingy set... I wish there was more to it to be honest and I thought it was early access but I don''t see anywhere on the store page that it is. You also can''t change the train floors which I''d hope you could... and what you can change the colours seems so bland imo.\nIf you like fetch quests', 'Very Positive', 91.19, 1.28, 4.65);
INSERT INTO reviews VALUES (56304, 2328730, 100, 'This game does everything right. The puzzles are well-crafted and challenging, and it gives you the tools to solve them without any random guessing. The UI is customizable, so you can adjust most features to appear the way you want them. There is no timer to rush you or keep you superficially glued to the game. It is pure, unadulterated, deduction-based puzzling.\n\nThe only downside is that there''s no computer-generated "infinite mode," but the hand-crafting is also its strength.', 'Puzzles can only be solved through trial and error, which doesn''t really feel like solving a puzzle at all. There''s often no way (at least to me) to combine factors to logic out answers. Harder does not always equal better with puzzle games.', 'Very Positive', 89.00, 34.63, 7.70);
INSERT INTO reviews VALUES (56306, 2328750, 594, 'This is literally those mobile apps you see in the ads, but like… the actual thing. And no ads. Yeah it’s grindy, but it’s super chill.', 'Feels more like a mobile game. You don''t actually get to do anything. You just walk around and collect resources. Then walk to spots and deposit resources. Its basically just a time waster, but I guess it could be fun if you were listening to music or watching a movie, but dedicating time to focus on the game is a bit boring!', 'Very Positive', 90.24, 7.00, 6.17);
INSERT INTO reviews VALUES (56307, 2328760, 133, 'I have literally made several videos in which I have praised Pinball FX calling it both the "best value proposition in gaming" by comparing the cost of playing real machines to the FX recreations and I also called Pinball FX "the best Live Service game" because they have removed the strange paid currency from the game and they have been updating and tweaking the tables to make them better. \r\n\r\nIt''s actually baffling that I could have played this game for a year without reviewing it but now i''m 5', 'So far I see no improvement over FX 3 and The graphics look very bad.', 'Mixed', 69.92, 750.02, 8.73);
INSERT INTO reviews VALUES (56346, 2329630, 115, 'What seemed like a simple game about being with a woman along in a hotel room ballooned into a weirdly emotional story filled with unrequited love and the seedy underbelly of society. It''s narrative focus is nuanced and only expands once you''ve invested in these characters. The plot itself reminds me some K-Drama I watched in a restaurant once. Otherwise, art is nice and detailed and the ''rewards'' earned in the game are great.\n\nFind yourself some love guys, it''s all we have left.', 'I cannot recommend this game due to heavy themes of suicide that are not disclosed anywhere in the beginning or description of the game. If you are going to play just be aware it is really easy to get endings that involve instances of suicide so be prepared for that.', 'Mostly Positive', 74.78, 1.38, 3.22);
INSERT INTO reviews VALUES (56378, 2330360, 197, 'Very good first impressions. I would like to see a "Free draw" option (with an export function) in the game & available from the start. This way I can work on drawings after each tutorial!', 'Let''s be clear, this won''t teach you anything about pixel art. It''s not even about pixelart It''s more about filling the pixels with the right colors. There are many better and cheaper games of this type (for now). For example, Coloring Pixels (Steam) or many mobile this game of type. Hope some day I will be able to recommend it but not for now.', 'Overwhelmingly Positive', 97.97, 2.08, 0.87);
INSERT INTO reviews VALUES (56398, 2330750, 282, 'I played for about 30 minutes just to look at the controls, I booted up a completely random character and tried figuring out how to navigate my inventory. I found out that I had a cellphone on me, and proceeded to access it, curious with what I could do.\nI saw it had an option to play games on it, so I clicked that, then in a list of a bunch of games I selected snake.\nI proceeded to play snake within the zombie game.\n10/10 would play snake again.', 'The Lack Of Support For The Paid Version is insane, the game itself is great, but the single developer who put this version up on steam just took our money and ran with it, I feel that I and many others have been sold a false bit of goods because it is literally being updated on the browser version but not on steam so why pay for it? why not clarify that cdda is no longer being updated on steam, and the server is filled with power hunger people, who are so ignorant and blind to see that the deve', 'Very Positive', 92.20, 30.00, 348.53);
INSERT INTO reviews VALUES (56415, 2331130, 119, 'Allow 3v3 and 4v4 gameplay! Would be a lot more fun especially with bigger maps!', 'Will change this review to positive once a few things get fixed.\n\nI honestly think it''s a one of a kind game right now, had so much fun that it hurts that you can literally max the game out with a decent 4 stack in 10 hours... as soon as you figure things out, learn mechs (including the bugged ones), learn the routes (even the hidden ones), the problems the game has potentially clears the fun out (balance issues, netcode problems, bugs that cost rounds even if you do everything right, lack of co', 'Very Positive', 94.12, 10.23, 9.35);
INSERT INTO reviews VALUES (56426, 2331330, 108, 'It''s a very well-made game with an appropriate game length and difficulty\r\n\r\nThe final part of the ballerina chapter was especially my all-time number one moment in this game.\r\nIt’s incredibly well-directed, with perfect harmony between tension and the tempo of the music!', 'Average B-movie horror movie with some interaction. Not terrible, not great, first game is much better. Still worth a play if that''s what you''re looking for', 'Overwhelmingly Positive', 95.37, 11.83, 5.90);
INSERT INTO reviews VALUES (56475, 2332240, 170, 'Fun retro style adventure. Got stuck in the first room for a bit when I was figuring out the mechanics, but after that it''s been smooth sailing. Going to try and make it through without using a guide.\n\nEDIT:\nThanks to the developers for making this controller compatible, works great on Deck.', 'This game blows. I feel like an idiot clicking on random shit to try and get something to happen. I don''t mind a game that makes me chose the exact action I want to do to make something happen but I literally got stuck in the first room. Shit just seems like the creator just wants you to do random things to make something happen and not really think. No really overall story or no real thought process spam options to something happens is brainrot and stupid. Enjoy your clicking and frustration.', 'Very Positive', 94.71, 7.45, 0.48);
INSERT INTO reviews VALUES (56476, 2332260, 359, 'As a Roguelite, it''s a shame that the biggest issue with the game is its replayability. I would estimate that the game needs 10 times more content to be minimally replayable. The only thing that changes in each run is the map generation. I understand that in some games, a different map can be enough for a strong replayability, but unfortunately, that''s not the case here. After completing a mission, I feel no desire to play it again; the equipment is the same, the objectives are the same, and the', 'im not entirely sure how i feel about this game. i was excited for it to release and ive been following the dev logs, but now that its out it really isnt that fun to play. its just go down for loot come up to spend that loot so u can go farther down and find more of the exact same loot.\n and at the end of a game u just leave, u dont earn any permenent upgrades or anything to help u get better. so because u dont earn anything theres basically no sense of progression atleast not for me. im still o', 'Very Positive', 91.64, 3.02, 0.50);
INSERT INTO reviews VALUES (56542, 2334170, 437, 'I can''t stop playing.  Its hard to understand what to do at first but once you get your grips the game loop sinks it''s teeth in you.  Before you know it, you''ve grind mech parts and disks for hours without even realizing it.  \n\nMy only gripe is the pixelation filter on higher resolutions.  For the best visuals set the resolution to 720p windowed and use a third party app like borderless gaming to stretch the window fullscreen.  I hope the devs will give us an option to lower the resolution while', 'The game is a lot of fun, until it stops being fun all of a sudden.\n\nEarly on it can feel pretty easy, you''re killing foot soldiers with your little dude, get a mech and can start going toe to toe with other mechs. You might die but it seems pretty fair. Then you get to the third area. It''s mechs all the way down and they decided these guys need to be like ultra ace pilots that are constantly flying across the map faster than you can react. Try chasing them in your mech and oops you''re suddenly ', 'Very Positive', 90.39, 30.18, 14.27);
INSERT INTO reviews VALUES (56576, 2334780, 111, 'the last of us un poroto, me cague todo', 'The premises are interesting but I got bored out of corridors after only 5/10 mn of play.', 'Overwhelmingly Positive', 96.40, 0.83, 0.20);
INSERT INTO reviews VALUES (56633, 2336200, 346, 'Fun little game that can be played with mouse only so when I am talking to people i have something to do. Plenty of upgrades.', 'This doesnt really play like a survivor, like with random upgrades and stuff. This for the most part plays like one of those flash games where you spend the money you gain to (permanently) upgrade you train to make more money to get more upgrades. You know, the penguin kite game or the zombie car game kind of deal.', 'Very Positive', 87.57, 7.50, 0.28);
INSERT INTO reviews VALUES (56662, 2336720, 198, 'good game was ass a thirst and not 8 pounds good', 'this is the shi**est game i have ever played i bought a water jug went to fill with water it dissapeared 4 times then i had 30k on me went to the "potato" farm to stash them there and guess what magicly it turned into 8k and not to mention the servers i had to restart the game 3 times just to get in a game and get kicked 5 sec after because of pos or something like that. For the love of god fix the game and make a fu**ing tutorial i had to dig in the trash bins for items to sell for 30min becaus', 'Mostly Negative', 32.83, 29.40, 11.52);
INSERT INTO reviews VALUES (56678, 2337140, 137, 'Can''t Live Without Electricity is a great little puzzle game. Devilish in it''s simplicity, and a great sound track as well.', 'Unironically the most frustrating puzzle game I''ve ever played. The game pulls the same shit as Mini Motorways and places houses in the middle of actual nowhere and says "Good luck shithead, try connecting that efficiently". I''m not terrible at the game, but I''m definitely not great, my bitterness comes from the absurd difficulty spike after the first bunch of levels. It makes you feel like an idiot and will give you houses that look impossible to connect, and some that actually are, (truth on t', 'Very Positive', 94.89, 11.83, 5.08);
INSERT INTO reviews VALUES (56705, 2337820, 216, 'While I thought the idea of the game was interesting, the art style is unique, and the storyline was decent enough to follow, once you understand the gameplay the game falls flat. The auto generated dialogue is probably the biggest factor that ruins the game. After collecting all items and going through 3 seasons, there''s almost no reason to keep playing. It has SO much potential, especially with the characters and their personality and designs, but actual conversations lack variety. Try to comp', 'The concept is great but after 1 season in game, you''ve seen pretty much everything and the game doesn''t actually do a whole lot with the idea of filming a raunchy, trashy reality TV show. There aren''t individual cast interviews, you can''t really interact with the cast members other than doing "quests" for them, you can''t influence how cast members react with each other, and you can''t edit the footage you shoot in a way to boost viewership like you would expect a reality TV producer to do. \n\nAll', 'Mostly Positive', 72.69, 6.30, 6.95);
INSERT INTO reviews VALUES (56722, 2338140, 411, 'I never knew such a game existed until the video of a certain eyepatch wolf guy came into my feed. Do you wish to destroy the relationships between you and others? Buy this game and play it with the homies.. Do you wish to be abused by game A.I ? Than buy this and play it alone. Set the npcs at the highest difficulty if you want the true pegging experience.', 'Wish could give a mixed review, with friends it''s a blast. But singleplayer the CPU just cheats non-stop and if you have multiple CPUs they all team up on you. It''s not fun.', 'Very Positive', 90.02, 46.12, 9.52);
INSERT INTO reviews VALUES (56742, 2338770, 11981, 'When it comes to single player or playing 1 vs 1 with ur friend this game is as good as any other nba 2k, but multiplayer is so bad that buying this game for more then 15$ is just not worth it.', 'The worst 2k Game of all time and arguably the worst game ever on steam. Inside scoring is completely broken. The badge system is broken. The limitations on the myplayer builds are so bad a 99 rated myplayer  isn''t actually 99 it''s equivalent to a 75 rated player at best. Seriously, check your max attributes versus actual 90-99 rated players in the game. All to just try to get you to spend money on your build. There is no good build, your build isn''t the problem, they are hoping you will think y', 'Mixed', 45.36, 29.92, 198.70);
INSERT INTO reviews VALUES (56756, 2339040, 205, 'Landnama is a simple economy management game with only one real currency to manage: heart.\nDespite that apparent simplicity, there''s a surprising amount of depth to the gameplay - managing that one factor is your only concern as you try to survive each coming winter, with every building and exploration demand cutting into your reserves but ultimately being an investment you can''t afford not to make.\n\nBy keeping things simple, Landnama manages to scratch my city-builder itch without forcing me to', 'It''ll take you 2 hours to complete the game once. after that, its just rinse and repeat. higer difficulty level don''t add features or complexity, only skew the probabilities. Its not more difficult. just less likely', 'Very Positive', 82.93, 6.98, 3.22);
INSERT INTO reviews VALUES (56819, 2340520, 143, 'This is the first time I have actually been excited to follow and engage in the progression of an early access game. This game is absolutely beautifully crafted so far. The art is really stunning and I genuinely feel the love that was put into this game. The characters are unique and interesting. The story actually feels like there was thought and effort put into it. And I love that they have weaved in so much lore. \n\nIt is most definitely a work in progress being early access and all...so if yo', 'not being able to create and customize your own character in a cozy life/farm sim with socializing, romancing, and dating options is one of the biggest sins you can commit with this genre.  it''s right up there with player death; you''d think you''d just get KO''d and someone saves you and takes you back home to recover (like stardew valley, etc.) but nope, the cozy illusion ends when you die and have to reload -- talk about immersion breaking!\n\nif these fundamental issues are remedied, it''s an easy', 'Very Positive', 86.71, 16.10, 9.38);
INSERT INTO reviews VALUES (56824, 2340650, 143, 'Despite some negative reviews from players, I personally feel that it is a nice game.\r\nPlus I am a fan of swordfighting stories :)', '我是河洛铁粉，但这是第二部 续 侠隐阁后的烂制作，完全跑偏了。。我已经不懂怎么写，，存粹支持。', 'Mixed', 67.83, 136.47, 26.00);
INSERT INTO reviews VALUES (56831, 2340870, 317, 'TO THE DEVELOPERS: The game is getting better incredibly. Congratulations!\nWe need more difficulty. On the hardest level I easily win with all the teams. We need a faster and more slippery CPU AI.\nWe also need more difficulty in the shots. With the arrow that indicates it, is impossible to miss. Maybe a shorter arrow like in Rugby 22, and not this one that goes so high, this way it is impossible to miss the shots and it becomes very easy.\nThank you!', 'Another rugby title where the studio think licenses is more important than gameplay. This is beyond bad.\n\nUpdate after full release :\n\nGameplay is still terrible, they added a few PNG files during EA. There system required listed is even wrong.', 'Mostly Negative', 37.85, 22.20, 8.77);
INSERT INTO reviews VALUES (56838, 2341070, 147, 'Hey you! Do you like solo board games? Do you like solving extremely punishing logistics puzzles? Do you like space monks getting drunk to stave off the encroaching fear brought on by the endless, uncaring void of space? If yes, then have I got the game for you! To be honest, you can tell right away if this game is for you just by looking at the screenshots. If the concept and Gene Wolfe inspired aesthetic appeals to you at all, then this game is going to be an absolute treat. It may not have th', 'Very slick visuals, cool world-building and a nice set of game systems that I really, really wanted to enjoy, and that I WOULD have enjoyed if the game hadn''t given up on doing any kind of better integrated tutorial instead of slapping me with a thick PDF game manual to read and cross-reference multiple times while playing (I do mean that literally, the game pops up a page and you click the next arrow to flip through many, many pages of what is essentially a board game rules manual).\n\nThe core o', 'Mostly Positive', 79.59, 8.78, 1.55);
INSERT INTO reviews VALUES (56921, 2342920, 206, 'Beautiful writing, beautiful men and a beautiful story. Unique and detailed, this visual novel is a most worthwhile experience. It explores themes that require a mature audience, but if a dark and well written story is what you''re after, this game will be perfect for you. The game itself encourages exploring the narrative to its fullest, offering many choices that often might have grave consequences. Tread carefully - or not, and simply allow the story to take you with its flow, as you face the ', '', 'Overwhelmingly Positive', 100.00, 33.27, 0.00);
INSERT INTO reviews VALUES (56924, 2342950, 1980, 'It''s a good time sink. Different classes play differently. They are by no means balanced. Consider this a difficulty slider. I''ve got more than 100 hours in this game and I''m not good at it, but I''ve beaten the core game. \r\nHave fun!', 'Radio silence, no actual updates for months then announcing DLC when game is basically unfinished beta is too funny. You could have gotten DLC money out of me if you didn''t use such a shady development process.\nWhy would I buy dlc from you when there will never be any updates afterward.', 'Very Positive', 85.66, 113.13, 55.38);
INSERT INTO reviews VALUES (56925, 2342980, 250, 'As with Freyre''s other stuff on steam, this is great concept art and the absolute bare minimum of actual game.\nI hope they hook up with a couple more developers and make an actual *game* game.\nIt took me half an hour to play through, so even very cheap, it''s relatively expensive in dollars-per-hour.\nStill very interesting to experience, though.  This isn''t a developer doing asset flips, this is a developer to has something to say, but not enough time to say it properly.', 'Too short and too easy.\nGreat if it was free. Like a demo or something.\nSimple replayability features would''ve been better than scattering different weapons around that I only discovered on my way out.', 'Overwhelmingly Positive', 96.40, 0.63, 0.67);
INSERT INTO reviews VALUES (56960, 2343600, 159, 'Everyone who says the translations suck is completely justified, but with that said, if you figure out what''s going on, it''s a hell of a fun game. I''ve won with the most wonky builds and love it.', 'Why is it trying to access my wi-fi and gps data though', 'Very Positive', 89.31, 22.15, 1.33);
INSERT INTO reviews VALUES (56978, 2343900, 124, 'Congrats to the DEVs for the ambitious game, no Early Access  just buy and play. Thanks for listening to the feedback \n for controller inputs . I highly recommend the game for those who love survival horror and Gooner stuff ;)  .The game has combat ,stealth,shooting , werewolf transformation and Alpha werewolf as your nemesis , great xxx scenes ,also multiple  branch choices . For does who are stuck or lost , the DEVs has walk-through in their YOU-TUBE channel , just throwing it out there for th', 'Still feels like an alpha version. Same quality as the pre-release demo. Was hoping it would be somewhat more polished...', 'Very Positive', 88.71, 13.37, 0.60);
INSERT INTO reviews VALUES (56980, 2343930, 125, 'I must admit, I first saw the game through a negative review, but after checking the game and the developer''s website, I realized it’s an indie studio. Furthermore, offering such a product at this price is quite surreal.\n\nAs an old man, this is my first review, and I must say I appreciated a lot about the game. First of all, it has a beautiful concept and a solid product. It brings up pleasant associations with great games like AoE and M&B. However, I’m not comparing it to those, as it would be ', 'ITALIAN LANGUAGE NOT RECEIVED.', 'Very Positive', 82.40, 1.60, 0.43);
INSERT INTO reviews VALUES (56992, 2344320, 2510, 'Ignore the negative reviews that popped up within 30 minutes of the games launch. The devs have been communicative and amazing. Servers were fixed with ZERO issues within two hours. The audio bug was identified and issued a hotfix, twice, with the second one fixing it completely.\n\nAs far as the game goes, tons of fun. Awesome graphics and engaging extraction gameplay. Still digging into the classes to learn the ins and outs, but so far, the most fun I’ve had in an extraction game, period.', 'tl;dr: Great potential squandered handily by experienced devs who should have known better than to charge for "early access" to a half-baked, poorly-balanced product. Do not buy this game in its current state. You can trust people who say "ignore the reviews, this is good!" or you can look at the player count on steamcharts and see that an all-time peak of 2,415 players on EA launch on 2/16 is down to a 24-hour peak of 124 at the time of writing this review. A loss of 95% of the player base in t', 'Mostly Positive', 72.67, 35.73, 6.88);
INSERT INTO reviews VALUES (56998, 2344520, 13230, 'Diablo 4 is a Exilelike ARPG that was built for dads to play 2-4 hours on the weekend.  It''s really good for what it is. I like it. \n Story is weak.  Got a bit of modern audience vibes, but hey, it''s blizzard, so can''t expect anything that wouldn''t get approved by HR.  8/10, pretty fun, but not for long term consumption. \n', 'The $30 this game costs is better spent on Grim Dawn with expansions, Last Epoch or Path of Exile 2 early access.', 'Mostly Positive', 73.73, 162.78, 3.97);
INSERT INTO reviews VALUES (57023, 2345020, 583, 'Fun game.\n\nWould be great if i could upgrade buildings without having to demolish lower tech ones (like storage and turrets) and it would be nice if i could see what got destroyed after a wave so i can rebuild it because at some point it becomes hard to memorise what you build where since your base becomes very big.\nAs a final note, hotkeys for speeding up and slowing the game down would also be appreciated.', 'Refunding on principal, which is a bummer because it seems fun and the premise is great. However, I forgot what button takes control of a bee and there''s no UI or keybind menu to find out what it is. Keybinds should be "Games 101" and I refuse to support developers that skip it.', 'Very Positive', 85.59, 5.07, 0.37);
INSERT INTO reviews VALUES (57088, 2346410, 138, 'Great base building, tower defence hybrid. \r\nGets much better the more you play as everything begins to unlock and bigger maps come into play.\r\n', 'I wish I could give some type of neutral review, because its not a bad game, but I wouldn''t go around recommending it to people either. The game at its core is fun to play, but its unpolished and honestly just kinda meh. This game takes inspiration from several different game genres and combines them together. However, this approach has lead to a bit of a jack of all trades, master of none situation. The game fails to innovate in anyway or bring anything new to the table. It''s a very safe game, ', 'Very Positive', 84.78, 19.85, 1.75);
INSERT INTO reviews VALUES (57155, 2347940, 266, 'Sea of Survivors is a typical survivor-like game where you can''t control the attacks and only control your “character”. Only in this game there is no possibility to stand still. \nI really liked the design, but the gameplay still needs some work. Personally, I don''t think there are many builds that are good and that you can beat the game with.\nIt also takes a while to get the hang of it and survive for a longer period of time. Nevertheless, I had fun and if you get the game in the sale, it''s a re', 'For the current price Sea of Survivors simply lacks sufficient content and replayablity.  One final boss, few enemy types, sparse upgrades and straightforward weapons make it a very thin experience.', 'Very Positive', 82.33, 48.38, 6.68);
INSERT INTO reviews VALUES (57162, 2348090, 291, 'Bought this last night. Already over 3hrs. Rare for me. Haven''t heard of this before it popped in my feed, so I''m dropping this to help visibility, but also because it''s just a damn good game. Addictive. I must appease the food squares and build the glorious coin engine now. Maybe a nap first. \r\n\r\nOh, it''s a deckbuilding, engine builder... it''s weird, but theres a demo that sucked some time away from me too. THE FOOD SQUARES CALL ME NOW.', 'I have played 6 runs in 3 hours. I have won 5 of those. I won my first run easily. Halfway through the game it told me I could end the game early if I want to. I have no strategy at all going into the run and it still feels way to easy. There are so many notes that could be tied together to make this game better, but it feels like I don''t even need to do any of the extra stuff.', 'Very Positive', 94.50, 16.33, 3.15);
INSERT INTO reviews VALUES (57163, 2348100, 767, 'I bought this on a whim during a sale. While I was using my laptop to play a movie for my students, they saw I had Steam and asked what games I had. Upon seeing the comically large title and hearing the premise, they wanted to try it. It was before a break on a half day, so why not? Luckily it worked on the touchscreen board in my classroom.\n\nY''all, it kept my 6th graders so occupied. They took turns, gave advice, and had a blast. During break I played more of the easier levels and next half day', 'Unforgiving and unnecessary timer required to achieve 3 stars on each level makes a relaxing puzzle game into a stressful puzzle game as your trying to rush every level and replaying the same level over and over again trying to do the same puzzle you''ve completed only this time doing it in 5 seconds.\nI could understand if it was finish the level in under X moves but it''s not and the timer adds nothing to the challenge of the game it''s just really annoying and very quickly made me lose all intres', 'Mostly Positive', 74.45, 4.75, 0.40);
INSERT INTO reviews VALUES (57230, 2349830, 122, 'CAW', 'Trash, garbage. Kinda like the dev Xeloph', 'Very Positive', 82.79, 13.40, 0.13);
INSERT INTO reviews VALUES (57242, 2350020, 216, 'difficult but not impossible, crafting system is well thought out, as are the NPC enemies\r\n', '- No auto save feature. So once you log out without saving all your progression disappear.\r\n- Audio and visual bugs. Where you hear bots swimming underneath you while you on top of a mountain. Also, you cannot hit animals from any side.\r\n- Furnace Glitch in melting Oil and Lithium where they disappear from the loot spots.\r\n- If you die while hitting anything you will respawn doing the same physical move where your hand moving by itself even with or without holding items.\r\n- light glitching and t', 'Mixed', 66.67, 223.15, 11.42);
INSERT INTO reviews VALUES (57255, 2351330, 101, 'Excellent horror game!\nThe story gives an intense and terrifying psychological experience. You play as an introvert who must confront his fears and reality or try to escape from it. The developer uses a great way to show how difficult it can be for some to leave your own home. \nThe sound design is absolutely fantastic! With great voice acting and a soundtrack that creates an oppressive, stressful atmosphere. There''s no reliance on jumpscares, yet the game still manages to make you feel scared an', 'Honestly. Just a boring game. It peaked 10 minutes in and that was it. The game inspires to be more but misses the mark.', 'Very Positive', 93.07, 2.12, 1.42);
INSERT INTO reviews VALUES (57264, 2353250, 1012, 'I''m a 74 year old woman, its a hard game for me but having the most fun trying to make it work.', 'All the reviews putting it on par with subnautica - what trash.\n\n- The biggest issue is that you just cant move for 80% of the game. 80% of the game is waiting for your jetpack to refill so you get 2 more seconds of movement before you wait again. The dev obviously never heard of Newton''s First Law of Motion.\n- The other 20% of the game is trying to balance utter ridiculous power needs, which can only be solved by construction, but you have no option to fabricate becasue there is no power and yo', 'Very Positive', 87.06, 41.47, 17.62);
INSERT INTO reviews VALUES (57265, 2353700, 135, 'First off: read all the instructions\r\n\r\nI started this thinking it was just a simple game, but there are mechanics on how to play that make it end up more positive or negative. It is more hardcore as you cannot roll back, so mistakes have to be lived with, so my advice read carefully how to play or else.\r\n\r\nThe scenes are all animated except a few, but it is more of an animated art style. It can be very sexy as you take advantage of the women. Note that you can creampie as you wish in this game,', ' A recipe for perfect hentai game; done half-baked. (6/10) \nI have to be sad again that steam doesn''t allow neutrals, because I do feel like this game is pretty enjoyable for what it wants to be, but it''s bogged down enough in execution by some jarring flaws; enough to make me think it deserves a bit less than "95% nice ratings". Some of them did express mixed feelings; I''m just doing the inverse in how I want my score to count on steam. If it was at 60% I would''ve thumbed up.\n\nIf you''re a major', 'Very Positive', 94.81, 67.10, 27.27);
INSERT INTO reviews VALUES (57272, 2357570, 110, 'ok game but mommy widow/Keri/mercy', 'no.', 'Mixed', 40.91, 262.58, 161.38);
INSERT INTO reviews VALUES (57273, 2358040, 128, 'This is an amazing game if you like grinding games (which I do). There are a lot of things that are never explained to you in this game so you kind of just have to figure it out yourself, but luckly a fan has created a "Fantasy Craft Guide" which has been a huge help and still in the works. I do also wish they would add horses for faster mobility at certain times. Over all a really good game and I can''t wait for more updates.', 'Thought i would try this game again since it has been overhauled.  Well they give you the option of changing the day night cycle but it does seem to work still had to wait forever with a dark screen since the cost of a torch is insane.  To craft a bed you need feathers and I had no way of finding them in the dark!!!!  If you are thinking about getting this game you should look elsewhere there are so many great games in the genre and this game does not seem to be getting any better.\n\nGame moves a', 'Mixed', 69.53, 67.67, 52.80);
INSERT INTO reviews VALUES (57275, 2358260, 1896, 'I really appreciate Bigant Studios and Ross Symons making cricket games. But rather than hunting pirates, you can make the game better. If the game is good and perfect, people will buy it. Cricket 24 still has a lot of bugs. Even mobile cricket games are doing better jobs. Please consider this to make this game more playable.', 'Just buy Cricket 22. Same game, same awful fielding, same disgraceful career mode. Do not give these people your money, and if you have then try to get a refund. All Big Ant have done for this version is change the menu.', 'Mostly Positive', 78.59, 162.88, 3.25);
INSERT INTO reviews VALUES (57282, 2360210, 101, 'When the Darkest Dungeon characters, finally had enough of each other''s s**t, crawled out topside and just kicking the living f**k out of each other :P', 'I like the game but it''s definitely too early to recommend. While you can check it out the balance is just not there yet. Also predictions sometimes blatantly lie resulting in you getting squashed.\r\n\r\nAlso for the love of god let us skip difficulties or at least make them global for every character. Having to grind almost the same campaign over and over to ramp difficulty is annoying by itself, let alone having to do it again on every character. I know slay the spire did it but it doesn''t mean i', 'Very Positive', 91.09, 26.30, 6.08);
INSERT INTO reviews VALUES (57290, 2362090, 104, 'A cluckin'' good game.', 'The ending was not polished well and a huge let down.\n5/10, a quick ride for an adventure that doesn''t feel like one and not worth the price at all.', 'Very Positive', 83.65, 0.48, 7.85);
INSERT INTO reviews VALUES (57291, 2362420, 112, 'THE GAME IS GREAT , GOOD STORY , GOOD DIALOGUE , DECISIONS THAT FEEL LIKE THEY ACTUALLY MATTER , BUT THERES 1 ISSUE \r\nA BUG , IF YOU LAUNCH THE GAME THROUGH STEAM CERTAIN DLC QUESTLINES WILL HARDLOCK YOUR PROGRESS BY CONTINUALLY CRASHING AT THE END OF THE MISSION , THE WORKAROUND FOR THIS IS LAUNCHING THE GAME VIA THE EA LAUNCHER , WICH IS A DUMB BUG WITH A DUMB WORKAROUND THAT I FEEL IS ALMOST INTENTIONAL', 'This title is a hostage of a corporation and you can''t play it unless you get the 700mb testicular cancer that is EA launcher. \r\n\r\nThen, there''s a different EA login required within the game.\r\n\r\nWon''t let you paste your password too, have to type it out, and if it''s above 16 characters and has some special chars that would trigger http: requests - too bad. \r\n\r\n', 'Mixed', 68.75, 38.33, 0.20);
INSERT INTO reviews VALUES (57308, 2366980, 4566, 'How much would you spend at the movies? $15? $20? \n\nBetter idea, don''t leave your house, buy this game instead.\n\nIts funnier than anything you''re going to watch there and you can stay in your underwear.', 'Charming at first, then...\n\nit gets really repetitive and kind of annoying to navigate. You mostly loop through the same areas with little flourishes that are new each time\n\nFeels like you''re playing a character in a mid-tier  show. Maybe more of a 2000s flash game. \n\nMight be worth a look at half the price.', 'Overwhelmingly Positive', 96.71, 3.50, 2.75);
INSERT INTO reviews VALUES (57313, 2368300, 218, 'Awesome game as long as the devs don''t give up on it.\n\nI am sincerely enjoying playing this. the combat system and beautiful pixel graphics make it so fun to play, and the fast pace of the battles keep it from taking too long for a battle.\n\nThis game was not ready for full release. It is severely lacking in features and has a multitude of bugs. I am leaving a positive review because I believe LAVABIRD is going to make this game great. We just need to give them a chance to fix their mistakes befo', 'Lavabird Studios should be charged with fraud for releasing this game in its current state. The Warside website claims 30+ campaign missions, there are actually only 24 after which the campaign abruptly ends without warning/closure. Basic functionality like explanations of game mechanics, animations, and game sounds are inexplicably missing in many instances. The plot of the campaign is often totally incoherent, with references to unique unit types that never appear and CO powers that the AI nev', 'Mixed', 69.27, 12.92, 10.82);
INSERT INTO reviews VALUES (57337, 2375780, 164, 'For only less than $15 bucks (sale), it offered a lot of feature, I don''t even need the pricey Tobee anymore.', 'Tbh it''s pretty crap. I initially tried with a pseye and c920 and with both there is no tracking, just guessing. No matter how often i calibrate, with/without glasses, how much my room is lit. it simply does not work beyond being sometimes roughly in the correct quadrant. Their calibration still doesn''t clarify whether the head is supposed to stay still during it or rotate to where one''s looking, in their discord they do, not that it would make a difference.  \n\nAll in all not the Tobii-killer i ', 'Very Positive', 87.80, 880.87, 4.38);
INSERT INTO reviews VALUES (57356, 2379910, 1829, 'I live in England so i can''t really tell the difference between these near-future dystopian cities and Milton Keynes', 'So this is not a fun review to write. As of right now, Dystopika has a very strong Overwhelmingly Positive review set, and it deserves it for the people that enjoy it. Alternatively, for actual city builder enjoyers this is a bit lacking. You see, this is not a game. It''s an experience. Not in the way Stanley Parable is, or walking simulators. It''s more of a boring clicker. \n\nLet me clarify - there is no game in this game.  You place buildings, move them around, make them bigger and smaller. You', 'Overwhelmingly Positive', 96.50, 1.20, 0.12);
INSERT INTO reviews VALUES (57361, 2382520, 904, 'The NPC''s hate me. Reminds me of home. I left a party after dying to a boss and was promptly whispered to "git gud" before the A.I. blocked me.\n\n10/10. Will be playing daily.', 'This isn''t a bad game by any means, but I don''t recommend it for anyone outside a relatively niche audience.\n\nThe idea of a single-player MMO with bots has been floating around for a while and systems vaguely similar have been implemented in the past (e.g. GW1 henchmen/heroes). However, this is the first game I''m aware of that''s build from the ground up around that concept. And it does a good job of it from what I can tell: it''s clearly a lovingly crafted "fake" MMO with simulated world chat and', 'Overwhelmingly Positive', 95.02, 1.58, 2.57);
INSERT INTO reviews VALUES (57366, 2383990, 675, 'The closest you''ll feel like being a real ghostbuster short of building your own illegal unlicensed particle accelerator.', 'game full of console players , full of kiddos every time someone talking in voice chat is 4 y old kid ,matchmakking of lvl suck oh you are lvl 1 here you can go play vs ghost lvl 60, teamates who only walking around map like f NPC jesus this game can be so good but it s f trash', 'Very Positive', 91.11, 72.55, 1.68);
INSERT INTO reviews VALUES (57372, 2385530, 1739, 'I try to name my character Tucker.  "this name violates our profanity filter".  Okay?  I use Tuck, and that''s fine.  My first round I play against an NPC named Tucker.  Cool.  10/10 game I guess.', 'This game is a complete bait and switch.  I''ve played some grindy games in my day, but at least they gave you the opportunity of earning something that felt good at a reasonable rate.  Want to buy new clubs?  Spend VC.  Want to level your character?  Spend VC.  Want new shoes/glove/hate/sunglasses in the store.....SPEND VC.  Now 2K nerfed the VC gains and it will take you roughly 363 rounds to level a character to max level (99).  This is the mobile game model on F2P games, not something that sh', 'Mixed', 65.21, 72.23, 3.00);
INSERT INTO reviews VALUES (57379, 2387380, 261, 'I own over a hundred adult games. Most are pretty meh. Among all the meh, be a Bare Witness! It is really good. There are 11 endings with many combinations of the women. Each of the women are well written and very likable with their own interests, paths, and endings. I honestly liked them all. LOTS of great scenes. Also, it''s a complete game! Hate getting into other games, then it takes years to finish or is never finished. This one is great from start to finish! Looking forward to their next ga', 'The relationships feel shoe stringed and the main character seems to just not care that his Witness protection was broke. He says he does but his actions are basically the opposite of someone who would die if they''re name and location got out. Also, apparently you can just google his fake name and it shows you his real name?????\r\n\r\n The character models are that once type that fluctuates between uncanny (or gross) and fine depending on the lighting. Like a character will smile into the camera an', 'Very Positive', 92.72, 16.40, 7.08);
INSERT INTO reviews VALUES (57384, 2389040, 145, 'This is not a game for hardcore factory builder fans, this is a game for rogue-like fans who like factory builders but get tired of them once the scale gets too big.', 'I keep coming back to the game, so that bodes well. The initial promise is there, and the idea of creating units that are immediately used in a battle in a factory management style game is fun! But the actual application of it is lacking at the moment. It does not feel like the devs even test their game. I also feel like the playerbase has been pretty vocal about a few requests but have gone unanswered/unacknowledged.\n\nAt the moment, I don''t recommend the game. There''s the potential for this to ', 'Very Positive', 93.10, 49.15, 11.90);
INSERT INTO reviews VALUES (57392, 2390230, 200, '1% cook serve delicious gameplay\r\n99% yakuza + quentin tarantino + soap drama of your choice storytelling\r\n\r\nthis game is beyond goated', 'The idea of a typing game where you run a kitchen sounded really fun to me, but the execution didn’t quite land. The game play mechanics felt a little confusing and didn’t flow as smoothly as I hoped. I did appreciate that there was a story to follow, which added some charm, but overall, the game didn’t fully click for me.', 'Overwhelmingly Positive', 98.00, 2.00, 0.38);
INSERT INTO reviews VALUES (57393, 2390260, 1077, 'Ok, let me start off with saying how this game changed my whole life. I love this game more then my family, if  someone said to pick between Topple Tactics and my family I would choose Topple Tactics in a heartbeat. The game has perfect gameplay and amazing sound design. The sounds that the small toppler makes is perfect and I love it. My whole life has changed in the time I have had this amazing game, the game starts with the best minigames to decide who becomes the terrible monster of Mega Top', 'The game might be good but we''ll never know it because there are no players online. Check steacharts before buying it. Too bad. I really liked the idea.', 'Very Positive', 90.53, 84.50, 0.12);
INSERT INTO reviews VALUES (57454, 2391870, 140, 'This game really did something to me... it made me emotional. It was simply beautiful.', '', 'Overwhelmingly Positive', 100.00, 8.12, 0.00);
INSERT INTO reviews VALUES (57455, 2391900, 137, 'It''s fast and it''s fresh. \r\nYou got five bucks? \r\nYou even like Hot Wheels a little bit? What are you waiting for?', '4 out of 5 matches i played with a friend got ruined because of server disconnects. Quick play has alot of ai bots that just run into walls . Great combat but game breaking bugs that need to be fixed.', 'Mostly Positive', 77.37, 4.23, 3.08);
INSERT INTO reviews VALUES (57470, 2392230, 140, 'i came in expecting ghost titties, i got that AND ghost polycule. hell yes. hell. fucking. yes.\n\nedit: for science is my favorite ending. good ending for everyone. i love my stupid, cringe, ginger boyfrend. ghost boy is cool, but im obsessed with my pathetic little kitten. fucking idiot. GOD i love him so much, i want to put him in my mouth and shake him around like a dog. he''d probably let me too. i need to get him pregnant.', '', 'Overwhelmingly Positive', 100.00, 4.22, 0.00);
INSERT INTO reviews VALUES (57471, 2392280, 169, 'Support indie developers! A breath of fresh air in what is turning into a AAA gaming hellscape. Play the game and help development of the newest indie gem', 'What everyone is saying about the UI and the difficulty is spot on, this is an annoying experience. What few others have mentioned however is the infuriatingly slow animations. If you''re just learning how to defeat an early wave, and keep losing to it, having to sit through a journey to the map and a journey back to the level every time you lose is unbearable. It''s a game where you''ll wear out your escape key, not because it cancels anything, but because you''re hammering it hoping by some magic ', 'Very Positive', 86.98, 0.25, 0.47);
INSERT INTO reviews VALUES (57480, 2392520, 144, 'Please fix the inflation bug in this game, inflation makes this game unplayable. Spend some time and redesign the formula you use for inflation the current calculation method is buggy, you cant take poorer countries out of poverty without crashing your economy in the process and having social security cost go out of control @eversim', 'Built 33 tanks as Sweden and now my growth is 180% and the tank industry is 50% of my economy. Good lord. They can''t make this game work if you give them 180 years to figure it out. Imagine achieving hyperinflation by building 33 tanks. This would be such a good game if it was functional.', 'Mixed', 50.69, 133.80, 55.23);
INSERT INTO reviews VALUES (57500, 2393160, 995, 'Viva La Dirt League made a game and my adventurer heart can''t handle it.\n\nThey have take some of the best bits of there sketches - awkward dialogue loops, pointless fetch quests and of course Baelin''s Route and turned it into a fever dream.\n\nSeeing my favourite YouTubers go from sketch comedy kings to creators of an actual game is amazing. You have rolled a nat 20 and summoned perfection.\n\nViva La Dirt League, you''ve officially leveled up. GG', 'The idea of the game is fun and original, dialoges are funny, visuals are nice. But the gameplay is just dull... its all just a bunch of quests to "bring this get that" and it gets old very quickly. The mechanics of fishing are interesting but personaly it also gets a bit too repetitive.', 'Very Positive', 91.16, 1.93, 1.38);
INSERT INTO reviews VALUES (57523, 2393770, 164, 'My God. What a game. Please make a second with more depth on playing in Europe and maybe International. Your close to making a £50 game here. Makes FIFA look like trash. LOVE THIS GAME. Thank you for creating it. AMAZING..........', 'Trash lol\n\nGame has thousands of glitches I have found in the first hour of playing, and, I know this is just my opinion, but the gameplay is just, what do they call it, poo poo on a stick. It''s WAY too fast paced for a "calm relaxing football game," and the amount of mistakes the ai, and the player, makes, is just rage inducing. Maybe one day I can look back and really enjoy the game, but right now, nope.', 'Overwhelmingly Positive', 98.17, 15.63, 9.22);
INSERT INTO reviews VALUES (57560, 2394650, 1063, 'I really, really appreciate the idea of casual metroidvanias, and I think Crypt Custodian is even more charming than Death''s Door. It''s not hard, but not trivial either, has a lot of secrets and unlocks, and making ten friends among dead animals is a very worthy quest. Some gimmicks feel a bit less inspired than others (the rafts are only used in one location, and in an uninteresting way), but overall it plays really well.', 'As a Metroidvania I would not recommend. Basic, repetitive, unfulfilling exploration. Controls nicely though. Good game for someone out there, but not a MV I would tell others to play.', 'Overwhelmingly Positive', 98.40, 19.15, 0.78);
INSERT INTO reviews VALUES (57580, 2395210, 2745, 'every activision and blizzard executive is going to hell before they die for merging vicarious visions and sending their employees to the diablo and call of duty mines instead of remastering thps 3+4', 'Always Online DRM.', 'Very Positive', 88.74, 59.60, 6.17);
INSERT INTO reviews VALUES (57634, 2396240, 1080, 'Not long into it, but can already tell it''s everything great about SteamWorld Heist 1 and more.  The SteamWorld franchise titles are instant purchases for me and this is no exception.  Was counting down the minutes to release and am eager to dive back into this beloved world!  Heist 1 was my favorite in the franchise so I''m beyond eager to see where this new adventure takes us.', 'Ugh, I really want to give this game a good review. It gets a lot right for a tactics type game, but it falls into the worst and most major sin: Reinforcements.\n\nI get it. You want your game to be challenging, and giving players too much time means they can crawl their way through. But why, why in god''s name would you think the solution is to spam adds at random throughout the stage? The entire game is about positioning and reinforcements literally flip over the chess board. You can do everythin', 'Overwhelmingly Positive', 95.00, 40.77, 6.40);
INSERT INTO reviews VALUES (57663, 2396980, 1187, 'New generation wouldn''t understand why Tohsaka has a defenseless a....', 'They removed the sex scenes! That was the only reason i read this 500 hour long novel few years ago,just to see the threesome in the first route and it was so worth it. I find this insulting,you cant just cut off something that makes this novel +18,now fate series is officially like +13. Hell even Heavens Feel movies had one sex scene, why not follow the story as it is written? The new players wont even know epic memes like defenseless Tohsaka,my favorite meme from stay night.\nCringe remaster.\n\n', 'Overwhelmingly Positive', 97.30, 57.15, 109.87);
INSERT INTO reviews VALUES (57670, 2397250, 136, 'CASTLE CRASHERS!\n\nNow that I have your attention, this game is a bit similar to Castle Crashers, one of my favorite games. It is an exciting, kind of goofy, hack-and-slash game that really keeps you interested with all the different playable characters to unlock and boss fights to conquer! Weapons are pretty cool and unique, but my favorite part of the game is the different abilities and the art style!\n\nI am only a few missions in, but I am already enjoying this with my little brother immensely.', 'I was concerned when the game recommends you use a controller and then doesn''t allow you to navigate the options menu properly or even start the game with a controller.....Odd, but manageable. But, I returned the game once it started when I noticed there are inverted controls that you cannot change at all! Inverted controls (meaning "down" brings you upstage and "up" brings you to the foreground) in a beat ''em up is a laughably stupid choice. At least allow the player to change it. Geez. Returne', 'Very Positive', 84.56, 10.93, 0.13);
INSERT INTO reviews VALUES (57703, 2398030, 213, 'Game is fun, good graphics, easy to use a Radio Transmitter and tether it to the game.\r\nThis game has a ton of potential.\r\n\r\n**PLEASE ADD STEAM WORKSHOP SUPPORT SO PEOPLE CAN UPLOAD MAPS TO THE GAME**', 'This project is dead. There hasn''t been a single update in over 9 months — and even that last one was just a minor patch.\nThere''s been zero communication from the developers: no posts on Steam, no official Discord server, nothing on any platform.\nThis simulator had potential, but it''s turning out to be yet another Early Access scam that will likely never see a full release.\nThe devs originally announced version 1.0 for 2024. I could have understood delays if they had aimed higher or simply kept ', 'Very Positive', 90.61, 10.52, 18.12);
INSERT INTO reviews VALUES (57708, 2398170, 393, 'i enjoy this game. not a lot to do after unlocking all the upgrades.', 'S++ fun for about 50% of the game B+ fun game after for about 60% the other 40% is being over powered digging strait down grab a thing and leaving. upgrades get pointless after gem storm. very fun for 50% off. the perks need balancing. ex if you have certain perks like bombs ect the drill gets pointless. other perks like the drone that shoots or buzz saw never get to see mobs as they are dead before they do anything. the third hero is so strong with gem storm i stopped and never used the other t', 'Very Positive', 84.22, 23.32, 15.63);
INSERT INTO reviews VALUES (57751, 2399060, 128, 'Ate candy. Died. Sniffed test tubes. Died. Engaged with characters. Died. Tried to leave instead of engage with characters. Died. High recommended.', 'I am not really sure what to make of this game.\nI loved Cooking Companion, so this game was a no-brainer buy for me, but it is kinda disappointing:\n\nThe good part of Cooking Companion was the progression. At the beginning, it was a normal day and everyone was happy. With some mild hints and time, it got scarier, and this kind of progression is missing for me in this game almost completely. It basically cuts right to the action, and the clever horror elements and uncanniness that were sometimes h', 'Very Positive', 85.16, 15.90, 4.63);
INSERT INTO reviews VALUES (57759, 2399160, 1649, 'Great game. Love the marriage system. Awesome to see a dev who sticks to his vision.', 'hardcoding marriage to be exclusively heterosexual so that modders cant even add same-sex marriage is really weird, man', 'Very Positive', 84.66, 1.08, 0.83);
INSERT INTO reviews VALUES (57764, 2399220, 123, 'For those that are blissfully unaware, GET.THE.PATCH.FROM.JOHREN for the full experience', 'First, the vn is mosaic censored, even after the 18+ patch. That alone is reason to recommend against buying Nukitashi.  The story is mildly interesting, however, 3 hours in and I haven''t made a single decision. It appears that I''m reading a $29.99 manga through Steam. I can get better translated, truly uncensored manga for less than that. Big thumbs down.', 'Very Positive', 87.80, 33.95, 2.83);
INSERT INTO reviews VALUES (57768, 2399420, 2938, 'People giving bad reviews because they are having bugs in an Early Access.\n\nStupidity put apart, the game has the best force feedback on the market (improved version of the already #1 rFactor 2 physics engine).\nGraphics are clean, tracks are true to life, and the netcode is really good, making it possible to have great battles with contact (unlike other sims like iRacing).\nAs for the bugs, there are still some crashes from time to time but they are very rare now, at least for me. I''ve never had ', 'It is fun but releasing DLCs while it is still in Early Access is questionable. I feel like it would be more fair to release the DLCs as updates for Early Access users rather than releasing them as paid ones.\n', 'Mostly Positive', 76.38, 294.63, 44.97);
INSERT INTO reviews VALUES (57779, 2399730, 233, 'I LOVE this game.  It''s a blast from the past.  I played the original for hours on end.  Here I am, 60 years old, and still enjoy this game.  My one complaint is in the arena.  If you lose the match, you lose 100% of your bet.  If you win, you only win 10%.  Must have something to do with the odds feature.\n\nAnyway, 9.9 outta 10 for me.', 'As a Front Mission veteran, and having played every Front Mission game there is, I am EXTREMELY disappointed with this. This shouldn''t even be called a remake. More like a downgrade. I was hoping the mercenaries update would fix a lot of bugs and add exciting new content. All we got was more bugs and random crashes with a very crappy multiplayer/side story. The SNES and DS versions had a way better multiplayer system that was fun. And the models for the wanzers look like a man on acid and LSD tr', 'Very Positive', 84.98, 256.87, 51.08);
INSERT INTO reviews VALUES (57783, 2399830, 41697, 'I have played the ''old'' Ark Survival since its release back in 2015. But held back buying this one as I felt the price was high, considering it is the same game I already purchased. Now, at less than $40 AUS, I thought it worth ''giving it a go''.\r\nAs you probably read, it has better graphics. And it does. Not just the game, but even the menus seem more ''crisp'' and professional. Everything looks better, and the vegetation is thicker. \r\nThere was a warning that you need at minimum a NVIDIA 4070 to ', 'I waited to write a review.  I wanted to see how things go.  Every mod that is really interesting goes premium.  Which is fine, but things I would have normally tried on ASE, I am skipping, including maps.  The thing is, the base game plus DLC is the price of a premium game.  And now there are more DLC, pay to play dinos.  It is just too much too quickly.  ASE was about no microtransactions.  I really support the idea of mods getting rewarded by placing their mods under premium, I just cannot sp', 'Mixed', 58.68, 232.73, 2024.12);
INSERT INTO reviews VALUES (57791, 2400160, 538, 'I was surprised to see Glyphica, a typing game, listed as having full controller support. Rather than just menu control or an awkward on-screen keyboard, the game features a proper controller mode in which the words that kill enemies are replaced with sequences of button inputs. If you enjoy type-to-survive games then the presence of an endless mode is enough to justify a purchase, and then the inclusion of a controller mode for casual fun just makes it even better.\r\n\r\nGlyphica handles the rogue', 'Enjoyable, but I have some complaints. \n\nOnce things really get moving, you can''t read any of the words so you become rapidly doomed to fail. Which is very discouraging because once you get on a roll it''s basically over. \n\nTheir needs to be some increased contrast or highlighting of the words. so you can see them through each other somehow. If they become uninterpretable the game stops being fun.', 'Very Positive', 90.89, 7.18, 1.78);
INSERT INTO reviews VALUES (57797, 2400340, 452, 'Nazrin rolls "worst bomb ever"\n\nAsked to leave Gensokyo', 'Other than the new characters and songs which are really cool, Unfinished Dream of All Living Ghost feels like a downgrade compared to the other games. The gameplay style of UDoALG feels quite gimmicky (specially on harder modes), the character balance is all over the place and it even lacks basic features like a scoring system or replays.\nBeing honest I''m not really sure of what will be ZUN''s next step with the franchise after releasing this unfinished mess to the public.\n\nJust play Phantasmago', 'Very Positive', 93.36, 19.50, 11.63);
INSERT INTO reviews VALUES (57801, 2400430, 326, 'Wazzler and his Haohmaru out here ruining everyones day . He must be stopped', 'If you''re buying this for Power Stone 1 and 2 that you experienced on the Dreamcast, don''t waste your time - the singleplayer experience of Power Stone 2 and the vast item creation system is not there. Its JUST the arcade modes. Don''t buy this expecting them.', 'Mostly Positive', 79.45, 5.62, 0.17);
INSERT INTO reviews VALUES (57802, 2400510, 1642, 'Balatro but its blackjack. Solid game so far, super fun!\n\n10/10', 'I played Balatro for hours and hours and I know that Dungeons & Degenerate Gamblers is not Balatro. The biggest downside: no easily comprehensible card descriptions and their potential impact on the game.\n\nAlso, there is no way to strategize or think. You just hit and hope that your opponent doesn''t have some special cards that disrupt everything. Often times, you don''t even know what''s actually happening. Cards move in all sorts of directions and you have to check the card afterwards to see, wh', 'Very Positive', 83.31, 2.43, 0.55);
INSERT INTO reviews VALUES (57807, 2400640, 188, 'I don''t normally write reviews, but man this one deserves it.\r\nNanoApostle is just brilliant. At first I was scared of the amount of actions, I feared the game was unnecessarily complex for the sake of it, but I swear, it finds a way  for you to use everything in your toolkit.\r\nIf you love bosses in which your first attempt only goes 10% of the way through and you go "this is impossible, I don''t even understand what''s happening" and you enjoy learning the patterns and seeing your progress try af', 'If you like hard games with a fast pace you will like this. For everyone else. Stay away.', 'Overwhelmingly Positive', 95.74, 10.07, 0.63);
INSERT INTO reviews VALUES (57815, 2400770, 740, 'not currently playable on steamdeck. Hoping issues are fixed soon because I loved the demo and have been super excited to play.\n\nCrashes before title screen', 'This is just not a fully fleshed out game. This feels like a demo of something that could be great. Progression is slow without any agency from me to speed it up. You aren''t supplied enough information to effectively optimize. This doesn''t feel like $15 of a game.', 'Very Positive', 80.00, 16.27, 6.72);
INSERT INTO reviews VALUES (57821, 2400880, 136, 'a ghost was standing near the door looking at me. I do not recommend because i almost pissed my pants. Good Game', 'Basically plays like a bad gmod horror map.', 'Very Positive', 87.50, 0.52, 0.45);
INSERT INTO reviews VALUES (57832, 2401230, 577, 'i attempted to fight the first boss using a wooden halberd and she proceeded to cut the damn thing in half and then she promptly decapitated me\n\nim not even mad that shit was awesome', 'i loved clone drone in the danger zone, my brother got me into it and we both 100% it on our switches. so when we heard that the vr was coming out we waited and waited. we were excited to learn that thr release date would be smack dab on my brothers birthday, so i waited for it to come out and i bought it for him so he could play. i left for a few hours and when i came back he told me he already beat the whole thing. so i decided to play as well and i beat it too. and let me say we were very dis', 'Very Positive', 90.81, 4.87, 8.82);
INSERT INTO reviews VALUES (57840, 2401410, 605, 'First off. I really REALLY like this game and I will undoubtedly play this game many times over BUT one thing that bugs me so much is the "romance". \n\nFirst you meet a character that you can flirt with and tease to hell and back only to find out that nope cannot romance that guy because he is gay...And mind you they could have made everyone gay in the game and I would not have minded if I realized it from the get go.\nBut I played hours and thought it was so OBVIOUS this guy would be someone you ', 'The atmosphere and the story is great but the gameplay is just not there yet. There are tons of bugs that make the game borderline unplayable. Crashes, for one. Another issue is making a choice the game doesn''t expect you to and forcing you to reload (did you do X but ran out of time to do Y? The game will not let you sleep in your coffin even when it''s daybreak and impossible to do anything else but die). Another issue I hope they fix is the ability to skip. If you reload or restart the game, y', 'Very Positive', 92.89, 55.38, 26.52);
INSERT INTO reviews VALUES (57854, 2401970, 670, 'Really fun game that will make you feel smart, that scene where miles and phoenix started having gay sex was bizarre though… not sure why they added that in', 'The circus case from Ace Attorney: Justice for All is more interesting than anything on offer here.', 'Overwhelmingly Positive', 98.66, 68.53, 58.38);
INSERT INTO reviews VALUES (57867, 2402280, 156, 'I am going to recommend this game because it''s marvelously written and excellently put together. I also love World of Darkness stuff and I''ve been really into Werewolf lately. \n\nHowever, there has NEVER been a Choice Of Game that has ever needed a save function as badly as this game imo. This game is massive and very in-depth, and you have to make a lot of decisions and choices blind, and it''s very easy to ruin a very thoroughly thought-out run with a tiny mistake, and restarting this game from ', 'Credit where it''s due, the dev put a lot of effort into writing all of this.  And some of the writing is good - I actually lol''ed at one point (ah, Nin, and her inadvertent quips).  But a lot of it gets rather tiresome - who knew that werewolves wanked so much, and so repetitively, about "stomping fash", killing Nazis, and taking out the police?  I thought Werewolf was about saving the planet (used to be back in v1); something we all can agree on.  Alas.  Also could use a save button, the abilit', 'Very Positive', 90.38, 85.12, 16.50);
INSERT INTO reviews VALUES (57914, 2403290, 102, 'Recommend to read both "Childhood''s End" by Arthur C Clarke and "Night on the Galactic Railroad" by Kenji Miyazawa before playing / buying the game.', 'I really enjoyed it at first and played for the engaging plot and silly routes, taking great interest in the relationship between the two main characters. The plot was cute, and had actual depth - I was super excited to hear about the situation with the school and students.\n\nBut unfortunately the sudden presence of outright gooner bait and weird sexual content in the underground area, especially since the mc is a literal schoolkid, is really off putting and overall ruined the world building and ', 'Very Positive', 94.12, 3.77, 8.77);
INSERT INTO reviews VALUES (57945, 2404000, 303, 'An hour long story about hiding a weapon of mass destruction.\nThe voice acting is also really good.', 'While Sulcate''s art is great, this is not their best work. Very short game with no animations, like max 3 pictures per sex scene and less than a dozen unique pieces of art.', 'Overwhelmingly Positive', 95.71, 1.57, 0.37);
INSERT INTO reviews VALUES (57962, 2404370, 344, 'I have zero knowledge about Love Live but I think Yohane is a lovely character, really like her.\nThe game is a short light metroidvania of a good quality, can be finished 100% in 8h c.a.\nThe full price for this title may be prohibitive for a lot of people in my opinion the entertainment it delivered to me was enough to leave me satisfied so I''m not regretting the purchase but it may of course be different for you.\nThat thing just before the ending thou... that was unnecessary.', 'abusive relationship', 'Very Positive', 92.73, 8.27, 260.08);
INSERT INTO reviews VALUES (57987, 2404880, 770, 'Its fun, but game is way too easy, 0 challenge whatsoever. Allot of mechanics that are completely unnecessary, just buy any car and put it on the lot for the most you can and eventually someone will pay full sticker price for non-drivable hunk of rust. There''s a rival dealer mechanic that lasted 5 days before they just added a setting that turns him off. (lazy) The driving mechanic gets boring fast, all vehicles feel the same. No suspension means a curb sends you into orbit. There''s like 7 car m', '- game runs very poorly, even on the lowest settings\n- graphic is not that good. And the trees flicker like hell\n- car sounds are boring. Every car sounds same\n- the driving is awful. You get stuck on every corner, the cars spin like crazy. When you break it feels like nothing happens\n\nMaybe it will get better with some updates but for now I would not recommend it.', 'Very Positive', 80.52, 57.00, 0.60);
INSERT INTO reviews VALUES (57997, 2405060, 206, 'If you dodge the terrible voice acting and a UI made by someone on the team that had a little bit of extra time over, it''s a pretty fun game. I recommend it, but wait for a sale - it''s a bit too much for what it is at the moment.', 'in a way i´m kind of suprised, that it have so positive review, what´s there is really not that bad. But it just don´t feel complete at all. In these 3 hours, there have been some issues. like enemies, especially bosses at times just standing there. at random points, had a issue where the camera went underground, in a good run. i hade to let the character die. because it was unplayable. a enemy that got behind a fence when it spawned. almost unable to damage it. status effects, that you barely n', 'Very Positive', 88.83, 0.53, 6.23);
INSERT INTO reviews VALUES (58044, 2406180, 179, 'This game is fucking awesome. It takes me back to my childhood, where you''d browse the "lesser sold/unknown" games on the bargain bin, but you still took the risk in bringing some of them home cause the cover looked awesome and ended up finding real gems. This is one of those gems.\n\nIt''s mindblowing to me how something so basic, so devoid of pretentious fundamentals and media, comes together in such an incredibly polished and FUN experience. It''s even more mindblowing when you realize it''s 1 dev', 'The game looked really appealing to me but I immediately noted a few issues for me. When you run, there is a disjointed stutter that happens at all times that can''t be disabled. This may be because I use an ultrawide, but it gave me a headache and made me feel motion sick very quickly - an issue I have never had before playing a game. Other than that, I just am not a fan of the systems within it. I hope the game succeeds because it has an incredible look to it, but its not for me.', 'Overwhelmingly Positive', 97.21, 26.87, 0.45);
INSERT INTO reviews VALUES (58071, 2406770, 19155, 'DONT BUY THIS GAME IF U HAVE AN OLDER PC.... This game takes alot to run.\n', 'After this micro transaction update all character customization is gone other than preset skins locked behind a price tag. I''ve spent 150+ hours of grinding this game to make my character look the way it did piece by piece and now that''s all in the trash.. Big disappointment by these developers.', 'Mostly Positive', 73.23, 11.18, 162.63);
INSERT INTO reviews VALUES (58094, 2407270, 2152, 'Don''t let that terrible IGN review fool you. This is a great game that is a ton of fun and challenging. Defeating the bosses will give you the souls high satisfaction many lovers of this genre chase after.', 'The combat could be good, but the enemy attacks are timed terrible. Long preparation, and then instant attack. There is no movement, no animation, the attack just lands and you get hit. No human can ever react to it, it''s basically 1-2 frames. \nAnd this is in a game where parriyng is haevily implied and sometimes required.', 'Very Positive', 92.98, 26.68, 17.67);
INSERT INTO reviews VALUES (58096, 2407310, 135, 'Last time i was in a zombie apocalypse my buddy fredrick blew his brains out after fuckin this one baddie of a zombie like Level 10 Gyattttt, this game reminds me of that incident', 'An hour, an hour and a half, that''s how long the whole game is.\nNot worth the money.\nThree levels two are with zombies and that''s it.\nThe cutscenes are cheap, short, two seconds are few and those pictures with the good quality in the store are not in the game. And you cannot control the gallery with a mouse.\nMaybe 1 euro for one play, that''s how much it deserves.\nGames are becoming more expensive and the quality more cheaper.', 'Mixed', 69.63, 2.17, 1.53);
INSERT INTO reviews VALUES (58118, 2407830, 518, 'All other ''Cozy Games'' that put time pressures on you need to pay attention to Trash Goblin. \r\n\r\nThere is a clock, yes. There are only so many tasks you can get done in a day, yes. But there isn''t a pressure. Customers will wait for you to find their item, or come back and it''s ok. \r\n\r\nThis game is whimsical, lovely, and an actual COZY game.', 'For now, I think the game is way too limited to be entertaining past the first hour. You''re mostly playing the same block smashing game, hoping for RNG to accommodate you and actually give you what the customer asks for. Your pay for most items is pretty low compared to the cost of upgrades, most of which don''t actually streamline your business but just give you more storage to cram more garbage into. I don''t like that cleaning a single tooth takes as long as cleaning a giant jug, and that the s', 'Very Positive', 88.61, 7.78, 1.80);
INSERT INTO reviews VALUES (58164, 2408820, 2693, 'I feel like a lot of the negative reviews I''ve seen here have the wrong notion of what the game is.\n\nIf you are looking for Stardew or Harvest Moon-like experience where you balance time, resources, and relationships; this is not the game for you. If you are looking for something that is more chill like Animal Crossing (New Horizons specifically) but with the basic functionally of farming, mining, and exploration (puzzles are easy but fun) then this IS that game.\n\nI have greatly enjoyed my time ', 'I''ve enjoyed the heck of of this game. But with the most recent update I can not genuinely recommend it to most people who play games. If you are a HYPER casual gamer who doesn''t even really want gameplay then this game might actually be for you. For anyone who actually want''s a game in their game, that''s mostly been removed here. I waited quite a while to leave a review since the patch dropped in hopes that the creator would package the new version into some sort of "easy mode" or "story mode" ', 'Very Positive', 90.27, 40.10, 19.93);
INSERT INTO reviews VALUES (58177, 2409110, 149, 'One of the most ambitious games I''ve ever seen from a solo developer. Story is very intriguing and the characters are immediately endearing. You can also beat up giant frogs and you have a son named yooba.', 'Judging from the majority of reviews Im seemingly alone with this opinion, but so be it. Dont forget to Jester.\n\nWhile I think the combat is well thought out it still kind of feels annoying. Enemies always fly backwards after finishing a combo and you always have to run after them. Enemies also never roam around in the game, they always spawn out of nowhere. Though the spawning animations are cool I guess. There are way too many cutscenes. They are nicely animated, but getting stopped every 5 st', 'Overwhelmingly Positive', 96.64, 2.08, 1.72);
INSERT INTO reviews VALUES (58187, 2409360, 241, 'Listen. The reviews saying that this game is repetitive and has huge swings in difficulty and really long.. All those things are true. But if you are a restaurant sim/time management game enjoyer, those aspects are PROS, not CONS. I cannot recommend this game enough if you are wanting to scratch a Diner Dash or Cook Serve Delicious itch.', 'lots of artificial difficulty, sure you can play on easy but even on medium to get 100% you hv to do the night missions with the game breaking your coffee machine every 3secs forcing you to play a stupid minigame each time it breaks down. do not get this game if you are looking for a chill game', 'Very Positive', 93.36, 28.67, 5.02);
INSERT INTO reviews VALUES (58204, 2409780, 118, 'if you want an easy money cheat you go in the dialog files and open them with the text editor. you find the add.money line and change the numbers', 'The reason why I cant recommend this game is for one thing, and it may not be a big reason, but for me, the reason that I''m going to make changes the review from good to bad. \r\n\r\n If you have played any of their other games, dont buy this one! \r\n\r\nThis game is identical to the other games, it has nothing new to it. You could put this into MOS, and you would probably not even notice its a seperate game. Its not that the games bad, it isn''t, but it also doesn''t stand out at all in anyway. They cou', 'Mostly Positive', 79.66, 5.97, 15.65);
INSERT INTO reviews VALUES (58221, 2410170, 107, 'I BEEN PLAYING RPG GAMES FOR OVER 40 YRS. THIS IS ONE OF THE MOST EXCITING GAME I HAVE PLAYED IN A LONG TIME.  I HAVE OVER 100 RPG GAMES ON MY PC. THIS GAME HAS IT ALL. YOU CAN GRIND ALL DAY FOR MATERIAL TO UPGRADE YOUR EQUIPMENT, MONEY, AND LEVELS. THE OPTIONAL BOSSES IS CRAZY. THEY JUST POP OUT OF NO WHERE. OVERALL THIS GAME SHOULD BE AN EXAMPLE OF HOW RPG GAMES SHOULD BE. THIS GAME IS BETTER THE THE TOP TIER GAME THAT''S OUT NOW. I HOPE YOU MAKE A SIMILIAR GAME IN THE FUTURE. THE PEOPLE THAT W', 'The game is quite good, but way overpriced. The story is nice, Combat is ok. But there is A LOT of grind. Like you will do the same combat 50 or 100 times in a row in order to get "potential points" (for example, if you play sword, you will have to grind potential points from lance, axe, bow, dagger, etc.) anyway.', 'Overwhelmingly Positive', 98.13, 218.70, 37.43);
INSERT INTO reviews VALUES (58342, 2412490, 139, 'HOT\n\nI’d recommend watching the gameplay on my site, but apparently, that counts as advertising.', 'You miss 90% of the scares because the game takes away your flashlight at the beginning. \nAlso no human being walks as slow as the gelatinous mass in this game does.', 'Mostly Positive', 76.98, 0.97, 1.97);
INSERT INTO reviews VALUES (58368, 2413050, 171, 'A great open-world retrowave game where you can just let your mind wander while listening to chill retro music on a car ride, or drive to the beach to save a hot chick''s life, or go in search of hidden VHS, etc... \nDo whatever you like, but just soak up the retrowave vibes!', 'A lot of stuff just feels out of place at this moment honestly. I waited for this game for quite a bit but I can''t help but feel like Rewind pushes more games just to farm on the retro/synthwave hype while failing to deliver an actual good product. I know that this is an early access, but it''s still just underwhelming even for this state of the game. Some things just feel... forced. And I just can''t feel like this game will still leave a lot to be desired in the end. Retrowave didn''t feel partic', 'Very Positive', 81.29, 5.87, 10.82);
INSERT INTO reviews VALUES (58426, 2414270, 520, 'This game is pitched as a couch co-op game, but I''m also happy to mention that this game works well if you set it up online via Discord game streaming.', 'Loved the game, but the constant looking down at mobile to PC is really annoying and it chews the battery. As soon as everyone can play via the PC for the controls i will repurchase the game.', 'Overwhelmingly Positive', 95.58, 2.98, 1.85);
INSERT INTO reviews VALUES (58445, 2414630, 159, 'This game is honestly amazing. The gameplay is really smooth and makes it feel rewarding to be able to sneak around the house. The environment and main enemy are perfectly balanced to deliver an unsettling experience which makes you want to replay it over and over again. The story is also very interesting. (Although I will say, for people who do not like reading, the story may not be as accessible.)\r\n\r\nOverall, if you like survival horror where you have to complete objectives while avoiding an u', 'This game started off well enough with an impressive setting and eerie ambiance. However, I then played further and discovered what this game is really all about... constantly hiding from a relentless and aggressive monster. For me, this only made the game a highly frustrating experience. This monster is somehow everywhere at all times. She''s lightning fast and can even grab you out of a hiding spot to kill you. This is also one of those games where you cannot defend yourself. All you can do is ', 'Very Positive', 91.82, 19.52, 2.85);
INSERT INTO reviews VALUES (58462, 2415010, 228, 'Death is babygirl', 'I dunno.\n\nIt was great until it wasn''t. More and more the game stopped pretending I had any agency and broke the facade of options.', 'Overwhelmingly Positive', 98.68, 41.72, 3.95);
INSERT INTO reviews VALUES (58470, 2415240, 104, 'Leaving DNA is an enjoyable slow burn AVN. \nIt has nice renders, good writing and a good story. \nIt has some lewds, but not a lot so far. If you''re just in for the lewds, it''s probably not for you, but if you like characters and story, then you will probably enjoy this one.', 'The renders are beautiful, I don''t think I''ve spotted a stock character asset yet.  Characters'' faces are expressive and their wardrobes change.  It''s really visually stunning, though nothing makes me hit ''skip'' faster than render slideshows of someone working out.  ;)  The writing is good on the technical side and conversations flow pretty naturally.\n\nI was happy I bought this and have been looking forward to updates, right until the "plot twist" at the end of chapter 4.  The dev pulled a bait-', 'Very Positive', 90.38, 6.15, 30.40);
INSERT INTO reviews VALUES (58494, 2415960, 398, 'My monitor has a few stains; the game should have come with wipes.', 'No option to turn off mouse smoothing. \n\nThere are also women in this game, I''m like 99% sure the redheads on the moving target ranges are Asuka Langley and someone else I''ve never heard of.', 'Very Positive', 91.46, 12.22, 0.23);
INSERT INTO reviews VALUES (58538, 2416880, 118, 'Animal Abuse Simulator 3', 'I spent SO LONG to get to cloud kingdom and what do I get in return? A SOFTLOCK. I CAN''T GET THE REQUIRED GOLDEN GEM, SO I''M STUCK NOW. HORRIBLE GAME, DON''T BUY.', 'Very Positive', 88.98, 24.18, 21.05);
INSERT INTO reviews VALUES (58584, 2417850, 273, 'This is a fantastic idler! I often had this running while I worked and found the level of involvement to be just right. The pixel art is outstanding. I loved going through all of the different palette options. And I thoroughly enjoyed the writing (including  the enemy names/puns). Good tunes, too!', 'Love the name of the game, love the way it looks and the characters are cute but the game play loop needs work.  Every time I''d check in to see if I could send my hero on a quest their needs would be too low so I''d set them to do toilet, bath, food and sleep which takes time so I''d walk away.  I''d get back to try to set them on a quest again but their needs would be back down. Rinse and repeat. I wish we could queue up going on a quest after queuing up their needs but it just interrupts their ba', 'Very Positive', 93.41, 141.32, 28.32);
INSERT INTO reviews VALUES (58611, 2418520, 1416, 'I NEVER played Farm Together 1 because at first glance it seemed like a mobile game ported to PC, BUT I WAS SO WRONG!  \n\nI''ve now sunk 150 hours into FT2 and gotten my husband, 70-year-old mother, high school son, and shooter-game-loving friend playing Farm Together 2.  It''s THAT fun, chill, and addicting.  It works on Steam Deck too and fills my PC''s ultrawide monitor!! \n\nYes it''s simple and repetitive, but there''s something about the desire to unlock all the crops, animals, and plots that''s so', 'This game just went from a positive pre-release to a thumbs down.\n\nThe devs as of yesterday 30th surprised everyone by suddenly stating the game is now fully released. Comments from other players (myself included) are straight up saying this is is NO way ready to be labeled as a full release. The reply from the devs was "well the game as a lot of content in it." Yes, for pre-release that''s true but the first game has considerably more. I''d dare say while this games offers some new experiences th', 'Very Positive', 93.08, 272.98, 106.93);
INSERT INTO reviews VALUES (58635, 2419090, 708, 'Dear Aspyr would you kindly also please release Star Wars: Episode III – Revenge of the Sith (video game) for PC \n\nAmbient occlusion is broken, drop FPS from 60 fps to 30 fps in Extreme, disable it , if you want a solid 60 fps.\n\n100.. 200.. 300! You guys are gonna make me rich.', 'My review is going to be negative for now even though I love this game. First of all they need to add multiple save files like there was in the original, I''ve collected all the secrets and will never see one again when replaying missions unless I am able to start a new save file. Second, when using keyboard and mouse the mouse movement is very jagged and stutters a lot. Also when moving the camera with a controller moving it up and down is a much higher sensitivity than moving it left and right.', 'Very Positive', 87.15, 14.97, 63.50);
INSERT INTO reviews VALUES (58672, 2419900, 124, '9 из 10\nЧудо хоррор', 'finding keys simulator', 'Mostly Positive', 74.19, 4.68, 1.47);
INSERT INTO reviews VALUES (58681, 2420110, 8583, 'the game can be a bit tough early on but then one must remember I am nearly 83 years old  but you younger ones should have no difficulty with your sharper reflexes', 'Aloy keeps on telling the solution or hints to puzzles within seconds of entering the area, she just does it too much that the game isnt challenging as the first game.\n\nI don''t mind the "talking to herself", it''s amazing and cute.\n\nWhat I do mind is the immediate hints on puzzles. You don''t even get to have a look around at what you should do before Aloy says "maybe I should move that crate over here" .05 seconds after I enter an area and haven''t even seen the crate myself.', 'Very Positive', 89.05, 411.20, 1.42);
INSERT INTO reviews VALUES (58693, 2420460, 184, 'Bought this on a whim, I liked the premise. I had no idea what i was in for. The animations are well rendered and the characters unique but that is but the tip on a very long iceberg. I mean cmon. This game has no right being this good. Superb writing, going from reaching for the tissues, to laughing then back to tissues (but in a different way). It''s remarkable, i just can''t wait for the finished product. Until then, I salute you QuadrupleQ', 'Another one of those games that drags on with releases. At least it is not one of those episode 1 2 3 4 etc. Looks like this is going to be one episode release per year with the rate it is going. More than likely be years until finish if it ever does.', 'Very Positive', 92.93, 12.55, 5.52);
INSERT INTO reviews VALUES (58698, 2420520, 109, 'A unique idea and a fresh take on a game like this. Music is not bad, pictures and cinematics rendered normally no errors were found when playing the game', 'Refund requested. This game is so boring, and worse, it is way overpriced. If you pay more than $2 for it, you''ve been ripped off. And if you paid $2, you still wasted your money.', 'Mostly Positive', 72.48, 3.22, 0.43);
INSERT INTO reviews VALUES (58707, 2420660, 2669, 'Life is hard. We run in circles, over and over again; never really stopping to question why. We find partners, friends we can place our trust in. We face hardship. We lose. We lose ourselves, we lose our friends. It can all feel so pointless. But there are certain points in these cycles where it''s important to stop and recognize. To ask that ever elusive question once again: why? Because if you listen closely in those precious moments, you can hear the answer. And although it can never last, as ', 'Neva is a beautiful game where the devs have let the aesthetics overtake gameplay and accessibility.\n\nMake no mistake, the game is gorgeous, but this comes at the expense of gameplay. Pop-up text is sometimes lost as white text on white skies, because the designers felt it would be too "ugly" to outline the text. The devs so want to show off their art that sometimes the main character and enemies can blend into the background, or be obscured by foreground. Character animations are very pretty, b', 'Very Positive', 94.64, 10.57, 1.98);
INSERT INTO reviews VALUES (58720, 2420880, 413, 'I enjoyed my time playing this game and I really like the cutesy witch theme, that''s why I preferred this over Stacklands.\n\nThat said, I don’t think I’ll do a second playthrough. Maybe it’s the repetitive gameplay, or maybe this kind of game just isn’t quite my thing.\n\nBut I had my fun regardless and if you like something like Stacklands or think this game looks kinda neat then just give it a try!', 'I have high hopes for this genre, this game on the other hand does not expand on games that came before like stacklands and cultist simulator. Buy those instead.\r\nThe art is cute, the game is unstable. You are supposed to aquire more and more cards while expanding the playarea but every time you do, there is a chance the game just freezes.\r\n', 'Very Positive', 92.25, 10.10, 20.40);
INSERT INTO reviews VALUES (58745, 2421410, 261, 'Dude, only play this game if you can handle pretty much any triggering subject. This game has sex trafficking, child sexual abuse, suicide, mental illness, etc. I almost couldn''t handle it with all the kid stuff. The subjects are very heavy and prominent. I love games with hacking, and Cyber Manhunt 2 was right up my alley. My only complaint is that I didn''t really care for the mini games in this one, especially the end game. Anyway, if you love hacking games, I definitely recommend playing this', 'Ultimately the game is boring. Every stage hinges on finding one piece of data that has been deliberately hidden so that you cannot use the tools given to you until you find it. This generally boils down to screen scrubbing:  mousing over each bit of text to see if it can be captured to your profiles. Sometimes you''ll be required to manually input a value based on logical deduction. There''s nothing really in the way of red herrings or alternate story paths.', 'Very Positive', 93.10, 12.47, 46.10);
INSERT INTO reviews VALUES (58765, 2421780, 126, 'It''s a decent game, if pretty basic. It would be nice if there were a better variety of positions to choose from, and that we as players had more control over what actions were performed. Not sure if it''s worth the $10 full price, but the half off sale price I payed, I would say is just about right. I recommend if you get this game, you also do so when it''s on sale, or part of a bundle.', 'This is a scam - half of the screenshots are not part of the game. This is not a dating sim at all! The sex scenes happen randomly and just look very dated. The actual "game" is horrible and short. The dialogue is clearly translated by someone with only a very weak grasp of English. There''s zero chemistry with the girl you''re supposed to be seducing.  I hoped for it to have at least a decent story but nope.', 'Very Positive', 80.16, 10.40, 0.92);
INSERT INTO reviews VALUES (58767, 2421820, 114, '⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⣠⣤⣄⡀⠀⠀⠀⣠⣤⣀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀\n⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⢀⣾⠟⠉⠉⠁⠀⢀⣾⠟⠉⢻⣧⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀\n⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⣼⡏⣰⣤⣤⣤⡄⣾⡏⠀⠀⢰⡿⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀\n⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⣿⡇⠈⠉⠉⣿⡇⣿⣇⠀⣠⣿⠇⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀\n⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠘⢿⣦⣀⣼⡟⠀⠈⠻⠿⠟⠉⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀\n⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠉⠉⠉⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀\n⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⣠⣤⣤⣤⣤⠀⣀⠀⠀⠀⣀⠀⠀⢀⣀⣀⠀⠀⠀⢀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀\n⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠈⣿⡍⠁⠀⠀⠀⣿⠀⠀⠀⣿⡆⢀⣿⠟⠛⠛⠀⠀⣿⠁⢀⣴⡿⠃⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀\n⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⢹⣧⣤⣤⡄⠀⣿⠀⠀⠀⣿⡇⢸⡏⠀⠀⠀⠀⠀⣿⣾⡟⠋⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀\n⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠀⠸⣿⠈⠉⠀⠀⣿⡄⠀⢠⣿⠃⢸⣇⠀⠀⢰⣷⠀⣿', 'TOO: expensive. TOO: short. ANIMATIONS: Limited. EVEN WORSE: cannot manually "save". AND: there is a FORCED ENDING after a number of in-game days which forces you to start over at the beginning. I should have paid attention to the label "MIXED REVIEWS". AND: Too late for a refund ;(', 'Mixed', 61.40, 1.83, 1.85);
INSERT INTO reviews VALUES (58778, 2422090, 145, 'Got 100% in just under 180 hours, fun game over all. Not super short but not a serious time-sink. Nails the basics of an idle/clicker game. Fun music on a loop, good looking visuals, a few things to always progress/level up and work towards', 'bugs bugs everywhere bugs\n\nand very boring even for idler/clicker :/', 'Very Positive', 82.07, 171.42, 78.12);
INSERT INTO reviews VALUES (58779, 2422110, 196, 'This is it. I have tried every single non-EA football game, searching desperately for a game with adequately smooth play, high creativity capacity, and solid coaching that has serviceable graphics. If you love team creation, league variance, coaching, and  arcade style play-ability coupled with significant strategic and play calling challenges, then this is your next download.', 'I bought this game as i was looking for a replacement for madden''s pitiful franchise mode. went in with high expectations based on steam reviews, but came out the other side less hopeful than ever that there will ever be a realistic franchise simulation for nfl fans. \n\nfirst of all, let me say that i don''t actually play games - i''m more interested in the gm side of the nfl, and with axis'' graphics being probably 10-15 years behind the times (they remind me of madden 2007-ish, to put things in so', 'Mixed', 69.90, 50.92, 55.85);
INSERT INTO reviews VALUES (58856, 2424440, 214, 'Difficult to decide whether to recommend this game or not. I bought it for the price of a coffee in Starbucks, so I can''t really complain about that. There isn''t much content and the story is not very engaging and very linear. At some point you can decide what to do, but the story still goes on the other branch. (the next day you visit the second branch as well, but the narrative is again wrong). This is one of the bugs in the game. Another one is the fact that all the achievements and scenes ar', 'The writing and dialog ruined the fun for me. The words (with frequent typos) coming out of the MC are juvenile, making it hard to relate to him. Word choices also conflict with the medieval time period.\n\nTried to enjoy the story and the game but after an hour or so asked for a refund.', 'Mostly Positive', 78.04, 2.67, 1.72);
INSERT INTO reviews VALUES (58863, 2424650, 250, 'A very cool Rouge-like that while simple has a lot of charm, a unique gameplay loop, a surprising amount of item variety, and even a hard mode that while unfair at times is quite fun.  All of this giving the game a lot of replay value for the price. Also your playing as a frog named Froggy who supports trans rights and hates capitalism whats not to love (⁎˃ᆺ˂)', 'This game has great art style and is a fun + simple game that will give you the serotonins. However I was surprised and disappointed with the political ideology messaging early on in the game at almost every second loading screen: "Froggy supports trans rights!" & "Froggy uses any pronouns!" etc. I just want to play a fun, silly game and not have this kind of stuff in my face.', 'Overwhelmingly Positive', 96.00, 3.65, 0.37);
INSERT INTO reviews VALUES (58890, 2425290, 101, 'that one chick bad as hell', 'this has the most janky, uncomfortable guns ive ever used in a VR game, which sucks, because it has the potential to be FAR better, with how all the physics of it work. \n\ni never even got to use the visual scripting because the game seemingly crashed? it was still open in the background, but i couldn''t do anything.\n\neither way, shows potential, but i mean, its been nearly a year since first release and its still this bad? thats not good.', 'Very Positive', 80.20, 0.42, 0.60);
INSERT INTO reviews VALUES (58981, 2427410, 1023, 'The game works perfect on the Steam Deck OLED. Even on Maximum graphic settings + FSR the game could get 60 FPS.\n\nThis time the game has controller support.\n\nIf interested, I uploaded my test on the Steam Deck OLED: https://youtu.be/jS-kGhh1Ufk', 'Honestly astounding and shout out to GSC for making SoC worse. A truly incredulous feat. You have to agree to some weird EULA, why? The original never had that. Also the main menu advertises the other games, just why??? Let me admire the CNPP in the background, it''s just strange and extremely unnecessary. \n\nStrelok also forgot to wear his glasses so the game looks WORSE than the original (Which came out in 2007... again, groundbreaking stuff). Plus other reviews are mentioning stuff about revisi', 'Mixed', 48.29, 0.90, 0.32);
INSERT INTO reviews VALUES (58982, 2427420, 272, 'Same story here as with CoP EE and SoC EE.  You get a solid, updated version of Clear Sky again, completely free and still, people complain. "Too dark," "too blurry," "not enough this," "too much that." Maybe modern gamers have just gotten too soft.\nIt’s Clear Sky. It runs smoother, looks better, has achievements, and costs zero. But people are acting like they dropped $70 on it and didn’t get a full AAA remake. Maybe dial back the expectations a bit? Not everything has to be photorealistic or p', 'They should fix the blur issue, I''ve tried many combinations but still couldn''t get rid of the absurd amount of blur game has.\n\nS.T.A.L.K.E.R.: Clear Sky - Blur Edition', 'Mixed', 45.22, 139.32, 6.72);
INSERT INTO reviews VALUES (58983, 2427430, 324, 'Still a damn good game. \nRegarding the redactions: I too would feel a bit salty if my coworker died defending my country from an invading army.', 'If you played the trilogy ahead of the STALKER 2 release then there is nothing groundbreaking here. It''s actually a major let down to be honest as the picture quality is blurrier and noisier than the original. No DLSS no DLAA, FSR sucks so yeah. It''s nice that steam owners of the stalker games got this for free, but it''s barely an upgrade. Instead of playing around with enhanced editions, they should be fixing STALKER 2''s A-Life as we bought at AAA cost into an unfinished game. Disappointed is a', 'Mixed', 45.99, 23.07, 0.58);
INSERT INTO reviews VALUES (59000, 2427700, 4008, 'For anyone wanting to skip this game ''cause it''s tagged "PvP": it''s not that kind of PvP.  It''s asynchronous--there is no interaction and your opponent isn''t really there--you play against a snapshot of a rando''s build.  It''s more like playing against randomized NPCs.\r\n\r\nHeavily addictive', 'Alt+tab causes game client to freeze for up to 10 seconds/game crash. \nIf you report this bug on their discord, you get kicked after a generic "verify your game files/check drivers" etc response with a smirk from the dev.\nBug has been a thing for over 6 months at the time of writing this review.\nOther than this, it''s fun', 'Very Positive', 92.86, 873.75, 45.93);
INSERT INTO reviews VALUES (59011, 2427950, 187, 'Please god. Please devs. Please somehow make this game multiplayer with prox chat. I''ll suck your cock. PLEASE', 'Cool concept, looks good, has a weird and very forced out of place story. The first few levels are well made but, it quickly just becomes walk from point A to point B. The cars aren''t even hard to dodge, like, you just walk the other way or press your super mega dash button. That''s only if they don''t get stuck halfway through the level. Main games only about 30 minutes long, about 1/2 of that time isn''t even on levels with active cars. The new Backroads content is about 10 minutes long. Nothing ', 'Very Positive', 93.05, 3.07, 1.18);
INSERT INTO reviews VALUES (59047, 2428810, 180, 'Nice. Now we are just waiting another year for them to remove this version and replace it with a remaster. Thank you Sony', 'Take all the best things about the Horizon games and all the best things about the previous Lego games... and throw them out the window to leave behind this.\r\n\r\nLevels are way too short, there''s no real exploration, no puzzles of any kind, nothing to really collect, even when I raised the difficulty on starting a game it was pretty trivial in combat... And I am about half way done the sacred lands at this point.\r\n\r\nCollecting the mini figures was something that took effort before, they''re gone. ', 'Mixed', 57.78, 1.47, 4.20);
INSERT INTO reviews VALUES (59048, 2428840, 143, 'I absolutely love it. The symbolism, the simplicity, the fantastic music, the intricate ways it uses puzzles, it''s all great, and on a low price point too! My respect to the devs. And that is without even mentioning the art, my goodness the art... This game is a journey and I am so happy it exists. I hope many find this an inspiration (as a writer, I absolutely did) and continue in the genre''s footsteps', 'Awful - there''s no game or story here, and such a jarring art style. Returned for a refund.', 'Overwhelmingly Positive', 96.50, 1.65, 0.17);
INSERT INTO reviews VALUES (59060, 2429100, 110, 'Fun lil Homestar games for fans of the show. It''s simple, yes, but for $2 I don''t think it''s a bad deal and anything to show support to the Brothers Chaps for continuing to make Homestar stuff is fine by me. Definitely feels like a classic Videlectrix type game.', '', 'Overwhelmingly Positive', 100.00, 1.63, 0.00);
INSERT INTO reviews VALUES (59067, 2429240, 222, 'Me: Mom, can we get Witchfire?\nMom: We have Witchfire at home, dear.\nMe: Okay.', 'Neat little game, marred by some pretty annoying design decisions.\n\nGold doesn''t need to despawn. It forces the player to play a certain way, which is never a good idea in my book, at least.\n\nHaving mobs spawn behind you when you''re backed into a corner of the map feels very cheap. Happens quite often.\n\nFinal bosses come off as pretty lazy. Both Countess and Cursed King spam huge AoE''s that hit for most of your HP bar.', 'Mostly Positive', 72.52, 0.10, 8.53);
INSERT INTO reviews VALUES (59075, 2429350, 470, 'it''s good, but... FAR too difficult. it took me two hours to get the first ending, and i feel as if the difficulty is TOO high.\n\nnow, yes, i did do all of the minigames before i finished night 5. but i only did that as a BUFFER, because i was getting VERY annoyed and mad because i just couldn''t get through night 5. it felt up in the air whether i got through a night or not.\n\ni hope the day one patch, if that happens, fixes the extreme difficulty, because it feels very, very unfair at the moment.', 'I love this game, but the length of the minigames and day 5 makes me want to rip my arms off and cosplay as Withered Chica.', 'Very Positive', 86.60, 2.18, 2.47);
INSERT INTO reviews VALUES (59098, 2429860, 762, 'The Female onichan is an allusion to Oppenheimer''s team of scientists operating on a Nuke while resisting the urge to drink the nuke''s bathwater', 'this game makes me realize how much i hate being alive, im sitting in my room on a beautiful day with my blinds closed playing "living with sister: monochrome fantasy" this is fucking ridiculous, im going on a walk', 'Overwhelmingly Positive', 95.01, 15.93, 0.58);
INSERT INTO reviews VALUES (59139, 2430730, 351, 'i''ve never felt such a strong maternal instinct for a video game child. i was so ready to kill for them. Actually bawling right now. Outside of that, my heart goes out to all the living lebensborn children.', '''''Just don''t blame yourself next time''''\n\n''''Heart Hardened after you said that''''\n\nWhat??', 'Overwhelmingly Positive', 97.44, 6.70, 1.45);
INSERT INTO reviews VALUES (59148, 2430900, 165, 'This is the best "game inside a game" I''ve ever played. This game really rewards people who pay attention as there is symbolism and twists eveywhere. This is a perfect example of how games can convey art and story in a way that no other medium can. Try to go in blind without spoilers because things get wild and it''s best experienced first hand. I hope you enjoy it as much as I did.', 'I really wanted to like this game, but it''s just frustrating. The game feels like it''s running at 60FPS even though it''s running at 144 FPS, making the input sluggish. The optimisation is also rubbish because my 3080 ti is running hot. Something tells me it''s rendering the entire scene in the game and outside the game at the same time. The combat is frustrating and damage is pretty much unavoidable. The puzzles are also annoying because they''re not complicated but always require you to look for ', 'Overwhelmingly Positive', 96.36, 4.10, 1.10);
INSERT INTO reviews VALUES (59154, 2431070, 231, 'g o o d', 'this game is a pile of dogshit.  it has scary thing move across screen. stock image blacked out and distorted. oh no they move scary image across screen im so scared. like actually, there was no effort. the scariest thing was the skull apearing on screen making a loud noise. but thats just cause it was a loud unexpected noise. genuinely worst game ive played. i spent my money on something like this. i can t believe. i beg you dont buy this you wont be scared by hearing random knocks. its genuine', 'Mostly Positive', 77.92, 0.22, 3.05);
INSERT INTO reviews VALUES (59156, 2431100, 470, 'Get yelled at, eat shroom, pet dogs, all while freezing your balls off was never better.', 'A well made and technically solid game that I enjoyed spending an hour playing - but I kept feeling like it was trying to be deeper than it actually was. In the end it just didn''t really go anywhere. I would have enjoyed more dog sledding and exploration, and less forced spooky moments / flashbacks.', 'Very Positive', 91.49, 1.38, 1.10);
INSERT INTO reviews VALUES (59186, 2431700, 139, 'This is the best VR game that I have played to date. It has a proper narrative and isn''t just a tech demo. The gameplay is reminiscent of Dishonored but in VR. Also, you''re a vampire in the World of Darkness.\n\nIf any of that sounds appealing to you then consider picking it up. I played on a Quest 2 with system link cable and didn''t have any technical issues. The only issues I had were related to achievements but that may have been fixed in the last update. If not, I wrote a guide to help get 100', 'Have you ever dreamed of being the world''s crappiest Vampire? Do you like VR games where the controls are so poorly done that even the most basic interactions like opening a door or turning a nob will make your blood boil? Are you looking for a game with a lack-luster story and mediocre graphics where 3 hours of game play will feel like 10 hours of torture? Then this is the game for you! I really wanted to like this game, but it is awful. You play as a Vampire who is more feeble than your averag', 'Mixed', 64.75, 42.02, 3.53);
INSERT INTO reviews VALUES (59206, 2432110, 108, 'White Album 2 when', 'Everything about this VN comes across as really inorganic. You meet all these friends that you went to HS with and you now attend university with. Honestly I felt pretty good about it. The banter at this part was okay. Except after this initial introduction you never hang out as a group again.\r\n\r\nYour gf is on tv, people have birthday''s, etc. None of these events lead to a friendly get together.\r\n\r\nYou also "randomly" run into your friends at your job and when you wander around town and they''re ', 'Very Positive', 92.59, 24.65, 25.30);
INSERT INTO reviews VALUES (59300, 2434160, 148, 'A good simulation game that targets the narrow subject of the office worker. The engine as in many other games of this plan - nothing fantastic and new in the game is not there, Outstanding in the game only sound component - it is perfect both in the menu and during the game it amused me a lot))', 'I definitely would not recommend this game to anyone.  I love Adult AVNs and I generally just dont bother posting a review when I don''t like a game, cause I want to be supportive of this genre.  But this game is just a joke.\r\n\r\nThere really is no story...or plot.  Not in my opinion.  Three hours to finish the game, and most of it just playing a click game to earn in game money to play the "plot".  I dont mind a little grind like that, but a 10-15 mins of total "plot" for my reward of just playin', 'Mostly Positive', 72.97, 2.33, 2.97);
INSERT INTO reviews VALUES (59343, 2435090, 907, 'It''s a really fun game and I would play it more but I ain''t buying the coming DLC if the dev does not add a Save and Exit mid run basic ass feature... Buyer beware: a run could take up an hour or so to finish.', 'I really want to like this game but there are so many little annoyances. The talent tree will generate dead ends, which can completely kill a run on higher difficulties. The class balance is whack, with the starter class being next to impossible to lose on period on any difficulty, with the rest lagging a mile behind feeling kind of shit to play with (usually) dinky range, glacial attack speed, and much more limited ability usage until 75% of the way through a run, if you can make it that far.\r\n', 'Very Positive', 90.96, 64.32, 14.03);
INSERT INTO reviews VALUES (59347, 2435180, 111, 'Artistic simulation of the existential dread of millenial and Gen Z life, the continuous cycle of living just to not die, birthed into the cycle to work in a machine as but a tiny cog, life is meaningless, there is no real happiness. Life is fleeting, it has no purpose but to eventually end, like a fever dream that you can never escape but you can but close your eyes to do it all again, and again, and again. The point of life is to suffer, or to not, all life is meaningless, your only real choic', '', 'Overwhelmingly Positive', 100.00, 21.25, 0.00);
INSERT INTO reviews VALUES (59390, 2435900, 311, 'Finished it in a couple hours, pretty fun for what it is\r\n\r\n\r\n\r\nTheres 1 (one) singular black man in the entire game\r\n\r\nYou Can beat him to death', 'Trash game, It''s not clear what needs to be done', 'Very Positive', 93.89, 2.80, 0.08);
INSERT INTO reviews VALUES (59393, 2435960, 232, 'The seemingly undefeatable soviet balloon at the end of the game is simply a metaphor for the eternal nature of war against communism, which will rage on for the rest of time.\n\nThis is a remarkable game-- one which can only truly be understood by brilliant philosophers. It is, by far, the best I''ve ever had the privilege of playing, and is quite possibly the best ever made.', 'It''s funny for like 2 seconds, but after that it''s just short and stupid. got it on sale but it should be free.', 'Overwhelmingly Positive', 95.26, 0.27, 0.88);
INSERT INTO reviews VALUES (59424, 2436570, 180, 'Dragon Quest Minecraft is a neat little spin off all about crafting and building towns for your little NPC buddies. There are monsters to slay but no level ups to be had. You''ll craft gear to stand a better chance against them and as you progress your town there will be defense events against groups of various monsters where some of your more capable NPCs will aid you.\n\nIt''s a fun game but quite repetitive as every time you clear an area you will move to a new one just to start all over again. F', 'It is such an amazing game with so much to do, so much to encounter, and a lot of fun to have-\r\nThat being said, whatever smooth-brained developer decided a item placement limitation was a smart move on a building sim, should probably reconsider their line of work, 16 hours into an intense playthrough, decorating, and building to specific measures, and when trying to put down some stairs "Item placement limitation reached" or somesuch message. I hadn''t even built 5 to 6 other room recipes yet. S', 'Overwhelmingly Positive', 95.00, 41.97, 26.52);
INSERT INTO reviews VALUES (59433, 2436940, 233, 'the game is fun, my only problem is when played with a controller i thought it would be, one stick moves the other aims twin stick shooter style but i was wrong, please make this a option as i feel it would be so much more fluent, much like the kbm gameplay', 'Nearly every part of this game is deeply flawed. The items are incredibly weak and the set bonuses range from bad to useless. You''re forced into taking useless items to increase your set bonuses. You increase the strength of your items via a Tetris inventory management system, using tablets that boost the level of nearby items. This means you often have to devote 5 inventory spaces to boost one item from 0 star trash to 5 star still useless. On average, you''re lucky if an item increases your pow', 'Overwhelmingly Positive', 96.14, 4.95, 28.27);
INSERT INTO reviews VALUES (59442, 2437170, 4588, 'The game is now in a state that is night and day different from the early closed alphas. Don''t listen to all the mindless doomers that spread misinformation. When it goes free to play, play the game and form an opinion on the current product. I see the game only getting better in the months to come and feel pretty confident if anyone plays this game with an open mind they will enjoy it.', 'Trying to make me purchase skins i paid for already? Thousand+ Dollar Smite account basically useless. Need blue gems for old skins? 500 skins total i get slapped with a fee to buy rewashed skins. Idk man i loved Smite but adding a number 2 and trying to double charge me is beyond aggravating. I would gladly pay for new skins but not old skins i already owned.', 'Mixed', 65.65, 882.22, 11.33);
INSERT INTO reviews VALUES (59462, 2437670, 131, 'Off to a good start. Hope to get AI squad members like the old Delta Force for single player. Great retro shooter.', 'The game''s AI is garbage; they ALWAYS know where you are even at night and with silencers.\n\nDon''t bother until they fix this.', 'Very Positive', 85.50, 1.18, 1.02);
INSERT INTO reviews VALUES (59513, 2438680, 269, 'Most deffinitely. However please go in this new adventure that this aerial city builder is, with the correct mindset. When quests are pending, do ONLY WHAT IS ASKED OF YOU, NO MORE. You ''ll ruin the game if you do. For example, you need to destroy a pirate outpost. En route there you spot a prison so you destroy it. You get nothing out of it, because the next quest you ''d be getting would be a "break ''em out of jail" mission. This would have given you something. Now you ''ll get nothing. Not even', 'I was eagerly watching this game because I love survival games with mobile bases. \nThis game right now is so friggin badly tuned.  As soon as I hit 30 pop, everything immediately went downhill. Works constantly got sick, at ridiculous rates. I had to wait for my weaver to craft 10 cloth, which took a full in game day, slowing down even more because I had to juggle workers between manning and unmanning stations because I had 17/30 population infirm.  Pirates attack every couple of hours, like jus', 'Very Positive', 90.33, 44.72, 1.35);
INSERT INTO reviews VALUES (59524, 2438990, 156, 'You want to play this game but you don''t want to teach anyone this game. Problem solved.', 'Ark Nova does not live up to the hype.\n\nIt disguises a very flat and uninspired game with layers upon layers of fluff.  So many tracks and resources to manage, but none of them are meaningfully distinct.  \n\nA more streamlined (and better) implementation is That''s So Clever, which itself is just a better version of Yahtzee.  And that''s the level of skill/interaction you should expect here, but with piles of unnecessary sludge layered on top to convince you there''s something more.  There isn''t.\n\nT', 'Very Positive', 91.03, 18.85, 5.45);
INSERT INTO reviews VALUES (59583, 2440200, 264, 'Let me say this, the gameplay aspect? 2/10. If you try and change the deck into a completely different one compared to the default deck, you are handicapping yourself. The default deck have, in my opinion, the best in terms of damage : mana ratio. Any other damaging card is a very mid card. This sucks as deck building game is more or less easy to balance.\n\nStory wise? 6/10. The MC is basically trying to bang a goddess. Kinda based but that''s beside the point. The story''s is a bit funny I guess? ', 'I don''t recommend this game. There''s barely any content. I took awhile before I decided to add my review but I feel like there''s too many people buying this thinking it''s a GOOD FULL FLESHED OUT GAME. The story is so small, short, and mediocre. It''s like a high school project where you have to create a story and apply basic interactive gameplay to it in a short time. Graphics feels like they used AI or poor use of it. Trying to make it like a live2D doesn''t make it any better. It''s very bare bon', 'Mostly Positive', 75.76, 18.07, 84.98);
INSERT INTO reviews VALUES (59592, 2440380, 1395, 'Game is good fun for the money but you wont get more than a few long runs of enjoyment out of it. It desperately needs meta progression. Unlockable classes, items, sets, etc. More monster variety as well could go a long way and even some actual bosses. Only buy if you want to enjoy a game for a day or two because in its current state it will just get repetitive fast', 'The game gets worse and worse with every update. it was pretty good at the beginning, but could''ve used a bit more variety in items but the Dev keeps changing what made it fun to begin with, removing things and nerfing aspects of the game that were really cool before.\r\nI''m all for increasing the difficulty but the changes made just removes the fun aspect of finding combinations and forces you into certain builds instead of giving you the opportunity to experiment.\r\n\r\nI held out for a while in ho', 'Mixed', 65.09, 14.93, 26.15);
INSERT INTO reviews VALUES (59596, 2440510, 4982, 'I feel like I''m in a parallel dimension, how is this game bashed so much? Maybe when it was released it was buggy and lacking content, but from what I see now (after the updates), this game just looks, sounds and plays great with plenty of content. I was reading comments of similar games like Automobilista 2 and Le mans ultimate, it ''s so surreal, I see all these positive comments, meanwhile those games come nowhere near the polish of Forza Motorsport. Those positive comments should have been di', 'Built from the ground up!\r\n\r\nThe ground being Motorsport 4 with a brand new option of selecting how much fuel is in the car before each session. But finally, there is a penalty system! As long as you like being penalized for other people running into you. Do you like arcade racers? NFS is a better arcade racer, or even Forza Horizon. Do you like sim racing? Assetto Corsa is a better simulation, or iRacing, or even RaceRoom which is free. Do you like rally racing? Well you''re shit outta luck, try', 'Mixed', 44.12, 46.93, 269.38);
INSERT INTO reviews VALUES (59623, 2441100, 104, 'This game is honestly the best! The devs did a great job and Mizkif is my favorite streamer!\n\n*remove this part when you''re leaving a review*', 'This game is too hard. I have no problem falling down sometimes but come on does it have to make me fall all the way to the bottom, every time. Also I need a new monitor.', 'Very Positive', 87.50, 0.87, 5.65);
INSERT INTO reviews VALUES (59634, 2441270, 1132, 'Not enough women go on bloody crusades of revenge against the criminals that wronged them. I''m glad the devs are taking the 1st steps in fixing society.\n\nFr tho, I don''t have an hour of game when writing this but I can already tell that it''s more than worth the already cheap price of admission. Props to the devs for the quick, simple and addicting gameplay + a fantastic artstyle and pixel animations!', 'If you sucks like me, this game isn''t for you\nI tried hours but did not made it through, and not for newbies.\nonly Normal or expert level, no entry level game\nIt was fun and looked easy when I watching Youtuber''s play, and when I play it wasn''t\nI should try Demo before I purchase, but I didn''t. Regret it.', 'Overwhelmingly Positive', 95.94, 3.98, 0.73);
INSERT INTO reviews VALUES (59650, 2441700, 1672, 'There''s a lot of good things I can say about Underdogs, from the art style, to the combat, and even dialogue.\r\n\r\nHowever, I''m particularly interested in how Underdogs addresses a core problem in physics-based VR games, specifically those with weight simulation like Boneworks & Bonelab; the disconnect between the player''s real body and their virtual body. (i.e. you''re waving around a near weightless controller effortlessly IRL while your character''s arms are having a seizure in-game because you''r', 'I don''t like the ghetto slang, the constant swearing and gangster rap music.', 'Overwhelmingly Positive', 97.91, 2.18, 0.30);
INSERT INTO reviews VALUES (59655, 2442020, 489, 'Dear Strong Bad,\r\n\r\nHow do you write a Steam review with boxing gloves on?\r\n\r\nCrapfully yours,\r\nKohara LaRue', 'Fun, but I beat the whole game in just over two hours. Not worth 7.99 or even the 4.99 I got it at. And I can''t even get a refund :(', 'Overwhelmingly Positive', 98.77, 3.10, 2.65);
INSERT INTO reviews VALUES (59671, 2442380, 227, 'Buy it so SNK get Code Mystics to port Neo Geo Battle Colosseum to modern platform with rollback and superior lobby', 'Censorship. \n\nI will never support shit like that.\n\nedit: \nGame itself is not censored, but the fact alone that they had to censor the artwork for the west, and tell us that they are very sorry that this game could offend people is reason alone for me to not support this release and give it a negative review.', 'Very Positive', 86.78, 4.88, 1.35);
INSERT INTO reviews VALUES (59674, 2442460, 1157, 'This game would''ve been perfect, but I had a little problem at the end of the game where I couldn''t see the screen because tears were streaming down my face.', 'Not as good as the first one. The first game had a lot of poignant stories about making the best of a bad situation and finding a new home. In this game you shuffle from crisis to crisis while a cartoonishly evil villain chases you. Meanwhile to the extent there are still some decent stories in here you''re prevented from fully enjoying them by having to grapple with the game''s annoying new stress mechanic. Who played the first game and thought "you know, this would be better if my die were break', 'Very Positive', 93.78, 13.38, 11.92);
INSERT INTO reviews VALUES (59706, 2443090, 111, 'The shared experience pool is a great feature. It makes playing with friends more cooperative and less competitive.', 'Dont buy this game.\nThe dev ran away like the bi''ches they are..\n\nDONT BUY IT\nthe game has not been updated seens August.', 'Mixed', 69.37, 3.33, 16.08);
INSERT INTO reviews VALUES (59719, 2443360, 949, '+custom engine with lower system requirements than the steam client\n+price of a takeaway sandwich\n+great level design, secrets\n+great movement\n+fresh takes on the standard fps weapons roster\n-i will never make anything this cool\n', 'It''s not a bad game, but it''s far more jank than 98% positive rating suggests.\nLevel design is messy, some ideas are neat, but everything severely lacks polish and isn''t tied together well, they don''t ''flow'' as in many other boomer shooters.\nBalancing is weird: enemies tend to hit like a truck, but you''ll be drowning in health items, so their only hope is to DPS you down in a really short span of time. Tons of ammo around every corner too, feels like it''s balanced around maximum enemy density. W', 'Overwhelmingly Positive', 97.89, 4.58, 0.97);
INSERT INTO reviews VALUES (59732, 2443630, 159, 'Dear Aspyr would you kindly please release\n\nStar Wars: Episode I – The Phantom Menace (video game) on steam\n\nand \n\nStar Wars Episode 3 Revenge of the Sith (video game) on steam', 'Ok so at its core this game has always been pretty bad, but it''s okay for a few hours of couch co-op I guess. \nThis is a port of the Dreamcast version (not PS1) so no destructable environments and less colorful lighting. Game is still super jank and filled with bugs. Combo inputs make you feel like you are lagging irl and you spend 50% of combat getting stunlocked by random stuff. Skill issue? Absolutely! Still feels awful tho.\n\nOh btw this is an Aspyr port so of course there are consistent game', 'Mostly Positive', 76.73, 0.57, 20.77);
INSERT INTO reviews VALUES (59741, 2443780, 232, 'Settlemoon is by all accounts, less a game and more a dynamic virtual terrarium.\n\nand that is EXACTLY why it works so well, do not get it twisted this is not the kinda game you sit and play for hours on end. in reality its a game you log onto, restock your little town, maybe move a couple things and keep stock of inventory and simply, let it do its own thing.\n\nif you don''t find gradual slow real time progress engaging? you sadly won''t magically enjoy SettleMoon. but if you DO you will be WELL aw', 'I want to like this game. It''s got great style and it''s got moths. Both of which I''m pretty fond of. But the gameplay is just.... bad. This fits into the niche of games that obfuscate how their gameplay works behind cryptic visual instructions and displays. That''s not necessarily a bad thing... but how this game does it is. There are mechanics throughout the game that I''ve played a majority of the game and still have no idea how they actually work or what they do, because the game doesn''t explai', 'Very Positive', 86.21, 26.93, 10.80);
INSERT INTO reviews VALUES (59767, 2444350, 135, 'ok', 'THIS IS CHEEKS BRO', 'Mostly Negative', 25.93, 7.72, 5.30);
INSERT INTO reviews VALUES (59814, 2445340, 163, 'i played for 3 hours without realizing i did not have the the r18 patch installed... well played developers, well played ;)', 'I simply don''t like visual novels. The way the protagonist describe the girls is just cringe. I spent half of the game rushing through the conversations, fishing and completing missions. The art is ok, and the animations look weird (mainly just image stretching) It is an ok game to purchase with discounts.', 'Very Positive', 92.02, 8.23, 7.92);
INSERT INTO reviews VALUES (59831, 2445690, 629, 'switch to english (it starts in chinese):\n\nhit 2nd button from top > hit the back arrow on the 3rd option , > hit esc > press the option on right\n\nthen do this again but change it back to english and everything will be in english\n\nez', 'It''s fun, but what happened to the couch co-op from the first one? I liked the first one because it gave me that nostalgic feeling from when I was a kid playing castle crashers with friends. :(', 'Very Positive', 90.14, 5.62, 21.70);
INSERT INTO reviews VALUES (59845, 2445990, 434, 'There''s so much to love about Bloomtown. Essentially, it plays like a Persona game (and the premise itself is very akin to Persona 4), but the world it inhabits is more like Earthbound. The setup is that of Gravity Falls, where two siblings are forced to spend the summer with their curmudgeonly elderly relative in a small town where weird, dangerous things are happening. And finally, there are thematic elements that line up with Stephen King''s IT, where horrific things are happening to the child', 'The story seems fun, but the combat is excruciatingly tedious. Most trash mobs heal, and your miss rate is incredibly high, making combat last forever, even when you''re using abilities to hit weaknesses and combo attacks. \n\nThe lack of a save option is a massive pain as well. Coupled with the combat system I can already see this game burning hours of my life just because the RNG in combat doesn''t go my way. \n\n', 'Very Positive', 87.10, 38.87, 3.88);
INSERT INTO reviews VALUES (59875, 2446550, 6177, 'Unfortunately, this game is super dead. It is sad to see because after a few updates it became a good remaster of the original. I am recommending this purely due to the single player modes. Otherwise, if you are buying this for online game play do not bother. All the servers are dead.', 'lock the price for this game at under 10 dollars. You guys have some balls releasing this broken piece of work at 35 dollars. Pure insanity', 'Mostly Negative', 21.05, 4.80, 0.87);
INSERT INTO reviews VALUES (59879, 2446600, 831, 'If you like Fire Emblem games, you''ll love this game. The sheer amount of possible customization in how you can build your team is incredible.', 'Slightly better than the predecessor, but overall really mediocre in comparison to other similar games in the genre, even for indie standards.\n\nThe story, the dialogue and the voice acting is really beyond cheesy, whoever wrote the story and the characters needs to be let go, I cant stress how bad it is, after a couple of chapters you will end up skipping everything.\n\nThe later half of the maps feel like an after-thought as if they ran out of time to properly make a map, the classes feel as if t', 'Very Positive', 94.10, 30.28, 34.52);
INSERT INTO reviews VALUES (59882, 2446680, 103, 'A short tragic story.\r\n\r\nI really enjoyed it, would recommend, there are no jumpscares for anyone wanting to know.', 'No. Too simple and too predictable. Didn''t impress me in anyway. It''s not bad it''s just absolutly mediocre.', 'Very Positive', 94.17, 0.48, 1.00);
INSERT INTO reviews VALUES (59968, 2448930, 494, 'This game is the equivalent of going downstairs to get a glass of water, but on your way to the kitchen you notice that your dog pissed on the carpet. You get the things to clean up the mess and once you''re done you also notice that your mail had arrived, so you go outside and grab your mail. Finally, you get back to your room, close the door, sit down, put your headphones on, and then realize you forgot to get your glass of water.', 'This is the type of game Yahtzee craves; a relaxing, chilling delivery game through space with you delivering shipments for other planets, learning about the story in the background all the while you have a podcast on in the background.\n\nI can''t say this kind of monotony was for me, and I''m still thumbs-downing it since I wouldn''t recommend it, but I''m glad it was made for a specific target audience instead of a mass-appeal game, even if it means I couldn''t get into it.', 'Very Positive', 88.06, 24.15, 0.98);
INSERT INTO reviews VALUES (59972, 2449040, 490, 'What a great and simple game!!! Love it ♥️', 'Meh. Decent concept but execution is a little off. Feels super repetitive even for this style of game. And quick to get that point too. Sure it''s only 5 bucks, but it''s just...bleh. Needs fleshing out and more variety in combat levels. This should be a free browser game. Not something you pay for.', 'Very Positive', 85.92, 10.38, 1.97);
INSERT INTO reviews VALUES (59991, 2449430, 148, 'The game feels a bit like Factorio in a spreadsheet. It has a relatively simple UI that at least currently changes more frequently and thus also improves acuh imho. At the moment I can''t recommend it to Linux users, but I think anyone who likes this kind of game will enjoy it.\n\nThis is a difficult review for me because with the current patch this no longer works properly on Linux (only with some rough bugs) but before that it ran and was a lot of fun for me and it is also in Early Access and the', 'Building is nice, in need of a bunch of improvements and bugfixes, but nice overall.\nHowever the "excavation" battle mode is just so bad and a permanent blocker that I can''t recommend this. You easily reach all research and guns you can have for your stage just to get stomped anyways. The only thing you can really build more by farming is walls, so all that''s left to do is fill your screen with walls and hope for the best. Sorry, but that just sucks.\n\nUpdate: Due to a broken patch that allowed m', 'Mixed', 69.59, 20.30, 11.02);
INSERT INTO reviews VALUES (60020, 2450120, 129, 'guys help me please, how can I delete this game from Recent activity???', 'If you watch the trailer, you have seen everything...', 'Mostly Positive', 72.09, 2.65, 0.95);
INSERT INTO reviews VALUES (60021, 2450130, 152, 'Short and simple, but good render and beautiful girls.', 'Horrible mini game, the scenes are terrible and timed. I lost multiple saves and broke the game several times by clicking to many menus open. This is a typical unity asset crap game.', 'Mixed', 66.45, 3.55, 0.73);
INSERT INTO reviews VALUES (60032, 2450400, 226, 'This is a relatively simple tactical game elevated mostly by the cute flavor — trash animals fighting over, well, trash. Nothing like your possum mom creating a bunch of babies who serve as turrets!\r\n\r\nThat is not to say the game is easy — you''ll have to think and plan your builds and actions. It just doesn''t have much variety. Still a decent installment for the genre.', 'no patch or communication from devs since September 2024, don''t buy unless it starts up again', 'Very Positive', 94.69, 16.38, 0.08);
INSERT INTO reviews VALUES (60036, 2450450, 345, 'Believe the other reviews with this one.\nYou got a really cool, really fun flashy Fantasy Mech anime hack n slash Action RPG bogged down by microtransactions and odd FTP mobile game gotcha mechanics that don''t really matter if you don''t play the competitive online multiplayer.\n\nGet it on sale if you can, stick to the story and resist the urge to spend money on it and you''ll have a pretty alright time worthy of 30 bucks.', 'Installs Epic game store services, even if its for cross play and anticheat. can''t remove them without doing a hard drive wipe / system restore.', 'Very Positive', 84.06, 4.62, 0.27);
INSERT INTO reviews VALUES (60044, 2450700, 772, 'amazing game i have not played much yet but i love it the only thing that would make it even better if it would have multiplayer so i can make drugs for junkies with friends :) give this a like if you agree let this be seen', 'It was fun till it got repetitive. Then there were no new updates. :(', 'Very Positive', 80.57, 35.83, 4.95);
INSERT INTO reviews VALUES (60048, 2450820, 107, 'I played this game in sega saturn since I was a kid. I would say this is one of the best in this category, but the pc version now has a bug when launching the game - after launching the game once (or a few times more), you will receive an error when launching the game. I hope this could be fixed asap.', 'Good game, not a great port. Only supports 720p internal resolution: This needs to be fixed. I''ve read in the steam forums that AMD GPU users are having problems with the game as well. This needs a patch LiveWire.', 'Very Positive', 90.65, 1.38, 0.33);
INSERT INTO reviews VALUES (60139, 2452920, 136, 'Great puzzle game.', 'The concept for this game is very original, which is rare. What is not rare is the cowardly level design that never forces the player to infer any principle outside of an implicit tutorial level. The complexity ceiling is also quite low, and the endgame puzzles are just as trivial as the midgame ones. While the concept is initially intimidating, the resulting game is under-stimulating. It''s not awful, but don''t expect a brain buster.\r\n\r\n6/10', 'Overwhelmingly Positive', 96.32, 0.63, 3.18);
INSERT INTO reviews VALUES (60142, 2453060, 397, 'I misunderstood the core concept of this game before buying it.  From my little experience playing it, you are simply walking around and exploring.  This is not what I expected, so I was not happy with it and have requested a refund.  \n\nHowever, if this was the type of game that interested me, and it is the type of game that interests you, I think you will be very happy with the wandering around and discovering the seemingly random locations within the levels.  This is why I marked it as Recomme', 'perfect imagination of the backrooms, non stop loops with some music you will always follow but never find. truly hell, i keep following the music but i can never find where its coming from and since there is barely any info on the game i''m hearing hallucinations of the music playing and my mind is breaking apart like i''m truly in the backrooms. and idk but i keep playing it my mind is like a broken record now it keeps playing and playing, if you are seeing this pls do not play if you want to ke', 'Very Positive', 87.66, 0.72, 8.02);
INSERT INTO reviews VALUES (60214, 2454570, 308, 'I typically do not write reviews unless the product is so bad I need to warn other users to stay away. This game is the exception. When you find yourself tearing up because the writing is phenomenal I realized that this was a hidden gem, especially in this games genre. Yes it is an "adult" game with explicit scenes. Yes there are some cheesy "plot" moments. However, overall the story/writing is amazing. The relationships between the protagonist''s BFF his Ex his current GF and his potential new p', 'A game catered to the male gaze.', 'Overwhelmingly Positive', 95.13, 78.15, 24.02);
INSERT INTO reviews VALUES (60224, 2454890, 392, 'Fun asymmetrical co-op game.  It''s sort of like if staff at an SCP facility had to play ''Keep Talking and Nobody Explodes'' to stay alive.  Lore for the lore hounds too.', 'the only thing scary about this game is its performance lmao', 'Overwhelmingly Positive', 97.19, 9.22, 1.18);
INSERT INTO reviews VALUES (60262, 2455640, 736, 'So I recommend this game with the caveat that it is VERY apparent that it is a remake of a very old game. By that I mean, the story is relatively barebones, there''s an ass ton of combat (probably around 80% of the game), and the characters are all (mostly) without personality and just randomly generated. Don''t expect a gripping narrative or endless variety, this is a very straightforward game and if you don''t like turn based combat stay away. \n\nBUT. It is incredibly unique and has a very clear a', 'I didn''t think much of it when I first bought it, but the DRM of this game is insulting. You need an Online Connection to authenticate the game... Every. Single. Launch.\n\nSo if you''re Internet''s out? Tough shit, go play something else.\n\nA shame, because the game itself is quite good, but I can''t play it at the one time I''d very much like to.', 'Very Positive', 90.76, 37.98, 34.87);
INSERT INTO reviews VALUES (60278, 2455920, 305, 'This game is basically like one of those little booklets of logic puzzles you''d pick up in a newsagent. If you like that sort of thing like I do, you''ll like this game.\r\n\r\nIt''s a very inventive mechanic for the puzzle, and I really enjoyed it. At time of writing I''ve solved each dungeon type at least once, so I''ve done both of the "main" objectives, but I doubt I''ll really be done with the game for a long time because I''ll come back and play again whenever I fancy a logic puzzle.\r\n\r\nI''m also tem', 'This game is stupid. You can have two or more separate logical answers that put the mimics in different places. Why make a logic puzzle where logic brings you to a dead end? A good idea executed poorly.', 'Overwhelmingly Positive', 98.36, 22.95, 1.13);
INSERT INTO reviews VALUES (60304, 2456350, 218, 'I have finished the Early Access content. Here are some of my thoughts:\r\n\r\n1. The storyline is quite engaging and interesting, but predictable (and the predictability here is a strength). It’s engaging and interesting because the story is told through "short ghost stories on the radio," from the perspectives of various characters. The "predictability" comes from the fact that after carefully listening to the short stories on the radio, I was almost able to piece together the complete narrative. ', 'du ma may', 'Very Positive', 94.95, 10.87, 2.33);
INSERT INTO reviews VALUES (60317, 2456740, 9076, 'I met a girl in the park. We joked, we hugged, we were engaged within an hour of our first date and then I got a text while I was asleep informing me that she died. 10/10 No Notes.', 'Buy two copies of Schedule 1, if you want to have a good time.\n\nEdit: Until this game updates it''s ToS and Offline abilities It''s not worth the 40 currently.', 'Very Positive', 81.69, 24.63, 1.93);
INSERT INTO reviews VALUES (60323, 2456960, 275, 'Very good. I didn''t play the original, but I had a lot of fun. Even though the game has a horror theme, it’s not scary and doesn’t have jump scares. (Although the doll room gives me chills, lol.)\nThe graphics are really nice, and I didn’t encounter any bugs like many complained about. I played on the Quest 3', ' I was really looking forward to this game because it is one of those rare games where it isn''t all about running around shooting your enemies . But I was disappointed.  Yes, some of the puzzles are fun to play.  But others made no sense  what so ever. I used a lot of hints and skipped some, even with using a walk through. I did like the story line and the graphics were decent. I would rate this game 4 stars.', 'Very Positive', 93.82, 9.15, 19.67);
INSERT INTO reviews VALUES (60333, 2457220, 7400, 'Someday the rage tourists will run out of games to play and settle themselves on finance bro podcasts for the bulk of their entertainment, and we shall be free of their blight.\n\nUntil then, thanks for the game endorsements!\n\nAlso you don''t have to choose they/them pronouns or fungal stuff for your character if you don''t want to. It literally does not impact the gameplay in any way.', 'This game is OK. i don''t feel like people understand it''s a 70 dollar game when they defend it. The world is empty, NPCs don''t move, you can''t interact with anything unless it''s predetermined. For 20 dollars? Yes. For 70? Absolutely not.', 'Mostly Positive', 78.72, 30.33, 1.15);
INSERT INTO reviews VALUES (60342, 2457540, 237, 'This game definitely has a ton more cards compared to the last game, just from browsing through the in-game shop. The price is steep yes, but since a real life deck can easily cost double the price of this game, I feel like it''s not so bad for multiple hours of entertainment. \n\nOne thing that really stands out to me that I hope they fix is the English translation. Not even ten minutes into the game, and the tutorial has misspelled the word Vanguard... it''s in the title of the game. A lot of the ', 'I genuinely enjoy this series and find it incredibly fun. However, Bushiroad’s approach feels overly greedy. The game itself is poorly optimized, riddled with glitches, and prone to frequent crashes. At its current state, it simply isn’t worth the $70 price tag. If you''re looking for a game with similar graphical fidelity, you’d be better off playing the Yu-Gi-Oh! titles released on the GBA. If you don’t have access to Cardfight!! Vanguard in person, I’d recommend waiting for a sale before consi', 'Mostly Positive', 72.15, 1.82, 14.43);
INSERT INTO reviews VALUES (60367, 2458210, 345, 'After completing the game 100%—yes, I got all the cards for all three characters—I can say the game has an ok rewarding system. After defeating the bosses, you''re treated to a spicy cutscene, and let me tell you, the cutscenes are definitely worth it. However, getting every card for every character is quite the grind, and unfortunately, there’s no major reward for doing so. It would have been great if they added a special cutscene featuring the tentacles or each boss. They could release new cont', 'There are just too few H scenes for me to give a good review for its asking price because there are games that were only $5 that had more scenes', 'Very Positive', 85.22, 34.42, 3.30);
INSERT INTO reviews VALUES (60374, 2458310, 282, 'It''s a Steampunk RPG.                                                                 \n\n... what?  You need more?  It''s a GOOD steampunk RPG.  \n\nYes, it''s technically creaky (it''s called early access), the voice acting is hit or miss, the game loves its fetch quests, however: the world building is top tier, the visuals fantastic, the combat lots of fun, the story is great and the companions lovely.  More importantly, for all the jank, the game is full of heart and originality.  In a RPG world do', 'Probably, but not yet. It''s under-cooked. Story is interesting, world is compelling. But the game, fights against you. \n\nWorking in your inventory is an exercise in frustration. Single click here, but the next time you might need to double. To move something - sometimes you single click, sometimes you drag. To drop or equip something - rest assured, once you achieve this feat, the mechanics will change on you. Splitting, moving, equipping, dragging, buying just 1 - just kill me already, finish t', 'Mostly Positive', 79.79, 5.50, 4.42);
INSERT INTO reviews VALUES (60383, 2458560, 1061, 'im enjoying this game, but it clearly has lack of testing / very different from the trailers\npretty repetitive with the tasks and a lack of mutants, not really a horror game and more of a shooter with tasks to do', 'These are the devs behind Sparky Marky. The trailers are not like the game and its like nne of the devs tested it. Buggy, constantly getting softlocked and you can''t do anything till you finished ONE enclosure. Save you the 25 dollars cause this game is not worth it.', 'Mixed', 59.19, 4.33, 1.58);
INSERT INTO reviews VALUES (60391, 2458830, 527, 'It''s Castle Crashers with deeper classes and Diablo loot.\n\nIt''s a good time. Maybe not "forever game" levels of fun, but great to vibe with for a bit', 'PLEASE READ THE EARLY ACCESS NOTES, when the game launches into 1.0 there will be a full wipe that undoes all your progress and it''ll switch to a f2p model with paid quality of life which is something I find very untrustworthy, when it comes out I might change this review to positive depending on how that goes, but I don''t trust it one bit', 'Mostly Positive', 79.32, 148.87, 1.37);
INSERT INTO reviews VALUES (60394, 2458940, 174, 'Farm Keeper is a nice managment game with some cutes pixels designs and a cozy ambient. For his low price, I recommend it!!! 🐰💗', 'A little too random.  Suddenly you need two rocks to win, and it will never give them to you.  There''s no control at all. Let me break my wells or something to get those rocks back.', 'Very Positive', 94.25, 10.13, 1.90);
INSERT INTO reviews VALUES (60409, 2459350, 141, ' I swear, i''m only playing this for the   achievements ', 'I would NOT recommend this to anyone decent. The Gay crap has to stop. I am straight. I will NOT play a game that requires a gay scene. Enough of the woke garbage.', 'Mostly Positive', 76.60, 16.17, 3.22);
INSERT INTO reviews VALUES (60420, 2459550, 1795, 'Got this game after watching Fauna playing it. Pretty good game I must say, although there''s not a lot of content yet, and some towers might do with a buff or two, maybe a few more hours and those seemingly under-powered towers may shine.', 'I used to be a fan of this game in the demo. The concept of a mazebuilding towerdefense deckbuilder roguelite is very cool.\nYou used to be able to manipulate the draw of your deck by holding on to your other cards. In the early access release however, your deck is endless. Akin to casino blackjack, you have multiple decks so you can no longer manipulate your draw. The game used to favor a small deck so that your hand doesn''t get full, but now it doesn''t matter. You can draw and draw and draw, an', 'Overwhelmingly Positive', 97.38, 26.52, 5.25);
INSERT INTO reviews VALUES (60424, 2459750, 193, 'i love it when john sunshine slay the numazu spire', 'it''s a fun game but wtf are those DLC prices? yea let me burn 10 dollars to make yohane a duck', 'Very Positive', 91.71, 83.97, 25.18);
INSERT INTO reviews VALUES (60471, 2460920, 119, 'Fun little game with a lot of potential, but man it''s frantic.  You can''t let your guard down for a second or everything dries up and dies on you.  There''s some automation but it''s finicky and getting a field up and planted, weeded, watered, fertilized is a manual process that just wears you out.  I believe it''s a solo dev, so kudos to him for this, but it needs a lot of QOL polish.\n\nLot of potential here so keep an eye on it.  Otherwise, get it on sale.', 'No possibilities to automate\nTo much grinding\nEasy to be "softlocked"\n\nHave a good potential, but its not there... yet.', 'Very Positive', 84.87, 26.88, 10.22);
INSERT INTO reviews VALUES (60498, 2461430, 185, 'You play as a young man who gets a new job as a personal assistant for a wealthy family. You will meet family members and see how this new job will change your whole life.\r\n\r\nThe game works on the principle of decision-making in given situations and offers you the opportunity to be the good guy or the bad guy.\r\nAchievements are also set according to this, so for hunters I recommend playing according to the guide, thanks to which you know how to make decisions and where to save the game, that way', 'Was playing season 1 again to refresh before season 2 and the game now freezes in multiple spots. Cannot progress the story past a certain point. If the devs fix the bugs I would recommend it but until then, why pay for what you can''t play?', 'Very Positive', 91.35, 3.72, 29.88);
INSERT INTO reviews VALUES (60518, 2461850, 3520, 'I don''t think I ever mentally recovered from using headphones on the first game.\r\n\r\nI was really excited to come back to this world, however, I think linear story games are in the past for me. I can''t find myself getting locked in or wanting to play more. If you are looking for an amazing experience that follows a tight story, try it out. The audio with headphones will make you feel crazy. But if you like story games with freedom to explore and do side quests, etc., this may not be the game for ', 'This game is honestly a disgrace after the first one. It is one thing, if the writers can''t get to the same level as they did before, but the story contradicts itself constantly. One of the biggest parts of the first game is leaving it open if the supernatural exists or it is all in Senuas head. This game shuts the door on this debate, just forgets to take its hand out of the way first... People see the giants, they throw spears at them, die by their hands... the moment there is an outsider inte', 'Very Positive', 84.77, 2.92, 9.23);
INSERT INTO reviews VALUES (60546, 2462520, 237, 'Super glad to notice that, this time, the game seems to be complete at the time of release. Includes both normal and hard modes right away, and even normal levels feel challenging. Thanks Notovia, I know what I''ll be doing on my long weekend off!', 'Changing the game so that you have to select the correct type of report changes this from a semi-spooky fun game to dying because you''re doing the wrong type of reporting. I know some streamers found the previous installations too easy and wanted things to be harder, but if that''s the case a mode should have been added where you can simply report anomalies. At the very least having that many different reporting options is unnecessary and it takes away from the fun. I wish I had refunded.', 'Overwhelmingly Positive', 96.62, 25.40, 2.07);
INSERT INTO reviews VALUES (60605, 2463800, 101, 'This game, made by a small mobile game compay called Gameduchy, released a day later than Bleach: Rebirth of Souls, a Bandai Namco published game for one of the world''s best ever selling manga/animes. One of those games has rollback, working ranked/casual lobbies, polished gameplay, and field tested quality of life performance. And the other one is the game with Bandai Namco''s logo on it.', 'Modern fighting game design syndrome, seems cool in training mode, then you take it out of it and all the cool stuff is on 50 year cooldowns', 'Very Positive', 89.11, 38.58, 17.00);
INSERT INTO reviews VALUES (60615, 2464090, 133, 'Pretty nice Hidden Cats game, I really liked the idea of having every characters speaking and the various hidden achievements. As usual, my mind keeps wandering off so don''t take in account the time I took to finish this game as being accurate.', 'A bit boring, and every single cat has something to say, and takes its time to say it, that gets somewhat tedious after 100 cats. Dumb achievements, one of which makes you reset the game for a "full" complete game. That ends up artificially increasing the game length. Not recommended.', 'Overwhelmingly Positive', 98.50, 1.30, 1.20);
INSERT INTO reviews VALUES (60628, 2464460, 129, 'I started playing Portal Fantasy and it’s SO GOOD 😍\r\nit’s like Pokémon + Zelda + cute pixel vibes all in one.\r\nyou collect these creatures called Porbles and can fuse them to evolve + customize, and battles actually need strategy?? their passives work together so team building is super fun, also the world is beautiful, full of secrets and quirky characters. and the puzzles. Actually clever, not just random busywork.\r\n\r\nhighly recommend if you like creature collecting, turn-based combat, and cozy', 'this game has become dodgy AF sets off my anti virus every time i start it. It forces open a network connection for "Verification" reasons and when I close then game it never stops running unless I reboot the computer. way to may red flags for me. the demo didn''t do any of this stuff.', 'Mostly Positive', 72.87, 7.73, 2.70);
INSERT INTO reviews VALUES (60635, 2464530, 376, 'AAA is dead, dude. Stuff like this, Witchfire, Selaco, and SULFER and all I ever want and need, ever again. THANK YOU DEV', 'This is a great demo.  Unfortunately that''s all it is at this point.  A $26.00 demo.  4 hours on played, and at least an hour was running around the only two levels available trying to figure out how to unlock the 3rd level to realise that was it. \n\nThe game play, fighting, graphics are all really good though.  Only reason it''s a negative review is it''s a $26.00 demo of what can be.  A lot of indie games die in the "it has potential" stage, and I hope this isn''t one of them.   I''ll easily change', 'Overwhelmingly Positive', 95.48, 4.07, 3.85);
INSERT INTO reviews VALUES (60651, 2464880, 434, 'i put old men in a box and they wont stop reproducing help', 'I don''t think I would recommend this game.\nIt''s not that the game isn''t complex, but it doesn''t feel like you are playing for any particular purpose. Like, you don''t unlock anything, there''s no story or anything. It''s just a game that you play until your strategy fizzles out, and then if you still feel like it, start again.\n\nI just got to turn 240, and rather than feeling elated for getting so far, I feel glad that it''s over because it dragged. I could start again and try to get further, but why', 'Very Positive', 86.64, 29.80, 12.45);
INSERT INTO reviews VALUES (60729, 2467300, 115, 'where deer sex?', 'The deer-hunter game where you’ll spend more time waiting for players than actually playing. With empty servers and no single-player mode, all you get is a lonely forest to explore and a empty lobby. 🦌💨\r\n\r\nFollow my curator page for more "games" that only exist in the lobby! 🎮🦌\r\nhttps://store.steampowered.com/curator/42602807-Osiris-Reviews/', 'Mostly Positive', 71.30, 16.58, 0.20);
INSERT INTO reviews VALUES (60749, 2467810, 232, 'Game is great!!! Dont listen to some minor negative reviews LOL I mean one of those was saying that for the price and content don''t match..... Dude literally was playing the free early access demo!!!! Another was complaining about picking up the whole boar instead of getting just meat from it.... Dude maybe unlock the spit roaster that the boar goes on. People need to stop doing reviews if they cant even play the games right', 'A bit too simplistic for the price.  No end-game and it becomes a bit of grind for the last upgrade level.  Combat is poor.  Enemies seem to spawn right next to you, undetectable until you start taking damage.\r\n\r\nFinished the game and have no desire to start a fresh game.', 'Very Positive', 83.62, 10.75, 168.00);
INSERT INTO reviews VALUES (60766, 2468100, 337, 'Their previous game, Forward Escape the Fold was just excellent. I had the chance of trying Pyrene''s demo a little while ago and it seemed to be a really good improvement. It''s exactly my type of game and I''m happy to report that it plays very well and seems to have tons of content. Gotta catch back to where I was in the demo but I just want more of it.', 'The game was pretty mid. The campaign is short and after that it offers nothing but a couple of challenge modes. There isn''t really any deck building, as you just get a handful of cards throughout the run and you just choose the strongest ones, no matter what "strategy" you''re going for (there are no strategies, just overpowered legendaries and 2-card combos) and your success depends on getting an overpowered legendary or 2-card combo early.\n\nI also massively disliked the survival aspect after y', 'Very Positive', 90.80, 1.82, 17.20);
INSERT INTO reviews VALUES (60809, 2469200, 267, 'The game currently has a fair bit of jank. Not as pervasive or game ending as a lot of the negative reviews give it. The main problem they seem to be having is that the Level 1 early game is rough. Stamina is very low, along with health and ''tools'' to use in combat. However, once you follow through the tutorials (which I recommend to follow through until you get to the end of upgrading your tribe), the game begins to expand out more. The "core" of gameplay is locked behind the skill tree, but ea', 'Game may be decent after some further development however the optimisation currently is pretty bad. My main reason for not recommending to play right now is the fact that the game is early access but nowhere is it advertised you only get to play a small portion of the game. It feels a bit cheap to ask for a £22 price tag and tell us you only get the starting area once you log in. Its understandable the full game isn''t completed (its early access after all) but you''re basically paying for a demo ', 'Mixed', 64.04, 17.23, 0.17);
INSERT INTO reviews VALUES (60851, 2470300, 283, 'Time to blend flavors and change lives', 'It pains me to give this a negative review. I was looking forward to this for a long time solely because of the pixel art. It looked so crisp and clean from the screenshots but no matter the resolution, it''s blurry and scaled incorrectly in-game. If you don''t care about that sort of thing, it''s a comfy time but as someone who really appreciates the time and effort that goes into the presentation of pixel art games like this, it''s very bothersome.', 'Overwhelmingly Positive', 96.11, 5.85, 0.68);
INSERT INTO reviews VALUES (60998, 2473480, 383, 'There is no reason to not like this if you are a fan of the first game. It''s bigger, better, and has so much more depth in its gameplay mechanics.', 'Completed on medium difficulty.\nPositive impressions changed to negative ones quite quickly, when you realize that this is a reskin of the first game and nothing more. It feels like the second game is smaller in content than the first. A complete lack of any innovations, both in the plot and in the gameplay. If you played the first part, then just replace the frogs with bats and you know what the game iis about. Little has changed in terms of gameplay. They replaced  extra damage to races with d', 'Very Positive', 84.07, 7.17, 10.23);
INSERT INTO reviews VALUES (61009, 2473710, 125, 'A casual puzzler for the cultured man, with a main character superior in design to the average multi-hundred million dollar effort of today. It''s a quirky game likely made with off-the-shelf assets, but there''s genuine intention and a certain amount of spirit here. Setting/premise is interesting, if nebulous. One of those odd little titles where if you''re drawn to the initial impression, you''ll probably like it well enough in spite of its flaws. Plays in Proton but has crashed a few times. This ', 'My main complaint with the game and games similar to this is all of the good cosmetics are only unlocked at the end of the game as part of the post game content.\n\nBut why on earth would i want to edit the main character to walk around a room, you can''t replay the levels as you know all the solutions so there is little point.\n\n You are going to spend 80% of the time playing through the main levels so that is when i want to change the looks, not when i have completed the game and ready to uninstal', 'Very Positive', 88.80, 8.32, 4.82);
INSERT INTO reviews VALUES (61018, 2473890, 344, 'Life changing experience. So very emotional on all fronts.  If you like dinosaurs and can handle a complicated story structure, my guess is you''ll enjoy this.  10/10', 'This is based off of 81 min. in  \nThe game is nothing like the trailer, no nudity, and no s-scene animations \nThe character creation in the beginning is ridiculous, it ask for genital types but she has a skirt on  , no manual save and no auto-play\nit would say that she is naked on the bed but shows a black background  \nI really wanted to like this game, the trailer looks fun, looks great, but the game is nothing like it \nIt has no self voice acting, no AI voice option, but it has moans, grunts, ', 'Overwhelmingly Positive', 98.26, 0.33, 1.35);
INSERT INTO reviews VALUES (61024, 2474030, 179, 'As you wander through foggy streets and explore a haunted mansion, it begins to feel less like solving a simple puzzle and more like experiencing an epic infused with psychological horror.', 'A mostly solid first 2/3 with a final act that is 90% cut-scenes and a finale that is unbelievably disappointing. The juice was not worth the squeeze. \r\n\r\nRiddled with modernist anachronisms that ruin any sense of time or place -- but if you''re one of those ideologues who can''t bear the past unless it''s rewritten to mirror your own current beliefs, it might be for you. People in this game think and act the way nobody thought or acted in the 1900s. It''s clear these people do no research or were s', 'Overwhelmingly Positive', 95.53, 7.07, 16.43);
INSERT INTO reviews VALUES (61086, 2475420, 313, 'I like this game because you are a car parking manager and you can upgrade your parking spaces, paint parking bays, and build lots of facilities including an underground car park. The maximum level is 8, and you can hire staff to help you."\n"The bugs I see in the game are:\n\nCars stacking on top of each other\nCars crashing into each other and getting stuck\nCars flying', 'DO NOT WASTE YOUR MONEY! The last MAJOR update was in 2023 these devs literally got it up and "stable" and just let it be. Yeah they released a "new" DLC but doesn''t fix anything with the game, if you play in a session long enough eventually traffic just stops and constant honking no matter what.', 'Mixed', 67.41, 46.97, 8.67);
INSERT INTO reviews VALUES (61090, 2475460, 106, 'A fun, wacky, physics based puzzler, with a good amount of content and a decent amount of fun to be had.\nWorth a try, especially if you play with friends.', 'Someone took Human fall flat and made it worse', 'Very Positive', 82.08, 5.45, 1.53);
INSERT INTO reviews VALUES (61092, 2475490, 20292, 'This feels like a trolley problem but there is no lever and there is no alternate track. you are simply watching a group of people suffer', 'I can''t fathom how this got to be Overwhelmingly Positive. Usually games with that rating are either extremely good, or good enough and extremely cheap. Mouthwashing is neither. Fairly decent writing and characters get you interested at the start of the game, but then devolve steadily into vague nonsense; tone-deaf, derivative "horror" sequences; wholesale abandonment of the themes that got you invested in the first place; and an ending that drags on about half an hour too long -- just enough to', 'Overwhelmingly Positive', 96.56, 1.77, 2.38);
INSERT INTO reviews VALUES (61157, 2477010, 459, 'There are a lot of people who are complaining because this is a rerelease, but this version is far superior in stability and support.   They are constantly adding new options and fixing bugs.   Graphics look is subjective, but I appreciate the optiopn to swap between newer graphics and more traditional graphics.', 'Purchased it originally and it was great.  Then it was decided to re-licence to a different software development and they produced this busy, less featured version that costs more.  No doubt in a couple of years they''ll re-licence again and expect me to buy a third copy.  Clearly it''s just to generate money and not to improve the game at all.', 'Mixed', 57.73, 23.27, 33.72);
INSERT INTO reviews VALUES (61162, 2477090, 1321, 'I bought this game on release and had a lot of fun. One year later, they add online coop unannounced--amazing, just stellar. One year later, they double the size of the game.\n\nI''m floored. There''s too much they''ve done for us for the measly asking price of the game. \n', 'Don''t be confused if you played this and found yourself endlessly infuriated. Even a game with tons of positive reviews can be subjectively bad. This definitely isn''t for me, and it isn''t for everyone. The concept was attractive, but the execution feels as if it genuinely hates you the whole time you play it. Not relaxing or enjoyable, not for me anyway.', 'Very Positive', 94.93, 12.65, 1.15);
INSERT INTO reviews VALUES (61166, 2477140, 152, 'A Doom mod with anime, cyberpunk vibes, lots of violence and kawaii? (Loads shotgun with malicious intent)', 'Game is per se fun, but the Level design is just horrible :( Way too confusing. Game loop is basically: You kill every enemy in your sight - you search 5 minutes for the hidden green door to continue. Repeat until you get to the end', 'Very Positive', 91.45, 2.68, 0.43);
INSERT INTO reviews VALUES (61175, 2477340, 1360, 'Despite a lot of SR enthusiasts have a lot to complain about this game, I found it pretty fun and enjoyable. There are no roads or any designated paths, your make your own and every step is a mini puzzle to be solved. It is clearly not SR, but fun in a different way.', 'A pure downgrade of Snowrunner/Mudrunner. It took the tedious parts of it, removed the open world aspect, made weird decisions about gameplay mechanics (for some weird reason they decided you can''t move multiple vehicles through gateways/tunnels) and released it. \nThe tasks and contracts all require different specialists, which means that you''ll have to start over and over and over again just to fit requirements for different tasks. \nYou''ll crawl through the same rocks for hours just to finish e', 'Mixed', 54.19, 115.97, 7.23);
INSERT INTO reviews VALUES (61249, 2478970, 2885, 'As someone who played Tomb Raider 2 growing up. The Remastered graphics here are... insanely well made.\nOther games doesnt always succeed or you just want to experience the original. Which i am sure new players want with any game. But i can say... they really nailed the remastered graphics in a way that makes this game look good.\n\n10/10 all the way! Play it!', 'I want to like this, I really do. When I was a kid Tomb Raider was near mystical for being an action puzzle style adventure game. I even enjoyed the Crystal Dynamic reboots even if they took Laura in a completely different direction with her story, the combat and puzzle solving just hit home. \n\nBUT I can''t get use to tank controls any longer and Modern controls are missing some key features that it seems are meant to be missing in order to drive you to learn tank controls, not just to allow you ', 'Very Positive', 89.08, 3.40, 9.67);
INSERT INTO reviews VALUES (61267, 2479290, 163, 'easy to beat - easy to play - has a hint of stress but easy to overcome - pretty realistic with pc repair tactics. Not exact but the structure is there. Can help you decide if you want to get into IT work or business.', 'Just another pump and dump, abandomware by  cheesecake devs! DO NOT BUY! They have done this a couple of times now, released a game just to abandon it couple of months after!', 'Mixed', 63.80, 34.80, 2.72);
INSERT INTO reviews VALUES (61269, 2479320, 562, 'This has become my #1 comfort game of all time. Everything makes sense and scratches an itch I didn''t know was there. To show my dedication I even collected a Golden Frame for each Frog- iykyk!\n\nLook past the wordy name (I just call it ''Frog Game'' because duh) and it being a late addition to a saturated genre (Bullet Heaven). What this brings to the table is worth working through all of your gripes for. It''s new, it''s fresh, it''s innovative, it''s confident, and nearly one hundred hours in, I can', 'Cool design with poor metaprogression.', 'Overwhelmingly Positive', 95.20, 109.32, 1.53);
INSERT INTO reviews VALUES (61294, 2479810, 37840, 'I came to this game despite the reviews I''ve seen and despite being solo. So far nothing of the bad reviews make any sense at the current state of the game and the player base is wholesome.. I m having tons of fun and the guys most of em being super helpful.. All I have to say is don''t listen to the reviews cuz most of em being before the updates that stabilized the performance. Just try it yourselves.. hope to see u in game.. much love guys.. also you will die.. a lot but that''s the point 🫡', 'Waiting 6 months on updates to do basic upgrades is far to long cant recommend something the devs aren''t serious about.', 'Mostly Positive', 70.18, 41.82, 103.85);
INSERT INTO reviews VALUES (61297, 2479840, 161, 'Chill game to play. more customization and this game could be better.', 'This game, and Pawn Simulator, are built on the same code base. This one has different graphics, but the code is exactly the same.', 'Very Positive', 82.61, 4.77, 0.55);
INSERT INTO reviews VALUES (61312, 2480200, 177, 'Some of the other reviews are bang on.  It would be nicer if there were some more choices and every woman that walked towards didn''t just drop their clothes.  Otherwise, I''m enjoying the game', 'The sex scenes are way way to short like each one is like not even 3 to 4 seconds and then you click to do the same thing again it just ruins it should of just made it one whole scene with out the need to click hopefully next one they do they will learn from this mistake.', 'Mostly Positive', 74.58, 3.05, 4.22);
INSERT INTO reviews VALUES (61320, 2480560, 100, 'Playing a game made by Jeff is like going over to your grandmother and grandfathers place for a weekend. You''re going to be relaxed, comfortable, and you''ll be well taken care of by people who care about you. Your meals will be made with love and care.\r\n\r\nWhen I''m depressed I turn to Spiderweb and everything feel like it''s going to be OK. I wish Jeff would give me a hug in a way that makes me seem like I''m not an insane Internet person.\r\n\r\nAnyway, yeah, recommend.', 'I really wanted to like this as it seemed super interesting and had a cool retro feel to it that brought back good memories. Everything was really cool but...\n\nThe inventory system was so terrible, all I was waiting to do was to get through the tutorial part so I could sell the vendor trash just to find out none of it sells. It was really bad before I found that out, now I see a game where playing will be second to hours of constant inventory management. No thanks.\n\nEdit: They won''t refund the g', 'Overwhelmingly Positive', 98.00, 102.23, 4.80);
INSERT INTO reviews VALUES (61340, 2481020, 521, 'Honestly? I wish I played this game during my Intro to Psych and Neuroscience. It probably would''ve been a bit better of a help in crystallising certain concepts for me than the lectures and readings.\n\nThe Camarilla needs to get their shit together.', 'I think I misunderstood what this game was when I bought it. I thought it it was a virtual novel with a touch of choose-your-own story, but it is more like you are taking a class on Cognitive Behavioral Therapy (CBT) skills with a cool teacher who set up the lessons as part of a story. From what I experienced, the story is interesting, the art is beautiful, the voice acting is excellent, and the education is woven into the story well. The analogy that keeps coming to mind is that it feels like w', 'Overwhelmingly Positive', 95.97, 10.25, 0.40);
INSERT INTO reviews VALUES (61399, 2482440, 663, 'Game offers a charming and engaging experience with its cute graphics and dual-character control. The ability to customize characters with various skins adds a personal touch to the game. The dual-character mechanic introduces a unique challenge that is enjoyable. However, the game’s single endless level can become monotonous, and the basic interface and visual effects are not very impressive. The lack of level variety may lead to a repetitive experience. Despite its potential and charm, the gam', 'I am a rhythm gamer. I play osu!, Stepmania, Thumper, and anything that moves fast and breaks brains. So imagine my surprise when a $0.99 ninja game made me feel clumsy.  My brain was like: “Easy!” My fingers: “Bro, what??”  I was gonna give this a thumbs down because there’s no leaderboard, no progression, no speedrun mode… But then I hit “restart” like 15 times and realized: I''m having fun. Dang it.  So yeah, not perfect. But still worth it. 😅‍', 'Very Positive', 93.97, 557.60, 0.33);
INSERT INTO reviews VALUES (61472, 2484130, 417, 'I love this game so far! Has a similar vibe to Slime Rancher, in my opinion.\nIt''s cozy and low-pressure compared to other cooking sims, which makes it very comfy to play. Everything feels tactile: picking up, moving, and throwing items, pressing buttons in the truck, picking fruit out of trees and bushes, moving appliances and decorations around your kitchen... It''s all very satisfying.\nThe game gives you a lot of freedom in setting up your kitchen and progressing through the game. There are no ', 'I loved this game so deeply id play it for hours strait but it soft locked because of the glitches and as i tried to fix them it just got worse. I wish this game was finishable to me but i just cant reccomend it if you completly can not play it after a few glitches. it truly is beautiful though and i will continue to support this company because i love their ideas and art. (sorry for the spelling errors i dont feel like fixing them)', 'Very Positive', 84.89, 5.57, 76.92);
INSERT INTO reviews VALUES (61524, 2485180, 345, 'I found cats and clicked on them, just as advertised 12/10', 'This game is the least enjoyable among the "Cats Hidden in xx" series. Normally, the art and the hidden cats blend well together, but for this one, it feels a bit rushed and chaotic. Rather than being relaxing, it was quite the opposite. If you want to start playing this series, I recommend beginning with "Cats Hidden in Paris," "Cats Hidden in Bali," or "Cats Hidden in Italy." at least these are what I personally tried and recommend.', 'Very Positive', 94.78, 3.33, 0.52);
INSERT INTO reviews VALUES (61526, 2485270, 207, 'Another great game! I loved the sex animations and story. Very engaging! But only one thing i didn''t like is there is no sex sound effects! Other than that its a good adult game!', 'Everything about the game looks top grade but then the animations have no sound??? Like why would you do that?? Without sound effects the sex scenes are just meh! Refund time, such a bad decision. Shame as the quality of game is otherwise pretty good. Example of an AVN that gets audio right would be "Innocence or Money" or "The Genesis Order"', 'Very Positive', 84.54, 20.47, 0.82);
INSERT INTO reviews VALUES (61587, 2486740, 2266, 'challenging but a lot oh fun i recommend a controller p.s it would be cool if the sled and rider got snowy', 'devs got lazy', 'Very Positive', 94.62, 23.82, 720.28);
INSERT INTO reviews VALUES (61597, 2487060, 214, 'It''s an interesting game with an interesting story, while I personally am a real cybersecurity specialist, I can say I appreciate the somehow closeness to the reality with the shell commands although simplifies syntax. I like how you can choose what to do and how much damage to do, I overall recommend it for those curious how a "hacker" world would kinda look like.\r\nThe game showcase different real named exploits and techniques both remote and physical while maintaining the simplicity of a game.', 'I didn''t find it very fun, and it had a rough and cheap feeling like many slapped together "simulator" games.', 'Very Positive', 80.84, 15.27, 0.75);
INSERT INTO reviews VALUES (61610, 2487350, 1647, 'The answer to 1984 is this video game. Please drop an update with full steam support (badges, achievements & points shop items). I want proof on my profile that I defeated the globalists.', 'I bought this game just for fun, but I soon realised it was not worth it. I wanted to have fun with all the ridiculous conspiracy theories, but I found out that this purchase supports the spreading of them. Sorry, not sorry.', 'Very Positive', 92.05, 1.02, 0.57);
INSERT INTO reviews VALUES (61649, 2488370, 1644, 'Shame on me. I love sorting, collecting and giving back money. But I am also autistic.', '"Not an automation game — in fact, it actively resists it."\nThe premise has potential, but once multiple currencies (Euro, Dollar, and their counterfeit variants) enter the mix, the experience becomes more of a cluttered micromanagement chore than a satisfying system.\nQoL features are minimal, and the Money Counter L only filters fake bills — it doesn’t help with currency sorting, which leads to messy, manual work.\nIf you’re hoping for incremental automation or progression-based streamlining, th', 'Very Positive', 89.05, 15.42, 35.32);
INSERT INTO reviews VALUES (61660, 2488510, 756, 'Fun game to play. Starts out a little tough and then gets easier over time. Unfortunately doesn''t have much of an endgame other than grinding with limited growth once everything is unlocke.\n\nUpdate: The game has released now and they added two characters and a map but not an endgame. There are like three hundred achievements but every one of them is just beat map x with class y on the highest difficulty. Runs take 20-30 minutes to complete and play out the exact same way every time, regardless o', 'By rule, any game that gets abandoned by devs within 6 months of release gets a negative review. There is too much missing from this game to recommend playing it. Other games are similar with better execution. This game started really well, excellent potential, but abandoning mid-development is so disappointing.', 'Mostly Positive', 73.94, 20.85, 65.03);
INSERT INTO reviews VALUES (61664, 2488590, 687, 'i close my eyes and seize it. i clench my fists and beat it. i light my torch and burn it. i am the wizard i worship', 'I''m going to agree with what another negative review said about combat and repeat it here myself.\n\nTo put it bluntly, it doesn''t feel good. It''s very frustrating. You can''t tell how far an enemy can attack, and it''s even harder to get a feel for how far your own attacks reach. My experience so far has been to run around spamming mouse clicks wondering how on earth my attacks aren''t connecting. Having to spam clicks is a bit annoying too.\n\nLove the visuals, love the lore and the setting, all of t', 'Overwhelmingly Positive', 95.49, 17.40, 5.27);
INSERT INTO reviews VALUES (61666, 2488620, 5637, 'This game is incredibly unrealistic. I''m able to win races with Scuderia Ferrari.\r\n\r\n10/10', 'Played for 70 hours, the My Team career save with 65 hours of practice/play time has been deleted without my consent and I have no way to get this back. This will be the last time I play an F1 game, congrats to EA for being one of the worst companies to ever exist. You are a disgrace to the gaming community.', 'Mostly Positive', 71.92, 275.87, 71.30);
INSERT INTO reviews VALUES (61727, 2489990, 126, 'sumakay ako sa jeepney\nikaw ang nakatabi\n‘di makapaniwala', 'Couldn''t get over the first customer, the other just wouldn''t leave the car after arriving at the point and even circling around for 5 minutes.\r\nGame could have at least a fun-bad potential if there would be some more work put into it.\r\nAlso I don''t understand leaving this game in early access and releasing the 2nd game while this one still barely works?', 'Very Positive', 92.86, 1.62, 0.78);
INSERT INTO reviews VALUES (61758, 2490790, 159, 'It''s pretty alright, maybe even good. Not abysmal, but not perfect either. A little pricey for its runtime, so if you''re planning on getting it, wait for a sale. 6.5/10', 'Actual cash-grab mascot horror slop that asks for money for ~30 minutes of gameplay.', 'Mixed', 66.04, 0.68, 0.90);
INSERT INTO reviews VALUES (61769, 2490990, 985, 'This feels like sitting in front of the SNES playing Mana in the 90s. The music. The colorful intro. The characters. Everything about it, is pure Mana. Child-like wonder and the power of friendship. I hope they port the other Mana games over to Steam. These games are instant buys. \nThere was one summer where every day, I''d ride my bike down to a friends house to play Secret of Mana with him. Furiously pedaling, hoping against hope that he didn''t progress the story any since the previous night. T', '          Sadly I beat the game....\r\n             Honestly, this is the WORST Mana game by FAR. The plot was concerning, like they tried to take a page from the Tales series but done poorly, They want you to care for one of the main characters family/village but failed HARD. The whole village was insufferable and I didn''t care if they all lived or died with how they acted. A lot of NPC''s are copy/pasted throughout the game, which would be fine if they were background characters with no name, but', 'Very Positive', 82.23, 23.22, 84.87);
INSERT INTO reviews VALUES (61796, 2491640, 331, 'Good fast twin stick shooting fun in a tubular wrapper. At these prices you need a snake farm of your own!\n\nThe central mechanic of ''investing'' in your snake farm to get more and more snakes and finish with a better high score is a great way of regulating difficulty according to the player and their own treshhold for reptilian mayhem.', 'maybe I need to play more, but this game is not fun; \n\nthe higher-tier snakes feel like too sudden of a spike in difficulty and you sacrifice in firepower in order to get the mobility needed to do anything about their special abilities.', 'Overwhelmingly Positive', 96.07, 5.10, 0.42);
INSERT INTO reviews VALUES (61817, 2492040, 785, 'Very fun game to play and spectate.\r\n\r\nOnly downside is including Ronaldo who is banned from EVO irl. For more info why he''s banned from EVO, google ''Ronaldo Las Vegas''\r\n', 'I waited a quarter of a century for a new Fatal Fury game only for established characters to get sidelined for street fighter characters, a real life dive grass player and some random dj that is friends with SNK''s current owners. Guest characters just come off as cheap marketing and makes it look like you don''t have faith in your own character, history or brand. \n\nMaybe I''ll pick the game up in a few years when the whole thing hits 75-80% off. The game could be the greatest fighting game every, ', 'Very Positive', 84.33, 25.97, 8.47);
INSERT INTO reviews VALUES (61822, 2492120, 147, 'I played Saeko through DLSite, so don''t worry about my playtime and achievements.\n\nSAEKO: Giantess Dating Sim isn''t a game for people who are already deep-in with a size fetish. It uses a giant woman as a backdrop to tell its story but does not linger to exist as a fetish game. It''s psychological horror. You spend time making moral choices in an environment that''s staged and shown to you as  truly hopeless and you''re forced to make decisions of who lives and who dies. \n\nThe artstyle and music ar', 'the main good things about this are the pixel art style, and the compositions. they''re very much in line with everything the game is going for, and are what made me play this all the way through. there''s a definite sense of vision with this game, and with more time i really do think this dev team could make something truly wonderful and moving down the line. however, there were so many glaring issues that i ran into while playing this, and they are sown into the foundational elements of this gam', 'Very Positive', 91.16, 1.02, 3.27);
INSERT INTO reviews VALUES (61835, 2492390, 207, 'unethical amount of puzzles, destroyed a month''s worth of my productivity', 'Crashes frequently on the Steam Deck, despite being verified. Shame, as it''s pretty good otherwise', 'Overwhelmingly Positive', 99.03, 82.12, 4.32);
INSERT INTO reviews VALUES (61927, 2494780, 252, 'This is an amazing game with so much in it, very much in the spirit of other great really indies, but READ THIS FIRST; If you have a controller make sure your ''Steering'' and ''Acceleration'' are both changed to ''LINEAR'' in the Options Menu! This is the sole issue with the steering and acceleration being ''off'' that some people are saying.', 'I just can''t recommend this one. Bottom line - this game just isn''t fun to play. The driving feels SO bad. Describing the handling as "arcadey" is being too generous, it''s essentially mobile game handling. I like the art style but that is just about the only redeeming quality of this game. Engine noise is terrible, co-driver calls turns too late to be useful, lot''s of minor bugs, menu navigation isn''t intuitive. The early cars are terrible to drive and the later cars are only a little better. Ov', 'Mostly Positive', 74.21, 14.33, 1.48);
INSERT INTO reviews VALUES (61943, 2495100, 3357, 'I don''t play World of Warcraft, I''m playing Hello Kitty Island Adventure\r\nIt''s cute, and pretty chill... there''s a lotta things to do and discover\r\n⭐⭐⭐⭐⭐\r\n', 'I think the game is fun!! But unfortunately it''s just a 10$ mobile game at a +30 dollar premium. Very fun!! But until they lower the price I cant say I''d recommend :/', 'Very Positive', 94.07, 52.02, 31.45);
INSERT INTO reviews VALUES (61959, 2495450, 475, 'making positive reviews for hentai games recommends them to your friends which ruins their steam store page with hentai games.', 'If you wanna whole experience you need download full version on their website. The Steam version first and second game are not full versions They need to update game.', 'Overwhelmingly Positive', 95.16, 6.43, 3.60);
INSERT INTO reviews VALUES (62008, 2496640, 137, 'Did you know that reviewing games puts them on your friends recommended page?\n7/10 IGN', 'Hey, wait a minute... This isn''t World of Warcraft...', 'Very Positive', 80.29, 0.58, 0.15);
INSERT INTO reviews VALUES (62046, 2497560, 142, 'You are in SKIBIDI TOILET HELL but luckily one of your TVman friends (being the goated sigma that he is) shows you how to stun the skiboilets, which allows you to kill them by flushing they gyatts. Up your rizz in this absolute banger of a game, collect all the toilet paper to pay your fanum tax, kill the skibiboss and flush all their skiboilet minions straight to ohio.', 'This should not be considered a horror game. All they did was put a hundred of the toilet ai everywhere and you just go running away from like 10 of them to collect toilet paper. That is what every level. It is not worth $5 or even the discount at $1.74.', 'Mostly Positive', 76.76, 4.67, 0.45);
INSERT INTO reviews VALUES (62058, 2497900, 1676, 'Liked the gameplay and the fact that the devs are trying something new! 5/5 jump scare simulator. \n\nLearnt something more about myself that I''m not a screamer though, takes the fun slightly away.\n\nWill find a screamer friend see if I leave another comment hehe.', 'this game is total crap and super cheap. Twice i''ve had a bear kill me when I was at 0:00, it completely kills any desire to finish this heap of garbage. dont waste yout money. the game is called dont scream not bear attack simulator', 'Mixed', 67.72, 1.38, 4.08);
INSERT INTO reviews VALUES (62060, 2497920, 2785, 'What more do you need? Working legs? No, that''s stupid. All you need is upper body strength. Your legs might as well be in a cauldron.', 'This game is terrible, wayyy too difficult', 'Very Positive', 89.73, 18.95, 0.63);
INSERT INTO reviews VALUES (62061, 2497930, 118, 'Models are good, really good, animations are also good quality and also the amount of lewd scenes at this stage of the game is plenty.\r\n\r\nStorywise, its not a great banger, but its a solid one, i would easily recommend this one.', 'Mostly a very boring game, way to much talking and come on a lawyer turned basically spy, get real. The story is just dumb. Wouldnt recommend unless you get it free. Oh and If you like choice games this isnt for you either, there a few for the first couple episodes but as they go on you get less and less and I think you only had like 2 choices the entire 6th episode.', 'Mostly Positive', 70.34, 4.93, 6.47);
INSERT INTO reviews VALUES (62085, 2498570, 340, '  I originally was like, eh idk if I should get it, and then I did and I don''t regret it. i''m not map-editor pilled, you can tell by the games I play, I''m a noob with creativity. I felt like this really snapped for me and really gave me an outlet. I feel like you can really get into the fine details of the map you build and the size of them is impressive. The dev seems like he cares, and its his passion project which is super cool. keep up he good work!\r\n  Id like to see more workshop items for ', 'Very much false advertising, shows to have quite a lot of assets to build with, It also shows that you can build towns and cities just by making regions drawn with your mouse, the best you get Is the Interior of a select few buildings that don''t add more when the building gets larger, It doesn''t fill the gaps.', 'Overwhelmingly Positive', 95.00, 45.30, 0.15);
INSERT INTO reviews VALUES (62122, 2499470, 628, 'Absolutely amazing game, probably the best simulator of this kind. I LOVE that you get to hire your first employee immediately and that you get to automate pretty much everything (apart from the lemonade stand i guess lol) with employees. Must buy game for simulation lovers. Hope the devs will make other similar games in the future, cause I am going to be buying all of them for sure !', 'There is no Arabic language', 'Very Positive', 93.95, 17.85, 15.45);
INSERT INTO reviews VALUES (62126, 2499520, 814, 'I play a lot of autobattlers and danmaku/bullet hell games, and I have to say: this is one of the best ones so far! There are cool units, the game is challenging but becomes "easier" with meta progression, and it even has funny dialogues. :)\nThe only thing missing is an endless mode where it keeps getting harder instead of ending after beating the boss — and of course, more units, more perks, and more meta progression would be awesome too.\nOtherwise, it''s a 9.5 out of 10 for me! This game defini', 'The game closes on you when you refuse to post a review, which is very annoying, so here''s your (negative) review. I would have recommended this game otherwise.\n\nNot much replay-ability once you win.\nPerma-upgrades are pretty limited right now.\n\nArt is nice, as is the voice acting.', 'Very Positive', 86.24, 3.83, 1.18);
INSERT INTO reviews VALUES (62142, 2499800, 724, 'A return to form for Banban. Character arc progression, storyline development, loose ends being tied up, it''s got it all!', 'Why do I continue my personal hell', 'Mostly Positive', 76.52, 2.40, 2.02);
INSERT INTO reviews VALUES (62185, 2500750, 226, 'Nobody will read this so I will do 10 push-ups for every like this gets.', 'This game is like 95% fine and then the rest is absolute garbage. And that garbage ruins it for me.\r\n\r\nIt''s not the fake objects place to troll me, or assets without collisions, or even the janky grabbing mechanics on some assets. It''s that you can climb for 45 minutes and be within sight of the end only to get caught in inescapable terrain and have to just... restart. Not even offered the inconvenience of being able to fall. Of course, it''s worse because you''re only in that terrain because you ', 'Mixed', 50.88, 0.22, 18.37);
INSERT INTO reviews VALUES (62202, 2501600, 1198, 'Diceomancer is to Slay the Spire as David Bowie is to the Beatles: it takes an incredible established style and pays homage to it while simultaneously elevating and expanding upon it.\r\n\r\nAcross all platforms I''ve spent 1000+ hours in StS, and even after only 10 hours, I''m pretty confident in saying that I think Diceomancer is more fun.\r\n\r\nDon''t get me wrong, StS is still incredible and you definitely should play it too. But what Diceomancer has achieved is something I didn''t think was possible: ', 'I feel kind of bad for giving this one a thumbs down because there''s a lot of good design work and great presentation here, but it''s also the ten billionth deckbuilder to copy ascensions from StS without really thinking them through and I just cannot fucking handle playing 19 tutorial/easy mode runs per class anymore. It is more tutorial than anyone needs.\r\n\r\nAnd you know, maybe this is unfair. Maybe there''s something clever that happens around ascension 15 or so. But I''ll never find out because', 'Overwhelmingly Positive', 96.49, 84.02, 15.60);
INSERT INTO reviews VALUES (62249, 2503220, 147, 'This is a really cool and fun little racing game. However, it is a FANTASTIC racing game in VR. \nThe game is so ferkin beautiful in VR that it really looks like it was made for VR from the ground up. The only thing that gives it away is  that the menus aren''t visible in the headset (just lift the visor between races, which in itself adds to the immersion, if you think about it). The other thing that shows its flat roots is that there is no cockpit view- Man, I would die for a cockpit view in thi', 'Is the game good? Yes, but the game will never leave Early Access, since the team moved on to another project, so if you wanna buy a good finished racing game, buy Circuit Superstars', 'Very Positive', 82.31, 1.93, 7.00);
INSERT INTO reviews VALUES (62273, 2503770, 220, 'Wow this is a SUPER unique game I did not expect a guild 3, with CK3 elements on top of the management mechanic. I really hope this game keep pushing updates and fixes crashes because this game is MEGA intresting. DEFEINTLY keeping an eye on this one. \n\nAt the time of this review I played a few more hours and the game does have use for all skills. Business, art, writing, might and cunning. Some are easier to understand than others, like for exampe business for trading, buying and selling.  Other', 'Not fully translated', 'Overwhelmingly Positive', 98.64, 6.88, 21.38);
INSERT INTO reviews VALUES (62340, 2505570, 366, 'Burger Shop 3 is PRECISELY what a sequel game should be: Similar enough to the previous game that there''s no learning curve at all, so the gamer can dive right on in; it retains everything that made the previous game excellent; and it adds enough new stuff that it doesn''t feel like a mere remake. The fun, the charming music, the playful humor, the cast of characters, and the well-paced keep-it-moving gameplay.........this is a perfect sequel in both spirit and fun! GoBit Games, a very heartfelt ', 'Played for 4 hours so far. The more I play, the worse the game gets. The challenge is way too hard even just on story mode. The recipes are too complex and then you''ve gotta answer phones, dogs, pack up orders....it''s too much! I understand challenge is necessary and even fun but there is a limit and this has gone way beyond that for me. Did they even play test this?', 'Overwhelmingly Positive', 98.36, 158.37, 5.53);
INSERT INTO reviews VALUES (62365, 2506160, 2249, 'What makes Fears to Fathom so special is how real it feels. It doesn’t rely on over-the-top horror or jump scares. it creeps in through the ordinary. Every story plays out like something you might’ve heard from a friend, or worse, experienced yourself. The characters, the pacing, the quiet moments of tension, they all feel unsettlingly human.\n\nIt’s about what people are capable of. And that’s what makes it terrifying.\n\nEven the routine moments, grabbing a drink from the fridge, answering a text,', 'This review is a little late, I was going to get Woodbury at some point but I realized the thing that turned me off from it is that a creative and fun horror series was ruined by the maker''s obvious piss fetish. Every. Single. Game. There is more and more disgusting pissing sequences and it''s repulsive. Way to ruin your games because you can''t control your nasty obsession.', 'Very Positive', 91.55, 3.33, 4.03);
INSERT INTO reviews VALUES (62380, 2506480, 193, 'I''m a fan of board games so being able to play online or with AIs at any time is nice', 'Yo. Why is everything so expensive. It''s like everything besides the 1 crime scene costs money. cool. I bought the game, now I gotta buy more things. greedy bastages. It''s a good game but dang', 'Very Positive', 91.19, 85.70, 15.75);
INSERT INTO reviews VALUES (62386, 2506580, 294, 'I found this game from a random video that popped up in my feed, and decided to get it. 11 hours later I''ve beating the main and dlc. This is a great game especially for one made by one person. Quackpond if you read this know that you should be proud for the game that you made.', 'The ammo pools are too low for most weapons to be fun. The ammo pickup system is frustrating. The levels don''t feel balanced for horde-style gameplay as even in the smallest maps with the lowest enemy counts you will find yourself scrounging for ammo - and of course enemy units (and allies) aren''t hemmed in by the same limitations.\r\n\r\nIt really is a shame because the story seems like a callback to Muv-Luv (Schwarzesmarken especially) and things like Blue Gender. I understand the imperative to ke', 'Overwhelmingly Positive', 96.94, 12.07, 1.92);
INSERT INTO reviews VALUES (62440, 2507980, 175, 'the game was great a few months ago but bordering on unplayable at the moment. frequent movement key locks is causing the player character to move to one direction and unable to traverse the stage. in tour mode, this situation becomes unbearable.', 'Grindy game with an over reliance on metaprogression, terrible boss fights with nearly unreadable attacks that almost always one shot you, and generally brain dead gameplay with next to no actual skill involved. It has potential but the more I play, the more I''m beginning to realize it''s unlikely to actually deliver on it.', 'Very Positive', 85.71, 239.42, 8.68);
INSERT INTO reviews VALUES (62552, 2510770, 255, 'Simply stunning and beautiful, a true 10/10. All the characters felt meaningful, all had a purpose. The art style was to my liking. If you like reading Visual Novels, this is a must read.', '(Your mileage may vary)\r\n\r\nPros:\r\n\r\n- The game is beautiful artistically, as befits a modern VN\r\n- The premise was interesting, but still not top-drawer sci-fi, though this is a novel scenario for Key\r\n- I very much rooted for Jude the Courier, this is a harsh world, and navigating it requires drastic actions\r\n- The ending is better thematically than going on with Willem''s plan, but see below\r\n\r\nCons:\r\n\r\n- Philia: remains unlikable to the end. I get that she needs to get some development, but st', 'Overwhelmingly Positive', 98.43, 6.83, 6.57);
INSERT INTO reviews VALUES (62557, 2510850, 157, 'The game is fun, the idea behind it is great. But some of the gameplay elements are a bit too frustrating. I understand that none of the upgrades are permanent, it''s a rogue-like after all, but it would be cool if the Minotaur wouldn''t appear right in the beginning and if there was a consistent way to stop the chase. Often times, enemies are also too strong for the current level.\n\nI also got stuck after an explosion threw me through the air. \n\nI''ll follow the development and hope that those aspe', 'alot of potential but movement and combat is a bit wonky', 'Very Positive', 92.99, 1.10, 0.12);
INSERT INTO reviews VALUES (62562, 2510960, 738, 'EDIT: They''ve patched out the caps. Games fun. it''ll get better over time too. go have fun.\n\nI read some other reviews seeing it had mixed rating and they mentioned capped skill trees. I thought nah it''s probably just typical steam reviews complaining about nothing. why cap the trees? it makes no sense. is it to force you to play as all tems? progress blockers for what purpose? it''s pretty egregious. I would possibly understand having some higher tier skills being locked out until more updates b', 'It''s a Pokemon themed Vampire Survivors clone with almost none of the depth of play or freedom of player expression. Impossibly curated and on-the-rails in a genre that is known for outrageous builds that can wipe the screen without you even moving.\n\nLets say you want to unlock a new character. That''s great. If you go into the menu, it doesn''t tell you how to unlock any of them. If you want to do that, you have to go into the convoluted and overlapping path of exile style web of bullshit to figu', 'Very Positive', 80.22, 10.08, 16.48);
INSERT INTO reviews VALUES (62591, 2511500, 1084, 'I''m an old guy and I was just thinking about something: the first D and D characters I ever played in the 80s were MUCH less detailed in their stats and info sheets than the basic troops of Dominions. that is FAR OUT , man!\n This game is a triumph of old school turn based wargaming cranked up to 11, then attached to some wonderful lore as well. I must confess, I have borrowed and stolen many bits of the lore for my own tabletop campaigns, that''s how highly I think of it. \nBe aware there''s sort o', 'In my opinion they ruined the magic system from dominions 5. Just keep playing that. They nerfed and they nerfed and they removed and put spells into a new magic called glamour.   I hate it.\n\nThe only quality of life I could find was auto search for magic sites. Still shitty controls, still no rebinding keys, the ui is worse. Something is wrong with these devs. The price is not worth it at all, Why the hell don;t you jsut make expansions to one game instead of Rearranging the same old ******* ga', 'Very Positive', 90.22, 475.77, 18.50);
INSERT INTO reviews VALUES (62620, 2512090, 202, 'This game would be way more fun if you could run as different political parties.  Not just independent, green, libertarian, etc... Let me revive the Whig party and make the entire country yellow', 'One step forward. Three Steps back. \n\nWhen you work in the political industry, it hurts to play games like this. \n\nI have been playing since the OG Political Machine in 2008. Somehow every time the game gets worse every 4 years. They add a much needed feature, then they remove some. Every Four Years.', 'Mostly Positive', 75.74, 17.27, 3.32);
INSERT INTO reviews VALUES (62623, 2512190, 147, 'Honestly, this is still a better ''Magic School Sim'' than Hogwarts Legacy', 'Takes too long to get to the content', 'Mostly Positive', 75.51, 2.35, 0.77);
INSERT INTO reviews VALUES (62624, 2512200, 126, 'awesome game! we definetly need a part 3', 'How do you make the second game worse than the first?  Add pointless mini-games and then actually shorten the video scenes!', 'Mixed', 66.67, 0.80, 1.10);
INSERT INTO reviews VALUES (62641, 2512560, 915, 'Not a bad game, but man you gotta come up with a new way to end your games. Every single one I''ve played ends with a 2.5d png jumpscare. Iron lung it was okay because it was the first time. Then in squirrel stapler it was fine because there was the build up and you knew it was coming and the horror came from knowing. But this time you just walk down a hallway, and get jumpscared and then the game tries to give you a seizure which is kinda cool cause horror games should be designed to kill me irl', 'The gameplay is fine, but the story and setting are just... Absolutely fucking disgusting? There are these cultists who are chopping people up in the most gruesome ways possible, stripping out bones, skinning people, in excruciating detail? And you get health by taking pictures of blood, gore, and all this carnage, and your character absolutely loves it. It''s just... fucked up? The dev seems to really have gone off the deep end with this one, I think bro legit needs intensive therapeutic care. T', 'Very Positive', 94.64, 1.67, 1.15);
INSERT INTO reviews VALUES (62674, 2513240, 134, 'This does what i want a idle game to do. It is like "Progression Quest" but with pretty graphics and more interactability. I leave this on over night and on a second screen while i play other games, and from time to time i tinker with it, level up, clear out stash, then leave it again for hours.\r\n\r\nPersonally i don''t like idle games that force me to pay attention to it all the time, so this is just what i like! Ignore all the hate in the reviews.. there are way too few games like this.. and ther', 'God I couldn''t stand to do more than an hour of this. It feels like a glorified mobile game where you afk through fights until you are high enough level to get to the next enemy to grind through. Also with the added bonus of micro transactions to make the exp grind actual not something to pull your hair out over. Do yourself a favor and find a better game.', 'Mixed', 64.93, 136.58, 0.57);
INSERT INTO reviews VALUES (62676, 2513280, 7650, 'Sonic''s story is basically a cartoon episode while Shadow''s story is a whole Dragon Ball Z arc.', 'Very misleading title! With the name "Sonic X Shadow Generations", I was expecting some hot, steamy Sonadow action. But much to my disappointment, they don''t even kiss! Gameplay is cool, but what the heck, Sega?! I need my gay hedgehog yaoi!', 'Overwhelmingly Positive', 97.56, 4742.13, 11.80);
INSERT INTO reviews VALUES (62704, 2514460, 322, 'I said my pan was a tool of justice. Not used in anger. Not used for vengeance. But now... Now I''m not so sure. And besides, this isn''t my pan.', 'was really fun at first, however it got rather repetitive and is very unpolished. while the unpolished part kinda added to the fun, it is disappointing they only updated the game a single time and then left it. I cannot in good faith recommend a game that is abandoned by the devs so early on.', 'Mixed', 69.57, 0.88, 16.35);
INSERT INTO reviews VALUES (62721, 2514960, 1142, 'i thought i was getting a cute little robot personality quiz to show my friends. instead, i learned what it means to be human and to love someone. 10/10, i cried', 'I was drawn in by the cute art, great soundtrack and the unique idea of personality analysis through choices made in the game. \n\nI didn''t feel the personality test was accurate/meaningful and I made some choices by mistake by clicking about through confusion. So, this shouldn''t be the main reason you choose to buy this game (like it was for me).', 'Very Positive', 91.24, 4.23, 1.32);
INSERT INTO reviews VALUES (62723, 2515020, 9018, 'Performance seems to be much better than the demo, and the soundtrack is godlike.\n\nExclusives for who.', 'Denovo locked me out of the game for 24 hours for simply changing my Steam proton, which I needed to do because in the 9.0 verison I was getting repeated graphical glitches.  This is absolutely unacceptable for a game I pre-order now I can''t even play it all. \n\nAs long as this is a problem I can not recommend this game.', 'Very Positive', 80.35, 3.28, 60.98);
INSERT INTO reviews VALUES (62727, 2515070, 248, 'o7 goodbye onion lady', 'There''s a lot to like in this VN.\nCute characters, funny dialogue, sweet story, really amazing art and music.\nBut I think there''s definitely some things to dislike about this game that others aren''t really talking about.\nIt''s a pretty short VN, especially for the price. I think supporting Hololive Projects like this for future content is a good idea from fans like us, but this was lacking IMO.\nAs it was an "Aqua" focused VN, I didn''t expect the side characters to get fleshed out routes, but the ', 'Overwhelmingly Positive', 99.19, 6.93, 4.63);
INSERT INTO reviews VALUES (62734, 2515210, 700, 'i want to kill myself', 'THIS GAME IS A BITCOIN MINER ; i checked the game files and it uses some program named Phonon to mine bitcoin with your hardware\n\nDo not buy', 'Mixed', 67.57, 4.35, 0.18);
INSERT INTO reviews VALUES (62735, 2515240, 510, 'Welcome to Kowloon is a short psychological and supernatural horror set in the bowels of Kowloon, where our protagonist has found an apartment to hide out in but didn''t expect that in this suburb there would be horrors waiting to awaken him. It''s a short game, but it delivers a tense caustrophobic premise with closed walls, camera movements and some cheap jumpscares.', 'last jumpscare is personal', 'Very Positive', 85.29, 15.68, 2.02);
INSERT INTO reviews VALUES (62786, 2516360, 202, 'I used to make unfunny YTPs that nobody watched in high school back in like 2007-2009. Now I can make unfunny YTPs that nobody watches when I''m in my 30s! Thank you!', 'Never. Again.\nI had some friends that had been using this program to make funny nonsense videos. It was on sale so I thought, eh, I have a nice library of funny videos, so why not, I''ll buy it and join in the fun.\nThis may be the worst mistake I made today.\nI am a linux user, so I set it to use my system installation of Proton GE, 9.20. While it was initially downloading and setting up ffmpeg and ffprobe, it made a very unpleasant noise I can only describe as screaming souls from the depths of h', 'Overwhelmingly Positive', 98.51, 14.67, 0.93);
INSERT INTO reviews VALUES (62805, 2516820, 140, 'As my playtime suggests I probably shouldn''t play slots in real life.', 'It''s boring and pretty shallow. Go play Luck Be a Landlord instead if you haven''t already.', 'Very Positive', 94.29, 30.97, 2.55);
INSERT INTO reviews VALUES (62892, 2518900, 127, 'ABSOLUTE PEAK CINEMA. STAFF WENT ABOVE AND BEYOND. THIS IS WITHOUT A SHADOW OF A DOUBT, GAME OF THE FUCKIN YEAR.', 'I was really disappointed to learn that one of the developers of this game moderates a Discord that fosters a toxic and transphobic environment. They recruit others to spread hate, and if you don’t join in, you get kicked. This is not only unprofessional but also reflects poorly on the game itself. Developers should be focused on creating enjoyable and inclusive experiences, not spreading negativity or fostering hostile communities. It’s disheartening to see such behavior from someone in the gam', 'Overwhelmingly Positive', 96.06, 1.60, 4.65);
INSERT INTO reviews VALUES (62895, 2518960, 654, 'Recommend this game to JRPG fans and those that don''t mind the harsh treatment this game can dish out (Instant death moves, harsh trail and error as well as permanent xp draining to name a few). The remake and its "modernization" by its inclusion of additional features is well done. I don''t think I would''ve enjoyed the game as much as I have without these quality of life changes from the original.\nHowever any gameplay affect can be toggled on or off as the player wishes. So if you want a pure or', 'played for 2.5 hours so can''t refund but in that time I had two characters reset to lvl 1 fighters while raising their levels. game breaking. Do yourself a favor and skip this one, especially at 35.00 for nostalgia. Wish I had\n', 'Very Positive', 83.64, 131.70, 172.27);
INSERT INTO reviews VALUES (62899, 2519060, 6956, 'I got faulty banned and steam  do nothing about it, I did not had a chance to try campaign, this game means a lot to me and it''s only hope I have that activision and steam  agree to unban me, I not recommend this game under 18 years old, but for myself as adult I can focus better on daily tasks when I play short sessions. didn''t try play zombies or campaign, mutilplayer full of hackers, it breaks my hart, I hope human being can read this review and understand my pain :(\n\n', 'A login to an online service is required to play the solo campaign.  This is becoming more common, but is still not a good practice that I will not support.\n\nThe solo campaign is the only mode that can be accessed without adding a phone number to the steam account.  I personally will never recommend or support a game that dictates how the player handles their personal information or private accounts.', 'Mostly Negative', 30.13, 0.00, 0.00);
INSERT INTO reviews VALUES (63007, 2521380, 1240, 'friendly reminder: the actual developer of this remastered package is Saber in collaboration with some talented people from the community, like Raina Audron. The only thing Aspyr was responsible for is publishing. Tomb Raider I-III remastered package was crafted exactly the same way and this is why these two games are that good, especially compared to other stuff released under Aspyr alias recently. So, don''t thank Aspyr for anything about these remasters, the fact that these games turned out go', 'Please aspyr patch this game , i cant see anything in some areas,i need brightness and gamma options in this game.until you can change that ,i am giving this a negative review.', 'Very Positive', 91.37, 26.97, 18.97);
INSERT INTO reviews VALUES (63021, 2521600, 540, 'Stardew Valley IN SPACE!!!  Enough said.\nIn comparison, the only minor con (for me) is the soundtrack is not as well-implemented as in Stardew.\nI don''t like that if I stay in one place for an extended period of time, the music stops playing.\nI want the music to be on a continuous never ending loop, so I can get lost in this game and just completely forget about the world.', 'The bones are good. Cute art. Fun set of characters. I love that instead of "seasons" you have different planets to go to. I love that you''re a rookie captain trying to prove yourself for captain points rather than just some guy taking over a farm. I wish it was less grindy, but honestly I don''t think it''s any more grindy than most games in this genre.\n\nThe problem is... there''s nothing really here. It''s basically JUST grind. You advance the "plot", grind some more, advance the "plot", grind som', 'Very Positive', 90.19, 9.03, 27.27);
INSERT INTO reviews VALUES (63022, 2521630, 204, 'I’m really enjoying this game. It’s chill and satisfying, and it reminds me of Mini Metro. However, instead of losing when resources aren’t transferring fast enough, your population just decreases. The goal isn’t to avoid losing, but rather to grow the population to a target level and construct monuments. \n\nIf you make a mistake that causes traffic jams, you can fix it without stressing about losing the game. I love that I can just listen to a podcast and chill while playing. You can even walk a', 'I want to start out saying this game is exactly what it says it is, from what I played it didn''t seem buggy or anything like that, I just... didn''t have fun playing it. \n\nThe majority of the time spent playing the game I felt like I was either fighting the road system to get something to work the way I wanted it to (the end point of the road seemed to be what was relevant I figured out), or waiting for the city to progress so I could do the next tier of the same thing. I had it at 3x speed almos', 'Very Positive', 85.29, 125.82, 0.78);
INSERT INTO reviews VALUES (63053, 2522520, 141, 'Another game that is hard to complete because the floor and various objects are quite difficult to jump on and are quite slippery. Still be a great game to spent time on!', 'WHY IS THERE NO CHECKPOINTS, AT LEAST YOU CAN FUCKING PUT A GODDAM CHECKPOINT AT SOME SPOTS!', 'Mixed', 61.70, 2.33, 2.93);
INSERT INTO reviews VALUES (63079, 2523120, 798, 'Won my first game because the enemy king was one square off the board and his only legal way back onto the board was by putting himself into check or stepping on a landmine.\n\nHe chose the landmine.', 'i hate this im angry bring me back my money', 'Overwhelmingly Positive', 95.86, 1.38, 0.63);
INSERT INTO reviews VALUES (63085, 2523310, 265, 'Simply put, I love this game. It''s such a massive level up from what Lingo 1 could do, and I love that.\nIn Lingo 1, you had mechanics represented by colors and heights. That was fine, but some of the heights of said colors felt... unusable, really. Yet, when a color didn''t have a height, the community immediately tried to invent one for it, leading to mechanic bloat. Especially considering the recent influx of custom colors (i would know, i''ve made four of them) and all of THEIR heights.\nI have ', 'Play Lingo 1. If you like that this is only okay.\n\nIs this actually fun? I was solving a puzzle where the clue was simply "5 letter vehicle". "Truck" I think instantly. That''s wrong. Plane maybe? No. A few minutes later I search it on the internet, because is this really such an interesting question anyways? It really isn''t. I was in a pure green pyramid with a bunch of other easy similar puzzles. This puzzle had no interesting relation to the world around it. It was not exploring some new mecha', 'Overwhelmingly Positive', 96.23, 65.12, 46.07);
INSERT INTO reviews VALUES (63110, 2523910, 123, 'It''s not a good nor a bad piece, it''s somewhere in between It''s playable but not something I would recommend', 'You don''t get to claim your game has multiple endings if there are zero animated scenes for every outcome--popping up one or two images to say "guess who I ended up with" does not make the playthrough unique. It''s just a disappointment.', 'Very Positive', 86.18, 2.73, 2.28);
INSERT INTO reviews VALUES (63164, 2525230, 116, 'My Lovely Stepsister is a great NSFW game that you can play with one hand :) Since the title has Stepsister in it, I was wondering about whether the game has a washing machine scene or not. Well, let''s just say that the game didn''t disappoint. I really enjoyed my time with it. Renders are great, and animations are looking good. It''s one of those visual novel games where it lets you free roam and gather money to buy stuff. I want to thank the devs for not making it grindy. There are minigames her', 'Not recommended at all. It appears to have a free roam aspect to the game but it is really just a point and click. It tells you where to go all of the time and if you try to veer away from the next task, there is nothing to do or see. All of the people disappear so there is nothing anywhere except where you are required to go next. Mini games are very easy to win but really a waste of time.', 'Mostly Positive', 70.69, 2.38, 1.32);
INSERT INTO reviews VALUES (63167, 2525310, 749, 'I played Drop Duchy extensively during the demo and immediately bought the game when it fully came out. Roguelite, puzzle, city-builder Tetris is a very unique game genre, but it does an amazing job of pulling it off. Building up your card selection and board is satisfying, and each round feels different as you try to maximize your adjacency bonuses while balancing it with trying to make it tightly packed and get the most resources every round.\n\nIf that wasn''t enough, there is even a unique comb', 'At its core, the game is pretty damn cool—like a blend of Dorfromantik, Tetris, and Balatro/Slay the Spire. Every mechanic feels well thought out and well implemented—except for one: the rogue-lite element. It just doesn’t work. The progression system and unlocks make the game more complex, but not in a meaningful way. Instead of adding depth to the mechanics, it just adds more keeping it shallow. I beat the game on my first run, unlocked a bunch of content, tried it out, and honestly thought, “', 'Very Positive', 90.52, 18.12, 2.57);
INSERT INTO reviews VALUES (63168, 2525380, 443, '“I feel stronger now!” The Angel of Darkness remaster gives us the proper workable game that was lacking over 20 years ago and I think tomb raider fans should give it a second chance.\n\nI hope that the other TR games like Anniversary, Legend and Underworld can get remastered with the same care and treatment as well.', 'It breaks my heart to give this a negative review but sadly Tomb Raider IV-VI Remastered is NOT A FINISHED PRODUCT...\n- TR5 is the most polished out of all 3 games. Levels are absolutely gorgeous with plenty of additional objects, enhanced geometry and effects on top of fabulous textures. There is nothing bad I can say about this remaster, it got the most love.\n- TR4 it start wonderful with Angkor Wat and Valley of the Kings but when you reach Alexandria it disappoints... Only basic remastering ', 'Very Positive', 88.49, 3.37, 37.80);
INSERT INTO reviews VALUES (63211, 2526310, 149, 'If you have played a lot of horror games and want a refreshing experience this is the game. It''s not scary in the sense of jump scares but the sense of atmosphere and the story. 100% recommend. A great experience', 'This game is basically atmosphere and nothing else.  The story is thin.  You are crawling through tunnels behind the walls 85% of the time. Its failing to be anywhere close to Little Nightmares. It wasn''t even that scary. The ending was weak too.', 'Overwhelmingly Positive', 98.66, 3.78, 5.85);
INSERT INTO reviews VALUES (63254, 2527390, 2025, 'Setting the example for how you remake a legendary game. Adored being surprised by the new gameplay features and getting to experience that Rocket Launcher for real this time. Love having two unique versions of the game to play, whether it be the nostalgic route from 2006, or to experience the visuals of RE Engine in DRDR. Crazy time to be a fan of Dead Rising.', 'Capcom made an underpolished and overcensored waste of time and money. This is actually worse than the original in almost every way. The lighting and shadows are way too realistic, although the texture quality is of course looking good. Some areas do look nice and vibrant. After seeing a certain video, it''s apparent the quality and soul of the original are in the shitter for this "deluxe remaster". \n\nI was actually having some fun until i kept getting crash after crash when returning to the safe', 'Very Positive', 83.95, 58.88, 7.37);
INSERT INTO reviews VALUES (63259, 2527500, 21317, 'Solid 9.4 in it''s respective category. One the most polished games I''ve played on my account and I have 1000+ games. Good story delivery, good pace, doesn''t stall out or drag. Finds refreshing ways to keep the player involved all the way throughout the game. Art, animations, transitions etc genuinely impressive and creative. Indie game of the year, definitely. \n\n-x', 'Good things about MiSide:\nThe gameplay is solid, the situations and moods are varied enough that you won''t get bored, the story has good forward momentum. It will entertain you for the five or so hours it takes to finish it.\n\nBad things about MiSide:\nThe characters are just one-dimensional instances of their tropes. In the end nothing is resolved, no questions are answered, no character completes an arc, no themes are treated adequately. Once those five hours are up, you''ll be like "That''s it?" ', 'Overwhelmingly Positive', 98.27, 3.78, 11.63);
INSERT INTO reviews VALUES (63330, 2529080, 219, 'The game is fun, it''s not expensive, and you can put it down between any of the missions and it''ll save your progress for you to continue later. What''s not to like about a great way to spend a spare half hour like this is? Two thumbs up.', 'The progression gating is waaaaaay too aggressive. Most of the content is gated behind unlocking "artifacts" which are rewards that you can receive 0-2 of after completing missions, and there are only 11 missions per playthrough that yield artifacts. The first unlock tier occurs at 20 artifacts, meaning you have to complete about two full playthroughs in basic mode to even begin to explore the first part rest of the content. At 80 artifacts at least 16 playthroughs in order to access all content', 'Very Positive', 82.19, 36.52, 13.73);
INSERT INTO reviews VALUES (63333, 2529120, 363, 'teacher scolded me for missing class as I was being stabbed to death by a child', 'i love m dickie but this game is a steaming pile of dogshit you cant do anything without getting jumped by random people im flat broke and cant go into any building to steal cash because SLEEPING AT THE HOSPITAL TAKES MONEY AND EVERYTIME I LEAVE I GET JUMPED so i go to class to try and improve but if you dont have the class specific item on you when you walk in you FAIL FUCK THIS GAME AND FUCK YOU DICKE YOU CAN DO BETTER', 'Very Positive', 85.12, 5.55, 20.68);
INSERT INTO reviews VALUES (63337, 2529170, 506, 'Great Game! A few suggestions...when tipping over cardboard box, things should fall out. When hitting pedestrians, lose money over lawsuit. More homes for sale. More vehicles for sale. Restore vehicles from bad to perfect. Restoration should cost money.\r\nJust a few ideas...it is addicting to play though, for those of us who like games where we "make money".', 'Though realistic, the gambling mechanic is completely rigged', 'Mostly Positive', 71.34, 15.45, 0.52);
INSERT INTO reviews VALUES (63368, 2529820, 1685, 'Its a fun little game.\nWhile it is fun, you dont get tons of content. It feels like a first game from someone who has passion but lacks experience. But "Wedding Witch" definitely has potential (although it seems like the devs are busy with other stuff).\nI enjoyed it for what it is.\nAnd no there is no actual nsfw-stuff, steam tags are just stupid.', 'no sex\n', 'Very Positive', 92.34, 9.97, 0.65);
INSERT INTO reviews VALUES (63392, 2530430, 135, 'A really fun slasher that stick true to the general tropes of the genre. This game feels more like an interactive movie then a game but I still found it very enjoyable. The art is also amazing. Really like how freaky Teddy looks. I highly recommend this game though I do warn some; you will have to kill a dog.', 'Was enjoying it until I had to rip apart dog just minding his own business to progress.', 'Very Positive', 90.37, 3.53, 2.65);
INSERT INTO reviews VALUES (63396, 2530490, 169, 'Good Game, responsive publisher.\nHad a game breaking issue and the publisher fixed it within an hour of it occurring.\n10/10 customer service.\nIf you like turn based strategy RPGs give this one a shot!', 'It has all the bones of a good game, but ultimately it is not.  \r\n\r\nCharacters are fun to play, lots of skills, upgrades feel significant, relics are fun, making progress is satisfying.\r\n\r\nThe battles are where it falls short.  Not enough maps, not enough enemies, just not enough meat on the bones.  there are like 7 non boss enemies total in the whole game (re-skins and just calling them zombies with the exact same move-sets does not count as more enemies)  and like 10 maps you play over and ove', 'Very Positive', 85.21, 34.95, 32.22);
INSERT INTO reviews VALUES (63419, 2530950, 153, 'It''s not bad. I think it feels extremely empty for being so close to full release, though. Even though there''s lots of clothes, cars, and guitars to buy and a few skills to grab and stuff, it just doesn''t feel like there''s really all that much to see. Game''s cheap, though... Just wish it felt more... gamey.', 'everything is "coming soon" and yet the game is apparently finished.', 'Very Positive', 82.35, 3.17, 0.45);
INSERT INTO reviews VALUES (63422, 2530980, 258, 'Too be honest i wasn''t expecting to see this but i''ve seen enough. NAMCO, GIVE US TALES OF THE ABYSS DEFINITIVE EDITION AS WELL, AND MY LIFE IS YOURS.', 'So single player game but I can''t play unless I agree to data collection? Declining results in you going back to the agree screen\n\nquickest refund in the west', 'Very Positive', 90.31, 16.42, 0.15);
INSERT INTO reviews VALUES (63436, 2531310, 7400, 'The game is very immersive. Your GPU works so hard rendering individual raindrops that you can feel the humidity rising in your room. By hour two, your PC is covered in condensation, and by hour five, mushrooms start growing on your keyboard. For the whole experience, keep a brick on your desk and throw it at your monitor every time your frames drop below 60.', 'The biggest piece of mental disorder woke gender-pretending alphabet nonsense I have EVER encountered in over three decades of gaming. It reeks of desperation to validate fringe societal abnormalities made possible in today''s world only through brainwashing, extensive pharmaceutical abuse, and self-mutilation through medical enablement, all of which profiteers off the mentally-ill. In a post-apocalyptic world, such nonsensical human abuse just isn''t feasible given the lack of any sophisticated i', 'Very Positive', 90.54, 47.80, 0.48);
INSERT INTO reviews VALUES (63458, 2531940, 122, 'Yeah, okay, the game is cool. \nBut why all the characters are not different cats?\nLike: cat rogue, cat barbarian, cat mage etc.\n\nAlso: undo button is needed', 'The game mechanics differ from the demo and thus I can no longer recommend the game.\n\nIn the demo, to unlock new items you gathered "souls". These were received through progressing as far through each run as you can, as well as taking additional risk on killing as many enemies as possible per stage. Unlocking one character would take multiple runs.\n\nIn the release, you unlock items by earning shards gained through steam achievements. This creates an initial burst of progress (I unlocked every si', 'Very Positive', 80.33, 4.20, 2.20);
INSERT INTO reviews VALUES (63481, 2532430, 347, 'This was a short (~1.5 hours) fun little horror game that definitely worked hard to create a creepy atmosphere.\n\nWith the low price tag, it was well worth the cost. I would recommend it to anyone looking for a quick scare.\n\nFor anyone looking to see the game before they buy, or if you are looking to watch a full play through, I humbly offer my video for your consideration: https://youtu.be/CiAbO8Zfsco', 'DON''T WASTE YOUR MONEY ON THIS GARBAGE. The game is almost unplayable. Whoever coded this game did so in the worst possible way. You''ll spend your time walking around trying to get events to trigger but nothing happens. I bought this game thinking it would be a fun horror game that I could snag up the achievements for but how I was wrong. I''m lucky I only spent $4 for this on sale but it should be free. It''s simply so poorly made that you''ll spend half the time not knowing what to do because the', 'Mixed', 69.45, 1.53, 1.12);
INSERT INTO reviews VALUES (63486, 2532550, 740, 'Finally a historically accurate game about Russian history. Amazing attention to detail and love for the little things. Rich and complete biography of historical characters. A thorough reproduction of ancient Slavic strategies and tactics.\n\nAnyone who wants to understand Russia should play this game.', 'Don''t let the reviews fool you as they did to me, I thought it might have been some fun cheap hidden gem but it is simply not good. It''s a meme game. Nothing aside from the music and loading screen art is good.', 'Very Positive', 90.14, 1.75, 0.98);
INSERT INTO reviews VALUES (63534, 2533960, 1255, 'A very relaxing and simple straight-to-the-point sandbox game about just laying back and enjoying that warm, digital breeze while building some houses.\nI can''t help but love it.\n\nIt''s not the type of game to keep you engaged for the "long run", instead more like a "fun run".\nSincerely, Summerhouse is best enjoyed in small, few, compact sessions with a hot cup of coffee on a hot summer evening.\nStrong recommendation!', 'The art style is very healing, but I still don''t recommend this game because it has fewer items than you imagine. The author seems to have not considered players who want to build a diverse and realistic house, but rather leans towards crazy players who like to build houses randomly or through objects with similar characteristics to the desired ones. This is unfair to players who want to build a qualified house seriously. We don''t want to build other houses with the same style after completing t', 'Very Positive', 93.94, 1.67, 30.07);
INSERT INTO reviews VALUES (63548, 2534370, 100, 'If you were worried that this was phoned in, don''t. It''s got that WayForward gravy. Cute girls, silly banter, monster girls, and incredible music.\n\nThough, a cyberpunk metroidvania about a sloppy hacker girl is extremely my kind of game, so I''m not exactly neutral.', 'It''s a good metroidvania with some fun hacking minigames but... "dude zomg this dialogue is so relatable and fun lolz". The music is also wonderful, but I got too annoyed by the dialogues and them being so "hip, modern and relatable".', 'Very Positive', 91.00, 8.57, 0.72);
INSERT INTO reviews VALUES (63577, 2535440, 253, 'It''s the almost the same as the 360 version I still own to this very day, with zero PC options added. Didn''t assume it''d be getting much with it''s budget pricing, but I''m personally okay with that. So most folks expecting an actual PC port are going to be very disappointed. Thankfully it''s still the dumb, funny, clunky-beautiful game it always has been. Would still recommend it to anyone with a puerile sense of humor that also enjoys movies like Evil Dead 2 and Dead Alive. \n\nGoing to fart around', 'This has always been a game with a great script and wonderful voice acting. It''s a game with incredible style. However, this is not a remaster. The game has no graphic settings menu. And the graphics are still pretty bad. There is also only one audio setting for master volume, so dialogue can be hard to hear and music is way too loud. It''s just disappointing to see so little effort.', 'Very Positive', 88.93, 4.82, 0.88);
INSERT INTO reviews VALUES (63584, 2535670, 103, 'This is a wonderful little puzzle game with cute characters and a charming art style. Short, fun and definitely worth the money. Don''t underestimate the speedrun achievement!', 'I got this game cause it looked cute but unfortunately, there are some MAJOR BUGS to this game which makes me don''t want to continue.\nFor example the worms in chapter 2, it requires you to get 1 worm for the fish to get the key which is important to progress in the story, but it also asks you to give 3 worms to the duck to enter its house. The problem is there were ONLY 3 worms that you can find in the map. If you didn''t give that 1 worm to the frog, instead you gave it to the duck (because how ', 'Overwhelmingly Positive', 99.03, 7.75, 1.37);
INSERT INTO reviews VALUES (63596, 2535830, 1368, 'I have no squirrels and I must staple\n\nEdit: I couldn''t figure out what about the visuals of this game were so appealing to me or why, but I''ve just realized its because it looks so much like Jurassic Park Trespasser.', 'Not enough squirrels', 'Overwhelmingly Positive', 96.56, 2.23, 1.93);
INSERT INTO reviews VALUES (63628, 2536530, 531, 'Twilight Sparkle if she locked tf in', 'game look cool i buy\ngame feel ok it cool\ngame play like sleep i snore\ngame no good i want 3 dollar back', 'Very Positive', 94.16, 0.93, 0.37);
INSERT INTO reviews VALUES (63633, 2536650, 112, 'Pretty good bullet heaven that''s really fun to get good at. It''s unique and addictive. Parrying explosions is always... a blast...\r\n\r\n100% achievement completion mostly boils down to just getting good. You don''t have to be good at typing. There''s a little bit of grinding, but the most difficult achievements are just about practicing some strategies. Overall: very difficult, but very fun.', 'It is fun, but very limited - one game mode, kinda like tetris ramping up from easy to hard over time. I was hoping for a twist or new idea for a typing game, and its a very cool idea, but I can''t really consider this a typing game since you only learn the left hand.', 'Overwhelmingly Positive', 95.54, 10.93, 0.12);
INSERT INTO reviews VALUES (63672, 2537590, 8333, 'After 1 hour of loading screen gameplay i can only say that this is the most immersive loading screen i have ever played:)', 'Dear Microsoft,\r\nI was told the reason you made MSFS 2024 more cloud based was because some of your customers complained it took up a large amount of hard drive space.  I''m writing to inform you that if I bought an RTX4090, a Thrustmaster joystick throttle and foot peddles, a valve index for VR, and the top tier version of MSFS 2024, I''m very likely not put off by the concept of buying an additional $50 SSD drive for my PC to store your game on it.  What I am put off is playing MSFS 2024 for thr', 'Mixed', 45.15, 7.15, 102.42);
INSERT INTO reviews VALUES (63682, 2537920, 169, 'It''s like if Untitled Goose Game and Little Kitty Big City had a child! Absolutely amazing and funny game, I loved every moment of it. I put of playing it for a while and finally picked it up a few days ago. I couldn''t stop playing it! I loved being an asshole to everyone.\n\nI encountered a few bugs but nothing major. More just the crow getting stuck in things it shouldn''t have. I felt like it added to the game''s humor in a way.', 'i really really wanted to like this game, but it just feels very unpolished, janky (not in a good or enjoyable way) and outdated.\nthe price point is way too high for what you get and experience. hopefully things will get better, but i was looking forward to playing this and was disappointed.\n', 'Overwhelmingly Positive', 95.86, 5.77, 0.72);
INSERT INTO reviews VALUES (63706, 2538370, 129, 'Similar to the better AVNs we used to get a few years back before the genre became saturated with copy cats, hentai ports, and pump & dumps. The standard AVN tropes are used smoothly for a Slice-of-Life power fantasy; with a little bit of railroading around the main characters to provide narrative structure. \r\n\r\nI think the amount of romanceable characters is about right, enough for variety, not so much as to be undercooked in the (eventual) final version of the game. NTR is offered and optional', 'Dont buy this game! You will see a nasty dude friend more often then any of the girls. AND THERE IS NO ACTUAL SEX WITH ANY OF THEM EXCEPT THE FIRST LATINA GIRL. I SPEND 9 HOURS HAVING A BONER, WAITING FOR A GOOD SCENE BUT THE GAME JUST SAYS F*** YOU.', 'Very Positive', 91.47, 3.48, 9.87);
INSERT INTO reviews VALUES (63747, 2539520, 118, 'The game has changed a lot since I last reviewed it. The developer continues to update the game frequently which is promising. The over the shoulder slot improvement was very welcome and needed.  If he continues to add new content and improve the game it should be really good. Right now I suggest an improvement on the enemy animations. This is something the first game lacked and I think it would be a huge help to this version and lead to a lot more sales.  The weapons and environments are much b', 'Just play into the radius', 'Very Positive', 85.59, 13.20, 0.18);
INSERT INTO reviews VALUES (63760, 2540230, 154, 'It''s a bit like Crusader Kings but with less incest.', 'The gameplay is long and redundant considering the reason people buy these games.   The storyline is rich if you just want the "visual novel" but if you want to see the sex, you will find the animations quite underwhelming compared to other games of similar genre.   The style is a bit crude and tasteless too, focusing on "forced encounters" and even beastiality.   Artwork is mediocre at best, most of the models, particularly the "milfs" are not very attractive and most "scenes" don''t even have a', 'Very Positive', 85.06, 29.25, 12.55);
INSERT INTO reviews VALUES (63771, 2543180, 116, 'Made by Hypergryph, so there is an expected level of quality - and they far surpassed it. Genuinely one of the best couch co-op games I have played in a while, definitely going to 100% this game. Check out Hypergryph''s other projects like Ex Astris or Arknights & Arknights: Endfield.', 'good with 2p not 4p', 'Overwhelmingly Positive', 96.55, 12.77, 3.33);
INSERT INTO reviews VALUES (63774, 2544110, 230, 'I came here after playing an adventure game called "Crowns and Pawns: Kingdom of Deceit" - a modern adventure game clearly inspired by the old Broken Sword game. Yet, playing both that game and Broken Sword Reforged has reminded me why adventure games today suck - and why the genre is dying. Namely, it''s no wonder that modern adventure games don''t sell well when they can''t hold a candle to games made 30 or more years ago! Go and play any more modern adventure game and compare it Broken Sword - a', 'Too expensive for what you get, the graphic updates are not worth 30 euro I also detest the new mouse interaction, sound is the same as the original version so no update there. I refunded it due to the price and lack of value (we shouldn''t be punished for the use & cost of AI upscaling) and personally I liked the added content from the directors cut so it being removed from this version seems like a money grab to me due to cut content.', 'Overwhelmingly Positive', 95.65, 5.75, 0.77);
INSERT INTO reviews VALUES (63776, 2545220, 102, 'This is such an interesting game! It only caught my attention after about half an hour, when I finally understood the game''s mechanics and what I had to do, but at that point I couldn''t leave it anymore. It is not your classical horror game, with lots of jumpscares (I only encountered one) and spine chilling atmosphere, but it creates a different kind of feeling, the one you had as a child when you were left alone at home during nighttime. Not fear. Something different. You''ll only understand if', 'I like this game.  I WANT to play this game. However, it has game breaking bugs and I can''t recommend it.  I am at a point now where I can no longer move forward due to a bug when fighting an early boss. Its frustrating.  You have no choice but to reload your save and try again, but the issue persists.', 'Very Positive', 86.27, 7.62, 8.03);
INSERT INTO reviews VALUES (63777, 2545360, 345, 'If you played the first game, Downhill, you know what to expect.  Great physics, shortcut hunting, high tension seat of your pants speed thrills, and a lot of fun.  Also a LOT of crashing (the hitting rock kind, not the game itself :)', 'Really nice game would love to love it, but you play against the camera angle and 50% of the movement and the line is a fat guess. If the camera angle is unlucky, you can see like 5 meters in front of you. If you can live with it, it should be fun but I just can´t. \n\n', 'Very Positive', 90.43, 0.92, 1.23);
INSERT INTO reviews VALUES (63794, 2550040, 247, 'I have been a recreational-tec diver and public safety diver for nearly 17 years. This game absolutely nails the look, feel and really, the SOUND , of being underwater while free-diving/snorkeling. Very immersive. The environments are incredibly realistic and the wildlife behave and move naturally. I am really really impressed with what is on offer. The game looks great, runs great and controls well. Do yourself a favor and try this out. Recommendations to the developer: please introduce scuba, ', 'This is first and foremost a swimming simulator with very little gameplay. Yes, the environments are impressive. The wow factor is strong at first. The problem is that once this effect wears off (and it will), you might find yourself as bored as I was. Levels (environments) are locked until you find enough items in the previous level. This can take an incredibly long time searching through every square inch of water in search of the final tiny item in order to proceed. If standing around moving ', 'Overwhelmingly Positive', 97.98, 5.43, 1.42);
INSERT INTO reviews VALUES (63806, 2555430, 157, '$3 for this game?? I''m sorry, but what? Buy it. It''s a steal. This game is simple but it''s great. I''m genuinely enjoying it and haven''t stopped playing all day.\r\nIf you''re curious, just buy it. It''s less than a coffee. Support the devs.\r\nKnowing how much I enjoy this game, I would have happily paid $15 for it.\r\nIt''s a great game for great value. Good job, devs.', 'The game has some great aspects, but the combat and soldier leveling system is terrible! It might be the worst system you’ve ever seen. When you recruit a soldier, they stay by your side and fight for you unless you replace them. However, even if your soldier wins 20 or more battles, NOTHING HAPPENS! YOUR SOLDIER DOESN’T LEVEL UP!\n\nAfter a while, your enemies reach terrifying levels like 6 or 8, but your soldiers remain at level 1. To level up your soldiers, you need to earn points by constantly', 'Very Positive', 89.81, 16.95, 21.25);
INSERT INTO reviews VALUES (63824, 2561580, 1762, 'I really feel like the game is nowhere near old enough to need a remaster. Like yeah it looks good but it already looked good and it''s only slightly dated. I mean I love Horizon Zero Dawn and I love Forbidden West, but the PC port of HZD came in 2020. It SIMPLY doesn''t need a remaster. Can we have useful remasters instead? You know, like games stuck on ps2/ps3. Why would you remastered this, but not Bloodborne or any GoW, Killzone, Resistance, Uncharted games, instead you choose a game that is p', 'As good as the game may be, requiring an internet connection to log into an account to play an offline game should be illegal.\n\nEdit: I don''t know whats happening, but the game doesn''t even launch anymore. The only thing I can see is the "Sony presents" screen and then the game is just frozen. Why are games such trash these days? As cool as the technology nowadays is, gaming is f**ing dying and it makes me sad.\n\nAvoid this waste of storage and play the original game instead. Don''t give Sony your', 'Very Positive', 81.27, 1.83, 11.45);
INSERT INTO reviews VALUES (63909, 2564860, 129, 'This is a really cute game with very obvious inspirations. I was enjoying it so much… aaaaand then it was over. The main game I literally beat in 40 minutes. I knew it was gonna be small but I was honestly hoping for a full fledged game in this style. And if not a full fledged gamed at least 5 hours like some other reviewers were saying. There is a tower mode after you beat the game but it’s a rogue like mode that I’m just not interested in.\nDon’t get me wrong, I like this game a lot. I want to ', 'An inoffensive, but shallow game. While the game advertises a bite-sized adventure, I wasn''t expecting to be served crumbs. All of the core mechanics are things that have been around for decades, only explored at the most basic level. There''s just nothing of substance to appreciate here. While I''m not one who usually factors in price and playtime in a review, I saw pretty much everything the game has to offer in an hour. And it wasn''t even a particularly entertaining hour. The current asking pri', 'Mostly Positive', 77.52, 0.78, 1.13);
INSERT INTO reviews VALUES (63939, 2565550, 363, 'It''s good but it''s a pain that you can''t save, so if you quit out mid level when you load back it just puts you right back that the start of a level.', 'This one could have used another year in the oven to fix bugs and maybe tighten up some of the experience. I couldn''t tell you why the game has a crafting mechanic, I basically never used it. I don''t know why they had an open world hub, nothing interesting is done with it and it has issues loading in. There''s like 3 or 4 main types of enemies and they are not really all that threatening. I only died in actual combat I think one time and that was during the final boss because I decided to start b', 'Mostly Positive', 76.58, 13.87, 11.25);
INSERT INTO reviews VALUES (64029, 2567870, 17552, 'Don''t be fooled by the cheap price of the game. The real price is the cost of friendships, family ties and a girlfriend that gives you the silent treatment.', 'I had 3 best buds now I wish cancer upon them , cant believe these people have brain cells', 'Very Positive', 91.74, 9.73, 6.83);
INSERT INTO reviews VALUES (64080, 2569330, 100, '21st century gauntlet, anyone from the 80s knows this, nicer graphics, more enemies, BRING IT!', 'Maybe this game was meant for a very specific and niche audience but if you like modern roguelikes/bullet hells similar to vampire survivors then you might not like this. \n\nI should preface this by saying that I never played the original Gauntlet so I don''t know what that was like. This game feels slow and lacks variety. The upgrades every time you level up, feel inconsequential. They are things like "+2% attack speed" or damage or defense, etc. They''re very slight number upgrades so not particu', 'Very Positive', 82.00, 5.75, 1.52);
INSERT INTO reviews VALUES (64123, 2570210, 680, 'I was going in with mixed expectations, but since I had such a great time with Planet Crafter (another great example of early access gone right), I decided to buy the game. And boy, did I make the right call.\n\nI was honestly worried at first. I had flashbacks to Empyrion - Galactic Survival, a game that''s way too bland for it''s own good. I went a few hours struggling (everything was taking so long) before deciding on really going all in into the automation phase. That''s where things really took ', 'Bit of a harsh critique here, I do appreciate what this game offers, the gameplay elements are there, but it feels and looks unpolished in my opinion, mainly with the UI and the use and fx of the main tool.\n\nIt feels a bit like if gmod was made out of half life 1 after half life 2 came out if that makes sense?\n\nPerhaps in future if it seems overhauled I might give it another go, but it just didn''t sit right with me after having played Planet Crafter and Satisfactory.', 'Very Positive', 84.85, 16.83, 0.47);
INSERT INTO reviews VALUES (64220, 2573100, 102, 'The only thing I would say this game have issues is that still lacks character creator.\n\nBut still a great game.', 'Game''s very poorly optimized and feels slow and empty. If it goes on like this, I''ll just say that it won''t be enjoyable in any way once story mode comes out.', 'Mostly Positive', 74.51, 0.72, 1.37);
INSERT INTO reviews VALUES (64313, 2575900, 1235, 'If I had a nickel for every time I got briefly obsessed on a 3d platformer starring a goat character exploring a dream, I''d have two nickels. That''s not a lot but it''s weird that it happened twice, right?', 'I heard good things about Corn Kidz 64 and how faithful it was to good N64 platformers. Turns out it also has some of their worst aspects as well. Despite how massive the levels are, you get booted back to the start of the game should you quit. Almost as bad is the inconsistency in how progress through the level is saved. Certain puzzles get reset, while others, seemingly arbitrarily, don''t. The platforming is imprecise enough to be outright masochistic at times, while usually requiring very pre', 'Very Positive', 94.17, 26.20, 8.77);
INSERT INTO reviews VALUES (64373, 2577760, 226, 'The game is good, but if they added a reward system, where you earn points after each run. That you could spend to upgrade your button for the next run. It would be a lot better.', 'Pretty mediocre game overall, you will find out very quickly that it is the kind of game that looks much better in Youtube videos compared to playing it yourself.\n\nIf steam had neutral reviews this game would probably deserve one, since its still pretty cheap and its not BAD or anything, but there are many other games out there that are likely more worth your time.\n\nIf you do get it you can expect 2-4ish hours of play and then probably never touch it again.', 'Very Positive', 92.48, 2.72, 2.07);
INSERT INTO reviews VALUES (64426, 2578880, 126, 'I CANNOT WAIT TO LOSE MY VIRGINITY RAAAAAAAAAAHHHHH (I’m 51 years old)', 'Glorified slideshow with very few choices.', 'Very Positive', 80.95, 885.12, 1.40);
INSERT INTO reviews VALUES (64428, 2578910, 528, 'Idk why people are so upset when the game was Advertised as short and even has it in the tags, Game was fine and enjoyable especially considering the amount of people that worked on it, plus the people mad because of the Gay relationship is kinda crazy, do some research on a product instead of hating, its not like the game was Trying to hide the fact it was LGBTQ+ like y''all are weird, Anyways though Game was well done for the amount of people that worked on it and hopefully the dev is willing t', '5% survival story, 30% walking around empty bland areas, 65% boring generic gay romance between two bland broccoli hair zoomers, less than 30 minutes of playtime, all the notes scattered around lead to nothing and the information in them is useless as the game isn''t about the apocalypse, you''re better off reading some fallout fanfiction with gay people or something, there''s nothing interesting here and this dev really has some balls to charge people for something you can complete while taking a ', 'Very Positive', 89.77, 1.12, 0.97);
INSERT INTO reviews VALUES (64462, 2579730, 104, 'I''m giving this a tentative thumbs up. There''s a lot of content and the woman all look hot. But there are also a whole lot of typos. Also, even if you change the MC''s name, there are instances where the game still uses the default name. And the third person narration "He does x..." rather than first person "You do x..." kind of breaks immersion. I also wish there were voice/sex sounds. Finally, I have to say that the back and forth over and over with the main love interest between "I want him/My', 'Not a huge fan of the game having a focus on women with big fake tits. Honestly took me out immediately. Also whats with everyone clearly being obsessed with huge tits, where is the love for small tits. Bigger isn''t always better people, we seriously could use some more variety around here. I''m not here to yuck anyone''s yum but i mean seriously people i can''t be the only one sick of seeing nothing but oversized tits and ass. Conclusion- Not for me, big tits are over rated and fake ones are gross', 'Mostly Positive', 77.88, 12.63, 0.23);
INSERT INTO reviews VALUES (64475, 2580020, 470, 'Even the all knowing clerk doesn''t know how Julien managed to release an indie game while working in a mainstream game studio and raising a newborn baby at the same time, and he still has time to reply to my messages!', 'It''s kinda disappointing? The gameplay is very bare, and not super engaging due to being really easy to exploit, and the story just is not substantial. Maybe if you''re into extrapolating plot from very small hints this might be for you, but to me there just isn''t enough meat to make it a satisfying plot. By the time I felt it was getting started and would go somewhere interesting the game just ends, I looked up the other endings just in case there might be more but they don''t seem to add a whole', 'Very Positive', 92.13, 15.13, 1.62);
INSERT INTO reviews VALUES (64481, 2580130, 121, 'I gave it a thumbs up for the animation, which is really quite good. However, be aware the writing will kill off a significant number of brain cells. Love it when you''re reading a period piece about vampires, witches, werewolves, etc., then the dialog breaks into some street banger lingo about fucking. Stupid.', 'Lost 45mins reading a cheesy and overly complicated story. Some stuff feel bugged (first s3x scene only at chapter3?).\nMost of the game is just still images that you browse like a powerpoint.\nNo interactivity. \nREFUNDED', 'Very Positive', 83.47, 7.50, 0.83);
INSERT INTO reviews VALUES (64513, 2581370, 124, 'improvements over the other games, but first person camera is waaaaay too zoomed in yet again. why dont we have a slider yet?', 'I would rather throw my money at strippers than spend $80 on this absolute joke of a game again.', 'Mixed', 45.16, 1.13, 0.60);
INSERT INTO reviews VALUES (64515, 2581410, 155, 'Do you like the trailers and game description? Good! Thats exactly what you are going to get, if you buy Stygian Outer Gods. \n\nAs someone who played pretty much every Lovecraftian game i feel like at home! A promising title that borrows stealth elements from games like Gloomwood and Bethesda classic Dark corners of the earth ( relased in 2006) and its fantastic sanity mechanic......You feel like your character starts to go nuts, hearing sinister voices the more your sanity deteriorate. \n\nTLDR: A', 'Im going to go for a refund for now. Premise is great, lovecraftian vibes all round, all in all seems promising, but ill wait for a full release, barely playable in the current state.\nPerformance is all over the place, crashes on volume change, frame generation completely breaks fps, random crashes in dialogues, random crashes during movement.', 'Very Positive', 85.16, 7.05, 0.65);
INSERT INTO reviews VALUES (64528, 2581700, 306, 'absolutely the best motogp game i have ever played, unlike other motogp games you actually have brakes and can brake in a lean without the front end just collapsing, if you are looking to buy a motogp game, i would not bother with any of the other games from the motogp series. this is the best one hands down. milestone actually made an enjoyable motogp game', 'Buyer be ware, Epic Store account/connection is required. Refunded.', 'Very Positive', 83.33, 281.18, 0.90);
INSERT INTO reviews VALUES (64560, 2582560, 3581, 'Maybe a hot take but I am having fun with this madden. Now keep in mind I am a Franchise player NOT an online guy. No MUT or H2H for me personally. IMO if its on sale for a decent price and you like me enjoy Franchise then it is not a bad game. But also EA is a vile company so do with this information what you so choose lol', 'Same stale game. To start I am solely a franchise player so I don''t care about any of the other game modes. Franchise mode is still the same it''s been for years. The simulation stats are horrible. Simulation in general has the weirdest outcomes. Even from a game play aspect the game feels clunky. CPU lineman make the dumbest decisions on who to block in the open field. CPU secondary players are clueless. Overall I am just not having fun with this game still after skipping buying for 3 years and ', 'Mixed', 54.29, 484.58, 159.95);
INSERT INTO reviews VALUES (64652, 2585050, 156, 'emotional roller coaster, full of beautiful story writing, and great character development, this exceptional work creates for an amazing experience, great combat mechanics, and compelling choices, and one of the hardest yet fulfilling fights in online gaming history, Also it made me so mad that I slammed my jiblets in a waffle iron whilst it was on (I am now Infertile) :)', 'Every man named Tyrone that talks to me i just get flashbacks of how i got butt raped by this big black guy named Tyrone.', 'Very Positive', 90.38, 23.12, 5.20);
INSERT INTO reviews VALUES (64660, 2585270, 155, 'Kamla is a 10/10 of baddie.\n\nFatt k 4 ho gaya..', 'Guys This Game is Very Bad For Low End PC\n', 'Very Positive', 93.55, 3.95, 0.10);
INSERT INTO reviews VALUES (64677, 2585720, 104, 'A Thrilling Horror-Erotica Adventure\n\nIf you''re a fan of the horror genre and zombies with a twist of eroticism, then "Sex Apocalypse 2" is a must-play game for you. This game masterfully blends the thrill of surviving a zombie apocalypse with the titillating journey of our bold heroine, who somehow manages to lose all her clothes while battling through hordes of the undead.\n\nAs you guide our fearless protagonist through the devastated city, you''ll pick up guns, ammo, and health packs, all while', 'For Gameplay Check Out My Video Here: https://youtu.be/gmxtJR0B7KQ\n\nBy no means was I expecting a masterpiece but still. Gameplay is extremely tedious even for a wave based shooter. Spawn points are easily exploitable. Bullets spread outside where the reticle tells you they should go. Animations are busted but your nut won''t be. Even the "Adult" scenes are laughable. I will give the voice actress credit, she did make me laugh... although it may have been unintentional.\n\nJust play a CoD Zombies c', 'Mostly Positive', 75.96, 1.63, 0.83);
INSERT INTO reviews VALUES (64678, 2585830, 938, 'It''s basically a business side-story from the Yakuza series turned into a whole game. It''s super funny, relaxing, easy to play and to get into, it has a banger OST, cool artstyle, compelling characters and well written dialogue. Total no brainer if the vibe you get from the trailers seems appealing to you.', 'a nice impassioned story, but nothing interesting or involved about the play. like hittin a vape while reading critical theory.', 'Overwhelmingly Positive', 98.08, 19.72, 13.80);
INSERT INTO reviews VALUES (64753, 2587770, 160, '🎖️ A platina é muito fácil kkkkkk 🎖️\n\n A PIOR coisa no relacionamento é a pessoa se tornar obsessiva e tentar mata o/a ex e fazer todo tipo de ameaça a amigos e família, vejo uma porrad@ de reportagem sobre isso, é algo quase "comum" de acontecer. \n\n The Stalked é um jogo de terror curto, mas agradável, com um enredo linear que proporciona uma ótima tensão, atmosfera assustadora e alguns sustos bem cronometrados. Eu realmente adorei que você pudesse simplesmente mergulhar na história e não ter q', 'The story is bad', 'Very Positive', 93.12, 0.87, 6.70);
INSERT INTO reviews VALUES (64901, 2591010, 143, 'What is going on with these reviews?? I''m really enjoying this game. I really struggled with the Uboat game cos it was WAY too in depth (pun totally intended) for me. Ah! but what specific type of salted pork would crewman Jurgen prefer with his rations? Hmm? Oh dear me, Gunter is in a bad mood today so might not be as reliable at loading torpedos.\n\nThis game doesn''t give a rusty mackerel tin for that nonsense. It''s the first sub game where I could just get out of port and go hunting ships withi', 'This is not Sim-Lite, but Arcade.\nI left the base in Midway and had my first contact with the enemy right next to it. A lone enemy tanker. Because that''s the absolute safest place for Japanese tankers: where you least expect them. I was surprised that it didn''t moor directly at the neighbouring pier at the start.\nThe weather was clear and we opened fire at long range, hitting nothing and the tanker stubbornly continued on its course towards us. They probably wanted to have a serious word with us', 'Mixed', 62.94, 30.97, 0.30);
INSERT INTO reviews VALUES (64916, 2591280, 1612, 'Finished my 1st season in career mode, Verstappen won the WDC but Red Bull lost the constructors because Checo was down 200pts to Max. Very realistic. Would recommend', 'Really isn''t much different to the last 2 games. The graphics aren''t much better than 23. Create a team and mentality are the only real major differences. Pity Motorsport Manager never made a new game.', 'Mostly Positive', 77.54, 85.88, 74.82);
INSERT INTO reviews VALUES (64922, 2591410, 328, 'I’m starting to question my mental well-being. Why have I willingly spent this many hours playing a game about moose—moose that mine an endless supply of gems, so I can upgrade them... to mine even more gems? Is this a cry for help, or the peak of gaming? Either way, send snacks.\r\n\r\n10/10', 'Less of a "No" more like a "Eh". Overall the game is a nice timewaster, but it lacks offline progress, making it crucial you keep it open to make significant progress. I usually dont mind this in other incremental games, but that is because they are optimized for running in the background or have a mode that significantly reduces the load on your PC while you play. This game lacks that, so your pc is on load for the entirety of the time you have the game open, even when minimized. Add some optim', 'Mixed', 68.90, 125.50, 7.37);
INSERT INTO reviews VALUES (64939, 2591910, 276, '>>play My Furry Protogen\n>>playing My Furry Protogen 2\n>>realize that no irl women would never treat me so lovingly\n>>feel sad', 'If peak gameplay for you is *space* *space* *space* *space* *space* *space* *space* *space* *space* *space* *space* *space* *space* *space* *space* *space* *space* *space* *space* *space* *space*  then this game is for you', 'Overwhelmingly Positive', 95.65, 19.40, 0.22);
INSERT INTO reviews VALUES (64972, 2593370, 548, 'Somewhat spoilery for the first ''twist''.\n\nI really don''t understand many of the criticisms in the negative reviews of this game. In regards to "pedo" claims about some content about the game, I just want people to actually think critically for once. Does the game at any point endorse the disgusting actions of the protagonist? No, it in fact actively goes out of it''s way to show how he has become without morals at the start of the story, in how he describes humans and his victims as ''sheep''. Does', 'a lot of negative reviews brought up the same issues as me/have the same playtime as me, so i''m assuming we all quit after this part of the game: \n\nthe scene in particular is where the character you play has to pick between joking about threatening to r/pe a 9-year old girl to her face, or to take off her skirt so you can hit her. up until this point, there was also a lot of talk about children defecating/peeing, and it was just an uncomfortable read. i ended up refunding the game right after.\n\n', 'Very Positive', 93.61, 10.63, 0.82);
INSERT INTO reviews VALUES (64998, 2593900, 176, 'A really fascinating experience.\n\nOut of all the Chilla''s Art games, this one feels the most real one atleast in some story aspects as it deals with a really heavy and emotional situation, something that still sadly happens to this day and they handled it in a serious way which helps bring awareness to this topic.\n\nIt''s about 1 hour long and has multiple endings aswell as being able to pet a cat.', 'Chiila''s Art''s game often compare with Fears to Fathom series, but I totally disagree. Fears to Fathom''s games are short but have a lot a dense amtosphere, suspense and almost every action and dialogue make sense. They develop the story and do it very well. But in Kidnapp won''t find anything like this. Here are only boring tasks like get A to B, bring C to D. Many senseless dialogues and action. Very slow characater control. It seems like developer tried to slow down game as much as possible. \nD', 'Very Positive', 84.09, 2.83, 1.68);
INSERT INTO reviews VALUES (65023, 2594540, 739, '!! Gore Warning !!\r\n\r\nBy default the game has criminals enabled and  They can murder your customers. You then have to dissolve the bodies in acid barrels and dump the human slush before the cops find them. \r\n\r\nOutside of that, this is a chill management sim. Just make sure not to keep employees running 24/7 early on or you will go bankrupt.', 'The level of utter Disappointment with this update cannot be any higher....we get to start all over and do all the exact same stuff only now for some reason in the desert.  Instead of opening the existing map and giving us NEW rooms and themed rooms,  a coffee shop and or cafe.....new furnishings for rooms...SO many possibilities were available but they decided that this was the better option.....honestly it only makes me want to Uninstall the game completely. I guess they didn''t want to put the', 'Very Positive', 85.66, 17.77, 61.72);
INSERT INTO reviews VALUES (65076, 2595860, 205, 'steam needs more hitlers.', 'Not even a game\n0/10', 'Very Positive', 90.73, 7498.98, 0.62);
INSERT INTO reviews VALUES (65094, 2596420, 179, 'The way the main gimmick of the game is utilised is excellent. Play enough games like this and you start to develop an intuition for what kinds of puzzles and extra mechanics will show up, so it''s always great when one surprises you in clever ways. Sadly there''s no easy way to backtrack for optional puzzles, but I had fun all the same. I''d absolutely go back if there was a map or a post-game state with less tedious navigation.\n\nAlso, the writing is really good. To address one negative review who', 'Cute presentation and nice music. Original idea for puzzles but most are just too easy, areas are ending as soon as the puzzles get a bit challanging.\n\nInsufferable dialog.', 'Very Positive', 94.41, 4.05, 3.65);
INSERT INTO reviews VALUES (65119, 2597080, 220, 'If you want to play much easier Hades, get this game. \nIt is a nice game, but WAAAAY TOOOO easy for my taste. I would like to see a difficulty not in the way of increasing enemies damage and HP. I would like to see more attack patterns, specific ways to kill an enemy. Also i would like to see much more sinergies, for now all gameplay is straight forward evade, spam attack, you have something to upgrade, do it. something dropped? YE PICK IT UP (no drawbacks, no sinergy ruin) \nI will be waiting fo', 'It''s a cheap Hades clone with none of the personality. Shame too because the art style is gorgeous.', 'Overwhelmingly Positive', 96.36, 13.83, 0.28);
INSERT INTO reviews VALUES (65222, 2599270, 328, 'Oh my Science this game is so good I hope we can get a nintendo switch port with Funko pop merchandise!!!', 'Needs more he/her trans representation', 'Overwhelmingly Positive', 95.43, 5.02, 15.18);
INSERT INTO reviews VALUES (65224, 2599300, 448, 'Does anyone know how to wash underwear? I would appreciate some advice.', 'This just feels like its designed by a rude person. I haven''t felt that before with a game. You immediately run into issues that would take 10 minutes to fix, and must have surely been pointed out by countless people. So the decision was made not to fix them. That''s just rude. Grow up, man. \n\nI have never seen this game before but it looks to me like this must have performed well on some live stream and got the streamers'' audience to play/like the game. I can''t think of any other reason why so m', 'Very Positive', 87.50, 4.25, 0.90);
INSERT INTO reviews VALUES (65228, 2599370, 231, 'Pretty fun mix of the "Entity-identifying" and "Anomaly-spotting" genres. Spotting anomalies/events, and more importantly keeping track of what you''ve spotted, are the key to figuring out which special herbs and spices you have to use for your banishment recipe ritual, as the requirement for each herb is randomized each play. If you''re a fan of anomaly-spotters, then it''s definitely worth giving this game a shot.\n\nAs an added bonus, features an active dev that very clearly cares about the game, ', 'This game is very bad, the ghost/ demon legit doesn''t kill you or it is bugged and one of the 4 people in our lobby was legit invisible and we needed to restart lobby. Lighting is horrible, tried to play medium brightness but still bad to see, needed highest brightness but was still horrible.', 'Very Positive', 88.31, 23.15, 0.15);
INSERT INTO reviews VALUES (65343, 2601940, 225, 'Game is kinda brutal to play on deck.  The TDP has to be maxed with the fans raging to make it smooth.  It shouldn''t need that much power to run, so it seems poorly optimized.  This will rip through the deck''s battery, unfortunately.', 'it''s not a metroidvania. \n\nA completely linear game with 1 forced, pointless, and completely linear backtracking segment is not a metroidvania lmao.', 'Very Positive', 84.89, 1.52, 5.90);
INSERT INTO reviews VALUES (65349, 2602030, 196, 'This is the bullet heaven that I have been waiting for. \n\nA+ meta progression and very rewarding and tactile combat. The addition of co-op is also very welcomed to the genre. I wish more games had it. I also really like how each piece of gear has its own skill tree.', 'WARNING!: Uses Epic Games Store services for multiplayer', 'Very Positive', 84.18, 99.52, 0.43);
INSERT INTO reviews VALUES (65394, 2603020, 328, 'The TRVE Caesar 5.  Sort of.\n\nMechanically it does everything that Caesar did but modernized. It even has world map interactions, similar to Caesar 2 (though not as deep.)\n\nOne thing this game lacks is the personality of the Sierra games. No clicking on your civs for random bits of dialogue. No school children running through the streets as soon as you place a school. Those games had so much charm, Citadelvm is sort of straight laced in this respect and the lack of that 90''s Sierra charm is noti', 'It is Caesar 3 light.\nLess depth, simplified mechanics, distances are virtually irrelevant.\nExternal combat was added, which the original was missing, but unfortunately implemented in a way that feels rather gimmicky. Add to that, the game is not exactly a looker. \nOver all fun for a short bit, but due to its limitations gets old very quickly.', 'Very Positive', 81.40, 1.02, 31.90);
INSERT INTO reviews VALUES (65453, 2604480, 110, 'I have wanted a good Tram simulator, and I think I have found it! With good graphics and ok physics this is pretty good. It is a little dry of content though.', 'First Negative : Dovetail Games\nSecond Negative: Not up to what i expected, To purchase trams its not money but some sort of reward points you earn, Customisation on trams is just the front logo, No colour changing NOTHING Significant at all.\n\nDeffo not worth the asking price at the moment.', 'Mixed', 58.18, 53.02, 2.65);
INSERT INTO reviews VALUES (65492, 2605640, 151, 'Well, the idea is really good, but! It doesn''t scare me at all, I wasn''t scared, the good thing about the game is that I played it offline and noticed that as soon as you start a new game the level is regenerated, the puzzles only change slightly, the replay value is limited.', 'i give it 1/5. some part of it is glitchy and buggy. particulary the security box with the four toggles whatever its called. had to restart a few times. all of a sudden youre trapped inside a coffin, at least give us the context. this game shouldve been free.', 'Mostly Positive', 78.81, 0.98, 0.93);
INSERT INTO reviews VALUES (65537, 2607060, 738, 'A really enjoyable take on the style made popular by TAB. Not a clone at all, just a well-made, honestly under-rated game in the genre. I love the setting, graphics, and balance. \n\nFor the hours I''ve already put in, I''d pay double the price, and I intend to put in many more', 'I wish I could get a refund for this game but I already played over 2 hours of this game. The concept for the game is neat, however this game has the most annoying consumption of resources that I have ever played in any RTS/Tower Defense game. It is so bad that you can softlock your playthrough if you placed too many water, electricity, and worker home resources because you''re only given 5 resources found only in the basic mine. So if you didn''t make sure to place down a mine before you placed a', 'Overwhelmingly Positive', 96.48, 119.38, 12.08);
INSERT INTO reviews VALUES (65578, 2608040, 240, 'Travellin'' Cats devs are good devs.  They aren''t like those copy cats that try to ride the coat-tails of other devs success.\r\n\r\nThis game gives you a giant black & white artwork screen where you are supposed to find 100 cats hidden within the art.  You can zoom in and the image is still crisp and sharp.  Some cats are just sitting there out in the open, easy to find while others camoflage themselves to try to blend in with the backdrop.  Some cats are tiny and hard to see while others are large.', 'Cats nice. Telephone not.', 'Overwhelmingly Positive', 98.33, 4.43, 0.47);
INSERT INTO reviews VALUES (65590, 2608270, 1613, 'This game is mechanically superior to its predecessor to the point that replaying the first game is extremely painful for me.\n\nHOWEVER the first game''s story, flow, mission design, and scenario placement are all superior to this one''s.\n\nSo the developer is remaking the first game in the second game''s engine.\n\nMe happy.', 'It''s a hotline miami, except that the controls are bizarrely bad, stealth is extremely necessary, and not necessary like "kill one here and there stealthily and advance the game if you want a more dynamic game", no! It''s a stealth that if you think about making a dynamic game ALL NPCS WILL GO AFTER YOU, and there is no weapon throwing or anything you can do lol. The reviews are positive but I can''t understand why, it''s a pretty cool game, but to be honest it''s the same as the first in almost eve', 'Overwhelmingly Positive', 96.59, 19.20, 0.42);
INSERT INTO reviews VALUES (65595, 2608350, 451, 'This is just a straight up upgrade to the last title with a little bit more story and a couple new weapons. I like it quite a lot for it''s simplicity and replayability, but I swear to god if we don''t get a third title with a happy ending for the sisters, I will burn this place down.', 'One important aspect of the game are the coworkers you can hire to help you; they are colorful and entertaining and getting all of their endings and scenes is one of the major reasons for replaying the game.\n\nHowever, you can only hire them if their card appears among the 3 choices after a day, and if you have the necessary credits. The problem is that, if you don''t get the character you want by day 20, you already missed one of their scenes, and it is not rare to restart the game over and over ', 'Overwhelmingly Positive', 98.45, 10.02, 6.22);
INSERT INTO reviews VALUES (65607, 2608620, 626, 'This is world''s least sexy porn game. It''s about a lonely naked pervert with grandma issues and the world''s most annoying voice wanking on things and pooping on the floor. This is a disturbing ultraviolent vignette about a sad, broken man struggling with impulses he cannot control. \n\nIf this was a bad joke, it would have stopped a lot sooner. This game goes so far beyond simple "bad taste" or "edginess" that I can''t help but feel there''s actual commitment to an artistic vision going on. The fact', 'Probably the funniest, most idiotic, most disgusting game i have ever played. Truly a waste of time, but gave me and my friends a few awkward chuckles. You do get to poop on the floor on command though.', 'Mixed', 67.57, 1.30, 1.40);
INSERT INTO reviews VALUES (65649, 2609610, 482, 'In concept, the game is fantastic, all the ideas are great, and the execution of most is good, my biggest issue is the lack of variety, making the grind very repetitive, though, guns feel great, looting is nice, enemies are pretty good.\nThe first map definitely needs work in interactability, though the second one gets that a lot better, generally, a great game with TONS of potential. I’m looking forward to the future.', 'In short this game is just way too bare bones at the moment.  I did 3 raids, each time there were 2-3 bandits on my map (which is tiny), there were maybe 2-3 items of loot that could be looted, the vast majority were just empty car husks, open garages with nothing in them, etc.  I also realized that my dog companion can just take dudes out while I hide behind cover and figure out how to reload lol.  Just isn''t very fun yet, needs more loot, bigger maps, more variety in the maps, etc.  I know it''', 'Very Positive', 83.40, 5.37, 0.82);
INSERT INTO reviews VALUES (65774, 2613060, 194, 'Very addicting game, great game to play while listening to a podcast or just taking a minute to chill.  Needs more content for the base game or at least discount the DLC in the steam store heavily.  Would recommend.', 'Releasing a paid DLC when something as basic as cars driving in the recycling center get stuck behind an invisible wall says a lot about the dev''s mindset.\n\nFinish the game, then release DLCs.', 'Mixed', 66.49, 350.68, 0.97);
INSERT INTO reviews VALUES (65883, 2615670, 208, 'I''m a big fan. The setting is interesting, the characters are both funny and cute, and there''s a lot to enjoy. Especially for its price point. You''ll be surprised by what choices, which you assume are innocuous at most, will end up taking you somewhere you definitely didn''t expect. My only problem is. . . that dang locked door by the well! Does it ever open? Am I too much of a silly goose to solve its mysteries? Its smug aura mocks me. I want to see it destroyed. I want to marry it. I don''t know', 'uh. yeah no. despite it being very much a 18+ game, it feels almost childish and gaudy the way they keep shoving how adult it is in your face. its very... hazbin hotel riverdale-esque and its just painful to read through the 17th dialogue of quill being a hoe. wow cool the teachers are extorting students and cooking up drugs in class haha that is so funny and weird!!!! idk, it all just reads like a comically bad bl manhwa. \n\nif you don''t really care about writing and just wanna see hot guys bone', 'Overwhelmingly Positive', 97.60, 20.82, 1.78);
INSERT INTO reviews VALUES (65897, 2616140, 192, 'This game is amazing if you like renovation games, and designing rooms this game is for you, you get to cook and drive around the world i would recommend this game 100 percent.', 'The game is a great simulator game, if you enjoy gas simulator you can really like it. However the turn off for me is the AI. Every time a dialogue pop up, it''s on a horrible ai voice, same with every customer who talks to you all in Ai voice. It''s a shame a would really prefer to have a no voice at all than that but again, if you don''t care about that and you just want to focus on the simulator, you surely gonna like it.', 'Mostly Positive', 78.65, 10.20, 0.85);
INSERT INTO reviews VALUES (65908, 2616460, 519, 'I played this game as a kid back in the early 2000s, on a CD copy upon my grandfather''s off-white Intel Pentium desktop PC; I didn''t beat it at the time (only got about halfway through), but neither did he, since he got to the last level of the game and found it too challenging.\nA decade or so passed, and I played it again, a GOG copy that i got from a friend; I beat the game, and genuinely understood why my grandfather never beat the game, because that last level was very early 2000s difficulty', 'This version of the game is unstable - freezes randomly. Cant even exit the game without it locking windows - Steam do some better quality control of what you offer on your platform. Had great memories of the original but this is just non-performing on modern systems it would seem.', 'Very Positive', 94.99, 29.85, 8.03);
INSERT INTO reviews VALUES (65950, 2617700, 329, 'Do you like Terraria?\nYes?\nDo you like Core Keeper?\nYes, too?\n\nThen you will love this game, give it a try!\nAlso it feels illegal for how cheap the game is...', 'Constant crashes with losing progress, badly optimised resolutions, day/night cycle sometimes skips in a span of 1 second, lights won''t work in low performance mode and it''s not even all bugs i discovered. It really ruins the first impression of the game for me. Game itself is fun, but in current state not recommended, better wait for a couple of patches.\n\nEDIT: This game is unbalanced, broken mess. Fun disappeared after 10 hours of crashing, losing progress, repeat. Devs can''t fix anything, the', 'Very Positive', 90.88, 23.22, 31.68);
INSERT INTO reviews VALUES (66029, 2619650, 508, 'curse Olexa for showing yet another great game on his channel', 'Boring, not worst the price, regularly crash steam and my PC something fierce. Badly developed, badly executed. Good intention. Worst than I thought, crash my graphic card. Thought it was steam, broke my computer. I wonder how many of these positive reviews or fake.', 'Overwhelmingly Positive', 95.87, 11.28, 7.65);
INSERT INTO reviews VALUES (66049, 2620240, 121, 'Pro: fun with friends and with recent changes the difficulty has been toned down so much that you can enjoy it well!\n\nCon: No tutorial, cant find multiplayer servers since not many play this game :'')\n\n(I cant fill my playtime only because my friends aren''t all available and multiplayer doesn''t have enough players)', 'The game play itself is decent, and the art style is awesome. But there need to be some changes made and I think most would agree. First of the grind it self is good but there''s no reward for the effort. What is the point of exorcising the creatures just for them to come back? And with them coming back you run out of funds quickly trying to keep up. Secondly I can''t think of any game I''ve played that a boss can not be defeated, and I''m coming from the Coleco days so I''ve got many decades of expe', 'Very Positive', 82.64, 22.03, 39.12);
INSERT INTO reviews VALUES (66072, 2620730, 172, 'This is a fantastic game to scratch that Hollow Knight itch while we all wait for Silksong. It''s a little shameless, in terms of similarities...ok maybe a LOT shameless actually, especially in the early mossy area. I found myself saying, "Oh c''monnn!" more than once, but as far as clones go, I don''t mind them, as long as they imitate a game I love and do it well. And this game definitely does that. Like it really just felt like I was playing a modded version of Hollow Knight. Combat''s a little d', 'you are a disgrace to gaming development.\n\nNo shame or respect towards players or colleagues at all.\n\nStealing art from the best game in the genre? That''s the lowest I ever saw', 'Mostly Positive', 77.33, 23.23, 0.08);
INSERT INTO reviews VALUES (66099, 2621420, 115, 'I very much enjoyed this game, so much so that I was happy to go back and pick up some missed achievements. I hope this dev keeps making more games.', 'I wish I could recommend this. I was intrigued because it seemed right up my alley. It''s not a bad game, it worked fine, graphics were kinda cool, premise seemed interesting, I should have loved it. \nMy issues are the length, and the gameplay. It''s just too short. Feels like a demo. Not finished. \nAnd gameplay wise, I just felt let down by the ''puzzles''. They were very, very simple. I could tolerate that simplicity if the atmosphere was a bit more engaging, but at the end of the day it just seem', 'Overwhelmingly Positive', 95.65, 1.65, 3.28);
INSERT INTO reviews VALUES (66139, 2622380, 41672, 'All the returning bosses got me concerned but thankfully there is no Soldier of Godrick this time, I can at least get past the tutorial now', 'No duo option, had random people join to just run off and do their own thing. Let me duo with my mate...', 'Very Positive', 84.28, 46.50, 11.32);
INSERT INTO reviews VALUES (66200, 2624280, 1014, 'I''m gonna be honest, the first 420 Blaze It game is a masterpiece, and this would be a worthy successor. BUT. One thing this game needs in order to be that.\n\nPlease devs, make the MLG effects more badass and impactful just like in the first game. Like the screen flashed green when you killed someone, and a gif played, with random texts like: f**king hax, noscope 360, aimbot, rekt and everything like this, Now its just a few PNGs with hitmarkers flying around, which is kinda lame tbh.\n\nI enjoy th', 'too good, make it worse', 'Overwhelmingly Positive', 98.42, 15.82, 3.13);
INSERT INTO reviews VALUES (66235, 2625420, 2803, 'its like the the long drive game but better. this is a prime example of why video games can copy game mechanics and have a completely different game.', 'So basically the long drive but with better graphics but bigger price tag it''s a good game but I''d wait for the price to go down', 'Very Positive', 81.23, 23.68, 0.13);
INSERT INTO reviews VALUES (66243, 2625620, 435, 'This game is AWESOME however there is a problem.\n1. Vehicles do get stuck so it would be nice if there is a respawn car button on the vehicle menu.\n\nSo developers if you read this please make this happen. Also I would love to be part of your developing team for this game to make it even more AWESOME.', 'Not a chance would i recommend. I vary rarely leave reviews, so if you are undecided on this game DO NOT BUY IT. there is so many issues that never get fixed, instead what you get are pointless updates that are so poorly done. The latest ''BIG UPDATE'' that has been months in the making is the casino which has two games blackjack and some sort of shooting thing, in a dealer simulation game!!! make that make sense.  a card game to possible help you raise money ? an hour in I made less than a grand.', 'Mixed', 61.84, 37.45, 41.32);
INSERT INTO reviews VALUES (66318, 2627570, 307, 'Played in a public lobby with sponge (developer). He brought the smoke. Don''t underestimate him.\n\nGreat Game though.', 'Almost no Microphone settings apart from picking which one, this means that the microphone quality ingame is terrible and some mics wont even be picked up so not all of my friends can use proximity chat but have to talk on discord, if this is not fixed we will all refund until then this is a negative for us.', 'Very Positive', 90.23, 10.45, 2.57);
INSERT INTO reviews VALUES (66347, 2628420, 339, 'This game is super enjoyable. It''s relaxing...it has wonderful differing frog species sounds, it''s both an idle and collection game. You can even mate the frogs to gain better stats. It''s colorful and lots of fun. If you''re looking for a game that makes you feel relaxed and eventually sleepy get this one. It does wonders for the stress of political aids.', 'This game IS NOT IDLE guys', 'Very Positive', 92.92, 138.95, 0.63);
INSERT INTO reviews VALUES (66353, 2628570, 163, ' First off, for anyone looking to see how the game plays, keep in mind it requires a decent amount of waiting on resources to generate. For anyone into idlers, it''s not necessarily bad, but just keep that in mind if you''re thinking of buying.\n\n Now as far as the rest of the game, I think that It''s just good enough for the current price (50% off). The current state the game is in feels more like an early access. Some people are reporting bugs here and there are still many things that could be add', 'I am a bit conflicted about Stellar Settlers, but in it''s current state, I don''t think I can recommend it. I got it because it looks like a cute small city builder or colony sim, and it is to some extent. The main gameplay revolves around placing pods with different effects, like generating resources, treating sick settlers or acquiring research points. Some of those pods only work above a certain floor and all have to be connected with tunnels to work, so you quickly end up with a big interconn', 'Mixed', 52.76, 4.43, 1.20);
INSERT INTO reviews VALUES (66410, 2630080, 133, 'they are coming\r\nme too', 'Glitches on steam deck mean i cant cycle through weapons or suddenly can''t fire my weapon = unplayable', 'Very Positive', 94.74, 6.75, 0.28);
INSERT INTO reviews VALUES (66458, 2631250, 481, 'I would rather play a game that is rough around the edges but full of interesting ideas, than a polished one that is completely uninspired and chases trends.', 'Cool idea for a game very unique but defineitly not worth AAA price tag for indie game\n\nthe game is janky control aren''t smooth, english translation is wierd, Graphics looks like a 15$ game\n\nwait for discount and try it your self', 'Very Positive', 88.57, 14.98, 16.53);
INSERT INTO reviews VALUES (66517, 2632930, 230, 'It is entirely possible to finish the main story of this game and 100% it in the process within 2 hours and request a refund.  I''m choosing not to request that.\n\nThis game isn''t anything mind-blowing, but there is definitely a lot of passion and hard work put into it.  You play a man who examines the schedules and lifestyles of multiple potential targets in order to deduce the one he believes he is supposed to sacrifice to a malicious god that threatens to destroy the world.  Upon doing so, you ', 'I can only recommend this game to a certain type of person: the type of person I wish didn''t exist.', 'Very Positive', 87.83, 1.95, 0.18);
INSERT INTO reviews VALUES (66523, 2633170, 143, 'First season, my Dolphins went 16-1, and then Tua got hurt the last game - right before the playoffs. Backup quarterback, Tyler Huntley, put on a majestic 3 interception performance, we get blown out by the Bills, and we still haven''t won a playoff game since 2000. 10/10 realism.\n\nUI is pretty clean once you get used to it. The real world rosters are great but using random rosters is pretty cool too, lots of replay value there. \n\nI just do the GM stuff and let the AI handle the playbook/in-game ', 'I really miss all the windows that you can have open on Front Office Football 8.  You could look up your Corner in one window, a Free agent in another, and look at your depth chart, Roster Requirements  in others. Was really fun to be able to do that. The new interface looks smoother/ cleaner and really does have more information. However, sadly it takes more clicks to get to the other screens while also not being able to look at them side by side. Not a deal breaker for some, but I will stick t', 'Mostly Positive', 78.32, 103.60, 2.00);
INSERT INTO reviews VALUES (66586, 2634950, 7529, 'The racing genre is saved.\n\nGenki, you are awesome. 18 years out and the TXR experience is the same as ever. \n\nBuy. This. Game. And support Genki making the game even better.', 'Roll Racing: The Video Game. Gameplay loop is press accelerator and then wait until you win or lose. That''s it. That''s the whole game.', 'Overwhelmingly Positive', 96.32, 13.63, 5.23);
INSERT INTO reviews VALUES (66596, 2635340, 100, 'I would play this game even without the girls. Although, why does this game have no achievements. -', 'For a yahtzee game it is not the worst, but for a lewd yahtsee game it is not very good. 2 girls with 2 scenes each. completed in 18 minutes, and crashed at the end. I bought it on sale for 2$, and i reccomend you do too (if you have to purchase it at all).', 'Overwhelmingly Positive', 95.00, 1.13, 0.30);
INSERT INTO reviews VALUES (66646, 2636420, 282, 'Genuinely the best horror game of the screamer genre. It is not RE, not outlast, nothing even remotely close. If they base off immersion, this one is fully screamer-based. However, it was scary, very scary. From dozens of horrors played, this game is actually the one where I feared to open doors or to look from the window. Took a few water and air breaks.\n\nI don''t understand why people rate it so low. I mean, this game has a relatively small location, indeed lacks new ideas, but the game is just', 'This game was hard to rate.\n\nOn the one hand, the game looks really good and has a pretty decent start to it.  On the other hand, the games story kind of gets lost after a bit and the quality of the scares/mechanics starts to fall off hard.\n\nThe game is so cheap when on sale that I am sure you won''t be too disappointed by the purchase but if you are looking to buy a top quality game overall, then you probably won’t want to pick this one up.\n\nIf you are looking to see the game before you buy, I h', 'Mostly Positive', 74.11, 2.30, 1.18);
INSERT INTO reviews VALUES (66673, 2637070, 105, 'I bought this game because I was very horny.', '- It''s a goon game but does absolutely nothing with it. \n- The gameplay is very repetitive\n- The visuals are just another ue4/5 slop. The models are probably ripped from daz3d with the ugliest hair cards possible, and the VFX are from the free asset pack everyone uses. You can''t be more of an assetflip of a game yet some reviewers call this "stunning". Literally 0 knowledge in gamedev and probably watch asmongold or something.\n\nI would give it a thumbs up if either the goon, or gameplay aspect w', 'Very Positive', 89.52, 10.03, 3.18);
INSERT INTO reviews VALUES (66686, 2637940, 132, 'I think overall the idea for this game is a solid one. \nI think it needs time or mods to really make it super fun right now.\nif you want to just flip cars legally the progression is really slow, profit is just so limited. \nyou can also steal cars but the risk is pretty crazy so i''m gonna revisit this game after the major updates.', 'I love the idea but I don''t like the implementation. A Used Cars Simulator should focus on that and not on eating, drinking and peeing. That''s just my opinion and what I''m looking for. I do enough of that in my own life so this game is not for me.', 'Mixed', 63.64, 12.62, 0.42);
INSERT INTO reviews VALUES (66689, 2637990, 3893, 'Duck Detective 2: The Baloney Burglar\r\nDuck Detective 3: The Taffy Thief\r\nDuck Detective 4: The Ravioli Robber\r\nDuck Detective 5: The Pie Pilferer', 'The game is VERY short, and I feel like I wasn''t the target audience at all. This is something a very young child would enjoy as an introduction to gaming. It''s not a bad game, it just missed its mark and I was fooled by the overwhelmingly positive rating. The story is too simple, you only get to solve 1 case, I was half expecting after solving the mystery to have more cases to solve, or for the story to evolve in some way, it felt like an "intro" mystery to get you accustomed to how the game pl', 'Overwhelmingly Positive', 95.25, 2.00, 2.50);
INSERT INTO reviews VALUES (66707, 2638370, 4681, 'As somebody who has been very much feeling the concern of quality in the recent games, especially in the anniversary line-up for the FNAF Series, this game was such a welcome surprise. I was excited about this game from it''s initial reveal but....Holy. Crap. \r\n\r\nThis game is absolutely amazing from it''s environments to it''s sound design to the story, everything about it is such a fresh and incredible ride for this series and I genuinely cannot say enough good about this game. I am genuinely amaz', 'It drags on for too long, and the gameplay gets repetitive really quickly, they never really introduce any new mechanics and the entire game boils down to luring spring bonnie into a room and hiding, then going back and forth between the ball pit to find an item you need and to use it in a different area. If you are not into fnaf for the lore I would not recommend this game.', 'Overwhelmingly Positive', 95.64, 10.50, 5.83);
INSERT INTO reviews VALUES (66711, 2638560, 303, 'I recommend this game because it allows you to do things that are impossible in real life, like talking to girls and having sex with them.', 'This game is the ultimate lesson in false advertising. You’re the "chosen one"? Yeah, chosen to endure 2.5 hours of a "story" that feels like it was written by an AI stuck in medieval fan-fiction mode.\n\nThe "adventure" is as thrilling as microwaving leftovers, and the "choices" are about as impact as deciding whether to wear socks today. And let’s talk about those "sex scenes"—if you can even call them that. Blink, and you’ll miss them. I’ve seen more tension in a PG-13 rom-com.\n\nIf you’re here ', 'Very Positive', 84.82, 6.77, 1.03);
INSERT INTO reviews VALUES (66794, 2640560, 251, 'Play my game', 'I like this game, but sadly too short and therefore not really worth the money.', 'Very Positive', 80.48, 0.93, 0.57);
INSERT INTO reviews VALUES (66837, 2641490, 115, 'i played the demo extensively and I''m quite enjoying the full game so far. While it''s a bit easier than ZERO Sievert, I like the fact that i can play without getting one shot by the enemies every few runs.\n\nthe artwork and sound design are great and the cyberpunk vibe feels well polished.\n\nIF you''re a fan of extraction shooters, I wouldn''t pass this one up. you can''t beat the price.', 'Game breaks with each update. Dev deletes posts critical of updates breaking the game.', 'Mostly Positive', 78.26, 0.78, 60.98);
INSERT INTO reviews VALUES (66969, 2644360, 145, 'It''s a fun old-school game of puzzle solving, combat, and exploration. Worth $10.\r\n\r\nPlease allow us to remap keys though - I don''t know why that''s not a thing in 2024 when a lot of us are left handed.', 'Kingsgrave is a puzzle exploration game with a unique structure and a lot of jank. You''ll spend a lot of time pushing at the edges of the map, trying to find the resources you need to unlock that next ability, which in turn will give you access to more of the map. The puzzles are not too bad, and the under-tutorializing of the mechanisms leads to some great "aha" moments, but there''s also a lot of frustration to be had. \n\nWarping around the map to trade resources for other resources quickly beco', 'Mostly Positive', 73.10, 26.20, 3.67);
INSERT INTO reviews VALUES (66972, 2644470, 949, 'the game came out 25 minutes ago and i already lost all my friends\n\n10/10, will play again when i find new friends', 'Don''t play this game. Its actual dog shit and if you have friends who say they enjoy it they are actually sadists and want to see you suffer', 'Very Positive', 94.84, 3.52, 7.20);
INSERT INTO reviews VALUES (66980, 2644610, 559, 'I''m giving 60% and very conditional recommendation, especially if you''re fan of Lovecraft.\n\nSomeone has already formulated it perfectly in another review - the game does everything right, except the gameplay. It has story. It has visuals. It has pretty cool concept of choosing next events from "travel decks". And, yeah, there''s also the combat which is by far the least exciting (and takes most of the time).\n\nThe cards are too similar and don''t really synergize much, the main decision made in mos', 'The game in its current state is way too hard, there are many unbalanced mechanics. This is my experience from Act I and the first character, the detective. \r\n\r\n- You are forced to prolong fights to upgrade cards, since they get upgraded from X uses. This turns into spamming defensive cards to upgrade all your cards in fights. \r\n- If you get unlucky you just run out of fuel at the start of Act II. Your fuel doesn''t refill at the start of the act, neither does your/your companions health.\r\n- Your', 'Very Positive', 90.70, 29.85, 4.67);
INSERT INTO reviews VALUES (67059, 2646460, 5053, 'I like this game.  It has the potential for hundreds, or even thousands, of hours of game play.  \n\nIf I had to pick one thing that annoys me, it''s when any company announces a "Free DLC" before their game is even out of beta (Early Access).  Just release it as a normal update and stop acting like you''re giving us something for free.  We gave you our money to help you beta test your game, I don''t need "free stuff" to recommend your game to others, I just need you to continuously improve your game', 'This game was really fun for a short period. They recently added server transfers and it has ruined the game. Last night a group of 15+ people came in and wiped the whole server. They were on the top tier gear and rides and everything. Totally just ruined this game. They sent a message to the whole server basically saying we''d have to "pay up" to stop getting raided.', 'Very Positive', 80.13, 135.43, 260.37);
INSERT INTO reviews VALUES (67084, 2647060, 240, 'Climate change, wars, rising political tensions, global inflation, and my boss... Here I am, with a controller in one hand and my dick in the other jerking away one problem at a time.', '1. Cannot be played with one hand\n2. No automatic control\n3. No handjobs, oral sex, or breast sex that interact with the player\n4. Poor anal details\n\nTo be realistic, players play this type of game just to masturbate. If players are given the ability to masturbate while playing, even if there is no model creation, it will be acceptable and receive more positive reviews.', 'Mixed', 67.92, 1.05, 0.68);
INSERT INTO reviews VALUES (67089, 2647230, 422, 'is good with cheat engine so u dont hv to grind for gacha', 'The developers wasn''t able to add Yozora Mel in time, and because it seems that terminated members are technically taboo, "Cover just doesn''t want to publicly admit it" it''s very likely they will never add Mel ever, hence personally I don''t like the game now. \n\nIf by any change or miracle the developers decided to still add Mel along with the first gen members, I will immediately change this review.', 'Very Positive', 85.31, 14.02, 17.12);
INSERT INTO reviews VALUES (67094, 2647680, 589, 'The game was released on the day that mankind first used an ICBM in actual combat. \nI don''t know if it''s an eerie coincidence or if the publisher intended it to be.', 'As much as I enjoy the game and the first one. I cant honestly recommend this game to anyone new to the genre. There are just to many bugs I have personally ran into that ruin the game for me.  I will continue to keep an eye on the game but I lost my sanity trying to deal with the bugs.  Posting on the discord gets you a response but these issues should''ve been found in play testing. Which makes me wonder if they play tested it at all.  Sorry guys.', 'Very Positive', 89.81, 1.13, 17.63);
INSERT INTO reviews VALUES (67098, 2647820, 162, 'Spiritual successor to Motherlode, with lots of great variety in different depths having different biomes and dangers. Great game.', 'Too many things cause insta-death without explanation making you lose a ton of progress.', 'Overwhelmingly Positive', 96.91, 13.67, 18.05);
INSERT INTO reviews VALUES (67107, 2648050, 249, 'So far, it seems just like the original but better. The lighting and graphics are a straight upgrade, and as such the animations don''t feel as janky and stilted as they did in the original. The audio is much better, and the music has been remastered with apparently new tracks I have yet to hear. There''s been some new features, like the avatar for Sam''s dialogue choice wheel being a hand-drawn animation rather than the 3D render the OG had (it looks WAYYYY better), the fabled Nutri-Specs have bee', 'Don''t support companies that censor art.', 'Overwhelmingly Positive', 99.20, 4.20, 24.67);
INSERT INTO reviews VALUES (67150, 2649080, 593, 'It''s a bit easy for a game in its genre, but it knows what it is and delivers fully. Excited to try out ice cream in November, but as it is, it''s a bit scant for things to do once you''ve unlocked all of the recipes (unless you care about achievements). I think I got my money''s worth, especially considering there''s more coming.\n\nIf you''re not very good at time management games, get  it at any price, the developer''s price point is, in my opinion, right on for a game of it''s scale. If you''re quite ', 'fun concept as It''s basically the same as plate up!, however, the game is so easy there is absolutely zero challenge to it. There''s basically no point in having multiple tables as customers come one at a time, with plenty of time between, and there''s never a case of stretching for time. I literally finished my first run with 2000 extra coins with nothing to spend it on, and every encounter where I had to serve, I would have all 4 tables with a coffee waiting for customers to arrive.', 'Very Positive', 93.76, 5.70, 2.53);
INSERT INTO reviews VALUES (67181, 2649970, 699, 'As a girl its nice to be able to play as one. I do wish the husband was hotter or gets broken up with since he''s not exactly easy on the eyes. Other male characters are pretty good looking tho so no complaints. fell asleep with the game running so the hours arent super accurate in terms of playtime.', 'TLDR: Go play Desert Stalker\nI really wanted to like SOB, but the game fell short in a lot of ways that make it an unpleasant experience. The biggest issue is how the game forces you into situations without giving any real choice. I understand that the story revolves around corruption and cheating, but your decisions don''t matter because the mc ends up cheating, no matter how you want to play. \n\nThe game forces relationships with characters, even if it''s not the direction you want to go in. It’s', 'Very Positive', 92.99, 19.82, 4.27);
INSERT INTO reviews VALUES (67238, 2651280, 8174, 'With great graphics come great system requirements', 'EDIT: Ladies, Gentlemen, Otherly Decideds, it seems we have an Alien: Colonial Marines Typo Situation again. If you go into the base game directory and shunt two files "dstorage.dll" and "dstoragecore.dll" into a new folder, a lot of the game''s most serious issues that I''ve reported oddly.... go away. I hope the porting team at Nixxes implements a better, more permanent solution, but I''m delighted to be able to get to work on a more FUN version of this review in time.\n\n\nHold off on buying until ', 'Mostly Positive', 77.95, 40.17, 113.77);
INSERT INTO reviews VALUES (67272, 2652000, 306, 'Played all the games twice, theyre fun and finally having an 18+ jackbox is great. The only thing is it shouldnt be $21 by any means for only 3 games. The new game is a bit lacking but it can be interesting', 'Unfortunately, as a fan of the Jackbox Party Packs who plays them with friends all the time, I can''t recommend this pack. There should have been the traditional 5 games to choose from but there''s only 3 this time which is very disappointing. Honestly after trying each game, Fakin It: All Night Long is amazing, with remote integration it is a fantastic game to play. However, the other two are subpar. We didn''t need a dirty version of "Drawful" as there was 3 versions before it and "Let Me Finish"', 'Mostly Negative', 28.43, 3.90, 4.32);
INSERT INTO reviews VALUES (67330, 2653790, 3838, 'This game made my head hurt severely. I''ve memorised every goddamn inch of that hallway, and I still somehow get it wrong. Also, the walking guy needs to just shave it all off, his bald spot was so bad I almost turned around thinking it was an anomaly. I actually found a secret shortcut to the exit in record time… Alt + F4. 10/10, would leave again.', 'The Backrooms concept and it’s overbearing grip on psychological horror games…\n\nAnomaly games are immersive but after some gameplay you are desensitized to what these games have to offer. After a good while on this game specifically, you will find it to be nothing more than a W key holding, dragged out, boring chore.', 'Very Positive', 94.03, 2.55, 0.42);
INSERT INTO reviews VALUES (67341, 2653940, 1526, 'The bar isn''t set particularly high, but Star Trek: Resurgence is the best Star Trek game I''ve played in years. While Resurgence is not without flaws (the graphics and controls can be clunky to say the least), the game truly shines in the story and acting. Above all else, this felt like playing out an episode of 90s era Trek. An absolute blast from start to finish.', 'Initially it feels like star trek - dialogue choices feel important, but very quickly you realize that this game is a disneyland ride. It feels like the right atmosphere, but you are on a single track without any truly meaningful options. The game is like a series of cutscenes tied together with simplistic minigames. There is no true adventure to be had here.', 'Very Positive', 89.45, 15.45, 2.78);
INSERT INTO reviews VALUES (67361, 2654470, 197, 'No, simply peeking up an anime girl''s skirt does not count as "Frequent Nudity or Sexual Content". I refuse to play by the rules of modern sensibilities, when the average western game can get away with far more explicit content with nary a wink in its direction.', 'no nudity', 'Very Positive', 89.34, 2.72, 4.32);
INSERT INTO reviews VALUES (67405, 2655580, 122, 'This is actually a pretty scary game lol. It’s a walking sim, you’re never in any real danger, but man, there’s a few segments that really freaked me out lol. They’re jump scares of course, which is synonymous with this type of game, but they’re good ones!\n\nGraphics are great, performance is good, sound design is good, the only thing I would ding it for is lack of native controller support. I set one up in 2 mins. It’s 2025, all games these days should support controllers. Overall I really enjoy', 'Unfriended the dev and gave him his money back', 'Overwhelmingly Positive', 96.72, 1.20, 0.47);
INSERT INTO reviews VALUES (67430, 2655960, 171, 'Can''t you change Wendy''s hairstyle and face shape a little bit? Do you really think she looks pretty? Or is she just an annoying character created for the plot. Even if she''s an annoying character in this season, she should be made to look beautiful so that people can look forward to what will happen to her in the next season, the wide forehead and thin chin, coupled with the twin ponytails, I really feel that there''s something wrong with your design of this character. And the skin texture of Pe', 'Buy only at a big discount\nBoring, nothing new, no voiceovers, animations haven''t gotten any better', 'Very Positive', 80.12, 81.73, 12.47);
INSERT INTO reviews VALUES (67513, 2657900, 114, '*SPOILERS*\n\nI think the game is good, runs well, immersive and pretty unique style artistically. A few key notes though, would''ve appreciated more game-play aspects or some form of difficulty to really consume the tenseness of the game. Lastly, I think the story is left a little too abstract to really get a take away at the end of the play-through. Also, a few jump scares never hurt if done properly, unless you have heart problems haha!\n\nI''ll give this a solid 6.3/10, I play a lot of horror game', 'I cannot give my opinion on this game even though I fully completed all endings. I neglected to look at the AI generation disclosure before I purchased it. This is my fault as I refuse to support AI generation at all, and so I will not refund this. Due to the presence of AI generations, the quality of it is compromised. It is despicable if that disclosure is honest for them to taint this experience in such a minuscule way that is extremely easy to get around. If they are not honest, which is a f', 'Overwhelmingly Positive', 96.49, 0.78, 0.97);
INSERT INTO reviews VALUES (67537, 2658450, 1308, 'needs a graphic settings ASAP. dont see how a remake being released in 2024 cannot include any graphic settings other than resolution. the game looks good but id rather scale it down to where my pc can handle it smoothly.', 'Cannot recommend at this price in this state.\nGlitchy scene transitions. QTEs not working properly.\nCel shading removed. Removal of key licensed songs.\nLacking PC options.\n\nEDIT: Thanks to music community mod and the first patch, things are much better. If you are still on the fence, wait for a sale and a few more patches.', 'Very Positive', 87.16, 2.08, 7.33);
INSERT INTO reviews VALUES (67538, 2658470, 349, 'Neat game, very creative!  Quite short though, probably around 2-3 hours to beat.  Some decent puzzles, nothing too outlandishly hard by any means. Definitely had to use the hint system a couple times.  I''d recommend it, to try something new. Admittedly the $15 price tag is a bit rough for the length, but hey it''s all subjective.', 'I loved the prologue and the demo so I bought the game. Is is unfortunately full of meaningless puzzles and sadly the game itself is pretty boring. I died almost 20 times and played really slow and only took 3 hours or so to finish the game. It is really short. The demo and the prologue themselves felt more fun and long. This amount of gameplay should be at least 1/3 of the game.\n\nIt has bugs, not so logical puzzles and really stressful parts where you need to run around like a headless chicken,', 'Very Positive', 94.27, 1.90, 3.08);
INSERT INTO reviews VALUES (67555, 2658720, 168, 'I enjoyed the first two games in this trilogy a lot, and I feel like this one builds on what came before, both mechanically and narratively. The art that I liked in the previous games is still good and it feels a little more polished on how it is animated and integrated into the story. I''m pretty comfortable with the setting and rules of VtM - this game definitely feels like it rewards familiarity with it, and the creators feel like they understand the world.', 'Worst installment of the series.\n\nThere is a Hunter Threat gauge that goes up if you use your vampire Disciplines too much, and if it gets too high then you get a bad ending no matter how many times you lower the Hunter Threat afterwards. However, there are multiple points in the game where *you have no choice* but to use Disciplines. Many of the choices that trigger Hunter Threat going up are really mundane too. You aren''t turning into a bat or destroying a building. Even things that should be ', 'Mixed', 66.07, 16.48, 0.67);
INSERT INTO reviews VALUES (67570, 2659050, 183, 'The true successor to The Movies. Engaging, fun, thought- and creativity-provoking, excellent graphics and user-friendly interface. Admittedly it is still in EA, so some fine-tuning is needed, and eventually I''d like to see a better movie-creation tool than the rough one there currently is, but even in its EA state this is a very polished game. It took me quite a few hours and re-starts to figure out how to advance to higher levels, in order to access more advanced buildings and to make larger m', 'Man this game is kinda rough and feels almost exactly the same as the demo.\n\nMaybe they''ll make it great and feel like The Movies, but right now I would say to wait.', 'Mostly Positive', 72.13, 164.98, 0.23);
INSERT INTO reviews VALUES (67607, 2659900, 1036, 'On sale for 3 dollars US?? Easily worth it.\r\n\r\nBiggest Downside? As the game progresses, resource generation becomes more punishing. Wish I had known that I would need read the wiki to get to a stable infinite gameplay spot. And that if I couldn''t I''d need to restart my progression from the midgame. Probably won''t finish the game because of that. \r\n\r\nI loved exploring the efficiencies, it just too punishing for testing out builds in the endgame to continue to be fun.\r\n\r\n7/10', 'This game needs to be even more clear that is barely anything more than a Clicker game, but not one you can leave alone.  It highlights the texting-based story, but has about as much plot as Cookie Clicker.  Also easy to miss, as they come randomly about 20 minutes apart.  Not sure who it''s for, as the automation takes a while to get to but the complexity build-up or the setup is not at all rewarding.  Machines locked until further progress are not visible in any way, have no indicator of when y', 'Mostly Positive', 74.52, 39.70, 3.07);
INSERT INTO reviews VALUES (67633, 2660460, 3057, 'Real Civil Engineer brought me to this game, and I am glad I bought it. It is a very fun and laid back indie game. You have little missions to do all while building your own plane that balances weight distribution, velocity, lift, etc in order to complete said missions. Highly recommend this especially at the price it is.', 'Note: This review is based on core mechanics and does not take into account missing features commonly found in Early Access games.\n\nFor a game centered entirely around aviation, the flying physics leave a lot to be desired. The crash mechanics feel more like an arcade game than a simulator. For instance, landing gear is nearly indestructible—no matter how hard you hit the runway. This made me more inclined to just slam the aircraft down rather than attempt a proper landing. The rest of the plane', 'Overwhelmingly Positive', 97.22, 13.58, 2.03);
INSERT INTO reviews VALUES (67715, 2662630, 159, 'It''s fine, really. Honestly, it doesn''t live up to the hype, and certainly isn''t a 10 year Anniversary DLC, no doubt about that. But, after playing it for awhile I''ve learned to appreciate some of the elements of this zone. It''s fairly small, and I like that, there are an amazing amount of basically "free" skyshards to collect, just walk up to them in the overland. I really do like the music, much like Galen, very relaxing and pretty which helps me play longer not stressed from horns, trumpets a', 'Charging additional for companions after purchasing the expansion... bunch of greedy corporate fools... dropped my ESO plus earlier this year and never giving another dime to this game. I already paid for the base game and several expansions... the previous expansions came with the companions and now they are finding just one more way to nickle and dime their players. Plenty of other games out there for me to go play and give a one-time payment to.', 'Mostly Negative', 39.62, 0.00, 0.00);
INSERT INTO reviews VALUES (67719, 2662780, 298, 'Heat Death: Survival Train is one of the most original survival games I''ve ever encountered.  With that said, I ask the developer to remember something:  It is a game.  Games need a payoff for the player''s hard work and determination to learn, play, and, in this case, survive.  The resources are meager, scattered in some inaccessible places, even on the edge of a cliff with no way to get there.  I got stuck in a crevice trying a few times.  The drop pods (those large, round techno things in the ', 'The resource economy needs serious work. Structures need to be unlocked from the start with no blueprint cost. Why can I build a hatch that requires a half ceiling piece to close in the roof, but then I need a half ceiling piece which isn''t unlocked? you have to progress the game to then buy the half ceiling piece. It doesn''t make sense, for a game where being exposed to the elements is lethal.  The required material to build basic things like walls and ceilings is way too expensive.\n\nIt feels l', 'Very Positive', 82.55, 46.30, 2.98);
INSERT INTO reviews VALUES (67816, 2665460, 210, 'I''ve been looking for a Sid Meier''s Pirates successor for years.\nThis is it.\nIt''s just Sid Meier''s Pirates with more depth. I''m loving this.', 'Kind of OK game but damn the pirates are just annoying. It''s like that one mosquito at 2 AM in your bedroom. Doesn''t do much but FOR SOME REASON, if there is a pirate ship ANYWHERE on your screen, well, you better go kill it or wait for a horde of friendly incompetent NPC ships to take it down. And here, have some repetitive anti-chill combat music while you are locked out of skill trees, town interfaces and what-not. Pirate dead? Good! Now wait another 10 seconds while we let the music fade unt', 'Very Positive', 82.38, 2.90, 2.10);
INSERT INTO reviews VALUES (67826, 2665680, 686, 'A fun little game for the price. With some more work, this could be great one. Has good bones.', 'Too grindy for higher level. Also, the upgrades are too expensive for just a small change.\r\nNeed more polish.\r\nSorry, I cannot recommend the game in this stage.', 'Mostly Positive', 79.45, 7.48, 20.17);
INSERT INTO reviews VALUES (67835, 2666200, 106, 'Story: not award winning, but it''ll do, especially considering the ultimate goal... There is an actual story here and it''s entertaining enough, but the localization is ... headscratchingly terrible, it''s not even Ingrish...\n\nlocalization (into English): English, you say? I guess the words are technically English, but that''s about where it ends. Luckily, you don''t need proper English to get where the story is going (either one)\n\nSex scenes: not terrible, they set the stage, but aren''t anything wo', 'Boring, uninspired and scenes are very basic.', 'Mostly Positive', 77.36, 2.23, 4.15);
INSERT INTO reviews VALUES (67849, 2666510, 5718, 'This is the only game that is getting me through working on my thesis right now. I leave it on the bottom of my screen as I write and research feverishly until I decide enough is enough and I take a break by checking on my farm.\r\nThis game is the last of my sanity. My only request is that one day there is the ability to fish somehow. Because I love fishing. I also might be going crazy.', 'If you have a high-resolution monitor I would advise against running this as there are some concerning power draw issues. I have a 4090 playing at 1440p & 4K and this seems to take up 20-30% GPU usage and 10% CPU usage which is antithetical to being an idle game. For reference, I''ve run dozens of idle games and they usually draw 0.1%-2% GPU usage and 0.5-4% CPU usage on my system (granted they are less graphically intense)\n\nIt seems the developers have been aware of this issue for nearly a year ', 'Overwhelmingly Positive', 97.22, 181.48, 14.13);
INSERT INTO reviews VALUES (67870, 2667120, 1343, 'i just like the vibes man, the funny dancing stick-figure that says "Wow!" every time i pick a new upgrade, they motivate me.  I appreciate them so much especially after a long day of work.', 'Really fun game at first, and it has a lot of potential. Unfortunately you are very strongly incentivized to NOT UNLOCK ANYTHING (i.e. the meta-progression).... because after you unlock many additional items and get to the higher difficulties, the vast majority of runs become impossible since there are way, way too many items in the pool and way, way too few rerolls (and no ban feature for some reason), so you end up with random unrelated crap almost every run and auto-lose because of it, as str', 'Very Positive', 86.75, 4.48, 24.07);
INSERT INTO reviews VALUES (67884, 2667410, 136, 'Game has perfect pacing, levelling experience, and replayability\r\n\r\nAlmost 100%''d the game after around 20 hours, highly recommend', 'I really want to like it. The art is pretty, the idea is cool. But the game itself lacks character -- Upgrading cards feels pointless. You get maybe 1 extra attack. Big deal. There''s no feeling of massive progression that rougelites are meant to have. There''s none of the enjoyment when in a rougelite you find an amazing synergy that really works.\n\nI got to the last stage and just quit out of boredom.', 'Very Positive', 87.50, 23.88, 0.75);
INSERT INTO reviews VALUES (67923, 2668170, 100, 'The modelling of the body parts is quite good, but the faces are not as good as they could be. Other aspects of the plot and story were okay.', 'Good concept/idea\r\nPoor renders\r\nPoor plot\r\nPoor translations\r\nNo rollback option', 'Mostly Positive', 73.00, 6.48, 18.82);
INSERT INTO reviews VALUES (67932, 2668430, 305, 'I mean its Trails, if you need a review you need to go back and start at the begining: Trails in the Sky. \n\non a side note, can we do something about whichever cornball millennial is localizing these for NIS? No character in this series should ever be saying that they need to "up their Rizz". it gives very "hello fellow zoomer" vibes.', 'Amazing port but garbage localization as expected from NISA. Having to read "Beauty''s Blade" over and over again makes me wanna kms.\n\nAlso the DLC pricing is just absurd. Support Falcom otherwise and dont waste your money on NISA.', 'Very Positive', 92.46, 133.20, 26.33);
INSERT INTO reviews VALUES (67938, 2668510, 6212, 'Amazing game, but charging 50€/$ for a 14 year old game is ridiculous. If it was an actual remake with RDR2 graphics, new features then fine but this is just greedy. Definitely worth putting it to your wishlist and wait for atleast 50% discount.', 'Charging that much money even on sale for a 2010 game should be a crime. The sharkcards weren''t enough to fund GTA 6 for you, Rockstar???', 'Very Positive', 92.18, 1.07, 2.05);
INSERT INTO reviews VALUES (67981, 2669320, 21693, 'far better than the last few titles; however, it is still an EA product. So, I wouldn''t recommend buying this game at full price (the $70 price tag is simply outrageous for the amount of improvement this game has gotten since the last title). My suggestion for the possible buyer of this game is to wait until December, then buy the game during the winter sale at a fairly lower price.', 'Started as a football game, ended up running a digital casino where my team’s success depended on how deep my wallet was. My best tactic? Praying to EA’s loot box gods. “Pay-to-Winchester,” “Credit Card FC,” and “Microtransaction United” were my top clubs. 2/10 would rather play actual football in my backyard. 💸🎰⚽\r\n\r\nFollow my curator page for more wallet-draining disasters, RNG heartbreaks, and games where skill loses to spending! 💸🎮✨\r\nhttps://store.steampowered.com/curator/42602807-Osiris-Revi', 'Mixed', 49.17, 74.65, 0.83);
INSERT INTO reviews VALUES (67983, 2669380, 169, 'baldi from hit game baldi''s basics has cloned himself, now you, a rogue baldi clone, must massacre them all.\n\nalso you all get guns.', 'jankier melee combat than bonew*rks\nwanted to throw a magazine, threw the whole gun instead\nplayer-to-corpse collision is never a good thing\nsudden GPU lagspikes :(', 'Overwhelmingly Positive', 97.63, 14.73, 0.10);
INSERT INTO reviews VALUES (67985, 2669410, 1372, 'The game stays true to the Metro series. In terms of VR, one of the better quality titles this year. \n\nI''ve refunded the game not because I didn''t like it, but because I repurchased on the Quest 3 to take advantage of a steep discount.', 'You need an internet connection just to play this single-player game? Yeah, no thanks. \nI’ll be getting a refund. I wouldn’t have even noticed if my internet was stable, but every time it cuts out (which happens a lot where I live and is not fixable), the game kicks me right off.\n\nyou dont own your games!', 'Mostly Positive', 73.83, 1.78, 0.12);
INSERT INTO reviews VALUES (68033, 2670630, 27717, 'Dear dev team,\n\nPlease allow me to commit small fraud - I wanna steal +0.01-0.10$ off customers. Some deserve it for staying too long and buying only 2 things.\n\nThank you. \n', 'I really love the organization and store management aspects of this game, but the more things they add to the game the less of it I like. I''m especially disappointed by the addition of cleaning as an entire mechanic, without even the option to hire an employee to do it for you. I''m here to keep my shelves stocked and pretty, not to fight with a poorly-programmed mop every two minutes. I hope there''s an option to toggle it off in the future, like the next major update apparently plans to do with ', 'Very Positive', 94.50, 9.42, 59.13);
INSERT INTO reviews VALUES (68061, 2671230, 488, 'Update: My GOAT. This is my GOTY. It''s in my top 5 of all time games now. No notes. Play this now.\n\n\nThis is it. Only 2 hours in and I already know this is my GOTY. Team Ladybug/WSS have hit it out of the park once again. Building off their previous metroidvanias to create their own IP, Blade Chimera has some of the most absolutely solid combat I''ve ever experienced in the game, all without needing a stupid parry. Buy this game at full price, it''ll be worth every goddamn cent.\n\n\nI''ll probably up', 'i dont even know what to say, team ladybug has been so consistent with their releases up until now but this game just flat out sucks. its fucking brimstone. im honestly surprised the same devs behind touhou luna nights and drainus could put this out, what did it even get delayed for? the pixel art is beautiful and the combat is very fun and customizable with lots of weapons; still the game manages to waste these things. the game might as well not even be a metroidvania, it''s divided into 4 separ', 'Very Positive', 92.42, 5.43, 4.23);
INSERT INTO reviews VALUES (68087, 2671970, 812, 'Best Suika game here on steam. Personally prefer the switch version overall but as far as Steam goes, this is as good as it gets.', 'I feel shame for getting the 100% in this one...\n', 'Very Positive', 92.36, 15.03, 22.73);
INSERT INTO reviews VALUES (68150, 2673660, 163, 'Absolute gem and a must for fans of System Shock / Arx Fatalis. Atmosphere is crazy, humorous but also oppressive, yet always believable and immersive - and the setting includes a lot of varied locales ranging from what you''d expect to find on a submarine, to parks, and ancient libraries and temples, and it all fits together. Just finished with a melee psionic - early and mid game were survival horrory, with resources always being very tight but always just enough to get by; by the late game tho', 'Sorry, I really wanted to enjoy this. But there''s a reason the OG System Shock controls went extinct and its sequel went with a standard WASD freelook system.... over 25 years ago!\n\nThe controls are so clunky and poorly done that the game isn''t playable for me. And that''s saying something; I love moody, janky indie stuff and I want to say it''s exceedingly rare that I refer to a game as unplayable, but here we are. I played the original System Shock on a Pentium 120 almost 30 years ago and the co', 'Very Positive', 85.89, 24.08, 0.58);
INSERT INTO reviews VALUES (68174, 2677660, 5504, 'They perfectly captured the atmosphere; now I’d love to see them apply this approach to a Blade Runner game.', 'BUYER BEWARE - Check the minimum specs. For some reason this game has high requirements, but you probably won''t notice until several hours in when a cutscene refuses to progress. This puts you past Steam''s refund window and Bethesda support will dismiss your case.', 'Very Positive', 90.43, 21.43, 29.82);
INSERT INTO reviews VALUES (68189, 2679460, 11099, 'Well, if you''re into JRPGs, then you gotta try this one out. Yes, it is pretty similar to Persona/SMT, same devs, after all. But Metaphor has lots of unique things under its belt as well, like party formations, archetypes being a lot more thought out mechanically than personas, real-time combat before the main turn-based one where you can stun the enemy.\r\nBut the best thing about Metaphor is that you don''t need to go to school, awesome.', 'Unable to play this game in offline mode on the steamdeck, was looking forward to progressing during travel. Blocked by the DRM saying I needed to go online to validate my copy of the game and refusing to launch. This is a single player RPG with optional online elements, why is this even blocking to launch.\r\n\r\nSteam is the DRM in-case people have forgotten, there shouldn''t be another DRM layer that denies access to the game for customers due to not being online. As long as Steam validates the ac', 'Very Positive', 93.87, 105.57, 45.07);
INSERT INTO reviews VALUES (68206, 2680010, 6447, 'die 20+ times to boss, manage to finally defeat boss with 5% hp left, cutscene plays and the boss gets angry, begin phase 2 with full health bar...\r\n\r\nah shit, here we go again..\r\n\r\n10/10 \r\n', 'Promising Start, But Quickly Falls Into Repetition\n\nThe game begins with engaging combat and challenging boss fights, offering hope for a solid experience. However, as you progress, it becomes painfully clear that the game relies heavily on repetition. Mission stages feel almost identical, and side missions are just recycled versions of main missions. The same enemies keep appearing over and over again, from the tutorial to the very end, making the world feel stagnant. The story doesn’t do much ', 'Very Positive', 93.22, 100.02, 27.10);
INSERT INTO reviews VALUES (68228, 2680550, 950, 'Released a banger. The lead actor died shortly before the premiere. His family demanded a percentage of the gross. I said no. They sued and won. Then they died from the heroin they bought with the money. 10/10', 'Well, we tried. Great vibe, great systems. However, I cannot recommend the game in the state it is in. So rarely do I play a tycoon and just drop it altogether because of unpolish, but I will be doing that here. First and foremost, there is zero replayability in this game. The tutorial is not in your face, but is very present your playthroughs. This means that it will stick around for... well, I have 5 hours in the game and I''d say during hour 3 it started to cool down. Important note is that in', 'Very Positive', 82.63, 3.82, 5.35);
INSERT INTO reviews VALUES (68247, 2681180, 103, 'I cried with how majestic this was. The experience with 3 of my buddies was mesmerising. GOTY contender for sure. Cant believe its this cheap. \n\nPlease add volume slider and day/night cycle and we have a winner', 'poop', 'Mostly Positive', 79.61, 0.68, 0.22);
INSERT INTO reviews VALUES (68258, 2681490, 218, 'RPG where you fetch things to get... rewards. Suggest getting on discount and/or bundles.', 'Don''t do it! These girls physics came from an old TV show called Gumby. these avatars have weird bends and creases like they''re clay-mation. \n\n2/10', 'Mixed', 67.89, 0.22, 0.50);
INSERT INTO reviews VALUES (68281, 2682120, 104, 'The game does a good job at simulating life as a cinema owner. From the nitty gritty bits to the pleasures of the business Movie Cinema Simulator shows you all sides of the business, from the nitty gritty bits to the pleasures. It is a delight finding the parody version of one of your favourite films in the store and putting it on tomorrows schedule immediately. The scheduling of movies on screens does comes off as a simplified version of the mechanic from Empire TV Tycoon, but that’s not a bad ', 'it''s bad really bad i don''t know why they made a game for iPhone app and for pc it''s was designed to be a app for a phone not pc so not play it bad really bad it''s not fun at all.', 'Very Positive', 92.31, 2.83, 4.30);
INSERT INTO reviews VALUES (68300, 2682580, 1123, 'People keep saying it''s a Rust clone. It quite literally is Deadside re-skinned. \n\nGreat progression flow, never felt held back. Once you start upgrading your base everything just flows so smoothly.\n\nCommunity is unbelievably toxic, but what Open World Survival Craft PVP MMO isn''t.\n\nUPDATE: Player count has fizzled to a mere third of what it was when this review was originally posted earlier in October. It hasn''t even been a full 4 weeks and servers are barren, and player counts are unaffected b', 'Would be a fun game if it wasn''t ruined by cheaters.\nsince we bought the game we had 3 nice runs, till the hackers find you.\ndifferent servers are not really an option because there are not enough players.\nGG\n', 'Mostly Positive', 75.42, 38.00, 42.92);
INSERT INTO reviews VALUES (68323, 2683150, 2799, 'good game, bad people. tried as a women to play with randoms one time, got called a slave, a bitch and all kinds of other insults. Don''t really care just not nice when playing a calm game. VALORANT''S PLAYERS ARE EVERYWHERE NOW!', 'I love almost everything about this game, but the inability to pause is incredibly frustrating.  Every time I need to take my dog outside, or get a snack, or leave my computer for any reason at all, I have to remember to save the game and exit out to the main menu.  I''m an adult with adult responsibilities, and I have to get up A LOT, so it gets old fast.  I understand that it''s a co-op game, but there is a single-player mode, and this seems like an egregious oversight.', 'Very Positive', 87.82, 17.78, 77.37);
INSERT INTO reviews VALUES (68435, 2685380, 118, 'Let it be known this game was made by a Dipper Pines cosplayer', 'I absolutely adore this game, and I think it''s incredible. But one of the devs told me I should be the first negative review, so here I am.', 'Overwhelmingly Positive', 99.15, 0.28, 0.17);
INSERT INTO reviews VALUES (68459, 2685900, 997, 'This game is like a cheap pizza, it doesn''t cost a lot and its enjoyable for the little time you have it, but i have nothing else to say about it and will probably never even think about this game again.', 'Cute little game with a nice cast of characters, and overall a great achievement for a first release.\n\nHowever it is very short (100% in under 2 hours) and most of the puzzles are so simple that do not require any effort to solve.\nIt''s not at all a bad experience but it''s a bit uninspired and review score is heavily inflated by the author''s popularity.', 'Very Positive', 88.97, 4.43, 1.83);
INSERT INTO reviews VALUES (68497, 2686900, 329, 'this game exists, idk if i can genuinely recommend it, but i know i cant leave a bad review as the game does what it sets out to do, but like.... who is this for????', 'Refunded in less than 15 minutes, new record.\r\n\r\nYeah, didn''t even came.\r\n\r\nThe game is poorly optimized and it''s so basic, the devs haven''t updated in a while, and it''s straight so, i do not recommend it.', 'Very Positive', 93.01, 0.17, 0.25);
INSERT INTO reviews VALUES (68544, 2687970, 1158, 'Selling a game as early access when they are actually just selling a half done game with no intent to finish it is unethical.\n\nThis game was on track to be good, but was abandoned. The bean counters did not see enough early interest to bother spending the money to finish it.\n\nI still play the game, it is fun. But it is in it''s twilight already. I think it is worth $20, but know what you are buying.', 'dead on arrival. big potential but the quick cash grab was more important i guess.', 'Mixed', 63.21, 68.28, 13.50);
INSERT INTO reviews VALUES (68567, 2688570, 365, 'REALLY REALLY GOOD! STORYLINE, JUMPSCARES, NO BORING TASKS, VERY NICE! ROBIN <3', 'no sex scene 0/10 barely playable', 'Very Positive', 94.79, 2.87, 3.68);
INSERT INTO reviews VALUES (68583, 2688950, 5482, 'Game runs great and is fun. Much like the first game.\nIf you like the first game, you will for sure like this one.\nOnly complaint i have is that you can''t turn off rain in sandbox. But i''m sure they will fix that in the future.', 'I like this game a lot, but unfortunately there is a solid amount of greed on display here. There are coasters & rides in the game, visible within the build menus, that send you to purchase DLC when you try to build them. Even worse, there are in-game rides, shown to every player, which require pre-order DLC that is currently not available to purchase. I wanted to build a "powered rotating ride", which is a basic Haunted Mansion-style track ride, but it''s locked behind a pre-order exclusive DLC ', 'Mixed', 64.92, 15.55, 23.37);
INSERT INTO reviews VALUES (68592, 2689120, 223, 'great central game play but its also over priced and lacking basic features. looking forward for it to expand.', 'game is not worth 15 dollars in its current state with how clunky and strange it is and  and from my experience the remote play feature doesnt even exist ingame', 'Very Positive', 90.58, 10.10, 0.40);
INSERT INTO reviews VALUES (68596, 2689230, 170, 'This game is.. everything I could ever ask for. When I first spread the legs of that deer stuck in the wall, and gazed upon it''s glistening asshole, a hand pushed out, revealing a keycard. A tear rolled down my eye, as the buff naked wolf guy ran up behind me and shove his hand in my ass. It shows how life is a cycle, and revenge causes a cycle that there is no escape from. The writing is amazing, perfect even. If I could do one thing for the developer of this game, it would be to give my life f', 'I want to kill myself', 'Mostly Positive', 74.12, 0.17, 1.02);
INSERT INTO reviews VALUES (68605, 2689470, 781, 'If Cultic and Hotline Miami had a baby that was left on the porch of an abusive alcoholic and was raised to become a serial killer, that would be CRUEL \n10/10', 'Feels like a run and gun that punishes you for going to fast. the traps, shadow creatures, crows and monkeys just kills all momentum i had because i had to slow down to make sure i don''t get hit by something that spawned right on me.\nthis game looks amazing but the gameplay does not meet the same quality', 'Overwhelmingly Positive', 95.13, 4.80, 1.33);
INSERT INTO reviews VALUES (68738, 2693060, 796, 'This game changed my life for the better, I now have a wife and kids and a stable job. Thank you Euphoric Brothers, you guys really changed my life.', 'if i had a penny for every time i had to hear "iM StiLl HunGrY. oH I rEmeMbeR YoU, yOU AlWayS hAtEd mY jOkES." i would have enough money to buy an entirely new game.\nany game, really.\nliterally any other game but this one.', 'Very Positive', 85.55, 10.43, 2.88);
INSERT INTO reviews VALUES (68740, 2693120, 310, 'This app is the best thing that ever happened to steamdeck owners. This allows me to play any game on gamepass including COD black ops 6 and  MLB The Show', 'Absolutely do not install this on your steam deck. It crashed my steam deck and now my steam deck will not boot, it gets stuck on the launch page. It appears I will have to be sending it into valve as nothing is fixing it on my end.', 'Mostly Positive', 79.35, 119.75, 1.72);
INSERT INTO reviews VALUES (68758, 2693460, 115, 'Decent graphics and great Christmas vibe and decoration - though the story occurs in New Year''s Eve so a little inconsistency with the game''s name and other elements of the story, some of which are implied, but not explained..\n\nA linear point and click story, it offers good scares and scary ambiance, though the scare scenes are hampered as they occur in almost complete darkness.\n\nCould benefit from faster walking/running speeds, and UI could be better; i.e. fireworks activation and items pickup.', 'Eh. Like it’s not bad but I’ve played much better horror games for the same price. The story is incoherent at times with poor grammar and a confusing timeline. Like it’s called Christmas Nightmare but takes place on new years? If you’re a streamer looking for a Christmas themed horror game then it’s okay but honestly it feels like a 99 cent asset flip at best.', 'Very Positive', 92.17, 2.13, 0.87);
INSERT INTO reviews VALUES (68769, 2693710, 177, 'This game taught me to love robots and myself\n\nI''m a trans woman; I have a body like the player character, HC''s. Not blue or detachable unfortunately, but y''know, close enough. I''ve spent years figuring out how to feel comfortable in my own body as something more than an object of fetishization and/or shame that being trans-femme can so often feel like. Between that and my dysphoria, I''ve always struggled with feeling "good enough" -- attractive enough, sexy enough, not too insecure, always anxi', 'I do think this game is fun but i just feel the writing is a bit forced at times..\n\nif there was a mixed option i would definitely choose that instead of negative\n\nThe artstyle is great and the environments are pretty...the whole trans girl protagonist thing is really nice to see but personally i just didn''t connect with it much (Surprising because im trans)', 'Very Positive', 89.27, 21.43, 0.50);
INSERT INTO reviews VALUES (68770, 2693730, 491, 'I''ve never played PF2e before, as far as I know this is the only game to use it so far. It''s seems to be a fantastic system and this game does a great job of teaching you, picked up the basics straight away.\r\n\r\nAs of the game itself, presentation is simple but clean and clear, UI is easy to use and there''s plenty of tooltips to explain the game. Base game is very short, 20 or so encounters with story parts in between and is capped at level 4 but the expansion doubles the length and brings you to', 'This game lives off of the generosity and enthusiasm of the Pathfinder 2e community. It''s just terrible. The stories are trite and stupid, the voice acting is so bad it''ll make you physically cringe, the characterizations are just stereotypes of a class/race, immersion is constantly broken by the characters speaking about game mechanics in casual conversation, and the assets are worse than what you can get from free packs. It''s not even a good price! Pathfinder: Kingmaker goes on sale for 3.99!\n', 'Overwhelmingly Positive', 97.96, 9.65, 1.88);
INSERT INTO reviews VALUES (68781, 2693930, 1100, 'I would consider this an early access game, but the development is promising. There is a lot of content planned for the future, and the balance is being adjusted with each update. Assuming everything on the roadmap comes out okay, this may indeed prove worthwhile.', 'There are very few meaningful decisions to make in this game. It SEEMS like there is a lot of customization and strategy, but after you play for a while you realize that the game almost plays itself.', 'Very Positive', 84.45, 38.95, 0.57);
INSERT INTO reviews VALUES (68801, 2694420, 974, 'This is the quintessence of a modern arcade game. There are no unnecessary elements here. Everything fits together and was made with devilish precision.', 'Feels good\r\nLooks good\r\nPlays good\r\nHowever it feels to have close to no progression. Unlocks include objectives that are borderline impossible to understand what you supposed to do or where. Its pretty much retrying same map over and over again until something randomly unlocks.\r\n10/10 for style, vibe and smooth clean gameplay\r\n1/10 for progression system and replayability', 'Very Positive', 94.35, 109.95, 0.87);
INSERT INTO reviews VALUES (68839, 2695270, 222, 'I couldn''t stop gooning, every time I opened this game and played it, non-stop goonage, if there was a measurement for the amount of liquid spilt during this playthrough, the ocean would be extra white and salty~', 'Gameplay is just not fun.  Not worth it for the small amount of bewbs.', 'Very Positive', 85.14, 2.20, 1.83);
INSERT INTO reviews VALUES (68846, 2695490, 1088, 'quite a fun game simple progression, fun to battle for ships and just make bigger and bigger ship! and lots of dakka!!', 'Honestly this is a great game. I didn''t know this was an mmo... either way thats whats wrong... bunch of cheaters using the trainer from cheatcc making them invincible. also they are running around in the most powerful ships nuking newbies and stealing resources. I like the game play and it is really fun. they need some balancing on enemys. never and i mean never mess with sharks.', 'Mostly Positive', 78.58, 46.70, 4.80);
INSERT INTO reviews VALUES (68860, 2695940, 3692, 'we group camp the toilet out of fear, one friend burp and we all died. 10/10 do it again.', 'Panicore must be one of the worst games I''ve ever played and the first I’ve ever refunded. Trash monsters that walk in the air and kill you 1 second after spawning. The whole game is like an AI virus game you get on a porn site.', 'Mostly Positive', 76.00, 20.08, 0.37);
INSERT INTO reviews VALUES (68864, 2696050, 242, 'This is a fun Monster capture game, with a pretty good story.\r\n\r\nOnly con I have is the MC design. I get enough of that when I look in the mirror.', 'I would strongly advise anyone considering purchasing this product to look elsewhere for a game aimed at adult audiences. This game is a blatant cash grab scam, and I regret falling for it. I thought I was buying a game that combined Pokémon-like elements with adult scenes, but that''s not what I got. The game has a Pokémon-esque aesthetic and an interesting story, but if you''re looking for adult content or interactions with the characters you''ve defeated, you''re out of luck.\n\nTo access any adult', 'Very Positive', 90.91, 48.52, 8.78);
INSERT INTO reviews VALUES (68936, 2697930, 677, 'Really like the game, but the Snow-Melter boss during the final act is literally impossible to defeat (unless your build is broken enough to somehow do it within two turns). After three turns, he activates all three torches making himself invincible, and as far as I can tell there is no way to extinguish the torches and the battle just keeps going forever until you either lose or give up. Will change to a positive review if and when this is somehow fixed.\n\nEDIT: I played through the game a coupl', 'Very fun game, but unfortunately released too early it seems as there is very small card / relic pool, which makes the game very repetitive early on, unlike most other roguelites that are similar. I''d say wait a while before they add more content. Fun little game though!', 'Very Positive', 91.29, 6.22, 19.40);
INSERT INTO reviews VALUES (68969, 2698780, 1608, 'EDIT: Still wonderful, but I''ve been stuck in the skyscraper since September and I can''t get out...\n\nWonderful game - nearly 150 hours for £16 is good value. Bug-ridden at the moment and graphics need an overhaul but adds to the charm and will be very interested to see how the devs update the game over the remainder of early access.\n\nOnly criticism has been mentioned by other reviewers. This is a bit of a dull grind for solo players. As one who plays most games solo, tasks which are meant to be ', 'Concept is good. I support devs by buying their game. But I cannot recommend it until they fix major bugs. Which kills all my desire to play every time. Cause waste several hours on building smth big and then cannot finish the contract cause of some bug (like stairs or that i cannot place the last door = can''t move forward to complete the building). I want to play the game but I guess better not to play until devs fix most of the anooying bugs (i''m not even talking about small bugs that are anno', 'Very Positive', 81.41, 180.15, 50.35);
INSERT INTO reviews VALUES (68974, 2698870, 143, 'This is a fantastic game! I really enjoyed the beta for this, and am happy to see that the early access version is just as satisfying, with an all new wild cards mode and some other additions that are really fun and keep the matches fresh! An awesome game to hop on for quick rounds with your friends or randoms, and have a blast. Hilarious matches, fun voip interactions, unique gameplay, and the game "works." In and out of matches quickly, and seems quite polished. A good amount of different game', 'so i guess you can just turn up the brightness/gamma to get advantages. why do gamers ruin everything? Look, if you are thinking about getting this game, just get it for you and your friends. Playing with randos will almost certainly put you in matches with people that take the game too seriously and want to look for every advantage and exploit they can find in an online multiplayer game because they are poor, hate themselves, and haven''t moved out of their step mom''s boyfriends trailer', 'Mostly Positive', 72.03, 21.95, 1.23);
INSERT INTO reviews VALUES (68977, 2698940, 3587, 'I love how the cars feel in this game, I also enjoy the steering wheel animations in this game. My only gripe is that the multiplayer mode is missing cross-play free roam.', 'Purchased this game, downloaded it, and it says that i don''t have the key too access and play the game ? F**k you ubis**t', 'Mostly Positive', 76.08, 87.72, 0.12);
INSERT INTO reviews VALUES (69114, 2701660, 1062, 'I played hundreds of hours of the NES original back in the 80s. It''s nice to see a modernized take that preserves the sense of exploration and whimsy I enjoyed as a kid. Visually the game is a treat, and I''m very happy Square-Enix continues to bring their HD-2D titles to Steam. The personality system for stat growth is quirky and adds replay value even if its implementation is a bit cumbersome when rolling up a party. While there are difficultly options, they''re not granular like in Dragon Quest', 'A really incredible remake and solid port, mechanically. Marred by some of the worst and most flagrantly inaccurate translation in the video game industry. The Dragon Quest series deserves better. People will try to minimize this issue and make it seem like a political thing, but it''s strictly an issue of competency and respect. This translation is akin to the 4Kids One Piece translation where Smoker can''t smoke cigars and gets renamed Chaser and multiple main characters have entirely rewritten ', 'Very Positive', 92.00, 76.12, 2.85);
INSERT INTO reviews VALUES (69117, 2701700, 144, 'I got this game thinking it was like beatsaber (im not fond of beatsaber) but i gave it a chance and oh my god i am so happy i did.\nI love classical music and the fact that i can conduct a whole orchestra is amazing (Can''t wait for these amazing devs to get more music into this game). The only thing that would make this game better are mods, i would love to have some goofy hands holding a sausage or something while conducting songs from CupHead or TeamFortress2 (please collab for the love of god', 'Doesnt work with the original steam controllers.  Shame, it seems like a fun game but doesnt respond to certain gestures and you can''t select anything in the pause menu.  Getting really tired of VR games that can''t register the original style of vive controller.  But looking online apparently the controller binding is a common issue.  So make sure you test everything out should you decide to purchase.  Refunding.', 'Overwhelmingly Positive', 97.22, 1.93, 0.55);
INSERT INTO reviews VALUES (69159, 2702490, 130, 'the best tetris release since TETRIS EFFECT, and it''s not even an official game! it exudes a lot of charm and comes slam-packed with tons of modes, but its central gimmick surprisingly shakes everything up a lot and will definitely punish core tetris fundamentals if you''re not thinking of that extra layer. it helps that the game feel on this is impeccable - the sound design is so juicy and the visual effects / palettes are all a stunning love letter to both the TGM series and the CD-i version. a', '', 'Overwhelmingly Positive', 100.00, 38.42, 0.00);
INSERT INTO reviews VALUES (69166, 2702700, 207, 'I love this game, a ton of potential. HOWEVER, THIS GAME HAS NOT RECEIVED AN UPDATE IN OVER 9 MONTHS! I understand games take a lot of time and effort, but they could at least be more transparent about what is going on behind the scenes. I hope this game is still being worked on, but I am running fairly low on hope.', 'I really want to like this game, but it''s so buggy, and it''s been months since any news.\nNPCs can be entirely broken if you get really close to them and crouch, they will frequently just walk straight through walls, as well as freeze and stop shooting,\nAnd to come back to my previous point, it''s been fucking ages since any news or updates, and it feels like they''ve just abandoned the project.\nIf you''re really set on getting this game, wait until either there''s an actual update, or it''s on sale.', 'Mostly Positive', 71.01, 6.38, 8.80);
INSERT INTO reviews VALUES (69220, 2703850, 3796, 'Awesome game, needs more maps ASAP though - workshop integration would make this the f***ing golden standard.', 'Promising, but in it''s current state I can not wholeheartedly recommend it. There are too few moves, and the maps are small. I think the Dev should focus on big map at first, rather than spread himself thin on four. There is also not currently any recovery animation for when you hurt your character, instead it just teleports to its base position. I will be buying it again if/when the game becomes more whole, but for now I''ll wait. I hope the game reaches it''s potential, because it definitely has', 'Overwhelmingly Positive', 96.87, 21.72, 0.42);
INSERT INTO reviews VALUES (69318, 2706170, 1496, 'as a foddian game expert Get To Work seperates itself from the pack with its narrative driven story and VO. The gameplay is challenging yet rewarding whne you get the hang of it. In certain section it is clear the dev was drunk, but it is made up for by the community who have already discovered several skips to vastly speed up how quickly you can beat the game.\n\nFor fans of foddian games, speedrunners, or just viewers who think they are better than their streams, this game is worth trying.', 'This game is a fun Foddian game, it can be unforgiving at times, but whenever I fall, it''s more of a case of "I messed up" than "The game made me mess up"... when it works fine that is. The problem I have is that throughout the game, you constantly get small stuttering and frame drops throughout the game. The stuttering gets worse the higher you get up, but it''s very noticeable when you make it to Middle Management. This wouldn''t be much of an issue, but there are no settings in the game to adju', 'Very Positive', 92.38, 8.32, 3.93);
INSERT INTO reviews VALUES (69325, 2706300, 207, 'Where do I begin? The repetitive sigma grindset required to get a nut off is bewildering. You would have better luck getting a girlfriend irl. Aside from that, the artwork is HOT. Full stop. My only other complaint aside from the money making system, is the sleeper agent effect. Why am I getting half the messages in Russian? They want me to be a Manchurian candidate sooooo bad bro. WTF is that about?? All in all, would recommend.', 'Art is ok. Progression is ok.\r\n\r\nSpoiler alert.\r\n\r\nThe really bad part about this game is the story. The MC is really hard to like. You spend the game selling drugs, selling pics of your friends, stealing from them, and everyone loves you for it. They get mad at their husband for cheating but love when you cheat on them. There''s no reason to like this MC. You''re basically in this situation because you''re too scared of people you owe money to.', 'Mixed', 69.08, 14.12, 3.95);
INSERT INTO reviews VALUES (69384, 2707490, 330, 'I like this game. But 2 things that are really annoying:\n- the game is way too fast. After day 3 it is really hard to track my production, rebuild the base while resources are done and keep track of the minion waves. Consider slowing it down and make possible to pauze build\n- Limit of towers is really bad. Second map is big as hell and there is more space than i can build towers in them.', 'Too many external growth factors force you to waste time on repetitive levels. Beating the game depends less on your strategy and more on your level. If your level is high enough, you can easily pass; even the best strategy can''t compensate for a low level. This makes the whole game dull.', 'Very Positive', 84.85, 2.75, 7.10);
INSERT INTO reviews VALUES (69404, 2707940, 1872, 'Needs a leaderboard, top 100 players get conscripted', 'The game allegedly has files that resemble a trojan and are (no joke) pinging your location to the Russian government in case you are a Ukrainian FPV pilot in training\n(more info from @GwarWorin on twitter)\n\nFYI: The company is based in St. Petersburg Russia \nThe controls are jacky and the physics don''t fell right\nThe game feels like an asset flip', 'Very Positive', 85.20, 13.30, 0.47);
INSERT INTO reviews VALUES (69422, 2708280, 356, 'When I first downloaded Escape the Boykisser, I expected a lighthearted game to pass the time. \nWhat I found instead was an emotional journey that fundamentally shifted my perspective on everything my life has to offer, and my opinion on kissing boys.\nThis isn''t just a game; it''s an experience. It''s therapy disguised as entertainment, a mirror held up to our collective anxieties with a wink and a nudge, a peakness that can never be toped again.\nTo the developers: thank you for changing my life i', 'Does not have graphic setting! very unoptimize!', 'Mostly Positive', 75.84, 6.12, 0.12);
INSERT INTO reviews VALUES (69424, 2708450, 1386, 'So the game itself is very fun, matches are short so there''s no real commitment, with VOIP the game is hilarious too, very simple mechanics so anyone can play.\r\n\r\ndownside is there is no player-base so its rare to get a full lobby with good ping. if you do buy i suggest getting your friends to buy it too.\r\nI think lowering the price in the long term would earn the creator(s) more money and would help the game thrive because i think for what it is its quite expensive.', 'Priced too high for what is effectively a mini-game.', 'Very Positive', 85.06, 3.83, 0.42);
INSERT INTO reviews VALUES (69450, 2708950, 200, 'You''re reading this review right now so you''re interested in this in some way. If you''ve browsed any of the risqué tags you''ll see an absolute sea of cheap and low quality NSFW - I wouldn''t consider this that. For what it is, at it''s pricepoint, and still getting updates this is one of the better ones. \n\nThe gameplay loop is engaging enough - all while balancing a good ratio of play vs erotica. It''s part visual novel and part customer management with some decision making mixed into the gameplay ', 'Look, some of you may like this, But I have a problem with these management games that don''t go anywhere with complete redundancy and lack of variation in game mode till you are just doing the management and nothing ell''s happens and you probably wont get enough points for other achievements. Like someone tipping you 50 in one round "and" letter grades that have to be successful at the same time while it just gets harder and harder to satisfy customers? That''s just one example. The story and sex', 'Very Positive', 90.50, 6.08, 28.37);
INSERT INTO reviews VALUES (69532, 2710950, 106, 'Ass game', 'The game play is very boring and tedious leading it to be hard to recommend, but I''m trying my best to get through it, because I do like the story so far. Graphics are nice too. \nIt''s like one of those games where I want to recommend, but just can''t. I''d only recommend if you''re like with your friends and need to put on something while chatting.', 'Very Positive', 85.85, 3.13, 3.32);
INSERT INTO reviews VALUES (69629, 2713690, 130, 'Been playing since the early builds on Patreon and picked it up on Steam to support the dev. Long story short - this is a great one! The game can be a bit grindy as you level up your powers and earn money in order to expand your harem empire, but the payoffs are worth it. The ladies are gorgeous and all waiting to be corrupted! So what are ya waiting for champ? Get to it!\n\nOh and before you go flying to the discussion board to ask/complain, the base version of the game doesn''t have.. Familial re', 'Fix the damn blackjack game to not be rigged... Played 30 actual hands in a row... I didnt just lose every time... I paid attention to the way the cards came out... Every hand, it did not matter whether I hit or stayed... the cards were stacked against me.  If I hit, the cards busted me, but would have gave them exactly what they needed.  If I stuck, the cards they drew gave them exactly what was needed but would have busted me.  30 times in a row... like literally stacking the deck.  Complete b', 'Very Positive', 91.54, 6.45, 16.13);
INSERT INTO reviews VALUES (69663, 2714620, 806, 'After playing the Duck Detective: The Secret Salami and The Ghost of Glamping I''ve become a true detective. My Detective skills tell me the next Duck Detective game will release on the 21st of May 2026.', 'Honestly, it''s not *bad*, it''s just not really good enough.\nLike, the overall quality of the majority of it is perfectly fine, but something like this lives and dies on its comedy, and i... smirked a few times, i guess?\nIt''s also very, VERY short', 'Overwhelmingly Positive', 99.13, 1.78, 2.18);
INSERT INTO reviews VALUES (69673, 2714970, 117, 'It has been 4 hours since I successfully sucked my own penis. Things are different now. As soon as mouth-to-penis contact was made I felt a shockwave through my body. I have reason to believe I have super strength and telekinesis now.. 3 hours after contact I noticed a van parked on my street but no one has entered or exited the car since its arrival. I fear for my safety, I''m not sure what sort of power I may have stumbled upon but it''s possible that the government has found out\n\n\n\npretty scary', 'As a Backrooms enthusiast, this game is just absolutely terrible and is not worth playing even if it was free. \nThe AI does nothing in the three (?) levels that they exist, the levels are way too short, the stamina regen feels like shit with the levels being as empty as they are and there is absolutely no fun or engagement to be had even with friends. The sound design doesn''t really exist either, so this game just ends up bringing absolutely nothing to the table.\n\nPlay these instead:\nhttps://sto', 'Mixed', 48.72, 1.25, 1.03);
INSERT INTO reviews VALUES (69695, 2715650, 146, 'I can definitely assure you.\n\nHumans are not that against Lizardwomen!\n\nI''d love a big ol'' lady Lizard slobbin'' on my knob.', 'Well, its boring. Some things are good, like puzzle minigames or nude scenes, they are funny. But overall it''s waste of time. A story line and talking between minigames and nude scenes is long and not so interesting or funny.', 'Very Positive', 92.47, 0.25, 1.20);
INSERT INTO reviews VALUES (69719, 2716110, 199, 'The Chillasart fan community seems to want exactly the opposite of me, because in my opinion this was definitely the best thing the two of them have produced in a very long time, Night Security was a real transitional step at a solid level and Jisatsu unfortunately missed a few Opportunities, but convincing as a pure horror experience on a completely different level than its unintentionally funny predecessors.', 'I got this game because of the devs positive  reputation, but this is just not even a game. No one would believe the details, if I laid them all out. And its not fair to ruin it for other players who decide to try this one out.  Opinions vary, but I think for the majority of horror game fans, this critique is pretty spot on.  I don''t even have the words to describe how disappointing  this experience was.  The player  wanders around in the dark, with no idea what their  purpose is.  I literally g', 'Very Positive', 81.41, 1.85, 1.00);
INSERT INTO reviews VALUES (69731, 2716400, 1928, 'A detective story about repulsively ugly opportunists misusing technology they barely understand is the perfect way to bookend a year of announcements by publishers concerning the exciting possibilities presented by generative AI in video games.', 'While not without merit, Rise is certainly a step down from its predecessor where it matters most: the experience of solving the puzzles. Many puzzles feel forced in to serve a convuluted narrative rather than standing on their own as solid levels to a game. Case of the Golden Idol wasn''t perfect, but a narrative first mindset feels like the wrong approach for this series. The joy I got from the first one was from the satisfaction of opening a scenario, having absolutely no idea how to comprehen', 'Overwhelmingly Positive', 96.01, 12.75, 8.62);
INSERT INTO reviews VALUES (69761, 2717080, 522, 'A fun and charming game that captures the essence of Christmas. Highlights include:\n- Engaging Gameplay: Keeps players involved and entertained.\n- All-Age Appeal: Easy to learn, making it perfect for families.\n- Basic Aesthetics: Simple design that facilitates gameplay.\n- Needs More Features: Additional challenges could improve enjoyment. In summary, it’s a wonderful way to enjoy the holidays together!\n', 'Fake Reviews by fake Accounts by AI Generators?\n\nOVER 500 HOURS on this Game?\nClose to All Positive?\nCheck the Text thats written\n\nThank you steam Support for Made This Possible !', 'Overwhelmingly Positive', 97.51, 888.52, 2.73);
INSERT INTO reviews VALUES (69771, 2717260, 177, 'I beat it quickly, no glitches or bugs, it had some startling moments when you turn the camera and something appears after you''ve just looked there - which is an effect I love, from old skool Skyrim horror mods. The story was a bit hard to follow, but I got the gist... I think it works in favor of little horror games to have loosely translated material because it seems creepier. Lost in a little village, picking up notes that piece a story together, and being alerted by friendly mannequins when ', 'I’m counting to 6… is a short horror walking simulator taking place in an abandoned village. It’s important to acknowledge that visually this game looks fantastic. However, the story and gameplay leaves a lot to be desired. For the bulk of the game you are walking back and forth in a small area of a house. In short order, your actions start to feel like a vector for the next unsettling thing to happen. You walk across the room? Expect a mannequin to be behind when you turn around. You pick up an', 'Very Positive', 83.05, 1.12, 0.23);
INSERT INTO reviews VALUES (69790, 2717750, 104, 'Not a bad little 1st-person puzzler. It''s no Portal, but it''s worth the price.\nDecent puzzles. Excellent voice acting.', 'Most of the 3-hour playtime is because I left the game running, paused, while I ate dinner, cleaned the kitchen, and lazed about for a while before returning to my PC. I only ever got 5-6 puzzles in. \n\nI really wanted to enjoy this game, but I can''t stand the narrator. This game is another entry in a genre of Portal-likes that I tend to enjoy when they don''t suffer from a sadly common flaw: Trying to give their game a GlaDOS, missing the mark, and polluting their game with a regrettable fount of', 'Very Positive', 92.31, 2.83, 2.72);
INSERT INTO reviews VALUES (69796, 2717880, 680, 'Dead Cells structure, Hades art vibe, PoP nostalgia, good stuff. Very acrobatic. Minus a point for Ubisoft, but I guess they own the license.', 'It''s not a bad game. But it certainly has lengths to go.\nIt is simply way too short for the asking price. €16 for an incomplete game that I have finished 4 times in 3 hours is just... Really lackluster.\n\nThere are cool ideas behind it, but it is just too short, and too easy.\nWait for the 1.0, and go play Dead Cells in the meantime.', 'Very Positive', 87.94, 7.23, 3.27);
INSERT INTO reviews VALUES (69812, 2718240, 110, 'Cozy game! The owls ate my squirrels, the worms pooped, the trees grew tall. 10/10', 'Unfortunately the FPS issues with the game make it very hard to play any endgame. I even attempted to not expand the forest but the FPS issues continue after you get bears and eagles out. I abandoned all my campaign maps to do achievements in free-play mode. Look forward to having a large forest someday and I can swap to a positive review :~)', 'Very Positive', 93.64, 8.98, 15.60);
INSERT INTO reviews VALUES (69834, 2719060, 319, 'Extremely Cute and Funny. Kani aside it''s actually pretty good. You can tell the dev put his entire heart and soul on this project. Graphics are nice, music is good, gameplay is very exhilarating. It''s fairly priced as well. If you want to support small time devs putting their all into their work, you can''t go wrong with buying this game. ToT/10 would 1cc hard when I finally git gud', 'Epstein would love this game. Little girls in revealing outfits. We’ve really come a long way.\n\nGameplay is also boring. Which I hope is the reason YOU got it. Looks way more fun in the trailer.\n\nI’d be weary of anybody who owns this game. Now i’ll take my steam awards now, you lolicon scum.', 'Overwhelmingly Positive', 97.49, 2.08, 0.60);
INSERT INTO reviews VALUES (69838, 2719160, 1444, 'It''s basically Warzone in VR, but IT NEEDS PVE!! The player base has gone down and you guys either need a PVE mode or fill the lobby with bots if players aren''t there. Same with the extraction mode! Don''t ruin all the hard work on this amazing game! We don''t mind bots and PVE as long as the AI is challenging.', 'biggest complaint as a solo is going against no job having 12 year olds running 3 stacks, why is there no option as a solo player to play solo only lobbies?', 'Mostly Positive', 72.78, 5.40, 55.05);
INSERT INTO reviews VALUES (69840, 2719200, 229, 'So far it seems like a great port but I do have a question... Dynasty warriors Gundam reboot when?', 'I appreciate that they finally did a decent PC port and included lots of features and DLC without bloating the price. However, with no English dubs, it is almost impossible to follow the story or characters or what is going on because of the sheer amount of battle chatter in Musou games. I cannot read paragraphs of subtitles while monitoring the map, running around, fighting officers, and keeping tabs on troops and objectives. KOEI, you have to start localizing the games again, I am begging you.', 'Very Positive', 87.77, 20.30, 0.83);
INSERT INTO reviews VALUES (69845, 2719290, 197, 'I see people comparing this to Zero Sievert, and sure its similar in many ways, however for $6 this game is on par with Sievert if not IMO better. This game is amazing if you like loot, and who doesn''t like loot!?', 'Game was great, lots of fun, recent updates have ruined the game, zombies spawning ontop of you, impossible to survive zombie waves\n\nEdit* After giving the updates a little more time, getting to do the prison a few times, the game is complete trash now, sniper with 8x and the prison ai still shoot you from off screen while scoped in, yeah great fun that is to die to a dude with an MG34 you cant even see.', 'Very Positive', 87.31, 30.85, 84.45);
INSERT INTO reviews VALUES (69878, 2719940, 141, 'i love this game but when i play no one plays so can you make it free for like a week so me and my friends can play with me and other people', 'was just 3d pacman with a crappy skeleton model that chases you, has absolutely no objective, got bored in about 5 minutes\n', 'Very Positive', 87.94, 1.95, 0.20);
INSERT INTO reviews VALUES (69885, 2720010, 146, 'I had only ever played RF 3 web version prior to this, so this required a lot of change in play style. It requires a LOT more thought of how and where you''re going to move, where to stand, which weapon/spell to use, how to allocate your talent points, etc. Some might say that it''s less based on RNG due to all of that, but I disagree. How this feels to me is like if RF3 had the difficulty cranked past maximum, and that''s *why* you have to be so particular about everything. \r\n\r\nI would argue that ', 'The more I play this game the less I like it. "Every run is viable" is 100% nonsense. Half the roster is useless, and the other half will continue to be nerfed until they are useless too.  Save yourself a headache and play a game that doesn''t think endless horde ambushes is peak level design.', 'Very Positive', 93.84, 60.17, 52.07);
INSERT INTO reviews VALUES (69922, 2720950, 611, 'Finally, a Mystery Adventure game that satisfies my deep seeded need to manically complete chores while I break into peoples homes.', 'Having to do everything over and over again really sucks', 'Overwhelmingly Positive', 97.87, 2.65, 2.93);
INSERT INTO reviews VALUES (69977, 2722360, 152, 'back at it again with another masterpiece.', 'This was my first escape room video game I''ve played, and I played it with 4  other people.  At first, the puzzles were challenging but still reasonable.  Unfortunately, the puzzles quickly got really annoyingly absurd and monotonous.  If it weren''t for the hint system, we never would''ve solved half of them.  Also, the game was too reliant on things like sliding tile puzzles or light all the lights puzzles.  Thus, it kind of stopped being fun to figure out the puzzles, and we quit playing like 1', 'Very Positive', 90.79, 7.70, 2.52);
INSERT INTO reviews VALUES (70114, 2725260, 3230, 'As a huge fan of Ender Lilies I was beyond hyped when I heard that Ender Magnolia was coming and it definitely didn''t disappoint a bit. I loved the game so much and the story was as good as the first game and it made me tear up at times too. Also the music is phenomenal like Ender Lilies. All in all, I had a blast playing Ender Magnolia and I hope they make another sequel because this series is a masterpiece 💖', 'i dont really like the fact that theres no contact damage now and the combat isnt as fun as the last game', 'Overwhelmingly Positive', 97.77, 31.68, 2.10);
INSERT INTO reviews VALUES (70167, 2726450, 2107, 'This game is extremely cool and fun TBH!!\n\nThe dragons in this game get a rating of 0/10, for no dragons.', 'This game made me fight my pc irl', 'Overwhelmingly Positive', 96.06, 11.47, 4.28);
INSERT INTO reviews VALUES (70170, 2726490, 200, 'One of the few instances I felt genuine guilt while playing something. \nPeTA take notes because this dev is going places. \nMost likely jail.', 'Good meme, but severely lacking content, disappointing tbh :^(', 'Very Positive', 92.50, 3.52, 2.33);
INSERT INTO reviews VALUES (70206, 2727650, 359, 'This is a really fun game! I''ve already spent HOURS playing this with my kids, and found myself returning on my own to see what sort of quirky mix of gameplay mechanics and puns was just around the corner.\n\nAmazing game filled to the brim with dad-puns, cars that never does what you think they''ll do, and tons of environmental humour to take in as you do anything but drive normally through the world - highly recommended!', 'i was really expecting something much more unique, like what the golf, which you can never guess what the next level will be about.  despite the reviews and advertising both saying "anything but a racing game"... it''s basically just a racing game and the 15 or so levels i played were all basically the same gameplay with none of the surprises i was expecting based on what the golf (except like "wow you have bigger legs" "wow you have little legs" but you drive basically the same, on a level very ', 'Very Positive', 84.12, 8.47, 0.82);
INSERT INTO reviews VALUES (70244, 2729000, 111, 'In the Cats and Seek series this is the only one not free. However, with its 500 cats and 5 stages this is the longest. The theme is a dinosaur-based fun park with lots of cats to find, plus, something else (such as bees) can also be looked for on each level. \n\nCats have their own text message that pops up once you click on them - this includes their name and a little description telling you what they are famous for. From the menu you can navigate to a website where you can add your own cat''s na', 'There are a slew of "find 100 cats" games out there for free. This is literally just 5 of those put together with a price tag slapped on. There''s nothing unique or interesting about it. It''s not fun compared to other games of this style that have secrets, stories, etc.', 'Overwhelmingly Positive', 99.10, 1.13, 0.80);
INSERT INTO reviews VALUES (70265, 2729480, 267, 'I can beat people throw money at strippers shoot whoever and no one can stop I can also smoke a cigarette while doing that to be a sigma 10/10.', 'paint the town red but made in 30 minutes with free unity assets', 'Very Positive', 92.13, 2.88, 0.33);
INSERT INTO reviews VALUES (70309, 2730540, 166, 'This is a pretty fun deckbuilder rogue-likey thing with some pretty great features. I love that the activation of a muse changes the music and background especially.\n\nAs a warning to anyone looking, this game is anime. It is EXTREMELY anime, it is anime inside of anime inside of anime. Like a giant robot girl falling over and a lightbeam covering her pants/privates levels of fan-servicey anime. \n\nYou can completely and utterly ignore all the story though and just pretend it''s a deckbuilder but i', 'It is a simple and fun card game but it gets repetitive very quickly, the story is as generic as it can get and it has some very cliche fan service. I would only recommend it on sale and if you are out of card games to play, there are much better options.', 'Overwhelmingly Positive', 95.18, 6.27, 8.82);
INSERT INTO reviews VALUES (70362, 2731870, 557, 'I''ve been playing Ys (and Trails) for decades now, and it''s easily one of my favorite JRPG series alongside Trails and Persona. It’s still surprising to me that Ys isn’t more popular in the West, but that’s a rant for another day. With Ys X, the series continues its tradition of smooth, fluid combat, a colorful cast, and epic, heart-pounding music. A heads-up, though: Chapter 1 is a bit of a slow burn, mainly serving as a tutorial. But once you unlock your full combat kit, the game really opens ', 'Hey Falcom, maybe dont announce an updated re-release of your game just two months after it comes out in the west?\n\nfeeling screwed over by falcom aside, while my own playthrough did end on positive terms I did feel extremely mixed about the game for the vast majority of my time with it, and that announcement just reinforces my feelings that this one entry in the Ys series is a bit undercooked.\n\nWait for the updated re-release to come out in the west in 2 to 4 years I guess.', 'Very Positive', 87.43, 6.45, 48.00);
INSERT INTO reviews VALUES (70373, 2732100, 325, 'Came here because of Drae. Legitimately fun game, far more realistic than other blacksmithing games I''ve played. It doesn''t baby you, and the custom blade designing is really fun to play around with. I do recommend you give this a go.', 'I was surprised—from other reviews, I thought this game would be better. Let me get some praise out of the way: you have some creative freedom in how you make your weapons, and the process contains a few fiddly bits that make it feel good to "do a good job."\r\n\r\nUnfortunately, that’s the end of my praise. For all the freedom you get, there are no interesting decisions to make. Like, for example, you could make a spear. Start by cutting a really long handle and forging a small blade. Kind of neat,', 'Very Positive', 85.23, 8.05, 3.52);
INSERT INTO reviews VALUES (70403, 2732820, 345, 'You will be free.\nYou will own land.\nYou will get married.\nYou will fulfill your destiny.\nYou will find strength in Jesus Christ.', 'Would be a really cool game if it wasn''t so political.', 'Overwhelmingly Positive', 96.81, 0.45, 0.13);
INSERT INTO reviews VALUES (70409, 2732960, 2430, 'Major love to EA and all the people behind it for releasing the source code and allowing further updates to the game by the community.\n\nWhat a good time to pick up on this masterpiece.', 'Loved this game since it was out for the first time. Played it as a kid and a teenager solo then in college with friends. I was so excited to see it here on steam. Got it last week to give it a try but only to realize that nothing was done to make it playable on modern systems. Figured out the resolution issue and then I had the camera being too low issue. Google suggested some third party solutions but come on, I already payed for a game that I already owned (on CD) so I wish there were efforts', 'Very Positive', 91.40, 19.48, 15.70);
INSERT INTO reviews VALUES (70496, 2735510, 104, 'A Disney  game that''s truly fun for kids of all ages! Minus those first few years.', '1st one was good. Cute, funny and a variety of characters. This one just feels like a cash grab. Short, incomplete, no polish. Plus the artwork in considerably worse than the first. best example of this is the character that is supposed to look like Jasmine. WTF? Her eyes are are janky, her face is weird and her mouth is way off to one side. Plus she does not look like Jasmine at all. Not in the face, not in the figure..nothing.\n\nThey also altered almost all the characters into these generic, bo', 'Mostly Positive', 74.04, 9.52, 5.48);
INSERT INTO reviews VALUES (70541, 2736480, 109, 'It''s a fine "Where''s Waldo" type of game.  \r\n\r\nIt could give you a lot more interesting things to find and could be of bigger scale, but what''s here is casual fun for 70 minutes.\r\n\r\nFor a bigger and better experience check out Hidden Folks.', 'Only buy on sale, regretting paying full price.\n\nI''m new to the series, so I didn''t understand you are paying for ONE scene. The main game is one scene in Berlin, with 200 cats and no repeatability. There are "bonus" levels to unlock by just finding the cats, but those are smaller, with 50 cats and are what the game is counting, including the people you find in hard mode, to get to the supposed "over 900" objects. Easily finished in less than a half hour, even if you pace yourself. \n\nGraphics ar', 'Overwhelmingly Positive', 99.08, 1.22, 1.92);
INSERT INTO reviews VALUES (70552, 2736690, 211, 'I like this game a lot. It distills the souls-like formula down to the fundamentals that make the genre work. Timed parries, dodges, shortcuts, stamina management, souls dropped on death, etc... it''s all here. All the excess fat and noise has been trimmed from this game and the result is something that is lean and purposeful in its design. Every item makes a meaningful difference to how you play the game. Every point you allocate into your stats matters. This is a game that respects your time, m', 'Game isn''t bad, but cant recommend:\n1. there is no tp between bonfires. even no item to tp back to hub\n2. you are able to change loadout and consumables ONLY at bonfire. because of inability to change loadout in action you cant change your strategy. for example: in ds in fight with dogs you can use shield to block their attack and then attack yourself, after that you see group of ranged and meele enemies, so you able switch to bow and kill at least one of them. same with consumables\n3. some enem', 'Overwhelmingly Positive', 97.63, 1.75, 10.07);
INSERT INTO reviews VALUES (70578, 2737300, 928, 'This was on John Linneman''s top 11 list for 2024 so I bought it on that recommendation. What I didn''t expect to find was that he''s a corporate sellout, how was this game not number 1? Most fun I''ve had with a game in months. It''s pure, addictive joy from a long last art of... being fun.', 'It''s almost fantastic, I want to love it, but the critical flaw is ramps. An arcade racing game should have fun ramps you want to hit fast for rewards. Ramps in this game 70% of the time will make you roll over or hit a ceiling and lose all speed. Even the player guides recommend drifting up ramps to avoid gaining air and losing control, and staying under 70kph at ramps. \n\nThe later tracks get longer and feature more ramps as more opportunities to lose control. It''s been incredibly frustrating t', 'Overwhelmingly Positive', 97.20, 8.63, 1.83);
INSERT INTO reviews VALUES (70613, 2738380, 148, 'Sofar this game is very addicting and fun. One thing i wish the dev would add is the ability to move entire gaming setups, not just one peice at a time.', 'Would only recommend this game for one continuous sitting only cause once you save it and load it again all of your progress is gone, countless hours just deleted, i was enjoying the game until that happened', 'Very Positive', 82.43, 141.22, 10.45);
INSERT INTO reviews VALUES (70620, 2738490, 310, 'It is absolutely perfect for an early access, everything you get here is functionnal, crafted with love, and already so fun to play, the mechanic is addictive and the art style by Chariospirale is amazing (and slightly reminiscent of Plastiboo''s Vermis, but more cartoonish).\n\nBuy this to encourage more game from this great team !', 'It''s a good attempt at creating something original. However, after playing for 4 hours, I find that my character is not stronger than a new account. This isn’t a skill issue. The progression feels almost nonexistent; the newly unlocked units are weak, and each run offers very little variety. \n\nThis game seems to cater to those who enjoy RNG and probabilities—understanding the math doesn''t provide any advantage. I suspect that if I continue playing for another 10 hours, I still won''t find any mor', 'Very Positive', 94.52, 3.05, 4.32);
INSERT INTO reviews VALUES (70628, 2738670, 192, 'I applied to goon.\r\n\r\n\r\n\r\nThey meant "henchman".\r\nnow my ass is deployed on the northern front, and I can''t quit until we''ve destabilized the Bolivian government,\r\nI gotta read my contracts more thoroughly, bruh.', 'There''s just no animation. The "interesting" scenes are just like 3-5 pictures with voice acting on top. The art is good, the voice acting is decent, but for these to work, they should be animated imo. If pictures alone do it for you, then go for it, if you want animated scenes, then don''t buy this game.', 'Very Positive', 93.75, 8.23, 3.60);
INSERT INTO reviews VALUES (70644, 2738940, 281, 'Every single time its the same infuriating crap with this dev.\n\nI instabuy their incredible games and have no choice but to feel guilty that I got it so cheap.\nCharge more, you bastard!', 'This game is extremely easy to put down. I''ll play for 5-10 minutes, feel zero engagement, debate why I would boot up another run, and just alt+f4.  I can''t find the hook, yano? That thing where you''re like, "Oh snap, this is great!"\r\n\r\nYou WASD your away around enemies and projectiles, struggle to see through the visual noise, and occasionally get an upgrade. But the upgrades never felt impactful. Maybe I do more damage but there''s no way to tell -- you don''t even get a "numbers go up" moment. ', 'Overwhelmingly Positive', 95.37, 73.02, 0.75);
INSERT INTO reviews VALUES (70664, 2739590, 775, 'Legally, it''s questionable\nMorally, it''s disgusting\nPersonally... I like it', 'Possibly a good game..\nBut i stop playing when i realize that you can''t rape a male natives as female..\n\nAnd it''s lack of femdom element in the game.\n\nSo it''s not recommended for anyone that into femdom', 'Very Positive', 92.39, 39.92, 3.00);
INSERT INTO reviews VALUES (70667, 2739630, 191, 'Genuinely incredible. Gave me feelings I''ve never felt before. Touched on topics and themes so personal to me that I''m struggling to think of *any story* I like better than this one. Made me experience catharsis. I think I understand now what people mean when they say art speaks to them. I can''t believe this is only the first of five planned chapters.', '', 'Overwhelmingly Positive', 100.00, 24.83, 0.00);
INSERT INTO reviews VALUES (70673, 2739830, 287, 'The gameplay is great, but just like the original King Arthur, the difficulty spikes are nightmarish.  Work up to play the game on hard, or very hard, then hit the endgame and it is impossible.  Be ready, bc if you have a few hundred hours in King Arthur, normal will be too easy, but then the jump to hard or very hard will have a few fights which seem impossible despite just crushing it on normal or hard.', 'I''d love to be able to recommend this game, but I can''t - it''s just too short. The turn-based combat is great! The story is engaging to start with and the character levelling and loot are great, but I finished the main campaign in 8 hours! After that there are no more characters to be found, no more levels to be gained and almost all the loot you find is useless because you already have the best loot available. There''s lots more content, but it is just an endless parade of repetitive, rather poi', 'Mostly Positive', 70.03, 51.97, 13.12);
INSERT INTO reviews VALUES (70698, 2740280, 208, 'Way better than Undisputed', 'Game is trash dont waste your money. Just box in real life.', 'Mostly Positive', 74.52, 30.23, 28.85);
INSERT INTO reviews VALUES (70726, 2741490, 113, 'Experience the stress and anxiety of working in the food service industry.\n\n\nAnd I guess theres also a ghost haunting you has well but thats also par for the course.', 'I really REALLY wanted to like this game, but I did not.\n\nI enjoyed making pizzas even with the clunky UI/Mechanics. But the spoops/story was lacking and the puzzles were either broken or buggy for me so I couldn''t even complete the game. \n\nMaybe if I were able to finish, I could recommend it. But as it stands, it''s gonna be a no from me. Sorry frands :(', 'Mostly Positive', 79.65, 1.53, 2.27);
INSERT INTO reviews VALUES (70730, 2741560, 345, 'A game where I can demonstrate my inability to manage a budget without my wife getting mad. Good to see I haven''t gotten any better at this game since childhood.', 'A relaxing classic, featuring timeless music, and outstanding gameplay depth. It sorely needs to be patched though - the GOG version is clearly better now as that one has a 16:9 resolution, and fixed the scroll speed issue.', 'Very Positive', 84.35, 10.97, 8.48);
INSERT INTO reviews VALUES (70734, 2741620, 200, 'of all the puzzle games i''ve played and not liked, this ones got the most aura', 'Way too short and there''s no challenge at all. The entire game is just decoding an alphabet. The voice acting is excellent though. \n\nOverall, not worth £4, but 99p would have been reasonable.', 'Very Positive', 92.00, 0.20, 0.83);
INSERT INTO reviews VALUES (70779, 2742830, 2394, 'Upgraded a unit to 100 health, who took half damage, returned 100 (max health) back to attackers, and boosted it''s own damage and armor each time it was hit.\n... Then managed to duplicate that guy twice so I had one per floor -- all on my first run.\n\nThe crazy combos are back!\nEasy thumbs up.', 'There is very little to differentiating this from the first game. I don''t feel there was a point to continue playing as I had felt burnout coming all the way back from when I played the first game, which was due to the gameplay loop between runs being too similar to each other.', 'Overwhelmingly Positive', 96.37, 5.97, 0.98);
INSERT INTO reviews VALUES (70812, 2743850, 206, 'love it so far. great maps, even greater movement.\nwas a huge SSX3 fan - this is a very good recreation.\nlooking forward to whats to come.', 'When there''s a game, maybe there''ll be an review.\nIn the meantime, following a tutorial on YouTube isn''t enough to make a game.\nIt''s not early access, it''s the software''s YouTube tutorial.', 'Overwhelmingly Positive', 96.60, 1.02, 0.08);
INSERT INTO reviews VALUES (70817, 2744010, 200, 'While I do love the game, it''s almost unplayable. I am an indie pc gamer, and I usually play all my games on my pc, which is just a regular Dell for work with Windows 11. I asked my husband to lend me his Steam Deck so I could finish my game, but even there, it couldn''t run correctly. It crashed, hard, to the point where the Steam Deck got restarted thrice. I humbly ask the developers to optimize it, because it was fun and cute. I want to finish it, I''m learning from plants, and I even want to b', 'A charming concept, but a pretty poor execution. \r\nI was very entertained for the first 2-3 chapters, but the more I played, the more of a drag it became. Moving and placing objects is janky and since its the only thing you do it becomes VERY annoying, the clipping is not the greatest, sometimes i place a plant directly next to a humidity source but its need for humidity isn''t getting fulfilled, camera movement being so limited its hard to place object properly, etc.\r\nAnd since this game is comp', 'Very Positive', 94.00, 33.40, 6.63);
INSERT INTO reviews VALUES (70826, 2744230, 102, 'Y!YW"TG"R?SHYG!NLSYCT!2 is just as fun and the title still rolls off your tongue.', 'Full of mobile game ads.', 'Mostly Positive', 72.55, 6.08, 0.35);
INSERT INTO reviews VALUES (70896, 2745800, 165, 'While this game is definitley not for everyone, i liked it a lot. Because it reminds me a bit of Game Dev tycoon.', 'Overall a fun concept, but clearly made from a male perspective and a pretty sexist one at that. It''s also really annoying that you can pick your character''s gender but despite picking female, I keep getting called he/him when other writers and reviews reference my character. It''s fun to discover the different plots and play around with the different challenges and I like how it doesn''t shy away from more controversial themes, but the way certain things are handled are just not enjoyable as a fe', 'Mostly Positive', 70.91, 11.37, 1.93);
INSERT INTO reviews VALUES (70900, 2745870, 284, 'Nostalgia with a fresh coat of paint of improved animations, new voice acting, and higher quality sound. All that''s missing is the science teacher to hide my screen from.', 'i love that the old game is back but its so horribly unbalanced its very frustrating and with how the enemy gets instant support and much quicker spawn time then the player there is a better way then to make it this frustrating on the medium difficulty', 'Very Positive', 90.14, 1.85, 1.15);
INSERT INTO reviews VALUES (70905, 2746030, 106, 'Easily 8/10\r\nMack recommended this in his recent video, and I''m glad I checked it out.\r\nRTS, tower defense, rouge-like with a few fun twists. \r\nDig until you run out of fuel. Gather what you can and get back to digging. If you stay in the level too long you will perma-die.\r\nWhile in the level you gain upgrades for the current run that you can craft, and bank points that give you permanent upgrades that can be used on the next run.\r\nReminds me a bit of Infested Planet, Mindustry, or Lumencraft.\r\n', 'Game is a lot more stressful and different than it seemed in the trailer. You''re not slowly expanding and taking ground, you''re on a few-minute timer to get all the resources you need to fuel your drill and complete the level and then do it all again. Then you also have a complete information overload in both the run progression and meta progression. There''s also some weird power scaling that can leave some of your units/defences completely useless and a waste of space doing 9 damage and dying i', 'Very Positive', 86.79, 37.73, 1.98);
INSERT INTO reviews VALUES (70954, 2747550, 462, '48 year old geezer that played games with this charming sprites in the vein of Blood.\r\nOne of the best I''ve ever played, let''s see what comes more with the updates.', 'Had a ton of potential but got rushed out of early access before it felt ready... NOT worth full price and probably not worth at all because it got abandoned because it seems it didn''t get enough attention (also TWO price increases before pushing this game to "full release" is just rude, id keep an eye on the devs and publishers and not buy anything from them again!)', 'Very Positive', 84.42, 16.47, 0.73);
INSERT INTO reviews VALUES (70966, 2747780, 334, 'As a dishwasher I can in fact say this is my life.  Someone please help me escape.  I am a rat in a cage.', 'Why would you put a platforming section at the end of your game?? Could there be some kind of precedent set up during the main game, so that the ending isn''t a frusteration fest?', 'Very Positive', 87.72, 7.07, 17.15);
INSERT INTO reviews VALUES (71046, 2749770, 944, 'Love it, would like to see more keyboard shortcuts as this game is seriously straining my wrist. To be fair, I did play for 5 hours straight.', 'Gonna try grinding it out a bit more but seems a bit too slow paced for me, to the point of being a bore.\n\nOnly thing it has going for it are the space kitties but even that doesn’t save it. \n\nAnd I swear…if these fools ask for another cheeseburger without cheese, imma lose my shiz >.>', 'Overwhelmingly Positive', 97.03, 23.67, 2.60);
INSERT INTO reviews VALUES (71054, 2750000, 368, 'I have been waiting for this to come out for a long time.\n\nThe demo was great and the full version is better. It''s a refreshing take on the automation genre with a very unique focus on logistics. I have a few issues with the early progression, specifically with the order that the trail types are unlocked, but I still highly recommend the game for anyone that enjoys games like Factorio, Dyson Sphere Program or Satisfactory.\n\nThe music, ambiance and atmosphere are especially good', 'I really wanted to like this game. The ant mechanic is great at first but there are some big problems. You think its a factory game but its more of a puzzle game, its like the game designers had a certain way in mind for you to play and you need to figure it out otherwise it becomes painful to play. The ant factories desperately need a control on them to limit amount of ants made, the timers and counters just don''t cut it. You either have to manually control everything or you end up with a ton o', 'Very Positive', 87.23, 0.60, 55.03);
INSERT INTO reviews VALUES (71055, 2750080, 352, 'I used to be a fan of the old Settlers games, particularly the ones that came out on the Commodore Amiga and eventually on PC, such as Settlers II and The Settlers II 10th Anniversary. These were the original ones I played (and still do) until the series took a different direction.\n\nThis new game comes close to the old days but still falls short in some areas. For instance, the AI doesn''t expand its land and only tries to attack with its army, which is easy to wipe out. However, I wouldn''t say i', 'Is that it? It seems like buying half a game. There are only a low number of maps, a low number of buildings and abilities available. Its a disappointment compared to the older games of the series.', 'Mixed', 46.02, 227.20, 13.33);
INSERT INTO reviews VALUES (71087, 2751000, 1865, 'The best Ubisoft game since Rayman Legends, so you know damn well the entire team behind it will be laid off', 'Ubisoft connect account needed to login and play. \n\nGet the fuck outta here.\n\nEdit: I decided to try it to see if it was anything different from other modern-day-designed games, but it''s not. \n\nLike most modern games, it feels disjointed and thoroughly unoriginal. A bunch of individual ideas were pulled from different sources and tossed into a blender, leading to an incohesive whole of a gameplay experience. (i.e., parrying, dark souls-style bosses, designed around modern-meta of speed running )', 'Very Positive', 86.11, 31.58, 0.85);
INSERT INTO reviews VALUES (71091, 2751050, 214, 'good but needs more difficulty options and late game scaling. after around round 40 it just becomes repetitive and dull. Overall solid and fun game though could be wayyy better with some developments.', 'great game but the visual bugs mentioned by others sneak in the more you play so I found on two runs that after about day 50 I couldn''t play properly as the whole screen would fill with glitching animations. It''s a pity because the core dynamic is solid but you can''t complete it', 'Very Positive', 84.58, 2.53, 7.32);
INSERT INTO reviews VALUES (71186, 2753270, 194, 'I would like to see content in Red Dead Redemption that would be in the spirit of the wild West. Among other things, it would be great if there were horses and, for example, sheep in the game — for more variety.', 'Negatives:\n-Camera controls horrible, it''s like camera at end of rubber string. Also seeing my mouse cursor all the time on screen brakes the immersion.\n-Quest are written by absolutely braindead person, I can see why player is not given a revolver in the beginning, because I would have shot Claire pretty fast.\n-No option button in esc menu, wtf devs?\n\nPositives:\n-You can uninstall it.', 'Mixed', 67.53, 4.00, 0.57);
INSERT INTO reviews VALUES (71195, 2753520, 167, 'This game helped me so much and made me learn a life lesson and pee. Do not pee at 12 am in the middle of the night or your toilet will be gone. Your toilet is a toilet. What the hell am i writing.', '.', 'Very Positive', 92.81, 0.37, 1.87);
INSERT INTO reviews VALUES (71200, 2753620, 226, 'You can not tell my family that I spent 20 hours throwing fruit into a bowl..', 'I DON''T LIKE FRUIT!', 'Overwhelmingly Positive', 98.67, 19.77, 1.00);
INSERT INTO reviews VALUES (71203, 2753720, 120, 'Yet another new anomaly horror, and a fun one too! With 81 anomalies to find youll get around 3 hours of gameplay if you wanna see anything, and there are some creative ones with the cute little mascot character cue-chan. Also no cheap jumpscares, always appreciated!', 'i cant play the game. every time i try to open it, it shows me the main screen and but when i start the game it shows me a black screen with the controls then turns fully black and wont let me close it and wont let me press anything then after a while i just closes. i have downloaded the update thing as well and it still doesnt work', 'Overwhelmingly Positive', 98.33, 2.67, 3.12);
INSERT INTO reviews VALUES (71236, 2754380, 2306, 'i''m a huge detective/investigative game fan, and this is among the best out there, if not the very best. while it doesn''t have the unique art appeal of obra dinn or the golden idol series, it more than makes up for it with the amount of breadcrumbs to follow and an incredibly satisfying gameplay loop and storyline. i welcome the roottrees to the detective game scene with open arms and have high hopes for what the creators have planned going forward.', 'Really enjoyed everything about this game and was going to give it a glowing review until the credits rolled and revealed that it used Midjourney to generate some of the art for the initial version. While the developer states that this version doesn''t use that technology for any of its art, if I''d known this game was built on stolen and environmentally destructive art, I wouldn''t have bought it.', 'Overwhelmingly Positive', 97.57, 26.67, 15.42);
INSERT INTO reviews VALUES (71334, 2756920, 1893, 'This game is something special. I''m legally blind and have never been able to drive. I missed out on the feeling my family and friends had getting their first car and the sense of freedom it brings. This game has given me the ability to experience those moments of freedom and adventure for myself.  Thank you to Y/CJ/Y for all the hard work and passion you poured into this game.. At 39 I finally feel what it''s like to get behind the wheel.  10/10', 'The description and videos drew me in, the positive reviews sealed the deal. Playing the game was underwhelming at best. The "challenges" on the road are basically just puzzle games where you match colors and patterns. Customizing your car primarily affects the colors and patterns during the challenges. The hitchhikers aren''t very memorable and feel more like extra inventory or a tool to, can you guess? Help with the colors and patterns of the challenges. \n\nEverything is point, click, or drag. M', 'Very Positive', 94.03, 24.45, 6.37);
INSERT INTO reviews VALUES (71346, 2757330, 2655, 'In the first 5 minutes, i watched Jecka get abused by her dad. Him wanting to sleep with his daughters friend and Jecka wanting to turn gay.\n\nW game!', 'Definitely the worst way to end a series, had the least amount of endings and each route had maybe 1 to 2 choices tops. It mostly felt like the writer hated the fact his game became so popular with certain bases because of tiktok and word of mouth so he needed some weird psuedo-intellectual misery porn to cleanse his palate, which his last message after achieving all the endings all but confirms. It was a disappointing end to an otherwise great, dark comedy visual novel series.', 'Mixed', 53.33, 10.77, 3.48);
INSERT INTO reviews VALUES (71352, 2757490, 216, '🙏BLESS🙏', 'As a fan of needy streamer overdose I had to get this game because I wanted more of it so I bought this on sale and... Eh. It''s well made at least. This game comes with 3 different games. The first game is a visual novel with Ame. It''s well made and has some good choices in it and I like the dialog but it just has a lot of small things missing that make me feel mixed. First there''s no saves. Granted it short but I still feel like that needs to be included. Anytime you want to play this you have ', 'Very Positive', 86.57, 1.20, 0.47);
INSERT INTO reviews VALUES (71368, 2757720, 191, 'I remember when i would get back home from school, and finish homework and finally play some sonny. Now i''am much older,the music,the art and the game play brings back memories. They really need to create one more proper sonny game and tie the story line together so we can finally have our closure.', 'EDIT: According to SteamDB 2 hours after they released the game on steam, they removed the line "updated for modern hardware".  how scummy of the devs to do this.\n\nSonny 1 & Sonny 2 are great games, this "port" however is not. \n\naccording to the devs "These games remain true to their original form,  but now feature updates for modern hardware,  both games grouped together, and all new achievements. All work on the port has been done by the original development team."\n\nYet we see no updates for m', 'Very Positive', 92.15, 5.98, 11.17);
INSERT INTO reviews VALUES (71446, 2759810, 139, 'After taking the driving test, I had no confidence and always felt like it was difficult. So, I procrastinated and didn''t learn how to drive. On the recommendation of a friend, I bought this software and practiced it. I didn''t feel as difficult as I thought, so I decided to get my driver''s license in one go.', 'Meh. Not worth 5 euro or w/e you''d pay for it. Suspicious comments saying "I can drive a real car thanks to this simulator" are  not helping either.', 'Very Positive', 84.89, 4.05, 0.15);
INSERT INTO reviews VALUES (71601, 2763670, 2641, 'This game was exactly what I needed on a Friday night. Finished it and I feel like I have become a better person. I have ascended to become one with the eggs.', 'I guess this game is some kind of inside joke that I just don''t get. Flipping eggs and reading nonsensical dialog in a dystopian world; it just wouldn''t click for me.', 'Overwhelmingly Positive', 97.31, 2.75, 1.22);
INSERT INTO reviews VALUES (71650, 2764750, 131, 'This is 3 or 4 steps up from Phasmo. This deserves success. Everything is executed better. The UI, the controls, the gameplay. I love how you can easily do multiple things at a time with the phone and devices.   Everything is great and fun to do over and over.  I love it. Great job. I really hope this game gets attention and praise.', 'This game truly has potential. It really does, but the constant shutting off the breaker and the fact that you lose all you equipment if you die is insane. The equipment costs way too much for you to lose it completely. I can deal with the shutting off the breaker every 5 seconds. I cannot deal with the fact that even on novice you lose all your equipment you took with you if you die. That is absurd. Especially for brand new players that just getting into this game. Yes, the game give you loaner', 'Overwhelmingly Positive', 95.42, 2.75, 4.35);
INSERT INTO reviews VALUES (71677, 2765460, 138, 'All the fun of a mobile star trek gacha game without the scummy monetization. Pay one fair price and get the game, like it was in the olden times.', '“Steam Deck Verified”\n(Only playable online)\nWhy did they do this?\n\nEdit: AND NOW ITS ON SWITCH AND PLAYABLE FULLY OFFLINE?! Make it make sense!', 'Mostly Positive', 70.29, 9.93, 0.37);
INSERT INTO reviews VALUES (71678, 2765490, 105, 'Absolutely worth the price, very fun. it matches what it is like to be the healer in a MMO game (as someone who has spent decades ALWAYS being the healer on dungeon runs and raid groups). \n\nBe warned, it is totally unrealistic in one way and that is the tank doesn''t run as far ahead of the healer as possible, pull every mob they can find and then die quickly while you are still trying to reach them, then turning around after you raise them to yell at you for being ''a bad healer''. So in that sens', 'I requested a refund after about 45 minutes. The concept is cool and I don''t mind the old graphics, but this game becomes a ''party movement'' simulator more than a healing simulator. Your AI party won''t avoid telestrations at all and the UI makes it hard to know when you''re healing an ally or damaging an enemy. \n\nI lost to the 2nd boss twice not because I oomed or got unlucky skills, but that the boss requires most of your actions to be focused on moving your party around the room to avoid his at', 'Very Positive', 86.67, 1.82, 0.95);
INSERT INTO reviews VALUES (71746, 2766860, 103, 'My future aint looking so bright', 'The translation is rough sometimes one answer felt like the exact opposite of what I thought it would be from the translation and the confusing pronouns and family type talk really confused who was who to each other with how different the languages are. I like the characters tho so if they fixed the translation issues this would be much better.', 'Very Positive', 91.26, 6.25, 1.87);
INSERT INTO reviews VALUES (71774, 2767520, 325, 'My community doesn''t even care about me anymore. All they want is to fish and climb the leaderboard. 10/10 game.', 'It seems fun to play, but makes me lag too much when streaming. Don''t understand why this requires a 2080 GPU. My GTX 1080 can''t handle it.', 'Overwhelmingly Positive', 97.85, 93.02, 0.88);
INSERT INTO reviews VALUES (71805, 2768430, 11642, 'This one''s a real monkey''s paw kind of game. Someone out there wished for a new diablo game that was good and the finger curled menacingly.', 'There is a person corrupting save data and stealing IP addresses through the game. Please do not join lobbies that look malicious or contains stuff like this. You are risking compromising your save data, personal data, and steam account possibly.', 'Overwhelmingly Positive', 97.05, 28.57, 21.90);
INSERT INTO reviews VALUES (71823, 2769080, 139, 'I love monke.', 'Not really a Metroidvania, instead it''s a somewhat linear 2.5D action adventure game. You''ll backtrack occasionally, but because you got lost not because you acquired a new key item etc. \r\nSurvivor Instinct''s main problem is that the basic gameplay loop is set in the first 30 minutes and it doesn''t really change. There''s some real epic high points here where you''ll escape from Titans in sequences similar to the Ori and the Will O'' The Wisp boss battles, but they''re not that common and the majori', 'Mostly Positive', 74.10, 14.13, 6.15);
INSERT INTO reviews VALUES (71828, 2769210, 147, 'It let me cast Stop on a boss and I just auto-attacked it to death and it couldn''t fight back at all! Status effects seems worthwhile in this game', '', 'Overwhelmingly Positive', 100.00, 13.83, 0.00);
INSERT INTO reviews VALUES (71952, 2772650, 143, 'Was not expecting an atmospheric psychological horror game glad I stayed for the long haul the puzzles and jumpscares were great.', 'Game was too easy, speedran it in 4 minutes, fully busted, nutted, and splurged all over my monitor\ngonna need to do better than that against a grand master baiter ranked jerkmate player\n\nDo better', 'Very Positive', 87.41, 408.40, 0.08);
INSERT INTO reviews VALUES (71957, 2772750, 2785, 'STFU about being mad about the AI portraits. One sole Polish guy made a strategy game comparable to a paradox game, great game made by small indie dev.', 'This game uses AI slop images for units and leaders, also it just throws you into the gameplay, no tutorial, no nothing. \nI Absolutely love the second game in the series and was mega hyped for this one to release, but I was dissapointed once it released.', 'Very Positive', 85.06, 3.48, 1.12);
INSERT INTO reviews VALUES (71980, 2773280, 2400, 'Befriended a lonely man addicted to glue, became addicted to glue myself. Man in a black coat approaches us and offers us glue for killing each other, my "friend" instantly smashes my skull. \n\n10/10 game', 'Recent changes to the game have made it disrespectful towards player time. It can take multiple hours to get certain roles now as a prole only to get two shot by scum. It''s also pushed the balance towards scum rotting the server so the continuity that used to happen between play sessions is pretty much dead. If you have time to no life it, the game can be fun, but right now the juice ain''t worth the squeeze. The game has real potential if they balance the amount of grind you have to do to have f', 'Very Positive', 87.38, 1.53, 183.43);
INSERT INTO reviews VALUES (72006, 2773870, 100, 'Finally a game that matches my freak', 'A novel concept that doesn''t result in fun.\n\nAreas are sparse, bland and not immersive like some really old maze games you would see in the 80''s on DOS.  \n\nI''d take Eye of the Beholder or Time Crisis over this any day.  I want to say the game meshes these two but what we get is a game that feels like a proof of concept prototype and not a fun experience at all.', 'Overwhelmingly Positive', 97.00, 3.32, 0.17);
INSERT INTO reviews VALUES (72023, 2774380, 258, 'a perfect encapsulation of what a twink from hong kong finds most terrifying: numerological motifs, references to american media, and black nurses. I think that''s why he stuffed them into mortuary lockers- not even metaphorically. great game for shoving your friends into sawblades.', 'Use of AI generated content', 'Very Positive', 82.17, 3.22, 3.95);
INSERT INTO reviews VALUES (72065, 2775370, 184, 'you know a game is good when one of the images on its store page has activate windows in the corner.\n 10/10 truly a work of art', 'dev barely made any progress compared to first game, gameplay became even more lamer than before, randomization of npcs doesn''t help you in card battles too, and it''s hugely on AI stuff or stolen assets, like it has Guts sword but with rusty render on it wtf. clearly an refund, tis thing is again just for pseudo-schizos who will goon to main girl and nothing more about it.', 'Overwhelmingly Positive', 97.28, 5.42, 1.83);
INSERT INTO reviews VALUES (72104, 2776450, 143, 'A fairy just pops out of nowhere, gives you a gun and sends you off to commit interdimensional crimes. you get to travel the multiverse, steal anything not nailed down, meet interesting characters and use them as meatshields/unpaid workers, grow stronger, the works. Its ridiculously good!', 'seemed like a good game until I realized every single art asset was AI generated', 'Very Positive', 89.51, 386.50, 1.83);
INSERT INTO reviews VALUES (72111, 2776570, 147, 'A great hidden cats game by Travellin Cats, and possibly the most difficult one yet. This time, it''s set in a Germany-inspired town.\nThere are some interactive elements, too... including a MUSHROOM JUMPSCARE.\n\nIf you like hidden objects and/or cats, this is a good one.', 'This game has a huge drop in quality compared to the previous installments. The line work is fuzzy. Objects are placed rather strange. Some structures don''t make sense at all. The text is just gibberish (the games before had always readable text).\n\nAll of this screams at me that this game was AI generated.', 'Overwhelmingly Positive', 96.60, 0.60, 0.23);
INSERT INTO reviews VALUES (72238, 2779440, 229, 'I suck so horribly bad at this game....\n\n...and I love it! I bought this game immediately for the sole reason I am part of the greatest gaming community in the world and do not regret it at ALL!', 'Hot Dog Runner is a 3D endless runner released in 2024 by Aidor Gaming and Neebs Gaming Games that asks the question “how much can you reasonably expect for $2?” The game is about a weird little guy named Simon who likes hot dogs and he’s running and there’s hot dogs and he eats the hot dogs. Sometimes there’s pits and crates and torii for some reason and if you run into them Simon falls down and hollers.\n\nI did not know this when I bought the game, but the publisher is a YouTube channel/gaming ', 'Overwhelmingly Positive', 99.13, 0.20, 0.77);
INSERT INTO reviews VALUES (72244, 2779570, 102, 'It''s amazing how quickly your brain can adapt to a new type of motion. At first, I struggled to keep two characters in focus simultaneously, but that made it all the more satisfying when I finally pulled it off.\n\nIn the sea of bullet-hell action roguelikes, it''s rare to find something truly unique. This game not only brings a fresh concept but also implements it brilliantly.\n\nHighly recommended!\n\nI hope the developers will add more levels in the future, but there is plenty of content for the cur', 'Do not buy this game if you are not going to play it exclusively as a local co-op and if you do not have two controllers. Its just too weird of gameplay to be worth the time investment as a solo player. I can imagine the game is quite fun in co-op mode, but its really a chore in single player.', 'Overwhelmingly Positive', 95.10, 2.97, 0.17);
INSERT INTO reviews VALUES (72285, 2780710, 185, 'I''ve played the testing version, and this one already has more content. Loving it! It feels and plays like the dev actually put some real thought into it.\n\nIf you like bullet-hell games or survivor-likes, you should definitely give it a try.', 'I don''t like the design decisions of this game. The randomness is too brutal und punishing, while the meta progression to soft it up is locked behind content thats too far away. You have to struggle to the mid- and endgame without meaningfull progression in order to unlock basic upgrades. Resulting in many aborted runs. This is not worth my time.\nSince you have only a limited amount of rune slots per run, the worth of runes and stats they provide have to be evaluated differently compared to othe', 'Very Positive', 90.27, 0.38, 14.17);
INSERT INTO reviews VALUES (72294, 2780980, 7271, 'A fun game to play with friends. Current state of the game is very polished. My only complaint would be that the gameplay doesn''t change much so I feel that there needs to be a new map or two soon.', 'You are in early access.  Don''t start putting out paid cosmetic dlcs already.  Less than 6 months in early access and you have paid cosmetics hitting.  This is a terrible practice.', 'Very Positive', 85.17, 14.03, 16.85);
INSERT INTO reviews VALUES (72304, 2781210, 223, 'Games like this remind me of those urns found in ancient pyramids or tombs, where the owners loved their pets so much that they wanted to be buried together. That they built statues to them, memorialized them, wanted the world to know, someone, anyone, anyone who will ever see this, hundreds or even thousands of years later, that this animal here with me for eternity was my little buddy and I loved them very much.\n\nAhem. Anyway, good game.', 'The fuck did i just witness?\n\nI would say this is for kids... but i''m not even sure a kid would understand what happened.', 'Overwhelmingly Positive', 99.55, 0.52, 0.47);
INSERT INTO reviews VALUES (72362, 2782610, 153, 'If you like exploring, crafting and looting your goblin brain will be very happy.\r\n\r\nThis is incredible remake of phone game. All microtransactions removed and gameplay overhauled!\r\nHow this port from mobile game was handled is the most impressive and deserves all the prize.\r\n\r\n', 'This game is a relaunch of a f2p p2w mobile game, even though the microtransactions were removed, the insane grind and repair costs are still present in mid to late game. Until the game has been rebalanced, i wouldn''t recommend anyone to play it yet.', 'Very Positive', 86.93, 41.42, 23.50);
INSERT INTO reviews VALUES (72436, 2784470, 2808, 'Rats killed my run... i had 12 rats plot level 200 and i got the splicing perk, now the game crash every time i try to  continue the run.\nI want to finish the run  ill try to log in the game in the supercomputer of a friend of mine and try to check the stats of rats\nRats', 'The game has a lot of interesting ideas, but it feels like there is a major problem with player agency.\n\nMost of the scaling in the game occurs through buildings that buff units at the end of each round AND is often multiplicative. This means that in most cases you have to lock in a build relatively early in the game because you have to scale your units in order to keep up with the enemy. It also makes it very hard to ever pivot a build because your new units will be so far behind on the scaling', 'Very Positive', 94.30, 10.48, 0.77);
INSERT INTO reviews VALUES (72444, 2784620, 144, 'ROGUE FLIGHT absolutely OOZES charm and mid-90s nostalgia from every corner. With poppy visuals and responsive controls that manages to keep everything readable and in your hands even in the most enemy saturated segments. Though I sadly found the bosses themselves to be a bit on the bland side; struggling to communicate their scale or really stand-out in any way. \n\nStill I''d be the third biggest liar in the universe if I said I didn''t enjoy the game... so there you go... twelve gold-plated space', 'I wish Steam had something between recommending a game and not. This is not a *bad* game, but it is not one I would recommend to others or believe is worth its release price of $20.  \n\nFlashy presentation but very shallow gameplay and uninteresting enemies. You''ll experience all of the game''s mechanics in the first 10 minutes, and the story doesn''t do much to keep things interesting. You''re forced to complete the game four times to see all of it, with the final two runs barely adding anything of', 'Overwhelmingly Positive', 97.22, 6.90, 3.87);
INSERT INTO reviews VALUES (72476, 2785200, 139, 'listen, if your looking at this that means you like horror and dinosaurs. just buy the game already!!', 'Game is miserable and clearly designed in such way as to stretch play-time to that  sweet 2-hour refund point. Even copious UE5 assets can''t help the sub-par visual direction. Microphone mechanic is a pointless gimmick as it usually is in UE5 indie horror games at the moment. \n\nFor 5 dollars this game could at the very least be a funny novelty but for $20 without a sale this is unhinged.', 'Mostly Positive', 79.14, 1.07, 2.60);
INSERT INTO reviews VALUES (72533, 2786680, 989, 'This game has a big bug. When i looked under Lin''s skirt in the wall climbing scene, there was weird black zone under her skirt. That need to be fixed', 'admin rights on each launch sus', 'Overwhelmingly Positive', 95.65, 11.67, 0.78);
INSERT INTO reviews VALUES (72541, 2786830, 174, 'rust if it was actually good', 'I did not see the man myth himself. I don''t think he is here don''t buy this game,', 'Mixed', 67.24, 0.23, 0.20);
INSERT INTO reviews VALUES (72559, 2787320, 406, 'Just saw a note from the devs to Sharon. Laughed. The whole game has that vibe. I''m more used to first person, it''s maybe a bit more clunky than the last game but it''s good to see a second entry in the series. I''m pleased the devs reunited after the studio was shut down.', 'The humor, and everything that makes the first game good, its still here. But the game has a absolutely fatal flaw. The controls suck. The forced third person is not great, you can''t even adjust the camera. But the part that kills the game is the animations, they can''t be interrupted. When moving or doing things the game won''t respond to inputs its not ready for. This makes movement very floaty and unresponsive. Delayed and ignored inputs are not ok. Its like your on ice and lagging. And being u', 'Very Positive', 88.67, 5.72, 1.47);
INSERT INTO reviews VALUES (72597, 2788310, 263, 'Twilight survivors is modern day bullet hells done right with simple controls and mechanics that you can ease into but need time and discipline to master as every single character in this game pilots a lot differently and how they interact with the simple controls. this game is always about trial and error no character is bad you just have to actually take the time to learn the weapon combinations and passive skills. i will say though for anyone looking to 100% this game there is a large spike i', 'Ultimately pretty disappointing. I usually won''t complain about a game this cheap, but compared to other similar games with similar price points, it is bland. I played about 4 rounds and the weapons are all the same each time. There are other survival-likes maybe $1-$2 more that will be a lot more fun and not be boring after an hour like this game.', 'Very Positive', 93.92, 54.25, 1.97);
INSERT INTO reviews VALUES (72608, 2788520, 388, 'wife is addicted to this game. I have caught her trying to take apples and sell them to people on the weekends because of this. I love that the cozy game distracts her from the ever approaching doom of the economy and her existential dread, however, I think she might have a misconception about traveling markets. (consider making permits for each town for more realism).', 'Heard about this game from my friends. Had a gift card, so I figured why not?\n\nBefore the game even starts you''re greeted with a "land acknowledgement."\n\nImmediately refunded. I refuse to support anything made by radical far-left activists who hate me and people like me.', 'Overwhelmingly Positive', 95.10, 58.05, 0.08);
INSERT INTO reviews VALUES (72625, 2789130, 105, 'The game has a good base and interesting story, that''s why i''m leaving a positive review.\n\nBut there are too many bugs and the game literally unplayable\nyou will suddenly fly into air or lose car parts while you were driving normally without hitting anything\nand many functions of game is bugged or not working, like radioing for quests or pull-over\nwish they can fix the game......since I''ve already pass the refund due......', 'Dont buy this game just don''t. honestly at this stage Aerosoft just shut your doors you release games in a stage that are tech demos and charge full price.\n\nCars slide like nothing, runs like trash, so many glitches this is unacceptable in 2024 just shut down the studio you lot won''t accomplish anything i could of done it better with asset flips which a lot of this looks like you tried', 'Mostly Negative', 30.48, 4.37, 0.67);
INSERT INTO reviews VALUES (72637, 2789460, 225, 'Ale Abbey made me realize that I did everything wrong in my life, and how much better it would have been if I was a monk brewing beer in a monastery!\nI think it''s a little too late for a career change, but I can still have some fun by playing this gem.\nAle Abbey is the most entertaining tycoon game I tried in many years. It''s easy to play but offers a lot of depth, and it''s full of fun details. \nThe pixel art is a true joy for the eyes and the music sets the vibe. \nWhile being an early access ga', 'The pixel art is amazing and the soundscape is fitting for the game. Unfortunately, the core gameplay itself is a repetitive chore simulator with very little in terms of strategy or challenge. I think this game can be redeemed with further development. I wouldn''t recommend buying it at its current state.', 'Very Positive', 92.89, 24.52, 3.93);
INSERT INTO reviews VALUES (72648, 2789810, 343, 'when playing balatro, its very easy to get a baseline understanding of what your ballpark score will be per-hand.\nwith Bingle Bingle, its next to impossible. The information just isnt on the screen or optionally available until its scoring', 'Starting with the positives: the game has a nice presentation; the sounds, music and visuals are good and obviously reminiscent of Balatro style-wise. I absolutely like the look of it.\n\nUnfortunately, the gameplay itself is nowhere near as polished as Balatro. Whilst I appreciate it trying to do something else in the ‘casino-sphere’, it somehow feels convoluted at best, and at times downright confusing. I get the impression the style and setting was decided on first (which is not necessarily a b', 'Very Positive', 83.09, 7.82, 0.75);
INSERT INTO reviews VALUES (72669, 2790330, 469, 'cant believe it took everyone this long to make another typing game thats a real game and not a beginners kids flash game', 'Really cool concept of typing to move, pick up objects and kill enemies.\nI have to rate this badly though because I refunded the game simply because you can''t join other people''s games unless a lobby code is used to find the lobby. That means unless you have mates who are into these sorts of games, you have to play solo. I don''t want to have to join a discord or anything to reach out to play with others, I just wanna search for open lobbies and join them.\n\nI''ll revise this should the above chang', 'Overwhelmingly Positive', 95.52, 1.18, 1.02);
INSERT INTO reviews VALUES (72785, 2793370, 362, 'Its a fun, short game in the style of exit 8. Its a ''spot the difference'' horror game all about remembering details and getting to the end. This one also has a story included in it making it different from the other ones. And I think that all in all, its a great time to play through. \n\nMy only real complaint is that 100%ing this game is a drag. The way how exit 8 does it, is that the anomalies you dont have, have a higher chance of showing up on any consecutive playthrough. This game makes it ap', 'I haven''t reviewed any games on Steam until now, whether I liked them or not. However, this game has the worst graphics I''ve ever seen in my life, and no matter what I do, the image is always blurry. I''ve tried everything I can, but it''s a terrible, low-quality production.', 'Very Positive', 84.81, 2.43, 1.20);
INSERT INTO reviews VALUES (72799, 2793710, 713, 'Amazing game! I initially got this because I like the "find anomalies" genre. But I''ve got a lot more than I expected. The atmosphere in this game is incredible. You could call this a job simulation game as you are hired to inspect the quality of the dolls in a doll making factory. But you''ll get much more than you signed up for. Short but sweet, creepy and atmospheric, with some replay value. There is some clever gameplay, the graphics are good, the game runs smoothly, the voice acting is good.', 'everything looks good except the characters in the game are clearly voiced by ai, making the whole experience just feel cheap. Also a bulk of the playtime is just walking through long corridors for no real reason.', 'Overwhelmingly Positive', 95.09, 4.65, 3.40);
INSERT INTO reviews VALUES (72834, 2794610, 151, 'This was well worth the wait from playing the demo months ago. So many characters to enjoy with 90% of the dialogue being voice by great VA''s. Its well worth the purchase and it even came out right on time for Halloween!', 'GAME KONTOL KEK TAI ANJING MATI AJA NGENTOT BADUT KONTOL MUSIK KEK TAI CERITA GA JELAS MEMEK CERITANYA KEPANJANGAN KONTOL.', 'Very Positive', 90.07, 2.27, 1.78);
INSERT INTO reviews VALUES (72842, 2794770, 222, 'Seeing a Clock Tower game on Steam is pretty surreal, what a great time to be a survival horror fan.', 'This game is great to go back to, but I am giving a negative review because there are RIDICULOUS "you unlocked a cutscene" notifications that come up during major events, cover the ENTIRE screen, and take like 10 seconds to go away. This is such an insanely bad design choice. For the first playthrough it will literally be covering your screen during some of the most intense and important moments in the game. The literal FIRST SCARE IN THE GAME triggers a 10 second FULLSCREEN notification to pop ', 'Very Positive', 89.64, 4.13, 0.45);
INSERT INTO reviews VALUES (72844, 2794830, 239, 'The United States is crumbling as I type this so I''m just gonna be a bunny tonight.', 'Disappointingly shallow and weak, especially for $25. Under the cute bunny veneer, there is very little content and what things you can do are poorly explained. It''s like Stardew Valley but with 5% of the sauce and none of the detail.', 'Overwhelmingly Positive', 95.82, 1.17, 6.23);
INSERT INTO reviews VALUES (72905, 2796180, 500, 'Playing this game will 100% give you heartattack they should all get sued I checked under my bed for the first time in 12 years after playing this game :):L):I)=:UI)IU?AS=)DUA=D)?(FDUSF?(FSDFDSFS', 'A shallow jump scare simulator dressed up in UE5. Initially eerie, but quickly devolves into aimless wandering with no meaningful context beyond ''find five missing people''. The cycle of jump scare, death, repeat gets old fast - what you see in the first 10 - 15 minutes is all the ''game'' really offers. \n\n', 'Mostly Positive', 73.60, 0.43, 0.32);
INSERT INTO reviews VALUES (72954, 2797340, 101, 'Luck Be a Landlord with cute animals who make adorable sounds, surprisingly deep and satisfying considering its casual look. Thought I was buying it as a fun trinket to show my wife, but then I''m 3 hours deep going "I can''t believe that my tiger ate my eagle which ate my dormice, I am never gonna financially recover from this"', 'Not overwhelming, it had it''s moment but got boring quickly. \nMore like a game for mobile you play to pass time.', 'Very Positive', 91.09, 21.22, 7.23);
INSERT INTO reviews VALUES (73077, 2800450, 150, 'The game was incredibly enjoyable. Addictive gameplay combining construction and battles. A huge living world with its own dangers. I want to study everything in order to develop better in it. Excellent graphics, locations and models are made at a high level.', 'This game it''s really bad DO NOT BUY from the developers they are publishing games and leaving them and in early access. this is the third game in early access from them the organization is really bad. the games just seem like a cash grab the game is not worth the price i would avoid these developers and they need to stop making game and focus on the ones they already have out.', 'Mixed', 64.67, 3.02, 0.17);
INSERT INTO reviews VALUES (73102, 2800900, 159, 'I''ve only played the first two levels, and I can already see the potential here. I recently finished Thronefall and was craving something similar and I can tell this game is going to deliver a great or even better experience.\n\nHuge props to the dev team for the amazing audio design and the pixel art style it really adds a lot of charm to the game. Fantastic work overall!\n\nAlso, shutout to Olexa! I found this game through him ❤️', 'Just a puzzle game, not a Tower Defense game, at least on most levels.  Many  levels require you to play with the exact towers and exact set up the developer designed them for to survive.  \n\nCould be good, but is so constrained by the rails it is placed on that I cannot recommend it.\n\n1/5 - Go play a real TD game.', 'Overwhelmingly Positive', 97.48, 7.37, 1.83);
INSERT INTO reviews VALUES (73136, 2802110, 301, 'Who knew that a pig with a grappling hook would be this fun? SPY-der PIG is a hilarious, chaotic ride from start to finish. I grabbed it in a bundle and got way more enjoyment than I expected. The pig’s acrobatics are pure comedy gold, and I found myself laughing at how absurdly fun it is. If you’re looking for something quirky and entertaining, definitely pick it up in a bundle.‍', 'I wasn’t sure about SPY-der PIG at first. The controls felt clunky, and I kept getting stuck on the same part. But after pushing through, I realized the game actually has some charm. It’s frustrating at times, but I finally got past that difficult level, and it was so satisfying. The pig’s antics are hilarious, and I’m starting to enjoy it more than I expected.‍', 'Very Positive', 93.69, 3.27, 3.28);
INSERT INTO reviews VALUES (73187, 2803280, 182, 'Do not sleep on this side scrolling roguelike!!!  Me personally,  I put it up there with Dead Cells!! Extremely great roguelike, for real!!!!  Play it! You will see!!', 'No controller rebinds. Yep that''s the only reason.', 'Mostly Positive', 79.67, 171.38, 0.22);
INSERT INTO reviews VALUES (73245, 2805060, 383, 'ok game not as good as quake 3 I wish I was playing quake 3 my wife left and took my daughter', 'They took your money for Diabotical and promised to bring it to Steam. Instead we got this half baked something which  gameplay and features wise is miles behind og DBT.   Do not give those people your hard eraned coins - they lied to you. Unless Diabotical - which is almost a complete game is on steam, I will boycott this studio.', 'Mostly Positive', 72.58, 3.77, 7.28);
INSERT INTO reviews VALUES (73289, 2806230, 103, 'whats next simulator game ?', 'This dev loves to make their quests infuriating. Buy X number of things for someone, give me money etc.. They did this with their other game Movie Cinema Simulator. Avoid this dev if you hate infuriating quests.', 'Overwhelmingly Positive', 96.12, 19.55, 14.57);
INSERT INTO reviews VALUES (73304, 2806640, 294, 'The original The Talos Principle rebuild in Unreal Engine v5\nBecause of the Unreal Engine, the hardware requirements of this version are higher, \non older hardware with several tweaks in the game''s settings this game runs OK\nThe game''s content is the base game, The Road to Gehenna, and a new chapter In the beginning\nthe recorder puzzle is slightly changed\nThe original The Talos Principle is one of my most favorite games, and this version is a big step up from the original.', 'This game did not need a remake at all.  At least, this remake is nowhere NEAR an acceptable performance level to top the original Talos Principle.  I honestly believe the visuals were better in Talos Principle 2 running in the same Unreal Engine 5.  The framerates were certainly better, anyway.  I appreciate the quality of life changes, the developer commentary, and the new difficult puzzles, but I cannot in good faith recommend this when the original is as good as it is for the low price of 1 ', 'Very Positive', 87.76, 27.17, 0.23);
INSERT INTO reviews VALUES (73320, 2807150, 516, 'A seriously underrated game that requires just a bit more polish and rebalancing to be great.\n\nIt''s like against the storm but better imo, with combat and longer maps, so it''s not just rushing to complete objectives. For those unfamiliar, you''ll build up a base using basic resources, gradually unlock advanced materials, and eventually complete the game objectives, similar to other base-building games like tropico and perhaps anno. Combat is performed by summoning temporary monsters, with serious', 'It''s just an Anno with Cthulhu art slapped over it. Yes, raising cows and having to separate buildings to provide my villagers with milk is what instantly pop into my mind hearing "Lovecraft mythos".\n\nGame is very lost with it''s identity. It feels more like Cthulhu is you regular alien servant providing you with building materials.', 'Very Positive', 87.60, 10.23, 2.50);
INSERT INTO reviews VALUES (73465, 2810780, 206, 'got screamed at by a bald guy\nchased by another bald guy with a chainsaw\nthen some other bald guy came on me\n\nSMASH THAT LIKE BUTTON\nIF WE CAN HIT 1000 LIKES I''ll SHAVE MY FUCKING HEAD BALD TOO', 'you''re charging double the price of lethal company for an early access title with no content\nlol\nlmao even', 'Very Positive', 81.55, 5.33, 0.47);
INSERT INTO reviews VALUES (73604, 2814610, 226, 'Different to most games, story line to progress the game, but also a free roam zone to explore, earn money, etc.  Could do with a bit more explanation around how the game works and how to advance your character, but still enjoyable.  Takes a long time to get to any lewd stuff so it''s not the game for you if you just want sex and nudity.  Enjoyable, interesting, different.', 'I cannot in good conscience recommend a game that SHOULD BE in early access, but isn''t. This made for an incomplete, massive tease of a game. \n\nThat''s not to say the game isn''t playable or won''t keep you busy; between free roam, missions and a character that levels up, there''s actually a lot to do, and the premise is decent, as are the characters. \n\nBut as an AVN, it takes several hours just to get to your first animated scene, which is short and a bit janky, and by the time you''ve unlocked them', 'Very Positive', 81.86, 16.78, 7.33);
INSERT INTO reviews VALUES (73699, 2816950, 307, 'There''s a lot of good here. The art is fantastic, the world is big, the catalog of collectible creatures is unexpectedly large. Fishing. Little bit of town building. Several little crafting systems. Part time jobs for your minions. \n\nThe auto combat is going to be hit or miss for people. Some will like it, some won''t. It''s a style. Know going into this whether you''re kosher with the fighting happening mostly without your input. ... You can intervene a bit, with consumable charms that do things l', 'Main character is of ambiguous gender, can''t pick whether you''re boy or girl, naturally I can''t recommend the game as a result. At least it doesn''t have body type A and B but still, we don''t like this kind of pandering. We need a binary gender option, with binary pronouns.', 'Overwhelmingly Positive', 96.42, 7.87, 4.43);
INSERT INTO reviews VALUES (73724, 2817620, 162, 'NOTE: At the time of writing, you get softlocked on several chapters, but they''re fixing that soon!\n\nOverall, I loved the first game, Machinika Museum, and this game improves on it with leagues of QoL. You can now swap between the classic point-and-click movement of the previous game, or a new free movement system that allows you to walk around the room. There are several collectible notes, and there''s also a new Hints function if you need help during puzzles. I love this game from what little I', 'Game hardlocks on chapter 3, some graphic glitch removes the thing you gotta do so you can progress at all', 'Mostly Positive', 72.84, 6.38, 0.72);
INSERT INTO reviews VALUES (73744, 2818150, 110, 'I bought this game specifically because of all the whiny snowflakes giving it bad reviews because of the pronouns feature. OMG this game added inclusive pronouns and allows people to be called what they want QQ. Get a grip folks. Same people who whine about others being snowflakes are the biggest snowflakes of all.\n\nAs for the game, haven''t really played it yet. Probably won''t get to it until I''m done with Clair Obscur. I hope it''s fun, the demo seemed interesting and I like the cozy feel of thi', 'I was actually really excited for this game and personally love farming games, but I just can''t recommend this. Everything about this game just feels unfinished and like it''s just trying to be the trendy farming game of the month.\n\nThe farming, fishing and mining feel unsatisfying, the in game economy just feels off since everything cost very little and you get so much money at the start as well as fishing and foraging just not giving much money so it''s just not worth doing. There''s not much to ', 'Very Positive', 89.09, 0.10, 2.33);
INSERT INTO reviews VALUES (73747, 2818260, 576, 'Its a good game but $20 for a free game on console cmon now', 'paid money for a free to play game... just for the extra stuff... \r\nand when the release hit... they took it all away..  after all the  waiting and issues, they just take it away.\r\nnothing for my money but a badge? im done with you vigor.. you robbed me twice.\r\nnot to mention release dont work! its broken go figure.. maybe they will give us some gold they can take back.\r\n', 'Mixed', 52.43, 6.62, 26.47);
INSERT INTO reviews VALUES (73820, 2819970, 112, 'Nag 123 pasahero ko.', 'Some other free driving simulations are better. Controls are complicated. The graphics need improvements. Does not support controllers. A very messy HUD.', 'Very Positive', 92.86, 2.27, 0.20);
INSERT INTO reviews VALUES (73860, 2820800, 117, 'this game is schizophrenia but instead of normal schizophrenia its on a bus', 'mid game', 'Very Positive', 88.89, 0.95, 1.72);
INSERT INTO reviews VALUES (73861, 2820820, 1496, 'If you are a busy professional juggling time between work, family, and social life, and yet still trying to make time for games to preserve your identity as a gamer. \r\n\r\nIf you need games to be interesting enough that should you choose to sit for a 2 hour session, you can, but still be reassured in knowing that it is short enough, in case you need to walk away after just 20 minutes. \r\n\r\nIf you need games that are simple enough to pick up quickly, and easy enough on your attention and focus that ', 'I really tried to like this game but other games in the genre just do it better. Jotunslayer takes everything that makes Roguelike and Bullet Hell games fun and waters it down. No one is really talking about it, but a huge issue i see with this game is - algorithmic manipulation of the level up rewards choices. You simply cannot do this in the Bullet Hell genre, I understand trying to control the pacing of the game so players don''t trivialize the difficulty by getting lucky but that''s simply par', 'Very Positive', 86.10, 35.92, 5.07);
INSERT INTO reviews VALUES (73902, 2821800, 413, 'Little fun game with one MAJOR drawback - it''s EXTREMELY time-consuming. \r\n\r\nBased on my experience, 150-200m run will take approximately 1~1.5 hours. If you want to go deeper and fulfill various qualifications - prepare to spend up to 3 hours per run. What''s important - you CANNOT save mid-game. That''s the biggest problem I can see with this game so far.', 'The AI really need to incorporate some level of self-preservation in there. 60 hours in, and I''m still watching these idiot workers fly past a flame tile, not around it, but along side it and keep dying. Also there needs to be a "panic" button for when that worm comes by and you want everyone to retreat, but you don''t want to end the day early. I find it difficult to think that I''ve thought of this before the developers, but alas, here we are. It''s too frustrating trying to get the last few qual', 'Very Positive', 87.17, 38.95, 63.97);
INSERT INTO reviews VALUES (73909, 2821890, 254, 'A brilliant way for ADHD brains to pass the time while watching 4hr police interrogations on YT', 'Gameplay loop never evolves and gets more and more stale after only 2 hours or so', 'Mostly Positive', 74.41, 119.75, 155.95);
INSERT INTO reviews VALUES (73925, 2822370, 132, 'game is good, but DEVS STOP USE so many AI !!! even on thumbnail !', 'Sadly, when I bought this game I thought it was going to be a factory game where you start off small and end up with a massive chocolate factory auto making it-self. But accord to the dev from my post its a hand crafted game where you own a small shop and make each of the chocolate by hand 1 by 1. I had to get a refund on this after finding this out as the name of the game is factory, not a small shop. While I gave this a good go it''s lacking for what it is, the robot doesn''t really do anything ', 'Mostly Positive', 76.52, 4.47, 2.50);
INSERT INTO reviews VALUES (73953, 2823080, 828, 'I''ve played quite a lot of Sketchy''s now and I''ve got to say, among this genre of game, I think it stands a cut above the rest. I''ve been able to have a chaotic, unpredictable and hilarious time with my friends for many hours whilst also being able to get quite focused and enjoy the game in a solo environment as well! \n\nLike other''s in the genre, the game focuses on completing quotas for "the company" by collecting "loot" from the various planets all with different environments and challenges. B', 'Sketchy''s Contract could be a fun game, and it’s well-made in terms of atmosphere and mechanics. However, it’s only for players who enjoy high-risk/high-reward gameplay and are comfortable with frequent, often punishing, trial and error.\r\n\r\nYour goal is to collect and sell loot toward a specific quota. During your explorations, expect to die randomly to monsters or traps that you had no way of anticipating, causing you to lose everything: equipment, levels, experience, and credits. As you progre', 'Very Positive', 83.82, 56.00, 7.52);
INSERT INTO reviews VALUES (73991, 2823890, 128, 'I can''t love this game enough.  GREAT Game that gives you grind, strategy, and fun!! Keeps you very busy, always something to do!\n\nUpdate! I''m Over 230 hours in and still loving this simulation game. Part of the reason I love it so much is because you don''t just stock the shelves for your customers. You have to grow it, can it, bag it, build it first. And in order to do that, you have to mine it, smelt it, grow and saw the wood, etc. You can also design and strategize the layout of your work sta', 'Very rude support. Very rude mods. If you speak against the game in any way you will be banned from discord and forums. Game is meh but this treatment is the worst I have seen. There are lots of bugs that require work around, and if you ask you get banned.', 'Very Positive', 85.16, 388.82, 20.27);
INSERT INTO reviews VALUES (74028, 2824660, 789, 'just got an rtx 4060 and this is the first game i play with it. can confirm it runs', 'To start on the positive side, the game graphically nails the PS1 / Sega Rally Dreamcast vibe. But the handling of the cars is absolutely miserable. After 2 rallies and several different cars, this is definitely the biggest weakness of the game.\n It is neither arcady nor realistic. Going to refund but will gladly rebuy if they figure out the driving mechanics.', 'Very Positive', 91.89, 13.43, 0.42);
INSERT INTO reviews VALUES (74058, 2825110, 216, 'Technotopia is a mix between citybuilders like Dorfromantik and decision-driven RPGs like Reigns. Your objective is to balance between factions while building a perfect cyberpunk city. Every in-game week you''ll get a dilemma (or city event) that can be resolved by choosing one of multiple options. Every option will have it''s pros and cons, and will increase a faction counter that''ll affect next city events.  \n\nI haven''t played Technotopia too much, but even so I can say it plays nice and relaxin', 'I just expected more from a game with such a high score on steam, but i guess a lot of people rate based on price to quality ratio, sure you can''t expect much from a 5$ game, but i will rate the game overall and not money worths value.\n\nTo put it simple the game just falls short of expectations.  There just is not enough of different mechanics, the basic game loop is simple. It is captivating and keeps you glued in its quite addictive, but that is about it. It''s like those candy crush games but ', 'Very Positive', 86.11, 1.00, 6.58);
INSERT INTO reviews VALUES (74079, 2825530, 205, 'There are two reasons to play this game: \nTall Russian Woman\nSleeping with Tall russian Woman', 'it has sooo much potential but the way it is now, meh. there''s not nearly enough passengers. the longer the game goes the easier it gets. and the extra characters like cooks or the bartenders are almost completely useless. and they dont react to certain key situations, no extra dialog or pathways to the story, nothing. I think a fix to this is a free mode after you beat the game to conduct the train in a free mode back and forth and dealing with different passengers (a lot more than the main gam', 'Very Positive', 86.34, 6.72, 40.00);
INSERT INTO reviews VALUES (74101, 2826180, 396, 'Good pomodoro app, but... I want more location like medieval tavern, forest camp, treehouse, diner etc.\nNeed more ambient sounds also. It can be trees cracks, thunderstorm, night animals (owl, frogs, train sound from away, dogs barking) need more random sounds that makes atmospere realistic.\nAnd more social and usefull features if it possible', '【DEVELOPER BANS USERS FROM USING THE CHATROOM WITHOUT NOTICE】\n\nSo there''s a global chatroom in the game. While there are no moderation rules, I have been banned from it without any notice because I used Xi Jinping as my ID.\nI am sure this is political censorship because I have been extremely polite and never attacked any people in the chatroom.\n\nSo I had a little check about the developer of the game, and it turns out, that even tho they claim they''re a global studio based in France, the custome', 'Very Positive', 93.94, 250.42, 157.40);
INSERT INTO reviews VALUES (74127, 2826800, 800, 'The puzzles are infuriatingly hard, but the story is excellent imo. So I say go for it. Just don''t get all the achievements like I did. THEY SUCK!!!!!!!!!!!', 'Having difficult puzzles is great and all, but the first couple don''t make any sense whatsoever and I ended up throwing in the towel, having to follow walkthroughs to even find out how to solve the opening puzzle because even the hints are puzzles themselves is irritating and completely breaks all immersion. I''ve been following this series since the original came out on itch.io and its pains me to say this one in particular just wasn''t fun.', 'Very Positive', 82.12, 8.60, 0.70);
INSERT INTO reviews VALUES (74144, 2827230, 1241, 'It''s Furry Battlefield. The gameplay is absolutely solid, even if you''re not a furry, but the devs know their audience.', 'I like the game itself, and enjoy playing it. However I''m not paying for a game that has 4 real players in a match at most..', 'Mostly Positive', 77.03, 76.50, 3.58);
INSERT INTO reviews VALUES (74171, 2827810, 106, 'Lots of potential, a cross between Oxygen Not Included and a tower defence game with FTL type pressure mechanic. Really looking forward to where this goes!', 'Wonky game\nbuilding and replacing buildings is a core mechanic and functions like a person with one leg riding a bike, not great.', 'Mostly Positive', 73.58, 35.98, 3.97);
INSERT INTO reviews VALUES (74208, 2828860, 13187, 'Recommended, but before you buy exercise caution;\n\nFew raids in and the game looks good, combat feels chaotic and the extraction shooter mechanics feel like they were implemented well. The game''s art style is what carries all of this however and it does an exemplary job of it, sadly there is one major downside thus far:\n\nYour base has a water level, this water level is constantly decreasing, even when the game is closed and the only way to get more water is to find it in raid or complete quests,', 'Until they change the ridiculous water system in this game, I would stay far away from it. Whether you have five days of water, or 50 days of water, your progress is being erased as soon as you log out of the game. It''s a predatory little scheme the devs have come up with, to keep players logging in. Couldn''t play the game for a number of days because I actually have a life, so I lost about a million in credits, all inventory, and upgrades to innards. Basically I have to restart the game...but I', 'Mostly Positive', 73.78, 8.20, 31.57);
INSERT INTO reviews VALUES (74264, 2830150, 337, 'Love it!\nSuper Mining Mechs is a major upgrade from Mining Mechs, bringing fresh depth and variety to the mining experience. With new biomes that each offer unique challenges and resources, the game keeps exploration exciting and rewarding. The visuals are sharper and more detailed, enhancing the game''s overall atmosphere.\n\nGameplay feels smoother with improved controls, and customization options now allow players to upgrade mechs to match their strategy. A variety of new adversaries and environ', 'Body Type 1 / 2 Nonsense.\n\nAlso the games U.I. needs a lot more polish.', 'Very Positive', 89.32, 9.68, 0.23);
INSERT INTO reviews VALUES (74293, 2831060, 179, 'Very spacious! Lots of room for my kids to play around. I haven''t seen Timmy in a few weeks now but I''m sure he''s around here somewhere.', 'People who say this game is like House of Leaves are being extremely disingenuous, it''s a small experience with a lot of busy work that doesn''t actually scare you at any point despite the MiNdBeNdInG twists of terrain. It''s a typical low-energy stress game that threatens you with a scary time but never actually follows through with it, and as punishment if you want to 100% it you have to play it again afterwards. Two more times. Buy at your peril. If you want to support small horror devs at the ', 'Mostly Positive', 75.98, 1.70, 3.10);
INSERT INTO reviews VALUES (74338, 2832400, 202, 'A wonderful game with beautiful characters, great animation. We played with the whole family, everyone really liked it', 'Season 1 was mediocre but made up for it with some level of scene variety; but this Season 2 is borderline false advertising. The game store image implies a harem pregnancy arc or similar. This is a lie. Arya becomes pregnant off-screen between seasons; but for all the others - you will pull out every single time; laughably, predictably so. Some king... Especially given the dire lack of men to replenish the tribe...\r\n\r\nThe one good aspect of Season 1 (the renders) have gotten notably worse. Some', 'Very Positive', 90.10, 7.60, 1.50);
INSERT INTO reviews VALUES (74423, 2834600, 280, 'This gets the Rusty''s Retirement seal of approval 👍\n\nI absolutely love that I can build a massive apartment tower complex on the side of my monitor. It''s a great addition to the ''Bottom-Of-Your-Screen'' genre!', 'It''s an interesting game in that it''s less of a sim and more of a puzzle. Here is your randomly generated character that you cannot customize. You can change its name but not its skin color, clothes, or voice pitch. Get a second character! But that specific character has a specific storyline where they don''t want a career. In horizontal mode, you can have a two-story house... and everyone can share the bathroom but not the kitchen stove. But they can share the microwave. \n\nMultiple characters ma', 'Very Positive', 92.50, 4.93, 8.82);
INSERT INTO reviews VALUES (74448, 2835110, 125, 'I love fishing minigames in other games and i would always go ''man what if an entire game was like this?'' then call myself stupid because how would that even work? Well this is how.', 'At the moment (01/08/2025), the english translation quality is very poor and makes it difficult to decipher what the game wants you to do. The english dialogue also often goes off of the text box or UI elements that have the English text.', 'Very Positive', 88.00, 15.42, 2.33);
INSERT INTO reviews VALUES (74470, 2835570, 27509, 'good multiplayer game but can you do split screens so can we can play local with our friends', 'Bought the game on itch.io as an early supporter. Had to buy it again on steam so I could play it with a friend, because itchio version isn''t being updated and you don''t get a steam key. Rather scummy behaviour', 'Overwhelmingly Positive', 96.71, 8.07, 1.40);
INSERT INTO reviews VALUES (74533, 2836860, 212, 'The game starts very strong. easy to get started and engaging core loop. presentation is also top notch.\ni think the game fell short in the second half. there''s very little agency. you largely repeat the same tasks with little variation. side mission has no impact on the main gameplay.', 'The game is too easy, not once in my playthrough did I have any challenges or was even near to lose my investigators. That does not make it a bad game, as it has nice writing and setting. But it is also short (little under 7 hours) and has no replayability to speak of. As it is, it is too pricey. Hopefully the developers will build something more challenging on this setting in the future.', 'Very Positive', 91.04, 6.32, 6.57);
INSERT INTO reviews VALUES (74669, 2840190, 1028, 'this game has it all. yuri, MILFs, speed dating, cobigail, taking down a fascist regime, dogs, ritual sacrifice, volleyball, yaoi, mukbangs, and the bizzyboys. just to name a few\nvery awesome game i give it 10/10 king please give me a chance', 'honestly the game is just. ok to me. nice art, interesting themes, good music. just didnt really vibe with it for some reason. if there was a mixed review option i would choose that but... eh i wasnt vibing with it for most of the game\n\ngotta say though. making the gods 3d while having the humans be 2d is a great stylistic choice.\n\nedit: also im sorry but the bizzy boys or whatever they were called pissed me off.', 'Overwhelmingly Positive', 99.51, 11.87, 5.57);
INSERT INTO reviews VALUES (74670, 2840210, 180, 'In the Ghost Hunting genre of games that have popped up the last few years, you’re probably familiar with ones like Conrad Steven’s Paranormal P.I., Phasmophobia, and a couple others. I’m happy to say that Bureau of Contacts does stand out from similar titles thanks to some differences in how determining ghost type works as well as “quests” you can complete to further your investigation and lead into a new mechanic. Unlike others in the genre, once you figure out what the ghost is, you can find ', 'Lol why does this game have positive reviews? It''s just another clone of the ghost hunting game. And its selling point is the AI  that doesn''t even work. You can''t talk to the ghost about anything. It literally has the same "code phrases" as phasmaphobia. So why buy it? Refunded', 'Very Positive', 82.22, 24.45, 0.70);
INSERT INTO reviews VALUES (74673, 2840250, 149, 'I have only played the first two levels but the game has a great atmosphere, great gameplay, and it''s scary! I got jumped a couple of times and it definitely spooked me. I played on the Steam Deck and it felt pretty good. I''d say the experience on PC would be better due to being able to aim and react quicker but it definitely runs well and works on the Deck.\n\nThere are a couple of puzzles that made me rattle my brain and had me slightly confused but I got the gist. There''s definitely hints place', 'Repetitive, overly simple, generic, unexciting gameplay. Find door code, open door, find keycard in there, open other door, read blood stain passcode on wall, open 3rd door, and so and, and so forth. \n\nSorry to be negative to a small developer but I want to keep these overall ratings more honest as I feel like certain small, niche releases get skewed by a specific crowd’s overexcitement- kind of like how you wouldn’t expect a neutral unbiased opinion of someone’s work by asking their mom.', 'Very Positive', 85.91, 3.42, 0.97);
INSERT INTO reviews VALUES (74685, 2840480, 260, 'Let''s go gambling!\n\n❌❌ aw dangit\n❌❌ aw dangit\n❌❌ aw dangit\n❌❌ aw dangit\n❌❌ aw dangit', 'I wish there was arabic\nSo my brother can read it\nHe lose on easy mode', 'Very Positive', 94.23, 0.22, 0.83);
INSERT INTO reviews VALUES (74697, 2840770, 2287, 'It''s been 12 years since Far Cry 3 came out and they''re still making the same game.\nIt''s the most ubisoftiest 7/10 game of all time.', 'Gameplay is Decent, Graphics are fantastic, Writing and Story are terrible. Whoever greenlit the script for this should be fired along with the writers.', 'Mixed', 69.48, 0.47, 39.10);
INSERT INTO reviews VALUES (74752, 2842040, 3191, 'I’ve played Star Wars Outlaws on release on Ubisoft connect and now having gone through the opening section again on Steam I can already tell it’s a completely different game.\n\nI even like the stealth gameplay now. It feels less punishing while still being realistic. They even changed animations. For example performing a takedown with the help of your companion Nix felt a little clunky at first having to wait for an animation to finish and then press the takedown button in a short window or else', 'Ubisoft should be outlawed from making video games. I can''t even feel bad for them anymore, because they have willingly thrown away every opportunity to make good games by trashing every IP they''ve gotten their hands on. They messed up Pirates, Star Wars, and Samurai all in a span of a year. That’s a pretty impressive achievement by anyone’s standards. They would rather produce boring, corporate slop with the same cookie-cutter gameplay year after year rather than make something unique and inter', 'Mostly Positive', 73.96, 85.43, 0.25);
INSERT INTO reviews VALUES (74790, 2842860, 140, 'One of the most absurd stories I ever saw even in pr0n games, the author must either have a vivid imagination, be on drugs, or, likely, both.\nSome of the wildest renders you will ever see.', 'I finished the entire game in 10 minutes and refunded it, since I couldn''t believe it ended that abruptly. Visually it is not terrible, but there is nothing beyond a few adult scenes in terms of, well anything such as a story. \n\nBe very suspicious of all the positive reviews with 3, 4, 7 or 8 hours of gametime, in my opinion those can''t be legit, this is not a game to replay 10+ times, and even the slowest of readers will not need hours to get through this....and it is a truly linear game, there', 'Very Positive', 82.86, 5.58, 0.23);
INSERT INTO reviews VALUES (74808, 2843190, 225, 'Played the demo during next fest and thought it was really cute! Have been waiting for it to pop up in my emails that it was released, so was quite happy when that happened today. If you like Unpacking and those sorts of cute organising games, definitely give this a go as it scratches that itch. The art style is nice and being able to customise your little campers is an extra touch as well! Defo a chill evening game to just sit back and relax to.', '- Controller support doesn''t allow for menu/UI navigation with D-Pad. It''s not comfortable to navigate UI with thumb sticks working as a mouse and there''s a lot of tiny menu items to mess with.\n\n- No controller button on screen at all when customizing van, like X and B to rotate item. Didn''t bother trying to guess the rest of the controls to place or manipulate items.\n\n- Tutorial is bugged? Got to the part where the game teaches me camera movement around my van, then shines my backpack icon gold', 'Overwhelmingly Positive', 96.00, 4.28, 0.25);
INSERT INTO reviews VALUES (74825, 2843640, 290, 'The game tries to be gnorp, but doesn''t quite get there.\n\nQuite good and worth the price, but demands too much attention from an idle game.', 'I wish each meta-progression point felt more impactful. There have been multiple times I''ve prestiged, but since the upgrades I could get only affect super specific things, the next run feels exactly the same.', 'Very Positive', 81.72, 7.20, 10.73);
INSERT INTO reviews VALUES (74859, 2844500, 114, 'I was notified that the game released.\nHopped on my phone to buy it and downloaded it on my computer.\n\nNever in my life I have bought a game so fast after it released.\n\nlets go more protogen honkers', 'This visual novel is not even worth the price for its art. The art time should''ve just stayed invested in my furry protogen series. Not that that''s an any better VN, but at least Juno and a human shlong looks way more appealing. Than a purple toy or Xena.', 'Overwhelmingly Positive', 98.25, 25.32, 3.35);
INSERT INTO reviews VALUES (74873, 2844850, 220, 'Sakaguchi''s stories were my childhood, and Fantasian really brings home that cozy sense of gaming often missing in modern releases. I played the mobile version and am eager to jump back into this on a big screen with 4k resolution. The additional Uematsu soundtrack options are all great. Highly recommended for anyone with nostalgia for older Final Fantasy titles, Blue Dragon, Lost Odyssey, or just really cool folk who love retro RPGs.', 'This game is an example of what happens when story is just a series of events and the characters have no actual character. There''s no meat for me to sink my teeth into, it''s just shallow interactions and every potential mystery gets explained almost immediately with blatant signposting or exposition. Not to mention fights are long slogs, even with the Dimengeon feature, and boss fights especially so. I''m a little over halfway through the game and I don''t feel any stronger in a fight than I did 2', 'Very Positive', 81.82, 62.28, 24.53);
INSERT INTO reviews VALUES (74884, 2845090, 104, 'its new so theres gonna be bugs.  i luv the concept and i believe the game will get better. i may be a tad biased tho being a Texan, makes me wanna restore the land which is the main goal.\nNeeds keybinding and more polish.', 'Stay Away This Game\n\nI have 6hrs into the game and honestly I was judging it as if it was a Work In Progress game. Well I just had it pointed out this game is meant to be complete. I am not going to write a long review here not needed. Scroll down the right side of this page and click on DISCUSSIONS. There is the forum you find all the short comings of the game that Devs call complete. Perhaps they will fix a bug or 2 but based on things said in the forum this does not sound like a Completed gam', 'Mixed', 62.50, 4.22, 5.68);
INSERT INTO reviews VALUES (74917, 2845630, 409, 'I wasn''t even fully sure if I should keep Codename: Ocean Keeper in my list of bullet heaven games. After all, it''s certainly a hybrid of sorts. The player gets to control a fairly slow mech in a 3D top-down view underwater environment, looking for caves to explore to mine minerals. When entering a mine, the player controls a diver in a peaceful 2D sidescroller mode, where they get a limited time to extract said minerals - which then can be spent on upgrades for either the diver''s speed, mining ', 'This single player game REQUIRES an active internet connection. If you block the games .exe in your firewall it will crash on launch. If you allow it through your firewall it will launch and play fine. While the game is running if you block the .exe from the internet it will crash.\n\nREFUNDED.', 'Very Positive', 86.31, 3.32, 0.17);
INSERT INTO reviews VALUES (74926, 2845840, 101, 'This happened to my buddy Eric during the pandemic.', 'barbotine is a weird little horror game that unfortunately has very little going for it. I will say it has a fantastic art style and is slightly creepy, but ultimately has very little substance. This felt like it should be a free demo to a much longer and more involved game. \n\nIt takes less than 20 minutes to complete, which I by no means have a problem with nowadays, however there is practically nothing to this game. Each of the 7 "days" generally consist of walking around and interacting with ', 'Very Positive', 93.07, 0.42, 0.28);
INSERT INTO reviews VALUES (74935, 2846060, 183, 'I thought it was pretty fun but my friends dont want to play it with me', 'I''m just scratching my head wondering... Why would anyone play this over Lethal? It''s not bad or the worst lethal clone I''ve played, but it''s mostly copying the exact homework of another great indie game. Lethal Company + Minecraft. The Level design is also mid, every map is about the same. Also typo in "sever browser" was this rushed for a quick buck? The monster designs are atleast cool, I''ll give you credit for that. Honestly I wish I could give this game a middle review instead of positive o', 'Very Positive', 86.89, 0.80, 5.25);
INSERT INTO reviews VALUES (74945, 2846290, 340, 'I bought this game thinking, "Hey, how bad can it be, right?". I mean, I literally have a GUN. I''m sure it wouldn''t be THAT scary. So I ended up finishing the game within 1 hour. 1 hour which I suffered immense psychological stress. The gun does not make you feel any safer. The atmosphere of the game was very eerie and I was always on edge, using real life military tactics to clear rooms, but to no one''s surprise it helped very little. The game isn''t very puzzling and the way forward is always p', 'Muck.', 'Very Positive', 88.82, 1.00, 0.85);
INSERT INTO reviews VALUES (75083, 2849080, 1453, 'Fun game-play but not a lot of content.\r\n100% completed the game and all achievements in 22 hours and by no means was I speedrunning it, for £15 it''s a little disappointing.\r\nFor comparison I have 110 hours in the original KR, 58 hours in KR Frontiers, 46 in KR Origins, and 40 in KR Vengeance.\r\nStill enjoyed it just hope they add a little more content - and not in the form of a paid dlc.', 'Ironhide seems to be losing sight of what made the Kingdom Rush series good in the first place. Before, it was about tower and hero placement, timing when and where to use your reinforcements and other powers, and carefully considering which towers to upgrade during a level. Now, the devs have overused enemies that disable towers and bosses that outright destroy them to make money the primary enemy of the player during a level. The final boss of the most recent DLC is basically a moving version ', 'Very Positive', 83.28, 24.28, 52.48);
INSERT INTO reviews VALUES (75101, 2849680, 677, 'A fantastic modern take on a roguelike Missile Command, with wonderfully emulated vector graphics.  The team seems to have a very clear vision of what they want to achieve, and the game is fun, challenging, and awesome.  Can''t wait for more content and 1.0, hopefully we can get it to 10/10!\r\n\r\n9/10', 'Unfortunately there is just not enough game here. Within practically one hour I easily feel like I''ve seen everything this game has to offer. These types of games live and die by the ability to provide different builds and upgrade paths to experiment and play with, and this game just doesn''t have even close to the quantity required to make this a highly re-playable experience. The only real difference run to run is what order you get the few upgrades they do have handed to you. \n\nI know it''s new', 'Overwhelmingly Positive', 95.72, 19.02, 1.47);
INSERT INTO reviews VALUES (75116, 2849960, 112, 'somehow it feels like... I had a strong sake', 'The Revues are not subbed. The OP isn''t subbed. As much as I''m enjoying this, I cannot recommend it in any capacity considering how central the songs are to the franchise as a whole.', 'Overwhelmingly Positive', 95.54, 50.58, 5.88);
INSERT INTO reviews VALUES (75186, 2851150, 316, 'Get this game because it was your childhood! and shout out to all the people who use to play the demo version for hours.', 'Tomba (Tombi to us in PAL territories) is a good game. So good I''m surprised it''s taken this long to get a rerelease on modern platforms. While this rerelease is competent, it doesn''t offer any real advantage over the PS1 version. The FMVs haven''t been touched, they''re grainy and artifacted just like on the PS1. The in-game graphics are all 4:3, and the scaling is not the best. There''s no widescreen support here unless you count borders or stretching, and you know we don''t. The in-game menus did', 'Very Positive', 89.24, 1.87, 0.37);
INSERT INTO reviews VALUES (75209, 2851700, 113, 'Miss classic round based Call of Duty zombies from the World at War and Black Ops 1 days?\nThen this game is for you!\n\nSolid shooting, quick movement, decent selection of weapons, juicy sound effects, Easter eggs to discover, and there''s multiplayer for you and up to 3 friends to play together. At the time of writing, there''s only one map but the next map is being worked on now that multiplayer has been added.\n\nOnly con is that the developer is British.', 'Incompatible with Steam Deck (and Linux?)\nDEVS PLZ FIX', 'Overwhelmingly Positive', 99.12, 9.08, 1.23);
INSERT INTO reviews VALUES (75241, 2852770, 220, 'Number 1 Producktivity tool on Steam', 'This isn''t a bad game, don''t get me wrong, but it isn''t what I expected. When you enter the game, you go to the menu, select the ducks you want to see, and then they appear on your desktop. The problem is, when you interact with anything on your desktop (opening new tabs, switching between screens, etc.) the ducks that were previously on your screen are now gone. You CAN click the icon in the hotbar of your screen to make them reappear, but I bought this so I could have the ducks in the backgrou', 'Overwhelmingly Positive', 97.27, 1042.35, 0.23);
INSERT INTO reviews VALUES (75248, 2852930, 110, 'If you enjoy indie horror, a twisting story, and an uneasy atmosphere, Ethel is where you should be. Read everything, look at everything, and pay attention to the details. \n\nAlthough you may explore, learn, and solve puzzles, you are also made to feel like you are always being watched. The creature design is great, and the story is full of twists that I look forward to exploring further in the sequel, Claire. \n\nSupport Indie Devs, Support Indie Horror, Solo Dev created this indie horror gem that', 'This game describes itself as requiring "sharp OBSERVATIONAL and MEMORY skills" which actually just means that you''ll have to remember where you saw something that you couldn''t pick up, but you will need it later on. The observational skills you will need refer to the fact that there will be things located in the most obscure and random places for no reason and there is no guidance as to why they are there and they describe it as "no hand holding." My biggest gripe with this game above all is th', 'Very Positive', 94.55, 1.32, 1.22);
INSERT INTO reviews VALUES (75251, 2852980, 282, 'It''s always so nice when developers listen to feedback from playtest and Steam Next Fest! Great game for a very small price!!!', 'Way too easy, and the fact that your deck and stats reset at the start of each chapter removes any sense of progression. Imagine if at the beginning of a new act in Slay the Spire, the game took away all your relics and swapped out the deck you''d been crafting for a slightly better base deck. It''s a baffling decision that kneecaps any potential this game had because it can''t effectively scale in complexity, making it an inherently shallow experience.', 'Mostly Positive', 78.37, 9.83, 1.85);
INSERT INTO reviews VALUES (75255, 2853130, 158, 'Despite its name, it''s not an idle game, it''s an incremental game. You won''t find yourself idling much. I mean, you can idle a bit, but it''s absolutely not necessary. The progress is fast enough without idling.\nThe graphics are excellent and the gameplay is fun.\nIt has two modes, each take about six hours to beat.', 'I got the demo when it first released, and was really interested in buying the full game because it seemed super neat and chill.\n\nUltimately though, when I finished the game, I came away with a sense of-- that''s it?\n\nThere''s really not a whole lot to the game, honestly, and it''s over pretty quick-- and given this is a rare idle game that is paid, that is... not a good thing.\n\nI honestly don''t really feel like I got my money''s worth. Maybe on a heavy sale.', 'Very Positive', 89.87, 12.17, 5.35);
INSERT INTO reviews VALUES (75275, 2853590, 809, 'Great FTL like game set in absolutely not Warhammer 40k universe.', 'It''s an FTL mod that strips down the event system to the point of not being worth reading after a run, and which fails to credit FTL while lifting every single ship upgrade progression directly from that game. The 20$ price tag is an insult.', 'Very Positive', 91.47, 21.07, 5.37);
INSERT INTO reviews VALUES (75280, 2853730, 920, 'There is no reality where this game is worth $60. However... It''s pretty fun for a $24 game. If you don''t get it for the introductory price at 60% off, I''m sure it will drop FAST.', 'Ah yes, the "quadruple A" game. Imagine having the blueprints for a successful pirate game in Assassin''s Creed Black Flag, and then messing up this bad... The only real pirates were the Devs taking peoples money.', 'Mixed', 66.85, 197.10, 0.08);
INSERT INTO reviews VALUES (75287, 2853840, 110, 'So I’m sitting there, barbeque sauce on my titties', 'not worth the price. its very linar and the story is bland. and for the "Breeding" part, its dumb. no pay out on them being pregnant.', 'Very Positive', 80.00, 1.17, 0.95);
INSERT INTO reviews VALUES (75328, 2854740, 1386, 'I saw that on the store and thought: \n"Did some horny developer make a Hades clone, but with a nun fetish?" \nthen I played it and it turns out: \nYes, some horny developer DID make a Hades clone, but with a nun fetish! \n\n10/10 no notes.', 'no nun sex', 'Very Positive', 92.64, 4.48, 7.18);
INSERT INTO reviews VALUES (75330, 2854780, 175, 'A really cute and short platformer that is heavily inspired by Kirby’s Adventure on the NES. You can eat your enemies, throw them at each other, ride acorns and apples, and use your sticky tongue to overcome the obstacles of terrain by pulling yourself around. The content it offers for a dollar is incredibly well actually. I definitely wasn’t expecting all 7 levels filled with collectibles. Some of them are very well hidden as well. You also get a new hat at the end of the game that could serve ', 'I love frogs :) \nThe jumps are too hard :( \nI feel sad seeing the frog die :(', 'Overwhelmingly Positive', 97.14, 2.13, 0.55);
INSERT INTO reviews VALUES (75343, 2855480, 110, 'The one who parasitizes,\nthe one who is parasitized,\nand the one who is devoured.', 'i tried to '' enjoy '' it with all my will, but the game bugging at the same levels almost made me quit. def g graphics nd atmosphere but beyond that there was nothing more to it', 'Mostly Positive', 76.36, 0.93, 0.50);
INSERT INTO reviews VALUES (75381, 2856450, 322, 'Genuinely a lot more content than I was expecting from an early access title.  There is massive potential here with the art and the music and the combat!\n\nI think I can safely say this game is going to eat up a lot of my free time...\n\nPlus, Shork, I mean come on, a cat shark hybrid. I love him.\n\nEdit Update: The music is still stuck in my head. Weeks later. Still singing that damn theme.', '2 issues:\n1. The game is very unbalanced. Most fights are so easy you steamroll through the enemies. Then you encounter an enemy that is wildly overtuned that is impossible to beat.\n2. The content takes too long to unlock. I just want to play the roguelike mode with some new characters. It takes 30 min going through unskippable dialogue in the campaign to unlock 1 new character.\nThis game has a lot of potential if some issues can be fixed', 'Very Positive', 88.82, 6.35, 9.33);
INSERT INTO reviews VALUES (75443, 2858150, 128, 'Air Chips: Los Tortillas is the thrilling story of Totopo, the last intact chip in his tribe''s bag. He has to get to the guac because I got stoned as shit right before I wrote this', 'Achievements (and other predatory nonsense) is planned on being added. Damn shame.\n\n"I don''t plan to add any kind of predatory nonsense."\n*Adds achievements. AKA predatory nonsense.*\nMfw.\n\nBy a portion of the audience, do you mean the two virtual crack addicts huddled in the corner of their room rocking back and forth because they don''t know how to play video games when not being directly piloted by virtual crack cocaine on sticks?', 'Very Positive', 93.75, 32.82, 83.25);
INSERT INTO reviews VALUES (75452, 2858370, 108, 'Good start, Needs a major update to be worth the price. \n\n***ADD PUNCHING***\n***ADD REALISTIC WEAPON SOUNDS*** (Sounds like airsoft, no kick to it) <---- \n', 'The game is very cool, but I dont feel like the price tag fits the game at the moment, the physics are great, the weapons are ok and the vehicles are amazing but it just feels so lonely, like i get assigned to knock down this building but, why? its boring in my opinion im just given dynamite and boom its down just like that, 20 minutes of messing around and i was already bored of what the game has. I think that if you want a fun sandbox where you can blow stuff up and be satisfied get this, but ', 'Very Positive', 89.81, 1.42, 0.33);
INSERT INTO reviews VALUES (75485, 2859200, 251, 'Alex Hill is clearly targeted at Nancy Drew fans who desperately want to play a new Nancy Drew game that is not completely horrendous.  Graphics quality leaves something to be desired, there are random bugs, and the navigation is so awkward, but these issues are quintessentially Nancy Drew.  This game, like the Nancy Drew games, is not trying to be cutting edge or perfect - it is a cozy, story-driven, mystery point and click that takes you back to a simpler PC gaming time. I look forward to this', 'It''s games like these where I really wish Steam had a better rating system than just a thumbs up/down, because I feel intensely mixed.  The titular Alex Hill is full of charming snark, the story was a solid mystery that dealt with more mature topics well, and the many easter egg references to Nancy Drew games and other properties were a fun little delight.  The puzzles were sparse, but I enjoyed all the ones that were there. I think as a series idea, these games have a LOT of promise., and I''m e', 'Overwhelmingly Positive', 97.21, 8.93, 4.93);
INSERT INTO reviews VALUES (75545, 2860450, 232, 'YOU HAVE TO BUTCHER THE SHEEP AND YOU GET ITS GUTS I WAS NOT ANTICIPATING THIS AAAAAAAAAAAAAAAAAA ;~;\n\nIt is very cute and very wholesome but good gosh I just wanted a nice fun time with my lil sheepies not to play the unrighteous hand of god\n\n-V', 'So, I have some concerns. This game is tit for tat a copy of Stacklands. I suspected it when I saw the trailer, but the music, sounds, and graphics are all copies of Stacklands. The only difference here is that instead of cards, it''s more graphics and no stacking. The game is okay on its own, but the more I played, the more the constant hand holding and copying got under my skin. I looked at the people who created Stacklands, including the programmers and neither of this wife/husband duo worked ', 'Very Positive', 84.48, 1.52, 0.35);
INSERT INTO reviews VALUES (75573, 2861150, 163, 'My friends opend this game on my laptop in school.\n10/10 game, Dont open in school', 'I just bought me self a video player of some animations and a little devilish background of lore. This game automatically sets the text in auto, which I have trouble reading them. This game can''t even go on a full screen. \n\nBut damn the quality of the video is pretty good. And the soundtrack is relaxing.\nMaybe you can get this on sale? Other than that, well, maybe not. So, 5/10 nah', 'Overwhelmingly Positive', 98.16, 0.33, 0.90);
INSERT INTO reviews VALUES (75656, 2863160, 205, 'This game honestly suffers from advertising itself so much as a porn game. While it does have sex scenes and they are really well done, the characters and writing are the real star of the game. The characters all feel real and complex and are all very likeable. They have their faults, and they lean on each other for some really impactful moments, paired with a pretty really well selected music to invoke emotions far deeper than just horny. There''s also a good amount of humor that doesn''t feel li', 'Maybe that''s my high expectations affecting negative review but...\r\n\r\nBoring. Level of writing is declining beginning from ending of Season 1. A lot of needless dialogues with no humour, drama (except showing "we are all friendly friends here") or action. If you can''t add dynamics in dialogs - simply cut them off, be a good editor to yourself...\r\n\r\nGraphics is still flawless, though, much better music, no logical issues or env bugs - good work on beta testing. I''d recommend Season 2 for those wh', 'Very Positive', 94.15, 8.48, 17.97);
INSERT INTO reviews VALUES (75670, 2863640, 656, 'At first it''s a horror game, but it slowly grows into a cozy little game with lovely melancholy, and only sections of horror.\r\n\r\nBy the end of the game it feels like home.', 'For kids it''s too scary, for adults it tremendously lacks in gameplay and level design. Visuals are unique but visuals alone can''t let an art project become a game. I''ve completed the first chapter and visited the housy and must say it didn''t present even a single engaging gameplay idea at this point. The housy could be a good intrigue since it does have shelves for collectibles but it turns out all the environment doesn''t actually change depending on what you''ve found, it''s static. You can even', 'Overwhelmingly Positive', 96.95, 20.02, 0.52);
INSERT INTO reviews VALUES (75709, 2864560, 547, 'Day 1 PC release is enough for me. Don''t have to suffer through the absolute performance nightmare that was rune factory 5 on switch', 'Really wish there was a "Mixed" recommendation. On the surface, this is a fine mid range game, blending casual elements of a town-builder, action RPG, farming game, and a dating sim while giving a relatively barebones experience at each. It doesn''t excel at any of them enough to really shine and while using the RF name It has stripped pretty much any complexity that existed in the original Runefactory game formula and slapped an almost "mobile game" coat of paint on whole experience.\n\nSimply put', 'Very Positive', 91.96, 24.43, 28.05);
INSERT INTO reviews VALUES (75724, 2864890, 404, 'This is a legitimately good idle game that doesn''t make me feel guilty when playing it. There is a lot of game to it, but there is also some "just sit there and look at number go up when life is really bad". It has plot. It has fun synergies to figure out. This is a good game, play it (you should also play no. 1, but do it first - I don''t think I could go back to MR1 after all the tasty QoL in MR2)', 'The game just keeps on piling on mechanics with no good way to manage them across a dozen screens. Very early in the game you''ll be juggling so much crap and every time you prestige you have to painstakingly do it all again. Theoretically you can save builds or whatever, but even if you save spells to cast the game will make you go into a different screen and click to activate each one as you learn them anew every prestige. And every prestige involves rebuilding your inventory over and over, whi', 'Very Positive', 93.07, 356.20, 40.67);
INSERT INTO reviews VALUES (75744, 2865440, 101, 'Finally can recommend after the latest patch. Old school TRPG that can get quite tough at times.', 'okay so i like front mission quite a bit and would love to see remakes of 3, alternate, four and 5 but y''all screwed this one up theres lots of bugs and it kinda felt half baked when compared to the first remake. a shame a blemish a stain a pockmark a greek tragedy a wet fart so on so forth. Please do better we''d love to see the others remade well, but please don''t halfcock them.', 'Mixed', 60.40, 43.37, 31.30);
INSERT INTO reviews VALUES (75882, 2868860, 236, 'Slightly premature review (as anyone who played the previous CS knows, hundreds of hours of gameplay are possible), but I just wanted to counter some of the inane early negative reviews I''m seeing here, and hope that other fans will do the same.\n\nAs someone who played CS:TI in early access last time and saw how it evolved, what we have here on day 1 is pretty much exactly what I''d hope to see.  Is it perfect? No, but who cares. I understand that some are skeptical of EA titles, and understandabl', 'If you loved CSTI like I did, you will be disappointed by this release. It''s click-bait in the form of a game. 17 hours in for me, and I have yet to come across anything remotely "fantasy" about this forest. I guess there''s the Sacred Oak and "magic" elements, but the "magic" is not what you would think or hope it is --  it''s just feels like "occult" elements from CSTI. There are no fairies or trolls or gnomes, goblins, etc. Instead, make way for such fantastical creatures like: deer, elk, badge', 'Very Positive', 91.95, 9.03, 17.32);
INSERT INTO reviews VALUES (75914, 2869860, 1181, 'I''ll be honest... this installment isn''t for me. Not quite the right kind of nerd for all the references, etc this time around.\n\nBut not being target audience is no excuse for a bad review! Writing style is still hilarious, characters are fun.\n\nGreat work, y''all!', 'Very, VERY, VERY cringe. Unless you really know what you''re getting into and are deep in the con/tumblr/fanfic space... don''t.\n\nThe characters are written as if they''re 14 year olds. One of the characters is canonically a discord mod. Another is an avid fanfic writer. The clown is a little interesting I guess. Still, can''t recommend.', 'Overwhelmingly Positive', 99.15, 2.80, 0.88);
INSERT INTO reviews VALUES (75940, 2870350, 177, 'Pipistrello and the Cursed Yoyo, aside from being a really fun game, is one of the most legit GBA-style games I''ve ever seen!\n\nTight controls and amazing pixel art!\n\nNot only it has an option to play on a simulated LCD screen, but the OST is a GBA masterpiece! Full of recognizable samples from that time. One of the best releases this year!', 'It''s a nicely designed game but this is not for casual players.  I''ve beaten and loved every Legend of Zelda game, and while this game has some familiar feel, it is much more difficult than any of them.  I''m sure there are lots of gamers who appreciate that but it''s not for me.', 'Overwhelmingly Positive', 97.74, 4.18, 2.68);
INSERT INTO reviews VALUES (75945, 2870420, 314, 'Brilliant. This is what I was looking for after playing the Model Builder in Last Call BBS. \nVery easy to get into, relaxing and enjoyable to play. \n', 'BUYER BEWARE: This game is dishonest about using generative AI assets. When confronted on Twitter Don Pachi blocked me after being wishy washy about using generative AI in order to create assets for the game. \n\nIf the game was transparent about its use of generative AI I would have never bought it. Generative AI is theft and the several open court cases against Midjourney and the like will be legal precedent against its undisclosed and excessive use in the near future. \n\nThis dev could have easi', 'Mostly Positive', 76.11, 2.52, 0.10);
INSERT INTO reviews VALUES (75961, 2870710, 195, 'a girl slept over and no joke showed me this game on youtube, had to come home and buy this masterpiece', 'Please remove the name pih #BRINGBACKBIGPIG', 'Overwhelmingly Positive', 95.38, 26.20, 0.67);
INSERT INTO reviews VALUES (76082, 2874130, 156, 'In the short space of 16 minutes I found out about a lot of Windows shortcuts. I have no idea what they are. But I know they exist.', 'Please do read the description, because MASHING the keys like in the trailer is NOT optional. It is literally part of the controls, and you are pretty much forced to smash as many keys as possible to  control your character. It''s not just a gimmick.\n\nIs it unique? Yes. Is it interesting? For about 3 minutes. Is it fun? Absolutely not.\nOn top of that, the stamina concept just seems horrible for one of these games, it makes me feel like I have zero control over my timing. Whereas a game like One F', 'Mostly Positive', 76.28, 0.27, 0.18);
INSERT INTO reviews VALUES (76226, 2877540, 290, 'pretty dope roguelight but im getting ripped by this one lightning warrior boss.... pretty frustrating thinking he needs a debuff (or i needa get gooder :-o    )', 'While the game is fun, it requires WAY TOO MANY resets to complete even the most basic of progress. After a while the missions to unlock different items or skills are actually straight up boring asinine wastes of time that force you to throw away 15 minutes of your time on a sh*t tier build just to HOPE you proc correctly.\n\nFor example: Burn 30 enemies in 30 seconds. There is not a singular area in the entire game that I can think of where you can even FIGHT 30 enemies in 30 seconds, let alone p', 'Very Positive', 94.83, 85.13, 16.28);
INSERT INTO reviews VALUES (76266, 2878420, 483, 'Nice, chill game - great with friends! But the music is a bit depressing. \nMy recommendation: turn down music, put on some medieval lofi in the background.', 'I bought this game because i love simulation games and intended to get my friends to buy it once they added more stuff to do in the game me and my friends love games like this and this one is fun  but unfortunately i saw  that the devs used Generative AI for promotional material and from what your AI generated content disclosure says its also in game which was not disclosed at the time of purchase.I refuse to support games that use AI art and if i could i would refund this game', 'Very Positive', 90.48, 8.83, 7.77);
INSERT INTO reviews VALUES (76289, 2878960, 1298, 'ppl complaining abt the island mode not being there as if that mode isnt just a garbage place designed to make you pay microtransactions and see company logos.', 'I do not recommend the PC version especially since the PC is considered by 2K as old gen , wtf 2k The only reason I bought this game was because of the intergender matches and the underground matchs But seriously, 2K hates PC users because there are many PCs that run much better than the PS5, including my own. We give the PC a huge upgrades and companies don''t release new generation versions for PC. pathetic', 'Mixed', 65.25, 103.98, 32.18);
INSERT INTO reviews VALUES (76290, 2878980, 10651, 'Great space heater. My room gets cold sometimes, and i dont have a heater, so i turn my PC on NBA 2k25 and gets my room to a nice 74 degrees F. Thank you for making a computer intensive, unoptimized, laggy game to keep me warm at night.', 'I''m just not buying this game anymore. Them having career mode tied to the Mypark system is just frustrating. They Increase the grind every year for the premium currency (VC) needed to increase the stats of the career player and it just isnt fun while playing basically 100+ games needed (with each career) to get them good enough to play. Even the animations are tied to stats and VC. and if you make a build only to find out it doesnt work well, then you have to start over no respecing like normal', 'Mixed', 63.74, 385.02, 75.47);
INSERT INTO reviews VALUES (76351, 2880730, 379, 'This game is so goood especially when you''re a very lonely man, I highly recommend this game because the funny catgirl makes me feel loved and wanted unlike real girls. I love her so much that I don''t want to escape and I just want to stay and talk with her forever and ever since she is my girlfriend now. 100000/10 :)', 'The game itself is okay, but the people who manage their discord are horrible.\r\nI joined their server for fun and lulz, and made a post where I speedran death in this game.\r\nThe quickest way to do so is by insulting the character. I censored all the bad words, so it will comply with the server rules, yet after a day I got banned. Apparently they didn''t care if I followed the server rules or not, they just straight up banned me for INSULTING A GAME CHARACTER. In their own words:\r\n"""\r\nYou were ba', 'Very Positive', 91.29, 7.22, 3.72);
INSERT INTO reviews VALUES (76424, 2882870, 266, 'i really hateee doll real good game like phasmophobia ...\n\n\ndon''t look doll the important thing is the locked door don''t afraid okay u go sleep', 'I absolutely loved this game when it came out, but the choices they have made since then blow my mind. I''m not sure how other people feel about this, but for someone who only has a little time to play after work, the dolls are nowhere near memorable enough to remember their names. That matters when the clues come down to them moving around and I have to google pictures of who each doll is when its been a few days since I played. The new maps introduced such obscure clues with no explanation. It ', 'Very Positive', 93.61, 3.83, 35.30);
INSERT INTO reviews VALUES (76624, 2888120, 116, 'if i only had the same speed to jack it off', 'I played with game with Butt Slapper by Amarillo for meme time with friends, and something began downloading files, messing with my discord settings, and accessing personal information. Waste of $4. Could have gotten a chicken sandwich from CFA and been more satisfied.\n\nThis comment has been edited as one of the developers finally responded with a more in depth description of what this app does and what may have caused the issue. I, personally, cannot recommend it, but it may work for you. It di', 'Very Positive', 86.21, 18.05, 0.15);
INSERT INTO reviews VALUES (76727, 2890830, 1363, 'The game is actually good, i really enjoy the game, i love the live of being streamer, W Developer. But, There is one problem, if from computer, and then we go immediately to the door, the game suddenly crash. I dont know it is only my computer or not, i hope it can fix, but once again, what very good game. 5 Starst from me and i reccomend to buy!', 'Feels like an AI slapped this together with no real effort. The gameplay is dull, interactions are robotic, and there’s almost no ambient sound, making everything feel even more lifeless. The AI-generated pictures look awful, adding to the cheap, soulless experience. Using AI instead of real creativity just makes everything worse', 'Mostly Positive', 78.80, 15.40, 0.38);
INSERT INTO reviews VALUES (76746, 2891310, 557, 'I bought the game the day before it went 50% off. The dev found out and replied with vine boom sound effect. Based.\n(P.S - There''s literally a free demo that shows you how amazing the game is. definitely worth it)', 'It''s a miss for me. Roguelikes are one of my favorite genres. I literally own hundreds of them. This one is just frustrating to me. All the weapons have insanely bad accuracy outside of "snipers", this can be fixed with upgrades and perks but, in the meantime, expect enemies to consistently glide right through your hail of bullets to hit you as you aim directly at them.\n\nAnd, when you do hit them, your weapons feel limp and pathetic. This is even shown on the store page, you see that first gif u', 'Very Positive', 93.90, 9.73, 4.63);
INSERT INTO reviews VALUES (76950, 2897240, 220, 'This is exactly the type of game that deserves to do very well on Steam.  Hard to believe this is from a sole developer, first project, over just 9 months apparently!  A very tight gameplay loop.  Well designed, actively maintained, and no Early Access vapourware BS.  Better than a lot of AAA games over the past couple of decades.\n\nStart a new fledgling airline company, plan and maintain a spiderweb or routes across the planet.  The Quarterly Goals are well thought out to provide focus and diffi', 'Games good and all.\n\nUnfortunately, the developer has no idea how to manage a community, and decided to retroactively apply rules to a discussion that was had.\n\nEdit; Dev was even mature and friendly enough to add the Jester. Hallmark of professionalism.', 'Overwhelmingly Positive', 95.91, 53.58, 3.13);
INSERT INTO reviews VALUES (76968, 2897760, 171, 'The current positions are a bit limited. I hope there will be more positions involving the calves and the inner thighs. It would be even better if the two guardians of the netherworld could have sex. In the wild, you can encounter NPCs for wild sex, which is extremely exciting. I hope there will be more positions. Currently, there are still too few costumes and too few sex toys. I suggest adding sex toys such as gag balls, nipple clamps, nose hooks, anal hooks, and vaginal clamps. Also, that yel', 'I quite like the game''s theme as well as some of the heroines. But its current version has too many unfinished things even though it is an EA version.', 'Very Positive', 92.40, 17.97, 0.67);
INSERT INTO reviews VALUES (76989, 2898270, 187, 'gambled my employees salary and lost it all', 'Hasn''t been updated since august 2024 and even that update only added one game. All the casino sims seem to get abandoned. Stay away', 'Mostly Positive', 79.68, 64.50, 0.43);
INSERT INTO reviews VALUES (77015, 2899050, 514, 'I''ll be honest, when I purchased this I didn''t realize just how early access it was. Still worth every dollar & unforgettable.\n\nHeart sank when I got to the end of what''s currently available, this game is just too exceptional. It''s so easy to get emotionally invested in literally everyone. In some games the main quest is boring and side quests are good or vice versa, literally everything in this however I just want more of.\n\nI will say though, releasing a game in early access with the ability to', 'First, I dont want to play Andrew Tate and his Harem. Just the guy face completely brakes my immersion\r\n\r\nSecond, all the girls bodies look the same (with very few exceptions) with unrealistic proportions. While i understand a lot of people like it, a developer should understand it s not the case for everybody; hence there should be more variety in the proposition than having everywhere huge boobs and huge asses, where in the end every scene look like the other\r\n\r\nIt s a pity because there is a ', 'Overwhelmingly Positive', 96.89, 30.20, 4.30);
INSERT INTO reviews VALUES (77190, 2904000, 2709, '10/10 gameplay\n7/10 overall for what it wants to be\nSelf damaging spells is annoying, co op damage is annoying, enemy variety limited, no clear explanation on what elements do what or how they combine. Having said that it shows promise and its very new so I dont expect everything to be done. \nIf u like Vampire survivors, gunfire reborn or darkest dungeon you will enjoy this.', 'First, friendly fire is a bad mechanic in a survivor like game because it makes a co-op game feel like a solo game. It encourage you to avoid your friends and to never interact. You can''t show off your build, you can''t combo.\nSecond, the balance is off. Luck is mathematically about 5x better than xp because base xp upgrade nets you one level at most while luck gets you about 5 rares per game, doubling an upgrade. Do not xp, it is awful in this game.\nThird, there is no one spell procs another spe', 'Very Positive', 91.18, 1.77, 1.87);
INSERT INTO reviews VALUES (77260, 2906370, 173, 'There''s a basic element (an overused cliche), that''s included here, and in most but not all ''Adult'' games - the external overpowering force that makes otherwise sane characters go crazy, a drug slipped into cups of coffee (Depraved Awakening), a fertility drug experiment (Prince of Suburbia), a psychotic person (Acting Lessons), or a demon (Bright Lord), who needs energy. At least the Dev didn''t use the typical harem, hypnosis, or incest themes, and they kept family internal conflict, tension, a', '3/10\r\nThis game has many problems. Your choices barely matter in a storyline that is unimportant.\r\nThe animations are very bad, and the "secret devil" button is pointless.\r\nThe sex is a 1/10. The protagonist lasts 4 pumps and is done, so the scenes are crazy short. The acts he does are intensely repetitive and the angles are weak. Not to mention it goes forever between occurrences but when it happens, it seems at a nonsensical time.\r\nAlso, the main character fluctuates wildly from wimp to aggres', 'Very Positive', 86.71, 9.23, 3.53);
INSERT INTO reviews VALUES (77355, 2908950, 101, '"Karryn''s Prison and its consequences have been glorious for the human race"\r\n-The UnaGooner', 'Having content locked behind a patch that needs to be downloaded externally is a big no go, means players like myself who use steam decks have 0 access.  The ENTIRE game should be avaliable through the steam and steam alone.', 'Very Positive', 81.19, 6.22, 2.40);
INSERT INTO reviews VALUES (77374, 2909400, 7878, 'Thank you Square Enix for the  relatively  quick port. Do consider a simultaneous launch on PC for the next one.', 'Please put FSR support in, or AT LEAST the option to completely disable TAA/TAAU for AMD GPUs. The ghosting literally is making me feel sick.\n\nOtherwise if you have an Nvidia GPU the game will be grand.\n\nEDIT: I have found that you can download DLSS enabler for AMD GPUs and it does make the blur go away I''m using it myself and don''t have 1600 viruses yet but don''t take my word that it''s safe. I''m leaving the review negative for now until Square patch in alternative anti aliasing for AMD or a mor', 'Very Positive', 81.39, 81.60, 38.97);
INSERT INTO reviews VALUES (77563, 2915460, 1231, 'An upgrade from the original game in the customization department, and i dont have to hold shift to run, so that means i can scratch my balls. 10/10', 'can''t sex the lamplighter', 'Overwhelmingly Positive', 99.03, 14.37, 3.80);
INSERT INTO reviews VALUES (77592, 2916430, 2712, 'this game is very realistic because I got locked in the freezer by my co workers which is just like the time when I was working at a mcdonalds and got locked in the freezer by my co workers', 'Game is fun and satisfying especially for an early access. But it uses AI art.\n\nI will flip this review to positive the second the AI Art is replaced', 'Very Positive', 94.58, 3.23, 29.70);
INSERT INTO reviews VALUES (77624, 2917350, 179, 'fun little game, only QOL improvement I would like is being able to check your inventory in the map screen so I can see if I have a key or not for golden chests', 'Im very very on the fence, the huge problem I have is this, during a combat, there just basically nothing to do, you just watch the animation of the wheel of the machine going until the end of the combat, there is no choice to do during a combat, literally 0, so 99% of the combat goes with the fastest speed and the auto spin.\nI have a hard time because, well, there nothing to do, just click and wait...\nSure there are the runes you could use, but that like extremely rare a runes would really make', 'Mostly Positive', 78.77, 6.78, 3.77);
INSERT INTO reviews VALUES (77661, 2918410, 118, 'this game is sick as hell. it really scratched that dungeon crawler itch. if you like anything like grimrock or shadow tower abyss or king''s field, you might like this one. frequently didnt realize how much time had gone by lol', 'Game is way too hard for how clunky the UI is. Movement is grid based, but combat is full 360, meaning you can get hit from diagonal. So while you are moving around in a grid,  you have use the mouse to aim off angle and dodge from attacks in that position as well. Since movement is only orthogonal and extremely slow, the combat is really hard to execute. Real time combat, but everything you do is extremely slow and delayed. Plus rotating and strafing reset the camera view, so you cannot even tr', 'Overwhelmingly Positive', 95.76, 7.98, 1.55);
INSERT INTO reviews VALUES (77719, 2919660, 376, 'I LOVE SPENDING MY FAMILY''S LIFE SAVINGS ON GAMBLING! I LOVVVVVEEEE BLOWING ALL OUR MONEY ON ALCOHOL!!!! I SPEND EVERY DIME IN THE CASINO AND NOT A SINGLE CENT ON MY FAMILY, I LOVEEE THIS GAME', 'honestly, was super fun at the start, but the dice mini game makes the game almost unplayable towards the end of the game, and really makes the game feel clunky. restarting the same day over and over again just to continue because you have an 85% to die/get arrested is super dumb and takes the fun out of the game', 'Very Positive', 83.51, 47.03, 9.57);
INSERT INTO reviews VALUES (77839, 2922410, 148, 'Aside from some stability issues, it is decent over all, may need to cook a little longer, but so far really enjoyable, to bad no multiplayer, not to much to complain about for 5 buckaroos. Great game if you like survivor genre. \n\n(Edit - Feb/28/25)\nAfter the last 2 patches i can say that stability issues (improved FPS) are fixed for the most part, stutters only seem to happen when stuff is kinda nutz, so no real complaints.  With directional attack on mouse and controller just added that was a ', 'It''s $5 but it isn''t good. Maybe a 5/10 if I''m being generous. Get it if you''re a huge fan of the survivors genre and played the many, many, better offerings out there.\n\nA brief summary: A tacked on building system that is wholly unforgettable, bland skills, even less creative upgrades (cooldown, range, crit, attack speed, with a major upgrade every 5 levels generally being throw more or something equally boring), and clumsy map design towards the end. As in tiny funnels and paths where many ski', 'Very Positive', 80.41, 26.58, 6.17);
INSERT INTO reviews VALUES (78234, 2933080, 2979, 'Its not exactly what I expected but its pretty fun. It will def scratch the itch until they make a sequel to Payday 2.', 'I cannot recommend the game in its current state after a recent update borked the teammate AI.\n \nCrew members that are not controlled by the player will often run off on their own and get themselves wasted. This consistently happens during the Cagnali heists which require you to defend mission objectives. Furthermore, those heists tend to glitch out and prevent the player from firing their weapons, regardless if they switch characters.\n\nAlso, during stealth heists, AI teammates unnecessarily tak', 'Mostly Positive', 75.09, 23.02, 129.57);
INSERT INTO reviews VALUES (78238, 2933130, 4687, 'This game is like 80% of the way to being great, but that 20% is plagued with bizarre design and game balance choices that make it a little frustrating. There was absolutely love for LOTR put into this game, though, which is pretty nice to see. Pick it up on a sale if you love Lord of the Rings and survive-''em-ups, and are looking for a new one to scratch the itch, but brace yourself for things to be a little rough around the edges.', 'The game is fun for a few hours, but it quickly becomes apparent that the game has clearly been rushed to release with many copy/pasted areas and enemies throughout.\n\nBalancing is all over the place: bosses are often far easier than standard enemies. Many resources that should be abundant are finite and fairly limited. \n\nWithout the Lord of the Rings licence, the game would be a 4/10 at best. Your time and money are better spent elsewhere.', 'Very Positive', 81.57, 52.38, 38.42);
INSERT INTO reviews VALUES (78258, 2933620, 7989, 'Most fun I''ve had in awhile on a call of duty. Only complaint is the coddling to the sensitive community.  Why can''t we talk to enemy team after a match or when switching sides on search and destroy. Our operators can swear but if we do we get com banned? It''s an M rated game. Quit making it so soft.', 'I can''t get a refund because my Warzone play time got added to Black Ops 6. I bought the game on November 30th for the autumn steam sale and played 1 nuke town match, I didn''t enjoy it and submitted a refund request. The next day I an email from steam support say that my request was denied because of significant playtime. That led me to feel like I got robbed because of the Warzone playtime. This is my first steam review, hope this helps someone.', 'Mixed', 42.52, 0.00, 0.00);
INSERT INTO reviews VALUES (78280, 2934190, 400, 'It only took 16 years and several terrible mobile game sequels to get us here. Worth the wait honestly.', 'i couldnt sex the ao oni', 'Mostly Positive', 79.50, 2.58, 0.37);
INSERT INTO reviews VALUES (78334, 2935700, 103, 'Listen, I went into  Cowgirls Cafe  expecting wholesome small-town charm, maybe some latte art, and a dash of yeehaw energy. What I got was a caffeine-fueled fever dream where the coffee’s hot and the cowgirls are hotter!', 'Less than three hours to get all achievements, so don''t expect much.  And while the art is great, there''s only so much of it, and it simply can''t carry the rest of the game.  The dialogue is atrocious, too, so don''t think you''ll feel immersed.\r\n\r\nThe early game is very tedious, with a few hundred well-timed clicks for each of the girls until you can progress - and the fact that the droplet has variable timing is INFURIATING.  Once you get the machine, and shortly afterwards orders and deliveries', 'Mostly Positive', 76.70, 2.37, 2.98);
INSERT INTO reviews VALUES (78479, 2939640, 132, 'Good overall vampire-like with crafting. Haven''t checked the multiplayer as i have no friends.', 'Progress ain´t shared, for a Game that´s advertising so much with coop and play with friends, that´s total BS!\nCould´ve atleast given the ressources you and your friends earned during a session, towards your own save when you leave their world.\nCan´t recommend multiplayer as for right now, unless you´re down to loose all progress whenever the host of the world decides to stop playing.\n\nAside from that, price fits for what you get, decently fun but very Basic in most regards.', 'Mostly Positive', 75.00, 1.70, 8.35);
INSERT INTO reviews VALUES (78517, 2940490, 287, 'Average Team Fortress 2 player warmup', '100% crap. \ngun animation is good, but that''s all. there''s no aim training feature.\nEven sexual game purpose, every furries are AI generated. So there is no erection, No soul.', 'Very Positive', 89.55, 0.32, 0.18);
INSERT INTO reviews VALUES (78563, 2941660, 152, 'Please for the love of god dont give up on this game. Its everything a old gamer life myself needs', 'The look of the game is gorgeous.  Everything else has problems.  If you don''t code on a regular basis, this game is not for you, as any controls you try to implement need coding.  Building is based on blocks, but your blocks never merge into a unified structure.  Each created block-based shape you add to your build remains a separate substructure.  Editing a structure becomes a nightmare.  There is no structural integrity; there is no damage of any kind.  Aerodynamics is a kludged-together mess', 'Very Positive', 88.16, 29.35, 32.28);
INSERT INTO reviews VALUES (78616, 2942780, 282, 'It''s early access and I would be lying if I didn''t think it needs some more updates. Be it, UI or QOL.\n\nHowever, the concept and gameplay is fantastic and very fun for an idle game.\n\nHope to see more updates in the future!', 'game has potential but still feel really empty, \n\nmissing the excitement of getting upgrades, there isnt much of a goal, no cool items/upgrades to farm for, only golden items which only purpose is to sell for gold, game has no offline progress as of yet too\n\nwill come back to it hopefully with better changes to come', 'Very Positive', 85.46, 234.03, 38.90);
INSERT INTO reviews VALUES (78629, 2943150, 335, 'Playing casually and sees score approaching high score.\nDecides to go into first person to lock in.\nCrashes full speed into a tree.\nGives Up.\nGreat Game 10/10', 'This wasn''t what I expected. A game that promises a laid back "zen-mode" experience with mountains littered with rocks and a trillion trees doesn''t compute. This gets especially troublesome with wonky controls while in the air as neither setting for left thumbstick axis (Z or Y ie. Lincoln Loop to 180/360/... spin) get predictable movement. Refund asked after 30 minutes of play.', 'Overwhelmingly Positive', 97.61, 16.70, 0.50);
INSERT INTO reviews VALUES (78657, 2943650, 954, 'I''d like to preface by saying I''ve got 140 hours in the beta and roughly another 40 across EA play tests so my current hours are a little deceptive. Gun play is amazing, art style is beautiful, optimization is fantastic. In a market full of saturated tactical shooters FragPunk is one of the few that are taking an overused formula and adding an original spin with the card system. The best way I could explain the game is its a tactical shooter with rogue-lite elements where every round, every game', 'It''s the same re branded formula made to only sell skin. I appreciate the effort of trying to add new feature to the already existing game format (has been for ages), but when you see that everything already has 10 skin and that there is 9 CURRENCIES, you know what the intentions behind this game are. I wont even talk about gacha lord help me. The game feels jankie, everything is so slow in an environment where you would think that it should be fast and explosive. Even the game don''t know what i', 'Very Positive', 88.05, 32.80, 13.00);
INSERT INTO reviews VALUES (78876, 2948640, 208, 'good game, also hi-lo should show the 10 highest AND the 10 lowest ranked answers at the end of the game', 'The concept is amazing, the problem is the users. The problem is "poop" is usually in the top 20 no matter the question. For example here''s a typical question you might get. "Worst places for a first date", well "murder" was the #1 answer, followed by "movie theatre". We were always dumbfounded when we saw what the top 10 were. I wish it was in a better state, because the game could of been great', 'Very Positive', 90.87, 62.48, 4.72);
INSERT INTO reviews VALUES (78882, 2948790, 163, 'Probably this is one of the strongest recommendations in the entire history of my steam reviews. This is substantially the videogame transposition of "It follows", that happens to be one of my favorite horror movies ever, so I totally could not miss it. Some time ago I tried the demo on itch.io, and I was a bit disappointed by the fact that it looked WAY too similar to the movie, I would have liked to see something more, something original. Fortunately, the full game has just that something! It ', 'cool idea, awful controls, really frustrating.', 'Very Positive', 93.87, 4.00, 1.02);
INSERT INTO reviews VALUES (78951, 2950340, 376, ' I like it. Good Night, Good Luck. \nHonestly they should make a movie series about this game, maybe even a book series\n\nI rate the game 9¾ /10', 'WARNING!!!! DO NOT BUY!!!\nI tested the Collection and the original game side by side. There is maybe a MINUTE difference definately NOT WORTH 40€.\nIts a lazy straight up copy and paste. Not even the effects look enhanced. You basically pay for a bunch of achievements without any new game experience.\nDO NOT RECCOMEND', 'Very Positive', 80.85, 69.78, 0.37);
INSERT INTO reviews VALUES (78988, 2951520, 237, 'Bleh bleh bleh, bleh bleh bleh bleh.', 'Gameplay and atmosphere are a little bit bad, some of the puns are predictable, liked the end, but not that much to have a nice experience with it.', 'Overwhelmingly Positive', 97.47, 0.98, 0.52);
INSERT INTO reviews VALUES (78991, 2951630, 2147, 'instead of abandoning Pharaoh after a rough release, the dev team took the time to make things right with fans.  you love to see it', 'I do love this game - I believe it is an excellent addition to the Total War series. HOWEVER, there is currently a game breaking memory leak bug that forces you to exit and reload the game every 4-5 in-game turns. This issue has been known by the developers since last year, and there still isn''t a patch available to fix it. I rarely leave a game review, and my intention here is to help prompt dev action to resolve this problem. \n\nI will happily update this to a positive review once the memory le', 'Very Positive', 83.19, 13.63, 105.65);
INSERT INTO reviews VALUES (78995, 2951770, 618, 'This is a 2d puzzle platformer that takes on a simple concept: the player has fall damage. The player can jump, but the jump is just high enough to take fall damage, killing the player instantly. The player must constantly find ways of jumping by landing on higher elevation or helpless civilians, making you think twice before you jump. The level design perfectly complements this gimmick to make exploration and discovery so enjoyable.\n\nIt may be a cheap and short game, but this is a hidden gem th', 'This game is a precision platformer above all else. It isn''t a puzzle-focused game, so don''t get pulled in thinking it is a puzzle platformer or adventure game with mystery as many reviews say. \n\nGreat music and adorable graphics lured me in, but this game is about luck and repetition. It became a chore pretty early and an absolute slog by the end. Really solid potential, there are so many positive things about the game and I feel conflicted about leaving a negative review. But overall, the desc', 'Overwhelmingly Positive', 97.41, 4.85, 4.35);
INSERT INTO reviews VALUES (79218, 2956820, 200, 'Metal gear solid meets magical madoka\n\njanky gameplay, 10/10 absurdity. \n\nhighly rec', 'Waste of time', 'Very Positive', 93.50, 3.43, 1.12);
INSERT INTO reviews VALUES (79255, 2957700, 117, 'I love the game so much. There are some translation errors here and there but I''m sure they will be fixed over time, as the game is still in early access.', 'for being a game that''s main appeal is about the storytelling, the poor english translation is not acceptable. as well as a lot of limitations and glitches when it comes to designing anything in the game, the mechanics are a wonderful concept, but with lackluster execution especially for its current price. it''s currently early-access, so I 100% recommend coming back to consider a purchase when it''s finally done with the proper work and correct language use.', 'Very Positive', 89.74, 6.05, 2.25);
INSERT INTO reviews VALUES (79261, 2957800, 362, 'Saw that powerpak made a video on it, dropped everything to play the game first, enjoyed everything about it and now I''m back to the video as I write this. \n\nFound the characters to also be very relatable, especially Ella and my own experiences as a transwoman \n\nThank you very much for the experience <3', 'If you''re looking for a horror game I would skip this one. If you''re looking for a game where you read a discord group chat including some cringe discord romance DMs this is the game.\n\nI didn''t hate this game but I think it takes a really good idea with how you see in the game and doesn''t do any interesting with it at all. I think the idea of viewing through what an AI is telling you that you''re looking at is quite interesting especially coupled with a certainty percentage so you might think the', 'Very Positive', 93.92, 2.07, 1.37);
INSERT INTO reviews VALUES (79385, 2960770, 177, 'The reviews that are talking down on this game are just a bunch of nerds that dont know how to have fun or they just went into the game knowing too much. The experience is way better if you havnt watched anyone play it so you dont anticipate the worst, This game is really enjoyable to play with friends and if you feel like it you can speedrun the game after you get the feel of the maps.', 'I can’t believe this—I''m actually losing my mind over this chessboard mistake! I’m playing through the "house level," everything’s fine, and then BAM—they’ve flipped the chess pieces. The king is on D1 instead of E1, and the black queen is on D8 instead of E8! How do you mess that up? It’s basic chess—everyone knows that the king starts on E1 and the queen goes on D1 for white, and the black king goes on E8 with the black queen on D8. This is literally the first thing you learn when you pick up ', 'Very Positive', 81.92, 10.65, 2.05);
INSERT INTO reviews VALUES (79413, 2961530, 1268, 'Waited for this for so long , I hope the dev is gonna make a f2f season 2 soon as this was the last episode in the series for now , great games can t lie , come on with season 2 ;)', 'When I first got into the Fears to Fathom series, I became really excited with how the games worked; playing from the perspective of a person who went through a trauma-inducing experience. The games were short and sweet, with an innovative mechanic; that being using the player''s microphone while hiding from the person who was searching for you. I believe the game peaked at the 3rd installment due to the perfect horror game length and the sick plot twist at the end. In comparison, this game feels', 'Very Positive', 85.57, 2.63, 1.85);
INSERT INTO reviews VALUES (79494, 2963880, 1950, 'It''s fun stuff.\n\nLETHAL COMPANY, CONTENT WARNING, and MURKY DIVERS are the perfect trifecta.', 'The game is not that fun I''m not going to lie, it feels like its trying to clone other games in the same genre but with worse mechanics. The ship piloting doesn''t really add to the gameplay, the late game upgrades are not that exciting or an incentive. The game is not scary whats so ever, and the movement is terrible and feels bad. The monsters don''t really have any gimmicks besides run away or stay quiet. Its interesting but I can not recommend it in its current state.', 'Very Positive', 88.10, 10.77, 1.58);
INSERT INTO reviews VALUES (79534, 2964810, 100, 'It’s strange that this dlc for assassin’s creed black flag comes out after so many years and under a different publisher, but without it the game will definitely be incomplete, in some places even better than the original\n', 'Fake Positive Reviews.  Completely bugged cant even move my character at times. positive reviews are fake you cant even make it through one mission in this game.', 'Mostly Positive', 75.00, 3.85, 1.07);
INSERT INTO reviews VALUES (79567, 2965660, 2073, 'This game was amazing I got 7 hours of gameplay for £5. - I left a catacombs after playing in a duo and watching my friend get murdered in front of my eyes. I enter again shortly after to retrieve his loot to be surprised by the sound of his voice stating "I''m coming back to you" I asked "hello?? how are you alive i just watched you die" five seconds later i hear his voice yell and i am confronted by his corpse reanimated using his real life voice in front of me as i am then killed as well. I ha', 'The core idea is fun, but it has very little content. I''ve played for an hour, figured out the base mechanics and explored a bulk of the content before it just starts looping. \n\nThere is very little here to recommend purchasing at this time. Devs are not actively updating, so I''d say wait for full release before committing.', 'Mostly Positive', 76.80, 6.87, 0.88);
INSERT INTO reviews VALUES (79623, 2966850, 142, 'Exemplifies perfectly how can someone talented take a seemingly very simple idea for a game (both in terms of gameplay and narrative principles) and then elevate them with the right execution to create something truly special.', 'Okay, this game checks off the most important box and... YES, it is very fun.  The movement feels good, the using guns to jump gimmick works, and each weapon feels great to use.  HOWEVER, the game is wayyyy too easy.  I beat it in 2.5 hours, and I got the speedrun/flawless/all kills trophies on at least 2/3 of the levels (mostly on my first try).  I flawlessed all of the bosses except the final boss on the first try as well.  I''m not even that great of a player; in comparison, it took me 5 mins ', 'Overwhelmingly Positive', 97.89, 3.08, 2.50);
INSERT INTO reviews VALUES (79644, 2967320, 225, 'story is gold! funny dialogue and fun combat. Let''s get grandpa laid haha. Took me 68 min to complete. I think it was worth the money i paid for it.', 'TLDR : Deceitful\n\nThe 3 cutscenes are funny , but the rest of the game feels unfinished.\n\n80% of the game is a half-cooked third person shooter with no music or jokes/voice-lines during gameplay.\n\nThere was just enough love and effort put into the game to have a cool Trailer on the store page.', 'Very Positive', 88.00, 2.05, 0.92);
INSERT INTO reviews VALUES (79683, 2967990, 763, 'Pros:\nI''ve played for 40 hours and tried many UK and German trains. I really like how much depth this game has, especially with all the systems like AWS, PZB, SIFA, LZB, etc. I highly recommend this game to anyone, even if they are not a train fan. For new players, I strongly suggest using all these real protection systems—AWS, SIFA, and PZB—as they completely change the game experience."\nCons:\nThe only downside might be that the DLCs are so expensive—it''s really crazy. This game doesn''t have an', 'The train simulator market needs more competition. Currently, I can''t recommend it in its current state. The DLC''s are preposterously overpriced for what you get. The map detail is often somewhat poor and the routes are often short. Many of us would like to see more metro routes, and city transit. It''s an enjoyable game at times, but it''s flooded with bugs and poor AI. A shame.', 'Very Positive', 80.34, 96.70, 57.22);
INSERT INTO reviews VALUES (79738, 2969160, 356, 'The game is fun, scary and goffy, the jumpscares are a little bit overused, but what would make the game better would be a 50 MINUTES SEX SCENE WITH PANPAN OR THE NURSES', 'I seriously cannot believe this game has a "Mostly Positive" rating—unless the reviews were bought, or maybe this is what 12-year-olds consider scary. To put it bluntly, this is one of the lamest horror games I’ve played in a long time.\n\nThe game felt like a lazy cut-and-paste job straight out of the Unreal marketplace, with zero originality or effort put into the design. After the third jump scare (which, by the way, became utterly predictable and stale), the enemies turned from mildly interest', 'Mostly Positive', 78.93, 2.17, 1.98);
INSERT INTO reviews VALUES (79746, 2969380, 206, 'Yes. \r\n\r\nIn all seriousness this is one of those games where if you''re looking at it, you already had an interest in it and this is where I can proudly confirm that yes, it''s good.\r\n\r\nYou''ll hear the words "spiritual successor to Goemon/Mystical Ninja made by Goemon/Mystical Ninja devs" here and there and yeah it''s exactly that.\r\n\r\nAnd for those that don''t know what that means, I can sum this game up as a very polished stylized action platformer that you might expect to play on the Gamecube or e', 'I played up to the first boss (about 10 levels in an hour when you aren''t going for the pointless collectibles) and this one is unfortunately a refund and I can''t recommend it even at the discounted price of $16 that I paid. The levels are flat out boring and poorly designed with large empty areas filled with enemies and some minor obstacles. They are not fun to traverse at all like you would expect from a 3D platformer. On top of that they''re incredibly easy. I guess this is a game for kids eve', 'Very Positive', 94.66, 26.03, 1.07);
INSERT INTO reviews VALUES (79832, 2972990, 283, 'a very neat and relaxing game to play on steamdeck while watching your favorite holomem. Senchou''s commentary and holomem''s voice when you throw them makes this game really funny and adorable.\n\nps. I always put Aqua in so I will always listen to her voice even after the end of August.', 'This physics in this game are unintuitive and retarded which is essential for a game such as this.', 'Overwhelmingly Positive', 98.94, 21.33, 29.75);
INSERT INTO reviews VALUES (79960, 2976400, 109, 'Some games are enjoyable to play alone with complete immersion, while others are more entertaining to watch when played by streamers or friends. Personally, I believe this game belongs to the latter category.', 'Kudos for the effort, and I admit I wasn''t in the right frame of mind at the time (a little ill, a little annoyed), but this was a very fast uninstall, sorry.', 'Mostly Positive', 71.56, 0.75, 0.82);
INSERT INTO reviews VALUES (79983, 2976900, 192, 'While the game does have some confusing aspects like the whole its 1933 but i got a van and a modern flashlight but other than that this game is pretty cool. I like how the task may change from time to time and I haven''t crashed once while playing like others have been stating. My specs are above the recommended requirements so if your below that may be why, the recommendation is there for a reason. Don''t let those reviews deter you. Overall I''d give it a 7/10 it does need some work but for a ga', 'My friend Perry told me to get this game. I''m no longer friends with Perry', 'Mostly Positive', 72.92, 12.68, 0.55);
INSERT INTO reviews VALUES (80004, 2977620, 322, 'Played through the whole questline and about half the achievements so far with my wife, we had a wonderful time with the game and are planning on finishing out the achievements tomorrow. Only bug we had was she had to relog to use the bombs, other than that the game played perfectly. A patch was pushed out on 3/30 and I believe it fixed the problems people were having with houses vanishing after relog. Overall a great and cute game, can''t wait for possible extra content to be added.\n\nStory only ', 'The game is fun and cute and quite short. There is one Achievement locked behind finding someone to play with you through multiplayer. So either a friend needs to buy the game also or you need to try and find a friendly person though the games discord to help you out with that achievement, for that reason alone i am giving it a thumbs down until that achievement is removed or reworked', 'Very Positive', 93.48, 6.10, 6.10);
INSERT INTO reviews VALUES (80035, 2978540, 118, 'I complained about a bug by posting a screenshot on my Steam profile\nThe next day there was a hotfix update and the dev himself commented on how to solve it\nI''m just a random lol player and I was impressed with the company''s care', 'A lot of players have an issue when they can''t see anything after 18.00 in the game, and developers  haven''t done anything for months!', 'Very Positive', 83.90, 13.68, 5.73);
INSERT INTO reviews VALUES (80171, 2981590, 138, 'Wait a few months before buying. Dev claims they hit some IRL issues.\n\nOK 1st game from a single dev using common assets. Dev was highly active until November. Copycat games all over the place, this one seems to have come 1st and actually has a discord. Updated at least 4x a month before november rolled around.\n\nPriced about what you''d expect.', 'abandonware .devs done a runner. hes making a second version ,,,,first one with a few patches and pull the same sc!!  again .', 'Mostly Positive', 75.36, 5.68, 3.77);
INSERT INTO reviews VALUES (80486, 2989950, 360, 'another great horror game from Chilla''s Art, you will like this one if you liked Their previous games', 'If I could refund this I would. I cannot believe there are not more reviews talking about this. For the record, I LOVE Chilla''s Art games and snatched this up. But this one is unpolished and missing the mark.\n\n1. The game glitches horribly. It goes from red to green to blue hues in a second that it is dizzying. I found playing with the tv screen to help, but only a few second temp fix. Then the black screen started. I could only go to the settings screen and just start changing settings until so', 'Very Positive', 91.11, 8.90, 4.75);
INSERT INTO reviews VALUES (80522, 2990640, 351, 'If you thought Dead space is scary, you''d be mostly correct\r\nBut try beating Dead space with just one bloody arm', 'im left handed', 'Very Positive', 87.46, 15.28, 6.58);
INSERT INTO reviews VALUES (80588, 2992500, 143, 'Awesome puzzle game. Glad I found it watching Orbital Potato video reviewing it, otherwise I would of missed it. Steam is not the easiest to find new gems. Thank you to the Dev for making this beautiful game.', 'Talking about Coin Factory is weird, because on some level, I think it may just be a game that''s not for me.  I played it for a few hours and never really understood why I should care about what was going on in it, despite the victory goal being plain to see after the first level.  I think part of the problem is that it seems to have an identity crisis, at once wanting to be a puzzly game of optimising a coin-producing engine, while simultaneously being a laid-back idler where you watch said eng', 'Very Positive', 80.42, 1.13, 4.83);
INSERT INTO reviews VALUES (80634, 2993780, 3685, 'Hi, I''m the husband. My wife has been playing Fantasy Life i: The Girl Who Steals Time for 14 hours straight and is still on Tutorial Island. No, this is not an exaggeration.\n\nShe’s taking her sweet time with everything, and honestly, I think she’s trying to 100% the tutorial before the actual game even begins.\n\nSo if you''re looking for a game with charm, choice paralysis, and the power to completely replace your spouse’s attention for the foreseeable future—this is it. 10/10, would be ignored b', 'Good game, absolutely ruined by the worst multiplayer integration of all time. \n\nWhy even bother if you disable most of the npcs, don''t let you progress your lives, and put a forced 90 minute timer before kicking you back to single player. Wow great, my friend can walk in circles on the dead empty "open world" area then has to leave after stabbing four scorpions to actually level up. Ironically you''ll never hit the 90 minute timer because you have to disconnect and reconnect to turn in your ques', 'Overwhelmingly Positive', 95.06, 250.23, 12.78);
INSERT INTO reviews VALUES (80642, 2994010, 102, 'Decent for what it is and its price, not what i expected for an x-com type though. There is no world map or base you upgrade or even tech/talent trees for the agents. You start the game and play it through continuously, each area unlocking the next area/fights in a linear experience with some fights/looting in between. If the majority of Slay the Spire games were 3D modeled i''d compare it more to that type of game. Decent for what it is though.', 'Game play is fun but :\nI upgraded my tank with extremely rare materials and gave him extra crystal slots which are permanent non refundable 1 time buffs.. and the devs kill off the character in the story without refunding anything. This must be one of the dumbest decisions I''ve ever seen.\nConstant backtracking and no map to see where you''ve been or where you should go.\nThe path is blocked by 2 boxes, hip high, in your way... they are military guys and cannot pass 2 boxes. \n\nIt could be good, but', 'Mixed', 69.61, 17.58, 12.95);
INSERT INTO reviews VALUES (80713, 2995920, 40690, 'You see EA, when you actually let talented people with good ideas do what they want, you get games like this. This is actually incredible, we need more games like this one.', 'I tried to play "It Takes Two" with my daughter, and after nearly 30 minutes of struggling with Epic''s setup process, we were finally able to start the game. We had to create two new Epic accounts, link them to our Steam accounts, and go through about a dozen verification emails and codes. By the time we got in, I was so frustrated that I wanted to delete the game before even starting.\n\nThe user experience just to access the game was awful. There''s no way I’d recommend this game to anyone while ', 'Overwhelmingly Positive', 95.96, 14.08, 15.02);
INSERT INTO reviews VALUES (80719, 2996040, 1134, 'Played this on switch and loved it, had to pick it up for PC to play with my PC buds. Its a simple to pick up Rougelike but has a really fun skill ceiling. I would say if you are looking for the complexity of Hades or Dead Cells you are not going to get it, but if you want a fun arcade style beat-um up Rougelike than this is a good option. \n\nIts not super hard like I said but its fun all the way through and builds are unqiue enough to be fun. Give it a try if you are a fan of Rouges or Beatum up', 'The game is completely incomplete.  It''s half, maybe even a third of the actual storyline.  They don''t even tell you the game is over or to wait for a DLC to come out.  On that topic, why would you release an incomplete game and force us to buy DLCs to play out the rest of the story?  Pretty scumbag move.  \n\nNow if that were the only issue, i wouldn''t complain.  However, the game is riddled with all sorts of bugs such as falling off the map and not being able to swap artifacts in co-op mode amon', 'Very Positive', 84.39, 0.65, 28.53);
INSERT INTO reviews VALUES (80877, 3000030, 107, 'I have been playing the game for almost half a year at this point and I don''t plan to stop any time soon as it''s already lot of fun and there is plenty of room to grow.\n\nThe game gets regular updates, about once a month new content drop sprinkled with minor bug fixes and QoL patches between. The developer is very active on Discord and most of the time manages to keep balance between his vision of the game and players'' feedback quite well\n', 'The monsters are cool, I like that you can collect them. Too bad you don''t see them for long in combat since they instantly die... The game was fun at first, as you unlock new mechanics to use. But the numbers becomes so high they lose all meaning, and they do so incredibly fast.', 'Very Positive', 85.05, 7306.27, 48.05);
INSERT INTO reviews VALUES (80879, 3000120, 143, 'this game very good. i''m really excited to see how deep the content goes, that''s like my biggest rule for a roguelike is how deep does the hole go and this hole seems deep. i will throw myself into this deep hole', 'Interesting idea with a flawed execution. Instead of being attacked by waves of enemies like most vampire survivors, in this one you choose to summon enemies, and they can be of 4 different difficulty tiers. Every time you kill an enemy, you heal 1 hp, so you want to spam weak enemies while fighting strong enemies. \n\nThe problem is that every fight feels the same, you are focusing all of your attention of the QTE of summoning more enemies and it doesn''t actually matter if you are sitting in a pa', 'Very Positive', 87.41, 3.27, 6.08);
INSERT INTO reviews VALUES (80924, 3001560, 111, 'One-armed gameplay is top as usual, and if the facts are not bad, the gameplay is ordinary', 'Overpriced for the amount of content, especially with no voicing. Only took a little over an hour to get all the achievements and 100% the game. It''s nice to be able to skip through, but there isn''t too much content.\r\nIf it gets expanded this might be more worth it. Mainly that''s the reason for the negative review. It''s 1hr for $8-9 dollars is a bit much, especially with no video or voice acting, even if there''s animated sexual content. As a short VN it''s not too bad though.\r\n\r\nAlso, if you''re g', 'Very Positive', 88.29, 5.45, 2.27);
INSERT INTO reviews VALUES (80930, 3001730, 110, 'Typical slavic school experience', 'Whats wild to me is people seem to be more bothered by a single rat than a little girl getting abused by her dad and homophobia. I cant recommend this game, it feels like the devs are just out for shock value than making an actual decent spooky game. As a horror fan I''m telling you, you simply don''t need homophobic slurs or child abuse to make a horror game decent and its a sorry day when we are desensitised to it. \n\nIf you want to feel incredibly uncomfortable and sick to your stomach then this', 'Very Positive', 82.73, 0.58, 0.77);
INSERT INTO reviews VALUES (81276, 3009850, 568, 'within 3 minutes of me installing the game, my character already pissed his pants, and then a prison guard burned me with a flamethrower as punishment for pissing in front of everybody.\n\nMat Dickie''s still got it folks', 'I really want to give this game a good review and this game has the opportunity to be perfect, but MDickie has made so many dumb changes that completely strip what made the previous games fun. The main issue I have is how the wanted system works. If you commit even the most minor crimes, the alarm will immediately go off and a million officers will swarm you instantly. Since NPCs can enter and exit rooms in real time now, officers will keep on spawning even if they aren''t any in the room. It''s n', 'Very Positive', 86.97, 0.10, 2.40);
INSERT INTO reviews VALUES (81287, 3010070, 138, 'If world was fair, this developer would have gotten millions of dollars in budget to make a great rival to Disco Elysium, but it isn''t sadly. This game is short, and every second of it is had so much care and craft put into it with clever writing, memorable characters and insane art style. You, indeed, can do great shit with MS Paint. In its short length it somehow manages to be really funny, jerk a tear out of you, and creep you out. Can''t reccomend it enough.', 'It took me 17 minutes to finish the game with all achievements. Yes the art style is cool but there are too many overlapping and reused cut scene that it''s getting boring. I didn''t request to refund the game cuz I like collecting achievements, but this game is more like a collection instead of a game', 'Overwhelmingly Positive', 97.83, 1.27, 0.28);
INSERT INTO reviews VALUES (81330, 3011030, 677, 'Played the demo months ago and loved it, immediately wish listed and waited for the full release. Worth the wait! Love the mechanics in the game, and the atmosphere/vibes are perfect. Excited to explore this game fully', 'nothing hurts more then going on a 50 minute run and then dying to bad game design. such as a count down ending on 1 and not 0.', 'Overwhelmingly Positive', 96.90, 7.73, 1.03);
INSERT INTO reviews VALUES (81345, 3011440, 1225, 'i dont know what happened here but an antler-less moose made me click a clicker in a threateningly sexual manner for 30 minutes and that was pretty cool', 'if you''ve seen the trailer, you''ve played the game. 40 minutes of clicking with some edgy commentary from a dude in a mask. not worth it.', 'Very Positive', 83.84, 0.65, 1.08);
INSERT INTO reviews VALUES (81464, 3014520, 107, 'Nice little game, unfortunately a bit short and the performance could be better. Let''s see how the other parts perform ;) for 7€ the price is okay.', 'I''m SO sick of these devs not writing CONTENT WARNINGS/TRIGGER WARNINGS for their games. As a streamer, I''ve put my trust into these devs to at least have SOMETHING at the start of their games warning our audiences of deep traumatic stories that are going to be happening in your game. It blows my mind that in 2025, these devs keep creating these BrokenLore games with NO content warnings or trigger warnings. Its a small, kind line of text that you can include, but I''m just over it at this point w', 'Very Positive', 82.24, 1.55, 2.22);
INSERT INTO reviews VALUES (81628, 3018910, 134, 'I finished the game with 2.1 hours playtime. Im marking this my favorite horror game of the year so far, because everything is so incredible. It combines cyberpunk and horror which blend together perfectly with the photorealistic graphics and amazingly designed levels. 10/10', 'Honestly, according to the description of the announcement, I expected that here you will have to somehow hide in the locations and avoid meeting with bosses to survive. However, here we are met with boring and scripted walking along a strict route through several small locations. In fact - it''s just a "tour" with special effects in real time on the collected assemblies in Unreal Engine. \r\nThe whole essence of the "game" - go and look, like "experience feelings" together with the main character,', 'Very Positive', 80.60, 2.90, 4.90);
INSERT INTO reviews VALUES (81710, 3021100, 1448, 'Very fun to play, the girls are very pretty and they all have something special. I haven''t played many games of this genre but it has nothing to envy to the rest, they all make you feel that your mere existence has no value as you will never be loved or wanted as in these stories. They all make you rethink your personal decisions and how they led you to be playing a dating simulator at 2 AM. I really liked Gran btw', 'Its not bad, but I dislike being forced to replay several chapters because of the requirements to get to the next chapter, I also feel like there was not enough run time to get to know the characters well enough. Other than that, it was enjoyable.', 'Very Positive', 94.75, 6.22, 3.15);
INSERT INTO reviews VALUES (81724, 3021630, 132, 'A small dev team has put a lot of love and passion into this game, and it shows.\nSavara could be described as "Hades meets Monster Hunter" : fight creatures of different sizes, collect their body parts and craft your weapons and armor. Do not expect it to be as fast as Hades, its combat is slower but still very interesting and satisfying.\n\nThe game is mostly light-hearted and has a simple but fun story, with some great characters. I also had a lot of fun trying to find some easter eggs and refer', 'not sure why this is being compared to hades or no rest for the wicked...the combat flow is nothing like those games at all. \n This is more like a top-down monster hunter.  You break monster parts to craft weapons/armors, with some meta-progression upgrades along the way.\n\ncombat was ok, but there''s a lot of animation locking so it didn''t feel smooth to me.  Due to the slow nature of monster hunter, this game is a lot slower but for an action roguelike, it didn''t really work to me because you do', 'Very Positive', 93.94, 20.07, 0.97);
INSERT INTO reviews VALUES (81918, 3026440, 106, 'Decided to play while the wife was at work. The game was so addictive that I didn''t notice when she came back, I got punched in the face, but the game is cool', 'whelp that was underwhelming. it is neither a good game nor a good pr0n0.  if you think youre getting into an X theme tycoon game where you build and manage a sleazy empire, set up and direct scenes, and do all sorts of custom shit w the models... think again. very boring, i beat it in 15 minutes. lame.', 'Mostly Positive', 74.53, 2.32, 0.50);
INSERT INTO reviews VALUES (81944, 3027260, 268, 'To put it simply, this game is like Flappy Bird with a little bit of Sonic the Hedgehog along with some inspiration from Learn to Fly 2 combined with a healthy dose of Super Rub ‘a’ Dub without skimping on the Pizza Tower in conjunction with that one level from Rayman Legends topped off with some Dark Souls Remastered all from the perspective of the pyro from TF2.\n\nEdit: Realized I forgot Superman 64.', 'I know it''s not fair to compare this to the other games by The Behemoth, but I was at least hoping for something that would be fun and inventive like some of the better flash games on Newgrounds. \n\nIt feels like a free mobile game that isn''t even worth the download. It''s not fun, funny, or interesting. I know these guys can do better. Disappointing.', 'Very Positive', 87.69, 5.12, 1.62);
INSERT INTO reviews VALUES (81971, 3027930, 729, 'This game is a pretty unique take on the Vampire Survivors-style genre. When I first watched the trailer, I thought it was going to be a mix of a beat-em-up and Survivors game—and it kinda is. But at its core, it’s still a Vampire Survivors setup: you auto-attack (melee in this case), and tons of enemies deal damage on collision. Although, I noticed they don''t hurt you when you''re pulling off a combo. You get to mix and match moves from different martial arts, not just karate, which is awesome. ', 'Very shallow survivor game. More about finding a good room to kite in a circle than it is about making a good build. One character. No evolutions like VS. It has melee weapons but they are underwhelming and usually less effective than your hands and feet. You''re basically forced to pick a build that consists of all red or all blue attacks (look at the screenshots) because you get a huge damage bonus for each additional attack with the same color. You can''t skip upgrades, you can only reroll once', 'Very Positive', 91.22, 14.32, 4.08);
INSERT INTO reviews VALUES (81993, 3028310, 982, 'I love this game so much! I have 60 hours in the Beta and Demo. Systems are deep and rewarding, sound design is satisfying and you always just wanna play one more round. By far my favorite tower defense game. The roguelike elements fit this so well. Thank you for making this game!\n\nEDIT: Came back to say, I regret nothing. Still awesome and I am still learning. To all those people that got beyond wave 40. Touch some grass! \n\nRoad Map looks good! Looking forward to new content and new variables. ', 'They broke the game.  The opening economy has been patched to be so punishing that the later stages of the game where the interesting strategy on towers happens have become unreachable.   Because you need to follow a specific "get these items",  "select these upgrades", and pick specific perks for specifically placed towers, without any deviation or variance, it''s about memorizing builds instead of emergent game play. \n\n', 'Very Positive', 88.29, 53.73, 25.95);
INSERT INTO reviews VALUES (82075, 3030250, 174, 'Game of the year 2024 🏆 عشان مافيها اجندة', 'اللعبة تعلق مره و الغرافيك حقها سيء ليتني استخرت قبل ما اشتريها', 'Very Positive', 87.93, 0.43, 6.68);
INSERT INTO reviews VALUES (82092, 3030720, 483, 'So much fun. Everything is better except for two things I noticed. Some item textures look really bad in the UI, and the controls are the same jank from the first game. Other than that, this game continues to grow and improve. There are a lot of new details in environment, and graphics. \n\nI just cant help but think its only a shader with UI over the same exact game we already had. There are a few new things, but it feels unfinished, or at least unpolished. I was expecting more polish, and refine', 'I was really looking forward to this but it feels like it released to early. I do like some of the QOL things that were added but the bugs and visuals really need to be addressed. Some textures and models feel like they have been updated and given a refresh while others still look low poly and low res which causes severe clashing with the art style. There are also a handful of bugs that, while not game breaking, are just annoying to deal with. Also this might just be a minor nitpick but the ques', 'Mixed', 69.57, 0.87, 1.97);
INSERT INTO reviews VALUES (82258, 3034600, 117, 'Not a bad game that is good for a couple of evenings. The game has good scenes that surprised me but unfortunately not much functionality', 'There is not a single mention that all characters in this story are intersex (hermaphrodite).\n\nThe trailer features voices characters. There are none in this game.\n\nPlease don''t trust this publisher.', 'Mostly Positive', 73.50, 4.42, 0.40);
INSERT INTO reviews VALUES (82302, 3035500, 711, 'As someone who''s interested in using this to map out a campaign setting for D&D and/or other tabletop games, I''d really like to see an option that would allow the "player" to set up details (country names and their religious and cultural details, for example) for the various nations on the map before pitching head-long into developing the world''s history.  It''s hard to customize when the game starts the action immediately.', 'I love the concept behind this game, and in practice it seems fun. However, there are far too many ways to accidentally delete everything you have worked on, and there is no undo button. An example, I just spent two hours getting my provinces exactly how I want them. I went to fix a few things about the nations so clicked the random nation button. The YES OPTION on this menu also completely rearanges provinces. A couple hours of work down the drain and no way to undo it. I WILL NOT give this gam', 'Very Positive', 88.33, 0.22, 1.88);
INSERT INTO reviews VALUES (82305, 3035570, 3124, 'Hey Ubisoft ! Want to sell your very skippable 7/10 games ? Then give up on you ubiApp garbage and free us from installing it on our machine. From the hole commuty', 'Getting that "Ownership authentication error in Ubisoft Connect PC when launching game through Steam".\nUbisoft please DELETE THIS Ubisoft Connect or Uplay or whatever its called these days.', 'Mostly Positive', 74.87, 5.67, 0.25);
INSERT INTO reviews VALUES (82324, 3035990, 140, 'Has the novel idea of making the protagonist of a mystery story extremely bad, possibly the worst, at dealing with mysteries - spent her entire life in a single room, barely able to tell left from right, easily overwhelmed by stimuli, poorly repressed hornball - and therefore extremely relatable, so I enjoyed myself greatly.', '', 'Overwhelmingly Positive', 100.00, 12.55, 0.00);
INSERT INTO reviews VALUES (82327, 3036080, 470, 'Really good, Imagine you work as a shaworma man and come home and work as a shaworma man, now i want to become a shaworma man', 'It''s a cute little game and fills an interesting niche. But this all comes at the cost of some pretty fairly blatant AI usage. AI has no place in video games.', 'Very Positive', 90.64, 9.48, 0.13);
INSERT INTO reviews VALUES (82402, 3037930, 186, 'You are not alone. Violence and injustice are harsh realities for many but that doesn''t make them normal or acceptable.\n\nSilence only lets the darkness grow so reach out to people you trust or seek help from professionals and organisations to support you. There is a kinder future awaiting you. https://safeandtogetherinstitute.com/international-domestic-violence-resources/', 'Mouthwashing and Its Consequences:\n\nTo start, I will say that The Hole is ultimately coming at this triggering topic from a place of good faith and I don''t think the devs are, like, bad people or anything. I think they genuinely wanted to tackle the topic of domestic violence and CSA from their uniquely interslavic POV, and I do appreciate their attempt to do so. However, a lot of this game and its treatment of those topics left a really bad taste in my mouth.\n\nA majority of The Hole revolves ar', 'Very Positive', 90.32, 1.12, 0.78);
INSERT INTO reviews VALUES (82629, 3044030, 276, 'One of the best Anomaly games I have ever played! \r\n- Detailed atmosphere\r\n- Excellent storytelling \r\n- Superb music\r\n- Unexpected moments \r\n- Good spooks (absolutely no cheep jump scares)\r\nAnd the best part of all was that I was raided on Twitch by the dev of the game just as I 100% the game. The community behind Hillfort is 10/10 and I look forward to the next adventure!', 'Game wants you to look for anomalies, yet can''t be bothered to sort out environmental inconsistencies such as mirrored bottle labels so the game actually makes sense. \n\nSome of the set pieces are really cool! But it isn''t polished enough for me to accurately guess if the z-fighting on textures is an anomaly or a developer oversight.', 'Overwhelmingly Positive', 96.38, 3.55, 0.97);
INSERT INTO reviews VALUES (82633, 3044100, 198, 'Bat to the Heavens is the kind of game that will NOT pull its punches from the player, and it will force them to interact with the complex momentum physics it has in play.\n\nThe game will greet you with a lovely art style that mixes 2D pixel art with some really neat 3D backgrounds, all culminating in a great showpiece of what the Godot engine is capable of achieving. Together with some relaxing tunes that will keep you from absolutely hating your life after you mess up your swings, Ceroro did an', 'See that bit at 21 seconds in the reveal trailer? That''s the very first room in the game after you get the bat. I could not beat it. I feel like a games journalist. This game requires precision my thirty five year old hands are straight up incapable of in the very first room. I looked up a video and watched someone beat it and could not replicate it. I beat Celeste, I don''t think I''m BAD at platformers, but I''m sure not good enough to play this.\n', 'Overwhelmingly Positive', 97.47, 19.98, 0.58);
INSERT INTO reviews VALUES (82648, 3044550, 177, 'I recommend this game because it allows you to do things that are impossible in real life, like talking to girls and having sex with them.', 'Way too simple, way too short. All the characters you have seen here is all you get and they only have a scene once(except the elves I guess). Sex scenes don''t even have climax. But I guess the game is cheap enough, but hardly recommendable.', 'Mostly Positive', 72.88, 1.17, 1.22);
INSERT INTO reviews VALUES (82649, 3044560, 113, 'Finally, after all these years, a new Left 4 Dead has been released.  This game has something that was not in the last part, namely hot ladies who will give a juicy blowjob to their savior! I will wait for co-op to get together with friends and their wives and share the experience of this game.', 'This just a killing floor 2 mod , with 18+ scene that not even relate to the game imo. So far there around 5 kind of zombie that  similar to KF2 as common , boomer , siren , fleshpound and those invisible witch. Have some kind of upgrade system but once your start the horde there no stopping unless die. Have minor bug (M249 disappear while u can still shoot it ). The 18 scene dont have much fetishes , some vanilla , BJ and yuri. Considerate buy this game if it around 1$ , other than that 1hr is ', 'Mostly Positive', 78.76, 1.42, 1.15);
INSERT INTO reviews VALUES (82733, 3046600, 149, 'I''m conflicted because CAPCOM decided (for whatever reason), to censor this games, just why?!?!?! \nThis is one of my all time favorite games, please, revert back to the original, 100%, no censorship at all!\nThis game is from the golden era of video games, just pure fun, i absolutely love this game, and i still have my Onimusha 2 from PS2 on my shelf by the way.', 'If i knew they censored it i wouldn''t have bought it. I think anyone censoring this or that is pure scum. Everyone should be outraged, if they censor one thing than its a matter of time before they censor everything, than you''ll pay 50 bucks a month to read only two books, the bible and "a walk to the light house"', 'Very Positive', 90.60, 11.20, 24.77);
INSERT INTO reviews VALUES (82799, 3048140, 236, 'So, first I tortured everyone.\r\n\r\nThen I asked a few questions.\r\n\r\nThen I hung the priest and left.\r\n\r\n10/10', 'having no other options to advance time except torturing people and having the torture be simple timing minigames really took any shock and uneasiness out of it\nlackluster ending\nthe only thing the game has going for it is the nice cutscenes for the visions\n3/10\nwaste of time', 'Overwhelmingly Positive', 95.34, 0.82, 0.60);
INSERT INTO reviews VALUES (82804, 3048280, 155, 'For the price its amazing even if it was £10 it would still be worth it for me', 'Crashes when i load in..', 'Very Positive', 83.87, 7.10, 27.12);
INSERT INTO reviews VALUES (82878, 3050220, 125, 'I mean if you already have the old version then might as well upgrade it to the current one, it''s only $7. This seems to be the unpatched day 1 version of Global Match interestingly. I remember when it released on the other platforms the rollback had issues too but they were addressed with a patch. Now why didn''t SNK just release the patched version from the get go I don''t know but maybe they''re working on a day-one patch specifically for PC. Either way, I doubt the rollback is gonna stay broken', 'DO NOT BUY THIS PORT UNTIL IT''S FIXED!\nAlthough offline seems to be working ok, online it''s completely unplayable even under the best conditions (literally playing my neighbour). It seems that the game portrays rollback as frame drops or something like that. The game is a visual choppy mess. This is with 28ms connection wired. When I increase fixed delay, it gets better although still visually choppy.\nThis is not normal rollback behavior. I own the PS4 port and it works completely fine and is ve', 'Mostly Negative', 37.60, 0.18, 33.60);
INSERT INTO reviews VALUES (83023, 3054610, 137, 'Well, I downloaded the demo, completed, bought the game, played for 2 and half hours. It has a couple minor things that I would like to see improved, such as the audio. It is kind of "meh". On easy, first time players will have a fun experience that will prepare them for later levels. You aren''t punished for starting on easy. Makes for a fantastic welcoming experience for new Action Roguelike players. The controls feel fantastic. I prefer to play these types of titles with a controller. This fee', 'I asked multiple times on the Discussion board to allow players to rebind their keys. It needs to be a thing because the devs messed up the inputs for the game and have yet to fix it. Game gets a bad review for lazy devs who can''t implement a simple configure keybind option.', 'Mostly Positive', 74.45, 2.45, 2.85);
INSERT INTO reviews VALUES (83146, 3057760, 129, 'Played the demo and i love that it kept the crops i bought and maps i beat from there, just beat mountains and i have to say this game is just so great and most definitely worth the price. Excited to see future updates', 'Game in a nutshell (Play Meta and only Meta, win. Play anything other than Meta, lose.)\nUnderstandably, the game is RNG however, power scaling in PvP doesn''t exist and more times than not its just the same build over and over. They really missed the opportunity to name this game rock, paper, scissors instead.', 'Very Positive', 90.70, 3.57, 9.28);
INSERT INTO reviews VALUES (83185, 3058630, 4705, 'It''s early access and people are tweaking out. For me it works and what is included feels amazing', 'The game is really good. Cars handle great, and unlike the first game it works with a controller and wheel out the box. Seems like they''ve learned from the mods. Graphics are fine, and the Ai opponents are fair. There''s a couple of FPS hiccups when you minimize the game and go to another window, but that can be fixed before launch. Along with other bugs, which I haven''t experienced too many of. I''d say we''re off to a good start?\n\nSo why am I down voting this games and not recommending it to anyo', 'Mixed', 69.27, 5.02, 17.78);
INSERT INTO reviews VALUES (83199, 3058890, 213, 'bro thought he could become the next rizz king by doing the uncanny ankha zone dance like a sussy baka in ohio💀 dont bro know quandale dingle already did the forgis on the jeep thug shaker banban style with baller💀bro aint ever making it out of oklahoma the ocky way💀 bro got negative infinity morbin chill bill pizza tower barbenheimer rizz bro💀bro got that nathaniel b ahh griddy bro💀bro got that canon event baby gronk waffle house monday left me broken ahh drip in ohio bro💀 we aint ever makin it', 'ppl online: ''hey how are u''. \npeople irl: ''LMAO 5''5" manlet with a NW1 Norwood receding hairline at 22, negative FWHR, no zygomatic projection, subhuman IPD, and a philtrum longer than your future. Bunny-tier maxilla, no jaw definition, and ears that stick out like a fucking car door mirror. Your voice is higher than a Stacy’s after helium, and your shoulders are narrower than a foid’s dating standards. A literal NPC with the skeletal structure of a malnourished Victorian child. No T. No frame. ', 'Overwhelmingly Positive', 97.18, 0.12, 0.27);
INSERT INTO reviews VALUES (83203, 3059010, 100, 'Chinese Metal Slug running in flash.... yeah \n\n:D', 'Purchased while influenced by nostalgia until I got reminded how jank and bullshitty the game is, didnt age well at all. The memories I have with this game from my childhood are fond, but not ones i''d like to return to', 'Overwhelmingly Positive', 97.00, 4.75, 0.57);
INSERT INTO reviews VALUES (83205, 3059070, 2737, 'Great concept, but needs more interiors, maps and monsters.\n\nFor now 2.5 hours of fun, then gets old.', 'The game really has potential, and I will probably check in on the game in time to see if it has lived up to it. The game really needs  more than just photo taking. Lethal Company is built on watching your friends die in horrific ways while your running around getting scrap, Content Warning is literally you watching your shenanigans play out on the big screen. This game is just taking photos of some cool designed aliens that walk in straight lines and make your friend''s arm fall off. If this gam', 'Very Positive', 88.24, 2.77, 1.03);
INSERT INTO reviews VALUES (83226, 3059520, 1462, 'Bought the game, \r\nStarted a 78-lap Monaco race,\r\nStroll crashed into the wall on lap 17. \r\nPretty realistic, all recommendations.', 'First off the driving does feel marginally better. The dirty air addition feels nice.\nGetting rid of the ability to have a custom driver in My team is hugely off-putting for me and I''m sure for many people who just want to enjoy immersion in the offline mode as well. I was super excited to try out the new My Team but the simple inability to have a custom driver killed it for me.\nThey say they did it for realism yet you can still still have drivers on the grid who retired decades ago but a custom', 'Very Positive', 88.37, 222.55, 25.53);
INSERT INTO reviews VALUES (83245, 3060170, 103, 'the game is awesome. thanks to it, i no longer hang out with my friends (my old friends), thank you!', 'I don''t have friends anymore.', 'Mostly Positive', 73.79, 1.93, 2.52);
INSERT INTO reviews VALUES (83305, 3061810, 2724, 'Wow, the Pirate game genre is pretty dry right now. I wish there was a game that could scratch that itch.\r\n\r\nThe Yakuza series for some reason:', 'Compared to other yakuza games, I wouldn''t recommend this game. It''s unfocused, inconsequential, and not worth the price. I''ve been a fan for 7 years and love Majima as a character, so I was excited for this, but I was left disappointed. The gameplay is very easy, even on the highest difficulty; There are no memorable boss fights, and all fights can be completed quickly by spamming the main attack button. The side content even feels rushed, and the completion list is very easy to complete. I rea', 'Very Positive', 92.55, 49.37, 24.45);
INSERT INTO reviews VALUES (83355, 3062970, 126, 'WarioWare but fish.', 'A competent warioware clone that suffers from a lack of polish. Most of the microgame ideas are great, but there are a lot of situations where a game just can''t be completed within the time limit due to either RNG or poor balancing. A good example comes in the form of the "find the game" microgame which has you sift through a fake file system trying to find an exe. The problems come from the lack of a pattern (sometimes the exe will be in Programs>Games, while other times it will be in something', 'Very Positive', 93.65, 4.62, 2.48);
INSERT INTO reviews VALUES (83588, 3069120, 599, 'If you ever see me getting drugged by my beautiful white haired gf with the prettiest eyes, leave me alone. I''m right where I want to be.', 'I wasn''t going into this expecting anything crazy, but for there not to even be a kiss scene with my love interest was very disappointing. It never felt like my character ever had a very meaningful connection with them either. Extremely disappointing game, did not even want to try any of the other routes. I wanted to like this as well, but found myself skipping through most of the dialogue by the end. I kept waiting for that spark of love between the MC and the love interest to finally happen an', 'Overwhelmingly Positive', 99.67, 16.88, 4.65);
INSERT INTO reviews VALUES (83608, 3069470, 153, 'Spend real money to get fake money to get real money', 'Same situation as Banana, you idle on the game and get an item dropped into your inventory, you sell it off to someone who''s very irresponsible with their money, and the dev gets a cut of the profit from the Steam marketplace.\n\nEither don''t participate in the market part of it, or open Unity and make your own gimmick "clicker" in the hopes of getting rich quick.', 'Mostly Positive', 79.74, 770.07, 6.58);
INSERT INTO reviews VALUES (83618, 3069810, 295, 'Great horde-survivor game, been waiting for it!\nThe graphics and the pixel art are on point\nMy issues: lacks content (which is understandable since the game JUST came out), i''ve been able to unlock everything with 3.5 hrs playtime and the enemy models/sprites are getting boring after a bit since they''re only 3.\nIm not leaving a negative review because the game is new and im sure the devs are gonna put more on it for sure!\np.s. VERY FUN GAME!', 'This game lacks any sort of depth.\r\nIt''s too easy to complete and does not offer enough challenge. It does not even require moving, the build paths are extremely straightforward, and you can complete it after around 30 minutes of gameplay. The rest is just a grind for achievements.\r\nThis is more of a draft game than anything else, the gameplay is completely idle.', 'Very Positive', 93.56, 3.90, 4.15);
INSERT INTO reviews VALUES (83655, 3070520, 359, 'super fun with friends but why is there jiggle physics 😭😭😭😭', 'Absolute dogshit, developer sneakily changed the description pre-launch from: "This is a creepy co-op horror game for 1-3 players." to: "This is a creepy co-op horror game." so if you pre-ordered it you wouldnt get the game you initially bought. This can only be played with 1 friend, see how i dont use the plural "friends" like the description of this game still does? Because you arent playing with "Friends" but with "A Friend". Also, a shitton of bugs, audio resetting each time you enter the ga', 'Mostly Positive', 79.11, 4.08, 1.75);
INSERT INTO reviews VALUES (84047, 3080380, 178, 'This anthology is already worth paying just for the "No I''m Not a Human"\nThe game is not even out yet, and have an insanely high potential for it to be the next "Five Nights at Freddy''s" speculation story level.', 'Welcome to 2024, now you buy the demos too.', 'Very Positive', 85.39, 1.88, 0.85);
INSERT INTO reviews VALUES (84177, 3083300, 311, 'It''s less of a puzzle in that you won''t have to think hard and much (and when you get lost, a hint is free). But it''s a great logical timekiller to fill during boring calls and the likes — and Bruegel''s proverbs are very fun to learn as well!', 'I love puzzles, but there''s very little variety or satisfaction here. I completed about 10% of the game, at which point I realized that it had long ago started to become more tedious than rewarding. I really want to give this a positive recommendation, since it should be right up my alley; but I really just feel like I would have been better off without the time invested in this clever but unsatisfying jaunt.\nThere is no discernible pattern that allows you to "see" what you''re painting as you so', 'Overwhelmingly Positive', 98.07, 21.72, 13.15);
INSERT INTO reviews VALUES (84321, 3087650, 364, 'This game is incredible, it shows the reality of what it''s like to have cats, a busy house and toys everywhere haha.\nAnd the most important thing is to show that every kitten deserves love and affection, regardless of what they are, the media always tries to show the most ''beautiful'' cats and this creates a mental illusion that that is what really is beautiful, which is not It''s true, all cats are beautiful, of all ages, colors, with disabilities or not.\n\nIf you can, buy the games, they are all ', 'I''m surprised about the overwhelmingly positive response. I looooove the Full of Cats games, and this one just didn''t deliver. The story is weird, the drawing seems rushed, the minigames are peculiar, and the hidden cats don''t make any sense at all. In few points I was just clicking around trying to find things without having the fun of deduction. Just a heads up for anyone who is expecting the same as the previous games. Cats are still cute though!\n\nI do appreciate the message of the game and I', 'Overwhelmingly Positive', 97.80, 16.88, 2.97);
INSERT INTO reviews VALUES (84351, 3088250, 216, ' The game feels like finding a random 10-episode anime made by studio Trigger back in 2012 and that shit is the bomb. We need more "Trigger-likes" aesthetics!', 'Cute girls, great art direction, solid menu/UI design in the main menu. The Horoscope system is novel. There''s weapon variety which I like though the salary and unlock loop feels a bit strange.\nAnd yeah, general gameplay feel kills it.\nIf you move through a level a certain way your cursor can get stuck on one side. Feels terrible. Don''t know, it''s like your mouse is on a leash. Controls are stiff in general, ledge drop inputs feel forced (you need to stop and tap down which doesn''t feel great at', 'Mostly Positive', 78.70, 6.78, 0.77);
INSERT INTO reviews VALUES (84628, 3095170, 127, 'I was torn between giving this a thumbs down or not but the amount of content makes it hard to.  My only real problem is compared to almost every other VN I''ve played this one feels almost like a chore to get to H scenes.  I''ve got like 7 hours played because I don''t skip dialogue and it feels like I''ve seem around 5 scenes.  I can appreciate the story but it''s so much dialogue that it''s annoying at times.  The renders and character models look really good though.  The decent price is probably w', 'Finishing it i can say that you don''t stick your dick in any child stylized adults. but you do perform several sexual acts upon their specifically child sculpted bodies. don''t worry though, the author assures you that they are def 18. I can only assume the authors other works and their proclaimed second and even third chapter will titillate any would be peter files out there.', 'Very Positive', 88.19, 20.27, 11.98);
INSERT INTO reviews VALUES (84741, 3097560, 12806, 'This game is hilarious with friends and fun as hell.\n\nI hope they add a character who is just a normal Otter, so he has to stand on a stack of books and hold the cards with both paws.', 'It''s a great game with a great immersive aspect to it. Great game for friends to get together and shoot the shit with eachother.\n\nHowever... I cannot recommend that you play this game from a public lobby with randoms. Hackers run rampant and are allowed to look at your cards, connect to your PC, change the odds, change their own cards, the list goes on.\n\nBuyer beware right now -- the game is very insecure and the P2P networking model allows anyone to have a connection to your PC.', 'Very Positive', 90.61, 14.12, 2.90);
INSERT INTO reviews VALUES (84778, 3098470, 120, 'Made a negative review about the game being disorienting because there was no FOV slider and the dev said it makes the snow look a glitchy in a steam discussion thread so assumed that was the end of the matter.\n\nWake up the next day to see a dev response that they added an FOV slider. Comes with a warning about the snow but who cares, absolute legend to positively respond to feed back like that and I wish them the best. 10/10', 'Check your settings before loading a game. It automatically goes for ultra, but if your computer is not a beast, this will hog your resources, and for pretty pitiful graphics.\nHalf my playtime is loading time, and I do not have a minimum spec computer.\nDays fly by, light is terrible as if there is no outdoor light, there is no light in the rooms. No light switches, no flashlight.\nThere is no ''find'' feature so you can clean the dirt or pick up trash without the light, so have fun when there is no', 'Very Positive', 91.67, 1.52, 1.20);
INSERT INTO reviews VALUES (84837, 3100210, 113, 'HE AMPUTATED ME AND LOCKED ME UP JUST BECAUSE HE DOESN''T AGREE WITH ME ABOUT CAPITALISM', 'The game got very cute graphics, but real short story. , time skips and it tells you the end by a text. We can''t really see the relationship growing up(maybe expected since it''s a comedy game? I can''t tell). I expected an elaborated/interesting game, since it''s finished. If i''m being honest with whoever is reading it, I would not recommend the game, but if you are looking for a simple and bit silly game to expend idk 1 hour, go for it (maybe a little more if you want all the ramdom, yet funny ac', 'Overwhelmingly Positive', 99.12, 1.13, 28.32);
INSERT INTO reviews VALUES (85131, 3107330, 8834, 'Saw this game on video from real civil engineer and i gave a try and i can say its very addicting, finished the game in one sitting abolutely love it!', 'I''m going to have to give this game a negative.  While there is an option to "disable flashing", it does not, in fact, disable it.  By the time you get to the later game, the constant strobe effects become intense, and caused a seizure.   An option to disable a harmful effect should, in fact, do exactly that.\n\nAs it stands now, this game could kill someone without appropriate warning.\n\n', 'Overwhelmingly Positive', 97.59, 6.25, 3.12);
INSERT INTO reviews VALUES (85159, 3107900, 262, 'Along the same lines as "Pools", a Walking Simulator divided into 4 chapters. In my opinion it is too expensive for the total duration of 1/2 hours and too repetitive. Maybe the final chapter is the one a little different but in general there are few things to observe.\nThe sound is one of the qualities of this game, in fact in many scenes it is really spot on.\nWait for a discount to buy it. 6/10 my rating', 'It was ok at first, nothing too special, but nice. A tyical liminal space walking sim. But after 90 minutes I got a ciritical error (by just walking around) and now I can''t get it to start up again. My laptop is higher than the recommended stats. I don''t trust it so I''m refunding it. The game needs more work I think.\n\n', 'Very Positive', 85.11, 1.60, 1.57);
INSERT INTO reviews VALUES (85184, 3108510, 6822, 'very cool game if u are a fly but want to know what it is like to be a knight\nor if u are a knight that wants to know what it''d be like to be a fly but u r still a knight\n\nwould recommend even if u r not a fly or a knight', 'Game keeps crashing at a certain point. I''m not sure if it''s purely a multiplayer issue, but I didn''t get this game to play it alone.', 'Overwhelmingly Positive', 96.85, 2.67, 0.98);
INSERT INTO reviews VALUES (85295, 3111080, 414, 'I solved the potion making system, made an absurd amount of spell power increasing potions, and then tried to cast the basic mush spell. The spell that was originally meant for pushing buttons on high-up walls now hits with as much force as a tomahawk missile. I cast it ONCE and it destroyed everything in the courtyard and flipped over the giant bounce pad in the green space which proceeded to bounce against itself and rocket into space. Best game ever.', 'The game has a disgusting technical realization. The game crashes because of “low video memory”. After tambourine dances it worked, but it''s a pain. The visual part of the game does not look to be so demanding', 'Overwhelmingly Positive', 97.34, 3.80, 0.92);
INSERT INTO reviews VALUES (85341, 3112260, 914, 'It''s the definitive version of the game. Yes, it''s lacking single-player content—I don''t believe SEGA intended for R.E.V.O.''s audience to be of the single-player kind. You''ll only be buying this game for the core Virtua Fighter experience; nothing more. If you''re an old-school competitive fighting game player, you''ll love it. However, if you''re one of those that need story modes, world tours, and avatar customization, you should pass. R.E.V.O. is not for you.', 'The publisher was not transparent about what version of the game that was being released for sale. There should be plenty of customization options available but they''ve gutted the mode from previous versions of the game that would let you acquire them, in favor of purchaseable DLC, for a 20-year old game, in a desperate bid to push sales to continue to fund the next installment in the series.\n\nThe terrible thing here is--I enjoyed the gameplay. However what is on offer is amazingly and unfairly ', 'Mostly Positive', 76.37, 40.43, 1.75);
INSERT INTO reviews VALUES (85396, 3113680, 110, 'so far pretty fun, there might be some bugs but that''s fine', 'BanBan? More like BadBad! -Freddy Fazbear  (he said this)', 'Very Positive', 92.73, 4.82, 1.07);
INSERT INTO reviews VALUES (85413, 3114010, 182, 'this game. HOLY. I''ve never had a game made my actual hairs stand on end ever, but this one did that. The scares are incredibly effective, the atmosphere that is crafted is immaculate. Usually with infinite looping games, it becomes kind of boring after the first few loops. CAPTURED defies that standard. Hands down one of my favourite horror games of all time. \n\nIf you''re reading this asking yourself: "Is this actually scary and/or worth the $9(CAD)?" The answer: Yes. A million times yes. You wi', 'I hate to do this because this game seemed to have promise. Sure it was fun for about 15 minutes, but you literally go around the very small house in circles over and over forever until you "spot the differences". At first it was fun and some of the objects and rooms were interesting. But the game is wonky. For example, sometimes you need 3 objects to successfully "loop" and get the rooms to change, but other times only 2. So which is it? Then once you start racking up objects, let''s say you get', 'Overwhelmingly Positive', 96.70, 4.67, 1.15);
INSERT INTO reviews VALUES (85533, 3116890, 247, 'Love this game. Its the only way I will ever see the phrase, "Here are your World Series Champion Pittsburgh Pirates." \r\n\r\nBob, sell the team and just buy this game. I feel even you would hate to work for you. Or just sell the team.', 'Performance issues don''t make up for the mediocre changes that barely iterate on itself in the previous version. Playing for longer than 30 minutes introduces input lag so severe you need to restart to fix the issues.\n\nI''ve been playing OOTP since OOTP18, and have 6k+ hours across all versions. This is one of the worst performing, least improved versions of the game I have received, and if you have either OOTP25 or OOTP24 there is no reason to buy this version. \n\nIt feels like the game needs a h', 'Very Positive', 80.16, 190.27, 1.72);
INSERT INTO reviews VALUES (85553, 3117820, 676, 'Great game 10/10. The game review is mixed because it’s been bombarded by homophobic Chinese reviewers. Apparently you can romance Faris in the game but the Chinese gamers don’t like that. Avoid the Chinese community and just enjoy the game.', 'this game is fun, and i’m enjoying it, but the english translation is so poor that i can’t recommend it in its current state, especially not for the price it’s at.\n\ni could forgive the frequent misspellings and grammatical errors, but what’s harder to look past is some of the sentences being so lost in translation that you can’t even figure out what is trying to be said. there are parts of the game i simply do not understand because the explanations make no sense in english. the translations are', 'Very Positive', 94.67, 11.35, 69.73);
INSERT INTO reviews VALUES (85685, 3121110, 2363, 'For the blind, zort is light. For the hungry, zort is bread. For the sick, zort is the cure. For the lonely, zort is company. For the sad, zort is joy. For the prisoner, zort is freedom. For the poor, zort is treasure. For me, zort is everything.\r\n\r\nIf zort has a million fans, then I am one of them.\r\nIf zort has ten fans, then I am one of them.\r\nIf zort has only one fan then that is me.\r\nIf zort has no fans, then that means I am dead.\r\nIf the world is against zort, then I am against the world.', 'Why are you looking for bad reviews, this game is peak and it''s 4$ buy it and play it with friends if you have some', 'Very Positive', 94.79, 3.17, 2.05);
INSERT INTO reviews VALUES (85698, 3121470, 133, 'If you''ve heard about this game, it''s likely in the context of Outer Wilds, and a lot of the influence is clearly there. The level and puzzle design is filled with all the rule discovery, revelation, and exploration that that comparison would suggest. Its notable that, unlike Outer Wilds, there is still a fair amount of logicking and execution to be done even after the rules are understood, placing Chroma Zero as a unique intermediate between the pure riddle-like "puzzles" of Outer Wilds and a m', 'Pretty game, with a nice (albeit repetitive) soundtrack.  The biggest problem is that there are things you learn through observation...but the developer puts all these other hints in to make sure you were right about what you were observing.  Unfortunately the hints are very abstract leading you to think that they are a completely different puzzle.  So the answer to the thing you learned through observation is also presented through abstract art and dialog.  Sometimes you''ll spend time trying to', 'Overwhelmingly Positive', 98.50, 9.65, 29.45);
INSERT INTO reviews VALUES (85784, 3123410, 479, 'Played 10 hours from the demo before the game released, and it''s everything I had hoped for from the promotional material. Alchemy system from the Atelier series with open world exploration taken from Breath of the Wilds , combat reminiscent of Final Fantasy 15, along with a more mature direction with the narrative. So far have been enjoying myself, and looking forward to the rest of the game now that the main game is up.', 'I might change my mind on this, but I''m honestly unsure how to feel about this game. First off, all the negative things in other reviews listed are just true. The graphics are strangely blurry and no graphic setting fixes that. It''s like you should be wearing glasses. The game also only takes 2% of your GPU, uses 40% of your CPU, but somehow freezes and drops frames (especially around the lighthouse), while it has so many extra resources still to use... what''s even up with that?\n\nThe protagonist', 'Mostly Positive', 74.32, 37.17, 1.85);
INSERT INTO reviews VALUES (85844, 3125120, 144, 'Rodland ain''t even mad that you won bro he writes a whole musical number about how not mad he is', 'My PC somehow couldn’t handle it, it’s a 86 bit computer. :(', 'Overwhelmingly Positive', 99.31, 4.03, 0.48);
INSERT INTO reviews VALUES (85877, 3125890, 134, 'Absolute blatant ripoff from Rogue Tower.\n\nAnd since i love Rogue Tower and it pains me to see it abandoned, I''m crossing my fingers for Mineral Defense.\ni''m gonna miss the juicy ballista hit sound and the annoying vibing music, which MD doesn''t get close to, but still better than nothing. :)\n\nhere''s to MD outgrowing it''s spiritual predecessor!\ncheers!', 'Great gameplay for a tower defense genre, probably the best of its kind\r\nBut the progression ironically sloooooooow and the tech tree progression is tedious, i hope the reason arent because devs farming players playtime hours, it need to be fixed, the tedious progressions disrespect players time\r\nJust play Nodebuster instead\r\nBut still fine if you want this game, get it on sale', 'Very Positive', 93.28, 17.82, 56.92);
INSERT INTO reviews VALUES (85886, 3126150, 203, 'I HAVE BEEN SOMERSAULTED 10 BILLION BLOCKS AWAY, I HAVE BEEN SENT TO HEAVEN, I HAVE BEEN THROWN INTO THE SUN. great game', 'I did enjoy the game and following the story, however, compared to the original game it was very lackluster. The puzzles all had the same concept which ruins the replay ability. Instead of having two different stories, you play alongside each other. If you are looking for a game just as good as the original Bokura you will be disappointed. It was enjoyable to play through, but it isn''t as fulfilling. I was looking forward to having two new perspectives, but I was let down tremendously.', 'Very Positive', 85.22, 1.12, 5.23);
INSERT INTO reviews VALUES (85897, 3126330, 501, 'I opened the game, spent one minute exploring the room and then another 29 spawning infinite soda cans out of the box in the storage room all the while a phone was ringing right into my ear trying to distract me from playing the game.\n\nAfter filling the entire floor and lower shelf level with soda cans the FPS has decreased noticeably, making my soda spawning experience less pleasant and entertaining. I hope the devs will fix this issue so I can continue enjoying the game', 'Honestly, I was so excited about this game because the demo was scary, absolutely I thought the cooking was nice but I expected more horror and longer story than the demo was. \nI was scared though so you get a big plus on that but the rest would have liked to see more of. :(', 'Very Positive', 90.82, 0.52, 2.38);
INSERT INTO reviews VALUES (85977, 3128740, 111, 'We''re trying to make amazon profitable with our poor bezos and it''s really not easy. Considering that Bezos is sending rockets into space, the game is really open to improvement.', 'I''m kind of suspicious about the other reviews. There''s really no progression at all other than having more money, buying more expensive items, putting them in the same boxes, and selling them for the same 30%-ish profit. The other vehicles make no sense to buy unless you''re selling a ton of cheap items for no reason. Same with employees. The items all seem to have similar profit margins so why sell 100 of something when you can just sell 2 of the more expensive thing?\n\nThe game won''t even let y', 'Mostly Positive', 77.48, 5.15, 1.82);
INSERT INTO reviews VALUES (86065, 3131680, 234, 'This is a good Subway Surfers clone. Fun abilities, decent maps, and overall fun to play.\n\nI would give it a 7/10 because the gacha grind is a nightmare.\n', 'ehhhhhh.. i''m torn. the gameplay is really fun! but i impulse bought it and didn''t realize how.. mature... the art was. not my thing, personally. :/ but if you''re into that and want to play a fun subway-surfers-type game with vtubers, then this is for you!', 'Overwhelmingly Positive', 99.15, 3.13, 0.17);
INSERT INTO reviews VALUES (86209, 3135930, 103, 'I did not know Steam showed my friends what games I play.', 'This VN Released back in 2024-09-18 before it came to steam. this VN is one of My Favorites. But Until I see More Consistent News and Updates on steam my Review will change to Recommend. I DO NOT Recommend VN''s that have no Official News of any plans/progress to Update and Continue the Story of an Unfinished VN. Chapter 1 was not enough to rate this.', 'Very Positive', 88.35, 7.97, 9.85);
INSERT INTO reviews VALUES (86318, 3138780, 280, 'Game''s a blast but super unbalanced in terms of logic to prevent losses due to bad luck, especially when you get to the part where you have to start mixing medications. I get that the idea is that you can''t cure everyone but you reach a point where you can''t even cure most of your patients in a day if they need high doses because you run out of everything and sometimes need to mix ALL FOUR medications at once. I know resource management is part of the game but I can''t help but feel there should ', 'I want to like this game. It''s a super interesting concept let down by poor execution. I was honestly shocked that it came out so soon after the demo-- the devs received a lot of feedback that the mechanics were confusing, poorly explained, and frustrating to use, but instead of meaningfully addressing these concerns they simply slapped a couple of sentences into the in-game instruction manual and then released it.', 'Mixed', 69.29, 5.90, 0.92);
INSERT INTO reviews VALUES (86380, 3140620, 200, 'Take the game play loop from Helldivers, mix it with the aesthetic and humor of Strange Brigade, add in a dash of the Doom soundtrack, set it in the 1950s and release it on early PS2 and you''ll get C.A.S.T. I''ve only played a couple rounds but i can''t wait to get my friends on and go some more.', 'Accidentally dismantled the gun I spent hours upgrading. This made me realize the game is far too grindy to go and get back what I lost.', 'Very Positive', 93.00, 23.72, 12.40);
INSERT INTO reviews VALUES (86569, 3145620, 107, 'It''s a short but deep, psychological horror visual novel, really diving straight into an unravelling mind. The art of the game is simply gorgeous, it''s a ASCII style design that just looked incredible to me, really powering those horror feelings. Less is more in horror, and just seeing black outlines in ASCII turns out to be quite effective.\n\nThe sound design was pretty good too, building that horror ambiance. Gotta get the headphones on for this. I did enjoy the writing too, the story was short', 'Look, it''s an extremely well-crafted game, with unusual and beautiful visuals, clear and moody sound design, and solid writing. Hats off to him for his creativity and the amount of work this must have taken. I will look for other games from this developer. \n\nThe first time I got to an ending, I had moderately positive feelings toward the game, although I was a little dissatisfied because I didn''t get what I''d consider a "good" ending. You can hit "continue" after the ending and the post-ending m', 'Overwhelmingly Positive', 96.26, 2.95, 2.27);
INSERT INTO reviews VALUES (86609, 3146520, 47120, 'As I entered my first public lobby, I was warmly greeted with an invitation to a wedding ceremony. The proceedings were held on a private island, with drinks, snacks, and most importantly bait provided! Upon my arrival I was eagerly informed that, as part of the celebration, additional marriage proceedings would be offered upon request. \n\nThe host also informed me that a suitable marriage partner would be provided to me free of charge! Thus I quickly snatched up this fabulous opportunity, and I ', 'If you love Animal Crossing, and wanna enjoy a fun cozy fishing experience with homies, this game is amazing for that. It also has a good grind if you''re into that sorta thing too.\n\nHowever, given security risks I cannot recommend this game (for now). I played with a friend earlier today, in a private code-only lobby, and a random guy joined us. We immediately disbanded the room, after hearing rumours of hackers on the game, we didn''t want to risk any data getting corrupted, or other malicious a', 'Overwhelmingly Positive', 97.97, 29.38, 24.33);
INSERT INTO reviews VALUES (86648, 3147430, 540, 'Very solid incremental game! Very little idle time, there are A LOT of different spells and abilities that provide a lot of freedom and replay value. Wanna go skeletons? Sure. Dragons? Sure. Poison build? Sure. If you feel like you hit a wall, you simply need to experiment with all the different unit combinations.\r\n\r\nThat said, you are looking at a 4-8 hour play depending on your efficiency. \r\n\r\nWord to the developer: this game is absolutely begging for a prestige system at 100. Heck, even if yo', 'It''s not really an incremental/upgrade game. The game has predefined builds that you need to change to every time you pass certain milestones. Every time you pass a certain milestone, you respec so you can make the new build. There''s no room for creativity in the builds. Perfectly building what the developer wants you to build grants you slow progression through the game.', 'Very Positive', 88.52, 13.90, 1.30);
INSERT INTO reviews VALUES (86743, 3149370, 503, 'i built some beautiful decks, the rogue light elements were annoying but game had a solid foundation.', 'Honestly after goblin america''s demo I was expecting a surreal departure from the concept at some point, even as a final gag.  Freedom isn''t free and a hard throw into a completely different type of game, or if gil was being lazy, maybe right into the goblin america demo with no warning or explanation. Or the weird skull nail that was poking fun at inscryption to kick off some absurdly pointless ARG that gives you some code to put into the game to unlock golden planks that do nothing but say "wi', 'Overwhelmingly Positive', 96.62, 1.13, 1.35);
INSERT INTO reviews VALUES (86793, 3150440, 613, 'CaseOH made me wanna play this game so bad after watched his stream on twitch. I enjoy playing this game and having a lot of fun. BEST RECOMMEND !!!!!!!!!', 'This game was great and a lot of fun. All of that changed when I unlocked laundry delivery service. I have gotten 2 out of 10 deliveries done to complete the next laundry unlocks/upgrades. I''ve received no more phone calls for laundry delivery, therefore, I cannot progress as it''s required to unlock the next level. The game is pointless to play now. I''ve read on steam forum others have also had this issue with no solution. I''ve reached out via email to the devs through steam support. \r\nDon''t was', 'Very Positive', 88.25, 14.77, 10.55);
INSERT INTO reviews VALUES (86838, 3151380, 123, 'It''s like the best part of the Sims. I''m sad that I don''t get to build a small space, but I am in love with decorating the small space. The apartments I''ve decorated so far are so cute and eclectic. If this is early access, I am SUPER excited for what is to come!! 11/10 would decorate again', 'nice game cute and cozy just like furnish master but its lack of many options places and decoration stuff. maybe after many updates and new features i will think again.', 'Overwhelmingly Positive', 95.93, 1.95, 0.15);
INSERT INTO reviews VALUES (86990, 3155430, 133, 'The fifth and the longest in the series which now has a theme of Vikings. The Find All series is all about looking for objects but unlike other HOGs here we can always look for 3 specific type of objects and they are displayed at the bottom of the screen. Once one of them has been exhausted a pop-up shows 3 additional items we can choose from to be added to the below pool.\n\nAs you keep going through the level you see certain items stand out. You will soon realise that they can also be added late', 'I am a big fan of the Find All series but this installment left me disappointed. Call me sensitive, but watching a bunch of adorable cartoon people crying and fleeing their homes is a little upsetting. I come to these games for cozy relaxation and I just could not find that here. I thought it would be handled similarly to the Middle Ages or Magic titles in the series: no crusades or witch hunts depicted there, just charming scenes that fit the aesthetic. If this is the direction the series is go', 'Very Positive', 94.74, 4.02, 3.38);
INSERT INTO reviews VALUES (87044, 3156770, 6220, 'imagine the gunplay of Destiny but none of the intense shame of being a Destiny player', 'Honestly... Not even remotely worthy of the hype this game has been getting. It has a whole 3 maps to play, very limited upgrade system, and the game goes from laughably easy at the start, to borderline impossible by the end.\r\n\r\nI think some of this can be blamed on the extremely unfinished design of the game, half the equipment is missing, gun abilities can be upgraded but not the gun stats making enemies WAY too hard at the end of the game, everything is spongy as HELL. Ammo is way way way WAY', 'Very Positive', 92.70, 10.70, 13.55);
INSERT INTO reviews VALUES (87097, 3158270, 132, 'The game is so realistic, women avoid talking to me here too', 'Fun game until you notice your stats gets worse and worse even if you go home drink espresso and go back to training. You either stay stuck at the same point or lose stats, and 10 different laguages at the same time, one message is japanese one is germen and the next you have no idea. When you start chatting with someone they suddenly send the same message 20 times and youre stuck watching it cant even go out of your phone. The demo was 10 times better then this its a miracle they made it worse.', 'Very Positive', 81.06, 4.75, 2.85);
INSERT INTO reviews VALUES (87137, 3159330, 9992, 'Jin Sakai mastered the way of the ghost, but Naoe was born in the shadows.\n\nHey Ubisoft! If you actually want people to buy your forgettable 7/10 games, then drop the Ubisoft Connect bullcrap and stop forcing us to install it. Nobody wants this garbage clogging up their PC. Do better.\n\n – From the entire community.', 'Microtransaction in single player game never cease to pisses me off.', 'Very Positive', 81.37, 10.13, 94.80);
INSERT INTO reviews VALUES (87145, 3159570, 234, 'Played a whooole bunch of the Demo, I''m so excited for this game to come out!\n\nIt''s like a mix of Hades and Animal Crossing. The combat is right up there with all the best ARPGs and it nails the cozy aspect as well! Super vibrant game, the music is amazing, I could go on forever, but you should just buy the game and check it out yourself!', 'I refunded this game when my 1 player "offline" game crashed at the exact same second my internet connection died.\n\nI''m not the sharpest person in the world, but even I can figure out that''s no bueno.', 'Very Positive', 86.75, 30.58, 2.40);
INSERT INTO reviews VALUES (87203, 3167550, 620, 'A cozy little desktop distraction. You collect animals and creatures, unlock weird variants like ghosts, zombies and rainbow corgis, and occasionally clean up their poop. That’s pretty much it.\n\nGameplay is semi-idle—perfect for having in the background while pretending to work. No story, just vibes. Music’s chill, everything runs smooth, and unlocking all the creatures was oddly satisfying.\n\nNo bugs, no stress, no regrets.\n\n8/10 – Would babysit pixel animals again.', 'Unlike rusty''s, there''s seemingly no real goal and unlocking other animals isn''t rewarding. it''s missing that chemical x that makes me want to play it.', 'Very Positive', 93.39, 174.27, 0.87);
INSERT INTO reviews VALUES (87204, 3167970, 109, 'Absolutely LOVE this game! Fun easter eggs and the attention to detail is incredible! Genuinely challenging game that rewards synergy and skill, really feels like a grindy retro roguelike with an engaging story and multiple unique gameplay mechanics! Can’t recommend enough!!!', 'It''s too much like Slay the Spire without adding anything different or compelling enough. It just made me want to play more Slay the Spire. This game is more shallow; the card synergies are a little too obvious and set-in-stone, to the point that too many cards outside of your "build" are useless.\n\nThe retro graphics are cool, but they''re only cool in screenshots. The game has too much visual noise when you make a decision or go to a new screen. Things like multiple UI elements flashing and popp', 'Very Positive', 89.91, 5.73, 1.02);
INSERT INTO reviews VALUES (87206, 3168260, 153, 'The game about gladiatorial fights with the possibility of a variety of leveling as the game there were various things as the game is really hard', 'good game, good concept etc. played the original for several hundred of hours before. but the reforged version inst any better. All the frustration from the original still exist, and more. its not like this game is new too, they have lots of excuses and time and still not much progress other than the equally poorly scripted DLCs. \n\nThe thing about this game is terrible loading time, not polished, everything feels so, clunky. and god the file size for this kind of game is ridiculous. its probably', 'Mixed', 68.63, 3.07, 0.75);
INSERT INTO reviews VALUES (87207, 3168600, 479, 'It''s good. I think that playing pubs kind of sucks though because half the players are either 3 years old, don''t talk, or 3 years old and don''t talk.', 'Fun game but literally got banned in the first hour for voice chat. Yes i probably said something foul but keep in mind I was in a private game with friends. On top of this, you have to check so many guidelines before you play. (The most I have ever seen in a game). I am refunding simply because I was in a private game and they tracked my voice. Rubs me wrong.', 'Mixed', 57.83, 0.22, 1.18);
INSERT INTO reviews VALUES (87225, 3170410, 136, 'Over 25 years later, the Mighty Bombers are back to reign supreme as global soccer/futbol overlords. (Even Russia''s Cagey Bees aren''t gonna stop me)\r\n\r\nGame is running smoothly, thank you Mega Cat Studios for bringing this to Steam!', 'Pros and Pro teams are no longer in the game. I understand that they did that for licensing reasons, but it''s disappointing. More disappointing to me is that the interface is more akin to Backyard Baseball than the original software. I liked the original interface better, both aesthetically and that it was significantly different from Backyard Baseball.', 'Overwhelmingly Positive', 97.06, 12.60, 0.25);
INSERT INTO reviews VALUES (87226, 3170540, 1599, 'This is Unapologeticly a Copy of the Orginal game PRO TIP: Don''t press the Print Icon if you are connected to a Printer, It will literally Print a copy of whatever is on the screen. 10/10 would print again', 'I accidentally hit print on the player stats and it used more money in ink than the game costed. 10/10 Would print again.', 'Overwhelmingly Positive', 97.37, 2.08, 19.55);
INSERT INTO reviews VALUES (87236, 3172310, 171, 'A friend of mine recommended buying Mad Max. I was not deceived, the game is really interesting.', 'Man. Sooooooooooo much dialogue back and forth and back and forth nonsensical conversations with almost zero consequences - and very little actual gameplay. Just click, click, click, click, click, click, click, forever........ "Thrones" was so much better, guys. This one is a miss for sure.', 'Mostly Positive', 70.76, 2.10, 1.22);
INSERT INTO reviews VALUES (87243, 3173560, 275, 'I made a cup of cancer, felt bad for her, then gave her a cup of cure and she was all better. 10/10 amazing game.', 'Art-Thievery example: https://x.com/Cosette_kesaite/status/1871096639542473120', 'Very Positive', 81.45, 7.65, 2.92);
INSERT INTO reviews VALUES (87256, 3176060, 510, 'Absolutely loving the game so far! Just hoping for more content down the line.\nfor the developer : keep it up bro u doing a great job <3', 'no sex with hot tall lady', 'Very Positive', 86.47, 7.93, 3.80);
INSERT INTO reviews VALUES (87318, 3177970, 151, 'It''s about ten hours of content to beat the game and complete the 30-floor challenge mode, or a few hours less if you land on a busted build.\n\nThe translation''s kinda jank so there were times I was wondering what various mechanics or powers actually did. The fact that all of your brains are active simultaneously should really be explained better at the beginning.\n\nOverall, pretty fun while it lasts if you like experimenting with weird game interactions and going "I wonder if this works?" But onc', 'I would be weary of supporting this developer now.\n\nTheir other game was allegedly pulled from Steam because of an issue with their publisher. They launched the game again under a different name and listing and will only compensate Steam keys to those who emailed them within a month of posting their news article on the previous game. They only provide Epic Game Store keys now.\n\nThey''ve stated that it doesn''t matter, as the game won''t get any updates. \n\nIt''s safe to say that both projects are aba', 'Mostly Positive', 78.81, 7.88, 1.00);
INSERT INTO reviews VALUES (87321, 3178350, 532, 'A fun roguelite with a blueprint similar to the bullet heaven genre, but with active combat. Features your usual Warriors techniques - normal attacks, charge attacks, musou attacks, and dodging. Difficulty starts off easy and gradually increases during your run. Without significant unlocks, the game becomes quite difficult in boss encounters, but feels very rewarding when overcoming the odds. I''d say I get about one unlock per run, and there are ~100 characters to unlock along with with various ', 'Musou + Roguelike is a cool idea, but the execution is cheap and lazy... the empty levels and the lack of enemy and boss variety makes it boring even after a few runs. And the difficulty seems entirely reliant on meta-progress. You''ll die quickly past the 1st boss, not because you''re playing bad or have a bad build, but because you need to grind the meta progression.\n\nHonestly, it''s so barebones it feels like a side-mode from an Orochi game. Just grab Warriors Orochi 3 and play the Gauntlet mode', 'Very Positive', 89.47, 35.50, 1.23);
INSERT INTO reviews VALUES (87364, 3179730, 240, 'I played the demo way too much and eagerly awaited full release.  The game builds on the promise of the demo - more nights, many more cards, many more room types.  Modifiers to change-up runs with added difficulty.  And there''s still a lot of space for expansion later.\r\n\r\nIf you haven''t played it - try the demo, but know that the full game is much richer, and more satisfying.\r\n\r\nThere''s nothing quite like coming to the end of a long day at work and expanding the mansion into an ever bigger, hung', 'This is a very hard review to write. I''ve been following the development of this game for a while - I played the demo and shared it with a large number of friends. The devs for this game are very involved with the community, and have taken feedback well. In its current state, I cannot recommend it at the official price ($20), but I am optimistic that the devs will continue to build on it. As it stands, Deck of Haunts is a unique, fun, and novel experience, but it ultimately comes up shallow.\n\nDe', 'Very Positive', 85.42, 47.98, 20.83);
INSERT INTO reviews VALUES (87389, 3180240, 143, 'I think what makes the value for this game is the documentary rather than the games it includes, because there are many other Tetris games out there that can give you way more bang for your buck like PPT or connected, so if you''re only here for that, it''s probably a game you''ll want to wait for a sale.', 'It pains me to leave a negative review for a Tetris game, but this particular collection is way overpriced for the lack of variety and amount of redundancy you get: Five iterations of the original Tetris (With the Electronika 60 and Spectrum Holobyte DOS versions being the only interesting ones from a historical lens), three iterations of Hatris, and five iterations of Bombliss (which somehow manages to omit Tetris Blast, which is arguably the best iteration of the included handheld Bombliss ver', 'Mostly Positive', 72.73, 15.32, 1.82);
INSERT INTO reviews VALUES (87542, 3184110, 471, 'I am marking this as a yes, because Steam really doesn''t have a ''it depends'' button. Widget Inc is a reverse idle game. At the start you make your little factory and watch the numbers go brrr... but past tier 9 you have maxed out the upgrades for your lower tiers, so they never get faster. But the resources from them continue to be needed in ever increasing amounts, and you need to spend more to make more factories for those resources each time... so instead of the game getting faster as time pa', 'This is a neutral-leaning-negative review.\n\nI got to tier 3 in just under an hour, and started to realize that I was going to be doing the same thing for 3 more hours and then be done with it. With other automation / incremental games, normally the next tier or step comes with some new complication. In Factorio, oil processing adds new fluid handling, cracking, and fluid recipes to think about. In Cookie Clicker, you ascend and find new upgrades that change the way you play. This one is the same', 'Very Positive', 85.14, 63.48, 1.10);
INSERT INTO reviews VALUES (87669, 3187700, 109, 'All aboard the cat tram! 🚋🐾 It’s like public transit, but with more meows and less stress. Lack''s purpose and substantial gameplay, it’s worth trying if you appreciate supporting hand drawn games.\r\n\r\nFollow my Curator page for more purr-fect picks and stress-free adventures:\r\nhttps://store.steampowered.com/curator/42602807-Osiris-Reviews/', '', 'Overwhelmingly Positive', 100.00, 0.42, 0.00);
INSERT INTO reviews VALUES (87781, 3191030, 8688, 'I scored a multiplier so high on Round 103 that the game described it as "You broke the game". Later, on Round 247, I scored so high that it did actually break the game and the application crashed. Tremendous game.', 'an addicting gameplay loop that''s too often ruined by mediocre item and perk balance, resulting in a majority of runs either losing with a mishmash of useless and non-synergizing loadouts, or winning on cruise control at 9999x multiplier without even aiming. uninteresting challenges. lack of saving of any kind means that you''ll lose your entire run if the game crashes, which has happened three times so far in five hours of gameplay.\r\n\r\nthe framework is there, and the aesthetic is a lot of fun, b', 'Overwhelmingly Positive', 97.59, 26.28, 14.08);
INSERT INTO reviews VALUES (87782, 3191050, 1173, 'most people don’t realize this but the reason it’s called brazilian drug dealer 3 is not because it’s the third game but because you play as the third drug dealer to ever exist in brazil', 'this does not accurately represent bulgaria - this is because it doesn''t intend to', 'Overwhelmingly Positive', 98.64, 6.97, 6.18);
INSERT INTO reviews VALUES (87907, 3193840, 163, 'Actually kind of fun, AI need a ton of work but its still better then Warzone', 'Even at the discounted price of $13.49 from $15.00, I really struggled to find the value in the game that I was expecting for my money spent. The concept was interesting, as was the theme; I thought I''d give it a shot.\n\nThe first thing I noticed when loading into a match, was how ear shattering the silence was. No background noise or ambiance to even attempt immersion, and this can be said for the AI enemies on the map as well. No kind of informative audio from the AI, other than their footsteps', 'Mixed', 58.90, 55.87, 1.15);
INSERT INTO reviews VALUES (87931, 3194550, 151, 'I''m pretty neutral on this. It''s cute, but I do think it needs work. \nThe camera movement is super slow and I wish the items had descriptions. I also wish pandas actually visited or at least dropped their laundry off. I truly might be asking too much for an idle game though.', 'This is a cute game that I excitedly bought at full price when it launched (always a mistake) because I loved the art style so much. And it IS cute, but that''s about it, I think I expected that there would be some kind of small story or progression that happened as you gained money, perhaps recurring client characters with some dialog, or a landlord who owns the lot. Maybe the pandas who work the laundromat have different personalities or designs and you could unlock them. Alas, no, just more co', 'Very Positive', 88.74, 24.97, 66.17);
INSERT INTO reviews VALUES (87981, 3195790, 2496, 'It''s called white knuckle because the game is so good you white all over your knuckles', 'Great game but the "water" rises WAY TOO FAST. Especially in the second interlude! Also everything past that does way too much of a jump in difficulty. I get that it’s supposed to be a hard game but dying because a turret shot you a few times right at the end and having to restart EVERYTHING is just not fun. There are also way too few Upgrades to get in a run, especially if you get unlucky and only find temporary ones at the one midpoint. It’s really sad that this absurd jump in difficulty makes', 'Overwhelmingly Positive', 98.60, 40.47, 14.88);
INSERT INTO reviews VALUES (88096, 3198680, 155, 'Finished the game, 10/10 (oh wait my inventory is public so you can check my achievements *gulp*)', 'for some reason i have not been earning any money though i have finished some areas been to level 18 in some areas plus im intermedate .when the bug is fixed ill change it to a good reveiw', 'Overwhelmingly Positive', 95.48, 4.13, 8.80);
INSERT INTO reviews VALUES (88306, 3204250, 672, 'Prodüktörün yakışıklılığı sebebiyle tüm ekibin dikkati dağılmış ve oyunun yapım süresi çok uzamış diye duydum. Bu büyük soruna rağmen bu kadar tatlı bir iş çıkması gerçekten takdire şayan. Muhabbet kuşum, yolda olan güncellemelerin oldukça iyi olduğunu söyledi.\n\nMuhabbet kuşum genelde doğru söyler, ben ona güveniyorum. Muhabbet kuşumu bir hava limanında kaybetseydim bu oyunda geri bulmak isterdim. Umarım muhabbet kuşumu kara borsada satmazlar.', 'This game is pretty fun, in a "free browser flash game you play on your lunch break" kind of way... but honestly couldn''t keep me interested and I''m not sure I''ll want to play more.\r\nI don''t like how upgrades are objects you have to keep on your desk, leaving less room for actual lost items.\r\nI am VERY displeased to see missing features advertised in-game as "upcoming free DLC"... This game is in reality in Early Access and SHAME on the dev(s) for trying to pass this off as a fully finished game', 'Mostly Positive', 72.02, 2.05, 0.63);
INSERT INTO reviews VALUES (88343, 3205080, 1186, 'very good game, kinda short tho. one of the best jumpscare of this game was finding out that the dev likes lil girls', 'good game, mega jaw drop. shame the creator was doing vore rp with a 14 year old. dont support this game financially.\n\n\nhttps://docs.google.com/document/d/e/2PACX-1vT5CuvEurnGVCm12AW5LzXfCnPnxX8hyrThG6NkYGsgV-JjDsZRGGmwKWnIOh48E2nS12sp0pXSQjVe/pub', 'Very Positive', 82.29, 1.70, 0.42);
INSERT INTO reviews VALUES (88483, 3207880, 126, 'I bought this today, and even if it wasn''t on sale (which it was) it is STILL extremely affordable and worth every penny. Very relaxing incremental game done in a retro style with soothing sci-fi music that seems to flow as well as the game does. I spent 4 HOURS playing this and didn''t even notice the time, like at all. At first I didn''t think I was going to like it, but after the first half hour (I''m guessing) I got lost in space!\nHighly recommend.', 'Debian 12 user here. Both the Steam Linux runtime and legacy runtime don''t allow the game to launch. I tried a couple Proton versions and it launches but crashes after overriding the ship speed limit.', 'Very Positive', 94.44, 18.22, 0.23);
INSERT INTO reviews VALUES (88633, 3211680, 120, 'Run a tobacco shop, beat up thieves, and balance your budget—all while keeping customers happy (or at least pretending to). Perfect for players who think retail therapy means running a business.🛒\n\nFollow my Curator page for more chaotic business ventures and questionable decisions:\nhttps://store.steampowered.com/curator/42602807-Osiris-Reviews/', 'the game introduces nothing new to the genre while other simulators implement features better.\n\nnot worth it at this price point\n\nkind and invested dev though, future projects could be promising', 'Overwhelmingly Positive', 95.83, 1.75, 0.37);
INSERT INTO reviews VALUES (88669, 3212530, 277, 'Literature like this would normally be incorporated into some sort of High School English class, but the steam store is an acceptable alternative.', 'С-Tier Millennial writing', 'Overwhelmingly Positive', 99.64, 4.22, 1.82);
INSERT INTO reviews VALUES (88719, 3213850, 190, 'I have a recommendation, add steam workshop and negative reviews will be resolved by the community itself.', 'If you came for the character/room customisation, you will be sorely disappointed. Only certain parts of items are colourable, and even when coloured, because of the lighting and shading, the colours look different on every item, so you can''t really create any sense of style between items, whether it''s clothing or furniture. This was a massive part of the game for me, so I am quite sad to say I will be refunding this.', 'Very Positive', 92.11, 59.53, 1.05);
INSERT INTO reviews VALUES (88772, 3215170, 268, '>looking for a typing game\n>ask steam if Typing of The Net is reddit or 4chan\n>steam doesnt understand |>pull out illustrated diagram explaing what is reddit or 4chan\n>she laughs and says “it’s a good typing game”\n>buy the game\n>its reddit', 'honestly, this should be free. it''s cool that it comes with an entire platformer but the actual typing game I paid for was about 8 minutes long. i was actually looking forward to this because i like typing, but there''s only 3 very short and easy stages. sorry ame', 'Mostly Positive', 73.51, 0.97, 0.57);
INSERT INTO reviews VALUES (88798, 3215660, 211, 'Well. I don''t know. Visually, it''s a treat. Gameplay-wise, tank controls are tankier than the tankiest PS1 tank controls, which is... pretty unfun. This style of movement worked for the older survival horror games because enemies were slow and you had time to skirt around them. The enemy in this game, however, is extremely fast and kills you instantly. Compounding this issue, you only have 3 lives. Egh\n\nI''m not sure how much longer games can get away with a cool retro aesthetic and good sound de', 'When a game is made, it should be made for everybody, if it is advertised and released on every platform available. This game clearly stated that controller provides best experience. I do not have controller and have no intention of buying one. If you release it for mandated controller or make the control of this game such that, a controller is obligatory for smooth game experience, do not advertise it to players like us. I played it for 10 minutes and the control of this game is so insufferable', 'Overwhelmingly Positive', 96.21, 1.58, 0.35);
INSERT INTO reviews VALUES (89230, 3226530, 911, 'Really solid and charming tower defence game. Like Rogue Tower but way more polished and fleshed out, with a lot of variation between factions, commanders, buildings and doctrines.  I spent a huge amount of time on the demo, and the full game is even more expansive and fun than I''d hoped with a lot of different replayability. If you''re on the fence, try the demo and you''ll likely end up wanting more. A lot more. \n\nIt is currently tickling a part of my brain that no other tower defence has in a l', 'Fun base for a game. But iam missing any kind of stats. Also the screenshots in the steamstore show a lot more towers then u will ever build. It also lacks depth.\n\nBUT, iam looking forward for future updates. I think there is a lot potential.', 'Very Positive', 85.84, 41.27, 18.65);
INSERT INTO reviews VALUES (89241, 3226750, 590, 'It''s a good active and short incremental game, scratches the itch left by To The Core and Nodebuster.\n\nWouldn''t put it on the same level as those two games, primarily because the dopamine rush isn''t quite as addictive, and the upgrades aren''t as bombastic as those games. \n\nThe game starts to get cooler around the point where you unlock all the mines, but then it''s a bit of grind to unlock the cooler effects and grind to the end. \n\nStill, fun incremental game, took about 3 hours with a further 20', 'I don''t love to give a thumbs down, especially because the game is priced at 99 cents. But I did not jive with this game. I love the genre, and hope this dev continues making games, but this one felt very shallow. The tech tree was almost all repeats of just "more damage, more speed". I want a tech tree with interesting upgrades, not filler and fluff.\n\nThe interesting upgrades that were sprinkled throughout the tree weren''t even that interesting unfortunately. A few different types of weapons, a', 'Very Positive', 93.22, 3.58, 0.68);
INSERT INTO reviews VALUES (89292, 3228180, 1107, 'Short, but fun. Completely lacking in automation though, so that tag is a bit misleading, but otherwise nice.', 'Doesn''t progress past doing stuff manually, which quickly makes the game really repetitive, as you can''t focus on making new stuff without having to manually create all the previous ingredients.', 'Very Positive', 91.96, 4.23, 3.23);
INSERT INTO reviews VALUES (89306, 3228590, 2198, 'This rouge like is well made and fun to play HOWEVER...\nThe devs have a history of pumping out a game, making money off of it, and never updating said game. Keep this in mind before buying. In its current state its a lot of fun! Hopefully more content is added in the future.', 'While the game does play well and was a bit of fun. I ended up being Zone 1 in just over a hour(there''s 3 zones) it makes me question how much you can really get out of the game.\n\nMy other major concern is the history of the developer abandoning previous titles. Mainly Tribes 3 which released in EA in April of 2024 and has not had a update since June of 2024. Not a fan of companies who don''t finish previous titles.\n\nRefunded for the time being until the developer proves they are going to fully r', 'Very Positive', 90.99, 14.25, 1.32);
INSERT INTO reviews VALUES (89333, 3229170, 267, 'Art is fun to look at, the "plot" is very tongue in cheek. It''s $4, you''ve got nothing better to do than squeeze the egg. Also, nothing will ever describe the dopamine you get from a 99% squeeze. like, holy shit dude.', 'While the price point for the game is more than fair, I just don''t find the central (and only) gameplay mechanic of guessing a random timer value between ~3 and ~10 seconds fun or engaging, and often find it frustrating. The optimal way to play ends up being just squeezing for 3 to 4 seconds to avoid ever cracking the egg and losing your streak. Still glad to get some FLOOR BABA production but overall would not recommend this as a good use of free time.', 'Overwhelmingly Positive', 99.25, 2.65, 1.27);
INSERT INTO reviews VALUES (89445, 3232040, 160, 'A good game with great potential, there are certainly problems, but in general norms', 'bro im sorry but wtf is this??? Do u even adecvatinng ? ???', 'Very Positive', 86.25, 3.68, 1.88);
INSERT INTO reviews VALUES (89488, 3233390, 101, 'In a world of NSFW games with NO passion in them, there''s Lilith''s lair- the radiant beacon of hope for NSFW games moving forward. \n\nIt''s good, it''s GOOD!! Like it''s SOO GOOD WTF????! Well, if these oddball kinks are your kinks anyway.', 'eh, not worth the 6 dollars, no interactivity, this just seems like his games he releases to the public, but with a little more extended content, I think he''s starting to think a little too much of himself now as a dev, and jacking his prices up since his last game was successful, one good growth sequence when she turns mini giantess, but thats about it, he doesnt even show the "stealing" of size and all step by step with the female vampiress, she just POOF is massive at the end everytime you en', 'Overwhelmingly Positive', 97.03, 2.65, 1.38);
INSERT INTO reviews VALUES (89671, 3238510, 103, 'a game like this lives or dies by its character writing and art direction and those are both very good here. the cast as a whole and each individual character is engaging and nuanced. I''ve only done one playthrough (rode off with Eight which I''m certain is the best possible ending) but I absolutely want to see more of what makes Stefan tick in a future playthrough. my one regret is that they only had the budget to art up the core cast; I really would''ve liked to have seen some of the other estab', 'I am so disappointed by the lack of Lilia''s route. She is by far the most interesting in this game and you have fake options to help her but it never works. She always gets executed while some worse get their routes. If Lilia''s DLC gets released I will definitely buy it but I don''t like the story in its current form', 'Overwhelmingly Positive', 100.00, 2.58, 4.68);
INSERT INTO reviews VALUES (89675, 3238670, 1281, 'I''d say its worth the 10$ \n\nits got all the cool things a dumb girl like me crave such as:\n\n-number go up\n\nits perfect.', 'New terms include non-ownership and arbitration. Huge red flag. Cannot recommend as a result.\r\nwas a great game now I''m uninstalling it for the Garbage EULA.\r\nthanks for ruining something wonderful\r\n', 'Very Positive', 92.12, 50.30, 37.45);
INSERT INTO reviews VALUES (89733, 3240220, 21735, 'before i played this game i was lazy, suicidal, sad, and didnt do much aside sleeping. Nothing has changed but game is good.', '"The GTA Online profile associated with this Rockstar Games account is not eligible for migration at this time." If you think i''m throwing away nearly 700 hours of gameplay on one character so that you can make a few more bucks off me, then you can lick my anal orifice clean.\n\nThis is an objective downgrade from the "old" version. Gonna pretend this was never released & continue to enjoy Legacy version until the new game comes out when I''m 60.', 'Mixed', 65.92, 0.48, 0.47);
INSERT INTO reviews VALUES (89788, 3241660, 75817, 'This game is solid. I don''t know what possessed the developer to use an emoji as the main banner/logo for the game... It makes it look like a scam or a terrible greenlight game that was made for a joke but it''s actually better than other extraction horror games\n\nEdit: The banner has changed since I wrote that lol... Very fun game indeed', 'Not really my cup of tea. Mechanically it''s mostly playing hide and seek + scavenger hunt. Better with friends, but too many games these days create bland, repetitive environments attempting to apply the Lethal Company formula, and ultimately rely too heavily on the camaraderie you bring to facilitate an interesting game.', 'Overwhelmingly Positive', 96.75, 32.30, 2.83);
INSERT INTO reviews VALUES (89829, 3242950, 194, 'Honestly, I am pleased with this game so far. I''m around 10 hours in and have been having A lot of fun :-D  \n\nIgnore all the idiots who are complaining about power and whatever else. I tried to reply to their reviews but they disabled comments. LOL\n\nThey haven''t advanced far enough to even grasp the fact that there are upgrades and techs and things you can do in the future to alleviate all the issues they bring up. I wont spoil it, but the game leaves these techs and upgrades for you to discover', 'I tried to love this game, as much as I love Satisfactory or Factorio. But there are some design decisions which rendered my factory very soon into a big mess. For example you need to click on the source and the destination to set a route for the materials from machine to machine. This soon produces spaghetti where you hardly can see, from where to where something flows. It is also not possible to see what a smelter produces, without hovering over it. I wanted to build something, but did not kno', 'Very Positive', 91.24, 11.97, 1.73);
INSERT INTO reviews VALUES (89830, 3243190, 2176, 'Gameplay Tip: you could fix her, but why would you?\n\nRealworld Tip: your tax money pays for all police equipment, you own the handguns that officers carry', 'Incredible game, would be a 10/10 if they didn''t forget to add one crucial detail: SHE DOESN''T GET OILED UP BUTT-BOOTY NAKED AND START BUSTING IT DOWN SEXUAL STYLE!!!!! WHYYYYYY!!!!!! PLEASE!!!! I BEG YOU!!!!!', 'Overwhelmingly Positive', 97.52, 6.08, 4.93);
INSERT INTO reviews VALUES (89865, 3244210, 240, 'Chonkers is a very cute cat game where you have to buy cards and complete all collections: normal, chonkers, space and space chonkers.  The ambient is very cozy and the pixels graphics are nice. I highly recommend it!!! 🐈💗', 'This idle game is boring, slow and a very obvious cash grab. Have had it running for days now and literally haven''t earned anywhere near enough money to open up anything interesting other than the default room and basic items. Disappointing.', 'Very Positive', 80.83, 60.97, 83.12);
INSERT INTO reviews VALUES (89866, 3244220, 8608, 'A friend told me there wasn''t enough to this game, but it actually goes a lot deeper than he thought....', 'A fun cute game completely ruined by its "endgame". An experience all about digging a hole suddenly taking away every tool you have to make a jarring, shoehorned and badly made stealth section work sure was a choice...', 'Very Positive', 90.86, 2.97, 10.10);
INSERT INTO reviews VALUES (89879, 3244640, 169, 'I respect the developers for their attention to small details. For example, in the video, one of the dudes wipes sweat from his forehead out of fatigue. I feel sorry for him for two reasons: the guy worked hard, was very tired and sweaty, but he is incredibly stupid because he wiped the sweat from his forehead without taking off his motorcycle helmet.', 'Don''t buy this scam. Almost nothing works : controller doesn''t work , waves are infinite , airdrop and half the keybinds are unusable , only support WASD , scenes are gif and are laughtably bad , the gamplay is straight out of a mobile game from 10years ago.\nPure scam like alll their games', 'Mixed', 69.82, 1.77, 0.60);
INSERT INTO reviews VALUES (90208, 3253630, 113, 'I fully respect everyone''s opinion. My personal opinion is that this game far surpasses the first, and I liked it even more. I played it co-op with a friend and we got 100%. To properly enjoy it, you have to read and understand how to get the most out of its mechanics. Weapon synthesis is great if you know how to use it, but if not, you''ll just feel like you have a lot of duplicate weapons filling up your inventory. However, even if you don''t want to use sub-weapons and rely only on basic weapon', 'How many people do you think play a Galgun game do not know what "Haaaai! Maou-sama daisuke!" means? Who do you think you are fooling pretending it translates to "Oh my gawd! I just love you to bits, sire darling?"\n\nYou guys keep passing off this crap as translation, and I will keep localizing "Recommended" in my reviews with just as much respect for accuracy.', 'Mostly Positive', 71.68, 19.22, 19.78);
INSERT INTO reviews VALUES (90272, 3255380, 298, 'It plays on steam deck, which is more than i can say about Grandia. Gungho should fix that...', 'Honestly these games are great but the QOL in the remaster just does not warrant the $50 price tag. I personally believe the new VAs feel flat and tonally distant from the originals. Graphically the remastered mode feels like they placed a filter over everything giving it too much smoothing, you can see it more in the character profiles. \n\nOverall the games themselves are great but this remaster feels unnecessary if you already have the originals ready to play via emulation.', 'Very Positive', 90.60, 31.60, 1.25);
INSERT INTO reviews VALUES (90370, 3258290, 241, 'The game has a wonderfully dark story in comparison to other horse games, the scenery is stunning and the finished cutscenes are very well made, the characters have a lot of expressions and most of the dialogue feels natural, the soundtrack is absolutely amazing as well.\nWhile there are some mild connection issues (I mean duh, the game came out less than 2 hours ago) it''s running perfectly on my system with the highest graphic settings.\nI just hope there will be a cutscene gallery for later rewa', 'Possibly one of the most promising equestrian-centred games I''ve seen in a while. That being said, it isn''t without it''s issues and I can''t recommend this game in its current state, but updates and patches have been a regular occurrence.\n\nA £21 fee for very early access with almost game-breaking lags is insane: clipping into ''locked'' buildings without escape, running races and being teleported backwards from what I''ve currently experienced. Although I enjoy the realistic graphics and horse mecha', 'Mostly Positive', 75.52, 11.85, 14.32);
INSERT INTO reviews VALUES (90390, 3259040, 115, 'I’m about to start working in an office and decided to practice with a game first.\n\nI picked the first thing that came up in the search results. And it really surprised me. I had no idea there’d be a piano in the office.\n\nOther than that, everything’s great—interesting story, beautiful graphics, and of course, realistic dialogue. I can’t wait for my first workday to begin.\n\nIf you read the review and liked it, don''t forget to give it a thumbsup;)The further - The better♥️', 'Requested a refund. Game doesn''t play past trying to talk to Angela. Needs a fix. Also some minor adjustments. When tweaking the settings I realize they always revert to whatever they were at default. So having to constantly adjust mouse sensitivity, audio etc. was a bit annoying. Overall curious as to what this game can manage long term once the issue is resolved. Will adjust review at a later date if it''s improved. Can''t recommend just yet.', 'Very Positive', 82.61, 3.35, 0.37);
INSERT INTO reviews VALUES (90405, 3259470, 1812, 'Don''t be shy, Flipline Studios. Those remaining Papa''s games deserve to be released on Steam and everyone''s gonna love them.\nCannot wait to play such classics and new ones like Cakeria, Sushiria, Wingeria, Donuteria, FPShooteria and Diarrhea.', 'first negative review (Anyways the game is a banger, you should play it)', 'Overwhelmingly Positive', 98.57, 40.92, 2.43);
INSERT INTO reviews VALUES (90542, 3263320, 419, 'Be very careful on who you play this with. Friendship is like glass, it can break due to this game.', 'There needs to be an option to switch servers, I bought this game expecting to have fun with my friend but we can not play together because I''m american and he''s european.', 'Mostly Positive', 78.28, 4.58, 3.38);
INSERT INTO reviews VALUES (90626, 3265250, 878, 'I actually think its pretty good tbh. For me it has run fine, visuals look great. I was getting ready to refund it but after an hour im not thinking about doing that kind of want to see where it goes and its fun enough. Seems interesting.', 'i truly wonder who playtested this game before release but they need to be fired.\nstory seems pretty okay for the 1 hour i played but some stupid things make me feel like the game was not tested at all before release for example when in a vehicle and driving up a hill your camera goes down almost into the floor.\n\n\nTLDR: feels like a rushed release with some trivial issues not worth $59.99 right now', 'Mixed', 45.67, 3.55, 1.32);
INSERT INTO reviews VALUES (90834, 3272300, 1143, 'The moment the game gave me SIG Sauer P226  and told to me to attack Takeda clan, I got a flashback to my history lesson about 16th century Japan.\n\nReally good learning resource for anyone interested in Japanese history or wanting to learn more about Yasuke. 10/10', 'For some reason the devs forgot to put the very important lore boss "Somali Streamer" into the game. This makes the game no longer historically accurate. It''s a common folktale in japan, the epic shark riding yasuke vs somali. I hope they fix it in the next patch.', 'Overwhelmingly Positive', 97.38, 2.27, 1.10);
INSERT INTO reviews VALUES (90924, 3274790, 115, 'With a name like Ultracop, you know it''s going to be great, and it is.  You get a hovercar, a mech, plenty of firepower, and your own two fists to deal out ludicrously violent justice.  It has an incredibly good AA12.  It has babes.  It has 4 different soundtracks.  It has gloriously over the top destruction for just about everything.  It has the most deep-fried audio you''ll ever hear.  It has bullet penetration(???!!!).  It has grinders you can throw things into.  It has squad commands.  It has', 'The game is pretty racist.', 'Very Positive', 89.57, 0.72, 0.73);
INSERT INTO reviews VALUES (90931, 3275010, 115, 'Rogue Loops immediately grabs your attention with its stunning art style. The hand-crafted environments and character designs feel alive, making every run visually exciting. The gameplay is smooth with plenty of strategic depth in how you combine skills and relics.Combat feels tight and satisfying.The sound design is just as impressive.', 'I don''t usually write reviews, but I will this time for hope of better balancing and future improvements in other projects.\n\nThe game is good, but I cannot recommend to people who don''t like to grind for hours with little improvements. The game itslef isn''t bad, but progression seems futile after a few runs because you can unlock only a few of the wishes at the same time wich isnt useful for every character. As of the time of this review only 1.9% of players unlock 10 scrolls wich is not a lot c', 'Very Positive', 80.00, 2.03, 13.15);
INSERT INTO reviews VALUES (91138, 3281130, 102, 'I just wanted to set the record straight, I saw a person say there is not wheel support for their Moza wheel. That is untrue. You have to go to the settings and bind the steering and the pedals manually. I just didn''t want anyone discouraged from buying it on that review. Navigate the menus with your keyboard to get to the settings and bind them. Works awesome just wish it had a FFB slider for strength. VR would be nice too but maybe we will get a mod for that.', 'I really like this game, and will continue to play it, but I cannot recommend this to anyone except those frothing at the mouth for sprint cars. It''s a good baseline for for future games to come in and improve, but this is just a lackluster entry in the dirt racing scene.\r\n\r\nIt feels like someone tried to copy the old Ratbag games and swapped the mechanical polish for visual.  Lacks detailed setups, lacks non-visual track evolution, the AI feels like a carbon copy of each other, and you cannot e', 'Very Positive', 92.16, 54.02, 11.07);
INSERT INTO reviews VALUES (91361, 3287520, 1139, 'Oh I have missed you, welcome back ninjas.\n\nAs for the game, so far so good, feels like ninja gaiden with better graphics, will update if I find any issues later.', 'Is it an improvement over Sigma 2? Yes definitely. Is it actually like the original 360 game? Still no, enemy counts are still drastically reduced and health/damage of enemies increased to compensate (but not as drastically as in sigma 2), not to mention plenty of features of the older versions are missing like score, coop, ninja race, tests of valor etc. Levels are also based on Sigma 2 which is evident from the checkpoint placement, but the statue bosses from that version are gone luckily.\n\nWh', 'Very Positive', 82.62, 13.22, 1.35);
INSERT INTO reviews VALUES (91398, 3288600, 161, 'I bought SKIBIDI GYATROOMS believing it would just be a random, kinda funny game. I did not expect it to have such a drastic impact on my life. I am now scared to go to the toilet because I fear it might be a skibidi toilet just waiting for me to let my guard down so it can mog me. This fear has led me to buy multiple plungers. There is at least one plunger in every room of my apartment. I take great care to ensure that I always have at least one plunger within arm’s reach. I even sleep with one', 'this game was just really bad and didnt work whatsoever. we had over a dozen issues in our 10 minutes.\r\nthis game ruined my life. i want to kill myself', 'Very Positive', 80.75, 1.98, 0.22);
INSERT INTO reviews VALUES (91473, 3290710, 1900, 'Ratshaker is a game about shaking the rat. When I started the game, I shook the rat. I was good at it. I kept shaking him, progressing further, shaking more, I felt proud of myself. I shook the rat. I was succeeding. I was gonna beat the game. I shook the rat. It was difficult, but I like a challenge. I shook the rat. I got an achievement, I shook the rat I learned more about myself. I shook the rat I was winning I shook the rat I was good I shook the rat I kept shaking the rat I shook the rat I', 'cant romance the rat', 'Overwhelmingly Positive', 95.42, 0.78, 2.82);
INSERT INTO reviews VALUES (91521, 3292260, 695, 'Goes from stunning to terrifying in a heart beat. Not scared of horror games so I thought this would be a breeze, am now scared of horror games.', 'I''m unsure if these are paid reviews or these people don''t play horror games or what but this game is horrid.', 'Mostly Positive', 78.85, 1.83, 1.28);
INSERT INTO reviews VALUES (91771, 3298170, 151, 'Comparing the two games to each other S.T.A.L.K.E.R. 2 and S.E.X. Z.O.N.E. ☢️. The clear winner was S.E.X. Z.O.N.E. ☢️', 'It s just cutscenes\nI was jerking off and then the camera switch to the dude,I came all over him', 'Mixed', 62.91, 3.50, 0.28);
INSERT INTO reviews VALUES (91784, 3298460, 141, 'Made my friend go absolutely insane until he started roaming the desert and found a cat', 'Nobody will read my review so I Will Eat 1 Chili pepper without milk For Every Like this gets.', 'Mixed', 49.65, 4.78, 3.17);
INSERT INTO reviews VALUES (92054, 3304770, 100, 'Visit the Saikey Studios website to get the steam patch.', 'You people are sick.', 'Mostly Positive', 78.00, 1.58, 0.85);
INSERT INTO reviews VALUES (92301, 3311740, 1546, 'people are reviewing this game who clearly did not read the text by the buttons. It is movement based. The cabins can be different. Yes, this is different from other anomaly games. It is unfortunate that it seems some people let this prevent them enjoy an otherwise clever and fun game. For the price, it is great. Just know that it isn''t a ''spot the difference'' based anomaly game.', 'I don''t want to sound too harsh, if you enjoy anomaly hunting games, you *might* enjoy this. The premise is not to find differences, but rather indications of a haunting. So you may notice something has changed, but if it''s not outright acting like a haunting (moving on its own, floating, possessed, etc.) then it is not something you should mark as dangerous. Don''t go into it thinking it''s simply a spot the difference type of anomaly hunting game.\n\nThere are mainly two issues with this game for ', 'Very Positive', 92.56, 0.55, 0.72);
INSERT INTO reviews VALUES (92379, 3314060, 1043, 'I bought the game, installed it, spent about 10 minutes making my sim look the way i wanted her too, bought a house, made breakfast, set the stove on fire, caught fire, then died. It took longer to make my sim than she lived, 10/10 it works great though.', 'Who the hell ports a 2000 game and doesn''t even scale the UI to modern resolutions????? It''s impossible to play like this.', 'Mixed', 65.10, 8.25, 0.22);
INSERT INTO reviews VALUES (92380, 3314070, 1829, 'Sul sul!\n\nThe game does not require EA Play and it doesn''t use Denuvo. Pressing Alt+Enter will enter windowed mode. There''s no windowed borderless built into the game but Borderless Gaming on Github lets you play the game in borderless.\n\nThe Denuvo notice was included on the 25th Birthday Bundle by mistake, and the EA Play requirement only applies to The Sims 4 since you get two Sims 4 kits for buying the bundle.\n\nAnyway. Time to rack up 1,000 hours.', 'cash grab, there is nothing "optimized" for the game\nLaunches in 640x480 resolution, full screen only (no windowed mode), refresh rate is locked\n\nIf you already have the Ultimate Collection just skip this one', 'Mixed', 63.31, 20.27, 0.10);
INSERT INTO reviews VALUES (92467, 3316470, 109, 'This game makes me feel nostalgic for something i havent experienced before. Love the atmosphere and sound design! Well worth the asking price. Also.. My cat puked all over the place earlier which made the whole experience very immersive smell wise. Great Job!', 'No invert Y option. Unplayable.', 'Very Positive', 88.07, 3.28, 0.08);
INSERT INTO reviews VALUES (92649, 3320800, 132, 'I found the duck of unlimited money.\n\nGame is fun, but somewhat unrealistic, as you can make a living from writing and selling books.', 'It''s a very cute game but right now it''s severly unfinished. I keep running into bugs (customers trapped in the shop after closing time and blocking space when I try to redecorate, books randomly disappearing or stuck on the floor and can''t be picked up). It''s badly impacting an already very empty game. I played the demo before buying the game and I''m sorry to say that there''s honestly so little content in the full game, it almost feels like a scam.\nI really love the idea of managing a little bo', 'Very Positive', 84.85, 4.43, 9.30);
INSERT INTO reviews VALUES (92783, 3324320, 114, 'Its Enter the Gungeon but slightly worse in a bunch of weird ways. Which is fine with me because Im starving for more Gungeon even if its a slightly off tune cover version.', 'After long awaiting finally Mori Calliope have her game... and it''s a cheap lazy reskin of Raspberry Mash of the same dev. You may say "Even Marine game Tresure Mountain was a reskin game"! Yes, but it was themed. Here? Some weapon are just reused from the other game, same goes at least for the majority of the enemy (and ok they may fit the location), some artifact are themed while other doesn''t ring a bell (maybe I was hoping for something like the one in Holocure).\nThe music is cool except the', 'Very Positive', 83.33, 0.97, 4.60);
INSERT INTO reviews VALUES (92904, 3327170, 174, 'Super addictive game with just the right amount of progression and satisfying gameplay to keep me going for new runs. The sounds and effects are juicy, the abilities nice and varied and you can take whatever upgrade path you like. The insults every time you die are, MOTIVATING, and they definitely keep you humble!\n\nI''ve been playing the demo for some time, and am super stoked to fail miserably at getting to that 5 minute mark now that the game has released - awesome game!', 'Extremely short. Was a decent first hour, glazed through the second hour trying not to fall asleep, third hour was a little more interesting as things opened up....and then it''s done. Felt more like a Game Jam demo. Not worth full price. Perhaps half, but that''s generous in my opinion.', 'Mostly Positive', 76.44, 4.67, 3.05);
INSERT INTO reviews VALUES (92956, 3328480, 314, 'A lot of negative reviews due to keyboard mapping not quite working right on launch, which is sad to see. Other then this (and some slippery DAS issues), this is a pretty great implementation of TGM in a modern format that you can help support the devs with. The OST is pretty good, and they''ve implemented TGM1 as TGM Controls-> Standard Mode. There''s even a practice mode implemented to test out some the incredibly hard gimmicks you''ll find that''s fairly robust.\n\nA bit puzzled at some of the revi', 'Unfortunately the controls are ridiculously slippery since DAS charge is actually retained when you turn around from DAS, and you also can''t rebind any keys, which makes the game feel like dick to play. pls fix :pleading:', 'Very Positive', 90.13, 7.68, 0.93);
INSERT INTO reviews VALUES (92970, 3328720, 103, 'Never have I been so confused in my life @~@', 'I''ll be honest the game is fun for the price point, but I do want to make it clear that nearly all the ''attacks/skills'' in the game are direct rips with minor visual effect changes to particles from another game called Dragon Nest. The current skills are nearly 100% taken from the warrior class within Dragon Nest. \n\nIf new and original content is added in the future, I may play more or recommend more highly. \nFor now it''s a decent time waster but nothing worth sinking many hours into!', 'Very Positive', 91.26, 0.37, 6.82);
INSERT INTO reviews VALUES (93039, 3330250, 490, 'Blue Turtle''s Youtube playlists got me through my PhD Thesis. So happy there is now a game-like interface I can use while working. Beautiful hand drawn landscapes coupled with relaxing tracks which are great as background music for all kinds of tasks. Immediately into the game I was very happy to see there are new playlists specially composed for the game as well as the Youtube playlists I''ve come to know. I am looking forward to using this during my day-to-day work.', '- Very few playlists. All in the same style, lacking in ambient music.\n- Music has far too much dynamic range to be suitable for background.\n- Timer does not go past two digits.\n- Pushing enter does not create a new entry in task list.\n- Alarm sounds are all too jarring, cannot be disabled, and the volume cannot be changed.\n- The notes/journal stuff is kinda pointless - because they don''t have enough features to compete with trello or a calendar, can only be used while running the game, and ther', 'Overwhelmingly Positive', 98.16, 27.88, 0.33);
INSERT INTO reviews VALUES (93228, 3334550, 203, 'This game was unsettling....as what Chilia''s Art is known for, this game sadly was much shorter, still a decent play for what it offered, a few spooks here & there. Definitely not their best game compared to some of the previous but they are getting much better with the visuals and audio work. It was impressive! \n\nScore 7.5/10', 'I can''t overlook how poorly this game is optimized. Maybe you should take a little longer between game releases to make sure your game is just a little optimized. But nah, you could just make sure you shove all the upscaling crap in there to mask poor optimization, and everyone will look past it because you''re Chilla''s Art.\n\n*Edit* I did play this game, and I did enjoy it. I thought it was quite scary, unfortunately, I wouldn''t attempt to play this game with any GPU less powerful than a 3090, an', 'Mostly Positive', 78.82, 2.13, 2.62);
INSERT INTO reviews VALUES (93408, 3339420, 493, 'I bought this just because I could flabbergast my friends a little with the feeds like "Frankeindew now owns "your wife.", "Frankeindew plays "your wife" for the first time." and "Frankeindew is now playing "your wife." even though most of them didn''t even have one in the first place.\n\nWhat matters isn''t the actual content but the feeds.', 'i cant beat wife', 'Overwhelmingly Positive', 97.97, 30.08, 0.53);
INSERT INTO reviews VALUES (93422, 3339780, 524, 'Come for roguelike, stay for emotional support sword friend.', 'Authentic Windows 98 experience with constant freezes and crashes which make you lose your progress.\n\nPass on this one and wait for Desktop Survivors XP.', 'Very Positive', 94.47, 49.08, 19.67);
INSERT INTO reviews VALUES (93455, 3340810, 126, 'A worthy continuation of the series. Very well-balanced resource-wise, though money may feel a little tight here and there. Don''t rush buying everything you can, not everything is needed immediately.\r\n\r\nAt one point it may seem that there''s no continuation possible but you need to just keep talking to a person with a speech bubble.', 'It really hurts to give a thumbs down. I played the whole series, starting with Hero of the Kingdom 1, and really loved the chilled and relaxed gameplay. This part (the 6th) is not bad - but just not good enough. Not good enough for such a great "franchise" like Hero of the Kingdom.\n\nSomehow, the series has the tendency that the grind gets more and more annoying from part to part. The first games, there was simply no grind, you could play the game basically just by doing your quests, harvesting,', 'Very Positive', 90.48, 5.55, 4.70);
INSERT INTO reviews VALUES (94174, 3359320, 1100, '3.4 hours and still haven''t escaped yet..., I take back making fun of youtubers who couldn''t escape either. This game is hard even on easy mode...', 'I dont think others should play this because the parents are abuseive', 'Very Positive', 91.91, 6.37, 8.63);
INSERT INTO reviews VALUES (94267, 3361470, 4543, 'I enjoyed the scaling, not every incremental has to be a multi-month slog. it was 3 dollars and I had a few hours of fun with it.', 'The exact same thing you do at the start of the game is what you''ll be doing 2-3 hours later when you beat it.  No difference at all.  This is perhaps the most repetitive game since Mavis Beacon Teaches Typing the original, released in 1987.  So, bravo on that, I guess.\r\n\r\nSave your money, save your time, save your wrist and fingers.\r\n\r\n1/5  It had some neat ideas, but it never once tried to explore them at all.', 'Overwhelmingly Positive', 98.00, 4.52, 3.97);
INSERT INTO reviews VALUES (94343, 3363390, 104, 'If a movie with a similar name was also similar in plot to this game, it would be much more interesting to watch.\n', 'Dude, not to break your confidence, but I could have finished the game in ten minutes because three minigames were holding me back, so I bought this game and I got a game that had a very different story and all the same choices up front, and then a branching point at the end? I originally thought he was something like Stranded in Space\nThe same thing turned out to be a real disappointment. Four girls, ten minutes of drama and three minigames of meaningless choices and that''s the end\n\n伙计不是我打击你的自信', 'Mostly Positive', 73.08, 3.37, 0.35);
INSERT INTO reviews VALUES (94643, 3371240, 1492, 'Genuinely the first game where women run around gutting each-other with nothing but pasties on that I can safely say most people genuinely play for the gameplay.', 'Wanted a boomer shooter, immediately started almost naked, saw my portrait was mostly naked, looked down and saw that half my screen was breasts and her splaying out her thighs. This is pathetic, why cant indie devs either make a porn game, or just have it be a normal game instead of constantly flaunting sexuality to distract from the gameplay', 'Overwhelmingly Positive', 96.25, 6.07, 0.17);
INSERT INTO reviews VALUES (94667, 3371930, 105, 'Hoping this game gets more people from Australian time zones playing as no one has been on so far when I tried it. Looks like fun and similar to another game I already play. Probably a good game for people with huge friends lists that can invite people to play.', 'I really want to like this game\n\nBut I don''t\n\n\nP.S: Most positive reviews seem to be fake 💀', 'Overwhelmingly Positive', 99.05, 0.85, 1.07);
INSERT INTO reviews VALUES (94728, 3373660, 2076, 'it''s like fear and hunger, except it''s fun and not a chore to play', 'Gave this game a shot wanted to like it, but no monster HP bars, Randomness of monster encounters + not being able to escape is RNG and losing progress when you die to it just sucks ass. Maybe if they change it later ill pick it back up. Concept was pretty cool and liked the older style RPG UI.', 'Overwhelmingly Positive', 98.99, 11.83, 1.75);
INSERT INTO reviews VALUES (94804, 3375580, 127, 'Stop playing NSFW games! Leave your complexes and shyness behind!  There are so many dead girls in the world who wouldn''t mind spending time with you!', 'If I were a zombie, I would make love to every man in sight.\n\nThe game is broken. You can only complete the first two tasks.  It''s a terrible game, created by AI. There''s nothing interesting about it.  The positive reviews seem to have been paid for.', 'Mostly Positive', 74.02, 1.07, 0.80);
INSERT INTO reviews VALUES (94833, 3376250, 143, 'Fun game but wouldn''t recommend for public lobbies because you won''t find one for a long time.\n\nIt''s only worth buying to play it with friends.', 'this game is bad', 'Very Positive', 90.21, 0.58, 2.15);
INSERT INTO reviews VALUES (94867, 3376990, 1218, 'I''ve bought the game and 100%''d it in 3 hours, it has way more potential, you could add more characters, adding multiplayer where you could fight other players and in the story mode you go home after vacation, you jump in time to the next summer vacation and meet new people, find new bugs and so on.\n\n Over all i enjoyed the game very much even if it was pretty short, very cozy game, i enjoyed the art style a lot, hope the best from this game.', 'The male developer should take a break from plastering his own face (and ego) over the game. I’m here for the gameplay, not a one-man vanity project. \nThe game itself is actually a lot of fun: cute style, chill vibes, and the achievements are super easy to snag. \nWorth a play if you can handle a few too many dev cameos along the way.', 'Overwhelmingly Positive', 99.84, 3.25, 4.62);
INSERT INTO reviews VALUES (94878, 3377310, 155, 'It was difficult, but I was able to pass with one hand :D', 'EXTREMELY mediocre. Slow gameplay, terrible sex scenes, and horrible "voice-acting" (it is just monotone ai). It is just bad jump scares with ear blasting audio. It isn''t worth it aside from the easy achievements.', 'Mostly Positive', 79.35, 2.38, 1.07);
INSERT INTO reviews VALUES (94958, 3379650, 129, 'The game quality is still lame - the developers should still polish a lot of things in this game for a better game experience. But as an experience, it''s fun to mix such set-ups in one whole, which gives an ambiguous feeling of the game.', 'Полная х*й*я, не покупайте ни в коем случае.', 'Very Positive', 91.47, 3.23, 0.57);
INSERT INTO reviews VALUES (95206, 3385670, 171, 'I remember my Mom tirelessly waited in lines to get me a Nintendo Wii and one of the final games I got on it was World of Goo. I got about halfway through the game before I found out my cousin sold my Wii for substances LOL \n\nWholesome moment seeing World of Goo 2 on my Steam store!\nCant wait to play this later with my mom :)', 'It''s okay, even though it has too many recycled levels. What made me refund was that the game doesn''t even start without an active internet connection. It simply refuses to launch. You''re better off buying the DRM-free version somewhere else (not on Steam).', 'Very Positive', 88.89, 14.37, 1.17);
INSERT INTO reviews VALUES (95413, 3391450, 263, 'This is a very fun game! Almost more fun than the first GORN! Even the slicing mechanics are more realistic! \n\nPs: The game has more humor :)', 'This game wasn''t terrible it was just really disappointing the hitboxes and physics of this game where nowhere near as good as the first gorn if you disagree, replay the first game... also the hand-to-hand combat felt terrible', 'Very Positive', 86.31, 5.13, 5.78);
INSERT INTO reviews VALUES (95454, 3392420, 132, 'Game so good I bought it twice, once for me and once for my kiddo so he stops trying to take my PC over. Been playing since the bata and its shocking how far the game has come so fast. LOVE LOVE LOVE GeckoShop', 'Game has awful pacing, very buggy, but has a unique artstyle instead of the average asset flip I''m 5 hours in and the most recent thing I''ve unlocked is a lab where I can gamble for a 33% (if I remember properly) chance to upgrade it to a higher tier. 5 geckos for 1 gecko. The gecko will either transform to a higher tier or you''ll get one of the same tier. All I can do other than that is sell 2 types of gecko profits (basically just reskins,) I can sell sand or red sand (basically just reskins o', 'Very Positive', 94.70, 5.42, 4.95);
INSERT INTO reviews VALUES (95793, 3399950, 369, 'A game where I can invite my friend’s mom? Finally, a true family drama simulator.\n\nThe multiplayer experience is something else. The more friends you have, the more moms you can invite. At some point, it stops feeling like a game and starts resembling an unexpected family gathering. The achievement system is also… unique. Spending "30 minutes with a different mom" doesn’t sound like a challenge—it sounds like a headline that could ruin your reputation.\n\nThe gameplay is disturbingly realistic. I', 'Not accurate, needs more violence and slapping from the mother', 'Very Positive', 92.95, 5.97, 0.08);
INSERT INTO reviews VALUES (95796, 3400000, 927, 'So far I''m enjoying it, the negative reviews seem to be about co-op/mp, but im not bothered about multiplayer so for me the game''s ok.', 'Game has potential but the multiplayer / co-op experience is horrible. \n\nOnly the host can progress the quest as well as do certain actions like owning vehicles and ships. Was met with a "only the host can do this action" a few times.', 'Mostly Positive', 74.97, 59.08, 1.30);
INSERT INTO reviews VALUES (95814, 3400930, 953, 'My client got sentenced to death for sinking the titanic because he broke the drill used to unclog toilets. The prosecution had a flawless case. Evidence, a good witness and bias from the judge. I had to fabricate all my evidence on the spot, and even had to call on santa as a witness. According to santa 10% of the worlds population is called nightcat. But the judge didn''t believe it and sentenced santa to death for perjury. When all was said and done, I obviously had to insult the judge, but th', 'Really enjoyed the demo, but the full game isn''t the same. May of the features from the demo aren''t in the full game, like the rule book (which has an achievement associated with opening the rule book, but it''s not possible to do so). You aren''t able to change evidence cards like in the demo. There''s no whiteboard displaying evidence cards, you have to press tab to see the cards. It''s cluttery and not as straightforward. My friends and I had a blast with the demo but the full game is poorly thro', 'Very Positive', 91.92, 1.18, 0.57);
INSERT INTO reviews VALUES (95820, 3401490, 289, 'I played the demo more than I expected I would and I instantly bought the game upon release.\n\nThis game scratches the itch Zachtronics used to. Each puzzle has not just a solution, but solutions. Every solve just opens up and opportunity to optimize and optimize. It''s addicting and quickly ate up hours of my life.', 'Lua sucks.', 'Overwhelmingly Positive', 97.58, 40.42, 2.07);
INSERT INTO reviews VALUES (95838, 3404470, 127, 'I was going to pre-purhcase Doom: The Dark Ages but then I saw this game and changed my mind.\n\nNow I''m 5 dollars short, but I have this great game where I am helping animals relax and enjoy a nice bath.', 'Change the fucking name back what''s wrong with yall.', 'Overwhelmingly Positive', 96.85, 239.72, 23.82);
INSERT INTO reviews VALUES (95858, 3408110, 123, 'Love the game. However, it would be nice to have a storage room of some type such as a warehouse for supplies. I have boxes in corners....\r\nI understand that this could be played with multiple people, but the ability to hire a stocker would be amazing too :)', 'It''s buggy as hell and barely anything to do. Even this low asking price is too much imo.', 'Mostly Positive', 76.42, 19.28, 4.03);
INSERT INTO reviews VALUES (95870, 3410310, 193, 'Only died 109 times trying to walk down a short street. \nBlown up, impaled, crushed, run over and every other kind of way to die.\nThat opening chime is going to haunt my dreams.  10/10.', 'Only play this if you don''t want to have fun. Also many hit boxes of falling objects are way to big and often the character stupidly stands still before imminent danger, not allowing you to move when one could have easily gotten away from the gas pipe for example or simply walk back when the street lights fall.', 'Very Positive', 88.60, 1.68, 0.20);
INSERT INTO reviews VALUES (95915, 3416070, 1315, 'This is the perfect game to have running in the corner while you''re doing the daily grind at work. Never so distracting that you can''t work a spreadsheet, but entertaining enough to spend 5 minutes redecorating your island when you don''t want to respond to Rebecca in Accounting.', 'I might have bought this game too fast hahaha. Don''t get me wrong, is not a scam, but I was hoping for the little frog to do more stuff, like having lunch, drinking tea or something else. Instead he just cut grass and sleeps. A bit boring honestly: I know it is not really a "game" but would have loved to catch the frog doing something else instead of just the two above things', 'Overwhelmingly Positive', 96.88, 341.30, 7.65);
INSERT INTO reviews VALUES (95953, 3421300, 249, 'It''s a fun incremental game, you run around uncovering the ground and collecting resources. It''s got a big upgrade tree that''s nice to see expand as your dog gets progressively more powerful.\n\nBUT, I''m only at Prestige 5 (1.5 hours in) and the performance has completely wild slowdowns and performance drops. It''s a pixel art game, so it''s really surprising to see such bad lag. I''m using a 4090 and 7800X3D, so it''s definitely a game optimization issue. There is a ''Low FPS'' option in the menu that ', 'The game is certainly fun, but the performance makes it unplayable. Takes all the enjoyment out of the game. I''ll revisit this review in a month after the game is, hopefully, optimized.', 'Very Positive', 83.94, 3.77, 8.93);
INSERT INTO reviews VALUES (96016, 3431040, 968, 'Okay so I''ll be the first to say it. Not only is this game easier and fun with steam it also works on the steam deck if your ever interested', 'I''m personally gonna leave this on Do Not Recommend until they hopefully add things that were in the Itch.io version.\n\nMissing the descriptions to each person really took a lot away from this. I like some of the new additions and everything and really enjoy this game but taking away one of the basic features from the Itch.io version really made this seem rushed and empty', 'Very Positive', 85.74, 8.48, 1.45);
INSERT INTO reviews VALUES (96050, 3435260, 109, 'Full disclosure, I made the pixel art in this game, but genuinely, even if I hadn''t contributed to it, I would still wholeheartedly recommend this game. The devs are just a small team of two, but they''re dedicated to supporting, and adding so many forthcoming features to the game, and for the price, it''s an absolute steal.\n \nIt''s my exact kind of game, love the incremental unlocking of cool relics and dice, and I''m genuinely excited for all the cool new things to come. With any luck, I''ll get to', 'There are a few bugs, the sort of thing you''d expect from an early access game, and nothing to care too much about. And some odd scoring choices too, which limits strategy, and is a little bit more concerning. But ultimately, the biggest risk with a game relying so heavily on luck is with balance. Item and dice choices are supposed to mitigate the luck factor, which is something done in other games of the genre, but as of yet, the balance is not right. The game doesn''t feel difficult or challeng', 'Very Positive', 92.66, 11.60, 0.85);
INSERT INTO reviews VALUES (96074, 3438800, 100, 'First review of doodle empires (i think) amazing game i played back when it was on itch.io, but i did expierence some lag problems so idk, other then that i love it, keep it up cant wait for the updates', 'Great concept but I have trouble saving. It either takes a long time to save or the game crashes and I lose a lot of progress. I have tried to change the frame rate to 30fps but still have trouble saving and loading games. Hopefully this is fixed soon.', 'Very Positive', 94.00, 3.30, 16.78);
INSERT INTO reviews VALUES (96160, 3444480, 282, 'Fun to play and balanced pretty well. Only 1 glitch where my power went off and the save file changed from hard to easy. Can finish the game in 2 to 3 hours and there''s permadeath after which will take a while imo. I think what would make the game great is community workshop content where you can make enemies and waves and have different upgrades enabled/disabled', 'Camera sway does not belong in a bullet hell. Also, if you use your white diamond resources incorrectly, you have to restart the game or else bang your head against a wall fighting a boss for resources you can''t even use because you already filled out the skill tree.', 'Very Positive', 87.94, 3.85, 2.80);
INSERT INTO reviews VALUES (96211, 3445580, 183, 'I thought it would be an easy and very entertaining game, but my surprise was when I discovered that I am just an Ambimbecile 10/10!!! :D', 'This game is extremely frustrating from the get-go, be aware that you''ll have to constantly repeat over and over each level until you almost master them, as the timer is quite tight.\n\nRather than developing ambidexterity, I''d say it''s about memorizing the order of actions to perform with each hand.', 'Overwhelmingly Positive', 98.91, 27.85, 0.70);
INSERT INTO reviews VALUES (96239, 3446200, 119, 'i have a massive fear of the ocean but still decided to play this game for my YouTube channel. when i tell you this was the most terrifying gaming experience I''ve had, i MEAN it. \n\nMAJOR props to the developer. the ending sequence almost has me in tears because of how scary it was\n\n10 \\ 10', 'i dont like this game. before i played this game i was enjoying a nice clean pair of pants..... now... my room is quite litterally a art meuseum exhibit of a singular color... brown.... this game has given me depression. in the way. the poop has completely filled my pants. bad game. water. bad. make a version where there is no water. and instead. its.. just that.  or add a dlc to remove water. i am now scared of even my bathroom sink. i will never pee again', 'Overwhelmingly Positive', 95.80, 1.65, 1.03);
INSERT INTO reviews VALUES (96296, 3447410, 462, 'As I''ve played this game for the first time, it has opened my mind, years of constant people pleasing, and such has caused me to be a big sad depressed son of a bitch.\nBut my god, the tears that flew down my face as I realised these words were uttered not to some big hero or king, but to me, some lowlife with barely any self respect.\n\nThank you, for the creators of this game, and thank you for who ever is in the air has blessed me by making me come across this game.\n\nThank you, and thank the cre', 'I felt compelled to leave this review because, as of now, the game has 100% positive feedback.\n\nThe credits say that this isn''t a game, it''s an "experience".  That should tell you most of what you need to know about the mindset of the developers.\n\nThis is a generic online personality test except that it costs $5.', 'Overwhelmingly Positive', 98.27, 0.63, 0.33);
INSERT INTO reviews VALUES (96313, 3447690, 112, 'For a small price you get a relaxing digging game. \n\nIt''s especially fun to find all the random things further down, like a coffin, lol\n\nClearly recommended.', 'i wanted to like this game but if theres a giant trump coin labeled #trump with the words fight fight fight on it in the game im good... hard pass i beat it in an hour and 25 minutes solo anyway.', 'Mixed', 56.25, 4.58, 1.53);
INSERT INTO reviews VALUES (96543, 3453600, 266, 'This game is worth absolutely every penny!\n\nAn enjoyable and relaxing toy car salesman simulator. Here you can also collect models of toy cars, sometimes there are quite rare and expensive. The game both relaxes and awakens a sense of excitement, when you open each box and in anticipation of what will fall out. It''s like opening a lootbox, but the money is virtual, not real.\n\nI wish the game further development and release from early access.', 'just getting boring of the same products and its like a hamster in a wheel your going round in circles doing the same thing over and over none stop they need to update game with more items i am disappointed', 'Very Positive', 93.98, 6.58, 80.10);
INSERT INTO reviews VALUES (96583, 3454590, 759, 'Let any fish who meets my gaze learn the true meaning of fear; for I am the harbinger of death. The bane of creatures sub-aqueous, my rod is true and unwavering as I cast into the aquatic abyss. A man, scorned by this uncaring Earth, finds solace in the sea. My only friend, the worm upon my hook. Wriggling, writhing, struggling to surmount the mortal pointlessness that permeates this barren world. I am alone. I am empty. And yet, I fish.', 'Gotta say I love the idea of the game but I ultimately found it really unexciting and tedious. You have to make sure your bait is stocked every 10-15 minutes or so by buying more, which is one click, and selling fish to free up inventory space. This makes it so you can''t idle for a few hours and come back to big gains and do a bunch of things at once. Instead, you have watch painfully slowly as your cash flow increments 10% at a time towards your goal. The time between having to restock/sell doe', 'Overwhelmingly Positive', 97.36, 22.37, 18.98);
INSERT INTO reviews VALUES (96839, 3461920, 219, 'thought i was just gonna chill n serve boba. instead i blinked twice, lost 3 years of eyesight, screamed 3 times, bonded w pixel customers, n now i''m emotionally unemployed cuz the game ended too fast. best 40 mins of my life tbh. would open my doomed boba shop again without thinking', 'The demo was awesome. i couldn''t wait to play the full game but now that it''s out i don''t know why it won''t open. i spent 5 bucks on a game that doesn''t even open and i really wanted to play it, now i''m going to ask for a refund.', 'Overwhelmingly Positive', 96.80, 1.28, 0.10);
INSERT INTO reviews VALUES (97021, 3468640, 132, 'I will start by saying that games that release with game breaking bugs should have an extended refund period past the 2 hours mark. Big Ants (and many others) are releasing games at full price with game breaking bugs and then fixing them later. Scummy practice when the developers know that the bugs are there as people are finding them after 5min-10min of play.\n\nNow to the game. I really like it. Its 100% step up from AFL 23 but is it worth $100? No definitely not but that answer maybe different ', 'Biggest copy and paste job ive ever seen. Game play is legit the exact same they''ve just added some new cut scenes lol. 1 new addition to gameplay i noticed is there new handball animation when you get tackled its legitimately a illegal handball and happens nearly every time you handball out of a tackle the devs probably dont even know what afl is. This should be considered fraud charging $100 for the exact same game with 1 or 2 new things you will never do in game is insane. Dont give your mone', 'Mixed', 53.79, 19.58, 7.90);
INSERT INTO reviews VALUES (97392, 3487060, 139, 'I genuinely am confused as to why there''s so many negative reviews on an early access game mere hours into a release, from players who seemingly have only just completed the tutorial.\n\nYoutuber''s Life 3 continues to deliver on the same gameplay that it always has done, a life simulation game where you create videos, livestreams and photo content in order to grow your channel, except this time, it is online. Your channel is ranked with other players, who you will see making their own posts and vi', 'this game is not what i expected i am sad that they made it real-time day so you actually have to wait a real time day to get an event that u want on calendar and the card battle is really funky and is slow. The explanations at the start are shit. the editing prose''s is bad and not good enough explained, i do not recomend this game i do however recommend the first 2 games they''re good. And i have refunded the game bc this was not worth my time', 'Mixed', 46.04, 24.58, 1.60);
INSERT INTO reviews VALUES (97400, 3489670, 187, 'It''s clearly obvious when you see a game that was made with love and passion. Everything is like the first game, but BETTER!\nAbsolute cinema. 🙌', 'The game''s fun for what it is, but there''s a bug that killed my enjoyment of the game. I completed Act 14 and decided to close the game to take a break. I open the game about 5 minutes later and it erased all of my data and I''d have to start over from the beginning. I''m not THAT upset about it because the game''s pretty cheap, but I hope that the developer(s) fix the bug soon.', 'Very Positive', 94.12, 2.48, 0.77);
INSERT INTO reviews VALUES (97401, 3489700, 4579, 'You bought this game because you are cripplingly addicted to Souls-like games.\nI bought this game because I am horny.\nWe are not the same.', 'The opening cinematic is the most epic sequence you''ll see. And then you start playing and meet the combat system. It''s miserable. Movement with mouse and keyboard has a stutter to it. Dodge and run are on the same input and the delay from dodge to run makes running awkward. Attacking, blocking and dodging animations all feel too long. Animation locking punishes any aggression and makes you feel like you have to play a turn based game. Even a single light attack can lock you into animation long ', 'Overwhelmingly Positive', 97.44, 2.45, 1.83);
INSERT INTO reviews VALUES (97620, 3508770, 107, '-Isn''t this a russian game?\n\n-Yes, russian dev. So keep in mind that each game copy bought is one more rocket that russia will launch toward ukraine.\n\n10 / 10Z \nABSOLUTE ZINEMA', 'It''s Haydee 2 copied and pasted with stuff that was in 1 cut in 2 added in 3, the map is new but everything else is just Haydee 2 to the point its mods are ported over and just as the game came out not even a few hours passed and the mods are ported stright over. you won''t be getting anything new and just something that easily could of been a update or a mod, which haydee 2 had a mod to implement the cut stuff that was in 1 and not in 2 making this even less of a change.\n\nI''m not against the gam', 'Very Positive', 82.24, 1.40, 0.35);
INSERT INTO reviews VALUES (98404, 3533100, 168, 'This game is the type of games I like to play, especially with friends. I just started playing yesterday, so far its enjoyable, but it gets nauseating when I play longer. I had the same effect when I played Fast food simulator. When i removed the motion blur in that game, the motion sickness never came back. Is it possible for this game to remove motion blur as well, or something else to fix motion sickness players? I look forward to playing this game.', 'Don''t get me wrong, Brilliant game. But it gets boring quick. I have 2.3 hours so i can''t refund it... It was fun the first day but now i''m bored. My friend who bought it just to play with us also wants a refund but cannot. Its good but very boring after a day.', 'Very Positive', 89.29, 0.57, 2.30);
INSERT INTO reviews VALUES (98613, 3539440, 508, 'On the off chance that Alexandra Herout sees this...\n\nThank you for making such a wonderful game.\n\nThat is all.', 'I kind of enjoyed it, but the aesthetic definitely carried here. \nThe gun play felt terrible, no impact when enemies are hit, shooting feels very bad and movement could also be a little better. Wonderful world, but I didn''t really like the interior segments. \nAnother general thing would be how low contrast everything is, it''s probably intentional but doesn''t feel great, when inside.', 'Overwhelmingly Positive', 98.23, 1.45, 2.20);
INSERT INTO reviews VALUES (98665, 3541130, 139, 'It was so hard to aim for the Chalice with cascades of tears pouring down my face - but I did it.\nThis game is truly a gem. I can’t fully express how much I loved it. It''s profoundly thought-provoking, peeling away every layer you put on yourself. It completely disarms you, undress you. Mystically touching, you will find a reflection of yourself in at least one ‘character’. The most cathartic moment for me was the unease I felt as the braid slid into the wall, and I waited - just for a breath - ', 'I wish Steam would have a 10/10 rating system, as I would have voted a 6/10.\nI do love the concept and it''s attempt to raise some pseudophilosophical questions, with an easy to play, simple gameplay and aesthetics.\n  What put me off, the reason for my vote, was the themes and language used. The tiny snippets that made me download the game turned out to be only the skeleton of what it could have been a pretty interesting and thought-provoking game, but instead it chose a vocabulary and some theme', 'Very Positive', 94.96, 1.15, 1.48);
INSERT INTO reviews VALUES (99659, 3570430, 146, 'The weakness of most incremental games is how quickly they become repetitive, there''s only so long you can watch numbers go up before they lose all their meaning. Snakecremental avoids this by grounding the upgrades in the gameplay of Snake. You can have all the upgrades in the game, but you ultimately still need to be good at Snake.\r\n\r\nThe upgrades also feel impactful, which is essential for a game like this. Unlocking red health pips and blue armor pips genuinely changes the way you approach t', 'lost complete interest in this game after finding out you have to grind the entire game again to get all the achievements if you don''t pick upgrades in the correct order the first time. game was ok, just becomes really repetitive and slow around the 80% mark', 'Very Positive', 91.78, 4.12, 4.28);
INSERT INTO reviews VALUES (99681, 3571560, 100, 'The Industrial Revolution and its consequences have been a disaster for the human race', 'As a game, it''s bad 4/10.\nAs porn, it''s very bad 2/10 (there''s almost non of it)\nAs a porn game, it''s bad because it all disjointed mess and an asset flip.\nDon''t buy it.', 'Mostly Positive', 75.00, 2.10, 0.78);
INSERT INTO reviews VALUES (100437, 3593780, 310, 'I love the part where I cut down trees\r\n\r\nI don''t love the part where I have to find anything specific in the game, please let me use some of my in game tree money to buy a useful in game map that I can access anywhere.', 'Game is really fun at the core, but the upgrades are in a very rough state, and the game is very tedious to navigate. Played through most of the game, got all the upgrades, then the game turned a very dark red and became an eye strain simulator.\r\n\r\nI''m optimistic that the game can be developed further into a good state, as I have seen the developer interacting with players and discussing potential changes. However, I do also have some gripes about selling the game as a finished product, when it ', 'Very Positive', 82.26, 5.95, 4.12);
INSERT INTO reviews VALUES (100590, 3598130, 255, 'I decided to refund my purchase of Assassin''s Creed Shadows and buy Big Rigs: Over the Road Racing instead.\n\nI have many regrets in life but at least this game tells me I are a winner.', 'I could just sit here and give you my obligatory ironic praise review of the legendary Big Rigs, but be warned that this is an incredibly sketchy paid release of a notoriously unplayable game, hastily hacked together with the only real addition being those profile showcase letter slop achievements. No thanks!', 'Mostly Positive', 75.69, 0.17, 0.67);
INSERT INTO reviews VALUES (101435, 3624190, 131, 'May Thy Knife Chip and Shatter\r\n\r\nDune Awakening''s beta is a tantalizing taste of what''s to come. The vast, arid landscapes stretch out before you like an endless canvas of intrigue and danger. Survival''s the name of the game, as you navigate treacherous sandworms, rival factions, and the ever-watchful eye of the Bene Gesserit. The gameplay''s still rough around the edges, but the potential''s undeniable. If you''re a fan of the Dune universe or just love a good survival game, this beta''s worth div', 'Not worth it starting zones are so over camped  cants get nothing done...', 'Very Positive', 90.84, 43.83, 2.42);
INSERT INTO reviews VALUES (101466, 3625270, 169, 'I originally started designing mods for Desktop Mate, but when support was dropped, I lost interest. There wasn’t much point continuing with a downgraded version that would never get updates. Then I came across this new tool on Reddit. It might cost a few dollars, but the creative freedom it offers makes it well worth it. Official mod support is essential these days, as it keeps the software alive through community involvement. I have a lot of respect for the people behind this project and how a', 'null', 'Overwhelmingly Positive', 98.82, 19.50, 16.37);
INSERT INTO reviews VALUES (101700, 3632530, 106, 'Intense gameplay, deep atmosphere and unique style. Passing the levels is difficult, but every victorious battle brings real satisfaction. A great choice for fans of roguelike and dark subjects!', 'While the description and even the pictures and video show a game that could be fun and have fun adult content, I can say without a doubt it is not fun and the content is very mid at best.  The about section of this game is not wrong there are 12 active and 12 passive abilities which evolve into 12 more powerful, I think, abilities.  I only played for 30 minutes and beat the first stage first try without even getting to evolve any of my skills.   Even after wining I saw no adult content had enou', 'Overwhelmingly Positive', 96.23, 0.77, 0.47);
INSERT INTO reviews VALUES (102738, 3667230, 214, 'This game is amazingly well made. I would recommend it to EVERYONE. Just for 3 euros it left me speechless due to the endings being so well made. You shall try this out cuz peak is awaiting for you', 'The game doesn''t launch because my graphics card doesn''t run on somekind of Vulkan version driver. I don''t like that this game only runs on a certain computer. FIX THIS!!!', 'Overwhelmingly Positive', 98.13, 1.03, 0.37);
